INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Перебить все ингредиенты в блендере.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Добавить соль, специи, сливочное масло.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Повторить взбивание.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1683,'Паштет поставить в холод.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Печень вынуть из холодильника, дать полежать при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Удалить вены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Субпродукт вымыть холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Печень обсушить, посыпать солью, перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Отправить в форму для запекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Залить смесью хереса и коньяка. Положить гнет.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Поставить продукты на сутки в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Запекать в течение сорока или сорока пяти минут, температура – сто градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Форму поставить на противень с водой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1684,'Паштет остудить, поставить еще на сутки в холодильник.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Свиное сало нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Выложить на сковороду, жарить до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Добавить чеснок, репчатый лук, морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Все вместе жарить до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Печень очистить от пленок, нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Добавить на сковороду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Обжарить на сале до готовности, но не допускать зарумянивания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Массу остудить, пропустить через мясорубку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Смесь вернуть на сковороду, влить молоко, немного коньяка, соль, специи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Все вместе потомить на тихом огне шесть или семь минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Массу остудить, перебить блендером.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1685,'Паштет довести до кипения, охладить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Почки, печень и сердце промыть очень холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Отварить в подсоленной воде и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Добавить специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Растопить сливочный жир.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Чернослив промыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Если продукт слишком сухой – подержать в теплой воде пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Сухофрукты и субпродукты пропустить через мясорубку отдельно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Всыпать соль, приправы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1686,'Паштет охладить, дать загустеть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Вытопить гусиный жир, обжарить нарезанный лук и печень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Продукты посолить, посыпать специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Добавить кусочки гусиного мяса через шесть или семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Все вместе готовить около двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Массу можно досолить по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Ингредиенты остудить, добавить нарезанный чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1687,'Продукты перебить блендером до полной готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1688,'Промыть помидоры под проточной водой. Нарезать кусочками среднего размера. Для салата лучше выбирать сорта помидор с розовой мясистой мякотью и кисло-сладким вкусом. Салатные листья помыть и обсушить полотенцем. Нарвать салат, руками складывая несколько листов вместе. Так салат будет более сочным, нежели тот, который разрезан ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1688,'Твердый сыр зрелых сортов натереть на терке с крупной решеткой. Куриную грудку разделать, отделив ненужную шкуру и киль, так, чтобы осталось одно филе. Промыть и обсушить. Разрезать мясо на четыре крупных куска, и прожарить на слегка смазанной оливковом масле сковороде-гриль, с решетчатой поверхностью. Первые несколько минут, жарить на сильном огне, чтобы мясо запечаталось и приобрело золотистую корочку, после убавить огонь и продолжить готовить мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1688,'Готовое мясо остудить и разрезать на брусочки поперек волокон или по диагонали. Салат подавать порционно, выкладывая листья салата, поверх нарезанные помидоры, далее кусочки курицы. Заправить все майонезом, присыпать сыром и сухариками. Кстати, если сухарики заменить гренкам, вкус салата «Весенний» будет более органичным и богатым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Печень промыть, обсушить, удалить пленки, протоки, нарезать кусочками. Посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Нарезать репчатый лук кубиками, спассеровать до прозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Добавить тертую морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Обжарить в течение пяти минут на другой сковороде печень, оставить под крышкой на пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Субпродукты остудить, перемолоть блендером вместе с овощами, затем взбить с мягким маслом и специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1689,'Переложить массу в керамический горшочек и поставить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Промыть печень, обсушить, нарезать любыми кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Репчатый лук и морковь измельчить, обжарить на растительном масле в режиме «Жарка» до получения золотого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Добавить субпродукт, влить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Выставить режим «Выпечка» на двадцать пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'При готовности смесь посолить и поперчить, всыпать другие специи по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Превратить продукты в пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Выложить мягкое сливочное масло, перебить массу еще раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1690,'Выложить в креманки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'Промыть и очистить печень от прожилок, сосудов. Нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'Измельчить морковь и репчатый лук, обжарить со сливочным маслом на сковороде, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'Отдельно, также на сливочном масле, обжарить печень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'Грибы нарезать пластинками, обжарить в масле, оставшемся от приготовления печени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'Взбить продукты в однородную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1691,'В чашу комбайна добавить сливки и еще немного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1692,'Соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1692,'Цыпленка нарезаем на кусочки. Добавляем соль, черный молотый перец и аджику.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1692,'Обжариваем цыпленка на сливочном масле по 10 минут с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1692,'Заливаем цыпленка соусом и тушим 15- 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1693,'Печень очистить и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1693,'Субпродукт посыпать специями и солью, жарить на растительном масле десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1693,'Измельчить и обжарить лук и морковь, перемешать с печенью и мягким сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1693,'Перемолоть ингредиенты при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Промыть чернослив, залить коньяком на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Печень нарезать кусочками, жарить на смеси сливочного и оливкового масла, время – пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Влить сливки, все вместе томить десять минут под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Перемолоть массу при помощи кухонного комбайна, добавить чернослив.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Паштет перемолоть еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1694,'Выложить массу в емкость для хранения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1695,'Репчатый лук нашинковать, печень промыть и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1695,'Массу обжарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1695,'Влить сливки, тушить все вместе под крышкой десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1695,'Остудить, выложить в чашу кухонного комбайна, добавить специи, базилик, чеснок, вяленые томаты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1695,'Готовый паштет переложить в посуду, хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1696,'Печень нарезать, выложить в кастрюлю, посолить, влить воду, добавить лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1696,'Проварить десять минут, снять с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1696,'Лук и морковь измельчить, обжарить на оливковом масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1696,'Перемешать печень с овощами, специями и сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1696,'Продукты перебить при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Королевские или тигровые креветки разморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Очистить от панциря, хвостик оставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Побрызгать морепродукты лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Приготовить кляр из белой муки, воды, семян кунжута, соли, пищевой соды, имбиря.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Обмакнуть подготовленные креветки в кляр, опустить в кипящее масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Время приготовления блюда – от четырех до пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Обжаривать на рафинированном растительном масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1697,'Выложить закуску на салфетку для впитывания жира.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Кабачок чистим и натираем его на крупной терке. Солим натертый кабачок, перемешиваем и пока отставляем его в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Пока приготовим начинку. Все ингредиенты подготавливаем в разные миски. Твердый сыр натираем на крупной терке. Нарезаем репчатый лук, колбасу и зелень укропа. Помидоры я нарезаю тонкими пяточками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Натертый кабачок постоял минут 15, теперь отжимаем с него лишнюю жидкость и выкладываем отжатый кабачок в другую посуду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'В отжатый кабачок добавляем куриные яйца, пшеничную муку. Солим эту кабачковую массу по вкусу и добавляем молотый черный перец. Хорошо размешиваем кабачковое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Форму для выпечки смазываем растительным маслом и выкладываем в нее наше кабачковое тесто, разравнивая его по форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1717,'Добавить классические продукты – отваренную и нарезанную кубиками свеклу, морковь, картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Теперь на кабачковое тесто выкладываем слоями нашу подготовленную начинку. Я сначала посыпаю укропом затем репчатый лук, нарезанные помидоры и последним слоем нарезанную полукопченую колбасу. Посыпаем кабачковую пиццу натертым сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1698,'Готовим пиццу из кабачков примерно 50 минут в духовке при 190 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Для начала нужно приготовить соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Сыр натираем на мелкой или крупной терке. Перекладываем в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Укроп мелко нарезаем. Перекладываем в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Лаваш нарезаем по размеру сосисок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Подготовленный лаваш намазываем соусом, посыпаем сыром и укроп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'На 1 край, укладываем сосиску, и заворачиваем, слегка прижимаем. Даём немного пропитаться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1699,'Далее «Сосиски в лаваше» нарезаем на бочонки, и после этого по середине лаваша прокалываем шпажкой. На каждой шпажке у меня получилось по 4-5 бочонков.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1700,'Налить на сковороду растительное масло, прогреть, опустить крупные креветки, веточки лемонграсса, чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1700,'Посыпать имбирем и сахарным песком, жарить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'В воду всыпать муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'Соль – по вкусу, добавить молотый корень имбиря.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'Налить на сковороду растительное масло на три или четыре сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'Прогреть в течение трех или четырех минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'Креветки по одной штуке обмакивать в кляр, затем – в панировку, выложить в масло на пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1701,'Продукт должен приобрести золотистую корочку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'Муку перемешать с молоком, в смеси не должно быть комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'Добавить сырой куриный желток, соль, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'На крупных креветках сделать надрезы так, чтобы они стали плоскими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'Разогреть масло во фритюрнице.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'Морепродукты обмакивать в кляр, в сухари, затем – погрузить в кипящее масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1702,'Жарить пять или шесть минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1703,'Всыпать муку в воду, перемешать венчиком, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1703,'Вскипятить масло во фритюрнице, выложить морепродукты в кляре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1703,'Время жарки – от пяти до семи минут, в зависимости от размера креветок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1704,'Приготовить кляр из воды с мукой, яйца и плавленого сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1704,'Добавить соль, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1704,'Раскалить растительное масло на сковороде, креветки обмакнуть в сырную смесь, обжарить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1704,'Время приготовления – несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1705,'Мякоть авокадо натереть на терке или приготовить пюре при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1705,'Порубить отваренные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1705,'Смесь посолить, добавить лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1705,'Отварить и остудить креветки, разрезать пополам, добавить в основную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1705,'Влить немного бульона или домашнего майонеза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1706,'Скумбрию горячего копчения и плоды авокадо очистить, перемолоть при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1706,'Добавить мягкий сыр, сливки, давленый чеснок, рубленую зелень и семечки кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1706,'Ингредиенты перемешать, посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'С куска сала срезать шкурку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Промыть сало холодной водой, обсушить полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Прокрутить через мясорубку несколько раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Очистить чеснок, пропустить через пресс.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Сало посолить по вкусу, поперчить, добавить чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Перемешать ингредиенты до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1707,'Хранить пасту в холоде, в стеклянной баночке под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1717,'Добавить покрошенный репчатый лук, заправить блюдо растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1718,'Перемешать отваренные овощи: нарезанный кубиками картофель, свеклу и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1718,'Покрошить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1708,'Просеять муку, собрать ее в горку, в середине сделать углубление, положить в него творог, который необходимо протереть через сито, порезанное на маленькие кусочки масло и соль. Замесить густое тесто, поместить его в полиэтиленовый пакет и поместить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1708,'Разогреть духовку до 200 градусов. Снять с яблок кожуру, вырезать середину, припустить в маленькой кастрюле на протяжении 5 минут, добавить сок лимона, достать яблоки, обсушить. Присыпать стол мукой, раскатать на нем пласт прямоугольной формы, порезать его на квадраты по величине яблок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1708,'Положить по одному яблоку на каждый квадратик из теста, смешать корицу с сахаром и насыпать в яблоко. Соединить противоположные концы теста, смазать взбитым яйцом и запекать полчаса. Перед тем как подавать на стол, яблоки, запеченные в творожном тесте необходимо остудить и посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Отскрести лишнюю соль с куска сала, протереть его бумажным полотенцем, разрезать на несколько частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Истолочь в ступке горошины перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Промыть очищенный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Перебрать зелень укропа, кинзы, базилика, петрушки. Жесткие части удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Зелень покрошить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Перемолоть продукты при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Массу положить в банку, хранить в холодильнике.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1709,'Температура хранения сала – от минус восьми до минус пятнадцати градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1710,'Несоленое сало измельчить любым способом: пропустить через мясорубку или перемолоть в кухонном комбайне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1710,'Порубить зелень укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1710,'Пропустить очищенный чеснок через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1710,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1711,'Черный перец, чеснок, паприка, кориандр, красный перец, тмин, горчица в зернах – все специи должны быть в молотом виде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1711,'Сало измельчить в пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1711,'Перемешать основной компонент с добавками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1712,'Красный болгарский перец очистить от семян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1712,'Порубить чеснок, петрушку, базилик, кинзу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1712,'Растереть черный и душистый перец в ступке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1712,'Все продукты перемолоть в блендере вместе с салом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Отварить, очистить и нарезать свеклу, морковь, картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Нарезать соленые огурцы, репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Посолить по вкусу, заправить подсолнечным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Белую или красную фасоль предварительно замочить в холодной воде на несколько часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Отварить до готовности, но не переварить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1713,'Добавить в винегрет и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Отварить морковь, картофель, свеклу. Овощи нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Покрошить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Добавить кусочки заранее отваренной курицы, маринованные грибы, квашеную капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Вместо грибов можно использовать нарезанную сельдь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Если в блюдо добавить квашеную капусту и маринованные огурцы, то острый вкус кушанья можно смягчить нарезанным или натертым яблоком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Заправить винегрет оливковым маслом или майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1714,'Готовое блюдо посыпать рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Отварить картофель, свеклу и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Овощи очистить, нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Выложить ингредиенты слоями вместе с репчатым луком и консервированным зеленым горошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Последовательность слоев: свекла, белая отваренная или консервированная фасоль, картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'На этом этапе продукты желательно посолить и поперчить, добавить немного подсолнечного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Далее – репчатый лук, морковь с маслом и солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1715,'Соленый, маринованный или свежий огурец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1716,'Отварить в подсоленной воде овощи: картофель, свеклу, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1716,'Нарезать кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1716,'Перемешать с морской капустой, репчатым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1717,'Перемешать консервированную фасоль с маринованными грибами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1718,'Приготовить заправку из растительного масла, горчицы, соли, сахарного песка и уксуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1718,'Добавить нарезанное кисло-сладкое яблоко, соленую кильку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1719,'Свеклу положить в целлофановый пакет, запечь в микроволновке в течение двадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1719,'Далее нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1719,'Добавить отваренный картофель, морковь, репчатый лук, лучше красный, фасоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1719,'Заправить растительным маслом, выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1720,'Отваренный картофель, морковь, свеклу нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1720,'Соединить с консервированной или отваренной фасолью и солеными огурцами, репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1720,'Заправить подсолнечным маслом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Свеклу отварить, охладить, очистить, натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Нашинковать белокочанную капусту и помять ее руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Порубить репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Морковь вымыть и натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Продукты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Приготовить заправку из растительного масла, сахарного песка, соли и лимонного сока. Взбить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1721,'Полить салат смесью, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Свеклу вымыть, отварить в воде с уксусом. Время варки – около часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Нашинковать свежую капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Отварить в мундире картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Порезать репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Нарезать кубиками картофель, остывшую свеклу, соленые огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Перемешать ингредиенты в глубокой миске.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Приготовить заправку из столовой горчицы, уксуса, соли, сахара, растительного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1722,'Залить салат, перемешать еще раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Отварить морковь, картофель, свеклу, охладить, очистить, нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Нашинковать краснокочанную капусту, посолить и помять руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Затем полить продукт лимонным соком, уксусом, оставить на десять минут для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Соленые огурцы очистить от кожицы, нарезать мелкими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Нарезать соломкой соленые грибы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Приготовить заправку: растереть горчицу с растительным маслом, добавить соль и сахарный песок, молотый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1723,'Ингредиенты соединить, полить соусом, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1724,'В глубокую емкость положить горчицу, сахар, соль, томатную пасту и все перемешать. Во второй чашке смешать приправы с измельченным чесноком, залить кипятком. Накрыть и поставить, пока смесь не остынет. После этого перемешать настой, вылить в него через ситечко смесь из первой емкости, перемешать. Разбавлять нужно так, чтобы масса получилась не слишком жидкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1724,'Налить в кетчуп лимонный сок. Причем сразу выливать его не стоит, делать это нужно постепенно, возможно его понадобится меньше. По вкусу можно посыпать солью и перцем. Готовый домашний натуральный кетчуп с чесноком необходимо перелить в баночку и поставить ее в холодильник. Кетчупа получается 200 миллилитров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Картофель, морковь и небольшую свеклу хорошо вымыть, отварить, очистить и нарезать маленькими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Репчатый лук нарезать произвольно и обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Белокочанную капусту нарезать соломкой и помять руками, чтобы продукт дал сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Консервированную фасоль откинуть на дуршлаг, дать стечь жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Нарезать зелень укропа и петрушки, соленые или маринованные огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1725,'Ингредиенты перемешать, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1726,'Отварить по отдельности свеклу, картофель и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1726,'Овощи очистить, зелень укропа мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1726,'Покрошить белокочанную капусту, лук, свежие огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1726,'Отваренные овощи нарезать кубиками одного размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1726,'Салат заправить майонезом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Вымыть и отварить до готовности свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Нарезать тонкой соломкой белокочанную капусту, посолить и потереть руками до появления сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Нарезать соломкой яблоко с кожицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Побрызгать продукт уксусом или лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Порезать очищенный репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Свеклу натереть на терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1727,'Продукты перемешать, заправить рафинированным растительным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'Морковь, картофель, свеклу отварить до готовности, остудить, очистить и покрошить кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'Нашинковать белокочанную капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'Нарезать репчатый лук полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'Соленые или маринованные огурцы нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'В салат добавить зеленый горошек, соль и горчицу по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1728,'Полить растительным маслом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1729,'Отварить до готовности морковь, свеклу, картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1729,'Очистить овощи, нарезать мякоть брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1729,'Нарезать репчатый лук полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1729,'Добавить квашеную капусту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1729,'Салат посолить и поперчить, влить рафинированное растительное масло, посыпать зеленью петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Фасоль, свеклу и картофель отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Свеклу нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Нашинковать лук и картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Для салата уместна белая фасоль, можно использовать консервированный продукт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Добавить квашеную капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1730,'Заправить салат растительным маслом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1731,'Отварить в отдельных кастрюлях морковь, свеклу, картофель в кожуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1731,'Продукты остудить, очистить, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1731,'Промыть и порубить укроп, репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1731,'Продукты переложить в салатницу, добавить зеленый горошек, квашеную капусту, влить оливковое масло, всыпать соль, перец, влить лимонный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Картофель, свеклу, морковь отварить в кожуре. Очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Картофель и морковь можно варить вместе, свеклу – отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Нашинковать овощи кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Очистить репчатый лук, порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Нарезать маринованные огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Продукты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Добавить квашеную капусту, влить растительное масло, посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1732,'Ингредиенты еще раз перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Отварить курицу до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'В другой кастрюле отварить свеклу, в третьей – картофель и морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Продукты остудить, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Свеклу выложить в отдельную емкость и полить растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Квашеную капусту отжать, нарезать мелкими кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Соленые огурцы очистить и нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Все ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1733,'Приготовить заправку из лимонного сока, горчицы, растительного масла. Заправить винегрет, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Свеклу, морковь и клубни картофеля отварить в кожуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Очистить, нарезать овощи кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Свеклу полить растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Слить жидкость от квашеной капусты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Отварить спаржу в течение четырех минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Переложить в сковороду, полить кунжутным маслом, спассеровать в течение двух минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Продукты перемешать, добавить рубленый репчатый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Приготовить заливку из подсолнечного масла, лимонного сока, ингредиенты перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1734,'Залить салат.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1735,'Лук очистить и нарезать четвертькольцами. Свинину нарезать небольшими кусочками (около 3*1,5 см).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1735,'В сковороде разогреть растительное масло и обжарить лук на сильном огне в течении 3 минут, перемешивая. К луку добавить паприку и перемешать. Затем добавить свинину, пропустить чеснок через пресс снова перемешать и убавить огонь до минимума, готовить под крышкой 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1735,'Спустя 20 минут посолить мясо, добавить горячую воду (100 мл), накрыть крышкой и готовить еще 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1735,'Болгарский перец очистить от семян. Помидоры и перец нарезать мелким кубиком, отправить в сковороду, добавить томатную пасту – перемешать. Накрыть крышкой, готовить еще 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Отварить морковь и картофель в одной емкости, свеклу – в другой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Порубить все овощи мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Очистить от кожуры свежие огурцы, порубить кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Продукты перемешать в салатнице.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Отжать сок от квашеной капусты, добавить в основную массу вместе с нарезанным луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1736,'Полить растительным маслом и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1737,'Нарезать сосиски на кольца. На мелкой терке натереть морковь. Нарезать картофель на маленькие кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1737,'Поставить кастрюлю с водой на огонь, добавить соль, довести до кипения. После того, как вода закипит, добавить картофель, доводим до кипения, варим 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1737,'Морковь обжарить на сковороде с растительным маслом на среднем огне в течении 5 минут. Затем добавить сосиски и все вместе жарить еще 3-4 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1737,'Когда картофель отварился, в кастрюлю добавить морковь, сосиски и вермишель. Варим еще 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1737,'Кастрюлю с супом снимаем с огня, добавляем плавленые сырки и перемешиваем, пока сырки не растаят.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Сливочное масло комнатной температуры соединить с сахарной пудрой – перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Добавьте яйцо, ванилин и соль, снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Добавьте разрыхлитель и постепенно всыпьте муку, замесите тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Накрыть тесто пакетом или положить в пакет и отправить в холодильник на 1 час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Выстелить лист бумаги для выпечки по форме противня, раскатать на нем тесто (не тонко, около 5 мм). Вырезаем из теста круги, в середине каждого круга вырежьте дырочку (я вырезала при помощи крышки от бутылки).⠀',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1738,'Порубите орехи и взбейте яйцо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Картофель, свеклу и морковь отварить или запечь в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Нарезать мякоть соломкой или кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Свеклу держать отдельно, полить растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Квашеную капусту отжать и добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Нарезать слабосоленую сельдь, соленые огурцы и репчатый лук',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Открыть банку консервированного горошка, слить жидкость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Приготовить заливку из растительного масла с уксусом, сахарным песком, молотым перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1739,'Смесь взбить вилкой. Ингредиенты соединить, залить соусом. Перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1740,'Заправка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1740,'Добавляем соль, сахар, черный молотый перец, сухой базилик, лавровый лист, томатную пасту и воду.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1740,'Рыбу посыпаем солью, черным молотым перцем и поливаем растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1740,'Выкладываем рыбу в формы и заливаем заправкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1741,'Готовим начинку. Доводим до кипения кастрюлю с водой. Куриное филе нарезать слайсами толщиной 1 см, в кипящую воду отправляем порционно кусочки филе (по 1-2 штуки за раз), варим по 5 минут. Вынимаем, остужаем и нарезаем мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1741,'Нарезаем грибы и белый лук, также мелким кубиком. В сковороде разогреть растительное масло и отправить туда грибы с луком, готовим на среднем огне в течении 10 минут, перешивая. Снимаем с огня, добавляем курицу и смесь перцев, перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1741,'Разложить листы теста фило на столе, нарезать на прямоугольники по размеру будущих рулетиков. Растопить сливочное масло, смазать им прямоугольники теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1741,'На каждый прямоугольник выкладываем начинку, скручиваем рулетики запечатав края, чтобы начинка не вываливалась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1741,'В сковороде разогреть большое количество растительного масла и обжариваем рулетики на среднем огне со всех сторон до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Отварить говядину заранее, охладить и тонко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Куриные яйца отварить вкрутую, охладить и очистить, нарезать небольшими дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Свеклу завернуть в лист фольги и запечь в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Отварить картофель с морковью, овощи очистить и нарезать маленькими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Покрошить репчатый лук и соленый огурец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Если кожица твердая, жесткая – срезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Перемешать майонез с лимонным соком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1742,'Заправить продукты соусом, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Налить в кастрюлю воду, поставить на огонь и хорошо нагреть. В горячую воду отправить копченые ребра. Доводим до кипения и варим 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Готовим чипетки. В миску разбить яйцо, добавить щепотку соли и муку, замесить тесто руками. Готовое тесто положить в пакет и пока отложить в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Лук нарезать мелким кубиком. В сковороде с растительным маслом обжарить лук на среднем огне в течении 5 минут, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Болгарский перец очистить от семян, нарезать мелким кубиком, добавить в сковороду, готовим 5 минут, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'К этому времени отварили ребра, достаем их из кастрюли и остужаем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Снимаем с ребер мясо и нарезаем мясо на кубики. Отправляем мясо в кастрюлю, добавляем чеснок, пропущенный через пресс. Перемешиваем, накрываем кастрюлю крышкой, варим на медленном огне 3 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1743,'Тесто, достаем из пакета, и раскатываем из него тонкие колбаски, нарезаем колбаску на куски длиной 0,5-1 см. Отправляем чипетки в кастрюлю и перемешиваем, засыпаем консервированную фасоль. Накрываем кастрюлю крышкой, варим на медленном огне 10 минуты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1744,'Перепелиные яйца отварить, охладить в воде, очистить, разрезать каждое пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1744,'Натереть твердый сыр, нашинковать зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1744,'Выложить на большое блюдо порванные руками листья зеленого салата, далее – яйца, кусочки сельди, посыпать сыром и украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1744,'Поперчить, побрызгать соком лимона, растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1745,'Порезать слегка подмороженное филе курицы на кубики, выдавить чеснок, смешать с овсяной крупой в пропорции 1 к 1 и майонезом. Слепить куриные котлетки с овсянкой и обжаривать их на сковороде приблизительно по 5 минут со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Отварить свеклу, морковь и клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Сельдь очистить и нарезать ломтиками, нашинковать репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Добавить консервированную фасоль без жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Разрезать пополам консервированные оливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Покрошить соленые огурцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1746,'Ингредиенты перемешать, полить оливковым маслом и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Отварить картофель с морковью до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'В отдельной емкости отварить свеклу, остудить и почистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Все овощи нарезать одинаковыми кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Измельчить любым способом соленые огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Квашеную капусту отжать, крупные кусочки мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Все подготовленные ингредиенты соединить, поперчить по вкусу, полить оливковым маслом и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1747,'Нарезать зелень, посыпать салат. Выложить ломтики сельди.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Сварить свеклу, отдельно – картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Продукты охладить, очистить от кожуры, нарезать крупными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Яблоко очистить, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Красный лук нашинковать полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Все компоненты соединить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Сельдь нарезать тонкими брусками, лук-шалот – кольцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Все ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Посыпать зеленым консервированным горошком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1748,'Полить салат оливковым маслом, побрызгать соком лайма, соль и перец – по вкусу и желанию.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Куриный бульон смешать с кукурузным крахмалом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1749,'Подсолнечное масло перемешать с солью и сладкой горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1749,'Влить яблочный уксус, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1749,'Соус перебить блендером до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1750,'Перемешать оливковое масло с винным уксусом при помощи вилки или миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1750,'Всыпать мелкую соль, смесь молотых перцев.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1750,'Ввести давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1751,'Перебить до однородности густую томатную пасту с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1751,'Добавить сладкую горчицу, влить немного кипяченой воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1751,'Ингредиенты еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1751,'Соль и сахар – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1752,'Промыть и обсушить листья светлого базилика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1752,'Измельчить вместе с чесноком при помощи блендера, влить оливковое масло первого отжима.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1752,'Всыпать тертый сыр «Пармезан», соус перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1752,'Добавить очищенные кедровые орешки, массу еще раз перебить блендером или миксером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1753,'В нежирную сметану добавить натуральный яблочный уксус, неострую горчицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1753,'Ингредиенты хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1753,'Всыпать соль по вкусу, сахарную пудру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1753,'Смесь поставить в холодильник на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1754,'Перемешать винный уксус с оливковым маслом, добавить сахар и соль, молотый черный перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1754,'Перемешать, соль и сахар должны раствориться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1754,'Добавить неострую горчицу, влить лаймовый или лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1755,'Отварить куриные яйца, желтки растереть при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1755,'Добавить молотый перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1755,'Отдельно перемешать бальзамический уксус с кукурузным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1755,'Смесь влить в соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1755,'Компоненты растереть, добавить лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1756,'Перемешать дижонскую горчицу с соком лайма, ингредиенты растереть до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1756,'Всыпать сахарную пуду, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1756,'Влить охлажденную смесь оливкового и подсолнечного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1756,'Продукты перемешать еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1756,'Подержать в холоде не менее пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Грибы вымыть и обсушить на полотенце, ножки аккуратно срезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Куриное филе пропустить через мясорубку, обжарить на растительном масле вместе со специями и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'В посветлевший фарш всыпать мелко нарезанные грибные ножки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Прогревать в течение десяти или пятнадцати минут, огонь – средний. Мясо должно приобрести корочку, грибы стать мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Ввести сметану и давленый чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Подержать на плите еще три или четыре минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Огонь погасить, начинка должна остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Потереть твердый сыр на терке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Форму для запекания застелить калькой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Смазать поверхность маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Наполнить грибные шляпки начинкой с помощью чайной ложки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Выложить в форму.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1757,'Посыпать тертым сыром, отправить в духовой шкаф на двадцать или двадцать пять минут, температура приготовления – от 190 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Свежие шампиньоны и репчатый лук мелко нарезать и немного обжарить на сливочном масле. Масса должна уменьшиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Ввести перец молотый, соль по вкусу, сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Подержать на огне пять минут, помешивать, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Переложить в тарталетки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Твердый сыр натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Противень застелить пергаментом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Присыпать закуску сыром и запечь при температуре 180 градусов в течение пяти или семи минут. Сыр должен расплавиться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1758,'Подать жульен теплым.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'В миске смешать муку, сахар, соль и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Влить теплое молоко и воду, перемешать, вымесить тесто (около 7-10 мин).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Вмешать в тесто мягкое сливочное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'Залить основную массу, выставить опцию «Выпечка» на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Через час тесто выложить на рабочую поверхность и пальцами расплющить в круг.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Через 10 минут каждый шар теста расплющить в лепешку и снова сделать шар. Накрыть и оставить на 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Сковороду смазать растительным маслом слегка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1759,'Перевернуть булочки, накрыть крышкой и готовить еще 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1760,'Отварить картофель в кожуре, остудить, почистить, порезать кубиками, сложить в емкость. Порезать кубиками огурец, положить его к картофелю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1760,'Добавить зеленый консервированный горошек без жидкости и маринованные грибы. Если грибы большие, порезать их на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1760,'Перемешать салат и добавить растительное масло. Украсить салат «Боярский» зеленью укропа или петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Нарезать говядину кусочками небольшого размера, обжарить на растительном масле до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Влить воду, всыпать соль и перец, потушить двадцать минут под крышкой, помешивать. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Репчатый лук нарезать полукольцами, свежие шампиньоны – пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Твердый сыр натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Сметану разбавить водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'На дно горшочков выложить кусочки говядины, полить выделившимся при тушении соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Далее – грибы, лук, соль и перец молотый – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Влить жидкую сметану.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Горшочки с крышками отправить в духовой шкаф. Время запекания – от пятидесяти до пятидесяти пяти минут. Температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Горшочки вынуть, посыпать тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1761,'Запечь порции второй раз, без крышек, время – от десяти до пятнадцати минут. Сыр должен расплавиться.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Филе птицы отварить, нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Нашинковать репчатый лук, нарезать грибы тонкими пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Влить в чашу растительное масло, добавить соль, обжарить грибы в режиме «Выпечка». Жидкость должна испариться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Добавить топленое масло, жарить еще пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Переложить обжарку в другую емкость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Выставить режим «Тушение», спассеровать репчатый лук до прозрачности, добавить грибы и курицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Через пять минут всыпать муку, перемешать, влить сметану с перцем и солью. Время приготовления – семь минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1762,'Посыпать блюдо тертым сыром, выставить режим «Выпечка на десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1763,'При помощи мультиварки обжарить репчатый лук и шампиньоны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1763,'Добавить отваренное заранее куриное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1763,'Приготовить заливку из сметаны, муки и масла. Все вместе потомить в режиме «Тушение».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1763,'Готовую начинку выложить в тарталетки вместе с подливкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1763,'Натереть твердый сыр, посыпать блюдо, поставить в микроволновую печь или в духовой шкаф до расплавления сыра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1764,'Картофель нарезать пластинками, обжарить с топленым маслом в режиме «Выпечка» или «Жарка» в течение десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1764,'Добавить тонко нарезанные маринованные грибы, топленое масло и нашинкованный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1764,'После испарения жидкости в жульен добавить специи, влить сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1764,'Блюдо потушить еще десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1764,'Всыпать сушеный укроп, тертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1765,'Свежие шампиньоны нарезать пластинками, тушить в мультиварке в режиме «Выпечка» вместе с нарезанным мясом и брусочками репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1765,'Готовить без крышки, ингредиенты помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1765,'Влить сливки, добавить перец и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1765,'Готовить блюдо еще полчаса в том же режиме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1765,'Посыпать тертым сыром, потушить еще десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'Грибы отварить в нескольких водах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'Обжарить в масле вместе с нарезанным репчатым луком, выставить мультиварочный режим «Жарка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'Приготовить подливу из сливок, муки, специй, соли, тертого сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1766,'В конце всыпать дополнительную порцию тертого сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Томаты очистить, мякоть нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Выставить режим «Выпечка», влить в чашу мультиварки оливковое масло и выложить мидии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Как только морепродукт приобретет оранжевую окраску – добавить креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Все вместе жарить три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Добавить томаты, влить подливку из сметаны, гранатового соуса, соли, перца, соевой приправы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1767,'Все посыпать тертым сыром, потомить блюдо под крышкой в течение десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Выставить в мультиварке режим «Выпечка», жарить лук в масле до полупрозрачного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Добавить курицу, нарезанную брусками, все вместе потушить до испарения жидкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Тонко нарезать грибы, добавить в основную массу вместе со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Время тушения – пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Остудить в миске.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Удалить верхушки с булочек, вынуть мякоть, заполнить грибной начинкой, присыпать тертым твердым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Печь пять минут в том же режиме.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1768,'Другой способ – довести булочки с начинкой до готовности в микроволновой печи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Сливочное масло или качественный маргарин смешать с мукой и сырым куриным яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Вымесить тугое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Готовый колобок завернуть в пленку и поставить в холод на двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Формочки для маффинов или бумажные корзинки для кексов смазать растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Раскатать из охлажденного теста тонкие лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Выложить в формочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1769,'Выпечь тарталетки до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Свежие шампиньоны мелко нарезать, обжарить до готовности с репчатым луком и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Копченую курицу нарезать и тоже обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Можно использовать вареное мясо – в этом случае его проще разобрать на волокна.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Ингредиенты соединить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Начинить тарталетки, посыпать тертым твердым сыром, запечь в духовом шкафу до расплавления сыра. Температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1770,'Выложить на блюдо, украсить оливками, зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1771,'Банан размять вилкой в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1771,'Добавить яйцо, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1771,'Добавить муку и разрыхлитель, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1771,'Влить молоко и добавить мед, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1771,'Выпекать в микроволновой печи 3-4 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1772,'Приготовить обжарку из курицы, грибов, репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1772,'Перемешать с плавленым сыром из коробочки. Масса должна получиться густой и тягучей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1772,'Выложить начинку в тарталетки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1772,'Запечь в течение нескольких минут в микроволновой печи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Курицу обжарить с грибами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Влить жирные сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Прогреть до загустения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Выложить готовую начинку в корзинки-тарталетки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Посыпать тертым сыром, запечь в духовке при температуре 220 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1773,'Жульены вынуть, подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1774,'Для приготовления натуральных красителей для коржей необходимо выжать сок шпината, моркови и свеклы. В микроволновую печь поставить замороженную ежевику и чернику, чтобы выделился сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1774,'Взбить сливочное масло с растительным маслом и сахаром. Вбить желтки и взбить до воздушной массы. Добавить йогурт, молоко, ваниль, поочередно с мукой, содой и разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1774,'Разлить тесто в 6 формочек, добавить в них красители, должно получиться 6 различных коржей: несколько столовых ложек сока свекольного, 1,5 столовые ложки сока морковного, желток с 1 столовой ложкой молока, столовая ложка сока шпината, столько же сока ежевичного и черничного.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1774,'Корж каждого цвета выпекать по 15 минут при температуре 175 градусов (готовность нужно проверять зубочисткой). Перед тем как достать коржи из формочки, их необходимо остудить в течение 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1774,'Взбивать на протяжении нескольких минут ингредиенты, приготовленные для крема. Должна получиться кремовая, однородная масса. Чтобы приготовить глазурь, взбить сливки, соль и сахар, добавить ваниль. Каждый слой торта смазать сливочным кремом. Снаружи на весь разноцветный торт «Радуга» с натуральными красителями нанести глазурь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'В чаше мультиварки обжарить курицу с грибами и репчатым луком. Все продукты должны быть мелко нарезаны, режим «Жарка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'Добавить сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'Смесь вынуть, начинить готовые тарталетки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'Посыпать порции сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'Выставить закуску на дно чаши, закрыть крышку, запечь при режиме «Выпечка» или «Жарка». Время приготовления – от двадцати минут до получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1775,'Подать закуску теплой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1776,'Куриное филе нарезать, обжарить с репчатым луком и шампиньонами до получения золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1776,'Заправить начинку майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1776,'Выложить в песочные корзинки, посыпать тертым сыром. Масса не должна быть слишком водянистой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1776,'Запечь до расплавления сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Тушки кальмаров вымыть, зачистить, нарезать максимально тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Шампиньоны нарезать тонкими пластинками, репчатый лук – полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Раскалить сковороду, обжарить лук в течение трех минут, всыпать грибы, жарить еще десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Кальмары обжарить на другой сковороде, перемешать с грибами и луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Выложить в небольшие формы для запекания. Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Немного муки обжарить на сливочном масле, перемешать со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Соусом залить жульен.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1777,'Посыпать тертым сыром, поставить в духовку на десять минут, можно чуть больше или меньше, температура приготовления – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Окорочок варим и убрав кожу нарезаем его на маленькие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Варим замороженную смесь овощей как указано на упаковке (примерно 7 минут). Сливаем воду из овощей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Лук нарезаем полукольцами и маринуем его. Для этого в нарезанный в миску лук добавляем все ингредиенты для маринада и отставляем его пока постоять в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Из яиц делаем тонкие омлетные блинчики, посолив и поперчив их по своему вкусу. Остужаем блинчики и нарезаем их тонкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Теперь из маринованного лука сливаем воду через ситечко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1778,'Смешиваем все подготовленные продукты в салатнике и заправляем майонезом. Солим салат по своему вкусу и хорошо перемешаем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1779,'Печенье нужно измельчить в крошку при помощи блендера. Крошку печенья пересыпаем в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1779,'К крошке печенья добавляем какао-порошок и молоко замешиваем «песочное тесто». Как только замешали, убираем «песочное тесто» в холодильник на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1779,'В другую миску перекладываем 2 пачки творога, масло сливочное и сахар. Все перемешиваем. Если масса сухая, то можно добавить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1779,'Лично я «песочную массу» переложил на коврик для выпечки, и на нем раскатал «песочную массу» до 1 см. Вы можете сразу раскатать на пищевой пленке, Далее на раскатанную «песочную массу» намазываем творожной начинкой, и с 1 края укладываем повидло. (или джем) И далее заворачиваем в рулет. Край пищевой пленки заворачиваем к себе, а рулет от себя. Как только у вас получился рулет, заворачиваем его в пищевую пленку, и убираем в холодильник на 1 час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1779,'Все готово, спустя 1 час достаем, и подаем к чаю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'В глубокую миску просеять 500 г муки, добавить соль, сахар и быстродействующие дрожжи. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'Добавить 2 яйца, теплое молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'В конце добавляем 2 ст.л. растительного масла и хорошо перемешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'Накрываем тесто чистым полотенцем и убираем в теплое, защищенное от сквозняков место, примерно на 2 часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'Тесто должно увеличится в 2-3 раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'На хорошо разогретую сковороду добавляем растительное масло и выкладываем столовой ложкой тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1780,'Обжариваем оладьи на среднем огне до красивого румяного цвета.Приятного аппетита!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'В кастрюлю с толстым дном налить растительное масло. Отправить лук и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Тем временем измельчить чеснок. Можно выдавить через пресс, но мне больше нравится измельчённый, так чеснок лучше раскрывает свой вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Чеснок добавить к луку. Отправить петрушку, (у меня была замороженная). Перемешать и добавить томаты в собственном соку (можно заменить на свежие). Слегка потушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Нарезать кубиками картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Картофель отправить в кастрюлю к овощам. Хорошо перемешать и залить водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Пока овощи варятся порежу рыбку. У меня филе пангасиуса. Но можно взять любую белую рыбу, минтай или хек к примеру.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1781,'Когда картошка практически готова, добавить рыбку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'Мясо вымыть, обсушить и нарезать небольшими кусочками.','https://vkuso.ru/data/cache/data/25/b754021c1a6eb25_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'Соленые огурцы нарезать брусочками.','https://vkuso.ru/data/cache/data/e9/cf4b884560871e9_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'На разогретую сковороду добавляем растительное масло, выкладываем мясо и обжариваем на сильном огне до золотистого цвета.','https://vkuso.ru/data/cache/data/89/88d660e11545189_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'Добавляем соленые огурцы. Перемешиваем и обжариваем еще минуты 3.','https://vkuso.ru/data/cache/data/46/7a8584b97646e46_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'Добавляем томатную пасту, соль, черный перец и воду. Перемешиваем. Добавляем еще два лавровых листа. Доводим до кипения, уменьшаем огонь. Тушим на слабом огне под закрытой крышкой 25-30 минут.','https://vkuso.ru/data/cache/data/26/ec6a51f8c15c126_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'За 3-5 минут до готовности добавляем измельченный чеснок.','https://vkuso.ru/data/cache/data/e0/f79439ff7ea9ae0_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1782,'Блюдо готово! Приятного аппетита!','https://vkuso.ru/data/cache/data/db/a796e6a634f16db_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1783,'Налить в блендер молоко, по вкусу добавить сгущенное молоко, чернику и банан, взбить бананово-черничный коктейль на полной мощности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1784,'Нарезаем картофель соломкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1784,'Нарезаем грудинку (сало) полосками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1784,'В форму выкладываем свиную грудинку, серединку наполняем картофелем с луком и накрываем всё свиной грудинкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Куриное филе нарезаю небольшим кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Выкладываю курицу в смазанную растительным маслом форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Посыпаю приправой для курицы, она у меня уже с солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Перемешиваю и разравниваю слой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'В миске смешиваю яйца я натертым сыром и сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Выливаю «заливку» поверх курицы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Сверху выкладываю нарезанные кольцами помидоры',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1785,'Запекаю в духовке при 180 градусах 40 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Смешать соевый соус с горчицей и опустить в смесь крылышки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Оставить мариноваться пока подготавливаются остальные ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Морковь нарезаю на брусочки, лук-перьями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Обжариваю овощи в разогретой сковороде с растительным маслом до прозрачности лука',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Добавляю сливочное масло',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Всыпаю в сковороду пропаренный рис ,и обжариваю его 3 до 5 минут. Это поможет предотвратить разваривание риса в дальнейшей готовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Всыпаю специи. Перемешиваю и выкладываю на дно формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Сверху выкладываю куриные крылышки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1786,'Отправляю форму в разогретую до 180 градусов духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Шиитаке замочить в теплой воде на 1 час до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Говядину тонко нарезать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'В сковороду влить кунжутное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Добавить чеснок, жарить 1 минуту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Добавить грибы готовить 2 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Добавить лук и морковь, жарить 2 минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1787,'Влить соевый соус, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Свинину промыть, обсушить, нарезать крупными кусочками, посолить, посыпать специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Влить на сковороду постное масло, положить сливочное.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Обжарить мясо со всех сторон до получения корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Влить воду в сковороду на две трети объема.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Тушить один час под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Через десять минут мясо переворачивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'По необходимости жидкость доливать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Отдельно, на маленькой сковороде, приготовить соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Обжарить на сливочном масле репчатый лук, нарезанный полукольцами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Добавить белое сухое вино и специи.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Тушить до выпаривания алкоголя.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Влить сливки, подержать смесь на огне до загустения.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1788,'Залить соусом мясо, перемешать и потушить все вместе еще пять минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'В отдельной посуде смешать муку, сахар, ванилин и разрыхлитель.','https://vkuso.ru/data/cache/data/42/8ced04175ecc842_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Отделить желток от белка.','https://vkuso.ru/data/cache/data/99/eef8dfedc96bb99_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Белок взбить с щепоткой соли в пышную пену.','https://vkuso.ru/data/cache/data/b4/a0cefcf117b63b4_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Добавить молоко, растопленное сливочное масло и творог. Перемешать.','https://vkuso.ru/data/cache/data/0e/8ccf3d1989c940e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Теперь добавляем сухую мучную смесь и замешиваем тесто.','https://vkuso.ru/data/cache/data/f6/0e7b2ed19912ff6_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Тесто разделить на 6 частей.','https://vkuso.ru/data/cache/data/d6/53ded5f07e27cd6_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Теперь каждый кусочек теста раскатать в колбаску и свернуть кренделем.','https://vkuso.ru/data/cache/data/89/8ffe01065a22c89_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Булочки выложить на противень застеленный бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1789,'Приятного аппетита!','https://vkuso.ru/data/cache/data/a2/29af46274d3e0a2_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Репчатый лук нарезать кольцами, свинину – полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Сначала приготовить лук в мультиварке, режим «Обжарка». Продукт должен стать прозрачным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Свинину обвалять в муке, обжарить вместе с луком до румянца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Нарезать сладкий болгарский перец, добавить в общую массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Отдельно приготовить соус из томатной пасты, воды, сметаны, перца, соли и сахарного песка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1790,'Залить мясо, перемешать, выставить режим «Тушение» на час, готовить при закрытой крышке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1791,'В емкости соединить уксус или сок лимона, томатную пасту, майонез и специи для шашлыка или свинины. Немного соевого соуса тоже не помешают. Перемешать все, посолить по вкусу. В получившийся маринад заложить ребрышки, нужно буквально втереть маринад в мясо. Поставить в холодильник на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1791,'Почистить картофель и порезать его на четыре части, желательно брать мягкий картофель, чтобы он запекался быстрей. В противном случае порезать его на куски меньшего размера. Порезать морковь и лук полукольцами, обжарить немного на растительном масле. Смешать сырой картофель, лук и морковь, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1791,'На формочку для запекания положить фольгу, уложить на нее картофель, сверху укрыть гарнир свиными ребрами. Завернуть фольгу для герметичности, поставить блюдо в духовку, разогретую до 190 градусов. Выпекать аппетитные свиные ребрышки с картошкой приблизительно 90 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1791,'Развернуть фольгу и еще 20 минут дать мясу подрумяниться, поставив на обдув или включив гриль. В течение 20 минут мясо необходимо перевернуть один раз, чтобы подрумянены были две стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Репчатый лук нарезать полукольцами, обжарить до золотистой корочки на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Мясо вымыть, обсушить, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Обжарить вместе с луком, черным и красным перцем, посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Перемешать, потушить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Добавить нарезанные грибы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Посыпать мукой, перемешать, потушить десять минут. Муку можно заменить крахмалом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Когда грибы выделят жидкость, добавить сметану, долить воду, если есть такая необходимость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Грибы с мясом перемешать, тушить все вместе еще пять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1792,'Незадолго до готовности добавить укроп или измельченный чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Жирные сливки перемешать с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'По желанию продукт можно заменить разведенной в воде сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Добавить сушеную кинзу, лимонный сок, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Свинину вымыть, обсушить салфетками, нарезать кусочками и выложить в готовый маринад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Поставить продукт на два часа в холодильник, емкость закрыть пленкой или крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Выложить мясо в форму для запекания, накрыть листом фольги, поставить в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Время приготовления – полчаса, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1793,'Фольгу снять, допечь в течение пятнадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Свежую свинину нарезать пластинками толщиной в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Обжарить на сковороде до корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Выложить в тарелку. Выделившийся сок пригодится для соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Репчатый лук нарезать кольцами, потушить до прозрачного состояния на тихом огне. Посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Обжарить на сковороде муку, добавить сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'При тушении соус постоянно помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Если масса получилась слишком густой – долить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Всыпать перец, соль, молотый мускатный орех.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Варить две минуты, снять с плиты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Противень смазать маслом, выложить обжаренное мясо, посыпанное перцем и солью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Выложить слой лука, полить сметанным соусом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Время запекания – полчаса, температура – 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1794,'Посыпать тертым твердым сыром, подержать в духовом шкафу семь минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1795,'Свинину нарезать небольшими кусочками, обжарить на сковороде до золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1795,'Нарезать очищенный чеснок, добавить к свинине, перемешать, огонь убавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1795,'Приготовить соус из молока, муки, сушеного майорана, базилика, черного молотого перца, соли. В смеси не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1795,'Мясо перемешать с молочным соусом, потушить под крышкой, несколько раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Батон нарезаем и обжарим его в духовке или на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Яйца варим до готовности. Натираем на мелкой терке яйца и плавленый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Рыбные консервы разминаем вилкой и смешиваем их с натертыми яйцами и плавленым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Свежий укроп мелко нарезаем и добавляем к остальным продуктам. Оставьте немного укропа для украшения бутербродов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Солим по своему вкусу и добавив майонез все хорошо перемешаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Обжаренный батон натираем чесноком и намазываем на него подготовленную начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1796,'Украшаем бутерброды нарезанными кружочками огурца и помидор. И посыпаем сверху зеленью укропа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1797,'Укроп мелко нарезаем и перекладываем в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1797,'Красный болгарский перец нарезаем соломкой и перекладываем в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1797,'В глубокой тарелке, делаем намазку для куриного филе. Из сметаны 5 ч.л. майонеза 2 ч.л., соль, перец по вкусу, и плавленый сыр 3 ч.л. Перемешиваем и убираем в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1797,'Куриное филе моем, сушим бумажным полотенцем. Далее его нужно распластать на 2 части, после чего каждую часть отбиваем. Солим, перчим, и тд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Так же на крупной тёрке натереть яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Отварное куриное филе нарезать небольшими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Измельчить зелёный лук',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1797,'На каждое подготовленное куриное филе намазываем слегка подготовленной намазкой, посыпаем укропом, укладываем с 1 края 1 соломинку болгарского перца, и заворачиваем в рулет. Далее этот рулет обворачиваем в несколько полосок бекона. Перекладываем на протвинь, рулетики нужно укрыть фольгой, и отправить в разогретую духовку при 180°С на 30-35 минут. Спустя 20 минут снимаем фольгу, и даем «подсушиться» подрумянится бекону. Достаем и подаем к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'В большой миске смешать муку, соль, сахар и дрожжи. Влить оливковое масло и воду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'Выложить тесто на рабочую поверхность, присыпанную мукой, и вымесить тесто (около 7-10 минут).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'Тесто разделить на 2 части (у меня получилось 2 шарика теста весом около 500 гр).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'Смазать тесто оливковым маслом, положить каждый шар теста в отдельную миску и накрыть пищевой пленкой. Оставить в теплом месте подниматься на 1 час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'Шар теста выложить на рабочую поверхность, присыпанную мукой, и начать растягивать его руками. Переложить тесто на противень, придать форму руками. Собрать пиццу на свой вкус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1798,'Выпекать пиццу при разогретой до 230ºС духовке 15-17 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1799,'Замочить желатин в молоке и оставить на 1 час набухнуть',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1799,'Первый ягодный слой:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1799,'Второй ягодный слой готовиться аналогично первому',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1799,'В подготовленные формы выложить поочередно ягодные слои,давая им каждый раз в холодильнике (20-30 мин) или морозильной камере (5 минут) стабилизироваться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1799,'Творожно-йогуртовый слой:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Мелко нарезаем тыкву и яблоки, предварительно очистив от шкурки и семян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Тыкву заливаем молоком и тушим на медленном огне почти до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Добавляем к ней яблоки и продолжаем тушить несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Затем добавляем манную крупу, перемешиваем и провариваем 3-5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Яйцо взбиваем с сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'После того, как тыква с яблоками остынет, добавляем в массу взбитое яйцо с сахаром, перемешиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1800,'Выкладываем в форму для выпечки, смазанную сливочным маслом и отправляем в духовку на 180 градусов примерно на 20-25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Сначала подготовим картофель. Нарезать кубиками, отварить в подсоленной воде до полуготовности (5-7 минут с момента закипания).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Пока картофель варится, измельчить лук. К фаршу добавить лук, яйцо, соль, гранулированный чеснок. Хорошо вымесить фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Подготовим заливку. В миску вылить сливки, добавить молоко. Измельчить укроп, добавить к заливке. Выдавить зубчик чеснока. Посолить, поперчить, добавить мускатный орех. Перемешать. Сыр натереть на мелкой тёрке. Добавить к заливке, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Форму для запекания смазать сливочным маслом. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Сформировать маленькие фрикадельки и выложить сверху на картофель.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1801,'Запекать при температуре 180-200°С около 40-60 минут, до румяной корочки. Ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Грибы нарезать кубиками. Я ещё оставила немного пластин для украшения.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'На раскалённую сковородку отправить грибы, ждём когда они пустят сок, и время от времени помешивать, до полного испарения сока.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Натереть отварной картофель на крупной тёрке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Твердый сыр натереть на крупной тёрке',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Собираем салат.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1802,'Вот и все, наш салат готов. Он очень вкусный и сытный. Подавать можно слоями в салатнике, особенно красиво будет смотреться в прозрачном, или как я с помощью кольца либо же кольца от розъёмной формы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1803,'Просеять муку в емкость, добавить масло и растереть ладошками. Насыпать сахар и замесить тесто. Взять квадратную формочку со сторонами 23 сантиметра, положить бумагу для выпечки, положить тесто и наколоть вилкой. Разогреть духовку до 180 градусов, поставить форму и выпекать 20 минут. Когда тесто станет румяным, вынуть формочку и дать ей остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1803,'Чтобы приготовить крем, в тефлоновую кастрюлю насыпать сахарный песок, добавить сгущенное молоко и масло. Варить на маленьком огне, пока крем не закипит, непрерывно помешивая. Сделать огонь на минимум и варить примерно 5-7 минут. Крем должен стать густым, бледно-желтым и отходить от стенок кастрюли. Выложить смесь равномерно по печенью и дать остыть. После растопить шоколад. На крем выложить орехи, налить сверху шоколад, поставить вкусное печенье с молочным шоколадом в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Куриное филе нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Промыть и выложить на бумажное полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Раскалить на сковороде подсолнечное масло, выложить куриное мясо в один слой, обжарить на сильном огне до получения корочки, которая не даст вытечь соку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Приготовить сливочный соус на другой сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Обжарить на сухой поверхности муку до орехового оттенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Добавить сливочное масло, растопить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Влить сливки, соус перемешать, довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Добавить куриное филе, соль и приправы. Использовать черный молотый перец, сухие травы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Довести до кипения еще раз, убавить огонь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1804,'Тушить курицу под крышкой в течение десяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1805,'урицу вымыть, обсушить, нарезать кусочками, обжарить на раскаленном растительном масле со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1805,'Отдельно на сухой сковороде обжарить муку до светло-коричневого цвета, добавить сливочное масло, растопить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1805,'Влить сливки, добавить давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1805,'Выложить в соус куриное мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1805,'Через десять минут выключить газ, в сковороду выложить рубленую зелень, подержать под крышкой десять или пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Куриное филе нарезать, вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Разогреть на сковороде растительное масло, обжарить курицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Влить жирную сметану, сливки, посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Другие приправы – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1806,'Тушить блюдо на тихом огне в течение получаса. Куриное мясо должно стать мягким.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'В глубокой тарелке замешиваем «намазку» из плавленого сыра 1 ст.л сметаны 5 ч.л, соли, перца по вкусу и мелко нарезанного укропа. Убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'Огурец нарезаем соломкой и перекладываем в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'Колбасу и крабовые палочки можно нарезать маленьким или средним кубиком. и переложить в ту же миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'Кукурузу сладкую также добавляем в ту же миску, я добавил полбанки. (Сладкую водичку из под кукурузы переливаем в чашку)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'И теперь в миску, где все ингредиенты, добавляем то, что сделали ранее, это «намазка» из сметаны, укропа и плавленого сыра. Все хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1807,'Лаваш нарезаем на равные квадраты или прямоугольники. И после этого на каждую подготовленную часть лаваша укладываем салат при помощи чайной ложки. Края заворачиваем друг к другу, один край должен быть сверху, прокалываем по середине зубочисткой или шпажкой, перекладываем на тарелку или поднос.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Куриное мясо нарезать, вымыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Раскалить на сковороде подсолнечное масло, раскалить, обжарить до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Сладкий болгарский перец очистить и нарезать, прогреть до мягкости в сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Влить сливки, довести до кипения, пробить блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Готовый соус влить в куриную обжарку, посолить, добавить неострые приправы, тушить все вместе тридцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'За пять минут до готовности добавить мягкий плавленый или твердый тертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Прогреть до расплавления продукта.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1808,'Соус должен быть однородным.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Куриные голени вымыть, обсушить салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Раскалить на сковороде подсолнечное масло, прогреть мясо на сильном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Нарезать полукольцами репчатый лук, натереть морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Обжарить на смеси растительного и сливочного масла до получения золотистого оттенка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Смешать куриные ножки и овощную обжарку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Залить молоком, добавить приправы и соль, тушить полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Ввести муку при постоянном помешивании.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1809,'Довести до кипения, добавить нарезанный базилик, прогревать еще пять или семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Ножки курицы хорошо вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Пропустить через мясорубку перец чили, перемешать с солью и черным молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Вместо перца чили можно использовать 2 ч. л. грузинской аджики, в этом случае в продукт достаточно добавить черный молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Нашинковать репчатый лук, обжарить до золотистого цвета на сливочном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Остатки лука вынуть и выбросить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'В луковом масле обжарить муку, влить сливки и немного заранее приготовленного куриного бульона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Другой вариант – разведенный кубик со вкусом курицы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Пропустить чеснок через пресс.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Добавить в соус, поперчить и посолить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1810,'Готовым соусом полить ножки, запекать в течение получаса или чуть больше при температуре 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Куриное филе нарезать, хорошо вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Обжарить кусочки на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Отварить лесные грибы: для груздей и волнушек потребуется от пятнадцати до двадцати минут, для опят – двадцать минут, для маслят – от десяти до пятнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Грибы нарезать, обжарить на сливочном масле до полной готовности, перед окончанием приготовления добавить давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Муку обжарить, влить молоко или сливки, выложить грибы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Все вместе варить десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Массу пробить блендером до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1811,'Влить готовый соус в куриную обжарку, добавить приправы и соль, тушить все вместе от пятнадцати до двадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Куриное филе нарезать, вымыть, обсушить, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Нарезать кружками помидоры, выложить в сотейник, тушить на большом огне до испарения жидкости. Консистенция массы должна быть полужидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Добавить соль, перец, сливки и базилик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Соус довести до кипения. Можно добавить муку в качестве загустителя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Готовый соус влить к куриному мясу, довести до кипения, тушить двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'В качестве гарнира использовать отваренные макароны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1812,'Куриное мясо положить на гарнир и полить томатным соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Куриное филе вымыть, обсушить и обжарить до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Обжарить 100 г грецких орехов, измельченные в ступке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Всыпать в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'На той же сковороде обжарить муку, добавить орехи и сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Прогреть, довести до кипения, добавить курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Все вместе потушить двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Измельчить зелень и оставшиеся орехи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1813,'Этой смесью посыпать блюдо при подаче.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Куриное филе вымыть, нарезать, обсушить, обжарить до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Соленые огурцы и свежие грибы нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Обжарить грибы с репчатым луком на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Далее добавить огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Все вместе тушить до тех пор, пока не выкипит жидкость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Влить сливки, досолить по вкусу, поперчить, тушить две или три минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Натереть на крупной терке сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Ингредиенты перемешать, часть сыра оставить для украшения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Смесь выложить в небольшие горшочки, сверху – оставшийся сыр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1814,'Противень с емкостями поставить в духовку на двадцать минут, температура приготовления – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Курицу разрезать на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Грудку, окорочка и крылья натереть молотой паприкой и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Жарить до корочки, затем влить стакан воды, потушить полчаса, потомить под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Вяленые помидоры мелко нарезать, перемешать с сахарным песком, солью, йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Влить лимонный сок, добавить курицу с бульоном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Все вместе потушить десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1815,'Порубить укроп и кинзу, посыпать курицу при подаче.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Креветки разморозить, отварить в воде с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Морепродукты остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Крабовые палочки натереть на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Процедуру легче проделать с предварительно замороженными палочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Красный лук очистить и нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Покрошить томаты кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Вымыть красный болгарский сладкий перец, удалить плодоножку с семенами, мякоть нарезать соломкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1816,'Продукты выложить в посуду, посолить, посыпать перцем, заправить майонезом, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1817,'Отварить тальятелле, как указано на упаковке, пока не будет в состоянии аль-денте. Обжарить на масле грибы-лисички с порезанным луком. Влить сливки и готовить, пока смесь не станет густой. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1817,'Слить пасту и выложить ее к соусу в сковороду. Хорошо перемешать и готовить 2 минуты, пасту должен полностью окутать соус. На стол тальятелле с лисичками в сливках подавать в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Креветки отварить в течение полутора или двух минут в воде с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Готовность определяется цветом – продукт должен стать розовым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Снять пленку с тушки кальмара, мясо выложить в подсоленный кипяток на три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Тушку вынуть шумовкой, выложить в дуршлаг.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Креветки разрезать пополам, крабовые палочки, кальмары, пекинскую капусту нарезать полосками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1818,'Ингредиенты полить майонезом и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Нарезать мелким кусочками консервированные ананасы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Нарезать подмороженные крабовые палочки и отваренные куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Твердый сыр натереть на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Креветки быстро отварить, охладить и очистить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Продукты полить майонезом и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1819,'Блюдо досолить по вкусу и поперчить по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Отварить креветки в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Очистить, покрошить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Отварить яйца вкрутую, порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Натереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Продукты соединить, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1820,'Массу разровнять, украсить красной икрой и зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1821,'Отварить замороженные креветки в подсоленной воде, остудить, удалить панцирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1821,'Крабовые палочки нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1821,'Отцедить консервированную кукурузу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1821,'Заправить салат майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Залить кипятком замороженные креветки и кальмаров на две минуты, отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Натереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Покрошить кальмары и крабовые палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Креветки разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1822,'Ингредиенты перемешать, заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Отварить куриные яйца, очистить и натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Креветки выложить в соленый кипяток на три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Откинуть на дуршлаг, подождать, пока стечет жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Крупные креветки можно разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Нарезать кубиками крабовые палочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Натереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Покрошить зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Свежий огурец очистить от кожуры, натереть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Выложить на тарелку слоями: огурцы, яйца, сыр, майонез, крабовые палочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Далее – оставшиеся яйца, сыр, майонез, крабовые палочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1823,'Сверху – креветки и зелень.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Креветки разморозить, можно подержать в воде комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Удалить головы и панцири.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Отварить в течение трех минут в подсоленной воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Нарезать очищенный чеснок, обжарить на сливочном масле. Продукт не должен подгореть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Налить в сковороду сливки, посолить. Довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1824,'Выложить креветки, потомить все вместе две или три минуты под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1825,'Взбиваем 1 куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1825,'Если у вас крупные кусочки грецкого ореха, то его можно нарезать на более маленькие кусочки про помощи ножа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1825,'Слоеное дрожжевое тесто слегка раскатываем, нарезаем на равные полоски, перекладываем на протвинь, смазываем их взбитым куриным яйцом. Отправляем в разогретую духовку 180°С на 20-25 до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1825,'Спустя 20-25 минут, как только языки дошли до золотистой корочки, достаем и перекладываем на тарелку, смазываем их мёдом и посыпаем грецким орехом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1826,'Креветки разморозить, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1826,'Чеснок и лук очистить и нарезать, выложить на сковороду со сливочным маслом, жарить до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1826,'Добавить креветки, жарить все вместе одну минуту, огонь – сильный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1826,'Влить сливки с солью и перцем. Огонь уменьшить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1826,'Потушить продукты в соусе под крышкой десять минут. Масса должна загустеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Прогреть смесь сливочного и оливкового масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Обжарить креветки со всех сторон, общее время термообработки – от шести до семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Влить жирные сливки с давленым чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Потомить блюдо под крышкой до загустения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Посолить, добавить ломтики голубого сыра, Специи – по желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1827,'Прогревать до расплавления сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Растопить на сковороде сливочное масло, добавить мелко нарезанный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Прогревать до прозрачного состояния чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Влить белое вино.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Прогревать до испарения напитка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Влить сливки, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Довести соус до кипения, всыпать очищенные креветки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Потушить все вместе на тихом огне восемь или девять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Креветки вынуть, соус прогревать до уменьшения объема наполовину.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1828,'Вернуть морепродукты на сковороду. Прогреть две минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Вымыть брокколи, разобрать на соцветия, положить в кипящую воду с солью на семь или восемь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Откинуть капусту на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Растопить на сковороде сливочное масло, обжарить нарезанный чеснок до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Всыпать очищенные размороженные креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Влить сливки с солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Все вместе потушить три или четыре минуты, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Добавить тертый сыр, томить блюдо еще три-четыре минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1829,'Выложить капусту на тарелки порционно, сверху – соус с креветками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Пасту отварить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Разогреть на сковороде оливковое масло, обжарить нарезанный чеснок. Продукт удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'В чесночное масло выложить размороженные чищеные креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Жарить две минуты, переложить в отдельную емкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'В ту же сковороду влить жирные сливки, посолить, добавить сушеный базилик.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Томить соус на тихом огне, он должен загустеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Вернуть креветки, прогреть еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1830,'Выложить пасту. Готовить две минуты на тихом огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1831,'В миску сложить очищенные бананы разломав их на куски. Измельчить до состояния пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1831,'В отдельной миске взбить яйца в пену. Добавьте сахар, корицу и ванильный сахар, снова взбейте до растворения сахара. Соединить яичную смесь с банановым пюре и взбить. Затем добавить муку и разрыхлитель, перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1831,'В сотейник налейте много растительного масла, чтобы пончики при жарке были покрыты маслом до середины. Хорошо разогрейте',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1831,'В пиалу налить воду, в ней мы будем смачивать руки, чтобы тесто не прилипало к рукам. Итак, смачиваем руки формируем из теста лепешку и отправляем в сотейник. Обжариваем на среднем огне с двух сторон до золотистого цвета (занимает около 3 минут для каждой стороны).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1832,'В пиалу налить горячую воду, добавить мед и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1832,'Хурму очистить от кожуры и косточки, нарезать дольками и отправить в пиалу с медом. Добавить здездочки бадьяна и 1/2 ч.л. ванильного сахара с кусочками ванили – перемешать. Выложить хурму на противень, застеленный фольгой, добавить кусочки сливочного масла. Ставим противень в разогретую духовку до 190 градусов на 20 минут. Спустя 20 минут достаем из духовки и немного остужаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1832,'В греческий йогурт добавить корицу и 1/2 ч.л. ванильного сахара с кусочками ванили – перемешать. Фисташки нарезать крупными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1832,'В бокал или креманку выкладываем йогурт, поверх хурму и посыпает нарезанными фисташками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'Рис отварить до готовности (варим в пропорции 1 (порция риса) :2 (пропорция воды)).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'Воду доводим до кипения. Куриное филе нарезать слайсами толщиной 1 см, в кипящую воду отправляем порционно кусочки филе (по 1-2 штуки за раз), варим по 5 минут. Вынимаем, остужаем и нарезаем кубиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'В пиалу разбить яйца, добавить соль и взбить до однородности. Разогреваем сковороду с оливковым маслом, обжариваем на сильном огне в течении 2 минут, перемешивая. Готовый омлет перекладываем в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'На сковороде, где готовился омлет разогреваем еще немного оливкового масла. Обжариваем курицу на сильном огне до слегка золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'Добавить в сковороду отваренный рис, перемешать, влить соевый соус. Ставим на сильный огонь, готовим 5 минут, перемешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1833,'Спустя 5 минут добавить очищенные креветки (мелкие креветки отправить целыми, большие нарежьте кусочками) и зеленый горошек, готовим еще 2 минуты, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1834,'В миску положить творог, добавить фету, сметану, яйца, рубленый укроп, перец и пропущенный через пресс чеснок. Хорошо перемешать начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1834,'Слоеное тесто немного раскатать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1834,'Распределить ровным слоем начинку на тесте, оставляя 3-4 см с одного края. Аккуратно свернуть рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1834,'Рулет свернуть в улитку, выложить в форму для выпечки застеленную пекарской бумагой. Сделать надрезы на рулете поперек, на рулетики.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Очистите репчатый лук и нарежьте мелким кубиком. Затем в кастрюле на 3 л разогрейте 20 гр сливочного масла, обжарьте лук в течении 7 минут на среднем огне, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Нарежьте морковь мелким кубиком и сельдерей небольшими кусочками. Нарезанные овощи отправляем в кастрюлю с луком, обжариваем 10 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Чили нарезать мелкими кусочками, отправить в кастрюлю и готовить еще 3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Залейте 2 л воды, добавьте лавровый лист. Приправьте солью, перцем и паприкой. Всыпьте чечевицу. Доведите суп до кипения, снимайте пену и варим 5 минут. Затем снимаем с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Готовим заправку. Разогрейте сливочное масло, чтобы полностью растаяло (15 гр), добавьте белый винный уксус и дижонскую горчицу – перемешать до однородности. Греем 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Чоризо нарезать тонкими колечками, отправить на сухую сковороду и обжарить на сильном огне в течении 5 минут, перемешивая. Затем отправить чоризо в кастрюлю, но при этом в сковороде оставить немного выделившегося масла',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1835,'Помидоры нарежьте кружками (потолще). Выложите ломтики помидоров в горячее масло от чоризо, посыпьте небольшим количеством сахара и обжарьте помидоры с обеих сторон по 2 минуты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1836,'Сначала приготовить люля: положить в фарш измельченный лук, посыпать солью и перцем, полить уксусом. Перемешать и поставить мариноваться минут на 80. Придать фаршу форму колбасок, на противень постелить фольгу и положить люля, сверху смазать маслом. Выпекать минут 20 при температуре 220 градусов, пока не появится румяная корочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1836,'Во время маринования и жарки люля, порезать помидоры и огурцы соломкой. Нашинковать капусту и слегка помять. Красный репчатый лук порезать на тонкие полукольца. Затем сделать чесночный соус: в йогурт добавить прессованный чеснок, посыпать перцем, можно по желанию насыпать щепотку зиры, растертой ладонью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1836,'Намазать соус на лаваш, положить люля-кебаб -1 или 2 штуки, добавить овощи по вкусу, сверху снова смазать соусом, лаваш завернуть. Подавать к столу шаурму с люля-кебаб и овощами в чесночно-йогуртовом соусе сразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Рукколу промыть, обсушить, выложить на блюдо горкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Плод авокадо нарезать кубиками, косточку удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Очистить и обжарить небольшие креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Черри разрезать на две части, соединить с креветками и зеленью. Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'В оливковое масло влить немного меда, лимонный сок, соевый соус, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Полить готовой заправкой салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1837,'Натереть сыр, посыпать закуску сверху, украсить очищенными кедровыми орешками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'В оливковое масло влить бальзамический уксус, поперчить, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Свежий огурец нарезать полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Удалить с помело пленки, порвать мякоть кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Креветки залить кипятком на три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Очистить, обжарить до золотого оттенка, соль и молотый перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Продукты перемешать. Добавить рукколу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1838,'Полить соусом, посыпать салат тертым сыром «Пармезан».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Картофель крупно нарезать, переложить в кастрюлю, залить водой. Довести до кипения и варить до готовности около 20 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Лук и морковь нарезать кубиками, чеснок измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Разогреть сковороду на сильном огне, влить оливковое масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Добавить морковь, готовить 2 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Добавить фарш, готовить 5 мин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Посолить, добавить розмарин и тимьян, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Добавить замороженный горошек, перемешать, убавить огонь на средний, готовить до тех пор, пока соус не загустеет.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'Сыр натереть на мелкой терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'К картофелю добавить яичный желток, сыр, соль по вкусу и молоко.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1839,'В форму для выпечки выложить мясную начинку и разровнять.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Креветки очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Обжарить на раскаленном кунжутном масле до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Перепелиные яйца отварить в течение пяти или семи минут, очистить, разрезать на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Помидоры черри разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Перемешать черри с рукколой, листьями салата «Айсберг», добавить креветки и нарезанные дольками яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1840,'Соединить молотый перец с солью, лимонным соком, медом, горчицей, маслом. Полить готовым соусом салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Креветки разморозить. Если времени мало – продукт можно залить горячей водой на пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Рукколу и листья базилика промыть и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Полить бальзамическим уксусом, оливковым маслом, соль и молотый перец – по вкусу. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Черри вымыть, обсушить, разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Нашинковать полукольцами красный лук, поломать руками или нарезать сыр «Моцарелла».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Креветки обжарить на сковороде до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1841,'Посолить и поперчить продукт. Перемешать ингредиенты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Креветки разморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Сыр «Пармезан» натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'В оливковое масло влить лимонный сок, положить французскую горчицу, перец, соль, майоран, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Рукколу порвать руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Залить частью соуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Помидоры разрезать пополам и выложить на зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Сыр «Фета» нарезать кубиками, добавить в салат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Креветки очистить, нарезать шампиньоны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Продукты обжарить на масле и выложить в общую массу горячими.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1842,'Полить соусом, посыпать тертым сыром «Пармезан».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Креветки выложить в кипящую воду, варить пять минут, удалить панцири и головы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Сладкий перец нарезать полосками, маслины и помидоры черри – половинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Листья базилика и рукколу выложить на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Приготовить соус из оливкового масла, лимонного сока, пряностей, сладкой горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Ингредиенты перемешать, добавить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1843,'Добавить остальные продукты, перемешать еще раз, украсить готовыми креветками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Креветки очистить, посолить и поперчить по вкусу, побрызгать лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Оставить продукт на пятнадцать минут для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Влить немного оливкового масла на сковороду, добавить мелко нарезанный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Выложить креветки вместе с маринадом, жарить несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Нарезать манго и яблоки крупными дольками, очищенные огурцы – соломкой, черри – половинками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Рукколу хорошо промыть и обсушить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Выложить на плоское блюдо по кругу овощи и фрукты, в центр – зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1844,'Блюдо полить бальзамическим уксусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Духовой шкаф заранее прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Тыкву очистить, нарезать квадратиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Перемешать молотый перец с солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Перемешать с рубленым чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Влить масло, бальзамический уксус, ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Промазать тыкву.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'На столе раскатать лист фольги, выложить тыкву, завернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Время запекания – полчаса, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Фольгу развернуть, прогреть овощ до корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Отдельно, на сковороде, обжарить тыквенные семечки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Поместить рукколу в салатницу вместе с тыквой, посыпать сушеными травами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Залить соусом из оливкового и тыквенного масла, бальзамического уксуса, перца и соли.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1845,'Добавить креветки, семечки, соус. Перемешать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Нарезать репчатый лук, побрызгать лимонным соком, оставить для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Куриные грудки обвалять в любимых специях, сбрызнуть растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Сковороду смазать подсолнечным маслом, обжарить куриные грудки до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Готовое мясо нарезать тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Свежие огурцы порезать дольками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Очистить грейпфрут от кожуры, мякоть нарезать кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Выложить на тарелки листья шпината, далее – все ингредиенты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Побрызгать заправкой из апельсинового сока, подсолнечного масла, меда, чеснока и «Вустерского» соуса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1846,'Сверху посыпать кунжутными семечками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'Кедровые орехи обжарить на сковороде без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'Очистить грейпфрут и авокадо, кусочки перемешать, полить шампанским, дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'В смесь добавить веточки базилика, листочки шпината.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'Смесь выложить в тарелки порционно или в общую салатницу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'«Бри» тонко нарезать, украсить сыром салат. Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1847,'Посыпать блюдо кедровыми орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'Сначала приготовим маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'Далее нужно сделать небольшую подготовку мяса.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'Далее мясо нарезаем на порционные кусочки поперёк волокон. Уже потом на каждом кусочке делаем надрезы с каждой стороны, это нужно для того, чтобы специи и маринад хорошо впитались в мясо.. Далее солим, перчим и добавляем смесь приправ для мяса по вкусу. Все это хорошо втираем в мясо с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'Уже после этого можно замариновать мясо, лично я его покрывал мясо маринадом при помощи кондитерской кисти. С каждой стороны мясо нужно помазать маринадом. Оставляем мариноваться на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'В это время картофель нарезаем на дольки и перекладываем в миску. Далее солим, перчим, добавляем сушеный укроп и красный перец, а также растительное масло. Все хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'На противень расстилаем фольгу блестящей стороной во внутрь (к себе), на эту фольгу укладываем мясо, и все хорошо заворачиваем. Далее ещё раз отрываем фольгу, в неё укладываем картофель, все хорошо заворачиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1848,'Все это отправляем в духовку при 200°C. Лично у меня все приготовилось почти за 2 часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Картофель чистим и варим его до готовности. Сливаем воду, добавляем небольшой кусочек сливочного масла и солим по своему вкусу. Разминаем вареный картофель в пюре. Добавляем в пюре 4 куриных яйца и хорошо перемешаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Нарежем репчатый лук. Свежие грибы нарезаем небольшими кусочками произвольной форму. В сковороду наливаем немного растительного масла и жарим грибы с луком до готовности, солим жареные грибы по своему вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Свежий укроп мелко нарезаем. А плавленый сырок натираем на крупной терке в отдельную миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Теперь смажем растительным маслом форму для выпечки, у меня прямоугольная форма 20 на 30 сантиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Половину картофельного пюре выложим в смазанную форму разровняв его. В оставшуюся половину пюре я добавляю натертый плавленый сырок и хорошо перемешиваю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'На пюре в форме выкладываем жареные грибы и посыпаем их нарезанным свежим укропом. Сверху равномерно раскладываем вторую половину пюре с сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Разбиваем в миску 1 куриное яйцо и добавим в него соли по своему вкусу. Хорошо размешаем яйцо и смажем им нашу картофельную запеканку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1849,'Готовим картофельную запеканку с грибами в духовке примерно минут 40 при температуре в 190 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1850,'Измельчить салатные листья, порезать апельсин и яйца. Выложить ингредиенты в емкость, заправить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'Измельчаем крабовые палочки',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'На терке натираем свёклу, сыр и яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'Для заправки смешиваем сметану и майонез. Добавляем в салат и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'Добавляем измельченный чеснок и при необходимости солим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'Салат выкладываем в кулинарное кольцо, слегка утрамбовываем ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1851,'Рекомендую отправить салат на пару часов в холодильник.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Грейпфрут очистить от прожилок, пленок и кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Мякоть нарезать тонкими кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Точно так же нарезать томаты, мягкий сыр – кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Промыть оливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Выложить в салатницу слоями грейпфруты, томаты и сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Слои чередовать, оливки – сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Приготовить соус из оливкового масла, душицы, соли, молотого перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Блюдо заправить полученной смесью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1852,'Охладить, подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Разогреть оливковое масло на сковороде, обжарить мелкие креветки, всыпать по вкусу соль и молотую паприку. Общее время приготовления – не более семи минут. Продукт остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Авокадо разрезать пополам, вынуть косточку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Мякоть нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Приготовить соус из «Кетчупа» и легкого майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'В салатницу выложить промытые и обсушенные листочки рукколы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'В центр налить столовую ложку майонезной заправки и выложить часть готовых креветок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Вокруг, в произвольном порядке, выложить кусочки авокадо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Любой плод цитрусовых очистить от кожуры, разделить дольками, удалить пленки и прожилки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1853,'Выложить также в любом порядке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Перемешать соль с молотым перцем и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Обвалять в этой смеси лососевое филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Выложить в емкость для пропитывания, побрызгать оливковым маслом и винным уксусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Оставить на час или два.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Очистить грейпфрут от кожуры, мякоть разделить на дольки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Чеснок покрошить, нарезать тонкими дольками лимон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Салат руккола промыть, обсушить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Мелко нарезать лук шалот.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Готовую рыбу нарезать максимально тонкими полосками, выложить на тарелки, посыпать шалотом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Украсить ломтиками лимона, оливками, долькам грейпфрута, рукколой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1854,'Полить маринадом, посыпать тертым сыром «Пармезан».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Свежие огурцы мелко нарезать, посолить и оставить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Выделившийся сок слить в отдельную мисочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Очистить грейпфрут, мякоть нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Свежий лимон тонко нарезать вместе с кожурой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Приготовить заправку из лимонного сока, сливок, майонеза на оливковом масле, перец и соль – по вкусу, добавить томатную пасту, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1855,'Заправить салат, блюдо охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Приготовить тесто из муки, соли, сахарного песка, кусочка твердого натертого сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Ингредиенты быстро растереть руками до получения крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Вбить сырое куриное яйцо, быстро замесить тесто, скатать в шар и оставить на некоторое время.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Смазать форму для десерта топленым сливочным маслом, посыпать сахарным песком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Сочные яблоки нарезать четвертинками, выложить по кругу в два слоя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Первый слой посыпать сахарным песком и посыпать кусочками масла, второй слой – процедуру повторить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Форму с яблоками поставить в духовой шкаф, печь при температуре 200 градусов, время – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Тесто раскатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Накрыть лепешкой запеченные яблоки, заправить бортики по кругу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Наколоть массу в нескольких местах, чтобы выходил пар.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1856,'Печь пирог еще около получаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Быстро приготовить тесто из молока, яиц, сахарного песка, ванилина, муки, постного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Выложить в сотейник кусочек сливочного масла, добавить сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Массу растопить, она должна приобрести карамельный оттенок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Вымыть яблоки, удалить сердцевину, мякоть нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'В силиконовую форму вылить карамельную массу из сотейника.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Выложить яблочные дольки, залить полужидким тестом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1857,'Время выпекания тарта – полчаса, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Готовое слоеное тесто разморозить при комнатной температуре в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Яблоки нарезать дольками, сердцевину вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Форму для выпекания накрыть тестом, выложить начинку, присыпать молотой корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Отдельно приготовить заливку: взбить молоко со сметаной, сахаром, ванилином, яйцом и порошком для растворимого ванильного пудинга.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Массу вылить на яблоки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1858,'Выпечь тарт при температуре 200 градусов до появления румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Натереть охлажденное сливочное масло, перемешать с сахаром, солью, мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Ввести ледяную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Готовое тесто положить на полчаса в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Выдавить сок из лимона, полить очищенное и нарезанное кусочками яблоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Посыпать тростниковым сахаром, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Сырые куриные яйца взбить, смазать форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Раскатать тесто, накрыть начинку, бортики завернуть при помощи вилки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Взбить в пену белки, смазать тесто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Присыпать сахарным песком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Сделать отверстие для выхода пара в центре.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1859,'Выпечь до получения корочки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Яблоки нарезать тонкими пластинками, кожуру удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Форму смазать маслом, выложить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Приготовить тесто из муки, разрыхлителя, сахарного песка, соли, ванилина, корицы, воды, растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Сначала перемешать сухие компоненты, затем жидкие.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Влить жидкую массу в сухую.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Тесто перебить венчиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1860,'Залить начинку, время выпекания – от тридцати до сорока минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Куриные яйца охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Сливочное масло довести до комнатной температуры, взбить с сахарным песком в воздушную массу, она должна побелеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Ввести желтки, просеять крахмал, массу продолжать взбивать при помощи миксера, скорость – средняя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Всыпать порциями просеянную муку. Тесто должно загустеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Поставить в холод на пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'У яблок вырезать сердцевину.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Тонко нарезать слайсами. Посыпать сахаром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Собрать пирог: распределить руками тесто по стенкам и дну формы. Присыпать панировкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Выложить яблоки равномерно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Печь 45 минут при температуре 189 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Приготовить массу из белков, сахара, лимонной кислоты и ванильного сахара.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Меренгу взбить миксером, время – семь минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1861,'Выложить на пирог ложкой, запечь в течение десяти минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Приготовить тесто из муки, 130 г мягкого сливочного масла, сахара, соли, яиц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Ингредиенты растереть вручную до получения крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Нарезать плоды яблок кубиками, перемешать с ванилином из пакетика и обычным сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Растопить 20 г сливочного масла в сотейнике, потушить яблоки в течение десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Выложить тесто в форму, распределить его ровным слоем по дну и бортикам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Выложить начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1862,'Время выпекания – от двадцати до двадцати пяти минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1863,'В миске перемешиваем творог с сахаром, после добавляем повидло или джем. Все хорошо перемешиваем до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1863,'(Можно не делать) Взбиваем куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1863,'Лаваш нарезаем на равные части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1863,'На подготовленный лаваш укладываем 1 ст.л. начинки, заворачиваем края с 2 боков, и с 1 края, где у вас лежит начинка, заворачиваем в конверт. Я сделал так, немного завернул в конверт, и часть лаваша, которая осталась, обрезал. И в эту обрезанную часть снова положил начинку и завернул в конверт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1863,'(Можно не делать) Каждый конвертик смазываем взбитым куриным яйцом, и отправляем в разогретую духовку при 180°C на 10 минут. Все готово.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'С апельсина снять цедру и выжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'В миску вбить яйца, добавить сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Добавить растопленное сливочное масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Добавить апельсиновую цедру и сок, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Добавить половину муки, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Добавить оставшуюся муку и разрыхлитель, перемешать до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Форму для выпечки смазать маслом и влить готовое тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1864,'Дать кексу остыть в форме, и затем вытащить его и подавать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Прогреть в сотейнике сахарный песок, помешивать, пока не образуется карамель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Добавить сливочное масло, перемешать. Масса должна быть густой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Вылить ее на коврик из силикона тонким слоем, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Поломать, измельчить блендером, должна получиться карамельная пудра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Яблоки очистить, удалить сердцевину с семечками, мякоть нарезать слайсами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Посыпать дно разъемной формы карамельной крошкой, выложить слайсы, посыпанные сахаром, в два слоя внахлест.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Насыпать крошку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Операцию повторить несколько раз, пока не закончатся ингредиенты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Сверху должна быть крошка из карамели.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Время выпекания – сорок минут, температура – 150 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Форму поставить на противень, сахар может вытечь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Общее время выпекания зависит от толщины яблочной нарезки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1865,'Плоды должны стать мягкими, верхний слой – полупрозрачным.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1866,'Почистить картофель и лук. Натереть лук в большую емкость. Картофель натереть на терке, добавить яйцо, посолить. Все перемешать, насыпать муку и снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1866,'Разогреть немного масла на сковороде, с помощью лопатки положить картофельную массу. Обжарить со всех сторон. К столу подавать с любым соусом, употреблять в пищу деруны в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Ошеек, окорок или кусок от тазобедренного отруба хорошо промыть и обсушить салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Приготовить маринад из разведенной в воде соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Поместить говядину в рассол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Отдельно приготовить другую жидкость: вода, душистый перец, лавровый лист, пряные травы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Довести до кипения, влить в кастрюлю с мясом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Поставить на пять дней в прохладу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Вес куска мяса за это время должен увеличиться на треть от первоначального веса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Рассол можно ввести в ткани при помощи шприца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Мясо нашпиговать пластинками чеснока, нарезанной полосками сладкой морковью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Обвалять в специях, сухих травах.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Примерный набор: сухая морковь и лук, паприка, кунжутное семя, лавровый лист, травы, перец.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Другой способ панировки – обмазать кусок тестом, приготовленным из ржаной муки и воды.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Поместить продукт в форму, поставить в духовой шкаф на два часа.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1867,'Первоначальная температура – шестьдесят градусов, через полчаса – восемьдесят, далее – сто десять.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Промыть кусок телятины, обсушить полотенцем, удалить жилы и пленки, срезать лишний жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Сделать небольшие прорези, наполнить пластинками чеснока, брусочками моркови – по желанию. Овощную нарезку вставлять по лезвию ножа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Говядину хорошо натереть ароматными травами, молотым перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Смазать постным маслом, посыпать рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Дать полежать полчаса для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Выложить продукт в чашу мультиварки, выставить режим «Тушение» на три часа, готовить под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'Несколько раз кусок перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'В емкость можно влить немного сухого вина.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1868,'В конце запекания выставить режим «Выпечка» на двадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Говядину промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Натереть продукт солью и перцем, пряностями, любимыми специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Сделать надрезы, заполнить рубленым чесноком и зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Обмазать кусок растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Положить продукт в холодильник на ночь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Расстелить два слоя фольги на противне, выложить согревшееся до комнатной температуры мясо, кусок плотно упаковать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'Время запекания – два часа, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1869,'За полчаса до готовности буженину раскрыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Мясо вымыть, промокнуть салфетками, посолить, натереть молотым перцем, кориандром, травами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Репчатый лук очистить, нарезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Половину продукта выложить в рукав.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Разместить мясо на «подушке» из репчатого лука, сверху и с боков выложить оставшийся лук вместе с лавровым листом и горошинами перца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Края рукава завязать или закрепить клипсами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Поставить на ночь в холод для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Вынуть рукав из холодильника, влить воду, бульон или вино.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'Рукав снова завязать, выложить на противень, запечь при температуре 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1870,'На пакете сделать отверстия для выхода пара. Время приготовления – два часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Хорошую говядину вымыть и обсушить бумажными салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Морковь очистить, нарезать крупной соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Очистить чеснок, пропустить через пресс, выложить в пиалу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Добавить молотый перец, соль, измельченный лавровый лист, нерафинированное оливковое масло. Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Еще одну головку чеснока очистить и нарезать пластинками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Нашпиговать мясо вместе с морковью и целыми горошинами перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Обмазать кусок соусом, выложить в холод на шесть часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Мясо завернуть в несколько слоев фольги, полить остатками маринада.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Завернуть в форме конфеты. Время запекания – два часа, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1871,'Перед окончанием тушения фольгу приоткрыть для образования поджаристой корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Плоский кусок говядины натереть специями, пряностями, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Сухофрукты промыть, ошпарить, промокнуть салфетками. Часть нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'В мясе сделать надрезы, нашпиговать черносливом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Остальной продукт разместить поверх говядины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Полить сухим вином.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Завернуть рулетом, перевязать кулинарной нитью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1872,'Выложить в форму для запекания, накрыть листом фольги, поставить на два часа в духовой шкаф. Температура запекания – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Морковь очистить и промыть, нарезать кружками, выложить на смазанную маслом фольгу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Репчатый лук очистить, разместить головки на бумаге целиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Зубчики чеснока разрезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Очистить яблоки, удалить сердцевину, мякоть нарезать пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Говядину вымыть, сделать надрезы, нашпиговать кусок яблоками, чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Поверхность хорошо промазать майонезом, завернуть в двойные слои фольги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1873,'Температура запекания – 200 градусов, время – два часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'Грибы промыть, удалить потемневшие участки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'Нарезать пластинками, жарить на постном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'Влить молоко, огонь убавить. Грибы потушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'Отдельно взбить куриные яйца с молоком, солью, молотым перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'Залить грибы, оставить на пять минут на плите под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'При подаче посыпать рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1874,'По желанию в омлет можно добавить нарезанный бекон, ветчину, куриное мясо, томаты, сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1875,'Телятину нарезать кусками толщиной в полтора сантиметра, отбить молотком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1875,'Приготовить смесь из яиц, молока, специй, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1875,'Отбивные погрузить в яичную смесь, обкатать в панировочных сухарях, обжарить в разогретом оливковом масле до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1875,'Духовой шкаф нагреть до средней температуры, запекать блюдо в течение пятнадцати минут. Мясо должно стать мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Телятину нарезать кусками, отбить и натереть специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Отдельно взбить куриные яйца, добавить воду, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Смешать панировочные сухари с мукой в равных пропорциях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Прогреть растительное масло на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Куски мяса по очереди погрузить в яйца, в панировку с мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1876,'Жарить на среднем огне с двух сторон до получения румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'Мясо нарезать кусками, посыпать специями, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'Обмакнуть во взбитые яйца, запанировать в сухарях, обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'На готовые куски выложить нарезанные томаты и давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'Посыпать сыром, прогреть в микроволновке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'На том же масле, на котором готовилось мясо, обжарить хлеб.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1877,'На гренки выложить мясо, посыпать рубленой зеленью и сразу подать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1878,'Телятину нарезать кусками, отбить, натереть специями, обмакнуть в яичную смесь с водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1878,'Приготовить панировку из сухарей и муки, запанировать мясо, обжарить до готовности на подсолнечном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1878,'Выложить на готовые ромштексы нарезанный сладкий болгарский перец, посыпать тертым сыром «Моцарелла».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1878,'Прогреть, подать к столу теплым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1879,'Мясо отбить, обвалять в специях, полить оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1879,'Дать полежать несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1879,'Выложить продукт на гриль, жарить по семь минут с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1879,'Несколько раз в процессе приготовления полить мясо минеральной водой или маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1880,'Взять большую сковороду, нагреть сливочное или оливковое масло на небольшом огне. Положить на сковороду грибы и чеснок. После того как чеснок станет прозрачным, влить сливки и горчицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1880,'Сделать огонь, как можно меньше, и тушить приблизительно 5 минут. Выложить сверху куриные грудки, обжаренные на гриле, посыпать курицу-гриль в сливочно-горчичном соусе петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Нарезать морковь, корень сельдерея, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Овощи перемешать с сахарным песком, солью, молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Поломать руками листья лавра, добавить в овощную смесь вместе с розмарином, петрушкой и оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Промыть говяжью вырезку, обсушить, оставить продукт в маринаде на несколько часов или на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'С вырезки удалить овощи, они могут подгореть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Мясо обвалять в муке, обжарить до появления корочки на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Жарить на сале или на оливковом масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1881,'Переложить мясо в форму, поставить в духовой шкаф на полчаса, температура приготовления – 220 градусов. Готовность проверить зубочисткой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1882,'Приготовить маринад из растительного масла, меда, апельсинового сока, соевого соуса, молотого мускатного ореха, соли, перца, прованских трав.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1882,'Промыть говядину, обсушить и натереть со всех сторон готовым маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1882,'Оставить для пропитывания на два или три часа при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1882,'Налить подсолнечное масло на сковороду, обжарить мясо до получения румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1882,'Фольгу смазать маслом, выложить говядину, завернуть, запечь в духовке в течение сорока или сорока пяти минут, температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Растолочь душистый перец с морской солью, влить виноградное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Готовой смесью натереть говядину, жарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Переложить на блюдо, немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Пропустить чеснок через пресс, перемешать с зернистой горчицей, мясо еще раз натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Выложить кусок в форму, печь при температуре 220 градусов в течение десяти минут, затем температуру понизить до 150 градусов, прогревать полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Побрызгать листья мяты свежим лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1883,'Посыпать зеленью ростбиф, подать с горчичным соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Говяжью вырезку натереть солью, молотым перцем, сушеным розмарином и эстрагоном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Полить кусок соевым соусом, смазать горчицей и медом. Оставить для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Прогреть сковороду, обжарить вырезку на растительном масле до получения румяной корочки, огонь – сильный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Мясо переложить на лист фольги.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Отдельно обжарить целые или нарезанные шампиньоны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Выложить грибы вокруг мяса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Нарезать полукольцами репчатый лук, посолить и поперчить, выложить поверх грибов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1884,'Закрыть продукты сверху вторым листом фольги, прогреть при температуре 200 градусов, время – полчаса или чуть больше.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Кусок говяжьего мяса замочить на три или четыре часа в соевом соусе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Периодически продукт переворачивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Натереть мясо специями, сушеными травами, выложить в заранее прогретую сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Подрумянить со всех сторон, переложить в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Разрезать на четыре части баклажаны, посолить, через десять минут промыть водой, горечь должна уйти.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Сладкий перец разрезать пополам, картофель – крупными кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Полить овощи соевым соусом, по желанию также посыпать специями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Выложить вокруг мяса в ту же форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1885,'Прикрыть емкость фольгой, печь в течение сорока пяти минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Говядину замариновать в специях и приправах на сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Хороший состав для маринада: лимонный сок, перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Жарить на угольном гриле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Сначала температура должна быть максимальной, затем завернуть кусок в фольгу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Томить на среднем огне несколько часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1886,'Рядом с грилем поставить воду с красным сухим вином и розмарином.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'Мясо разморозить при комнатной температуре, натереть солью с перцем, специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'Кусок смазать маслом, жарить на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'Мясо переворачивать щипцами для гриля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'Первые десять минут огонь – сильный, затем – слабый.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'Продукт поливать выделяющимся соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1887,'В конце приготовления сковороду накрыть фольгой, поставить в духовой шкаф на десять или пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'Приготовить маринад из оливкового масла, зернистой горчицы, давленого чеснока, соли, розмарина, перца, соевого или «Вустерского» соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'Смесью натереть телятину, дать постоять два или два с половиной часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'Прогреть духовой шкаф до 250 градусов, запечь мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'Через пятнадцать минут огонь убавить до 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'Мясо смазать остатками маринада, запекать еще полтора часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1888,'За десять-пятнадцать минут до окончания приготовления смазать ростбиф медом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Подогреть воду и молоко до тридцати градусов, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Всыпать дрожжи, оставить на пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Затем всыпать муку, опару поставить в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Через полчаса добавить оставшуюся муку, соль, сахар, топленое масло, ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Тесто должно постоять два часа, каждые полчаса его нужно обминать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Сформовать булочки, выложить на противень, оставить на пятнадцать минут, печь при температуре 200 градусов в течение двадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1889,'Сосиски обжарить на костре или на гриле, отварить или обжарить на сковороде, приготовить в микроволновой печи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1890,'Готовые булочки прогреть в микроволновой печи, разрезать вдоль, удалить мягкую часть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1890,'Приготовить соус из горчицы, майонеза, кетчупа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1890,'Выложить в булочку готовую сосиску, полить соусом и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'В сметану добавить соду гашеную водой, желтки, сахар, ванилин, сушеную цедру апельсинов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'В получившуюся смесь постепенно всыпать муку, тесто должно быть мягким и не липнущим к рукам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Раскатать тесто в пласт толщиной 1-1,5 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Стаканом вырезать кружочки и выложить на противень, застеленный бумагой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Выпекать в предварительно нагретой духовке при 180°С около 15 минут (до зарумянивания).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Готовым пряникам дать остыть и посыпать сахарной пудрой или смазать глазурью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1891,'Глазурь: смешать все ингредиенты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1892,'Баранину можно разрезать на несколько частей. Далее я помещаю ее в кастрюлю и довожу до кипения. В воду добавляем немного соли и лавровый лист. Кипятим примерно 30 минут для того, чтобы выварить запах и размягчить мясо для дальнейшего запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1892,'В это время я нарезаю морковку дольками и лук кольцами. Также нужно подготовить розмарин и убрать жесткие ветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1892,'Когда баранина готова, перекладываем ее в жаропрочную емкость для запекания. Бульон оставляем, так как он нам еще понадобится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'Очищенный арахис промыть, обсушить, выложить на блюдо для микроволновки, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'Жарить при максимальной мощности тридцать секунд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'Процедуру повторить семь-восемь раз. В перерывах продукт помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1892,'Так же раскладываем лук, морковку, солим, перчим, баранину поливаем маслом, добавляем розмарин. Добавляем 1-2 стакана бульона к баранине. Закрываем плотно фольгой. Выпекаем при температуре 210°С в течении 1,5 часа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1893,'Смазать формочку для выпекания маслом, распределить в ней грецкие орехи, клюкву, полстакана сахара и поместить в духовку, разогретую до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1893,'Смешать сахар, яйца, муку и сливочное масло. Залить тестом клюкву и выпекать приблизительно 50 минут. Перед подачей на стол простой пирог с клюквой слегка остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1894,'Готовые булочки разрезать вдоль, выложить листья свежего салата и сосиски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1894,'Выложить закуску в микроволновую печь на две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1894,'Свежий огурец и редиску нарезать тонкими ломтиками, украсить сосиску, сверху выдавить кетчуп, горчицу, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Репчатый лук покрошить и обжарить на растительном масле сковороде до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Переложить на противень, посушить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Добавить к луковой обжарке чипсы, поломанные в крошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Венские сосиски обжарить на гриле или подогреть на сковороде, выложить в разрезанные булочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Обмазать начинку горчицей, кетчупом или майонезом, посыпать луком с чипсами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1895,'Украсить кружками маринованных огурцов и свежих помидоров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Сосиски прогреть или обжарить на гриле, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Лаваш нарезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Одну сторону намазать горчицей, майонезом или кетчупом, посыпать нарезанной пекинской капустой, выложить помидоры, нарезанные кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Сверху овощной подушки выложить сосиски, рубленый зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Свернуть лаваш рулетом, прогреть закуску на сковороде или в микроволновой печи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1896,'Другой вариант – обжарить на гриле до корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1897,'Мелко порубить свежую зелень, перемешать с нарезанным репчатым луком и квашеной капустой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1897,'Побрызгать смесь растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1897,'Готовые булочки разрезать вдоль пополам, выложить начинку на одну сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1897,'Сосиски отварить или обжарить, поместить поверх капустной смеси.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1897,'Закуску полить майонезом или кетчупом с горчицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Сливочное масло прогреть до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Сухофрукты промыть проточной водой, перемолоть при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'В масло добавить сахарный песок, добавить ванилин и молотый изюм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'В сотейник налить воду, прогреть до семидесяти градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Всыпать соль, перемешать до растворения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Овсяную муку всыпать в масляную смесь, долить соленую воду, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Влить погашенную лимонным соком соду, всыпать пшеничную муку, замесить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Массу раскатать скалкой тонким слоем, вырезать кружки при помощи стакана или формы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1898,'Выложить печенье на противень, смазанный маслом, печь изделия в течение десяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Растворить соль в теплой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Отдельно соединить мед с овсяной мукой и подсолнечным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Влить солевой раствор, всыпать разрыхлитель, перемешать ингредиенты до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Добавить рубленые орехи, цукаты, сухофрукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Сформовать кружки, изделия выложить на противень, смазанный маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1899,'Выпекать блюдо при температуре 200 градусов, время – от десяти до двенадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1900,'Арахис очистить, промыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1900,'Выложить на блюдо для микроволновой печи, обжарить продукт семь или восемь раз по тридцать секунд. Мощность – максимальная.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1900,'Орехи перемешивать в перерывах между обжарками, продукт не должен подгореть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1900,'В конце приготовления оставить ядра в печи на десять минут. Снять шелуху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1900,'Перемешать ядра с сахарной пудрой, поставить в печь на тридцать секунд. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'В конце оставить орехи на десять минут в печи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'Закуску выложить в вазочку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1901,'Для приготовления орешков можно использовать морскую соль, а чтобы она лучше прилипла – сбрызнуть продукт растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Налить в емкость воду, добавить соль и мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Поставить в микроволновую печь на одну или две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'В готовый сироп выложить очищенный арахис, прогреть в микроволновке еще две минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Воду слить, выложить половину орехов на тарелку с пергаментом в один слой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Поставить в микроволновку еще на две минуты, мощность – максимальная.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Орехи вынуть, перемешать, прогреть еще две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Обжарить еще раз до образования золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1902,'Вторую часть продукта приготовить аналогично.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1903,'Арахис в скорлупе замочить на полчаса в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1903,'Обсушить полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1903,'Выложить на блюдо для микроволновки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1903,'Перемешать, довести до готовности за тридцать секунд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1904,'Взбиваем 1 куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1904,'Посыпаем стол мукой, чтобы тесто к нему не прилипло. Раскатываем слоеное тесто, далее на раскатанное слоеное тесто укладываем полоски бекона. Заворачиваем в рулет. И после этого нарезаем на маленькие рулетики, перекладываем на противень с подложкой из силиконового коврика для выпечки (или пергамента). Уложить «Улитки» нужно на бок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1904,'Смазываем «Улитки» взбитым куриным яйцом, и отправляем в разогретую духовку до готовности, до золотистой корочки. У меня «Улитки» приготовились в духовке за 30 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1904,'Спустя 30 минут, все готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1905,'Мясо моем, обсушиваем бумажным полотенцем, отрезаем сухожилия, жилки и тд. Далее нарезаем на порционные кусочки, перчим, посыпаем приправой для мяса и красным молотым перцем, все по вкусу. Убираем в сторону на 20 минут, чтобы мясо слегка пропиталось приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1905,'Спустя 20 минут каждый кусочек свинины оборачиваем в полоску бекона и перекладываем на противень. У меня получилось так: было всего 8 полосок бекона, тем самым у меня получилось 8 штук свинины в беконе, часть свинины, которая осталась, я просто запек в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1905,'Отправляем в разогретую духовку до готовности примерно на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1906,'Готовые жареные орехи очистить от шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1906,'Приготовить глазурь из кокосового молока и сахарного песка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1906,'Смесь прогреть до загустения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1906,'Залить арахис остывшим сиропом, посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1906,'Подсушить на силиконовом коврике в течение суток.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Плоды перебрать, удалить испорченные.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Высыпать в воду. Те каштаны, которые всплывут, в пищу не использовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Отобранные плоды вымыть щеткой и обсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Сделать надрезы на скорлупе в виде крестика, чтобы при термообработке они не взорвались.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Высыпать на сковороду с толстым дном, поставить на огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Накрыть смоченной водой салфеткой. Время приготовления – двадцать минут, жарить под крышкой, несколько раз встряхнуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1907,'Кожица должна потемнеть, салфетку убрать, плоды прогреть на пару.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1908,'Смешать мед и соевый соус, добавить прессованный чеснок, кунжут и имбирь. На противень уложить, как можно плотней, ножки, полить маринадом, поместить в духовку, разогретую до 175 градусов. Выпекать 40 минут, через 20 минут куриные ножки с медом желательно перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1909,'Перебрать плоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1909,'Вымыть, удалить прожилки, обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1909,'Всыпать плоды в емкость для микроволновой печи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1909,'Присыпать солью, влить горячую воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1909,'Прикрыть емкость пищевой пленкой, поставить в камеру на несколько минут. Мощность – максимальная.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Отобрать целые, неповрежденные плоды. Промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Сделать надрезы острым ножом на каждом плоде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Высыпать продукт на противень, надрезы должны быть вверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Поставить противень, время запекания – от двадцати пяти минут до получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1910,'Плоды всыпать на полотенце, завернуть, оставить на пять минут для пропаривания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Плоды перебрать, выбросить порченые.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Продукт вымыть и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Наколоть вилкой или сделать небольшие надрезы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'В прогоревших углях сделать углубление.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Переложить каштаны, прикрыть углями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Плоды начнут щелкать через десять или пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1911,'Достать их из ямки, выложить на блюдо, укрыть полотенцем на несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Спелые бананы очистить и размять в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Всыпать овсяную муку, мелко нарезанные сухофрукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Тесто столовой ложкой выложить на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Между печеньем оставлять свободное пространство.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Время выпекания в духовом шкафу от десяти до пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1912,'Готовый десерт украсить свежей мятой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1913,'Овсяные хлопья залить кефиром, оставить на полчаса для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1913,'Изюм высыпать в кипящую воду, через двадцать минут жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1913,'Продукт промокнуть бумажной салфеткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1913,'Добавить в кефирную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1913,'Время выпекания печенья – полчаса, температура в духовке – 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1914,'Прогреть сливочное масло, добавить мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1914,'Всыпать муку, сахарный песок, орехи, соль, добавить гашеную соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1914,'Замесить тесто, выложить на застеленный пергаментом противень небольшие лепешки на расстоянии друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1914,'Время выпекания – от десяти до пятнадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1915,'В большую миску выложите мягкое сливочное масло и добавьте сахар. Взбейте миксером до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1915,'Добавьте яйцо, взбейте миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1915,'Просейте какао порошок и лопаткой перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1915,'Просейте частями муку, перемешайте, вымесите тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1915,'Сформируйте печенье любой формы и выложите на противень, застеленный бумагой для выпечки. Выпекайте печенье в разогретой до 180°С духовке 20-25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Залить рассолом овсяную муку',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Влить растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Оставить смесь на десять минут для настаивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Всыпать сахар, добавить соду, погашенную уксусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Замесить тесто, масса должна быть пластичной и густой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1916,'Сформовать печенье, готовить в течение двадцати минут при температуре 180 градусов до получения золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'Сливочное масло прогреть на водяной бане, всыпать корицу, имбирь, влить мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'Всыпать овсяную муку, соль, пекарский порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'В смесь влить подогретую воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'Замесить тесто, оно должно быть однородным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'Выложить печенье ложкой на противень, застеленный пергаментом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1917,'Время выпекания – до пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1918,'Удаляем у голеней косточку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1918,'Добавляем лук, чеснок, черный молотый перец, соль, горчицу, аджику, хмели-сунели и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1918,'Сыр нарезаем на кусочки и вставляем в каждую голень. Маринуем 30-40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1918,'Жарим на углях 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Смешиваем соль,черный молотый перец и копченую паприку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Нарезаем картофель на кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Свиную грудинку нарезаем полосочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Посыпаем картофель и свиную грудинку смесью соли и перцев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Сворачиваем, чередуя свиную грудинку и картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Поливаем растительным маслом и заворачиваем в пергаментную бумагу и фольгу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Жарим на углях 35-45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1919,'Снимаем фольгу и поджариваем на углях до румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1920,'Перемешать в чаше пряные травы и специи для свинины, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1920,'Смазать кусок мяса, побрызгать оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1920,'Проколоть продукт в нескольких местах ножом, накрыть пленкой, оставить в холоде на десять часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1920,'Мясо свернуть рулетом, перевязать нитью, обернуть листом фольги.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1920,'Выложить в мультиварку, выставить режим «Выпечка» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Говяжью вырезку натереть приправами и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Обсыпать кусок поломанным лавровым листом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Сделать «кармашки» острым ножом, наполнить дольками чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Оставить на час для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'В чашу мультиварки влить оливковое масло, выложить мясо, выставить режим «Жарка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Обжарить кусок с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Закрыть крышку и выставить режим «Тушение» на сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'После окончания приготовления не открывать крышку еще полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1921,'Выложить продукт на блюдо, посыпать молотым черным перцем, рубленым чесноком, поставить в холод на два часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Перемешать тертый имбирь с чесноком и горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Грудку индейки посыпать молотым перцем и солью, натереть имбирной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Выложить в пакет, подержать в холоде восемь часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Выложить заготовку в рукав, затем в чашу мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Выставить режим «Выпечка» на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Незадолго до окончания приготовления рукав разрезать, допечь продукт до румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1922,'Оставить в чаше прибора до полного остывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1923,'Протереть творог сквозь сито, положить сметану и тщательно перемешать. Вымыть фрукты, почистить ананас и киви, у клубники убрать листики. Порезать ананас и киви на брусочки, клубнику порезать на 4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1923,'Положить на 1/3 от края блина творожную смесь полоской. Рядом положить фрукты, свернуть блин в плотный рулет. Так же приготовить рулетики из остальных блинов и начинки. На час поместить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1923,'Порезать рулеты на одинаковые кусочки, выложить сладкие роллы с начинкой из творога и фруктов на блюдо, посыпать шоколадом, потертым на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1924,'Всыпать соль в молоко, прогреть в мультиварке в режиме «Молочная каша».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1924,'Довести до кипения, выложить куриное филе, варить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1924,'Выставить режим «Подогрев», добавить свежие травы: розмарин, мяту и чабрец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1924,'Дать постоять два часа при включенной опции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1924,'Мясо вынуть, обсушить, натереть тмином, карри, куркумой, паприкой и красным молотым перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'В куске хорошей свинины сделать надрезы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Продукт натереть солью, посыпать сухим тимьяном и молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Лесные грибы или шампиньоны нарезать, обжарить в мультиварке: режим «Жарка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Добавить к основному продукту сушеную петрушку, любые специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Грибной бульон слить в чашу, оставить несколько грибов, остальными начинить мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Свернуть свинину в рулет, перевязать нитью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Выставить режим «Жарка», влить в чашу масло, обжарить рулет с двух сторон до получения румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Выложить на блюдо, чашу вымыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Влить в емкость еще немного масла, выложить мясо, кусочки бекона, томаты, нарезанные кольцами. Влить грибной бульон.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Выставить режим «Выпечка» или «Мясо» на полтора часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Рулет в процессе приготовления несколько раз перевернуть и полить соком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1925,'Буженину остудить, нить срезать, мясо нарезать пластинами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Сделать надрезы в свиной шейке, заложить в них зубчики чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Посыпать кусок перцем и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Горчицу перемешать с майонезом и сушеным тимьяном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Готовой смесью обмазать кусок мяса, оставить на четыре часа для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Выставить в мультиварке режим «Жарка», обжарить по пятнадцать минут кусок мяса с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Выставить режим «Тушение», запекать свинину в течение трех часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Продукт несколько раз перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1926,'Остудить буженину в мультиварке, положить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Любое мясо посолить, поперчить, посыпать другими приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Сделать проколы, выложить чесночные дольки морковь, нарезанную брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Отдельно перемешать подсолнечное масло с горчицей, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Обмазать смесью мясо, обернуть пищевой пленкой, оставить для пропитывания на час или на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Смазать чашу мультиварки маслом, выложить мясо, выставить режим «Выпечка» на сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Через двадцать минут продукт перевернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Далее – режим «Тушение» на полтора часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1927,'Буженину вынуть, остудить и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'В ступку всыпать горошины душистого и черного перца, кориандр, тмин, сушеный укроп, петрушку и орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'Пряности растереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'Добавить измельченный чеснок, влить растительное масло и соевый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'Натереть мясо полученным маринадом, выложить в миску, посыпать поломанными лавровыми листочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'Полить остатками маринада, накрыть полотенцем, оставить на пять часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1928,'Выставить в мультиварке режим «Выпечка», жарить мясо двадцать минут, затем – режим «Тушение» на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Крупу промыть несколько раз проточной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Залить горох кипящей водой, оставить на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Воду слить, продукт выложить в казан, присыпать пищевой содой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Залить водой полностью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Варить полчаса на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Долить воду, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1929,'Прогревать до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1930,'Замочить горох на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1930,'Свинину нарезать кусочками, обжарить на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1930,'Добавить ломтики моркови и лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1930,'Соль и приправы – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1930,'Горох вновь залить водой, перемешать с обжаркой, тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'Замочить горох на ночь в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'Пересыпать в кастрюлю, залить новой порцией воды с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'Варить на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'Репчатый лук и морковь нарезать и спассеровать на жире из банки с тушенкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'Потомить с мясом на тихом огне до выкипания воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1931,'В готовый горох добавить сливочное масло, обжарку, специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1932,'Горох замочить на ночь, промыть, влить свежую холодную воду, варить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1932,'Посолить в конце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1932,'Копчености нарезать вместе с репчатым луком, обжарить до румянца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1932,'Выложить в сковороду с обжаркой готовый горох.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1932,'Приправить специями, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1933,'Горох промыть, пересыпать в чашу, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1933,'Выставить режим «Тушение» на 110 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1933,'Открыть крышку за двадцать минут до окончания приготовления, посолить, положить масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1933,'Далее вновь тушить под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Промыть продукт до прозрачности воды, выложить в чашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Залить новой порцией воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Соль – по вкусу, выставить режим «Каша» на 95 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Нарезать сало кубиками, жарить до шкварок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Добавить зелень укропа и репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Жарить до готовности лука.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1934,'Перемешать горох с обжаркой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1935,'Горох вымочить, залить подсоленной водой, варить от двадцати пяти до пятидесяти пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1935,'Превратить массу в пюре при помощи блендера, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Смешаем в миске тёплое молоко с тёплой водой. Добавить сахар, соль, дрожжи и хорошо перемешать. Оставить на 10-15 минут, чтобы дрожжи заработали.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Добавить муку, начать замешивать тесто. Я начинаю замешивать ложкой, когда тесто станет тяжело замешивать ложкой, добавить растительное масло, и продолжить замес руками, тесто после ввода масла становится мягким и эластичным.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Тем временем займёмся начинкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Подготовим чесночно-майонезный соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Тесто подошло, перекладывает его на рабочую поверхность, слегка присыпанную мукой. Разделить тесто на 10 равных частей. С каждого кусочка скатать небольшие шарики, защипывая края снизу. Оставить тесто отдохнуть минут на 5.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Раскатать тесто, на небольшие пиццы размером 12,5-15см в диаметре. Переложить на противень на небольшом расстоянии друг от друга. Накрыть полотенцем и дать немного подойти, минут 10.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Сделаем бортики на пиццах. Каждую пиццу смазать томатным соусом, по 1-1,5 ст.л.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Выкладываем начинку: курицу, грибы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Запекать при температуре 200°C 15-20 минут, до румяной корочки, ориентируйтесь на свою духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1936,'Вот и все, наши домашние мини пиццы готовы. Они получаются вкусные, сочные, а тесто очень мягкое.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'Лук нарезать очень мелко.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'В фарш (у меня свино-говяжий) отправить обжаренные овощи, добавить сухари, яйцо, сливки, соль, черный перец, душистый перец. Хорошо вымесить фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'Сформировать небольшие фрикадельки. Руки и поверхность, куда буду выкладывать фрикадельки, смочила немного водой, чтобы фарш не прилипал.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'На сковородку отправить сливочное масло и растительное масло. И жарить фрикадельки до золотистого цвета со всех сторон.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'Приступим к соусу. На ту же сковороду, где жарили фрикадельки, отправить сливочное масло, растопить его. Добавить муку, и слегка поджарить, постоянно помешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1937,'Добавить фрикадельки и тушить ещё 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1938,'Печенку нарезаем мелкими кубиками. Добавляем сметану или майонез, перемешиваем, ставим на 30-60 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1938,'Тем временем займёмся начинкой. Зелёный лук, зелень петрушки и укропа мелко нарезаем, и хорошо перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1938,'Теперь в отдельную посуду разбиваем яйцо, взбиваем венчиком, добавляем муку, снова взбиваем венчиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1938,'Печеночную массу выкладываем на сковородку с разогретым растительным маслом, по 1 ст.л., сверху кладем зелень около 1 ч.л. На зелень выкладываем снова по 1 ст.л. печеночной массы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1938,'Готовые котлеты выкладываем на бумажное полотенце для удаления лишнего жира.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1939,'Миндаль очистить и разделить на половинки.  Развести крахмал холодной водой, тщательно размешать, чтобы не было комочков, дать постоять. Сварить сироп в кастрюле: сахар залить водой, помешивать, довести до кипений, пену снять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1939,'Влить в сироп разбухший крахмал, постепенно, помешивая, затем орехи и кипятить. Варить до тех пор, пока не выпарится лишняя влага, и масса не загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1939,'Выложить массу на противень или на поднос с бортиками, толщина пласта должна быть 2 – 2,5 сантиметра. Дать массе застыть. Готовый рахат-лукум с миндалем порезать на кусочки любой формы, обвалять их в сахарной пудре  и подать на блюде в восточном стиле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'Готовим фарш: пропускаем через мясорубку куриное филе, свинину, лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'В фарш добавляем яйцо, овсяные хлопья, соль, перец, карри, сухой чеснок. Перемешиваем и частями добавляя холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'Оставляем фарш примерно на 20 минут, чтобы набухли овсяные хлопья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'По истечению этого времени фарш отбиваем, чтобы он уплотнился.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'Руки смазываем растительным маслом и формируем колбаски. Выкладываем их на противень, выстеленный фольгой и смазанный растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1940,'Отправляем колбаски в духовку на температуру 180 градусов на 30-35 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Горох несколько раз промыть и замочить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Утром варить в той же жидкости, в которой продукт замачивался. Время – около сорока минут, кашу помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Добавить соль, теплые сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Массу размять при помощи толкушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Морковь, репчатый лук и сладкий болгарский перец очистить, вымыть, нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Потушить с небольшим количеством воды и сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1941,'Пюре из гороха выложить в пиалы, сверху – обжарка. Посыпать рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Варим до готовности картофель и куриные яйца. Остужаем, чистим и нарезаем небольшими кубиками',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Нарезаем куриную печень произвольными, небольшими кусочками. Обжарим печень в сковороде на растительном масле посолив ее по своему вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Репчатый лук нарезаем четверть кольцами, а почищенную морковь натираем на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Обжариваем лук с морковью на растительном масле в сковороде до мягкости и прозрачности лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Соленые огурцы нарежем мелкой соломкой. Зеленый свежий укроп мелко шинкуем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1942,'Смешиваем все продукты в салатнике. Заправляем салат майонезом и посолив по своему вкусу перемешиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1943,'Куриное филе, промыть просушить бумажным полотенцем, далее распластать на 2 половинки, и отбить до 5-7 мм. Солим и перчим по вкусу, и посыпаем приправой для курицы. Убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1943,'Сыр натираем либо на крупной или мелкой терке, перекладываем в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1943,'Чеснок мелко нарезаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1943,'Помидор нарезаем меленьким кубиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1943,'Берем противень и в него укладываем куриное филе, далее куриное филе смазываем майонезом, посыпаем чесноком, далее посыпаем сыром и помидором, отправляем в духовку до готовности, примерно до 40 минут. Все готово.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1944,'Подготовим начинку. Лук мелко нарезать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1944,'Слоеное бездрожживое тесто разморозить и раскатать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1944,'Смазать творожным сливочным сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1944,'Два желтка слегка взбить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1945,'Срезать верхушку у каждого яблока. С помощью ложки удалить семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1945,'Грецкие орехи нарубить ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1945,'Каждое яблоко посыпать корицей, наполнить грецкими орехами, полить медом и сверху положить кусочек сливочного масла. Накрыть верхушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1945,'Поместить яблоки на противень, застеленный фольгой и отправить в разогретую до 200°С духовку минут на 15-20.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1946,'Свинину как всегда нужно промыть, обсушить бумажным полотенцем. Можно обрезать жир. Далее свинину нарезаем на порционные кусочки. Все специи добавим по вкусу. Оставляем на 20 минут. Далее добавляем сок из 1 половинки апельсина, и 1 ч.л. сметаны, перемешиваем. Убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1946,'Половинку, если будет на хватать берем 1 апельсин, нарезаем чуть тонкими кружочками. Шкурку апельсина надо обрезать. ( Я этого не сделал, особой горечи не было)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1946,'В форму для запекания, например противень, выкладываем подготовленный апельсин, на него укладываем подготовленную свинину (можно наоборот) . Далее форму для запекания можно закрыть крышкой от формы, или фольгой. Отправляем в разогретую духовку при 180°С, на 35-40 минут до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1947,'Для коржей растереть до белого цвета сахар с размягченным маслом. В смесь добавить сметану, муку и соду. Тесто хорошо вымесить и разделить на две части, одну оставить первоначального цвета, другую «окрасить» в коричневый цвет с помощью какао. Каждую часть разделить еще на три и раскатать тонкие коржи: по три белых и по три коричневых. Печь при высокой температуре в течение 5 – 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1947,'Приготовить крем. Перемешать молоко, одно сырое яйцо, сахар, ванилин, муку. Варить на тихом огне до загустения. Остудить. Отдельно взбить мягкое сливочное масло и какао. Масляную коричневую массу постепенно, столовыми ложками, вмешать в крем. Торт «Крем-Брюле» собрать, промазывая коржи кремом, чередуя их цвет. Верх также намазать кремом, украсить, как захочется, можно посыпать тертой шоколадной крошкой. Оставить на ночь в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Горох залить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Утром залить свежей водой с солью, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Вымыть репчатый лук и грибы, нарезать продукты мелкими кубиками, обжарить на рафинированном растительном масле. Другой вариант – на сливочном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Перед окончанием приготовления массу посолить по вкусу, посыпать пряностями, рубленым чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Готовую обжарку перемешать с кашей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1948,'Укутать кастрюлю в плед на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1949,'Красную чечевицу быстро промыть при помощи дуршлага.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1949,'Переложить массу в кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1949,'Залить водой, прогревать на тихом огне в течение десяти минут после закипания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1949,'Добавить сливочное масло, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Растопить в сотейнике сливочное масло, добавить сахарный песок, перемешать и дождаться начала плавления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Влить в емкость воду, прогревать, помешивая, до растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Добавить теплые жирные сливки, еще раз перемешать и довести смесь до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Через полминуты огонь выключить, карамель снять с огня и процедить через марлю или сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Отдельно перемешать пшеничную муку с маслом, ледяной водой, солью и сырым яйцом, замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Разделить массу на две части, раскатать каждую в тонкий пласт, вырезать круги, немного превышающие диаметр формы для выпекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Лепешку переложить в форму, уплотнить и сформовать бортики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Очистить от кожуры яблоки, нарезать их тонкими дольками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Выложить на основу из теста и полить готовой карамелью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Накрыть вторым пластом теста, фигурно защипать края, сделать в центре несколько отверстий ножом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1950,'Смазать пирог взбитым яйцом, печь 30 – 40 минут в духовом шкафу при температуре 200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1951,'Банан очистить и размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1951,'Добавить сырые яйца, взбить массу с помощью блендера до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1951,'Ввести кокосовую стружку и немного корицы, по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1951,'Смесь еще раз взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1951,'Блинчики жарить на любом растительном масле с двух сторон до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Яблоки отчищаем от кожицы, нарезаем на маленькие кубики, перекладываем в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Куриное яйцо нужно взбить вместе с кусочком растопленного сливочного масла и убрать в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Изюм нужно залить кипятком и убрать в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'На разогретую сковороду кидаем 2 кусочка сливочного масла, перекладываем нарезанные яблоки и посыпаем сахаром, все это тушим до тех пор, пока яблоки не станут мягкими, примерно 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Спустя 5 минут перекладываем яблоки в миску, даем им остыть. Затем смешиваем их с корицей и изюмом (Воду, который вы заливали изюм, нужно слить!) Все хорошо перемешиваем. Убираем в сторону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Лаваш нарезаем на 2 равных части. И смазываем с 1 стороны смесью из сливочного масло и куриного яйца, Даем пропитаться лавашу 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'На лаваш выкладываем начинку с 1 края и заворачиваем в рулет.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1952,'Отправляем эти ленивые штрудели в духовку на 15-20 минут, до тех пор пока корочка не подрумянится.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Репчатый лук очистить и нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Натереть морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Разогреть на сковороде оливковое масло, спассеровать овощи.','https:https://st.vkuso.ru/data/cache/thumb/58/381fc7a47b8be58_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Приготовить мясной фарш, вбить в него сырое куриное яйцо, всыпать рубленый чеснок. Соль и перец – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/e0/7e02434810b6be0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'По желанию можно добавить сухую или свежую измельченную зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Массу перемешать и отбить о дно емкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Смочить руки холодной водой, сформовать шарики размером с небольшой орех.','https:https://st.vkuso.ru/data/cache/thumb/cd/e45b81ff7acc5cd_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Переложить фрикадельки в пассеровку в один слой, подлить разбавленную водой сметану или молоко.','https:https://st.vkuso.ru/data/cache/thumb/e4/b022936ff4f16e4_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Мясные изделия должны изменить цвет, только после этого их можно перемешать.','https:https://st.vkuso.ru/data/cache/thumb/4a/132ed0591e78a4a_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Потушить вместе все ингредиенты до выпаривания жидкости.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Добавить помидоры, нарезанные кусочками, томатную пасту. Посолить по вкусу, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/04/21faa822b93e204_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Посыпать сухой смесью болгарских перцев и прованских трав.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'В отдельной посуде отварить спагетти, они должны остаться полутвердыми.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1953,'Подать блюдо горячим с соусом из маленьких фрикаделек, украсить свежей зеленью петрушки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Все ингредиенты должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Мягкое сливочное масло перемешать со сметаной, всыпать порциями пшеничную муку, влить погашенную уксусом или лимонным соком соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Масса должна получиться мягкой и эластичной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Поставить тесто на два часа в холод, накрыть пищевой пленкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Для начинки потребуется размороженная вишня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Оттаявшие ягоды отжать от излишков сока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Разделить охлажденное тесто на шестнадцать частей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Кусочки раскатать в длинные лепешки, положить ягоды в центр, посыпать сахарным песком, края защипать.','https:https://st.vkuso.ru/data/cache/thumb/36/ca779d7f19f8036_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Выложить трубочки с ягодами, похожие на гороховые стручки, в форму по кругу, дно должно полностью закрыться.','https:https://st.vkuso.ru/data/cache/thumb/20/82e79608e50fe20_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Выпечь четыре таких коржа, температура приготовления – 200 градусов, время – по 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/e0/8eca1ec10d834e0_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Полученную выпечку остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Взбить сметану с сахарной пудрой, промазать кремом коржи, дать торту постоять полчаса или всю ночь для пропитывания.','https:https://st.vkuso.ru/data/cache/thumb/ce/9300d5757539ece_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1954,'Перед подачей посыпать блюдо кокосовой стружкой.','https:https://st.vkuso.ru/data/cache/thumb/ed/d482bed34cd88ed_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1955,'Натереть сыр на крупной терке. В оригинальном исполнении используются такие сорта сыра, как сулгуни и имеретинский, кулинарам, живущим в других широтах можно посоветовать использовать адыгейский и российский сыр в равных пропорциях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'В процессе замешивания не добавлять сразу всю муку, лучше делать это порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1970,'Добавить растительное масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1955,'Добавить яйца, немного соли, но она может и не понадобиться, сыры сам по себе достаточно соленый продукт. Порубить и добавить зелень укропа и кинзы, молоко. Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1955,'Выложить на противень пласт тонкого лаваша, по размеру – на весь противень, намазать на него тонким слоем сырную начинку, снова лаваш и начинка. Повторить процедуру семь раз. Немного начинки оставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1955,'Ачму выпечь в течение 20 – 30 минут в духовке, разогретой до 180 градусов. Почти при готовности смазать слоеный пирог остатками сырной начинки, дать подрумяниться. Подать грузинскую ленивую ачму, порезав порционными кусками, можно еще немного посыпать верх пирога свежей зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'500 мл. кефира подогреть (до ~35-40°C).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Добавить к кефиру 1 ст. л. жидкого меда, 1 ч. л. соли и 1 ч. л. соды. Смешать. Оставить на 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Добавить 2 ст. л. оливкового масла. Смешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Затем - 300 гр. просеянной ржаной цельнозерновой муки и 1 ч. л. разрыхлителя теста. Смешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Далее - 1 ч. л. молотого кориандра и 60-80 гр. семян (тыквы, подсолнечника и кунжута). Смешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'В заключение - 300-350 гр. пшеничной цельнозерновой муки. Добавлять постепенно, попутно перемешивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Замесить липкое тесто. Недолго.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Разделить тесто на 2 части. Сформировать батоны. Сделать надрезы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1956,'Выпекать в разогретой до 200°C духовке, 25-30 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Свежие вешки или другие грибы мелко нарезать и обжарить на сливочном масле.','https:https://st.vkuso.ru/data/cache/thumb/e0/77554aa53a949e0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Сырокопченую ветчину нарезать соломкой.','https:https://st.vkuso.ru/data/cache/thumb/c5/507312b63811ec5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Приготовить соус из растопленного сливочного масла и муки. Массу прогревать и помешивать в течение двух минут.','https:https://st.vkuso.ru/data/cache/thumb/d0/f2c1892130810d0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Влить молоко, добавить соль по вкусу, довести до кипения. Огонь выключить.','https:https://st.vkuso.ru/data/cache/thumb/c6/08cfdd1c95d6ec6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Пластины лазаньи отварить: вскипятить воду, посолить, влить ложку растительного масла, опустить готовый, купленный в магазине, продукт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Варить 10 минут, откинуть на дуршлаг, промыть холодной водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Форму для выпечки смазать растительным маслом, полить полученным соусом, выложить первый слой пластин. Сверху – измельченная ветчина, грибы, соус, тертый сыр.','https:https://st.vkuso.ru/data/cache/thumb/73/48bd898e8f93373_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Накрыть вторым слоем отваренного теста.','https:https://st.vkuso.ru/data/cache/thumb/65/601a571f2653d65_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Процедуру повторить еще два-три раза. Сверху должен быть сыр.','https:https://st.vkuso.ru/data/cache/thumb/b8/18c5e6722b9e9b8_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1957,'Печь изделие в духовом шкафу при температуре 200 градусов в течение получаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Прогреть молоко, соединить с сухими дрожжами, сахарным песком и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Всыпать пшеничную муку, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Вбить сырое куриное яйцо, замесить тесто, смазать маслом поверхность.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Поместить массу в сухую и чистую емкость, накрыть тканью и поставить в тепло на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Тесто раскатать в тонкую лепешку, переложить на прогретый противень, заранее застеленный пергаментом.','https:https://st.vkuso.ru/data/cache/thumb/b2/e64a7c4ff66fbb2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Основу смазать томатным соусом, разложить нарезанные ананасы и ветчину, посыпать пиццу тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/2c/3510682231bae2c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1958,'Печь в течение 15 минут при температуре 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Раскалить в казане растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Нарезать свинину кусочками средней величины, опустить в казан, обжарить до образования румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Репчатый лук нарезать кольцами или полукольцами, всыпать в мясо, продолжать обжаривать на огне средней мощности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Нарезать очищенный картофель крупными кусками, положить в общую массу при готовности лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Прогревать до полуготовности картофеля.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Подлить воду, она должна покрыть продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1959,'Накрыть казан крышкой, готовить 15 минут. Снять с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Приготовить тесто из пшеничной муки, воды, сухих или свежих дрожжей, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Масса должна быть очень липкой, время вымешивания – от пяти до десяти минут.','https:https://st.vkuso.ru/data/cache/thumb/e9/d098c2c13ab53e9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Готовый продукт накрыть салфеткой и оставить в тепле на 10 – 12 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Хороший вариант – использовать для раскатывания пищевую пленку, присыпанную мукой.','https:https://st.vkuso.ru/data/cache/thumb/4b/7f11917e198414b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Сформовать батон.','https:https://st.vkuso.ru/data/cache/thumb/89/41f294ac232ed89_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Противень выстелить бумагой, сбрызнуть оливковым маслом, посыпать мукой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Выложить изделие, накрыть тканью и оставить в теплом месте еще на два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1960,'Печь в течение 30 – 35 минут, на нижнюю полку духового шкафа поставить поддон с водой.','https:https://st.vkuso.ru/data/cache/thumb/fb/9a815c2d88124fb_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Просеять пшеничную муку с солью в глубокую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Влить заранее подогретую воду, добавить сметану и мягкое сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Вымесить эластичное тесто, разделить на три части, каждую завернуть в пищевую пленку.','https:https://st.vkuso.ru/data/cache/thumb/c0/e0d7f065993b7c0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Разморозить вишню, отцедить лишнюю жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Сок не выливать, в ягоды добавить крахмал и сахарный песок.','https:https://st.vkuso.ru/data/cache/thumb/ca/11f7636d86d92ca_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Готовое тесто тонко раскатать, нарезать кружки с помощью стакана.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Выложить на лепешки начинку, защипать края.','https:https://st.vkuso.ru/data/cache/thumb/7a/4891b6f5720ab7a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Довести воду до кипения, положить вареники, степень готовности определяется всплытием плюс еще три-четыре минуты.','https:https://st.vkuso.ru/data/cache/thumb/01/282ed139dcd9801_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1961,'Подавать блюдо порциями, для соуса можно использовать густую сметану с оставшимся вишневым соком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Говяжье филе и морковь нарезать кубиками, репчатый лук – крупными кольцами.','https:https://st.vkuso.ru/data/cache/thumb/82/612516fac3e4082_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Мясо выложить на бумажное полотенце, чтобы удалить лишнюю жидкость.','https:https://st.vkuso.ru/data/cache/thumb/35/7ac7c1ff3099635_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Нарезать бекон мелкими кусочками, обжарить до корочки на сухой сковороде.','https:https://st.vkuso.ru/data/cache/thumb/be/cade36c1ea459be_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Переложить говядину на сковороду с беконом, готовить небольшими партиями, жарить со всех сторон, огонь – сильный.','https:https://st.vkuso.ru/data/cache/thumb/42/92810e12b3ba942_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Переложить продукт в сотейник.','https:https://st.vkuso.ru/data/cache/thumb/e7/d9e2d1fd86c74e7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Все на той же сковороде обжарить нарезанные овощи.','https:https://st.vkuso.ru/data/cache/thumb/38/e1268fc4126b238_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'К мясной обжарке добавить по вкусу соль, перец и немного муки, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Поставить в духовой шкаф на четыре минуты, перемешать и допечь еще четыре минуты. Температура приготовления – 230 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Добавить овощи со сковороды, влить заранее сваренный говяжий бульон, красное вино, измельченный чеснок, томатную пасту, сушеный майоран, тимьян, лавровый лист и зеленую петрушку.','https:https://st.vkuso.ru/data/cache/thumb/0f/90da6fd278a670f_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Довести массу на плите до кипения, накрыть сотейник фольгой, поставить в духовой шкаф на три-четыре часа, температуру снизить до 160 градусов.','https:https://st.vkuso.ru/data/cache/thumb/f6/6105b20c6a28bf6_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Очистить белые грибы и лук-шалот.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Сначала обжарить лук на смеси оливкового и сливочного масла, переложить на блюдо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'В той же сковороде обжарить грибы, вернуть лук, подлить бульон, всыпать зелень и специи.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Смесь потушить под крышкой в течение 10 минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'За 45 минут до готовности мяса добавить в него полученный грибной соус, перемешать, накрыть фольгой, довести до готовности.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1962,'Растопить сливочное масло, добавить муку, перемешать. Полить мясо полученной заправкой.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1963,'Смешать до однородности творог, сахар, муку, желтки сырых яиц, сливки. В качестве добавок можно положить изюм и цукаты, рубленые орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1963,'Отдельно взбить в устойчивую массу белки, осторожно, чтобы пена не опала, соединить с основной творожной массой.  Выложить в смазанную форму, печь творожную пасху при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Приготовить маринад из подсолнечного масла, рубленого чеснока, соевого соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Куриную грудку положить в смесь на два часа, затем обжарить до готовности с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Обжарить на сковороде бекон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Разрезать вдоль багет, прогреть хлеб в духовом шкафу до появления хрустящей корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Обе половины смазать соусом из майонеза, соевого соуса и дижонской горчицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'На одну половину хлеба выложить салат латук, помидоры кружочками, обжаренную грудку, нарезанную наискосок.','https:https://st.vkuso.ru/data/cache/thumb/e6/218c98d4c43d8e6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Сверху – обжаренный бекон, вторая половина багета.','https:https://st.vkuso.ru/data/cache/thumb/53/d56d02e658c2353_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1964,'Готовый сэндвич разрезать на две части.','https:https://st.vkuso.ru/data/cache/thumb/2a/076556f89b38c2a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1965,'Репчатый лук очистить, порубить, всыпать в мультиварку, выставить режим «Поджаривание» на семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1965,'Очищенную морковь натереть, добавить в обжарку, перемешать, потушить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1965,'Зеленую чечевицу перебрать и промыть, выложить продукт в чашу, влить кипяток и всыпать специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1965,'Выставить режим «Тушение» на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1965,'Посолить за пять минут до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Малое куриное филе слегка отбиваем, потом посыпаем специи по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Заранее поставьте картофель отвариваться до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Сметану смешиваем с плавленым сыром и чесноком ( который нужно выдавать через чеснокодавку). Убираем в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Ананасы из банки можно порезать на маленькие кусочки. (Если они конечно у вас сразу маленькие то, можно не нарезать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Сыр натераем на мелкой терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1966,'Куриное филе, выкладываем на протвинь, смазываем его намазкой, укладываем ананасы, и посыпаем сыром, отправляем в разогретую духовку при 180°С, до готовности. Это примерно минут 35-40. Все готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Картофель нарезать кубиками, посолить и обжарить на сильном огне минут 5.','https://vkuso.ru/data/cache/data/2c/2229a1869098a2c_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Репчатый лук нарезать кубиками и обжарить до мягкости.','https://vkuso.ru/data/cache/data/a1/e7dcca9cdbba3a1_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Добавить на сковороду нарезанные пластинками шампиньоны, посолить, поперчить и обжарить 5-7 минут.','https://vkuso.ru/data/cache/data/50/b38525902965150_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'На дно горшочков выложить 1/2 часть грибов, добавить 1 ст. ложку сметаны.','https://vkuso.ru/data/cache/data/8d/2b1ca302a702a8d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Следующий слой картофеля. Добавить 50 мл воды в каждый горшочек.','https://vkuso.ru/data/cache/data/3a/d8e609105952d3a_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Далее опять слой грибов и сметаны. Сверху посыпать натертым сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1967,'Приятного аппетита!','https://vkuso.ru/data/cache/data/0d/856f0696749840d_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1968,'Банан размять вилкой в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1968,'Добавить муку, какао, разрыхлитель, сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1968,'Влить молоко или воду, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1968,'Выпекать 3-5 минут в микроволновой печи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'Лук мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'На растительном масле обжарить лук.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'Сыр натереть на крупной тёрке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'Завернуть в блины мясную начинку. И уложить их в форму для запекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'Приготовим бешамель.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1969,'Залить блины соусом. Сверху посыпать сыром. Посыпать орегано.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1970,'В миску разбить два яйца. Добавить соль, сахар, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1970,'Влить молоко, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1970,'Добавить просеянную муку и разрыхлитель, хорошо перемешать до однородности. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1970,'На разогретой и слегка смазанной сковороде жарить блины до готовности. Смазываю сковороду только перед первым блином. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Замесить тесто из муки, масла, сметаны и щепотки соли. Тонко раскатать и выложить в форму, смазанную растительным маслом (у меня форма диаметром 24 см).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Лук нарезать полукольцами и обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Приготовить заливку: для этого взбить венчиком яйца со сметаной и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Выложить обжаренный лук на тесто, поверх лука рыбу, порезанную небольшими кусочками. Посыпать специями для рыбы',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Залить пирог заливкой и сверху посыпать натертым на крупную терку сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1971,'Отправить в духовку на температуру 180 градусов примерно на 30-35 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1972,'Промыть и очистить шампиньоны, порезать мелко и обжарить на масле. Отварить яйца вкрутую, порубить. Порезать ветчину тоже кусочками. Ингредиенты соединить, добавить рубленую зелень петрушки, майонез. Попробовать смесь на вкус, при необходимости добавить соль, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1972,'Твердый желтый сыр сделать мягким, для этого положить весь кусок в горячую воду, дать прогреться, вынуть и раскатать в тонкий пласт толщиной 0,5 сантиметра. Сырную лепешку смазать готовой смесью и плотно свернуть рулетом. Нужно делать это достаточно быстро, пока сыр не остыл и не начал ломаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1972,'Закусочный рулет из сыра, ветчины и грибов закатать в пищевую фольгу и на пару часов отправить в холодильник.  Вынуть и порезать на пластинки, украсить зеленью тимьяна (веточками), дольками помидоров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Свинину промыть и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Репчатый лук мелко покрошить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Чечевицу хорошо промыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Прогреть на сковороде растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Обжарить мясо с луком, перцем и солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Переложить продукты в казан.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Другой вариант – кастрюля с толстым дном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Томатную пасту развести в бульоне или воде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Всыпать чечевицу, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1973,'Тушить все вместе на тихом огне пятьдесят минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'Зеленую чечевицу промыть, залить холодной водой для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'Промыть бобы еще раз, переложить в кастрюлю, влить воду, варить до полной готовности, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'По желанию добавить корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'Курагу замочить в воде на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'Растереть в кашу бананы при помощи вилки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1974,'Добавить массу в кашу. Перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Чечевицу промыть проточной холодной водой, выложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Влить воду, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Довести до кипения, огонь уменьшить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Варить кашу полчаса, пену снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Нарезать свежие вымытые шампиньоны, покрошить репчатый лук, натереть морковь и порубить чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'На сковороде в масле спассеровать лук до полуготовности, добавить чеснок и морковь, все вместе жарить три или четыре минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Добавить грибы и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Жарить до выпаривания жидкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Бобы откинуть на дуршлаг, процедить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Выложить на сковороду, добавить специи и зелень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1975,'Кашу перемешать, Подержать под крышкой без огня пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Произвольно нарезать репчатый лук, сладкий болгарский перец и помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Морковь потереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Прогреть сливочное масло на сковороде, спассеровать морковь и лук до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Добавить помидоры, чеснок и перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Продукты побрызгать лимонным соком и соевым соусом. Перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Потушить пятнадцать минут на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Прогреть воду в кастрюле, всыпать чечевицу, соль, добавить лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Все вместе варить на тихом огне десять минут под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1976,'Обе массы соединить, посыпать свежей рубленой зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Чечевицу промыть, залить свежей водой, оставить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Промыть курагу, нарезать мелкими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Яблоки очистить, удалить сердцевину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Мякоть и грецкие орехи перемолоть в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Выложить в кастрюлю бобовые, влить цельное молоко с семенами льна, прогреть на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Довести до кипения, огонь уменьшить, варить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Влить натуральный мед, добавить курагу, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1977,'Выложить массу на тарелку, подать с ореховым пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1978,'На дно чаши положить кусочек сливочного масла, всыпать овсяные хлопья, сахарный песок и соль по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1978,'Влить молоко, наполовину разведенное водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1978,'Выставить режим «Каша» на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1979,'На дно чаши мультиварки всыпать овсяные хлопья, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1979,'Выставить режим «Каша» на десять или пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1979,'Добавить сахар, соль, фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1980,'Тыкву промыть, очистить, нарезать кубиками или натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1980,'Всыпать в чашу прибора овсянку, сахарный песок, влить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1980,'Добавить тыкву, сливочное масло и корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1980,'Массу перемешать, в ней не должно быть комочков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1980,'Выставить режим «Варка» или «Молочная каша». Готовить двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1981,'Изюм хорошо промыть, выложить в чашу мультиварки вместе с овсяными хлопьями, влить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1981,'Соль и сахар – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1981,'Тушить под крышкой в режиме «Молочная каша» около получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1981,'Если масса получилась водянистой – прогреть без крышки несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Апельсин вымыть, снять кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Цедру натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Фрукт поделить на дольки, очистить, нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Выложить на дно чаши мультиварки апельсин вместе с цедрой, всыпать сахар и овсянку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Влить молоко с водой, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1982,'Выставить режим «Молочная каша», несколько раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1983,'Чашу мультиварки смазать сливочным маслом, выложить овсянку, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1983,'Добавить корицу и соль, выставить режим «Каша» на тридцать или сорок минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1983,'Добавить мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1983,'Миндальные или другие орехи нарезать или натереть, всыпать в готовую кашу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1984,'Творог смешиваем с сметаной и медом (или джемом, для вкуса), убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1984,'Слоенное тесто слегка раскатываем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1984,'На раскатанное слоенное тесто намазываем начинку из творога, затем нарезаем на равные полоски, перекладываем на противень и отправляем в духовку при 180°C на 20-25 минут до готовности.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1985,'Приготовить тесто, такое же, как для пиццы: смешать мягкое сливочное масло, яйцо, всыпать сахар, соль по вкусу, немного соды, влить сметану. Массу хорошо перемешать. Количество сахара в тесте можно варьировать, в зависимости от того, собирается ли кулинар приготовить пирог в качестве второго блюда или сладкий десерт, во втором случае сахара можно взять в несколько раз больше. Всыпать муку, замесить тесто, муку добавлять постепенно, продолжая месить. Приготовить начинку: творог, рубленая зелень, раздавленный через пресс чеснок, соль, перец – по вкусу. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1989,'Теперь помещаем нашу кастрюлю на водяную баню и доводим до однородной консистенции, помешивая ложкой. До кипения доводить не стоит. Как только масло начнет подтапливаться, можно снимать с плиты и помешивать еще в течение пары минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'В кастрюлю влить разведенные дрожжи, яйца с сахаром, растительное масло и кефир, соль, муку и ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1985,'Тесто раскатать на две части. Каждую часть раскатать в круг диаметром 30 – 35 сантиметров. На половину лепешки положить начинку из творога, оставив края для защипывания. На творожную начинку выложить тонкие кружочки салями или другой сухой колбасы, пластинки сыра. Лепешку свернуть пополам, защипать края. Чтобы пирог не вздулся во время выпечки – наколоть его в нескольких местах вилкой.  Печь кальцоне с творогом, сыром и салями на листе бумаги для выпечки, на противне, духовку разогреть до 220 градусов. Перед выпечкой верх пирога смазать взбитым яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Капусту нарезать шайбами толщиной 1,5 см.','https://vkuso.ru/data/cache/data/6f/f867e58f036686f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Стейк с одной стороны смазать растопленным сливочным масло, посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/ad/62bad62d39d05ad_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Выложить на противень смазанным срезом вниз.','https://vkuso.ru/data/cache/data/f2/f66a295734bf2f2_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Растительное масло смешать с приправой "Итальянские травы" или любой другой по вашему вкусу.','https://vkuso.ru/data/cache/data/5c/1a50e3e6f1c2e5c_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Смазать верхнюю часть стейка приготовленной смесью, посолить по вкусу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1986,'Готовые стейки сверху украсить свежими овощами и зеленью. Подавать к столу с мясом, рыбой или как самостоятельное блюдо!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1987,'Для начала займёмся маринадом. Яблоки почистить, нарезать. Нам нужно их слегка запечь, чтобы они стали мягкими. Отправляем яблоки в разогретую духовку, либо в микроволновку на полную мощность на 5-7 минут до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1987,'Яблоки отправить в чашу блендера, добавить паприку, соль, кетчуп, острый соус, соевый соус, половину сока лайма. Хорошо пробить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1987,'Подготовить ребра. Убрать пленку. Нарезать порционными кусками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1987,'На противень выложить ребра одним слоем. Распределить оставшийся маринад. Форму закрыть фольгой и отправить в разогретую до 180°C духовку на 60-80 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1987,'Через час - час двадцать достать ребра, убрать фольгу, смазать их соусом и отправить в духовку без фольги минут на 20-30 до румяной корочки. Ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1988,'Для начала очищаем зеленые яблоки от кожуры. Лучше брать чуть кисловатые сорта. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1988,'Предварительно размороженные пласты теста слегка раскатываем и нарезаем на полоски толщиной примерно 1 см. Каждую полосочку теста слегка раскатываем скалкой. Обмакиваем яблочное кольцо в сахар и обматываем полосочку теста вокруг яблока, но оставляем небольшие зазоры, так как при запекании тесто увеличится в объемах. На одно яблочное кольцо у меня уходит две полосочки теста. То же самое проделываем со всеми яблоками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1988,'Из данного объема теста у меня получилось 16 таких яблочных колец. Лучше запекать булочки на пергаменте, смазанном маслом, так как при запекании из них выходит сок. Смазываем яйцом и по желанию можно присыпать корицей или кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1988,'Выпекаем в разогретой духовке примерно 25-30 минут при температуре 180 градусов. Готовые булочки очень ароматные, яблоки хорошо пропекаются, становятся мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1989,'Для начала возьмем большую миску, в которую мы будем крошить печенье. Вы можете делать это при помощи рук, но со скалкой получается гораздо быстрее и удобнее. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1989,'В отдельную кастрюльку кладем сливочное масло (у меня одно домашнее). Его лучше брать комнатной температуры. Добавляем сахар, сметану, какао порошок и вареную сгущенку. Со сгущенкой вкус мне нравится больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1989,'На столе расстилаем фольгу и половину массы перекладываем по центру. Формируем руками колбаску. Затем скручиваем фольгу по краям, чтобы наша колбаса не вылезла при более плотном нажатии.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1989,'Теперь, когда обе колбаски готовы, помещаем их в холодильник до застывания. На это понадобится несколько часов. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'Замаринуем куриные бедра. Для этого нарежем луковицу и измельчим чеснок. Смешаем куриные бедра с чесноком и луком, добавим 2 ст. л. майонеза и немного подсолим. Перемешаем и оставим мариноваться на пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'Нарезаем произвольными небольшими кусочками сырую морковь и болгарский перец. Разделим овощи на 2 равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'Промытый рис делим пополам (по 1,5 стакана). Отправляем рис в 2 пакета для запекания. Добавляем в каждый пакет с рисом по 1 ч. л. приправы для плова и по 1 ст. л. растительного масла. Также в каждый пакет добавим поделенные пополам нарезанные овощи. Перемешаем все продукты в пакетах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'В 800 мл воды добавляем 2 ч. л. соли и хорошо размешаем до полного растворения соли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'В каждый пакет с рисом и овощами выложим по 3 замаринованных куриных бедра и добавим по 400 мл. подготовленной соленой воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'Закрываем пакеты для запекания и сверху делаем по насколько дырочек (как рекомендуют по инструкции на пакетах для запекания).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1990,'Готовим курицу с рисом в разогретой до 200 градусов духовке примерно 45-50 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1991,'2 банана размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1991,'Добавить 1/4 ч. л. соли, 2 ст. л. сиропа топинамбура, 1 ч. л. молотой корицы, 40 мл. растительного масла. Смешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1991,'Добавить 70 гр. нутовой муки, 50 гр. кокосовой муки и 1 ч. л. разрыхлителя теста. Смешать. Оставить на 5-10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1991,'Скатать из теста шарики. Выложить на противень, застеленный пергаментом. При помощи вилки придать заготовкам плоскую форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1991,'Выпекать в разогретой до 180°C духовке, 15-18 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Укроп мелко нарезаем и временно убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Сметану смешиваем с плавленый сыром и чесноком, который нужно выдавить через чеснокодавку ,',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Куриные яйца нужно заранее отварить, и почистить, заметем меленько нарезать, и добавить к смеси из сметаны и плавленого сыра,',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'От крабовых палочек сперва отрезаем тоненько красную часть и временно убираем ее в сторону. Сами крабовые палочки очень мелко нарезаем и добавляем к тем же ингредиентам, все хорошо перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Красную часть от крабовых палочек мелко нарезаем и перекладываем на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Из полученной смеси, катаем шарики, затем их обваливаем в нарезанной красной части крабовых палочек, я ещё их обвалил в укропе. Убираем в холодильник на 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1992,'Подаем на праздничный стол .',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Минтай вымыть, почистить, удалить плавники и хвост. Нарезать на порционные кусочки.','https://vkuso.ru/data/cache/data/23/f31312778753823_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Посолить, добавить приправу для рыбы, перемешать и оставить мариноваться на 15-20 минут.','https://vkuso.ru/data/cache/data/f4/65bbdf1b37e0ff4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Лук нарезать кубиками.','https://vkuso.ru/data/cache/data/e1/d8a11577df1fae1_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Морковь натереть на крупной терке.','https://vkuso.ru/data/cache/data/86/a6e9f681364a886_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Лук и морковь обжарить на сильном огне постоянно помешивая в течении 4-5 минут.','https://vkuso.ru/data/cache/data/6b/279ff2f2b297a6b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Замаринованный минтай выложить в форму одним слоем, дно формы я смазала растительным маслом.','https://vkuso.ru/data/cache/data/56/6522bf8dde94b56_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Сверху выложить лук с морковью.','https://vkuso.ru/data/cache/data/82/4b7b74bb77e1982_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Теперь приготовим соус, для этого смешаем сметану (любой жирности), майонез, дижонскую горчицу, соль и воду (50 мл).','https://vkuso.ru/data/cache/data/9f/6e7cd2a1ab55d9f_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Перемешать в емкости сырые куриные яйца с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Замесить тесто, масса должна быть эластичной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Заливаем минтай приготовленным соусом. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1993,'Приятного аппетита!','https://vkuso.ru/data/cache/data/18/4841ca561a62d18_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1994,'Перцы (можно взять любые – красные, желтые, оранжевые) очистить от семян. «Хвостики» не отрезать.  Приготовить начинку: нарезать куриное филе кубиками в один сантиметр. Помидоры опустить в кипяток ровно на одну минуту, вынуть и снять кожицу. Их также порезать кубиками, еще мельче, чем курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1994,'Смешать эти два ингредиента, добавить зелень лука и петрушки, соль, перец – по вкусу, любые сухие специи. Добавить немного йогурта, начинка станет еще сочнее, перемешать. Йогурт взять нейтрального вкуса, без добавок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1994,'Перец разрезать на половинки поперек, в «чашечки» положить куриный фарш, печь 30 минут при температуре 180 – 200 градусов. Вынуть перцы из духовки, посыпать каждый тертым сыром и допечь еще 10 минут, до расплавления перца и образования аппетитной корочки.  Подать куриное филе в болгарском перце, посыпав свежим рубленым укропом или просто положить его веточками сверху перцев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1995,'В емкость всыпать сахарный песок, разрыхлитель, муку, соль, пищевую соду, ванильный сахар и корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1995,'В другой миске взбить яйца с топленым маслом и банановым пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1995,'Обе массы соединить, тесто выложить в прямоугольную форму, печь при температуре 180 градусов в течение пятидесяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1996,'Бананы очистить и превратить в пюре, лучше взять переспевшие плоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1996,'Отдельно смешать топленое масло с сахарным песком, вбить сырые куриные яйца, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1996,'Добавить банановое пюре, влить немного молока, всыпать разрыхлитель, муку. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1996,'Влить оставшееся молоко и муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1996,'Замесить тесто, разделить его на три части, выпечь по очереди три пирога в мультиварке, режим «Выпечка» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1997,'Бананы очистить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1997,'Мягкое сливочное масло выложить в хлебопечку вместе с мукой, бананами, дрожжами, сахарным песком, яйцами, специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1997,'Прибор включить в режим «Замес» на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1997,'Сформовать хлеб, выставить режим «Кекс» или «Выпечка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'Превратить в муку овсяные хлопья при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'Пересыпать в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'В блендер выложить нарезанные спелые бананы, любые сухофрукты, часть соевого молока, разрыхлитель и корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'Превратить в однородную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'Соединить смесь с овсяной мукой, оставшимся молоком и грецкими орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1998,'Тесто выложить в форму для выпекания, поставить на восемьдесят минут в духовой шкаф, температура выпекания – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Грецкие орехи поместить на противень, запечь пять минут при температуре 180 градусов, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Отдельно перемешать сахарный песок с мягким сливочным маслом, вбить сырые куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Добавить банановое пюре, рубленые орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Всыпать корицу, муку, соль, разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Массу перемешать, выложить в форму, печь в течение часа при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (1999,'Остудить перед подачей в течение пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2000,'Льняную муку растворить в воде, влить растительное масло, положить банановое пюре и ваниль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2000,'В другой миске соединить орехи, сухофрукты, ржаную муку, соду, корицу, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2000,'Обе массы перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2000,'Выложить в форму, готовить тридцать пять минут при температуре 170 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Перетереть творог через сито (с мягким творогом этот шаг можно пропустить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'К творогу добавить мягкое сливочное масло, ванильный сахар и сахарную пудру, пробить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Слегка смочить руки, сформировать сырки и выложить их на поверхность, застеленную пищевой пленкой (или можно распределить творожную массу по силиконовым формочкам).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Шоколад разломать на небольшие кусочки и выложить в миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Растопить шоколад на водяной бане, периодически помешивая. Или растопите его в микроволновке импульсно - по 10-15 сек нагрели, перемешали, опять нагрели, перемешали и так до тех пор, пока шоколад не растопится полностью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'В растопленный шоколад влить растительное масло и хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Достать сырки из морозилки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Окунуть каждый сырок в глазурь, достать и дать стечь лишнему шоколаду, выложить на бумагу для выпечки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2001,'Аккуратно убрать деревянные шпажки, по желанию украсить сырки глазурью и убрать их в холодильник до полного застывания шоколада.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2002,'Бананы очистить, поломать, приготовить пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2002,'Растопить сливочное масло, добавить к бананам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2002,'Всыпать сахарный песок, муку, разрыхлитель, вбить яйцо, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2002,'Смесь вымешать, положить в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2002,'Хлеб выпечь в течение часа, температура – 170 градусов. Готовность проверить деревянной палочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Влить в емкость кипяток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Выложить сухофрукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Оставить на пять минут. Откинуть на дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Промыть проточной водой, обсушить бумажным полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Нарезать чернослив и курагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Смазать форму в хлебопечке сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Выложить ингредиенты: сухофрукты, муку, сухие дрожжи, соль, сахарный песок, изюм, курагу, ванилин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Влить жидкое сливочное масло, молоко.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2003,'Выставить режим «Сладкая выпечка».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Сухие быстрые дрожжи всыпать в теплую воду. Добавить немного белой муки, сахарный песок. Перемешать, поставить смесь в тепло на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Отдельно взбить сырые куриные яйца с сахаром при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'В глубокую емкость влить содержимое мисок, растопленное сливочное масло и сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Всыпать сахар, муку. Замесить тесто, укрыть кастрюлю полотенцем, поставить в теплое место на три часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Цитрусовые нарезать кусочками вместе с цедрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Любые сухофрукты замочить на пять минут в теплой воде, затем мелко нарезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Ввести в тесто сухофрукты, ванилин из пакетика, цитрусовые.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Тесто размять, добавки должны распределиться равномерно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Форму смазать маслом, выложить тесто, накрыть тканью, дать постоять в тепле один час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Выпекать в течение сорока минут в заранее прогретой духовке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2004,'Вынуть, выложить на стол, укутать тканью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Сухие дрожжи перемешать с сахаром и теплым молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Поставить мисочку на десять минут в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'В большую емкость влить растопленное сливочное масло, всыпать сахар, муку, соль, влить разведенные дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Тесто замесить руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Поставить кастрюлю в тепло, накрыть тканью. Время – два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Вмесить изюм.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Сформовать шесть колобков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Емкость для выпекания смазать маслом, выложить шарики вплотную друг к другу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2005,'Подержать полчаса в тепле, затем печь в духовке тридцать минут. Температура приготовления – 190 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Сухие дрожжи растворить в подогретой воде, оставить на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Влить в кастрюлю теплое молоко, всыпать сахарный песок, сливочное масло, просеянную муку, ванилин, соль, яйца, разведенные дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Замесить тесто, поставить в тепло на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Горький шоколад поломать кусочками, вмесить в тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Форму для выпекания смазать растительным маслом, выложить тесто, накрыть полотенцем, убрать в тепло на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2006,'Духовку прогреть, поставить форму с пирогом, время выпекания – сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Изюм без косточек выложить в кипящую воду на двадцать минут, отбросить на дуршлаг, обсушить полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Сухие дрожжи размешать в теплой воде, поставить в тепло на десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Таз накрыть тканью, поставить в тепло на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Вмесить изюм.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Чашу мультиварки смазать растительным маслом, выложить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Выставить режим подогрева на десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Оставить тесто на полчаса для подъема.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2007,'Выставить режим «Выпечка» на час, перевернуть, печь еще сорок минут. Готовую выпечку вынуть, укутать в ткань.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2008,'Приготовить тесто, для этого сначала взбить белки с сахаром и щепоткой соли. Отделенные от белков желтки взбивать отдельно, тоже с сахаром, добавить ванилин. В эту смесь постепенно влить растительное масло без запаха. Обе массы соединить. В яичную массу вмесить просеянную муку с добавлением разрыхлителя. Перемешивать осторожно, постараться, чтобы не пропал объем, тесто должно получиться воздушным, легким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2008,'Отдельно смешать какао и растворимый кофе, разбавить кипятком. Небольшой противень  застелить бумагой для выпечки, немного смазать растительным маслом. Выложить две трети теста ровным слоем. Оставшееся тесто смешать с какао-кофейной смесью, перемешать. Столовой ложкой выкладывать на светлое тесто в виде клякс, их немного «размыть» с помощью деревянной палочки, можно использовать зубочистку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2008,'Печь при 180 градусах в течение 15 – 20 минут. Выпеченный пласт быстро опрокинуть на кухонное полотенце и горячим свернуть в рулет. Оставить свернутым в полотенце до остывания. Приготовить крем: взбить сметану с пудрой, добавить загуститель для сливок. Отдельно растопить на водяной бане шоколад. Спелый банан очистить и размять вилкой в пюре, соединить с шоколадом, влить коньяк. Вымешанную до однородности смесь смешать со сметанной массой. Остывший мраморный рулет промазать полученным кремом и снова свернуть. Охладить и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'В большую емкость всыпать муку, ванилин, сахарный песок и дрожжи, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Влить растопленное сливочное масло, подогретое молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Мять руками до эластичности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Накрыть таз материей, поставить в тепло на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Обмять руками, снова накрыть материей, поставить в тепло еще на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Поделить массу на шарики диаметром в три сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'В небольшую емкость влить растопленное сливочное масло, отдельно перемешать корицу с тростниковым сахаром, всыпать в масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Окунать шарики из теста в сливочное масло, обвалять в посыпке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Круглую форму с отверстием застелить пергаментом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Выложить шарики из теста в шахматном порядке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Емкость поставить в тепло на тридцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Прогреть духовку до 180 градусов, выпечь хлеб в течение получаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2009,'Хлеб вынуть, укутать в полотенце.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Куриное мясо промыть, нарезать брусками небольшого размера, обсушить салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Обжарить в прогретом растительном масле до получения румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Выложить на салфетку для впитывания жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Промыть свежие шампиньоны, нарезать тонкими ломтиками, обжарить до румянца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Промыть вилок пекинской капусты, жесткую часть удалить, мягкую нарезать полосками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Нарезать полукольцами свежие огурцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Белый хлеб нарезать кубиками, обжарить на растительном масле вместе с очищенным чесноком до розоватого оттенка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Выложить на бумажные салфетки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Ингредиенты перемешать, посолить по вкусу, поперчить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2010,'Заправить смесью домашней сметаны и майонеза. Посыпать салат гренками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Морковь отварить. Другой способ – корнеплод промыть, поместить в пищевой пакет и отправить в микроволновую печь на семь минут. Включить среднюю мощность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Готовый продукт мелко покрошить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Репчатый лук почистить, нарезать полукольцами, обжарить до полупрозрачного состояния на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Свежие шампиньоны очистить и нарезать пластинками, обжарить на сильном огне, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Продукты выложить на тарелку слоями в любом порядке, промазывать чесночным соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Крабовые палочки нарезать кусочками, жарить на сковороде три минуты, огонь – слабый, продукт помешивать. Палочки должны стать мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Ингредиенты перемешать, добавить рубленый укроп, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2011,'Заправить домашней сметаной, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2012,'Шампиньоны оттаять при комнатной температуре, промыть, нарезать кусочками, обжарить до золотистого цвета вместе с полукольцами репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2012,'Сладкую кукурузу отцедить и промыть, обсушить на полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2012,'Перемешать обжарку и кукурузу с морковью по-корейски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2012,'Посолить и поперчить по вкусу, заправить майонезом. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Репчатый лук очистить, нарезать полукольцами, полить кипятком с уксусом и оставить для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Куриное филе вымыть, обсушить, нарезать полосками, жилы и пленки удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Прогреть масло на сковороде, обжарить курицу на сильном огне, помешивать. Соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Выложить в тарелку, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Свежие шампиньоны промыть и нарезать дольками, обжарить до корочки светло-коричневого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Отварить клубни картофеля, очистить от кожуры, натереть на крупной терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Яйца отварить. Желтки соединить с майонезом и рубленым чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Наполнить половинки белков полученной смесью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Выложить в прозрачную салатницу курицу, далее – лук, сеточка из майонеза.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Следующий слой – грибы, картофель, снова сеточка из майонеза.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Украсить начиненными белками в виде сугробов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2013,'Посыпать салат сырной стружкой, украсить листочками розмарина или веточками укропа.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'Репчатый лук нарезать кубиками и спассеровать на растительном масле до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'Копченую курицу очистить от кожицы, мясо также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'Шампиньоны промыть, покрошить, добавить в луковую обжарку, прогреть на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'В конце приготовления посолить, жарить до появления корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'Маринованные или соленые огурцы нарезать кусочками, отжать от излишков влаги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2014,'Ингредиенты переложить в салатницу, заправить майонезом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Репчатый лук очистить от шелухи, нарезать кубиками, обжарить на сковороде с постным маслом до появления румянца, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Шампиньоны промыть, обсушить и тонко нарезать, выложить к луковой обжарке, прогревать до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Отварить и очистить яйца, нарезать средними кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Свежие огурцы нарезать кубиками, ветчину, сыр – небольшими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Продукты перемешать, посолить и поперчить, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2015,'Выложить массу в сервировочное кольцо, уплотнить, кольцо удалить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Картофель отварить в мундире, охладить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Нарезать кубиками, побрызгать оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Грибы нарезать кусочками, обжарить с полукольцами репчатого лука до появления румяной корочки, соль – в конце приготовления.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Наколоть вилкой в нескольких местах сладкий болгарский перец, обжарить над пламенем конфорки до легкого обугливания кожуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Завернуть плоды в пленку на пять минут, а затем очистить и удалить семенные камеры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Мякоть нарезать тонкой соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Свежие огурцы порубить, нарезать промытый и обсушенный шпинат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Листовой салат порвать руками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Ингредиенты поместить в емкость, посыпать морской солью, побрызгать оливковым маслом, посыпать паприкой. Перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2016,'Выложить салатную массу на тарелку горкой, украсить дольками помидоров, листочками зелени.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2017,'Моем, чистим рыбку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2017,'Панировка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2022,'Горшочки для запекания смазать растительным маслом, разложить приготовленную смесь. Отправляем в духовку на 45 минут при температуре 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2017,'Панируем рыбку и выкладываем на фольгу и пергаментную бумагу, смазанную растительным маслом. Жарим на углях по 7 минут с каждой стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2018,'Картофель моем, чистим и промываем. Обсушиваем бумажным полотенцем и нарезаем «колечками» средней толщены. Солим, перчим, можно добавить паприку и перемешиваем. Временно убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2018,'Грудинку свиную моем, обсушиваем бумажным полотенцем, нарезаем на средние кусочки с небольшой толщеной. Также солим, перчим, можно добавить приправу для мяса, перемешиваем. Временно убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2018,'В отдельной тарелке смешиваем растительное масло и мелко нарезанным укропом и чесноком (который можно мелко нарезать или выдавить через чеснокодавилку)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2018,'Берем деревянные шпажки и поочередно накалываем сначала картофель, потом грудинку, Перекладываем на противень (у меня стеклянный). Вы можете взять металлический противень, накрыть его фольгой, сделать те же действия с шашлыком, накрыть фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2018,'При помощи кисточки смазываем шашлык смесью из укропа, растительного масла и чеснока. Подливаем немного воды, чтобы она дала пропариться блюду, и закрываем крышкой. За 20 минут до приготовления шашлыка снимаем крышку и даем подрумяниться грудинке. Данное блюдо готовится примерно 1 час в духовке. Все готово.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2019,'В кастрюлю налить воды. Добавить куриное филе без кожи. Ставим на огонь и доводим до кипения, варим 15 минут. Периодически снимаем пену. Спустя 15 минут вынимаем курицу из кастрюли и остужаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2019,'Картофель очистить и нарезать небольшими кубиками. В бульон, в котором варилась курица отправляем картошку, солим. Накрываем кастрюлю крышкой и доводим до кипения, варим 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2019,'Пока вариться картошка нарезаем репчатый лук и жарим в сковороде на сливочном масле 3 минуты, перемешивая.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2019,'Нарезать куриное филе на небольшие кубики. Отправить к картошку нарезанную курицу и обжаренные лук с грибами. Добавить плавленый сыр и поперчить. Перемешиваем, пока сыр не расплавится. Затем снимаем с огня',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2020,'На сковороде с растительным маслом обжарить фарш на сильном огне в течении 10 минут, перемешивая. Затем посолить и поперчить. Макароны отварить до полуготовности или взять вчерашние, смешать их с фаршем и мелко нарезанным укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2020,'Смешать в пиале сметану и яйца до однородности. Сыр натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2020,'Форму для запекания смазать растительным маслом, выложить макароны. Полить макароны смесью из сметаны с яйцами., посыпать сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2020,'Духовку разогреть до 190 градусов, отправить запеканку в духовку на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2021,'Крабовые палочки или крабовое мясо нарезать мелким кубиком, выложить в тарелку. Добавить панировочные сухари (4 ст. л.), майонез, соль и перец, вбить яйца и добавить дижонскую горчицу. Все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2021,'Подготовить панировочные сухари и пиалу с водой, чтобы смачивать руки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2021,'Смачиваем руки водой, формирует котлетки и обваливаем в панировочных сухарях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2021,'В сковороде разогреть растительное масло, отправить жариться котлетки. Готовим на среднем огне, обжариваем с двух сторон до золотистого цвета (примерно по 4 минуты с каждой стороны).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2022,'Свинину нарезать на мелкие кубики. На сковороде разогреть растительное масло, отправить мясо, жарим на сильном огне 10 минут, перемешивая. Спустя 10 минут, переложить мясо в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2022,'Лук репчатый (100 гр) нарезать мелким кубиком, отправить в сковороду, добавить вареные лесные грибочки (у меня были свежемороженые, они уже нарезаны на крупные кусочки). Готовим на среднем огне 5 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2022,'Картофель очистить и натереть на мелкой терке. Пропустить оставшийся репчатый лук, пропущенный через мясорубку (если нет мясорубки натереть на терке как картофель). Добавить яйцо и перемешать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2022,'Укроп мелко нарезать добавить к картошке, посолить, поперчить. Добавить сметану, обжаренное мясо, грибы с луком и чеснок пропущенный через пресс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2023,'Лучше взять молодой картофель, почистить и порезать дольками. Крупно порезать репчатый лук, морковь очистить и порезать кусочками. Корнеплод лучше не натирать на терке, от этого он «потеряется». Добавить в смесь овощей любые специи или смесь сухих специй, соль и перец молотый – по вкусу. Добавить томатную пасту и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2023,'Перемешанную массу положить в рукав для запекания (завязать его с одной стороны). Сделать несколько проколов, чтобы в процессе термообработки выходил пар. Печь при большой температуре в течение 1 – 1,5 часов. Рукав разрезать, содержимое высыпать в блюдо. Подать картофель, запеченный в духовке на гарнир горячим. Посыпать большим количеством рубленой свежей зелени (петрушка, зеленый лук, укроп).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'Капусту мелко нашинковать. В глубокой сковороде разогреть растительное масло и отправить готовиться капусту на среднем огне 10 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'Морковь натереть на крупной терке. Репчатый лук очистить и нарезать мелким кубиком. Отправить овощи к капусте и готовить еще 7 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'В сковороду влить воды и накрыть крышкой, готовить до полного выкипания воды. Затем добавить в сковороду чеснок пропущенный через пресс, соль и перец',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'Колбасу нарежьте соломкой. Добавьте в сковороду и готовьте все 5 минут, помешивая. Снимаем сковороду с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'Поверхность присыпать мукой и выложить тесто, немного раскатать. Разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'Противень застелить пекарской бумагой, смазать бумагу растительным маслом, чтобы при выпекании тесто не прилипло. Выкладываем слой теста на противень, а на него – начинку ровным слоем. Накройте начинку вторым пластом теста и запечатайте края.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2024,'В пиалу вбить яйцо и размешать. Смазать яйцом тесто и отправить пирог в разогретую духовку до 190 градусов. Выпекаем 40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2025,'Грибы перебрать, вымыть, порезать и обжарить на сковороде с рубленым репчатым луком. Отдельно отварить картофель, куриные яйца. Натереть картофель и яйца на терке, то же самое сделать с солеными огурцами и сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2025,'Выкладывать на блюдо слоями, первый слой – грибы с луком, вареный картофель, зеленый лук, промазать майонезом. Затем соленые огурцы, яйца, майонез, сыр. Сверху слоеный салат «Грибы под шубой» по кругу украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Фасоль замочить на ночь, утром отварить в подсоленной воде до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Откинуть продукт на дуршлаг, жидкость должна стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Репчатый лук очистить, нарезать кубиками и обжарить вместе с нарезанными шампиньонами до румянца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Продукты остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Отварить и очистить яйца, нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Такими же кубиками нарезать свежие огурцы и размороженные крабовые палочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Компоненты соединить, поперчить, посолить по вкусу и желанию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2026,'Заправить майонезом и хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Грибы отварить или обжарить на сковороде вместе с репчатым луком и постным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Баклажаны нарезать кубиками, посыпать солью и оставить под гнетом на час для удаления горечи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Выделившуюся жидкость слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Мякоть обсушить салфетками и обжарить с маслом на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Кабачки очистить, нарезать, обжарить. Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Остывшие продукты соединить, добавить нарубленные куриные яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Приготовить соус из уксуса, растительного масла, перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2027,'Залить салат, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Овощи промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Репчатый лук нарезать полукольцами, спассеровать на масле до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Добавить тертую морковь, жарить вместе пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Всыпать грибы, нарезанные пластинками, жарить до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Куриные окорочка отварить, охладить, отделить филе от костей, мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Яйца отварить и очистить, натереть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Открыть банку со сладкой кукурузой, отцедить зерна, промыть, обсушить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2028,'Натереть зубчики чеснока, перемешать с майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2029,'Яблоки очистить от кожуры и натереть или нарезать тонкими слайсами. Отложить их в сторонку, предварительно сбрызнув немного лимонным соком, чтобы не потемнели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2029,'Тесто для пирога очень мягкое и послушное. Для начала необходимо взбить яйца с сахаром в пышную пену. Затем ввести йогурт и размягченное масло. Массу тщательно размешать и соединить с мукой и разрыхлителем. Вымесить мягкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2029,'Противень подойдет с высокими бортиками. Обсыпать противень молотыми сухарями или мукой. Раскатать не тонко тесто и уложить в противень, захватив борта. Тесто должно равномерно расположиться по дну и бортам противня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2029,'Взбить миксером сметану, желтки и половину сахара, отставить в сторону. Затем взбить белки и вторую половину сахара в пышную пену. Соединить две части заливки и аккуратно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2029,'Уложить яблоки по тесту, не до верха, и залить пирог «Неженка» с яблоками сметанной смесью. Противень поставить в разогретую духовку на 45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Яйца отварить, белки натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Шампиньоны очистить и нарезать, обжарить до румянца, перемешать с белками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Куриное мясо отварить, остудить и нарезать кубиками, перемешать с рубленым зеленым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Часть зелени оставить для украшения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Продукты выложить в салатницу, перемешать с майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Отваренные желтки перемешать с луком и майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Картофель очистить, нарезать соломкой, обжарить во фритюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Выложить на бумажные салфетки для впитывания жира.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Закуску выложить на сервировочную тарелку, сформовать углубление в центре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Вокруг выложить брусочки картофеля, посыпать рубленой зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2030,'Сформовать из желтковой массы яйца, наполнить ими углубление в центре.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Яйца отварить вкрутую, охладить, очистить и разрезать на четыре части каждое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Нашинковать кубиками репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Измельчить промытый шпинат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Разрезать шампиньоны на четыре или шесть частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Обжарить до корочки, выложить в салатницу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Добавить на сковороду растительное масло, спассеровать лук до мягкого состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Выложить в емкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Хлеб нарезать мелкими кубиками, посыпать куркумой и паприкой, обжарить на той же сковороде с маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Добавить в грибы шпинат, побрызгать лимонным соком, посолить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Оставить для настаивания на несколько минут, добавить часть сухарей.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Массу перемешать двумя вилками, посыпать оставшимися сухариками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2031,'Выложить закуску в порционную посуду, добавить по разделенному яйцу.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Сливочное масло нарезать, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Сырые куриные яйца перемешать с сахаром, муку вмесить порциями, комочки разбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Форму смазать маслом, вылить полужидкое тесто, разровнять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Ягоды вымыть, обсушить, посыпать сахарным песком, дать постоять до появления сока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Жидкость слить, ягоды всыпать на тесто ровным слоем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Поставить пирог в духовой шкаф, печь при температуре 200 градусов, время -  от тридцати пяти до пятидесяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2032,'Выпечку вынуть, остудить, вынуть из формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2033,'Для приготовления торта подойдет любая глубокая тара, от формы тары будет зависеть красота и вид торта. Готовые сладкие рулеты с начинкой порезать очень тонко и уложить кусочками всю тару, не пропуская ни сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2033,'Творог взбить миксером в пышную массу, постепенно добавляя сахар. Охлажденные сливки хорошо взбить и добавить сахар. Растворить желатин в холодной воде. Соединить творог, сливки и желатин, еще раз тщательно перемешать. Добавить фрукты кусочками в массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2033,'Выложить всю творожную массу в форму, усланную рулетами. Сверху прикрыть одним коржом. Поставить королевский торт с творогом в холодильник. На следующий день из формы аккуратно достать торт, перевернув его вверх ногами. Получится, что торт будет стоять на корже, а рулеты сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Маргарин хорошего качества натереть на терке, перемешать с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Добавить погашенную уксусом или лимонным соком соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Массу перемешать, добавить муку порциями, вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Форму для выпекания смазать маслом, выложить тесто, сформовать бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Перемешать ягоды брусники с сахарным песком, лишний сок слить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Выложить в тесто, поставить изделие в духовой шкаф на тридцать минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2034,'Готовый пирог остудить и нарезать на порции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Дрожжевые гранулы растворить в подогретой воде. Вода должна быть теплой, но не горячей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Растопить маргарин на водяной бане, перемешать с сахаром и сырым яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Влить дрожжи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Всыпать муку порциями, тесто должно получиться густым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Накрыть массу полотенцем, оставить в тепле на три часа. Тесто два раза обмять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Вынуть продукт из емкости, еще раз обмять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Четверть теста отрезать, оставить, остальную массу раскатать в лепешку толщиной в один сантиметр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Выложить на смазанный маслом противень, сформовать небольшой бортик.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Свежие или мороженые ягоды брусники засыпать сахарным песком, поставить на тихий огонь, проварить несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Когда начинка даст сок – всыпать молотую корицу и гвоздику, перемешать, огонь погасить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Массу остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Выложить на тесто.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Оставшуюся четверть теста тонко раскатать, накрыть пирог, края защипать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Другой вариант – нарезать раскатанное тесто полосками, выложить сеточку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2035,'Пирог выпекать в течение двадцати пяти минут, температура – 200 градусов. Выпечку остудить.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2036,'Бруснику вымыть, обсушить, пересыпать сахаром, крахмалом и корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2036,'Готовое слоеное тесто раскатать, выложить в форму, всыпать начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2036,'Оставшимся тестом произвольно украсить пирог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2036,'Печь при температуре 200 градусов, время – двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2036,'Готовый пирог посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2037,'Куриное филе нарезаем на полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2037,'В миску (или глубокую тарелку) перекладываем куриное филе, солим, перчим. Добавляем приправу для курицы, все по вкусу. Затем добавляем сметану, перемешиваем. Оставляем на 20 минут для маринования.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2037,'В другую глубокую тарелку засыпаем панировочные сухари. И в этой миске панируем куриные палочки, перекладываем на противень, на который нужно положить коврик для запекания или пергамент. Отправляем в разогретую духовку при 200°С до готовности. Следите за приготовлением - корочка должна быть румяной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2038,'150 гр. заранее просеянной нутовой муки соединить с 1/2 ч.л. соли и 300 мл теплой воды. Хорошо смешать. Поместить в холодильник на 2-8 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2038,'Измельчить 1/2 ч.л. семян кумина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2038,'Далее добавить 1 ст.л. растительного масла и 1/2 ч.л. молотого кумина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2038,'Смазать сковороду растительным маслом. Жарить так же как и обычные блины, периодически перемешивая массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2038,'Для начинки. Размять вилкой 1 среднее спелое авокадо. Добавить 1 ч.л. лимонного сока, 1-2 ч.л. оливкового масла, 1/3 ч.л. горчицы, 1/4 ч.л. кориандра, 1/4 ч.л. смеси перцев и 1/4 ч.л. соли. Смешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2039,'Для тефтелей необходимо отварить рис до полуготовности. Смешать фарш, рис, яйцо и специи. Вымесить фарш для тефтелей и разложить на порционные кружочки. Каждую тефтелю обвалять в муке. Обжарить тефтели на растительном масле с двух сторон и сложить в противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2039,'Для приготовления вкуснейшего белого соуса следует обжарить муку на сковороде, добавив масло. Кипяченое горячее молоко постепенно вливать в сковороду с мукой, постоянно помешивая, чтобы не было комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2039,'Массу кипятить на сковороде пару минут. Отставить с огня и добавить взбитые желтки, перемешать. Залить соусом горячие тефтели и отставить для пропитывания. Нежные мясные тефтели в белом соусе прекрасно сочетаются с любым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Мягкое сливочное масло перемешать с сахарным песком, ванилином из пакетика, вбить сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Добавить муку и разрыхлитель, замесить крутое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Массу выложить в форму, сформовать бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Вымыть ягоды, высыпать на основу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Заготовку отправить в духовой шкаф на полчаса или чуть больше, температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2040,'Взбить сметану с сахаром. Залить смесью пирог, дать постоять два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Размягченное сливочное масло перемешать с яйцом, сахарным песком, сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Отдельно перемешать муку с разрыхлителем и ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Всыпать сухую смесь в яичную.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Массу вымесить, в ней не должно быть комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Выложить тесто в смазанную форму, сформовать бортики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Мягкий сливочный сыр взбить с яйцами и сахаром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Нарезать яблоко кубиками, высыпать на тесто в один слой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Далее – вымытые ягоды брусники.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Залить продукты творожной массой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Сверху насыпать оставшиеся ягоды.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Яблочные дольки красиво выложить по кругу поверх ягодного слоя.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Время выпекания пирога – тридцать пять минут, температура – 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2041,'Пирог остудить, при подаче нарезать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Компоненты для домашнего теста должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Перемешать яйца с жирной сметаной, растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Добавить соль и сахар, дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Всыпать муку порциями, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Все операции можно проделать при помощи хлебопечки. Масса не должна липнуть к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Поставить продукт в тепло, затем обмять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Листья щавеля промыть и обсушить, нарезать, жесткие стебельки удалить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Растопить на сковороде сливочное масло, выложить щавель, посыпать сахарным песком, потушить до мягкости, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Тесто разделить на куски, раскатать небольшие лепешки, выложить начинку, защипать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Выложить пирожки на противень, шов – внизу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Поверхность смазать желтком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2042,'Время выпекания – от пятнадцати до двадцати минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Сухие дрожжи перемешать с сахарным песком, влить теплую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Подождать, пока дрожжи не «заработают».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Добавить растительное масло, всыпать муку, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Емкость накрыть мокрым полотенцем, масса должна подойти два или три раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Щавель нарезать, припустить с добавлением воды или масла, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Добавить сахарный песок и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Сформовать пирожки на присыпанном мукой столе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Жарить с маслом на сковороде, огонь – средний.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Другой вариант – приготовить пирожки в кастрюле или в сотейнике, в большом количестве масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2043,'Готовность выпечки определяется появлением золотистой корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'В большой емкости перемешать одно яйцо с домашней сметаной, всыпать сахар и соль, добавить мягкое сливочное масло комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Массу вымесить, она не должна липнуть к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Завернуть продукт в пищевую пленку, убрать в морозилку или в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Два яйца отварить в течение десяти минут, охладить, очистить, измельчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Добавить нарезанный зеленый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Отдельно припустить с маслом или водой измельченный щавель.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Остудить, смешать с луком и яйцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Соль и перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'На столе раскатать кусочки теста, сформовать пирожки, защипать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Противень смазать маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Выложить изделия.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Смазать маслом, крепким сладким чаем или желтком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2044,'Время выпекания – двадцать минут, прогреть духовой шкаф до 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Влить воду, оставить на полтора часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Погасить пищевую соду в стакане кефира, всыпать сахар и соль, вбить свежее яйцо, добавить мягкое сливочное масло или хороший маргарин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Всыпать муку высшего качества, замесить тесто, оно должно быть мягким и упругим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Отдельно нарезать вымытый щавель, потушить с маслом и сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Сахар должен раствориться, щавель – осесть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Присыпать мукой стол, раскатать тесто, вырезать лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Выложить сочную начинку, защипать, печь на сковороде с растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Жарить по три минуты с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2045,'Далее – закрыть выпечку крышкой, подержать одну минуту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Тушку птицы отварить с пряностями или овощами: морковью, луковицей, зубчиками чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Насыпать в пиалу желатин, влить бульон, оставить на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Срезать верхушку от полуторалитровой бутылки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Разобрать тушку на волокна, удалить кости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Набухший желатин соединить с оставшимся бульоном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Поставить на водяную баню, прогреть, но не кипятить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Мясные кусочки выложить в миску, перемешать с чесноком, влить бульон с растворенным желатином.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Массу перемешать, по желанию добавить соль и приправы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Выложить мясо в бутылку, затянуть пищевой пленкой, поставить в холод в вертикальном положении на пять часов или на всю ночь. Рулет должен застыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Нижнюю часть срезать, емкость разрезать вдоль, вынуть готовый продукт.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Для диетического варианта блюда подойдет грудка.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2046,'Для сытного сальтисона добавить в состав сало или бекон.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Для начала нарезаем куриное филе на небольшие кусочки. Затем в хорошо разогретой с маслом сковороде обжариваем его.  Не забываем посолить и поперчить. Буквально 5-6 минут и курица готова. В конце накрываем крышкой и оставляем на выключенной плите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Теперь приготовим правильный соус. Берем майонез, добавляем сметану, немного горчицы для любителей, затем пропускаем чеснок через пресс, немного свежего укропа и тщательно перемешиваем. Соус готов. Густой, ароматный и пикантный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Следом нарезаем помидоры на тонкие дольки.  Огурец нарезаем  соломкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Собираем наш цезарь-ролл. Кладем лаваш на большое плоское блюдо. На него наносим небольшое количество кетчупа. Распределяем при помощи ложки. Присыпаем тертым сыром. Выкладываем обжаренную курицу и сдабриваем сверху нашим чесночным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Следом кладем измельченный салат «Айсберг», затем слой помидоров и слой огурцов. И снова немного соуса и сыра.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2047,'Подготовленные роллы обжариваем на хорошо разогретой сухой сковороде. Буквально пара минут и образуется аппетитная румяная корочка.И сыр внутри немного расплавляется. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Куринные окорочка отварить с солью и пряностями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Остудить, отделить мясо от костей, нарезать мелкими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Грибы нарезать брусочками небольшого размера, обжарить вместе с нарезанным луком до испарения жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Желатин залить подогретым бульоном, прогреть до растворения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Смешать мясо с грибами, бульоном и специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Выложить массу в пластиковую бутылку без горлышка, оставить в прохладе на пять или шесть часов, до застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2048,'Тару разрезать, переложить рулет на блюдо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Морковь нарезать кружками, выложить в пластиковую бутылку вместе с мясом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Влить бульон, поставить тару в холод до застывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2049,'Для начала необходимо протопить молоко с творогом. Для этого следует соединить молоко с творогом и кипятить 15 минут на медленном огне, помешивая деревянной лопаткой, чтобы не подгорал творог. Потом снять молоко с огня и процедить творог через сито. Пусть творог полежит, чтобы стекла сыворотка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2049,'Далее следует соединить мягкое масло с содой и яйцом в глубокой кастрюле на медленном огне. Масло должно растаять, тогда высыпать молочный творог. На очень медленном огне варить массу примерно 5 минут, помешивая, чтобы не подгорал творог. При сильно сухом твороге можно влить немного сыворотки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2049,'После идеального соединения всех ингредиентов, массу пересыпать в подготовленную форму. Форма должна иметь дырочки, чтобы стекала сыворотка. Когда сыворотка перестанет течь, сыр следует убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2049,'Домашний твердый сыр из творога и молока готов на следующие сутки. Жирность сыра регулируется жирностью творога, из которого сделан сыр. Если сыр любите соленый, то в процессе приготовления необходимо добавить 1 чайную ложку соли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Куриное филе отварить в воде с солью, лавровым листом и душистым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Мясо нарезать кусочками небольшого размера, выложить в емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Измельчить сладкий болгарский перец, вместе со сладкой кукурузой из банки обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Добавить к мясу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Любую зелень мелко нарезать, добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Прогреть бульон, развести желатин, влить в мясо с овощами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Добавить любимые приправы, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Срезать горлышко с пластиковой бутылки, заполнить массой, поставить в холодильник на восемь часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2050,'Достать, вынуть закуску, нарезать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'тварить курицу, добавить соль и пряности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Нарезать мясо кусочками, удалить кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Продукт подсушить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Обжарить рубленые орехи с нарезанным черносливом и чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Добавить продукты к мясу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Разбавить желатин теплой водой, долить к основным ингредиентам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Перемешать, заполнить массой пластиковую бутылку без горлышка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Поставить в прохладу до застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2051,'Разрезать бутылку, подать закуску на блюде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Отварной картофель натираем на крупной терке и выкладываем на плоское блюдо первым слоем. Я делаю 2 слоя картофеля. Смазываем картофель соусом из майонеза и сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Отварную морковь натираем на крупной терке и выкладываем вторым слоем. Смазываем слой соусом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Куриную грудку отвариваем и нарезаем небольшими кубиками. Выкладываем следующим слоем и смазываем соусом. Как правило, я делаю 2 слоя куриного филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Следующий слой - тертый сыр и сметанно-майонезный соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Далее снова куриное филе и соус из сметаны и майонеза.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2052,'Символом Красной Шапочки у нас будут зерна граната. Щедро присыпаем верхушку салата и украшаем кайму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2053,'Банан разомнем вилкой. Добавим растопленное сливочное масло и сахар, перемешаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2053,'Яйцо взобьем в пышную пену и добавим к банановой смеси. Аккуратно перемешаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2053,'Муку просеиваем через сито и добавим в общую массу, перемешаем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2053,'Половину порции шоколада измельчаем ножом, остальная часть пойдет на украшение в растопленном виде.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2053,'Выпекаем в разогретой духовке при температуре 180 градусов 20-25 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2054,'Чесночный соус готовится довольно быстро и легко. Сначала, в растопленном сливочном масле потомите мелко нарезанный чеснок, для придания специфического аромата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2054,'Затем в это масло добавьте ложку муки и обжарьте на сковороде, помешивая, чтобы не было комочков. Вливайте понемногу сливки, непрерывно помешивая. Соус начнет загустевать, поэтому следует следить, чтобы он не пригорел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2054,'В конце следует добавить немного воды, посолить и поперчить по вкусу, можно кинуть 1 лавровый лист. Отставьте готовый соус в сторону. Морковь натереть на крупной терке, лук порезать полукольцами. Обжарить овощи на растительном масле до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2054,'Картофель почистить и порезать кольцами 0,5 см. Уложить картофель на противень, смазанный растительным маслом, посолить, поперчить. На картофель уложить форель, заранее посоленную и присыпанную любимыми специями для рыбы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2054,'На рыбу выложить морковь с луком и залить чесночным соусом. Форель в чесночным соусом на картофеле будет готовиться в духовке 45 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2055,'Промоем молодой картофель и порежем на несколько частей. Кожуру оставляем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2055,'Приготовим маринад: смешаем масло, чеснок, соль, перец молотый, карри и паприку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2055,'Выложим нарезанный картофель в большую емкость и перемешаем с маринадом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2055,'Выкладываем картофель в жаропрочную форму или на противень в один слой, чтобы картофельные дольки хорошо пропеклись.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2056,'Творог натираем через сито, добавляем сметану, сахарную пудру. Хорошо перемешиваем до тестообразной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2056,'Манго, киви и грушу нарезаем соломкой. Можно взять клубнику и ананас. Будет не менее вкусно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2056,'Подготовим циновку (как для суши), положим сверху пленку или пакет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2056,'Затем выкладываем блин. Намажем творожной массой. Выкладываем полоски киви, манго и груши.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Сырое куриное мясо нарезать брусками, выложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Нарезать небольшими кубиками сладкий болгарский перец и помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Перемешать с мясом, посолить, поперчить, добавить нарезанный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'В пакет для запекания выложить мясо с овощами, влить полтора литра воды, края скрепить с помощью зажима.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Выложить пакет в мультиварку, выставить режим «Выпечка» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Переложить готовый продукт в пластиковую бутылку, поставить в холод на шесть часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2057,'Тару срезать, закуску выложить на тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Куриную грудку нарезать кубиками, выложить на сковороду вместе с лавровым листом, давлеными зубчиками чеснока, приправами и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Влить воду, потомить мясо в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Желатин из пакетика залить подогретой водой, подождать до разбухания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Смешать состав с бульоном, прогреть на бане.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Мясо остудить, перемешать с бульоном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Массу выложить в пластиковую бутылку и поставить ее в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2058,'Пластик удалить, заливное выложить на блюдо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Приобрести в магазине набор для приготовления холодца из курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Если его нет – использовать тушку курицы небольшого размера, хрящи, крылья, кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'По желанию можно использовать курицу и индейку в равных пропорциях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Залить мясные ингредиенты водой, варить два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Бульон не кипятить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'В середине приготовления массу посолить, выложить морковь, корень петрушки, репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Добавить горошины перца, лавровый лист и зелень за пять минут до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Мясо и овощи вынуть, петрушку и лук выбросить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Бульон процедить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2059,'Мясо поделить на волокна, убрать все лишнее, перемешать с рубленым чесноком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Нашинковать репчатый лук, сладкий перец и морковь нарезать соломкой, томаты – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Куриное филе нарезать одинаковыми кусочками среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Добавить соль и перец, специи, перемешать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'В литровую банку продукты поместить слоями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Сверху – ложечка жира или кусочек сливочного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Между слоями добавлять лавровый лист и перец-горошек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Емкость закрыть крышкой или фольгой, поставить в духовой шкаф, прогревать с нулевой температуры вместе с банкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2060,'Довести до 180 градусов, запекать от полутора до двух часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Курицу разрезать на части, посолить, поперчить, посыпать специями для куриного мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Чеснок очистить и порубить, полить соевым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Смесью заправить курицу, подержать под пленкой или крышкой сорок минут или дольше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Картофель очистить, разрезать на четыре части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Добавить соль, специи, полить растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Выложить в литровую банку слоями, добавить нарезанный кольцами репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Накрыть фольгой, перевязать ниткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Прогреть духовку до 180 градусов, застелить противень махровым полотенцем. Выставить банку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Время запекания – от полутора часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2061,'Духовку выключить, подержать в ней банку еще пятнадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'В большую миску выложить творог.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'Добавить яйца, снова пробить с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'Добавить кукурузный крахмал, перемешать венчиком до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'Добавить тыквенное пюре, корицу, имбирь и мускатный орех, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'Форму для выпечки слегка смазать растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2062,'Вылить тыквенно-творожную смесь в форму, разровнять тесто и отправить в разогретую до 180°С духовку на 35 минут. Дать запеканке остыть, вынуть из формы и подавать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Разрезать курицу на куски, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Очистить сладкий перец и репчатый лук, нарезать ломтиками средней величины, так же нарезать помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Выложить в литровую банку слоями: мясо, лавровый лист и перец-горошек, овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Повторить несколько раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Накрыть фольгой горлышко емкости, запекать при температуре 180 градусов, время – полтора часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2063,'Остудить, выложить на тарелку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Вымыть и нарезать ломтиками курицу, репчатый лук – кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Перемешать продукты, посолить, заправить лимонным соком, посыпать приправами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Оставить мариноваться на час при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Влить минеральную воду на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Нанизать мясо на шпажки вместе с луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Выложить маленькие шашлыки в банку, накрыть фольгой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Поставить в холодную духовку, довести до 150 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2064,'Подать шашлык горячим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2065,'Для приготовления печенья следует замочить в кефире на 40 минут овсяные хлопья. Изюм необходимо промыть и запарить в кипятке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2065,'Замесить тесто из всех ингредиентов и выложить порции теста на противень, застланный пергаментной бумагой. Диетическое овсяное печенье выпекать полчаса, пока не зарумянится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Курицу вымыть, протереть полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Банку наполнить водой на три четверти, положить пряности, соль, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Натереть тушку солью и молотым перцем внутри и снаружи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Усадить на банку, крылья обернуть фольгой, чтобы не обгорели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Время приготовления – один час, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2066,'Поливать стекающим жиром или соевым соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Голову промыть и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Залить водой, добавить ножки и кусочки мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Оставить продукты на три или четыре часа, жидкость поменять два раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Положить в кастрюлю корень сельдерея и петрушки, специи, соль, чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Добавить вымоченные субпродукты и мясо, влить свежую воду, варить четыре часа, пенку снимать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Нарезать мясо и хрящики кусочками. Соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Переложить продукты в формы из силикона, залить процеженным бульоном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2067,'Оставить в холоде на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Свиной желудок промыть от слизи, оставить на восемь часов в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Всыпать в желудок кукурузную крупу, помять руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Оставить на сорок минут мокрым полотенцем. Крупу смыть рукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Эти манипуляции избавят желудок от неприятного привкуса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Свиную голову вымыть, поскоблить острым ножом. Удалить уши, глаза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Голову разрубить на куски, залить водой, варить четыре или пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Сменить воду на свежую, варить четыре часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Всыпать в емкость с мясом, перец, дольки чеснока, соль, ломтики репчатого лука, лавровый лист. Время варки – один час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Мясо удалить из бульона, нарезать мелкими кусочками, соль – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Наполнить массой желудок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Зашить отверстие кулинарными нитками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Бульон отцедить, довести до кипения, вылить в желудок с начинкой, варить в течение час, огонь – минимальный.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Запечь желудок в течение получаса в духовом шкафу, температура – средняя.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2068,'Поставить на изделие груз, остудить, переместить в холодное место на семь или восемь часов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Свиную голову промыть и очистить, разрубить на восемь частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Язык отдельно замочить в соленой холодной воде на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Все куски, включая язык, залить водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Добавить нарезанный крупными ломтиками лук и морковь, чеснок, специи, лавровый лист и соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Субпродукты варить пять или шесть часов на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Снять кожицу с языка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Мясо порубить средними кусочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Овощи и кости выбросить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Застелить форму марлей, ткань должна быть свернута в пять или шесть слоев.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Сверху выложить жир и мясо, добавить специи и соль по желанию.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2069,'Марлю завязать узлом. Заготовку прижать грузом, оставить в холоде на одиннадцать часов. Марлю снять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Очищенную свиную голову нарезать крупными кусками, выложить в чашу мультиварки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Добавить очищенный чеснок, коренья из бульона, специи и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Мясо варить в соответствующем режиме в течение семи или восьми часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Продукт разобрать на кусочки, кости выбросить вместе с чесночными головками и кореньями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Выложить готовый субпродукт в несколько слоев марли под груз, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2070,'Оставить в холоде на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Свиной желудок подготовить – вымочить и подержать с кукурузной крупой, затем ее смыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Голову промыть, нарезать крупными кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Отварить субпродукт с солью, лавровым листом, специями. Время приготовления – пять часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Мясо снять с костей, досолить по необходимости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Набить желудок мясными кусочками, зашить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'В бульоне, оставшемся от варки головы, сварить желудок с субпродуктами. Время кипячения – чуть больше часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2071,'Блюдо запечь в духовке до румянца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Голову свиньи очистить и разрубить на восемь частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Влить холодную воду, довести до кипения, жидкость поменять на свежую.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Всыпать перец, лавровый лист, дольки чеснока, соль, специи, морковь и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Варить пять часов на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Желудок вывернуть, вымыть, удалить слизь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Влить в желудок лимонный сок, натереть солью крупного помола.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Промыть через пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Влить оставшийся лимонный сок, добавить лавровый лист, перец-горошек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Насыпать разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Натереть субпродукт изнутри кукурузной крупой, промыть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Мясо отделить от костей, снять с языка пленку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Мясо порезать кусочками небольшого размера.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Перемешать с измельченным чесноком и кусочками сала.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Перец молотый и соль – по вкусу, перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Желудок набить мясом со специями, зашить отверстие.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Варить в бульоне, оставшемся от приготовления головы, время – полтора часа.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2072,'Выложить продукт под гнет на три часа.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Свиную голову очистить, удалить язык, замочить субпродукты в очень холодной воде на три с половиной часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Жидкость несколько раз поменять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Мясо промыть еще раз, залить новой порцией воды, варить пять часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Всыпать соль, специи, лук, морковь, сельдерей, часть зубчиков чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Снять с костей мясо, очистить от пленок язык.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Субпродукты нарезать кусочками, добавить оставшийся чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Переложить мясо в пластиковую бутылку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Влить процеженный бульон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2073,'Выложить емкость в холодильник на ночь. Удалить пластик.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'У кочана капусты вырезать сердцевину, положить в кипящую воду, подсолить, готовить несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Снять верхние листы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Постепенно снимать с кочана листья и класть на тарелку, чтобы остыли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Отварить рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Обжарить шампиньоны и лук, в конце посыпать приправами для грибов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Крупно потереть морковь, обжарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Порезать оливки на кольца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Все соединить и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/0d/8debce4cbac190d_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Завернуть начинку в капустные листья.','https:https://st.vkuso.ru/data/cache/thumb/22/28b0a4522dee622_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Чуть-чуть обжарить голубцы, выложить в форму.','https:https://st.vkuso.ru/data/cache/thumb/e7/ea2caf79439a4e7_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'На них положить обжаренную морковь, полить постным майонезом.','https:https://st.vkuso.ru/data/cache/thumb/84/4f7f4c100c81784_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2074,'Готовить 20 минут, соблюдать температуру 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Заранее отварите картофель, после этого картофель превращаем в пюре! Для пюре можно использовать молоко, или картофельный отвар. Солим по вкусу. Убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Лук нарезаем на соломку, слегка обжариваем и смешиваем с пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Яйцо куриное можно смешать с молоком и взбить (Молоко необязательно)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Сливочное масло нужно растопить в микроволновке и смешать с молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Лаваш нарезаем на равные квадраты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'Эти квадраты из лаваша нужно смазать смесью из масла и молока, и дать им немного пропитаться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2075,'На лаваш укладываем картофель, при помощи рук приминаем его, и заворачиваем в конверт. Перекладываем на противень, смазываем взбитым яйцом с молоком и посыпаем кунжутом, отправляем в духовку на 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2076,'Для приготовления теста следует закислить молоко уксусом. Для этого в стакан молока следует влить ложку уксуса, когда молоко свернется, отставить. Смешать все сухие ингредиенты: в муку высыпать соду, разрыхлитель и какао. Мягкое масло размять с сахаром, добавлять по одному яйца. Все тщательно размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2076,'Соединить все ингредиенты, вымесить жидкое тесто. Шоколадное тесто вылить в форму, застеленную пергаментной бумагой и выпекать 30 минут при температуре 200 градусов. Готовность коржа проверить спичкой. Охлажденный корж разрезать на две равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2076,'Крем для торта «Южная ночь» подойдет любой, со сгущенкой, ириской, сметанный, заварной или масляный. Самый вкусный и легкий крем, со сгущенкой. Сливочное масло взбить миксером с половиной банки сгущенки, промазать обильно коржи. Верх торта залить растопленным шоколадом. Если глазурью не заливать, тогда торт украсить шоколадной крошкой или фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Добавить в молоко воду. Но можно использовать молоко без воды, тогда получится более сливочный вкус. С водой получаются диетические манники.','https:https://st.vkuso.ru/data/cache/thumb/5c/b5c7917309f3f5c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Поставить молоко на плиту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Насыпать сахар и соль.','https:https://st.vkuso.ru/data/cache/thumb/d1/9e5c4d36b1a6fd1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Когда жидкость начнет закипать, насыпать тоненькой струей манную муку.','https:https://st.vkuso.ru/data/cache/thumb/7c/be80b0a167b3a7c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Готовить, время от времени помешивая, чтобы не было комков. Должна получиться густая каша. Охладить.','https:https://st.vkuso.ru/data/cache/thumb/87/5d6fe0f2da0b087_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Отдельно взбить венчиком яйцо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Перелить взбитое яйцо в кашу.','https:https://st.vkuso.ru/data/cache/thumb/36/0aacd4395698b36_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Каша обязательно должна быть холодной, чтобы яйцо не свернулось.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Размешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/ee/d28182094061bee_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Можно использовать панировочные сухари из магазина или сделать самим: потереть на терке черствый батон, чтобы получилась крупа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Скатать из манной массы шарик, обвалять в сухарях, формируя котлетки круглой формы.','https:https://st.vkuso.ru/data/cache/thumb/39/a127b7e5b0db139_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Обжарить манники на растительном масле с каждой стороны по несколько минут.','https:https://st.vkuso.ru/data/cache/thumb/84/3155a8fa6cce884_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2077,'Этого времени достаточно, чтобы схватилось яйцо, так как манка уже была в готовом виде.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Почистить кальмары, удалить хорду, порезать на тоненькие полоски, налить устричный соус и терияки.','https:https://st.vkuso.ru/data/cache/thumb/c1/02cff08e7f20cc1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Перемешать, отправить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/23/86c08780c11ea23_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Вымыть рис, откинуть на сито. Хорошо обсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Налить в кастрюлю с толстым дном 250 миллилитров воды, насыпать рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Накрыть крышкой, довести до кипения, готовить на тихом огне 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Убрать с плиты. Дать постоять под крышкой 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/50/e5ae4708d945850_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Смешать сахар, соль, рисовый уксус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Положить равномерным тоненьким слоем, остужая, медленно полить рисовым уксусом. Не перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'После остывания рис примет любую форму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Сделать 4 рисовые котлетки, обжарить на растительном масле, можно использовать специальные формы для котлет.','https:https://st.vkuso.ru/data/cache/thumb/7a/41849defb88f97a_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Выложить на салфетку, чтобы впиталось лишнее масло.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Положить на сковороду чеснок, чуть-чуть обжарить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Положить к чесноку кальмары.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Накрыть крышкой на минуту.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Перемешать, положить паприку, лук, чили, томатный соус. Размешать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Корректировать вкус, можно насыпать чуть-чуть сахарной пудры.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Жарить на большом огне 4 минуты.','https:https://st.vkuso.ru/data/cache/thumb/c3/48ca72bbc021cc3_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Убрать с огня. На 10 минут накрыть крышкой.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2078,'Собрать рисовый бургер и подавать.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Порезать куриное филе на кусочки по 2 сантиметра.','https:https://st.vkuso.ru/data/cache/thumb/ae/58b41e99c3d11ae_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'В емкости соединить соевый соус, кунжутное масло, сахар. Необходимо использовать именно эти ингредиенты – в них вся тонкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Положить в смесь кусочки мяса.','https:https://st.vkuso.ru/data/cache/thumb/6e/3b7c1d00d0e956e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Перемешать курицу, накрыть пленкой, отправить в холодильник минимум на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Измельчить чеснок, острый чили, белую часть зеленого лука порезать на полоски по 3 сантиметра.','https:https://st.vkuso.ru/data/cache/thumb/72/f196d017d033472_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Вместо чили можно использовать сладкий перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'На горячей сковороде нагреть ложку оливкового масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Положить маринованную курицу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Обжаривать мясо партиями, чтобы кусочкам было просторно на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/ce/bc52536156729ce_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Обжаривать 4 минуты, переворачивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Когда появится корочка, переложить курицу на тарелку, обжаривать следующую партию.','https:https://st.vkuso.ru/data/cache/thumb/25/39719ae31107f25_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Обжарить чеснок 40 секунд, чтобы появился запах.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Положить лук, чили, жарить несколько минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Посыпать перцем.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2079,'Добавить кусочки мяса, жарить 4 минуты.','https:https://st.vkuso.ru/data/cache/thumb/26/d7e96f983443e26_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2080,'В горячем молоке (не кипяченом) развести пасту Нутеллу, взбить миксером на малых оборотах. Охлажденные сливки взбить с сахарной пудрой, чтобы получилась пышная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2080,'В бокал налить горячий шоколад с маршмеллоу и выложить взбитые сливки, сверху присыпать тертым шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Порезать картофель на кубики, положить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Полить оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Соединить приправы: чесночный порошок, соль, паприку, перец, пармезан.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Посыпать смесью картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Перемешать руками, чтобы все кубики были смазаны смесью сыра и специй.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2081,'Готовить картофель 45 минут, соблюдать температуру 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Нагреть духовку, готовить картофель 45-60 минут.','https:https://st.vkuso.ru/data/cache/thumb/3a/ecbc0c21efc693a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Снять кожуру, потереть картофель.','https:https://st.vkuso.ru/data/cache/thumb/75/e06bcf49740a875_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Намазать сливочным маслом или побрызгать растительным формы для маффинов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Положить в них по 3-4 больших ложек тертого картофеля. Прижать картофель к краешкам формочек, чтобы получились корзинки.','https:https://st.vkuso.ru/data/cache/thumb/a3/a07d0327f90d8a3_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Готовить в духовке 15-20 минут. Важно следить, чтобы корзинки не подгорели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Достать из духовки, остудить.','https:https://st.vkuso.ru/data/cache/thumb/b2/a46636c95201cb2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Во все корзинки вбить по яйцу, посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/5c/7c02ce4fad3e35c_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Готовить в духовке 15 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2082,'Достать картофельные корзинки из формочек при помощи ножа.','https:https://st.vkuso.ru/data/cache/thumb/1a/f5bb6b5e2900a1a_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Поломать и растопить шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Подсушить орехи на сухой сковороде, почистить фундук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'В растопленный белый шоколад налить сгущенное молоко, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Добавить сок лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Положить кокосовую стружку, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Положить обжаренные орехи, размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Полученную массу вымешать деревянной лопаткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Постелить в форму пищевую пленку, положить орехово-шоколадно-клюквенную массу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Мокрыми руками приплюснуть массу, равномерно распределить по форме.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Накрыть пленкой, отправить на несколько часов в холодильник или на полчаса в морозилку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2083,'Достать и порезать батончики из белого шоколада со сгущенкой, фундуком и клюквой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Взбить масло и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Вбить яйца, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Налить ром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Насыпать муку, посыпать солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Сформировать пласт прямоугольной формы, завернуть в полиэтилен, отправить на несколько часов в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Достать тесто, раскатать толщиной 3-4 сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Вырезать круги на 1-2 сантиметра больше, чем диаметр тарталеток.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Сделать тарталетки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Положить начинку, накрыть тестом, закрепить краешки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Намазать желтком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Готовить 20 минут, соблюдать температуру 175 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2084,'Остудить пирожкам и подавать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Почистить и порезать тыкву на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Соединить оливковое масло и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Почищенный чеснок и тыкву перемешать с ароматным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Положить на противень, застеленный пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Готовить 20 минут, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Довести до кипения сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Положить готовую тыкву в сливки, взбить до однородности при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Накрыть крышкой, отставить на 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2085,'Посыпать сливочный крем-суп из запеченной тыквы с чесноком тыквенными семечками и сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Вымыть и почистить картофель, порезать на кольца прямо в сухую форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Посыпать картофель специями, солью.','https:https://st.vkuso.ru/data/cache/thumb/5e/2465d0856a3155e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Сверху посыпать крупно тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/e7/d75c2c7dd8b3ce7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'На сыр положить слой картофеля, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Приготовить сливочно-молочную заправку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Положить на горячую сковороду сливочное масло. Когда оно растает, насыпать муку, размешать.','https:https://st.vkuso.ru/data/cache/thumb/9c/1fa6c39b45f949c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Подержать на сковороде до золотистого оттенка.','https:https://st.vkuso.ru/data/cache/thumb/ee/f885df00673a3ee_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Постепенно налить молоко, перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/15/487290f7d7b0015_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Варить 3-4 минутки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Вылить заливку на картофель, посыпать ароматными приправами.','https:https://st.vkuso.ru/data/cache/thumb/57/1f8e8f5c5b17057_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Отправить на 30 минут в духовку. Можно посыпать сверху сыром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Для заправки сделать соус из прессованного чеснока, зелени и сметаны.','https:https://st.vkuso.ru/data/cache/thumb/0e/d4a808bfafc360e_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2086,'Полить готовый картофельный эскалоп соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'збить белки и щепотку соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Осторожно ввести сахар, вбить по одному желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Отдельно соединить какао, муку, соду и медленно подмешать к яичной массе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Переложить тесто в форму намазанную маслом, отправить на 30 минут в духовку, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Полностью остудить корж.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Приготовить крем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Взбить желтки с сахаром до белого цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Насыпать крахмал и ванилин, налить молоко.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Довести смесь до густоты на тихом огне, помешивая.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Убрать с огня, остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Чтобы не было комков, можно взбить крем миксером.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'В холодный крем положить масло, порезанное на куски, взбить миксером до однородного состояния.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Намазать бисквит кремом, отправить на 30 минут в холод.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Приготовить глазурь: растопить шоколад, поломанный на куски и молоко.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Перемешать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Когда шоколад растает, положить сливочное масло.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Довести до однородности, остудить.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Когда остынет глазурь, крем на бисквите остынет, покрыть торт глазурью.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2087,'Отправить на 60 минут в холодильник.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Залить манную крупу молоком, положить цедру лимона, насыпать ванильный сахар, варить до густоты на тихом огне. Помешивать венчиком, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Убрать кашу с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Переложить в другую посуду, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Перетереть творог через сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Можно налить 20 миллилитров ароматного ликера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Взбить яйца и сахар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Соединить манку, смесь из яиц, творог. Размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Намазать дно формы маслом, посыпать мукой или манкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Положить тесто, распределить равномерно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Почистить яблоки от семечек и кожуры, разрезать на 4 части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Сделать на дольках глубокие надрезы по вертикали.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Чтобы яблоки не потемнели, побрызгать соком лимона.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Положить яблоки в тесто, немного вдавить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Намазать мягким сливочным маслом, присыпать сахаром.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2088,'Готовить запеканку на манной каше с яблоками и творогом 60 минут, соблюдать температуру 170 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2089,'Для приготовления чизкейка необходимо создать «платформу», на которой будет лежать сырная масса. Для этого печенье перетереть с мягким сливочным маслом или маргарином и сахаром. Форму для чизкейка выложить этой массой и немного примять, поставить в холодильник для застывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2089,'Сыр взбить с сахаром и желатином. Желатин должен набухнуть в этой массе. Затем в сыр добавить кусочки персика и взбитые в пышную массу сливки, аккуратно все перемешать. Сырную массу выложить в форму на печенье и распределив по всей поверхности, поставить назад в холодильник. Через пару часов вкуснейший чизкейк с персиком готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Подогреть сыворотку, насыпать муку, вымесить. Смесь должна получиться, как густая сметана, но литься на сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Нагреть сковороду, в центр налить тесто, распределить по всей поверхности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Накрыть крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2090,'Перевернуть блин, накрыть крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2091,'Сварим в подсоленной воде картофель,морковь и куриные яйца. Остужаем эти продукты и почистив нарезаем их небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2091,'Селедку чистим от кожуры и костей (если Вам неохота возиться с селедкой, то для простоты Вы можете сразу купить готовое филе слабосоленой селедки). Селедку я нарезаю на кубики среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2091,'Чистим красный салатные лук. Лук можно нарезать четверть кольцами, я же буду нарезать его тонкими полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2091,'И напоследок измельчаем зелень (я в этот салат добавляю только свежую зелень укропа) Вы же можете использовать любую зелень на Ваш вкус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2091,'Отправляем все подготовленные ингредиенты в миску и заправив майонезом хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Яблоки нарезать кубиками.','https://vkuso.ru/data/cache/data/2b/8ebfbb4420d2e2b_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Растопить на сковороде 30 г сливочного масла, выложить яблоки, добавить, сахар и корицу. Перемешать и тушить на среднем огне до полного испарения жидкости.','https://vkuso.ru/data/cache/data/01/b4ae8879c631d01_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Добавить к яблокам измельченные грецкие орехи. Перемешать.','https://vkuso.ru/data/cache/data/b0/593d8d770018db0_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Слоеное тесто (у меня дрожжевое, но можно использовать и бездрожжевое тесто) раскатать в тонкий пласт, толщиной примерно 2 мм.','https://vkuso.ru/data/cache/data/3a/42906bd5aa06c3a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'На тесто выложить начинку и равномерно распределить.','https://vkuso.ru/data/cache/data/9e/c0b13c1ff466d9e_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Свернуть в рулет, края защипнуть.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2092,'Готовый штрудель посыпать сахарной пудрой. И можно подавать к чаю.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Размять творог при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Положить в блендер яйца, творог, мед, сахар, взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Нагреть до 200 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Выложить массу на блюдо, смазанное сливочным маслом и посыпанное мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Готовить 45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2093,'Присыпать запеканку корицей, отправить в духовку на 3-4 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Порезать хлеб на маленькие кубики, положить на противень, подсушивать 20-25 минут, соблюдать температуру 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Помешивать, чтобы сухарики не подгорели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Сделать фарш.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Измельчить в блендере лук и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Соединить фарши в емкости, положить лук и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Налить воду, посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Порезать на кубики сливочное масло, положить в фарш, вымесить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Сформировать небольшие котлетки, обвалять в сухарях, отправить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Сделать соус: измельчить чеснок, лук.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Обжарить на оливковом масле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Положить томаты, мед, варить 15 минут, помешивая.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Убрать соус с плиты, посыпать перцем, солью, перемешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Обжарить котлеты по 3 минуты с каждой стороны.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Переложить на противень, застеленный пергаментом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Отправить в духовку на 12-13 минут, соблюдать температуру 180-190 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Перебрать листья салата, вымыть, просушить, порвать на крупные куски.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Крупно порезать помидоры, соединить с базиликом и листьями салата.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Заправить оливковым маслом.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2094,'Посыпать перцем, солью.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'Нагреть духовку до 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'Соединить в большой емкости сахар, муку, соль, разрыхлитель, мускатный орех и корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'В другую посуду положить масло, яйца, тертый кабачок, ваниль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'Перемешать. Высыпать мучную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'Наполнить массой формочки на ¾, посыпать корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2095,'Готовить кабачковые маффины 30 минут до появления корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Замесить тесто, отправить в тепло на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Обмять и дать тесту подняться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Поделить тесто на маленькие кусочки, сделать шарики, отправить в форму, отставить на 10-15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Готовить в духовке 10-12 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Приготовить соус: почистить и измельчить чеснок, посолить, налить оставшееся масло, добавить измельченную зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2096,'Полить пампушки чесночным соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Взбить подтаявшее масло и сахарную пудру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Вбить яйцо, насыпать муку, смешанную с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Чтобы тесто получилось рассыпчатым и нежным, его нужно замесить быстро, долго не месить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Если месить долго, то тесто будет плотным, тягучим и может развиться клейковина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Из теста сделать лепешку, завернуть в пленку, отправить на 30-40 минут в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Поделить тесто на куски, пропустить через мясорубку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Веревочки из теста равномерно распределить на противне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Выпекать 20 минут, соблюдать температуру 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Когда веревочки станут румяными, перемешать, выпекать еще 5 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Чуть-чуть остудить, переложить в большую посуду, покрошить, добавить вареную сгущенку, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2097,'Разложить по формочкам.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Приготовить курицу: отварить или чуть-чуть обжарить уже готовую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Порезать капусту на тоненькие полоски.','https:https://st.vkuso.ru/data/cache/thumb/52/fbff17890e65452_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Порезать помидоры на небольшие дольки.','https:https://st.vkuso.ru/data/cache/thumb/fb/33d9dd8a38816fb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Мелко потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/16/19eef91451f4b16_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Отваренную курицу поделить на маленькие кусочки вдоль волокон','https:https://st.vkuso.ru/data/cache/thumb/57/2194858d02eea57_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2098,'Приготовить соус. Измельчить в блендере майонез, чеснок, зелень и две капли лимонного сока.','https:https://st.vkuso.ru/data/cache/thumb/16/29bf78ab9533916_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2099,'Тесто для торта готовиться в несколько этапов. Сначала следует взбить яйца с сахаром в пышную пену. Потом растопить (не кипятить) маргарин. Теплое молоко соединить с кофе. Просеянную муку соединить с содой, разрыхлителем, ванильным сахаром, какао. Все ингредиенты смешать в одной посуде и вымесить тесто, по консистенции, как густая сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2099,'Подготовленный противень услать пергаментной бумагой и смазать бумагу растительным маслом. Тесто вылить в противень и равномерно распределить по всей площади. Выпекать корж полчаса в разогретой до 200 градусов духовке. Готовый корж вынуть из духовки и поставить остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2099,'Для крема следует смешать сметану с сахаром, добавить яйцо и муку и поставить массу на водяную баню. Когда крем загустеет снять с огня и остудить. Сливочное масло взбить миксером, постепенно добавляя остальной крем. Холодный корж разрезать по горизонтали на несколько частей. Промазать каждый корж вишневой прослойкой и заварным кремом. Сверху залить шоколадной глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2099,'По заварному крему можно делать рисунки из шоколада. Для этого плитку шоколада растопить на водяной бане, добавив немного сливок, положить жидкий шоколад в кондитерский мешок и с фантазией нарисовать по торту рисунки. По желанию можно украсить сверху вишней. Шоколадный торт с вишней и масляно-заварным кремом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'Положить творог в тарелку, размять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'Потереть или мелко порезать банан.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'Положить к творогу. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'Постелить на противень специальную бумагу или намазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'С помощью ложки выложить творог.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2100,'Готовить 10-15 минут при средней температуре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Порезать кабачок на дольки, перец на кубики.','https:https://st.vkuso.ru/data/cache/thumb/84/3004f3ba1dc5284_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Рыбу порезать на кубики.','https:https://st.vkuso.ru/data/cache/thumb/13/7adf03dc183d213_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Снять лимонную цедру.','https:https://st.vkuso.ru/data/cache/thumb/d8/64af19bf65c3ed8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Измельчить укроп.','https:https://st.vkuso.ru/data/cache/thumb/4a/f419d6f3d5a214a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Отправить на полчаса в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Мелко натереть яблоки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Сделать маринад: соединить цедру, укроп, сок половины лимона, оливковое масло.','https:https://st.vkuso.ru/data/cache/thumb/9b/20e3f42a615a59b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Положить в чашу рыбку, овощи. Посыпать перцем, солью, полить маринадом.','https:https://st.vkuso.ru/data/cache/thumb/6d/4ff5a18e757966d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Перемешать, отставить мариноваться на 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Постелить на противень специальную бумагу или намазать маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Положить деревянные шпажки на 10 минут в воду.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Наколоть на шпажки кусочки рыбы и овощей по очереди.','https:https://st.vkuso.ru/data/cache/thumb/fa/71fa3e1a3e3cefa_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Положить шашлык на противень, отправить в духовку на 7-10 минут под гриль.','https:https://st.vkuso.ru/data/cache/thumb/89/01d96fea77dfd89_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2101,'Если отсутствует режим «Гриль», то готовить 10-15 минут, соблюдать температуру 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Растопить шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Кисточкой нанести тоненький слой шоколада внутри формочек (желательно использовать силиконовые).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Отправить в морозилку минут на 10.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Если получились пробелы, то снова нанести шоколад на эти места и отправить в морозилку еще на несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'В это время растереть творог с сахарной пудрой, мягким сливочным маслом и ванилином.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Достать формочки, наполнить на 1/3 творожной массой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'В середину положить начинку, заполнить творогом до конца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2102,'Покрыть творог растопленным шоколадом, поместить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Пласты замороженного теста порезать на двенадцать прямоугольников.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Раскатать их, с противоположных сторон сделать надрезы.','https:https://st.vkuso.ru/data/cache/thumb/1d/f0ca9b83dfdb11d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Почистить и вымыть картофель. Отварить в соленой воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Приготовить из картофеля пюре, добавив 30 грамм масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Огурцы порезать на маленькие кубики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Мелко порезать мясо, обжарить, посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Добавить лук, порезанный на полукольца, готовить под крышкой 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Убрать крышку, готовить на большом огне, пока не испарится жидкость.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Положить на тесто столовую ложку картофеля, распределить равномерно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'На картофель положить мясо, сверху огурцы.','https:https://st.vkuso.ru/data/cache/thumb/0f/cbd4fb097ef850f_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Свернуть тесто по очереди с двух сторон, чтобы разрезы получились посередине пирожка – друг над другом.','https:https://st.vkuso.ru/data/cache/thumb/4d/91081aaf60e244d_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Защипнуть краешки, чтобы получилась форма лодочки.','https:https://st.vkuso.ru/data/cache/thumb/09/3a2e7564628e109_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Намазать противень маслом, постелить специальную бумагу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Положить лодочки, посыпать сыром, намазать взбитым яйцом.','https:https://st.vkuso.ru/data/cache/thumb/13/25c1ab263659d13_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2103,'Готовить лодочки со свининой и картофелем 15-25 минут, соблюдать температуру 200 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Порезать мясо на кусочки приблизительно 5 на 5 сантиметров.','https:https://st.vkuso.ru/data/cache/thumb/43/4c115b4f997a343_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Мариновать мясо в приправах и соке лимона 30 минут.','https:https://st.vkuso.ru/data/cache/thumb/00/9d0f2532a157900_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Накалить казан, налить растительное масло, нагреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Положить мясо, подрумянить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Залить пивом, готовить 5-7 минут.','https:https://st.vkuso.ru/data/cache/thumb/f6/b27e7f51303a3f6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Выложить слоями порезанные овощи.','https:https://st.vkuso.ru/data/cache/thumb/af/260516e7c72c3af_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Каждый слой посыпать солью: морковь, лук, картофель, помидоры, баклажаны, перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Поставить казан на средний огонь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Томить под крышкой 2 часа, пока жидкости не станет мало.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Время от времени подкладывать поленья, но казан не должен сильно накаляться.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'В конце посыпать измельченным чесноком, размешать, накрыть крышкой, убрать с огня.','https:https://st.vkuso.ru/data/cache/thumb/00/bdfd23f18392a00_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2104,'Настоять армянскую хашламу с пивом в казане 5-7 минут, разложить по тарелочкам, посыпать зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Положить в емкость уваренные ягоды, добавить свежие ягоды и яблоки, отжав предварительно сок. Перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2105,'Растереть в кастрюле желтки с сахаром, мукой и ванилином до однородного состояния. В отдельной посуде молоко довести до кипения. Влить его к яйцам, непрерывно помешивая. Поставить кастрюлю на плиту и варить, пока заварной крем  не загустеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Размять вилкой или натереть плавленый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'С куриного окорочка снять мясо, обжарить и положить к сыру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Отварить яйца, потереть, добавить к мясу с сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Добавить к ингредиентам корейскую морковь и измельченный укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Заправить майонезом, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Расстелить на столе лаваш, тоненьким слоем нанести салат, свернуть в рулетик, отложить на 30 минут, чтобы пропитался.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Можно завернуть рулет в пленку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Перед подачей снять пленку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2106,'Порезать закуску из лаваша с окорочком и корейской морковью на порционные куски.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2107,'Нагреть на сковороде оливковое масло, насыпать сухой рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2107,'Готовить, помешивая, пока рис не побелеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2107,'Налить чуть-чуть кипящей воды, тушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2107,'Порезать корень имбиря, пожарить с соевым соусом на второй сковороде. Положить креветки, готовить пару минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2107,'Соединить обе массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Нагреть растительное масло, насыпать муку, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Медленно налить стакан молока, довести до кипения, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Положить тертый сыр, помешивать непрерывно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Посыпать приправами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Добавить подтаявшее сливочное масло, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2108,'Полить подливой макароны или потушить их в соусе несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Раскатать тесто в одном направлении.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Вырезать два квадрата со сторонами по 15 сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Положить на противень, застеленный пергаментом или на коврик для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Чуть-чуть надавливая ножом, обвести бортик, отступив от края 1 сантиметр (тесто до конца не прорезать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Сделать проколы вилкой.','https:https://st.vkuso.ru/data/cache/thumb/cc/b278d336b1d32cc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Порезать оливки и ветчину на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/85/7a9458d2e60a985_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Крупно потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/ce/337678a6dba0ece_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Разложить оливки, сыр и ветчину по тесту, не выходя за бортики.','https:https://st.vkuso.ru/data/cache/thumb/6b/982aa735a138f6b_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Готовить 12-15 минут, соблюдать температуру 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Вынуть из духовки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'На каждую слойку разбить яйцо.','https:https://st.vkuso.ru/data/cache/thumb/22/00a7fff3262b322_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Посыпать перцем, солью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Вернуть на 5-7 минут в духовку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2109,'Посыпать слойку с ветчиной, сыром и глазуньей измельченной петрушкой.','https:https://st.vkuso.ru/data/cache/thumb/53/c6e957d61bf3153_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Взбить яйца, растопленное масло, сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Насыпать муку, просеянную с солью и какао. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Отправить тесто на полчаса в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Приготовить блинчики на сливочном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Переслоить порции блинов пастой Nutella, ягодами и ореховой крошкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2110,'Украсить орехами, сахарной пудрой, топингом, ягодами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Нагреть духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Порезать яблоки на небольшие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Намазать форму маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Разложить порезанные яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Растереть яйца и сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Просеять муку, насыпать остальные продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Залить смесью яблоки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2111,'Отправить в духовку на полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Вымыть ягоды, удалить косточки. Данный пирог готовится из замороженных ягод (голубики, малины, красной смородины, ежевики).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Разделить ягоды на 2 части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Одну часть уварить, чтобы испарилась жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Приготовить тесто: насыпать в емкость муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Положить порезанное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Перетереть в крошку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Насыпать сахар, ванилин. Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Насыпать крахмал (если начинка жидкая, то добавить крахмал с горкой, если густая, то без горки). Размешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Насыпать сахар по вкусу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Если ягоды кислые, то 160 грамм, если сладкие, то 120 грамм. Перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Постелить в разъемную форму диаметром 24 сантиметра специальную бумагу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Тесто поделить на две части.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Большую часть раскатать, чтобы получился пласт диаметром приблизительно 30 сантиметров.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Выложить пласт в форму, сформировав бортики.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Положить начинку, распределить равномерно.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Раскатать тесто поменьше в пласт примерно 25 сантиметров.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Вырезать фигурки формочкой, например, стаканом.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Одну в середине и пять по краям.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Переместить пласт на пирог, используя скалку. Защипнуть края.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Остальные фигурки выложить на тесто.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Намазать пирог белком.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Во все отверстия положить по кусочку масла. Тогда начинка не вытечет во время приготовления.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Готовить 40-45 минут, соблюдать температуру 180 градусов.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Вынуть пирог из духовки, провести по краю ножам, чтобы удалить кольцо.',NULL,28);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Остудить пирог.',NULL,29);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Переложить в холодильник, чтобы начинка хорошо застыла.',NULL,30);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2112,'Можно есть пирог сразу в теплом виде. Тогда начинка будет жидковатой, но вытечь не должна.',NULL,31);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Натереть цедру апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Налить в емкость апельсиновый сок. Можно использовать готовый или выжать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Насыпать манную крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Размешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Насыпать сахар, добавить растительное масло. Размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Положить цедру апельсина. Размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Отставить на 20-30 минут, чтобы набухла манка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Насыпать соду. Размешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Просеять муку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Насыпать маленькими порциями, каждый раз помешивая.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Должно получиться тесто без комков, по консистенции, как сметана.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Намазать форму маслом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Посыпать панировочными сухарями или мукой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Налить тесто в форму.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Отправить в духовку на среднюю полку.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2113,'Готовить 40 минут, соблюдать температуру 180-190 градусов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'На горячей сухой сковороде обжаривать 2 минуты орехи, измельчить блендером или скалкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Размягчить сливочное масло, соединить с ванильной сахарной пудрой. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Насыпать ½ сахарной пудры, добавить орехи, размешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Соединить муку и разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Насыпать постепенно в масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Непрерывно перемешивать до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Замесить тесто, завернуть в полиэтилен, отправить на 30 минут в холод.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Отрезать от теста небольшие куски, сделать шарики, приплюснуть в виде печенья.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'На противень постелить пергамент, выложить печенье.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Готовить 20 минут, соблюдать температуру 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Необходимо следить за готовностью печенья, так как оно может приготовиться раньше.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Обвалять чуть-чуть остывшее печенье в смеси корицы и сахарной пудры.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2114,'Остудить и подавать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Почистить картофель от кожуры. Если он молодой, то можно не чистить, а просто помыть щеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Порезать на очень тоненькие кружки. Удобно использовать для этого овощерезку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Положить на пергамент один слой картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Посыпать специями, солью, измельченной зеленью (можно сушеной).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Отправить в микроволновую печь на 5 минут, готовить на максимальной скорости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Или в духовку под гриль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2115,'Когда чипсы станут золотистыми, они готовы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Почистить и вымыть картофель. Отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Вымыть и порезать грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Почистить, вымыть, измельчить лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Обжарить лук и грибы на растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Приготовить из картофеля пюре, добавив чуть-чуть овощного бульон, в котором готовился картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Посыпать солью, специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Остудить грибы, перемолоть в мясорубке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Посыпать перцем, солью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Нагреть духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Намазать форму растительным маслом, выложить 1/3 картофельного пюре.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'На картофель положить шампиньоны, вторую часть пюре.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Тоненьким слоем выложить на пюре порезанные помидоры.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'На них положить слой оставшегося картофеля.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Сверху намазать постным майонезом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2116,'Готовить постную картофельную запеканку с помидорами и грибами приблизительно 40 минут до румяной корочки, соблюдать температуру 180 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Разморозить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'В это время почистить и измельчить соленый огурец, зеленый лук, бекон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Растянуть тесто руками, проколоть вилкой в нескольких местах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Положить слой половины сыра, зеленый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Чуть-чуть обжарить бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Выложить слой бекона с соленым огурцом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Посыпать сыром, оформить края, чтобы получился пирог.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Залить сверху яйцами, взбитыми со сметаной, солью и перцем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Соли добавлять немного, потому что огурцы, сыр и бекон сами по себе соленые.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Готовить 35 минут, соблюдать температуру 190-200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2117,'Края пирога можно намазать сырым яйцом, чтобы они стали румяными.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2118,'Взять сухую кастрюлю с толстым дном. В нее разбить 4 яйца, перемешать с сахаром.  Поставить кастрюлю на плиту и начать нагревать. При этом непрерывно помешивать, не отходя от кастрюли. Как только яйца образуют густую массу, снять их с огня и пока не остынут помешивать. В миску насыпать сахарную пудру, взбить в ней масло сливочное. Яичную смесь добавить к масляной. Добавить в масляный крем чуть ванили для вкуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Залить водой гороховые хлопья, готовить, пока не разварится. Это может занять 10-30 минут, в зависимости от вида гороха.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Можно использовать для приготовления горохового пюре гороховую муку или колотый горох.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Приготовленную смесь измельчить блендером до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Если необходимо, то налить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Должна получиться смесь, как жидкий кисель. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Налить в емкость растительное масло, добавить чуть-чуть гороховой смеси.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Необходимо взять 1 часть горохового «киселя» и 2 части оливкового масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Взбивать 30-60 секунд.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'В соус насыпать перец, сахар, соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Добавить горчицу, постепенно, чтобы не перекислить, налить уксус.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Взбивать 1-1,5 минуты. Соус должен стать плотным.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2119,'Проверить Гороховый майонез без яиц на вкус, если необходимо посыпать специями.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Порезать лук на средние кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Морковь порезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Нагреть в сковороде растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Положить лук и морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Порезать говядину на средние кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Положить в сковороду на овощи. Готовить 20-25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Налить в сковороду кипяченую воду, рассчитывая 2 стакана воды на стакан риса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Посыпать специями, перцем, солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Когда закипит вода, добавить рис.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Готовить на большом огне, чтобы ½ жидкости выкипела.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2120,'Накрыть сковороду крышкой, готовить сытный плов с говядиной на сковороде на тихом огне 15-20 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Почистить орехи, перебрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Измельчить при помощи мясорубки, блендера или просто потолочь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Масса должна быть мелкой и однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Опустить овощ в кипящую воду, варить шесть минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Положить к орехам кинзу, измельченный чеснок, базилик, растереть все до однородности. Проще это делать деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Положить в посуду с ореховой смесью в любой последовательности красный перец, шафран, хмели-сунели, измельченный кориандр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Довести соус до густоты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Развести кипяченой холодной водой массу, налить гранатовый сок или винный уксус по вкусу, посыпать солью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Густоту выбирать в зависимости от назначения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Если он предназначен для заправки овощного соте, то делать соус, как жидкая сметана. Для рыбных и мясных блюд делать соус более густым.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Порезать баклажаны на кольца толщиной 1-1,5 сантиметра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Намазать растительным маслом, выложить на бумагу для выпечки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Готовить в духовке по 5-7 минут с каждой стороны.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Достать баклажаны, разложить на салфетку, чтобы впиталось масло.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Положить по 1-2 маленькой ложки орехового соуса на кусочки баклажанов в виде горки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2121,'Украсить зеленью.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Почистить и вымыть лук, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Почистить и вымыть морковь, крупно потереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Налить в кастрюлю 3 ложки растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Положить лук, жарить, перемешивая, несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Добавить морковь, готовить 3 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Вымыть грибы, порезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Налить в сковороду 3 ложки растительного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Положить грибы, тушить, помешивая, 5-6 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'К моркови и луку насыпать муку и положить томатную пасту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Налить чуть-чуть воды.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Готовить несколько минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Соленые огурцы порезать на кубики.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Положить их к овощам, размешать, готовить 5 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Положить обжаренные грибы. Готовить 5 минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Залить маслины кипяченой водой, посыпать перцем и солью, положить лавровый лист.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Готовить солянку 7-10 минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Вымыть и измельчить зелень.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Перед подачей посыпать суп.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2122,'Положить в тарелки по кусочку лимона.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Взбивать масло несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Соединить соду и сметану, когда смесь начнет пузыриться, перелить в масло, порциями насыпая муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Взбить творог и сахар до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Поделить тесто на 40 частей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Из каждой сформировать овал, положить полосой начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Свернуть рулетиком, защипнуть краешки, придать вид банана.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Разложить печенье на противень, застеленный пергаментом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2123,'Готовить до легкой румяности, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Отправить воду в холодильник, насыпать в нее соль, размешать до растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'В емкость просеять муку, сформировать углубление.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Медленно подливая воду, замесить некрутое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Положить тесто и оставшуюся муку на доску, вымесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Тесто постное, поэтому его необходимо вымешивать более 20 минут, чтобы оно вобрало всю муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Накрыть тесто, отставить на 20 минут, чтобы оно набухло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Перемешать, сформировать колбаску, порезать на одинаковые куски (приблизительно, как орех).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Раскатать куски в лепешки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Разложить начинку, защипнуть краешки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2124,'Готовить вареники 5-7 минут в подсоленной воде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Пропустить мясо курицы через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Положить в фарш измельченный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Добавить белки, сливки, посыпать специями, вымесить до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Первый способ приготовления: положить подготовленный фарш в фольгу, завернуть, завязать кончики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Фольгу завернуть в два слоя полиэтилена, кончики завязать нитью, чтобы в фарш не попала вода.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Облить ледяной водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Отварить куриные яйца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Налить в кастрюлю воду, чтобы она покрыла колбасу, положить ее в воду, готовить 30-40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Достать из кастрюли, отправить колбаску в холодильник на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Второй способ приготовления: наполнить фаршем кишки. С одной стороны завязать нитью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'При помощи тоненькой иглы сделать несколько проколов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2125,'Положить домашнюю куриную колбасу со сливками в кипящую воду. Готовить при слабом огне. Охладить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Разделить белки и желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Взбить белки и сахарную пудру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Подмешать желтки и сухие ингредиенты, просеянные через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Постелить на противень специальную бумагу, вылить тоненьким слоем тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Готовить 10 минут, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Перевернуть коржик на влажное полотенце, намочить бумагу водой, чтобы легче было снять ее с коржа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Разрезать коржи пополам, скатать их с полотенцем в рулетик. Охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Приготовить начинку: соединить все ингредиенты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Положить начинку на коржи, сформировать рулеты, отправить на 60 минут в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2126,'Порезать холодные рулеты на части, посыпать корицей и сахарной пудрой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Почистить картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Вымыть и почистить перец от семян и сердцевины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Вымыть помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Порезать овощи на маленькие одинаковые кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Налить в сковороду оливковое масло, нагреть на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Положить картофель, готовить 5 минут, помешивая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Положить помидоры и болгарский перец, готовить 3 минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Посыпать специями (перцем, базиликом, измельченным чесноком).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Посыпать солью, добавить томатную пасту. Перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Сделать в овощной массе четыре отверстия, осторожно влить в каждое углубление по яйцу, стараться, чтобы желток не повредился.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2127,'Сделать минимальный огонь, посолить яйца, жарить до готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2128,'80 гр. овсяных хлопьев небыстрого приготовления и 40 гр. кокосовой стружки измельчить в блендере, импульсами, чтобы стружка не выделила масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2128,'К 550 гр. творога добавить 2 яйца, 3 ч. л. сахара, 1 ч. л. ванильного сахара, 1 щепотку соли и измельченные сухие ингредиенты. Смешать до однородности. Оставить на 5-10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2128,'Застелить противень пергаментом (или смазать маслом). Выложить творожную массу на противень при помощи 2-х ложек, периодически смачивая их в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2128,'Выпекать в разогретой до 180 °C духовке в обычном режиме, 20 минут. Затем еще 10 минут при 180°C в режиме конвекции (верх). До румяности. Если режим конвекции у вашей духовки отсутствует, то их следует перевернуть спустя 20 минут после начала выпекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2129,'Слоеное тесто раскатывать не нужно, я его нарезал на равные части. Всего у меня было 2 пачки слоеного теста, по 2 пласта. Из этих 4 пластов теста у меня вышло 12 равных частей. Как только нарезали тесто на равные части, перекладываем на противень и отправляем в духовку при 190°С, на 20 минут, пока тесто не подрумянится и не поднимется!',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2129,'В это время, пока тесто в духовке, можно приготовить крем. Я его сделал из сгущенки и сливочного масло, получилось очень вкусно. Для начала я переложил масло в миску, взбил его до бела, примерно минут 5. Потом соединил со сгущенкой, и довел до кремовой основы. Убирал в сторону, можно убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2129,'Спустя время, достал коржики, отрезал верхнею корочку, которая подрумянилась, переложил в миску и часть, которая осталась, я осторожно разделил на 2 части. Переложил на тарелку. Из верхней части я сделал крошку для посыпки пирожных.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2129,'Взял коржик, намазал кремом, и сверху положил еще 1 корж, и снова намазал, и так еще 2 раза, потом смазал бока пирожного и обсыпал его тем, что сделал ранее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2129,'Данные пирожные можно убрать в холодильник на час.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2130,'Свеклу отварить и натереть на крупной терке.','https://vkuso.ru/data/cache/data/15/196922a4f115815_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Остудить в холодной воде, очистить, нарезать дольками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2130,'Куриную печень обжарить на сковороде до готовности.','https://vkuso.ru/data/cache/data/7b/6cdc9d5e7dd937b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2130,'Нарезать соломкой.','https://vkuso.ru/data/cache/data/87/3801a3be28e5a87_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2130,'В глубокой миске смешать натертую свеклу, печень, измельченную зелень петрушки или кинзы, чеснок (тоже предварительно измельчить), соль. Заправить растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2130,'Переложить салат в салатницу и сверху посыпать измельченными грецкими орехами.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2131,'Мягкое сливочное масло взбить со сгущенкой. В процессе взбивания добавить постепенно желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2132,'Картофель моем, чистим, промываем, нарезаем. Затем его нужно отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2132,'Сыр натираем на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2132,'Лук тонко нарезаем кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2132,'Мясо свинины сначала нарезаем на порционные кусочки, потом отбиваем. Солим, перчим и посыпаем приправой для мясо по вкусу. Оставляем на 20 минут, чтобы мясо пропиталось специями. Затем выкладываем мясо на противень (у меня меня стеклянный) смазываем его сметаной с майонезом, укладываем лук, посыпаем сыром. Отправляем в разогретую духовку при 190°C на 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2132,'Как только картофель приготовился, толчем в пюре. Добавляем молока и солим, и еще немного доводим до пюре. Закрываем крышкой, убираем сторону.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Соединить сливки, яйца, соль и зелень, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Приготовить омлет на горячей сковороде, намазанной маслом. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Намазать чуть-чуть майонезом, сформировать рулет, порезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Порезать мясо на средние кусочки, отбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Намазать чесноком, перцем, солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Положить на кусочки мяса по куску омлета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Свернуть рулетики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Намазать форму, разложить рулеты, рядом положить картофель, порезанный на кружочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Отправить на 20 минут в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Достать, залить сливками, готовить 30 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2133,'Достать мясные рулетики с омлетом в сливках, намазать чесночно-укропным маслом (смесь укропа, чеснока и сливочного масла).',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Весь отмеренный сахарный песок разделить на шесть частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Насыпать одну часть в сотейник с толстым дном, растопить до золотистого цвета, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Добавить еще столько же сахара, снова растопить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Повторить процедуру несколько раз, пока весь сахар не расплавится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Емкость можно наклонять в разные стороны, но содержимое не перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'В другом сотейнике жирные сливки довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Карамель снять с огня, добавить в неё сливочное масло, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Влить горячие сливки, еще раз перемешать. Соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Сотейник вернуть на огонь, нагреть до 108 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2134,'Перелить готовый продукт в глубокую миску, накрыть пищевой пленкой так, чтобы она касалась поверхности, поставить в холод на 12 часов или на сутки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'Креветки очистить, хвостик и голову удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'Отварить в кипятке в течение от одной до четырех минут, до изменения цвета на розовый.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'В блендер выложить свежий укроп, соус «Табаско», мелко нарезанный репчатый лук, любой майонез, очищенные креветки и соль по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'Взбить ингредиенты до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'Пасту нанести на хлеб, можно использовать багет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2135,'Подать бутерброды со свежими помидорами и огурцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Свиное филе нарезать ломтиками толщиной в полтора сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'В каждом кусочке сделать горизонтальный надрез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'В каждый разрез положить консервированные ананасы и немного сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Кармашки закрепить зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Натереть филе молотым перцем и солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Отдельно взбить сырое куриное яйцо, посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Грибы крупно нарезать, добавить в основную массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Каждый кармашек окунуть в яйцо и в панировочные сухари, выложить на заранее разогретую сковороду с растительным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2136,'Жарить с двух сторон по 10 – 12 минут, накрыть крышкой и подержать на тихом огне еще пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2137,'Шоколад растопить на водяной бане, смазать им силиконовые формочки, поставить в морозильную камеру на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2137,'Если есть необходимость – процедуру повторить, замазать «пробелы» и вновь поставить формы в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2137,'Растереть творог с ванилином, сахарной пудрой, мягким сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2137,'Формы достать из морозилки, наполнить на треть объема творожной массой, положить в центр начинку, заполнить творогом до конца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2137,'Десерт сверху смазать остатками растопленного шоколада, убрать в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Отделяем белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'В желтки добавляем сахар и с помощью венчика или миксера взбиваем до тех пор, пока желтки не посветлеют.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Белки взбиваем до твердых пиков.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Форму застилаем бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Ставим форму для выпечки на противень и низ формы закрываем фольгой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Отправляем пирог в разогретую до 170°С духовку на 40 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2138,'Отправляем пирог в холодильник на час, затем вынимаем его из формы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Собираем все ингредиенты. Рис промываем до прозрачности воды, заливаем водой и варим после закипания 15 минут на небольшом огне. Дальше готовим заправку для риса. К рисовому уксусу добавляем соль, сахар и мешаем до полного растворения сахара и соли.','https://vkuso.ru/data/cache/data/42/64ba745e5e02042_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Вливаем заправку в рис и хорошо все мешаем. К сыру Филадельфия добавляем соевый соус и хорошо мешаем.','https://vkuso.ru/data/cache/data/63/4e39479f0d59263_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Выкладываем салат на тарелке с помощью кондитерского кольца. Диаметр устанавливаем 20 сантиметров. Один лист нори обрезаем под размер кондитерского кольца и стелим на дно. Наверх выкладываем половину риса. Смачиваем вилку водой и равномерно распределяем. Рис смазываем половиной сыра.','https://vkuso.ru/data/cache/data/9e/3ab1da6728c939e_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Огурец нарезаем слайсами и выкладываем сверху. Середина огурца слишком влажная, ее убираем. Дальше нарезаем рыбу тонкими полосками и выкладываем на огурцы.','https://vkuso.ru/data/cache/data/f6/d07a24d10e959f6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Лист нори нарезаем мелко и смешиваем с оставшимся рисом. Распределяем сверху на рыбу.','https://vkuso.ru/data/cache/data/59/589f9680b9e1159_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Смазываем оставшимся сыром. Оставшуюся рыбу нарезаем кубика и выкладываем на верх. Равномерно распределяем и посыпаем сверху кунжутом. Салат накрываем пищевой плёнкой и отправляем в холодильник как минимум на 1 час.','https://vkuso.ru/data/cache/data/79/b1bc6c8ae71ac79_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2139,'Дальше нарезаем мокрым ножом и подаём к столу. Вот и всё, вкусный и красивый салат готов!','https://vkuso.ru/data/cache/data/bd/418e0d29ac4babd_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Печень хорошо промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Разогреть на сковороде сливочное масло, обжарить продукт в течение пяти минут, по окончании посолить и поперчить по вкусу. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Огонь выключить, субпродукт накрыть крышкой и оставить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Нарезать репчатый лук перышками, выложить в тарелку, полить винным уксусом со щепоткой сахара.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Зеленый горошек положить в кипяток, добавить по щепотке сахара и соли, варить в течение пяти минут, окатить ледяной водой, чтобы сохранился цвет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Промыть стручковую фасоль, кончики отрезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Стручки нарезать на кусочки по два-три сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Для приготовления заправки смешать оливковое масло с винным уксусом, крупной солью, молотым перцем, готовой горчицей. Перемешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Выложить на блюдо хорошо вымытые листья зеленого салата, сверху положить печень, фасоль, зеленый горошек, яйцо.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2140,'Полить заправкой, перемешать и подать к столу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2141,'Нужно взять масло сливочное, размягчить его при комнатной температуре, а потом, добавив сгущенное молоко, взбить до однородности. Охладить готовый крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'В большой емкости перемешать обычную или рисовую муку с картофельным крахмалом, сахарным песком и щепоткой соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Влить молоко, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Добавить в смесь растопленное сливочное масло и вбить куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Массу взбить с помощью венчика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Обжарить блины с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Для приготовления начинки перемешать творог, сгущенное молоко и сметану.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Намазать блины, один или несколько, расположить их внахлест.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'На край ближнего блинчика положить дольки очищенных бананов, свернуть в ролл, уплотнить его руками, нарезать кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Для соуса перемешать мягкое сливочное масло со сметаной, сахарным песком и какао-порошком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2142,'Смесь прогреть до однородного жидкого состояния, полить десерт и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Перемешать кворк или обычный мягкий творог со сметаной, сырым куриным яйцом, оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Отдельно смешать сухие ингредиенты: соль, муку, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Эту смесь добавить в творожную, перемешать до получения крутого теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Можно подлить немного молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Тесто разлить в формочки для кексов-маффинов, присыпать маковым семенем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Печь в предварительно разогретой духовке в течение 20 минут при температуре 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Готовность проверить деревянной палочкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Для начинки нарезать пластинками свежие огурцы, ветчину, зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2143,'Маффины разрезать поперек, прослоить перечисленными продуктами и сколоть зубочисткой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Рассыпчатую рикотту перемешать с сыром «Пармезан», солью, мукой, сырым куриным яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Приправить по вкусу молотым черным перцем, поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Разрезать спелые помидоры пополам, удалить семена.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Мякоть нарезать мелкими кусочками, сок отцедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Измельчить листья и стебли свежего базилика, перемешать с помидорами и перцем чили, освобожденным от семечек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Посолить и поперчить по вкусу, сбрызнуть оливковым маслом и винным уксусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Разогреть сковороду с антипригарным покрытием, добавить оливковое масло хорошего качества, рафинированное.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Выложить несколько ложек массы с рикоттой на некотором расстоянии друг от друга в виде пирожков, они не должны соприкасаться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Обжарить изделия до золотистой корочки, перевернуть лопаткой, обжарить с другой стороны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Готовые пирожки посыпать морской солью крупного помола и рубленым мускатным орехом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2144,'Сбрызнуть пирожки оливковым маслом, посыпать тертым сыром «Пармезан» и подать к столу в горячем виде вместе с овощным салатом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Налить оливковое масло в сковороду с высокими бортиками, добавить тмин и порошок карри, перемешать и прогреть в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Добавить куриное филе, нарезанное на кусочки, жарить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Курицу выложить на тарелку.','https:https://st.vkuso.ru/data/cache/thumb/e4/3c2d2dc071242e4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Вымыть яблоки, обсушить, нарезать дольками.','https:https://st.vkuso.ru/data/cache/thumb/73/9403d9c9ef7d773_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'В сковороду, где жарилось куриное филе, добавить репчатый лук, нарезанный полукольцами, чеснок и яблоки.','https:https://st.vkuso.ru/data/cache/thumb/d1/d13616f51538fd1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Все вместе жарить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Вернуть на сковороду курицу.','https:https://st.vkuso.ru/data/cache/thumb/d8/399d095a0656fd8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Через десять минут всыпать зеленый горошек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Курагу вымыть, обсушить на бумажных полотенцах, добавить в сковороду.','https:https://st.vkuso.ru/data/cache/thumb/d8/4bf3f3dd660ced8_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Положить замороженный зеленый горошек, влить полстакана воды или куриного бульона, добавить молотый перец и соль, перемешать, накрыть крышкой, потомить в течение пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/74/6a3e07fef9bb374_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2145,'Выложить смесь на тарелку и подать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Куриную грудку вымыть и отварить с солью до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Мясо остудить и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Тонкими полосками нарезать вяленые помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Маслины без косточек разрезать на половинки, пекинскую капусту – небольшими полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Для приготовления заправки перемешать оливковое масло с перцем и лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2146,'Все ингредиенты соединить, полить масляной заправкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Измельченный лук и чеснок обжарить на оливковом масле.','https:https://st.vkuso.ru/data/cache/thumb/d4/9738fd172baccd4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Добавить протертые томаты и приправить солью, перцем, зеленью, оливковым маслом.','https:https://st.vkuso.ru/data/cache/thumb/74/cc6b11b729c1d74_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Шляпки шампиньонов смазать соусом.','https:https://st.vkuso.ru/data/cache/thumb/5d/4279a93143fe15d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Выложить рикотту и твердый сыр.','https:https://st.vkuso.ru/data/cache/thumb/b5/2b011793af567b5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Сверху разложить нарезанные помидоры черри.','https:https://st.vkuso.ru/data/cache/thumb/6f/e6fe0144db8956f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Запечь блюдо при температуре 190 градусов при температуре 15 – 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2147,'Перед подачей блюдо украсить рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2148,'Измельчить 100 гр. овсяных хлопьев в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2148,'Размять вилкой 2 банана. Добавить 1/2 ч. л. соды гашеной 1 ст. л. яблочного уксуса. Далее добавить 1 щепотку соли, 50 гр. сахара и 1 ч. л. корицы и 50 мл. растительного масла. Смешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2148,'Затем добавить 100 гр. ц/з пшеничной муки, измельченные овсяные хлопья и 1 ч. л. разрыхлителя. Смешать. Добавить 50 гр. грецких орехов. Оставить на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2148,'При помощи двух ложек выложить тесто на противень, застеленный пергаментом. Придать заготовкам плоскую форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2148,'Выпекать в разогретой до 180°C духовке 18-20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2149,'Вскипятить молоко и ванильный сахар. В манку влить немного воды, смешать их вместе. Влить манку с водой в горячее молоко. Довести до кипения, медленно подогревая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2149,'Желток растереть тщательно с сахаром и маслом. Должна получиться пышная однородная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2149,'В нее добавить небольшими порциями манную кашу, взбивая постоянно венчиком. Если сделать это аккуратно, то крем из манной каши останется пышным и легким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2150,'В чашу блендера наливаем 300 мл молока.','https://vkuso.ru/data/cache/data/1f/f35b413470c641f_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2150,'Добавляем клубнику, если клубника замороженная - размораживаем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2150,'Взбиваем в блендере.','https://vkuso.ru/data/cache/data/00/1236743542c9900_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2150,'И все коктейль готов! Приятного аппетита!','https://vkuso.ru/data/cache/data/17/5c104dfe5ff4b17_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Подготовим овощи. Лук измельчить. У болгарского перца отрезать края. Вынуть сердцевину. Разрезать перец, и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Смешать соль, гранулированный чеснок, черный перец, белый перец и паприку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Нагреть масло в большой широкой чугунной сковороде (или в жаровне).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Выложите куриные бедра на сковороду кожей вниз. Жарить 4-5 минут, пока кожица не станет золотисто-коричневой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'На ту же сковороду добавить лук и болгарский перец. Жарить 3-4 минуты, пока овощи не станут мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Тем временем нарезать колечками охотничьи колбаски. Добавить к овощам охотничьи колбаски и готовить еще 2 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Добавить орегано, чеснок, томатную пасту. Перемешать, затем добавьте рис. Снова перемешать, чтобы рис полностью смешался с овощами и колбасками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Влить бульон, все перемешать, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Помидоры черри или коктейльные разрезать пополам.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2151,'Накрыть сковороду крышкой (или фольгой) и поставить в хорошо разогретую духовку до 180-200°C на 35-40 минут, пока рис не станет мягким. Ориентируйтесь на свою духовку
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Лук измельчить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Подготовить соус. К сметане добавить томатный соус (можно заменить томатной пастой разведенной водой с добавлением сахара, чтобы урегулировать кислоту), добавить горчицу и хорошего перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Разогреть на сковороде растительное и сливочное масло. Обжарить печёнку. Убрать печень на тарелку, на той же сковороде обжарить лук.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Добавить бренди, поджечь, через секунд 40-50 выпариться алкоголь и огонь погаснет. Можно не поджигать, тогда тушить несколько минут до выпарения алкоголя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Добавить соль, черный перец, белый перец, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'Влить соус, перемешать. Довести до кипения и тушить 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2152,'По желанию добавить немного воды, и тушить ещё минут 5.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Приготовим тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'В муку добавить соль. Растительное масло. Подошедшие дрожжи. Вторую половину воды.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Тем временем займёмся соусом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Добавить сахар, соль, орегано. Добавить сушеные томаты (можно обойтись без них), хорошо перемешать довести до кипения и тушить пару минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Подготовим начинку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Обжарить бекон до румяной корочки и слегка подсолить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Тесто увеличилось в 2 раза. Разделить его на 2 равные части.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Смазать основу соусом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2153,'Отправляем в разогретую до 220°C духовку на 10-15 минут, до готовности теста. Ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Нарезать кубиками ветчину и сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'В большую миску вбить яйца. Добавить сахар, соль, перец и взбить венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Добавить молоко и растопленное сливочное масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Добавить часть муки, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Добавить оставшуюся муку и разрыхлитель, перемешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Добавить ветчину и сыр, вмешать в тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2154,'Заполнить формочки для кексов тестом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Поместить капусту брокколи, чеснок и лук в кастрюлю, залить овощным бульоном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Бульон довести до кипения, накрыть крышкой, огонь уменьшить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Варить суп на тихом огне до мягкости в течение восьми минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Половину бульона и брокколи переложить в блендер вместе с половиной картофеля и орехами кешью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Все взбить до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Через час кушанье будет готово.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Перелить в другую емкость, то же самое повторить с остатками картофеля, брокколи и кешью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Суп накрыть крышкой, подогреть на тихом огне в течение 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Посолить, поперчить, всыпать красный перец по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Нарезать кубиками хлеб, корочки срезать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Обжарить гренки на сухой сковороде и посушить в духовом шкафу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2155,'Готовый суп подать с гренками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Мягкое сливочное масло растереть с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Вбить по очереди два сырых яйца и один дополнительный белок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Желток оставить для смазывания теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Всыпать пищевую соду, погашенную лимонным соком или яблочным уксусом, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Муку всыпать частями, замесить густое тесто, накрыть его пленкой и поставить в холодильник или поставить в холод на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Измельчить молочный шоколад, очистить миндаль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Тесто вынуть из холодильника, перемешать его с орехами и шоколадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Сформовать два батона, выложить на противень, застеленный пергаментом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Смазать изделия желтком, поставить в духовку на 35 минут, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Батоны вынуть, остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2156,'Разрезать хлеб на продолговатые ломтики, разложить на противень, поставить в духовку на пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'В яблочный сок налить растительное масло, по вкусу можно добавить сахар, если сок кисловатый.','https:https://st.vkuso.ru/data/cache/thumb/59/d05d5999eaf6959_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Всыпать пшеничную муку вместе с разрыхлителем.','https:https://st.vkuso.ru/data/cache/thumb/e3/371809b07900de3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Замесить мягкое тесто.','https:https://st.vkuso.ru/data/cache/thumb/2a/1ea213ec1af8a2a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Разделить массу на четыре части, каждую раскатать в круг, разрезать сегментами от центра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Для приготовления начинки промыть финики, нарезать крупными кусочками очищенные бананы, обжарить арахис, все вместе взбить при помощи блендера.','https:https://st.vkuso.ru/data/cache/thumb/c7/a9c303b30eaf6c7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'На каждый треугольник нанести по ложечке массы, плотно свернуть.','https:https://st.vkuso.ru/data/cache/thumb/ca/afe7c871c07c6ca_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Для смазывания печенья можно использовать желток, разведенный крахмал или кисель из клюквы.','https:https://st.vkuso.ru/data/cache/thumb/44/2e029e3a1743144_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2157,'Посыпать изделия дроблеными орехами, выпекать в течение 15 – 20 минут, температура – 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/71/78fd4b066d5c671_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Куриное филе нарезать ломтиками по пять или семь сантиметров, обжарить на топленом или сливочном масле до изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Побрызгать лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Добавить нарезанные грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Жарить на сильном огне, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Всыпать муку и специи',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Влить бульон и сливки, жидкость должна полностью покрывать продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Тушить на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Вбить яичный желток, хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Готовый соус влить в курицу, довести до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Подержать под крышкой до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2158,'Добавить мускат перед окончанием приготовления.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2159,'Протереть творог через мелкое сито дважды. Влить к творогу холодные сливки. Творог и сливки взбить на малой скорости миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2160,'Куриное филе нарезать кубиками небольшого размера, жарить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2160,'Цедру лимона натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2160,'Мясо посолить и поперчить, грибы нарезать тонкими пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2160,'Продукты залить сметаной, всыпать цедру.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2160,'Блюдо потушить до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Курицу промыть, обсушить, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Выставить режим «Жарка», добавить смесь растительного и сливочного масла, жарить до появления корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Всыпать специи и муку, добавить нашинкованный репчатый лук и чеснок, лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Выставить режим «Тушение» на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Влить белый сухой вермут, сливки, воду или бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2161,'Прогревать еще сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Куриное мясо отварить, нарезать кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Грибы промыть, разрезать на четвертинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Отварить и нарезать спаржу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Сладкий болгарский перец нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Обжарить на сливочном масле овощи и грибы до появления корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Растопить масло, добавить муку, вермут и бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Довести до готовности на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'В конце приготовления добавить молотый перец, соль и лимонный сок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Ингредиенты смешать, залить соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2162,'Блюдо должно постоять и пропитаться.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Рис отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Обжарить кубики куриного филе на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Посолить по вкусу, добавить свежий базилик и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Потушить под крышкой несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Добавить грибы, готовить еще двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'Влить воду или бульон, тушить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2163,'На тарелки выложить рис, сверху – фрикасе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Вбить в емкость сырые куриные яйца, всыпать сахарный песок, превратить в пену при помощи миксера за три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Всыпать муку порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Перемешивать движениями снизу вверх.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Нарезать кисло-сладкие яблоки вместе с кожурой тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Дно формы для выпекания смазать сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Выложить начинку, вылить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Время приготовления – 15 минут, мощность – от 600 до 800 кВт.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'По желанию мощность можно повысить и готовить пять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Дать постоять в выключенной печи три минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Готовность проверить зубочисткой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2164,'Подать пирог теплым, посыпать сахарной пудрой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2165,'Глазурь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2165,'Нарезаем зелень, сладкий перец, шампиньоны и измельчаем чеснок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2165,'Посыпаем солью и черным молотым перцем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2165,'Заворачиваем в пергаментную бумагу и фольгу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Вбить в емкость сырые яйца, добавить сгущенку, перебить миксером до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Всыпать муку, разбить комочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Отдельно погасить пищевую соду лимонным соком, влить в тесто, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Яблоки очистить, удалить сердцевину, нарезать кубиками небольшого размера, побрызгать лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Перемешать фрукты с тестом, вылить массу в форму для выпекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Выставить мощность микроволновой печи от 600 до 800 кВт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'Время приготовления - десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2166,'По желанию яблоки можно посыпать молотой корицей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2167,'У меня было малое куриное филе, которое я промыл, обсушил бумажным полотенцем и отбил. Затем по вкусу посолил, поперчил и посыпал приправой для курицы. Убрал в строну.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2167,'В миску вбил 2 куриных яйца, добавил 6 ст.л. сметаны, затем соль, перец, укроп сушеный и паприку, все хорошо перемешал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2167,'Постепенно добавлял сметану и довел кляр до состояния густой сметаны. (Лично у меня кляра не хватило, вы можете сделать чуть больше кляра, чем я)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2167,'Разогрел сковородку с растительным маслом. Отбитое куриное филе опустил в кляр, обвалял его c двух сторон, далее переложил в сковороду и обжаривал по 2-3 минуты до корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Яйца взбить с сахарным песком при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Растопить сливочное масло, добавить в основную массу вместе с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Влить немного сметаны и всыпать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Продукт заранее просеять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Яблоки и бананы очистить и нарезать кубиками, вмесить в тесто вместе с грецкими орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Выпекать десять минут, мощность нагрева микроволновой печи – от 600 до 800 кВт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2168,'Бананы можно заменить грушами, а грецкие орехи – любыми другими.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2169,'Вбить яйцо в миску, всыпать сахарный песок, затем муку и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2169,'Очистить и нарезать яблоки мелкими кубиками, посыпать молотой корицей, сбрызнуть лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2169,'Выложить в тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2169,'Кружки смазать маслом, выложить тесто ложкой, емкости должны быть заполнены наполовину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2169,'Время выпекания в микроволновой печи – пять минут. Готовность проверить зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2170,'Яйца пять минут взбивать с сахаром при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2170,'Влить кефир, всыпать ванилин из пакетика, разрыхлитель, заранее просеянную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2170,'Добавить очищенные и нарезанные яблоки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2170,'Тесто в форму выкладывать ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2170,'Поставить в микроволновую печь на десять минут, мощность для выпекания – от 600 до 800 кВт. Готовность пирога проверить палочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Круглозерный рис перебрать, промыть в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Нарезать мелкими кубиками очищенный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Натереть морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Куриный фарш соединить с яйцом, рисом, овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Посолить по вкусу, добавить приправы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Массу хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Сформовать среднего размера тефтели мокрыми руками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Выложить шарики в чашу мультиварки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Отдельно приготовить заливку из томатной пасты с водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Залить тефтели.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Мультиварку закрыть, выставить режим «Тушение» на сорок или сорок пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Блюдо немного остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Подать с кашей, овощами, картофельным пюре.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2171,'Гарнир полить оставшейся в мультиварке подливкой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2172,'Для приготовления рассола я в 1 литр воды отправляю молотый кориандр, оба перца горошком, лавровый лист и сахар с солью. Перемешиваю рассол и довожу его на плите до закипания. Кипятим рассол пару минут, снимаем с плиты и даем ему остыть до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2172,'Всю кильку хорошо промываю, отрезаю у нее голову и вычищаю все внутренности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2172,'Очищенную кильку выкладываем в посуду подходящего размера. Заливаем рыбу остывшим до комнатной температуры рассолом и накрыв крышкой отправляем посуду с килькой в прохладное место минимум на одни сутки (я поставила кильку солиться в холодильник)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2172,'Через сутки наша соленая килька пряного посола готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2173,'Смешать в кастрюле яйца и муку. В смеси не должно быть комочков. Вскипятить в другой кастрюле молоко и сахар, постоянно помешивая. Молоко влить тонкой струйкой к муке, при этом помешивайте постоянно ложечкой, венчиком. Полученный крем поставить на плиту, на несильный огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2173,'Довести до загустения, постоянно помешивая. Крем не должен закипеть. Снять кастрюлю с кремом с огня, насыпать в него ванильный сахар и положить сливочное масло. Мешать заварной ванильный крем, пока не растает масло. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Творог измельчаем любым удобным для Вас способом (я его протерла через сито) чтобы не было комочков в запеканке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Бананы я натираю на мелкой терке. Чтобы не заморачиваться можно творог вместе с бананом измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Натираем половинку шоколада на мелкой терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Теперь в миске смешаем протертый творог,банан и шоколад. Добавляем молоко, яйца и муку с сахаром. Перемешаем эти ингредиенты до получения однородной творожной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Форму для выпечки смазываем сливочным маслом и выложим в нее нашу творожную массу, равномерно ее разровняв.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'Готовим творожную запеканку примерно 45 минут в разогретой до 180 градусов духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2174,'На готовую еще горячую творожную запеканку и натираю немного оставшегося шоколада.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2175,'В глубокую миску выложить творог, добавить щепотку соли, сахар, 1 яйцо и ванильный сахар. Перемешать.','https://vkuso.ru/data/cache/data/04/4ac619368ecb104_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2175,'Добавить муку и хорошо замешать тесто – густое, хорошо держащее форму.','https://vkuso.ru/data/cache/data/d0/408be9350cef7d0_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2175,'Теперь берем творожное тесто чайной ложкой делаем лепешечку в центр кладем ягоду вишни и аккуратно соединяя края формируя шарик.','https://vkuso.ru/data/cache/data/a0/44e56f2ab3adea0_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2175,'Отвариваем вареники в подсоленной кипящей воде до всплытия их на поверхность, примерно 5-7 минут.','https://vkuso.ru/data/cache/data/99/1fac6135fc91299_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2175,'Приятного аппетита!','https://vkuso.ru/data/cache/data/79/369e573eab25879_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2176,'Установить емкость с водой на плиту. Посуду со сливочным маслом поместить в нее, так чтобы емкость с маслом касалась воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2176,'Нагреть воду до закипания. Уменьшить огонь до минимума. Оставить на от 1-1,5 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2176,'Как только на поверхности растопленного масла образуется пенка, ее нужно удалить. Эту пенку можно использовать для приготовления пищи. Масло должно стать прозрачным, а на дне должен образоваться белый осадок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2176,'Процедить готовое масло через несколько слоев марли, перелив в любую другую емкость. Хранить в холодильнике или в другом прохладном месте от 1 до 3 месяцев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Приготовить домашний фарш из говядины, свинины или курятины, с чесноком, луком, зеленью и морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Лук и морковь обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Рис промыть, залить водой. Время варки крупы – от семи до восьми минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Плиту выключить, рис переложить в сито, отцедить горячую воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Соединить все продукты, вбить яйцо, всыпать соль, перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Масса должна получиться вязкой, выложить в холодильник на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Сформовать шарики мокрыми руками, выложить в кастрюлю в один слой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Влить воду, жидкость должна доходить до половины ежиков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Варить под крышкой на тихом огне в течение двадцати минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Обжарить муку на сковороде до золотистого оттенка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Снять с плиты, влить сметану, хорошо перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Влить немного воды, добавить рубленую зелень и давленый чеснок.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Залить тефтели заправкой, поставить в горячий духовой шкаф.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Тушить блюдо полчаса без крышки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2177,'Огонь погасить, дать кушанью постоять один час.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Морковь и репчатый лук очистить и вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Перемолоть в мясорубке свинину и говядину, морковь и чеснок, лук. Продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Отварить рис до полуготовности, время – от семи до восьми минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Воду слить, крупу выложить в фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Перемешать руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Настоять в течение часа, охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Сформовать ежики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Влить масло в мультиварку, выставить режим «Тушение».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Выложить шарики.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Отдельно растворить в воде соль, сметану, хорошо перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Смесью залить ежики, посыпать зеленью и тушить блюдо под крышкой сорок минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2178,'Мультиварку выключить, кушанье остудить под крышкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Белый рис отварить в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Приготовить фарш из говядины и свинины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Очистить овощи: лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Обжарить на сливочном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Соединить овощную обжарку с рисом и мясом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Массу вымешать, приправить перцем и солью по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Охладить в течение получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Томатную пасту развести холодной водой, влить сметану, перемешать венчиком, ввести зелень и чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Сформовать шарики, размер – средний.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Выложить на дно кастрюли, залить заправкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2179,'Тушить при минимальной температуре под крышкой, время – от тридцати пяти до сорока минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Отварить рис, отцедить, перемешать с мясным фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Массу положить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'На сковороде с высокими бортиками растопить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Добавить рубленый лук и тертую морковь. Жарить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Влить сметану, воду, томатную пасту с солью и приправами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Потушить соус двадцать пять минут на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Сформовать руками тефтели из фарша с рисом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Выложить изделия на сковороду, тушить под крышкой пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Ежики перевернуть, тушить еще столько же времени.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2180,'Всыпать рубленую зелень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Куриное филе вымыть, нарезать кусками и перемолоть при помощи мясорубки или блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Отдельно отварить рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Перемешать рис и куриный фарш с карри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Выставить в холод на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Смазать форму для выпекания сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Выложить внутрь тефтели в один слой, сформованные из мяса и риса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Смешать воду со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Влить в форму, посыпать рубленой петрушкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'Выпекать сорок минут при температуре 185 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2181,'В процессе приготовления поливать блюдо заправкой, чтобы тефтели не пересохли.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2182,'Молоко вскипятить, потом снять с огня и остудить. Соединить все ингредиенты и взбить миксером. Взбивать до однородной консистенции и перламутрового цвета. Взбить сливочный крем миксером. Можно это сделать венчиком или миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Морковь и лук очистить, промыть говядину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Пропустить продукты через мясорубку, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Отдельно отварить рис, перемешать с фаршем, добавить молотый лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Массу вымесить и охладить в течение часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Отдельно взбить сметану с томатной пастой и чесноком, влить воду, поперчить, посолить, добавить рубленый укроп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Сформовать небольшие тефтели из фарша с рисом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2183,'Выложить в кастрюлю, влить томатно-сметанную заправку, тушить сорок минут или чуть больше под крышкой, температура – минимальная.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Приготовить фарш из свинины, курицы или говядины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Отварить рис, остудить при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Приготовить соус из тертого сыра, сливок, прованских трав, добавить картофельный крахмал.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Сформовать небольшие тефтели, выложить на противень, тушить двадцать минут при температуре 190 градусов в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2184,'Залить сливочным соусом, тушить еще тридцать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Нарезать репчатый лук, петрушку, базилик и укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Мясо вымыть, перемолоть в фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Продукты соединить, влить молоко, всыпать панировочные сухари, специи, добавить взбитое яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Массу хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Сформовать маленькие шарики-тефтели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Их можно заморозить и хранить до появления необходимости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Обжарить изделия на растительном масле с двух сторон, выложить на бумажные салфетки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Отдельно прогреть на сковороде сливочное масло, обжарить белые грибы или шампиньоны, нарезанные кусочками. Время приготовления – от семи до десяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Добавить сливки и муку, приправы, перемешать, прогреть на огне.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2185,'Выложить тефтели, тушить все вместе пятнадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'Нут промыть в холодной воде и удалить кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'Выжать сок из лимона, нарезать чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'В чашу блендера всыпать нут и измельчить, затем выключить блендер соскрести со стенок нут и снова пробить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'Добавить тахини, лимонный сок, оливковое масло, чеснок, кумин, соль, измельчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'В процессе добавлять воду (100-200 мл), чтобы пюре приобрело нужную консистенцию и если нужно добавить соль и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2186,'Готовый хумус разложить по герметичным контейнерам и убрать в холодильник (он может храниться там до 7ми дней).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Нарезать репчатый лук и любые фрукты полукольцами, косточки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Куриное мясо нарезать брусочками небольшого размера, натереть солью и специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Перемешать руками, полить лимонным соком, еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Массу оставить для пропитывания на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Выложить продукты в банку слоями: курица, лук, фрукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Слои повторять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Запекать блюдо в духовке в течение полутора часов, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2187,'Оставить в печи еще на пятнадцать или двадцать минут при выключенном огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Очистить картофель от кожуры, нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Влить в банку пиво, поставить емкость на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Вокруг банки выложить картофель, посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Перемешать сметану с давленым чесноком, перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Заправкой натереть целую тушку курицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Насадить на банку, печь при температуре 200 градусов до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2188,'Проверять можно палочкой: вытекающий сок должен стать прозрачным.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Перемешать итальянские травы с черным молотым перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Добавить давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Влить соевый соус и сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Охлажденную курицу промыть под краном, обсушить, натереть готовым маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Оставить на двадцать минут для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Хорошее пиво налить в противень, выложить курицу, запекать сорок пять минут, температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2189,'Подать с зеленью и овощами в качестве гарнира.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Свинину нарезать кубиками.','https://vkuso.ru/data/cache/data/20/6d179e046d1df20_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Обжарить на сильном огне в течении 5 минут, до легкого зарумянивания.','https://vkuso.ru/data/cache/data/46/681262e96b8c446_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Репчатый лук нарезать полукольцами.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Томатную пасту развести 250-300 мл воды и добавить в мясо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Добавить приправу хмели-сунели, чеснок, посолить поперчить по вкусу.','https://vkuso.ru/data/cache/data/14/148d7bd54c8f914_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Довести блюдо до кипения. Закрыть крышкой и тушить на медленном огне до готовности, 40-45 минут.','https://vkuso.ru/data/cache/data/9c/23c2f2bb0c1cd9c_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Рис хорошо промыть под проточной водой.','https://vkuso.ru/data/cache/data/7e/bc5224ee040777e_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'На сковороде растопить кусочек сливочного масла, выложить рис и обжарить его в течении 2-3 минут.','https://vkuso.ru/data/cache/data/cf/20eebe855b7a0cf_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Добавить 2 стакана воды, соль и куркуму.','https://vkuso.ru/data/cache/data/10/5017e8bc9841510_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2190,'Довести до кипения, закрыть крышкой и готовить на медленном огне до готовности. Приятного аппетита!','https://vkuso.ru/data/cache/data/89/cb230e024380b89_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Чистим, потрошим, моем карасей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Делаем надрезы на спинке карасей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Разрезаем карасей вдоль по хребту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Посыпаем солью и черным молотым перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Смазываем рыбу аджикой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2191,'Решетку выстилаем фольгой, пергаментной бумагой и смазываем растительным маслом. Выкладываем карасей и жарим по 7 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2192,'В блендере сначала смешать банан, ягоды, йогурт и апельсиновый сок. Добавить льняные семечки и снова перемешать. Разлить по стаканам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2193,'Нарезаем сало.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2193,'Жарим на углях 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2193,'В углях делаем углубление и выкладываем картофель. Засыпаем углями. Запекаем 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2193,'Подавать с луком и бородинским хлебом натертым чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Маринад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Моем, чистим, потрошим рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Нарезаем на кусочки ( не дорезая до конца ) толщиной 3 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Смазываем рыбу маринадом .',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Чистим и нарезаем авокадо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2194,'Вкладываем авокадо в разрезы и запекаем на углях по 10 минут с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2195,'Готовим основу пирога. В миске перемешать муку, сахарную пудру, щепотку соли. Холодное сливочное масло нарезать кубиками, сложить в глубокую миску. Размять руками в мелкую крошку. Добавить яйцо и холодную воду, замесить тесто. Завернуть тесто в пищевую пленку и положить в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2195,'Раскатать тесто в пласт, выложить тесто на форме сделав невысокие борты, проколоть дно основы вилкой. Духовку разогреть до 190 градусов отправить пирог выпекаться на 15 минут. Затем достать и полностью остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2195,'Для кокосового заварного крема смешать муку, сахарную пудру и три желтка и перемешать вилкой. Влить кокосовое молоко перемешать. Ставим на медленный огонь и готовим до загустения, перемешивая. Затем снимаем с огня и остужаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2195,'Груши очистить и нарезать четвертинками. Удалить ножку и семена.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2195,'Основу для пирога залить кремом (немного оставить), выложить половину груш смазать еще раз кремом и выложить вторую часть груш.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2196,'Отвариваем яйца вкрутую (доводим воду до кипения, варим 7 минут после закипания). Затем сливаем воду и заливаем холодной, полностью остужаем и очищаем от скорлупы, разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2196,'Лук очистить и тонко нарезать полукольцами. Помидоры и болгарский перец порежьте кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2196,'В сковороде разогреть сливочное масло. Отправить в сковороду лук, обжарить на среднем огне 6 минут перемешивая. Затем отправить в сковороду нарезанный болгарский перец и помидоры. Готовим 10 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2196,'Пока готовятся овощи мелко нарубить петрушку и натереть сыр на мелкой терке. После того как овощи обжарены, добавляем соль, перец и паприку – перемешиваем. Выкладываем яйца разрезом вниз, посыпать нарубленной петрушкой и тертым сыром. Закройте крышкой и держите на слабом огне пока сыр не расплавится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'Свинину промываем под водой, обсушиваем бумажным полотенцем. По желанию можно обрезать жилки, сухожилия.','https://vkuso.ru/data/cache/data/ec/e0328cd069351ec_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'Свинину нарезаем поперёк волокон на порционные кусочки. Затем их нужно отбить.','https://vkuso.ru/data/cache/data/e2/1d77e8248797fe2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'Далее солим, перчим и посыпаем приправой для мяса (также можете добавить приправ на ваш выбор). Убираем в сторону.','https://vkuso.ru/data/cache/data/99/1ddc9f5ad341699_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'Натираем сыр.','https://vkuso.ru/data/cache/data/29/ee6a80d9f25b929_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'В миске замешиваем кляр. Вбиваем 3 куриных яйца, добавляем сметану, соль перец, все хорошо взбиваем.','https://vkuso.ru/data/cache/data/3b/8a4d986e7c43c3b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'Затем добавляем сыр, перемешиваем. Добавляем муку. У вас должен получится более менее густой кляр.','https://vkuso.ru/data/cache/data/b6/b06d0b272ee77b6_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2197,'В кляр отпускаем порционный кусочек свинины, обвалуем его с двух сторон. Перекладываем на разогретую сковороду.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Перемешать просеянную муку со специями, солью, смесью перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Влить светлое пиво, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'В сотейник влить растительное масло, уровень – десять сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Мясо птицы нарезать полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Муку высыпать на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Обвалять курицу в муке, обмакнуть в кляр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Обжаривать в масле небольшими порциями по четыре минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2198,'Наггетсы выложить на бумагу для впитывания излишков жира.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Куриные бедра натереть молотым перцем и солью, смазать медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Оставить настаиваться на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Залить курицу пивом так, чтобы жидкость полностью ее покрывала.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Время настаивания – три или четыре часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Морковь нарезать тонкими кружками, репчатый лук – полукольцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Жарить овощи с мясом в одной чаше с маслом, время – 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Очистить и разрезать пополам мелкую картошку, выложить в чашу мультиварки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'Выставить режим «Выпечка» на сорок минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2199,'За пятнадцать минут до окончания приготовления добавить чеснок и имбирь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Мясо нарезать средними кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Пропустить чеснок через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Солью и перцем натереть куриное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Нарезать репчатый лук кольцами, обжарить на сковороде с маслом до получения золотистого оттенка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Лук сдвинуть на край, выложить курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Жарить по шесть или семь минут на каждом боку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2200,'Влить алкоголь, потушить десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2201,'Все продукты должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2201,'Разбить и поместить 6 перепелиных яиц в узкую емкость. Яйца предварительно следует вымыть. Добавить 200 мл. оливкового масла. Взбивать погружным блендером в течение нескольких секунд, не перемещая блендер. Затем взбивать еще несколько секунд, перемещая блендер, до образования эмульсии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2201,'Затем добавить 1 ст. л. лимонного сока, 1/2 ч. л. горчицы, 1/2 ч. л. сахара, 1/3 ч. л. соли и по 1/3 ч. л. сухого чеснока, кориандра и смеси перцев. Взбивать в течение нескольких секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2201,'Перелить майонез в стеклянную посуду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2201,'Хранить в холодильнике в течение недели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Вылить пиво в стеклянную банку, выставить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Насадить птицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Приготовить заправку из сметаны, специй и давленого чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Обмазать курицу полученным составом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'На противень налить воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Время запекания – от шестидесяти до семидесяти минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2202,'Мясо проколоть зубочисткой, если выделяется прозрачный сок – оно готово.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2203,'Смешайте все ингредиенты в блендере до консистенции смузи и сразу же подавайте к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Куриные голени и бедра промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Пропустить через пресс зубчики чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Мясо натереть специями, обжарить с двух сторон до появления корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Выложить в глубокую кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Репчатый лук очистить и нарезать, добавить с кайенским перцем к курятине.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Влить светлое пиво, соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2204,'Время тушения на тихом огне – сорок пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Куриное мясо нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Репчатый лук очистить, нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Очистить картофель, нарезать кубиками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Отварить рис в подсоленной воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Лук обжарить на сковороде с маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Посолить по вкусу, добавить зелень петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'В полуготовую обжарку добавить мясо и специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Время тушения – от пятнадцати до двадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Влить пиво, довести до кипения, тушить пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Влить газированную воду или «Кока-колу», тушить еще десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2205,'Добавить картофель, тушить все вместе до готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2206,'Редьку и морковь очистить, натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2206,'Зеленый лук промыть, нарезать ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2206,'Ингредиенты соединить, посолить по вкусу и заправить растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2207,'Кочан китайской капусты разделить на листья, промыть холодной водой, нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2207,'Свежие огурцы нарезать полукружьями, натереть редьку, порубить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2207,'Приготовить заправку из лимонного сока и оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2207,'Заправить салат, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2208,'Чернослив замочить в холодной воде, жидкость слить, сухофрукты подсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2208,'Очистить зеленую редьку, удалить сердцевину, натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2208,'Плоды яблок также измельчить на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2208,'Пропустить через пресс давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2208,'Ингредиенты перемешать, посолить, заправить майонезом или сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2209,'Отварить куриные яйца, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2209,'Зеленую редьку очистить, натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2209,'Нашинковать белокочанную капусту, зелень и репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2209,'Продукты все соединить, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2209,'Заправить майонезом или сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Отварить рис, добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2210,'Красную или белокочанную капусту нарезать максимально тонкими полосками, отжать руками. Продукт должен пустить сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2210,'Зеленую редьку очистить, натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2210,'Порезать мелкими кусочками стебель сельдерея, порубить зеленый лук, укроп и петрушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2210,'Ингредиенты соединить, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2210,'Влить растительное масло, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Отварить курицу или другое мясо, остудить, разобрать руками на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Зеленую редьку очистить, натереть, добавить к мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Репчатый лук нарезать полукольцами, обжарить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Добавить в салат в горячем виде. Хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Блюдо посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Приготовить заправку из равных частей майонеза и сметаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2211,'Перемешать салат еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2212,'Зеленую редьку натереть на терке, нарезать полукольцами сладкий болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2212,'Пропустить через пресс чеснок, порубить зеленый лук, продукты добавить в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2212,'Блюдо посыпать сахаром и солью, кунжутным семенем, красным острым перцем, полить уксусом, рисовым или столовым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2213,'Курицу отварить, остудить, мясо разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2213,'Нарезать лук и грибы, обжарить на растительном масле, добавить специи и соль по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2213,'Отцедить лишнюю жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2213,'Редьку очистить, натереть или нарезать тонкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2213,'Порубить зелень укропа. Ингредиенты перемешать, посолить, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Отварить любое мясо, нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Натереть зеленую редьку на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Сладкий болгарский перец разного цвета нарезать полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Пропустить чеснок через пресс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Порвать руками листья зеленого салата, порубить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2214,'Продукты перемешать, посолить, заправить соевым соусом, сметаной или майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'В теплое молоко всыпать дрожжи, 1 столовую ложку сахара и 130 грамм муки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'В большую миску вбить яйца и добавить сахар, взбить с помощью миксера до пышности (примерно минут 5).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Добавить к взбитым яйцам опару, сливочное масло и щепотку соли, перемешать венчиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Изюм залить теплой водой и оставить на 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Формы для выпечки смазать растительным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Когда тесто поднимется можно отправлять куличи в духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Готовым куличам дайте остыть при комнатной температуре и затем выньте их из формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2215,'Шоколадную глазурь растопите в микроволновке или на водяной бане.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Говяжье сердце замочить в подсоленной воде на восемь или десять часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Отварить субпродукт, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Нашинковать отваренный картофель и яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Нарезать соленые огурцы, зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Зеленую редьку натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Продукты перемешать, добавить консервированный зеленый горошек, посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2216,'Приготовить заправку из сметаны и горчичного соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2217,'Смешать все ингредиенты в блендере до консистенции смузи, украсить клубникой  и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Картофельные клубни отварить и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Так же поступить с кисло-сладкими яблоками, морковью, зеленой редькой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Натереть морковь на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Копченую колбасу нарезать кубиками или полосками, нашинковать репчатый лук полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Выложить на дно блюда картофель, затем слой колбасы, редьки, яблок, лука, морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Каждый слой промазывать майонезом, солить и перчить по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2218,'Оставить салат для пропитывания на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Приготовить фарш из куриной грудки, добавив батон, замоченный в теплом молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Продукты перемешать, посолить и поперчить. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Отдельно приготовить соус из сливок, измельченного чеснока, зелени и тертого сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Сформовать шарики, выложить на дно мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Залить сливочным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2219,'Готовить в режиме «тушения» 45 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Рис промыть и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Перемолоть рыбное филе, перемешать с солью, специями и рисом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Сформовать шарики, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Натереть морковь, влить сливки, поставить на огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Довести смесь до кипения, добавить тефтели, тушить двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2220,'Измельчить соленые огурцы, добавить в кушанье, через десять минут всыпать зелень укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Приготовить фарш из курицы и репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Добавить соль и смесь перцев, белый хлеб без корочки, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Массу вымесить руками или при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Сформовать небольшие шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Соединить отдельно муку со сливками, добавить соль, рубленый или пропущенный через пресс чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Добавить молотый мускатный орех.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2221,'Выложить полуфабрикаты на сковороду, влить соус, тушить на среднем огне десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Через мясорубку пропустить рыбу, замоченный в молоке белый хлеб, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Вбить сырое яйцо, специи, растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Вымесить массу до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Слепить шарики мокрыми руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Обвалять изделия в муке, обжарить на сковороде в масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Выложить полуфабрикаты на сковороду, залить сливками с рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2222,'Блюдо тушить в духовке в течение пятнадцати минут, температура – 190 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Рис промыть, отварить, остудить, перемешать с чесноком, луком, мясом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Всыпать специи, соль, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Сформовать ежики, выложить на смазанный маслом противень, залить смесью томатной пасты со сливками и водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Прогревать при температуре 210 градусов в течение тридцати пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Емкость затянуть фольгой, чтобы жидкость не испарялась.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2223,'Еще двенадцать минут печь в открытом виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2224,'Приготовить фарш с помощью кухонного комбайна: перемолоть говядину, репчатый лук, размоченную в молоке белую булку, специи, соль – по вкусу. Масса должна постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2224,'Сформовать небольшие тефтели, выложить на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2224,'Печь при температуре 190 градусов в течение двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2224,'Отдельно приготовить подливу из зелени и рубленого чеснока со сливками и тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2224,'Залить шарики, все вместе тушить еще полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Приготовить фарш из филе птицы, лука, отваренного риса, специй, соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Вылепить небольшие шарики, запечь в духовке на смазанном противне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Отдельно обжарить измельченный лук с морковью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Влить в обжарку сливки, добавить муку и сливочное масло. Специи, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Полить тефтели полученным соусом, запекать двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'В конце приготовления выставить режим «Гриль» для получения румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2225,'Подать к столу в полуостывшем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Свинину и говядину вымыть, удалить сухожилия, продукт нарезать кусочками, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Нарезать репчатый лук, добавить в фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Вбить сырое яйцо, всыпать соль и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Мокрыми руками сформовать шарики, запанировать в муке, жарить на растительном масле до получения румянца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Еще одну луковицу очистить, нарезать и обжарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Натереть морковь, добавить к луку, жарить вместе несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Всыпать молотый перец, соль, влить томатную пасту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Прогреть молоко, всыпать муку, хорошо перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Добавить сметану.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Готовый белый соус перемешать с обжаркой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Выложить тефтели в жаропрочную форму, влить соус, добавить лавровый лист.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2226,'Подержать в духовом шкафу полчаса, температура приготовления – 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Куриное филе промыть, разрезать кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Нарезать крупными кусочками репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Залить белый батон молоком, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Добавить в фарш, еще раз пропустить через мясорубку. Соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Положить отваренный рис, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Слепить шарики, запанировать в сухарях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Противень смазать растительным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Морковь натереть, выложить на противень, сверху – тефтели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Поставить блюдо в духовой шкаф, прогревать при температуре 200 градусов в течение пятнадцати минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Для подливы перемешать муку с теплой водой, массу взбить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Влить томатную пасту и сметану, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2227,'Положить кусочки лаврового листа. Залить соусом изделия, тушить в течение часа.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Нашинковать репчатый лук, добавить любой фарш, вбить сырое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Всыпать отваренный рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Посолить и поперчить по вкусу, массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Приготовить тефтели, выложить в чашу мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Отдельно соединить кетчуп со сметаной и мукой, солью, перцем, лавровым листом и сухим базиликом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Влить немного воды и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2228,'Соусом залить тефтели, выставить режим «Тушение» на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Нарезать репчатый лук и свинину кусочками, пропустить через мясорубку несколько раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Перемешать с заранее отваренным рисом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Вбить сырое яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Посолить и поперчить по вкусу, сформовать небольшие шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Запанировать изделия в муке, обжарить на заранее прогретом растительном масле в глубокой сковороде. Должна получиться золотистая корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Отдельно перемешать воду с томатной пастой, влить на сковороду, тушить под крышкой в течение десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Всыпать муку в сметану, влить немного воды, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Залить тефтели в томатном соусе, тушить еще пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Влить еще немного воды, положить лавровый лист, соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2229,'Тушить десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Нарезать репчатый лук, натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Овощи переложить на сковороду, жарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Перемешать свиной фарш с телячьим, добавить овощи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Добавить специи и соль по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Сформовать тефтели, жарить на растительном масле, на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'В отдельной емкости перемешать сметану со сливками, солью и приправами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2230,'Влить соус в кастрюлю, выложить шарики, тушить под крышкой полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Рыбное филе пропустить через мясорубку или воспользоваться блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Добавить тертый чеснок и сушеную зелень, соль, молотый перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Массу хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Всыпать тертый сыр, массу еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Вбить сырые яйца, добавить панировочные сухари, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Слепить небольшие тефтели, обвалять изделия в муке, выложить в форму для запекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Приготовить подливу из сметаны с водой, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2231,'Залить тефтели, печь полчаса при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2232,'Смешать в блендере мякоть спелой груши, шпинат и остальные ингредиенты, украсить и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Нарезать репчатый лук, овощи выложить в емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Добавить говяжий фарш два раза пропущенный через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Размочить в холодной воде батон без корочек, добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Вбить яйцо, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Всыпать отваренный рис, массу перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Скатать небольшие шарики мокрыми руками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Выложить в форму для запекания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Приготовить соус из томатной пасты со сметаной и мукой, посолить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Влить немного воды и перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2233,'Залить тефтели, тушить полчаса под крышкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Репчатый лук мелко нарезать, перемешать с любым фаршем, добавить заранее отваренный рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Вбить яйца, посолить, поперчить. Массу хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Сформовать небольшие шарики, запанировать в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Растопить сливочное масло на сковороде, всыпать муку, обжарить до однородного состояния, продукты помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Соединить со сметаной, тушить все вместе две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Влить воду и томатную пасту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'В другую сковороду влить растительное масло, обжарить тефтели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Соус влить на противень, добавить лавровый лист и обжаренные тефтели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2234,'Печь в духовке при температуре 200 градусов, время – полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'В магазинный или приготовленный дома фарш вбить сырое яйцо, всыпать соль и молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Репчатый лук натереть на терке, добавить к мясу, перемешать руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Смазать маслом форму для выпекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Сформовать из фарша шарики небольшого размера, выложить в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Нашинковать лук и морковь, перемешать с томатной пастой и водой, добавить соль и любые приправы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Полить готовой подливой фрикадельки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Блюдо подержать в духовом шкафу от сорока пяти до пятидесяти минут, температура приготовления – 190 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'Тушить под крышкой или фольгой, в конце крышку снять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2235,'При подаче посыпать тертым сыром, рубленой зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'В мясной фарш всыпать приправы, соль, добавить сырое яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'Порубить чеснок, натереть репчатый лук, овощи добавить к фаршу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'Нарезать некрупной соломкой сырой картофель, переложить в форму для запекания, посыпать специями и полить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'Вылепить шарики небольшого размера, выложить поверх овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'Долить воду. Тушить около часа при температуре 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2236,'Для приготовления блюда идеальный вариант – фарш-ассорти из говядины и свинины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Булочку или белый хлеб замочить в молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Порубить репчатый лук, добавить в куриный фарш вместе с отжатым хлебобулочным изделием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Всыпать немного соли, специи, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Выложить сформованные шарики на дно стеклянной или керамической формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Поставить в духовку, время – от десяти до пятнадцати минут. Температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Порубить зелень и чеснок, натереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Ингредиенты соединить, приправить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Влить сливки, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2237,'Вынуть фрикадельки из духовки, полить соусом, тушить еще двадцать минут, температура – та же.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2238,'Смешать творог и сахар, перебить блендером в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2238,'Какао смешать с сахаром и водой и довести до кипения на плите (до растворения сахара)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2238,'Намочить марлю и положить в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2238,'Далее укладываем слой творога, сверху слой печенья, предварительно обмакнув его в шоколад. И повторяем до заполнения миски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2238,'Ставим в холодильник на 5 часов. После накрываем сверху тарелкой, переворачиваем и за края марли вытаскиваем из формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2239,'Отвариваем картошку в мундире и яйца вкрутую. Все это чистим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Остудить рис до теплого состояния, добавить в фарш, ингредиенты перемешать руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2239,'Дно сковородки (или формы для выпечки) смазываем маслом и укладываем слой картошки, поливаем сметаной, солим,перчим, посыпаем яйцом (у меня уходило половинка яйца на каждый слой)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2239,'Далее следующий слой картошки - сверху сметана соль/перец и яйцо. И так - до самого верха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2239,'Сверху можно притрусить сыром',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2239,'Ставим в духовку 180-200°C на 35-40 минут. Достаем и наслаждаемся, сейчас будет вкусно-вкусно!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2240,'Нарезаем соломкой курицу, крабовые палочки, огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2240,'Заправляем майонезом и добавляем немного перца по вкусу. Перемешиваем. Приятного!!!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2241,'Лично я сделал так. 1 часть сосисок разделил на 2 части. А другую на 3.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2241,'Для начала надо припылить стол мукой. Затем слоеное тесто нужно раскатать и нарезать на равные полоски. Полоски лучше сделать чуть шире, чем я.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2241,'Куриное яйцо взбиваем с небольшим добавлением воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2241,'Эти полоски нужно смазать куриным взбитым яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2241,'Затем данные полоски наматываем на подготовленные сосиски. Перекладываем на противень, снова смазываем взбитым куриным яйцом и отправляем в разогретую духовку при 180°С на 20-25 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2242,'Лук нарезать мелким кубиком. В кастрюле разогреваем оливковое масло и отправляем туда лук. Готовим на среднем огне 5 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2242,'Болгарский перец очистить от семян, нарезать небольшим кубиком. Отправить перец к луку, готовить 10 минут на среднем огне, перемешивая. Залить водой, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2242,'Картофель очистить и нарезать маленькими кубиками, отправить в кастрюлю, добавить лавровый лист, мускатный орех, майоран, молоко, соль – перемешиваем. Накрываем кастрюлю крышкой, доводим до кипения и варим 15-20 минут, пока не приготовится картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2242,'Спустя 15 минут добавить кукурузу и плавленый сыр, креветки предварительно очищенные – перемешиваем и греем 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2243,'Цветную капусту разобрать на соцветия, залить водой и поставить на огонь. Доводим до кипения, а затем варим 5 минут. Сливаем воду и остужаем. Нарезать на мелкие кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2243,'Болгарский перец очистить от семян, нарезать мелким кубиком. Сыр натереть на крупной терке. Петрушку мелко порубить ножом. Куриную грудку перекрутить в фарш (или взять готовый куриный фарш). Все ингредиенты смешать в глубокой тарелке, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2243,'К фаршу с овощами вбить яйца, добавить сметану и муку. Все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2243,'Разогреть в сковороде растительное масло, сформовать мокрыми руками котлеты, обжарить их до золотистого цвета с двух сторон на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'Творожную массу выложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'Желтки отделить от белков и отправить желтки в творожной массе. К творожной массе влить молоко и добавить ванильный сахар, перемешать до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'Добавить муку снова перемешать, чтобы не осталось комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'Белки взбить в пену, а затем перелить к творожной смеси и аккуратно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'На сковороде разогреть сливочное масло, а затем вылить омлет на сковороду. Выложить горсть ягод и готовить на медленном огне, до золотистого цвета, затем перевернуть и готовить также на медленном огне до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2244,'Готовый омлет посыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Мясо пропустить через мясорубку вместе с луком, добавить яйца, специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Кориандр добавить по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Сформовать шарики, выложить в емкость для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Время приготовления – от десяти до пятнадцати минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Перемешать муку со сметаной и приправами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2245,'Полить фрикадельки, потушить в духовке еще 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2246,'Абрикосы и манго очистить от кожуры и косточек, нарезать ломтиками. В блендере смешать все ингредиенты, разлить смузи по бокалам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Отварить рис до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Белый хлеб замочить в молоке, дать набухнуть, отжать, добавить в фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Натереть репчатый лук, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Печь фрикадельки в форме в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Приготовить подливу из сметаны, горчицы, базилика, прованских трав.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Мясные шарики вынуть, полить соусом, печь 20 минут при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2247,'Зелень петрушки и лука порубить, посыпать блюдо за пять минут до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2248,'Индейку нарезать кусочками среднего размера, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2248,'Таким же образом измельчить морковь и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2248,'В мясо добавить перец и соль, белок одного яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2248,'Сформовать шарики, выложить в огнеупорную форму и печь при температуре 170 градусов, время – от сорока до сорока пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2248,'Приготовить соус из нежирной сметаны, специй.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Крупу промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Другой вариант – замочить заранее, на шесть часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Промытую крупу обжарить на сковороде без жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Переложить в кастрюлю, добавить воду, довести до кипения, огонь убавить. Время варки – двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Открыть мясные консервы, жир переложить на сковороду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Обжарить репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Добавить тертую морковь, рубленый чеснок и консервы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Посолить и поперчить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Тушить подливу под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Переложить в кастрюлю, перемешать и потомить двадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2249,'Оставить блюдо на плите, подать через полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Крупу промыть холодной водой и залить кипящей. Оставить для разбухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Измельчить овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'В мультиварку выложить консервы из говядины вместе с жиром. Разобрать ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Высыпать овощи, в конце – крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Залить холодной водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Добавить любимые специи, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2250,'Перемешать, выставить режим «Тушение», а затем «Подогрев». Жидкость должна выпариться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Крупу промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Довести воду до кипения, всыпать перловку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Варить три минуты на сильном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Воду слить, влить новую порцию жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Довести до кипения, огонь уменьшить, варить около часа, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Выложить на сковороду жир из консервной банки, обжарить репчатый лук и морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Консервированное мясо нарезать кусочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'За пятнадцать минут до готовности перловой каши добавить овощную обжарку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2251,'Оставить блюдо под крышкой на десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Перловую крупу замочить в холодной воде на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Измельчить лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Нарезать картофель, соленые огурцы и свежие помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Довести воду до кипения, всыпать перловку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Убавить огонь, кипятить пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Налить на сковороду оливковое масло, обжарить лук и морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Спассеровать, добавить помидоры, потомить семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Добавить огурцы, жарить все вместе две минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Варить картофель с перловкой, через пятнадцать минут добавить подливу со сковороды и говяжью тушенку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2252,'Варить пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'На дно небольшой стеклянной банки насыпать соль, выложить лавровый лист и черный перец-горошек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Следующий слой – свинина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Затем свиное сало или жир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Отдельно перловую крупу залить кипятком и распарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Выложить часть перловки в банку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Далее слои повторить, банка должна заполниться по плечики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Налить воду, оставить два сантиметра до горлышка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Емкость закупорить и поставить в автоклав.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Тушить в течение часа при температуре 120 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2253,'Автоклав выключить, стравить воздух, вынуть банки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2254,'Одну чайную ложку желатина залить 6 чайными ложками холодной воды и оставить для набухания на 15-20 минут.','https://vkuso.ru/data/cache/data/4d/c83dce4a014294d_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2254,'Один стакан сахара (200г) высыпать в сотейник или кастрюлю, залить 4 столовыми ложками воды','https://vkuso.ru/data/cache/data/70/fe2ced286092c70_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2254,'Нагреть на медленном огне до полного растворения сахара, уваривать сироп не  нужно, хорошо растворился сахар, нет крупинок - снимайте.','https://vkuso.ru/data/cache/data/5f/e33a910a129ab5f_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2254,'В горячий сахарный сироп добавить набухший желатин. Размешать до полного растворения желатина.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Чеснок чистим, убираем в строну.','https://vkuso.ru/data/cache/data/f7/1c14ef15d3f71f7_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Смешиваем мёд и соевый соус.','https://vkuso.ru/data/cache/data/da/ba22df7a4670bda_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Подготавливаем куриное филе. Затем солим перчим, и посыпаем приправой для курицы, примешиваем','https://vkuso.ru/data/cache/data/15/3614187382a3b15_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'В глубокую миску перекладываем филе, и заливаем его маринадом. Убираем в сторону.','https://vkuso.ru/data/cache/data/b3/f2ddc2bd0f194b3_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Подготавливаем рукав. Рукав должен быть чуть больше чем противень.','https://vkuso.ru/data/cache/data/c8/08d1859de3c5fc8_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'В рукав перекладываем куриное филе, и чеснок. Края заворачиваем и защепляем зажимом. Отправляем в духовку до готовности на 45 минут. Время запекания куриного филе зависит от вашей духовки.','https://vkuso.ru/data/cache/data/08/898a35fde132508_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Спустя 45 минут можно отрезать часть рукава и смазать куриное филе образовавшимся бульоном.','https://vkuso.ru/data/cache/data/76/820154930ecca76_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2255,'Снова убрать в строну на 15 минут. Готово.','https://vkuso.ru/data/cache/data/31/e35a1c3e2214731_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2256,'Измельчить в блендере ломтики моркови, соцветия брокколи, добавить апельсиновый сок и тщательно перемешать на низких скоростях. Добавить оставшиеся ингредиенты, перемешать, разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Обжарить измельченный лук и морковь на растительном масле до появления золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Добавить говяжью тушенку, специи и томатную пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Потушить все вместе десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Обжарить на сковороде перловку, выложить в горшочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Первый слой – крупа, второй – овощи с консервами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Влить воду, добавить давленый чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Горшочки поставить в духовой шкаф, время приготовления – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2257,'Температура – 200 градусов, затем ее уменьшить до 180 градусов, тушить еще час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Зерна промыть, залить кипящей водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Нарезать пластинками свежие шампиньоны, обжарить на масле в течение семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Добавить рубленый репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Перловку соединить с грибами и луком, добавить специи, влить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Поставить кашу тушиться под крышкой в духовой шкаф.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2258,'Время – один час, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Крупу залить водой, оставить на сорок минут для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Налить в кастрюлю воду, довести до кипения, всыпать соль и крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Ввести масло, тушить еще двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Разогреть масло на сковороде, обжарить морковь, лук, грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Сначала выложить нарезанный полукольцами репчатый лук, затем – тертую морковь, через пять минут – грибы. Перец и соль, специи – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Тушить все вместе десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Выложить обжарку в большой глиняный горшок, вариант – несколько маленьких.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Всыпать перловку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2259,'Томить под крышкой в духовке двадцать минут при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'Отварить 50-60 гр. длиннозерного риса. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'Добавить к рису 2-3 измельченных отварных куриных яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'Отварить 150-200 гр. замороженных креветок. Измельчить и добавить к смеси.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'Далее - небольшой пучок измельченного зеленого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'Затем - 3-4 ст. л. майонеза и 140 гр. консервированной кукурузы. Смешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2260,'При желании, можно добавить соль и специи. Украсить целыми креветками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Крупу залить холодной водой, поставить на огонь, варить полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Крупу обжарить на сухой сковороде без масла, затем отправить в кипящую воду на сорок минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Замороженные грибы отварить в подсоленной воде, время – двадцать минут. Бульон не выливать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Репчатый лук очистить, нарезать кубиками, спассеровать на топленом масле, всыпать крупу, пять минут спустя влить белое вино. Алкоголь должен выпариться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Влить грибной бульон, потушить до испарения жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Нарезать грибы, добавить в кашу, перец молотый и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Влить воду или остатки бульона в соотношении «один к двум».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Потомить кашу две минуты, снять с огня, посыпать тертым сыром «Пармезан», перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Выложить массу в горшочек или форму для запекания, поставить в духовку на сорок минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2261,'Готовить при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Сушеные грибы замочить в воде на час, продукт мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Воду процедить, но не выливать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Включить мультиварку, выставить режим «Жарка», влить масло в чашу, прогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Спассеровать нарезанный кубиками репчатый лук, тертую морковь, грибы. Овощи должны стать мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Добавить кубики картофеля, всыпать перловку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Влить воду, оставшуюся от замачивания грибов и кипяток.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Посолить и поперчить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2262,'Варить в режиме «Суп» в течение часа. Другой вариант – режим «Тушение» на два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Выставить режим «Жарка», прогреть масло, обжарить говядину, нарезанную кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Мясо посолить и поперчить, влить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Выставить режим «Тушение» на сорок минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Свежие шампиньоны разрезать на четыре части, морковь – соломкой, репчатый лук – кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Добавить грибы в тушеное мясо, овощи – через десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Довести до мягкости, всыпать зеленый горошек, через две минуты добавить перловку, замоченную на ночь в холодной воде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2263,'Перемешать, тушить в том же режиме один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2264,'В воду всыпать крупу перловки, настоять сорок минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2264,'Выставить режим «Жарка», влить растительное масло, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2264,'Филе птицы нарезать брусками, обжарить до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2264,'Добавить нарезанный лук, морковь, грибы и чеснок, потушить все вместе до готовности овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2264,'Всыпать крупу, влить воду (соотношение: один к двум), выставить режим «Тушение» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Отварить перловку, всыпать в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Добавить грибы, морковь, репчатый лук, корень и стебель сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Перемолоть в фарш.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Добавить специи, соль. Можно использовать индийские приправы, паприку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Перемешать, сформовать котлеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Если изделия разваливаются – добавить в фарш пшеничную муку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2265,'Котлеты обвалять в кукурузной муке, обжарить до румянца, переложить в форму, довести блюдо до готовности в духовом шкафу при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Перловку промыть и замочить в теплой воде на ночь или на семь часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Воду слить, крупу промыть',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Всыпать в кастрюлю, влить литр воды, всыпать соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Довести блюдо до кипения, тушить на тихом огне полчаса или сорок минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Крупу откинуть на дуршлаг, отцедить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Сладкий болгарский перец очистить от семян, мякоть нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Репчатый лук нашинковать полукольцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Помидоры нарубить кубиками среднего размера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Покрошить петрушку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Прогреть сковороду с маслом, обжарить перец и лук, время – от десяти до пятнадцати минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Всыпать перловку. Жарить все вместе пять минут. Помешивать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Добавить петрушку и помидоры, черный молотый перец, другие специи.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2266,'Убрать с огня через две или три минуты.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Блюдо для праздничного стола, чернослив придаст начинке сладковатую ноту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Репчатый лук и морковь нарезать кубиками, чернослив обдать кипящей водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Все перемешать с перловкой, добавить соль и специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Куриное мясо промыть, натереть тушку снаружи и изнутри перцем и солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Начинить смесью овощей с перловкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Выложить в рукав вместе с остатками каши, печь в течение часа в духовом шкафу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2267,'Температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Молодой картофель очистить, разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Застелить фольгой противень, выложить картошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Приготовить заливку из оливкового масла, свежего сока лимона, рубленого чеснока, орегано, залить картошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Соль и молотый перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Залить блюдо водой, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Поставить в духовку, прогревать в течение 45 – 60 минут, несколько раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2268,'Продукт должен стать румяным, впитать всю жидкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Отделить желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Отдельно перемешать творог, сметану, сахарную пудру, ванилин из пакетика, картофельный крахмал, сырые желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Массу взбить, она должна стать однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Белки охладить, взбить в плотную пену, вмешать в творожную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Форму для выпекания смазать маслом, выложить творог, разровнять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Очистить от кожуры, белых перегородок и косточек апельсины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Выложить в блендер, добавить в блендер вместе с оставшимся крахмалом, взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Вылить на творожную массу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Поставить блюдо в разогретую духовку, печь при температуре 180 градусов в течение 40 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2269,'Блюдо остудить в форме и нарезать порциями.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Банан очистить и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Вишню разморозить, отжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Творог перемешать с мёдом. Если продукт густоват, его можно предварительно растопить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Для сворачивания «роллов» взять лист рисовой бумаги, опустить на несколько секунд в миску с теплой водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Намокший лист выложить на твердую поверхность, смазать творогом, края оставить свободными.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Выложить на ближний край по две полоски банана, несколько вишен.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Свернуть ролл, закрыть края боковыми краями бумаги.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Выложить рулет на тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'Таким же образом приготовить все рулеты, тарелку на 20 минут поставить в морозильную камеру.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2270,'При подаче нарезать роллы на части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2271,'В блендере измельчить ломтики моркови, добавить морковный сок и тщательно перемешать. Влить сметану, кусочки лайма и специи (по желанию). Разлить по бокалам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Куриную грудку нарезать полосками в сантиметр шириной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Молодой лук разделить на зеленую и белую части, первую – мелко порубить, вторую – разрезать пополам вдоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Ошпарить помидор кипятком, кожуру снять, мякоть нарезать небольшими кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Отдельно перемешать карри и просеянную пшеничную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Сковороду смазать растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Выложить курицу, обжарить до образования золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Добавить белый лук, обжарить еще немного, затем – помидоры, прогреть три минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'В заключение – мука с карри и нарезанный кусочками консервированный ананас.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Выпарить блюдо на тихом огне в течение пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2272,'Соль – по вкусу, добавить остатки зеленого лука, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Соединение в одном блюде разнородных продуктов: редиса, апельсина и перца чили получается неожиданно вкусным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Апельсин вымыть, снять половину цедры, смешать с оливковым маслом, оставить для пропитывания на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Вымыть редис, нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Остальные апельсины очистить от кожуры и пленок, нарезать мякоть острым ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Острый перец чили очистить от семян, нарезать полукольцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Промыть зеленый салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Выложить в тарелки редис, листья салата и апельсины.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Растолочь в ступке розовый перец, смешать с перцем чили, маслом, посолить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2273,'Салат полить полученной заправкой, дать постоять в течение пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Сливочное масло комнатной температуры взбить со сгущенным молоком','https://vkuso.ru/data/cache/data/cd/72409588f8e79cd_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'К творогу добавить взбитое со сгущенным молоком масло и все тщательно перемешать, при помощи погружного блендера.','https://vkuso.ru/data/cache/data/e1/79cae31018aaee1_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Разделить массу на 2 части.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Форму для пасхи установить на тарелку. Марлю смочить водой и отжать. Уложить марлю, в 2-3 слоя, в пасочницу.','https://vkuso.ru/data/cache/data/05/53026088a3b9405_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Полученные массы хаотично распределить по форме.','https://vkuso.ru/data/cache/data/80/1da6764dc361680_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Края марли аккуратно сложить, закрывая творожную массу. Сверху установить тарелку, а не нее груз. Убрать форму с грузом в холодильник, минимум на 14 часов. (время зависит от влажности творога, моя пасха стояла почти 24 часа). Периодически сливая жидкость, которая будет образовываться на тарелке.','https://vkuso.ru/data/cache/data/7a/3cd2765e3aeb37a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2274,'Перед подачей снять верхнюю марлю, накрыть пасху перевёрнутой сервировочной тарелкой и аккуратно перевернуть. Снять пасочницу и марлю.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'Емкость для выпекания застелить пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'В каждой грудке сделать вдоль филе глубокий надрез, отступая по два сантиметра от краев. В результате должен получиться «кармашек».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'В отдельной посуде перемешать «голубой» сыр, «Пармезан» или «Моцареллу» с нежирной сметаной или йогуртом, соль и перец черный молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'Полученной массой нафаршировать «кармашки», обернуть каждую куриную грудку тонко нерезаной ветчиной, закрепить зубочисткой или небольшой деревянной шпажкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'Готовые грудки выложить на противень, смазать оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'Печь в течение 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2275,'Готовое блюдо подержать еще пять минут в остывающей духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Творог взбить с сырым яйцом, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Добавить мёд, нарезанное яблоко и мак.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Кожицу с яблока, по желанию, можно снять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Готовить блюдо в пароварке в течение 20 – 25 минут, в духовом шкафу – 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2276,'Запеканку остудить, подать с мёдом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Хорошо вымыть плод лимона, нарезать крупными кусочками вместе с цедрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Косточки вынуть, измельчить с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Курагу предварительно замочить в кипятке, продукт должен быть эластичным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Измельчить, как и лимон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Порубить грецкие орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Перемешать все ингредиенты, добавить жидкий мёд, всыпать хлопья геркулеса. Перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Массу выложить на антипригарный противень с толстым дном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Блюдо поставить в духовой шкаф, печь при температуре 200 градусов в течение 15 – 20 минут, масса не должна пригореть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Готовое изделие вынуть, переложить на пищевую пленку, завернуть со всех сторон и убрать в холодильник до полного застывания на три-четыре часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2277,'Готовую массу нарезать на батончики.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2278,'С замороженных бананов снять кожуру, нарезать кусочками, сложить в блендер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2278,'С яблок снять кожуру, мякоть нарезать небольшими кусочками и тоже положить в блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2278,'Добавить молотую корицу, молоко, взбить до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2278,'Смузи разлить в бокалы, украсить дольками яблок, присыпать корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Говядину нарезать на порционные кусочки, обжарить со всех сторон на растительном масле до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Мясо посолить, поперчить, добавить специи, воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Тушить до готовности в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Промыть шампиньоны, разрезать на четыре части, добавить к мясу, тушить 10 – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Нарезать соломкой морковь, репчатый лук – кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Добавить к мясу и грибам овощи, тушить все вместе, под крышкой, в течение 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'При готовности овощей добавить размороженный зеленый горошек, готовить две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Перловую крупу промыть, залить большим количеством воды на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Утром слить воду, продукт промыть еще раз, сварить кашу в подсоленной воде. Жидкость должна впитаться, остатки слить, кастрюлю укутать одеялом, подержать так до остывания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Добавить в перловку грибы и овощи.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2279,'Массу осторожно перемешать, подержать на огне в течение двух минут, подать к столу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2280,'В большой миске смешать овсяную и пшеничную муку, сахар, разрыхлитель, ванильный сахар, корицу и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2280,'Влить растопленное сливочное масло, мед и воду, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2280,'Разделить тесто на части, скатать шарики и сформировать печенье.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2280,'Выложить печенье на противень, застеленный бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2281,'Измельчить овощи и зеленый лук в блендере, добавить остальные ингредиенты и перемешать. Разлить по бокалам и сразу подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2282,'Чистим овощи и прокручиваем их на мясорубке с луком и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2282,'Добавляем к прокрученным овощам нарезанный укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2282,'Также добавим кефир, соду и куриные яйца. Солим по своему вкусу и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2282,'Теперь добавим муку и хорошо перемешаем наше овощное тесто до однородной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2282,'Жарим овощные оладьи на разогретом в сковороде растительном масле с двух сторон на среднем огне до красивого золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Репчатый лук нарезать кольцами или полукольцами.','https://vkuso.ru/data/cache/data/a8/9d92e40f66162a8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Переложить в глубокую миску. Добавить две столовые ложки сахара, 4 столовые ложки уксуса, 1/2 чайной ложки соли и 8 столовых ложек воды. Тщательно все перемешать. Миску закрыть пищевой пленкой, поставить в холодильник мариноваться на 5-6 часов.','https://vkuso.ru/data/cache/data/31/74f85c0d28b4331_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Мясо хорошо вымыть обсушить и нарезать кубиками.','https://vkuso.ru/data/cache/data/31/67daed98f269531_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Переложить в глубокую посуду. Влить сок одного лимона, одну столовую ложку уксуса, добавить соль, перец и приправу для мяса. Хорошенько все перемешать и убрать в холодильник на 5-6 часов, а лучше на ночь.','https://vkuso.ru/data/cache/data/d7/dcab0d8e92545d7_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Сливаем с лука лишнюю жидкость и аккуратно укладываем его в рукав.','https://vkuso.ru/data/cache/data/29/2bdbad7b2a13329_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Свинину выкладываем на луковую подушку и завязываем рукав. Прокалываем его сверху в нескольких местах. Отправляем в разогретую до 250 градусов духовку на 20 минут. Затем убавляем огонь до 180 градусов и готовим еще 40 минут.','https://vkuso.ru/data/cache/data/e5/e27dec2488c02e5_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Вынимаем мясо и сверху разрезаем рукав. Аккуратно переворачиваем кусочки на другую сторону, не затрагивая луковую подушку. Шашлык поливаем образовавшейся жидкостью и еще на 20 минут отправляем в духовку (при 180 градусах).','https://vkuso.ru/data/cache/data/52/e9cc840c9740052_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2283,'Приятного аппетита!','https://vkuso.ru/data/cache/data/a9/6fea656a36fd1a9_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Перемешать любой фарш, предварительно отваренную гречку, измельченные с помощью блендера луковицы, сырые куриные яйца, сметану, перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Сформовать тефтели, обвалять в муке, потушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Налить в небольшую кастрюлю немного растительного масла, сложить изделия.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Приготовить соус из корнеплода, измельченного на терке для «корейской» моркови.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Нарезать полукольцами репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Овощи потушить на той же самой сковороде с маслом, где тушились тефтели.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Влить томатную пасту, соль, перец, измельченный чеснок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Массу хорошо перемешать, кипятить две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2284,'Готовый соус вылить на тефтели, прогревать на среднем огне в течение 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'Цветную капусту разобрать, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'Смешать в миске большого объема оливковое масло, измельченный чеснок, четверть стакана тертого сыра «Пармезан» или «Российского».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'В смесь добавить капусту, перемешать, выложить массу на противень, застеленный фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'Посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'Печь в духовке в течение 45 минут, каждый 15 минут – переворачивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2285,'Незадолго до готовности блюдо посыпать остатками тертого «Пармезана».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2286,'Куриные грудки промыть, выложить в чашку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2286,'Отдельно перемешать молоко с солью, залить мясо, поставить в холодильник на ночь для маринования.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2286,'Смешать зиру, паприку, измельченный чеснок и рубленый мускатный орех, куркуму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2286,'Влить темный соевый соус и жидкий мёд, перемешать, обмазать смесью грудки, оставить на полчаса для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2286,'Обвязать грудки капроновой ниткой или шпагатом, выложить на противень, поставить в духовку на 20 минут, температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2287,'Очистить киви и порезать на ломтики, из виноградин извлечь косточки. Смешать все ингредиенты в блендере до консистенции смузи, разлить по бокалам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2288,'Насыпать каркаде в миску, залить 4 стаканами кипятка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2288,'Накрыть, оставить на три-четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2288,'Готовый чай процедить в графин, добавить 4 стакана холодной воды и гранатовый сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2288,'Отправить напиток в холодильник на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'Вбить в теплый кефир яйца, размешать венчиком в однородную массу, всыпать сахар, подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'По частям, помешивая массу венчиком, подсыпать муку, до получения теста, как для приготовления оладий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'Нагреть молоко примерно до 90 градусов и тонкой струйкой добавить, постоянно размешивая в тесто, дать ему постоять четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'Если за это время тесто станет чересчур густым, то можно добавить еще немного молока и размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'Смазать нагретую сковороду растительным маслом, вылить порцию теста, равномерно распределить ее по всей поверхности, наклоняя сковороду во все стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2289,'После появления на поверхности блина пузырьков перевернуть его на другую сторону, поджарить до слегка коричневатого цвета, переложить на тарелку, промазать маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Перемешать муку, дрожжи, добавить сахар, соль, влить слегка подогретое молоко и сметану, вымесить тесто до эластичности, поставить «созреть» в теплое место, за 2 часа дважды обмять и дать еще раз подняться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Порубить очень мелко пару-тройку (зависит от их размера) головок чеснока, распустить масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Из небольшой порции теста раскатать сочник по форме напоминающий грушу примерно 20х10 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Желательно в процессе раскатывания не использовать масло и муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Готовый раскатанный сочень присыпать чесноком (его можно заменить семенем кунжута), вдавить его кусочки, прокатав скалкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2290,'Обжарить лепешки  на сухой сковороде при нагреве чуть выше среднего с одной и другой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2291,'Натереть сыр, очистить чеснок, маслины порезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2291,'В чашу блендера положить помидоры с чесноком, залить маслом с вяленых помидор, взбить до гомогенного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2291,'Отварить согласно инструкции макароны в подсоленной воде, слить ее, но примерно четверть стакана оставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2291,'Макароны выложить в сковородку, добавить смесь из чеснока и помидоров, оливки, каперсы и оставленную от варки макарон воду, перемешать, поперчить, прогреть 3-4 минуты на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2291,'Горячие макароны фарфалле с вялеными помидорами и каперсами присыпать сырной стружкой, размешать и сразу подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Вымыть хорошо зелень и помидоры, обсушить их.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Протереть на средней терке сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Зелень нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Помидоры порезать на колечки, порезать на куски ветчину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Лист лаваша побрызгать водой, уложить его (подрумяненной стороной вверх) на сковороду с разогретым маслом, чтобы края свисали.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'По центру разложить помидор, чуть присолить, прикрыть ветчиной (колбасой), залить разболтанным яйцом, присыпать сыром с зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Загнуть края листа внутрь, прикрыв начинку, поджарить до появления корочки (степень зажарки регулировать по вкусу).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2292,'Осторожно перевернуть «конвертик», обжарить ветчину с помидорами в армянском лаваше с другой стороны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Включить для прогревания до 180 градусов духовку, плоды томатов надрезать крестом, перцы разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Разложить на противне овощи, побрызгать их оливковым маслом, надрезы заполнить розмарином, поместить в уже прогретую духовку на треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Вынуть розмарин из томатов, удалить с плодов шкурку, помесить их в блендер, измельчить до состояния пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Перемешать с томатным соком овощное пюре, нагреть его до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Проварить томатный супчик из печеных помидоров и перцев 5-6 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2293,'Приправить перцем, солью, влить оливковое масло, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2294,'Всыпать в чашу миксера сахар, добавить масло, перемешать, добавить растопленный на водяной бане шоколад, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2294,'Вбить в однородную массу яйца, добавить ваниль и измельченные орехи, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2294,'Заполнить им форму, запечь при 150 градусах до корочки, слегка остудить, вынуть из формы перевернув на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2294,'Для оформления верха приготовить глазурь из растопленного на водяной бане шоколада с добавлением масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Перебрать изюм, залить горячей водой, дать постоять минут 5, воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Перемешать изюм с цедрой, влить ром, дать постоять пару-тройку часов, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Дать обсохнуть, припудрить мукой перед добавлением в тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Перемешать масло с кипящим молоком, дать чуть остыть, вылить в чашу миксера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Добавить дрожжи, перемешать, всыпать муку, сахар, специи, вбить яйцо, вымесить тесто до однородной консистенции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Прикрыть емкость чуть влажным х\б полотенцем, оставить на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Вмешать цукаты, кусочки яблок и цедру, дать постоять еще час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Включить для прогрева до 220 градусов духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Разделить тесто примерно на 20 порций, сформовать булочки, переложить их с промежутками в 3-4 сантиметра на противень, выстланный пергаментом, прикрыть слегка влажной тканью, дать постоять час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Смазать булочки разболтанным яйцом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Перемешать 5 ст. л. воды с 70 г муки до состояния достаточно густой пасты, заполнить шприц, нарисовать на булочках крест.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Поставить противень в уже разогретую духовку примерно на полчаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2295,'Достать подрумяненные булочки, смазать джемом, подать к столу горячими.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2296,'орезать банан на кусочки, размять вилкой, добавить масло, яйцо, ваниль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2296,'Перемешать сухие ингредиенты в однородную массу, объединить с банановой смесью, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2296,'Готовое тесто с большими промежутками выкладывать столовой ложкой на противень, выстланный пергаментом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2296,'Выпекать около трети часа при температуре примерно в 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2297,'Порезать мякоть курицы на кубики 2х2 см, поперчить, посолить, всыпать специи, добавить майонез, перемешать, дать постоять час в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2297,'На плоское блюдо высыпать сухари, нанизать мясо на вымоченные в воде бамбуковые шпажки, обмакнуть каждую сторону в сухари.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2297,'Обжарить панированные шашлычки из курицы на сковороде в большом количестве хорошо разогретого масла со всех сторон примерно по 4 минуты, подать горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2298,'Верхушку помидоров надрезать крест-накрест, положить в дуршлаг, окунуть на минуту в кипяток, удалить кожуру, порезать на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2298,'Зубки чеснока раздавить ножом, зажарить до румянца в сильно разогретом масле и вынуть их из сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2298,'Положить в масло помидоры, убавить нагрев до минимума, тушить 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2298,'Влить вино, добавить в соус сахар, специи, орегано и базилик, подсолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2298,'Снять соус с плиты, слегка остудить, протереть ложкой сквозь сито для удаления помидорных семечек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2299,'Сложить печенье в пакет, прокатать скалкой, крошку перемешать с орехами и вареной сгущенкой в однородную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2299,'Руководствуясь своей фантазией сформовать из смеси торт «Муравейник» из печенья и сгущенки с грецкими орехами, убрать на ночь в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2299,'Застывший десерт покрыть шоколадной глазурью, присыпать ореховой крошкой и подержать еще немного в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2300,'Измельчить и перемешать все ингредиенты для тефтелей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2300,'Скатать небольшие шарики, убрать на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2300,'Обжарить до золотистости в сотейнике кубики лука, всыпать порубленную зелень, подсолить, поперчить, добавить паприку, воду, томатную пасту, перемешать, дать закипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2300,'Поместить в соус тефтели и горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2300,'Готовить тефтели в томатном соусе с зеленым горошком и зеленью на малом огне около получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2301,'Надрезать верхушки томатов, поместить на пару минут в кипяток, очистить от шкурки, удалить семечки, порезать кубиками, переложить на сито для стекания сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2301,'Обжарить на масле чеснок с острым перцем и анчоусами, добавить каперсы и оливки, жарить еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2301,'Положить в сковороду помидоры, накрыть крышкой, тушить примерно четверть часа, добавить петрушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2301,'Отварить под крышкой спагетти на большом огне, откинуть на дуршлаг, переложить в сковороду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2301,'Смешать спагетти с соусом из анчоусов, оливок и каперсов, прогреть пару минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2302,'Морковь и банан нарезать кусочками, измельчить в блендере. Добавить сок и йогурт, перемешать. Разлить в стаканы и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Насыпать просеянную подсоленную муку горкой, добавить дрожжи, сделать в верху углубление.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Перемешать теплую воду и масло, влить в углубление, вымесить тесто, оставить в тепле для «созревания».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Когда объем увеличится примерно в 2 раза тесто обмять и дать еще раз подняться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Противень смазать маслом, притрусить мукой, тесто равномерным слоем распределить по его поверхности, сформовать бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Смазать основу для пиццы маслом, размазать равномерно готовый соус для пиццы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Прикрыть слоем тертого сыра, поверх разложить начинку, обжаренный бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2303,'Выпекать примерно 12 минут в разогретой чуть ниже 230 градусов духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2304,'Сливы порезать на дольки, выложить в форму, включить прогреваться духовку, 160 градусов будет достаточно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2304,'Смешать миксером яйца с молоком или сливками, всыпать муку, ваниль, сахар, взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2304,'Полученной массой залить сливы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2304,'Выпекать ванильный клафути со сливами около часа или чуть больше до появления у выпечки золотого «румянца».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Перебрать чечевицу, промыть, поставить варить почти до готовности, отвар сцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Разогреть хорошо сковороду, обжарить кусочки баклажана около 10 минут, всыпать кубики лука, обжарить до золотистости, переложить овощи в дуршлаг, чтобы масло стекло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Разогреть в сковороде масло, обжарить булгур, тимьян с добавлением куркумы, корицы, сахара, соли, душистого перца, лаврового листа, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Всыпать чечевицу, долить воду, чтобы она ее полностью покрыла, но не выше 1,5 мм, перемешать, дать закипеть, варить минут 5-7.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Закрыть крышкой, поставить вегетарианский плов с булгуром, чечевицей и баклажаном в прогретую до 160 градусов духовку на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2305,'Добавить лук и баклажаны, аккуратно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Сварить курицу, остудить в бульоне, порезать на полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Яйца разрезать каждое на 8 частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Морковку крупно натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Лук нарезать на полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Объединить все ингредиенты, подсолить, поперчить, приправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2306,'Аккуратно перемешать, переложить в салатник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Включить для прогрева до 220 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Перемолоть блендером куриное филе, добавить яйцо, зеленый лук, чеснок, горчицу, муку, чили, подсолить, поперчить, перемешать в однородную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Нарезать моцареллу на 36 кубиков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Всыпать молотый миндаль или панировочные сухари в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Смочить ладони водой, взять столовую ложку мясной массы, положить в центр кусочек моцареллы, скатать в шарик, обвалять в панировочной смеси, должно получиться 30-35 мясных шариков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'В воке разогреть масло при среднем нагреве примерно до 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Обжарить шарики порциями, обсушить на бумажном полотенце от излишков жира.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Можно блюдо приготовить и в духовке, прогретой до 220 градусов – 10 минут, снизить температуру до 190 градусов и запекать еще 20 минут до появления корочки темного соломенного цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Добавить к соусу чили топленое масло, подогреть в небольшом сотейнике до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2307,'Залить острым соусом запеченные шарики и сразу подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Растереть сахар с желтками, перемешать с растопленным маслом, мукой, и гашеной содой, вымесить тесто, убрать на полчаса в холодильник, из этого количества получится 4 коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Для второго коржа сахар взбить с белками, крупно порубить орехи, тесто поместить на сковороду, распределив равномерно по всей поверхности, присыпать орехами, промазать белковым кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Выпекать при 180 градусах около четверти часа до румяного безе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Аналогичным образом выпечь остальные коржи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Для приготовления крема взбить сгущенку и масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2308,'Холодные коржи для торта смазать масляным кремом, верх оформить дроблеными орехами, убрать на 6-10 часов в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Отделить желтки и взбить с маслом, всыпать сахар, добавить погашенную соду, хорошо еще раз взбить, чтобы растворился сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Порциями всыпать муку, перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Заполнить полученным тестом выстланную пергаментом и смазанную маслом форму, поместить ее в уже прогретую примерно до 180 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Готовую основу для торта «Пёрышко зебры» с суфле остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Для приготовления суфле дать набухнуть в небольшом количестве воды желатину, прогреть его, размешивая до прозрачности и дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Мелкий сахар взбить с охлажденными белками и лимонной кислотой в устойчивые пики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Соединить с желатиновым раствором, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'В сотейнике с толстым дном нагреть шоколад на паровой бане вместе с растительным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'К половине суфле добавить жидкий шоколад, тщательно перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Остывший готовый корж поместить в форму, по центру выложить, чередуя друг с другом, белое и шоколадное суфле, зубочисткой нанести «паутинку».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2309,'Убрать торт в холодильник, для более быстрого застывания можно поместить десерт в морозильник на треть часа, достать, и удалить бумагу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'В небольшой кастрюльке взбить подсоленное молоко, порошок какао, нагреть смесь до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Залить в миску с мелко поломанным шоколадом, перемешать в однородную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Растворить в чашке молока сахар при нагревании.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Желтки взбить и соединить с молочным сиропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Проварить полученный состав при слабом нагреве до получения густой смеси.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Смешать заварной крем (добавлять через сито) и шоколадную массу, хорошо вымешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Емкость с домашним мороженым «Джелато шоколато» установить в миску большего объема, заполненную колотым льдом, накрыть пленкой, помесить в холодильник, чтобы смесь хорошо охладилась.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2310,'Переложить ее в мороженицу и приготовить лакомство согласно инструкции к аппарату.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Размешать, варить еще минут 7, пока не испарится излишняя жидкость.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Положить все специи, перемешать, дать остыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Притрусить стол мукой, раскатать одну порцию теста в пласт и вырезать стаканом или кружкой кружочки, переложить их на противень, выстланный листом пергамента.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'Сразу приготовим маринад для овощей. В небольшую мисочку наливаем 4-5 ст.л. растительного масла (у меня подсолнечное), кладем 1 столовую ложку жидкого меда (засахаренный растопите), добавляем 2 столовые ложки лимонного сока, половинку чайной ложки соли (или по вкусу), черный молотый перец ,1,5 ч.л., приправы "Итальянские травы" и два зубчика измельченного чеснока (можно заменить на сухой). Хорошо перемешиваем и заправка готова.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'Лук нарезать кольцами.','https://vkuso.ru/data/cache/data/2e/07980322c965d2e_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'Лук перекладываем в глубокую посуду вливаем заправку и хорошо перемешиваем.','https://vkuso.ru/data/cache/data/8d/42a07cf2bd1fc8d_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'Помидоры нарезаем не очень тонкими кружочками. Выбирайте плотные плоды среднего размера.','https://vkuso.ru/data/cache/data/1e/aa0673a4d0cfb1e_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'В салатницу слоями выкладываем помидоры и лук. Закрываем крышкой или затягиваем пищевой пленкой, чтобы другие продукты в холодильнике не впитывали запах закуски. Оставляем в холодильнике буквально на полчаса - за это время овощи охладятся и пропитаются душистой заправкой.','https://vkuso.ru/data/cache/data/ca/b40461524269bca_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2311,'Приятного аппетита!','https://vkuso.ru/data/cache/data/f0/b64a5caebca14f0_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2312,'В форму для запекания выложить сыр фета и томаты черри. Затем пропустить чеснок через пресс, молоть черный перец и полить оливковым маслом. Разогреть духовку до 200 градусов и отправить форму в духовку на 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2312,'Пока готовится сыр с томатами, в это время отварить спагетти. Готовим спагетти на 2 минуты меньше, чем указано на упаковке. Затем снять с огня и слить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2312,'Как раз приготовился сыр с томатами, достаем из духовки. Размять вилкой или лопаткой сыр и томаты. Получится соус. В него отправляем спагетти и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2312,'Подавать спагетти можно с листиками базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2313,'В глубокую миску вылить молоко, добавить к нему сахар и соль, вбить яйца и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2313,'Затем добавить разрыхлитель и муку. Тщательно перемешать, чтобы не осталось комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2313,'Укроп мелко порубить ножом, сыр натереть на мелкой терке. Добавить сыр и зелень в тесто, затем влить растительное масло и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2313,'Сковороду для блинов смазать растительным маслом 1 раз, затем разливаем тесто и выпекаем блины. Готовить нужно на медленном огне с двух сторон до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Моем, чистим, потрошим кильку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Панировка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Нарезаем шампиньоны, панируем и выкладываем на рыбу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Нарезаем плавленый сыр и выкладываем на грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Выкладываем ещё слой грибов и накрываем рыбой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2314,'Смазываем кильку растительным маслом. Заворачиваем в фольгу и жарим на углях 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2315,'Приготовить тесто. Для этого смешать кефир, соль, сахар. Добавить соду и тщательно перемешать. Аккуратно ввести в кефир тертый сыр и добавить муку. Замесить руками тесто. Получится очень нежное, мягкое тесто. Разделить тесто на 5 одинаковых частей, скатать из них шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2315,'Раскатать каждый шарик и положить в середину измельченную ветчину, защипнуть края, собрав их к центру. Перевернуть шарик с начинкой швом вниз и раскатать скалкой, чтобы равномерно распределилась начинка внутри лепешки. Обжарить сырные лепешки с начинкой из ветчины с каждой стороны на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Перемешать сахар, муку и соль, можно добавить натертую цедру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Растереть смесь с размягченным маслом до состояния маслянистой крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Влить кефир, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Полученное тесто разделить пополам, завернуть каждый колобок в пленку, убрать на пару часов (можно дней) в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Включить для прогрева до 180 градусов духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Для начинки очищенные яблоки порезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Высыпать в кастрюлю с сахаром, добавить сок лимона, проварить, накрыв крышкой минут 10.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Со второй порцией теста поступить аналогичным образом, на каждом кружке сделать надрезы.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Разложенные на листе кружки смазать небольшим количеством воды, положить на каждый по ложечке яблочного пюре, прикрыть кружками с прорезью, края тщательно обмять вилкой, окунув ее предварительно в муку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Смазать крошки пироги с яблочной начинкой разболтанным со столовой ложкой воды яйцом, посыпать верх сахаром.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2316,'Отправить примерно на треть часа в духовку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2317,'В чашу блендера отправляем очищенный чеснок, томатную пасту, соль, сахар, черный перец, растительное масло, воду и укроп.','https://vkuso.ru/data/cache/data/54/665514150aff054_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2317,'Хорошо измельчаем до однородной консистенции. Вот и всё! Соус готов!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2318,'Насыпать хлопья в пиалу, сверху положить разрезанные на четвертинки ириски, залить все молоком чуть выше хлопьев, примерно на пару сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2318,'Поставить кашу на 4 минуты в микроволновку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Добавить к просеянной муке порезанное на кусочки масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Растереть до получения крошки, смешать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Вымесить эластичное и не слишком крутое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Обернуть пленкой, убрать его на час в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Шар теста разрезать на 4 части, раскатать каждую в пласт, порезать его на квадратики примерно7х7 см.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'По центру каждого положить небольшую порцию густого варенья, скатать в рожок, края тщательно защипать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Выпекать кифлики примерно минут 20-25 при температуре в 200 градусов до легкой золотистости.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2319,'Готовую выпечку обвалять в сахарной пудре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'Яйцо вбиваем в миску, можно посолить, поперчить и добавить гранулированный укроп, все хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'В другую миску всыпаем муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'Мясо нарезаем на порционные кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'Отбиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'Солим, перчим, и посыпаем приправой для мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2320,'Мясо отпускаем в яйцо, потом в муку и обжариваем на разогретой сковороде до корочки 3-4 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2321,'Добавить к творогу сметану и сахарную пудру, растереть до состояния пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2321,'Застелить коврик пищевой пленкой, присыпать ее кунжутом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2321,'Разложить ровным слоем творожную массу, а на нее фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2321,'С помощью коврика свернуть творог в рулет, отправить минут на 20-30 в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2321,'Смочить нож водой, нарезать творожные роллы с киви и бананами, украсить их орехами, шоколадной стружкой и сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2322,'Порезать авокадо и огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2322,'Салат нарвать на кусочки руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2322,'Сдобрить специями, всыпать семя льна, подсолить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2322,'Приправить свежий зеленый салат с авокадо и огурцами оливковым маслом и осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'Миндаль залить водой и оставить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'На следующий день слить воду и промыть орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'В чашу блендера всыпать орехи, влить воду, добавить мед или 2 финика без косточек и щепотку соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'Включить блендер и измельчить в течении минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'Процедить молоко через марлю и отжать оставшийся жмых.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2323,'Готовое молоко перелить в бутылку или кувшин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2324,'В глубокую миску вбить яйца, всыпать стакан сахара, положить 2 пачки творога, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2324,'В другой смешать руками просеянную муку, сахар, натертый маргарин и соду, должна получиться маслянистая крошка, которую разделить на 2 части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2324,'Одну из них насыпать ровным слоем на смазанный маслом противень, вылить на нее творожную массу разровнять, присыпать второй половиной крошки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2324,'Поставить пирог примерно на треть часа в прогретую духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Включить для разогрева до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Взбить слегка охлажденное масло с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Вбить яйца, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Влить ванильную эссенцию еще раз тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Добавить к смеси небольшие кубики свежих яблок (груш, можно заменить на изюм), перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'В смесь просеять муку с разрыхлителем, вымесить достаточно мягкое тесто без комочков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Промазать форму маслом, заполнить тестом, присыпать дробленым орехами (можно кунжутом).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2325,'Отправить яблочный пирог с орехами на масле примерно на треть часа в уже прогретую духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'Порезать на кубики морковку, лук, картошку, шпинат – соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'Распустить в сотейнике масло, положить лук, довести его до золотистости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'Всыпать морковку, картошку, жарить все вместе еще минуты 4, добавить в конце шпинат, прогреть еще пару минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'В кастрюлю переложить тушеные овощи, влить овощной бульон (воду), молоко, сдобрить прованскими травами, перцем, солью, нагрев уменьшить до минимума, варить примерно полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'Всыпать макаронные изделия, варить суп до их полного размягчения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2326,'Влить сливки, всыпать крупную сырную стружку, чуть прогреть, убрать с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2327,'Отбить кусочки филе равномерно по всей площади, присыпать перцем, присолить, уложить смесь сыра, ветчины и петрушки, свернуть в трубочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2327,'Обвалять их в муке, а затем обмакнуть в подсоленное взбитое яйцо и снова обвалять в измельченном крекере, либо сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2327,'Переложить их на противень, задвинуть его на 25 мин в прогретую до 200 градусов духовку, готовить до появления слегка хрустящей корочки соломенного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2328,'Первым делом нужно приготовить вкусные домашние гренки. Снять с хлеба корку, нарезать мякиш кубиками. Если хлеб очень свежий, то его нужно немного подсушить. Можно это сделать на сухой сковороде или в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2328,'На сковородке хорошо разогреть сливочное масло, выложить на нее кубики хлеба и сразу перемешать, чтобы масло равномерно обволокло хлеб. Равномерно подрумянить гренки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2328,'Печень трески размять вилкой, предварительно слив с нее масло. Добавить к ней порезанные вареные яйца, выложить кукурузу и заправить майонезом. Размешать печень с остальными ингредиентами, выложить ее на листья салата. Перед подачей на стол сверху салата из печени трески насыпать гренки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'Промыть мясо, обсушить многослойным бумажным полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'Порезать зубки чеснока на клинышки, нашпиговать ими мясо со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'Залить в небольшой мисочке специи маслом, добавить горчицу, перемешать, обмазать этой пастой мясо, обернуть его несколькими слоями фольги, поставить на 12 часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'Уложить промаринованное мясо в фольге в форму, поместить в прогретую до 200 градусов духовку на полтора-два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'Запеченная свинина в горчичном маринаде в фольге будет готова, когда при протыкании ее ножом будет выделяться светлый и прозрачный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2329,'После этого аккуратно надрезать фольгу, отогнуть края, продолжить запекать еще минут 15 до образования на поверхности мяса коричневатой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2330,'Перемешать мягкое масло со сгущенным молоком, сиропом, какао, любым алкоголем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2330,'Добавить к смеси измельченную крошку печенья, хорошо перемешать, скатать шарики, как для пинг-понга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2330,'Обвалять их в небольшом количестве, оставленной крошки, перемешанной с порошком какао, стружкой кокоса или молотыми орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2330,'Шоколадный клубок из печенья со сгущенкой переложить на блюдо, поместить на час-два его в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Засыпать в блендер слегка обжаренные и очищенные от шелухи орехи, перемолоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'В сотейнике с толстым дном закарамелизовать до коричневого цвета сахар, всыпать орехи, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Приготовить пралине: вылить массу на противень, выстланный листом пергамента, дать остыть, смолоть блендером до состояния крошки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Масло с кусочками белого шоколада растопить в густую гомогенную массу на водяной бане, дать слегка остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Сформовать 10-12 шариков, в середину каждого положить по орешку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2338,'Выпекать лимонное безе с шоколадом в духовке надо примерно 1,5 часа при 60 градусах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Уложить каталонские конфеты с фундуком и белым шоколадом на блюдо, поставить его минут на 10 в морозильную камеру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'За это время растопить оставшийся молочный шоколад любым удобным способом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Слегка подмороженные конфетки обмакнуть в шоколад, и убрать еще на четверть часа в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2331,'Достать, нанести сеточку из белого шоколада, чуть охладить и подать к чаю.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2332,'Сварить сердце, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2332,'Морковь и сыр измельчить на крупной терке, луковицу мелко нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2332,'Разогреть масло, обжарить лук и морковь, чуть остудить, перемешать с сердцем и сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2332,'Салат с сердцем и плавленым сыром заправить майонезом, чуть поперчить, перемешать еще раз, дать чуть постоять, оформить верх зеленью и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2333,'Перемешать все ингредиенты для теста (муки взять столько, чтобы тесто перестало липнуть к рукам).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2333,'Раскатать в круг, поверх разложить любую начинку из продуктов, что оказались в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2333,'Пиццу на кефире с любимой начинкой поместить в духовку, испечь до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2334,'уковицу нашинковать кубиками, обжарить в масле до мягкости, добавить кусочки печени, обжарить все минут 6-7, периодически помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2334,'Переложить все в форму, подсолить, сдобрить перчиком, присыпать нашинкованным чесноком и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2334,'Сверху выложить кубики помидоров, присыпать натертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2334,'Отправить в хорошо прогретую духовку, держать до расплавления сырной стружки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Перемешать просеянную сахарную пудру с шоколадом и мелко смолотым кофе, включить духовку и прогреть до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Поместить в чашу миксера подсоленные белки, взбить на малой скорости, объем содержимого должен увеличиться примерно раза в 3.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Добавить, непрерывно взбивая, частями (по столовой ложке) сахарную пудру до появления белого цвета и образования пиков устойчивой формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Перед окончанием всыпать крахмал и влить уксус, взбивать еще минуту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Меренгу выложить ровным слоем на круг из бумаги для выпечки и отправить в уже разогретую до нужной температуры духовку, почти сразу снизить температуру на 30 градусов (примерно до 150).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Выпекать корж для порядка часа до появления хруста, но сохранения мягкости внутри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Дать ему остыть ночь в духовке с чуть приоткрытой дверцей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Достать холодные сливки, взбить их до появления видимых пиков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Нанести на холодный корж, присыпать сквозь ситечко порошком какао.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2335,'Убрать торт в холодильник, дать постоять около часа и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Измельчить печенье в очень мелкую крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Влить молоко, добавить какао, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Раскатать (на пленке) полученную массу в прямоугольный 5 мм пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Мягкое масло взбить со сгущенкой, всыпать стружку кокоса, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Уложить эту начинку на основание быстрого рулета «Баунти» из печенья, отступив по 5 см от края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2336,'Свернуть в трубочку, поставить на час в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Порезать мясо на порции (толщина должна быть до 2 см), аккуратно отбить, присыпать солью и перцем с обеих сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Грушу – на пластинки по 5 мм, сыр крупно натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Лист для выпечки смазать маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Уложить кусочки мяса, накрыть кусочками груши, присыпать сырной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Верх блюда оформить сеточкой из майонеза и засыпать маком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2337,'Готовить в прогретой до 190 градусов духовке примерно минут 40.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2338,'В миксере до устойчивой плотной пены взбить белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2338,'Постепенно, во время взбивания, добавлять порциями крахмал, сахарную пудру, лимонную кислоту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2338,'Натереть мелко шоколад, смешать ложкой с уже плотной белковой пеной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2338,'Застелить противень листом пергамента, выложить полученную массу небольшими порциями с большими промежутками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'С помощью миксера взбить желтки до начала изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Влить порцию коньяка, осторожно и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Добавить по ложке мягкий сыр, перемешивая каждый раз, до получения однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Мелко натереть шоколад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Сварить кофе и дать остыть, можно, при желании, добавить его (2 ст. л.) к крему из маскарпоне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Наполнить кремом кондитерский шприц, в широкий и низкий стакан выложить слой крема, далее – печенья, смоченного в кофе, присыпать шоколадной стружкой, повторить все слои.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Последним слоем в шоколадном тирамису с коньяком будет крем, присыпать его слоем порошка какао.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2339,'Убрать в холодильник на пару-тройку часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'В миску вбиваем куриные яйца, и добавляем сметану, взбиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'Затем туда же натираем сыр, и добавляем муку, перемешиваем. Убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'Куриное филе нужно распластать на 2 половинки, отбить слегка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'И затем солим, перчим и посыпаем приправой для курицы, убираем в сторону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'Куриное филе отпускаем в кляр, затем на разогретую сковороду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2340,'Обжариваем с 2 сторон по 2-3 минуты до корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2341,'Разварить помидоры до полного размягчения. Протереть их сквозь сито. Лук мелко порезать и обжарить на масле до золотого цвета. Добавить к обжаренному луку пюре томатное, гвоздику, лавровый лист, петрушку, влить бульон (его можно приготовить из кубиков) и вино, затем довести смесь до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2341,'Потом, помешивая, растворить кусочки сыра плавленого в супе, загустить при помощи крахмала, добавить остальные специи по собственному вкусу. Суп разлить по чашкам. Кусочки хлеба слегка обжарить на сухой сковороде, натереть чесноком, намазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2341,'Положить кусочки хлеба в каждую порцию, сверху на них выложить горкой тертый сыр. Чашки с супом поставить в духовку, чтобы на гренках сыр подрумянился. Домашний томатный суп с гренками и сыром подавать к столу горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2342,'Банан-шоколад.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2342,'Ягодный.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2342,'Арахисовый.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'Яблоки моем, чистим.','https://vkuso.ru/data/cache/data/b5/fd9e5f90cf18cb5_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'Затем нарезаем на маленькие или средние кубики,','https://vkuso.ru/data/cache/data/c4/e881da152233fc4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'Затем яблоки нужно потушить. В разогретую сковороду добавляем еще 1 кусочек сливочного масла, добавляем яблоки и тушим 4 минуты, добавляем сахар и еще тушим минуты 2. Перекладываем в миску.','https://vkuso.ru/data/cache/data/e7/df3aa77254679e7_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'На этой же сковороде обжариваем батон до корочки, точно так же можно добавить сливочное масло или растительное для обжарки.','https://vkuso.ru/data/cache/data/b7/147ee4a665f9fb7_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'Яблоки посыпаем корицей и перемешиваем.','https://vkuso.ru/data/cache/data/31/9a5b93ca5a23131_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2343,'На получившейся гренки укладываем яблоки, и подаем к чаю, Можно украсить мятой.','https://vkuso.ru/data/cache/data/c3/779f50c644055c3_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Из растопленного масла, сахара, орегано, и горчицы приготовить соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Раскатать в тонкий пласт тесто, уложить на него кусочки ветчины, а сверху – сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Свернуть пласт в трубочку, нарезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Переложить рулетики в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Залить соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2344,'Готовить в духовке до готовности, подавать горячими.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Перемешать сыр с пропущенным через пресс чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Нарезать палочки и укроп, разрезать лаваш на 4 равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Хорошо перемешать яйца с мукой, перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Промазать 1 пласт лаваша сыром, присыпать измельченными палочками и порубленным укропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Прикрыть вторым пластом лаваша.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Повторить все.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Когда закончатся все пласты лаваша разрезать полученное «сооружение» на 8 частей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2345,'Восточные гренки из лаваша со сливочным сыром обмакнуть в яйцо, обжарить до появления корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Заранее на полчаса залить мак кипятком, дать ему набухнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Слить лишнюю воду, мак размять в ступке, перемешать его с медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Орехи чуть поджарить, удалить шелуху, измельчить, пересыпать к начинке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Раскатать тесто в пласт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Распределить ровным слоем начинку, скатать в трубочку, согнуть в форме подковы, надрезать по всей длине.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2346,'Выпекать рулет из слоеного теста с маком и грецкими орехами, смазанный взбитым яйцом, в прогретой духовке до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Разрезать шарик теста на две равные части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Раскатать одну под размер формы, другую – чуть больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Форму заполнить раскатанным тестом, сформовать бортики, положить порубленный щавель, вылить на него разболтанное яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Накрыть все второй раскатанной частью, хорошо защипать края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Проделать надрезы для выхода пара.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2347,'Духовку разогреть до 200 градусов, пирог выпекать около трети часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2348,'Замесить из всех сухих ингредиентов и воды тесто, дать подняться, обмять дважды, разделить его на 4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2348,'Сформовать лепешки, промазать каждую водой, присыпать кунжутным семенем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2348,'Выпекать дрожжевые узбекские лепешки с кунжутом около получаса при температуре духовки 250 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Для маринада перемешать специи и натертый мелко чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Мясо порезать на кусочки примерно одного размера, перемешать их с маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Миску с мясом убрать на пару-тройку часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Шпажки на полчаса залить водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Нанизать кусочки курицы на шпажки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2349,'Готовить домашний шашлык из куриного филе на шпажках в духовке при 250 градусах, поворачивая каждые 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2350,'Разморозить отварные креветки. Отварить в течение нескольких минут креветки в кипятке. Затем креветки желательно очистить – в этом случае они лучше пропитаются соусом и специями. Если не хватает времени, можно и не чистить. Слегка посолить по своему вкусу, выложить на разогретую сковороду с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2350,'Оставить креветки на сковороде на несколько минут. После этого их залить соевым соусом, кетчупом, добавить измельченный чеснок. Когда креветки подрумянятся и свернутся «улиточками», выложить их на тарелку. Креветки к пиву, обжаренные в кетчупе, подавать в горячем виде. При подаче на стол можно сбрызнуть лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2351,'Тщательно смешать (с помощью миксера) до получения пышной массы белого цвета яйца с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2351,'Масло растопить, перемешать с яичной смесью и сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2351,'Всыпать порциями муку с добавлением соды, размешать ложкой до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2351,'Всыпать в тесто ягоды, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2351,'Выпекать быстрый пирог на сметане с ягодой выпекать при температуре духовки (прогреть заранее) около 180 градусов примерно 35 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Для основания чизкейка из мельчить печенье или бисквит в крошку, масло растопить, перемешать до получения маслянистой «мокрой» массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Форму заполнить крошкой (дно выстлать пергаментом), сделать небольшие бортики, утрамбовать с небольшим усилием ложкой, поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Для начинки тщательно смешать сыр, крахмал и сахар с подсоленной лимонной кислотой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Добавить по одному яйца и желтки, после каждого добавления хорошо перемешивать массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Положить сметану и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Полученную массу (1\2) уложить на основу, уложить на нее малину, прикрыть оставшейся половиной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2352,'Поставить на 10 минут в духовку с температурой 200 градусов, снизить нагрев до 110 градусов, «подсушить» чизкейк в духовке еще около полутора часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2353,'Порезать помидоры вместе с колбасой на пластинки, лук порубить мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2353,'Тортилью промазать кетчупом, посыпать луком (половиной), уложить на него колбасу, покрыть ее сеточкой из майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2353,'Положить слой из колечек помидора, присыпать луком, далее – натертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2353,'Отправить пиццу из тортильи за 10 минут в микроволновку на пару-тройку минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2354,'Перемолоть фундук до состояния муки (блендер или кофемолка вам в помощь).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2354,'Яйца и сахар хорошо перемешать и смешать с разрыхлителем и ореховой мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2354,'Подготовить форму, смазать маслом, заполнить полученным тестом, разровнять его.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2354,'Готовить кекс микроволновке на мощности 900 Вт около 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2354,'Переложить готовый кекс на блюдо, присыпать сахарной пудрой (можно добавить к ней корицы).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Открыть банку, слить жидкость, рыбу превратить в пюре с помощью вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Вбить яйцо, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Добавить к смеси нашинкованный мелкими кубиками лук и крупно натертый картофель, поперчить, добавить соль и еще раз хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Тесто разделить на равные части, каждую раскатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Уложить одну на противень, выложить на нее начинку, прикрыть второй половинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Хорошо защипать края, сделать сверху несколько дырочек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2355,'Выпекать быстрый и очень вкусный пирог с сайрой около получаса в разогретой до 180 градусов духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2356,'Порезать тонкий лаваш на равные полосы (прямоугольники).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2356,'Для начинки порезать ветчину брусочками, сыр крупно натереть, зелень порубить, все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2356,'Для любителей острого можно добавить натертый мелко зубчик чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2356,'Распределить начинку на поверхности нарезанных прямоугольников, свернуть их в трубочку или свернуть в виде конвертиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2356,'Разболтать яйцо в молоке, смазать верх, присыпать верх кунжутным семенем, отправить в духовку с температурой 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2357,'Сыры натереть на крупной терке, добавить яйца и немного черного молотого перца, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2357,'Тесто раскатать на 2 одинаковых прямоугольника (по размеру вашего листа).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2357,'На первый лист теста выкладываем начинку и разравниваем, прикрываем вторым листом теста и защипываем края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2357,'Для того, чтобы пирог после выпечки имел приятный блеск его необходимо смазать яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2357,'Выпекается пирог в разогретой духовке до 180 С около 15-20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Начинать приготовление торта надо с крема, поместить в чашу блендера сыр, сахарную пудру, сметану, все взбить в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Собрать шоколадный торт с творожным сыром без выпечки в нижеследующем порядке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Смазать печенье кремом, сделать из него первый слой (размер по желанию).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Присыпать ореховой крошкой, прикрыть печеньем, далее опять крем и т.д.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Когда закончится печенье, смазать кремом бока тортика, верх из крема присыпать крошкой из нескольких штук печенья, далее украсить по своему вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2358,'Убрать десерт на пару-тройку часов в холодильник, чтобы он стал мягким и нежным на вкус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2359,'Миксером (до побеления) взбить смесь желтков с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2359,'Добавить маскарпоне, хорошо еще раз перемешать в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2359,'Для начинки порезать ягоды клубники пластинками или кубиками, перемешать с кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2359,'Заполнить массой трубочки из кондитерского шприца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2360,'Перемешать в глубокой миске подсоленную муку с крахмалом, яйцами, горчицей, сметаной, измельченной петрушкой, горчицей, перцем, базиликом и колечками маслин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2360,'Полученную смесь вылить на противень, выстланный, промазанным малом пергаментом, разровнять ее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2360,'Выпекать закусочный рулет «Леопардовый» с красной рыбой около 7 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2360,'Дать чуть остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2360,'Отделить пласт от пергамента, смазать сыром, уложить слой из кусочков красной соленой рыбы, свернуть трубочкой – оригинальная закуска готова.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Порезать кубиками перец вместе с колбасой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Яйца перемешать со специями и горчицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Перемешать с начинкой, сыр крупно натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Форму смазать маслом, заполнить дно и бортики тестом, залить начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Оформить верх быстрого пирога из слоеного теста к завтраку майонезной сеточкой. Посыпать сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2361,'Выпекать пирог полчаса при 180 градусах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2362,'Перемешать все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2362,'Взять любые продукты для начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2362,'Разогреть масло в сковороде, вылить тесто, положить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2362,'Выпекать пиццу на майонезе и сметане за 10 минут под крышкой на медленном огне до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Перемешать соду с кефиром, подсолить, перемешать, всыпать муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Оставить его дозревать на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Для начинки порубить зелень, крупно натереть сыр, посолить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Шар теста разделить на 12-14 частей (зависит от диаметра сковороды), раскатать каждый в тонкую лепешку, по центру положить по ложке начинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Хорошо защипать вверх края, примять пальцами, раскатать еще раз до толщины около 2 мм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Жарить аварские лепешки на кефире Чуду с двух сторон на сковороде без масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2363,'Готовые лепешки смазать маслом, уложить на блюдо в стопку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2364,'Подготовить филе, вымыть, обсушить салфетками, обсыпать и втереть смесь молотого перца с паприкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2364,'В лоток засыпать 100 г соли, уложить филе, засыпать остатками соли, залить сверху коньяком, поставить на 12 часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2364,'Достать мясо, хорошо промыть, обсушить салфетками, обернуть марлей, поместить опять в холодильник примерно на сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2365,'В глубокую тарелку разбить яйца, всыпать специи, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2365,'Лаваш порезать на полосы шириной примерно по 10 см, сыр – пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2365,'Разогреть масло, обернуть сыр лавашом, обмакнуть в яичную смесь, обжарить с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2366,'Тщательно перемешать сахар, муку, кусочки яблок сушеных, разрыхлитель, изюм, соду, корицу и соль. Взбить яйца, вмешать масло растительное и молоко. Добавить к сухим ингредиентам. Перемешать до однородности. Смазать слегка сковороду маслом. Разогреть на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2366,'Выложить на сковороду оладьи (примерно по четверти стакана). Жарить, пока одна сторона не подрумянится. Перевернуть оладьи и жарить еще пару минут, пока не подрумянится и вторая сторона. Оладьи с изюмом и сушеными яблоками подавать к столу с медом, вареньем, кленовым сиропом – по собственному вкусу и желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Крупно натереть морковь, обжарить в масле, чуть присолить, переложить в небольшое сито, дать остыть и стечь маслу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Взбить белок в крепкую пену, осторожно перемешать с холодной морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Уложить смесь на пергамент, выпекать примерно треть часа при температуре духовки 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Смешать творог и сметану с порубленной зеленью с чесноком, поперчить, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Смазать рулет этой начинкой, свернуть в трубочку, обернуть пленкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2367,'Убрать в холодильник на пару-тройку часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2368,'Залить желатин небольшим количеством воды, печенье измельчить до состояния крошки, перемешать с кофе, заполнить массой форму, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2368,'Перемешать миксером мягкий сыр и сахар, влить йогурт, перемешать, добавить сливки, еще раз перемешать примерно 3 мин. на высокой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2368,'Приготовить на водяной бане раствор желатин, смешать с натуральным кофе и сливочной массой, все вместе хорошо вымешать, всыпать шоколадную стружку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2368,'Заполнить смесью форму, поставить кофейно-шоколадный десерт из печенья в холодильник для застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Срезать у булочки верх, удалить середину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Сыр крупно натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Порезать на кусочки помидор и мясо, уложить их в «стаканчик» из булочки, залить яйцом, присыпать сырной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Накрыть срезанным верхом, обернуть фольгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2369,'Выпекать мясо с сыром в булочке около получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Для приготовления коржей растопить масло на водяной бане, смешать его с сахаром, джемом, какао и шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'К нагретой смеси, не снимая с бани, добавить соду, перемешать, масса чуть увеличится и побелеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Снять с плиты, дать чуть остыть, по одному вмешать все яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'В массу всыпать муку, размешать ложкой, выложить на стол, окончательно вымесить тесто до однородности, разделить на 8 равных частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Раскатать каждый колобок до необходимого диаметра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Выпекать коржи для торта минут по 5-6 в прогретой до 220 градусов духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Вынуть, подровнять края, пока коржи еще горячие (шаблон 20 см).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Из смеси сахара и мака с хорошей сметаной приготовить крем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Для удобства торт собирать лучше в кольце от разъемной формы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Коржи промазать кремом (примерно по 5 ст. л. на каждый), сложить в стопку, поставить в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Утром удалить кольцо, при необходимости подровнять края.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2370,'Оформить верх по своему усмотрению, например, крошкой от коржей, дроблеными орехами и т.п.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Кабачок (только мякоть) крупно натереть, отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Вбить яйца, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Влить кефир, подсолить, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Всыпать в тесто для блинчиков из кабачка с петрушкой муку, вымесить до однородности, оставить примерно на четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Порубить петрушку, высыпать в тесто и размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Обжарить блинчики с обеих сторон на сухой сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2371,'Смазать маслом с 2 сторон, подать горячими.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2372,'Нарезать мясо по спирали, присыпать перцем, побрызгать соком граната, поставить минимум на час в холодильник, а лучше часа на 4.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2372,'Из смеси горчицы, майонеза, семян горчицы, лаврового листа приготовить соус и обмазать мясо со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2372,'Нарезать болгарский перец небольшими кубиками, перемешать с порубленным чесноком, положить начинки на мясо, свернуть трубочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2372,'Завернуть мясной рулет с болгарским перцем и чесноком в фольгу, запекать на среднем огне порядка полутора-двух часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2372,'В конце приготовления осторожно срезать верх фольги и дать появится на рулете румяной корочке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2373,'Порезать порционно сыр на свое усмотрение: брусочками, кубиками, пластинами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2373,'Чуть подогреть масло, перемешать его со специями и медом, залить этим маринадом сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2373,'Через час сыр в медовом маринаде с базиликом будет готов к подаче на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2374,'Порезать сыр с ветчиной на одинаковые брусочки, лаваш – полосами, равными по ширине ветчине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2374,'Разболтать вилкой яйцо с молоком, приправить специями, уложить на полоску лаваша зелень, и ветчину с сыром, свернуть конвертиком, обмакнуть в яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2374,'В сковороде разогреть масло, обжарить ветчину с сыром в конвертиках из лаваша с одной и другой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2375,'Открыть консервы, слить сок (чуть оставить), размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2375,'Смешать с парой яиц и нашинкованным маленькими кубиками луком, немного поперчить, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2375,'Батон порезать на ломтики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2375,'Смазать маслом, добавить слой начинки, оформить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2375,'Поместить в прогретую духовку для запекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Куриное филе подготавливаем к приготовлению. Нарезаем, у меня вышло по 6 кусочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Лук нарезаем соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Куриное филе перекладываем в миску, добавляем кефир, горчицу, соль, перец, лук репчатый, все хорошо перемешиваем. Оставляем на 30 минут для маринования куриного филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Готовые лепешки смазать топленым маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Болгарский перец нарезаем на прямоугольники. Сначала у меня получилось 3–4 кусочка, потом я еще раз нарезал на 2 части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Спустя полчаса берем шпажку и накалываем куриные кусочки и болгарский перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2376,'Перекладываем на противень (у меня стеклянный), поливаем оставшимся маринадом и распределяем лук. Отправляем в духовку на 60 минут (или более) до готовности. У меня шашлык приготовился за 1 час и 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Дрожжи измельчаем.','https://vkuso.ru/data/cache/data/94/1c615ab7fa71e94_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Добавляем 1 стакан теплой воды.','https://vkuso.ru/data/cache/data/4e/cb0bf2edddb464e_434x295_notrise.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Добавляем сахар 2 ст.л., муки 1 ст.л. и тщательно перемешиваем венчиком, пока комочки не исчезнут.','https://vkuso.ru/data/cache/data/75/ff57584a05c2575_434x295_notrise.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Оставляем опару подниматься на 10-15 минут.','https://vkuso.ru/data/cache/data/55/7e1ed2bcda37b55_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Просеиваем муку и добавляем в нее 1ч.л. соли.','https://vkuso.ru/data/cache/data/57/ad56cd5b4e49b57_434x295_notrise.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Когда опара поднялась, добавляем ее в муку и замешиваем тесто.','https://vkuso.ru/data/cache/data/d5/cda9a310bd06fd5_434x295_notrise.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Накрываем тесто полотенцем и ставим в теплое место на 30 минут.','https://vkuso.ru/data/cache/data/14/be46741df3ac714_434x295_notrise.png',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Когда тесто увеличилось в 2 раза, раскатываем из него колбаску и делим ее на 8 равных частей.','https://vkuso.ru/data/cache/data/0d/0e554d0494dab0d_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Каждую часть расплющиваем ладонью и внутрь кладем 1ч.л. сахара, это начинка.','https://vkuso.ru/data/cache/data/ea/fac1db5c3a906ea_434x295_notrise.png',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Заворачиваем края внутрь.','https://vkuso.ru/data/cache/data/4f/7a9dbf6ad9e1e4f_434x295_notrise.png',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Смазываем булочки взбитым яйцом, и посыпаем сахаром. Выпекаем булочки при 180°С до золотистой корочки.','https://vkuso.ru/data/cache/data/87/8c19768a7c47187_434x295_notrise.png',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2377,'Приятного аппетита!','https://vkuso.ru/data/cache/data/ff/a94263dce794cff_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2378,'Натереть тыкву и яблоки на терке. Взбить яйца с сахаром. Добавить немного соли. Перемешать яйца с яблоками и тыквой. Добавить муку (чем меньше будет муки, тем нежнее и сочнее получатся оладьи). Все тщательно перемешать. Разогреть на сковороде растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2378,'Выкладывать яблочно-тыквенную массу при помощи ложки, не слишком перегружая сковороду. Жарить до румяности на небольшом огне (примерно 15 минут), переворачивая аккуратно их деревянной лопаткой. Подавать домашние тыквенные оладьи с яблоками к столу со сметаной или с медом – в зависимости от собственного вкуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2379,'Измельчить бекон кубиками и обжарить до прозрачного цвета, крупно натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2379,'В миксере смешать подсоленную муку с маслом и разрыхлителем, поперчить, влить молоко, еще раз перемешать в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2379,'Положить в тесто бекон с сыром, если надо, то подсыпать муки и еще раз перемешать все вместе, чтобы можно было раскатать в плат толщиной в сантиметр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2379,'Нарезать произвольно, например, ромбами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2379,'Печенье на молоке с беконом и сыром выпекать в прогретой до 200 градусов духовке около 25 минут (пока верх не станет золотистого цвета).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2380,'Тщательно вымыть молодые клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2380,'Отварить в слегка подсоленной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2380,'Мелко порубить зелень с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2380,'Добавить перец, масло и зелень, аккуратно перемешать, подать к столу в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2381,'Дать клубнике немного оттаять, поместить ее в блендер, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2381,'Переложить в 3-х литровую банку, влить водку, накрыть крышкой, убрать на 10 дней в темное место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2381,'Сварить сироп, охладить, влить в настой, тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2381,'Разлить клубничный ликер на водке с сиропом в подходящие бутылки, поставить дальше настаиваться в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Дать постоять четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Для начинки перемешать творог с порубленной зеленью и небольшим количеством сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Колобок теста разделить на 12 частей, раскатать каждый в лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Положить начинку, тщательно защипать края, чуть прокатать скалкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2382,'Обжарить аварские лепешки «Чуду» с творогом и зеленью с обеих сторон без масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2383,'Залить молоком сушки примерно на четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2383,'Смешать фарш с луком, подсолить его и поперчить, натереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2383,'Для выпекания фаршированных сушек под сыром в духовке разогреть предварительно духовку до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2383,'Заполнить фаршем отверстия в сушках, смазать майонезом, присыпать сыром, выпекать около 45 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2384,'В миску всыпать сахар и влить теплую воду. Перемешивать до тех пор, пока сахар полностью не растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2384,'Выжать сок из апельсинов (у меня получилось 240 мл).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2384,'В кувшин влить апельсиновый сок, добавить лимонный сок, влить сироп и газированную воду, хорошо перемешать. Поставить в холодильник на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2385,'Достать заранее масло, когда станет мягким – взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2385,'Добавить мягкий сыр, взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2385,'Всыпать сахарную пудру, еще раз взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2385,'Добавить в Сливочный крем-чиз с сахарной пудрой сливки, взбить в последний раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2386,'Начать приготовление с кляра, смешать с базиликом солью и перцем яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2386,'Добавить горчицу с майонезом, еще раз все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2386,'Всыпать муку, перемешать до исчезновения всех комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2386,'Разогреть сковороду, налить немного масла, прогреть его.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2386,'Палочки обмакнуть в кляр и обжарить до образования корочки соломенного цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2387,'Разболтать вилкой яйца, влить сметану, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2387,'Всыпать слегка подсоленную муку с разрыхлителем, вымесить тесто, похожее на тесто для оладий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2387,'Подготовленную форму промазать маслом, наполнить тестом, уложить фрикадельки, присыпать сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2387,'Выпекать пирог на сметане с фрикадельками около 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'Залить желатин водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'Почистить апельсин, выжать из него сок, нагреть его почти до кипения, снять с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'В горячем соке распустить желатин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'На водяной бане расплавить шоколад, объединить его с соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'Разделить желтки и белки, белки (6 шт.) взбить до пышной массы, желтки (3 шт.) взбить вместе с шоколадной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'Перемешать обе смеси.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2388,'Разложить шоколадно-апельсиновый мусс с желатином по формочкам, убрать на 2-3 часа в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2389,'Перемешать в миске все сухие ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2389,'Вбить яйца, добавить размягченное масло, яблочный уксус, молоко, оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2389,'Тщательно все перемешать, используя миксер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2389,'Маслом смазать круглую форму, уложить на дно кружок пергамента, выпекать шоколадный бисквит на молоке с какао примерно час при температуре 175 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2389,'Выпечку остудить на решетке, прикрыть пленкой, дать постоять перед подачей к столу около 2 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Залить теплым молоком столовую ложку сахара с дрожжами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Примерно на 10 минут поместить в теплое место, добавить оставшиеся ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Вымесить тесто, накрыть тканью, дать полежать час для дозревания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Приготовить из натертой цедры лимона с апельсином и сахаром начинку для пирога.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Раскатать тесто в прямоугольник (примерные размеры 30х50 см).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Смешать смесь из цедры с маслом, уложить ровным слоем на поверхность теста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Порезать на прямоугольники (5х10 см), поместить их в форму, выстланную бумагой для выпечки, дать постоять около получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2390,'Пирог «Гармошка» с апельсиново-лимонной начинкой выпекать около 40 минут в духовке, разогретой до 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2391,'Из горчицы (2 ст.л.), масла оливкового, специй, лимонного сока приготовить маринад и со всех сторон замариновать семгу. Оставить в прохладном месте на полчаса. Нарезать лук-порей тоненькими кольцами, мелко порубить свежую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2391,'Перемешать в салатнице лук-порей с горчицей, сливками и половиной зелени. Смазать огнеупорное блюдо маслом оливковым, выложить из салатницы смесь. Выложить поверх маринованную семгу, на нее – пару долек лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Нарезать батон, обжарить ломтики с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2391,'Поставить на 10-15 минут в разогретую до 220 градусов духовку. За пару минут до готовности убрать дольки лимона, посыпать сыром и оставшейся зеленью. Подавать маринованную семгу под сливочным соусом, в котором она жарилась.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2392,'Отварить картофель и яйца. Мелко нарезать ингредиенты.','https://vkuso.ru/data/cache/data/cc/9fb376aadfa02cc_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2392,'Желток вынуть из отваренных яиц и размять вилкой в отдельной тарелке, добавить горчицу, майонез, сметану и тщательно перемешать.','https://vkuso.ru/data/cache/data/4f/aead0ce312e2d4f_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2392,'Получившуюся массу смешать с нарезанными инредиентами для окрошки, посолить и залить минеральной водой. Перед употреблением оладить, приятного аппетита!','https://vkuso.ru/data/cache/data/ee/3c6d2c3d47463ee_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'Сыр натираем на крупной терке.','https://vkuso.ru/data/cache/data/86/c5c5ef368ce5086_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'Помидор мелко нарезаем.','https://vkuso.ru/data/cache/data/ec/3a8e9e65b2733ec_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'Смешиваем сыр, помидор и сметану.','https://vkuso.ru/data/cache/data/50/c756eb388369a50_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'Лаваш нарезаем на равные части.','https://vkuso.ru/data/cache/data/8b/ed16244f29a438b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'На уголок лаваша укладываем 1 ст.л. начинки и заворачиваем в конвертик.','https://vkuso.ru/data/cache/data/41/c8dbca244782041_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'У вас должны получится вот такие конвертики.','https://vkuso.ru/data/cache/data/ce/9202341566eafce_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'На сковороде разогреваем масло растительное, и затем обжариваем конвертики с начинкой. Обжариваем с 2-х сторон до корочки.','https://vkuso.ru/data/cache/data/40/b4785b635777e40_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2393,'Перекладываем на тарелку. Приятного аппетита','https://vkuso.ru/data/cache/data/8f/5efeff09307228f_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2394,'Перемешать все сухие ингредиенты в миске.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2394,'Влить кефир, вбить яйцо, тщательно вымесить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2394,'Растопить масло, вылить его вместе с кипятком в тесто, еще раз размешать, чтобы блины получились без комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2394,'Хорошо разогреть сковороду с толстым (предпочтительнее) дном, выпекать блины с двух сторон, если планируется еще и начинка, то с одной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2395,'Для приготовления закуски нам потребуются два молодых кабачка, т.к. кабачки молодые очищать их от кожуры не надо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2395,'Теперь приступим к приготовлению заправки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2395,'Добавляем измельчённый чеснок, соевый соус, мёд, лимонный сок, черный перец по вкусу и растительное масло хорошо перемешиваем.','https://vkuso.ru/data/cache/data/4e/719d7c32362144e_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2395,'Соединяем кабачки и заправку, хорошо перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2395,'Закуска готова! Приятного аппетита!','https://vkuso.ru/data/cache/data/27/07abadc25aa8927_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2396,'Влить в кастрюлю воду, добавить маргарин или масло, перец, орех мускатный, соль. Довести до кипения. После закипания сразу же высыпать всю муку, хорошо вымешать до образования однородной массы. Тесто должно получиться гладким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2396,'Снять с огня, дать постоять пару минут и вмешать яйца по одному. Снова перемешать до однородной массы. Взять примерно 120 г сыра, нарезать небольшими кубиками и аккуратно вмешать в тесто. Дать постоять примерно час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2396,'Застелить форму бумагой и смазать маргарином или маслом. Сформировать из теста что-то вроде булочек и выложить в форму. В середине сделать дырку среднего размера. Оставшийся сыр также нарезать кубиками и выложить поверх теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2396,'Разогреть духовку до 200 градусов и поставить тесто. Выпекать примерно 40 минут. Когда блюдо будет готово, оно будет светлого желто-золотистого цвета (если пережарить до коричневого оттенка, будет суховато). Кубики сыра, выложенные сверху, должны расплавиться, но при этом не зажариться. Домашние гужеры с сыром достать из духовки, дать немного остыть и подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Подготавливаем куриные желудки, их нужно очень хорошо промыть. Если есть пленка, то избавиться от неё. Куриные желудочки можно нарезать на несколько частей.','https://vkuso.ru/data/cache/data/c6/c5a6d83b449b1c6_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Растопить сливочное масло или маргарин на тихом огне, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Затем по вкусу солим, перчим и добавляем приправу для курицы. Перемешиваем, убираем в сторону.','https://vkuso.ru/data/cache/data/cc/160d1fd033cadcc_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Заранее надо разморозить замороженные овощи.','https://vkuso.ru/data/cache/data/82/733f4292f32db82_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Картофель нарезаем дольками.','https://vkuso.ru/data/cache/data/6d/f58227b9adeff6d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Затем, по вкусу солим, перчим и добавляем паприку, перемешиваем.','https://vkuso.ru/data/cache/data/a5/ee00c17bf7cb2a5_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Чеснок надо почистить. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2397,'Закрываем фольгой и отправляем в духовку до готовности. Время приготовления зависит от вашей духовки. У меня это заняло 1 час и 30 минут.','https://vkuso.ru/data/cache/data/24/7c7ea23e5349e24_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Порубить маргарин с просеянной мукой, влить сметану, добавить желтки, перемешать ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Переложить массу на стол, окончательно вымесить до образования однородного теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Разделить его на 24 кусочка, положить на пару часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Из белков и сахарной пудры (всыпать по частям) взбить крепкую пену, орехи подробить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Раскатать каждый кусочек, положить по центру по столовой ложке крема из белка и одной чайной ложке орехов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2398,'Соединить края, защипать «гребешком», поместить плюшки с орехово-белковым кремом примерно на полчаса в духовку с температурой около 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2399,'Перемешать сахар с мягким маслом, вбить яйцо, всыпать необходимую порцию муки, перемешать, соду добавить в тесто вместе с молоком, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2399,'В последнюю очередь всыпать какао и влить кипяток, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2399,'Выпекать Печенье Вупи Пай с творожной начинкой на пергаменте 5-6 минут при 160 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2399,'Готовое печенье собрать попарно, прослоив кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2399,'Для его приготовления перемешать до однородности сахарную пудру с сыром и взбитым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Подготовить и обжарить свежие грибы (нарезать кубиками) с маслом, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Курицу порезать тоже кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Сыр крупно натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Чеснок раздавить прессом, желательно с мелкими отверстиями, либо натереть до состояния кашицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Массу для тарталеток с копченой курицей и шампиньонами перемешать с майонезом, попробовать на соль, если надо, то присолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Заполнить тарталетки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2400,'Выложить их на плоское блюдо, оформить веточками укропа, или петрушки, или присыпать измельченной зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Нашинковать и обжарить половину лука до прозрачности на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Положить мясо, обжарить все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Крупно натереть морковь, перец порезать соломкой, помидор – на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Высыпать все к мясу, добавить чеснок и специи с солью, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Раскатать из теста пласт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Нанести на поверхность тонким слоем начинку из тонких полуколечек лука.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Завернуть в трубочку, нарезать на кусочки длиной примерно до 5 см.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'В смесь овощей и мяса влить немного воды, разровнять содержимое сковороды.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Уложить сверху все кусочки рулетика.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2401,'Готовить ханум на мясной подушке с овощами, закрыв крышкой, примерно треть часа, сильный огонь не делать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Взбить сырое куриное яйцо с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Отдельно нарезать кабачок, смочить пластинки в яичной смеси, запанировать в пшеничной муке и обжарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Из несвежего батона нарезать ломтики, приготовить обычные гренки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Выложить на них обжаренные кабачки, посыпать рубленым чесноком, украсить зеленью петрушки и укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Сверху по желанию можно положить мягкий сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2402,'Остатки яично-молочной смеси использовать так: вылить немного жидкости на сковороду и вдавить в нее готовый бутерброд хлебной стороной вверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Всыпать тертый сыр твердого сорта, добавить красный молотый перец и горчицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Отдельно взбить сырые желтки, вылить на сковороду и продолжать мешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Массу прогреть, до кипения не доводить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2403,'Намазать горячую смесь на гренки и поставить на несколько минут в духовой шкаф.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2404,'Вбить яйца в молоко, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2404,'Смесь хорошо взболтать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2404,'Батон нарезать ломтиками, обмакнуть в жидкую массу и обжарить с двух сторон на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2405,'Измельчить ветчину, колбаски и сосиски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2405,'Заправить смесь томатной пастой и острым красным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2405,'Пшеничный хлеб нарезать ломтиками, обжарить их на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2405,'Намазать мясной массой, посыпать тертым голландским сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2405,'Запечь в духовом шкафу до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2406,'Батон белого хлеба разрезать вдоль на восемь полосок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2406,'В небольшой емкости взбить вместе сахарную пудру и молоко, добавить мускатный орех, коричневый сахар, молотую корицу, сырые куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2406,'Каждую полоску батона обмакнуть в полученную смесь и обжарить на сковороде, на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Молоко немного подогреем и разводим в нем сахар, соль и быстродействующие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Высыпаем в миску с молоком просеянную муку и немного перемешаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Сливочное масло растопим и добавим его в тесто. Хорошо замешиваем тесто примерно минут 5. Я это дрожжевое тесто замешивала миксером со специальной насадкой для густого теста. Накрываем тесто полотенцем или пищевой пленкой и убираем в теплое место для расстойки теста (я расстаивала тесто примерно 1 час).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Час прошел и тесто хорошо поднялось. Обминаем тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Выложим дрожжевое тесто в форму смазанную растительным маслом. Накрываем форму с тестом полотенцем и даем ему опять подняться примерно 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Наше дрожжевое тесто окончательно подошло. Делаем сверху на тесте три небольших надреза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2407,'Готовим наш домашний хлеб в духовке примерно 30-35 минут. Я дрожжевое тесто ставлю в холодную духовку и включаю ее на 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Нежное мясо с легкой фруктовой кислинкой. Соус сделает сочным даже суховатое филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Курицу промыть, вытереть насухо бумажными полотенцами, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Растопить в сковороде сливочное масло, обжарить на нем филе по четыре минуты с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Очистить чеснок, раздавить плоской стороной ножа, выложить на дно формы для запекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'На чеснок положить по кусочку куриного мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'В сковороду, где обжаривалась курица, влить молоко, добавить нарезанную полосками цедру лимона и немного шафрана в порошке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Молочный соус довести до кипения, залить им мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2408,'Печь в течение получаса, курицу поливать смесью постоянно, температура приготовления – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Грубоватое на вид, но очень вкусное и полезное, ароматное печенье к завтраку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Муку и сливочное масло комнатной температуры растереть в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Твердый сыр натереть на мелкой терке и добавить в смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Ввести сырые куриные желтки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Отдельно порубить свежий шалфей, замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Можно добавить немного воды, чтобы масса стала однородной и пластичной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Сформовать шарики, выложить их на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2409,'Поставить в духовой шкаф, выпечь до золотистой корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Творог растереть с яйцами и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Всыпать муку, замесить тесто, мягкое и однородное.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Разделить массу на четыре равные части, раскатать в колбаски, толщиной до трех с половиной сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Нарезать на кусочки среднего размера, скатать их в шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Разогреть растительное масло в кастрюльке, на среднем огне. Его должно быть много.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Выложить кусочки теста порциями, они должны свободно плавать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Обжарить пончики до золотисто-коричневой корочки со всех сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Выложить готовые изделия на салфетку, дать впитаться лишнему жиру.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2410,'Посыпать сахарной пудрой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Отрезать от хлебного каравая верхнюю часть, вынуть мякиш руками, стенки должны остаться целыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Промазать их сметаной, корзинку поставить в духовой шкаф на 10 минут для подрумянивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'На растительном масле обжарить несколько зубчиков очищенного чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Горячий каравай-корзинку вынуть из духовки, выложить на дно репчатый лук, нарезанный соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Затем – слой хорошо промытых шампиньонов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Начинку посолить и поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Полить все растительным маслом с запахом чеснока или сметаной и закрыть корзинку крышкой из срезанной части хлеба.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2411,'Поставить каравай в духовой шкаф на 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'В кастрюлю средней величины выложить свежий имбирь, корку лимона, нарезанную широкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Залить продукты водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Довести смесь до кипения на сильном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Варить при средней температуре, под крышкой, в течение 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Всыпать сахарный песок, перемешать, варить еще 15 минут до упаривания жидкости на четверть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Массу процедить, корку и имбирь выбросить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'Остуженный сироп перелить в стеклянную банку, хранить в течение недели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2412,'При необходимости перемешать четверть стакана эля со стаканом холодной газировки, добавить сироп и лед.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2413,'Промыть ягоды голубики. Растопить сливочное масло и дать немного остыть. В большой миске смешать муку, миндаль молотый и сахарную пудру. Добавить соль. Влить остывшее масло в полученную смесь. Перемешать смесь основательно, до получения жирноватой миндально-мучной крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2413,'При помощи миксера взбить в отдельной миске яичный белок в пену. Добавить в тесто и перемешать. Тесто получиться должно довольно жидким. Добавить в тесто голубику. Подготовить формочки. Можно использовать как круглые, так и различных других форм. Формочки смазать маслом и присыпать мукой, чтобы изделия не прилипали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2413,'Наполнить формочки полученной массой, до края не доходить несколько миллиметров, поскольку тесто будет подниматься при выпечке. Отправить в духовку, нагретую до 200 градусов. Убавить через 10 минут температуру до 180 градусов, и выпекать еще примерно 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2413,'Как только корочка станет равномерно румяной, финансье с миндалем и голубикой готово! Аккуратно достать изделия из формочек (можно помогать ножом или лопаткой), посыпать сахарной пудрой и оставить на несколько минут немного остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Для приготовления дрожжевого теста перемешать в миске сахарный песок, сухие дрожжи и подогретое молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Смесь накрыть тарелкой, оставить на 15 минут до появления пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Отдельно перемешать пшеничную муку с солью и мягким сливочным маслом, должна получиться крошка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Сырые куриные яйца взболтать с помощью вилки, вылить в крошку, добавить подошедшую опару.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Замесить тесто, скатать его в шар.','https:https://st.vkuso.ru/data/cache/thumb/01/067367204bba301_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Выложить массу в емкость, накрыть пленкой, толстой тканью и поставить в тепло на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Застелить противень бумагой для выпечки, смазать её небольшим количеством сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Подошедшее тесто обмять, выложить на бумагу, растянуть по поверхности руками.','https:https://st.vkuso.ru/data/cache/thumb/43/9d7d61cb12cf343_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Накрыть лепешку полотенцем, дать постоять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'В сотейнике или небольшой кастрюле с толстыми стенками разогреть сливочное масло, добавить сахар, мёд и молоко.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Смесь прогреть на тихом огне до растворения сахара.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Огонь выключить, всыпать лепестки миндаля.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Тесто на противне наколоть в нескольких местах вилкой, намазать сверху карамельной смесью, распределить равномерно.','https:https://st.vkuso.ru/data/cache/thumb/6a/66833a7a222236a_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Печь корж в течение 10 – 15 минут до золотистой корочки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Достать, накрыть полотенцем до остывания.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Для приготовления крема положить в молоко надрезанный стручок ванили, поставить прогреваться на средний огонь. Кипятить не надо.','https:https://st.vkuso.ru/data/cache/thumb/17/71f9450130ef917_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Сырые желтки растереть с сахарным песком до побеления.','https:https://st.vkuso.ru/data/cache/thumb/1e/7795039fb1c831e_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Всыпать кукурузный крахмал, перемешать.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Влить прогретое молоко, ваниль убрать.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Смесь помешивать венчиком.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Вылить массу в кастрюлю, варить на тихом огне до загустения.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Когда крем начнет густеть – мешать интенсивнее, чтобы крем получился гладким.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Убрать с плиты, охладить при комнатной температуре, а затем в холодильнике.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Остывший корж разделить на две части вдоль по длинной стороне.','https:https://st.vkuso.ru/data/cache/thumb/61/6bf6eea32d68761_434x295.jpg',24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Каждую часть разрезать вдоль длинным ножом.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Верхнюю часть с заливкой нарезать на квадраты.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Взбить сливки в плотную пену и соединить с заварным кремом движениями сверху вниз.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Полученной массой намазать нижние части коржа.','https:https://st.vkuso.ru/data/cache/thumb/ad/8ee1e7ed470a3ad_434x295.jpg',28);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Сверху разложить квадратики с миндалем, дать выпечке постоять в течение часа или двух в прохладном месте.',NULL,29);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2414,'Разрезать на пирожные вместе с нижним слоем.',NULL,30);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Морковь нарезать на кольца или полукольца, толщина – до восьми миллиметров.','https:https://st.vkuso.ru/data/cache/thumb/b6/235ded6f4c4ffb6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Мелко порубить зубчики чеснока и очищенный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Обжарить на оливковом масле в кастрюле половину луковой нарезки и чеснок до румяного цвета.','https:https://st.vkuso.ru/data/cache/thumb/05/d1711c9810ad405_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Залить овощи заранее сваренным куриным бульоном, положить морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Оставшийся чеснок выдавить или порубить, перемешать с оставшимся луком, молотым мускатным орехом и острым перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Добавить в готовый мясной фарш, еще раз хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Руки смочить в холодной воде, сформовать шарики диаметром в один сантиметр.','https:https://st.vkuso.ru/data/cache/thumb/bf/f4bd45e7b9d0bbf_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Когда бульон закипит – огонь убавить, выложить тефтели так, чтобы они не слиплись.','https:https://st.vkuso.ru/data/cache/thumb/2d/afc70547569e82d_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Снимать пенку ложкой, как только она начнет появляться на поверхности супа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'При готовности моркови всыпать зеленый горошек.','https:https://st.vkuso.ru/data/cache/thumb/f5/4dd96c1cec928f5_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Варить две минуты, огонь выключить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Дать постоять блюду 20 минут под крышкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2415,'Подать с грубыми кусками батона или со свежим хлебом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Для приготовления теста перемешать муку с солью и карри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Влить воду, добавить масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Замесить тесто, накрыть массу полотенцем и оставить на полчаса для набухания клейковины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Для начинки отварить крупный картофель и приготовить пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Добавить сахарный песок, соль, кокосовую стружку, кунжут, имбирь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Все ингредиенты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Стол посыпать мукой, тесто раскатать в прямоугольник 30 см на 50 см.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Выложить картофельную начинку, скрутить лепешку в рулет.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Разрезать его на кусочки толщиной в один сантиметр',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Обжарить рулетики на подсолнечном масле, на среднем огне, с двух сторон, до золотистой корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2416,'Другой вариант – запечь в духовке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2417,'Помидоры и сыр «Моцарелла» нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2417,'Хлеб ломтиками намазать соусом «Песто».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2417,'Выложить на один кусочек помидоры черри, сыр, листочки базилика, соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2417,'Накрыть вторым ломтиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2417,'Готовый сэндвич обжарить на сковороде или на гриле, третий вариант – запечь в духовке в течение семи минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'Нарезать клубнику на крупные кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'В чашу блендера вбить 2 яйца и добавить сахар, пробить в течении минуты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'Вылить смесь в глубокую миску.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'Добавить разрыхлитель и оставшуюся муку, перемешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'Форму для выпечки смазать растительным маслом и дно застелить бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2418,'Готовому кексу дайте остыть и затем выньте из формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Крупу залить водой на ночь, утром жидкость слить, продукт промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Репчатый лук покрошить и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Нарезать морковь кубиками, свежие шампиньоны – пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Все ингредиенты перемешать с перловой крупой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Выложить в горшочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Всыпать в каждый соль, влить растительное масло, посыпать сушеной зеленью петрушки или укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Влить горячую воду, она должна покрывать кашу на два сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2419,'Поставить на час или полтора в духовку, температура приготовления – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Помидоры нарезать кусочками небольшого размера, сладкий болгарский перец – кубиками, репчатый лук – полукольцами. Натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Перловую крупу промыть и смешать с овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Добавить соль, сахарный песок, растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Довести ингредиенты в кастрюле до кипения, тушить на тихом огне два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Время от времени массу помешивать, чтобы продукты не пригорели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2420,'Выложить в стерильные банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2421,'Баклажаны очистить, нарезать небольшими кусочками (кубиками или дольками), оставить на 15 минут в подсоленной воде – благодаря этому уйдет излишек горечи. Помидор обдать кипятком, снять с него кожицу и разрезать на четыре части. Чеснок очистить и выложить вместе с помидорными дольками в «корзинку» из фольги. Разогреть духовку до 200 градусов, поставить запекаться на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2421,'Мелко нарезать лук, обжарить до золотистого цвета на масле оливковом. Сковороду для этого взять глубокую. Достать баклажаны из подсоленной воды, немного отжать и добавить к обжариваемому луку. Влить туда же стакан бульона. Посыпать приправой из трав, довести до кипения, убавить огонь и оставить тушиться на 10 минут под закрытой крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2421,'Из духовки достать помидоры с чесноком, снять с огня баклажаны. Все овощи перемешать в блендере, присыпав острым молотым красным перцем. Добавить к полученному овощному пюре мягкий сыр и подогретые сливки. Посолить по собственному вкусу. Перемешать в блендере снова, до получения однородной массы. Крем-суп «Ренуар» из баклажанов не требует дополнительных заправок при подаче к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'На дне глубокой кастрюли или казана прогреть растительное масло с рубленым луком-шалотом и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Все вместе жарить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Говядину нарезать соломкой, жарить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Крупу промыть, всыпать в казан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Влить немного белого вина, тушить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Добавить грибы, нарезанные кубиками, тимьян.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Влить мясной бульон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Варить один час, подливать остатки бульона, перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2422,'Всыпать тертый сыр «Пармезан» за минуту до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'Крупу замочить в очень горячей воде на сорок или сорок пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'В чашу кастрюли влить постное масло, обжарить репчатый лук, добавить морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'Перловку промыть, выложить на обжарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'Влить холодную воду, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'Потомить блюдо сорок минут или чуть больше, режим «Плов».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2423,'Оставить на двадцать пять минут в закрытой посуде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Обжарить полукольца лука в программе «Жарка» или «Выпечка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Всыпать бруски моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Свинину вымыть, обсушить, нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Добавить в обжарку тогда, когда овощи будут готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Все вместе жарить до появления корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Крупу хорошо промыть горячей водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Добавить в обжарку с мясом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Долить горячую воду в соотношении «один к двум».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2424,'Выставить режим «Плов» на час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Крупу на ночь замочить в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Обжарить в чаше мультиварки нарезанные лук и морковь с растительным или сливочным маслом. Режим «Выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Выложить сверху крупу, ошпаренную кипящей водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Кашу посолить, посыпать сушеными ароматными травами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Добавить тушенку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2425,'Выставить режим «Гречка» на восемьдесят минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2426,'Грибы нарезать тонкими пластинками, репчатый лук – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2426,'Жарить в мультиварке, программа «Выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2426,'Перловку замочить в холодной воде, отцедить, выложить поверх овощей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2426,'Выставить режим «Рис».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2427,'Перловую крупу промыть холодной водой несколько раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2427,'Залить еще одной порцией жидкости на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2427,'Промыть горячей водой, пересыпать в чашу мультиварки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2427,'Сверху вылить смесь воды с молоком, соль и сахар – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2427,'Выставить режим «Молочная каша» на час или чуть больше.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Курицу нарезать крупными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Выложить в чашу мультиварки, посолить, полить растительным рафинированным маслом, выставить режим «Выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Репчатый лук нарезать кольцами или полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Морковь нашинковать брусками или натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Овощи добавить к готовой курице, подрумянить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Всыпать промытую перловку, приправы для приготовления плова.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Залить кашу с курицей горячей кипяченой водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2428,'Выставить режим «Плов» на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Перловку с вечера залить обычной водой, утром жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'На любом масле обжарить кусочки тыквы и кубики лука до размягчения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Добавить нарезанную брусками морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Все вместе прогревать восемь или девять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'За две минуты до окончания жарки выложить в емкость перловку, отцеженную и промытую.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Залить теплой водой, она должна покрыть продукты на два или два с половиной сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Добавить лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'Выставить режим «Плов».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2429,'За пять или шесть минут до окончания приготовления всыпать зиру и соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'В миске взбиваем 5 куриных яиц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'В другую миску пересыпаем муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'Подготавливаем куриные бёдра, отделяем кожу. По желанию отрезаем жилки, сухожилия и тд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'Куриное бедро можно нарезать на несколько частей, затем отбиваем куриное бедро.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'Все кусочки бедра, которое вы отбили, перекладываем в миску, солим, перчим и добавляем приправу для курицы. Все очень хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'Затем добавляем соевый соус и ещё раз перемешиваем. Оставляем на 30 минут для маринования.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2430,'Спустя 30 минут отпускаем кусочки бедра во взбитое куриное яйцо. Затем в муку, и перекладываем на разогретую сковороду, обжариваем около 5-7 минут до золотистой корочки. Подаем к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Перловку залить холодной водой на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Баклажан, томаты, сладкий болгарский перец промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Продукты нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Баклажан для удаления горечи засыпать солью, оставить на двенадцать или пятнадцать минут, затем промыть холодной водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Выставить в мультиварке режим «Жарка», приготовить овощи вместе с рубленым чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Поверх всыпать крупу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Влить горячую воду, всыпать соль, компоненты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2431,'Выставить режим «Плов» на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'Морковь, репчатый лук и чеснок измельчить, спассеровать на растительном или сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'При готовности добавить курицу, нарезанную кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'Все вместе готовить до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'Промыть перловку, выложить в обжарку, посолить, посыпать приправами для плова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'Влить воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2432,'Выставить режим «Рис» или «Крупа».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Перемешать сырые куриные яйца с теплой водой, топленым маслом, просеянной мукой и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Замесить тесто, оно должно быть эластичным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Массу поделить на три шарика, поставить в тепло на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Раскатать колобки в лепешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Прослоить сливочным маслом, уложить друг на друга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Скатать заготовку в рулет, нарезать кругляшами, раскатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'В центр поместить по кусочку масла и начинку из тертой тыквы и рубленого лука, соль и молотый перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2433,'Сформовать треугольники, время выпекания – тридцать пять минут. Температура приготовления – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Тыкву очистить и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Измельчить репчатый лук, спассеровать на растительном масле до прозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Добавить тыкву, нарезанную кубиками, перец, соль и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Все вместе обжарить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Сформовать из теста прямоугольники, выложить начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Сформовать заготовки самсы, смазать смесью яйца со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2434,'Выложить на противень, поместить в духовку на двадцать пять минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2435,'Измельчить сыр в блендере или натереть на мелкой терке. Лучше всего использовать в данном рецепте сыр пармезан, но вкусно получится и с другим тертым сыром. Взбить белки при помощи миксера до устойчивой пены. Аккуратно смешать с сыром белки, поперчить по собственному вкусу. Перемешать белки и сыр необходимо тщательно, чтобы ингредиенты были распределены равномерно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2435,'Сформировать небольшие шарики из полученной массы и обвалять их в панировочных сухарях, не слишком сжимая при этом тесто. Если шарики получатся слишком крупными, они недостаточно хорошо прожарятся, и будут не такими вкусными. Шарики обжарить во фритюре до золотистого цвета. К столу сырный делисьез подавать горячими. Перед подачей на стол можно украсить зеленью. Прекрасно сочетаются с вином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Тыкву очистить, мякоть нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Перемешать с бараньим жиром, кусочками говядины, лука и острого стручкового перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Начинку перемешать, посолить, подлить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Слоеное тесто разморозить, свернуть в рулет, разрезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Раскатать лепешки, сформовать треугольные пирожки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2436,'Выложить самсу на противень, смазать яйцом, печь в духовке в течение получаса при температуре 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2437,'Репчатый лук нарезать кубиками, обжарить на сливочном масле до прозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2437,'Очищенную тыкву натереть, перемешать с луком, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2437,'Приготовить лепешки из слоеного теста, сформовать пирожки с начинкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2437,'Печь при температуре 200 градусов, время - двадцать пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2438,'Тыкву, картофель и репчатый лук очистить и нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2438,'Начинку перемешать, посолить, добавить топленое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2438,'Раскатать слоеное тесто, вырезать лепешки, выложить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2438,'Печь в духовке на покрытом пергаментом противне. Температура приготовления – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2439,'Тыкву натереть, отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2439,'Порубить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2439,'Ингредиенты перемешать, добавить курдючный жир, нарезанный кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2439,'Заготовки из слоеного теста наполнить начинкой, края защипать, чтобы получились треугольники.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2439,'Печь в духовом шкафу двадцать пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2440,'Натереть тыкву, измельчить лук, добавить соль, молотый перец и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2440,'Тонко раскатать слоеное тесто, нарезать прямоугольники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2440,'Выложить начинку, края защипать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2440,'Печь в духовке при температуре 200 градусов, время – двадцать пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2441,'Пшеничную муку просеять, перемешать с теплой водой, в массе не должно быть комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2441,'Добавить теплое растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2441,'Массу посолить, замесить полужидкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2441,'Добавить варенье.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2441,'Выставить режим «Выпечка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Апельсины и лимоны хорошо вымыть.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Из второго апельсина выжимаем сок.','https://vkuso.ru/data/cache/data/d8/e2b1b13545058d8_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Лимон также нарезаем кружочками.','https://vkuso.ru/data/cache/data/84/61059424b8c6284_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Переливаем апельсиновый сок в кувшин, добавляем кружочки апельсина, лимона, мяту и сахар по вкусу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Заливаем газированной водой, перемешиваем. Даем настояться 5-10 минут.','https://vkuso.ru/data/cache/data/d3/baaf776702bfbd3_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2442,'Лимонад готов!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Картофель нарезаем кусочками.','https://vkuso.ru/data/cache/data/2d/cec6a66d59fd32d_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Солим, перчим и посыпаем приправой для мяса.','https://vkuso.ru/data/cache/data/75/b042701253a0475_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Лук нарезаем соломкой.','https://vkuso.ru/data/cache/data/da/ca5ae0056f86bda_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Грудинку нарезаем средними по толщине кусочками.','https://vkuso.ru/data/cache/data/8f/89bbd75cc5ec38f_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Перекладываем в какую-то ёмкость и затем солим, перчим и посыпаем приправой для мяса.','https://vkuso.ru/data/cache/data/c3/300120ce6ae3dc3_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Затем добавляем сметану, перемешиваем. Оставляем на 30 минут.','https://vkuso.ru/data/cache/data/dc/2fe49bd28e652dc_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Берем гриль или противень и укладываем сначала картофель в 2 слоя.','https://vkuso.ru/data/cache/data/ae/c9b857668fb02ae_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Потом грудинку, затем лук','https://vkuso.ru/data/cache/data/d3/e8c674b44aef9d3_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2443,'Закрывай фольгой, или кулинарным рукавом для запекания. Отправляем в духовку до готовности. У меня это блюдо приготовилось за 1 час и 30 минут. Для придания корочки, за 30 минут до приготовления снимаем фольгу, или кулинарный рукав и при помощи кисточки смазываем грудинку.','https://vkuso.ru/data/cache/data/81/09da25b6eeb2081_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2444,'В миску разбить яйцо, перемешав его с солью, молокой, сахаром и растительным маслом. После этого всыпать дрожжи. Не переставая мешать постепенно всыпать муку. При желании можно процесс введения муки разделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2444,'Готовое тесто должно легко отставать от рук. Ничего страшного если осталось немного муки.  В это время нужно разогреть духовку. Когда тесто готово духовку нужно выключить и поставить туда тесто и оставить там на полчаса. После этого можно достать универсальное тесто и печь пироги и пирожки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2445,'Сначала готовим маринад. В соевый соус добавляем чайную ложку меда, паприку, перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2445,'Заливаем курицу маринадом и оставляем на 40-60 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2445,'После этого сливаем маринад в сковороду, добавляем ещё три ложки меда и апельсиновый сок (100 мл), помешиваем и доводим до кипения (должна получиться однородная масса).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2445,'В соус кладём ножки, обмакиваем со всех сторон и ставим в духовку 180-200°С на 45-60 минут. Через 45 минут переворачиваем ножки ещё раз, обмакнув в маринад, и ставим под гриль на 10 минут. Достаем и кушаем!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2446,'Кефир перемешать с сахарным песком, взбить венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2446,'Всыпать муку, влить растопленное сливочное масло, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2446,'Всыпать немного соли и пищевую соду. Масса должна напоминать сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2446,'Вылить тесто в чашу мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2446,'Готовый пирог разрезать вдоль, промазать любимым вареньем с кисло-сладким вкусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Приготовить тесто из сливочного масла, разрыхлителя, яйца, дополнительного куриного желтка, пшеничной муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Масса должна получиться гладкой и однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Раскатать две лепешки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Смазать маслом чашу мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Выложить одну лепешку, выложить начинку – малиновое варенье, накрыть второй лепешкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Время выпекания – сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2447,'Пирог охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2448,'Яйца взбить миксером или блендером с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2448,'Всыпать муку, ввести соду, погашенную уксусом, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2448,'Чашу мультиварки смазать маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2448,'Выложить тесто, оно должно быть однородным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2448,'Полить несладким вареньем, выставить режим «Выпечка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2449,'Взбить сырые яйца с сахаром в пышную пену вручную или при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2449,'Сливочное масло или столовый маргарин растереть добела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2449,'Оба продукта соединить, ввести муку, ванильный сахар, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2449,'Быстро замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2449,'Выложить в заранее смазанную чашу мультиварки, сверху выложить варенье с крахмалом, запечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Перетереть сахар с сырыми желтками, добавить мягкое сливочное масло, продукты перемешать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Всыпать лимонную цедру, просеянную муку, молотые грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Состав перемешать, побрызгать соком половины лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Смазать чашу мультиварки, выложить тесто, печь двадцать минут до полуготовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Крышку открыть, выложить начинку из клубничного варенья, сахарного песка, взбитых в пену яичных белков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Печь еще двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2450,'Остывший десерт нарезать ромбами или прямоугольниками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Натираем соленые огурцы на мелкой терке. Выложим натертые огурцы в ситечко чтобы из них сбежала лишняя жидкость и оставим постоять минут на 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Очищенные лук и морковь также натираем на мелкой терке. Обратите внимание если у вас лук ядреный то уменьшите его количество!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Смешиваем наши натертые продукты и обжарим их на сковороде с растительным маслом примерно минут 15 на среднем огне. Даем полностью остыть овощам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Теперь заправим начинку майонезом и перемешаем. При желание можете перебить эту овощную массу блендером, так у Вас получится начинка более однородная.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Далее в нашу овощную массу натираем сыр тоже на мелкой терке (можете взять вместо плавленого сырка обычный твердый сыр, это на Ваш вкус). Также добавим пропущенный через пресс чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Мелко нарезаем зелень и добавляем ее в миску к остальным продуктам. Солим и перчим по своему вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2451,'Перемешиваем и наша овощная начинка готова. Ее можно использовать как для бутербродов так и в качестве овощной начинки для пирогов или блинов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2452,'Капусту мелко шинкуем в миску. Немного посолим и помнем руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2452,'Нарезаем свежие огурец тонкими полосками. Зелень укропа и лук мелко шинкуем. Отправляем в миску к капусте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2452,'Варим яйца и разделим их на желтки и белки. Белки яиц мелко нарезаем произвольной формы и добавляем их в миску к остальным продуктам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2452,'Вареные куриные желтки выложим в тарелочку и разомнем их вилкой. Добавим к желткам майонез и столовую горчицу. Перемешаем нашу заправку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2452,'Теперь добавим заправку в миску к остальным продуктам и посолив по своему вкусу хорошо перемешаем наш салат из свежей капусты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'Мексиканскую смесь отвариваем по инструкции на упаковке, я овощи варила 7 минут в подсоленной воде. Выложим вареную смесь в дуршлаг и даем ее полностью остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'Картофель варим до готовности и остудив чистим его. Режем вареный картофель небольшим кубиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'Свежие огурцы, помидоры и полукопченую колбасу я также нарезаю мелким кубиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'Всю свежую зелень мелко шинкуем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'В миске подходящего размера смешиваем все подготовленные продукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2453,'Солим по своему вкусу и заправив майонезом перемешиваем наш салат из мексиканской смеси овощей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Варим куриный окорочок в подсоленной воде до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Репчатый лук чистим и нарезаем его небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Свежую морковь также почистим и натираем ее на мелкой терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Обжарим лук и морковь на растительном масле в сковороде до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Влить воду. Поставить кастрюлю в духовку на сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Другой вариант – плита.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Готовый куриный окорочок достаем из куриного бульона. Высыпаем в этот бульон промытую гречневую крупу и варим ее до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'С вареного куриного окорочка снимаем все мясо и мелко его нарезаем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Гречневая каша у нас сварилась. Добавляем в нее нарезанное куриное мясо, обжаренные лук с морковью и немного сливочного масла (я добавила примерно 70 грамм).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2454,'Перемешаем гречневую кашу и закрыв кастрюлю крышкой дадим ее настоятся минут 15-20.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2455,'Нарезать куриное филе на мелкие кусочки и нарубить ножом. Мелко нарезать лук и добавить к фаршу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2455,'Взбить 1 яйцо. Добавить половину яйца к фаршу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2455,'Разогреть сковороду на сильном огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2455,'Перевернуть котлеты, убавить огонь на минимальный, накрыть крышкой и готовить 5-6 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2456,'Взять готовое слоеное тесто и поставить на разморозку. Желательно при комнатной температуре. После этого тесто нужно раскатывать в виде прямоугольника и разрезать на полоски, ширина которых равна 3 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2456,'Сосиски освободить от упаковки и завернуть их в тесто. При этом нужно двигаться по диагонали. Сосиски, завернутые в тесто, смазать при помощи кисточки взбитым желтком и посыпать семенами кунжута. Выпекать сосиски в слоеном тесте необходимо в разогретой духовке до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Перемешать сахарный песок с медом, сырыми яйцами, сливочным маслом, корицей, пищевой содой, гвоздикой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Добавить немного муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Влить молоко и всыпать оставшуюся муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Чашу мультиварки смазать жиром, переложить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Сверху – любое варенье в виде кружков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2457,'Запечь. Охладить, подать пирог к столу холодным.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2458,'Яйца взбить с сахарным песком, всыпать соль и влить простоквашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2458,'Всыпать муку порциями вместе с пищевой содой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2458,'Тесто вымесить, добавить яблочное варенье.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2458,'Чашу мультиварки смазать маслом, посыпать панировочными сухарями, выложить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2458,'Время выпекания – от двадцати до двадцати пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Перемешать сахарный песок со сметаной и сырым яйцом, растереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Ввести размягченный маргарин, сахарную пудру и какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Ингредиенты хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Всыпать заранее просеянную муку, замесить шоколадное тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'В конце приготовления добавить соду и соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Выложить массу в мультиварку, выставить режим «Печь».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2459,'Корж разрезать, смазать вареньем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2460,'Мягкое сливочное масло растереть с пшеничной мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2460,'Влить молоко. Тесто должно быть плотным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2460,'Сливочный сыр натереть, перемешать с тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2460,'Массу выложить в смазанную чашу мультиварки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2460,'Выпечь до готовности, нарезать треугольниками, полить вареньем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2461,'Льняное семя немного прожарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2461,'Перемолоть продукт в кофемолке, добавить любые сухофрукты или вяленую клюкву.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2461,'Влить кипящую воду, она должна покрыть продукты, накрыть крышкой или блюдцем на пять или десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2461,'Полить натуральным медом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Сырые семена гречки измельчить в муку при помощи кофемолки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Так же поступить с семенами льна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Продукты соединить, посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Отдельно довести до кипения молоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Залить семена, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Дать блюду настояться четыре минуты под крышкой, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2462,'Кашу еще раз перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2463,'Льняную муку залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2463,'Оставить при комнатной температуре до набухания. Лучший вариант – оставить на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2463,'Масло взбить с солью, добавить в кашу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Отварить картофель в мундире, клубни остудить, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Часть мака пересыпаем в отдельную ёмкость, он нам понадобится для обсыпки.','https://vkuso.ru/data/cache/data/5b/3f6a3912dedc55b_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Другую часть пересыпаем в глубокую тарелку и заливаем почти горячей водой, чтобы мак набух. Убираем всё в сторону.','https://vkuso.ru/data/cache/data/d6/096e7ac52a116d6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Яблоки очищаем от кожицы и произвольно нарезаем.','https://vkuso.ru/data/cache/data/d3/dc0d11a2ffed9d3_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Далее перекладываем яблоки в ёмкость и при помощи погружного блендера превращаем в пюре. Пюре перекладываем на тарелку, убираем в строну.','https://vkuso.ru/data/cache/data/71/fb74dff9b34bb71_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Печенье превращаем в крошку.','https://vkuso.ru/data/cache/data/79/f003be7f1670b79_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Спустя то время, которое прошло после заливки мака водой, воду нужно слить через сито или марлю.','https://vkuso.ru/data/cache/data/7b/f104c26debe537b_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Соединяем крошку печенья, мак и яблочное пюре, все хорошо перемешиваем. Для более лучший формы конфет можно чуть больше добавить песочной крошки. Масса печенья липнет к рукам, после того как вы скатали пару шариков, просто помойте руки.','https://vkuso.ru/data/cache/data/fd/cc351697ebab4fd_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Из данной массы просто катаем шарики и в той части мака которую вы оставили для обсыпки берем, и обсыпаем конфеты.','https://vkuso.ru/data/cache/data/5a/6dcce5ecd3eaf5a_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2464,'Конфеты перекладываем на тарелку. (Часть конфет я обсыпал в кокосовой стружки) Эти конфеты можно убрать в холодильник на 30 минут.','https://vkuso.ru/data/cache/data/03/2ee2b8209b45d03_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Мелко нарезать капусту.','https://vkuso.ru/data/cache/data/55/3f134ffeb6e8355_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Вскипятить 2 литра воды. Нарезанную капусту поместить в кипящую воду. Снова довести воду до кипения и варить капусту до полуготовности, примерно 5 минут.','https://vkuso.ru/data/cache/data/3b/ae32b777906093b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Затем горячую воду слить.','https://vkuso.ru/data/cache/data/4c/d496ee21488594c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'В глубокую миску разбить 5 яиц, добавить соль и черный перец. Перемешать.','https://vkuso.ru/data/cache/data/c4/80e40cb49b6dfc4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Добавить муку. Тщательно всё перемешать, чтобы не осталось комочков муки.','https://vkuso.ru/data/cache/data/67/4c2ef17582a0467_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Добавить капусту и сыр, натертый на крупной терке. Перемешать.','https://vkuso.ru/data/cache/data/d3/ef22297b8aec1d3_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Сковороду разогреть, смазать растительным маслом. Порциями (по 1 ст. ложке) выложить в сковороду тесто. Обжаривайте капустные оладьи с сыром до золотистого цвета.','https://vkuso.ru/data/cache/data/60/3efef378a696d60_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2465,'Капустные оладьи с сыром готовы! Подаем к столу в горячем виде со сметаной! Приятного аппетита!','https://vkuso.ru/data/cache/data/8e/964fd1d07b3878e_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2466,'Картошку очистить. Отварить в подсоленной воде до готовности. После этого размять ее в пюре. В массу положить 1 яйцо, манную крупу и муку. Смесь посолить и тщательно перемешать. Готовое картофельное тесто раскатать в лепешку. Она не должна быть тонкой. После чего разрезать ее на прямоугольник. В него нужно будет завернуть сосиски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2466,'Сливочное масло растопить и положить туда яйцо. Всю массу взбить при помощи миксера.  Эта смесь необходимо для того, чтобы обмазать ею сосиски в картофельной шубке. При желании можно обвалять каждую в растолченных сухарях. Запекать блюдо в разогретой духовке до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Свежую или мороженую клюкву превратить в пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Сушеную или свежую черноплодную рябину промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Перемолоть пекан в крошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Воду прогреть до сорока градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Перемешать на средней скорости в кухонном комбайне льняную кашу с клюквенным пюре и водой, половиной рубленого пекана, цветочным медом и половиной черноплодки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Мед добавлять по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2467,'Выложить в тарелки, украсить облепихой, клюквой, черноплодной рябиной, пеканом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Льняную муку отправить в емкость, залить горячей водой, всыпать соль, накрыть крышкой, обмотать махровым полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Очистить морковь, натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Нашинковать репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Кабачки и тыкву нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Выложить часть овощей в емкость с толстым дном и стенками, сверху – льняная каша, третий слой – овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2468,'Блюдо должно получиться похожим на запеканку. Заправить домашним майонезом с чесноком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Семена льна перебрать, не промывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Залить водой в соотношении один к двум. Время замачивания – от часа до двух.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Переложить в блендер, взбить до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Добавить нарезанный банан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Снова все взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Выложить в тарелку, сверху – оставшийся нарезанный банан и дольки персика.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2469,'Посыпать грецкими орехами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Семена расторопши замочить на пять часов или на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Продукт можно перемолоть в кофемолке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Семена льна замочить на ночь в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Продукт также можно измельчить в кофемолке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Бананы очистить и поломать на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Перемолоть в чаше блендера вместе с льном и расторопшей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Если используются молотые семена – залить их теплой водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Все вместе взбить до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2470,'Выложить в тарелки, украсить фруктами, посыпать какао-порошком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Клубни залить холодной питьевой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Приготовить пюре при помощи толкушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Добавить теплое масло или молоко, натертую отваренную морковь, муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Должен получиться густой вязкий состав.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Массу немного остудить, вбить сырое яйцо, давленый чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Продукты хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Нагреть растительное масло, сформовать биточки толщиной в два сантиметра, обвалять в сухарях.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2471,'Обжарить до появления золотистой корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2472,'Огурцы хорошо вымыть, обрезать хвостики и нарезать крупными кружочками.','https://vkuso.ru/data/cache/data/92/cf101ec57cdd392_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2472,'Для приготовления заправки смешать соевый соус, лимонный сок, чеснок, растительное масло, красный острый перец и мед.','https://vkuso.ru/data/cache/data/f2/af4e62ee27fedf2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2472,'Нарезанные огурцы переложить в глубокую миску, добавить заправку и перемешать. Пробуем на вкус, если требуется, добавляем недостающие специи.','https://vkuso.ru/data/cache/data/71/4e869d56e510271_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2472,'Миску закрываем пищевой пленкой и оставляем мариноваться минимум на 20 минут, а лучше на 1-2 часа.','https://vkuso.ru/data/cache/data/57/3aa723fe2707757_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2472,'Затем перекладываем в салатницу и посыпаем кунжутом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2473,'Лук очистить и порезать на мелкие кусочки. Пучок зелени промыть под проточной водой и тоже мелко накрошить.  Добавить все к свежему творогу. Чтобы смесь получилась более нежной и мягкой, нужно взбить ее с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2473,'Взять хлеб нарезать на куски и смазать полученной смесью.  На него положить порезанный тонкими пластинами редис. Сверху редиса положить слой огурцов порезанных ломтиками. В самую последнюю очередь на бутерброды положить пластины семги. Ломтики должны быть тонкими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Шампиньоны или любые другие грибы промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Отварить продукт в воде с солью, откинуть на дуршлаг, мелко нарезать, обжарить вместе с рубленым репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Добавить соль, молотый перец, давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Картофель охладить, размять, соединить со специями и яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Сформовать небольшие лепешки, выложить начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Края соединить, изделия должны быть похожи на котлету.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2474,'Биточки обвалять в сухарях, жарить на горячей сковороде, на растительном масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Отварить картофель, приготовить пюре. Текстура продукта должна быть плотной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Вбить сырое яйцо, тертый сыр, перец молотый и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Сформовать маленькие биточки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Обвалять в муке, опустить в яичную болтушку, затем окунуть в сухари с молотой паприкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'Изделия обжарить в растительном масле до появления золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2475,'По желанию в пюре можно добавить луковую пассеровку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Приготовить пюре, вбить яйцо, влить теплое молоко, специи, соль, молотый перец. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Выложить рубленый репчатый лук на сковороду, обжарить в масле, добавить фарш из равных долей говядины и баранины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Жарить все вместе до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Слепить небольшие лепешки мокрыми руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Выложить фарш, края лепешек соединить, сформовать биточки, обжарить на растительном масле до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Должна получиться хрустящая корочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2476,'Приготовить соус из сметаны, рубленого укропа, измельченного чеснока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Картофель очистить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Отварить до готовности, жидкость слить, приготовить пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Полуостывшую массу дополнить сливочным маслом, мукой, яйцом комнатной температуры, нарезанной мелкими кубиками ветчиной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Порубить стрелки зеленого лука, поперчить массу, хорошо перемешать все продукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Прогреть на сковороде растительное масло, сформовать биточки ложкой, выложить на расстоянии друг от друга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2477,'Жарить до корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Очистить картофель, отварить до мягкого состояния в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Пропустить клубни через мясорубку вместе с размороженными крабовыми палочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Добавить рубленую петрушку, укроп, любые другие растения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Влить томатную пасту, тертую морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Массу вымесить, она должна получиться однородной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Растительное масло прогреть на сковороде, выложить сформованные биточки, жарить с двух сторон до появления розовой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2478,'Приготовить соус из постного майонеза, рубленого укропа и томатной пасты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Клубни очистить и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Отварить, жидкость слить, продукт охладить, пропустить через кухонный комбайн.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Добавить пассерованный до прозрачного состояния репчатый лук, вбить сырые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Продукты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Можно добавить муку или манку, если тесто получилось жидковатым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2479,'Оформить ложкой биточки, хорошо обвалять в сухарях, обжарить на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Отварить очищенный и нарезанный кубиками картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Остудить до теплого состояния, приготовить пюре с мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Отварить яйца вкрутую, покрошить, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Поперчить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Сформовать маленькие биточки, обжарить до румянца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2480,'Подать со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Фарш выложить в емкость, добавить молотый перец и любые специи, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Перемешать, массу отбить руками, бросая ее руками на стол или обратно в мисочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Процесс повторить двадцать раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Сформовать мокрыми руками небольшие котлеты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Обвалять изделия в сухарях.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Обжарить на растительном масле на сковороде, с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2481,'Допечь под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Куриное мясо промыть и обсушить, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Свежий или подсохший батон замочить в молоке, отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Куриное филе пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Продукты соединить, добавить соль, перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Долить сливки, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Сформовать биточки небольшого размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2482,'Жарить на сковороде с маслом, с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2483,'Муку просеять в глубокую миску. Положить к ней соль, разрыхлитель и сахар. Разбить туда яйца и влить половину стакана молока.  Тщательно перемешать смесь. Главное постараться, чтобы не было комочков. Постепенно влить остальное молоко, не переставая мешать. В это же время нужно влить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2483,'Разогретую сковородку смазать маслом и налить тесто. При этом нужно постараться чтобы оно покрыло сковородку ровным тонким слоем. Как только блинчики сверху просохнут можно переворачивать на другую сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2483,'Для приготовления начинки нужно мелко покрошить репчатый лук и грибы. В чистую сковородку положить сливочное масло и прожирать там лук и грибы. В конце жарки посыпать солью и перцем. Можно еще добавить немного масла. В готовый блин положить начинку сверху покрыв ломтиком сыра. Свернуть блинчики с грибами, луком и сыром в виде конвертиков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2484,'Отварить картофель в кожуре, подождать, пока остынет, почистить, порезать на кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2484,'Сложить в плошку слоями картофель, порезанные огурчики, помидоры, редиску, посолить, поперчить, залить сметанкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2484,'Положить сверху отваренные яйца, порезанные на дольки, посыпать салат «Бахар» со сметаной измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Почистить репчатый лук, порезать на тоненькие полукольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Растопить масло в сковороде, чуть-чуть обжарить лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Положить томатную пасту, помешивая, довести лук до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Помыть креветки, отварить, достать креветки из бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Не выливать бульон – он еще будет нужен.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Охладить креветки, почистить, порезать на небольшие кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Бульон от креветок поставить на огонь, довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Положить в кипящий бульон пассированный лучок, огурцы, почищенные от кожуры и порезанные на маленькие кубики, лавровый листик, каперсы, перец горошком, посыпать солью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Готовить минут десять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'За несколько минут до завершения готовки заправить сметанкой, довести до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Перед подачей положить в тарелочки вареные креветки, маслины, порезанные пополам, кусочек лимона.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2485,'Разлить по тарелкам солянку, посыпать солянку с креветками и каперсами измельченной петрушкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Взять картофель (можно в мундире), порезать на кубики приблизительно 1 на 1 сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Порезать отваренное мясо (можно взять колбасу или копченое мясо), порезать на кубики 1 на 1 сантиметр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Чуть-чуть обжарить порезанное мясо или колбасу, убрать со сковороды при помощи шумовки, чтобы масло стекло в сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Можно использовать и колбасу, и мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'В жире, который остался в сковороде, чуть-чуть обжарить порезанный картофель, посыпать солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Положить к картофелю обжаренное мясо, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'В отдельной посуде смешать яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Положить несколько ложек майонеза или сметанки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Взбить при помощи венчика до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Яичной смесью залить мясо с картофелем.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2486,'Отправить блюдо в горячую духовку, готовить крестьянский завтрак в сметане до образования корочки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'Отварить морковь и картофель, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'Колбаску и консервированный перец порезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'В подсоленной воде отварить зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'Смешать все продукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'Заправить Украинский салат «Буковина» с копченой колбасой и перцем смесью сметанки, взбитой с соком лимона, желтком, перцем и солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2487,'Посыпать салатик измельченным зеленым лучком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'Лук нарезать мелкими кубиками. Включить режим ЖАРКА на 15 минут и обжарить лук до мягкости минуты 3.','https://vkuso.ru/data/cache/data/81/b0ece3536eb2581_434x295_notrise.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'Мясо нарезать небольшими кусочками и обжарить вместе с луком 7-8 минут.','https://vkuso.ru/data/cache/data/c2/029c43aa7a20fc2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'На помидоре сделать крестообразный надрез, залить кипятком. Воду слить, аккуратно снять кожицу и нарезать кубиками.','https://vkuso.ru/data/cache/data/49/e95ee4c07ba8149_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'Добавить к мясу и луку, обжаривать до конца программы.','https://vkuso.ru/data/cache/data/34/9d7d11a07797034_434x295_notrise.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'Добавить рис, томатную пасту, соль, специи, воду. Включить программу СУП/ТУШЕНИЕ на 60 минут.','https://vkuso.ru/data/cache/data/4c/d92b25ad71f094c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'За 5 минут до готовности, добавить свежую зелень.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2488,'Приятного аппетита!','https://vkuso.ru/data/cache/data/c6/d56999c85dfbbc6_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2489,'В первую очередь необходимо подогреть уксус с сахаром и солью. Рис тщательно промыть под проточной водой, и откинуть на дуршлаг, чтобы вся лишняя влага стекла. После чего положить рис в кастрюлю и залить чистой водой. Поставить на огонь и дать вскипеть, проварить в течение 15 минут. Далее необходимо убавить огонь и варить еще 7 минут. Затем снять кастрюлю с огня и оставить на 15 минут, предварительно завернув его полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2489,'Как только время выйдет необходимо залить рис подготовленным уксусом и тщательно перемешать, оставить охлаждаться. Специальную циновку нужно покрыть пищевой пленкой, сверху положить лист нори. На него ровным слоем выложить рис. Чтобы распределить рис по всей поверхности листа необходимо периодически обмакивать руки в воде с лимоном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2489,'Затем нужно перевернуть листом вверх. Положить на нори свежие огурцы и мякоть свежего авокадо.  Сверху положить ломтики угря. Теперь нужно сделать самое сложное – аккуратно завернуть лист в ролл. При этом необходимо стараться уплотнить рулет, чтобы ингредиенты не вываливались. Готовый ролл можно разрезать на куски. Суши с угрем и авокадо посыпать семенами кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Разогреть мангал или гриль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Посыпать перцем и солью мясо, чуть-чуть сбрызнуть растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Разложить на решетке, обжарить с двух сторон до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Положить на тарелочку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Чуть-чуть остудить, порезать на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'В маленькой посуде соединить майонез, сметанку, измельченный зеленый лук, хрен, черный перчик, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Намазать лепешки смесью с одной стороны, положить три кусочка мяса и два сыра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Посыпать нашинкованным латуком, завернуть рулетиком, краешки подгибать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Каждый ролл завернуть в пергамент.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2490,'Охладить роллы из говядины с чеддером часов восемь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Отваренный картофель порезать на маленькие кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'На такие же кубики порезать свежий огурчик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Кубиками порезать вареную колбаску и яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Мелко порезать редис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Измельчить зеленый лучок и укроп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Чтобы вкус блюда был еще насыщенней, измельченную зелень перетереть для появления сока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Измельченные продукты перемешать в общей емкости, посыпать солью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Разложить салатную массу по тарелочкам, можно добавить ½ маленькой ложки потертого хрена, большую ложку сметанки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Залить квасом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Также, чтобы придать окрошке еще более приятный вкус, можно положить чуть-чуть горчицы. Перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2491,'Посыпать домашнюю окрошку с колбасой и хреном свежей зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Сделать сдобное пресное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Сварить куриное мясо, отделить мясо от костей, порезать на ломтики, заправить белым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Сварить рис, заправить рассыпчатый рис маслом, положить измельченные яйца, отваренные вкрутую, зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Потушить в масле белые грибы, заправить белым соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Из приготовленного теста и начинок сделать пирог.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'¼ теста отделить для поверхности пирога, остальное тесто раскатать в круглый пласт толщиной полтора сантиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Переложить ее в формочку, смазанную маслом, или сковороду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Краешки формочки должны быть покрыты слоем теста.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Выложить на лепешку начинку слоями: рис, яйца, порезанные кружочками, курицу, порезанную на ломтики, грибы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Раскатать оставленный кусочек теста, накрыть начинку, сделать в середине отверстие, чтобы во время готовки выходил пар.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2492,'Готовить курник с белыми грибами и рисом, соблюдая температуру 220 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Довести до кипения воду с солью и маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Просеять муку, высыпать на стол в виде горки, сделать колодец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'В три приема вылить в колодец горячую воду с маслом, осторожно размешивать ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Кода вся вода будет вылита в муку, вымешать тесто. Должно получить пластичное, гладкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Скатать шар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Приготовить начинку: помыть и посушить вишни, просеять сахарную пудру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Косточки из вишни можно вытащить, можно и оставить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Соединить сахарную пудру и манную крупу или крахмал, соблюдая пропорцию 4 к 1 или 2 к 1.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Отрезать часть теста, раскатать толщиной пять миллиметров.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Вырезать из пласта кружки, используя рюмку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Накрыть заготовки полотенцем, приступить к лепке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Все кружки раскатать тоненько.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'В центр каждого положить ягоды, посыпать смесью пудры, краешки соединить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'В завершение заплести косичку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Бросить вариться в кипящую соленую воду минуты на четыре.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2493,'Достать домашние вареники с вишней и сахарной пудрой, положить на тарелочки и наслаждаться.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Взбить при помощи венчика яйца и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Насыпать разрыхлитель, соль, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Налить кефир, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Медленно насыпать манную крупу, очень быстро перемешать тесто при помощи венчика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Наполнить формы на 2/3.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Положить в центр курагу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2494,'Запекать манные кексы с курагой в духовке минут сорок, соблюдать температуру приблизительно 170 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Лук репчатый нарезаем маленьким кубиком, перекладываем в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Чеснок нарезаем маленьким кубиком, перекладываем к луку. Убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Сыр натираем на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Нарезаем помидор',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Фарш надо заранее разморозить. После этого перекладываем его в миску, солим, перчим, перекладываем лук с чесноком. Все хорошо перемешиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Вбиваем яйцо и снова перемешиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'Из фарша катаем мясные шарики, их можно запанировать в панированных сухарях. Перекладываем на противень (у меня стеклянный).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2495,'На эти шарики укладываем сыр и помидор. Отправляем в разогретую духовку до готовности. У меня мясные шарики запекались минут 40. Если у вас скатится сыр его можно поправить. Все готово. Большое спасибо за внимание!',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2496,'Почистить фрукты, порезать на крупные кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2496,'При помощи блендера сделать из фруктов однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2496,'Насыпать в пюре сахарную пудру, чтобы консистенция была жидковатой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2496,'Сок можно не добавлять, тогда получится фруктовое очень вкусное пюре, его можно есть ложечкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2496,'Перед подачей посыпать коктейль тертым шоколадом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2497,'Имбирь очистить и порезать на тонкие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2497,'Засыпать в турку сахар, корицу, кофе, положить имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2497,'Залить массу кипятком, дать постоять несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2497,'Перемешать, вылить в чашку, подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2498,'Выжать из лаймов сок, хорошо взбить в блендере вместе с йогуртом, тертой цедрой лаймов, молоком, фруктозой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2498,'Разлить смесь по формочкам, воткнуть по центру палочки, убрать замороженный йогурт с лаймом и фруктозой на 3-4 часа в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2498,'Форму достать, окунуть дно в кипяток, достать лакомство, переложить на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Порезать один апельсин на тоненькие кружочки, со второго апельсина снять цедру, почистить, разделить на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Положить все в кастрюльку, налить воду, насыпать сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Варить минут пятнадцать на минимальном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Кружочки будут служить в качестве украшения, апельсиновые дольки отправить в блендер, залить 75 граммами сиропом, измельчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Процедить остальной сироп, отставить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Сделать бисквит: залить миндаль кипятком, почистить, подсушить, обжарить на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Позволить остыть, измельчить практически в муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Просеять миндаль, разрыхлитель, муку и мак.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Минуты четыре взбивать яйца, насыпать сахар, соль, взбивать еще несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Осторожно примешать пюре из апельсина, после этого добавить мучную смесь в три приема.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Постелить на дно формочки специальную бумагу, положить кружки апельсина, налить тесто, отправить в духовку минут на сорок, соблюдать температуру 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Готовность нежнейшего апельсиново-макового торта проверять сухой зубочисткой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Перевернуть, охладить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Для крема смешать яйца, лимонный и апельсиновый сок, тертую цедру лимона и апельсина, сахар, масло и сливки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2499,'Промазать коржи, украсить миндальными лепестками.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Помыть огурцы и редис, порезать на тоненькие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Порезать куриное филе на тоненькие ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Почистить лук, порезать на тоненькие кольца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Порезать брынзу на тоненькие пластинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Все кусочки хлеба намазать маслом (сливочным).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'На четыре кусочка хлеба положить колечки редиса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'На два кусочка положить пластинки брынзы, на нее пластинки огурца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'На два ломтика положить колечки лука, на него положить кусочки мяса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Чуть-чуть посыпать перцем, солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'На хлеб с редисом положить перышки лука.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Сложить сэндвичи попарно.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'Во всех сэндвичах должен присутствовать ломтик с редисом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2500,'При помощи острого ножа разрезать сэндвичи с куриным филе и редисом на треугольники.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Разрезать маргарин или масло на части, отставить, чтобы оно стало мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'В большой посуде взбить яйца и сахар, положить погашенную соду, взбить, положить маргарин или масло, порубить его мелко, взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Медленно насыпать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Сыпать муку, пока ее удобно взбивать миксером, потом насыпать постепенно остальную, но перемешивать при помощи ложки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Когда станет трудно мешать и ложкой, высыпать в тесто оставшуюся муку и вымешивать руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Тесто не должно прилипать и должно остаться мягким.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Если липнет, то насыпать чуть-чуть муки и продолжать вымешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Если потребуется, то повторить процесс несколько раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Приготовленное тесто обернуть в полиэтилен и отправить в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Включить духовку и нагреть до двухсот градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Присыпать противень мукой (постелить специальную бумагу).',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Достать из холодильника тесто, отрезать ¼ часть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Остальное снова отправить в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Из теста сформировать колбаску, пропустить через мясорубку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Когда тесто будет выходить, подождать, пока оно опустится на пять сантиметров, рукой приподнять снизу и отрезать ножом. Так получится идеальная форма – основание и пушистый цветочек.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Положить заготовку на противень.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Чтобы следующее печень получилось в форме красивого цветка, счистить оставшееся тесто с решетки мясорубки.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Когда все тесто в мясорубке будет использовано, достать из холодильника кусок и продолжать.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Желательно делать процедуру быстро, чтобы тесто сохранило форму и не начало таять.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Наполненный противень отправить в духовку и ждать готовности – приблизительно минут сорок.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2501,'Посыпать готовое печенье «через мясорубку» на сливочном масле сахарной пудрой и можно подавать.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Вскипятить воду в большой кастрюльке, готовить пасту минут десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'В это время приготовить креветки: растопить сливочное масло на сковороде, подогреть оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Добавить прессованный чесночок, готовить шестьдесят секунд, должен появиться аромат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Положить почищенные вымытые креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Готовить еще минуты три, креветки должны стать красноватыми.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Переложить креветки в емкость и отставить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'В ту же сковороду положить консервированные томаты (томатную пасту), насыпать соль, черный и красный перчик, готовить на тихом огне минут пять, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Когда соус станет густоват, положить пасту, промытую заранее проточной водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Перемешать соус, пасту, положить креветки. Вновь перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'Попробовать на соль.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2502,'В конце украсить пасту с креветками и консервированными помидорами измельченной свежей петрушкой, чтобы блюдо приобрело свежий вид.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2503,'В небольшую кастрюльку или сотейник отправляем яблочное пюре. Добавляем быстрорастворимый желатин (это должно быть указано на упаковке). Перемешиваем.','https://vkuso.ru/data/cache/data/8a/713512ce3b89d8a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2503,'Ставим кастрюлю на плиту и на небольшом огне, постоянно помешивая, нагреваем пюре с желатином. При этом масса не должна закипеть. Как только масса прогреется и желатин начнет распускаться, пюре станет более жидким и однородным.','https://vkuso.ru/data/cache/data/e9/08ffc028d27cce9_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2503,'Снимаем кастрюлю с плиты и сразу же начинаем взбивать миксером, на высокой скорости. Взбиваем 10-15 минут, масса должна побелеть и увеличиться в размерах.','https://vkuso.ru/data/cache/data/25/5d107ba90580a25_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2503,'Форму застелить пищевой пленкой, выложить в нее яблочную массу и убрать в холодильник до полного застывания, примерно на 1 час.','https://vkuso.ru/data/cache/data/a4/cb7f03678a4a4a4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2503,'Затем достаем форму из холодильника нарезаем десерт на порционные кусочки и подаем к столу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2504,'Некрупную картошку очистить и тщательно обсушить. Каждую необходимо наколоть зубочисткой. В глубокую миску налить масло, добавить протертый через мелкую терку чеснок, посолить и приправить. Туда же всыпать рубленую зелень. Всю эту смесь вылить на картошку и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2504,'Заправленную картошку положить в пакет для запекания, плотно завязать. Чтобы при выпекании пакет не вздувался необходимо его проколоть в нескольких местах.  Запекать блюдо нужно в духовке разогретой до 200 градусов. Время на приготовление примерно 1 час. Картофель на гарнир, запеченный в пакете, готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Вымыть и очистить кабачки, разрезать пополам, удалить все семена, порезать на кубики небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Апельсины вместе с лимоном прокрутить на мясорубке или мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Смешать с кабачками, добавить сахар, дать постоять часов 5, а лучше ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Утром довести смесь до кипения, проварить несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Дать остыть, процесс повторить еще пару раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2505,'Заполнить готовым Янтарным вареньем из кабачков с апельсинами и лимоном простерилизованные банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Печенье измельчить в крошку блендером, смешать с растопленным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Заполнить масляной крошкой форму, утрамбовать ее, сделать с помощью ложки бортики поместить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Засыпать в сыр сахар, перемешать, вбить яйца, положить ванильный сахар, влить сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Полученную массу хорошо размешать, нанести полученный крем на хорошо охлажденный корж.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Поломать на кусочки шоколад, растопить, вылить на крем, сделать с помощью зубочистки узоры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Форму с ванильно-шоколадным чизкейком из печенья обернуть фольгой, установить на противень с высокими бортикам, который заполнен кипятком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Выпекать десерт около часа при температуре не выше 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2506,'Готовый чизкейк остудить и убрать минимум на два часа в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'Взбить размягченное масло с яйцами и сахарным песком до получения воздушной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'Всыпать в нее порциями смесь просеянной подсоленной муки с разрыхлителем в каждую порцию добавлять сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'Разрезать яблоки на четвертинки, удалить семена, порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'Засыпать их вместе с изюмом в тесто, осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'На подготовленный и выстланный пергаментом противень выложить с небольшим расстоянием чайной ложкой порции теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2507,'Мягкое печенье с изюмом и яблоками будет готово примерно через четверть часа, температура в духовки должна быть около 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'Очистить клубни картофеля, порезать их на брусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'Подготовленные куриные голени присолить и обсыпать приправой, выложить на дно мультиварки с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'Уложить на курицу подсоленный картофель, присыпать его приправой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'Выставить режим «Выпечка» на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'После сигнала открыть крышку, перемешать куриные ножки с картофелем и укропом в мультиварке, закрыть и готовить, не меняя режима, еще треть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2508,'Мелко нашинковать укроп, посыпать, разложенное по тарелкам, готовое блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Подсоленную воду с маслом довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Всыпать полстакана муки, энергично перемешать до гомогенного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Вбить яйцо, хорошо перемешать, добавить остаток муки, вымесить еще раз до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Полученное тесто должно быть пластичным и не липнуть к рукам, оставить его постоять около часа-двух.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'За это время мясной фарш перемешать с перекрученным луком, кефиром (водой), добавить специи, подсолить, поперчить, хорошо вымесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Раскатать сочни, положить на одну половину фарш, накрыть второй, защипать с помощью вилки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2509,'Обжарить правильные чебуреки с мясной начинкой в хорошо разогретом масле до золотисто-солнечного цвета с одной и другой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Включить для разогрева до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Стакан сахарного песка взбить с белками до устойчивой пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Второй стакан взбить с желтками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Объединить обе смеси, добавить муку, осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Вылить на выстланный пергаментом противень половину теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Поместить в прогретую духовку минут на 20.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Также выпечь второй корж.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Разрезать каждый на два, выровнять ножом края.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Для крема взбить сгущенку и размягченное масло, всыпать обжаренные и измельченные орехи, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Пропитать равномерно коржи крепким кофе без сахара, смазать кремом, сложить в стопку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2510,'Убрать ореховое пирожное с кремом из вареной сгущенки в холодильник, дать хорошо пропитаться, порезать на пирожные.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2511,'Вымесить из подсоленной муки тесто, дать ему постоять полчаса в тепле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2511,'Мясо прокрутить с луком и чесноком, сдобрить перцем, перемешать с подсоленным молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2511,'Часть теста раскатать в пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2511,'Вырезать кружки, положить на каждый по ложке фарша, хорошо защипать полумесяцем, а потом скрепить края между собой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2511,'Выложить пельмени сибирские на молоке на доску, присыпанную мукой, хорошо заморозить, переложить в пакет и оставить в морозилке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2512,'Обжарить подготовленные грибы, добавить кубики ветчины, жарить все вместе еще минуты 4.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2512,'Взболтать яйца, всыпать к ним натертый сыр, нашинкованный мелко укроп, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2512,'Вылить к грибам, поперчить, присолить, перемешать, готовить все вместе еще минуты 4.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2512,'Лист готового теста раскатать, надрезать от краев к центру, положить начинку, заплести полоски в косичку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2512,'Смазать яичницу-болтунью с ветчиной и грибами в слоеном тесте разболтанным яйцом, печь примерно треть часа в прогретой до 190 градусов духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2513,'Все ингредиенты смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2513,'Форму промазать маслом, заполнить формы до половины полученной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2513,'Далее выложить изюм, сгущенку или курагу, прикрыть оставшимся тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2513,'Выпекать в прогретой до 200 градусов сырники с изюмом на сметане в формочках около получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Приготовить желе разных цветов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Хорошо охладить в общей камере холодильника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Порезать на кусочки, очень острым горячим ножом, перемешать кусочки между собой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'В другой емкости залить пару пакетиков желатина 0,5 стаканом охлажденной воды, дать разбухнуть в течение пары минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Влить полтора стакана воды, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Влить сгущенку, размешать, смесь охладить, залить разноцветные кубики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Убрать десерт в холодильник, дать переночевать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2514,'Нарезать на порции очень острым подогретым ножом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2515,'Подготовить сердечки, обжарить, периодически перемешивая в растительном масле порядка 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2515,'Подсолить, поперчить, добавить кориандр, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2515,'Влить томатный соус, обжаривать куриные сердечки в томатном соусе с чесноком еще 20-25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2515,'В почти готовое блюдо добавить порубленный чеснок, перемешать, готовить 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2516,'Растопить шоколад и сливочное масло. Яйца тщательно взбить с сахаром. Добавить первую смесь ко второй и перемешать. Всыпать в эту массу муку и снова перемешать. Готовую смесь нужно разлить по промазанных маслом формочкам. Чтобы шоколад легко отставал нужно предварительно формочки посыпать мукой или какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2516,'Выпекать десерт при температуре 210 градусов не более 10 минут. После чего достать его и остудить. Пока пирожное теплое положить сверху нежный крем или мороженое. Чтобы середина пирожного вытекла и смешалась с кремом или мороженым — проткнуть выпечку ложечкой. Пирожное «Тающий шоколад» готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Рис отварить, каша должна быть мягкой, но рассыпчатой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Порубить зелень петрушки, репчатый лук и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Продукты соединить с мясным фаршем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Вбить сырые желтки, всыпать специи, соль, отваренный рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Добавить панировочные сухари, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Прогреть на сковороде растительное масло до потрескивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2517,'Мокрыми руками сформовать небольшие круглые котлеты, жарить до получения румяной корочки с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Белый батон размочить в молоке, отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Пропустить через мясорубку вместе с репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Массу соединить с любым фаршем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Добавить яйцо, перец молотый, соль. Хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Высыпать на тарелку крахмал.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Мокрыми руками слепить круглые котлеты, обвалять в крахмале.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Довести на сковороде растительное масло до кипения, жарить биточки с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Приготовить подливу из мелко покрошенного репчатого лука, тертой моркови.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Овощи спассеровать в течение десяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Влить томатный соус, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Подливу поперчить, посолить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Влить воду, довести до кипения.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Готовые биточки выложить в форму, смазанную маслом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2518,'Добавить подливку, поставить в духовку на пятнадцать минут, печь при температуре 185 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Отварить картофель, порубить репчатый лук, спассеровать его на сковороде с маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Добавить мясной фарш, приправы, перец, соль, жарить все продукты вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Приготовить из картофеля пюре, добавить яйца и теплое молоко. Масса должна быть плотной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Приготовить лепешки, выложить мясную начинку, края завернуть, залепить шов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Обмакнуть биточки в яйцо, запанировать в сухарях.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Выложить на горячую сковороду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Жарить с обеих сторон в масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Приготовить соус из рубленого укропа, чеснока, сметаны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Массу перемешать при помощи блендера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2519,'Полить биточки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Говядину нарезать кусками, приготовить фарш при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Белый хлеб размочить в молоке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Продукт отжать, переложить в блендер вместе яйцом, молоком, посолить по вкусу, добавить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Перемешать. Сформовать биточки-шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Влить воду в чашу мультиварки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Выставить решетку, выложить биточки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2520,'Установить режим «Пар» на тридцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Свинину, говядину, репчатый лук перетереть в фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Добавить соль, размоченный в молоке батон, перец, сырые яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Массу вымесить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Измельчить плавленый и твердый сыр на терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Сформовать из фарша лепешки, выложить на каждую немного тертого сыра, свернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2521,'Обжарить на подсолнечном масле с двух сторон, потушить под крышкой до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Белый хлеб выложить в мисочку, влить охлажденное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Дать постоять и отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Рыбу с репчатым луком и хлебом пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Вбить сырое яйцо, всыпать соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Массу хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Ввести манную крупу, смесь должна постоять полчаса для набухания крупы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Сформовать котлеты, выложить в форму, смазанную маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'Время запекания в духовом шкафу – двадцать пять минут. Температура приготовления – 225 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2522,'По желанию долить немного воды – продукт не должен пригореть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2523,'Охлажденные, но не замороженные крабовые палочки мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2523,'Твердый сыр натереть или нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2523,'Отдельно перемешать майонез с давленым чесноком, добавить палочки и сыр, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2523,'Выложить магазинные чипсы на блюдо, сверху – начинка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2523,'Украсить мятой или петрушкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2524,'Сливочное масло подержать при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2524,'Измельчить чеснок, добавить в масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2524,'Массу намазать на магазинные чипсы, сверху выложить красную икру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2525,'Авокадо очистить, мякоть размять в кашицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2525,'Добавить измельченную зелень петрушки, сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2525,'Добавить нарезанные кубиками помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2525,'Креветки очистить, добавить в основную массу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2525,'Выложить начинку на чипсы, украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2526,'Натереть чеснок, сыр, перемешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2526,'Выложить массу на чипсы, сверху – веточки укропа и мелкие креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Болгарский перец нарезаем соломкой.','https://vkuso.ru/data/cache/data/b4/a491264b8e7feb4_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Сыр натираем на любой терке, крупной или мелкой.','https://vkuso.ru/data/cache/data/df/37f91ae9aa6d9df_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Куриное промываем, обсушиваем. Затем отбиваем.','https://vkuso.ru/data/cache/data/5a/5ac18c7ccd75c5a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'После солим, перчим, добавляем приправу для курицы.','https://vkuso.ru/data/cache/data/21/99e7c71421a8e21_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Затем добавляем соевый соус, перемешиваем и убираем в строну на 30 минут.','https://vkuso.ru/data/cache/data/e0/8cd2aae262bd4e0_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Спустя 30 минут куриное филе перекладываем на противень (у меня стеклянный) после перекладываем болгарский перец и посыпаем сыром. Отправляем в духовку до готовности, примерно 1 час.','https://vkuso.ru/data/cache/data/82/3b360e59b385f82_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2527,'Ужин готов, приятного аппетита!','https://vkuso.ru/data/cache/data/b2/ed9a76c96e025b2_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Берем печенье савоярди и отрезаем нужную длину для бортиков. Выкладываем бортики сахарной стороной наружу.','https://vkuso.ru/data/cache/data/96/149fc8edee28296_434x295_notrise.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Клубнику соединяем с сахаром и пробиваем блендером, получаем сироп-пропитку. ','https://vkuso.ru/data/cache/data/95/bef88fd27c25395_434x295_notrise.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Для крема взбиваем в холодной чаше холодные сливки, добавляем сахарную пудру, хорошо перемешиваем блендером, далее добавляем сливочный сыр. Хорошо перемешиваем до однородного крема.','https://vkuso.ru/data/cache/data/c3/5000d3a9e1220c3_434x295_notrise.jpeg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Торт собирается очень легко, печенье Савоярди хорошо обмакиваем в клубничном сиропе с двух сторон и выкладываем плотно друг к другу в форму. Пустоты заполняем маленькими кусочкам.','https://vkuso.ru/data/cache/data/46/b9f3412ff2bca46_434x295_notrise.jpeg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Сверху распределяем крем. Затем снова идёт слой савоярди и крем. Итого получается по 3 слоя печенья и крема.','https://vkuso.ru/data/cache/data/c8/7f3b517e150b5c8_434x295_notrise.jpeg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2528,'Ставим в холодильник на пару часов, после украшаем сверху клубникой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2529,'В первую очередь  разогреть духовку до 200 градусов. Рульку необходимо промыть и обсушить полотенцем. После чего с помощью ножа сделать глубокие разрезы по всей длине рульки. Затем тщательно натереть рульку протертым через мелкую терку чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2529,'Обильно обсыпать специями и солью. Смазать майонезом. Затем завернуть в фольгу и положить на глубокий противень. Блюдо нужно отправить в духовой шкаф на два часа. По истечению времени достать противень аккуратно развернуть фольгу и подавать свиную рульку с чесноком на стол с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2530,'Рыбу нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2530,'Авокадо очистить, также нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2530,'Ингредиенты перемешать, влить сливки, нашинкованную зелень укропа. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2530,'Чипсы большого размера выложить на блюдо, сверху – начинка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Чеснок очистить и нарезать, перемешать с майонезом и дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Промыть зелень петрушки, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Вымыть помидоры, серединки удалить, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Такими же кубиками покрошить сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Заправить помидоры с сыром и петрушкой майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2531,'Выложить готовую начинку на чипсы, украсить листочками петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2532,'Корейский салат выложить в емкость, добавить нарезанную колбасу салями, заправить начинку майонезом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2532,'Выложить салат на чипсы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Зефир разделить на половинки, часть половинок разделить еще раз пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Приготовить крем из сметаны с сахаром. Масса должна стать пышной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Поставить продукт на полчаса в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Выложить слой зефира на тарелку, смазать сметанным кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Сверху – тонко нарезанный киви.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Далее – сметана, зефир, сметана, бананы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Украсить оставшимися зефирными половинками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2533,'Поставить десерт в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Сырые куриные яйца взбить с сахарным песком, влить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Поварить на тихом огне до вязкого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Массу остудить, взбить с мягким сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Приготовить крошку из печенья, зефир нарезать вдоль на несколько частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Собрать торт послойно: зефир, крем, крошка из печенья.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Слои повторить несколько раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Верхний слой – крошка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2534,'Поставить торт на ночь в холодильник для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Ядра грецких орехов превратить в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Взбить сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Готовый зефир разрезать поперек, фигурные пластинки оставить для украшения верха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Кружками нарезать банан, апельсин, киви.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'На середину блюда отсадить сливки, сверху – зефир и орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Залить первый слой сливками, разложить фрукты, зефир, орехи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Слои промазывать сливками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2535,'Украсить десерт по желанию, поставить в холодильник на два или три часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Мягкое сливочное масло, взбить со сгущенным молоком при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Печенье размолоть в крошку в пакете.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Измельчить грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Магазинный зефир разделить на половинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Выложить в кондитерское кольцо зефир, масляный крем, примерно четверть общего объема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Процедуру повторить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Торт поставить в холод на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2536,'Кольцо снять, торт выложить на блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Песочное печенье размолоть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Перемешать с мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Массу переложить в форму со съемным бортиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Выровнять поверхность. Отправить форму в холод на двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Творог перемолоть при помощи блендера, взбить с сахаром и сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Зефир растопить в микроволновой печи, добавить в творог вместе с лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Смесь взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Суфле разложить по застывшему нижнему слою торта.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Поставить торт в холод еще на четыре часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2537,'Готовый десерт посыпать сахарной пудрой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Сливки взбить с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Нарезать дольками персики без косточек и кожуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Зефир разрезать на три плоских части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Выложить зефирные пластинки на блюдо верхушками вниз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Покрыть сливками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Второй слой – фруктовые ломтики, сливки и снова зефир.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Тарелку перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2538,'Торт поставить в холод на три часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Печенье поломать кусочками, перемолоть в комбайне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Натереть цедру лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Сырые яйца взбить венчиком, перемешать с молоком и сахаром, частью крошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Готовую смесь перелить в емкость с толстым дном, варить до загустения. Масса должна получиться вязкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Остудить, перемешать с цедрой и мягким сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Выложить смесь слоями с половинками зефира в форму со снимающимися бортиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2539,'Дать постоять восемь часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Сливки перемешать с сахарным песком, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Готовый магазинный зефир нарезать плоскими кусочками, верхушки оставить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Выложить на блюдо зефир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Полить кремом из сливок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Выложить клубнику, нарезанную дольками, посыпать орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Далее – зефир, нарезанный кружочками киви.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Украсить верхушками зефира.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Каждый слой промазывать сливками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2540,'Поставить в холодильник на три часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'В одну чашку вбить сырые куриные белки, в другой разместить желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'В желтки добавить сахарный песок, перемешать венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Всыпать сахар в белки, взбить в пышную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Обе массы перемешать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Просеять муку, всыпать в яичную массу, замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Отсадить массу при помощи кондитерского мешка или шприца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Отсаживать на застеленный пергаментом и смазанный маслом противень. Длина печенья – до десяти сантиметров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2541,'Посыпать печенье сахарной пудрой, запечь в духовке при температуре 200 градусов. Время приготовления – пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2542,'Включить духовку и разогреть ее до 180 градусов. Дно формы смазать маслом и выложить туда консервированные ананасы. Сливочное масло (50 г) растопить, добавить 5 ложек сахара и постоянно мешая, варить на медленном огне не более 4 минут. Готовой смесью полить ананасы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2542,'В глубокой миске замешать тесто. Для этого перемешать просеянную муку с ванилином, разрыхлителем и солью. Взбить в упругую массу 100 г сливочного масла, понемногу добавляя туда сахар. Яйца вводить в массу по одному каждый раз тщательно взбивая миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2542,'Половину муки добавить к массе и снова взбить, но уже на низкой скорости. Влить сироп от ананасов, всыпать остаток муки и снова перемешать до однородного состояния. Готовое тесто понемногу влить на ананасы. Домашний ананасовый пирог-перевертыш выпекать не более 45 минут. Готовое изделие перевернуть вверх дном на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'Два желтка комнатной температуры взбить с сахарной пудрой при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'В другой емкости взбить белки, всыпать сахар, перемешать венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'Массы соединить, добавить еще один желток, муку, ванилин, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'Противень застелить пекарской бумагой, выложить тесто при помощи кондитерского мешка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'Присыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2543,'Изделия запечь в течение пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Белки отделить от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'В желтковую массу всыпать сахарный песок, взбить миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Добавить муку, соль, аккуратно перемешать вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Белки также взбить с сахаром в пену, обе массы соединить и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Противень смазать сливочным маслом, присыпать мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Выложить тесто при помощи шприца, печенье должно быть похожим на палочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Присыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Печь при температуре 150 градусов в духовом шкафу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2544,'Показатель готовности выпечки – золотистая корочка.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Разделить желтки с белками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Белки охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Перебить при помощи блендера с частью сахара. Масса должна получиться густой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'В желтки добавить сахар, немного лимонного сока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Теплые желтки также взболтать с сахаром, он должен раствориться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Добавить часть белковой массы, перемешать, положить остатки, перемешать еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Муку хорошо просеять, всыпать в основную массу порциями. Тесто должно быть воздушным.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Выдавить массу на смазанный маслом противень при помощи кондитерского мешка. Длина палочек – около десяти сантиметров, ширина – два сантиметра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Посыпать заготовки сахарной пудрой через сито.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2545,'Печь в духовом шкафу при температуре 200 градусов, время – десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Белки поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Желтки взбить с сахарной пудрой до получения крема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Добавить сливочный сыр, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Белки вынуть из холодильника, взбить при помощи миксера, добавить массу в желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Заварить отдельно кофе, добавить коньяк.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Пропитать полученным раствором печенье.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Выложить часть изделий на дно стеклянной миски или в форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Полить десерт кремом, выложить второй слой печенья, снова полить кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Процедуру повторять до тех пор, пока не закончатся продукты. Сверху – крем.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2546,'Десерт нарезать дольками, подержать в холоде для пропитывания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2547,'Куриное филе вымыть и отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2547,'Перемолоть продукт на мясорубке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2547,'Влить в фарш теплое молоко, добавить мягкое сливочное масло, всыпать муку, положить перепелиный желток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2547,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2547,'Форму смазать маслом, выложить состав, время запекания – полчаса, температура в духовом шкафу – 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Промыть куриное мясо, отварить в подсоленной воде с лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Пропустить продукт через мясорубку два раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'В этом случае фарш станет очень мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Добавить желтки, соль, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Натереть морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Растопить сливочное масло в кастрюле, выложить морковь, потушить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'На сухой сковороде поджарить муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Ингредиенты добавить в фарш, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Белки взбить в пену, добавить в основную массу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Форму смазать сливочным маслом, выложить смесь для суфле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2548,'Время запекания – полчаса, температура приготовления – 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2549,'В фарш положить молотую паприку, яйцо, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2549,'Продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2549,'Долить молоко, перемешать еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2549,'Противень смазать маслом, основную массу вылить, разровнять, смазать сметаной, присыпать еще одной порцией паприки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2549,'Температура запекания – 200 градусов. Время приготовления – до получения румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Филе курицы вымыть и обсушить салфеткой, нарезать кусочками, перемолоть в кухонном комбайне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Вбить сырые яйца, посолить, перетереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Добавить манку, еще раз все перетереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Влить сметану, массу взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Фарш переложить в смазанные маслом порционные формочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2550,'Выставить на решетку пароварки, влить воду. Время приготовления – двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2551,'Репчатый лук очистить и покрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2551,'Нашинковать белокочанную капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2551,'Морковь натереть или нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2551,'Выложить продукты в блендер вместе с яйцом, солью, молоком, свежей зеленью и перцем. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2551,'Выложить в формы, печь при температуре 180 градусов, время – от двадцати до двадцати пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Филе курицы срезать с кости, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Отварить рис и тоже пропустить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'К продуктам добавить специи и соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Использовать карри и немного молотого перца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Добавить мягкое сливочное масло. Еще раз все перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Сформовать небольшие котлетки, приготовить в пароварке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2552,'Другой вариант – использовать дуршлаг. Время варки – по пятнадцать минут с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2553,'Взбить в блендере клубнику молоко и мороженое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2553,'Перелить в стакан, по желаю украсить взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'В растительное масло добавляем соль, перец чили в хлопьях и копчёную паприку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'Рыбку моем потрошим и удаляем хребет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'Посыпаем рыбку солью, черным молотым перцем, сухим базиликом и добавляем растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'Заворачиваем в виноградный лист и нанизываем на шпажки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'Окунаем нанизанную рыбку в растительное масло с солью, перцем чили и копченой паприкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2554,'Выкладываем на решётку и жарим на углях по 5-7 минут с каждой стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2555,'Белки отделить от желтков и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2555,'Брокколи, кабачки, зелень, лук нарезать и перемолоть в блендере вместе с куриным мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2555,'Добавить желток и молоко, масло и специи, рубленые фисташки, соль. Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2555,'Отдельно взбить в пену белок, добавить к остальным продуктам, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2555,'Готовую массу выложить в небольшие формы и запечь при температуре 180 градусов, время – двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2556,'Желатин залить водой и дать разбухнуть. На это потребуется примерно 10 минут. Разбухший желатин перемешать с молоком и слегка подогреть его.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2556,'Перемешать смесь с сырковой массой, тщательно протереть через мелкое сито или пропустить через мясорубку. После этого добавить в массу разноцветное желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2556,'Смесь завернуть в виде колбасы в пищевую пленку и положить в холодильник на два часа. Десертный творожный сыр с желе готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Свежие неочищенные чесночные зубчики залить водой на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Очистить от шелухи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Продукт обсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Влить в сотейник чистую воду, сахарный песок, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Довести до кипения, влить уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Выложить на дно промытой банки гвоздику, перец и корицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Насыпать чеснок, залить продукт маринадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2557,'Выставить банки на полотенце в воду, кипятить от семи до восьми минут, закрутить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Плотные головки чеснока полить кипятком и очистить от верхней части шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Овощи поместить в стеклянную стерилизованную банку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'В кастрюлю положить морскую соль, сахар, перец-горошек, лавровый лист, влить уксус и воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Лавровый лист лучше покрошить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Смесь поварить на тихом огне пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Залить горячим, но не кипящим маринадом чеснок в банках.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2558,'Закрыть капроновыми крышками, охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Чеснок очистить и промыть, залить кипящей водой на минуту, затем окунуть в ледяную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Острый перец чили нарезать тонкими кольцами, семена удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Перец положить в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Добавить уксус, лавровый лист, соль, специи, сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Влить воду. Поварить маринад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Выложить дольки чеснока в чистую посуду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2559,'Залить маринадом с гущей, остудить под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Головки чеснока с шелухой залить кипящей водой на две или две с половиной минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Жидкость слить, удалить шелуху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Стеклянные банки стерилизовать, заполнить чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Влить воду в кастрюлю, добавить сахар и соль, лавровый лист, уксус и два вида перца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Маринад довести до кипения, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Воду с пряностями вылить в банки на чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Остудить под крышками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Выставить на холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2560,'Закуска будет готова через семьдесят два часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Промыть неочищенный чеснок, разделить головки на зубки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Шелуху не снимать, обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Переложить в чистые банки, влить уксус, разбавленный водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Емкости закрыть крышками, поставить в темное холодное место на семь или восемь дней.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Переложить чеснок в другие банки, залить прокипяченным соевым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Время кипячения – от двенадцати до четырнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2561,'Поставить закуску на хранение в прохладное место.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Снять с чеснока первый слой шелухи, на дольки не делить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Воду довести до кипения, поместить чеснок на три или три с половиной минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Остудить в холодной воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Порезать слайсами сырую свеклу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Выложить на дно чистой банки несколько зонтиков укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Выложить головки чеснока, кусочки свеклы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Чистую воду довести до кипения, растворить в ней каменную соль и сахар, уксус, добавить перец и лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Маринад довести до кипения, немного остудить и залить чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2562,'Закатать металлическими крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Чесночные головки очистить от верхнего слоя шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Облить кипящей водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Продукт выложить на плоскую поверхность, остудить, посыпать крупной солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Выложить в емкость слоями с тархуном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Приготовить смесь из воды с уксусом, сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Перелить в банки. Закрыть крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2563,'Время маринования – от десяти до пятнадцати дней.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Головки чеснока вымыть, очистить от верхнего слоя шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Выложить в эмалированный таз, влить домашний яблочный уксус, очень холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Оставить для маринования на сорок дней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Жидкость слить, головки чеснока промыть проточной водой, выложить в банку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Растворить в слитой жидкости сахар, чесночную соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Довести до кипения, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Залить чеснок маринадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2564,'Подержать под крышкой две недели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Разобрать чеснок на зубчики, ошпарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Соединить соль с сахарным песком, чистой водой, уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Довести до кипения, кипятить две или две с половиной минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Выложить дольки чеснока в стеклянные банки, добавить по среднему стручку перца чили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Залить закуску маринадом и закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2565,'Банки остудить, поставить в прохладу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Очистить лук от шелухи, промыть и высушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Разделить головки чеснока на дольки, обдать поочередно кипятком и ледяной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Шелуху от лука выложить в банки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Приготовить маринад из крупной соли, сахарного песка, перца-горошка, лаврового листа, корицы, чистой воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Время кипения смеси – две с половиной минуты, влить уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2566,'Залить закуску в банках и закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2567,'В кастрюлю с горячей водой положить соль, сахар, влить уксус. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2567,'Стеклянные банки предварительно стерилизовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2567,'Чесночные стрелки уложить плотно, рядами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2567,'На дно – лавровый лист и перец-горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2567,'Влить маринад в банки с нарезанными стрелками, закрутить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2568,'Приготовить фарш с добавлением лука и замоченного в молоке хлебом, поперчить, подсолить, хорошо вымесить, охладить 10 мин холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2568,'Порезать на колечки помидоры, перцы высотой по 1 см и луковицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2568,'Выстлать противень пергаментной бумагой, выложить на нее порционно фарш высотой около сантиметра, промазать кетчупом, выложить лук, промазать майонезом, далее – помидоры, вокруг них – перец, присыпать сырной стружкой, смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2568,'Выпекать ласточкино гнездо с помидорами и болгарским перцем чуть более получаса в прогретой до 180 градусов духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Испечь коржи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Натереть крупно остуженные вареные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Тертую вареную морковь смешать с измельченным чесноком и майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Слегка смазать корж майонезом, поверх уложить размятые консервы (половину).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'На второй корж уложить морковную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Третий промазать майонезом и присыпать яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'На четвертый уложить остаток консервов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Верх и бока закусочного «Наполеона» с рыбными консервами и сыром обмазать творожным сыром, присыпать крошкой из измельченного коржа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2569,'Прикрыть закуску пленкой, положить разделочную доску, а на нее груз, дать постоять в холоде пару часов и можно подавать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2570,'Масло растопить и перемешать со сметаной и разрыхлителем. Медленно всыпать муку. Замесить тесто. Оно не должно прилипать к рукам и должно быть мягким. Тесто разделить на 20 небольших одинаковых по размеру шариков. На полчаса шарики убрать на холод. За это время приготовить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2570,'Банан очистить и размять при помощи вилки. В банановое пюре добавить муку, сахар, творог и ванилин или ванильный сахар. Смесь тщательно перемешать. Тесто достать из холода и каждый из шариков раскатать в виде прямоугольника. В одну половину прямоугольника положить начинку и закрыть второй половиной. Защипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2570,'Придать пирожкам форму бананов. Готовые «бананы» выложить на смазанный маслом противень. Для того, чтобы блюдо не пригорело можно застелить пекарской бумагой. Сверху пирожки намазать взбитым яйцом. Выпекать 25 минут в предварительно разогретой духовке. Готовность сладких пирожков «Бананчики» можно определить по золотистой корочке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2571,'Порезать на полосы курицу, втереть в мясо перец и соль, обжарить их в сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2571,'Уложить курицу в форму, залить остатками масла и смесью молока, сметаны и специй.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2571,'Форму с куриным филе в топленом молоке со сметаной поставить в духовку с температурой порядка 200 градусов, примерно через треть часа блюдо будет готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Залить дрожжи чуть подогретым молоком, разболтать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Через 10 минут всыпать сахар, добавить масло, ванилин, яйцо и белок от второго, подсолить, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Порциями всыпать просеянную муку, вымесить тесто, убрать его для созревания на час в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Увеличенное в объеме тесто обмять, повторить процедуру через час еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Разделить его пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Раскатать два прямоугольника, надрезать под 45 градусов у каждого края 8-10 раз, центр присыпать крахмалом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'На одну заготовку выложить клюквенный джем, а на другую – лимонный, слегка присыпать опять крахмалом, полоски переплести, чтобы получилась косичка, смазать взболтанным желтком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2572,'Выпекать плетенки около получаса при температуре 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'Куриное филе вымыть обсушить и нарезать небольшими кусочками.','https://vkuso.ru/data/cache/data/1f/f196c5ed3a0901f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'Нарезанное филе переложите в глубокую посуду, посолите, поперчите по вкусу, добавьте 3 ст.л. крахмала. Перемешайте.','https://vkuso.ru/data/cache/data/15/4bcd1f12df18915_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'В сковороде разогрейте растительное масло, выложите кусочки курицы и обжарьте со всех сторон на сильном огне около 10 минут.','https://vkuso.ru/data/cache/data/ad/95c3fb828197bad_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'Уберите курицу со сковороды.','https://vkuso.ru/data/cache/data/1c/2af3b428abfdc1c_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'В ту же сковороду, где жарилась курица, влейте соевый соус, уксус, кетчуп, сахар, измельченный чеснок. Доведите до кипения на слабом огне.','https://vkuso.ru/data/cache/data/54/ba6e95268b04754_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'1 ст.л. крахмала развести в стакане холодной воды.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'Верните курицу в сковороду, перемешайте. Тушите на медленном огне около 10 минут.','https://vkuso.ru/data/cache/data/34/8262a1293cf2134_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2573,'Получилось очень вкусно! Приятного аппетита!','https://vkuso.ru/data/cache/data/d0/d0b34ef483c72d0_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'В глубокую кастрюлю наливаем воду и доводим ее до кипения. В кипящую воду аккуратно опускаем лапшу и варим до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Дальше отбрасываем макароны на дуршлаг и подставляем под проточную прохладную воду. Оставляем лапшу на некоторое время в дуршлаге, а затем перекладываем в салатницу и добавляем растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Шампиньоны, лисички и сыроежки промываем, обсушиваем, чистим и мелко нарезаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Чистим чеснок, выживаем его сквозь чесночницу и добавляем в смесь разогретого на сковороде масла сливочного и масла растительного. В этой смеси и обжариваем грибы до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Сваренные вкрутую куриные яйца очищаем от скорлупы и мелко нарезаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Листья салата промываем под проточной водой, обсушиваем и мелко рубим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'Из масла оливкового, специй, уксуса виноградного готовим заправку, тщательно смешивая все эти компоненты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2574,'В глубокую салатницу выкладываем измельченные яйца и салат, затем грибы с лапшой. Заливаем ингредиенты соусом. Минут на 20 ставим салат «Екатерина» в холодное место, а перед тем, как отправить блюдо на стол, еще раз перемешиваем его.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2575,'Прогреть до 220 духовку, в смазанную маслом небольшую форму уложить разрезанные вдоль бананы, присыпать цедрой лимона, полить лимонным соком, присыпать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2575,'Через 10 минут вкуснейший десерт будет готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2575,'Уложить на тарелку дольки банана, на него – мороженое, присыпать крошкой из печенья, полить соком лимона, посыпать шоколадной стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2576,'Порезать курицу, уложить в форму, присолить, прикрыть колечками помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2576,'Далее выложить слой грибов, присолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2576,'Всыпать в сметану сырную крошку, вбить яйца, подсолить, хорошо перемешать, залить курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2576,'Запечь куриную запеканку с грибами, помидорами и сыром в течение 40 минут в духовке с температурой около 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2576,'Дать чуть остыть, порезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Всыпать манку в сметану, тщательно перемешать, дать полчаса постоять и набухнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Взбить сахар, яйца с солью и ванилином, соединить с манкой, добавить масло, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Всыпать в тесто какао-порошок, муку, корицу и разрыхлитель, взбить до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Заполнить тестом форму, присыпать измельченной халвой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Поставить шоколадный манник на сметане с халвой примерно на полчаса в прогретую до 180 градусов духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2577,'Дать выпечке чуть остыть, вынуть из формы, порезать на кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Картофель и куриные яйца отварить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'То и другое нарезать кубиками вместе с маринованным и свежим огурцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Продукты выложить в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Слабосоленое филе семги нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Добавить зеленый горошек и рубленую петрушку, репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Соль и перец – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Для приготовления соуса смешать нежирную сметану с красной икрой, заправить салат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2578,'Украсить блюдо рукколой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Морковь очистить и крупно нарезать, измельчить с помощью блендера в «крупу».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Вымыть и натереть яблоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'В глубокой емкости перемешать просеянную цельнозерновую муку вместе с пищевой содой и корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Добавить йогурт или яблочный сок, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Добавить мёд, морковь, яблочное пюре, отруби, перемешать, накрыть тканью и оставить на 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'В тесто влить растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Формочки также смазать маслом или использовать силиконовые.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2579,'Выложить тесто, посыпать овсяными хлопьями, печь в течение 45 – 50 минут при температуре 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2580,'Пшеничные отруби перемолоть в муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2580,'Смешать нежирный творог, отруби, сырые куриные желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2580,'Влить в полученную смесь молоко, добавить по вкусу какао-порошок, сахарозаменитель, ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2580,'Сформовать пирожные, поставить в холодильник на час или два.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2581,'Вскипятить воду, добавить соль, положить репчатый лук целиком. Готовить 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2581,'Добавить картофель, нарезанную морковь, лавровый лист, зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2581,'Всыпать предварительно промытую гречневую крупу, положить кусочек сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2581,'Варить суп до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2582,'Творог протереть или размять вилкой и смешать с сахаром и мягким сливочным маслом. Спелый банан очистить, выложить на тарелку и намазать творожной массой с трех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2582,'Отдельно растопить в кастрюле сахар с какао-порошком и сметаной. Горячей массой полить банан в твороге. Остудить и нарезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Яблоки вымыть и испечь целиком или предварительно разрезать на части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Протереть мякоть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'В пюре добавить сахарный песок, варить до загустения, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Охладить белки, взбить, соединить с пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Отдельно развести желатин так, как написано на пакете.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Соединить с яблочной массой, добавить сок лимона, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Выложить в порционную посуду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2583,'Охладить десерт в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2584,'Положить в блендер овсяные хлопья, банан, грушу или яблоко, влить молоко, мёд, оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2584,'Должно получиться жидкое тесто, дать ему постоять в течение 15 минут для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2584,'Затем выпечь оладушки без масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Свежий хлеб нарезать кубиками, поставить в разогретую духовку, подсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Сухарики не должны пригореть, их нужно периодически перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Полученный продукт перемолоть в муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'То же самое проделать с сухофруктами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'То и другое перемешать с мёдом, полученную смесь выложить в форму, предварительно смазанную маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Нарезать яблоко и банан тонкими ломтиками, выложить поверх коржа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Отдельно замочить желатин в воде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Дать набухнуть, затем прогреть, до кипения не доводить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Дополнительный банан растереть, вмешать творог, добавить молотую корицу и молоко.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Сахарный песок можно не добавлять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Влить остывший желатин, перемешать, вылить смесь в форму.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Сверху положить кружочки банана или любого другого фрукта.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2585,'Поставить десерт в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2586,'Отварить рис, добавить молоко, поварить еще пять-семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2586,'Перемолоть кашу в блендере вместе с бананом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2586,'По желанию добавить изюм или корицу, кокосовую стружку, какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2586,'Выложить смесь в прозрачный стакан, сверху полить йогуртом, украсить кружочками бананов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Тонкий армянский лаваш намазать тонким слоем сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Сверху выложить второй лист, также намазать сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Накрыть третьим слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Для приготовления начинки протереть творог через сито, пропустить через пресс чеснок, смешать с творогом, добавить рубленую зелень укропа, нарезанные маслины, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Рулет свернуть, завернуть в пищевую пленку, поставить на два часа в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2587,'Нарезать наискосок на кусочки острым ножом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2588,'Для приготовления блюда сырые куриные яйца взбить с сахарным песком, добавить творог, сметану, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2588,'Очистить яблоки и морковь, натереть то и другое на терке или перемолоть с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2588,'Все ингредиенты соединить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2588,'Форму для выпекания или приготовления на пару смазать растительным маслом, можно положить лист фольги.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2588,'Выложить массу, печь в течение 40 минут или до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Разогреть оливковое масло в большой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Измельчить чеснок и добавить красный перец, жарить три-пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Очистить креветки, положить в кастрюлю вместе с солью и перцем, варить до тех пор, пока они не станут розовыми, на это потребуется две-три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Морепродукт вынуть и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Добавить в чесночную обжарку белое сухое вино, лимонный сок, довести смесь до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Добавить сливочное масло и еще немного оливкового.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Прогреть, переложить креветки, добавить рубленую петрушку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2589,'Смесь перемешать, посолить и поперчить. Сразу же подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Нагреть молоко в кастрюле, положить разрезанный вдоль стручок ванили, позже его нужно будет вынуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Банан превратить в пюре с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Прогреть молоко, добавить банановую массу, продолжать нагревать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Поломать горький шоколад, выложить его в кастрюлю с напитком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Массу перемешать, шоколад должен полностью раствориться, смесь – стать однородной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2590,'Коктейль снять с огня, разлить в чашки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Для приготовления маринада мелко нарезать чеснок, добавить его в кефир, посолить, положить травы и перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Куриные бедрышки замариновать в полученной смеси на 25 – 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Очистить картофель, нарезать дольками, выложить в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Добавить соль, перец, травы, оливковое масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Зубчики чеснока очистить, раздавить ребром ножа, выложить на картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Помидоры разрезать на четыре части, выложить в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Сверху выложить курицу, залить остатками маринада.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2591,'Печь в духовке в течение 40 минут при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Желатин замочить в горячей воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Вишню или другие ягоды, фрукты разморозить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Набухший желатин смешать с молоком, довести до кипения на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Отдельно перемешать обезжиренный творог, желатиновую массу, натуральный мёд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Выложить на дно формы ягоды и фрукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2592,'Получившуюся смесь залить в форму, поставить в холод на три-четыре часа или на всю ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Подготавливаем куриные бедра, моем обсушиваем. По желанию можно чуть отрывать кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Потом отбить, сделать чуть тоньше куриные бедра. (Лично я отбил в конце приготовления)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Перекладываем в глубокую миску, солим перчим и добавляем приправу для курицы, перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Добавляем майонез (сметану) и снова перемешиваем. Убираем в сторону на 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Болгарский перец нарезаем кубиком, перекладываем в миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Сыр натираем на мелкой терке, перекладываем в миску, где помидор и болгарский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'Затем добавляем сметану перемешиваем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2593,'На отбитые куриные бедра укладываем начинку и заворачиваем в рулет. Скрепляем зубочисткой. Перекладываем на противень, отправляем в разогретую духовку до готовности. У меня куриные рулетики запекались около 1 часа 40 минут. Чтобы была более румяная корочка, можно рулетики полить «бульоном» который появился во время запекания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Зелень укропа, помидор и красный болгарский перец измельчить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Куриное мясо пропустить через мясорубку, можно взять готовый продукт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Все ингредиенты смешать, добавить сырое яйцо, сливочное масло, приправы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Массу хорошо перемешать, сформовать небольшие котлеты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Варить на пару в течение 20 – 25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Для приготовления соуса порубить зелень петрушки и укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Растопить сливочное масло, добавить зелень, приправы, лимонный сок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2594,'Снять смесь с огня, подать к котлетам.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2595,'Креветки и яйцо отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2595,'Замороженный горошек залить кипятком, оставить на две-три минуты, жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2595,'Нарезать кусочками креветки, яйцо, мякоть авокадо, сладкий болгарский перец зеленого цвета, помидор, лук-шалот или обычный зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2595,'Заправить салат йогуртом, добавить подходящие специи для салатов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2595,'Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2596,'Нарезать кубиками куриную грудку, брынзу, вареные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2596,'Измельчить в крошку очищенные грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2596,'Замочить в кипятке чернослив, дать набухнуть, удалить косточки, плоды мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2596,'Все составляющие перемешать и заправить сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2597,'Взбить сырые куриные яйца с сахарным песком. Продолжать взбивать, добавить муку, крахмал, разрыхлитель и какао-порошок. Массу выпечь в духовке в течение получаса при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2597,'Взбить жирные сливки с сахаром. Добавить мягкий протертый творог. Замочить желатин из пакетика в холодной воде на 15 минут, довести до кипения, процедить. Добавить в творожную массу и взбить миксером на небольшой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2597,'Собрать торт «Фруктовый взрыв»: выложить готовый корж в разъемную форму, влить полученную начинку. Блюдо поставить в холодильник на 3 – 4 часа. При готовности украсить любыми фруктами: клубникой, виноградом, мякотью апельсина или мандарина, очищенными и нарезанными киви, вишней, ежевикой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2598,'Овсяные хлопья измельчить в блендере, добавить размятый нежирный творог, кефир, сырые яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2598,'Вмешать чернику в тесто, можно взять свежие или замороженные ягоды, оставить на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2598,'Оладьи жарить на разогретой сковороде с антипригарным покрытием, по три минуты с каждой стороны, огонь – средний.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2598,'Отдельно смешать мёд с йогуртом, подать к оладьям в качестве соуса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Банки стерилизовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'На дно положить перец-горошек и лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Уложить стрелки чеснока с зеленью, плотно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Залить кипятком, дать постоять несколько минут, затем слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Всыпать в жидкость соль и сахар, влить уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Залить стрелки и закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2599,'Основной продукт можно перемежать с петрушкой или укропом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2600,'В стерильные банки выложить лавровый лист, перец-горошек, корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2600,'Плотно набить банку стрелками чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2600,'Влить кипящую воду, дать постоять, слить в емкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2600,'Добавить сахарный песок, соль, немного уксуса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2600,'Вновь залить стрелки, закатать металлическими крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2601,'Стерилизовать банки, выложить стрелки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2601,'Залить кипятком, затем жидкость слить и приготовить маринад на ее основе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2601,'Всыпать соль и сахар, влить уксус, добавить зерна горчицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2601,'Залить заготовки, закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Клубнику вымыть, удалить хвостики и измельчить в блендере до однородности.','https://vkuso.ru/data/cache/data/4d/c20167e492be54d_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Охлажденные сливки влить в глубокую посуду и взбить миксером в густую массу.','https://vkuso.ru/data/cache/data/25/fb9a1efb5dbf925_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Продолжая взбивать, влить сгущенное молоко. Сгущенное молоко добавляется для сладости, поэтому его количество может быть чуть больше или меньше, по вашему вкусу.','https://vkuso.ru/data/cache/data/5c/111999872c6ac5c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Добавить клубничное пюре. Взбить миксером до однородной консистенции.','https://vkuso.ru/data/cache/data/40/a0ad885e1f97240_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Массу перелить в форму.','https://vkuso.ru/data/cache/data/96/9a75fe26f1b1f96_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Закрыть пленкой в контакт и убрать в морозилку до полного застывания.','https://vkuso.ru/data/cache/data/ff/74b260b0a0aeaff_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2602,'Очень вкусное клубничное мороженое готово. Приятного аппетита!','https://vkuso.ru/data/cache/data/d6/ef20f6046e715d6_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Стрелки чеснока измельчить, обжарить на раскаленном растительном масле до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Огонь убавить, добавить сахарный песок и соль, яблочный уксус, приправу для моркови по-корейски, соевый соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Обжарить до густоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Газ выключить, смесь остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Перемешать с рублеными зубчиками чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2603,'Переложить готовую смесь в заранее простерилизованную банку и поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2604,'Стрелки чеснока вымыть, нарезать, опустить в кипяток на пять минут, откинуть на дуршлаг и уложить в стеклянные банки плотными рядами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2604,'Перемешать яблочный сок для заливки с сахаром и солью, довести до кипения, залить чесночные стрелки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2604,'Закатать, банки перевернуть, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Морковь и лук очистить, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Репчатый лук нарезать мелкими кубиками, морковь натереть, зеленое перо порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Слить сок от консервированного тунца в банке, рыбу размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Продукты соединить, добавить пропущенный через пресс чеснок, куриные яйца, карри и паприку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Фарш вымешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Сформовать котлеты овальной формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Поджарить на оливковом масле, должна получиться румяная корочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Изделия перевернуть и довести до готовности под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2605,'Выложить на бумажную салфетку или на решетку для удаления излишков жира.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Открыть банку с консервированной сайрой, слить жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Рыбу размять вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Приготовить пюре с помощью блендера из репчатого лука и чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Перемешать, вбить яйцо, посолить, добавить специи, манную крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Накрыть емкость крышкой, дать массе постоять около получаса для набухания крупы. Готовый фарш должен быть густым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Руки смочить в воде, сформовать котлеты, обвалять в панировочных сухарях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Обжарить на растительном масле, огонь – средний, время – по три минуты с каждой стороны',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2606,'Выложить на бумажные салфетки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Промыть рис до прозрачного состояния жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Отварить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Слить жидкость от консервов, рыбу размять вилкой, крупные кости удалить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Нарубить репчатый лук и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Все перемешать, добавить остывший рис, яйцо и специи, муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Сформовать котлеты, посыпать сухарями, выложить на смазанный маслом противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Печь при температуре 200 градусов. Время приготовления – 15 минут, посыпать тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2607,'Поставить в духовку еще на десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2608,'Баклажан нарезать кубиками, посыпать солью и оставить на полчаса для удаления излишней горечи. Затем слить выделившийся сок, промыть кусочки под проточной водой и обсушить бумажным полотенцем. Нарезать мелко репчатый лук. Обжарить баклажан с небольшим количеством оливкового масла вместе с луком до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2608,'Куриную грудку отделить от костей, нарезать кубиками и обжарить на небольшом количестве растительного масла, добавить зубчик рубленого или пропущенного через пресс чеснока. Жарить до образования золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2608,'Нарезать кубиками помидоры и мягкий сыр. Все ингредиенты перемешать, полить оливковым маслом с добавлением лимонного сока и прованских трав, любых других сухих специй. Дать салату-закуске из курицы, баклажанов и помидор постоять два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2609,'Горох замочить в холодной воде на 10 минут, затем хорошо его промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2609,'Картофель нарезать кубиками, лук мелко нарезать, морковь натереть на мелкой терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2609,'Установить режим "жарка"/"выпечка". (если готовите в кастрюле, то поставьте кастрюлю на сильный огонь)
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2609,'Добавить лук, жарить 2 минуты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2609,'Закрыть крышку, установить режим "суп" 1 час 40 мин. (или накрыть кастрюлю крышкой и варить на среднем огне).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Окуня промыть, срезать хвосты и плавники, выпотрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Тушки положить в морозильную камеру или окунуть в кипяток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Очистить, удалить хребет и кости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Филе пропустить через мясорубку вместе со свиным салом, хлебом и луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Добавить сырое яйцо, перец молотый черный, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Фарш вымесить. Сформовать котлеты, обвалять в сухарях, обжарить на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2610,'Перевернуть. Довести до готовности под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Готовое филе окуня пропустить через мясорубку вместе с репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Белый батон залить молоком, через десять минут отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Размять массу вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Ввести яйцо, соль, черный перец и давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Фарш вымесить, сформовать котлеты одного размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Противень застелить пергаментом, смазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2611,'Запечь изделия в течение сорока минут, температура приготовления – 150 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'Репчатый лук очистить и перемолоть в блендере в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'Так же поступить с морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'Залить панировочные сухари горячей водой, размять вместе с творогом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'Все продукты смешать с куриным фаршем, специями, яйцами, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'На противень положить силиконовый коврик, расположить котлеты из курицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2612,'Время запекания в духовке – около получаса, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2613,'Разморозить брокколи под струей холодной воды, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2613,'Размять вилкой творог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2613,'Перемешать продукты с куриным фаршем, вбить сырое яйцо, давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2613,'Поперчить, посолить, сформовать котлеты, готовить в пароварке полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Творог размять с сырым яйцом и солью по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Разморозить рыбный фарш, ввести в творог вместе с измельченной блендером луковицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Нарезать зелень укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Все вместе вымешивать десять минут, накрыть пленкой, поставить в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Противень застелить пекарской бумагой, духовку прогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Из готового охлажденного фарша сформовать котлеты удлиненной формы, окунуть во взбитое яйцо, выложить на лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Время запекания – полчаса, изделия не должны подгореть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2614,'Если фарш получился жидковатым – в него можно добавить манную крупу и дать постоять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Подготавливаем куриные бедра, подрезаем и т.д.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Затем отбиваем их.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Солим, перчим и посыпаем приправой для курицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'В отдельной тарелке делаем маринад, из соевого соуса, мёда и горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Этим маринадом заливаем куриные бедра и перемешиваем. Убираем в строну.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Яблоки чистим от кожицы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Затем яблоки нарезаем маленьким кубиком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2615,'Берем куриное бедро, на него укладываем нарезанное кубиком яблоко и заворачиваем в рулетик, скрепляем зубочисткой. Перекладываем на противень, и отправляем у духовку при 180°С, до готовности. У меня в духовке приготовились примерно за минут 40.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Репчатый лук очистить и мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Помять руками, добавить в куриный фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Вбить сырое куриное яйцо, всыпать манку и влить сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Посолить, ввести специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Массу вымесить, отбить о дно чаши.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Накрыть пленкой, поставить в холод на пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Сформовать котлеты, жарить на раскаленной сковороде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'После получения корочки изделия переложить на тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'На сковороде, на том же масле, обжарить еще одну рубленую луковицу и тертую морковь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Перемешать не темную томатную пасту с теплой водой и мукой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Вместо воды можно добавить бульон.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Залить овощи на сковороде, довести до кипения, посолить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Лавровый лист добавить по желанию.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2616,'Выложить в соус котлеты, потушить на тихом огне десять минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Белый хлеб залить подогретым молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Отжать через пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Перемолоть в блендере вместе с репчатым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Добавить яйцо, специи, соль, смешанный фарш из свинины и говядины. Вымешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Сформовать изделия овальной формы среднего размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Обвалять в панировочных сухарях, выложить на смазанный маслом противень с высокими бортиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Время запекания – пятнадцать минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Спассеровать на сковороде вторую луковицу, покрошенную мелкими кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Добавить тертую морковь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Отдельно перемешать томатную пасту со сметаной, добавить воду по необходимости.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Смесью залить овощи, добавить бульон, кипятить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Соль и пряности – по вкусу.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Вынуть котлеты из духовки, полить соусом с овощами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2617,'Запекать в духовке еще пятнадцать минут, температуру убавить до 170 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Ломтик хлеба замочить в сливках на десять минут, отжать жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Пропустить через мясорубку вместе с рыбным филе и репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Добавить по вкусу соль, сырое куриное яйцо, молотый черный перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Вымешать фарш, слепить котлеты мокрыми руками, обвалять изделия в манке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Жарить с двух сторон на растительном масле, на сильном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Изделия переложить на тарелку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'На той же сковороде спассеровать репчатый лук со сладким болгарским перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Продукты нарезать мелкими кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Надрезать помидоры, ошпарить, снять кожицу, мякоть порубить и добавить в обжарку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Потушить все вместе до загустения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Прогреть муку до золотистого цвета на сковороде без масла, добавить в овощи вместе с бульоном.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2618,'Выложить в подливу котлеты, потушить до готовности.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Грудки подморозить, нарезать пластинками, а затем полосками поперек волокон по два сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Порубить мелко лук и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Добавить сырое куриное яйцо, крахмал и сметану, соль и молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Фарш вымешать, отбить руками о дно чашки или об стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Оставить для пропитывания на пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Нарезать белый батон такими же кусочками, как и мясо, подсушить в духовом шкафу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Часть сухарей размолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Соединить с кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Сформовать котлеты, обвалять в полученной панировке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2619,'Жарить на растительном масле на среднем огне до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Свинину без жира хорошо промыть, обсушить и порезать тонкими полосками, а затем поперек, по два сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Перемолоть репчатый лук в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Добавить крахмал и яйца, соль, специи – по вкусу и желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Оставить в прохладе на двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Обвалять рубленые котлеты в панировке из сухарей, жарить на сильном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'При получении корочки изделия перевернуть и тушить под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Пламя уменьшить, довести котлеты до полной готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2620,'Крахмал можно заменить на муку, но это будет уже другое блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2621,'Натереть на крупной терке очищенный от кожицы и семян кабачок. Добавить сырые яйца, просеянную пшеничную муку, зелень и любые специи.  Массу обжарить на сковороде с двух сторон, чтобы получилась нетолстая лепешка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2621,'Для начинки: обжарить нарезанные шампиньоны, мясной фарш, репчатый лук, соль, перец молотый – по вкусу. Начинку выложить на остывшую кабачковую лепешку, посыпать тертым сыром, свернуть в рулет. При подаче рулет «Спортсменка» нарезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Удалить пленки и прожилки с куска мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Нарезать продукт полосками или кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Перемешать с солью, яйцами, нарезанным репчатым луком и майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Всыпать крахмал, хорошо перемешать, дать постоять пятнадцать минут в прохладном месте.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Сформовать котлеты, обвалять в панировке, выложить на сковороду, прогретую с растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2622,'Обжарить до появления корочки с двух сторон, огонь – средний.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'В кастрюлю влить воду, растительное масло и уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Всыпать специи, соль, сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Добавить лавровый лист, дольки очищенного чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Продукты перемешать, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Грибы промыть, крупные экземпляры разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Удалить почерневшие места, выложить в кастрюлю с горячим маринадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'При появлении пузырей маринад с грибами перемешать, варить на тихом огне восемь минут, пенку снимать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2623,'Огонь погасить, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Вымыть шампиньоны, удалить испорченные места, отварить в подсоленной воде в течение пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Грибы откинуть на дуршлаг, дать стечь жидкости, придавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Очистить и нарезать овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Болгарский сладкий перец покрошить соломкой, репчатый лук – полукольцами, морковь натереть на терке по-корейски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Очистить дольки чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Смесь припустить на слабом огне, на масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Влить грибной бульон, добавить соевый соус и специи, яблочный уксус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Перемешать, залить шампиньоны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2624,'Остудить на нижней полке холодильника в течение ночи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Приготовить маринад из лимонного сока, жидкого меда, растительного масла без аромата, соевого соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Продукты перемешать при помощи венчика или вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Промыть крылышки проточной водой, удалить перья и остатки кожи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Откинуть на дуршлаг, переложить в миску, полить готовым маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Оставить для пропитывания на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Прогреть духовку до 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Застелить противень ковриком для выпекания или пергаментом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2625,'Выложить крылышки, посыпать молотым острым перцем, время запекания – полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Куриные крылышки промыть, обсушить бумажными салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Выставить программу «Выпечка» на сорок минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'В чаше мультиварки прогреть растительное масло, обжарить крылышки по пять – семь минут со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Посолить по вкусу, жарить еще две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Кислое яблоко вымыть, обсушить, нарезать тонкими слайсами, сердцевину удалить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Добавить фрукт к куриному мясу, смешать, оставить прогревать до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Приготовить маринад из меда, горчицы, соевого соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2626,'Выставить программу «Плов», залить основную массу маринадом, тушить пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Крылышки промыть, очистить от остатков перьев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Разделить по суставам острым ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Прогреть растительное масло в сотейнике или на глубокой сковороде, обжарить основной продукт до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Приготовить соус из лимонного сока, соевого соуса, специй для курицы, соли, томатного соуса или «Кетчупа», чеснока, меда.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Залить прожаренное мясо, довести до кипения, томить десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2627,'Соус должен немного загустеть, огонь погасить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2628,'Приготовить маринад из белого сухого вина, соевого соуса, жидкого натурального меда, растительного масла и измельченного чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2628,'Вымыть крылышки, очистить, разрезать на кусочки по суставам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2628,'Влить маринад, перемешать, оставить для пропитывания на три или четыре часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2628,'Переложить продукт вместе с жидкостью в рукав, сверху – картофель, соль – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2628,'Выложить перевязанный рукав в форму для выпекания, тушить сорок минут, температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2629,'Промыть куриные крылышки, нарезать кусочками, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2629,'Перемешать паприку с нарезанным острым перцем без семян, имбирем, розмарином, сушеным чесноком, мускатным орехом, кориандром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2629,'Добавить соевый соус, поломанный лавровый лист, черный перец-горошек, гвоздику, соль, жидкий мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2629,'Подержать крылышки в соусе полчаса или час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2629,'Выложить продукт на сетку, запекать на углях, поворачивать каждые две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2630,'Куриные крылышки промыть и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2630,'Перемешать с соевым соусом и медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2630,'Вложить в чашу мультиварки вместе с маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2630,'Выставить режим «Выпечка» или «Гриль» на пятнадцать или семнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2631,'Крылья вымыть, обсушить, нарезать по суставам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2631,'Приготовить маринад из меда, соевого соуса, аджики, соуса «Кетчуп» и тертого или пропущенного через пресс чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Заправку охладить и поставить в холод.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2631,'Залить куриные крылышки, поставить в холод для пропитывания на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2631,'Время запекания в аэрогриле – по пятнадцать минут с каждой стороны, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2632,'Приготовить маринад из меда, лимонного сока, соевого соуса, французской горчицы в зернах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2632,'Добавить давленый чеснок, рубленую свежую зелень, соль, специи для куриного мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2632,'Промыть крылышки, отцедить жидкость, залить маринадом на три или четыре часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2632,'Время запекания – полчаса, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2633,'Очистить чеснок, попустить через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2633,'Добавить измельченный имбирь, мирин, мед, соевый соус, кукурузный крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2633,'Перемешать, дать маринаду постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2633,'Промыть куриные крылья, положить в форму для запекания, залить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2633,'Время запекания – сорок пять минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2634,'Взбить сливки с сахаром и ванилином. Сыпучие ингредиенты добавлять постепенно, порциями. Печенье обмакивать в свежий, заваренный, кофе, выложить на дно формы плотным слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2634,'Часть выпечки поломать, чтобы заполнить кусочками все пустоты. Залить взбитыми сливками. Снова выложить слой печенья с кофе. Тирамису дать постоять в холодильнике несколько часов для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Куриные крылышки промыть, обсушить салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Лук-шалот очистить и нарезать тонкими кольцами, выложить в форму, сверху – крылышки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Перемешать соевый соус с нарезанным чесноком, солью, перцем-чили, кунжутным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Залить крылышки с луком, дать постоять сорок пять минут или час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Время запекания – тридцать пять минут, температура – 210 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2635,'Посыпать кунжутным семенем незадолго до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Перебрать свежие или мороженые ягоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Выложить в сотейник, залить водой, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Добавить коричневый или белый сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Отдельно в холодной воде развести крахмал.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Влить тонкой струйкой к закипающей клюкве.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Уваривать три минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Клюкву тушить на тихом огне. Плиту выключить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Соус немного остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Превратить его в однородную массу при помощи погружного блендера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Дать постоять при комнатной температуре, поставить в холод на полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2636,'Подавать заправку охлажденной, она должна быть густой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Красный лук нарезать тонкими полукольцами, обжарить на растительном масле до прозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Добавить кубики зеленого кислого яблока без кожуры, рубленый чеснок, тертый имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Тушить все вместе под крышкой на тихом огне пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Добавить коньяк.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Уварить соус на половину объема, добавить мороженую или свежую клюкву.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Заправку развести водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Поварить пять минут, сахарный песок и соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2637,'Охладить смесь при комнатной температуре, поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Клюкву и бруснику перебрать, промыть, выложить в емкость для блендера, перемолоть с обычным белым или тростниковым сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Выложить соус в кастрюлю небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Добавить давленый чеснок, соль и мускатный орех.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Прогревать на тихом огне при постоянном помешивании, сахар должен раствориться. До кипения не доводить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Снять с плиты, остудить, поставить в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2638,'Подать к мясу в холодном виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Для приготовления соуса понадобится сотейник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'В емкость выложить клюкву, перебранную и промытую.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Добавить тертую цедру ½ апельсина, тертый имбирь, сахарный песок. Соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Довести массу до кипения, варить три минуты на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Добавить сок от целого апельсина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2639,'Кипятить две минуты, огонь погасить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'Прогреть на сковороде сливочное масло, обжарить рубленый репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'Вымыть апельсин, снять цедру теркой, отжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'В сотейнике перемешать клюкву, сок и цедру апельсина, лук со сливочным маслом со сковороды, немного меда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'Тушить соус на тихом огне пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'Снять с плиты, поперчить, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2640,'Массу протереть через сито. Заправка должна быть однородной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2641,'В сотейник с высокими бортиками сложить цедру апельсина, клюкву, сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2641,'Добавить молотый черный перец, мускатный орех, имбирь, розмарин. Посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2641,'Добавить воду и апельсиновый сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2641,'Смесь довести до кипения на сильном огне, тушить на среднем огне десять или пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2641,'Почти готовый соус взбить погружным блендером, протереть через сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'Красный апельсин порезать кубиками вместе с кожурой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'Добавить нарезанный перец чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'В сотейник выложить сахар, залить водой, прогреть до карамелизации.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'Выложить апельсин с перцем чили, клюкву.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'Добавить лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2642,'Потомить массу на тихом огне двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Выложить в посуду с антипригарным покрытием свежую клюкву и нарезанный репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Влить воду, тушить на тихом огне до тех пор, пока ягоды не полопаются.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Размолоть погружным блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Поставить на огонь добавить сахарный песок, чесночный порошок, соль, молотую корицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Уварить на среднем огне до половины объема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2643,'Добавить уксус, перемешать и дать покипеть еще несколько минут. Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Порезать батон, обжарить в тостере или на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Печень трески помять ложкой, потереть яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Смешать с майонезом, измельченным укропом и сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Намазать порезанный батон чесноком (можно этого не делать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Положить начинку на кусочки батона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2644,'Посыпать закусочные бутерброды порезанным зеленым луком и укропом непосредственно перед подачей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'Порезать хлеб на тоненькие кусочки в виде каких-либо фигур: звездочек, ромбиков, сердечек и так далее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'Намазать краешки и верх хлеба сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'Бока ломтиков обмакнуть в измельченный укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'Положить на каждый кусочек слой икры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'Украсить бутерброды листиком петрушки и кусочком лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2645,'По бокам сделать узор из подтаявшего сливочного масла, используя кулинарный шприц.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Снять кожу с красной рыбы и удалить кости, порезать на тоненькие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Порезать батон на ломтики, все ломтики еще на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Разложить на батоне по кусочку красной рыбы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Сделать надрезы не до конца, чтобы было похоже на крылья божьей коровки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Разрезать маслину, сделать из нее голову божьей коровке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Из мелко порезанных маслин сделать пятнышки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2646,'Уложить заготовку на рыбку, украсить необычный бутерброд листиком петрушки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Порезать белый хлеб для тостов на тоненькие кубики 5 на 5 сантиметров, чуть-чуть поджарить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Сделать первый слой: натереть сыр, раздавить чеснок, соединить все с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Присыпать измельченным салатом и укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Сделать второй слой: помыть помидоры черри, срезать краешек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Сделать на помидоре продольный надрез. Это будут крылья.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Из разрезанной маслины сделать голову.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Майонезом нарисовать глаза или выложить зернами кунжута.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Выложить на спине точечки, вырезанные из оливок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2647,'Положить все на бутерброд, присыпать измельченным укропом, украсить листиком петрушки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Избавить сельдь от косточек, кожицы и внутренностей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Сварить морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Пропустить морковь, масло, сельдь, сырки через мясорубку. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Хранить можно 5 суток в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Паштет можно намазать на булочку, хлеб, печенный или отварной картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Можно фаршировать помидоры, яйца и так далее.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2648,'Каждый откусивший бутерброд скажет, что он с красной икрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2649,'Развести дрожжи в воде, добавить майонез, соль и сахарный песок. Муку всыпать постепенно, порциями, должно поучиться мягкое, эластичное тесто. Накрыть его тканью и оставить на полтора часа. За время выстойки универсальное тесто на майонезе нужно два раза обмять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2650,'В чашу блендера выложить банан, добавить грецкий орех, семена чиа, чернику и молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2650,'Взбить. По желанию можете добавить 1-2 ч.л. меда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Порезать багет на 8 кусочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Нагреть сковороду с оливковым маслом, пожарить хлеб, посыпать перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Соединить в емкости майонез, соус Сальса, чили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Намазать кусочки багета смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Потереть сыр, присыпать бутерброды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Обжарить бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Разрезать бекон пополам, положить на кусочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Сыр чуть-чуть расплавится.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'Положить сверху рукколу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2651,'На итальянские кростини выложить порезанные томаты с кинзой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Порезать хлеб на средние кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Порезать колбасу, маринованные огурцы на маленькие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Почистить болгарский перец от семечек, порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Мелко порезать зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Подготовленные продукты положить в посуду, вбить яйца, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Намазать противень маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Намазать белый хлеб майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Выложить на хлеб начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Потереть сыр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Посыпать бутерброды, запекать 5-7 минут, соблюдать температуру 190 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2652,'Должна получиться золотистая корочка из сыра.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Разрезать поперек багет, положить на лист, отправить на несколько минут в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Нагреть на сковороде масло, пожарить измельченный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Положить грибы, готовить 5 минут, посыпав перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Положить на подготовленный багет грибы, положить на него два кусочка сыра моцарелла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Можно отправить бутерброды в микроволновку, чтобы сыр расплавился.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2653,'Присыпать приправами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2654,'Порезать хлеб, намазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2654,'Нанести мясной фарш (заправленный перцем и солью).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2654,'Мелко потереть чеснок, соединить с майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2654,'Намазать полученную смесь на фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2654,'Положить бутерброды на противень, отправить в духовку на 10-15 минут, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2655,'Порезать хлеб, намазать все куски майонезом, положить ветчину, по дольке помидора, накрыть тоненькой пластинкой сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2655,'Готовить в духовке, пока н расплавится сыр (несколько минут).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2655,'Подавать бутерброд с ветчиной на большой тарелке, уложив на салатные листья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2656,'Тонко нарезать очищенные клубни картофеля. Промыть в дуршлаге под струей воды, чтобы удалить излишки крахмала. Можно замочить в воде на полчаса, затем слить и промывать до прозрачности воды. Обсушить с помощью бумажных полотенец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2656,'Чипсы посыпать крупной солью и любыми специями для овощей, готовить в микроволновке порциями. Каждую прогреть в течение трех минут, затем перевернуть, уменьшить мощность наполовину и готовить еще три минуты. Домашние хрустящие чипсы в микроволновке готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2657,'Порезать хлеб, намазать оливковым маслом. Отправить в духовку, обжаривать, пока не появится хрустящая корочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2657,'Положить на багет слайс моцареллы и лосося.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2657,'Соединить в посуде соевый соус с чесночным порошком, добавить мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2657,'Побрызгать хрустящие бутерброды полученной смесью, посыпать измельченным луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Приготовить куриный бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Измельчить морковь и лук, обжарить лук на жире, снятом с бульона, до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'С помидора снять кожуру, порезать помидор на маленькие кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Положить к моркови и луку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Чуть-чуть обжарить овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Помыть шампиньоны, порезать на пластинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Достать курицу из бульона, снять с костей мясо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Поделить мясо на кусочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Положить в кипящий бульон обжаренные овощи, грибы, помидоры.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Готовить 10 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Высыпать в суп куриное мясо, положить горсть вермишели.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Готовить 5 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2658,'Перед подачей в тарелки добавить измельченную петрушку и чеснок.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2659,'Прокипятить сок апельсина с отварным картофелем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2659,'Взбить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Надеть сосиски на шпажки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Такую же процедуру сделать с сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Соединить в большой посуде кукурузную муку с блинной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Взболтать яйца, добавить в смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Налить воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Нагреть масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Опустить сосиски и сыр в тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Позволить стечь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Осторожно окунуть в масло.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Подождать пару минут, пока они не станут золотистого оттенка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2660,'Достать и дать стечь маслу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Порезать мясо на средние куски, пожарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Порезать на полукольца лук, грибы на дольки, морковь соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Обжаривать 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Положить в ту же сковороду мясо, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Налить стакан бульона или горячей воды, уменьшить огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2661,'Когда мясо будет готово, положить сметану, тушить 5-7 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Нагреть сковороду, налить оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Измельчить базилик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Соединить сахар, муку, соль, разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Во вторую посуду вбить яйца, налить молоко, добавить рикотту, растопленное масло. Взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Соединить смеси, перемешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Положить в смесь кусочки шоколада и измельченный базилик. Перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2662,'Налить в горячую сковороду тесто, перевернуть через несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Отрезать ножки у грибов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Почистить креветки от панциря, отваривать несколько минут в кипящей воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Слить воду, ополоснуть креветки под проточной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Почистить авокадо от косточек и кожуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Положить мякоть в емкость, полить соком лимона, чтобы не стал темным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Размять авокадо вилкой, положить йогурт, помидоры, добавить соевый соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Посолить, поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2663,'Начинить шампиньоны фаршем, украсить веточкой рукколы и креветкой, добавить колечко красного перца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Сварить пасту до состояния «al dente» в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Процедить, оставив чуть-чуть жидкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Помыть кабачок, срезать основание, разрезать на две части, порезать на полу кружки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Разрезать пополам помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Крупно порезать базилик.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Нагреть оливковое масло в большой сковороде, положить кабачок, обжаривать пару минут, помешивать до румяного цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Положить помидоры, выдавить чеснок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Размешать, томить несколько минут, пока помидоры не станут мягкие.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Посыпать солью, добавить базилик, сливки. Перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Довести соус практически до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Положить пасту, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Если блюдо очень густое, то долить чуть-чуть жидкости, которая осталась после готовки макарон.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2664,'Разложить пасту с кабачками, помидорами и базиликом по тарелкам, посыпать черным перцем, обильно посыпать сыром.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Положить в теплое молоко сахар, дрожжи, чуть-чуть муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Помесить смесь в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Когда образуется шапочка из пузырьков, добавить взболтанное яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Соединить сухие продукты: муку, соль, сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Медленно ввести дрожжевую смесь в мучную. Сформировать тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Положить охлажденное топленое масло. Замесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Оно будет липкое, но муку не досыпать. Накрыть тесто полотенцем, отправить в тепло на несколько часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Сделать крем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Развести крахмал в подогретом молоке, положить сахар, желтки, ваниль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Готовить, пока крем не станет густым.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Непрерывно мешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Остудить, положить масло, взбить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Помять тесто на столе, присыпанном мукой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Подлить тесто на 15 кусков.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Из каждого куска сделать овал по 12-15 сантиметров.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Отступив от верха 3 сантиметра, положить маленькую ложку крема.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Накрыть крем тестом, залепить краешки.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Порезать остальное тесто на полосочки, свернуть булочки.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Положить их на противень, отставить на 20 минут.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Намазать булочки желтком.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Готовить 15 минут в духовке, соблюдать температуру 180 градусов.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Накрыть их полотенцем, отставить на 10-15 минут.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2665,'Посыпать воздушные булочки с молочной начинкой сахарной пудрой.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'В отдельных емкостях отварить треску и картофель (не солить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Удалить у трески кости и кожу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Мякоть измельчить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Помять картофель толкушкой, чтобы исчезли комки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Очень мелко порезать петрушку и лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Соединить с треской и картофелем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Постепенно вбить яйца в смесь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Посыпать перцем, добавить мускат, соль, если нужно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Смочить водой две большие ложки, с их помощью сделать шарики из полученной смеси.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Если эта процедура не получается, то скатать шарики влажными руками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Нагреть масло для фритюра, положить шарики, пожарить до золотистого оттенка.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2666,'Выложить шарики на салфетку, чтобы стекло масло.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Чтобы приготовить тесто, нужно соединить все продукты и порубить ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Быстро вымесить тесто, и сделать шар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Завернуть в полиэтилен, отправить на полчаса в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Нагреть духовку до 180 градусов. Форму намазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Раскатать тесто на столе, присыпанном мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Выложить тесто в формочку, равномерно распределить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Сделать проколы вилкой, накрыть специальной бумагой, посыпать бобами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Готовить 20-25 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Убрать бобы и бумагу, дать коржу остыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Остывший корж достать из формы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Взбить до однородности сыр с сахаром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Растопить на горячей водяной бане порезанный белый шоколад.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Дать ему остыть, соединить с Маскарпоне, сразу добавить сливочный сыр.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Замочить в воде желатин, держать на тихом огне, пока он полностью не растворится.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Дать желатину чуть-чуть остыть.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Добавить сок лимона, несколько ложек сливочного сыра.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Осторожно ввести в сливочный крем.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Перемешать до однородности.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Смешать шоколадные чипсы и взбитые сливки, добавить в основной крем.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Заполнить кремом корж, отправить на несколько часов в холодильник.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Растопить на водяной бане шоколад, чуть-чуть остудить.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2667,'Украсить чизкейк с шоколадно-сливочной начинкой шоколадной стружкой.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Помыть куриное филе, порезать на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/4a/22d9f72db48154a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Растопить сливочное масло на сковороде, долить оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Обжаривать мясо 10 минут. Добавить к мясу соевый соус. Положить мед. Размешать и готовить 15-20 минут.','https:https://st.vkuso.ru/data/cache/thumb/c8/7b7862569599ec8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Если необходимо, подсолить. Добавить сок лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Во время приготовления мясного соуса, отварить фарфалле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Довести до кипения воду, подсолить, отправить макароны в воду. Готовить 10 минут, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Слить всю воду, используя дуршлаг.','https:https://st.vkuso.ru/data/cache/thumb/33/5aab67ba06cc433_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Положить макароны в сковороду с соусом.','https:https://st.vkuso.ru/data/cache/thumb/6c/35380604a15976c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2668,'Если соус очень густой, то добавить воду. Готовить 3 минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Насыпать сахар на сковороду, подогреть до карамельного оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Добавить масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Когда растопится, положить яблоки, порезанные на тоненькие дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Посыпать корицей. Готовить 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Перетереть яйца и творог, можно насыпать сахар и ваниль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Залить яблоки смесью из творога. Накрыть крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Готовить, пока снизу не получится корочка, и омлет максимально не вздуется.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2669,'Перевернуть омлет из творога и яблок с корицей на тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2670,'Крупно нарезать любое мясо, например, свиную лопатку.  Кусочки должны быть такого размера, как для приготовления шашлыка. Выложить в горшочек для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2670,'Добавить жирные сливки, размятый помидор без кожицы, кольца репчатого лука, немного лимонной цедры. Соль и черный молотый перец – по вкусу. Залить кипятком до верха, печь нежнейшую свинину в горшочках в течение часа или чуть больше при температуре 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Растопить сливочное масло и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Нагреть духовку до 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Взбивать яйца и сахар 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/20/e1b55b40e383020_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Насыпать муку, осторожно размешать.','https:https://st.vkuso.ru/data/cache/thumb/09/73685b5a3e36e09_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Добавить растопленное масло.','https:https://st.vkuso.ru/data/cache/thumb/3b/f01e5e06dedc93b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Консистенция получится не жидкая, но и не густая.','https:https://st.vkuso.ru/data/cache/thumb/90/1cb8d9ba8897a90_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Разложить по ячейкам чуть-чуть теста, положить ягоду. Формочку смазывать не нужно.','https:https://st.vkuso.ru/data/cache/thumb/a2/df692b585e31ba2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2671,'Готовить мадлен с любимыми ягодами 12 минут, они должны потемнеть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Порезать мясо на кусочки среднего размера, порезать чеснок на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Посыпать мясо любыми специями, посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Положить курицу в форму, равномерно распределить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Взбить сливки миксером, намазать мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Отправить в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2672,'Куриную грудку с чесноком в сливочном соусе готовить 45-50 минут, соблюдать температуру 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Вымыть бедра, обтереть бумажным полотенцем, натереть солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Начинить измельченным чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Для этого сделать надрез в коже, просунуть чеснок в получившиеся отверстия, распределить чеснок под кожей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Намазать форму маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'В середину положить мясо.','https:https://st.vkuso.ru/data/cache/thumb/a9/01525ef186290a9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Почистить картофель, порезать на кружки (если картофель большой, то разрезать пополам).','https:https://st.vkuso.ru/data/cache/thumb/12/d4f8ccc1de63912_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Разложить порезанный картофель вокруг мяса слоями.','https:https://st.vkuso.ru/data/cache/thumb/ed/3e41235d7bd3eed_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Чуть-чуть посолить, так как бедра пустят соленый сок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Крупно потереть сыр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Соединить сыр с майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Распределить смесь по картофелю. Слегка намазать майонезом мясо.','https:https://st.vkuso.ru/data/cache/thumb/42/5e5eebe02339942_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Готовить куриные бедра с чесноком в картофельном кольце 40 минут, соблюдать температуру 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2673,'Картофель будет покрыт корочкой.','https:https://st.vkuso.ru/data/cache/thumb/53/782779beb9c4853_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Мелко потереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Почистить яблоко и крупно потереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Удалить кости из рыбы, размять мякоть.','https:https://st.vkuso.ru/data/cache/thumb/ac/82e9f7b698713ac_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Положить в емкость консервы, морковь, яблоко, измельченную зелень, лук. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/3c/258a5d385e5c13c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Заправить майонезом или сметаной. Размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Взять небольшие помидоры, порезать на кольца.','https:https://st.vkuso.ru/data/cache/thumb/23/bfb244bd3c32723_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Разложить на блюдо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Сверху положить смесь из овощей и рыбы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2674,'Украсить зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Вымыть и обсушить филе от куриной грудки. Если грудка маленькая, то взять 2.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Порезать на маленькие куски.','https:https://st.vkuso.ru/data/cache/thumb/c3/112c8f7e054d8c3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Крупно потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/ce/41d1279445079ce_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Добавить к мясу сыр, яйцо, посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/cb/1d9c59cf2f145cb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/bd/375eef63a79c9bd_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Сформировать котлеты нужно размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Выложить котлеты на раскаленную сковороду.','https:https://st.vkuso.ru/data/cache/thumb/77/3b8191ec2fc2b77_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Перевернуть, когда побелеет верхняя часть котлеты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Когда поджарится низ изделия, накрыть на 1 минуту крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2675,'Процесс готовки занимает максимум 10 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Свинину порезать на тонкие ломтики. Отбить все куски.','https:https://st.vkuso.ru/data/cache/thumb/27/a5fd43b5b153f27_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Использовать пищевую пленку: мясо не будет лезть в разные стороны и останется чистым.','https:https://st.vkuso.ru/data/cache/thumb/68/f9be6b052ed9368_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Каждый кусочек посыпать перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Выложить свинину на противень, намазанный маслом, или в формочку.','https:https://st.vkuso.ru/data/cache/thumb/d2/5efddc8b344dbd2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Сверху намазать мясо маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Помидоры порезать на тоненькие кружки, разложить на мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Сверху намазать майонезом.','https:https://st.vkuso.ru/data/cache/thumb/0d/a14a9fb6fe78e0d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Выложить помидоры.','https:https://st.vkuso.ru/data/cache/thumb/88/7ec10047fb09c88_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Намазать майонезом и кетчупом.','https:https://st.vkuso.ru/data/cache/thumb/a9/843e18ec8a7e7a9_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Крупно потереть сыр.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Посыпать помидоры.','https:https://st.vkuso.ru/data/cache/thumb/dc/0ee6ead644e79dc_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2676,'Готовить 35-40 минут в духовке, соблюдать температуру 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2677,'Смешать просеянную пшеничную муку, стакан воды или молока, мягкое сливочное масло. Массу перемешать и поставить на слабый огонь. Прогревать, помешивая, пока тесто не заварится в тугой комочек. Дать немного остыть и добавить яйца по одному, хорошо перемешать, можно делать это с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2677,'Противень застелить бумагой для выпекания. Тесто переложить в кулинарный шприц или мешок и отсадить на противень небольшие пирожные. Печь в течение 20 – 25 минут при температуре 200 градусов. Пирожные должны подняться и образовать полости. Отдельно взбить сливки с сахарной пудрой, наполнить массой кулинарный мешок или шприц и заполнить пирожные изнутри. Сладкие профитроли со сливочной начинкой готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Насыпать в теплое молоко дрожжи, насыпать половину чайной ложки сахара, 2 или 3 маленькой ложки муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Размешать, чтобы получилось однородное жидковатое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Отставить на 30-40 минут, чтобы образовалась пенная шапка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Просеять муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Насыпать сахар, соль, размешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Положить в смесь мягкий маргарин, сметану, растереть до крупной крошки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Влить дрожжевую смесь, замесить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Если тесто очень жидкое и не держит форму, то в процессе замеса досыпать чуть-чуть муки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Если мука плохо смочилась, или тесто получилось очень густое, то долить молоко.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Накрыть тесто, отставить на 10-15 минут, чтобы мука впитала влагу. Тогда тесто будет легко меситься.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Хорошо вымесить тесто до однородности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Накрыть тесто и поставить в тепло, чтобы оно увеличилось.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Обмять тесто, и еще раз отправить в теплое место.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Если время не позволяет этого сделать, то достаточно одного раза.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Сделать творожную начинку: растереть до однородности сахар, творог и яйцо.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Если творог очень влажный, то добавить чуть-чуть муки или измельченных сухарей.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Раскатать тесто толщиной 0,5-1 сантиметр.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Разложить начинку из творога.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Свернуть тесто в неплотный рулет.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Порезать его на кусочки любой толщины.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Разложить творожные завитушки на противне, застеленном специальной бумагой.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Накрыть, отставить на 40 минут для расстойки.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'В этот период завитушки увеличатся в объеме.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Намазать завитушки разболтанным яйцом, через 5-7 минут отправить в духовку.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Готовить до румяного цвета. Соблюдать температуру 180-200 градусов.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Сделать заливку: соединить сахар и сметану.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2678,'Обильно намазать завитушки заливкой, накрыть, отставить до остывания.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Мелко порезать мясо, овощи и курдюк на маленькие кубики.','https:https://st.vkuso.ru/data/cache/thumb/3e/35023d7839d8b3e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Посыпать перцем, солью, добавить толченную зиру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Размешать руками, отправить на 20 минут в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/93/34c5d34f77ff893_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Замесить круто тесто из воды, соли и муки.','https:https://st.vkuso.ru/data/cache/thumb/dd/ff980bf92f326dd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Поделить тесто пополам, накрыть полиэтиленом, отставить на 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Раскатать тесто в тоненький пласт, порезать на широкие ленточки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Намазать растительным маслом. Положить фарш на каждую ленту.','https:https://st.vkuso.ru/data/cache/thumb/53/1eb348887f38553_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Сложить ленты с фаршем пополам. Защипнуть края.','https:https://st.vkuso.ru/data/cache/thumb/65/1bbc32c47512c65_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Скрутить ленту в виде улитки, защипнуть краешки.','https:https://st.vkuso.ru/data/cache/thumb/20/c44cd86d68ff820_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Получаются манты в виде гюль – роза.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Низ окунуть в растительное масло, чтобы во время готовки они не прилипали.','https:https://st.vkuso.ru/data/cache/thumb/83/e83ae723405fd83_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2679,'Можно варить в пароварке или в мантышнице 40-45 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Подготовить ингредиенты комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Взбить сахар с растительным маслом миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Вбить яйца, налить ряженку, добавить экстракт ванили, взбить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Насыпать муку, посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Добавить в тесто соду, гашенную уксусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Перемешать очень осторожно.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Положить пекан или другие орехи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'В формочки разложить тесто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Готовить 10-20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Остудить капкейки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Сделать крем: 2 минуты взбивать творожный сыр со сливочным маслом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'Насыпать ваниль, пудру, взбить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2680,'При помощи кондитерского мешка украсить Ореховые капкейки с творожным сыром кремом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Растопить и остудить маргарин или масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Насыпать в посуду сахар, вбить яйца, положить растопленный маргарин (масло), добавить ванилин. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Постепенно насыпать муку, просеянную с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Поделить тесто на 2 разные по размеру части (2/3 или 1/3).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Часть поменьше отправить в морозилку на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Часть побольше распределить на противне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Предварительно тесто раскатать, но можно этого не делать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Положить на тесто слой варенья, равномерно распределить по поверхности при помощи ложки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Достать из морозилки меньшую часть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Крупно потереть на терке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Выложить слоем на варенье.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2681,'Отправить пирог в духовку на 20-25 минут. Соблюдать температуру 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'В подсоленной воде отварить куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Разделить приготовленное мясо на тоненькие волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Вымыть шампиньоны, порезать, не убирая ножки, на тоненькие пластинки, не снимая кожицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Обжарить грибы на подсолнечном масле. Шампиньоны должны чуть-чуть подрумяниться, а жидкость испариться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Подсолнечное масло можно заменить сливочным. В этом случае у салата будет более нежный вкус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Когда грибы чуть-чуть остынут, положить их к мясу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Добавить сыр. Перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Чтобы сыр чуть-чуть расплавился, грибы нужно использовать теплые.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Перемешивать следует быстро, чтобы сыр не превратился в комок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Заправить майонезом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Посолить, если необходимо. Можно не солить, так как грибы сильно впитывают соль.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2682,'Отправить салат в холодильник для пропитки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Растворить в теплой воде соль, сахар, дрожжи. Отставить на 5 минут, чтобы смесь вспенилась. Чтобы это произошло, нужно использовать свежие дрожжи и только теплую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Просеять в посуду ¾ муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'В горке муки сделать углубление, осторожно вылить в него смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Все чуть-чуть перемешать, добавить оливковое масло или подсолнечное, но без запаха.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Снова перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Делать тесто легко: плавно руками месить массу. В результате тесто должно стать мягким, эластичным, гладким.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Чтобы тесто сильно не липло к рукам, необходимо капнуть на ладошки масло и досыпать чуть-чуть муки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Из готового теста сформировать шар, накрыть салфеткой и поставить на 40 минут в тепло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Тесто надуется и увеличится, потому что дрожжи насыщают тесто углекислым газом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Когда тесто станет в 2 раза больше, обмять, чтобы вышел лишний воздух.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2683,'Готовое тесто раскатать толщиной 4-5 миллиметров, положить на него начинку, отправить в духовку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Обжаривать миндаль в духовке 15-20 минут, каждые 5 минут помешивать, чтобы он пропекался равномерно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Выключить духовку, но противень не доставать, миндаль понадобится позже.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Постелить специальную бумагу в форму 33 на 23 сантиметра, намазать бумагу обильно маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Положить в маленькую посуду мед, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Отдельно соединить сироп, сахар, соль, нагревать на небольшом огне, пока не растворится сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Положить в кастрюлю термометр, дождаться, пока он покажет 150 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Когда температура будет 115 градусов, начать взбивать белки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Переложить их в емкость для миксера, взбить на большой скорости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Уменьшить скорость, медленно влить горячий мед, непрерывно взбивая.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Увеличить скорость, взбивать все вместе до пиков.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Взбивая на средней скорости, налить в массу сахарный сироп.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Сделать снова скорость максимальной, взбивать 5 минут, чтобы получилась устойчивая, блестящая масса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Положить ванилин, масло.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'На данном этапе масса опадет, но после продолжительного взбивания поднимется.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Выключить миксер, положить обжаренные в духовке орешки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Размешать кондитерским шпателем.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Вылить массу в форму, равномерно распределить.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Работать будет довольно сложно, потому что масса получается липкая и очень устойчивая.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Положить сверху еще один лист специальной бумаги, намазать маслом.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Отставить на ночь.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Перевернуть противень, достать застывший лист нуги, порезать ножом, намазанным маслом, на квадраты.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2684,'Кусочки медово-ванильной нуги с миндалем завернуть в полиэтилен или специальную бумагу для хранения.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Нашинковать на терке морковь или порезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Перемешать, посыпать солью, позволить настояться 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Насыпать сахар, половину ложечки красного острого перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Важно вводить все ингредиенты постепенно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Перемешать морковь, отставить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Порезать на кольца лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Обжарить на растительном масле лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Достать лук из масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Остудить масло, добавить уксус.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Перелить ароматную смесь к моркови, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2685,'Положить чеснок, перемешать, отправить на 3 часа в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Растворить сахар и дрожжи, добавить в теплую воду. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Насыпать 4 ложки муки. Размешать, накрыть влажным полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Поставить опару в тепло на 60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Насыпать в опару соль, добавить подсолнечное масло, муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Замесить гладкое тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Накрыть полотенцем, отправить в тепло на 1,5-2 часа. Периодически чуть-чуть обминать тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Поделить тесто на шарики по размеру, как грецкий орех.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Положить в огнеупорную форму или на противень, намазанный маслом, на расстоянии 0,5 сантиметров.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Поставить в тепло на 10-15 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Готовить пампушки 15-20 минут, соблюдать температуру 220 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Приготовить соус. Измельчить чеснок, насыпать соль, налить растительное масло. Развести кипяченой водой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Достать пампушки, полить чесночным соусом, отправить в духовку еще на 5 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2686,'Полить классические чесночные пампушки к борщу остальным соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Нагреть духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Двадцатисантиметровую форму застелить пергаментом и намазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Взбить масло и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Добавлять по одному яйцу, каждое взбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'В отдельной емкости просеять разрыхлитель и муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Медленно ввести в смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Насыпать мак, ваниль, налить молоко.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Размешать до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Переложить тесто в форму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Положить на него вишню, утрамбовать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Заполнить вишней форму до краев.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Отправить на 30 минут в духовку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Проверять готовность деревянной палочкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2687,'Подавать пирог со взбитыми сливками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'В одной посуде чуть-чуть взбить яйца, долить кефир, добавить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Во второй – сухие ингредиенты: муку, соду, какао, сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'В емкость с сухими ингредиентами налить взбитые яйца, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'В смазанную форму вылить смесь, отправить в духовку. Готовить 50 минут, соблюдать температуру 170-200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Охладить пирог, разрезать на 3 части вдоль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Намазать заварным или сметанным кремом, посыпать орешками и шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Заварной крем: закипятить молоко, взбить добела яйца и сахар, не переставая взбивать, ввести муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Вылить смесь тоненькой струей в кипящее молоко, размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Сделать огонь тише, насыпать ваниль, хорошо вымешать крем. Остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Положить мягкое масло. Размешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Отправить крем на 30 минут в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2688,'Сметанный крем: соединить сметану, мягкое масло, сахар, взбить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'В кастрюлю налить 3 литра воды, закипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Промыть в холодной воде рыбу, порезать на большие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Помыть и почистить картофель, лук, морковь, петрушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Порезать картофель на большие кусочки, морковь соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Разрезать корень петрушки на 4 части, лук проткнуть в двух местах ножом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Закипевшую воду посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Положить овощи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Варить 10 минут, чтобы картофель был практически готов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Положить перец горошком, лавровый лист. Варить несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Положить в кастрюлю рыбу, варить 8 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Помыть укроп, положить в суп.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Если нужно, досолить суп.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Варить еще 2 минуты. Выключить огонь.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Дать ухе из лосося настояться несколько минут, достать лук и корень петрушки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Положить в тарелки по кусочку лимона, кусок рыбы, морковь, картофель.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2689,'Разлить по тарелкам бульон, дать настояться 2 минуты.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2697,'Филе птицы вымыть, обсушить бумажными полотенцами, натереть любимыми специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2697,'Застелить пергаментом форму для запекания, смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2690,'Добавить в куриный фарш измельченный репчатый лук и чеснок, соль, перец – по вкусу. Массу перемешать. Нарезать помидоры кружками. Так же нарезать баклажаны и обжарить на сковороде без жира с антипригарным покрытием. Немного остудить и положить сверху, на кружочки, фарш с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2690,'Смазать форму для выпечки, по кругу выложить баклажаны и помидоры поочередно. Добавить кусочки сливочного масла, посыпать тертым сыром. Печь рататуй с куриным фаршем при температуре 180 градусов до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Взбить чуть-чуть яйца, ванильный и коричневый сахар и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Насыпать муку, предварительно просеянную со специями, разрыхлителем, солью и содой. Взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Положить измельченные орешки, морковь, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Положить тесто в форму, намазанную маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Поставить в духовку, готовить при температуре 180 градусов. Готовить 50 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Вынуть пирог, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Приготовить крем: взбить сахарную пудру и сливочный сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Налить сок лимона, размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Украсить пирог кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Можно разрезать пополам вдоль и намазать внутри.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2691,'Посыпать грецкими орехами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Порезать помидоры на 4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Противень полить оливковым маслом, положить на него четвертинки томатов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Полить помидоры несколькими ложками оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Посыпать солью, черным и красным перцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Разложить между помидорами зубчики чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Поставить противень в духовку, томить 10 часов, соблюдать температуру 80 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Спустя время томаты поморщатся, кожицу можно снять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Взять литровую банку, налить чуть-чуть оливкового масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Положить чуть-чуть печеных томатов, потом несколько листиков базилика, запеченный чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Полить оливковым маслом, продолжать, пока банка не будет полной.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Затем налить масло, оставшееся на противне.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2692,'Закрыть банку крышкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'Клюкву перемолоть блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'В ягодное пюре влить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'Добавить сахарный песок, коньяк, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'Далее добавить палочку корицы, варить еще три или пять минут, масса должна загустеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'Соус снять с огня, добавить апельсиновый сок или нарезанный фрукт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2693,'Перемешать и поставить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Убрать лишний жир с тушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Приготовить маринад из чеснока, специй, цедры и сока апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Натереть составом наколотую кожу утки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Оставить на ночь для пропитывания, можно два или три раза перевернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Вынуть птицу, наполнить дольками апельсина, корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Отверстие заколоть зубочистками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Время запекания – сорок минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Вынуть из духовки, смазать выделившимся соком, печь еще сорок минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2694,'Готовую тушку смазать жидким медом и прогреть пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Тушку утки разделать на кусочки небольшого размера, промыть, шкурку не снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Дно чаши мультиварки смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Выложить птицу, обжарить с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Добавить лавровый лист, другие специи, соль, лук-порей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Нарезать кружками апельсины, выложить поверх мяса и лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2695,'Выставить режим «Тушение» на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2696,'Птицу вымыть и высушить, натереть специями снаружи и внутри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2696,'Набить тушку нарезанными яблоками с корицей и апельсинами, отверстие заколоть зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2696,'Ноги связать, на грудке сделать надрезы или наколоть вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2696,'Выложить тушку на противень, часть яблок расположить вокруг.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2696,'Полить свежим апельсиновым соком, время запекания – от полутора до трех часов, в зависимости от размера птицы. Температура приготовления – 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2697,'Выложить филе, полить соусом, приготовленным из апельсинового сока, бульонного кубика и соевого соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2697,'Поставить на двадцать пять минут в разогретую духовку, температура запекания – 210 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Перемешать тмин и можжевельник с черным перцем-горошком, кориандром и бадьяном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Специи высыпать на сухую сковороду и прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Нарезать кубиками или ломтиками морковь, чесночные зубчики – пополам, репчатый лук – тонкими полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Прогретые на сковороде специи измельчить в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Добавить цедру апельсина, соль, корицу, кунжутное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Смесью хорошо натереть птицу, полить натуральным жидким медом и полить соком апельсина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Выложить в утятницу, на дне расположить тимьян, лавровый лист, морковь, лук, апельсин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Поставить в духовку. Время запекания – двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Поливать стекающим соком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Тушку перевернуть, оставить на сорок минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Далее температуру убавить, потомить один час.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2698,'Выложить утку на блюдо, добавить в овощи соевый соус.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Перец, соль, прованские травы, сухой шалфей перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Добавить лимонный и апельсиновый сок, влить десертное вино.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Утиную тушку смазать маринадом, накрыть пищевой пленкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Поставить в холод для пропитывания на четыре часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Нарезать кольцами еще один апельсин, покрошить корень сельдерея.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Нафаршировать продуктами утку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2699,'Выложить в форму. Время запекания – один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Прогреть духовой шкаф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Утиную грудку отбить, натереть любыми специями для птицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Жарить с двух сторон до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Выложить птицу на сковороду под крышку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Дольки апельсина разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Вымыть и разрезать на две части помидоры черри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Разрезать полукольцами лук-шалот.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Перемешать овощи и фрукты со шпинатом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Приготовить заправку из соевого соуса, кунжутного масла, соли, перца.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Выложить готовый салат на блюдо, сверху – ломтики или кубики утки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2700,'Блюдо полить апельсиновым соком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Просеять в миску муку, влить немного горячей воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Далее ввести оставшуюся воду, соль и кунжутное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Замесить тесто, оставить на пятнадцать минут для набухания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Размять вилкой креветки, измельчить ростки бамбука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Перемешать со свиным фаршем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Очень тонко раскатать тесто, вырезать кружки диаметром в пять миллиметров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Выложить начинку, завернуть в виде мешочка с открытым верхом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2701,'Готовые изделия приготовить на пару, как манты, отварить или обжарить на сковороде до корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Муку перемешать с водой, приготовить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Завернуть в пленку, оставить на двадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Приготовить свиной фарш.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Добавить измельченный имбирь, чеснок, кунжутное масло, соевый соус, соль, перец, вино, рисовое или белое сухое.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Перемешать, поставить в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Нарезать тонкими полосками пекинскую капусту, опустить на две минуты в кипяток.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Обсушить, измельчить, добавить в фарш.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Тесто нарезать кусочками, раскатать колбаски, нарезать еще раз, сформовать кружки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Выложить начинку, защипать края так, чтобы шов был сверху.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Прогреть сковороду с кунжутным маслом, жарить пельмени на огне средней мощности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'После образования корочки влить воду и потушить под крышкой пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Крышку снять, воду выпарить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Добавить масло кунжута, жарить под крышкой еще пять минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2702,'Приготовить подливку из соевого соуса, рисового уксуса. Подать к пельменям отдельно, в качестве дип-соуса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'В емкость всыпать кукурузный и пшеничный крахмал, посолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Осторожно ввести кипящую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Замесить тесто, продукт должен быть однородным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Добавить топленое сало, перемешать еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Выложить полупрозрачное тесто в пакет на двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Креветки очистить от панцирей, часть превратить в фарш, другую нарезать кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Добавить продукт в свиной фарш вместе с рубленым зеленым луком, перцем, вином, солью, сахарным песком, кунжутным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Если фарш получился густым, в него можно влить имбирную воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Свежий корень нарезать тонкой соломкой, влить кипяток.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Готовый фарш покрыть пищевой пленкой, поставить на двадцать минут в холод.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Раскатать тесто в колбаски, нарезать кусочками, сформовать лепешки толщиной один или два миллиметра. Диаметр – восемь сантиметров.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Выложить начинку с креветками, слепить пельмени, выложить на решетку пароварки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2703,'Варить пять минут на сильном огне.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Муку просеять, влить воду, добавить соль, замесить пельменное тесто. Дать постоять под салфеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Приготовить начинку из свиного фарша, измельченного имбиря, китайской капусты и зеленого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Добавить соевый соус, специи, растительное масло. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Сформовать из теста колбаски, нарезать, слепить шарики, раскатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Выложить фарш, края теста поднять и сложить как цветок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2704,'Отварить в подсоленной воде или приготовить на пару.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Приготовить тесто из пшеничной муки, кукурузного или рисового крахмала, яиц и кунжутного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Влить воду, перемешать, тесто должно быть водянистым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Приготовить фарш из свинины, китайской капусты, лука, специй и соевого соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Добавить перец, имбирь, кориандр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Раскатать тесто, нарезать кружки, выложить начинку, сформовать пельмени в виде открытого цветка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2705,'Варить пять минут в воде или на пару.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Перемешать муку с водой и солью. Вымесить тесто до гладкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Дать постоять под влажной салфеткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Приготовить начинку из свиного фарша, чеснока, имбиря, лука, кунжутного масла и рисового уксуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Раскатать тесто, нарезать квадратами, выложить начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Собрать края так, чтобы пельмень вверху остался открытым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Приготовить на пару, решетку застелить тканью или пергаментом с дырочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Готовить на сильном пару, время – от восьми до десяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2706,'Приготовить подливку из соевого соуса, рисового уксуса, имбиря и коричневого сахара.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2707,'Приготовить тесто из муки, холодной воды и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2707,'Порубить баранину мелкими кусочками, добавить соевый соус, имбирь, кунжутное масло и тертый дайкон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2707,'Сформовать лепешки толщиной в три миллиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2707,'Выложить начинку, слепить края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2707,'Время варки – от семи до восьми минут, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2708,'Очистить мандарины и выжать сок. Смешать его в кастрюле с сахарным песком, прогреть до растворения вместе с пряностями: цедрой лимона и лайма, лавровым листом, палочкой корицы, мускатным орехом, бадьяном, стручком ванили и бутонами гвоздики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2708,'Довести смесь до кипения, варить пять минут на тихом огне. Влить красное вино, перемешать и прогреть, но не кипятить. Дать домашнему глинтвейну с корицей и мускатным орехом постоять, подать в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Просеять муку, влить воду, замесить обычное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Раскатать колбаску, нарезать, сформовать лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Приготовить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Креветки и трепанги перемолоть в пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Измельчить огурцы, отжать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Добавить к морепродуктам вместе с имбирем, солью, перцем и кунжутным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Выложить начинку на лепешки, сформовать узелки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Варить от пяти до семи минут в подсоленной воде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2709,'Отдельно подать соевый соус с рубленым чесноком или соевый соус с темным рисовым уксусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'В миску пересыпаем панировочные сухари и кунжут. Чуть перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'В миске или тарелке взбиваем 3 яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'В тарелке делаем маринад, соединим соевый соус 100 мл и мёд 2 ч. л. Количество маринада рассчитываем по количеству куриного филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'Куриное филе подготавливаем, моем, обсушиваем, избавляемся от жилок сухожилий и тд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'Перекладываем в миску, солим, перчим и посыпаем приправой для курицы, сразу можно добавить маринад, перемешиваем и убираем в сторону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'Заранее панируем ломтики из куриного филе. Ломтик куриного филе отпускаем в взбитое куриное яйцо, затем в панировку из панировочных сухарей и кунжута. Перекладываем на доску.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2710,'Разогреваем сковороду с растительным маслом и обжариваем ломтики из куриного филе до корочки. Обжаривать нужно около 2-3 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Сделать из тыквы горшочек: срезать крышку, вынуть семена, мякоть оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Приготовить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Нарезать свинину кусочками, выложить на сковороду с нагретым растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Обжарить, затем посолить, добавить черный молотый перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Перемешать, потушить десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Свинину переложить в емкость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'На сковороде потушить нарезанный репчатый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Нарезать кубиками картофель и баклажаны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Перемешать с мясом, зеленью, луковой обжаркой и чесноком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2711,'Нафаршировать тыкву, поставить в духовку, тушить при температуре 200 градусов. Время приготовления – один час.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Срезать с тыквы верхушку, удалить семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Мякоть срезать со стенок получившегося горшочка и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Отварить гречку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Обжарить на сливочном масле мясо с луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Добавить перец и соль, специи, потушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Перемешать с гречневой кашей, добавить тыкву, крупно нарезанные крутые яйца, зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Заправить сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2712,'Наполнить начинкой тыкву, поставить в духовку на час. При готовности тыкву можно будет проколоть спичкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Из тыквы небольшого размера сформовать горшочек: снять крышку, вынуть семечки, мякоть нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Нашинковать репчатый лук, спассеровать на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Выложить фарш из говядины, жарить с луком до посветления.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Добавить томатную пасту, соль и молотый перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Приправить давленым чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Наполнить смесью тыкву-горшочек, поставить в духовой шкаф.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2713,'Натереть сыр, посыпать начинку сверху, прогревать до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2714,'Лук, морковь, картофель подготовить и нарезать одинаковыми кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2714,'Шампиньоны – пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2714,'Курицу нарезать длинными полосками вдоль волокон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2714,'Наполнить смесью продуктов тыкву, посолить по вкусу, поперчить, влить кипяток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2714,'Накрыть «крышкой» и тушить в духовом шкафу от сорока до сорока пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Сделать из тыквы горшочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Натереть стенки изнутри смесью растительного масла с солью, перцем и прованскими травами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Поставить на полчаса в духовку, температура запекания – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Отварить пшено, пропустить куриное мясо через мясорубку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Остудить кашу, фарш обжарить вместе с нарезанным репчатым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Вынуть из духовки тыквенный горшочек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Снять мякоть со стенок, порубить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Перемешать куриную обжарку с тыквой и кашей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Перемешать, выложить в тыкву.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Накрыть срезанной крышкой, тушить в духовке еще полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'За десять минут до готовности снять крышку, насыпать тертый сыр.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2715,'Допечь блюдо без «крышки».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2716,'Пангасиус нужно подготовить, очень хорошо промыть, потом нарезать на порционные кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2716,'Затем в миске его нужно посолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2716,'В другой миске нужно сделать кляр. В миску вбиваем 3 яйца, и добавляем сметану 3 ст.л. хорошо перемешиваем. Затем добавляем муку около 5 ст.л. и доводим кляр до густоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2716,'Каждый кусочек опускаем в кляр и перекладываем на разогретую сковороду, обжариваем с двух сторон по 2-3 минуты, до корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Мякоть тыквы срезать, порубить кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Нарезать морковь и сельдерей кружками. Чеснок – прозрачными слайсами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Мелко нарезать цветную капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Прогреть в сотейнике растительное масло, обжарить морковь и сельдерей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Добавить цветную капусту и тыкву, потушить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'В почти готовое рагу добавить зеленый горошек, специи, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Выложить начинку в тыкву, накрыть срезанной крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2717,'Тушить в духовке полчаса при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2718,'Сделать из тыквы горшочек с крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2718,'На дно выложить сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2718,'Промыть рис несколько раз, залить кипящей водой на пять минут, всыпать в тыкву на две трети объема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2718,'Добавить сахар или мед.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2718,'Влить молоко, поставить тыкву-горшочек на сорок минут в духовку, тушить при температуре 220 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Приготовить из тыквы горшочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Отварить рис до полуготовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Перемешать с курагой, черносливом, изюмом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Всыпать сахар, ваниль, корицу или гвоздику.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Выложить начинку в тыкву, прикрыть «крышкой».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2719,'Поставить фаршированный плод в миску, тушить в духовом шкафу от часа до полутора при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Удалить стебельки и мягкие ягоды',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Отобранный продукт промыть, откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Налить воду в емкость с толстым дном, добавить сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Поварить до получения сиропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Ягоды в дуршлаге опустить в сироп, варить пять минут, пену удалить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Продукт остудить, вынув дуршлаг с ягодами из сиропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Всыпать оставшийся сахар, переложить в кастрюлю, варить на тихом огне полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Стерилизовать банки, литровые или полулитровые.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2720,'Выложить варенье, банки закрыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Ягоды снять с кисточек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Промыть, отцедить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Крупные ягоды можно наколоть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Переложить продукт в чашу мультиварки, добавить сахар, выставить режим «Тушение» на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Стерилизовать небольшие банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2721,'Выложить варенье, закрыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2722,'Виноград снять с веточек и промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2722,'Выложить в емкость с толстым дном, добавить воду и сахар, ваниль и корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2722,'Варить на плите на тихом огне. Сироп должен получиться густым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2722,'Газ погасить, варенье остудить при комнатной температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2722,'Банки с крышками стерилизовать, выложить варенье, закрыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Ягоды оборвать с веточек, помыть, крупные ягоды наколоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Всыпать сахар, оставить на час, продукт должен подать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Промыть мяту водой, мелко порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Добавить в виноград.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Варить в кастрюле с толстым дном до закипания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Влить воду, варить еще две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Оставить продукт для настаивания на несколько часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Слить сироп, добавить желирующий состав из пакетика, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Перемешать с ягодами, варить три минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2723,'Разлить варенье в стерильные банки, закрыть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2724,'Очистить от костей и нарезать соленую сельдь. Отварить и нарезать яйца, картофель и морковь. Мелко накрошить репчатый лук. Все ингредиенты смешать, заправить салат «Прибой» майонезом, соль, перец молотый – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Ягоды промыть, отцедить от воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Выложить в кастрюлю вместе с частью сахарного песка, оставить на семь часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Основной продукт должен дать сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'В другую емкость выложить сахар, влить сок и добавить корицу, варить до получения сиропа на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Остудить, добавить в ягоды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Варить до готовности, ягоды должны опуститься на дно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2725,'Выложить варенье в стерильные банки, закрыть крышками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Ягоды промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Сварить в кастрюле с толстым дном сироп из сахара и воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Залить ягоды, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Дать постоять пять часов при выключенном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Листья мяты и вишни промыть, добавить к остальным ингредиентам, еще раз довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Дать постоять пять часов, довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Процедуру повторить еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Зелень удалить, добавить в варенье лимонную кислоту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2726,'Выложить десерт в стерильные банки небольшого размера, закрыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Ягоды сорта «Кишмиш» отделить от веточек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Продукт промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Яблоки кисло-сладкого сорта очистить от семян и кожуры, мякоть промыть и нарезать кубиками, дольками или ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Влить в кастрюлю воду, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Отдельно перемешать яблоки с виноградом и залить кипятком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Варить в кастрюле с толстым дном, довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Огонь погасить, дать варенью постоять четыре или пять часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Снова довести продукт до кипения, оставить для настаивания на четыре часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Процедуру повторяем в течение дня.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2727,'Выложить варенье в чистые банки, закрыть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Персики вымыть, удалить косточки, нарезать мякоть дольками или кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Промыть виноград, снятый с веточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Выложить в емкость оба продукта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Отдельно смешать желирующую смесь с сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Всыпать в виноградно-яблочную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Варить на тихом огне до закипания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Всыпать оставшийся сахар, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Еще раз довести до кипения, проварить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Снять варенье с огня, выложить в стерильные банки, промыть, закрыть крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2728,'Перевернуть емкости вверх дном, остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Виноград снять с веточек, промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Отдельно вскипятить воду, всыпать виноград, варить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Вынуть виноград в тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Перемешать сахар с водой, сварить сироп на тихом огне при постоянном помешивании. Время приготовления – около получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Орехи кешью оставить целыми или немного поломать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Варенье еще раз довести до кипения, добавить орехи, пряности, специи: бадьян или корицу. Варить двадцать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2729,'Выложить продукт в простерилизованные банки, перевернуть, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Виноград любого сорта хорошо промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Вымыть и ошпарить лимон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Разрезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Из половины выжать сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Вторую часть нарезать дольками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Всыпать в кастрюлю с толстым дном сахар, влить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Варить на тихом огне до полного растворения сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Переложить виноград и лимон, влить сок, перемешать. Остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Проварить смесь до закипания, остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Процедуру повторить три или четыре раза.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2730,'Выложить десерт в стерильную тару, остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Перебрать виноград, промыть водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Промыть кизил.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Ягоды пересыпать в толстостенную кастрюлю, всыпать сахарный песок, влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Варить на огне средней мощности, довести до кипения. Пену снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Семь минут варить смесь на очень тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2731,'Варенье разлить в стерильные банки, закрыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Ягоды винограда промыть холодной водой. Обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Вымыть груши, удалить сердцевину и кожуру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Мякоть нарезать дольками или кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Фрукты засыпать сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Виноград размять, отцедить сок через сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Добавить сок в груши, перемешать и оставить на несколько часов для настаивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Варить в тазу с толстым дном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Довести до кипения. Помешивать, избегать пригорания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Далее варить на тихом огне один час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Груши должны стать мягкими, сироп – темным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2732,'Выложить лакомство в стерильные банки, закрыть, перевернуть, остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2733,'Ягоды промыть, отцедить, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2733,'Варить с сахаром и водой в несколько приемов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2733,'Каждый раз варенье должно доводиться до кипения и полностью остывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2733,'По желанию добавить желирующие вещества из пакетика или природные – цитрусовые, смородину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2733,'В процессе варки удалять образующуюся пену.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Виноград промыть, перебрать, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Выдавить мякоть, кожуру выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Выложить в кастрюлю, довести до кипения, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Процедить массу через сито. Косточки выбросить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Перемешать с сахаром и лимонной цедрой, свежим лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Довести до кипения, варить на тихом огне полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Массу помешивать, пену убирать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2734,'Разлить в банки, хранить в темноте.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Замороженные креветки залить кипятком, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Спагетти, обычные рожки или макароны фетучини отварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'На огонь поставить сковороду с оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Чеснок очистить и измельчить, жарить полминуты, а затем удалить со сковороды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Положить креветки, жарить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Полить сметаной, посыпать тертым сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2735,'Перемешать пасту с морепродуктами, сбрызнуть свежим лимонным соком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Листья смородины вымыть, разложить на полотенце. Убрать в темное место на 8-10 часов, чтобы листья немного подвяли.','https://vkuso.ru/data/cache/data/02/b9e96d2b92ca602_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Затем пропускаем листья смородины через мясорубку.','https://vkuso.ru/data/cache/data/2a/570845be4f9432a_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'На поддон электросушилки поставить поддон для пастилы, если такового нет можно воспользоваться бумагой для выпечки или марлей, вырезав их по форме поддона.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Ягоды смородины, перебрать и хорошо вымыть. Разложить на поддоны. 
(если ягоды крупные их можно просто выкладывать поддоны, а если мелкие, то лучше так же воспользоваться поддоном для пастилы или бумагой для выпечки).','https://vkuso.ru/data/cache/data/e2/0d9ac188cf75de2_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Установить поддоны на электросушилку, выставить температуру 45 градусов, включаем и ждем 10-12 часов.','https://vkuso.ru/data/cache/data/fd/71638d13143dcfd_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Готовые ягоды и измельченные листья смородины пересыпать в сухую баночку, закрыть крышкой и убрать на хранение!','https://vkuso.ru/data/cache/data/fd/f641d965cda50fd_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2736,'Приятного аппетита!','https://vkuso.ru/data/cache/data/a7/67de9b145fde5a7_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2737,'Белокочанную капусту мелко нашинковать, можно измельчить массу в блендере. Добавить сырые яйца, соль, перец, любые специи по вкусу, всыпать пшеничную муку.  Перемешать и испечь блинчики, остудить. Измельчить репчатый лук и натереть морковь, то и другое обжарить. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2737,'Смазать капустные блинчики сырым, подсоленным по вкусу, фаршем. Сверху – слой морковно-луковой обжарки, зелень. Таким образом сделать несколько слоев. Овощной торт выложить на противень, смазать смесью тертого сыра и майонеза. Печь капустный тортик с мясным фаршем в духовом шкафу в течение 15 – 20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Готовое магазинное слоеное тесто немного раскатать, разрезать на кусочки, выложить на противень и печь в духовом шкафу до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Влить растопленное сливочное масло, добавить муку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Для приготовления крема взбить в густую массу яйцо с сахарным песком, добавить муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Вскипятить молоко, положить в него кусочек сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'В яичную массу влить кипящее молоко, взбить миксером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Смесь поставить на плиту и довести до загустения, добавить ванилин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Испеченные коржики из слоеного теста залить горячим кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Форму для торта застелить пищевой пленкой, выложить коржи с кремом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2738,'Охладить в холодильнике в течение пяти-шести часов, можно оставить на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'В емкость просеять пшеничную муку, добавить мягкое сливочное масло комнатной температуры, сметану, соль, влить горячую воду, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Рабочую поверхность присыпать мукой, массу вымешивать до тех пор, пока она не станет эластичной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Накрыть тесто пищевой пленкой, оставить на 10 – 15 минут для набухания клейковины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Для приготовления начинки клубни картофеля отварить и приготовить пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Мелко нарезать любые грибы, соединить с пюре, соль и перец – по вкусу, добавить рубленую зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Треть теста раскатать в пласт шириной десять сантиметров, начинку выкладывать двумя столовыми ложками, формируя шарики. Они должны располагаться на расстоянии в пять сантиметров друг от друга.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Края теста немного намочить, сложить, накрывая начинку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Шов прижать пальцами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Вареники нарезать при помощи стакана.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Изделия положить в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Готовые вареники отваривать в большом количестве воды, с солью, перцем-горошком, лавровым листом, зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2739,'Всплывшие изделия достать шумовкой, подать со сливочным маслом и сметаной.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Круглозерновой рис промыть, залить водой и довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Огонь уменьшить, добавить соль и доварить кашу до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Очистить и вымыть морковь и репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Морковь натереть, лук нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Мясной фарш немного обжарить, посолить и поперчить по вкусу, далее тушить на небольшом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Почти при готовности продукта добавить измельченные овощи и жарить до тех пор, пока они не станут золотистыми и мягкими.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Форму для запекания смазать подсолнечным маслом, выложить рис слоем в полтора-два сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Сверху – слой мяса с овощами, снова рис.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Отдельно взбить яйцо с водой и сметаной.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Смесь вылить на рис, распределять равномерно.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2740,'Запеканку поставит в горячую духовку, печь при температуре 180 градусов в течение 10 – 15 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Желатин в листочках замочить в холодной воде на пять или десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'В емкости смешать сметану, кефир, сахарный песок и ванильный сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Размешать до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Слить с желатина лишнюю воду, массу прогреть на очень тихом огне на водяной бане или в микроволновой печи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Влить желатин в кефирную смесь тонкой струйкой, помешивая, желатин должен равномерно распределиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Поставить массу в холодильник на 20 минут для загустения, а затем взбить венчиком или миксером, крем должен увеличиться в объеме, приобрести пышность.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2741,'Разлить смесь в стаканы-формочки, охладить в холодильнике в течение трех-четырех часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Налить в кастрюлю воду, чуть больше половины объема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Положить куриное филе, поставить варить на 20 минут, пену снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Колбасные и мясные изделия, соленые огурцы нарезать соломкой, сосиски – кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Если колбаса не обезжиренная, то перед закладкой в суп её можно немного обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Куриное мясо достать из кастрюли, нарезать мелкими кусочками и положить обратно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Добавить обжаренную колбасу, картофель или рис – по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Натереть морковь и нарезать репчатый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Вылить тесто в форму, выпечь до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Разогреть сковороду с маслом, обжарить лук до золотистого цвета, добавить морковь, через две минуты – томатную пасту, измельченный чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Все вместе жарить пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'В солянку добавить огурцы, консервированные маслины кружочками, влить огуречный рассол.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Можно добавить каперсы.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Соль и перец черный молотый и острый красный – по вкусу.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2742,'Мелко нарезать зелень, положить в солянку, варить пять минут, дать блюду постоять под крышкой несколько минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Тесто разделить на отдельные листы и оставить для размораживания при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Перемешать половину нормы молока, пшеничную муку, сырые куриные яйца и крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Оставшееся молоко вылить в кастрюлю, всыпать порциями стакан сахарного песка, прогревать на небольшом огне, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Смесь довести до кипения, но не давать закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Влить яичную массу, помешивать, снова довести до кипения, но не кипятить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Огонь выключить, продолжать помешивать еще три-пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Крем по консистенции должен напоминать манную кашу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Листы слоеного теста выпечь по десять минут до золотистого оттенка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'В остывший крем добавить сливочное масло и взбить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2743,'Листы промазать кремом, сложить стопкой, посыпать крошкой от коржей.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Смешать в миске «быстрые» дрожжи, сахарный песок, теплую воду, пшеничную муку, соль. Лучше делать это ложкой или венчиком, в конце добавить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Тесто хорошо вымесить, оно должно быть эластичным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Положить колобок в теплое место, накрыть тканью и дать постоять от 20 минут до часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Из подошедшего теста сформовать шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Противень застелить пергаментом, выложить изделия вплотную или на некотором расстоянии друг от друга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Печь при температуре 180 градусов до образования золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Чеснок очистить и измельчить, смешать в равных пропорциях с растительным маслом, добавить соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Измельчить зелень укропа и петрушки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Пампушки вынуть, накрыть на три минуты влажным полотенцем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Нанести чесночную смесь кисточкой, посыпать зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2744,'Подать к горячему борщу со сметаной.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Тесто:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Муку смешать с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Холодное сливочное масло нарезать на небольшие кубики и растереть с мукой в крошку. Влить в муку яичную смесь и вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Распределить тесто по форме для выпечки, сделать проколы вилкой и убрать в холодильник на 10-15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Начинка:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Достаньте тесто из холодильника. Выложите равномерно ягоды и залейте йогуртовой начинкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2745,'Выпекайте при 180°С 45-50 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Молодые кабачки вымыть и очистить от кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Натереть мякоть на крупной терке, соль и перец – по вкусу, дать массе постоять, до выделения сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Лишнюю жидкость слить, добавить сырые куриные яйца и пшеничную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Коржи жарить на горячей сковороде с растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Для приготовления начинки мелко нарезать очищенный репчатый лук, натереть морковь, то и другое обжарить до мягкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Отдельно смешать рубленый чеснок и укроп с майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Нарезать помидоры тонкими кружками, натереть сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'На первый корж намазать слой майонеза с зеленью и чесноком, выложить обжарку из лука и моркови, помидоры, посыпать сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Накрыть вторым коржом, операцию повторить несколько раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2746,'Коржи должны быть горячими, сыр плавится и скрепляет торт.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Взбить сырые куриные яйца с сахарным песком, поставить емкость в кастрюлю с кипящей водой и взбивать до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Миску снять, продолжать взбивать массу до остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Грушу, банан или манго, любой другой фрукт, очистить от кожицы и семян, мякоть натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Замочить желатин так, как написано на упаковке, ввести во фруктовое пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Взбить творог с сахаром, ввести в массу взбитые сливки, фруктовое пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Борта формы для запекания выстелить пергаментом, выложить смесь на готовый корж и поставить десерт в холодильник для застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Ввести желатин в апельсиновый сок, смазать поверхность изделия этой смесью, выложить кусочки фруктов и смазать их оставшимся апельсиновым желе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2747,'Торт поставить в холодильник на несколько часов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Для приготовления теста перемешать с помощью комбайна или миксера сахарный песок, сырые куриные яйца, чайную ложку соды, погашенной соком лимона или уксусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Всыпать просеянную муку, влить сметану, половину банки сгущенки. Тесто должно получиться полужидким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Противень с бортиками застелить бумагой для выпекания, вылить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Выпекать при температуре 180 градусов в течение 20 минут, готовность проверить спичкой или зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Для приготовления крема смешать сырое яйцо, столовую ложку пшеничной муки, стакан молока и сахарный песок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Смесь перемешать и поставить на огонь, довести до кипения, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Варить до загустения, затем охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Мягкое сливочное масло взбить миксером на небольшой скорости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Добавить остывший крем порциями, взбивать до однородного состояния.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Влить остатки сгущенного молока, продолжать взбивать медленно, а затем быстро в течение двух-трех минут. Крем должен получиться легким и воздушным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Разморозить вишню, сок слить и смешать с коньяком или ликером «Амаретто».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Готовый корж разрезать на три части, одну нарубить кубиками.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Нижнюю часть выпечки пропитать смесью вишневого сока с коньяком, выложить крем и ягоды вишни.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Сверху – второй корж, полить кремом, выложить ягоды, кусочки рубленого коржа, крем, вишню.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Приготовить глазурь из сахарного песка, какао-порошка, горячего молока и сливочного масла.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Смесь прогреть на плите, помешивать, довести до кипения, не кипятить. Сахар должен раствориться.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2748,'Снять с плиты, через минуту или две глазурью залить торт.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Некрупные клубни картофеля нарезать кубиками и отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Отцедить маринад от консервированной фасоли, зеленого горошка и сладкой кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Пекинскую капусту разобрать на листья, промыть, жесткую середину удалить, остальное нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Перемешать все ингредиенты, включая остывший картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Нарубить зелень петрушки и укропа, натереть очищенные свежие огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Отварить куриные яйца, очистить, нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Все составляющие вновь перемешать, соль и черный молотый перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2749,'Салат заправить майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Отварить фунчозу так, как написано на упаковке. Обычно рисовую лапшу не отваривают, а заваривают кипятком с добавлением соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Воду слить, продукт переложить в небольшую емкость и перемешать с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'В сковороде вок нагреть еще немного растительного масла, обжарить мелко нарезанный чеснок (4 зубчика) и сухой перец чили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Добавить свежие или размороженные креветки и жарить не больше двух-трех минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Вынуть морепродукт шумовкой, переложить в отдельную посуду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'В вок переложить фунчозу, подлить смесь рыбного соуса, сахарной пудры и тамариндовой пасты (1 ст. л.), её можно заменить соком лайма.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Лапшу немного обжарить, а затем сдвинуть лопаткой на край сковороды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Подлить еще немного масла, вбить сырые куриные яйца, немного обжарить и перемешать с лапшой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Добавить в сковороду креветки, рубленую зелень кинзы, измельченный чеснок (3 зубчика).',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2750,'Жарить еще три минуты, огонь выключить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2751,'Приготовить с помощью миксера банановое пюре. Соединить массу с ванильным сиропом или пастой, корицей, любым ореховым или оливковым маслом, добавить мёд, овсяные или ячменные хлопья быстрого приготовления, молотый фундук или кокос, изюм. Массу перемешать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2751,'Из полученного теста сформировать двенадцать шариков, обвалять их в овсяных хлопьях и немного расплющить. Печь бананово-овсяное печенье с корицей при температуре 160 градусов в течение получаса или чуть больше, до золотистого цвета. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Кабачки нарезать кружочками, толщиной около 1 см.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Противень застелить бумагой для выпечки. Кабачки смазать с двух сторон растительным маслом и выложить на противень. Поперчить и посолить по вкусу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Через пять минут противень достаем из духовки, переворачиваем кабачки на другую сторону и запекаем еще 5 минут.','https://vkuso.ru/data/cache/data/aa/a092b5b338e62aa_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Соединяем в миске сыр фета, сметану, измельченный чеснок и перец.','https://vkuso.ru/data/cache/data/89/4a0bc8e5bd29489_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Раскладываем сырную массу на кабачки и запекаем в духовке еще 5 минут.','https://vkuso.ru/data/cache/data/f7/e3213d4b7dbc0f7_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2752,'Готовые кабачки с сыром Фета выкладываем на тарелку, украшаем зеленью и подаем сразу, горячими.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Измельчить репчатый лук, натереть морковь, то и другое обжарить на оливковом масле до прозрачности лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Добавить в сковороду фарш, перемешать и прогревать на тихом огне, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Небольшие мясистые помидоры надрезать крест-накрест, опустить на минуту в кипяток, а затем очистить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Плоды перемолоть с помощью блендера, влить соус в мясную обжарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Добавить измельченный чеснок, соль, перец, свежий базилик.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Все вместе потушить на тихом огне до выпаривания влаги, на это потребуется около получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Баклажаны очистить, мякоть нарезать полосками толщиной в сантиметр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Нарезку обвалять в пшеничной муке и обжарить в растительном масле до получения золотистой корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Обжаренные овощи выложить на бумажные полотенца для впитывания лишнего жира.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Сырые яйца немного взбить вилкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Собрать пармиджану: на дно огнеупорной формы выложить часть мясного соуса, затем слой баклажанов, снова соус и измельченный сыр «Моцарелла».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Залить все яичной смесью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Снова выложить баклажаны, слои повторять, пока не закончатся ингредиенты.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Сверху должен быть мясной соус.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Блюдо поставить в горячую духовку, печь при температуре в 190 градусов в течение получаса.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2753,'Перед подачей кушанье посыпать тертым сыром «Пармезан».',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Манную крупу залить кефиром и оставить на час или два для набухания крупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Сырые куриные яйца взбить вместе с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Смешать массу с манкой, добавить размягченный маргарин, разрыхлитель и ванильный сахар из пакетика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Хорошо смазать маргарином форму для выпекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Половину теста выложить в форму, сверху – ягоды годжи, по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Прикрыть начинку оставшимся тестом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Печь манник в духовом шкафу, температура – 180 градусов, время – полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2754,'Остудить пирог на решетке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Растереть в крошку творог, муку и сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Постепенно подлить подсоленный кефир с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Тесто должно получиться мягким, завернуть его в пленку и дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Любые грибы, например, размороженные лисички, нарезать и обжарить с репчатым луком, добавить зелень укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Картофельные клубни отварить, приготовить пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Тесто растянуть руками по размеру противня с небольшими бортиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Выложить ровным слоем грибную начинку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'В пюре добавить яйца и кефир, массу взбить до пышности, смешать с тертым сыром и выложить поверх начинки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Печь изделие при температуре 180 градусов в течение 40 – 45 минут до образования румяной корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2755,'Готовый пирог накрыть тканью и дать постоять в течение 15 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Дрожжевое тесто можно замесить с вечера и поставить на ночь в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Для его приготовления потребуется мука, сухие дрожжи, сахарный песок, щепотка соли, молоко, кефир, сырые яйца, мягкое сливочное масло и ванильный экстракт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Ингредиенты можно перемешать с помощью кухонной машины или вручную.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Во втором случае сначала нужно смешать сухие ингредиенты, а потом влить в них жидкие.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Месить удобнее смазанными растительным маслом руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Готовое тесто должно подняться, его нужно выкладывать в большую кастрюлю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Для приготовления начинки очистить и нарезать кубиками яблоки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Пересыпать фрукт сахарным песком и перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Разогреть в сотейнике сливочное масло, добавить натуральный мёд, перемешать до однородного состояния.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Залить смесью яблоки, прогревать в течение 10 – 15 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'В конце добавить крахмал, перемешать, готовить две минуты, помешивать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Начинку остудить, её тоже можно приготовить вечером и оставить на ночь в холодильнике.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Для штрейзеля смешать муку, натертое охлажденное сливочное масло, ванильный сахар и пудру.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Все ингредиенты перетереть в крошку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Тесто из холодильника вынуть и дать постоять полчаса при комнатной температуре.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Руки смазать маслом, помять тесто и разделить его на равные кусочки.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Раскатать их в небольшие круглые лепешки, выложить на застеленный бумагой противень.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Между ватрушками должно быть расстояние, они увеличатся в размере.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Тесто накрыть тканью, оставить на 15 – 20 минут.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Дно стакана намазать растительным маслом и сделать им углубления для яблочной начинки.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Выложить её на ватрушки, бока смазать немного взбитым яйцом или только желтком.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2756,'Посыпать штрейзелем и печь при температуре 180 градусов в течение получаса, до готовности.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'У крупных яблок срезать нижнюю часть для устойчивости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Чуть выше середины плода срезать шляпку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Яблоки сбрызнуть лимонным соком, чтобы не почернели, удалить часть мякоти и сердцевину, переложить в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Для начинки перемешать мёд, творог, молотую корицу и изюм без косточек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Начинить плоды творожной массой, закрыть срезанными шляпками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Начинка должна быть немного выше края.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Десерт печь при температуре 180 – 200 градусов в течение 20 – 30 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Вынуть, полить медовым сиропом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Для его приготовления развести в чашке мёд с горячей, но не кипящей водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2757,'Подать яблоки к чаю с лимоном.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Филе судака или любой другой белой рыбы пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Затем прокрутить сливочное масло и очищенный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Добавить в рыбный фарш сырое яйцо, молотый перец, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Фарш отбить, кидая его в миску, масса должна стать пышной и пластичной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Сформовать котлеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Каждую смочить во взбитом яйце и обвалять в сухарях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Изделия выложить на доску для разделки и поставить в морозильную камеру на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Для соуса «Тартар» пропустить через пресс зубчики чеснока, маринованные огурцы натереть на мелкой терке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Смешать ингредиенты со сметаной и майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2758,'Котлеты обжарить на растительном масле до образования корочки, выложить на блюдо и подать с соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Сырые куриные яйца перемешать с сахарным песком венчиком или с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Емкость поставить на водяную баню, хорошо помешивать до тех пор, пока масса не увеличится в два-три раза. Огонь – минимальный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Кастрюлю снять с плиты, продолжать взбивать до тех пор, пока тесто не остынет до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'В остывшую массу ввести муку, добавлять её порциями, по столовой ложке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Противень застелить пергаментом, вылить тесто, печь бисквит в течение 15 минут, верх должен немного подрумяниться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Сливочное масло комнатной температуры взбить с остатками сахарного песка, добавить в него хорошо промытую и обсушенную малину, крем перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Готовый бисквит скрутить рулетом вместе с листом пергамента, остудить, развернуть, бумагу удалить, смазать выпечку малиновым вареньем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Выложить крем с ягодами, изделие свернуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Остатки сливочного масла растопить с молоком, добавить какао-порошок и сахарный песок, перемешать, довести до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2759,'Глазурью полить готовый рулет, посыпать шоколадными семечками и поставить в холодильник на 10 часов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'В небольшую емкость насыпать сухие дрожжи, сахарный песок, влить теплую воду, смесь перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'Поставить в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'В глубокую емкость влить подогретое молоко, добавить соль, сахар, сырые желтки, растительное масло, влить дрожжи, все ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'Пшеничную муку просеять, всыпать порциями в жидкую основу, замесить тесто, оно должно быть мягким и липким, масса должна отставать от рук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'Тесто положить в миску, смазанную маслом, верх прикрыть пищевой пленкой, поставить в тепло для подъема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'Через полтора-два часа обмять, накрыть, оставить для второго поднятия.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2760,'Можно убрать тесто на ночь в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2761,'Приготовить из говядины фарш и потушить его на сковороде в течение пяти минут. Головку репчатого лука нарезать тонкими перьями, пропустить через пресс очищенные дольки чеснока, перемешать с фаршем. Потушить еще семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2761,'Помидоры залить кипятком и снять кожицу. Нарезать мякоть кубиками. Добавить в основную массу вместе со специями: паприкой, молотым перцем чили, посолить по вкусу, положить веточку розмарина. Влить четверть стакана воды, тушить десять минут, постоянно помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2761,'Добавить в обжарку томатную пасту, еще немного воды, если масса получилась густоватой. Тушить под крышкой еще пять минут. Отварить пасту почти до готовности, она должна остаться твердой. Выложить на блюдо, добавить фарш с томатами, украсить зеленью укропа, петрушки. Паста «Болоньезе» с говяжьим фаршем готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'В одной емкости перемешать пшеничную муку, какао-порошок, соль и пищевую соду.','https:https://st.vkuso.ru/data/cache/thumb/7a/4a6a0669a4b557a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'В другой – сахарный песок, растопленное сливочное масло, воду, растворимый кофе и лимонный сок.','https:https://st.vkuso.ru/data/cache/thumb/c7/09924fb3e8ad1c7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Соединить обе смеси, жидкие ингредиенты влить в сухие, замесить тесто, оно должно получиться жидковатым.','https:https://st.vkuso.ru/data/cache/thumb/b8/806cc96b5e621b8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Перелить массу в форму, поставить на выпекание на 40 минут, температура приготовления – 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/a4/48cf059556a70a4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Для крема-лазури перемешать молоко, сахар, какао-порошок, воду и растопленное сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Крахмал развести водой отдельно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Шоколадную смесь прогреть, довести до кипения, огонь убавить и ввести раствор крахмала.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Огонь выключить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2762,'Испеченный корж полностью остудить, смазать шоколадным кремом, украсить любыми ягодами и подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Сырые куриные яйца растереть с сахарным песком.','https:https://st.vkuso.ru/data/cache/thumb/7d/91b67686dc3077d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Нарезать сливочное масло или маргарин кусочками, перемешать с небольшим количеством пшеничной муки.','https:https://st.vkuso.ru/data/cache/thumb/5b/63f8884363ad75b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Растереть ингредиенты в крошку руками или порубить ножом.','https:https://st.vkuso.ru/data/cache/thumb/2d/010674a0d78922d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Соединить с яичной массой, перемешать до однородности и добавить жидкий натуральный мёд.','https:https://st.vkuso.ru/data/cache/thumb/d7/b52e7c3779f8cd7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Погасить пищевую соду лимонной кислотой. Все ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Всыпать муку еще раз, замесить тесто. Оно должно хорошо раскатываться и не липнуть к рукам.','https:https://st.vkuso.ru/data/cache/thumb/9d/d39a65fff42049d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Поставить массу в холодильник на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Очистить и измельчить грецкие орехи, ядра порубить ножом.','https:https://st.vkuso.ru/data/cache/thumb/79/980cc2fe5c7d679_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Всыпать сахар, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Вынуть тесто из холодильника, тонко раскатать, лепешку смазать с помощью кисти растительным маслом, посыпать сладкой ореховой смесью.','https:https://st.vkuso.ru/data/cache/thumb/f8/8b78a0b6f9527f8_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Свернуть изделие в рулет.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Обжать, уплотнить, нарезать на кусочки одинакового размера.','https:https://st.vkuso.ru/data/cache/thumb/08/f02562fecbe2a08_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2763,'Готовые рулетики выложить на смазанный маслом противень, поставить в заранее разогретую духовку, печь при температуре 200 градусов в течение 25 – 30 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Помидор нарезаем слайсами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Кабачок нарезаем «шайбой»',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Сыр нарезаем на ломтики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Чеснок нарезаем тонко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Куриное бедро можно нарезать произвольно, но кусочки должны быть маленькими. Кожу от куриного бедра нужно отделить, она не нужна.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Затем куриные кусочки солим, перчим, и посыпаем приправой для курицы. Перемешиваем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Затем добавляем сметану и снова перемешиваем. Убираем в сторону на 30 минут, чтобы куриное мясо чуть пропиталось специями и сметной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'На противень в пергаментом укладываем сначала кабачки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'На эти кабачки укладываем чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Затем укладываем про помощи ложки куриное кусочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Укладываем сыр.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Сверху укладываем помидор.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2764,'Отправляем в духовку до готовности при 200°С, около 40 минут. Смотрите чтобы не подгорело!)',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Перемешать в миске пшеничную муку, молотую корицу, молотый имбирь, какао-порошок, мускатный орех и гвоздику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Отдельно, с помощью миксера, взбить сливочное масло комнатной температуры со свежим очищенным и натертым корнем имбиря.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Влить патоку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Растворить в кипящей воде немного соды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Всыпать в миксер в два этапа сухие ингредиенты, добавить соду в промежутке между ними.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Всё смешать до однородного состояния, добавить кусочки горького шоколада.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Готовое тесто завернуть в пищевую пленку, поставить в холодильник на два часа или больше.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Сформовать из охлажденного теста шарики, обвалять их в коричневом сахаре, выложить на противень на расстоянии друг от друга.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Разогреть духовку до 180 градусов, печь изделия в течение 10 – 15 минут, пока печенье не потрескается.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2765,'Перед подачей выпечку остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Помидоры средней величины поместить в кипящую воду на две-три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Кожицу снять, семена удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Очистить морковь, порубить её вместе с красным репчатым луком, сладким красным перцем и мякотью томатов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'На оливковом масле обжарить целые зубчики чеснока, затем их вынуть и выбросить, для блюда понадобится только аромат этого острого овоща.','https:https://st.vkuso.ru/data/cache/thumb/74/21bb7804e192274_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Огонь уменьшить, добавить подготовленные овощи, все вместе тушить до мягкости томатов.','https:https://st.vkuso.ru/data/cache/thumb/00/bd36778cf8cae00_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Блюдо посолить и поперчить по вкусу, в процессе прогревания перемешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'В смесь всыпать крупу для кускус, перемешать, влить в сковороду горячую воду.','https:https://st.vkuso.ru/data/cache/thumb/7d/4f38e62b986ef7d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Кушанье тушить на тихом огне еще 10 – 12 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Отцедить макароны с помощью дуршлага и заправить их небольшим количеством оливкового масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Время приготовления может быть разным, чтобы не ошибиться – лучше прочитать то, что написано на упаковке крупы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2766,'Порубить зелень петрушки, добавить в почти готовую кашу, массу перемешать и подать на стол.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Крупу залить кипящей водой на 5 – 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Приготовить фарш из куриного мяса, перемешать его с отдельно взбитым сырым яйцом, мелко нарезанным луком, толченым чесноком, полуготовой гречкой, специями и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'В качестве приправ можно использовать смесь сладкой молотой паприки и жгучего перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Сформовать небольшие биточки и обжарить их на небольшом количестве масла или другого жира.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Влить в кастрюлю полстакана воды, разбавленную сметану или молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Довести смесь до кипения, уложить биточки слоями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2767,'Готовить блюдо на тихом огне в течение 20 – 25 минут до готовности крупы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Сметану отвесить на ночь в ситцевой ткани или в марле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Жидкость должна отцедиться, а масса стать густой и плотной.','https:https://st.vkuso.ru/data/cache/thumb/88/1f75ec502feaa88_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Коньяк, ром или вино прогреть вместе с водой, замочить в смеси чернослив на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Приготовить вафельные трубочки со сгущенкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Измельчить их в крошку, всыпать в стакан.','https:https://st.vkuso.ru/data/cache/thumb/44/05fa39a4299ee44_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Смешать вафли с какао-порошком, кокосовой стружкой и растопленным на плите или в микроволновой печи сливочным маслом.','https:https://st.vkuso.ru/data/cache/thumb/10/d764bb08a659910_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Разогреть духовой шкаф до 170 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Форму для выпекания застелить пергаментом, насыпать основу, утрамбовать тем же стаканом.','https:https://st.vkuso.ru/data/cache/thumb/55/a5e777782e45855_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Поставить изделие в духовку на семь минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Для крема взбить сметану с сахарным песком, ингредиенты должны полностью соединиться.','https:https://st.vkuso.ru/data/cache/thumb/83/a4014e88afd6a83_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Горький шоколад растопить в микроволновке или на водяной бане, влить его в сметану, добавить гранулированный кофе и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/73/a31b357e2278f73_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Взбивать смесь миксером или венчиком, добавляя сырые куриные яйца по одному.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Масса должна получиться однородной, но без пузырьков.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'В последнюю очередь всыпать муку и перемешать смесь лопаткой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Разрезать пополам чернослив, выложить плоды на основу из вафель.','https:https://st.vkuso.ru/data/cache/thumb/99/76d4637437c5799_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Сверху вылить сметанный крем.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Форму встряхнуть, пузырьки должны уйти.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Поставить изделие в нагретую духовку, печь при температуре 160 градусов в течение 40 – 45 минут.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'У готовой выпечки должна остаться сыроватая середина.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2768,'Остудить чизкейк в духовке, затем поставить в холодильник на пять-шесть часов, он должен стать плотным.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2769,'Смешать немного воды и сырой яичный белок, не взбивать. Обмакнуть свежую клюкву в эту смесь, затем обвалять в сахарном песке со всех сторон. Сушить ягоды при комнатной температуре в течение двух часов, можно воспользоваться мелкой решеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Предварительно отварить клубни картофеля и куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'То и другое нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Так же измельчить свежий огурец, кожицу можно снять, если она горчит.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Нарезать копченую колбасу, ветчину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Зеленый лук и укроп мелко порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Для заправки перемешать горчицу с яичным желтком, согреть сметану до комнатной температуры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Перемешать в миске подготовленные ингредиенты с зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Отдельно соединить сметану с охлажденной кипяченой водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2770,'Налить смесь в миску и приправить блюдо горчицей с желтком по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Нарезать соломкой репчатый лук, измельчить бекон, разрезать пополам помидоры черри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Отделить сырые белки от желтков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Отварить спагетти в подсоленной воде в течение 11 минут, продукт должен остаться сыроватым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Налить такое же масло в сковороду, прогреть на огне средней мощности, обжарить лук и бекон в течение полутора-двух минут, до образования золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/fd/ac07e9d4e57d0fd_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Влить в сковороду сливки средней жирности, перемешать, прогревать минуту.','https:https://st.vkuso.ru/data/cache/thumb/9f/713ac2e1fe1459f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Добавить полуготовые спагетти, прогреть на тихом огне в течение полминуты.','https:https://st.vkuso.ru/data/cache/thumb/6f/9c9d0c4f559c56f_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Всыпать прованские травы, перемешать, посолить и поперчить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/10/c74b3abd8dc7d10_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Убрать блюдо с огня, ввести желток и еще раз перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2771,'Подавать блюдо с помидорами черри, тертым сыром «Пармезан» и зеленым базиликом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Сухофрукты, например, чернослив, залить кипящей водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Отдельно растопить сливочное масло и отделить белки от желтков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Протереть творог через сито для получения воздушной текстуры, добавить сырые желтки, масло, сахарный песок, манку, тертую цедру лимона или апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Вымыть распаренные сухофрукты, обсушить с помощью бумажного полотенца, измельчить, смешать с творогом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Взбить сырые белки в плотную пену, аккуратно ввести творог, перемешать движениями снизу вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Массу выложить в смазанные маслом и посыпанные панировочными сухарями формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2772,'Печь блюдо в течение 25 минут при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Овощ промыть, нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Если плоды горчат, то их предварительно вымачивают в воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Кубики подсолить и оставить в тарелке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'В сотейнике обжарить рубленый репчатый лук на свином жире.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Добавить баклажаны и паприку, перемешать, залить томатной пастой и потушить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Сметану загустить пшеничной мукой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2773,'Вылить соус на овощи и потушить все вместе 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Просеять в миску пшеничную муку, соль и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Несоленое мягкое сливочное масло взбить с сахарным песком (200 г) до побеления, для этого потребуется три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Скорость миксера уменьшить, вбить сырое куриное яйцо, влить молоко и добавить ваниль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Постепенно, порциями, всыпать мучную смесь, должно получиться жидкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Смазать форму маслом, вылить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Сверху выложить вишни без косточек, близко друг к другу, чтобы ягоды образовали сплошной «ковер».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Присыпать пирог остатками сахарного песка и поставить блюдо в заранее разогретую до 180 градусов духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Печь до золотистого цвета в течение часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2774,'Остудить на решетке, не вынимая из формы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'Крупно нарезать шампиньоны, лук мелко нарезать, нарубить мелко чеснок и кинзу, сыр натереть на мелкой терке. Яблочный укус развести в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'Разогреть сковороду на сильном огне. Добавить растительное масло, выложить шампиньоны на сковороду и посолить. Жарить 3-5 мин.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'В ту же сковороду добавить растительное и 5 гр сливочного масла (1). Добавить лук, жарить 2-3 мин на сильном огне. Добавить чеснок, жарить 1 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'Всыпать рис для ризотто, обжарить помешивая 30 сек. Влить яблочный уксус, разведенный с водой. Готовить, помешивая до тех пор, пока вода не испарится.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'Добавить еще 2 половника бульона, готовить до тех пор, пока бульон не выпарится.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'Продолжать также добавлять по 2 половника бульона и готовить так до тех пор, пока рис не приготовится.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2775,'В конце добавить 15 гр сливочного масла (2), сыр, кинзу и соль по вкусу, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Промыть свинину с ребрышками, нарезать порционно, переложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Залить холодной водой, довести до кипения, огонь уменьшить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Бульон должен слабо кипеть в течение часа, пену снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Свиное сало вымыть, обсушить, мелко нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Покрошить копченое свиное сало.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Оба продукта выложить на сковороду, отправить на плиту, вытопить жир.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Репчатый лук очистить, вымыть, обсушить, нарезать, выложить в сало вместе с тертой морковью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Пассеровать при постоянном помешивании.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Добавить квашеную капусту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Тушить до готовности, капуста должна стать мягкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Очистить и обсушить еще немного моркови, натереть, добавить в капусту с салом, тушить все вместе десять или пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Добавить муку, подержать минуту, перемешать, тушить две минуты.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Добавить в мясной бульон с костями лавровый лист, душистый и черный перец.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Всыпать кубики сырого картофеля, варить пять или семь минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Добавить заправку.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Также всыпать нарезанный корень петрушки.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'За пять минут до окончания приготовления всыпать измельченный вместе с зеленью чеснок.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Огонь погасить, дать супу постоять под крышкой два или три часа.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2776,'Можно оставить на ночь.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Очистить от кожуры репчатый лук и морковь, нарезать кубиками, обжарить на смальце в казане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Промыть пшено, добавить в овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Очистить и промыть картофель, крупно нарезать, добавить в основную массу, жарить все вместе две или три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Влить кипяток, всыпать лавровый лист и молотую паприку, не солить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Варить пятнадцать минут на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Добавить крупно нашинкованную капусту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2777,'Добавить соль, сахар, зелень, сушеную или свежую, потомить семь или десять минут на среднем огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2778,'Растереть сливочное масло комнатной температуры с сахаром. Добавить соль и растопленный горький шоколад. Взбить в плотную пену яичные белки с оставшимся сахаром. Желтки смешать с шоколадной массой, добавить взбитые белки и осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2778,'Смешать муку и ваниль, всыпать разрыхлитель, просеять в готовую массу и снова перемешать. Должно получиться негустое тесто. Смазать сливочным маслом форму для выпечки, печь корж в течение 30 – 40 минут в разогретой до 160 градусов духовке. Готовый бисквит остудить, обрезать края на 1,5–2 см. Пропитать выпечку любым ликером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2778,'Замочить столовую ложку желатина в четверти стакана сливок. Черный шоколад с маслом прогреть на водяной бане до растворения, влить распущенный желатин, перемешать. Снять с огня, влить четверть стакана ликера, дать немного остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2778,'Взбить оставшиеся сливки в крепкую пену. Смешать шоколадную смесь и сливки, вылить на корж. Бортики формы выложить бумагой для выпечки или плотной пленкой, в середину положить корж и залить муссом из черного шоколада. Поставить десерт в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2778,'Приготовить, таким же образом, мусс из молочного и белого шоколада. Поочередно залить слои в форму.  Для глазури: довести до кипения сливки с маслом, растворить в нем белый шоколад. Вылить смесь на торт, жидкость должна растечься по поверхности ровным слоем. Торт «Три шоколада» в белой глазури готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Выложить в кастрюлю морковь, целую луковицу и свиные ребрышки.','https:https://st.vkuso.ru/data/cache/thumb/46/13c3a1de62ba446_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Довести до кипения, варить бульон до готовности, пену снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Очистить и мелко нарезать картофель.','https:https://st.vkuso.ru/data/cache/thumb/f7/52f6cd5dcf133f7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Нарезать квашеную капусту.','https:https://st.vkuso.ru/data/cache/thumb/ff/a746d9fa4a1b4ff_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Промыть несколько раз пшено, залить на пять минут свежей порцией воды, жидкость слить.','https:https://st.vkuso.ru/data/cache/thumb/11/3e3987624f45f11_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'В почти готовый бульон выложить картофель, пшено.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Приготовить зажарку из сала, репчатого лука, тертой моркови.','https:https://st.vkuso.ru/data/cache/thumb/30/3bcc214033b3330_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'В конце влить томатный сок.','https:https://st.vkuso.ru/data/cache/thumb/d9/2ad65e2386b7dd9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'В капустняк всыпать квашеную капусту.','https:https://st.vkuso.ru/data/cache/thumb/40/e72b2e7b762c240_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Очистить, вымыть и порубить лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Свежую капусту натереть на мелкой терке, добавить в суп, довести до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Из капустняка вынуть часть картофеля, размять и вернуть в кастрюлю.','https:https://st.vkuso.ru/data/cache/thumb/63/900e37c6bd46b63_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2779,'Добавить обжарку, соль по вкусу, лавровый лист, перец, рубленую зелень.','https:https://st.vkuso.ru/data/cache/thumb/a4/7923d31de022ba4_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Свинину обжарить на сильном огне до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Отварить очищенный картофель целиком, вынуть, размять вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Обжарить до прозрачности репчатый лук с салом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Перебрать и промыть пшено несколько раз, отварить до полуготовности в отдельной емкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Квашеную капусту и пшено пропустить через мясорубку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'По желанию добавить морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Продукты переложить в кастрюлю, где варился картофель: сначала мясо, варить десять или пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Далее – сам толченый картофель, капусту с пшеном.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'В обжарку с луком добавить томатную пасту, перемешать и добавить в суп.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2780,'Все вместе варить пятнадцать или двадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'В кастрюлю влить воду, всыпать перец-горошек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Репчатый лук очистить, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Пересыпать в кастрюлю с водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Через пять минут добавить картофель, нарезанный кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Отдельно промыть пшено горячей водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Всыпать в кипящий бульон, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Квашеную капусту промыть, нарезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Добавить в кастрюлю, картофель в это время уже должен быть мягким.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Капуста должна покипеть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Промыть и натереть морковь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Обжарить на сковороде с растительным маслом, помешивать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'В конце приготовления заправить обжарку томатной пастой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Перемешать, влить воду, тушить пять минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Перемешать, добавить соль и любимые специи.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Перелить обжарку в кастрюлю.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Чеснок очистить и нарезать полосками.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Заправить суп, досолить по вкусу, добавить лавровый лист.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2781,'Варить все вместе десять минут.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'Сварить куриный бульон из супового набора. Время варки – сорок минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'По вкусу добавить соль и луковицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'В готовый суп добавить картофель, пшенную крупу, варить все вместе десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'Обжарить тертую морковь и накрошенный лук отдельно, на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'Нашинковать свежую белокочанную капусту, пересыпать в суп вместе со стручковой фасолью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'Варить пятнадцать минут. Досолить, если нужно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2782,'Перелить обжарку, поперчить, всыпать рубленую зелень. Варить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Заранее замочить в холодной воде на шесть или семь часов, отварить красную фасоль. Время варки до готовности от пятидесяти до шестидесяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Репчатый лук очистить и мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Обжарить на растительном масле в казане, время – от трех до пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Всыпать муку, обжарить минуту при постоянном помешивании.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Добавить квашеную капусту, перемешать, жарить две или три минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Влить кипяток, он должен скрыть продукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Довести до кипения, тушить под крышкой на тихом огне пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Добавить томатную пасту, паприку, лавровый лист.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Перемешать, тушить десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Нарезать кружками копченые колбаски.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Очистить и пропустить через пресс чеснок.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Зелень мелко нарезать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Добавить колбаски и отваренную фасоль. Перемешать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2783,'Влить полтора литра кипящей воды, довести до кипения, варить суп пять минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Свинину постную или жирную вымыть, удалить прожилки, варить со специями, любимыми пряностями для супа, лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Пшено промыть, залить на час холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Очистить, вымыть и нарезать картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Прогреть на сковороде растительное масло без запаха, обжарить морковь и лук на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Через четыре минуты добавить пшено и нарезанный картофель.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Квашеную капусту, отжать от рассола, переложить в сотейник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Добавить специи, соль, томатную пасту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Влить бульон.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Мясо нарезать и также положить в капустняк.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2784,'Варить на тихом огне от двадцати пяти минут до получаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Налить в чашу мультиварки подсолнечное масло, выставить режим «Жарка-овощи», температура приготовления – 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Мясо хорошо вымыть, промыть проточной водой, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выложить в чашу, жарить под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Время от времени крышку открывать, содержимое чаши помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Репчатый лук нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Мультиварку с мясом выключить кнопкой «подогрев-отмена».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Мясо посолить по вкусу, перемешать. Всыпать лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выставить программу «Жарка-овощи», температура 140 градусов, довести лук до золотого цвета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Натереть морковь, добавить в основную массу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Обжарить все вместе до полуготовности моркови.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выключить прибор кнопкой «подогрев-отмена», влить воду.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выставить режим «Жарка-мясо», температура 120 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Довести мясо до полной готовности.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'В кастрюлю, отдельно, выложить нарезанный картофель.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Влить воду, посолить. Варить на плите до готовности.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Продукт переложить в другую емкость.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Чашу с супом выключить, добавить воду, влить томатный сок.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выставить режим «варка-обычная».',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Белокочанную капусту пропустить через мясорубку. Добавить в чашу с супом.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Всыпать помытое пшено. Влить воду.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Выставить режим «Каша», варить до готовности пшена.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Картофель без жидкости растолочь.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Влить слитую воду, перемешать. Масса должна быть похожа на обычное пюре.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Добавить еще немного жидкости, перемешать.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Массу перелить в чашу мультиварки, добавить перец, соль, лавровый лист.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Долить еще немного воды.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2785,'Суп довести до кипения, выключить кнопкой «подогрев-отмена».',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Из тыквы удалить семена, очистить кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Мякоть натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Нарезать укроп и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Продукты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Влить масло в сковороду, прогреть. Лучше использовать посуду с антипригарным покрытием.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Выкладывать массу небольшой ложкой, формовать лепешки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2786,'Жарить по две минуты с каждой стороны на среднем огне до получения корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2787,'Картофель и тыкву очистить и промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2787,'Натереть мякоть, отжать лишнюю жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2787,'Добавить кукурузную или пшеничную муку, молотый мускат, сырое куриное яйцо, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2787,'Ингредиенты перемешать до однородного состояния, оставить массу для настаивания на пять или десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2787,'Прогреть сковороду с растительным маслом, выкладывать оладьи, жарить с двух сторон до получения золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Очистить и промыть тыквы, картофель, пучок петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Овощи натереть, жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Добавить рубленую зелень, соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Выложить оладьи на решетку пароварки, время приготовления – сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2788,'Другой вариант – обжарить на растительном масле до получения золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2789,'Смешать растительное и сливочное масло, обжарить нарезанные кубиками луковицы и натертую морковь.  Добавить в обжарку готовый куриный фарш, специи, массу вымесить до однородного состояния и выложить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Сырой лук всыпать в фарш.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2789,'Отдельно отварить гречневую крупу, охладить, добавить очищенные от кожуры и натертые яблоки, тертый полутвердый сыр, перемешать. Массу выложить в форму поверх куриного фарша с овощами, немного примять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2789,'Печь около получаса в духовке при температуре 200 градусов. Запеканку из гречки с куриным фаршем вынуть, посыпать тертым сыром и прогреть еще пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2790,'Тыквенную мякоть натереть на терке, средней или мелкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2790,'Вбить сырое куриное яйцо, муку, картофельный крахмал, кориандр, зиру, молотый черный перец, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2790,'Застелить пергаментом противень, смазать маргарином или маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2790,'Выложить драники ложкой. Время запекания – тридцать пять минут, температура – 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2790,'Подавать теплыми или горячими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2791,'Тыквенную мякоть натереть, удалив жесткие волокна и кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2791,'В яйцо всыпать манку, сахарный песок, муку, тертую тыкву, добавить ванилин или корицу, немного пищевой соды, погашенной уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2791,'Готовую массу оставить на десять или пятнадцать минут для набухания крупы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2791,'Жарить драники на растительном масле с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2792,'Натереть на терке картофель, репчатый лук, тыкву.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2792,'Добавить муку и специи, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2792,'Часть репчатого лука нарезать и добавить в куриный фарш, соль и молотый перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2792,'Прогреть сковороду с маслом, выложить тесто из овощей в виде лепешек, сверху – фарш, затем оставшуюся овощную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2792,'Жарить до готовности, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2793,'Приготовить смесь из яиц, муки, сахара и специй.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2793,'Размороженную тертую тыкву добавить в тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2793,'Массу пробить блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2793,'Выложить тесто на горячую сковороду, жарить до корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2793,'Подать к столу со сметаной или медом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2794,'Кабачковую и тыквенную мякоть натереть, слить лишнюю жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2794,'Вбить сырые яйца, всыпать специи и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2794,'Ингредиенты перемешать, выложить на смазанную сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2794,'Обжарить до корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2794,'Подать со сметаной или сметанным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Очистить тыкву.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Мякоть натереть соломкой, добавить соль, перемешать и оставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Натереть очищенный картофель и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Тыквенную мякоть отжать, перемешать с луком и картофелем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Вбить яйцо, всыпать пшеничную муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Заправить массу смесью перцев, добавить рубленый чеснок, рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2795,'Жарить драники на горячем масле с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Тыкву и кабачки вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Удалить сердцевину и кожуру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Тыкву очистить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Овощи натереть. Отжать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Зелень обсушить, добавить специи, пшеничную муку и тыквенное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Продукты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Жарить оладьи на горячем подсолнечном масле по две минуты с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Для приготовления соуса порубить укроп, мяту, зеленый лук.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2796,'Натереть свежий огурец, отжать, перемешать с йогуртом, добавить зелень, специи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Тыкву вымыть, очистить от сердцевины, мякоть натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Вымыть и очистить яблоки, натереть, смешать с тыквой, всыпать сахар по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Промыть лимон горячей водой, обтереть, снять цедру мелкой теркой, только желтый слой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Влить подогретый кефир, всыпать разрыхлитель, ввести муку порциями, каждый раз перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Обжарить драники из густого теста на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2797,'Довести до готовности под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Оригинальное сочетание вкусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Мякоть тыквы натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Очистить и натереть картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Зелень вымыть, обсушить, нарубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Натереть твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Продукты перемешать, посолить, добавить специи, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Всыпать муку, перемешать еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2798,'Испечь на масле оладьи до румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Картофель, тыкву, репчатый лук очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Картофель и тыкву натереть, лук порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Шампиньоны вымыть, очистить, натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Продукты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Обсушить вымытую зелень, удалить черенки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Добавить зелень к овощам, всыпать муку, специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2799,'Драники обжарить со всех сторон, огонь – средний. Изделия должны хорошо пропечься.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Очистить и вымыть клубни картофеля, очистить лук, тыкву, чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Тыкву и картофель натереть, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Превратить в кашицу лук при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Добавить фарш, вбить яйца, всыпать специи и рубленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Массу перемешать, всыпать пшеничную муку и манку, оставить на полчаса для набухания крупы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2800,'Приготовить драники круглой формы, подать теплыми.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Крупу замочить в воде на два или три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Далее воду слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Мелко покрошить лук и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Обжарить овощи на оливковом масле в посуде с толстыми стенками. Время приготовления – от двух до трех минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Всыпать перловку, перемешать, потомить пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Влить лимонный сок или вино, потушить до впитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Вливать в смесь частями воду или овощной бульон, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2801,'Добавить шпинат, сыр «Пармезан», любые орехи, перемешать, посолить и поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Перловку залить на ночь водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Покрошить лук-шалот, жарить на тихом огне, на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Слить жидкость от перловой крупы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Добавить продукт на сковороду, жарить несколько минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Влить белое сухое вино, проварить до испарения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Добавить в несколько приемов бульон или воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'В конце посыпать кашу тертым сыром «Пармезан». Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2802,'Соль и перец молотый – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Перловку промыть холодной проточной водой. Откинуть на сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Очистить и нарезать кубиками чеснок и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Обжарить овощи на растительном масле до получения золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/6e/2d7ae7b9b4e566e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Добавить перловку, жарить все вместе минуту или две.','https:https://st.vkuso.ru/data/cache/thumb/5e/9e1fdb99fe5235e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Влить белое вино, выпарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Крупу перемешать, влить в несколько приемов рыбный бульон.','https:https://st.vkuso.ru/data/cache/thumb/4e/ddbf6a31f8eab4e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Довести до полуготовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Смесь морепродуктов разморозить, вымыть, удалить налет, хитин.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Обжарить на сливочном масле.','https:https://st.vkuso.ru/data/cache/thumb/77/038bc3eadaed877_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Влить томаты в собственном соку, посолить, добавить чеснок, молотый перец и сахарный песок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2803,'Приправить листочками базилика, сливочным маслом, перемешать и влить еще немного рыбного бульона.','https:https://st.vkuso.ru/data/cache/thumb/e1/d7a2a7aaf1b40e1_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2804,'Нарезать багет наискосок, можно заменить батоном или хлебом для тостов, вырезать из хлеба треугольники, кружки, квадраты, ромбы. Копченую или малосольную семгу нарезать тонкими ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2804,'Вымыть, обсушить и тонко нарезать лимон, кружками или полукружьями. Слить жидкость от консервированных оливок, обсушить их на бумажных полотенцах. Листья зеленого салата положить в холодную воду на полчаса или час. Затем откинуть на дуршлаг, дать воде стечь, листья обсушить на полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2804,'На каждый кусочек хлеба выложить по листику салата и ломтику рыбы. На шпажки насадить ломтики лимона с оливками и воткнуть в бутерброд с соленой семгой. Украсить зеленью петрушки, укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2805,'Сыр нарезаем на ломтики, или же его можно натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2805,'Лук нарезаем соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2805,'Болгарский перец нарезаем кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2805,'Пангасиус промываем, обсушиваем. Затем солим, перчим',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2805,'Я рекомендую не смазывать растительным маслом пергамент, так как у меня слегка подгорело, но только по краям, под рыбой все хорошо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Прогреть сотейник с оливковым маслом на дне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Репчатый лук нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Покрошить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Обжарить овощи.','https:https://st.vkuso.ru/data/cache/thumb/d9/d93b43a626378d9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Всыпать перловку, прогреть.','https:https://st.vkuso.ru/data/cache/thumb/2a/11aa2aad8eb4c2a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Влить немного белого вина, всыпать тимьян. Потушить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Влить воду, варить до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Индюшачью печень нарезать кусочками, выложить в емкость, добавить соль, оливковое масло, тимьян, перец, розмарин. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/dc/1c7a4c5e7097edc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Натереть на терке грана падано.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Под сотейником с крупой огонь убавить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Жарить печенку на сковороде с растительным маслом.','https:https://st.vkuso.ru/data/cache/thumb/fe/9c2f72ed84a8afe_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Снять с огня, подержать под крышкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'В перловку влить сливки, проварить и снять с огня.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Добавить твердый и сливочный сыр, перемешать, поперчить, посолить.','https:https://st.vkuso.ru/data/cache/thumb/27/6d230fd2c547627_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2806,'Перловку выложить на тарелку, печень – сверху, полить соусом из сковороды.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Натереть лук и картофель на терке. Можно использовать кухонный комбайн.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Отжать картофельную массу в марле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Перемешать с рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Вбить сырое яйцо, всыпать муку. Замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Влить сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Еще одну луковицу нашинковать, соединить с фаршем, вбить яйцо, посолить и поперчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Массу перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Жарить оладьи на растительном масле, выложить на тесто фарш, третий слой – тоже тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Операции можно проделывать руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Сначала обжарить с одной стороны, затем изделия перевернуть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2807,'Блюдо допечь до готовности под крышкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Филе нарезать брусками, обжарить на прогретой сковороде, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Отдельно обжарить на масле нашинкованный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Натереть картофель на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Лишнюю жидкость отжать, вбить сырые яйца, всыпать муку, соль, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Покрошить зелень, натереть твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Прогреть растительное масло на сковороде, выложить картофель ровным слоем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Обжарить, перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Выложить на половину слой мяса, луковую обжарку, тертый сыр и зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2808,'Прикрыть начинку вторым слоем при помощи лопатки. Обжарить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Мясной фарш посыпать приправами и подсолить, добавить рубленую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Нарезать репчатый лук, чеснок, перемешать с мясом, долить немного воды и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Натереть картофель, отжать жидкость через марлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Всыпать соль и подходящие приправы для картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Поделить массу из картофеля и фарш на равное количество частей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Из картофельного теста скатать шар, расплющить, поместить фарш в центр, завернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'На сковороду налить растительное масло, подогреть, поместить несколько изделий, обжарить до легкой корочки и поместить на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'Полить сметаной, печь полчаса при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2809,'При подаче посыпать нарезанным зеленым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Картофель натереть на мелкой терке, сок отжать через марлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Дать жидкости постоять, крахмал, осевший на дно, добавить в картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Всыпать муку, соль, вбить яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Массу хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Часть нарезанного лука спассеровать на масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Пассерованный лук добавить в картофельную массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Перемешать, соль и молотый перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Сформовать котлеты из фарша, закрытые со всех сторон картофелем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Жарить до золотистой корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Переложить изделия в другую емкость, влить бульон, он должен полностью покрыть колдуны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2810,'Потушить полчаса на тихом огне.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Картофель измельчить любым способом, отжать жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Картофельную массу перемешать с мясным фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Добавить рубленую зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Влить сметану, яйцо, всыпать перец, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Добавить нарезанный репчатый лук, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Раскалить масло на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Тесто разделить на шарики мокрыми руками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Обжарить на сковороде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Шарики переложить в форму для запекания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2811,'Поставить в духовой шкаф на полчаса, температура – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Картофель измельчить при помощи комбайна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Отжать сок, дать постоять, крахмал вернуть в картофельную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Вбить сырые куриные яйца, посолить и поперчить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Мелко нашинковать белокочанную капусту, обжарить с большим количеством масла, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'В конце приготовления добавить нарезанный репчатый лук, обжарить все вместе, подержать пять минут под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Перемешать картофель с остывшими овощами, сформовать шарики, обжарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2812,'Выложить изделия на противень, печь полчаса при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Картофель очистить, измельчить, жидкость отжать и дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Осевший крахмал добавить в картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Массу посолить, всыпать немного куркумы, вбить яйцо. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Нарезать лук, добавить в фарш, добавить немного воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'В емкость мультиварки влить растительное масло, выставить режим «Выпечка» или «Мультиповар».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Сформовать шарики из картофеля руками, в середины поместить начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2813,'Изделия запекать по восемь минут с каждой стороны, под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'Персики мелко нарезать и переложить в кастрюлю.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'В глубокую миску всыпать сахар, соль, ванильный сахар, добавить лимонный сок и теплую воду. Хорошо перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'Форму для выпечки смазать растительным маслом, дно застелить бумагой для выпечки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'Перед приготовлением кокосового крема поставьте банки с кокосовым молоком в холодильник на ночь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'Бисквит разрезать на 3 коржа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2814,'Накрыть вторым коржом, пропитать его сиропом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2815,'Протереть творог через сито. Замочить изюм без косточек в теплой воде, обсушить на полотенце. Взбить яйца, всыпать манную крупу, предварительно замоченную в молоке, сахарный песок и разрыхлитель, ванилин из пакетика. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2815,'Смазать сливочным маслом противень, выложить изюм, сверху – творог. Печь почти до готовности в духовом шкафу. Творожную запеканку «Объеденье» вынуть, смазать верх сметаной и снова запечь до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2816,'Смешать сливочное масло комнатной температуры с любыми рублеными орехами, сахаром и какао-порошком. Раскрошить готовое печенье, добавить в массу и перемешать, выложить на пергамент тонким слоем, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2816,'Мягкое сливочное масло перемешать с сахарной пудрой и кокосовой стружкой до однородного состояния, выложить на слой из печенья. С помощью пергамента скрутить массу в рулет, поставить в холод. При подаче шоколадно-кокосовый рулет нарезать кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2817,'Отварить и очистить куриные яйца. Отделить белки от желтков, первые нарезать соломкой, вторые натереть на мелкой терке. Охлажденные крабовые палочки и сливочное масло натереть по отдельности. Также натереть очищенное от кожицы и семян кисло-сладкое яблоко плавленый сырок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2817,'Выложить салат послойно, каждый слой промазывать майонезом и солить по вкусу. Последовательность: белки, крабовые палочки, сыр, масло, яблоко, желтки, крабовые палочки. Готовый салат «Крабовая шубка» поставить в холодильник на 2 – 3 часа, блюдо должно пропитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2818,'Филе курицы отварить и нарезать на небольшие кусочки, помидор – крупными дольками. Разрезать пополам авокадо, убрать косточку, счистить кожицу. Мякоть нарезать ломтиками и сбрызнуть лимонным соком, она не должна потемнеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2818,'Нарезать соломкой редис, порвать руками листья зеленого салата. Все ингредиенты смешать, заправить йогуртом без цветовых добавок или нежирной сметаной. Калифорнийский куриный салат с авокадо готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2819,'Из курицы или окорочков удалить кости, снять кожицу. Нарезать филе на средние кусочки и положить в емкость. Посыпать солью, перцем, давленым чесноком. Всыпать пакетик сухого желатина, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2819,'Взять использованный пакет из-под молока или сока с фольгой внутри, сложить в него куриное мясо, верх пакета закрыть пленкой. Варить в кастрюле с водой в течение полутора часов, уровень мяса в пакете должен совпадать с уровнем воды в емкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2819,'Пакет вынуть, полностью остудить в холодном месте. Через  8 – 12 часов коробку разрезать, подать ветчину, порезав на ломтики. Нежная куриная ветчина, приготовленная в домашних условиях, готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2820,'Отварить куриные филе, охладить и нарезать кубиками. Так же поступить с брокколи, в отваренном виде капусту разобрать на соцветия. Нарезать сыр ленточками или кубиками. На дно формы для запекания выложить веточки любой зелени, брокколи, маринованные шампиньоны, каперсы, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2820,'Отдельно растворить желатин в небольшом количестве теплого куриного бульона. Массу охладить, залить ассорти и поставить в холод на 3 – 4 часа. При полном застывании опустить форму на 3 – 4 секунды в горячую воду и перевернуть на тарелку. При подаче закусочное заливное ассорти украсить дольками помидоров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2821,'Хорошо вымыть говядину или свинину с косточкой. Залить водой, варить до готовности. Очищенную свеклу нарезать соломкой. Разогреть на сковороде растительное масло, добавить рубленый репчатый лук, морковь и свеклу, смесь жарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2821,'Добавить нарезанную мякоть помидора без кожицы, томатную пасту, перемешать. Влить стакан бульона, всыпать нарезанный сладкий болгарский перец и сахарный песок. Массу потушить в течение 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2821,'Очистить клубни картофеля и варить в бульоне почти до готовности. Нашинковать белокочанную капусту, всыпать в суп, затем влить овощную обжарку, посыпать рубленой зеленью укропа и петрушки. Дать покипеть пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2821,'Порезать и обжарить кусочек копченого сала, затем добавить в борщ вместе с давленым зубчиком чеснока. Выключить огонь и дать постоять блюду несколько минут под крышкой. Подать со сметаной. Вкуснейший украинский борщ с копченым салом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2822,'Для приготовления бисквита смешать одно яйцо и 4 желтка, кефир, растертый в пудру сахарозаменитель и разрыхлитель для теста. Добавить ванилин на кончике ножа, кукурузный крахмал. Массу взбить с помощью миксера до однородного состояния. Вылить в смазанную форму и выпечь до готовности, проверить зубочисткой: если она останется сухой, то выпечка готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2822,'При готовности корж вынуть из духовки, остудить, можно разрезать пополам по горизонтали. Для желе сварить какао, кипятить пять минут, до легкого загустения. Желатин замочить на два часа в молоке, прогреть и влить в какао. Для приготовления суфле взбить белки в легкую пену, добавить сахарозаменитель, протертый в пудру, влить лимонный сок. Желатин также предварительно замочить на два часа в молоке, прогреть и остудить, аккуратно влить в белки, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2822,'Собрать торт: вылить в форму часть шоколадного желе, дать немного застыть в холодильнике. Выложить сверху суфле, снова убрать в холод на 15 минут. Выложить бисквит, также пропитанный желе, затем влить его остатки. Десерт поставить в холодильник на 1,5 – 2 часа. Он получится в перевернутом виде. Выложить торт на блюдо. Украсить торт «птичье молоко» диетический по желанию: взбитыми сливками, зефиром, цветным мармеладом, шоколадными фигурками, цветной кулинарной посыпкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2823,'Натереть сыр и морковь. Добавить сырые яйца, сметану, просеянную пшеничную муку. Выпечь морковные оладьи на растительном масле, обжаривать с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'Очистить грушу и нарезать на мелкие кусочки. В сотейнике прогреть небольшое количество воды с сахаром до золотистого цвета, в полученный сироп долить еще немного горячей воды. Всыпать грушу и проварить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'При готовности взбить блендером в однородную массу. Яичные желтки взбить миксером, добавить часть грушевого сиропа. Белки взбить в пену и влить оставшийся сироп, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'В отдельной посуде смешать по трети от взбитых белков и желтков, добавить картофельный крахмал, соду, лимонную кислоту, перемешать. Массу выложить в застеленную пергаментом форму, печь в течение 12 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'В оставшиеся взбитые желтки добавить крахмал. Молоко разогреть в сотейнике, до кипения не доводить. Перелить немного молока во взбитые желтки, перемешать. Массу перелить в молоко и варить крем на среднем огне, постоянно помешивая, чтобы яйца не свернулись.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'Загустевший крем с появившимися пузырьками снять с огня. Смешать ложку желатина в пяти ложках воды, дать набухнуть и добавить в крем. Перемешать и охладить, добавить йогурт, остатки взбитых белков, перемешать. Корж выложить на дно формы, вылить сверху крем и поставить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'Груши очистить от кожицы и разрезать пополам. Сварить в сотейнике сироп из сахара и воды, прогревать до золотистого цвета, добавить еще немного горячей воды. Положить половинки груш и варить 10 минут под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2824,'Через пять минут, после начала прогревания, плоды перевернуть. Вынуть из сиропа, остудить. Жидкость уварить, добавить желатин. Груши разрезать на тонкие пластинки и выложить на торт. Полить сиропом с желатином, снова убрать в холодильник. Бисквитный торт «Грушево-карамельный» готов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2825,'Смешать тахини с йогуртом без вкусовых и цветовых добавок. Добавить измельченный чеснок, лимонный сок, перемешать. Всыпать рубленую зелень петрушки, мелко нарезанный зеленый перец чили, соль, перемешать. Соус подать к рыбе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2826,'Филе нарезать крупными кусками, посыпать смесью разных молотых перцев, солью, оставить на полчаса для пропитывания. Разрезать помидоры черри на четыре части каждую, лук – полукольцами, сельдерей тонко нашинковать поперек. Отварить картофель в «мундире» до полуготовности. Остудить, очистить и нарезать круглыми ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2826,'Смешать картофель, размятый розмарин, соль, оливковое масло. Добавить помидоры, лук, сельдерей, овощи перемешать. Выложить смесь на противень, куски рыбы – сверху. Можно еще поперчить, посыпать специями для рыбных блюд. Печь в течение получаса при температуре 180 градусов. Лосось с картофелем и сельдереем в духовке готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4355,'Готовым тестом залить яблоки и отправить в духовку минут на 35-40. Очень ароматная и вкусная творожная шарлотка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2827,'Для основы перемешать вручную или в кухонном комбайне просеянную муку вместе с охлажденным и натертым маслом, сырыми яйцами, цедрой лимона. Скатать тесто в шар. Завернуть в пищевую пленку и поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2827,'Разогреть духовку до 190 градусов, в форму для выпечки положить тонко раскатанное тесто, сформовать бортики. Наколоть корж вилкой, закрыть бумагой и всыпать сухой горох, фасоль или рис. Печь 15 минут, крупу или бобовые вынуть, корж допечь еще в течение пяти минут, уменьшив температуру до 150 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2827,'Для приготовления начинки смешать яйца, сахарную пудру, сок и цедру лимонов, сгущенное молоко, сливки. Массу поцедить и вылить на основу для тарта. Печь 30 – 40 минут. При подаче французский лимонный тарт посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2828,'Для приготовления теста нужно взбить яйца с ванилином и сахарным песком, всыпать пшеничную муку, разрыхлитель. Массу взбить. Форму для выпечки смазать сливочным маслом или маргарином, вылить тесто. Печь на умеренном огне около часа при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2828,'Для приготовления крема взбить сахар с яйцом, добавить ванилин, молоко и просеянную муку. Перемешать, прогреть на тихом огне до загустения. Снять массу с огня, добавить мягкое сливочное масло и снова взбить. Крем охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2828,'Сварить глазурь: растопить нарезанное кусочкам сливочное масло, добавить какао-порошок, сахар, сметану, ванилин из пакетика. Смесь перемешать и варить до однородного состояния, не давая закипеть и постоянно помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2828,'Корж разрезать пополам по горизонтали, прослоить кремом. Полить выпечку шоколадной глазурью и поставить торт «Чародейка» в холод на несколько часов для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2829,'Полстакана перца-горошка взбить в блендере. Добавить соль и цедру нескольких лимонов. Массу взбить до однородности, консистенция должна быть максимально мелкой. Всыпать на противень и сушить несколько часов, можно оставить на ночь. Затем смесь взбить еще раз. Хранить в герметично закрывающемся контейнере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2830,'Смешать в равных количествах корни валерианы и шишки хмеля. Столовую ложку смеси залить кипятком, настоять в течение 20 минут и процедить. Пить по полстакана два раза в день или один стакан на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2831,'Смешать равные порции корня валерианы травы мяты перечной. Столовую ложку смеси залить кипящей водой, дать постоять в течение получаса и процедить. Пить чай по полстакана два раза в день. В смесь можно добавить анис или семена укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2832,'Три успокаивающих компонента: корни валерианы, травы пустырника и мелиссы, взять в равных пропорциях. Залить ложку смеси стаканом кипятка, настоять 20 минут, процедить. Пить по столовой ложке три раза в день до еды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2833,'Смешать шишки хмеля, траву пустырника. Залить смесь кипятком, дать постоять 10 минут, добавить зеленый чай, настоять еще пять минут и процедить. Добавить мед по вкусу, пить по полстакана три раза в день.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2834,'Залить смесь травы зверобоя, мелиссы и липы кипящей водой. Через 10 минут процедить, всыпать зеленый чай и настоять еще пять минут. Мёд – по вкусу. Пить по полстакана несколько раз в день.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2835,'Аккуратно удалить ножки. Обмакнуть шляпки в подсоленную воду, ножки мелко порубить. Обжарить на сковороде с растительным маслом кубики ветчины и нарезанные грибы, красный лук, в течение пяти минут. Добавить сладкий болгарский перец, жарить еще две минуты. Добавить паприку, базилик, майоран, молотый черный перец и другие специи, залить сливками или сметаной, потушить 3 – 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2835,'Полученной начинкой нафаршировать шляпки, низ смазать маслом и выложить на лист бумаги для выпечки. Сверху налить немного сливок столовой ложкой, печь в течение 10 минут при температуре 180 градусов. Почти готовую закуску вынуть, посыпать тертым сыром «Пармезан» или «Российский» и поставить обратно в духовку еще на 10 – 15 минут. Жульен, запеченный в шляпках шампиньонов готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2836,'Сливочное масло охладить, натереть на терке. Смешать с просеянной мукой, перетереть в крошку. Сделать углубление, добавить яйцо, растительное масло, воду и соль по вкусу. Замесить тесто, можно добавить еще немного муки. Накрыть массу миской, оставить на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5814,'Смешать молотый цикорий и молотый кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2836,'Приготовить начинку: удалить из яблок сердцевину с семечками, нарезать крупными кусками. Сбрызнуть лимонным соком, чтобы мякоть не почернела. Промыть изюм без косточек, добавить к яблокам вместе с корицей и молотой цедрой лимона. Перемешать, добавить панировочные сухари.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2836,'Раскатать готовое тесто на присыпанной мукой поверхности, накрыть влажной тканью и дать постоять еще 15 минут. Растянуть лепешку от центра к краям, тесто должно быть тонким, полупрозрачным. Смазать поверхность растопленным маслом и выложить яблочную начинку. Свернуть в рулет. Переложить будущую выпечку на выстланный пергаментом противень, шов должен оказаться внизу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2836,'Печь рулет в течение 30 – 40 минут при температуре 180 – 200 градусов. Если штрудель будет слишком подрумяниваться – накрыть его листом пищевой фольги. При подаче домашний яблочный штрудель с изюмом и корицей густо посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2837,'Смешать творог с растительным маслом с помощью миксера. Добавить сырое яйцо, сахарный песок, всыпать предварительно просеянную муку вместе с разрыхлителем. Замесить тесто.  Форму для выпечки среднего размера смазать маслом. Раскатать и выложить тесто для коржа, сформовать высокие бортики. Поставить заготовку в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2837,'Для начинки отделить белки от желтков, взбить и тоже поставить в холод. Вымыть лимон, натереть чайную ложку цедры и выжать столовую ложку сока. Взбить мягкое, комнатной температуры, сливочное масло, сахарный песок, желтки. Добавить творог, сметану, разрыхлитель, сок и цедру лимона, массу перемешать. Очистить мандарины, удалить пленки. Половину мякоти добавить в начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2837,'Осторожно, порциями, вмешать взбитые, охлажденные белки. Снова все перемешать. Выложить творожную массу в форму с тестом, сверху – оставшиеся мандариновые дольки, немного углубить, вдавить их в массу руками. Печь в течение часа при температуре 180 градусов. Если пирог начинает подгорать – накрыть его фольгой. Остудить, подать творожный пирог «Ноктюрн» с мандаринами на стол теплым или холодным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2838,'Смешать сметану с сырым яйцом, посолить по вкусу, всыпать специи, зеленый рубленый укроп. Смесью смазать лаваш. Сверху – тертая ветчина, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2838,'Разрезать лепешку на кусочки произвольной формы, переложить на противень без масла и подсушить чипсы из лаваша в духовке в течение 7 – 10 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2839,'Для теста: взбить яйца с сахарным песком и мукой. Нагреть и смазать маслом противень, выложить тесто ложкой, размазать до диаметра в 10 см. Выпечь в разогретой духовке, лепешку вынуть и в горячем виде скрутить в трубочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2839,'Для крема: смешать вареную сгущенку, мягкое сливочное масло, измельченные орехи, например, обжаренный арахис. Начинить хрустящие трубочки ореховым кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2840,'Подсушить в духовке фундук в течение 8 – 10 минут. Орехи отшелушить с помощью полотенца или руками. Мелко нарубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2840,'Шоколадные вафли наломать в среднюю крошку. Смешать с орехами и добавить шоколадный крем «Нутелла». Из массы слепить шарики из одной чайной ложки шоколадной массы. Если она жидковата, то можно ее немного подморозить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2840,'Готовые конфеты поставить в холод на 45 минут. Растопить на водяной бане шоколад. Немного остудить и опустить каждый шарик в шоколадную массу. Остудить и подать Конфеты «Ferrero Rocher» к кофе в бумажных формочках.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2841,'Взбить сырые яйца, влить молоко, соль и перец – по вкусу. Продолжая взбивать, добавить просеянную муку и пищевую соду. Должно получиться жидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2841,'Порезать кубиками ветчину и паприку. Измельчить чеснок, порубить зелень, натереть сыр. Все ингредиенты перемешать с тестом, выложить в форму, печь в течение получаса или чуть больше при температуре 200 градусов. Быстрый пирог с болгарским перцем и ветчиной готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2842,'Отварить и очистить клубни картофеля и яйца. Первый ингредиент нарезать кубиками, яйца разделить на белки и желтки, то и другое мелко порубить или просто размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2842,'Нашинковать белокочанную капусту, посолить и помять руками. Обжарить грецкие орехи, постоянно помешивая, они должны приобрести светло-золотистый цвет, мелко порубить. Натереть сырую морковь на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2842,'Салат собрать послойно: на дно блюда выложить картофель, посолить, смазать майонезом. Второй слой – морковь, соль, майонез, затем размятый желток и майонез, отжатая капуста, майонез. Верх посыпать белками и орехами. Дать овощному салату «Кремлевский» постоять два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2843,'В теплом молоке развести дрожжи, сахарный песок, соль и взбитое яйцо. Всыпать муку небольшими порциями, затем – размягченное сливочное масло. Замесить тесто, накрыть тканью и дать постоять в течение полутора часов. Масса должна увеличиться в два раза. Для приготовления начинки перемешать масло с сахаром, выложить на пищевую пленку, сделать «колбаску» и заморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2843,'Противень застелить бумагой для выпекания, выложить двадцать булочек-шариков, накрыть их полотенцем и оставить в тепле на полчаса. В каждой булочке сделать углубление, положить по кусочку сладкой масляной «колбаски», можно добавить по курагу и изюм. Смазать булочки «Масляные глазки» яйцом с сахаром. Печь при температуре 10 – 15 минут при температуре 230 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2844,'Приготовить тесто: смешать муку со сметаной и растопленным сливочным маслом или маргарином. Добавить погашенную уксусом соду или разрыхлитель. Массу замесить и убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2844,'Для крема смешать сметану, яйцо, сахарный песок и немного муки. Смесь взбить миксером или венчиком, вручную. Очистить яблоки от кожуры и очень тонко нарезать. Можно натереть плоды на терке для чипсов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2844,'В форму для выпечки средней величины выложить тесто, сформовать бортики. Выложить яблочную начинку, залить кремом. Печь в течение часа при температуре 180 градусов. Цветаевский яблочный пирог поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2845,'Смешать сметану или простоквашу с мягким сливочным маслом или маргарином. Добавить просеянную муку, соду на кончике ножа. Массу смешать и порубить ножом до однородности. Готовое тесто убрать в морозильник на 1– 1,5 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2845,'Раскатать тесто, вырезать язычки овальной формы. Посыпать сахаром, можно с добавлением ванилина или корицы. Противень смочить холодной водой, выложить слоеные язычки, печь при температуре 180 градусов до образования золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2846,'Отварить круглый рис в подсоленной воде. Остудить и полить свежим лимонным соком. Измельчить грецкие орехи. Крабовое мясо или крабовые палочки нарезать на кусочки. Нарезать кубиками вареные яйца. Добавить консервированную кукурузу без жидкости, майонез, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2846,'Взять коврик для приготовления суши или обычную пищевую фольгу. Покрыть поверхность пищевой пленкой, выложить рис тонким слоем. Затем – крабовый салат. Свернуть рулетом и посыпать орехами. Крабовый салат-рулет с грецкими орехами готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2847,'Смешать дрожжи, соль, сахарный песок, растительное масло, всыпать муку. Замесить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2847,'Смазать противень растительным маслом, выложить тонко раскатанную лепешку. Можно использовать любую начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2848,'Растопить сливочное масло. Добавить сырые куриные яйца, кефир или простоквашу, сахар, соду, погашенную уксусом. Всыпать манную крупу и просеянную пшеничную муку. Вымесить, тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2848,'Печь в форме, в духовке, на среднем огне. Горячий манник залить молоком, понадобится два стакана. Дать впитаться жидкости, остудить и подать. Манник «Мокрый» с молоком готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2849,'Грудки посолить и поперчить по вкусу. Добавить мед, сушеный базилик, кориандр. Оставить для маринования на 20 минут. Сделать на шкурке надрезы, обжарить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2849,'Переложить мясо в форму, печь при температуре 200 градусов в течение 20 минут. Можно накрыть сверху пищевой фольгой, чтобы блюдо не пересушилось и не подгорело.  Перед подачей кожицу снять, утиные грудки нарезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2850,'Влить в кастрюлю воду, посолить, положить сливочное масло и довести смесь до кипения. Всыпать просеянную пшеничную муку, перемешать до однородного состояния на огне в течение двух-трех минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2850,'Тесто немного остудить, ввести сырые яйца по одному. Смазать противень растопленным сливочным маслом, отсадить тесто для эклеров через кондитерский мешок или просто выложить его столовой ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5814,'Подогреть молоко и 4 кружки для кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2850,'Печь в течение получаса при температуре 180 градусов. Пирожные должны подняться, в них образуются пустоты. Сделать надрезы, положить начинку: вареное сгущенное молоко, его можно смешать с мягким сливочным маслом. Другой вариант: взбитые сливки с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'С куриной грудки снять мясо и нарезать небольшими кусочками, немного отбить через пищевую пленку. Можно воспользоваться тыльной стороной ножа. Посолить, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'Натереть сыр, тонко нарезать бекон. Ветчину нарезать полосками средней ширины. Взбить яйца с солью. Емкость для запекания выстелить пищевой фольгой. Выложить на неё слой бекона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'Обвалять в муке куски курицы, затем обмакнуть в яйцо, запанировать в тертом, «Российском», сыре. Выложить мясо тонким слоем на середину бекона, затем слой ветчины, продолжать чередовать мясные продукты, верхний слой должен быть куриным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'Полить блюдо сметаной и посыпать молотой паприкой. Завернуть свободными концами бекона, накрыть пищевой фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'Печь слойку в духовом шкафу в течение часа при температуре 180 градусов. В конце обработки фольгу снять и допечь еще в течение нескольких минут, чтобы получилась румяная корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2851,'Блюдо охладить, поставить на ночь под пресс в 1,5 – 2 кг в холодильник. При подаче фольгу снять, мясной рулет в копченом беконе нарезать на порции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2852,'Смешать оливковое масло, сахарный песок, соевый соус, молотый черный перец, соль и воду. Из куриных ножек удалить косточку. Кожу оставить и распластать мясо, как отбивную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2852,'Обмакнуть ее в масляную смесь, обжарить куриные ножки по-китайски на сковороде с двух сторон, до образования румяной корочки. Потушить под крышкой в течение 15 минут на слабом огне, во время обработки два раза перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2853,'Шампиньоны вымыть, нарезать крупными ломтиками и обжарить. Нарезать кубиками  репчатый лук, натереть морковь, то и другое обжарить на масле. Нарезать соломкой маринованные огурцы, жидкость отцедить. Отварить и очистить яйца, консервированную сардину размять вилкой, косточки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2853,'На блюдо выложить грибы, смазать майонезом. Затем слой тертых яиц, часть оставить для украшения. Снова майонез, огурцы, сардины, жареный лук с морковью, жир отцедить.  Нарисовать сеточку из майонеза, посыпать оставшимися тертыми яйцами, снова смазать майонезом и посыпать салат с шампиньонами и сардинами тертым сыром Эмменталь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2854,'Удалить из яблок сердцевину, очистить от кожицы. Натереть плоды на крупной терке, добавить свежий сок от половины лимона, сахарный песок и ванилин из пакетика. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2854,'Лист армянского лаваша разрезать на восемь кусочков прямоугольной формы. В середину каждого положить приготовленную яблочную начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2854,'Завернуть, придать пирожкам форму конвертов. Жарить яблочные пирожки из лаваша на сковороде, на растительном масле, швом вниз, по две-три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2855,'Обжарить на сковороде хлеб для сэндвичей, без масла. Нарезать зеленый лук, перемешать с размятым сыром Филадельфия, добавить соль и перец, сок лимона. Полученную заправку намазать на хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2855,'Положить по ломтику слабосоленой семги и твердого сыра. Сделать еще один такой бутерброд и сложить их друг на друга, начинкой внутрь. Прогреть сэндвич с семгой и сыром в течение двух минут на сковороде или на гриле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2856,'Куриную или индюшачью печень отварить в подсоленной воде, всыпать специи. Остудить и натереть субпродукт на крупной терке. Отварить куриные яйца. Шампиньоны тонко нарезать, обжарить на растительном масле. Нарезать репчатый лук кубиками, морковь натереть. Сначала обжарить лук, затем добавить морковь, довести овощи до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2856,'Выложить на блюдо слой печени, смешанной с майонезом. Второй слой – овощная обжарка, жир от которой нужно слить или выложить массу на несколько минут на бумажное полотенце, чтобы он впитался. Третий слой – грибы, смешанные с майонезом. Четвертый – тертый плавленый сыр с майонезом. Сверху – тертые яйца, полить майонезом в виде «сеточки» или концентрических кругов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2899,'Для приготовления начинки предлагается два варианта: шпинат с сыром моцарелла и жареные в сметане лисички с этим же сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2856,'Тонко нарезать маринованный огурец и украсить кружочками бока салата. Дать слоеному салату с куриной печенью и шампиньонами постоять два-три часа и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2857,'Растереть мягкое сливочное масло с половиной нормы муки. Влить молоко, сметану с пищевой содой, перемешать массу руками. Всыпать оставшуюся муку. Замесить тесто, оно должно быть мягким, поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2857,'Порезать кубиками репчатый лук, обжарить до золотистого цвета. Нарезать кубиками отварную куриную грудку, помидор, сладкий болгарский перец. Все ингредиенты перемешать, добавить зеленый горошек. Соль и перец молотый – по вкусу. С помощью вилки взбить яйца, сметану, муку. Массу посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2857,'Форму для выпечки среднего размера смазать маслом, выложить тесто руками, сформировать бортики. Сверху – начинка, залить её яичной смесью. Печь заливной пирог с куриной грудкой в течение 50 минут при температуре 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2858,'Мягкое сливочное масло взбить с сахарным песком, масса должна увеличиться в объеме. Добавить сырые яйца, ванильный сахар. Понемногу всыпать просеянную муку вместе с разрыхлителем и солью. Замесить однородное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2858,'Противень смазать маслом и застелить пергаментом. Выложить приготовленное тесто. Сверху – ягоды вишни, если плоды крупные – разрезать их пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2858,'Печь в течение 40 – 45 минут при температуре 180 градусов. Готовность блюда проверить спичкой или зубочисткой. Охладить в форме, а затем – на решетке. При подаче вишневый пирог нарезать на квадратики и посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2859,'Приготовить маринад: смешать мед, оливковое масло, черный молотый перец, соль, сок лимона, цедру с двух лимонов. Куриное филе выложить в форму для запекания, сверху вылить смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2859,'Печь куриные грудки в лимонно-медовом соусе в течение 30 – 35 минут при температуре 180 градусов. Филе должно стать золотисто-коричневым, соус полностью выпариться. Вынуть мясо из духовки, остудить, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2860,'Перемешать просеянную пшеничную муку с разрыхлителем, добавить молотую корицу, мускатный орех, тертый имбирь. Отдельно взбить мягкое сливочное масло с сахаром до образования пышной массы. Вбить яйца по одному.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2860,'Всыпать половину полученной сухой смеси, взбить, влить пахту, снова взбить. Добавить оставшуюся муку со специями, нарезанный кусочками ананас, тертую морковь, рубленые фисташки и кокосовую стружку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2860,'Готовое тесто разделить на три части и выпечь три коржа в трех смазанных и присыпанных мукой формах, в течение получаса, при температуре 175 градусов. Готовность выпечки проверить спичкой или зубочисткой, она должна остаться сухой. Остудить, можно поставить коржи на ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2860,'Для крема взбить мягкий сливочный сыр с маслом до однородного состояния. Добавить сахар, корицу, ванилин из пакетика, кленовый сироп. Массу снова взбить. Промазать кремом коржи, смазать верх и бока. Украсить ананасово-морковный торт молотыми и целыми фисташками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2861,'Смешать готовый мясной фарш, отваренный до полуготовности рис, обжарку из рубленого репчатого лука и тертой моркови. Мелко порубить чеснок. Белокочанную капусту также порубить и ошпарить. Все ингредиенты смешать, добавить сырое яйцо, специи, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2861,'Для приготовления соуса смешать томат-пасту, сметану, разбавить смесь водой, посолить, поперчить по вкусу. Сформовать из массы котлеты, обвалять в муке. Выложить на смазанный противень. Полить поученным томатно-сметанным соусом, печь ленивые голубцы из мясного фарша при температуре 170 градусов в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2862,'Для приготовления теста растопить сливочное масло, добавить соль, влить кефир. Отдельно взбить сырые яйца, добавить в смесь, всыпать просеянную муку вместе с разрыхлителем. Перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2862,'Для начинки обжарить на растительном масле любые рубленые грибы с репчатым луком, соль и перец – по вкусу. Смазать форму для выпечки, вылить большую часть теста, затем выложить начинку и залить оставшейся смесью. Печь в течение 35 минут при температуре 200 градусов. Остудить пирог на кефире с жареными грибами под полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'С помощью миксера взбить сливки с ванилином.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2863,'Смешать соевый соус, перец молотый, рубленый чеснок. В полученный маринад положить куриную грудку. Затем мясо немного обжарить. Приготовить блинчики из яиц и молока, обжаривать с двух сторон. Готовые смазать смесью сметаны с рубленым или давленым чесноком и нарезать лапшой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2863,'Отварить картофель до готовности, нарезать кубиками. Слить жидкость из банки с консервированной кукурузой, нарезать наискосок зеленый лук. Все ингредиенты перемешать, заправить майонезом. Выложить Салат «Праздничный» на листья зеленого салата, украсить зернами граната.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2864,'В посуду всыпать сухие дрожжи, влить холодное молоко и горячую воду. Смесь перемешать, посолить, влить растительное масло. Постепенно всыпать просеянную муку, замесить тесто. Поставить в теплое место на 1 – 1,5 часа, накрыв тканью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2864,'Поднявшееся тесто разделить на двенадцать частей, сформовать булочки любой формы, например, раскатать в небольшие «колбаски» и завернуть их «узелком». Вскипятить три литра воды, всыпать пищевую соду. В эту пенящуюся жидкость опустить каждую булочку на пять секунд с помощью шумовки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2864,'Выложить на противень, выстеленный промасленным пергаментом. Посыпать кунжутными семечками, маком, морской солью. Печь немецкие сдобные булочки с секретом в духовке в течение 20 минут при температуре 180 градусов, до образования золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2865,'Смешать кефир, растворимый кофе, сырые яйца, сахарный песок. Массу взбить. Добавить мягкое сливочное масло, стакан муки, разрыхлитель или соду, гашенную уксусом или лимонным соком. Массу перемешать и выпечь до готовности. Приготовить крем из сахара, сметаны и растворимого кофе, полить быстрый кофейный пирог сверху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2866,'Свиную шейку нарезать на порционные куски. Посолить по вкусу, посыпать любой приправой для мяса, выложить на противень, смазанный растительным маслом. Отдельно отварить клубни картофеля в «мундире», остудить, очистить и натереть. Картофельную массу выложить на свинину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2866,'Порезать небольшими кусочками консервированные ананасы и твердый сыр. Все ингредиенты перемешать, залить майонезом. Выложить смесь на картофель. Печь свинину «Ананасовое налаждение» в течение 50 минут при 200 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2867,'Смешать творог с сырым яйцом, щепоткой соли, сахарным песком и небольшим количеством муки. Скатать шарики мокрыми руками. Обвалять в муке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2867,'Жарить идеальные сырники на раскаленной сковороде на среднем огне, с двух сторон, до золотистого цвета. Прогреть несколько минут под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2868,'Форель или семгу нарезать на порции, выложить на смазанный противень, посолить, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2868,'Обжарить рубленый репчатый лук до золотистого цвета, добавить сметану, тертый сыр смешать с майонезом. Обе смеси выложить на рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2868,'Печь филе форели под майонезом при 230 – 250 градусах в течение 15 – 20 минут, сыр должен запечься до коричневатой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2869,'Для приготовления маринада смешать растительное масло, молотую паприку, соль, перец. Полученной массой обмазать куриные окорочка, разрезанные пополам, накрыть крышкой и оставить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2869,'Мелко нарезать репчатый лук и красный острый перец, порубить чеснок. Обжарить ножки со всех сторон на масле, до образования золотистой корочки, вынуть. В той же сковороде обжарить лук и чеснок, добавить сладкий перец и жарить все вместе еще три минуты.  Добавить рис, подержать на среднем огне пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2869,'В сотейник вылить размятые томаты в собственном соку, подлить стакан воды, выложить рис, обжарку, курицу, посолить по вкусу. Довести блюдо до кипения, накрыть крышкой, уменьшить огонь, тушить курицу с рисом и сладким перцем до готовности в течение получаса. В процессе приготовления можно долить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2870,'Отварить длиннозерный рис до готовности, воду подсолить. Отварить и очистить яйца, натереть морковь, обжарить на растительном масле. Отдельно смешать сметану, растительное масло и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2870,'Выложить салат слоями: порванные руками листья зеленого салата, рис, сметанный соус, размятая консервированная горбуша, соус. Следующий слой – рубленый лук, соус, обжаренная морковь, соус, мелко порезанный огурец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Просеять какао-порошок и пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2870,'Салат «Ромашковое поле» полить остатками сметаны, украсить ромашками: лепестки из яичных белков, серединки – из тертого желтка, лепестки – зелень петрушки и укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2871,'Очистить и измельчить репчатый лук. В сотейнике нагреть растительное масло, обжарить на нем лук в течение пяти минут. Снять с огня. Порубить зелень петрушки. Готовый куриный фарш смешать с мягким сливочным сыром, петрушкой, яйцом, соль – по вкусу. Добавить обжаренный лук, перемешать. Накрыть, поставить в холод на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2871,'Для соуса обжарить в сотейнике просеянную муку до золотистого цвета. Добавить сливочное масло, прогреть в течение минуты, помешивать. Снять с огня, влить сливки, продолжать мешать. Снова поставить на огонь, прогревать и растирать массу до растворения комочков. Добавить рубленую зелень петрушки, накрыть и оставить в тепле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2871,'Из готового фарша слепить небольшие шарики, обвалять в муке. Обжарить порциями в масле до золотистой корочки. Залить фрикадельки из куриного фарша с сыром сливочным соусом, прогреть и подать в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2872,'Вскипятить молоко, затем остудить. Ввести три сырых желтка, сахарный песок и ванилин из пакетика, перемешать. Массу поставить на водяную баню, варить, помешивая, до загустения. Отдельно взбить сливки, смешать с молочно-сахарной смесью. Поставить на час в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2872,'Через час массу перемешать при помощи миксера на невысокой скорости. Снова поставить в морозильную камеру. Через час процедуру повторить. Нежный домашний пломбир готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2873,'Смешать в равных количествах овсяные хлопья «Геркулес», чернослив и натертую сырую свеклу. Массу перемешать, залить кипятком, варить в течение 15 минут на тихом огне. Отвар процедить и выпить за два часа до сна, а гущу можно съесть утром вместо завтрака.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2874,'Порубить репчатый красный лук, морковь и стебель сельдерея, кусочки должны быть среднего размера. Нарезать кубиками картофель и кабачки цуккини. От консервированной фасоли отцедить жидкость, промыть, обсушить. Стручковую фасоль порезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2874,'На среднем огне, в кастрюле, разогреть немного оливкового масла. Обжарить лук, морковь и сельдерей с добавлением свежего или сушеного розмарина, острого перца, массу посолить и поперчить. Прогревать, помешивая, до образования золотистого цвета, в течение 5 – 8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2874,'В обжарку добавить размятые консервированные томаты в собственном соку. Прогревать минуту, немного уварить жидкость. Всыпать картофель и цуккини, фасоль, влить воду, куриный или овощной бульон. Суп довести до кипения. Добавить стручковую фасоль, варить до мягкости всех овощей. За 10 минут до готовности добавить сухую короткую пасту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2874,'Огонь выключить, добавить в блюдо тертый чеснок, нарезанный базилик, можно еще подсолить. Перемешать, дать постоять несколько минут под крышкой. Подать итальянский суп «Минестроне», посыпав тертым сыром Пармезан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2875,'Взбить мягкое сливочное масло с сахаром. Добавить ванилин и сырые яйца, хорошо перемешать. Всыпать просеянную вместе с разрыхлителем муку, замесить тесто. Добавить рубленые грецкие орехи и промытый изюм. Смочить руки водой, сформовать два батона шириной 8 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2875,'Выпечь батончики на смазанном противне в течение 25 минут при температуре 180 градусов. Вынуть, остудить, нарезать по диагонали ломтиками средней толщины. Выложить бискотти с грецкими орехами и изюмом на противень и печь еще 10 минут, через пять минут – перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2876,'Нагреть сковороду большого размера. Обжарить на растительном масле мелко рубленный репчатый лук, красный болгарский перец, нарезанный кусочками цуккини. Посолить, тушить в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2876,'Добавить в обжарку томатное пюре, свежий тимьян, лавровый лист. Огонь убавить, тушить под крышкой еще 10 – 20 минут до мягкости овощей. Соль, перец – по вкусу, в конце тушения добавить рубленую зелень базилика, орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2876,'Филе лосося вымыть и обсушить. Противень застелить фольгой, выложить рыбу, посыпать перцем, посолить. Печь в течение 10 минут при температуре 200 градусов. Вынуть из духовки на пять минут, сбрызнуть соком лимона и оливковым маслом. Подать лосось с овощами «Рататуй».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Мелко нарезать лук. Пожарить до прозрачности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2877,'Приготовить светлое тесто. Для этого смешать сырые яйца, тертую цедру лимона и его сок, соль – по вкусу. Массу взбить, всыпать в нее просеянную смесь пшеничной муки, крахмала, разрыхлителя. Замесить тесто, выложить в смазанную маслом форму для выпечки среднего размера. Печь при температуре 180 градусов в течение 20 – 25 минут. Корж остудить, разрезать пополам по горизонтали острым ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2877,'Для приготовления темного теста смешать яйца, сахарный песок и соль, взбить. Всыпать смесь муки с крахмалом, какао-порошком и разрыхлителем. Перемешать, выложить тесто в смазанную форму, печь столько же времени, как и светлый корж. Разрезать пополам. Для начинки вскипятить молоко с сахарным песком, добавить порошок с ванилином для приготовления пудинга и остудить. Вмешать мягкое сливочное масло и кофе Эспрессо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2877,'Для пропитки смешать сахар, воду, две чашки кофе «Эспрессо». Смесь вскипятить, остудить, полить темный корж. На него выложить четверть приготовленного крема, выдавить кольцом малиновое варенье с помощью кулинарного шприца. Ту же процедуру проделать с еще одним темным и одним светлым коржом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2877,'Собрать торт, сверху – светлый корж, политый пропиткой. Торт обмазать остатками крема. Для безе взбить сырые белки с солью в крепкую пену, ввести сахар, какао-порошок. Массу выложить на противень, застеленный бумагой для выпекания, в виде полосок. Печь при температуре 80 градусов в течение часа. Украсить полосками готовый торт сверху и с боков. Кофейный торт «Мокко-крем» с безе готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2878,'Вскипятить молоко в небольшой кастрюле, удалить пенку. Остудить. Отдельно взбить желтки с сахарным песком. Влить остывшее молоко, прогревать смесь на тихом огне, помешивая деревянной ложкой. Масса должна загустеть, увариться. Крем остудить, можно его поставить в миску с холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2878,'Взбить сливки, добавить в крем, перемешать. Выложить массу в небольшой контейнер, поставить в морозильную камеру на три часа. Мороженое достать, переложить в посуду, быстро взбить с помощью миксера или вилки. Массу снова переложить в контейнер, заморозить, через три часа операцию повторить. В общей сложности натуральное ванильное мороженое готовится девять часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2879,'Накануне приготовления блюда нужно смешать зиру, кардамон, молотый кориандр и красный перец, черный перец, сок лайма, давленый чеснок. Смесь поместить в пластиковый пакет вместе с куриным филе. Оставить на ночь в холодильнике для маринования.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2879,'Растопить в сковороде большого размера сливочное масло. Спассеровать рубленый репчатый лук до прозрачного состояния. Добавить куриное мясо, жарить по пять минут с каждой стороны. Подлить томатную пасту с нарезанными свежими помидорами, тушить под крышкой в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2879,'При готовности курицы подлить сливки и посыпать блюдо мелко нарубленной петрушкой. Перемешать. Отварить в воде рис вместе с куркумой и порошком из чеснока. Выложить готовый рис на тарелки, сверху – курица в соусе. Рис басмати со сливочной курицей по-индийски готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2880,'Шампиньоны вымыть, нарезать. Репчатый лук очистить, мелко порубить. То и другое обжарить на растительном масле. Массу выложить на блюдо, соль – по вкусу, смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2880,'Отварить яйца, очистить, измельчить, высыпать на грибы, смазать майонезом. Отварить куриное филе, нарезать, выложить третьим слоем, смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2880,'Четвертый слой – морковь по-корейски, смазать майонезом, посыпать тертым твердым сыром. Салат с куриным филе, грибами и морковью по-корейски готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2881,'Свиную вырезку, куриное филе и сало нарезать мелкими кубиками. Отдельно взбить яйца, посолить, поперчить по вкусу, добавить измельченный чеснок, специи и пряности. В смесь ввести картофельный крахмал, добавляя его понемногу, порциями. Смешать с мясом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2881,'Готовый фарш выложить с помощью столовой ложки на пищевую фольгу в виде колбаски. Завернуть, как конфету, чтобы не вытек сок. Переложить колбасу на противень, печь при температуре 180 – 200 градусов в течение часа. При подаче фольгу снять, нарезать натуральную домашнюю колбасу на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2882,'Нарезать мясо кубиками, морковь – длинной соломкой. Помидоры ошпарить и снять кожицу, нарезать кубиками, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2882,'Обжарить свинину в казане или глубокой сковороде с толстым дном, огонь должен быть сильным. Отдельно обжарить лук до золотистого цвета, переложить к мясу, затем обжарить морковь, поступить так же. Прогреть помидоры и тоже добавить в общую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2882,'Залить блюдо кипятком, он должен покрыть массу на два пальца, накрыть крышкой, быстро довести до кипения, затем огонь убавить. Варить полтора часа, мешать не нужно. Зирвак посолить, поперчить, варить еще час-полтора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2882,'Рис промыть, всыпать в мясо, разровнять и долить воду. Поставить на сильный огонь, варить 10 минут без крышки. В середину положить целую головку чеснока, посыпать специями, тушить под крышкой в течение 15 минут при небольшой температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2882,'Плов перемешать, огонь выключить. Дать домашнему плову со свининой настояться в течение часа и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2883,'Грибы быстро отварить, в течение двух-трех минут. Отцедить, немного охладить. Добавить рубленый чеснок, соль, уксус, сахарный песок, лавровый лист, перец-горошек. Влить холодную кипяченую воду, чтобы грибы были покрыты. Массу перемешать, поставить в холодильник на сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2884,'Репчатый лук очистить и нарезать мелкими кубиками. Затем обжарить на сливочном масле до золотистого цвета. Филе курицы нарезать тонкой соломкой, выложить к луку и обжарить все вместе две минуты. Соль, перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2884,'Посыпать массу небольшим количеством муки и перемешать. Добавить сметану и нарезанный кусочками плавленый сыр. Тушить куриное филе «Неженка» в сметанно-сырном соусе несколько минут, на тихом огне, дать немного покипеть. Если соус густоват – подлить немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2885,'Приготовить негустой фарш из пропущенной через мясорубку индейки, манной крупы, сметаны, сырого яйца. Добавить готовую горчицу, сахарный песок, соль, специи – по вкусу. Мелко порубить зелень петрушки, укропа, добавить в массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2885,'Разогреть сковороду с растительным маслом, выложить массу столовой ложкой, жарить котлеты по две-три минуты с каждой стороны. Затем подлить немного воды, закрыть крышкой и тушить котлеты из фарша индейки еще по пять минут с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2886,'Кефир перемешать с содой, дать постоять 10 минут, посолить, всыпать сахар и муку порциями. Замесить тесто, оно должно быть мягким по консистенции, дать ему полежать в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2886,'Для приготовления начинки нарезать лук, помять его руками, чтобы дал сок, всыпать сваренные вкрутую и накрошенные яйца, соль и молотый перец – по вкусу. Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2886,'Тесто разрезать на восемь частей, выложить начинку, сформовать круглые пирожки и приплюснуть. Жарить мягкие пирожки на кефире с луком и яйцом под крышкой на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2887,'Нарезать репчатый лук полукольцами, шампиньоны – ломтиками средней толщины, филе курицы – кубиками.  Лук обжарить на растительном масле, добавит грибы, и жарить все вместе в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2887,'Добавить мясо, посолить, поперчить по вкусу и тушить куриное филе с шампиньонами под крышкой в течение 20–25 минут. Посыпать рубленой зеленью укропа, петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2888,'Утку обработать, удалить пеньки от перьев. При необходимости можно опалить и промыть водой. Тушку хорошо натереть солью, молотым перцем и мускатным орехом снаружи и изнутри. Кислые яблоки очистить, удалить семенные камеры, нарезать дольками, присыпать сахарным песком. Нафаршировать ими утку, отверстие зашить или заколоть зубочистками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2888,'Уложить в жаровню, добавить топленое масло, тушить при температуре 270 градусов до золотистой корочки. Температуру снизить до 170 градусов, поливать периодически выделяющимся соком. Жарить еще около часа. Утку вынуть, нитки удалить. Яблоки выложить вокруг утки на большом блюде. Украсить праздничную утку с яблоками зеленью, подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2889,'Взбить яйца с сахаром в пену до увеличения объема в несколько раз. Всыпать ванилин из пакетика, просеянную пшеничную муку, размешать ложкой, осторожно, движениями снизу вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2889,'Противень выстелить пергаментом, вылить тесто, печь в предварительно разогретой духовке в течение 20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Подавать суп «Гамбо» с креветками, крабовым мясом и беконом в глубоких тарелках',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2889,'Готовый корж вынуть, намазать в горячем виде сгущенным молоком, осторожно, чтобы не поломать, свернуть в рулет. Простой рулет со сгущенкой к чаю готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2890,'В небольшом количестве растительного масла пожарить фарш со специями, лишняя жидкость должна выпариться. Посыпать тертым твердым сыром. Мелко нарезать картошку и обжарить во фритюре, соленые огурцы нарезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2890,'Раскатать тесто, как на пельмени. Положить в разъемную форму с бортиками, выложить мясную начинку, затем порванный сыр для сэндвичей. Следующий слой – обжаренный картофель и соленые или маринованные огурцы, майонез. Массу посыпать сыром моцарелла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2890,'Пирог накрыть фольгой, поставить в разогретую духовку, печь при температуре 180 градусов в течение 15 – 20 минут. Фольгу открыть, уменьшить температуру выпечки до 140 градусов и допечь в течение 15 минут. Сыр должен приобрести золотистый оттенок. Слоеный пирог с мясным фаршем и картофелем готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2891,'Довести до кипения литр воды с имбирем и сахаром. Сироп помешивать, сахар должен полностью раствориться. Снять с огня.  Всыпать сухой чай каркаде, подержать под крышкой в течение 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2891,'Процедить, охладить, влить лимонный сок. Насыпать в стаканы колотый лед, влить красный чай с имбирем, украсить дольками лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2892,'Для приготовления маринада смешать мед, оливковое масло, лимонный сок и тертую цедру лимона, раздавленный чеснок, соль, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2892,'Стейки положить в смесь со специями, поставить в холодильник на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2892,'Обжарить стейки на гриле в течение 15 минут с двух сторон. Подать с овощным салатом или любым другим гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2893,'Говяжьи стейки обжарить на разогретом растительном масле с двух сторон по 3–4 минуты. Должна образоваться румяная корочка. Соль и молотый перец – по вкусу. Довести до готовности в горячей духовке в течение 10–12 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2893,'В сковороде, где жарилось мясо, обжарить нарезанный репчатый лук, влить белое вино. Жидкость выпарить. Влить сливки и всыпать горчицу зернами. Полученный соус довести до кипения, посолить и поперчить. Подать к говяжьим стейкам горчичный соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2894,'Нагреть молоко на тихом огне, в кастрюле. Всыпать какао-порошок, перемешать, прогреть почти до кипения. Разлить в кружки. Сверху положить по ложке взбитых сливок, посыпать какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2895,'Потушить на растительном масле нашинкованный лук в течение пяти минут. Обжарку охладить. Довести до кипения подсоленную воду. Острым ножом вырезать кочерыжку, вилок положить в кипяток. Отделившиеся, после прогревания, листья, вынуть с помощью щипцов или шумовки, обсушить бумажным полотенцем. Толстую часть листьев можно срезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2895,'Для начинки смешать говяжий фарш, охлажденный лук, вареный белый или коричневый рис, изюм, соль.  Выложить начинку на полуотваренные капустные листья, завернуть голубцы конвертом. Выложить в смазанную форму для выпечки или кастрюлю.  Для соуса смешать кетчуп, говяжий бульон и паприку. Смесью залить голубцы с мясной начинкой, накрыть блюдо фольгой, печь в духовке в течение часа. Подать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2896,'Замесить тесто из творога, манной крупы и сахарного песка. Сформировать лепешку из теста, положить вареную сгущенку, закрыть второй лепешкой. Слоеный сырник обвалять в муке, жарить на сковороде до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2897,'Отварить вкрутую куриные яйца, остудить, очистить, натереть на крупной терке. Отварить куриное филе в подсоленной воде, остудить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2897,'Смешать с готовой морковью по-корейски. Натереть твердый сыр, добавить в салат. Залить майонезом и перемешать, соль – по вкусу. Салат «Bonito» с куриным филе готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2898,'Прогреть на сковороде сливочное масло с сахаром, убрать с огня. Выложить тонко нарезанные яблоки внахлест. Готовое слоеное тесто раскатать до диаметра сковороды и накрыть яблоки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2898,'Печь в течение получаса при температуре 180 градусов.  Пирог немного остудить. Перевернуть «Тарт Татен» с яблоками тестом вниз на большую тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2899,'Для приготовления блюда отварить рис, посолить по вкусу, добавить сливочное масло и шафран для цвета. Дать массе постоять два часа при комнатной температуре. В смесь можно добавить немного тертого сыра Пармезан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2899,'Положить на ладонь рис, сформовать лепешку. Сверху – немного начинки и кусочек сыра. Закрыть рисом начинку, колобок обмакнуть в воду с мукой или во взбитые яйца. Обвалять рисовые «Аранчини» с начинкой в панировочных сухарях, жарить во фритюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2900,'Для основы измельчить в крошку готовое печенье, удобнее это делать в полиэтиленовом пакете. Растопить сливочное масло с медом, все ингредиенты перемешать. Массу переложить в смазанную форму для выпечки, сформовать высокий бортик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2900,'Для начинки: выжать сок из лаймов. Отдельно взбить яйцо и белок, влить сок и сгущенку. Смесь хорошо перемешать и вылить в форму. Печь в течение 25 – 30 минут при температуре 170 градусов. Середина пирога должна остаться мягкой. Готовый пирог с лаймом остудить и оставить в холодильнике на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2901,'Филе освободить от костей и нарезать на стейки. Приготовить маринад из растительного масла, и любых приправ. Хорошо обмазать подсоленную рыбу, дать полежать для пропитывания полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2901,'Натереть морковь на крупной терке, уложить на дно противня. Нарезать лук полукольцами, тоже выложить на противень. Сверху – рыба, намазать ее майонезом, укрыть блюдо фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2901,'Печь семгу на овощах в духовке в течение 20 минут. Фольгу снять, на каждый стейк положить немного лука, моркови.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2902,'Для приготовления теста натереть на крупной терке сливочное масло, добавить творог, перемешать. Добавить сырое яйцо, снова перемешать. Отдельно смешать муку с пищевой содой, сахарным песком, солью и творогом, перемешать обе массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2902,'Получившееся крутое тесто на 10 минут поставить в холодильник. Соединить для начинки перетертую брынзу или сыр Сулгуни, сметану, яйцо, давленый чеснок.  Тесто разделить на две одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2902,'Разъемную форму для выпечки смазать растительным маслом, выложить тесто, растянуть его руками. Выложить начинку, сверху оставшееся тесто, также тонко растянутое. Печь в течение получаса при температуре 180 – 190 градусов. Остудить грузинский пирог «Хачапури» в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2903,'Измельчить через мясорубку репчатый лук. Добавить мясной фарш, молотый перец, молоко. Массу перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2903,'Для теста соединить муку, немного взбитое вилкой яйцо, влить подсоленную воду. Замесить тесто. Обернуть пленкой, оставить на полчаса, затем еще немного обмять. Тесто разделить на части, раскатать и вырезать кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2903,'Сформовать пельмени, заморозить, хранить в морозилке, в полиэтиленовом пакете. Отваривать домашние пельмени с мясным фаршем в кипящей воде, соль, лавровый лист, перец-горошек – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2904,'Взбить сахар с яйцами до пышности. Растопить пачку маргарина, остудить до комнатной температуры и добавить в яичную массу. Снова взбить. Всыпать муку с разрыхлителем, перемешать. Влить сметану небольшими порциями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2904,'Для начинки перемешать протертый творог, яйца, сахарный песок, ванильный сахар и ванильный пудинг из пачки. Продукты перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2904,'Тесто раскатать и нарезать кружками. Выложить на одну сторону начинку, другой половиной прикрыть. Пирожки смазать яйцом и печь при температуре 180 градусов в течение 17 – 20 минут, творожные сочники должны зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2905,'Клубни картофеля вымыть, не чистить. Разрезать каждую на две части вдоль. Десертной ложкой, аккуратно, выскрести мякоть. Должны остаться бортики толщиной 5 –7 мм. Положить полученные лодочки в холодную воду, чтобы клубни не почернели и «отдали» лишний крахмал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2905,'Растопить сливочное масло, обжарить на нем шампиньоны, потушить 5 –7 минут на среднем огне, добавить рубленый репчатый лук. Потушить все вместе еще столько же, всыпать муку. Перемешать, масса должна немного загустеть. Влить сливки или сметану. Соль и перец – по вкусу. Поварить еще 3 – 4 минуты, снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2905,'Форму для запекания смазать маслом, выложить лодочки, в каждую положить по кусочку сливочного масла, посолить, поперчить и наполнить грибной начинкой. Печь в течение 15 минут при температуре 180 – 200 градусов. Почти готовый грибной жульен в картофеле посыпать тертым сыром и печь еще 15 минут, до зарумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7717,'Добавить размятый банан, сырые куриные яйца, мёд и ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2906,'Пропустить чеснок через пресс, перемешать с тертой сырой морковью. Заправить массу майонезом. Нарезать мелкими кубиками копченую колбасу и свежие огурцы, натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2906,'Выкладывать слоями: морковь с чесноком, колбаса, майонез, огурцы, майонез, консервированная сладкая кукуруза. Украсить слоеный салат «Осень» с копченой колбасой веточкой укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2907,'Взбить в кухонном комбайне сахарный песок, муку, соль. Добавить мягкое сливочное масло, взбить в крошку. Добавить ледяную воду и взбить массу еще раз. Добавить геркулес, снова взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2907,'Выложить готовое тесто в смазанную разъемную форму, растянуть, сформовать невысокий бортик. Печь около получаса при температуре 200 градусов. Корж остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2907,'Приготовить крем: вскипятить молоко на тихом огне. Отдельно взбить сахар с желтками, ванилином из пакетика и просеянной мукой. Влить тонкой струйкой теплое молоко, довести до кипения на среднем огне. Поварить 5 – 10 минут, остудить и взбить миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2907,'Вылить массу на корж, сверху выложить виноград, вдавить ягоды в крем. Охладить тарт со свежим виноградом в течение двух часов (можно дольше). При подаче посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2908,'Мясной фарш обжарить с луком. Выложить массу на листы тонкого лаваша, добавить зелень, помидоры, нарезанные кружочками, соломку красного сладкого перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2908,'Лаваш свернуть рулетом, уложить в смазанную и присыпанную сухарями форму. Сделать несколько таких трубочек, они должны лежать плотно друг к другу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2908,'Для приготовления заливки смешать сырые яйца, сметану, майонез, соль, перец, специи. Залить смесью запеканку с мясным фаршем, посыпать тертым твердым сыром и зарумянить в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2909,'Натереть картофель, отжать, слить лишнюю жидкость. Всыпать крахмал, соль, рубленый зеленый укроп, яйца, сметану. Массу перемешать. Мясной фарш смешать с тертой луковицей и шампиньонами, также натертыми на мелкой терке. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2909,'Выложить на сковороду немного «теста» из картофеля, затем начинку, накрыть еще одной картофельной лепешкой. Жарить с двух сторон, излишки жира можно удалить с помощью бумажного полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2909,'Готовые колдуны выложить в сотейник, закрыть фольгой или крышкой, печь 20 – 30 минут при температуре 180 градусов. Грибы нарезать кусочками, обжарить на масле рубленый репчатый лук. Добавить грибы, обжарить все вместе, подлить сметану, всыпать приправы. Дать закипеть. Подать к колдунам с мясной начинкой в качестве соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2910,'Белки охладить и взбить в пену, масса должна увеличиться в объеме. Добавить половину нормы сахарного песка, взбивать еще минуту. Желтки взбить с оставшимся сахаром, добавить какао-порошок и аккуратно перемешать. В массу постепенно вмешать белки, перемешивать осторожно, движениями снизу вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2910,'Противень выложить бумагой для выпечки, смазать сливочным маслом, распределить тесто ровным слоем. Печь в течение 30 – 35 минут при температуре 180 градусов. Корж остудить и разрезать на четыре одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2910,'Для крема нагреть сливки почти до кипения, но не кипятить. Снять с огня, добавить плитки шоколада, поломанные на кусочки. Прогревать до растворения, крем должен получиться однородным.  Коржи промазать полученной шоколадной массой, верх и бока также смазать. Остудить аппетитный шоколадный торт в холодильнике в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2911,'Отварить картофель, приготовить пюре. Немного остудить. Добавить сырое яйцо, перемешать, всыпать муку, соль. Должно получиться мягкое картофельное тесто, скатать его в шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2911,'Для начинки мелко нарезать укроп, размять вилкой отваренные вкрутую яйца. Размять консервированные в масле сардины, все перемешать, можно добавить немного масла из консервной банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2911,'Картофельные шарики расплющить, положить начинку, слепить пирожки. Жарить картофельные зразы с начинкой из сардин на сковороде до готовности, с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2912,'Клубни картофеля вымыть, отварить в мундире, охладить и очистить. Каждый клубень разрезать вдоль, пополам, вынуть мякоть ложкой из середины, делать это нужно аккуратно, чтобы не сломать лодочку. Мелко нарезать ветчину и репчатый лук, натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2912,'Мелко порубить зелень, смешать с мякотью картофеля. Массу заправить сметаной, соль и перец – по вкусу. Выложить начинку в картофель. Печь закусочные лодочки из картофеля в течение получаса при температуре 220 – 250 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2913,'Телячьи или свиные шницели отбить. Натереть мясо солью и перцем и выложить в форму для запекания. Мелко порезать репчатый лук и зелень петрушки, добавить к рубленому мясу, вбить яйца, всыпать панировочные сухари. Массу посолить, поперчить по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2913,'Готовый фарш выложить ровным, тонким, слоем на шницели. Смешать сливки с сухим белым вином и полить блюдо. Посыпать тертым твердым сыром, печь шницель «Нельсон» в сливочном соусе в течение 45 – 50 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2914,'В смешанный мясной фарш добавить рис, тертый репчатый лук, зелень петрушки и сельдерея.  Всыпать молотый тмин и мускатный орех, помидоры ошпарить, очистить от кожицы и натереть на терке. Мелко нарезать красный болгарский перец. Все ингредиенты перемешать, посолить, поперчить, разбавить овощным бульоном. Массу на час поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2914,'Разъемную форму среднего размера застелить фольгой, а затем пекарской бумагой. Кочан капусты разобрать, листья запарить, срезать утолщения острым ножом. Выстелить ими форму так, чтобы они свисали за бортики. Если листья тонкие, то можно сделать два слоя. Выложить половину фарша, полить остатками бульона, накрыть еще одним слоем листьев. Слои повторить, полить блюдо сверху растительным маслом и лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2914,'Слоеный пирог «Ленивец» из капусты и фарша закрыть фольгой, печь около часа в духовке, при температуре 190 градусов. Фольгу снять, дать подрумяниться в течение 10 минут. Можно дополнительно посыпать тертым сыром и еще немного запечь. Выделившийся соус слить, полить им готовое блюдо, если пирог получился суховатый.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2915,'Очистить и натереть на мелкой терке корень имбиря. Взбить мягкое сливочное масло с сахаром, масса должна побелеть. Влить мед, снова взбить, добавить сырые яйца, в последнюю очередь – имбирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2915,'Муку смешать с солью и разрыхлителем. Смесь просеять в масляную смесь и замесить тесто. Посуду накрыть пищевой пленкой или крышкой, поставить в холодильник на два часа или больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2915,'Перед выпечкой достать тесто из холодильника, брать его столовой ложкой, слепить шарики. Обвалять их в сахарном песке, выложить на застеленный бумагой или пергаментом противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2915,'Бумагу или пергамент можно дополнительно смазать сливочным маслом. Изделия немного приплюснуть, чтобы получились лепешки.  Печь имбирное печенье с медом при температуре 180 градусов в течение 10 – 15 минут до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2916,'Взбить яйца с сахаром в течение 8 – 10 минут до увеличения объема в три раза. Просеять муку через частое сито, растопить сливочное масло. Медленно вмешать муку и масло в яичную массу. Тесто разделить на три части. В одну всыпать какао-порошок, в другую – розовый пищевой краситель, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2916,'Выложить тесто в три одинаковые формы небольшого диаметра, выстеленные пергаментом. Печь в течение 12 – 15 минут при температуре 180 градусов. Коржи в процессе выпечки должны отойти от края формы, остудить их на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2916,'Взбить миксером сливочное масло комнатной температуры и сливочный сыр в течение 6 – 8 минут. Добавить сахарную пудру, взбивать еще столько же, масса должна стать легкой и воздушной. Смазать все коржи и верх трехцветного торта «Радуга» полученным кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2917,'Смешать сырые яйца, сахарный песок, сливочное масло, просеянную муку и пищевую соду, погашенную лимоном. Можно сделать это вручную, с помощью венчика, или миксером. Тесто должно быть полужидким. Треть массы смешать с тертым, вместе с цедрой, лимоном, Две трети – с тертой на мелкой терке морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2917,'Выложить в форму для выпечки половину теста с морковью, затем – с лимоном, сверху – вторая часть морковного теста. Печь в течение 10 минут при температуре 200 градусов, закрыть торт «Любовь-морковь» фольгой и печь еще 20 – 25 минут. Готовую выпечку охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2963,'Переложить подготовленные классические творожные сочники на противень (смазать предварительно маслом), верх каждого промазать чуть взбитым желтком. Выпекать',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2918,'Морковь, сельдерей, картофель нарезать небольшими кубиками, тушить в кастрюле в течение 15 – 20 минут до полуготовности. Филе рыбы нарезать полосками в длину, соль, перец – по вкусу, оставить для пропитывания на 20 минут. Свернуть рулетами и скрепить зубочистками или шпажками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2918,'Натереть твердый сыр. Приготовить смесь из молока, тертого сыра и яиц, массу взбить. Добавить зеленый горошек без жидкости, перемешать. Массу выложить в форму для запекания, сверху – рыба, полить блюдо молочно-яичной смесью, выложить кусочки сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2918,'Запекать рыбные рулеты с овощами в духовке в течение получаса. При подаче посыпать рубленой зеленью укропа и петрушки и украсить зеленым горошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2919,'Грибы очистить, промыть, опустить в кипяток с солью и уксусом. Варить на тихом огне три минуты, откинуть на сито. Для теста растереть желток с солью и растительным маслом, добавить молоко, просеянную муку, замесить тесто, оно должно быть жидким по консистенции. Дать тесту постоять в течение 20 минут, затем ввести в него взбитый белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2919,'Грибы сбрызнуть растопленным сливочным маслом, лимонным соком, обмакнуть в тесто и жарить в большом количестве растительного масла. Излишки жира можно удалить с помощью бумажных полотенец. Шампиньоны, зажаренные в тесте готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2920,'Смешать кефир комнатной температуры с растопленным сливочным маслом или маргарином. Добавить сахарный песок, соль, яйцо, просеянную муку и разрыхлитель. Вымесить тесто ложкой или с помощью миксера. Масса должна быть, как густая сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2920,'Форму для выпекания смазать растопленным сливочным маслом, вылить три четверти теста, равномерно размазать. Морковь, грибы и кабачки вымыть, мелко нарезать, то и другое обжарить на сковороде, добавить специи, подлить сливки, соль – по вкусу. Тушить начинку в течение 10 минут, добавить рубленую зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2920,'Полученную массу выложить поверх слоя теста, залить оставшимся тестом. Печь около получаса при температуре 180 градусов. Готовность заливного пирога с грибами проверить зубочисткой, она должна остаться сухой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2921,'Филе пангасиуса посолить и посыпать специями, выложить на лист фольги. Отдельно обжарить рубленый репчатый лук и тертую морковь, овощи выложить на рыбу, завернуть в фольгу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2921,'Печь в духовке в течение получаса. За пять минут до готовности фольгу развернуть, пангасиуса смазать майонезом, посыпать тертым твердым сыром и рубленым укропом. Допечь в духовке до готовности. Пангасиус с овощами, запеченный под сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2922,'Перемешать манную крупу, сахарный песок, сырые яйца, творог, сметану. Добавить по вкусу соль и пищевую соду, погашенную уксусом, перемешать. Вылить массу на сковороду или в форму для запекания, печь в духовке до румянца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2923,'Сахарный песок взбить со сливочным маслом, масса должна побелеть. Добавить сырые яйца по одному, продолжать взбивать, всыпать ванильный сахар из пакетика. Отдельно смешать какао-порошок, пищевую соду и разрыхлитель. Добавить муку, кефир, продолжать взбивать вручную или с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2923,'Вылить тесто в смазанную сливочным маслом и присыпанную панировочными сухарями форму. Печь в течение 30 – 40 минут при температуре 180 градусов. Готовый корж остудить, разрезать острым ножом по горизонтали на две равные части. Консервированные мандарины отцедить от жидкости. В сок добавить желатин и дать набухнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2923,'Взбить сливки с сахаром и загустителем в крепкую массу, добавить отдельно растопленный желатин. В кольцо от разъемной формы выложить один корж, вылить сливочный крем, накрыть вторым коржом, обмазать остатками крема, выложить мандарины и залить мандариново-желатиновой смесью. Шоколадно-мандариновый бисквитный торт готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2924,'Порезать мясо крупными кубиками, для равномерного прожаривания они должны быть примерно одинакового размера. Смешать соль и черный перец, обсыпать кусочки мяса, побрызгать их уксусом, перемешать с кольцами лука, убрать на холод часов на 5-6.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2924,'Распустить в сковороде сливочное масло, припустить до мягкости полукольца фиолетового лука в течение 5 минут, добавить порубленный чеснок, обжарить все вместе около минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8251,'Обвалять изделия в муке и яйце, обжарить со всех сторон до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2924,'Шляпки грибов порезать на четвертинки, ножки измельчить, жарить до полуготовности, добавить промаринованное и отжатое мясо, обжарить до красивой хрустящей корочки соломенного цвета, положить обжаренный лук, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2924,'Переложить содержимое сковороды в форму, довести грузинский шашлык из говядины по-мирзаански примерно минут за 15 до готовности в духовке, прогретой до температуры чуть выше 210 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2925,'Перемолоть на мясорубке мясо, лук, морковь, добавить крупно натертый и отжатый от лишнего сока кабачок, вареный рис и очень хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2925,'Порубить очень мелко зелень, высыпать к фаршу, вбить яйцо, сдобрить перцем и солю, хорошо вымешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2925,'Сформовать из фарша куриные котлеты с рисом и овощами, обвалять со всех сторон в муке, зажарить в сильно разогретом масле, подать горячими с любым гарниром',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2926,'Порезать подготовленное сало на небольшие бруски, сделать в каждом куске, немного не доходя до шкурки продольные разрезы. Чеснок нашинковать пластинками, перемешать молотый и крупнодробленый горошек черного перца с солью. Наполнить разрезы чесноком, обмазать сало солевой смесью и обложить со всех сторон пластинками чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2926,'Уложить обработанные куски в глубокий лоток, переложить между кусками лавровый лист, прикрыть крышкой от лотка меньшего размера и чем-нибудь ее придавить. Дать домашнему салу с чесноком постоять на столе пару-тройку часов, поставить в холодильник желательно на сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2927,'Очень тонко пошинковать капусту и чуть присолить, нарезать кубиками колбасу. Оставшиеся ингредиенты положить в чашу блендера и взбить, перемешать полученную смесь с капустой и колбасой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2927,'Заполнить капустно-колбасным тестом формочки, запекать кексики из капусты до полной готовности при температуре духовки около 220 градусов. При подаче ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2928,'Вскипятить воду в кастрюле с толстым дном, положить масло, дать ему растаять, перемешать. Добавить небольшими порциями муку, очень тщательно перемешивая после каждой порции, убрать с плиты, дать чуть остыть. Включить для прогрева до 175 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2928,'Вмешать по одному все яйца до получения однородного теста. Выложить на смазанный противень, используя чайную ложку, небольшие шарики теста. Задвинуть противень  с в духовку, дверцу не открывать до полной готовности десерта. Когда основа остынет наполнить ее кремом. Воздушные профитроли с шоколадным кремом готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2929,'Перемешать творог и яйца, взбить до однородного состояния, всыпать сахар и кубики фруктов, хорошо перемешать, переложить в форму с высокими бортиками, поставить в микроволновку с мощностью 750 Втт на 3 минуты. При более высокой мощности время приготовления будет меньше. Когда творожное суфле с фруктами будет готово, то на нем образуется плотная верхняя корочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2930,'Отрезать у крупной головки чеснока верхушку высотой около 1 сантиметра. Нож должен быть очень острым, чтобы не мял чеснок, а резал. Полученную нижнюю часть головки положить в кружку, облить оливковым маслом, прикрыть блюдечком, поставить на пару минут в микроволновку, чтобы чеснок размяк. Достать, дать чесноку остыть, очистить и размять зубчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2930,'Сварить выбранную пасту, согласно указаниям на упаковке, отцедить жидкость, оставить стакан отвара для приготовления соуса. Перемешать рикотту с размятым чесноком, сдобрить черным перцем и солью, влить оставленный отвар, перемешать до однородного состояния. Смешать пасту с порезанными на половинки черри, шпинатом, залить соусом, размешать, присыпать стружкой пармезана, еще раз аккуратно перемешать. Салат с пастой, помидорами черри и чесноком готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2931,'Сложить в чашу блендера крупно нарезанный репчатый лук, предварительно замоченные и отжатые ломти батон без корочки и мелко нашинкованную петрушку, перемолоть в однородную массу, добавить мясной фарш, перемешать. Вместо блендера можно использовать привычную мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2931,'Переложить фарш в подходящую по объему миску, всыпать порошок горчицы, добавить желток яйца, очень тщательно перемешать. Если фарш для приготовления котлет получиться густым, то влить немного воды и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Массу хорошо перемешать, добавить отдельно взбитые яичные белки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2931,'Взбить оставленные белки в пену, соединить половину с фаршем, осторожно перемешать, добавить вторую половину, окончательно перемешать. Сформовать, смочив руки, небольшие по размеру и толщине мясные котлетки, обжарить в хорошо прогретом масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2932,'Засыпать порцию хлопьев в миску, налить теплой воды, дать постоять четверть часа, сцедить, очистить банан и мандарины. Нарезать банан на сантиметровые кружочки, с долек мандарина удалить пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2932,'Переложить фрукты к овсянке, приправить салат медом, добавить сливки, перемешать, переложить в салатницу, оформить любыми ягодами. Фруктовый салат с медом и овсяными хлопьями готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2933,'Отварить чищенную картошку практически до полной готовности, мелко порубить чили и чеснок, болгарский перец (разноцветный) и лук порезать на кубики. Растереть в ступке чеснок, чили, тмин, паприку с добавлением уксуса и масла, подсолить, перемешать, можно добавить еще и рубленую зелень, но не обязательно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2933,'Нагреть в сковороде несколько ложек масла, обжарить картошку (маленькую можно целиком), добавить лук, обжарить до размягчения. Всыпать в картошку кубики болгарского перца, положить приготовленную заправочную смесь, перемешать, жарить минут 5-6, если надо, то по вкусу подсолить. Горячий острый картофель с красным перцем разложить по тарелкам, присыпать петрушкой, можно добавить укроп и базилик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2934,'Высыпать на стол муку, добавить кубики охлажденного масла и творог, порубить широким ножом до маслянистой крошки, положить желток, вымесить тесто, сформовать колобок, обернуть пленкой, положить мину на 40 на верхнюю полку холодильника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2934,'Притрусить стол мукой, достать и раскатать в пласт тесто, порезать кусочками треугольной формы, посыпать поверхность будущих рогаликов смесью корицы с мелким сахаром, свернуть в трубочку, начиная с длинного конца, убрать на полчаса в морозилку. Переложить домашние творожные рогалики на подготовленный противень, выпекать около получаса, не превышая 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2935,'Взбить удобным путем стакан сахара и пару яиц, смешать с творогом, всыпать соду, посолить, перемешать, всыпать стакан муки, перемешать, добавить второй стакан муки, вымесить тесто, порезать на 8 равных частей, убрать на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2935,'Приготовить смесь для крема из пары яиц, стакана сахара, муки, пары стаканов молока, хорошо все взбить, поставить на плиту, при помешивании дать закипеть, убрать с плиты, положить масло, все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2935,'Выпекать коржи для творожного торта «Рафаэлло» несколько минут, разложить их на столе, дать чуть остыть, промазать молочным кремом, собрать торт, присыпать верх десерта стружкой из кокоса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2936,'Смешать все ингредиенты для приготовления десерта, проварить при помешивании минут пять. Разлить полученную массу для апельсиновых карамелек по формочкам, дать постоять и хорошо остыть до полного отвердения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2937,'Отварить яйца вкрутую, порубить, огурец почистить, порезать кубиками или натереть на крупной терке и отжать сок, порезать на небольшие кусочки, размороженные крабовые палочки. Все смешать, всыпать мелко порезанный зеленый лук и порубленную зелень укропа, подсолить, приправить майонезом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2937,'Поставить на тарелку металлическое кольцо, заполнить салатом, слегка утрамбовать, аккуратно удалить кольцо, оформить зеленым луком, подать ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2938,'Тщательно промыть лимоны, желательно со щеткой, у трех тоненькой стружкой срезать цедру (желтый слой без белого, т.к. он дает напитку горечь), переложить в миску, залить соком из оставшихся лимонов, засыпать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2938,'Залить все кипятком, тщательно размешать, прикрыть крышкой, оставить полезный натуральный лимонад ночевать в прохладном месте. Созревший напиток перемешать, всыпать сахар, перемешать, процедить, разлить для хранения по бутылкам, герметично укупорить, убрать на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2939,'Курицу (или ее отдельные части) промыть, после чего отварить в подсоленной воде. Подождав, когда мясо остынет, его необходимо отделить от костей и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3033,'Заполнить хорошо охлажденным тестом для песочных орешков форму, выпекать «скорлупки» до светло соломенного цвета, дать остыть, наполнить вареной сгущенкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2939,'Морковь и лук почистить, тонко порезать и обжарить в масле на сковороде до мягкого состояния. Шампиньоны промыть, обсушить, порезать на мелкие кусочки и обжарить в масле. Вареные вкрутую яйца измельчить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2939,'На низ кладем куриное мясо. Затем выкладываем обжаренные морковку и лук. Добавляем в салат измельченные яйца. И в верхний слой выкладываем обжаренные грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2939,'Последний этап приготовления – заливаем салат слоеный с курицей майонезом и даем ему выстояться несколько часов в прохладном месте, чтобы все слои хорошенько пропитались. Перед подачей на стол блюдо можно украсить веточкой зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2939,'Вариант 2:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2940,'Почистить картошку, нарезать на кружочки, выложить ими дно подготовленной формы, чуть присолить. Прикрыть картофель полукольцами лука, затем – кубиками курятины, присыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2940,'В чашу блендера загрузить яйца, йогурт (можно заменить хорошей сметаной), сыр, все взбить, залить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2940,'Задвинуть форму в разогретую духовку, запекать до полной готовности и образования красивой корочки соломенного цвета. Минут за 7-10 до окончания приготовления присыпать поверхность сочной куриной запеканки зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2941,'Для приготовления блюда выбрать рассыпчатый сорт картофеля, почистить клубни, разделить каждый на две половины, удалить среднюю часть, переложить в форму. Перемешать нашинкованный мелко лук и фарш, подсолить, поперчить, добавить по ложке масла и майонеза, перемешать, скатать небольшие шарики, выложить их на картошку',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2941,'К замороженным овощам добавить вырезанную из клубней «лишнюю» картошку, влить масло, майонез, сдобрить солью и перцем, перемешать, переложить на середину выбранной формы, а по краям разложить кусочки куриного мяса (по желанию).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2941,'Выпекать фаршированный картофель с мясной начинкой  около 180 градусов в течение примерно 50 минут. Степень готовности блюда регулярно контролировать, достать противень, присыпать содержимое сырной стружкой, подержать еще минут 10 в довольно горячей духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2942,'Филе курицы нарезать на тоненькие пластинки (удобнее работать со слегка подмороженным мясом), если получились толстыми, то отбить, присыпать солью, паприкой, свежее смолотым черным перцем, порошком чеснока. Включить прогреваться до 180 градусов духовку. Скатать с усилием мясо в трубочку, для прочности закрепить зубочистками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2942,'Насыпать на плоскую тарелку муку, обвалять рулетики, окунуть потом в слегка взбитое вилкой яйцо, хорошо обвалять в размолотых сухарях. Переложить на решетку, поставить в уже прогретую духовку, под решетку установить большую сковороду или противень, рулетики из куриного филе в панировке будут готовы минут через 20-30.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2943,'Печенье измельчить удобным способом до состояния крошки, орехи чуть обжарить на сковороде, снять коричневую пленку и тоже измельчить, перемешать с печеньем, оставить пару ложек для обсыпки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2943,'Масло положить в сотейник и довести жидкого состояния, всыпать какао, перемешать и добавить сгущенку, еще раз хорошо перемешать, вылить к подготовленной крошке, добавить ликер, вымешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2964,'Залить на пару часов огурцы холодной водой, подготовить набор специй, промыть листья, банки для надежности лучше простерилизовать, но можно этого и не делать, дать им высохнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2943,'Скатать небольшие шарики или цилиндрики, в отложенную крошку всыпать какао, перемешать и обвалять их со всех сторон. Переложить оригинальные десертные шарики на плоскую тарелку и дать застыть  в холодильнике примерно час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2944,'Мягкое масло смешать со сгущенным молоком, всыпать порошок какао, можно добавить вино. Измельчить печенье и перемешать с масляной смесью до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2944,'Скатать из полученного теста пирожные, оформить верх смесью из столовой ложки сливочного масла и чайной ложки мелкого сахара, выдавливая ее из кондитерского мешка. Убрать домашнее пирожное «Картошка» на 5-6 часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2945,'Для приготовления теста перемешать чайную ложку сахара с чуть теплой водой и дрожжами, подсолить, влить масло, добавить муку, смешать в комбайне до получения теста. Смазать миску растительным маслом, переложить тесто, прикрыть тканью, дать постоять для созревания час-полтора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2945,'Раскатать половину теста в пласт примерно сантиметровой толщины, отступив от краев 6-7 сантиметров нанести по всей площади равномерным слоем томатную пасту, присыпать измельченным сыром. Следующим слоем разложить ветчину и салями, яйцо слегка взбить, смазать свободные от начинки края, свернуть в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2945,'Переложить пиццу на противень, сверху смазать яйцом, присыпать сыром, нанести поперек рулета через каждые 5-6 сантиметров разрезы, присыпать высушенной петрушкой или орегано. Поместить противень с пиццей-рулетом «Стромболи» с салями на 10-12 минут в духовой шкаф с температурой чуть ниже 250 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2946,'Порезать грудку курицы, освобожденную от кожи, на тонкие пасты, слегка отбить. Шампиньоны очистить от земли, если надо, то почистить, затем порезать на тонкие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2946,'Высыпать грибы на сковороду со смесью прогретого сливочного и подсолнечного масла, поперчить, подсолить, добавить чуть молотого мускатного ореха и гвоздики, обжарить с добавлением мелких кубиков лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2946,'Расправить отбитую пластинку мяса, положить на нее ложку готовых грибов, дополнить брусочком твердого сыра, свернуть в трубочку, переложить в форму (шов должен быть внизу).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2946,'Очищенные клубни картофеля порезать на 2-4 части (зависит от размера), а потом надрезать каждую на ломтики, не доходя на пару миллиметров до конца. Разложить картофель между мясными рулетами, залить сливками 15% жирности, в которые добавлена соль и перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2946,'Прикрыть форму фольгой, запекать рулеты из куриной грудки с грибами в сливках до полной готовности картофеля, в конце приготовления снять фольгу и довести под грилем до румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2947,'Каждое филе грудки разрезать вдоль на две половинки, слегка отбить, присыпать перцем и солью, переложить в глубокий лоток, залить сливкам, убрать в прохладное место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2947,'Нарезать лук на мелкие кубики, грибы – на тонкие пластинки, обжарить в сливочном масле. Разложить мясо на противень, на каждое филе разложить ровным слоем смесь грибов с луком, разболтать майонез и сметану, вылить на мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2947,'Присыпать куриное филе «по-французски» сырной стружкой, убрать противень в прогретую до 180 градусов духовку на 20-25 минут. На гарнир к готовому блюду лучше всего подать овощи по сезону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2948,'Нарезать мясо брусочками, обжарить в хорошо разогретом масле до коричневатой корочки. Очищенные овощи положить вместе с луком и огурцами в чашу комбайна, измельчить, вылить смесь в мясо, добавить морковь и томаты, протушить все вместе на медленном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2948,'В конце приготовления азу мясного с соленым огурцом добавить в сковороду чеснок, лавровый лист, перец и др. приправы. В качестве гарнира к блюду хорошо подойдут макаронные изделия или отварной рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2949,'Для приготовления бисквита тщательно перемешать пару яиц, пару стаканов сметаны, и пару стаканов муки с добавлением соды (погасить можно сметаной). Полученное тесто разделить пополам, одну часть оставить как есть, а в другую всыпать порошок какао и перемешать. Выпекать коржи при температуре не выше 200 градусов около трети часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3040,'Раскатать размороженное тесто в трехмиллиметровый пласт, промазать его слоем начинки, скатать с небольшим усилием в трубочку, порезать на 8 равных кусочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2949,'Для пропитки коржей из сметаны и сахарной пудры с добавлением сока от половинки лимона приготовить крем. Верх домашнего торта «Кудрявый парень» оформить глазурью из сметаны, хорошего сливочного масла, какао порошка и мелкого сахара, растопленных на огне (кипеть не давать!).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2950,'Поставить кипятится воду в кастрюле, подготовить овощи и грибы, порезать на кусочки. Обжарить на сливочном масле морковь, грибы и лук, картофель всыпать в закипевшую воду. Готовую грибную зажарку переложить к картофелю, готовить до размягчения картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2950,'Порезать твердый и плавленый сыр, положить в суп, помешивая дождаться полного его растворения, приправить солью и черным перцем, положить несколько листиков лаврушки и сухой сельдерей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2950,'Филе рыбы нарезать на небольшие кусочки, положить в кастрюлю, проварить все вместе 5-7 минут. Разболтать в холодной воде крахмал, вылить, помешивая тонкой струйкой в сырный суп с форелью и грибами, перемешать, присыпать рубленой зеленью базилика, дать прокипеть на малом огне пару минут, прикрыть крышкой, дать чуть постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2951,'Включить для прогрева чуть ниже 180 градусов духовку. В кипяток положит очищенный картофель, чуть проварить (5 минут будет достаточно), откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2951,'Переложить картофель на дно подходящей по размеру формы, уложить помидоры и моцареллу, присыпать стружкой из твердого сыра, добавить раздавленный прессом чеснок, подсолить и поперчить, сбрызнуть оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2951,'Поставить форму на треть часа в духовку, готовить до красиво зажаренной корочки и полного расплавления сыра. К столу картофель, запеченный с моцареллой подавать горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2952,'Перемешать в глубокой миске порезанные: ветчину, морковь, моцареллу, петрушку вместе с вареным рисом. Подготовить  форму для запекания, смазать маслом, переложить в нее полученную смесь, залить взбитой в блендере смесью из сливочного сыра, тертого твердого сыра, молока, яиц с добавлением перца и соли. Поместить запеканку из риса с сыром и ветчиной в прогретую до 200 градусов духовку на полчаса, готовить до золотистой верхней корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2953,'Положить в чашу блендера творог, всыпать сахар, перемешать на средней скорости. Добавить вареное сгущенное молоко, перемешать еще раз, но долго, желательно, не взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2953,'Разложить творожный десерт по креманкам в следующем порядке: взбитая творожная смесь, кусочки фруктов, далее слой натертого шоколада, и так несколько раз, верх полить клубничным вареньем, украсить ягодами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2954,'Насыпать в стакан сухой желатин, залить водой комнатной температуры, дать постоять и разбухнуть. В кастрюльку с толстым дном влить сливки с молоком, всыпать сахар, положить надрезанный вдоль ванильный стручок, довести смесь до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2954,'Убрать кастрюльку с плиты, извлечь стручок ванили, влить желатин, хорошо перемешать, если не удалось найти натуральную ваниль, то добавить эссенцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2954,'Разлить ванильную панна-котту по формочкам, дать остыть и для полного остывания поставить десерт в холодильник, чтобы он стал густым, через 3-4 часа десерт можно будет подать к столу прямо в формочках или выложить на плоское блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2955,'Муку просеять и оставить в сторону. Все ингредиенты перемешать, подсыпать по частям муку до получения мягкого и эластичного не липнущего ни к рукам, ни к столу теста. Заранее определить точное количество муки невозможно, поскольку качество у нее может быть различным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2956,'Бананы почистить, растереть в пюре, влить сок лимона, размешать. Сахарную пудру взбить вместе со сливками, соединить с банановым пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2956,'К полученной массе можно добавить взбитые по частям белки, оформить крошкой печенья или шоколада. Десертный банановый мусс готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2957,'Поставить варить мясо и яйца, лук нашинковать и обжарить до изменения цвета на золотистый. Замесить на кефире или сметане с добавлением майонеза, яиц, подсоленной муки  соды тесто по густоте напоминающее сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2964,'Разложить по банкам листья и специи, плотно заполнить огурцами, залить обычной водой. Затем воду слить, посмотреть какой получится объем и добавить по норме соли, перемешать рассол до полного растворения крупинок соли, разлить по банкам с огурцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2957,'Отварное мясо измельчить в блендере или на мясорубке, перемешать с жареным луком,  чуть подсолить. В заранее подготовленную форму вылить около половины теста, разложить ровным слоем мясную начинку, присыпать порубленными на кубики яйцами, залить оставленным тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2957,'Убрать форму с пирогом на кефире с мясной начинкой в духовой шкаф, выпекать примерно 40 минут, не превышая температуры в 200 градусов, периодически проверяя готовность зубочисткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2958,'Подготовить грибы, порезать вместе с ветчиной тоненькой соломкой, а морковь – немного покороче. Яйца протереть на терке с крупными отверстиями, разделяя белки и желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2958,'Выложить салат на блюдо слоями, соблюдая следующий порядок: морковь, грибы, крошка из чипсов, ветчина, сыр, белки яиц. Каждый слой разровнять, промазать майонезом, верх слоеного салата «Орхидея» присыпать желтками, украсить цветами из целых чипсов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2959,'Поставить варить пасту, измельчить филе лосося, обжарить в хорошо прогретом оливковом масле, переложить для остывания в тарелку. В этой же сковороде, добавив сливочное масло, обжарить нарезанный чеснок и лук, добавить помидоры, тушить все вместе около минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2959,'Влить бульон, белое вино, приправить эстрагоном, солью, красным молотым перцем и паприкой, размешать, дать закипеть. Положить стручковый перец, креветки, прогреть около минуты, добавить готовую пасту, хорошо перемешать. Заключительный аккорд: положить рыбу, отключить нагрев, присыпать фетуччини с лососем и острыми креветками перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2960,'Нашинковать перья зеленого лука, сыр натереть, перемешать в глубокой миске, добавить смесь сметаны с майонезом, еще раз хорошо перемешать. Отдельно смешать чеснок, раздавленный прессом и мягкое масло до однородности, объединить с сырной массой, перемешать. Включить для прогрева духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2960,'Булку хлеба разрезать вдоль на две части, промазать мякоть каждого куска сырно-чесночной смесью, поставить в прогретую духовку, запекать до корочки темно соломенного цвета. Достать горячий бутерброд с сыром, зеленью и чесноком, дать немного остыть, разрезать очень острым ножом на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2961,'Тщательно отделить белки, взбить со стаканом сахара, отдельно с таким же количеством сахара взбить желтки. Объединить желтки с белками, очень осторожно маленькими порциями добавить просеянную смесь муки и разрыхлителя, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2961,'Подготовить противень, выложить тесто небольшими порциями, равными примерно по объему десертной ложке, выпекать основу для торта при температуре в 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2961,'Взбить крем из сметаны и сахара до полного исчезновения крупинок сахара. На подготовленное блюдо выложить слоями остывшие печенюшки, смазанные кремом в форме панциря черепахи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2961,'Для вкуса между слоями оригинального торта «Черепашка» можно проложить тоненькие ломтики кисло-сладких яблок и присыпать дробленым орехом, верх украсить стружкой из шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2962,'Твердый сыр протереть на терке с крупным отверстиями, яйца отварить вкрутую, порезать кубиками. Довести до кипения подсоленную воду, всыпать подготовленную овощную смесь, немного проварить, добавить сыр, перемешать, проварить до полного растворения сырной стружки, всыпать в диетический сырный суп порезанное яйцо. Добавить в кастрюлю измельченную зелень, приправить молотым перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2963,'Сухой творог пропустить сквозь сито для удаления даже самых маленьких крупинок. Перемешать все ингредиенты, подготовленные для крема, лучше не используя миксер, иначе начинка получится чересчур жидкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2963,'Из размягченного масла, яйца, пудры и соли, приготовить с помощью миксера однородную массу. Из подготовленной муки отсыпать пару столовых ложек, всю оставшуюся перемешать с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2963,'Добавить небольшими порциями муку в масляную смесь, смешивать до получения мягкого теста, скатать из него шар, дать постоять треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2963,'Брать небольшие порции теста, раскатывать в овалы, на половину каждого положить начинку, прикрыть второй половиной, но так, чтобы небольшое ее количество было видно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4143,'Готовить в духовом шкафу при 210 градусах, в течение 20 минут. Запеченное с лимоном филе лосося выложить на блюдо и подать с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2964,'Составить банки в таз, прикрыть пластмассовыми крышками, дать постоять для скисания рассола трое суток в тепле, затем убрать соленые хрустящие огурчики на хранение в подвал или погреб.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2965,'Взбить все подготовленные ингредиенты, исключая муку с разрыхлителем, которые необходимо сначала просеять, а потом объединить с взбитой массой, как следует вымесить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2965,'Вырезать из пекарской бумаги 5-6 кругов, соответствующих размеру формы, промазать маслом. Каждый корж выпекать минут по 5 в духовке с температурой 180 градусов (количество теста для каждого коржа по объему не должно превышать половника), отделить от бумаги пока они еще теплые.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2965,'Добавить в 100 г взбитого со сливками сгущенного молока ванильный сахар и ром (можно и без него), отдельно взбить оставшиеся 100 г сгущенного молока с маслом. Обе смеси соединить и осторожно, но тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2965,'Сложить коржи стопкой, промазывая каждый, верхушку шоколадного торта со сливочным кремом оформить шоколадной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2966,'Нарезать грибы, нашинковать петрушку, обжарить в разогретом масле порезанную на кусочки курицу, добавить грибы и немного бульона, проварить минут 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2966,'Отлить половину бульона, положить нарезанный хлеб, дать закипеть, переложить в блендер, взбить вместе с мясом, грибами, петрушкой и желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2966,'Перелить в кастрюлю с оставшимся разогретым бульоном, приправить французский куриный суп-пюре натертым мускатным орехом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2967,'Натереть отварные яйца и сыр на терке с крупными отверстиями, одинаково мелко нарезать лук, крабовые палочки и грибы, вскрыть банку с кукурузой, жидкость отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2967,'Выложить салат на плоское блюдо слоями, промазывая каждый майонезом, но можно заменить его и сметаной: кукуруза, кубики лука, стружку сыра, яйца, завершить крабовыми палочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2967,'По желанию салат с крабовыми палочками и грибами можно не выкладывать слоями, а просто перемешать все ингредиенты, переложить в салатницу, присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2968,'Выбрать для приготовления сыра не жирный и обязательно сухой творог, положить его в кастрюлю с молоком, дать закипеть, подержать на плите (не забывая помешивать) минут 10, до тех пор пока творожная масса не начнет плавиться и слегка тянуться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2968,'Глубокий дуршлаг застелить марлей, откинуть молочно-творожную смесь, дать хорошо стечь всей жидкости. Полученная масса будет напоминать тягучий размягченный пластилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2968,'Освободить массу от марли, переложить в кастрюлю с толстым дном, добавить масло, соду, вбить яйца, подсолить, очень хорошо вымешать смесь руками, при постоянном помешивании нагреть до расплавления и нагревать (мешать не переставать!) еще примерно 6-7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2968,'Сыр «Сливочный» из творога можно считать готовым, когда масса начнет отставать от стенок кастрюли. Готовый сыр выложить на блюдо, прикрыть от заветривания пленкой, убрать на холод. Остаток сыворотки после варки сыра можно не выливать, а испечь на ней вкусные блинчики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2969,'Первым приготовить творожное тесто. Для этого смешать в блендере свежий творог с парой столовых ложек муки, яйцом, ванильным и обычным сахаром, поставить на треть часа в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2969,'Для приготовления шоколадного теста хорошо перемешать пару столовых ложек какао порошка с мукой, разрыхлителем, растительным маслом, молоком, содой и яйцом, залить кипятком, очень хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2969,'Достать замороженное тесто с творогом, уложить в чашу мультиварки, смазанную маслом, сверху вылить шоколадное тесто, установить режим выпечки, готовить шоколадный пирог на творожной основе в мультиварке  час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2969,'Достать готовый пирог из чаши, приготовить из смеси сливочного масла, сахара, молока и какао глазурь, нагрев при непрерывном помешивании все ингредиенты в течение 5 минут. Горячей глазурью залить пирог, дать пропитаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2970,'Раздавить чеснок прессом, а лучше натереть на мелкой терке, перемешать с мягким маслом, измельченной зеленью и тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3872,'Отделить с грудки индейки филе, вырезать сухожилия, натереть солью смешанной с перцем и завернуть в рулет, перевязать шпагатом и дать чуть постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2970,'Чуть черствый багет надрезать наискось, но не до конца, заполнить полученные «кармашки» сырно-чесночной смесью. Запаковать батон в фольгу, положить на противень и поместить в прогретую до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2970,'Спустя треть часа фольгу приоткрыть и оставить батон, запеченный с сыром и чесноком в духовку для зарумянивания еще на 5 минут. Подать блюдо горячим, порезав на порции по сделанным для фарширования надрезам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2971,'Подготовить, отварить и порезать грибы, обжарить их с добавлением лука на прогретом масле, дать остыть. Измельчить чуть обжаренные орехи, отдельно натереть яйца и сыр, мелко порезать отварное и охлажденное филе, чеснок пропустить через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2971,'Перемешать сыр, майонез и чеснок в однородную смесь. Салат с куриным филе и грецкими орехами выложить послойно на подходящую плоскую тарелку, каждый слой промазать майонезом. Первый слой из мяса, второй из яиц, третий из грибов и лука, четвертый из чесночного сыра, последним выложить ореховый слой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2972,'Для приготовления густого теста перемешать все ингредиенты в однородную массу. Покрыть противень тонким слоем масла, разложить ровным слоем по всей площади тесто, испечь до готовности. Нарезать прямо на противне на кружочки, обрезки растереть в мелкую крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2972,'Приготовить крем, взять кружок, погрузить в крем, со вторым поступить также, «склеить» вместе, обвалять в крошке. При желании пирожное «Лакомка» со сметанным кремом можно делать из большего количества кружочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2973,'Прогреть чуть ниже 200 градусов духовку, готовое тесто раскатать, отрезать с боков толстые полосы, сплести из них косичку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2973,'Порезать грибы и колбасу на одинаковые кусочки, обжарить в разогретом сливочном масле. Пока смесь жарится взбить яйца, перемешать с натертым сыром, добавить в сковороду вместе с рубленой петрушкой, по вкусу приправить перцем и солью, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2973,'Посередине раскатанного теста уложить яичницу, прикрыть сплетенной косичкой, смазать яичницу с грибами и колбасой в слоеном тесте взбитым яйцом, запекать до светло золотистой аппетитно хрустящей корочки примерно полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2974,'Кефир комнатной температуры перемешать с яйцами, сахаром и гашеной содой, всыпать небольшими порциями муку, смешать до образования эластичного теста. Отделить часть теста, раскатать в полусантиметровый пласт и вырезать, подходящей по диаметру чашкой заготовки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2974,'На каждый кружок выложить по ложке малины, присыпанной сахаром, сложить его пополам и очень тщательно защипать края, чтобы начинка не потеряла сочность. Положить вареники со свежей малиной в кипящую воду, отварить до готовности и сразу подать к столу вместе со сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2975,'Включить для прогрева до 180 градусов духовку. В молоко вбить яйца, чуть подсолить, взбить только слегка (иначе не получить пышного омлета). Всыпать в яичную смесь крупно натертый сыр, аккуратно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2975,'Перелить массу для сырного омлета в форму, смазанную маслом, поместить ее в уже прогретую духовку, выпекать минут 25 до появления вкусной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2976,'Обжарить нашинкованный кольцами лук в масле до изменения цвета, мелко порезать перья зеленого лука, смешать все с картофельным пюре. Просеять в большую миску муку с добавлением растительного масла и соли, залить кипятком, быстро перемешать до образования комка теста. Дать массе слегка остыть, вымесить тесто, дать ему постоять около получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2976,'Раскатать из теста лепешки, соответствующие по диаметру сковороде, проколоть в нескольких местах вилкой, чтобы они при выпекании не вдувались, выпекать до появления коричневатых пятен на сухой сковороде с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2976,'На готовые и еще горячие лепешки размазать слой картофельной начинки, так, чтобы она занимала только половину площади, прикрыть второй половиной лепешки, смазать маслом, подать кыстыбый с картофелем и луком к столу пока горячие.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2977,'Перемешать муку с растопленным маргарином. Приготовить смесь из трех яиц, пары ложек какао порошка, соды и стакана сахара, объединить с мукой и маргарином, вымесить до однородного состояния. Включить прогреваться духовку примерно до 180 градусов',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2977,'Приготовить форму, промазать ее маргарином или маслом, переложить тесто, поставить выпекаться, заняться приготовлением крема. Смешать стакан молока с парой ложек муки, добавить сахар, размягченное масло, все вместе тщательно взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2977,'Достать готовый корж, охладить его и разрезать на три пластины, промазать каждую кремом, собрать торт «Чародейка» со сливочным кремом, верх оформить дробленым орехом или шоколадной крошкой, а можно приготовить и смесь из какао, сливочного масла, сахара, молока, все довести до кипения, не забывать перемешивать. Остывшей смесью равномерно облить торт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2978,'Очистить грибы, залить подсоленной водой, дать закипеть, проварить после этого минут 12, отцедить, разрезать, в зависимости от размера, на 2-3 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2978,'Нарезать мелко лук, обжарить пару минут в масле до прозрачности, всыпать кубики картофеля, перемешать, обжарить, перемешивая, минут 15, сдобрить перцем и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2978,'Добавить в сковороду отварные кусочки опят, влить сметану, размешать. Прикрыть сковороду с картофелем и опятами в сметане крышкой, подержать при слабом нагреве еще минут 5-7, подать с овощами по сезону и измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2979,'Нагреть слегка молоко и залить дрожжи, дать постоять. Нагреть воду, залить изюм, дать постоять минут 5, откинуть на дуршлаг, выложить на бумажное полотенце, дать впитаться остаткам воды, перемешать со щепоткой муки. Смешать растопленное масло с сахаром, солью, ванильным сахаром, яйцом, растительным маслом, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2979,'К растворенным дрожжам добавить чуть просеянной муки и кефир, размешать, влить масло с добавками, добавить специи, по частям муку, а в конце – распаренный изюм, полученный шар теста смазать маслом, переложить в соответствующую емкость, прикрыть тканью, убрать в тепло на час для полного созревания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2979,'Из готового теста сформовать булочки, выложить на противень, застеленный промасленной бумагой для выпечки, дать постоять четверть часа, смазать разболтанным яйцом, поставить в духовку с температурой не больше 200 градусов. Выпекать мягкие пряные булочки с изюмом до пробуждающего аппетит золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2980,'Смешать муку с молоком (можно с водой), «быстрыми» дрожжами, растительным маслом, солью и сахаром, тщательно вымесить тесто, дать ему созреть и подойти. Обжарить часть лука, добавить его вместе с мелко порезанным сыром в фарш, начинку подсолить, поперчить, для сочности добавить чуть воды, очень хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2980,'Вырезать из теста, раскатанного в пласт, сочни диаметром примерно около 7-8 сантиметров. Положить на каждый начинку, отступив от края, смазать свободное место белком, прикрыть другим кружком из теста, тщательно защипать, чтобы фарш остался сочным, обжарить на сковороде с двух сторон в масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2980,'Затем переложить беляши с мясным фаршем на противень, прикрыть фольгой, поместить на треть часа в прогретую примерно до 180 градусов и выключенную духовку, вынуть из духовки, переложить в кастрюлю, прикрыть крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2981,'В чашу миксера вбить яйца, всыпать сахар, взбить, положить размягченное масло и сметану, еще раз взбить. Подсыпать по частям муку с разрыхлителем, добавить ваниль, замесить тесто похожее на хорошую домашнюю сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2981,'У фруктов удалить косточки, порезать на дольки. Почти все тесто положить в круглую форму, часть оставить для формирования верхушки пирога. По поверхности теста разложить персики, слегка вдавить их в тесто, сверху – сливы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2981,'Остатком теста заполнить кулинарный мешок, выдавить полоски сверху пирога. Поставить ванильный пирог сл сливами и персиками в духовку минут на 40, температуру выше 200 градусов не поднимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2982,'Приготовить из куриной грудки, лука и яйца с добавлением специй, зерен горчицы, кетчупа, муки и соли фарш. Отварить картофель, нарезанный крупными кусками до готовности, нарезать плотные помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2982,'Подготовленную форму натереть чесночной долькой, смазать маслом, выложить кусочки картофеля попеременно с колечками помидоров, по центру расположить котлетки, а вокруг присыпать полукольцами репчатого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2982,'Залить смесью из яиц, сыра и молока со сметаной, задвинуть минут на 40 в прогретую до 180 градусов духовку. Куриные ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2983,'Достать заранее масло из холодильника, когда станет мягким растереть его с сахаром и какао порошком. На лист пергамента намазать полученную смесь слоем чуть менее сантиметра, а на нее положить квадратики печенья, чтобы получить прямоугольник 3 шт. х 5 шт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2983,'Смешать полпачки мягкого масла с творогом и сахаром, тщательно. Массу из творога разложить на среднем ряде печенья, сложить в рулет треугольной формы, отправить застыть в холодильник примерно на 5 часов. Очень аккуратно удалить бумагу с десерта «Домик» из творога, переложить его на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2984,'Порезать на кружочки маслины без косточек, помидоры черри разрезать на четыре части. У красного мясистого болгарского перца удалить семенную коробку, нашинковать его мелкой и длинной соломкой, такой же по размеру соломкой нарезать ветчину и твердый сыр, порезать мелко укроп, добавить мелкие макароны, все смешать, приправить итальянский салат с макаронами майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2985,'Очистить банан и киви, порезать, перемешать, чуть помять, засыпать сахаром, добавить чайную ложечку желатина, проварить варенье минут 5, дать чуть остыть и можно подавать к столу. Таким вареньем из киви можно также промазывать коржи для торта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2986,'Натереть сыр на терке, перемешать с крахмалом, выложить полученную смесь тонким слоем на сковороду. Когда лепешка растает нагрев убрать, подождать пока расплавленный сыр чуть-чуть схватится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2986,'На дно перевернутого стакана наложить сырный «блинчик», прижат его к краям стакана, после застывания сыра снять полученную тарталетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2986,'Заполнить тарталетку любой начинкой, например салатом из огурца с креветками и укропом. Переложить тарталетки из сыра с огурцом и креветками на широкое блюдо выложенное листьями салата и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2987,'Нарезать о отварить картофель в кипящей подсоленной воде до полной готовности. Пока варится картофель почистить и нарезать грибы, нашинковать мелкими кубиками лук, такими же кубиками нарезать болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2987,'Сыр натереть, шинку и помидоры и остывший картофель мелко нарезать. Обжарить картофель в разогретом масле до красивой корочки, переложить картофель на тарелку. В оставшемся масле поджарить овощи и шинку в течение 7-8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2987,'Взбить в миске яйца до перемешивания белка с желтком, приправит черным перцем и солью, перемешать. В сковороду добавить обжаренный картофель и раздавленный чеснок, залить яйцами, обжарить треть часа на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2987,'Снять сковороду с фриттатой с овощами и грибами с плиты, присыпать сырной стружкой, поставить на гриль до расплавления сыра, нарезать на порции, разложить по тарелкам и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2988,'Порубить масло с мукой, сахаром и разрыхлителем до состояния масляной крошки, вбить яйцо, добавить воду замесить тесто. Подготовить форму, смазать маслом, разложить тесто, так, чтобы оно покрыло дно и стенки формы, наколоть тесто вилкой в нескольких местах, закрыть пергаментной бумагой и засыпать фасолью, запечь 10 минут в духовке с температурой не превышающей 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2988,'Пока печется основание, приготовить начинку. Хорошо взбить сливки, сахар и творог, вбить яйца и еще раз перемешать. Нарезать на дольки груши, разложить их на дно готового основания для пирога, залить смесью из творога, присыпать верх ягодами. Поставить выпекать пирог в прогретую до 200 градусов духовку минут на 40. Достать форму, дать пирогу с творогом, грушами и ягодами остыть, переложить его на блюдо, присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2989,'Очистить яблоко от  кожуры и семенной коробки, нарезать на кусочки и измельчить в блендере, имбирь натереть на терке, смешать с тертой морковью и апельсином. Если для приготовления морковно-апельсинового смузи использовать пакетированные соки, то их можно просто перемешать блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2990,'В сотейнике смешать вино с сахаром и водой, прогреть до тех пор пока сахара не растворится. Разделить абрикосы на половинки, удалить косточки, положить в сотейник, проварить примерно минуту, добавить листики мяты и ванилин, протушить все вместе около 5 минут. Подавать абрикосы в белом вине с мятой можно с мороженым или йогуртом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Включить духовку для разогрева, квадратную форму (20 на 20 см) для выпекания смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2991,'Вскипятить воду, добавить масло, перемешать, сразу засыпать просеянную и подсоленную муку. Вымешать смесь миксером до образования теста, которое должно легко отставать от стенок кастрюли, дать ему остыть и вбить, размешивая после каждого, яйца, тщательно перемешать до гладкости, убрать минут на 40 в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2991,'За это время прогреть примерно до 200 градусов духовку, налить в невысокую кастрюлю воду, поставить вниз духовки, чтобы при выпекании основы для торта не дать ей пересохнуть. Подготовить противень: выстелить пергаментом, промазать его маслом. Заполнить шприц или фунтик охлажденным тестом, выдавить тонкое печенье длиной примерно по 5-7 сантиметров, запечь до золотистости, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2991,'Из взбитой с сахаром с добавлением сгустителя сметаны приготовить крем. Хорошо остывшие «пальчики» обмакнуть в крем и уложить на плоское блюдо горкой, полить слои и верх торта кремом, оформить стружкой из темного шоколада. Торт «Дамские пальчики» с шоколадным кремом готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2992,'Порезать на кубики подготовленное филе курицы, переложить в мультиварку, задать режим «Жарка», готовить до красивой корочки золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2992,'Обдать кипятком помидоры, удалить шкурку, измельчить, репчатый лук нашинковать на мелкие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2992,'Вынуть кусочки мяса, засыпать смесь из лука и помидоров, обжарить минуты 3-4, влить чуть воды, перевести мультиварку в режим «Тушение».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2992,'Добавить к овощам курицу, влить сливки, тушить куриные грудки в сливках в мультиварке еще минут 10. Подать блюдо горячим с салатом, рисом или картофелем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2993,'Нашинковать кабачок кольцами средними, окунуть во взболтанное яйцо, затем в муку, обжарить с обеих сторон, разложить на бумажном полотенце для удаления остатков масла. Протереть морковь на терке с крупными отверстиями, порубить как можно мельче чеснок, помидоры порезать на кольца, лук – на полукольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2993,'Смазать противень или большую сковороду маслом, уложить  в два слоя кольца кабачков одно к другому, прикрыть их слоем из вареной и нарезанной тонко поперек грудки курицы. Уложить на мясо слой из лука с морковью, далее помидоры, закончить чесночным слоем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2993,'Верх диетической пиццы из кабачка с куриным филе присыпать сыром, залить разболтанным с молоком (водой) яйцом, присыпать зеленью, отправить в духовку, держать до расплавления сыра в красивую румяную и очень аппетитную корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2994,'Потушить мелко нашинкованный лук до прозрачности при слабом нагреве, курицу порубить на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2994,'Сложить мясо в сотейник, прикрыть луковым «одеялом», сдобрить перцем и солью, присыпать не жалея измельченной кинзой, положить порезанный на дольки помидор. Тушить чахохбили из курицы с кинзой до готовности на слабом огне, прикрыв посуду крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2995,'Нарезать на куски бананы, положить в чашу миксера, залить сгущенкой и пастеризованным молоком, вбить свежие (лучше домашние) яйца, тщательно взбить до однородности. Затем, продолжая взбивать, добавить непрерывной тоненькой струйкой водку. Банановый ликер процедить, разлить в бутылки, дать настояться, подавать напиток к столу в охлажденном виде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2996,'В глубокую миску положить творог, всыпать сахар, муку с содой, добавить взбитые с солью яйца, хорошо все перемешать. Хорошо разогреть в сковороде масло, выложить массу столовой ложкой горками на некотором расстоянии друг от друга. После обжарки с одной стороны перевернуть, сковороду накрыть крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2996,'Разделочную доску застелить бумажными полотенцами в два слоя, выложить на них пышные, мягкие ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2997,'Заранее достать масло, а потом его растопить, хорошо растереть сахар с яйцами, перемешать с маслом и молоком, всыпать муку, замесить тесто, разрезать на 3 части, убрать в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2997,'Достать хорошо замороженное тесто, протереть на крупной терке, выложить небольшими порциями на пергамент и запечь по 10 минут при температуре не выше 160 градусов до золотистого окраса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2997,'Порубить обжаренные грецкие орехи, измельчить испеченные коржи, добавить вареную сгущенку, осторожно и очень хорошо перемешать, выложить торт «Муравейник» с орехами, дать постоять и чуть застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2998,'Залить кипятком инжир, дать немного постоять, слить воду, дать остыть, обсушить полотенцем из бумаги. Растопить горький шоколад либо используя водяную баню, либо – микроволновку, добавить немного хорошего сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2998,'Надрезать крестообразно ягоды инжира, нафаршировать крупно порубленными ядрами грецкого ореха, придать форму трюфеля, обмакнуть в шоколад, осторожно разложить на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2998,'При желании чуть застывший слой шоколада покрыть порошком какао, оформить орехами и убрать до полного застывания в холодильник. Шоколадные конфеты из инжира с грецкими орехами готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2999,'Добавить к муке соль, разрыхлитель и сахар, перемешать. Разболтать йогурт с маслом, всыпать небольшими порциями муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2999,'Присыпать стол мукой положить тесто, поделить примерно на 10 комочков, сформовать булочки, переложить их на противень, застеленный промасленным пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (2999,'Задвинуть противень с булочками без яиц и дрожжей в прогретую чуть выше 200 градусов духовку примерно на треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3000,'Порезать соломкой колбасу и огурец, если у огурца жесткая шкурка, то ее желательно удалить. Очень тонко порезать капусту и слегка помять руками, сыр крупно натереть, вскрыть банку кукурузы, слить жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3000,'Объединить все ингредиенты, приправить салат со свежей капустой и копченой колбасой майонезом, аккуратно перемешать, попробовать и по желанию можно чуть присолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3001,'Обжарить мелко нашинкованный лук, когда он поменяет цвет добавить в сковороду фарш, яйцо, сдобрить солью, перцем, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3001,'Бублики замочить в молоке, следить, чтобы не размокли, а лишь слегка размякли, достать, заполнить их центр фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3001,'Взболтать яйца, обмакнуть в них фаршированные бублики, а потом – в муку, обжарить с обеих сторон в хорошо разогретом масле до образования аппетитно зажаренной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3002,'Подготовить печень, помыть, вырезать протоки, зачистить от верхней пленки. Куски присолить, посыпать специями и мукой, зажарить в хорошо разогретом масле. Раздавить чеснок прессом, орехи раздробить, прогреть в сковороде масло, обжарить около минуты чеснок, всыпать орехи, прожарить еще три минуты, не забывая помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3002,'Всыпать в сметану муку, перемешать, перелить к чесноку и орехам, соус прогреть, подсолить, добавить немного карри, довести до кипения, положить обжаренную печень, закрыть сковороду крышкой, сделать минимальный нагрев, тушить куриную печень в ореховом соусе еще минут 10, присыпать мелко нашинкованной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3003,'В сгущенное молоко вбить яйца, хорошо взбить, всыпать смесь муки, разрыхлителя и соды, перемешать до образования слегка жидкого теста без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3003,'Включить прогреться  до температуры 190 градусов духовку. Из приготовленного теста выпечь 5 коржей. На выпекание каждого уйдет примерно по 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3003,'Из вареной сгущенки и сметаны взбить крем, промазать коржи кремом и собрать стопкой в вкусный домашний торт, верхушку оформить по своему усмотрению.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3004,'Развести сок лимона 1:1 водой, залить желатин, дать постоять 5 минут, подогреть, чтобы желатин полностью распустился, дать раствору остыть. В творог влить йогурт, добавить мед, перемешать, объединить с желатином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3004,'Дно формы выложить слоем ягод и фруктов, залить смесью желатина с творогом. Верх легкого чизкейка из обезжиренного творога разровнять и оправить десерт ночевать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3005,'Порезать филе на куски, выложить ими дно формы для запекания, слегка присолить, прикрыть мясо кружочками помидора и тоже чуть подсолить, промазать равномерно майонезом. Разложить поверх майонеза ровным слоем кусочки ананаса, присыпать (не жалея) тертым сыром и приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3005,'Поставить форму в духовку с температурой чуть выше 200 градусов, куриная запеканка с ананасами и помидорами будет готова минут через 40, когда покроется золотистой корочкой. Подавать блюдо можно как самостоятельное, так и с гарниром из сезонных овощей, рисом или картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4454,'Раскатать из теста небольшие тонкие лепешки овальной формы, положить фарш на одну половинку, накрыть второй и защипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3006,'Смешать кефир с мукой, добавить яйца, соду, перемешать, всыпать какао и сахар, добавить любое варенье, замесить тесто, выпечь из него два коржа, разрезать каждый вдоль на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3006,'Для смазки коржей взбить в миксере сметану и сахар. На промазанный корж выложить плоские ломтики банана, прикрыть его кремом, накрыть вторым коржом и т.д. Дать шоколадному торту постоять минимум минут 40, а лучше пару часов, чтобы он стал мягким и нежным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3007,'Хорошо перемешать с подсоленным творогом соду и масло, порциями всыпать всю муку, замесить плотное тесто. Пропустить его через решетку мясорубки со средними отверстиями, периодически срезая небольшие порции и перекладывая их на подготовленный противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3007,'Выпекать печенье «Хризантемы» примерно треть часа при температуре около 160 градусов. За 5 минут до окончания готовки выдвинуть противень и присыпать печенье сахарным песком, продолжить запекать дальше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3008,'Нашинковать тонко чеснок, огурцы и капусту, сложить послойно в подходящую емкость. На дно уложить капусту с огурцами, далее чеснок с капустой и огурцами, закончить чесноком с капустой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3008,'В кастрюльку залить воду, всыпать сахар, горошки перца, соль, положить укроп, паприку, дать закипеть. Влить в маринад масло, уксус, проварить все вместе пару минут, залить овощи, накрыть крышкой, дать постоять 5-6 часов, чтобы капуста с огурцами в маринаде хорошо промариновался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3009,'Заранее достать масло для приготовления конфет, размять его вилкой, как следует перемешать со сгущенкой, прибавить ванилин (можно коньяк) и  около 50 граммов белой стружки кокоса. Все перемешать до получения густого однородного крема, убрать его на сутки в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3009,'Достать застывшую массу, сформовать с помощью чайной ложки и закругленного ножа шарики, поместить внутрь каждой кокосовой конфеты «Рафаэлло» по орешку миндаля, обвалять в стружке кокоса. Аккуратно уложить шарики на плоское блюдо, поставить его в холодильник, чтобы они хорошо затвердели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3010,'Порезать печенку соломкой, зажарить в разогретом масле. Полукольца репчатого лука обжарить до изменения цвета, влить соевый соус, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3010,'Взболтать каждое яйцо по отдельности и обжарить с каждой стороны, порезать яичные блинчики длинной соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3010,'Объединить все ингредиенты, чуть присолить, заправить салат «Печеночная фантазия» майонезом, переложить горкой в салатницу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3011,'Нагреть, постоянно мешая в сотейнике смесь меда с содой до потемнения. Смешать с растопленным и охлажденным маслом сахар и яйца, тщательно взбить, всыпать муку (стакан), перемешать миксером, добавить остаток муки и окончательно перемешать до получения однородного теста как на оладьи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3011,'Перелить тесто в форму, дно предварительно выстелить пергаментом, готовить при 180 градусах примерно полчаса. Выпеченный корж разрезать вдоль на несколько штук. Взбить в однородную массу вареную сгущенку, сметану, мед и сливки, полученный крем поделить на две части. Когда коржи остынут промазать их кремом, сложить стопкой и поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3011,'Для верха торта приготовить крем с желатином. Замочить желатин в холодных сливках, дать разбухнуть, прогреть, помешивая до полного растворения, дать чуть остыть, смешать с оставленной частью крема. Сразу залить верх торта, заем разровнять слой лопаточкой. С помощью пленки с пузырьками «нарисовать» соты, аккуратно вдавив ее в крем. Бока торта обсыпать крошкой от обрезанных краев коржей, убрать его на треть часа для застывания сот в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3011,'Для лепки пчелок приготовить на водяной бане массу из растопленного в отдельных емкостях горького и белого шоколада, заполнить им фунтик, нарисовать темным шоколадом на пергаментной бумаге тельце пчелок, дать хорошо застыть, нарисовать белым шоколадом глазки и полоски на туловище, сделать из миндальных лепестков крылышки.  Оформленный домашний торт «Пчелка» медовый должен постоять в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3017,'Пока тесто созревает приготовить начинку. Прокрутить на мясорубке мякоть говядины, болгарский перец порезать на маленькие кубики, нарезать лук и помидоры, переложить все в комбайн, слегка подсолить, добавить остальные специи, перемешать до гомогенной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3012,'Начинать приготовление десерта удобнее с крема. Для этого в небольшую кастрюльку, желательно с толстым дном, налить молоко, вбить пару яиц, всыпать стакан сахара и пару столовых ложек муки, добавить для аромата ванильный сахар, все аккуратно взбить, нагреть на слабом огне до изменения консистенции с жидкой на густую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3012,'Пока крем еще горячий положить в него хорошее сливочное масло, перемешать, закрыть крышкой. Теперь можно приготовить основу для торта. Перемешать в глубокой миске сгущенку с яйцом, добавить погашенную уксусом соду. Всыпать небольшими порциями муку, когда станет трудно вымешивать ложкой тесто выложить на присыпанный мукой стол и довести до эластичного, но мягкого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3012,'Разделить полученный колобок на 8 частей, раскатать каждую в корж, проколоть несколько раз вилкой, испечь на разогретой сковороде при среднем нагреве. Выпекать каждый корж примерно по минуте с каждой стороны, когда все будут готовы, наложить подходящую по диаметру плоскую тарелку и подравнять края, обрезки оставить для оформления верха торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3012,'Собрать коржи в стопку, промазывая каждый горячим кремом, верх и бока тоже аккуратно покрыть кремом и присыпать крошкой от коржей, дать немного постоять и подать к столу. Торт на сковороде со сливочным кремом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3013,'Натереть яйца, отваренный в мундире картофель и маринованный огурец. Отварную холодную курицу нарезать кубиками, измельчить маринованные опята.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3013,'Салат «Грибные пенечки» с опятами послойно выложить на тарелку в следующем порядке: картофель, мясо, огурец, опята, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3013,'Между слоями сделать прослойку из майонеза, по верху «башенки» сделать кольцо из измельченного зеленого лука, заполнить его крошкой из желтка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3014,'Курицу сварить и остудить (лучше прямо в бульоне), пока варится мясо приготовить соус из смеси, взятых поровну, майонеза и сметаны. Порезать соломкой мясо, перемешать с порубленным чесноком, переложить в креманку, сдобрить соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3014,'Очистить большое зеленое яблоко кисло-сладкого вкуса, порезать соломкой, взбрызнуть лимонным соком, уложить на курицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3014,'Чернослив хорошо промыть, если он чересчур сухой, то залить горячей водой и дать немного постоять, нарезать тонкими полосками, положить его на яблочный слой, равномерно полить небольшим количеством соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3014,'Следующим слоем салата будет порезанная соломкой говядина и тоже смазанная соусом, последним же уложить мелко тертый сыр, присыпать его орешками кедра. Салат «Княжеский» с курицей и черносливом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3015,'Промыть рис, засыпать в сотейник с полутора стаканами кипятка, проварить, не перемешивая минут 10. Обжарить на сливочном масле нашинкованный мелко лук и раздавленный прессом чеснок, когда лук начнет менять цвет положить в сковороду рис, влить бульон (примерно полстакана), тушить, помешивая до исчезновения жидкости, затем влить еще полстакана и дать опять впитаться, добавить сырную стружку, хорошо перемешать, полученную массу остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3015,'Насыпать в одно блюдце молотые сухари, а в другое – муку. Сформовать влажными руками шарики из рисовой массы, обвалять в муке, затем – в сухарях, разложить шарики на плоское блюдо, дать застыть в холодильнике около часа. Достать рисовые шарики с сыром в панировке, обжарить в хорошо разогретом сливочном масле до красивой корочки, переложить на салфетки для удаления лишнего масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3016,'Нарезанный картофель в подсоленной воде отварить до мягкости, но не до полной готовности, откинуть на дуршлаг, переложить на противень, дать подсохнуть в нагретой до 150 градусах духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3016,'Нашинковать маленькие луковицы на полукольца, чуть обжарить, всыпать кусочки картофеля, приправить солью, черным перцем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3016,'Жарить картофель с луком по-лионски до готовности, аккуратно помешивая, чтобы не нарушить форму кусочков до золотисто-соломенного колера. Разложить картофель по тарелкам, присыпать зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3017,'В слегка подогретой воде с сахаром развести сухие дрожжи, чуть подсолить, влить масло, тщательно перемешать, по частям всыпать муку, хорошо перемешивая после каждого добавления. Должно получиться тесто, как для приготовления пиццы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3017,'Из кусочка теста, размером не больше яйца, раскатать тонкий большой сочень, промазать его приготовленной начинкой – это будет первый этли экмек с говядиной подготовленный к выпечке. Аналогично поступить с оставшимся тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3017,'Противень смазать маслом, разместить лепешки с некоторым расстоянием друг от друга, задвинуть его в прогретую не выше 270 градусов духовку, печь до появления на поверхности лепешек красивого слегка коричневатого колера. При подаче к столу порезать горячее блюдо на куски, подать с охлажденным айраном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3018,'Отварное мясо курицы порезать на кубики, огурцы, грибы и яйца – соломкой. Обжаренные и очищенные от пленок орехи поломать рукам на крупные куски, чтобы они добавили вкуса в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3018,'Нашинковать перья зеленого лука, все объединить, заправить салат «Чебурашка» с курицей и орехами смесью сметаны с горчицей, подсолить, поперчить, осторожно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3019,'Взбить в чаше блендера смесь молока и масла, всыпать горчицу с солью, перемешать до получения эмульсии. Добавить сок лимона, взбить в густую массу. Этот майонез хорошо хранится в холодильнике больше недели. Такой домашний майонез можно использовать как основу для приготовления других соусов с различными добавками (маринованные огурцы, грибы, маслины, зелень и проч.).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3020,'Смешать растопленное масло со специями и нашинкованным зеленым луком. Хлеб порезать на куски вдоль и поперек, но, не дорезая до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3020,'Вставить в надрезы тонкие пластинки сыра, аккуратно обернуть фольгой, поставить хлебную закуску в прогретую (до180 градусов) духовку на четверть часа. После этого времени фольгу развернуть, продолжить запекать еще минут 10.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3021,'Очистить куриные желудочки и отварить до готовности, остудить, порезать на тонкие полоски. Каждое вареное и охлажденное яйцо порезать примерно на 8 частей, морковь протереть сквозь крупную терку, мелкие луковицы нашинковать на кольца. Все аккуратно перемешать в глубокой посуде, приправить майонезом, перцем и солью, перемешать. Салат «Радость Жеглова» готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3022,'В куриные крылышки втереть соль, раздавленный прессом чеснок с соусом табаско, сложить в лоток, прикрыть крышкой, дать постоять около часа в холодном месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3022,'Потом крылышки по-мексикански можно обжарить в сковороде с разогретым маслом или поставить запекаться в духовку. Подавать блюдо к столу в горячем виде с большим количеством овощей и разнообразной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3023,'Помыть черри, вытереть, обжарить в разогретом масле. Листья салата вымыть, высушить, порвать на кусочки, сложить в миску, приправить оливковым маслом, осторожно перемешать, прибавить обжаренные черри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3023,'Легкий салат по-французки слегка подсолить, поперчить, перемешать, добавить порезанный на тонкие ломики твердый сыр, размешать еще раз и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3024,'Перемешать овсяную и гречневую муку с маслом, ванилином и сахаром, вбить яйца, влить смесь молока и воды, хорошо перемешать до получения однородной массы без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3024,'Выпечь на хорошо разогретой сковороде блины из овсяной крупы. К горячим блинам подать бананы и клубнику, порезанные на кусочки. При желании можно облить растопленным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3025,'Порезать очищенный от кожуры огурец и помидор на небольшие кусочки. Из нори сформовать урамаки с сыром Фетаки, рисом, салатом и смесью огурца с помидором.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3025,'Оформить греческие роллы с сыром Фетаки семенем кунжута, порезать на 6 одинаковых частей, переложить на плоское блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3026,'Разделить на две части, замешанное из всех ингредиентов тесто. Из каждой раскатать круг по 20 сантиметров в диаметре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3026,'Порезать круг на 8 сегментов, на широкую часть положить по  чайной ложке очень густого джема, завернуть рулетом. Для сгущения джема в него можно добавить крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3026,'Выпекать сладкие рулетики с джемом около четверти часа в духовке с температурой около 210 градусов до слегка кремового цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3033,'Когда смесь станет однородной подсыпать муку, вымесить тесто, убрать его  в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4454,'Беляши с бараниной и морковью обжарить в растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Сложить все в сковороду, обжарить с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3027,'Для основы чизкейка измельчить в крошку шоколадное печенье, смешать ее с размягченным маслом. Переложить массу в обмазанную маслом форму, сформовать бортики высотой около 5 сантиметров, убрать в холодное место. Перемешать поломанный на кусочки шоколад с парой ложек охлажденной воды и растворимым кофе в однородную массу, убрать застыть в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3027,'В высокой посуде взбить с помощью миксера сахар, ваниль, сливочный сыр, муку в однородную массу без комков, вбить яйца, взбить еще раз до гомогенного состояния, но переключив миксер на низкую скорость. Полтора стакана сливочной смеси прикрыт крышкой и убрать на холод. В оставшуюся часть положить холодную шоколадную смесь, перемешать до однородности. Залить готовый корж полученной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3027,'Запекать примерно полчаса в духовке с температурой не выше 180 градусов. Примерно за 10 минут до окончания выпечки удалить остатки сливочной смеси. Когда шоколадный слой полностью запечется вложить на него сливочный слой. После этого запекать чизкейк еще треть часа, оставить остывать на 10 минут прямо в форме. Освободить чизкейк «Кофе с молоком» на шоколадной основе из формы, дать ему полностью остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3028,'Хорошо смешать все ингредиенты, вылить на подготовленный противень, застеленный промасленным пергаментом, выпекать около 5минут  в заранее прогретой духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3028,'Смазать шоколадно-ореховой пастой Нутелла, при  желании, для большей мягкости, можно обернуть быстрый рулет в фольгу пока сервируется стол и заваривается чай.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3029,'Порезать мясо курицы на кубики, болгарский перец – соломкой, морковь измельчить на терке с крупными отверстиями, чеснок раздавить прессом, зелень нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3029,'В разогретом масле обжарить в течении 5 мнут перец с морковкой, всыпать чеснок, размешать, прогреть все вместе еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3029,'Объединить курицу с овощами, всыпать зелень, приправить майонезом, разложить по тарталеткам. Тарталетки с копченой курицей готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3030,'Заварить полуфабрикат желе, но использовать вдвое меньше воды, чем указано на упаковке, остудить поставить в морозилку на несколько минут, чтобы жидкость едва схватилась и превратилась в колыхающуюся массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3030,'К банке охлажденного молока добавить сахарную пудру, взбить смесь до увеличения объема вдвое. Полученную смесь тоненькой струйкой, не переставая взбивать, влить в чуть застывшее желе до образования пышной пены. Разлить десертный персиковый мусс в любые формочки, отправить для дальнейшего застывания на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3031,'Срезать  у небольших булочек верхушку, аккуратно удалить мякоть, большие булочки можно разрезать пополам и тоже подготовить их для фарширования.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3031,'У соленого огурца срезать шкурку, порезать вместе с ветчиной соломкой, приправить смесью  горчицы с майонезом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3031,'Смочить изнутри булочки небольшим количеством молока, смазать маслом, заполнить начинкой, присыпать зеленью, вбить в каждую по яйцу, желтки поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3031,'Переложить закусочные булочки с яичницей на противень, задвинуть его в прогретую примерно до 200 градусов духовку, запекать до готовности белка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3032,'Перемешать просеянную муку с сухим порошком какао и разрыхлителем. Всыпать к желткам половину нормы сахара, влить масло и воду, хорошо перемешать. Вторую часть сахара  смешать с белками и взбить в пену, объединить с желтками и мучной смесью, аккуратно, но тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3032,'Заполнит полученным тестом подготовленную форму. Хорошо смешать все ингредиенты для творожной массы, заполнить ею фунтик или шприц, выдавить поверх шоколадного теста в виде решетки. Выпекать до готовности около 30-40 минут при температуре не выше 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3032,'Когда пирог «Подушки» с творогом будет готов, то сразу станет ясно, почему у него такое оригинальное название. Решетка из творожной массы выдавит и приподнимет над плоскостью пирога прямоугольники шоколадной, в результате получится очень симпатичный десерт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3033,'Дать маслу постоять при комнатной температуре, когда оно станет мягким смешать с ванильным и обычным сахаром, подсолить, вбить яйца, добавить соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Положить кусочки мяса в зажарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3034,'В теплой воде или молоке растворить сахар, добавить дрожжи, прикрыть тканью, дать полчаса постоять в тепле, смешать с остальными ингредиентами, оставить тесто часа на полтора для «созревания», несколько раз за это время обмять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3034,'Поделить тесто на 10 кусочков, раскатать лепешки овальной формы, переложить на подготовленный противень, присыпать сыром, сформовать лодочки, запечь до готовности  в духовке, прогретой чуть выше 200 градусов, тесто должно стать золотистого колера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3034,'Достать из духовки противень, положить по небольшому кусочку масла в каждое хачапури, вбить, осторожно, чтобы не повредить желток, по яйцу. Поставить грузинские хачапури с яйцом по-аджарски запекать еще минут на 5, белок схватится, а желток должен остаться жидким, подать к столу горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3035,'Поместить белки в чашу блендера, установить среднюю скорость, взбить до появления устойчивых, но мягких пиков. Всыпать порциями сахар, скорость взбивания увеличить, продолжать процесс до тех пор, пока блестящие пики не станут «твердыми».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3035,'К готовой воздушной массе прибавить шоколад, размешать, переложить в формочки, поместить на полминуты в микроволновку. Дать десерту в микроволновке остыть и вынуть из формочек, подавать можно с любым сладким соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3036,'Подготовить плоды перца: помыть, порезать на две части, удалить сердцевину и все семена. Лук мелко нашинковать, морковь протереть на крупной терке, обжарить все на разогретом масле. Пожаренные овощи объединить с мясным фаршем, приправить смесью «прованские травы» и чесноком, тщательно перемешать, заполнить половинки перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3036,'Переложить перцы в сотейник, прикрыть фарш в каждом ломтиками помидоров и смазать сметаной или майонезом, залить стаканом крутого кипятка, убрать в духовку с температурой в 200 градусов. Достать перцы с начинкой из говяжьего фарша через полчаса, присыпать сыром, продолжить запекать еще треть часа, подавать лучше с салатом из свежих овощей, но можно и с любым другим гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3037,'Кусочки сухой клубники запарить кипятком, хлопья на 40 минут залить кефиром, перемешать с сухофруктами. Противень выстелить пергаментом, ложкой выложить горки полученной массы, выпекать диетическое овсяное печенье с клубникой полчаса при температуре около 200 градусов, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3038,'С помощью миксера взбить желтки с добавлением сахара. Изюм смешать с мягким маслом, манкой и цедрой лимона, соединить с желтками, перемешать, добавить протертый творог, хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3038,'Белки с оставшейся порцией сахара (добавлять по частям) взбить до крепкой пены, осторожно перемешивая, объединить с творогом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3038,'Глубокую форму смазать маргарином или маслом, притрусить стенки и бока манкой, лишнюю высыпать, заполнить ее тестом, смазать верх сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3038,'Поставить в творожную запеканку с изюмом в духовку с температурой 160 градусов, выпекать пока верх запеканки не станет радовать глаз аппетитной румяной корочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3039,'Готовое слоеное тесто достать из морозилки, дать полежать, за это время приготовить из сахара, части молока (примерно 4 ст.л.) и пудинга крем. В оставшееся молоко всыпать сахар, добавить желтки, взбить в однородную смесь, соединить с пудинговой смесью. Полученную массу нагреть, помешивая до загустения, но не более минуты, всыпать кокос, тщательно перемешать, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3039,'Тесто раскатать в квадрат, разрезать его на 4 полосы, а потом каждую разделить вдоль на 4 части. Кусочки переложить на противень, выстланный бумагой для выпечки, разболтать желток и смазать полоски, а потом проколоть в нескольких местах вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3039,'Запечь их до соломенного цвета в духовке с температурой слегка выше 200 градусов, оставить пару-тройку штук, растереть в крошку, использовать для обсыпки готовых  пирожных из слоеного теста. Квадратики расслоить на две части, прослоить кремом середину и верх, оформить верх крошкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3040,'Для начинки всю зелень мелко измельчить, чеснок раздавить прессом, сыр измельчить вилкой, все перемешать, приправить перцем, добавить яйцо и сметану, смешать в однородную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3872,'Положить рулет в сотейник, залить водой, добавить петрушку, морковь и лук, дать закипеть, убавить огонь до минимума и варить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3040,'Промазать форму маслом, поставить кусочки вертикально, но не вплотную, смазать их разболтанным со сливками и маслом желтком. Выпекать порционный закусочный пирог около получаса при  температуре духовки в 170 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3041,'Включить прогреваться духовку до 180 градусов. Отделить 5 желтков, всыпать сахар, растереть, чтобы смесь стала белого цвета, аккуратно смешать с крепкой пеной из белков. Просеять прямо в полученную массу муку и разрыхлитель, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3041,'Форму (желательно разъемную) смазать маслом или жиром, заполнить тестом, печь около получаса, полностью остудить. Дать разбухнуть желатину, у оставшихся яиц отделить желтки, размешать с сахарной пудрой, поместить на водяную баню, взбить, добавить желатин и маскарпоне, хорошо перемешать. Вмешать в крем пену из взбитых с ванильным сахаром белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3041,'Остуженную основу разрезать на три коржа, пропитать их кофе с добавлением ликера. Форму сбрызнуть холодной водой, застлать пленкой, собрать из коржей десерт, промазывая каждый кремом (верх не смазывать), поместить часа на 4 в холодильник. Достать форму с домашним тортом «Тирамису», прикрыть плоской тарелкой, осторожно перевернуть, присыпать верх порошком какао.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3042,'Порезать на кубики помидор (без семян), лук, картофель и огурец. Яйца сварить, охладить и порубить, мелко порезать рыбу, креветки оставить целыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3042,'Застелить пленкой подходящую по размеру форму. Выложить ингредиенты (каждый смазать майонезом и слегка присолить) в следующем порядке: креветки, огурец, яйца, помидор, лук, рыба, картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3042,'Закрыть краями пленки верхний слой салата, поместить форму на час в холодильник, достать, аккуратно прикрыв плоским блюдом, перевернуть, удалить осторожно пленку. Слоеный салат «Фантазия» с красной рыбой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3043,'Засыпать в кастрюлю вишню и сахар, поставить на плиту, дать желатину набухнуть в 50 г воды четверть часа, масло растереть с мукой, всыпать сахар, добавить протертый творог, перемешать, убрать на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3043,'Добавить желатин в кипящую вишню, очень тщательно перемешать, дать хорошо остыть. Заполнить тестом форму, поставить на треть часа в духовку, заранее прогретую до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3043,'Выложить на готовый корж вишневую начинку без жидкости, разровнять, убрать творожный чизкейк с вишней в холодильник, когда сироп начнет схватываться, залить верх десерта и дать до конца застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3044,'Картофель надрезать (не до конца) в форме гармошки. Смешать масло, раздавленный чеснок, перец, подсолить, хорошо смазать этим составом куски курицы и клубни картофеля, так, чтобы он попал и в надрезы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3044,'Заложить все в рукав, уложить его на противень, отправить в духовку, через полтора часа куриные окорочка, запеченные в рукаве с картофелем будут готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3045,'Маринованные шампиньоны разрезать на четвертинки, желток яиц порубить, белок порезать маленькими кубиками вместе с мясом и огурцами, перемешать, всыпать тертый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3045,'Приправить мясной салат «Сытый гость» майонезом, аккуратно смешать, переложить в салатник, оформить верх раздробленными орехами и сырной стружкой, дать немного постоять и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3046,'Надрезать крестообразно каждую помидорку, перемешать порубленную зелень, с соевым соусом и специями, заполнить смесью разрезы. Переложить плоды в рукав для запекания, завязать, отправить ночевать в холодильник. Утром малосольные помидоры черри можно будет подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3047,'Порезать булочки на две части, луковицу мелко нашинковать, помидоры и болгарский перец порезать на мелкие кубики, сосиски – на кусочки, зелень порубить, все перемешать, сыр протереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3047,'Промазать половинки булочек маслом, а потом кетчупом, прикрыть слоем начинки, присыпать сыром. Разложить булочки на противень, отправить в уже прогретую духовку Пицца на булочках будет готова примерно минут через 7-10 минут, когда сыр покроется румянцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3054,'Хорошо перемешать все сыпучие ингредиенты в однородную смесь, используя миксер, соединить с жидкими и еще раз тщательно перемешать не менее трех минут, убрать кастрюльку в тепло, через полтора часа проконтролировать созревание теста, вымешать ложкой, дать постоять еще полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3048,'Залить теплой водой дрожжи, всыпать соль, сахар, влить масло, подсыпать постепенно с перемешиванием просеянную муку, должно получится мягкое тесто. Переложить его в миску, прикрыть х/б тканью, дать постоять в тепле около получаса или час. Из отварной курятины и обжаренных с луком грибов приготовить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3048,'Созревшее тесто раскатать в пласт, вырезать, подходящей по диаметру формочкой, кружки, положить по ложке начинки, края защипать. Обжарить жареные пирожки с куриной грудкой в хорошо прогретом масле до корочки золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3049,'Включить для прогрева чуть ниже 200 градусов духовку, подготовить противень: выстлать пергаментом, промазать маслом. Отделить у яиц белки, взбить до устойчивой густой пены с сахаром (добавлять постепенно) и ванилью, взбивать продолжить и влить растопленное масло, добавить порциями просеянную муку, перемешать до кремообразного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3049,'Зачерпнуть чайной ложкой тесто и выложить с большими промежутками на противень, но не больше 4 ложек, кругом распределить равномерно тонким слоем тесто по поверхности. Заполнить кондитерский шприц (вместо него можно использовать и чайную ложку) растопленным шоколадом и нанести на корж разводы, отправить на 5 минут в духовку, выпекать до потемнения краев.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3049,'Осторожно поддеть кружки ножом и свернуть в трубочки, использовать все тесто, шоколад периодически необходимо будет подогревать. Готовый десерт сложить на блюдо и полить шоколадом. Хрустящие трубочки с шоколадом к чаю готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3050,'Перебрать и промыть изюм, залить кипятком, дать постоять около часа, воду слить, сухофрукты хорошо обсушить, также поступить и с маком. Сметану растереть с яйцом и сахаром, всыпать смесь муки с содой, хорошо взбить, добавить изюм, испечь при температуре в 180 градусов до готовности. По аналогии выпечь еще два коржа: один с маком, а другой с орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3050,'Из желтков, молока и сахара взбить основание для крема, проварить его минут 6-7 при непрерывном помешивании пока состав не загустеет, остудить, добавить взбитое до пышного состояния масло, перемешать, поставить готовый крем в прохладное место или холодильник. Собрать  коржи оригинального трехслойного торта в стопку, промазывая каждый кремом, верх оформить крупнодроблеными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3051,'Картофель отварить до готовности прямо в кожуре, обдать холодной водой, удалить кожуру, подавить до состояния пюре, подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3051,'Порубить зелень петрушки и чеснок, измельчить лимонную цедру и перья зеленого лука, сдобрить оливковым маслом, перемешать с пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3051,'Слепить из полученной массы небольшие шарики, сплюснуть, помести на треть часа в холодильник, обжарить картофельные оладушки с зеленым луком в сильно разогретом масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3052,'Отварить креветки в чуть подсоленной воде (3 минуты), дать остыть, снять панцирь, а в оставшемся бульоне сварить колечки кальмаров, дать остыть. Порезать палочки и яйца на кубики, все перемешать с майонезом, добавить красную икру, заправить по вкусу перцем и солью, убрать  на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3052,'У буханки хлеба срезать верхушку, но не совсем, осторожно вырезать мякиш и запечь при 230-240 градусах около 5 минут, дать «сундучку» остыть. Распустить плавленый сыр на водяной бане или микроволновке, смазать со всех сторон хлеб, заняться оформлением  салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3052,'На расплавленный сыр приклеить зелень петрушки и колечки болгарского перца, подрезанную верхушку буханки подпереть зубочистками, т.е. приоткрыть сундучок, дополнить украшение красной икрой и маленькими целыми осьминожками, заполнить хлеб салатом. Праздничный салат «Сундучок с сокровищами» готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3053,'Обжарить очень мелкие кубики лука до прозрачности, добавить порубленный чеснок жарить еще около минуты все вместе, пожить порезанную на небольшие кусочки курицу, обжарить до побеления минуты 3-4.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3053,'Переложить все в кастрюлю с бульоном, добавить высушенные травы, подсолить, положить томаты, сок от них тоже добавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3053,'Дать супу закипеть, проварить полчаса при слабом кипении, всыпать мелко нарезанную фасоль, варить  томатный суп с куриным филе и зеленой фасолью еще 10 минут, снять с плиты, разлить по тарелкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3872,'Порезать очищенные от кожуры яблоки без сердцевины на дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3054,'Смазать сковороду маслом или кусочком сала, насаженным на вилку, вылить по центру дна порцию теста, наклоном из стороны в сторону придать округлую форму. После появления дырочек и исчезновения влажного блеска на поверхности выпекать еще пару минут  при среднем нагреве, чтобы марокканские дрожжевые панкейки Beghrir успели подняться и при этом снизу не сгорели. Подавать выпечку лучше горячей с медом и растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3055,'Тщательно перемешать сливки со сметаной, перелить в кастрюлю, поставить в емкость с дробленым льдом или сильно охлажденной водой, взбить венчиком до густой красивой пены.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3055,'Всыпать, не прекращая процесса взбивания, ванильный сахар и сахарную пудру, перемешать густой крем для домашнего торта до однородности, поместить на пару-тройку часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3056,'Перемолоть печенье в крошку, перемешать с растопленным маслом до состояния маслянистой крошки. Полученную массу уложить на дно формы, прокатать с усилием маленьким стаканчиком или воспользоваться  для утрамбовки ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3056,'Растереть или разбить блендером творог до пастообразного состояния, чуть подсолить, всыпать сахар, добавить ванильный сахар, взбить в однородную массу, соединить ее с цедрой от половинки лимона и свежевыжатым из него соком, перемешать. Прибавить в смесь пару яиц (по одному), перемешать, используя венчик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3056,'Заполнить этим кремом форму с основой, разровнять начинку лопаточкой. Установить форму в противень с высокими бортиками, заполненный горячей водой. Поставить  на час в духовку с температурой  чуть выше 150 градусов, готовый творожный чизкейк на песочной основе остудить, поставить минимум на 4 часа в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3057,'Нарезать сыр и ветчину на кусочки, а лаваш на квадраты. Завернуть в лаваш по кусочку каждой начинки, на сковороде подрумянить конвертики из лаваша с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3058,'Разбить в миску яйца, всыпать к ним сахар, растереть, добавить полбанки сгущенного молока, ввести погашенную соду, а в конце по частям всыпать муку, тщательным образом перемешать, разделить на две порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3058,'Выпекать коржи при 180 градусах. Пока они выпекаются оставшееся сгущенное молоко взбить вместе с маслом, полученным кремом перемазать готовые и слегка остуженные коржи, верх быстрого пирога на сгущенке оформить обжаренными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3059,'Всыпать в масло половину муки, растереть, влить молоко, добавить сметану с содой, перемешать, подсыпать остаток муки, вымесить тесто, обернуть пленкой, положить на полчаса в холодильник, за это время приготовить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3059,'Включить для прогрева до 180 градусов духовку. Порезать на кубики курицу, сладкий перец и помидоры, лук поджарить, всыпать горошек, слегка подсолить, добавить перчик, перемешать. Для заливки открытого пирога с куриной грудкой и овощами приготовить смесь сметаны, муки, яйца, сдобрить перцем, присолить, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3059,'Распределить тесто по дну формы, сформовать бортики, заполнить начинкой, залить яичной смесью, поставить минут на 50 в уже прогретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3060,'Нашпиговать подготовленный кусок мяса небольшими зубчиками чеснока, смешать с небольшим количеством воды приправы, равномерно втереть в мясо, убрать его на три часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3060,'Достать кусок, обернуть фольгой, поставить в духовой шкаф, минут за 10 до окончания приготовления аккуратно, чтобы не обжечься, приоткрыть фольгу и дать свинине, запеченной с корицей, обзавестись аппетитным «загаром». Мясо считается готовым, когда при проколе куска выступает прозрачная жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3061,'Подготовить бедрышки, сыр порезать пластинками, аккуратно вложить под кожу каждого кусочка. Переложить мясо в форму для запекания, слегка присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3061,'Смазать кусочки майонезом с добавлением мелко порубленной зеленью и раздавленным прессом чесноком, поставить форму в духовку с температурой чуть ниже 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3061,'Куриные бедрышки с ченоком, запеченные с сыром будут готовы примерно минут через 45. К мясу подать салат из сезонных овощей, рис или пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3117,'Куриную грудку порезать кубиками, нашинковать мелко лук, положить на пару минут в кипяток. Измельчить яйца, порезать ананас, добавить кукурузу, заправить салат майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3062,'Взять половину количества сахара, взбить с белками, а другую половину – с желтками. Влить к желткам молоко, добавить соду, изюм, прокрученный через мясорубку, все перемешать на малых оборотах блендера, всыпать муку, еще раз перемешать, а в конце аккуратно ввести в смесь взбитые белки осторожно (снизу вверх) все смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3062,'Выстелить форму пергаментом, заполнить тестом, выпекать корж для пирожного около получаса в духовке с температурой 180 градусов, разрезать остывший корж вдоль на две части. Для прослойки пирожных «Белочка» с изюмом взбить сгущенное молоко и сливки, промазать коржи, присыпать верх ореховой крошкой, поставить в холодильник, охлажденный десерт порезать на отдельные пирожные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3063,'У кабачков снять шкурку, порезать вместе с помидорами кружками, лук нашинковать тонкими кольцами. Сбрызнуть форму маслом, разложить в один слой кабачки, чуть присолить, прикрыть кольцами лука и помидоров, еще раз присолить и поперчить, присыпать порубленным  свежим или сухим базиликом, а сверху стружкой пармезана и поместить в духовку. Подавать к столу ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3064,'Промыть и залить горячей водой грибы на полчаса, размягченные кусочки нарезать более мелко. Закипятить примерно три литра подсоленной воды, положить грибы, проварить полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3064,'Нашинковать порей кольцами, репчатый лук – мелкими кубиками. Морковку протереть на терке со средними отверстиями, картошку порезать брусочками и положить к грибам, проварить минут 10.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3064,'Добавить в сырный суп с картофелем и белыми грибами морковь и лук. Перед окончанием варки положить сыр, приправить по вкусу перчиком, подсолить, размешать, отключить нагрев, дать немного постоять под крышкой и разлить по тарелкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3065,'Кусок говядины подготовить и нарезать соломкой, лук мелко нашинковать, присыпать сахаром, перемешать, обжарить в разогретом масле, помешивая минут 15, до появления у лука коричневого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3065,'Раздавить зубки чеснока широким ножом, измельчить, присыпать солью, перемешать и высыпать к луку, размешать, обжарить все вместе пару-тройку минут. Добавить мясо, перемешать, прикрыть крышкой, тушить примерно 10 минут пока оно не даст сок и не посветлеет, положить кетчуп и аджику, перемешать, тушить еще столько же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3065,'Переложить все в кастрюлю, добавить кубики картофеля, влить горячую воду, чтобы она прикрыла содержимое примерно на 2 сантиметра, приправить специями, тушить 10 минут пока картофель не начнет размягчаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3065,'Отжать слегка квашеную капусту, нарезать, переложить в кастрюлю, томить суп-гуляш по–тирольски с говядиной при слабом нагреве не менее двух часов, влить сок половинки лимона, если надо, то еще подсолить, дать настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3066,'В сотейник положить полпачки масла, добавить мед, растопить на медленном огне. Пока идет процесс взбить миксером стакан сахара и яйца. Добавить в растопленную массу соду, когда она слегка остынет, смешать ее с взбитыми яйцами, всыпать стакан муки, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3066,'Переложить все в широкую миску, всыпать остаток муки, вымесить до теста, похожего на размягченный пластилин, раскатать 5 коржей, запечь каждый до соломенного цвета. Для крема стакан сахара хорошо перемешать в миксере со сметаной, прибавить полпачки мягкого масла, взбить до однородности, добавить кусочки чернослива и дробленые орехи, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3066,'Пока пекутся наши коржи, подготовим крем. Для этого взбиваем сметану со стаканом сахара, добавляем 100 грамм размягченного сливочного масла и продолжаем взбивать. Когда масса станет однородной, добавляем в нее измельченные чернослив и грецкие орехи. Дать коржам остыть, нанести на каждый крем, разровнять, верх особого медового торта с черносливом тоже промазать и оформить мелкими кусочками грецкого ореха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3067,'В стакане миксера взбить сахар и яйца, чуть присолить, добавить молоко, всыпать муку, хорошо перемешать и влить масло, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3067,'Если тесто для получится излишне густоватым, то можно долить немного молока. Разогреть сковороду, поджарить с двух сторон, если ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3075,'Перемешать кефир и масло, чуть подогреть, подсолить, добавить сахар. В муку добавить сухие дрожжи, просеять, влить небольшими порциями кефирную смесь, вымесить тесто, прикрыть и убрать в тепло минут на 30.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3068,'Мясо обмыть, обсушить, порезать на крупные, но тоненькие куски, аккуратно отбить, сложить в объемную миску, присыпать мелко порубленным чесноком, смесью соли и перца, добавить другие любимые специи, дать постоять треть часа, включить прогреваться духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3068,'Уложить мясо и лук на смазанный противень, присыпать молотым черным перцем, промазать майонезом, прикрыть картофелем, опять смазать майонезом, присолить, присыпать натертым сыром, промазать майонезом, задвинуть его в прогретую духовку. Ароматный и вкусный картофель со свининой по-французски будет готов примерно через час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3069,'Засыпать в кастрюлю с толстым дном стакан сахара, влить две столовые ложки холодной воды, прогреть на среднем огне до получения темно золотистой, даже чуть коричневатой карамели, влить кипящие сливки (стакан), перемешать карамельную массу, процедить и дать остыть. Включить прогреться духовку до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3069,'Комбайном взбить в течение одной минуты до состояния мелкой крошки кубики замороженного масла и муку. Вбить яйцо, добавить по ложечке комнатной температуры воду. Как только во время взбивания образуется из массы шар, выключить миксер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3069,'Переложить полученное тесто на стол, разделить его на две части. Каждую раскатать в круглый 3-5 мм пласт. Подготовить начинку из порезанных на тонкие ломтики яблок, присыпанных сахаром (выделившийся сок слить).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3069,'Уложить один круг теста в форму, поверх разложить яблочную начинку, полить карамелью, добавить еще слой яблок, полить карамелью, прикрыть слоем яблок. Накрыть начинку кругом теста, тщательно защипать, сделать с помощью вилки красивый фигурный край.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3069,'Сделать по верху закрытого яблочного пирога с карамелью пять разрезов для выхода пара в форме яблока, смазать молоком, присыпать сахаром, отправить пирог примерно на 40 минут в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3070,'Тонкими ломтиками бекона выложить чашу мультиварки, обмазанную сливочным маслом. Заполнить перченным и подсоленным фаршем, смешанным с яйцом. Закрыть мясной слой тертым сырым и отжатым от сока картофелем, перемешанным с яйцом, майонезом и тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3070,'Порезать на пластинки шампиньоны, обжарить с кубиками лука на сливочном масле, выложить на слой тертого картофеля, накрыть все загнутыми от стенок ломтиками бекона. Поставить готовить трехслойный мясной пирог без муки в мультиварке на час в режиме «выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3071,'Сварить рис до готовности, мелко нашинкованный лук обжарить до изменения цвета. Взбить яйца вилкой, смешать с отварным рисом, золотистым луком, добавить карри, муку, сыр, перец и соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3071,'Хорошо разогреть на сковороде масло, сформовать из полученной массы небольшие сырно-рисовые котлетки, обвалять в измельченных сухарях, зажарить до корочки с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3072,'В чашу блендера вбить яйца, всыпать муку, перемешать, долить молоко, перемешать, подсолить, всыпать сахар, добавить масло. Все еще раз перемешать, дать тесту постоять 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3072,'Для начинки порезать на одинаковые кусочки огурец, сыр и колбасу. Обжарить блинчики с двух сторон, положить начинку, свернуть каждый блинчик в трубочку, разрезать вдоль на несколько кусочков. Рулетики из блинов на завтрак готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3073,'Разрезать лимон и два апельсина на 4 части, у имбиря соскоблить верхнюю корочку, разрезать на две части. В оставшийся апельсин, равномерно распределив по всей поверхности, воткнуть все гвоздички.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3073,'Вылить вино в кастрюлю, положить нарезку фруктов, целый апельсин, имбирь, корицу в палочках и изюм, добавить сахар, поставить на плиту на слабый огонь, помешивая, довести примерно до 70-80 градусов, но кипеть не давать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3073,'При появлении пара и исчезновении с поверхности глинтвейна с имбирем, гвоздикой и изюмом пленки светлого цвета убрать вино с плиты, накрыть крышкой, дать постоять треть часа и разлить по кружкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3074,'Сварить курицу, дать остыть, порезать на небольшие кубики, также порезать картофель и ветчину. Лук тонко нашинковать и тоже нарезать кубиками, яйца порубить, оливки разрезать вдоль на несколько частей. Перемешать все ингредиенты салата «Венеция», подсолить, приправить майонезом, желательно дать немного постоять и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3075,'За это время приготовить сладкую, мясную или какую-нибудь другую начинку. Слепить пирожки из воздушного теста, уложить их на противень, выстланный промасленной бумагой швом вверх, дать постоять минут 10. Разболтать яйцо, смазать верхушки пирожков, поставить в прогретую до 200 градусов духовку, выпекать до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3076,'Для приготовления коржа в устойчивую пену взбить стакан сахара с белками, всыпать смесь муки и какао, взбить до исчезновения комков. Вылить полученную массу в смазанную форму, дать запечься в духовке с температурой 200 градусов. Примерно через треть часа корж поднимется и станет румяным, достать его и остудить, разрезать вдоль на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3076,'Приготовить из 7желтков, перемешанных с сахаром с добавлением молока и нагретых при постоянном перемешивании  густой крем. Как только он начнет булькать сразу снять с плиты и дать остыть, добавить мягкое сливочное масло, хорошо взбить в пышную массу желтого цвета и промазать коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3076,'Сварить из сахара с добавлением какао и молока помадку, дать массе остыть, добавить масло и взбить до однородности. Вылить ее на верх торта «Птичье молоко», смазать также и бока десерта, поставить его в холодное место, чтобы слегка застыл.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3077,'Перемешать сахар с солью, добавить кусочки масла, перемешать до состояния пышной массы, вбить по одному яйца, взбивать не переставать. Смешать муку с картофельным крахмалом и разрыхлителем перемешать с яично-масляной смесью и молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3077,'Круглую форму выстелить пергаментом, промазать маслом, заполнить тестом, выпекать  идеальный воздушный бисквит при температуре  духовки в 180 градусов около получаса, вынуть, дать чуть остыть, порезать вдоль на коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3078,'Каждое филе разрезать на две более тонкие части, чуть отбить, промазать раздавленным чесноком и солью с перцем, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3078,'Переложить мясо в форму, на него уложить размороженные креветки и кубики помидоров, прикрыть майонезом, присыпать свежее смолотым черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3078,'Поставить в прогретую до 220 градусов духовку, через треть часа мясо «Аппетитное» с креветками можно будет подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3079,'Перемешать хорошо охлажденный и натертый на терке маргарин с яйцом, сахаром и порошком какао, добавить муку с содой, вымесить упругое тесто, разрезать его на три части. Смазать форму маслом и протереть в нее две части,  а третью на полчаса положить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3079,'Для начинки желтки смешать с протертым творогом, ванилином, сахаром и крахмалом в конце прибавить в смесь белки, хорошо перемешать. Залить начинкой стружку из теста в форме, сверху прикрыть стружкой из замороженной части теста, поставить в духовку. Готовность простого домашнего пирога с творогом периодически проверять зубочисткой, если она без следов творога, то выпечка готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3080,'Взбить с майонезом и небольшим количеством воды яйца, сдобрит солью и перцем, из смеси выпечь под крышкой омлет. Натереть охлажденный плавленый сырок, перемешать с майонезом, рубленой зеленью и раздавленным прессом чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3080,'Смазать полученной начинкой слегка охлажденный омлет, свернуть его в трубочку, срезать края, убрать рулет из омлета с сыром примерно на час в холодильник, достать порезать на ломти и подать к столу, как закуску или сделать с ними бутерброды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3081,'Охлажденные белки взбить с добавлением сахара (всыпать небольшими порциями) до сохраняющих форму пиков. Застелить противень пергаментом, массу выложить ложкой на расстоянии друг от друга, выпекать воздушное безе начинать в холодной духовке, постепенно доведя температуру до 100 градусов. Десерт будет готов примерно через час-полтора. Во время приготовления духовку открывать нельзя.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3082,'Порезать филе на кусочки, сложить в блендер вместе с зубчиками чеснока, измельчить до получения однородного фарша, добавить сливки, продолжить взбивание, по одному добавить белки яиц. В конце взбивания влить для окраски сок свеклы, приправить специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3089,'Вскипятить воду, залить на четверть часа грибы, слить воду, сполоснуть их и нарезать кусочками, небольшие кубики лука обжарить на масле. Пока готовится лук очистить и порезать на небольшие кусочки картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Влить вино, готовить до его испарения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3082,'Переложить фарш на расстеленную фольгу, свернуть в трубочку, края завернуть, как у конфеты. Упаковать в пакет, а затем еще в один, хорошо завязать. Варить домашнюю колбасу из куриного филе при слабом нагреве примерно около получаса, зависит все от толщины будущего батона, дать остыть, не раскрывая фольги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3083,'Включить и прогреть чуть выше 150 градусов духовку, смазать глубокую прямоугольную форму (подойдет для приготовления хлеба) маслом. Присыпать дно орехами и коричневым сахаром, выложить ровным слоем масло, поставить на 8 минут в прогретую духовку, расплавленную массу перемешать, выложить на нее кружки бананов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3083,'Перемешать в однородную смесь все сухие ингредиенты, объединить с другими ингредиентами, все вместе взбить, полученной массой залить бананы, поставить на час выпекаться. Готовый остудить прямо в форме примерно треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3083,'Все ингредиенты для глазури положить в небольшой сотейник с толстым дном, поставить на плиту, дать закипеть, варить пару минут при непрерывном помешивании до получения однородной массы. Дать глазури слегка остыть (примерно около минуты), залить верх пирога. Пирог с бананом в карамельной глазури готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3084,'Разморозить специальные палочки, они чуть больше обычных крабовых, обычно на упаковке указывают для чего они предназначены. Сварить яйца, охладить, измельчить на средней терке, зелень порубить, замороженную семгу порезать на тонкие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3084,'Палочки полностью раскрутить, промазать небольшим количеством майонеза, с краев оставить по 2 см не смазанной части, присыпать измельченным яйцом, зеленью, положить пару пластинок рыбы, палочки опять закрутить с небольшим усилием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3084,'Разрезать закусочные роллы из крабовых палочек на три части, уложить срезом вниз на плоское блюдо, оформить каждый небольшим количеством красной икры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3085,'Перемешать все ингредиент для теста, оно должно получиться густым и не липнущим к рукам. Для начинки приготовить не слишком густой (для сочности чебуреков) фарш подсолить его и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3085,'Стол притрусить мукой, раскатать тесто толщиной как для приготовления пельменей. Разложить начинку по половинке раскатанного сочня, прикрыть второй половинкой, прокатать ребром тарелки. Обжарить сочные чебуреки с фаршем в сильно разогретом масле с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3086,'Подготовить водяную баню, в кастрюлю вбить яйца, всыпать сахар, добавить мед и соду, тщательно растереть, поставить на баню, всыпать полный стакан муки, размешать до образования плотного теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3086,'Разрезать его на 8 кусочков, раскатать в тонкие коржи, проколоть их в нескольких местах вилкой. Выпекать на противне, выстланном пергаментом по паре минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3086,'Из растворенного в кипятке сахара, какао с добавлением сливочного масла, взбить крем. Промазать им коржи торта «Дамский каприз» медового, собрать в стопку, смазать бока и верх изделия, присыпать крошкой от выравнивания коржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3087,'Курицу помыть, порубить на куски, подготовит мультиварку. Налить в чашу масло, сложить мясо, выставить режим «Выпечка» или «Жарка» (зависит от модели мультиварки) и время 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3087,'Через четверть часа приготовления, открыть крышку, перевернуть кусочки птицы, добавить минут через 10-15 после этого полукольца лука, перемешать, готовить до окончания выбранной программы «Выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3087,'Добавить к блюду соль, специи, сметану, лаврушку, размешать, готовить полчаса в режиме «Тушение» или «Молочная каша». Посыпать минуты за три до окончания ароматную курицу рубленым укропом. Аппетитная курица в сметане в мультиварке готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3088,'Натереть сыр, обмыть и обсушить грибы, мелко порезать вместе с луком, обжарить, сдобрить перцем и солью, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3088,'На ломти хлеба или половинки булочек уложить грибную смесь, прикрыть кружками огурца и помидора, присыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3088,'Поместить в духовой шкаф или микроволновую печь до образования сырной корочки и сразу подать к столу. Горячие бутерброды с овощами и грибами готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3194,'Бананы без кожуры нарезать на кусочки любой формы и размера. Сбрызнуть их соком лайма. Яйцо, творог, йогурт и мед выложить в блендер и смешать до получения воздушной однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3089,'Перемешать фарш со специями, сделать шарики, разложить вместе с картофелем, грибами и луком послойно по горшочкам, сверху присыпать протертым сыром. Разболтать сметану с небольшим количеством воды, залить, прикрыть горшочки крышками, разместить в прогретой до 200 градусов духовке минут на 40. Картофель с фрикадельками и грибами в горшочках готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3090,'Потушить отварные и порезанные грибы вместе с капустой до ее размягчения, переложить в кастрюлю, добавить воды, поставить на плиту. Обжарить мелко нашинкованный лук с добавлением томатной пасты на подсолнечном масле, протушить все вместе минут 7.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3090,'Огурцы мелко порезать и когда солянка станет закипать, всыпать вместе с луком в кастрюлю, через несколько минут положить перец, нашинкованные перья зеленого лука и лавровый лист, проварить под крышкой при слабом нагревании еще около 10 минут. Дать домашней грибной солянке немного настояться, подать к столу со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3091,'Морковку вымыть, почистить, протереть на терке для приготовления корейской моркови. Колбасу тонко порезать соломкой, лук помыть и нашинковать, переложить все в салатник, добавить кукурузу, приправить салат «Аврора» с копченой колбасой майонезом, осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3092,'Отделить желтки, переложить в чашу блендера, всыпать сахар, взбить все вместе, добавить 10% сливки и ванильный сахар, перемешать, поставить варить при малом нагреве и постоянном помешивании практически до кипения (не кипятить!), убрать с плиты, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3092,'Хорошо охлажденные жирные сливки отдельно взбить до густой воздушной пены, влить по частям, постоянно перемешивая, остывшую желтковую смесь. Переложить полученную массу в лоток, убрать часа на 3 в холодильник. Достать лоток с домашним мороженым «Пломбир из детства» и переложить в морозильник на пару часов, хорошо перемешать, оставить мороженое в морозильной камере ночевать до окончательного застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3093,'Луковицу нашинковать на кубики, обжарить вместе с фаршем и пропущенными через пресс зубками чеснока. Открыть банку томатов, порезать, добавить в сковороду к мясу, заправить базиликом, томатной пастой, влить вино, протушить соус «Болоньезе» из говяжьего фарша еще треть часа, но можно и чуть побольше, тогда соус получится еще ароматнее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3094,'Печень зачистить и промыть, положить в подсоленную кипящую воду, сварить до готовности, вынуть, дать остыть, порезать на небольшие кубики, измельчить на такие же кубики яйца, перец и помидоры, маслины без косточек разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3094,'Заправить салат из куриной печени, помидоров и перца майонезом, аккуратно перемешать, можно добавить черный перец или другие любимые приправы. Дать салату настояться и подать к столу, присыпав обжаренным семенем кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3095,'Если делать круглой формы торт, то листик обрезаем, придавая круглую форму. Если листы не используются, то слой риса сразу выкладываем на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3095,'Выложить на плоское блюдо слой риса, смазать творожным сыром, прикрыть слоем рыбы. Сверху уложить тоненькие пластинки огурца или авокадо, можно заменить болгарским перцем, теперь повторить рис-сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3095,'А теперь дело дошло до креветок, сдобренных вассаби и прикрытых листом нори, снова – рис, рыба (креветки). Края праздничного суши–торта с креветками прикрыть листам и нори, порезанными на пластинки, либо тоненькими пластинками огурца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3096,'Протереть картофель на крупной терке, чеснок раздавить прессом, мясо очень мелко порезать. Отварные желтки протереть на мелкой терке, а в другую тарелку протереть белки. Часть сыра (примерно половину) измельчить на крупной терке, другую часть – на мелкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3096,'Хорошо перемешать кубики из куриного филе, горошек, желтки, крупно потертый сыр, чеснок, картофель, приправить достаточным количеством майонеза, выложить на блюдо в форме тела ежика, сделать из маслин, разрезанных вдоль на дольки «иголочки».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3096,'Из горошинок сделать ежику глазки и носик. Салат «Ежик» с куриным филе оформить зеленью петрушки и небольшими грибочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3111,'Отварить до готовности язык, обдать холодной водой, удалить пленку, дать немного порезать соломкой. Картофель протереть на терке с крупными отверстиями, белки и желтки яиц натереть в отдельные емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3097,'Залить желатин теплой водой, жирный творог перетереть с сахаром. Шоколад поломать на мелкие кусочки, на водяной бане растопить, смешать с маслом. Разбухший желатин на водяной бане нагреть до полного растворения, влить к шоколаду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3097,'Полученную массу объединить с творогом и как следует перемешать в однородную массу. Выложить в виде прямоугольника на присыпанный кокосовой стружкой пергамент, по центру положить ягоды, по бокам оставить место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3097,'Поднять осторожно края пергамента так, чтобы ягоды прикрылись со всех сторон творожной массой. Очень аккуратно (поскольку масса достаточно жидкая) завернуть все фольгой и поставить на 3 часа в холодильник. Перед подачей охлажденный творожный десерт «Белоснежка» порезать на кружочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3098,'Включить для разогрева до 200 градусов духовой шкаф. В сковороде при среднем нагреве растопить масло, всыпать муку, размешать, прогреть до появления коричневого цвета, поперчить, подсолить, залить молоком и еще раз тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3098,'Убрать сковороду с плиты, вылить содержимое в глубокую миску. В другую миску насыпать смесь соли с перцем, обвалять кусочки картофеля, переложить их внахлест друг на друга в сковороду, залить смесью молока. Слои картофеля прослоить сырной стружкой, сдобрить солью и перцем, часть сыра оставить для оформления верха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3098,'Прикрыть сковороду со сливочным картофелем эскалоп несколькими слоями фольги, запечь около часа. По окончанию удалить фольгу и минут 10 обжарить до образования золотистой румяной корочки, вынуть из духового шкафа, дать постоять около 10 минут и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3099,'Вареную курицу остудить и порезать на кубики среднего размера, на такие же кубики порезать огурцы, зелень укропа порубить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3099,'Переложить в салатник добавить зеленый горошек, подсолить, приправить сметаной, размешать, дать для усиления вкуса немного постоять. Салат «Леди» со сметаной готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3100,'Нагреть сковороду, обжарить до золотистой корочки булочку. Нижнюю часть промазать соусом Хайнц с сыром, а верхнюю – острым соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3100,'На сырный соус положить зеленый листик салата вместе с тоненькими кружочками лука и помидоров. Теперь положить основной ингредиент – котлету из говяже-свиного фарша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3100,'Для любителей острого посыпать перцем, накрыть пластинкой сыра и обжаренным яйцом (желток должен оставаться жидким). Завершить сборку бургера «Сытый Джо» булочкой, покрытой острым кетчупом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3101,'Перемешать в однородную массу лимонный сок, соевый соус и мед. Рыбу, порезанную на порции замариновать минут 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3101,'Переложить рыбу вместе с маринадом в подходящую форму, присыпать семенем кунжута и поставить рыбу в медово-лимонном маринаде в духовку, прогретую чуть ниже 190 градусов примерно на треть часа, подавать лучше с овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3102,'Залить молоком желатин в стакане примерно на час, хорошо разбухший прогреть до получения прозрачной жидкости и убрать с плиты, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3102,'Положить в миску творог, всыпать сахар, перемешать, добавить мелко раздробленные орехи, сметану, порезанную на кусочки курагу, раствор желатина, еще раз все хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3102,'Подготовить форму, выложить пластинками яблок, творожной смесью, опять яблоками, завершить слоем творожной массы, поставить на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3102,'Форму достать, погрузить дно в кипяток, осторожно перевернуть творожный торт «Морозко» на плоское блюдо, оформить кусочками киви и курагой. Для новогоднего блюда вырезать из бумаги снежинку, присыпать мелко измельченными орехами или шоколадом, а потом осторожно ее убрать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3103,'Приготовить на минералке с добавлением подсоленной муки и яиц кляр по консистенции как домашняя сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3103,'Кусочки филе обмакнуть в готовый кляр, обжарить в сильно разогретом масле. Подавать к столу нежную и аппетитно хрустящую рыбу в кляре на минеральной воде лучше горячей с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3104,'Перекрутить дважды мякоть куриных грудок вместе с луком, добавить рис, отваренный в подсоленной воде со специями до полуготовности, тщательно все перемешать. Скатать небольшие шарики, обкатать в муке и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3104,'Перемешать томатную пасту (либо кетчуп) со сливками и небольшим количеством воды, залить тефтельки, запечь тефтели из куриного филе примерно треть часа, минут за пять до конца присыпать сыром и дать ему расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3105,'Порубить до состояния крошки охлажденное масло с просеянной мукой, содой и сахаром, добавить холодный кефир, желток, тщательно перемешать до образования мягкого теста, разрезать его на две части и убрать на час в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3105,'Достать одну часть, раскатать в пласт, переложить на противень, застеленный промасленной бумагой. По тесту размазать ровным слоем любое (желательно погуще) варенье, прикрыть вторым раскатанным пластом, смазать верх разболтанным белком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3105,'Выпекать печенье на кефире с вареньем к чаю примерно полчаса при температуре около 180 градусов, достать подрумяненный корж, порезать квадратиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3106,'Чуть подсолить охлажденные желтки от трех крупных яиц, помещенных в чашу миксера, добавить сахар, слегка взбить в однородную массу. Влить уксус, перемешать, добавить горчицу, установить на миксере среднюю скорость, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3106,'Не выключая миксера небольшими порциями добавить масло, каждый раз, хорошо взбивая до полного эмульгирования смеси, густота майонеза будет зависеть от количества влитого масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3106,'По вкусу в майонез добавить зелень, чеснок или горчицу, все еще раз взбить, хранить в холодильнике не более 6 дней. Вкусный майонез с зеленью в домашних условиях готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3107,'Сварить грибы (10 минут будет достаточно), но лучше запечь или чуть-чуть зажарить, а любители могут оставить их сырыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3107,'Подкопченное мясо, помидор, огурец порезать на одинаковые по размеру кубики, всыпать порубленную зелень, приправить майонезом, подсолить, поперчить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3107,'Заполнить этой смесью чуть остывшие шляпки, украсить фаршированные шампиньоны с копченой курицей маслинами без косточек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3108,'Для приготовления соуса смешать кетчуп, рубленую зелень, майонез, чеснок и немного соли. Сварить рис, овощи, сыр, порезать по отдельности на мелкие кубики. Салат «Креветочный» уложить на блюдо слоями, промазывая каждый соусом, в следующем порядке: рис – смесь огурцов с помидорами – яйца – сыр. Верх оформить креветками, перед самой подачей присыпать зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3109,'Всыпать в стакан желатин, залить кипяченой водой комнатной температуры, дать постоять примерно полчаса, чтобы хорошо разбух, далее подогреть, размешивая его до полного растворения (кипеть не давать!). Взбить сметану хорошего качества с мелким сахаром, влить, перемешивая тоненькой струйкой в нее раствор желатина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3109,'Взять глубокую куполообразную миску, выстелить дно и стенки пленкой, положить ягоды, прикрыть их поломанным на кусочки бисквитом, опять ягоды и т.д. В конце залить желатином со сметаной, убрать сметанный тортик с фруктами на пару часов в холодильник. Накрыть миску плоским блюдом, аккуратно перевернуть, удалить пленку и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3110,'Включить для разогрева до 180 градусов духовку. Просеять в объемную миску муку с пекарским порошком, чуть подсолить. Разогреть в сотейнике молоко, положить масло, дать ему растаять, перемешать, снять с плиты, дать остыть. Яйца взбить в крепкую пену вместе с сахаром, добавить порциями масло с молоком, а затем муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3110,'Полученную массу взбить в однородное тесто, вылить его в форму, выстланную смазанным маслом пергаментом, поставить в духовку, бисквит будет готов примерно через 45 минут, когда на корже образуется корочка золотистого цвета, а зубочистка после его протыкания будет оставаться сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3110,'За время выпекания приготовить пропитку для торта, перемешав с добавлением ванили все три молока. Готовый корж переложить на широкое блюдо, многократно аккуратно проткнуть его тонким ножом, залить пропиткой, дать постоять ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3110,'После того, как бисквит готов, вынимаем его из формы и перекладываем в емкость, которая будет немного шире его в диаметре. Для того, чтобы залить будущий торт пропиткой, следует проткнуть его ножом во многих местах, добавить пропитку и оставить на ночь. Утром домашний торт «Три молока» покрыть топингом, оформить вареной сгущенкой или глазурью, можно цукатами с фруктами, либо взбитыми сливками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3111,'Огурцы порезать на мелкие кубики и перемешать в однородную массу с майонезом, грибы и лук порезать, и обжарить до изменения цвета у лука. Выложить на блюдо слоями в следующем порядке: картофель – мясо – грибы и лук – желтки – белки. Каждый слой промазать смесью майонеза и огурца, верх салата «Язычок под шубкой» оформить рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3112,'В глубокой миске перемешать сахар с пятью яйцами, всыпать соду, перемешать, добавить какао и муку, смешать до однородности. Влить в полученную массу стакан кефира, добавить муки, перемешать до состояния густой сметаны, отлить половину в форму, испечь корж, повторить процесс со второй порцией теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3112,'Дать коржам остыть, разрезать каждый вдоль на две части, из полученных четырех, но более тонких, пару оставить, а другую — поломать на небольшие части. Для смазывания шоколадного торта приготовить из взбитой жирной сметаны и сахара с добавлением раствора желатина крем. Нарезать по паре апельсинов, киви либо персиков, бананов. По вкусу можно использовать и другую комбинацию фруктов: абрикосы, ананас, клубника и т.п. Кусочки фруктов перемешать с кремом, маком и кусочками поломанных коржей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3112,'Уложить в форму корж, смазать полученной массой из фруктов и сметаны, накрыть вторым коржом, вырезанным в форме лепестков ромашки, убрать для пропитки торт в холодильник минимум на час, а для более лучшей можно и на дольше. Вынуть торт шоколадный «Африканская ромашка» из холодильника, лепесточки для завершения картины покрыть мастикой из белого шоколада, или фруктовым желе светлого тона, но и без этого торт уже готов к употреблению.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3113,'Подготовить и нарезать на куски мясо, замариновать примерно на 40 минут в смеси кетчупа, крахмала и растительного масла. В сильно разогретом масле обжарить быстро перец (около полуминуты), добавить тертую морковь, раздавленный прессом чеснок, жарить все вместе еще чуть больше полминуты, не забывая помешивать, переложить содержимое сковороды на тарелку. Влить в сковороду столовую ложку масла, сильно разогреть, обжарить со всех сторон кусочки мяса в течение пару минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3113,'Сдобрить молотым перчиком, влить немного воды, положить несколько листиков лаврушки, закрыть сковороду крышкой, убавить нагрев до минимального, тушить примерно четверть часа или чуть больше (все зависит от размеров кусочков мяса). Положить к мясу овощи, протушить еще пару минут, подать к столу горячей, присыпав рубленой зеленью. Свинина с овощами в томатном маринаде готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3114,'Мелко порезать лук, огурец очистить, натереть на крупной терке. На такой же терке натереть охлажденные крабовые палочки, отдельно – яйца и твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3114,'Салат выложить слоями на плоское блюдо, соблюдая следующую последовательность: лук – майонез; огурец (отжатый от сока) – майонез;  палочки – майонез; яйца – майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3114,'Чередование слоев повторить еще раз, верхним сделать сырный, оформить верх слоеного салата «Вкусный» с крабовыми палочками зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3115,'Добавить к холодным белкам щепотку соли, всыпать сахар, взбить. В другой посуде взбить желтки вместе с сахаром, добавить растительное масло, ваниль, перемешать, влить молоко, всыпать какао, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3115,'Понемногу к желтковой смеси добавить просеянную муку вместе с разрыхлителем, каждую порцию тщательно перемешивать, добавить взбитые белки, должно получиться однородное шоколадное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3115,'Подготовить широкую форму, заполнить полученным тестом, поставить примерно на 45 минут в духовку с температурой 180 градусов. Готовый корж хорошо охладить, разделить вдоль на 3 части. Либо можно выпечь два коржа, а потом каждый разделить на два, в результате получится торт из четырех коржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3115,'Перемешать мягкое масло, вареную сгущенку и растопленную плитку шоколада, смазать полученным кремом все коржи и бока торта. Верх домашнего торта «Шоколадное кухэ» залить еще одной растопленной плиткой шоколада, дать ему застыть, оформить ягодами клубники, убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3116,'Нашинковать лук, обдать кипятком, копченую куриную грудку порезать на кубики, отжать корейскую морковку, все смешать, добавить сцеженную кукурузу. Заправить салат «Карусель» майонезом, перед самой подачей к столу всыпать сухарики и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3117,'Подсолить салат «Ветка сакуры», перемешать, переложить в салатник, присыпать сырной стружкой. Верх украсить сакурой, цветочки которой сделать из белка и покрасить соком свеклы, а веточки — из кусочков огурца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3118,'Порезать соломкой твердый сыр, не жирную ветчину, пару-тройку свежих огурцов (твердую шкурку лучше очистить), все смешать, подсолить. Добавить в салат «Кармелита» с ветчиной майонез, аккуратно перемешать, переложить в салатницу, оформить веточками зелени и порезанным на полоски сладким перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3119,'Взбить половину стакана сахара (всыпать постепенно) с белками до крутой устойчивой пены, оставшуюся половину стакана сахара растереть с желтками, осторожно все перемешать. Яблоки почистить, удалить середину с косточками, порезать на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3119,'В смесь всыпать муку (предварительно просеять), должно получиться однородное тесто, напоминающее по густоте хорошую сметану. Подготовить форму, смазать дно и бока маслом, выложить на дно ломтики яблок и кусочки ананаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3119,'Прикрыть фрукты тестом, выпекать сладкую шарлотку с ананасом минут 40 в духовке с температурой 180 градусов. Верх выпечки должен зарумяниться, а спичка, опущенная в тесто должна оставаться сухой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3120,'Разогреть сковороду, налить масло, обжарить одну сторону ломтей хлеба до аппетитной хрустящей корочки, рыбу поломать вилкой на кусочки, укроп мелко порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3120,'Сложить в миску укроп, рыбу, сыр, размешать, смазать ломти хлеба, украсить кростини с лососем и сливочным сыром тонкими ломтиками огурца и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3121,'Порезать сало и мясо на кусочки, прокрутить на мясорубке, фарш подсолить, приправить перцем, перемолотым лавровым листом, тмином, добавить чеснок, натертый на мелкой терке, фарш хорошо вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3121,'Подготовить кишки, тщательно промыть, залить раствором соды с уксусом, дать немного постоять, хорошо обмыть водой. Надеть кишки на специальную насадку на мясорубке, заполнить фаршем, разделить и перевязать нитками на отдельные колбаски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3121,'Часть мясных колбасок можно заморозить впрок, а другую сварить, зажарить или запечь. Подавать эту вкуснятину лучше с гарниром из картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3122,'Смешать сметану и майонез в равных пропорциях. Добавить сырые яйца, взбить смесь венчиком. Вмесить муку порциями. Приготовить начинку, нарезать кубиками мясные продукты: сосиски, салями, ветчину. Порезать помидоры тоже кубиками или тонкими кружками, их можно не разрезать на сегменты, если помидоры мелкие. Порезать колечками маслины, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3122,'Тесто вылить на смазанную растительным маслом сковороду. Выложить начинку ровным слоем, посыпать сыром. Можно добавить средиземноморские или любые другие специи – вкус пирога будет ярче и насыщеннее. Майонез налить в кондитерский мешок и нанести на пиццу сеточкой. Печь очень быструю пиццу с салями под крышкой на небольшом огне до готовности, сыр должен расплавиться, это и будет признаком готовности блюда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3123,'Свежую красную рыбу натереть крупной морской солью и сахаром. Можно использовать и простую соль, но вкус будет немного другим. Отдельно приготовить смесь рубленого укропа и мелко натертой цедры лимона или лайма.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3123,'Обвалять рыбу в этой смеси и сбрызнуть коньяком. Рыбу положить в кастрюлю, закрыть пленкой, оставив дырочки для доступа воздуха. Красную рыбу, маринованную с коньяком, поставить в холодильник, лучше, если оно постоит в холоде не менее 12 часов. Если закуска нужна срочно – будет достаточно 2 – 3 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3124,'Кальмары обдать горячей водой и очистить от пленки. Положить в кипящую воду, варить 3 – 4 минуты, не дольше, иначе они станут «резиновыми». Порезать полосками. Покрошить остальные ингредиенты: свежие огурцы, яйца, сваренные вкрутую, лук-репку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3124,'Огурцы можно очистить, зеленую кожицу снять стружкой или длинными полосками – они пригодятся для украшения блюда. Соль по вкусу. Диетический салат из кальмаров заправить сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3130,'Выложить карпаччо из говяжьего филе на блюдо, полить  небольшим количеством приготовленного зеленого соуса. Посыпать тонкими полосками тертого пармезана. Украсить ломтиками помидоров, листиками рукколы, яйцом. Отдельно подать порезанный четвертинками лайм.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3125,'Картофель порезать дольками (лучше взять некрупный, молодой), варить пять минут в воде с небольшим количеством соли.  Порезать дольками кабачки и баклажаны. «Синенькие» немного горчат, их лучше заранее порезать, немного подсолить и дать постоять, горечь уйдет вместе с излишками сока, отцедить. Нарезать соломкой красный сладкий перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3125,'Помидоры натереть или нарезать кружочками. Порубить чеснок. Взять глубокую форму для выпечки, смазать маслом, на дно выложить картофель, затем подсоленные кабачки, перченые баклажаны, сладкий перец. Сверху запеканку посыпать чесноком. Залить нежные ароматные овощи сметаной, поверх нее – помидоры. Печь в течение 25 – 35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3126,'С кусочка белого хлеба срезать корочки, мякиш порвать руками и залить молоком до набухания. Порезать кусочками мясо (лучший вариант – телятина). Очистить картофель и лук, также порезать. Все ингредиенты пропустить через мясорубку, включая хлебный мякиш, отжатый от лишнего молока. Добавить рубленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3126,'В готовый фарш вмешать растопленное сливочное масло, сырое яйцо, соль, перец и горчицу по вкусу. Если фарш буде жидковат – добавить немного панировочных сухарей и дать постоять, лишняя жидкость просто испарится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3126,'Котлетки слепить руками, круглой формы. Панировать не обязательно. Жарить на растительном масле, на среднем огне, переворачивать, следить, чтобы не пригорели. Дотушить под крышкой. Готовые вкусные котлетки из телятины складывать партиями в другую посуду с крышкой, чтобы не успевали остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3127,'Курицу отварить, нарезать мясо кубиками или соломкой. Содержимому банки консервированных ананасов дать обтечь, мякоть нарезать небольшими кубиками. Отдельно натереть твердый сыр. Приготовить заливку, для этого чеснок порубить или пропустить через чеснокодавку и смешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3127,'Ингредиенты заправить этой смесью, проверить, нужна ли еще соль, добавить при необходимости. Поперчить и разложить порционно на листья свежего зеленого листового салата. Салат «Дамский» с куриным филе можно украсить петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3128,'Крупную луковицу нарезать тонкими полукольцами. Обжарить на растительном масле до золотистого цвета. Печень можно взять любую, самая нежная и быстрая в приготовлении – куриная. Нарезать ее кусочками, добавить к жарящемуся луку, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3128,'Добавить специи, например, зиру, рубленый чеснок, соль по вкусу. Когда кусочки печени посветлеют (это произойдет через несколько минут) – огонь убавить. Залить куриную печень сметаной, закрыть крышкой и тушить 5–10 минут. Подать на листьях свежего листового салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3129,'Растительное масло нагреть в сковороде, обжарить на нем до мягкости рубленую лук-репку и чеснок. Затем положить шпинат и жарить еще две минуты. Шпинат должен немного завянуть, но не потерять цвет.  Приправить зеленую начинку солью, перцем, кедровыми орешками и остудить. Противень для выпечки смазать растительным маслом, выложить готовое слоеное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3129,'Сверху – начинка из шпината. Посыпать измельченным сыром, можно использовать сыр фета или другой, начинку выложить на половину теста, завернуть другой половиной. Края можно соединить с помощью вилки, просто прижимая их к поверхности стола. Печь пирог с сыром, шпинатов и кедровыми орешками при 190 градусах в течение 20 минут, тесто должно немного подняться и подрумяниться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3130,'Мясо (филе, говядина) заморозить в холодильнике. Пока мясо морозится – приготовить соус. Рукколу промыть, отварить яйцо вкрутую, разрезать его не половинки. Каперсы и анчоусы распечатать и дать стечь жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3130,'Разрезать на четыре части лук-шалот. Все соединить и взбить с мякишем белого хлеба, оливковым маслом и винным уксусом до однородности. На взбивание зеленого соуса должно уйти не более одной минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3130,'Достать говядину из морозилки, очень острым ножом тонко нарезать на тонкие (3 мм) ломтики. Выложить их на алюминиевую бумагу по два кусочка вместе, сверху накрыть такой же бумагой и прокатать скалкой, мясо станет еще мягче.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3144,'Комок теста завернуть в пленку и положить в холодильник на 2 часа. В блендере измельчить лук. Можно натереть его на терке. Фарш смешать с луком, посолить, добавить специи. Слепить чебуреки из теста и фарша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3131,'Лимоны очистить. Часть цедры можно натереть и добавить в крем, аромат от этого только усилится и дольше сохранится. Из мякоти цитрусовых выдавить сок, добавить сахар и мешать до растворения сахара. Смесь не должна быть кислой, нужно проверить на вкус, при необходимости еще добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3131,'Отдельно вручную взбить яйца, процедить, влить лимонный сок с сахаром, перемешать. Если не нравится цедра в креме – можно дать крему постоять, а потом процедить и кусочки цедры, которые уже отдали свои ароматы блюду, выбросить. Перелить смесь в кастрюлю, добавить сливочное масло и ванилин, варить до загустения, помешивая. Разлить нежный  десертный лимонный крем в баночки, хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3132,'Куриное мясо порезать кусочками, промыть и обсушить салфеткой. На сковороде разогреть растительное масло, обжарить курицу, быстро переворачивая, не пересушить. Соль, перец, любые любимые пряности – по вкусу, добавить в конце обжаривания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3132,'Приготовить соус-заливку: порубить или пропустить чеснок через чеснокодавку, добавить мелко порезанный укроп, сметану, соль. Разбавить смесь водой в пропорции 1 к 1,5 (воды понадобится больше), перемешать и залить курицу. Тушить под крышкой 15–20 минут. Соус не должен выкипеть весь, если жидкости становится маловато – долить. Ароматная курица в сметане с чесноком готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3133,'Сливочное масло выдержать в тепле, чтобы оно стало комнатной температуры. Взбить его вместе с сахаром в белую пышную массу. Шоколад растопить в микроволновке или водяной бане. С апельсина срезать цедру теркой.  Шоколад и цедру добавить к маслу и взбить еще раз. Отдельно в другой посуде смешать какао-порошок, муку и разрыхлитель. В масляно-шоколадную смесь влить молоко, вбить яйца и хорошо взбить еще раз. Теперь просеять сухие ингредиенты и взбить снова до однородности. Тесто должно быть гладким, без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3133,'Для приготовления торта взять две формы, которые помещаются друг в друга и при этом в большой форме есть место для воды. Готовить торт будем на водяной бане. В маленькую форму налить тесто и накрыть плотно фольгой. Стенки формы предварительно нужно смазать маслом. В большую форму налить воды и поместить в нее маленькую форму. Всю конструкцию поставить на плиту. Довести воду до кипения. Потом убавить огонь, чтобы вода продолжала немного кипеть, и продолжить варить. Уровень воды в большой форме не должен меняться. Варить на протяжении 1,5 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3133,'Потом убрать с плиты и оставить остывать в маленькой форме. Торт при остывании ужмется, его будет легко достать. Приготовить соус. Для этого все ингредиенты положить в ковш и варить, помешивая, на среднем огне примерно 3 минуты. Соус остудить и затем вылить его в середину торта, чтобы масса сама растеклась по поверхности торта. Шоколадный торт с оригинальной структурой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3134,'Грибы тонко нарезать. Обжарить их с солью и карри до готовности и потом потушить еще в сметане. Остудить. Яйца взбить. Влить к ним немного молока и всыпать немного просеянной муки, замешивая тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3134,'Постепенно, частями добавить все молоко и муку к тесту. Половинку луковицы окунуть срезом в растительное масло. Этой луковицей смазать разогретую сковороду. Выпечь тонкие блинчики. Их будет примерно 20 штук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3134,'Собрать торт. Блинчик намазать плавленым сыром, выложить сверху грибы и прикрыть следующим блинчиком. И так пока не закончится начинка. Блинный торт с шампиньонами и сыром  можно подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3135,'Масло размягчить и взбить с сахаром. К маслу добавить поочередно по одному желтку, продолжая взбивать. Подмешать воду, крахмал и муку.  Белки взбить до консистенции крепкой пены и аккуратно вмешать в тесто. Густота теста будет как кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3135,'Трубочки выпечь сразу же после приготовления теста. Вафельница должна быть хорошо разогрета. Открыть ее, вылить на середину нижней части 1 ст. л. теста. Закрыть и прижать. Выпекать, ориентируясь на цвет вафель: они должны быть светло-коричневыми.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3135,'Готовые вафли осторожно снять с вафельницы. Можно делать это лопаткой, ножом. Пока вафля еще не остыла свернуть ее в трубочку и переложить на блюдо. Вкуснейшие трубочки начинить любимым кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Смесь из томатной пасты с вином и водой (1:1), поперчить, залить в сотейник, тушить рулеты час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3136,'В кефир всыпать сахар и соды, посолить. Перемешать. Муку и сыр добавить к кефиру, снова перемешать. Получившееся тесто разделить на шарики, раскатать каждый в лепешку и положить сверху начинку. Края лепешки соединить и немного прикатать сверху скалкой. Лепешки на кефире жарить на сковороде с разогретым маслом с двух сторон, накрыв крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3137,'Апельсины помыть и срезать с них по одной верхушке. Мякоть вынуть, чтобы из апельсинов получились «мисочки». Все фрукты и ягоды нарезать кубиками или небольшими ломтиками. Гранат очистить и разделить на зерна, виноград разрезать напополам и вынуть косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3137,'На дно апельсиновой кожуры положить немного джема, затем наполнить фруктами. Мякоть апельсина тоже положить внутрь. Сверху украсить сладкий фруктовый салат «Сочный дракон» зернами граната, посыпать орешками и корицей. Для украшения также можно использовать листики мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3138,'Перловую крупу хорошо промыть, выложить на сито и обсушить. Грибы порезать, выложить в кастрюлю с  1,5 л воды, подсолить и отварить. Мелко порезать лук и слегка, до прозрачности обжарить в оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3138,'К луку положить сливочное масло, туда же всыпать перловку. Помешивая, прогреть крупу с луком, пока крупа не станет немного прозрачной. Добавить на сковороду 1 половник грибного бульона, перемешать и подождать пока впитается. Аналогично добавить еще бульона, всего его нужно влить 1 литр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3138,'Когда перловка практически приготовится, добавить бальзамический уксус. Грибы, сливки и специи добавить спустя 2–3 минуты.  Варить, постепенно подливая при необходимости грибной бульон, еще 20 минут. Перлотто с лесными грибами и луком украсить зелеными листиками петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3139,'Отварить куриное филе. Мясо курицы и шампиньоны нарезать на небольшие кусочки. Мелко покрошить лук. Сначала обжарить лук, затем к нему на сковородку выложить грибы и держать на плите, пока не выпарится вся влага. Добавить куриное мясо. Посолить, добавить перец и снять с огня. На второй сковороде, без добавления масла обжарить муку до золотого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3139,'Влить к муке сливки, положить соли, перца и довести до кипения. Смешать соус с грибами и мясом, снять с плиты. Полученную массу выложить в кокотницы. Сверху посыпать тертый сыр. В разогретую до 180 градусов духовку поставить кокотницы на 30 минут. Кокотницы с готовым жульеном «Наслаждение» с куриным филе поставить на сервировочное блюдо и подавать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3140,'Мясо отварить, остудить и порезать кубиками. Натереть морковь на средней терке и на сковороде обжарить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3140,'Порезанный мелкими кубиками лук залить смесью уксуса, сахара и кипятка. В течение 15 минут промариновать лук. Затем слить маринад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3140,'Смешать мясо, лук, морковь, горошек. Заправить салат «Купеческий» майонезом. Соль и перец добавить по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3141,'В средней по размеру кастрюле смешать белый шоколад, молоко и соль. На умеренном огне закипятить, уменьшить огонь и 2 минуты варить. Шоколад нужно постоянно помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3141,'Белый горячий шоколад с взбитыми сливками нужно подавать в горячем виде. Для украшения можно посыпать корицей, кокосовой или шоколадной стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3142,'Замесить тесто из всех продуктов, хорошо его вымесить, чтобы не было комочков. Вылить массу в силиконовую или стеклянную форму, подходящую для использования в микроволновой печи. Включить самую максимальную мощность и выпекать 7 минут. Для украшения шоколадный кекс в микроволновке можно посыпать сахарной пудрой, полить сиропом, шоколадной глазурью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3143,'Взбить яйца с молоком. К ним добавить черный перец. Сыр положить на хлеб, сверху ветчину, затем второй ломтик сыра и закрыть сверху вторым кусочком хлеба.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3143,'Обмакнуть в яйца с молоком и обвалять в панировочных сухарях.  Хлеб пожарить с двух сторон на сковородке до золотистого цвета. Горячий бутерброд с ветчиной в рубашке готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3144,'Просеять муку. Добавить яйцо и растереть руками до образования мелкой сухой крошки. Влить в крошку растительное масло и снова перетереть. В крошку добавить небольшими порциями подсоленную воду и замесить гладкое и мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6375,'Кипятком ошпарить репчатый лук и измельчить, порубить мелко зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3144,'Противень застелить пергаментом и выложить на него чебуреки. Сыр натереть. Яйцо взбить. Чебуреки смазать яйцом и присыпать сыром и зеленью. Фольгой прикрыть противень так, чтобы она не касалась ваших изделий. При выпекании чебуреков с мясным фаршем в духовке фольгу снять через 15 минут и выпекать еще столько же без нее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3145,'Рыбу порезать на кусочки и засыпать солью. Оставить на 12 часов в холодильнике. Затем рыбу достать и промыть от соли. Залить уксусом 6% на 5 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3145,'Рыбу уложить в посудину слоями в таком порядке: рыба, перец, лук. Залить все растительным маслом и оставить на 12 часов в холодильнике. Рыбка, маринованная в уксусе с луком готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3146,'Сыр смешать с яйцом, всыпать разрыхлитель и муку. Посолить. Полученную массу разбавить сметаной, йогуртом или кефиром до густоты сметаны. Сырную смесь вылить на разогретую сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3146,'Если сковорода будет маленькой, то хачапури получится пышным. Посыпать сверху зеленью. Жарить ленивые хачапури на сметане на средней мощности плиты под крышкой, пока края не подрумянятся, потом перевернуть на другую сторону и жарить на второй стороне до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3147,'Грибы порезать, посолить, поперчить. Бульон довести до кипения. Одновременно с этим налить в сковороду 1 ст. л. оливкового масла, дождаться, когда оно разогреется и обжарить грибы за 3–4 минуты.  Вынуть грибы со сковороды и положить туда еще 2 ложки оливкового масла, хорошо разогреть и обжарить лук-шалот за 1–2 минуты, добавить к нему рис, посолить и жарить еще 3 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3147,'Уменьшить огонь до умеренного. На сковороду влить полстакана кипящего бульона. Перемешать и подождать пока он впитается. Еще добавить полстакана, опять дать впитаться. И так добавить весь оставшийся бульон. Это займет примерно 30 минут. Выложить к рису готовые грибы добавить сливочное масло и пармезан.  Добавить к ризотто на курином бульоне с грибами специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3148,'Вишню залить водой и насыпать сахар. Вскипятить, убавить огонь, открыть крышку и тушить 2–3 минуты, пока сироп не загустеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3148,'Йогурт перемешать с корицей. В креманку вылить слоями йогурт и вишню. Украсить парфе с вишней крошками печенья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3149,'Вымыть перец, срезать у него верхушку, перегородки и семена вынуть. Приготовить фарш, для этого обжарить полукольца лука на топленом масле. Рис слегка отварить, промыть и смешать с луком. Мясной фарш и рис с луком перемешать и добавить к ним яйцо, соль и черный перец по вкусу, зелень. Вымешать фарш до однородности. Фаршем наполнить перцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3149,'Сливочное масло растопить на дне кастрюли. Поставить плотно перцы, вертикально, дном вниз в кастрюле, налить воды, положить томатную пасту. Уровень воды должен быть до краев перца. Кастрюлю с перцами накрыть крышкой и тушить на слабом огне 30 минут. Лавровый листик добавить за 5 минут до готовности. Болгарский перец с начинкой из куриного фарша подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3150,'Сахар и размягченный маргарин смешать вместе. Добавить яйцо, перемешать. Молоко немного подогреть. Дрожжи развести в молоке. Молоко и маргарин смешать, всыпать муку и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3150,'Замесить тесто и потом завернуть его в пищевую пленку. Оставить на 15–20 минут. Начинку для пирожков из французского дрожжевого теста можно делать любую: картошку, лук, грибы, сладкие начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3151,'Растопить на водяной бане 150 грамм шоколада и остудить. Полстакана сахара взбить с белками. Взбить масло с 0,5 стакана сахара. Масло должно быть комнатной температуры. К маслу добавить желтки и шоколад, снова взбить. Затем добавить взбитые белки, крахмал и снова взбить. Выложить тесто в форму, смазанную маслом и посыпанную мукой. Выпекать при 160 градусах примерно 50 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3151,'Тесто можно разделить на 2 отдельных коржа, которые выпечь отдельно. Или выпечь один большой корж и после остывания разрезать пополам. Клубнику промыть, обсушить, нарезать. Клубничный джем растопить на водяной бане. Нижний корж намазать джемом, выкладываем на него клубнику. Накрываем вторым коржом, поливаем шоколадной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3158,'Отдельно взбить яйцо и смешать его с молоком. Немного присолив залить этой смесью рулет в жаропрочной форме и поставить его в духовой шкаф. Время готовки при температуре в 180 градусов составить полчаса. Готовый горячий ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3151,'Шоколадную глазурь готовить так: полстакана сахара и полстакана воды вскипятить, положить туда 300 грамм шоколада, растопить. Когда шоколад расплавится, то снять с огня. До кипения глазурь не доводить. Глазурь нанести на торт в несколько этапов. Между каждым этапом ставить торт в холодильник. Верхний корж можно украсить клубникой или выложить ее под слой глазури. Домашний шоколадный торт со свежей клубникой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3152,'Из продуктов для теста замесить тесто. Разделить его на 9 равных шариков, раскатать каждый в пышку. Каждую пышку жарить на сухой сковороде до золотистого цвета с двух сторон. Для крема яйцо с сахаром взбить и добавить к ним муку. Взбить яично-мучную смесь до однородной массы. Вскипятить молоко и вылить туда яично-мучную смесь. Варить до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3152,'В теплый крем добавить масло и ванилин, перемешать, дать растворится маслу и остудить. Каждую пышку обмазать кремом с двух сторон, сложить стопкой. Тортик сверху посыпать измельченным печеньем. Быстрый торт «На скорую руку» на кефире оставить пропитаться на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3153,'Хлеб разрезать небольшими кубиками или по желанию брусочками и обжарить на сковороде с небольшим количеством масла. Дно и бортики миски натереть чесноком  и пересыпать в нее гренки немного встряхнуть, для того, чтобы поджаренный хлеб приобрел тонкий аромат чеснока, но при этом не имел характерной горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3153,'Белокочанную капусту нашинковать ножом, либо используя шинковку. Присолить капусту и немного помять руками, чтобы из нее выделился сок. Филе сельди разрезать на небольшие кусочки, но не кроить, чтобы рыба в салате имела вкус, а не послевкусие. Соленый огурец измельчить. Добавить огурец и сельдь к капусте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3153,'Микс из зелени промыть и обсушив, нашинковать мелко. Прибавить зелень к капусте. Сюда же положить рубленый чеснок. Заправить салат майонезом средней жирности и аккуратно перемешать, используя для взрыхления капусты две столовые ложки, которыми ингредиенты при смешивании поднимаются снизу вверх.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3153,'На блюдо разложить салатные листы, сверху горкой выложить салат из капусты с сельдью и зеленью. Присыпать салат «Садко» успевшими остыть, гренками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3154,'Свежий огурец и паприку нарезать соломкой, корень сельдерея обчистить и натереть на крупной терке. Проросшую фасоль залить горячей водой и сразу же откинуть на дуршлаг. Присолить. Помидоры черри освободить от плодоножек и промыв, разрезать пополам. Свиную ветчину нарезать слайсами на тонкие пластины, каждую из которых опустить по очереди в кипяток на 2-3 секунды, до приобретения мясом более бледного оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3154,'Овощи смиксовать и небольшими пучками заворачивать в пластины, из ветчины скрепляя на конце деревянными шпажками, чтобы ни раскручивались. Выложить закусочные рулетики из ветчины с овощами на подушку из ростков фасоли маш. Приправить соусом из кунжута, предварительно дополненным нашинкованным белым луком и украсить помидорами черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3155,'Подготовить соус. Для этого необходимо смешать соевый соус с чайной ложкой рисового уксуса, за неимением которого можно использовать лимонный сок. В полученную смесь вмешать пол чайной ложки картофельного крахмала. Нарезать свинину брусочками, овощи такими же по размеру кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3155,'Обжарить на раскаленном масле мясо. Для того чтобы мясо не пустило сок, его необходимо класть в сковороду небольшими порциями и обжаривать до образования золотой корочки. Нарезка тонкими брусочками дает возможность мясу в такой непродолжительный срок пребывания на сковороде при высокой температуре, основательно прожариться и не быть сырым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3155,'После того, как все мясо будет готово, наступает очередь овощей, их так же прожарить порционно и переложить в емкость к свинине. Желательно не пережаривать овощи, они должны быть хрустящими и сочными. В отличие от нашей традиционной кухни, китайская кухня не предполагает длительного тушения и жарки, а готовность блюд достигается методом высоких температур, мелкой нарезки и особого состава соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3159,'Для сочного маринада смешать масло растительное, предпочтительно оливковое с соевым соусом. Добавить толченный с солью чеснок и ароматный базилик изрубленный меленько. Для любителей острого пригодиться щепотка черного свежесмолотого перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3155,'В последнюю порцию овощей при жарке добавить толченый чеснок и рубленую зелень, быстро пересыпать все ранее приготовленные овощи вместе с мясом, залить соевым соусом и перемешать. Свинину «Стир-фрай» в соевой заливке переложить на керамическое блюдо и подать к столу горячей. В идеале такое блюдо подается на чугунной сковороде под крышкой, и ставиться перед едоком на деревянную дощечку. После открытия крышки температура мяса 50-60 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3156,'Рис  замочить и промыть в нескольких водах  до прозрачности. Отварить до готовности, стараясь не переварить. В идеале, зернышки при раскусывании должны немного хрустеть, но не быть при этом сырыми. Куриное мясо промыть и обсушив порезать очень мелко, дополнительно можно изрубить мясо ножом после резки. Переложить мясо к успевшему остыть рису.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3156,'В рис добавить измельченную свежую паприку красочных тонов, перемешать. Укроп так же необходимо изрубить и ввести к фаршу. Вбить в фарш яйцо и хорошо вымешать, присолить и добавить щепотку молотого перца и выбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3156,'Жарить такие рубленые котлеты необходимо на разогретом масле, изначально под крышкой, а после, сняв крышку, довести до образования хрустящей корочки. Повторив весь процесс, с точностью до наоборот, можно получить хорошо тушеные, мягкие котлетки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3156,'Рубленые куриные котлеты с рисом и болгарским перцем имеют нежную структуру, они вкусны и ароматны, а благодаря сочетанию сладкого перца и укропа вкус их по особому пикантен.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3157,'Переложить в кастрюлю с толстым дном полпачки сливочного масла и поставить на огонь. Когда масло растопится прибавить к нему воду, соль, сахар-песок и, перемешав довести до кипения. Снять кастрюлю с огня и понемногу всыпать просеянную муку. Вымешать тесто до гладкости. Взбить отдельно куриные яйца и ввести в остывшее тесто тонкой струйкой при беспрерывном помешивании. Тесто должно получиться масляно гладким, блестящим и жидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3157,'Включить духовку на 220 градусов. Пока духовка разогревается сформировать пирожное. Для этого форму необходимо выстелить промасленным пергаментом или особым кулинарным силиконовым листом. Перекладываем жидкое заварное тесто в кондитерский мешок с рефленной насадкой и выдавливаем из него круглые кусочки теста прямо на пергамент, с тем учетом, что при выпекании они увеличиваются  вдвое.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3157,'За неимением кондитерского кулька, можно воспользоваться плотным пакетом, один угол которого необходимо срезать, сделав отверстие нужного диаметра, или же воспользоваться столовой ложкой смоченной в масле. Выпекать профитроли при данной температуре около 15 минут, после чего снизить температуру до 180 и продолжать готовить еще 10 минут. Готовые профитроли осторожно раскладываем на блюдо и оставляем остывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3157,'Настало время приготовить крем, для профитролей можно использовать несколько вариантов, взбивая белки с пудрой, или сливочное масло со сгущенным молоком, но особой нежностью отличается заварной крем, от вкуса которого зависит успех профитролей. Для его приготовления требуется вскипятить молоко с сахаром. Пока молоко греться, взбить яйца и прибавить к ним смесь муки и крахмала, немного сахара и чуточку молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3157,'Когда молоко начнет вскипать, влить тонкой струйкой подготовленную смесь при постоянном помешивании. Добавить ванилин на кончике ножа. Когда крем начнет густеть, выключить огонь и оставить остывать. Остывшим кремом наполнить полости в середине профитролей с помощью все того же кондитерского мешка, только уже с длинной и острой насадкой. Украсить поверхность домашних профитролей с заварным кремом каплями помадки или посыпать пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3158,'Слоеное тесто накрыть пленкой и оставить размораживаться. Раскатать скалкой поверх пищевой пленки в тонкий слой. Смешать  два сорта натертого крупно сыра с рублеными сосисками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3158,'Разложить подготовленную начинку на пласт слоеного теста, оставив с одной стороны  отрезок в несколько сантиметров неприкрытый начинкой. Скрутить рулет по направлению к отрезку теста, не прикрытого начинкой. Защипнуть края и стараясь, чтобы рулет лежал швом вниз закрутить по спирали в форме раковины улитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5259,'В течение 40 минут потомить суп в духовке, в конце положить мелко нарезанные помидоры и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3159,'Куриное филе поделить на средние по величине куски, на каждом из которых, сделать неглубокие надрезы по диагонали по отношению к куску. Сбрызнуть мясо подготовленным заранее маринадом, стараясь, чтобы он пропитался в сделанные надрезы, и оставить на полчаса для маринования.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3159,'Прожарить мясо с двух сторон на раскаленной сковороде и поставить в разогретую духовку еще на 15 минут. Горячее мясо переложить на тарелку и оставить, как говорят профессиональные повара – «отдохнуть». Помидор салатного сорта нарезать крупными кубиками. Огурец нарезать полукольцами. Соленый огурец – брусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3159,'Промыть салат и порвать на мелкие куски. Мясо нарезать поперечными брусочками, оставив несколько ломтиков отрезанных тонко по диагонали на украшение. Выложить на блюдо салат, смешанный в миске и полить приготовленной заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3159,'Для заправки смешать сметану 15% жирности, горчицу в зернах, пару капель соевого соуса. По вкусу можно добавить пару капель свежего лимонного сока. Поверх заправки выложить веером нарезанное тонко мясо и половинки помидор. Салат «Пригажуня» с куриным филе готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3160,'Апельсин тщательно промыть и снять с него цедру с помощью специальной терки. Разрезать апельсин пополам и выжать из него сок. Процедить сок от косточек и волокон. Распустить сливочное масло на водяной бане. Яйца взбить, прибавив к ним в процессе взбивания сахар-песок и соль. Прибавить остывшее топленое масло к яичной смеси. Туда же влить процеженный апельсиновый фреш и хорошо взболтать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3160,'Небольшими порциями ввести просеянную пшеничную муку, периодически подливая молоко. Тесто должно получиться жидким, но плотным, для лучшей вязкости необходимо дать тесту постоять минут 15, чтобы из муки выделилась клейковина. Творог перетереть через железное сито или же взбить блендером. Добавить сахар, сметану и продолжать взбивать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3160,'С апельсина аккуратно снять шкурку, помогая себе ножом и разделив на дольки дать немного подсохнуть. Когда тонкая пленка станет хрупкой ее можно счистить, без потери мякоти. Мякоть апельсина нарезать кусочками, освобождая в процессе от косточек. Выпечь румяные, тонкие блины. Дать остыть. На каждый блинчик поочередно выкладывать небольшое количество творога, апельсины и закручивать в рулет. Апельсиновые блинчики с начинкой из творога можно подавать прямо так, а можно разрезать их на роллы по диагонали.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3161,'Растопить маргарин. Соединить его с сахаром, яйцами, солью и содой. Насыпать муку, сделать тесто, которое поделить на несколько частей. Часть поменьше поместить на 15 минут в морозилку. Часть побольше раскатать и поместить на противень, намазать вареньем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3161,'Достать первую часть из морозилки, натереть ее на терке и посыпать сверху начинки. Домашнее печенье «Венское» с вареньем поставить в духовку и выпекать полчаса, соблюдая температуру 180 градусов. Остудить и порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3162,'Выкладывать салат слоями: сначала обжаренный лук с морковью и чесноком. Затем колбаса, порезанная на кубики, майонез. Далее крупно натертый картофель и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3162,'После этого яйца разрезать, достать желток, измельчить и смешать с майонезом. Данной начинкой нафаршировать белки. Выложить яйца вниз начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3162,'Сверху слоеный салат «Сугроб» с колбасой полить майонезом и посыпать сыром. Поставить в холодильник на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3163,'Суп готов буквально влюбить в себя с первой ложки. Этот питательный, ароматный и густой суп, обладающий приятной остротой, способен согреть в холодную погоду. Острым супчик делает перец чили, можно использовать молотый перец. Стоит хоть раз попробовать этот остренький супчик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3163,'Обжарить на масле мелко порезанный лук, помешивая, пока не станет прозрачным. Добавить томатное пюре, довести до кипения и готовить на маленьком огне минуты 3. Использовать именно томатное пюре, а не пасту. Его можно сделать из свежих помидор или приобрести готовое. Добавить в смесь фасоль и перец чили. Если перец свежий, то разрезать его вдоль, убрать семена, измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3185,'Порезать мелким кубиком свежий огурец, яичный белок и рыбу. Добавить рис, мелко нарезанный зеленый лук и кукурузу. Все аккуратно перемешать с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3163,'Все тушить под крышкой минут десять. Добавить в томатную массу бульон, довести до кипения. Немного бульона смешать с кукурузной мукой, перемешать, чтобы исчезли комочки, и влить в суп. Посолить. Если у супчика кисловатый вкус, то добавить немного сахара. Перед подачей или в конце готовки в острый густой томатный суп с фасолью насыпать много измельченной зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3164,'Порезать куриную грудку на маленькие кусочки, освободить от косточек, довести до кипения, накипь снять. Порезать картофель на четвертинки и добавить к мясу, туда же бросить морковь и лук, крупно порезанные.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3164,'Когда все приготовится, немного остудить. Сделать блендером массу похожую на пюре. Насыпать сухарики. Сверху суп-пюре с куриной грудкой и сухариками можно украсить тертым сыром и веточкой зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3165,'Растопить шоколад и сливочное масло и соединить. Можно растапливать на водяной бане или просто на маленьком огне, непрерывно мешая. Также можно воспользоваться микроволновой печью. Добавить сгущенное молоко, все перемешать. В полученный крем насыпать кокосовую стружку и снова все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3165,'Готовый десертный кокосовый крем «Рафаэлло» выложить в стеклянную баночку и поместить на ночь в холодильник или хотя бы на 4 часа. Если крем предназначен для украшения торта, то использовать его сразу. И в украшенном виде дать торту постоять, чтобы он пропитался кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3166,'Отбить грудки, посыпать солью и перцем. Измельчить лук и грибы, немного посолить и поперчить, обжарить на сковороде. Остудить. В отдельной емкости смешать прессованный чеснок и измельченный укроп со сметаной, должен получиться соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3166,'На куриные грудки выложить приготовленную грибную массу, посыпать сыром, мелко натертым. Свернуть мясо в рулетики, заколоть зубочистками и пожарить на сковороде со всех сторон. Готовить, пока не появится корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3166,'Готовые куриные рулеты с сыром и грибами выложить в кастрюлю, полить предварительно приготовленным соусом, тушить минут 20 на очень маленьком огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3167,'Торт состоит из четырех разных коржей: с орехами, какао, маком и изюмом. Смешать все ингредиенты, в один корж положить изюм, во второй – мак, в третий – орехи, в четвертый – какао. В духовке выпечь четыре разных коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3167,'Приготовить крем: сливки или сметану взбить с закрепителем сливок, обычным и ванильным сахаром. Смазать кремом каждый корж.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3167,'Торт «Проще простого» сверху украсить глазурью из смеси топленого сливочного масла с шоколадом. Также можно посыпать тортик тертым шоколадом и орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3168,'Порезать лук на кубики и пожарить на растительном масле до золотистого цвета. Фарш посыпать перцем и солью. Вбить яйцо и 1/2 обжаренного лука. Перемешать и сделать фрикадельки. Потереть морковь на терке и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3168,'Поместить в кастрюлю с водой лук, морковь, посолить. Довести до кипения. Положить в суп фрикадельки, предварительно подготовленные. В это время почистить картофель и порезать его на маленькие брусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3168,'Спустя 7 минут добавить в супчик картофель. Бросить специи по вкусу и лавровый лист. Порезать сырки на небольшие кубики. Когда картофель приготовится, добавить в суп сырки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3168,'Хорошенько перемешать до полного растворения сырков. Спустя три минуты положить в сырный суп с фрикадельками из говяжьего фарша измельченную зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3169,'Сварить картофель. Порезать лук полукольцами, несколько минут обжаривать на растительном масле. Положить грибы и жарить до испарения всей жидкости. Например, можно взять 300 грамм лесных замороженных грибов.  Из картофеля сделать пюре, добавляя горячие сливки. Картофельную массу и грибную объединить. Добавить порезанную мелко зелень, поперчить, посолить. Все перемешать. Получается начинка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3169,'Раскатать тесто, чтобы получился тоненький пласт, порезать его на 3–4 прямоугольника. Из двух листов получается 4 заготовки, если лист один, то его можно разделить на три части. Уложить заготовки на противень по два пласта и выпекать по 12 минут, соблюдая температуру 200 градусов. Тесто должно стать подрумяненным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Чтобы приготовить мясо тушеное с овощами по-татарски можно взять мякоть говядины или баранины, нарезать вырезку крупными кусками по 300 г.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3169,'Положить на противень один корж и смазать его кремом. Посыпать потертым сыром. Положить все слои – сверху положить корж, который уже не промазывать, а просто украсить сыром. Выпекать горячий пирог «Наполеон» с картофельно-грибным кремом минут пять при такой же температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3170,'Обработать творог блендером, добавить приблизительно 100 грамм сметаны. Из творога должна получиться гладкая масса без комочков. Взять яйца, желтки отделить от белков. Взбить белки и полстакана сахара. Добавить к ним постепенно полстакана муки. Желтки взбить с половиной стакана растительного масла. Часть смеси положить в формочку с высокими стенками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3170,'Остальную смесь положить в подготовленную творожную массу. Посыпать солью, насыпать полстакана сахара, ванильный сахар, 1/3 стакана молока. При помощи миксера вымесить массу и аккуратно налить ее в форму сверху первого слоя. Слой первый по краям поднимется.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3170,'Поместить в духовку на 40–60 минут, соблюдая температуру 180 градусов. Торт во время приготовления поднимется и приобретет коричневатый цвет. Достать из печи, намазать смесью из 2 ложками сахара и 50 грамм сметаны. Поставить торт в выключенную духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3170,'Выложить на чизкейк ягоды или фрукты. Можно использовать как свежие, так и консервированные. Приготовить желе: два стакана сиропа, в котором обрабатывались ягоды или фрукты, смешать со стаканом подготовленного предварительно желатина. Залить творожный чизкейк получившимся фруктовым желе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3171,'Крабовые палочки измельчить. Отварить яйца и крупно натереть на терке. Также крупно натереть сыр. Все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3171,'Смешать сметану с майонезом и заправить смесью салатик. Салат «Крем-брюле» должен постоять минут 40.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3172,'Порезать сыр на квадратики по 1,5 сантиметра в толщину. В глубокую емкость разбить несколько яиц и взбить. Во вторую посуду положить панировочные сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3172,'Все кусочки сыра по одному обмакнуть в яйца, после в панировочные сухари, дальше опять в яйца и в сухари. Жарить сыр в панировке по-чешски на большом огне по 30 секунд со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3173,'Порезать кусочки батона на ромбики, со всех сторон обжарить на растительном масле. Крупно потереть свеклу, добавить прессованный чеснок, заправить майонезом. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3173,'Положить массу на обжаренные кусочки батона. Сверху уложить кусочек селедки. Закусочные бутербродики с сельдью и свеклой готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3174,'Помыть картофель, наколоть в 2-3 местах вилкой. Положить картофель на решетку и выпекать до готовности, соблюдая температуру 180 градусов. Готовить примерно 45 минут (в зависимости от размера овоща).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3174,'Мелко натереть сыр, добавить растаявшее масло, майонез и укроп, перемешать. Сформировать шарики. Слегка остудить картофель, сделать крестообразные надрезы. При этом нужно вырезать по 1 сантиметру, не дорезая несколько сантиметров до конца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3174,'Немного раздвинуть картофель и вложить в середину сырный шарик. Перед подачей на минуту поставить картофельный гарнир в духовку или микроволновую печь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3175,'Измельчить луковицу и обжарить на масле. Отварить грибы, добавить к луку, обжарить. Когда грибы станут румяными, насыпать муку, томатную пасту, лавровый листик, посыпать перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3175,'Налить стакан воды, посыпать солью и томить минут десять на среднем огне, время от времени помешивая. Перед подачей подливу из грибного ассорти посыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3176,'Баклажаны нарезать на тонкие круги, приблизительно 5 мм. Посолить и отставить, чтобы выделилась жидкость. Так из баклажанов убирается горечь. Слить жидкость, овощи обвалять в муке и жарить на сковороде, смазанной растительным маслом. Масла на сковороду лить немного, чтобы баклажаны не были сильно жирными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3176,'Отварить небольшую целую морковь, и измельчить ее на терке. Соединить с майонезом и чесноком. На широкое блюдо выложить жареные баклажаны, сверху положить морковную начинку и украсить помидорами черри и свежей зеленью. Закусочные баклажаны с морковью и чесноком готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3185,'В салатницу выложить горкой салат, порисовать майонезом. Притрусить тертым желтком, украсить ломтиками рыбы и красной икрой. Салат «Рог изобилия» с красной рыбой хорош, когда настоится 2 часа на холоде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3177,'Для биточков следует выбирать фарш из птицы и свинины, чтобы был в меру жирным и сочным. Соединить мясной фарш с мелко порезанным луком, добавить специи по вкусу. Поделить готовый фарш на порционные кружочки, обвалять в сухарях или муке и обжарить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3177,'Для приготовления нежного сырного соуса обжарьте сливочное масло с 3 ложками муки. Размешивая влейте в муку молоко, постоянно помешивая, дайте закипеть. Добавьте все необходимые специи. Введите плавленый сырок и оливковое масло. Размешайте соус. Отварить спагетти, выложить сверху горячие биточки и полить сырным соусом. Перед подачей украсьте блюдо свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3178,'Мелко порезать все ингредиенты, сложить в салатницу, кроме сухариков, и добавить майонез. Тщательно перемешать. Перед подачей присыпать сухариками, чтобы сохранить их хруст.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3179,'Смешать манку, сахар, ванилин и залить на 3 часа водой для набухания. Влейте в массу растительное масло, тщательно перемешайте. Затем добавляйте остальные продукты: муку с разрыхлителем, какао. Размешайте тесто до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3179,'На приготовленную форму следует выложить пергаментную бумагу, смазать маслом и вылить все тесто. Поставьте форму для запекания в духовку на 40-50 минут при температуре 180 градусов. Приготовление пирога пробуйте спичкой или деревянной палочкой. Готовый шоколадный манник остудить и украсить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3180,'Порезать очень тонко полукольцами очищенный лук и болгарский перец. Выложить на сковороду, смазанную маслом. Припустить овощи до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3180,'Выложить обжаренные овощи на форму для запекания тонким слоем и залить взбитыми яйцами. Посолить, поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3180,'Сверху выложить тонкие кольца помидоров и притрусить тертым сыром. Простую пиццу без теста запекать в духовке 20 минут в режиме гриля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3181,'Замороженные фрукты, молоко, сироп, лед, яблочный уксус взбейте в блендере до образования пышной пены. Готовый весенний коктейль разлейте по бокалам и украсьте веточкой мяты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3182,'Отварить картофель кусочками и приготовить пюре, слив всю жидкость. Посолить, добавить яйцо и немного взбить венчиком. Затем разложить на мокрое полотенце, аккуратно разровняв края ложкой. Сделайте из картофеля ровный прямоугольник толщиной 2 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3182,'Фарш обжарить на растительном масле с луком. Посолить поперчить по вкусу. Выложить начинку из мяса на картофель. Чтобы аккуратно свернуть, следует приподнять края полотенца и с его помощью скрутить рулет из картофеля с мясным фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3182,'Выложить рулет на противень, подровнять края и проткнуть вилкой по всей поверхности. Смазать взбитым яйцом со сметаной и присыпать тертым сыром. Запекайте рулет в духовке до образования золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3183,'Для приготовления шоколадного десерта следует подогреть молоко до комнатной температуры. Соедините кукурузный крахмал и какао, размешайте в части молока до полного растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3183,'В остальном молоке растворите ванилин и сахарный песок и поставьте на медленный огонь. Когда молоко закипит, помешивая, варите 5 минут. Влейте в кипящее молоко смесь с какао через марлю или сито, чтобы исключить попадания комочков. Венчиком взбивайте массу, пока не закипит.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3183,'Готовый горячий шоколадный пудинг имеет глянцевую поверхность и очень сладкий, когда десерт остынет, его вкус станет более приятный. Разложить пудинг по креманкам и поставить в холодильник. Перед подачей украсить ягодами или взбитыми сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3184,'Приготовить специальную намазку. Для этого взбейте в блендере  сыр майонез, сок лимона, укроп и немного цедры лимона. Разложить лаваш по всей длине и намазать смесь по всей поверхности. Разложить лосось кусочками, тонко нарезанный огурец и рукколу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3184,'Свернуть рулет очень плотно и завернуть в пищевую пленку. Хранить ролл из лаваша с лососем и рукколой можно в холодильнике долго. Перед подачей на стол порезать тонко рулет и выложить на листья салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3185,'В салат входит много морепродуктов, их вкус стоит довести до совершенства. Для этого следует сбрызнуть рыбу и креветки соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Поставить варить, приправив лавровым листом, солью, горошками черного и душистого перцев.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3186,'Куриное филе необходимо разрезать на тонкие пластины и немного отбить. Посолить, поперчить по вкусу. Для курицы по-боярски следует приготовить сырную начинку. Натереть твердый сыр на мелкой терке и смешать с майонезом и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3186,'В середину филе положить немного сырной начинки и свернуть рулетом. Обжарить их на сковороде, смазанной растительным маслом. Затем немного смазать майонезом и присыпать сухарями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3186,'Сложить рулеты на противень и присыпать тертым сыром. Запечь в духовке 10 минут до образования золотистой корочки. Куриное филе с сыром по-боярски подавать с картофелем и овощным салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3187,'В быстрый рецепт шарлотки входит сгущенное молоко. Банку сгущенки взбить миксером с яйцами. Соду и корицу соединить с мукой. Сгущенку и муку соединить и хорошо размешать миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3187,'Яблоки порезать кубиками, уложить в форму для запекания. Залить полужидким тестом и поставить в микроволновку на 10 минут для выпекания. Шарлотку из микроволновки достать, когда остынет,  посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3188,'Отварить говядину и порезать на мелкие кубики. Свежий огурец порезать на кубики, а соленый кружочками. Если соленые огурцы сильно крупные, тогда кружочки разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3188,'Вареную морковь очистить и нарезать кубиками, соединить с фасолью, мясом и огурцами. Все тщательно перемешать и добавить майонез. Выложить готовый салат «Околица» с говядиной в блюдо и украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3189,'На сухой сковороде обжарить лук в течение 1–2 минут. На сковородку у луку выложить порезанные шампиньоны и пожарить на большом или среднем огне. Выложить грибы с луком на тарелку и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3189,'Яйцо с двумя белками взбить вместе с солью, испечь на сухой сковороде блинчик. Готовый блин остудить и порезать на квадратики. Для заправки смешать творог с йогуртом, добавить перец, чеснок, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3189,'Куриное филе отварить, охладить его и порезать на кубики. К мясу добавить грибы с луком и блин. Заправить оригинальный салат «Белковый» творожной заправкой и поставить в холодильник на пару часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3190,'Яйцо с сахаром, солью и ванилином взбить в пену. Добавить молоко, еще раз хорошо взбить. Всыпать постепенно какао с мукой, размешивая тесто миксером. В тесто влить растительное масло или топленое сливочное. Добавить гашеную соду. Дать постоять минут 5–10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3190,'На разогретую без масла сковороду ложкой выложить тесто для одного большого оладушка. Обжарить с двух сторон. Приготовить крем: перемешать яйцо, сахар и муку. Для аромата можно добавить ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3190,'Постепенно тонкой струйкой влить молоко и поставив на плиту довести до кипения, постоянно помешивая. Добавить сливочное масло и хорошо вымесить. Оладушки сложить стопкой и перемазать кремом. Дать пышным шоколадным панкейкам с кремом постоять 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3191,'Картофель помыть, почистить и порезать тонкими кружочками. В форму для запекания выложить слоями картофельные ломтики, каждый слой посыпаем солью, перцем, можно еще посыпать мускатным орехом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3191,'Сверху залить сливками и положить на всю поверхность сливочное масло небольшими кусочками. Тертый сыр нанести на всю поверхность ровным слоем. Поставить форму с картофелем в духовку, нагретую до 180 градусов. Запекать 75 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3191,'Проверить готовность картофеля, проколов вилкой. Если картофель еще твердый, то поставить еще на 15 минут в духовку.  Готовый сливочный картофель, запеченный в духовке украсить мелкопорезанным укропом или петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3192,'Продукты для теста смешать, полученное тесто вылить в форму.  Продукты для начинки смешать, равномерно высыпать на тесто. Выпекать в духовке, лучше всего на нижнем ряду, при температуре 170–180 градусов. Время приготовления 20–25 минут. Готовый кокосовый пирог украсить взбитыми сливками и можно посыпать кокосовой стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3193,'Яблоко, очищенное от кожуры, порезать небольшими кусочками. К муке добавить сахар, соду и взбитые яйца, разбавить кефиром до густоты сметаны. К тесту добавить яблочные кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3193,'Налить масло на разогретую сковородку и выложить ложкой оладушки одинакового размера. Жарить оладушки с яблоком до румяного цвета под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3194,'Бананы выложить в форму для выпечки, залить творожной смесью. В духовку, нагретую до 180 градусов, поставить форму с бананом с творогом и йогуртом и выпекать 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3195,'Масло растопить и немного остудить. Муку просеять. Молоко немного подогреть. Половину муки смешать с дрожжами и высыпать в молоко, вымесить опару.  Опару поставить в теплое место, полотенцем закрыв посуду с ней. Когда опара подойдет в 2 раза, в нее добавить 2,5 яйца, смешанных с сахаром и солью. Всыпать туда же вторую половину муки и вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3195,'К тесту добавить растопленное масло и тщательно вымесить, чтобы оно отлипало от рук. Опять накрыть полотенцем и поставить в тепло. Для начинки мак залить кипятком на 1–2 см выше уровня мака. Перемешать, закрыть крышкой и оставить разбухать на 40 минут. Слить воду с мака, откинув его на сито, подождать минут 5–10, чтобы вся вода стекла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3195,'Мак выложить в кастрюлю, раздавить толкушкой. Добавить мед, сахар.  Когда тесто поднимется в 2 раза, выложить его на посыпанный мукой стол. Из теста сформировать шар, его разделить на 12 одинаковых частей. Каждую часть раскатать в лепешку. Раскатывать не нужно слишком сильно, размер лепешки должен быть ровно такой, чтобы поместилась ложка начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3195,'Положить на лепешку одну столовую ложку начинки и быстро защипать края. Можно вначале защипнуть края вдоль, а потом собрать весь край в «кучку». Булочки сложить на противень, смазанный маслом, шов вниз. Дать булочкам расстояться еще 20 минут. Смазать их смесью из оставшейся половины яйца и ложки молока. Выпекать булочки с начинкой из меда и мака в нагретой до 220 градусов в духовке 18 минут на среднем уровне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3196,'240 грамм шоколада порубить и растопить вместе со сливочным маслом. Сахар, ванилин и яйцо взбить миксером. Яичную и шоколадную смеси смешать вместе.  Муку в отдельной миске смешать с солью и разрыхлителем. Перемешать с яично-шоколадной смесью очень тщательно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3196,'К тесту добавить оставшиеся 150 гр шоколада, порубленные на кусочки, аккуратно перемешать. Выложить тесто небольшими лепешками на противень, застеленный пергаментной бумагой. Шотландское печенье с кусочками молочного шоколада выпекать 12–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3197,'Говядину отварить и нарезать на мелкие кусочки. На сковороду налить немного масла и обжарить кусочки говядины до румяной корочки. Очищенную морковь натереть, поджарить в отдельной сковородке в малом количестве масла. Откинуть в дуршлаг, чтобы стекло лишнее масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3197,'Лук, порезанный полукольцами, тоже обжарить и откинуть на дуршлаг. Огурцы нарезать тонкой соломкой, слить с них лишнюю жидкость. В салатнике перемешать мясо, огурцы, лук и морковь. Добавить для вкуса выдавленный чеснок. Заправить овощной салат с говядиной и чесноком майонезом и, если нужно, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3198,'Замесить тесто из муки, соли и воды. Сделать из теста шарик и оставить прикрытым салфеткой на 15 минут. Нарезать мелко зелень, посыпать солью и размять руками. Перемешать зелень с раскрошенным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3198,'Тесто разделить примерно на 8 частей и раскатать каждую в тонкую лепешку. Начинку выложить на половину лепешки, края половинок слепить. На горячей сухой сковородке выпекать чебуреки. Каждый смазать маслом. Выложить быстрые чебуреки с брынзой на блюдо горкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3199,'Куриное филе нарезать на небольшие кубики и обжарить на сковородке с растительным маслом. Жарить минут 10. Переложить мясо в миску. Шампиньоны тоже порезать, можно пластинками, можно кубиками. Выложить их на ту же сковороду и обжарить. Лук порезать и обжарить либо вместе с грибами, либо отдельно на той же сковородке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3199,'На крупной терке натереть очищенный картофель. Добавить соль, перец. Выложить картофельную массу в форму для запекания, смазанную маслом. Сверху на картофель уложить ровным слоем куриное филе, потом выложить слой грибов, а затем лука. Полить запеканку сливками и поставить в духовку на 30 минут, запекать при 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3199,'Натереть сыр. Через 30 минут приготовления картофельной запеканки с шампиньонами и куриным филе вынуть форму, посыпать сыром и поставить еще на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3288,'Следующий ингредиент – «длинный» рис, все вместе жарить еще 2 минуты. Паэлью с куриными ножками и овощами залить куриным бульоном, тушить около получаса, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3200,'Копченую колбасу нарезать тонкой длинной соломкой. Тонкими кружочками нарезать помидоры. Перец очистить от семян и нарезать кубиками. Головку чеснока очистить и раздавить прессом. Сыр натереть. Отваренные макароны промыть под холодной водой, слить всю воду через дуршлаг. Майонез, кетчуп и чеснок перемешать. Смешать с макаронами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3200,'Выложить макароны в соусе на дно формы. Сверху уложить слоями колбасу, помидоры, перец, сыр. Духовой шкаф нагрет до 220 градусов. Поставить туда форму на 20 минут. Когда пикантные макароны с копченой колбасой в духовке будут готовы, разложить их на порционные блюда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3201,'Из кефира и муки замесить упругое тесто. Убрать его на 40 минут постоять в теплое место. Сделать начинку из тертого сыра, зелени и сырого яйца. Поделить тесто на 2 части и раскатать из каждой большую лепешку, смазать их поверхности сливочным маслом, свернуть в плотный рулет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3201,'Два рулета убрать в холодильник на полчаса. Достать рулеты, отрезать ломтики от них и раскатать в квадратик, на серединку положить начинку. Края завернуть конвертиком. Конвертики на кефире с сыром и зеленью пожарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3202,'Мясо порезать на кусочки размером 2–3 см. Приготовить заправку: лук нарезать полукольцами, морковь тонкими брусками. Можно натереть морковь на терке для корейской моркови. Казан поставить на огонь и сильно – сильно накалить. Налить масло на его дно, чтобы полностью его закрыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3202,'В раскаленное масло выложить лук и зажарить его до золотистого цвета. Выложить мясо в казан. Когда мясо зарумянится, то налить воды так, чтобы прикрыть мясо полностью. Крышкой не закрывать и огонь не убавлять. Жарить пока вода не выпарится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3202,'Добавить морковь и все специи. Жарить пока морковка не станет мягкой. Эта заправка называется зирвак. Заправку аккуратно разровнять и насыпать сверху рис. Не перемешивать и не убавлять огонь, крышкой тоже не накрывать. Налить воды, чтобы прикрыть рис на 4 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3202,'Когда вода практически выкипит, собрать рис горкой, не задевая зирвак. Используя палочку (можно от суши) сделать проколы сквозь рис до дна.  По краям казана налить несколько ложек воды. Закрыть крышкой, убавить огонь до минимума. Через 10 минут перемешать плов с говядиной по-узбекски в казане, собрать горкой и выключить огонь. Дать постоять еще 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3203,'Кальмары очистить и опустить в кастрюлю с кипящей водой на 3 минуты. Вынуть из кипятка и облить холодной водой, порезать соломкой. Также порезать соломкой помидоры. Выдавить через пресс чеснок. Сыр натереть. Перемешать все продукты и заправить салат с кальмарами майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3204,'В жароустойчивой миске смешать сахар, соль, какао и масло. Миску поместить в широкую сковороду с кипящей водой. Мешать содержимое пока масло не растает и масса не станет однородной. Миску вынуть и подождать пока остынет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3204,'Добавить ваниль и яйца по одному. Перемешать. Всыпать муку и опять перемешать до однородного состояния. Похлопать тесто резиновой лопаткой или деревянной ложкой 40 раз. Если хотите брауни с орехами, то добавьте их на этом этапе. Противень накрыть большим листом пергаментной бумаги, так чтобы края бумаги выступали за бортики противня. Духовку нагреть до 160 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3204,'Тесто распределить по противню. Выпекать 20–25 минут на нижнем уровне духовки. Готовность теста проверить зубочисткой. Дать полностью остыть в духовке и потом достать из противня, потянув за концы бумаги. Домашние шоколадный брауни с грецкими орехами нарезать на 12 –15 кусочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3205,'Масло размягчить, положить в разные миски для разных вкусов и посолить. Добавить приправы или травы и перемешать масло лопаткой до однородности. Вкусовые добавки должны равномерно распределиться по всему маслу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3205,'Переложить его на полиэтиленовую пленку. Сформировать из масла ровные цилиндры. Обернуть пленкой и завязать концы на узелок. Поместить масляные смеси для бутербродов в холодильник и охладить, по крайней мере, в течение минимум 2 часов до еды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3209,'В отдельную плоскую тарелку насыпать толченые сухари. Во вторую просеянную муку. Яйца взбить в глубокой мисочке добавив щепотку соли. Заготовленные шницели с начинкой опускать вначале в муку, затем в яичный кляр, и напоследок обвалять в молотых сухарях.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3206,'Яйца размешать, добавить сахарный песок, порошок ванилина и продолжать взбивать, пока масса не станет белого цвета. Сливочное масло размягчить при естественной температуре воздуха и прибавить к яйцам. Взбить смесь миксером на средних оборотах до образования плотной, но воздушной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3206,'Муку просеять через сито, наполняя кислородом и очищая от комков, добавить пакетик разрыхлителя. Подмешать муку к яично-маслянной смеси и замесить вязкое и мягкое тесто. Для того чтобы тесто приобрело необходимые качества, его нужно отстоять пару в часов в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3206,'По прошествии часа-полтора  тесто готово к дальнейшей обработке. Для приготовления песочного печенья можно выбрать несколько вариантов обработки. В первом случае можно просто скатать тесто в жгут и разделив на одинаковые порции скатать из них шарики. Для разнообразия можно раскатать тесто в пласт и вырезать через трафарет разнообразные фигурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3206,'Взбить отдельно белки и промазать ними поверхность печенья, посыпать кристаллами сахара. Выложить на выстеленный пергаментом и смазанный маслом противень и выпекать в течение получаса в разогретой заранее до 180 градусов духовке. Вытащить золотистое, рассыпчатое быстрое песочное печенье и подать его к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3207,'Нежирный творог растереть до исчезновения в нем ярко выраженной зернистой структуры. Прибавить к нему пару ложек сметаны жирностью в 20% или предпочтительно домашнего производства и хорошенько перемешать. В отдельной миске соединить стакан сахара с двумя охлажденными яйцами и немного взбить до растворения кристалликов сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3207,'В творожную смесь ввести растопленное и успевшее остыть сливочное масло. Осторожно ввести яичную смесь в творожную массу. Просеять муку и добавить в нее 5г соли и ложку разрыхлителя. Пекарский порошок можно заменить гашеной содой, но при этом у готовых изделий может сохраниться неприятный щелочной привкус соды. Понемногу подсыпая муку замесить некрутое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3207,'Выпекать творожный кекс можно в большой форме смазанной маслом или в маленьких силиконовых розетках. Готовый кекс из творога можно присыпать сахарной пудрой или полить лимонным соусом, приготовленным на основе свежего сока цитрусовых с добавлением куриных яиц в качестве загустителя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3208,'Мед растопить на водяной бане. Яйца взбить с сахарным песком до растворения крупинок. Просеять пшеничную муку. Один стакан от общего количества, всыпать тонкой струйкой, а яичную массу замесив жидкое тесто. Добавить жидкий мед, соду, гашенную уксусом и поставить тесто на пару минут на водяную баню постоянно перемешивая его силиконовой лопаткой. Тесто должно немного увеличиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3208,'Снять кастрюлю с жидким тестом с водяной бани и досыпав постепенно остальное количество муки, замесить эластичное тесто. Разделить тесто на 6-8 равных частей. Раскатывать тонкие коржи и выпекать их в разогретой духовке. Время выпечки 3-5 минут, готовый корж должен иметь золотистый цвет и быть мягким. Для приготовления крема необходимо хорошо охладить сметану, а так же посуду  которой она будет взбиваться. Добавляя сахарную пудру тонкой струйкой, взбить крем в пышную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3208,'Перемазывая остывшие коржи сметанным кремом собрать торт. Верх и края так же перемазать кремом и разровнять поверхность ножом. Оставшиеся обрезки покрошить мелко руками растирая между ладонями крошки и украсить поверхность медовика. Для того чтобы домашний медовый торт со сметанным кремом таял во рту ему нужно дать время на пропитку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3209,'Сыр и ветчину разрезать тонкими пластинами. Шницели промыть и разрезать пополам, так чтобы образовалось из двух шницелей четыре одинаковых заготовки для приготовления отбитых котлет с начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3209,'Надрезать каждый кусок мяса с одной стороны так, что бы образовался своеобразный карман. Если планируется сначала отбить мясо для большей его мягкости, то надрез делается немного шире, так чтобы мясо можно было открыть как книгу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3209,'Каждый кусочек отбивается изнутри. Для того чтобы мясо не порвалось, его накрывают пленкой или пакетом. Положить на одну половину сыр и ветчину, прикрыв второй. Края защипнуть зубочистками, чтобы при жарке не вытек расплавленный сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5259,'Подавать лучше всего щи по-боярски со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3209,'Переложить заготовки на блюдо и поставить в холодильник на 20 минут. В охлажденном состоянии сухарики будут плотнее прилегать к мясу, образуя при жарке хрустящую корочку. Жарить кордон–блю из свинины с сыром и ветчиной по 6-8 минут с каждой стороны на топленом масле с добавлением растительного.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3210,'Форму с высокими бортами выстелить пищевой фольгой так, чтобы края немного свисали, и при необходимости можно было запечатать блюдо. На выстеленную фольгу выложить тонкие ломтики сала или просто смазать поверхность подсолнечным маслом. Куриные голени промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3210,'Смешать соль, специи, каплю лимонного сока и ложку растительного масла. Натереть этим маринадом мясо, и выложить его в форму. Наличие подсолнечного масла обеспечит мясу сочность и хрустящую корочку сверху. Очищенные клубни картофеля нарезать кружками не очень тонко. Выложить вместе с куриным мясом и посыпать солью и специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3210,'Смешать майонез со сметаной, можно добавить капельку воды. Если соус получился жидким, не переживайте, в процессе приготовления вода частично испариться, а часть ее впитается в картофель придав нежный привкус и структуру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3210,'Залить соусом мясо и картофель, запечатать фольгу и поставить в нагретую до 180 градусов духовку. По истечению 30-35 минут открыть фольгу, давая мясу приобрести золотистую корочку и поставить обратно на 15 минут в духовой шкаф, усилив температуру на 20 градусов. Куриные ножки, запеченные с картофелем в духовке, готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3211,'В закипевший бульон положить стебли петрушки, кожуру от соленых огурцов и дать провариться 10 минут. Процедить бульон и снова поставить на огонь. Очищенный и нарезанный мелкими кубиками картофель всыпать в кастрюлю с бульоном. Туда же добавить промытую рисовую крупу. Варить, время от времени помешивая, что бы рис ни пристал ко дну. Присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3211,'Пока суп готовиться, почистить от кожуры и перетереть морковь, нашинковать лук и обжарить на сковороде до полуготовности. Помидоры окатить кипятком и снять с них кожуру, мелко нарезать и прибавить в сковороду к овощам. Огурцы без кожуры перетереть на крупной терке и так же пересыпать в зажарку. Тушить еще 10 минут. Когда картофель и рис станет мягким из фарша сформировать небольшие фрикадельки и опустить в кипящий суп одну за другой, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3211,'Перед тем как выключить огонь переложить в суп зажарку и рубленый чеснок. Посыпать зеленью. Сразу суп накрывать не нужно, поскольку он должен «подышать» под приоткрытой крышкой. По желанию в завершающей части приготовления, в рассольник с рисом и куриными фрикадельками можно положить пару листиков лаврового листа для насыщенного аромата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3212,'Подготовить кляр. Взбить охлажденное молоко с яйцами. Добавить соль и перец. В отдельное блюдо насыпать просеянную муку. Свинину нарезать поперек волокон. Слегка отбить молотком сначала стороной с крупными зубцами, потом мелкими. Каждую отбивную присолить отдельно. Для того чтобы при отбивании не порвать волокна, мясо можно прикрыть пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3212,'Обмакивать по отдельности куски отбитого мяса, вначале в муку, а затем в кляр. Если кляр слишком жидкий, прибавьте к нему ложку крахмала. Жарить в большом количестве подсолнечного масла на среднем огне. Для тех кто не любит сильно зажаренное мясо можно дополнительно потушить отбивные в казанке добавив пару ложек сливок и немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3212,'Когда жидкость выкипит, отбивные будут на редкость нежными с молочно-сливочным привкусом. Горячие сочные отбивные из свинины в чесночном кляре выложить на блюдо и посыпать рубленой зеленью с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3213,'Подготовить духовку, разогрев ее до 175 градусов. В большой емкости соединить муку, соду, имбирь, разрыхлитель, корицу, гвоздику, перец душистый, 1/2 коричневого сахара и соль. Добавить кленовый сироп, яйцо, яблочный соус, 1/2 растаявшего масла, 1 столовую ложку молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3213,'Положить тесто в кондитерский мешок, можно использовать обыкновенный полиэтиленовый пакет, обрезав его уголок. Смазать маслом формочку для выпекания пончиков и заполнить ее на половину тестом, выдавленным из пакета. Готовить в духовке около 7 минут. Вынуть формочку и вытащить из нее пончики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Достать готовое мясо из бульона, дать остыть и порезать на небольшие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3213,'Масло, которое осталось, растопить в небольшой посуде на небольшом огне вместе с сахаром. Довести до кипения и готовить несколько минут. Налить столовую ложку молока и опять довести до кипения. Насыпать сахарную пудру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3213,'Если глазурь очень густая, то добавить еще оставшуюся ложку молока. Оставляя глазурь на огне, обмакнуть в нее пончики, так как застывает глазурь мгновенно. Получаются очень вкусные имбирные пончики в сахарной глазури к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3214,'Из бананов сделать пюре. Немного взбить яйца. Смешать в емкости муку, молотый имбирь и соду. Насыпать овсяные хлопья и все перемешать. Смешать в сотейнике мед с сахаром. Довести до кипения. Сняв с огня, добавить бананы, яйцо и масло. Налить в смесь из муки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3214,'Прямоугольную формочку смазать маслом и постелить бумагу. Положить тесто. Готовить 60 минут в духовке, соблюдая температуру 170 градусов. Не вынимая из формы, дать печенью остыть, после этого положить его на стол и порезать на квадратики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3214,'Приготовить глазурь: в емкость просеять сахарную пудру, налить чуть-чуть воды. Нужно сделать жидкую, гладкую массу. Полить ею печенье. Украсить бананово-овсяное печенье с медом цукатами или фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3215,'Взбить в большой посуде сахар с маслом. Взбить также молоко с яйцом и экстрактом. Смешать муку с солью и разрыхлителем, медленно добавить в смесь. Накрыть крышкой и поместить на 4 часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3215,'Тесто поделить на две части. Посыпать стол мукой и раскатать обе части толщиной 1/4 дюйма. Взять формочку в виде желудя и с ее помощью разделить тесто на кусочки. Положить на сухой противень (не смазанный маслом).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3215,'Готовить в духовке минут 10, соблюдая температуру 190 градусов. Убрать с противня и охладить. Растопить в микроволновой печи шоколад, перемешать до однородности. Каждое оригинальное печенье «Желуди» намазать шоколадом, украсить орехами пекан. Подождать, пока шоколад застынет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3216,'Нашинковать капусту, почистить картофель и порезать кубиками. Нагреть масло на сковороде, желательно топленое, бросить калинджи, а спустя 15 секунд кинуть карри и асафетиду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3216,'Положить в сковороду капусту и картофель. Закрыть крышкой и тушить. Минут за пять до готовности добавить болгарский перец, порезанный соломкой. Посолить. Жаркое из овощей по-вегетариански необходимо готовить в целом 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3217,'Смешать муку с солью и разрыхлителем и просеять в глубокую посуду. Насыпать сахар и перемешать. Вбить яйца и взбить венчиком. На противень постелить пергамент, смазать его маслом. Положить тесто слоем в 5–7 миллиметров и выровнять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3217,'Выпекать минут 10 минут в горячей духовке, соблюдая температуру 180 градусов. В горячем виде тесто скрутить в рулетик и остудить. Необходимо при этом соблюдать баланс – холодный корж будет сложно развернуть рулет, он будет крошиться, на горячем будет таять начинка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3217,'Приготовить начинку: измельчить халву при помощи крупной терки или ножа. Положить масло и венчиком взбить. Развернуть рулетик, смазать начинкой, вновь свернуть бисквитный рулет с начинкой из халвы и поместить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3218,'Крупно натереть маргарин, насыпать муку, добавить сметану и перемешать. Погасить соду соком лимона. Насыпать сахар и соль. Замесить тесто и положить в холодильник на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3218,'Приготовить 14 яблок небольшого размера, поделить их пополам. Вырезать середину. Почистить шкурку. Тесто разделить на 28 шариков, из каждого сделать лепешку. На лепешку положить 1/2 яблока срезом вверх, свернуть и защипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3218,'Круглую часть намазать белком, посыпать сахаром. Проколоть вилкой. Выпекать домашнее печенье «Румяные щечки» с яблоком полчаса, соблюдая температурный режим 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3219,'Отварить картофель в кожуре, почистить и порезать на куски. Сварить сосиски и порезать. Огурцы порезать на ломтики. Почистить лук и порезать полукольцами. Пучок зеленого лука порезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3219,'Приготовить заправку: перемешать оливковое масло, горчицу и уксус, посолить и положить орегано. Смешать ингредиенты и выложить заправку. Оформить немецкий картофельный салат с сосисками зеленой петрушкой и укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Отварить индейку, нарезать некрупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3220,'Хорошо взбить яйцо и сахар. Поочередно насыпать муку и наливать кефир, чтобы не было комочков: сначала взбить с ложкой муки, а затем с кефиром. Затем снова с мукой и кефиром, пока он не закончится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3220,'Добавить соду или разрыхлитель, гашенный уксусом. Обжарить домашние оладьи для завтрака со всех сторон в большом количестве масла. Переворачивать с помощью двух вилок. Подавать можно с вареньем, сметаной и медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3221,'Крупно натереть сырую тыкву. Муку перемешать с разрыхлителем, солью и корицей. Взбить хорошо яйца, смешать с подготовленной массой, добавить тыкву, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3221,'На противень положить пергамент, смазать маслом, выложить массу, выровнять с помощью лопатки, поставить в разогретую духовку. Готовить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3221,'Достать готовый корж. На стол положить кухонное полотенце, насыпать на него сахарную пудру, перевернуть корж на полотенце, чтобы пергамент оказался сверху. Корж скатать в рулетик вместе с пергаментом, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3221,'Приготовить начинку: взять сливочный сыр, размягченное масло, ванильный сахар, измельченный арахис, сахарную пудру. Все кроме арахиса смешать в емкости, взбить блендером, насыпать арахис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3221,'Развернуть рулетик, убрать пергамент. Выложить равномерно начинку на рулет. Используя полотенце, скатать рулет из тыквы со сливочной начинкой. Перед подачей порезать по 1 сантиметру шириной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3222,'Замесить в емкости тесто из муки, дрожжей, соли, пива, разрыхлителя и оливкового масла. Накрыть емкость с тестом и оставить на 60 минут. Камень для пиццы положить на нижнюю решетку духовки, нагреть до 230 градусов. Вмешать в посуде сливочное масло и чеснок, размять, используя вилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3222,'Растянуть массу в круг, чтобы получился диаметр 30 сантиметров. Выложить его на бумагу для выпекания. Растягивать необходимо постепенно, пока не будет нужный размер. На получившуюся основу выложить получившуюся массу, посыпать сырами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3222,'Тесто с начинкой переложить на камень для пиццы, используя камень. Готовить минут 10, пока не появится корочка и не расплавится сыр. Через 2 минуты после приготовления порезать. Подавать сырные палочки с чесноком на сыре с соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3223,'Перетереть холодное масло с творогом и сахарным песком. Насыпать муку и сразу замесить тесто. Обернуть его полиэтиленовой пленкой и отправить в холодильник больше, чем на 2 часа. Лучше всего оставить в холодильнике тесто на всю ночь. Можно добавить несколько капелек ванильной эссенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3223,'Пока духовка разогревается, раскатать тесто до 3 миллиметров, порезать печенье. На противень постелить специальную бумагу, выложить печенье. Печь печенье из творога для детей минут 10–15, зависит от его величины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3224,'Залить желатин молоком и на 60–90 минут оставить набухать. Подготовленный желатин поставить на маленький огонь, довести до растворения, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3224,'В желатин насыпать обыкновенный и ванильный сахар, размешать до растворения и остудить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3224,'Протереть творог через сито, чтобы получилась пастообразная консистенция. Можно использовать блендер. Добавить в массу из желатина, перемешать и смешать с творожной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3224,'Разделить массу, которая получилась, напополам. В одну часть насыпать какао, размешать. Залить в формочку светлый слой, поставить в холодильник для застывания. Можно поставить форму минут на 20 в морозилку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3224,'Как только светлый слой застынет, налить второй слой и вновь поставить в холод. После того как ванильно — шоколадный десерт из творога застынет, порезать его кусочки и украсить шоколадом или фруктами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3225,'Приготовить не жидкий кляр: смешать яйцо с мукой и молоком, размешать. Молоко добавлять постепенно, пока не получится необходимая консистенция.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3225,'Колбасу с сыром порезать порциями. Окунуть в кляр. Обжарить со всех сторон на растительном масле. Каждую отдельную порцию украсить майонезом, смешанным с чесноком или любым другим соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3226,'В шейкере очень хорошо взбить все ингредиенты. В качестве украшения использовать ломтик ананаса. Подавать коктейль «Голубой гаваец» в специальном бокале.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Отварить порезанный на четвертинки картофель в воде с солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3227,'Порезать мелко лук, обжарить его на масле до прозрачности. Выложить его на дно формочки. Обжарить мясо курицы или индейки, которую предварительно мелко нарезать. Также выложить в формочку. Порезать шампиньоны дольками, обжарить и выложить на куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3227,'Положить на сковороду сливочное масло и обжарить на нем муку до золотистого цвета. По вкусу можно насыпать каких-нибудь травок, перец и мускатный орех. Влить сливки, посолить и все перемешать, чтобы исчезли комочки, вылить на зажарку из лука, грибов и курицы. Потереть сыр и посыпать им сверху соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3227,'Поставить формочку в духовку, выпекать, соблюдая температуру 200 градусов. Все ингредиенты уже приготовлены, поэтому в духовке держать ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3228,'Порезать куриное филе на маленькие кусочки, добавить кефир или майонез. Оставить мариноваться в холодильнике больше, чем на 2 часа, желательно на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3228,'В смесь добавить яйцо, перец, соль, муку и 1/2 луковицы. По густоте должно получиться тесто, как на оладьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3228,'Подогреть сковороду и выложить на нее ложкой куриные котлетки с луком и яйцом, обжаривать по 2 минуты со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3229,'Все хорошо перемешать и залить в формочку. Готовить манную запеканку на кефире минут 30, соблюдая температуру приблизительно 180 градусов',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3230,'Порезать масло на небольшие кубики, выдержав при комнатной температуре. Положить зефир в пол-литровую банку и поставить на полминуты в микроволновую печь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3230,'Зефир станет в несколько раз больше. Его необходимо очень быстро начать взбивать миксером, по кусочку постепенно класть масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3230,'Когда 1/2 масла вмешана в зефир, перестать взбивать и поставить баночку с кремом в холодную воду.  Взбивать дальше, добавляя в массу остальное масло. Зефирный крем для любой выпечки готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3231,'Тесто для булочек делается на опаре. Для этого дрожжи следует развести в теплом молоке. Добавить немного сахара, соли и поставить в теплое место на 20 минут. Мягкое масло взбить с сахаром и яйцом до получения однородной и пышной массы. Затем вылить туда опару, хорошо размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3231,'Добавить в массу теплое молоко и муку, хорошо вымесить и поставить в теплое место тесто, чтобы увеличилось в 2 раза. Когда тесто подошло, его стоит раскатать в пласт толщиной 3-4 см. Сахар смешать с корицей и посыпать пласт теста этой смесью, затем тесто свернуть рулетом и сделать нарезку на порционные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3231,'Выложить тесто на противень, смазанный маслом и поставить на 20 минут в теплое место, чтобы булочки приняли форму и напитались кислородом. Верх необходимо смазать взбитым яйцом. Поставить противень в духовку на 30 минут при температуре 180 градусов. Готовность дрожжевых булочек с корицей проверить спичкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3232,'Смешать яйца, немного сахара, уксус и ложку масла, соединить с мукой и тщательно вымесить тугое тесто. Оно должно постоять при комнатной температуре 30 минут, чтобы ингредиенты соединились и взыграли. Затем это тесто раскатать в очень тонкий пласт и нарезать на тонкие полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3232,'Раскалить сковороду и залить подсолнечное масло. Класть полоски теста во фритюр и обжарить до золотистого цвета. Хворост увеличивается в размере в несколько раз, чтобы убрать лишний жир, его выкладывать стоит на бумажное полотенце. Остывшее домашнее печенье «Хворост» посыпать сахарной пудрой или солью, это на любителя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3233,'Для соления стоит выбирать жирную свежемороженую сельдь или скумбрию. Рыбу необходимо распотрошить и порезать на порционные куски. Для приготовления смеси для натирки рыбы стоит смешать соль, сахар, перец молотый, базилик и укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3233,'В этой смеси стоит хорошо вымокать каждый кусок рыбы и замотать в пищевую пленку на одни сутки. При подаче на стол рыбу, засоленную в домашних условиях, стоит полить растительным маслом, а для аромата сбрызнуть соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3234,'Для приготовления ветчины понадобится мясо с курицы без шкуры. Его необходимо довести до вкуса приправами и солью и высыпать пачку быстрорастворимого желатина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3242,'Для приготовления сыра взять любую форму, в дне которой можно проделать отверстие. Хорошо для этого подойдет пластиковая бутылка. От нее отрезать верхнюю часть с горлышком, а в нижней проделать несколько отверстий ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3234,'Все хорошо размешать и запаковать в рукав для запекания, сформировав тугой рулет. Рулет варить в воде 1 час, затем вынуть и остудить. С холодного рулета снять пакет. Натуральная диетическая ветчина из курицы отлично режется и аппетитно выглядит.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3235,'Утиные грудки следует промыть и просушить. Внимательный осмотр каждого кусочка позволить исключить попадания перьевых оснований в коже. На каждой грудке следует сделать на кожице надрезы, чтобы во время обжарки вышло больше жира.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3235,'Обжарить мясо на раскаленной сковороде до золотистого цвета. Хрустящая корочка придаст мясу отличный вкус и позволит удержать сочность. Обжаренные грудки сложить в противень и накрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3235,'Для приготовления соуса следует использовать сок, что стек во время жарки грудок. Добавить в него апельсиновый сок, вино и выпарить вполовину всю жидкость. Для придания густоты можно добавить порезанный базилик или ложку кукурузной муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3235,'В соус всыпать коричневый сахар, посолить, поперчить и проварить еще пару минут. в конце добавить кусочек сливочного масла. Подавать утиные грудки, порезанные ломтиками и политые густым апельсиновым соусом. На гарнир можно приготовить овощное рагу или запеченные овощи на гриле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3236,'Для теста растереть масло с яйцом и сахарной пудрой, посолить и добавить муку. Вымесить мягкое тесто и поставить на холод, пока будет делаться начинка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3236,'Груши очистить, разрезать на две части, полить соком лимона, притрусить корицей. Для карамелизации груш их стоит засыпать сахаром и залить водой, затем поставить в микроволновую печь на 9 минут. Для франжипана необходимо смешать все ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3236,'Тесто раскатать и выложить в форму, смазанную маслом. Выложить франжипан, сверху груши и оставшийся крем. Поставить вкусный грушевый пирог с франжипаном в духовку на 25 минут при температуре 180 градусов. Проверить готовность спичкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3237,'Замочить и просушить чернослив, а миндаль перемолоть на кофемолке или блендере. Сыр натереть на мелкой терке. Смешать мед, не весь миндаль (отложить 2 столовые ложки), лимонный сок, сыр. Тщательно размешать и скатать в жгутики размером с орех. Обвалять их в молотом миндале и вложить в чернослив.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3237,'Заполненный чернослив обернуть в сырную полоску и завязать перышком зеленого лука. Красиво выложить на блюдо и поставить праздничную закуску из сыра с черносливом в холодильник на 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3238,'Приготовив кофе по-турецки, обязательно стоит немного подсластить. Затем в горячий напиток добавить цедру апельсина и коньяк.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3238,'Охлажденные сливки взбить в пышную пену и добавить к горячему кофе с коньяком и апельсиновой цедрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3239,'Для приготовления соуса развести гранатовый сок, мед и уксус. Через 10 минут следует добавить масло, посолить и поперчить. Затем добавить несколько гранатовых зерен и кольца лука. Разделите соус на две части, одну уберите в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3239,'Рыбу помыть, посолить, поперчить. Уложить лосось в форму для запекания, утопив филе в гранатовом соусе, уберите форму в холодильник для пропитки рыбы на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3239,'Сковороду раскалить и обжарить филе лосося с каждой стороны по 5 минут. Если куски рыбы больше 1,5 см, тогда увеличить время приготовления. Подавать лосось, зажаренный в гранатовом соусе на листьях салата, полив свежим соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3240,'Отварить 4 картофелины в кожуре, очистить и протереть. 12 картофелин очистить и натереть на мелкой терке, сок слить. Все смешать, добавить тертый лук. Добавить специи по вкусу и ложку крахмала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3240,'Фарш посолить, поперчить и хорошо перемешать. Картофельные лепешечки разложить на столе и положить внутрь по ложке мясного фарша. Защипнув края, обжарить на растительном масле до золотистого цвета. Клецки из картофеля со свининой готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3241,'Приготовить тесто для блинов. Отлить половину теста и добавить в него какао и сахар. При жарке блинов, красиво совмещайте два теста, тогда получатся самые неожиданные узоры, которые завлекут детей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3241,'Начинку для полосатых блинчиков «Зебра» может быть самая разная: творог с изюмом, яблоки, варенье или просто масло с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Массу взбить до образования крема, затем вмешать взбитый белок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3242,'Застелить форму марлей и на нее плотно уложить йогурт. Закрыть вторым концом марли и поставить форму в другую емкость, чтобы могла свободно стекать жидкость из йогурта. Поставить в холодильник на 2 дня. Если вы хотите получить более плотную структуру сыра, то после первого дня нужно положить на марлю какой-нибудь груз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3242,'Через 2 дня сыр из натурального йогурта будет готов. Он будет очень нежный и вкусный. Если вы хотите придать блюду пикантность, то сделайте из него шарики и обваляйте в специях, травах, измельченных орехах на ваш вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3243,'Яйца растереть с солью и сахаром. Дрожжи растворить в теплом молоке, его температура должна быть не выше 37 градусов. Дрожжи и яйцо смешать вместе. Добавить муку небольшими порциями. Вымесить тесто. Добавить растительное масло и опять вымесить хорошо. Накрыть тесто полотенцем и поставить в тепло минут на 20–30.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3243,'Обмять тесто, накрыть полотенцем и снова поставить в теплое место примерно на такое же время, чтобы оно поднялось еще раз. Приготовить яблочную начинку. Для нее яблоки нарезать кубиками и засыпать сахаром и корицей. Перемешать.  Потушить яблоки на слабом огне 5 минут, постоянно помешивая. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3243,'От теста отрезать небольшие кусочки, раскатать и выложить в центр яблочную начинку. Соединить у лепешек вначале центр, потом бока, а затем оставшиеся края. Тогда пирожки будут аккуратной формы и не протекут при готовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3243,'Намазать противень растительным маслом, пирожки выложить на него и смазать кондитерской кистью со взбитым яйцом. Пирожки запекать в духовке при температуре 180 градусов. Время запекания примерно 40 минут.  Горячие дрожжевые пирожки с яблоками намазать сливочным маслом, и дать им остыть, накрыв хлопчатобумажным полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3244,'Порезать чеснок плоскими ломтиками, лук измельчить мелко ножом. На сковороде растопить масло и выложить чеснок, лук и добавить к ним один лавровый лист. Убавить огонь и тушить минут 15. В кастрюлю налить 1 литр воды, выложить лук с чесноком и довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3244,'Порезать картофель мелкими кубиками и выложить в кипящий бульон. Суп посолить и варить 15 минут. Вынуть из супа лавровый листик. Налить сливки и блендером разбить пряный сливочно-чесночный суп до пюреобразного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3245,'Мелко порезать грибы и лук. Потушить 15 минут их на растительном масле. Крышку держать закрытой. Если грибы будут получаться суховатыми, то долейте немного воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3245,'Затем положить на сковородку сметану и потушить еще 5–7 минут. Когда соус из шампиньонов со сметаной немного остынет, добавить в него измельченную зелень и взбить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3246,'Взбить для теста яйца с сахаром в течение 3 минут. Добавить к яйцам кефир, масло и гашеную соду. Хорошо взбить. Муку просеять прямо в тесто. На низкой скорости взбить миксером. Творог для начинки перемешать с ванилином, крахмалом, сахаром, яйцом и сметаной. Тщательно растереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3246,'Тесто выложить в форму для выпечки, в середину на тесто положить начинку. Не выкладывать начинку по краям теста! Для украшения можно положить на творог цукаты. Выпекать при 170–180 градусах 40 минут. Готовность пирога проверить на сухую спичку. Остывший пирог с творожной начинкой и цукатами посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3247,'Взять кабачок. Если он молодой, то чистить его не нужно. На крупной терке натереть его. К кабачку добавить яйца и насыпать муку и соль. Вилкой хорошо перемешать, одновременно взбивая, получите жидковатую массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3247,'Вылить ее на раскаленную сковородку, смазанную маслом, закрыть крышкой. Жарить на слабом огне. Потом перевернуть и пожарить на другой стороне. Готовый французский омлет из кабачка можно подать просто так, а можно подать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3248,'На самой крупной терке натереть картофель и цуккини. Выложить всю натертую массу в дуршлаг и дать стечь лишней жидкости в течение 30 минут. Хорошо посолить. Взбить яйца с петрушкой и лимонной цедрой. К ним добавить щепотку соли и перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3248,'Кабачково-картофельную массу выжать через полотенце, чтобы удалить остатки лишней влаги. Добавить к ним щепотку хлебных крошек и яичную смесь. Перемешайте и накройте получившуюся массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Выпекать сливочный пирог с картофелем и рыбой примерно 40 минут, подать горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3248,'Нагреть на среднем огне неглубокую сковороду. Растопить ложку сливочного масла. Выложить ложкой блинчики и обжарьте их с каждой стороны. Подавать блинчики из цуккини и картофеля со сметаной или несладким йогуртом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3249,'Сварить пасту аль денте, как говорит инструкция на упаковке. Слить воду с пасты, оставив 3/4 стакана воды. В большой сковороде на среднем огне растопить 2 столовые ложки масла. Выложить и обжарить половину грибов в течение 7 минут. Переложить в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3249,'Таким же способом пожарить вторую половину грибов. Около 5 минут обжаривать на сковороде лук-шалот до мягкости. К луку на сковороду положить грибы и налить вино. Варить около 3 минут, пока вина не станет в 2 раза меньше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3249,'Долить на сковороду жидкость, оставленную после варки пасты, и выложите оставшееся сливочное масло. Посолите 1 чайной ложкой соли. Огонь на плите убавить до минимума, в сковороду выложить пасту, сыр и петрушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3249,'Перемешайте, чтобы соус покрыл все макароны. Греть пока не растает сыр. Сливочно-грибную пасту с луком-шалот подавать сразу же после приготовления.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3250,'Разрезать баклажаны вдоль, толщина ломтиков должна быть 0,5 см. Обильно посолить и оставить баклажаны на 40–50 минут, чтобы выступила горькая жидкость. Духовку нагреть до 200 градусов. Баклажаны промыть от соли и обсушить бумажной салфеткой и выложить на противень в один слой. Запечь в течение 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3250,'Вынуть баклажаны и остудить. Духовку оставить включенной. В миске замесить вместе сыр рикотта, чеснок и специи. Перемешивать до практически однородной массы. С ломтиков баклажанов снять ножом шкурку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3250,'Взять любую форму с высокими стенками и смазать ее дно и стенки оливковым маслом. Баклажаны выложить так, чтобы они перекрывали друг друга и закрывали стенки формы, оставив один или два ломтика. Выложить сверху начинку из сыра, укрыть оставшимися ломтиками баклажанов. Сверху посыпать тертым сыром. Поставить баклажаны под сыром Рикотта в духовку на 7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'Взять миску, пригодную для использования в микроволновой печи. Выложить в нее белые грибы и залить водой. Накрыть миску пленкой, в которой проделать несколько отверстий для пара. Грибы поставить в микроволновку на 30 секунд на высокой мощности. Вынуть и дать полежать еще 5 минут, чтобы грибы смягчились. Грибы достать из жидкости и порубить. Воду из-под грибов не выливать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'Включить духовку на 220 градусов. Грибы Портобелло выложить на противень ровным слоем и полить равномерно грибы 2 ст. ложками масла. Посыпать грибы 0,5 ч. л. соли и столько же перца. Перемешать. Жарить пока не испарится вся жидкость из грибов и они не сморщатся. Это займет примерно 30 минут. Грибы охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'В это время разогреть на среднем огне 1 ст. л. масла в маленькой сковородке. Пожарить лук, ¼ ч. л. соли и столько же перца до коричневого цвета у лука. Лук переложить в большую миску. В комбайне измельчить шампиньоны и обжарить их в 1 ст. л. масла на сковороде до испарения всей жидкости. Немного убавить огонь и добавить белые грибы, 1 ст. л. чеснока, 1 ч. л. соли и 1 ч. л. перца. Обжарить около 1 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'Налить на сковороду вермут. Варить 2–3 минуты пока жидкость не испарится. Выложить к грибам сливочное масло и дождаться его таяния. К грибам добавить муку и постепенно влить оставшуюся от варки грибов жидкость. Влить молоко и посыпать мускатным орехом. Опять увеличить огонь и вскипятить. Огонь уменьшить и кипятить пока соус не загустеет на медленном огне. Он должен быть как густые сливки. Это займет минут 10–15.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'Соус снять с огня и перемешать с 2 ст. л. петрушки и 1/4 чашки базилика. В миске перемешать 2 вида сыра. В крупную посуду выложить грибы Портобелло с луком.  Листы лазаньи выложить в форму и залить на 5 минут горячей водой. Листы периодически приподнимать, чтобы они не слиплись. Достать листы лазаньи и выложить на полотенце. Форму вытереть насухо и обмазать маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'На дно формы вылить 1 стакан грибного соуса, выложить сверху три листа лазаньи, опять 0,75 стакана соуса, 2 стак. грибной смеси и 3/4 сырной смеси. Так же выложить еще 2 слоя. Сверху прикрыть 3 листами лазаньи и оставшимся грибным соусом.  Фольгу намазать маслом, закрыть ей лазанью. Выпекать лазанью нужно до появления пузыриков, около 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3251,'В это время смешать 2 ст. л. петрушки и столько же базилика с 1 ч. л. чеснока и цедрой. Температуру в духовке увеличьте до 260 градусов. С лазаньи снимите фольгу и выпекайте 7–8 минут, пока сыр не станет пятнисто-коричневым. Вынуть изысканную лазанью с грибным ассорти из духовки и сразу посыпать смесью трав, дать постоять 15 минут и подавать на стол, разрезав на куски.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3252,'Включить духовку разогреваться до 200 градусов. Для теста взбить яйцо и сахар. Добавить муку и перемешать. Выложить тесто на противень, выложенный бумагой для выпечки. Разровнять его поверхность и распределить по всему противню. Бисквит выпекать примерно 12–15 минут до золотистости. Остудить, не снимая с бумаги. Отделить бисквит аккуратно от бумаги. Обрезать края по форме прямоугольника. Обрезки раскрошить в блендере или мелко порезать ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3252,'Бисквит разрезать на 3 равные части, для этого можно воспользоваться линейкой. Чтобы получился длинный и узкий торт, который легко потом режется на отдельные порционные пирожные, режьте поперек противня. Масло взбить для крема, добавить к нему желток, халву, сгущенку. Насыпать сахарную пудру, ваниль. Все взбить миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3252,'Коржи сложить стопкой и промазать кремом. Торт намазать также и с боков и сверху. Разровнять поверхность ножом или спатулой. Крошкой обсыпать сверху и сбоку.  Поставить торт бисквитный «Славянка» с халвой на сутки, чтобы он хорошо пропитался.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3253,'Белки аккуратно отделить от желтков и взбить в густую пену. Взбитые белки отставить в сторону. Желтки и 2 ст. л. горячей воды тоже вбить в пену. Постепенно всыпать сахар-песок и ванильный сахар. Взбивать пока масса не посветлеет. Добавить к желткам лимонный сок и выложить взбитые белки. Перемешать осторожно венчиком, чтобы масса осталась пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3253,'На полученную смесь просеять муку с разрыхлителем. Перемешать и замесить тесто. Форму выложить бумагой для выпечки, влить тесто и разровнять его поверхность. В нагретую до 200 градусов духовку поставить бисквит и выпекать 8 минут. Бисквит остудить прямо в форме. Пропитывать такой бисквит ничем не надо, он будет легким, воздушным и нежным. Поверхность его при выпекании не вздувается.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3253,'Для начинки залить желатин водой и оставить для набухания. Через 30–40 минут распустить желатин на плите. Дать немного остыть в течение 5 минут. Взбить творог с лимонным соком и сахаром. Добавить взбитую сметану и продолжая взбивать ввести желатин. Разъемную форму выложить ровно пищевой пленкой. Положить готовый бисквит, сверху выложить начинку и разровнять ее поверхность.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3253,'Торт поставить в холодильник на пару часов. Для украшения нарезаем апельсины и очищаем от кожуры (или используем любые другие фрукты или ягоды). Выкладываем их на торт, немного придавливаем, чтобы они стали немного утопленными в творожную начинку. Залить сверху желе, приготовленным согласно инструкции на упаковке. Торт бисквитный «Оранжевое настроение» поставить в холодильник на всю ночь для окончательного застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3254,'Яйца, желательно охлажденные взбить, понемногу подливая пиво и молоко. Прибавить щепотку соли и пару столовых ложек сахара. Муку просеять и ввести в смесь, понемногу подсыпая и размешивая, чтобы не было комков, за несколько приемов. Влить в жидкое тесто подсолнечное масло и добавить негашеную соду. Тщательно перемешать. Не стоит сразу приступать к жарке блинов, если накрыть тесто полотенцем и дат немного настояться, результат превзойдет все ожидания. Блины получаться ажурными, нежными и мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3254,'Для того чтобы пожарить первый блин без утрат, в виде прилипшего теста или пресловутого кома, следует смазать абсолютно чистую сковороду кусочком свежего сала, наколотым на вилку. В дальнейшем в процессе жарки можно сковороду не смазывать, поскольку тесто содержит достаточное количество растительного масла, которое выделяться на сковороду при жарке и обеспечивает легкое переворачивание блинов. Наливать жидкое тесто удобнее половником, другой рукой при этом проворачивать сковороду по часовой стрелке держа на весу за ручку, обеспечивая тем самым равномерное распределение теста по всей поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3261,'Вскипятить в кастрюле воду, добавить соль, насыпать стручковую зеленую фасоль, готовить минут 6 до готовности. Кинуть на дуршлаг и помыть в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3254,'Снимая готовые, прожаренные с обеих сторон блины, следует складывать их на тарелку, которую лучше установить на паровую баню, чтобы к окончанию готовки все блины были горячими и мягкими. Блинчики на пиве очень вкусные и сами по себе, что не мешает их употреблять с разными добавками в виде варенья, творога, меда, грибной поджарки или чего душа пожелает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3255,'Разделить грудки цыпленка на восемь одинаковых кусков, каждую из которых по отдельности накрыть пленкой и отбить с обеих сторон. В результате должны получиться тонкие отбивные условно прямоугольной формы. Каждый из мясных заготовок натереть смесью соли с перцем, по желанию можно добавить тертый чеснок или чесночный порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3255,'Мягкий плавленый сыр Хохланд с травами намазать на поверхность будущих мясных рулетов, если данный вид сыра не доступен, можно заменить его мягким сливочным Янтарем добавив к нему мелко изрубленную зелень петрушки, укропа и пару листочков базилика. Кроме того такую же зелень выложить по чайной ложке с одного края мясного пласта с той его стороны, которая будет завернута внутрь рулета. Свернуть, таким образом, все рулеты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3255,'Подготовить кляр из взбитого с солью яйца, отдельно подготовить пару ложек просеянной муки и на другом блюде толченные или молотые сухари. Рулеты должны пройти панировку вначале в муке, затем в яйце и в завершение в панировочных сухарях. После этого следует переложить заготовки на блюдо и поставить в холодильник минут на 20, так сухари лучше укрепятся и панировка не останется на сковороде при жарке. Охлажденные рулеты из грудки цыпленка класть в раскаленное масло и обжаривать со всех сторон до появления приятного аромата и внешнего вида изделия.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'Два стакана пшеничной муки просеять на разделочную доску и сформировать из нее горку. Сделать небольшую лунку, в которую влить стакан ледяной воды и добавить соль и подсолнечное рафинированное масло. Вода должна быть именно ледяная, а не холодная, для этого желательно предварительно поставить ее в морозильную камеру на 20 минут. Руками замесить крутое тесто и отставить его на полчаса, дав время выделиться клейковине, которая и придает тесту эластичность и прочность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'После того как тесто полежало оно становиться значительно мягче. Необходимо понемногу подсыпая муку замесить гладкое и эластичное тесто, которое при нажатии на него пальцем будет моментально восстанавливать форму, не оставляя вмятины. Тесто повторно отставить в сторону накрыв полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'Тем временем подготовить фарш, прокрутив мясо через мясорубку. Лук так же можно прокрутить вместе с мясом или же измельчить с помощью ножа. Для того чтобы фар получился сочным, лук можно отдельно присыпав солью и перцем немного помять, для того что бы он пустил сок. Смешать лук и фарш, добавить молотый кориандр и черный перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'Небольшими порциями подливать в фарш ледяную воду, перемешивая и оставляя массу на некоторое время в покое, чтобы мясо впитало как можно больше воды, это при варке даст изделиям сочный бульон. После того как фарш возьмет нужное количество воды его необходимо проверить на соль и добавить если есть такая необходимость. Поставить фарш на холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'Приступить к изготовлению полуфабрикатов хинкали. Для этого необходимо разделить тесто, на порции разрезав ножом обсыпанным мукой. Кусочек теста раскатать в пласт толщиной чуть более миллиметра. С помощью стакана или рюмки с широкими краями вырезать кружечки теста. Обрезки теста можно перемесить и раскатать вторично.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'С помощью десертной ложки выкладывать на середину фарш и собирая края вверху формировать своеобразный мешочек из теста, в середине которого находиться фарш. Очень важно плотно сомкнуть края, чтобы начинка не выпала наружу при варке. Складок на тесте должно получиться много, а верхушку необходимо прокрутив по часовой стрелке защипнуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3256,'Для варки лучше использовать широкую кастрюлю, варить следует небольшими партиями в соленой воде. После того как хинкали «Три мяса» всплывут, следует проварить их на среднем огне 15-18 минут, после чего аккуратно выловить шумовкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3297,'Желатиновую массу смешать с творожной. Одну треть получившейся массы смешать с какао-порошком, вторую – с крошкой печенья. Оставшуюся часть оставить без добавок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3257,'Куриное филе нарезать брусочками и переложить в емкость с высокими бортиками, желательно не металлическую. Приготовить маринад на основе соевого соуса, который придает мясу нежную структуру и исключительный аромат. Что очень важно, солить мясо не нужно, поскольку соус отдаст столько соли, сколько будет необходимо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3257,'Итак, растворить кристаллики сахара в соевом соусе и добавить немного кунжутного масла. Залить этой смесью подготовленное мясо, встряхнуть и оставить мариноваться, выставив предварительно на холод. Пока мясо маринуется, а это около часа можно приготовить соус к нему.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3257,'Для соуса в сотейник перелить соевый соус, разбавить водой и растворить в этой смеси ложку, полторы мела. Поставить на медленный огонь и помешивая прибавить кетчуп и пару капель соуса чили. Как только соус начнет густеть – выключить огонь. Крахмал смешать с просеянной мукой и панировать в этой смесью куриное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3257,'Обжарить куриное мясо на среднем огне в большом количестве масла, если есть сковородка-вок – это самое оно, в ней мясо получиться с хрустящей корочкой и нежное внутри. Кусочки мяса разложить горкой на подогретой тарелке, полить соусом и присыпать кунжутными семенами. Медовая курочка в кунжуте восхитительное и утонченное блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3258,'Творог протереть и залить кефиром, перемешать до однородности. Ввести яйцо, сахар – песок, добавить щепотку соли и соду. Добавить просеянную муку и замесить некрутое, мягкое тесто. Тесто скатать в шар и накрыть полотенцем, дать ему немного времени расстояться и приобрести эластичность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3258,'Приготовить начинку. Для пирогов по такому рецепту подойдет любая не очень жидкая начинка, это может быть соленый творог с зеленью, жареные грибы с луком, картофельное пюре с луковой поджаркой. При подготовке начинки необходимо немного увеличить количество соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3258,'Для изготовления пирожков можно раскатывать тесто скалкой в пласт и вырезать чашкой кружочки. Так же удобно выдавливать одинаковые шарики теста через большой и указательный палец, руки при этом можно смазать подсолнечным маслом. Каждый колобок теста размять пальцами на ладони в кружок и на его середину положить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3258,'Защипнуть края в форме пирожка. Положить на смазанный маслом стол, швом вверх и немного приплюснуть пирожок ладонью, что бы при жарке тесто в середине не оказалось сырым. Обжаривать пирожки на сковороде при средней температуре. Первую сторону жарить под крышкой, после перевернуть и доготавлиать без крышки. Готовые пирожки из творожного теста на скорую руку сложить в миску и накрыть полотенцем, это необходимо, чтобы они стал мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3259,'Отварить картофель кусочками, слить воду и сбить в густое пюре. При варке можно добавить чуть больше обычного соли. Параллельно обжарить измельченный лук и заправить этой поджаркой пюре. Ввести в остывший картофель сырое яйцо и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3259,'Для начинки можно использовать различные варианты, это может быть отварная протертая печень с луком, измельченное мясо со специями или же отварные яйца с зеленым луком. Из пюре сформировать одинаковые по размеру колобки, каждый из которых превратить в лепешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3259,'На середину лепешки выложить начинку и завернуть по типу пирожков. Лепить зразы удобнее на смоченной холодной водой ладони, так как не столе они могут ломаться. Заготовки зраз панировать в молотых сухарях и обжаривать на сковороде непродолжительное время. Перед жаркой можно охладить зразы в холодильнике. Зразы из картофеля с луком и яйцом можно подавать со сливочным или грибным соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3260,'Выпотрошить карпов, помыть поделить на филе с кожей. Посолить филе рыбы и поперчить. Обрезать у лука-порея перья, вымыть его и на несколько минут положить в кипящую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3260,'В бланшированный лук завернуть рыбное филе и обжарить на гриле со всех сторон по 5 минут. Затем поместить в духовку на 20 минут и готовить при температуре 200 градусов. Сварить рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3260,'Приготовить соус: порезать лук и свеклу на маленькие кубики, припустить, добавив соль и сахар. Добавить томатную пасту и вино, убрать с огня и измельчить блендером. Уложить карпа в луке-порее на рис, вокруг полить соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7718,'Влить нежирное молоко, всыпать какао-порошок и любой сахарозаменитель, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3261,'Приготовить соус: измельчить чеснок, растереть его в ступке с солью, медленно подливать оливковое масло и сок лимона. Заправить фасоль соусом, перемешать и на 25 минут оставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3261,'Тонко порезать сельдерей. Вымыть, посушить и крупно порезать петрушку. В емкость положить два вида фасоли, сельдерей, посыпать перцем и солью, размешать. Подавая салат по-аргентински из фасоли, посыпать рубленой петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3262,'Порезать перец кубиками или небольшой соломкой. Измельчить укроп. Через пресс выдавить чеснок. Потереть сыр. Все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3262,'Порезать лаваш на прямоугольники 10 на 20 сантиметров. На короткий край выложить чуть-чуть начинки. Чтобы сыр не растекался, нужно от верхнего и нижнего края отступить на сантиметр или полтора. Свернуть в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3262,'Положить трубочки на сковороду с разогретым маслом. Обжаривать блинчики с сыром из лаваша со всех сторон по 3 минуты, пока не появится корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3263,'Отварить яйца, измельчить и отдельно поджарить на масле лук и шампиньоны. Салат состоит из шести слоев, каждый смазать майонезом. Первый слой состоит из порезанных копченых окороков. Второй из жареных грибов. Третий слой – это пассированный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3263,'Четвертый состоит из измельченных яиц. Пятый – соленые огурцы, порезанные на кубики. Шестой слой состоит из корейской моркови. Украсить салат «Изабелла» с копченым окороком по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3264,'Обмазать кусочки горбуши приправой, обвалять в муке и поджаривать со всех сторон на масле. Положить рыбу на противень, каждый кусок смазать майонезом, положить кусочек помидора и посыпать натертым сыром. Поместить минут на 15 в духовку. Горбуша с помидорами в духовке под сыром готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3265,'Нагреть духовку до двухсот градусов. Взять шесть формочек для кексов и смазать сливочным маслом. Выдавить чеснок, смешать его с луком, укропом и маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3265,'Раскатать тесто тоненьким слоем, положить на него подготовленную смесь. Скрутить тесто в рулетик и порезать на шесть одинаковых частей. Разложить по формочкам и посолить. Выпекать чесночно-луковые рогалики минут 20.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3266,'Промыть цветную капусту, разделить на соцветия. Красный лук порезать на тонкие ломтики. Накрыть противень фольгой, положить на него капусту, лук, посыпать солью, перцем и карри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3266,'Готовить 45 минут, соблюдая температуру двести градусов. Горох разморозить и смешать с капустой, приправить, сбрызнуть маслом, размешать. Выложить цветную капусту карри, запеченную в духовке,  на тарелку, подавать в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3267,'Из 1/2 муки, дрожжей и воды сделать опару. Когда она подойдет, замесить тесто, добавить остальную муку и поставить в тепло. Порезать лук и поджарить его на оливковом масле, добавить чеснок, пассировать около минуты, положить в поджарку морковный жмых, соль, приправы и замесить тесто. Месить, пока начинка по тесту ровно не распределится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3267,'Скатать три батона продолговатой формы, положить на противень, намазанный маслом. На всех хлебцах сделать надрезы по диагонали. Накрыть влажным полотенцем и на 20 минут оставить. Выпекать морковный хлеб в домашних условиях 15 минут, соблюдая температуру 240 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3268,'Разделить капусту на 8 частей, крупно нарезать зеленые листья лука-порея. Положить на решетку или в паровую корзину, готовить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3268,'Почистить и мелко порезать шампиньоны. Мелко порезать морковь и обжарить на сливочном масле с грибами. В самом конце положить в сковороду мякоть помидоров, порезанных мелко прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3268,'Лук-порей и капусту измельчить и добавить к грибам. Заранее размочить хлеб в молоке, отжать и добавить в массу. Вбить яйца, посыпать перцем и солью, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3268,'Смесь поместить в чашу для риса или в емкость, смазанную маслом. Готовить запеканку из грибов и овощей полчаса. Подавать со сметанным соусом, можно и в горячем, и в холодном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3269,'Маргарин или масло в холодном виде крупно натереть на терке. Перетереть его с сахаром, вбить яйцо. Посолить, медленно насыпать муку, перетереть до однородности. Чтобы бисквит получился хорошим, нужно все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Когда мультиварка подаст сигнал, нужно на помидоры высыпать тертый сыр и рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3269,'Влить кефир, довести до консистенции похожей на густую сметану. Добавить соду. Промыть изюм, заварить в кипятке и добавить в тесто. Смазать формочку маргарином или маслом, присыпать манкой или панировочными сухарями, что имеется под рукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3269,'Готовить минут 40, соблюдая температуру 200 градусов. Чтобы бисквит остывал медленно, оставить его на пять минут в духовке. Когда бисквит остынет, разрезать его на две части и намазать кремом или джемом. Бисквит на кефире посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3270,'Смешать манную крупу со сметаной и оставить на 60 минут, чтобы крупа набухла. Взбить яйца и сахар, налить смесь в манку, перемешать. Насыпать муку с разрыхлителем, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3270,'Вылить в формочку, поставить в духовку. Готовить манник для детского меню минут сорок, соблюдая температуру 180 градусов. Для проверки готовности блюда необходимо проткнуть его зубочисткой. При этом она должна остаться сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3271,'Почистить сырые креветки, предварительно их разморозив. Измельчить их в блендере до однородности. Взбить яичный белок, добавить его к креветочной смеси, посыпать перцем и солью. Перемешать и намазать на хлеб слоем приблизительно 4 миллиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3271,'Сверху присыпать кунжутом, разрезать хлеб по диагонали на четыре части. Получатся треугольники. Налить на сковороду чуть-чуть масла, разогреть ее, положить тосты креветками вниз. Готовить хрустящие креветочные тосты с кунжутом несколько минут на умеренном огне. После этого перевернуть и жарить еще минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3272,'Перемолоть печень на мясорубке, соединить все продукты, испечь блинчики. По вкусу положить начинку, свернуть печеночные блинчики с начинкой из моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3273,'Для приготовления пирога необходимо растопить плитку шоколада в закипающих сливках. До кипения не доводить, хорошо размешать. Растереть творог с яйцами, чтобы не было комочков. Для идеального состояния можно пропустить творог через сито. Затем эту массу разделить на две части, одну сделать поменьше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3273,'В меньшую творожную часть добавить растопленный шоколад, хорошо размешать. Также добавить в каждую часть по 2 ст.л. крахмала. Разогреть духовку до 180 градусов. Форму для выпекания смазать сливочным маслом или выложить бумагой для выпечки. Выложить тесто одного цвета, затем вылить в середину тесто другого цвета и лопаткой сделать круговые движения, по всей форме. Получится цветная фантазия из черно-белого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3273,'Поставить форму в духовку на 40 минут. Разместить в середине духовки, чтобы пирог пропекся со всех сторон одинаково. Готовность проверить спичкой. Когда золотистый пирог испечется, оставить его в выключенной духовке еще на 20 минут. Охлажденный сладкий пирог «Зебра» из творога украсить сахарной пудрой или фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3274,'Огуречный соус готовится на основе сливочного сыра, тертых огурцов, рубленого чеснока, мелко порезанного укропа и жирной домашней сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3274,'Все ингредиенты необходимо размешать. С огурцов предварительно слить лишнюю жидкость. Огуречный белый соус по вкусу довести солью, любимыми приправами, молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3275,'Для приготовления салата необходимо обжарить морковь на смазанной растительным маслом сковороде. Отварить яйца и натереть на крупной терке. Сыр натереть на терке. Мелко порубить чеснок. Отварить куриное филе и мелко нарезать кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3275,'Все ингредиенты смешать, добавить изюм и майонез. Посолить и поперчить по вкусу. Тщательно размешать салат. Выложить на широкую тарелку салат в форме браслета. Киви очистить от кожуры и нарезать слайсами. Выложить фруктовыми кольцами салат «Малахитовый браслет», не оставляя пустого места.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3276,'Картофель очистить от кожуры и промыть под холодной водой. Нарезать дольками, опять замочить в холодной воде. Затем обсушить картофель, промокнув бумажным полотенцем. Взбить белки в пену и смешать с картофелем. Посыпать всеми приправами, специями, хорошо перемешав все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3282,'Сырные лепешки готовятся из кефирного теста. Для этого в кефире размешать соду и дать постоять 2 минуты, пока пройдет реакция. Добавить в кефир тертый сыр, взбитое яйцо и ложку растительного масла. Посолить по вкусу. Добавить муку и вымесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3276,'Разогреть духовку до 200 градусов. Противень смазать растительным маслом. Выложить картофель на горячий! противень, разложить аккуратно, чтобы каждый кусочек соприкасался с поверхностью противня. Выпекать картофель 40 минут при температуре 220 градусов. Золотистые хрустящие кусочки достать из духовки. Картошку, жаренную со специями в духовке подавать со сметанным соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3277,'Фрикадельки готовятся из двух фаршей: индейки и свиного. Добавить к мясному фаршу яйцо и один белок, молотую кинзу, кунжутное масло и острый соевый соус. Хорошо вымесить все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3277,'К смеси добавить чеснок, пропущенный через пресс и приправы по вкусу. Корень имбиря натереть мелко и добавить в фарш. Также изюминкой фрикаделек станет мед, который тоже идет в рецепт приготовления фарша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3277,'Их тщательно вымешенного фарша сформировать небольшие шарики, обвалять их в панировочных сухарях и выложить на противень, смазанный маслом. Выпекать в духовке 20 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3277,'Из половины 1 лайма выдавить сок и смешать с соусом Хойсин и 1 ч.л. соуса Срирача и майонезом. Это традиционный соус со специфическим турецким вкусом пойдет к подаче с фрикадельками. Фрикадельки из мясного фарша по-турецки готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3278,'Тесто для палочек раскатать очень тонко в пласт. В ширину пласт не очень раскатывать. Нарезать ветчину на тонкие и длинные полоски и уложить их по всей ширине теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3278,'Для выпечки стоит выбирать сыровяленую ветчину или хамон. Тесто разрезать на полоски, чтобы каждая полоска была с ветчиной. Затем скрутить спиралью в длинные полоски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3278,'Противень смазать растительным маслом и выложить полоски из слоеного теста, смазать верх палочек взбитым яйцом. Выпекать слоеные палочки с ветчиной 20 минут. Пышные поджаренные и хрустящие палочки идеально сочетаются с любым блюдом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3279,'Спагетти отварить в большом количестве подсоленной воды. Варить стоит точно по времени, иначе переваренными, спагетти могут испортить вкус блюда. Слить воду и добавить немного оливкового масла. Красную рыбу порезать на небольшие кубики и поджарить на сковороде с добавлением растительного масла. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3279,'В сухую сковороду налить сухое вино и немного выпарить, затем добавить к вину тертый пармезан. Сыр можно измельчить блендером или на терке. К сыру влить сливки и веточку розмарина. Смесь кипятить. Консистенция должна быть, как густая сметана. На середину широкой тарелки выложить спагетти, середину полить соусом и сверху выложить красиво кусочки рыбы. Спагетти с пармезаном и семгой готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3280,'Для салата необходимо отварить куриное филе в подсоленной воде. Готовое мясо порвать на длинные волокна, очень аккуратно и не очень мелко. Выложить в салатницу первым слоем. Смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3280,'Чернослив обдать кипятком и порезать на тонкие полоски в длину. Выложить сверху курицы. Смазать майонезом. Свежие огурцы порезать тонкими полосками, посыпать сверху чернослива, затем майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3280,'Яйца отварить, разделить желтки от белков. Белки порезать на тонкие полосочки и сделать четвертый слой, смазать майонезом. Грецкие орехи потолочь и посыпать сверху белка, затем притрусить порубленной мелко зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3280,'Сверху зелени посыпать тертым желтком, смазать майонезом. Украсить салат «Нежность» с куриной грудкой и черносливом полосочками огурца и веточками петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3281,'Для приготовления картофельной запеканки необходимо отварить куриную грудку и обжарить грибы на растительном масле. Мясо порезать на небольшие полоски. Очистить картофель и порезать соломкой в ширину 1 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3281,'Помидор обдать кипятком и снять кожуру. Нарезать соломкой, как картофель. Смешать картофель, помидор, жареные грибы, варенное куриное мясо и сыр. Выложить в форму для запеканки, полить соусом и посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3281,'Для приготовления соуса стоит смешать сливки и яйцо. Посолить и приправить специями. Форму c запеканкой из картофеля с шампиньонами и курицей накрыть фольгой и поставить в духовку на 40 минут при температуре 180 градусов. Затем снять фольгу и выпекать до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8505,'Тонко нарезать лук-порей и стебель сельдерея. Натереть яблоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3282,'От теста отщипнуть шарик и раскатать в небольшую лепешку. В середину положить ложку начинки из рубленного зеленого лука, майонеза и сырого белка. Хорошо защипнуть тесто и немного раскатать скалкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3282,'Раскалить сковороду и обжарить лепешки на растительном масле до золотистого цвета. Сырные лепешки на кефире с зеленым луком очень вкусные горячими, поэтому остывшие лепешки можно всегда поджарить на сливочном масле. Хрустящая корочка от сливочного масла придаст новый вкус и аромат блюду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3283,'Растопить горький шоколад на водяной бане вместе с четвертью чашки кофе эспрессо до однородной массы. Взбить сливочное масло комнатной температуры с сахарным песком до образования воздушной массы. Влить апельсиновый ликер, растопленный шоколад, экстракт миндаля, всыпать молотые миндальные орехи. Продолжать взбивать. Масса должна стать однородной и воздушной. Крем остудить. Отдельно взбить сливки, ввести их порциями в основную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3283,'Дно разъемной формы или глубокой миски выложить печеньем «Дамские пальчики», выпуклая сторона должна быть внизу. Сбрызнуть заготовку смесью воды и ликера. Таким же образом выложить печенье по всей форме, располагая его выпуклой стороной к бортикам. Форму закрыть пищевой пленкой, поставить в холодильник на шесть часов для пропитывания. Края формы снять, подать французскую шарлотку с ликером и шоколадом к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3284,'Растопить и немного остудить сливочное масло. Всыпать коричневый сахар и ванилин из пакетика. Можно использовать обычный сахар, на вкусе блюда это не отразится. Отдельно, с помощью вилки, взбить сырые куриные яйца, соединить их с масляной смесью. Всыпать просеянную пшеничную муку вместе с солью и разрыхлителем. Добавить шоколадные «капли» и сушеную вишню, перемешать, тесто должно быть немного липким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3284,'Прямоугольную форму для выпекания застелить пергаментом, выложить готовое тесто, разровнять и печь в течение 40 минут при температуре 180 градусов. Выпечка должна покрыться румяной корочкой. Вынуть из духовки, нарезать на небольшие квадраты, подавать печенье с кусочками шоколада и сушеной вишней в теплом или холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3285,'Креветки отварить в подсоленной воде с добавлением специй. Продукт остудить, очистить от панцирей. Красный грейпфрут очистить от кожицы и пленок, нарезать дольками. Мякоть авокадо без кожицы тонко нарезать. Промыть и обсушить листья зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3285,'Приготовить заправку из оливкового масла, сметаны, соевого соуса, мёда и дижонской горчицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3285,'Заправку мужно подать отдельно или залить ей креветки с фруктами, перемешать. Салат из креветок с авокадо и грейпфрутом выложить на листья зеленого салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3286,'Сыр «Адыгейский» покрошить или натереть на крупной терке. Вымыть и нарезать кубиками помидоры. Нарубить зелень петрушки, укропа, кинзы, красный лук нарезать. Заранее отваренное куриное филе нарезать кусочками. Все ингредиенты перемешать. Завернуть полученную смесь в тонкий лаваш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3286,'Обжарить лаваш с курицей, помидорами и сыром на сковороде без масла, с антипригарным покрытием, или на гриле. Должна получиться золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3287,'Творог тщательно протереть сквозь сито, можно сделать это два раза. Добавить жидкий натуральный мёд, перемешать, сделать это вручную или воспользоваться блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3287,'Застелить мисочку или чашку пищевой пленкой. Выложить часть готовой массы, затем слой фруктов, очищенных и нарезанных кубиками, сверху – оставшийся творог. Десерт утрамбовать ложкой, поставить в морозильную камеру на 4-5 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3287,'Дно застывшего блюда опустить на минуту в кипяток, аккуратно перевернуть на тарелку. Пленку снять, мороженое из творога с медом и фруктами посыпать нарезанными сухофруктами, какао-порошком, молотой корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3288,'Куриные ножки разрубить пополам, кожу снять. Мелко нарезать репчатый лук, чеснок, порезать мелкими кубиками сладкий болгарский перец и консервированные помидоры без кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3288,'Разогреть на сковороде оливковое масло, обжарить куриное мясо, добавить лук и чеснок, перемешать, потушить еще 3-5 минут. Добавить перец и томаты, обжаривать до выпаривания влаги, затем молотый перец и соль, паприку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3289,'Орехи почистить от шелухи. Ирис порезать на некрупные кусочки и на водяной бане растопить, добавив 5 ложек сливок и коньяк. Снять массу с огня и добавить 2 ложки масла. Перемешать пока масса не станет блестящей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3289,'Смазать маслом маленькие формочки, влить в них расплавленный ирис, вложить в центр целый орех и снова налить сверху ирис. К шоколаду добавить оставшуюся ложку сливок, пол-ложки сливочного масла и растопить на водяной бане. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3289,'Чайной ложкой налить шоколад по центру каждой конфетки в форме. Убрать формочки с конфетками в морозилку на 4–5 часов. Замороженные  домашние конфеты Тоффи с фундуком быстро отделяются от стенок формы, а в тепле становятся мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3290,'Сидр налить в кастрюлю и довести до кипения. Разлить сидр еще горячим по 2 бокалам. Влить в каждый бокал немного сока апельсинов и по 30 мл бурбона. Добавить специи и палочку корицы. И подавать яблочный сидр с бурбоном на стол еще горячим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3291,'Очищенные от скорлупы яйца и креветки мелко порезать. Разрезать оливки на 3–4 части. Горчицу смешать с майонезом и паприкой. К заправке добавить остальные продукты и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3291,'Посолить салат и добавить перец, оставить в холодильнике на час. Перемешать салат из яиц с креветками и оливками и подавать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3292,'Промыть горох. Залить холодной водой и оставить на несколько часов.  Разбухший горох отварить пока он не станет готов (примерно 1 час). Ребрышки порезать на кусочки и положить к отварному гороху, довести до кипения. Картофель порезать крупно и тоже положить к гороху и отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3292,'В это время обжарить на масле лук и морковь, мелко порезанные. Овощи выложить через 15 минут после картофеля. Огонь убавить и оставить томится суп еще 10 минут. Зелень порезать мелко и всыпать. Подать суп гороховый с овощами и копчеными ребрышками на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3293,'В блендер сложить все продукты и взбить до однородности. Подавать молочный коктейль охлажденным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3294,'Все продукты для торта кроме кипятка положить в глубокую миску и перемешать. Тесто взбить блендером. В это время вскипятить воду и не выключать ее. Влить кипяток к тесту и снова перемешать миксером. Тесто станет жидковатым, потому что сахар растворится от кипятка – так и должно быть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3294,'Противень вымазать маслом и вылить на него тесто. Поставить противень в духовку на 40 минут. Температура – 180 градусов. Пока выпекается бисквит, смешать сметанный крем, перемешав сметану и сахар. Готовый бисквит порезать на кубики. Подходящую миску застелить пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3294,'Кусочки бисквита обмакнуть в крем, дать стечь лишнему крему и выложить слоями в миску. Убрать домашний шоколадный торт на кипятке со сметанным кремом в холодильник на пару часов, потом застывший торт перевернуть на сервировочное блюдо и снять с него пленку.  Украсить торт оставшимся кремом или полить шоколадной глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3295,'Снять цедру с апельсина и лимонов, сок выжать в миску. Цедру залить водой, добавить сахар и вскипятить. После закипания огонь убавить и варить 5 минут.  Сироп немного охладить, процедить от цедры и влить сок цитрусовых. Половину клубники и половину сиропа взбить в блендере. Положить в контейнер для заморозки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3295,'Также взбить оставшийся сироп и ягоды. Убрать в холодильник контейнер и оставить на 3 часа. Достать и перемешать массу. Снова поставить на 3 часа в морозилку. Перед подачей на стол клубнично-цитрусовое мороженое без молока достать заранее за 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3296,'Отварное куриное филе порезать в виде соломки.  Болгарский перец и ветчину тоже порезать на тонкую соломку. Залить кипятком изюм на 5 минут, потом воду слить. Обсушить его бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3296,'Слить с грибов жидкость. Если грибы крупные, то порезать их соломкой как остальные продукты. Ананасы порезать, а орехи немного обжарить и порубить на мелкие кусочки. Перемешать все продукты вместе с майонезом. Пикантный салат «Изюминка» с ананасом и грибами готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3297,'Замочить желатин на полчаса в половине стакана холодной воды.Творог, сметану и сахар перемешать и взбить блендером. Молоко подогреть на слабом огне (не кипятить!). Желатин положить в молоко и растворить, непрерывно помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Все перемешать, посолить и заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3297,'Глубокую форму застелить пленкой. Выливать слоями разные по цвету массы (по 2 ложки каждой поочередно). Убрать форму с простейшим шоколадно-творожным десертом в холод на 4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3298,'Овощи порезать соломкой. Зелень покрошить ножом и добавить к овощам.  Сбрызнуть их соком лимона и приправить перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3298,'Завернуть овощи в тонкий лаваш рулетом. Обжарить немного каждый завертыш из тонкого лаваша на тефлоновой сковородке с обеих сторон по паре минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3299,'Покрошить зелень. Рыбу порезать острым ножом на тонкие ломтики. Смазать лаваш тонко сыром и выложить сверху рыбу. Зелень насыпать сверху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3299,'Свернуть рулетом лаваш и на 15 минут убрать в морозилку. Тогда рулеты станут по тверже и их можно будет нарезать кусочками. Рулетики из тонкого лаваша можно сделать с семгой, а можно аналогично с ветчиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3300,'На мясорубке или блендере измельчить готовую гречневую кашу.  Мелко порезать лук. Добавить к фаршу сырым. Перемешать гречку с фаршем и добавить 2 яйца, соль и перец. Вымесить фарш в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3300,'Сформировать котлеты и запанировать их в яйца, а сверху в сухарях. Обжарить с каждой стороны. Можно в конце еще потушить гречаники из готовой каши с куриным фаршем минут 7 в томатном соусе и луке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3301,'Мяту залить в стакане кипятком и оставить на ночь настаиваться. Одну треть мятного настоя перемешать с  2/3 ст. минеральной воды. Добавить лимонный сок и мед. Украсить натуральный энергетический напиток ломтиком лимона или кружочком банана и листиком свежей мяты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3302,'Включить духовку разогреваться до 177–180 градусов. Противень смазать тонко маслом или сбрызнуть спреем против пригорания. Тесто выложить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3302,'Колбасу или сосиски обжарить, убрать лишнее масло бумажными салфетками или пергаментной бумагой. Яйца взбить. Сыр натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3302,'На тесто выложить колбасу или сосиски, залить яйцом и посыпать сыром. Поставить запеканку из слоеного теста в духовку на 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3303,'Порезать на тонкие ломтики одинакового размера колбасу и сыр. Положить стопкой ломтик сыра, колбасы, снова сыра, колбасы и в конце опять сыра. Обвалять в муке, обмакнуть в яйце, и так запанировать 2 раза. Обжарить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3304,'Разрезать капусту на четвертинки и 8–10 минут проварить в воде с солью. Дать стечь воде с капусты через дуршлаг. Смолоть капусту на мясорубке и отжать лишний сок. Лук потереть на мелкой терке. Чеснок измельчить через пресс. Зелень покрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3304,'Перемешать капусту с луком, чесноком и зеленью. Добавить по вкусу соль и перец. Всыпать муку и манку, перемешать до однородного состояния. Из капустного фарша слепить котлетки и обвалять их в сухарях. Обжарить постные капустные котлеты на растительном масле пока не появится корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3305,'К молоку влить воду, посолить. Перелить жидкость в горшочек среднего размера и поставить на сильный огонь. Когда жидкость закипит, всыпать геркулес и зерна овсянки и убавить огонь до средних значений. Непрерывно помешивая, сварить овес.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3305,'Каша',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3306,'Разделить цветную капусту на соцветия и ополоснуть под холодной водой. Сложить соцветия в глубокую кастрюлю и засыпать 2 ч. л. соли. Налить в кастрюлю воды, чтобы она прикрывала всю капусту. Кастрюлю накрыть крышкой и вскипятить воду на умеренном огне. Варить 15 минут. Когда капуста будет мягкой, слить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3306,'Нагреть в сковороде масло. Яйцо взбить с солью в миске. Во вторую миску насыпать сухари. Соцветия капусты обмакивать в яйцах, потом обваливать в сухарях. Выкладывать цветную капусту в панировке на горячую сковородку и жарить до золотистости со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3307,'Посолить сметану и добавить перец, чеснок измельчить через чеснокодавку и выложить в сметану. Перемешать соус. Куриные грудки разложить в противне и полить соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3307,'Сыр натереть и посыпать им грудки сверху. Поставить на 45 минут грудки под сметанным соусом в духовку при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3313,'Приготовить сироп: залить сахар водой, кипятить на плите, пока не пропадет вкус сырой воды. Снимать постоянно пенку. Сняв сироп с огня, добавить масло. В перемолотые семена насыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10243,'Отварить говяжий язык, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3308,'Для салата сделать формочки из фольги. Полоску фольги шириной в 8–10 см свернуть в длину до ширины 1,5–2 см. Всего сделать 5 полосок. Каждую полоску соединить концами, чтобы получилось кольцо. Концы соединить внахлест. Сварить вкрутую яйца. Картошку сварить в мундире и очистить. Слить с рыбы соус и размять ее вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3308,'Остальные продукты потереть на мелкой терке, белок и желток отдельно друг от друга, яблоки предварительно очистить от кожицы и семечек. Салат выложить слоями в формочки. Каждый слой должен быть тонким – примерно 2 мм. Первый слой – половина рыба, ее намазать небольшим количеством майонеза. Далее разложить половину картофеля и смазать его майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3308,'Сверху по половине лука, яичного белка, снова нанести слой майонеза, положить половину яблока и натертого сыра. Нанести майонез и выложить слои из оставшихся продуктов снова в том же порядке.  Посыпать желтком салат в формочках. Порционный салат «Мимоза»  с горбушей поставить в холод. Через пару часов салат можно подавать, предварительно сняв фольгу и посыпав зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3309,'Картофель почистить и срезать плоско у него один конец для устойчивости. Надрезать картофелины вертикально 8–9 раз по всей длине. Посолить, поперчить. Порезать ветчину. Размер ломтиков должен быть таким же, как глубина надрезов на картошке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3309,'Чеснок измельчить через чесночный пресс. Обмазать картофелины чесноком. Ветчину вложить в каждый надрез картофеля. Полить картофель растопленным сливочным маслом – по 1 ч. л. на картофелину. Завернуть картофелины с ветчиной в фольгу – каждую отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3309,'Выложить на противень картофелины в фольге и поставить в разогретую духовку на 45 минут. С готового картофеля развернуть фольгу, посыпать сыром, мелко натертым. Украсить листьями салата блюдо и подать на нем картофель, запеченный в фольге с ветчиной, сыром и чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3310,'Накануне вечером замочить курагу в холодной чистой питьевой воде на полчаса. Воду слить. Курагу вместе с яйцом, ванилином и творогом размолоть в блендере. При этом 50 гр. творога оставить.  Творожную массу с курагой оставить на ночь в холодильнике. За это время творог пропитается вкусом кураги и немного загустеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3310,'Утром творожную массу выложить ложкой, смоченной водой, на противень с пергаментной бумагой. Противень поставить в разогретую до 180 градусов духовку на полчаса. Готовые диетические сырники с курагой полить заправкой. Например, смешать оставшийся творог с водой, ванилином и стевиозидом в блендере. Можно добавить лимонный сок. Вместо творожной заправки использовать йогурт, кефир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3311,'Для основы взбить белки до крепких пиков. Добавить фруктозу и снова взбить. Аккуратно ввести с помощью спатулы измельченный миндаль или муку из миндаля. Тесто переложить в разъемную форму и поставить в духовку на 10–15 минут. Температура в духовке должна быть около 150–160 градусов. Основу остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3311,'Второй вариант основы: 300–400 грамм имбирного печенья истолочь в крошку и перемешать с 50 грамм сливочного масла, для аромата можно добавить немного Бейлиса. Убрать в холодильник пока делается начинка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3311,'Для начинки растопить шоколад на водяной бане. Сливки взбить. Сливочный сыр (предварительно нагретый до комнатной температуры) взбить с фруктозой. Влить ликер и перемешать. Сливки и шоколад добавить к сливочному сыру и перемешать до однородности с помощью комбайна.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3311,'Начинку выложить на основу и разровнять лопаткой. Убрать в холодильник на ночь. Шоколадный чизкейк на миндальной основе украсить какао-порошком или шоколадной крошкой и сливками. Можно по трафарету выложить узоры на поверхности торта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3312,'Замесить дрожжевое тесто и отставить, чтобы поднялось. Раскатать тесто, на одну половину разложить нарезанную колбасу, второй половиной накрыть и порезать на полосочки. Сделать в них дырочку, а потом, как у хвороста. Посыпать сыром. Положить булочки из дрожжевого теста с полукопченой колбасой на противень и отправить в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3313,'Перемолоть семечки, не очищая шелухи, в кофемолке до состояния пасты. Блендер лучше не использовать, так как могут затупиться лезвия. Если нет кофемолки, то подойдет также мясорубка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7989,'Выпекать манные кексы около 50 минут в заранее прогретой до 200 градусов духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3313,'Провернуть смесь через мясорубку второй раз, тогда халва получится воздушной. В сироп добавить пасту, перемешать и выложить в формочку, например, масленку с крышкой. Отправить халву из семечек подсолнуха в холодильник для застывания, положить сверху пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3314,'Крупно потереть кабачки, чуть-чуть отжать лишнюю жидкость. Насыпать к кабачкам муку, молотый перец и соль, вбить яйца. Перемешать, должно получиться тесто, как на оладьи. Смазать маслом сковороду и готовить блины, размазывая по сковороде тесто ложкой, чтобы блины не были очень толстыми. Обжарить блины со всех сторон и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3314,'Соединить майонез с прессованным чесноком, размешать. Порезать помидоры на тоненькие кружки. Намазать блинчик майонезом, разложить на него кусочки помидоров, положить вновь блин и так далее. Верх украсить майонезом, помидором и зеленым луком, порезанным на колечки. Отправить кабачковый торт с помидорами и майонезом на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3315,'С бананов снять кожуру, разрезать на две части, поместить в формочку и сбрызнуть лимонным соком, чтобы не стали темными. Растопить масло. Соединить яйца, творог, мед, масло и блендером смешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3315,'Выложить массу на бананы равномерным слоем. Если необходимо, то добавить чуть-чуть творога. Поместить формочку в духовку и готовить бананы с творогом минут 25, соблюдая температуру 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3316,'Сделать в помидорах с помощью ножа надрезы у основания крест-накрест и несколько минут бланшировать. Дать остыть, очистить кожуру, порезать на крупные куски.  Почистить чеснок и перец, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3316,'Соединить в кастрюле помидоры, чеснок, оливковое масло, перец чили, измельченную петрушку. Поставить на плиту, после закипания посыпать солью, взбрызнуть соком лимона. Готовить томатно-чесночный соус к блюдам из рыбы минут двадцать, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3317,'Разморозить тесто, чуть-чуть раскатать в длину, чтобы толщина получилась миллиметров пять. Порезать на полоски по два сантиметра. Снять оболочку с сосиски. Завернуть ее в тесто по спирали и немного внахлест.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3317,'При желании можно взять сыр. В длину сосиски сделать небольшой разрез и положить в него крупно потертый сыр. Обернуть полоской теста. Застелить противень специальной бумагой и положить на него заготовки. Оставить минут на пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3317,'Взбить чуть-чуть яйца и намазать ими заготовки. Отправить сосиски в дрожжевом тесте в духовку и готовить минут двадцать, соблюдая температуру 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3318,'Хорошо помыть 1 лимон щеткой, порезать на тоненькие кружки. Положить в кастрюльку, насыпать сахар, долить воду. Готовить минут десять. Почистить киви и порезать на кружочки. Выжать в кастрюлю лимонный сок, засыпать сахаром, размешать и положить киви.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3318,'Довести до кипения, налить в емкость из керамики и на ночь оставить. Перелить снова в кастрюльку и готовить минут двадцать помешивая время от времени. Пастеризовать банки, разлить в них варенье из киви с лимоном. Получится приблизительно 1,4 литра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3319,'Помыть кабачки и порезать на полосочки по 0,5 сантиметров. Постелить на противень специальную бумагу, выложить кабачки, намазать чуть-чуть оливковым маслом и посолить. Поместить на семь минут в разогретую духовку, чтобы кабачки стали мягче.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3319,'Порезать куриное филе на тоненькие продольные полоски, чуть-чуть отбить, положить чеснок, посыпать солью и перцем. Размешать и слегка замариновать. На кабачки положить мясо, посыпать базиликом и сыром, положить немного соуса. Свернуть рулетики из кабачка с куриным филе, скрепить шпажками и готовить минут 25, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3320,'Порезать хлеб кубиками. Взбить блендером или в комбайне чеснок и петрушку. Положить туда же пармезан и опять взбить. Добавлять понемногу кусочки хлеба, фарш. Потом яйца, молоко, поперчить смесь и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3320,'Можно сделать этот руками. Порезать хлеб, соединить прессованный чеснок, тертый сыр, измельченную петрушку, все посыпать солью и перцем. Взбить яйца, налить молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3320,'Добавить в смесь, в конце положить фарш. Перемешать руками или воспользоваться вилкой. Сформировать шарики и обжарить домашние фрикадельки из говяжьего фарша на сковороде минут восемь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3321,'Соединить манку с кефиром, насыпать соль, размешать, на тридцать минут отложить. Растереть подтаявшее масло с сахаром. Массу соединить со взбитыми яйцами. Добавить смесь к манной крупе с маслом, размешать. Слегка жидковатое тесто вылить в формочку, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3321,'Готовить минут пятьдесят, соблюдая температуру 160 градусов, так как манник не переносит сильного жара. Чтобы получилась румяная корочка, в конце температуру можно сделать больше. Сверху манник на кефире без муки можно намазать сметаной, выложить яблоки и посыпать сахаром. Снова поместить в духовку минут на десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3322,'Особенно оценят бисквитный шоколадный торт с шоколадной глазурью и кремом любители шоколадных тортов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3322,'Приготовить бисквит: разогреть до двухсот градусов духовку. Формочку смазать маслом сливочным и посыпать мукой. Взбить желтки и половину сахара. Получится светлый пышный крем. Взбить отдельно белки, постепенно насыпать сахар. Должна получиться гладкая масса. Аккуратно, используя силиконовую лопатку или обычную ложку, соединить смеси из желтков и белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3322,'Осторожно насыпать муку, смешанную с какао, хорошо перемешать от краев к середине. Влить по краю растопленное холодное масло и осторожно размешать. Вылить тесто в формочку и готовить тридцать минут. Минут на семь оставить готовый бисквит в формочке, чтоб остыл. Положить на решетку и часов на восемь оставить, чтоб настоялось. Приготовить крем: из холодильника достать масло и положить в емкость, где будет взбиваться крем, и оставить таять при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3322,'Приготовить сироп: соединить в кастрюльке воду и желток, добавить сгущенное молоко. Размешать все и поставить на минимальный огонь. Варить минут пять, помешивая непрерывно. Можно приготовить сироп на водяной бане, но на это уйдет гораздо больше времени. Охладить приготовленный сироп до комнатной температуры. Масло взбить с ванильным сахаром до белого пышного крема приблизительно это займет пять минут. Не переставая взбивать, влить готовый сироп в масло. Затем насыпать какао. Взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3322,'Собрать торт: разрезать бисквит на три коржика. Крем поделить на две части. Первый и второй коржи прослоить. Бока и верх помазать джемом. Если джем с кусочками фруктов, то его необходимо протереть через сито. Остудить, чтобы застыл джем. Приготовить глазурь: растопить масло и шоколад на маленьком огне, не доводя до кипения. Полить традиционный торт «Прага» шоколадной глазурью. Перед подачей дать торту настояться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3323,'Взбить хорошо яйца, кефир и соду. Положить крупно потертую брынзу, муку и масло. Размешать. Переложить в формочку, готовить минут 25, соблюдая температуру двести градусов. Готовность болгарской баницы на скорую руку проверять зубочисткой. К столу подавать сразу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3324,'Приготовить тесто: соединить муку, разрыхлитель и мягкое сливочное масло. Положить остальные продукты и замесить тесто. Завернуть его в полиэтилен. Отправить на полчаса в холодильник. Приготовить творожную начинку: соединить желтки и сахар, положить сметану, ваниль, манку, протертый через сито творог. Тщательно перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3324,'Достать из холодильника тесто, переложить в формочку. Положить сверху начинку. Готовить минут сорок, соблюдая температуру 180 градусов. Достать торт и сверху положить суфле, которое приготовить, взбивая сахар с белками до пиков. Готовить торт «Слезы ангела» с суфле минут двадцать. Достать и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3325,'Взбить сахар и яйца. Соединить и растопить мед и сливочное масло. Положить соду и варить, чтобы масса приобрела насыщенный карамельный цвет. Сняв с плиты, продолжать перемешивать секунд 60. Смешать с яичной смесью. Насыпать муку и замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3325,'Тесто поделить на шесть частей. Сделать из каждой круг и раскатать его. Готовить коржи минуты четыре, соблюдая температуру 170 градусов. По тарелке обрезать лишние края. Готовые коржи накрыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3325,'Приготовить крем: сгущенное молоко смешать с маслом, взбить до однородности. Обрезки измельчить в крошку с помощью блендера. Коржи намазать кремом, посыпать божественный медовый тортик с вареной сгущенкой крошкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Смешать просеянную муку, соду, пекарский порошок, добавить корицу (оставить пол-ложки для глазури), имбирь, соль, гвоздику.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3326,'Обжарить лук и отдельно грибы. Соединить их, положить в салатник. Сделать из майонеза сеточку. Мелко натереть яйца, положить слой, сделать майонезную сетку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3326,'Мелко потереть замороженные крабовые палочки, положить в салатник, сделать сеточку из майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3326,'Мелко натереть сыр, сделать майонезную сетку. Слои ложкой не приминать, тогда получится настоящий нежный салат «Пушинка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3327,'Нашинковать лук, измельчить чеснок, бросить в разогретое масло, обжаривать несколько минут, помешивая. Добавить порезанные помидоры без кожуры, бросить лавровый листик, орегано, базилик, соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3327,'Тушить минут пятнадцать. Чтобы не пригорело, постоянно мешать. Минут через пятнадцать можно бросить базилик. Вылить все в блендер и измельчить до однородности. Лучший соус для приготовления пиццы готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3328,'Курицу или говядину нарезать на кусочки, обжарить с репчатым луком на растительном масле до изменения цвета мяса. Затем посолить, добавить мелко нарезанные соленые огурцы, немного потушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3328,'Добавить нежирную сметану, если смесь получилась слишком густая – долить немного воды. Черный и красный перец, другие специи, соль – по вкусу. Тушить азу из говядины по татарски под крышкой 20 минут, до готовности мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3329,'Свиную шейку нарезать небольшими кусочками. Смешать сахар, уксус, растительное масло, залить лук, порезанный кольцами, на 5 – 10 минут, затем жидкость слить. Пересыпать приготовленным луком мясо и оставить не меньше, чем на пять часов, для маринования. Разогреть топленое масло, обжарить на сковороде мясные кусочки с луком со всех сторон, помешивая, в течение 6 – 7 минут. В конце обжаривания посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3329,'Клубни картофеля очистить, нарезать кружками в полсантиметра, добавить к мясу и жарить 15 – 20 минут при средней температуре. Вымыть и нарезать небольшими кусочками помидоры. Нарезать зелень кинзы. То и другое добавить к мясу и картофелю, тушить под крышкой до готовности еще 15 – 20 минут. Оджахури из свиной шейки с картофелем готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3330,'Смешать в равных пропорциях муку и сахар, добавить какао, молоко, растительное масло, одно сырое яйцо. Масса должна быть однородной. Вылить в чашку, смесь должна наполнить посуду на две трети объема. Печь в микроволновой печи в течение трех минут, быстрый шоколадный пирог должен подняться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3331,'Нагреть молоко до температуры 40 градусов. Небольшую его часть отлить, добавить сахар и дрожжи, поставить в тепло на 15 минут, чтобы дрожжи «заработали».  В оставшееся молоко добавить яйца, сметану, размягченное сливочное масло, соль. Размешать, затем влить готовую опару. Замесить тесто, оно должно быть мягким, липким, поставить в тепло, накрыть тканью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3331,'Приготовить начинку: бараний или говяжий фарш, нарезанный лук и кубики картофеля, соль, перец, специи. Тесто раскатать кружками, выложить начинку и сформовать треугольные пирожки, защипывая от краев к середине. В центре пирожков можно оставить небольшие отверстия для выхода пара.  Перед выпечкой смазать немного взбитым яйцом, посыпать зернами кунжута. Печь эчпочмак с говяжьим фаршем в духовке около часа при температуре 160 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3332,'Для приготовления блюда необходимо луч, чеснок и имбирь мелко порубить. В сковороде разогреть растительное масло и положить в него подготовленные овощи, пассировать до готовности. Когда лук станет мягким и прозрачным, сковороду снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3332,'В отдельной жаропрочной посуде смешиваем все жидкие ингредиенты, добавляем кетчуп и сахар. Все тщательно перемешиваем. В получившуюся заготовку добавляем пассированные овощи, опять все хорошо перемешиваем. Соус необходимо довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3332,'Крахмал растворить в воде. Непрерывно мешая соус, аккуратно влить крахмал. Продолжая помешивать, увариваем домашний кисло-сладкий соус по-китайски до тех пор, пока он немного не загустеет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3333,'В посуду поместить подготовленные фрукты, сахар и корицу, залить все апельсиновым соком. Все ингредиенты тщательно размять и перемешать. Затем добавить вино и бренди, опять все перемешать. Посуду с сангрией герметично закрыть и убрать в холод на несколько часов. Перед подачей удалить из сангрии корицу и добавить газированной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3334,'Начать следует с молока, его необходимо разогреть, но не доводить до кипения. Желтки взбить, аккуратно, чтобы они не сварились, тонкой струйкой добавить к ¼ молока, продолжить взбивать. В отдельной посуде смешать все сухие ингредиенты и добавить к ним получившуюся смесь из молока и желтков. Тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3334,'Не переставая работать венчиком, получившуюся массу добавить в оставшееся молоко. Варить на среднем огне, постоянно помешивая, до загустения. Затем снять с огня и остудить под крышкой, чтобы избежать образования пленки. Бананы очистить от кожуры и порезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3334,'В подготовленную посуду для подачи, слоями выложить печенье, затем бананы и все залить пудингом. Количество слоев зависит от высоты посуды. Украсить банановый пудинг на основе из печенья кусочками бананов и взбитыми сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3335,'Ягоды промыть, при необходимости убрать косточки. В чашу с подготовленной вишней всыпать сахар и оставить на полчаса. Затем всыпать крахмал, все размешать и поставить на плиту. Не переставая помешивать, ягоды варить на не большом огне. Убрать с огня, когда вишневый сок по консистенции будет похож на кисель. Дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3335,'Слоеное тесто заранее разморозить и раскатать с помощью скалки. Толщена теста, не должна превышать 0.5 см, затем порезать на равные части. Каждый квадрат мысленно поделить пополам. На одной из частей, с помощью ножа сделать небольшие надрезы не касаясь края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3335,'На другую часть положить начинку, нарыть стороной с надрезами, чтобы получился треугольник. Края защепить. Слойки с вишней из бездрожжевого теста выложить на противень и выпекать в заранее разогретой духовке в течение 20 минут, при температуре 210 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3336,'В посуде смешать все сухие ингредиенты, вбить яйцо и влить кефир, все перемешать. В кипятке растворить соду и влить в тесто. Выпекать заварные блинчики на разогретой сковороде до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3337,'Нечищеные клубни помыть и высушить. Каждую картофелину сбрызнуть маслом и присыпать солью. Готовить в разогретом духовом шкафу при температуре 200 градусов на протяжении полутора часов. В подготовленный кусок фольги положить чеснок, не очищенный от шкурки, присыпать специями, сбрызнуть оливковым маслом и добавить кусок сливочного масла. Все завернуть и поместить к картофелю за полчаса до его готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3337,'Бекон мелко нашинковать и обжарить без добавления масла. Готовые клубни достать из духовки и дать остыть, затем разделить на две части и вынуть мякоть, аккуратно, не повреждая кожицу. Чеснок очистить. Сыр натереть на терке. Зелень измельчить. В отдельную миску положить все подготовленные ингредиенты, все перемешать. Сыр использовать не весь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3337,'Полученной смесью фаршировать картофель, поверх положить кусочек сливочного масла и присыпать оставшимся сыром.  Готовые картофельные лодочки запекать до образования золотистой корочки в разогретом духовом шкафу. Блюдо подавать рекомендуется горячим, сбрызнув оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3338,'Гранулы желатина замочить в воде, дать набухнуть, а затем нагревать на водяной бане до тех пор, пока желатин не растворится. Все ингредиенты смешать в отдельной посуде, до однородной консистенции. Готовый желатин, постоянно помешивая аккуратно ввести в творожную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3338,'Фрукты или ягоды предварительно помыть и обсушить, если есть необходимость – порезать на дольки. Подготовленную начинку выложить на дно формы и залить получившейся массой. Форму с фруктовым десертом убрать в холод на 1-2 часа, до полного застывания. Через 2 часа фруктовый десерт из творога без выпечки готов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3339,'Куриную грудку разделить на небольшие кусочки, приправить специями и обжарить на сковороде до золотистого цвета. Все овощи помыть, порезать и заправить майонезом. Лаваш смазать кетчупом, затем выложить кусочки куриного филе и подготовленные овощи в майонезе. Лаваш завернуть в конверт. Летняя закуска из жареной курочки в лаваше готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3340,'Лук и грибы нарезать и сложить в сотейник. Пассировать на протяжении 7 мин, затем добавить предварительно нарезанное небольшими кусочками мясо. Готовить еще около 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Картофель со свининой под сыром в мультиварке накрыть крышкой и потомить еще 10 минут пока не расплавится сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3340,'Отдельно смешать горчицу, томатную пасту, каперсы и тимьян. Получившуюся массу добавить в сотейник, залить пол стакана воды и тушить около 30 минут, до полной готовности мяса. Ввести сметану, сливки, довести до кипения и оставить томиться еще на несколько минут. Свинина с пряностями и грибами по–Строгановски готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3341,'Картофель натереть на крупной терке. Затем отжать, чтобы избавиться от лишней жидкости. Смешать с пюре и приправить специями. В отдельной посуде соединить сыр, творог и сливки, добавить мелко нарезанный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3341,'Формируем пампушки. Для этого взять часть картофельного теста и в средину положить ложку подготовленного фарша из творога и сыра. Залепить края. Таким образом, делаем пампушки, пока не кончатся подготовленные ингредиенты. Заготовки обжаривать в масле по 7 минут с каждой стороны. Картофельные пампушки с творогом и сыром готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3342,'В теплое молоко добавить дрожжи, сливочное масло, сахар и соль. В отдельную миску высыпать муку, в нее вбить яйца и вылить теплое молоко с дрожжами. Замесить тесто, смазать его маслом и убрать на некоторое время, накрыв пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3342,'Сыр измельчить. Готовое тесто разделить на несколько равных частей. Настолько же частей разделить натертый сыр. Теперь в середину теста выложить сыр, залепить края. Заготовку положить швом вниз на рабочую поверхность и с помощью скалки раскатать блин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3342,'Хачапури обжарить на сковороде, при этом обязательно прикрыть крышкой, с каждой стороны по 5 минут. Затем, каждую лепешку промазать маслом. Когда хачапури с сыром по–Имеретински из дрожжевого теста немного остынут – порезать их на части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3343,'200 мл жирных сливок довести до кипения, от них отлить 20 мл. В горячие сливки положить поломанный на кусочки шоколад и растопить его. Получившийся ганаш остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3343,'С помощью блендера смешать творог и 1/3 чашки сахарной пудрой, добавить кофе, который предварительно растворить в отложенных сливках. Все хорошо взбить, должна получиться однородная субстанция.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3343,'300 мл сливок смешать с половиной чашки сахарной пудры до образования густой пены. В посуду для подачи укладываем слоями, сначала творожную массу с кофе, затем шоколадный ганаш и завершит композицию слой сладких сливок. Убрать творожное капучино с шоколадом в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3344,'В миске смешать все сыпучие ингредиенты, покрошить в эту миску масло и все размять руками до образования крошек. В растертую муку влить порциями молоко и замесить тесто. На рабочую поверхность присыпать мукой и размять тесто, затем разделить его на прямоугольники одинакового размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3344,'На каждый положить шоколадную дольку, завернуть тесто и прижать края. Заготовки выложить на устланный пергаментом противень и обмазать яйцом. Духовой шкаф разогреть до 200 градусов, готовить булочки на протяжении 20 минут до золотистого цвета. Достаньте хрустящие булочки с шоколадом  из духовки и подайте на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3345,'Все ингредиенты (яйца, крабовые палочки/крабовое мясо и сосиски) измельчить. Лук пассировать и добавить к измельченным продуктам. Все перемешать. Вбить сырые яйца, добавить сухие ингредиенты и майонез. Все тщательно перемешать. Из полученного фарша слепить котлеты и обжарить на разогретой сковороде с добавлением растительного масла. Экономные сосисочные котлеты с крабовым мясом готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3346,'Приготовить кляр, для этого молоко, яйцо и майонез смешать в отдельной посуде и присыпать специями и солью. В полученную смесь добавить просеянную муку и все тщательно перемешать, стараясь не допустить образования комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3346,'Колбасу порезать на прямоугольные кусочки, толщенной 1 – 1.5 см. Колбасные кусочки обмакнуть в кляр и обжаривать на сковороде с разогретым растительным маслом с каждой стороны до образования корочки. Готовые кусочки колбасы в воздушном кляре выложить на бумажную салфетку для того чтобы стекло излишнее масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3347,'Крошки, сахар, мягкое масло смешать в отдельной миске, добавить для аромата немного корицы. Замесить тесто. Форму смазать и утрамбовать масленые крошки на дно формы, таким же образом сделать высокие бортики. Форму поставить в холод на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8075,'Осторожно 5-6 движениями вмешать в фарш.','https:https://st.vkuso.ru/data/cache/thumb/c8/c3fa0bfec897ac8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3347,'Сыр и сгущенное молоко перемешать в посуде с помощью блендера. В получившуюся смесь добавить яйца, ванилин, лимонный сок и щепотку соли. Все тщательно взбить, должна получиться однородная субстанция.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3347,'Крем влить в форму с основой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3347,'Духовой шкаф заранее разогреть до 150 градусов. Будущий десерт готовить в течение 45 минут. Выпечку остудить. В сотейнике смешать крахмал и сахар, влить сок и поставить на огонь. Варить до тех пор, пока соус не загустеет, постоянно помешивая. Остудить. Нежный гранатовый чизкейк полить соусом и убрать в холод на несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3348,'Творог растереть, чтобы избавиться от комочков и добиться однородной консистенции. Добавить мед и все перемешать. Ложкой взять творожную массу, в середину положить орех и скатать шарик. Творожный шарик обвалять в кокосовой крошке. Готовые творожные конфеты с медом убрать в холод на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3349,'Сыр измельчить, с помощью пресса выдавить чеснок. Зелень порубить и смешать с маслом. Все соединить и перемешать. Батон надрезать в нескольких местах и наполнить эти надрезы готовой начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3349,'Нашпигованный батон упаковать в фольгу. Сверток положить в духовой шкаф, заранее разогретый до 200 градусов на 25 минут. По истечению времени фольгу открыть, чтобы образовалась золотистая корочка.  Наш батон с сыром и чесноком готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3350,'Сыр и курицу порезать кубиками. Помидоры разрезать пополам. Чеснок очень мелко порезать или воспользоваться чеснокодавкой. Ингредиенты подготовленные перемешать, добавить соль по вкусу, заправить майонезом. Салат «Аппетит» с сыром готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3351,'Тесто. Сливочное масло растопить (можно в микроволновке) и остудить до комнатной температуры. Соединить сливки и кипяток – должна получиться теплая, но не горячая жидкость. Добавить дрожжи, сахар и перемешать. Оставить на 10-15 минут. Положить соль и муку, еще раз все перемешать. Муки, возможно, понадобится и немного больше – тесто должно быть не липнущее к рукам, но и не очень крутое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3351,'Размешать тесто руками, добавить сливочное масло, собрать его в комок и отставить на 15-20 минут. Дальше взять тесто, вымесить его или в комбайне, или руками (круговыми движениями). Скатать тесто в шар и оставить минут на 30 (накрыть). Обмять тесто еще раз, скатать в шар и отставить еще на 40 минут под салфеткой или полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3351,'Начинка из капусты. Капусту нашинковать, положить в кастрюлю, присыпать солью, влить немного воды. Кастрюлю прикрыть крышкой и жарить на небольшом огне, периодически мешая (10 минут). Затем крышку снять и продолжить тушить, пока вода совсем не выпариться и капуста не будет мягкой, положить немного сливочного масла, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3351,'Начинка из мяса. На сковородку добавить масло, обжарить на нем мелко порезанный лук. Добавить фарш, поперчить, посолить и жарить до готовности. Тесто выложить на стол, поделить его примерно на 30 частей. Из каждой части сделать шарик, а потом раскатать лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3351,'На лепешку положить одну столовую ложку начинки (чередуя капусту с мясом) и соединить края. Пирожки выложить на противень, смазанный маслом. Отставить их на 20 минут. Духовку нагреть до 220 градусов. Пирожки домашние с капустой и с мясом смазать сверху яйцом, выпекать около 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3352,'Муку (2-3 стакана) насыпать горкой, влить воду и посолить. Добавить уксус, немного растительного масла, перемешать и постепенно добавляя еще муки, замесить тесто. Вымешивать его необходимо до тех пор, пока тесто не перестанет прилипать к рукам. Смазать тесто сверху подсолнечным маслом, обернуть в пленку, оставить полежать в теплом месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3352,'Начинка. Изюм промыть горячей водой, сухарики обжарить на сливочном масле. Тонко нарезать яблоки (достаточно будет 2 больших или 4 маленьких яблок), отжать сок лимона. Нарезанные яблоки полить соком лимона, присыпать сахаром и корицей, добавить изюм, сухари и перемешать. Тесто раскатать очень-очень тонко, смазать его растительным маслом, а затем нужно его взять в руки и растягивать, стараясь не разорвать. Чем тоньше тесто, тем вкуснее и хрустящее штрудель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3382,'Положить на решетку и дать застыть. Затем растопить шоколад, окунуть каждую полоску в шоколад, поставить апельсиновые палочки в шоколаде опять на решетку до полного застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3352,'Выложить на тесто начинку, а потом очень аккуратно скрутить рулетом. Из этого количества теста получится 2 рулета. Положить на противень пергаментную бумагу и выложить яблочный штрудель. Сверху полить сливочным маслом (топленым). Выпекать в духовке на небольшом огне 30 минут. Когда сверху зарумянится – вытянуть из духовки. Сильно засушивать не нужно. Готовый хрустящий яблочный штрудель с изюмом присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3353,'Взять емкость, смешать муку, порошок для выпечки, сахар и соль. Во второй емкости смешать молоко, сметану, яйца и ваниль. Добавить сюда же растопленное масло. Все хорошо перемешать и вылить в первую емкость, где смешаны сыпучие ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3353,'Шоколад измельчить на небольшие кубики, добавить в тесто и хорошо перемешать. Выкладывать тесто в формочки для выпекания. Кекс с жидкой шоколадной крошкой выпекать 15-20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3354,'Взбить кефир, сахар, яйца, соду и муку. Консистенция теста, как густая сметана. Далее его поделить поровну на 2 части, в одну из частей прибавить чайную ложку какао. Спечь 2 коржа, охладить и острым ножом разрезать каждый напополам (4 коржа).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3354,'Взбить сметану с сахаром. Коржи смазать получившимся кремом (можно добавить цукаты или орешки). Сверху притрусить какао, дать ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3355,'Смешать маргарин с сыром и перец, добавить нарезанную кубиком курицу и грибы, хорошо перемешать. Раскатать слоеное тесто и нарезать его на треугольные кусочки. На большую сторону теста выложить ложку начинки, скрутить, обернув начинку полностью тестом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3355,'Каждый пирожок окунуть в растопленное масло, обвалять в панировочных сухарях или хлопьях. Выложить курицу с грибами и сыром на противень и запекать 25 минут при температуре 175 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3356,'Необходимо взять крупное плоское блюдо, в его середине установить стакан. Кругом стакана уложить слоями: картофель отварной, курицу копченую, соленые грибы или огурец, зеленый лук, яйца вареные, морковь вареная, сыр с чесноком. Все слои перемазать майонезом, осторожно достать стакан. Украшать салат «Изумрудный браслет» орехами и киви. Салат «Изумрудный браслет» на любой праздник готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3357,'Промыть и очистить от шкурки куриные грудки, нашпиговать их мелко порезанным чесноком, натереть солью и притрусить перцем. Посуду, в которой будут запекаться грудки, смазать растительным маслом, поместить туда мясо, а прогалины между ним заполнить измельченным луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3357,'Залить все сливками (примерно 150 гр., жирность не меньше, чем 20 процентов), чтобы они немного покрыли все ингредиенты. Выжать на сливки половинку лимона. Для обогащения вкуса блюда добавить несколько ложек натертых консервированных помидоров, не смешивая со сливками (но можно и без них).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3357,'Картофель измельчить кружочками, уложить его так сверху, чтобы кружочки не затрагивали помидорные островки. Добавить соль, перец по вкусу. Поместить в разогретую духовку (200 градусов), лучше на решетку, немного ниже среднего уровня. Запекать около 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3357,'Потом достать из духовки, щедро присыпать натертым сыром. Поместить в духовку еще на 15 минут, сыр за это время зазолотится. Сочное и нежное блюдо, куриные грудки в сливках запеченные под сыром, готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3358,'Размять банан, чтобы получилось пюре, добавить размягченное сливочное масло и коричневый сахар, перемешать. В отдельной емкости взбить яйцо и добавить к полученной смеси. Присоединить муку, перемешать, затем добавить овсяные хлопья, перемешать еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3358,'Добавить к смеси шоколад. Взять две ложки и с их помощью скатать шарики, положить печенье на противень. Выпекать 20 минут (180 градусов). Охлаждать домашнее овсяное печенье с бананом и шоколадом на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3359,'Орехи и печенье измельчить в блендере, чтобы получилась мелкая крошка. Перемешать с растопленным маслом и корицей. Дно разъемной формы выстлать пергаментной бумагой (необходимо вырезать круг из бумаги, который будет совпадать по размеру с дном формы). Выложить на бумагу смесь печенья с орехами, хорошо разровнять руками, сделать не высокие бортики (примерно 2 см.).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3459,'Заправка: перемешать йогурт, горчицу, тертый чеснок, майонез, мелко порубленный лук (зеленый), перец и соль по вкусу. Яйца и помидоры положить в емкость, полить заправкой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3359,'Для начинки смешать в отдельной емкости творог, семена из стручков ванили, сметану, яйца и сахар. Взбить блендером, затем чтобы вышла однородная, гладкая масса. Если творог с крупинками, то его нужно перетереть через сито. Выложить творожную начинку на слой из печенья, сверху накрыть полотно фольгой и выпекать примерно час при 170 градусах. Потом сбросить фольгу, убавить температуру до 160 градусов и печь опять минут 20.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3359,'Масса при этом схватиться и по бокам немного зарумянится, серединка останется нежной. После выпекания творожный чизкейк оставить в духовке до абсолютного остывания, для того, чтобы он не потрескался. Потом поставить десерт в холодильник – там окончательно сформируется текстура десерта. Творожный чизкейк с грецким орехом готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3360,'Йогурт перемешать с 2 столовой ложкой меда, другую ложку необходимо оставить, и ванилью. Взять 6 бокалов, в них выложить слоями йогурт, миндаль, ананас, киви, йогурт, киви, ананас и миндаль. Сверху парфе с ананасом и киви сбрызнуть медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3361,'Яйца перемешать с крахмалом, мукой, майонезом, перцем и солью. Отсыпать немножко теста и перемешать его с зеленью. На противень положить бумагу для выпечки и тесто без зелени вылить на него. Чайной ложкой выкладывать тесто с зеленью. Порезать оливки и положить их на тесто. Запекать в духовке минут 7-10 (180-200 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3361,'С противня перевернуть тесто на бумагу – снизу должна оказаться сторона с оливками. Смазать сыром, затем выложить икру, филе рыбы, взбрызнуть соком лимона. Завернуть рулетом и поставить в холодильник на 2 часа. Закусочный рулет «Тигровый» с красной рыбой готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3362,'Взять орехи, если они не лущеные, то необходимо аккуратно расколоть скорлупу, лучше всего воспользоваться орехоколом. Очень внимательно нужно отделить ядра от осколков и пленок. Поставить сковороду на небольшой огонь, разогреть, всыпать половину сахара, постоянно перемешивать, когда сахар начнет плавиться, понемногу всыпать вторую половину сахара, продолжая помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3362,'После того, как весь сахар расплавится, добавить сок лимона и продолжать перемешивать, пока сахар совсем не растворится и данная смесь не закипит. Нужно внимательно следить за цветом карамели. Если сковородка темная, то можно воспользоваться листом белой бумаги. Масса вначале будет светло-желтой, а дальше будет темнеть. Чем темнее становится карамель, тем более выраженным будет привкус жженого сахара. Довольно будет довести карамель до светло-коричневого цвета и можно всыпать орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3362,'Огонь уменьшить до минимума, чтобы карамель не пригорела. Все хорошо перемешать, чтобы орехи равномерно покрылись карамелью, и прожарить их минут 5. Разостлать на столе пергамент, выложить на него орехи в карамели и равномерно разровнять. Оставить остывать на столе. Грильяж из грецких орехов – вкусное лакомство как само по себе, так и очень хорошо дополняет горячий чай или кофе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3363,'Для теста взбить маргарин (размягченный) с сахаром, добавить сметану. Далее добавить муку с содой. Перемешать. Замесить эластичное тесто, потом поделить его на 4 части. Каждый шарик раскатать в круг толщиной около 1-1,5 см. и запечь в подогретой до 200 градусов духовке 10 минут. Если противень большой, то можно все заготовки спечь за один раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3363,'Для крема жирную сметану перемешать с сахаром и взбить до пышности и густоты. После того, как коржи остынут, можно начинать собирать торт. На первый корж намазать крем и уложить слой из очищенных мандаринов, сверху их покрыть кремом. Уложить второй корж, покрыть его кремом, далее кусочки ананаса и покрыть их кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3363,'Тоже самое сделать и с третьим коржом, использовать киви. Далее положить четвертый корж и полить его толстым слоем крема. Обмазать бока торта и все хорошо разровнять. Готовый торт украсить по своему желанию (тертым шоколадом или конфетами, фруктами или шоколадной крошкой). Обязательно сметанный торт с фруктами нужно поставить в холодильник, чтобы торт хорошо пропитался.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3381,'Потушить еще минут 5 или 10. Отварить картофель в подсоленной воде. Потом слить ее, но не всю, а немного воды оставить на дне. Хорошо картофель помять, когда она уже будет хорошо размята, добавить туда молоко горячее, масло и соль по вкусу. Мясной гуляш с подливкой и картофельным пюре, как в садике можно подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3364,'В посуде соединить масло, ванильный сахар и сахарный песок, все очень тщательно взбить, масло должно стать белого цвета. Яйца вбить по одной штуке. Отдельно смешать муку, соль, разрыхлитель и порциями ввести в яично-масленную смесь, все перемешать, стараясь избежать образования комочков. Форму необходимо заранее подготовить, а именно промазать маслом и припорошить мукой. Готовое тесто поместить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3364,'У яблок удалить середину и счистить кожицу. Разрезанные на тонкие дольки яблоки положить на тесто и присыпать коричневым сахаром. Готовить десерт в духовке, установив температуру 180 градусов, на протяжении 15 минут, заготовку посыпать орехами и убрать допекаться еще на 15 минут. Пирог с яблоками и орехами будет готов тогда, когда образуется золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3365,'Муку, сахар, какао и ванилин соединить в отдельной посуде, затем, в сухую смесь добавить молоко и растительное масло, смешать все ингредиенты. В отдельной миске взбить яйца и ввести их в тесто. Заготовку выпекать в течение 40 минут, при температуре 180 градусов. Готовый ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3366,'Куриные сердца на некоторое время замочить в воде. Лук нашинковать полукольцами, зелень измельчить, все присолить и размять руками с добавлением ложки оливкового масла. Молодой картофель хорошо промыть, не счищая кожуры, порезать колечками, затем обжарить на масле до образования румяной корочки. Сердца помыть и разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3366,'Потушить в течение 10 минут на сливочном масле вместе с грибами. В форму, выложить слоями, сначала обжаренный картофель, затем лук, а потом сердечки с грибами, все посыпать сыром. Яйцо взбить, но не сильно, добавить сметану, посолить по вкусу. Этим соусом полить запеканку. Форму поместить в духовой шкаф, готовить 15 минут, при температуре 200 градусов. Запеканка с сыром по-деревенски готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3367,'Курицу сварить с добавлением лаврового листа и луковицы, бульон немного посолить. Готовить ее следует долго, мясо должно хорошо отделяться от кости. Рис замочить. Яйца сварить в крутую. Для приготовления соуса в сотейнике необходимо растопить пару ложек сливочного масла, всыпать муку. Разогретые сливки аккуратно влить в сотейник, постоянно, помешивая. Готовый соус посолить, специи добавить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3367,'Курицу остудить, отделить мясо и порвать на мелкие кусочки. Рис сварить на курином бульоне. Луковицу нашинковать, шампиньоны измельчить, все пассировать на сковороде с растительным маслом, в конце добавить зубчик чеснока. Керамическую форму смазать маслом. Основой пирога будут блины. Теперь слоями выложить подготовленные продукты, сверху каждого слоя прослойка из блинов. Сначала выложить рис и полить его растопленным маслом. Затем, порезанные яйца, полить их куриным бульоном, потом слой курицы, политой соусом, сверху слой грибов так же под соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3367,'Крышкой пирога будут блины, политые растопленным маслом. Форму накрыть фольгой и убрать в духовой шкаф на 30 минут, готовить при температуре 180 градусов. Через 15 минут фольгу снять. Готовый пирог вынуть из духовки и немного остудить. Разделочную доску положить сверху и все вместе перевернуть. Форму снять. Блинный курник с грибами и курицей порезать порционно и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3368,'Куриные яйца взбить с сахарным песком и ванильным сахаром. Теплый кефир присоединить к яично-сахарной смеси, добавить топленое масло. Все сухие продукты смешать и присоединить к жидким. Слегка перемешать ингредиенты, но тесто не замешивать. Затем дать тесту отдохнуть, по консистенции оно должно быть схоже с густой сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3368,'Сковороду очень сильно разогреть и смазать маслом, затем огонь уменьшить. Тесто, с помощью ложки выложить на сковороду, оставляя расстояние между оладьями. Когда с одной стороны ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3369,'Куриное филе порезать на небольшие кусочки и не сильно отбить, затем обжарить на сковороде с добавлением капли масла. Если для приготовления блюда используются куриные бедрышки или крылышки, отбивать их не надо. Для соуса, соединить вино, соевый соус и мед, все тщательно перемешать до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3418,'Половину готовой начинки выложить на середину круга из теста. Плотно скрепить края, чтобы начинка не вытекала. То же самое сделать и со вторым диском из теста. Выпекать кальцоне с творогом и шпинатом 15-20 минут до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3369,'Когда куриные кусочки приобретут золотистый оттенок, в сковороду влить весь соус, готовить на сильном огне в течение 15 минут постоянно перемешивая. К готовому блюду в качестве гарнира отлично подойдет рис. Его нужно выложить на тарелку, сверху положить курицу и все полить соусом, для пикантности, блюдо можно присыпать кунжутом. Курица в соевом соусе с вином и медом по-японски готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3370,'Для приготовления данного рецепта следует подобрать картофель одинакового размера. С помощью ножа, в каждом клубне вырезать середину и подрезать донышко, картофель должен устойчиво стоять. Для приготовления начинки, мясной фарш посолить по вкусу, присыпать специями и добавить мелко нашинкованный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3370,'Готовой начинкой нафаршировать картофель. Клубни плотно установить в сотейник, до половины налить воды и варить до полуготовности. Морковь и лук нашинковать, пассировать на растительном масле, с добавлением томатной пасты. Готовую заправку добавляем к картофелю и тушим до готовности. Наш потрясающий фаршированный картофель с мясной начинкой обязательно подавать горячим, с подливой и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3371,'Кефир соединить с содой и не трогать 10 минут. Яйца вбить в майонез, все перемешать, добавить соль и сахар и все взбить. В получившуюся смесь влить кефир, всыпать просеянную муку и замесить тесто. Готовое тесто вылить тонким слоем на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3371,'Колбасу и лук нарезать и обжарить. Помидоры порезать дольками. Подготовленные ингредиенты выложить на тесто и присыпать потертым сыром. Готовить в духовке при температуре 180 градусов, в течение 20 минут. Пицца по-домашнему  на кефирном тесте готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3372,'Масло перетереть с сахарным песком, яйца вбить по одному, влить сок и добавить цедру.  В отдельной посуде перемешать сухие ингредиенты (мука, разрыхлитель, ванилин). Сухую смесь, поочередно с молоком вводить в подготовленную яично-масленную смесь. Получившееся тесто влить в форму, выпекать при температуре 175 градусов, в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3372,'Для приготовления крема, яйца разбить и поместить в жаростойкую посуду с добавлением сахара и цедры лимона. Нагреть ингредиенты, затем убрать с огня, и перемешать с маслом. Смесь немного остудить и влить сливки, все взбить. Корж разрезать на две части, середину промазать кремом и выложить дольки мандарина. Верхушку так же смазать кремом и украсить мандаринами.  Лимонный торт со взбитыми сливками и мандаринами готов. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3373,'Для приготовления фарша, нужно прокрутить через мясорубку филе, чеснок и заранее замоченный в молоке белый хлеб. В готовый фарш посолить по вкусу, всыпать специи и добавить яйца, все перемешать. Сыр порезать маленькие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3373,'Из фарша вылепить котлеты, внутрь которых поместить кусочек сыра. Каждую обвалять в муке и обжарить с каждой стороны на разогретой сковороде до образования румяной корочки, затем прикрыть крышкой и довести котлеты до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3373,'Для соуса необходимо отварить грибы и измельчить лук, затем все пассировать. Масло растопить в жаропрочной посуде, тщательно перемешивая всыпать муку, затем влить сливки. Соус довести до загустения и влить в посуду с грибами и луком, добавить зелень. Готовые котлеты, при подаче, обильно полить соусом. Куриные котлеты с сыром под сливочно-грибным соусом готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3374,'Для того чтобы приготовить тесто, необходимо смешать все сухие продукты, добавить оливковое масло, яичные желтки и частями влить воду. Замесить жидкое тесто и убрать в холод на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3374,'Холодную сковороду смазать маслом, в центр вылить тесто, не распределяя его по сковороде. Выпекать на среднем огне, не переворачивая. Блинчик по-Мароккански будет готов тогда, когда верх не будет прилипать к руке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3375,'Макаронные изделия сварить до полуготовности и выложить на противень. Грибы и чеснок измельчить, зелень нашинковать, сыр натереть, все смешать со сметаной. Яйцо немного взбить и добавить к ингредиентам, все перемешать. Получившейся начинкой наполнить гнезда. Готовить в духовом шкафу в течение 15 минут, при 180 градусах. Гнезда с сырно-грибной начинкой подавать как самостоятельное блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Из бульона и нашинкованных овощей сварить соус с добавлением молотого черного перца, соли, лаврового листа и топленого масла, варить 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3376,'Для теста необходимо сливочное масло заранее довести до комнатной температуры. Взбить масло, яйца, сметану, сахар, соду погасить уксусом и добавить в заготовку. Поэтапно вмешать просеянную муку. Готовое тесто убрать на холод на 30 минут. Для крема необходимо, с помощью блендера взбить все подготовленные ингредиенты, довести их до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3376,'Готовый крем убрать на холод. Тесто руками распределить по форме, обязательно сформировать бортики. Ананасы уложить на тесто и залить их кремом. Готовить в духовом шкафу в течение 50 минут при температуре 180 градусов. По истечению отведенного времени, готовый пирог остудить в форме, затем убрать на холод. По истечении некоторого времени пирог с творожным кремом и анансами можно подавать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3377,'Картофель почистить и нарезать тонкой соломкой, обжарить во фритюре. Яйца сварить вкрутую и измельчить. Курицу и огурец нашинковать соломкой. Все ингредиенты соединить, приправить по вкусу и смешать с майонезом. Салат с копченой курицей на каждый день готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3378,'Для приготовления маринада необходимо, имбирь очистить от шкурки и измельчить с помощью мелкой терки, чеснок нашинковать, добавить растительное масло, молотый чили, кинзу и сок лайма. В получившийся маринад поместить куриное филе, порезанное на несколько кусков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3378,'Лук мелко нашинковать и пассировать на масле, добавить куркуму. Курицу, поместить в сковороду, залить маринадом и обжаривать до полуготовности. Влить кокосовое молоко, добавить мелко нарубленный перец, посолить, поперчить. Тушить в течение 20 минут. Курицу приготовленную в имбирно-кокосовом маринаде подавать с рисом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3379,'Картофель отварить, размять до состояния пюре, вбить яйцо, добавить мягкое масло, тертый сыр и по вкусу приправить специями. Все перемешать, пюре поместить в формочки для маффинов. Лук нашинковать и обжарить до прозрачности и золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3379,'К готовому фаршу присоединить рис, яйцо, лук, добавить соль и специи и перемешать. Подготовленную начинку разложить в корзиночки и присыпать сыром. Готовить в духовом шкафу в течение 40 минут при температуре 190 градусов. Перед подачей тефтельки в картофельных корзиночках с сыром остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3380,'Для того чтобы приготовить тесто, необходимо, холодное масло измельчить, вместе с мукой, присоединить лимонный сок, воду, все присолить. Вымесить тесто плотной консистенции, убрать на холод на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3380,'Для начинки, сначала нужно подготовить сироп, для этого, в сотейник налить воду, всыпать сахарный песок и специи, все нагреть. Отдельно развести крахмал и влить, в сироп тонкой струйкой, постоянно помешивая. Дать покипеть минуту, ввести вишню, через пару минут снять с огня и добавить сливочное масло и лимонный сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3380,'Начинку обязательно охладить. С помощью скалки тесто раскатать по размерам формы, разложить начинку. Для украшения пирога из остатков теста нарезать полоски и уложить их, переплетая между собой, чтобы получилась решетка. Тесто промазать желтком. Выпекать в духовом шкафу в течение 40 минут при температуре 200 градусов. Перед подачей рассыпчатый домашний пирог с вишней обязательно остудить и присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3381,'Небольшими кусочками нарезать мясо, обжарить, (можно и не обжаривать, а налить к нему немного кипятка). Добавить растительное масло и протушить с порезанным луком и тертой морковью на несильном огне. Долить воды (приблизительно полкилограмма мяса стакан воды), тушить, пока мясо не будет мягким. Готовность проверять вилкой или ножом. Во время тушения мясо должно быть немного прикрыто образовавшимся бульоном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3381,'Где-то за 10 минут до готовности, посыпать солью, положить 1 лавровый лист, несколько штук перца-горошка. Развести на полстакана воды чайную ложку томатной пасты, столовую ложку муки и сметаны (можно и без сметаны). Хорошо перемешать, чтобы не было комков, лучше всего это сделать вилкой. Постоянно мешая гуляш, влить в него смесь из стакана. Он сразу начнет густеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3382,'Кожуру срезать с апельсина, нарезать на длинные полоски. Вскипятить воду, положить туда полоски, держать их в воде несколько минут, пока полосочки не сделаются мягкими и прозрачными. Вынуть их из воды, ненадолго отложить, сверху густо притрусить сахаром или даже обвалять в сахаре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3383,'Масло с сахаром взбить, затем положить сюда яйцо и опять взбить. Положить соль, корицу, разрыхлитель, ванилин и снова все взбить. Прибавить овсяные хлопья и хорошо перемешать, потом шоколад (мелко порубленный), сухофрукты, опять перемешать. Добавить муку и замесить тесто руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3383,'Поделить его на 12 частей, скатать кружочки и положить их на противень, на некоторой дистанции один от одного. Запекать в духовке 15 минут (температура 180 градусов). Вытянуть из духовки, остудить на противне, а потом то самое печенье из «Starbucks» аккуратно снять с противня и можно пить чай.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3384,'Лучше всего приготовление начать с рассола, так как он варится, а потом его необходимо остужать до комнатной температуры. Поставить воду на огонь, пока она закипает, порезать морковь кружочками. В закипевшую воду, положить сахар, соль, морковь и специи, должно покипеть приблизительно 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3384,'Пока сваренный рассол остывает, почистить рыбу: отрезать плавники, голову, выпотрошить внутренности, промыть брюшко водой. Рыбу порезать на куски (2 сантиметра толщиной), лук — полукольцами. Уложить куски рыбы в банку, прослоить их морковью из рассола и луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3384,'В рассол, который уже остыл (можно, чтобы был едва теплый), прибавить уксус яблочный и масло растительное. Залить рассолом рыбу, его как раз должно хватить, чтобы рыба вся покрылась. Поставить банку в холодильник на сутки, спустя это время маринованная пряная скумбрия с луком и морковью готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3385,'Лук очистить и мелко измельчить, лучше всего воспользоваться теркой или блендером. Добавить его к фаршу вместе с яйцом. Мелко нарезать зелень, натереть на терке сыр. В фарш добавить соль, перец, зелень и сыр, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3385,'Слепить небольшие котлетки (на одну котлетку пойдет примерно одна столовая ложка фарша). Обжарить куриные котлеты с сыром и зеленью по-домашнему на среднем огне с добавлением малого количества растительного масла до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3386,'Нашинковать лук, потереть на терке морковь, картофель порезать тонкими ломтиками. Лук обжаривать на сковородке до прозрачности. Прибавить к нему морковь и обжаривать примерно 5 минут. Сюда же добавить фарш и тушить, пока фарш не приобретет коричневый оттенок, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3386,'Форму, где будет запекаться мусака, смазать маслом, лучше сливочным, на дно уложить слой картошки, далее слой фарша и дальше их чередовать. На последний слой фарша уложить помидоры и все это накрыть картошкой (обязательно верхним слоем необходимо, чтобы была картошка).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3386,'Запечь в духовке 20-25 минут (250 градусов), пока картошка не станет румяной. Взбить яйца с солью и молоком (как для омлета) и этой смесью равномерно полить блюдо сверху. Потом покрыть слоем сыра и запечь столько же времени, пока сыр не зарумянится. Перед подачей сербскую мусаку с сыром посыпать петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3387,'Немного проварить ягоды, измельчить (блендером или через сито). Добавить сахар, крахмал и хорошо перемешать. Эту смесь пока отставить. Взбить белки, положить их во фруктовую массу и аккуратненько перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3387,'Смазать сливочным маслом форму, уложить туда горкой фруктово-белковую смесь. Поставить торт-суфле «Розовое облако» в заблаговременно нагретую духовку на 30 минут, до зарумянивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3388,'Куриные крылышки помыть и разрезать на составные части. В крупную емкость налить воду, добавить лавровый лист, уксус, тимьян, розмарин, орегано, соль и вскипятить. Положить крылышки и варить минут 15 после закипания воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3388,'Выложить крылышки на решетку оставить, чтобы остыли и обсохли (минут 15). Растереть чеснок и щепотку соли до однородной массы. В большой емкости соединить чеснок, оливковое масло, перец (красный и черный) и перемешать. В полученный маринад положить крылышки и хорошо перемешать, всыпать панировочные сухари, а потом полстакана тертого пармезана, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3388,'На противень выложить крылышки, взбрызнуть оливковым маслом, посыпать оставшейся половиной пармезана. Запечь пряные куриные крылышки с сыром в духовке 20-25 минут (температура 230 градусов) до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4315,'Поставить бутерброды с курицей и моцареллой на 15 минут в горячую духовку, сыр должен расплавиться. Готовые бутерброды выложить на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3389,'Бисквит. Яйца и сахар необходимо взбить в пену. Затем сюда прибавить разрыхлитель, муку, ванилин, сливочное масло (размягченное, но не растопленное), снова хорошо взбить. Тесто, что получилось вылить в форму для запекания и отправить в духовку на 25 минут (160 градусов). Когда запечется, вынуть из формы и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3389,'Крем и персики. Персики почистить и нарезать на кусочки, по собственному желанию. Кондитерские сливки охлажденные вылить в ёмкость и взбивать, пока не загустеют. К ним добавить сливочное масло, топленый и охлажденный желатин взбить. Бисквит, когда он остыл, разрезать вдоль на три части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3389,'Самый нижний корж намазать кремом и положить на него часть персиков, сверху положить бисквит, дальше сливки, персик и так далее. Верх торта и его бока тщательно смазать сливками. Украсить торт на собственный вкус и фантазию. Готовый торт «Для любимой мамочки» с персиками и взбитыми сливками поставить на ночь в холодильник, чтобы пропитался. Получится нежный и мягкий торт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3390,'Морковь почистить и нарезать кружочками (необходимо 18 штук). Вырезать небольшие треугольники из каждого кружка моркови – ноги для будущих пингвинов. Взять мягкий сливочный сыр (можно обычный, а можно с добавками – чеснок, зелень, соль), вырезать щель вдоль большой оливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3390,'Заполнить вырезанные отверстия сыром. Далее закрепить на моркови оливку с помощью зубочистки. Вырезать небольшие отверстия в маленькой оливке, вставить треугольник из моркови – нос готов. Установить маленькую оливку на зубочистку над большой оливкой. Канапе «Пингвинчики» из оливок и сыра это украшение для любого праздничного стола.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3391,'Отсчитать необходимое количество бубликов и положить в миску с горячим молоком минут на 20, пока они не размякнут. Лучше их за это время несколько раз перевернуть, чтобы пропитка была равномерной. Очистить луковицы, тонко порезать их на кружочки, не нарушая структуры, положить его в миску и залить уксусом (чтобы жидкость все покрыла).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3391,'Фарш мясной посолить, поперчить, перемешать. Противень смазать растительным маслом, выложить на него размягченные бублики. С лука слить уксус и колечки выложить на бублики. С фарша сформировать мини-котлетки, каждую уложить поверх колец лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3391,'Сыр нарезать тонкими квадратиками и положить на фарш. На сыр положить кружочек соленого огурца. Далее томаты, также нарезанные тонкими кружочками. На самый верх – капельку майонеза. Бублики с мясной начинкой под сыром отправить в духовку (160-170 градусов) минут на 25.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3392,'Грудку порезать соломкой. Порезать лук, оливки, помидоры и сельдерей, орехи перемолоть. Заправка: в емкость положить масло, перец, уксус и соль, выдавить чеснок (можно и без него, по желанию), смешать. Заправить наш легкий салат из курицы заправкой и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3393,'Разбить в миску яйца (3 штуки), взбить с сахаром и солью. Присоединить молоко, помешать. Постоянно мешая тесто, всыпать муку, пока тесто не будет консистенцией, как 15 процентная сметана. Добавить соду и растительное масло, помешать и отставить миску с тестом в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3393,'Приготовить крем: сгущенное молоко размешать со сметаной и размягченным сливочным маслом. Поставить в холодильник. Взять тесто, смазать сковородку для первого блина растительным маслом, хорошо разогреть, налить тесто, когда появятся пузырьки, перевернуть, подождать пару секунд и снять блин со сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3393,'Также пожарить остальные блины, но сковородку маслом уже не смазывать. Получится стопка блинов. Достать крем из холодильника, перемазать блины. Украсить торт из блинов с нежным кремом по своему желанию и предпочтениям.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3394,'Испечь пустой корж из песочного теста (желательно диаметром 22 сантиметра), согласно инструкции на упаковке. Вынуть корж из духовки и полностью остудить. Выложить в уже испеченную форму начинку: ветчину, соцветия брокколи, тертый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3394,'В отдельной посуде взбить оставшиеся продукты, залить начинку, поставить в духовку. Запекать пирог с ветчиной и брокколи под сыром в духовке около 45 минут. Подавать остывшим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3526,'Отправить в холодильник. Слепить котлеты, добавить в них замороженную воду или бульон, для сочности. Обмакнуть котлеты в муку или кляр, обжарить до корочки со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3395,'Мясо порезать кусками примерно 2х2 сантиметра, лук полукольцами. Свинину уложить в крупную миску, добавить лук, взбрызнуть все соком лимона, добавить перец, оливковое масло и соль. Отставить мясо на несколько часов (а можно и на ночь) для маринования. Затем выложить замаринованное мясо в сковородку и тушить на среднем огне до приятного золотистого цвета. Готовую сочную свинину по-мужски переложить в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3396,'В большой емкости смешать творог, сахар, яйца и соль, перемешать. Прибавить изюм и все еще раз смешать. В отдельную емкость всыпать манную крупу, из творожной массы сделать маленькие шарики, сплюснуть, обвалять в манной крупе и положить на разогретую сковородку с растительным маслом. Таким образом пожарить все сырники. Нежные сырники в манке готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3397,'Кастрюлю с водой поставить на огонь. Куриное филе измельчить до состояния фарша. Одну луковицу очень мелко нашинковать вмешать в фарш. Вторую луковицу так же измельчить и положить в кастрюлю, когда закипит вода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3397,'Картофель порезать на средние кубики, морковь натереть на терке, все добавить в кастрюлю. Из фарша слепить фрикадельки и положить в бульон, соль и перец добавить по вкусу. Варить в течение 15 минут. Затем добавить петрушку.  Бульон с фрикадельками из куриного филе готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3398,'2 куриных яйца взбить с щепоткой соли, по очереди ввести сметану и кефир, все хорошо перемешать. Муку просеять и ввести в заготовку, замесить тесто, по консистенции оно должно быть густое, как на обычные оладьи. Заранее сваренные 2 яйца измельчить, смешать с нашинкованным зеленым луком и добавить в тесто. Все тщательно перемешать и обжарить оладки «Смайл» с вареным яйцом с обеих сторон на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3399,'Замесить тесто для блинов, используя яйца, сахар, муку и молоко, все ингредиенты смешать до однородной массы, стараясь избежать образования комочков. Испечь тонкие блины. На 1 рулет понадобится 4 блина. Для приготовления первой начинки необходимо измельчить киви, для второй-измельчить мак в кофемолке и смешать с небольшим количеством сахара и воды, для третьей-убрать косточки из ягод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3399,'Для приготовления желе из сметаны, нужно растворить желатин в стакане горячей воды. Сметану смешать с сахаром, влить желатин и все взбить до однородной консистенции. Начинки завернуть в блины, один блин – одна начинка, сложить пирамидой. Четвертый блин смазать желе из сметаны и обернуть им подготовленные блины. Убрать блинчики-рулеты со сметанным кремом в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3400,'Перемешать все сыпучие ингредиенты, в другой посуде при помощи блендера взбить яйца, сахар и масло на низкой скорости до однородной консистенции. Затем, постепенно ввести подготовленные сыпучие продукты, добавить кокосовую стружку и морковь, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3400,'Тесто перелить в форму устланную фольгой и промазанную маслом. Готовить пирог в течение 30 минут, при 175 градусах. Для приготовления крема необходимо тщательно смешать все подготовленные ингредиенты. Пирог остудить и смазать кремом. Сладкий морковный пирог со сливочным сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3401,'Приготовить маринад, для этого смешать, кипяченую воду, уксус и сахар. В нем замочить порезанный лук. Сельдь разделать на филе, картофель сварить в мундирах, огурцы помыть, все порезать кубиками. Морковь натереть и выдавить сверху чеснок. Все ингредиенты перемешать. Зеленый лук нарубить и украсить салат. Наш простой и вкусный салат с сельдью готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3402,'Белки и сок лимона взбить на невысокой скорости с добавлением ванилина, ввести сахар порциями, взбивать до тех пор, пока не получатся устойчивые пики, затем, частями всыпать муку. Тесто перелить на подготовленный противень, устланный пекарской бумагой, выпечку готовить духовке 15 минут, при 175 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3402,'Немного остудить и переложить на заранее присыпанное сахарной пудрой кухонное полотенце, скрутить рулет и полностью остудить. Сливки взбить с добавлением ванилина и сахарной пудрой. Затем добавить порезанную клубнику и аккуратно перемешать. Бисквит раскрутить и промазать подготовленным кремом, скрутить обратно. Бисквитный рулет с клубникой в сливках готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3526,'Довести до готовности в духовке, налить чуть-чуть бульона, положить лавровый лист, перец и потушить сочные мясные котлеты еще минут пятнадцать на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3403,'Взбить яйца, сахар и мед. Сухие продукты смешать и порционно добавить в смесь. Тесто перелить в чашу мультиварки, промазанную маслом. Установить программу «Выпечка» на полтора часа. Мягкое сливочное масло взбить со сгущенным молоком и какао. По окончанию программы, бисквиту дать остыть, затем разрезать его на несколько равных частей, смазать кремом. Бисквит украсить сливками. Торт «Медовик» с нежным кремом готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3404,'Клубнику с сахаром, при помощи блендера измельчить до состояния пюре, протереть через сито, чтобы удалить косточки. Из лайма выжать сок. Смешать подготовленные ингредиенты, добавить воду и немного взбить. Освежающий напиток с клубникой и лаймом готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3405,'Яйца взбить с добавлением соли и сахара. Ввести ванилин и творог, все перемешать. Добавить мелко нарезанные сухофрукты. Банан измельчить до состояния пюре и добавить в заготовку. Перемешать, добавить муку и снова перемешать. Готовое тесто остудить в течение 10 минут, сформировать сырники, обвалять в манке и обжарить на сковороде. Пробить блендером половину банана и 2 ст.л. кефира, сахар добавить по вкусу. Сырники выложить на блюдо и полить банановым соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3406,'Для приготовления теста необходимо, в глубокую посуду поместить муку, сформировать посередине воронку, соединить соль и воду, соленую воду влить в муку и замесить тесто. Готовое тесто прикрыть и дать отдохнуть в течение 30 минут. Для приготовления начинки подготовленное мясо перекрутить в фарш. Лук нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3406,'Мясной фарш обжарить на сковороде с добавлением лука. Начинку остудить. Тесто раскатать скалкой в очень тонкий пласт, весь промазать растопленным маслом и завернуть на скалку маслом внутрь. Затем разрезать тесто вдоль, скалку удалить, полученный отрезок разрезать пополам вдоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3406,'Из отрезков теста крутить рулет, сделать 3 оборота, тесто обрезать и так до конца. Каждый получившийся рулетик разрезать на 2 части, каждую часть придавить сверху. Получившиеся лепешки раскатать, в центр положить начинку и сформировать треугольную самсу, тщательно залепляя швы. Заготовки обжарить в разогретом растительном масле с двух сторон до золотистой корочки.  Слоеная самса с сочным мясом готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3407,'Рис отварить, немного остудить и добавить рисовый уксус. Яйцо взбить с добавление соевого соуса, обжарить с обеих сторон, Омлет остудить и порезать на полоски. Все подготовленные ингредиенты порезать на брусочки. Креветки сварить. На специальный коврик уложить водоросли нори.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3407,'Сверху положить еще не остывший рис, отступив немного места от края. На рис рядами выложить начинку и мягкий, творожный сыр. Свернуть ролл, помогая себе бамбуковым ковриком. Свободный от риса край нории смочить водой и зафиксировать рулет. Готовый рулет разрезать на несколько частей, толщиной 1.5–2 см. Роллы с нежным творожным сыром подавать с соевым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3408,'В миске взбить масло и сахар с помощью блендера до тех пор, пока масса не станет воздушной. По одному вбить яйца, влить кефир и добавить ванильный сахар, продолжая взбивать ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3408,'В другой посуде смешать оставшиеся сухие продукты и ввести в семь, замесить тесто и добавить фрукты. В подготовленную форму для маффинов положить бумажные формочки, наполнить их на половину тестом, выпекать в духовке, разогретой до 190 градусов, в течение 25 минут. Маффины с бананово-яблочной начинкой готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3409,'Взбить сметану, сахар и растопленное сливочное масло, добиться однородной консистенции, вмешать муку и замесить тесто. Затем его поделить на одинаковые части. С помощью скалки, на присыпанной мукой поверхности раскатать. На получившийся пласт положить форму или тарелку, вырезать круг, выложить на противень, устланный пергаментом, обрезки, так же положить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3409,'Таким образом раскатать и обрезать все заготовки. Коржи готовить в духовом шкафу в течение 5 – 7 минут, при 200 градусах. Для крема необходимо взбить яйца и сахар, ввести муку. Заранее подогретое молоко осторожно влить в смесь, не переставая тщательно перемешивать, затем на небольшом огне довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3459,'Подготовить 4 куска хлеба, положить на них колечки огурцов и тонкие пластинки сыра, сверху уложить салат, наверх положить второй ломоть хлеба. Ароматные сэндвичи с яичным салатом можно подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3409,'Мягкое сливочное масло ввести в крем порциями, все взбить до однородности. Готовым кремом промазать коржи, складывая их друг на друга стопкой. Испеченные обрезки теста измельчить и крошкой обсыпать торт. Готовый торт «Наполеон» на сметане с нежным кремом убрать на холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3410,'Куриное филе замариновать в соке лимона с добавлением порубленного перца чили. Убрать в холод на 30 минут. По окончанию отведенного времени филе обжарить на разогретой сковороде, с добавлением оливкового масла, до появления золотистой корочки, затем огонь убавить и довести курицу под крышкой до готовности. На гарнир отварить спагетти. В сотейнике припустить чеснок и разрезанные помидоры черри, добавить готовые спагетти и базилик, все перемешать и прогреть. Острая куриная грудка маринованная в лимонном соке с соусом готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3411,'Отварить любые макаронные изделия до полуготовности. Лук, чеснок и грибы пассировать на сливочном масле. Для соуса взбить яйцо, сливки и натертый сыр, специи присыпать по вкусу. К грибам добавить макароны и все полить соусом, перед подачей посыпать тертым сыром. Паста с грибами готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3412,'Капусту нашинковать и потушить под закрытой крышкой до полуготовности, добавить остальные овощи. Куриное филе обжарить на другой сковороде. Ингредиенты соединить, приправить солью и специями по вкусу. Курица с тушеными овощами по-домашнему готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3413,'Спагетти отварить, помидоры порезать кубиками и дольками, сыр натереть. Для соуса смешать яйцо, молоко и часть тертого сыра, приправить специями и солью. В форму для запекания выложить помидоры, спагетти окунуть в соус и все поместить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3413,'Сверху положить порезанный бекон и помидорные дольки. Выпекать в духовке в течение 30 минут, при 180 градусах. Когда бекон зарумянится, пирог присыпать рубленным зеленым луком и тертым сыром, запекать еще в течение 10 минут. Пирог из спагетти под сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3414,'Для приготовления кляра необходимо смешать яйца, молоко, муку и специи. Рыбное филе нарезать. Ломтики обвалять в муке и опустить в кляр. Обжаривать их в раскаленном масле с обеих сторон. Рецепт рыбы в воздушном кляре обязательно приживется в вашем доме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3415,'Для приготовления теста сахар, яйца и сметану смешать и тщательно взбить. Ввести муку, предварительно смешанную с ванилью и содой. Промытые и очищенные яблоки нарезать, поместить в форму для выпечки, посыпать корицей и залить тестом. Шарлотку выпекать при температуре 180 градусов в течение 45 минут. Ароматная «Шарлотка» готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3416,'Овсяную крупу, муку и корицу смешать. Добавить оставшиеся измельченные ингредиенты, ввести мед и перемешать. Из получившегося теста слепить печенье и выпекать в течение 30 минут, при температуре 175 градусов до золотистого цвета. Полезное печенье с фруктами и медом готово.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3417,'Порезать кусками рыбу, посолить, взбрызнуть соком лимона, дать постоять около 10 минут, а затем поджарить на сковороде. Отдельно от рыбы поджарить грибы и лук, приправив солью и перцем. Картофель отварить в мундире, в подсоленной воде. Помидоры опустить в кипяток и снять кожицу, порезать его дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3417,'Вареное яйцо очистить и порезать на 8 частей (дольками). Сыр натереть на терке. Взять круглую форму для запекания, смазать ее немного маслом. Выложить все ингредиенты слоями: в центр формы половину грибов с луком, далее пожаренные кусочки рыбы, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3417,'Выложить по кругу формы кружочки картофеля, на рыбу выложить, по кругу, чередуя помидоры и дольки яиц. Оставшиеся грибы выложить в центр круга из помидоров и яиц. Полить майонезом, и притрусить все сыром. Рыбу по-Монастырски с сыром печь в духовке около 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3418,'Духовку нагреть (260 градусов). На сковородке обжарить до золотистого цвета лук на маленьком огне, посолить, поперчить. Еще уменьшить огонь и добавить нарезанный шпинат. Дальше тушить до готовности шпината (примерно минуту). Снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3418,'В отдельной емкости смешать творог, тертую  моцареллу, тофу, мускатный орех и яйцо. Перемешать до однородной массы. Лишний сок из готового шпината удалить и добавить его в творожную смесь. Тесто поделить пополам, каждую часть раскатать в форме диска.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8081,'Багет разрезать на 4 части, каждую часть надрезать еще на 3 части, но не до конца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3419,'Картофель в мундирах почистить и сделать пюре, посолить, поперчить. Сделать начинку: потереть морковь (на мелкой терке), сыр поломать руками на крупные крошки. На сковородке поджарить морковь и сыр (примерно 10 минут). Во время тушения, добавить соль, куркуму, красный перец и сливки. Перед самой готовностью положить мелко порезанную петрушку и укроп. Из всех подготовленных ингредиентов лепить зразы. Руки при этом можно намочить водой или намазать растительным маслом. Взять немного картофельного пюре, сделать на руке из него лепешку (1,5-2 сантиметра толщиной), сверху положить начинку, осторожно свернуть, защипать со всех сторон. Далее зразу обвалять в муке со всех сторон и уложить на подогретую сковородку с растительным маслом. Соус: ингредиенты взбить в блендере (перец необходимо очистить от семян). Картофельные зразы с сыром под крем-соусом готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3420,'Все ингредиенты для теста соединить и выпекать в форме приблизительно 1 час. Пока кекс готовится подготовить глазурь. Шоколад растопить и смешать со сливочным маслом. Готовый кекс остудить и украсить шоколадной глазурью. Творожный кекс в шоколаде готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3421,'Натереть по отдельности крабовые палочки, желтки и белки на терке (лучше мелкой). Подготовленную форму застелить пленкой. Рыбу необходимо нарезать небольшими полосками и выложить ею дно и стенки формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3421,'Крем: желатин намочить в воде (полстакана), дождаться, когда он разбухнет и растопить его на водяной бане, оставить остывать. Перемешать до однородной массы майонез, сметану и сыр. В эту смесь, непрерывно помешивая, влить желатин. Консистенцией крем должен быть, как густая сметана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3421,'Укладывать слоями: крем, тертые желтки, крем, крабовые палочки, крем, тертые белки, крем, рис и крем. Отправить готовый кекс в холодильник на ночь. Достать из холодильника, накрыть плоской тарелкой и перевернуть кекс с красной рыбой и сыром на нее. Украсить красной икрой и зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3422,'Размягченное масло присыпать сахарной пудрой. Добавить семена ванили и растереть ложкой до получения однородной массы. Ввести в смесь пару белков, желательно комнатной температуры. Перемешать, всыпать муку и замесить мягкое тесто. Приготовленное тесто выложить в форму равномерным слоем. Выпекать 12 минут, при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3422,' Заливка: взбить желтки с сахаром и ванилью в белую густую массу. Затем поочередно добавить крахмал, сметану и продолжать взбивать на низкой скорости. Готовую смесь вылить на горячую основу. Поместить пирог в духовку, убавить температуру до 170 градусов и выпекать еще примерно 40-50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3422,'В процессе выпекания пирог поднимется горкой, но впоследствии немного осядет. Сметанник двухслойный можно есть и теплым, но охлажденный он просто бесподобен.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3423,'Яйца отварить, разрезать пополам, отделить желтки и размять их вилкой. К желткам  добавить половину предварительно натертого сыра, щепотку соли и перца. Половинки белков нафаршировать получившейся смесью и выложить в форму для запекания. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3423,'Перец и лук нарезать небольшими кубиками и обжарить на растительном масле до золотистого цвета. Добавить в приготовленную смесь томаты. Овощи тушить, пока не выпарится сок от томатов примерно на 2/3. Получившимся соусом залить яйца. Посыпать оставшимся сыром. Форму поставить в разогретую духовку (180 градусов) и запекать около 15 минут. Яйца по-Кубински под соусом готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3424,'Куриным фаршем начинить макароны. Макароны предварительно не отваривать. Фаршированные макароны уложить в форму и залить водой смешанной с томатной пастой так, чтобы вода полностью покрыла макароны. Поставить на 20 минут в разогретую духовку (180 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3424,'Спустя 20 минут достать макароны из духовки, вода должна немного выпариться и впитаться, снова залить макароны, но уже сливками. Сверху макароны посыпать тертым сыром. Вернуть «Каннеллони» начиненные куриным фаршем в духовку минут на 20 до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3425,'Филе лосося нарезать небольшими кусочками, сбрызнуть лимонным соком, добавить перец, соль и отставить на полчаса. Через 30 минут филе залить водой (горячей) и варить на маленьком огне примерно 10 минут. Брокколи также отдельно от рыбы отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Добавить мякоть в творожную массу вместе с сырыми куриными яйцами, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3425,'Сливки взбить с молоком, яйцами и сыром, посолить, прибавить мускатный орех и перец. Форму для запекания промазать маслом, уложить слоями рыбу и брокколи, и залить взбитой смесью. Запекать рыбу под сыром в духовке около 20 минут (220 градусов). Лосось в лимонном соке с брокколи под сыром готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3426,'Испечь тонкие блины (по любому рецепту). Далее приготовить начинку: растереть творог с ванильным сахаром, яйцом, сахаром, затем добавить цукаты и тертый на крупной терке банан, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3426,'Начинку выложить на блин, скрутить в трубочку. То же самое сделать и с остальными блинами. Форму для выпекания смазать маслом, трубочки из блинов выложить в нее по спирали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3426,'Заливка: немного взбить яйца с сахаром, прибавить сметану и перемешать до однородной консистенции. Все блинные рулеты с творожно-банановой начинкой и цукатами равномерно залить смесью, поставить в духовку на полчаса (190 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3427,'Крупно нарезать моцареллу, крупными дольками порезать помидор. Куски сыра и дольки помидора уложить полукругом на большую тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3427,'Сделать соус: смешать горчицу (2 чайные ложки), оливковое масло (1 чайную ложку), немножко уксуса, перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3427,'Полить готовым соусом моцареллу и помидоры. Сверху салат с помидорами и горчичной заправкой украсить рукколой и посыпать хлебными крошками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3428,'Куриную грудку нарезать на небольшие кусочки. В салатницу уложить курочку и немного ее примять. Помидор нарезать небольшими кубиками. Половину головки чеснока измельчить и смешать в отдельной емкости с помидорами и майонезом. Полученную смесь выкладываем на курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3428,'Болгарский перец нарезать маленькими кубиками. Оставшийся чеснок измельчить и смешать с перцем и майонезом. Смесь из перца выложить слоем поверх помидоров. Огурцы нарезать кубиками и уложить следующим слоем. Следом положить слой сухариков и смазать майонезом. И в завершение, щедро присыпать салат с куриной грудкой и сухариками тертым сыром и оставить на холоде примерно на 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3429,' Чернослив вымочить в небольшом количестве теплой воды. Желатин замочить в четверти стакана холодной воды. Яйца и сахар взбить, аккуратно всыпать муку с крахмалом и разрыхлителем. Перемешать и вылить в форму для выпекания (круглую). Выпекать 20 минут (200 градусов). Охладить корж не вынимая его из формы',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3429,'Небольшими кусочками нарезать чернослив, настой после него процедить, добавить к желатину и нагревать на водяной бане, пока желатин не растворится. Сметану и творог с сахаром взбить, аккуратно вмешать желатин с черносливом и выложить на корж.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3429,'Отправить наш восхитительный сметанно-творожный торт с черносливом в холодильник, пока он не застынет. Перед подачей на стол вынуть из формы и присыпать тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3430,'Духовку нагреть (200 градусов). Смазать сливочным маслом форму для выпекания. Картофель очистить, нарезать ломтиками и выложить в форму для запекания. Смешать сливки, молоко, добавить измельченный чеснок, соль, перец и муку. Получившейся смесью залить картофель, укрыть фольгой и запекать 30 минут. Потом убрать фольгу и оставить в духовке еще на 20-30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3430,' Когда картофель будет готов, присыпать сыром (тертым) и отправить в духовку еще минут на 5 (чтобы сыр расплавился, но не зарумянился). Украсить картофель, запеченный в духовке с сыром, зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3431,'Духовку нагреть. Перец хорошо промыть, высушить, уложить на противень с фольгой и отправить в духовку примерно на полчаса. Готовый перец положить в герметически закрытую кастрюлю или завернуть в фольгу до полного охлаждения. Остывший перец очистить от кожицы,семян и нарезать меленькими кубиками. Запеченный перец приправить солью, молотым перцем и петрушкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3431,'Подготовленное куриное филе прикрыть пищевой пленкой и отбить. Затем на кусочек сырокопченого бекона выложить отбитый шницель и приправить. На край шницеля выложить 2 столовые ложки начинки из перца, скрутить рулетом и закрепить кулинарной ниткой. Выложить рулетики в форму для выпечки с пергаментной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3474,'По истечению отведенного времени курицу в апельсиновом маринаде выложить в жаропрочную форму, запекать в течение 40 минут, при 220 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3431,'Бекон порезать кубиками маленькими и обжарить на сухой сковородке. Соцветия цветной капусты положить в емкость, добавить кубики бекона, соль, перец чили и оливковое масло. Смешать и уложить в форму с рулетиками. Отправить куриные рулеты с перцем в беконе в духовку и печь приблизительно 30 минут (температура 130 градусов).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3432,'Грибы мелко порезать и обжарить на сковородке вместе с измельченным чесноком и петрушкой. Как только на грибах появится аппетитная корочка, влить бульон,положить соль и перец по вкусу, и варить 15 минут. Бульон с грибами взбить в блендере. Сливки немного подогреть и взбить с мускатным орехом венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3432,'В миску для супа или чашку налить суп и выложить взбитые сливки. Для дополнения, ароматный суп «Грибной капучино» украсить грибным ломтиком, обжаренным на топленом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3433,'Шоколад растопить на водяной бане и немного остудить. Смешать сахарный песок, ванильный сахар, щепотку соли со сливочным маслом и все хорошо взбить. По одному ввести куриные яйца, присоединить растопленный шоколад. Муку с разрыхлителем перемешать и добавить в заготовку. Получившееся тесто вылить в разъемную форму, промазанную маслом и обсыпанную мукой. Готовить корж в духовке течение 20 минут, при температуре 175 градусов. По окончанию отведенного времени выпечку достать из духовки и оставить в форме на 15 минут, затем вынуть корж из формы и остудить его полностью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3433,'Мякоть двух апельсинов порезать на кубики, один апельсин разрезать дольками, при этом удалить пленки. Из пленок и обрезков выжать сок. Желатин замочить. Творог, маскарпоне и сахар смешать, добавить апельсиновый сок, пряные специи, все взбить. Желатин отжать, немного прогреть и смешать с небольшим количеством крема. Получившуюся массу ввести в крем и добавить кусочки апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3433,'Готовый крем вылить в форму с коржом и убрать на холод до полного застывания, примерно на 3 часа. После того, как выпечка полностью застынет, украсить торт-тирамису с апельсинами и темным шоколадом по вашему вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3434,'В жаропрочной посуде смешать сахарный песок, молоко, мед, какао и масло. Все содержимое поставить на несильный огонь и нагревать до тех пор, пока масло и сахар не растопятся. Соду, гашенную уксусом поместить в миску, туда же аккуратно вбить яйцо и очень быстро все перемешать. Смесь снять с огня и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3434,'в охлажденную смесь всыпать немного муки, выложить на рабочую поверхность присыпанную мукой, и замесить тесто. Разделить тесто на 10 равных частей, раскатать до размера формы для выпечки. На каждом корже сделать проколы и выпекать в течение 7 минут в духовке, разогретой до 190 градусов. Готовые коржи остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3434,'Для приготовления крема молоко нагреть со стручком ванили. Желтки взбить с сахаром и семенами ванили, всыпать крахмал, муку и влить немного теплого молока. Из молока удалить стручок ванили и добавить яичную смесь, все перемешать. Добавить сливочное масло, крем довести до загустения и убрать на холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3434,'Взбить сливки и ввести в остывшую массу. Все коржи промазать кремом, заготовку убрать на холод, сверху положить груз. Для приготовления глазури необходимо взбить масло и сгущенное молоко. Желатин размочить, добавить пару ложек кипятка и ложку сметаны и тщательно перемешать. Затем ввести в смесь оставшуюся сметану.Соединить обе смеси и получившейся глазурью промазать торт. Выложить на торт пленку с пузырьками, предназначенную для упаковки стеклянных предметов и прижать ее к глазури. Оставить пленку на глазури и убрать кофейно-медовый торт «Соты» на холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3435,'Отварное куриное филе и грибы нарезать небольшими кусочками. Лук измельчить. Предварительно отваренные яйца натереть на крупной терке. На блюдо слоями выложить куриное филе, грибы, лук, куриные яйца и завершить слоем из мелко натертого сыра. Каждый слой в салате промазать майонезом. В качестве украшения, с помощью майонеза, нарисовать сетку и в середину каждого квадратика поместить половинку маслины. Перед подачей новогодний салат «Подсолнух» украсить чипсами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3458,'Пока масса застывает, растопить шоколад (на водяной бане или в микроволновке). С помощью вилок макать домашние кокосовые конфеты «Баунти» в шоколад и укладывать назад на поверхность, чтобы шоколад затвердел.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3436,'Кочан разобрать, листья опустить на некоторое время в кипящую воду, а затем остудить. Приготовить начинку, смешав рис, фарш, нашинкованный лук(1 головку) и зелень, посолить, добавить специи. Пару ложек получившейся начинки поместить на лист, и заворачивая края свернуть голубец. Таким образом, начинить все подготовленные листья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3436,'Обжарить на разогретой сковороде с обеих сторон. Морковь измельчить с помощью терки, лук порезать, все обжарить на масле со специями, добавить томатный сок. Голубцы переложить в жаропрочную посуду и тушить с пассированными овощами до готовности. Голубцы из пекинской капусты с мясом по-домашнему подавать со свежей зеленью и сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3437,'Творог и яйца взбить, аккуратно всыпать муку, разрыхлитель и замесить тесто. Готовое тесто раскатать толщиной 0.7 мм., на присыпанной мукой поверхности. С помощью формы вырезать из теста кружки диаметром 5-7мм., и вырезать у них серединки. Пончики аккуратно опустить в горячее масло и обжаривать с обеих сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3437,'Белый шоколад растопить на водяной бане или с помощью микроволновой печи, добавить к нему сок свеклы, все перемешать.Готовые творожные пончики остудить и покрыть глазурью. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3438,'Грудки натереть маслом и солью, обильно обвалять в острых специях. Выложить на противень, устланный пергаментом, и запекать в хорошо разогретой духовке в течение 20 минут. Острые куриные грудки вынуть из духовки только после полного ее остывания. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3439,'Листья салата порвать руками, лук тонко нашинковать кольцами, помидор и яйцо крупно порезать. Раковые шейки извлечь из панциря. Лук, помидор, шейки и яйцо выложить на листья салата и полить майонезом. Приправить легкий салат из раков и зелени по вкусу солью и специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3440,'В теплой воде растворить сахарный песок, дрожжи и соль. Затем влить растительное масло, порционно ввести муку и замесить тесто. Готовому тесту дать отдохнуть в течение часа. По окончанию отведенного времени, заготовку разрезать на 10 частей. На присыпанной мукой поверхности каждую часть теста раскатать в очень тонкий пласт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3440,'Большую сковороду разогреть. Выложить на нее тесто и обжарить пласт с обеих сторон в течение нескольких секунд, до образования румяных точек. Масло, при жарке армянского лаваша на дрожжах, добавлять не нужно. Таким образом раскатать и обжарить все части. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3441,'Смешав подготовленные ингредиенты замесить тесто. Затем очень тонко его раскатать, промазать маслом, скрутить в рулет и убрать в холод на 2 часа, прикрыв предварительно пищевой пленкой. По истечению отведенного времени тесто достать и нарезать кусочками. Затем кусочки теста раскатать и заполнить начинкой, защепив края. Выпекать самсу по-домашнему в духовом шкафу при температуре 200 градусов, в течение 25 минут. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3442,'У свежих помидор срезаем верхушку и с помощью чайной ложки, аккуратно удаляем мякоть. Куриное филе режем на небольшие кубики и обжариваем на растительном масле до образования золотистой корочки, сдобрив их предварительно солью и перцем. Сыр измельчаем с помощью терки. В каждый помидор закладываем куриное филе, обильно поливаем его майонезом и присыпать сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3442,'Подобным образом необходимо нафаршировать все томаты и поместить их в форму для запекания. Готовить томаты в духовке, при температуре 220 градусов, в течение 15 минут. Подавать фаршированные помидоры под сыром как самостоятельное блюдо, так и в качестве закуски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3443,'Измельчить печенье до состояния мелкой крошки и смешать с растопленным маслом. Из получившейся массы сформировать, в разъемной форме, дно и бортики будущего десерта и на некоторое время убрать на холод. Смешать, предварительно протертый через сито творог, яйца, сахарный песок, манную крупу, ввести молоко и хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3443,'Начинку переложить на подготовленную основу. Выпекать в течение 30 минут при 180 градусах. Выпечку остудить. Ягоды выложить наверх пирога и залить подготовленным желе. Вишневый чизкейк с домашним творогом убрать на холод и оставить там до полного застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3459,'Подсушить хлеб на смазанной растительным маслом сковородке (только с одной стороны). Из помидора удалить семечки, а мякоть мелко порезать. Яйца также мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Готовые перцы наполнить начинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3444,'Пол стакана сахара и желтки взбить до однородной консистенции. Присоединить муку, крахмал и влить пол стакана молока, все взбить. Оставшееся молоко и сахар смешать в жаропрочной посуде, довести до кипения. Вмешать подготовленную ранее смесь и варить на маленьком огне, пока масса не загустеет. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3444,'Масло размягчить при комнатной температуре и взбить, постепенно добавляя в остывший крем. Аккуратно вмешать 3/4 кокосовой стружки. На дно сервировочного блюда выложить печенье, промазать его 1/3 крема, затем выкладывать поочередно слои крекера и крема. Домашний торт без выпечки обильно присыпать кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3445,'Куриную грудку предварительно отварить и разобрать на волокна. Яблоко очистить от кожуры и натереть на терке. Измельчить сыр. Вареное яйцо разделить на составляющие и так же измельчить с помощью терки. Затем все ингредиенты выложить слоями по очереди, курица, яблоко, сыр, желток и белок. Каждый слой промазать смесью сметаны и майонеза. Перед подачей салат «Оля-ля» с яблоком и курицей должен немного постоять на холоде и пропитаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3446,'Мед и сахарный песок смешать и растопить на водяной бане или в микроволновой печи до полного растворения сахара, ввести водку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3446,'Мандарины, вместе с кожурой нарезать на кольца и поместить в банку, добавить подготовленные пряности. В сосуд влить медовую смесь. Банку герметично закрыть и убрать мандариновый ликер с медом минимум на месяц. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3447,'Репчатый лук очистить, разрезать на 4 части и  нашинковать. Фасоль откинуть на дуршлаг и ополоснуть кипяченой водой. Овощи порезать кубикам. Все подготовленные ингредиенты смешать, заправить майонезом и приправить салат с огурцом, ветчиной и фасолью черным перцем. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3448,'Замесить тесто из сметаны, предварительно смешанной с солью и сахаром, муки и соды. Разделить на 4 одинаковые части. Из каждой части скалкой раскатать круг. Выпекать коржи в духовке около 10-15 минут (230-240 градусов). Приготовить крем взбить сметану с ванильным сахаром и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3448,'Готовые коржи выкладывать друг на друга, на большое плоское блюдо, предварительно промазать каждый из них кремом. Последний корж измельчить в крошку и присыпать этой крошкой самый верхний корж, щедро намазанный кремом. Украсить сметанный торт с ванильным кремом по собственному усмотрению и отправить в холодильник на 3-4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3449,'Лук и бекон нашинковать, помидоры разрезать пополам. Спагетти отварить до полуготовности и полить оливковым маслом. Лук и бекон пассировать на оливковом масле до золотистого цвета, влить сливки. В соус поместить готовые спагетти, хорошо прогреть и добавить специи по вкусу. Сковороду с пастой «Карбонара» убрать с огня и ввести желток, все перемешать, присоединить помидоры и присыпать тертым сыром. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3450,'Свеклу отварить до готовности, почистить и нарезать кружками в пол сантиметра. Для крема смешать сыр брынза и лимонный сок, приправить по вкусу солью и специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3450,'Авокадо разрезать, извлечь мякоть, смешать ее со сметаной сметаной и приправить специями и солью. Оба крема выкладывать на дольки свеклы и помещать их друг на друга, от большей к меньшей. Получившиеся свекольные елочки с авокадо скрепить шпажкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3451,'Филе копченой курицы разобрать на кусочки, огурец порезать соломкой, крабовые палочки – дольками, сыр измельчить с помощью терки. Картофель натереть на терке для приготовления корейской моркови и обжарить в растительном масле. Все продукты выложить слоями на блюдо, каждый слой, промазывая майонезом. Салат «Соблазн» с сыром украсить обжаренным картофелем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3452,'Куриное филе хорошо вымыть, просушить и порезать небольшими кусками. Почистить лук и нарезать его тоненькими полукольцами. Вымыть курагу и нарезать ее вдоль пополам. Вымыть и обсушить эстрагон, мелко порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3452,'На сковородке нагреть масло и обжарить лук (минут 6). Добавить кусочки кураги и курицы, влить полстакана воды. Протушить минут 10 на среднем огне, под накрытой крышкой. Затем добавить эстрагон, посолить, поперчить по вкусу. Помешать, убрать с огня, полностью остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3534,'Добавить в пюре, предварительно растопив, сливочное масло, горячее молоко, лук пассерованный и все тщательно перемешать. Пюре должно получиться густым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3452,'Просеять муку в крупную миску, добавить щепотку соли и дрожжи, перемешать, добавить яйца. Растопить сливочное масло, объединить его со сливками и понемногу вливать в смесь с мукой. Далее добавить пармезан (тертый) и замесить тесто. Порционно добавить к тесту остывшее филе куриное и курагу, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3452,'Форму для теста (прямоугольную) смазать маслом, накрыть пергаментной бумагой так, чтобы ее края свешивались вниз. Уложить смесь для кекса, разровнять и накрыть свисающими краями бумаги. Отправить дрожжевой кекс с куриным филе в разогретую духовку на 45 минут. Потом достать кекс из формы и охладить. Есть можно как теплым, так и холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3453,'Яйца с солью взбить, творог выложить в большую емкость, добавить ванилин и манную крупу. Если масса удастся немного жидкой, то можно прибавить еще манной крупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3453,'Далее подготовить шоколадку и муку (обваливать сырники). Присыпать руки мукой, на руку столовой ложкой выложить немного творожной массы, расплющить, сверху выложить кусок шоколада и, обмакнув в муку, образовать сырник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3453,'Обжарить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3454,'Яблоки очистить от кожуры, удалить сердцевину и порезать кружочками (толщиной примерно сантиметр). Поджарить их на растительном масле до золотистого цвета, но не долго, чтобы яблоки не начали расползаться. Во время жарки яблоки слегка можно присыпать сахаром – для карамелизации. Выложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3454,'Лук нарезать тонко кольцами и обжарить до золотистого цвета на том же самом масле. Выложить и пока отставить в сторону. Подготовить печень: удалить все плёнки и сухожилия. Нарезать небольшими кусками и обкатать в муке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3454,'Обжарить печень по-берлински «Leber Berliner Art» в том же масле, минуты по 2-3 с каждой стороны (серединка должна остаться мягкой и розоватой), посолить. Выложить на тарелку печень, далее яблоки и потом лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3455,'Дрожжевое тесто раскатать тонко на присыпанном мукой столе. Затем его переложить на противень для запекания. На тесто выложить кусочки сосисок, порезанных сначала вдоль, а потом поперек на 3 части, по кругу. Завернуть кромки теста за сосиски и плотно прижать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3455,'Затем надрезать между кусочками сосисок и по центру каждого кусочка и развернуть их в противоположные стороны. Середину пиццы смазать кетчупом, разложить ломтики сосисок и сладкого болгарского перца. Сверху посыпать любым тертым сыром и на него положить тонкие кружочки помидора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3455,'Затем добавить маслинки (кружочками) и приправу, зелень. Еще раз присыпать сыром, сделать тонкую сеточку майонезом. Края пиццы смазать взбитым яйцом. Выпекать дрожжевую пиццу по-домашнему 30 минут. Когда будет готова – украсить укропом и капельками кетчупа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3456,'Взять среднюю емкость, перемешать муку, разрыхлитель и соль. В отдельной миске перемешать творог, сахар, экстракт ванили и яйца, взбить блендером или в комбайне до однородной массы. К творогу добавить сухую массу и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3456,'Растительное масло подогреть на сковородке. В тарелку насыпать немного муки. Ложкой взять немного теста, на средину выложить дольку шоколада. Аккуратно тесто с шоколадом положить в муку и сверху тоже притрусить мукой, сформировать сырник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3456,'То же самое сделать с остальным тестом. Обжаривать творожно-шоколадные сырники на слабом огне до золотистой корочки, посыпать перед подачей к столу сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3457,'Потереть картофель на крупной терке. Если образуется вода, то можно прибавить пару ложек муки (вода может и не образоваться). Смешать все ингредиенты, затем массу класть ложкой на нагретую сковородку с растительным маслом и формировать блинчик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3457,'Уменьшить огонь и жарить сытные картофельные блины с куриным фаршем примерно 5 минут. Есть можно со сметаной. А еще по желанию в нее можно положить зелень и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3458,'Тщательно перемешать кокосовую стружку со сгущенным молоком. Подготовить поверхность, которую необходимо будет поставить в холодильник, с пергаментной бумагой или пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3458,'Взять в ладонь немного смеси и придать ей прямоугольную форму и выложить на предварительно подготовленную поверхность. Также поступить и с прочей начинкой. Затем поставить все прямоугольники в морозилку минут на 20. Так их будет намного удобнее окунать в шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3460,'Взбить белки в плотную пышную массу. Добавить сахарную пудру, помешать. Примерно 3 столовые ложки отложить для глазури. В белки, что остались добавить миндаль и корицу, вымесить тесто. Поставить в холодильник (часа на 2).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3460,'Потом тесто раскатать и вырезать печенье (можно формочками), смазать каждое глазурью и отставить на один-два часа, чтобы глазурь подсохла. Выпекать ореховое печенье в сахарной глазури в духовке в течение 10 минут (160 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3461,'Положить клюкву в кастрюлю, налить воду и закипятить. Затем огонь убавить и оставить варится на полчаса. Добавить корицу, гвоздику, сок лимона, мед и, снять с плиты, прикрыть крышкой и отставить на час. Затем клюквенный чай с лимоном и корицей процедить. Подавать теплым или холодным. Также по желанию добавить еще меда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3462,'На противень положить бумагу для выпечки, разогреть духовку. Снять с лимонов цедру, выжать сок. Белый сахар перемешать с цедрой и растирать рукой до тех пор, пока сахар не приобретет желтый оттенок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3462,'Прибавить измельченное на кубики масло и взбить до пышности (миксером). Затем добавить яйцо, опять взбить, влить лимонный сок. Понемногу добавить муку с разрыхлителем и содой, замесить тесто. Чайной ложкой зачерпывать тесто, сформировать шарики и обвалять их в тростниковом сахаре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3462,'Уложить шарики на противень на некоторой дистанции друг от друга, немного приплюснуть рукой. Выпекать лимонное печенье минут 10-12 до легкого золотистого оттенка. Готовое печенье остудить полностью, а потом переложить на блюдо или в контейнер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3463,'Курицу помыть и порезать небольшими кусочками. Уложить в сковородку с толстыми стенками. Смазывать сковородку ничем не нужно, добавлять также ничего не нужно (типа воды, жира или бульона). Положить на дно курицу, накрыть крышкой и поставить на медленный огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3463,'Замочить желатин в воде (необходим стакан воды). Курка готовится примерно 40 минут (мясо будет свободно отделяться от костей). За данное время не рекомендуется часто открывать крышку, тогда образуется много сока, не забыть посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3463,'Пока курица готовится, порезать мелко орехи, почистить чеснок. По истечении 40 минут, вынуть птицу на тарелку немного остудить, а потом разобрать: отделить мясо от костей, кожи и хрящей (по желанию, кожу можно оставить). Взять сковородку, в которой готовилась курица (в ней остался сок).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3463,'В этот сок добавить мясо, чеснок, пропущенный через пресс, измельченные орехи и желатин (его предварительно поставить на водяную баню или в микроволновку). Все перемешать. Взять чистую пластиковую бутылку (на полтора литра), срезать горлышко и влить туда смесь из сковородки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3463,'Дальше поставить ее в холодильник часа на 3-4 для застывания. Затем осторожно разрезать бутылку и аккуратно вынуть нежный куриный рулет с орехами. Порезать и подавать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3464,'Маргарин оставить ненадолго при комнатной температуре, чтобы растаял. Перемешать все ингредиенты, муки, возможно, пойдет чуть больше, главное, чтобы получилось мягкое, эластичное тесто, не прилипающее к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3464,'Поставить в холодильник (около получаса), потом раскатать, выдавить рюмочкой кружочки. Макнуть в сахар, выложить быстрое слоеное ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3465,'В подогретом молоке развести дрожжи, прибавить соль, яйцо, муку, вымесить мягкое тесто. Разделить тесто пополам, раскатать каждую в пласт, перемазать растопленным сливочным маслом. Затем скатать каждый из пластов в рулет, а потом его в улитку. Упаковать в пленку и положить в холодильник на пару часов (не более 4).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3465,'Крем (магалябия): яйцо с сахаром и крахмалом растереть в белую густую массу, добавить теплое молоко, отправить на медленный огонь (можно на водяную баню), постоянно мешая закипятить и довести до необходимой густоты. Необходимо, чтобы он остыл до теплого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3465,'Вынуть тесто из холодильника (не месить!), раскатать скалкой в два пласта (2-3 миллиметра). Первый пласт выложить на противень с пергаментной бумагой, на него выложить начинку, разровнять. Второй пласт теста необходимо сделать немного больше, его края (примерно на 2 сантиметра) необходимо подвернуть под нижний пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Ингредиенты перемешать, добавить консервированную кукурузу без жидкости, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3465,'Немного потыкать вилкой, смазать желтком, взбитым с ложкой молока. Поставить в разогретую духовку на 25-30 минут, пока он не станет красивого румяного оттенка. Затем немного остудить и присыпать сахарной пудрой. Фытыр по-египетски на дрожжевом тесте вкусно есть как теплым, так и холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3466,'Нагреть духовку (250 градусов). Форму для выпечки смазать оливковым маслом, поместить туда креветки в один слой. Взять лимонный сок, смешать с ним остальные ингредиенты, кроме петрушки. Этой смесью залить креветки',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3466,'Запекать в духовке примерно 10 минут, пока креветки не приготовятся. Вынуть запеченные креветки с лимоном и чесноком из духовки, посыпать измельченной петрушкой. По желанию можно еще добавить лимонного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3467,'Печень помыть и высушить. Лук порезать полукольцами и протушить на растительном масле (примерно 2 минуты), переложить на тарелку. В этом же масле поджарить печень (около 1 минуты с каждой стороны). Затем добавить сахар, лук, уксус, перец и мускатный орех, тушить примерно 4 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3467,'Переложить в порционные формы, прибавить 1 чайную ложку сметаны, присыпать тертым сыром и отправить куриную печень под сыром в духовку или в микроволновую печь, пока сыр не растает. Можно подавать с рисом, картофельным пюре или с салатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3468,'Плитку шоколада разделить на дольки и растопить на водяной бане. В отдельной посуде взбить сметану, сахарный песок, соль и масло. По одному вбить яйца, добавить подготовленный шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3468,'Сыпучие ингредиенты просеять и ввести в массу. Получившееся тесто переложить в форму, выпекать шоколадный пирог-брауни  в течение 25 минут, при 175 градусах. Пирог подавать теплым, с шариком мороженого.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3469,'Для приготовления основы необходимо перетереть в крошку масло, сахарный песок, какао и муку. Разъемную форму застелить пергаментом и выложить в нее часть заготовки для основы. Для приготовления начинки необходимо все подготовленные ингредиенты соединить в миске и взбить с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3469,'Получившуюся массу перелить в форму и присыпать оставшимися крошками. Выпекать пирог в течение 1 часа, при 170 градусах. По истечению отведенного времени шоколадно-творожный пирог достать из духовки и остудить, не вынимая из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3470,'Помидоры порезать на дольки, листья салата порвать. Креветки бросить в кипящую воду, с добавлением соли и специй, поварить в течение 2 минут. Затем вынуть из воды, остудить и почистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3470,'В миске соединить подготовленные ингредиенты, полить салат с помидорами черри и креветками столовой ложкой лимонного сока, заправить майонезом, добавить соль и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3471,'В отдельной посуде соединить яйца и сахар, тщательно взбить с помощью блендера. Сухие ингредиенты смешать и просеять. Все продукты, подготовленные для приготовления коржа поместить в миску и замесить тесто. Поместить его в форму и выпекать при 200 градусах, в течение 30 – 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3471,'Готовый корж остудить и разрезать на 2 части. Для приготовления крема необходимо смешать сметану, йогурт и сахарный песок, взбить. В отдельной посуде взбить сливки. Все смешать и получившимся кремом обильно промазать коржи. Клубничный торт со сливочным кремом украсить на ваш вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3472,'Репчатый лук очень мелко нашинковать или измельчить с помощью терки. Филе порезать на кусочки. Соединить лук и рыбу, ввести майонез, оставить на некоторое время. Затем, вбить яйца, добавить тертый сыр, крахмал. Все посолить, поперчить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3472,'Руками аккуратно сформировать котлеты и обжарить на разогретой сковороде, с добавлением растительного масла. Котлетки из красной рыбы с сыром можно подавать как в горячем, так и в холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3473,'В куриный фарш вмешать измельченное яблоко и лук, добавить манную крупу, посолить и поперчить по вкусу. Смешать сметану с горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3473,'Сформировать котлеты, выпекать при 200 градусах, в течение 30 минут, за 10 минут до готовности куриные котлеты с яблоком смазать подготовленной заливкой и присыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3474,'Смешать все ингредиенты для приготовления маринада (из апельсина выжать сок и добавить в маринад пару тоненьких кружочков). Курицу нарезать, поместить в маринад и оставить на 2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3475,'Овощи порезать кубиками. Куриное филе нарезать и обжарить до золотистого цвета, разложить по глиняным горшочкам. В каждый горшочек добавить субпродукты, подготовленные овощи, грибы, чеснок. Добавить немного воды, соли и специй. Горшочки закрыть крышками и поставить курицу с потрошками и грибами в духовой шкаф на 50 минут, при 200 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3476,'Смешать картофельное пюре и яйцо, добавить майонез и нашинкованный зеленый лук. Получившейся массой намазать кусочки хлеба. Сыр измельчить, смешать с майонезом, зеленью и специями. Эту массу нанести поверх картофельного пюре. Бутерброды «Картофельные ленивчики» выпекать при 175 градусах, в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3477,'Батон разрезать вдоль пополам, промазать соусом. Сыр измельчить с помощью терки и присыпать им батон. На сыр уложить подготовленную начинку(любую, на ваш вкус). Запекать быстрый сэндвич-пиццу в духовке при 260 градусах, в течение 10 – 15 минут, пока сыр не расплавится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3478,'Все сухие продукты смешать в миске, к ним присоединить масло и перетереть. Ввести поочередно мед и кефир, все перемешать и сделать тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3478,'Получившееся тесто поместить в холодильник. Затем его раскатать и с помощью фигурных формочек вырезать фигурки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3478,'Заготовки уложить на противень, устланный пекарской бумагой, выпекать медовые коржики на кефире 15 минут, при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3479,'Все подготовленные ингредиенты для маринада смешать (из половинки лимона выжать в маринад сок). Куриные крылья разрезать по хрящам на 3 части, залить маринадом и оставить на пару часов, выложить в форму. Запечь куриные крылья в сметанном маринаде в духовке в течение 40 минут, при 150 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3480,'Сварить куриное филе и нарезать его на кусочки. Овощи крупно нашинковать и пассировать. Перемешать филе и овощи, вмешать сметану, зелень, соль и перец добавить по вкусу. Смешать все подготовленные для теста ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3480,'Форму промазать маслом, часть теста поместить в форму, сверху положить всю начинку и накрыть оставшимся тестом. Заливной пирог с курицей  и овощами выпекать в течение 30 минут, при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3481,'Замесить тесто, по консистенции оно должно быть как на оладьи. Ингредиенты для начинки измельчить. Тесто вылить на сковороду, сверху вылить немного соуса, выложить все подготовленные продукты и готовить быструю пиццу под закрытой крышкой в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3482,'В отдельной миске смешать специи, соль и крахмал и муку. Четверть от этой смеси переложить в другую посуду, добавить разрыхлитель и пиво, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3482,'Рыбу, предварительно порезанную на кусочки, промытую и обсушенную, сначала обвалять в мучной смеси, а затем поместить в пивную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3482,'Филе трески в пивной панировке обжарить на раскаленной сковороде с добавлением большого количества растительного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3483,'В емкость положить все специи, добавить имбирь, всыпать соду, все смешать, затем присоединить муку. В отдельной миске размять сахарный песок и масло. Вбить яйца, добавить мед, все перемешать. Соединить две смеси, ввести мучную в масляную. Тщательно перемешать, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3483,'Готовое тесто охладить и раскатать, вырезать фигурки. Заготовки выпекать в течение 7 минут, в хорошо разогретой духовке. Молоко и сахарную пудру перемешать до образования однородной массы — глазури. Покрыть имбирно-медовое печенье получившейся сахарной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3484,'Свежий картофель и 1 луковицу почистить и натереть на терке, отжать. Вмешать яйцо, добавить сметану и порциями ввести муку. Соль и специи добавить по вкусу. Для начинки необходимо вторую луковицу так же натереть и перемешать с мясным фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3484,'На горячую сковороду выложить порцию картофельного теста, обжарить с одной стороны, положить начинку и сверху положить ложку теста. Затем драники из картофеля с мясным фаршем обжарить с другой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3485,'Колбасу нарезать тонкими ломтиками, сыр натереть, лаваш смазать кетчупом и майонезом. Уложить ломтики колбасы и присыпать их сыром, лаваш скрутить, смазать майонезом и запечь рулет из тонкого лаваша с начинкой в духовке до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5814,'Сварить кофе нью-орлеанский с цикорием, разлить по горячим кружкам, добавить горячее молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3486,'Вишню предварительно разморозить и разложить по жаропрочным формам, присыпать пудрой. Яйца и сахар смешать, всыпать крахмал, ванильный сахар и муку. Добавить теплое молоко и этой смесью залить вишню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3486,'Запекать ванильный клафути с вишней в духовом шкафу при 180 градусах, в течение 20 минут. Готовый десерт присыпать корицей непосредственно перед подачей к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3487,'Грудку нарезать кубиками, лук мелко нашинковать. Предварительно отваренный картофель и отварную морковь натереть на терке. Яйцо сварить вкрутую и так же натереть. Для соуса: чеснок добавить в майонез и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3487,'На сервировочное блюдо выложить слоями все ингредиенты поочередно, сначала картофель, яйца, грудка, лук и морковь. Каждый слой тщательно промазать соусом. Салат с копченой грудкой и чесночным соусом обильно присыпать натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3488,'Муку и дрожжи перетереть с маслом до образования крошки. Вбить яйца, добавить соль и перец по вкусу. Порционно влить молоко и замесить тесто, оно не должно прилипать к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3488,'Тесто убрать в тепло на пару часов. Для приготовления начинки необходимо смешать творог, яйца, нашинкованную зелень и лук, все залить сливками, соль и перец по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3488,'Тесто раскатать и уложить в форму, положить начинку, края теста загнуть таким образом, чтобы пирог стал похож на ватрушку. Смазать пирог с творожно-луковой начинкой с яйцом, выпекать в духовом шкафу в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3489,'Все ингредиенты отварить и остудить. Куриную грудку разделить на волокна. Яйца, картофель и свеклу натереть на терке. Репчатый лук мелко нашинковать и обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3489,'На середину блюда поставить стакан и вокруг него разложить все подготовленные ингредиенты слоями, в определенной последовательности: картофель, свекла, грецкий орех, курица, лук, яйца, курица. Каждый слой промазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3489,'Салат «Гранатовый браслет» с куриной грудкой убрать на холод, перед подачей промазать майонезом и украсить зернами граната и орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3490,'Свеклу нарезать мелкими брусочками, филе сельди порезать на кусочки. Лук нашинковать, яйца отварить и натереть. В отдельной посуде соединить яйца и лук, заправить майонезом, сдобрить солью и специями. На рабочую поверхность положить бамбуковый коврик и застелить его пищевой пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3490,'На подготовленную поверхность выложить лаваш или блин, тонким слоем промазать его яичной смесью, затем уложить кусочки свеклы и сельди, свернуть рулет. Через некоторое время сельдь с овощами в тонком лаваше разрезать на роллы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3491,'Рис отварить, соединить с фаршем и нашинкованным луком, с добавлением соли и специй.  Капустные листы варить в течение 15 минут. Морковь натереть и обжарить. В жаропрочную форму выложить капустные листы, сверху фарш, затем морковь. Все слои повторить, последний слой должен быть капустный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3491,'Для заливки смешать яйца и сметану, получившейся смесью залить запеканку. Выпекать при температуре 200 градусов до образования золотистой корочки, затем, жар уменьшить до 160 градусов и продолжать готовить в течение часа. Нарезать слоеную запеканку «Ленивые голубцы» порционно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3492,'Желтки смешать с сахарным песком до белой пены. Белки тщательно взбить до пиков. Соединить обе смеси, аккуратно перемешать. Все сухие продукты просеять и порционно ввести в яичную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3492,'Очень аккуратно перемешать, чтобы не повредить белок. Тесто поместить в форму, выпекать при 180 градусов, в течение 40 минут. Готовый бисквит остудить, затем разделить на две части и пропитать сиропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3492,'В молоко поместить желатин, после набухания нагреть на водяной бане. Сметану и сахар смешать. Сливки взбить с сахарной пудрой, обе смеси соединить, влить желатин. Бананы нарезать на кубики и добавить в крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3492,'Нижнюю часть бисквита поместить обратно в форму, вылить весь крем и накрыть верхней частью. Убрать шоколадный торт «Бонжур» с банановым суфле на холод, до полного застывания начинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3504,'Растереть мягкое сливочное масло и сахар. Вбить яйца, положить творог, насыпать муку. Размешать тесто до однородности, оно должно стать, как пластилин. Выложить тесто на бумагу, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3493,'Приготовить тесто: в эмалированной посуде растереть яйца, взбить с медом и сахаром. Положить масло и поставить емкость на водяную баню, чтобы растаяло масло. После этого добавить соду и подождать, пока она будет пениться. В полученную массу насыпать муку, замесить пластичное тесто, чуть-чуть липнущее к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3493,'Поделить тесто на восемь одинаковых частей, раскатать коржи приблизительно одного размера. Каждый корж положить на противень, обрезать по кругу лишние края. Можно использовать крышку от кастрюли. Обрезки готовить с коржами. Выпекать до коричневого цвета. Должно получиться восемь коржиков и чуть-чуть обрезков, которые понадобятся для присыпки тортика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3493,'Приготовить крем: в посуду из-под теста вбить яйца, насыпать муку и сахар. Налить молоко, положить масло, поставить на водяную баню. Заварить густой крем, чтобы не стекал с коржей. Охладить до комнатной температуры. Быстрей остынет, если поместить в емкость с холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3493,'Взбить крем до однородности. Намазать остывшие коржи кремом. Измельчить обрезки теста, посыпать полученной крошкой тортик со всех сторон. Отставить медовик с молочным заварным кремом минут на двадцать для пропитки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3494,'Приготовить начинку для кузикмяка: измельчить лук, обжарить на сливочном масле. Измельчить укроп. Отварить картофель в подсоленной воде. Приготовить из картофеля пюре. В пюре положить пассированный лук, зелень, масло сливочное, 100 мл молока. Все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3494,'В оставшееся молоко вбить яйца, посыпать солью, насыпать муку. Замесить эластичное тесто. Тоненько раскатать тесто. Вырезать из теста кружочки при помощи блюдца диаметром 18 сантиметр. Сложить круглые заготовки на тарелочку, присыпая каждый мукой, чтобы не слиплись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3494,'Обжаривать лепешки на сухой сковороде. Когда лепешки покрываются пузырьками и появляются золотистые пятнышки, они готовы. Сверху намазать лепешки топленым маслом. На готовую лепешку, смазанную маслом положить начинку до серединки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3494,'Сложить пополам, намазать маслом. Картофельные лепешки «Кузикмяк» по-татарски накрыть полотенцем, отставить на тридцать минут, чтобы масло пропиталось,  подавать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3495,'Сделать тесто: соединить сахар, яйцо, мягкое масло, перемешать. Насыпать разрыхлитель и муку. Добавить щепотку соли, перемешать до однородности. Отправить минут на тридцать в холодильник. В смазанную формочку положить тесто, распределить его тоненьким слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3495,'Приготовить начинку: соединить сахар, творог, яйца, крахмал. Вылить массу на творог. Почистить яблоки, вырезать сердцевину, порезать дольками. Достаточно плотно воткнуть творожную начинку, посыпать корицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3495,'Готовить в духовке минут сорок, соблюдая температуру 180 градусов. Достать пирог, остудить прямо в форме для запекания, чтобы он не потерял форму. Достать творожно-яблочный пирог «Осенняя мелодия» из формы и порезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3496,'Порезать колбасу на маленькие кусочки, мелко натереть сыр, измельчить зелень. Перемешать. Порезать на полосочки лаваш с помощью ножниц или ножа. Развернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3496,'На краешек полоски положить начинку, свернуть уголком раза в четыре, чтобы скрыть всю начинку, лишнее обрезать. Таким способом свернуть все пирожки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3496,'Разогреть на сковороде растительное масло, обжарить пирожки из тонкого лаваша с сыром и ветчиной с двух сторон. На обжарку уйдет всего несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3497,'Взбить яйца с солью или сахаром, налить молоко, снова все взбить. Перелить массу в баночку с закручивающейся крышечкой. Поставить баночку в кастрюлю с водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3497,'После закипания воды, варить минут 25. Крышку закручивать не сильно. Можно положить в диетический омлет тертую морковь, свежую измельченную зелень и многое другое.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3498,'Растереть сахар с творогом, вбить яйца. Просеять муку, разрыхлитель, ванилин. Пересыпать в творожную смесь. В казан налить растительное масло, разогреть. Влажными руками взять чуть-чуть теста, скатать шарики диаметром приблизительно четыре сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3518,'Отправить меренги в духовку на 50-180 минут в зависимости от размера. Подсушивать при температуре 100 градусов. Выключить духовку, открыть ее. Остудить меренги, не доставая с духовки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3498,'Бросить их в кипящее масло, жарить пончики, пока не всплывут и не станут коричневыми. Доставать при помощи шумовки. После первой порции убавить огонь. Готовые творожные пончики выложить на специальную бумагу, дать стечь лишнему маслу, посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3499,'Соединить все сухие ингредиенты, перемешать. Соединить жидкие ингредиенты, взбить вилочкой. Соединить обе смеси. Перемешать до однородного состояния, чтобы получилось негустое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3499,'Вылить в формочки по ложке теста, положить по ложке варенья, на него опять тесто. Формочки нужно наполнить на 2/3. Отправить  маффины «Бомбочки» с вареньем на 25 минут в духовку, готовить до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3500,'Взбить на водяной бане желтки и сахар до пышной массы. Нужно растворить сахар,  масса должна быть густой и светлой. Это занимает минут десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3500,'Убрать с огня, налить сироп, размешать, остудить при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3500,'Взбить сливки, аккуратно соединить с желтками. Разлить смесь по формочкам, отправить малиновое парфе на сливках в морозилку на три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3501,'Соединить сахар и яйца, взбить. Размягчить масло. Развести соду в воде. Соединить все ингредиенты для коржей, не считая какао, замесить тесто. Поделить его на 3 части, в одну положить какао, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3501,'Смазать формочку маслом, положить одну часть в формочку, выровнять, выпекать минут десять, соблюдая температуру 200 градусов. Таким же способом испечь остальные части. Если необходимо, выравнивать их по размеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3501,'Приготовить крем: соединить сгущенное молоко со сметаной, перемешать. Собрать тортик, чтобы темный корж был посередине. Все слои сметанного торта «Паутинка» смазать кремом. Растопить шоколад, нарисовать зубочисткой рисунок в виде паутинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3502,'Налить в кастрюльку молоко и сливки, подогреть, насыпать муку. Активно и быстро перемешать, чтобы не было комочков. Через несколько минут смесь загустеет и получится вязкое заварное тесто. Если все-таки комочки образовались, то разбить их блендером. Если его нет, то можно воспользоваться другим способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3502,'Насыпать муку в кастрюльку, медленно подмешивать молочную массу, перемешивая. Таким образом, густое тесто будет разбавлено молоком. В зависимости от силы температуры огня, на приготовление может уйти от 15 до 20 минут. Необходимо определять готовность на глаз, наблюдая за консистенцией. Готовое тесто убрать с огня, охладить, перемешать. Насыпать разрыхлитель, сахар, мускатный орех, соль, добавить желтки по одному.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3502,'Разогреть духовку. На противень постелить пергамент, смазать маслом. Взбить белки, ложкой переложить в тесто, перемешать осторожно, чтобы масса не упала. Делать легкие движения снизу вверх, словно насыщая его кислородом. Вылить тесто на противень, поставить запекаться в духовку минут на тридцать. Оно начнет подниматься и опускаться – не стоит этого пугаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3502,'Почистить авокадо, порезать на маленькие кусочки. Измельчить укроп. Порезать лосося на маленькие кубики. В емкости соединить сметану, крем-сыр, укроп и сливки. Размешать или миксером, или вручную. Положить в творожную массу рыбу, сок лимона, авокадо. Размешать. Достать готовое тесто. На доску постелить пергамент, положить тесто верхом вниз, осторожно снять пергамент сверху. Остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3502,'Когда пласт остынет, положить начинку, края снизу оставить свободными, чтобы закрепить рулетик. Помогая пергаментом, осторожно свернуть его плотно. Серединку прижимать руками, но сильно не давить. Тесто получается нежное. Отправить рулет с лососем, сыром и авокадо в холодильник часа на два, чтобы застыл.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3503,'Протереть творог через сито, чтобы получилась равномерная структура. Налить кефир, насыпать соду, соль, манную крупу, ванилин. Взбить яйца с сахаром, переложить в творожную смесь. Размешать все до однородности, отставить минут на двадцать, чтобы набухла манка. Можно положить изюм или вяленую клюкву.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3503,'Положить тесто в формочку, отправить на сорок минут в духовку, соблюдать температуру 170 градусов. Запеканка должна подняться и стать золотистой. Достать из духовки, остудить, она чуть-чуть осядет. Достать диетическую творожную запеканку с клюквой, перевернув форму на тарелку, порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3504,'Придать форму можно с помощью ложки. Или можно воспользоваться кондитерским шприцем. На тесто положить ягодки, чуть-чуть вдавить их, поставить печенье из творожного теста с малиной на сорок минут в духовку. Готовить при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3505,'Разогреть духовку. Соединить сок лимона, оливковое масло, измельченный чеснок в большой посуде. Помыть картофель. Тоненько порезать или потереть на специальную терку. Приблизительно по 1 миллиметру. Равномерно обмазать картофель в масляной смеси. Разложить картофель в формочке (25 сантиметров) в виде гармошки. Готовить шестьдесят минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3505,'Достать из духовки. Обмазать повторно оливковым маслом по вершине ломтиков. Между кусочками картофеля положить тимьян и грудинку. Посыпать перцем и солью. Снова отправить в духовку, готовить хрустящий картофель с грудинкой еще тридцать минут или до полной готовности. Края картофеля должны быть хрустящими, а середина мягкая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3506,'В подогретое до теплого состояния молоко налить воду, насыпать сахар, дрожжи, отставить минут на семь, чтобы поднялась шапочка. Насыпать соль, просеянную муку, добавить 6 столовых ложек растительного масла. Замесить тесто. Затем добавить еще 1 столовую ложку масла (растительное).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3506,'Накрыть тесто теплым полотенцем, отставить часа на полтора, за весь период его необходимо несколько раз мять. Поделить тесто на маленькие шарики размером как мандарин, сформировать пирожки и жарить на растительном масле, как можно дольше. Выложить готовые пирожки с луком и яйцом на салфетки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3507,'Вымыть небольшие помидоры, величиной со сливу, разноцветный сладкий болгарский перец, некрупные кабачки, баклажаны. Кабачки и баклажаны нарезать по диагонали, пластинками, толщиной в 1 см. Помидоры и перцы разрезать вдоль, на четыре части каждый, у перцев удалить семенные камеры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3507,'Чеснок мелко измельчить и смешать с оливковым маслом, залить смесью овощи. Для приготовления заправки мелко порубить вымытую петрушку, смешать с нарубленным чесноком, сахарным песком и бальзамическим уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3507,'Взбить массу венчиком, влить оливковое масло, посолить, поперчить по вкусу. Разогреть сухую сковороду, обжарить кабачки и баклажаны, по две минуты с каждой стороны. Выложить на бумажные полотенца, чтобы удалить излишки жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3507,'Обжарить помидоры и перцы, по 1,5 минуты с каждой стороны, также выложить на полотенца. Остывшие овощи переложить на блюдо, влить готовую заправку, перемешать.  Оригинальный салат из обжаренных овощей готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3508,'Отварить до готовности куриное филе, нарезать. Промыть и нашинковать листья пекинской капусты. Очистить и измельчить яблоко. Все ингредиенты перемешать, добавить консервированную кукурузу без жидкости, майонез, рубленую зелень и специи по вкусу. Перед подачей к столу, салат из куриной грудки тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3509,'Растереть сырые яйца с сахарным песком, добавить пшеничную муку, какао-порошок, тертые орехи и сливочное масло, ванилин, перемешать. Влить молоко и снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3509,'Смесь варить на тихом огне до загустения, постоянно помешивать. Разложить пасту «Нутелла» с орехами  в небольшие стеклянные баночки, хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3510,'Растворить свежие или сухие дрожжи в теплой воде. Влить в просеянную муку, добавить сахар, оливковое масло, соль по вкусу. Тесто замесить и положить в теплое место. Для начинки очистить помидоры: сделать крестообразный надрез и опустить в кипяток на две минуты. Кожуру очистить, удалить семенную камеру, порезать кусочками, откинуть на сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3510,'Натереть твердый сыр, Пармезан или Российский, добавить нарезанную ветчину и приправы, зеленый или сушеный базилик, зелень петушки. Перемешать. Раскатать тесто, выложить начинку на половину лепешки, закрыть второй половиной и защипать косичкой в форме полумесяца. Выложить пиццу «Кальцоне» по-итальянски на противень, сбрызнуть теплой водой и печь в течение 20 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3511,'Взбить сырые яйца с сахаром, ванилином, растопленным сливочным маслом и йогуртом. Смешать просеянную пшеничную муку с содой или разрыхлителем, добавлять к яичной массе порциями, перемешивать. Тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8394,'Выложить сладкий болгарский перец, нарезанный соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3511,'Формочки для кексов смазать растопленным сливочным маслом, выложить по одной столовой ложке теста. В середину каждой формочки – по столовой ложке любого ягодного джема или конфитюра, покрыть оставшимся тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3511,'Кексы печь в разогретой до 190 градусов духовке около 20 минут. Кексы на йогурте с джемом должны подрумяниться, готовность можно проверить зубочисткой. Готовую выпечку остудить и посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3512,'Для приготовления теста смешать сырой желток, сахарный песок, растопленное сливочное масло. Добавить просеянную муку, смешанную с разрыхлителем и какао-порошком. Замесить тесто. Форму для выпечки торта выстлать бумагой для выпечки, выложить две трети массы, разровнять. Остаток теста заморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3512,'Для начинки взбить сырые белки с сахарным песком, добавить кокосовую стружку, перемешать. Выложить массу на тесто в форме. Оставшееся замороженное тесто быстро натереть поверх начинки. Печь при температуре 180 градусов в течение часа. Охладить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3512,'Взбить мягкое сливочное масло до пышности. Отдельно прогреть сырые желтки с сахаром и молоком, варить до густоты кефира, охладить. Перемешать с взбитым маслом, добавлять порциями, постепенно. Влить немного коньяка.  Полученным кремом смазать торт сверху и с боков, поставить в холодильник на несколько часов или на всю ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3512,'Залить шоколадный торт «Баунти» со сливочным кремом глазурью, приготовленной из поломанного темного или молочного шоколада или какао-порошка, прогретого со сливочным маслом на водяной бане до гладкого, однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3513,'Нарезать белый хлеб, в середине каждого кусочка вырезать квадратное отверстие — «окошко». Смешать сырые яйца, кубики ветчины, рубленый зеленый лук, соль. Добавить порезанные кусочками помидоры, сладкий болгарский перец разного цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3513,'Каждый ломтик выложить на сковороду, влить в отверстие полученную смесь с помощью столовой ложки, обжарить тосты с ветчиной к завтраку с двух сторон, до полной готовности начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3514,'Багет разрезать пополам вдоль, затем каждую часть разломить еще на три. Нарезать кружками копченую колбасу, репчатый лук, болгарский перец. Оливки  – кольцами, пластинками – грибы, ветчину, консервированный ананас.  Обжарить любой нежирный мясной фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3514,'Нагреть духовой шкаф до температуры 210 градусов, выложить багет на противень, предварительно застеленный бумагой для выпечки. На каждый кусочек намазать томатный соус или пасту, выложить сыр моцарелла  и начинки по вкусу. Печь оригинальные пиццы на багете до расплавления сыра в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3515,'Натереть сыр. Свежие или размороженные грибы немного обжарить с рубленым луком или без него, соль – по вкусу. Если для приготовления блюда взяты консервированные грибы, то с них просто нужно слить жидкость. Порубить зелень, всё перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3515,'Разложить начинку на армянский тонкий лаваш равномерно, не доходя до краев. Свернуть рулетами, торцевые края загнуть внутрь. Закуску смазать чуть взбитым яйцом или майонезом, поставить в духовку, разогретую до 180 – 200 градусов, печь рулет из тонкого лаваша с сыром и грибами до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3516,'Нарезать соломкой ветчину, твердый сыр, отварное филе кальмара. Кубиками – вареное яйцо, репчатый лук. Мелко порубить зелень укропа и петрушки, смешать с майонезом. Все ингредиенты салата «Нежнейший» перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3517,'Смешать творог, сахарный песок, сырое яйцо, муку и соль по вкусу. Замесить тесто, оно должно быть мягким, скатать в шар, оставить на некоторое время для набухания клейковины.  Разделить массу на четыре части, раскатать колбасками на присыпанном мукой столе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3517,'Нарезать на кусочки, отварить в подсоленной воде. После всплытия варить еще пять минут. Ленивые творожные вареники к завтраку подать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3518,'Взбить белки, медленно насыпая сахар. Продолжать взбивать, пока смесь не будет плотной. Противень покрыть пергаментом. На него выложить тесто с помощью ложки, но лучше использовать кулинарный мешочек с фигурными насадками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4367,'Залить заварочный чайник кипятком, дать постоять 2-3 минуты, слить воду, засыпать в прогретый чайник заварку, залить крутым кипятком, настаивать 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3519,'В емкости соединить сметану, майонез и яйца, насыпать соду, муку. Посыпать солью. Тесто должно быть, как густая сметана. Приготовить начинку: почистить лук, картофель. Измельчить лук. Размять вилкой рыбу. Смазать маслом формочку для выпечки, налить 1/2 теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3519,'Натереть мелко картофель и выложить слоем в 1 сантиметр. Уложить  на него лук, сверху измельченные консервы. Накрыть остальным тестом. Отправить пирог с рыбной консервой на сорок минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3520,'Взбить с помощью миксера сырые яйца, сахарный песок, ванилин из пакетика. Влить растительное масло, продолжать взбивать, затем – лимонад. Всыпать частями пшеничную просеянную муку, заранее перемешать её с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3520,'Тесто должно получиться жидким, как для приготовления оладий. Выпечь оригинальный бисквит на лимонаде в духовке при температуре 180 градусов, в течение получаса. Форма для выпечки должна быть высокой, не менее 12 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3521,'Отваривать замороженные пельмени минут пять в подсоленной воде. Переложить в дуршлаг, чтобы стекла жидкость. Растопить масло (сливочное), обжарить пельмени. Обжарить на растительном масле лук. Бросить тертую морковь, потом грибы, обжаривать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3521,'Положить в горшочек чуть-чуть овощей, на них пельмени, сверху опять овощи. Развести сметану водой, вылить в горшочек до середины. Засыпать тертым сыром. Готовить жареные пельмени с овощами,  не накрывая крышкой, минут тридцать при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3522,'Просеять муку, насыпать дрожжи, соль, положить корицу, сахар, масло. Взбить яйца, размешать. Влить в смесь холодное молоко, непрерывно помешивая. Готовое тесто раскатать в лепешку.  В середину лепешки положить вишню, сомкнуть краешки, мешать тесто еще примерно четыре минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3522,'Разделить тесто на десять частей, скатать шарики. Бумажные формочки смазать маслом. Оставить минут на 45.  На булочках сделать надрезы крест-накрест. Развести водой муку. Положить смесь в кондитерский мешок, заполнить надрезы. Отправить пасхальные вишневые булочки на пятнадцать минут в духовку, выпекать, соблюдая температуру 180 градусов',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3523,'Очень хорошо растопить масло и тщательно перемешать с крошкой из печенья, чтобы получилась однородная масса. Взять форму, лучше всего разъемную, так будет проще вынимать торт. Постелить пергаментную бумагу, что тоже облегчит вынимание десерта из формs.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3523,'В формe равномерно выложить крошку, чуть-чуть уплотнить, отправить торт в холодильник, чтобы он застыл, минут на тридцать. Предварительно формe необходимо накрыть полиэтиленом, чтобы не впитались посторонние запахи с холодильника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3523,'Пока торт находится в холодильнике, в глубокую посуду налить полстакана воды, насыпать желатин, размешать, оставить минут на 25 для набухания. Почистить киви от кожуры, порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3523,'Положить в кастрюльку, добавить сок лимона, насыпать сахар, поставить на плиту. Киви должно нагреться и пустить сок. Полученый сироп охладить, добавить желатин, йогурт, перемешать. Достать корж, положить на него бананы, порезанные на тоненькие пластинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3523,'Практически в конце, на торт вылить фруктовую начинку сверху бананов и поставить в морозилку минимум часов на шесть, а лучше на ночь. Достать легкий торт «Шедевр» на йогурте из морозилки, осторожно извлечь из формы и снять бумагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3524,'Капусту промыть, обсушить, порезать, посыпать солью и  обмять. Нарезать помидоры, колбасу, яйца, зелень. Положить кукурузу, предварительно слив жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3524,'Порезать на кубики батон и подсушить его на сковороде. Смешать все ингредиенты, кроме сухариков, посыпать перцем, солью. Посыпать салат из пекинской капусты перед подачей на стол, сухариками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3525,'Положить все ингредиенты в небольшую баночку из стекла. Закрыть плотно крышечкой, потрясти. Разрыхлитель равномерно распределяется по тесту и не дает лишних привкусов и запахов, в отличие от обычной соды, гашенной укусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3526,'Пропустить мясо через мясорубку. Измельчить лук и растереть. Замочить в сливках булочку. Мелко натереть капусту или картофель. Все смешать, посыпать приправами, положить прессованный чесночок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4367,'К заварке добавить сметану, сливки, соль, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3527,'Переложить творог в кастрюльку, налить молоко, поставить на медленный огонь. Готовить минут пятнадцать, время от времени помешивая. Смесь будет разделяться, будет выделяться сыворотка. Когда закипит, варить еще минут десять. Откинуть смесь на ситечко, чтобы стекла сыворотка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3527,'Положить творог обратно в кастрюльку. Вбить яйцо, насыпать соду, соль, варить минут десять на маленьком огне. Когда смесь совсем расплавится, станет тягучей, готовить еще пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3527,'Смазать формочку растительным маслом, и сразу (так как быстро теряется пластичность), переложить сырную массу. Дать остыть, затем отправить диетический творожный сыр в холодильник для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3528,'Перемешать куриный фарш, манную крупу, яйцо, желток. Добавить измельченный сладкий перец, репчатый лук и лук-порей, зелень, соль, молотые перцы. Разложить смесь по формочкам. Накрыть бумагой для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3528,'Отправить на час в духовку, готовить при температуре 180 градусов. Достать, уложить сверху полоски разных сыров, посыпать приправами, запекать куриный батон с перцем минут пятнадцать, чтобы расплавился сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3529,'Смешать воду с молоком, довести до кипения, охладить. Добавить растительное масло, насыпать соль, сахар, размешать. Вбить яйцо, насыпать дрожжи, муку, размешать. Отставить минут на десять. Затем по чуть-чуть досыпая муку, месить тесто примерно 7 минут. Смазать сверху растительным маслом и отставить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3529,'Из толстой бумаги свернуть конусы, обернуть их фольгой. Достать тесто, разделить на восемь частей, поместить на 5 минут в морозилку охлаждаться. Скатать все части в колбаску приблизительно 90 сантиметров длиной. Завернуть вокруг конуса колбаску из теста по диагонали, начинать с острого кончика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3529,'Взбить яйцо с молоком, намазать конусы, посыпать кунжутом и маком. Отставить тесто на полчаса. Выпекать 20 минут, соблюдая температуру 175 градусов. Дать постоять, достать конус, нафаршировать хрустящие трубочки какой-нибудь начинкой или любимым салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3530,'В манную крупу влить кефир, отставить на полчаса для набухания. Отдельно растереть яйца, соль, обычный и ванильный сахар. Крупно натереть на терке лимон вместе с цедрой. Все ингредиенты соединить. Всыпать в смесь разрыхлитель и муку. Форму для пирога застелить пергаментом, смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3530,'Вылить тесто в форму. Поставить ее в предварительно разогретую духовку и готовить при температуре 200 градусов. Примерно через минут двадцать проверить готовность зубочисткой. Переложить нежный лимонный манник на тарелку и посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3531,'Смешать сухие специи. Куриные крылышки посыпать солью, приготовленными специями и полить маслом. Втереть в крылья получившийся маринад и отставить минут на пятнадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3531,'Готовить крылья в мультиварке примерно 17 минут при температуре 200 градусов. Подать острые куриные крылышки с зеленью и овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3532,'Взбить яйца с сахаром, положить йогурт и предварительно растопленное масло. Муку соединить с разрыхлителем, насыпать в смесь и замесить густое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3532,'Разложить тесто по формочкам, заполняя примерно на 2/3. Готовить клубничные маффины на йогурте в духовке 25 минут, соблюдая температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3533,'Взять два ломтика белого хлеба или батона, толщиной примерно 2 сантиметра, вынуть серединку. Порезать бекон на кубики. Измельчить укроп и лук. Выпекать при температуре 180 градусов. Заранее приготовленный кусочек фольги смазать оливковым маслом и положить на нее хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3533,'Обвернуть кусок хлеба так, чтобы получился кораблик, стенки должны плотно прилегать к хлебу. В середину хлебного кусочка вбить яйцо, добавить перец и соль. Выложить сверху 1/2 часть нарезанной колбасы, укроп, лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3533,'Сверху вбить еще яйцо и снова добавить соль и перец. В уголок положить половинку черри. На краешки хлеба капнуть несколько капель оливкового масла. Повторить процедуру со вторым ломтиком хлеба. Готовить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3534,'Замесить тесто и дать ему настояться 20 минут, порезать тесто на куски, как для пирожков, раскатать до тонких лепешек и выпекать на сухой раскаленной сковороде 5-6 минут до образования румяной красивой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3534,'Выложить на одну половину лепешки картофельную начинку, лепешку согнуть пополам, соединить концы и придавить края вилкой, чтобы лепешки на сгибе не ломались, начинить их нужно в горячем виде (для этого завернуть обжаренные лепешки в полотенце, чтобы оставались мягкими и не остывали). ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3534,'Смазать поверхность лепешек с картофелем «Кыстыбай кузикмяк» по-татарски сливочным растопленным маслом, лепешки подавать на стол горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3535,'Филе кальмаров вымыть, очистить, удалить внутренности. Отварить в кипящей воде в течение двух-трех минут, воду подсолить по вкусу. Вынуть филе, охладить, нарезать соломкой,  плавленый сыр охладить в холодильнике и натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3535,'Отварить и нарезать кубиками куриные яйца. Мелко порезать зелень петрушки, укропа. Пропустить через пресс очищенный чеснок, смешать с майонезом. Соединить все ингредиенты, заправить майонезом с чесноком. Подать салат с кальмаром, сыром и чесночным соусом на листьях зеленого салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3536,'Взбить яйца с сахаром до получения пышной светлой массы. Мёд переложить в небольшую кастрюлю с толстым дном, прогреть до 50 градусов. Всыпать соду, постоянно помешивать, прогревать на среднем огне. Масса будет пениться, её нужно довести до темно-карамельного цвета. Горячий мёд с содой вмешать в яичную смесь, осторожно, порциями, чтобы яйца не свернулись.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3536,'Добавить просеянную пшеничную муку, тоже в несколько приемов. Тесто должно получиться полужидким. Форму для выпечки выстелить пергаментом, вылить тесто. Печь 40 минут при температуре 160 градусов. Для приготовления крема смешать яйца, сахарный песок и молоко. Всыпать муку, перемешать. Смесь прогреть на среднем огне, помешивая, до загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3536,'Перелить заварную массу в миску, накрыть пищевой пленкой и дать остыть. Сливочное масло комнатной температуры взбить до побеления, соединить с заварной основой и снова взбить. Крем должен получиться гладким и однородным. Выпеченный бисквит разрезать на три коржа, промазать и украсить готовый торт «Медовый» с заварным кремом, крошкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3537,'Подсолить воду, довести до кипения и отварить спагетти почти до готовности, время варки указано на упаковке. Откинуть на дуршлаг и вернуть в сухую кастрюлю. Отдельно измельчить бекон, порубить очищенный репчатый лук и чеснок. Все ингредиенты обжарить на сковороде до золотистого цвета в течение 5 – 6 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3537,'При необходимости в процессе обжаривания добавить масло. Взбить сырые яйца с тертым сыром и подогретыми сливками, добавить молотый черный перец. В отваренные макароны всыпать бекон с чесноком и сливочную смесь, перемешать и подать в горячем виде. При подаче посыпать пасту «Карбонара» с беконом тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3538,'Смесь воды и молока немного подогреть, добавить свежие дрожжи и сахарный песок, ингредиенты полностью растворить. Добавить оливковое масло и просеянную муку, соль по вкусу, замесить эластичное тесто. Миску с массой накрыть тканью и оставить подниматься, до увеличения объема теста в два-три раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3538,'Для начинки нарезать репчатый лук кубиками, обжарить на растительном масле до мягкости. Добавить фарш из говядины, обжарить до коричневого цвета, соль и перец – по вкусу, посыпать сухой приправой для пиццы и немного остудить. Смешать массу с кетчупом или свежими нарезанными помидорами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3538,'Тесто раскатать, выложить на противень. На половину лепешки нанести начинку, оставить края свободными. Сверху – нарезанный кусочками сыр моцарелла, посыпать тертым твердым сыром, накрыть второй половиной теста, защипать края. Проткнуть верхний слой вилкой в нескольких местах для выхода пара во время выпечки. Печь в духовке при 220 градусах до румяного цвета в течение 25 минут. Подать на стол пиццу «Кальцоне» с сыром и мясным фаршем, порезав на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3539,'Готовые ржаные сухарики смешать с майонезом, оставить несколько штук для украшения. Выложить в разъемную форму, поставленную на блюдо, сверху – слой зеленого консервированного горошка и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3547,'Замесить тесто из пшеничной муки, растопленного сливочного масла, соды, погашенной уксусом или лимонным соком, и густой сметаны. Замесить и оставить на полчаса для набухания клейковины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8394,'Посолить, готовить две-три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3539,'Нарезать ветчину, выложить в форму, снова майонез, нарезанные маринованные огурцы, тертые отваренные яйца, смешанные с небольшим количеством майонеза. Салат «На траве дрова»  с ветчиной посыпать зеленью укропа или лука, украсить целыми сухариками. Дать блюду постоять два часа. Снять бортики и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3540,'Перемешать до однородной массы размятый или протертый творог, сырые яйца, дополнительно один белок, сахарный песок, пакетик ванилина, манную крупу, растопленное сливочное масло. В массу можно добавить изюм, курагу или чернослив, нарезанный кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3540,'Форму для выпечки смазать маслом, обсыпать манной крупой, вылить тесто. Верх смазать оставшимся желтком. Выпечь творожную запеканку  в течение 40 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3541,'Вскипятить молоко. Отдельно растереть сырые желтки с сахаром, ванилином и просеянной мукой. Влить горячее молоко, перемешать. Варить заварной крем на среднем огне, до загустения массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3542,'Смешать молотый фундук, сырые яйца, сахарный песок и разрыхлитель. Форму для микроволновой печи смазать маслом и присыпать мукой. Печь массу при соответствующем режиме в течение пяти минут. Намного охладить бисквит, разрезать и промазать кремом. Ореховый торт без муки посыпать сахарной пудрой, украсить взбитыми сливками и фруктами, полить растопленным шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3543,'Взять говядину или баранину по своему вкусу, сварить наваристый бульон, процедить, отлить пол стакана для теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3543,'Замешать в средней посуде тесто для клецек: для этого в просеянной муке сделать углубление, туда вбить 1-2 яйца, посолить и поперчить, постепенно долить бульон и замесить тесто, проследить, чтобы к этому времени бульон остыл, в противном случае, если он останется горячим, может свернуться яичный белок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3543,'Консистенцию теста сделать жидкой, но не настолько, чтобы оно сразу стекало с ложки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3543,'Отрывать пальцами или брать ложкой небольшие куски теста, после чего опускать в кипящий бульон, варить клецки «Семах» по-татарски до тех пор, пока они не всплывут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3543,'Чтобы приготовить вкусный суп с клецками, перед их опусканием положить в бульон картофель и обжаренный лук с морковкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'Отделить мясо от костей, мякоть говядины прокрутить в мясорубке, желательно дважды, а из костей сварить бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'Лук очистить, тонко нашинковать и обжарить, зелень мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'В получившийся говяжий фарш добавить лук, зелень и специи, хорошо вымешать фарш руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'Для теста смешать яйцо, муку и воду, хорошо вымешать для получения крутого теста, затем раскатать его в две полосы и на одну выложить фарш, края промазать яйцом и прикрыть второй полосой. Края хорошо защипнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'В горячий мясной бульон положит получившиеся пельмени, и варить на небольшом огне, пока они не будут готовы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3544,'Для соуса к пельменям простоквашу смешать с рубленым чесноком или пропущенным через пресс, готовые пельмени полить соусом, отдельно подать бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3545,'Очистить и промыть любые свежие грибы. Ошпарить кипятком, откинуть на сито, дать воде стечь. Нарезать ломтиками, посолить и обжарить на масле. Довести до готовности, всыпать немного пшеничной  муки и перемешать, затем влить сметану и довести смесь  до кипения. Переложить в форму для выпечки, смазанную маслом, посыпать грибы в сметане по-деревенски тертым твердым сыром и запечь при температуре 200 градусов в течение 8 – 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3546,'Размочить желатин в теплой воде. Прогреть на водяной бане до полного растворения, в смеси не должно быть комочков. Растереть сливочное масло комнатной температуры с сахарным песком, добавить размятый творог, ванильный сахар, молоко. Влить готовый растворенный желатин тонкой струйкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3546,'Форму для выпечки с высокими бортиками выложить пленкой, слоями сложить консервированные персики или другие фрукты и готовое бисквитное печенье, промазать творожной массой. Верхним слоем должно быть печенье. Поставить в холодильник до полного застывания. Готовый быстрый торт «Нежный»  без выпечки выложить на блюдо и посыпать тертым темным или молочным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8394,'Подлить сливки, выпарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3547,'Порубить и обжарить репчатый лук, натереть плавленые сырки и смешать с яйцами. Все ингредиенты перемешать. Сформовать небольшие пирожки любой формы. Уложить пирожки с плавленым сыром на смазанный противень и выпечь до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3548,'Свежие огурцы и помидоры нарезать небольшими дольками, порвать руками пучок зеленого листового салата. Нарезать брынзу кубиками, все ингредиенты перемешать. Отдельно смешать йогурт без цветовых и вкусовых добавок, сухие прованские травы, лимонный сок, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3548,'Перемешать до однородного состояния. Салат заправить йогуртовой смесью  и перемешать. Отварную куриную грудку нарезать пластинками и обжарить с двух сторон. Выложить салат «Для дам и кавалеров» с брынзой на тарелки, сверху – куриное филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3549,'Нарезать сырое куриное филе крупными кусочками, шампиньоны – пластинками. То и другое обжарить в сковороде на сливочном масле. Лишнюю жидкость можно слить.  Для заправки раздавить очищенные зубчики чеснока, натереть твердый сыр, добавить рубленую зелень укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3549,'Залить смесь сливками средней жирности, всыпать смесь сухих прованских трав, перемешать. Залить сливочно-сырной заправкой курицу с грибами, потушить на тихом огне еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3550,'Порезать батон на тоненькие ломтики, приблизительно 1 сантиметр толщиной. Натереть на крупной терке вареную колбасу и твердый сыр. Добавить майонез, кетчуп и тщательно перемешать до однородности. Помидоры нарезать на кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3550,'Полученную смесь положить на ломтики батона, сверху на каждый ломтик положить по кружочку помидора. Выложить бутерброды «Ленивая пицца» с колбасой и сыром на противень смазанный маслом и оправить на двадцать минут в духовку. Готовить при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3551,'Предварительно отварить овощи, и поставить в холодильник для охлаждения. Разделать сельдь на филе, убрать косточки и порезать на маленькие кубики. Измельчить лук и добавить к сельди.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3551,'Почистить и мелко натереть овощи и яйца. Выложить все ингредиенты слоями, смазать каждый слой майонезом, посолить. Первым слоем выложить тертую и отжатую свеклу ровным слоем на пленку и чуть-чуть уплотнить с помощью пленки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3551,'На свеклу положить морковь и также уплотнить. На морковь положить слой тертого картофеля. Следующим слоем будет яйцо. Каждый выложенный слой должен быть тоньше предыдущего.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3551,'Свернуть все рулетом и обжать краешки. Салат «',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3552,'Нагреть духовку до 180 градусов. Смазать маслом,  застеленный специальной бумагой противень, размером 35 на 25 сантиметров. Отделить белки от желтков. Взбить белки до пиков. Взбивать желтки с сахаром минут десять, насыпать соду и какао. Осторожно соединить желтки с белками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3552,'Перелить тесто на противень. Готовить минут десять, выложить корж на сухое, чистое полотенце. Скрутить рулетом и, не снимая полотенца оставить остывать. Поставить на огонь молоко и муку и готовить пока смесь не загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3552,'Снять с огня, вбить яйцо постоянно помешивая и охладить. Соединить молочно-мучной крем и масло, поделить на несколько частей (40 к 60). Смешать какао с сахарной пудрой и всыпать в большую часть. В часть поменьше, насыпать ванильный сахар. Отлить половину шоколадного крема для украшения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3552,'На раскрученный остывший корж намазать ванильный крем и 1/2 часть шоколадного крема. Положить вдоль бананы и снова скрутить рулет. Покрыть его шоколадным кремом и посыпать какао. Отправить шоколадный рулет с начинкой из бананов в холодильник на пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3553,'Мясное ассорти порезать на небольшие кусочки. Соединить с майонезом, посыпать перцем, солью и зеленью. Взять помидоры, срезать у них верхушки и достать мякоть. Положить в середину каждого помидора подготовленную начинку и запекать. Фаршированные помидоры с мясным ассорти присыпать тёртым сыром и подать к столу как самостоятельное блюдо',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3554,'Отварить яйца, остудить, почистить, отделить желтки от белков, потереть мелко в разные тарелочки. Помыть авокадо и огурцы, обсушить. Почистить авокадо, вырезать косточку. Порезать авокадо и огурцы на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4367,'Питательный и тонизирующий чай по-татарски со сливками, сметаной и солью разлить по чашкам и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3554,'Помыть болгарский перец, вырезать серединку, порезать на кубики. Мелко потереть сыр, ветчину порезать на кубики. Помыть петрушку, обсушить измельчить. Выложить на плоскую тарелочку слои: белки, чуть-чуть майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3554,'Затем выложить половину сыра, зеленый горошек, майонез, авокадо, перец болгарский и снова немного майонеза. Далее выложить ветчину, майонез, огурчики, опять майонез, измельченную петрушку, остальной сыр и желтки. Слоеный салат с авокадо, ветчиной и огурцом убрать на несколько часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3555,'Почистить лук, разрезать пополам, нашинковать полукольцами. Почистить помидоры от подножек, обдать кипятком, снять кожу. Убрать жидкость и семена. Порезать дольками. Порезать маслины вдоль и пополам. Измельчить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3555,'Смешать овощи, чуть-чуть посыпать солью, приправами, семенами укропа, добавить перец горошком (перец и семена потолочь). Отставить овощи в сторону. Порезать курицу на средние кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3555,'Приготовить смесь для курицы: смешать оливковое масло, чеснок, соль и приправы. Обвалять курицу в данной ароматной смеси. В форму для запекания положить 1/2 часть овощей, слегка сбрызнуть оливковым маслом, сверху выложить куриное мясо, а затем остальное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3555,'Отправить в духовку курицу по-провански с маслинами на 75-90 минут, соблюдая температуру 180 градусов. Если верх начнет подгорать и засыхать, то накрыть формочку фольгой, в конце готовки снять ее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3556,'Взять соленые огурцы, крупно натереть и обжаривать на растительном масле, пока рассол не выпарится и огурчики чуть-чуть не обжарятся. Натереть морковь и обжарить отдельно от огурцов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3556,'Соединить морковь и огурцы.  Добавить майонез и измельченный чесночок. Остудить, и намазать на кусочки серого хлеба. Бутерброды с соленым огурцом перед подачей лучше немного охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3557,'Взбить яйца до устойчивой пены, налить стакан молока, насыпать соль, сахар. Медленно всыпать муку и размешивать, пока не исчезнут комки. Влить остальное молоко, размешать, добавить растительное масло. Тщательно взбить. Выпекать тонкие блинчики на предварительно разогретой сковороде. Готовые блинчики на молоке смазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3558,'Соединить яйца, соль и сахар. Ввести муку, добавить йогурт. Перемешать, чтобы не было комков, положить соду, предварительно гашенную уксусом. Отставить тесто на несколько минут. Налить в разогретую сковороду масло и обжарить оладушки. Подать домашние оладушки с йогуртом и медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3559,'Развести в подогретом молоке дрожжи. Положить в молоко растопленое сливочное и растительное масло, вбить яйца, насыпать сахар, соль, перемешать, всыпать муку. Замесить тесто. Положить его в пакет, отложить на время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3559,'Приготовить начинку: порезать картофель и мясо на кубики по 1 сантиметру. Измельчить репчатый лук, посыпать перцем и солью. Вымесить тесто, поделить на равные кусочки, размером приблизительно с мандарин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3559,'Раскатать каждый в лепешку, в центр положить начинку, слепить пирожки в форме треугольников посередине с отверстием, в которое при запекании будем наливать бульон. Положить эчпочмаки на противень, смазанный маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3559,'Отправить эчпочмак с картофелем и мясом в духовку, минут пять готовить при температуре 200 градусов. Убавить температуру до 175, запекать еще двадцать минут. Достать противень, намазать яйцом, в дырочку налить бульон, снова отправить в духовку еще минут на двадцать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3560,'На дно противня выложить картофель, очищенный и порезанный на кружочки. Посолить. На картофель выложить свиной фарш с перцем и солью. Сверху положить грибы, обжаренные с луком (лук обжаривать отдельно от грибов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3560,'Смазать майонезом и посыпать твердым тертым сыром. Отправить противень в духовку и готовить картофель по-французски с грибами под сыром примерно час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3561,'Мясо курицы измельчить. Вбить яйца, налить молоко, насыпать соль, муку и крахмал. Можно положить чуть-чуть майонеза, но не обязательно. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3561,'Отставить тесто минут на десять. Тесто должно быть, как на обычные оладьи. Жарить оладьи из курицы на сковороде с маслом до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5815,'Нарезать мясо брусочками, обжарить до готовности в разогретом растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3562,'Протереть творог через ситечко. Влить молоко и перемешать. Вбить яйцо, снова размешать. Всыпать манную крупу, сахар и снова перемешать. Каждый раз именно перемешивать, а не взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3562,'Смазать форму сливочным маслом, положить творожную смесь, равномерно распределить. Отправить легкую ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3563,'Разломать шоколад, порезать масло на кусочки, все положить в емкость и растопить на паровой бане, постоянно мешая. Взбить в пену яйца, желтки и сахар. Соединить взбитые яйца с растопленным шоколадом, насыпать соль и муку. Размешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3563,'Смазать маслом формочки, разлить тесто и печь примерно минут восемь в духовке. Выпекать кекс с темным шоколадом, соблюдая температуру 200 градусов. Краешки должны пропечься, начинка остаться в жидком состоянии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3564,'Сливочное масло или маргарин комнатной температуры растереть добела с сахарным песком. Добавить сырые яйца, сметану, порциями всыпать пшеничную муку вместе с разрыхлителем. Можно добавить специи: ваниль, молотый мускатный орех, кардамон. Вымесить тесто, оно должно получиться эластичным. Положить на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3564,'Вынуть тесто, отделить четверть, оставить её в холодильнике. Остальную массу раскатать, выложить на сухой противень и сформовать невысокие бортики. Намазать корж густым вареньем или джемом, сверху – натертое охлажденное тесто из холодильника. Печь тертый пирог на сметане с джемом, при температуре 180 градусов в течение 35 – 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3565,'Перемешать сырые яйца, майонез, сметану и просеянную пшеничную муку в равных количествах. Добавить картофельный крахмал и разрыхлитель, немного рубленого чеснока. Белокочанную капусту мелко порубить, посолить и перетереть руками, чтобы выделился сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3565,'Смазать противень растительным маслом, уложить капусту, залить жидким тестом. Посыпать тертым сыром. Печь 20 минут при температуре 200 градусов. Капустную запеканку под сыром остудить и порезать на порции. В начинку можно добавить рубленый зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3566,'Натереть небольшой кабачок, добавить яйцо, муку и манную крупу, соль и перец – по вкусу. Застелить противень фольгой, смазать её растительным маслом и вылить полученное жидкое тесто ровным слоем. Печь 15 минут при температуре 250 градусов. Остудить, фольгу удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3566,'Для приготовления начинки нарезать ветчину, твердый сыр, помидоры, порубить любую зелень и чеснок. Выложить массу на кабачковую лепешку, свернуть рулетом, печь еще 15 минут при той же температуре. Кабачковый рулет с сыром и ветчиной остудить и разрезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3567,'Тонкой соломкой нарезать сырое куриное филе, репчатый лук, шампиньоны. Пассировать рубленый репчатый лук, на оливковом или любом другом растительном масле, до прозрачного состояния, затем добавить мясо, через 4 – 5 минут – грибы. Соль и перец – по вкусу. Обжаривать до выпаривания влаги, добавить сметану, тушить пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3567,'Отварить ракушки, откинуть и немного остудить. С помощью ложки нафаршировать макароны, выложить на огнеупорное блюдо или в форму для запекания, посыпать тертым твердым сыром. Запечь жульен по-французски в конкильони в духовке до готовности, сыр должен расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3568,'Порубить репчатый лук, нарезать ветчину соломкой, помидоры – кубиками. Обжарить лук на растительном масле до золотистого цвета, добавить к нему ветчину, еще немного обжарить. На дно формы для выпечки выложить ветчину с луком, затем – слой помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3568,'Отдельно взбить яйца, добавить муку, соль, черный молотый перец. Влить молоко и перемешать. Залить полученной смесью ветчину и помидоры. Печь пышный омлет с ветчиной в духовке в течение 20 – 25 минут при средней температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3569,'Куриное филе нарезать на небольшие кусочки. В сотейнике на сильном огне разогреть немного растительного масла. Обжарить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3569,'Нарезать репчатый лук полукольцами, крупно порубить чеснок. Обжарить смесь в течение пяти минут, в сотейнике, на среднем огне. Сладкий болгарский перец нарезать толстой соломкой, его и чеснок добавить в лук, жарить всё вместе ещё пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3609,'Застелить смазанную сливочным (топленым) маслом форму фольгой или бумагой для выпечки, промазать еще раз, выложить тесто и отправить в духовку на 25 минут до появления красивой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3569,'Вернуть в сотейник куриное филе, добавить консервированные томаты, размятые вилкой вместе с соком. Соль – по вкусу. Массу довести до кипения, уменьшить огонь и тушить до мягкости перца, в течение 25 – 30 минут. Пепперонату из курицы по-итальянски посыпать рубленым зеленым базиликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3570,'Взбить яйца миксером, всыпать ванилин, стакан сахарного песка, просеянную пшеничную муку и разрыхлитель. Взбить массу до пышности, выложить в круглую форму и печь в течение 40 – 50 минут. Растопить темный шоколад на тихом огне в сотейнике, с добавлением молока, или на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3570,'Готовый корж остудить до комнатной температуры, достать из формы, залить растопленным шоколадом. Отдельно взбить в плотную массу сливки с сахарным песком. Выложить сливки поверх застывшего шоколада и украсить свежими ягодами. Летний торт с ягодами и шоколадом можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3571,'Картофель очистить и нарезать небольшими кубиками, переложить в кипящую воду. Нарезать копченую жирную колбасу, нашинковать репчатый лук, морковь, очищенный чеснок и любую зелень. Обжарить колбасу на сухой сковороде. Всыпать лук и морковь, тушить всё вместе в течение 5 – 7 минут. В кастрюлю с картофелем добавить плавленый сыр, растворить, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3571,'При полуготовности картофеля всыпать рис. Заправить суп колбасно-овощной поджаркой, дать покипеть три минуты, посолить и поперчить по вкусу. Можно добавить сухие приправы для овощей. За пять минут до готовности всыпать рубленый чеснок и зелень. Огонь выключить, дать сырному супу с копченой колбасой постоять в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3572,'Листья мяты вместе со стеблями промыть, обсушить и порезать. Мелко нарезать лимоны вместе с кожурой. То и другое сложить в кастрюлю, варить 10 минут, оставить на сутки для настаивания. Смесь отжать, отфильтровать, добавить сахарный песок и варить до готовности, до загустения. Горячее варенье из мяты и лимона разлить в стерильные, пропаренные банки и закатать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3573,'Сухую детскую смесь Малютка смешать с жареным арахисом. Упаковку не выбрасывать. Отдельно смешать сахарный песок с какао-порошком, добавить молоко, довести до кипения, помешивать. Вылить смесь в ореховую массу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3573,'Массу выложить в упаковку от Малютки, заклеить верх скотчем и охладить в холодильнике. При подаче молочный щербет с орехами и какао нарезать пластинками или брусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3574,'Натереть твердый сыр, например Маасдам, смешать с двумя сырыми яйцами, сметаной, нашинкованной зеленью укропа, мукой. Перемешать. Влить в сковороду растительное масло, выложить полученную массу. Обжарить хачапури с сыром по-грузински на среднем огне с двух сторон. Одну сторону обжаривать под крышкой, вторую – без крышки, по пять-семь минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3575,'Отрезать корки у шести ломтей белого хлеба. Намазать сливочным маслом с одной стороны. Выложить на тарелку ломоть маслом вверх, накрыть ломтиком ветчины и мелко нарезанными солеными или маринованными огурцами. Далее слои повторять, верхний ломоть положить маслом вниз. Сэндвич уплотнить, плотно прижать руками, накрыть пищевой пленкой и поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3575,'Размешать и взбить сливочный сыр, можно немного развести молоком или сливками до полужидкого состояния. Вынуть бутерброд из холодильника, намазать со всех сторон сырной массой, посыпать рубленым зеленым луком. Вернуть в холодильник еще на один час. При подаче сэндвич со сливочным сыром и ветчиной нарезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3576,'Сырые куриные яйца взбить с тертым твердым сыром, молоком и пшеничной мукой. Соль – по вкусу. Растопить на сковороде сливочное масло. Вылить массу и обжарить с двух сторон. При подаче омлет с сыром посыпать рубленой зеленью петрушки, укропа, полить кетчупом или подать его отдельно, в соуснике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3577,'Имбирь почистить, порезать на тонкие пластинки. Лимон помыть, порезать на тоненькие пластинки, убрать косточки. Переложить в кастрюлю к имбирю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3577,'Сахар высыпать к имбирю и лимону. Варить, непрерывно мешая, чтобы сахар не подгорел. В процессе готовки имбирь становится прозрачным и мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3713,'Белки отделить от желтков. Вторые растереть с сахарозаменителем, добавить обезжиренный творог, соль и мармеладное желе. Массу хорошо перемешать и добавить немного манной крупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3577,'Готовить на большом огне, когда варенье сильно закипит, постоянно помешивая, варить еще минут пять. Разлить имбирное варенье с лимоном по баночкам, полностью остудить и закрыть закручивающимися крышками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3578,'Порезать мясо на небольшие кубики. Мясо готовится дольше всего, поэтому его необходимо предварительно обжарить на сковороде практически до готовности и только потом положить в горшочки. Почистить морковь и порезать ее на кубики приблизительно один  на один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3578,'Положить морковь на сковороду и чуть-чуть обжарить на растительном масле. Практически тоже нужно сделать и с луком: порезать на не очень маленькие кубики, чуть-чуть обжарить на сковороде отдельно от моркови. Порезать томаты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3578,'Почистить картофель, порезать на такие же кубики, что и мясо. Измельчить зелень. Выложить слоями, не забывая солить, все ингредиенты в горшочки. На дно налить чуть-чуть масла, первым слоем положить лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3578,'Следующим слоем положить морковь. Затем мясо. На мясо положить картофель. На картофель, выложить остальные ингредиенты: нарезанные помидоры, измельченную зелень, посыпать любыми специями, а также перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3578,'Накрыть горшочки крышкой, отправить в духовку на час и готовить при 180 градусах. Затем выключить духовку, но мясо в горшочках по-селянски не доставать, пусть блюдо минут пятнадцать доходит.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3579,'Просеять муку с солью в глубокую емкость. Перетереть ладонями мягкое масло вместе с мукой, чтобы смесь была похожа на крошки хлеба. Чуть-чуть взбить яйцо, добавить в массу, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3579,'Сформировать шар, завернуть в полиэтилен, отправить минут на пятьдесят в холодильник. Почистить тыкву, убрать семена. Мякоть порезать на кубики. Положить тыкву в кастрюльку с толстым дном, налить немного воды и тушить, пока не испарится жидкость, и тыква не станет мягкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3579,'Измельчить мякоть блендером так, чтобы получилось нежное пюре. Раскатать тесто на поверхности, посыпанной мукой. Выложить его в низкую круглую формочку диаметром 30 сантиметров и выпекать минут пятнадцать, соблюдая температуру 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3579,'В пюре из тыквы вбить яйца, сахар, сливки, посыпать приправами и солью. Взбить. Вылить в формочку с запеченным тестом. Выпекать минут пятьдесят, соблюдая температуру 180 градусов. Когда пирог из тыквы по-американски остынет, порезать его на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3580,'В емкости среднего размера смешать креветки, кукурузный крахмал, перец и соль. Отставить на 10 минут. Нагреть сковороду на большом огне, предварительно смазав ее маслом. Выложить слой креветок и обжаривать 2 минуты. Переложить креветки в отдельную емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3580,'В сковороду влить предварительно взбитые яйца и, постоянно помешивая, приготовить омлет. Рис отварить. Обжарить предварительно измельченный, зеленый лук и смешать его с рисом. Равномерно распределить рисовую смесь по дну сковороды и готовить несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3580,'Полить рис соевым соусом. Добавить кунжутное масло, подготовленные овощи, креветки, яичный омлет и хорошо перемешать. Затем еще раз немного обжарить рис, чтобы разогрелся. Добавить соевый соус. Выложить  жареные креветки в соевом соусе с рисом и овощами на блюдо и подать к столу',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3581,'Смешать в кастрюле молоко и воду, положить сливочное масло и варить 7 минут на тихом огне. Выключить огонь и всыпать в смесь просеянную муку, постоянно помешивая. Мешать содержимое кастрюльки, пока не получится кусок теста, отстающий от стенок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3581,'Переложить остывшее тесто в кухонный комбайн и взбивать на медленной скорости,  вводя по одному яйца. Тесто должно получиться глянцевым. Переложить его в кондитерский мешок, противень застелить специальной бумагой и выдавить тесто полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3581,'Готовить эклеры в духовке 10 минут, соблюдая температуру 200 градусов. Убавить температуру до 175, и готовить еще 10 минут. Приготовить крем: все ингредиенты должны быть комнатной температуры, тогда крем будет однородным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3589,'Разогреть на сковороде растительное масло глубиной приблизительно 1 сантиметр. Окунуть в кляр кусочки капусты. Обжарить капусту в кляре со всех сторон до золотистого оттенка. Готовые кусочки цветной капусты в яично-пивном кляре выложить на салфетки, чтобы стекло масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3581,'Смешать вареное сгущенное молоко с маслом и взбить на маленькой скорости. Добавить в крем коньяк, сгущенное молоко и еще раз взбить. Готовые и охлажденные пирожные надрезать сбоку и наполнить кремом. Заварные эклеры со сливочным кремом выложить на блюдо и по желанию присыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3582,'Свиную вырезку вымыть и обсушить с помощью бумажного полотенца. Приготовить маринад: соединить паприку с соевым соусом. Мелко натереть имбирь, положить прессованный чеснок, все добавить в соус и перемешать. Положить мясо в маринад и оставить на 3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3582,'В маринованной вырезке сделать разрез вдоль, не до конца, и положить в него рядком маслины. Завернуть вырезку в тоненькие пластины бекона. В предварительно разогретую до 230 градусов духовку отправить вырезку в беконе, готовить 15 минут. Духовку выключить и оставить свинину в чесночно-имбирном соусе еще на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3583,'Взбить яйца и сахар. Всыпать муку и замесить жидкое тесто. Смазать формочку маслом, положить в нее тесто. Отправить тесто в духовку на 20 минут, соблюдая температуру 180 градусов. Чуть-чуть пропитать приготовленный корж вишневым компотом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3583,'Убрать из вишни косточки, выложить ягоды на корж. Приготовить крем: взбить сливки и сахар, добавить маскарпоне, размешать. Выложить крем на остывший пирог и посыпать сверху мелко натертым шоколадом. Отправить пирог «Наслаждение» с вишней на 4 часа в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3584,'Смазать формочку маслом и посыпать сухарями для панировки или мукой. На дно и по бокам положить картофель, нарезанный кружками. Посыпать солью. На картофель выложить мясо, приправить перцем и солью. Выложить измельченный лук и снова приправить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3584,'Приготовить тесто: смешать сметану, яйца, муку, соль, майонез и соду. Залить тестом блюдо. Готовить заливной пирог с картофелем и курочкой в духовке 50 минут, соблюдая температуру 190 градусов. Перевернуть на плоскую тарелку и порционно нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3585,'Помыть филе курицы, порезать на небольшие кусочки, приблизительно по 1 сантиметру. Выжать в сок из половины лимона в нарезанное мясо, размешать.Отставить на 30 минут. Порезанное и замаринованное мясо быстро обжарить на хорошо разогретой сковороде в масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3585,'Когда филе станет румяным, посыпать карри и перемешать. Накрыть крышкой и оставить на 5 минут, на тихом огне. Остудить филе. Остывшее мясо откинуть на дуршлаг, чтобы стекла жидкость от карри и лимонного сока, если не процедить, то салатик расползется.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3585,'Собрать салат: выложить мясо в виде виноградной грозди. Смазать майонезом,посыпать измельченными орехами. Натереть и выложить яйца. Снова смазать майонезом и посыпать орехами. В конце выложить натертый сыр, также смазать майонезом и посыпать орехами. Украсить слоеный салат «Тиффани» виноградом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3586,'Налить в глубокую посуду молоко. Вбить яйца, посолить. Размешать, но не взбивать. Смазать формочку сливочным маслом. Перелить полученную  массу в формочку, заполняя на 2/3 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3586,'Отправить на 30 минут в духовку и готовить при температуре 200 градусов. По истечении времени, духовку выключить, но не открывать еще 20 минут. Нарезать молочный омлет на порции, на каждую порцию положить по кусочку сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3587,'Подогреть кокосовое молоко. В миску просеять какао, муку и разрыхлитель. Всыпать два вида сахара. Размешать. Налить в смесь теплое молоко, осторожно и быстро перемешать. Формочку (20 сантиметров) смазать растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3587,'Перелить тесто в форму и выпекать в духовке примерно 40 минут при температуре 180 градусов. Сделать глазурь: растопить шоколад, влить масло и размешать. Полить шоколадный торт на кокосовом молоке глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3588,'Смешать нарезанные кубиками фрукты с орехами, залить йогуртом и перемешать. Положить в смесь взбитые сливки, осторожно размешать. Переложить салат в контейнер. Поставить на 2 часа в морозилку. Замороженный салат из фруктов подать на стол в креманках.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3589,'Приготовить кляр: взбить венчиком яйцо, муку и пиво. Добавить перец, соль. Разделить капусту на соцветия. Опустить соцветия в подсоленную, кипящую воду и готовить 7 минут. Откинуть капусту на дуршлаг, остудить, подождать, пока вода полностью стечет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Полить салат подсолнечным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3590,'Смешать овсяные хлопья и манную крупу. Залить кефиром, перемешать и оставить на 2 часа. Взбить яйца, добавить в миску с кефирной смесью, всыпать сахарный песок, соль и соду. Влить растительное масло, перемешать. Обжаривать блинчики на манке и овсяных хлопьях на сковороде, по несколько минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3591,'Тушки кальмаров отваривать, в кипящей воде, в течение 5 минут. Очистить от пленки. Натереть плавленые сыр, добавить очищенный, рубленый чеснок, зелень, креветки и майонез. Массу перемешать и начинить кальмары, уплотнить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3591,'Кальмары с чесночно-сырной начинкой нарезать кольцами. Можно уложить кольца фаршированных кальмаров на ломтики свежего кислого яблока и украсить веточками укропа, или выложить такие бутерброды на листья зеленого салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3592,'Шампиньоны вымыть. Нарезать ломтиками или на четыре части каждый. Помидоры черри нарезать половинками, репчатый лук — мелкими кубиками. Разогреть на сковороде оливковое масло, обжарить зубчики чеснока, разрезанные пополам, дольки убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3592,'На чесночном масле обжарить лук до прозрачного состояния, затем добавить грибы и выпаривать жидкость 5 – 7 минут. Добавить помидоры, жарить еще 5 минут. Затем влить жирные сливки, прогреть на среднем огне 10 – 12 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3592,'Помидоры черри можно заменить обычными, порезанными на кусочки. Готовый сливочно-грибной соус с помидорами черри подать с отваренной гречкой, рисом, картошкой, макаронами или отварным мясом. Перед подачей соус перемешать с гарниром и прогреть пару минут под крышкой или просто полить им блюдо сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3593,'Натереть на терке плавленые сырки, чеснок пропустить через пресс. Готовую морковь по-корейски мелко порезать и заправить майонезом. Выложить массу на блюдо в виде мышки, украсить тертым сыром, зеленью петрушки. Сделать лапки, ушки и хвостик — из вареной колбасы. Глаза и нос — из половинок черных консервированных маслин, усики — из зеленого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3594,'Охладить белки, добавить соль и лимонный сок и взбить миксером до увеличения массы в полтора-два раза. Ввести сахарный песок частями, продолжать взбивать до образования плотной, густой массы. Переложить в миску, всыпать смесь молотого миндаля, сахарной пудры и пищевого красителя желтого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3594,'Вымесить тесто. Масса должна стать густой и тяжелой. Застелить противень бумагой для выпечки, отсадить лепешки с помощью кондитерского мешка или целлофанового пакета. Печенье должно быть маленьким, 3 см в диаметре. Оставить на столе на 45 минут для подсушивания. Выпекать печенье 15 минут при температуре 140 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3594,'Для приготовления крема размягчить сливочное масло, взбить, добавить вареное сгущенное молоко, снова взбить до однородного состояния. Готовые лепешки соединить попарно с помощью крема и немного прижать. Поставить печенье «Макарун» с миндалем в холодильник примерно на 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3595,'Растереть в крошку муку с размягченным сливочным маслом, сахаром и двумя сырыми желтками. Добавить соль и ванильный порошок. Массу быстро скатать в колобок и поставить на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3595,'Охлажденное тесто раскатать в пласт. Вырезать из теста фигурки. Выпекать песочное печенье в духовке при температуре 180 – 200 градусов, до образования румяной корочки. Перед подачей песочное печенье к кофе, его можно посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3596,'Куриные бедра натереть солью и перцем, дать постоять для пропитывания. Налить оливковое масло в большую сковороду, обжарить курицу на сильном огне с двух сторон до золотистой корочки 2 минуты. Нарезать зеленый лук, клубни очищенного картофеля – на половинки или четвертинки, в зависимости от размера клубня. Мелко нарезать чеснок, свежий розмарин и орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3596,'Выложить на блюдо для запекания, сверху – куриные бедра, обжаренной кожицей вверх. Полить лимонным соком, выложить консервированные зеленые оливки, без жидкости. Курицу с картофелем по-итальянски накрыть фольгой и запечь в разогретой до 180 градусов духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3597,'Размягченный маргарин или сливочное масло нарубить вместе с мукой или натереть на терке. Добавить в массу протертый творог, соду. Замесить тесто, оно должно получиться тугим, и оставить в холодильнике на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8394,'посыпать зеленью укропа и петрушки, перемешать и подать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3597,'Раскатать массу в тонкий пласт, вырезать одинаковые кружочки. На каждом кружке сделать острым ножом по шесть надрезов от центра к краю. Лепестки завернуть к середине и прижать. Обмакнуть печенье во взбитое яйцо, затем в сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3597,'Можно печенье «Творожные цветки» смазать яйцом с помощью кисточки и присыпать сахаром. Печь на смазанном маслом противне 20 минут, при температуре 220 градусов, до золотисто-коричневой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3598,'Вымыть и натереть свежие огурцы, очистить, измельчить чеснок. Мелко порубить вымытый и обсушенный укроп. Все ингредиенты выложить в тарелку, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3598,'Грецкие орехи почистить и потолочь, чтобы получились кусочки средней величины. Залить смесью кефира и воды, посыпать орехами. При подаче украсить болгарский суп «Таратор» с грецкими орехами, веточкой петрушки или любой другой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3599,'Для приготовления теста растопить и остудить сливочное масло. Смешать яйцо с сахарным песком, ванилином и мёдом. Добавить нежирную сметану и масло, просеянную муку с разрыхлителем. Замесить эластичное, тугое тесто. Раскатать массу на всю поверхность противня и печь 8 минут, при температуре 175 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3599,'Для крема: смешать сгущенное молоко с апельсиновым соком и сметаной. Взбить венчиком. Готовый выпеченный корж разрезать поперек, острым ножом, на две половины. Крошки сохранить для присыпки. Коржи прослоить кремом и оставить на несколько часов для пропитывания. Присыпать крошками и разрезать на порции.  Медовые пирожные с апельсиновым кремом украсить и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3600,'Яйца разбить в глубокую ёмкость и взбить, используя миксер, до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3600,'В яичную смесь влить молоко, добавить предварительно растопленное сливочное масло, приправить солью и снова тщательно перемешать до консистенции густой сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3600,'Ёмкость для выпекания смазать жиром или маслом  и поставить на огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3600,'Приготовленную смесь для тунтэрмы вылить в ёмкость и довести до загустения, сгустившуюся смесь переставить в духовой шкаф на 4-5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3600,'Перед подачей на стол омлет «Тунтерма» сбрызнуть жиром или маслом и разрезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3601,'Перемешать манную крупу, сахар, сырые яйца, протертый творог, сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3601,'Всыпать щепотку соли и соду, погашенную уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3601,'Вылить массу в форму или на сковороду, запечь быструю творожную запеканку в духовке до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3602,'Куриные окорочки вымыть, разрезать на кусочки, натереть сухими специями для курицы. Потушить на растительном масле в сковороде. Натереть очищенную морковь, добавить к мясу, затем рубленый репчатый лук. Тушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3602,'Выложить окорочка в порционные горшочки, в каждый добавить по две столовые ложки сырого риса. Долить воду, чтобы она покрывала рис на 2 см. Соль – по вкусу. Закрыть крышками и запекать куриный плов с карри в духовке в течение 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3603,'Очистить чеснок, раздавить его плоской стороной ножа. Положить в посуду небольшого объема и залить оливковым маслом. Поставить в микроволновую печь на 40 секунд. С белого батона срезать корочку, порезать мякоть кубиками. Выложить на противень, полить полученным чесночным маслом и перемешать. Отправить противень в духовку на 20 – 40 минут и запечь при температуре 150 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3603,'Готовые сухарики остудить. Для заправки смешать сваренные желтки, горчицу и раздавленный чеснок. Массу растереть пестиком в небольшой ступке. Добавить лимонный сок и соль по вкусу. Влить порциями оливковое масло, продолжая растирать. Оставить соус на час для настаивания. Сырое куриное филе разрезать вдоль на тонкие пластинки, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3603,'Жарить на оливковом масле в течение 4–5 минут с каждой стороны. Вымыть и обсушить листья зеленого салата. Порвать листья кусочками и выложить на блюдо. Сверху – сухарики с чесночным маслом и ломтики курицы, затем нарезанный тонкими пластинками сыр пармезан. Полить классический салат «Цезарь» с курицей заправкой. Украсить помидорами черри, порезанными на четыре части, или дольками обычных помидоров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5848,'Нашинковать капусту, лук порезать тонкими полукольцами, промыть и нарезать ломтиками шампиньоны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3604,'Влить в манную крупу кефир, размешать и отставить на 20 минут, чтобы манка набухла. Растопить в микроволновой печи, в высокой форме для выпечки, маргарин. Всыпать сахар, размешать до однородности, вбить яйцо и добавить манку с кефиром. Перемешать. Всыпать просеянную муку и разрыхлитель. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3604,'Разделить тесто на две равные части. Одну часть теста смешать с какао. Вылить светлое тесто в форму, где растапливалось масло. Отправить в микроволновую печь на 6 минут и готовить при мощности 600 вт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3604,'Форму с тестом при выпекании не накрывать. Готовый корж перевернуть на блюдо и разрезать на две части. Выпечь темный корж и также разрезать его на две части. Приготовить крем, смешав сметану с сахаром. Выложить на блюдо коржи, чередуя белые с темными и смазать каждый кремом. Готовый сметанный торт «День и ночь» украсить тертым шоколадом или присыпать какао-порошком',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3605,'Вскипятить в кастрюле молоко. Отдельно растопить масло. В масло всыпать муку и быстро перемешать. В результате смесь должна приобрести золотистый оттенок. Через 7 минут, после добавления муки, влить несколько ложек подогретого молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3605,'Венчиком размешать соус и влить остальное молоко. Готовить, пока соус не загустеет. Посыпать перцем и солью. Дополнительно в соус «Бешамель» можно положить зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3606,'Взбить яйца, ванилин, сахар, положить йогурт, с размешенной в нем содой и всыпать муку. Тесто должно получиться жидким. Застелить противень специальной бумагой и вылить тесто. Оно должно растечься равномерно по всей поверхности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3606,'Отправить противень в разогретую духовку, готовить 7 минут до розоватого цвета. Вынуть, перевернуть розовой стороной на влажную ткань. Быстро смазать джемом и, используя ткань, свернуть рулетом. Чуть-чуть остудить. Убрать ткань. Посыпать йогуртовый рулет с джемом сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3607,'Взбить сливки, медленно всыпать ванилин и сахар. Каждое печенье обмакивать в горячий кофе и выкладывать на дно формы. Свободные углы заполнять кусочками. Обильно покрыть печенье взбитыми сливками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3607,'Таким же образом выложить остальные слои печенья. Готовый торт без выпечки с кофейным ароматом украсить взбитыми сливками. Кофе можно заменить теплым молоком, сливками или вареньем. Дополнительно можно добавить фрукты или ягоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Самым главным в данном рецепте является спаржа. Ее можно использовать замороженную или свежую. Если спаржа свежая, то отрезать нижние кончики, внизу стебли зачистить овощечисткой. Если спаржа замороженная, то дать ей постоять 20 минут при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Брать 50-70 грамм на порцию. Довести воду до кипения, чуть-чуть подсолить, варить спаржу 3 минуты. Подготовить емкость с кубиками льда или холодной водой. Когда спаржа будет готова, сразу переложить ее в ледяную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Это помогает остановиться процессу приготовления, спаржа остается хрустящей и яркой. Спустя 2 минуты переложить спаржу на салфетки, чтобы стекла лишняя влага. Отварить яйца (на каждую порцию по одному).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Приготовить яйца можно любым способом: всмятку, яичница, пашот. Измельчить шалот.Нагреть сотейник, добавить оливковое масло. Положить шалот. Пока обжаривается лук, измельчить несколько стеблей зеленого лука, 2 зубчика чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Насыпать в сотейник молотый кориандр или другие специи. Положить черри, порезанные на четыре части. Перемешать, налить маленькую ложку винного белого уксуса. Перемешать, высыпать лук и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3608,'Положить спаржу на тарелку, выложить заправку из помидор. На нее положить яйцо, посыпать перцем, солью. Перед подачей теплого салата со спаржей, черри и пряной заправкой проколоть яйцо, чтобы желток красиво растекся по салату.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3609,'Для приготовления теста очищенные кабачки (цуккини) натереть, лук прокрутить на мясорубке или размолоть в блендере, желтки растереть с солью и разрыхлителем, белки взбить до состояния «крепкой пены», хорошо перемешать кабачки, лук, желтки, затем осторожно ввести в тесто белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3609,'Для начинки пожарить грибы до выпаривания жидкости, смешать с пассерованным луком, добавить сливки и немного потушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3609,'Духовку разогреть до 180-190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3609,'Перевернув форму, вынуть горячий корж, положить начинку, посыпать натертым сыром, свернуть рулет из кабачков с грибной начинкой, если все сделать достаточно быстро, сыр успеет расплавиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3610,'Приготовить начинку: мелко потереть вареные яйца и плавленый сыр. Положить размягченное сливочное масло, размешать. Можно посыпать перцем и солью, если рыбка не слишком соленая. В 1/3 часть смеси положить измельченную зелень и отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3610,'В остальную смесь положить мелко натертую, отваренную свеклу, размешать. Собрать закуску шубу в шубе: разрезать багет с одного края вдоль, чтобы он легко приоткрывался. Рукой или при помощи ложки убрать мякиш, оставить стенки приблизительно 1 сантиметр толщиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3610,'Внутри намазать багет свекольной смесью, распределить ее по стенкам. На свекольную смесь равномерно положить слой с зеленью. По желанию можно положить измельченный зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3610,'Около неразрезанного края багета в линию выложить корнишоны, рядом положить филе сельди. Стенки по линии разреза чуть-чуть намазать сливочным маслом, закрыть багет, осторожно соединить края, плотно завернуть пищевой пленкой в 2 оборота.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3610,'Если процедура выполнена правильно, то разрез склеится и станет незаметным. Отправить шубу в шубке с сельдью и плавленым сыром в холодильник на 3 часа. Перед подачей снять пленку, порезать на ломтики по 1 сантиметру толщиной. Разложить кусочки на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3611,'Сначала осторожно снять кожу с окорочка чулком — это достаточно легко сделать. Отделить мясо от кости, разрезать на небольшие куски, добавить свинину, порезанную на кусочки. Мариновать в домашнем майонезе (потому что в состав входит горчица, перец, соль) 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3611,'Почистить апельсин от кожуры, порезать мякоть на кусочки, выдавить чеснок. По вкусу посыпать солью, перцем, размешать. Полученную начинку поместить в чулки, завернуть края. Чтобы было надежней, можно закрепить зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3611,'Положить на горячую сковороду, чуть-чуть обжарить окорочка с двух сторон. Переложить обжаренные фаршированные куриные ножки с апельсином в формочку для запекания, готовить 20 минут, соблюдать температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3612,'Соединить полстакана масла, базилик, уксус, розмарин, чеснок, порезанные дамские пальчики. По вкусу посыпать перцем и солью. Нагреть гриль. Натереть початки кукурузы маслом, перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3612,'Обжаривать в бройлере приблизительно 7 минут до образования золотистых пятнышек, время от времени переворачивать. Остудить, снять кукурузу с початка. В большую салатницу положить кукурузу, черри, орешки, рукколу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3612,'Заправить подготовленным соусом, равномерно перемешать. Посыпать перцем, солью. Присыпать салат с рукколой, кукурузой и помидорами, тертым пармезаном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3613,'Взбивать яйца и сахар, пока не появятся пузырьки. Добавить остальные ингредиенты. Размешать, перелить все в формочку, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3613,'Готовить час, соблюдая температуру 150-180 градусов. Первые 20 минут не открывать дверцу духовки. Готовый  бисквит на сметане  намазать кремом и украсить на свой вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3614,'Приготовить базиликовый песто, соединив в кухонном комбайне чеснок, базилик, кедровые орешки, тертый пармезан. Размешать. Не переставая размешивать, насыпать перец, соль, добавить оливковое масло. Если песто очень густой, то добавить чуть-чуть оливкового масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3614,'Нагреть духовку. Положить на противень основу для пиццы, готовить 5-7 минут. Вынуть из духовки, в горячем виде посыпать тертой моцареллой (250 грамм), на нее положить кусочки помидоров. Посыпать солью. Соединить в небольшой емкости оставшийся сыр, майонез, перец, базиликовый песто, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3614,'Выложить смесь на помидоры. Готовить 15-20 минут, основа должна чуть-чуть подрумяниться, а сыр расплавиться. Порезать пиццу с помидорами, моцареллой и базиликом перед подачей клиньями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3615,'Разморозить филе курицы, обязательно его вымыть, потому что при разделывании курица не обрабатывается. Протереть куриное филе полотенцем, порезать на пластинки. Посыпать мясо солью, приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4434,'Отварить яйца, крупно натереть крабовые палочки, яйца и сыр. Разложить лаваш, посыпать сыром, палочками, яйцом. Намазать смесью йогурта и горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3615,'Выложить кусочки на сковороду с растительным маслом, обжаривать, пока не образуется аппетитная корочка. Достать бекон из упаковки, порезать на тонкие пластинки. Положить его на почти сухую сковороду, чуть-чуть обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3615,'Переложить обжаренный бекон на салфетку, чтобы она впитала лишний жир. Вымыть помидоры и порезать на не очень тонкие пластинки. Снимать кожуру не нужно, она не будет мешать. Приготовить заправку, смешав майонез, соевый соус и лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3615,'Сформировать салат. Помыть зеленый салат, протереть руками. Положить его на тарелку, сверху положить кусочки куриного филе. На него выложить бекон. Полить приготовленной заправкой. Получается ароматный, теплый салат с куриным филе и беконом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3616,'Почистить сладкие мандарины, разделить их на дольки, измельчать в блендере 2 минуты. Получившееся пюре перетереть через сито. Это поможет избавиться от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3616,'Соединить в блендере сгущенное молоко, сметану, пюре из мандаринов. Смешивать 3 минуты. Налить массу для мороженого в пластиковый контейнер, поместить в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3616,'Один раз в час доставать мороженое и перемешивать. Можно использовать блендер. Когда в очередной раз взбитая смесь станет густой, отправить ее замораживаться на 4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3617,'Растопить шоколад и сливочное масло. Отдельно взбить сахар и яйца. Соединить шоколадную смесь и яичную. Насыпать муку, размешать. Взбить сливки. Обжарить на сковороде фундук. Намазать чашечки сливочным маслом, посыпать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3617,'Разлить по чашечкам шоколадное тесто, наполняя чуть-чуть меньше половины. Чтобы было удобней, можно использовать кондитерский мешок. Готовить приблизительно 5-10 минут, должна появиться корочка. Соблюдать температуру 180-190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3617,'Внутри кексы останутся жидковатыми. Достать кексы, сверху положить обжаренный, остывший фундук. Покрыть готовый шоколадный кекс предварительно взбитыми сливками, чтобы получилась шапочка. Посыпать какао, подавать шоколадный кекс со сливками и фундуком  сразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3618,'Отварить свеклу, остудить, снять кожуру, 1/2 свеклы порезать на маленькие кубики. Положить в салатник. Порезать на маленькие кубики огурец. Положить к свекле. Порезать соломкой редис. Положить к овощам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3618,'Порвать руками салатные листья (можно мелко порезать), измельчить укроп, салатные листья и 1/2 укропа положить к предварительно подготовленным овощам. Размешать. Крупно порезать остальную свеклу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3618,'К свекле влить кефир, добавить остальной укроп, посыпать солью. Взбивать миксером, пока не получится однородная смесь. Отварить яйцо, охладить, разрезать на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3618,'Налить на тарелки свекольно-кефирную заправку, положить перемешанные овощи. В качестве украшения летнего супа можно использовать веточку зелени и половинки яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3619,'Порезать на маленькие кусочки перец чили, смешать с прессованным чесноком. Положить измельченную петрушку, добавить сок лимона и оливковое масло. Помыть и подсушить шампиньоны, натереть грибы полученной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3619,'Отставить на 30 минут. Порезать сыр на брусочки, положить его произвольно в шляпки грибов. Готовить острые шампиньоны с сыром 15-20 минут в духовке, соблюдая температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3620,'Через мясорубку пропустить сырки, филе, чеснок, зеленый лук, зелень. Размешать. Вбить яйцо, добавить сметану или майонез, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3620,'Сформировать маленькие котлеты, обвалять в сухарях, обжарить.  Куриные котлеты с плавленым сыром можно кушать. Вместо зеленого лука, можно использовать лук репчатый.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3621,'Взбить в белую пену 2 яйца и сахар, затем добавить масло, миндаль, муку, ром, крахмал, и перемешать миксером, поставить на 20 минут для застывания в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3621,'Вырезать из слоеного теста круг диаметром 26 см, выложить на него франжипан (миндальный крем), отступив от края немного больше чем на 1 см, и смазать белком край торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3627,'Следующим слоем выложить корейскую морковь, на нее сыр, полить кетчупом и майонезом. Края лаваша загнуть и скрутить рулетом, обжарить шаурму с колбасой и корейской морковью на сковородке (желательно с толстым дном), на небольшом огне с обеих сторон, пока не будет румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3621,'Тесто с кремом накрыть вторым кругом, сделать насечки тонким ножом (но не прорезать тесто, чтобы не вытек крем), придавить к нижнему коржу верхний по всему диаметру пальцами, и поставить на 20 минут в прохладное место. Можно оставить торт в морозилке на несколько дней, и затем выпекать, не размораживая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3621,'Поставить торт «Питивьер» с миндальным кремом-начинкой в духовку, разогретую до 220 °C, 15 минут выпекать, затем понизить температуру до 175 °C и выпекать еще приблизительно 10 минут, затем торт достать и смазать предварительно взбитым желтком и отправить на несколько минут в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3621,'Когда желток немного заглазируется, торт достать и посыпать сахарной пудрой, поставить в духовку еще на 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3622,'Почистить огурцы, порезать вдоль на две части, убрать семена, сделать из них лодочки. Измельчить сердцевину огурца и помидоры, мелко порезать отваренное яйцо и капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3622,'Соединить со сметаной. Начинить данной массой огурцы. Полить овощной салат в «лодочках» из огурцов, сметаной. Для украшения использовать измельченный укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3623,'Положить в фудроцессор прессованный чеснок, сок лимона, кукурузное масло. Включить фудроцессор, постепенно добавлять сок лимона приблизительно по 2 ложки, кукурузное масло по 4 ложки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3623,'Когда останется 2 ложки сока лимона и 1/3 стакана масла, добавить в процессор белки, оставшийся лимонный сок, масло. Посыпать солью. Взбивать несколько минут. Переложить чесночный соус  лимонным соком в емкость и отправить на 1 час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3624,'Картофель начистить, нарезать кружками, очень тонко не рекомендуется, достаточно будет 4-5 миллиметров. Довести до кипения сливки, добавить соль, положить сюда картофель, прокипятить на небольшом огне 5 минут, снять с плиты, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3624,'В жаропрочную форму выкладывать слоями (можно по желанию подсаливать): слой картофеля, потом тертого сыра. Немножко сыра отложить для присыпания сверху, а сливки пока не трогать, повторять слои несколько раз, последней должна быть картошка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3624,'Затем залить все сливками, закрыть форму фольгой и отправить запекаться на 15 минут (180 градусов). Потом фольгу убрать, присыпать сыром и вернуть в духовку на 10-15 минут. Картофельный гратен с сыром по-французски готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3625,'В крепкую пену взбить белки, к желткам добавить сахар (75 грамм) и также взбивать в пену. К желтковой массе постепенно добавлять просеянную муку и аккуратно смешивать. Добавить соль, осторожно добавить белки и смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3625,'Смазать противень маслом и притрусить мукой, разогреть духовку (150 градусов). Переложить тесто в кондитерский шприц с диаметром отверстия где-то 14 миллиметров. Выдавить из теста шприцом палочки приблизительно 10 сантиметров длиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3625,'Смешать оставшийся сахар и сахарную пудру, половиной смеси присыпать печенье. Оставить его на 10 минут, чтобы сахар растаял, потом снова присыпать смесью. Подождать еще 2 минуты, отправить классическое бисквитное печенье «Савоярди» в духовку и выпекать до золотистого оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3626,'Выложить вишни в глубокую емкость, разморозить в микроволновке и аккуратно удалить косточки, затем переложить их в дуршлаг, чтобы убрать лишнюю жидкость. В отдельную емкость выложить творог, яйца, сахар и хорошо размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3626,'Прибавить муку, перемешать, далее положить корицу и какао. Погасить чайную ложку соды уксусом, положить в тесто, смешать, если тесто выйдет очень густым (не будет спадать с ложки), можно добавить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3626,'В последнюю очередь добавить в тесто ягоды и осторожно смешать, чтобы они не повредились. Форму перемазать маслом, вылить тесто и поставить в нагретую духовку (180 градусов) на полчаса. Домашний творожный пирог с вишней готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3627,'Нарезать колбасу кубиками и обжарить на сковородке (приблизительно 10 минут), по желанию можно добавлять приправы. Нарезать помидоры тонкими слайсами, огурцы соломкой, капусту мелко нашинковать, зелень нарубить, сыр натереть на терке. Взять лаваш, выложить на него колбасу, затем помидоры с огурцами, далее капусту и зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3730,'Проварить маринад несколько минут, потом ввести муку, слегка обжаренную на масле, поставить на медленный огонь и варить еще 15 минут. Влить в конце варки уксус и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3628,'Прежде всего, необходимо испечь блины, сделать это можно по своему любимому рецепту. Также для данного блюда можно использовать блины, которые остались не съеденными с завтрака, например. Начинка: яблоки промыть, почистить и нарезать кубиками (не очень мелкими).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3628,'Растопить сливочное масло в глубокой сковородке, выложить туда яблоки, добавить воду (1/3 стакана) и тушить под крышкой около 10 минут. После того, как яблоки станут мягкими, добавить корицу, сахар, влить сливки, тушить еще 5-7 минут. В результате должны выйти мягкие яблоки, как пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3628,'Форму можно использовать любую (для кекса или хлеба, или просто стеклянную), застелить пленкой, выложить поверх нее блины, края должны хорошо свисать, может уйти около 4 штук. Выложить половину охлажденной начинки, закрыть ее блинами, где-то еще 3 штуки, пюре должно быть полностью закрыто, их можно разрезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3628,'Далее выложить оставшуюся начинку, закрыть свисающими краями, обернуть форму пленкой и отправить в холодильник на ночь. После пребывания на холоде террин станет плотным, так как схватится начинка. Блинный террин с нежной яблочной начинкой нарезать на кусочки и подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3629,'Кости отделить от куриного мяса, отварить из них бульон, мясо порезать кусочками и поджарить с добавлением лука и перца на сливочном масле (около 100 миллилитров топленого масла), поперчить, посолить, присыпать специями по вкусу. Сухофрукты вымыть и залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3629,'Процедить бульон, развести его молоком (соотношение 1:1), посолить и сварить в нем замоченный ранее рис. Когда он свариться, перелить его в дуршлаг и дать стечь жидкости, промывать его нужно в том случае, если он вышел недостаточно рассыпчатым. На стол насыпать пшеничную и кукурузную муку (по 2 столовые ложки).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3629,'Смешать и раскатать на этой смеси слоеное тесто. Раскатанный лист должен закрыть всю внутренность казана и свисать с бортиков. Смазать растопленным маслом дно и стенки казана, уложить тесто, опять смазать маслом, насыпать рис и равномерно полить его топленым маслом по всей поверхности (необходимо приблизительно 100 миллилитров масла).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3629,'Достать из жидкости сухофрукты, немного отжать и выложить поверх риса, далее выложить курицу и овощи, полить жидкостью, которая образовалась от их жарки. Свисающее тесто завернуть и тщательно залепить, смазать маслом, плов должен быть герметично упакован.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3629,'Подогреть духовку до 180 градусов, поставить туда плов и готовить около 40-45 минут. ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3630,'Отварить картофель, натереть на терке, прибавить муку, перемешать. Яйцо взбить в глубокой емкости, вылить в картофель и тщательно смешать. Нарезать полукольцами лук, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3630,'Форму промазать маслом, уложить на дно картофель, потом лук, верх посыпать тертым сыром. Запекать в духовке при 180 градусах, примерно 30-40 минут. Картофельная запеканка под сыром готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3631,'Творог протереть сквозь сито, можно воспользоваться мясорубкой (чтобы не было комочков), добавить соль, яйцо, сахар, сметану, хорошо вымесить, можно при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3631,'Замесить эластичное и мягкое тесто, постепенно добавляя муку, оставить тесто на 15 минут. В это время посыпать сахаром нарезанные кубиками сливы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3631,'Раскатать творожное тесто толщиной 3 мм, кружочки вырезать стаканом, положить на каждый кружочек 1 ч.л. слив и залепить вареник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3631,'Отварить вареники в слегка подсоленной воде, при этом помешивать деревянной ложкой, чтобы вареники не пристали ко дну кастрюльки. Варить вареники после их всплытия 7 минут на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3631,'Достать вареники шумовкой, разложить на блюде. Вареники из творожного теста со сливами можно при желании смазать маслом и присыпать сахаром, подавать можно в горячем виде, а также в холодном в качестве десерта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3632,'Смешать муку, дрожжи и соль, разделить на три равные части. Зеленый хлеб: взбить блендером шпинат, воду (100 миллилитров) и масло, затем сюда добавить одну часть муки, просеянной вместе с солью и дрожжами, вымесить тесто и оставить, чтобы подошло в теплом месте приблизительно на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3730,'Подать готовую рыбу в луковом маринаде по-скандинавски в холодном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8574,'Для приготовления теста смешать овсянку с яйцом и клубникой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3632,'Красный хлеб: вторую часть муки смешать с паприкой молотой, пюре из воды (120 миллилитров) и бланшированного красного перца. Отправить тесто в тепло на час, чтобы поднялось. Желтый хлеб: сделать пюре из запеченной тыквы и воды (50-70 миллилитров), перелить его в просеянную муку с солью и дрожжами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3632,'Также отправить тесто в теплое место на час. Затем взять разные куски теста приблизительно одинакового размера, на присыпанной мукой поверхности сформировать одинаковые колбаски. Верхние края колбасок соединить и сплести из жгутов неплотную косичку, край также закрепить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3632,'Накрыть полотенцем и оставить на 20-30 минут, чтобы подошло. Потом немного смочить верх хлеба водой и каждый вид теста присыпать соответственным видом семян. Выпекать трехцветный хлеб в течение 30-35 минут (220 градусов), охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3633,'Мясо куриное сварить и нарезать маленькими кусочками. Полукольцами нарезать лук, измельчить чеснок, цуккини (1 штуку) нарезать небольшими ломтиками. На сковородке подогреть масло оливковое, добавить чеснок и лук, обжарить. Добавить цуккини и тушить приблизительно 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3633,'Венчиком взбить яйца с солью, влить сливки, прибавить творог, муку и тертый сыр (половину количества). Смешать, добавить курицу и обжаренные овощи, поперчить, посолить, перемешать. Взять форму (можно использовать разъемную или обычную для запеканок), смазать маслом, притрусить мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3633,'Выложить смесь, поперчить и присыпать тимьяном. Второй цуккини порезать тоненькими кружочками, уложить сверху, посыпать сыром, что остался и на 30 минут отправить в духовку (180 градусов). Потом усилить температуру до 220 градусов и печь куриный пирог с творогом и сыром 10 минут, до золотистого оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3634,'Шоколад с маслом растопить на небольшом огне или на водяной бане, постоянно мешать. Белки отделить от желтков, желтки тщательно взбить с сахаром до устойчивой плотной пены в течение 5 минут (важно именно это время взбивания). Осторожно смешать желтки с остывшей шоколадной массой с помощью спатулы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3634,'Отдельно взбить белки с добавлением лимонной кислоты (обязательно до мягких пиков, это важно). Аккуратно вводить частями взбитые белки в шоколадную массу, смешивать осторожно, снизу вверх, миксером взбивать нельзя. Лучше использовать разъемную форму, которую необходимо смазать маслом и присыпать мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3634,'Если используется не разъемная форма, то нужно проложить ее фольгой, чтобы легче было вынимать торт. Тесто перелить в форму и разровнять, выпекать в нагретой духовке (150 градусов) 35-40 минут. Когда пройдет это время, консистенция трюфеля будет дрожать, так и должно быть, она позже дойдет в холодильнике, станет плотной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3634,'Если передержать, то тесто перепечется и станет обычным бисквитом. Сначала десерт необходимо охладить в форме, а потом уже поставить в холодильник на ночь. Хранить шоколадный десерт «Трюфель Евы» нужно в морозилке, порезать кусочками и каждый отдельно заморозить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3635,'Кляр: яйцо смешать с пивом, поперчить, посолить, добавить постепенно муку, тщательно смешать венчиком, отставить, чтобы настоялось. Нарезать мясо кубиками (2х2), переложить мясо в кляр и перемешать. Налить растительное масло в глубокую толстостенную сковородку где-то на 1-1,5 сантиметра, дать хорошо прогреться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3635,'Потом сделать средний огонь и выкладывать ложкой мясо, каждый кусочек отдельно. Когда подрумянится – перевернуть, как только зарумянится и вторая сторона – шумовкой класть на бумажные полотенца, лишний жир уйдет, получатся очень хрустящие кусочки. Полить сочную свинину в пивном кляре, кисло-сладким соусом и  подавать с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3636,'Баклажаны разрезать вдоль и достать серединку, нарезать ее кусочками, смешать с измельченным сладким перцем, томатами и репчатым луком. Полить массу оливковым маслом, приправить специями и солью, уложить в баклажанные лодочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3636,'Поставить имам баялды из баклажан и сладкого перца на противень и печь, пока овощи не сделаются сочными и мягкими. А можно еще, как вариант, перед запеканием залить взбитым яйцом и присыпать сверху тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3739,'Нашинковать свежую капусту, смешать ее со шпиком, выложить в сковороду и поставить на несколько минут в предварительно разогретую духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3637,'Перетереть размягченный маргарин с сахаром, прибавить муку, соль и желтки, замесить однородное тесто, а потом влить несколько ложек воды (обязательно ледяной). Создать из теста шар, положить в пленку и уложить в холод на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3637,'Разогреть духовку (180 градусов). Тесто поделить напополам, одну часть раскатать и поместить на противень (предварительно смазать маслом). Потыкать тесто вилкой по всей поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3637,'Распределить по тесту джем, потереть оставшуюся часть теста на терке поверх начинки. Печь 20 минут. Готовое рассыпчатое печенье с фруктовым джемом нарезать кусочками. Приятного аппетита.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3638,'Вскипятить в кастрюле воду и растворить в ней сахар и соль, дать воде остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3638,'Куринную тушку заранее помыть, обсушить и разрезать на четыре части, куски курицы поместить в подготовленный рассол и оставить просаливаться на двое суток, все это время курицу в рассоле держать в холодном месте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3638,'Просоленные куски курицы, по истечении нужного времени, достать из рассола и отварить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3638,'Для отварной соленой курицы с ананасом по-скандинавски приготовить соус: смешать сливки, майонез и ананасовый сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3638,'Блюдо подавать на листьях зеленого салата, полив соусом, с запеченным картофелем. Украсить свежим или консервированным ананасом, порезанным на кубики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3639,'Выложить джем на сито и перетереть, чтобы получилась прозрачная масса без мякоти и кусочков (где-то 1 столовая ложка), пока отставить, она пригодится, для смазывания готового пирога. Джем с кусочками и лимонную цедру перемешать с маслом и взбивать, пока масса не посветлеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3639,'Потом добавить сахар и еще немного взбить, масса не получится гладкой. Положить творог и взбивать миксером до гладкой, однородной консистенции, по одному добавить яйца, хорошо размешивать после каждого.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3639,'Должна выйти достаточно жидкая смесь. Прибавить к ней оба сорта муки и разрыхлитель и вымесить тесто. Переложить его в смазанную и посыпанную мукой форму, персики достать из сиропа, выложить на тесто, хорошо вдавливать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3639,'Печь 45-50 минут (170 градусов), охладить. Джем без мякоти, что остался, смешать с лимонным соком и подогреть. Кисточкой смазать смесью остывший творожный пирог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3640,'Дать готовому тесту немного оттаять. Раскатывать только в одном направлении, тогда структура его не нарушится, и оно хорошо поднимется при выпечке. Нарезать тесто полосками где-то 3-4 сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3640,'На каждую уложить по 3 или 4 полукольца вареной колбасы (полукруги немного должны выступать над тестом) и аккуратно свернуть рулетом. Нижний край теста обязательно тщательно залепить – розочка при выпечке не поплывет. Выложить розочки на противень с пергаментной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3640,'Верх смазать немного взбитым яйцом. Отправить в духовку на 20-30 минут (220 градусов), готовность смотреть по колбасе, когда края зарумянятся – убавить температуру до 160-170 градусов и дать розочкам дойти. Быстрые слоеные розочки с колбасой немного остудить и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3641,'Растворить дрожжи в теплом молоке с добавлением сахара, чуть подсолить, добавить сметану перемешать и поставить в тепло на 10 минут. Загрузить в хлебопечку смесь муки, оливкового масла, молока и сделать первый замес. Добавить к полученной массе раствор дрожжей и если понадобиться добавить чуть муки, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3641,'Раскатать тесто в пласт толщиной в 3-5 мм. Колбасу порезать соломкой, при желании можно добавить грибы, сыр натереть. На тесто разложить слой начинки, присыпать смесью сушеных овощей и порезать на прямоугольники. Пластинки теста завернуть в трубочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3641,'Переложить рулеты в форму, дать постоять полчаса в тепле, смазать яйцом, присыпать семенами кунжута и маком. Выпекать порционный пирог с сыром и копченой колбасой  в прогретой до 180 градусов духовке около 40 минут. Достать пирог, дать чуть остыть, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3642,'Разрезать каждый пряник вдоль на две половинки, сахар перемешать со сметаной. Обмакнуть кусочки пряников в сметану и разложить на плоском блюде. Сверху положить слоями кусочки ананаса, пряники и снова ананасы. Смазать слои кремом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8574,'Выложить массу в форму, поставить в духовку на 5 – 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3642,'Верх полить остатками сметаны. Убрать пряничный торт с ананасом в холодильник. Когда сметана застынет,  присыпать торт шоколадной стружкой и измельченными орехами. Снова убрать в холодильник, к столу подать утром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3643,'Подогреть молоко и воду, влить в хлебопечку, засыпать муку, дрожжи, сахар, подсолить. Включить режим Тесто и через час тесто будет готово. Достать, разделить на порции, разложить на смазанном противне. Прикрыть тесто полотенцем, дать постоять треть часа в тепле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3643,'Когда пампушки подойдут смазать их желтком, выпекать в прогретой до 200 градусов духовке 20 минут. Раздавить прессом чеснок, перемешать с маслом и порубленной зеленью. Смазать соусом верх чесночных пампушек пока они еще горячие.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3644,'Сухие грибы промыть, желательно холодной проточной водой, проварить, слить воду и снова промыть, затем мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3644,'Пшено вымыть и поставить вариться в той же воде, в которой были сварены грибы. Картофель очистить, нарезать кубиками, через 10-15 минут после того, как пшено закипит, положить подготовленный картофель и варить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3644,'Лук очистить и нашинковать, обжарить с грибами в растительном масле, когда лук зарумяниться, положить его вместе с грибами в пшено, перемешать и довести кулеш с грибами и картофелем до кипения, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3644,'К столу блюдо подать украсив мелко порубленной зеленью укропа и петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3645,'Картофель, сладкий перец и кабачки нарезать на небольшие кубики, мясо – кусочками. Нашинковать лук и морковь на полукольца. Разогреть в утятнице масло, обжарить кусочки мяса со всех сторон, уложить на него слоями овощи подсолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3645,'Залить мясо с овощами 1/2 стакана воды, разложить по верху кружочки помидора. Готовить овощное рагу с куриной грудкой, под крышкой, 40 минут при среднем нагреве. Подавать горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3646,'Прогреть духовку до 170 градусов, перемешать все сухие ингредиенты. Масло взбить с сахаром в воздушную массу, добавить яйцо, ваниль, перемешать. Добавить молоко, частями всыпать мучную смесь и вымесить тесто. Добавить в тесто пюре из бананов и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3646,'Смазать форму маслом, залить тесто, положить сверху шоколадную пасту, присыпать дробленым орехом и поставить банановый пирог с шоколадом и грецким орехом на полчаса в духовку. Дать десерту остыть и нарезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3647,'Нарезать на кусочки филе курицы. Обвалять его со всех сторон в панировке и обжарить на сковороде в разогретом масле. На лист лаваша положить лист салата, на него – кружочки помидора и огурца, мясо, зелень и лук. Смазать начинку смесью из сметаны, майонеза, перца, чеснока, свернуть в трубочку. Ароматный цезарь ролл с курицей готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3648,'Сварить лапшу до готовности, морковь нашинковать соломкой, лук – полукольцами, початки кукурузы разрезать вдоль. Разогреть масло в сковороде вок, обжарить лук в течение минуты. Всыпать измельченный чеснок, морковь и кукурузу и обжаривать все вместе 2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3648,'Положить к овощам лапшу, осторожно перемешать, положить бобовые ростки. В емкости с круглым дном перемешать сок лайма, чили, зеленый лук, соевый соус, сахарную пудру и кориандр. Разложить вегетарианский салат с яичной лапшой по тарелкам, присыпать обжаренными и измельченными орехами вместе с зеленью, добавить соус и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3649,'В кастрюле с толстым дном растопить масло, положить нашинкованный полукольцами лук, тушить до мягкости. Добавить измельченный сельдерей, кружочки моркови, готовить все вместе еще 5 минут. Нашинкованную капусту положить к овощам, залить кипятком и дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3649,'Поперчить, подсолить, добавить паприку и варить, пока капуста не станет мягкой (15 минут). Перемешать фарш, предварительно отваренный рис, кубики лука, нашинкованную петрушку и яйцо до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3649,'Добавить в фарш перец, соль и скатать фрикадельки. Сложить их порциями в кастрюлю к овощам, после всплывания проварить суп с мясными фрикадельками и овощами еще 7 минут. Дать супу настояться под крышкой 10 минут, разлить по тарелкам, посыпать измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Охлажденное печенье отправить в духовку на 8 минут и выпекать при температуре 180 градусов, готовому печенью дать полностью остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3650,'Перемешать фарш с предварительно нашинкованными луком и зеленью. В большую миску насыпать горкой муку, влить  по центру конуса подсоленную горячую воду и перемешать до образования однородного заварного теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3650,'В другой емкости перемешать масло, яйца и муку с добавлением водки, сахара и соли в однородную смесь. Объединить ее с заварным тестом, хорошо вымесить. Полученный колобок обернуть пленкой и дать постоять полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3650,'Раскатать сочни для чебуреков, положить по центру фарш и тщательно залепить края, можно использовать для этого вилку. Разогреть в сковороде масло и обжарить крымские чебуреки с мясом и луком до золотистой корочки, с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3651,'Мясо порезать на кубики и обжарить в разогретом масле со всех сторон. Нашинковать чеснок, добавить в почти готовое  мясо, обжарить около минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3651,'Грибы порезать на кусочки такого же размера, что  и мясо. Добавить грибы к мясу, перемешать и обжаривать все вместе около 5 минут. Влить в сковороду соевый соус со сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3651,'Уменьшить нагрев и готовить соус до его сгущения. Подать куриное филе с шампиньонами под сливочным соусом горячим, с отварным рисом или макаронами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3652,'Просеять муку через сито, соединить с разрыхлителем; сливочное масло растопить, чуть остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3652,'Взбить яйца с сахаром и щепоткой соли добела, всыпать ванильный сахар, осторожно вмешать муку и лимонную цедру, тщательно перемешивая, понемножку добавлять масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3652,'Убрать тесто на холод часа на два (можно даже на ночь).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3652,'Заполнить тестом смазанные маслом формочки на 2/3, отправить в духовку, прогретую до 200-210 градусов, примерно на 10 минут, когда печенье «Мадлен» с лимонной цедрой станет золотистым, вытащить из духовки, из формочек вынимать сразу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3653,'Филе курицы порезать на кусочки, лук – на 4 части, пропустить все через мясорубку или порубить в блендере. Фарш поперчить, посолить, вбить яйцо и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3653,'Для кляра, взбить яйца с солью в достаточно глубокой миске. Намазать на вафельный корж фарш, прикрыть вторым, обмакнуть вафельные бризольки с куриной грудкой в кляр и обжарить в хорошо разогретом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3653,'Для надежности, можно дополнительно пропарить бризольки. Подавать можно с любой кашей, пюре или как самостоятельное блюдо на листьях салата, присыпанное зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3654,'Нарисовать силуэт рыбки на бумаге, разрезать его на части: хвост, туловище, плавники. Из пласта теста вырезать туловище. Выложить на него слой из ломтиков кеты, прикрыть мелко порубленным укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3654,'Приготовить из картофеля пюре, добавить яйцо, дать остыть и выложить на укроп. Из другого пласта вырезать верх туловища, чуть больше, чтобы можно было подвернуть под пласт с начинкой и защипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3654,'Нарезать из тонко раскатанного пласта кружочки для чешуи и выложить их на туловище смазанное белком, начиная с хвоста. Верх пирога «Золотая рыбка» с кетой смазать взбитым желтком, выпекать 25 минут в заранее разогретой духовке',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3655,'Натереть цедру апельсина на мелкой терке. Мягкое масло и сахар взбить в пышную белую массу и, не прекращая взбивать, влить апельсиновый сок. Добавить яйца, апельсиновую цедру, перемешать. Засыпать перемешанную с разрыхлителем муку и вымесить однородное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3655,'Заполнить форму половиной теста, выложить на него ягоды или другую начинку, залить оставшимся тестом. Выпекать апельсиновый кекс с малиной 45 минут при температуре 170 градусов до готовности. Из формы достать, когда кекс полностью остынет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3656,'Для начинки сварить картофель, слить воду и размять его с добавлением масла и горячего молока в однородное пюре. В готовое пюре добавить соль, перец, вбить сырое яйцо, перемешать и укутать кастрюлю с пюре одеялом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3656,'Из муки сделать горку, в углубление на вершине залить слегка подогретое молоко и растопленное масло, добавить сахар, соду, соль, вбить яйцо и вымесить тесто до однородности. Убрать готовое тесто, завернув в пленку, в холодильник на треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3821,'Насыпать в кефир соду и отставить на 5 минут. Затем положить остальные ингредиенты и размешать. Вылить 1/2 теста в смазанную маслом и посыпанную мукой форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3656,'По истечении времени достать, разделать на небольшие шарики и раскатать каждый в сочник, диаметром около 15 сантиметров. Обжарить кыстыбай на сухой сковороде. Готовые лепешки выложить на плоское блюдо, смазывая маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3656,'На половинку лепешки положить начинку и накрыть второй частью, чуть прижав верх. Можно готовые лепешки с начинкой разложить на противне, смазать маслом и поставить на 20 минут в духовку, разогретую до 160 градусов. Перед подачей к столу татарский кыстыбый с картофельным пюре промазать маслом еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'Легкое в приготовлении блюдо для микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'Половину сыра нарезать небольшими кусочками, перемешать с мелко порубленным вареным яйцом, огурцы порезать мелкими кусочками, сардельки — длинными полосками, помидор — кружочками или полумесяцем, мясо индейки и перец измельчить и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'В молоке размешать дрожжи с сахаром, отстоять в тепле 15 минут; смесь должна слегка забродить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'Добавить разведенные дрожжи в муку, вбить яйцо, налить масло и замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'Расправить тесто на противне тонким слоем, выложить первым слоем сыр с яйцами, вторым — огурцы с сардельками, третьим — помидор, четвертым — индейку и перец, сверху засыпать оставшимся мелко натертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3657,'Пиццу с индейкой, сардельками и яйцом готовить 6-8 минут на режиме «полная мощность», подавать охлажденной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3658,'В половине стакана чуть теплого молока, смешанного с чайной ложкой сахара, распустить дрожжи и дать постоять четверть часа. Перемешать остатки молока с кефиром, яйцом, сахаром и солью. Добавить дрожжевую смесь, муку, а если понадобиться, то и масло, и вымесить тесто. Переложить его в пакет из полиэтилена, убрать в холодильник на 2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3658,'Затем раскатать тесто в прямоугольник, смазать маслом и присыпать, перемешанным с корицей, сахаром. Свернуть в рулет, переложить на бумагу для запекания. Сделать ножницами надрезы (толщиной по 1 см). Уложить прорезанные части так: влево, вправо и посередине, затем повторяем технику до последнего кусочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3658,'Рулет уложить на противень, дать постоять 20 минут, накрыв пленкой и выпекать в прогретой до 180 градусов духовке около 20 минут до золотистой корочки. Когда сдобный рулет-плетенка с корицей будет готов, смазать его глазурью из смеси сахарной пудры и небольшого количества воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3659,'Растереть смесь желтков с сахаром, добавить размолотые сухари с мукой, перемешать, всыпать тертый шоколад. Затем влить взбитые в устойчивую пену белки, очень аккуратно перемешать. Заполнить массой подготовленную и смазанную маслом форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3659,'Выпекать в духовке с температурой 180 градусов до полной готовности. Для приготовления крема перемешать с небольшим количеством воды сахар, растопить до коричневого цвета, добавить воду и перемешать до полного растворения карамели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3659,'Отдельно перемешать молоко с растопленным маслом и всыпать муку. Дать массе закипеть и перемешать с карамелью. Промазать коржи бисквитного шоколадного торта остывшим кремом, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3660,'Подогреть духовку (180 градусов), форму застелить бумагой. Перемешать сахар, муку, хлопья и разрыхлитель, потом сюда прибавить масло, яйцо, клюкву, смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3660,'Переложить тесто в форму, утрамбовать, отправить в духовку на 25 минут. Оставить в форме на 10 минут (немного охладить) и нарезать кусочками. Овсяные квадратики с клюквой полить растопленным шоколадом и подавать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'В небольшой, но глубокой емкости развести теплой водой дрожжи и отставить минут на 6-7 в теплое место. Добавить в дрожжи сахар и теплое молоко, перемешать и опять отставить. В муку добавить соль, 60 г сливочного масла и перетереть руками в крошку. Когда дрожжи подойдут, сделать в муке с маслом углубление, перелить туда жидкость с дрожжами и вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'После того, как тесто будет отделяться от стенок посуды, переложить его на стол и вымешивать еще минут 5. Тесто получиться шелковистым и нежным, не будет липнуть к рукам. Скатать тесто в шар, уложить в емкость смазанную маслом, обвалять тесто в масле со всех сторон и прикрыть емкость пленкой или полотенцем. Поставить тесто часа на полтора в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Когда оно подойдет, обмять. Обминать тесто минут 5, потом опять сформировать из него шар, уложить в емкость и оставить приблизительно на час. Затем тесто еще немного обмять, сформировать из него не тонкий прямоугольник, завернуть его в пленку и отправить в холодильник минут на 30. Затем тесто вынуть, раскатать в прямоугольник не тонко (приблизительно размером 16х32).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'На 2/3 площади прямоугольника выложить оставшееся масло, распределить его по поверхности, не доходя до краев 2 сантиметра. Сложить тесто: сначала завернуть край теста (1/3) без масла, углы теста натянуть, должен получиться ровный прямоугольник. При складывании теста, нужно кисточкой убирать лишнюю муку. Потом завернуть край теста с маслом, уголки также натягивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Края немного прижать. Далее перевернуть тесто на 90 градусов, раскатать скалкой от себя и к себе, стараться снова раскатать до размеров 16х32. Сложить тесто книжкой втрое, завернуть в пленку и положить в холодильник. Охлажденное тесто раскатать от себя и к себе и снова сложить книжкой. Перевернуть на 90 градусов и раскатать также как и раньше.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Сложить опять книжкой (получается четвертое сворачивание), теперь тесто готово. Завернуть тесто в пленку и отправить в холодильник или на 45 минут, или до следующего дня. А можно и заморозить. Вынуть из холодильника, снять пленку, раскатать прямоугольником (размер 35х53).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Перерезать тесто вдоль пополам, а дальше каждую половину нарезать треугольниками. Шоколад поломать или порезать на кусочки. В одном яйце отделить желток от белка и смешать с 1 ст.л. молока, белок убрать в холодильник. Формировать круассаны по одному.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Сначала треугольник нужно растянуть в ширину и длину за уголки, у основания треугольника сделать небольшой перпендикулярный разрез. Убрать излишки муки кисточкой, на треугольник выложить немного шоколада, края разреза загнуть поверх шоколада, направляя их в противоположные стороны. Свернуть круассан, по направлению к вершине.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'Вершинку немного смазать желтком, чтобы он не разворачивался, и скрутить тесто полностью. Края загнуть к центру – придать форму полумесяца. Готовые круассаны переложить на смазанный противень, оставляя между ними немного свободного места. Смазать холодной водой, прикрыть сверху полотенцем и оставить приблизительно на час при комнатной температуре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3661,'В теплое место не ставить – масло вытечет, слои не выйдут. К желтку, что остался, влить белок и еще 1 ст.л. молока, взбить. Получившейся смесью смазать поверхность круассанов и поставить противень в духовку (220 градусов), через 3-4 минуты убавить огонь до 180 градусов, продолжать печь еще минут 15-20. Достать круассаны с шоколадной начинкой из духовки и выложить на блюдо. Кушать можно горячими или холодными.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3662,'Нарезать хлеб ломтиками, вырезать мякиш, обжарить их с обеих сторон. Далее в каждый кусок хлеба уложить немного сливочного масла, измельченный лук и грибы, добавить соль и яйца. Поджарить на слабом огне. Готовую яичницу с грибами в хлебе можно подавать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3663,'Взять говядину, порезать брусочками приблизительно 1 сантиметр. В глубокой миске смешать оливковое масло, измельченный чеснок, соевый соус, острый перец, выдавить сок лайма и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3663,'Добавить мясо, хорошо смешать и отправить в холодильник на час или полтора, емкость закрыть пленкой. На сухой разогретой сковородке обжарить до готовности мясо. Переложить мясо на тарелку, поставить рядом томатный соус и добавить зелень. Фахитос по-мексикански с говядиной и лаймом готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3664,'Измельчить блендером вишню и финики без косточек, пока не образуется липкая масса. Миндаль порубить и перебить блендером в крошку. Смешать фрукты и миндаль до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3664,'Переложить массу на противень, застеленный пергаментной бумагой, хорошо утрамбовать. Отправить в холодильник минут на 30, потом переложить на доску и нарезать прямоугольниками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3665,'Перетереть творог со сметаной, добавить цукаты, яйца, изюм и пудинг, все тщательно перетереть до однородной массы. Запарить мак, три раза перекрутить с орехами на мясорубке. Добавить к маку цукаты, сахар, изюм и яйца, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5848,'Потушить в растительном масле капусту до мягкости, посолить, поперчить, переложить в другую емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3665,'Шоколадная масса: взбить яйца с сахаром (минут 5-6), осторожно смешать с какао, мукой и разрыхлителем. В застеленную бумагой форму переложить массу с маком, потом творожную массу, залить все шоколадной массой. Печь 40 минут (190 градусов), достать из духовки, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3665,'Перевернуть торт на бумагу, притрушенную сахаром, и убрать с верхнего коржа бумагу. Крем: перемешать сметану с сахаром, яйцом и кофе. Варить крем на водяной бане, пока не загустеет, охладить. Затем добавить масло и взбивать миксером до пышности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3665,'Перерезать корж напополам. Выложить на тарелку одну часть коржа (маком вверх), смазать кремом, затем положить вторую часть коржа (маком вниз). Украсить шоколадно-творожный торт «Три желания» и поставить на некоторое время в холод, чтобы пропитался.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3666,'Желатин размочить в холодной воде (полстакана). В кастрюлю налить воду, добавить сахар и варить минут 10 на небольшом огне (постоянно мешать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3666,'Потом добавить лимонную кислоту и соду, размешать и варить еще 7 минут. Убрать с плиты, перелить в другую емкость, добавить разбухший желатин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3666,'Взбивать начать на небольшой скорости и постепенно дойти до самой высокой. Когда зефир начнет загустевать, переложить мягкий домашний зефир в формочки (лучше силиконовые) и подождать 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3667,'Положить ванильный сахар и пудру в размягченное масло. Взбивать, пока смесь не будет пышной. Добавить муку (половину порции), смешать миксером на небольшой скорости, должна получиться крошка. Добавить сюда желтки, молоко (или воду), перемешать, всыпать оставшуюся муку и вымесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3667,'Сформировать колбаску, ее диаметр должен быть такой, как пирожные. Обернуть пленкой и отправить в морозилку минут на 40, пока не затвердеет. Потом вынуть тесто, острым ножом разрезать на кружочки, выложить на застеленный противень, немножко приплюснуть рукой. Печь 15 минут (200 градусов), охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3667,'Намочить в холодной воде (2 ст. ложках) желатин и оставить, пока не разбухнет. Перемешать с сахарной пудрой и ванилином белки, установить на водяную баню и взбивать миксером на высокой скорости до густой и пышной массы. Растопить желатин, добавить его в белковую массу, взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3667,'На половину печенья выложить ложкой крем, накрыть оставшимся печеньем. Поставить в холодильник приблизительно на час. Поломать на кусочки шоколад, прибавить растительное масло и растопить в микроволновке или на водяной бане. Перемешать. Достать пирожные из холодильника, обмакнуть их бока в глазурь, выложить на поднос и полить глазурью сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3667,'Поставить минут на 15 в морозилку, и как только глазурь застынет, перевернуть пирожные на бумагу и полить опять глазурью. Снова отправить в морозилку на 15 минут. Потом домашнее пирожное «А-ля Choco-Pie» в шоколадной глазури достать из морозилки и хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3668,'Все ингредиенты смешать и замесить тесто. В отдельной емкости смешать кардамон, сахар и корицу. Раскатать из теста прямоугольник, смазать всю его поверхность растопленным маслом, присыпать предварительно порубленными орехами и смесью с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3668,'Скрутить рулетом и тонко порезать. Переложить булочки на противень, закрыть пленкой и оставить на 45 минут в теплом месте, чтобы подошло. Затем смазать их яйцом, взбитым с водой, отправить в нагретую духовку на полчаса (до корочки золотистого оттенка).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3668,'Глазурь: частями добавлять в пудру молоко и взбивать миксером до однородности. Получившейся смесью залить еще теплые сдобные булочки с корицей и грецким орехом.Сдобные булочки с корицей можно подавать к чаю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3669,'Взбить масло и сахар до густоты и пышности. Добавлять яйца по одному и тщательно взбивать. Добавить разрыхлитель и просеянную муку, смешать. Далее влить молоко и мешать, пока не выйдет однородного теста. Поделить на 3 части, одну из этих частей разделить еще на 3. Из них одну оставить как есть, во вторую добавить какао, а в третью – пищевой краситель (оранжевый).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3675,'Положить сметану и сливки, вылить смесь в емкость для морозилки. Замораживать, взбивая каждые 2 часа. Затем положить крупно натертый или мелко поломанный шоколад.Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8416,'Полученной смесью натереть куриное мясо, оставить для пропитывания на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3669,'Форму смазать маслом, 1/3 часть теста тонко налить в форму, тестом с какао нарисовать спиральку, поверх нее нарисовать спираль оранжевым тестом, затем опять шоколадным и снова оранжевым. Щели, что остались, заполнить белым тестом, верх также осторожно залить белым тестом, выпекать. Таким же образом выпечь 3 коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3669,'Крем: взбить с сахарной пудрой сливочное масло (100 грамм белого крема отложить для украшения), добавить растопленный шоколад (50 грамм растопленного шоколада также оставить для украшения), тщательно перемешать. Коржи перемазать кремом, украсить оригинальный «Леопардовый» торт пятнышками, как окрас леопарда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3670,'Через мясорубку перекрутить помидоры, отправить на огонь, прибавить масло, соль, сахар, лавровый лист, черный перец и уксус. Прокипятить 30 минут, далее положить нарезанный перец, прокипятить еще минут 5-10. Закатать в банки, перевернуть, закутать и оставить, пока полностью не остынет. Можно хранить домашнее лечо из болгарского перца всю зиму, а начинать кушать уже через сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3671,'Перемешать муку с солью и разрыхлителем, сливочное масло с сахаром взбить миксером. Продолжать взбивать и добавить яйца, потом добавить ванилин и мучную смесь, вымесить тесто, сделать из него шар, обернуть пленкой и положить в холодильник часа на два, а лучше на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3671,'В смазанную маслом форму натереть половину количества теста, немного прижать, смазать джемом, натереть оставшуюся часть теста. Выпекать минут 35 (175 градусов), пока верх не зарумянится. Тертый ванильный пирог с джемом охладить и перед подачей притрусить пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3672,'Нагреть духовку, намазать сливочным маслом две формочки. В большой емкости растереть пальцами цедру и сахар. Вбить яйца, взбивать после каждого добавления. Положить йогурт, ванилин, масло, две больших ложки сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3672,'Насыпать соль, разрыхлитель, муку. Замесить тесто. Разлить равномерно по двум формочкам, готовить минут 40. Намазать коржи оставшимся соком при помощи кисточки для пропитки. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3672,'Приготовить глазурь: довести сок грейпфрута до кипения в кастрюле и варить, пока не останется 1/4 стакана. Остудить. В посуде взбить сливочное масло и цедру до однородности. Налить загустевший сок, насыпать медленно сахарную пудру, размешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3672,'Постепенно добавлять по одной ложке сливки, пока не будет нужная консистенция. Нанести глазурь на каждый корж, обильно полить верх и украсить. Йогуртный торт в грейпфрутовой глазури готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3673,'Получается ароматное, хрустящее печенье за счет добавления в тесто цедры апельсина. Вбить в муку яйца, насыпать сахар. Растопить на водяной бане или в микроволновой печи маргарин. В остывшем виде влить к другим продуктам, положить апельсиновую цедру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3673,'Все размешать, замесить песочное тесто. Раскатать, порезать небольшими полосками. Готовить печенье 15  минут, соблюдать температуру 180 градусов. Достать печенье, чуть-чуть остудить. Посыпать сахарной пудрой. Хрустящее апельсиновое печенье к чаю подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3674,'Взбить до однородности яйца, молоко, муку, чтобы получилось без комков. Положить измельченный укроп. В формочку положить пергамент. Намазать растительным маслом при помощи силиконовой кисточки, залить омлетом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3674,'Готовить минут десять, соблюдать температуру 160 градусов. Приготовить начинку: на растительном масле поджарить лук, морковь. Отдельно обжарить грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3674,'Соединить грибы и поджарку из лука и моркови, положить измельченный шпинат. Посыпать перцем и солью. Выложить начинку на готовый омлет и осторожно свернуть плотный рулет. Украсить готовый рулет из омлета с грибами по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3675,'Подогреть молоко в кастрюле, но не доводить до кипения. Остудить 2 минуты. Взбить отдельно сахар и желтки. Медленно влить охлажденное молоко. Поставить на огонь и готовить (5 минут) помешивая, пока смесь не станет густой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3675,'Отставить, чтобы смесь полностью остыла. Очистить от косточек вишню, положить в кастрюлю с водой. Готовить минут 5, на небольшом огне. Взбить вишню в кухонном комбайне или блендером, отставить. Соединить пюре и яичный крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Склеить половинки попарно малиновым или земляничным джемом и слегка сжать, сверху посыпать сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3675,'Отправить в морозилку пока не затвердеет, лучше на ночь. Переложить сливочное мороженое с вишней и шоколадом в холодильник на 30 минут. Подавать мороженное в креманках, украшенное по желанию вишней и шоколадной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Вымыть клубни, не очищать шкурку, а просто вырезать ножом подозрительные места. Срезать верх. Если положить клубень набок, это сделает будущую кокотницу просторной и большой. Осторожно при помощи чайной ложечки выскрести мякоть, чтобы получились бортики и донышко по 7 миллиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Для данного блюда мякоть больше не понадобится. Положить кокотницы в холодную воду, чтобы картофель не стал темным. Разогреть духовку до 190 градусов. Приготовить грибной жульен. Положить на сковороду сливочное масло, когда оно растает, положить измельченные грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Мешать, пока грибы не выделят сок и не осядут. Тушить несколько минут при умеренной температуре, положить измельченный лук. Тушить еще 5 минут, помешивая. Положить приблизительно половину столовой ложки муки, чтобы жульен загустел. Хорошенько все размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Когда мука равномерно разойдется, налить сливки или сметану, если нравится пикантная кислинка. Совсем чуть-чуть посыпать солью, черным молотым перцем и тушить смесь, пока она не загустеет. На это уйдет 3 минуты. Убрать сковороду с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Вытряхнуть из кокотниц воду, положить их на противень (или жаростойкую емкость), смазанный топленым или сливочным маслом. Во все кокотницы из картофеля положить по несколько крупинок соли, черного молотого перца, маленькому куску сливочного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'При помощи ложки выложить в кокотницы грибы, тушеные в сметане или в сливках, равномерно распределить. Отправить начиненные кокотницы в духовку. Готовить 15 минут, соблюдая температуру 190 градусов.  Достать кокотницы, посыпать жульен тертым сыром, чтобы над начинкой получилась крышка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3676,'Она не даст начинке подсохнуть. Отправить кокотницы опять в духовку. Выпекать еще 20 минут. Если сверху и вокруг картофеля образовалась румяная корочка, то жульен готов. Грибной жульен в картофельных кокотницах полить топленым сливочным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3677,'Поставить на огонь кастрюльку, налить около двух литров воды. Помыть свинину, порезать на маленькие кусочки. Порезать и измельчить лук. Почистить и крупно потереть морковь. Обжарить свинину на сковороде с растительным маслом до образования корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3677,'Чтобы мясо не пригорело, готовить его на небольшом огне. Когда вода закипит, положить лук, а потом мясо. Накрыть крышкой, готовить минут тридцать на тихом огне. Обжарить до золотистости морковь на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3677,'Почистить картофель и порезать на брусочки. Положить в суп морковь, картофель и помидоры,  порезанные на кусочки. Посолить. Готовить минут пятнадцать. Выключить огонь, положить в ароматный суп с жареной свининой измельченный укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3678,'Помыть и подсушить ягоды, удалить плодоножки и веточки. Перемешать ягоды, посыпать сахаром, полить соком лимона. Позволить настояться минут пятнадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3678,'Взбивать холодную сметану, пока не получится густая масса. Насыпать сахарную пудру и еще несколько минут взбивать. Салат из ягод полить сметаной заправкой и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3679,'Порубить сливочное масло и муку, вбить яйцо, посыпать солью. Замесить тесто. Отправить минут на пятнадцать в холодильник. Измельчить зеленый лук, пожарить в сливочном масле, посыпать перцем, солью, охладить. Порезать филе лосося на полоски, перемешать с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3679,'Остальные яйца смешать со сметаной, перцем, солью. Тесто раскатать в пласт, положить в формочку, намазанную маслом, чуть-чуть приподнять краешки. На тесто сверху положить лосося с лучком, залить смесью из яиц. Готовить немецкий пирог с лососем и зеленым луком примерно 6 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'На плиту или водяную баню поставить кастрюлю, положить в нее сливочное масло и насыпать стакан сахара. Когда масло и сахар чуть-чуть растворится, добавить соду, порошок-какао, размешать, убрать с огня. Вбить по одному яйцу, взбить ложкой или вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3700,'В молоко всыпать сахар (полстакана оставить), варить, помешивая полчаса на малом огне. Арахис обжарить на сухой сковороде до легкого загара, удалить шелуху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Отмерять по стакану воды и медленно вмешивать в тесто. Приблизительно уйдет 2,5 стакана муки. Можно насыпать два стакана, отправить посуду с тестом в холодильник на час, чтобы оно затвердело. После этого посмотреть, нужно ли досыпать еще.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Должно получиться тесто, которое можно будет раскатать, оно не должно липнуть. В любой момент можно досыпать муку, важно, чтобы ее не было много, потому что тогда коржи получатся очень твердые и не пропитаются кремом. Нагреть духовку, достать тесто из холодильника.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Разделить на шесть приблизительно одинаковых частей. Каждую часть раскатать в тоненький пласт на специальной бумаге, посыпанной чуть-чуть мукой. Чтобы измерить размер, необходимо сверху пласта прикладывать тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Ничего страшного, если он будет неровный, главное, чтобы тарелка помещалась. Каждый корж выпекать по пять минут в горячей духовке. Отделить приготовленный корж от бумаги при помощи большого ножа, осторожно отделять по кругу с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Приложить тарелку, обрезать по кругу, обрезки положить отдельно. Помыть и порезать маленькими кусочками чернослив. Взбить сметану и стакан сахара до необходимой консистенции. Измельчить обрезки в крошку, собрать тортик.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Намазать все коржи кремом, посыпать измельченным черносливом. Положить один коржик на другой, прижать его чуть-чуть ладошками, чтобы крем распределился по всей поверхности. Постараться распределить чернослив по всем коржам, кроме верхнего.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3680,'Наверх выложить оставшийся крем, посыпать измельченной крошкой от коржей. Отправить тортик в холодильник часа на три, а лучше на ночь для пропитки. Можно дегустировать шоколадный торт с черносливом и нежным кремом, с чаем или кофе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3681,'Порезать мармелад на небольшие кусочки. Растереть ванильный и обычный сахар с маслом. Положить сметану, размешать. Положить мармелад, размешать. Насыпать муку и разрыхлитель, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3681,'Постелить специальную бумагу в формочку, намазать маслом, положить равномерно тесто. Готовить пирог на апельсиновом мармеладе 30 минут, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3682,'Сделать тесто из муки, сливочного масла, цедры лимона, сахарной пудры, желтка и соль. Сформировать из теста шар, отправить в холодильник минут на шестьдесят. Разогреть духовку. Намазать формочки маслом, присыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3682,'Раскатать тесто в тоненький пласт, положить в формы тесто, осторожно распределить по дну и стенкам. Сделать проколы вилкой. Отправить в холодильник на 30 минут. Затем поместить корзиночки в духовку и выпекать 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3682,'Остудить, каждую намазать смородиновым джемом. Растворить желатин в воде. Перемешать сахарную пудру, сметану и цедру лимона. Подогреть сок лимона, вылить его в желатин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3682,'Соединить со сметаной. Накрыть, отправить минут на 30 в холодильник. Наполнить корзиночки кремом, сверху положить ягоды. Лимонные корзиночки с черникой и джемом готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3683,'Залить несколько больших ложек овсяных хлопьев несколькими большими ложками молока, подождать, пока набухнут. Яблоки очистить и нарезать на дольки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3683,'Положить в миксер сметану, сахар, яблоки и лимонный сок. Взбивать 30 секунд. Положить хлопья и еще раз взбить. Яблочно-овсяная каша для малышей готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3684,'Обжарить колбасу на сковороде. Положить на тарелку, накрытую салфеткой. Отставить в сторону. На среднем огне обжарить тоненько порезанный лук, пока не подрумянится и не станет мягким. В маленькой кастрюльке смешать специи, базилик, томатный соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3684,'Отправить на тихий огонь, мешать, пока содержимое не нагреется. Убрать с огня, охладить. Тесто для пиццы поделить на четыре части. Все части раскатать в круг по 20 миллиметров диаметром. Положить сверху по большой ложке соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3684,'На него выложить обжаренную колбаску, пепперони, обжаренный лук. Посыпать натертым сыром. Свернуть тесто пополам, краешки защипнуть. Взбить яйцо, намазать им кальцоне. Готовить кальцоне с салями и сыром в духовке 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3700,'Расплавить оставленный сахар на сковороде до коричневатого цвета, смешать с молочным сиропом и варить щербет около часа до готовности. Затем добавить масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3685,'Подготовленную рыбу порезать очень острым ножом на стейки 3 сантиметровой толщины. Кусочки присыпать перцем, подсолить с каждой стороны, переложить в глубокую посуду, посыпать сушеными помидорами (можно без них) и паприкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3685,'Дать постоять (пока готовятся угли), разложить на решетке, обжарить с обеих сторон, семга на решетке будет готова примерно через 15 минут. Рыбу сразу надо переложить на блюдо, чтобы не прилипла к решетке и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3686,'Сложить очищенные крабовые палочки в чашу блендера, измельчить, сыр – натереть на  мелкой терке, смешать оба ингредиента, добавить соус, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3686,'Развернуть лист лаваша, смазать полученной начинкой. Завернуть лаваш в трубочку и порезать на кусочки не толще 2,5 см. Закусочные рулеты из лаваша с соусом тартар выложить на сервировочное блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3687,'Подсоленную воду довести до кипения, опустить в нее на 10 секунд тушки кальмаров, вынуть шумовкой, дать остыть, нарезать на кольца толщиной примерно по полсантиметра. Нагреть сухую сковороду, высыпать семена кунжута, помешивая поджарить до золотисто-соломенного цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3687,'Влить на сковороду масло, уксус, добавить специи, измельченный чеснок, соевый соус, прогреть полученный маринад. Снять его с плиты и залить колечки кальмаров. «Хе» из кальмаров  в соевом соусе остудить, а потом поставить в холодильник часов на 10, блюдо подавать холодным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3688,'Всыпать в яйца сахар, взбить до состояния белой пены, тщательно перемешать с размягченным маслом, размять бананы в пюре. Объединить пюре и масляную смесь, добавить соду, всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3688,'Вымесить тесто, дать ему созреть четверть часа. Тесто раскатать в пласт, вырезать формочками печенье. Отправить банановое печенье в духовку с температурой 180 градусов. Через 20 минут печенье будет готово. Приятного чаепития!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3689,'Почистить отварные креветки, зубки чеснока разрезать пополам. Сковороду разогреть и смазать сливочным маслом, насыпать кус-кус, залить кипятком, варить на среднем огне, помешивая зубчиками вилки 5-7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3689,'Положить сливочное масло, подсолить и осторожно перемешать, кус-кус должен быть рассыпчатым. Нагреть в сковороде на сильном огне оливковое масло, добавить сливочное, перемешать, дать ему растаять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3689,'Всыпать измельченный чеснок, обжаривать примерно полминуты. Добавить креветки, поперчить, подсолить и все вместе обжаривать еще 5 минут. Смешать кус-кус с креветками и соусом.  Кус-кус с креветками и чесночным соусом подать горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3690,'Филе грудки отбить, присолить, поперчить, готовое тесто раскатать в пласт, уложить на него мясо, свернуть в рулет, порезать на кусочки толщиной примерно по полтора сантиметра. Обмакнуть полученные рулетики одной стороной в семя кунжута и разложить на выстланный пергаментом и промазанный маслом противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3690,'Выпекать закусочные куриные рулетики с кунжутом, в заранее прогретой до 180 градусов духовке, примерно 40 минут. На дно духовки, чтобы мясо осталось сочным и не пересохло, следует поставить миску с водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3691,'Нашинковать помидор и лук на кольца, листья салата порвать руками. Фарш приправить перцем, подсолить, перемешать, сформовать котлетки. Для удобства руки можно смочить холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3691,'Булочки разрезать пополам, срезы зажарить на сковороде или гриле, смазать их соусом или кетчупом, поверх уложить колечки лука. Обжарить котлетки по паре минут с каждой стороны, уложить на лук, прикрыть ломтиками сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3691,'Завершить сооружение колечками помидора. Смазать помидор смесью горчицы с майонезом, уложить поверх листья салат и прикрыть второй половинкой булочки. Домашний чизбургер с сыром можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3692,'Нарезать все овощи переложить в большой таз, перемешать, влить масло с уксусом, добавить лавровый лист, горошки перца, соль и сахар, тщательно вымешивать, час дать постоять для выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3692,'Сложить в кастрюлю, нагреть до кипения, проварить четверть часа, разложить горячий салат «Кубанский» из капусты и овощей по стерилизованным банкам и закатать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5719,'Разогреть на сковороде масло. Готовить по несколько минут с каждой стороны под крышкой. Подавать пышные дрожжевые оладушки с медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3693,'Залить манку сметаной, дать примерно час постоять, вбить яйца, всыпать сахар, тщательно перемешать. Добавить муку с содой, вымесить тесто, чашу смазать маслом, обсыпать стенки и бока сухой манкой, излишки ссыпать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3693,'Заполнить чашу тестом, выставить на режим выпечка, и готовить традиционный манник в мультиварке, примерно час. Откинуть крышку, дать маннику немного остыть, перевернуть на тарелку, украсить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3694,'Рыбу порезать на куски, поперчить, присолить, обжарить пару минут в разогретом масле, разложить на многослойное бумажное полотенце для впитывания масла. Помидоры разрезать пополам, сыр – на кубики, смешать все с листьями шпината.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3694,'Заправить салат со шпинатом, лососем и сыром фета небольшим количеством лимонного сока, добавить раздробленные в блендере грецкие орехи, поперчить, посолить, перемешать. На широкую тарелку выложить рыбу, а рядом горкой – салат. Приятного аппетита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3695,'Размять бананы в пюре, перемешать со стружкой, переложить на коврик, выстланный пленкой, выровнять слоем в полсантиметра. Поверх разложить порезанные ягоды клубники, плоды киви, свернуть в ролл и на 15 минут поставить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3695,'Распустить шоколад, равномерно обмазать ролл, пока он не застыл присыпать орешками и малиной, вернуть в морозилку, перед подачей к столу порезать ролл на кусочки. Сладкие банановые роллы в темном шоколаде можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3696,'В просеянную подсоленную муку добавить мускатный орех, добавить яичный желток, взбитые яйца, растопленное масло, влить молоко, все взбить в однородную массу. Сковороду смазать растопленным маслом, испечь блины (6-8 штук), обжаривая с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3696,'Обжарить в масле чеснок и лук, добавить грибы, обжарить до готовности. Базилик нашинковать, перемешать с рикоттой, натертым пармезаном, порезанной на кусочки моцареллой, смешать с грибами, поперчить по вкусу и посолить, аккуратно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3696,'На каждый блин положить по центру начинку, завернуть края. Переложить блины по-итальянски с грибами и сыром в форму для запекания, присыпать стружкой пармезана, положить кусочки масла, выпекать треть часа в разогретой заранее духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3697,'Сахар поделить на две части, одна- 230 г, другая – 140 г. Перемешать с меньшей частью яблочное пюре, добавить ванильный сахар, дать постоять. Залить агар-агар водой, растворить, дать закипеть, всыпать вторую (большую) часть сахара, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3697,'Варить пока раствор не начнет тянуться за ложкой, затем убрать с плиты, дать остыть. Взбить пюре и половину белка (масса должна побелеть), добавить оставшийся белок и продолжить взбивать. Влить тонкой струйкой при непрерывном перемешивании раствор агар-агара, можно добавить краситель и взбить еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3697,'Заполнить полученной смесью кондитерский мешок, высадить домашний яблочно-ванильный зефир на ровную поверхность, присыпанную сахарной пудрой, дать постоять пару часов и ароматный десерт будет готов. Приятного чаепития!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3698,'Мягкое масло перемешать, используя миксер, с сахаром до состояния пышной массы, добавить оставшийся сахар и яйцо, взбить на средней скорости, добавить второе яйцо, продолжать взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3698,'Яблоки почистить, порезать на кубики, сбрызнуть лимонным соком, перемешать. В масляно-яичную массу всыпать подсоленную муку и разрыхлитель, перемешать до получения густого теста, всыпать яблоки и еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3698,'Заполнить полученной массой формочки. Выпекать нежные яблочные кексы в прогретой до 200 градусов духовке около 20 минут. Готовые кексы присыпать корицей, перемешанной с сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3699,'Отварить очищенный картофель, лук нашинковать полукольцами, чеснок натереть, перемешать с четвертой частью бульонного кубика и перцем. Лук потушить до мягкого состояния, порезать яйца, ветчину, нашинковать зелень петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3699,'Взбить сметану с добавлением перца, горчицы и соли, добавить ветчину, лук, яйца, зелень и тщательно перемешать. Нашинковать картофель кружочками, уложить в форму, залить подготовленной смесью, присыпать сыром. Выпекать картофель с ветчиной и сыром при температуре 200 градусов около 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Соединить пряности с соевым соусом тереяки, маслом, чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3700,'Форму выстлать бумагой, насыпать дробленые орехи, залить щербет и убрать в прохладное место до полного застывания. Готовый щербет с дробленым арахисом порционно нарезать.  Приятного чаепития!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3701,'Обжарить фарш на малом огне, подсолить, поперчить. Добавить кубики предварительно нарезанного лука, томатную пасту, перемешать и тушить до полной готовности фарша. Дать остыть. Очистить кабачок, семена удалить, мякоть крупно натереть, отжать от сока и уложить половину в форму, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3701,'Прикрыть фаршем, поверх разложить вторую порцию кабачка, чуть присолить. Накрыть кружочками помидора, подсоленную сметану взбить с яйцами и залить помидоры, присыпать тертым сыром. Отправить запеканку из кабачков с мясом и помидорами на 30 минут в духовку, с температурой 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3702,'Все подготовить, капусту помыть, разделить на соцветия, отварить, переложить в смазанную форму. Распустить сливочное масло, всыпать муку и обжарить, помешивая пока мука не потемнеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3702,'Затем влить подсоленные сливки, добавить карри, кориандр, асафетиду и тертый сыр, перемешать. Залить соусом капусту. Убрать запеканку из брокколи и цветной капусты с сыром, на 30 минут в духовку. Готовую запеканку достать, остудить и разрезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3703,'Картофель порезать соломкой, хорошо промыть, отварить, морковь натереть и обжарить вместе с луком на масле. Добавить зажарку в суп, сцедить и отжать грибы, положить в кастрюлю к картофелю, проварить 5 минут. Всыпать промытый рис и варить 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3703,'Затем влить в суп из сушеных грибов молоко, подсолить, дать закипеть и проварить еще пару минут. Убрать кастрюлю с плиты, всыпать в суп мелко нашинкованную зелень, положить масло, прикрыть крышкой, дать постоять минут 10. Ароматный суп из сушеных грибов с рисом разлить горячим по тарелкам и кушать. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3704,'Свежее натуральное молоко смешать с поваренной солью, поставить емкость на плиту. Отдельно взбить сметану с сырыми куриными яйцами. Довести молоко до кипения, влить яичную смесь тонкой струйкой, продолжать помешивать, чтобы избежать пригорания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3704,'Сыр можно готовить на водяной бане. В процессе термообработки должны появиться белые хлопья, отделится прозрачная сыворотка. Прогреть массу еще в течение 5  минут, не передерживать. Подождать, пока остынет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3704,'В дуршлаг положить марлю в три-четыре слоя, вылить творожную смесь. В неё добавить рубленую зелень укропа или по желанию, можно добавить изюм, нарезанные сухофрукты или мелкие кусочки сладкого болгарского перца любого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3704,'Отцедить творожную массу в течение получаса, вынуть из дуршлага, обернуть  головку марлей и положить под пресс. В качестве груза можно использовать банку с водой или кастрюлю. Домашний адыгейский сыр с зеленью будет готов через  5 – 6  часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3705,'Очищенные креветки большого размера выложить в смазанную оливковым маслом форму для выпекания в один слой. Отдельно смешать свежий лимонный сок, тертую цедру лимона, молотый острый красный перец, измельченный чеснок, оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3705,'Полить полученной смесью креветки. Печь при температуре 250 градусов в течение 8 – 10 минут, до готовности. Готовые острые креветки с лимоном в чесночном соусе посыпать свежей рубленой зеленью петрушки, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3706,'В емкости большого размера довести воду до кипения. Добавить соль, отварить капусту брокколи и цветную до полуготовности в течение 3  минут. Откинуть овощи на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3706,'Свежее филе семги нарезать небольшими кусочками, по 2 сантиметра. Для приготовления соуса смешать в глубокой миске сырые яйца, сливки, тертый сыр. Взбить смесь вилкой или венчиком. Соль и перец – по вкусу, добавить сушеный базилик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3706,'В подготовленную форму выложить капусту и рыбу, залить соусом.  Печь блюдо в духовом шкафу в течение 20 – 30 минут, до зарумянивания верха. Подать запеканку из брокколи, семги и цветной капусты к столу, в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3707,'Желатин из пакетика залить молоком, оставить для набухания на час или полтора. Затем смесь прогреть на тихом огне, помешивать, продукт должен полностью раствориться. Добавить сахарный песок, ванилин, перемешать и остудить до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3707,'Протереть через сито или с помощью блендера нежирный творог, консистенция продукта должна стать пастообразной. В желатиновую смесь добавить нежирную сметану, все перемешать с творогом. Полученную массу разделить на две равные части. В одну добавить какао-порошок, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3707,'В форму для десерта налить светлый слой, поставить в холодильник или в морозилку на 15 – 20 минут. На застывший первый слой вылить темную массу, снова поставить в холод для застывания. При подаче оригинальный творожный десерт без выпечки разрезать на порционные куски, украсить ягодами, фруктами или тертым темным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3708,'Если для приготовления используется полуфабрикат, варено-мороженые креветки, то их достаточно залить кипящей водой и оставить на две минуты. Для сырых креветок разогреть в сковороде немного растительного масла, лучше использовать оливковое, положить креветки вместе с зубчиком очищенного чеснока, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3708,'Морепродукты быстро обжарить по две минуты с каждой стороны, переложить на бумажные полотенца, чтобы впитался лишний жир. Разрезать пополам или на четвертинки, в зависимости от размера, помидоры черри. Сыр настрогать небольшими полосками с помощью овощечистки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3708,'Выложить в салатник промытую и очищенную рукколу. Добавить остальные ингредиенты, перемешать. Бальзамический уксус смешать с молотым перцем и солью по вкусу. Сбрызнуть полученной смесью салат из креветок, рукколы и помидоров черри при подаче на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3709,'Мелко нарезать перо зеленого лука, укроп, лук-репку. Добавить в смесь нежирный творог, перемешать вручную или с помощью блендера. Ржаной хлеб намазать полученной творожной пастой, сверху – слои тонко нарезанного редиса, свежих огурцов и ломтики семги слабого посола. Сэндвич  на ржаном хлебе с семгой готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Выжать сок из лимона. Чеснок, зелень петрушки розмарина, тимьяна растереть в ступке или порубить как можно мельче. Все продукты соединить, подлить оливковое масло, молотый острый красный перец, смесь взболтать вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Куриное  филе разрезать пополам вдоль, положить в полиэтиленовый пакет или пищевую пленку, отбить молотком до толщины в полсантиметра или чуть больше. Переложить подготовленное филе в контейнер с маринадом, закрыть, потрясти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Оставить на 10 минут для пропитывания. Молодую морковь вымыть, очистить, нарезать тонкими кружочками. Небольшие корнеплоды можно готовить целиком. Отварить овощ в кипящей воде с солью в течение семи-восьми минут и откинуть на дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Маринованное куриное филе обжарить на сковороде без жира с антипригарным покрытием, по две минуты с каждой стороны. Готовое мясо положить на тарелку и накрыть фольгой, чтобы не остыло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Огонь убавить до умеренного, обжарить на той же сковороде очищенные и раздавленные зубчики чеснока целиком, в течение полминуты. Добавить подготовленную морковь, жарить при постоянном помешивании 3-4 минуты на сильном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3710,'Добавить спаржевую фасоль, жарить еще 2 минуты. Готовые овощи посолить по вкусу и перемешать. Выложить куриное филе на тарелки, гарнировать овощами. Куриную отбивную с морковью и фасолью можно подавать как в горячем, так и в холодном виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3711,'Киви и яблоко очистить и нарезать кусочками, взбить в блендере до однородного пюре. Влить свежий сок лимона и яблока, без мякоти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3711,'По желанию добавить сахарный песок, перемешать. Вылить коктейль «Витаминная бомба» с яблоком и киви в стакан, добавить пищевой лед, посыпать молотой корицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3712,'Перемешать куриные сырые яйца с нежирным творогом и манной крупой. Смесь поставить в холодильник на ночь или поместить на 20 – 25 минут в морозильную камеру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3712,'Присыпать стол манкой, сформовать из творожного теста колбаску, разрезать на небольшие кусочки и переложить в кипяток. Довести до кипения и варить 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3712,'При подаче ленивые вареники из творога можно полить вареньем или медом, сметаной, посыпать сахаром, украсить свежими или размороженными ягодами малины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5726,'Молодой картофель вымыть и порезать вдоль на 8 частей (чистить не надо).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Намазать смесью грудки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3713,'Отдельно взбить белки в плотную пену со щепоткой лимонной кислоты. Ввести в тесто порциями, осторожно перемешивать. Разлить готовую массу в формочки. Печь порционный чизкейк с мармеладом при температуре 190 градусов в течение 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3714,'Отварить картофель в мундире, остудить, снять кожицу, мякоть нарезать кубиками. Измельчить помидоры, свежие или малосольные огурцы, репчатый лук. Все ингредиенты перемешать и полить подсолнечным маслом, соль – по вкусу. Салат из картофеля и свежих овощей можно подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3715,'Отварить куриные яйца, разрезать на половинки, вынуть желтки. Распечатать банку консервированного тунца, рыбу размять вилкой. Зеленый лук мелко нарезать и добавить к тунцу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3715,'Полить смесь лимонным соком, посолить, специи – по вкусу. Перемешать. Наполнить массой белковые лодочки. Яйца, фаршированные зеленым луком и тунцом выложить на блюдо, украсить и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3716,'Смешать овсяные хлопья с разрыхлителем, влить молоко, жидкий натуральный мед, вбить сырое яйцо. Массу хорошо перемешать, перелить в форму.  Добавить кусочки банана, выложив их поверх, в произвольном порядке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3716,'Печь овсяную запеканку с медом и бананами в заранее разогретой духовке, при температуре 180 градусов в течение 30 – 40 минут. Готовую запеканку, перед подачей к столу, порционно нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3717,'Тыквенную мякоть нарезать кубиками, выложить в форму для запекания, накрыть фольгой. Печь при температуре 200 градусов в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3717,'Фольгу снять, прогревать запеченную с творогом и цукатами тыкву еще пять минут. Добавить творог, изюм, цукаты, перемешать. По желанию блюдо можно полить медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3718,'Перемешать творог, нежирный кефир, сырое яйцо, манную крупу и разрыхлитель, добавить фруктозу. Массу хорошо перемешать. Банан и киви очистить и нарезать кружками, вмешать в творожную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3718,'Печь блюдо в течение 35 – 40 минут при температуре 180 градусов. Готовую творожную запеканку с бананом и киви нарезать порциями и кушать. Можно посыпать сахарной пудрой и украсить листочками мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3719,'Брокколи разобрать на соцветия.  Зеленые соевые бобы и капусту брокколи отварить в кипятке в течение 2  минут, воду слить, овощи положить в форму изо льда, продукты не должны потерять цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3719,'В салатницы выложить порционно хорошо вымытый и обсушенный зеленый салат «Айсберг», брокколи, бобы, очищенные и нарезанные авокадо, отваренные вкрутую и накрошенные яйца, готовые креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3719,'Взбить с водой майонез и кунжутное масло. Сбрызнуть полученной заправкой энергетический салат с креветками и авокадо и посыпать кунжутным семенем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3720,'Отварить гречневую крупу до готовности в подсоленной воде. Для лучшего упаривания укутать кастрюлю в одеяло или плед на 10 минут. Затем почти готовую кашу посолить по вкусу и перемешать. Шампиньоны промыть под проточной холодной водой, просушить бумажным полотенцем, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3720,'Очистить и мелко нарезать репчатый лук. Зелень петрушки и укропа промыть и мелко нарезать. Поставить глубокую сковороду на огонь, влить немного растительного масла, сначала обжарить лук в течение 4  минут, затем – шампиньоны (10 минут). Посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3720,'Оставить массу на несколько минут, снять с плиты сковороду. Остывшую смесь переложить в блендер, измельчить до однородности. Добавить зелень, снова измельчить. Соединить упревшую гречневую кашу с грибной массой, хорошо вымесить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3720,'Сформовать из фарша котлеты небольшого размера, удобнее это делать мокрыми руками. Каждое изделие панировать в сухарях и обжарить до золотистой корочки. Переложить домашние котлеты из гречки с шампиньонами в глубокую сковороду, добавить питьевую воду, потушить 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3721,'Нарезать брынзу кубиками. Соединить сырые куриные яйца с солью, перцем и молоком, смесь взбить с помощью венчика. Шпинат обдать кипяченой водой, мелко нарезать, жарить на растительном масле в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3721,'Добавить яичную смесь и нарезанную брынзу, жарить пять минут, допекать в духовке еще столько же. Быстрый омлет со шпинатом и брынзой выложить на блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Зеленый салат порвать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3722,'Чернослив мелко нарезать, растолочь в ступке орехи, обжарить овсянку на сухой сковороде в течение пяти минут. Перемешать овсянку, чернослив и орехи, добавить горячую воду, подливать ее постепенно, по столовой ложке. Смесь должна стать густой и липкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3722,'Добавить мед, перемешать. Сковороду смазать оливковым маслом, выложить смесь, разровнять, утрамбовать. Если масса получилась жидковатой – добавить овсяные хлопья. Поставить сковороду на тихий газ, закрыть крышкой, прогревать лепешку с каждой стороны по 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3722,'Масса должна подрумяниться, уплотниться, но не подгореть. Чтобы изделие аккуратно перевернуть – его нужно положить на тарелку и перевернуть, затем переложить обратно и подрумянить вторую сторону. Готовый овсяный  десерт с черносливом и орехами остудить и нарезать квадратиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3723,'Сырые куриные белки взбить в плотную пену, добавить заменитель сахара по вкусу и ванилин из пакетика. Желатин залить водой, дать набухнуть, нагреть, но не кипятить до растворения, остудить до комнатной температуры. Готовый желатин влить в белковую пену, взбить. Разлить десерт спортсмена из взбитых белков в формы и поставить в холодильник на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3724,'Лисички хорошо промыть, нарезать мелкими кусочками. Налить масло на разогретую сковороду, выложить грибы, обжаривать продукт в течение 10 минут. Смешать яйца с молоком, взбить вилкой, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3724,'Вылить подготовленную массу на сковороду, готовить омлет в течение 5 минут. Посыпать пышный омлет с лисичками рубленым укропом, петрушкой, можно украсить овощной нарезкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3725,'Яблоки вымыть, очистить от кожуры, сердцевину удалить. Фрукт натереть на мелкой терке, сделать пюре, залить холодным кефиром и взбить. Добавить в напиток мед и немного молотой корицы, взбить еще раз. Разлить яблочно-медовый коктейль на кефире по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3726,'Нарезать сырую куриную грудку кусочками небольшой величины, посолить. Перемешать соевый соус с давленым чесноком, замариновать в смеси куриное мясо в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3726,'Обжарить курицу на сковороде на сильном огне до появления корочки, с двух сторон. Листья салата промыть и просушить, порвать руками. Свежий огурец нарезать полукольцами, помидоры – произвольно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3726,'Все овощи и зелень перемешать, посолить, поперчить, полить оливковым маслом, перемешать и положить сверху кусочки курицы. Диетический овощной салат с куриной грудкой подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3727,'Мелко нарезать яблоко, поставить в микроволновую печь на 4 минуты, мощность – максимальная. Овсяные хлопья залить кипяченой водой, добавить соль и варить до выкипания жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3727,'Влить немного молока, перемешать, довести до кипения. Накрыть кастрюлю крышкой, дать каше постоять, через пять или семь минут добавить яблоко, мед и перемешать. Овсяная каша с яблоками и медом готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3728,'Желатин всыпать в четверть стакана холодной воды, дать постоять пять минут. Довести до кипения, но не кипятить, плиту выключить, добавить желатин, помешивать до растворения. Перемешать сахарозаменитель и ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3728,'Желатин должен остыть. Отдельно в миске взбить яичные белки. Влить медленно желатин, взбить миксером в течение 15 минут на высокой скорости. Смесь должна приобрести консистенцию густой пены и немного остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3728,'Перелить массу в неглубокую форму с антипригарным слоем или равномерно выложить на пергамент. Остудить. Домашний диетический «Маршмеллоу» через  4  часа можно будет разрезать ножом на куски и подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3729,'Смешать творог, манку, яйцо, сахарозаменитель и ванилин, вымесить. Поломать горький шоколад на кусочки. Сформовать лепешку из теста, положить кусочек шоколада, защипать. Сформовать сырник, обвалять его в овсяных хлопьях и обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3730,'Разделать рыбу на филе, удалить косточки, нарезать на большие порционные куски, запечь их в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3730,'Приготовить луковый маринад, для этого мелко нашинковать коренья и лук, до золотистого цвета обжарить их в масле, залить небольшим количеством кипяченой воды, добавить соль, лавровый лист и прочие приправы по собственному вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Насыпать сахарную пудру на поднос, хорошенько обвалять шарики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3731,'Для приготовления блюда понадобятся сырые куриные яйца большого размера. Отделить желтки от белков. Белки положить в холодильник, в один из желтков добавить сахарозаменитель, ванилин, влить йогурт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3731,'Массу перемешать. Залить нектарины кипятком на пять минут. Кожицу снять, косточку вынуть, мякоть нарезать кусочками. Накрошить миндаль. Охлажденные белки взбить в густую, плотную пену. Вмешать ее в йогуртную смесь, аккуратно перемешать так, чтобы она не опала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3731,'Измельчить миндаль в крошку, добавить кусочки нектарина, снова перемешать все вместе. Вылить массу в форму, предварительно застеленную пищевой пленкой. Сверху накрыть ей же, поставить в морозилку на 3 часа. При подаче дать йогуртному семифредо с нектаринами и миндалем немного подтаять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3732,'Натереть на терке луковицу и кабачок. Добавить в овощную массу яйца, соль, молоко, перец молотый, рубленую зелень, отруби. Тесто должно быть по консистенции чуть гуще, чем на блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3732,'Для приготовления начинки обжарить куриный фарш без масла вместе с нарезанным луком.Посолить, поперчить, добавить рубленую зелень. Сковороду нагреть, налить тесто. На схватившийся блин выложить фарш, края должны остаться свободными. Накрыть фарш свободной стороной блина, прижать лопаткой края так, чтобы они склеились.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3732,'Для приготовления начинки обжарить куриный фарш без масла вместе с нарезанным луком. Печь чебуреки из кабачка с куриной начинкой  на тихом огне под крышкой, до румяной корочки, с двух сторон. При подаче чебуреки можно украсить веточками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3733,'Финики разрезать на половинки, косточки удалить. Бананы нарезать небольшими кусочками. Все ингредиенты поместить в чашу блендера вместе с кубиками льда, взбить на высокой скорости. Перелить йогуртный  смузи с бананами и финиками в высокие охлажденные стаканы, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3734,'Для приготовления теста хорошо взбить сырые куриные белки с солью. Отдельно взбить желтки, добавить мягкий творог, отруби, перемолотые в муку. Вмешать взбитые белки. В форму выложить половину теста, начинку, сверху – остатки теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3734,'Для приготовления начинки понадобится отварное куриное филе, маринованный огурец, пассерованный лук. Печь заливной пирог с курицей и отрубями при температуре 180 градусов в течение 20 – 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Замесить из муки, соли, яйца, сметаны и сливочного масла (200 г) тесто. Поставить в холодильник на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Приготовить за это время фарш из говядины и свинины, измельчить зелень, свежие грибы, луковицу, натереть сыр на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Растопить на сковороде сливочное масло, поджарить грибы, лук, петрушку, мясной фарш, сыр, добавить по вкусу перец и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Разделить на две части тесто, раскатать одну часть и выложить на противень, смазанный маслом, затем выложить начинку и накрыть вторым пластом, края следует хорошо защепить, чтобы мясо не сочилось,можно украсить верхний пласт плетенкой из тонких полосок теста, смазать сырым яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Поставить паштет из говядины и свинины по-скандинавски в разогретую духовку, выпекать до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3735,'Подавать паштет к столу в горячем виде со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3736,'Банан и киви очистить, нарезать кусочками или измельчить в пюре с помощью блендера. Влить молоко, нежирный кефир, мед, всыпать молотый имбирь. Массу взбить до однородного состояния. Молочный напиток с медом и фруктами разлить в бокалы и украсить фруктами, например, кружочком киви.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3737,'Яйца отварить. Обжарить нарезанные пластинками шампиньоны с луком. Порезать кубиками свежие огурцы. Нашинковать соломкой крабовые палочки. Все ингредиенты смешать, соль – по вкусу. Заправить грибной салат «Аленка» с крабовым мясом майонезом и посыпать зеленью петрушки. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3738,'Смешать сгущенное молоко и яйцо, всыпать просеянную муку. Добавить гашеную уксусом или лимонным соком соду и вымесить. Застелить противень бумагой для выпечки, вылить на неё тесто в виде прямоугольника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3738,'Печь 15 минут при 180 градусах.  На горячий выпеченный корж выложить клубничный мармелад. Свернуть в рулет, в этом поможет бумага и прихватки. Дать остыть. Быстрый рулет с клубничным мармеладом нарезать и подать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3739,'Приготовить из баранины крепкий бульон, заправить его тертой на терке морковью и луком, обжаренным на масле до золотистого цвета, добавить капусту, тушенную в духовке со шпиком и дать повариться на слабом огне некоторое время. Затем добавить в кастрюлю картофель, нарезанный соломкой, перец, соль, лавровый лист по вкусу, копченую колбасу (мелко нарезанную кубиками), после этого варить до готовности картофеля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3739,'Заправить щи с бараниной и шпиком «Скандинавские» сметаной перед тем как подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3740,'Отделить желтки от белков. Взбить в пену белки, добавить сахарную пудру, влить лимонный сок. Заранее замочить в воде желатин, затем разогреть и немного остудить. Тонкой струйкой влить в белки, одновременно взбивая венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3740,'Сварить какао, прогреть, чтобы немного загустело. Влить также предварительно распущенный желатин. Часть какао влить в форму, остудить в холодильнике, затем слой белковой массы, снова дать застыть, третий слой – какао. При подаче шоколадно-лимонный торт «Птичье молоко» выложить на блюдо, посыпать какао-порошком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3741,'Приготовить смесь из одного яйца, майонеза, томатной пасты или кетчупа, порезанной сосиски или колбасы, тертого сыра. Добавить по вкусу зелень и любые специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3741,'Массу намазать на кружки немного черствого белого батона, выложить на смазанный противень, печь в духовке 5 минут. Дать постоять в духовке с выключенным огнем еще 2  минуты и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3742,'Промыть квашеную капусту, дать стечь воде. Порубить столько же свежей белокочанной капусты, смешать и обжарить в сотейнике на растительном масле. Добавить порезанные маринованные огурцы, влить бульон, тушить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3742,'Тонко порезать репчатый лук и морковь, пассировать на масле в течение 2 – 3 минут. Добавить томатную пасту, жарить еще две минуты, постоянно помешивая массу. Положить полученную обжарку в капусту, туда же — порезанные маринованные грибы, половинки маслин, долить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3742,'Перец-горошек, лавровый лист, соль, сахар – по вкусу. Прогревать на тихом огне 10 минут. За две минуты до готовности всыпать мелко нарубленную зелень петрушки, укропа. Грибная солянка с квашеной капустой и маслинами готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3743,'Смешать сметану с манной крупой и оставить на час для набухания. Отдельно взбить яйца с сахаром, добавить манку со сметаной, хорошо перемешать. Всыпать в массу муку и разрыхлитель, замесить тесто средней густоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3743,'Вылить тесто в смазанную форму, поставить в духовку на 40 – 50 минут, печь при 180 градусах.  Готовность ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3744,'На хлеб выложить твердый сыр нарезанный пластинками, затем колбасу. Смазать любым острым  томатным соусом, сверху – хлеб. Затем опять слой колбасы, соус, сыр и снова хлеб, смазанный сливочным маслом. Прогреть острые горячие бутерброды с сыром в духовке в течение 5 минут',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3745,'Нарезать картофель и мясо птицы небольшими кубиками, а репчатый лук – кольцами (если луковица слишком крупная, то лучше нарезать полукольцами), потереть морковь на мелкой терке, все ингредиенты сложить в глубокую посуду, хорошо перемешать, соль и перец добавить по вкусу, при желании можно добавить и другие приправы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3745,'Разложить получившуюся смесь в небольшие глиняные горшочки, в воде развести томатный соус, майонез, горчицу, тщательно все это перемешать, чтобы образовалась однородная смесь, затем влить в уже подготовленные горшочки с мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3745,'Поставить в разогретую предварительно духовку горшочки примерно на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3745,'К столу подавать птицу в духовке по-скандинавски в горячем виде, украсив перед этим содержимое каждого из горшочков веточками зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3746,'Рулетики готовятся из тонких слайсов порезанных баклажан, которые необходимо порезать и посолить. Когда сойдет жидкость, слить. Слайсы обмакнуть в муку и обжарить в небольшом количестве растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3746,'Жареные баклажаны выкладывать на бумажное полотенце, чтобы убрать лишний жир. Начинку для рулетиков из орехов, чеснока, кинзы и сметаны измельчить в блендере до пастообразной массы. Если паста сухая, тогда добавить небольшое количество воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6375,'Все подготовленные ингредиенты переложить в кастрюлю, добавить перец и соль, все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3746,'Добавить специи по вкусу. Охлажденные баклажаны намазать начинкой и свернуть рулетами. Украсить рулеты из баклажан по-кавказски зернами граната и свежими веточками кинзы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3747,'Чтобы получились  баурсаки, необходимо приготовить дрожжевое тесто на опаре. Для этого в теплом молоке растворить ложку сахара, соль и дрожжи. Соленую опару оставить на 20-30 минут, чтобы дрожжи растворились в молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3747,'Затем в тесто влить майонез и взбитые яйца. Просеянную муку всыпать в мягкое тесто, затем оставить для подъема в теплом месте. Когда тесто увеличится в два раза, смять его руками и выложить на стол, смазанный растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3747,'Раскатать тесто в пласт толщиной в 1 см. Выдавить из него стаканом или рюмкой кружки. В толстостенной кастрюле или в высокой сковороде раскалить растительное масло. Жарить баурсаки в растительном масле как во фритюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3747,'Готовые золотистые шарики выкладывать на бумажное полотенце. В тесте мало сахара, чтобы баурсаки прожарились внутри. Традиционные казахские баурсаки можно присыпать сахарной пудрой и подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3748,'Для приготовления роллов необходимо творог соединить с разными начинками. В одну половину всего творога добавить сметану и ложку меда. Хорошо перемешать при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3748,'В другую часть творога добавить несколько ягод спелой клубники и ложку сахарной пудры. Смесь также измельчить в блендере. Для формирования роллов из творога необходимо взять пищевую пленку и присыпать всю ее поверхность цветной кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3748,'Затем по пленке распределить творожную массу, аккуратно формируя ровный прямоугольник. По поверхности разложить порезанный чернослив или кусочки банана, и свернуть творог рулетом при помощи пищевой пленки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3748,'Использовать белую творожную массу с цветной кокосовой стружкой, а розовую с белой стружкой. Ровные творожные роллы с медом и фруктами выложить на тарелку и украсить свежими фруктами или веточкой мяты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3749,'Чтобы приготовить творожные оладьи, необходимо творог измельчить в блендере или протереть через сито, чтобы разбить все кусочки. Муку всыпать, пока не получится тесто консистенции густой сметаны. Взбить миксером все ингредиенты, добавить муку и вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3749,'Раскалить сковороду и налить 2 ложки растительного масла. Ложкой выкладывать творожные оладьи на сметане на сковороду и жарить с двух сторон под накрытой крышкой. Вкус оладушек можно разнообразить добавлением в тесто сухофруктов, орехов или свежих ягод',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3750,'Для приготовления курочки в банке необходимо окорочка или куриную тушку порезать на маленькие порционные кусочки и сложить их в глубокую миску. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3750,'Лук очистить от кожуры и порезать тонкими полукольцами. Добавить в миску к курице и хорошо перемешать. Чистые стеклянные банки наполнить куриным мясом с луком и накрыть каждую банку фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3750,'В холодную духовку поставить курочку в банках. Теперь включить духовку на 200 градусов и готовить блюдо 45 минут. Курочка, запеченная в банке готова. Пропаренное сочное мясо подавать с картофельным гарниром и овощным свежим салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3751,'Для приготовления закуски необходимо смешать в блендере творог, сметану, зелень, чеснок, перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3751,'Томаты нарезать на тонкие кружочки и выложить на широкое блюдо. Сверху каждого кружочка ложкой выложить творожную начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3751,'На творог посыпать тонко порезанный перец и свежий огурец. Томаты с творожным кремом и овощами украсить зеленью и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3752,'Чтобы приготовить слоеную картофельную запеканку необходимо отварить очищенный картофель до готовности и потолочь в пюре, слив жидкость полностью. Лук очистить, порезать мелким кубиком и обжарить с фаршем на сковороде до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3752,'Чтобы фарш был сочным, во время приготовления добавить немного воды. Обжарить лук и морковь, порезанные соломкой. Добавить шампиньоны, также нарезанные соломкой и немного протушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'Хорошо промыть картофель, кожицу лучше не срезать. С одного бока отрезать 1/3 часть клубня. Использовать для жульена будем большую часть. Если клубни крупные, то можно резать их на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3752,'В картофельное пюре вбить одно яйцо и белок, немного взбить миксером или венчиком до пышной массы. Форму для выпекания выложить бумагой для выпечки, смазать всю поверхность сливочным маслом и посыпать панировочными сухарями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3752,'Выложить в форму 1/3 картофельного пюре, затем слой мясного фарша, разровнять ложкой края. Опять картофельное пюре, грибную начинку. Верх запеканки выложить картофельным пюре, разровнять аккуратно края и смазать поверхность яичным желтком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3752,'Сыр натереть на средней терке и посыпать ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3753,'Нарезать мясо говядины небольшими кубиками и слегка обжарить на сковороде. Чтобы мясо стало более мягким, его можно проварить полчаса в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3753,'Порезать мелко лук и сардины и добавить к готовому мясу, при желании лук можно слегка обжарить на масле, смешать с сырыми желтками, поперчить, посолить, салат «Татарский» с сардинами и говядиной должен получиться острым, можно добавить немного масла от сардин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3753,'Также можно приготовить морковь по-корейски, для этого натереть морковь на терке соломкой длинной, добавить хмели-сунели, перец, измельченный чесночный зубчик, соль, сухую кинзу, таким же образом приготовить свеклу по-корейски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3753,'Добавить в салат морковь и свеклу по-корейски, все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3753,'Перед подачей на стол салат украсить несколькими веточками петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3754,'Для приготовления мраморного пирога необходимо делать два теста: белое и шоколадное. Белое тесто — творожное. Необходимо взбить блендером творог, яйца, сахар, ванилин и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3754,'Шоколадное тесто готовится из растопленного шоколада, мягкого масла и взбитых яиц с сахаром. В эту массу добавить разрыхлитель, ванилин и просеянную муку с какао. Все тщательно размешать ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3754,'Тесто в пироге получается наливное. Форму для пирога застелить пергаментной бумагой. Налить на дно часть шоколадного теста. Затем выложить творожные шарики по всей поверхности. Залить шоколадным тестом и ложкой порисовать по всему пирогу, создавая разводы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3754,'Затем вылить остаток шоколадного теста, чтобы выровнять поверхность пирога. Выпекать в умеренной духовке 40-45 минут. Проверить готовность пирога деревянной палочкой. Украсить охлажденный творожно-шоколадный мраморный пирог сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3755,'Репчатый лук порезать тонкими полукольцами и обжарить на растительном масле до готовности. Шампиньоны порезать соломкой и отдельно обжарить на растительном масле до золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3755,'Отваренную морковь натереть на крупной терке или порезать очень тонкой соломкой. Крабовые палочки нарезать вдоль, получив длинную соломку. Также обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3755,'Все ингредиенты соединить, добавить мелко нарезанный укроп. Хорошо размешать, добавив майонез. Не стоит добавлять много майонеза из-за наличия растительного масла в продуктах. Салат «Нежный» с шампиньонами готов, приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3756,'Очистить сырую морковь и натереть на крупной терке. Твердый сыр также натереть на крупной терке. Копченую колбасу порезать соломкой. Открыть банку кукурузы, слить жидкость и высыпать ко всем ингредиентам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3756,'Перемешать все продукты, посолить и поперчить по вкусу. Чеснок пропустить через пресс, добавить майонез. Все перемешать и выложить в салатницу. Украсить ароматный салат с копченой колбасой свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3757,'Для приготовления запеканки необходимо отварить картофель в мундире до готовности, но не переварить. Средние клубни варить после закипания воды 6-7 минут, затем воду слить, а остывший картофель порезать на небольшие кружки, толщиной 2 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3757,'Ломтики бекона обжарить до золотистой хрустящей корочки на сковороде, затем выложить их на бумажное полотенце, чтобы оно впитало лишний жир. В этом жиру обжарить лук до мягкости, к нему высыпать порезанные грибы и жарить до готовности. В конце приготовления выдавить в грибы чеснок и притрусить перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3763,'Разложить овощи и грибы по банкам, переложить их пряностями, долить в отвар от перца и сельдерея воды до нужного количества, добавить сахар и довести до кипения,влить в кипящий отвар уксус, снова довести до кипения и залить им овощи и грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3757,'Для приготовления основы для запеканки необходимо взбить миксером или блендером яйца со сливками, оливковым маслом и горчицей. Затем всыпать натертый сыр пармезан, перец и тимьян. В эту массу добавить картофель и грибы. Форму для запекания выложить бумагой для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3757,'Затем вылить всю массу для запеканки, засыпать поверхность тертым сыром и зеленью. Выпекать картофель с грибами и беконом под сливками 50 минут, до золотистой корочки. Когда блюдо остынет, порезать на порционные кусочки и полить сметаной или посыпать свежей зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Нарезать помидоры кружочками, натереть морковь на крупной терке, нарезать кольцами лук, выложить все в таз, добавить 100 г соли, сахар, и оставить на ночь (примерно на 10-12 часов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Слить по прошествии данного времени из овощей жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Приготовить на сковороде маринад из масла растительного, уксуса, сахара, добавить горошины черного перца и лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Подготовленные овощи залить маринадом (горячим), все тщательно перемешать, варить на медленном огне примерно полчаса, периодически помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Разложить горячий салат с зелеными помидорами и морковью по-татарски по стерилизованным горячим банкам, закатать, потом перевернуть вверх дном банки и укутать их до полнейшего остывания полотенцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3758,'Салат готов! Через несколько дней можно подавать закуску на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3759,'Для приготовления этого блюда необходимо отобрать крупные красные помидоры. Надрезать дольки помидоров толщиной 1-1,5 см. Дольки до конца не прорезать. Соединить мясной фарш, порезанный мелким кубиком лук, соль и перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3759,'В помидорные карманы вложить фарш, чтобы получилась гармошка. Противень для запекания смазать растительным маслом, выложить начиненные помидоры, сверху сбрызнуть маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3759,'Залить помидоры томатным соком. Запекать блюдо 30-40 минут на среднем огне, чтобы фарш зарумянился. Закусочные помидоры, запеченные с фаршем подавать горячими, украсив кольцами болгарского перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3760,'Смешать томатную пасту, соевый соус, майонез, соль, мед, паприку и черный перец. Получается замечательный маринад для куриных крылышек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3760,'Положить куриные крылышки в маринад на 60 минут. Готовить в духовке 30 минут при температуре 200 градусов. Куриные крылышки в домашнем маринаде готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3761,'Приготовить соус: соединить кетчуп и майонез, чуть-чуть посолить. Сварить в подсоленной воде креветки. Отварить картофель и яйца.  Измельчить свежий огурец, яйца, картофель, лук-порей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3761,'Мелко натереть сыр. Выложить ингредиенты слоями. Каждый слой полить соусом. Слоеный салат с креветками и свежим огурцом подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3762,'Приготовить начинку: помыть курагу, залить водой, насыпать сахар и варить, пока не станет мягкой, откинуть на дуршлаг, остудить. Сироп, оставшийся после варки отставить. Замесить дрожжевое тесто опарным методом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3762,'Сформировать из него овал и переложить на противень. Выровнять, наколоть вилкой по всей  лепешке, чтобы она не вздулась во время выпечки. Равномерно выложить на тесто кусочки кураги, загнуть бортик и намазать сиропом, который образовался при варке кураги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3762,'Готовить открытый пирог с янтарной курагой при температуре 190 градусов, пока он не станет румяным. Готовый пирог смазать сиропом от варки кураги, с помощью кисточки. Для украшения использовать цветы из теста, смазанные сиропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3763,'Тщательно промыть очищенные грибы, нарезать кусочками, погрузить в подсоленную кипящую воду, добавить немного уксуса, довести до кипения. Грибы варить 5 минут. Ополоснуть грибы холодной водой и подождать, пока стечет вода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3763,'Очистить и нарезать лук кружочками, нарезать очищенный корень сельдерея пластинками, положить в подсоленную кипящую воду, довести кипения, отварить в течение 15 минут и вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3763,'Отварить в той же воде сладкий перец, нарезанный полосками, достать его шумовкой и оставить обсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3771,'К шашлыку из баранины с бараньей почкой по-карски отдельно подать молотый сушеный или свежий барбарис и соус ткемали.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8574,'Отдельно приготовить крем из мягкого творога, изюма, ванилина, молотой корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3763,'Закрыть банки и установить их в бак с горячей водой для стерилизации, при температуре около 90 градусов время стерилизации составляет 20 минут, банки с салатом-заготовкой из овощей и грибов по окончанию стерилизации немедленно охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3764,'Соединить в емкости ингредиенты для маринада. Порезать курицу пополам или на большие куски. На несколько часов положить в маринад. Смазать оливковым маслом форму для выпекания. Выложить в формочку маринованное мясо курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3764,'Накрыть фольгой, готовить 70 минут, соблюдая температуру 200 градусов. Снять фольгу и готовить курицу в остром медовом маринаде еще 20 минут, поливая образовавшимся бульоном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3765,'Отварить, почистить и порезать яйца. Отварить брокколи, обдать холодной водой и выложить на сито. Порезать бекон и помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3765,'Все выложить красиво на тарелочку, посыпать орешками. Приготовить заправку: соединить уксус бальзамический, мед и оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3765,'Положить прессованный чеснок, измельченные каперсы и базилик. Насыпать перец, соль. Взбить блендером. Заправку для салата из брокколи с перепелиным яйцом и беконом подавать отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3766,'Миксером взбить яйца, соль и сахар. Добавить сметану, растопленное сливочное масло, взбить миксером. Всыпать разрыхлитель, муку, налить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3766,'В готовое тесто добавить измельченный укроп, порезанные оливки, колбасу или готовое мясо, порезанное на маленькие кубики, мелко натертый сыр. Посыпать перцем и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3766,'Постелить в формочку пергамент, положить ложкой тесто. Готовить закусочные кексы с колбасой и оливками в духовке 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3767,'Сделать из филе индейки фарш, вбить яйца, влить молоко, добавить специи, соль и размешать. Взять пленку, положить фарш в виде колбаски. Пленку с фаршем плотно скатать и завязать концы. Варить 7 минут. Домашние диетические сосиски из индейки готовы. По желанию готовые сосиски можно немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3768,'Отварить куриное филе. Выложить снизу вверх слои: мясо, тертый сыр, вареное яйцо. Затем выложить натертую свежую морковь с редькой, снова мясо, тертый сыр, яйцо. Все слои смазать майонезом. Сверху слоеный салат с курицей и редькой обложить половинками винограда и посыпать ореховой крошкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3769,'Вымыть, почистить и порезать груши на четыре части, вырезать сердцевину. Сбрызнуть соком лимона. Соединить какао, муку и разрыхлитель, просеять. Отделить желтки и белки. Взбить белки с солью. Смешать желтки с водой, сахаром, ванилином, взбивать, пока сахар не растворится и не получится пена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3769,'Осторожно ввести в белковую смесь желтки. Медленно всыпать муку, помешивая круговыми движениями. Налить 1/2 теста в формочку, по кругу положить кусочки груш, вылить остальное тесто. Готовить 40 минут, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3769,'Приготовить глазурь: измельчить шоколад и масло, соединить со сливками и растопить. Охладить, постоянно помешивая. Украсить ароматный пирог «Груши в шоколадном бисквите» глазурью и шоколадными фигурками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3770,'Крупно нарезать морковь, лук и печень. Соединить масло растительное со сливочным и обжарить на нем ингредиенты 7 минут, помешивая. Если, проткнув печень ножом, появился светлый сок, то она готова. Охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3770,'Отварить яйца. Пропустить печень, яйцо, лук и морковь через мясорубку. Хорошо размешать. Посыпать перцем, солью. Добавить приправы для печени, мускатный орех. Получается начинка из печени и лука, для блинов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3771,'Срезать с мякоти поясничной и спинной частей баранины грубые сухожилия, разрезать мясо на куски поперек волокон из расчета один кусок на порцию, посолить, замариновать со специями и луком (10 г).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3771,'Надеть кусок мяса перед жаркой на шпажку вместе с очищенной от пленки почкой (бараньей) на одном конце и некрупным помидором на другом, смазать мясо сливочным маслом или курдючным топленым салом, жарить над углями на решетке или на вертеле до готовности, периодически поворачивая к огню другой стороной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3771,'Жареный шашлык, помидор и почку при подаче снять со шпажки и положить на блюдо, украсить долькой лимона, зеленым луком и кольцами репчатого сырого лука, веточкой сельдерея или петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'С помощью маленькой ложки выскрести середину, чтобы края и дно были 7 миллиметров толщиной. Положить кокотницы в воду, чтобы картофель не стал темным. Пока будет разогреваться духовка, приготовить жульен.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'Растопить сливочное масло на сковороде, положить измельченные шампиньоны или другие грибы. Подождать пока грибы осядут и тушить 3 минуты, добавить измельченный лук. Готовить 7 минут. Помешивая всыпать муку, чтобы жульен загустел. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'Налить сметану или сливки, чуть-чуть посолить, поперчить и тушить, пока сливки не станут густыми, то есть еще 4 минуты. Выложить обсохший картофель на противень или в жаростойкую емкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'Положить во все кокотницы немного перца, соли и кусочек масла. Ложкой выложить в картофель грибы, тушенные в сметане и равномерно распределить. Поместить емкость или противень в духовку, готовить, соблюдая температуру 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3772,'Спустя 15 минут достать кокотницы и посыпать жульен сыром, чтобы над начинкой образовалась корочка и не дала ей подсохнуть. Поставить вновь в духовку и выпекать 20 минут. Если по бокам и сверху появилась румяная корочка, то жульен из шампиньонов в картофеле готов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3773,'Взять филе щуки и, не обращая внимания на маленькие кости, пропустить через мясорубку. Положить булку/хлеб, размоченную в молоке. Насыпать специи для рыбы, добавить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3773,'Сформировать котлетки, выложить на противень или сковороду, налить воды и готовить сочные котлеты из щуки, пока не станут румяными.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3774,'Соединить муку и дрожжи, добавить остальные ингредиенты. Тесто месить  5 минут, не добавляя дополнительно муку. Сформировать шарик, положить в емкость, накрыть тарелкой и поместить в теплое место, чтобы тесто вдвое увеличилось. Обмять его и поделить пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3774,'Посыпать стол мукой, раскатать прямоугольник толщиной около двух сантиметров. Поделить на двенадцать частей. То же повторить со второй частью. В центр положить по чайной ложке начинки. Слепить концы по диагонали, смачивая их водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3774,'Положить получившиеся подушечки на противень, накрыть полотенцем и отставить на 25 минут. Намазать яйцом и готовить в духовке 30 минут, соблюдая температуру 190 градусов. Сдобные булочки «Подушечки» с клубничным повидлом накрыть полотенцем и отставить еще на 10 минут. Посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3775,'Приготовить тузлук: насыпать в воду сахар и соль. Сахар и соль сыпать без горки. Растворять их или в холодной воде, или вскипятить, а затем охладить. Красную рыбу выложить в емкость для заморозки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3775,'Налить тузлук, накрыть тарелкой и отправить в морозилку на 24 часа. Размораживать, пока лед полностью не растает. Вынуть рыбу, сполоснуть в воде, обсушить салфетками и смазать растительным маслом. Красная рыба, засоленная в морозилке готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3776,'Предварительно отварить и почистить овощи. Порезать морковь, отварное  мясо, свеклу и крабовые палочки на кубики, измельчить сыр, виноград порезать на половинки. Смешать все ингредиенты и заправить салат «Жизнь в розовом цвете» майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3777,'Свежую капусты вымыть под холодной водой, снять верхние листья, отрезать от кочана часть капусты примерно в 60 г.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3777,'Белокочанную свежую капусту нашинковать тонкой короткой соломкой, нарезать кубиками яблоки, очищенные от семян и кожицы, соленый огурец порезать кружочками, если огурец крупный – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3777,'Отварить яйца вкрутую, остудить и почистить, мелко нарезать, потереть сыр на крупной терке, все перемешать и заправить майонезом, положить в салатницу и присыпать мелко нарезанным зеленым луком, посолить, добавить немного мадеры (по желанию).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3777,'Перед подачей на стол салат с огурцом, капустой и яблоками по-татарски украсить свежей зеленью. Салат получится более вкусным, если дать ему постоять в холодильнике пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3778,'Намазать формочку маслом. Порезать очищенный картофель на тоненькие кружочки, выложить в формочку. Порезать лук на колечки и положить на картофель. Размять рыбу вилкой и выложить сверху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3778,'Заняться тестом: взбить яйца, муку, соду, соль и кефир. Данным тестом залить пирог и отправить на 30 минут в духовку. Готовить пирог «Черепашка» с рыбными консервами, при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3779,'Натереть сельдь укропом, солью, полить маслом, внутрь положить лавровый лист и лук-порей. Завернуть рыбу в фольгу. Помыть картофель и разрезать пополам. Положить в кастрюлю, посолить, помаслить, встряхнуть и выложить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3779,'Готовить 30 минут, соблюдая температуру 210 градусов. Раскрыть рыбку и запекать минут десять. По хребту сельди провести ножом и убрать косточки. Перед подачей к столу выложить сельдь с картофелем на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3780,'Осторожно отделить желтки от белков. Взбить желтки с сахаром, добела. Отдельно взбить белки, добавить сахарный песок  и еще раз взбить до образования плотной воздушной массы. То и другое осторожно смешать. Просеять муку и крахмал вместе, добавить в яично-сахарную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3780,'Быстро замесить тесто. Вылить в смазанную маслом и присыпанную мукой форму для выпечки. Печь 20 минут при температуре 200 градусов.  Для приготовления крема заранее замочить в воде желатин, прогреть до однородности. Смешать молоко с сахаром, добавить ванилин из пакетика, также прогреть и влить набухший желатин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3780,'Взбить сливки, добавить протертый или хорошо размятый творог, влить молочно-желатиновую массу, перемешать.  Выпеченный бисквит пропитать сахарным сиропом, уложить в разъемную форму. Сверху – сливочный крем, поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3780,'На застывший крем выложить свежую клубнику, разрезанную на половинки или четвертинки. Залить красным желе, которое можно приготовить из желатина с клубничным соком. Поставить творожно-сливочный торт со свежей клубникой в холод до полного застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3781,'Белки отделить от желтков, взбить в крепкую пену. Отдельно смешать мягкий творог любого сорта, соль, сахарный песок, ванилин, добавить желтки. Всыпать распаренный изюм, перемешать. Постепенно вмесить муку, просеянную вместе с разрыхлителем. Взбитые белки осторожно ввести в массу, перемешивать снизу вверх, чтобы тесто не потеряло пышность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3781,'Форму для выпечки смазать сливочным маслом, выложить творожное тесто и печь в духовке при 190 градусах. Через 40 минут форму с пирогом вынуть, немного потрясти, чтобы выпечка отстала от стенок и перевернуть на блюдо. При подаче творожный пирог с изюмом посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3782,'Для приготовления теста просеять муку, смешать с солью и сухими дрожжами. Влить теплую воду небольшими порциями, добавить оливковое масло. Дать тесту постоять 30 – 40 минут в теплом месте, защищенном от сквозняков. Емкость накрыть тканью. Для начинки промыть и нарезать свежие грибы ломтиками, можно использовать шампиньоны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3782,'Репчатый лук и помидоры — кольцами, колбасу – ломтиками. Натереть два вида сыра – твердый и полутвердый, смешать. Раскатать поднявшееся тесто в тонкую лепешку круглой формы. Выложить на противень, застеленный пергаментом, на который насыпано немного муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3782,'Косичкой завернуть внутрь края пиццы. Тесто в середине смазать томатной пастой или кетчупом, выложить начинку, посыпать сыром. Печь 20 – 30 минут при температуре 200 градусов. Готовую пиццу с грибами и по-домашнему порезать на порции, посыпать свежей рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3783,'Картофель отварить в слегка подсоленной воде «в мундире», яйца сварить вкрутую, лук замариновать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3783,'Отварной картофель очистить от кожуры и потереть на мелкой терке, яйца также натереть на терке или мелко покрошить, лук нарезать очень мелко, а также мелко порезать соленый огурец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3783,'Приготовить татарский соус, для этого смешать сметану, майонез, тертый на мелкой терке твердый сыр, нарезанный соленый огурец, измельченный чеснок, добавить зелень по собственному вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3783,'Выкладывать салат слоями в салатницу, первый слой – отварной тертый картофель, второй слой – мелко нарезанный маринованный лук, третий слой – тертые отварные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3783,'Сверху залить салат соусом, слегка подлить по краям растительного масла, поставить салат картофельный под соусом по-татарски в холодильник на 2-3 часа, дать настояться, перед подачей на стол украсить свежей зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3784,'Приготовить картофельное пюре. Добавить сырые яйца. Порубить и обжарить на растительном масле репчатый лук, добавить в пюре, всыпать немного пшеничной муки и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3784,'Форму для выпечки смазать растительным маслом и посыпать панировкой. Выложить картофельную массу и запечь. Незадолго до готовности смазать испанскую тортилью яичным желтком и допечь до образования румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3785,'Яйца взбить с помощью венчика, добавить майонез, снова взбить. Разогреть на сковороде небольшое количество растительного масла, вылить немного омлетной массы, выпечь тонкий блинчик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3785,'Печь только с одной стороны в течение 20 – 30 секунд. Скатать блин при помощи деревянной или силиконовой лопатки, сдвинуть рулет на край сковороды. Влить следующую порцию омлета, она должна подтечь под рулет, снова обжарить и свернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3785,'Операцию повторить несколько раз, пока не закончится яичная смесь. Омлет по-японски с вяленой говядиной переложить на блюдо и порезать ломтиками. На гарнир подать нарезанные помидоры, ломтики вяленой говядины, зелень петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3786,'Обжарить креветки на небольшом количестве масла и выложить на тарелку. В той же сковороде обжарить репчатый лук до полупрозрачности, вернуть креветки, положить нарезанные плавники кальмара, крутые яйца, тертый твердый сыр, рубленую зелень петрушки. Соль и перец молотый – по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3786,'Полученной смесью начинить тушки кальмаров, заколоть отверстие зубочисткой. Обвалять в муке, обжарить на растительном масле. В той же сковороде обжарить рубленый лук, влить белое вино, немного выпарить. Очистить от кожицы и семян помидоры, мелко нарезать, добавить в соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3786,'Тушить всё вместе 10 минут, затем массу посолить и поперчить по вкусу, влить воду и тушить еще в течение получаса. За несколько минут до готовности соуса добавить фаршированные кальмары и прогреть. Филе кальмара с креветками в винном соусе подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3787,'Говяжью вырезку нарезать небольшими кубиками. Порубить репчатый лук, морковь и сельдерей, очистить и мелко нарезать чеснок. Очищенные клубни картофеля также нарезать кубиками. Шампиньоны вымыть, обсушить и нарезать четвертинками или половинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3787,'Разогреть в сотейнике растительное масло, обжарить на нём мясо со всех сторон, до образования румяной корочки, в течение 5 минут. Переложить в кастрюлю. В том же сотейнике обжарить нарезанные овощи, огонь уменьшить. Добавить грибы, жарить еще 5 минут и переложить массу к мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3787,'Залить обжаренные мясо и овощи готовым мясным бульоном или водой, добавить рубленый чеснок, перловую крупу, посолить по вкусу. Довести суп до кипения, варить под крышкой до готовности перловки, огонь – умеренный. Через 40 минут всыпать картофель, варить еще 20 минут. При подаче грибной суп с говядиной и перловкой посыпать рубленым укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3788,'Помытые баклажаны разрезать на тонкие пластинки по длине овоща. Толщина пластинок около 4–5 мм. Сковороду поставить на огонь и разогреть на ней 1 ложку растительного масла. Ломтики баклажанов положить на сковородку и обжарить с каждой из сторон по 2 минуты до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3788,'Готовые баклажаны положить на бумажные полотенца, чтобы убрать лишнее масло. Помидоры помыть и вырезать из них семена. Мякоть оставить и порезать на средние бруски или толстую соломку. В чашу от блендера положить зелень, сыр фета и 1 ложку оливкового масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3788,'Включить блендер и перемолоть продукты в пасту.Положить чайную ложечку получившейся пасты на каждый ломтик баклажана, добавить половинку грецкого ореха и выложить кусочек помидора. Завернуть баклажан в рулет. Закусочные рулетики из баклажана и феты готовы!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3789,'Свежую морковь помыть и очистить. Натереть на средней терке. Сыр тоже потереть на терке, но уже на крупной. Смешать морковь и сыр. Добавить в качестве заправки сметану, для вкуса добавить соль и давленый чеснок. Салат из свежей моркови с сыром и сметаной можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3790,'Ломтика хлеба слегка поджарить на разогретой сухой сковороде и просушить таким образом, чтобы они снаружи хрустели, но при этом внутри оставались мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3794,'Картофель разрезать на крупные дольки пока он еще горячий и перемешать с содержимым сковородки. Оставить на 10 минут пропитываться ароматами. В это время приготовить заправку. Лимонный сок и масло перемешать, добавить горчицу, соль и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3790,'Мясо пропустить через мясорубку, обжарить фарш на разогретой сковороде на незначительном количестве масла, также обжарить мелко нарезанный репчатый лук, добавить к фаршу мелко порубленные кильки, нарезанный небольшими кубиками маринованный огурец, обжаренный лук и сырые желтки (можно по желанию добавить сметану – так фарш получится сочнее), поперчить и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3790,'Уложить на поджаренные ломтики хлеба полученную массу, украсить гренки с мясным фаршем и килькой по-татарски свежей зеленью петрушки, при желании поставить их на несколько минут в разогретую духовку, гренки наиболее вкусны в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3791,'Чеснок ножом покрошить на мелкие кусочки. Взять кастрюлю с толстым дном. Смазать маслом и разогреть.  На масле обжарить чеснок в течение 1 минуты, чтобы чесночный аромат стал ярче. Томаты размять, выложить мякоть и сок на сковородку, залить водой. Вскипятить воду и положить макароны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3791,'Огонь слегка убавить и варить 5 минут. За это время порезать кабачки на кубики, а капусту разобрать на соцветия небольшого размера. Положить в кастрюлю кабачок и капусту. Добавить тимьян, и по вкусу соль и перец. Томатный суп с макаронами и овощами варить еще примерно минут 5–7, пока овощи не будут готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Приготовить яйца и воду. Для этого взять два, одинаковых по объему, стакана. В один влить яйца, в другой влить  воду. Лучше если вода будет отфильтрованной. В воде растворить соль и соду. Муку просеять в миску горкой. Сделать в горке муки углубление и влить туда подготовленную воду и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Замесить тесто из продуктов в миске, мешая ложкой по кругу. Если необходимо, то добавить в процессе муку. Потом ложку отложить и месить тесто рукой. Когда тесто перестанет липнуть к ладони, то тесто стало правильным. Такое тесто не собирается при раскатывании скалкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Оставить тесто под полотенцем на столе. Для фарша измельчить на блендере лук (или натереть на терке). Добавить к луку соль и специи. Они растворятся в луковом соке и лучше войдут в фарш. Оставить лук промариноваться минут  на 10 вместе со специями. Фарш можно взять свиной, говяжий или куриный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Перемешиваем фарш с луком. Если лук не сочный, то добавить к фаршу 1–3 ложки воды. На стол положить пленку. На нее выложить кусок теста и сверху прикрыть снова пленкой. Раскатать тесто между двумя слоями пленки тонко, как на пельмени. При таком способе тесто раскатывается легко и тонко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Пласт теста порезать ножом на прямоугольники 7х12 см. По всей длине прямоугольника теста, вдоль длинной стороны, выложить фарш тонким слоем. Слепить края и скрутить пельмень как улитку. Получиться роза. Таким образом слепить ленивые пельмени из всего теста и фарша.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3792,'Вскипятить и подсолить воду. Бросить пельмени в кипяток и сразу помешать деревянной лопаткой, чтобы они не прилипли ко дну. Когда пельмени всплывут, проварить их еще 4 минуты и можно вынимать. Ленивые пельмени «Розочки» с мясом выложить на блюдо и кушать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3793,'Очистить яблоки от середины. Порезать их на мелкие кубики или потереть на терке. Соком, выжатым из лимона побрызгать на яблочные кусочки. Смешать в равных количествах сахар, манку и муку. Намазать сливочное масло на дно формы для выпечки. Присыпать поверх масла муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3793,'На дно высыпать одну треть сухой массы. Положить сверху сухой смеси половину нарезанных яблок. И высыпать сверху вторую треть сухой смеси для теста. Аналогично выложить вторую половину яблок и оставшуюся сухую смесь. Сливочное масло порезать тонкими пластиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3793,'Выложить его сверху пирога. Можно вместо масла залить пирог сливками. Поставить выпекаться пирог в духовку. Время – 30 минут, температура – 180 градусов. Для аромата присыпать пирог корицей.  Яблочный пирог с лимоном и корицей  можно подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3794,'Помыть картофель с помощью щетки, не снимая кожуры. Сварить в слегка подсоленной воде, в мундире. Нарезать кубиками со стороной 1,5 см бекон, колбасу порезать кружочками, а лук порезать на четвертинки колец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3794,'На сухой сковороде вытопить жир у бекона. Затем положить колбасу, жарить 5 минут. Добавить на сковородку лук и жарить пока лук не станет хрустящим (примерно 3–4 минуты). Снять со сковороды луково-копченую смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3794,'Заправить картофель с копченостями. Огурец порезать на тонкие пластинки и добавить в салат. Отставить  салат на 20 минут и подавать на стол, посыпав нарезанной зеленью. Картофельный салат  с беконом, без майонеза готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3795,'Апельсиновый сок охладить. В бокал налить сок, добавить столько же шампанского. Коктейльной ложечкой аккуратно перемешать сок и шампанское.  Игристый коктейль «Мимоза» украсить долькой апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Если необходимо с минимальными затратами сил, времени и продуктов сытно и вкусно накормить домашних, то обратите внимание на рецепт открытого пирога с грибами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'В подогретой воде грибы замочить на 2 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Для приготовления теста перед замешиванием следует просеять муку, чтобы тесто получилось более пышным, на водяной бане распустить маргарин, смешать с кефиром и содой, подсолить, подсыпая порциями муку замесить тесто, затем прикрыть и дать созреть, отставив на 50-60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Порубить грибы, мелко нашинковать лук, перемешать его с грибами, посолить, добавить молотую гвоздику, перец, немного воды (жидкость должна покрыть грибы полностью), еще раз перемешать. Выставить печь на полную мощность, протушить грибной фарш 6 -7 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Раскатать тесто чуть больше диаметра керамической формы, чтобы можно было сформировать бортики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Выложить грибной фарш на тесто и разровнять, посыпать  поверхность пирога измельченным зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3796,'Выставить микроволновую печь  на полную мощность и выпекать пирог на кефире с грибами по-украински в микроволновке 5-6 минут, затем уменьшить до средней мощности и доводить до готовности 3 минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3797,'Взбить яйца с солью и сахаром до пены. Влить стакан молока к яйцам, снова взбить. Всыпать постепенно муку, взбивая блендером. Влить второй стакан молока, перемешать, всыпать второй стакан муки. Снова взбить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3797,'К тесту добавить какао, перемешать и влить растительное масло. Соду погасить уксусом, положить в тесто и еще раз перемешать. Оставить тесто на 5–10 минут.  Включить плиту, разогреть сковородку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3797,'Масла наливать не нужно. Жарить шоколадные «Чоко-панкейки» на сухой сковороде на среднем огне. Перевернуть и обжарить другую сторону, как только на поверхности появятся и лопнут пузырьки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3798,'Макароны отварить до полуготовности. Порезать на кусочки куриную грудку. Посыпать солью и перцем.  Чеснок раздавить, перемешать со специями и обмазать им грудку. Оставить на 20 минут. На горячей сковороде обжарить тертую морковь и нарезанный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3798,'К овощам добавить курицу и обжарить вместе. Влить немного воды, выложить макароны. Все содержимое сковородки перемешать и потушить 2 минуты. Огонь выключить и оставить куриную грудку с овощами и макаронами под крышкой еще на пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3799,'Замесить опару. Молоко налить в миску и всыпать маленькую ложку сахара и дрожжи. Все перемешать и оставить на 10 минут под салфеткой. Муку, сахар и соль смешать в отдельной посуде.  К сухой смеси добавить опару, яйца и молоко. Все перемешать ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3799,'Когда перемешивать ложкой станет тяжело, добавить сливочное масло маленькими кусочками. Месить еще 10 минут. Оставить тесто в чистой миске, под салфеткой. Когда тесто поднимется в 2 раза, (примерно через полтора часа,) достать и выложить на стол. Тесто разделить пополам и раскатать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3799,'Из теста вырезать круги, размером примерно 5 см в диаметре, стаканом или формочкой. Три кружка сложить вместе лесенкой, друг на друга. Свернуть кружки вместе и разрезать пополам. Так получится 2 части кружев. Таким образом сформировать булочки из всего теста. Форму для кексов застелить пергаментной бумагой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3799,'Кружева уложить не очень тесно. Сладким молоком помазать поверхность булочек и оставить подойти, пока они не увеличатся в 2 раза. Кружевные булочки поставить в духовку на 15–20 минут. Температура выпекания – 180 градусов. Готовые кружевные булочки на дрожжах посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3800,'Первым готовится омлет. Обжарить предварительно нарезанные  лук и грибы. Взбить два яйца и перемешать с мелко порезанной зеленю, луком с грибами и мукой. Смешать все ингредиенты и вылить омлет на сковородку. Обжарить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3800,'Отрезать свиной биток и отбить с двух сторон кулинарным молотком или обратной стороной ножа. Посолить и поперчить. На биток выложить омлет и плотно свернуть в аккуратный рулет. Сколоть его зубочистками. Будущую закуску обвалять в муке, потом в яйце, а затем в сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3800,'Обжарить рулет во фритюре в течение 10 минут. Дополнительно можно поставить рулет еще на 15 минут в духовку, завернув в фольгу. С готового рулета снять зубочистки и нарезать его на толстые ломтики. Мясную закуску «Пенечки» с шампиньонами выложить на блюдо, посыпать свежей зеленью и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3801,'Взбить мед, сахар и масло вместе. Вбить в массу яйца по одному, продолжая взбивать. Муку просеять с разрыхлителем и добавить к медовой массе. Замесить пластичное тесто.  Выбрать тарелку для лекала будущих коржей. Разделить тесто на 6 частей и скалкой раскатать каждую в пласт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3801,'Пласты раскатывать такого размера, чтобы они были лишь чуть больше диаметра тарелки.  Коржи выпечь в духовке при 200 градусах. Как только коржи станут золотистого цвета, сразу их доставать. Готовые коржи обрезать по выбранной тарелке и уложить друг на друга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3801,'Для крема взбить сметану с сахаром. Сахар должен полностью раствориться. Обильно пропитать кремом каждый корж.  Измолоть в крошку обрезки от коржей и посыпать ими традиционный торт «Медовик» со сметанным кремом со всех сторон. Торт оставить пропитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3802,'Нарезать крупными кубиками картофель,  морковь – чуть мельче, все обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3802,'Добавить к смеси мелко порезанный лук, поперчить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3802,'На отдельной сковороде, на сильном огне быстро обжарить мясо. Добавить бульон,  пасту и тушить до полуготовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3802,'Послойно, чередуя мясо и овощи, выложить все в сотейник, залить бульоном. Заправить перцем, солью, лавровым листом, тушить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3802,'В тарелке жаркое из говядины по-домашнему по-украински украсить сверху смесью рубленой зелени с чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3803,'Масло согреть до комнатной температуры. Взбить с яйцами. Влить сгущенное молоко и снова взбить.  Всыпать разрыхлитель и взбить еще в течение 30 секунд. Муку просеять и всыпать в тесто. Размешать лопаткой быстрыми движениями по кругу. Одну половину теста отложить и перемешать с какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3803,'В разъемную форму, предварительно смазанную жиром, вылить одну половину теста. Поставить в духовку при 180 гр. пока не станет корж золотистым. Вторую часть аналогично выпечь в духовке. Сметану и сахарную пудру смешать и взбить до растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3803,'Коржи разрезать ножом вдоль и промазать со всех сторон сметанным кремом. Сложить в произвольном порядке и посыпать орешками. Оставить торт «Сметанник» с нежным кремом пропитаться на пару часов в прохладе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3804,'Корки очистить от остатков розовой мякоти и от зеленой кожуры. Оставить надо только белую мякоть. Порезать мякоть на кусочки.  Положить кусочки в кипящую воду и варить 5–7 минут на умеренном огне. Сахар и воду нагреть, вскипятить, снять пену и варить 2 минуты. Кусочки арбузной мякоти высыпать в сироп и добавить туда цедру от лайма.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3804,'Вскипятить и варить на медленном огне 5 минут. Выключить огонь и оставить остывать. Мякоть из сиропа не вынимать. Таким образом нагреть и остудить арбузную мякоть в сиропе 4–5 раз. Затем в сироп выжать сок лайма и снова провести цикл нагревания и остывания 4–5 раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3804,'Цукаты из арбузных корок с лаймом готовы, когда мякоть станет прозрачной. Тогда цукаты выложить на бумагу для выпечки и высушить до твердости. Можно делать это на открытом воздухе или в духовке при 50 градусах с включенным вентилятором.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3805,'Перемешать все ингредиенты. Выложить творожную массу на пласт слоеного теста. Поставить запеканку в духовку на 40 минут. Когда покроется небольшой корочкой, можно вынимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3805,'Плитку черного шоколада растворить с небольшим количеством молока и полить творожную запеканку «Пальчики оближешь» сверху. Оставить до застывания шоколада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3814,'Из охлажденной молочной смеси сделать небольшие шарики. Положить в каждый шарик по одному орешку. Обвалять домашние конфеты «Рафаэлло» с миндалем в стружке кокоса и охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3806,'Филе куриной грудки отбить хорошо кулинарным молотком. Обсыпать со всех сторон специями. Сыр натереть и разделить на 3 части. Натертую морковь разделить на 2 части. Зелень измельчить. На филе выложить начинку: на одно — тертые сыр и морковь, на другое — сыр с зеленью, а на третье  – сыр, морковь и зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3806,'Филе свернуть в рулеты и обернуть пищевой пленкой. Выложить их в кипящую воду, отварить в течение 20–25 минут. Не вынимая приготовленные рулеты  из воды, дать остыть. Куриные рулетики «Ассорти» с сыром вынуть из пленки и разрезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3807,'Помыть яйца и помидоры. Намазать маслом формочки. Разогреть духовку. Заполнить 1/2 каждой формы, половинками помидоров черри, чуть-чуть посыпать солью. Вбить на помидоры 1-2 яйца, в зависимости от размера формочки. Посыпать предварительно натертым сыром. Запекать яичницу под сыром в духовке 15 минут, должен схватиться белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3808,'Насыпать на стол муку горкой, сделать углубление. Вбить в него осторожно яйца, добавить растительное масло и морковный сок, смешанный с солью. Размешать, медленно собирая по краям муку. Соединить фарш и тертый сыр, посыпать перцем, солью, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3808,'На тесто положить немного фарша, сделать пельмень. Варить пельмени 5 минут. Смешать соевый соус со сметаной. При подаче к столу домашние пельмени с мясом и сыром выложить на блюдо, полить сметанным соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3809,'Порезать мелко или натереть предварительно отваренную или маринованную свеклу. Кубиками нарезать помидоры, огурцы и редиску. Измельчить зелень. Переложить продукты в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3809,'Налить кефир, добавить воду до желаемой концентрации. Посыпать перцем и солью.  Подать к столу латышский холодный суп на кефире можно с черным хлебом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3810,'Отварить, охладить, почистить и крупно натереть морковь и яйца. В подсоленной воде отварить мясо. Порезать на кусочки. Измельчить грибы и огурцы. Сыр натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3810,'Выложить салат слоями: грибы, морковь, сыр, огурец, мясо, яйцо.  Все слои смазать майонезом. Потереть сверху желток, украсить мясной салат «Мельник» яйцом, порезанным на колечки и двумя грибочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3811,'Отварить, охладить, почистить и крупно натереть морковь и яйца. В подсоленной воде отварить мясо. Порезать на кусочки. Измельчить грибы и огурцы. Сыр натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3811,'Выложить салат слоями: грибы, морковь, сыр, огурец, мясо, яйцо.  Все слои смазать майонезом. Потереть сверху желток, украсить мясной салат «Мельник» яйцом, порезанным на колечки и двумя грибочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3812,'Бигус галицкий со свининой получается одинаково вкусным и из свежей, и из квашеной капусты, и даже из их смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3812,'В сотейнике припустить капусту (свежую сбрызнуть уксусом) с бульоном под крышкой до полуготовности, готовить на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3812,'Нарезанную свинину смешать со специями и дать чуть постоять. Зажарить на сильном огне мясо до коричневой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3812,'Мелко нашинковать лук, зажарить на отдельной сковородке, добавить пасту и нагревать еще 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3812,'Смешать лук с мясом, добавить лавровый лист, приправы (соль и сахар по вкусу), специи и довести до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3813,'Сварить мясо: положить его в холодную воду, варить 60 минут периодически снимая пенку. Посолить. Готовое мясо порезать на кусочки и положить снова в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3813,'Нарезать и обжарить лук. Положить томатную пасту или тертые помидоры, измельченный чеснок, приправы, аджику, все обжаривать 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3813,'Промыть рис и добавить в кастрюлю. Минут через 20 заправить супчик зажаркой.  Готовить еще 5 минут. Положить в  суп харчо по-грузински, грецкие орешки. Дать супу настояться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3814,'Выложить сгущенное молоко в антипригарную емкость, положить сливочное масло. Варить, пока смесь не загустеет, непрерывно помешивая. Смесь должна стать вязкой, кремового цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3814,'В уваренную сгущенку положить кокосовую стружку, чуть-чуть оставить для украшения, размешать и убрать с огня. Поставить смесь остывать. Обжарить на сухой сковороде миндаль. Выключить огонь, оставив орешки подсыхать на сковороде. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5815,'Очистить яблоки от кожуры и семян, нарезать брусочками, порезать дольки апельсина вдоль на 2-3 кусочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3815,'Почистить картофель и лук. Лук порезать на тоненькие колечки, картофель – на пластинки. Взять сковороду с антипригарным покрытием, чтобы легко можно было перевернуть в дальнейшем тортилью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3815,'Налить оливковое масло и поджарить картофель и лук на среднем огне. В конце посолить. Взбить яйца, разрыхлитель и соль. С помощью шумовки переложить картофель с луком в полученную смесь, перемешать. Слить лишнее масло со сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3815,'Выложить яично-картофельную смесь на разогретую сковороду и готовить 15 минут  – низ должен хорошенько схватиться. Используя тарелку или крышку, перевернуть «Тортилью» по-испански и жарить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3816,'Замочить желатин в холодной воде минут на двадцать. Когда он набухнет, всыпать 1/2 сахара и поставить на огонь, до полного растворения желатина и сахара. Охладить. Приготовить бисквит: взбить сахар и яйца. Просеять муку, насыпать в яичную смесь и размешать. Смазать форму маслом, перелить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3816,'Выпекать 30 минут, соблюдая температуру 180 градусов. Чтобы проверить готовность с помощью зубочистки, она должна остаться сухой. Достать бисквит из формы, остудить. Разделить пополам. Приготовить суфле: взбить белки, сначала на минимальной скорости, затем постепенно ее увеличивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3816,'В белки постепенно всыпать оставшийся сахар, в том числе и ванильный. Размягченное масло взбить со сгущенным молоком. Положить в белки масло и желатин. Размешать все миксером. На одну часть бисквита выложить суфле, другой частью накрыть. Отправить торт «Птичье молоко» с молочным суфле в холодильник на 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3817,'Разделать судака на филе, разрезать на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3817,'Нарезать картофель тонкими кружочками, сложить в миску посыпать смесью соли и перца, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3817,'Слоями, чередуя рыбу с картофелем выложить все в смазанную маслом форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3817,'Прогреть смесь сметаны и растопленного сливочного масла, залить в форму. Сверху присылать рубленой зеленью базилика, накрыть крышкой (фольгой) и отправить в духовку до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3817,'Очень хорош тушеный судак в сметане по-украински с картофельным пюре и свежими помидорами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3818,'Удалить у капустных листьев жесткие прожилки. Листья нашинковать или потереть. Разогреть оливковое масло, положить зубчик чеснока, капусту, накрыть крышкой и жарить минут десять. Осудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3818,'Дрожжи развести в теплой воде, подождать, пока поднимется шапочка. В муку насыпать соль, влить дрожжи и вымешивать тесто минут пятнадцать. В готовое тесто положить капусту и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3818,'Готовое тесто накрыть влажным полотенцем и отправить на 1,5 часа в тепло. Посыпать поверхность стола кукурузной мукой.  Обмять тесто, раскатать его колбаской диаметром 5 сантиметров и нарезать небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3818,'На противень постелить пергаментную бумагу, присыпать мукой. Выложить булочки и отставить на 40 минут. Выпекать пышные капустные булочки в духовке примерно 25 минут, соблюдая температуру 220 градусов',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3819,'Кальмары, обдать кипятком, почистить от пленки и внутренностей, убрать хрящики. Отрезать плавники и нарезать их соломкой. Приготовить начинку: грибы порезать соломкой и обжарить на масле. Почистить и измельчить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3819,'Помыть и натереть морковь. Отварить и порезать соломкой яйца. Крупно натереть сыр. Сложить все в посуду, добавить нарезанные плавники. Размешать. Посыпать перцем, солью. С помощью чайной ложки нафаршировать кальмары.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3819,'Краешки скрепить зубочистками. Смазать сковороду маслом, выложить кальмары. Поставить на 10 минут в духовку. Готовить при температуре 180 градусов. Посыпать кальмары фаршированные грибами тертым сыром и готовить еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3820,'Нарезать перец кольцами, предварительно удалив перегородки и семена. Разогреть на сковороде оливковое масло и обжарить перцы. В каждый перчик вбить по одному яйцу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3820,'Посыпать перцем, солью. Обжарить еще 2 минуты с одной стороны, затем осторожно перевернуть. Посыпать яичницу сыром. Яйца с сыром пармезан в сладком перце можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5815,'Нашинковать мелко лук, порубить яйца, смешать с мясом, яблоками и апельсином, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3821,'Положить на тесто начинку из сырого фарша и предварительно измельченного лука. Вылить остальное тесто. Готовить мясной пирог на кефире в духовке 40 минут, при температуре 170 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3822,'Обжарить кружочки баклажанов (толщиной около 2 см) на растительном масле до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3822,'Лук нашинковать полукольцами и припустить до прозрачности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3822,'Морковь и другие корнеплоды нашинковать и потушить на масле до полуготовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3822,'Все смешать и пропустить через мясорубку, сдобрить специями, сахаром, солью, добавить порубленную зелень и томатную пасту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3822,'Разогреть в сотейнике полученную массу примерно до 70 градусов. Далее разложить икру баклажанную по-запорожски по пол-литровым банкам и стерилизовать. Через 1,5 часа икра готова к зимнему хранению.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3823,'Тертую морковь взбить в блендере с орехами, финиками, корицей, маслом и ванилью. Должна получиться однородная паста. Переложить пасту в смазанную маслом форму и утрамбовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3823,'Взбить сметану и сливочный сыр. Добавить ванилин, цедру, мед и сироп. На морковную основу выложить слой крема и украсить орехами пекан. Отправить чизкейк на морковной основе в холодильник на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3824,'В подогретое молоко положить дрожжи и сахар, размешать, отставить на 15 минут. Размягченное масло смешать с молочно-дрожжевой смесью, посолить, медленно ввести муку и замесить тесто. Сделать шар и поставить в тепло на 30 минут, чтобы тесто подошло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3824,'Приготовить начинку: порезать на тоненькие ломтики ветчину. Мелко натереть сыр. Когда тесто подойдет, вымесить и раскатать пласт, примерно 30 на 40 сантиметров. Намазать тесто томатным соусом. Разложить на него ветчину и небольшие кусочки ананаса, сверху посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3824,'Свернуть тесто рулетом и порезать на двенадцать частей. Положить роллы на противень, смазанный маслом и поставить в тепло на 30 минут. Смазать взбитым с молоком желтком. Готовить 30 минут, соблюдая температуру 180 градусов. Готовую пиццу-ролл с ананасами выложить на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3825,'Достать заранее масло из холодильника. Когда оно подтает, смешать с 1/2 сахарной пудры, насыпать какао, перемешать до однородности. Соединить с остальной пудрой творог, добавить ванилин и взбить. Пропитать печенье молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3825,'На фольгу выложить шоколадную смесь в виде прямоугольника. Затем положить в три ряда пропитанное печенье. Сверху положить и распределить творожную смесь, в середину положить клубнику.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3825,'Осторожно скатать рулет. Чуть-чуть прижать стык и отправить на несколько часов в холодильник. По истечении времени, творожный рулет без выпечки с клубникой можно подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3826,'В тертый сыр сулугуни влить заранее взбитые 3 яйца, кефир, влить чесночный соус, положить зелень и перемешать. Влить кефир, смесь должна получиться жидкой. На противень, смазанный маслом, выложить лаваш так, чтобы с противня свисали его края.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3826,'На лаваш намазать тоненьким слоем сырную массу, посыпать перцем, накрыть другим листом лаваша, снова намазать начинку, положить опять лаваш и так далее. Последний слой начинки нужно накрыть свисающей частью. Смазать взбитым яйцом, поставить на 25 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3826,'Готовить при температуре 180 градусов. Достать лаваш, посыпать тертым твердым сыром и снова поместить в духовку, соблюдая температуру 220 градусов. Готовить до образования золотистой корочки. Армянский лаваш с сыром сулугуни нарезать на порции и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3827,'Галушки с творогом и шкварками по-украински можно назвать классическим блюдом украинской кухни.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3827,'Заварить в кипящей воде 50 г муки, размешать, снять с плиты, дать остыть, добавить остальную муку, яйцо, соль, полученному  тесту дать чуть постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3827,'Брать чайной ложкой смесь и опускать в соленый кипяток, вынимать шумовкой, когда начнут всплывать и выкладывать на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3827,'Нарезать мелкими кубиками сало (удобнее замороженное), вытопить до образования шкварок, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3827,'На тарелку с творогом выложить шкварки, перемешать и сразу подавать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8845,'Наколоть на шпажку маслину, затем ролл с рыбой, затем кусочек хлеба.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3828,'Любые готовые вафли, за исключением лимонных, измельчить в блендере или с помощью мясорубки. Добавить теплое молоко и мягкое сливочное масло. Замесить тесто, скатать его в шар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3828,'Руками отщипывать от теста небольшие кусочки и обмакивать в смесь сока сырой свеклы и лимона. Обвалять в сахаре. Поставить нежные пирожные «Вишенки» в холодильник. Можно украсить блюдо листочками свежей мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3829,'Пропустить через мясорубку куриное филе, плавленые сырки, зелень, чеснок и  зеленый лук. Перемешать. Добавить сырое яйцо, сметану или майонез, соль и перец – по вкусу. Сформовать маленькие котлеты «Малышки», обвалять в панировочных сухарях и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3830,'Залить желатин из пакетика водой и оставить на 15 минут для набухания. Приготовить сироп из полутора стаканов сахарного песка, кукурузного сиропа, соли и полстакана воды. Варить на среднем огне в небольшой кастрюле, до растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3830,'Добавить огонь и довести массу до температуры 240 градусов. Снять с огня.Влить сахарный сироп в растворенный желатин тонкой струйкой, взбить до вязкости, в течение 15 минут, с помощью миксера. Добавить ванилин и еще немного взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3830,'Форму для выпечки накрыть фольгой и посыпать сахарной пудрой, выложить массу. Разровнять, присыпать пудрой, оставить на ночь при комнатной температуре. Застывшую массу перевернуть на посыпанную сахарной пудрой поверхность, вырезать квадратики или любые другие фигурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3830,'Приготовить какао: довести молоко до кипения, добавить какао, сахар, ваниль. Заварить. На дно чашки положить кусочки темного шоколада, залить полученной смесью. Украсить какао взбитыми сливками и маршмеллоу. Какао с взбитыми сливками и зефиром «Маршмеллоу» подавать в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3831,'Тушку сельди без головы и хвоста (сохранить их для оформления) разделать на филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3831,'Перекрутить в мясорубке с мелкой решеткой сельдь с предварительно замоченным в молоке и отжатом хлебом. Полученную смесь протереть сквозь сито или взбить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3831,'Далее добавить тертый сыр, размягченное сливочное масло, перец, мускатный орех, горчицу, вымесить до однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3831,'Выложить все на плоское блюдо, придать сельди с хлебом и сыром по-киевски форму рыбы, приставить хвост и голову, украсить зеленью петрушки перед подачей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Взбить яйца с сахарным песком до образования пышной массы. Вмесить порциями просеянную пшеничную муку, соль по вкусу, ванильный сахар. Можно добавить щепотку соды. Форму для выпечки смазать маслом, переложить в нее полученное бисквитное тесто, печь при температуре 200 градусов в течение 15 – 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Готовность выпечки проверить зубочисткой, остудить в форме. Для приготовления суфле понадобятся охлажденные сливки и йогурт. Сливки взбить с сахарным песком в густую пену, добавить густой йогурт, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Желатин замочить в небольшом количестве воды на 15 минут. Добавить в него сок лимона, немного прогреть. Влить в суфле, перемешать. Готовую смесь поставить в холодильник. Слить из банки с консервированными персиками сироп. Часть жидкости понадобится для пропитки, часть – для приготовления желе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Добавить в первую часть сахарный песок, прогреть, влить лимонный сок, бренди или коньяк, остудить. Для приготовления желе добавить в сироп апельсиновый сок, нагреть, всыпать сахар. Желатин залить небольшим количеством холодной воды, добавить лимонный сок, влить в сироп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Массу перемешать, при необходимости добавить еще немного апельсинового сока и сахар. В форму со съемными бортиками выложить готовый корж. Пропитать остывшим сиропом, выложить суфле. Поставить в холодильник, верхний слой должен немного застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'Нарезать дольками персики из банки, выложить на поверхность торта в любом порядке, залить половиной желе, снова убрать в холодильник. Торт вынуть и залить оставшейся половиной желе и вернуть десерт в холодильник до полного застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3832,'При подаче достать торт, отделить ножом суфле и желе от края формы. Нарезать теплым ножом, обмакнув его в горячую воду. Украсить бисквитный торт с персиковым суфле клубникой и листочками свежей мяты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3833,'Для приготовления бисквита одно яйцо и один дополнительный желток взбить с сахарным песком до пышной пены и увеличения объема массы в два-три раза. Всыпать просеянную муку и какао, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3833,'Отдельно взбить оставшийся белок со щепоткой соли, массу ввести в тесто. Небольшой противень застелить бумагой для выпекания. Вылить тесто, печь 10 – 12 минут при температуре 210 градусов, до готовности. Бисквит охладить, разрезать на два коржа острым ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3833,'Для крема, взбить сыр маскарпоне со сгущенным молоком до образования однородной массы, добавить сухое молоко, перемешать. Прослоить кремом коржи, прижать и разрезать киндер «Молочный ломтик» по-домашнему на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3834,'Соединить яйца, соль, сахарный песок, водку и муку. Замесить крутое тесто, оставить на полчаса под влажной тканью. Тесто тонко раскатать и нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3834,'В центре каждой полоски сделать надрез, вывернуть тесто наизнанку. Жарить во фритюре из растительного масла. Готовый хворост на водке посыпать сахарной пудрой и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3835,'Мясной фарш смешать с рубленой зеленью, специями и сырым яйцом. Половину фарша выложить на готовое размороженное слоеное тесто. Сверху – половинки яиц, сваренных вкрутую, вторая часть фарша. Свернуть рулетом, смазать поверхность сырым, чуть взбитым, яйцом и посыпать семечками кунжута.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3835,'Готовить при температуре 200 – 220 градусов в течение 40 – 45 минут. При подаче нарезать мясной рулет с яйцом кусочками, выложить на листья зеленого салата и украсить дольками обычных помидоров или половинками черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3836,'Печенье измельчить в блендере. Растопить сливочное масло на водяной бане, перемешать с крошкой. Для приготовления понадобится разъемная форма, ее нужно застелить пергаментом. Всыпать массу, утрамбовать и поставить на 15 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3836,'Желатин из пакетика залить небольшим количеством воды комнатной температуры на 15 минут, затем прогреть на водяной бане до полного растворения, до кипения не доводить. Смешать сметану с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3836,'Отдельно смешать сахар, какао и молоко, прогреть на тихом огне в течение 2 – 3 минут. Массу немного остудить и смешать со сметаной. Влить желатин и перемешать. Бананы разрезать вдоль, и каждую половину еще на четыре части поперек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3836,'Выложить кусочки на застывший корж. Сверху выложить  крем.  Поставить десерт в холодильник на 5 часов. Готовый торт с бананово-шоколадным суфле вынуть из формы, удалить бумагу и украсить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3837,'Положить тщательно вымытое пшено в подсоленный кипяток и варить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3837,'Порезать небольшими кубиками картофель и добавить в кастрюлю, варить 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3837,'Нарезать мелко лук и сало, жарить пока лук не приобретет золотистый цвет. Добавить зажарку к пшену, дать закипеть, проварить 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3837,'Кулеш с салом и картофелем по-украински посыпать в тарелке измельченной петрушкой и базиликом, можно добавить ложечку сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Свиное мясо порезать кусочками, накрыть пищевой пленкой и отбить. Снять пленку, поперчить, посолить и еще немного отбить. Сложить мясо в посуду, посыпать специями, добавить тонко нарезанную луковицу, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Оставить на 2 – 3 часа для маринования. Нарезать еще одну головку репчатого лука полукольцами, залить кипятком, влить уксус, всыпать сахар и соль по вкусу, можно добавить лимонный сок. Оставить массу на час для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Противень застелить бумагой для запекания. Рукав для запекания завязать с одной стороны, выложить в него маринованный лук ровным слоем, на получившуюся подушку положить мясо. Второй конец рукава завязать, сделать в оболочке несколько проколов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Печь в духовке 1 – 1,5 часа, до готовности. Выложить на блюдо, лук использовать для гарнира. Для приготовления картошки очистить и нарезать клубни средними дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Крупно порезать лук, морковь – кусочками, специи, соль, перец – по вкусу. Добавить растительное масло, томат-пасту. Перемешать, выложить в рукав для запекания, края завязать, сделать проколы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5828,'Потушить на масле нарезанную соломкой свеклу 5-7 минут, влить уксус, добавить томатную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3838,'Запекать 1 – 1,5 часа при максимальной температуре. Можно это делать одновременно с мясом: температура и время выпечки – одинаковое. При подаче, свиной шашлык с картофелем посыпать свежей рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3839,'Мелко нарезать зеленый перец и обжарить на сливочном масле в течение нескольких минут. Добавить нарезанную ветчину, еще немного обжарить, затем всыпать рубленую зелень петрушки и взбитые яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3839,'Прогревать, помешивая, до готовности. На каждую тортилью или лаваш выложить готовый омлет, посыпать тертым сыром и завернуть рулетом. «Буррито» по-мексикански с сыром и ветчиной подать горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3840,'Просеять муку, добавить сахарный песок, дрожжи, перемешать. Влить подогретое молоко, сырое яйцо, добавить нарезанное кусочками мягкое сливочное масло и соль. Вымесить тесто в течение 20 минут, оставить на час в тепле. Масса должна увеличиться в объеме в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3840,'Для приготовления крема растереть сырые желтки с крахмалом, добавить немного молока, масса должна быть жидкой. Вскипятить оставшееся молоко, влить в него тонкой струйкой яичную смесь, помешивать венчиком. Довести до густоты, прогревая в течение 2 – 3 минут. Крем закрыть пищевой пленкой и дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3840,'Выложить подошедшее тесто на присыпанную мукой поверхность. Раскатать в большой прямоугольный пласт, смазать кремом и посыпать кусочками шоколада или готовыми капельками для выпекания. Скатать в рулет, нарезать кусками. Форму выложить бумагой для выпекания или смазать растопленным сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3840,'Выложить булочки, оставляя между ними зазоры. Оставить на полчаса. Выпечь при температуре 160 градусов в течение 40 – 45 минут. Остудить на решетке. Остывшие бриоши с заварным кремом «Патисьер» можно посыпать семенами кунжута или украсить глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3841,'Соединить крахмал, соль и сахар. Медленно влить молоко. Подогреть смесь на водяной бане, помешивать время от времени. Поломать шоколад на куски и бросить в смесь, когда она загустеет (минут через 20).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3841,'Непрерывно мешать, пока пудинг не будет густым и однородным, приблизительно через 5 минут. Убрать с огня, насыпать ванилин. Процедить бархатный пудинг и разлить по порционным креманкам. Накрыть пленкой и отправить на час  в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3842,'Помыть филе белой рыбы, просушить с помощью бумажного полотенца. Сделать начинку: порезать на небольшие кубики форель, маринованный перец, креветки, лук, цуккини. Посыпать перцем, солью, приправить вустерским соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3842,'На все кусочки белой рыбы разложить начинку, свернуть рулетики. Закрепить деревянными шпажками или специальными кольцами. Переложить их в огнеупорную формочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3842,'В посуде соединить сок лимона, масло с тимьяном, тандури масала. С помощью кисточки смазать полученной смесью рулеты, добавить в форму розмарин. Накрыть фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3842,'Отправить в духовку на 30 минут и готовить, соблюдая температуру 200 градусов. Снять фольгу с рулетов из белой рыбы с форелью и креветками и готовить до румяного цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3843,'В кастрюлю с тремя литрами воды положить мясо, дать закипеть и варить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3843,'Нарезать стручки фасоли на кусочки, морковь и свеклу – соломкой, положить все в кастрюлю, дать закипеть и варить 10  минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3843,'После этого засыпать тонко нашинкованную капусту и нарезанный кубиками картофель, проварить 7-10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3843,'За пару минут до окончания варки добавить порезанный кубиками лук, заправить томатной пастой и толченым чесноком с салом, посолить, поперчить, добавить лавровый лист и дать закипеть, засыпать рубленую зелень, снять с огня и под крышкой дать настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3843,'На стол борщ  со свининой по-житомирски подавать со сметаной, чесноком и посыпанный зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3844,'Все продукты соединить и вылить в форму. Приготовить начинку: в сухой посуде смешать сахар, стружку кокоса, ванильный сахар. Распределить готовую начинку по поверхности теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3844,'Отправить форму с пирогом в духовку на 30 минут, соблюдая температуру 190 градусов.  Полить готовый ванильно-кокосовый пирог сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6142,'Нарезать кольцами репчатый лук. Добавить уксус, сахарный песок, подлить воду, оставить мариноваться на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3845,'Порезать грудки на маленькие кубики. Положить мясо в большую посуду. Смешать манную крупу, яйца, сметану, соль,  нарезанный болгарский перец. Добавить к мясу и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3845,'Отправить заготовку в холодильник на 2 часа, чтобы мясо пропиталось и стало нежным, но можно жарить и сразу. Ленивые отбивные из курицы можно класть на булочку и кушать на завтрак.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3846,'Разогреть духовку. Выложить 1/2 грецких орехов на противень и отправить в духовку. Обжаривать 8 минут. Немного остудить, положить на доску и измельчить. Выставить температуру 160 градусов, противень застелить специальной бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3846,'В большой посуде смешать какао, сахарную пудру, соль и измельченные орехи. Добавить в смесь ванилин, белки и с помощью миксера взбить. Чтобы печенье не стало жестким, взбивать долго не надо. Выложить на противень двенадцать небольших порций на расстоянии друг от друга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3846,'Готовить 15 минут. Повернуть противень другой стороной, чтобы шоколадное печенье с грецким орехом выпекалось равномерно, и готовить еще 15 минут. При готовности верхушки печенья должны начать трескаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3847,'Картофель очистить и сварить, размять с молоком, маслом и яйцами, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3847,'На слабом огне потушить квашеную капусту 25-30 минут. За 5-7 минут добавить лавровый лист и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3847,'Поджарить на растопленном со шкварками сале мелко порезанный лук, смешать с готовой капустой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3847,'Смазать противень маслом, выложить слой пюре, потом капусту и накрыть еще слоем картошки, смазать сверху растопленным салом и отправить в духовку, запекать до румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3847,'Перед подачей лежни картофельные с капустой по-полтавски разрезать на порционные куски и полить сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3848,'Нашинковать очень мелко капусту, приправить солью и помять руками, чтобы пустила сок. Крупно потереть лук, влить кефир, вбить яйцо, измельченную зелень, можно положить чеснок. Насыпать разрыхлитель, муку и размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3848,'Тесто должно быть, как сметана, при необходимости досыпать муку. Разогреть на сковороде чуть-чуть растительного масла и готовить оладьи до золотистого оттенка. Готовые капустные оладьи на кефире выкладывать на бумажное полотенце. Подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3849,'Смешать молоко, сахар, какао и растительное масло с помощью миксера. Полученную смесь разделить на две части. В одну из частей добавить яйца, муку, ванильный сахар, разрыхлитель и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3849,'Смазать форму маслом, влить мучную смесь и готовить 25 минут, соблюдая температуру 180 градусов. Чтобы убедиться в готовности, используйте зубочистку, если сухая – пирожное готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3849,'На горячий пирог вылить другую часть смеси и оставить на ночь. Готовый классический брауни порционно нарезать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3850,'Разогреть духовку. Вбить в творог яйца, взбить при помощи миксера. Насыпать муку и соду. Замесить густое тесто. Смазать формочки, дно застелить смазанной маслом бумагой. Выложить тесто и готовить в духовке до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3850,' Если оно чуть-чуть опадет –  не страшно, вкус от этого не меняется. Обмазать приморские творожники сметаной, положить в кастрюлю и накрыть крышкой. Оставить на время для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3851,'Крупно натереть картофель, положить все ингредиенты, кроме масла. Сильно разогреть духовку. Смазать формочки для маффинов маслом. Брать смесь из картофеля руками, отжимать сок и тоненько распределять в формочках в виде гнезда, то есть, по стенкам и дну. Сбрызнуть оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3851,'Отправить в духовку на 25 минут. Сделать начинку: потереть яблоко, мелко порезать крабовое мясо, размешать и положить остальные ингредиенты, кроме гранатовых зерен. Ими украсить готовые картофельные гнезда с крабом и яблоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3852,'Растереть подтаявший маргарин с сахаром и желтками, чтобы сахар растворился. Насыпать соль, муку и замесить тесто. Отрезать 1/3 часть и отложить в сторону. Большую часть теста раскатать и переложить на противень, застеленный бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3859,'Взять свиные ребрышки, разрезать, хорошо вымыть. Лук нарезать кольцами. Замариновать ребрышки в соевом соусе, перце, луке и любимых специях. Отставить на 2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3852,'Руками выровнять и сформировать бортики. Растереть творог и сахар, положить ванилин и предварительно размоченный изюм. Взбить белки и добавить к творогу. Размешать. Выложить равномерно на тесто. Раскатать оставшуюся часть теста и порезать на полоски по 1 сантиметру в ширину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3852,'Разложить полоски на начинку, как решетку. Намазать сметаной при помощи кисточки. Готовить 50 минут, соблюдая температуру 200 градусов. Готовый песочный пирог с изюмом  творогом чуть-чуть остудить, порезать на кусочки и подать к чаю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3853,'Протереть творог через сито, вбить одно яйцо, всыпать сахар. Перемешать. Залить изюм теплой водой и отставить на 30 минут. По истечении времени слить воду, просушить изюм бумажным полотенцем. В творожную массу добавить ванилин и изюм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3853,'Разделить тесто пополам, раскатать тоненькие прямоугольные пласты. Отступив чуть-чуть от краев, положить начинку на оба пласта. Каждый свернуть плотным рулетом. Защипнуть краешки, положить швом вниз. Порезать рулеты кусочками по 4 сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3853,'Смазать форму сливочным маслом, постелить специальную бумагу  и выложить кусочки. Слегка взбить яйцо, намазать рулеты, посыпать корицей и сахаром. Готовить слоенки с творогом и изюмом в духовке примерно 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3854,'Смешать натертый на терке сырой картофель (предварительно отжать сок) с мукой, содой, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3854,'Брать столовой ложкой, выкладывать на сковороду в сильно разогретое масло, обжаривать деруны с двух сторон до золотисто коричневатого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3854,'Приготовить из заранее замоченных грибов соус, для этого отварить грибы (воду не выливать), порезать и  смешать с поджаренным луком, добавить гвоздику, посолить и прожарить смесь на сковороде 1-2 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3854,'Обжарить до кремового цвета муку, добавить сливочное масло, 2 стакана грибного отвара, проварить 10 минут. Вылить в смесь грибов с луком и  прокипятить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3854,'Деруны с грибной подливой по-украински подавать к столу обязательно горячими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3855,'Взять форму диаметром 20 сантиметров, постелить пергамент. Чтобы не вытекало масло, поставить форму на противень. Взбить масло, соль и сахар. Вбивать в смесь по одному яйцу, продолжая взбивать. Крупно натереть сыр, положить в смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3855,'Налить молоко. Просеять и соединить сухие ингредиенты, добавить ванилин. Выложить получившуюся пышную смесь в форму. Готовить 50 минут, соблюдая температуру 160 градусов. Положить сырный кекс с лимоном и ванилью на решетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3856,'Сделать трафарет в виде птицы, приложить его к тарелке, на которой будет выложен салат, и обвести простым карандашом. Сначала положить слой размятой или измельченной рыбы с нарезанным луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3856,'Затем, нарезанные корнишоны. Следующий слой – тертые яйца,  последним слоем выложить тертый сыр.  Каждый слой посолить и промазать майонезом. Положить маслины, порезанные пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3856,'Измельчить перец и сделать снегирю грудку, а мелко потертым белком посыпать остальную часть салата. Веточку сделать из зелени. Убрать на некоторое время салат «Снегирь» с красной рыбой в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3857,'Обжарить грецкие орехи на горячей, сухой сковороде и измельчить их. Нарезать пряники пластинками, приблизительно по 4 миллиметра. С бананов удалить кожуру, нарезать на тоненькие кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3857,'Соединить сметану, сахарную пудру и взбить до однородности. Застелить глубокую емкость пленкой. Положить в нее слой пряников, смоченных в сметанном креме и слой бананов. Все слои посыпать измельченными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3857,'Накрыть пленкой, осторожно утрамбовать руками и отправить в холодильник  на 10 часов. Переложить охлажденный торт на плоскую тарелку и снять пленку. Украсить банановый торт из пряников кремом и орехами и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3858,'Отваривать филе курицы в течение 20 минут. Измельчить лук. Приготовить яичные блины: каждое яйцо отдельно посыпать перцем, солью, взбить. По одному вылить яйца на горячую сковороду, смазанную маслом и обжарить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3858,'Блины сложить друг на друга и разрезать на четыре части. Порезать соломкой. Остудить и измельчить курицу. Соединить мясо, блинчики, лук (по желанию) и посолить. Заправить салат из курицы с яичными блинами майонезом. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3859,'Накрыть фольгой и отправить в духовку. Готовить приблизительно полтора часа. За 20 минут до готовности  убрать фольгу. Сочные свиные ребрышки в соевом соусе выложить на блюдо и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3860,'Отделить яичные желтки от белков. Взбить желтки и 6 ст.л. сахара до однородности. Положить предварительно натертую цедру апельсина, всыпать разрыхлитель и муку. Перемешать. Можно добавить немного молока. Взбить белки и осторожно вмешать в основную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3860,'Перелить тесто в форму для пирога, смазанную маслом и застеленную бумагой. Готовить 40 минут, соблюдая температуру 160 градусов. Охладить корж, разрезать пополам, вдоль. Коржи пропитать соком апельсина. Мелко порезать половину клубники. Взбить сливки с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3860,'Смазать коржи кремом, положить ягоды и снова смазать кремом. Уложить один корж на другой. Остальным кремом промазать поверхность торта. Украсить апельсиновый торт с клубникой и сливками, оставшимися ягодами и отправить на 3 часа в холодильник. Перед подачей посыпать измельченными орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Довести до кипения предварительно замоченную фасоль и проварить 5 минут. Сменить воду и снова поставить варить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Добавить к фасоли порезанное на кусочки мясо, дать закипеть, уменьшить огонь, варить до полуготовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Добавить в суп, порезанный средними кубиками картофель, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Поджарить до мягкости нашинкованный мелко лук и нарезанную соломкой морковь, положить их в суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Заправить суп из свинины с фасолью и картофелем по-украински толченым чесноком, измельченной зеленью, лавровым листом, поперчить, дать чуть настояться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3861,'Разлить суп по тарелкам и посыпать нашинкованным базиликом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3862,'В просеянную через сито муку добавить соль, влить воду. Замесить гладкое тесто, скатать в колобок, накрыть тканью и оставить на 10 – 15 минут. Сделать из теста шарики среднего размера, по 130 – 140 г каждый. Снова накрыть полотенцем, дать постоять 10 минут для набухания клейковины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3862,'Для приготовления начинки очистить клубни картофеля, нарезать мелкими кубиками, добавить рубленый репчатый лук, зелень, соль, специи – по вкусу. Шарики тонко раскатать, в центр положить картофельную смесь, завернуть края к центру, полностью закрыв начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3862,'Тесто можно немного смочить водой или сырым яйцом, чтобы оно лучше склеилось. Лепешки жарить на разогретой с растительным маслом сковороде, на тихом огне, шов должен быть внизу. Готовить в течение 5 – 7 минут с каждой стороны под крышкой, печь до золотистого цвета.  Подать плацинды с брынзой и картофелем в теплом виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3863,'Отделить яичные белки от желтков. Взбить сырые желтки с сахарной пудрой, влить воду и растительное масло. Взбить до гладкого, однородного состояния, всыпать, просеянную вместе с разрыхлителем, муку.  Отдельно взбить в густую, устойчивую пену, белки, ввести в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3863,'Для начинки: Любой мягкий творог растереть с желтковой массой. Всыпать ванилин, кукурузный крахмал, цедру лимона.  Форму для выпечки смазать растительным маслом, вылить приготовленное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3863,'Творожную начинку выдавить на корж сверху с помощью насадки для крема, в виде решетки. Печь бисквитные «Подушечки» с творогом, при температуре 180 градусов в течение 35 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3864,'Отделить яичные белки от желтков. Взбить белки в густую, плотную, пену, добавить часть сахарного песка. Отдельно взбить растаявшее сливочное масло до состояния крема, также добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3864,'Желтки взбивать до тех пор, пока масса не посветлеет, затем добавить коньяк и цедру лимона. Соединить масляную и желтковую смеси, постепенно добавить просеянную муку, подмешать белки, делать это осторожно, движениями снизу вверх, чтобы масса не опала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3864,'Готовое тесто разложить в формочки для кексов, в центр добавить густой джем, его можно оставить открытым или залить тестом. Печь лимонные кексы «Пальчики оближешь»  в духовке, при температуре 180 градусов в течение 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3865,'Куриные сердечки вымыть, обсушить. На сковороде с толстым дном разогреть растительное масло, обжарить субпродукты. Присыпать мукой, залить сливками или сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3865,'Тушить блюдо под крышкой в течение 30 – 40 минут. Вымыть зелень укропа, петрушки, кинзы, луковое перо, порубить вместе с очищенным чесноком. Массу можно измельчить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3865,'Тонко нарезать колечками перец чили, семена удалить. Сердечки посолить и поперчить, добавить чили, чеснок, зелень, тушить в течение 5 – 10 минут. Куриные сердечки с перцем чили подать с гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3866,'Клубни очистить и нарезать тонкими кружочками, репчатый лук и помидоры – полукольцами, рыбу – кусочками. В жирные сливки всыпать специи, соль, перец и перемешать. Выложить картофель в форму для запекания, затем лук, помидоры и рыбу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3866,'Можно немного посолить по вкусу, залить сливочной смесью. Посыпать тертым твердым сыром. Печь при температуре 200 градусов в течение 25 – 30 минут. При подаче, картофель с белой рыбой под сливками посыпать рубленой зеленью укропа, петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3867,'Порционные куски мяса на кости отбить слегка с двух сторон, натереть солью и смесью крупномолотых перцев, дать чуть постоять и обжарить в сильно разогретом масле с обеих сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3867,'Из молока, яичного желтка, муки, сахара и соли сделать кляр, взбить белок в густую пену и в несколько приемов аккуратно перемешивая ввести в кляр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3867,'Обмакнуть котлеты в кляр и зарумянить с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3867,'Горячие мясные котлеты на кости в тесте по-херсонски выложить на тарелку с жареным картофелем, украсить дольками помидора и веточками петрушки. Отдельно подать хрен и горчицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3868,'Растопить на водяной бане кусочки темного шоколада со сливочным маслом. Масса должна получиться однородной, шелковой. Немного остудить. Взбить в пену два сырых яйца, дополнительные желтки и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3868,'Соединить обе смеси, добавить соль и просеянную пшеничную муку, перемешать. Формы для выпечки смазать растопленным сливочным маслом, разлить тесто. Выпекать в духовке в течение 7 – 10 минут. Середина американских кексов должна остаться жидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3869,'Яйца отварить, отложить 2 желтка. На блюдо выложить слой соленых крекеров. Затем слой яиц, натертых на терке и смешанных с майонезом. Снова крекеры, размятая консервированная рыба (тунец, горбуша, сайра), её также нужно смешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3869,'Следующие слои: мелкорубленый зеленый лук, крекеры, тертый сыр с рубленым чесноком и майонезом, крекеры. Верх смазать майонезом и посыпать тертыми, сваренными вкрутую желтками. Оставить слоеный салат из крекеров  для пропитывания на 2 часа при комнатной температуре или на 1 час в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3870,'Отварить пасту так, как указано на упаковке. Воду слить, макароны смешать со сливочным маслом. В сковороде с оливковым маслом обжарить морепродукты по очереди: креветки, белую рыбу и кальмары, нарезанные кусочками. В оставшееся от обжарки масло влить рыбный бульон и сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3870,'Затем всыпать тертый сыр пармезан, морскую соль по вкусу. Прогревать соус пока не загустеет. Выложить в готовый сливочный соус пасту, зелень петрушки и морепродукты. Пасту «Феттучини Альфредо» со сливочным соусом перемешать и подать, обильно посыпав тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3871,'Смешать в отдельной емкости половину чайной ложки сахара и дрожжи. Затем добавить 2 или 3 чайные ложки воды и накрыть (можно блюдцем), чтобы дрожжи активизировались. Отдельно немного взбить яйцо, прибавить кефир, соль и сахар, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3871,'Просеять муку, тщательно перемешать. Тесто на данном этапе должно выйти очень густым, иначе оладьи не будут очень пышными. Натереть банан на терке, взбрызнуть лимонным соком, чтобы он не потемнел (тогда и тесто останется светлым).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3871,'Добавить в тесто дрожжи и банан, тщательно вымесить. Тесто получается, как очень-очень густая сметана, должно плохо сползать с ложки. Накрыть тесто полотенцем и отставить, чтобы подошло. Когда тесто подойдет, то полотенце зашевелится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3871,'Пройдет около получаса и тесто увеличится раза в 2 или 2,5. Можно начинать печь оладьи, тесто не перемешивать. На сковородку налить столовую ложку масла, выкладывать ложкой оригинальные банановые оладьи и жарить сначала на среднем огне, а затем его немного уменьшить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6543,'В холодной воде замочить фасоль на 12 часов, отварить в ней же до готовности, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3872,'Достать готовый рулет, порезать на порционные куски, переложит на сковороду. Обложить мясо со всех сторон яблоками, залить соусом из муки и сметаны, посыпать сыром и отправить до зарумянивания в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3872,'Запеченное с яблоками и сыром филе индейки – отличное горячее блюдо для любого праздничного стола.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3873,'Сварить кофе (крепкий), охладить. Положить в чашу блендера: сиропы, кофе, молоко, корицу, коньяк – взбивать до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3873,'Прибавить лед (колотый), взбивать 1 минуту. Разлить в бокалы, украсить кофе Фраппе с коньяком, взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3874,'Взбить вилкой яйца, молоко, соль и перец. Взять небольшую сковородку, разогреть с растительным маслом, налить яичную массу, распределить равномерно по всей сковородке (наклонять ее из стороны в сторону, как для блинчиков).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3874,'Жарить на небольшом огне. После того, как масса схватится, выложить кусочки ветчины и сыра, завернуть оба бока омлета внутрь. Прожарить его еще 1 минуту. Омлет в баварском стиле с сыром выложить на тарелку и посыпать нарезанным луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3875,'Муку просеять, добавить яйцо, затем воду. Замесить тесто и отставить на полчаса для расслаивания (обязательно). Сделать фарш: мясо, соль, перец и лук перемешать. Взять тесто, раскатать его очень тонко (1 миллиметр).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3875,'Фарш уложить сверху, скатать рулетом. Обязательно защипать длинный край. Острым ножом порезать на столбики – это и есть ленивые пельмени. Готовить их можно хоть в воде, хоть на пару или в микроволновке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3875,'А можно так: уложить пельмени в глубокую сковородку на подушку из чеснока и жареной моркови (можно с луком), залить все разбавленной с водой сметаной, добавить приправу (например, хмели-сунели).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3875,'На каждый пельмень положить маленький кусочек сливочного масла. Накрыть крышкой и тушить ленивые домашние пельмени на слабом огне, пока жидкость практически полностью не впитается. Выложить на тарелку, присыпать зеленью и подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3876,'Измельчить свинину в мясорубке с мелкой решеткой (лучше 2 раза).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3876,'Нарезать мелкими кубиками сало, смешать с фаршем, добавить молоко (либо воду), специи и хорошо все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3876,'Сделать из массы колбаски, смочить в яйце, обвалять в сухарях, жарить на маргарине до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3876,'Подавать колбаски «Львовские» по-домашнему можно с любым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3877,'Куриное филе отварить (для аромата можно добавить морковь, лавровый лист, лук). Нашинковать пекинскую капусту. Измельчить зеленый лук. Огурец порезать соломкой или натереть. Филе порезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3877,'Отварные яйца измельчить. Выложить все ингредиенты в салатник, приправить салат из пекинской капусты и курицы майонезом, добавить перец и соль. Подавать порционно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Крем, который больше всего подходит для данного торта – заварной или масляно-заварной. Лучше приготовить масляно-заварной крем. Взбить яйца с сахаром (можно сразу добавить и соль). Особой пышности не требуется, поэтому можно взбивать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Крем лучше готовить на водяной бане (немного дольше, но зато точно не пригорит). Для этого необходимо поставить кастрюлю на огонь с водой. В сотейник налить молоко и поставить на небольшой огонь. Продолжать взбивать яйца, понемногу всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'После того, как молоко начнет закипать, снять его с огня и тонкой струйкой влить в яичную смесь, постоянно мешая. Получится жидкая масса, которая еще не является кремом. Перелить все обратно в сотейник и поставить на водяную баню. Продолжать взбивать венчиком, но не очень сильно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Когда масса будет густеть, интенсивность взбивания можно увеличить, чтобы не образовались комочки. Если станет настолько густым, что венчик уже не будет справляться, его необходимо заменить лопаткой и продолжать мешать. Крем получается очень густым. В конце приготовления добавить ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Необходимо полностью остудить крем, но обязательно под крышкой (чтоб не появилась корочка). Пока остывает, его нужно периодически помешивать. Взбить сливочное масло, далее к нему постепенно добавлять крем и все взбивать до однородной массы. Накрыть крем крышкой и отставить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Теперь можно приступать к приготовлению коржей. Чтобы тесто получилось однородной консистенции, творог лучше перед использованием перетереть через сито, а можно использовать блендер, только добавить яйцо и сахар. Но можно оставить и так, если кусочки творога в тесте не будут смущать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'К творогу добавить соду (погасить уксусом), и сахар ванильный, перемешать. Добавлять постепенно муку (на количество муки повлияет размер яйца, жирность творога, ее может понадобиться больше или меньше того количества, которое указано в рецепте). Тесто должно выйти пластичное и средней густоты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Разделить тесто на 6 или 8 частей (зависит от диаметра сковородки, на которой будут коржи выпекаться). Посыпать стол мукой и раскатать часть в круг, для того, чтобы коржи были идеальной формы, можно воспользоваться тарелкой, подходящей по диаметру к сковородке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Разогреть сковородку, положить в нее корж и обколоть его вилкой, чтобы не образовывались пустоты. Выпекать на сухой сковороде на слабом огне с обеих сторон, пока корж не станет румяным. Так сделать с каждой частью теста. Готовые коржи оставить остывать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Когда коржи остынут, можно начинать собирать торт. Взять плоскую тарелку, положить на нее корж, смазать кремом, то же самое сделать и с остальными коржами. Сверху торт равномерно покрыть кремом со всех сторон и украсить фруктами или ягодами (например, клубникой).',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3878,'Нежный творожный торт на сковороде поставить в холодильник минимум на час, чтобы пропитался. Подавать с чаем или кофе. На второй день торт будет еще вкуснее, если что-то от него останется.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3879,'Хлеб пропечь в тостере или на сухой сковородке с обеих сторон. Нарезать брусочками (0,8 сантиметра), также нарезать бекон и сыр. Брусочек хлеба смазать горчицей, положить на край полоски с беконом, рядом уложить брусочек сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3879,'Плотно завернуть и уложить на решетку над раскаленным углем. Запекать около 5-8 минут, периодически переворачивать. Сыр должен слегка расплавиться, а бекон подрумянится. Закусочные трубочки из бекона выложить на блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3880,'Слить жидкость с кукурузы, почистить лук и мелко нашинковать. Морковь почистить и натереть. Лук и морковь обжарить на сковородке, затем добавить в сковородку рис (промытый) и кукурузу, помешать, чтобы они пропитались маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3880,'Выложить подготовленную смесь в форму и залить стаканом горячей воды или бульона. Курицу хорошо натереть солью и паприкой и специями со всех сторон, выложить на смесь. Сверху положить фольгу и отправить в духовку примерно на час. Куриные «Ленивые» ножки перед подачей украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3881,'Смешать муку, соль и дрожжи. Отдельно соединить воду и масло. В сухую смесь влить жидкость и замесить тесто. Выложить его на стол и месить минуты 2-3. Положить тесто в миску. Прикрыть миску полотенцем или пленкой и отправить в теплое место на полчаса, пока оно не увеличится примерно в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3881,'Потом снова тесто месить примерно 1-2 минуты. Затем домашнее тесто для итальянской пиццы раскатать в круг и положить на противень. Прикрыть сверху и отставить минут 20. Выложить начинку (по своему усмотрению) и отправить в заранее нагретую духовку на 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3882,'Сыр нарезать полосками. Развернуть крабовую палочку, положить сыр и завернуть палочку обратно. Кляр: перемешать молоко, яйца, соль, муку и перец. Тесто консистенцией должно получиться как сметана. Обмакнуть в кляр и обжарить крабовые палочки в кляре со всех сторон на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3883,'Просеять муку и перемешать ее с остальными сыпучими продуктами (сахар, соль, сода). Яйца взбить с ряженкой и маслом, далее продолжать взбивать, постепенно добавить муку. На поверхности должны сразу образовываться пузырьки воздуха, если они не показались, то оставить тесто на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3883,'Подогреть сковороду, намазать ее маслом (обязательно немного смазать, а не налить, тогда получаться нежирные легкие оладьи). Сухими они не будут, так как масло присутствует и в тесте. Тесто необходимо наливать столовой ложкой, подождать пару минут и перевернуть. Подавать бабушкины оладьи на ряженке с медом или вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Котлеты из картофеля под сметанно-грибной подливкой подаются к столу горячими с гарниром по желанию.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3884,'Замочить желатин в паре столовых ложек воды, отставить (10 минут). Сливки взбивать, пока не сформируются устойчивые пики. Подогреть желатин до полного растворения (не кипятить). Взять большую емкость, смешать йогурт, ванилин, сахар, желатин и цедру. Добавить мелко порезанный ананас.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3884,'Дальше ввести взбитые сливки. Сок, в котором были ананасы, вылить в емкость и макать в него печенье перед тем, как формировать слои.  Выкладывать – печенье, крем, опять печенье и крем. Закрыть йогуртный торт «а-ля Тирамису» с ананасом  пленкой и поставить в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3885,'Мякоть свинины помыть, разрезать на четыре порционных куска, каждый кусок хорошо отбить, натереть смесью из перцев (лучше свеже смолотой), мускатного ореха, соли, убрать на холод и дать пропитаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3885,'В плоской посуде взбить яйцо, смочить свинину в яйце, запанировать смесью тертого сыра с тмином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3885,'Затем мясо можно либо обжарить на сковороде, либо на среднем огне запечь в духовке, предварительно смазав маслом противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3885,'К столу свинина с сыром по-карпатски подается с большим количеством зелени и жареным картофелем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3886,'Лук порезать колечками (толщина 6 миллиметров). Положить в дуршлаг и обдать кипятком. Кляр: взбить яйца, затем добавить соль, сметану, а далее муку. Консистенцией должно получиться, как тесто на оладьи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3886,'Опустить кольца в кляр. Разогреть масло на сковородке, аккуратно обжарить колечки с обеих сторон. Хрустящие луковые колечки  к пиву подавать с томатным или чесночным белым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3887,'Сначала необходимо сварить несколько картофелин, чтобы получилось готового пюре 2 стакана. Промыть грибы, измельчить соломкой и поджарить в малом количестве масла. Порезать лук и поджарить вместе с грибами. Добавить перец, соль по вкусу и немного зелени для аромата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3887,'Готовые грибы (без жира и жидкости) выложить на плоскую тарелку и остудить. На них уложить слой картофельного пюре, смазать майонезом. Затем выложить филе курицы, порезанное на маленькие кусочки и снова промазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3887,'Потом слой сладкой кукурузы и слой пюре. Сформировать розу из чипсов – в центр поставить самые маленькие и завернутые, а далее по кругу ставить чипсы большего размера, ряд за рядом. Салат «Роза» с копченой курицей готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3888,'Сухофрукты порезать кусочками размером 1х1 сантиметра. Марципановую массу можно немножко разогреть в микроволновке или размять хорошо руками, она должна получиться мягкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3888,'К ней добавить сахарную пудру, масло, крахмал, ванильный и инвертный сахар, цедру, соль и взбить массу. Постепенно добавлять яйца, дальше просеянную муку с разрыхлителем, фруктовую начинку и коньяк.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3888,'В формы для выпечки уложить бумагу, смазать маслом и выкладывать тесто на 2/3 каждой формы. Выпекать в разогретой духовке примерно час (температура 150 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3888,'Остудить, вынуть из формы, пропитать сиропом, смешанным с коньяком или ликером, завернуть в пленку и отправить в холодильник на сутки. Готовый рождественский кекс с финиками и инжиром покрыть шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3889,'Капусту мелко нарезать, ветчину и перец нашинковать соломкой. В миске смешать подготовленные ингредиенты, добавить консервированную кукурузу. Приправить солью и черным перцем, перемешать с добавлением майонеза. Быстрый салат из пекинской капусты посыпать зеленым луком и кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3890,'Картофель натереть, лук мелко нашинковать, чеснок выдавить с помощью пресса. Все ингредиенты добавить в фарш, присоединить размоченный мякиш, майонез, присолить и поперчить. Слепить котлеты, поместить их на противень, предварительно обвалять в панировке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3890,'Готовить при температуре 180 градусов, через 20 минут котлеты промазать маслом, а в противень налить немного воды,  продолжать готовить в течение 20 минут. Картофельно-мясные котлеты  из духовки подавать с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3891,'Заварить в кипящем подсоленном молоке (воде) из муки с добавлением яйца тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3891,'Сделать творожную начинку, добавив в протертый через сито творог сахар, взбитое яйцо и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6209,'Поперчить, украсить укропом Канапе с икрой мойвы, сельдью и яблоком и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3891,'Отрезать от теста небольшие кусочки и руками аккуратно растягивать в тонкие кружочки. По центру каждого чайной ложкой выложить творожную смесь и защипать края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3891,'Положить вареники из гречневой муки с творогом по-украински в подсоленную кипящую воду, и после закипания проварить 7-10 минут. Можно приготовить на пару, тогда они точно не расползутся, и начинка останется на месте, даже если плохо защипать края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3891,'Подавать вареники со сметаной и сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3892,'Для начинки, необходимо нашинковать лук и измельчить грибы, обжарить их до золотистого цвета. Для теста, смешать муку, натертое масло, ввести сметану и замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3892,'Раскатать и поместить в форму, на тесто выложить начинку. Взбить яйца, молоко, сметану и сыр, смесь залить в форму. Запекать в течение 45 минут, при 180 градусов. Грибная запеканка под сыром готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3893,'Сделать тесто для пельменей, смешав муку с холодной водой и яйцом. Для начинки, пробить в блендере лук, чеснок и ядра грецких орехов, посолить. Тесто порезать на кусочки, раскатать, в центр поместить подготовленную начинку и залепить края. Пельмени с грецким орехом отварить в воде с добавлением соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3894,'Куриное филе, порезанное на кусочки, обжарить. Овощи нарезать на средние дольки, смешать с майонезом. На лаваш выложить курицу, сдобрить кетчупом, добавить овощи. Лаваш свернуть в конверт. Закуску из лаваша с курицей и овощами можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3895,'Взбить яйца и сахарный песок, смешать муку и какао. Мучную смесь порционно ввести в яичную массу. Тесто поместить в форму и выпекать до готовности. Бисквит еще горячим вынуть из формы и сложить пополам, в середину положив скалку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3895,'Остудить в таком виде. Масло взбить добела, ввести сгущенное молоко, все взбивать до образования пышной массы. Для глазури, на водяной бане прогреть масло, шоколад и сливки. Бисквит раскрыть, вынуть скалку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3895,'Промазать половиной крема, положить банан, опять промазать кремом и накрыть другой половиной бисквита. Банановый торт «Слоновья слеза» полить шоколадной глазурью, а бока украсить дроблеными орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3896,'Готовый фарш приправить специями и солью. С помощью пресса для чеснока выдавить 2 зубчика в фарш, вбить яйцо, ввести сметану и четверть стакана муки, все ингредиенты хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3896,'Луковицу и картофель натереть на терке, отжать сок и вбить яйцо, всыпать остатки муки, приправить специями и солью и все перемешать. Получившееся тесто из картофеля выложить в разъемную форму, предварительно промазанную маслом, сформировать бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3896,'В середину выложить начинку. Запеканку готовить в течение 45 минут, при 180 градусов. По истечению отведенного времени запеканку из картофеля с индейкой посыпать натертым сыром и готовить еще в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Замесить из муки, желтка, масла и холодной воды с добавлением соли тесто, убрать в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Обжарить порезанное мелкими кубиками сало и тонко нашинкованный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Из сливок, яиц, сыра и измельченного зеленого лука приготовить смесь, поперчить ее и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Раскатать тесто чуть больше формы, чтобы можно было сформировать бортики, выложить его в форму, положить и разровнять на нем сало с луком и залить приготовленной смесью из сливок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Поставить пирог с салом по-украински в микроволновую печь, установить ее на среднюю мощность и выпекать 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3897,'Перед подачей пирог посыпать нашинкованной зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3898,'В миске смешать готовый фарш, предварительно отваренный рис и яйцо, все ингредиенты  сдобрить специями. Добавить одну мелко нашинкованную луковицу  и все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3898,'Сформировать небольшие шарики, обжарить их до золотистой корочки. Луковицу и грибы порезать и обжарить на другой сковороде, влить сливки. Получившейся соус приправить солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3898,'Обжаренные тефтели залить подготовленным соусом, присыпать сыром и запекать в духовом шкафу в течение 30 минут, при 180 градусах. Мясные тефтели в грибном соусе можно подать с любым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6229,'В холодном молоке замочить красивые крупные головки белых сушеных грибов на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3899,'Шоколад, масло и соль растопить на водяной бане. Желтки взбить. Вскипятить половину стакана воды и аккуратно влить в нее взбитые желтки, не переставая помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3899,'Растопленный шоколад хорошо перемешать, ввести 1/3 желтков, все перемешать и добавить остатки желтков. Все ингредиенты тщательно взбить до однородной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3899,'Массу вылить в форму, застеленную фольгой, убрать на холод. Когда масса затвердеет, разрезать на кусочки и обвалять их в какао. Трюфели из горького шоколада без сахара готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3900,'В жаропрочную посуду поместить молоко, добавить в него масло, соль, вскипятить, затем убрать с огня и ввести муку, перемешивая венчиком. Довести до однородной консистенции. Когда заготовка чуть остынет, по одному ввести яйца и еще раз взбить, должно получиться однородное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3900,'На противень, устланный пергаментом, при помощи ложки выложить шарики теста. Пирожные готовить на протяжении 7 минут, при 220 градусах, затем уменьшить температуру до 180 и выпекать еще 10 минут. Профитроли остудить. Для приготовления крема смешать сахарный песок, яйца,  муку и взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3900,'Молоко вскипятить и аккуратно ввести в него яично-мучную смесь, тщательно вымешивая довести до кипения, а затем остудить. Каждое пирожное начинить кремом. Для приготовления карамели необходимо смешать сахарный песок и воду в кастрюле с толстым дном и поставить на огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3900,'Когда сахар расплавиться и потемнеет, перемешать содержимое кастрюли и снять с огня. Карамель должна быть золотистого цвета. Начиненные профитроли обмакнуть в горячую карамель и сформировать пирамиду. Французский десерт крокембуш с карамелью украсить нитями из карамели и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3901,'Куриную грудку сварить в подсоленной воде и разделить на волокна. Яйца отварить и  измельчить с помощью терки. Лук мелко нашинковать и смешать с майонезом. Все ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3901,'Ломтик сыра разрезать на 3 части. На каждую часть выложить подготовленную начинку и завернуть розочкой. Одна порция состоит из 3 частей разрезанного сыра. Закуску из сыра «Розы для милых дам» выложить на блюдо и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3902,'Бананы и ананас порезать кусочками, поместить в кастрюлю, добавить стружку, всыпать сахар, влить сок лимона и сироп от ананасов, все перемешать и довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3902,'Готовить на небольшом огне в течение 10 минут, затем измельчить при помощи блендера и еще немного поварить. Домашний джем «Monkey Butter» можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3903,'Рис отварить и остудить, огурец и яйца измельчить с помощью терки, лук нашинковать, печень трески размять и слить жир. В сервировочное блюдо выложить слоями сначала рис, затем печень, сверху лук и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3903,'Каждый слой промазать майонезом, последним слоем выложить огурец. Если для подачи используется блюдо с высокими краями, слои можно повторить. Слоеный салат с печенью трески и рисом украсить по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3904,'Все подготовленные продукты перемешать в миске, получившееся тесто поместить в форму, выпекать при 180 градусах, до готовности. Бисквит остудить и разрезать на две равные части. Для приготовления крема необходимо сварить молочную манную кашу, взбить масло и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3904,'Соединить кашу и масленую смесь, добавить стружку, все перемешать. Нижний слой обильно промазать кремом и накрыть верхней частью. Полить торт «Баунти» с нежным манным кремом растопленным шоколадом и убрать на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3905,'Сварить из костей наваристый бульон, отдельно до готовности – перловку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3905,'Потушить капусту (если очень кислая, то слегка промыть) на бульоне с добавлением томата жира и специй.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3905,'Отварить на мясном бульоне грибы, сделать зажарку из муки и мелко нашинкованного лука, нарезать соломкой колбасу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3905,'Смешать капусту, грибы, зажарку и колбасу, все выложить в кастрюлю с бульоном, дать закипеть и проварить 10 минут, добавить часть порезанной зелени, дать настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3905,'Суп грибной с капустой по-гуцульски подавать со сметаной и зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Нагреть на сковороде муку до кремового цвета, добавить сливочное масло и сметану, хорошо перемешать, прогреть 3 минуты, этим соусом полить голубцы при подаче.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3906,'Куриное филе разрезать на порционные куски и отбить при помощи молотка. Для приготовления кляра необходимо, смешать в миске яйца, сметану и соль, всыпать муку с содой и все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3906,'Подготовленное куриное филе посолить и присыпать перцем, обмакнуть в кляр. Обжарить на горячей сковороде сначала с одной стороны в течение 5 минут, затем с другой еще несколько минут. Куриные отбивные в хрустящем кляре подать с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3907,'Для приготовления теста необходимо, просеять муку и перемешать все сухие ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3907,'Вбить яйца и тонкой струей ввести молоко, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3907,'Жарить блины на раскаленной сковороде промазанной маслом. Сначала обжарить с одной стороны, затем с другой. Блинчик должен зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3907,'Тонкие блины на молоке смазать сливочным маслом и кушать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3908,'Мясо промыть и порезать на кусочки и обжарить с каждой стороны до золотистого цвета. Лук и грибы нарезать, тушить на сковороде с добавлением сливочного масла. Картофель отварить и нарезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3908,'Подготовленные продукты поместить в горшочек, присыпать тертым сыром и накрыть крышкой. Горшочек поместить в духовку, готовить при 180 градусов, в течение 20 минут. Свинина с сыром и картофелем  в горшочке готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3909,'Яйца и рис отварить. Капусту нашинковать, а рыбу порезать дольками. Для приготовления соуса смешать сливки, майонез и сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3909,'В блюдо выложить поочередно, сначала капусту, затем рис и куриные яйца, заключительный слой – рыба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3909,'Каждый слой промазать соусом. Выкладку повторить. Салат украсить перепелиными яйцами и икрой. Салат «Федоровский» с красной икрой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3910,'Обжарить дольки картофеля в растительном масле, дать зарумяниться на сильном огне, затем, уменьшив нагрев, довести до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3910,'Нарезать все овощи кубиками, потушить до мягкости, в конце добавить помидоры, поперчить, добавить мускатный орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3910,'Сварить (лучше на бульоне) рассыпчатый рис, смешать его с картофелем и тушеными овощами, посолить, долить бульон, тушить 10-15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3910,'Салат из овощей с рисом по-карпатски — прекрасная горячая закуска для холодного времени года.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3911,'Чиабатту разделить на две части, разрезав ее вдоль, промазать майонезом и на обе половинки выложить тонко порезанный сыр. Далее уложить ветчину, смазанную горчицей и буженину. Затем жгучий перец, лук, салат и дольки помидор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3911,'Готовый бутерброд обжарить на раскаленной сковороде гриль до образования золотистых полосочек с каждой стороны. Во время обжарки, панини с бужениной необходимо придавить прессом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3912,'Смешать все сухие продукты и ввести молоко, сливочное масло растопить и добавить в заготовку. Яйцо взбить и присоединить к остальным продуктам. Готовое тесто поместить в кондитерский мешок и отсадить в специальные углубления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3912,'Пончики готовить в аппарате для приготовления пончиков в течение 4 минут с каждой стороны. Затем, смешать сахарный песок и корицу в целлофановом пакете, поместить в него готовые пончики с корицей и хорошо потрясти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3913,'Бекон порезать на средние ломтики, поместить в чашу мультиварки и обжарить, используя программу Выпечка  (установить на 40 минут), в течение 15 минут, затем добавить нашинкованный чеснок. Через пару минут ввести томатную пасту и сливки, посолить и добавить перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3913,'Соус готовить, постоянно помешивая, до загустения, в течение 10 минут.  Затем, в соус поместить спагетти, разломанные на две части, долить горячей воды и готовить до окончания программы. Установить программу Тушение и готовить спагетти «Карбонара» со сливками до окончания программы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3914,'Для приготовления коржа необходимо, смешать все подготовленные ингредиенты, тесто поместить в разъемную форму, промазанную маслом. Выпекать корж до золотистой корочки, при температуре 200 градусов. Готовый корж остудить и пропитать сахарным сиропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3914,'Желатин замочить в молоке, оставить до набухания, а потом прогреть на водяной бане. Творог, сметану и сахарный песок пробить блендером до однородности. Соединить творожную смесь и желатин с молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3914,'Бананы измельчить, выложить на корж и залить готовым бланманже. Творожный торт бланманже с фруктами украсить дольками персиков и залить желе. Убрать на холод до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3915,'Подготовленные ингредиенты смешать и пробить блендером. Получившийся кофейный крем-ликер разлить по бутылкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3916,'Спелые бананы размять до состояния пюре при помощи вилки. Присоединить все сухие компоненты, вбить яйца и все тщательно взбить. Влить молоко, перемешать, добавить овсяные хлопья и измельченные орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3916,'Получившееся тесто поместить в форму, выпекать при 180 градусах, накрыв фольгой. Через 30 минут убрать фольгу и запекать еще в течение 15 минут.  Бананово-овсяная запеканка в молоке можно кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3917,'Налить в кастрюлю воду для супа, довести до кипения, подсолить, добавить морковь и картофель, нарезанные небольшими кубиками, варить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3917,'Обжарить на масле до прозрачности нарезанный кубиками репчатый лук, выложить жареный лук в кастрюлю с супом, бросить лавровый лист, заправить чесноком и проварить еще 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3917,'Добавить любые готовые шкварки, зелень и дать закипеть, убрать с плиты, дать настояться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3917,'В тарелке картофельный суп по-татарски со шкварками посыпать зеленью и добавить ложку сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3918,'Нагреть духовку (190 градусов). Перемешать творог с маслом, затем добавить яйцо. Муку отдельно перемешать с солью, разрыхлителем и сахаром, прибавить ее к массе из творога. Замесить тесто, оно не должно быть очень крутое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3918,'Отставить тесто минут на 10, а пока можно сделать начинку. Сыр потереть на большой терке, чеснок измельчить. Перемешать чеснок, сыр, тимьян и сметану. Тесто поделить на две части (чтобы одна часть была немного больше). С каждой части сформировать шар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3918,'Затем каждую часть раскатать в круг (соответственно большего и меньшего диаметра) примерно 8 миллиметров толщиной. Круг меньшего диаметра уложить на противень с пергаментной бумагой (края немного смазать водой), на него выложить начинку (по всей площади). Накрыть кругом большего диаметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3918,'Свободные края верхнего круга аккуратно завернуть под нижний. Получившуюся сырную лепешку смазать яйцом, присыпать кунжутом и запекать 20-30 минут, пока не станет золотистого цвета. Накрыть домашнюю творожную лепешку с сыром полотенцем, и немного остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3919,'Грудку куриную порезать на небольшие кусочки и бросить в кипящую подсоленную воду, варить минут 15. Картофель нарезать кубиками, добавить в бульон к курице.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3919,'Морковь порезать на кусочки небольшого размера (можно натереть), лук нашинковать. Разогреть сковородку с растительным маслом, приготовить поджарку из лука и моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3919,'Переложить ее в суп и варить еще минут 10. Сыр нарезать кусочками и положить в суп и мешать, пока сыр не растворится. В суп с плавленым сыром и куриной грудкой добавить зелень и специи и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3920,'Тесто: взять 5 яиц и перемешать со стаканом сахара (не взбивать). Прибавить чайную ложку соды (не гасить). Затем добавить стакан муки и пачку какао (100 грамм). Перемешать все в однородную массу. Далее добавить неполный стакан кефира и при необходимости еще немного муки, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3920,'Тесто по консистенции следует сделать, как густая сметана. Поделить тесто пополам, одну часть вылить в форму и печь в духовке до готовности. Затем испечь второй корж и полностью их остудить. Остывшие коржи разрезать пополам, две половины оставить, а две порезать или поломать на маленькие части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3920,'Крем: пол литра сметаны взбить со стаканом сахара. Взять три пачки желатина, замочить их в горячей кипяченой воде, когда полностью растворится добавить в сметану. Порезать фрукты маленькими кусочками. Смешать сметанный крем с нарезанными фруктами, пачкой мака и раздробленными коржами. Взять форму, в которой запекались коржи, положить один целый корж на дно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3920,'Далее положить сметанно-фруктовую массу. Оставшийся корж разрезать в форме ромашки и положить сверху торта. Поставить торт «Африканская ромашка» с фруктами в холодильник на час, для пропитки. По желанию лепестки ромашки украсить глазурью или мастикой, но и без этого торт можно кушать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3921,'Разобрать брокколи, бросить в подсоленную кипящую воду на 5-6 минут, прикрыть крышкой, затем вынуть брокколи из воды. В отдельной емкости взбить яйцо, добавить сыр, чеснок, муку, перец и соль, перемешать, затем молоко, а потом и брокколи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3921,'Взять толкушку и сделать пюре. Разогреть сковородку, налить немножко масла и на небольшом огне поджарить оладьи. Готовые оладьи с брокколи и сыром выложить на бумажное полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Отварить до готовности в подсоленной воде говядину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Пока варится мясо можно приготовить домашнюю лапшу, для этого в горке просеянной муки сделать углубление, влить яйцо, подсолить и постепенно, добавляя охлажденную воду замесить тесто, дать ему созреть 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Нашинковать лук кольцами, а морковь кружками, положить в кипящий, бульон (предварительно достать готовое мясо) и варить15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Раскатать тесто в тонкий пласт, подсушить 10 минут, нарезать в форме тонкой лапши, можно ромбами, треугольниками или квадратами, и дать лапше подсохнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Добавить в суп подсохшую домашнюю лапшу бросить лавровый лист, поперчить, посолить и варить, пока лапша не всплывет. Убрать нагрев, и дать супу настояться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3922,'Суп-лапша с мясом по-татарски разлить по тарелкам, в каждую добавить порезанное брусочками отварное мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3923,'Луковую шелуху замочить в воде (ненадолго), затем поставить ее на огонь, посолить (на 1 литр воды необходимо положить 5 столовых ложек соли).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3923,'Луковую воду вскипятить, положить скумбрию и варить 3 минуты (не больше). Выложить скумбрию на дуршлаг, дать стечь. Скумбрию в луковой шелухе нарезать кусочками и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3924,'Крабовые палочки нарезать маленькими кусочками. Зубчики чеснока потереть на небольшой терке. Положить сыр в емкость и добавить к нему чеснок, хорошо перемешать. Зелень укропа необходимо промыть, высушить и мелко порубить. Лист лаваша разрезать ровно на 4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3924,'Для этого лаваш свернуть пополам, перерезать, потом каждую часть сложить напополам и снова разрезать. Положить один пласт лаваша, намазать сыром, посыпать зеленью, выложить крабовые палочки на всю поверхность. Прикрыть вторым пластом лаваша, повторить с начинкой и третьим пластом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3924,'Сверху накрыть пластом лаваша (четвертым) и хорошо прижать. Взять острый нож и разрезать получившийся брикет на небольшие квадратики. Добавить муку к яйцам, взбить, восточные гренки на тонком лаваше обмакнуть в яичную смесь и поджарить на растительном масле со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3925,'Готовое тесто разморозить и слегка раскатать. Затем разрезать на квадратики, положить внутрь начинку (смешать кубики копченой колбасы, тертый сыр и измельченный чеснок). Сложить треугольниками, края защипнуть вилкой. Смазать закрытую пиццу на слоеном тесте яйцом и отправить в духовку минут на 20.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3926,'Бекон порезать небольшими кусочками, лук нашинковать. Разогреть сковородку, поджарить бекон и лук (можно и без него, по желанию). Небольшими кусочками порезать вареный картофель, добавить на сковородку к бекону и луку и потушить все вместе. Затем в жареный картофель с беконом добавить измельченную зелень, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3927,'Залить водой сахар и поставить на небольшой огонь. Вскипятить и проварить приблизительно 3 минуты, постоянно мешая. Убрать с огня, растворить в получившемся горячем сиропе какао и масло, тщательно помешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3927,'Постепенно добавить сухое молоко, положить орехи (измельченные). Хорошо вымесить массу и отправить в холодильник (на час). Затем, вылепить шоколадные трюфели с орехом в форме пирамидок и обвалять в какао. Подавать с чаем или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3928,'Вытопить в кастрюле из нарезанного кубиками сала жир, добавить порезанное на кусочки мясо и помешивая слегка обжарить со всех сторон, добавить пару стаканов воды и тушить на малом огне 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3928,'Порезать лук на кубики и засыпать к мясу, залить литром воды и дать супу закипеть, добавить разрезанный на четвертинки картофель и варить до его готовности, а за 7 минут положить лавровый лист, перец и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3928,'Перед подачей татарский суп с мясом сдобрить большим количеством рубленой петрушки и заправить измельченным чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3929,'Насыпать на стол муку, масло порезать на кусочки и добавить к муке, затем все вместе порубить ножом. Должна получиться крошка. Добавить сюда же соду и сахар и перемешать (можно продолжить рубить ножом). Поставить тесто в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3929,'Начинка: взбить яйца с творогом, ванильным сиропом и сахаром (лучше блендером). Добавить изюм, перемешать (вручную). Из холодильника достать крошку, большую часть ее высыпать на противень (не утрамбовывать), разровнять, сделать небольшие бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3929,'Противень смазывать не надо. На крошку выложить начинку, разровнять и присыпать ее оставшейся крошкой. Поставить в нагретую духовку примерно на 40-50 минут. Дать песочному пирогу с творогом немного остыть, затем вынуть из противня, нарезать кусочками и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3930,'Творог протереть сквозь сито (можно блендером), прибавить сметану и тщательно помешать. Фрукты почистить и порезать кубиками или брусочками. Взять блин, на 1/3 от кромки блина положить полоску начинки, положить фрукты и скрутить плотно рулетом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3930,'Так же сделать рулеты из остальных блинов, фруктов и творожной массы. Готовые рулеты убрать в холодильник на час-полтора. Роллы из блинов с творожной начинкой вынуть из холодильника, нарезать кусками, выложить на тарелку, притрусить шоколадной стружкой и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3931,'Хорошо промыть картофель в мундире, уложить его в кастрюлю и налить воды таким образом, чтобы она прикрывала картофель примерно на 8-10 сантиметров. Поставить кастрюлю на плиту (средний огонь) и сварить картофель до полной готовности (минут 20). Тем временем нужно натереть сыр на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3931,'Снять кастрюлю с готовым картофелем с плиты, слить воду. Почистить картофель (нанизать картофелину на вилку и с помощью ножа снять кожицу). Пропустить очищенный картофель сквозь мясорубку с небольшой насадкой (можно воспользоваться комбайном). Переложить пюре в глубокую емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3931,'Добавить в пюре измельченный сыр, по вкусу посолить, поперчить, прибавить мускатный орех. Вбить 1 яйцо, перемешать все ингредиенты до однородной консистенции. Получится масса средней плотности. Остудить до комнатной температуры, нагреть духовку до 190 градусов, положить на противень пекарскую бумагу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3931,'Остывшую картофельную массу переложить в кондитерский мешок (насадка звездочка), выдавить пюре в виде завитков на противень. Оставить между фигурками пространство (сантиметра 3-4). Поставить противень в духовку, печь минут 15-20, пока не образуется золотистая корочка по краям завитков. Вынуть французские картофельные завитки из духовки и выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3932,'Нашинковать мелко лук, шампиньоны и поджарить на оливковом масле. Филе куриное порезать маленькими кусками. Помидоры порезать кольцами. Уложить все продукты на тарелку слоями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3932,'Сначала курица, затем лук с грибами и помидоры (все слои смазать майонезом), сверху обильно присыпать тертым сыром. Дать салату «Тоска» с шампиньонами постоять в холодильнике пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3933,'Баклажаны порезать кружочками (около 1 сантиметра), посолить и отставить. Грибы порезать пластинками (если большие, то кубиками), чеснок мелко нашинковать, перемешать со специями и сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3933,'Брынзу и сыр потереть на мелкой терке (можно и без брынзы), помидоры порезать кружочками. Баклажаны еще раз промыть и по необходимости опять посолить. Взять форму для выпекания, смазать маслом, уложить баклажаны, затем грибы, а потом помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3933,'Смазать сверху смесью со сметаной, присыпать смесью брынзы и сыра. Запечь в духовке примерно полчаса (180 градусов). Запеченные под сыром баклажаны с грибами вынуть из духовки и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Голубцы в вине по-татарски со сметанным соусом – это одна из вариаций всем известных голубцов, только «пьяных».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Отделить от проваренного в течение 8 минут кочана капусты 4 крупных листа, у каждого вырезать центральное утолщение.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Обжарить и смешать лук с рисом, фаршем, яйцами, специями и посолить, выложить полученную смесь на капустные листы и свернуть их в виде рулетов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3934,'Порезать ломтиками сало, выложить их на дно сотейника, сверху положить кислую капусту, а на нее – рулеты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3935,'Промывать рис, пока вода не будет прозрачной, потом залить его чистой водой (1:1,2) и вскипятить на сильном огне. Затем огонь убавить и варить примерно 12 минут (зависит от сорта риса). Готовому рису необходимо дать постоять под крышкой, потом добавить уксусную приправу и помешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3935,'Продукты для начинки нарезать длинными брусочками. Часть листа нори (3/4 части) положить на макису (коврик для роллов) и равномерно распределить рис по листу, не доходя примерно 1,5-2 сантиметра до края. На середину риса положить васаби и начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3935,'Лист нори  сворачивать от себя, придерживая начинку рукой. Получившемуся роллу придать округлую форму, разрезать его сначала пополам, а затем обе половины еще на три части. Роллы со свежим огурцом и тунцом готовы. Подавать с васаби, имбирем и соевым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3936,'Взбить желтки с сахаром, добавить маскарпоне и взбить до однородности. Отдельно взбивать белки пока не появятся устойчивые пики и аккуратно ввести их в массу с маскарпоне. Нарезать персики, в сиропе от них замочить печенье савоярди.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3936,'Затем выкладывать слоями: печенье в сиропе, крем, измельченный персик, повторить слои снова в том же порядке. Украсить нежный персиковый тирамису половинками персика. Отправить в холодильник, чтобы готовый десерт пропитался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3937,'Ягоды промыть и просушить на бумажном полотенце. Если ягоды не свежие, а замороженные, то после размораживания необходимо слить лишнюю жидкость и просушить также на полотенце. Бисквит: просеять муку (2 раза), белки отсоединить от желтков и переложить в отдельную емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3937,'Взбивать белки, постепенно добавляя сахар (по одной ложке) и ванилин. Белковая масса должна получиться белой и довольно густой. Далее добавлять по одному желтки, не переставая взбивать. Когда все будет взбито, постепенно добавлять муку, осторожно перемешивая ложкой снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3937,'Перелить тесто в квадратную форму и поставить в духовку на 25 минут (190-200 градусов). Пока бисквит печется открывать духовку нельзя. Через 25 минут выключить духовку и дать ему постоять минут 5 в закрытой духовке. Вынуть бисквит из духовки, немного остудить, обрезать края и разрезать на две ровные части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3937,'Размягченное масло взбить с сахарной пудрой, добавить ягоды и перемешать. На бисквит выложить начинку, прикрыть оставшимся коржом и снова положить начинку (разровнять по всей поверхности и бокам). Поставить бисквитное пирожное «Ягодка» в холодильник часа на 3 (можно на ночь), вынуть и порезать на маленькие порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3938,'Замочить окорочка (лучше на ночь) в смеси из соли, чеснока и перца. Слоеное тесто разморозить, порезать на квадраты. Промазать каждый квадрат взбитым яичным белком и положить в центр небольшой кусочек сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3938,'В каждый окорочок аккуратно, возле косточки затолкать чернослив, замоченный в коньяке (на полчаса), и кусочек грецкого ореха. Завернуть каждый в тесто конвертиком и уложить на противень. Смазать  тесто желтком и присыпать кунжутом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3938,'Отправить в духовку на час (180 градусов), если тесто зарумянится раньше, то сверху необходимо прикрыть фольгой, чтобы не пригорело. Куриные ножки  в слоеном конвертике подавать с овощным салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3939,'Помыть печень, обсушить бумажным полотенцем и порезать на кусочки. Разогреть на сковородке растительное масло, поджарить печень до румяной корочки, добавить соль, перец. Затем полить печень вином и продолжить жарить до полного его испарения. Переложить печень на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3939,'На сковородке разогреть сливочное масло и обжарить муку. Развести молоком сливки и добавить к муке. Тщательно перемешать, чтобы не было комков, добавить соль, перец. Сюда же прибавить тертый сыр и размешивать до полного его растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3939,'Положить в эту смесь печень, прогреть примерно 1 минуту, добавить измельченную зелень. На гарнир можно отварить спагетти или лапшу. Выложить гарнир на блюдо и подать с кусочками нежной печени в сырном соусе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Порезать мясо на несколько крупных кусков, отварить в 2 стаканах соленой воды, остудить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Очистить и порезать на четыре (мелкий пополам) части картофель, сварить в воде с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Нашинковать и обжарить морковь с луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Выложить на дно формы порезанное мясо, сверху кусочки картофеля, а на него зажарку из моркови и лука, залить стаканом бульона, добавить перец и отправить на 40 минут в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Тушенный картофель с мясом по-татарски можно приготовить и чуть иначе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Разрезать мясо на крупные куски, присыпать перцем, обвалять в муке, обжарить до аппетитной корочки на сковороде, переложить в казанок, добавить к мясному соку в сковороде стакан воды, прокипятить, процедить и вылить в мясо, посолить, тушить на медленном огне порядка часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3940,'Выложить на готовое тушеное мясо вареный картофель, сверху – луковую зажарку с морковью, добавить лавровый лист, несколько горошин душистого и черного перцев и тушить еще полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3941,'Растереть яйца с разрыхлителем, солью, добавить стакан кефира. Взбивать миксером, понемногу добавляя муку. Тесто должно получиться консистенцией, как на оладьи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3941,'В готовое тесто добавить тертый сыр, зелень (любую), несколько измельченных сосисок (можно колбасу или вареное мясо).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3941,'Еще раз тщательно перемешать и перелить в форму для выпекания (смазанную маслом). Выпекать сырный пирог с колбасой примерно 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3942,'К кефиру добавить сахар, соль, погашенную уксусом соду, перемешать. Добавить муку, чтобы получилось не крутое тесто, вымесить. Скатать шар, завернуть тесто в пленку или накрыть тарелкой и оставить примерно на полчаса. Поделить тесто на 4 части, раскатать каждую в тонкую лепешку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3942,'Начинка: посолить творог, прибавить тертый сыр, размельченный чеснок, все перемешать. Начинку положить в центр лепешки и защипнуть, как пирожки, затем немного расплющить. Жарить простые хачапури с творогом на сухой сковородке (с толстым дном) минут 7-10 с обеих сторон, пока они не станут золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3943,'Взять дрожжевое тесто, оно пластичное и лепить из него очень легко и разделить на две части. Одну часть теста раскатать, вырезать из него форму рыбки. Отрезать тонкие полоски теста и из них выложить бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3943,'Положить начинку:  предварительно отваренный рис, рыбные консервы в масле и измельченный лук. Взять оставшуюся долю теста и также раскатать в тонкий пласт. Аккуратно вырезать из него голову и хвост рыбы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3943,'Рюмкой вырезать кружочки (чешуя и глаз). Выложить все части поверх начинки, вырезать плавнички. Смазать желтком и отставить ненадолго, чтобы пирог «Рыбка» с рыбной консервой  немного поднялся. Запекать в духовке до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3944,'Натереть твердый сыр и яйца на некрупной терке, добавить майонез и плавленый сыр, пропустить чеснок сквозь пресс, перемешать. Получившейся массой смазать кусочки хлеба.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3944,'Можно нарезать ломти хлеба пополам или по диагонали, на треугольники. Уложить салатные листья на тарелку, выложить на них ломтики хлеба, посыпать черным перцем, а сверху положить рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3944,'Тонко порезать помидоры и огурцы, измельчить зеленый лук. Рядом с рыбой на ломте хлеба положить помидор, огурец и украсить веточкой петрушки или укропа. Праздничные бутерброды с сыром и шпротами можно подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3945,'Перетереть творог сквозь сито (можно применить блендер), перемешать его со сметаной и сахаром. Замочить желатин в теплом молоке (взять половину молока) и отставить набухать. Оставшееся молоко нагреть, но не кипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3945,'Понемногу влить его в молоко с набухшим желатином, помешать. Порезать консервированные ананасы. Смешать творог с желатином и фруктами. Разлить творожное бланманже с ананасом в формочки и поставить в холодильник на 3-4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3946,'Перекрутить дважды на мясорубке с мелкой решеткой филе сельди, добавить растительное масло, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3946,'Нарезать лук и огурец небольшими кубиками, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3946,'Выложить селедочный фарш на овальное блюдо (в форме удлиненной лепешки). Сделать по центру углубление и аккуратно вылить в него желток яйца, вокруг равномерно выложить лук с огурцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3946,'Рубленая сельдь по-татарски подается с горячим отварным картофелем и зеленью укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Смазать тост майонезным соусом положить на него поочередно лист салата, ломтик бекона, кружочки помидора и накрыть вторым тостом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3947,'Творог взбить с половиной масла и полстакана сахара. Для глазури: оставшееся масло растереть с остатками сахара и какао, до полного растворения сахара (будет быстрее, если использовать сахарную пудру). На пищевую пленку или фольгу выложить печенье, очертить контур краев печенья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3947,'Затем печенье убрать, на очерченной площади равномерно размазать глазурь. Печенье обмакнуть в молоко, уложить на глазурь. Намазать ровным слоем творожный крем. В центр выложить ряд ломтиков персика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3947,'Затем приподнять края фольги и завернуть таким образом, чтобы получился домик (треугольник). Отправить на пару часов в холодильник, снять фольгу (от глазури она отделится очень легко). Перед подачей, торт «Шалаш любви» с персиками, нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3948,'Картофель почистить, вымыть, срезать один бок так, чтобы картофель можно было установить вертикально. По всей длине картофеля сделать надрезы ножом,  не дорезая до края, примерно 1 сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3948,'Добавить перец, соль и положить внутрь каждой картошки по 1 чайной ложке масла. Можно вложить, по желанию, чеснок. Картофель уложить в форму для запекания с высокими бортиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3948,'Сверху на все картофелины уложить небольшой ломтик сыра. Запекать примерно 50 минут, до готовности картофеля. Подавать ароматный картофель «Дофинэ» горячим, присыпав измельченным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3949,'Нарезать бекон (ветчину или грудинку) небольшими прямоугольными брусочками. Эти брусочки обжарить на небольшом огне, с прибавлением оливкового масла. Опустить спагетти (или прочие виды макарон) в значительное количество кипящей подсоленной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3949,'Варить их необходимо до состояния аль-денте,  быть немного недоваренными. Натереть сыр на самую мелкую терку. Взять яйцо и желток взболтать их хорошо вилкой, добавить специи, соль, пряные травы. Сюда же добавить тертый сыр и тщательно помешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3949,'С готовых макарон слить воду и сразу же перемешать их с жареным беконом. Затем сразу же влить яично-сырный соус и перемешать. Классическую пасту «Карбонара» с сырным соусом выложить на тарелки и притрусить натертым твердым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3950,'Обжарить на среднем огне, предварительно нарезанные перец и лук, добавить измельченный чеснок. Влить вино, сок, добавить мед и специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3950,'Немного увеличить огонь и жарить, пока жидкость не уменьшится в два раза. Прибавить петрушку и креветки и прожарить еще минуты 3-4.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3950,'Сварить спагетти аль-денте (недоваренные), выложить в сковородку к креветкам, перемешать. Подавать спагетти с пряными креветками теплыми, присыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3951,'Поставить варить курицу целиком в подсоленной воде, готовую тушку порезать на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3951,'Нарезать на четыре части и отварить в подсоленной воде картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3951,'Сварить на курином бульоне нашинкованную морковь и лук, подсолить добавить перец, лавровый лист и масло, проварить еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3951,'Картофель переложить в сковороду, выложить на него куски курицы, залить овощным соусом и протушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3951,'Готовить курицу с картофелем под соусом по-татарски 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3952,'Масло немного размягчить, взбить с сахаром, добавить яйцо, и снова взбить. Перемешать сухие ингредиенты: какао, муку, ванильный сахар и разрыхлитель. Постепенно добавить мучную смесь и молоко к масляной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3952,'Выложить тесто на пергамент столовой ложкой, разровнять, чтобы получился небольшой круг. Выложить, таким образом, остальное тесто. Выпекать в духовке 10-12 минут, остудить. Крем: взбить сливки и сахарную пудру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3952,'Взять один испеченный круг (вупи), на него выложить ложкой или с помощью кондитерского мешка крем, и накрыть второй половинкой вупи. Так же поступить и с остальными вупи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3952,'Отправить домашнее пирожное «Whoopie» в холодильник (минут на 30). По истечении времени пирожное можно кушать. Хранить готовые вупи можно в холодильнике или в морозилке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Коржи. Взять сотейник с толстым дном, перемешать в нем сахар, мед и масло. Поставить на плиту на средний огонь. Вбить яйца в отдельную емкость и слегка взбить венчиком. Затем добавить яйца к уже теплой смеси, постоянно мешая. Помешивать до тех пор, пока масло и сахар не растворятся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Смесь держать на огне минут 5-7, пока не образуется белая пена (температура смеси примерно 70 градусов). Прибавить соду, подержать смесь на огне еще одну минуту, смесь должна увеличиться где-то в 2 раза, убрать с огня. Сливочно-яичную смесь перелить в чашу блендера, всыпать всю муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Мешать тесто на небольшой скорости минуты 2 до однородности. На этом этапе тесто может показаться слишком жидким. Муки досыпать не нужно, когда тесто остынет, оно будет пластичным и не липким. Сформировать шар из теста, немного дать полежать минуты 2-3, затем поделить его на 8 частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Из каждой части сформировать шарики, накрыть полотенцем или пленкой, чтобы тесто не заветрелось. Разогреть духовку раскатать 8 коржей, проколоть их вилкой, печь каждый по 3 минуты в духовке. Достать корж из духовки сразу же, не давая ему остыть и обрезать круг диаметром где-то 24 сантиметра, обрезки не выкидывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Когда все коржи испечены и обрезаны, положить обрезки на противень и поставить в духовку минут на 5, чтобы поджарились и стали ярко-янтарного оттенка. Дать остыть и размельчить в блендере в крошку. Крем: яйца с крахмалом взбить, молоко нагреть (но не кипятить) и тонкой струйкой ввести в яичную смесь, постоянно взбивая венчиком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Перелить смесь в сотейник с толстым дном и отправить на маленький огонь. Варить смесь, непрерывно мешая пока не загустеет (примерно 5 минут). В масло добавить мед, сгущенку и взбить. В последнюю очередь прибавить сметану, перемешать, но не взбивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3953,'Выложить первый корж на плоскую тарелку, смазать обильно кремом, присыпать сверху крошкой с обрезков. Накрыть вторым коржом и так далее. Верх торта и бока смазать кремом, присыпать крошкой. Поставить торт «Медовик» со сгущенным молоком в холодильник минимум на 12 часов (лучше на сутки), чтобы торт хорошо пропитался.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3954,'Нарезать соломкой огурцы и колбасу. Натереть на терке сыр и яйца. Добавить морковь, заправить майонезом и перемешать. Украсить салат «Флоренция» по собственному желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3955,'Взять ржаную булочку, положить на нее сыр. Поставить сковородку на средний огонь, налить немного растительного масла, добавить измельченный зубчик чеснока. Затем положить порезанные крупно листья шпината, добавить соль, перец, немного протушить и уложить наверх сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3955,'Яйцо-пашот необходимо готовить в последнюю очередь, чтобы при подаче оно было теплым. Для его приготовления потребуется вода, 2 столовых ложки уксуса и соль. Яйца поочередно разбить в небольшую мисочку (целостность не нарушать). Воду налить в кастрюлю и нагревать на небольшом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3955,'Когда на дне появятся пузырьки добавить уксус, аккуратно поднести мисочку с яйцом к самой воде и осторожно влить яйцо в горячую воду. Не давать яйцу опускаться на дно с помощью ложки с отверстиями. Готовить примерно 4 минуты, пока белок не схватиться (не станет белым).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3955,'Осторожно вынуть яйца из воды, положить на подушку из шпината и присыпать солью. Соус: перемешать 1/4 чайную ложку горчицы, 1/2 чайную ложку меда и 2 чайные ложки сметаны. Полить соусом яйца, добавить перец. Бургер с яйцами-пашот под соусом нужно подавать теплым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3956,'У багета срезать низ и вытащить мякоть (не всю, а большую часть). Дно смазать зернистой горчицей – это каноэ. Овощи измельчить, добавить перец и соль. Перемешать с тертым сыром, плотно уложить готовую смесь в каноэ.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3956,'Подготовленное каноэ и сосиску (отдельно) уложить на противень и поставить в духовку примерно на 20 минут. Сосиску прежде необходимо проткнуть вилкой в нескольких местах, чтобы она не треснула во время запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3956,'Когда истечет 20 минут, все достать из духовки, сосиску уложить в каноэ, присыпать тертым сыром. Оригинальный хот-дог «Каноэ» снова отправить в духовку, пока сыр не зарумянится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3957,'Печень сварить и натереть. Лук измельчить и обжарить на растительном масле. Рис сварить (воду предварительно посолить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3957,'Яйца, заранее сваренные, натереть. Уложить продукты на плоское блюдо пластами: печень, дальше лук, затем рис, измельченный укроп и яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3957,'Все слои смазывать майонезом или сметаной, перчить. Дать немного настояться и слоеный салат «Шапочка» с печенью готов к употреблению.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3958,'Порезанное мясо положить в сковороду, на него — слой картофеля, залить овощным бульоном, добавить несколько горошин черного перца, тушить либо на плите, либо в духовке 45-50 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3959,'Лук нашинковать полукольцами. Подогреть в кастрюле оливковое масло, прибавить к нему сливочное и растопить, добавить лук. Тушить приблизительно 5 минут, постоянно мешая. Убавить огонь, всыпать сахар и тушить еще около 15 минут, прикрыв кастрюлю крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3959,'Посолить и поперчить по вкусу.  Дальше готовить без крышки примерно полчаса, пока лук не примет карамельный оттенок. Влить вино, бульон и закипятить. Огонь уменьшить и варить примерно еще полчаса, пока суп не загустеет. Разогреть духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3959,'На застеленный пергаментом противень выложить куски багета, запечь до золотистого оттенка. Разлить суп по огнеупорным мисочкам, положить сверху кусок багета, присыпать тертым сыром. Запекать суп в духовке около 5-7 минут, пока сыр не зарумянится. Подавать французский луковый суп под сыром горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3960,'Разогреть духовку. Ягоды промыть и положить в большую миску. Взять отдельную емкость, смешать сахар, тапиоку и соль. Присыпать ягоды готовой смесью и осторожно смешать. Раскатать 2 пласта теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3960,'Выложить один пласт на дно в форму, мастеря бортики. На него уложить ягоды, прикрыть вторым пластом теста. Сделать в нем несколько отверстий. Поставить пирог со свежими ягодами в духовку и запечь до золотистой корки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3961,'Тесто: масло растопить, присоединить муку и перемешать венчиком до образования консистенции густого крема (несколько секунд). Струйкой влить молоко (холодное) и мешать венчиком, пока крем не станет гуще (консистенция густой сметаны).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3961,'Убрать с плиты, ввести по одному желтки, постоянно помешивая венчиком. Добавить мускатный орех, соль и тертый пармезан. Взбить белки и щепотку соли в крутую пену. Добавить белки в тесто. Аккуратно перемешать, снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3961,'Застелить противень пергаментом, вылить тесто и равномерно распределить. Запекать примерно 13 минут. Вынуть противень, накрыть корж полотенцем и немедленно скрутить совместно с ним рулетом. Дать рулету остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3961,'Начинка: тонкими ломтиками порезать рыбу, перемешать со сметаной и измельченным укропом. Рулет развернуть, положить начинку и скрутить, как можно плотнее. Завернуть сырный рулет с нежной семгой в фольгу и отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3962,'Филе куриное, перец болгарский и кабачок нарезать маленькими кусочками, натереть сыр на терке. Сделать фарш из курицы, сыра, овощей, яиц и муки, добавить перец и соль. Сформировать котлеты и обжарить их со всех сторон. Рубленые котлеты из курицы и овощей можно подать с любым соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3963,'Плитку шоколада разломать, добавить пальмовое масло, поставить на плиту (лучше на водяную баню) и довести, постоянно мешая, до образования жидкой консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3963,'В отдельной емкости смешать сахар, муку, соду и соль. Отдельно взбить яйца и ванилин, добавить остывшую смесь из шоколада. Варить яично-шоколадную смесь пока она не станет гуще, затем добавить сахар с мукой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3963,'Переложить в форму. Запекать приблизительно 20 минут. Достать домашнее пирожное на шоколаде из духовки и разрезать. По желанию можно полить глазурью или шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3964,'Измельчить печенье в крошку и перемешать с размягченным сливочным маслом, до образования сыпучей массы. Взять разъемную форму (диаметр 22 сантиметра), застелить пергаментом.  Уложить тесто в форму, распределить и утрамбовать. Выпекать в духовке около 12 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3964,'Взбивать миксером на небольшой скорости (чтобы не появились пузырьки воздуха) сливочный сыр, творог, ванильный сахар, сахар, сметану и яйца в течение 10-15 минут. Форму, с основой для чизкейка, завернуть в два слоя фольги и поставить ее в большую по объему другую форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3964,'Выложить на основу сливочную смесь. Большую форму заполнить водой на 2/3. Выпекать в духовке примерно час. Середина готового десерта будет подрагивать, поверхность должна остаться светлой. Выключить духовку и оставить его в духовке до совершенного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Сэндвич по-американски с беконом, томатами и салатом подать на большой подогретой тарелке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3964,'Потом поставить в холодильник не меньше, чем на 8 часов (лучше на ночь). Заливка: сметану с сахаром взбить, прибавить разведенный в горячей воде желатин. Выложить готовый сметанный крем на поверхность, разровнять. Дать настояться в холодильнике. Украсить белоснежный сливочный чизкейк по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3965,'Кабачки порезать на ломтики (примерно 1 сантиметр толщиной), чтобы было хоть немного похоже на порезанные грибы. Перемешать кабачки с черным перцем, солью, сахаром, подсолнечным маслом, петрушкой, укропом, уксусом и чесноком, оставить на 3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3965,'Когда пройдет время, уложить кабачки в подготовленные банки (стерилизованные). Затем банки пастеризовать в горячей воде из расчета полулитровая банка — 5 минут. Кабачки в маринаде «под грузди» закатать, перевернуть и охладить. Не укрывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3966,'На терке натереть масло из морозилки. Процесс приготовления теста лучше не затягивать – чем быстрее приготовить, тем более слоеным получится тесто. Даже можно натертое масло опять убрать ненадолго в морозилку (на пару минут). К маслу прибавить муку и щепотку соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3966,'Перемешивать необходимо ложкой, чтобы мука как будто обволакивала масло. Сделать углубление, вбить яйцо, добавить 2 столовые ложки ледяной воды и вымесить тесто (очень быстро). Вероятно, воды надо будет влить еще. Тесто обмотать пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3966,'Убрать в холодильник на полчаса (так получится вкуснее, но можно раскатать и сразу). Начинка: рыбу нарезать относительно крупно, брынзу нарезать кубиками, нарезать шпинат. Перемешать в кастрюле рыбу, шпинат, брынзу, прибавить сметану (3-4 столовых ложки с горкой), посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3966,'Тесто поделить на две неравные части: 2/3 и 1/3. Меньшую часть положить в холодильник, а большую раскатать и уложить в форму для запекания. Прикрыть фольгой, насыпать груз (например, горох) и поставить в духовку на 15 минут, затем груз снять и печь еще 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3966,'Выложить начинку на испеченный корж. Раскатать меньшую часть теста, накрыть ею начинку, проколоть вилкой, смазать яйцом и отправить песочный пирог с семгой и брынзой в духовку, на полтора часа',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3967,'Маргарин растопить, добавить сахар, соль и молоко, необходимо, чтобы смесь была теплой. Добавить дрожжи и муку, замесить тесто. Затем разделить тесто на 3 части и раскатать каждую в прямоугольник (примерно 35х20), муку не добавлять. Сформировать шарики из начинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3967,'Положить их вдоль длинного края теста. Скатать тесто в рулет и защипнуть по бокам. Затем ребром ладони как бы перепиливать тесто между начинками на кусочки (имитировать режущее движение). Получатся пирожки-подушечки, бока у них будут закрыты. Для того чтобы бока не расходились, не нужно класть много начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3967,'Если же бока немного разошлись, то тесто очень эластичное и это легко исправить – защипнуть края. Взять форму для выпечки, застелить бумагой, уложить в нее пирожки-подушечки, сверху смазать яйцом и присыпать кунжутом. Запекать пышные пирожки-подушечки примерно 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3968,'Взять большую емкость, на ее дно красиво выложить фрукты – это будет верх торта. Желе развести водой согласно инструкции на упаковке, немного подогреть. Воды лучше налить немного меньше, чтобы желе было плотнее.  Залить первый слой в емкость и отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3968,'Пока застывает первый слой, необходимо развести желе другого цвета. Когда первый слой застыл, достать торт из холодильника, уложить на него фрукты и залить второй слой. Отправить в холодильник. Аналогично поступить с третьим слоем желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3968,'Последним слоем торта будет сметанный. Смешать сметану с сахаром, развести в молоке пачку желатина, немного подогреть и добавить в сметану. Можно добавить немного ванилина или какао. Залить последний слой и отправить торт в холодильник до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3968,'Чтобы готовый, оригинальный торт-желе с фруктами переложить на блюдо, необходимо емкость с тортом опустить в горячую воду на несколько секунд и перевернуть на блюдо. Украсить можно мятой, цукатами, кусочками фруктов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3978,'Оставить еще на 36 часов, воду поменять лишь один раз (спустя 18 часов). Следующие два дня корки необходимо кипятить – один раз за день. После каждого кипячения корки заливать чистой холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3969,'Куриное филе сварить и охладить. Сварить вкрутую яйца. У помидора вырезать серединку и убрать жидкость, взять только стенки. Филе, яйца, перец и помидор измельчить кубиками, добавить соль, белый перец и заправить майонезом. Перемешать. Салат «Коралл» с курицей и крабовым мясом готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3970,'Размять сливочное масло, прибавить сахар (150 грамм), растереть. Смешать муку с какао и с сахарной смесью. Все хорошо растереть до рассыпчатого состояния. Уложить в форму бумагу для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3970,'Всыпать половину крошки, разровнять. Начинка: творог перетереть с оставшимся сахаром и ванилином, прибавить сметану и яйца. Взбивать блендером до однородности, добавить крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3970,'Вылить смесь из творога на шоколадную крошку, сверху высыпать вторую половину крошки. Печь нежный творожный «Торфяной» пирог около 45 минут в духовке. Готовый пирог остудить, нарезать кусочками и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Подсушить орехи в разогретой духовке, а потом измельчить. Лучше орешки нарубить не очень мелко и не очень крупно, а так, чтобы орехи ощущались в готовых коржах. Аккуратно отделить яичные белки от желтков. Белки необходимо взвесить и возможно пересчитать количество необходимой муки и сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Предоставленное число ингредиентов рассчитано на примерно 210 грамм белков. В отдельную емкость всыпать муку, добавить дробленые орехи, и положить 80 % всего количества сахара, перемешать. Белки с оставшимся количеством сахара взбить до устойчивых пиков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Необходимо использовать белки комнатной температуры, а в том случае, когда они из холодильника, то их лучше подогреть, опустив в емкость с теплой водой. Начать взбивать белки необходимо на низкой скорости миксера, когда появится белая пена – прибавить немного лимонного сока (несколько капель).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Затем увеличить скорость и взбивать до мягких пиков. Далее добавить сахар и взбивать уже до устойчивых пиков (сформированный на венчике пик не должен гнуться даже на верхушке). Но главное не перебить, так как перебитые белки будут хрупкими и тусклыми, а тесто, приготовленное из таких белков, с большей вероятностью опадет во время выпечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Во взбитые белки добавить муку и орехи, очень аккуратно, перемешивая снизу вверх. Тесто выложить на противень с пергаментной бумагой (можно использовать 2 круглые формы), разровнять, выпекать примерно 120-130 минут. Готовые коржи отставить и полностью охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Затем вынуть из формы и убрать бумагу. Готовые коржи необходимо оставить на решетке для подсушивания (12-24 часов). Держать только в сухом помещении, так как такое воздушное тесто не переносит влаги. Когда коржи подсохнуть, необходимо их подровнять (обрезать), обрезки перетереть в крошку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Крем: взбить слегка яйцо, добавить сахар, молоко, все смешать и отправить на слабый огонь и варить, пока не загустеет. Загустевший крем перелить в тарелочку, накрыть и отставить для охлаждения. Сливочное масло взбить с ванильным сахаром в пышную массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Для того чтобы результат получился хорошим, лучше взять масло примерно 20 градусов (немного холоднее комнатной температуры). Не переставая взбивать, ввести сахарно-молочную смесь, в конце ввести коньяк. Коржи соединить между собой толстым слоем крема. В оставшийся крем добавить какао-порошок и перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3971,'Этим кремом перемазать бока торта. Обсыпать измельченной крошкой от коржей. Обмазать вершину торта тоже шоколадным кремом, украсить по собственному желанию. Отправить торт «Киевский» с орехами и кремом шарлотт в холодильник примерно на час и можно подавать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3972,'Сметану и желтки перемешать, добавить мед, сахар, растительное масло и цедру апельсина. Хорошо перемешать, прибавить муку, немного соли, корицу и соду (загасить лимонным соком), далее всыпать цельнозерновую муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3972,'Вымесить не крутое тесто. Раскатать в пласт (1 сантиметр), стаканом вырезать коржики. Ножом (тупой стороной) сделать на них узор снежинка. С помощью кисточки каждый коржик смазать молоком, обмакнуть в сахар этой стороной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3978,'Затем положить корки в сладкий сахарный сироп на 4 суток. Затем его немного нагреть, достать корки, обвалять в сахаре, положить сахарные цукаты из апельсиновых корок на сито и высушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3972,'Выложить на противень и запекать приблизительно 15-17 минут (температура 200 градусов). Сначала 7 минут можно печь в духовке с обычным режимом, а остальное время при режиме конвекция. Готовые классические сахарные коржики переложить на плоскую тарелку и накрыть тканевым полотенцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3973,'У помидоров срезать вершины и достать мякоть. Отложить в сторону. Куриное филе отварить. В отдельной емкости перемешать нарезанные ингредиенты для салата. Отдельно взбить венчиком компоненты к соусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3973,'Добавить соус в салат и смешать. Помидоры выложить листьями шпината или салата, разложить ложкой салат в помидоры. Салат-коктейль в помидорах выложить на блюдо и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3974,'Грудку отделить от костей, очистить от шкурки (там больше всего жира). Почистить лук, чеснок, вымыть зелень. Отварить гречку до полуготовности и охладить. Перекрутить на мясорубке или в блендере грудку, лук и чеснок с зеленью. Смешать полученный фарш и гречку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3974,'Добавить яйцо, посолить и поперчить. Перемешать и отправить в холодильник примерно на 15-20 минут. Половину сыра нарезать кубиками в тефтели, а половину оставить для соуса. Сформировать тефтельку, внутрь положить кусочек сыра. Сделать тефтельки из  остального фарша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3974,'Затем уложить готовые тефтельки в смазанную маслом форму. Соус: перемешать оставшийся сыр, сливки, зелень, сметану и соль. Залить этим соусом тефтельки. Поставить тефтели из курицы и гречки в соусе в духовку примерно на 35 минут (200 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3975,'Перемешать все ингредиенты для теста, взбить миксером. Поделить тесто напополам и выпечь два коржа. Готовые коржи остудить и разрезать каждый вдоль на 2 части (станет 4 коржа).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3975,'Перекрутить через мясорубку чернослив, изюм и курагу (можно что-то одно). Миндаль мелко порубить. Крем: перемешать сметану с сахаром, хорошо взбить. Отставить ненадолго, чтобы сахар растворился и опять перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3975,'Чтобы было быстрее, можно взять сахарную пудру, вместо сахара, а также сметану пополам со сливками. Коржи (обязательно, чтобы были не холодные) смазать кремом, присыпать орехами и перекрученными сухофруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3975,'Потом смазать торт по бокам. Украсить. Ненадолго оставить в сторону, а затем убрать в холодильник. Дать торту настояться несколько часов (можно на ночь), чтобы пропитался. Классический «Медовик» с сухофруктами готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3976,'Разогреть духовку (190 градусов). Готовые блины уложить на блюдо, смазанное маслом. Сосиску порезать, выложить на блин, наверх разбить яйцо. С помощью зубочисток края скрепить так, чтобы получился квадрат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3976,'Выпекать яйца в духовке примерно 10 минут (яйца должны пропечься полностью). Затем каждое яйцо в блинном конвертике выложить на отдельную тарелку, украсить зеленым луком и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3977,'Вскипятить в кастрюле воду (250 мл). Когда вода начнет кипеть, положить сливочное масло и растворить его. Далее добавить туда же сахарный песок, соль (щепотку) и мешать пока все не растворится. Убрать емкость с огня и добавить муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3977,'Муку тщательно перемешать, лучше деревянной ложкой, немного охладить. Добавить по одному яйца, после каждого яйца массу хорошо перемешивать. На противень положить пергаментную бумагу и выложить тесто ложкой или с помощью кондитерского мешка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3977,'Эклеры необходимо укладывать на некоторой дистанции друг от друга. Отправить в духовку и печь, пока не зарумянятся. Крем: желтки с сахаром взбить до однородной консистенции, прибавить муку (40 грамм) и хорошо перемешать. Отдельно вскипятить ванильный сахар с молоком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3977,'В молоко положить крем и размешивать, пока консистенция не будет однородной. Дать крему остыть. Затем разрезать каждый эклер пополам до середины (лучше воспользоваться острым ножом) и положить в него ванильный крем. Домашние эклеры с ванильным кремом готовы к подаче.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3978,'Апельсиновые корки нарезать продолговатыми тонкими полосками и вымачивать в холодной воде приблизительно трое суток, воду необходимо менять три раза в день. По истечении 3 суток, залить корки водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4053,'Коржи обильно промазать кремом, так же смазать бока и верхушку. Торт на майонезе с банановым кремом можно украсить дольками банана и миндальными лепестками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3979,'Грудку куриную и яйца отварить. Курицу  нарезать кусочками, яйца натереть на терке (белок одного яйца отложить в сторону для украшения). Лук нашинковать и обжарить с нарезанными грибами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3979,'Все компоненты для салата уложить слоями на тарелку в форме ежика. Глазки и носик сделать из маслин, иголочки из корейской морковки, а мордочку присыпать тертым сыром. Гриб сформировать из яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3979,'Чтобы сделать шляпку, половинку белка вымочить в чайной заварке (белок приобретет коричневый оттенок). Вокруг ежика на тарелку притрусить зелень – измельченная петрушка или укроп. Оригинальный слоеный салат «Ежик» можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3980,'На крупной терке натереть кабачок, отжать. Выделившийся сок слить. Добавить лук, яйцо, муку (3-4 столовых ложки с горкой), прибавить соль, специи, смешать. Куриное филе мелко измельчить. Добавить чеснок, специи и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3980,'Разогреть растительное масло на сковородке (огонь небольшой). Сначала выложить на сковородку столовую ложку кабачка, затем чайную ложку фарша, сверху закрыть кабачками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3980,'Накрыть сковородку крышкой и поджаривать вначале с одной стороны на небольшом огне, затем перевернуть на другую. Можно подавать колдуны  из кабачка и курицы со сметаной или с любимым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Соком залить желатин и отставить разбухать (30-40 минут).  Затем подогреть сок в сотейнике или микроволновке, не доводить до кипения, пока желатин совсем не растворится. Охладить. Почистить манго, с косточки срезать мякоть и нарезать кубиками. Очистить апельсин от пленок и кожуры,  мякоть порезать дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Положить мякоть манго в блендер и взбить до консистенции однородного пюре. Затем добавить мякоть апельсина и немного взбить (измельчать не очень сильно). Фруктовое пюре перелить в глубокую чашу, добавить лимонный сок и растопленный желатин. Хорошо перемешать ложкой. Отставить пюре, чтобы загустело (немного).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Выложить половину подготовленного пюре в форму и отправить в холодильник для полного застывания. Перетереть яичные желтки с сахаром (чтобы стали белыми). Установить на водяную баню и взбивать, пока сахар полностью не растворится (лучше воспользоваться блендером с насадкой венчик), охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Взять маскарпоне (комнатной температуры), аккуратно ввести в него яичный крем, влить ликер. Масса должна получиться консистенцией, как густая сметана. Сливки взбить со сгущенкой в стойкую массу. Перемешать смесь с маскарпоне и смесь со сливками, взбить миксером (секунд 10-15).  Масса должна стать однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Отправить в холодильник, чтобы крем загустел. В отдельной емкости взбить яичные белки и щепотку соли до белой пены, добавить половину чайной ложки лимонного сока, продолжить взбивать до устойчивых пиков, понемногу добавлять ванильный сахар. Аккуратно добавить белки в сливочно-сырную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Перемешать лопаткой, снизу вверх. В застывшее фруктовое пюре  выложить половину крема, поставить на полчаса в морозилку. Выложить наверх оставшееся фруктовое пюре и поставить в морозилку еще минут на 10. Следующим слоем уложить оставшийся крем, разровнять лопаткой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3981,'Наверх выложить кружочки киви, прикрыть пищевой пленкой и поставить в морозилку не менее чем на 4 часа (можно и на ночь). За полчаса до употребления, поставить десерт семифредо «Под солнцем Сицилии» в холодильник, чтобы немного размягчился. При подаче украсить фруктами по собственному вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3982,'Растворить дрожжи и сахар в холодном молоке. Муку просеять в миску, прибавить соль, солод (можно и без него), затем всыпать в молоко с дрожжами и замесить тесто. Если использовать комбайн, то месить 10 минут, руками немного дольше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3982,'Тесто получается мягкое, не нужно забивать его мукой. Возможно,  понадобиться еще немного молока. Отставить тесто примерно на 40-45 минут для отдыха. Именно для отдыха, а не подъема. Затем тесто хорошо размять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3982,'Далее раскатать тесто в не очень тонкий пласт. От центра порезать пласт на треугольники. Начинка может быть любая: мак, повидло или сыр с колбасой, а можно сделать и вовсе без начинки. В данном случае для начинки смешаем мак и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6229,'Затем влить воду и отварить их до готовности, остудить, просушить и натереть солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3982,'Начинку положить на широкую часть теста и закрутить. Выложить круассаны на противень, сверху смазать желтком, взбитым с 1 ст.л. молока и запечь в духовке, до зарумянивания. Вынуть хрустящие круассаны с маком из духовки, переложить их на блюдо и можно подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3983,'Филе куриное промыть и нарезать небольшими кусочками. Мелко нашинковать лук и поджарить его в малом количестве растительного масла. После того, как лук станет прозрачным, добавить к нему курицу, посолить, поперчить и тушить (минут 5-7). Капусту помыть, тонко нашинковать и сложить отдельно в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3983,'Добавить перец и соль, немного майонеза – салат готов. Курицу переложить на отдельную тарелочку. Соус: взять пару небольших мисочек, в первую выдавить 5 столовых ложек кетчупа и насыпать чайную ложку приправы (можно хмели-сунели или любой любимой приправы), перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3983,'Во вторую налить 5 столовых ложек кефира, добавить 4 столовые ложки майонеза, два зубчика чеснока измельченного, перемешать. Сделать нарезку из овощей: порезать тонкими дольками огурец и помидор. Все подготовленные тарелочки поставить рядом на столе, чтобы удобно было брать при сборе шаурмы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3983,'Взять большую доску, уложить на нее половину листа лаваша, намазать сразу двумя соусами, ближе к правому краю выложить в ряд курицу (будет удобнее, если ее разделить уже на тарелке на 4 части). Возле курицы выложить в ряд капусту. Наверх капусты уложить помидоры и огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3983,'Сначала загнуть края лаваша по бокам от начинки, чтобы она не вытекала, а затем свернуть все рулетом. Сделать три оставшиеся шаурмы таким же способом. Растительное масло разогреть на сковородке и обжарить шаурму с курицей и свежей капустой с обеих сторон до золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3984,'Вначале нужно приготовить кисель, в соответствии с инструкцией на упаковке. Готовый кисель немного остудить. Замочить желатин в небольшом количестве воды и отставить, пока не набухнет. В чаше блендера взбить творог, сметану и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3984,'Готовую творожную массу перелить в кисель, добавить предварительно подогретый желатин и взбить. Распределить массу по креманкам и отправить творожный мусс на киселе в холодильник, пока полностью не остынет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3985,'Перемешать муку, щепотку соли и сахар. Взбить яйцо с молоком и влить к муке. Перемешать до однородной консистенции. Нагреть сковородку и столовой ложкой выложить тесто. Поджарить оладушки на молоке с обеих сторон. Кушать можно с вареньем (медом) или сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3986,'Перемешать все ингредиенты в большой емкости и взбивать блендером до однородной массы, продолжать взбивать, пока не загустеет. Мягкий шоколад готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3987,'Взять емкость, разбить в нее яйца, добавить сметану и сахар, взбивать венчиком. Растопить масло, размять вилкой бананы, порубить ножом грецкие орехи.  Добавить в тесто. Всыпать муку с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3987,'Перемешать и вылить тесто в форму для выпечки. Отправить  форму в духовку приблизительно на 40 минут (190 градусов). Достать пирог из духовки, остудить и разрезать вдоль, напополам, чтобы получилось два коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3987,'Аккуратно обрезать верхушку и бока коржей, обрезки мелко измельчить в блендере. Крем: размягченное сливочное масло взбить со сгущенкой. Смазать кремом коржи бананового торта с грецким орехом, а также верх и бока, притрусить крошкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3988,'Тесто: в емкость всыпать муку, сахар, соль, масло (порезанное на кусочки), перемешать. Добавить холодную воду и снова перемешать. Образовать из теста шар, обернуть его пленкой и положить в холодильник, не менее чем на час.  Начинка: нарезать яблоки маленькими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3988,'В сотейнике нагреть сливочное масло, добавить яблоки и тушить приблизительно 5 минут.  Добавить измельченную грушу, цедру лимона и сок, сахарную пудру. Тушить, постоянно мешая, приблизительно минут 10-15 или пока масса не станет полностью густой и мягкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3988,'Начинка должна немного остыть. Тесто поделить напополам, из одной части теста вырезать круги (стаканом), а вторую часть теста уложить на дно формы для запекания. Круги теста выложить по бокам, как бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4060,'Картофель отварить, почистить и измельчить с помощью терки. Лук нашинковать, обжарить, смешать с подготовленным картофелем, придавить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3988,'Выложить начинку на тесто, а круги завернуть в центр, таким образом, чтобы они немного закрывали начинку. Поставить яблочно-грушевый пирог «Нежность» в духовку на 45-50 минут (180 градусов). Перед подачей пирог остудить и притрусить сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3989,'Помыть чернослив и замочить его минут на 5 в горячей воде. Вынуть из воды, обсушить и разрезать каждый на четыре части. Взять креманки, на дно уложить слой чернослива (примерно полтора сантиметра), немного утрамбовать. Творог перемешать с ванильным и обычным сахаром, йогуртом и взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3989,'Готовую массу разложить поверх чернослива. Разломать шоколад на кусочки, добавить сливочное масло и установить на водяную баню. Растопить шоколад и охладить его до температуры 30 градусов. Творожную смесь в креманках полить шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3989,'Отставить креманки в сторону и дать немного застыть.  Миндаль положить в емкость, залить водой (кипятком), прикрыть крышкой и отставить минут на 10. Затем почистить, прожарить немного на сковородке и измельчить. Присыпать творожный десерт с шоколадом рубленым миндалем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3990,'Слоеное тесто разложить на столе и поделить на 6 частей (одинаковых). Каждый кусок теста смазать томатной пастой, затем присыпать сухими травами. Далее выложить на каждый кусок по одному большому кругу салями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3990,'Сверху выложить по две тонких пластинки сыра. Свернуть все в рулетики и уложить на противень. Перемешать яйцо с паприкой и смазать все рулетики сверху. Выпекать рулеты слоеные с салями и сыром примерно 20 минут (200 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3991,'Взять форму размером примерно 30х25 (противень). Муку, разрыхлитель и крахмал смешать и просеять. Взбивать яйца с горячей кипяченой водой примерно минуту. Добавить в воду сахар и взбивать еще 2-3 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3991,'Затем добавить смесь из муки и мешать на низких оборотах миксера или ложкой (не взбивать). Перелить тесто в форму и отправить в духовку минут на 10-12 (180 градусов). Приготовить крем. Взбить все ингредиенты в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3991,'Сначала взбивать масло, пока не станет пышной белой массой, затем добавить остальные ингредиенты. Развернуть на столе полотенце, притрусить сахарной пудрой и выложить на него готовый бисквит.  Убрать бумагу, свернуть вместе с полотенцем и остудить (минуты 2-3).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3991,'Раскрутить, намазать равномерно кремом по всей поверхности. Скрутить, присыпать  бисквитный рулет «Куршену» сахарной пудрой и украсить по собственному желанию. Поставить в холодильник на пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3992,'Грудку куриную порезать небольшими кусочками, опустить в кипящую воду (подсоленную) и варить минут 10-15. Нарезать картофель кубиками и положить в воду к курице.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3992,'Мелко порезать лук и морковь, немного их поджарить на сковородке с растительным маслом. Переложить поджарку в суп и варить снова минут 10-15.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3992,'Сырки добавлять в готовый суп (лучше порезать на куски) и мешать до полного растворения. Затем в ароматный суп с сыром и курицей добавить специи и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3993,'Белки отделить от желтков и взбить их до крепких пиков. В другой миске взбить желтки с сахаром (с сахарной пудрой получится быстрее). Добавить муку, можно взбить миксером на низкой скорости. Затем в смесь добавить белки и осторожно перемешать ложкой, снизу вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3993,'Выложить тесто малыми порциями на противень с помощью кондитерского мешка. Немного притрусить сахаром (можно и без него) и оставить на пару часов при комнатной температуре. Печь «Ленинградское» бисквитное печенье в духовке 10 минут (180 градусов). Печенье кушать с молоком или чаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3994,'Из воды, муки и соли вымесить тесто, дать постоять (минут 20). Картофель порезать, сложить в кастрюлю и залить водой. Отправить на огонь, посолить и варить до готовности. Порезать мелко грибы и лук. Обжаривать грибы 10 минут. Добавить к грибам лук и обжаривать до золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3994,'Из вареного картофеля приготовить пюре, перемешать с грибами и луком, посолить. Капусту нашинковать соломкой и тушить на растительном масле, на небольшом огне, до мягкости (минут 15-20). Посолить. Оторвать от теста кусок, сформировать с него жгут, поделить его на небольшие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6229,'Сначала грибы запанировать в муке, потом в яйце, и в конце в сухарях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3994,'Раскатать скалкой, уложить внутрь начинку и сформировать вареники. Отваривать вареники в подсоленной воде 4 минуты. Лук мелко порезать и поджарить на сковородке. Простые домашние вареники переложить в тарелку, присыпать жареным луком, перемешать и сразу подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3995,'Горох промыть, всыпать в кастрюлю, залить бульоном и посолить. Вскипятить на сильном огне, потом огонь уменьшить и варить, накрыв крышкой, 30-40 минут (станет мягким). Нарубить не очень мелко сельдерей, морковь и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3995,'Овощи тушить приблизительно 4-5 минут. Убрать с огня. Порезать кубиками ветчину и картофель. Примерно через 15 минут, как горох начал вариться, к нему положить картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3995,'За 5 минут до готовности, прибавить в кастрюлю ветчину и обжаренные овощи. Готовый гороховый суп с ветчиной по-домашнему присыпать зеленью, прикрыть крышкой и дать настояться 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3996,'Взять свиной окорок примерно 4 килограмма, убрать кость и поделить его на две части. Мясо промыть и высушить, лишний жир срезать. Приготовить смесь для маринада: измельчить лавровый лист, объединить его с солью, тимьяном и перцем, хорошо смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3996,'Натереть мясо смесью, завернуть его в пленку и отправить в холодильник на ночь. Взять рукав, уложить в него крупные куски лука, зубчики чеснока (целые), сверху уложить мясо, добавить немного душистого перца горошком и лавровый лист. Рукав завязать и поставить в духовку на 40 минут (180 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3996,'Сделать картофель по-деревенски, картофель и лук нарезать крупно, присыпать смесью специй, полить растительным маслом, хорошо помешать и запечь в духовке. В конце запекания посолить (лучше крупной солью). Вынуть мясо из духовки, разрезать рукав.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3996,'Выложить готовое мясо на огнеупорное блюдо или противень. Заполнить противень картофелем со всех сторон и поставить в духовку минут на 10 (200 градусов) до красивой румяной корочки. Вынуть запеченную в рукаве буженину с картофелем из духовки, дать немного остыть, нарезать порционно и подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3997,'Растопить на слабом огне масло в воде, затем добавить сахар. Варить смесь, пока сахар совсем не растает. В отдельной емкости перемешать сухое молоко и какао, чтобы не было комков (иначе изменится вкус конфет).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3997,'В сыпучую смесь влить жидкую и хорошо перемешать до однородной консистенции. Дать остыть, а потом отправить в морозилку на несколько часов до полного застывания. Затем массу достать, слепить из нее шарики и обсыпать какао. Домашние трюфели с какао можно подавать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3998,'Ветчину мелко порезать и немного поджарить. Сыр натереть и добавить к ветчине. Готовое тесто немного раскатать (толщина 3-4 миллиметра). Это не очень тонко, так как в процессе выпекания его объем сильно увеличится. Пласт порезать на треугольники, на широкую часть уложить немного начинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3998,'Скрутить пласты плотно рулетами и немного подкрутить края. Чтобы получилась золотистая корочка, необходимо намазать сверху яйцом. Запекать круассаны с сыром и ветчиной примерно 10-12 минут. Можно сразу подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'Готовое слоеное тесто выложить на присыпанный мукой стол (если заморожено, то немного подождать, пока размягчится). Если тесто в форме брикета, то его необходимо раскатать в тонкий пласт (4-5 миллиметров). Раскатанное тесто порезать на небольшие квадратики (примерно 2х3 сантиметра).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'На противень с пергаментной бумагой уложить квадратики теста так, чтобы они не соприкасались между собой, и запечь в духовке до золотистого оттенка (200-220 градусов). Достать из духовки, охладить до теплого состояния. Несколько квадратиков отложить для будущего украшения торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'Остальные квадратики положить в большую емкость и немного помять, чтобы примерно четверть объема рассыпалось на маленькие кусочки. Крем:  уложить в чашу сахар, муку, вареное сгущенное молоко, яйца, добавить молоко, взбить в однородную массу. Затем ее перелить в кастрюльку и поставить на медленный огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'Довести крем до кипения и варить, пока не загустеет. На вид получится, как густая манная каша. В еще горячий крем положить сливочное масло и перемешать для распределения масла равномерно по всей консистенции. Чтобы крем получился еще нежнее, то его можно взбивать миксером или блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'Горячий крем вылить в емкость с измельченными квадратами из теста. Очень тщательно перемешать. Форму взять лучше прямоугольную или квадратную, застелить ее фольгой или бумагой. Выложить массу из теста и крема и утрамбовать, чтобы не было воздушных просветов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (3999,'Охладить массу до комнатной температуры и отправить в холодильник. Квадраты, отложенные ранее, измельчить в крошку. Вынуть торт из формы, убрать фольгу (бумагу), обвалять его в крошках. Перед подачей к столу слоеный торт «Наполеон» на скорую руку аккуратно порезать на куски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Начинка: шоколад расплавить на водяной бане или в микроволновке. Сливочное масло взбивать миксером, небольшими частями добавляя шоколад. 200 грамм ягод черники взбить в пюре, 50 грамм оставить целыми. Добавить и пюре, и ягоды в шоколадную смесь. Перемешать, чтобы пюре и ягоды распределились по всему крему.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Macaroons: миндальную муку и сахарную пудру просеять сквозь сито несколько раз. Смесь пересыпать на противень с пергаментной бумагой и отправить в духовку минут на 5 (150 градусов). Вынуть из духовки и еще раз просеять в миску. Добавить половину белков, предварительно состарить (примерно 55 грамм).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Пока отставить в сторону. Взять небольшую кастрюльку, перемешать в ней сахар и воду. Вскипятить на медленном огне, постоянно мешать венчиком и проводить по стенкам кастрюли кисточкой, чтобы сахар не карамелизировался. Затем добавить красители и перемешать. Держать сироп на плите, пока смесь достигнет температуры 118 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Взбить до пышной пены оставшуюся часть белков. Снизить скорость и, взбивая, добавить сироп тонкой струйкой. Взбивать, пока масса не станет температурой 45 градусов (на ощупь будет немного теплой). Масса станет густой, гладкой и блестящей, но не должна дойти до состояния устойчивых пиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Белки, взбитые правильно, будут плотные, но мягкие, а кончик на венчике будет плавно изгибаться в птичий клюв. Аккуратно перемешать сухую смесь и белок (он потеряет свою структуру). Далее к ней добавить белки, взбитые с сиропом. Аккуратно перемешивать лопаткой, а другой рукой поворачивая емкость против часовой стрелки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Смесь должна быть однородной и плавно стекать с лопатки. Тесто переложить в кондитерский мешок. Выложить кружочки (диаметр 3-4 сантиметра) на противень с пергаментной бумагой. Если тесто замешано правильно, то хвостики от выдавленного теста сразу будут расходиться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Оставить противень постоять при комнатной температуре на 1 час. Это очень важно, так как вследствие этого на поверхности теста образуется тоненькая корочка.  Печенье не потрескается во время запекания, а внизу образуется «юбочка». Выпекать примерно 15-18 минут (160 градусов). Время выпекания будет зависеть от диаметра макарунов и мощности духовки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Вынуть готовое печенье из духовки, взять за края бумаги и осторожно перенести их на ровную поверхность, полностью охладить. Если все сделано правильно, то испеченные макаруны легко будут отделяться от бумаги. Если они отделяются плохо, а бумага остается липкой, то значит, они недодержаны в духовке. Сборка: начинку выложить в кондитерский мешок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4000,'Выдавить крем на одну половинку мakaroons, накрыть сверху другой половинкой, подходящей  по диаметру. Убрать классические черничные макаруны в холодильник (лучше на ночь). Макаруны никогда не едят свежими, а дают отдохнуть и пропитаться, тогда к утру и будет самая нежная и тающая структура, как у настоящих французских мakaroons.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4001,'Оливковое масло перемешать с водой. В отдельной большой емкости перемешать муку с солью, дрожжами и сахаром. В мучной смеси соорудить углубление и влить туда смесь с водой и оливковым маслом. Замесить не тугое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4001,'Отправить его на полчаса в теплое место. Когда подойдет, поделить тесто на две части, раскатать, выложить начинку по собственному вкусу и выпекать классическую пиццу по-домашнему в духовке, приблизительно 10 минут (250 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4002,'Взять свежих цыплят, надрезать посредине грудки вдоль цыпленка. Распластать цыпленка на доске кожей наверх и немного отбить молотком для мяса, чтобы придать цыпленку более плоскую форму. Это будет способствовать плотному прилеганию цыпленка к сковородке. Мясо равномерно обжарится, и станет более мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4002,'Маринад на основе вина и трав, все ингредиенты хорошо смешать. Цыплят уложить в пакет, облить маринадом и отставить часа на 2. Разогреть немного масла на сковородке, уложить цыпленка кожицей вниз. Сверху прикрыть тарелкой и поставить какой-либо гнет (может быть, кастрюлька с водой) и жарить минут 15 на небольшом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4002,'Когда сторона с кожицей станет золотистой – перевернуть и жарить снова 15 минут таким же образом (обязательно с грузом и на небольшом огне). Соус. Растереть в ступке морскую соль с чесноком и добавить сметану, перемешать. Подавать сочного цыпленка табака (тапака) можно с гарниром и соусом, а можно и без гарнира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4003,'Хорошо перемешать ингредиенты для теста, можно взбивать вручную, а можно миксером. Тесто получается жидковатое. Выливать тесто в форму частями, как на тонкие коржи (2-3 сантиметра). Выпекать каждый корж 15 минут (175 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4003,'Если использовать круглую форму диаметром 25 сантиметров, то получится примерно 8 коржей. Крем: вскипятить полтора стакана молока вместе с сахаром. Оставшееся молоко взбить с мукой, яйцом и осторожно добавить в кипящее молоко с сахаром. Убавить огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4003,'Варить приблизительно 7-8 минут пока не загустеет, постоянно помешивая. Снять с плиты и охладить. Потом добавить мягкое сливочное масло и тщательно взбить (лучше блендером). Смазать кремом все коржи, а также бока торта. Домашний торт «Ноченька» на кефире украсить по собственному желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4004,'Тыкву помыть, очистить и запечь в духовке до мягкости (180-200 градусов). Залить кипятком изюм и отставить на несколько минут, затем слить воду. Выложить изюм на полотенце или салфетку и высушить. Тыкву охладить и нарезать брусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4004,'Почистить апельсин, поделить его на дольки, их очистить от пленки и порезать напополам. Соус: в кастрюльку положить сахар, залить водой и на маленьком огне варить до полного растворения сахара. Затем добавить шоколад, разломанный на дольки, сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4004,'Варить, постоянно мешая, пока смесь не будет однородной консистенции. Добавить ванилин и сливки. На плоскую тарелку выложить апельсин и тыкву, сверху уложить изюм (можно также добавить чернослив или курагу), полить сладкий салат из апельсина и тыквы шоколадным соусом и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4005,'Перемешать все ингредиенты для теста: масло растопить, молоко подогреть. Оставить, чтобы подошло. Когда тесто подойдет, раскатать, не очень тонко. Разрезать его от центра на треугольники, скрутить рогалики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4005,'Уложить на противень и отставить немного, чтобы подошли. Желтки взбить с молоком и хорошо смазать рогалики со всех сторон. Обсыпать нежные рогалики на кефире кунжутом или маком и выпечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4006,'Все ингредиенты для маринада смешать и натереть им рыбное филе. Завернуть рыбу в тряпочку (холщовую) и отправить в холодильник на ночь. Утром семгу малосольную можно кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4007,'Яйца взбить со стаканом сахара. Далее прибавить щепотку соли, кефир (стакан), погашенную соду (1/2 ч.л). Всыпать приблизительно стакан муки, хорошо перемешать. Тесто получится не густое (чуть гуще, чем на оладьи). Форму намазать маслом, притрусить сухарями (можно манкой).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4007,'Влить тесто в форму и выложить сверху фрукты или ягоды (можно вишню без косточек, половинки абрикосов или киви). Печь около 15-20 минут. Затем вынуть заливной пирог с фруктами из духовки, немного охладить и притрусить сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4008,'Порезать отваренные яйца и помидоры. Сыр натереть на терке. Выложить на тарелку листья салата, сверху положить вареные креветки, яйца и помидоры, добавить лимонный сок и соль. Притрусить салат с креветками и перепелиным яйцом тертым сыром и подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4009,'Перемешать сметану (жирность 20 %), кефир (жирность 2,5) и 1 чайную ложку соли. Перелить в дуршлаг, поставить в холодильник под гнет на пару суток. По истечению времени нарезать свежего укропа, измельчить чеснок и щепотку соли, все смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4009,'Обвалять сыр в приготовленной смеси, сформировать сырный батон. А еще можно накатать шариков и залить их растопленным маслом с разнообразными специями. Домашний творожный сыр с укропом готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5828,'Нашинковать тонко лук, нарезать морковь, обжарить отдельно и добавить к свекле, перемешать, засыпать муку, потушить 5-7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4010,'Порезать кубиками картошку, положить в воду и поставить на плиту. Пока она варится, крупно порезать шампиньоны и обжарить их в смеси масел (сливочное и растительное) 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4010,'Порезать лук, натереть морковь, добавить к грибам и обжарить, но сильно не зажаривать. Добавить в воду к картошке лавровый лист и специи. Использовать любые макароны (только мелкие), добавить в воду, проварить 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4010,'Далее добавить зажарку с грибами. Дать покипеть еще минуту, вытащить лавровый лист и отключить огонь. Прикрыть крышкой и оставить ароматный грибной суп с вермишелью настояться. Перед подачей притрусить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4011,'Помидоры измельчить, поместить в отдельную посуду и залить 1/2 стакана воды. На хорошо разогретой сковороде обжарить нарезанный лук, присоединить измельченный чеснок и красный перец, все перемешать и добавить фарш. Листы лазаньи поломать на 2 – 3 части и выложить поверх фарша, когда тот приготовиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4011,'В сковороду влить соус и добавить нарезанные помидоры. Мясную лазанью в сковороде тушить на медленном огне в течение 20 минут, закрыв сковороду крышкой. По истечению отведенного времени, на готовую лазанью разложить рикотту и посыпать пармезаном. Перед подачей, блюдо присыпать рубленым базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4012,'В кастрюле прогреть масло, нашинкованный лук обжарить до золотистого цвета. Залить воду и довести до кипения, добавить лавровый лист. Картофель нарезать и положить в воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4012,'Рыбу порезать на кусочки и поместить к остальным ингредиентам, через 5 минут влить сливки. Крахмал развести и аккуратно ввести в суп, варить еще 8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4012,'Добавить сливочное масло и снять с огня. Перед подачей сливочный чаудер из лосося сдобрить лимонным соком, специями и солью, присыпать рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4013,'Для того чтобы замесить тесто необходимо, смешать муку и сахарную пудру, ввести желтки и масло, все посолить. Тесто раскатать, поместить в форму и сделать равномерные проколы вилкой, сформировать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4013,'Поверхность теста застелить пергаментом и насыпать на него груз (это может быть любая крупа, фасоль или горох). Форму поместить в духовку, разогретую до 190 градусов, выпекать в течение 20 минут. По истечению отведенного времени убрать груз и готовить еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4013,'Выпечку остудить и вынуть из формы, промазать конфитюром. Шоколад растопить, добавив сливки. Марципан раскатать, выложить на конфитюр и полить растопленным шоколадом. Апельсиновый мазурек с марципаном  украсить орехами и убрать на холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4014,'Картофель отварить и размять до состояния пюре. Добавить муку и сливочное масло, посолить по вкусу и замесить тесто, затем раскатать и поместить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4014,'Для приготовления начинки необходимо, нашинковать лук и перец, пассировать овощи. Фарш обжарить до готовности, присоединить овощи, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4014,'Начинку выложить в форму, сверху украсить дольками помидоров и тертым сыром. Готовить оригинальный пирог с мясом и овощами в течение 40 минут, при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4015,'Сливки подогреть и растопить в них мед. Яйца и сахар тщательно взбить. Просеять и перемешать все сухие ингредиенты, ввести теплые сливки, взбитые яйца и масло, все перемешать. Тесто поместить в форму и готовить при 170 градусах, в течение 25 минут. Бисквит остудить и вынуть из формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4015,'В сотейнике приготовить карамель, растопив масло и сахар, поместить в него яблоки, порезанные на дольки и корицу. Через пару минут ввести ром и мед, все потушить, снять с огня и остудить. Желатин замочить, как указано на упаковке. Сливки и сахарную пудру хорошо взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4015,'Небольшую часть сливок нагреть и смешать с желатином, полученную смесь присоединить к сливкам, все взбить. Бисквит положить в кулинарное кольцо или разъемную форму, выложить яблоки, полить соусом и уложить сливки. Торт «Медовое яблочко» со сливками поместить на холод на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4016,'Желтки отделить от белков. Все ингредиенты, кроме белков поместить в миску и пробить до однородной консистенции при помощи блендера. Белки охладить и взбить с добавлением сахара до пиков. Аккуратными движениями ввести белки в творожную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Украсить блюдо маслинами и чипсами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4016,'Полученную смесь поместить в форму, готовить в течение 50 минут, при 180 градусах. По истечению отведенного времени, творожный  пудинг с ванилью остудить, не вынимая из духовки. Перед подачей украсить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4017,'Развести тесто и испечь блины. Готовые, остывшие блины промазать сыром, сверху поместить кусочки лосося и ветчины. Скрутить рулет, обернуть пленкой и охладить. Перед подачей блинные рулетики с сыром филадельфия нарезать на ролы и скрепить зубочистками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4018,'Смешать сахарный песок и пюре, присоединить ванильный сахар. Агар-агар замочить в воде, затем нагреть и растворить, всыпать сахар (500 г), поварить на слабом огне до загустения сиропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4018,'1/2 белка ввести в пюре, взбить блендером, когда масса станет немного светлее ввести остатки белка и взбивать до пышности. Аккуратно смешать сахарный сироп и подготовленное пюре – все взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4018,'Получившуюся массу поместить в кондитерский мешок и быстро отсадить на поднос, застеленный пекарской бумагой. Мягкий яблочный зефир сушить при комнатной температуре в течение суток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4019,'Целый апельсин поместить в кастрюлю с водой, довести до кипения и поварить в течение 5 минут, затем остудить. Разрезать на несколько частей и пробить в блендере до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4019,'Яйца и сахарный песок взбить, ввести предварительно смешанные и просеянные сухие компоненты, добавить подготовленное пюре. Изюм промыть, просушить и присоединить к тесту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4019,'Затем его поместить в форму и готовить на протяжении 45 минут, в духовке, разогретой до 180 градусов. Перед подачей, традиционный апельсиновый кекс остудить и присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4020,'Масло и сахар перетереть до состояния крошки, присоединить сметану, все ингредиенты тщательно взбить. Получившуюся смесь поделить на равные части. В одну половину ввести просеянные сухие компоненты и замесить тесто. Поместить его в форму, готовить при 180 градусах, на протяжении 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4020,'По истечению отведенного времени корж остудить и разрезать на 3 части.  В другую половину вмешать ванилин, получившимся кремом промазать коржи, верхний присыпать тертым шоколадом. Домашний торт «Ростовский» на несколько часов поместить на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4021,'Яйца и сгущенное молоко взбить. Сухие составляющие смешать, просеять, ввести в яичную смесь, замесить тесто. При помощи скалки, на присыпанной мукой поверхности, тесто раскатать и с помощью формочек вырезать кружочки. Обжарить быстрые пышки в растительном масле до румяной корочки. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4022,'Сахарный песок, цедру и масло взбить при помощи блендера. Поочередно вести яйца, просеянные муку и ванилин, замесить тесто. Яблоки порезать на дольки, сбрызнуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4022,'Тесто поместить в форму, сверху положить яблоки, присыпать их корицей и сахарной пудрой. Выпекать в течение 40 минут, при 200 градусах. Яблочный пирог с лимоном и корицей остудить и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4023,'Кабачок порезать кружками, помидоры пополам, а шампиньоны на кусочки, сыр измельчить с помощью терки. Кабачки обжарить с 2 сторон, грибы также обжарить и немного потушить. Подготовленные компоненты поместить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4023,'Выложить затем  помидоры, приправить солью и специями. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4024,'Тушки кальмаров почистить, отрезать плавники, а затем их мелко нарезать. Для начинки необходимо, порезать отваренные вкрутую куриные яйца. Грибы, порезанные дольками обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4024,'Лук и морковь нашинковать, сыр измельчить с помощью терки. Смешать все составляющие, добавить плавники, по вкусу присолить и поперчить. Получившейся смесью начинить тушки кальмаров и уложить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4024,'Готовить кальмары в течение 15 минут, при 180 градусов. За несколько минут до готовности посыпать кальмары тертым сыром. Кальмары с грибами, запеченные под сыром выложить на блюдо и подать к столу горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4025,'Картофель, одинакового размера очистить от кожуры и хорошо промыть. Воду вскипятить, опустить в нее подготовленный картофель и варить в течение 5 минут. Затем, клубни достать, дать стечь воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4060,'Обжарить до образования корочки. Затем перевернуть на другую сторону и так же обжарить. Бабка из отварного картофеля должна иметь золотистую корочку с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4025,'В сковороде разогреть оливковое масло, в нем растопить сливочное, обжарить ароматный картофель «Шато» с каждой стороны до золотистого цвета, соль и перец добавить по вкусу. При подаче присыпать картофель свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4026,'Сыр и куриное филе нарезать на небольшие кубики, добавить мелко нашинкованный лук, все ингредиенты поместить в миску. Добавить крахмал, соль и специи по вкусу, влить кефир, присоединить рубленую зелень, замесить фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4026,'Сформировать котлетки и обжарить на разогретой сковороде до образования золотистой корочки. Сочные котлеты «Нежность» можно подавать с любым гарниром. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4027,'Желтки отделить от белков. Белки хорошо взбить в стойкую пену. В жаропрочной посуде растопить шоколад с добавлением молока, присоединить масло и тоже его растопить. Затем ввести желтки, сахар и просеянную муку, все хорошо вымесить и снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4027,'В заготовку аккуратно ввести взбитые белки. Тесто поместить в форму и готовить на протяжении 30 минут, при 180 градусах. Жирные сливки разогреть, поместить в них шоколад и растопить, постоянно помешивая венчиком. Остудить. Мягкое сливочное масло перетереть с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4027,'Остывший растопленный шоколад взбить. Когда масса увеличится в размере, ввести масленую смесь. Все тщательно взбить, мелкими порциями добавляя шампанское. Готовым кремом промазать коржи, торт украсить на свой вкус. Торт «le chocolat» с темным шоколадом готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4028,'Банан очистить от кожуры, разрезать на дольки и размять с помощью вилки до состояния пюре. Присоединить яйцо, сухое молоко и влить сок. Все ингредиенты взбить в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4028,'Кусочки хлеба обмакнуть в получившейся кляр. Обжарить банановые гренки до золотистой корочки на разогретой сковороде, с добавлением масла. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4029,'Жирные сливки взбить с добавлением сахарной пудры в стойкую пену. Промазать корж и уложить безе, следующий корж обильно промазать сливками и уложить безе. Последний корж, также промазать сливками. Смазать сливками бока торта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4029,'Шоколад разделить на дольки и украсить ими края, обвязать ленточкой.  Вафельными палочками разделить верхушку торта на несколько частей и заполнить каждую часть подготовленными драже Skittles. Оригинальный торт «Быстрый и вкусный» готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4030,'Тщательно взбить яйца и сахар, добавить корицу и просеянную муку. Яблоки помыть, удалить сердцевину и порезать на дольки. Уложить их в форму, сверху покрошить масло и залить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4030,'Выпекать пирог на протяжении 40 минут, при 180 градусах. Готовую шарлотку с кислыми зелеными яблоками припорошить сахарной пудрой и нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4031,'Белки и желтки разделить. Белки взбить до образования пышной пены. В отдельной миске взбить желтки и сахар, влить кефир и растительное масло, добавить ванилин. Компоненты перемешать, присоединить просеянную муку и разрыхлитель, вымесить тесто и аккуратно, небольшими порциями присоединить взбитый белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4031,'В другой посуде смешать сахарный песок, корицу, соль, добавить муку и присоединить мелко нарезанное холодное масло. Все ингредиенты размять руками до состояния крошки. На дно формы поместить половину заготовленного теста, сверху выложить порезанные бананы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4031,'Присыпать бананы частью масленой крошки, залить остатками теста и посыпать оставшимися крошками. Готовить пирог на протяжении 60 минут в разогретом духовом шкафу. Готовность проверить шпажкой. После выпекания банановый бразильский пирог остудить в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4032,'Для того чтобы приготовить тесто нужно смешать масло, творожный сыр и муку, эти ингредиенты перемешивать с помощью блендера до образования крошки. Затем смесь посолить по вкусу и влить воду, замесить тесто и убрать его на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4032,'Для приготовления начинки необходимо, нашинковать лук и измельчить грибы, все пассировать в сотейнике, присоединить мелко нарезанное куриное филе, посолить и поперчить. Сотейник убрать с огня, добавить измельченный сыр, все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4039,'Слоеное тесто заранее разморозить, раскатать. На середину уложить подготовленную начинку (яблоко, нарезанное на кусочки и присыпанное сахаром и корицей). Накрыть одной половиной. Смазать яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4032,'Для приготовления соуса потребуется растопить масло, смешать его с мукой, аккуратно ввести молоко, добавить соль, перец и мускатный орех. Тесто разделить на части, одну раскатать до размера формы, проколоть вилкой, уложить начинку, полить соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4032,'Из второй части теста нарезать полоски, с помощью которых сделать крышку – решетку, смазать яйцом и присыпать кунжутом. Выпекать пирог на протяжении 45 минут, при 180 градусов. Сырный пирог с курицей и грибами остудить в форме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4033,'Яйца и сахар взбить, смешать с протертым творогом, мукой и кокосовой стружкой. Все ингредиенты тщательно перемешать, сформировать шарики и уложить в форму. Нарубленный шоколад растопить в теплом молоке, желтки и белки разделить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4033,'Желтки взбить с сахаром и ввести в растопленный шоколад. Присоединить сухие компоненты (они должны быть заранее перемешаны и просеяны), замесить тесто. Белки взбить до образования пиков и аккуратно ввести в тесто. Получившимся тестом равномерно залить подготовленные творожные шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4033,'Пирог выпекать при 180 градусах, на протяжении 35 минут (готовность проверить шпажкой). Для приготовления глазури необходимо, растопить шоколад и смешать со сливками, маслом и медом. Остывший  пирог, с творожными шариками и шоколадом, извлечь из формы и полить глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4034,'Яйца отварить вкрутую. Все продукты порезать кубиками. Уложить слоями курицу, на нее выдавить чеснок, затем кукуруза, помидоры, яйца и тертый сыр. Каждый слой промазать небольшим количеством майонеза. Быстрый салат «Восторг» с копченой курицей украсить и подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4035,'Фарш приправить специями и солью, сформировать фрикадельки и обжарить их до золотой корочки, присоединить нашинкованный лук и чеснок, все готовить в течение 6 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4035,'Морковь измельчить и пассировать на отдельной сковороде. Все подготовленные ингредиенты поместить в кастрюлю, залить заранее сваренным бульоном, добавить томаты. При необходимости добавить соль и специи по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4035,'Варить на протяжении 40 минут, затем добавить пасту и варить до готовности. Готовый суп разлить по жаропрочным супницам, присыпать натертым сыром и отправить в хорошо разогретую духовку на 10 минут. Перед подачей, лазанья суп с пряными травами украсить базиликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4036,'Сахар и масло перетереть, по одному ввести яйца, все хорошо перемешать. В полученную смесь добавить шоколадные чипсы и ванилин. Затем, присоединить заранее смешанные и просеянные сухие компоненты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4036,'Замесить тесто. Формочки промазать маслом и заполнить их тестом на 2/3. Выпекать в течение 25 минут, в разогретом духовом шкафу. Ванильные маффины с шоколадными чипсами  немного студить и подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4037,'Для приготовления начинки необходимо, луковицу нашинковать на полукольца, а грибы дольками. Компоненты обжарить на разных сковородках и смешать в миске. Приправить солью и специями, присоединить зелень. Рыбу почистить и выпотрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4037,'Нафаршировать ее подготовленной начинкой, брюшко скрепить шпажками, сделать надрезы, в них поместить дольки лимона. Запекать рыбу в духовке в течение 25 минут. Карп, запеченный с лимоном и грибами готов. Рыбу выложить на блюдо и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4038,'Для того чтобы приготовить заварное тесто необходимо, нагреть молоко и растопить в нем масло, присоединить заранее просеянную муку, посолить. Все ингредиенты перемешать, убрать с огня и поочередно ввести яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4038,'Заготовку хорошо пробить с помощью блендера. Готовое тесто с помощью обычной ложки, или используя кондитерский мешок отсадить на противень, промазанный маслом или застеленный пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4038,'Выпекать эклеры при 180 градусах, в течение 20 – 25 минут. Для приготовления крема необходимо, смешать все подготовленные компоненты до однородной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4038,'Миску с заготовкой поместить в микроволновую печь и на максимальной мощности разогревать 5 минут. Каждую минуту крем тщательно взбивать. Остывшие эклеры начинить кремом и полить растопленным шоколадом. Заварные эклеры со сливочным кремом можно подавать к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6113,'Смешать соевый соус, лимонный сок и джем, отдельно перемешать перец, сушеный чеснок, соль и тимьян, чеснок нарезать тонкими пластиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4039,'Затем накрыть другой половинкой и так же смазать яйцом. В качестве украшения, на заготовке можно сделать надрезы. Выпекать при 180 градусах, в течение 25 минут. «Ленивый» штрудель с яблоком и корицей остудить и присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4040,'С помощью мясорубки перемолоть куриное филе, очищенную картофелину и луковицу. Получившейся фарш сдобрить солью и специями, вбить яйцо и все хорошо перемешать. Каннеллони нафаршировать и уложить форму. Сверху положить круглые дольки помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4040,'Обильно смазать их майонезом и насыпать тертый сыр и нашинкованную зелень. В форму налить немного бульона или воды. Запекать каннеллони, фаршированные куриной грудкой, в разогретой духовке при температуре 150 градусов, на протяжении 30 – 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4041,'Творог перетереть через сито. Белки и желтки разделить, последние взбить с добавлением сгущенного молока и ванильного сахара, затем присоединить творог. Отдельно взбить белки, добавив соль и лимонную кислоту. Взбивать до устойчивых пиков. Взбитые белки аккуратно перемешать с творожной массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4041,'Чашу мультиварки промазать маслом и поместить в нее заготовку. Установить программу Выпечка на 40 минут. Выпекать запеканку до готовности. Затем остудить, не вынимая из мультиварки. Простую запеканку из творога нарезать кусочками и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4042,'Воду залить в жаропрочную емкость, довести до кипения, поместить в нее масло. Когда масло растает, ввести муку, хорошо перемешивая венчиком. Затем, поочередно ввести яйца, все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4042,'Получившееся тесто, с помощью ложки или кондитерского мешка отсадить на противень, устланный пергаментом. Готовить профитроли в течение 15 минут, при температуре 220 градусов, затем жар убавить до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4042,'Выпекать на протяжении еще 25 минут. Для приготовления крема необходимо, взбить размягченное масло, сгущенное молоко и сахарную пудру, присоединить ваниль и пп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4042,'В крем вмешать протертый творог, все компоненты тщательно взбить. Профитроли разрезать и начинить кремом. Все компоненты очень хорошо взбить и остудить. Припорошить профитроли с творожным кремом сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4043,'В миске смешать сахарный песок, соль и кефир, добавить тертый сыр, присоединить муку и соду, замесить тесто. Подготовленные для начинки компоненты измельчить, добавить соль, специи и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4043,'Тесто разделить на несколько частей, каждую часть раскатать, в середину положить начинку, соединить края и снова раскатать. Обжарить сырные лепешки  на разогретой сковороде, промазанной маслом, до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4044,'Смешать сахарный песок, ванильный сахар и соль, перетереть с мягким маслом. Сметану и соду, гашенную соком лимона присоединить к масленой смеси, затем ввести просеянную муку и замесить тесто. Готовое тесто накрыть пленкой и убрать на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4044,'Через некоторое время его раскатать и нарезать ромбами. Заготовки уложить на противень, застеленный пергаментом и присыпать смесью сахара и корицы. Выпекать традиционное печенье «Земелах» в разогретой духовке, на протяжении 15 минут, при 200 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4045,'Для того чтобы приготовить опару необходимо, нагреть молоко и ввести в него сахарный песок, немного муки и дрожжи. Миску убрать в тепло на некоторое время. Сахар и мягкое масло взбить. Присоединить яйца, цедру и заранее перетертый творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4045,'Сдобрить смесь солью и смешать все компоненты.  Ввести муку и готовую опару, замесить тесто и убрать его на 1 час в тепло. Готовое тесто поделить на равные части и сформировать булочки, поместить их на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4045,'Дать булочкам постоять под полотенцем в течение 20 минут. Творожные булочки с лимоном промазать желтком, готовить в разогретой духовке на протяжении 30 минут, до золотой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4046,'Все сухие компоненты поместить в отдельную миску и перемешать. Яйцо и воду взбить, соединить со смесью, ввести масло и цедру, вымесить тесто. Готовое тесто оставить на пару часов, накрыв материей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4046,'Для приготовления крема: в молоко поместить цедру (срезанную лентой), крахмал, ваниль и сахарный песок, ввести желтки. Все ингредиенты тщательно перемешать и поставить на огонь. Крем немного проварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4046,'Добавить в крем масло, орехи и лимонный сок, все перемешать. Тесто поделить на равные части,  и каждую из частей раскатать, сверху положить ложку крема, залепить края, из оставшегося теста нарезать полоски и уложить их сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4046,'Таким образом сформировать все булочки. Уложить их на противень, через полчаса заготовки промазать яйцом и готовить в течение 15 минут, при 180 градусах. Перед подачей сдобные булочки «Крем-де-Паризьен» остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4047,'Лук и чеснок нашинковать и обжарить. Картофель отварить и натереть на терке. Остальные продукты измельчить, все подготовленные ингредиенты смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4047,'Получившуюся смесь поместить на булочку, вбить сырое яйцо и запекать на протяжении 15 минут. Простые бутерброды к завтраку готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4048,'Сухие компоненты смешать, добавить яйца и холодную воду. У яблок удалить сердцевину и очистить кожицу, затем нарезать кольцами и сбрызнуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4048,'Каждую дольку опустить в кляр, обжарить до золотистой корочки в разогретом масле. Хрустящие яблочные кольца в кляре перед подачей присыпать мускатным орехом. Подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4049,'Лук нашинковать, добавить в фарш, приправить солью и специями, перемешать. Картофель отварить и растолочь, соединить с мукой, маслом и яйцами, все перемешать. Получившуюся массу поместить в форму, промазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4049,'Равномерно распределить и сформировать бортики. Уложить начинку. Залить смесью из майонеза и яйца, присыпать сыром. Выпекать мясной пирог с сыром при 180 градусах до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4050,'Куриные сердечки промыть и почистить, немного обжарить и разложить по горшочкам. Картофель почистить и нарезать на кусочки. Обжарить нашинкованный лук, морковь и шампиньоны, присоединить к сердечкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4050,'Добавить подготовленный картофель. В миску вылить сливки, добавить по вкусу соль и специи, вмешать крахмал, получившуюся смесь разлить по горшочкам. Сыр натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4050,'Посыпать им блюдо и готовить под закрытой крышкой на протяжении 30 минут, при 180 градусах. За 5 минут до готовности крышку снять. Жаркое из сердечек с шампиньонами в горшочке готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4051,'Яйца, муку и майонез смешать, тесто вылить на противень. Компоненты, подготовленные для начинки измельчить и уложить на заготовку, присыпать тертым сыром. Готовить быструю пиццу в хорошо разогретой духовке в течение 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4052,'На рабочую поверхность высыпать муку, в центре сделать углубление, в него вбить яйца и добавить соль, замесить тесто. Для достижения нужной консистенции теста можно добавить немного воды, в итоге оно должно получиться крутым. Готовое тесто накрыть и оставить на некоторое время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4052,'Затем, разрезать на 3 равные части и раскатать в тонкие пласты. Для приготовления начинки необходимо, пассировать нашинкованные лук и чеснок. Присоединить заранее измельченную морковь и сельдерей, готовить в течение 5 минут. Добавить порезанную ветчину и фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4052,'Тушить до золотистого цвета. Ввести вино, проварить 10 минут, добавить томатный соус, готовить на протяжении 1.5 часов. Для приготовления соуса необходимо, в сотейнике обжарить муку до золотистого цвета с добавлением сливочного масла. Молоко довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4052,'В него поместить лавровый лист и мускатный орех. Когда молоко настоится, влить его тонкой струйкой в муку, при этом тщательно перемешивая венчиком, чтобы избежать образования комочков. Соус посолить, довести до кипения, убрать с огня. В форму, с высокими бортами положить фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4052,'Накрыть его одним пластом теста, затем опять положить фарш, полить его соусом и присыпать сыром, затем, снова положить тесто, фарш, соус, сыр. Уложить последний слой теста, полить его соусом и посыпать сыром. Готовить ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4053,'Яйца и сахарный песок тщательно взбить, присоединить сгущенное молоко и майонез, ввести смесь из муки и разрыхлителя. Из получившегося теста испечь несколько коржей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4053,'Готовить их следует в духовом шкафу, при 170 градусах, в течение 15 минут. Коржи остудить. Масло и сгущенное молоко хорошо взбить, в заготовку положить заранее измельченные бананы, все взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6229,'На сливочном масле обжарить грибы со всех сторон до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4054,'Муку высыпать на рабочую поверхность, сверху положить нарезанный кусочками маргарин. С помощью ножа порубить компоненты до образования крошки. Затем все крошки собрать и сделать в центре кратер, в который поместить яйцо и сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4054,'Замесить тесто, скатать его в шар и убрать на холод. Через некоторое время тесто разделить на 10 частей, каждую из которых раскатать и испечь при температуре 200 градусов в течение 7 минут. Масло, сгущенное молоко хорошо взбить. Остывшие коржи промазать кремом и уложить друг на друга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4054,'Коржи в центре смазать вареньем, на верхний корж положить груз (книги, емкость с водой и т.д.) на 8 часов. По истечению указанного времени груз снять, края торта подровнять. Промазать кремом бока и верхушку. Обрезки измельчить до состояния крошки и обсыпать торт. Торт домашний «Степка-растрепка» готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4055,'В кефир добавить соду, хорошо перемешать и присоединить остальные подготовленные продукты, замесить тесто, затем завернуть его в пленку и оставить на 40 минут. Подготовить начинку, нашинковать зелень, чеснок и смешать с тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4055,'Для второго варианта начинки можно смешать картофельное пюре, тертый сыр и зелень. Тесто размять и разделить на кусочки. Каждую часть раскатать, в центр поместить ту или иную начинку, края теста собрать сверху. Сформировать мешочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4055,'С помощью скалки аккуратно раскатать лепешку. Таким образом начинить и раскатать все кусочки теста. Готовые лепешки проколоть вилкой и обжарить на сухой сковороде по 5 минут с каждой стороны. Домашние хычины с разными начинками можно кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4056,'Яйца и сахарный песок соединить в миске, затем все тщательно взбить, присоединить остальные ингредиенты, подготовленные для теста. Все перемешать, получившееся тесто разделить на две равные части, в одну добавить какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4056,'Жаропрочную форму промазать маслом, тесто вливать поочередно, не большими порциями, в середину, сначала шоколадное, затем тесто без добавок. Выпекать сметанный торт «Зебра» при 200 градусах, в течение 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4057,'Готовое слоеное тесто заранее разморозить, затем раскатать и разрезать на квадраты под размер подготовленных формочек. Тесто поместить в формочки, придавить и прокатать скалкой по краям.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4057,'Обрезать излишки теста и вилкой сделать проколы. В миске смешать все ингредиенты, приготовленные для начинки кроме помидор, их следует порезать кружками. Начинку поместить в форму. Сверху уложить дольки помидор.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4057,'Приправить солью и перцем, сбрызнуть оливковым маслом. Слоеные корзиночки с томатами и рикоттой выпекать в разогретой духовке, на протяжении 20 минут. Выпечку остудить, достать из формочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4058,'Молоко подогреть, растворить в нем кофе и какао. Яйца и сахар взбить, присоединить к смеси мягкое масло, опять взбить. Соединить молоко и яичную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4058,'Ввести просеянную муку и разрыхлитель. Все перемешать, в тесто добавить измельченные орехи. Выпекать кофейно-шоколадный кекс в жаропрочной форме, в течение 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4059,'Дрожжи и сахарный песок поместить в теплую воду и оставить на некоторое время. В посуде соединить соль и муку, добавить дрожжи и масло. Затем порционно присоединить цельнозерновую муку и замесить домашнее дрожжевое тесто для пиццы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4059,'Готовое тесто убрать в тепло на 20 минут, прикрыв полотенцем. Тесто раскатать, поместить на него заранее подготовленную начинку. Пиццу выпекать в течение 15 минут, при температуре 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Для абрикосового мусса закипятить сок с мякотью, всыпать манку, размешать, проварить 10 минут, можно добавить по вкусу сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Дать остыть, взбить блендером, вылить на корж в форме, накрыть другой частью бисквита, слегка прижать, убрать в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Приготовить шоколадный крем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Пару стаканов сока абрикоса довести до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Частями, помешивая, всыпать манку, проварить 10 минут, дать чуть остыть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Добавить, поломанный на кусочки шоколад, влить сок апельсина, добавить цедру из половины плода, перемешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Дать остыть, взбить в блендере.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Залить шоколадным кремом верх второго коржа.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4061,'Слоеное тесто раскатать и разрезать на 2 части. Для первого вида начинки потушить капусту, добавить к ней яйца, для второго вида – обжарить фарш, с добавлением лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4061,'На каждую часть уложить начинку, соединить края и поместить в форму, выкладывая улиткой. Смазать желтком, готовить при 180 градусах, в течение 30 минут. Быстрый слоеный пирог-улитка готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4062,'Все компоненты поместить в миску и смешать до однородной консистенции. К готовому тесту присоединить любые ягоды, все тщательно перемешать. Чашу мультиварки промазать маслом, вылить в нее тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4062,'Установить программу «Выпечка» на 1 час 20 минут, готовить до окончания программы. Нежный пирог на кефире остудить не вынимая из мультиварки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4063,'В сотейнике смешать сахарный песок, воду и ваниль. Смесь нагреть и варить до полного растворения сахара, присоединить лимонный сок, готовить еще 5 минут, затем снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4063,'Орехи измельчить с помощью блендера. Несколько листов теста фило промазать растопленным маслом, уложить ореховую смесь и скрутить в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4063,'Таким образом начинить все листы теста, заготовки уложить на противень и промазать маслом. Готовить в течение 30 минут. После приготовления восточную пахлаву с орехами полить сахарным сиропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4064,'Стейк сдобрить солью, промазать васаби и обильно панировать кунжутом. Рыбу обжарить на хорошо разогретой сковороде, с добавлением масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4064,'Рисовую лапшу сварить в воде до готовности. Чеснок и имбирь измельчить, обжарить на сковороде, присоединить лапшу, все вместе обжарить. Ввести лимонный сок и соевый соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4064,'Зеленый лук нашинковать добавить к лапше. Перед подачей рыбу нарезать на кусочки и выложить на блюдо к лапше. Тунец с лапшой по-японски готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4065,'У картофелины срезать крышку, с помощью ложки удалить мякоть. В лодочку положить часть масла, немного тертого сыра, бекон и нашинкованный лук, залить яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4065,'Подготовленную зелень измельчить и посыпать ей картофелину, присыпать сыром. Таким образом начинить все картофелины. Запекать закусочный картофель с беконом в течение 25 минут, при 175 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4066,'Фарш приправить солью и специями, слепить из него шарики, затем сформировать лепешки, каждую обвалять в муке и обжарить до появления корочки. Сочные куриные котлеты на сковороде готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4067,'Сыр измельчить с помощью терки, смешать с мягким маслом. Присоединить остальные компоненты и замесить тесто, которое, в последствие, необходимо завернуть в пленку и убрать на холод на некоторое время. Тесто раскатать, нарезать равные, тонкие (приблизительно 2 см в ширину) полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4067,'Каждую полоску намотать на карандаш, затем аккуратно снять и заготовку положить на противень, устланный пергаментом. Таким образом сформировать все завитки. Выпекать сырные завитки к супу в течение 15 минут, в разогретом духовом шкафу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4068,'Заранее, молоко нагреть и смешать с дрожжами. В миску поместить сахарный песок, куриные яйца и кефир. Присоединить растопленное масло, молоко с дрожжами, приправить солью. Перемешать все компоненты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4068,'Порционно ввести муку, замесить тесто. Затем его убрать в тепло для расстойки. Орехи, корицу и сахарный песок перемешать. В отдельной посуде соединить мед и масло, перемешать. Готовое тесто разделить на равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4068,'Обе части раскатать, одну промазать смесью масла и меда, присыпать смесью орехов и корицы, накрыть второй. В середину поместить фужер, заготовку разрезать на 10 – 12 частей, каждую закрутить. Готовить в течение 20 минут, при 170 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4068,'Перед выпечкой дать пирогу отдохнуть. Для приготовления глазури, необходимо, смешать сахарную пудру, молоко и ванилин. Готовый болгарский пирог с  грецким орехом покрыть глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4069,'Все компоненты, подготовленные для теста тщательно смешать и вылить в смазанную форму, сверху выложить порезанную дольками грушу и измельченные грецкие орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4069,'Выпекать пирог при 170 градусах, в течение 25 минут. Готовность пирога можно проверить шпажкой. Ароматный грушевый пирог с орехами подавать, присыпав сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Отварить курицу, нарезать, выложить первым слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4070,'Куриную грудку разрезать на равные дольки. В отдельной посуде соединить яйца, острый соус и соль. В смесь уложить подготовленную курицу. В другой посуде соединить муку, соль и черный перец. Панировать куриную грудку в сухой смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4070,'Выложить на фольгу. Запекать при температуре 180 градусов на протяжении 15 минут. По окончанию отведенного времени, кусочки поместить под гриль. Для соуса необходимо смешать все подготовленные компоненты. Готовый соус вылить в сотейник и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4070,'Куриные дольки поместить в соус и немного потушить, как только соус загустеет, сотейник снять с огня. Зеленый лук нашинковать и добавить к курице. Острую куриную грудку в апельсиновом соусе можно подать с любым гарниром или свежими овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4071,'Печень почистить, нарезать на тонкие кусочки и обжарить с каждой стороны, затем остудить и нарезать. Репчатый лук порезать полукольцами, а огурец и морковь нашинковать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4071,'Приправить солью и перцем все ингредиенты, сдобрить майонезом, все хорошо перемешать. Салат из огурцов и говяжьей печени настаивать на холоде, на протяжении нескольких часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4072,'В отдельной посуде, с помощью вилки или венчика взбить яйцо, приправить солью и специями, присоединить натертый сыр, все перемешать. Лаваш положить на смазанную маслом сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4072,'Подготовленное яйцо вылить на лаваш, уложить начинку, завернуть края. Лаваш обжарить на среднем огне, с двух сторон до золотистого цвета. Сырный омлет «Ёка» в лаваше готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4073,'Из банки с печенью трески слить масло, печень размять и присоединить к заранее измельченному филе. Добавить рубленую зелень, сдобрить солью и специями, вбить яйцо, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4073,'Из получившегося фарша сформировать котлеты, которые следует панировать в сухарях и обжарить до золотистого цвета. Простые котлеты из трески можно подать с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4074,'Арахис прогреть на сухой сковороде, при необходимости очистить от шелухи. Ядра измельчить в блендере, добавить подготовленные компоненты, все пробить в блендере до однородности. Арахисовое масло можно употреблять с хлебом или использовать как начинку в выпечке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4075,'Все подготовленные ингредиенты по возможности порезать соломкой, корейскую морковку измельчить, салат порвать на кусочки. Все компоненты соединить, заправить майонезом. Тарталетки с корейским салатом и салями выложить на блюдо и подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4076,'Для приготовления блинчиков необходимо, темный шоколад растопить, присоединить остальные ингредиенты, замесить тесто. Блины испечь на разогретой сковороде, промазанной маслом, затем остудить. Для приготовления крема необходимо растопить белый шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4076,'Сливки взбить с добавлением сахара до устойчивых пиков, ввести растопленный шоколад, тщательно взбить. Остывшие блины уложить стопочкой, каждый обильно промазать кремом. Торт из шоколадных блинов, по краям, также намазать кремом и украсить тертым шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4077,'Морковь и сыр измельчить с помощью терки. В жаропрочной посуде смешать молоко, масло, муку, сдобрить солью и специями, варить до загустения, на среднем огне, постоянно помешивая. В готовый соус добавить часть натертого сыра. Предварительно отваренные макароны смешать с морковью, залить соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4077,'Часть макарон уложить в форму и засыпать частью сыра, выложить оставшиеся макароны и посыпать остатками сыра. Запеканку готовить при 180 градусах, в течение 25 минут прикрыв фольгой, потом еще 40 минут без фольги. Запеканку из макарон под молочным соусом порционно нарезать и кушать горячей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4078,'Бананы пюрировать, овсяные хлопья измельчить при помощи блендера. Компоненты смешать, сформировать шарики, уложить на противень, устланный пергаментом, готовить на протяжении 15 минут, при 180 градусах. Простое бананово-овсяное печенье подать к чаю или кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4079,'Кипящую воду посолить, сдобрить специями, кинуть лавровый лист. В сковороде пассировать нашинкованный лук и измельченную грудинку, затем добавить в кипящую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4196,'Слегка остудить и, не сливая воду, измельчить картофель в пюре. Положить в картофельную массу очищенный и прессованный чеснок, молоко, муку, яйца и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4079,'Морковь и картофель нарезать на кусочки и присоединить к остальным компонентам. Когда картофель станет мягким, ввести грибы и плавленый сыр. Перед подачей, в сырный суп с грибами и копченостями, добавить рубленый чеснок и зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4080,'Кусочки хлеба поджарить на сухой сковороде. С помощью круглой формы обрезать края. Хлеб промазать майонезом, сверху уложить сыр и кусочек хлеба, который, также следует промазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4080,'Дальше положить ломтик колбасы/ветчины, смазанной горчицей. Затем уложить все используемые компоненты в том же порядке. С помощью блендера взбить сыр и болгарский перец, получившимся кремом намазать весь «торт».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4080,'Огурец нарезать на тонкие полоски, обернуть вокруг бутерброда, сверху выложить тонко нарезанные дольки редиски и ломтики помидора. Бутербродный торт со сливочным сыром подать на стол в качестве закуски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4081,'Тушку цыпленка натереть чесноком. Для того чтобы приготовить маринад необходимо, смешать соевый соус, мед, соль и карри. Намазать цыпленка и убрать на холод для маринования на некоторое время. Затем, курицу поместить в рукав (или пакет) для запекания, влить оставшийся маринад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4081,'Добавить порезанный кольцами лук и несколько зубчиков чеснока. Готовить цыпленка на протяжении 50 минут. За 10 минут до готовности рукав (пакет) разрезать для того чтобы цыпленок зарумянился. Цыпленок карри в медовом маринаде подать с любым гарниром и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4082,'Для приготовления коржей необходимо, хорошо взбить масло с добавлением сахарного песка. Затем, поочередно присоединить яйца. Какао и краситель перемешать, ввести в заготовку, все перемешать на маленькой скорости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4082,'Порционно ввести кефир и муку, добавить гашеную соду и ваниль. Получившееся тесто разлить по формам, выпекать 35 минут, при 180 градусах. Чтобы приготовить крем, нужно тщательно взбить масло и сахарную пудру, присоединить сыр, экстракт ванильный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4082,'Все очень хорошо взбить. Крем убрать на холод. Для приготовления декоративной крови нужно смешать все подготовленные для этого компоненты. Коржи остудить, промазать кремом и полить декоративной кровью. Оригинальный «Бархатный» торт готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4083,'Желтки отделить от белков. Сахарный песок разделить на две части, с одной часть взбить желтки, с другой белки до устойчивых пиков. Все смешать, ввести просеянную муку. Тесто переложить в форму, готовить при 180 градусах, в течение 40 минут. Готовый бисквит не трогать на протяжении 10 часов, потом разрезать на части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4083,'Масло и сгущенное молоко взбить до однородности, получившимся кремом промазать коржи. Верхушку полить шоколадной глазурью и украсить ягодами. Желе приготовить как указанно на упаковке, полить ягоды. Убрать бисквитный торт с ягодами на холод, до полного застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4084,'В теплую воду поместить сахарный песок, дрожжи, добавить масло и щепотку соли. Ввести муку и замесить тесто. Готовое тесто оставить «отдохнуть» на пару часов. Затем раскатать и уложить на пергамент. Промазать маслом от помидор, сверху смазать пастой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4084,'Уложить помидоры, ветчину и брынзу, сдобрить специями. Перед тем как пиццу поместить в духовку, дать ей немного постоять. Противень разогреть в духовке, затем переложить на него пиццу, готовить в течение 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4085,'Овсяные хлопья измельчить с помощью блендера, залить теплым молоком и оставить на полчаса. Когда геркулес набухнет, вбить яйца, добавить сахарный песок, разрыхлитель и корицу, влить масло, все перемешать. Цедру апельсина натереть на терке, сок выжать, все ввести в тесто. Овсяно-апельсиновые блинчики обжарить с двух сторон на горячей сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4086,'Для приготовления крема необходимо соединить в чаше блендера сахарный песок, творожную массу и сметану. После, вбить яйцо, и всыпать ваниль. Все компоненты довести до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4086,'Печенье измельчить до состояния крошки, залить растопленным маслом и все перемешать, смесь плотно выложить в формочки. Наполненные формы поместить в микроволновую печь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4086,'Готовить в течение минуты, установив среднюю мощность (700 Вт). В формочки разложить подготовленный крем, готовить в микроволновой печи, при той же мощности в течение 2х минут, затем поставить еще на минуту. Перед подачей охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4087,'Все подготовленные специи положить в ступку и растереть пестиком. Добавить сок лимона и оливковое масло, все перемешать. Креветки очистить и натереть маринадом, убрать на холод на 2 часа. Креветки насадить на шпажки, готовить 7 минут на решетке для гриля. Пряные креветки гриль на шпажках можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4088,'Для приготовления теста необходимо смешать все сухие компоненты, присоединить масло и все смешать. Аккуратно влить молоко, замесить тесто. Раскатать тесто на припорошенной мукой поверхности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4088,'С помощью формы или стакана вырезать заготовки и поместить их на противень, устланный бумагой, промазать маслом и присыпать кунжутом и орехами. Готовить сырные тарталетки с кунжутом 15 минут, при 220 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4089,'Овощи измельчить с помощью терки, присоединить нашинкованную зелень. Добавить творог, сдобрить солью, все перемешать. Свекольно-яблочный салат с творогом готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4090,'Из приготовленных продуктов замесить жидкое тесто, добавить фарш, все перемешать. Обжарить оладьи с обеих сторон на разогретой сковороде. Мясные оладьи на скорую руку можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4091,'Масло и сахарный песок соединить в миске и растереть, добавить желтки, измельченный шоколад и орехи, все перемешать. Отдельно взбить белки и ввести их в заготовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4091,'Готовое тесто выложить в форму, устланную пергаментом, сверху уложить ломтики шоколада. Готовить торт «Два орешка» с горьким шоколадом в течение часа, при 190 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4092,'Компоненты для приготовления теста смешать и испечь блины. В миске смешать сыр и нашинкованный укроп, присоединить цедру и сок лайма. Красную рыбу порезать на ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4092,'Каждый блин промазать подготовленным кремом и уложить лосось. Блины укладывать друг на друга, верхушку «торта» украсить икрой. Закусочный торт с лососем и сыром перед подачей к столу лучше нарезать порционно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4093,'Два вида капусты мелко нашинковать и размять. Зелень нашинковать, морковь измельчить с помощью терки. Все компоненты соединить в миске, добавить консервированную кукурузу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4093,'В отдельной посуде перемешать йогурт и горчицу, добавить уксус, все сдобрить сахаром, солью и перцем, перемешать. Салат «Коулсло» заправить получившимся соусом, перед подачей дать салату настояться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4094,'Готовое тесто предварительно разморозить и раскатать. Вишни сбрызнуть ликером, присыпать сахарной пудрой. Взбить молоко, ванильный сахар, добавить шоколадный порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4094,'Готовым кремом помазать тесто и уложить вишню, скрутить рулет. Штрудель переложить на противень, смазать яйцом. Выпекать вишневый штрудель 30 минут, при 200 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4095,'С помощью формочки или рюмки в кусочке хлеба вырезать отверстие. В сковороде растопить масло, обжарить на нем хлеб. Когда хлеб приобретет золотистый оттенок, вырезанное отверстие вбить яйцо. Когда белок схватиться, хлеб аккуратно перевернуть и готовить еще 30 секунд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4096,'В жаропрочной посуде смешать мед и сливочное масло, поставить на огонь и растопить. Всыпать соду, все перемешать и варить до образования золотисто-карамельного оттенка, снять с огня. В отдельной посуде взбить яйца, ввести их в заготовку, добавить муку, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4096,'Готовое тесто разделить на несколько частей, каждую раскатать и испечь в духовке при 170 градусах, в течение 4 минут. Готовые коржи обрезать по форме блюда, на котором будет подаваться торт. Обрезки измельчить при помощи блендера до состояния крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4096,'Для приготовления крема необходимо взбить до однородности вареное сгущенное молоко и сливочное масло. Получившимся кремом промазать коржи, каждый из них посыпать крошкой, собрать торт. Бока и верхушку также промазать кремом и обильно обсыпать крошкой. Домашний  торт «Рыжик» со сгущенкой  готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4097,'Масло измельчить с помощью терки или порубить ножом, затем присоединить яйца, сахарный песок, ввести муку и замесить тесто. Готовое тесто убрать на холод на некоторое время. Яблоки очистить, удалить сердцевину и полить лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4097,'Часть яблок разрезать на кусочки и потушить на сковороде в течение 15 минут с добавлением сахара, ванили и ½ ст. воды. Оставшуюся часть яблок разрезать на очень тонкие ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4097,'Тесто выложить в разъемную форму, не формируя бортики. Затем уложить потушенные яблоки, сверху красиво выложить тонкие дольки и промазать их джемом, присыпать сахаром. Готовить яблочный  торт из Норвегии, полтора часа, при 190 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4098,'Филе семги нарезать на порционные куски. Перец растолочь в ступке, натереть цедру. Филе полить смесью масел, посыпать частью цедры и перца, посолить, оставить мариноваться на некоторое время. Выпекать в течение 10 минут в духовом шкафу, на застеленном фольгой противне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4098,'Нашинкованный тонкой соломкой перец обжарить на протяжении 3 минут на сковороде, полить соком лайма и присыпать розовым перцем. Семгу, с лаймом и розовым перцем, выложить на блюдо с перцем и салатом фризе, украсить долькой лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4099,'Свинину порезать на небольшие кусочки, обжарить на сковороде до полуготовности. Картофель почистить, измельчить с помощью терки. Затем удалить лишнюю жидкость и ввести яйца, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4099,'С помощью ложки выложить на разогретую сковороду оладьи, обжарить. Лук измельчить и пассировать с добавлением томатной пасты. На дно жаропрочного глиняного горшочка уложить оладьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4099,'Сверху выложить кусочки мяса и лук, залить подготовленным бульоном и присыпать нашинкованной зеленью. Готовить на протяжении 30 минут, при 180 градусах. Свинина по-гуцульски в горшочке готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4100,'Компоненты, подготовленные для выпечки смешать в миске, замесить тесто и испечь тонкие блины. В отдельной посуде соединить творог, яичные желтки и масло, все перемешать. Ложку начинки выложить на середину блинчика и свернуть конверт. Обжарить тонкие блинчики с нежным творогом с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4101,'В отдельной миске соединить все сухие компоненты. В другой миске смешать яйца и йогурт, объединить обе смеси и все перемешать. Масло растопить и присоединить ко всем ингредиентам, шоколад измельчить с помощью терки и ввести в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4101,'Подготовленные формочки заполнить тестом не полностью. Домашние маффины, на горьком шоколаде, выпекать в течение 20 минут, при температуре 200 градусов. Остудить и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4102,'Ингредиенты, приготовленные для теста соединить, перемешать и замесить. Получившееся тесто раскатать, пласт перенести в промазанную форму. Базилик и чеснок измельчить, смешать с солью и перцем, добавить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4102,'Готовой смесью обильно смазать куриные бедра и уложить их в форму на тесто, между ними положить дольки лимона. Края защепить, и с помощью кисточки промазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4102,'Выпекать 45 минут, при 180 градусах. Курицу поливать соком, который образуется во время приготовления. Пряную курицу, запеченную в тесте, выложить на блюдо и присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4103,'Желатин замочить, как указанно на упаковке. Желтки взбить с добавлением сахара и ванили, присоединить 1/3 стакана сливок. Остальные сливки немного нагреть, аккуратно влить желтки. Все хорошо мешать до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4103,'Массу убрать с огня, присоединить поломанный на дольки шоколад, ввести желатин, все взбить. Полученную смесь разложить по формочкам и убрать на холод, на несколько часов. Десерт из горького шоколада, перед подачей, подержать несколько минут в тепле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4104,'Одну часть желатина залить водой, другую молоком. Клубнику предварительно разморозить, затем пробить при помощи блендера с добавлением сахара. Желатин, замоченный в воде нагреть на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4104,'После его полного растворения, аккуратно ввести в ягодное пюре. Затем, таким же способом, растворить желатин, замоченный в молоке. Взбить сметану и сахарный песок, присоединить растопленный желатин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4104,'В креманки или бокалы выложить слоями подготовленные массы. Верхний, сметанный слой украсить 2 – 3 ложками ягодного пюре, с помощью зубочисток сделать рисунок. Оригинальное двухцветное желе убрать на холод, на несколько часов, до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4105,'Все подготовленные ингредиенты порезать на дольки, мясо отбить. Все компоненты выложить в форму, посыпать сыром, залить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4105,'Готовить 50 минут, при 200 градусах. Свинину по-французски, перед подачей к столу, выложить вместе с картофелем на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Соль – по желанию и вкусу, блюдо можно поперчить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4106,'В посуде перемешать все подготовленные сухие компоненты, добавить воду, масло, ввести соду. Присоединить вишню, тесто поместить в форму, готовить 30 минут, при 180 градусах. Готовый кофейный кекс со свежей вишней немного остудить и подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4107,'Печень порезать на кусочки и обжарить на сковороде, лук нашинковать и присоединить к печени, все сдобрить солью и специями, потушить. Яйца отварить и очистить, масло довести до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4107,'С помощью блендера или мясорубки измельчить все компоненты, перемешать. Быстрый печеночный паштет можно намазать на хлеб или подать в качестве холодной закуски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4108,'Все овощи порезать на дольки и обжарить на гриле с двух сторон, сбрызнуть их маслом и сдобрить специями. Листья руколы сбрызнуть соком лимона, сверху уложить овощи и сыр, приправить маслом и специями. Овощи гриль с сыром моцарелла можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4109,'Яйца отварить вкрутую, измельчить с помощью крупной терки. Грибы порезать и обжарить. Лук с морковью пассировать. Огурцы нашинковать соломкой, рыбу размять и извлечь кости. В салатник выложить слоями, сначала обжаренные грибы, затем измельченные яйца и огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4109,'Потом уложить рыбу и лук с морковью, затем опять яйца. Каждый слой смазать майонезом. Последний слой этого салата – тертый сыр. Салат из шампиньонов и сардины украсить зеленью и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4110,'Имбирь и чеснок измельчить с помощью терки. Тмин прогреть на сковороде и растолочь в ступке, все подготовленные компоненты перемешать, добавить перец. Получившейся смесью натереть мясо и убрать на холод на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4110,'Обжарить мясо со всех сторон до образования корочки. После поместить мясо в разогретую духовку на 15 – 20 минут. Перед подачей дать мясу отдохнуть в течение 10 минут. Нарезать жаркое из свинины в имбирном маринаде, на порционные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4111,'В миске смешать фарш, измельченный лук, половину подготовленного сыра и нашинкованную зелень, присоединить заранее замоченный в молоке хлеб и яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4111,'Все компоненты перемешать, сдобрить солью и специями, слепить котлеты не большого размера. Их обвалять в муке и обжарить. В сковороду влить вино, выпаривать его в течение 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4111,'Затем присоединить сливки и тушить на протяжении 10 минут. Добавить сыр. Подавать через 3 минуты, после того, как сыр расплавится. Котлеты куриные в сырном соусе готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4112,'Куриное филе нарезать на небольшие ломтики, обжарить до золотистой корочки. Печенку так же порезать и обжарить на сливочном масле в течение 2 минут. Затем поместить в чашу блендера с добавлением горчицы, сметаны и сока лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4112,'Получившейся соус сдобрить солью и специями. Салат порвать на кусочки, выложить на блюдо, сверху уложить кусочки филе, затем положить грушу, порезанную на не большие дольки. Ямайский куриный салат полить соусом и можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4113,'50 мл молока смешать с желтками, сахаром и крахмалом, остальное молоко перелить в жаропрочную посуду и поставить на огонь. Когда молоко закипит, ввести смесь, все компоненты варить, на слабом огне, тщательно перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4113,'Ликер и кофе перемешать, пропитать печенье, сливки взбить в стойкую пену, бананы измельчить. В порционные бокалы уложить слоями сначала пропитанное печенье, затем крем, после бананы и сливки. При необходимости слои повторить. Банановый трайфл с черным кофе готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Все компоненты, приготовленные для теста смешать и замесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Получившееся тесто оставить на полчаса отдохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Сыр измельчить, перемешать с творогом, сдобрить солью и перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Тесто разделить на части, каждую раскатать в лепешку, в середину которой уложить начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Края теста сомкнуть и с помощью скалки опять раскатать. Подобным образом раскатать и начинить все лепешки, проколоть вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4114,'Обжарить лепешки на сухой сковороде с двух сторон. Быстрые хачапури с творогом и сыром можно подавать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4115,'Готовое тесто предварительно разморозить, немного раскатать. Смешать сахарную пудру и корицу, этой смесью обильно присыпать тесто и скатать рулет, нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4115,'Получившиеся улитки выложить на противень, застеленный пергаментом, промазать сиропом. Готовить слоеные улитки  с корицей в течение 10 – 15 минут, при 180 градусах, до образования золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4116,'У хлеба отрезать корочки, каждый кусок раскатать скалкой. Сыр порезать на дольки, положить на хлеб, скрутить рулеты. Каждый рулет обжарить на сковороде, положив их швом вниз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4117,'Смешать горчицу и майонез, добавить измельченный чеснок, все перемешать. Мясо порезать и отбить, сдобрить солью и перцем, промазать соусом. На каждый кусок положить дольку сыра, скрутить рулет и закрепить зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4117,'Рулеты обжарить на хорошо прогретой сковороде до золотистой корочки, затем поместить их в жаропрочную посуду и тушить на медленном огне, на протяжении 20 минут. Свиные рулетики  с чесноком и сыром подать на стол горячими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4118,'Перец порезать, удалив семена, чеснок измельчить. Масло разогреть, на нем обжарить чеснок, затем ввести соусы – рыбный и соевый, через минуту присоединить вино, влить кокосовое молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4118,'Потушить в течение 10 минут, добавить цедру и перец, предварительно очищенные от панциря креветки, через 2 минуты добавить отваренную лапшу.  Креветки с лапшой в кокосовом молоке перед подачей посыпать нашинкованной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4119,'Продукты, подготовленные для начинки измельчить. Тесто раскатать, промазать соусом. Сверху выложить начинку, тесто скрутить в рулет и нарезать на части, переложить на противень, застеленный пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4119,'Каждую улитку присыпать сыром и пряными травами. Готовить 30 минут, при 200 градусах. Дрожжевые улитки  с колбасой можно подавать как в горячем, так и в холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4120,'Шоколад растопить на водяной бане, добавить сахарный песок, воду и ликер. Смесь перелить в миску «на холоде» т.е. в одну миску поместить лед и ледяную воду, на нее поставить миску большего диаметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4120,'С помощью блендера взбить компоненты до загустения. Присоединить часть сливок, остальную часть взбить. В порционные бокалы выложить слоями мусс из горького шоколада, сливки и пюре из хурмы, десерт украсить листиком мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4121,'Киви очистить от кожицы, мякоть поместить в чашу блендера. Влить сок, смешать сахарную пудру и корицу, смесь присоединить к ингредиентам. Все компоненты взбить до однородности. Коктейль из киви с корицей разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4122,'Предварительно отваренные вкрутую яйца разрезать пополам и вынуть желток. В миске смешать желток, майонез (йогурт), с помощью пресса выдавить чеснок, присоединить размятую, консервированную рыбу. Все перемешать и сдобрить специями и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4122,'Помидор разрезать на две части, удалить середину, в нее поместить белок, начиненный подготовленной массой, украсить нашинкованным луком и оливкой. Закусочные яйца «Мимоза» выложить на блюдо и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4123,'В миске взбить до однородной консистенции мягкое масло и сметану, затем присоединить смесь муки и разрыхлителя, замесить тесто. Для приготовления крема необходимо взбить яйцо и сахарный песок, ввести сметану и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4123,'В форму поместить тесто, на дно выложить чистую, но просушенную малину и залить ее получившимся кремом. Пирог готовить при 200 градусах, на протяжении 50 минут. Домашний пирог со свежей малиной остудить и вынуть из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4124,'Куриное филе измельчить с помощью блендера или мясорубки, смешать со специями, вбить яйцо и замесить тесто. Тесто выложить на противень, устланный бумагой для выпечки и готовить в духовом шкафу при 180 градусах, на протяжении 20 минут. Для приготовления соуса, все подготовленные компоненты поместить в сотейник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4124,'Уварить, постоянно помешивая, до загустения. Готовую основу для пиццы смазать соусом, сверху выложить заранее измельченную начинку. Запекать в духовке в течение 15 минут. Оригинальную пиццу «по-новому» немного остудить, нарезать ломтиками и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4135,'Часть сахарного песка и дрожжи поместить в воду и оставить на полчаса. Компоненты, за исключением брынзы и сливочного масла, смешать, добавить дрожжи и замесить тесто. Отставить его на некоторое время, затем поделить на 3 части. Каждую, раскатать в прямоугольный пласт, промазать маслом и выложить покрошенную брынзу или творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4125,'Морковь и огурец измельчить соломкой, салат порвать на кусочки, черри разрезать пополам. Компоненты выложить на сервировочное блюдо, присоединить заранее обжаренные креветки и тонко нарезанный сыр. Зелень нашинковать, добавить в салат, присыпать кунжутом и перцем, посолить. Все перемешать и сбрызнуть маслом. Легкий креветочный салат с овощами можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4126,'Орехи измельчить с помощью ступки и пестика, смешать с остальными компонентами. Все тщательно взбить. Классический сметанный соус с орехами подавать к мясу, салатам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4127,'Холодное масло измельчить с помощью терки, присоединить компоненты подготовленные для теста. Готовое тесто разделить на 2 неравные части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4127,'Меньший кусок убрать в морозильную камеру, а тот, что побольше – в холодильник. Через 30 минут большую часть теста раскатать и уложить в форму, промазанную маслом и присыпанную мукой или манкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4127,'Сделать проколы и промазать вареньем. Достать тесто из морозилки, измельчить его с помощью терки и присыпать пирог. Готовить тертый ванильный пирог к чаю, в духовом шкафу при 180 градусах, на протяжении 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4128,'Взбитые яйца смешать с молоком, присоединить муку и разрыхлитель. В готовое тесто влить стакан кипятка, быстро перемешать и добавить растительное масло. Из получившегося теста испечь блины. Молочные заварные блины готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4129,'Изюм заранее промыть и припорошить мукой. Все компоненты, для теста смешать, присоединить изюм и отставить для набухания. В смазанную форму для выпечки, выложить тесто и готовить в духовом шкафу, на протяжении 50 минут. Манник с изюмом остудить и промазать джемом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4130,'Мясо и лук необходимо измельчить с помощью мясорубки, вбить яйцо. Добавить булку, которую следует заранее размочить в молоке и сдобрить специями. Из готового фарша вылепить котлеты в виде лодочек, в центре которых сделать небольшое углубление. Котлеты выложить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4130,'Готовить в духовом шкафу при 180 градусах, в течение 20 минут. Сыр измельчить с помощью терки и уложить в сформированные углубления, затем, аккуратно вбить яйцо и опять присыпать сыром. Готовить шницели с сыром и яйцом на протяжении 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4131,'В миске соединить все сухие компоненты, в другой посуде взбить яйца с добавлением сахарного песка, ванили и алкоголя. Часть сухой смеси ввести во взбитые яйца, присоединить половину заранее растопленного масла, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4131,'Доложить оставшиеся компоненты, опять все перемешать. Яблоки измельчить и добавить в тесто. Готовое тесто выложить в форму, выпекать в течение часа, при 180 градусах. Для приготовления карамели в сотейнике смешать сахар и воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4131,'Нагреть, постоянно помешивая венчиком до образования золотистого оттенка. Пирог остудить, вынуть из формы и полить готовой карамелью. Простой яблочный пирог с карамелью подавать с шариком мороженого.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4132,'Яйца и сахарный песок взбить, присоединить творог, все перемешать и ввести масло. Всыпать муку и замесить тесто. Все тесто разделить на небольшие кусочки, каждый размять, в центр поместить ягоду, залепить края и скатать шарик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4132,'Шарики обвалять в муке и опустить в кипяток. Варить в течение 3–5 минут после того, как шарики всплывут. Домашние рафаэлло с клубникой обвалять в кокосовой стружке, сухарях и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4133,'Все подготовленные компоненты поместить в сотейник и вскипятить. Получившийся маринад охладить. Поместить в него рыбу. На сутки убрать на холод. По истечению времени домашнюю сельдь можно кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4134,'Филе порезать на крупные куски, поместить в форму для запекания, присыпать солью и перцем. Помидоры нарезать кольцами и положить сверху на рыбу. Для приготовления заливки необходимо соединить предварительно натертый сыр, горчицу и сметану. Получившимся соусом залить ингредиенты в форме. Готовить на протяжении 25 минут, при 180 градусах. Треска под сырно-сметанным соусом готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4135,'Свернуть рулетом и порезать на части. Выложить в форму, промазанную маслом, оставить отдохнуть на 20 минут. Готовить при 200 градусах, на протяжении 30 минут, смазав яйцом. После отведенного времени, болгарский тутманник сбрызнуть водой, укрыть полотенцем и оставить на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4136,'Нарезанные грибы обжарить на сковороде с небольшим количеством масла, через 7 минут добавить нашинкованные лук и чеснок, готовить еще 5 минут. Затем влить вино и тушить примерно 5 минут, до полного испарения вина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4136,'Влить 1/4 часть сливок, сдобрить солью и специями, готовить еще 5 минут. Приготовить заправку. Для этого в миску поместить масло, сливки и уксус, все перемешать, посолить. В заправку добавить листья салата, перемешать. Листья выложить в сервировочное блюдо, сверху уложить готовые грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4136,'Теплый грибной салат с козьим сыром подавать в сочетание с тостами. Для их приготовления необходимо, багет нарезать и подсушить в разогретом духовом шкафу в течение 7 минут, затем немного остудить, смазать козьим сыром и готовить еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4137,'В миске соединить измельченную чиабатту, нарезанные артишоки, нашинкованный чеснок. Присоединить нарезанную мяту, цедру и сок лимона, все сдобрить солью и специями. Влить несколько ложек масла и тщательно перемешать. Филе форели разрезать на 2 куска.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4137,'На противень, застеленный пекарской бумагой положить шпагат, на него уложить подсоленное филе, выложить начинку и накрыть другим куском филе. Сверху поместить бекон, веточки тимьяна и завязать бечевку. Готовить форель с артишоками, миндалем и мятой при 220 градусах, на протяжении 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4138,'Капусту отварить в подсоленной воде, затем измельчить с помощью мясорубки. Так же измельчить лук и чеснок. Зелень мелко нашинковать и добавить в фарш. Все сдобрить солью и специями. Присоединить муку и манную крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4138,'Из получившейся массы сформировать котлеты, которые следует обвалять в панировочных сухарях и обжарить на сковороде до золотистого цвета. Сочные котлеты из капусты можно кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4139,'Для приготовления теста нужно смешать все подготовленные компоненты. Готовое тесто, обернуть пленкой и убрать на некоторое время на холод. Затем, тесто раскатать на припорошенной мукой поверхности, получившейся пласт поместить в форму и с помощью вилки сделать проколы. Готовить 40 минут при 175 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4139,'Для приготовления сыра, довести до кипения молоко, добавить йогурт (пахту или лимон), и когда отделится сыворотка, творог собрать и подвесить на 10 минут. Для приготовления карамели сахарный песок и сливки довести до кипения и варить на медленном огне. Присоединить 3 ложки масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4139,'Шоколад растопить, промазать им заготовку (изнутри). Чтобы приготовить начинку необходимо смешать до однородности сливочный сыр, карамель, ванилин и масло. Готовую массу выложить в заготовку, на остывший шоколад и украсить ягодами. Оригинальный черничный пирог готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4140,'Батон порезать на ломтики, остальные компоненты измельчить с помощью терки, вбить сырые яйца и перемешать. Получившуюся массу намазать на кусочки хлеба и выложить на разогретую сковороду, начинкой вниз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4140,'Обжарить гренки до золотистого цвета, затем перевернуть и обжарить с другой стороны. Гренки с сыром выложить на бумажное полотенце, чтобы удалить лишний жир. Подавать гренки теплыми. Приятного аппетита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4141,'Печенье измельчить с помощью блендера или мясорубки, смешать с заранее растопленным маслом. Получившуюся смесь уложить в форму и убрать на холод. Дольки шоколада растворить в горячих сливках, все перемешать и остудить. Взбить до густого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4141,'Для приготовления ванильного крема необходимо смешать сливки и ванильный сахар, тщательно взбить до пиков. На основу выложить сначала шоколадный крем, затем ванильный. Французский сливочный тарт украсить шоколадной крошкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4142,'Картофель измельчить с помощью терки, белок заранее взбить и присоединить к картофелю, добавить сметану и сдобрить солью. С помощью ложки выложить драники на хорошо разогретую сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4142,'Сначала обжарить драники с одной стороны, затем с другой. Присыпать сыром, закрыть крышку и готовить еще 2 минуты, пока сыр не расплавится. Готовые драники из картофеля подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4143,'Подготовленное филе выложить на противень, устланный пергаментом. Каждый кусок сдобрить солью, специями, промазать майонезом и присыпать зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8607,'С помощью блендера измельчить морковь, апельсин, сырые куриные яйца и отруби.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4144,'Яйца отварить. Все подготовленные компоненты измельчить, заправить майонезом и хорошо перемешать. Выложить на сервировочное блюдо. Для того чтобы оригинально украсить салат, надо тонкими полосками нарезать моцареллу и переплести полоски  между собой в квадрат, чтобы получились лапти. Салат «Лапоточки и грибочки» с опятами, подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4145,'Для приготовления блинов необходимо, смешать в миске все компоненты. Испечь блины. Приготовить начинку, соединив подготовленные ингредиенты. Остывшие блины начинить и свернуть рулетами. Не разъемную форму промазать маслом и присыпать сухарями, уложить фаршированные блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4145,'Отдельно смешать сметану, яйца и ванилин. Получившимся соусом залить блины. Готовить в духовке при 190 градусах, на протяжении 35 минут. Блинную «Улитку» под сметанным соусом сначала остудить, и только потом достать из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4146,'Очистить баклажаны, помидоры и картофель от кожуры. Порезать сладкий перец и очищенные овощи, кубиками. Лук обжарить на разогретой сковороде. Добавить баклажаны и жарить еще 10 минут. Затем на сковороду добавить лавровый лист, помидоры, сладкий перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4146,'Тушить овощи еще 10 минут. Тушеные овощи переложить в кастрюлю, налить чуть-чуть воды. Добавить картофель, соль, чеснок, перец и рубленую зелень. Тушить до готовности картофеля. Грузинский аджапсандал из овощей посыпать свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4147,'Масло заморозить в морозилке и когда оно станет твердым, не размораживая, натереть крупно на терке. К нему добавить одно яйцо, сахар, перемешать, насыпать муку и разрыхлитель. Руками замесить тесто и скатать из него в шар. Смазать маслом форму для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4147,'Для этого количества продуктов подойдет форма диаметром 24 см. Тесто раскатать скалкой толщиной 1 см. Аккуратно обернуть вокруг скалки раскатанное тесто и переложить в форму. Тесто уложить так, чтобы были высокие бортики 6–7 см. Сметану взбить венчиком или миксером с остальными яйцами, сахаром и ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4147,'Вылить начинку в форму. Бортики должны быть выше начинки на 2–3 см, так как начинка очень сильно поднимается в процессе выпекания. Пирог выпекать при 180 градусах 45–50 минут. Готовый ванильный сметанник охладить в холодильнике и украсить фруктами. Приятного аппетита.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4148,'Огурцы нарезать и положить в чашу блендера. Выдавить к огурцу сок лайма и апельсина. Огурцы с соком измельчить до однородной жидкости. Добавить мед, холодную воду и перемешать. Украсить бокалы освежающего лимонада из огурца и лайма, веточками розмарина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4149,'Картофель почистить и разрезать на части. Кусочки должны быть небольшими. Нарезанные кусочки картофеля проварить в воде, в течение 7–10 минут, затем воду слить. Вынуть и остудить картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4149,'Теплые кусочки картофеля обвалять в муке с солью и любыми приправами. Смазать жиром пекарскую бумагу, застелить ей противень и выложить на нее картофельные ломтики, оставляя между ними расстояние.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4149,'Противень поставить в духовку. Чтобы корочка была равномерно золотистой, через некоторое время противень с картофелем нужно перевернуть. Простой картофель, запеченный в духовке разложить по тарелкам и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4150,'Сначала приготовить инвертный сироп. Для этого растворить сахар в кастрюле с водой и вскипятить, постоянно помешивая. Кастрюля должна быть с толстым дном. Добавить лимонную кислоту к сиропу, перемешать. Закрыть кастрюлю крышкой, огонь убавить. Оставить сироп на 45 минут, греться. Выключить плиту. Сироп получится бледно-желтого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4150,'Через 1–1,5 часа развести соду в столовой ложке воды и добавить в остывший сироп. От соды сироп начнет пениться, его нужно периодически помешивать. Примерно через 10–15 минут он станет цветом и густотой напоминать майский мед, значит инвертный сироп готов. Для приготовления самих маршмеллоу, развести желатин в 0,5 ст. воды и оставить на 15–30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4150,'В кастрюльку налить остальную воду, добавить инвертный сироп, сахар и соль. Перемешать полученную жидкость, поставить на плиту и довести до кипения. После этого убавить огонь и варить 8 минут, не мешая. Разбухший желатин переложить в посуду для взбивания и миксером, на маленькой скорости, начать взбивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Добавить сахарный песок, влить молоко и половину яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4150,'В процессе взбивания тонкой струйкой вливать горячий сироп. Включить на миксере высокую скорость и взбивать еще 15 минут. Масса станет похожей на взбитые белки или на зефир. Отрезать кусок пищевой пленки по размеру, чтобы хватило накрыть маршмеллоу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4150,'Смазать ее растительным маслом без запаха и уложить в форму. Массу выложить на один край пленки, накрыть сверху вторым краем и поставить на ночь в прохладное место для застывания. Достать утром массу из пленки и разрезать на кусочки острым ножом. Обвалять классический зефир маршмеллоу в смеси крахмала и сахарной пудры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4151,'Рыбное филе натереть солью (по желанию), порезать на порционные кусочки и сбрызнуть лимонным соком. В майонез добавить мелко порезанные помидоры, зелень и чеснок. Натереть сыр и добавить половину к майонезу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4151,'Рыбу обмакнуть в полученный соус и выложить на смазанный противень. Посыпать сверху оставшимся сыром. Нежную рыбу по-гречески запекать 30 минут. Духовка должна быть заранее нагретой, до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4152,'Нагреть духовку до температуры в 180 градусов. Яйцо и сахар взбить миксером. Всыпать кокосовую стружку и размешать. В яично-кокосовую массу насыпать разрыхлитель и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4152,'Перемешать и замесить тесто. На полчаса поставить его в холодильник, чтобы тесто стало окончательно готовым к выпеканию. Вылепить из теста печенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4152,'Если тесто прилипает к рукам, то окуните их в холодную воду и лепите, не вытирая рук. Печенье уложить на противень и поставить на 15 минут в духовку.  Быстрое печенье из кокосовой стружки готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4153,'Просеять сахар в кастрюлю и добавить к желтки. Растереть добела. Туда же добавить ванилин. Молоко нагреть и развести им желтки. Нагреть содержимое кастрюльки, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4153,'Когда смесь загустеет и исчезнет пена на ее поверхности, снять кастрюльку с плиты и процедить смесь через мелкое сито. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4153,'Перелить в емкость мороженицы. Убрать мороженое в морозилку. В процессе заморозки, периодически доставать и взбивать смесь. Домашнее мороженое на молоке готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4154,'Разбить яйца и отделить белок от желтка. Белки взбить. Желтки перетереть с солью и сахаром. Просеять муку. Молоко влить к муке, перемешать, добавить протертые желтки и растопленное сливочное масло. Все размешать и осторожно добавить взбитые белки, затем влить растительное масло и еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4154,'Нагреть на сковороде 1 ч. л. масла и по очереди, выпечь тонкие блинчики. Для начинки: протереть творог с сахаром. Каждый блинчик разрезать на полоски. Творог положить на край полоски, на него выложить фрукты, порезанные тоже полосками, по ширине блинчика. Свернуть рулетом. Роллы творожные, с фруктами готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4155,'В кефир добавить соду и на 5 минут оставить, для прохождения реакции. Затем добавить все продукты по рецепту и хорошо перемешать тесто. Нанести на дно и бортики формы тонкий слой масла, немного насыпать муки, поверх масла. Примерно 1/2 теста вылить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4155,'Для начинки, мелко порезанный лук перемешать с сырым фаршем и выложить в форму. Вылить сверху остатки теста. Поставить пирог мясной «Легче не бывает» в нагретую до 170 градусов духовку и выпекать 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4156,'Замороженный маргарин натереть на терке. Добавить размятые вилкой ингредиенты и замесить тесто. Из творога, яиц и сахара приготовить начинку, добавить по вкусу корицу и ваниль. В форму уложить половину теста, сверху выложить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4156,'Разровнять ее поверхность и выложить вторую половину теста. На 30 минут поставить пирог в духовку. Температура в духовке должна быть 180 градусов. Затем творожный пирог «Изюминка» с корицей достать, и оставить остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4157,'Лук порезать мелкими кусочками, положить в глубокую сковородку и обжарить до мягкости. Добавить сметану. Вскипятить, добавить соль и перец. Кольца кальмара не размораживая промыть и выложить в сметану. Потушить, помешивая, 4 минуты. Переложить готовые кольца кальмара в тарелки и украсить зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4158,'Кубиками порезать куриное филе. Сыр нарезать кубиками такого же размера, либо меньше. Лук мелко порезать. Лук, сыр и мясо перемешать с кефиром, крахмалом, специями и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4158,'Смешать смесь с порубленной зеленью и сформировать котлеты. Их получится примерно 15 штук. Пожарить котлеты на среднем огне. Рубленные котлеты» Нежность»  из курицы можно подать с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4159,'Киви очистить от кожицы. Луковицы почистить. Измельчить в блендере киви и 2 луковицы до однородной пасты. Сладкий перец и остальной лук нарезать кольцами. Мясо промыть и крупно порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4159,'Натереть молотым кориандром и солью каждый кусочек мяса. Залить соусом из киви и лука, добавить нарезанные овощи. Мясо и маринад хорошо перемешать, чтобы мясо было хорошо промазано маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4159,'Убрать в холодильник на 2,5 часа, мариноваться. В чашу мультиварки сложить мясо и вылить маринад с овощами. Поставить зажариваться в режиме Выпечка, на 45 минут. Нежный свиной шашлык в мультиварке готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4160,'Просеять муку, соду и соль вместе. Добавить сметану, размягченное сливочное масло и сахар. Перемешать и замесить тесто. Мешать тесто можно руками или толкушкой, для картофельного пюре. Затем, тесто прокрутить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4160,'Как только выдавится тесто примерно с ладонь, оторвать его и уложить на противень, застеленный кондитерской бумагой. Печенье на 20–25 минут поставить в нагретую духовку. Золотистое печенье остудить и измельчить в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4160,'Немного крошек отложить в сторону. Мягкое сливочное масло и сгущенку взбить. Перемешать крем с крошкой и выложить горкой на блюдо. Сверху торт посыпать оставленной  крошкой. Убрать песочный торт «Муравейник» с кремом на ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4161,'Муку просеять. Яйца взбить с сахаром и ванилином. Добавить муку, размешать. Растопить масло, смешать с медом и добавить полученную смесь к тесту. Смазать противень, сливочным маслом и застелить кулинарной бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4161,'Тесто вылить на противень ровным слоем. При необходимости, разровнять поверхность лопаткой. Духовку включить и нагреть до 180 градусов. Противень с тестом поставить в духовку на 14–16 минут, до готовности коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4161,'Готовый бисквит смазать сливками, дать немного пропитаться. Почистить банан, положить на корж и свернуть рулетом, аккуратно отделяя корж от бумаги. Убрать домашний сливочный рулет с бананом в холодильник, на пару часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4162,'Отварить яйца и куриную грудку. Лук нарезать и заранее замариновать. Салат выложить слоями в миске. Первым слоем: отваренная и порезанная мелкими кусочками куриная грудка, затем маринованный лук, маринованные грибы и посыпать тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4162,'Уложить сверху мелко натертый белок, затем мелко натертый желток. Все слои промазать тонким слоем майонезом. Майонез для промазывания слоев можно смешать с зеленью или с чесноком. Салат «Нежный» с курицей, украсить на свой вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4163,'Очищенный картофель отваривать 10 минут, до полуготовности. Слить воду и остудить. Лук мелко нарезать и перемешать с фаршем. Фарш посолить, добавить перец и вымесить.  Мелко натереть сыр. Помидоры порезать кружочками. Нарезать картофель ломтиками, в 1 см толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4163,'Противень застелить пергаментом, промазать маслом, чтобы картофель не присох. На него выложить картофель, смазать маслом, приправить травами и специями, посолить.  Выдавить чуть-чуть майонеза на каждую картофелину и положить давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4163,'Прикрыть кружочком помидора, сверху положить маленькую ложку фарша.  Присыпать тертым сыром и поставить запекаться при 180–200 градусах, на 30 минут. Готовый картофель, запеченный с мясом и помидорами, украсить щепоткой зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4164,'Взбить 2 яйца. Уксус развести водой, смешать вместе с яйцами. Посолить и перемешать еще раз. Измельчить замороженное масло, можно мелко порубить ножом или натереть на терке. На стол насыпать муку горкой. Сверху насыпать масло. Порубить муку с маслом ножом, чтобы перемешалась смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4164,'Сделать ямку в муке с маслом и влить яичную смесь. Быстро замесить тесто. Тесто разрезать на 12 частей, каждый скатать в шарик. Выложить шарики на тарелку и прикрыть пищевой пленкой. Поставить в холодильник на 1 час. Для крема вскипятить литр молока. Убавить огонь до минимального.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6255,'Очищенные яблоки потереть на крупной терке, вместе с мукой, жиром, яйцом и солью добавить к картофельной массе и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4164,'Желтки перетереть добела с обычным и ванильным сахаром. Добавить муку, перемешать вилкой и перелить к горячему молоку. Довести до загустения на маленьком огне. Не переставать мешать. На пергаментной бумаге, тонко раскатать шарик теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4164,'Приложить круглую форму и обрезать лишнее тесто. Корж уложить на пергаментную бумагу и наколоть вилкой, несколько раз в разных местах, чтобы при выпекании не вздулся. Поставить противень с коржом на 7–10 минут в духовку, на 180 градусов. Испечь еще 11 коржей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4164,'Каждый корж промазать кремом, складывая их стопкой. Бока и верх торта также смазать кремом. Запеченные обрезки теста измельчить в блендере или перетолочь толкушкой. Посыпать крошками всю поверхность торта, включая боковую. Торт «Наполеон» с яичным кремом  поставить на 6–7 часов в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4165,'Все ингредиенты, кроме муки и черники, смешать в жаропрочной посуде, в которой будет выпекаться кекс. Чернику обсыпать мукой, чтобы она во время выпекания не опустилась на дно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4165,'Ягоды добавить к тесту. Посуду с тестом поставить в микроволновку. Выпекать кекс на максимальной мощности, 3–4 минуты. Быстрый черничный кекс немного отудить и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4166,'Замочить грибы в 300 мл горячей воды, пока они не станут мягкими. Из дрожжевого теста вырезать кружки, по размеру чуть больше чем горлышко горшочка для запекания. Курицу обжарить на сковороде с разогретым маслом. Мясо убрать со сковороды и поджарить нарезанный лук и бекон (примерно 5 минут).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4166,'Грибы порезать на небольшие кусочки. В сковороду добавить грибы и зеленый горошек. Потушить, добавить муку и перемешать. Влить молоко и бульон оставшийся от замачивания грибов, положить специи. Грибы с получившимся соусом вскипятить и тушить до готовности. Курицу порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4166,'Положить мясо на сковородку, добавить тмин и еще немного потушить. Начинку разложить по горшочкам, накрыть каждый кружками теста и плотно залепить края. Поверхность теста смазать желтком.  Поставить пирог с курицей и грибами в горшочках, в духовку на 20–25 минут, при температуре 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4167,'Взбить яйца с солью до появления пенки. Влить стакан кипятка и взбить миксером жидкость. К жидкости добавить кефир, хорошо перемешать. Просеять муку с содой и добавить к жидкой смеси вместе с сахаром и маслом. Миксером перемешать тесто. Жарить заварные блины на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4168,'Сахар, соль, ванилин добавить к яйцам и взбить (5 минут). Подогреть масло до мягкости. Подогреть немного молоко, добавить кофе и мешать ложкой, пока оно не растворится. К яйцам добавить масло, кофейное молоко, соду. Миксером взбить смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4168,'Муку просеять с какао. Выложить к тесту и перемешать. Форму (20 см) смазать и налить в нее тесто. Поставить корж выпекаться в нагретую до 180 градусов духовку, на 30–50 минут. В начале выпекания духовку не открывать. Корж остудить, разрезать на 3 одинаковых коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4168,'С верхнего коржа срезать шапочку и порезать ее на кубики. Сметану и сахар перемешать. Это будет крем. Ингредиенты для глазури смешать и варить на медленном огне, пока не получится однородная, густая глазурь.  Бананы порезать на тонкие пластинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4168,'Смазать кремом нижний и средний корж. Между ними выложить бананы.  Смазать кремом верхний корж и уложить на торт. Кубики бисквита, залить кремом и выложить на верхний корж. Залить глазурью. Шоколадный торт с бананами в глазури, убрать на 2 часа, чтобы он хорошо пропитался.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4169,'Куриное филе некрупно порезать. Натереть сыр. Смешать кусочки курицы, сыр, яйцо, муку. Добавить специи, выдавить очищенный чеснок. Перемешать фарш. Слепить котлетки. Нагреть сковороду и обжарить куриные котлетки с чесноком и сыром с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4170,'Клубнику очистить от зеленых плодоножек и промыть холодной водой. Обсушить ягоды. Насыпать слой сахара на дно большой кастрюли, для варки варенья. Выложить в кастрюлю часть ягод и снова насыпать слой сахара. Таким образом выложить слоями весь сахар и все ягоды. Отставить ягоды на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4195,'Разогреть духовку до 170 градусов. Помогая ножом, разложить закусочные тающие треугольники на противень и готовить минут 10. Можно употреблять, как закуску к пиву или с охлажденным сухим вином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Отварить свиной язык, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4170,'Слить выделившийся сироп в отдельную кастрюлю, вскипятить его и залить сиропом ягоды. Поставить кастрюлю с вареньем на медленный огонь и варить, не мешая, примерно 50 минут. За пару минут до готовности добавить к варенью лимонный сок. Когда варенье из клубники с лимонным соком будет готово, разложить его по банкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4171,'Заранее достать яйца и масло из холодильника. Мягкое масло посолить и добавить 2 яйца, муку и замесить пластичное тесто, не липнущее к рукам. Муку подсыпать постепенно, чтобы не пересыпать лишнего. Завернуть тесто в пленку, убрать на холод на 1 час. Охлажденное тесто поделить на равные части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4171,'Тонко раскатать каждую часть и вырезать, круглой формой, кружочки диаметром 7 см. Половину лепешек оставить целыми, а из второй половины вырезать отверстие в центре в форме звездочки (или любое другое). На целые кругляши выложить начинку, не затрагивая краев. Сверху выложить кругляши с отверстием и залепить края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4171,'Для надежности края придавить кончиками зубцов вилки. Желток слегка взбить вилкой и смазать им печенье. В нагретую духовку поставить печенье на 12–15 минут. Температура выпекания 180 градусов. Рассыпчатое печенье  на скорую руку готово. Печенье немного остудить и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4172,'На дно салатника выложить порванные руками листья пекинской капусты. Положить слой консервированной кукурузы, на нее выложить тунец, немного измельченный вилкой. Воду с консервов обязательно слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4172,'Нарезать огурцы и помидоры соломкой. В салатник положить слой огурцов, затем помидоры. Плавленый сыр натереть на терке. Украсить им салат. Для заправки смешать масло, соль и немного сока лимона. Залить заправкой салатик «Легкий» с пекинской капустой и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4173,'Налить на сковородку оливковое масло, выложить лук, полукруги моркови и мелко порезанный чеснок. Положить куски курицы и обжарить, не накрывая крышкой. Посолить курицу крупной солью, много карри и наливаем немного бульона из курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4173,'Перемешать содержимое сковородки и тушить под крышкой 5 минут.  Добавить на сковородку и перемешать мелко порезанный киви, свежемолотый черный перец и сметану.  Готовить при слабом булькании 20 минут под крышкой. Подавать пикантную курицу в сметанном соусе, с картофельным пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4174,'Заранее включить духовку нагреваться до 180 градусов. Форму, которая будет использоваться для запекания рыбы, намазать маслом изнутри. В большой кастрюле вскипятить немного подсоленную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4174,'Сложить в воду рыбное филе и варить 5 минут. Потом филе достать и дать стечь воде. Рыбу раскрошить и переложить в форму.  Для соуса, на сковороде растопить маргарин и, сняв с огня, добавить к нему муку и молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4174,'Сковороду вернуть снова на огонь. Варить до загустения на среднем огне. Посолить. Кусочки трески полить соусом и посыпать тертым сыром и запечь в духовке до румяной корочки. Треску из духовки под сырным соусом кушать горячей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4175,'Печень трески раздавить вилкой. Вареные яйца натереть. Порезать батон на ломтики и обжарить на сковороде без масла или в тостере. Натереть чесноком с двух сторон. Яйца и печень перемешать с сыром, майонезом и порезанным укропом. На батон выложить подготовленную начинку. Подавать  закусочные сэндвичи с печенью трески, посыпав зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4176,'Отварную куриную грудку вилкой разделить на мелкие волокна. Можно порезать ножом, но тоже мелко. Огурец порезать соломкой. Если шкурка у него грубая, то лучше огурец предварительно почистить. Перемешать тертый сыр, огурец и грудку, заправить заправкой из соевого соуса и сока лимона.  Подавать куриный салат с огурцами под соевым соусом через 5–10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4177,'В миске смешать яйцо и специи, хорошо взбить. Влить к яйцу молоко и масло (1 ст. л.). Опять взбить. К кляру добавить муку. Масса должна получиться густой. Можно добавить к нему панировку или посыпать ей кусочки после обмакивания в кляре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4177,'В глубокой сковороде нагреть масло.  Курицу обмакнуть со всех сторон в кляр и обжарить на сковороде. Сочное филе курицы в кляре выложить на блюдо и подавать горячим, как самостоятельное блюдо или с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6255,'Обвалять в сухарях сформованные из готовой массы котлеты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4178,'Сгущенное молоко и масло смешать в блендере. Добавить коньяк и какао к масляно-молочной смеси. Измельчить через мясорубку печенье до мелкой крошки. Смешать все ингредиенты и хорошо перемешать до однородности.  Разделить полученное тесто на одинаковые овальные колобки. Поставить пирожные «Шоколадная картошка» в холодильник на 5 часов, чтобы застыли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4179,'Растереть яйцо со всеми продуктами и перемешать с 1 стаканом муки. Сформировать из творожного теста «колбаски», подсыпав на стол муки. Разрезать их на лепешки и отварить в подсоленной воде. Время варки – 1 минута, не дольше.  Ленивые вареники из творога полить сладким соусом, вареньем или сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4180,'Болгарский перец трех разных цветов порезать на тонкие кольца. Чеснок потереть. Луковицы порезать полукольцами. Посыпать солью и перцем куриные грудки.  На сковороду налить оливковое масло и положить сливочное масло. Нагреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4180,'Куриные грудки обжарить на смеси из масел и когда они будут готовы, переложить в форму для запекания. На сковороде, где жарились грудки, пожарить лук и тоже переложить его в форму. Затем там же обжарить болгарский перец до мягкости и убрать к курице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4180,'Пассировать чеснок в течение 30 секунд, долить воды и положить нарезанные помидоры. Перемешать и добавить щепотку мускатного ореха, итальянские травы, перец, соль, овощной бульонный кубик. Также налить полстакана сливок и хорошо перемешать соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4180,'Соус поставить на плиту и варить 5 минут на слабом огне.  Курицу залить соусом и закрыть фольгой.  Поставить форму в духовку на полчаса при температуре запекания 200 градусов. Курицу «Пикассо» с овощами и пряностями достать из духовки и убрать фольгу. Посыпать сыром и вернуть в духовку еще на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4181,'Молоко подогреть, но не кипятить. Раскрошить дрожжи и растворить в молоке. Добавить предварительно взбитые с сахаром, яйца. Немного присолить. Постепенно добавить в жидкую смесь 3 стакана просеянной муки. Затем влить растительное масло и вымесить. Подсыпая четвертый стакан муки, замесить некрутое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4181,'Собрать тесто в смазанный маслом полиэтиленовый пакет. Пакет завязать, но так чтобы внутри остался воздух и место для роста теста. Положить пакет с тестом на блюдо, на полку холодильника. Примерно через час тесто будет готово. Тем временем подготовить творожный крем. Творог перетереть с яйцами и сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4181,'Добавить ванилин, если творог слишком сухой, то можно добавить ложку сметаны, йогурта или сливок. В творог добавить персики или любые фрукты по вашему желанию. Когда тесто поднимется, переложить его на присыпанный мукой стол и раскатать по размеру противня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4181,'Намотав тесто на скалку, переложить на смазанный маслом противень. Сверху на тесто выложить творожный крем, края ватрушки завернуть внутрь и смазать желтком, взбитым с ложкой воды. Выпекать ватрушку «Нежность» с персиками, в нагретой заранее духовке. Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4182,'Размять 150 г творога, добавить в него сахар, яйцо, растительное масло и взбить миксером на средних оборотах. Понемногу подсыпая муку, смешанную с разрыхлителем, замесить эластичное тесто. Раскатать тесто в пласт, высотой в 1,5-2 см и выложить его в круглую форму для запекания с высокими бортами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4182,'На время приготовления начинки, форму с тестом поставить в холодильник. Для приготовления начинки отделить белки и взбив их в пышную пену, с каплей лимонного сока, положить на время в холодильник. Размягченное масло взбить с оставшимися желтками и сахаром. Снять с лимона цедру, выдавить сок из 1/2 лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4182,'Добавить в масляный крем творог, сок лимона, цедру и перемешать. Всыпать немного разрыхлителя, добавить сметану и взбить миксером. Очистить мандарины от кожуры, разделить на дольки и дать немного подсохнуть. Когда прозрачная оболочка долек станет ломкой, очистить мякоть от пленок и разрезать каждую на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4182,'Добавить мякоть мандаринов в творожную начинку и аккуратно вымесить. Осторожно подмешать пену из белков. Переложить начинку поверх охлажденного теста и выпекать в разогретой духовке до золотистой корочки. Пирог «Ноктюрн» с цитрусом лучше подавать к чаю охлажденным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6255,'Котлеты из картофеля и яблок обжарить со всех сторон и подать с овощным салатом, сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4183,'Фундук перемолоть в кофемолке. Пересыпать молотые орехи в глубокую миску, добавить к ним сахар, разрыхлитель и чуть взбитые яйца. Форму для микроволновой печи смазать маслом и перелить в нее тесто. Выпекать около 5 минут, при мощности в 900Вт, в микроволновке или в духовке, 7-10 минут при 180 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4183,'Вынуть корж из формы только после полного его остывания. Крем приготовить из масла комнатой температуры с взбитым сгущенным молоком. Корж разрезать вдоль на две половины острым ножом и обмазав кремом, сформировать торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4183,'Так же, можно разделить тесто на две части и выпекать поочередно два коржа, тогда время их выпекания сократиться до 3 минут на каждый корж. Сверху, быстрый торт из орехов украсить, присыпав дробленым фундуком или тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4184,'Свежие огурчики промыть под проточной водой, обсушить и при необходимости очистить от кожуры. Молодые огурцы с тонкой шкуркой можно оставить нечищеными. Нарезать огурцы мелкими кубиками. Отваренное яйцо нарезать не очень крупно. Семгу порезать брусочками и добавить в салатник к яйцу и огурцам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4184,'Выложить пару ложек консервированной кукурузы, отделив ее предварительно от рассола. Укроп промыть и мелко нарезать. Заправить салат нежирным майонезом, можно домашнего приготовления и посолить. Всыпать укроп, перец и перемешать. Деликатесный салат из нежной семги выложить на блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4185,'Масло порубить и соединить с мукой, перетереть в мелкую крошку. Яйца взбить до однородности с молоком и влить жидкость в мучную крошку. Соду погасить и добавить в тесто, туда же влить растительное масло. Понемногу подсыпая муку, замесить тесто, оно должно быть не очень крутым и непременно эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4185,'Скатать тесто в колбаску и разрезать ножом на несколько сегментов, по количеству коржей. Накрыть тесто полотенцем от высыхания. Раскатать один кусочек теста и обрезать его по контуру крышки или тарелки, подходящего диаметра. Жарить на сковороде, под крышкой, с обеих сторон по 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4185,'Для того чтобы тесто при жарке не сжималось, можно сделать разрезы ножом или проколоть вилкой. Жарить необходимо на чуть смазанной сковороде, либо с антипригарным покрытием, поскольку тесто при жарке выделяет жир. Пока жариться один коржик, можно раскатать следующий, главное не прозевать и не спалить первый.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4185,'Готовые коржи сложить стопкой и накрыть салфеткой для того чтобы они немного размякли. Для крема: Яйца взбить с сахаром. Молоко вскипятить. Тонкой струйкой ввести яичную массу и варить, помешивая до сгущения. Можно добавить чуточку крахмала или муки. В конце всыпать ваниль и отставить до остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4185,'Когда крем остынет взбить масло и присоединить к заварному крему. Влить сгущенку и повторно взбить миксером. Перемазать коржи кремом. Сверху присыпать крошкой из коржей (наверняка найдется неудавшийся корж или поломавшийся в процессе выпекания). Поставить торт пропитываться на 5-6 часов. Домашний торт «Наполеон» на сковородке готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4186,'Кабачки очистить от кожуры, семян и перетереть на терке, если овощи молодые – кожуру можно не снимать. В кабачковую массу добавить чуточку тертого чеснока. Вбить два яйца, присолить и тщательно вымесить. Подсыпать муку и замесить густое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4186,'Разделив кабачковую массу на две части. Поочередно обжарить на сковороде два коржа. Переворачивать коржи следует очень аккуратно. Выложить один остывший корж на плоскую тарелку, соответствующего диаметра. Смазать майонезом с добавлением тертого чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4186,'Помидоры разрезать на тонкие кружки и половину выложить прослойкой, между коржами. Присыпать рубленой зеленью. Накрыть вторым коржом, также смазать его майонезом, украсить помидорами и зеленью. Дать кабачковому торту с томатом и чесноком настояться в течение часа и подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4187,'Приготовить желе, сократив количество воды, указанное в инструкции на упаковке, вдвое.  Так если в инструкции указанно 400мл воды, использовать необходимо только 200-220мл, для того чтобы застывшее желе можно было порезать кубиками, а вкус его был более насыщенным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4196,'Почистить картофель и разрезать его на четыре части. Положить картофель в воду так, чтобы она его лишь покрывала. Посыпать солью и варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4187,'Растворить поочередно все желе залив их в прямоугольные формы для застывания. Подготовить фрукты, нарезав их кубиками, лучше использовать мягкие фрукты, такие как персик, банан, киви и цитрусовые. Печенье покрошить на кусочки. Желе нарезать кубиками. Сметану или сливки охладить. Желатин замочить в молоке. Набухший желатин растворить на паровой бане, при постоянном помешивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4187,'Сметану взбить с сахарной пудрой и влить, в пышную массу, немного остывший желатин. Глубокую миску в форме полусферы застелить пищевой пленкой. Всыпать в нее фрукты, печенье и цветные кристаллики желе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4187,'Залить сметанным кремом, перемешать и поставить в холодильник. Застывший десерт накрыть широким блюдом и перевернуть. Снять миску, пищевую пленку и украсить желейный торт-десерт «Мозаика», на свое усмотрение, кусочками фруктов, взбитыми сливками или тертым шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4188,'Говядину разрезать поперек волокон пластинами в полсантиметра толщиной. Отбить молоточком с мелкими зубцами или тыльной стороной лезвия ножа. Нарезать на тонкие полоски. На сковороде растопить сливочное масло и выложить в нее половину мясной нарезки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4188,'Обжарить на сильном огне пару минут, затем перевернуть целым пластом и снова обжарить. Так мясо запечатается и останется сочным внутри. Затем обжарить таким же образом вторую половину мяса. Переложить на блюдо и дать мясу отдохнуть. Лук мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4188,'Обжарить его в сотейнике с толстым дном, на сливочном масле, до прозрачности. Всыпать в лук, муку и продолжать обжаривать, помешивая, до карамельного оттенка. Как только мука приобретет коричневый оттенок, влить бульон и хорошо размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4189,'Все подготовленные компоненты перемешать. Присоединить мелко нарубленную зелень, измельченный чеснок и специи. Измельчить блендером. Белый холодный соус с чесноком подойдет к любому блюду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4190,'В чашу блендера поместить все ингредиенты (кроме растительного масла). Пробить до однородности и продолжая взбивать, медленно влить масло. Перемешивать до тех пор, пока не смешаются все компоненты. Чесночный соус к мясу и рыбе готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4191,'Все подготовленные ингредиенты хорошо перемешать. Соус карри с чесноком, на кефире употреблять с  мясом, овощами и рисом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4192,'Все компоненты, подготовленные для приготовления соуса перемешать до однородного состояния. Подавать соус к мясным блюдам и курице.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4193,'Все ингредиенты поместить в чашу блендера, измельчить, сдобрить солью и специями. Острый турецкий красный соус идеально подойдет к мясу, рыбе и картофелю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4194,'Духовку разогреть до 180 градусов. Противень застелить специальной бумагой. Всыпать в белки соль и взбить до пиков. Соединить какао, сахарную пудру и миндаль. Добавить массу в белки. Аккуратно перемешать, чтобы не потерялся объем белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4194,'Положить смесь в кондитерский мешок и отсадить на противень кружки одинакового размера. Отставить на полчаса, чтобы затвердел верх пирожных. Сделать шоколадную начинку. Шоколад растопить на водяной бане. Положить масло и влить сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4194,'Размешать. Отправить макаруны в духовку, готовить 13 минут. Готовые макаруны вынуть и охладить. Плоскую сторону намазать кремом, накрыть второй частью. Подобную процедуру сделать со всеми макарунами. Миндальные макаруны с шоколадной начинкой выложить на блюдо и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4195,'В процессор с ножами насыпать просеянную муку, положить масло, посолить и перемешать. Можно это сделать вручную на столе. В конце данного процесса насыпать тертый сыр и продолжить рубить. Отделить белок от желтка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4195,'Выложить смесь в емкость, вбить желток. Масса будет рассыпчатой, но, несмотря на это, она легко соединится в шар. Завернуть шар в полиэтилен и на 20 минут отправить в холодильник. Смазать форму для выпекания мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4195,'Охладить, до появления на масле тонкой, застывшей пленки. Тесто раскатать. Нарезать тесто на квадраты, размером  5 на 5 см, а затем каждый квадрат разрезать по диагонали. Взбить белок, смазать им треугольники и посыпать кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5027,'В холодную погоду глинтвейн из белого сухого вина с ромом и изюмом – прекрасный согревающий, тонизирующий и поднимающий настроение напиток.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4196,'Посолить, влить немного растительного масла. Перемешать и отставить тесто минимум минут на 20. Разогреть сковороду, смазать ее растительным маслом и пожарить тонкие блины из картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Взбить миксером холодные белки и щепотку соли, чтобы получилась крепкая пена. Не прекращая взбивать, медленно добавить сахар. Взбивать, до образования блестящей стойкой пены, не выпадающей из емкости, перевернутой вверх дном. Измельчить блендером орехи в муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Если не получается сделать мелкую крошку, то высыпать орехи  на противень, застеленный пергаментом, сушить минут 10, соблюдая температуру 150 градусов. Снова перемолоть. Аккуратно всыпать ореховую крошку вместе с мукой в белки. Осторожно перемешать снизу вверх, при помощи силиконовой лопатки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Взять круглую формочку диаметром 24 сантиметра и обвести ее карандашом на пергаменте. Это основа для торта. Потребуется нарисовать шесть  кругов, на расстоянии приблизительно 4 сантиметра друг от друга. В процессе готовки коржи не должны соприкасаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Ровно распределить на кругах тонкий слой белковой смеси, помогая кондитерской лопаткой или ножом. Готовить коржи минут 20, соблюдая температуру 140-150 градусов. Вынуть коржи из духовки, если нужно выровнять края ножом и охладить. Приготовить крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Соединить желтки, сахар обыкновенный и ванильный, 1/3 часть молока и размешать до однородности. Остальное молоко налить в кастрюльку с толстым дном и довести до кипения на медленном огне. В кипящее молоко аккуратно добавить взбитые желтки, не переставая помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Снова довести до кипения, снять с огня. Остудить и отправить на 60 минут в холодильник. Взбить подтаявшее масло со сгущенным молоком и добавить в крем. Влить коньяк или вишневую водку, взбить и остудить. Приготовить глазурь: пять коржей смазать кремом, а последний корж покрыть тонким слоем джема, подогретого на водяной бане.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Растопить белый шоколад и смешать его до однородности со сливками. Полученной горячей массой покрыть джем. Чуть-чуть остудить. Растопить темный шоколад. Когда верх слегка застынет, с помощью кондитерского мешка, темным шоколадом по светлой поверхности торта нарисовать спиральки, от середины к краям.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4197,'Повторить процесс восемь раз, поделив, таким образом, торт на восемь частей. Снова поделить каждую часть, но в направлении от края к серединке. Рисунок будет похож на перышки. Бока обсыпать миндальной стружкой. Отправить торт «Эстерхази» в белом шоколаде, в холодильник, часов на 12. Достать минут за 15 до подачи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4198,'Залить желатин молоком и отставить минут на 60. Соединить сметану, творог, сахар и взбить миксером до однородности. Мелко нарезать фрукты. Подготовленный желатин нагреть на огне до растворения, но не кипятить. Все ингредиенты смешать в емкости, например, в силиконовой форме. Отправить легкий бланманже с фруктами на 5 часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4199,'Порезать лук полукольцами и замариновать в уксусе. Взбить  молоко с яйцами и приготовить тонкие блинчики. Охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4199,'Порезать соломкой окорочка и блины. Смешать все ингредиенты, посолить. Заправить салат «Солнечный» майонезом выложить на блюдо и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4200,'Соединить ванилин, тофу, корицу, молоко и соль, размешать венчиком. Разогреть сковороду с маслом. Все кусочки окунуть в молочную смесь и обжарить со всех сторон. Полить клюквенным соусом и кремом из кешью. Французские тосты с соусом из клюквы можно кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Желательно сделать заварной крем предварительно. Крем должен успеть охладиться и застыть. Соединить сахар, сливки и молоко, положить в смесь измельченный белый хлеб и подогреть, постоянно перемешивая, чтобы хлебные крошки разошлись.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Когда смесь начнет парить (станет сильно горячей), влить в нее тоненькой струей крахмал, разведенный 3 ст.л. воды. Быстро размешивая молочную смесь, прогревать ее до загустения. Снять крем с огня, перелить в посуду и отставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Пока крем остывает его необходимо периодически перемешивать, чтобы не образовалась корочка. Затем положить на крем полиэтилен, чтобы он не подсох, и отправить в холодильник на ночь или хотя бы на час. Приготовить блинчики: в воду насыпать дрожжи, сахар и минут на 5 отставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Дрожжи должны насытиться влагой. Размешивать до полного растворения дрожжей и сахара. Влить молоко, насыпать разрыхлитель и муку. Перемешать до однородности, чтобы разбить все комочки. Отставить массу на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Выпекать блины с одной стороны, на сковороде с антипригарным покрытием. Когда у блина подсохнет верх – он готов. Нагрев во время выпекания следует отрегулировать так, чтобы в процессе жарки, блинчик стал румяным и при этом не подгорел.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4201,'Сложить готовые блины внутрь не поджаренной стороной. Краешки слепить до центра. Используя кондитерский шприц, наполнить кармашек кремом. Украсить арабские блинчики «Катаеф» с кремом молотыми фисташками. Блинчики подать к чаю или кофе и кушать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4202,'Порезать мясо на ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4203,'Сварить макароны до полуготовности и откинуть на дуршлаг. Измельчить чеснок, нарезать лук и морковь. Цукини порезать на тонкие кружочки. Пассировать муку в сливочном масле, влить молоко и минут 5 проварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4203,'Убрать с плиты, добавить желтки и всыпать специи. Разогреть духовку до двухсот градусов. Обжарить цукини на растительном масле. Затем обжарить овощи: чеснок с луком и морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4203,'Положить томатную пасту. Смазать маслом форму и выложить слоями начинку, макароны и цукини. В сытную овощную запеканку с мясом влить приготовленный соус, посыпать сыром и отправить на 30 минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4204,'Смешать в однородную массу муку, яйца, майонез, молоко и соду. В форму, смазанную маслом, налить 1/2 часть теста, выложить филе семги, порезанное на кусочки, посыпать солью и перцем. Затем вылить остальную часть теста. Готовить заливной пирог с филе семги минут 40, соблюдая температуру 150 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4205,'Натереть крупно сыр. На тоненькие кружочки порезать сосиски. Смешать в однородную массу кефир, яйца, соль. Всыпать разрыхлитель, муку и размешать, чтобы исчезли комочки. Положить в смесь сосиски и сыр, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4205,'Выложить тесто в форму 25 на 25 сантиметров, смазанную маслом. Отправить в духовку и готовить минут 35, соблюдая температуру 180 градусов. Простой пирог с сыром и сосисками подавать теплым, но холодный он тоже хорош.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4206,'Тесто разморозить, пару полосок отложить. Оставшееся тесто чуть-чуть раскатать и положить в смазанную форму, сформировав бортики. Отложенные полоски скрутить в жгутики и уложить крест-накрест.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4206,'Получится четыре отсека для начинки. Выложить в них фрукты и ягоды. Если ягоды в замороженном виде, добавить крахмал, тогда они не растекутся. Фрукты можно присыпать сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4206,'Верх теста смазать желтком. Поместить слоеный пирог «Ягодное лукошко» в духовку и готовить минут 25, соблюдая температуру 180 градусов. Пирог остудить и присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4207,'Разогреть духовку приблизительно до 190 градусов. Вымыть, почистить картофель и нарезать на шайбы. Отваривать минут 5 в подсоленной воде. Слить воду. Нарезать шампиньоны  и лук кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4207,'Разогреть на сковороде чуть-чуть масла, бросить 1/2 часть лука. Положить грибы и жарить минут 7-8. Положить тимьян, соль и перец. Переложить смесь с шампиньонами в отдельную емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4207,'Обжарить остальной лук, добавить фарш и готовить минут 5. Добавить паприку, томатную пасту, сливки, посыпать перцем и солью. Размешать и готовить до закипания. Выложить грибы и тушить, еще несколько минут, все вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4207,'Положить в формочку 1/2 грибного фарша, потом слой картофеля, сверху остальной фарш. Посыпать сыром. Готовить слоеную мясную запеканку с грибами минут 30. Перед подачей можно посыпать измельченной зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4208,'Репчатый лук нарезать и обжарить на растительном масле. Добавить кислую нашинкованную капусту, перемешать и тушить под крышкой, до готовности. Помешивать, продукты не должны пригореть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4208,'Почти готовую капусту посыпать небольшим количеством пшеничной муки и перемешать. Половину готовой массы переложить в сотейник или в кастрюлю с толстыми стенками. Отдельно нарезать и обжарить разное мясо: годится свинина, телятина, гусятина, курица, кролик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4316,'Размять консервированного тунца в собственном соку с помощью вилки. Отварить и покрошить куриное яйцо, порубить зелень. Заправить смесь дижонской горчицей по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4208,'Выложить мясные продукты на капусту, распределить ровным слоем, накрыть оставшейся капустой. Блюдо украсить нарезанными солеными огурцами, корнишонами, сосисками, маринованными или солеными грибами, оливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4208,'Посыпать специями. При желании можно добавить грибы трюфели. Массу полить соусом, оставшимся от обжаривания, поставить в духовку и прогреть до готовности. Селянку московскую по-домашнему подать к столу в той же посуде, в которой селянка запекалась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4209,'Разогреть оливковое масло, обжарить рубленый репчатый лук, добавить пропущенный через пресс чеснок и перец чили в виде хлопьев. Продукты добавлять постепенно, делать паузы. Влить красное вино, довести до кипения. Оставить тушиться, половина жидкости должна вывариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4209,'Добавить нарезанные помидоры в собственном соку, соль, молотый перец, любые специи – по желанию. Тушить 15 минут, затем добавить рубленую зелень. Такой соус можно подавать на стол сразу или хранить несколько дней в холодильнике, перед использованием взбить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4209,'Форму смазать оливковым маслом, выложить слой готовых листов для лазаньи, купленных в магазине. Нанести половину сыра рикотты, выложить половину свежего измельченного шпината, полить небольшим количеством приготовленного соуса. Слои повторить, сверху должно быть тесто и соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4209,'Натереть сыр, посыпать  им блюдо и закрыть форму фольгой. Поставить в духовку на час, печь при температуре 175 градусов. Затем фольгу снять и допечь блюдо до образования золотистой корочки. Вынуть лазанью со шпинатом под соусом «Маринара» из духовки, дать постоять 10 минут и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4210,'Сухие дрожжи всыпать в теплую воду, оставить на несколько минут, они должны начать пениться. Добавить сахарный песок, молоко и сливочное масло. Ввести сырое куриное яйцо, дополнительный желток, тертую цедру апельсина и  соль. Всыпать просеянную пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4210,'Тесто вымешивать до состояния эластичности (оно должно остаться липким). Массу выложить в емкость, накрыть тканью, поставить в тепло для подъема, она должна увеличиться в 2 раза. Готовое тесто раскатать в лепешку прямоугольной формы и толщиной около полсантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4210,'Растопить сливочное масло, смазать тесто, посыпать корицей и сахаром, часть обычного сахара можно заменить ванилином. Скатать лепешку в рулет и нарезать на 12 кусочков одинаковой толщины. Отдельно разогреть мед и сливочное масло, перемешивать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4210,'Для выпекания понадобится форма или противень с высокими бортиками. Вылить масляно-медовую смесь в форму, посыпать орехами пекан, выложить булочки вплотную. Поставить заготовку в холодильник на ночь или на несколько часов, затем выпечь до готовности. Медовые булочки с орехами и корицей готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4211,'Свежую зелень укропа, петрушки, сельдерея, сладкий болгарский и перец чили вымыть и удалить семена. Очистить чеснок. Все подготовленные продукты пропустить через мясорубку и перемешать. Стеклянные банки хорошо вымыть и обдать кипятком. Разложить массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4211,'Вымыть помидоры, разложить в емкости с зеленью, можно использовать бурые, зеленые и красные плоды, но они не должны смешиваться в одной банке. Крупные плоды можно разрезать на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4211,'Для приготовления маринада вскипятить воду с сахарным песком, солью, лавровым листом, черным перцем-горошком, столовым уксусом. Смесь остудить, залить помидоры и закрыть крышками из пластмассы. Банки с помидорами «Невозможно оторваться» встряхнуть и поставить в прохладное помещение.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4212,'Баклажан, кабачок, цуккини, морковь вымыть и нарезать. На среднем огне, в сковороде или в кастрюле, разогреть оливковое масло. Обжарить рубленый репчатый лук до прозрачности, добавить морковь, тушить в течение 5-6 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4212,'Соль и перец – по вкусу. Добавить овощи, перемешать и прогревать еще 5-7 минут. Добавить томаты, рубленую зелень, влить две чашки воды и довести до кипения. Включить тихий огонь, накрыть крышкой, тушить 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4212,'Пропустить через пресс очищенный чеснок, перемешать с основной массой, блюдо посолить и поперчить, подать к столу. При подаче, ароматное рагу с кабачками и баклажанами, можно дополнительно посыпать рубленой зеленью петрушки, укропа, кинзы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4213,'Куриные грудки вымыть и обсушить. Смешать соль крупного помола, смесь разных перцев, коньяк или виски. В форму выложить половину смеси, затем грудки, посыпать остатками смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4213,'Емкость закрыть, поставить в холодильник на сутки. Куриный балык в коньячном маринаде вынуть, промыть и обсушить. Завернуть в льняную ткань, убрать еще на одни сутки в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4214,'Замороженный банан без кожуры, нежирный творог и две порции бананового протеина взбить с помощью блендера, миксера или другой кухонной техники похожего назначения. Масса должна превратиться в однородную смесь. Поместить в пластиковый контейнер, поставить на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4214,'Мороженое вытащить, перемешать, снова поставить в морозилку.  Мороженое должно медленно и равномерно застывать. Повторить операцию насколько раз, пока продукт не станет густым и не приобретет нужную консистенцию. Творожное мороженое на протеине можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4215,'Растворить желатин в воде так, как написано в инструкции, дать постоять. Протеин растворить в таком же количестве воды отдельно. Оба продукта смешать, разлить в формочки или в одну большего размера. Поставить протеиновый желейный десерт в холодильник на ночь, до полного застывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4216,'Из пергамента вырезать окружность по размеру формы, выложить на дно, смазать растительным маслом стенки. Отделить белки и взбить в стойкую пену, можно сделать это венчиком или с помощью блендера. В большой емкости, смешать сырые желтки, протеин шоколадный, добавить муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4216,'Муку всыпать порциями, по столовой ложке. Добавить погашенную лимонным соком пищевую соду. Добавить взбитые белки, перемешать движениями снизу вверх. Тесто должно получиться воздушным и жидким. Вылить массу в форму, поставить в духовку, разогретую до 150 градусов, время выпекания – 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4216,'Оставить готовое блюдо в выключенной духовке еще на 10 или 15 минут, вынуть, остудить. Разрезать выпечку по горизонтали, на два одинаковых коржа, острым ножом. Для приготовления крема смешать яйцо, муку, протеин шоколадный, долить молоко, поставить на тихий огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4216,'Довести до загустения помешивая, не кипятить. Всыпать тертый горький шоколад. Смазать полученным теплым кремом торт со всех сторон, остудить, посыпать тертым шоколадом. Шоколадный торт с заварным кремом на протеине можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4217,'Из куриных грудок приготовить фарш. Нарезать репчатый лук кубиками, добавить в фарш вместе с солью и специями, влить сырые куриные белки и перемешать. Смазать оливковым маслом форму для запекания, выложить половину приготовленного фарша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4217,'Сыр Холлендер нарезать брусочками, выложить на слой фарша, залить остатками. Сверху – ломтики сладкого перца. Печь в духовке в течение часа при температуре 240 градусов. Готовый куриный хлеб с сырной начинкой нарезать ломтиками и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4218,'Положить в кефир соль, соду, сахарный песок, добавить сыр. Размешать и всыпать муку. Замесить тесто. Сделать из теста шарики и раскатать, чтобы получились лепешки. Обжаривать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4219,'Из рыбы убрать кости и измельчить с помощью мясорубки. Вместе с рыбой перекрутить зелень. Добавить прессованный чеснок. Промыть рис и отварить до готовности, в подсоленной воде. Порезать мелко лук и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4219,'Приготовленные ингредиенты положить в фарш из рыбы. Посыпать солью и перемешать. На пару минут отправить в холодильник. Приготовить начинку: грибы измельчить и обжарить. Посолить. Отложить  часть грибов для соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4219,'Намочить руки и сделать из фарша лепешку. Выложить в середину обжаренные шампиньоны и сформировать котлету с начинкой внутри. Обвалять в панировочных сухарях и обжарить на сковороде до образования корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4219,'Чтобы приготовить соус, необходимо лук порезать на полукольца, и еще раз пополам. Крупно натереть морковь, добавить к луку и обжарить. Положить оставшиеся грибы. Развести в кипяченой воде томатную пасту (нарезанные томаты в собственном соку).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4219,'Добавить в овощи и посыпать солью. Довести соус до готовности. Уложить котлетки в форму и полить морковно-томатным соусом. Залитые соусом котлеты поставить на 20 минут в духовку. Рыбные котлеты в грибном соусе подать с гарниром и кушать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4220,'Мелко натереть морковь, лишний сок отжать, посыпать солью. Крупно натереть твердый сыр, добавить прессованный чеснок. Почистить от кожуры яблоко и порезать соломкой. Сбрызнуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4220,'Крупно натереть предварительно отваренную свеклу, сцедить сок. Выложить все подготовленные ингредиенты слоями, промазывая каждый майонезом. Обильно посыпать салат «Любовница» грецкими орехами и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4221,'Замесить мягкое тесто. Поделить его на маленькие шарики. Каждый шарик раскатать. Вареную колбасу нарезать на кружки, поделить каждый на 4 части. Выложить колбасу на тесто и защипнуть края. Обжаривать пирожки на сковородке, в масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4222,'Разбить яйца в емкость. Положить майонез и сметану. Размешать, добавить разрыхлитель. Медленно всыпать муку и размешать до однородности. Для приготовления начинки, отварить яйца, куриное филе и измельчить. Приготовить картофельное пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4222,'Яйца, курицу и картофельное пюре смешать. На дно формы постелить фольгу и смазать ее растительным маслом. Вылить в формочку 1/2 часть теста. Выложить начинку и налить остальное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4222,'Выпекать «Невесткин» пирог с курицей минут 30, соблюдая температуру 180 градусов. Проверить готовность зубочисткой. Когда появится румяная корочка, пирог достать и немного остудить. Перед подачей порционно нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4223,'Взбить подтаявшее масло, ванилин и сахарный песок, вбить яйца. Насыпать соль, муку, разрыхлитель и размешать. Положить изюм и овсяные хлопья.  Сформировать шарики и выложить на противень, застеленный пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4223,'Оставить между печеньями расстояние, потому что при выпечке они растекутся. Поместить противень в разогретую духовку и готовить 15 минут, главное не пересушить. Переложить готовое печенье с изюмом на решетку, дать остыть и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4224,'Разрезать одну грудку курицы вдоль, чуть-чуть отбить, посыпать перцем и солью. Оставшиеся две грудки пропустить через мясорубку. Получившийся фарш смешать со шпинатом, зеленью, добавить перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4224,'В отбитое мясо положить фарш и свернуть рулетом.  Рулеты, из курицы со шпинатом, обжарить на сковороде до румяной корочки. Затем выложить на противень и готовить еще 20 минут в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4225,'Уложить в банку укроп, листья вишни и смородины, измельченный корень хрена, чеснок, черный перец горошком и грибы. Залить все подготовленным заранее рассолом, закрыть крышкой и поместить на 3 суток в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4226,'Уложить все в кастрюлю, посолить и накрыть тарелкой. Поставить сверху груз. Если в помещении не жарко, то лучше оставить грибы на 24 часа в комнате, а затем поместить на 48 часов в холодильник, так грибы получатся более крепкие. Чем меньше грибы, тем меньше времени уйдет на их приготовление.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4227,'Вымыть куриное мясо, нарезать кусочками и положить в раскаленную кастрюлю с толстыми стенками. Обжарить. Добавить сливочное масло, измельченный и пассированный лук, влить вино и немного потушить. Добавить паприку, кориандр, соль, томаты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4227,'Можно долить немного воды, чтобы было сочнее. Тушить еще минут 30, накрыв крышкой, на маленьком огне. Измельчить зелень, чеснок и орехи. Положить орехи и чеснок в мясо и готовить еще минуты 3. Посыпать куриное чахохбили зеленью, размешать. Выключить огонь и дать постоять 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4228,'Отварить рис и яйца. Перемешать измельченную рыбу, рис, тертые яичные белки и перец, посолить и заправить майонезом. Мелко натереть морковь и желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4228,'Скатать из салата шарики, обвалять в измельченной зелени, желтках и моркови или просто в кунжуте. Оригинальные салатные шарики выложить на блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4229,'Положить в стаканы мороженое. Налить кока-колу, немного размешать, чтобы пена опустилась. Долить еще лимонада. Разлить коктейль «Черная вдова» по бокалам, посыпать тертым шоколадом и подать с трубочкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4230,'Порезать мясо ломтиками и отбить. Посыпать перцем и солью. Отложить отбивные в сторону. Приготовить кляр: яйца взбить, добавить перец, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4230,'Добавить прессованный чеснок. Обвалять отбивные со всех сторон в муке. Опустить их в кляр и жарить сочные отбивные в чесночном соусе до золотой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4231,'Почистить, нарезать и пожарить на сливочном масле лук. Убрать с печени пленку, промыть и добавить к луку. Обжарить печень. Внутри она должна быть розовой, главное не пересушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4231,'Залить печень сливками, посыпать перцем, солью и, несколько минут, потушить. Охладить, измельчить в блендере. Куриный паштет на сливках, намазать на хлеб и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4232,'Отварить грудку, вместо соли добавить соевый соус. Грудку охладить и измельчить. Желтки соединить с майонезом, добавить тертый пармезан, перец и куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4232,'Начинку выложить на ломтики сыра. Свернуть конвертом. Закуску можно украсить вареной морковью и огурцами. Оригинальная закуска «Каллы» готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4233,'Почистить и измельчить лук и чеснок. Снять с помидоров кожицу, предварительно ошпарив кипятком. Измельчить блендером или размять. Натереть сыр. Обжарить лук, добавить к нему фарш и 1/2 часть прессованного чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4233,'Обжарить, разминая фарш лопаткой, чтобы он стал рассыпчатым. Добавить размятые помидоры и готовить без крышки минут 15. Практически вся жидкость должна выпариться, но в то же время, фарш не должен быть сухим. Выключить огонь, приправить и положить оставшийся чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4233,'Отварить в подсоленной воде листы лазаньи. Если при варке добавить растительное масло, то листы не будут склеиваться. Выложить в форму слоями листы лазаньи и фарш. Таким образом выложить несколько слоев. Каждый слой фарша полить соусом «Бешамель» и посыпать сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4233,'Верхний слой накрыть листами лазаньи и промазать соусом. Готовить в духовке минут 40, соблюдая температуру 170 градусов. Незадолго до подачи посыпать сыром. Сделать температуру выше, чтобы сыр запекся. Мясную лазанью под белым соусом нарезать порционно и кушать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4234,'Замесить тесто: в емкость положить сметану, яйца, водку и соль. Хорошо размешать. Медленно всыпать муку и вымесить тесто. Оно должно быть плотным и эластичным. Накрыть тесто и отложить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4234,'Посыпать стол мукой и скалкой очень тонко раскатать тесто. Нарезать на ромбики по десять сантиметров. В центре ромбиков сделать надрезы по 5 сантиметров и продеть в надрез кончики теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4234,'Налить в сковороду растительное масло. Когда масло закипит положить в него заготовки так, чтобы они не прикасались друг к другу. Не стоит класть сразу много печенья, так как оно увеличиться в размере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4234,'Печенье быстро подрумянивается, поэтому нужно вовремя его переворачивать, чтобы не подгорело. Готовый хворост выложить на салфетку, чтобы впиталось масло. Смешать сахарную пудру с ванилином и посыпать печенье. Хрустящее печенье «Хворост» на водке готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4235,'Мелко натереть сыр и заранее отваренные яйца. На мелкие кубики порезать ветчину. В емкости смешать сыр, яйца, ветчину, майонез. Пополам разрезать помидоры черри. Порезать огурец на средние колечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4235,'Собрать все ингредиенты закуски в оригинальную композицию. На плоскую тарелку выложить измельченную зелень, она станет для мухоморов полянкой. Можно использовать любую зелень, которая оказалась под рукой: петрушка, укроп, лук и так далее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4235,'На зелень положить ломтики огурцов, они станут для грибов основанием. Из ветчины, сыра и яиц сформировать шарики. Приплюснуть шарики снизу и сверху, чтобы получился бочонок – это будет ножка гриба. Усадить ножки на основания из огурцов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4235,'На ножки одеть половинки помидоров черри – получатся красные шляпки. Нарисовать майонезом белые точки – закуска «Мухомор» приобретет законченный вид. Это можно сделать при помощи зубочистки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4236,'Промыть виноград и разрезать его пополам. Крупные ягоды можно разделить на четыре части. Нарезать ананас на кубики. Натереть сыр. Измельчить чеснок. Смешать все  ингредиенты, добавить в салат «Французских цыган» майонез и размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4237,'Насыпать муку в емкость, покрошить маргарин и растереть в крошку руками. Смешать сметану и желтки, всыпать сахар, соль и соду. Размешать. Переложить смесь в маргариновую крошку и замесить тесто. Выложить его на специальную бумагу и раскатать тонкий прямоугольник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4316,'Готовую пасту намазать на хлебцы. Украсить хрустящие хлебцы с тунцом, ломтиками свежего помидора и огурца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4237,'Разрезать тесто на две равные части, чтобы получилось два коржа. Выпекать минут 25, соблюдая температуру 220 градусов. Охладить. Орехи немного измельчить в блендере, смешать с вареным сгущенным молоком и размешать. Намазать смесь на один корж и накрыть вторым коржом сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4237,'Растопить в микроволновке или на водяной бане шоколад и вылить равномерно глазурь на корж, посыпать миндальными хлопьями или орехами. Поставить торт в холодильник для застывания, затем порезать его острым ножом. Получаются вкусные ореховые полоски с горьким шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4238,'Хорошенько вымыть и просушить все овощи. Поместить помидоры в кипяток секунд на 15, снять кожицу, убрать семена. Почистить перец, огурец и порезать овощи на маленькие кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4238,'Очистить и измельчить чеснок. Мякоть белого хлеба также нарезать на кубики. Положить подготовленные ингредиенты в большую емкость. Отдельно растолочь тимьян и добавить в овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4238,'Перемешать, посолить. Добавить уксус и лимонный сок. Измельчить все овощи в блендере и протереть через ситечко. Влить в традиционный овощной гаспачо оливковое масло. Разлить суп по тарелкам и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4239,'Духовку разогреть до 180 градусов. В одной емкости смешать муку, разрыхлитель, соль и соду. В другой емкости чуть-чуть взбить яйца, всыпать сахар и взбивать еще 30 секунд. Положить масло, ванилин и взбивать еще 60 секунд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4239,'Насыпать часть муки, затем ввести часть пахты, не переставая взбивать. Добавить остальную муку и пахту. Выложить тесто в формочки и выпекать минут 15. Готовность можно проверить зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4239,'Чтобы сделать шапки, необходимо взбить кремчиз и небольшое количество сахарной пудры. Отдельно взбить сливки. Соединить смеси и, с помощью корнетика, украсить кремом нежные капкейки с ароматом ванили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4240,'Смешать подготовленные ингредиенты и замесить тесто. Поставить на пару часов его в тепло. Раскатать готовое тесто. Смазать маслом противень, выложить на него пласт. Смазать майонезом и кетчупом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4240,'Приготовить начинку. Нарезать и обжарить подготовленные для начинки ингредиенты, за исключением помидор. Выложить обжаренную начинку на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4240,'Сверху разложить порезанные кружками помидоры и залить заливкой. Посыпать пиццу  тертым сыром и измельченной зеленью. Домашняя овощная пицца под сыром готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4241,'Кабачки почистить от семян и кожуры, нарезать на кубики. Почистить и порезать на мелкие кубики морковь (можно крупно натереть). Чтобы консистенция икры была нежнее, с помидор лучше снять кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4241,'Для этого на помидоре нужно сделать надрез и опустить его на 30 секунд в кипяток. После снятия кожицы нарезать помидоры. Измельчить лук и обжарить его на растительном масле.  Когда он станет прозрачным, добавить морковь и готовить минут 7.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4241,'Добавить кабачки, потушить минут 10, помешивая время от времени. В конце положить помидоры и посыпать солью. Тушить овощи еще 10 минут. За несколько минут до окончания готовки, положить измельченный чеснок и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4241,'Если икра предназначена для консервирования, то добавить на каждый килограмм кабачков по 1 чайной ложке столового уксуса. Измельчить овощи в блендере. Перед употреблением домашнюю икру из кабачков и помидоров охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4242,'Духовку разогреть до 180 градусов. Просеять в посуду муку. Добавить какао, сахар, разрыхлитель, молоко, масло и яйца. Перемешать миксером и поделить тесто на две части. Вылить половину теста в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4242,'Поставить форму минут на 7 в разогретую духовку. Когда первый корж будет готов, выпечь второй корж. Приготовить крем: в теплой воде развести кофе. Хорошенько взбить сливки, добавить кофе и чуть-чуть взбить. Собрать торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4242,'Для этого положить корж на плоское блюдо и смазать сливками, накрыть вторым коржом. Смазать торт оставшимися сливками и посыпать тертым шоколадом. Отставить, чтобы коржи пропитались. Через пару часов торт «Мокко» с темным шоколадом можно кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4243,'Смешать в блендере оливковое масло, перец, мяту, сахар, бальзамический и белый винный уксус, соль, тимьян, измельчить до получения грубой кашицы. Смазать кашицей ногу барана, с которой предварительно срезать жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4243,'Мясо в маринаде, обернуть в фольгу и на несколько часов отправить в холодильник. Затем положить баранью ногу на противень и поместить в разогретую до 220 градусов духовку, на 15 минут. Затем уменьшить температуру до 180 градусов и готовить еще 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4243,'Потом, повысить температуру снова до 220 градусов и оставить мясо на 10 минут в духовке. Вынуть баранью ногу в мятном маринаде и нарезать мясо на тонкие ломтики. Подавать с овощами, обжаренными на гриле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4244,'Прокрутить печень в мясорубке, всыпать муку, добавить соль, перец, яйцо и сметану. Перемешать и выпечь на сковороде тонкие печеночные коржики. Приготовить начинку: измельчить лук и чеснок, мелко натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4244,'Обжарить лук с грибами, отдельно — лук и морковь. Сформировать слоеный торт. Взять печеночный корж, смазать майонезом и выложить на него, очень тонким слоем, обжаренный с морковью лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4244,'Положить следующий корж, смазать майонезом и выложить грибы, обжаренные с луком. Выложить, таким образом, остальные коржи. Сверху, нежный печеночный торт с грибами, смазать майонезом, украсить кружочками помидоров и зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4245,'Измельчить в блендере, в однородную массу, свежую клубнику. Если клубника замороженная, то чуть-чуть разморозить и измельчить прямо с соком. Положить в клубнику желатин и оставить, чтобы он слегка набух.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4245,'Добавить сок лимона, сахарную пудру, перемешать и нагреть на маленьком огне. Варить, пока желатин не растворится (не кипятить). Охладить и взбивать миксером минут 6, чтобы получилась густая, светлая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4245,'В форму для застывания постелить специальную бумагу и вылить клубничную смесь. Разровнять и поставить на 6 часов в холод. Достать домашний рахат-лукум с клубникой из формы, посыпать сахарной пудрой и порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4246,'Взбить яйца с сахаром. Влить кефир, посолить, всыпать муку, соду и размешать. Должно получиться пышное, легкое тесто. Порезать яблоки на мелкие ломтики. Ложкой выложить тесто на сковороду с разогретым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4246,'На оладьи положить кусочки яблок и прижать ложкой. Обжарить со всех сторон. Переложить готовые оладьи на блюдо, присыпать корицей и сахарной пудрой. Оладьи на кефире с корицей и яблоком можно кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4247,'Нарезать баклажаны на полоски. Хвостики не отрезать. Между полосками выложить кружочки помидоров и ломтики сыра. Смешать майонез с чесноком и смазать баклажаны. Выпекать до готовности. Оригинальные запеченные баклажаны выложить на блюдо и кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4248,'Промыть мясо и нашпиговать его чесноком, разрезав каждый зубчик на несколько частей. Сделать маринад из прованских трав, сухой горчицы, соли и оливкового масла. Размешать. Положить говядину часа на 2 в маринад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4248,'Запекать мясо, в рукаве, при температуре 180 градусов 50 минут. Подавать сочную говядину с прованскими травами, можно с любым соусом. Прекрасно сочетается с рисом и овощным салатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4249,'Промыть филе и порезать на кусочки. Слить жидкость с консервированных шампиньонов. Измельчить лук. Разогреть оливковое масло и пожарить в нем лук, добавить кусочки курицы, а через 3 минуты нарезанные грибы. Затем добавить морковь, нарезанную кубиками, фасоль, горошек и еще немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4249,'Довести бульон до кипения и вылить в сковороду. Все перемешать, положить томатную пасту. Тушить минут 20, после этого насыпать промытый рис, накрыть крышкой и готовить 20 минут. Посолить, поперчить и добавить шафран. Испанскую паэлью с куриным филе можно подавать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4250,'Почистить картофель. Отварить, подсолив воду. Из картофеля сделать пюре. Крупно натереть сыр, очистить морковь и натереть на мелкой терке, измельчить крабовые палочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4250,'Положить в пюре палочки, морковь, муку, яйца, тертый сыр, специи, зелень и соль. Перемешать. Сделать котлетки, обвалять в сухариках и обжарить. Картофельные котлеты «Минимум затрат» готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4251,'Перемешать ингредиенты для теста и замесить. Испечь пять коржей, один разломать в крошку для  посыпки салата. На плоское блюдо положить корж, сверху выложить тертый сыр, смешанный с майонезом. На второй  корж выложить рыбу с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8642,'Полученным кремом промазать готовые блины, верх украсить тертым темным шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4251,'На следующий корж — предварительно отваренные и измельченные яйца с жареным луком и майонезом. Последний корж намазать майонезом и посыпать крошкой. Оставить на ночь, чтобы пропитался. Разрезать оригинальный слоеный салат «Наполеон» на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4252,'Подготовить блинчики. Рис и яйца отварить. Сыр натереть на терке. Для начинки смешать рис, измельченные яйца, сметану, рубленую зелень и часть сыра. По желанию можно добавить обжаренный лук. Выложить немного начинки на каждый блин и заворачивать трубочкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4252,'Положить блинчики в формочку для запекания. Порезать соломкой ветчину, и выложить поверх блинов, присыпать сыром. Готовить минут 20, соблюдая температуру 180 градусов. Подать на стол фаршированные блины под сыром, из духовки, и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4253,'Положить в кастрюлю соль и масло. Влить воду. Поставить на огонь и держать, пока не растопится масло. Убрать с плиты и всыпать муку. Вернуть на огонь и, постоянно помешивая, нагревать, пока тесто не приобретет однородность, и не начнет отставать от краев кастрюли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4253,'Снять с огня. Вбить в кастрюлю яйца (по одному), после каждого хорошо перемешивать. Положить тесто в кондитерский мешок. Противень застелить пергаментом и отсадить на него небольшие булочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4253,'Если мешочка нет, то выкладывать тесто можно обыкновенной ложкой. Поставить противень в духовку и минут 20 выпекать, соблюдая температуру 200 градусов. Должна получиться аппетитная корочка. Вынуть профитроли и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4253,'Приготовить начинку: порезать на маленькие куски рыбу. Сыр размять вилкой и смешать с измельченным укропом. Добавить рыбу и размешать. Срезать с булочек верх, наполнить начинкой. Накрыть профитроли, со сливочно-лососевым кремом, срезанными верхушками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4254,'Отварить до готовности рис. Измельчить в блендере капусту. Смешать рис и капусту с куриным фаршем. Вбить яйца, посыпать специями и солью. Сформировать шарики. Выложить их на противень, залить смесью сметаны и томатного сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4254,'Плотно накрыть фольгой. Готовить в духовке минут 40. Снять фольгу и запекать тефтели куриные под томатным соусом еще минут 7. По желанию добавить в подливку морковь и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4255,'Готовый куриный фарш перемешать с тертым чесноком и сыром, сырыми куриными яйцами, панировочными сухарями, орегано, солью и перцем. Массу хорошо вымешать, разделить на 24 части. Сформовать лепешки, в центр каждой положить по шарику моцареллы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4255,'Края завернуть на сыр и скатать круглую фрикадельку. Обвалять в муке. То же проделать с остальным сыром и фаршем. На сильном огне разогреть немного растительного масла, обжарить фрикадельки до золотистой корочки, со всех сторон. Переложить изделия на противень, поставить в разогретую духовку на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4255,'Печь при температуре 180 градусов. Для приготовления соуса мелко порубить репчатый лук и очищенные зубчики чеснока. На среднем огне разогреть столовую ложку растительного масла, обжарить сначала лук, затем добавить чеснок и орегано, перемешать и жарить еще минуту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4255,'Влить консервированные и размятые помидоры в собственном соку, довести до кипения и тушить, без крышки, в течение 10 минут, соус должен выпариться, загустеть. Соль и сахарный песок – по вкусу. Подать домашние фрикадельки с моцареллой, с томатным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4256,'Натереть твердый сыр и охлажденное сливочное масло на мелкой терке, хорошо перемешать. По желанию в массу можно положит кунжутное семя или тмин. Посолить по вкусу, добавить молоко и лимонную цедру, еще раз перемешать. Всыпать просеянную пшеничную муку, замесить тесто, оно должно быть мягким и эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4256,'На рабочей поверхности, посыпанной мукой, раскатать массу в пласт, толщина – полсантиметра. Нарезать лепешку на полоски, каждую полоску скатать в трубочку руками. Выложить изделия на пергамент, печь в духовом шкафу при температуре 180 градусов в течение 15 минут, до золотистого цвета. Соломку сырную остудить и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4257,'В небольшой емкости смешать свежую нарезанную клубнику и сахарный песок. Если ягоды мелкие, то их можно не резать. Варить на тихом огне в течение 5-8 минут, клубника должна стать мягкой. Отдельно развести кукурузный крахмал в небольшом количестве холодной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4257,'Добавить в соус и проварить несколько минут, масса должна загустеть. Соус немного охладить и разлить в креманки. Манную крупу обжарить со сливочным маслом до образования золотистого цвета и орехового аромата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4257,'Крупу нужно помешивать, чтобы она прогрелась равномерно. На процесс обжаривания уйдет 6-7 минут. Довести до кипения молоко, всыпать манную крупу и варить, помешивая, в смеси не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4257,'Всыпать сахарный песок, масса должна получиться густой. Остудить и добавить немного молотого кардамона. Выложить манный слой, на клубничный. Обжарить на сухой сковороде миндальные лепестки. Посыпать ими клубнично-манный пудинг сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4258,'Растопить и немного остудить сливочное масло. Всыпать коричневый сахар и ванилин из пакетика. Можно использовать обычный сахар, на вкусе блюда это не отразится. Отдельно, с помощью вилки, взбить сырые куриные яйца, соединить их с масляной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4258,'Всыпать просеянную пшеничную муку вместе с солью и разрыхлителем. Добавить шоколадные капли (тертый шоколад) и сушеную вишню, перемешать, тесто должно быть немного липким. Прямоугольную форму для выпекания застелить пергаментом, выложить готовое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4258,'Разровнять тесто и печь в течение 40 минут при температуре 180 градусов. Выпечка должна покрыться румяной корочкой. Вынуть из духовки, нарезать на небольшие квадраты, подавать печенье с вишней и шоколадной крошкой в теплом или холодном виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4259,'Приготовить куриный фарш, смешать с мелко нарезанным луком-репкой, можно пропустить его через мясорубку. Вбить сырое яйцо для связки, соль и молотый перец – по вкусу. Разморозить, купленное в магазине, слоеное тесто. Раскатать массу в пласт толщиной полсантиметра и нарезать тонкими полосками, на посыпанной мукой доске или столе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4259,'Из фарша сформовать котлетки. Обмотать их полосками слоеного теста, выложить на застеленный бумагой противень. Заготовки для выпечки смазать взбитым желтком. Печь в разогретой до 180 градусов духовке в течение 30 – 40 минут, до образования золотистой корочки. Оригинальные куриные котлеты «Клубочки» подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4260,'Огурец очистить от кожицы, нарезать мелкими кусочками. Чеснок очистить и пропустить через пресс, мелко порубить зелень укропа. Смешать все подготовленные ингредиенты, добавить соль по вкусу, заправить сметаной. Легкий огуречный салат со сметаной можно кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4261,'Отварить говядину, разобрать её на волокна. Соленые огурцы натереть на крупной терке, очищенный чеснок пропустить через пресс. Перемешать. Отварить куриные яйца, очистить, порубить или натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4261,'Рубленые на кусочки грецкие орехи обжарить на сухой сковороде. Выложить салат слоями: мясо, огурцы с чесноком, отварные яйца, орехи. Все слои промазать майонезом. Поставить слоеный мясной салат «Принц» в холодильник для настаивания, на час или два.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4262,'Для приготовления опары смешать теплое молоко, 3 ст.л. пшеничной муки, сахарный песок и пакет быстродействующих дрожжей. Дать смеси постоять в тепле в течение 15 минут. Добавить в опару треть стакана растительного масла, и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4262,'Порциями всыпать оставшуюся пшеничную муку и замесить мягкое тесто, оно не должно липнуть к рукам. Накрыть готовое домашнее тесто на дрожжах влажной тканью и поставить в тепло на 15 минут. Можно готовить из него сразу или дать постоять еще полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4263,'В небольшой емкости смешать соль и сахарный песок, тертый корень очищенного имбиря и васаби. В полученную массу выложить филе семги с кожей, она должна быть сверху. Накрыть блюдо крышкой и поставить в холодильник на сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4263,'Рыбу вынуть, промыть под проточной холодной водой, обсушить с помощью бумажных полотенец. Смешать васаби с майонезом, масса должна быть однородной. Подать соус к семге отдельно, в соуснике. Имбирная семга с соусом васаби готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4264,'Курицу разделать на небольшие кусочки. Приготовить маринад из давленого чеснока, томатной пасты, соевого соуса и жидкого меда. Смесь хорошо перемешать, залить куриное мясо, поперчить по вкусу и оставить на полчаса. Очистить и нарезать сладкий болгарский перец соломкой, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8665,'Смешать в миске оливковое масло, лимонный сок, горчицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4264,'Измельчить листочки свежей мяты, базилика, несколько листьев оставить для украшения. Разогреть на сковороде растительное масло, обжарить курицу со всех сторон. В кастрюлю или жаровню положить мясо и овощи слоями.  Сначала курицу, затем лук с перцем, курица, сверху – лук с перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4264,'Каждый слой поперчить по вкусу. Подлить остатки маринада и воду. Тушить блюдо в течение 20 минут. При необходимости – посолить. Огонь выключить, положить рубленую зелень базилика и мяты, дать постоять 5-7 минут. Куриное рагу в соево-медовом маринаде выложить на блюдо и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4265,'Нарезать кубиками репчатый лук, снять кожицу со свежих и консервированных помидоров. Заранее разморозить мидии в холодильнике, дать стечь жидкости. Лук обжарить на оливковом масле, добавить томатную массу, прогреть в течение нескольких минут и размять массу лопаткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4265,'Всыпать свежий или сушеный орегано, влить белое сухое вино. Прогревать в течение 10 минут на тихом огне. Добавить нарезанный перец чили, семена удалить. Всыпать сушеный базилик, соль и сахарный песок, через десять минут – растаявшие мидии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4265,'Соус уварить на тихом огне до нужного состояния. Отдельно отварить спагетти, лучше брать тонкие сорта, воду подсолить. Откинуть, дать стечь воде, выложить на тарелку, сверху – мидии в соусе. Готовые спагетти с мидиями в винном соусе, поперчить по вкусу и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4266,'Филе курицы нарезать на порции, отбить, посолить, приправить по вкусу. Для приготовления кляра взбить сырые куриные яйца, добавить майонез, специи, соль, рубленый свежий укроп. Массу хорошо перемешать и всыпать порциями муку. Должно получиться полужидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4266,'Натереть сыр на крупной терке. Отбивную обмакнуть в кляр с одной стороны, выложить на сковороду этой стороной вниз, сверху – сыр, налить ложкой немного кляра, так, чтобы сыр оказался внутри. Жарить отбивные из курицы в кляре до готовности, с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4267,'Грудку накрыть пищевой пленкой и отбить тупой стороной ножа. Соль и перец – по вкусу. Обмакнуть в сырой куриный белок со всех сторон и густо посыпать кунжутным семенем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4267,'Обжарить куриную грудку в кляре из кунжута в течение 3 минут, под крышкой. Можно сделать это без масла, на сковороде-гриль или с маслом, его нужно взять совсем немного, достаточно столовой ложки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4268,'Перемешать сырые куриные яйца, дополнительные белки, протеин. Выпечь на сковороде с антипригарным покрытием три коржа-блинчика, каждый обжарить с двух сторон. Приготовить крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4268,'Для этого перемешать хороший домашний творог, куриные белки и протеин. Взбить крем с помощью блендера, промазать им коржи, покрыть верх и бока торта. Поставить белковый торт с творожным кремом на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4269,'Грудки посолить, обжарить с половиной нормы сливочного масла, полить лимонным соком. На оставшемся сливочном масле обжарить нарезанные грибы с рубленым чесноком. Массу выложить на грудки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4269,'В сковороду, на которой жарилось мясо, добавить сливки, прогреть соус до загустения, не кипятить. Полить смесью грудки, подать к столу. Куриные грудки с чесноком и грибами можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4270,'Для приготовления куриных грудок в беконе нужно сделать разрез между мышцами — карман. Положить тертый копченый сыр, например, колбасный. Каждую грудку запеленать в тонкие полоски свиного бекона, под грудинку положить веточки кинзы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4270,'Солить не нужно, положить изделия на лист фольги и печь в течение 35 минут до образования румянца. Куриные грудки с копченым сыром выложить на  блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4271,'Приготовить куриную грудку с рисовой лапшой. Филе вымыть. Приготовить овощной бульон, подлить в него светлый соевый соус и отваривать мясо в течение 12 минут. Рисовую лапшу замочить в горячей, но не кипящей воде, через 15 минут продукт откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4271,'Тонкими полосками нарезать очищенную морковь, сладкий болгарский перец и луковую зелень. Очистить и нарезать корень сельдерея, порубить острый перец чили. Из бульона вынуть мясо, добавить подготовленные овощи, варить в течение четырех минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6311,'Отправить форму в духовку на минут шестьдесят, соблюдая температуру 180 градусов. Проверять готовность ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4271,'Соль и перец добавить по вкусу. Курицу измельчить, положить в бульон и быстро прогреть. Готовую лапшу разложить в тарелки, сверху – мясо и овощи. Куриные грудки с рисовой лапшой полить маслом кунжута и подать, можно украсить кориандром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4272,'Для этого нужно отварить рис с приправами, но без соли. Обжарить куриные грудки. От консервированных ананасов отцедить сок. Выложить продукты на сковороду слоями: рис, ананас, поперчить или посыпать любыми сухими травами, сверху – курица. Куриные грудки с рисом и ананасами полить соком от ананасов, посолить и тушить под крышкой, в течение 15 минут, в духовке или на плите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4273,'Куриную грудку можно приготовить со спаржей. Мясо приправить по вкусу, обжарить на оливковом масле и тушить под крышкой в течение 15 минут. Верхушки зеленой спаржи срезать и разрезать их пополам, вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4273,'Опустить в кипящую подсоленную воду на 3 минуты, обдать холодной водой. Очистить и нарезать клубни картофеля кубиками, небольшого размера. Обжарить их на небольшом количестве масла, влить овощной бульон и тушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4273,'Влить бальзамический уксус, посолить, поперчить, добавить оливковое масло. Смесью полить нарезанные кубиками помидоры и зелень. Разложить спаржу и мясо по тарелкам, полить приготовленным теплым томатным соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4274,'Грудку вымыть, обсушить, нарезать длинными кусочками средней толщины. Залить продукт кефиром, подсолить, посыпать специями, поставить в холодильник для маринования на 1,5-2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4274,'Мелкую овсяную крупу смешать с сухими травами и молотой паприкой. Мясо обвалять в овсяной смеси, выложить на противень или в посуду и запечь в духовке при температуре 180 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4275,'Перемешать обезжиренный творог, казеин, яичный белок и целое сырое куриное яйцо. Выложить массу в форму, поставить в духовку, печь при температуре 180 градусов в течение 10 – 15 минут. Творожный пирог с казеином немного остудить и кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4276,'Филе рыбы разрезать на четыре части. Очистить и нашинковать кружочками морковь. Стебель сельдерея и лук-репку разрезать на четыре части, лимон – тонкими ломтиками. Лимон и овощи положить в сотейник, влить полтора литра воды, довести на сильном огне до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4276,'Пламя уменьшить, поварить овощи под крышкой в течение 8 минут. Положить рыбу, снова накрыть крышкой и тушить еще 5 минут. Овощи с припущенным лососем выложить на блюдо и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4277,'Перемешать обезжиренный творог, сырое куриное яйцо плюс дополнительный белок, апельсиновый протеин. Массу разложить в формы и поставить в духовку на 20 – 30 минут, печь до готовности. Творожные протеиновые кексы подать к чаю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4278,'С помощью кофемолки перемолоть сухие овсяные хлопья или использовать готовую овсяную муку. Отделить белок от желтка. К белку добавить сухой сывороточный протеиновый порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4278,'Перемешивать массу с помощью миксера, в течение 1 — 2 минут, до однородности. Порошок должен полностью раствориться. Натереть щепотку апельсиновой цедры и добавить в массу вместе с творогом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4278,'Всыпать овсяную муку и дать немного постоять, продукт должен немного набухнуть. Вафельницу сбрызнуть спреем для выпечки, налить тесто, испечь вафли. Протеиновые вафли с апельсином подать на стол в качестве десерта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4279,'Куриную грудку и шампиньоны измельчить с помощью блендера или мясорубки. Налить воду в сковороду, добавить красный молотый перец и соль, любимые специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4279,'Сформовать небольшие котлетки, опустить в воду. Тушить, поворачивая, с каждой стороны по 3-5 минут. Огонь – средний. Диетические котлеты с шампиньонами готовы. Приятного аппетита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4280,'Смешать овсяную крупу, ряженку или кефир, яичный белок, хорошо вымытый изюм без косточек, какао-порошок. Добавить молотую корицу и ванилин из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4280,'Тесто выложить в виде печенья на пергамент или фольгу, печь в течение 20 – 25 минут при небольшой температуре. Овсяное печенье с изюмом немного остудить и подать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4281,'Грудку измельчить с помощью мясорубки или блендера, добавить куриный белок, специи: черный перец, кориандр, базилик, молотый чеснок. Соль – по вкусу и по желанию. Массу хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4281,'Для скатывания рулета понадобится циновка для приготовления суши и полиэтиленовый пакет. На пакет намазать куриный фарш толщиной в полсантиметра или чуть больше. Отдельно обжарить шампиньоны или опята.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4281,'Выложить начинку на курицу, свернуть в рулет с помощью циновки, края фарша должны соединиться. Осторожно перенести пряный куриный рулет с шампиньонами в форму для запекания или на противень, печь в течение 20 – 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4282,'Яичные белки взбить со свежим лимонным соком. Добавить сахарозаменитель порциями, продолжать взбивать в плотную пену. Если сахарозаменитель в таблетках – его нужно растворить в небольшом количестве горячей воды, а затем остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4282,'Выложить на противень бумагу для выпечки. Массу для безе выкладывать чайной ложкой или при помощи кондитерского шприца. Печь при температуре 100 градусов в течение часа. Духовку выключить и оставить домашнее безе еще на 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4283,'Промыть куриное филе, нарезать на мелкие кусочки. Хорошо взбить белки. Смолоть семена льна. Все подготовленные ингредиенты перемешать, добавить льняную клетчатку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4283,'Застелить форму для выпекания бумагой. Куриную массу выложить на противень и посыпать кунжутным семенем. Печь куриный хлеб, в течение 40 минут, при температуре 140 градусов, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4284,'Сырой куриный желток смешать с кефиром. Овсяную крупу перемолоть в муку. Белки взбить с сахарозаменителем и смешать с основной массой. Всыпать пищевую соду, овсянку, ванилин из пакетика, протеин. Вылить массу в разъемную форму и выпечь при температуре 160 градусов. Готовность торта проверить с помощью зубочистки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4284,'Для приготовления начинки ежевику выложить на корж, вместе с соком. Залить холодной водой желатин, дать набухнуть, через полчаса прогреть, до кипения не доводить. Остудить, смешать с йогуртом, творогом, заменителем сахара, протеином. Поставить в холодильник до почти полного застывания. Застывшую массу намазать поверх слоя ежевики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4284,'Для верхнего слоя торта смешать еще одну порцию замоченного желатина с йогуртом и протеином, убрать в холодильник до загустения, затем налить на десерт. Готовое изделие поставить на ночь в холодильник. Осторожно отделить протеиновый торт с ежевикой от стенок формы ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4285,'Морковь и брокколи нарезать, тушить в течение десяти минут или прогреть до готовности в пароварке. Нарезать полосками куриную грудку, смешать с овощами, сбрызнуть лимонным соком, полить оливковым маслом. Отдельно отварить куриное яйцо, очистить, покрошить желток и посыпать им овощную смесь с курицей. Куриные грудки с капустой брокколи выложить на блюдо и подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4286,'Очистить крупный картофель, нарезать кубиками, оба вида капусты разобрать на соцветия и кочанчики. Мелко порубить очищенный репчатый лук. Разогреть на сковороде оливковое масло в течение 7-8 минут. Заранее приготовленный овощной бульон перелить в большую емкость, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4286,'Добавить одновременно все овощи, соль. Огонь убавить и варить в течение получаса. Снять суп с огня, немного остудить и взбить блендером до состояния однородности. Легкий крем-суп из овощей разлить по тарелкам и кушать. Приятного аппетита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4287,'Вымыть яблоко, отрезать верх, аккуратно вынуть внутреннюю часть. Перемешать творог, подсластитель, молоко, ванилин. Масса по консистенции должна напоминать густую сметану. Духовку прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4287,'Готовый творожный крем выложить в яблоко, поставить в духовку на 20 – 30 минут. Чтобы запеченные яблоки с творожным кремом не теряли влагу, для приготовления и подачи лучше использовать силиконовые и бумажные формочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4288,'Натереть крупную морковь, кабачок цуккини и репчатый лук на крупной терке. Смешать овощную массу с куриным фаршем, сырым яйцом или только белком, специями по вкусу. Смочить руки холодной водой и сформовать небольшие котлеты круглой формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4288,'Запечь до золотистого цвета в духовке, при температуре 180 градусов. Должна образоваться золотистая корочка. Время приготовления нежных курино-овощных котлет примерно 20 – 30 минут, оно зависит от их величины и толщины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6319,'Под холодной водой промыть цветную капусту, разделить на некрупные соцветия, помидоры порезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4289,'Часть овсяных хлопьев обжарить на сковороде без масла до коричневато-золотистого цвета. Предварительно замочить сушеную курагу. Две трети сухофруктов перемешать с хлопьями, свежим очищенным и натертым имбирем, цедрой одного апельсина и молотой корицей. Перемолоть с помощью блендера. Масса должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4289,'Оставшуюся курагу мелко нарезать, смешать с любимыми рублеными орехами. Из основной массы сформовать большой прямоугольник, максимально его уплотнить и дать постоять для пропитывания. Разрезать на квадратики одинакового размера. Обвалять квадратики из овсяных хлопьев в какао и подать на стол, к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4290,'Отварить до полуготовности цветную капусту. Форму для выпекания смазать растительным маслом. На дно выложить нарезанный кусочками стеблевой сельдерей или морковь. Полить овощ натуральным йогуртом или нежирной сметаной, посыпать тертым твердым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4290,'Следующий слой – соцветия капусты, соль, ароматные травы. Вновь полить сметаной или йогуртом и посыпать оставшимся сыром. Готовить диетическую запеканку под сыром при температуре 180 градусов, до получения румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4291,'Заранее приготовленный куриный бульон довести до кипения, всыпать длиннозерный рис, перемешать. Огонь убавить, варить полуприкрытым до мягкости риса. Отдельно взбить куриные белки, добавить желтки, взбивать смесь до тех пор, пока смесь не станет кремообразной. Добавить лимонный сок и продолжать взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4291,'Небольшими порциями, чтобы смесь не свернулась, добавлять рисовый суп и одновременно взбивать массу миксером. Вылить крем в суп, мешать до загустения, суп не должен закипать. Посолить и поперчить блюдо по вкусу, подать греческий суп «Авголемоно» горячим, посыпать мелко нарубленной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4292,'На небольшом количестве растительного масла обжарить нарезанный кольцами репчатый лук и мелко нарезанный сладкий перец. Добавить заранее отваренные грибы, подержать на огне 5 минут, помешивая. Продукты должны стать мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4292,'Отдельно, в глубокой сковороде с толстым дном или в казане, разогреть масло и обжарить рис до золотистого оттенка. Залить бульоном и варить на среднем огне до впитывания влаги. Добавить грибы, прогреть все вместе на тихом огне в течение 2 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4292,'Посыпать почти готовое блюдо рубленой петрушкой, зеленым луком, базиликом, сыром пармезан, молотый перец и соль – по вкусу. Грибное ризотто с сыром пармезан перемешать, потомить под крышкой и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4293,'Грудку вымыть и просушить. В небольшой емкости соединить соль, черный молотый перец, орегано, паприку. Можно использовать и другие любимые специи. Смесью хорошо натереть мясо, оставить на 10 минут. Разогреть на сковороде немного оливкового масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4293,'Положить грудку, обжарить с двух сторон до появления румяной корочки, на это потребуется по 2-3 минуты. Духовку разогреть, застелить противень или форму фольгой, сложенной в несколько раз. Чеснок очистить и пропустить через пресс, можно использовать как свежий, так и сушеный продукт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4293,'Сверху налить оливковое масло, оставшееся от обжаривания курицы. Фольгу завернуть конвертом. Выпечь блюдо в духовке, сначала на среднем огне, через 20 – 25 минут его увеличить и довести кушанье до готовности при сниженной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4293,'В результате такой ступенчатой тепловой обработки буженина хорошо пропечется и пропитается специями. Готовую, пряную буженину из куриной грудки осторожно вынуть из фольги и нарезать кусочками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4294,'Отварить заранее зеленую чечевицу, нарезать спелое авокадо, листья хорошо промытого и обсушенного шпината. Смесь посолить, полить лимонным соком и оливковым маслом. Салат из чечевицы с мандаринами, украсить зернами граната и кружками мандарина, нарезанными поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4295,'Для приготовления теста охлажденное сливочное масло нарезать крупными кусками, насыпать сверху просеянную муку, щепоть соли, порубить все вместе в крошку средней величины с помощью ножа. Массу быстро перетереть руками, пока она не согрелась, и выложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5099,'Положить, не разрезая, свиной окорок в большую емкость, залить луково-чесночным маринадом, плотно закрыть и поставить мариноваться на холод (10-12 часов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4295,'Затем влить очень холодную воду, быстро замесить. Форму для выпекания застелить пергаментом, выложить тесто, равномерно распределить его руками по всей поверхности, в том числе и по бокам. Поставить заготовку в холодильник. Для приготовления начинки очистить морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4295,'Молодой кабачок и цукини нарезать тонкими полосками вместе с кожурой, таким же образом поступить с корнеплодом. Можно воспользоваться овощерезкой или овощечисткой, нарезка должна быть одинаковой по ширине, полоски кабачка и цукини могут быть чуть толще.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4295,'В охлажденное тесто выложить овощи, начинать нужно с краев, постепенно продвигаясь к центру, продукты чередовать. Приготовить заливку: взбить венчиком сырое яйцо, подлить молоко, снова взбить. Добавить рубленый чеснок, тертый сыр, соль – по вкусу. Массу хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4295,'Вылить смесь на овощи, посыпать пирог оставшимся тертым сыром. Постучать формой о стол, чтобы заливка затекла между полосками овощей. Разогреть духовой шкаф до температуры 180 градусов, печь оригинальный овощной пирог с сыром в течение часа, до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4296,'Шампиньоны нарезать кусочками, обжарить на растительном масле в течение 5 минут. Морковь большого размера натереть на средней терке, добавить в грибы и жарить все вместе еще столько же. Подлить еще немного масла, всыпать рис. Массу перемешать, рис должен впитать масло. Влить кипяток, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4296,'Тушить на огне средней мощности в течение 20 минут. Убавить температуру до минимальной, оставить до полного впитывания влаги. Во время тушения рис не трогать, не перемешивать. Вегетарианский плов с шампиньонами выложить на блюдо горкой и посыпать небольшим количеством рубленой зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4297,'Перемешать пшеничную муку, сахарный песок или сахарозаменитель, сырые куриные яйца, подлить молоко. Ингредиенты перемешать до гладкого состояния, долить еще полстакана молока. Дать тесту постоять в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4297,'Силиконовые, стеклянные формы или противень смазать маслом, присыпать мукой. На дно выложить нарезанные фрукты или ягоды, можно использовать персики, яблоки, грушу,  залить тестом. Печь блюдо в микроволновой печи в течение 3 минут, мощность – 800 Вт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4297,'Пирог можно приготовить в духовке при температуре 180 градусов в течение 35 – 50 минут. Готовый десерт должен немного пружинить. Французский вишневый «Клафути» посыпать сахарной пудрой и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4298,'Морепродукт отварить в кипящей подсоленной воде в течение 5 минут. Измельчить кальмары с помощью блендера вместе с заранее отваренными куриными яйцами. Один желток оставить, он пригодится для украшения. Подлить натуральный йогурт, посолить, поперчить, добавить нежирный сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4298,'Отдельно измельчить консервированный зеленый горошек, без жидкости, перемешать с зеленью петрушки, йогуртом, корнишонами и сыром. Выложить обе смеси, белую и зеленую, в стаканы, слоями. Украсить диетический салат-коктейль с кальмарами, оставшимся раскрошенным желтком и петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4299,'Куриное мясо прокрутить через мясорубку или порубить с помощью блендера, можно взять готовый, магазинный, фарш. Изрубить небольшой красный болгарский перец с помидорами и укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4299,'Перемешать все ингредиенты, добавить размягченное сливочное масло, соль, перец, сырое куриное яйцо, любимые приправы. Массу хорошо вымесить. Сформовать котлеты и готовить в пароварке, в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4299,'Для приготовления соуса мелко порубить петрушку и укроп. Растопить сливочное масло, добавить сок лимона, приправы и зелень. Смесь немного прогреть, снять с огня. Подать готовые куриные котлеты на пару со сливочным соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4300,'Отварить картофель и размять толкушкой в пюре. Подсыпать пшеничную муку, соль, влить воду, перемешать. Разделить полученное тесто на 5-6 шариков. Для начинки обжарить на оливковом масле рубленый репчатый лук с шампиньонами, соль и перец молотый – по вкусу. Добавить шпинат и прогреть под крышкой 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4307,'Репчатый лук нарезать кольцами, уложить на смазанный маслом противень. Сверху выложить тонко нарезанное куриное филе, соль и перец – по вкусу. Подлить немного бульона или воды, чтобы продукты не пересушились во время приготовления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4300,'Каждый картофельный колобок раскатать в лепешку, выложить сверху грибной фарш и сформовать котлеты с начинкой. Размолоть грецкие орехи, запанировать в них готовые изделия и печь в духовом шкафу при температуре 180 градусов, в течение 20 минут. При подаче, гарнировать овощные котлетки в ореховой корочке свежей зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4301,'Слабосоленую семгу нарезать острым ножом — тонкими пластинками. Лаваш, расстеленный  в два слоя, смазать сливочным сыром, выложить сверху семгу и листья зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4301,'Все продукты завернуть рулетом, уплотнить, нарезать порционными кусочками. Закуске дать постоять в холодильнике один час, для пропитывания. Легкий закусочный рулет с семгой готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4302,'Отварить брокколи в подсоленной воде в течение 5 минут, затем процедить. Подержать под струей холодной воды. Духовой шкаф разогреть до температуры 200 градусов. Куриные грудки поместить в полиэтиленовую пленку и отбить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4302,'Верхнюю пленку снять. Мясо посыпать солью, порошковым кайенским перцем и молотым черным перцем. Сыр нарезать мелкими кусочками. Поместить его на край отбивной, добавить несколько столовых ложек брокколи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4302,'Оставшуюся пленку использовать для того, чтобы свернуть продукты в ролл. Шов закрепить зубочистками. Подлить в сковороду растительное масло, можно использовать оливковое, выложить куриные роллы, обжаривать на среднем огне по минуте с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4302,'Лист для выпечки также смазать растительным маслом, выложить изделия швом вниз. Печь при температуре 200 градусов в течение получаса. Для приготовления легкого соуса, в масло, оставшееся на сковороде от обжаривания курицы, подлить молоко и овощной бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4302,'Затем всыпать черный перец, паприку и чесночный порошок. Поварить, помешивая, в течение 5 минут. Вынуть готовые роллы из духовки, залить полученным соусом и подать к столу. Куриные роллы под нежным соусом можно подавать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4303,'Перемешать гречневую муку с геркулесом и молотой корицей. Добавить в блюдо нарезанные финики без косточек, натертое яблоки и спелый очищенный банан, размятый в пюре. Замесить тесто, при желании в него можно добавить жидкий натуральный мёд по вкусу или сваренный сахарный сироп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4303,'Из полученного теста сформовать печенье, выложить изделия на противень, заранее застеленный бумагой для выпекания. Готовить в духовке в течение получаса или чуть больше, должна получиться золотисто-коричневая корочка. Перед подачей гречневое печенье с фруктами остудить на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4304,'Помидоры и хорошо промытый листовой салат мелко нарезать. Натереть твердый сыр. Куриную грудку разделать на мелкие кусочки, потушить на тихом огне в течение 20 минут, жидкость должна испариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4304,'Продукт можно немного обжарить. Открыть банку с красной фасолью, отцедить жидкость. Все ингредиенты перемешать, заправить сметаной или майонезом. При подаче легкий куриный салат с сыром посыпать сухариками и сразу подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4305,'Развести желатин так, как написано в инструкции на пакетике. Перемешать обезжиренный творог и йогурт, влить желатин и клубничный сок, всыпать сахарный песок или сахарозаменитель по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4305,'Массу хорошо перемешать, вылить в форму и дать застыть в холодильнике. Полностью застывшее творожно-йогуртовое суфле выложить на тарелку, перевернув форму и нарезать десерт на порционные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4306,'Филе курицы нарезать кусочками небольшого размера. Добавить рубленый чеснок, соль по вкусу, сладкую молотую паприку, быстрорастворимый желатин, измельченную зелень, черный молотый перец. Все ингредиенты хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4306,'Выложить смесь в рукав для запекания, края завязать и готовить блюдо в прямоугольной форме. Сначала подержать изделие час при комнатной температуре, продукты должны пропитаться, а желатин – набухнуть. Пакет проколоть иглой в нескольких местах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4306,'Печь блюдо при температуре 180 градусов в течение 50 минут. Вынуть форму из духовки, сверху положить груз, на ночь и поставить в холодильник. Утром рукав снять, мраморную курицу в желе нарезать тонкими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6319,'Очищенный чеснок измельчить, добавить к помидорам и капусте, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4307,'Картофель очистить, нарезать кружками, разложить поверх курицы. Блюдо посыпать тертым сыром, полить нежирной сметаной или майонезом. Печь куриную грудку по-царски в духовом шкафу, в течение 40 минут, до образования румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4308,'Для приготовления блюда понадобятся куриные окорочка. Мясо нужно отделить от кожи и костей, мелко нарезать, фарш не делать. Добавить сырые куриные яйца, влить кефир, посолить, посыпать специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4308,'Массу перемешать, выкладывать её ложкой на разогретую сковороду с антипригарным покрытием, жарить рубленый шницель из куриной грудки с двух сторон, до готовности. Масло не использовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4309,'Куриную грудку промыть, нарезать длинными не очень толстыми брусками. Залить мясо обезжиренным кефиром, посолить, посыпать специями. Отставить на час или больше, для маринования.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4309,'Овсяные отруби перемешать с сухими травами и паприкой. Обвалять грудки в получившейся смеси, выложить на противень и поставить в заранее разогретую духовку. Печь наггетсы из курицы по-дюкановски в течение 20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4310,'Снять с хорошо вымытого лайма цедру при помощи терки. Выжать сок из мякоти, добавить  растительное масло, мед, рубленый чеснок, соль, перец. Филе курицы нарезать небольшими кусочками, переложить в маринад, перемешать и оставить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4310,'Пикантное куриное филе с лаймом переместить, вместе с жидкостью, в чугунный казан или другую посуду для жарки, тушить на тихом огне в течение часа, помешивать. При подаче посыпать блюдо измельченной зеленью петрушки или мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4311,'Репчатый лук очистить, мелко нарезать, пассировать на оливковом масле, добавить измельченные свежие грибы и баклажаны, прогреть до полуготовности. Добавить рубленую зелень укропа и петрушки, перец, соль, вбить сырое куриное яйцо. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4311,'Белокочанную капусту без кочерыжки переложить в кипящую подсоленную воду, варить 10 минут. Разобрать кочан на листья, утолщенные места отбить, выложить фарш, свернуть изделия конвертиками. Выложить диетические голубцы в большую емкость, залить нежирной подсоленной сметаной и тушить в духовке в течение 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4312,'Нежирный творог, немного натурального йогурта, сырой желток и стевию перемешать до однородного состояния с помощью блендера. Всыпать ванилин, всыпать овсяные отруби.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4312,'Массу еще раз перемешать. Разогреть духовку до 180 градусов, смесь выложить в формы из силикона для маффинов на треть объема. Печь в течение получаса, сырники остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4312,'Для приготовления соуса перемешать йогурт, стевию, цедру лимона. Подать готовые сырники с отрубями, с йогуртовым соусом, украсить свежими или размороженными ягодами или фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4313,'Отжать из мякоти плода лимонный сок. Перемешать с оливковым маслом. Куриное филе нарезать ломтиками, выложить в маринад, оставить на час в холоде. Подготовленное филе обжарить  на сковороде, разогретой до средних температур, остудить. Промыть, обсушить и нарезать салат айсберг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4313,'Добавить к нему отцеженную кукурузу, половинки томатов черри, кубики авокадо. Для приготовления заправки смешать оливковое масло, бальзамический уксус, сухие прованские травы. Смесью заправить салат, добавить курицу, кусочки грецких орехов. Салат с лимонной курицей подать к столу в красивых салатницах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4314,'Половину батона белого хлеба размочить в молоке. Пропустить его через мясорубку вместе с очищенным репчатым луком, куриным филе. Чеснок пропустить через пресс, добавить перец и соль, все ингредиенты перемешать. Вбить сырое куриное яйцо, перемешать массу еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4314,'Сформовать котлеты, обвалять в панировке из сухарей. Разогреть на сковороде растительное масло и жарить котлеты из курицы с двух сторон в течение 5-7 минут. Должна образоваться хрустящая, аппетитная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4315,'Сыр моцарелла нарезать тонкими пластинками, выложить его на кусочки ржаного или цельнозернового хлеба, сверху – слой хорошо вымытых и обсушенных салатных листьев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4315,'Крупный помидор нарезать полукружьями, заранее отваренное куриное филе – ломтиками, и то, и другое выложить на бутерброды поверх салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6319,'Сыр потереть, зелень порубить, посыпать ими салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4317,'На сковороде разогреть немного оливкового масла. Положить чеснок, прогреть до прозрачности. Добавить капусту брокколи, разобранную на соцветия, молотый красный и черный перец, соль. Готовить еще минуту. Влить немного воды и потушить продукт под крышкой до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4317,'Капусту остудить. В большой емкости взбить сырые куриные яйца с помощью венчика. Добавить брокколи, перемешать. Перелить смесь в сковороду с разогретым маслом. Прогревать на среднем огне три-четыре минуты, края запеканки должны схватиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4317,'Отдельно натереть сыр, посыпать им блюдо, поставить сковороду в духовку на среднюю решетку на десять минут. Готовый, нежный омлет  с брокколи достать из духовки, засыпать оставшимся сыром и молотым перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4318,'Банан очистить, нарезать кусочками небольшого размера, поставить на 20 минут в морозильную камеру. Мандарины вымыть и очистить. Переложить мякоть в блендер, взбить вместе с замороженным бананом, молоком, йогуртом, медом и ванилином в течение 30 секунд. Энергетический смузи из мандаринов разлить по бокалам и украсить очищенным от кожицы мандарином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4319,'Разрезать пополам куриное филе, но не до конца. Выложить мясо на фольгу, смазанную оливковым маслом, развернуть, отбить молотком до толщины в один сантиметр. Филе поперчить, посыпать рубленым укропом, добавить тертую морковь, нарезанный чеснок и помидоры. Отдельно отварить куриные яйца, очистить, нарезать, посыпать ими курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4319,'Мясо вместе с начинкой закатать рулетом, завернуть в фольгу, поставить в духовку на полчаса. Температура приготовления – 200 градусов. Затем фольгу развернуть и запекать еще 15 минут, чтобы рулет из курицы с овощами подрумянился.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4320,'Сушеный горох замочить в холодной воде на пять часов или на ночь. Коренья сельдерея и петрушки очистить и нарезать соломкой. Горох можно варить в той же воде, в которой он замачивался, или заменить на свежую. Добавить измельченную петрушку и сельдерей. Довести смесь до кипения, огонь убавить, не солить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4320,'Варить до тех пор, пока горох не станет мягким, примерно в течение полутора часов. Очистить репчатый лук и морковь, лук нарезать кубиками или сегментами, морковь натереть. Оба овоща обжарить на растительном масле, помешивать, следить, чтобы не пригорели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4320,'Обжарку переложить в суп почти при готовности, все вместе поварить 5 минут. Блюдо немного остудить, взбить в пюре с помощью блендера. Перелить в кастрюлю, посолить по вкусу, довести до кипения и снять с огня. Постный суп-пюре из гороха разлить по тарелкам, посыпать молотым кориандром, зеленью укропа и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4321,'Большие, спелые бананы очистить, мякоть размять. Перемешать со стаканом геркулеса, орехами, изюмом без косточек, шоколадом, молотой корицей. Ингредиенты – по желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4321,'Сформовать печенье, готовить при температуре 250 градусов в течение 15 минут на смазанном маслом противне. Готовое печенье, овсяное с орехом и фруктами, подавать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4322,'Натереть морковь на мелкой терке. Отдельно взбить сырой куриный белок. Смешать нежирный творог, сахарный песок, соль, сырое яйцо, манную крупу и морковь. Формочки для выпекания смазать сливочным маслом и перелить в них смесь. Готовить при температуре 180 градусов в течение 20 – 25 минут. Легкую, творожно-морковную запеканку перед подачей порционно нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4323,'Перемешать обезжиренный кефир или натуральный йогурт с небольшим количеством пищевой соды. Отдельно взбить сырое куриное яйцо, вылить его в кефир. Всыпать манную крупу и овсяные хлопья. Массу оставить на 15 – 20 минут, крупа должна набухнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4323,'По желанию можно добавить ванилин, молотую корицу, изюм, курагу. Кислые крупные яблоки вымыть, очистить от сердцевины и кожуры, если она слишком грубая. Форму смазать оливковым маслом, нарезать в нее яблоки ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4323,'Фрукт залить полученным кефирным тестом, поставить в духовой шкаф на 30 – 40 минут, печь при температуре 180 градусов. Диетический яблочно-овсяный пирог остудить, осторожно вынуть из формы и нарезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4324,'Мягкий творог с низким процентом жирности или обезжиренный смешать со сметаной или йогуртом, взбить с сахарной пудрой. Добавить сырые куриные яйца, снова взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4324,'Всыпать пшеничную муку, перемешать. Отдельно приготовить банановое пюре, вмешать в основную смесь, все взбить. Печь массу в разогретой до 160 градусов духовке в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4324,'Можно готовить чизкейк на водяной бане. Готовый десерт остудить, по возможности отставить на ночь. Остывший творожно-банановый чизкейк украсить клубникой и посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4325,'Смешать творог с желтками, разрыхлителем и картофельным крахмалом. Взбить с помощью блендера. Отдельно взбить сырые куриные белки с сахарозаменителем в плотную пену. Перемешать творог с белками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4325,'Дно мультиварки смазать маслом или маргарином, массу выложить в чашу, выровнять, поставить в режим Выпечка на 1 час 20 минут. По истечении времени крышку не открывать, оставить легкую творожную запеканку еще на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4326,'Овсянку до состояния муки перемолоть с помощью блендера или кофемолки. Перемешать ее с сырыми яичными белками и сахарозаменителем. Должна получиться масса, похожая на паштет. Готовым тестом выстелить формочки из силикона или с антипригарным покрытием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4326,'Сформованные корзиночки выпечь в разогретой духовке, температура – 180 градусов, остудить. Для приготовления начинки, желатин из пакетика замочить в воде, прогреть почти до кипения и добавить в обезжиренный творог вместе с сахарозаменителем. Размять вилкой клюкву.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4326,'Добавить к ягодам желатин и сахарозаменитель по желанию. Выпеченные корзиночки наполнить творожной смесью, украсить ягодами и поставить в холодильник на несколько часов. Начинка должна полностью застыть. Готовые овсяные корзиночки с творогом и клюквой подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4327,'Промыть гречневую крупу, залить холодной водой, варить до испарения жидкости, на тихом огне. Мелко нарезать репчатый лук и обжарить его до золотистого цвета. Нарезать соломкой грудинку, добавить в луковую массу, все вместе обжарить. Затем положить заранее отваренные шампиньоны или другие грибы, жарить еще 2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4327,'Упревшую гречневую кашу смешать с обжаркой, посолить по вкусу. Отварить и нарезать соломкой яйца, порубить зелень, добавить то и другое в кашу, перемешать. Накрыть гречневую кашу с грибами по-боярски крышкой и дать постоять 20 – 30 минут. Разложить по тарелкам и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4328,'Хек или минтай нарезать на порционные куски, натереть солью и перцем, добавить оливковое масло и прованские травы. Оставить для маринования на 2 часа в холодильнике. Помидоры, морковь, репчатый лук нарезать кольцами, сладкий перец измельчить на небольшие кусочки. Натереть сыр, можно использовать плавленый.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4328,'Выложить в мультиварку рыбу, затем – слой лука, морковь, помидоры, перец. Закрыть крышку, выставить режим Выпечка на 40 минут, паровой клапан снять. Почти готовую пряную рыбу под овощами посыпать сыром, снова закрыть крышку и оставить примерно на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4329,'Зеленый салат вымыть и порвать руками. Томаты, огурцы и моцареллу нарезать кубиками. Приготовить заправку из оливкового масла, натурального меда, горчицы, сушеных трав и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4329,'Сыр и овощи выложить в тарелку в любом порядке. Полить овощной салат с кунжутом и моцареллой готовой заправкой и посыпать заранее обжаренными кунжутными семечками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4330,'Для приготовления омлета взять по яйцу и чайной ложке молока, посолить. Смеси взбить по отдельности в небольших чашках. Выпечь шесть омлетов, каждый – с двух сторон, на смазанной маслом сковороде. Для начинки в куриный фарш добавить перец, соль, приправу для мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4330,'Массу отбить, добавить молоко или воду. Фарш должен быть жидковатым. Мягкий творог перемешать с рубленым укропом (немного отложить для украшения), часть творога можно заменить сметаной. На омлетные блинчики выложить фарш тонким слоем, затем намазать творог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4330,'Скрутить омлеты в рулетики, переложить в форму. Натереть нежирный сыр, посыпать им изделия. Печь при температуре 180 – 200 градусов в течение 20 – 25 минут. Бризоль из курицы с мягким творогом при подаче разрезать наискосок и присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4338,'Филе курицы нарезать небольшими кусочками, выложить в форму, смазанную маслом, посолить. Нарезать репчатый лук полукольцами, отварить и нарезать шампиньоны или другие  грибы. Выложить поверх филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4331,'Красный лук тонко нарезать полукольцами. Переложить овощ в тарелку, добавить винный или яблочный уксус, залить кипятком. Куриное филе можно обжарить на сковороде-гриль, предварительно натерев солью и черным молотым перцем. Сбрызнуть растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4331,'Грудки нарезать кубиками. Очистить апельсин от кожуры, удалить белые волокна, разделить на дольки. Каждую дольку разрезать на 3-4 кусочка. Сыр фета нарезать кубиками. Маринад от лука слить. Выложить в порционные тарелки листья зеленого салата, порванные руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4331,'Сверху – куриное филе, лук, апельсин и сыр. Для приготовления заправки перемешать оливковое масло, зернистую горчицу, белый винный уксус, пропущенный через пресс чеснок. Полить каждую порцию салата с апельсинами, курицей и сыром фета, заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'До полуготовности отварить рис, слить остаток воды, выложить и промыть в дуршлаге, разделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'Добавить к одной половине яйца и осторожно перемешать. В кастрюле нагреть масло, добавить смесь риса с яйцами, сахар и муку, перемешать и на среднем огне прожарить 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'Засыпать вторую часть риса и тушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'Сварить из промытых сухофруктов насыщенный узвар, процедить, сухофрукты выложить на отдельную тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'Накрыть кастрюлю с пловом с сухофруктами по-татарски широким блюдом и перевернуть, сверху окажется красиво зажаренный рис, а внизу будет слой белого.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4332,'Подавать плов с узваром и сухофруктами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4333,'Заранее приготовить пищевой лед. Для этого разложить в формы зерна очищенного граната, залить их водой и заморозить. Половину мяты мелко порвать, переложить в высокую посуду. Туда же нарезать лайм. Размять оба ингредиента скалкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4333,'Влить гранатовый сок и минеральную воду. Массу перемешать, процедить. Выложить в стаканы кубики льда с гранатом и налить гранатовый «Мохито» с лаймом. Украсить остатками мяты и дольками лайма, посыпать зернами граната.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4334,'Небольшой кабачок, баклажан и сладкий болгарский перец нарезать кубиками небольшого размера. В овощи вбить яйцо, всыпать предварительно натертый сыр, перемешать. Соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4334,'Массу переложить в чашу для риса, затянуть фольгой и готовить в пароварке в течение 25 – 30 минут. Готовые овощи под сыром, запеченные в пароварке, разложить по тарелкам и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4335,'Разморозить филе тилапии, хорошо промыть. В нежирное молоко добавить зелень, специи, соль. Застелить фольгой форму для выпекания, выложить рыбу, залить молоком. Фольгу не заворачивать, рыба должна остаться открытой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4335,'Посыпать мелкорубленой зеленью. Печь в духовом шкафу при температуре 180 градусов до готовности, примерно в течение получаса. Готовое филе тилапии запеченное в молоке, перед подачей порционно нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4336,'Капусту нашинковать соломкой и отложить в сторону. Репчатый лук нарезать небольшими квадратиками. В сковороду, вместо масла налить воду и поставить на средний огонь. Всыпать нарезанный лук и тушить 10 минут. Мелкими квадратиками нарезать морковь, сладкий болгарский перец и помидор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4336,'Капусту добавить к луку, долить воду. Тушить под крышкой около получаса, периодически перемешивая. Через полчаса добавить морковь, перец и помидоры. Прогревать под крышкой еще 30 минут, не забывая мешать. Соль и молотый перец – по вкусу. Сочную капусту, тушеную с овощами, подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4337,'Капусту, репчатый лук, томаты, зеленый болгарский перец, морковь, кусочек корня и стебли сельдерея мелко нарезать или натереть на терке. Репчатый лук предварительно обжарить на оливковом масле. Налить в кастрюлю холодную воду, сложить продукты и включить огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4337,'Во время закипания добавить карри, чеснок, имбирь, кориандр и лавровый лист.Не обязательно использовать все приправы, можно только одну, любимую. Когда суп закипит – добавить рубленую петрушку. Затем убавить огонь и кипятить содержимое кастрюли еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4337,'Затем закрыть кастрюлю крышкой и довести до готовности на тихом огне. Можно довести овощной боннский суп с имбирем до готовности выключив огонь и оставив суп настаиваться. Вместо воды можно использовать мясной бульон без жира, кубики овощей, пакет лукового супа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4338,'Приготовить соус из натурального йогурта со специями и солью. Залить куриное филе соусом и поставить в духовой шкаф на 30 – 40 минут. Незадолго до готовности, филе курицы в йогуртовом соусе присыпать тертым сыром, должна получиться аппетитная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4339,'Сырую гречневую крупу сначала обжарить на сухой сковороде, в течение 10 минут, затем отварить. Каша не должна быть разваренной. Мелко нарезать репчатый лук, грибы и обжарить на оливковом масле. Готовую гречневую кашу измельчить с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4339,'Добавить обжарку, соль и перец – по вкусу. Можно добавить любые другие специи. Положить рубленую зелень и перемешать. Из полученной массы сформовать котлеты классической формы, обжарить их с двух сторон по 7 – 10 минут на тихом огне. Простые гречневые котлеты с грибами можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4340,'Перемешать, руками или с помощью блендера, льняную муку или перемолотое льняное семя, протеин и яичный белок. Добавить тыквенное несладкое пюре. Можно использовать детское питание.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4340,'Можно добавить немного воды, если масса получилась суховатой. Тесто разлить в формочки и выпекать тыквенные кексы в разогретой духовке в течение 20 минут, при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4341,'Зажарить готовый стейк, порезать половинку луковицы мелкими кубиками, а вторую нашинковать тонкими полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4341,'Порубить мелко три огурца, оставшийся — надрезать веером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4341,'Разрезать на половинки четыре оливки, остальные и каперсы мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4341,'Смешать все нарезанные ингредиенты с вареными желтками яиц, солью, перцем, горчицей, выложить полученную смесь на бифштекс, вокруг положить полукольца лука и половинки оливок',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4341,'Украсить бифштекс с пикантной приправой по-татарски дольками помидора и веточками кресс-салата.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4342,'Куриную грудку хорошо вымыть, отварить и мелко нарезать. Горошек отварить до мягкости. Взбить сырые куриные белки и обжарить в виде блинчика на сковороде с антипригарным покрытием. Готовый омлет остудить и нарезать длинными полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4342,'Нарезать репчатый лук полукольцами, полить лимонным соком и кипящей водой, такая процедура позволит удалить из продукта излишнюю горечь. Все ингредиенты перемешать, посолить, добавить специи. Заправить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4343,'Смешать в однородную массу обезжиренный творог, яичный белок, куриные яйца целиком и протеин. Добавить черную смородину, перемешать еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4343,'Смесь вылить в мультиварку и выпекать запеканку из творога с черной  смородиной в режиме выпечка 1 час или выпечь в духовке при температуре 180 градусов, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4344,'Измельчить куриную грудку в кухонном комбайне, поперчить. Противень застелить пищевой пленкой и выложить куриный фарш ровным слоем. По поверхности разложить творожный нежирный сыр и свежий шпинат. Осторожно свернуть изделие рулетом и уплотнить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4344,'Обернуть изделие пленкой и положить в морозильную камеру на 2 часа. Затем выпечь при температуре 180 градусов в течение 40 минут. Время выпечки куриного рулета с мягким сыром зависит от толщины рулета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4345,'Овсяные хлопья залить обезжиренным кефиром и оставить на полчаса для набухания. Добавить обезжиренный творог, сырые куриные яйца, казеиновый протеин. Перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4345,'Смесь поместить в форму и выпекать в духовке 40 минут или вылить в чашу мультиварки и готовить блюдо в режиме Выпечка. Овсяную запеканку с творогом и протеином полностью остудить и нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4346,'Смешать сырые куриные яйца и дополнительные белки, влить воду или обезжиренное молоко. Всыпать разрыхлитель, кокосовую муку и добавить любой сладкий продукт: мед, заменитель сахара или стевию, на выбор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4346,'Смесь взбить, должна получиться гладкая масса. Выпечь на сковороде с антипригарным покрытием небольшие кокосовые блинчики. Печь сначала с одной стороны, пока тесто сверху не застынет, затем перевернуть и прогреть еще 1-2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4347,'Натереть нежирный твердый сыр на мелкой терке. Порубить зелень петрушки. Ингредиенты смешать, добавить соль, перец, сок и цедру лайма. Филе лосося разрезать на порции, выложить на противень, кожа должна быть внизу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4347,'Намазать кусочки филе сырной смесью и печь при температуре 180 градусов в течение 10 – 12 минут. Готовое филе лосося под сырной корочкой выложить на блюдо, гарнировать по своему усмотрению.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4348,'Творог протереть через сито, добавить ванильный протеиновый порошок, разведенный с небольшим количеством воды, часть кокосовой стружки, стевию. Все перемешать и сделать маленькие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4348,'В середину каждого шарика положить по жареному миндальному орешку и обвалять в оставшейся кокосовой стружке. Поставить творожные «Рафаэлло» на протеине в холодильник на час. Готовые конфеты выложить пирамидкой на блюдо и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4349,'Отварить рис, слить, промыть и обсушить. Отдельно смешать яичные белки, стевию, протеиновый порошок и корицу, можно сделать это в блендере. Добавить рис и аккуратно перемешать. Выложить рисовую смесь в форму. Запекать сладкую рисовую запеканку на протеине в духовке, в течение 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4350,'В овес влить горячую воду и оставить для набухания. Смешать белки и стевию в блендере, добавить овес, молотую корицу, еще раз перемешать. Выложить полученное тесто в формы, дать постоять и печь белково-овсяные кексы в течение 15 – 20 минут в духовке, при температуре 350 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4351,'Крупу промыть в холодной воде, варить в течение 2 минут, воду слить. Яичные белки взбить с протеином и молотой корицей. Все вместе смешать и печь в духовке в течение 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4352,'Крупу промыть в холодной воде, варить в течение 2 минут, воду слить. Яичные белки взбить с протеином и молотой корицей. Все вместе смешать и печь в духовке в течение 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4353,'Смешать с помощью вилки творог, овсянку без добавок, сырое куриное яйцо и горсть изюма. Форму для выпекания смазать оливковым маслом, дно присыпать овсяными хлопьями. Смесь выложить и разровнять, поверх уложить тонкие ломтики яблок без кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4353,'Посыпать корицей и ванилином из пакетика. Печь в духовке при температуре 160 градусов, в течение 20 – 25 минут. Блюдо должно подрумяниться. Достать из духовки и полить жидким медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4353,'Если продукт твердый, то его нужно заранее растопить на водяной бане, но не кипятить, иначе он потеряет свои целебные свойства. Творожно-яблочную запеканку с медом порционно нарезать, разложить по тарелкам и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4354,'Дрожжи растворить в молоке, добавить сахар и отставить в сторону, чтобы они ожили (минут 15-20). Соединить молоко, соль, кефир, сахар, яйцо, растительное масло и перемешать. Добавить в дрожжевую смесь муку (просеянную) и замесить тесто. Положить тесто в емкость, прикрыть пленкой и определить в теплое место, примерно на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4354,'Затем тесто обмять и поделить на 2 части. Одну часть положить обратно в емкость и накрыть полотенцем, а вторую часть раскатать в пласт (3-4 миллиметра), стол притрусить мукой. Стаканом выдавить кружочки. Оставшееся тесто, собрать, обмять, раскатать и опять выдавить кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4354,'Заготовки прикрыть пленкой, чтобы не обветрились. Взять один кружочек, положить на него одну полную чайную ложку фарша и разровнять по поверхности. Сверху положить щепотку тертого сыра. Согнуть круг пополам, затем еще пополам, край немного защипнуть. Также поступить с остальными кружочками и со второй частью теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4354,'Форму для выпечки (примерно диаметром 28 сантиметров) обмазать растительным маслом, уложить бумагу для выпечки и тоже смазать маслом. Укладывать заготовки плотно, один к одному, в форму. Для центра пирога взять три кружочка, смазать их фаршем, положить внахлест один на другой и скрутить рулетом. Поставить его по центру формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4354,'Форму закрыть пленкой и отставить примерно на полчаса. Верх пирога смазать смесью из 1 желтка и 1 столовой ложки молока. Запекать пирог примерно 40 минут (температура 180 градусов). Готовый, закрытый пирог «Хризантема» достать из духовки, смазать сливочным маслом. Прикрыть полотенцем и дать постоять минут 15.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4355,'Сахар растереть с яйцами. Затем добавить творог, муку с содой и сметану. Взбивать миксером. Яблоки очистить от кожуры и семян, измельчить дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4355,'Если яблоки сладкие, то их можно взбрызнуть соком лимона и/или рассыпать клюкву на яблоки, уложенные в форму для выпечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4356,'Брать можно любую морскую рыбу. Очистить ее полностью от шкурки и костей. Порезать готовое филе маленькими кубиками. Добавить измельченный лук, поперчить, посолить. Всыпать крахмал (1 столовую ложку), перемешать, вбить яйца и опять помешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4356,'Нагреть растительное масло на сковородке. Выкладывать фарш столовой ложкой и жарить, под крышкой, на небольшом огне с обеих сторон. Подавать простые рыбные оладьи можно с салатом или с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4357,'Баранину нарезать поперек волокон пластинами толщиной 1 см (размером с ладонь).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4357,'Отбить хорошо с двух сторон, добиться увеличения куска в два раза, постараться придать форму прямоугольника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4357,'Нарезать сало и сухари брусками размером 8 на 1 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4357,'Приготовить пасту из смеси перца, соли и небольшого количества воды, обмазать смесью мясо, положить сверху кусочек сала, а не него – сухарик, кусок скатать в рулет и обвязать ниткой, следить, чтобы начинка со всех сторон была закрыта мясом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4357,'Обжарит пальчики со всех сторон на сковороде до золотистой корочки, снять нитки, затем переложить «Пальчики» из мяса с салом по-татарскив огнеупорную форму. Залить на 2/3 их высоты соком, оставшимся на сковороде после жарки, если его не хватит, то можно добавить немного воды, поставить томиться в духовку на 1 час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4358,'Свинину поперчить, посолить и поджарить. Затем мясо мелко порезать. Измельчить огурцы и помидоры, капусту нашинковать, лук нарезать полукольцами. Соус: ингредиенты перемешать, чеснок пропустить сквозь пресс, мелко нашинковать укроп, все смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4358,'Лаваш намазать соусом, выложить начинку, полить сверху соусом и скрутить рулетом. Края также необходимо закрыть. По желанию, шаурму со свининой можно поджарить, до образования румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4359,'Духовку нагреть (180 градусов), форму для выпечки смазать маслом. Крендельки соленые положить в чашу блендера и измельчить в крошку. Влить сливочное масло (растопленное), всыпать сахар и взбить. Получившееся тесто выложить в форму, хорошо утрамбовать и запекать в духовке, приблизительно 10 минут. Вынуть из духовки, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4359,'Температуру в духовке уменьшить до 160 градусов. Сливочный сыр взбить с сахаром. Затем, добавить яичные желтки, лимонный сок и ваниль. Продолжить взбивать на средней скорости. Отдельно взбить белки в пену и осторожно добавить их в основную массу. Перемешать до однородности. Вылить массу наверх готового теста и запечь (25-30 минут).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4359,'Остудить сначала до комнатной температуры, потом отправить в холодильник, пока полностью не охладится. Сливочное масло и шоколад растопить (можно в микроволновке), хорошо перемешать и охладить. Желтки с сахарной пудрой положить в термостойкую емкость и поставить на водяную баню и постоянно помешивая, готовить примерно 10 минут, пока не загустеет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4359,'Затем добавить их в шоколадную массу, перемешать, поставить емкость в ледяную воду или лед (минуты на 2). Затем в эту массу добавить сливки. Распределить глазурь из шоколада на сырный слой, украсить сверху драже и отправить в холодильник до окончательного застывания. Чизкейк на соленых крендельках можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4360,'Болгарский перец нарезать кубиком, нашинковать мелко лук. В фарш добавить половину лука, яйцо, зелень измельченную, болгарский перец, соль и перец черный. Хорошо смешать. Поделить на 6 одинаковых частей. Натереть морковь на терке и поджарить с оставшимся луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4360,'Влить пасту томатную (разведенную водой) и тушить еще минуты 3-4. Сыр натереть на терке, лаваш поделить на 6 частей. Каждый кусок лаваша намазать майонезом, равномерно распределить фарш, свернуть рулетом и положить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4360,'Запекать в духовке приблизительно 40 минут (180 градусов). Затем вынуть форму из духовки, выложить на рулетики из лаваша с мясом томатную зажарку и притрусить сверху тертым сыром. Вернуть обратно в духовку, пока не расплавится сыр. Подавать сразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4361,'Перемешать сахар, муку, кэроб, миндаль, разрыхлитель и соль. Сироп, который остался от вишни, развести водой (до объема стакана) и добавить в сыпучие ингредиенты. Затем влить растительное масло и перемешать до однородности массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Равномерно распределить, отправить в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4361,'Добавить вишню без косточек. Форму смазать и притрусить мукой. Тесто перелить в форму и запекать в духовке около 35-40 минут, охладить. Очень аккуратно разрезать готовый бисквит пополам. Крем: взбить сгущенное молоко со сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4361,'Намазать первый слой бисквита, выложить на крем вишню, сверху положить второй бисквит и также смазать кремом. Украсить бисквитный торт с вишней и кэробом по собственному желанию и убрать на холод для пропитки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4362,'Перемешать соль, муку и разрыхлитель. Отдельно в емкости смешать мед (жидкий), яйца, растительное масло и молоко, все взбить. Смесь с молоком и медом перелить в муку и хорошо помешать, чтобы разбить все комки. Выпекать оладьи медовые с обеих сторон на разогретой сковородке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4363,'Крошка: растопить сливочное масло. В емкости смешать корицу, два вида сахара, растопленное масло и соль. Всыпать муку и перемешать до однородности. Дать смеси охладится минут 10. Пирог: нагреть духовку (175 градусов). Форму перемазать сливочным маслом. В большой емкости смешать какао, разрыхлитель, муку, соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4363,'Потом вбить яйцо, ввести молоко, добавить ванилин и масло. Можно перемешивать с помощью кухонного комбайна (примерно 2 минуты). Почти в самом конце добавить кипяток, перемешать – тесто выйдет жидкое. Вылить тесто в форму и отправить в духовку минут на 20. Вынуть пирог из духовки (он будет готов только на половину за это время).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4363,'Руками порвать приготовленное тесто для крошки и выложить его сверху, на шоколадную основу. Отправить пирог опять в духовку, еще на 20 минут. Вынуть из духовки, охладить несколько минут и присыпать сверху маленькими кусочками шоколада. Перед подачей дать шоколадному пирогу с крошкой настояться приблизительно час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4364,'Ирис поломать или нарезать мелкими кусочками. Растопить на водяной бане с добавлением сливок (5 столовых ложек). Снять ирис с огня и добавить к нему сливочное масло (15 грамм – 1,5 столовой ложки). Масса выйдет блестящей и гладкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4364,'Формочку для конфет обязательно смазать растительным маслом (без запаха), иначе невозможно будет вынуть конфеты из формочек. Чайной ложкой налить в формочки растопленный ирис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4364,'Фундук поджарить и очистить. В половину конфет положить по жареному орешку, а во вторую сушеную клюкву. Растопить шоколад на водяной бане, влить сливки (3-4 ложки). Их необходимо добавлять частями, возможно понадобиться меньше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4364,'Конфеты в формочках покрыть растопленным шоколадом. Готовые конфеты отправить в морозилку часа на 4. Затем вынуть конфеты «Тоффи» из формочек, они мгновенно станут мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4365,'В большую, глубокую емкость вбить яйца, добавить ванильный сахар и сахар-песок. Взбить миксером до состояния пены (минут 4-5). Смешать сухие компоненты (муку, разрыхлитель, соду и какао). К яйцам влить молоко и масло, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4365,'Частями, сухую смесь добавить к жидкой (просеивая). Каждый раз  хорошо перемешивать. Затем в тесто влить крутой кипяток (стакан) и быстро замесить тесто. Чашу мультиварки смазать маслом, притрусить панировочными сухарями (можно крошками) и влить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4365,'Поставить чашу в мильтиварку и выставить режим Выпечка (75 минут). Когда бисквит испечется, поставить решетку на чашу и перевернуть. Когда бисквит на кипятке из мультиварки остынет, нарезать и подать к чаю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4366,'Вымыть крылышки (в проточной воде) и порезать пополам. Включить мультиварку (режим Жарка), добавить оливковое масло, дать чаше немного нагреться и обжарить крылышки (с каждой стороны 6-8 минут). Лук и морковь порезать полукольцами (или маленькими кусочками) и положить к крыльям.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4366,'Обжаривать минут 10, постоянно мешая. Грибы промыть, немного просушить и порезать пластинами. Их также добавить в кастрюлю и обжаривать, пока вода целиком не выпарится, а грибы не приобретут золотистый оттенок (минут 10-12). Прибавить муку (ложку). Влить тонкой струйкой сливки, добавить соль, перец и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4366,'Рисовую крупу промыть, всыпать к овощам и налить воды (горячей). Включить мультиварку (режим Тушение) на 45 минут. По истечении времени положить измельченную петрушку, лавровый лист, закрыть крышкой и оставить еще минут 10-15. Подавать порционно сливочный суп с рисом и грибами, присыпав сверху еще зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4368,'Почистить и нарезать полукруглыми ломтиками баклажаны и положить их в емкость с холодной водой (10-15 минут). Взбить яйца. Баклажаны обвалять сначала в муке, затем в яйце. Обжарить с обеих сторон до румяной корочки. Измельчить и обжарить (минут 5) чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4368,'Нарезать помидоры маленькими кубиками, прибавить к чесноку и тушить до загустения (минут 15). Можно сюда же влить немного воды или жидкость от сыра моцарелла (тогда соус будет еще ароматнее). Добавить в соус соль, базилик и перец. В форму для выпечки положить бумагу, смазать. Выложить пармеджано слоями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4368,'Сначала соус, жареные баклажаны, пармезан тертый, порезанная небольшими кусочками моцарелла (половина), повторить еще раз все слои. Разрезать помидоры черри пополам и украсить сверху. Запекать в духовке минут 15 (170 градусов), затем баклажаны «Пармеджано» с моцареллой немного остудить и порезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4369,'Взять небольшую кастрюльку и смешать лимонный сок, вино, гвоздику, сахар, кардамон, имбирь, соль и палочку корицы. Вскипятить на небольшом огне и мешать, пока не растает сахар.  Положить очищенные от кожуры груши в кастрюлю и влить воду, груши должны быть полностью покрыты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4369,'Прикрыть кастрюлю крышкой и варить, пока груши не станут мягкими (30 минут приблизительно). Переложить груши на тарелку. Оставшийся  в кастрюле сироп продолжить кипятить на сильном огне, пока он не уменьшиться до объема стакана. Перед подачей, груши полить сиропом. Подавать пряные груши в белом вине с ванильным кремом или со сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4370,'Грибы вымыть и отварить. Можно использовать как свежие грибы, так и сушеные. Продукт мелко нарезать, смешать с томатной пастой и рисом, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4370,'Проварить в кипящей воде несколько листьев белокочанной капусты в течение 2-3 минут, вынуть из воды. Дать воде полностью стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4370,'Выложить на листья начинку, завернуть и обжарить постные голубцы с грибной начинкой в растительном масле, затем потушить на противне в духовке или в кастрюле на плите.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4371,'Для приготовления блюда понадобится йогурт или нежирная сметана, её нужно посолить, поперчить и добавить давленый чеснок. Натереть сыр на мелкой терке. Куриные грудки вымыть, обсушить бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4371,'Выложить мясо в форму для запекания, смазать сметаной заправкой и посыпать сыром. Курицу под сырной корочкой в сметане, запекать в духовке при температуре 180 градусов в течение 45 – 50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4372,'Куриное филе нарезать на кусочки небольшого размера, натереть очищенный чеснок. Все ингредиенты перемешать, выложить на лист пищевой пленки, замотать в несколько слоев для прочности, сформовать массу в виде бруска.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4372,'Положить продукт в воду и варить в течение часа. Жидкость слить, остудить рулет до комнатной температуры. Затем положить в холодильник и дать застыть. Готовый заливной куриный рулет нарезать ломтиками, присыпать зеленью и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4373,'Овощи очистить. Филе судака, нарезанные по своему усмотрению картофель, морковь, капусту цветную или белокочанную приготовить в пароварке. Для приготовления соуса смешать сырые куриные желтки, готовую горчицу, растительное масло и посолить по вкусу. Залить полученным соусом продукты и подать филе судака с овощами под яичным соусом к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4374,'Филе постной рыбы, такой как минтай, горбуша, треска, нарезать на небольшие кусочки и сбрызнуть свежим лимонным соком. Соль и перец – по вкусу. Поставить блюдо мариноваться в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4374,'Форму с высокими бортиками смазать растительным маслом, положить рыбу, поставить на 10 минут в духовой шкаф. Взбить сырые куриные яйца в пену, посолить и поперчить, можно добавить дробленые грецкие орехи и зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4374,'Смесью залить рыбное филе, печь блюдо в течение 10 – 15 минут до румяной корочки. Если во время приготовления омлет поднимется – его нужно поколоть ножом или вилкой. Подавать сочную рыбу, запеченную в омлете, украсив свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4375,'Взбить сырые яичные белки, добавить оливковое масло и еще раз взбить. Добавить протеин, перемешать, в массе не должно быть комочков. Выпечь протеиновые блины без муки на сковороде с антипригарным покрытием, без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Измельчить чеснок, обжарить. Положить орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4376,'Яйца перетереть с сахаром, добавить муку, сливочное масло, предварительно натертые орехи, какао, ванилин, хорошо смешать. Долить молоко и опять перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4376,'Получившуюся смесь поставить на небольшой огонь и варить, пока паста не загустеет. Паста «Нутелла» с фундуком будет любимым завтраком для всей семьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4377,'Рис необходимо хорошо промыть, затем замочить минут на 20 в холодной воде и поставить на плиту. Когда вода закипит, добавить к нему 2 чайные ложки уксуса и варить примерно минут 15-20.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4377,'Положить на стол коврик для сворачивания суши, обернуть его пищевой пленкой. Взять один пласт водорослей, поделить его пополам и уложить на край коврика. На водоросли выложить немного риса. Верхнюю часть коврика положить на нижнюю часть и сильно прижать и перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4377,'Затем коврик развернуть, рис будет снизу на коврике, а водоросли сверху. Посерединке выложить полоску сыра, далее немного порезанного соломкой помидора. Рису придать квадратную форму, потом на коврик уложить кусочки семги (5-7 сантиметров шириной).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4377,'Придать форму роллу с помощью коврика. Готовый ролл перерезать пополам, а потом каждую половину еще на 4 части. Роллы «Филадельфия» с творожным сыром подавать можно с соевым соусом и васаби.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4378,'К муке добавить соль, влить масло и воду, замесить тесто. Сформировать из него шар, обернуть пленкой и отставить на полчаса. Затем скатать тесто в шарики (приблизительно 32 г один шарик).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4378,'На столе, притрушенном мукой, раскатать шарики в тоненькие лепешки (размером примерно 30х20). Для начинки, на мелкой терке натереть сыр. С веток эстрагона оторвать листки, порезать, добавить к сыру и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4378,'На половину лепешки уложить сыр с эстрагоном. Накрыть свободным краем лепешки, края защипать. Лишнее обрезать. Поджарить лепешки с обеих сторон до готовности. Готовые азербайджанские кутабы с сыром смазать топленым маслом и кушать, с мацони или со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4379,'Филе куриное порезать, как на отбивные. Немного отбить, поперчить и посолить. Приготовить начинку: сливочное масло (размягченное) перемешать с соком лимона, рубленой зеленью, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4379,'Выложить начинку на куриное филе и сформировать рулеты. Тесто раскатать и разрезать на полоски (4-5 сантиметра ширина). Рулеты обернуть полосками теста, по спирали. Смазать яйцом и запекать куриные рулеты в слоеных спиральках в духовке, минут 35-40.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4380,'Бисквит делается без особых энергетических затрат. Разделить белки с желтками. Белки взбить с половиной сахара и лимонной кислотой. Желтки взбить с остальным сахаром, постепенно добавляя крахмал и муку. В получившуюся смесь аккуратно ввести взбитые белки и перемешать (осторожно).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4380,'Кастрюлю из мультиварки смазать маслом и притрусить манкой или сухарями. Переложить в нее тесто и включить на 60 минут (режим выпечки). По истечении времени оставить бисквит еще на 15 минут (режим подогрева). Затем мультиварку выключить и дать выпечке остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4380,'Вынуть белоснежный бисквит из мультиварки и разрезать на несколько коржей, вдоль. Пропитать сиропом, промазать кремом (можно сметанным) и добавить нарезанные фрукты. Отставить торт для пропитки (можно на ночь).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4381,'Яйца разбить в форму для кексов и печь минут 10-15 (180 градусов). Сыр натереть на терке, булочки подогреть. Булочку разрезать пополам, можно не дорезать до конца, положить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4381,'Присыпать сыром и определить в духовку, для расплавления сыра. Готовые бургеры с печеным яйцом и сыром можно кушать на завтрак или взять с собой пикник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4382,'Залить желатин 50 миллилитрами воды и отставить в сторону. Сливки перелить в кастрюлю, добавить ванилин и сахар. Вскипятить и варить, пока сахар не растает. Убрать с плиты и добавить шоколад (натертый на терке).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4382,'Перемешивать до полного растворения. Растопить замоченный желатин и влить его в сливочно-шоколадную смесь. Перемешать. Разлить смесь по креманкам и немного охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4382,'Затем поставить итальянский десерт «Паннакотта» в холодильник до полного застывания (часа на 2-4). Перед подачей можно присыпать орехами или тертым белым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Обмазать мясо ароматными сушеными травами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4383,'В кастрюльку положить все ингредиенты и залить молоком. Варить 30 минут, все время помешивать. Масса должна приобрести яркий цвет карамели и загустеть. Для того чтобы получились красивые топленые ириски «Тянучки», карамель лучше разлить в формочки для льда, предварительно смазанные маслом. Выложить массу и отправить в морозилку минут на 30.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Перемешать в емкости муку, ванильный сахар, сахар (2 ст.л.), соль и дрожжи, добавить яйца. Сливочное масло (60 грамм) растопить на слабом огне, влить воду и молоко. Убрать с огня. Молочно-масляную смесь добавить в мучную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Замесить миксером гладкое тесто. Тесто поставить в теплое место, пока оно не увеличится в два раза, в объеме. Апельсины сполоснуть горячей водой и снять цедру (лучше натереть ее на терке, так как просто измельченная цедра может быть грубоватой).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Изюм промыть, крупно порубить и добавить к цедре. Поднявшееся тесто еще раз хорошо вымесить и раскатать в пласт на присыпанном мукой столе. Пласт смазать топленым сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Колесом для теста (а можно и острым ножом) нарезать пласт на прямоугольники, размером примерно 8х10. Корицу перемешать с сахаром, притрусить смесью тесто. Сверху разложить смесь из цедры и изюма.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Форму для хлеба или кекса (примерно 26х11 сантиметров) смазать маслом, можно еще присыпать мукой. Поставить в миску так, чтобы она стояла вертикально, под небольшим наклоном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Каждый прямоугольник теста сложить пополам, немного растягивая в длину и ширину. Подготовленные прямоугольники выложить в форму, чередуя сгибы – первый прямоугольник уложить сгибом вверх, а следующий сгибом вниз и так далее.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Укладывать необходимо свободно, стопкой, не прижимая их друг к другу. Когда все слои будут уложены, форму нужно перевернуть горизонтально и распределить тесто равномерно по всей форме. Оставить форму в теплом месте минут на 15.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Выпекать в разогретой духовке (175 градусов), около 30 минут. Хлеб проверить минут через 15 — 20 и если нужно прикрыть сверху фольгой. Готовый хлебец вынуть из духовки и оставить минут на 10 остывать на решетке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4384,'Остывший хлеб достать из формы. Приготовить глазурь. Перемешать воду с сахарной пудрой, взбить до гладкости и намазать глазурью хлеб. Глазированный апельсиновый хлеб полностью охладить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4385,'Взбить в емкости жидкий мед, яйца и комнатной температуры молоко. В отдельной емкости перемешать сухие компоненты, исключая орехи. Затем в сыпучую смесь ввести жидкую и хорошо перемешать (как на оладьи).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4385,'Добавить измельченные орехи. Заполнить формы для кексов (на 2/3 объема). Поставить медовые кексы с грецким орехом в нагретую духовку (180 градусов) и печь около получаса. Готовые кексы охладить и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4386,'Наполнить заварочный чайник кипятком, подождать 2-3 минуты, вылить воду, положить в чайник заварку, добавить свежих листьев (можно сухих) черной смородины, залить кипятком, настаивать 5-7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4386,'Разлить по чашкам, добавить в чуть остывший чай мед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4386,'Чай татарский со смородиной и медом хорошо утоляет жажду, тонизирует и способствует очищению организма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4387,'Чернослив и изюм промыть. Картофель почистить, нарезать небольшими дольками и сложить в кастрюлю. Залить водой и варить под закрытой крышкой. За 10 минут до готовности картофеля добавить изюм и чернослив.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4387,'Через 5 минут после их добавления, всыпать сахар и соль. Муку обжарить на сковороде, положить туда же картофель, добавить корицу и масло. Перемешать картофельный цимес с сухофруктами и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4388,'В чашу блендера положить одно целое яйцо и желток. Добавить горчицу, сок лимона, хорошо посолить. Влить 350-400 грамм масла и взбить. Быстрый майонез с лимонным соком готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4389,'Если цветы целые, то необходимо взять рукой все лепестки вместе и отрезать их ножницами так, чтобы основание цветка (там, где лепестки белого цвета), остались на цветке.  А если лепестки уже оторваны от цветка, то ножницами срезать их основания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4411,'Сухофрукты помыть, курагу порезать напополам, можно добавить орехи. Всыпать муку в смесь из яиц, затем добавить соду (погашенную) и смешать. Форму смазать, выложить в нее начинку, разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4389,'На 100 грамм готовых лепестков, нужно взять 100 грамм сахара. Затем лепестки и сахар тщательно растереть. Для того чтобы лепестки легче растирались, их можно крупно порезать. В отдельной емкости приготовить сироп. Смешать 500 грамм сахара, 200 миллилитров воды и лимонный сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4389,'Поставить смесь на огонь и кипятить минут 5-7, затем добавить кашицу из лепестков и сахара. Варить варенье до готовности (минут 10-12). Варенье с лимоном из лепестков розы имеет приятный вкус и тонкий аромат. Разлить варенье в стеклянные банки и хранить в прохладном месте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4390,'Для теста: в глубокой емкости, взбить венчиком (секунд 30) сахар и яйцо. Влить кефир, добавить молотую корицу, перемешать. Яблоки очистить, нарезать мелкими кубиками и добавить в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4390,'Осторожно помешать, чтобы яблоки распределились равномерно. Затем добавить соду и просеянную муку, перемешать. На сковороде разогреть растительное масло, когда масло нагреется огонь немного убавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4390,'Класть тесто на сковороду столовой ложкой (1 столовая ложка теста – 1 оладья). Когда нижняя сторона подрумянится, перевернуть и жарить с другой стороны. Готовые кефирные оладьи с яблоком и корицей выложить на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4391,'Лук натереть на терке или пропустить через мясорубку, положить в фарш. Добавить перец, соевый соус и измельченный чеснок. При необходимости посолить, но учитывать соевый соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4391,'Фарш тщательно перемешать и поставить в холодильник на полчаса. Вынуть из холодильника и сформировать фрикадельки – с расчетом 4 штуки на шпажку. Приблизительно одна фрикаделька будет 25 грамм, а порция получится 100 грамм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4391,'Тесто раскатать в прямоугольник и порезать на полоски шириной немного больше диаметра фрикаделек. Шпажки несколько минут вымачивать в воде. Нанизать на шпажку край теста, затем фрикадельку, потом опять тесто, потом фрикадельку и так далее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4391,'Тесто будет как бы виться между фрикадельками. Противень смазать, выложить на него шпажки и запекать минут 30-40 (180 градусов). Подавать шашлычки в слоеном тесте на шпажках на листьях салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4392,'Приготовить тесто. Для этого в емкости смешать мед и воду (подогретую – 30-35 градусов), добавить сухие дрожжи, оставить минут на 5-10. Когда дрожжи начнут пениться, влить масло, посолить и хорошо перемешать. Всыпать стакан муки и еще раз размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4392,'Далее, понемногу добавляя муку, замесить тесто. Тесто намазать маслом, уложить в емкость, накрыть сверху салфеткой и поставить в теплое место, чтобы поднялось (приблизительно час). Лук нашинковать и слегка поджарить. В небольшую кастрюлю положить томатный соус, добавить приправы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4392,'По желанию можно добавить сахар. Варить соус около 5-7 минут. Нарезать итальянскую колбасу. Поджарить колбасный фарш на сковороде с растительным маслом. Когда тесто поднимется, поделить его на 4 части, каждую раскатать в пласт, смазать соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4392,'На одну часть теста выложить фарш и часть лука жареного. Сверху присыпать натертым сыром и нарезанной пепперони. Накрыть свободной стороной теста и фигурно защипнуть края. Смазать домашнюю закрытую пиццу с пепперони яйцом и печь до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4393,'Взять курицу, которая бы подходила по размеру к духовке. Она должна стоять в полный рост на банке. Налить пиво в банку (0,5 литра) и поставить ее в форму для запекания. На банку одеть курицу, как можно плотнее, чтобы не упала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4393,'Приготовить смесь для обмазывания курицы – сметану смешать с измельченным чесноком, перцем и солью. Очень тщательно обмазать ею курицу со всех сторон и отправить в духовку, приблизительно на 1 час 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4393,'Но нужно ориентироваться по образовывавшейся корочке и по соку, который будет вытекать после прокола мяса ножом (у готового мяса течет прозрачный сок, без примеси крови). Готовую сочную курицу, запеченную на банке, снять и подать к столу, порционно нарезав.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4394,'Налить в емкость воду, добавить дрожжи, немного сахара. Отставить минут на 10, пока не появится пена. Отдельно перемешать масло, яйца, соль и сахар. Влить в смесь с дрожжами и перемешать. Потом добавить половину муки, еще раз перемешать. Затем частями добавляя оставшуюся муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Поставить в мультиварку на 17 или 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4394,'Муки может пойти немного меньше или больше, указанного в рецепте количества. Тесто сформировать в шар, прикрыть салфеткой и отправить в теплое место, для расстойки (примерно на час-полтора). Потом помять тесто и сформировать булочки (круглые). Уложить их в смазанную маслом форму с некоторым расстоянием друг от друга (примерно 1-1,5 сантиметра).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4394,'Прикрыть сверху и дать им еще раз подойти (минут 45). Затем поставить в нагретую духовку (180 градусов), и выпекать около 45 минут, пока они не станут золотистого цвета. Вынуть пышные булочки к обеду из духовки, сразу смазать растопленным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4395,'В воде (обязательно теплой) развести дрожжи, соль и сахар. Всыпать часть муки, смешать. Положить манную крупу (пару столовых ложек), влить оливковое масло, а затем понемногу вмесить оставшуюся муку. Вымесить тесто и поставить в теплое место, чтобы поднялось. Сверху прикрыть. Поднявшееся тесто для итальянской пиццы обмять и поделить пополам – получится тесто для двух пицц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4396,'Для начала пассируем овощи. Налить оливковое масло, положить измельченные шампиньоны, морковь и лук. Добавить томатный соус и сметану. Переложить овощную смесь в горшочек и заняться фрикадельками. Лук и чеснок предварительно измельчить. Рис отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4396,'Смешать подготовленные продукты. Сформировать фрикадельки и немного их обжарить на сковородке. Для тех, кто следит за своей фигурой – это не обязательно. Можно сразу фрикадельки уложить в горшочек на овощи. Залить овощным бульоном так, чтобы фрикадельки немного выглядывали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4396,'Можно добавить любые любимые приправы (может быть гвоздика, перец горошек, кориандр). Лавровый лист ложить в конце (примерно за 5 минут до готовности). Поставить в духовку приблизительно минут на 30 (190 градусов). Вынуть горшочек из духовки, фрикадельки в горшочке по-русски готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4397,'Взять хлопья кукурузные и искрошить их (с помощью скалки и пакета). К крошке добавить корицу и кокосовую стружку. Перемешать и выложить в неглубокую миску, Яйца взбить (венчиком). Из сливочного мороженого сделать шарики и уложить их на бумагу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4397,'Каждый шарик сначала обвалять в крошке, потом в яйце, а потом снова в крошке. Чтобы шарики не таяли, их можно пока поставить в морозилку. В небольшой кастрюльке (лучше с толстым дном) нагреть масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4397,'Каждый шарик обжарить во фритюре, на сильном огне, около 20-25 секунд. Выложить жареное мороженое в хрустящей панировке на салфетку, чтобы стек излишний жир. Подавать мороженое, украсив по желанию свежими ягодами или фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4398,'В отдельной емкости перемешать все сухие ингредиенты для теста. Добавить к ним оливковое масло, воду и вымесить мягкое эластичное тесто. Уложить его в миску, смазанную маслом, прикрыть и отправить подходить в теплое место, приблизительно на 45 минут или на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4398,'Соус: потушить пюре из измельченных помидоров на небольшом огне минут 20, часто мешая. Приблизительно за 5 минут до готовности, добавить сахар, соль, измельченные зубчики чеснока и столовую ложку оливкового масла. Соус загустеет при варке. Затем его немного охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4398,'Начинка: нарезать салями, ветчину и два вида сыра. Подошедшее тесто, раскатать в лепешку, толщиной приблизительно 5 миллиметров (сначала нужно немного растянуть тесто руками, а потом использовать скалку). На большую часть теста нанести остывший соус, на него выложить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4398,'Прикрыть начинку оставшейся частью теста так, чтобы она не вытекала. Сверху сделать несколько надрезов. Побрызгать оливковым маслом и притрусить орегано. Отправить пиццу в духовку (220 градусов) приблизительно минут на 10 (время выпечки зависит от духовки и толщины теста). Пицца «Кальцоне» с домашним соусом готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4399,'Сначала необходимо приготовить маринад: перемешать соус соевый и чеснок (измельченный). Положить сердечки в маринад и отставить ненадолго. Затем надеть сердечки на шпажки и запечь куриные сердечки в соевом маринаде на противне, в духовке, полив сверху оставшимся соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4400,'Приготовить миндальную муку. Миндаль (30 г) залить водой (горячей) и дать настояться приблизительно 10 минут. Воду слить и снять с миндаля кожуру, промыть теплой водой. Подготовленный миндаль просушить в микроволновке минуты 3-4 и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4400,'Затем положить миндаль в чашу блендера и перемолоть его в муку. В емкости соединить миндальную муку, разрыхлитель и муку, перемешать. Цедру лимона натереть, растопить масло (70 грамм). Яйца с сахаром взбить в пышную пену и, не переставая взбивать, добавить лимон (натертую цедру), миндаль с мукой, затем масло (топленное).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4400,'Еще некоторое время (1 минуту) взбивать, на медленной скорости. Формочки смазать маслом и налить в них тесто, наполовину, потому что печенье будет увеличиваться. Во все формочки положить по одному целому ореху миндаля. Печь в духовке минут 10-12. Готовое миндальное печенье «Мадлен» с сюрпризом охладить и вынуть из формочек. Украсить сверху миндалем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4401,'Сварить пасту. Приготовить соус. Измельчить мелко лук, перец и травы (чем меньше будут кусочки, тем однороднее будет соус). Обжарить травы, лук и перец на оливковом масле, добавляя каждый продукт на сковороду поочередно, через 1-2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4401,'Когда овощи станут мягкими – добавить мидии. Аккуратно положить их к овощам и накрыть сковородку крышкой. Как только мидии раскрылись, снять с огня, так как морепродукты становятся резиновыми при чрезмерной термообработке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4401,'Те мидии, что не раскрылись, можно выбросить. Добавить в сковородку пасту и перемешать. Черную пасту с мидиями и овощами подавать к столу, взбрызнуть соком лайма или лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4402,'Этот национальный напиток готовят из плиточного чая, дать воде закипеть, положить чай, добавить молоко, кипятить, помешивая, 5 минут, добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4402,'Классический татарский чай подается в пиалах с кусочком сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4403,'На медленном огне сварить мясо с добавлением перца горошком и лаврового листа. Необходимо, чтобы бульон был прозрачным. Затем мясо вынуть и отделить его от костей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4403,'Взять казанок с толстым дном, уложить на дно картошку (если крупная, порезать), на нее уложить сверху мясо, затем лук, нарезанный полукольцами. Далее положить очищенные от шкурки и нарезанные полукольцами помидоры. Затем порезанный кольцами перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4403,'Присыпать все большим количеством измельченной зелени. Поперчить, посолить и варить под крышкой приблизительно полчаса. Армянскую хашламу из говядины можно подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4404,'Мед положить в воду, по собственному вкусу (можно добавить больше меда или меньше, или добавить сахар). Вообще, сильно сладким он не будет, так как присутствует лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4404,'Сюда же в воду насыпать специи: гвоздику, натертый имбирь и корицу. Довести всю эту смесь до кипения и оставить немного покипеть (минут 5). В процессе приготовления образуется много пены, ее необходимо снять, но только в конце варки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4404,'Если снимать раньше, то есть вероятность, что вместе с пеной можно удалить из воды все пряности. Из лимона выжать сок, добавить его в сбитень и процедить. Традиционный пряный сбитень готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4405,'Немного подогреть молоко, добавить дрожжи, просеянную муку (100 грамм), сахар, перемешать, накрыть полотенцем и поставить в теплое место примерно на час. Сделать начинку: сварить опята и охладить, картофель сварить, сделать из него пюре и тоже охладить. Лук мелко порезать и поджарить до золотистого цвета, укроп измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4405,'Все составляющие начинки перемешать, посолить, поперчить по вкусу. Вернуться к тесту: просеять оставшуюся муку, добавить яйца. Растопить сливочное масло, немного его охладить и влить в тесто. Вымесить тесто и оставить на пару часов, чтобы поднялось. Стол притрусить мукой и можно делать кныши.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4405,'Оторвать от общего количества немного теста, раскатать его в круг, сделать с четырех сторон небольшие надрезы. Выложить в центр начинку (можно по чайной или столовой ложке – зависит от диаметра круга), загнуть один лепесток сбоку на начинку, затем загнуть противоположный лепесток, а потом два оставшихся лепестка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4405,'Между собой лепестки можно скрутить или защипнуть. Выставлять подготовленные кныши на противень, но необходимо учитывать, что они в духовке поднимаются и расширяются. Взбить яйцо вилкой и обмазать сверху изделия (чтобы были румяными). Поставить кныши с картофелем и опятами в духовку минут на 20-25 (200 градусов).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Измельчить зелень, сыр.','https:https://st.vkuso.ru/data/cache/thumb/71/efdaae913e8f971_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4406,'Яйца, сахар, кефир, ванильный сахар, разрыхлитель и растопленный маргарин взбить венчиком. Отставить минут на 5. Начинка: промыть изюм, натереть цедру лимона и измельчить другие ингредиенты. Добавить в тесто просеянную муку, оно должно быть густым, но перемешиваться ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4406,'Добавить цукаты и изюм, помешать. Форму смазать и вылить в нее тесто, лопаткой разровнять. Печь 40-60 минут (в зависимости от объема формы), при 180 градусах. Охлаждать минут 15 и переложить на блюдо. Кекс на кефире «Любимый» можно притрусить сахарной пудрой или полить глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4407,'Филе птицы мелко порубить, переложить в емкость (глубокую). Добавить к нему творог, томаты, зелень и грибы, поперчить и посолить, помешать. С целого кочана пекинской капусты снять 8 листов, опустить их в кипяток минуты на 2-3.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4407,'Капустные ребра можно отрезать с помощью острого ножа или отбить молоточком. Начинку из мяса выложить на капустные листы и закрутить голубцы. Переложить их в смазанную форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4407,'Соус: перемешать томатную пасту с размельченным чесноком и зеленью, влить немного воды. Соусом залить голубцы на листьях пекинской капусты, поместить в духовку на 35-40 минут. Кушать со сметаной и присыпав зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4408,'Нагреть духовку (175 градусов), решетку поставить на средину духовки. Форму намазать маслом и выложить бумагой для выпечки. Ром, ваниль и кофе смешать в небольшой емкости до полного растворения. Вбить туда же яйца и отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4408,'Отдельно смешать муку, соль, разрыхлитель и какао. В другой небольшой емкости перемешать миндаль, изюм и часть муки (1/4). В чаше блендера взбить на высокой скорости масло и сахар (3 минуты), пока масса не станет бледно-желтого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4408,'Убавить скорость и добавить яичную смесь. Убавить скорость до минимальной и ввести сухую смесь, чередуя ее со сметаной. После добавления последней порции сухой смеси взбивать (секунд 15), а потом добавить изюм и миндаль в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4408,'Немного взбить и перелить тесто в форму. Печь примерно час, затем полностью охладить. Для глазури соединить ром, сметану, сироп, соль и кофе. Положить в кастрюлю и довести до кипения (средний огонь). Затем убрать с огня, добавить поломанный шоколад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4408,'Мешать, пока шоколад полностью не растает. Глазурь должна быть однородной. Залить ею охлажденный кекс. Оставить минут 30, чтобы глазурь застыла. Шоколадный кекс в горьком шоколаде можно подавать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4409,'Хлеб нарезать кубиками. Духовку нагреть (165 градусов), противень накрыть фольгой и смазать маслом. Мед, корицу смешать со сливочным маслом, в эту смесь положить кубики из хлеба. Обвалять их в смеси и уложить на противень (обязательно в один слой).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4409,'Отправить их в духовку минут на 15-20 , перемешивать каждые 5 минут. В небольшую кастрюлю налить сидр и варить, пока он не уменьшится в объеме и не загустеет. Потом добавить чеснок (измельченный), горчицу, уксус и взбить. Влить постепенно оливковое масло, постоянно помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4409,'Посолить, поперчить по вкусу. Нашинковать капусту тонкими полосками, выложить ее на две тарелки, сверху положить измельченные яблоки и голубой сыр. Приправить салат из яблок с брюссельской капустой сухариками и взбрызнуть заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4410,'Пропустить мякоть баранины дважды через мясорубку с маленькими отверстиями, во второй раз прокрутить вместе с зеленым луком, посолить и поперчить, долить немного воды и вымесить фарш до однородности, сделать из репчатого лука зажарку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4410,'Раскатать тесто в тонкий пласт, вырезать квадраты, На половину каждого положить ложку начинки, свернуть по диагонали и хорошо защипать края, противоположные углы соединить как у пельменей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4410,'Довести соленую воду до кипения, положить пельмени, дождаться всплытия и проварить еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4410,'На пельмени из баранины с луком по-татарски выложить зажарку и полить сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4411,'Приготовить тесто. Взбить яйца с сахаром в густую пену (масса должна возрасти в пару раз) и отставить. Яблоки очистить, сердцевину вырезать, мякоть нарезать тоненькими пластинами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4434,'Присыпать измельченным укропом, завернуть рулетом. Поместить на 2 часа в холодильник. Нарезать сырную закуску в тонком лаваше острым ножом и выложить на салатные листья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4411,'Сверху налить тесто и отправить в духовку. Печь 20-25 минут. Затем достать, залить сметаной перемешанной с ягодами и сахаром и поставить быстрый пирог с яблоками и курагой  в духовку еще минут на 5-7.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4412,'Сложить все компоненты для соуса в чашу кухонного комбайна и измельчить. Разрезать вырезку пополам вдоль на 2/3 глубины куска. Развернуть и немного отбить, чтобы мясо стало более плоским. Положить начинку по центру, вдоль вырезки и свернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4412,'Либо, как вариант, можно подготовить два куска вырезки. В этом случае выложить начинку и накрыть вторым куском вырезки (в зависимости от выбранного способа). Обвязать мясо ниткой. Обернуть пару раз вдоль и завязать простым узлом (нитку не обрезать).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4412,'Затем обернуть нить вокруг собственной руки, чтобы получилась петля. Одеть петлю на мясо и закрепить. Таким образом обвить ниткой весь кусок, край завязать. Обмазать вырезку оливковым маслом, положить на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4412,'Жарить приблизительно полчаса (200 градусов), при этом необходимо один раз мясо перевернуть. Вынуть готовую свинину, фаршированную соусом песто, из духовки, обернуть фольгой, дать постоять минуты три, затем можно снять нитку и нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4413,'Разрезать на порционные кусочки рыбу. Смешать соевый соус, мед и горчицу. Залить получившимся соусом рыбу и поставить минут на 15 в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4413,'Вынуть из холодильника, присыпать кунжутом и запекать в духовке минут 15 (170 градусов). Легкий и сочный лосось с медом и горчицей из духовки готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4414,'Нагреть духовку, смазать форму маслом. Растопить масло сливочное, к нему добавить и все оставшиеся ингредиенты. Смешать до однородности и перелить в форму. Выпекать 30-45 минут, потом немножко остудить и достать из формы. Притрусить шоколадный шведский торт пудрой сахарной и кушать теплым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Нагреть духовку (175 градусов). Смазать маслом форму (объемом 3 литра). Карамельный соус: в сковороду с толстым дном насыпать сахар и встряхнуть, чтобы сахар распределился по всему дну равномерно (лучше использовать широкую, чтобы сахар на ней лежал не толстым слоем).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Поставить на небольшой огонь и подождать, пока сахар не расплавится и не станет темно-коричневого оттенка (5-6 минут). Сахар не перемешивать, пока он не карамелизуется. Когда сахар полностью растает, добавить к нему 1/3 сливок, тщательно перемешать. Затем добавить оставшиеся сливки и варить 2-3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Карамель будет жидкой (она загустеет, когда остынет). Снять с огня и равномерно распределить по дну подготовленной формы. Смешать сухие ингредиенты для кекса (корицу, соль, какао, соду и муку). Растопить масло и шоколад. Добавить к нему сахар, кефир, яйца, ваниль и взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Затем добавить мучную смесь и снова перемешать. Получившееся тесто перелить в форму на карамель. Все ингредиенты для флана взбить миксером, аккуратно его вылить на тесто. Форму поставить в большую форму или противень с высокими бортами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Налить в большую форму горячую воду, до середины формы с десертом. Печь в духовке в течение 80-90 минут. Воткнутая зубочистка должна выходить из готового кекса только с несколькими влажными крошками. Аккуратно вынуть десерт из духовки и охладить в форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4415,'Затем отправить в холодильник (на ночь). Для того, чтобы остывший пирог вынуть из формы, необходимо наполнить большую емкость водой (горячей) и опустить в нее нижнюю часть формы. Карамель немного растает. Потом перевернуть форму на плоское блюдо. Нежный шоколадный флан подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4416,'Раскатать готовое сдобное дрожжевое тесто по диаметру чуть больше сковороды, чтобы можно было сделать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4416,'Очистить и нарезать яблоки дольками, предварительно удалив сердцевину, выложить их ровным слоем на тесто, присыпать сахаром, залить сметаной, посыпать растертым в крошку печеньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4416,'Отправить яблочный пирог по-татарски в духовку и выпекать 20 минут при средней температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Просеять сахарную пудру и миндальную муку вместе. Нагреть духовку и пересыпать эту смесь на противень с пергаментной бумагой. Подсушить в духовке минут 5. Просеять еще раз. Сюда же просеять какао, хорошо перемешать, добавить белок и отставить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Сформировать шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Смешать в кастрюльке воду и сахар, поставить на медленный огонь и помешивая довести до кипения. Сахар должен полностью раствориться. Периодически проводить кисточкой по стенкам кастрюли, чтобы сахар там не оставался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Увеличить огонь, нагреть сироп до 120 градусов и сразу снять кастрюлю с огня. Миксером взбить сухой белок с предварительно состаренными яичными белками, до пышной пены. Очень медленно ввести, тонкой струйкой, сахарный горячий сироп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Взбивать массу, пока она не станет густой, блестящей и гладкой. Если все взбито правильно, то белки не будут вытекать из перевернутой емкости. В миндальную смесь со свежим белком добавить меренгу и перемешать. Смешивать аккуратно снизу вверх, поворачивая тарелку против часовой стрелки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Тесто должно получиться однородным, мягким и плавно растекаться. Переложить его в кулинарный мешок и отсадить на противень кружочки диаметром 3-4 сантиметра. Отставить в сторону (от получаса до часа), пока не появится на них легкая корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Именно из-за этого в дальнейшем образуется «юбочка». Разогреть духовку (200 градусов). Когда макаруны будут готовы к запеканию, выключить духовку, поставить их в нее, закрыть дверцу и оставить там минут 10. Готовые макаруны без труда снимутся с бумаги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Шоколадный крем: шоколад поломать на кусочки и положить в миску. Сливки отдельно довести до кипения и вылить в шоколад. Подождать секунд 30 и можно начинать размешивать до однородности. Потом положить сливочное масло и опять перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4417,'Переложить крем в кондитерский мешок и отсаживать на одну макаруну, а второй закрывать сверху, немного прижимая. Поставить шоколадные макаруны с шоколадным кремом на ночь в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4418,'Подготовить овощи. Очищенный репчатый лук, перец и помидоры разрезать на 4 части, положить их в чашу комбайна (насадка нож), добавить перец чили, чеснок и измельчить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4418,'Перелить этот соус в кастрюлю (обязательно с толстым дном), варить примерно 1 час на среднем огне. Затем перетереть соус сквозь сито (чтобы убрать косточки и кусочки кожицу).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4418,'Перелить смесь обратно в кастрюлю, добавить горчицу, паприку, два вида сахара, соль и уксус. В кусочек марли положить палочку корицы, душистый перец, гвоздику и опустить в соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4418,'Варить еще приблизительно час, постоянно помешивать, кастрюлю прикрывать крышкой. Вынуть марлю со специями и перелить томатный кетчуп с чили и пряностями в стерилизованные банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4419,'В молоко (обязательно теплое) добавить дрожжи и 1 чайную ложку сахара. Отставить, чтобы дрожжи ожили. Потом добавить сливочное масло и яйца (можно и ванилин), перемешать. Частями добавлять муку и перемешивать ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4419,'Тесто получится липкое и мягкое. Отставить приблизительно на час, чтобы поднялось (сверху прикрыть). Потом переложить его в форму (диаметр 21 сантиметр), смазанную маслом. Тесто распределить руками (смазать растительным маслом) и отставить еще на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4419,'Порубить сахар со сливочным маслом и поставить в холодильник, чтобы не растаяло. Когда истечет полчаса, намочить палец растительным маслом и сделать углубления по всей поверхности теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4419,'Притрусить рубленым маслом с сахаром и отправить в духовку на 25-30 минут. Спустя 25-30 минут пирог достать, залить сливками (можно и сметаной) и отправить снова на 6-9 минут в духовку. Употреблять сахарный пирог под сливками горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Сделать опару, накрыть полотенцем и отставить минут на 30-40. Тесто: в чашу миксера положить яйца, опару и перемешать. В другую емкость просеять муку, положить сахар, соль и смешать. Добавить сухие ингредиенты к опаре и мешать 2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Оставить приблизительно на 5 минут. Затем вымесить тесто насадкой для теста, постепенно добавляя сливочное масло (по 1/4 столовой ложки). Получится мягкое и гладкое тесто. Обернуть его пленкой и отправить в холодильник (на 4 часа минимум, а лучше на ночь).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Приготовить начинку. Молоко подогреть. Муку, сахар, какао и белки смешать и влить горячее молоко, постоянно помешивая, чтобы белки не свернулись. Массу перелить в кастрюлю, поставить на огонь и варить до загустения. Убрать с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Выставить режим «Выпечка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Положить сливочное масло и мешать до его полного растворения. Переложить эту массу в лоток и поставить в холодильник. Процесс приготовления бриоши похож на приготовление слоеного теста. Поверхность стола притрусить мукой и раскатать тесто в прямоугольник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Уложить на него начинку, завернуть края к центру, защипнуть. Затем тесто раскатать опять в прямоугольник и свернуть, чтобы края оказались внутри. Раскатать тесто еще раз и свернуть прямоугольник по длинной стороне в рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4420,'Острым ножом порезать на 12 частей, положить их в форму для кексов и дать подойти минут 30-40. Выпекать в нагретой духовке (180 градусов) минут 15-20. Вынуть бриоши с шоколадной начинкой из духовки, достать из форм, положить на решетку и охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4421,'Подготавливаем продукты. Куриную грудку нарезать небольшими кусочками. Салатный лук очистить и тонко нарезать прозрачными полукольцами. Отваренные в течение 9 минут яйца остудить, залив водой, очистить и разобрать на составляющие. Желтки размять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4421,'Белки же натереть на терке, как и сыр, а так же отваренный картофель. Пекинскую капусту нарезать тонко. Собрать салат. Глубокий салатник смазать майонезом. Первым слоем выложить картофель, накрыть луком. Дать немного соли, перца и промазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4421,'Выложить куриное мясо. Далее выложить белки и сыр, сделать майонезную сетку. Присыпать тертыми желтками и сверху выложить немного капусты, распределив по салату так, чтобы проглядывались желтки. Простой салат «Лебединый пух» можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4422,'Заварить кофе в гранулах в 40 мл горячей воды. Отставить для приготовления кофейного мусса. Приготовить основание из теста: растопить на водяной бане масло и соединить с какао порошком. Затем нагреть на огне и всыпать сахар, помешивать до полного растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4422,'Немного остудить. Всыпать муку, немного разрыхлителя для теста и размешать. Отдельно взбить яйцо и ввести в жидкое тесто. Разъемную форму выстелить пергаментом смазанным маслом, переложить туда тесто, и поставить в разогретую до 180 градусов духовку на 10- 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4422,'Корж из формы не вынимать. Приготовить мусс. Замочить желатин в молоке. Отдельно сварить сироп из сахарной пудры смешанной с 4ст.л. воды. Отделить желтки и взбивать их венчиком до побеления массы. Продолжая взбивать, ввести в желтки горячий сахарный сироп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4422,'Масса должна стать более густой и кремообразной. Набухший желатин поставить на огонь, и, не доводя до кипения растворить. Ввести желатин в яичный крем, влить кофе. Взбить сливки в густую пену и по ложке подмешать в яичную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4422,'Переложить мусс в форму с коржом и поставить остывать в холодильник минимум на один час. Снять разъемную форму и переложить нежный торт с кофейным муссом на блюдо. Можно украсить кофейными зернами из мастики или присыпать какао через трафарет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4423,'Масло размягчить при комнатной температуре. Добавить сахар и взбить венчиком. Продолжая взбивать, вбить одно за другим охлажденные яйца. Влить простоквашу и размешать. Муку просеять через сито, насытив кислородом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4423,'Смешать муку с содой или разрыхлителем и понемногу добавить в смесь, получится жидкое тесто. Снять с яблок кожуру, вынуть семена, разрезать мякоть на кубики и сбрызнуть лимонным соком – это предотвратит окисление поверхности и дальнейшего потемнения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4423,'Добавить яблоки в тесто и перемешать до равномерного их распределения. Форму средней глубины, лучше керамическую, смазать маслом и присыпать манной крупой или панировочными сухарями. Выложить тесто и разровнять лопаточкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4423,'Поставить выпекаться при средней температуре около получаса, для разных духовок разное время выпекания, ориентироваться нужно, проверяя готовность лучиной или зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4423,'Такой рецепт классической шарлотки на простокваше подходит и для приготовления в мультиварке. Готовую шарлотку вынуть из формы и присыпать по желанию сахарной пудрой, к которой можно добавить щепотку корицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4427,'Отварное мясо разобрать на полоски, ветчину нарезать продолговатой тоненькой соломкой. Маринованные шампиньоны нарезать слайсами, тонко. Отварные яйца разделить, белки перетереть на терке или нарезать пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Приготовление состоит из нескольких частей: выпекание омлета, приготовление начинки, сборка рулета и его настаивание в холодильнике. Готовим рулет. Крабовые палочки, не размораживая, натереть на крупной терке. Зелень укропа промыть и мелко изрубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Взбить 5 яиц с молоком, прибавить просеянную муку, соль и еще раз размешать. В полученное тесто добавить зелень и крабовые палочки. Противень застелить бумагой для выпечки, смазать жиром. Вылить смесь, для омлета распределяя равномерно вкрапления палочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Очень важно ровно выставить духовку, чтобы высота омлета была равномерной. Поставить в ранее нагретую духовку и выпекать 10-15 минут. В середине приготовления заглянуть в духовку и сделать проколы в местах образования пузырей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Вынуть омлет из духовки и дать ему остыть. Из тертого сыра, оставшихся отваренных яиц и майонеза сделать начинку. Добавить измельченную зелень, тертый чеснок и перемешать. Можно разнообразить начинку, так как позволяет ваша фантазия.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Например, уместными будут добавки из крабовых палочек, разноцветного сладкого перца и даже консервированной кукурузы. Перевернуть на разостланную пищевую пленку остывший омлет, снять с его поверхности бумагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4424,'Смазать равномерно приготовленным кремом и аккуратно свернуть при помощи пленки. Завернуть в пленку и оставить на холоде настаиваться около 5 часов. Нарезать рулет из яиц и крабовых палочек ломтиками и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Отварить в подсоленной воде яйца, остудить и почистить. Нарезать мелко. Овощи помыть и сварить в кожуре, до мягкости. Остывшие картофель и морковь очистить и натереть на очень крупной терке. Маринованные огурцы нарезать так же мелко, как и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Ветчину порезать тонкими брусочками. В глубокую миску с широким дном выложить грибы шляпками вниз. Выкладывать следует плотно, так как это будет, позже, верхушкой салата, имитируя грибную полянку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Для большей натуральности можно нарубить зелени и выложить между ножками грибов, заполняя просветы между шляпками. Тертый картофель аккуратно распределить между ножками грибов и слегка утрамбовать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Таким образом, ножки грибов будут выступать в роле якорей, благодаря которым верхушка не будет слетать с готового блюда. Смазать майонезом. Следующим слоем выложить ветчину, так же нанести майонезную сетку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Затем выложить отварную морковь, присолить и так же полить майонезом. Выложить яйца, разровнять и немного прижимая ложкой нанести майонез. Последним слоем выложить огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Поверх салата положить пищевую пленку, немного прижать и накрыть тарелкой, диаметр которой войдет в миску. Настоять салат в течение нескольких часов. Убрать тарелку, снять пленку, накрыть широким плоским блюдом и перевернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4425,'Снять салатник и подравнять края. Смазать края майонезом и притрусить рубленым укропом. Оригинальный салат с опятами смотрится очень колоритно на праздничном столе, вызывая улыбку и, несомненно, аппетит.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4426,'Взбить венчиком сахар и яйца. Мед чуть растопить на паровой бане и понемногу ввести в яичную смесь. Затем влить кефир, лучше брать трехпроцентный, и всыпать соду, которая погаситься кефиром. Все тщательно взболтать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4426,'Ввести просеянную муку, тесто получиться немного вязким, вымешивать его не стоит, так как коржи наливные, по типу бисквитных. Разделить тесто на четыре одинаковые части и поочередно выпекать в смазанной маслом разъемной форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4426,'Коржи остудить переложив их на решетку. Затем разрезать на 2 части каждый. Чем тоньше коржи, тем лучше они пропитаются кремом. Приготовить традиционный крем из размягченного сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4426,'Сбить масло со сгущенным молоком, с добавлением какао. Перемазать коржи кремом, присыпать дроблеными орехами или крошками от коржа и дать настояться для лучшей пропитки. Торт «Медовик» с темным кремом подавать с ароматным чаем или с кофе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4427,'Предварительно отварить куриную грудку и яйца. Сырой картофель натереть на терке для моркови по-корейски и обжарить на сильном огне, в большом количестве растительного масла не перемешивая, а перевернув с одной стороны на другую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Всыпать муку, быстро перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4427,'Смешать мясо, ветчину, белки и грибы, заправить майонезом и присолить. На широком плоском блюде разложить веночком листья салата, посередине установить стакан. Выложить салат в одном направлении, формируя валик вокруг стакана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4427,'Вынуть стакан, на его место положить немного салата, так чтобы углубление осталось. Сверху салата выложить обжаренный картофель. Натереть на терке, смоченной водой, плавленый сыр, чеснок и желтки. Все смешать с каплей майонеза, добавить измельченный укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4427,'Мокрыми руками скатать из полученной массы три колобка, придать им форму яиц. Выложить яйца посередине импровизированного гнезда. Традиционный салат «Гнездо глухаря» не стоит делать заранее, так как слой из картофеля отсыреет и потеряет свои вкусовые качества.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4428,'Творог слегка размять и смешать с яйцами. Добавить сахар и чайную ложку разрыхлителя. Еще раз все перемешать. В просеянную муку добавить половину ложки разрыхлителя и, перемешав, насыпать ее на ровную поверхность стола.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4428,'Охлажденное сливочное масло перетереть на терке и смешать с мукой или же изрубить масло ножом до получения крошек. Дополнительно размять руками. Разделить крошку на две части. Одну часть выложить на дно формы для запекания, с высокими бортами и чуть утрамбовать ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4428,'Насыпать промытые и высушенные ягоды без косточек. Если ягоды замороженные, предварительно замочить их в кипятке и откинуть на дуршлаг. Сверху выложить творожную массу и разровнять. Прикрыть верхушку пирога оставшейся масляной крошки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4428,'Разровнять крошку и поставить пропекаться при 140-150 градусах в духовой шкаф. О готовности тертого творожного пирога с ягодами оповестит приятный аромат выпечки с нотками молока, а так же золотистая, хрустящая корочка на поверхности изделия.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4429,'Вымыть и почистить фрукты. Положить в блендер киви, взбить до однородности. Влить апельсиновый сок, взбить. Получается воздушная, густая смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4429,'Положить массу в формочки или рюмки с помощью чайной ложки, вставить палочки. Поместить мороженое из киви с соком апельсина на несколько часов в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4430,'Подготовить сковороду и прямоугольную форму 50 на 30 сантиметров. Почистить, вымыть картофель и порезать на тонкие ломтики. Разогреть духовку до 180 градусов. Растопить в сковороде сливочное масло, положить нарезанный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4430,'Обжаривать его минут 20, переворачивая время от времени. Убрать приготовленный картофель с огня. Порезать на небольшие кубики горгонзолу. Выложить в форму для запекания ровным слоем картофель, посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4430,'Распределить сверху слой сырных кубиков, затем слой картофеля и посыпать слегка солью. Слои повторить, закончить сыром. Поместить форму в духовку и готовить минут 15. Хрустящий картофель с сыром горгонзола разложить по тарелкам и подавать в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4431,'Порезать часть рыбы на тоненькие ломтики и положить их на доску. Если кусочки недостаточно большие, то их можно положить несколько внахлест. Приготовить начинку: мелко порезать оставшуюся рыбу и соединить ее с сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4431,'Перемешать. Легче это сделать, если сыр — комнатной температуры. Ровно выложить на рыбу начинку. Свернуть рулетики. Желательно остудить их в морозилке, чтобы сыр затвердел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4431,'Аккуратно порезать на кружочки. Закуска будет смотреться красивей, если рулетики делать тонкими и резать их острым ножом. Выложить рулеты из красной рыбы и сливочного сыра на кусочки огурца или гренки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4432,'В емкости среднего размера соединить сок лимона, тунец, тертую морковь, измельченные петрушку и лук. Яйца отварить вкрутую, вынуть желток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4432,'Начинить каждое яйцо приготовленной начинкой. Закусочные яйца с тунцом и зеленью украсить кукурузой и измельченной зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4433,'Порезать лук полукольцами. Грибы нарезать пластинками. Порезать соломкой крабовые палочки. Обжарить нарезанные ингредиенты по отдельности и соединить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4433,'Добавить крупно натертую, отваренную морковь, измельченный укроп, заправить оливковым маслом, размешать. Салат «Убей меня нежно» можно подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8879,'Грецкие орехи очистить, порубить ножом или размолоть при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4435,'Нагреть в кастрюле воду и сливочное масло. Помешивать, пока масло не растворится полностью. После закипания воды, снять с огня, насыпать муку и быстро замесить тесто. Вбить яйца и размешать до однородности. Тесто должно быть мягким и густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4435,'Разогреть до 200 градусов духовку. Положить на противень специальную бумагу. Используя кондитерский мешок или шприц, выдавить эклеры по 5–10 сантиметров длиной. Готовить минут 20, сделать температуру 150 градусов и выпекать еще 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4435,'После выключения духовки, открыть дверцу и остудить эклеры, не вынимая. Приготовить крем: взбить сметану и сахар. Все эклеры обмакнуть в крем и положить в разъемную формочку. Вылить остальной крем. Поместить на пять часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4435,'Эклеры должны пропитаться кремом. Заранее приготовить глазурь, растопив шоколад на водяной бане. Торт вынуть из формы и полить шоколадной глазурью. Отправить торт «Дамские пальчики» в шоколаде на холод, чтобы глазурь затвердела.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4436,'Смешать в емкости сахар и дрожжи с водой. Отставить на какое-то время для активации дрожжей. Затем добавить в дрожжи поочередно ингредиенты, взбить миксером. Всыпать муку, не переставая помешивать. В 2 ст.л. воды растворить соль и влить в массу, вместе с оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4436,'Увеличить скорость и взбивать еще минут 10. Убрать тесто со стенок посуды, накрыть полотенцем, на время отставить. Когда тесто увеличиться в 2 раза, выложить его на поверхность присыпанную мукой, размять руками и поделить пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4436,'Каждую часть раскатать в круги, имеющие диаметр приблизительно 20 сантиметров. Смазать две чугунные сковороды маслом (оливковым) и посыпать кукурузной мукой. Положить тесто и отставить еще минут на 15. Разогреть духовку до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4436,'На каждую фокаччу положить по 1/2 банки маслин без косточек и по 100 г предварительно натертого сыра. Отправить лепешки в духовку и готовить итальянскую фокаччу с сыром и маслинами минут 20. Готовую фоккачу подавать теплой, в качестве хлеба, к основным блюдам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4437,'Сварить очищенную морковь, мелко порубить, добавить сахар и немного соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4437,'Отварить яйца вкрутую, остудить, мелко порезать, смешать с морковью, добавить масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4437,'Из готового дрожжевого теста сделать небольшие лепешки, положить морковный фарш и сформовать в форме полумесяца пирожки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4437,'Морковная сумса по-татарски жарится на сковороде с большим количеством подсолнечного масла до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4438,'Взбить на небольшой скорости масло и сахар. Медленно добавить пять желтков, и продолжить взбивание. Посеять в смесь муку. Замесить тесто. Отщипывать от теста кусочки и раскатывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4438,'Сформировать печенье произвольной формы. Смешать оставшийся желток с молоком и смазать кисточкой все печенья, как можно гуще. С помощью зубочистки нарисовать на яичной глазури узоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4438,'Положить печенье на противень, застеленный специальной бумагой. Выпекать рассыпчатое печенье «Бретон» минут 15, соблюдая температуру 180 градусов. Готовое печенье идеально подойдет к чаю или кофе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4439,'Обжарить кролика на оливковом масле. Отдельно поджарить бекон и положить к кролику. В той же сковороде растопить масло сливочное, поджарить лук, сельдерей и чеснок. Добавить петрушку и тимьян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4439,'Положить все к кролику, добавить картофель и грибы. Размешать. Поместить массу в горшочки, залить вином. Закрыть кролика в винном соусе крышкой и поставить на 55 минут в духовку. Готовить при температуре 175 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4440,'Разогреть духовку до 180 градусов. Вымыть, обсушить, порезать куриную грудку, посыпать перцем и солью. Положить ее в сковороду, налить минут 5, после закипания. Переложить мясо в формочку для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4440,'Вымыть грибы, порезать на крупные кусочки. Лук порезать на полукольца. Мелко порубить или раздавить чеснок. Натереть морковь. Обжарить ингредиенты, кроме чеснока, на сухой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4440,'Налить бульон, посыпать приправами, дать 1/3 жидкости выпариться. Практически в готовый соус положить чеснок. Вылить грибной соус на мясо, накрыть крышкой или обернуть фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8879,'Репчатый лук очистить, нарезать кубиками и обжарить на масле до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4440,'Готовить 20 минут в духовке. Убрать крышку или фольгу посыпать сыром и готовить курицу с сыром в грибном соусе еще минут 5, до образования корочки. Готовую курицу подать с любым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4441,'Порезать кусочками сырое филе. Затем измельчать его в блендере, пока не образуется кремообразная масса. Всыпать по вкусу соль и перец, положить белки. При желании добавить мускатный орех.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4441,'В фарш влить холодные сливки, хорошо перемешать. На кусок полиэтиленовой пленки, прямоугольной формы, положить 1/3 фарша, завернуть колбаской, края закрепить нитками. Повторить процедуру с остальным фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4441,'Получится три колбаски. Налить в кастрюлю воду, поставить на минимальный огонь, чтобы вода не закипела. Положить в воду колбаски и придавить их блюдцем, чтобы не всплыли. Готовить примерно 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4441,'Вынуть готовые куриные колбаски и остудить. Снять пленку. Разложить на столе специальную бумагу, присыпать ее приправами или специями, можно использовать итальянские травы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4441,'На приправы положить колбасу и завернуть ее в бумагу. Повторить эту процедуру со всеми колбасками. Убрать в холодильник минимум на 8 часов. Подавать куриную колбасу в пряностях порезав на ломтики, в качестве закуски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4442,'Порезать мясо на кусочки, отбить, запечь в духовке или поджарить. Крупно натереть сыр, смешать со сметаной. Залить данной смесью мясо, чуть-чуть потушить. Говядина в сырно-сметанном соусе быстро готовится и получается нежной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4443,'Порезать говядину кубиками и пожарить на сковороде, разогрев предварительно оливковое масло. Положить в емкость, присыпать мукой. Туда же добавить крупно нарезанные морковь и лук. Положить продукты в мультиварку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4443,'Почистить и порезать на мелкие кубики яблоко, добавить к мясу. Смешать томатный сок и горчицу, налить смесь в мясо, посыпать перцем, положить лавровый листик, посыпать сахаром. Перемешивать не нужно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4443,'Готовить гуляш из говядины с горчицей и яблоком в режиме тушения, 60 минут. Минут за 10 до готовности положить измельченный чеснок и размешать. Подать гуляш с любимым гарниром или как самостоятельное блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4444,'Выпекать булочки необходимо в формочках для маффинов, поэтому по форме булочка будет похожа на кекс. Приготовить смесь для смазки: смешать желток и чуть-чуть молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4444,'Для опары смешать 200 г муки, теплое молоко, 1 ч.л сахара и дрожжи. Оставить опару на тридцать минут в теплом помещении. Добавить в опару остальные продукты, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4444,'Замешивать тесто минут 10, тесто должно быть эластичным и мягким. Накрыть пленкой, оставить в тепле на 60–90 минут. После приготовления, тесто разделить на 12 частей, скатать в шарики и отставить минут на 10.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4444,'Каждый шарик поделить еще на три части. Кусочки раскатать скалкой. Чтобы сделать одну булочку, нужно взять три лепешки, сложить пополам, и еще раз пополам. Выложить в каждую форму, вниз уголком, по три лепешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4444,'Расстойка приблизительно 40 минут. Булочки смазать молочно-яичной смесью, присыпать корицей и сахаром. Готовить сдобные французские булочки с корицей минут 25, соблюдая температуру 220 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4445,'Добавить к разведенным в теплой воде дрожжам муку, перемешать, оставить для брожения на 3 часа, опара должна увеличить в объем в 2 раза, а потом снова осесть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4445,'Приготовить рыбный фарш, освободить филе рыбы от кожи, пропустить через мясорубку, смешать с луком, обжаренным до прозрачности, и мелко порубленной зеленью, посолить, добавить перец, мускатный орех, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4445,'Выложить рыбную начинку в середину раскатанного пласта теста, разровнять, края приподнять, закрыть фарш и защипать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4445,'Кулебяку с рыбой по-татарски  переложить на смазанный маргарином противень, украсить сверху веточками из кусочков теста, накрыть тканью и поставить на расстойку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4445,'Перед запеканием в духовке кулебяка прокалывается в 2-3 местах вилкой и смазывается яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4446,'Небольшие морковки натереть, перемешать с грецкими орехами и отставить в сторону. Отдельно взбить сливочное масло с яйцом и коричневым сахаром. В третьей емкости, смешать сливки, молоко, сливочный сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4446,'Получившуюся смесь добавить в масляную смесь, перемешать. Смешать сыпучие ингредиенты и добавить их вместе с морковью и орехами в основную массу. Аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4446,'Подготовленное тесто разлить в формы для кексов, смазанные маслом. Выпекать маффины в духовке 20 минут (180 градусов). Готовые маффины с морковью и грецким орехом выложить на блюдо и по желанию присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4447,'Грушу порезать небольшими кусочками. Поставить сковородку на максимальный огонь и насыпать в нее сахар. Когда сахар начнет плавиться и темнеть, добавить сливочное масло и грушу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4447,'Тушит грушу до золотистого цвета (карамель должна булькать), приблизительно 10 минут, на небольшом огне. По окончании добавить тимьян. Тесто раскатать, уложить в форму и отрезать лишние края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4447,'Творог перетереть с яйцом и можно прибавить немного сахара. Положить начинку на тесто и разровнять. Затем полить карамелью и распределить по всей поверхности кусочки груши.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4447,'Поставить пирог из творога с карамельными грушами в духовку запекаться, пока тесто не приобретет золотистый оттенок (минут 15-20, при температуре 180 градусов). Готовый пирог немного остудить, выложить на блюдо и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4448,'Поломать печенье на кусочки, орехи измельчить, растопить шоколад. Смешать в емкости банку сгущенки, сливочное масло, орехи, печенье и шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4448,'Сформировать смесь в форме колбасы. Отправить сливочную колбаску с грецким орехом в холодильник, на ночь. Готовый десерт порционно нарезать и подать к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4449,'Разрезать пополам персики и удалить косточку. В сковороду всыпать сахар (2 столовые ложки), ванилин и налить воду (4 столовые ложки). В сироп опустить половинки персиков и тушить 10 минут, под закрытой крышкой. Мягкое сливочное масло перетереть с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4449,'Взбить 2 яйца и перемешать. Всыпать муку и вымесить тесто. Выложить персики в форму для выпечки и залить тестом. На первый взгляд теста покажется мало, но когда оно будет выпекаться в духовке, то распределиться по всей форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4449,'Печь пирог приблизительно 45 минут (до золотистой корочки), охладить. Охлажденный пирог с персиками покрыть взбитыми сливками и присыпать маком (можно также украшать и по собственному желанию). Подать пирог с персиками под взбитыми сливками к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4450,'Ножки у шампиньонов оторвать, шляпки хорошо вымыть и убрать воду бумажным полотенцем. Присыпать их черным перцем и солью. Сбрызнуть оливковым маслом. Натереть на терке пармезан и брынзу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4450,'Мелко порезать укроп. Смешать сыр с зеленью и начинить шляпки. Отправить шампиньоны с брынзой и пармезаном в духовку, приблизительно на 20 минут (200-220 градусов). Готовые грибы выложить на блюдо и подать в качестве закуски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4451,'Взять творог и размять вилкой. Вбить яйца, всыпать сахар, немного манки и щепотку соли. Опять хорошо размять. Форму для запекания смазать маслом и притрусить сухарями. Тесто переложить в форму, поверхность разровнять и смазать сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4451,'Прогреть духовку (200 градусов). Поставить форму в духовку. Запекать, пока не появится золотистая корочка. Готовую творожную запеканку кушать со сметаной или сладким вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4452,'Яблоки нарезать дольками, мандарин очистить от кожуры. В кастрюлю влить стакан воды, добавить анис и корицу, довести до кипения. Затем добавить туда же сахар, мандарины, яблоки и гвоздику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4452,'Потом влить вино и прогревать на небольшом огне, не доводя до кипения. Постоянно помешивать.  Когда появится белая пена, убрать с огня. Разлить глинтвейн с анисом и фруктами в стаканы и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4453,'Очистить и нарезать кубиками авокадо и помидоры. Лук нарезать тонкими полукольцами. Подготовленные овощи сложить в емкость, добавить фасоль и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4453,'Перец очистить от семян и очень мелко порезать. Заправка: смешать оливковое масло, соль, сок лайма и черный перец. Полить салат «Техасский» с чили и авокадо заправкой и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4454,'Приготовить тесто, дать ему расстояться, перемолоть мясо в мясорубке с мелкой решеткой два раза, добавить сок лимона, тертую морковь, мелко порезанный перец чили и болгарский сладкий перец, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4455,'Тесто слоеное разморозить. Изюм и курагу ошпарить кипятком, измельчить (все сухофрукты отдельно). Лист теста раскатать и разрезать на 4 листа, по размеру формы. Разложить на одном листе половину кураги и присыпать сахаром по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4455,'Накрыть другим листом теста. На него выложить слой из изюма и тоже присыпать сахаром. Опять накрыть тестом, выложить оставшуюся курагу и снова сахар. Укрыть последним листом теста. Поверхность смазать желтком, смешанным с ложкой воды. Порезать тесто с начинкой, ромбами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4455,'Дорезать не до конца, а только три верхних слоя. Украсить верх грецкими орехами. Пахлаву отправить в разогретую духовку на 10 минут (200 градусов). Вынуть из духовки, полить расплавленным сливочным маслом и вернуть в духовку еще на полчаса (160 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4455,'Сварить сироп (сахар и вода по полстакана). Для аромата добавить мед. У готовой пахлавы на слоеном тесте обновить разрезы (только первые три слоя), полить сиропом и охладить. Готовую, остывшую пахлаву дорезать до конца, выложить на блюдо и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4456,'Заправка: два вида масла смешать и добавить винный уксус. Затем, сюда же, добавить измельченный чеснок и листья базилика. Почистить перец чили от семян и положить в заправку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4456,'Перемешать и пока отставить, чтобы настоялось. Болгарский перец (семена убрать) и помидоры нарезать кубиками. Лук и петрушку мелко измельчить. Добавить к помидорам и перцу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4456,'Посолить, поперчить и осторожно смешать с помощью двух вилок. Влить настоянное масло и перемешать. Перед подачей, положить в салат из помидор, с острой заправкой, порезанные оливки и взбрызнуть соком лайма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4457,'Перемешать сахарную пудру, творог, мягкое масло и сливки. Из массы сформировать брусочки или шарики. Поставить на 10-15 минут в морозилку. Глазурь: шоколад растопить в микроволновке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4457,'Сырки из морозилки вынуть и окунуть в шоколад. С помощью двух вилок обвалять в глазури сырок. Выложить творожные сырки в молочном шоколаде на бумагу и отправить в холодильник, для застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4458,'Четыре ломтика хлеба смазать горчицей и майонезом. На 2 из них выложить ломтики ветчины, сверху положить сыр. Накрыть другим ломтем хлеба. Аккуратно обрезать фигурным ножом края сэндвича.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4458,'Яйцо немного взбить с солью и молоком, обмакнуть сэндвич в яичную смесь и подержать его там секунд 30. На сковородке разогреть сливочное масло, обжаривать сэндвич с каждой стороны приблизительно по 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4458,'Переворачивать его необходимо осторожно, двумя лопатками, после слегка придавить, чтобы лучше склеился. Снять горячий сэндвич «Монте-Кристо» на доску, подождать минуту и разрезать на треугольники. Можно подавать и как основное блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4459,'Из кислого молока, яйца, соды, оливкового масла, сахара, соли и муки вымесить тесто. Оно должно выйти не крутое и не липнуть к рукам. Поделить его на 4-5 частей, стол смазать маслом, раскатать круг (25-30 сантиметров). Потом нарезать его на 8 лепестков (сделать ножом надрезы по окружности 2-5 сантиметра).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4459,'Раскатать тесто опять (в процессе работы оно сильно поднимается). Выложить начинку и закрыть ее, накладывая противоположные лепестки один на другой. Серединка должна быть полностью закрыта. Начинка: много зелени (укроп, зеленый лук), мягкий сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4459,'Возможна комбинация из зелени и яйца (на 1 плацинду 1 яйцо). Жарить на сильно разогретой сковородке с толстым дном, налив 0,5 сантиметра масла. Уложить молдавскую плацинду с сыром швом вниз. Прожарить до золотистой корочки. Затем перевернуть и жарить вторую сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4459,'В конце подержать немного под крышкой. На одной порции масла можно жарить, приблизительно, 2-3 плацинды, но нужно следить, чтобы оно не подгорало (будет горчить). Готовую плацинду выложить на блюдо и подать  к чаю или кофе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4460,'Подогреть молоко (30 градусов), положить дрожжи, сахар (1 столовую ложку) и отставить, пока не образуется пенка. Потом добавить остаток сахара, масло, соль, яйца, муку и вымесить тесто. Убрать на 1,5-2 часа в теплое место, для расстойки (тесто увеличится раза в 3).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4497,'Нагреть муку до орехового цвета, развести грибным отваром, отдельно поджарить лук, добавить гвоздику, отварные грибы, потушить 5 минут, соединить с мукой и грибным бульоном, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4460,'Начинка: нарезать помидоры кружочками, перец полукольцами, моцареллу кружками. Семгу почистить от костей и кожи и нарезать полосками, приблизительно 2,5 сантиметра. На противень положить бумагу, раскатать из теста тонкий круг. Отступить от края круга 3,5 см и выложить полоски семги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4460,'Поперчить и посолить. Завернуть края теста внутрь и хорошо залепить – получится валик. Нарезать его кусочками по 4 сантиметра и развернуть все куски рыбой вверх. Оставшуюся рыбу порезать небольшими кусочками и выложить в центр пирога. Сверху уложить перец и помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4460,'Поперчить, посолить, выложить моцареллу. Притрусить зеленью и оставить пирог минут на 30. Затем, отправить пирог с сыром моцарелла и семгой в разогретую духовку минут на 20-25, вынуть, смазать яйцом и вернуть в духовку еще на 10 минут. Готовый пирог достать из духовки, выложить на блюдо и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4461,'Зефир положить в емкость, сбрызнуть соком лимона и отправить на 20 секунд в микроволновку. Он должен расплавиться. Потом добавлять понемногу сахарную пудру (просеять) и аккуратно мешать сначала ложкой, а потом рукой, как тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4461,'Хранить домашнюю мастику из зефира в полиэтиленовом пакете, но стараться, чтобы в нем было как можно меньше воздуха. Мастика должна соприкасаться с пакетом, иначе она обветриться. На ней образуется корочка, и мастика станет не пригодной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4462,'Нарезать грибы пластинками. Лук очистить и измельчить.Поджарить на сковороде шампиньоны вместе с луком. Филе курицы порезать вдоль, на пластины и отбить. Поперчить. Форму смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4462,'Выкладывать слоями: курица, немного майонеза, пластинки картофеля (порезать полукругом), майонез. Дальше грибы и лук, майонез, помидоры, полить сверху майонезом. Присыпать тертым твердым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4462,'Форму для запекания закрыть крышкой и отправить в духовку минут на 40 (200 градусов). Затем крышку снять и оставить еще минут на 10. Подавать куриное филе с грибами по-французски, присыпав зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4463,'Орехи обжарить, чтобы не горчили, измельчить, сварить яйцо вкрутую, остудить и измельчить, все перемешать с готовым пюре, если начинка получится слишком густой, то добавить горячего молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4463,'Раскатать готовое пельменное тесто, вырезать стаканом кружочки, положить фарш и тщательно защипать края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4463,'Отварить пельмени по-татарски с орехами в подсоленной воде, при подаче полить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4464,'Грибы с луком обжарить. Отварить корнеплоды и курицу. Картофель очистить и натереть на терке. Огурцы, морковь и курицу мелко порезать. Выложить слоями: грибы, картофель, огурцы, морковь, курицу, яблоко и измельченные вареные яйца. Все слои смазать майонезом и посолить. Куриный салат с яблоком и грибами присыпать сыром и украсить ломтиками яблока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4465,'Растопить масло с шоколадом и какао на небольшом огне, немного охладить. Добавить яйца, сахар, ванилин и муку. Застелить бумагой разъемную форму. Перелить тесто и отправить на полчаса в духовку (150 градусов). Брауни готов, когда схватиться середина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4465,'Охладить и убрать на 2-3 часа в холодильник. Взбить сливочный сыр с клубничным пюре и растопленным, немного охлажденным, белым шоколадом. С помощью кондитерского мешка красиво отсадить крем на бисквит. Перед подачей торт «Брауни» со сливочным сыром охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4466,'Молодые кабачки или цукини помыть и нарезать слайсами вдоль, при помощи овощечистки. Чеснок пропустить через пресс и смешать с 3 ложками растительного масла. Отставить на 5 минут. Затем, чесночным маслом смазать раскаленную сковороду гриль и выложить слайсы из кабачков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4466,'Обжарить с одной стороны. Готовность кабачков проверить наличием зажаренных полосок от гриля и снять со сковороды. В обжаренные кабачки завернуть по чайной ложке сыра или творога, смешанного с рубленой кинзой. Свернуть рулетики и сверху уложить веточку зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4466,'Куски хлеба обжарить, на сковороде гриль, до зажаренных полосок. На каждый маленький квадратик поджаренного хлеба выложить по одному рулету. Рулеты из цукини с творожным сыром выложить на широкое блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4497,'Уложить биточки в сотейник и залить соусом, тушить до готовности, добавить перед окончанием лавровый лист и перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4467,'Для приготовления сметанного соуса необходимо обжарить лук на растительном масле, до золотистого цвета. Для этого его необходимо почистить и нарезать полукольцами. В жареный лук влить сметану и небольшое количество воды. Тушить 5 минут на очень медленном огне. Затем всыпать мелко порезанную зелень и приправы по вкусу. Домашний сметанный соус должен еще покипеть 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4468,'Для приготовления желе необходимо сметану взбить с сахаром в пышную массу. Сметана должна быть комнатной температуры. Желатин растворить в горячей воде. Нагреть воду до комнатной температуры и ввести в сметану. Затем, еще раз взбить сметану. Чтобы масса не осела, желатин и сметана должны быть одинаковой температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4468,'Очищенный банан порезать колечками или маленьким кубиками. Выложить немного банановой начинки в прозрачные бокалы и залить сметанной массой. Поставить желе на сметане с бананом в холод, до полного застывания. Плитку шоколада натереть на терке и украсить застывшее желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4469,'Для приготовления торта необходимо приготовить творожный крем. Для этого подойдет нежный творог в пачках или несладкая творожная масса. Для однородной консистенции творог протереть через сито или взбить блендером. Сливки из холодильника взбить миксером, с добавлением сахарной пудры, в пышную пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4469,'В творожную массу вливать постепенно сливки, аккуратно перемешивая деревянной лопаткой, чтобы сохранилась пышность. Для приготовления теста на блины необходимо взбить миксером яйца с добавлением сахара. Продолжая взбивать, влить постепенно молоко, затем всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4469,'Взбивать до однородной пышной массы, чтобы разбить все комочки. В тесто добавить соду, гашенную лимонным соком. Плитку шоколада растопить на водяной бане и разбавить небольшим количеством молока. Влить в тесто для блинов. В самом конце в тесто добавить ложку рома или коньяка. В разогретой духовке выпекать блинчики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4469,'Охлажденные блины смазать творожным кремом, складывая блины, друг на друга. Сформировать торт. Поставить торт из блинов с творогом и сливками для пропитки в холодильник, на ночь. Украсить перед подачей тертым шоколадом или взбитыми сливками. Для разнообразия можно украсить свежими фруктами, орехами или цукатами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4470,'Для приготовления пирога необходимо тонко раскатать половину слоеного теста и уложить в форму, закрыв бока формы. Обжарить на растительном масле лук, нарезанный кубиками и добавить к нему фарш. Обжаривать фарш с луком до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4470,'Посолить и поперчить по вкусу. В готовый, горячий мясной фарш добавить сырые яйца и мелко порезанную зелень. Брынзу натереть на терке и всыпать в фарш. Размешать ложкой готовую начинку и выложить в форму с тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4470,'Вторую половину теста раскатать и накрыть пирог, аккуратно защепив края. По всему пирогу сделать проколы вилкой, чтобы выходил горячий воздух. Выпекать мясной пирог на слоеном тесте в духовке, при температуре 180 градусов, 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4471,'Разделать рыбу (лучше использовать леща), посолить, поперчить, слегка обжарить, сварить яйцо вкрутую, мелко порезать, лук нашинковать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4471,'Раскатать из готового дрожжевого теста два пласта толщиной 1 см, выложить на середину одного слой риса, лук, затем рыбу, а сверху яйцо, закрыть вторым пластом, защипать края, накрыть тканью, дать расстояться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4471,'Сделать на поверхности 2-3 насечки ножом и отправить пирог в разогретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4471,'Пирог с рыбой и рисом по-татарски выпекать 30-40 минут на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4472,'Шампиньоны промыть под проточной водой. Опустить грибы в кастрюлю с водой и поставить вариться. Посолить, чтобы вода была немного солоноватая. Варить грибы 20 минут. Затем в кипящую воду положить пряности, травы и приправы. Варить еще 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4472,'За 5 минут до готовности влить уксус. Маринованные пряные шампиньоны уложить в чистую тару с крышкой. Когда рассол остынет, грибы можно кушать. На закуску такие грибы хороши с растительным маслом и зеленым луком. Хранить в холодильнике не больше 30 дней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4497,'Биточки говяжьи по-селянски подаются с гарниром из предварительно поджаренного, а потом тушеного в бульоне с луком, морковью и томатной пастой картофеля.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4473,'Для приготовления блюда очистить картофель и сделать частые надрезы на каждом клубне, не дорезая до конца. Включить духовку, противень смазать растительным маслом. Выложить картофель на противень, посолить и поперчить по вкусу. Натереть мерзлое сливочное масло на терке и посыпать картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4473,'В духовке запекать 30 минут, при температуре 180 градусов. Затем вынуть картофель и посыпать тертым сыром, смешанным с панировочными сухарями. Вернуть противень в духовку и запекать 15 минут, пока сыр не зарумянится. Запеченный с сыром картофель выложить на тарелки и кушать горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4474,'Для приготовления куриных бефстроганов, филе нарезать на тонкие брусочки и полить небольшим количеством лимонного сока. Затем посолить и поперчить по вкусу. Жарить кусочки филе на растительном масле до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4474,'Лук нарезать полукольцами и обжарить на растительном масле, до золотистого цвета. Залить соусом. Для приготовления соуса необходимо 1 ложку муки соединить с водой и хорошо размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4474,'Добавить соль, сметану или сливки и довести до кипения. В лук с соусом добавить куриное мясо и тушить до готовности. Можно добавить любимые приправы для вкуса. Перед готовностью всыпать рубленую зелень. Бефстроганов из мяса курицы подавать с гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4475,'Для приготовления салата необходимо мелко порубить или натереть корень сельдерея, яблоко порезать на небольшие кусочки, зелень порубить. Все смешать и полить йогуртом. Вегетарианский яблочный салат готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4476,'Овощное ассорти готовится слоями. Каждый овощ необходимо помыть, очистить и нарезать. Затем выложить в форму. Первый слой из порезанного кубиком кабачка. Он выделяет сок во время приготовления, поэтому не стоит лить много масла на противень. Посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4476,'Сырую морковь натереть на крупной терке или сделать мелкую нарезку соломкой. Выложить поверх кабачка. Баклажан нарезать кубиком. Посолить и дать стечь жидкости, чтобы убрать горечь из овоща. Выложить баклажаны на морковь, посолить и притрусить молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4476,'Зелень мелко нарезать и присыпать баклажаны. Чеснок пропустить через пресс и выложить на зелень. Томаты обдать кипятком и снять кожуру. Порезать тонкими кольцами и выложить поверх зелени, застелив всю поверхность. Посолить. Полить сметаной или майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4476,'Противень с овощами поставить в разогретую духовку на 15 минут. Затем обильно посыпать тертым сыром овощи и запекать еще 50 минут. Когда сырная корочка станет золотистого цвета, овощное ассорти, запеченное под сыром, достать и угостить вкусным и сытным ужином всю семью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4477,'Перед приготовлением слоек необходимо разморозить тесто. Смешать вишню с сахарным песком. Тесто раскатать в тонкий пласт и порезать на прямоугольники 10х10 см. Каждый квадрат из теста необходимо смазать взбитым яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4477,'На одну сторону теста выложить несколько ягод вишни, присыпать крахмалом, для густой консистенции начинки, и защипнуть край. Противень застелить бумагой для выпечки и выложить слойки. Верх также смазать взбитым яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4477,'Выпекать слойки в духовке, при температуре 180 градусов, 25 минут. Быстрые слойки с вишневой начинкой перед подачей можно присыпать сахарной пудрой. Выложить слойки на блюдо и подать к столу. Приятного чаепития!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4478,'Для приготовления пиццы приготовить дрожжевое тесто. Для этого необходимо смешать дрожжи с сахаром, солью и мукой, затем влить стакан теплой воды. Вымешивая мягкое тесто влить подготовленное оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4478,'Мягкое послушное тесто оставить для подъема на 40-50 минут в теплом месте. По истечении времени тесто обмять и поставить на повторный подъем. Воздушное тесто раскатать по размеру формы тонким пластом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4478,'Учитывать, что оно в духовке еще немного поднимется. Полить томатным соусом по всей поверхности. Твердый сыр натереть на терке и посыпать по всей поверхности пиццы, поверх томатного соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4478,'В процессе приготовления сыр красиво расплавится, и начинка будет в сочном, тянущемся сыре. На сыр выложить королевские креветки, предварительно обжаренные, на сливочном масле, до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8879,'Морковь по-корейски немного нарезать, очистить гранат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4478,'Затем украсить каперсами. Пиццу поставить в разогретую духовку на 10-15 минут. Когда корочка зарумянится, пиццу с моцареллой и креветками можно доставать. Горячее блюдо посыпать свежей зеленью. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4479,'По спинке карасей необходимо сделать небольшие надрезы и посолить. Сковороду раскалить на огне и налить растительное масло. Рыбу обвалять в муке и выкладывать в раскаленное масло, для жарки. Золотистая корочка говорит о готовности карасиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4479,'Обжарив рыбу с двух сторон, ее необходимо выложить на бумажное полотенце, чтобы стек лишний жир. Караси жареные в масле вкусны и с гарниром, и как отдельное блюдо. Правильно приготовленная рыба станет любимым блюдом у каждой хозяйки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4480,'Для приготовления мясного салата отварить куриное мясо до готовности в подсоленной воде. Охладить и нарезать кубиками. Отварить и очистить картофель и яйца. Картофель, яйца и огурцы нарезать одинаковыми по величине кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4480,'Все ингредиенты соединить, добавить лук, нарезанный очень тонкими полукольцами, давленый чеснок, соль, перец и майонез. Аккуратно перемешать салат и выложить в порционную форму. Украсить мясной салат «Ростовский» с курицей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4481,'Сначала необходимо приготовить сметанный соус. Для этого очищенный чеснок пропустить через пресс и соединить со сметаной. Куриные грудки тщательно вымыть, просушить, затем посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4481,'Выложить грудки в форму для запекания и залить сметанно-чесночным соусом. Сыр натереть на крупной терке и щедро посыпать курицу. Поставить противень в разогретую духовку на час, при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4481,'Золотистая сырная корочка – признак готовности блюда. Выложить мясо на блюдо и присыпать зеленью. Куриная грудка в соусе под сыром украсит праздничный стол и восхитит гурманов сочным и ароматным мясом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4482,'Для приготовления кофе латте без кофемашины, необходимо сварить кофе в турке. Для этого, 4 ложки молотого кофе всыпать в турку и залить холодной водой. Варить на сильном огне не мешая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4482,'Когда пенка начнет подниматься, выключить. Можно приготовить растворимый кофе, но вкус будет другим. Молоко подогреть до комнатной температуры. Половину молока взбить в пенку, воспользовавшись блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4482,'Формы для латте наполовину заполнить кофе, затем аккуратно влить молоко и украсить молочной пенкой. Сверху классический кофе латте по-домашнему притрусить молотой корицей или тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4483,'Для приготовления салата необходимо порвать руками свежую зелень, и выложить на широкое блюдо. Яйца отварить и порезать крупными кусками, можно нарезать на четвертинки. Сельдь очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4483,'Нарезать на небольшие кусочки, удалив кости. Лук нашинковать полукольцами и замариновать в растительном масле, с сахаром и уксусом. На листья салата выложить кусочки рыбы, яйца и маринованный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4483,'Приготовить соус из горчицы, оливкового масла и уксуса. Полить соусом салат непосредственно перед подачей. Так сохранится свежесть салата. Салат «Отпад» из сельди солить в зависимости от просола рыбы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4484,'Тушку курицы необходимо тщательно вымыть и просушить. Затем обмазать маринадом и поставить на 6 часов для пропитки. Чтобы курица лучше промариновалась, ее можно поместить в пакет и закрутить края.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4484,'Для приготовления маринада смешать мед, сок лимона, соевый и чили соусы. Обмазав курицу соусом, необходимо раз в час переворачивать тушку, чтобы соус обволакивал все части курочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4484,'Сухофрукты и орехи необходимо не очень мелко измельчить. Можно разрезать на несколько частей. Начинить маринованную курицу сухофруктами и орехами. Зашить нитками все открытые края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4484,'Духовку разогреть до 200 градусов. Противень застелить пергаментной бумагой. Выложить оригинальную курицу в остром маринаде на противень и поставить запекаться на 1,5 часа. Температуру снизить до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4484,'Через 50 минут после выпекания курицу полить гранатовым соком. Оставшееся время курочка будет тушиться в кисло-сладком гранатовом соке. Готовое блюдо выложить на блюдо и снять аккуратно нитки. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Очистить и нарезать овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4485,'Яйца отварить и порезать мелкими кубиками. Крабовые палочки или крабовое мясо нарезать такими же кубиками. Сыр натереть на крупной терке. Заправить майонезом, поперчить, посолить по вкусу. Наполнить тарталетки салатом и украсить веточкой свежей зелени. Тарталетки с крабовым мясом и сыром выложить на блюдо и подать к праздничному столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4486,'Для приготовления морковного бисквита натереть свежую морковь на мелкой терке. Желтки отделить от белков и взбить миксером с частью сахарной пудры. Соединить с морковью. Белки взбить в крепкую пену смешав с оставшейся сахарной пудрой. Вылить пену в морковную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4486,'Аккуратно перемешать деревянной лопаткой. Противень застелить бумагой для выпечки. Вылить жидкое тесто на противень и поставить в разогретую духовку на 15 минут. Золотистая корочка скажет о готовности бисквита. Готовность можно проверить спичкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4486,'Пока выпекается бисквит, взбить сметану с сахаром. Пышный морковный бисквит охладить и смазать кремом. Оставить на пару часов для пропитки. Если пирог получился тонкий, его можно свернуть рулетом, смазав сметанным кремом. Украсить сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4487,'Тесто: просеять муку с разрыхлителем, всыпать сахар. Порезать кубиками охлажденный маргарин, положить в мучную смесь и руками перетереть в крошку. Потом вбить яйцо и вымесить тесто. Полученное гладкое тесто обернуть пленкой и положить в холодильник минут на 30-40.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4487,'Начинка: все компоненты для начинки перемешать и взбить миксером. Если творог крупинками, то массу лучше измельчить блендером. Разъемную форму (диаметром приблизительно 25-35 сантиметров) смазать маслом и притрусить мукой. Тесто достать из холодильника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4487,'Раскатать его пластом, уложить в форму и разровнять. Перелить на тесто начинку и тоже разровнять. Выпекать приблизительно час (160-170 градусов), пока не схватиться творог. Сделать меренгу: взбить белки до устойчивых пиков, с сахарной пудрой. Вынуть из духовки пирог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4487,'Выложить на него белковый слой, разровнять. Сделать разнообразные узоры и выпекать до золотистого цвета (минут 20). Достать Творожный пирог с меренгами из духовки и полностью охладить. На охлажденном пироге появятся карамельные капельки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4488,'Замесить не крутое тесто. Поставить его подходить на полчаса в теплое место. Потом обмять и снова поставить на полчаса, чтобы подошло. Начинка: мак (полстакана) проварить в воде или молоке, добавить 3 столовых ложки сахара. Затем жидкость необходимо очень тщательно отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4488,'Поделить готовое тесто на две части (выйдет два пирога). Если делать один пирог, то он получится очень большой. Раскатать тесто, смазать сливочным маслом. Присыпать сахаром (примерно 3 столовые ложки). Выложить мак и тщательно его разровнять по всей поверхности. Свернуть тесто в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4488,'С обеих сторон обрезать края (подойдут для центральной розы на пироге). Соединить края рулета в кольцо. Сделать надрезы ножницами, с расстоянием через каждый сантиметр. Два лепестка оставить снаружи (их немного раздвинуть), а третий вывернуть к центру. Таким образом уложить весь рулет, по кругу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4488,'С обрезанных краев сформировать розочку: один обрезок положить в центре (его не будет видно), а второй сверху. Поставить в теплое место, чтобы тесто немного подошло. Потом смазать желтком и поставить в духовку на 15-20 минут (170 градусов). Сдобный пирог «Бабушкина салфетка» выпекать до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4489,'Мясо куриное хорошо промыть, высушить и порезать брусочками. Шампиньоны промыть и порезать дольками. Лук репчатый нашинковать кубиками. Отваренный заранее картофель порезать кружочками (0,5 сантиметра толщиной).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4489,'Куриное филе присыпать перцем и солью, обвалять в муке. В сковороде, на растительном масле, поджарить филе до полуготовности со всех сторон. Добавить лук и шампиньоны. Тушить все вместе, пока мясо не приготовится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4489,'Влить часть сливок и вустерский соус. Постоянно помешивать, пока не загустеет. Затем снять сковороду с огня. Гарнир: нарезанный картофель поджарить на масле до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4521,'Пожарить во фритюре, на растительном масле. Выложить готовую «Бюджетную» сырную закуску на бумагу, чтобы стекло лишнее масло. Подать в качестве закуски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4489,'Прибавить к нему перец, остальные сливки и соль. Тушить, пока жидкость не испарится. Поджаренный картофель положить в форму для запекания. Присыпать тертым сыром и поставить в духовку, пока сыр не растает (10-15 минут, 180 градусов).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4489,'Положить на блюдо картофель. Рядом с картофелем выложить куриное фрикасе. Украсить куриное фрикасе с картофелем маринованными огурчиками, помидорами черри и зеленью петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4490,'Разделать подготовленного судака на филе, разрезать на порции, положить в кастрюлю на решетку, добавить порезанные сельдерей, морковь, петрушку, лук, залить холодной водой, приправить лавровым листом, горошками перцев, посолить и отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4490,'Сварить из хребта и плавников наваристый бульон, процедить, смешать с набухшим в воде желатином, порубленным зеленым луком и натертым хреном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4490,'Залить охлажденную рыбу в формочках бульоном, украсить кусочками моркови и веточками петрушки, дать остыть,затем убрать украинское заливное с судаком в холодильник для окончательного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4491,'Поджарить мелко нарезанное кубиками сало и нашинкованный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4491,'Нарезать мясо тонкими полосками, соленые огурцы – кубиками, добавить к луку, приправить томатной пастой, красным перцем и еще 5 минут потушить, перед окончанием добавить натертый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4491,'Смешать мясную зажарку с бульоном, поперчить, посолить, дать закипеть, проварить 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4491,'Солянка «Украинская» подается со сметаной, кусочками лимона, рубленой зеленью и каперсами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4492,'На огонь поставить молоко (200 мл), в оставшемся молоке (50 мл) развести крахмал и добавить желтки. Смешать и вливать в горячее молоко тонкой струйкой (мешать постоянно). Довести крем до кипения, убрать с огня и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4492,'Взбить сливки, сахарную пудру добавить по вкусу. Бананы почистить и порезать на тонкие полоски. Бисквит полить кофе и выложить слоями, чередуя с кремом и бананами, в высокий бокал. Чем больше слоев, тем вкуснее получится английский банановый трайфл.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4493,'Яйца со сметаной взбить и посолить. Смесь перелить на противень с пергаментной бумагой и печь минут 10 (180 градусов). Противень вынуть, корж немного охладить и перевернуть, убрать бумагу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4493,'Сыр натереть на терке, добавить сметану, измельченную зелень и чеснок. Намазать начинкой готовый корж и свернуть рулетом. Нежный рулет из яиц с сыром охладить и нарезать на порционные кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4494,'Картофель отварить и натереть на терке. Смешать с майонезом, посолить и уложить на блюдо – первый слой салата. Крупную луковицу нарезать полукольцами и поджарить (практически без масла) до золотистого оттенка – выложить поверх картофеля. Натереть на терке отваренные яйца, уложить на лук, перемазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4494,'Натереть сыр, уложить на яйца, далее, майонез. Болгарский небольшой перец порезать кубиками, перемешать с майонезом и уложить наверх салата. Сверху простой картофельный салат с сыром присыпать кубиками болгарского перца (без майонеза).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4495,'В отдельной емкости смешать кефир, яйца, соду, соль, растительное масло и разрыхлитель. В другую емкость насыпать муку, добавить кефирную смесь, порезанную фету (кубиками), измельченную петрушку (добавить по желанию). Вымесить мягкое тесто. Готовое тесто поделить на 16-18 частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4495,'Сформировать круглые булочки (размером с мандарин). На противень с пергаментной бумагой уложить сформированные булочки. Обмазать их желтком и притрусить кунжутом. Отправить в духовку на 25-30 минут (180 градусов) и запекать турецкие булочки с сыром фета до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4496,'Залить манку кефиром и отставить минут на 20-30, пока не набухнет. Натереть сыр на терке и перемешать с творогом. Добавить измельченный укроп и яйцо. Тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4496,'По вкусу поперчить и посолить. Можно добавить также и измельченный чеснок (по желанию). Переложить массу в форму и запекать творожно-сырный пирог в духовке, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4497,'Приготовить из мяса фарш, добавить мелко нарезанный репчатый лук, посолить, поперчить, долить воды, хорошо вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4497,'Сделать из фарша биточки, обвалять в муке и с обеих сторон обжарить на жире до коричневатого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4498,'Выложить натертую тыкву в емкость, вбить яйца, всыпать сахар, соду и соль. Влить молоко и оливковое масло. Затем, добавить муку и вымесить тесто (оно должно быть немного гуще, чем на обычные оладьи). Очень тщательно перемешать, чтобы не было комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4498,'Несколько ложек теста (приблизительно 5 ст.л.) перелить в небольшую емкость и добавить какао. Если масса получится очень густой, то ее можно разбавить молоком. Дать тесту постоять минут 10-20, чтобы набухла клейковина в муке. Оно станет более тягучим и удобным в работе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4498,'Сковороду хорошо разогреть, добавить немного масла. Далее добавлять его не требуется, будет достаточно того, что уже есть в тесте. Вылить на нагретую сковороду несколько ложек основного теста. Распределить его равномерно по сковороде и быстро накапать по поверхности коричневым тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4498,'Таким образом, имитируем пятна на коже жирафа. Жарить блин с обеих сторон до золотистой корочки. Складывать блины тыквенные «От жирафа» стопкой, смазывая сливочным маслом. Можно сворачивать треугольниками и подавать с медом, сгущенкой, сбитыми сливками, сметаной или вареньем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4499,'Добела перетереть маргарин и сахар. Сюда же добавить сметану и яйца. Затем постепенно всыпать разрыхлитель и муку. Тесто получается эластичное. По желанию, также в тесто можно добавить ваниль, кардамон или мускат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4499,'Отправить тесто приблизительно на час в холодильник. Затем достать, отделить от теста 1/4 часть и положить ее обратно в холодильник (можно даже ненадолго и в морозилку). Большую часть уложить на противень, разровнять и сформировать бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4499,'Смазать слой теста вареньем или джемом. Вынуть из холодильника оставшееся тесто и натереть на крупной терке. Разложить поверх джема. Печь в духовке около 35-40 минут (180 градусов). Тертый венский пирог с джемом готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4500,'Измельчить орехи в блендере. Взбить с сахаром масло, добавить желтки и опять взбить. Масса получится пышной и густой. Сюда же добавить муку и орехи, тесто получится очень густым (так и нужно по рецепту). Добавить в тесто 2 белка и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4500,'Оставшиеся белки (2 штуки) взбить миксером и также осторожно вмешать в тесто. Из теста выпечь коржи (2 штуки). Пекутся приблизительно 30 минут (180 градусов). Сливочное масло растопить. Положить мед, сгущенку и отправить на 10 минут на плиту (можно на водяную баню, чтобы не пригорело).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4500,'Мешать постоянно. Затем влить сливки, а через 10 минут убрать с огня и охладить. Первый корж смазать кремом, делать это необходимо осторожно, так как он может растекаться. Затем отложить намазанный корж и через 10 минут накрыть вторым коржом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4500,'Так, больше вероятности, что при накрытии коржом крем не вытечет. Глазурь: растопить шоколад, добавить сливки и смазать сверху классический миндальный торт, а также украсить бока. Присыпать по желанию орехами или шоколадной стружкой. Убрать на холод  на пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4501,'Почистить шампиньоны, отварить в подсоленной воде, процедить, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4501,'Нарезать мелкими кубиками лук, яблоки, морковь, добавить зеленый горошек, заправить сметаной, лимонным соком, посолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4501,'Приготовить из порезанных маринованных грибов, корнишонов и остальных ингредиентов соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4501,'Уложить на блюдо листья салата, выложить на них порезанные шампиньоны, сверху — смесь овощей, полить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4501,'Украсить грибной салат с овощами и яблоком под татарским соусом дольками помидоров и половинками оливок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4502,'Измельчить укроп. В йогурт добавить сок лимона, укроп и измельченный чеснок. Все ингредиенты хорошо перемешать. Йогуртовый соус к морепродуктам готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4503,'Для приготовления начинки смешать творог с яйцами, крахмалом и сахаром. Все ингредиенты для теста соединить и вымесить тесто. Отделить от теста 1/3 часть и отправить ее в морозилку. Большую часть теста выложить на противень и равномерно распределить руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4503,'Выложить на него творожную начинку. Достать остаток теста из морозилки и натереть его на крупной терке поверх начинки. Запекать минут 30 (180 градусов). Достать из духовки и порезать его на маленькие прямоугольники. Простое пирожное с творожной начинкой готово. По желанию присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4504,'Все ингредиенты для теста размять, перемешать вилкой, а потом вымесить руками. Прикрыть тесто пленкой и поставить на час в теплое место. Начинка: натереть желтый сыр, моцареллу и брынзу нарезать кубиками, вбить яйцо. Присыпать измельченной зеленью, выдавить чеснок и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4504,'Поделить тесто пополам. Часть раскатать, выложить в форму и сформировать бортики. Уложить начинку, прикрыть вторым пластом теста (раскатанным). Лишнее тесто обрезать, края защипать. Из остатка теста можно сплести косичку и выложить по краю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4504,'Смазать желтком. В центре пирога сделать незначительное отверстие. Поставить ароматный пирог с тремя сырами в духовку минут на 40 (180 градусов). Готовый пирог немного остудить, порционно нарезать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4505,'Мелко порубить шоколад. В сливки добавить ванилин и поставить на водяную баню (огонь средний). Довести сливки до кипения и перелить их в шоколад. Быстро перемешать, чтобы шоколад полностью растаял. Крем охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4505,'Смешать ингредиенты для теста и испечь блинчики. Каждый блин смазать тонким слоем малинового джема и слоем шоколадного крема. Последним слоем торта, обязательно, должен быть не смазанный блин. Верх торта и бока смазать шоколадным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4505,'Крем, что остался, поставить в холодильник. Из остывшего крема сформировать небольшие шарики (трюфели). Обвалять их в какао и выложить на поверхность торта. Весь торт также присыпать какао. Перед подачей, торт из блинов с малиной и шоколадом охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4506,'Порезать соломкой свинину и обжарить ее со всех сторон на масле несколько минут. В сковороду бросить лук, тоненько порезанный. Добавить соленые огурцы, порезанные соломкой. Посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4506,'Разбавить томатную пасту водой и добавить к мясу, вместе с измельченными томатами, петрушкой и чесноком. Довести классическое азу из свинины до кипения, огонь сделать тише, готовить минут 7. Подать к столу с гарниром и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4507,'Порезать свинину или любое мясо на тоненькие кусочки и обжарить на большом огне, на небольшом количестве масла. Порезать картофель дольками и добавить к мясу. Обжаривать еще минут 15, не накрывая крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4507,'Помешивать время от времени. Добавить в сковороду лук и раздавленный или измельченный чеснок. Посыпать перцем и солью. Когда картофель практически приготовится, разложить сверху помидоры, порезанные на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4507,'Чуть-чуть присыпать солью, тертым сыром и закрыть крышкой. Готовить картофель на сковороде по-французски, пока не растает сыр. Выложить картофель на тарелки. Присыпать блюдо зеленью и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4508,'Горький шоколад разломить на кусочки и растопить. Сахарную пудру, яйца, ром и какао соединить и взбить миксером или венчиком. Добавить смесь к растопленному шоколаду и поместить на паровую баню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4508,'Застелить квадратную формочку специальной пищевой пленкой, способствующей скорому остыванию. Смазать дно шоколадом, уложить сверху печенье. Намазать вновь слоем шоколада, затем печенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4508,'Чередовать слои, пока не заполнится формочка. Поставить немецкий десерт «Kalter Hund» в холод минимум на 6 часов. Когда десерт застынет, осторожно достать из формочки и снять пленку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4509,'Говяжий фарш выложить на сковороду и обжарить в небольшом количестве масле, накрыв крышкой. Готовить на среднем огне 60–90 минут. Мелко порезать чеснок и лук, обжарить до золотистого цвета. Снять кожуру с помидор (если это возможно) и порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4509,'Добавить чеснок и лук к фаршу, положить помидоры, посыпать перцем, солью. Обжаривать на сковороде минут 15. Приготовить соус бешамель: растопить сливочное масло, всыпать муку и немного обжарить. Влить молоко, посыпать перцем и солью. Варить пока соус не загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4509,'Готовить, пока масса не загустеет и не станет похожа на жидкую сметану. По желанию можно положить сушеный базилик. Натереть сыр. Заполнить каннеллони остывшим фаршем. Не следует сильно набивать трубочки фаршем, так как они могут лопнуть. Выложить в формочку 1/2 соуса бешамель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4629,'Молоко(1 литр) поставить на огонь и положить в него ванильный сахар, палочку корицы и лимонную цедру. К стакану холодного молока(250 мл) добавить взбитые желтки и кукурузную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4509,'Положить в форму каннеллони. Залить оставшимся  соусом. Соус должен закрывать края, иначе они могут высохнуть. Отправить в духовку. Готовить классические каннеллони под соусом минут 30, соблюдая температуру 180 градусов. Посыпать блюдо сыром и готовить еще минут 15.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4510,'Почистить картофель, порезать на тоненькие ломтики. Нарезать лук на полукольца, грибы на небольшие кубики. Соединить с фаршем и посыпать перцем и солью. Приготовить заправку: соединить сметану и чеснок, пропущенный через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4510,'Вбить яйцо, посыпать перцем, солью, размешать. Смазать формочку маслом, выложить 1/2 картофеля, посыпать перцем, солью, уложить сверху лук. Поверх лука положить фарш с грибами. Присыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4510,'Выложить оставшийся картофель. Посыпать перцем и солью. Вылить на простую, мясную запеканку с грибами заправку. Готовить блюдо минут 60, соблюдая температуру 180 градусов. Посыпать запеканку сыром минут за 5 до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4511,'Грудки посыпать специями и солью, на 10 минут отставить в сторону. Молоко довести до кипения, выключить, незамедлительно положить в него куриное мясо, оно должно быть полностью погружено в горячее молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4511,'Накрыть кастрюлю крышкой, укутать одеялом и отставить на 60 минут. Затем достать грудинки из молока и выложить на дуршлаг, чтобы стекла жидкость. Охладить. Нежное, куриное мясо в молоке порционно порезать и кушать с любимым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4512,'Довести молоко до кипения, охладить его. Взбить желтки и сахар, налить чуть-чуть молока, перелить смесь в оставшееся молоко. Готовить на небольшом огне до загустения, перемешивая. Поставить на 120 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4512,'Взбить сливки, выложить в молоко, не переставая взбивать. Поставить на 3 часа в морозилку, вынуть. Снова взбить, чтобы мороженое на сливках по-домашнему получилось без льдинок, однородным. Спустя 3 часа повторить процесс. Спустя 12 часов домашнее мороженое готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4513,'Растереть в блендере творог и банан. Насыпать муку и замесить тесто. Отправить на 60 минут в холодильник, но можно этого и не делать. Придать массе форму печенья и обвалять в присыпке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4513,'Положить мягкое творожное печенье с бананом на противень, выстеленный специальной бумагой. Готовить минут 12, соблюдая температуру 180 — 190 градусов. Готовое печенье немного остудить и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4514,'Минут 5 отваривать макароны и промыть водой, так их будет легче начинять. Почистить лук, порезать кубиками и обжарить. Почистить морковь, крупно натереть. Мелко нарезать огурцы. Крупно натереть на терке сыр. Соединить фарш, морковь, лук, огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4514,'Посыпать перцем, солью, положить измельченную зелень. Приготовить соус: измельчить в блендере или через мясорубку зелень и чеснок. Добавить майонез, соевый соус, специи, хорошо размешать. Начинить макароны с помощью кулинарного мешочка или просто маленькой ложечкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4514,'Застелить противень пергаментом или фольгой. Намазать сливочным маслом, плотно разложить начиненные макароны. На макароны положить 2/3 сыра. Вылить соус, накрыть фольгой, поместить на 30 минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4514,'Готовить каннеллони под сырной корочкой соблюдая температуру 180-190 градусов. Снять фольгу за 5 минут до готовности, выложить оставшийся сыр и поставить снова в духовку. Подать каннеллони горячими, выложив на блюдо и присыпав по желанию зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4515,'Соединить дрожжи с молоком и перемешать до однородности. Яйца предварительно достать из холодильника, чтобы они нагрелись. Затем взбить и вылить их в кастрюлю. Добавить слегка растаявшее масло (растопить его можно в микроволновке), насыпать ваниль, сахар и влить молочно-дрожжевую смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4515,'Размешать. Отдельно соединить муку и щепотку соли. Всыпать муку в общую кастрюлю. Соединить немного муки с водой и размешивать, пока не образуется клейкая масса. Добавить ее в тесто. Насыпать оставшуюся муку и замесить тесто. Вымешивать пока не перестанет прилипать к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4515,'Накрыть тесто и поместить на 60 минут в тепло. Насыпать на стол муку и раскатать на нем тесто в прямоугольник 40 на 55 сантиметров. Размазать по тесту подтаявшее масло. Приготовить смесь из коричневого сахара и корицы. Равномерно присыпать поверх масла. Скрутить рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Закипятить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4515,'Скатывать его необходимо плотно и ровно, тогда изделие будет похоже на продаваемые «Синнабоны». Чтобы разрезать рулет, можно использовать леску или нитку. В прямоугольную формочку постелить специальную бумагу. Плотно друг к другу выложить булочки. Вместо формы можно использовать противень, застеленный бумагой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4515,'Поместить минут на 20 в духовку и готовить булочки, соблюдая температуру 160 градусов. Приготовить глазурь: соединить ваниль, сахарную пудру, сыр, подтаявшее масло, перемешать до однородности. Смазать горячие готовые булочки  сырной глазурью. Подать булочки «Синнабон» в сырной глазури на завтрак.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Промыть рис, залить водой и довести до кипения. Чуть-чуть убавить огонь и готовить рис, пока не выкипит вода. Накрыть крышкой и минут на 15 оставить на горячей плите. Соединить сахар, уксус и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Сахар лучше предварительно растворить. Равномерно вылить смесь в рис. С помощью деревянной ложки переворачивать рис, чтобы уксус распределился равномерно. Поставить в холод для охлаждения. Приготовить уксусную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Налить воду в широкую емкость. Влить несколько ложек рисового уксуса. В этой жидкости необходимо смачивать ложку, нож и руки, чтобы не прилипал рис. Лист нори разрезать пополам. Положить рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Уплотнить руками, распределяя тоненьким слоем по нори. Перед тем как выложить начинку, при помощи коврика перевернуть рис вниз. Выложить начинку. Крепко скрутить рулетом, помогая ковриком для суши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Чтобы завернуть ролл в рыбу, необходимо порезать ее на тоненькие пластинки. Кусок к куску выложить из рыбы квадрат, положить ролл и завернуть с помощью коврика. Готовый ролл обвалять в кунжуте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4516,'Резать роллы необходимо длинным и очень острым ножом, предварительно смоченным в уксусной воде. Ролл «Филадельфия» с угрем и авокадо подавать с соевым соусом, имбирем и васаби.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4517,'Разогреть до 180 градусов духовку. Подготовить формочку диаметром 24 сантиметра. Обмазать ее маслом. Соединить в емкости муку с солью, разрыхлителем и корицей. В отдельной емкости добела взбить масло и сахар. Вбить туда же яйца, налить молоко и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4517,'Всыпать муку и с помощью лопатки аккуратно смешать тесто. Равномерно распределить в формочке. Порезать клубнику пополам, положить по кругу на тесто, немного придавить. Готовить клубничный итальянский торт в духовке, минут 30. Посыпать остывший торт сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4518,'Почистить бананы, порезать на три части. С помощью трубочки от коктейля осторожно извлечь середину. Низ банана обмакнуть в растопленный шоколад, посыпать дроблеными орешками. Отправить в холодильник, чтобы шоколад застыл.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4518,'Поместить шоколадную пасту в кондитерский шприц, наполнить ею охлажденные бананы. Десерт «Банановое наслаждение» в шоколаде выложить на блюдо и подать к столу. Идеально подойдет для детского праздника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4519,'Залить клюкву кипятком и отставить на 10 минут. Достать ягоды из кипятка и обсушить. Соединить муку, разрыхлитель, клюкву и сахар. С помощью вилки смешать остальные ингредиенты: молоко, сметану, масло и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4519,'Смазать маслом формочки, и выложить в них массу. Готовить маффины с клюквой на сметане, в духовке, примерно минут 20, соблюдая температуру 200 градусов. Выложить выпечку на блюдо, по желанию можно присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4520,'Почистить картофель, порезать на небольшие кусочки и сварить. Натереть морковь, лук измельчить, потушить, добавив растительное масло. Переложить лук с морковью к картофелю. Порезать сыр на кубики и положить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4520,'Перемешивать суп, пока сыр не растворится полностью в кипятке. Посыпать солью. Готовить минут 30. Подавать сырный домашний суп порционно, посыпав измельченной зеленью. В суп по желанию можно добавить креветки, грибы, сладкий перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4521,'Для приготовления теста налить в емкость холодное молоко, влить теплую воду, посолить и ввести гашеную соду. Медленно всыпать муку. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4521,'Добавить в тесто мелко натертый сыр. Вымесить. Чтобы палочки были мягкими и эластичными, отставить тесто некоторое время. Раскатать тесто и порезать на палочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Из теста раскатать два тоненьких пласта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4522,'В сотейнике перемешать все ингредиенты для маринада, подогреть до закипания, снять с плиты. Перелить маринад в чашу блендера, превратить в пюре, дать остыть. Кусок мяса присолить, поперчить со всех сторон, убрать в пакет. Залить охлажденным маринадом, крепко его завязать и отправить ночевать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4522,'Достать мясо, дать  постоять при комнатной температуре минут 40 в маринаде, затем кусок тщательно обсушить бумажными полотенцами, при желании можно еще чуть поперчить и присолить. Для панировки муку растереть со сливочным маслом до получения мелкой крошки, обмазать мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4522,'Филе с каждой стороны быстро обжарить в растопленном сливочном масле до коричневатой корочки. Прогреть до 200 градусов духовку, снизить нагрев до 160 градусов, переложить мясо в форму для запекания и поставить на пару часов в духовку. Порезать сыр на кубики 2х2 см, завернуть в ломтики бекона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4522,'Обмакнуть в кукурузную муку, а затем в яйцо и опять в муку. Насадить по три кусочка сыра на шпажки, обжарить до соломенно-золотистого цвета в сильно разогретом масле. Вынуть мясо из духовки, переложить на блюдо, прикрыть фольгой и дать постоять четверть часа. К жаркому в пивном маринаде и сырным шашлычкам подать дижонскую горчицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4523,'Замесить тесто и отставить, чтобы подошло. Соус: смешать сметану, майонез и соус краснодарский в равных количествах. Начинка: порезать кружочками оливки. Соломкой нарезать перец болгарский, полукругом помидоры, тонкими кружками колбасу. Натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4523,'Тонко раскатать тесто по диаметру противня, в котором пицца будет запекаться, и выложить соус по всему диаметру. На него положить начинку. Присыпать сверху сыром и зеленью. Отправить домашнюю пиццу с колбасой и оливками в духовку на 15-20 минут (200 градусов). Готовую пиццу нарезать кусочками и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4524,'В кастрюльке сварить куриный бульон. Мелко измельчить лук и поджарить его на сковородке. Раздавить чеснок, положить к луку и жарить на сковородке еще минут 5. Затем добавить измельченные лисички и влить белое вино (30 миллилитров).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4524,'Тушить, пока вся жидкость не выпарится. Убрать со сковородки лук с грибами. В этой же сковороде обжарить рис (минуты 3). Осторожно влить бульон, добавлять его необходимо порциями, постоянно мешая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4524,'Жидкости в итоге не должно остаться в сковородке – рис все впитает. Добавить к рису лисички, влить оставшееся белое вино и сливки. Все хорошо перемешать, посолить. Ризотто с лисичками в сливках можно подавать на стол и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4525,'Перетереть яйца с дрожжами и сахаром. Молоко нагреть, влить к яйцам и слегка взбить. Добавить соду, соль, масло и муку, хорошо перемешать. Тесто вылить в форму (смазать маслом) и отставить на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4525,'Поместить в разогретую духовку. Запечь. Охладить и притрусить сахарной пудрой или украсить по собственному желанию. Нарезать простой пирог «Пушистик» на порционные кусочки и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4526,'Взбить до однородной массы в блендере замороженный банан, арахисовое масло и какао. Готовую смесь переложить в формы для мороженого, положить палочку и заморозить до твердого состояния (часа 4).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4526,'Кусочки шоколада растопить с молоком в микроволновке (приблизительно минуту), перемешать и снова поставить в микроволновку (секунд 30). Опять перемешать, чтобы масса стала однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4526,'Достать из морозилки брикеты мороженого и окунуть их в шоколадную массу. Выложить банановый пломбир в шоколаде на бумагу или обратно в формочку для мороженого, чтобы шоколад застыл. Хранить мороженное в морозилке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4527,'Смешать креветки с сушеными травами и паприкой, отставить. Выложить нарезанный бекон на сковороду и поджарить до золотистой корочки (на небольшом огне). Отделить от бекона сало. Бекон вынуть из сковородки, а сало оставить. Положить на сковороду креветки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4527,'С одной стороны обжарить их, примерно минуты 2, перевернуть и обжарить с другой стороны еще секунд 30. Выложить креветки на тарелку, прикрыть и отставить в сторону. В ту же сковородку, где жарились креветки, положить измельченный лук. Обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4854,'Стейки семги промыть, обсушить салфеткой, обмазать оливковым маслом, обсыпать солью и кориандром, намазать медом и поставить мариноваться в холодильник на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4527,'Сюда же добавить чеснок, тушить секунд 30 и перемешать. Добавить в сковородку нарезанные помидоры и 1/4 стакана воды. Приправить перцем и солью. Тушить на небольшом огне под крышкой. Отдельно вскипятить 3 стакана воды и сварить рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4527,'Когда рис будет готов, добавить сливочное масло и перемешать. К соусу, что тушиться на сковороде, добавить острый соус и тоже перемешать. Крупу выложить на порционные тарелки, полить соусом и сверху выложить несколько креветок. Подавать жареные креветки с соусом, присыпав зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4528,'Порезать грибы пластинками. Очистить и измельчить лук. Обжарить на сковородке, охладить. Куриную копченую грудку и огурец порезать тонкой соломкой, измельчить зелень. Яйца отварить, очистить и натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4528,'Выкладывать слоями в салатницу: курица, огурец, лук с грибами, зелень и яйца. Немного промазать слои заправкой (майонез или сметана), посолить и поперчить. Выложить легкий куриный салат с грибами на блюдо и подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4529,'Мясо промыть и промокнуть бумажным полотенцем. Нарезать свинину кубиками и поджарить в сковородке или в сотейнике с высокими бортиками и толстым дном, на разогретом масле, до золотистой корочки. Лук очистить и нашинковать. Морковь натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4529,'Когда мясо поджарится, отправить к нему морковь и лук. Тушить 5-10 минут. Картофель нарезать кубиками. Положить картофель к мясу и налить воды так, чтобы она не до конца покрыла картофель. Посолить, поперчить. Когда закипит вода, огонь уменьшить и тушить под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4529,'Минут через 15 положить специи (сушеную петрушку, базилик, барбарис или любые другие по желанию и вкусу). Тушить, до готовности картофеля, вода при этом не должна полностью выпариться. Когда картофель будет готов, убрать с огня и отставить минут на 15. Свиное жаркое с картофелем готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Нарезать картофель и лук небольшими кусочками. Поставить кастрюлю, в которой все будет готовиться, на огонь и налить на дно масла (кастрюля должна быть с толстым дном). Можно использовать сливочное масло – будет вкуснее. Когда масло нагреется, положить туда лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Обжарить его до слегка золотистого оттенка. Когда лук обжариться, залить его водой (стакан) и дать ей закипеть. Положить в воду картофель, добавить воды, но чтобы она только покрыла картошку (стакана 2). Посолить, накрыть крышкой и варить на небольшом огне минут 15.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Нарезать курицу, если филе, то порезать кусочками приблизительно эквивалентными кусочкам картошки. Если другие части курицы (с костями), то порезать, как получится, но чтобы приблизительно куски были одинаковыми. Нарезать грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Положить курицу в кастрюлю. Если вода не покрывает содержимое, то можно немного долить (не больше, чем полстакана), но не желательно, лучше попытаться поместить курицу глубже. Накрыть крышкой и варить 15 минут. По истечении времени положить в воду брокколи и грибы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Залить сливками. Накрыть крышкой и оставить на 10 минут. Загуститель: в стакан положить крахмал (3 столовые ложки), влить полстакана воды и размешать. Затем влить в кастрюлю тонкой струйкой загуститель, постоянно помешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4530,'Добавить соль и разнообразные приправы (по вкусу), помешать. Накрыть крышкой и как только начнет кипеть, убрать с плиты. Картофель с курицей под сливками разложить по тарелкам и можно подавать на стол. Приятного аппетита.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4531,'Яйца с сахаром взбить до белой пены. Добавить какао, просеянную муку, осторожно смешать. Перелить тесто в форму и отправить в духовку (до сухой спички). Крем: взбить с маслом сгущенку. Какао перемешать с растительным маслом и смешать со сгущенкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4531,'Крем получается гладкий блестящий, имеет запах шоколада и вареной сгущенки. Когда бисквит испечется – вынуть из духовки и охладить. Если время не поджимает, то можно его оставить на ночь под полотенцем. Разрезать бисквит на 3 коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4531,'Сироп: смешать и вскипятить сахар, коньяк и воду. Каждый корж пропитать сиропом и смазать кремом. Обмазать также верх и бока. Украсить торт по собственному желанию. Убрать нежный торт с шоколадным кремом в холодильник и вынуть за час до подачи. Подавать к столу на сервировочном блюде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Положить один пласт, побрызгать водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4532,'Отделить мятные листья от стеблей и хорошо промыть, высушить. В кастрюлю налить сливки и молоко. Добавить к ним сахар (70 грамм) и мяту. Нагреть на медленном огне, не доводя до кипения (приблизительно 90 градусов). Убрать кастрюлю с огня и настоять не менее часа (сливки впитают в себя аромат и вкус мяты).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4532,'Процедить через сито сливки. Мяту хорошо отжать, можно руками, тогда в сливки попадет больше мятного аромата. Сливки снова перелить в кастрюлю и нагревать (до 90 градусов), не доводить до кипения. Желтки переложить в большую емкость, добавить оставшийся сахар и взбить добела, миксером или блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4532,'Тонкой струйкой влить к ним горячие сливки, постоянно мешая. Смесь перелить в кастрюлю и нагревать на медленном огне, помешивая, пока они не начнут густеть. Нельзя смесь доводить до кипения. Если окунуть в смесь ложку, то готовый крем будет густым слоем ее обволакивать',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4532,'Крем убрать с огня (можно процедить сквозь сито), поставить на холодную водяную баню, чтобы остыл. Если мороженое готовится в мороженице, то необходимо воспользоваться инструкцией по приготовлению мороженого. Крем, постоянно перемешиваемый и охлаждающийся, превратится в загустевшее, нежное мороженое.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4532,'Готовый мятный пломбир с шоколадом подавать, присыпав тертым шоколадом. А можно положить его в контейнер (также присыпать тертым шоколадом), закрыть и поставить в морозилку. Приблизительно за 20 минут до подачи, вынуть мороженое из морозилки и поставить в холодильник, чтобы оно немного размягчилось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4533,'Тесто можно приготовить с помощью миксера – налить в чашу теплое молоко и растворить в нем дрожжи. Отставить их минут на 10. Затем добавить муку и соль. Перемешивать 5 минут на маленькой скорости. Закрыть пленкой тесто и поставить в теплое место, чтобы поднялось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4533,'Через 20 минут тесто обмять и отставить еще минут на 20. Готовое тесто поделить на 16 одинаковых частей. Из каждого куска сформировать жгутик (30-35 сантиметров) и скрутить баранку или крендель. Сделать содовый раствор: вскипятить 1 литр воды с 1 чайной ложкой соды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4533,'Опустить каждый крендель в кипящий раствор на 20-30 секунд и сразу же выложить на противень. Присыпать кунжутом. Прикрыть крендели на противне полотенцем и оставить на полчаса. Выпекать немецкие крендели «Брецели» на верхней решетке, в духовке, минут 15-20 (220 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4534,'Охлажденное масло и муку порубить ножом. Добавить разрыхлитель, сахарную пудру, вбить яйцо и замесить тесто. Поделить тесто на две разные части (большая будет для изготовления бортиков, а меньшая для дна). Тесто раскатать, выложить в форму. Сформировать дно и бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4534,'Поставить тесто в холод. Начинка: отделить желтки от белков и растереть их добела с сахарной пудрой и ванильным сахаром (можно миксером). Затем добавить творог (перетереть через сито или взбить блендером), крахмал. Перемешать. Яичные белки взбить до устойчивых пиков и частями ввести в творожную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4534,'Аккуратно перемешать снизу вверх. Форму с тестом достать из холодильника и выложить начинку. Выпекать кезекухен с творогом минут 65-75 (температура 180 градусов). Первые 40 минут духовку открывать нельзя. После запекания дать пирогу полностью остыть и затем вынуть из формы. Готовый пирог подать на стол порционно нарезав.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4535,'Куриные крылышки необходимо хорошо вымыть прохладной водой, высушить бумажным полотенцем и сложить в большую миску. Картофель очистить, крупные клубни разрезать на четверть или половинки, мелкие – оставить целыми. Сложить картофель к крылышкам. Посолить и присыпать приправой карри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4535,'Для соуса необходимо смешать майонез, горчицу, соевый соус и давленый чеснок. Этим соусом залить крылья и картофель и оставить мариноваться на 3 часа. Если мариноваться дольше, то миску лучше поставить на холод. Противень для запекания смазать растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4535,'Выложить куриные крылышки с картофелем, сверху полить соусом. Запекать в духовке 40 минут, при температуре 200 градусов. Золотистые куриные крылья с картофелем подавать горячим. К блюду подойдут сметанный или томатный соусы, также не забывайте про свежую зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4861,'Нарезать мелкими кубиками шпик, обжарить и выложить на дно керамического горшочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4536,'У мушмулы очень мягкая мякоть, но твердая кожура, которую необходимо срезать, а косточку удалить. Для приготовления джема, мякоть порезать на небольшие кусочки и сложить в миску. А в варенье наоборот, фрукт будет красиво смотреться крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4536,'Соответственно лучше оставить половинки мушмулы целыми. Фрукты залить сиропом. Для приготовления сиропа, сахар растворить в теплой воде и довести до кипения. Затем прокипятить сироп в течение 2-3 минут и выложить в него фрукты. При варке варенья, лучше постоянно помешивать фрукты, чтобы не пригорал сироп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4536,'И джем, и варенье варить на очень маленьком огне, пока не будет достигнута нужная консистенция. Готовое джем и варенье из мушмулы можно кушать сразу, а можно закатать в стерильные банки на зиму и накрыть до полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4537,'В рецепт венгерского лечо входят традиционные томаты, сладкий перец, лук. С томатов необходимо снять кожицу. Для этого их надрезать крестом и обдать кипятком. Через 2 минуты можно легко снять жесткую кожуру, а мякоть порезать кусочками, удалив семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4537,'Сладкий перец помыть, удалить сердцевину и порезать на небольшие полоски или квадратики. Очищенный лук порезать полукольцами и обжарить на растительном масле (смальце). Жарить на большом огне, чтобы лук быстро зажарился, в это время всыпать перец и добавить ложку томатной пасты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4537,'Тушить до мягкости перца. Затем высыпать томат и тушить 20 минут на очень медленном огне. Посолить и поперчить. Если хозяйка предпочитает сытное лечо, тогда можно всыпать пол стакана риса и тушить его с овощами. За 10 минут до выключения всыпать нарезанную зелень и давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4537,'Тушить до готовности. Консистенцию контролировать добавлением томатного сока или наоборот его выпариванием. Перед выключением всыпать в лечо порезанную копченую колбаску или сосиски. Лечо по-венгерски с копченой колбасой довести до готовности и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4538,'Для приготовления салата «Алекс» необходимо отварить куриное филе или грудку, а грибы пожарить с луком на растительном масле. В салат натереть сыр, с необычными вкусовыми добавками, например с приправами или тмином. Чеснок пропустить через пресс и добавить в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4538,'Оливки разрезать на половинки и добавить в миску с салатом. Помидоры порезать на кубики или дольки, добавить их в последнюю очередь, чтобы они не успели пустить сок. В салат «Алекс» с куриной грудкой добавить майонез и хорошо перемешать. Украсить оливками или свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4539,'Для приготовления салата «Сосновый бор» отварить картофель в кожуре. Затем очистить и порезать на небольшие кубики. Мясо отварить до готовности и нарезать кубиками, как и картофель. Жирные куски мяса лучше не использовать, чтобы не испортить нежный вкус салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4539,'Маринованные грибы добавить в салат крупными кусочками, а лук очистить и мелко порезать. Соединить все ингредиенты и заправить майонезом. Посолить и поперчить по вкусу. Выложить мясной салат «Сосновый бор» на блюдо, присыпать измельченной зеленью и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4540,'Для приготовления грушевого пирога необходимо правильно сделать дрожжевое тесто. Для этого необходимо развести в теплом молоке дрожжи, дать постоять 10 минут. Затем добавить ванилин, соль и взбитые яйца с сахаром. Муку просеять и добавлять по немного в тесто. Вымешивать тесто 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4540,'Мягкое масло добавить в тесто и вымешивать еще пару минут. Затем сложить в миску, накрыть пищевой пленкой и оставить в теплом месте для поднятия. Груши очистить от кожуры, порезать на тонкие дольки и полить небольшим количеством лимонного сока, чтобы не потемнели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4540,'Жидковатое тесто примять лопаткой. Форму для пирога застелить пергаментной бумагой и смазать растительным маслом. Выложить тесто, разровнять лопаткой или ложкой, смазанной растительным маслом. По поверхности выложить дольки груш так, чтобы до края оставалось не меньше 1 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4540,'Чем больше будет грушевых долек в тесте, тем сочнее получится пирог. Накрыть форму пленкой. Оставить на 30 минут для поднятия теста. Выпекать Пышный пирог с грушами 40 минут при температуре 180 градусов. Готовность проверить спичкой. Пирог с золотистой корочкой посыпать сахарной пудрой и коричневым сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4541,'Для приготовления домашней «Нутеллы» необходимо растопить шоколад и сливочное масло на водяной бане. Затем в эту массу влить сгущенное молоко и какао-порошок. Смесь варить на водяной бане примерно 10 минут. Затем в массу всыпать орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4541,'Чтобы орешки хрустели в шоколадной массе, их необходимо немного обжарить на сковородке. Перемешать домашнюю «Нутеллу» на горьком шоколаде с орехами, сложить в лоток и поставить в холодильник. Теперь можно наслаждаться витаминным и энергетическим продуктом, к тому же очень вкусным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4542,'Тесто на московские плюшки готовится дрожжевое. Необходимо растворить в теплом молоке дрожжи. Затем взбить яйца, сахар, соль и добавить в молоко. Муку обязательно просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4542,'Всыпать в тесто муку, вымешивая мягкое тесто. Тесто разделить на небольшие шарики, а затем раскатать в пласт. Присыпать сахаром и скатать в рулет. Края рулета защепить, ножом сделать надрез и вывернуть плюшку наизнанку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4542,'Так получается стандартная форма сердечка. Противень застелить бумагой для выпечки и выложить на нее плюшки. Дать постоять 1,5 часа, чтобы они увеличились в размере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4542,'Выпекать Пышные «Московские» плюшки примерно 25 минут. Румяные плюшки выложить на блюдо и немного подождать до полного остывания, наслаждаясь ароматом свежей выпечки. Подать на завтрак с любимым напитком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4543,'Для приготовления майонеза лучше использовать домашние яйца, так как их оранжевые желтки придадут соусу приятный аппетитный цвет. Желтки отделить от белка и взбить миксером в миске с сахаром, солью и горчицей. В эту массу необходимо влить масло маленькими порциями, продолжая взбивать миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4543,'Густая масса получается ярко желтой и блестящей. Затем, не переставая взбивать, добавлять по ложке уксус, смешанный с водой. Во время взбивания, майонез начнет светлеть. Продолжить вливание уксуса с водой до достижения нужной консистенции майонеза. Домашний майонез на желтках готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4544,'Для маринования баклажаны следует порезать на кружки и оставить на час в соленой воде. Так они уберут свою природную горечь и станут более мягкими. Затем вынуть их из рассола, дать стечь и обсушить на бумажном полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4544,'Затем обжарить их на сковороде, в небольшом количестве масла. Не стоит добиваться зажаренной корочки. Чтобы удалить лишний жир, выложить жареные баклажаны на бумажное полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4544,'Сладкий перец очистить от семян и разрезать на несколько частей. Затем запечь в духовке до мягкости, в течение 50 минут. С горячих перцев снять кожицу и порезать мякоть на кубики. К ним выдавить чеснок и добавить нарезанную зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4544,'В посуду выложить слой баклажан, слой перцев с зеленью, затем слои повторить. Залить овощи маринадом из воды, соли и уксуса. Баклажаны маринуются сутки в холодильнике. Затем можно угощать знакомых вкусными сочными баклажанами «Мозаика» в яблочном уксусе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4545,'Для приготовления крема со вкусом пломбира, необходимо брать масло и сметану хорошего качества, желательно домашнего приготовления, так как в них высокая жирность. Масло взбить в пышную массу миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4545,'Сметану соединить с взбитыми яйцами, цедрой лимона, сахаром, ванилью и мукой. Массу поставить на водяную баню и варить, пока не загустеет. Следует постоянно помешивать. Остывшую массу ввести во взбитое масло, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4545,'Поместить крем в чистую тару и поставить в холодильник. Нежный крем со вкусом пломбира прекрасно подойдет для украшения тортов или на десерт детям. Если подать такой крем с малиновым вареньем можно покорить любого сладкоежку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4546,'Открыть банки с кукурузой и фасолью. Слить жидкость. В салатницу выложить половину каждой банки. Свежий огурец и вареную колбасу нарезать на мелкие кубики и добавить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4546,'Чтобы салат имел аромат копченостей, можно использовать копченую колбасу. Сыр натереть на крупной терке или порезать очень мелким кубиком. Зеленый лук покрошить, чеснок пропустить через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4546,'Смешать все ингредиенты, посолить и поперчить по вкусу. Добавить майонез. Салат тщательно размешать и выложить красивой горкой на блюдо. Перед подачей на стол, посыпать сухариками. Салат «Вкусный» с сухариками можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4547,'Чтобы приготовить курицу, необходимо тушку птицы тщательно помыть и аккуратно отделить мясо от кожи, не повреждая внешний вид курицы. Для этого, очень острым ножом, провести по всей тушке между кожей и мясом, крылышки и ножки не трогать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4547,'Апельсины помыть и нарезать на половинки кружочков. Если срезать кожуру, тогда потеряется явный апельсиновый аромат. Это рекомендуется сделать тем, кто предпочитает избавиться от насыщенного аромата цитруса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4547,'Курицу посолить и натереть молотым черным перцем. Затем под кожу вложить дольки апельсина, сколько влезет по всей длине тушки. Обязательно совершить процедуру по спинке. Очищенный чеснок вложить в середину, затем вложить апельсины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4547,'Ножки тушки необходимо связать ниткой, чтобы зафиксировать начинку. Курицу положить на противень, оставшиеся дольки апельсина разложить вокруг тушки. Поставить в духовку запекаться на 2 часа при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4547,'Во время приготовления блюда необходимо 3-4 раза поливать курицу образовавшимся в противне соком. Чем чаще поливать, тем сочнее будет курица в результате. Готовую румяную курицу достать из духовки и нарезать на порционные кусочки, апельсины выкинуть. Ароматную курицу, запеченную с апельсинами подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4548,'Для приготовления картошки по-итальянски мелкий картофель тщательно промыть и высушить. Срезать кожуру нет необходимости, в кожуре картофель получается с хрустящей корочкой, а мякоть более сочной. Травы и пряности необходимо сначала смешать в тарелке, добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4548,'Чеснок очистить и пропустить через пресс. Лук очистить от кожуры и очень мелко нарезать. Картофель посыпать давленым чесноком и луком. Тщательно перемешать. Затем посыпать специями и еще раз перемешать, чтобы каждая картошка была в специях. Выложить картофель на противень, смазанный растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4548,'Разложить по всему противню. Полить картофель оливковым маслом и поставить в духовку на 25-30 минут. Противень установить на середине духовки, чтобы пряный картофель по-итальянски хорошо пропекся со всех сторон. Румяный картофель с хрустящей корочкой подавать горячим. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4549,'Отварить куриное филе в подсоленной воде с лавровым листом. Остудить и мелко порезать. Натереть твердый сыр, порезать и обжарить на сливочном масле свежие шампиньоны. Порубить очищенные грецкие орехи и чеснок. Смешать все ингредиенты, соль – по вкусу. Заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4550,'Мелко нарезать свежие помидоры и соленый огурец. Порвать руками зеленый салат, порубить кинзу, все смешать и заправить оливковым маслом. Намазать плавленым сыром тонкий лаваш, выложить получившуюся начинку, завернуть рулетом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4550,'Обжарить овощной рулет на сковороде, на растительном масле. Поворачивать во время приготовления для обжарки обеих сторон. При подаче хрустящий рулет из армянского лаваша нарезать толстыми косыми кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4551,'Замочить горсть изюма и курагу в теплой воде с добавлением коньяка. Отдельно замочить желатин в холодной кипяченой воде. Очистить от кожуры и нарезать тонкими кружочками апельсин и мандарин. Они должны быть ровными, одинаковой толщины. На дно прозрачной салатницы выложить кружок апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4551,'Вокруг расположить половинки апельсиновых и мандариновых кружков. Выкладывать очень плотно друг к другу. Для приготовления начинки размять творог, можно протереть его через сито. Добавить сахарный песок, немного густой сметаны и набухший изюм. Желатин прогреть на водяной бане.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4551,'Большую часть желатина (две трети) добавить в творог. Столовой ложкой выложить массу на апельсины и мандарины, делать это надо осторожно, чтобы не сдвинуть кружочки. Смешать сметану, сироп вишневый (можно из черной или красной смородины), курагу нарезанную кусочками, подготовленную тертую цедру апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4551,'Влить оставшуюся треть желатина, перемешать, выложить сметанную массу на творожный слой. Поставить торт в холод на несколько часов. При подаче, творожный цитрусовый торт с курагой перевернуть на блюдо, чтобы цитрусовые оказались сверху. Украсить по вашему желанию и подать к праздничному столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6572,'Растереть творог, добавить сахар или мед, изюм, измельченные орехи, заправить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4552,'Для начала необходимо приготовить заварной соус бешамель. Для этого растопить (не кипятить) маргарин или сливочное масло. Всыпать ложку муки, непрерывно помешивая масло. Когда начнет закипать, влить тонкой струйкой молоко. Посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4552,'Помешивая, довести соус до кипения. Когда бешамель начнет густеть, значит, пора выключать. Филе рыбы порезать на порционные куски, посолить и поперчить по вкусу. Сковороду раскалить и налить немного растительного масла. Рыбу обвалять в муке и обжарить до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4552,'На разогретый противень с высокими бортами, выложить слой вареного картофеля, нарезанного на кружочки. Затем выложить рыбу и полить ее соусом бешамель. Посыпать все тертым сыром и поставить в духовку на 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4552,'Когда появится золотистая корочка, блюдо можно доставать из духовки. Нежная рыба под соусом бешамель готова. Так как в блюде присутствует растопленный сыр, кушать блюдо вкуснее горячим. Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4553,'В этот салат идеально подойдет красная фасоль в собственном соку. Банку с фасолью открыть и слить жидкость, фасоль высыпать в миску. Ветчину и маринованный огурец порезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4553,'Яйца отварить и натереть на крупной терке, но можно порезать очень тонкой соломкой. Чем мельче порезаны яйца, тем нежнее получится салат. Все ингредиенты смешать в миске, посолить и поперчить по вкусу. Выдавить чеснок, добавить к блюду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4553,'Зеленый лук мелко покрошить и высыпать в салат. Добавить майонез. Перед подачей на стол простой салат из фасоли с ветчиной перемешать и выложить на блюдо. Посыпать хрустящими сухариками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4554,'Яблоки средней величины очистить от кожуры и семян, натереть на крупной терке. Яйца взбить с сахаром и вылить к яблокам, размешать ложкой. Добавить ванильный сахар и щепотку соли. Всыпать муку и вымесить тесто ложкой. Тесто приобретет консистенцию густой сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4554,'Сковороду раскалить и смазать растительным маслом. Ложкой накладывать на сковороду оригинальные яблочные оладьи и жарить до румяной корочки. Если получились слишком жирные оладьи, то можно избавиться от лишнего жира, выложив их на бумажное полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4555,'Для приготовления творожной начинки взбить блендером творог, сахарную пудру и сметану. Затем добавить мягкое сливочное масло и кокосовую стружку. Взбивать еще 3-4 минуты и поставить массу в холодильник. Основой для рулета идет бисквитное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4555,'Для его приготовления необходимо взбить яйца с сахаром в крутую пену, добавить соль. Просеянную муку размешать с какао-порошком и разрыхлителем. Добавить по не многу в тесто муку и вымесить аккуратно деревянной лопаткой, чтобы не опустилась яичная пена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4555,'Противень застелить пергаментной бумагой, выложить жидкое тесто и поставить в разогретую духовку на 15-20 минут. Сильно пересушивать бисквит не стоит, иначе он не свернется. Горячий бисквит вынуть из противня, свернуть тугим рулетом и отставить остывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4555,'Когда остынет, рулет развернуть и нанести толстым слоем творожную начинку. Затем свернуть рулет и отставить напитываться, на 1 час. Бисквитный рулет с кокосовой начинкой готов, приглашайте друзей к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4556,'В глубокую миску высыпать кукурузу из банки, слив предварительно жидкость. Пекинскую капусту нашинковать, яблоко очистить от кожуры и семян. Натереть его на крупной терке и добавить к капусте. Яблоко лучше взять с небольшой кислинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4556,'Выдавить сок лимона и полить ингредиенты. Посолить и поперчить салат. Хорошо перемешать и выложить в глубокую салатницу. Чем дольше стоит легкий овощной салат с яблоком, тем больше полезного сока останется на тарелке, поэтому есть витаминное блюдо, стоит сразу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4557,'Кабачки вымыть, нарезать вдоль полосками по полсантиметра толщиной, ровными и одинаковыми. Застелить противень бумагой для выпечки, выложить кабачки, сбрызнуть оливковым маслом, соль – по вкусу. Печь при 180 градусах в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4557,'Нарезать тонкими полосками куриное филе, посолить, поперчить, немного отбить. Добавить рубленый чеснок, оставить на полчаса. На размягченные кабачки выложить куриное мясо и посыпать сверху тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Влить сливки, посолить по вкусу и поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4557,'Присыпать свежим рубленым базиликом, добавить немного готового соуса из паприки (он не должен быть острым). Скрутить рулетики, сколоть шпажками, печь 25 минут при температуре 180 градусов. Кабачковые рулетики с сыром и курицей подать в качестве закуски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4558,'Взбить яйца сахаром и солью, добавить молоко, снова взбить. Порциями всыпать просеянную муку. Взбивать до тех пор, пока не получится однородное тесто. Добавить сливочное растопленное масло и немного водки, перемешать. Тесто поставить на час в теплое место без сквозняков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4558,'Выпечь на сливочном масле тонкие блины большого диаметра. Жарить с обеих сторон на сковороде с тефлоновым покрытием. Приготовить начинку: очистить и разрезать на части спелые яблоки, удалить сердцевину, уложить плоды в сотейник. Влить полстакана воды, тушить 10 минут под крышкой при средней температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4558,'Добавить сахар, сметану, молотую корицу, перемешать и тушить без крышки 4 минуты, огонь прибавить. Снять с огня, остудить. Для выпечки понадобится прямоугольная форма. Выстелить ее пищевой пленкой, уложить на дно 2 блина, их края должны свешиваться наружу, на бортики формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4558,'Укладывать остальные блины, по одному или по два, всё зависит т высоты формы, прослаивая начинкой. Верхний блин накрыть свисающими блинами из первого слоя, завернуть пленку, положить гнет.  Оставить в холодильнике на ночь. Готовый пирог из блинов с яблоками и корицей, подать к столу порционно нарезав.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4559,'В теплом молоке растворить прессованные дрожжи, добавить полкило муки, размешать, поставить посуду с тестом в таз с теплой водой. Когда опара поднимется – добавить соль, взбитые с сахарным песком и ванилином яичные желтки. Вмесить растопленное сливочное масло, взбитые отдельно, в пену, белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4559,'Затем всыпать еще столько же муки, в результате тесто должно получиться средней густоты. Снова поставить посуду в таз с теплой водой. Когда тесто увеличится в два раза – добавить распаренный изюм, разложить в формы, они не должны быть наполнены доверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4559,'Поставить в тепло, накрыть тканью. Перед выпечкой смазать яйцом, печь при 175 градусах в течение 40 – 50 минут. Готовые куличи покрыть глазурью из растопленного шоколада с молоком и заваренным кофе. Мраморный кулич с кофейной глазурью подать на сервировочном блюде, нарезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4560,'Рыбные стейки горбуши поделить на две части и удалить кости. Каждый кусок обвалять в муке и обжарить на растительном масле до золотистой корочки. Для соуса: нарезать вдоль очищенный репчатый лук, так же поступить с чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4560,'То и другое обжарить на сковороде с растительным маслом. В конце обжаривания добавить томатную пасту, если она густая – немного развести водой. Соль, сахар – по вкусу. Добавить мелко нарезанные помидоры, молотый перец и сушеную паприку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4560,'Смеси дать потушиться еще 2 – 3 минуты. Обжаренную рыбу уложить в огнеупорную посуду, залить полученным соусом. Печь в духовке 20 минут. Горбуша, запеченная в томатном соусе готова. Перед подачей порционно нарезать и присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4561,'Замесить тесто: взбить яйца с сахаром, порциями добавить просеянную муку, сухое молоко, соль, погашенную уксусом или лимонным соком соду. Тесто должно быть полужидким. Вылить его на противень, печь при 220 градусах 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4561,'Вынуть из духовки, намазать любым повидлом, свернуть в рулет, пока корж не остыл. Подать простой рулет на скорую руку присыпав по желанию сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4562,'Взбить сырые яйца с сахаром, добавить просеянную муку с разрыхлителем и крахмалом. Печь 20 – 30 минут. Корж остудить. Для начинки размять творог с сахаром и ванилином. Добавить сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4562,'Отдельно развести желатин и ввести в творожно-сметанную массу. Остывший корж разрезать острым ножом по горизонтали. Половину выложить в разъемную форму, на корж – ягоды свежей клубники. Залить творожной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4562,'Поставить в морозильную камеру на 15 минут. Затем положить сверху второй корж, снова ягоды, залить готовым, разведенным в воде, желе из пакетика и снова заморозить. Подавать торт из творога со свежей клубникой на стол через час-полтора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Слоеный салат с беконом, яйцами и зеленью заправляется приготовленной заправкой и подается к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4563,'Содержимое пакетика малинового желе растворить в кипятке, остудить до 40 градусов, взбить миксером, добавляя сметану. Масса должна стать пышной, с пузырьками. По вкусу добавить сахарную пудру. Взбитый, легкий сметанный мусс разложить в креманки и убрать в холодильник до застывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4564,'Приготовить песочное тесто. Для этого растереть сливочное масло с сахаром. Просеять вместе муку и разрыхлитель. Добавить в масло, вместе с яйцом и солью. Замесить тесто, поставить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4564,'Смазать разъемную форму сливочным маслом, выложить раскатанное тесто. Печь при 200 градусах в течение 15 минут. Остудить. Замочить желатин в кипяченой воде. Дать набухнуть, затем прогреть, не доводя до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4564,'Протереть творог через сито, можно дважды, добавить сахар и ванилин из пакетика. Вымытую клубнику протереть до пюреобразного состояния. Соединить с творогом. Взбить сливки, также соединить с творогом, добавить желатин, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4564,'Еще часть клубники порезать кусочками и добавить в крем. Поставить в холод на час. Выложить массу на тесто, украсить сверху ягодами, их можно залить бесцветным желе. Дать застыть в течение 3 – 4 часов. Клубничный чизкейк на песочной основе готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4565,'Отделить от белка желток, в рецепте понадобиться только желток. Добавить к нему сметану, сахар и взбить. Затем постепенно вливать растительное масло, продолжая взбивать. Муку и разрыхлитель просеять, добавить в жидкую массу и замесить руками тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4565,'Оно должно отставать от рук. Из теста скатать колбасу, размером 3 на 4 сантиметра и нарезать ее на куски, толщиной около 1 сантиметра. Кусочки скатать в шарики и расплющить. Нанести рисунок: приложить молоток для мяса с шипами на печенье и немного придавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4565,'Поставить сковороду на маленький огонь и подогреть. Укладывать простое печенье на сковородку и печь около 3-4 минут с обеих сторон. В горячем виде края печенья будут мягкие – это так и нужно. Снять печенье на блюдо, остудить и кушать с любимыми напитками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4566,'Подогреть духовку (180 градусов), орехи измельчить в блендере, но не очень мелко, чтобы они чувствовались в тесте. Сахар взбить с маслом, приблизительно 5-7 минут. Добавить творог и перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4566,'Цедру лимона натереть, добавить в творожную массу, потом сюда же положить миндальную эссенцию и сок лимона. Тщательно смешать. Положить орехи, по одному вмешать яйца. Сюда же просеять муку с разрыхлителем, смешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4566,'Формы смазать маслом (можно испечь один большой кекс). Перелить в формы тесто. Сверху украсить колотыми фисташками. Отправить в духовку минут на 20-25 (если один большой кекс, то на 40-60 минут), печь до золотистых шапочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4566,'Затем формы достать из духовки и охладить (из остывшей формы кексы легко вынимаются). Получаются творожные кексы с фисташками и грецкими орехами очень мягкими и воздушными, прекрасно подойдут для завтрака.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4567,'Пассеровать на растительном масле нарезанный лук, натертую морковь и чеснок, добавить куркуму. Дать немного охладиться. Сырой картофель очистить и натереть на терке. Перемешать его с яйцами, манкой, горчицей, солью, майонезом, перцем и измельченной зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4567,'Потом добавить в картофель обжаренные лук и морковь, смешать. Сформировать из фарша маленькие шарики – фрикадельки (руки смочить водой). Картофельную массу переложить на смазанный противень и разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4567,'По всей поверхности выложить, немного вдавливая, помидоры черри и мясные шарики. Отправить форму в разогретую духовку (180 градусов) и запекать до готовности. Запеканку из картофеля с фрикадельками разложить порционно и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4568,'Вафли порезать на кусочки. Фундук измельчить, но не в крошку. Молочный шоколад растопить в микроволновке. Вафли, фундук и шоколад перемешать. Форму с бортиками застелить пергаментом. Переложить массу в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4568,'Поставить в холод, на час или два, для застывания. Ганаш: сливки подогреть в микроволновке, добавить масло и темный шоколад. Тщательно перемешать. Залить смесью застывшую основу и отправить в холодильник еще часа на 2.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4861,'Отбить нарезанное кусочками мясо, смазать каждый горчицей, дать постоять, обжарить на маргарине с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4568,'Когда масса застынет, разрезать ее горячим ножом на небольшие кусочки. Для глазури растопить темный шоколад, облить вафельные конфеты с лесным орехом шоколадом и опять отправить в холодильник. Готовый десерт подать на стол и наслаждаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4569,'Нарезать мясо на куски, лук нарезать кольцами, переложить в посуду, для маринования. Маринад можно применять любой (на свой вкус). Для этого рецепта используется следующий маринад: специи, сок лимона, бальзамический уксус, минеральная вода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4569,'Смешать и залить мясо маринадом. Отставить приблизительно на час и более. Взять деревянные шпажки, по размеру трехлитровой банки, нанизать на них мясо, чередуя с луком. Оставшийся лук уложить на дно сухой банки, сверху установить шпажки с мясом и накрыть горлышко банки фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4569,'Отправить банку в холодную духовку. Запекать приблизительно час (180 градусов). Потом духовку открыть и дать немного остыть, Нежный шашлык в банке вынуть из духовки и подавать к столу на сервировочном блюде, присыпав зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4570,'Нагреть духовку (180 градусов), все ингредиенты для глазури смешать. Куриные ножки положить в большую емкость, добавить соль, оливковое масло, перец (чили). Тщательно перемешать, чтобы ножки равномерно были покрыты приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4570,'Одним слоем выложить ножки на решетку, которую нужно установить на противне. Налить на него немного воды (не будет пригорать жир, который будет скапывать), запекать минут 25-30 (почти до готовности). Потом ножки достать, смазать их со всех сторон подготовленной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4570,'Вернуть противень в духовку минут на 5, затем достать и снова повторить смазывание глазурью. Поставить опять в духовку, пока ножки не подрумянятся. Достать из духовки ножки куриные в пикантной глазури, выложить на блюдо и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4571,'Хорошо вымыть чернослив и на полчаса залить его коньяком. Если по истечении времени коньяк не весь впитается – прогреть его в микроволновке (буквально 1 минуту) и охладить. Взбить сахар с яйцами (минимум 5 минут), небольшими порциями влить масло, продолжать взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4571,'Потом добавить творог и смешать миксером на небольшой скорости. Всыпать ванилин, разрыхлитель и муку (просеять), перемешать осторожно лопаткой. Затем добавить чернослив, еще раз перемешать и перелить в форму. Печь минут 10-15 (200 градусов), пока не зарумянятся края и не появится небольшой разлом на тесте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4571,'Снизить температуру в духовке (160 градусов) и печь кекс, до золотистого цвета. Оставить в духовке, чтобы немного остыл. Затем переложить кекс на решетку и охладить полностью. Присыпать кекс из творога с черносливом сахарной пудрой и подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4572,'Нагреть духовку (175 градусов), форму смазать маслом. Сахар добавить к яйцу и взбить до светлого оттенка (приблизительно 4 минуты). Затем добавить масло, банановое пюре, йогурт и ванилин. Отдельно перемешать муку, корицу, соду, разрыхлитель и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4572,'Постепенно, сухие ингредиенты добавить к жидкой смеси, перемешать. Перелить тесто в полиэтиленовый кулек и срезать уголок (как кондитерский мешок). Заполнить все формочки для пончиков из расчета 2/3 объема и поставить в духовку, минут на 10-12. Готовые пончики немного охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4572,'Смешать в небольшой емкости сироп, воду, масло и шоколад, Растопить глазурь (секунд 30) в микроволновке. Остывшие пончики окунуть в глазурь и смазать конфитюром. Отставить для застывания. Выложить пышные банановые пончики на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4573,'Нарезать баклажаны кружочками и присыпать солью (убрать горечь), воду, которая выступила, промокнуть полотенцем. Поджарить баклажаны на сковороде и выложить на салфетку (прибрать ненужный жир).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4573,'Натереть на терке брынзу. Мелко порезать инжир, измельчить грецкие орехи. Все смешать, добавить предварительно измельченный чеснок и мелко порубленную петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4573,'Смешать все со сметаной или майонезом (лучше приготовленным в домашних условиях). Выложить начинку на кружочки баклажана. Закуска из баклажан с инжиром и брынзой готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4629,'Молочно-яичную смесь влить в кипящее молоко, предварительно вынув из него цедру лимона и палочку корицы.Смесь варить, постоянно помешивая и снять с огня, как только она загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4574,'Нагреть духовку (220 градусов), форму смазать маслом. Сыр натереть на терке и смешать с измельченным сушеным тимьяном. Почистить картофель и порезать тоненькими ломтиками. Можно использовать специальную терку или кухонный комбайн.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4574,'Тогда, все ломтики будут одинаковыми, и это не займет много времени. Добавить сливочное масло (растопленное) и осторожно перемешать. На дно формы выложить ровным слоем третью часть картофеля. Присыпать сыром (третья часть), поперчить, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4574,'Повторить с процедуру. Последним слоем должен быть сыр. Запекать около часа, достать картофель с сырной прослойкой из духовки и подержать в форме около 5 минут. Затем перевернуть на блюдо и присыпать зеленью. Подать картофель к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4575,'Желатин замочить в холодной воде, пока не разбухнет. Перемешать сахарную пудру со сметаной. На водяной бане растопить желатин и тонкой струйкой влить в сметану, постоянно помешивая. Поломать крекер, положить его в сметану и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4575,'Застелить разъемную форму пленкой, натереть шоколад. Выложить смесь сметаны с печеньем в три слоя, каждый пересыпая тертым шоколадом. Отправить форму в холод на час или два. Застывший торт достать из холодильника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4575,'Украсить торт фруктами и залить желе (разводить в меньшем количестве воды, чтобы лучше застыло). Опять отправить в холодильник, до полного застывания (лучше на ночь). Сметанный торт из крекеров с фруктами готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4576,'Взбить яйца со щепоткой соли, добавить молоко, сахар, пиво, соду и перемешать. Постепенно добавить муку, а затем влить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4576,'На сковородке обжарить до готовности говяжий фарш, с предварительно измельченной луковицей и тертой морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4576,'Выложить начинку на готовый блин и свернуть конвертиком. Блины с фаршем, на пиве, можно подавать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4577,'Заправка: смешать семена кунжута, арахисовое масло, сахар, соль, соевый соус и рисовый уксус. Лапшу отварить до готовности и промыть водой (холодной). Морковь и грибы вымыть и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4577,'Креветки почистить и поджарить на вок-сковороде. Затем доложить к ним грибы шиитаке и жарить секунд 30, все время помешивать. Далее положить в сковородку пекинскую капусту (китайскую капусту) и прогревать еще секунд 30.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4577,'Добавить измельченную морковь. В готовую овощную смесь добавить лапшу и перемешать. Переложить лапшу соба с креветками и шиитаке в глубокие порционные тарелки, полить заправкой и присыпать сверху измельченной мятой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4578,'Растопить сливочное масло в сковородке на небольшом огне, положить туда яблоки (порезанные), корицу, сахар и тушить, пока на яблоках не появится карамельная корочка (приблизительно 2-3 минуты).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4578,'Уложить в высокий бокал слоями: йогурт, мюсли и яблоки. Слои повторить. Десерт яблочный парфе с мюсли и йогуртом готов. Перед подачей можно присыпать корицей или тертым шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4579,'Мясо перерезать по косточке и переложить в глубокую миску, для маринования. Добавить перец, соль и отставить в сторону. Смешать в отдельной емкости соевый соус (4 столовых ложки), белый бальзамический уксус, оливковое масло (2 столовые ложки), зерновую горчицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4579,'Добавить измельченный зубчик чеснока, чайную ложку коричневого сахара (по желанию). Тщательно смешать, и полить, получившимся маринадом, мясо. Мариновать приблизительно час, периодически перемешивать. Соус: зелень промыть и высушить, почистить имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4579,'Сложить в чашу блендера зелень, чеснок, имбирь, перец чили по вкусу. Понемногу подливая оливковое масло, измельчить блендером до однородности. Густоту данного соуса регулировать по собственному вкусу. Для большего аромата можно положить натертую цедру половины лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4579,'Добавить соевый соус, соль, щепотку соли, лимонный сок, 1 столовую ложку рисового уксуса. Потом попробовать и отрегулировать вкус, как нравится. Овощи вымыть, просушить, измельчить и поджарить на сковороде-гриль, залить их заправкой, смешанной из подготовленных ингредиентов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4629,'Разлить сразу по глиняным стаканам или маленьким мискам. Остудить десерт и посыпать сверху молотой корицей. Испанский десерт «Natillas» убрать на холод, до подачи на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4579,'Поджарить мясо на сковороде-гриль с каждой стороны (по 4 минуты). Затем, уложить его в форму для запекания, полить оставшимся маринадом и отправить в духовку минут на 10 (200 градусов). Разложить по порционным тарелкам, добавить овощи и соус. Говядина на косточке с овощами готова.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4580,'В емкость положить творог. Отделить желтки от белков, 3 желтка положить в отдельно, а остальные добавить к творогу. Белки тоже положить в отдельную емкость. В емкость с тремя желтками, добавить сливочное масло, половину сахара, муку (с разрыхлителем) и сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4580,'Замесить тесто. Сформировать шар и положить в холодильник на час. С яблок срезать кожуру и удалить сердцевину, порезать очень тонкими ломтиками или потереть на крупной терке. В творожную смесь добавить 1/3 стакана сахара, смешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4580,'Вынуть из холодильника тесто, уложить в форму, сформировать бортики. Разогреть духовку. На тесто выложить творог, потом уложить слой яблок, присыпать корицей и поставить в духовку минут на 30 (180 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4580,'Белки взбить с остатками сахара до устойчивых пиков. Пирог из духовки достать, выложить на него белки и поставить обратно минут на 5-7. Потом творожно-яблочный пирог с меренгами охладить, достать из формы и подать с чаем или кофе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4581,'Поставить на плиту вариться курицу. Кастрюлю взять лучше около 3 литров. После закипания воды, огонь уменьшить и собрать пену. Потом положить нарезанный кубиками картофель. Обжарить на сковородке измельченный лук и чеснок, натертую морковь. Отдельно обжарить измельченные грибы, поперчить и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4581,'Добавить, к почти готовой курице и картофелю, лук, морковь, а также грибы. Посолить, поперчить. Варить еще минут 5. Затем положить в суп плавленый сыр. Мешать, пока сыр не растворится полностью. Дать покипеть куриному супу с сыром и шампиньонами пару минут и добавить измельченную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4582,'Взять черный чай (три пакетика) и заварить его в стакане (воды налить до половины), отставить минут на 20. Мойву разморозить, отрезать у нее голову и вместе с головой вынуть тонкую кишку. Оставить молоки и икру. Промыть луковую шелуху и выложить ее на дно сковороды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4582,'Добавить лавровые листья, черный перец и чеснок (нарезать пластинами). Сверху выложить рыбу, плотными рядами, брюшками вниз. На нее покрошить бульонный кубик и можно немного посолить (1 бульонный кубик рассчитан на 500 грамм).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4582,'Потом вылить в сковородку остывшую заварку, жидкий дым (по желанию) и растительное масло. Получится, что рыба залита жидкостью до половины или немного больше. Прикрыть сковороду крышкой и отправить на большой огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4582,'Как только появятся первые признаки кипения, огонь уменьшить до минимума и оставить минут на 50 или на час. Потом снять крышку и опять прибавить огонь на максимум. Проварить минуты 3-4 (чтобы испарилась ненужная вода).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4582,'Домашние шпроты в луковой шелухе охладить и переложить в лоток или баночку для хранения, залить остатками жидкости из сковородки. Готовые шпроты можно кушать или использовать для приготовления бутербродов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4583,'Разморозить тесто (при комнатной температуре), залить мак кипятком. Изюм промыть водой и замочить. Когда тесто разморозиться, его нужно немного растянуть руками или раскатать. Взбить сахар с белком, добавить мак (процеженный) и хорошо перемешать. Смесь нанести на тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4583,'Присыпать сверху изюмом и прибавить немного сахара (по желанию). Свернуть все рулетом, порезать на кусочки и ненадолго оставить. Затем смазать, взбитым с молоком, желтком и присыпать маком. Слоеные булочки с изюмом и маком поставить в нагретую духовку на 15-18 минут (180 градусов). Готовые булочки немного охладить и подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4584,'Крем: смешать 2 яичных желтка (белки совсем не потребуются) и одно яйцо, молоко, сливки, ванильный сахар и обычный. Формочки обмазать сливочным маслом. Карамель: отжать сок из лимона. На медленном огне растопить на сковородке сахар, периодически необходимо встряхивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4584,'Когда сахар потемнеет, влить сок лимона и горячую воду. Кипятить, пока весь сахар не растворится, постоянно мешая. Убрать с огня и разлить жидкую карамель в формочки – она должна полностью покрыть их дно. Затем в формочки влить яичную смесь, на карамель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4584,'В противень или в форму для запекания поставить формочки с кремом и до половины высоты формочек налить воды. Печь в духовке приблизительно час (150-160 градусов), крем должен загустеть. Готовые десерты достать из воды, остудить до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4584,'Прикрыть пленкой и убрать в холодильник на 5 часов (чем дольше охлаждается, тем вкуснее). Затем необходимо провести вдоль стенки формочки ножом, накрыть ее блюдцем и резко перевернуть. Оригинальный десерт «Крем-карамель» можно подавать на праздничный стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4585,'Порезать хлеб небольшими кусочками. Выложить на сковороду и обжарить. Зажаривать по своему вкусу, можно зажарить сильно, а можно только получить легкую корочку. Необходимо следить, чтобы хлеб не подгорел – жарится очень быстро. Кусочки хлеба перевернуть и вбить к ним яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4585,'Посолить, поперчить и присыпать любимыми приправами. Накрыть сковородку крышкой, чтобы желтки и белки приготовились. Степень прожарки яиц регулировать по своему вкусу. На терке натереть пармезан (можно брать любой твердый сыр), потом пересыпать равномерно сыр в сковороду, на яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4585,'Оставить сковороду на огне, чтобы сыр растаял, но накрывать не стоит, так как образуется конденсат, а сыр должен остаться сухим. Переложить на тарелку, присыпать зеленью (мелко нашинковать), украсить свежими овощами. Гренки с яйцом и сыром пармезан кушать горячими на завтрак.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4586,'Картофель нарезать кубиками, морковь брусочками, лук – полукольцами, перемешать. Притрусить приправами, помидор натереть на терке. Влить растительное масло и перемешать. Уложить смесь в рукав, поставить в духовку часа на полтора (180 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4586,'Потом переложить все в миску. Добавить измельченный чеснок и зелень. Аккуратно перемешать, прикрыть пленкой и отставить, чтобы настоялось минут 5. Сочный картофель, запеченный в рукаве, выложить на тарелку и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4587,'Яйца взбить, поперчить, посолить. Мелко нарезать зеленый перец, обжарить на сливочном масле минуты 3. Прибавить измельченную ветчину и тушить еще минуты 2. Затем добавить измельченную петрушку и влить взбитые яйца. Жарить до готовности, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4587,'Взять тортилью и положить на нее омлет, притрусить натертым сыром и осторожно завернуть, так же сделать и с остальными. Простой буррито с ветчиной и сыром готовиться очень быстро, особенно если гости уже на пороге.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'В чашу кухонного комбайна всыпать муку (пшеничную и кукурузную), соль, потом добавить порезанное кубиками масло, взбивать, пока масса не станет крошкой. Потом сюда добавить воду (1 столовую ложку), желтки яичные, снова взбивать – смесь должна собраться в комок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'Если тесто суховатое, то можно положить еще пару ложек воды, чтобы тесто можно было собрать в шар. Завернуть тесто в пленку и охлаждать не менее 30 минут, а можно и больше. Налить сливки в небольшую кастрюльку, добавить щепотку соли, веточку тимьяна и листья шалфея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'Довести сливки до кипения, потом убрать с огня и оставить, чтобы настоялись и остыли полностью. Поверхность доски или стола слегка притрусить мукой и раскатать тонко тесто. Вырезать из него круги и уложить тесто в формочки для тарталеток, излишки теста срезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'Смазать формочки немного взбитым яичным белком и снова поставить охлаждаться (приблизительно на час). Нагреть духовку (180 градусов), достать тарталетки из холодильника, застелить пергаментной бумагой, насыпать бобы и поставить в духовку минут на 15.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'Потом вынуть, убрать бобы и бумагу и поставить обратно еще минут на 5. Затем тарталетки достать из духовки, температуру убавить до 170 градусов. Сливки сквозь сито процедить в емкость, добавить к ним взбитые яйца и тыквенное пюре, по вкусу приправить, тщательно смешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4588,'Ложкой класть смесь в тарталетки, присыпать сверху натертым пармезаном и листьями тимьяна. Печь приблизительно 20-25 минут. Оставить тарталетки в формочках, пока не остынут. Затем каждую тарталетку порезать на 4 части и выложить на блюдо. Тарталетки с тыквой и травами готовы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4630,'Масло согреть до мягкости при комнатной температуре. Взбить его с сахаром. Яйцо разбить к маслу и снова взбить блендером. Муку просеять с разрыхлителем и смешать со смесью яиц и масла. Включить духовку на 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4589,'Очистить от кожуры 3 банана, взбить блендером в пюре. Добавить к ним творог и опять взбивать. Затем к смеси положить сахар, соль и муку, взбить. Добавить яйца и сметану, опять взбить. Массу перелить в форму и поставить в духовку на 1 час (150 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4589,'Готовую запеканку полностью охладить и поставить на ночь в холодильник. Два банана порезать тонкими кружочками и украсить ими десерт. Перед подачей, легкий бананово-творожный десерт полить шоколадной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4590,'Тунец (обязательно слить воду) тщательно перемешать с измельченными овощами. На тарелку выложить листья салата, намазать куски булки или зернового хлеба смесью и уложить на листья салата. Простой бутерброд с тунцом можно кушать на завтрак или взять на пикник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4591,'Из печенья сделать крошку, с помощью блендера. Масло растопить, охладить и добавить к крошке. Замесить тесто – оно получается немного рассыпчатым и мокрым. Застелить пленкой форму для выпечки, на дно уложить тесто. Распределить по всей поверхности, утрамбовать и поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4591,'Желе из пакета сделать по инструкции, чтобы застывало. Его необходимо залить в такую форму, которая будет напоминать форму для выпечки, но будет ниже и меньше в диаметре. Отправить в холодильник, чтобы застыло. Через некоторое время добавить ломтики киви в желе. Дать полностью застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4591,'Чтобы вынуть желе из формы, ее нужно ненадолго опустить в емкость с горячей водой. Затем перевернуть форму с желе, в центр, на слой теста. Поставить на огонь молоко и, не доводя до кипения, нагреть. Залить молоком желатин. Хорошо перемешать, пока желатин полностью не растает и охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4591,'Добавить в сметану сахар и взбивать до полного растворения. В процессе взбивания добавить ваниль и развести пресным молоком. На небольших оборотах миксера взбить сметану. Влить тонкой струйкой молоко с желатином (чтобы не было комков, и желатин не схватился моментально).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4591,'Затем, взбитую смесь осторожно вылить в форму с тестом и желе. Отправить форму в холодильник еще на час. Потом аккуратно снять бортики формы и пленку. Сметанный торт с киви без выпечки готов. Торт получается очень воздушным и нежным, кисло-сладким на вкус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4592,'Смешать кефир с манкой и отставить, чтобы манка набухла. Яйца с сахаром взбить. Добавить сахар ванильный, какао, соль и разрыхлитель, перемешать. Соединить яичную смесь с манной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4592,'Форму для запекания немного смазать маслом (можно еще и положить бумагу), присыпать манкой. В форму перелить тесто и поставить на 40 минут в духовку (180 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4592,'Аккуратно достать простой шоколадный манник на кефире из духовки, охладить и присыпать какао (удобнее через сито). Выложить пирог на блюдо и кушать с чаем или кофе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4593,'Филе куриное порезать полосками и обжарить минуты 4-5 (до небольшой румяности), на оливковом масле. Лучше обжаривать порциями, чтобы они ложились на сковородку в один слой, а потом сложить вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4593,'Натереть цедру лимона и выдавить сок (нужно 2 столовые ложки). Все мясо переложить на сковородку, добавить к нему измельченный чеснок, сок лимона, соль, цедру и перец, убавить огонь до минимума и готовить минут 10.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4593,'Влить к мясу сливки, прибавить огонь, тушить пока сливки не загустеют. Потом добавить горошек и феттучини, немного подогреть и убрать с огня. Феттучини с куриным мясом получается очень нежным и сытным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4594,'Щуку тщательно вымыть, голову, плавники и хвост отрезать (жабры удалить) – их потом можно использовать для ухи. Тушку разрезать вдоль, тщательно очистить от пленок и внутренностей. Фарш: лук измельчить и поджарить на растительном масле до золотистого оттенка. Батон порезать на небольшие кусочки и просушить в духовке (тогда он будет лучше впитывать влагу).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4594,'Залить батон молоком и оставить ненадолго. Затем перекрутить на мясорубке филе рыбы, батон с молоком и лук. Затем прокрутить эту массу еще раз, чтобы она стала однородной, и раздробились все косточки. Получившийся фарш немного отбить, постепенно доливать сливки (по немногу, так как фарш станет тугим). Взбить белок и вмешать его в фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4861,'Нашинковать лук полукольцами, картофель порезать кубиками и положить на шпик, посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4594,'Потом еще совсем немного отбить, фарш готов – из него можно лепить все, что угодно, и рулеты, и котлеты, в данном случае каштаны. Начинка – измельчить креветки, добавить обжаренный лук и соль, перец. Насыпать на плоскую тарелку муку, в отдельной емкости взбить немного яйцо. Руки в процессе лепки смачивать теплой водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4594,'Из рыбного фарша сформировать лепешку, в средину положить 1-2 чайные ложки начинки, края соединить и аккуратно скатать шарик. Вначале обкатать его в муке, затем в яйце и затем в сухариках (необходимо, чтобы сухари покрыли всю поверхность). Налить растительное масло в глубокую сковородку или фритюрницу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4594,'Масло должно покрывать минимум половину шарика. Обжаривать каштаны со всех сторон до золотистого оттенка (буквально полминуты на один шарик). Потом выложить на противень и довести до готовности в духовке, минут 15-20. Подавать рыбные котлеты «Каштаны» из щуки можно с овощным салатом или зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4595,'Промыть рис и отварить его до готовности. Печень также промыть, отчистить от пленок и прокрутить через мясорубку. Потом к ней добавить рис, яйцо, соль и муку, смешать. Тесто должно выйти как на оладьи. Обжаривать их на сковородке с растительным маслом со всех сторон до золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4595,'Готовые оладьи из печени с жареным луком переложить на блюдо. Лук порезать полукольцами, поджарить, добавить к нему немного сахара, чтобы получился красивый золотистый оттенок. Перед подачей присыпать жареным луком оладьи и можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'Рыбу взбрызнуть лимонным соком, присыпать солью и отправить в холодильник на полчаса. Потом достать и нарезать на куски. Лук и коренья почистить. Желатин распустить. Налить 2,5 литра воды в кастрюлю, положить туда соль, горошины перца, коренья и лук. Когда вода закипит – уменьшить огонь до минимума и варить минут 25-30.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'В бульон положить рыбу и морковь, варить еще минут 20 на небольшом огне. Затем морковь и рыбу достать и охладить. Морковь будет применяться для оформления заливного. Процедить бульон (либо сквозь несколько слоев марли, либо сквозь сито), добавить к нему набухший желатин и отправить на огонь. Хорошо прогреть, но не кипятить, затем полностью охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'Украшение: залить желатин холодной кипяченой водой, половину количества рыбы порезать тонкими пластинками, а вторую половину маленькими кусочками. Отварить перепелиные яйца (после закипания воды, варить их нужно 7 минут), потом залить их холодной водой. Когда яйца остынут – разрезать на половинки. Подготовленную клюкву немного просушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'Одну морковь нарезать тонкими пластинами вдоль и вырезать ножом или формочками листики, а во второй вырезать желобки и нарезать кружочками (получатся цветочки). Способы оформления заливного. 1 способ: налить в форму бульон (толщина 1 сантиметр), поставить его в морозилку минут на 10-15, желатин схватится, куски рыбы не будут тонуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'Уложить на застывший бульон кусочки рыбы и украшения по собственному вкусу, потом налить немного бульона (буквально 0,5 сантиметров) и снова отправить в морозилку. Затем вынуть, разложить по бортам формы украшения и полностью налить бульон. Отправить в холодильник, пока полностью не застынет. Потом перевернуть его на тарелку и украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'2 способ: выложить на дно пластинки рыбы и украшения, залить немного бульона и поставить в морозилку (минут 10-15), потом достать, полностью залить бульоном и отправить в холодильник. 3 способ: желатин добавить в сливки, подогреть, чтобы желатин растворился, но не кипятить, охладить полностью. Мелко порезанную рыбу залить бульоном, перемешать и перелить в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4596,'Поставить в морозилку, чтобы схватилось, потом налить сверху слой сливок и опять убрать на холод. Поверх сливочного слоя выложить рыбные пластинки и украшения, добавить немного бульона и поставить в морозилку. Когда схватится, бульон залить до верха и снова поставить в холодильник до окончательного остывания. Заливная щука с овощами готова.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4597,'Острым ножом в каждой ножке сделать пару надрезов с каждой стороны. Переложить ножки в емкость (не металлическую), добавить к ним оставшиеся ингредиенты. Тщательно смешать, накрыть емкость фольгой или крышкой и поставить в холодильник (в идеале на ночь).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4597,'Подогреть духовку (220 градусов, режим гриля) вынуть ножки из маринада и выложить плотными рядами в жароупорную форму. Остаток маринада оставить в емкости, он еще понадобится. Поставить форму с ножками на средний уровень духовки, печь минут 30-40.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4597,'В процессе приготовления надо поливать курицу остатками маринада и переворачивать. Готовность регулировать по собственному вкусу – курица получится сочная или хрустящая. Уложить сочную курицу в медовом маринаде на тарелку, украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4598,'Нашинковать лук и поджарить его на оливковом масле. Ножом раздавить дольку чеснока, порезать на маленькие кубики морковь и добавить все к луку. Затем всыпать рис и немного прожарить. Влить вино. Огонь увеличить, чтобы вино выпарилось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4598,'Измельчить помидоры и вместе с горошком положить в сковородку, влить 300 мл горячей воды, добавить перец и соль, тушить 10 минут. Потом положить брокколи и стручковую фасоль, готовить еще 10 минут. Легкое ризотто с овощами можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4599,'Очистить мясо от жилок и пленок, потом его порубить совсем мелко или перекрутить сквозь мясорубку. Потом фарш посолить, добавить яичный желток, перемешать и сформировать котлетки. Нарезать овощи кружочками и кольцами, уложить в кастрюлю и налить воды столько, чтобы она только немного их накрывала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4599,'Потушить овощи почти до готовности, потом добавить зелень (свежую или сушеную), уложить котлетки сверху, прикрыть крышкой и готовить на медленном огне. Они готовятся практически на пару. Котлеты из телятины с тушеными овощами выложить на порционные тарелки и можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4600,'Смешать творог с яйцами, солью, содой и сахаром до однородной консистенции. Потом добавить муку (уходит приблизительно с горкой 12 столовых ложек), замесить тесто, вероятно муки придется снова добавлять, так как творог бывает разным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4600,'Затем от теста отщипнуть маленькую часть и скатать в шарик или сделать шарик или пончик (шарик немного сплюснуть и большим падем сделать небольшое углубление). Налить в емкость масло (около 350 мл), когда закипит – опускать в него шарики (пончики).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4600,'Поджарить до золотистого оттенка, не забывать переворачивать. Выкладывать на салфетку, чтобы стекло ненужное масло. Легкие творожные шарики полить растопленным шоколадом или присыпать пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4601,'Отварить куриные грудки, охладить и нарезать небольшими кусочками. В отдельной емкости смешать до однородной консистенции молоко, соус ранч, яйца и муку. Измельчить зелень (которая больше нравится), сыр натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4601,'Смешать вместе сыр, курицу, молочную смесь с мукой и часть зелени. Яично-молочную смесь вылить не всю, добавлять как для заправки салата. Формочки для кексов немного притрусить мукой, выложить ложкой курицу, сверху добавить оставшуюся смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4601,'Печь в духовке до готовности (приблизительно минут 20 при 180 градусах). Потом вынуть готовые кексы и присыпать зеленью. Маффины куриные с сыром охладить и можно подавать к столу. Их отлично дополнит соус сальса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4602,'Рыбу порезать на кусочки, приправить перцем, солью и отставить на 20 минут. Почистить картофель и нарезать тоненькими кружками. Помидоры нарезать сначала кружочками, а затем перерезать напополам, сыр натереть на терке. Уложить в форму половину картофеля, поперчить и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4602,'Сверху уложить рыбу, помидоры, затем выложить остаток картофеля, присыпать перцем и солью. Смазать сверху майонезом, притрусить сыром и отправить в духовку минут на 40. Картофель с рыбой под сырной корочкой разложить порционно, присыпать рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4603,'Отварить рис, натереть морковь на мелкой терке, нашинковать капусту, как можно мельче, добавить яйца, фарш, поперчить и посолить. Положить лук, все смешать. Соус: перемешать сметану и томатную пасту, добавить специи и соль. Сформировать в форме котлеток или в форме тефтелек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4603,'Затем их немного обжарить на сковородке, но можно этот процесс и пропустить. Выложить голубцы в форму. Залить соусом и поставить в духовку приблизительно на полчаса. Вынуть голубцы ленивые из духовки, разложить порционно и подать на стол. Присыпать зеленью и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Почистить картофель среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/72/894ddbb7b503f72_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4604,'Поставить варится картофель для начинки. Тесто: взять муку (3 стакана), просеять, добавить к муке сухие дрожжи и теплую воду. Оставить минут на 10. Потом в тесто добавить сметану, сахар и соль. Замесить плотное тесто, добавляя муку по необходимости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4604,'Отставить, чтобы поднялось. Начинка: смешать толченый картофель, предварительно нарезанный и поджаренный лук, приправить солью и перцем. Разделить готовое тесто на небольшие шарики. Из шарика образовать лепешку, уложить в центре него ложку начинки и защипнуть края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4604,'Аккуратно расплющить пирожок до 1 сантиметра толщиной, следить, чтобы тесто не порвалось. Жарить их на масле растительном с каждой стороны (небольшой огонь). Готовые пирожки с картофелем присыпать свежей или сушеной зеленью и измельченным чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4605,'Разморозить тесто и раскатать его немного больше, чем диаметр сковородки, положить тесто в холодильник, чтобы не подходило. Очистить яблоки, удалить сердцевину, нарезать половинками и взбрызнуть лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4605,'Растопить сливочное масло на сковородке, добавить сахар и корицу (можно заменить ванильным экстрактом), мешать, пока сахар не растает и смесь не станет карамелью. Убрать сковородку с плиты, выложить в карамель яблоки, ставить их нужно плотно на ребро.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4605,'Опять поставить сковородку на огонь (самый маленький) минут на 25. Карамель будет кипеть и очень увеличится в объеме за счет яблочного сока. Потом с огня убрать и дать немного остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4605,'Достать из холодильника тесто, расправить и выложить его на яблоки, края аккуратно подоткнуть по бокам яблок. Сделать на тесте ножом дырки 3-4, поставить в духовку на полчаса (230 градусов). Вынуть из духовки и оставить минут на 15, чтобы немного остыл.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4605,'Потом необходимо перевернуть ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4606,'Лук почистить и очень тонко нашинковать. В отдельной емкости смешать сахар, соль, масло, перец и уксус. Залить данной заправкой лук и отставить. Фасоль процедить от жидкости и выложить в емкость. Ветчину и огурцы измельчить соломкой. Вымыть зелень, просушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4606,'Зеленый лук измельчить, со стебельков петрушки сорвать листья (ее можно заменить и кинзой). В миску к фасоли прибавить зелень, ветчину и огурцы. Смешать, потом добавить лук вместе с заправкой и перемешать. Легкий салат из фасоли с ветчиной переложить в салатницу и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4607,'Взять половину зубчика чеснока, мелко измельчить, положить его в баночку. К нему добавить дижонскую горчицу, красный (можно белый) винный уксус, оливковое масло. Также сюда положить по 1 щепотке черного перца и соли, закрыть крышку и тщательно потрясти. Французская чесночная заправка готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4608,'В баночку налить натуральный йогурт, красный (можно белый) винный уксус, оливковое масло, по щепотке свежемолотого черного перца и соли. Прикрыть крышкой и салатную заправку на йогурте хорошо потрясти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4609,'Налить в баночку оливковое масло, добавить также свежемолотый черный перец и соль (по щепотке). Туда же выжать сок одного лимона. Прикрыть крышкой и хорошенько потрясти. Простой лимонной заправкой взбрызнуть салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4610,'Налить в баночку оливковое масло, уксус бальзамический, добавить черный молотый перец и соль (по 1 щепотке). Крышку закрыть и хорошо потрясти. Заправка салатная с бальзамическим уксусом готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4611,'Филе отделить от курицы, промыть и нарезать продольными кусочками (умеренно тонкими). Каждый кусок отбить молотком (не сильно). Притрусить смесью специй, черным молотым перцем и солью. Сложить кусочки один на один и ненадолго оставить. Мясо должно хорошо пропитаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4611,'Вбить в глубокую миску 3-4 яйца. На плоскую тарелку насыпать муку. На сковороде нагреть масло, взять кусок мяса, обмакнуть его сначала в муке, а потом в яйцах. Выкладывать на разогретую сковороду и жарить с каждой стороны (минут 5-7).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4611,'Натереть на крупной терке твердый сыр, добавить измельченную зелень укропа. Хорошо перемешать и выложить смесь на биточки, приблизительно за минуту до готовности. Когда сыр расплавится, переложить пряные куриные отбивные под сыром на тарелку и подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6319,'Соединить сметану, соевый соус, зеленый лук и зернистую горчицу, полученным соусом полить приготовленный салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4612,'Картофель измельчить, положить в кастрюльку, залить водой и поставить на плиту. Воду с картофеля слить, но не выливать, так как она может еще пригодится. Возможно, ее надо будет доливать. Затем картофель размять – можно использовать толкушку, мясорубку или блендер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4612,'Поэтому, нужно будет добавлять воду, понемногу. Стараться, чтобы в картошке не было комочков. Потом пюре отставить, чтобы остыло. Тесто: в емкость положить соль, сахар, дрожжи и залить водой (обязательно теплой, не горячей и не холодной).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4612,'Всыпать муку и вымесить некрутое тесто. Затем добавить охлажденное пюре. Смешать. Прикрыть миску с тестом салфеткой и поставить в теплое место примерно на час (чтобы оно выросло в 2 раза). Переложить тесто на противень, разровнять руками, полить сверху оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4612,'Сделать маленькие выемки пальцами. Отставить тесто минут 10-15 и затем отправить в духовку на 15-20 минут (200 градусов). Выпекать итальянскую картофельную фокаччу до золотистого оттенка. Затем немного остудить, порционно нарезать и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4613,'Разогреть духовку до 180 градусов. В отдельной емкости манку залить кефиром, перемешать и отставить, чтобы набухла. На дно формы уложить бумагу, бока формы смазать маслом и притрусить мукой. Белки отделить от желтков, взбить их до устойчивых пиков. В процессе взбивания добавить лимонный сок и немного сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4613,'Взбитые белки поставить в холодильник. Отдельно смешать желтки (5 штук), творог, ванильный сахар, остатки сахарного песка, соль и разрыхлитель. Затем добавить кефир с манкой и еще раз тщательно перемешать. Осторожно, чтобы не опали, белки ввести в тесто (лучше это делать частями).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4613,'Мешать нужно аккуратно, поворачивая миску. Перелить тесто в форму и отправить в духовку, выпекать приблизительно 50-55 минут. Минут через 45 уже можно проверять готовность зубочисткой. Дать запеканке из творога и манной крупы немного остыть и достать из формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4614,'Кожу с куриной ножки аккуратно отделить от мяса, чтобы не порвать. Вывернуть кожу и срезать мясо. Топориком обрубить кость, но часть косточки оставить. Грибы с луком измельчить и обжарить. Из лука, грибов и мяса сделать фарш, сыр натереть и положить в фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4614,'Начинить голень получившимся фаршем и край закрепить шпажкой или зубочисткой. Поставить куриную голень с грибной начинкой в духовку приблизительно на час (температура 180-200 градусов). Готовые ножки подать с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4615,'Из свинины и говядины сделать фарш. Добавить к нему сухари или хлебные крошки. Положить в фарш измельченный чеснок и специи. Вбить яйца и добавить тертый сыр. Влить бульон и хорошо перемешать фарш руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4615,'Форму для хлебцев смазать маслом, переложить туда фарш и разровнять. Сверху выложить несколько лавровых листиков. Запекать в духовке около часа (180 градусов). Традиционный мясной митлоф можно употреблять как холодным, так и горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4616,'Тесто разморозить. Яблоки вымыть, нарезать четвертинками, вырезать сердцевину и нарезать дольками (стараться резать как можно тоньше). Вскипятить 1 стакан воды и сахар (3 ложки). Выложить яблоки в сироп и проварить 2-3 минуты. Затем их вынуть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4616,'Раскатать тесто (длина около 30 сантиметров) и разрезать его на полосы, шириной 3 сантиметра. На каждую полоску уложить внахлест по 4 дольки яблок. Они должны приблизительно на 1/3 выступать за край теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4616,'Край полоски оставить свободным, с его помощью можно будет соединить розу, чтобы она не раскручивалась. Тесто с яблоками аккуратно завернуть в трубочку. Нижний край теста подвернуть внутрь – основание розочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4616,'Стараетесь, чтобы основание получилось ровным – удобнее будет ставить. Выставить все розы на смазанный противень и запекать в духовке около получаса (180-200 градусов). Готовые яблочные «Розы» в тесте немного охладить и присыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4617,'Тесто очень тонко раскатать и уложить в форму так, чтобы свисали большие края. Поджарить фарш и лук, влить сливки, соевый соус. Добавить соль, приправы по собственному вкусу. Укладывать на тесто начинку слоями: вначале выложить фарш, на него измельченный лук (сырой), потом грибы (также сырые).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Осторожно перемешать салат из курицы с овощами и кунжутом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4617,'Свисающие края теста нарезать полосками, дорезая до края формы. Сплести поверх начинки, из порезанных краев теста, косичку. Смазать яйцом и поставить в духовку минут на 35 (180 градусов). Слоеный пирог с грибами и мясом немного охладить и можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4618,'Немного растаявшее сливочное масло взбить с ванильным и обычным сахаром до пышности. Яйца взбить отдельно. Затем добавить к маслу, влить молоко. Прибавить муку и вымесить тесто. Поделить его пополам и выпечь 2 коржа (минут 20), тесто рассчитано на диаметр формы приблизительно 18 сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4618,'Готовые коржи охладить. Взбить сливки (можно без сахара, так как джем и бисквит довольно сладкие). Смазать сливками один бисквит. Второй, смазать джемом. Аккуратно соединить оба коржа так, чтобы между коржами были и сливки, и джем. Присыпать классический торт «Виктория пудрой и украсить ягодами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4619,'Тесто: смешать воду (обязательно теплую) с сахаром и добавить дрожжи. Отставить ненадолго, чтобы появилась пенка. Затем добавить масло, перемешать. Всыпать соль и муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4619,'Уложить тесто в емкость, смазанную маслом, прикрыть влажным полотенцем и отправить в теплое место на час. Тесто должно, как минимум, увеличиться в два раза. Разогреть духовку до 230 градусов. Застелить противни бумагой и смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4619,'Большую кастрюлю с водой поставить на огонь, положить соду и вскипятить. Поделить тесто на 8 частей. Из каждой части раскатать длинный жгут и расплющить его. По всей длине выложить тертый сыр и защипать края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4619,'Забросить подготовленные крендели в кипящую воду (по одному) и варить 30 секунд. Если вода крендель покрывает не полностью, то нужно поливать крендели кипятком с помощью черпака. Вынуть из воды и выложить на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4619,'Смазать сверху взбитым желтком с водой и присыпать крупной солью. Выпекать приблизительно минут 12, до золотистого оттенка. Крендели сырные немного остудить перед подачей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4620,'Разогреть духовку 175 градусов. Подготовить 2 противня и застелить их бумагой для выпечки. Смешать какао с мукой, с помощью миксера взбить сахар, масло, соль и мучную смесь до однородности. Прибавить ванилин, желтки и снова взбить. Поделить тесто пополам и каждую часть раскатать на доске.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4620,'Пласты нарезать прямоугольниками, должно выйти 24 штуки (обязательно четное количество). Переложить получившееся печенье на противень и печь минут 15-20. Вынуть, когда печенье станет твердым внутри и охладить. Затем, на противень выложить ровным слоем мороженое и поставить в морозилку, для заморозки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4620,'Нарезать мороженое на 12 прямоугольников, чтобы совпал размер. Можно использовать печенье, как трафарет. Между печеньями укладывать мороженое и заворачивать каждый сэндвич в пленку (чтобы держало форму). Готовые шоколадный сэндвич с мороженым хранить в морозилке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4621,'Три куриных грудки разрезать вдоль. Получившиеся  кусочки умеренно отбить. Посыпать солью и перцем. Ветчину порезать тонкими ломтиками чуть меньше по размеру, чем отбивная. Сыр порезать аналогично. На отбивную выложить ломтик ветчины и сверху сыра. Свернуть отбивные с начинкой в плотный рулет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4621,'Если он плохо держится, то закрепить для надежности зубочисткой. Смешать вместе паприку и муку. Панировать рулеты в обсыпке. Сливочное масло растопить на сковороде и выложить куриные рулеты. Обжарить с двух сторон. Затем залить вином и насыпать куриную приправу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4621,'Закрыть сковороду крышкой и потушить блюдо еще полчаса. Для соуса смешать крахмал и сливки. Рулеты вынуть со сковородки, а соус влить в нее. Постоянно помешивая, дождаться, когда соус загустеет. Куриное мясо «Кордон» в белом вине выложить на блюдо, полить сверху соусом и присыпать паприкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4622,'Мытые помидоры наколоть, чтобы они потом не потрескались. Можно сделать это иголкой или зубочисткой. В чистую, трех литровую банку сложить зонтик укропа, колечко острого перца, гвоздику, душистый перец. Также положить лавровый лист, и четвертинку сладкого перца. Помидоры уложить в банку и залить свежим кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4635,'Перекрутить рулет и связать узелком. Сформированные булочки переложить на противень и оставить на 15 минут, для окончательной расстойки. Смазать желтком булочки и присыпать черным тмином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4622,'Дождаться, когда содержимое остынет. Слить остывшую воду и добавить в банку еще зубчик чеснока, порезанный на кусочки, соль, сахар и влить уксусную кислоту. Залить кипятком второй раз и закатать банку с «Царскими» помидорами металлической крышкой. Укрыть банку с ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4623,'Смазать противень маслом. Картофель порезать кружками или брусками. Стейк семги разрезать на порционные ломтики. Лук порезать кольцами, сыр натереть на терке. Выложить на противень картофель, на него уложить семгу, посыпать луком и сыром. Залить сверху майонезом. Поставить в духовку на 40 минут для запекания. Нежную семгу, запеченную с сыром, выложить вместе с картофелем на блюдо и подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4624,'Это блюдо лучше делать в двойном размере, так как оно очень вкусное и съедается очень быстро. Можно его есть с печеньем, оладьями или просто так. Вареную сгущенку выложить из банки в глубокую посуду. Шоколад разломать на кусочки, положить к сгущенке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4624,'Влить туда же миндальный сироп. Поставить на водяную баню посуду с ингредиентами. И постоянно помешивая, нагреть до полного растворения шоколада. Возможно, останутся крупинки, не разошедшейся сгущенки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4624,'Снять емкость с водяной бани и взбить ее содержимое в течение 2 минут до однородности. Шоколадную пасту переложить в чистую стеклянную посуду, закрыть и поставить в холодильник. Через полчаса уже можно кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4625,'Отварить морковь и куриные грудки вместе с луком, лавровым листом, горошинами перца и несколькими стеблями сельдерея. Также добавить соль. Через 10–15 минут варки, огонь выключить, а мясо оставить в бульоне еще на 10–15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4625,'Яблоки порезать на кубики небольшого размера. Очистить сельдерей от волокон и порезать на небольшие кусочки чуть наискосок. Выжать сок половины лимона и сбрызнуть им яблоки. Противень застелить пергаментной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4625,'Орехи разложить на противне и поставить в духовку, разогретую до 180 градусов. Периодически помешивать орехи. Через 5–8 минут достать их из духовки. Куриное мясо вынуть из кастрюли с бульона и обсушить бумажными полотенцами. Разделить мясо на волокна.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4625,'Орехи порезать ножом на кусочки. Выложить 2/3 орехов к мясу. К мясу и орехам добавить яблоки, сельдерей. Залить йогуртом и майонезом. Посолить и перемешать салат. Охладить примерно в течение часа и подавать «Вальдорфский» салат с грецким орехом, посыпав остальными орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4626,'Натереть на терке сыр, зелень мелко порезать. Яйца отварить. Нарезать остальные продукты, желательно кубиками небольшого размера. В салатник выложить все ингредиенты и перемешать. Салат «Берлинский» с ветчиной заправить майонезом. Готовый салат подать к столу и кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4627,'Измельчить на мясорубке мясо. Добавить соль и перец. Лук мелко порезать. Вместе с фаршем обжарить его на сковороде. Картофель отварить и сделать картофельное пюре, добавив сливочное масло, соль, муку и специи по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4627,'Тщательно перемешивать продукты, чтобы масса была однородной, без комочков. По консистенции пюре должно быть густым. Охладить. Из пюре, на ладони, вылепить лепешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4627,'В середину положить фарш и завернуть лепешку, начинкой внутрь. Сформировать аккуратные круглые зразы. Разогреть сковородку и обжарить зразы из картофеля со свининой, до появления золотой корочки с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4628,'Персики опустить на минуту в кипяток и сразу в холодную воду. После этого снять с них кожицу. Порезать очищенные персики на 2 половинки, удалив косточку. Половинки разрезать на кусочки и сбрызнуть лимонным соком. Почистить апельсины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4628,'С помощью овощечистки снять с них белую мякоть. Порезать дольками. Кожуру и дольки измельчить в блендере (примерно минуту). Персики и апельсин смешать. Влить воду, насыпать сахар. Вскипятить фрукты и варить 5 минут, помешивая и убирая появляющуюся пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4628,'Варенье оставить на 6 часов остывать. Через это время опять вскипятить и проварить 5 минут. Пока ароматное персиковое варенье с апельсином не остыло, разлить его по простерилизованным банкам и укрыть герметично крышками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4861,'Мясо уложить на картофель, залить бульоном, бросить лавровый лист, разогреть духовку до средней температуры и поставить горшочки на 30-40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4630,'Выложить в форму тесто и разровнять поверхность. Поставить выпекаться на 10 минут. Сделать заливку. Для нее взбить сметану с яйцом, добавить ванилин и сахарную пудру. Взбить все миксером. Достать тесто из духовки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4630,'Вилкой примять его, чтобы получилось углубление, и положить в него ягоды. Залить заливкой. Пирог вернуть в духовку еще на полчаса. Остудить нежный финский ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4631,'Муку и маргарин растереть вместе до мелкой крошки. Добавить сметану, желтки, всыпать сахар, разрыхлитель и муку. Получившееся тесто разделить на 3 равные части. Тесто разложить по формам. Запарить горячей водой мак. Затем растереть мак с сахаром. К нему добавить яйца, масло и растереть еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4631,'Муку и разрыхлитель всыпать к маковой смеси и хорошо перемешать. Выложить маковую смесь на первый корж. На второй корж выложить курагу.  На третий корж выложить орехи. Взбить белки с сахаром до пышной крепкой пены. Полить все коржи сверху. Поставить коржи в духовку выпекаться при температуре 200 градусов, на 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4631,'Сварить заварной крем из молока, крахмала, масла, сахара. Выложить торт «Люби меня» с заварным кремом в следующем порядке: вначале маковый корж смазанный кремом, затем положить корж с курагой и снова смазать кремом. В конце накрыть коржом с орехами. Смазать верх и бока торта кремом и украсить по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4632,'Шоколад растопить на водяной бане. Намазать шоколадом изнутри формочки с помощью силиконовой кисточки. Поставить в морозилку для застывания шоколада на 10 минут. Затем формочки промазать второй раз, тщательно закрашивая все дырочки и пропуски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4632,'Делать это нужно быстро, чтобы не успел растаять первый шоколадный слой. Опять заморозить шоколад в морозилке. Растопить масло и смешать с сахарной пудрой и ванилином. Через сито протереть творог и добавить к нему остывшее масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4632,'Начинку хорошо перемешать и разложить по формочкам с шоколадом. При желании можно положить в начинку еще курагу, чернослив, орехи и другие наполнители. В формочки начинку выкладывать не до самого верха, оставляя место для слоя шоколада, который будет формировать дно сырка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4632,'Поставить формочки в морозилку на полчаса. Шоколадом нанести последний слой поверх начинки и снова поставить застывать на 20 минут. Домашние сырки в глазури лучше хранить в морозилке. За некоторое время до подачи, достать сырки из морозилки. Тогда они немного оттают.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4633,'Из указанных продуктов сделать тесто и поставить в тепло, для поднятия. Поднявшееся тесто обмять и снова оставить в тепле. Тесто обмять второй раз и раскатать в батон. Сделать на поверхности батона несколько косых надрезов острым ножом. Переложить на противень и отставить на 40 минут для расстойки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4633,'Смазать батоны яйцом, чтобы после выпекания образовалась красивая румяная корочка. Вместо яйца, смазать батоны можно также сметаной или маслом. Поставить выпекаться при 180 градусах, на 25 минут. Следить, чтобы выпечка не пригорела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4633,'Готовые батоны вынуть и для блеска смазать тонким слоем растительным маслом. Накрыть полотенцем и оставить на 15–20 минут. Тогда выпечка будет мягкая, пышная. Пышные батоны на кефире подавать к чаю как остывшими, так и теплыми, по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4634,'В эмалированную посуду положить желатин и залить холодной водой. Оставить на 40–60 минут набухать. Желатиновую массу подогреть до растворения крупинок желатина, но не кипятить. Влить к желатину сметану и сахар, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4634,'Ягоды и кусочки фруктов положить в сметанную массу и равномерно распределить, перемешивая. Перелить в силиконовую форму и поставить в холод, на несколько часов. Десерт вынуть из формы и порезать на кусочки. Сметанный десерт-желе с ягодами подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4635,'Теплое молоко и воду влить в миску и смешать с дрожжами, сахаром и солью. Дать постоять. Налить растительное масло в опару и после перемешивания всыпать муку. Вымесить. Тесто в миске накрыть хлопковым полотенцем и дать постоять час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4635,'Когда оно поднимется в 2 раза, переложить тесто на стол. Немного обмять и разделить на 9 частей. Каждую часть скатать в круглый шарик и сплющить в аккуратную толстую лепешку. Намазать мягким сливочным маслом и свернуть в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4635,'На 20 минут поставить булочки выпекаться, при 180 градусах. По истечении времени, сдобные булочки «Ачма» достать их духовки. Выложить на блюдо и подавать на завтрак или полдник теплыми. Приятного аппетита. ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4636,'Взбить с сахаром яйца до белого цвета, всыпать ванилин и разрыхлитель. Перемешать миксером на медленных оборотах. Ввести постепенно муку. Форму смазать и выложить 1/2 теста. Поставить форму с половиной теста в духовку на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4636,'Готовый корж вынуть, снова смазать форму и выпечь вторую половину теста. Остудить готовые коржи и разрезать. Сложить их стопкой и смазать любимым кремом внутри и снаружи. Украсить торт «Мечта» на бисквите по своему вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4637,'Киви и банан очистить и мелко нарезать. Смешать обе массы, размять, добавить сахарный песок и распущенный желатин. Варить 5 – 7 минут, варенье должно быть густым. Разложить ароматное варенье из банана и киви в небольшие чистые баночки, под полиэтиленовые крышки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4638,'Очистить клубни картофеля и разрезать каждый на четыре части, можно мельче, если клубни крупные. Положить в кастрюлю с кипящей водой, посолить. Варить 20 минут до готовности. Приготовить шампиньоны или другие грибы: очистить, мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4638,'Порубить репчатый лук и болгарский сладкий перец, семена удалить. Мелко порезать шинку, помидоры, натереть сыр. Слить воду от готового картофеля. Клубни нарезать и жарить на сливочном масле, маргарине или оливковом масле, до зарумянивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4638,'Картофель выложить. В той же сковороде обжарить овощи и шинку в течение 8 – 10 минут. Вернуть картофель в сковороду и посыпать блюдо рубленым или давленым чесноком. Взбить яйца, посолить, поперчить. Залить ими овощную массу на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4638,'Прогревать 20 минут на тихом огне. Можно поставить на гриль на 3 минуты. Убрать блюдо с огня, посыпать тертым сыром и снова прогреть, чтобы сыр расплавился. Подавать картофельную фриттату с овощами горячей, порезав на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4639,'Охлажденное сливочное масло порезать кубиками, смешать с просеянной мукой, разрыхлителем и сахарным песком. Добавить воду и яйцо, хорошо вымесить. Тесто раскатать в лепешку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4639,'Выложить в смазанную маслом форму так, чтобы получились высокие бортики. Наколоть вилкой в нескольких местах. Поверх, выложить бумагу для выпечки, наполнить фасолью или горохом, печь 10 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4639,'Для начинки, смешать творог со сливками и сахаром, взбить. Добавить яйца, перемешать до однородного состояния. С готового коржа удалить бумагу и горох. Груши порезать дольками и выложить на готовый корж.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4639,'Залить творожной смесью, посыпать сверху ягодами (черной смородины, ежевики, черники или голубики). Печь 40 минут при 200 градусах. Остудить, выложить на блюдо. Готовый и остывший творожный грушево-ягодный пирог нарезать порционно и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4640,'Очистить от кожицы и семян и мелко нарезать зеленое яблоко, измельчить в блендере. Натереть свежий очищенный имбирь. Подготовить морковный и апельсиновый соки с мякотью, добавить чайную ложку меда. Все смешать, взбить. Апельсиново-морковный смузи с яблоком разлить по бокалам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4641,'Смешать воду, белое вино и сахар, прогреть на тихом огне в небольшой кастрюле. Сахар должен полностью раствориться. Абрикосы разрезать на половинки, всыпать в смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4641,'Варить примерно 1 минуту, затем добавить ванилин из пакетика и листочки мяты. Тушить еще 4 минуты. Подать десерт «Пьяные абрикосы» с мороженым или йогуртом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4642,'Репчатый лук нарезать и обжарить на сливочном масле в течение 4 – 5 минут. Добавить нарезанный чеснок, жарить еще полминуты. Влить смесь сливок и молока, посыпать специями, положить веточки тимьяна, лавровый лист. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4642,'Всыпать очищенный и порезанный картофель, довести до кипения, варить 15 минут на среднем огне до готовности картофеля. Тимьян и лавровый лист удалить, переложить картофель с соусом в форму, посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4642,'Печь картофель, до образования золотистой корочки, в течение 20 минут. Подавать золотистый картофель под сыром в теплом виде, порционно разложив по тарелкам. Присыпать по желанию зеленью и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4643,'В кастрюлю с толстым дном выложить очищенные крупные куски белокочанной капусты. Порезать кубиками картофель, кабачки. Выложить поверх капусты. Не перемешивать. Полить сверху растительным маслом. Накрыть крышкой, варить 5 – 7 минут на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4643,'Отдельно измельчить репчатый лук и натереть морковь. Нарезать кубиками спелые помидоры. Обжарить на растительном масле лук и морковь в течение 3 – 4 минут, затем добавить помидоры и тушить еще 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4643,'Обжарку добавить в кастрюлю с капустой. Соль, перец – по вкусу, можно влить немного горячей воды. Тушить на тихом огне под крышкой до готовности, около 10 минут. Классическое рагу из овощей подавать порционно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4644,'Два литра красного виноградного сока варить 2 – 3 часа, постепенно всыпая сахар. Остудить получившийся кисель до теплого состояния. На плотную, крепкую, нитку нанизать половинки или четвертинки очищенного грецкого ореха.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4644,'Связка должна получиться примерно 20 см длиной, на конце сделать петельку. В теплый кисель добавить муку или смесь муки с крахмалом, перемешать, чтобы не было комочков. Прогреть на тихом огне в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4644,'Огонь выключить, макать в кисель связки орехов по 3 раза, с перерывом в 5 минут, можно больше. Повесить для просушки на 2-3 дня в хорошо проветриваемое помещение. Готовую домашнюю грузинскую чурчхелу можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4645,'Взбить яйца с сахарным песком. Добавить молоко, соль по вкусу, влить смесь в размягченное сливочное масло. Перемешать венчиком или миксером. Всыпать просеянную муку, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4645,'Тесто должно быть мягким, но не должно липнуть. Раскатать на посыпанном мукой столе, сложить вчетверо. Процедуру повторить. Поставить в холодильник на 40 минут. Затем разделить на несколько частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4645,'Посыпать каждую сахаром, сложить друг на друга. Раскатать стопку пластов в лепешку продолговатой формы. Длинные стороны завернуть к середине, оставив в середине щель в 2 см. Еще раз посыпать сахаром, сложить пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4645,'Нарезать кусочками по 1 – 1,5 см. Выложить домашнее печенье «Ушки» на смазанный маслом противень, печь в духовке 15 минут при 220 градусах. Готовое печенье подать на завтрак и кушать с любимым напитком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4646,'Некрупный картофель очистить. Сверху и снизу клубней сделать срезы так, чтобы они устойчиво стояли. Ножом кривой формы вырезать массу изнутри, чтобы остались тонкие стенки и донышко. Клубни перед обжариванием должны быть сухими, можно обсушить бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4646,'Жарить во фритюре из растительного масла, до золотистого цвета. Выложить на бумагу, чтобы удалить излишки жира. Мелко порубить репчатый лук. Обжарить его на растительном масле до румяного цвета. Добавить смесь говяжьего и бараньего фарша, специи. Обжарить, помешивая, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4646,'Всыпать орешки пинии или кедровые. Нафаршировать полученной массой картофель. Для приготовления соуса смешать томатное пюре и острый томатный соус, рубленый чеснок, зелень кинзы и базилика, мяту, молотую куркуму. Налить воду, смесь немного взбить венчиком. Налить готовый соус в сотейник, дать закипеть и добавить соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4646,'В другом сотейнике поставить плотно друг к другу фаршированные чашечки из картофеля. Подлить томатный соус со специями, прогреть до закипания. Огонь убавить, тушить под крышкой примерно 15 – 20 минут. Традиционный батата махши можно подать с натуральным йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4647,'Куриное филе разрезать на две части и немного отбить. Посолить, поперчить, сбрызнуть свежим лимонным соком. Сложить в посуду и оставить на 20 минут для маринования. Приготовить начинку. Мелко нарезать лук, раздавить или порубить чеснок. Смешать лук с чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4647,'Добавить размятый сыр фета. На каждое филе выложить сырную начинку и свернуть рулетами. Сколоть края рулетов зубочистками. Разогреть на сковороде растительное масло. Обжарить в масле стручок перца чили и целые чесночные дольки, затем их выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4647,'Обжарить на этом же масле куриные рулеты, по 3 минуты с каждой стороны. Выложить в форму для запекания или любую жаропрочную посуду. Посыпать тертым сыром и печь при 190 градусах, в течение 20 – 30 минут. Рулеты из куриной грудки с сыром фета готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4648,'Мясо по-ирландски готовится из фарша без котлетных добавлений. Солить и перчить фарш не нужно, это сделать в самом конце. Мясной фарш лучше выбирать говяжий или из телятины, чтобы было меньше жира. Хорошо перемешать и отбить мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4648,'Основа должна быть плотной. Разделить весь фарш на большие котлеты. Ломтики бекона разделить на длинные полоски. Этими полосками следует завернуть все колеты, чтобы мясо было закрытым. Полить котлеты растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4648,'Сковороду раскалить и налить не много растительного масла. Затем обжарить мясные котлеты в беконе (10 минут), до золотистой корочки. Ирландский рецепт предполагает немного недожаренное мясо, чтобы серединка котлет была розового цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4648,'Если вы не уверенны в качестве фарша, тогда, обжаренные котлеты стоит завернуть в фольгу и довести до готовности в духовке, в течение 20-30 минут. Мясо в беконе по-ирландски подавать на тостах или на ломтиках обжаренного хлеба.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4649,'Для приготовления печени по-словенски необходимо кусок печени очистить от пленки и прожилок, хорошо промыть и просушить. По всему куску сделать надрезы вдоль. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4649,'Дно, приготовленной формы для запекания, выложить тонкими ломтиками лимона и веточками петрушки. Затем положить печень. Сверху выложить опять ломтики лимона и петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4649,'В противень налить воду, наполовину заполнив до краев. Духовку разогреть до 200 градусов и поставить противень с печенью. Выпекать 30 минут на сильном огне, затем газ уменьшить и готовить еще 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4649,'Проверить готовность печени ножом, если не вытекает сукровица, значит, запеченная печень по-словенски готова. Подавать печень порционно, с любимым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4650,'Для приготовления лоци печене необходимо разделить корейку на порционные куски, разрезав мясо вдоль по костям. Ребра следует хорошо зачистить, а мясо отбить для сочности и мягкости. Затем натереть мясо смесью из соли, паприки, черного перца и чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4650,'На раскаленной сковороде обжарить ароматные отбивные на растительном масле, до румяной корки. Затем мясо следует завернуть в фольгу и запечь в теплой духовке (не больше 100 градусов), примерно  50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4650,'В сковороду, где жарилось мясо, выложить лук, порезанный полукольцами. Пассировать лук до мягкости. Домашнее лоци печене подавать, посыпанное свежей зеленью и пассированным луком. Отличным гарниром к блюду будут жареные овощи и свежий салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4651,'Для приготовления котлет необходимо тщательно вымесить свино-говяжий фарш и немного отбить его о стол. Очистить картофель и измельчить в сырое пюре. Добавить в фарш. Лук очистить и измельченный также добавить в фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4651,'С белого хлеба срезать корочку и замочить мякиш в молоке (или воде). Затем вместе с молоком добавить к мясному фаршу. Посолить и поперчить по вкусу. Вымешивая фарш добавить яйцо и очень тщательно взбить все ингредиенты в фарше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4651,'Для вкуса добавить 1 чайную ложку не острой горчицы. Затем отставить фарш на 10-15 минут, отдохнуть. Раскалить сковороду и влить растительное масло. Мокрой рукой взять шарик фарша и сформировать круглую котлету.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4651,'Затем обвалять ее немного в муке и выложить на горячую сковороду. Обжарить одну сторону котлет до румяной корочки, затем перевернуть, убавить газ и накрыть сковороду крышкой. Так они потушатся. Готовые мясные котлеты с картофелем подавать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4652,'Для приготовления маринада необходимо смешать жидкие ингредиенты и добавить давленый чеснок, соль, приправы и мелко нарезанную зелень. Курицу натереть этой смесью, тщательно смазывая внутреннюю часть, внутрь положить 2 лавровых листа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4652,'Затем скрепить все части курицы нитками или зубочистками. Поместить курицу в маринаде в пакет для запекания или фольгу и оставить напитываться на всю ночь. Утром всю курицу поместить на противень и накрыть фольгой для запекания. Запекать на медленном огне 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4652,'Сняв фольгу, увеличить газ в духовке и оставить курочку еще на 40 минут. Следить за тем, чтобы не пригорела. Золотистую и ароматную курицу в пряно-чесночном маринаде, подавать с овощным салатом или запеченными овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Порезать грибы на пластинки, потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4653,'Для приготовления салата из рукколы и куриной печени необходимо обжарить свежие шампиньоны на растительном масле, с добавлением уксуса и горчичного семени. Готовые грибы выложить на тарелку и отставить. Печень хорошо промыть и обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4653,'В конце жарки влить ложку коньяка и довести до кипения. Соединить жареную печень с грибами. Листья рукколы вымыть и высушить. Выложить на презентационную тарелку, сверху положить теплую печень и грибы. Полить салат из рукколы и куриной печени соусом, оставшимся после жарки печени и грибов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4654,'Чтобы домашние колбаски были в меру жирными, необходимо брать 3/4 свинины и 1/4 говядины (или баранины), от всего количества мяса. Все мясо нарезать на очень мелкие кусочки, примерно 1х1 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4654,'В мясо добавить мелко нарезанный лук и пропущенный через пресс чеснок. Посолить и поперчить по вкусу, также приправить уцхо-сунели. Кишки для колбасок очень хорошо промыть и набить мясным фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4654,'Набивать кишки легче при помощи специальных насадок или использовать любую воронку. Плотно набить кишки фаршем и проколоть иголкой по всей колбаске, чтобы она не порвалась во время жарки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4654,'На раскаленную сковороду, смазанную маслом, положить домашние колбаски и жарить не меньше 45 минут под крышкой. Готовые колбаски наполнят ароматом комнату и пригласят за стол всех членов семьи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4655,'Перед приготовлением пирога с абрикосами необходимо нагреть духовку до 200 градусов. Спелые абрикосы очистить от косточек, разделив плоды на 2 половинки. Яйца взбить с сахаром в крепкую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4655,'В яичную смесь добавить соль, растопленное масло и йогурт. Размешать деревянной лопаткой, аккуратно, чтобы не повредить пышность. В муку добавить ванилин и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4655,'Всыпать в тесто муку, аккуратно размешивая лопаткой, по консистенции тесто будет жидким. Форму для выпекания смазать маслом и застелить пергаментной бумагой. Вылить тесто в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4655,'Выложить половинки абрикос сверху, немного утопив в тесто. Поставить в духовку форму на 40 минут. Готовый пирог имеет золотистую корочку и пышную мякоть. Пышный абрикосовый пирог можно подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4656,'Для приготовления блюда из кабачков необходимо приготовить яичный омлет, которым следует залить основу из кабачков и лука. Взбить миксером яйца с молоком и сметаной, добавить тертый сыр, муку и специи. Молодые кабачки порезать тонкими колечками, лук мелко покрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4656,'В форму для запекания выложить кабачки, посыпать зеленым луком и залить яичной смесью. Выпекать 20 минут в духовке, до появления румяной корочки. Лук в блюде не имеет специфического аромата, поэтому смело кушайте в любое время суток. Запеченные в омлете кабачки разложить порционно, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4657,'Изюминкой этой легкой закуски являются солоноватые крекеры. Слои из, когда то хрустящего печенья, отлично сочетаются с другими ингредиентами салата. Слоеный салат необычного приготовления заслужит внимание каждой хозяйки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4657,'Первым слоем в салате идут крекеры. Их засыпать вареным тертым яйцом и мелко порезанным зеленым луком. Смазать майонезом. Следующий слой – крекеры, сверху — мелко порезанные крабовые палочки. Снова майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4657,'Затем опять крекеры и тертый сыр, смазанный майонезом. Верх салата уложить крекерами и промазать майонезом, не пропуская бока салата. Присыпать оригинальный салат с крекерами рубленой зеленью. По желанию украсить красной икрой, тертым желтком или свежим огурцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4658,'Грецкие орехи очистить от скорлупы и измельчить ядра. Соединить вареную сгущенку и мягкое масло, всыпать измельченные орехи. Лаваш раскатать и нанести слоем начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4658,'Затем скатать плотным рулетом, начиная с короткой стороны. Подавать ореховый десерт в лаваше, нарезав на порционные кусочки.  ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4659,'Этот салат слоеный, каждый слой необходимо промазывать майонезом. Первый слой – вареный картофель, натертый на крупную терку. Для вкуса картофель немного полить маслом из шпрот. Затем выложить слой шпрот, размятых в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4861,'На стол поставить мясо в горшочках по-скандинавски, а рядом глубокую тарелку, чтобы при желании можно было переложить в нее блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4659,'Посыпать тертым вареным яйцом, по желанию соединить с давленым чесноком. Завершающий слой – тертый сыр. Промазать салат майонезом сверху и украсить. Весь салат – это пруд, из которого торчат рыбьи хвостики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4659,'Для этого хвостики нескольких рыбешек воткнуть в середину салата, плавником вверх. По бокам салата разложить веточки зелени, из вареного яйца соорудить кувшинку, из зеленого лука сделать камыши. Салат слоеный «Рыбки в пруду» готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4660,'Для приготовления волованов со свеклой и сельдью необходимо раскатать слоеное тесто в одном направлении и нарезать острым ножом на квадраты со стороной 10 см. Затем взять половинки таких же квадратиков из теста и уложить на целые, сформировав звездочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4660,'Противень застелить бумагой для выпечки, духовку разогреть до 200 градусов. Аккуратно выложить на расстоянии друг от друга формы из теста, смазать сверху желтком. Выпекать до золотистого цвета, примерно 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4660,'Свеклу отварить до готовности и остудить. Натереть на средней терке, добавить чеснок по вкусу и майонез. В остывшие волованы вложить ложку свеклы и украсить кусочками соленой сельди (предварительно удалить кости). В серединку закуски вложить веточку петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4661,'Для приготовления салата необходимо очистить кабачки от кожуры и семян и натереть на терке для корейской моркови. Это касается только старых плодов с твердой кожурой и семечками. Если кабачки молодые, кожуру снимать не обязательно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4661,'Морковь очистить и натереть как кабачки, лук порезать маленькими кубиками. Все подготовленные овощи сложить в одну миску. Смешать специи, давленый чеснок, масло, уксус и добавить к овощам. Разложить салат по стерильным, полулитровым баночкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4661,'Для стерилизации взять высокую кастрюлю и застелить дно полотенцем. Выставить банки с салатом на дно кастрюли и налить воды по высоте салата в банках. Стерилизовать 30 минут. Салат «Корейский кабачок» на зиму закатать и укутать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4662,'Для приготовления баклажанов необходимо очистить овощи от кожуры и порезать на небольшие дольки. Сложить баклажаны в миску и посыпать солью. Отставить на 30 минут. В это время очистить от семян сладкий перец, лук очистить от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4662,'Нарезать овощи тонкими полосками и сложить в высокую кастрюлю или большую миску. Баклажаны под солью пустили сок. Его необходимо слить и отжать овощи. Обжарить баклажаны на растительном масле. Чем больше сока отожмете, тем меньше масла понадобится для жарки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4662,'Теперь следует соединить свежие овощи с жареными баклажанами. Добавить давленый чеснок, специи для корейской моркови и сбрызнуть уксусной заправкой. Украсить овощной салат «Баклажаны по-корейски» веточками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4663,'Для приготовления горячих бутербродов следует выбирать тостовый белый хлеб или уже порезанный батон. Тогда зажаренная корочка будет приятно хрустеть. Сыр и помидоры нарезать ломтиками. На ломтик белого хлеба нанести сетку майонеза и положить ломтик сыра, сверху кружок помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4663,'Если сыр пресный, тогда нужно посолить для вкуса помидор или посыпать приправами. Выпекать в предварительно разогретой духовке примерно 10 минут или 3 минуты в микроволновке, пока сыр не расплавится. Горячие бутерброды с сыром и помидорами посыпать свежей зеленью и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4664,'Для приготовления салата порезать куриное филе на небольшие кусочки и обжарить на растительном масле до румяной корочки. Морковь почистить и натереть на крупной терке. Сладкий перец порезать очень тонкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4664,'Теплую курицу соединить со свежими овощами и добавить давленый чеснок и сметану. Аккуратно перемешать. Теперь необходимо добавить ту самую изюминку — веточку ароматной травы тимьян. Подать к столу ароматный и сытный, теплый салат с курицей и овощами в сметане.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4665,'Вкус шашлыка из рыбы зависит от маринада, в котором пробудут морепродукты 2 часа. Для его приготовления необходимо измельчить чеснок с листьями розмарина. Отжать сок лимона и измельчить цедру. Все смешать с оливковым или растительным маслом, солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4862,'Надрезать крестообразно шкурку окорока, присыпать смесью соли и перца, равномерно по всей шкурке воткнуть бутончики гвоздики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4665,'Белую рыбу с плотной мякотью, желательно с минимумом костей, порезать на небольшие кусочки. Очистить креветки и положить в маринад вместе с кусочками рыбы. Нанизать кусочки рыбы на веточки, чередуя креветками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4665,'Жарить на мангале или на гриле 4 минуты. Рыба готовится очень быстро, поэтому необходимо следить за тем, чтобы готовое мясо не порвалось на шампурах. Подавать рыбные шашлыки с креветками с запеченными овощами, украсив ломтиком лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4666,'Кусок шейной части свинины необходимо замариновать в соусе на 2 часа. Для маринада необходимо выдавить из лимона сок, помидоры пожать руками, лук порезать полукольцами. Соединить подготовленные ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4666,'Добавить соль и перец. Сок лимона можно заменить сухим белым вином, но в этом случаем можно потерять лимонный аромат в блюде. Свинину, маринованную в соусе, выложить на фольгу и обложить овощами из маринада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4666,'Закрыть плотно мясо фольгой. Поставить свиную шейку с овощами в фольге в духовку на 1 час. Запекать при температуре 180 градусов. Чтобы мясо не пригорало, и было сочным, следует добавить в противень 0,5 стакана воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4666,'В конце запекания, раскрыть аккуратно фольгу и оставить запекаться мясо еще на 10 минут. Готовое мясо порезать на порционные кусочки. Выложить свиную шейку с овощами на блюдо, украсить запеченным картофелем и присыпать зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4667,'Ленивые голубцы готовятся в несколько этапов. Сначала необходимо потушить капусту – главный ингредиент в блюде. Для этого обжарить лук и морковь на растительном масле, затем добавить нашинкованную мелко капусту. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4667,'Тушить до готовности. В конце посыпать мелко нарезанной зеленью. Сырой фарш соединить с вареным рисом и тушеной капустой, посолить и посыпать приправами, специями. Сформировать небольшие котлетки и обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4667,'Можно выложить на противень, смазанный маслом и запекать в духовке 40 минут. На ленивые голубцы можно вылить приготовленную томатную обжарку и томить в подливе. Сочные «Ленивые» голубцы по-домашнему подавать порционно, со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4668,'Салат «Капрезе» с бальзамическим уксусом готовится очень просто. Необходимо нарезать кружками помидор и сыр моцарелла. Стоит учитывать, что помидоры лучше выбирать одинаковых размеров относительно сыра, чтобы в салате была красивая пропорция.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4668,'Для приготовления заправки необходимо смешать оливковое масло, уксус, пряности, специи. Выложить сыр, через один, с помидорными кружками. По блюду разложить литья базилика и все полить ароматной заправкой. Салат «Капрезе» с сыром моцарелла готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4669,'Чтобы приготовить яблочный пирог за несколько минут, необходимо очистить 5-6 яблок от кожуры и нарезать небольшими дольками. Затем замесить тесто. Яйца взбить блендером с сахаром. Добавить к яйцам растопленное масло или маргарин, мед и муку, смешанную с содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4669,'Замесить нежное тесто, по консистенции немного гуще сметаны. Соединить с яблочными дольками. Выложить массу в подготовленную форму, смазанную маслом. Духовку следует предварительно разогреть до 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4669,'Выпекать яблочный пирог при температуре 170-180 градусов до золотистой корочки. Яблоки очень любят корицу, поэтому можно добавить эту специю на кончике ножа в тесто или смешать с сахарной пудрой и посыпать уже готовый пирог. Яблочный пирог на меду можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4670,'Чтобы приготовить тесто для пышной пиццы, необходимо растворить сухие дрожжи в теплой воде и дать им постоять. Чтобы быстрее прошла реакция можно добавить в воду чайную ложку сахара. Муку просеять и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4670,'Влить разведенные дрожжи и оливковое масло (можно растительное рафинированное). Вымесить очень мягкое и послушное тесто, оно должно отлипать от рук. Затем тесто оставить отдыхать на час, накрыв чистым полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4670,'Подошедшее тесто разделить на 3-4 части. Раскатать одну часть и выложить в смазанную маслом форму. Теперь выложить начинку. Для начала необходимо смазать тесто томатным соусом и положить нарезанные томаты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6319,'Салат из цветной капусты с помидорами и сыром под сметанным соусом украсить зеленью и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4670,'Затем выложить резаную колбасу, жареные грибы и отварное мясо. Присыпать измельченным свежим сладким перцем и зеленью. По желанию положить морепродукты. Притрусить обильно начинку тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4670,'Разогреть духовку и поставить пиццу для запекания, на 20 минут. За это время сыр расплавится, и пышная домашняя пицца приобретет замечательный золотистый оттенок. Готовую пиццу нарезать на кусочки и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4671,'Главной особенностью этого пирога является крошка, которой необходимо уделить особое внимание. Для ее приготовления, нужно смешать все сухие ингредиенты и соединить их с растопленным сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4671,'Затем всю смесь хорошо растереть руками. Отложить крошку в сухую посуду и пока отставить. Яблоки необходимо очистить от кожуры и порезать тонкими дольками, затем сбрызнуть соком лимона, чтобы они не потемнели. Приготовить наливное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4671,'Для этого необходимо взбить мягкое масло с сахаром, затем ввести яйцо и продолжить взбивать. В просеянную муку добавить соль и разрыхлитель. В муку влить масляную смесь и вымешивая, разбавлять тесто теплым молоком. Подготовить форму для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4671,'Смазать ее сливочным маслом. Вылить все тесто в форму и высыпать сверху яблоки. Притрусить крошкой пирог и поставить в духовку на 40 минут, запекать при температуре 180 градусов. Проверить готовность спичкой. Французский пирог с крошкой подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4672,'Приготовить маринад. Измельчить  зубчик чеснока. В кастрюле смешать кефир, чеснок, травы, перец и соль. Куриные бедра положить в маринад на 20–30 минут. Порезать на дольки картофель. Выложить его в форму для запекания и полить оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4672,'Посыпать сверху травами и посолить. Оставшийся чесночный зубчик раздавить ребром ножа и тоже выложить на картофель. Разрезать на 4 части помидоры черри и выложить их в форму поверх картофеля. На овощи выложить бедра и полить сверху маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4672,'Поставить форму с курицей в духовку, нагретую до 200 градусов. Куриные бедра в чесночно-кефирном маринаде будут готовы через 40 минут. Готовые куриные бедра разложить по тарелкам и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4673,'Лук нарезать полукольцами или кубиками. Обжарить в масле до золотого цвета. Печень порезать на кусочки и выложить на сковородку к луку. Обжарить лук и печенку вместе в течение 5 минут. Плавленый сыр выложить на сковородку и дать ему расплавится до жидкого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4673,'Постоянно помешивать, пока он не разойдется полностью. Добавить на сковородку воды, соль, перец и лавровый лист. Убавить огонь и оставить сковородку с блюдом тушиться еще 15 минут. Сочную куриную печень в сырном соусе можно подавать с гарниром из картофельного пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4674,'Замочить желатин в половине стакана холодной воды, на 20 минут. В глубокой миске перемешать кефир и сметану. Влить к кефиру мед и венчиком взбить до полного растворения. Нагреть разбухший желатин на слабом огне, непрерывно помешивая. Дать ему растворится и после этого остудить. Остывший желатин влить в кефирную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4674,'Добавить ванилин и цедру, перемешать. Треть смеси перелить в другую емкость и смешать ее с вишневым сиропом. Взбить до однородности. В прямоугольную форму налить кефирную смесь белого цвета тонким слоем. Поставить в холодильник для застывания на 15 минут. Затем, на застывшую белую смесь налить слой розовой смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4674,'Снова поставить в холодильник. Чередуя цвета залить форму, полностью. Между слоями ставить форму на 15 минут в холодильник. Полностью заполненную форму оставить на 1 час в холодильнике. Готовое кефирное желе перевернуть на блюдо и порезать на ломтики средней толщины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4675,'Измельчить печенье до мелкой крошки и смешать с мягким сливочным маслом. Положить в разъемную форму, на дно, бумагу для выпечки или пищевую пленку. Печенье выложить в форму ровным слоем и плотно утрамбовать ложкой. Убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4675,'Слить сироп с консервированных персиков и перемолоть их в пюре блендером. Персиковый сироп поставить в микроволновку и подогреть. Растворить в нем желатин (лучше быстрорастворимый) и разделить на 2 части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'В кастрюлю влить томатный соус и бульон, довести до кипения, потом переложить туда на 10 минут подготовленные фрикадельки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4675,'Растереть творожную массу до исчезновения комочков. и перемешать с взбитыми сливками. Затем добавить одну часть желатинового сиропа. Вторую часть желатинового сиропа соединить с персиковым пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4675,'В форму, на корж, выложить ровным слоем творожную смесь. Сверху, ровным слоем персиковое пюре. Торт убрать на ночь в холодильник. Перед подачей на стол, персиковый торт с творогом без выпечки вынуть из формы, освободить от пленки и украсить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4676,'Порезать огурец на половину и затем на пластики Помидоры нарезать на половинки (если крупные, то на четвертинки). Салат порвать руками на некрупные кусочки. Яйца отварить и разрезать на 4 части. Порезать крупными кубиками сыр. Мясо с окорока также порезать кубиками и обжарить до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4676,'На прямоугольное блюдо выложить все продукты рядами. При этом огурцы и салат выложить с краю тарелки, а остальные продукты уложить произвольно, но так, чтобы цвета не слились. Ингредиенты для заправки смешать и полить сверху продукты на блюде. Классический «Кобб-Салат» подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4677,'Венчиком взбить яйца с сахаром. Добавить к ним мед, сливочное масло и соду. Поставить яично-медовую смесь на водяную баню и прогреть, помешивая, до растворения сахара. Смесь убрать с огня и добавить 400 г муки или чуть больше. Размешать тесто и накрыть его пленкой на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4677,'Через час тесто вынуть и замесить, подсыпав оставшуюся муку. Чтобы тесто не липло к рукам, смазывать их периодически маслом. Тесто разделить на 9–12 комочков. Каждую часть теста тонко раскатать на бумаге для выпечки, присыпанной мукой. Проткнуть коржи вилкой в нескольких местах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4677,'Выпекать коржи около 2–3 минут при температуре 200 градусов. Сгущенное молоко взбить со сметаной и медом. Сливки взбить и аккуратно соединить со сгущенным молоком. Промазать коржи кремом и сложить в стопку. Торт медовый «Пчелкин дом» убрать в холодильник на ночь. Украсить на свой вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4678,'Куриный фарш положить в миску и смешать с яйцом, тертыми яблоками и измельченным луком. Посолить и хорошо вымесить фарш. Бекон нарезать тонкими полосками. Сформировать котлеты и обернуть каждую полоской бекона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4678,'Сковороду разогреть с 2 ст. л. масла. Огонь убавить до среднего. Выложить котлеты и обжарить их по 10 минут с каждой стороны. Котлеты из курицы и яблок в беконе подать с любимым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4679,'Яйца взбить, всыпать к ним сахар и снова взбить. Влить в яичную смесь молоко и варенье. Просеять муку. Добавить ее вместе с содой к остальным продуктам. Из теста выпечь 2 коржа. Температура духовки 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4679,'В это время сметану взбить вместе с сахарной пудрой. Коржи разрезать на 2 слоя каждый. Выложить друг на друга, промазав каждый кремом. Украсить по своему желанию. Оставить в холодильнике для пропитывания. Быстрый торт на сметанном креме готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4680,'Капусту брокколи разобрать на отдельные соцветия. От белой луковицы лука-порея отрезать 2 кусочка. Картофель почистить. Овощи кинуть в кипящую воду и отварить в течение 15–20 минут. Бульон оставить в кастрюле, а овощи вынуть и измельчить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4680,'Овощное пюре разбавить бульоном и сливками. Полезный сливочный суп из брокколи посолить, поставить на плиту и варить до первых пузырьков. Готовый суп разлить по тарелкам и кушать. По желанию присыпать измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4681,'На водяной бане или в микроволновке растопить шоколад.  Если клубника крупная, то разрезать ее пополам. Положить клубнику по одной штучке в формочки для льда. Залить в формочки шоколад и поставить в морозильник на 5 минут. Как только шоколад застынет, десерт «Шоколад с клубникой» готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4682,'Муку просеять на стол и собрать в горку. В центре горки сделать углубление, влить в него оливковое масло, насыпать соль и дрожжи. Влить аккуратно воду и замесить мягкое, эластичное, нелипкое тесто. Из теста сформировать шар и, переложив его в миску, накрыть полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4682,'Оставить в тепле на 2–3 часа. Для начинки нарезать грибы кубиками, перец кольцами, ветчину на полоски. Если используется сыр моцарелла, то ее порезать на пластинки, а если твердый сыр, то его натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'Когда пройдет отведенное время, засыпать вермишель и готовить  5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4682,'Когда тесто подойдет, раскатать его на пергаментной бумаге, оставив чуть более толстыми бортики, и перенести вместе с бумагой на противень. Намазать тесто томатной пастой, сверху нанести соус табаско. Выложить на пиццу ветчину, помидоры, грибы и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4682,'Сбрызнуть овощи оливковым маслом. Выложить оливки и сыр. В нагретую до 180 градусов духовку поставить противень с пиццей, на полчаса. Когда домашняя пицца с пармской ветчиной будет готова, нарезать ее на сегменты, украсить свежей зеленью и подать горячей на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4683,'Творог перетереть с яйцами, сахаром и манкой. Добавить ванилин и перемешать тесто. Шоколад для начинки поломать на кусочки. Из теста сделать лепешку, в центр положить шоколадный кусочек и слепить края. Сформировать круглую форму сырника. Сырники обвалять в овсяных хлопьях и пожарить до светло-золотистого цвета. Сырники с начинкой в овсяной панировке можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4684,'Размять в миске банан в пюре, с помощью вилки. Добавить к банану творог и сахар. Вбить яйцо. Все смешать, добавить манку или муку. Замесить тесто и слепить из него сырники. На сковородке с растительным маслом обжарить нежные банановые сырники с двух сторон. Подать на завтрак или в качестве перекуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4685,'Налить в миску полстакана холодной воды. Вбить в воду яйцо и взбить, добавив соли. Из яичной смеси и муки замесить тесто. Перекрутить творог на мясорубке и смешать с сахаром и желтком. Добавить к творожной массе мягкое сливочное масло и соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4685,'Тонко раскатать на столе тесто. Вырезать из него кружочки при помощи стакана. Смазать их взбитым белком и в центр выложить немного начинки из творога. Края кружком соединить и фигурно защипнуть. Вскипятить воду в кастрюле и подсолить ее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4685,'Опустить вареники в кастрюлю и варить. Когда они всплывут, вынуть вареники шумовкой и переложить в салатник. Полить простые вареники с творожной начинкой растопленным маслом. Можно подавать со сметаной или вареньем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4686,'Лук и яблоко почистить и измельчить (можно натереть на терке). Фарш смешать с яблоком и луком, вбить яйцо и всыпать манку, добавить соль и перец. Перемешать фарш и оставить на пару часов для разбухания манки. Сформировать из фарша котлетки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4686,'Можно выложить фарш в маленькие формочки для маффинов. Поместить котлеты в духовку на 30 минут. В это время, для заливки смешать горчицу, сметану, соль и перец. Для цвета можно положить немного томатной пасты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4686,'За 5–7 минут до готовности котлет, смазать их заливкой и посыпать сверху тертым сыром. Куриные котлетки с зеленым яблоком подавать на стол горячими, с любимым гарниром. Идеально подойдут на гарнир свежие овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4687,'С помощью картофелечистки нарезать огурцы на длинные полоски. Копченый лосось и зелень мелко порезать. Ингредиенты для начинки перемешать. На полоску огурца выложить начинку и свернуть рулетом. Скрепить ролл зубочистками. Выложить огуречные роллы с копченым лососем на блюдо и украсить креветками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4688,'При помощи картофелечистки или ножа для сыра нарезать огурцы на длинные ломтики. Отварные яйца и зелень укропа мелко порезать. Все ингредиенты хорошо перемешать. На ломтик огурца выложить начинку и завернуть в рулет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4688,'Скрепить ролл шпажками для коктейлей или зубочистками. Выложить огуречные роллы с яйцом на блюдо и украсить целыми креветками. Для украшения можно еще использовать крупинки красной икры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4689,'При помощи ножа для сыра нарезать огурцы на длинные тонкие ломтики. Сладкий лук, зелень укропа и очищенный авокадо мелко порезать. Сыр натереть на терке. Смешать ингредиенты для начинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4689,'На ломтик огурца выложить начинку и завернуть в рулет. Скрепить ролл шпажками для коктейлей. Выложить огуречные роллы с авокадо и сыром на блюдо и украсить целыми креветками. Роллы можно кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4690,'Раскатать тонко тесто для пиццы в круг. Смазать сверху томатным соусом и посыпать сыром. Запечь пиццу в духовке при 400 градусах. Готовую пиццу разрезать на 8 ломтиков и сверху на нее положить тонкие ломтики салями. Смазать края пиццы оливковым маслом. Домашняя пицца «Милано» готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'Далее положить цуккини и фасоль, продолжать варить 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4691,'Порезать на небольшие кусочки свинину. Смешать мясо с порезанным луком и чесноком. Добавить соль и остальные приправы, влить соевый соус. Оставить мясо мариноваться, не менее часа, а лучше на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4691,'Противень смазать маслом. Мясо выложить на противень и запечь при 200 градусах. Когда сочная свинина по-корейски подрумянится, перевернуть и запечь другую сторону. Подать порционно с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4692,'Смешать воду с дрожжами и всыпав по 1 ст. л. сахара и муки, замесить опару. Отставить на 10 минут. В глубокой миске просеянную муку смешать с теплым молоком, опарой и растопленным сливочным маслом. Добавить сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4692,'Тесто убрать в тепло на 1,5 часа. Когда оно увеличится вдвое, обмять его и оставить в тепле еще на 30–40 минут, для второго подъема. Разделить тесто на 2 половины. Раскатать каждую половину толщиной 1 см в круг. Переложить круги на противень с пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4692,'Для начинки порубить зелень. Смешать ее с солью, перцем и творогом. Разобрать на волокна куриное филе. Сыр натереть на крупной терке. На каждый круг из теста посыпать немного манки, чтобы тесто не размокло от начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4692,'Выложить равномерно творог с зеленью, разложить филе. Сверху посыпать пиццу сыром. Поставить деревенскую пиццу с творогом и зеленью в духовку и запечь при 200 градусах, до румяного цвета. Готовую пиццу нарезать кусочками и кушать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4693,'Вскипятить подсоленную воду. Брокколи опустить в воду и варить 5 минут. Воду слить и залить брокколи ледяной водой. Вынуть капусту и дать стечь воде. Включить на 200 гр. духовку. Яйца взбить, влить сливки и молоко. Взбить еще раз. Добавить горчицу и снова взбить смесь. Просеять муку, соль, специи и перемешать с яичной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4693,'Положить в тесто 2/3 сыра. Форму смазать маслом. Капусту выложить в форму, сверху налить заливку. Сыр посыпать равномерно на запеканку и убрать форму в духовку на 30–40 минут. Готовую запеканку разложить по тарелкам. Брокколи, запеченную под сыром, подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4694,'Порезать рыбу на кусочки и обжарить на сковороде. Осторожно выложить ее в форму, посыпать перцем и солью. Отварить яйца. Лук порезать на кольца и обжарить. Яйцо нарезать на ломтики. Помидоры нарезать кружками. Сыр натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4694,'Положить яйцо на кусок рыбы, сверху положить помидор, лук, намазать майонезом, присыпать сыром. Поместить в духовку и готовить рыбу с сыром по-гречески до румяной сырной корочки. Готовую рыбу подать с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4695,'Соединить муку, соду, разрыхлитель, соль. Добавить имбирь, корицу, орех, изюм, мускатный орех. В отдельной емкости взбить яйцо, ваниль, кислое молоко и сахар. Натереть морковь и положить к предыдущим продуктам. Соединить две смеси, перемешать до однородности, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4695,'Обжарить на сливочном масле, с двух сторон, оладьи до золотистого цвета. Взбить сливочный сыр до воздушности, всыпать ванилин, сахарную пудру, корицу, налить молоко. Взбить еще раз миксером и подавать с оладьями. Морковные оладьи с имбирем можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4696,'Картофель натереть или измельчить в блендере с 1/2 луковицы. Посолить и выложить в дуршлаг, чтобы стекла жидкость. Если дуршлаг с большими отверстиями, то застелить его марлей. Из полученной смеси должны получаться колдуны. Вторую половину лука измельчить, соединить с фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4696,'Посыпать перцем, солью, добавить тмин, размешать. Взять чуть-чуть картофеля и сделать лепешку. В центр положить фарш, осторожно завернуть в массу. Разогреть на сковороде масло, положить домашние картофельные колдуны и жарить по 10 минут с каждой стороны. К столу подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4697,'Вбить в муку яйцо, добавить растительное масло и воду. Размешать. Посыпать стол мукой и энергично замесить тесто, подсыпая муку. Комочек недолжен, быть липким. Смазать тесто растительным маслом, положить в посуду и накрыть тарелкой. На 30 минут отставить в сторону. Почистить яблоки от кожуры и порезать на тонкие, маленькие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4709,'Разогреть духовку. Помыть и просушить картофель. Чтобы картофель получился хрустящим и румяным, он должен быть сухим. Намазать каждый клубень солью и оливковым маслом. Поместить в духовку на 60–90 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Нагреть 2 ложки растительного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4697,'Расстелить полотенце, насыпать на него муку. Равномерно распределить слой муки по поверхности. Положить на полотенце тесто, тонко раскатать его скалкой, а затем осторожно растянуть, чтобы не порвать. Полотенце должно просвечиваться сквозь тесто. Края обрезать ножницами. Посыпать тесто панировочными сухарями или измельченными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4697,'Положить нарезанные яблоки, посыпать сахаром. Свернуть рулетик, обрезать концы, чтобы не склеились. Положить на противень, готовить яблочный штрудель с грецким орехом минут 30, соблюдая температуру 190 градусов. Достать из духовки, смазать сливочным маслом и присыпать сахаром. Готовить еще 15 минут. Готовый штрудель подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4698,'Порезать курицу на восемь частей, сделать ножом несколько проколов в каждом кусочке, потереть измельченным чесноком, посыпать перцем, солью, положить острый перец и зиру, налить вино и минут 20–30 мариновать. Несколько раз переворачивать. Обсушить мясо салфетками, обжарить до корочки в широкой кастрюле, имеющей толстое дно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4698,'Переложить в посуду и отставить. Порезать овощи на кубики сантиметр на сантиметр. Горошек размораживать необязательно. В жире, в котором жарилось мясо, обжарить морковь и лук, тщательно перемешивая в мясном соке, положить перец и горошек в последнюю очередь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4698,'Овощи должны сохранить форму и стать хрустящими. Положить в кастрюлю рис, соединить с овощами и немного обжарить, чтобы он впитал масло и сок. На рис положить кусочки куриного мяса. Подсолить бульон и налить его к рису, чтобы он был закрыт на сантиметр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4698,'Довести до кипения, сделать огонь минимальным, накрыть крышкой и томить минут 30. Проверить готовность риса и, если необходимо, долить бульон, готовить еще 10 минут. Снять мясо, аккуратно размешать рис при помощи лопатки. Подавать рис с курицей маринованной в вине, с кусочком лайма или лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4699,'Мелко натереть морковь, тушить минут 15 на сливочном масле. Взбить до пиков белки с солью. Отдельно взбить сахар, желтки, крахмал и муку. Положить в тесто морковь и аккуратно добавить белки. Смазать специальную бумагу растительным маслом. Равномерно выложить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4699,'Готовить бисквит минут 15, при средней температуре. Готовый накрыть полотенцем, подождать еще минут 15 и отделить от бумаги. Во время приготовления бисквита приготовить начинку. Взбить сливки и творог, добавить сахар и цедру. Крахмал развести в охлажденном соке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4699,'Всыпать сахар и варить до загустения, на маленьком огне. Собрать морковный рулет. Намазать на бисквит 1/2 соуса. Положить начинку и сформировать рулет. Сверху смазать его оставшимся соусом. На 120 минут отправить в холодильник. Морковный рулет в апельсиновом соусе подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4700,'Взбить яйца и сахар добела, масса должна увеличиться и загустеть. На этот процесс уйдет приблизительно минут 10. Просеять муку с какао. Медленно, при помощи лопатки соединить муку с яйцами. Положить подтаявшее масло и осторожно размешать. Выложить тесто на противень или в формочку и выровнять лопаткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4700,'Готовить минут 10, соблюдая температуру 190 градусов. В горячем виде, переложить бисквит на полотенце и осторожно свернуть рулетом. Минут 40 остужать. Остывший рулет развернуть и пропитать сахарным сиропом. В сироп предварительно добавить алкоголь (желательно вишневую водку).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4700,'Взбить сливки до пиков и соединить с сыром маскарпоне. Из вишни сварить конфитюр, но можно использовать магазинный. Бисквит, пропитанный сиропом, смазать сливками, положить вишню и свернуть снова рулетом. Украсить шоколадный рулет с вишней «Черный лес» стружкой шоколада и присыпать какао-порошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4701,'Порезать мелко небольшой красный лук. Сделать легкий маринад, смешав воду с уксусом, сахаром и солью и мариновать лук минут 30. Слить через сито маринад. Слить жидкость с горбуши, размять рыбку вилкой, добавить маринованный лук и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4701,'Натереть сыр, раздавить зубчик чеснока и смешать с майонезом. Почистить отваренные яйца, отделить несколько желтков (оставить для верхнего слоя). Оставшиеся яйца натереть, посыпать солью и заправить майонезом. Получается три начинки – сырная, яичная и рыбная. Выкладывать салат на большое блюдо слоями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Положить грибы, жарить 5 минут, помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4701,'Сначала крекеры, затем начинка яичная. Снова крекеры, начинка рыбная, крекеры и начинка сырная. Заканчиваем опять крекерами. Смазать рыбный торт майонезом и посыпать измельченными желтками. Можно украсить по вкусу. Поставить в холод минимум на час. Подать простой рыбный торт с крекерами на праздничный стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4702,'Нагреть до 170 градусов духовку. Отварить макароны. Растопить сливочное масло на огне, всыпать муку и мешать, до золотистого цвета. Следить, чтобы не было комков. Влить молоко, помешать и довести до кипения. Соус готов. Разделить готовые макароны пополам. Выложить одну часть на противень, смазанный маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4702,'Посыпать макароны сыром, нарезанным мелко луком, перцем, солью. Выложить остальные макароны, посыпать луком и сыром, поперчить и посолить. Полить предварительно приготовленным соусом. Накрыть американские «Мак-н-чиз» специальной бумагой и готовить 25 минут. Подавать готовые макароны порционно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4703,'Взять картофель, помыть. Сделать надрезы, не дорезая до конца. Порезать на кусочки масло и пармезан. Чередуя, вложить в картофель. Поместить картофель на 40 минут в духовку. Готовить при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4703,'Достать печеный картофель с сыром пармезан из духовки, полить сливками и присыпать сверху твердым сыром. Запекать еще минут 15. Выложить картофель на блюдо и подать к столу. По желанию присыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4704,'Взбить яйцо венчиком. Налить молоко. Снова взбить. Насыпать муку, опять взбить.  Натереть сулугуни (творог) и добавить в массу. Размешать. Смазать сковороду сливочным маслом, налить тесто и готовить хачапури с сыром сулугуни до румяного цвета с обеих сторон. Подавать готовые хачапури на завтрак.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4705,'Растереть масло с сахаром, вбить яйца и налить ряженку.  Просеять муку, положить разрыхлитель. В смесь всыпать сухие ингредиенты, интенсивно перемешать. Разделить тесто пополам. В одну половину положить какао. Выложить равномерно темное тесто в формочки, в центр положить чуть-чуть сгущенного молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4705,'Почистить грушу, разрезать пополам, серединку убрать, положить в тесто по грушевой дольке. Светлое тесто разложить по формочкам до половины. В центр положить немного сгущенного молока, накрыть остальным белым тестом. Готовить грушевые маффины на ряженке при температуре 175 градусов. Присыпать сахарной пудрой по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4706,'Перебрать малину, положить в посуду. Засыпать ягоды сахаром и отставить на 120 минут. Размешать деревянной лопаткой, помешивать в одном направлении. На протяжении суток перемешивать варенье, пока сахар не растворится. Разлить ароматное малиновое варенье по сухим и стерилизованным баночкам, накрыть пластмассовыми крышками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4707,'Перебрать смородину, оборвать стебельки, промыть и положить в сито. Когда стечет вода, переложить в посуду для варки. Насыпать сахар и отставить на 120 минут. Размешать. Измельчить в блендере до однородности. Разлить быстрое варенье из смородины по сухим и стерилизованным баночкам, закрыть крышками из пластмассы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4708,'Приготовить тесто для блинов. Взбить яйца и молоко, насыпать сахар, муку, соль. Размешать тесто миксером. Промыть укроп, подсушить, измельчить. Можно использовать также зеленый лук и петрушку по желанию. Положить зелень в тесто. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4708,'Разогреть сковороду, предназначенную для выпечки блинов, смазать ее маслом. Обжарить блинчики с двух сторон. Должно получиться шесть штук. Вымыть твердые помидоры, обтереть, порезать на кружочки. Крупно натереть сыр, почистить шампиньоны и порезать на пластинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4708,'Обжарить грибы на сковороде, слегка посолить. Очищенный прессованный чеснок соединить с сыром. Выложить блинный торт в форму слоями. Сначала положить блин, сверху помидоры, посыпать перцем и солью. После выложить грибы и сыр с чесноком. Накрыть блином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4708,'Повторять слои, пока не закончатся блины. Последний блин посыпать сыром. Разогреть духовку до 180 градусов. Поставить закусочный слоеный торт из блинов на 15 минут. Достать, слегка остудить перед подачей. Нарезать торт на кусочки и подать в качестве закуски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4812,'Зелень покрошить. В салатнице смешать ингредиенты для салата и заправить его соусом. Присыпать сверху поломанной лапшой и миндалем. Подавать китайский шопский салат сразу и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4709,'За 30 минут до готовности завернуть в фольгу очищенный чеснок, посыпать перцем и солью, положить сливочное и оливковое масло. Спустя полчаса вынуть картофель, слегка охладить. Разрезать картофель вдоль на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4709,'Осторожно, не задев кожуру, выскрести серединку. Соединить мякоть с печеным чесноком, сметаной, измельченной зеленью, оливковым маслом, тертым сыром и обжаренным беконом. Осторожно размешать, чтобы из смеси не получилось пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4709,'Посыпать солью и перцем. Начинить картофель, посыпать сыром, сверху положить несколько кусков сливочного масла и отправить блюдо под разогретый гриль. Готовить до появления корочки. Пряный картофель под сыром сразу подавать на стол и кушать горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4710,'Нарезать тонко, соломкой, капусту и колбасу. Количество салата определяется количеством нарезанной капусты. Горошек слить и добавить к колбасе и капусте, заправить майонезом, поперчить. Быстрый салат из капусты и колбасы перемешать, выложить на блюдо и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4711,'Замесить тесто из подготовленных продуктов. Разделить его на 4 части, 3 части объединить в одну, четвертую оставить. Раскатать в пласт, толщиной в 0,5 см, большую часть теста. Выложить на сковородку диаметром 28 см, края теста должны выступать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4711,'Продукты для начинки порубить, добавить соль, приправить перцем по вкусу, перемешать. Начинку выложить на тесто. Оставшееся тесто раскатать и выложить на сковородку поверх начинки. Края двух лепешек из теста фигурно защипнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4711,'В нагретую, до 180 градусов, духовку поставить сковородку с пирогом, примерно на 70 минут. После того, как немного подрумянится корочка, влить в сковородку 100–150 грамм кипятка или бульона. Вынуть татарский «Зур Бэлиш» с мясом и сразу смазать его сливочным маслом. Затем немного остудить нарезать кусочками и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4712,'Тонкой соломкой нашинковать капусту.  Потереть крупно морковь и свеклу. Картофель порезать соломкой и обжарить. Мясо нарезать на кубики или соломкой, тоже обжарить до готовности. Все продукты выложить на большое блюдо, раздельными, одинаковыми горками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4712,'В центр блюда налить майонез. Его количество зависит от общего объема салата. На блюдо выложить 2 вилки и подать салат на стол. Непосредственно перед началом еды смешать классический «Дагестанский» салат с помощью двух вилок и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4713,'Куриное филе порезать на крупные ровные кубики. Отбить филе, посолить и поперчить со всех сторон. Болгарский перец порезать на кубики, мелко порезать лук. Добавить их к фаршу. Затем, добавить туда же измельченный чеснок, яйцо, соль и перец. Шампиньоны нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4713,'На крупной терке натереть сыр. В форму для запекания выложить филе, на него уложить фарш с овощами. Грибы выложить вокруг. Посыпать центр блюда сыром. Духовку разогреть до 200 гр. Куриное филе, запеченное под фаршем поставить запекаться на 35 минут. Готовое блюдо подавать горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4714,'Муку, соду и разрыхлитель смешать. Масло размягчить и вместе с сахаром взбить. К маслу добавить яйцо, лимонный сок и ваниль. Миксером все взбить (25–35 секунд). Не прекращая взбивать, на низкой скорости всыпать муку, небольшими порциями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4714,'Кунжут лопаткой вмешать в тесто.  Пекарскую бумагу постелить на противень и выложить на нее тесто чайной ложкой. Так как тесто растекается, то между печеньями оставить по 3–4 см. Поставить противень выпекаться при температуре 180 градусов, на 8–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4714,'В середине выпекания печенье можно перевернуть. Сразу после выпекания печенье из кунжута будет липким и мягким, но, когда остынет, оно затвердеет и станет хрустящим. Готовое печенье выложить на блюдо и кушать с любимыми напитками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4715,'Лук мелко покрошить и обжарить на сковородке с растительным маслом. Ветчину порубить на мелкие кусочки и выложить на сковороду к луку. Помешивая, обжарить лук и ветчину. На сковороду добавить сладкий перец кубиками и кукурузу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4715,'Обжаривать в течении 2 минут, затем закрыть крышкой и тушить еще 2 минуты. Добавить порезанные томаты вместе с соком и потушить немного под крышкой. Добавить соль, перец и чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'Овощной суп с сыром, фрикадельками и вермишелью по-итальянски посыпать тертым сыром перед подачей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4715,'Потушить несколько минут без крышки, чтобы испарилась лишняя жидкость. Убрать с плиты. Яйцо взбить с солью, добавить молоко, снова взбить. Вылить отдельно, на горячую сковородку с небольшим количеством масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4715,'Накрыть крышкой и приготовить омлет (3 минуты). Омлет разрезать на 2 части. Поставить на плиту сковороду-гриль, слегка смазать маслом, включить огонь выше среднего. На одну половину лепешки положить омлет, затем 3–4 ложки ветчины с овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4715,'Посыпать начинку тертым сыром и рубленой зеленью петрушки. Лепешку сложить пополам. Обжарить бурито с моцареллой по-мексикански с двух сторон, на сковороде-гриль, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4716,'Заранее включить духовку на 160–170 градусов и смазать противень маслом. Смешать кокосовую стружку в миске с сахаром, мукой, ванилью и солью. К сухой массе добавить яичные белки. Перемешать до однородности. Ложкой выложить на противень кокосовое печенье.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4716,'Поставить в духовку на 18–20 минут. Нужно обязательно следить за печеньем, так как оно может быстро подгореть. Охладить печенье «Кокосовые макаруны» на решетке. Готовое печенье идеально подходит к горячему чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4717,'Хлеб разрезать на кусочки. Сделать из них сухари. Сухари сложить в трехлитровую стеклянную банку. Налить в нее кипяченной горячей воды. Всыпать 2 ст. л. сахара и дрожжи. Размешать продукты в банке и закрыть ее марлей в несколько слоев, закрепить резинкой вокруг горлышка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4717,'Банку поставить в тепло и накрыть хлопковой тканью.  Через 2 суток убрать банку в холодильник. После охлаждения кваса, его нужно процедить и подсластить по вкусу сахаром. Ржаной квас на дрожжах готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4718,'Для маринада все продукты перемешать до однородности. Отлить 0,5 стакана маринада отдельно. Включить духовку на 190 градусов. Грудки уложить в пакет с замком и залить в него маринад (большую часть). Оставить на 20 минут мясо мариноваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4718,'На сковородке на оливковом масле обжарить чеснок и лук. Добавить грибы, соль и перец. Тушить пока готовности грибов. Надрезать куриные грудки вдоль, но не до конца. Вложить в грудки грибы и кусочек сыра, приправить эстрагоном. Грудки закрепить зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4718,'Разогреть сковородку и обжарить грудки на оливковом масле по 2 минуты с каждой стороны. Переложить их в форму для запекания и накрыть фольгой. Запечь в духовке и через 10 минут достать курицу, фаршированную грибами и сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4719,'Печенье окунуть поштучно в какао и уложить вдоль стенок бокалов или креманок. Взбить сливки до крепких, устойчивых пиков. Добавить к ним сыр, ликер и сахар. Массу перемешать и разложить по креманкам. Закрыть десерт пленкой и убрать в холодильник на всю ночь. Cливочно-шоколадный десерт «Тирамису» перед подачей полить ликером и присыпать тертым шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4720,'Отсыпать 45 грамм сахара и смешать его с ванильным сахаром. Добавить соль и взбить вместе со сливочным маслом, до светлой пышной массы, миксером. Постепенно вбить яйца, все время, продолжая взбивать и также постепенно всыпать муку и разрыхлитель. Тесто переложить в форму 18 см диаметром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4720,'Поставить в нагретую до 150 градусов духовку, на 20 минут. Переложить корж из формы на блюдо и поставить для остывания в прохладное место. Желатин растворить в прохладной воде. Кокосовые сливки, сыр маскарпоне, сахар и творог смешать.  Желатин растопить и ввести в крем тонкой струйкой. Затем добавить 1/2 взбитых сливок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4720,'Взять круглую, куполообразную глубокую чашу объемом 1,5 л и диаметром 18 см. Застелить ее пищевой пленкой. Перелить в нее кокосовое суфле. Миндаль нарезать и выложить на суфле, слегка вдавливая его внутрь. Прикрыть суфле с орехами пленкой и поставить застывать в холодильник, на 3–4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4720,'Чтобы суфле можно было легко вынуть, надо окунуть чашу, на несколько секунд, в очень горячую воду, вынуть суфле и положить на корж. Обмазать оставшимися взбитыми сливками. Чтобы торт был похож на конфеты «Рафаэлло», посыпать его кокосовой стружкой. Торт «Рафаэлло» с кокосовым суфле готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4740,'Очистить и нарезать картофель. Выложить его ломтики на противень. Лук нарезать на полукольца и обжарить на масле 3–5 минут.  Натереть сыр. Обжаренный лук выложить на картофель.  Кефир смешать с солью, чесноком, зеленью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4721,'Разъемную форму смазать маслом, положить круг из пергаментной бумаги на дно формы. Погружным блендером взбить творог, сахар, яйца, сметану, крахмал, ванилин до однородной массы. Творожную массу выложить на дно формы ровным слоем. Для шоколадного коржа отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4721,'Хорошо взбить белки до пышной массы и, продолжая взбивать, постепенно добавить сахар. Желтки взбить вместе с растительным маслом. Всыпать муку, разрыхлитель и какао. Добавить взбитый белок и перемешать ложкой. Выложить шоколадное тесто на творожную массу в форме. Поставить на 40 минут в духовку (температура – 180 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4721,'Вынуть форму, остудить и перевернуть на блюдо, творогом вверх. Пюре из клубники смешать с сахаром. Желатин залить небольшим количеством воды. Подождать, пока он набухнет. Потом нагреть и дождаться полного растворения. Желатин не кипятить. Теплый желатин влить в клубничное пюре и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4721,'Поставить борта от разъемной формы вокруг торта и влить клубничное желе, затем накрыть торт пленкой и убрать остывать в холодильник. Чтобы вынуть творожно-шоколадный торт с желе из формы, надо провести вдоль бортов формы ножом и аккуратно их убрать. Готовый торт украсить по желанию и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4722,'Помидоры черри промыть и высушить. Остро наточенным ножом разрезать помидоры наполовину. Затем каждую половинку разрезать еще раз напополам, проведя разрез только на 2/3 помидоры. Таким образом помидоры станут похожи на раздвинутые крылья божьей коровки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4722,'Сыр филадельфия намазать на крекер слоем средней толщины. Маслины промыть и обсушить. Одну маслину разрезать на 2 части, вынуть косточку и измельчить, чем меньше, тем лучше. На крекер аккуратно положить помидорные крылья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4722,'Нарезанную маслину перемешать с несколькими каплями растительного масла, чтобы ее кусочки стали липкими. Зубочисткой подцепить один кусочек маслины и переложить его на крылья божьей коровки. Это будут пятнышки на крыльях. Таким образом украсить все канапе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4722,'На канапе уложить по надрезанной оливке у цельной части помидоры. Это будет голова насекомого. В каждую маслину вставить 2 небольших перышка тонкого зеленого лука. Это будут усики. Выложить канапе «Божья коровка» с маслинами на блюдо и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4723,'Красный лук порезать на полукольца, зеленый лук измельчить. Чеснок мелко покрошить, а грибы разрезать на четвертинки. Порезать на 8 частей помидоры. Помидоры черри оставить целыми. Красный лук нарезать и пассировать до прозрачности, на сковороде с разогретым маслом. Добавить чеснок и грибы, обжаривать в течение 3–5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4723,'Выложить на сковородку помидоры с нарезанным зеленым луком и потушить все вместе еще 3 минуты. Салат посолить, добавить перец, присыпать цедрой и сбрызнуть лимонным соком, перемешать. Теплый грибной салат с лимонной цедрой посыпать резаной петрушкой, украсить помидорами черри и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4724,'Полукольцами нарезать лук. Толстыми брусками порезать мясо и картофель. Огурцы мелко нарезать, на кусочки. Мясо поджарить на сильном огне небольшими порциями. Обжарить на сливочном масле лук, до прозрачности. Добавить на сковороду томатную пасту, перемешать и выложить туда же мясо, залить водой или бульоном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4724,'Варить примерно 50 минут до готовности мяса. Обжарить картофель в большом количестве разогретого масле. К готовому мясу выложить картофель и огурцы. Перемешать рагу из говядины по-татарски и варить еще 10–15 минут. Готовое блюдо подавать на стол порционно и кушать. Перед подачей присыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4725,'Тесто нарезать на четное количество полосок шириной 2 см. Куриную грудку порезать на мелкие кусочки и выложить на половину полосок теста. Сверху выложить сыр. Закрыть полоски с начинкой второй половиной полосок. Защипнуть края. Пергаментную бумагу положить на противень. Слойку завернуть в спираль и выложить на противень. Косички смазать желтком. Противень со слоеными спиральками поставить выпекаться на 15 минут в духовку, нагретую до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4748,'Запекать при температуре 220 градусов до готовности. Если необходимо, накрыть формочку фольгой. В оставшееся тесто положить какао и приготовить второй корж. Охладить и оба разрезать вдоль на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4726,'В блендере смешать все ингредиенты для блинов и взбить в течение, примерно 10 секунд. Тесто убрать на час в холод. Разогреть сковородку. На сливочном масле пожарить тонкие блины и выложить их на тарелку. Промазать блины попеременно, взбитыми сливками и шоколадной пастой. Шоколадный торт из блинов со сливками можно подавать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4727,'Огурцы нарезать на мелкие кубики. В чесночном прессе раздавить чеснок. Мелко порубить ножом зелень. Смешать все продукты в миске, посолить и поперчить по вкусу. Оставить соус настояться на ночь в холодильнике. Греческий соус «Цацики» на йогурте подавать к мясным, рыбным или овощным блюдам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4728,'Порезать куриные грудки на некрупные кусочки. Залить сливками и поставить на полчаса в холодильник. Измельчить в блендере кукурузные хлопья, соль и паприку. Куриные кусочки обвалять в получившейся панировке со всех сторон. Противень смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4728,'Выложить на него наггетсы и поставить в нагретую духовку, на 15 минут. Как только наггетсы покроются золотистой корочкой, вынуть их из духовки и подать как закуску, либо с гарниром из овощей в качестве самостоятельного блюда. В дополнение, к наггетсам подать соус. Готовые куриные наггетсы с медовым соусом можно кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4729,'Размять творог вилкой или провернуть через мясорубку. Вбить к творогу яйца, насыпать манку и сахар, посолить и добавить ваниль. Перемешать творожную массу и оставить на 30 минут. Добавить изюм, гашеную соду и всыпать муки, чтобы тесто не липло к рукам. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4729,'Застелить пергаментной бумагой противень и выложить на него сформированные сырники. Выпекать в духовке при 180 градусах до подрумянивания, примерно 35–40 минут. Подавать готовые сырники с изюмом, со сметаной или вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4730,'Отварить в подсоленной воде куриное мясо. Дать остыть и нарезать кубиками. Тщательно промыть чернослив и положить на 10 минут в стакан с кипятком. Затем обсушить его бумажными полотенцами и нарезать тонкой соломкой. Вареные яйца почистить и натереть белки и желтки, отдельно друг от друга.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4730,'На сковороде, слегка обжарить без масла орехи и перемешать с морковью. Натереть крупно сыр и смешать с давленым чесноком и майонезом. Выложить салат слоями на плоской тарелке. Первым слоем выложить чернослив, смазать его майонезом. Вторым слоем – кусочки курицы. Посолить, поперчить и смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4730,'Третьим слоем выложить морковь с орехами, посыпать сыром и белками. Смазать салат со всех сторон майонезом и посыпать желтками. Салат оставить на 1 час в холодильнике и затем украсить перед подачей на стол веточками петрушки или мелко нарезанной  зеленью. Оригинальный салат с черносливом подать на праздничный стол и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4731,'Для начинки отварить очищенный картофель, растолочь его в пюре. Лук мелко порезать и пожарить до золотого цвета. Выложить к картошке. Лук и картофель смешать с тертым сыром, зеленью. Для теста смешать яйца, кефир и муку. Соль добавить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4731,'Из теста вырезать кружки и раскатать их скалкой. На кружок выложить картофельно-сырную начинку, слепить пирожок, плотно защипнув края. Скалкой придавить пирожок, чтобы получилась лепешка. Обжарить лепешки с картофелем на сковороде до образования хрустящей корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4732,'Взбить яйца с сахаром, для теста. Маргарин растопить и дать немного остыть. Смешать яйца с маргарином. Разрыхлитель перемешать с мукой и замесить мягкое, пластичное тесто. Убрать его в холодильник и приготовить заливку. Яйца для заливки взбить сахаром и смешать с мукой и сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4732,'В разъемную форму выложить тесто, аккуратно, сделав высокие бортики, чтобы не вытекла начинка. Выложить ягоды и налить сверху заливку. Пирог выпекать 35 минут, затем остыть. Готовый заливной пирог с ягодами подать к столу и кушать с любимыми напитками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4733,'На водяной бане растопить сливочное масло, к нему насыпать сахар-песок и влить воду. Прогреть пока не растворится сахар.  Добавить к маслу мед и снова прогреть до его растворения. Добавить соду и мешать пока не закончится реакция. Можно добавить 1 ст. л. водки или коньяка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4862,'Разогреть духовку до 150 градусов, сковороду смазать жиром и выложить на нее окорок вверх шкуркой, отправить мясо на 4,5 часа жариться в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4733,'Снять массу с бани и, не дожидаясь, когда она остынет, добавить 1–2 стакана муки. Перемешать, закрыть крышкой и оставить остывать. В остывшую массу ввести яйца, вбивая их по одному, и остальную муку. Замесить тесто, снова накрыть и опять оставить на полчаса. Разделить все тесто на 10–12 одинаковых частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4733,'Раскатать каждую на пекарской бумаге и выпекать по 5 минут каждый корж в духовке, при температуре 200 градусов. 11 коржей пойдут на торт, а 1 – на посыпку. Сахар и ваниль смешать, добавить к сметане и убрать смесь на 5 минут в холодильник. Взбить сметанную массу. Охлажденные сливки взбивать пока не начнут густеть и, не переставая взбивать, добавить частями сгущенное молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4733,'Сметанную и сливочную массу смешать и промазать кремом все коржи, кроме верхнего. На торт, сверху, положить на полчаса что ни будь не слишком тяжелое, чтобы слои получились ровными. После этого обмазать кремом верх, боковые стороны торта и посыпать крошками, полученными из последнего коржа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4734,'Приготовить соус для маринования. В кастрюлю разбить яйцо, добавить по 3 ст. л. муки и майонеза. Добавить любимые приправы и соль. Перемешать смесь. Куриные грудки промыть, отделить мясо от кости и порезать на 2–3 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4734,'Положить мясо в кастрюлю с маринадом и оставить на несколько часов, закрыв крышкой. Грудки можно использовать и замороженные, тогда в маринаде надо держать их подольше. Разогреть сковороду с маслом и выложить замаринованное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4734,'Обжарить грудки со всех сторон. Готовые мягонькие и сочные куриные грудки полить лимонным соком перед подачей на стол или на блюдо к ним добавить парочку ломтиков лимона. Подавать с гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4735,'Для теста перетереть муку, соду и соль вместе с маргарином. Влить кефир и замесить руками тесто. Для начинки орехи и сахар измельчить вместе в блендере. Тесто раскатать в тонкую лепешку прямоугольной формы и на нее выложить равномерно начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4735,'Свернуть тесто в рулет. Нарезать рулет наискосок на ломтики толщиной 4 см. Смазать желтком сверху. Ломтики выложить на смазанный противень. Поставить ореховые рулеты «Кода» в духовку на 30 минут в температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4736,'Ножки обжарить немного на сковороде. Приготовить соус, перемешав все продукты. Соусом залить курицу и 10 минут тушить на медленном огне, переворачивая мясо для равномерного обжаривания. Даже без предварительного маринования курица получается очень вкусной. Готовую курицу под медово-соевым соусом выложить на блюдо и подать с гарниром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4737,'Рыбу очистить от чешуи, под проточной водой хорошо промыть, разрезать брюшко и убрать внутренности. Икру, если она будет, оставить. Подготовленную рыбу нашинковать, то есть острым ножом сделать надрезы с обеих сторон поперек тушки, не задевая позвоночника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4737,'Надрезы делать часто, но аккуратно. Внутрь рыбы положить тонкие кольца лука и лавровый листик. Рыбные тушки обвалять в муке и обжарить на медленном огне. Сочную жареную рыбу без костей можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4738,'Укроп мелко порезать. Натереть мелко на терке сыр. Растительное масло нагреть на сковородке. Перемешать все остальные ингредиенты. Смесь вылить на сковородку и жарить по 10 минут с каждой стороны. «Ленивые» сырные хачапури остудить, промокнуть лишнее масло салфетками, порезать на порционные ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4739,'Перемешать теплое молоко с 1 ложкой сахара, дрожжами и всыпать немного муки. Перемешать опару и поставить в тепло. Яйца взбить вместе с сахаром и солью. Когда опара начнет опадать, подмешать к ней взбитые яйца. Оставшуюся муку тоже всыпать и замесить тесто. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4739,'Тесто месить руками, пока оно не перестанет липнуть. Завернуть его в полотенце или накрыть хлопковой тряпочкой и оставить в тепле на 1,5–2 часа. В этот промежуток времени тесто нужно 3 раза обмять.Когда тесто в очередной раз подойдет, разделить его на одинаковые части и оставить, для поднятия, еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4739,' Слепить пирожки с любимой начинкой и оставить на 10 минут для расстойки. Обмазать желтком «Бабушкины» пышные пирожки и печь в духовке при температуре 200 градусов, 20 минут. Готовые пирожки немного остудить, накрыв полотенцем, и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4862,'Вынуть окорок и дать остыть, нарезать ломтями, отдельно подать соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4740,'Картофель с луком полить соусом и поставить на 30 мин. в разогретую духовку. Блюдо посыпать сыром и поставить выпекаться еще на 15 минут. Запеченный в кефире картофель подавать на стол порционно, в качестве гарнира или как самостоятельное блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4741,'Все приправы и коньяк смешать. Обтереть полученной смесью рыбное филе со всех сторон. Рыбу обернуть холщевой тряпочкой и положить в контейнер. Оставить в холодильнике на ночь. Утром малосольная семга сухого посола будет готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4742,'Куриную грудку очистить от пленок и промыть. Отбить грудки, посолить и поперчить. Фарш смешать с мелко порубленным болгарским перцем и луком. Перец и лук можно потереть на крупной терке. К фаршу добавить яйцо, соль, чеснок и перец. Промыть грибы и порезать тонкими пластиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4742,'Сыр натереть. В форму для запекания уложить отбитые полоски филе. Сверху на каждый кусочек филе положить фарш, потом шампиньоны и в центр посыпать немного сыра. Поставить в духовку на 35 минут. Куриное филе, запеченное под фаршем, подавать на стол горячим с гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4743,'Яйцо разбить в миску и посолить. Добавить 1 ч. л. сметаны. Взбить вилкой смесь. На горячую сковородку вылить яичную смесь. Обжарить блин с двух сторон. Переворачивать его очень аккуратно, чтобы не порвать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4743,'Пока жарится первый блин, приготовить яичную смесь из второго яйца. Так по очереди приготовить 7 блинов. Лук мелко покрошить и выложить к свиному фаршу. Фарш посолить, добавить перец по вкусу и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4743,'На каждый блин выложить часть фарша в виде прямоугольной колбаски. Завернуть блины конвертиком. Выложить 7 яичных конвертов  в форму для запекания. Бульон подогреть, добавить сметану и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4743,'Перемешать соус и залить им яичные конвертики чуть больше чем наполовину. Духовку нагреть до 200 градусов и поставить форму для запекания на 25 минут, предварительно укрыв фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4743,'Через 15 минут фольгу снять. Духовку выключить. Достать конвертики и посыпать их сыром, вернуть на 5 минут в духовку, чтобы расплавился сыр. Яичные конвертики с мясной начинкой подавать горячими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4744,'Мелко натереть сыр и соединить со сметаной, яйцом и мукой. Перемешать. Кусочки хлеба искупать в сырно-яичной смеси. Выложить хлеб на разогретую сковородку и обжарить. Сытные, жареные в сыре гренки готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4745,'Листы слоеного теста раскатать до толщины 1–2 мм и в нескольких местах наколоть вилкой. Выпечь в духовке до легкого подрумянивания. Желтки, ванильный сахар и пудру взбить до пышности. Перемешать с маскарпоне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4745,'Собрать торт из коржей, пропитывая каждый слой кремом и укладывая ягоды.Сам торт собирать на плоском блюде, слегка смазанном кремом. Можно коржи разрезать предварительно и собирать пирожные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4745,'Верхний слой торта украсить целыми ягодками и посыпать сверху сахарной пудрой. Края смазать кремом и обсыпать крошкой от коржей. Слоеный торт «Мильфей» с маскарпоне можно кушать сразу или дать ему постоять пару часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4746,'На растительном масле обжарить куриные голени до полуготовности. Убрать их в сторонку. На той же сковородке обжарить лук и стручковую фасоль. Через 10 минут обжаривания добавить к ним кабачок, порезанный кубиками. Сметану и майонез перемешать вместе с раздавленным чесноком и смесью перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4746,'Овощную смесь выложить в форму для запекания. Куриные голени выложить сверху. Уложить поверх курицы дольки томатов и полить соусом. Курицу с овощами запекать в духовке при 170 градусах. Время запекания – 20 минут. Куриную голень с овощами, под соусом, подавать в горячем виде, выложив на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4747,'Размять горбушу вилочкой, отварить вкрутую яйца, почистить и покрошить. Порезать огурцы на мелкие кубики, крупно натереть сыр, измельчить луковицу. Соединить все ингредиенты, положить горошек, посыпать по вкусу перцем и солью. Заправить легкий салат с горбушей и огурцами майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4748,'Растереть сахар и яйца. Положить сгущенное молоко и сметану. Насыпать муку, чтобы тесто было текучим и густым одновременно. Погасить в уксусе соду, мгновенно добавить в тесто. Намазать формочку маслом, вылить 1/2 теста и отправить в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4884,'Приготовить из мяса, охлажденного вареного картофеля и вымоченной сельди фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4748,'Приготовить первую часть для крема: соединить и размешать молоко и яйца. Медленно добавить муку, не прекращая помешивать. Разбить все комочки. Класть ингредиенты нужно в той последовательности, которая указана, тогда комочки не останутся.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4748,'Поставить на огонь, довести до кипения, помешивать. Охладить. Приготовить вторую часть для крема: соединить и взбить какао, масло и сахар. Соединить обе части для крема. По желанию положить орешки. С таким кремом торт получается очень вкусным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4748,'Приготовить глазурь: соединить сахар и какао, долить воду, варить до слабого загустения, положить масло, перемешать. Полить классический шоколадный торт «Пражский» глазурью и поставить в холод на несколько часов. Торт «Пражский» готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4749,'Взбить сахар и яйца, положить сметану, какао, добавить соду, гашенную уксусом, насыпать муку, все перемешать. Разделить тесто пополам. Одна часть должна быть меньше, другая больше. Меньшая станет основой торта, выпечь ее и смазать кремом. Большую часть выпечь и порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4749,'Готовить тесто минут пятнадцать, соблюдая температуру 180 градусов. Проверять готовность зубочисткой. Приготовить крем: взбивать сахар и сметану, пока не растворится сахар. Все кусочки теста обмакнуть в крем и разложить на основную часть торта горкой, которую необходимо залить глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4749,'Чтобы приготовить глазурь, нужно смешать все ингредиенты и готовить пару минут на маленьком огне, перемешивая. Если добавить в оригинальный торт «Негр в пене» вишню, то он станет еще вкусней. Отправить торт минимум на 2 часа в холодильник, чтобы он пропитался. Готовый торт подать на стол и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4750,'Приготовить зирвак из мяса, овощей, приправ и сухофруктов. Лук порезать соломкой, морковь брусками. Если потереть морковь на терке, то плов будет кашеобразный. Порезать мясо на небольшие куски. В кастрюлю или казан налить масло, разогреть, положить лук и обжарить практически до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4750,'Положить мясо и готовить его до выделения сока. Причем не следует часто его мешать, чтобы в некоторых местах образовалась корочка. Огонь все это время должен быть большим. Добавить сухофрукты и морковь, размешать, сделать тише огонь, накрыть крышкой, тушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4750,'Посыпать перцем, солью, добавить куркуму, барбарис, зиру, размешать. Налить воду, чтобы она покрыла мясо. Закрыть крышкой, готовить минут сорок. Промыть рис минимум пять раз. Выложить с помощью ложки на мясо (не перемешивать). Разровнять. Налить теплую воду (лучше горячую), чтобы рис был на несколько сантиметров покрыт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4750,'Досолить. Накрыть крышкой, готовить пока не впитается вода. В центр положить чеснок, слегка вдавить в рис. Сделать в рисе отверстия при помощи зубочистки, чтобы выходил пар (не перемешивать). Готовить самаркандский плов с сухофруктами еще минут 20 под крышкой. Перед подачей перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4751,'Отварить минуты четыре цветную капусту (можно замороженную) в подсоленной воде. Положить капусту в формочку для запекания. Сделать заливку. Взбить яйца, положить сметану, посыпать солью и приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4751,'Вылить смесь в формочку на капусту. Посыпать тертым сыром. Готовить, пока сыр не станет румяным. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4752,'Размягченное сливочное масло перемешать с сахаром, вбить яйцо, влить молоко и снова размешать. Насыпать ванилин, муку, разрыхлитель. Замесить эластичное и мягкое тесто. Не слишком тонко раскатать его в пласт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4752,'Выдавить коржи при помощи формочек для кекса. Выложить коржи на противень, смазанный маслом. Готовить в духовке минут 15, соблюдая температуру 180 градусов. Домашние песочные коржики подавать к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4753,'Порезать сыр полосками, обвалять в муке, яйцах и сухариках панировочных. Обжарить со всех сторон на масле до золотистости. Выложить сырные закусочные палочки на салфетку, чтобы стекло масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4754,'Отварить куриное мясо, картофель или рис, яйца, морковь. Порезать лук на полукольца и чуть-чуть поджарить. Обжарить порезанные грибы. Крупно натереть сыр. Слоями уложить на тарелку: кусочки курицы, обжаренный лук, натертый отваренный картофель (рис).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4884,'Мелко нашинковать лук, обжарить и добавить вместе с яйцом и молоком в фарш, поперчить, посолить, всю массу хорошо вымесить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4754,'Каждый слой немного смазать майонезом. Затем выложить слой грибов, крупно натертую морковь, вновь смазать майонезом. Затем крупно натертые яйца и сыр. Отставить слоеный салат «А-ля жульен» часа на полтора для пропитки. Готовый салат украсить по желанию, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4755,'Измельчить в блендере бананы, творожную смесь смешать с мукой и яйцом, добавить изюм и измельченные бананы. Смазать формочку маслом, выложить смесь, готовить 20 минут. Для приготовления соуса, растворить сахар в сливочном масле, на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4755,'Как только сахар приобретет золотистый цвет, снять с огня. Постепенно влить сливки, постоянно помешивая. Полить торт карамельным соусом. Украсить банановый чизкейк с карамелью клубникой и взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4756,'Помыть куриное филе, обсушить, нарезать на небольшие волокна, посыпать перцем, солью и обжарить на растительном масле. Помыть огурец, порезать тоненькой соломкой. Помидор нарезать дольками. Приготовить соус: смешать майонез и кетчуп, посыпать перцем и солью. Положить на стол лаваш, обильно намазать соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4756,'Выложить корейскую морковь, затем капусту, огурец, порезанный соломкой, дольки помидоры, обжаренные кусочки мяса. Полить соусом. Свернуть лаваш конвертом, поместить в пакет. Перед подачей, около минуты, подогреть домашнюю шаурму с корейской морковью в микроволновой печи или на сковороде. Подавать горячей и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4757,'Почистить морковь, луковицу, картофель и чеснок. Помыть цукини. Измельчить чеснок. Другие овощи крупно потереть. К овощам положить петрушку, яйца, сухарики, базилик. Посыпать перцем, солью. Разогреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4757,'Смазать формочку маслом, выложить в нее овощную массу, выровнять поверхность, полить маслом, готовить минут 50, соблюдая температуру 180 градусов. Подавать еврейский овощной кугель горячим, разложив порционно по тарелкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4758,'Взбить яйца, положить сметану и приправить перцем и солью. Смешать разрыхлитель и муку. Аккуратно добавить к сметане. Крупно натереть сыр и кабачок. Кубиками порезать ветчину и перец. Почистить и измельчить чеснок. Положить все в смесь, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4758,'Выложить массу в форму для кекса и готовить 45 минут, соблюдая температуру 200 градусов. Приготовленный овощной кекс с ветчиной и сыром остудить и вынуть из формочки. Перед подачей нарезать кекс ломтиками и выложить на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4759,'В просеянную муку добавить дрожжи. Налить воду и замесить слегка липкое тесто. Накрыть и отставить на 30 минут. После этого налить в тесто масло, посыпать солью, вымесить. Тесто будет немного жирным. Спустя несколько минут всыпать пару ложек муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4759,'Накрыть и на 60 минут поставить в тепло. Приготовить начинку: порезать на тоненькие кружочки колбасу и помидор. Кольцами нарезать луковицу, измельчить зеленый лук, мелко натереть сыр. Спустя час обмять тесто, если нужно насыпать еще муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4759,'Выложить лепешку на пергаментную бумагу, вырезанную по форме противня. Раскатать скалкой тесто в круг, толщиной 4 миллиметра. Получится маленькая пицца (примерно 20 сантиметров диаметром). Намазать лепешку соусом или кетчупом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4759,'Выложить начинку, не доходя до края: помидоры, колбасу, затем лук. Посыпать зеленью и сыром. Готовить пиццу с колбасой на тонком тесте минут 25, соблюдая температуру 180 градусов. Готовую пиццу нарезать на кусочки и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4760,'Очистить апельсины от кожуры, мелко натереть цедру (белую часть не трогать, только оранжевую). Выжать сок из апельсина. Растопить масло, например, в микроволновой печи, слегка охладить. В масло вбить яйца, насыпать обычный и ванильный сахар, размешать при помощи венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4760,'Чтобы готовить маффины, не нужно использовать миксер. Вместо венчика можно воспользоваться обыкновенной ложкой, но венчиком проще перемешивать. Положить цедру, влить сок, размешать. Насыпать муку и разрыхлитель, размешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4760,'Выложить формочки специальной бумагой или смазать маслом. Положить тесто, 3/4 объема формы. Поместить в духовку и готовить пышные апельсиновые маффины минут 30, соблюдая температуру 180 градусов. Достать маффины из формочек и охладить. Посыпать кексы сахарной пудрой и украсить цедрой апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Через пару минут убрать кастрюлю с плиты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4761,'Смешать яйцо и масло, долить воду, насыпать соль, муку. Вымесить тесто, обернуть его полиэтиленом и отправить на полчаса в холодильник. Отварить куриную грудку, порезать на маленькие кусочки. Обжарить грибы и лук, посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4761,'Добавить мускатный орех и приготовленное мясо. Все смешать, обжарить и снять с огня. Разогреть до 180 градусов духовку. Смазать форму (23 сантиметров в диаметре) маслом. Тесто раскатать, положить в формочку, сделав бортик. Выложить начинку, выровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4761,'Размешать яйца вилкой, положить тертый сыр, сливки, еще раз размешать и вылить равномерно смесь на начинку. Готовить лоранский французский пирог минут 40. Бортик снять, выложить пирог на решетку, охладить. Остывший пирог выложить на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4762,'Приготовить соус: соединить натуральный йогурт и сметану или майонез (маложирные). Куриную грудку отварить. Все продукты измельчить и выложить в салатник. Заправить соусом. Легкий куриный салат с яблоками перемешать и кушать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4763,'Смешать сахар и яйца, взбивать, пока не образуется пышная смесь. Насыпать муку. Смешать сливки с ванильным сахаром или ванилью, вылить в массу. Смазать формочки маслом, посыпать мукой и выложить в них тесто, заполнив на 2/3.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4763,'В середину положить по маленькому кусочку шоколада. Готовить минут 25, соблюдая температуру 190 градусов. После приготовления оставить сливочные пирожные в формочках на несколько минут. Затем достать и полностью остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4763,'Приготовить глазурь: отдельно растопить сливочное масло и оставшийся шоколад. Можно это сделать на паровой бане или в микроволновой печи. Смешать эти ингредиенты и всыпать какао. Полить сливочные пирожные теплой глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4764,'Для приготовления супа необходимо в первую очередь очистить картофель, порезать его на кубики и отварить. Нарезать мелко лук, натереть морковь. Положить овощи на сковороду. Не слишком мелко порезать колбаски. Выложить кусочки колбасы на сковороду, к моркови и луку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4764,'Обжарить смесь на небольшом огне. Когда картофель будет готов, переложить содержимое из сковороды в кастрюлю. Положить зелень и лавровый лист. Готовить простой суп из копченых колбасок еще минут 5. Разлить готовый суп по тарелкам и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4765,'В стакане смешать сахар, муку и дрожжи, налить воду. Минут на 15 отставить. Просеять муку, сделать в центре углубление, налить разведенные дрожжи, воду, насыпать соль, замесить тесто. Добавить масло растительное, поставить в тепло. Обмять тесто. Приготовить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4765,'Отварить картофель и помять его до однородности. В отдельной емкости размять осетинский сыр, переложить в картофель, налить молоко или сметану, посолить и размешать. Сформировать лепешки по 1 сантиметру толщиной. В центр положить немного фарша, подготовленного предварительно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4765,'Свернуть края теста конвертиком, чтоб начинка осталась внутри. Выровнять поверхность лепешки, перевернуть и немного раскатать. Повторить данную процедуру несколько раз, пока пирог не станет округлым и ровным по толщине. Выложить пирог на разогретую сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4765,'Сделать сверху пирога в центре отверстие. Это не даст скапливаться парам и лепешка не развалится. Готовить, пока не появится специфический запах, и блюдо не подрумянится. Смазать сливочным маслом и сразу подавать. Кушать традиционный осетинский «Картофджин» горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4766,'Сделать обычное дрожжевое тесто. Можно сначала поставить опару, но делать это необязательно. Подогреть молоко, чтобы оно было теплым. Добавить чуть-чуть сахара и дрожжи. Отставить ненадолго, чтобы дрожжи могли полностью раствориться. Насыпать по вкусу соль, вбить яйцо, налить растительное масло, насыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4766,'Смазать растительным маслом и оставить подходить. Тесто лучше подходит, если ставить кастрюлю его в емкость с горячей водой. Подождать 60 минут, чуть-чуть помять тесто и оставить, чтобы оно подошло еще. Должно получиться приблизительно 1100 грамм – хватает этого количества на три пирога.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4773,'Разрезать курицу на две части, залить водой и 1/2 нормы вина, положить сельдерей, лук, две горошины перца, посыпать солью и готовить маленьком огне. Остудить мясо. Отделить мякоть от косточек и порезать на мелкие кусочки. Процедить бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4766,'Приготовить начинку в то время, пока подходит тесто. Взять чуть-чуть домашнего несоленого или слабосоленого сыра (осетинский или брынзу). Пропустить сыр через мясорубку, если есть необходимость подсолить по вкусу. Сформировать из теста лепешки и выложить в середину начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4766,'Соединить края, подняв их вверх, к середине. Примять лепешку руками и раскатать. Повторять процесс, пока лепешка не приобретет одинаковую толщину и ровную форму. Выложить на разогретую сковороду и обжарить. В центре сделать дырочку. Готовый пирог смазать сливочным маслом и подать горячим. Кушать классический «Уалибах» с сыром сразу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4767,'Потушить самым обычным способом капусту, посыпать перцем и солью. Перец должен хорошо чувствоваться. Любители острого, могут положить измельченный стручковый перец чили. Для одного пирога потребуется одинаковое количество начинки и теста. Посыпать стол мукой. Поделить тесто на три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4767,'Немного примять комочки, положить тесто. Осторожно поднять тесто около начинки и собрать, как будто мешочек. Тщательно защипнуть, ненадолго отложить в сторону. Затем примять тесто пальцами и сформировать тоненький круг, начиная с центра к краям. Все необходимо делать аккуратно, чтобы не порвалось тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4767,'Осторожно переложить на противень, в центре пирога сделать отверстие. Поставить в духовку, готовить при температуре 200 градусов. Процесс выпекания не займет много времени. Когда пирог станет румяным, вынуть и смазать сливочным маслом. Осетинский «Кабускаджин» с капустой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4768,'Взять лимон и эстрагон, отжать сок. Вылить в емкость, долить газированную воду. Разлить домашний «Тархун» по бокалам, наполнить их льдом и украсить веточкой эстрагона. Газированный напиток готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4769,'Отделить желтки от белков. Взбить белки в глубокой емкости до крепкой, пенообразной массы. Всыпать сахар, взбить до густой смеси. Через кондитерский мешок отсадить белки на противень. Можно использовать ложку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4769,'Готовить простое белковое безе минут 60, соблюдая температуру 100 градусов. Периодически посматривать, чтоб не подгорело. Готовое воздушное безе из яичных белков остудить и подать к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4770,'Соединить и перемешать в блендере яйца, молоко, сахар, гашеную соду, соль, муку. Не переставая мешать, добавить воду (чем больше воды, тем тоньше будут блины) и подсолнечное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4770,'Смазать чуть-чуть маслом горячую сковороду (один раз) и выпечь блинчики. Растопить сливочное масло. Приготовленные блины переложить на тарелку, обильно смазывая каждый растопленным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4771,'Приготовить начинку: натереть сыр, очистить зубчики чеснока, вымыть, почистить, измельчить. Добавить майонез, размешать. Развернуть крабовые палочки осторожно, выложить начинку и придать палочке первичный вид.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4771,'Сделать кляр: отделить белки и желтки, отправить в холодильник. Растереть желтки с солью, долить молоко, немного взбить. Насыпать муку, замесить тесто. Холодные белки взбить в густую пенку, положить в кляр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4771,'Осторожно перемешать, обмакнуть в кляр, подготовленные палочки. Разогреть в кастрюльке масло растительное, обжарить в ней палочки. Готовые крабовые палочки достать из масла, выложить на салфетки, чтобы стек жир. Приготовить соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4771,'Почистить оставшийся чеснок, измельчить его. Вымыть, подсушить и измельчить зелень. Соединить чеснок, зелень, сок лимона, сметану, перец, соль, все размешать. Перед подачей крабовые палочки в кляре полить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4772,'Застелить разъемную форму (19 сантиметров) пергаментом. Пропустить через мясорубку финики, всыпать орехи и муку. Сформировать смесь похожую на тесто. Выложить его в форму, поверхность выровнять и поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4772,'Размять бананы, соединить с какао и яблочным пюре, чуть-чуть взбить миксером. Смешать агар-агар с водой, секунд 30 кипятить. Шоколадную смесь медленно взбить миксером, тоненькой струей влить агар-агар, взбивать еще секунд 60, смесь должна загустеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4772,'Налить крем в формочку, отправить в холодильник минимум на 120 минут, а лучше на ночь. Пройтись по краю шоколадного пирога ножом и снять аккуратно формочку. Веганский пирог с финиками подать к столу и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4773,'Немного обжарить на масле измельченный чеснок, положить кусочки грибов и готовить приблизительно 5 минут. Всыпать муку и обжаривать минут 7, помешивая. Немного остудить, влить бульон и остальное вино, сварить густой соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4773,'Убрать с плиты, влить сливки, добавить тертый сыр, зелень и размешать. Сварить листы лазаньи в воде, затем на 2 минуты опустить в холодную воду. Налить часть соуса в форму, положить листы лазаньи, слой мяса, влить соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4773,'Повторять слои около 4 раз. Сверху влить соус, присыпать сыром и готовить лазанью с тушеной в вине курицей при температуре 230 градусов, минут 50. Готовую лазанью порционно нарезать и подать к столу горячей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4774,'Вскипятить воду, картофель очистить и порезать на небольшие кубики. Натереть плавленый сыр. Обжарить натертую или измельченную морковь, на сливочном масле. Измельчить чеснок и свежую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4774,'Обжаренные и измельченные ингредиенты выложить в кастрюльку, довести до кипения, посолить. Огонь выключить и оставить на плите. Когда легкий суп с плавленым сыром перестанет кипеть, разлить его по тарелкам и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4775,'Просеять муку, добавить разрыхлитель. Взбить венчиком сахар и яйца. Оттаять сливочное масло, размешать. Добавить в яичную смесь, положить сметану, размешать мешать. Медленно всыпать в массу муку, замесить некрутое мягкое тесто. Во время замеса тесто прилипает к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4775,'Насыпать в тесто столько муки, чтобы можно было сделать шар, присыпать его мукой. Поместить тесто в пакет из полиэтилена, отправить часа на 3 в холодильник. Посыпать мукой поверхность стола. Достать тесто из пакета и раскатать его в пласт, толщиной в 1 сантиметр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4775,'С помощью рюмки или формочки вырезать печенье. Формочку каждый раз необходимо окунать в муку. Если под рукой не оказалось формочек, можно просто порезать тесто на ромбики, квадраты и так далее. Смешать сахар с маком, обмакнуть в эту массу все печенья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4775,'Можно просто посыпать печенье сахарной пудрой. Положить рассыпчатое сметанное печенье на сухой противень. Готовить минут 20, соблюдая температуру 180 градусов. Если печенье тонкое, то на приготовление хватит 15 минут. Готовое печенье подавать с любимым напитком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4776,'Взбить в блендере до однородной смеси. Разлить чернично-банановый смузи без сахара в бокалы и сразу подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4777,'Почистить и вымыть кальмары. Промыть хорошенько сердцевидки и мидии. Желательно обдать кипятком. Налить в объемную кастрюлю воду и вино, положить приправы, лук, довести до кипения. Положить в кастрюлю кальмары, готовить минут 10, вынуть шумовкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4777,'Сердцевидки и мидии бросить в воду и готовить, пока они не раскроются. Достать из воды, не раскрывшиеся раковины и выбросить.В конце приготовления бросить креветки в слегка кипящую воду. Отваривать минуты 4 (в зависимости от размера).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4777,'Очистить раковины и креветки. Приготовить маринад: соединить сок лимона, соль, уксус, оливковое масло. Почистить и измельчить чеснок. Положить в маринад. Вылить подготовленный маринад к морепродуктам, влить туда же процеженный бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4777,'Оставить мариноваться – на это уйдет минимум полчаса. Перед подачей салат из морепродуктов в соке лимона посыпать измельченной петрушкой. Украсить салатик кусочками лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4778,'Отварите пасту по итальянской технологии. В кипящую подсоленную воду влейте пару столовых ложек растительного масла и положите пасту. Варить до состояния аль-денте, то есть полутвердой. В середине, паста должна иметь приятный хруст, но не липнуть к зубам. Отваренную пасту откинуть на дуршлаг и дать стечь воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4778,'Затем выложить ее в чистую, сухую посуду. Необходимо оставить 1 стакан воды, в котором варилась паста. В рецепте, большое значение имеет соус. Для его приготовления мелко порезанный лук-шалот обжарить на сливочном масле до мягкости. Затем влить сливки и немного потушить. Через 5 минут всыпать горошек и ломтики прошутто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'Чтобы начинка была вкусной и сочной, фарш необходимо делать самим. Мясо должно быть крупного помола, чтобы были видны кусочки мяса. Лук очистить и перемолоть с фаршем. Чем больше лука, тем сочнее будет начинка в чебуреках.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4884,'Сделать из фарша бифштексы и обжарить с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4778,'Проварить еще 4 минуты, влить лимонный сок и добавить цедру и убрать соус с огня. Густой соус нужно разбавить водой, в котором варилась паста. Добавить соус в кастрюлю с пастой, посыпать тертым сыром, посолить и поперчить по вкусу. Подавать блюдо теплым, выложив порционно. Перед подачей украсить пасту тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4779,'Для того чтобы приготовить омлет с макаронами, необходимо взбить яйца венчиком или вилкой до однородной консистенции. Добавить сваренные макароны и тертый сыр, хорошо размешать. Добавить соль и перец по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4779,'Форму для выпекания смазать растительным маслом и выложить половину макарон с яичной массой. Сверху выложить слой тонко порезанной копченой колбасы. На колбасу выложить остальные макароны и поставить противень в разогретую духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4779,'Выпекать омлет 25-30 минут, обжаривая его с двух сторон. Когда появится румяная корочка – блюдо готово. Подавать омлет со сметаной или майонезом. Омлет с макаронами под сыром вкусен как холодный, так и горячий.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4780,'Для приготовления салата «Дружба» необходимо сделать 2 омлета из яиц, поджарив их на сливочном масле. Затем омлеты нарезать на тонкие полоски. Свежий огурец порезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4780,'Сырок и копченую колбасу нарезать маленькими кубиками. Соединить все ингредиенты, добавить консервированный горошек. Салат промазать майонезом. Выложить в салатник и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4781,'Основой домашней пиццы является слоеное тесто, которое можно купить в любом продуктовом магазине. Один пласт необходимо тонко раскатать и выложить на противень для выпекания. Тесто смазать томатным соусом или пастой, в которую добавлен давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4781,'Затем посыпать тертым сыром. Чем больше тертого сыра в этом слое, тем больше будет он тянуться в уже готовой пицце. А это главная изюминка итальянского блюда. Затем необходимо разложить по тесту нарезанный сладкий перец, который придаст необыкновенный аромат блюду, варенное куриное мясо и жареные грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4781,'Брокколи обжарить на сливочном масле или немного отварить в подсоленной воде. Добавление этого ингредиента сделает пиццу полезной и красивой. Разложить соцветия брокколи по основе пиццы. Помидор также является незаменимым ингредиентом для пиццы. Его необходимо нарезать тонкими кружками и выложить по блюду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4781,'Маслины тоже нарезать тонко, кружками и разложить по всей поверхности пиццы. Все присыпать тертым сыром и поставить в разогретую духовку на 20 минут. Когда быстрая домашняя пицца с брокколи приобретет характерный золотистый цвет, ее можно доставать и угощать свою семью и друзей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4782,'Пресный творог (творог для долгожителей) готовится из молока и лимона. Молоко не киснет под действием бактерий, оно сворачивается от кислой среды лимонного сока. Для приготовления такого творога необходимо отжать сок с одного лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4782,'Молоко вылить в эмалированную кастрюлю. Поставить молоко на огонь и довести почти до кипения (не кипятить). В горячее молоко влить лимонный сок и быстро размешать ложкой. Снять с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4782,'Молоко начнет творожиться (сворачиваться), это и есть лечебный, пресный творог на лимоне. Его необходимо откинуть на мелкое сито и процедить, а сыворотку слить в отдельную посуду. Пресный творог готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4783,'Для приготовления нежной рыбы в сырном суфле необходимо выбирать белую рыбу с минимальным количеством костей. Рыба будет запекаться под сырным соусом, поэтому кости могут испортить впечатление от блюда. Филе рыбы необходимо порезать на порционные куски, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4783,'Противень для запекания застелить бумагой и выложить на нее рыбу, отделяя кусочки, друг от друга. Теперь необходимо сделать сырный соус. Яйца взбить миксером в пышную пену. Сыр натереть на мелкой терке и смешать с яичной пеной, продолжая взбивать миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4783,'Посолить по вкусу. Залить соусом рыбу и поставить противень в духовку на 40 минут, запекать при температуре 180 градусов. Когда сыр зарумянится, нежная рыба под сырном суфле готова. Подавать блюдо горячим, нарезав порционными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4927,'Мелко порубить зеленый лук и ветчину, смешать с желтковой массой и тертым сыром пармезан. Выложить в половинки яиц, украсить зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'Еще стоит добавить в фарш пол стакана ледяной воды, это также для сочности. Фарш посолить и поперчить по вкусу. Теперь необходимо правильно приготовить тесто, чтобы жареная корочка была хрустящей и вздутой. В муку необходимо влить горячую воду и замесить заварное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'В другую посуду всыпать муку, вбить яйцо, влить масло, водку, посолить и добавить сахар. Хорошо вымесить, затем влить заварное тесто. Еще раз тщательно вымесить, чтобы тесто не липло к рукам, а поверхность была блестящей и гладкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'Затем из теста сделать шар и обернуть пленкой. Оно должно отдохнуть 30 минут. Для лепки чебуреков необходимо использовать много муки. Шар теста разрезать на небольшие шарики и от них отщипывать небольшие кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'Маленький кусок теста необходимо раскатать в очень тонкий пласт, при этом присыпая тесто и скалку мукой. В середину теста выложить начинку и закрепить края чебуреков, зажимая их вилкой. Раскалить сковороду и налить в нее много рафинированного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4784,'Когда масло начнет закипать, очень аккуратно выкладывать на сковороду чебуреки и обжаривать их с двух сторон, до золотистого цвета. Жареные хрустящие чебуреки «Под градусом» выкладывать на бумажное полотенце, чтобы убрать лишний жир и  можно наслаждаться вкусом домашних чебуреков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4785,'Для приготовления салата необходимо отварить яйца (15 мину), картофель варить до готовности. Нарезать все средними кубиками и сложить в миску. Маринованные грибы необходимо нарезать небольшими полосками или пластинами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4785,'Маслины нарезать кружочками. Ананасы нарезать небольшими кубиками. Отварное куриное филе порезать средними кубиками, сыр натереть на крупной терке. Все сложить в общую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4785,'Консервированную кукурузу высыпать ко всем ингредиентам и добавить майонез. Аккуратно размешать салат. Грибной салат с ананасом и курицей подавать на широкой тарелке. Перед подачей украсить целыми маслинами и кусочками ананасов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4786,'Для приготовления шариков необходимо отварить куриное мясо и порезать на очень мелкие кубики. Отварную морковь натереть на терке. Какую использовать терку для моркови, выбирайте сами. С мелко натертой морковью шарики будут нежнее. Пряный сыр натереть на крупной терке, укроп мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4786,'В массу добавить майонез и молотый перец. Все тщательно размешать и сформировать шарики, размером с грецкий орех. Твердый сыр натереть на мелкой терке. Готовые шарики обвалять в сырной присыпке. Выложить горкой закуску «Наивкуснейшие шарики» на широкую тарелку и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4787,'Для приготовления творожной запеканки, следует взбить миксером или блендером такие ингредиенты: творог, любой жирности, главное, чтобы не сухой, взбитые в пену яйца, сахарный песок и ванилин, мягкое сливочное масло, манную крупу и молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4787,'Взбивая массу, очень аккуратно всыпать манку. Однородную массу выложить в форму для выпекания, смазанную растительным маслом. Отставить на 30-10 минут для того, чтобы манная крупа набухла в тесте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4787,'В разогретую духовку поместить противень с тестом и выпекать при температуре 180 градусов 40 минут. Готовность пробовать спичкой. Простую ванильную запеканку можно полить перед подачей сгущенным молоком или сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4788,'Куриные грудки надрезать пополам, не разрезая до самого конца. Раскрыть как книгу и выложить на пищевую пленку. Филе отбить кулинарным молоточком так, чтобы не образовалось дырочек в мясе. Смешать соль, орегано и черный перец. Приправить смесью отбитое филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4788,'На один край положить сыр и ветчину. Филе свернуть в плотный рулет, без отверстий. Скрепить с помощью зубочистки. Натереть сыр пармезан на мелкой терке. Смешать его с панировочными сухарями, чесноком и паприкой. На водяной бане растопить сливочное масло и обвалять в нем рулетики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4788,'Затем рулеты обвалять в сухарно-сырной панировке. Выложить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Яйца взбить с солью и содой. Муку насыпать горкой на стол, сделать лунку и в нее вылить взбитые яйца. Замесить мягкое, нелипкое тесто. Тесто завернуть в пакет и убрать на 15 минут. Тесто разделить на 2 части и каждую раскатать на припыленном мукой столе. Раскатанное тесто убрать на 10–15 минут для подсушивания (не на сквозняк).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Тесто не должно стать ломким, иначе его будет трудно потом разрезать. Порезать тесто на полоски шириной около 5 см. Полоски сложить пополам, присыпав мукой, а затем друг на дружку, по 3 полоски. Порезать полоски лапшой и раскидать ее на столе, чтобы не слиплась. Хорошо нагреть растительное масло в казане.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Маленькими порциями обжарить лапшу на среднем огне. Для порции брать примерно горсть лапши. Жарить быстро, по 1–2 минуты, до светло золотистого цвета. Лапшу вынимать шумовкой и выкладывать в тарелку на бумажные салфетки. В кастрюле с толстыми стенками приготовить сироп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Смешать 1 стакан меда с 1 стаканом сахара и разогреть их до кипения, постоянно мешая. Прокипятить 3 минуты и выключить плиту. Миндаль сложить в шумовку и окунуть в разогретый мед. Убрать миндаль в отдельную посуду. Из тарелки с обжаренной лапшой убрать салфетки и полить лапшу горячим сиропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Перемешать аккуратно двумя деревянными лопатками, а потом руками, смоченными в холодной воде. Мешать осторожно, чтобы не помять лапшу и не обжечься об горячий медовый сироп. Блюдо для чак-чака сбрызнуть холодной водой и быстро, пока не остыл, выложить чак-чак горкой, не прижимая его.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4789,'Сверху украсить медовым миндалем. Можно для украшения использовать и грецкий орех, и изюм, и разноцветные посыпки. Чак-чак убрать в темное место, чтобы он окончательно закрепился. Хранить татарский Чак-чак с миндалем можно 1–2 недели в шкафу, прикрыв его пленкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4790,'Перекрутить печень на мясорубке.  Перемешать с яйцами, содой и солью. Влить к печени молоко, перемешать и насыпать муку. Снова перемешать. Обжарить на сковородке на медленном огне, выкладывая небольшие оладьи из печени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4790,'Очистить и измельчить чеснок. После того как оладьи остынут, смазать их майонезом смешанным с чесноком. Закусочные оладьи из печени выложить на блюдо, украсить по желанию и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4791,'Отварить яйца вкрутую и потереть на крупной терке 2 яйца целиком и отдельно потереть белки и желтки оставшихся двух яиц. Лук порезать половинками колечек и обжарить. Грибы порезать и пожарить. Остудить. Открыть банку со шпротами и вилкой их размять. Если сухарики крупные, то помять и их.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4791,'Выложить в сервировочное блюдо салат слоями. Вначале яйца, потом шпроты, лук, майонез, затем высыпать сухарики, помазать майонезом, выложить грибы, 2 белка, майонез и в конце 2 желтка. Слоеный салат из грибов со шпротами поставить на 2,5 часа в холодильник, чтобы пропитался и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4792,'Порезать крабовые палочки наискосок, кольцами средней толщины. Помыть помидоры и нарезать кубиками, вырезав плодоножку. Сок с помидоров слить. Очистить чеснок и мелко покрошить. Перемешать помидоры, чеснок и крабовые палочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4792,'Салат заправить майонезом, посолить и добавить перец. Салат окончательно перемешать и выложить в порционные креманки. Украсить свежим укропом и подать крабовый салат-коктейль с помидорами к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4793,'Рукколу вымыть и высушить. Помыть помидоры и нарезать ломтиками. Выложить их в салатницу. Рукколу порвать руками и выложить к помидорам. В салатник выложить оливки, слив предварительно рассол. Сбрызнуть ингредиенты оливковым маслом и посолить. Хорошо перемешать легкий салат из томатов с оливками, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4794,'Отварить рис для суши. Заправить рис уксусом, перемешать. Уксуса добавлять по вкусу. Мидии промыть от масла и, если они крупные, порезать их пополам. Листы нори выложить на коврик для роллов и разрезать пополам. Выложить рис. В середину нанести полоску плавленого сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4794,'Выложить имитацию красной икры, ее лучше вдавить прямо в рис, чтобы потом она не высыпалась из готовых роллов. Мидии выложить полоской на сыр, свернуть ролл и нарезать. Роллы с мидиями и сыром выложить на блюдо и подать с соевым соусом и васаби.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4795,'Промыть рис не менее 7 раз и оставить сохнуть в сите, на 1 час. Затем залить водой, поставить на средний огонь, закрыть кастрюлю крышкой и довести до кипения, убавить огонь и варить в течение 13 минут. Затем выключить плиту и оставить рис в кастрюле, не открывая крышку, еще на 13 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6403,'На сковороде раскалить масло, пожарить рыбу до румяной корки, переложить на бумажное полотенце для выхода лишнего жира.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4795,'Уксус, сахар и соль смешать и влить в рис. Перемешать лопаткой и оставить остывать. Почистить авокадо и порезать ломтиками. Крабовое мясо разобрать вилкой на волокна. Тонкими ломтиками нарезать лосось. Взбить яйца и пожарить тонкие яичные блины. Нарезать блины соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4795,'Васаби и майонез смешать. Рис разделить на 5 частей. Форму выстелить пищевой пленкой и выложить на дно креветки. Сверху выложить слой риса и смазать смесью майонеза с васаби. Затем выложить слой семги и снова намазать смесью майонеза и васаби. Следующий слой – рис, потом крабовое мясо и снова смазать соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4795,'Снова слой риса, слой порезанных блинчиков и опять смазать соусом. Затем выложить последнюю часть риса, завернуть наверх концы пленки и прижать чем-то тяжелым, отставить на час. Готовый суши-торт с креветками и авокадо опрокинуть на блюдо и присыпать кунжутом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4796,'Яйца отварить и очистить. Размять вилкой яичные желтки, смешать с растительным маслом. Положить в яично-масляную смесь горчицу и уксус. По вкусу добавить соль, сахар и перец. Перемешать до однородности. В миску вылить сметану. Подготовить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4796,'Можно порубить мелко вручную или перекрутить в мясорубке, а можно часть измельчить в блендере, а часть мелко порезать. Главное, чтобы остались небольшие кусочки трав для красоты. Зелень выложить к сметане, добавить желтковую смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4796,'Мешать, пока соус не станет однородным. Порубить мелко белок и добавить его к соусу. Соус отставить и дать настояться, при комнатной температуре, в течение 1 часа. Подавать зеленый франкфуртский соус на сметане к мясу или вареному картофелю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4797,'Измельченный корень имбиря залить стаканом вскипяченной воды. Дать настояться и остудить до 40 градусов. В остывший имбирный чай добавить мед и дольку лимона. Имбирно-медовый чай с лимоном готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4798,'Порезать дольками очищенные яблоки и выложить в форму, на дно, ровным слоем. Для приготовления теста взбить яйца с сахаром и солью. Загасить соду уксусом и добавить к яйцам. Всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4798,'Перемешать и замесить жидкое тесто. Вылить его поверх яблок в форму. Поставить пирог в духовку на полчаса. Готовую яблочную шарлотку немного остудить, присыпать сахарной пудрой и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4799,'Полукольцами нарезать лук и немного обжарить. Порезанный болгарский перец выложить на сковородку и обжарить еще пару минут. Нарезанные колбаски также выложить на сковородку и перемешав с овощами, тут же, выключить плиту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4799,'Картошку крупно натереть на терке, добавить давленый чеснок, яйца, соль, перец и всыпать муку. Основу перемешать. На сковороде разогреть 2 ст. л. растительного масла и выложить основу из картофеля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4799,'Огонь уменьшить до среднего и жарить примерно 5 минут. Сметану и горчицу перемешать. Натереть сыр и порезать помидоры черри пополам. Картофельную основу аккуратно перевернуть. Через пару минут выложить на нее начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4799,'Разложить половинки помидоров, посыпать сверху сыром и зеленым луком. Закрыть крышкой и убавить огонь. Томить пиццу пока не расплавится сыр. Картофельная пицца с колбасой и сыром готова. Перед подачей нарезать пиццу на сегменты и можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4800,'Растворить в теплом молоке дрожжи. Сахар, муку и соль смешать вместе. В мучную смесь влить дрожжевую и хорошо перемешать. К тесту добавить цедру лимона и растопленное сливочное масло. Вымесить тесто еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4800,'Оно должно получиться мягким и лишь чуть-чуть липким. Тесто скатать в шар и переложить в чашу, слегка обмазанную маслом. Накрыть пленкой и оставить в тепле на 2 часа. Когда тесто увеличит объем вдвое, убрать чашу в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4800,'Достать тесто из холодильника за 2–3 часа до выпечки. Сахар, сметану и яйца хорошо перемешать. Раскатать тесто, переложить в форму. Надрезать края теста. На тесто выложить сметанную начинку. Поставить в духовку с температурой 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4800,'Через 30 минут проверить готовность пирога – если его немного потрясти, то серединка начинки должна немного колыхаться. Татарский лимонный сметанник остудить, лучше всего в холодильнике, оставив его там на ночь. Подавать с любимыми напитками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'Форму для выпекания смазать маслом или застелить пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4801,'Перетереть сметану и творог с обычным и ванильным сахаром. Взбить яйца в пышную пену и перелить к творогу. Добавить к ним изюм и манку, перемешать. Смазать маслом форму. Залить в форму яичную смесь, разровнять поверхность лопаткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4801,'Сверху на тесто выложить яблоки, нарезанные тонкими пластинами. Посыпать сверху сахаром или манкой. Поставить в духовку с температурой 200 градусов. Через 35–40 минут нежная запеканка из творога с яблоками будет готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'Разогреть воду, не доводя до кипения, и ввести масло и соль. Смешать. Добавить муку, и вымешивать венчиком, не снимая кастрюлю с плиты. Когда образуется комок переложить тесто в миску и вбить яйца. Вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'На бумаге нарисовать контуры будущего торта (чтобы все коржи получились одинакового размера), например, 25х18 см. Заварное тесто выложить кондитерским шприцем с круглой насадкой по контуру будущего коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'Затем тесто выложить в серединку полосками вдоль, а потом поперек. Запечь корж в духовке при 200 градусах. Нужно чтобы корж слегка зарумянился. Второй корж сделать с косыми полосками в середине. Так поочередно сделать 4 коржа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'Для крема: смешать яйца, сахар и крахмал. Хорошо растереть и ввести молоко. Перемешать и поставить на огонь. Как только крем закипит, снять с плиты и остудить. В сливочное масло, небольшими порциями, ввести теплый крем постоянно мешая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'Намазать корж кремом и положить в отверстия кусочки фруктов. Например, вишня, банан и персики. Или можно положить вишню, киви, персики – на свой вкус. Накрыть следующим коржом и слегка прижать, намазать крем и снова положить фрукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4802,'Верхний корж украсить белым шанти. Сверху выложить фрукты. Торт «Тропиканка» с фруктами поставить в холодильник для пропитывания и застывания крема. Готовый торт подать к праздничному столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4803,'Разобрать цветную капусту на соцветия, положить в кипящую воду (подсоленную) минуты на 3. Затем откинуть ее на дуршлаг, чтобы стекла вся вода. Филе куриное порезать небольшими ломтиками (толщина 0,5 см, а длина 5-6 см), поперчить и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4803,'Соус: натереть на мелкой терке сыр, выдавить через пресс чеснок. Подогреть на сковородке сливки. Добавить тертый сыр, перец и соль. Держать соус на огне, пока сыр полностью не растает, потом положить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4803,'В форму (смазанную маслом) уложить филе, потом положить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4804,'Измельчить половину овсяных хлопьев в муку. Оставшуюся часть овсяных хлопьев залить кипятком (2 стакана) и отставить в сторону. Взбить в емкости творог и йогурт. Добавить сок и цедру лимона, оливковое масло и тщательно смешать. Затем вбить яйцо и опять перемешать. Муку вместе с разрыхлителем просеять, добавить сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4804,'Всыпать муку в смесь с творогом, перемешать. Затем смешать творожную массу с мукой из овсяных хлопьев. Добавить запаренные овсяные хлопья. Оставить тесто минут на 20, чтобы настоялось. Сковородку разогреть, смазать маслом (кисточкой). Выкладывать тесто ложкой и жарить минуту или две с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4804,'Ягодный соус: положить в чашу блендера ягоды и йогурт (3 столовые ложки), по желанию можно также добавить и 2-3 ложки сахарной пудры (не для диетического варианта), хорошо взбить. Выложить оладьи на тарелку и полить ягодным соусом. Овсяные оладьи с творогом и голубикой подать на завтрак.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4805,'Дрожжи развести в воде (обязательно теплой), положить туда также соль, масло и сахар. Муку просеять и постепенно, небольшими частями, добавить в жидкость. Вымесить тесто. Смазать емкость маслом и положить в нее тесто, прикрыв сверху салфеткой. Отправить тесто в теплое, сухое место, чтобы поднялось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4805,'Все ингредиенты для соуса смешать, переложить в сотейник и тушить минут 15-20, осторожно разминая деревянной лопаткой. Добавить томатную пасту (1 чайную ложку), немного соли, потушить минуты 2 и снять с огня. Тесто разделить на 4 части (получится 4 небольшие пиццы). Очень тонко раскатать, положить пласт теста на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4805,'Присыпать тесто моцареллой, затем натертым на терке мерзлым сливочным маслом (тонкий слой). Смазать томатным соусом, присыпать пармезаном и опять моцареллой. Печь пиццу с сыром по-домашнему в духовке, при 200 градусах. Готовую ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4806,'Сыр натереть на крупной терке. Форму для выпекания густо намазать сливочным маслом. Лаваш нарезать по размеру формы. Уложить одну лепешку из лаваша в форму и смазать ее слоем майонеза (тонким). Притрусить сыром (чем больше, тем вкуснее) и накрыть сверху следующей лепешкой. Также повторить и с остальными кругами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4806,'Налить в емкость молоко, вбить яйца, положить соль и взбить миксером. Перелить взбитый омлет на пирог. Поставить пирог в духовку (200 градусов), приблизительно на полчаса, пока не появится красивая корочка золотистого оттенка. Готовый сырный пирог на лаваше подавать в качестве закуски, предварительно порезав на ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4807,'Срезать с хлеба корочку, взбить масло с перцем и томатной пастой. Сыр и колбасу необходимо порезать тонкими ломтиками. Взять один кусок хлеба, смазать его масляной смесью, положить на него колбасу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4807,'Затем взять следующий кусок хлеба, смазать маслом, и положить на слой колбасы (вниз маслом) и немного прижать. Сверху смазать его маслом, положить на него сыр. Тоже сделать с остальными кусками хлеба (в итоге должно получиться пару слоев сыра и колбасы).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4807,'Уложить готовый бутерброд под пресс (только легкий) и отправить в холодильник. Перед подачей порезать оригинальный полосатый бутерброд поперек, на небольшие кусочки и украсить зеленью. Подавать на сервировочном блюде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4808,'Вареную колбасу нарезать ломтиками и согнуть их пополам. Уложить их на поверхность в виде дорожки (немного накладывая один на другой). Затем из уложенных ломтиков скрутить валик, начиная со сгиба первого ломтика. Валик завязать пером зеленого лука в нижней четверти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4808,'Срезать основание (чтобы придать цветку устойчивость). Вокруг сердцевины, разложить сложенные четвертинками ломтики колбасы – они буду нижними лепестками цветка, сердцевину раскрыть. Украсить «Хризантему» из ломтиков колбасы зеленью и подать в качестве закуски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4809,'Срезать с батона корочку и размочить его в молоке. Кабачок отчистить от семян и кожуры, натереть на терке (мелкой). Лук и чеснок измельчить. Положить все к мясу. Перемешивать все ингредиенты, прибавить перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4809,'Образовать котлеты, обвалять в панировочных сухарях и поджарить котлеты на масле, до золотистого оттенка. Кушать жареные курино-овощные котлеты с гарниром или на завтрак с кусочком хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4810,'Масло разделить на 3 куска – 1 большой и пару маленьких (по 10-15 грамм). Больший кусок масло расплавить на слабом огне и отставить в сторону. Желтки отделить от белков и взбивать, пока не загустеют (около минуты). Добавить к ним воду, соль и лимон и еще немного взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4810,'Добавить 1 маленький кусочек масла и поставить на водяную баню (60 градусов). Взбивать около 2 минут, пока масса не станет кремообразной и не загустеет. Убрать кастрюлю с плиты, положить второй кусочек масла и хорошо перемешать. Затем влить растаявшее масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4810,'Сначала добавляя по капле, постоянно взбивая, а потом немного большими порциями. Не нужно вливать осадок, который образовался на дне масла. Крем должен получиться густым (как жирные сливки). Соус поперчить и посолить, добавить лимонный сок. Соус голландский «Голландез»  необходимо подавать чуть теплым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4811,'Чеснок и морковь почистить (можно также класть и репчатый лук, кто, что любит). Морковь натереть, чеснок измельчить. Поджарить их вместе на растительном масле. В форму для выпечки налить немного растительного масла и всыпать сухой рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4811,'Добавить к нему обжаренный чеснок с морковью и кукурузу (жидкость слить заранее). Все тщательно смешать, поперчить, посолить. Залить кипятком (600 мл), опять перемешать. Разложить куриные ножки в шахматном порядке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4811,'Накрыть фольгой форму и отправить в духовку (200 градусов) на 45 минут. Когда пройдет указанное время, вынуть из духовки, снять фольгу и готовить еще 15 минут. «Ежкин рис» с куриными ножками готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4812,'Чеснок и имбирь измельчить и смешать с остальными ингредиентами для заправки. Миндаль и лапшу отложить в сторону. Капусту и перец нашинковать, морковь натереть на терке. Салат порвать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6406,'Далее в кипящую воду переложить кнели и варить их 5-7 минут, перекинуть в дуршлаг, окатить горячей водой и уложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4813,'Приготовить ленивое слоеное тесто. Маргарин или масло порубить в мелкую крошку с мукой (можно натереть замороженное масло на терке), смешать солью и сахаром. Добавить воду, перемешать. Сформировать шар и отправить его в морозилку (минут на 20-30). Сыр натереть на терке, мелко порезать ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4813,'Вынуть тесто из морозилки и раскатать (0,5 сантиметра толщиной). Уложить сверху сыр и ветчину. Свернуть рулетом, с двух сторон. Сворачивать необходимо очень быстро, так как тесто будет таять под руками. Порезать рулет на печенье (толщина 5-7 миллиметров).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4813,'Придать печенью форму сердечек и уложить на смазанный противень. Если не все печенья уместились на противень, то остальные заготовки необходимо убрать в холодильник. Отправить противень в духовку (200-250 градусов). Сытное печенье с сыром и ветчиной немного охладить и можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4814,'Для приготовления соуса очень мелко измельчить лук и чеснок, обжарить их в глубокой сковороде, в разогретом масле. Когда подрумянится, добавить измельченные помидоры вместе с соком. Поставить воду для варки пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4814,'Добавить к соусу соль (немного), сахар (0,5 чайной ложки), приправу и тушить еще минут 5. Сюда же добавить каперсы и очень мелко порезанные анчоусы. Когда вода закипит, отварить в ней макароны. Паста должна быть немного не доварена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4814,'Добавить содержимое банки тунца к соусу. Соус тушить примерно 15 минут, пока варятся макароны. Слить воду с пасты, добавить к соусу и перемешать. Лингвини аль-тонно с тунцом сразу же подать на стол и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4815,'Взбить яйца до плотной белой массы, добавить мед и сахар (взбивать не менее 10 минут). Объем должен вырасти примерно в 4 раза. Потом добавить муку и осторожно перемешать снизу вверх. Застелить бумагой для выпечки форму и перелить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4815,'Несколько раз резко крутнуть форму, чтобы поверхность теста стала гладкой и ровной. Выпечь в духовке (170-180 градусов), готовность проверять шпажкой. Охлаждать обязательно в форме. Готовый бисквит ножом отделить от стенок формы и вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4815,'Нарезать его на 3 части вдоль, смазать два нижних коржа вареной сгущенкой или сгущенкой взбитой с маслом. Верхний корж полить глазурью и присыпать орехами. Бисквит можно кушать сразу, с любимым напитком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4816,'Приготовить кус-кус – залить крупу кипятком, добавить соль, толченые семена кориандра, зиры, оливковое масло (половину количества, что указано в рецепте), закрыть пленкой и отставить на 10 минут, затем перемешать вилкой – кус-кус готов. Немного остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4816,'Помидоры черри порезать четвертинками, сладкий перец и фету нарезать небольшими кубиками, листья базилика оторвать от веток. Все ингредиенты перемешать, заправить оставшимся оливковым маслом, лимонным соком и подать салат с кус-кусом и сыром фета на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Опара: перемешать воду и молоко (смесь должна быть теплой), положить дрожжи и всыпать муку (около 400 грамм). Хорошо смешать и отправить в теплое, сухое место на 1,5-2 часа (накрыть сверху). Растопить и немного охладить маргарин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Добавить сахар, яйцо, соль, перемешать. Влить смесь к опаре, прибавить оставшуюся муку и замесить тесто. Месить необходимо долго, пока тесто не перестанет липнуть к стенкам посуды и к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Затем накрыть посуду с тесто салфеткой и снова вернуть в теплое место часа на 2. За данное время тесто необходимо раза 2 обмять и перевернуть. Начинка: перемешать молоко, мак, сахар и вскипятить. Затем огонь убавить и варить еще минут 5-7 (мешать), пока мак не набухнет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Закрыть посуду с маком крышкой и отставить в сторону, чтобы остыл. Тесто раскатать толщиной полсантиметра, распределить по нему маковую начинку. Скрутить рулетом и нарезать кусочками толщиной 2 сантиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Разложить куски на противень, оставив между ними пространство. Накрыть сверху полотенцем и оставить минут на 40-50, для расстойки. Выпекать в духовке (180 градусов), до золотистого оттенка. Охладить, при этом накрыв полотенцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4817,'Глазурь: в воду добавить сахарную пудру и взбивать миксером, пока пудра не растворится. Затем добавить лимонный сок. В итоге получится белая глазурь. Глазурью полить пышные «Улитки» с маком и кушать на завтрак с чаем или кофе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4818,'Морковь, картофель и лук измельчить (небольшими кубиками). Подогреть в кастрюле масло, положить морковь, лук и тушить, часто помешивая, пока лук не будет прозрачным (минут 5). Не передержите, чтобы овощи не приобрели коричневый оттенок. Потом влить бульон или воду, вскипятить, убрать пену и добавить измельченный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4818,'Варить на маленьком огне, пока кусочки картофеля не станут мягкими (минут 15-20). Положить в суп соль и лавровый лист. Щавель порубить, добавить в кастрюлю и подождать, пока он поменяет цвет. Добавить черный перец молотый и по вкусу можно еще посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4818,'Варить еще минут 7, потом добавить измельченную зелень и убрать с плиты. Яйца сварить вкрутую (расчет – пол яйца на человека) и порезать кубиками. Подавать щавелевый украинский суп в порционных тарелках, украсить травами. В каждую тарелку добавить яйцо и сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4819,'Филе куриное хорошо обмыть и высушить, нарезать его на маленькие кубики. Добавить перец и соль, смешать. Потом добавить яйца, измельченный чеснок и снова смешать. Положить измельченную зелень, сметану и муку, хорошо перемешать, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4819,'Тесто должно получиться жидковатым, как кляр. На сковороду (разогретую), влить масло и выкладывать ложкой тесто. Жарить котлеты с обеих сторон до золотистого оттенка (около 2 минут), на слабом огне. Подавать котлеты из курицы по-французски с любимым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4820,'Нагреть духовку (180 градусов), смазать сливочным маслом (растопленным) дно формы для выпечки. Взять 3 небольшие емкости. В одной из них смешать, соль, муку, порошок чесночный и перец. Во вторую разбить яйца и немного взбить. В третью емкость насыпать панировочные сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4820,'Разрезать куриные грудки пополам и немного отбить. Должно получиться 6 шницелей. На каждый куриный шницель положить по ломтику сыра и ветчины, плотно свернуть рулетом. Рулеты обвалять в муке (встряхнуть излишки), окунуть в яйца, а затем обкатать в панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4820,'Связать рулетики ниткой или скрепить зубочисткой и выложить в подготовленную форму. Запекать до золотистого оттенка (минут 30-35). В процессе приготовления несколько раз полить растопленным сливочным маслом. Подавать сочные куриные рулеты с начинкой горячими, с дижонской горчицей и майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4821,'Муку смешать с солью и просеять в емкость, добавить сахар и масло и месить руками – должны получиться крошки. Потом к ним добавить два желтка и замесить тесто. Сделать шар из теста, обернуть его пленкой и отправить в холодильник приблизительно на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4821,'Разогреть духовку (180 градусов). Вынуть тесто из холодильника, оставить минут 15. Затем тонко раскатать тесто (3-4 миллиметра), любой формочкой вырезать печенье. Переложить тесто на смазанный противень, смазать желтком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4821,'Присыпать сверху сахаром или кунжутом (можно и тем, и тем). Поставить в духовку минут на 15-20. Степень готовности определять по собственному вкусу. Переложить печенье песочное по-домашнему на тарелку, дать немного остыть и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4822,'Взять муку, сливочное масло (охлажденное), яйцо, ледяное молоко, соль (половину чайной ложки). Измельчить смесь муки, масла и соли в крошку. Вбить одно яйцо, влить молоко (2 столовые ложки) и быстро смешать. Должна выйти сырая крошка, которая без труда соберется в один комок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4822,'Очень долго месить это тесто нельзя, действовать необходимо быстро. Всю влажную крошку собрать в комок (не месить), завернуть в пленку и положить в холодильник на час. Начинка: отваренный в мундире картофель нарезать небольшими кубиками, также нарезать ветчину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4822,'Шампиньоны порезать пластинками или кубиками (форма не важна), обжарить их на сливочном масле, жидкость должна выпариться полностью. В емкости смешать грибы, картофель, тертый сыр, измельченную зелень и ветчину. В маленькую мисочку разбить яйцо и немного взбить. Половину взбитого яйца смешать со сливками и добавить в начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4822,'Половину яйца оставить, чтобы смазать им пирог. Начинку посолить и поперчить. Вынуть тесто из холодильника, разделить его напополам, каждый кусок тонко раскатать (3 миллиметра). Переложить один пласт теста в форму (22-24 сантиметра в диаметре), сформировать бортики, выложить начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'В самом конце положить измельченную зелень.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4822,'Сверху прикрыть вторым пластом теста и защипать по кругу. В середине пирога нужно сделать маленькое отверстие, туда будет выходить пар. Верх пирога смазать яйцом. Печь в духовке минут 25-30 (190 градусов). Подавать картофельный тарт с грибами как основное блюдо, с овощным салатом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4823,'Тесто: смешать маргарин (немного растопить), сахар и яйца. Добавить сметану и соль, смешать. Потом прибавить муку, разрыхлитель и вымесить тесто. Ненадолго его отложить. Начинка: все компоненты для начинки смешать в одной емкости. Она должна получиться густой и не растекаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4823,'Тесто раскатать (не тоньше, чем пол сантиметра) и вырезать кружочки. Начинку уложить на один край кружочка, по бокам немного защипать, а спереди сочники оставить открытыми. Выложить сочники с творогом по-домашнему на противень, смазать яйцом. Отправить в духовку минут на 15 (190 градусов). Готовые сочни остудить и кушать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4824,'Баклажаны вымыть, обрезать хвостики, порезать кружками и обжарить их на сковородке, готовые сложить горкой. Жарка баклажан – самая ответственная работа – необходимо следить, чтобы не подгорели, чтобы сверху была золотистая корочка, но внутри они были мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4824,'Картофель отварить в мундире, почистить и тоже нарезать кружочками. Очистить и нарезать кружками перец. Помидоры также нарезать кружочками. Для укладывания мусаки больше всего подходит круглая форма (очень красиво смотрится). Сначала взять кружочек баклажана, потом положить рядом картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4824,'Затем уложить помидоры и кружки перца (если они очень большие, то лучше либо отрезать лишнее, либо разрезать пополам). Осень важно – плотно укладывать. Сначала необходимо заполнить внешний круг, потом перейти к внутреннему кругу. Когда все овощи будут плотно уложены, то мусаку посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4824,'Затем присыпать измельченным чесноком, налить немного масла (1 столовую ложку). Потом все залить взбитыми яйцами, присыпать тертым сыром и можно ставить в духовку (180-200 градусов), минут на 30-40, пока не образуется золотистая корочка. Болгарская мусака с сыром готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4825,'Тесто: смешать сахар, муку, соль и охлажденное масло, чтобы образовалась крошка. Постепенно добавляя воду и вымешивать, пока из теста не получится сформировать шар. Завернуть тесто в пленку и положить в холодильник на полчаса. Затем тесто достать, раскатать в тонкий пласт и уложить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4825,'На тесто выложить и распределить равномерно по всей поверхности в крошку измельченные орехи и печенье. Пюре: тыкву нарезать кубиками, отправить в духовку минут на 25. Дать остыть, а потом сделать из нее блендером пюре (2 стакана пюре – 1 килограмм тыквы).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4825,'Во взбитое пюре добавить сахар, сливки, корицу и взбитые яйца, смешать. Пюре выложить в форму на слой печенья с орехами и оправить в духовку (190 градусов), минут на 40-50. Перед подачей классический пирог из тыквы можно украсить шоколадом, сиропом или взбитыми сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4826,'Высыпать макароны в кастрюлю мультиварки, добавить соль и влить бульон. Закрыть крышку и готовить 15 минут (программа Суп). В процессе приготовления макароны перемешивать, чтобы они не прилипли к кастрюле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4826,'По истечении времени бульон должен быть полностью поглощен макаронами. Пока макароны варятся, необходимо подготовить и нарезать ингредиенты. Подойдут любые замороженные овощи (цветная капуста, брокколи, морковь и другие), в разных сочетаниях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4826,'Необходимо учитывать, что овощи еще немного будут готовиться с макаронами, поэтому их надо чуть-чуть не доварить. Варить их необходимо в кипящей воде (подсоленной), недолго. Например, зеленый горошек варится минуты 3-4.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4826,'Когда макароны будут готовы, добавить к ним молоко, тертый сыр, перец молотый, масло и овощи. Готовить еще минут 10, пока сыр не расплавится, а молоко полностью не впитается (программа Тушение).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4826,'Необходимо опять пару раз перемешать. Вкусный ужин макароны под сыром с овощами готов. Отлично подойдет к тушеному мясу, курице или к колбасе, сосискам. Подавать блюдо горячим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4833,'Нарезать печень небольшими ломтиками и слегка отбить. Затем, порезать ее полосками, переложить в емкость и присыпать крахмалом (2-3 ложки). Добавить соль и молотую паприку (по 1 столовой ложке). Можно также добавить острый молотый черный перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4827,'Разогреть в сковороде большое количество масла. В сосиски воткнуть деревянные палочки. В емкости взбить яйца, молоко, масло растительное (1/4 стакана). В другой емкости смешать сахар, муку (1,5 стакана), кукурузную муку, соль, разрыхлитель. Смешать смеси вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4827,'На плоскую тарелочку положить немножко муки, обкатать сосиски вначале в муке, потом в тесте и окунуть в разогретое масло. Обжарить оригинальный хотдог до золотистой корочки со всех сторон и переложить его на салфетку, чтобы прибрать лишний жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4828,'Поставить вариться мясо. Бульону для солянки надлежит быть крепким и насыщенным. Отварное мясо, колбасу, сосиски и ветчину порезать тонкими кусочками. Соленые огурцы также измельчить (наискосок, полосками или в виде ромбиков).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4828,'Лук репчатый порезать кольцами. Пассировать лук вместе с томатным пюре на оливковом масле. Положить в кипящий бульон колбасные изделия, мясо и готовить, пока не закипит. Потом добавить лук и огурцы, опять дать закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4828,'Уменьшить огонь и минут 10 варить. Затем положить лавровый лист, каперсы и маслины, чтобы они прогрелись. Выключить огонь, разлить солянку домашнюю с лимоном в порционные тарелки, положить сметану, ломтик лимона и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4829,'В форму для выпечки укладывать слоями. Нарезать картофель кружочками и уложить на дно формы, присыпать перцем и солью (1 слой). Измельчить грибы и лук, обжарить на сковородке и уложить на слой картофеля (2 слой). На грибы выложить фарш, присыпать его специями, перцем и солью (3 слой).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4829,'Потом выложить смесь овощей (4 слой). Промазать майонезом и поставить в духовку минут на 40-45 (180 градусов). Потом вынуть, присыпать сверху сыром, натертым и поставить в духовку снова минут на 10. Овощи запеченные с фаршем подавать на стол порционно, присыпав по желанию свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4830,'Ягоды промыть и высушить и обвалять в крахмале или в муке. Отделить от белков желтки, белки взбить в пену. Желтки добела перетереть с сахаром. Смесь из желтков тоненькой струйкой добавлять в белки и взбивать миксером. Муку перемешать с ванилином, просеять, маленькими частями прибавлять в жидкую смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4830,'Перемешивать нужно осторожно снизу вверх и лишь в одном направлении. Потом положить ягоды и снова аккуратно смешать. Обжаривать бисквитные оладьи с ягодой на растительном масле, лучше на маленьком огне и под крышкой. Готовые оладьи подать теплыми.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4831,'Смешать сметану, ванилин, сахар, соду (погашенную). Добавить масло оливковое, муку и замесить тесто. Разрезать получившееся тесто на 4 части. Каждую из частей раскатать (0,5- 0,7 миллиметра) и с помощью тарелки вырезать из теста круги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4831,'Обрезки теста тоже раскатать. Каждый корж выкладывать на сухую (обязательно сухую!) сковородку и прокалывать вилкой по всей поверхности. Обжаривать с обеих сторон до золотистого оттенка. Коржи жарятся очень быстро, нужно следить, чтобы не подгорели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4831,'Потом коржи отставить остывать. Крем: лайм хорошо вымыть, снять с него цедру, выжать сок. Смешать сгущенное молоко, рикотту, сок и цедру лайма. Все взбить миксером. Крем получается не очень сладким, поэтому по желанию можно добавить еще сахарной пудры (2 ложки).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4831,'Каждый корж щедро промазать кремом, хорошо смазать бока. Украсить готовый торт  тертым шоколадом или кокосовой стружкой. Поставить сметанный торт с рикоттой в холодильник для пропитки на пару часов и можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4832,'Разноцветные перцы порезать соломкой (зеленый, красный и желтый). В курином бульоне отварить пасту. Соус: подогреть масло (3 столовые ложки) и куриный бульон (полстакана) в кастрюле, на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4832,'Когда масло растает, добавить измельченный чеснок, соль и перец (по 1 чайной ложке). Потом постепенно добавлять тертый сыр (полстакана). Варить на небольшом огне, часто помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4832,'Перец обжарить на масле (минут 6), выложить к нему куриное филе и влить соус. Тушить приблизительно 5 минут. Переложить на порционные тарелки пасту, сверху полить соусом. Пасту с сырным соусом «Альфредо» можно кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Измельченные орехи смешать с растертыми с сахаром желтками, добавить немного пшеничной муки и горячее молоко, постоянно помешивая, нагреть смесь на медленном огне и варить до загустения 6-8 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4833,'Выдавить чеснок, влить масло растительное, перемешать и отставить минут на 20. Соус: взять соевый соус, томатную пасту, мед, сюда же влить половину стакана кипятка. Тщательно перемешать, чтобы растворился мед. Печень, замаринованную, выложить на сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4833,'Влить немного масла и поджарить со всех сторон. Затем добавить лук (нарезанный полукольцами) и тушить минут 5-7. Залить соусом, перемешать, прикрыть крышкой и тушить минут 10. Сочная печень «Красавица востока» готова, на гарнир можно подать рис или любые овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4834,'Очистить картофель, нарезать его небольшими кубиками и отварить в подсоленной воде. Слить воду с картофеля и размять его толкушкой или пропустить через мясорубку. Переложить картофель в большую емкость и отставить минут на 20, чтобы он полностью остыл. Остывший картофель необходимо плотно утрамбовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4834,'Затем условно поделить его в миске на 4 части. Вынуть из емкости 1/4 часть картофеля (можно положить его сверху на утрамбованную поверхность), чтобы получилась выемка. В нее всыпать муку (2 столовые ложки) и крахмал, столько, чтобы смесь полностью заполнила выемку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4834,'Немного взбить 1 яйцо и добавить его в картофель. Всыпать в массу соль и замесить однородное тесто.Месить тесто необходимо долго (не менее 8 минут). Затем оторвать объемный кусок теста и сформировать из него колбасу (диаметр 2-3 сантиметра). Порезать ее на куски (толщина 1-1,5 сантиметра).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4834,'Каждый кусочек скатать в шарик и пальцем вдавить по центру, чтобы образовалась выемка. Сделать также и с остальным тестом. Вскипятить в кастрюле много воды, посолить, опустить часть клецек в воду, перемешать и варить минуты 4 после того, как они всплывут.  Вынимать клецки на большую тарелку и укладывать их в один слой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4834,'После варки клецки очень липкие, но через некоторое время (буквально 2 минуты) они приобретают необходимую консистенцию. Подавать польские картофельные клецки можно сразу же с любимым соусом или посыпать жареными шкварками и луком. Также, клецки перед подачей можно обжарить до золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4835,'От рыбы отделить кости и острым ножом срезать кожу. Филе нарезать кусочками средней величины (чтобы были и не большие, и не маленькие кубики). Переложить ее в емкость, добавить к рыбе соевый соус (2 ложки), присыпать кунжутом и хорошо перемешать, чтобы и соус, и кунжут равномерно обволокли рыбу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4835,'Уложить рыбу на сковородку (разогретую), чтобы между кусками было пространство. Равномерно обжарить ее со всех сторон до золотистого оттенка и переложить на тарелку. Кабачки измельчить кубиками (около 1 сантиметра) и потушить на сковородке минут 5-7, часто мешая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4835,'Затем к ним добавить измельченный зеленый лук, и натертую лимонную цедру с лимонным соком. Поперчить, посолить и тушить минуты 2. Затем влить сливки и тушить еще пару минут. Перед подачей необходимо выложить на тарелку кабачки, а сверху кусочки рыбы. Лосось в кунжуте на овощной подушке готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4836,'Основа для пирога: перемешать сахар, муку и соль (можно воспользоваться комбайном). Масло сливочное порезать кубиками и добавить к смеси. Затем влить воду, миндальный экстракт и всыпать ванилин. Взбивать несколько минут. Переложить тесто на рабочую поверхность и вымесить руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4836,'Сформировать из теста диск, обвернуть его пленкой и положить в холодильник на полчаса — час. Начинка: все ингредиенты смешать в большой емкости. Духовку нагреть (200 градусов). Смазать форму маслом (сливочным) и застелить бумагой для выпечки. Вынуть из холодильника тесто и раскатать тонким пластом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4836,'Положить его в форму и мокрыми руками растянуть, чтобы тесто покрывало дно формы, ее стенки, а также немного свисало. Вылить начинку на тесто и прикрыть ее свисающими краями теста. Верх смазать яйцом и притрусить сахаром. Выпекать около 50 минут. Взбить блендером сливки, постепенно добавляя сахар и экстракт миндаля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4836,'Взбивать сливки до устойчивых пиков. Убрать крем в холодильник. Пирог достать из духовки и немного остудить. Перед подачей нарезать его кусками, сверху выложить немного взбитого крема, присыпать измельченным миндалем. Сельский пирог с грушами готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Подошедшее тесто размять и разделить на желаемое количество частей, поверхность стола присыпать мукой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4837,'Помыть и почистить картофель, отварить в воде (подсоленной), остудить. Лук нарезать маленькими кубиками. Сыр и картофель натереть на терке. Смешать, добавить к ним лук, пару яиц, поперчить, посолить и перемешать. Оставшиеся яйца взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4837,'Сформировать из картофеля биточки, обвалять их в муке, затем окунуть в яйца и обмакнуть в панировочные сухари. Обжарить их до румяной корочки. Домашние картофельные биточки подавать с овощным гарниром или как самостоятельное блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4838,'Очистить миндаль от кожуры и залить кипятком на некоторое время. Потом его высушить и измельчить до пудры в кухонном комбайне. Получившуюся пудру смешать с сахаром, пару раз пропустить смесь сквозь сито. От желтков отделить белки, прибавить в белки щепотку сахара и взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4838,'Когда белки станут подниматься, постепенно добавляя сахар взбивать, пока они не станут, как густая меренга. Добавить к ним пищевой краситель (розовый). Всыпать туда же 1/3 часть миндальной смеси и перемешать аккуратно лопаткой. Потом добавить оставшийся миндаль и перемешивать до тех пор, пока смесь не будет однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4838,'Необходимо следить, чтобы она не стала жидкой и не растеклась. Положить на противень пергамент, наполнить тестом кондитерский мешок и выдавить макаруны на бумагу (на расстоянии около 5 сантиметров). Смочить палец водой и слегка приплюснуть каждый, чтобы из них вышел воздух.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4838,'Оставить на полчаса, чтобы подсохли. Потом отправить их в духовку (150 градусов), на 13 минут. По готовности приоткрыть дверцу духовки, а через пару минут полностью открыть духовку и дать печенью полностью остыть. Миксером, масло взбить с сахаром и добавить сок лайма.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4838,'Клубнику мелко порезать и взбить вместе с маслом. Получившийся крем выложить на один макарун (с помощью кондитерского мешка) и накрыть сверху вторым. Перед подачей отправить макаруны «Клубничный дайкири» с миндалем в холодильник, минут через 30 подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4839,'Багет нарезать тонко, измельчить яйцо и перемешать его с мандариновым джемом и майонезом. Уложить начинку на ломти багета и запекать в духовке (180 градусов), пока багет не зазолотится. Важно не засушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4840,'Отделить белки от желтков, ни одной капли желтка не должно в них попасть. Можно сначала отделить белки в чашку, а потом уже перелить их в емкость, где белки будут взбиваться (так надежнее). Начать взбивать белки сначала на небольшой скорости, а потом ее постепенно увеличить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4840,'Взбивая, по частям добавлять сахар. Ореховую муку просеять сквозь сито (можно брать миндальную). Если такая мука отсутствует, то можно перемолоть орехи в кофемолке. Аккуратно, с помощью лопатки, перемешать взбитые белки и муку. Переложить массу в кондитерский мешок и отсадить печенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4840,'Выдавливать тесто на пергамент, стараясь не делать печенье очень высоким. Нагреть духовку (150 градусов) и выпекать минут 40. Показатель готовности – румяная корочка и печенье хорошо отстает от пергамента. Переложить миндально-белковое печенье на решетку, остудить и подавать к чаю или кофе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4841,'Почистить картофель и отварить. Потом воду слить и отставить остывать. Измельчить лук и поджарить его до золотистого цвета. Немного лука оставить, а большую часть положить в картофель. Затем туда же добавить тертый сыр и помять все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4841,'Положить соль, перец и измельченный чеснок, перемешать (можно миксером). В большую емкость насыпать муку, сделать выемку, положить в нее соль, яйца (немного взбитые) и воду (1 стакан). Хорошо все перемешать и замесить эластичное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4841,'При необходимости можно добавить еще воды. Выложить тесто на поверхность, присыпанную мукой и тонко раскатать. Вырезать с помощью стакана круги, на каждый кружок положить ложку начинки (чайную), края теста смазать взбитым яйцом и защипать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4841,'Варить вареники в подсоленной, кипящей воде, пока не всплывут. Затем достать шумовкой из воды и подавать вареники с сыром и картошкой вместе с оставшимся обжаренным луком, сливочным маслом или сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Белки взбить в крепкую пену и, не прекращая взбивать, осторожно влить горячую смесь желтков с орехами, аккуратно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Порезать на маленькие кусочки.','https:https://st.vkuso.ru/data/cache/thumb/b2/e1bb090c58fd8b2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4842,'Морковь с луком измельчить и обжарить. Мясо пропустить сквозь мясорубку. Добавить к нему яйца, базилик, сухари, соль, измельченный сельдерей, перец и все это хорошо перемешать (минут 5). Отставить примерно на полчаса, чтобы все ингредиенты соединились.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4842,'Выложить плотно смесь в форму, или просто сформировать из мяса кирпичик. Поставить форму в духовку (180 градусов) и печь минут 40. В конце запекания можно немного увеличить температуру, чтобы хлеб зарумянился. Мясной хлеб с травами охладить и подавать, предварительно нарезав ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4843,'В кастрюле, на слабом огне (можно на водяной бане) перемешать какао, сгущенное молоко и сливочное масло. Варить, часто помешивая, пока смесь не загустеет (минут 7-10). Убрать с огня и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4843,'Сформировать из смеси маленькие шарики и обкатать их в разнообразных присыпках (кокосовой стружке, измельченных орехах, сахарной пудре или кондитерских посыпках). Шоколадный десерт «Бригадейро» готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4844,'Духовку нагреть (190 градусов), грибы и лук измельчить. Подогреть масло на сковороде и положить туда лук с грибами. Жарить, пока лук не станет прозрачным и мягким, а грибы не уменьшаться в размере и не подрумянятся. Убрать с огня и оставить в сторону, чтобы охладились.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4844,'В большой емкости перемешать муку, соль, сахар и соду, образовать углубление. Положить туда холодные грибы и лук, влить пиво, перемешать. Тесто переложить в форму для буханки хлеба (смазать маслом), полить сверху растопленным маслом (1,5 ложки), печь минут 35.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4844,'Затем буханку вынуть полить еще маслом и опять отправить в духовку еще на полчаса. Готовность проверять зубочисткой. Готовый хлеб на пиве с грибами сначала немного охладить не вынимая из формы. Подавать его нужно немного теплым, смазав сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4845,'Смешать вместе арахисовое масло, яйца и сливочное масло. Соединить соду (разрыхлитель), муку и какао, а потом эту смесь добавить к маслу. Добавить шоколадные конфеты и орехи, аккуратно перемешать. Из массы сформировать печенье. Поставить в духовку (минут 15-20). Печенье шоколадное «Комфорт» готово.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4846,'Гратен – это французское блюдо из овощей, особую пикантность и аромат этому блюду придает корочка из сыра и сливок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4846,'Брокколи и цветную капусту промыть в холодной воде, разделить на отдельные соцветия и отварить 10 минут в слегка подсоленной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4846,'Яйца слегка взбить со сливками, желательно брать жирные сливки, не менее 20% жирности, добавить соль и мускатный орех, а также 1/3 натертого сыра твердого сорта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4846,'Цветную капусту и брокколи выложить в жаропрочную форму для запекания и залить сливочно-яичной смесью, сверху посыпать оставшимся натертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4846,'Гратен с сыром из брокколи и цветной капусты нужно запекать в духовке, разогретой до 200 градусов, приблизительно 30 минут, за это время образуется румяная корочка, подавать горячим, посыпав свежей зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4847,'Пирог «Фламмкухен» – это блюдо принадлежащее как к французской, так и к немецкой кухням. Готовиться этот пирог очень просто, а для желудка это блюдо совсем не тяжелое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4847,'Копченый бекон нарезать не толстой соломкой, лук очистить, нарезать некрупными полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4847,'Слоеное тесто при необходимости разморозить, форму для пирога застелить пергаментной бумагой (силиконовые формы застилать бумагой не нужно), бумагу смазать маслом, выложить на нее тесто, сделав «бортики» для будущего пирога, тесто намазать толстым слоем сметаны .',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4847,'На тесто, намазанное сметаной, выложить нарезанный лук, затем нарезанный копченый бекон, посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4847,'Пирог «Фламмкухен» с копченым беконом нужно выпекать в горячей духовке до появления румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Суфле – это распространенный во Франции десерт, отличающийся своей воздушностью и изысканностью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Грецкие орехи, очищенные от скорлупы измельчить, обжарить на сухой сковороде и дать им остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Отделить яичные белки от желтков, желтки растереть с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Готовый французский кекс «Четыре четверти» остудить прямо в форме, затем вынуть и подавать к столу, посыпав сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Духовку разогреть до 200 градусов, форму для запекания смазать маслом и выложить тесто для суфле, выпекать суфле по-французски из грецких орехов в течение 10 минут, когда готовое суфле остынет, оно немного опадет – это нормальный процесс.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4848,'Готовое остывшее суфле перед подачей на стол посыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4849,'Клубни картофеля очистить и отварить целиком, затем достать из воды, нарезать и положить обратно в воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4849,'Репчатый лук очистить, мелко нарезать и обжарить до золотистого цвета, половину лука добавить в мясной фарш, оставшийся обжарить вместе с одной натертой морковью, обжаренные овощи добавить к картофелю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4849,'В мясной фарш с луком вбить яйца, добавить соль и черный молотый перец,  из фарша слепить фрикадельки и добавить в суп, проварить суп 10 – 15 минут и положить в него нарезанные кубиками плавленые сырки, через 10 минут положить мелко нарезанную зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4849,'Суп сырный с фрикадельками по-французски подавать к столу горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4850,'«Вино богов» — это название напитка придумал легендарный французский повар Франсуа Ватель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4850,'Яблоки очистить от семян, нарезать кружочками, лимоны полностью очистить от кожуры и тоже нарезать тонкими кружочками, яблоки выложить ровным слоем в глубокое блюдо, посыпать сверху сахарной пудрой, сверху выложит кружочки лимонов и также посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4850,'Таким образом, слоями выложит все яблоки и лимоны, посыпая слои сахарной пудрой, сверху фрукты залить вином, чтобы оно покрывало фрукты полностью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4850,'Сверху, фрукты с вином накрыть плоской тарелкой, она должна придавливать фрукты, чтобы они не всплывали, и оставить на несколько часов, лучше на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4850,'Через несколько часов, фрукты можно вынуть и использовать в пищу, а «Вино богов» по-французски подавать в фужерах в холодном виде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4851,'Копченый бекон мелко нарезать, луковицу очистить и нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4851,'Мягкий козий сыр смешать со сметаной, оливковым маслом, мускатным орехом, солью, перцем и приправой «прованские травы».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4851,'Готовое тесто для пиццы тонко раскатать, используя муку для раскатки, и обрезать по форме прямоугольника.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4851,'Прямоугольник из теста равномерно намазать сырно-сметанной смесью, отступая от краев, на тесто выложить бекон и лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4851,'Духовку разогреть до 250 градусов и запекать тарт по-эльзасски в течение 10 минут, к столу эльзасский пирог — тарт «Фронтьера» подавать на деревянной доске горячим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4852,'Приготовит опару: смешать муку, сухие дрожжи, и теплую воду, опару оставить на 4-5 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4852,'Для теста смешать муку с сахаром, солью и водой, тесто смешать с опарой и оставить для расстойки на 3 часа в миске, смазанной растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4852,'Через 3 часа, тесто разделить на две части, из которых сформировать 2 батона и оставить их еще на 2 часа, затем на батонах сделать надрезы ножом наискосок и смазать батоны водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4852,'«Парижские» батоны выпекаются в духовке, разогретой за 2 часа с кирпичами или камнями для выпечки, в течение 30 минут, после выпечки батоны получаются мягкими с хрустящей корочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Этот кекс традиционно подается во Франции к завтраку или обеду, он отличается нежным сливочным вкусом, а название «Четыре четверти» отражает количество ингредиентов – по 250 г муки, сахара (включая 2 пакетика ванильного сахара), сливочного масла и яиц.  Если вес 4 яиц оказался меньше 250 г, то и другие продукты брать такого же веса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Сливочное масло размягчить и растереть с сахаром до однородной массы, затем взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Яичные белки отделить от желтков, желтки по одному вбить в масляную смесь, а белки убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Муку тщательно просеять и добавить в смесь масла и белков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Белки взбить с солью в крепкую пену и соединить с желтково-масляной смесью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4853,'Форму для кекса выстелить пергаментом, смазанным маслом и выпекать в горячей духовке 40 – 45 минут, если зубочистка выходит из кекса сухой, то он готов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Хорошо вымыть чечевицу и положить в кастрюльку. Налить 2,5-3 стакана воды, довести на огне до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4854,'Лук-шалот нарезать кольцами и обжарить на сковороде на сливочном масле, добавить рукколу, соль и перец, а также овощной бульон, и тушить в течение 10 минут, снять сковороду с огня и дать остыть, после остывания овощи измельчить в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4854,'Смесь из измельченных овощей довести до кипения, для густоты можно добавить муку, разведенную в холодной воде, затем влить свежие или кислые сливки и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4854,'Семгу достать из холодильника и потушить на сковороде, не накрывая крышкой, на медленном огне на одной стороне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4854,'Готовые стейки семги маринованной с крем-соусом по-французски подать к столу с крем-соусом, поперчив и приправив другими специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4855,'Луковицу очистить и мелко нарезать, посыпать карри и обжарить в разогретом масле, положить очищенные креветки, сбрызнутые лимонным соком и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4855,'На другой сковороде отдельно обжарить на сливочном масле муку и тонкой струйкой влить молоко и белое вино, добавить соль, перец и мускатный орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4855,'Смешать креветки с соусом и разложить в кокотницы или горшочки, сверху посыпать тертым сыром и запечь в течение 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4855,'Креветочный жюльен по-французски подавать в кокотницах с белым вином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'Положить в кастрюлю мед, соль, добавить 4 ст.л. теплой воды, смешать, добавить взбитое яйцо и перетереть до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'1 ¾ стакана муки с содой постепенно добавить в яично-медовую смесь, замешивая тесто, готовое тесто скатать в колбаску, диаметром 1 см и нарезать ее на кусочки, кусочки раскатать в лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'Обвалять лепешки в муке, обжарить на сковороде в разогретом масле и выложить на салфетку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'Приготовить сироп: в кастрюлю влить 1/3 стакана воды и положить сахарный песок, нагреть до сиропообразного состояния и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'Каждую лепешку обмакнуть в сироп и хорошо пропитать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4856,'Подавать жареные лепешки в сахарном сиропе по-японски с фруктами и мороженым.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4857,'Сваренные вкрутую яйца очистить и разрезать пополам поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4857,'Майонез смешать с тертым хреном и выложить эту смесь в салатник, поверх смеси выложить яйца срезами вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4857,'Подавать яйца с соусом-хрен по-японски, украсив рубленой зеленью и кусочками помидора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4858,'Небольшое количество холодной воды взбить с яйцом и добавить просеянную муку, в результате должно получиться жидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4858,'Отделить яичные белки от желтков, белки взбить, растительное масло нагреть в кастрюле, клубни картофеля очистить и нарезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4858,'Отделить от креветок усики и лапки, промыть, обсушить, обвалять в кукурузной муке, обмакнуть во взбитый белок, обмакнуть креветки в кляр, каждую креветку зажать между кружочками картофеля и осторожно обжарить картофель в кляре с креветками по-японски в кипящем масле до хрустящей корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4859,'Почистить и разделать рыбу на филе, нарезать на порционные куски, запечь ее в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4859,'Обжарить на масле нашинкованные коренья и лук, добавить воды, томатной пасты, лавровый лист, приправить перцем, мускатным орехом, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4859,'Отдельно обжарить до кремового цвета муку со сливочным маслом, соединить с зажаркой из овощей и проварить 15 минут. Перед выключением влить ложку уксуса, дать закипеть и тогда выключить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4859,'Рыба под луковым маринадом по-скандинавски подается холодной, политая сверху приготовленным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4860,'Замесить из сметаны, муки, сливочного масла (200 г), яйца и соли тесто, убрать на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4860,'Измельчить зелень, грибы, лук, сыр натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4860,'На растопленном сливочном масле поджарить грибы, сыр, лук, зелень петрушки, фарш, посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4860,'Раскатать половину теста, перенести на противень, смазанный маслом, на центр пласта выложить грибную начинку, разровнять, положить сверху раскатанный пласт из второй половины теста, края тщательно защипать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4860,'Смазать скандинавский паштет из мясного ассорти яйцом и поставить запекаться, подавать паштет горячим со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4862,'Готовят его из оставшегося при обжарке мясного сока с добавлением стакана воды, сметаны, перца и соли, все доводят до кипения, помешивая, вливают крахмал, дают загустеть и выключают нагрев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4862,'Подавать скандинавское жаркое из окорока с большим количеством овощей и жареным картофелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4863,'Нашинковать тонко капусту, разогреть смалец, добавить вино, мелко порезанный кубиками лук, желе, измельченные ягоды можжевельника, поперчить, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4863,'Перемешать и тушить до готовности под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4863,'Краснокочанная капуста с вином по-скандинавски — отличный гарнир к свиному жаркому, птице или к дичи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Освободить куриное филе от пленки и сухожилий, зачистить косточки, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Подготовить фарш для начинки. мелко порубить обжаренную куриную печень, смешать с одним измельченным вареным яйцом, петрушкой, красным перцем, сливочным маслом и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Положить по центру филе печеночный фарш, приподнять края и закрыть начинку, скрепить для надежности зубочистками, посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Запанировать котлету в муке, смочить взбитым яйцом, обвалять в сухарях, снова смочить в яйце и запанировать в мелких кубиках батона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Аккуратно обжать руками, придать форму слегка удлиненного яйца, зарумянить котлету во фритюре, а потом запекать в духовке до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4864,'Котлеты куриные с начинкой из печени с яйцом подавать с картофелем пай и овощным салатом с зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4865,'Нарезать филе рыбы на одинаковые средние кусочки, натереть их солью с перцем, запанировать в муке, зажарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4865,'Смазать остывшие кусочки сливочным маслом, присыпать натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4865,'Скандинавская закуска из рыбы и сыра выкладывается на блюдо и украшается рублеными белками яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4866,'Разогреть предварительно духовку до 180 градусов, перед выпечкой форму (диаметром не более 18 см) для торта смазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4866,'Хорошо взбить сахар со сметаной, добавить растопленное масло, просеянную муку, разрыхлитель, пряности, налить молоко, все тщательно смешать и залить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4866,'Выпекать торт скандинавский с пряностями примерно 1 час, периодически проверяя готовность: пока вынутый из середины коржа нож не будет чистым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4867,'Замесить из муки, сливок и масла песочное тесто и убрать в холодное место на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4867,'Порезать и потушить грибы, добавить смесь сливок, муки и яйца, посолить, поперчить, перемешать и прогреть все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4867,'Нарезать мелко сыр и крупно – ветчину, тесто раскатать, вырезать подходящей выемкой кружочки, положить на каждый по ложке грибов, ветчины и сыра, защипать края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4867,'Выпекать пирожки с ветчиной, сыром и яйцом на среднем огне в разогретой предварительно духовке примерно полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4868,'Большие клубни картофеля вымыть, обсушить, можно не чистить, оставить в «мундире». Завернуть в фольгу каждый по отдельности, выложить на противень и печь в течение часа при температуре 190 градусов. Готовить до мягкости, проверить с помощью палочки. Остудить и аккуратно удалить часть мякоти ложкой, чтобы получилась «лодочка» с толстыми стенками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4868,'Для начинки соединить порезанную ветчину, тертые сыры «Пармезан» и «Чеддер», натуральный греческий йогурт, размягченное сливочное масло, стручок измельченного сухого острого перца, рубленый чеснок. Паприка и соль – по вкусу. Добавить вынутую и размятую картофельную мякоть, долить немного йогурта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4868,'Начинить картофель, вернуть в духовку в той же фольге, но в открытом состоянии, на 20 -25 минут. За 10 минут до готовности блюдо вынуть, посыпать тертым сыром, допечь картофель с сыром чеддер в духовке до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4869,'Взбить яйца с молоком и приготовить омлет на разогретой сковороде с растительным маслом. Дожарить блюдо под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4869,'Выложить сверху тертый сыр и порезанную колбасу, зелень, немного сыра, свернуть омлет в рулет при помощи ложек или лопаток, пока не остыл. Прогреть омлет-рулет на сковороде швом вниз пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7730,'Жарить на сковороде на растительном масле, массу выкладывать ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4870,'Приготовить блинчики, для этого смешать яйца с сахарным песком и солью, влить молоко и всыпать просеянную муку, порциями, размешать до однородности, взбить венчиком, чтобы не было комочков, затем долить еще немного молока. Если избежать комочков не удалось – протереть массу через частое сито. Жарить блинчики на раскаленной сковороде с растительным маслом с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4870,'Для начинки отварить куриную грудку со специями и остудить прямо в бульоне, так мясо будет сочнее. Порезать репчатый лук кубиками, натереть морковь, овощи спассеровать на растительном масле до полуготовности. Добавить порезанные шампиньоны или другие грибы, обжарить до полной готовности, соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4870,'Куриное филе освободить от костей, порезать на кусочки, добавить в грибную смесь, долить еще немного растительного масла, прогреть две-три минуты. Снять с огня, немного остудить и вмешать сырое яйцо для вязкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4870,'Нафаршировать блинчики полученной начинкой, свернуть конвертом, немного обжарить на растительном масле с двух сторон, яйца внутри должны свернуться. Домашние блинчики с грибами и курицей можно подать со сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4871,'Для начинки натереть сладкие яблоки, добавить распаренный изюм без косточек, молотую корицу, сахарный песок. Перемешать. Готовые прямоугольные пластины из магазинного слоеного теста разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4871,'Выложить начинку, сложить квадраты в треугольники, защипать края. Сырой желток немного разбавить водой, размешать, этой смесью смазать выпечку сверху. Печь треугольники с яблоком при 180 градусах в течение 12 – 15 минут до образования хрустящей румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4872,'Смешать содержимое бутылки сидра с цедрой апельсина, свежим апельсиновым соком, корицей, гвоздикой, молотым имбирем и мускатным орехом. Добавить по вкусу мёд, размешать. Вылить в кастрюлю среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4872,'Варить на тихом огне 8 – 10 минут, предварительно довести смесь до кипения. Снять с огня, влить виски, размешать. Разлить сидр с виски и корицей в бокалы и украсить взбитыми сливками. Подать в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4873,'Все продукты должны быть охлажденными. Замороженное сливочное масло или маргарин быстро натереть на терке, сразу пересыпая мукой, чтобы кусочки не склеивались. Всыпать еще часть муки, перемешать, должна получиться крошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4873,'Смешать сырые яйца, соль и уксус, долить холодную воду. Смесь, которая тоже должна быть холодной, влить в крошку, быстро замесить тесто. Собрать массу в брикет, разрезать домашнее слоеное тесто на три части, обернуть каждую целлофаном и заморозить в течение двух-трех часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4874,'В большой жаровне разогреть оливковое масло. Обжарить на среднем огне порезанный кубиками репчатый лук, измельченный чеснок, щепотку молотого красного острого перца, лавровый лист. Через 3 – 5 минут после начала обжаривания лук должен стать мягким и прозрачным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4874,'Добавить содержимое банки помидоров в собственном соку, которое предварительно нужно размять в пюре с помощью толкушки, кожицу лучше удалить. Всыпать коричневый сахар, хлеб без корочки, довести смесь до кипения. Убавить огонь и варить до размягчения хлеба на среднем огне в течение пяти минут. Лавровый лист выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4874,'Выключить огонь, добавить оливковое масло и размолоть массу блендером до однородного состояния. Можно дополнительно протереть через сито. Долить куриный бульон, довести до кипения. Соль и перец добавить по вкусу, вновь довести до кипения. При подаче томатный суп украсить листочками свежего базилика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4875,'Нежирную свинину нарезать на порции и хорошо отбить. Смешать в равных пропорциях сахарный песок, соль, молотый перец, смесью хорошо натереть мясо со всех сторон. Залить молоком полностью и оставить на три часа пропитываться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4875,'Отбивные из свинины панировать в муке, затем обмакнуть в немного взбитое сырое яйцо, жарить на растительном масле до готовности, с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4876,'Очистить и нарезать спелый банан, клубнику, киви кусочками. Положить в контейнер, залить обезжиренным йогуртом без вкусовых добавок и красителей, можно греческим. Заморозить мороженое из йогурта с фруктами в течение трех часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Мелко потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/13/a0a40284a149013_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4877,'Смешать просеянную пшеничную муку, сухие дрожжи, яйца. Долить растопленное сливочное масло. Перемешивать венчиком до состояния полной однородности. Влить светлое пиво, осторожно, чтобы оно не слишком пенилось, перемешать, соль – по вкусу. Разлить тесто в силиконовые формочки для выпечки маффинов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4877,'Печь в духовке в течение 15 минут при температуре 180 градусов. Немного охладить, вынуть из формочек. Отдельно взбить сливки с сахаром, выложить по ложке на бельгийские оладьи, вместе с брусничным соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4878,'Смешать муку с сахаром и солью, добавить охлажденное сливочное масло, нарезанное кусочками. Перетереть массу руками в крошку, сделать это быстро, пока масло не растаяло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4878,'Форму выстелить бумагой для выпечки, две трети полученного теста высыпать и разровнять, немного утрамбовать руками. Оставшуюся крошку убрать на время в холодное место. Выпечь корж в течение 12 – 15 минут при 180 градусах, он должен стать коричневато-золотистым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4878,'Приготовить шоколадную массу, для этого нужно порубить темный шоколад, влить сгущенное молоко, поставить на огонь и прогревать до однородного состояния. Массу нанести на корж с помощью лопатки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4878,'Мелко порубить грецкие орехи, смешать с оставшейся охлажденной крошкой и шоколадными «каплями», посыпать готовый пирог. Печь в течение получаса при 180 градусах. Остудить, нарезать на квадраты. Посыпное шоколадное печенье готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4879,'Разморозить скумбрию, вымыть, почистить рыбу. Отрезать хвост и голову. Через верх рыбы вынуть потроха, то есть сделать разрез по спине, а живот оставить целым. Убрать все кости, а также плавники.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4879,'Отварить яйца и морковь. Остудить и крупно потереть, продольно на полоски порезать маринованные огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4879,'Филе рыбы положить мясом вверх, посыпать перцем, солью, сухим желатином. Сверху положить морковь, огурцы и яйца. Свернуть в рулетик, а его завернуть в пленку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4879,'Варить закусочный рулет из скумбрии минут сорок в подсоленной воде. Приготовленный рулет с пленкой в горячем виде положить под пресс, держать до полного остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4880,'Крупно потереть картофель и слегка отжать сок. К картофелю добавить яйцо, соль и муку. Выложить массу в формочки для кексов, поставить в духовку на тридцать минут, соблюдать температуру 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4880,'Остудить кексы, на дно положить несколько кусков рыбы. Приготовить соус: смешать измельченные огурцы, лук и майонез. Положить сверху рыбки. Украсить корзиночки из картофеля с сельдью и огурцом клюквой и луком',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4881,'Разогреть духовку. Взбить яйца, сыр и молоко. К яичной смеси добавить порезанную ветчину, помидорку, зеленый лук, посыпать приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4881,'Вылить в формочки на 2/3, так как они поднимутся. Готовить яичные кексы с ветчиной и сыром минут 35. Нежнейшие кексики подавать на завтрак. Также подойдут в качестве легкой закуски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4882,'Взбить в отдельных емкостях желтки и белки. Соединить остальные ингредиенты, налить взбитые белки, насыпать муку. Получится жидкое тесто, как на оладушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4882,'В 1/2 теста добавить какао, во вторую часть не добавлять. Готовить коржи при температуре 180 градусов. Сначала они сильно поднимутся, но потом чуть-чуть осядут. Если корж осел, значит готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4882,'С обоих коржей снизу снять тоненький слой выпечки, достаточно легко это можно сделать при помощи ножа или чайной ложки. Снятый слой руками разделить на маленькие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4882,'Смазать коржи сметанным кремом, соединить, сверху выложить измельченные куски коржей. Выкладывать их необходимо на крем вниз гладкой стороной, вверх лохматой стороной. Именно поэтому называется торт «Лохмач».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4883,'Вымыть грибы, бросить их в соленную кипящую воду и готовить минут пятнадцать. Если грибочки крупные, то порезать их. Достать грибы из воды. Приготовить маринад: налить воду в кастрюльку, насыпать соль, специи, добавить уксус и поставить на плиту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4883,'После закипания бросить в воду грибы, варить минут двадцать. Переложить грибочки в подготовленную банку. Залить маринадом, в котором шампиньоны варились, закатать крышкой. Домашние консервированные шампиньоны готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Готовое блюдо оформить мидиями и омарами.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4884,'Приготовить из сахара карамель, добавить бульон, уксус, коринку, обжаренную муку, прокипятить, перед подачей соуса на стол добавить в него столовую ложку масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4884,'Бифштекс «Зильбулар мед коринтзес» из сельди с соусом подавать с овощами и пюре из картофеля.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4885,'Для приготовления этого необычного салата взять скумбрию, консервированную в собственном соку с добавлением масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4885,'Слить из консервов лишнюю жидкость, рыбу измельчить, убрать кости хребта, нашинковать тонкими полукольцами лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4885,'Промыть вишню, удалить косточки, аккуратно смешать с луком и рыбой, поперчить, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4885,'Заправить салат скандинавский из скумбрии с вишней растительным маслом и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4886,'Соединить масло с обыкновенным сахаром и ванильным. Вбить в смесь яйца, налить молоко, насыпать разрыхлитель и муку. Замесить жидковатое тесто. Застелить противень специальной бумагой, вылить на нее тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4886,'Порезать персики на маленькие дольки, выложить их равномерно на тесто. Поставить пирог на тридцать минут в духовку. Миксером взбить сметанку и сахар, чтобы масса стала воздушной. Смазать домашний пирог с персиками сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4887,'Растереть в посуде творог и мягкое масло. В полученную смесь погасить соду соком лимона или уксусом. Медленно насыпать муку, замесить тесто. Отправить его на 60 минут в холодильник или в морозилку на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4887,'Разделить тесто на части, каждую раскатать на специальной бумаге, и вырезать круги при помощи граненого стакана. Все кружки обмакнуть с одной стороны в сахар, сложить пополам. Повторить данную поцедуру еще два раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4887,'Выложить печенье на противень, застеленный специальной бумагой. Сделать ножом надрезы на каждом печенье в виде гусиных лапок (две полоски). Готовить печенье «Гусиные лапки» из творога минут пятнадцать при температуре в среднем 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4888,'Почистить картофель, порезать на кусочки, бросить в воду (полтора литра) и варить. Крупно потереть морковь, кубиками порезать луковицу. Тушить овощи минут пять на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4888,'Положить лук с морковью в кастрюльку с картофелем. Порезать сыр на кусочки, бросить в суп. Мешать, пока не растворится сыр. Посыпать солью. Готовить классический сырный суп с овощами тридцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4889,'Разморозить тесто, поделить его пополам. Посыпать стол мукой и раскатать одну часть теста до размера формочки для выпекания. Вторую часть сделать меньше. Порезать ветчину на ломтики. Потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4889,'Посыпать формочку мукой, в нее положить пласт, который побольше, сделать бортики. Положить ветчину. Разбить яйца, проткнуть осторожно желток ножом. Положить сверху кусочки ветчины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4889,'Накрыть вторым пластом, краешки защипнуть. Посыпать сыром. Готовить пирог ветчиной и яйцами из слоеного теста минут тридцать, соблюдая температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4890,'Измельчить в блендере печенье, положить в массу растопленное масло. Размешать и плотно выложить в формочку. Получается основа десерта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4890,'Залить водой желатин, оставить на 15 минут. Соединить сахар и сметану. Смешать в кастрюльке молоко, какао и сахар, варить несколько минут на тихом огне. Соединить шоколадную массу со сметанной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4890,'Желатин поварить несколько минут и вылить в шоколадно-сметанное суфле. Очистить бананы и выложить их на основу десерта. Вылить на них суфле. Поставить часов на восемь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4890,'Желательно готовить банановый десерт на основе из печенья в разъемной формочке или обыкновенную форму смазать растительным маслом. Достать десерт из формочки, украсить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4891,'Для панировки использовать очень черствый белый хлеб. Смолоть его с оливковым маслом, измельченным зеленым луком и соком лимона. Взбить, чтобы получилась рыхлая мелкая крошка. Если потребуется, добавить масло, чтобы панировка не была слишком сухой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4891,'Приготовить соус: мелко порезать лук и помидоры черри. Обжарить на оливковом масле. Через несколько минут посыпать специями, солью и готовить еще минуты три. Духовку разогреть до 175 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Разделать каждую грудку, затем по отдельности завернуть каждый кусок в пищевую пленку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4891,'Филе лосося посыпать перцем, солью, положить на блюдо для выпекания. Положить панировочную массу. Готовить минут десять, потом включить бройлер минутки на две. Украсить томатным соусом. Переложить филе лосося в панировке с пикантным соусом на тарелку и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4892,'Отварить в подсоленной воде печень, перекрутить дважды в мясорубке с мелкими отверстиями, к печеночному фаршу добавить сливочное масло, натертый сыр, мелко порезанные яйца, измельченную зелень, кетчуп, посолить, поперчить, смесь хорошо вымешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4892,'Нарезать батон, можно поджарить кусочки в тостере и намазать паштетом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4892,'Готовые скандинавские бутерброды с печенью украсить веточками петрушки и ломтиками помидора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4893,'Просеять муку в большую посуду (это сделает тесто более пышным). Насыпать дрожжи в теплое молоко, размешать, накрыть полотенцем и на двадцать минут отставить. Спустя 20 минут в дрожжевую смесь положить желтки, соль, сахар. Взбить. Бросить мягкое сливочное масло. Хорошенько, но осторожно размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4893,'Вылить смесь в просеянную муку, замесить тесто. Накрыть тесто полотенцем и на сорок минут отставить, чтобы оно поднялось в несколько раз. Посыпать стол мукой, раскатать тесто в один сантиметр толщиной. Вырезать пончики с помощью стакана или рюмки. Дать подготовленному тесту расстояться минут тридцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4893,'Разогреть в кастрюльке столько масла, чтобы пончики были погружены минимум наполовину. Обжаривать с двух сторон и выложить, чтобы лишнее масло стекло. Посыпать пышные домашние пончики на дрожжах сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4894,'Порезать полукольцами лук, тоненькими пластинками шампиньоны. Обжарить лук на масле, добавить шампиньоны. Размешать, готовить минут пять. Положить фарш. Размешать, готовить минут пять, добавить томатный соус. Посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4894,'Налить в сковороду бульон или воду, тушить минут десять. Положить сметану. Размешать, покипятить несколько минут. Отварить спагетти, заправить оливковым маслом. Подавать спагетти с шампиньонами и мясным соусом, посыпав предварительно измельченной петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4895,'Слить сок с фасоли. Можно брать отварную фасоль. Порезать соломкой колбасу или ветчину. Помидор кубиками. Измельчить зелень. Перемешать все в емкости, положить измельченный чесночок. Слить сок с кукурузы, положить ее к ингредиентам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4895,'Посыпать перцем и солью, положить майонез, размешать. Порезать на кубики хлеб, подсушить на сковороде. Положить салат «Для любимого мужа» с ветчиной  в салатник, посыпать сухариками. Перед подачей перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4896,'Порезать свинину кусочками, положить в формочку для запекания. Порезать полукольцами луковицу, обжарить с тертой морковью. Положить томатную пасту, посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4896,'Выложить поджарку на мясо, положить сверху брынзу и намазать майонезом. Прикрыть фольгой, поставить на тридцать минут в духовку. Сочная свинина с брынзой в духовке готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4897,'Замочить желатин в 1/2 стакана кипяченной остывшей воды, распустить на водяной бане. Залить водой курагу, насыпать сахар, налить коньяк, варить минут двадцать на тихом огне. Измельчить в блендере вместе с отваром, чтобы получилась пюреобразная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4897,'Взбить холодные сливки, положить сахар и ванилин. Разделить желатин пополам, одну часть добавить в курагу, вылить в креманки и дать застыть. Вторую часть (можно поменьше) добавить в сливку. И вылить ее на курагу сверху. Тоже дать застыть.  Десерт «Курага под снегом» кушать с орехами и шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4898,'Растворить в кипятке растворимый кофе (нужно регулировать по вкусу, можно взять чай или какао). Положить мед, изюм, очищенное растительное масло, сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4898,'Тщательно размешать и медленно добавить муку, соду погасить в уксусе. Положить орехи, корицу и так далее. По чуть-чуть. Выложить все в формочку. Готовить домашнюю коврижку с изюмом минут пятнадцать при 200 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4899,'Сделать фарш, соединив ингредиенты, добавить воду, перемешать, отставить минут на десять. Взять формочку, не смазывая маслом, выложить в нее фарш. Осторожно выровнять и на тридцать минут поставить в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'С помощью колотушки для мяса отбить куриное мясо как можно тоньше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4899,'Порезать овощи: помидоры и лук полукольцами. Болгарский перец на четыре части и полосками. Выложить по очереди лук, помидоры, перец. Посолить и поставить в духовку минут на пятнадцать. Готовить при температуре двести градусов. Мясо должно пустить сок, потом оно подсушится и изменит цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4899,'Тщательно растворить томатную пасту в горячей воде, посыпать солью. Данную заливку вылить на мясо и продолжать тушить. Когда выпарится томатная заливка — ленивые мясные котлеты на противне готовы. Украсить петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4900,'Поделить лаваш на части. Налить в фарш молоко или воду, чтобы он стал жидковатым. На одну сторону лаваша намазать фарш, второй стороной накрыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4900,'Придавить совсем чуть-чуть рукой. Жарить ленивые мясные чебуреки из лаваша с двух сторон на растительном масле. Они получаются очень хрустящими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4901,'Порезать луковицу полукольцами и обжарить. Порезать пластинками грибы и обжарить. Порезать соломкой крабовые палочки тоже обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4901,'Соединить перечисленные ингредиенты, положить отварную, крупно натертую морковь, измельченный укроп. Размешать и заправить салат «Необыкновенный»  с шампиньонами оливковым маслом. Снова размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Просеять и перемешать муку, разрыхлитель, корицу, соль, имбирь, мускатный орех, соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Натереть на крупной терке очищенную морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Установить на миксере высокую скорость и взбить яйца, масло, сахар до консистенции густой сметаны, к полученной массе добавить морковь, экстракт ванили, перемешать миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Уменьшить скорость миксера, частями всыпать и перемешивать смесь муки с пряностями, взбить все в однородную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Выложить полученное тесто в формы с пергаментными вкладышами и запечь при 190 градусах 25-30 минут в предварительно нагретой духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Готовые морковные кексы с корицей и имбирем по-американски достать из духовки, накрыть тканью и не вынимать 10 минут из формочек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4902,'Достать кексы из формочек (вместе с бумагой), дать час постоять и присыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4903,'Приготовить топленое масло: растопить сливочное на тихом огне, снять, удалить пену с поверхности. Масло процедить, для этой цели можно использовать марлю. Противень застелить бумагой для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4903,'Картошку нарезать пластинками в форме шашек домино, уложить их боком, полить топленым маслом. Соль – по вкусу. Печь 40 минут при температуре 200 градусов. «Картофельное домино» должно подрумяниться. Подавать в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4904,'Обжарить нарезанную кубиками говядину и бекон полосками, порезанными поперек. Растопить сливочное масло, добавить муку, перемешать. Смесью покрыть мясо и тушить несколько минут. Добавить красное «Бургундское» вино, мясной бульон, кружочки моркови, лук-шалот или обычные маленькие луковицы, целиком, не резать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4904,'Всыпать свежий или сушеный чабрец, грибы. Довести массу до кипения, огонь снизить, тушить под крышкой полтора часа. Мясо выложить на тарелку, оставшийся соус кипятить несколько минут. Добавить остальное масло, зелень петрушки. Полить говядину Бургиньон с беконом полученным соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4905,'Смешать сырые яйца, стакан кефира, сахарный песок, гашеную соду, просеянную муку. Массу взбить, тесто должно получиться, как густая сметана. Разделить на две равные части, в одну добавить какао-порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4905,'Испечь светлый и темный коржи, остудить и каждые разрезать по горизонтали острым ножом еще на две части. Для крема смешать сметану и сахарный песок, можно добавить орехи или цукаты. Коржи промазать сметанным кремом. Сверху – какао, дать торту на кефире со сметанным кремом постоять два-три часа для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4906,'Сладкий болгарский перец и свежий огурец натереть на крупной терке по отдельности. Слить лишний сок, массу отжать. Натереть яйца, сваренные вкрутую, и сыр. На мелкой терке измельчить морковь. Все ингредиенты смешать и заправить салат «Трудовые будни» майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4928,'Вскипятить воду с добавлением соли и сливочного масла. Всыпать муку, вымешать до однородного состояния. Дать остыть до 25 — 30 градусов. Взболтать вилкой сырые яйца, вливать в тесто порциями, непрерывно вымешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4907,'Застелить противень пергаментом, сложить шарики готового ванильного мороженого и хорошо заморозить в течение двух часов. Смешать измельченные кукурузные хлопья, молотую корицу и кокосовую стружку. В этой смеси обвалять шарики мороженого и снова заморозить в течение получаса. Взбить вместе яйца, молоко и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4907,'Замороженные шарики обмакнуть и в эту смесь, снова обвалять в хлопьях, замораживать два часа. В кастрюлю с толстым дном налить много растительного или арахисового масла, нагреть его до температуры 180 градусов. Осторожно опускать во фритюр шарики мороженого на полминуты. Жареное ванильное мороженое обсушить на бумажной салфетке и сразу подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4908,'Взбить яичные белки с сахаром до образования пышной плотной массы. Добавить растительное масло, затем – желтки, мак, рубленые орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4908,'Перемешать и вылить в форму для выпечки. Печь при 170 градусах 40 минут. Духовку выключить, оставить маковый пирог внутри с приоткрытой дверкой еще на 20 – 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4909,'Свиное мясо нарезать небольшими кубиками, быстро обжарить на раскаленной сковороде. Выложить в порционные горшочки. Мелко нарезать репчатый лук, морковь – соломкой, овощи также обжарить. Выложить на мясо. Тонко порезать острые маринованные огурцы, выложить на лук с морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4909,'Нарезать картофель крупными кубиками, разложить в горшочки. Влить немного бульона. Полить майонезом, посыпать тертым сыром, печь в духовке около часа при температуре 190 градусов. Немного остудить и подать жаркое из свинины в горшочке в теплом виде. При подаче в каждый горшочек положить по веточке укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4910,'Очистить персики и превратить в пюре с помощью блендера. Влить свежевыжатый апельсиновый сок, хорошо перемешать. Формочки для мороженого наполнить фруктовым пюре, долить вишневый сок, не перемешивать. Поставить фруктовый лед в морозильную камеру на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4911,'Нагреть растительное масло до 160 градусов во фритюрнице или в большой кастрюле с толстым дном. Нарезать на тонкие брусочки картофель, излишки влаги удалить бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4911,'Обжарить картофель небольшими порциями по четыре минуты каждую. Переложить на бумажные полотенца, дать впитаться лишнему жиру. Температуру масла увеличить на 30 градусов, обжарить картофель во второй раз, до образования золотистой корочки. Повторно выложить на бумагу и посыпать крупной солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4911,'Приготовить приправу. Смешать тертый сыр «Пармезан», красный перец, нарезанный мелкими кусочками, рубленую зелень петрушки. Присыпать обжаренный картофель. Для приготовления чесночного масла раздавить зубчики чеснока в пасту, присыпав солью. Растирать можно ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4911,'Смешать с сырым желтком и дижонской горчицей. Перемешать и влить растительное масло. Можно добавить немного соуса «Табаско» и щепотку красного молотого перца. Подать соус к пикантному картофелю фри с красным перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4912,'Поломать весь шоколад на кусочки и растопить на водяной бане, включить на разогрев духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4912,'Блендером или миксером взбить яйца, сахар и мед, взбивать порядка 3 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4912,'Смешать шоколад с также растопленным на водяной бане маслом до получения однородной смеси.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4912,'Соединить шоколадную пасту со взбитой яичной смесью и перемешать, засыпать муку и еще раз вымесить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4912,'Выложить глубокую форму пергаментной бумагой и вылить тесто, выпекать «Очень шоколадный» пирог по-американски при 180 градусах 25-30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4913,'Репчатый лук мелко нарезать и поджарить до золотистого цвета. Добавить крупно нарезанные свежие шампиньоны, жарить на сильном огне. Соль, молотый перец – по вкусу. Смешать с густой сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4913,'Тонко, кружками, нарезать очищенные клубни картофеля. Выложить их в смазанную форму так, чтобы не было «дыр», плотно выкладывая дно и стенки. Посыпать любой приправой для приготовления овощных блюд, например, провансальскими травами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4913,'Выложить на картофель обжаренные грибы с луком. Натереть твердый сыр, посыпать сверху. Взбить яйцо с майонезом, вылить на начинку. Печь картофель с шампиньонами и сметаной в духовке до готовности, верхняя часть выпечки должна стать золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4914,'Отжать сок из лимонов. Вскипятить воду с сахаром, добавить цедру и мяту, варить 5 – 7 минут. Остудить в емкости с холодной водой, дать остыть. Удалить мяту и корочки, сироп процедить, добавить лимонный сок, перемешать домашний лимонад и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4915,'Смешать в миске муку, сахар, какао-порошок, разрыхлитель. Добавить горячую воду и растительное масло без запаха. Тесто должно получиться полужидким, если слишком густое – добавить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4915,'Формочки для выпечки кексов смазать маслом, выложить тесто. Печь в течение 15 минут при 200 градусах. Проверить простые маффины на готовность зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4916,'Растопить в кастрюле сливочное масло. Снять с огня, добавить сахарный песок, перемешать. Добавить сырые яйца и вновь перемешать. Всыпать просеянную муку, ванилин, смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4916,'Для выпечки потребуется три формы диаметром 20 см или чуть больше, со съемным основанием, дно нужно выложить пергаментом, вырезав кружки. Вылить тесто, печь при 180 градусах в течение 20 минут. Должна получиться румяная корочка. Коржи остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4916,'Приготовить глазурь: взбить размягченное сливочное масло и любой сливочный сыр с помощью миксера в течение 4 – 5 минут. Добавить просеянные сахарную пудру и какао, перемешать до однородного состояния. Прослоить коржи кремом, верх шведского пирога «Kladdkaka» также намазать кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4917,'Плоды вымыть, обсушить, разрезать пополам и удалить косточки, нарезать кубиками. Отдельно смешать творог, сметану, тертый спелый банан, мёд и ванилин. Массу взбить блендером до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4917,'Выложить десерт в прозрачные креманки. Слои должны распределяться так: персики, творожный крем, абрикосы, крем, персики, крем, абрикосы. Поставить фруктовый «Летний» десерт со сметаной на час в холодное место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4918,'Приготовить фарш из говядины или баранины, обжарить на масле. Добавить соль по вкусу, черный молотый перец, припущенный рис и луковую пассеровку. Перемешать. Замесить пресное тесто, раскатать кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4918,'Края смазать чуть взбитым сырым яйцом, положить приготовленный фарш, защипать края пирожков, придав им форму полумесяца. Обжарить самсу с бараниной с добавлением кулинарного жира.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4919,'Нарезать филе красной рыбы, манго, красный лук, сладкий болгарский перец кубиками среднего размера. Добавить рубленую зелень кинзы. Для маринада смешать сок и цедру половины лимона, оливковое масло, мирин, рисовый уксус, тертый очищенный имбирь. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4919,'Заправить овощи и рыбу, оставить на десять минут для пропитывания. Нарезать кубиками авокадо, полить лимонным соком, посолить и поперчить. Салат оформить с помощью специального кольца. Выложить в него слой авокадо, затем – рыбно-овощную смесь. Для украшения севиче из красной рыбы, авокадо и манго – красная икра и листочки свежего зеленого и фиолетового базилика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4920,'Фасоль замочить на ночь, она должна быть покрыта водой на несколько сантиметров. Назавтра добавить соль, веточки тимьяна, давленый чеснок. Тушить до готовности в течение часа. В толстостенной кастрюле обжарить кубики небольшой луковицы в растительном или сливочном масле или на сале. На это потребуется пять минут, лук должен стать мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4920,'Добавить сладкую паприку, шепотку чипотле, потушить еще минуту. Затем – нарезанные консервированные помидоры, дижонскую или обычную горчицу, коричневый сахар. Кожицу с помидоров лучше удалить. Тушить смесь на тихом огне 5 – 7 минут, до выпаривания лишней жидкости и загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4920,'Добавить фасоль и полстакана воды, в которой она варилась, в помидорную обжарку. Тушить под крышкой в духовке час-полтора. Затем крышку снять и печь тушеную фасоль с травами и овощами еще полчаса до выпаривания жидкости и подрумянивания блюда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4921,'Разрезать кусок говяжьей вырезки на четыре стейка, куски посолить и натереть перцем, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4921,'Обжарить мясо с каждой стороны в сильно разогретом оливковом масле по 5 минут, нагреть до 170 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4921,'На противень из сковороды переложить мясо, поставить запекаться в духовку на 5-6 минут, вынуть и дать остыть 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Подавать хрустящие куриные ножки в панировке можно как на общем большом блюде, так и порционно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4921,'Долить к соку, оставшемуся после обжарки стейков, 2 ч.л. масла и припустить 2 минуты на малом огне раздавленный прессом чеснок, добавить спаржу (предварительно отварить в кипятке 5 минут), черри и тимьян, осторожно перемешать, чтобы не раздавить помидоры, прожарить 2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4921,'Выложить говяжьи стейки с помидорами по-американски вместе со спаржей на блюдо, украсить веточками базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4922,'Шампиньоны большого размера вымыть, обсушить бумажным полотенцем, удалить ножки и мелко их нарезать. Растопить несоленое сливочное масло в большой сковороде, обжарить на среднем огне нарезанные ножки грибов с рубленым репчатым луком, мелко нарезанным зеленым перцем и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4922,'Пассеровать 10 минут до выпаривания большей части жидкости. Снять с огня. Добавить измельченные сухари, мелко нарезанный пепперони, тертый сыр «Романо», сушеную петрушку и орегано. Соль, черный молотый перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4922,'Готовой начинкой заполнить шляпки шампиньонов, печь до потемнения грибов и образования золотистой корочки на начинке, в течение получаса. Подавать фаршированные шампиньоны с пепперони в теплом виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4923,'Отварить рис в воде с добавлением соли до полуготовности. Воду слить, охладить. Репчатый лук очистить и нарезать небольшими кубиками, обжарить на подсолнечном масле до золотистого цвета. Добавить в говяжий фарш вместе с рисом, перемешать, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4923,'У кабачка аккуратно отрезать верхнюю часть, удалить семена с помощью длинного ножа. Начинить кабачок мясным фаршем с рисом, опустить его в котелок из чугуна. Приготовить соус, для этого нужно обдать помидоры кипятком и снять кожицу острым ножом. Лук нарезать полукольцами, поджарить до прозрачности на тихом огне. Добавить помидоры и продолжать прогревать до получения однородной массы. Можно долить воду, если смесь слишком густая. Соль, рубленая зелень укропа  – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4923,'Соусом залить кабачок, накрыть фольгой или крышкой, тушить до готовности при температуре 220 градусов в течение полутора часов, плод должен стать мягким, проверить вилкой. При подаче с фаршированного кабачка с говядиной и рисом нужно срезать кожицу, а сам плод нарезать толстыми кольцами. В порции подлить оставшийся от тушения соус, посыпать зеленью укропа и петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4924,'Творог протереть через сито, можно взять обезжиренный. Отдельно растереть яйца с сахаром и ванилином, добавить в творог вместе с мукой и сметаной, перемешать. В другой посуде растереть в крошку муку с охлажденным и натертым сливочным маслом, добавить какао и сахарный песок. На дно формы среднего размера, смазанной маслом и присыпанной мукой, выложить две трети полученной крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4924,'Вылить творожно-сметанную начинку, посыпать оставшейся мучной смесью. Печь пирог при 180 градусах в течение 50 минут, до готовности. Готовый торфяной пирог с творожной начинкой остудить в форме, затем переложить на блюдо, дать остыть полностью и поставить в холодильник на несколько часов для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4925,'Взбить куриные яйца с сахарной пудрой, можно сделать это миксером или вручную, венчиком. Всыпать в получившуюся плотную пенистую массу ванильный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4925,'На плиту поставить молоко, в горячее влить яичную массу, варить до загустения, помешивая. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4925,'Взбить в пену сливки, соединить обе массы и перемешать. Выложить сливочно-ванильное мороженое в формочки и заморозить в течение двух часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4926,'Куриную и говяжью печень, в равных количествах, промыть, удалить пленки, пропустить через мясорубку. Отдельно взбить сырые яйца с солью и перцем. Добавить в печень вместе с молоком или сливками, перемешать. Всыпать муку, её понадобится столько, чтобы получилось жидкое тесто. Выпечь блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4926,'Приготовить соус: спассеровать на растительном масле лук и тертую морковь по отдельности. Затем смешать, добавить майонез, зелень. Печеночные блины промазать полученным соусом, свернуть рулетами, дать остыть. При подаче печеночные рулеты с овощами нарезать на кусочки. Украсить зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4927,'Отварить яйца вкрутую, разрезать на половинки, вынуть желтки, растереть их с майонезом до однородности. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Всыпать кубики лука, обжарить его до размягчения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4928,'Противень выстлать пекарской бумагой и отсадить на него с помощью кондитерского мешка тонкие длинные полоски заварного теста. Печь при 220 градусах в течение 10 минут, затем температуру снизить до 180 градусов и печь еще около получаса. Остудить и нарезать на равные полоски-«бревнышки».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4928,'Для крема вскипятить молоко. Взбить желтки с сахаром и кукурузным крахмалом. Продолжать взбивать, осторожно влить горячее молоко. Довести до кипения, добавить сливочное масло и ванилин из пакетика, вымешать до однородности. Крем остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4928,'Из «бревнышек» выложить первый корж, смазать кремом, накрыть вторым слоем, расположив их поперек, повторить несколько раз, украсить торт из заварного теста с молочным кремом на свой вкус. Дать пропитаться, постоять несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4929,'Смешать тростниковый и белый сахар, добавить яйца, разрыхлитель с просеянной мукой и вымешать до однородной массы, включить для разогрева духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4929,'Взбить бананы блендером и добавить в тесто, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4929,'Консистенция теста должна быть не густой, но и не слишком жидкой, если тесто получилось недостаточной густоты, следует добавить немного муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4929,'Разложить тесто по формочкам и запечь в духовке с температурой 200 градусов, через 40 минут банановые маффины по-американски будут готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4930,'Клубни вымыть, очистить, нарезать кружочками. Налить молоко в кастрюлю, довести его до кипения, смотреть, чтобы не «убежало». Добавить порезанный кусочками твердый сыр и рубленый чеснок. Прогреть, помешивая. Выложить картофель, он должен быть покрыт молоком полностью. Варить 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4930,'Картофель выложить в форму для запекания, залить молочной смесью, в которой он варился. Посыпать французский картофель в молоке тертым твердым сыром и запечь в духовке в течение получаса при температуре 180 – 190 градусов. Блюдо должно подрумяниться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4931,'Отварить яйцо, очистить. Сливочное масло растереть миксером до побеления, добавить отваренный желток, снова растереть. Влить столовую ложку спиртного: ликер, ром коньяк, растопленный на водяной бане темный шоколад. Перемешать крем до однородного состояния. Поставить в холодильник на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4931,'Размолоть очищенный миндаль и темный шоколад в мелкую крошку, добавить ложку рома, сырой яичный белок, сахарную пудру, вымешивать блендером еще три минуты. Полученный марципан охладить в течение часа. Затем выложить массу на пергамент, скатать колбаской, нарезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4931,'Каждый раскатать в шарик, сделать маленькие лепешки. Положить на них по половине чайной ложки шоколадной начинки, защипать края, сформовать шарик. Натереть молочный шоколад для обсыпки. Готовые домашние конфеты с вишневым ликером обвалять в шоколадной стружке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4932,'Промыть изюм без косточек и курагу, её мелко нарезать. Если сухофрукты твердые, то их нужно предварительно замочить на полчаса в теплой воде, отцедить и обсушить. Добавить рубленые грецкие орехи, молотую корицу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4932,'Свежие яблоки вымыть, разрезать пополам, вынуть сердцевину с косточками. Аккуратно отрезать донышко, чтобы яблочные «лодочки» были устойчивыми. Положить по чайной ложке смеси из сухофруктов, полить мёдом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4932,'Выложить половинки яблок в смазанную сливочным маслом форму. Накрыть крышкой или фольгой, печь полчаса или чуть больше при температуре 180 градусов. Достать десерт, полить соком апельсина. Допечь еще 10 – 15 минут без фольги. Проверить готовность зубочисткой, запеченные яблоки с изюмом, курагой и орехами должны стать мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4933,'Кабачок цуккини нарезать полосками, вдоль плода. Обжарить на гриле, по окончании приготовления поперчить и посолить. Приготовить соус Бешамель, для этого растопить на среднем огне в кастрюле сливочное масло, добавить муку и взбить. Влить молоко, продолжать взбивать венчиком в течение пяти минут, до загустения. Всыпать рубленый базилик, рикотту, соль, перец по вкусу. Перемешать и дать настояться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4940,'Мягкое сливочное масло взбить с сахаром до побеления, добавить сметану. Растворимое кофе развести в горячем молоке и добавить в массу. Все вместе взбить, добавить ванильный ароматизатор. Просеять вместе муку с какао, замесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4933,'В блюдо для запекания слоями выложить соус, листы готового теста для лазаньи, которые можно купить в магазине, цуккини, присыпая тертым сыром Пармезан. Верхние слои – соус Бешамель и тертый сыр. Поперчить, печь вегетарианскую лазанью с цуккини 20 минут  при температуре 175 градусов. Немного остудить и подать. Украсить листочками зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4934,'Размолоть пшеничное и овсяное печенье в крошку, в любых пропорциях. Растопить сливочное масло и смешать с полученной крошкой, выложить в форму для запекания.  Поверхность разровнять ложкой или руками, немного утрамбовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4934,'Поломать кусочками горький шоколад, добавить сливки и растопить на водяной бане или в микроволновой печи. Размешать, добавить еще немного сливок, снова размешать до состояния гладкости, вылить на основу для печенья и разровнять. Поставить корж с начинкой в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4934,'Приготовить крем: нежирный творог взбить с сахаром и сливками. Замочить в воде желатин. Взбить сливки миксером, добавить сахар, еще взбить до образования плотной массы. Переложить в творог, добавить ликер, ванилин. Набухший желатин прогреть до полного растворения, ввести в основную массу и взбивать еще две-три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4934,'Крем вылить на корж и поставить в холод на три часа или на ночь. Вынуть творожный торт с шоколадной основой из формы с помощью тонкого ножа, нарезать на порции. Подать к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4935,'Натереть на терке яблоко, добавить сок, отжатый из половины лимона, чтобы оно не почернело. Посыпать сахарным песком и оставить на 10 минут для пропитывания. Для теста мягкое сливочное масло комнатной температуры взбить с сахаром, добавить по одному два яйца, продолжая взбивать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4935,'Всыпать муку, просеянную вместе с разрыхлителем. Положить яблоки с сахаром, перемешать и добавить еще муку. Готовое тесто выложить в смазанные маслом формочки для выпечки, печь 40 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4935,'Приготовить глазурь. Для этого столовую ложку мёда смешать с небольшим количеством лимонного сока, добавить сахарную пудру, столовую ложку любого алкогольного напитка с хорошим ароматом: ликера, рома. Довести смесь до кипения. Кексы «Мон Плезир» с яблоком вынуть из духовки, дать постоять пять минут и полить горячей глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4936,'Взбить яйцо с солью, добавить сахарный песок, творог, кефир и ваниль. Всыпать просеянную муку и соду так, чтобы получилось тесто, напоминающее по консистенции густую сметану.  Жарить оладьи из творога на смазанной сливочным маслом сковороде, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4937,'Смешать творог, куриные яйца, сахарный песок, манную крупу, сметану и ванилин. Соль – по вкусу, перемешать. Порубить или поломать темный шоколад кусочками, добавить в творожную массу. Выложить в смазанную форму, дать постоять полчаса, затем испечь творожную запеканку с шоколадом при 180 градусах в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4938,'Вареную тыкву измельчить блендером, либо использовать готовое консервированное пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4938,'Нашинковать мелкими кубиками луковицу, распустить в кастрюле масло, потушить лук до прозрачности, добавить бульон из курицы, тыквенное пюре, прокипятить. Уменьшить нагрев и влить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4938,'Смешать сахар с кукурузной мукой, корицей, мускатным орехом и помешивая постепенно засыпать все в кастрюлю, тогда не будет комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4938,'Дать закипеть, поперчить, посолить и варить еще 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4938,'Разлить тыквенный суп с корицей по тарелкам и превратить его в тыквенный суп с тертым сыром и корицей, посыпав щедро тертым пармезаном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4939,'Вымыть апельсины, разрезать пополам, вынуть мякоть и порезать на кусочки. Корочки очистить от белого слоя. Свежие, размороженные или консервированные шампиньоны нарезать ломтиками, обжарить на растительном масле до появления золотистого цвета. Соль – по вкусу, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4939,'Вымыть, освободить от семян и нарезать кубиками болгарский перец, можно взять плоды разного цвета. Натереть твердый сыр. Все ингредиенты смешать, залить салат с апельсином, сыром и шампиньонами майонезом с добавлением горчицы. Выложить массу в «тарелочки» из кожуры апельсинов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6514,'Смешать творог с яйцом, сметаной, ванилином из пакетика. Всыпать предварительно распаренный и обсушенный изюм без косточек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4940,'Из теста скатать шарики, размером с вишню, лучше это делать руками, смазанными растительным маслом. Смочить зубочистку водой и сделать на каждом печенье продольную бороздку. Печь печенье « Кофейные зерна» 10–15 минут при температуре 200 градусов, на противне, застеленном пергаментной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4941,'Раскрошить печенье в крошку. Растопить сливочное масло, смешать, массу выложить на дно формы для выпечки и утрамбовать руками. Для начинки смешать сливочный сыр и «Маскарпоне», добавить ванилин и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4941,'Взбить отдельно сливки, влить в сырную массу, вмешать измельченное печенье «Орео». Вылить начинку на корж, дать сливочно-шоколадному чизкейку постоять в холодильнике не менее шести часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4942,'Вымыть холодной водой листья шпината, обсушить. Помидоры черри разрезать пополам, сыр моцарелла — дольками. Разложить продукты в пиалы, полить каждую порцию небольшим количеством оливкового масла. Посолить, поперчить, посыпать сухими специями «Итальянские травы». Положить очищенные кедровые орешки или семечки кунжута. Итальянский салат со шпинатом готов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4943,'Мелко нарезать филе судака и репчатый лук, зелень. Натереть твердый сыр. Всё смешать, соль, перец – по вкусу. Нарезать батон кружочками по два сантиметра толщиной, лучше, если он будет немного подсохшим. Пропитать молоком, отжать, выложить в смазанную маслом форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4943,'В кружках сделать углубления: примять пальцами мокрый мякиш. Выложить по ложке рыбной начинки, верх смазать майонезом. Печь в духовке 40–45 минут при температуре 180 градусов. Почти готовые бутерброды посыпать сыром и допечь еще 5–7 минут, до подрумянивания. При подаче «Гнездышки» из батона с рыбной начинкой украсить листиками свежей петрушки, укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4944,'Взбить яйца с сахаром в течение 5 – 7 минут, добавить муку, вымешать. Тесто должно получиться полужидким. Яблоки очистить от кожицы и сердцевины, нарезать дольками. Можно сбрызнуть лимонным соком, чтобы не почернели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4944,'В смазанную форму вылить часть теста, примерно треть от общей массы, выложить яблоки, сверху – еще часть теста, снова яблоки и тесто. Печь шарлотку с яблоком в духовке при температуре 180 градусов в течение 40 – 60 минут, до готовности, при закрытой дверке духовки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4945,'Филе разрезать вдоль, но не до конца, развернуть и отбить. Посолить, поперчить. На одну сторону положить сливочное масло, ломтики ветчины и сыра, накрыть второй половиной филе, заколоть зубочистками. Смазать сливочным маслом форму и филе, печь около получаса, до готовности. Подать фаршированное куриное филе, порезав на несколько частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4946,'Порезать куриное филе на мелкие кусочки. Обжарить на сковороде рубленый репчатый лук, добавить муку, еще немного обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4946,'Добавить обжарку в куриный бульон, варить 10 минут. Влить сливки, посолить, варить еще 10 минут. Остудить и взбить в блендере. Подать суп-пюре из куриного филе, посыпав мелко нарезанной зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Нарезать подготовленную свинину небольшими кубиками, посолить, поперчить, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Порезать крупными кусками очищенный картофель и залить холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Отжать из мяса лишнюю жидкость и обжарить (постоянно помешивая) в сильно разогретом масле 10 минут, вынуть мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Если при жарке образовалось много жира, то его надо почти весь слить, нашинковать мелко лук и обжарить 5 минут в оставшемся жире, добавить измельченный перец чили без семян, паприку, чеснок, обжарить еще 3 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Добавить к зажарке мясо, картофель, залить бульоном и на среднем огне кипятить до мягкости картофеля, рагу необходимо периодически перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4947,'Перед подачей в рагу из свинины с картофелем и перцем чили выжать сок из целого лайма, поперчить, посолить и размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4948,'Растопить горький шоколад на водяной бане, влить сливки, мешать, прогревая, до однородности массы. В оставшиеся сливки добавить ванилин из пакетика, перемешать и добавить остальные ингредиенты: растопленный шоколад, сгущенные сливки, виски или водку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Верхние половики печенья миндального с корицей, кардамоном и ягодным джемом можно сделать с разнообразными отверстиями, например в виде сердечек.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4948,'Коктейль поставить на сутки в холодильник. Домашний Бейлис с горьким шоколадом можно подавать с кубиками льда. Украсить взбитыми сливками, тертым шоколадом и целой ягодой клубники с зеленым листочком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4949,'Раскрошить грецкие орехи с помощью блендера, достаточно мелко. Сырую свеклу очистить и натереть. Взбить сырые желтки с сахаром до побеления. В свекольную массу поочередно добавить все ингредиенты: взбитые желтки, молотые орехи, пшеничную муку, просеянную вместе с разрыхлителем, какао-порошок. Перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4949,'Сырые белки взбить со щепоткой соли, вмешать в свекольное тесто. Переложить его в смазанную и присыпанную мукой форму для выпечки, печь при температуре 180 градусов в течение часа.  Для глазури: смешать сахарную пудру и любой фруктовый сок. Остудить пирог из свеклы с грецкими орехами, украсить глазурью, поставить в холодильник на ночь или на сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4950,'Смешать сырые белки, ванилин из пакетика и сахарный песок. Поставить смесь на водяную баню, прогреть, взбить миксером в течение 7 – 8 минут. Должна получиться густая плотная масса. Отсадить безе с помощью кондитерского мешка или другого приспособления на противень. Треть массы оставить для крема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4950,'Печь безе в течение 1 – 2 часов при температуре 100 – 120 градусов. Склеить пирожные по два с помощью оставленного крема. Измельчить фундук или другие орехи, обсыпать пирожное в том месте, где намазан крем, сверху выдавить еще немного и украсить целым лесным орехом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4951,'Очистить яблоки от кожицы и сердцевины, нарезать тонкими дольками, посыпать сахаром, тертой цедрой, оставить на несколько минут для пропитывания. Яблоки должны дать сок, его нужно отцедить, плоды посыпать крахмалом, выложить в форму для выпечки ровным слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4951,'Можно использовать форму из силикона, либо выложить дно обычной формы фольгой. Не смазывать. Раскатать готовое слоеное тесто размером чуть больше диаметра формы, смочить его водой и выложить на яблоки, прижать к начинке, наколоть вилкой в нескольких местах. Печь пирог из слоеного теста чуть больше получаса до образования коричневато-золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4952,'Готовое слоеное тесто раскатать в круг диаметром 35 см. Выложить на застеленный пекарской бумагой противень. Очистить большие, спелые яблоки от кожицы и сердцевины, порезать пластинками и сбрызнуть лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4952,'Выложить на тесто, оставив края в 2 см. Загнуть наверх, на начинку, получившиеся бортики пирога. Посыпать молотой корицей и сахарной пудрой. Печь плоский ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4953,'Спелые крупные помидоры надрезать крест-накрест, положить на полминуты в кипяток, снять кожицу острым ножом. Удалить сердцевины, мякоть нарезать кусочками. Нарубить репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4953,'В кастрюле разогреть оливковое масло, обжарить лук, он должен стать прозрачным. Добавить порезанный перец чили, рубленый чеснок, жарить еще 3 – 4 минуты. Добавить помидоры, прогревать все вместе пять минут, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4953,'Смешать томат-пюре с бульоном из овощей или водой и влить в поджарку. Добавить карри, соль, довести суп до кипения, варить 5 – 7 минут. Положить кинзу и перец чили целиком. Снять индийский томатный суп с огня, подать блюдо горячим, стручки чили вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4954,'Смешать коричневый сахар, муку, просеянную с разрыхлителем, соль, молотую корицу, овсяные хлопья и горсть изюма без косточек. Отдельно приготовить другую смесь: оливковое масло, сырое яйцо, обезжиренное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4954,'Влить жидкость в сухую смесь, перемешать до однородного состояния. Выложить в силиконовые формочки, они должны быть наполнены на две трети объема. Печь овсяные маффины с изюмом 15 минут при температуре 200 градусов. Остудить и вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4955,'Спелые бананы протереть в пюреобразную массу, добавить лимонный сок. Отдельно смешать просеянную муку, соль, соду. В третьей миске взбить мягкое сливочное масло с сахарным песком. Масса должна стать пышной, увеличиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4955,'Сырые куриные яйца растереть с ванилином, часть этой смеси соединить с мучной, добавить немного молока и лимонный сок. Затем снова положить яичную смесь и молоко. Проделать это несколько раз. Полученную массу смешать с банановым пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Завернуть в трубочку.','https:https://st.vkuso.ru/data/cache/thumb/27/4cbd67ac81ef927_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4955,'Форму для выпечки смазать сливочным маслом и присыпать мукой, вылить тесто, печь в разогретой до 135 – 140 градусов духовке в течение часа. Готовность выпечки проверить зубочисткой, если она сухая – торт готов, его нужно вынуть и переложить в морозильную камеру на 45 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4955,'Приготовить сливочный крем. Смешать размягченное сливочное масло и крем-сыр «Альметте» до однородного состояния. Добавить в массу ванилин. Затем всыпать сахарную пудру и взбить в блендере на низкой скорости, скорость повысить, вымешать до готовности.  Крем нанести на охлажденный банановый торт, можно сделать прослойку, если разрезать корж пополам по горизонтали.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4956,'Помидоры и чеснок пропустить через мясорубку, кабачки нарезать мелкими кубиками. Перемешать, добавить соль, сахар, подсолнечное масло. Массу тушить в течение получаса. Нарезать соломкой сладкий болгарский перец, лучше красного цвета, всыпать в томатно-кабачковую массу, влить уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4956,'Смесь довести до кипения, варить 20 минут. Переложить в стерильные, пропаренные банки и закатать. Для остывания банки перевернуть и укутать пледом или одеялом. Овощной салат-соус «Анкл бенс» готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Обмазать кусок мякоти говядины растительным маслом и обсыпать  молотым черным перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Нашинковать полукольцами лук (толщиной по 5 мм).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Обжарить на чугунной сковороде кусок мяса с каждой стороны в сильно разогретом масле до зарумянивания, по времени все займет порядка 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'В утятницу налить 2 ст.л. масла, сильно разогреть, обжарить в течение 20 минут лук, аккуратно добавить уксус с пивом, бросить лавровый лист и помешивая дать закипеть, включить разогреваться духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Положить в пиво мясо и дать закипеть еще раз, отставить в сторону, накрыть крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Утятницу с мясом закрытую крышкой поставить в духовку, тушить до готовности мяса 3,5 — 4 часа при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Нарезать перед подачей мясо на куски и полить получившимся при тушении луковым соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4957,'Говядина тушеная в соусе с луком и пивом будет вкуснее, если на сутки ее оставить в соусе, а перед подачей нарезать на порции и подогреть в соусе, либо мясо завернуть в фольгу и убрать в нагретую до 150 градусов духовку на 35-40 минут, луковый соус в этом случае разогреть отдельно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4958,'Хлеб нарезать кубиками со стороной 1,5 – 2 см. Куриные бульонные кубики размять, добавить рубленый чеснок и растительное масло. Массу перемешать и добавить в хлеб, заливка должна распределиться равномерно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4958,'Выложить сухарики на противень нетолстым слоем, жарить кириешки с чесноком по-домашнему 25–30 минут при температуре 150 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4959,'Растопить маргарин или сливочное масло, добавить яйцо и сметану, соль, соду, просеянную муку, замесить мягкое тесто. Завернуть его в полотенце и положить в холодильник на час. Охлажденное тесто разделить на три части, две убрать обратно в холодильник. Раскатать в круг и разрезать на сегменты от центра, на восемь частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4959,'Для начинки изюм промыть, залить кипятком, дать постоять 15 – 20 минут, воду слить. Обсушить на полотенце. На треугольники из теста выложить начинку и завернуть рулетом от широкой части к узкой. Обмакнуть в сахарный песок, смешанный с молотой корицей. Печь рогалики на сметане с начинкой из изюма в течение получаса при 180 градусах в заранее разогретой духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4960,'Отделить желтки от белков. Последние хорошо взбить, желтки перемешать. Смешать муку и тертый твердый сыр. Массу постепенно добавить к взбитым белкам. Влить желтковую массу. Тесто должно быть полужидким, выложить его ложкой на смазанный маслом противень. Печь сырное печенье 15 минут при температуре 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4961,'Муку просеять и смешать с сахарным песком, какао-порошком и растворимым кофе. Сливочное масло порезать на куски, добавить в сухую смесь и растереть руками в крошку. Влить красное сухое вино и ром, замесить тесто. Оно должно быть эластичным. Завернуть массу в пищевую пленку, охладить в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4974,'С яблок слить воду. Тесто выложить в смазанную маслом форму руками. Выложить яблоки ровным слоем и залить сметанным кремом. Печь пирог «Яблоки на снегу» 50 минут при температуре 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4961,'Застелить противень бумагой для выпечки. Приготовить трубочки для пирожных (канноли). Тесто из холодильника раскатать в тонкий пласт, обрезать края, нарезать квадратами со стороной 6 – 8 см. Смазать канноли кукурузным маслом, обернуть вокруг трубочки, внахлест, квадратами из теста, уголок смазать взбитым яйцом, чтобы прилип.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4961,'Печь порциями в течение 12 минут в разогретой до 200 градусов духовке. Сразу снимать канноли с трубочек и остужать при комнатной температуре, печь следующую порцию. Для начинки растереть творог с сахарным песком и ванилью. Выложить массу в трубочки при помощи кулинарного шприца. Посыпать сицилийские канноли с творожным кремом сахарной пудрой, можно сразу подать на стол. Выпечка хранится в холодильнике трое суток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4962,'Обжарить ломтики хлеба, выложить на него кружочки помидоров, сыр «Моцарелла», соус «Песто». Поперчить и сбрызнуть оливковым маслом, закрыть вторым куском хлеба.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4962,'Жарить на гриле до образования золотистой корочки и до расплавления сыра, по 2 – 3 минуты с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4963,'Растопить сливочное масло в кастрюле на небольшом огне, обжарить тонкие ломтики репчатого лука до мягкости. Добавить полоски тонко нарезанного нежирного бекона, обжаривать вместе три минуты. Добавить кубики очищенного картофеля со стороной 1 — 2 см, ломтики фенхеля и моркови, лавровый лист. Перемешать. Посыпать мукой и еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4963,'В смесь влить молоко, через три минуты – воду, соль, перец – по вкусу. Довести до кипения, варить 15 – 20 минут до готовности картофеля. Помешивать, суп может пригореть. Шафран залить кипятком, добавить в суп при готовности последнего. Добавить зерна кукурузы, размороженные и очищенные тигровые креветки. Прогревать суп Чаудер с фенхелем и креветками на тихом огне 15 минут. Подать сразу, посыпать рубленой зеленью и хлопьями перца чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4964,'Темный шоколад поломать на кусочки, часть – натереть для украшения. Налить молоко в кастрюлю, довести до кипения, добавить шоколад и растворимый кофе, прогревать на тихом огне, помешивая, до растворения шоколада. Массу охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4964,'Шоколадную смесь влить в блендер, добавить шарики ванильного мороженого, оставшееся молоко, перемешать. Разлить в высокие стаканы или бокалы, добавить мороженое для украшения, посыпать кофейно-молочный коктейль шоколадной крошкой и подать с ложечками для десерта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4965,'Яйца перемешать с водой, посолить. Всыпать пшеничную муку постепенно, замесить тесто, добавить две столовые ложки растительного масла. Мягкое тесто оставить на 10 минут для набухания клейковины. Приготовить начинку: размять адыгейский сыр вилкой, посолить, добавить орегано и базилик, нарезанный зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4965,'От теста отщипывать небольшие кусочки, размером с грецкий орех, раскатывать в лепешки. Выложить начинку и защипать, как обычные пельмени. Жарить пирожки в большом количестве растительного масла на сковороде, с двух сторон, огонь – средний. Должна получиться румяная корочка, излишки жира удалить, выложив пирожки «Минутка» с адыгейским сыром на бумажные полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4966,'Нежирное мясо нарезать на кусочки, потушить на растительном масле до полуготовности. Отварить рис также до полуготовности. Порубить репчатый лук и чеснок, добавить тертый твердый сыр, полстакана воды, соль, перец, сверху выложить мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4966,'Печь запеканку «Воздушная» в духовке при температуре 200 градусов около получаса, до образования румяной корочки. Подать, посыпав зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4967,'Разрезать говяжью вырезку на стейки, посолить, натереть крупномолотым черным перцем и обжарить с каждой сторон по 7 минут на сильно разогретом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4967,'Порубить крупно петрушку, добавить лимонный сок, орегано, мелко рубленый чеснок и оливковое масло, посолить, поперчить, перемешать блендером до однородности соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4967,'Разложить готовые стейки по тарелкам и накрыть на 5 минут фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4967,'Перед подачей стейки из говядины с лимонным соком и травами полить приготовленным соусом и присыпать кедровыми орешками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4982,'Готовое слоеное тесто раскатать в виде прямоугольника, выложить на смазанный противень, поочередно выложить картофель и сосиски, любые специи, голландский сыр, снова картофель и сосиски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4968,'Натереть на крупной терке плитку темного шоколада и сливочное масло, смешать и растопить на водяной бане. Смешать два яйца и треть общей нормы сахара, добавить соль и ванилин, массу взбить. Затем ввести растопленную и остуженную шоколадно-масляную смесь. Всыпать муку, просеянную вместе с разрыхлителем, хорошо вымешать. Творог смешать с оставшимся сахаром, добавить яйца, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4968,'Смазать маслом форму для выпечки, застелить пергаментом, влить треть теста, размазать ровным слоем по дну формы, на тесто выложить половину творожной начинки, затем половину вишни, снова слой теста, творог и вишня. Сверху – оставшаяся часть теста. Печь шоколадный брауни с творогом в духовке около часа при температуре 180 градусов. Пирог остудить и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4969,'Баклажан нарезать соломкой, положить в подсоленную воду на 20 минут для удаления горечи, воду слить. Обжарить фарш вместе с репчатым луком и морковью, добавить специи. Нарезать клубни картофеля кружочками, помидоры черри – на половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4969,'Уложить все ингредиенты слоями: баклажаны, фарш, картофель, помидоры. Посыпать тертым твердым сыром, залить смесью из трех яиц с тремя столовыми ложками сметаны, специями. Запечь в форме в духовке до готовности. При подаче овощную запеканку с сыром и мясом украсить листиками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4970,'Крупную рыбу выпотрошить, удалить жабры и чешую, плавники не срезать. Промыть тушку холодной проточной водой. Нарезать на порции, поперек, голову не выбрасывать. Натереть куски солью и перцем, сбрызнуть лимонным соком, оставить мариноваться на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4970,'Глубокую форму по размеру карпа смазать растительным маслом. Клубни картофеля нарезать на кружки, посолить, выложить в форму ровным слоем. Нарезать помидоры и баклажаны кружочками такой же толщины, сладкий болгарский перец – кольцами, хорошо посолить все овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4970,'Рыбу выложить на картофель, сохранив форму, вместе с головой. Между кусочками рыбы – помидоры, баклажан, перец, часть овощей выложить вокруг тушки, слоями. Залить блюдо майонезом, печь карп с овощами под майонезом 45 минут в духовке при 200 градусах, до полной готовности картофеля. При подаче украсить зеленью петрушки, тонкими ломтиками лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4971,'Готовое слоеное тесто разморозить, раскатать, нарезать полосками шириной 2 см. Слить жидкость от консервированных ананасов, разрезать кружки-шайбы пополам и обмотать их полосками теста. Смазать яйцом, печь 15 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4972,'Говядину порезать небольшими кусочками, поперчить и обжарить на разогретом оливковом масле в широкой кастрюле. Мясо выложить, на оставшемся масле обжарить кольца или полукольца репчатого лука, целые очищенные зубчики чеснока, цедру лимона, пучок тимьяна в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4972,'Добавить в обжарку белое сухое вино, кипятить пять минут без крышки, лишняя жидкость должна испариться. Вернуть в кастрюлю мясо, добавить половинки или четвертинки груш. Порезать вдоль очищенные корни петрушки, порубить зелень, добавить то и другое к мясу. Соль, лавровый лист – по вкусу. Долить воду, такое количество, чтобы она на три четверти покрывала мясо и овощи. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4972,'Варить мясо с овощами на тихом огне 2 часа, три-четыре раза перемешать. В конце приготовления посолить. При готовности огонь выключить, дать мясу еще потомиться 20 минут под крышкой. Выложить говядину с грушами в белом вине на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4973,'Нарезать мелко репчатый лук, обжарить на растительном масле до полуготовности. Мелко нарезать шампиньоны, добавить в лук, продолжать обжаривать. Соль, перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4973,'Отварить говядину и нарезать мелкими кубиками, добавить в обжарку, посыпать молотым кориандром, прогреть, влить 1,5 столовые ложки сметаны, размешать и прогреть на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4973,'Разогреть духовку до 200 градусов. Наполнить тарталетки начинкой, посыпать тертым сыром, печь 5–7 минут, подать жульен в тарталетках в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4974,'Тонко почистить и нарезать яблоки, залить кипятком. Растопить сливочное масло, остудить, смешать со сметаной, просеянной мукой и погашенной уксусом содой. Положить в холодильник на полчаса. Для крема смешать сметану, яйцо, сахар и муку, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10536,'Перед подачей посыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4975,'Перемешать измельченные орехи и финики, добавить хлопья «Геркулес», залить смесь теплой водой, смешанной с растительным маслом и перемешать. Погасить соду лимонным соком, добавить в массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4975,'Тесто вымешать. Вылепить из полученной массы небольшие печенья, печь овсяное печенье с сухофруктами на решетке в духовке при температуре 200 градусов в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'Смешать просеянную муку с содой и солью, выставить на миксере среднюю скорость,  взбить 100 г масла и 3/4 стакана сахара, добавить поочередно яйца, взбить до воздушной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'Измельчить в блендере спелые бананы среднего размера, смешать пюре из бананов с получившейся воздушной массой, йогуртом и ванилью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'Соединить бананово-яичную смесь с мукой, переключить миксер на медленную скорость и вымешать тесто до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'Поломать шоколад на крупные куски, добавить растопленное сливочное масло (50 г), оставшийся сахар, измельченные жареные орехи, корицу и перемешать, включить духовку для разогрева до 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'В смазанную маслом и слегка припудренную мукой форму выложить половину теста, а на него шоколадную массу, опять тесто и закончить шоколадно-ореховым слоем, поставить в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4976,'Пирог с бананами, йогуртом, шоколадом и орехами будет готов через 40 минут после начала выпекания, оставить пирог на 30 минут в форме, а затем вынуть и окончательно охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4977,'Кальмары очистить, промыть, нарезать соломкой. Жарить на растительном масле в течение нескольких минут. Мелко порезать репчатый лук и спассеровать, добавить грибы. Смешать то и другое, залить сметаной, соль, перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4977,'Выложить смесь в кокотницы в форме рыбок, посыпать сыром, печь до темно-золотистой корочки. Подать жульен из кальмаров с шампиньонами, украсив листочками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4978,'Белый хлеб порезать ломтиками. Разогреть на сковороде сливочное масло, добавить в него крупно нарезанный чеснок, обжарить, чеснок вынуть. Обжарить на полученном чесночном масле хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4979,'Вскипятить воду с солью и маслом, заварить в ней полстакана муки, разбить комочки и остудить. Добавить яйцо и водку, перемешать. Порциями всыпать остальную муку, вымесить тесто. Тесто не должно липнуть к рукам, если жидковато – добавить еще муку. Дать постоять в течение часа, один раз обмять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4979,'Раскатать лепешки средней величины, печь на разогретой сковороде, не зажаривать. Складывать на тарелку, накрытую полиэтиленовым пакетом. В такие мягкие лаваши можно завернуть любую начинку. Если домашний тонкий лаваш высушить, то он может храниться несколько дней, при необходимости нужно сбрызнуть водой, снова положить в пакет для размягчения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4980,'Распарить изюм без косточек и обдать кипятком сушеные абрикосы. Дать постоять пять минут, слить воду, обсушить. Порезать небольшими кубиками. Протереть творог через сито. Готовое песочное печенье поломать. Сливочное масло комнатной температуры взбить с сахаром до воздушности, добавлять порциями творог, взбивая. Вмешать в массу изюм, распаренные абрикосы, ванильный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4980,'Перемешать и добавить печенье. Масса должна постоять при комнатной температуре один час. Выложить массу на пищевую пленку, свернуть рулетом, положить под гнет еще на час. Через два часа переложить в холодильник. Рулет можно превратить в торт «Творожный лентяй», если остудить массу в форме для выпечки и украсить любым кремом и дольками консервированных фруктов, ягодами из варенья, листочками мяты, кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4981,'Срезать верх у плодов апельсина, вынуть сердцевину с помощью ножа и ложки. Отварить куриное филе, порезать кубиками. Мелко покрошить свежие огурцы, апельсиновую мякоть. Лишний сок слить. Сварить яйцо, тоже порезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4981,'Майонез смешать с раздавленным зубчиком чеснока, можно посолить. Наполнить салатом апельсиновые «чашечки», посыпать красным перцем, положить на салат «Оранжевое настроение» по веточке зеленого укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4982,'Отварить картофель в «мундире» в течение 10–15 минут, подсолить. Клубни очистить и нарезать ломтиками. Сосиски разрезать пополам вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Пекинскую капусту нарезать тонкой соломкой, натереть морковь на средней терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4982,'Закусочный штрудель с сосисками скрутить, защипать торцовые части, смазать желтком, печь при температуре 180 градусов в течение получаса, до подрумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4983,'На огне в большой кастрюле растворить мед со сливочным маслом и маргарином, добавить соду, размешать венчиком или с помощью миксера, снять с огня. Добавить в массу яйца, продолжая взбивать, всыпать сахарный песок и перемешать. Добавить муку до густоты, вмешивать порциями. Готовое тесто разделить на 25 – 30 частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4983,'Каждую часть медового теста тонко раскатать на пергаменте, вырезать круглые коржи при помощи тарелки и острого ножа. Печь при температуре 180 градусов в течение пяти минут, коржи должны приобрести золотисто-коричневый цвет. Обрезки собрать для посыпки торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4983,'Для крема растворить кофе в кипящей воде. Отдельно смешать сметану с сахаром, добавить кофе, массу взбить миксером или вручную, венчиком. Все коржи промазать полученным кремом и сложить друг на друга. Верх медового торта «Пизанская башня» и бока также смазать кремом. Крошку от коржей смешать с рублеными орехами и обсыпать смесью весь торт. На ночь оставить в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4984,'Ошпарить кипятком изюм, слить воду, ягоды обсушить и смешать с небольшим количеством муки. Сырое яйцо смешат с солью, сахаром, ванилином из пакетика, чуть взбить и влить кефир, растопленное сливочное масло, всыпать манку, изюм, погашенную уксусом соду, перемешать. Дать смеси постоять 15 – 20 минут для набухания крупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4984,'Форму для выпечки смазать сливочным маслом и присыпать манкой. Переложить смесь, разровнять, печь 45 – 50 минут до загустения и образования румяной корочки. Выпечку остудить, переложить на блюдо. Верх манника с изюмом глазировать прогретым медом. Подать с чаем или молоком, киселем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4985,'Разрезать кусок мякоти говядины на куски, посолить и натереть перцем и мускатным орехом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4985,'В большой чугунной сковороде разогреть до шипения масло и с каждой стороны обжарить по 5-6 минут стейки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4985,'Переложить мясо на тарелку и накрыть фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4985,'Нашинковать мелко лук-шалот и обжарить в мясном соке с добавлением оставшегося масла, через 4-5 минут влить мадеру, посолить, поперчить, чуть обжарить, влить разведенный в небольшом количестве воды крахмал, засыпать порезанные грибы, тушить несколько минут пока соус не загустеет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4985,'Говяжий стейк в вине Мадера с грибами поливают соусом и подают горячим с большим количеством овощей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4986,'В любой мясной фарш добавить сырой желток, соль, перец. Сформовать фрикадельки, выложить на сковороду, залить водой до половины и прогревать в духовке до образования корочки. В кипяток всыпать кубики сырого картофеля. Нарубить лук, натереть морковь, обжарить овощи на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4986,'Обжарку положить к картофелю, добавить фрикадельки, варить под крышкой 20 минут. В конце варки в суп с картофелем и мясными фрикадельками добавить порезанный зеленый лук, укроп, петрушку, дать супу постоять 15 минут. Подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4987,'Мелко нарезать крабовое мясо. Сладкий болгарский перец освободить от семечек, нарезать квадратиками. Помидоры нарезать на дольки, а затем поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4987,'Соединить овощи, крабовое мясо, консервированный зеленый горошек, зеленый лук, укроп, петрушку. Заправить салат с крабовым мясом и сладким перцем майонезом, выложить на блюдо и украсить веточками зеленого укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4988,'В молоко добавить какао-порошок, сахарный песок и молотый кофе. Всыпать корицу и тертый мускатный орех. Добавить сок от трех мандаринов. Смесь нагреть, помешивая, не кипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4988,'Прогревать в течение 6 минут.  Выложить в бокалы лед, вылить полученный кофе, добавить сливки. Украсить мокко с молоком очищенными мандариновыми дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4989,'Приготовить тесто. В теплую воду добавить дрожжи и мед, оставить до появления пузырьков. Вмешать соль, оливковое масло, муку. Массу вымесить, скатать шар, выложить в смазанную оливковым маслом миску и убрать на час или два, до увеличения объема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4995,'Взбить перемешанные с ванилью желтки, добавить, не прекращая взбивать по частям молоко, взбивать до получения однородной смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9563,'Залить овощи яичной смесью и поставить в духовой шкаф на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4989,'Тесто раскатать в пласт, смазать смесью оливкового масла и раздавленного чеснока. По поверхности равномерно распределить тертый сыр «Пармезан» и «Моцареллу». Печь сырную пиццу с чесноком до готовности на сильном огне. В смесь оливкового масла и чеснока можно добавить сушеную душицу (орегано).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4990,'Блюдо, приготовленное по этому рецепту, нечто среднее между обычным пирогом и пиццей. Куриное мясо отделить от костей и кожуры, нарезать кусочками и обжарить до полуготовности. Соль, перец – по вкусу. Репчатый лук очистить, нарезать, обжарить на растительном масле до золотистого цвета. Помидоры и сладкий болгарский перец порезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4990,'Приготовить заливку, для этого смешать сырые яйца, сметану, тертый сыр. Готовое слоеное тесто раскатать и разрезать пополам, чтобы получились квадраты. Форму для выпечки смазать маслом, выложить квадраты теста друг на друга так, чтобы углы не совпадали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4990,'Начинку выложить слоями: куриное мясо, репчатый лук, сладкий перец, помидоры, заливка. Углы теста загнуть к центру, печь 30 – 40 минут при температуре 180 градусов. Подать заливной пирог с куриным филе и овощами, порезав на порции и положив по веточке зеленой петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4991,'Нарезать сыр эдам и ветчину соломкой, добавить ломтики помидора и сладкий желтый болгарский перец. Отварить пасту тальятелле, смешать с овощной нарезкой. Заправить майонезом. Украсить итальянский салат зеленью базилика, укропа, петрушки, маслинами без косточек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4992,'Для теста растереть размягченный маргарин с сахарным песком и яйцами, добавить муку, замесить мягкое тесто. Распределить тесто по форме руками, сформовать высокие бортики в 2–3 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4992,'На тесто высыпать арахис, залить сгущенкой. Печь в духовке при температуре 180 градусов до зарумянивания в течение 25 минут.  Остудить орехово-карамельный пирог и нарезать маленькими ромбиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4993,'Отделить желтки от белков, последние поставить в холодильник. Желтки взбить миксером в пену, всыпать сахарный песок, взбивать до растворения. Измельчить в мельнице темный шоколад, просеять. Крупные кусочки оставить для украшения. Охлажденные белки подсолить и взбить в пену, добавить сахар порциями, продолжая взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4993,'В шоколадную крошку всыпать просеянную муку, картофельный крахмал, какао-порошок, разрыхлитель. Смесь постепенно добавлять в желтки и растирать. Затем подмешать белки, осторожно, чтобы пена не опала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4993,'Полученное тесто выложить на застеленный бумагой противень, печь бисквит в течение 10 – 12 минут при 200 градусах. Не пересушивать, горячий бисквит свернуть рулетом вместе с бумагой. Остудить и убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4993,'Приготовить крем, для этого желтки немного взбить с помощью миксера с ванильным сахаром и картофельным крахмалом. Отдельно довести до кипения молоко с сахаром, влить в желтки тонкой струйкой, помешивая. Добавить тертую цедру апельсина, прогревать до загустения. Остывший крем поставить в холодильник, охлажденный растереть миксером с сыром маскарпоне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4993,'Две трети начинки намазать на бисквитный корж и снова свернуть рулетом. Положить его швом вниз, обмазать оставшейся третью крема и посыпать крупной шоколадной крошкой. Подержать выпечку в холодильнике в течение часа. При подаче шоколадно-апельсиновый рулет с маскарпоне украсить дольками апельсина, листочком мяты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4994,'Нарезать кубиками отварную или копченую грудинку, обжарить любые грибы с репчатым луком, отварить и измельчить на терке куриное яйцо. Слить жидкость от консервированной сладкой кукурузы, нарезать соломкой соленый, маринованный или свежий огурец. Фиолетовый лук замариновать: посолить и полить уксусом, нашинковать зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4994,'Приготовить морковь по-корейски, натереть твердый сыр, «Российский» или «Пармезан». Ингредиенты выложить на блюдо сегментами, от центра. Для заправки смешать майонез и сметану в равных пропорциях, добавить зубчик рубленого чеснока. При подаче салат «Ералаш» с куриной грудкой  украсить зеленью петрушки, укропа и зернами граната, соус подать отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4995,'Нагреть на умеренном огне в кастрюле с широким дном сахар и кокосовое молоко, не доводить до кипения!',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'Филе курицы нарезать в длину лентами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4995,'Все перелить опять в кастрюлю, довести при слабом нагреве  практически до кипения, непрерывно помешивая венчиком, быстро убрать с огня, продолжать мешать пока смесь не примет консистенцию крема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4995,'Перелить смесь в миску, остудить до комнатной температуры, долить к напитку темный ром, все перемешать, накрыть пленкой и убрать в холод на 3 часа (но лучше до утра).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4995,'Подать «Эггног» кокосовый с ромом в высоких стаканах, украсить сверху взбитыми сливками и присыпать корицей и мускатным орехом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4996,'Помидоры среднего размера нарезать ломтиками поперек, выложить их на блюдо в один слой, посолить и поперчить по вкусу. Для заправки смешать майонез и сметану в равных пропорциях, добавить рубленый зубчик чеснока, смесью смазать слой помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4996,'Зеленый лук промыть, обсушить и нарезать, посыпать помидоры. Натереть твердый сыр и посыпать блюдо сверху. Поставить помидоры под сырной шубой  в холодильник на два часа для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4997,'«Длинный» рис любого сорта поставить варить в подсоленной воде. При готовности откинуть на дуршлаг.  Свиную шейку нарезать кубиками со стороной в 2 — 3 см. Обжарить на сковороде до румяной корочки, выложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4997,'На жире, оставшемся от жарки, в течение 1 – 2 минут обжарить порезанный лук-шалот и рубленый чеснок. Добавить очищенный и натертый корень имбиря, кубики моркови и сладкого перца, зеленый горошек. Его можно использовать в свежем или замороженном виде. Всё вместе прогреть в течение 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4997,'При готовности овощей, они должны стать мягкими, вернуть на сковороду обжаренное мясо и положить отваренный рис.  Добавить соль, перемешать, тушить рис со свининой и овощами на сковороде еще 5 – 7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4998,'Смешать в равных пропорциях сметану и майонез, два сырых яйца, просеянную муку. Тесто должно получиться жидким, как для оладий. Вылить массу в сковороду, выложить на нее начинку: нарезанную колбасу или сосиски, соленые огурцы или маринованные оливки, грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4998,'Смешать поровну майонез и кетчуп, смазать поверхность. Посыпать тертым сыром. Поставить простую пиццу на тихий огонь на плиту. Блюдо будет готово через 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4999,'Вскипятить воду, развести желатин, помешивая, добиться однородности, чтобы не было комочков. Отдельно развести желе из пакетика по инструкции на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4999,'Измельчить любое песочное печенье в блендере в крошку, добавить растопленное сливочное масло, хорошо перемешать, дать постоять, чтобы масло впиталось. Измельчить печенье можно вручную, в полиэтиленовом пакете, чтобы крошки не разлетелись по кухне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4999,'На дно разъемной формы выложить пекарскую бумагу так, чтобы бортики были закрыты. Выложить массу из печенья ровным слоем, прижать толкушкой или стаканом, поставить корж в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4999,'Для начинки смешать крем-сыр «Филадельфия» или аналогичный, сметану, сахарный песок, ванилин из пакетика, взбить в течение 4 – 5 минут, масса должна увеличиться вдвое. В конце добавить лимонный сок и снова взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (4999,'Полученный крем вылить на корж из печенья и снова поставить в холодильник. Свежую клубнику вымыть, обсушить на бумаге и разрезать ягоды на половинки. Выложить чизкейк с клубникой на застывший крем, залить ложкой на ягоды остывшее желе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5000,'Тушку цыпленка вымыть, обсушить. Удалить с кожи всё лишнее с помощью пинцета. Мелко нарезать репчатый лук, шампиньоны – пластинками. Обжарить на оливковом или любом растительном масле сначала лук, потом добавить грибы, потушить до готовности. Соль, перец – по вкусу. Мелко порубить один или два зубчика чеснока и добавить в грибную начинку. Полученной смесью начинить цыпленка, заколоть брюшко зубочистками или зашить иголкой с ниткой. Тушку посолить, поперчить и смазать густой сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5006,'Приготовить гречневую кашу, для этого стакан крупы залить двумя стаканами воды, посолить и варить до готовности. При готовности кастрюлю закрыть полотенцем и дать постоять 10 – 15 минут. Нарезать шампиньоны или вешенки ломтиками, мелко нарезать репчатый лук, порубить зелень. Обжарить лук на растительном масле, добавить грибы, жарить еще 15 минут. По вкусу посолить и поперчить, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10543,'Креветки разморозить, промыть теплой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5000,'Форму для запекания застелить фольгой, положить курицу спинкой вниз, завернуть в фольгу. Печь в разогретой духовке или в аэрогриле, в первом случае — на средней решетке, во втором – на нижней. Для запекания потребуется полтора-два часа. В конце приготовления фольгу нужно приоткрыть, смазать курицу еще раз сметаной, дать подрумяниться. При подаче запеченную курицу с грибами в фольге разрезать на порционные куски, вынуть начинку, разложить в тарелки, полить соком от жарки, посыпать зеленью укропа, петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5001,'Просеять муку через сито, перетереть ее со сливочным маслом в мелкую крошку. Отдельно погасить соду лимонным соком или уксусом, добавить сметану, соль, сахарный песок, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5001,'Нарезать мелкими кубиками, со стороной в полсантиметра, свежую клубнику, перемешать мучную смесь со сметано-сахарной и нарезанными ягодами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5001,'Противень смазать растопленным сливочным маслом, выложить готовое тесто ложкой, в виде печенья. Посыпать сахаром и печь при температуре 180 градусов в течение 20 – 25 минут до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5002,'Куриное филе нарезать  соломкой, обжарить на оливковом или любом растительном масле. Посолить и поперчить, в конце обжаривания добавить немного воды и потушить 5 – 6 минут. Тонко нарезать шампиньоны, поджарить вместе с рубленым репчатым луком на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5002,'Для соуса смешать оливковое масло или любое растительное, цедру половины апельсина и апельсиновый сок. Добавить рубленый чеснок, перемешать.  Соломку куриного филе смешать с грибами и выложить массу на листья зеленого салата. Полить салат с курицей апельсиновым соусом и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5003,'Для приготовления коржа понадобиться готовое печенье, квадратной формы, и чашка крепкого остуженного кофе. Для приготовления помадки смешать сахарную пудру, какао-порошок, растворимый кофе, горячее молоко и растопленное сливочное масло. Перемешать венчиком, не взбивая, до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5003,'При необходимости массу можно прогреть в течение нескольких секунд в микроволновой печи. Для начинки смешать творог с сахарным песком и какао-порошком. Развести желатин без цветовых и вкусовых добавок в небольшом количестве молока и влить в творожную массу. На большой лист плотного целлофана выложить печенье, окуная его в кофе. «Корж» должен быть прямоугольной формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5003,'Творожную массу разделить на три части, промазать им два слоя печенья, верх торта также покрыть массой. Приподнять края целлофана так, чтобы получился треугольник-«избушка». Прижать руками и завернуть в целлофан, положить на ночь в холодильник. Перед подачей намазать торт «Домик» шоколадной помадкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5004,'Нарезать филе телятины кубиками 2,5-3 см, поперчить, посолить, сбрызнуть соком лимона, перемешать и дать постоять, нагреть в сковороде масло до шипения и обжарить кусочки мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5004,'Почистить яблоки, удалить семенную коробку, нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5004,'Переложить телятину в кастрюлю, залить кипящей водой с растворенным сахаром, положить яблоки, дать закипеть, залить вино, добавить корицу, гвоздику и тушить 50-60 минут на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5004,'После того как мясо станет мягким, снять кастрюлю с плиты, дать блюду настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5004,'Как гарнир к тушеной в вине телятине с яблоками и корицей подать рис или картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5005,'Темный шоколад поломать на кусочки, добавить кубики сливочного масла и поставить на водяную баню. Растопить и смешать ингредиенты до однородности. Снять с огня и остудить. Смешать сырые куриные яйца, сахарный песок, ванильный сахар из пакетика, соль – по вкусу. Влить в смесь шоколадную массу, перемешать. Всыпать просеянную муку и разрыхлитель, вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5005,'Форму для выпечки средних размеров смазать растопленным сливочным маслом, вылить тесто, разровнять. Печь в духовке при 180 градусах в течение 20 – 25 минут. Масса должна остаться немного сыроватой, рыхлой. Выпечку остудить, разрезать на прямоугольники. Подать классический брауни с горьким шоколадом к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5013,'Смешать желтки с корицей, сахаром, ванилином и содой, взбить все венчиком и частями добавить сливки и муку, вымесить тесто до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5013,'Осторожно соединить с тестом взбитые белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5006,'Грибную обжарку измельчить в блендере или пропустить через мясорубку. Массу смешать с гречневой кашей, зеленью, сырым яйцом для вязкости. Слепить шарики, обвалять их в муке и панировочных сухарях, жарить, поворачивая, со всех сторон, на растительном масле. Выложить готовые тефтели в кастрюлю с толстым дном. Для заливки смешать соус «Краснодарский», воду, специи, соль. Залить смесью гречневые тефтели с грибами и потушить 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5007,'Яичные белки отделить от желтков и взбить в пену.  Добавить просеянную муку и сахар, тертый темный шоколад, ванилин, корицу и кардамон. Массу вымешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5007,'Застелить противень пергаментом, чайной ложкой или с помощью кондитерского шприца выложить тесто. Печь шоколадное безе при температуре 180 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5008,'Замесить мягкое тесто из просеянной муки, теплой воды, растительного масла и шепотки соли. Скатать массу в шар и завернуть в пленку, оставить на час для набухания клейковины. Отварить картофель, приготовить пюре, добавить в него зеленый лук, свежую рубленую зелень кинзы и петрушки, соль, молотый перец. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5008,'Разделить тесто на пять частей, раскатать, на каждую положит приготовленную картофельную начинку, обернуть плотно тестом и защипать к середине. Полученные лепешки перевернуть и тонко раскатать. Жарить индийскую паратху на сильном огне в течение минуты, перевернуть, смазать растительным маслом. Через минуту снова перевернуть и смазать маслом, снова перевернуть и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5009,'Очистить шампиньоны, нарезать пластинками и обжарить на растительном масле.  Сладкий болгарский перец вымыть, удалить сердцевину с семечками и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5009,'Порубить зелень петрушки и базилика, чеснок. Для приготовления заправки смешать растительное масло, уксус, рубленый чеснок, соль, молотый черный перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5009,'На тарелку выложить листья пекинской капусты или зеленого салата, на них — смесь грибов с перцем. Посыпать салат с грибами и болгарским перцем зеленью и полить масляной заправкой с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5010,'Отделить желтки от белков. Желтки взбить с сахарным песком до белого цвета, вмешать просеянную муку, смешанную с какао-порошком, ванилином, разрыхлителем.  Белки взбить с солью и лимонной кислотой, масса должна стать плотной. Смешать с желтками, осторожно, движениями снизу вверх, чтобы пена не опала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5010,'Противень застелить пергаментной бумагой и смазать сливочным маслом. Вылить тесто слоем в один сантиметр, печь при температуре 180 градусов в течение 5 – 8 минут, до образования упругой корочки. Выпеченный корж перевернуть на чистое полотенце, снять пергамент, свернуть рулетом до остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5010,'Приготовить крем из упаковки или самостоятельно из взбитых сливок, сливочного масла и крем-сыра, сгущенного молока. Осторожно развернуть рулет, пропитать корж любым алкогольным напитком, намазать крем, снова свернуть. Готовую выпечку переложить на блюдо, украсить небольшим количеством того же крема. Положить бисквитный рулет с кремом в холодильник на несколько часов или на ночь для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5011,'Смешать тертую цедру одного лимона, молотый мак, сахарный песок, ванилин из пакетика. Всыпать просеянную муку, смешанную с содой. Влить стакан молока, положить сырое яйцо, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5011,'Заполнить тестом смазанную маслом и присыпанную мукой форму для выпечки. Печь до готовности. Готовый корж разрезать по горизонтали острым ножом пополам, промазать  повидлом, верх пирога «Маковник» посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5012,'Растереть со сливочным маслом сахарный песок и ванилин из пакетика, взбить. Добавить пачку творога, снова взбить. Добавить по одному три сырых яйца. Всыпать просеянную муку с разрыхлителем. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5012,'Выложить массу в смазанную форму на две трети объема. Печь при 180 градусах в течение 40 минут. Готовность выпечки проверить зубочисткой, она должна остаться сухой. Приготовить глазурь из молока и сахарной пудры, немного поварить и остудить. Украсить творожный кекс сахарной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5013,'Разбить яйца и отделить аккуратно белки от желтков, взбить белки с добавлением соли, чтобы белки лучше взбивались яйца нужно брать холодными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5013,'Вылить половником на середину хорошо разогретой сковороды порцию теста. Брать такое количество теста, чтобы блинчики не растекались и оставались в диаметре 10-12 см, обжарить с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5013,'Классические панкейки на сливках – блинчики по-американски подают с кленовым сиропом, но вкусно будет и с любым другим или даже с вареньем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5014,'Приготовить коржи, для этого смешать содержимое банки сгущенного молока, добавить сырое яйцо, перемешать. Влить погашенную уксусом соду, подсыпать муку. Переложить на присыпанный мукой стол и домесить, тесто должно быть эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5014,'Разделить массу на восемь частей, раскатать в коржи круглой формы, наколоть вилкой. Печь на среднем огне на сковороде, по одной минуте с каждой стороны. Готовые коржи ровно обрезать с помощью ножа и круглой тарелки, крошки оставить для обсыпки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5014,'Приготовить крем: влить в кастрюлю молоко, добавить два яйца, две столовые ложки муки, стакан сахарного песка, пакетик ванилина, взбить венчиком. Варить на тихом огне до загустения, помешивать. В горячий крем добавить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5014,'Промазать коржи горячим кремом и обсыпать крошкой. Для украшения торта «Изумрудная черепаха» можно выложить всю поверхность выпечки тонко нарезанным киви. Из кусочков фрукта вырезать «голову» и «ножки» черепахи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5015,'Слабосоленую семгу нарезать большими тонкими ломтиками. Вымыть свежие огурцы, нарезать кубиками или соломкой. Натереть или порубить чеснок. Творожный сыр «Филадельфия» или «Альметте»  смешать с чесноком и огурцами, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5015,'На семгу выложить полученную сырную начинку и свернуть рулетами. Подать с тонко нарезанными кружками лимонов, сами закусочные рулеты из семги также можно сбрызнуть лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5016,'Любую печень, свиное сало и обжаренный репчатый лук попустить через мясорубку. Добавить сырые яйца, измельченный чеснок, натертый сырой картофель. Всыпать муку, соль, перец. Массу перемешать и жарить котлеты из печени с картофелем на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5017,'Натереть цедру одного лимона, смешать её с нарезанным свежим тимьяном (богородской травой), оливковым маслом. Нарезать любые грибы, выложить в блюдо для запекания, сбрызнуть половиной лимонной смеси, соль, перец – по вкусу. Печь 10 минут. Посыпать грибную массу тертым сыром и печь еще пять минут, влить оставшуюся смесь и лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5018,'Смешать с помощью миксера яйца и сахарный песок. Вмешать стакан просеянной пшеничной муки и пакетик разрыхлителя. Отдельно смешать растительное масло и кипяток, смесь вылить в тесто и перемешать лопаткой. Форму для выпечки застелить бумагой, вылить тесто, печь в духовке в течение получаса при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5018,'Для приготовления заливки смешать сгущенку, концентрированное молоко и сливки. Бисквит наколоть зубочисткой, вылить на него заливку порциями, оставить торт «Три молока» на несколько часов или на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5019,'Филе любой рыбы разморозить и отжать лишнюю жидкость. Нарезать на куски средней величины, посолить, поперчить, посыпать паприкой или любой приправой для рыбы. Взбить сырые яйца с мукой. Обмакнуть каждый кусочек в кляр и обжарить на сковороде в течение нескольких минут, до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5019,'Выложить рыбу на противень, добавить поверх каждого кусочка кольца репчатого лука и кружки помидоров в виде «башенок». Сверху – немного майонеза или сметаны, посыпать тертым твердым сыром, «Российским» или «Пармезаном». Печь филе рыбы с помидорами под сыром  в течение 15–20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5020,'Ошпарить и обсушить лимон, цедру натереть, из мякоти выжать сок. Нарезать кусочками очищенные киви, яблоко, банан, клубнику, добавить целый виноград без косточек, зеленый или черный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5020,'Взбить сметану со сливками до состояния крема, добавить ванильный сахар, лимонный сок и цедру. Фрукты и ягоды разложить в тарелки, креманки или десертные бокалы, залить полученным кремом. Поставить в холодильник на полчаса. При подаче салат из фруктов с лимонным кремом украсить листочками свежей мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5027,'Разлить по стаканам ром, бросить в каждый небольшую порцию изюма и несколько бутонов гвоздики, залить горячим вином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5021,'Протереть через сито творог, добавить сахарный песок, перемешать. Вбить в массу три яйца, по одному, добавить растопленное сливочное масло и тертую цедру одного лимона, перемешать. Просеять муку с ванильным сахаром и разрыхлителем, небольшими порциями всыпать сухую смесь в творог, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5021,'В форму для выпечки положить маленькие бумажные формочки, наполнить их тестом на три четверти объема. Печь творожные кексики при 180 градусах в течение 25 – 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5022,'Клубни картофеля очистить и нарезать на четыре части. Варить в подсоленной воде до готовности около 20 минут. Слить воду и мелко нарезать. Шампиньоны промыть, очистить и мелко порубить. Репчатый лук также мелко измельчить. Очистить сладкий болгарский перец от семян и порубить. Нарезать шинку, помидоры, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5022,'Растопить сливочное масло или маргарин, можно использовать оливковое или любое другое растительное масло без ярко выраженного запаха. Обжарить на сковороде картофель до румяной корочки, переложить в другую посуду. На той же сковороде растопить еще немного сливочного масла, добавить смесь овощей и ветчину, готовить на среднем огне около десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5022,'Сырые яйца немного взбить, посолить, поперчить. Добавить картофель, давленый чеснок. В сковороду выложить почти готовый картофель, залить яичной смесью, прогревать в течение 20 минут на тихом огне. Блюдо поставить на гриль на три минуты. Готовую овощную фриттату с грибами и ветчиной убрать с огня и посыпать тертым сыром, снова поставить на огонь до расплавления сыра. Подать в горячем виде, порезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5023,'Загрузить в чашу для замеса сначала сухие дрожжи, муку, соль, сахарный песок, ванилин. Затем – жидкие ингредиенты: размягченное сливочное масло, молоко, сметану, яйцо. Замесить тесто, раскатать в тонкий пласт толщиной в полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5023,'Массу раскатать. Лепешку смазать растительным маслом без запаха, посыпать маком и сахаром. Свернуть в рулет, разрезать на десять частей. Выложить в ведерко для выпечки, оставить на выстойку на один час. Выпечь сдобный хлеб с маковой начинкой в хлебопечке до готовности в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5024,'Окорок нарезать кубиками, мелко порубить чеснок, тонко нарезать очищенные клубни картофеля. Перемешать, соль, перец – по вкусу.  Взять форму для запекания среднего размера, с высокими бортиками. Смазать поверхность растопленным сливочным маслом, посыпать рубленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5024,'Заполнить форму картофельной массой, полить сливками, посыпать тертым сыром. Печь при 200 градусах в течение 45 – 55 минут, выключить духовку и дать постоять в ней блюду еще 5–10 минут. Подать картофельную запеканку с окороком, порезав на порции, посыпать свежей зеленью укропа, петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5025,'Нарезать грибы и очищенный картофель соломкой. Натереть морковь, репчатый лук нарезать кубиками. Картофель отварить в кипящем курином бульоне почти до готовности. Спассеровать на сливочном масле измельченные лук и морковь, добавить грибы и обжарить всё вместе в течение нескольких минут на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5025,'Обжарку переложить в суп и дать закипеть. Натереть любой плавленый сырок и добавить в суп, продолжать кипятить, через 10 минут – выключить огонь. Соль, перец, лавровый лист – по вкусу, в грибной суп с сыром можно добавить зелень укропа и петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5026,'Разогреть сковороду с оливковым маслом или любым другим растительным без запаха, обжарить на среднем огне куриную грудку, соль, перец – по вкусу. На обжаривание одной стороны потребуется около семи минут, затем эту сторону смазать медом, перевернуть, смазать другую сторону, огонь увеличить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5026,'Продолжать переворачивать, нужно, чтобы мясо впитало в себя максимум меда. Можно добавить немного воды. Приготовить сэндвич из двух кусков хлеба с готовой грудкой, листом зеленого салата и нарезанным помидором.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5027,'Залить хорошо промытый изюм на полчаса белым ромом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5027,'Срезать овощечисткой половину цедры с лимона, нашинковать крупной соломкой, разломить на половинки палочку корицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5027,'Налить в кастрюлю вино, засыпать сахар, добавить цедру, корицу, поставить на средний огонь, непрерывно размешивая довести практически до кипения, снять с плиты и удалить из вина цедру и палочки корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5028,'Охладить и натереть на терке сливочное масло. Смешать сырое яйцо с растительным маслом и уксусом, долить ледяную воду и перемешать до однородного состояния. Растереть руками просеянную пшеничную муку со сливочным маслом в крошку, добавить жидкую смесь. Замесить тесто, разделить его на семь частей, накрыть пленкой и поставить в холодильник на один час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5028,'Для приготовления начинки добавить рубленую зелень лука и укропа, сырые яйца, соль по вкусу. Массу перемешать. Раскатывать тесто по одной порции на присыпанном мукой столе руками, затем скалкой. Остальная масса должна находиться в холодильнике. Корж должен быть очень тонким, просвечивать. На середину лепешки выложить две-три ложки творожной начинки, оставляя края свободными. Острым ножом надрезать тесто на шесть сегментов от центра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5028,'Взять два противолежащих сегмента и по очереди закрыть ими начинку от краев к центру лепешки. Затем то же проделать с остальными сегментами. Прижать по кругу всю плацинду, чтобы слепить тесто.  Жарить на сковороде с растительным маслом в течение пяти минут, выкладывать швами вниз. Перевернуть плацинду с творожной начинкой и обжарить с другой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5029,'Замесить тесто из просеянной пшеничной муки, воды, растительного масла, соли, сахара и пакетика сухих дрожжей. Оставить массу в теплом месте на час. Затем разрезать на кусочки, слепить шарики, выложить на смазанный маслом лист, накрыть тканью и дать постоять еще 20 – 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5029,'Пампушки выложить на противень, смазать взбитым яйцом и печь при температуре 220 градусов в течение 20–25 минут. Очистить чеснок и растолочь с солью в ступке, добавить растительное масло и немного воды. Смазать теплые чесночные пампушки этой смесью и дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5030,'Смешать воду, молоко, ванильный экстракт, молотую гвоздику и корицу, кардамон. Довести до кипения, уменьшить огонь и прогревать еще 10 минут, помешивая. Прибавить огонь, довести до кипения, выключить и добавить пакетики с чаем улун.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5030,'Накрыть крышкой на четыре минуты. Пакетики вынуть, чай отцедить через сито в кувшин, добавить сахар и лед. Такой чай хранится в холодильнике в течение суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5031,'Ребрышки вымыть и нарезать на порции.  Для приготовления маринада снять цедру с апельсина и лайма, натереть или мелко порезать, выжать сок из мякоти. Пропустить через пресс зубчики чеснока, смешать с соком и цедрой. Добавить ложку готовой горчицы, молотую паприку и черный перец, оливковое масло, мёд и сушеный укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5031,'В готовую пряную смесь поместить ребрышки, оставить мариноваться в холодильнике в течение 2 – 3 часов. Выложить ребрышки в два слоя фольги, полить медовым маринадом, завернуть и печь в духовке при температуре 180 градусов в течение полутора часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5032,'Поломать кусочками горький шоколад, добавить сливочное масло, смесь прогреть на водяной бане до полного растворения и смешивания ингредиентов. Взбить сырые яйца с ванилином из пакетика, коричневым сахаром, соль – по вкусу. Порциями добавить шоколадно-масляную массу во взбитые яйца, перемешать. Всыпать муку, снова перемешать. Тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5032,'Вылить массу на противень, распределить ровным слоем по всей поверхности, печь при 180 градусах в течение 10 – 12 минут.  Массу остудить и покрошить, измельчить в миксере. Понемногу влить ром, продолжая вымешивать. Слепить ромовые шарики и обвалять в сахарном песке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5033,'Филе рыбы разрезать на части. Смешать соевый соус и кунжутное масло, добавить тертую цедру апельсина и коричневый сахар, влить сок половины апельсина. Залить филе половиной сахарно-апельсиновой смеси и дать постоять 15 минут. Застелить фольгой противень, выложить рыбу, печь 10 – 15 минут при температуре 180 градусов, до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5033,'Перемешать порванные руками листья зеленого салата, нашинкованную красную капусту, нарезанную соломкой морковь. Сверху выложить готовое рыбное филе, полить оставшимся апельсиновым маринадом. Посыпать салат с лососем и красной капустой семечками кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5051,'Полученным соусом полить картошку, печь картофель в беконе со сметанным соусом в духовке еще 10 – 15 минут. При готовности посыпать блюдо свежей рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9306,'Филе порезать на полосы, у грибов слить рассол, если есть крупные, то порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5034,'Снять кожицу с лайма, нарезать зеленую петрушку и очищенные зубчики чеснока тонкими пластинками. Очистить и натереть корень имбиря, чили разрезать вдоль, а затем полосками поперек. Семечки можно не вынимать, это добавит блюду остроту. Растереть в ступке цедру лайма,  чеснок, петрушку и имбирь до состояния пасты. Добавить сок лайма, оливковое масло, посолить, поперчить. Разрезать свиную корейку на четыре отбивных на косточках. Натереть мясо полученным маринадом, сложить в посуду и дать постоять 40 – 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5034,'Посуда должна быть прикрыта пищевой пленкой. Обжарить мясо в толстостенной сковороде на растительном масле при температуре чуть выше средней. Жарить по две минуты с каждой стороны до образования золотистой корочки, кусочки продуктов из маринада с поверхности мяса лучше удалить, они начнут гореть при обжаривании. Сложить корейку в форму для запекания, полить остатками маринада, печь  свиные отбивные в пикантном маринаде 20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5035,'Нарезать репчатый лук и обжарить на оливковом масле, на тихом огне, в течение 20 минут. Нарезать очищенную тыкву и груши кубиками, залить все ингредиенты кипящим овощным бульоном или обычной водой. Варить до готовности, превратить массу в пюре с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5035,'Можно влить еще бульон или водой, если суп получился слишком густым. Добавить йогурт, греческий или соевый, соль и перец – по вкусу. При готовности разлить крем-суп из тыквы в тарелки, положить по чайной ложке йогурта и посыпать рубленым зеленым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5036,'Измельчить стакан любых орехов, сухое песочное печенье поломать в крошку в полиэтиленовом пакете. Протереть через сито творог и смешать его с мягким сливочным маслом и сахарной пудрой. Разделить массу на три части. В первую добавить рубленые орехи, во вторую – печенье, в третью – какао-порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5036,'Из орехово-творожной массы скатать маленький шарик, положить его в лепешку из творожной массы с печеньем, закатать. Получившийся шарик положить на лепешку из творога с какао и снова закатать. Конфеты «Творожные шарики» обмакнуть в сгущенное молоко, затем кокосовую стружку или тертый шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5037,'Кальмары очистить от пленок, внутренностей, промыть холодной проточной водой, порезать соломкой или кольцами. Выложить морепродукт в форму для запекания, залить сливками, посыпать тертым твердым сыром. Печь в духовке при температуре 200 градусов 20 минут, затем мощность увеличить еще на 50 градусов и печь кальмары в сливках под сыром до зарумянивания 7 – 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5038,'Смешать очищенные креветки с крупно помолотым черным перцем и солью, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5038,'Выложить в сковороду сливочное масло, растопить, добавить креветки, слегка обжарить до розоватого цвета около 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5038,'Сделать нагрев меньше, налить в креветки текилу и поджечь. Встряхнуть несколько раз сковороду и дождаться пока пламя не утихнет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5038,'Снять креветки с плиты, налить сливки или сметану, перемешать, всыпать мелко нарезанный зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5038,'Подавать креветки с текилой в сливках горячими с отварным рисом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5039,'Растворить дрожжи в теплом молоке, добавить соль, сахарный песок, сырое яйцо и просеянную пшеничную муку. Замесить мягкое тесто, положить в полиэтиленовый пакет, укутать тканью и оставить в тепле на 30 – 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5039,'Натереть твердый сыр, порезать  свежий или консервированный ананас и сосиски. Подошедшее тесто раскатать в лепешку и намазать кетчупом. Выложить сосиски и ананас, давленый чеснок, посыпать пиццу тертым сыром. Печь пиццу с сосисками и ананасом около получаса при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5040,'Порезать по одному килограмму белокочанной капусты, помидоров, огурцов, сладкого болгарского перца, натереть столько же моркови. Если какого-то ингредиента нет – заменить его удвоенной нормой другого овоща.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5040,'Массу перемешать, влить растительное масло, уксус, соль и сахар. Снова перемешать и поставить на огонь, довести до кипения, кипятить две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5040,'Горячую массу разложить в стерильные, пропаренные, банки и закатать. Перевернуть и укутать до остывания консервов. Хранить салат овощной «Гениальный» в прохладном месте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10556,'Тесто должно получится как очень густая сметана.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5041,'Пропустить через пресс чеснок, натереть твердый сыр, перемешать. Порубить зелень. Размять вилкой консервированную в масле горбушу. Репчатый лук мелко нарезать и обжарить на растительном масле. Отварить яйца, морковь, натереть отдельно на терке. Свежий огурец также натереть. На блюдо для салата выложить готовые вафельные коржи и прослоить их приготовленными овощами, каждый смазывать майонезом и солить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5041,'На первый корж намазать майонез, выложить рыбу, лук, морковь, закрыть вторым коржом. Затем майонез, измельченные яйца, снова корж, майонез, тертый огурец с зеленью, корж, майонез, чеснок с тертым сыром. Закрыть пятым коржом, майонез, посыпать нарезанными крабовыми палочками и морковью. Поставить закусочный торт «Рыбный» с горбушей в холодильник для пропитывания на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5042,'Смешать сметану с просеянной мукой. Взбить яйца с сахарным песком, добавить  сметанную массу, ванилин из пакетика и соль по вкусу. Соду погасить уксусом или лимонным соком, перемешать все ингредиенты до однородного состояния. На сковороде разогреть сливочное масло, жарить оладьи средней величины с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5043,'Порубить куриную грудку, выложить в миску и посыпать индийскими специями гарам масала. Добавить молотый черный перец, соль, перемешать. Всыпать муку. В этой смеси обвалять курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5043,'Обжарить мясо на разогретой сковороде с растительным маслом до готовности. Переложить курицу на тарелку. Огонь уменьшить, обжарить в той же сковороде нарезанный репчатый лук, через три минуты добавить рубленый чеснок и имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5043,'Выложить в сковороду консервированные томаты в собственном соку, жидкость слить. Влить молоко и добавить специи, соль и перец по вкусу. Довести массу до кипения, убавить огонь, тушить 15 минут до загустения соуса. Вернуть в соус курицу, прогреть куриное филе масала 2–3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5044,'Залить кипящей водой три сорта цветного желе быстрого приготовления, размешать и дать полностью застыть. Замочить желатин в стакане холодной воды, через 40 минут прогреть до растворения, не кипятить. Массу остудить. Смешать с помощью блендера нежирный творог с йогуртом и сахарным песком, добавить готовый желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5044,'Форму выстлать пищевой пленкой. Застывшее цветное желе порезать на крупные кубики, выложить в виде мозаики на дно формы, залить творожной массой. Охладить в холодильнике. При подаче творожный торт-желе «Битое стекло» разрезать на части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5045,'Порвать руками листья салата, порезать помидоры черри и сыр моцарелла и выложить на зелень. Немного обжарить очищенные кедровые орехи на сухой сковороде.  Для заправки смешать оливковое масло, лимонный сок, посолить, поперчить по вкусу. Полить смесью салат и посыпать кедровыми орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5046,'Налить в кувшин заваренный зеленый чай, добавить лимонный сок, листочки мяты и кипяченую воду. Охладить, разлить в стаканы, при подаче украсить мятой и тонкими ломтиками лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5047,'Для приготовления теста смешать холодное, натертое сливочное масло, нежирный протертый творог и сахарный песок. Добавить просеянную пшеничную муку, перемешать до образования мягкого теста. Замесить на присыпанном мукой столе. Готовую массу разделить на четыре части, сформовать плоские лепешки прямоугольной формы, обернуть каждую пищевой пленкой и положить в холодильник для набухания клейковины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5047,'Приготовить маковую начинку, для этого основной ингредиент нужно хорошо перемолоть. Обдать кипятком изюм без косточек, обсушить. Прогреть в кастрюле смесь молока, сахара и сливочного масла, до кипения не доводить. В горячую смесь добавить молотый мак, прогревать, помешивая, пока не впитается часть жидкости. Получившаяся масса должна напоминать кашу. Снять начинку с огня, добавить изюм и ванилин из пакетика, измельченную цедру лимона, ванилин, по щепотке корицы и молотого мускатного ореха, перемешать, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5047,'Для яблочной начинки нарезать плоды кубиками. Обдать кипятком сухофрукты, курагу и чернослив, обсушить и мелко нарезать. Перемолоть грецкие орехи на кусочки и миндальные – в муку. Растопить  молочный шоколад вместе со сливочным маслом, при помешивании всыпать тертую лимонную цедру, молотую корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Для приготовления ганаша растопить на водяной бане горький шоколад.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5047,'Порцию теста вынуть из холодильника, тонко раскатать, толщина должна быть 2 – 3 мм, присыпать мукой. На поверхность лепешки выложить часть маковой начинки, края загнуть внутрь, закатать в виде рулета. Так же поступить со второй порцией теста и яблочной начинкой: поверхность лепешки посыпать молотым миндалем для впитывания излишней жидкости, затем выложить массу и завернуть. Перед выпечкой штруделей смазать их смесью сырого желтка и молока. Печь творожный штрудель с двумя начинками на противне при температуре 180 градусов в течение 30 – 35 минут.  При подаче посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5048,'Измельчить в блендере чеснок и репчатый лук, добавить говяжий фарш, орегано, тертый сыр «Пармезан». Добавить панировочные сухари, молотый черный перец и соль по вкусу. Перемешать. Из получившейся мясной массы слепить небольшие шарики, выложить в блюдо, печь в течение 15 минут при температуре 200 градусов. Затем обжарить фрикадельки на сковороде, на растительном масле, до коричневой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5048,'Добавить к блюду сухие травы и томаты в собственном соку, довести до кипения на среднем огне. Огонь уменьшить, потушить еще в течение часа на тихом огне. Соль и молотый перец – по вкусу. Отдельно отварить пасту феттучини в кипящей воде с солью и небольшим количеством растительного масла. Разложить в тарелки, сверху  на феттучини — фрикадельки из говядины, рубленая петрушка, тертый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5049,'Сливочное масло натереть на терке или порубить острым ножом. Всыпать просеянную пшеничную муку, растереть массу руками, в крошку. Вбить яичный желток, замесить тесто в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5049,'Для выпечки взять разъемную форму. Застелить дно бумагой. От готового теста отщипывать кусочки теста и залепить ими всю поверхность формы, сформовать бортики в три сантиметра высотой. Заготовку для коржа убрать в холодильник на 20 минут или в морозилку на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5049,'Вынуть форму из холодильника и сразу поставить в разогретую до 200 градусов духовку. Печь 10 минут, до получения золотистого цвета. Можно перед выпечкой застелить поверхность теста фольгой и засыпать фасолью или сушеным горохом и выпечь корж в таком виде. Горох для выпечки можно использовать многократно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5049,'Для приготовления начинки влить в кастрюлю сливки, добавить кусочки шоколада, сливочное масло, прогреть массу до растворения и состояния однородности, помешивать. Готовый мусс снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5049,'Отдельно немного взбить яйца, влить смесь в шоколад, помешивать, яйца не должны свернуться. Начинку вылить на готовый теплый корж, вернуть в духовку и печь еще 5–10 минут при той же температуре. Шоколадный тарт остудить в течение получаса в прохладном месте, при подаче посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5050,'Замесить крутое тесто из муки и воды с сырым яйцом. Завернуть в пищевую пленку и поставить на час в холодильник. Тесто разделить на две части, очень тонко раскатать, тесто должно просвечивать, смазать жидким топленым маслом, свернуть рулетом по спирали, посыпав мукой. «Улитку» завернуть в пищевую пленку и положить в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5050,'Нарезать мелкими кубиками баранину и курдючный жир, чуть мельче, тоже кубиками, — репчатый лук. Смешать мясо с луком, посолить, поперчить, добавить зиру и кориандр, другие специи, перемешать. Дать постоять 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5050,'Тесто вынуть из холодильника и осторожно развернуть «улитку», вернуть тесту форму рулета. Разрезать его на кусочки по 5 см, положить срезом на стол, сформовать лепешки средней величины. Раскатать и положить по столовой ложке начинки, придать пирожкам любую форму: они могут быть прямоугольными, треугольными или круглыми.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5050,'Перед выпечкой  самсу с бараниной смазать поверхность смесью яйца и молока, посыпать семечками кунжута. Печь при температуре 210 – 220 градусов в течение получаса или чуть больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5051,'Некрупные клубни вымыть и отварить в «мундире». Остудить, очистить. Нарезать бекон тонкими полосками, завернуть в них каждую из картошек, положить в форму и печь в течение 10 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5051,'Приготовить соус: разогреть сливочное масло, добавить муку, размешать, чтобы не было комочков. Влить бульон, можно сделать его из кубика. Дать смеси закипеть, снять с плиты, влить сметану, соль по вкусу, молотый черный перец, лимонный сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5052,'Тонкими пластинками нарезать картофель, обжарить на растительном масле до образования золотистой корочки. Выложить на бумажные полотенца, дать впитаться лишнему жиру. Немного посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5052,'Нарезать лук кольцами, затем разрезать их на четыре части, обжарить на сливочном масле до состояния прозрачности. Натереть морковь, добавить в лук и потушить их вместе до мягкости. Нарезать ветчину соломкой, перемешать с овощной обжаркой. Разболтать сырые яйца, добавить сметану, тертый сыр, соль, любые специи, массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5052,'Дно формы для выпечки смазать растительным маслом, выложить картофель, половину начинки, смазать сметанным соусом. Снова слой картофеля, начинка, заливка. Сверху – третий слой картофеля и заливка. Печь картофельную запеканку с ветчиной в сметане около получаса при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5053,'Отварить клубни в «мундире», остудить и очистить от кожуры.  Для приготовления соуса мелко измельчить очищенные зубчики чеснока, зелень петрушки, натереть твердый сыр. Ингредиенты соединить с мягким сливочным маслом, добавить сметану, соль, молотый перец по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5053,'Картофель разрезать вдоль на половинки, выложить в смазанную маслом форму для выпечки. Сверху – чесночный соус. Печь картофель в чесночно-сметанном соусе при температуре 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5054,'В мясной фарш добавить панировочные сухари, соль, перец, перемешать. Сформовать фрикадельки, лучше это делать мокрыми руками. Нарубить репчатый лук, натереть морковь, нарезать крупными кубиками очищенный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5054,'Все ингредиенты всыпать в кипящую воду, довести до кипения, соль, перец-горошек – по вкусу. Положить фрикадельки и варить 15 – 20 минут. За пять минут до готовности положить в картофельный суп с фрикадельками лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5055,'Для приготовления теста смешать сырое яйцо, просеянную пшеничную муку, сметану и майонез в равных пропорциях. Тесто должно получиться полужидким. Вылить массу на смазанную сковороду среднего размера, выложить порезанные сосиски, соломку копченой колбасы, немного прожаренные грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5055,'Закрыть начинку тонко нарезанными помидорами, сделать «сеточку» из майонеза. Посыпать тертым сыром «Пармезан» или «Российский». Печь пиццу «Минутка» на сковороде в течение 10 минут на небольшом огне, под крышкой, до расплавления сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5056,'Мелко нарезать репчатый лук и спассеровать на сливочном масле до золотистого цвета. Порубить зелень укропа. Отварить картофель, воду посолить. Приготовить пюре, добавить обжаренный лук, рубленый укроп и сливочное масло, теплое  молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5056,'Приготовить тесто из молока, сырых яиц, соли по вкусу и просеянной муки. Вымесить до состояния эластичности и очень тонко раскатать. Вырезать кружки размером с блюдце, переложить на тарелку, пересыпав мукой, чтобы не слиплись. Обжарить на сухой сковороде, без масла, до готовности. Готовые лепешки смазать топленым сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5056,'Выложить на каждый кузикмяк начинку из картофеля с луком, сложить пополам, смазать маслом. Накрыть блюдо полотенцем, дать постоять полчаса и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5057,'Нежирный творог смешать с сахарным песком и взбить блендером. Желатин замочить в холодной воде, дать набухнуть и влить в теплое молоко. Прогреть до растворения, не кипятить. Влить в творожную смесь, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5057,'Разделить массу на три части, в одну добавить какао-порошок, в другую – растворимый кофе, немного разбавленный водой, в третью – ванилин из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5057,'Форму или салатницу выстелить пищевой пленкой, выложить смеси поочередно, по две столовые ложки каждой, слоями. Поставить «Мраморный» десерт в холодильник на пять часов для полного застывания желе. При подаче форму перевернуть на блюдо и снять пленку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5058,'Готовое слоеное тесто раскатать, смазать небольшим количеством майонеза. Натереть колбасу, твердый сыр, «Российский» или «Пармезан», посыпать рубленой зеленью. Свернуть рулет, нарезать на кусочки, смазать немного взбитым яйцом и печь слоеные рулеты в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5059,'Яйца отварить вкрутую, дать остыть, затем очистить и мелко измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5059,'С филе трески снять кожицу, порезать тонкими кусочками, немного отбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5059,'Очистить лук, мелко порезать и поджарить на масле, далее к луку добавить измельченные яйца, добавить перец, соль, все как следует перемешать и снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5059,'Полученный луково–яичный фарш разложить на куски рыбы, филе завернуть так, чтобы котлета из трески в кляре по-никитовски получилась продолговатой, со всех сторон обсыпать мукой, обмакнуть во взбитом яйце, в конце обвалять в сухарях и поставить в холод на 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5059,'Котлеты обжарить на сковородке с каждой стороны в большом количестве масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5060,'Взбить сахарный песок с сырыми яйцами в пышную массу. Растопить маргарин, остудить до комнатной температуры и влить в яичную массу, еще раз взбить в пену. Добавить муку, просеянную вместе с разрыхлителем, перемешать. Влить сметану небольшими порциями, дать тесту немного постоять, для набухания муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5060,'Для начинки перемешать творог, сырое яйцо, сахар, пачку ванильного пудинга и ванильный сахар. Тесто раскатать, вырезать кружки средней величины. На одну половину выложить творожную начинку и прикрыть второй, не защипывать. Смазать верх яйцом, печь сочники с творожно-ванильной начинкой в духовке около 20 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5061,'Вылить в миску кефир, добавить сырое яйцо, соль по вкусу и сахарный песок. Перемешать массу венчиком. Всыпать муку, просеянную вместе с содой, замесить тесто, оно должно получиться полужидким. Оставить на 10 – 15 минут для набухания. Выпечь домашние оладьи на масле, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5062,'Клубни картофеля вымыть, почистить и порезать толстыми пластинками. Отварить в соленой воде в течение пяти минут, воду слить. Нарезать репчатый лук квадратиками, шампиньоны – произвольно. Обжарить на масле до прозрачности половину лука, добавить грибы и жарить еще 7 – 8 минут, в конце добавить соль, молотый перец, тимьян. Массу переложить в другую посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5062,'На этой же сковороде обжарить остатки рубленого лука, добавить говяжий фарш, жарить пять-семь минут. Влить томатную пасту, стакан сливок, добавить соль и перец, молотую паприку, перемешать. Смесь прогреть до кипения, положить грибную обжарку, потушить продукты вместе в течение двух-трех минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5062,'В форму выложить половину грибной массы с фаршем, затем слой картофеля, вторую часть начинки. Посыпать тертым твердым сыром. Печь картофельную запеканку с фаршем в течение получаса. При подаче посыпать рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5063,'Отварить клубни картофеля в «мундире» до готовности, остудить, очистить от кожуры и нарезать на кружки толщиной в полсантиметра. Нарезать и обжарить на растительном масле репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5063,'Смазать маслом форму для запекания, выложить слой картофеля, затем лук, промазать сметаной, повторить слои еще несколько раз. Посолить, поперчить и посыпать тертым твердым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5063,'Печь запеканку из картофеля с сыром в духовке в течение 30 – 35 минут при температуре 180 градусов. Подать блюдо горячим, посыпать свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5064,'Отварить неочищенный картофель, остудить, снять кожицу, натереть на крупной терке. Добавить соль и молотый перец, сырое яйцо и просеянную муку. В смешанный мясной фарш добавить специи, холодную воду или кефир, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5064,'Картофельное тесто раскатать в колбаску и нарезать кусочками. Сформовать лепешки, выложить мясную начинку, оставив один из краев свободным. Закрутить рулеты, свободный край теста прижимать. Готовые изделия обжарить на масле с двух сторон до образования золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5064,'Выложить картофельные рулеты с мясным фаршем в форму для запекания, поставить в духовку на 15 – 20 минут, температура – 200 градусов. За пять минут до конца приготовления посыпать тертым сыром и допечь до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5065,'Отварить рис, мелко нарезать крабовые палочки, слить жидкость из банки с консервированной кукурузой. Отварить яйца, порубить. Мелко порезать лук-репку.  В блюдо с высокими бортиками выложить треть отваренного риса, смазать майонезом, затем выложить половину рубленых яиц, майонез, половину крабовых палочек, снова майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Переложить содержимое сковороды в кастрюлю, залить бульоном, заправить тимьяном, кайенским перцем, лавровым листом, добавить помидоры, посолить и варить около 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5065,'Высыпать всю кукурузу, смазать майонезом, выложить вторую часть риса, майонез, остатки крабовых палочек, майонез. Насыпать весь лук, майонез, яйца, майонез, оставшийся рис. Накрыть салат-торт из риса с кукурузой блюдом, на котором он будет лежать, перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5066,'Куриное филе вымыть, обсушить и нарезать небольшими кусочками. Выложить в глубокую сковороду с растительным маслом, посолить, жарить, помешивая, в течение 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5066,'Очистить, вымыть и мелко нарезать шампиньоны. Переложить к куриному филе, жарить 7 – 8 минут. Добавить плавленый мягкий сыр и жарить до полного растворения последнего.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5066,'Отварить макароны, слить воду, промыть большим количеством проточной воды. Переложить в сковороду с грибами и курицей, перемешать и прогреть вместе три-четыре минуты. Подать макароны с грибами и куриным филе, посыпав зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5067,'Отделить белки от желтков. Белки взбить в крепкую пену, добавляя постепенно сахарный песок. Желтки взбить отдельно и подмешать к белкам. Всыпать просеянную пшеничную муку, кукурузный крахмал и разрыхлитель для теста, перемешать. Влить лимонный сок и немного красного пищевого красителя, чтобы масса приобрела нежный розовый цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5067,'На дно разъемной формы выложить пекарскую бумагу, вылить готовое тесто и разровнять. Печь 20 – 25 минут на сильном огне. Открыть дверцу духовки и дать остыть в течение 10 минут. Отделить ножом корж по краям и дать ему полностью остыть, не вынимая из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5067,'Вымыть и очистить клубнику от «хвостиков», взбить в блендере в однородное пюре. Часть ягод нарезать кубиками и оставить для украшения. Перемешать сыр «Маскарпоне» с творогом и клубничным пюре. Смешать загуститель для сливок с сахарным песком, массу подмешать к сырному крему. В треть крема положить нарезанную клубнику.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5067,'Готовый корж вынуть из формы, разрезать по горизонтали острым ножом на две половины. Нижнюю часть смазать кремом с кусочками ягод, накрыть второй частью и выложить весь крем с ягодным пюре, смазать бока розового бисквитного торта. Поставить массу на час-полтора в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5068,'Куриное филе пропустить через мясорубку. В получившийся фарш добавить белый, заранее замоченный в молоке, черствый хлеб без корочки. Излишки молока отжать. Посолить, поперчить, массу вымесить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5068,'Для начинки натереть охлажденное сливочное масло и твердый сыр, «Российский» или «Пармезан», порубить чеснок и зелень петрушки, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5068,'Из куриного фарша сформовать лепешки, положить по две чайные ложки начинки, слепить зразы. Окунуть во взбитое яйцо, а затем обвалять в панировочных сухарях. Обжарить с двух сторон до образования золотистой корочки. При подаче зразы из куриного филе с сыром украсить зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5069,'Смешать пшеничную муку с «живыми» или сухими дрожжами, добавить соль, сахарный песок, сливочное масло, молоко и сырые яйца, все продукты должны быть  комнатной температуры. Замесить тесто. Миску смазать маслом, выложить полученную массу, затянуть пищевой пленкой и поставить в тепло на один час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5069,'Очистить сосиски. Тесто раскатать и разрезать на полоски шириной два сантиметра. Каждую сосиску обернуть и уложить на застеленный пекарской бумагой противень. Накрыть тканью и оставить на полчаса для расстойки. Печь сосиски в дрожжевом тесте в духовке до готовности при температуре 220 градусов. Подать теплыми.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5070,'Обжарить на растительном масле фарш или нарезанную колбасу, добавить мелко нарубленный репчатый лук, соль и перец – по вкусу. Массу перемешать и тушить пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5070,'Взбить яйца, добавить молоку, просеянную пшеничную муку, всыпать соду, погашенную уксусом, соль, сахарный песок.  Массу перемешать и вылить на смазанный противень. Печь 2 – 3 минуты при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5070,'Нарезать пластинками помидоры, натереть твердый сыр. Выложить на омлет, сверху – колбаса или фарш с луком, зелень, сыр, печь еще 15 минут. При подаче омлет-пиццу украсить веточками укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Когда овощи размякнут добавить петрушку, остававшийся лук, креветки и тушить еще 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Затем положить крабовое мясо, бекон, посолить, потушить 1-2 минуты, снять с плиты, удалить лавровый лист',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5071,'Грибы вымыть, почистить, отварить в течение 5 – 7 минут. Нарезать кусочками. Отварить до мягкости морковь и нарезать кубиками. Очистить чеснок и порубить. Нарезать зелень укропа. Отварить куриное филе, нарезать мелкими кубиками его и твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5071,'Отварить куриные яйца, мелко покрошить. Все ингредиенты перемешать и выложить на блюдо, соль, перец, майонез – по вкусу. При подаче салат «Цыпленок» с грибами и сыром украсить веточками укропа, листочками зеленого салата. Подать с черным хлебом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5072,'Кусочек черствого белого хлеба без корочки замочить в небольшом количестве молока. Дать набухнуть и отжать. Куриное филе измельчить в блендере или мясорубке, добавить хлеб, посолить, поперчить. Замесить фарш, слепить небольшие «колобки».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5072,'Круглозерновой рис отварить до полуготовности. Стеклянную огнеупорную форму для выпечки смазать растопленным сливочным маслом, присыпать панировочными сухарями, выложить на них рис. Сверху – любые размороженные овощи, отжатые от излишков влаги. Уложить куриные «колобки», между шариками насыпать рубленый репчатый лук, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5072,'Отдельно взбить яйца с молоком, соль, перец – по вкусу. Залить полученной смесью запеканку и поместить блюдо в духовку на 40 – 45 минут, печь при температуре 200 градусов. При подаче рисовую запеканку с куриными шариками посыпать рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Приготовить не очень жидкое картофельное пюре, остудить и выложить в виде змеи на плоское блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Очищенный и мелко нарезанный лук замариновать вместе с уксусом и сахаром либо с соком лимона, затем выложить на пюре и смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'На сковороде обжарить, с добавлением растительного и сливочного масла, нарезанные грибы и лук, остудить, выложить слоем поверх лука, тоже смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Отварить до готовности филе курицы, дать остыть, нарезать небольшими кусочками и покрыть им грибы, промазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Натереть на терке сыр, выложить слоем и смазать майонезом, затем аккуратно размазать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Измельчить чипсы в мелкую крошку, обсыпать блюдо, из целых чипсов сделать змее корону, глаза, украсить клюквой или смородиной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5073,'Картофельная «Змейка» с грибами, курицей и чипсами в конце оформляется зеленью, которую следует выложить по краям туловища змейки на блюдо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5074,'Нарезать кусочками ягоды клубники и очищенный банан. Взбить в миксере нежирный творог и влить две столовые ложки заваренного кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5074,'Выложить треть бананов на дно большой плоской салатницы. Затем слой клубники, тертого темного шоколада, творожно-кофейной массы, снова бананы, ягоды, творог. Посыпать верх шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5074,'Блюдо поставить в холодильник на несколько часов, можно на ночь. При подаче клубничный тирамису украсить нарезанными ягодами клубники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5075,'Взбить мягкое сливочное масло или маргарин с яйцами. Отдельно смешать просеянную пшеничную муку, какао-порошок, соду и соль, перемешать. Сухую смесь всыпать в масляную, перемешать и добавить сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5075,'Массу вылить в форму для выпечки и печь 30 — 40 минут, готовность проверить зубочисткой, она должно остаться сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5075,'Для начинки взбить сливки миксером в течение одной минуты, всыпать загуститель, снова взбить. Добавить нарезанную кусочками клубнику и банан. Вылить массу на шоколадный бисквит.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5076,'Раскатать готовое слоеное тесто, острым ножом нарезать на 30 одинаковых полосок, можно воспользоваться ножом для пиццы. Каждую полоску закрутить вокруг конусовидной формочки. Вставить формы на противень и печь до золотистого цвета в течение 12 – 15 минут. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5076,'Для приготовления крема взбить миксером сливочный сыр с сахарным песком до однородного состояния в течение 3 – 4 минут. Добавить сливки и ванилин, продолжать взбивать, ввести готовые взбитые сливки из баллончика и осторожно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5076,'Переложить полученный крем в кондитерский мешок, начинить выпеченные трубочки на половину объема, положить по ягоде малины или клубники, заполнить трубочки сливочным кремом до конца. Сверху также украсить свежей ягодой. При подаче посыпать блюдо сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10581,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5077,'Маргарин растопить и охладить до комнатной температуры. Взбить яйца с сахаром в пену. Добавить к яйцам маргарин, просеянную пшеничную муку и перемешать. Разогретую вафельницу смазать растительным маслом, положить столовую ложку теста, печь 2 – 3 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5077,'Горячую вафлю свернуть в трубочку. Для крема смешать мягкое сливочное масло с вареной сгущенкой. Остывшие вафельные трубочки наполнить начинкой с помощью кондитерского шприца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5078,'Желатин залить водой на 10 минут, затем влить молоко и подогреть до растворения желатина, не кипятить. Смешать протертый творог, сметану, добавить желатиновую массу. Разделить на три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5078,'В первую добавить какао-порошок, во вторую – крошки печенья, третью оставить без добавок. Выложить смеси в силиконовую форму, чередуя слои. Поставить десерт-желе с творогом в холодильник на несколько часов. Перевернуть на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5079,'В глубокой сковороде на разогретом оливковом масле обжарить креветки и мидии, последние должны раскрыться. В глубокой кастрюле разогреть оставшееся оливковое масло, обжарить на нем рубленый репчатый лук и чеснок, посыпать молотой паприкой, шафраном, добавить по вкусу соль и молотый перец, лавровый лист. В смесь добавить круглозерный рис, тушить пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5079,'Отдельно разогреть заранее сваренный рыбный бульон, влить его в рис, тушить в течение получаса. Можно еще немного поперчить и посолить. Переложить рис на большое блюдо, сверху – морепродукты. Украсить зеленью петрушки, подать паэлью с мидиями и креветками к столу в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5080,'Отварить картофель, натереть, перемешать с обжаркой из репчатого лука и моркови. Соль, перец, специи – по вкусу. Массу перемешать. Рыбное филе перемолоть в фарш, добавить замоченный в молоке и отжатый хлеб, рубленую зелень петрушки и укропа, посолить, поперчить, всыпать специи для рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5080,'Смазать форму маслом, выложить половину картофельной массы, затем рыбный фарш и оставшиеся овощи. Верх запеканки смазать немного взбитым яйцом. Печь запеканку из рыбного филе с овощами в духовке в течение 40 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5081,'Очистить тыкву, нарезать её на куски и запечь в духовке при температуре 180 градусов в течение 40 – 45 минут. Остудить, приготовить пюре. Добавить в массу по половине порции сахара и манки, яйцо, перемешать. Добавить в творожную массу 3 столовые ложки сахарного песка, оставшуюся манку, одно яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5081,'Положить вымытый и подсушенный изюм, перемешать. Форму для выпечки смазать сливочным маслом, положить сначала тыквенную, а потом творожную массу, слои повторить несколько раз. Выпечь запеканку из тыквы с изюмом и творогом в течение 50 – 60 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'Мелко нашинковать лук, порубить зелень петрушки, выжать сок из лимона, сыр разломить на мелкие кусочки, влить молоко, стебель сельдерея порезать на несколько частей вдоль, а затем поперек на длинные кусочки (по 6-8 см).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'Добавить сметану, все поперчить, посолить, получившийся соус хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'Креветки почистить, но хвостики оставить не очищенными, сложить в миску, посыпать солью, перцем, добавить оливковое масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'Разогреть гриль и отправить жариться креветки на 6-7 минут, если гриль газовый, то за это время их надо перевернуть 1 раз, при отсутствии гриля креветки обжарить с небольшим количеством оливкового масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'Распустить на водяной бане сливочное масло, добавить острый перечный соус типа чили, перемешать, полить этим соусом креветки и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5082,'При подаче креветки под острым соусом с сыром и сельдереем полить соусом из голубого сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Нарезать на тонкие ломти бекон, в чугунной сковороде обжарить на слабом огне, чтобы стал коричневым, переложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'Нашинковать репчатый лук, мелко порезать сельдерей, болгарский перец, чеснок, слить из помидоров сок и тоже измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5083,'В сковороду с жиром от бекона добавить растительное масло, добавить муку, и постоянно помешивая обжарить до коричневого цвета (20 минут), засыпать измельченные овощи (без помидоров) и третью часть нарезанного лука, тушить пока не размякнут (15-20 минут).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Включить миксер на высокую скорость, взбить сливочное масло (50 г оставить для глазури), сахар и ванильный экстракт, примерно через 3 минуты, когда смесь станет светлеть, по одному добавить яйца (не переставая взбивать), а потом абрикосовое пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Смешать полученную смесь с мучной, переключить миксер на слабую скорость и взбить смесь до однородной массы, добавить измельченные орехи и еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Переложить тесто в форму и поставить запекать в духовку на 45 минут, дать пирогу остыть в форме 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Приготовить из оставшегося масла, сливочного сыра, корицы, ванили и сахарной пудры глазурь, взбив миксером все до воздушности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Осторожно отделить пирог ножом от стенок, накрыть форму тарелкой и перевернуть ее. Теперь пирог на тарелке накрыть другой и еще раз перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5084,'Смазать остывший торт глазурью, на стол имбирно-абрикосовый пирог с глазурью и орехами подается после полного остывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Измельчить по отдельности на мясорубке семена укропа и розовый перец, смешать часть (2\3) перца с укропом, нарезанным мелко чесноком, солью и растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Сделать в окороке ряд глубоких продольных надрезов, втереть в них укропно-чесночную пасту и обмазать весь кусок мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Положить окорок в форму и убрать мариноваться в холодильник на 8-9 часов, затем достать свинину и дать постоять час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Разогреть духовку (170-180 градусов), запекать мясо около 2 часов, выложить готовое на доску и дать полчаса остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Налить вермут в кастрюлю, влить столовую ложку сока от запекания мяса, дать закипеть и через 2 минуты влить бульон, добавить оставшийся измельченный розовый перец и 5 минут варить на сильном огне пока объем жидкости не станет равным 1 стакану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Распустить сливочное масло, всыпать муку, перемешать и добавить все к соусу, проварить, непрерывно мешая венчиком 2 минуты до тех пор, пока соус не загустеет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5085,'Перед подачей нарезать свиной окорок с вермутом и розовым перцем кусками и полить соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5086,'Очистить красное яблоко от шкурки и семенной коробки, нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5086,'Растопить на сковороде небольшого диаметра масло, после исчезновения пены высыпать сахар, размешать и дать ему раствориться, подрумянить каждый ломтик яблока с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5086,'Взбить яйца с солью, вылить смесь на яблоки и запечь, сдвигая поджаренные края к центру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5086,'Когда останется слегка жидкой только середина омлета, налить туда густых сливок и пару ложек вареной сгущенки, завернуть лопаточкой треть омлета на сковороде внутрь, потом наклонить сковороду над тарелкой и дать половине омлета соскользнуть, а затем резким движением перевернуть сковороду и дать омлету таким образом свернуться в трубочку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5086,'Сладкий омлет с яблоками в глазури разделить на две порции, посыпать сахарной пудрой и подать горячим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'Разрезать говяжье филе на 4 стейка, натереть каждый солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'Обжарить стейки на раскаленном масле и сильном огне по 5-9 минут с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'Переложить стейки на блюдо и дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'Смешать раздавленный прессом чеснок с солью, консервированной фасолью, бульоном, маслом и все измельчить блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'Положить в сковороду к соку от стейков томатную пасту, 1 ч.л. розмарина и прожарить полминуты, налить вино, перемешать и довести до кипения, добавить пюре из фасоли и половину маслин порезанных кольцами, жарить 3 минуты, выключить нагрев, поперчить, посолить, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5087,'При подаче на стол говяжий стейк с фасолевым пюре и маслинами посыпать оставшейся половиной колечек из маслин и розмарином.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5088,'Залить семена льна кипятком и дать время набухнуть и выделить слизь, включить духовку на разогрев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5088,'Просеять муку, перемешать с разрыхлителем, орехами, овсяными хлопьями, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5088,'Сделать банановое пюре, добавить растительное масло и лен.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5177,'Отварить куриную грудку. Цветной болгарский перец и большую луковицу нарезать соломкой, добавить мясо, порванное по волокнам на кусочки или нарезанное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5088,'Приготовить из бананового пюре и мучной смеси тесто, по консистенции оно должно подходить для лепки булочек, при необходимости добавлять кипяченую воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5088,'Противень застелить пергаментной бумагой и смазать ее маслом, формовать влажными руками небольшие булочки круглой или вытянутой формы, а можно и треугольной и выкладывать на противень, готовы постные банановые булочки по-американски будут через 20-25 минут. Есть их лучше теплыми.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5089,'Снять с мандаринов полоску цедры (8 на 2 см), выдавить 1\3 стакана сока, тонко нарезать цедру соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5089,'Смешать в кастрюле сок с цедрой, тертым имбирем, клюквой, изюмом, сахаром, нагревать смесь, помешивая до кипения, и полного растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5089,'Проварить еще 20 минут, когда клюква начнет лопаться выключить нагрев и охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5089,'Подавать клюквенный соус с изюмом, мандарином и имбирем можно как самостоятельный десерт, или с взбитыми сливками, или бисквитом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Смазать кисточкой формочки для кексов распущенным сливочным маслом, убрать на 2 минуты в холодильник, достать и повторить операцию, после чего припудрить формочки мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Выставить миксер на высокую скорость и взбить масло и стакан сахара с добавлением соли до воздушного состояния, добавить желтки от яиц и взбить, прибавить к смеси 2 ст.л. лимонного сока, 1 ст.л. натертой цедры лимона и взбить все миксером до однородности, включить духовку для разогрева.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Переключить миксер на медленную скорость, всыпать муку (добавлять частями) и перемешать до однородности теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Взбить белки с солью до состояния жидкой пены, добавить 2 ст.л. сахара и взбить до консистенции пышного густого крема.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Смешать его до однородности с тестом',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Ввести белковый крем в тесто, перемешать до однородности, смешать чайную ложку цедры лимона с 2 ст.л. сахара.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Разложить тесто в формочки, присыпать смесью цедры и отправить в духовку с температурой 190 градусов, кексы будут готовы через 25 минут, дать им остыть в формочках 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Смешать для сиропа полтора стакана воды, полстакана лимонного сока, веточки свежего базилика (8 шт.), цедру лимона, всыпать оставшийся сахар, нагреть до кипения на слабом огне, периодически помешивая, когда сироп закипит снять крышку и варить еще 10 минут, процедить и дать остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5090,'Достать кексы из формочек, лимонные кексы в лимонном сиропе с базиликом разложить по глубоким тарелкам (пиалам) и залить сиропом, украсить взбитыми без сахара сливками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Сварить высушенный инжир до мягкости (около 40 минут), чтобы уменьшить время варки инжир можно предварительно замочить на ночь и отварить в той же воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Измельчить инжир блендером в пюре с добавлением виски и ванили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Подсушить в нагретой (180 градусов) духовке орехи в течение 10 минут, остудить и крупно перемолоть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Смешать просеянную и муку с солью, корицей, содой, разрыхлителем и мускатным орехом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Выставить миксер на высокую скорость и взбить масло с яйцами и сахаром до состояния крема (порядка 3 минут).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Переключить миксер на медленную скорость и смешать яичную смесь с пюре из инжира.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Продолжать взбивать и постепенно подсыпать мучную смесь до получения однородного теста, добавить к нему орехи и еще раз перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Заполнить тестом форму для выпекания и отправить в духовку, готов пекановый пирог с орехами, инжиром и виски будет примерно через 80 минут, дать остыть ему прямо в форме.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5091,'Пирог будет еще вкуснее, если его заранее приготовить и выдержать один день в герметично закрытом контейнере, хранится такой пирог не более 5 суток.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5092,'Нарезать кружками баклажаны, кабачки и помидоры, брынзу – тонкими пластинками. Противень с антипригарным покрытием смазать растительным маслом, поставить вертикально овощи и сыр, чередуя слои.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5099,'Достать мясо из маринада, перенести на противень и полить сверху маринадом, включить на разогрев духовку или гриль, запечь свинину до готовности, окорок поливать периодически сверху смесью маринада и сока от запекания мяса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5092,'Для приготовления соуса нарезать кубиками лук, помидоры, сладкий болгарский перец. Мелко порубить чеснок, смесь потушить на одной столовой ложке растительного масла. Массу можно взбить в блендере до однородного состояния или оставить кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5092,'Вылить соус на овощи, накрыть фольгой и печь в духовке в течение получаса при 180 градусах. Снять фольгу и допечь еще полчаса до готовности. Лишняя жидкость должна выпариться. При подаче рататуй с брынзой посыпать рубленой свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5093,'Для теста соединить муку, творог, яичные желтки, сахарный песок и соль по вкусу. Перемешать, поставить в холодильник на два часа. Вынуть косточки из свежих вишен, дать постоять, чтобы выделился сок. Очистить от кожуры и сердцевины яблоки, нарезать их кубиками, обжарить на сковороде, добавив молотую корицу и коньяк. Соединить массу с вишнями, добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5093,'Тонко раскатать тесто на пергаментной бумаге, выложить начинку, разровнять. Свернуть рулетом, печь в течение 35 минут при температуре 180 градусов. Подавать австрийский штрудель с яблоком и вишней теплым или холодным, посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5094,'Полпачки макарон-«бабочек» отварить почти до готовности. Обжарить на сковороде нарезанную итальянскую колбасу с пряностями вместе с рубленым репчатым луком, чесноком и орегано. Форму для запекания смазать сливочным маслом, выложить слой любого домашнего или магазинного соуса для спагетти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5094,'Затем слой отваренных макарон, снова соус, тертый сыр моцарелла. Посыпать тертым твердым сыром пармезан, следующий — слой обжаренной колбасы с луком, половина свежих нарезанных шампиньонов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5094,'Для второго слоя: оставшаяся паста, соус, моцарелла, пармезан, кубики ветчины, грибы. Третий слой: паста, соус, моцарелла, пармезан и нарезанная колбаса пепперони. Печь запеканку с макаронами и колбасой в течение 45 минут в духовке при 190 градусах. Немного остудить и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5095,'Перемешать сырые куриные яйца с молоком, вылить на горячую сковороду. Огонь убавить, накрыть крышкой, прогревать две минуты. На омлет выложить тертый сыр, нарезанную колбасу и рубленую зелень, сверху – еще немного тертого сыра, свернуть рулетом с помощью лопаток, прогреть омлет-рулет с колбасой на сковороде швом вниз еще минуту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5096,'Лимон промыть и поместить в морозилку. Замороженный плод натереть на терке вместе с кожурой. Этой лимонной «крошкой» можно посыпать супы, крупяные блюда, макароны, салаты, пасту, рис, любые блюда из рыбы, суши, десерты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5097,'Очистить кальмары, отварить в течение пяти минут, остудить, нарезать тонкой соломкой, добавить отваренные креветки. Нарезать соломкой репчатый лук, замариновать в смеси воды и уксуса, который можно заменить лимонным соком. Через 15 – 20 минут процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5097,'Нарезать брусками свежий огурец и яблоко. Все ингредиенты соединить, добавить консервированную кукурузу без жидкости, предварительно отваренный рис, рубленую зелень лука и петрушки, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5097,'При подаче салат «День рождения» с креветками и кальмарами заправить майонезом. Украсить маслинами, веточками зеленого укропа или петрушки, отваренными и очищенными креветками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Обрезать с мякоти свинины жир и разрезать ее на куски, мясо натереть перцем и дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Измельчить лук на мясорубке или приготовить луковое пюре в блендере, все овощи нарезать кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Выложить слоями в неглубокую кастрюлю овощи: половину огурцов, морковь, мясо, лук, цуккини, снова огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Залить в кастрюлю кипяток, последний слой огурцов должен лишь слегка покрываться водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Готовить блюдо на сильном огне, довести до кипения, а потом варить до мягкости мяса, свинина с огурцами, морковью и цуккини должна настояться после окончания варки 15-20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5098,'Мясо и овощи разложить по тарелкам и подать с греческим йогуртом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5099,'Нарезать мелко лук и чеснок, смесь пассировать в глубокой сковороде на оливковом масле до прозрачности лука, добавить соус барбекю, перемешать и прогреть несколько минут все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5099,'Время приготовления запеченного свиного окорока в маринаде с соусом барбекю зависит от веса взятого куска мяса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5100,'Несколько зубчиков чеснока нарезать тонкими пластинками, остальные – мелко порубить. Свинину без костей вымыть, обсушить бумажным полотенцем. Сделать надрезы острым ножом, нашпиговать пластинками чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5100,'Растолочь в ступке приправы: зерна кориандра, фенхель и сельдерей. Добавить соль, щепотку кайенского перца, черный молотый перец, рубленый чеснок, зернистую дижонскую горчицу, оливковое масло. Массу перемешать до однородности, обмазать свинину. Держать мясо в холодильнике от двух часов до суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5100,'За полчаса до приготовления вынуть свинину  из холодильника. Завернуть в фольгу, печь в духовке при температуре 180 – 190 градусов в течение 45 – 55 минут. Вынуть буженину с чесноком из духовки, подержать в фольге еще полчаса, развернуть. Подать, нарезав тонкими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5101,'Филе тилапии разморозить, посолить и поперчить, выложить в форму для запекания. Посыпать тертой лимонной цедрой, сбрызнуть лимонным соком. Смазать сметаной, посыпать тертым твердым сыром. Печь в  духовке в течение 20 – 25 минут при температуре 180 градусов. Филе тилапии под сыром подать на листьях зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Натереть кусок свиной вырезки молотым черным перцем и солью, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Очистить яблоки от кожуры и семенной коробки, порезать тонкими дольками, включить духовку для разогрева (необходимо 200 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Распустить сливочное масло, добавить растительное и хорошо разогреть сковороду, подрумянить свинину со всех сторон около 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Отправить сковороду с мясом в духовку на 15 минут, переложить мясо на блюдо, прикрыть на 15 минут фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Когда сковорода чуть остынет, и масло перестанет пениться, положить  яблоки, присыпать корицей и на среднем огне потушить до мягкости и золотисто-коричневого цвета 5-6 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Переложить яблоки на блюдо, а в сковороду влить куриный бульон, сидр и на сильном огне дать закипеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Развести в холодной воде крахмал и влить на сковороду, размешать, проварить 5 минут и дать соусу загустеть, его объем должен уменьшиться до стакана.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Снять соус с огня, добавить уксус, посолить, поперчить, перемешать до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5102,'Свинина жареная с сидром, яблоками и  корицей подается нарезанной на крупные ломти, поливается соусом и гарнируется запеченными яблоками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5103,'Для приготовления соуса смешать сырые куриные желтки с дижонской горчицей без семян, добавить соль по вкусу. Массу взбить до увеличения объема. Медленно влить оливковое масло, продолжая взбивать. Добавить сок лайма и лимона, снова взбить. Два анчоуса обсушить на бумажном полотенце, размять в пюре. Натереть сыр пармезан, его и анчоусы добавить в соус и снова хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5103,'Куриную грудку нарезать средними кусочками. На сухую сковороду насыпать, соль, черный молотый перец, карри и смесь прованских трав. Раскалить специи, добавить оливковое масло, куриное филе, обжарить до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5103,'Для приготовления гренок нарезать кубиками белый батон. Отдельно смешать оливковое масло, соль и рубленый чеснок. Выложить в противень сухарики, полить полученной смесью, присыпать орегано и печь в духовке 10 минут, гренки должны зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5103,'Листья салата ромэн  порвать руками, полить салат «Цезарь» полученным классическим соусом, выложить курицу, затем помидоры черри, еще немного соуса, посыпать гренками. Сверху посыпать тертым пармезаном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5104,'Заварить кофе, добавить сахарный песок, остудить. Консервированные персики взбить в блендере, добавить холодный кофе, три шарика мороженого, взбить до однородности. Перелить коктейль «Персиковый кофе» в бокал, украсить сливками, подать с соломинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5105,'Взбить яйца с сахаром, добавить растительное масло, лимонный сок и цедру, взбить. Просеять и смешать с разрыхлителем муку, всыпать в яичную смесь, вымесить. Добавить нежирную сметану, перемешать и выложить в формочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5105,'Печь ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5106,'Свинину нарезать кусочками три на два сантиметра. Потушить в сковороде на растопленном сливочном масле. Порубить репчатый лук и добавить к свинине, тушить вместе до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10611,'Варить все вместе двадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5106,'В казане или кастрюле растопить оставшуюся треть масла, выложить мясо с луком, соломку сладкого болгарского перца, дать закипеть. Выложить сверху очищенные клубни картофеля, разрезанные на четыре части. Долить воду, чтобы она покрыла картофель. Тушить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5106,'За 15 минут до окончания приготовления всыпать нарезанную морковь, перец-горошек, лавровый лист, соль и молотый перец – по вкусу, добавить паприку. За пять минут до готовности посыпать домашнее жаркое со свининой рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5107,'Отварить картофель в «мундире», очистить и нарезать ломтиками. Порубить свежий базилик и смешать с картофелем. Полить смесь лимонной заправкой, оставить на полчаса в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5107,'Нарезать дольками помидоры, смешать с картофелем, зеленью укропа и петрушки. Готовый картофельный салат разложить в тарелки, добавить оливки, украсить оставшимся рубленым базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5108,'Отделить яичные желтки от белков. Растереть  то и другое по отдельности с сахарным песком, белки взбить до увеличения объема. Всё смешать, добавить какао-порошок, просеянную пшеничную муку, погашенную уксусом или лимонным соком соду. Массу выложить в смазанную форму, печь при температуре 180 градусов в течение получаса. Корж остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5108,'Приготовить начинку, для этого смешать в кастрюле сахар, молоко, сливочное масло и кокосовую стружку. Прогреть, помешивая, на тихом огне в течение 10 минут, масса должна уплотниться. Охладить. Остывший корж разрезать острым ножом по горизонтали на две половины, пропитать разведенным водой ликером. Выложить начинку на корж, накрыть вторым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5108,'Сварить глазурь: молоко, сахар и какао варить несколько минут до загустения. Добавить сливочное масло, перемешать до однородного состояния и вылить на торт. Шоколадный торт с кокосовой начинкой оставить в холодильнике на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5109,'Рыбу почистить, выпотрошить, промыть проточной водой и обсушить полотенцем. Тушки обвалять в муке с солью. Жарить на сливочном масле до образования румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5109,'Переложить в другую сковороду без масла и залить сметаной. Тушить караси в сметане в аэрогриле при высокой температуре в течение 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5110,'Смешать гранатовый сок, сахар и воду. Можно добавить зерна свежего граната. Разлить гранатовый спритцер в бокалы со льдом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5111,'Разогреть духовку, либо гриль до средней температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5111,'Добавить в фарш перец, чеснок, соль и хорошо вымесить, сформовать четыре округлые котлеты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5111,'Выложить котлеты на смазанный маслом противень и отправить в духовку, через 2 минуты перевернуть котлеты на другую сторону и выпекать еще 3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5111,'Положить на каждую по пластинке сыра  и запекать еще 2 минуты, пока не начнет плавиться сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5111,'Разрезать вдоль 4 булочки для гамбургеров. Сделать чизбургер домашний со свининой, авокадо и кинзой: одну половинку каждой булочки смазать майонезом, положить последовательно котлету с сыром, кружок помидора, кусочек авокадо, посыпать рубленой зеленью кинзы и накрыть другой половинкой булочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5112,'Зеленый салат порвать руками, порезать красную малосольную или копченую рыбу кусочками, авокадо и клубнику – кубиками. Ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5112,'Для заправки смешать растительное масло, мед, готовую горчицу, бальзамический уксус. Залить салат с красной рыбой, клубникой и авокадо заправкой и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5113,'Для приготовления коржей взять муку, сахарный песок и яичные белки, очищенные грецкие орехи или миндаль. Белки взбить в пену, добавить сахар порциями, взбивать до получения плотной однородной массы. Орехи размолоть в муку и вмешать в тесто. Можно добавить ваниль или корицу. Тесто раскатать и вырезать шесть круглых коржей, выпечь на застеленном пергаментом противне, в духовке, в течение 20 минут при 140 – 150 градусах, поочередно. Остудить до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5120,'Каждый кусочек курицы обмакнуть в яичную смесь, затем в сухари со специями, выложить на разогретую с растительным маслом сковороду. Обжарить с двух сторон до образования румяной корочки. Обсушить куриные отбивные в панировке на бумажном полотенце, лишний жир должен впитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5113,'Обычное молоко смешать с кокосовым, с помощью миксера или венчиком. Отделить треть массы, всыпать поочередно сахарный песок, желтки и ванилин, вымесить до однородного состояния. Остальное молоко вскипятить, добавить полученную смесь, помешивая. Вновь довести до кипения, остудить. В остывший крем добавить мягкое сливочное масло, взбитое со сгущенкой, также можно добавить вишневую водку или ликер. Для глазури понадобится белый и черный шоколад, жирные сливки. Растопить на водяной бане черный шоколад со сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5113,'Собрать торт: промазать коржи кремом, сверху намазать джем. Растопить белый шоколад на водяной бане, полить торт сверху и с боков. Охладить. «Черную» глазурь выложить в кондитерский мешок, нарисовать на поверхности торта узор в виде спирали, острием ножа сделать из центра к краям восемь «лучей» и от краев к центру – столько же.  Бока торта «Эстерхази» посыпать миндальными хлопьями и поставить его на 12 часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5114,'С лаймов снять цедру, порубить зелень петрушки, нарезать поперек тонкими пластинками чеснок и перец чили. Семечки можно не вынимать, это добавит остроту. Натереть очищенный корень имбиря. Все перечисленные ингредиенты перетереть в ступке в пастообразное состояние.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5114,'Добавить сок лаймов, оливковое масло, соль и молотый перец – по вкусу. Свиную корейку разрезать на четыре отбивных на косточках. Натереть мясо полученным маринадом, положить в посуду и оставить на 40 – 45 минут. Посуду закрыть пищевой пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5114,'Разогреть растительное масло в толстостенной сковороде. Отбивные очистить от кусочков маринада и обжарить по две минуты с каждой стороны до образования золотистой корочки. Сложить обжаренное мясо в форму для запекания, полить свиную корейку остатками маринада и печь в духовке в течение 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5115,'Крупу промыть, отцедить воду. Обжарить в кастрюле на растительном масле мелкорубленый чеснок. Всыпать рис, перемешать, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5115,'Залить водой на два пальца выше уровня риса, варить под крышкой на сильном огне. При начале кипения огонь убавить и варить рассыпчатый рис еще 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5116,'Перемешать манную крупу, сахар, сырые куриные яйца, творог и сметану. Добавить в массу соду, погашенную уксусом или лимонным соком, можно всыпать распаренный изюм или кусочки сухофруктов. Вылить массу в форму для выпечки и печь творожную запеканку с изюмом в духовке до образования румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5117,'Для теста смешать яйца, по стакану сахарного песка и сметаны, сгущенку, разрыхлитель и два стакана муки. Готовое тесто разделить на две части, в одну добавить какао-порошок. Испечь два коржа, белый – в круглой форме, темный – на противне.  Для приготовления крема смешать сметану с сахаром, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5117,'Для глазури смешать какао и сахар, добавить мягкое сливочное масло, воду или молоко, довести до кипения и остудить. Темный корж нарезать на произвольные кусочки, треугольники, обмакивать их в крем и выкладывать на белый корж также произвольно, полить домашний торт «Графские развалины» глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5118,'Взбить яйца, добавить молоко и сахар, снова взбить. Нарезать на куски толщиной 2 – 3 см французский багет. Каждый кусочек обмакивать в яичную смесь, дать немного пропитаться с двух сторон, выложить на противень и посыпать молотой корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5118,'Нагреть сковороду со сливочным маслом, прогреть до потемнения и обжарить тосты с обеих сторон по три минуты до образования золотистой корочки. Готовый хлеб посыпать сахарной пудрой и подать французский тост с молоком в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5119,'Перемешать с помощью блендера свежую клубнику, очищенный банан, вишневый сироп и йогурт без цветовых и вкусовых добавок, всыпать молотую корицу. Разлить фруктово-йогуртовый коктейль в бокалы и остудить в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5120,'Куриные грудки нарезать длинными брусками толщиной в палец, немного отбить. Смешать панировочные сухари, сушеный базилик, соль и молотый перец. Взбить яйцо с небольшим количеством кипяченой воды или молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5135,'Нарезать курицу на куски, сложить в кастрюлю и, помешивая, подрумянить на оливковом масле (1 ч.л.) 5 минут, добавить к мясу яблочно-овощное пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5135,'Курицу в морковно-яблочном соусе тушить, постоянно помешивая еще 2-3 минуты, подать к столу горячей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5121,'Сырые яйца взбить с сахарным песком и солью в пену, долить стакан молока, снова взбить. Постепенно всыпать просеянную муку, комочки разбивать миксером или венчиком. Добавить оставшуюся муку и молоко, какао-порошок. Влить растительное масло или сливочное, растопленное на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5121,'Добавить погашенную уксусом или лимонным соком соду и снова перемешать. Дать массе постоять 5 – 10 минут для набухания муки. Жарить чоко-панкейки без масла на разогретой сковороде, на среднем огне, с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5122,'Взбить миксером мягкое сливочное масло с сахарным песком до однородного состояния, вбить сырые яйца. Смешать крепкий кофе с молоком. Приготовить сухую смесь из какао-порошка, просеянной муки, соды и разрыхлителя. В масляную смесь ввести половину сухих ингредиентов, влить кофе с молоком и остальную сухую смесь. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5122,'Две формы для выпечки среднего размера смазать сливочным маслом, вылить тесто поровну и выпечь два одинаковых коржа при температуре 175 градусов в течение 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5122,'Нарубить горький шоколад и прогреть вместе со сливками или водой на водяной бане, помешивать. Массу снять с огня и добавить нарезанное сливочное масло, перемешать. Крем остудить до комнатной температуры. Готовые коржи промазать остывшим кремом, намазать им также верх и бока шоколадного торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5123,'Мелко нарезать небольшие луковицы, чеснок и очищенный имбирь. Разогреть растительное масло, обжарить смесь в течение двух минут, до прозрачности лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5123,'Смешать соевый соус, сухое белое вино, яблочный уксус, кетчуп, коричневый сахар. Перемешать. Соединить обе смеси, снова перемешать и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5123,'Смешать с водой картофельный крахмал. Влить тонкой струйкой в соус, варить, пока не станет достаточно густым. Массу процедить или оставить кисло-сладкий соус как есть, с кусочками овощей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5124,'Киви очистить и нарезать кусочками, выложить в блендер или в ступку. Добавить два колечка лимона вместе с кожурой, петрушку, листики свежей мяты и мёд. Влить воду и измельчить массу в пюре. Вылить жиросжигающий коктейль в бокал, украсить пластинкой киви и сразу подать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Нарезать из филе баранины отбивные, натереть солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Нарезать мелко лук, чеснок — тонкими продольными пластинками, картофель нарезать кружками средней толщины (2-2,5 см), измельчить зелень тимьяна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Раскалить масло в чугунной сковороде и обжарить 1 минуту чеснок, извлечь шумовкой и выложить на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Обжарить в «чесночном масле» каждую отбивную с двух сторон по 3-4 минуты и переложить их на блюдо, поставить на разогрев духовку (190 градусов).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Подрумянить в оставшейся смеси масла и мясного сока лук, приправить лавровым листом и солью, влить вино, дать соусу закипеть и убрать с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Выложить слоями в глубокую емкость для запекания картофель, полить соусом и добавить чеснок, тимьян с маслинами, мясо, картофель и залить бульоном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5125,'Отправить все в прогретую духовку тушиться, баранина в белом сухом вине с маслинами и картофелем будет готова через полтора часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5126,'Сырые яйца взбить со стаканом сахара, добавить по полстакана майонеза и кефира, муку, пищевую соду и ванилин из пакетика. Вылить массу в смазанную сливочным маслом форму и печь в течение получаса в духовке на среднем огне. При подаче кекс «Гости на пороге» полить помадкой или глазурью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5127,'Взбить в пену яйца с сахаром. Отдельно смешать творог и мягкое сливочное масло. Продолжая взбивать, добавить в яичную массу творожную, перемешать до однородного состояния. Всыпать ванилин и разрыхлитель, просеянную муку, вымесить тесто. Очистить киви и банан, порезать кубиками, добавить в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5127,'Небольшие формочки для выпечки смазать растительным маслом или выстлать пергаментом. Выложить тесто и печь при температуре 190 градусов 30 – 35 минут. Готовность творожных кексов с киви и бананом проверить зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5136,'Молодой картофель тщательно промыть, если клубни «старые» — очистить. Залить водой, дать закипеть и варить 7 – 8 минут. Откинуть на дуршлаг, обсушить бумажным полотенцем, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5128,'Взбить сырые яйца, добавить майонез и сметану в равных пропорциях, просеянную пшеничную муку, разрыхлитель, немного соли по вкусу, поперчить. Можно всыпать любые специи для овощей. Массу взбить, всыпать тертый сыр «Чеддер», мелко порезанный зеленый лук и укроп, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5128,'Тесто выложить в смазанную форму для выпечки средней величины, печь в течение 30 – 40 минут при температуре 180 градусов. Готовность сырного пирога проверить с помощью зубочистки, она должна остаться сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5129,'Помидоры вымыть, пропустить через мясорубку. Сладкий болгарский перец вымыть, вынуть семена и нарезать каждый плод вдоль на несколько частей. Помидорную массу смешать с солью, сахаром, прогреть до закипания, положить перец и влить растительное масло. Вновь довести до кипения, варить полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5129,'При готовности снять массу с огня и влить уксус. Разложить заготовку в стерильные, пропаренные банки, закатать. Перевернуть банки, остудить домашнее «Лечо», укутав одеялом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5130,'Измельчить в блендере сахарное печенье, грецкие орехи и какао-порошок. В готовую крошку влить растопленное сливочное масло и перемешать. Переложить в разъемную форму и утрамбовать дно, сделать бортики. Форму с коржом поставить в духовку, печь в течение 10 минут при температуре 160 градусов. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5130,'Для приготовления начинки смешать сливочный сыр с сахарным песком, добавить сырые яйца по одному, ликер и картофельный крахмал, перемешать. Треть получившейся начинки отложить, добавить в нее растопленный на водяной бане темный шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5130,'В остывший корж выложить светлый крем, затем слой темного крема. Печь чизкейк «Бейлиз» с шоколадом в духовке, в течение 1 часа 20 минут, на дно поставить емкость с кипятком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5131,'Сварить яйца вкрутую, очистить. У каждого яйца отрезать верхнюю третью часть, желток осторожно вынуть. Размять желтки с майонезом, выложить массу в белковые «чашечки», накрыть «крышками» из отрезанных частей белка. Часть желтой начинки должна быть видна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5131,'Для украшения сделать «клювы» из моркови, «глаза» — из кусочков маслин. Низ яиц немного срезать, чтобы они устойчиво стояли на блюде. Охладить закуску «Цыплята в яйце» в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5132,'Картофель вымыть, очистить и отварить до полуготовности. Воду слить, растереть массу деревянным пестиком. Добавить растопленное сливочное масло, сырое яйцо, посолить и поперчить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5132,'Из теплого пюре сформовать небольшие шарики, обвалять их в муке. Большое количество растительного масла разогреть до кипения на большой сковороде, жарить картофельные шарики во фритюре до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5133,'Нарезать соломкой сырую куриную грудку, обжарить. Отдельно обжарить шампиньоны и репчатый лук, смешать с мясом, долить сливки и довести до кипения. Блюдо переложить в кокотницы, посыпать тертым полутвердым сыром и печь в течение 10 – 15 минут при температуре 180 градусов. Подать жульен с курицей и грибами горячим, в качестве закуски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5134,'Свежий ананас очистить, вырезать сердцевину и нарезать мякоть ломтиками. Вымыть сладкий болгарский перец, удалить семена. Очистить репчатый лук, его и перец нарезать также ломтиками. Очистить и мелко нарубить чеснок. Филе говядины промыть, обсушить и нарезать средними кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5134,'Смешать грибной и обычный соевый соус, всыпать сахарный песок, перемешать до растворения сахара. Добавить половину нормы растительного масла, приправить молотым черным перцем. Полученной смесью залить мясо, перемешать и оставить для маринования на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5134,'Влить оставшееся растительное масло в сковороду, прогреть, выложить ананасы, нарезанные овощи и маринованную говядину, перемешать, прогревать 2 – 3 минуты, до готовности. Говядину «Лук лак» с овощами подать в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5135,'Очистить и порезать на дольки яблоки, измельчить морковь, пастернак, розмарин, нашинковать лук, переложить все в кастрюлю и пассировать на оливковом масле 6-7 минут, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5135,'Добавить к смеси бульон и воду, нагреть до кипения и проварить, помешивая, 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5135,'Переложить все в блендер, добавить уксус и приготовить пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Переложить его в форму для запекания, сверху – ветчина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5136,'Застелить фольгой форму для выпечки, влить 2 столовые ложки оливкового или растопленного сливочного масла. Выложить картофель в один слой, полить клубни маслом и печь в течение получаса при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5136,'Приготовить смесь пряностей: смешать свежий или сухой базилик, розмарин, орегано, тимьян, любую другую зелень, влить по столовой ложке уксуса и оливкового масла, перемешать. Добавить лавровый лист и зубчики чеснока целиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5136,'Готовый картофель на гарнир вынуть из духовки, полить полученной смесью и допечь еще в течение нескольких минут, до образования золотистой корочки. Чеснок и лавровый лист удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5137,'Бананы очистить и нарезать каждый на 2 – 4 части. Растопить любой шоколад на водяной бане или в микроволновой печи в течение нескольких минут. Измельчить любые орехи в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5137,'Кусочки бананов насадить на деревянные палочки и обмакнуть в шоколад. Затем обвалять в рубленых орехах, выложить на пергамент и заморозить бананы в шоколаде в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5138,'Удалить у грибов ножки и мякоть из шляпок. То и другое мелко нарезать, смешать с нарезанным репчатым луком, обжарить до мягкости, посолить. Добавить сметану и прогреть одну минуту. Всыпать рубленую зелень укропа и снять с огня. Добавить тертый твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5138,'Смесью начинить грибные шляпки, посыпать «чашечки» сверху тертым сыром, поставить фаршированные шампиньоны на противень с небольшим количеством воды в духовку на 25 – 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5139,'Для теста смешать молоко с сахаром и сухими дрожжами, добавить соль, растопленное сливочное или растительное масло. Всыпать просеянную муку, вымесить. Разделить тесто на кусочки размером с теннисный мяч, раскатать в лепешки. Положить по «Венской» или аналогичной очищенной сосиске. Свернуть лепешку, как вареник, защипать края и разрезать поперек на восемь частей, не дорезая до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5139,'Сформовать «гусеницу»: нижний «пенек» положить налево с разворотом, следующий — направо, далее – в шахматном порядке. Противень выстелить бумагой для выпечки. Положить булочки на 15 минут в теплое место на расстойку. Верх смазать смесью яйца и молока, печь при температуре 220 градусов в течение 20 минут. Поверхность булочек «Гусенички» с сыром и сосисками должна зарумяниться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5140,'Растереть сырое яйцо с сахарным песком, добавить сметану, погашенную уксусом соду, уксус, просеянную муку, полпачки какао-порошка. Массу перемешать и выложить в форму, смазанную маслом и обсыпанную панировочными сухарями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5140,'Печь на небольшом огне в течение 35 – 40 минут. Готовый корж разрезать на две-три части по горизонтали, острым ножом.  Для приготовления крема «Трюфельный» смешать мягкое сливочное масло со сгущенным молоком. Массу взбить, добавить оставшееся какао, перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5140,'Промазать коржи кремом. Верх торта покрыть глазурью из какао, сметаны, сахара и мягкого сливочного масла. Все перечисленные ингредиенты растереть до однородного состояния и залить смесью трюфельный сметанник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5141,'Яблоки очистить от кожицы и семенной камеры, нарезать тонкими ломтиками, сбрызнуть лимонным соком, чтобы не почернели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5141,'Для приготовления теста взбить сырые яйца, понемногу, порциями, всыпать сахарный песок, продолжая взбивать. Сахар должен полностью раствориться. Ввести просеянную муку частями, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5141,'Чашу мультиварки смазать растопленным сливочным маслом или маргарином. Вылить половину теста, выложить яблоки, присыпать их сахаром и молотой корицей. Залить начинку второй половиной теста. Печь шарлотку с яблоками в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5142,'Взбить в блендере очищенный киви, банан и молоко. Можно добавить столовую ложку мёда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5143,'Свежую клубнику вымыть, взбить в блендере с небольшим количеством воды. Отдельно вскипятить воду с сахаром, через две минуты после начала кипения влить клубничное пюре, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5143,'Развести картофельный крахмал в воде и влить в клубничный сироп, прогреть, помешивая. Охладить под пленкой, постелить её прямо на поверхность приготовленной массы. Смесь разлить в формочки для мороженого эскимо и поставить в холодильник на 12 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10619,'В конце приготовления вынуть лук, влить сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5144,'Куриное филе отварить и мелко нарезать, соль, перец – по вкусу. Очистить и нарезать половинками тонкие пластинки одного киви. Отварить и натереть белки трех яиц, потереть яблоко и твердый сыр. Готовую морковь по-корейски мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5144,'Выложить слои в прозрачную салатницу: курица, киви, яичные белки, яблоко, сыр, морковь. Сверху – мелко раскрошенные желтки. Все слои салата из курицы с морковью по-корейски промазать тонким слоем майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5145,'Поставить варить рис, нарезать филе индейки на куски, измельчить лук, обжарить на разогретом масле 1-2 минуты лук, положить филе, поперчить, посолить, обжарить помешивая 7-8 минут, мясо переложить на тарелку и накрыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5145,'Выложить готовый рис на сковороду с мясным соком, перемешать и обжарить 10 минут, положить мед и, если надо,  добавить 2 ст.л. воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5145,'Промыть и обсушить шпинат, измельчить и добавить к рису за 2 минуты до окончания жарки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5145,'Филе индейки с медовым рисом и шпинатом подается горячим и украшается веточками свежего базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5146,'Приготовить фарш: прокрутить через мясорубку куриное филе, репчатый лук, зубчики чеснока. Добавить хлеб, сырое яйцо, соль, молотый перец. Для начинки натереть любой твердый сыр, вареные яйца, мелко порубить зелень петрушки и укропа, добавить мягкое сливочное масло и любые приправы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5146,'Сформовать из фарша лепешки, сделать в них углубления и положить по ложке начинки, сформовать котлеты. Все это легче делать мокрыми руками. Жарить куриные котлеты с сырной начинкой на разогретом растительном масле, до румяной корочки, с двух сторон, по несколько минут, на слабом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5147,'Куриное филе отварить до готовности в подсоленной воде. Мясо охладить и мелко нарезать. Нарезать консервированные ананасы кубиками, жидкость слить. Порезать также кубиками кочанный салат Айсберг или порвать руками. Все ингредиенты смешать и заправить салат с ананасом и куриным филе майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5148,'Отварить в воде куриное филе, вынуть. В готовый бульон всыпать мелко нарезанный картофель. Нарезать и обжарить репчатый лук, добавить шампиньоны, прожарить, посолить, снять с огня, остудить. Взбить массу в блендере до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5148,'Картофель с небольшим количеством бульона растолочь в пюре, добавить грибную массу, перемешать, влить сливки, прогреть на тихом огне. Добавить оставшийся бульон, если крем-суп из шампиньонов получился слишком густым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5149,'Помидоры бланшировать в кипятке в течение 30 секунд, очистить от кожицы и нарезать крупными кусочками. В сковороде или сотейнике обжарить на растительном масле рубленый репчатый лук. Добавить красный и желтый болгарский перец, соль, перец – по вкусу. Прогревать, помешивая, 4 – 5 минут. Вынуть перец и лук из сковороды и отложить. Обжарить ломтики баклажана, кожицу не чистить, перед обжариванием плоды посолить и поперчить, довести до светло-коричневого цвета и переложить к перцу и луку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5149,'Обжарить на том же масле цуккини пластинками, затем добавить все остальные овощи. Потушить с томатной пастой, помешивая, в течение нескольких минут. Добавить помидоры, сахарный песок, лавровый лист и тимьян, базилик, снова перемешать и прогревать под крышкой еще 15 минут. При готовности удалить из рагу лавровый лист, базилик и тимьян. Добавить рубленый чеснок и петрушку. Перемешать и подать классический рататуй в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5150,'Вскипятить воду, добавить сливочное масло и довести до кипения. Всыпать пшеничную муку и соль, замесить тесто. Дать ему остыть, ввести сырые яйца по одному. Тесто переложить в кондитерский шприц и отсадить полосками прямо на противень. Печь при температуре 180 градусов в течение 20 – 25 минут, духовку не открывать, иначе выпечка опадет. Приготовить крем: смешать любую сметану с сахаром по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5150,'Часть сметаны можно заменить сыром маскарпоне. Форму для выпечки выстелить пищевой пленкой, на дно выложить любые фрукты, нарезанные кусочками. Затем слой заварных «пальчиков» и крема, снова фрукты, заварные и крем. Оставить торт для пропитывания на пять часов при комнатной температуре и на 2–3 часа в холодильник. При подаче форму с тортом «Дамские пальчики» перевернуть на тарелку, пленку удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9628,'Слепить творожные комочки, каждый обмакнуть в какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5151,'В просеянную пшеничную муку добавить яйца, влить молоко, перемешать, добавить соль, сахар, растопленное сливочное масло, взбивать до исчезновения комочков. Дать постоять тесту 20 минут, чтобы набухла клейковина. Выпечь блинчики с двух сторон на небольшом количестве масла, лучше взять сковороду с антипригарным покрытием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5151,'Для начинки нарезать брусками малосольный или соленый огурец, завернуть его в тонко нарезанную колбасу, а затем в ломтик сыра. Выложить на тонкие блинчики, завернуть рулетом и разрезать на две-три части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5152,'Смешать нежирный творог, сырые яйца, сметану или йогурт без цветовых добавок, муку, сахар, тертую лимонную цедру или промытый изюм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5152,'Силиконовые формочки для выпечки смазать сливочным маслом, выложить творожную массу на две трети объема, печь ленивые сырники в духовке до готовности в течение получаса при температуре 180 – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5153,'Приготовить сироп из воды с сахарным песком, варить 15 – 20 минут, помешивать. Охладить, добавить концентрированный лимонный сок. В воду положить маргарин, довести до кипения, посолить по вкусу. Всыпать муку, хорошо перемешать, снять с огня. Втереть все яйца поочередно, вымесить до гладкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5153,'Переложить тесто в кондитерский шприц и отсадить «колбаски» по пять сантиметров длиной. На сковороде нагреть растительное масло, обжарить тулумбы до румяного цвета, встряхивая сковороду. Готовую выпечку перемешать с остывшим сахарным сиропом, выложить тулумбу на блюдо горкой или стопочкой и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5154,'Взбить сырое яйцо, добавить соль, молоко, коньяк, сок лимона. В мучной «горке» сделать углубление, вылить в него смесь жидких ингредиентов. Замесить мягкое тесто, скатать в шар, накрыть пищевой пленкой и оставить на столе на полчаса. Размягченное сливочное масло смешать с половиной стакана муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5154,'Раскатать тесто в виде большого прямоугольника, по нему распределить масляную лепешку, сделать конверт, загнуть все четыре угла к центру. Раскатать в прямоугольник в одном направлении до толщины 1 – 1,5 см, снова сделать конверт, положить в холодильник на 10 минут. Тесто достать, снова раскатать, свернуть, положить в холод на 20 минут, операцию повторить и охлаждать массу уже полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5154,'Из теста сформовать колбаску, поделить ее на 20 – 22 равные части, поставить в холодильник. Каждую часть тонко раскатать на коврике из силикона, наколоть в нескольких местах вилкой, печь при температуре 200 г до золотистого цвета. Выпечь все коржи, последний выпекать дольше, до светло-коричневого цвета, он будет нужен для обсыпки торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5154,'Приготовить крем: нагреть молоко почти до кипения. Взбить сырые яйца и сахарный песок, добавить ванилин из пакетика и просеянную муку. Влить стакан горячего молока  тонкой струйкой, хорошо перемешать до однородного состояния. Полученную массу влить в остальное молоко, варить, помешивая, до загустения, в течение 5 – 7 минут. Не кипятить. Готовый крем охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5154,'Взбить мягкое сливочное масло и порциями добавить в остывший крем. Собрать торт, промазывая коржи полученным кремом. Корж, оставленный для обсыпки, измельчить в блендере, обсыпать смазанный кремом торт со всех сторон. Оставить торт «Наполеон» для пропитывания при комнатной температуре на четыре часа, затем убрать в холодильник на 12 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5155,'Очистить и отварить клубни картофеля, растолочь в пюре. Отдельно натереть сыр, добавить рубленый чеснок, картофельную массу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5155,'С помощью кондитерского мешка отсадить на противень «розочки». Печь розочки из картофеля при температуре 180 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5156,'Взять мощный блендер, ручной в этом случае не подойдет, так как, даже если добавить растительное масло нежной консистенции пасты добиться не получится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5156,'Засыпать жареные орехи в блендер и перемолоть, в процессе измельчения масса будет меняться от крупной крошки до больших комков и только в конце она будет в виде гладкой массы, измельчать арахис надо на средей-высокой скорости блендера 5-6 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5156,'Когда масса превратиться в гладкую пасту добавить пару столовых ложек целого арахиса и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5156,'Домашняя арахисовая паста хрустящая – прекрасное дополнение к утренним тостам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5157,'Вскипятить воду, всыпать тертую морковь и картофель. Из любого мясного фарша слепить фрикадельки, положить в почти готовый суп, соль, перец, лавровый лист – по вкусу. За две минуты до готовности положить в суп с фрикадельками рубленый зеленый лук, петрушку, укроп, кинзу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5158,'Армянский готовый лаваш смазать сметаной. В сырой мясной фарш добавить рубленый лук, морковь, помидоры, соль и специи. Массу выложить поверх сметаны, затем слой зелени, накрошенные яйца, сваренные вкрутую, тертый сыр, сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5158,'Скрутить лаваш с начинкой в рулет, печь 40 минут. Смазать взбитым яйцом или растопленным сливочным маслом за 15 минут до готовности блюда. Подавать мясной рулет на стол в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5159,'Порезать кубиками отваренное куриное филе, свежие огурцы и репчатый лук. Из консервированных шампиньонов отцедить воду, порезать, если грибы крупные. Натереть твердый сыр. Сварить вкрутую яйца, белки порезать соломкой, желтки растереть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5159,'Выложить слоями  в салатницу: белки, курица, лук, огурцы, грибы, сыр. Слои салата из огурцов и куриного филе промазать майонезом, сверху – также майонез, посыпать тертыми желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5160,'Выложить слоями: рубленый зеленый лук или укроп, маринованные шампиньоны или опята, лук репчатый, тертый отварной картофель, майонез. Следующий слой: мелко порезанная отварная курица или свинина, мелко измельченные маринованные огурцы, репчатый лук, слой картофеля, майонез. Далее: готовая морковь по-корейски, тертый сыр, майонез, грибы, зеленый лук или укроп. Дать салату «Лукошко» с грибами и мясом постоять в холодильнике несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5161,'Взбить с помощью блендера творог, сметану, манку, сырые яйца, соль и сахар – по вкусу. Вылить смесь в смазанную маслом фигурную форму и печь творожник до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5162,'Смешать кефир, сырые яйца, растительное масло, соду и соль. Муки подмесить столько, чтобы тесто не липло к рукам. Раскатать, выложить начинку и выпечь быструю пиццу в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5163,'Белки отделить от желтков и взбить с сахарным песком. Добавить желтки, просеянную пшеничную муку, взбить до однородного состояния. Противень застелить пергаментом, вылить тесто, разровнять и печь при температуре 180 градусов в течение 15 – 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5163,'Для начинки вымыть лимон, обсушить бумажным полотенцем, натереть и смешать с половиной стакана сахара. Готовый корж вынуть из духовки, смазать лимонной массой, и свернуть в рулет. При подаче лимонный рулет посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5164,'Для приготовления соуса нашинковать любую зелень, порубить чеснок, влить сметану, соль и специи по вкусу. Перемешать. Противень выстлать бумагой для выпекания. Выложить ломтики сырого картофеля, половинки шампиньонов, слой соуса из сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5164,'Затем куриное филе кусочками, ломтики помидоров, тертый твердый сыр. Печь в течение 35–40 минут при температуре 200 градусов. Дать картофельной запеканке с курицей постоять 15–20 минут для пропитывания и подать к столу в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5165,'Бананы очистить и размять вилкой. Добавить сахарный песок, бадьян, ваниль, лимонную кислоту. Довести смесь до кипения, огонь выключить. Через 3–4 часа варенье вновь довести до кипения, через 10 минут выключить. Переложить банановое варенье в чистые банки и хранить в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5166,'Смешать мелко нарезанные шнитт-лук и петрушку с майонезом и пахтой, приправить молотым сушеным луком, чесночной солью, молотым черным перцем, готовый соус накрыть пленкой и убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5166,'Охлажденный соус «Ранч» по-американски прекрасно сочетается с салатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5167,'Растереть сырые куриные яйца с сахарным песком, добавить ванилин из пакетика, разрыхлитель, соль и лимонный сок, массу перемешать до однородного состояния. Добавить протертый творог, еще раз перемешать. Всыпать манную крупу и мак.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5167,'Массу выложить в силиконовую формочку, печь в микроволновой печи в течение трех минут на максимальной мощности. Дать творожному пудингу постоять две минуты при закрытой дверке, затем печь еще 1,5 минуты на той же мощности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Застелить форму для выпекания пергаментом и выложить печенье, убрать на час в холодное место, через 30-40 минут включить духовку для разогрева.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5168,'В кастрюле с толстыми стенками растопить сливочное масло с жирными сливками и всыпать сахарный песок. Варить, помешивая, до полного растворения сахара. Поломать на мелкие кусочки шоколадную плитку, добавить в масляную смесь и перемешать до растворения шоколада. Всыпать молотый кардамон, вымесить до однородного, шелковистого, состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5168,'Снять массу с огня, добавить орехи кешью, перемешать. Вылить в смазанную квадратную или прямоугольную форму, охладить и оставить на ночь в холодильнике или в морозильной камере. Застывший ирис-фадж с кешью вынуть из формы, нарезать небольшими квадратами и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5169,'Взбить с помощью блендера протертый творог, мягкое сливочное масло, соль и соду. Масса должна стать однородной. Варить на водяной бане, помешивать, прогревать до тех пор, пока смесь не начнет плавиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5169,'Форму для сыра смазать растопленным сливочным маслом, вылить горячую сырную смесь. Убрать плавленый сыр из творога в прохладное место на 8–10 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5170,'Замороженные крабовые палочки натереть на крупной терке, так же поступить с плавленым сыром Дружба. В массу добавить давленый или мелкорубленый чеснок по вкусу, всыпать нарезанную зелень укропа, заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5170,'Готовую массу намазать на тонкий лаваш слоем в полсантиметра. Нарезать кубиками свежие помидоры, выложить сверху, закатать в рулет. Острым ножом нарезать на кусочки в 1,5–2 см, выложить на блюдо и дать крабовому рулету из лаваша немного постоять для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5171,'Плоды порезать кружочками в полсантиметра, кожицу не снимать. Посолить, чтобы вышла горечь, затем жарить на растительном масле с двух сторон. Нарезать кружочками помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5171,'Для приготовления соуса мешать майонез, рубленый чеснок, зелень петрушки, укропа, кинзы. Выложить на блюдо слоями: обжаренные баклажаны, помидоры, промазать соусом с зеленью. Дать закуске из баклажанов постоять для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5172,'Смешать протертый творог, мягкое сливочное масло, сахарный песок, манную крупу, молоко, сырые яйца. Оставить на 40 минут, манная крупа должна набухнуть. Печь творожную запеканку в духовке при температуре 180–200 градусов до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5173,'Нарезать репчатый лук полукольцами, куриное филе, картофель и шампиньоны – тонкими полосками. Разогреть растительное масло обжарить ингредиенты в течение 5 – 10 минут до готовности. Добавить жирные сливки и куриный бульон, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5173,'Массу переложить в смазанную маслом форму для запекания, посыпать тертым твердым сыром. Печь жульен с картофелем, курицей и грибами около получаса в разогретой духовке при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5174,'Смешать воду, растительное масло и соль, смесь довести до кипения. Всыпать просеянную пшеничную муку, массу непрерывно помешивать. Смесь остудить, вбить по одному яйца, всыпать тертый твердый сыр. Тесто вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5174,'На лист пергамента отсадить тесто полосками с помощью кондитерского шприца. Печь сырные профитроли при температуре 190–200 градусов в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5175,'Тонко нарезать репчатый лук, сладкий болгарский перец, помидоры. Приготовить куриный фарш, посолить, поперчить, немного разбавить творожной сывороткой.  Баклажан разрезать вдоль на тонкие пластинки, не дорезая до конца, выложить на смазанное маслом блюдо в виде веера. Посыпать репчатым луком, намазать куриный фарш. Поставить массу на пять минут в микроволновую печь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5175,'Блюдо вынуть, положить помидор, болгарский перец, накрыть крышкой, печь четыре минуты. Затем посыпать баклажаны с фаршем «Павлиний хвост» тертым сыром, снова закрыть и печь 1,5 минуты. При готовности дать блюду постоять еще пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Размолоть миндаль в порошок и смешать с корицей, разрыхлителем, кардамоном, солью и просеянной мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Растереть масло с сахаром до состояния крема, добавить яйцо и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Смешать мучную смесь с масляным кремом до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Тесто раскатать в прямоугольный пласт толщиной в один сантиметр, накрыть пленкой и убрать в холодное место на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5176,'Достать тесто и раскатать еще раз, но в пласт в 2 раза тоньше, вырезать формочками фигурное печенье.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5177,'Приготовить заправку: налить в сотейник или сковороду полстакана растительного масла, уксус, поставить на огонь, помешивая, добавить красный горький и черный молотый перцы, острую приправу для корейской моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5177,'Соль – по вкусу. При закипании положить томатную пасту и прогреть до готовности. Залить курицу «Хе» с болгарским перцем горячей заправкой, перемешать, оставить для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5178,'Отделить белки от желтков, белки взбить с сахаром до густоты и увеличения объема. В массу добавить молочный шоколад, нарубленный кусочками, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5178,'Выложить шоколадную смесь в формочки или чашки, провести ножом по стенкам и поставить в микроволновую печь на 30 секунд. Охладить. Перевернуть торт-суфле на блюдо и подать к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5179,'Кефир перемешать с пищевой содой и оставить на пять минут. Добавить муку и соль, перемешать. Форму для выпечки смазать маслом, посыпать мукой и вылить половину приготовленного теста. Затем слой сырого фарша с кубиками репчатого лука, солью и перцем. Вылить вторую половину теста. Печь пирог с мясом в духовке в течение 40 минут при температуре 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5180,'Куриное филе залить водой, посолить по вкусу, варить 20 минут с момента закипания. Очистить и мелко нарезать репчатый лук, шампиньоны нарезать пластинками, картофель – кубиками. Готовое куриное филе вынуть из бульона, также порезать кубиками. Обжарить накрошенный репчатый лук на разогретом сливочном масле в течение пяти минут, добавить грибы, перемешать и прогревать до выпаривания жидкости, в конце приготовления посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5180,'Куриный бульон довести до кипения, положить картофельные кубики, варить 10 – 15 минут. Добавить грибную обжарку, через пять минут – куриное филе, плавленый сырок Дружба, нарезанный кубиками. Перемешать, сыр должен раствориться. Суп можно еще поперчить и посолить. Грибной суп с сыром и куриным филе подать горячим, украсить зеленью укропа, обжаренными грибами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5181,'Белые грибы варить в воде без специй в течение 30 – 35 минут. Добавить картофель, нарезанный кусочками, спассерованые на растительном масле репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5181,'Влить жирные сливки, посыпать рубленой зеленью укропа и положить зубчик рубленого чеснока. Варить грибной суп до полной готовности на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5182,'Свинину нарезать небольшими кусочками, посолить и поперчить, обжарить на сильном огне до  появления румяной корочки. Нарезать клубни очищенного картофеля кубиками со стороной в один сантиметр. Натереть на мелкой терке морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5182,'Выложить картофель в горшочек на две трети объема, затем мясо, морковь и снова картофель. Положить специи, лавровый лист, томатную пасту, соль – по вкусу. Залить водой почти доверху, закрыть жаркое из свинины в горшочке крышкой и печь в духовке в течение 30 – 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5183,'Натереть молодой картофель, отдельно взбить сырые куриные яйца с молоком. Прогреть сковороду, смазать растительным маслом, выложить картофель толстым слоем, залить яичной массой, добавить специи. Свержу уложить плавленый сыр, нарезанный пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5183,'Блюдо прогревать под крышкой на тихом огне в течение 7 минут. Запеканку из молодого картофеля разрезать на порции, при подаче посыпать зелёным консервированным горошком, свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5184,'Куриный окорочок или филе отварить до готовности и нарезать кубиками или соломкой. Сварить яйца вкрутую, натереть. Очистить и нарезать кубиками апельсин. Натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5184,'Выложить салат слоями в такой последовательности: курица, майонез, морковь по-корейски, майонез, апельсин, яйца, майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5185,'Свежие дрожжи развести теплой водой, добавить сахарный песок, перемешать. Отварить в «мундире» картофель, очистить и размять. Замесить эластичное тесто из пшеничной просеянной муки, размятого картофеля, разведенных дрожжей. Соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5185,'Тесто не должно липнуть к рукам, в противном случае нужно добавить еще немного муки и снова вымесить. К тесту можно также добавить зелень розмарина и майорана. Оставить массу на час в теплом месте, миску накрыть тканью или пищевой пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Вылить темное пиво в кастрюлю, добавить вустерский соус и дижонскую горчицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5185,'Поднявшееся тесто разделить на две части, раскатать по отдельности. Нарезать сыр мелкими кубиками. Часть теста выложить на смазанный противень или в форму для выпечки, выложить сырную начинку, накрыть второй половиной теста, защипать края «косичкой».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5185,'Сделать пальцами на поверхности пирога углубления и полить оливковым маслом. Посыпать солью крупного помола, сухими пряными травами, печь картофельный пирог с сырной начинкой при температуре 200 градусов в течение 35 – 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5186,'Просеять пшеничную муку, порубить ножом замороженное сливочное масло. Смешать, постепенно добавлять холодную воду, пока тесто не станет эластичным. Скатать массу в шар, завернуть в пищевую пленку и поставить на один час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5186,'Копченый куриный окорочок отделить от костей и кожи, мелко порезать. Часть копченого сыра натереть на мелкой терке, часть также порезать мелкими кусочками. Мелко порубить зелень петрушки и укропа. Взбить венчиком сырые яйца, добавить сметану и молоко. Смешать массу с сыром и куриным мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5186,'Тесто выложить в форму для выпечки, распределить равномерно, сформовать невысокие бортики, наколоть вилкой в нескольких местах. Сверху – начинка, посыпать зеленью и тертым сыром. Печь в духовке в течение 30 – 40 минут при 180 – 200 градусах. Остудить, подать, порезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5187,'Спассеровать на растительном масле рубленый лук и чеснок, добавить фарш, обжарить на среднем огне в течение 7 минут. Влить готовый соус, соль и перец – по вкусу. Добавить молотую паприку, тушить на тихом огне 10 минут. Тонкие спагетти отварить почти до готовности, добавить с мясной соус, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5188,'Смешать кефир с солью, сахаром, содой и сырым яйцом. Массу перемешать. Добавить тертый твердый сыр и пшеничную муку, вымесить. Тесто разделить на несколько колобков, раскатать тонкие лепешки, положить начинку с ветчиной или творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5188,'Для приготовления первой достаточно тонко нарезать ветчину, для второй  – смешать творог с рубленым укропом, давленым зубчиком чеснока, сметаной, солью и перцем. Соединить края и еще немного раскатать скалкой. Жарить лепешки из сыра с начинкой на разогретой сковороде с рафинированным маслом на среднем огне под крышкой, с двух сторон. Подать, нарезав на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5189,'Нашинковать репчатый лук мелко или полукольцами, обжарить на сковороде, на растительном масле. Нарезать куриное филе кусочками любой формы, посолить, поперчить по вкусу, посыпать сухой приправой для курицы, перемешать. Добавить мясо к луку и еще немного обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5189,'Из банки с консервированными грибами слить воду. Грибы нарезать. Добавить к чуть остывшей курице и хорошо перемешать. Взбить сырые яйца, добавить сливки и тертый твердый сыр. Всыпать нашинкованную зелень укропа, лука. Добавить соль и перец по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5189,'Готовое слоеное тесто разморозить и раскатать. Выложить в смазанную растительным маслом форму для выпечки так, чтобы получились бортики в три сантиметра. Всыпать куриную начинку, немного прижать сверху. Залить пирог из слоеного теста яичной массой, прикрыть края тестом. Печь полчаса при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5190,'Из помидоров одинакового размера средней величины удалить сердцевину. Обжарить со специями куриную грудку или мелко нарезать готовую копченую курицу. Начинить мясом помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5190,'Сверху обильно смазать майонезом и посыпать тертым твердым сыром. Печь в духовке в течение 15 минут при температуре 240 – 260 градусов до подрумянивания сыра. При подаче помидоры фаршированные курицей украсить зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5191,'Отварить куриные яйца, очистить и порубить. Нарезать крабовые палочки. Перемешать, добавить рубленый укроп и шнитт-лук или тонкий зелёный лук. Добавить сметану, майонез, в равных количествах. Поперчить по вкусу. Добавить немного воды, должна получиться полужидкая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5191,'Готовую начинку намазать на лист готового лаваша, свернуть плотным рулетом, завернуть в пищевую пленку. Оставить в холодильнике не менее чем на восемь часов или на ночь. Готовые рулеты «Краб-кебаб» нарезать на неширокие кусочки и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Ананасовый десерт в имбирно-ромовом сиропе можно приготовить заранее и оставить на сутки в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5192,'Приготовить тесто из просеянной пшеничной муки, сырого желтка, сахарного песка, соли, растопленного сливочного масла, молока, в котором предварительно растворены дрожжи. Тесто должно быть крутым, не липнуть к рукам. При необходимости можно добавить муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5192,'Приготовить фарш, добавить яйцо, соль и перец, перемешать. Порезать кубиками репчатый лук. Из готового теста раскатать лепешку прямоугольной формы, выложить фарш, лук, очищенный тертый сырой картофель. Посолить по вкусу и посыпать рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5192,'Свернуть лепешку рулетом, нарезать на кусочки по пять сантиметров толщиной. Каждый кусочек приплюснуть и выложить на смазанный маслом противень. Печь при 200 градусах по 10–15 минут с каждой стороны до румяного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5192,'Для приготовления соуса нарезать кубиками баклажаны, кабачок, болгарский сладкий перец, помидоры. Обжарить все ингредиенты на сливочном масле и пропустить через мясорубку. Измельчить чеснок, добавить в массу, соль, черный перец и молотая паприка – по вкусу. Перемешать. Подать к овощной соус к мясным рулетикам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5193,'Сырые куриные яйца взбить в пену с молоком. Посолить и поперчить по вкусу. Пшеничную муку просеять вместе с содой, добавить в массу, еще немного взбить. Порубить зеленый лук, натереть твердый сыр, ингредиенты добавить в омлетную массу. Перемешать. Полученное жидкое тесто перелить в формочки, печь омлет с сыром в духовке в течение 20 минут при температуре 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5194,'Крупные клубни очистить и отварить до полуготовности, примерно в течение 10 минут после закипания. Соль, специи – по вкусу. Нарезать бекон небольшими кусочками, мелко порубить репчатый лук, то и другое обжарить в течение 3 – 4 минут. Натереть твердый сыр на крупной терке. Отваренный картофель остудить и также натереть. Смешать картофельную массу с сырым яйцом, сметаной и третей частью сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5194,'Смазать маслом форму для запекания, выложить половину массы, затем начинку с беконом, луком и оставшимся сыром. Накрыть оставшейся картофельной массой. Печь в духовке при 180 градусах в течение 40 минут. Края запеканки должны приобрести золотистый цвет. Готовый террин из картофеля с беконом нарезать порциями и подать в горячем виде или комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5195,'Слоеное дрожжевое тесто предварительно разморозить, раскатать в лепешку толщиной полсантиметра. Выстелить противень бумагой для выпечки, выложить тесто. Сформовать небольшие бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5195,'Для начинки взбить яйца со сливками, соль и перец – по вкусу. Нарезать сало и натереть твердый сыр. Выложить на корж сначала сало, затем сыр, залить яичной смесью. Бортики пригнуть внутрь, печь лотарингский пирог в духовке до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5196,'На противень выложить булочки для бутербродов, разрезанные пополам. На половину булочки положить тонко нарезанную ветчину, ломтики сыра. На другую половину намазать майонез и соединить обе половинки. Также поступить со всеми остальными бутербродами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5196,'Отдельно смешать дижонскую горчицу, растопленное сливочное масло, луковый порошок, Вустерский или другой острый соевый соус, коричневый сахар и мак. Перемешать до однородности и залить смесью булочки. Закрыть бутерброды с сыром и ветчиной фольгой, печь 10 минут. Фольгу снять, прогревать еще 5–10 минут до расплавления сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Нарезать небольшими ломтиками очищенные ананасы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Очистить корень имбиря и нарезать кружочками толщиной по 2 сантиметра, сложить в кастрюлю, залить водой (5 стаканов на 10 кусочков имбиря), добавить сахар и нагреть, помешивая до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'После полного растворения сахара нагревать еще 3 минуты и снять с плиты, закрыть крышкой и дать постоять 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Достать имбирь из сиропа и положить кусочки ананаса, накрыв кастрюлю крышкой, проварить их до полупрозрачности, периодически помешивая 7-8 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Вынуть ананасы и разложить по креманкам или салатникам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Сироп проварить еще 15 минут, пока не останется два стакана жидкости, добавить треть стакана темного рома и при слабом нагреве проварить еще 1 минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5197,'Залить готовым сиропом ананасы и дать постоять 40-45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'Баклажан нарезать кружками и оставить на полчаса, чтобы отошла горечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5198,'Растопить маргарин, перемешать с сахаром, всыпать просеянную муку с разрыхлителем. Массу хорошо перемешать. Добавить молоко, взбитые яйца, еще раз вымешать. Дать тесту постоять в течение 10–15 минут. Выпечь рассыпчатое печенье в печеньечнице.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5199,'Натереть на мелкой терке сыр и чеснок, нарезать петрушку. Все ингредиенты перемешать, соединить с размягченным сливочным маслом. Нарезать черствый, вчерашний, батон по диагонали, не дорезая до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5199,'Разрезы заполнить сырной начинкой. Начиненный батон завернуть в фольгу, печь в течение 20 минут при 200 градусах. При готовности фольгу удалить и допечь батон с чесноком и сыром еще пять минут, до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5200,'Кочан капусты очистить от грязных листьев и поставить в микроволновую печь на 5 – 10 минут. При готовности листья должны легко отделяться. Приготовить фарш. Отварить рис до полуготовности, обжарить натертый лук, морковь и яблоко. Все продукты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5200,'Для «шубы» натереть сыр, нарезать два помидора, по пучку укропа и петрушки, нарубить чеснок. Массу перемешать, посолить, поперчить и добавить майонез. Сформовать голубцы, уложить на противень, смазанный маслом, накрыть сырной массой. Запечь голубцы с мясным фаршем до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5201,'Слабосоленое филе лосося промыть в проточной воде. Обсушить тушку бумажными полотенцами. Снять кожу ножом целиком. Филе нарезать мелкими кубиками, выложить в миску. Очистить, вымыть и обсушить репчатый лук, авокадо, манго, болгарский сладкий перец и перец  чили очистить от семян. Авокадо разрезать вдоль, развернуть половинки, удалить мякоть ножом, нарезать кубиками, также поступить с плодами манго, остальные ингредиенты также нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5201,'Перемешать овощи, фрукты и рыбу до однородного состояния. Выжать лимонный сок из половины плода. Поперчить блюдо по вкусу, можно добавить сухие травы. Заправить массу соевым соусом. Разложить салат с лососем, авокадо и сладким перцем в небольшие пиалы, утрамбовать и перевернуть на большое блюдо. Можно украсить закуску зеленью сельдерея, укропа, листочками мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5202,'Крупные помидоры разрезать пополам, выложить в блюдо или форму для запекания. Посыпать тертым сыром, посолить, поперчить, выложить рубленую зелень орегано, петрушки, тимьяна. Сбрызнуть закуску оливковым маслом. Печь помидоры с сыром при температуре 180 градусов в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5203,'Свежий батон разрезать вдоль не до конца, развернуть и вынуть мякоть из двух половинок. Размягченное сливочное масло разделить на три части, в каждую добавить мякиш, в первую – кетчуп, во вторую – рубленую зелень. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5203,'Заполнить батон полученной начинкой, в одну из половинок выложить разрезанную вдоль сельдь без костей. Закрыть второй половиной, завернуть в пакет, положить под пресс в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5204,'Белокочанную капусту нашинковать, посолить и помять руками. Порубить зелень петрушки и укропа, добавить в капусту. Взбить яйца до состояния однородности, добавить сметану, майонез, муку, соль и разрыхлитель, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5204,'Смазать форму сливочным маслом, выложить капусту. Залить тестом, посыпать верх кунжутом. Печь капустный пирог полчаса до золотистой корочки при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5205,'Отварить, остудить и натереть картофель и морковь небольшого размера. Отварить яйца вкрутую и также натереть. Мелко нарезать копченую куриную грудку, порубить маленькую луковицу. Майонез заправить давленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5205,'Выложить салат слоями: картофель, яйца, грудка, лук, морковь. Все слои последовательно промазать майонезом, картофель и морковь немного посолить. Верх салата «Рождество» засыпать тертым твердым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5206,'Отварить картофель в «мундире». Разрезать клубни вдоль, положить в смазанную маслом форму. Приготовить чесночное масло: перемешать мягкое сливочное масло, тертый  пармезан, сметану, раздавленные дольки чеснока, рубленую зелень петрушки. Намазать массу на картофельные половинки, печь картофель в чесночном масле в течение 10–15 минут в духовке при температуре 250 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5207,'Нарезать банан на кружки или приготовить из него пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5207,'Отрезать два ломтя хлеба, один смазать арахисовым маслом, другой — банановым пюре, соединить вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5207,'Распустит сливочное масло, и подрумянить бутерброд с каждой стороны. Перед подачей бутерброды с бананом от Элвиса Пресли разрезать по диагонали на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5208,'Отварить курицу целиком, разрубить на куски среднего размера, обжарить на сливочном масле. Мясо залить водой или бульоном, положить еще немного сливочного масла. Отдельно обжарить картофель, нарезанный кубиками, и помидоры кружочками, шампиньоны. Все перемешать, разлить в керамические горшочки, долить белое сухое вино. Прогреть курицу с шампиньонами по-купечески в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5209,'Перемешать в кастрюльке мед, молоко, масло, какао, сахар и гашеную соду. Нагреть массу на плите до появления пузырьков, как при закипании (или нагреть в микроволновке). Яйцо немного взбить и добавить в нагретую массу. Перемешать и постепенно подсыпать муку. Добавляя муки, следует учитывать, что после остывания тесто загустеет. Слишком густое тесто будет трудно раскатывать в коржи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5209,'Получившееся тесто разделить на 8 частей и раскатать каждую очень тонко. Перенести раскатанный корж на смазанный противень, это можно сделать с помощью скалки. Придать окончательную форму коржам уже на противне. Вилкой сделать несколько проколов в корже. Поставить противень в духовку на 5 минут. Духовка должна быть разогрета до 175 градусов. Так выпечь все коржи. Для крема перемешать молоко, сахар, муку, нагреть на слабом огне и сварить до загустения, постоянно помешивая. Положить в крем сливочное масло и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5209,'Промазать коржи кремом и оставить на 2–3 часа для пропитывания. Сверху положить что-нибудь плоское и тяжелое, например, разделочную доску, чтобы коржи при пропитывании остались ровными. Приготовить помадку. Сливки разогреть на небольшом огне, в них добавить поломанный кусочками шоколад. Перемешать и дать раствориться шоколаду. Готовой помадкой залить торт «Спартак» с заварным кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5210,'Нагреть духовку до 200 градусов заранее. Картофель разрезать на 8 частей. Дольки перемешать вместе с растительным маслом. Сухари смешать с чесноком, солью, порезанным шнитт-луком и измельченным розмарином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5210,'Смесь специй перемешать с дольками картофеля, чтобы они равномерно покрылись специями. Выложить подготовленные дольки на противень, который предварительно смазать маслом. Поставить запекаться в духовку на 40 минут пока хрустящий картофель в специях не будет готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5211,'Зеленые помидоры порезать на дольки небольшого размера. На кружки порезать перец. Чеснок очистить и измельчить через чесночный пресс. Все продукты смешать и оставить на полчаса, чтобы овощи дали сок. Разложить через полчаса салат «Кобра» по банкам, которые предварительно простерилизовать, и закатать их металлическими крышками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5212,'В большой кастрюле воду вскипятить и сварить спагетти. Порезать кубиками филе курицы и выложить его на горячую сковородку. Обжарить курицу до белого цвета. Влить подогретое молоко и вскипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5212,'Добавить в кипящее молоко сыр, чеснок и соль по вкусу. Варить соус пока он не загустеет, затем снять с огня и добавить к спагетти. Сразу подать спагетти с курицей в молочно-сырном соусе на стол, посыпав натертым сыром, зеленью и черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5213,'Масло нагреть при комнатной температуре до мягкости. Смешать его с сахаром. Ввести к маслу по одному яйцу. Смесь перемешать до однородного состояния. Сухие ингредиенты высыпать в масляно-яичную смесь и снова хорошо перемешать. Влить в тесто молоко и размешать тесто. Получится густое, липкое тесто. В формы для маффинов положить бумажные корзинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5213,'Тесто разлить по формам для маффинов с помощью кондитерского шприца. Наполнить формочки только до половины, положить в центр ириску, дольку шоколада или ягодку. Залить тестом сверху. Поставить ванильные маффины с начинкой в духовку на 15–20 минут до румяной верхушки. Температура выпекания примерно 175 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5214,'Заранее вечером намазать хлебцы творожным сыром, обернуть пищевой пленкой и оставить пропитываться в холодильнике на всю ночь. Благодаря этому они станут мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5214,'Утром снова намазать хлебцы сыром и положить сверху рыбу и тонкий пластик огурца. Свернуть в трубочку хлебцы с начинкой и закрепить получившиеся роллы из хлебцов зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5215,'Потереть кабачок. Добавить к нему желтки, муку, манку и соль. Пожарить кабачковые блинчики. Перемешать фарш и взбитые белки. Добавить молоко, соль. При желании поперчить. Тоже обжарить блинчики такого же размера, как и блинчики из кабачка. Обжарить морковь и лук, перемешать с чесноком, майонезом и зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5215,'Помидоры порезать кружками. Сложить слоями блинчики из кабачка, затем мясной блинчик, затем жареные овощи, на них уложить помидорные кружки. И снова в том же порядке. Кабачковый торт с овощами и куриным фаршем готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Развести в полулитре теплой воды дрожжи, посолить, добавить яйцо и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Всыпать в смесь муку, замесить тесто до густоты сметаны и убрать в холодильник на 2 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Порезать колбасу, лук, черемшу, грибы, перец, сыр натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Вылить на смазанный противень тесто, дать ему равномерно растечься и поставить запекать, пока тесто не зарумянится (6-7 мин).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Вынуть противень смазать тесто томатным соусом, уложить на него подготовленные ингредиенты, посыпать сверху тертым сыром, украсить кружками салями и отправить пиццу в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5216,'Если какого-либо ингредиента для американской пиццы с колбасой салями и сыром нет, то его можно заменить за счет увеличения другого.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5217,'Для фарша потереть лук на терке, картофель и чеснок. Смешать с мясом. Добавить яйцо к мясу, порезанный мелко батон и приправляем паприкой, перцем и солью. Перемешать фарш тщательно до однородности. Из фарша слепить лепешку, в ее центр положить вареное яйцо без кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5217,'Оборачиваем яйцо фаршем, закрывая его со всех сторон. Получившийся шарик из фарша с начинкой выложить на смазанный противень. Выпекать яйца в мясном фарше с беконом в духовке при 180 градусов в течение 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5218,'Масло и молоко поместить в кастрюлю и нагреть, довести до кипения и всыпать муку. Приправить перцем и добавить соль по вкусу. Перемешать. Убрать массу с огня, еще раз перемешать и вернуть на плиту на умеренный огонь, помешивая еще 2 минуты варить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5218,'Массу немного охладить и ввести яйца по одному. Тщательно вымешивать массу каждый раз. Положить сыр и горчицу. На противень уложить пергаментную бумагу. Двумя чайными ложками зачерпнуть массу и выложить на противень, оставляя расстояние между булочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5218,'Гужеры поставить выпекаться при 220 гр. После того как булочки увеличатся в размерах, уменьшить температуру до 190 градусов. Через 12 минут булочки вытащить. Масло с чесноком подогреть, добавить зелень и смазать еще горячие сырные гужеры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5219,'Блендером взбить белки в очень пышную и густую пену. Пена должна стоять крепко, не меняя формы и не оседая. Добавить сахар или пудру небольшими порциями и продолжать взбивать. Долго взбивать не следует, иначе масса осядет и потеряет пышность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5219,'Пергаментную бумагу положить на противень. Белковую массу выложить в виде безе на противень с помощью ложки или кондитерского шприца, так получится ровнее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5219,'Безе поставить в холодную духовку и включить температуру 90 градусов.Оставить высушиваться десерт в течение 2–2,5 часов. Оно не должно коричневеть. Лучше делать домашнее безе маленького размера, тогда они быстрее высохнут. Для десерта большого размера может понадобиться до 4 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5220,'Помыть шампиньоны и порезать на пластики. Грибы обжарить в собственном соку на сковороде без масла. Добавить соль. Дождаться, когда испарится вся жидкость, и снять грибы с огня. Охладить. Порезать кубиками лук и обжарить, добавив немного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5220,'Тертую морковь обжарить с маслом отдельно от лука. Масла при обжарке овощей использовать по минимуму. Порезать кубиками яйца. Смешать в салатнике яйца, грибы, овощи и кукурузу. Добавить перец и заправить грибной салат «Пальчики оближешь» сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5221,'Потереть мелко сыр. Порезать мелко ветчину, петрушку и 6 сваренных яиц. Картошку сварить в мундире. Из картофеля сделать пюре. Положить в него ветчину, яйца, сыр, лук и всыпать петрушку. Добавить 2 яйца сырых и соль, перемешать. Сформировать из картофельного фарша котлеты и обвалять их в сухарях. Картофельные котлетки с сыром и ветчиной обжарить с двух сторон, аккуратно переворачивая, чтобы их не сломать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Бекон нужно купить в нарезку, чтобы он уже был порезан на тонкие пластики. С него снять кожурку, которую пока отложить в сторону. Порезать бекон на полоски размером 0,5х4 см. Полоски бекона отварить в течение 10 минут в 1,5 литре воды. Слить воду, полоски обсушить бумажными полотенцами. Взять сотейник диаметром 26 см или больше. Налить 1 ст. л. растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Обжарить на среднем огне бекон. Его нужно только подрумянить, будет достаточно 2–3 минут. Вынуть бекон шумовкой на тарелку, оставив в сотейнике вытопленный жир. Порезать мясо крупно и обсушить салфетками, иначе мясо не обжарится. Включить огонь под сотейником посильнее, чтобы жир дымился. Обжарить мясо несколькими партиями. Выложить к бекону. Порезать кружками морковь, а лук мелко покрошить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Подрумянить овощи в том же жире и выложить на отдельную тарелку. Слить жир с сотейника и выложить туда бекон и мясо. Посыпать солью и приправить перцем, встряхнуть. Обсыпать мукой и снова встряхнуть. Обжарить 4 минут на одной стороне, потом встряхнуть и жарить еще 4 минуты. В результате обжаренная мука образует тонкую корочку на мясе. В сотейник налить вино, бульон, положить томатную пасту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Приправить раскрошенным лавром, давленым чесноком и тимьяном. Положить оставшуюся шкурку от бекона. Вскипятить и убавить огонь, чтобы жидкость немного булькала. Оставить тушиться на 3 часа. В это время нужно приготовить грибы и лук в темной глазури. Возможно достать мелкие белые луковицы будет сложно. Во второй сотейник меньшего размера положить по 1,5 ложки сливочного и растительного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Разогреть их и на среднем огне обжарить лук, стараясь не повредить верхний слой луковиц. Влить к луковицам бульон, всыпать соль и перец. Положить букет гарни. Томить на медленном огне 40–45 минут под крышкой. После этого букет гарни вынуть и выкинуть. У крупных шампиньонов срезать ножки. Смазать грибы растительным маслом и положить на сковороду-гриль, посыпать немного солью и перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Обжарить на гриле за 5 минут на одной стороне, перевернуть и еще 5 минут жарить на другой стороне. Готовые грибы можно оставить целыми или порезать на 2 или 4 части. Мясо и бекон через 3 часа тушения вынуть из соуса. Соус процедить через сито в соусник.  Вымыть сотейник и положить в него обратно мясо и бекон. Сверху выложить шампиньоны и луковицы в темной глазури. Снять жир с соуса и проварить 2–3 минуты на медленном огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5222,'Консистенция соуса должна быть – «покрывает ложку тонким слоем». Если он гуще, то разбавить бульоном. Если жидкий, то уварить. Соус перелить в сотейник сверху грибов и лука, охладить и убрать в холодильник до подачи на стол. Перед приходом гостей (за 15–20 минут) мясо достать их холодильника и довести до кипения на медленном огне. Закрыть крышкой и оставить говядину «Bouef Bourguignonne» по-бургундски до подачи на стол на медленном огне. Периодически соусом поливать овощи и мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5223,'Взбить вместе с сахаром яйцо. Добавить измельченную лимонную цедру. Перемешать творог с гашеной содой и добавить яичную смесь. Постепенно подсыпать муку. Перемешать до однородного теста, не слишком жидкого и не слишком густого. Скатать шарики по размеру чуть меньше чем грецкий орех. Для удобства смазывать ладони растительным маслом, чтобы творог не прилипал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5223,'Творожные шарики обжарить в растительном масле на слабом огне. Масло предварительно хорошо разогреть. В сковородку закладывать шарики так, чтобы оставалось между ними место, так как они при жарке увеличиваются в размерах. Присыпать готовые творожные шарики сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5224,'Нарезать куриное филе, запанировать его в смеси кунжута, перца и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5224,'Сильно разогреть масло и подрумянить мясо с двух сторон по 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5224,'Дать курице остыть и нарезать на полоски, на стол куриное филе по-американски в кунжуте подавать с рисом или овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5225,'Ветчину, яйца, огурец и сладкий перец порезать на тонкие брусочки. Потереть сыр. В креманку или большой фужер выложить ингредиенты по слоям. На самое дно бокала ветчина, затем положить огурцы, на них сверху выложить яйца. Перец положить следующим слоем и посыпать все сверху сыром. Между слоями промазать майонезом. Украсить салат-коктейль с ветчиной и сыром ломтиком огурца и свежей зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5226,'Филе отварить в соленой воде и охладить. Помыть грибы, порезать на кубики. Морковь потереть крупно на терке. Порезать кубиками лук. На сковороде обжарить лук до прозрачности. Положить к нему морковь и тоже обжарить. Грибы выложить на сковородку и потушить до готовности. Посолить и поперчить. Остудить овощи и грибы. Вареные яйца почистить и порезать кубиками вместе с филе. Слить с кукурузы воду. Перемешать все продукты и заправить салат с кукурузой, грибами и курицей майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5227,'Почистить кальмары и промыть под проточной водой. Опустить их в кипящую воду и проварить 3 минуты. Остудить и порезать кальмары на тонкие длинные брусочки. Вычистить из помидоров семена и порезать оставшуюся мякоть соломкой. В салатник выложить кальмары, помидоры, горошек. Мелко порезать зелень и добавить в салат. Салат «Просто и вкусно» с кальмарами заправить майонезом и немного подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5228,'Включить духовку нагреваться до 220 градусов. Лаваш разрезать на небольшие кусочки квадратной или треугольной формы. Выложить лаваш на противень и добавить туда же масло и все приправы. Перемешать, чтобы все кусочки смазались маслом и были обсыпаны приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5228,'Или вначале смажьте лаваш кондитерской кисточкой с маслом, посыпьте приправами, а потом разрежьте на кусочки. Так получиться более диетический вариант чипсов. Поставить противень на 6–7 минут в духовку.  Если чипсов «Начос» из тонкого лаваша много и на противне они лежат в несколько слоев, то время от времени их нужно перемешивать для равномерного подсушивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5229,'Промыть шампиньоны. Налить в кастрюлю воды. В воду добавить перец горошком и черный молотый перец.  Довести воду до кипения и варить грибы в рассоле 3–5 минут. Вынуть грибы шумовкой и сложить в контейнер для маринования. От рассола оставить столько, чтобы закрыло грибы в контейнере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5229,'Добавить в рассол, сахар, уксус и размешать. Остывшим рассолом залить грибы и убрать в холодильник и оставить на ночь мариноваться. Слить рассол на следующий день, а шампиньоны сбрызнуть оливковым маслом. Порезать репчатый лук и подать маринованные шампиньоны вместе с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5230,'Залить лапшу фунчозу на 5 минут кипятком и посолить. Промыть в холодной воде в течение 1 минуты. Порезать соломкой овощи, чеснок измельчить мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5230,'Разогреть на сковородке масло и немного обжарить перец и морковь до мягкости. В конце обжаривания положить чеснок. Фунчозу смешать с обжаренными овощами и огурцом. Залить уксусом (3 ч. л.) и соевым соусом по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5231,'Заранее включить духовку нагреваться до 200 градусов. Муку и соду просеять вместе. Миксером взбить яйца. Подмешать к ним сметану и растопленное масло. Всыпать сахар и соль. К яично-сметанной смеси добавить муку с содой. Если получится слишком жидкое тесто, можно добавить еще муки, чтобы оно не прилипало. Убрать на 20 минут тесто в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5231,'За это время сделать начинку – творог размять с сахаром. Белок взбить в пышную пену и перемешать вместе с творогом. Всыпать муку и снова перемешать. Тесто достать из морозильной камеры и раскатать на столе. Вырезать кружки из теста. Начинку выложить на лепешку с одной стороны, накрыть второй стороной теста и соединить края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5231,'Сформированные сочники выложить на противень, накрытый бумагой для выпечки. Намазать сверху желток, чуть-чуть размешанный с водой. Поставить противень в духовку на 20 минут, пока сочники не зарумянятся. Немного остудить творожные сочники и обсыпать сахарной пудрой через мелкое сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5232,'В микроволновке растопить 250 г черного шоколада и 250 мл сливок. Отдельно растопить 250 мл сливок с 150 г белого шоколада. Обе смеси охладить в холодильнике не менее 4 часов. Когда смеси охладятся, добавить к «черной» смеси 250 мл взбитых сливок и перемешать. Застелить миску для десерта пищевой пленкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5232,'Получившийся шоколадный крем густо нанести на стенки миски, дать застыть в холодильнике в течение 1–2 часов. Внутрь положить «белую» смесь. Сверху выложить кусочки, оставшиеся после обрезки бисквита и прикрыть шоколадным бисквитом, вырезанным по форме миски. Убрать в морозилку до утра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'Сырно-яичную массу распределить на кусочки хлеба, по диагонали разложить 3-4 полоски рыбы, между которыми положить крабовые палочки (диагонально).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5232,'После того как десерт застынет, перевернуть миску на плоское блюдо, вынуть аккуратно содержимое и намазать глазурью, приготовленной из 100 г темного шоколада и 150 мл сливок. Получившийся десерт «Шоколадная бомба» остудить в морозилке, чтобы застыла глазурь и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5233,'Яйца взбить миксером вместе с сахаром. Разрыхлитель теста перемешать с мукой, а лучше вместе просеять. Все ингредиенты перемешать в одной посуде.  Духовку включить нагреваться на 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5233,'Получившееся тесто вылить в форму для выпечки и поставить в духовку. Выпекать до готовности. Остудить готовый торт и разрезать корж на 2 части вдоль. Для крема взбить сметану с сахаром и добавить йогурт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5233,'Сливки для крема взбить отдельно и затем смешать со сметанной массой. Кремом промазать коржи со всех сторон. Украсить домашний торт на скорую руку по собственному вкусу – фруктами, шоколадной или кокосовой стружкой, орехами, глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5234,'Цветной желатин развести, следуя инструкции на упаковке. Для застывания разные цвета разлить по разным контейнерам. Оставить застывать цветное желе минимум на 3 часа, а желательно на всю ночь. Готовое желе аккуратно и ровно порезать на кубики одинакового размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5234,'Кубики желе засыпать в отдельную форму. В 0,5 стакана холодной кипяченой воды развести бесцветный желатин. Затем влить 1,5 чашки горячей воды, когда желатин начнет растворяться. Мешать пока желатин не растворится полностью. Сгущенное молоко добавить к бесцветному желатину и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5234,'После того как молочная смесь немного остынет, залить ей цветные кубики желе. Убрать форму на ночь в прохладное место или холодильник для окончательного остывания. Желе-десерт «Разбитое стекло» перед подачей к столу порезать на ломтики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5235,'Потереть кабачок на терке и посолить. Через 5 минут слить выделившийся сок. К кабачку добавить яйца, муку и манную крупу. Перемешать тесто и на сковороде выпечь блинчики. Обжаривать блинчики с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5235,'Потереть морковь, покрошить мелко лук. Обжарить овощи на сковородке. Чеснок измельчить через чесночный пресс и добавить к нему мелко порезанную зелень. Заправить майонезом и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5235,'Кабачковые блинчики сложить стопкой, при этом промазывая каждый чесночно-майонезной смесью и выкладывая обжаренные лук с морковью. Сверху тортик из овощей просто помазать оставшейся смесью майонеза и зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5236,'Открыть консервированную кукурузу и слить жидкость, приготовить в блендере пюре из кукурузы, переложить ее в кастрюлю, долить 2 стакана воды, нагреть, помешивая, до кипения и снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5236,'Распустить в другой кастрюле сливочное масло, добавить постепенно всю муку, долить горячее молоко. Если не удалось избежать комков, то остуженную смесь залить в блендер и взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5236,'Смешать кукурузу и мучную смесь, помешивая нагреть до кипения, добавить креветки, соль, после этого продолжать варить суп не более 7 минут, иначе креветки потеряют плотность.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5236,'Разлить суп-крем из кукурузы и креветок по тарелкам, добавить белые сухарики, сыр и посыпать зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5237,'Разрезать неочищенный баклажан на круглые пластики. Посолить и обжарить на горячей сковороде с каждой стороны до румяности. Чтобы убрать с баклажанов лишнее масло, выложить их на бумажное полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5237,'Мелко натереть сыр, морковь и чеснок. Смешать с майонезом. Каждый обжаренный ломтик баклажана намазать сырной пастой, выложить сверху ломтик помидора. Пикантную овощную закуску с сыром подавать на блюде с листьями салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5238,'Порезать шампиньоны на средние кусочки и обжарить на сковороде на растительном масле. Потереть на терке сыр и перемешать с обжаренными грибами. Порезать багет на круглые ломтики. Подсушить их в тостере или в духовке. Можно также подсушить их на сковороде без использования масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5238,'Обжаренный хлеб потереть долькой чеснока и помазать слегка майонезом. Смесь из грибов и сыра выложить сверху. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5259,'Уложить в кастрюлю измельченную капусту, добавить измельченный лук, мелко нарезанную морковь, 2 ст.л. растительного масла, корень петрушки, потушить до готовности, затем добавить к грибам и мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5239,'Отделить белки от желтков и взбить их по отдельности, добавив к желткам сахар. Аккуратно перемешать белковую и желтковую массу и всыпать стакан муки. Добавить к тесту растопленное сливочное масло и положить разрыхлитель теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5239,'Форму смазать маслом, распределить на дне ягоды или другую начинку. Влить тесто. Выпекать пирог с черникой в духовке около получаса при температуре 180 градусов. Украсить пирог на свой вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5240,'Включить заранее нагреваться духовку на 180 градусов. Сливочным маслом хорошо промазать внутреннюю поверхность формы. Все продукты по рецепту перемешать и положить в творожную массу часть ягод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5240,'Тесто с ягодами выложить в форму. Сверху украсить остальными ягодами, выложив произвольный рисунок. Поставить в духовой шкаф на 40 минут. Запеканку творожную с иргой очень вкусно кушать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5241,'Из банки рыбных консервов слить масло. Кусочки рыбы размять вилкой. Порезать мелко лук, морковь натереть крупно на терке. Обжарить на растительном масле. Отваренные яйца и сыр тоже потереть – на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5241,'Тортик выкладывается слоями, каждый при этом щедро промазывается майонезом. Первый слой – крекеры в 3 ряда по 3 штуки, на них нужно положить зажарку из овощей. Снова крекеры, потом рыбные консервы, крекеры, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5241,'Следующий слой опять крекеры и сыр. Даже если будет излишек майонеза между слоями, его впитают крекеры. Закусочный бутербродный торт с рыбой оставить минимум на пару часов пропитываться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5242,'Измельчить черешню в блендере. Консистенция может быть как пюреобразной, так и с кусочками – ориентируйтесь на свой вкус. Смешать сгущенное молоко и сметану. Ягодное пюре перемешать со сметанной массой. Смесь выложить в мороженицу и начать охлаждать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5242,'Когда мороженица остановится, то полученный десерт убрать в холодильник. Если мороженицы нет, то смесь залить в контейнер и через каждые 20–30 минут доставайте контейнер и перемешивайте мороженое с черешней для предотвращения появления кристаллов льда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5243,'Порезать на длинные ломтики молодые кабачки. Посолить их и отставить в сторонку на 10–15 минут. Помидоры порезать на дольки или кубики. Порезать на тонкие ломтики сыр. Очистить чеснок и оставить дольки пока целыми. Взбить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5243,'Кабачковый ломтик обвалять вначале в муке, а потом в яйце и сразу выложить на горячую сковородку. Обжарить по 5 минут на каждой стороне до мягкости. Пока ломтики еще горячие, выложить их на блюдо и смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5243,'На один край кабачка положить сыр, на второй – помидорный ломтик. Чеснок выдавить и помазать им сверху кабачковую заготовку. Посыпать измельченной зеленью. Свернуть кабачковый бутерброд в рулет с помидорного края. И заколоть зубочисткой. Выложить рулеты «Тещин язык» из кабачка на сервировочное блюдо краем вверх.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5244,'Рыбное филе измельчить, прокрутив через мясорубку, а также прокрутить через нее сыр, зелень, лук и имбирь. Фарш смешать с желтками, сливками и всыпать сухари. Посолить и поперчить по собственному вкусу. Вымесить хорошо фарш и для пышности несколько раз отбить его (приподнять над миской и с силой его уронить и так несколько раз).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5244,'Сформировать рыбные котлеты из фарша. Запанировать в сухарях и обжарить на сильном огне на сковородке с растительным маслом с двух сторон. Когда на рыбных котлетах с сыром и зеленью появится корочка, уменьшить огонь и потушить под крышкой 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5245,'Почистить и порезать на кубики сельдь. Лук покрошить мелко. Потереть на крупной терке картофель и перемешать его с майонезом. Свеклу тоже потереть и смешать с майонезом, но добавить к ней еще чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5245,'Порезать на кубики морковь и сыр, тоже смешать с майонезом. Салат выложить слоями: на дно салатника картофель, потом лук, на него сельдь кубиками, сверху свеклу с чесноком и в конце морковь с сыром. Украсить салат «Наваждение» с соленой сельдью свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5246,'Обжарить на сухой сковороде орехи. После этого 1/2 часть мелко натереть, остальные измельчить скалкой (не очень мелко). Перемешать фарш, посыпать солью, положить орехи, измельченный лук, чеснок, приправы (паприку и четыре вида перцев), сырое яйцо. Размешать. На тридцать минут поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5246,'Намочить водой руки, сделать из фарша девять колобков (кёфте). Высыпать на тарелку кунжут и хорошенько обвалять в нем кёфте. Смазать формочку растительным маслом, выложить колобки. Приготовить соус: насыпать в молоко муку, посыпать паприкой и солью по вкусу. Взбивать, пока не исчезнут комки. Вылить соус на кёфте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5246,'Готовить минут сорок при температуре двести градусов. Чтобы была румяная корочка, за пять минут до приготовления можно включить режим «Гриль». На гарнир отварить стручковую зеленую фасоль, откинуть на дуршлаг. Посыпать паприкой, солью и любыми приправами. Обжарить на масле. В принципе гарнир к мясным кёфте в соусе может быть любым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5247,'Почистить грейпфрут, порезать на дольки или кружочки. Таким же образом порезать помидоры. Порезать сыр на кубики. Соединить оливки, куски помидоров, грейпфрута, сыра. Соединить масло с зеленью, уксусом и солью. Заправить салат, поставить на тридцать минут в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5248,'Приготовить тесто 1: перетереть маргарин и сахар, вбить по одному яйцу, насыпать муку с порошком для выпечки. Формочку (30 на 35 сантиметров) застелить специальной бумагой, вылить тесто, готовить 35 минут, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5248,'Приготовить тесто 2: Замесить тесто из всех ингредиентов, кроме какао. Разделить пополам. Одну часть отправить в холодильник, в другую насыпать какао, замесить и тоже отправить в холодильник. Приготовить творожный крем: перетереть маргарин и сахар, вбить желтки, добавить порошок для выпечки, творог, пудинги, взбитые в пену белки, крупно натертое замороженное темное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5248,'На формочку постелить бумагу, облепить ее светлым тестом, готовить до румяного цвета. На готовое тесто положить творожный крем, готовить час, соблюдая температуру 175 градусов. Остудить. Приготовить пудинговый крем с желе: растворить в кипяченой воде желатин. В молоке растворить сахар и пудинг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5248,'Закипятить остальное молоко, налить в него пудинг, варить до загустения. Охладить. Растереть масло на пушистую массу, кладя по ложке заварной охлажденный крем. Добавить желе в пудинговую массу. Положить крем на творог, разровнять. Сверху положить первое тесто. Полить торт «Секрет монашки»с творожным кремом шоколадной глазурью, посыпать измельченными орешками, поставить в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5249,'Крупу перебрать, промыть, несколько раз поменяв воду, замочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5249,'Холодной водой залить курицу, добавить морковь и лук, нарезанные дольками, закипятить, убрать пенку, посолить и варить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5249,'Готовое мясо достать, бульон процедить и опять закипятить, всыпать крупу, варить еще 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5249,'Кубиками нарезать картофель, морковь, капусту и измельчить лук, все овощи добавить в суп и отварить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5249,'За 5-10 минут до конца приготовления «Уральские» щи с курицей посолить, поперчить, подавать с мясом, сметаной и зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5250,'Обжарить лук. Бананы, порезанные на кружки, сбрызнуть соком лимона. Подготовить ингредиенты. Сначала положить слой лука. Тонко смазать майонезом. Положить сверху курицу, покрыть майонезом. На курочку положить половину яиц. Положить бананы, на них остальные яйца. Залить майонезом, посыпать сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5250,'Чтобы украсить салатик, порезать пополам маслины. Собрать их срезом вверх на трубочках из-под соков. Вставить в трубочки перья лука, надрезанные не до конца, – это будет пышная листва. Установить пальмы на островок. Вокруг салата посыпать хлебцами или сухариками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5251,'Пропустить через мясорубку чеснок и грецкие орехи. Положить все в глубокую емкость и медленно вливать питьевую воду, помешивая. Воду использовать холодную, чтобы не горчили орехи. Масса должна стать средней по густоте, посыпать приправы по вкусу (кинзу, уцхо, соль, сунели, перец). Можно положить грузинскую аджику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5251,'Обжарить филе трески на сковороде со всех сторон. Промокнуть рыбу салфетками, чтобы убрать масло, переложить в глубокую посуду. Налить соус, отставить минут на тридцать. Подавать филе трески под соусом бажи в холодном виде. Украсить зернами граната.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5259,'В горшочек влить отвар из грибов, добавить кардамон, соль, перец, муку, которую нужно предварительно обжарить в столовой ложке масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5252,'Вскипятить томатную пасту и растительное масло, добавить уксус, охладить. Когда маринад остынет, насыпать соль и два вида перцев. Перец горошком должен быть не черным, а душистым, чтобы блюдо не было острым. Почистить рыбку, кожицу при этом не обдирать, сделать филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5252,'Порезать лук на полукольца, положить в маринад и перемешать.Сложить филе в посуду, перекладывая смесью. Отставить сельдь по-корейски минимум на четыре часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5253,'Муку, соль, яйцо, молоко или воду смешать, приготовленное тесто раскатать так, чтобы оно было тонким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5253,'Тесто слегка обсыпать мукой, разделить на полоски шириной по 6 см, сложить их друг на друга и нарезать поперек, полученной лапше дать подсохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5253,'Курицу, морковь и лук отварить, за несколько минут до готовности мяса добавить лапшу и варить 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5253,'Суп с лапшой по-домашнему на курином бульоне подается горячим и посыпанный рубленой петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5254,'Очистить, обдать кипятком свиные уши, положить в воду и отварить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5254,'Обсушенные и нарезанные уши сложить в сковороду, добавить растительное масло, жарить пока они не подрумянятся, в конце обсыпать блюдо сухарями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5254,'Подавать к столу уши свиные жареные с сухарями можно со свежими салатами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Отварить до готовности картофель, свеклу и морковь, вкрутую сварить яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'3 ст.л. уксуса смешать с сахаром, в полученный маринад положить очищенный и измельченный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Соленые и свежие огурцы мелко порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Натереть сначала белки на мелкой терке, потом отдельно желтки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Сваренные овощи крупно потереть на терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Взять плоское блюдо и уложить салат в виде змеи, все слои промазать майонезом: сначала картофель, затем соленые огурцы, далее свекла, потом свежие огурцы, желток, лук маринованный, белок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Последний слой посыпать морковью, сверху разложить тонкие полоски болгарского перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Из зеленого лука сделать змее чешую, голову — из кусочков овощей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5255,'Перед тем, как подавать новогодний салат «Овощная змейка», его нужно охладить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5256,'Сельдь разморозить на нижней полке холодильника, надрезать брюшко, удалить голову, хвост, внутренности и хребет с костями. Полученное филе порезать на кусочки около 2 см по ширине. Острым ножом нарезать тонкими кружками лимон, лук – кольцами, морковь крупно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5256,'В банку положить слой лука, листочек лаврушки, немного моркови, кружок лимона, засыпать сахаром и солью (по половине чайной ложки), добавить щепотку свежемолотого перца и наконец положить сельдь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5256,'Утрамбовывая, повторить все слои, пока не закончится сельдь и не заполнится банка, закрыть ее крышкой, поставить в холодильник. Через пару-тройку дней селедка по-голландски будет готова, подавая к столу полить маслом, по желанию можно с добавлением уксуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5257,'Порезать на тонкие ломтики очищенный картофель, нашинковать лук на полукольца, перемешать с фаршем грибы, порезанные небольшими кубиками, чуть подсолить, сдобрить перцем. Приготовить из смеси сметаны с яйцом, раздавленного прессом чеснока, перца и соли заправку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5257,'Заполнить форму половиной ломтиков картофеля, чуть присолить и поперчить, прикрыть луком, а сверху уложить фарш, присыпать его сырной стружкой. Выложить последним слоем оставшийся картофель, приправить солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5257,'Залить мясную запеканку заправкой  поставить примерно на час в духовку с температурой около 190 градусов, в конце приготовления присыпать запеканку сырной стружкой и дать ей зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5258,'Из сметаны с добавлением творожной массы и мягкого масла миксером взбить однородный крем. Печенье друг за другом окунуть в молоко, выложить на плоское блюдо, промазать кремом, все повторить до окончания крема и печенья. Готовый торт из печенья перед подачей должен постоять около 5 часов, но если не хватит терпения, то можно и чуть меньше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5259,'Мясо обжарить, грибы сварить, все мелко покрошить и сложить в глиняный горшочек: сначала грибы, потом мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9628,'Выложить изделия на тарелку и поставить в морозилку на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5260,'Положить в кастрюлю очищенных кальмаров, залить подсоленной водой так, чтобы она полностью покрыла тушки, дать закипеть, проварить минуту, убрать с плиты, дать остыть. Яйца порубить, нашинковать перья лука, порезать на кубики палочки и остывших кальмаров, все перемешать с рисом. Заправить крабово-кальмаровый салатик майонезом, подсолить, перемешать, переложить в салатник, присыпать зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5261,'Отварить в кипятке кубики картофеля, обжарить крупно натертую морковь с кубиками лука. Пока готовится зажарка порезать на кусочки курятину,  натереть замороженные сырки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5261,'Содержимое сковороды и мясо высыпать к картофелю, немного проварить, добавить сырки, непрерывно помешивая, дать им полностью растворится. Подать быстрый суп из плавленых сырков и окорока лучше с гренками из батона или, если нравится, бородинского хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5262,'В глубокую и широкую кастрюлю, или другую подходящую емкость, высыпать палочки, добавить распущенное масло, вареное сгущенное молоко, перемешать, слегка разминая палочки. Цветной мармелад порезать на кубики, высыпать к палочкам, осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5262,'Сформовать из полученной массы «колбасу», обвалять в обжаренных и измельченных орехах. Обернуть пирожное из кукурузных палочек фольгой или пленкой, положить минут на 30 в морозильную камеру. Достать, порезать на ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5263,'Перемешать тщательно все ингредиенты до получения однородного теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5263,'Приготовить из перемешанного со сгущенкой творога начинку для торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5263,'Вылить треть теста в подготовленную форму (не забудьте смазать маслом), разложить начинку, прикрыть оставшимся тестом, поставить торт «Лунная ночь» в духовку с температурой около 190 градусов, выпекать минут 40-45.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5264,'Поджарить грибы вместе с луком, пока они готовятся натереть крупно сыр, порезать грудку и перец на одинаковые небольшие кусочки, по отдельности натереть желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5264,'Перемешать все кроме яиц, подсолить, сдобрить майонезом, плоское блюдо застелить салатными листьями, выложить салат для детей с куриной грудкой в виде любого животного, например, зайчика, присыпать верх натертыми желтками и белками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5265,'Положить в чуть теплое молоко дрожжи, добавить соль и сахар, перемешать, порциями всыпать муку, а в конце – травы, вымесить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5266,'Перемешать подсоленное масло с прованскими травами и мелко нашинкованным чесноком. Порезать батон на кубики, засыпать их в керамическую форму, облить пряной масляной смесью, перемешать, обжарить при 170 градусах примерно 20 минут, за это время несколько раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5266,'Обжарить нарезанное на полоски филе, подсолить, поперчить, обсыпать кунжутным семенем, обжарить при сильном нагреве и помешивании около 5 минут, пережаривать нельзя, иначе можно пересушить мясо. В фетаксу добавить порубленный укроп, базилик, раздавленный прессом чеснок, размять все до однородности вилкой, добавить для мягкости немного сливок, скатать из массы шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5266,'Приготовить из смеси мандаринового сока, соевого соуса, майонеза и чеснока заправку для салата «Ревнивец» с курицей и сыром.  Порезать мелко капусту, сладкий перец – тонкой соломкой. Объединить вместе курицу, кукурузу, капусту, перец, мелко нашинкованный лук, хорошо перемешать, выложить на тарелку, поверх уложить шарики из сырной смеси, крутоны, полить сверху заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5267,'В кастрюлю с подсоленной водой положить телячье или говяжье сердце — промытое, без пленок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5267,'Отварить сердце в течение 4-5 часов, минимум за 30 , максимум за 60 мин до готовности сердца положить в кастрюлю чеснок, лук, лавровый лист, перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5267,'Готовое сердце отварное охладить, нарезать не крупными кусочками, разложить на плоскую тарелку и посыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5268,'Разбавить кефир водой, чуть подогреть. В кастрюлю вбить яйца, всыпать соль, сахар, влить кефир, тщательно перемешать до возникновения на поверхности пены. Всыпать, размешивая муку небольшими порциями, должна получиться довольно тягучая масса. добавить погашенную соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'По каждому краю новогодние бутерброды «Ёлочки» с рыбой и крабовыми палочками',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'украсить укропом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5268,'Хорошо раскалить в сковороде масло, обжарить оладьи на кефире без дрожжей с двух сторон, подать горячими со сливочным маслом, сметаной, а для любителей сладкого с вареньем, медом или сгущенкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5269,'Порезать подготовленный кусок свинины на ломти толщиной чуть больше пары сантиметров, но до конца не дорезать, чтобы получилось подобие гармошки. Промежутки чуть подсолить, поперчить, вставить в каждый по паре-тройке долек чеснока, пластинку сыра и колечко помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5269,'Шейку запаковать тщательно в фольгу, шов должен быть сверху, уложить на противень, поставить на час-полтора в прогретую до 200 градусов духовку. Чтобы вкуснейшая и нежнейшая фаршированная свиная шея получилась еще и с аппетитной  золотистой корочкой надо осторожно отогнуть верх фольги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5270,'Разрезать сосиски вдоль на несколько полосок, сыр порезать на такие же примерно по размеру пластинки, но слегка короче. Уложить на каждую полоску сосиски сыр, свернуть в трубочку, скрепить зубочисткой, запечь закуску «Улитки» минут 8-10 в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5271,'Раскатать пласт готового и чуть размороженного слоеного теста, разделить на две части, соответствующие размеру противня, сделать на них несколько проколов вилкой, выпечь в прогретой до 180 градусов духовке минут 12 до появления золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5271,'Один корж оставить целым, второй порезать размером с порционные куски десерта. Взбить сахар вместе с белками в устойчивые пики, в другой емкости повторить аналогичную операцию с желтками, всыпать крахмал, муку, ванильный сахар, влить воду, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5271,'В кипящее молоко влить желтковый крем, варить до получения густой массы на слабом огне, снять с плиты, аккуратно вмешать белки, полученный крем распределить равномерно по основе, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5271,'Взбить оставшиеся полстакана сахара со сливками, нанести массу на уже остывший крем, завершить сборку торта «Наполеон» в балканском стиле нарезанными кусочками коржа, присыпать поверх сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5272,'Порезать грибы на пластинки, обжарить в разогретом масле до мягкого состояния. Срезать мясо с кости большими кусками, разобрать на волокна, но не совсем мелко. Добавить курицу в грибы, пару минут жарить все вместе, влить сливки (сметану), размешать, нагревать пока начинка для ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5272,'Включить для прогрева на 200 градусов духовку. В сотейнике с толстым дном распустить масло, всыпать муку, небольшими порциями, помешивая влить молоко, приправить соус мускатным орехом, варить до получения густой массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5272,'Налить в форму несколько ложек соуса, чтобы полностью покрыть дно, уложить листья, на них – начинку, присыпать сыром, полить соусом, опять повторить все операции два раза. Верх лазаньи с куриной грудкой присыпать сыром, поставить ее в уже разогретую духовку минут на 40.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5273,'Взбить вместе сахар и яйца, влить сгущенное молоко, добавить сметану, все еще раз взбить в однородную массу. Всыпать муку и разрыхлитель, взбить в пышную массу до исчезновения комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5273,'Маслом смазать форму, заполнить тестом, выпекать кекс на сгущенном молоке примерно минут 40, температуру выше 200 градусов не поднимать, готовую выпечку присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5274,'Подготовит специи: укроп нашинковать, чеснок порезать на мелкие пластинки. Помыть огурцы, подрезать концы, сложить в п\э пакет, пересыпать солью, чесноком и укропом. Пакет завязать поплотнее, вложить еще в один для надежности, тоже его завязать, хорошенько потрясти, убрать в холодильник, ароматные и аппетитно хрустящие малосольные огурчики с чесноком будут готовы часов через 6-8.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5275,'Заморозить масло, натереть на терке, перетереть в маслянистую крошку с мукой. Добавить соду, погашенную сметаной, пару желтков, подсолить, вымесить мягкое, упругое тесто, оставить в покое на пару часов. Обжарить орехи, отшелушить от пленки, раздробить блендером в крошку, перемешать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5282,'Смешать все ингредиенты для заправки скандинавского салата с сельдью, добавить вместе с измельченным укропом к салату, поперчить, перемешать. Прежде чем подать к столу дать постоять минут 20 в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Дольки апельсина или грейпфрута разрезать на несколько кусочков, добавить их в соус к мясу и луку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5275,'Разрезать созревшее тесто на пять небольших шариков, 3 раскатать в пласт потоньше, 2 для первого и последнего слоя — чуть толще соответственно размерам противня. Уложить первый на противне, смазать растопленным маслом, равномерно распределить по поверхности начинку, прикрыть коржом потоньше, дальше поступить, как и с предыдущим и т.д.  Растопить в посуде с толстым дном масло и мед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5275,'Верх пахлавы смазать разболтанным желтком, надрезать острым ножом на ромбы, по центру каждого вдавить обжаренный орешек фундука, поставить на четверть часа в прогретую чуть ниже 190 градусов духовку. Достать десерт, сделать надрезы поглубже, залить домашнюю пахлаву медовым сиропом, еще на четверть часа отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5276,'Отварить рис, поджарить нашинкованный лук, смешать с готовым фаршем, вбить яйцо, добавить измельченный чеснок, приправить солью и черным молотым перцем, хорошо вымесить. Скатать из фарша небольшие шарики, обвалять в муке, смазать форму, переложить в нее тефтельки, поставить на треть часа в духовой шкаф при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5276,'Крупно натереть морковь, обжарить, залить половиной стакана воды с разболтанной в нем столовой ложкой жирной сметаны. Сдобрить измельченной зеленью, солью, перцем, добавить немного раздавленного прессом чеснока, дать соусу закипеть. Достать форму, залить содержимое соусом, готовить тефтельки в сметанном соусе еще четверть часа, к столу подать горячими с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5277,'Измельчить половину хлопьев быстрого приготовления блендером, перемешать с дробленым миндалем, стружкой кокоса, всыпать остальные хлопья и сушеную клюкву, перемешать. Растопить в сотейнике масло кокоса и  мед, залить смесь из хлопьев, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5277,'Заполнить полученной массой для приготовления батончиков с клюквой форму, разровнять, хорошо утрамбовать, на пару часов поставить в холодильник, разрезать на небольшие порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5278,'Муку, питьевую соду и корицу смешать, потом просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5278,'Растереть сахар, сливочное масло и яйца, в полученную массу влить молоко, приготовить тесто, понемногу добавляя муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5278,'Тесто раскатать так, чтобы его толщина получилась 0,5 см, с помощью стакана вырезать круги.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5278,'Круглым предметом меньшего размера в середине каждого кружка выдавить отверстие.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5278,'Готовить пончики «Московские» по-домашнему нужно на сковороде в сильно разогретом масле с обеих сторон, а перед подачей посыпать сахарной пудрой или полить шоколадной глазурью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5279,'Порезать сыр на пластинки, вложить их под кожу каждого куриного бедрышка. Переложить куски мяса в форму, присолить. Майонез смешать с порубленной зеленью и раздавленным прессом чесноком, все перемешать, смазать мясо, убрать в духовку. Запекать куриные бедра с зеленью под сыром при температуре чуть ниже 185 градусов примерно 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5280,'Достать заранее из морозилки готовое тесто, дать оттаять, раскатать в прямоугольник, сбрызнуть водой, присыпать корицей, перемешанной с мелким сахаром, скатать тесто в трубочку. Положить ее на стол швом вниз, порезать примерно на равные 5 частей (около 5 сантиметров толщиной).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5280,'Посередине каждого кусочка сделать подходящим предметом продольную борозду с нажимом, так, чтобы у булочек с корицей по-гамбурски поднялись края. Подготовить противень, заполнить булочками, прикрыть тканью, дать треть часа созреть в тепле, выпекать при 200 градусах в уже прогретой духовке примерно треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5281,'Отмерить кефир, залить в миске манку, оставить в покое на 10 минут. Когда смесь достаточно набухнет всыпать сахар и просеянную муку с добавленной содой, влить масло, добавить хорошо вымытый и высушенный изюм киш-миш, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5281,'Подготовить силиконовые формочки, заполнить тестом, 1/4 оставить пустой. Выпекать кексы с изюмом «150» в духовке с температурой не выше 180 градусов треть часа. Готовым кексикам дать слегка остыть, достать из формочек, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5282,'Нашинковать очень тоненько капусту, присолить, чуть-чуть помять, листья салата нарвать на куски руками, яблоко (лучше зеленое)  нарезать тонкой соломкой.  Филе сельди пряного посола разрезать на 3 (крупное на 4) куска.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10619,'Перемешать, снять с плиты и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5283,'Подготовить яблоки, вырезать косточки, нарезать на дольки. Дно чаши смазать маслом, разложить красивым веером. Размягченное масло взбить вместе со сгущенным молоком, добавлять ее порциями. Теперь вбить по одному все яйца, взбивать не прекращать, всыпать по частям муку с разрыхлителем, хорошо все вымесить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5283,'Полученной массой аккуратно накрыть яблоки, выставить режим «Выпечка», готовить пирог с яблоками на сгущенке в мультиварке чуть больше часа, после окончания выпечки под закрытой крышкой подержать четверть часа на режиме «Подогрев». Готовый пирог переложить на блюдо и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5284,'Смешать все ингредиенты для коржа, испечь четыре штуки, добавить в один фундук, во второй – мак, в третий – чуть распаренный чернослив, в четвертый – какао. Для прослаивания приготовить два крема один масляно-кофейный, а для другого взбить сметану хорошего качества с сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5284,'Осталось только собрать торт «Роскошный сметанник» с фундуком, для этого облить пропиткой коржи и собрать все в стопку, чередуя разный крем. Верх оформить кусочками шоколада и орехами, или по своему вкусу. Десерт получится более нежным и вкусным, если постоит несколько часов, а на следующий день, если хватит выдержки, будет просто превосходным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5285,'В пышную белую массу взбить сахар и размягченное масло, а затем добавить яйца и еще раз взбить до однородности. Всыпать порциями муку, добавить погашенную соду, вымесить тесто до эластичности, разрезать на три порции, убрать на полчаса в холодильник. За это время приготовить из всех ингредиентов масляный крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5285,'Из хорошо охлажденного теста раскатать три квадрата, испечь в прогретой до 180 градусов духовке по 20 минут, края ровно подрезать и измельчить в крошку. Промазать коржи джемом (лучше брать с кислинкой) и кремом, сложить их в стопку. Готовый торт «Ленинградский» по-домашнему обмазать сверху и с боков кремом и присыпать крошкой, а верх оформить дробленым грецким орехом, дать немного постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5286,'Взбить миксером сахар с яйцом, всыпать какао перемешать, добавить муку и крахмал с разрыхлителем, вымесить сравнительно густое тесто, влить масло, молоко, еще раз тщательно вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5286,'Подготовленную и смазанную маслом форму заполнить тестом, выпекать в микроволновке при максимальной мощности около 3 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5286,'Готовый бисквит для торта «Быстрый» с какао разрезать вдоль на два коржа, пропитать взбитой сметаной с сахаром, прослоить порезанными ягодами клубники, верх торта оформить по своему вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5287,'Рыбу подготовить, обмыть, почистить, порезать на небольшие куски. Для панировки смешать соль, специи, муку, обвалять рыбу, выложить ее на глубокий противень. Нашинковать полукольцами лук, обжарить в растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5287,'Сметану перемешать с яйцами, горчицей, нашинкованным укропом, чуть подсолить, добавить обжаренный лук, перемешать, вылить в противень на рыбу, присыпать стружкой сыра, поставить в прогретую до 200 градусов духовку. Рыба с сыром в сметане, будет готова, когда появится аппетитная соломенно-золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Филе горбуши очистить от кожи, извлечь все кости, вымыть и нарезать на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Смешать лимонный сок, уксус, белый и черный перец, рубленную петрушку и укроп для приготовления маринада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'В полученный маринад положить рыбу и отставить на 15-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Чтобы приготовить кляр, нужно в охлажденное молоко добавить растительное масло, яичные желтки, все посолить, смешать с просеянной мукой, приготовить жидкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Из яичных белков сделать густую пену, постепенно добавить в кляр, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Куски рыбы обмакнуть в кляр, выложить на сковороду, жарить до образования румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5288,'Филе горбуши в кляре по-сахалински может быть подано с измельченным зеленым луком, кольцами репчатого лука, обжаренными на сковороде, томатным соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5289,'Перец очистить от семян и вместе с чесноком прокрутить на мясорубке, также поступить и с кабачками. Натереть крупно морковь и яблоко, перемешать с остальными овощами, добавить уксус, масло, рубленую зелень, измельченный горький перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5289,'Поставить аджику из кабачков с перцем вариться до загустения примерно на полтора часа, готовую приправу разложить по подготовленным 0,5 банкам, влить в каждую по чайной ложке уксуса, закрутить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5290,'Отобрать для приготовления примерно одинаковый по размеру картофель продолговатой формы, почистить его, надрезать по всей длине, чуть присолить. Нарезать тонкими ломтиками бекон, заполнить пластинками прорези, можно их дополнить сырными и грибными, а можно использовать и все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5290,'Сверху картошку-гармошку с беконом сдобрить перцем, обернуть каждый клубень фольгой, разложить на противень, поставить примерно минут на 40 в духовку. Появление непередаваемо-ароматного и хорошо узнаваемого дурманящего запаха будет сигнализировать о готовности полезного и сытного блюда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5291,'Для быстрого приготовления вареной сгущенки перелить ее в стеклянную емкость, но можно использовать и керамическую, на пару минут поставить в микроволновку с мощностью 700 Вт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5291,'Вынуть, перемешать, еще на пару минут поставить в печку, не меняя мощности. Этот прием не даст сгущенки «сбежать». Так повторить 4 раза, т.е. варка займет примерно 8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5291,'Все, вареная сгущенка на скорую руку– готова, можно просто есть, намазав на хлеб, или использовать для прослойки печенья, торта или пирожных.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5292,'Насыпать в глубокую миску сахар, муку, какао, влить, размешивая частями молоко (не должно быть комков). Когда все молоко будет использовано перелить все в сотейник с толстым дном, поставить на  плиту, дать закипеть при непрерывном помешивании, иначе может пригореть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5292,'Блендером мелко раздробить орехи, смешать с маслом, чуть подсолить, хорошо перемешать, высыпать к содержимому сотейника, перемешать, варить при помешивании пока смесь не загустеет. Дать пасте «Nutella» с лесным орехом остыть, разложить по баночкам с крышками, поставить на хранение в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5293,'Покупные огурцы замочить на пару часов в холодно воде, обрезать концы, заполнить, как можно плотнее, подготовленную трехлитровку, добавить зубки чеснока и зелень, всыпать порошок горчицы (она предотвратит брожение рассола) и соль, аккуратно залить крутым кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5293,'Закупорить соленые огурцы на зиму капроновой или металлической крышкой, дать постоять в комнате пару недель, убрать в холодильник, но можно хранить и в комнате. Для получения вкуса малосольных огурцов банки оставить в комнате всего на несколько дне, а потом уже убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5294,'Порезать лимоны на тонкие дольки, заполнить ими банку, залить хорошим медом, положить немного свежего корня имбиря. Банку плотно закрыть, убрать для «созревания» на пару-тройку месяцев в холодильник. Лимон с медом от боли в горле можно считать готовым, когда содержимое банки станет напоминать жидкое желе, влить ложку теплой воды, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5295,'Очистить морковку, крупно натереть, также поступить с сыром, колбасу нарезать тонкой соломкой. Добавить в салат с полукопченой колбасой отцеженную кукурузу, раздавленные зубки чеснока, приправить майонезом, перемешать. Салат можно не солить, т.к. колбаса, сыр и майонез содержат достаточно соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5296,'В достаточно глубокую миску всыпать сахар, добавить маргарин, масло, взбить миксером, установив его на большую скорость, добавить яйцо, взбить, положить майонез, еще раз хорошо взбить, влить гашеную соду, перемешать. Всыпать, перемешивая небольшими порциями муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5296,'Заполнить тестом, размазывая его по стенкам и дну, подготовленные формочки, запечь до появления золотистого цвета, температуру выше 190 градусов не поднимать. Готовые корзиночки осторожно извлечь из формочек и наполнить густым джемом, а сверху украсить белковым кремом, оформить цветной присыпкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5297,'Порезать мелко луковицу, положить в куриный фарш. Натереть кабачок, порезать перец, положить в фарш. Посыпать перцем, солью. Вбить яйцо. Размешать. Порезать шампиньоны на тоненькие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5297,'Обжарить грибочки, на каждый сразу положить столовую ложку фарша. Обжарить с двух сторон. К столу подавать куриные котлетки с овощами вверх грибами. Украсить веточкой зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'На кружочки баклажанов выложить кружочки помидоров, поперчить и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5298,'Взбить сахар и маргарин, вбить по очереди яйца, положить остальные ингредиенты, кроме какао и вишни. Слить с вишни сок в отдельную емкость, он пригодится позже. Разделить тесто на две части, одну часть положить в круглую формочку 26 сантиметров диаметром. Во второй кусок теста положить какао, вымешать, положить на белое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5298,'Сверху выложить ягоды вишни. Поместить в духовку, готовить 45 минут, соблюдая температуру 180 градусов. Взбить холодные сливки, загуститель сливок, ванилин и сахар, чтобы получились устойчивые пики, положить кварк, вымешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5298,'Достать из формочки остывший корж, надеть съемную формочку, сверху положить творожную смесь, выровнять, отправить на несколько часов в холодильник. Приготовить желе: соединить фруктовое желе для торта, сахар, вишневый сок, если его мало, то долить воду. Сварить желе и налить на торт, поставить торт «Красная шапочка» в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5299,'Отварить до готовности филе курицы, порезать тонкими брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5299,'Помидоры нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5299,'Для приготовления заправки смешать соевый соус, майонез и натуральный йогурт, добавить измельченный чеснок и плавленый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5299,'В центр плоской посуды выложить заправку, по кругу разложить филе, помидоры и абрикосы в виде лепестков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5299,'Посыпается салат «Новогодняя гербера» нашинкованным зеленым луком, натертым сыром, перед подачей охлаждается.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5300,'Приготовить начинку: порезать луковицу на кубики, потереть морковь, обжарить. Залить булку молоком, хорошо отжать. Положить все продукты в блендер, посыпать перцем, солью. Измельчить. Вынуть из рыбки хребет, посыпать солью, перцем. Положить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5300,'Сколоть брюхо зубочистками. Переложить щуку на фольгу, посыпать приправами, полить вином. Завернуть рыбу в фольгу, отправить в духовку. Готовить 35 минут, соблюдая температуру 185 градусов. Вынуть фаршированную щуку со свининой из фольги, порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5301,'Порезать колбасу на мелкие кубики. Обжарить несколько минут на небольшом огне. Порезать помидоры и положить к колбасе. Готовить еще 60 секунд. Измельчить петрушку положить в сковороду, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5301,'Разбить в посуду яйца, налить молоко, насыпать перец, соль. Размешать вилкой. Вылить смесь в сковороду, помешивать лопаткой. Яйца схватятся за минуту. Обжарить в тостере несколько кусочков хлеба, выложить яичницу, получается вкусная яичница на тостах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5302,'Приготовить опару: развести дрожжи в теплом молоке, насыпать сахар, муку. Отставить опару на пятнадцать минут. Соединить муку с желтками и мягким маргарином. Размешать, посыпать сахаром, солью. Положить разрыхлитель и опару. Замесить тесто, накрыть полотенцем и отставить на полчаса. Оно не поднимется сильно, но станет чуть-чуть рыхлым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5302,'Поделить тесто на четыре части, раскатать прямоугольник, намазать любой начинкой, например, готовым маком, который сейчас продается. Если такой начинки нет, то можно приготовить ее: насыпать мак в молоко и дать закипеть. Охладить, насыпать сахар или положить варенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5302,'Можно сделать банники с ореховой начинкой: намазать джемом и посыпать грецкими или любыми другими орехами. Сложить прямоугольники, защипнуть края. Отложить на тридцать минут. Затем поставить банники с маком из песочного теста на двадцать минут в духовку, готовить при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5303,'Порубить петрушку и чеснок, настругать цедру лимона, перемешать все, посыпать солью. Вырезать у рульки косточку, разрезать, чтобы получился кусок мяса одинаковый по толщине. Выложить равномерно приготовленную смесь на мясо, свернуть рулетик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5303,'Перевязать нитью. Запекать рульку в рукаве, 120 минут, соблюдая температуру 200 градусов. Тонко порезать запеченную свиную рульку с лимоном на тарелке. Подавать с хреном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5304,'Взять готовые булочки и начинить грибочками (или чем-то другим). Выпотрошенные булочки намазать смесью из оливкового масла и зубчика чеснока. Выпекать при 200 градусах, пока не подрумянятся. Затем наполнить грибочками. Хрустящие булочки с грибами готовы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5491,'Обработать кальмары: снять кожицу, удалить внутренности, почистить щеткой. Варить в кипящей подсоленной воде в течение 1 – 3 минут, время варки зависит от величины тушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5305,'Вымыть печень, порезать, измельчить в блендере или через мясорубку. Положить фарш в емкость, налить молоко, вбить яйца, насыпать муку, соду, посыпать перцем, солью. Перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5305,'Налить оливковое масло на сковороду, поставить на маленький огонь. Столовой ложкой выложить печеночную смесь на сковороду. Обжарить оладушки и переложить на салфетки, чтобы стек жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5305,'Приготовить соус: измельчить зелень и чеснок. Смешать их в посуде, добавить сметану. Остудить оладьи, соединить по два, смазав между ними соусом. Положить печеночные оладьи со сметаной на тарелку, украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5306,'Разрезать куриные грудки на две части поперек. Каждую часть чуть-чуть отбить через пленку. Посыпать перцем и солью, в центр положить по кусочку масла, и немного измельченного укропа. Сложить каждую отбитую грудку пополам, придать красивую ровненькую форму, поправить края.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5306,'Разбить в одну емкость яйцо и чуть-чуть взбить его, во вторую насыпать муку, в третью посуду насыпать панировочные сухарики. Сначала обмакнуть отбивную в муке, сгладить все неровности. Далее окунуть в яйцо. В последнюю очередь обвалять в сухариках, хорошенько запанировать, придавливая руками и придавая идеально ровную форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5306,'Разогреть растительное или топленое масло на сковороде, обжарить отбивные «Куриное гадание» из филе на среднем огне до золотистого цвета с обеих сторон. Подавать блюдо горячим, пока корочка еще хрустящая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5307,'Убрать с печени пленку, если она имеется. Измельчить лук, петрушку и чеснок. Сначала порубить все по отдельности, потом смешать и еще раз порубить. Посолить персияд, чтобы соль измельчила приправу. Печень порезать на кусочки по 1 сантиметру толщиной. Растопить масло на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5307,'Положить печень, обжарить с одной стороны минуты две. Посыпать куски печени солью, перцем, перевернуть, вновь поперчить и посолить. Положить приправу из лука, чеснока и петрушки. Налить воду. Готовить говяжью печень с приправой персияд минуты три, жидкость должна стать насыщенным соусом, а печень в середине порозоветь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5308,'Отварить картофель в кожуре. Очистить луковицу, порезать полукольцами, а их еще пополам. Обжарить на масле. Грибы порезать на пластинки. Положить к луку, размешать, жарить минут двадцать. Посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5308,'Почистить картофель, порезать кружками. Моцареллу порезать тоненькими маленькими пластинами. Твердый сыр крупно потереть. Приготовить заливку: соединить сливки, яйца и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5308,'Сформировать запеканку: смазать формочку (25 на 25 сантиметров) маслом. Положить сначала грибы с луком, потом моцареллу. Сверху картофель, посыпать солью, перцем. Вылить равномерно заливку, посыпать сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5308,'Поставить запеканка из картофеля с двумя видами сыра в духовку, готовить 25 минут, соблюдая температуру 180 градусов. Сыр должен расплавиться, а заливка схватиться. Кушать сразу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5309,'Яичные блинчики придадут салатику довольно интересный вкус. Можно использовать как отварное мясо курицы, так и окорочок, копченое филе. Чтобы салатик стал более легким, можно добавить свежий огурец. Получается приблизительно семь порций. Отварить филе курицы до готовности. Охладить и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5309,'Мелко порезать луковицу, положить в кипяток, отставить минут на десять. Слить воду, помыть лук холодной водой, чтобы он не был горьким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5309,'Взбить яйца (по отдельности), чуть-чуть посыпать солью. Пожарить на растительном масле с двух сторон. Остудить блинчики, порезать соломкой. Соединить блинчики, мясо, лук, посыпать солью. Заправить салат «Нежность» с куриным филе майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5310,'Замесить тесто из всех ингредиентов, как очень густая сметанка. Тогда оладушки получатся пышными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5311,'Приготовить соус Цезарь: взбить чуть-чуть яйцо, положить горчицу, сок лимона, добавить растительное и оливковое масло, вустерский соус, пять филе анчоусов, посыпать перцем и солью. Размешать. Приготовить филе курицы: вымыть мясо, обсушить, положить в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5483,'Смешать посеянную пшеничную муку, мягкое сливочное масло, сахар, творог, сырые яйца, гашеную соду. Массу выпекать в высокой форме в течение часа. Для украшения сварить глазурь из растопленного шоколада и сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5311,'Посыпать перцем, солью, добавить масло, сок лимона, мед. Размешать, чтобы смесь покрыла мясо. Поставить на час в холод. Достать мясо из маринада, посушить. Нагреть масло, обжаривать филе с одной стороны до румяного цвета. Перевернуть, готовить еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5311,'Положить филе на противень, готовить минут десять, соблюдая температуру 175 градусов. Достать, остудить, тоненько порезать. Приготовить гренки: порезать чеснок, соединить с маслом. Отставить часа на три. Порезать хлеб на кусочки. Процедить масло с чесноком, нагреть на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5311,'Обжарить хлеб, выложить на лист для выпечки, посыпать солью и приправами. Поместить на пару минут в духовку. Салатные листья опустить на 60 минут в холодную воду. Вынуть, просушить полотенцем. Листья станут более хрустящими. Порвать салат на куски, сложить в емкость, налить приготовленный соус, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5311,'Перед подачей на стол разрезать пополам чеснок, натереть им тарелку. Положить на нее листья, чтобы не было видно дно. Положить сверху красиво порезанное филе курицы, посыпать гренками и сыром. Сбрызнуть салат «Цезарь» с куриным филе соусом, украсить помидорами черри. Кушать сразу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5312,'Размять консервы вилкой, измельчить лук и отдельно крабовые палочки, натереть сыр, отдельно размять вилкой желтки и белки. Выложить слои в следующей последовательности: сначала консервы, лук, майонез, сыр. Затем кукурузу, майонез, крабовые палочки, опять майонез, белки майонезом. Посыпать слоеный ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5313,'Порезать лук на кубики, пассировать на масле. Порезать печень на две-три части, положить к луку, жарить минут семь, помешивая. Переложить печень в формочку, посыпать перцем, солью, измельченной зеленью и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5313,'Порезать помидоры на кубики, положить на печень, посыпать сыром, поставить в духовку. Готовить куриную печень по-милански, пока не расплавится сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5314,'Перемешать темное или светлое пиво, оливковое масло, сахарный песок или патоку, соль, стакан муки, сухие дрожжи и тертый сыр пармезан или российский. Тесто должно получиться эластичным, можно воспользоваться миксером. Накрыть емкость с массой полотенцем, дать постоять в течение двух часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5314,'Обмять тесто, разделить на десять одинаковых частей. Каждую часть раскатать «колбаской» длиной 40 см, сложить пополам, скрутить и соединить концы. Должен получиться «плетеный» крендель. Дать постоять в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5314,'Довести до кипения четыре литра воды в большой кастрюле, варить бейглы по две-три штуки одновременно в кипящей воде. Крендели должны увеличиться в объеме. Застелить пекарской бумагой противень, вынуть и выложить бейглы с сыром пармезан шумовкой, посыпать морской солью крупного помола и «чернушкой»-кецах. Печь в течение 17 – 20 минут при температуре 250 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Говяжье филе очистить от костей, нарезать некрупными кусочками продолговатой формы, из костей сварить бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Полученный бульон перелить в горшочек, закинуть сырое мясо, поставить в духовку, разогретую до 150-200 градусов, на 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Очищенный и промытый картофель порезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Лук очистить, нашинковать полукольцами, жарить на хорошо разогретом сливочном масле пока не подрумянится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Из духовки достать горшочек, добавить картофель, поставить на плиту на слабый огонь и поварить 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Затем добавить обжаренный лук, лавровый лист, рубленую зелень и варить до готовности несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5315,'Русская похлебка с говядиной подается с черным хлебом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5316,'Пекинскую капусту разобрать на отдельные листья, опустить на минуту в горячую воду. Вынуть, остудить, острым ножом аккуратно срезать утолщения. Рис промыть и сварить рассыпчатую кашу. Обжарить очищенный арахис, измельчить. Смешать эти два ингредиента, добавить консервированную кукурузу без жидкости, рубленый зеленый укроп. Соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5330,'Когда мясо замаринуется, посыпать разными специями и травами, перцами. Положить свинину в рукав для выпекания, положить в сковороду, отправить в духовку. Готовить минут 80, соблюдая температуру 190 градусов. Готовность буженины из свинины в рукаве проверять зубочисткой, мясо должно стать мягкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5316,'На готовые листья капусты выложить по столовой ложке рисово-ореховой начинки, плотно завернуть. Обжарить «конверты» с двух сторон на смазанном растительным маслом гриле или на обычной сковороде. Прогревать до готовности или до полуготовности, во втором случае голубцы из пекинской капусты допечь в течение 15 минут при 170 градусах на противне в духовке, перед выпечкой блюдо полить «полосками» небольшим количеством кетчупа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5317,'Нарубить репчатый лук, обжарить на растительном масле. Добавить сладкий болгарский перец, нарезанный соломкой, когда он станет мягче – добавить размороженные лисички. Жарить на среднем огне в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5317,'Пекинскую капусту нашинковать и перетереть её с солью руками. Всыпать в сковороду с обжаркой, прогреть до мягкости. Добавить сметану, размороженный зеленый горошек, соль и перец – по вкусу. Огонь убавить, накрыть сковороду крышкой, тушить 15 минут. В конце приготовления в рагу из пекинской капусты добавить тертый твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5318,'Отварить клубни картофеля в «мундире» и морковь. Запечь свёклу в фольге в духовом шкафу. Все овощи остудить и очистить, нарезать брусочками. Отварить в кипящей подсоленной воде мороженый зеленый горошек, через 5 – 7 минут обдать холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5318,'Мелко нарезать репчатый лук, кубиками, мелко порубить чеснок. Маринованные грузди или опята нарезать в виде тонких полосок. Все ингредиенты перемешать. Для заправки смешать сметану и не острую горчицу, посолить при необходимости. Залить смесью салат с грибами и овощами, поставить в холодное место на час-полтора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5319,'Отварить куриную грудку. Нарезать репчатый лук и чеснок, обжарить на смеси сливочного и растительного масла. Все продукты измельчить в блендере, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5320,'Замесить тесто из пшеничной просеянной муки, яиц, теплого молока, мягкого, нарезанного кусочками, сливочного масла, сахарного песка, сухих дрожжей. Соль – по вкусу. Замесить тесто и дать подойти, масса должна быть мягкой и эластичной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5320,'Разделить тесто на две части, слепить «туловище» и «лапки», выложить начинку из капусты с яйцами. Взять пельменницу, посыпать мукой и прокатать лепешку из теста. Смазать получившиеся пятиугольники водой с одной стороны и налепить на «черепаху». «Глаза» сделать из гвоздик, в районе рта сделать надрез и вставить кусочек свернутой фольги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5320,'Дать «черепахам» постоять в течение 20 минут под хлопчатобумажной тканью. Смазать льезоном, смесью яйца с молоком, печь до румяной корочки при температуре 180 градусов. При готовности пироги «Черепахи» с капустой накрыть полотенцем и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5321,'Отварить куриное мясо, порезать соломкой. Крутые куриные яйца и свежий огурец также порезать соломкой. Натереть твердый сыр «Российский» или «Пармезан», спелые помидоры нарезать кубиками. Выложить на блюдо курицу, яйца и огурцы, слои по вкусу промазать майонезом. Сверху на салат «Золотой розан» насыпать сыр и помидоры, сделать сеточку из майонеза и розу из помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5322,'Смешать говяжий и свиной фарш, последний можно заменить индейкой. Добавить хлебную крошку или панировочные сухари, соль и молотый перец, рубленую зелень петрушки и чеснок. Отдельно взбить яйцо и добавить в фарш, перемешать. Сформовать небольшие фрикадельки, выпечь в смазанной маслом форме для выпечки в течение 20 – 30 минут при температуре 180 градусов, до образования румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5322,'Натереть сыр пармезан. Отварить любую пасту для супа до полуготовности, воду слить. Готовый, насыщенный куриный бульон довести до кипения в большой емкости. Всыпать свежий рубленый шпинат, варить в течение пяти минут. Положить фрикадельки и пасту, прогревать на огне до готовности. Подать свадебный итальянский суп с тертым пармезаном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5323,'Баклажаны очистить и нарезать вдоль плода ломтиками толщиной от полсантиметра до двух сантиметров. Выложить в подсоленную воду и оставить для удаления горечи на полчаса. Измельчить зелень укропа, нарезать тонкими ломтиками помидоры. Отдельно взбить вилкой сырые куриные яйца. Порубить чеснок и смешать с укропом, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5359,'Положить киви в формочки, сверху вылить сок, вставить палочку и отправить фруктовый лед с киви в морозилку на ночь или хотя бы на шесть часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5323,'Баклажаны обсушить с помощью бумажных полотенец, обмакнуть во взбитое яйцо. Обжарить с двух сторон до золотистого цвета. Положить на каждый ломтик по кружочку помидора, по чайной ложке чесночно-укропной массы, завернуть рулетами. Готовую закуску накрыть пищевой пленкой, дать полежать в холодильнике в течение часа или больше. Подавать рулетики «Хит осени»к столу в охлажденном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5324,'Замесить тесто из муки, воды, меда, макового семени, подсолнечного масла. Слепить пять «колобков», тонко раскатать каждый по величине сковороды. Края ровно обрезать с помощью тарелки. Обжарить полученные лепешки на растительном масле  двух сторон. Выпечку сложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5324,'Запарить мак кипятком, растереть в кашицу. Добавить немного воды и нагреть смесь до кипения. Влить мед, перемешать. Лепешки промазать полученной массой и снова сложить друг на друга, как торт. Верх смазать медом. Шуги можно украсить сверху маком, дать блюду постоять для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5325,'Фасоль предварительно замочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5325,'В кастрюлю с холодной водой сложить свинину, нарезанную некрупными кусочками, вымоченную фасоль, варить до готовности фасоли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5325,'Всыпать ячневую крупу и варить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5325,'В суп добавить капусту, когда он закипит положить растертый с солью чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5325,'Щи из ячневой крупы, тушеной капусты и фасоли со свининой заправить сметаной и зеленью, подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5326,'Для приготовления теста взбить сырое яйцо вилкой, влить воду и растительное масло, перемешать. В емкость всыпать просеянную пшеничную муку, соль, сделать углубление, влить яичную смесь. Замесить мягкое тесто, оно не должно липнуть к рукам. Оставить для набухания, накрыть миской.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5326,'Для начинки очистить от кожицы и семян яблоки, нарезать тонкими ломтиками. Залить горячей водой сухофрукты на несколько минут, вымыть, обсушить с помощью бумажных полотенец. Вяленую вишню можно заменить изюмом без косточек. Курагу и чернослив нарезать крупными кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5326,'Растопить на сковороде сливочное масло, добавить сахарный песок, специи, влить коньяк, положить яблоки и сухофрукты, перемешать. Смесь прогреть на тихом огне до выпаривания жидкости, яблоки должны стать мягкими. Остудить. Порубить грецкие орехи на крупные кусочки с помощью скалки и пакета или ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5326,'На стол постелить полотенце, присыпать мукой. Очень тонко раскатать тесто в виде большой лепешки прямоугольной формы. Выложить начинку, размазать, оставить свободным верхний край. Посыпать орехами. Свернуть тесто рулетом при помощи ткани, бока загнуть, оставшийся свободный край смазать растопленным сливочным маслом, залепить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5326,'Выложить рулет на смазанный сливочным маслом противень, «шов» должен оказаться внизу. Посыпать лепестками миндаля и смазать сливочным маслом. Печь при 180 градусах в течение 40 минут.  Горячую выпечку снова смазать сливочным маслом и посыпать сахарной пудрой. Яблочный штрудель с клюквой и сухофруктами нарезать и подать в теплом виде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5327,'Измельчить курицу, посолить, приправить по вкусу, обжарить до готовности. Чтобы мясо получилось сочным, его нужно не пережарить. Положить в одну емкость измельченные помидоры, огурцы и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5327,'Отдельно смешать майонез со сметанкой. Свернуть трубочкой лаваш. Овощи смешать с соусом. Начинить ими рулетик из лаваша, обжарить – получается домашняя шаурма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5328,'Все перемешать. Желательно пить перед сном и утром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5329,'Погасить 1/2 ложки горчицы бальзамическим уксусом, добавить оливковое масло. Положить листья шпината, размешать. Пополам порезать помидоры черри, бросить почищенные креветки. Полить салат из шпината и креветок соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5330,'Приготовить маринад: налить воду в кастрюльку. Положить соль (в соотношении столовая ложка на литр воды), перец горошком, лавровый лист. Можно посыпать любыми приправами, например, кориандром, гвоздикой. Довести маринад до кипения, варить минут семь. Остудить. Опустить свинину в маринад, поставить в холод минимум на четыре часа, лучше на 24.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5376,'Покрошить хлеб на маленькие кусочки, вбить яйца, бросить колбаску, порезанную на кубики, посыпать солью, перцем, размешать, измельчая ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5331,'Потереть крупно зеленую редьку или дайкон на терке. Посыпать солью, подождать, пока редька пустит сок, чуть-чуть отжать, вылить сок. Так редька станет не горькой. Порезать лук соломкой, чуть-чуть обжарить. Охладить, положить к редьке. Поделить отварное мясо на тоненькие волокна. Размешать яйца с водой, обжарить тоненькие блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5331,'Охладить, порезать лапшой. Соединить все компоненты салата. Потереть маленький кусок тыквы или моркови, чтобы салатик приобрел вкус и цвет. Можно этот ингредиент не класть. Заправить салат майонезом, посыпать перцем, солью, зеленью. Поставить мясной салат «Загадка» на тридцать минут в холодильник, чтобы он пропитался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5332,'Положить картофель в кастрюлю, налить воду. Посыпать солью, довести до кипения. Сделать меньше огонь, варить приблизительно минут пятнадцать. Важно не переварить. Слить воду, отправить в холодильник для остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5332,'Растопить сливочное масло на сковороде. Обжаривать отварной холодный картофель минут десять, периодически переворачивая. Выложить картофель на блюдо. Смешать масло с измельченной зеленью, смазать румяный картофель. По вкусу посыпать перцем и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5333,'Положить бедрышки на противень, посолить, поперчить. Полить сверху растительным маслом и хорошо растереть. Поставить на 40 минут в духовку, вытаскивать, когда начнет подрумяниваться корочка. Достать, накрыть фольгой. Отдельно смешать апельсиновый сок с медом, добавить измельченный чеснок, дать минут семь настояться. Вылить соус на курицу и отправить снова в духовку, готовить до золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5333,'Готовые бедрышки накрыть фольгой, чтобы мясо было нежным. Приготовить хашбраун: натереть мелко картофель, выложить на горячую сковороду. Придать любую форму и обжарить с двух сторон. Посыпать перцем и солью. Куриные бедра и хрустящий хашбраун готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5334,'Порезать лук полукольцами, а помидоры кружками. Приготовить маринад: измельчить чеснок, перемешать все продукты. Для маринования закуски использовать специальный контейнер или любую удобную',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5334,'емкость. Выложить слой помидоров и лука. Залить закуску из помидоров острым маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5335,'Порезать мясо небольшими пластами. Каждый пласт отбить специальным молоточком, чтобы мясо было более мягким и нежным. Порезать на кусочки фольгу, на каждый положить по пласту мяса. Хорошенько посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5335,'Намазать сметаной. Посыпать пряностями и специями. Крупно потереть сыр, посыпать кусочки мяса, смазанные сметаной. Завернуть осторожно мясо в фольгу, чтобы не вытек сок. Готовить в духовке минут шестьдесят.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5335,'Минут за пять до конца готовки мяса, достать противень и раскрыть фольгу, вновь поставить мясо в духовку. Блюдо станет более привлекательное внешне, сыр чуть-чуть поджарится. Ведь в закрытой фольге мясо только тушится, а сыр плавится. Выложить телятину с сыром из фольги на блюдо, украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5336,'Взбить яйца и сметану. Положить сахар и маргарин. Отдельно соединить соль, соду и муку, высыпать в смесь. Замесить тесто, отставить на пятнадцать минут. Если тесто очень мягкое, то раскатать его с мукой или насыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5336,'Поделить тесто на булочки и раскатать лепешки. Разогреть сковороду, готовить сметанные лепешки под крышкой. Перевернуть и готовить без крышки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5337,'Выложить слоями: консервированную горбушу, размятую вилкой, обжаренный лук, грибы. Крупно натертые вареные яйца, смешанные с измельченным чесноком. Обжаренную морковь. Все слои салата из горбуши пропитать майонезом. Посыпать измельченными желтками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5338,'Отделить белки от желтков. Взбить желтки с сахаром до воздушной массы. Налить молоко, кипяток, положить растопленное масло и горький шоколад, ванилин. Размешать, насыпать муку, соль, разрыхлитель, соду, какао-порошок. Отдельно взбить белки с солью до воздушных пиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5338,'Осторожно ввести в тесто. Размешать, чтобы получилась однородная смесь. Круглую формочку застелить специальной бумагой, намазать сливочным маслом, присыпать слегка мукой. Нагреть до 180 градусов духовкой. Перелить в формочку тесто, готовить минут сорок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6543,'Помыть и отварить картофель в мундире, облить холодной водой (тогда легче чистить), остудить, очистить, нарезать на мелкие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5338,'После остывания разрезать пирог на три одинаковых коржа. Приготовить начинку: размять бананы, налить ром, добавить растопленный шоколад. Хорошо взбить сливки, положить к бананам. Смазать каждый корж начинкой и обмазать всю поверхность шоколадного бисквита снаружи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5339,'Замочить желатин в горячей воде. Пропорции написаны на упаковке. Если желатин не растворился полностью, то процедить через марлю. Насыпать в воду сахар, размешивать, пока не растворится сахар. Остудить до комнатной температуры. Добавить раствор в сметану, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5339,'На дно емкости для желе, к примеру, бокалы положить зерна граната, налить желейную смесь. Поставить на несколько часов в холодильник. Насыпать еще гранатовые зерна и поставить снова в холодильник, желательно на ночь. Остывшее желе из сметаны посыпать зернами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5340,'Отварить, остудить и почистить картофель, потереть. Крупно потереть морковь, порезать лук полукольцами. Обжарить его с морковью. Порезать мелко колбасу. Отварить, охладить, почистить и порезать пополам яйца. Отделить желтки и белки. Растереть майонез с чесноком, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5340,'Нафаршировать смесью белки. Мелко потереть сыр. Уложить слои: картофель, налить майонез, морковь и лук, колбаска, майонез, положить срезом вниз фаршированные яйца. Намазать салат «Сугробы» с колбасой майонезом, посыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'На стол просеять муку горкой, в середине сделать ямку и вбить туда яйцо, добавить теплую воду, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'Вымесить крутое тесто, накрыть и отставить на 40 минут, потом раскатать его в тонкий жгут, порезать на равные части, которые раскатать в тонкие кружки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'Вымоченные грибы положить в кастрюлю с водой и посолить, отварить, мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'Мелко нашинкованный лук обжарить с отваренными грибами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'Сварить картофель, растолочь и смешать с грибами, луком, посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'На масле обжарить до легкого золотистого цвета муку для соуса, добавить томатную пасту, обжарить 5-7 минут, затем положить сметану, дать соусу закипеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'На половинку каждого кружка теста выложить фарш, свернуть тесто пополам, сформовать вареники.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'В кипящую воду добавит соль и опустить вареники, отварит до полуготовности, потом переложить их в горшочки, полить соусом, верх посыпать тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5341,'Вареники с сыром по-ярославски запечь до готовности в горшочках в духовке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5342,'Приготовить тесто «День»: растереть сахар с желтками, положит сметану, насыпать муку и пекарский порошок. Взбить, перелить в формочку, приготовить корж. Охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5342,'Приготовить тесто «Ночь»: густо взбить сахар с белками, положить сметану, измельченные орехи. Насыпать муку, какао, разрыхлитель, пекарский порошок. Приготовить в духовке корж, охладить. Разрезать коржи пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5342,'Сделать сметанный крем: взбить сметанку и сахар, поделить на две части, в одну положить чуть-чуть какао. Складывать коржики друг на друга, чередуя темный и светлый, смазывая кремом. Сверху положить белый. Намазать кремом, посыпать торт «День и ночь» тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5343,'Положить сливочное масло в морозильную камеру. Помыть цветную капусту, поделить на соцветия. Вскипятить воду, подсолить. Бланшировать соцветия минут шесть, залить холодной водой, подождать, пока вода стечет. Потолочь в ступке тмин с белым перцем. Можно использовать готовые молотые специи, но растертые специи будут ароматней.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5343,'Насыпать муку в глубокую емкость, перемешать с солью, предварительно растертыми приправами. Во второй емкости взболтать и чуть-чуть посыпать солью яйца. В третью емкость насыпать сухари. Сначала обвалять соцветия капусты в муке, опустить в яйцо, в последнюю очередь в сухариках.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5343,'Намазать формочку жиром, положить цветную капусту. Натереть холодное сливочное масло. Поставить на двадцать пять минут в духовку. Готовить, соблюдая температуру 190 градусов. Приготовить соус: смешать сливки с прессованным чесноком, перцем, солью, измельченной зеленью. Полить соусом блюдо. Выложить цветную капусту с чесночно-сметанным соусом на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'В миске очень тщательно с помощью венчика смешать кефир, муку, яйцо, соду и сахар для светлого коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5344,'Довести до кипения бальзамический уксус, кипятить, пока он не станет, как густой соус (приблизительно минут пятнадцать). Перелить получившийся соус в чашку с узеньким горлышком. Отставить на время, чтобы он загустел сильней. Порезать моцареллу и помидорки на одинаковые кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5344,'Выложить на блюдо помидоры, потом сыр, помидоры, снова сыр и так далее. Между слоями положить листики базилика. Тоненькой струйкой налить оливковое масло, бальзамический соус. Посыпать перцем, солью. Подавать салат «Капрезе» сразу. Соус, который остался, можно подать к любому салату или мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5345,'Нагреть масло и кефир до теплого состояния. Насыпать соль, сахар, размешать. Соединить муку и дрожжи (мука должна быть просеянной), высыпать в смесь. Если дрожжи не быстродействующие, то их необходимо предварительно развести в теплой воде и сахаре минут на пятнадцать. Или применить грамм сорок свежих дрожжей, насыпать их в кефир и масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5345,'Замесить тесто, отставить минут на тридцать, чтобы подошло. Сформировать пирожки, положить начинку, отставить, чтобы подошли. В это время разогреть духовку. Смазать пирожки желтком, отправить в духовку. Готовить пирожки «Как пух» с любой начинкой минут двадцать, соблюдая температуру двести градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5346,'Отварить яйца и мясо. Отварное мясо порезать кубиками, переложить в емкость небольшим слоем, намазать майонезом, посыпать маринованным луком, порезанным кубиками. Вареные яйца порезать на мелкие кубики, посыпать маринованным луком, намазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5346,'Крупно потереть сыр, посыпать луком, намазать майонезом. Чтобы замариновать лук, необходимо порезать луковицу и положить в полулитровую баночку. Посыпать душистым перцем, добавить гвоздику, уксус, налить воду, чтобы баночка была заполнена. Отставить часов на десять. Салат «Мужской каприз» с мясом украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5347,'Тоненько нашинковать капусту, посыпать солью, чуть-чуть перемять. Порвать салат на куски. Порезать яблоко тоненькой соломкой. Куски сельди порезать на три кусочка вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5347,'Приготовить заправку: соединить все ингредиенты, заправить салатик. Посыпать перцем, измельченной зеленью, размешать. Желательно салату с капустой и сельдью дать настояться минут двадцать в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5348,'Соединить дрожжи, теплое молоко, сахар, перемешать. Насыпать муку, размешать, минут на тридцать поставить в тепло для поднятия теста. Вбить яйцо в тесто, посыпать солью, положить растительное масло, размешать, отправить в тепло еще минут на двадцать. Смазать маслом раскаленную сковороду, положить один оладушек, жарить дрожжевые оладьи до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5349,'Помыть и подсушить овощи. Порезать на колесики по одному сантиметру. Приготовить соус: смешать сметану с измельченным чесноком и зеленью. Насыпать дробленные грецкие орехи, размешать. Обжарить овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5349,'Выложить друг на друга, все слои промазать соусом. Полить овощные столбики соусом, посыпать дробленными грецкими орешками, закрепить шпажкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5350,'Воду в кастрюльке довести до кипения, огонь сделать на минимум, положить масло и соль. Насыпать муку, перемешивать деревянной лопаткой, пока смесь не перестанет прилипать к стенкам. Тесто чуть-чуть охладить. Вбить яйцо, размешать. Так добавлять по одному яйцу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5350,'Разогреть духовку до двухсот градусов. Противень застелить пергаментом, чайной ложечкой выложить тесто. Готовить минут тридцать, соблюдая температуру 200 градусов. Далее сделать температуру 180 градусов и готовить до румяного цвета. В период готовки духовку не открывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5350,'Когда пирожные приготовятся, минут десять дать постоять в духовке, потом открыть ее и оставить еще минут на десять. Растопить шоколад и намазать им пирожные, можно взять шоколадную пасту, например, Нутеллу. Получаются вкусные заварные пирожные в шоколаде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5351,'Рыбное филе с кожей порезать порционными кусками, лук нарезать полукольцами, все выложить в глубокую сковородку: рыба, лук, рыба, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5351,'Залить рыбу на треть молоком, добавить перец горошком, масло, припускать около 20-25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5351,'Рыба в молоке по-старорусски подается с отварным картофелем и соусом, в котором готовилась.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10620,'Свинину положить в кипящую воду, варить два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5352,'Взбить сахар и желтки до белого цвета. Отдельно взбить белки, добавив соль, до образования густой пены. Добавить гашеную соду. Медленно соединить белки и желтки, насыпать осторожно какао и муку. Размешать до однородности, но тесто должно остаться воздушным. Взять формочку 24 сантиметра, положить тесто. Готовить минут тридцать, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5352,'Остудить, поделить на три коржа. Приготовить крем: соединить какао и сгущенное молоко, положить сливочное масло. Размешать. Корж намазать кремом, украсить тертым шоколадом, посыпать какао или шоколадной глазурью. Убрать шоколадный торт в холодильник, чтобы застыл крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5353,'Почистить кабачки и баклажаны, порезать кольцами, чуть-чуть обжарить на оливковом масле. Снять с помидоров шкурку, порезать колечками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5353,'Формочку смазать маслом. Положить овощные кольца «черепицей». Посыпать перцем, солью, сушеными травами, например, петрушкой, базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5353,'Взбить яйцо и молоко, положить мелко натертый козий сыр, размешать. Вместо козьего сыра можно взять сулугуни. Залить овощи сырно-молочной смесью, поставить диетическую овощную запеканку на 25 минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5354,'Мелко порезать капусту, положить в кастрюльку, налить воду. Закипятить, готовить минут тридцать. Слить воду, но не всю. Растопить сливочное масло, лук обжарить с чесноком до мягкости. Налить сливки, насыпать пармезан. Размешать, довести до кипения. Подержать минуту, снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5354,'Взбить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5354,'Отварить минут пять горошек. Отварить пасту, как сказано в инструкции, до состояния аль денте. Соединить горошек, соус и пасту. Размешать, поставить на огонь. Посыпать измельченной петрушкой и натертым сыром. Приготовить креветки: вымыть, очистить. Соединить приправы, обвалять в них креветки. Нагреть оливковое масло, пожарить креветки, пока не станут розового цвета. Положить креветки сверху на феттучини с соусом из цветной капусты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5355,'Соединить в блендере манку, творог и йогурт. Вбить яйца, насыпать сахар, добавить пекарский порошок и нежирные сливки. Мелко натереть шкурку апельсина, чтобы получилась цедра. Бросить ее в творожную массу, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5355,'Смазать маслом формочку, насыпать сухарики, вылить смесь из творога, поставить на десять минут в духовку, готовить при 220 градусов. Порезать ягоды и фрукты. Запеканку с творогом оставить на десять минут в духовке. Затем положить сверху фрукты, посыпать сахаром, минут на тридцать отправить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5356,'Просеять в большую посуду муку. Растворить в воде сахар и соль. В муке сделать отверстие, вылить раствор, растительное масло и водку. Хорошенько вымесить тесто, обернуть в пищевую пленку, на шестьдесят минут отложить. Приготовить начинку: можно взять баранину, говядину или использовать несколько видов мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5356,'Раскатать тесто толщиной миллиметра три. Блюдцем вырезать круги около двадцати сантиметров диаметром. Сложить тесто вдвое, защипнуть хорошенько края, чтобы не вытекла начинка. Слепить и обжарить хрустящие чебуреки с мясной начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5357,'Почистить луковицу и порезать на полукольца. Почистить, вымыть картофель и порезать на крупные кубики. Разогреть в кастрюльке растительное масло, пожарить лук. Положить картофель, налить холодную питьевую воду. Варить минут двадцать, пока не будет готов картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5357,'Почистить и порезать на несколько частей чеснок. Разогреть сливочное масло, пожарить до золотистого цвета чесночок. Положить его в кастрюлю с картофелем, варить минуты две все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5357,'По частям измельчить в блендере картофельную смесь, доливая постепенно отвар. Вылить все в кастрюльку, положить сливки, посыпать перцем, солью, закипятить. Чуть-чуть остудить. Посыпать зеленью, подавать картофельный суп-пюре с гренками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5358,'Положить в блендер кусочки банана, льда, йогурта, дольки манго, ананаса, ванилин и мед. Налить молоко, взбить до густой массы. Подавать ананасово-манговый коктейль сразу охлажденным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5359,'Довести до кипения воду и сахар, не мешая. Охладить. В сироп налить ананасовый сок, размешать ложкой .Почистить киви и порезать на не очень тонкие кусочки или колечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Для темного коржа необходимо смешать муку, какао, соду, яйцо, кефир и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5360,'Намотать пленку вдоль палочек, необходимо сделать приблизительно семь оборотов. Сделать надрезы, чтобы выпустить после намотки воздух. Скрутить коврик. Смазать коврик сыром, чтобы не прилип ролл. Уложить лист нори, сверху разложить рис тоненьким слоем, чтобы он на полтора сантиметра выступал. Чтобы рис был мягким и не разваливался, он должен быть теплым. Внутреннюю часть намазать сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5360,'Равномерно разложить начинку. Начинать сворачивать ролл следует с конца свободного от риса. Сразу может не очень хорошо получиться, все придет с опытом. Придать форму квадрата, сильно прижимать не нужно, чтобы не вылезла начинка. Скрутить ролл, затем в противоположную сторону завернуть хвостик с рисом. Снова сформировать форму квадрата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5360,'Сформировать форму треугольника, на верхний уголок положить рыбу. Ее желательно нарезать из целого куска, чтобы длина совпадала с шириной листа нори. Сверху посыпать кунжутом. Нарезать роллы « Гонконг» с угрем, желательно делать это японским ножом, смоченным предварительно водой. Приготовить васаби, можно из смешанного с водой сухого порошка. Чтобы сбить вкус от прошлого блюда, использовать имбирь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5361,'Отварить филе курицы, достать из бульона, охладить. Вымыть шампиньоны, порезать на средние кусочки, обжарить, охладить. Мясо порезать на небольшие куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5361,'Порезать сыр на кубики пять на пять миллиметров, помидоры на четыре части. Мясо, грибы, сыр и помидоры соединить. Заправить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Замариновать куриные крылья следующим образом: натереть их соком лимона и посыпать измельченным укропом, убрать в холод на 2-3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'В слегка подсоленной воде отварить крылья, остудить, извлечь кости, оставшееся мясо не сильно измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Крупно натереть на терке отварной картофель, очищенные яйца, немного подмороженные плавленые сырки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Все ингредиенты соединить, поперчить и посолить, добавить майонез и тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Оставить салат в холоде на полчаса, затем выложить его на плоское блюдо в виде змеи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Нарезать огурцы тонкими кружками, маслины – кольцами, выложить из них чешую.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Сделать змее корону и язык из вареной моркови, глаза – из маслин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'В середину каждой маслины положить зерно кукурузы, остальной кукурузой украсить голову змейки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5362,'Поставить новогодний салат «Змейка» из куриных крылышек в холод на 1 час, непосредственно перед подачей оформить листьями салата, зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5363,'Торт очень легко готовится. Без особых затрат получается очень вкусно. Соединить сахар, яйца, орехи, разрыхлитель. Смазать формочку маслом, посыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5363,'Готовить минут пять в духовке или микроволновой печи. Минут пять остудить. Посыпать ореховый торт сахарной пудрой, украсить фруктами или полить шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5364,'Отделить желтки и белки. Взбить желтки и 1/2 сахара в крутую пену. Насыпать 1/2 муки, взбить. Взбить белки до пышной массы, насыпать остальной сахар, взбить до пиков. Вмешать осторожно желтки в белки, насыпать муку, размешать. Положить тесто в кондитерский мешок или в пакет, отрезав уголок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5364,'Полосочками выдавить печенье. Посыпать сахаром. Готовить минут пятнадцать, соблюдая температуру 180 градусов. Охладить на решетке. Переложить печенье в формочку. Приготовить начинку: через марлю отвесить йогурт, чтобы стекла жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5364,'Взбить йогурт, сливочный сыр, ванильный экстракт, сахарную пудру. Вбивать по одному яйцу, насыпать муку, размешать. Налить начинку на основу. Разогреть духовку до 170 градусов. Обернуть чизкейк фольгой и выпекать на водяной бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5364,'Поставить формочку в форму побольше, налить кипяток до середины высоты бортика формочки с чизкейком. Сделать температуру 150 градусов, 75 минут готовить. Остудить отправить на ночь в холодильник. Вынуть чизкейк на натуральном йогурте с миндалем из формочки, намазать сгущенным молоком, посыпать миндалем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5365,'Отварить, почистить и порезать яйца. Отварить, порезать куриное филе. Измельчить помидоры, слить сок. Соединить яйца, курицу, грибы, посыпать перцем, солью, заправить майонезом. Размешать. Начинить тарталетки, украсить. Тарталетки с куриным салатом можно подавать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5366,'Помыть крылышки, натереть солью, приправить, отложить минут на тридцать мариноваться. Разогреть чуть-чуть растительное масло, бросить крылья, накрыть крышкой, жарить, пока не появится корочка. Перевернуть жарить с другой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5366,'Переложить в герметичную емкость, добавить порезанный чесночок, распределить его по мясу равномерно, плотно закрыть крышкой, встряхнуть минут через пять. Подавать куриные «Ароматные» крылышки можно спустя пять минут. Аромат даст чеснок в соприкосновении с горячим мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5367,'Отварить куриную грудку с черным перцем, лавровым листом и луком. Готовить желательно около часа. Убрать из мяса кости, поделить на волокна. Салат будет более нежным. Отварить яйца вкрутую, почистить. Отварить морковь и картофель, охладить, снять кожуру. Сыр-косичку расплести и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5367,'Можно взять обыкновенный сыр и натереть его на терку. Все ингредиенты поделить на несколько частей. Кольцо можно заменить баночкой из-под оливок. Поставить ее на середину блюда. Вокруг осторожно выложить одну часть мяса, посыпать солью. Все слои слегка утрамбовать. На мясо потереть половину картофеля, посыпать солью, потереть половину моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5367,'На морковь потереть морковь. Сверху положить 1/2 сыра. Майонезом сделать сеточку. Остальные овощи потереть таким образом: мясо курицы, сыр, яйца, морковь и картофель. Смазать салат «Нефритовый браслет» майонезом, осторожно вынуть баночку. Для украшения использовать кусочки киви.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5368,'Налить воду в большую емкость, насыпать обыкновенный сахар и ванильный. Перемешать до растворения сахара. Налить растительное масло, размешать. Просеять сто грамм муки, соединить с разрыхлителем и какао. Насыпать муку с какао в посуду со сладкой водой. Просеять остальную муку и понемногу насыпать в смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5368,'Вымыть изюм, слить лишнюю воду, подсушить на полотенце. Обвалять изюм в муке. Измельчить в блендере орехи (не слишком мелко). Положить их с изюмом в тесто. Размешать. Переложить тесто в формочку. Готовить постную коврижку минут пятьдесят, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5369,'Приготовить тесто: соединить все ингредиенты, вылить в смазанную формочку. С рыбы слить масло, размять ложкой. Положить измельченную зелень и яйца. Мелко натереть сыр. Выложить начинку в формочку, у бортика необходимо постараться оставить тоненькую полоску теста свободной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5369,'Отправить формочку на двадцать минут в разогретую духовку. Вынуть формочку с пирогом, посыпать сыром, поставить наипростейший и довольно бюджетный рыбный пирог на пять минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5370,'В первую очередь приготовить лимонадный курд: соединить сахар и сок лимона. С помощью венчика взбить интенсивно яйцо и желток. Соединить со сладким лимонным соком, размешать, перелить в кастрюлю. Положить масло, порезанное кусочками, поставить на плиту. Готовить минут восемь, помешивая до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5370,'Осторожно снять с плиты, вмешать цедру, накрыть крышкой, чтобы не появилась пленка. Чуть-чуть остудить – курд станет гуще. Приготовить тесто: взбить масло и сахар, добавить постепенно яйца. Постепенно насыпать 1/2 муки, сок и цедру половины лимона, остальную муку в несколько приемов. Распределить тесто по бумажным формочкам, готовить минут двадцать, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5370,'Осторожно вынуть капкейки, дать чуть-чуть остыть, сделать температуру 200 градусов. Приготовить меренгу. Осторожно засыпать белки сахаром, поставить на водяную баню. Мешать, пока сахар не растворится, взбить до пиков с помощью миксера. Вырезать осторожно в капкейке отверстие круглой формы практически до его дна, осторожно срезать верхушку вырезанной серединки и начинить кекс лимонным курдом, накрыть верхушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5370,'Осторожно нанести сверху меренгу. Такую же процедуру сделать с остальными капкейками, выпекать, соблюдая температуру 200 градусов. На выпечку капкейков с курдом и меренгой уйдет минуты четыре. Держать, пока не подрумянится меренга',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5376,'Выложить смесь в хлебную формочку. Сверху положить помидоры, порезанные на кружки, и дольки маслин. Посыпать русскую пиццу-бутерброде тертым сыром. Готовить в микроволновой печи приблизительно минуты три.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'На лист пекарской бумаги, постеленный на дно формы, вылить получившееся тесто (любое).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5371,'Приготовить тесто: растопить масло, налить молоко (теплое) – можно разогреть его в микроволновой печи или на плите. Вбить яйцо. Размешать, насыпать сахар и соль. Положить дрожжи, насыпать 1/2 стакана муки. Размешать, минут на двадцать отставить, чтобы дрожжи начали работать. Понемногу подсыпать муку, время от времени вымешивать. Тесто не должно прилипать к рукам. Поставить в тепло, чтобы тесто поднялось .',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5371,'В это время отварить картофель, приготовить пюре, добавляя молоко и масло. Размять. Помять тесто, разделить пополам. Раскатать тесто колбаской, порезать на кусочки. Обвалять каждый в муке, раскатать лепешки. В середину лепешки положить чуть-чуть картофельного пюре, распределить в длину. Положить в центр сосиску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5371,'Со всех сторон сделать по три надреза. Запеленать сосиску, намазать сверху взбитым яйцом. Смазать противень растительным маслом, положить сосиски с картофелем в дрожжевом тесте, отправить в духовку. Готовить минут пятнадцать, соблюдая температуру 50 градусов. Потом включить духовку на 250 градусов и готовить, пока не образуется корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5372,'Морковь почистить, помыть и мелко потереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5372,'Яблоко натереть с помощью крупной терки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5372,'К моркови и яблоку добавить сметану, сахар, все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5372,'Немного охладить морковный салат со сметаной, сахаром и яблоком и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5373,'Растворить дрожжи в теплом молоке. Насыпать муку, вымешать, поставить на несколько часов в тепло подходить. Изюм залить горячей водой, отставить минут на пятнадцать. Сцедить воду, подсушить изюм на салфетке. Растопить и остудить сливочное масло. Яйца растереть с сахаром, насыпать соду и ванилин, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5373,'Соединить опару со сливочным маслом и яичной массой. Медленно насыпать остальную муку. Тесто должно отходить от стенок емкости. Отставить минут на шестьдесят, чтобы оно подошло. Высыпать в тесто изюм, перемешать. Разделить тесто на 24 одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5373,'Из каждого кусочка скатать по несколько жгутов, переплести их между собой, концы слепить вместе. Булочки переложить на противень. Взбить яйцо с молоком, намазать смесью дрожжевые венские булочки. Готовить минут двадцать в духовке, соблюдая температуру 180 градусов. При появлении золотистой корочки, выключить огонь и оставить на решетке, пока не остынут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5374,'Нашинковать капусту, сложить горкой. Натереть морковь, выложить на капусту. Посахарить и посолить морковь, аккуратно размешать. Намного удобней делать это в большой посуде. Когда морковь распределится равномерно, попробовать на сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5374,'Банку наполнить капустой плотно, но не очень, слегка утрамбовывая. Не заполнять банку капустой полностью, необходимо оставить место для сока, который будет выделяться из капусты. Прикрыть банку крышкой, но не плотно, оставить на несколько суток в тепле. Если в помещении прохладно, то на трое — четверо суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5374,'Когда капуста станет на вид стеклянной, на вкус кисловатой и потонет в своем соку, значит, она готова. На этом моменте она тоже очень вкусная. Накрыть квашеную капусту с морковью крышкой, отправить в холодильник, таким образом, часть сока, выделившегося из капусты, вернется обратно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5375,'Соединить теплую воду и теплое молоко в посуде, насыпать дрожжи, тщательно их растворить. Посахарить, посолить, растворить, насыпать муку, вымешать. Сыпать муку, пока тесто не перестанет прилипать к рукам в момент вымешивания. На тридцать минут отложить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5375,'Застелить противень специальной бумагой, из теста сделать шарики небольшого размера. Положить их на противень с постеленной бумагой на расстоянии друг от друга. Сверху пампушки намазать желтком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5375,'Оставить минут на пятьдесят перед тем, как ставить в духовку, чтобы они подошли.  Когда пампушки поднимутся, поставить на двадцать минут в духовку, готовить, соблюдая температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5375,'Приготовить чесночный соус: почистить чеснок. Выдавить чеснокодавкой, измельчить укроп и петрушку. Посыпать солью, размешать. Налить слегка теплую питьевую воду и растительное масло. Размешать. Налить чесночный соус на дрожжевые пампушки и минут на пять отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10657,'И поджарьте его вместе с овощами 5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5377,'Залить холодной водой суповой набор суповой набор. Чтобы бульон был наваристый, мясо нужно заливать именно холодной водой. Довести до кипения, готовить минут сорок. Почистить картофель, морковку и лук. Лук измельчить, морковь потереть, картофель или потереть, или мелко порезать. Обжарить лук и морковь, долить чуть-чуть воды, тушить под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5377,'Маленьким детям не жарить морковь и лук, а сразу бросать в бульон с картофелем. Достать мясо, отделить его от костей, положить картофель в бульон, насыпать гречку, поварить минут пятнадцать под крышкой. Положить овощи, измельченное мясо, сухую зелень и лавровый лист. Варить гречневый суп с курицей минут семь, подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5378,'Сначала необходимо подготовить кабачок: потереть на терке. Если кабачок старый, то срезать кожуру, убрать семена, если овощ молодой, то делать этого не нужно. Отжимать кабачок тоже не надо, тогда котлетки будут сочными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5378,'Измельчить лук, чеснок и зелень. Положить в подходящую емкость кабачок, фарш, зелень, лук и чеснок. Посыпать перцем и солью. Размешать все, чтобы кабачок равномерно разошелся. Это сделает котлеты крепкими. Можно добавить яйцо, чтобы фарш не рассыпался.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5378,'Подготовить противень или формочку, застелить фольгой. Влажными руками сформировать котлетки, плотно положить на противень. Готовить котлеты «Сочные» с кабачком минут сорок, соблюдая температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5379,'Взбить яйцо и сахарный песок, налить кефир, масло, насыпать муку и разрыхлитель, добавить ванилин. Перелить тесто в формочку. Готовить «Кекс–красавец» минут 25. Температура должна быть не выше 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5380,'Положить в теплую воду сахар и дрожжи. Размешать и минут на пятнадцать оставить, чтобы дрожжи ожили. Положить масло, сметану, вбить яйцо, посыпать солью. Размешать венчиком. Медленно насыпать муку, замесить тесто. Подождать пока оно поднимется. Отварить курицу, порезать мясо кубиками. Приготовить соус «Бешамель»: растопить в сковороде сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5380,'Высыпать муку, хорошенько помешать, чтобы исчезли комочки, использовать деревянную лопатку. Налить горячее молоко или бульон, где варилось мясо небольшими порциями. Каждый раз размешивать, посыпать мускатным орехом, перцем, солью. Несколько минут поварить, после этого процедить, чтобы избавиться от комков, если они есть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5380,'Соединить мясо, приготовленный соус и измельченную зелень. Выложить тесто на стол, посыпанный мукой, чуть-чуть помесить, разделить пополам, чтобы один кусочек был немного больше другого. Кусок, который побольше, положить в формочку, смазанную маслом и посыпанную мукой, распределить равномерно, сделать бортики, положить начинку, утрамбовать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5380,'Растянуть кусок поменьше, уложить на начинку, защипнуть краешки, в середине сделать отверстие. Отставить минут на двадцать, чтобы расстоялся. Намазать молоком или желтком. Готовить пирог с начинкой из курицы в соусе  при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5381,'Порезать сосиски. Потереть сыр. Раскатать тесто, положить сосиски с сыром, распределить по поверхности теста. Сформировать рулетик, кончики закрепить. Положить в формочку фольгу или специальную бумагу, намазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5381,'Уложить рулетики. Взбить в отдельной миске яйцо и Айран. Намазать смесью пирог. Готовить сырную улитку, соблюдая температуру 190 градусов, пока не появится корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5382,'Соединить творог, желтки, ванильный и обыкновенный сахар. Положить сливочное масло, растопленное в микроволновой печи. Добавить разбухшую манную крупу. Просеять крахмал. Взбить белки и соль до густой пены, чтобы она не вылилась, даже при переворачивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5382,'Осторожно соединить творожную массу и белковую, размешать до состояния однородности. Переложить в формочку, намазанную маслом, на сорок минут отправить в духовку. Готовить сладкую творожную запеканку при 180 градусах. Когда сверху запеканка станет румяной, выключить духовку и не доставать ее минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5383,'Соединить сахар, соль, воду, перец чили. Взбивать венчиком, пока не растает сахар и соль. Положить в смесь креветки и отставить минут на двадцать. Нагреть масло, обжаривать чеснок и имбирь на протяжении минуты, помешивая деревянной ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10727,'Давление не должно превышать четыре бара.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5383,'Насыпать сахар, обжаривать еще минуты две – чесночок должен стать бледно-золотистого цвета. Слить креветки через дуршлаг, быстро переложить на сковороду. Сделать огонь выше среднего. Готовить креветки в остром маринаде, помешивая время от времени, минуты четыре, креветки должны быть розовыми.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5384,'Разрезать грудинку вдоль на две части. Натереть мясо оливковым маслом, посыпать тимьяном, солью, перцем. Положить на тарелочку и отправить в холодильник. Нагреть масло. Обжарить сельдерей, измельченный лук, орегано, перец, соль минут пять, помешивая. Положить прессованный чесночок, томаты. Размешать, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5384,'Сделать оного меньше, готовить минут пятнадцать, помешивая. На улице нагреть гриль. Положить курицу, обжаривать минуты четыре со всех сторон. Положить мясо на тарелочки, полить соусом, посыпать сырком. Поставить курицу «Пармезан» в духовку под бойлер и держать до расплавления сыра и образования корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5385,'Помыть и обсушить рульку. Порезать чесночок и морковь на тоненькие полоски. Нашпиговать рульку при помощи длинного ножа. Положить рульку на несколько слоев фольги, смазать маслом, приправить солью, специями, в конце горчицей. Завернуть в фольгу, мариновать минимум пять часов, а лучше ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5385,'В течение часа готовить в фольге, соблюдая 230 градусов. Развернуть фольгу, полить светлым пивом. Выпекать пьяную рульку с морковью в пиве минут шестьдесят, соблюдая температуру 180 градусов, каждые десять минуть поливать пивом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5386,'Почистить и отварить картофель. Порезать грибы, филе курицы, обжарить. Приготовить соус: соединить молоко или сливки с приправами, подогреть. Крупно потереть сыр. Измельчить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5386,'Смазать противень, положить картофель, сверху курицу с грибами, полить соусом, посыпать сырком. Готовить запеканку по-итальянски минут двадцать, соблюдая температуру 180 градусов. Сыр должен запечься. В конце украсить листиками петрушки и укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5387,'Растворить в теплом молоке дрожжи, вбить яйцо, насыпать муку, соль, замесить эластичное тесто. Поделить его пополам. Каждую часть раскатать. Разделить пополам сливочное масло, намазать им раскатанные пласты. Оба скрутить рулетиками. Каждый свернуть улиткой, обернуть полиэтиленом и положить в холод часа на два.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5387,'Пока охлаждается тесто, приготовить крем «Магалябия»: смешать крахмал и яйцо, растереть до густой смеси. Развести молоком, поставить на огонь, довести до загустения. Охладить. Достать тесто, раскатать пласты толщиной по три миллиметра, один перенести на противень, застеленный пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5387,'Выложить на тесто крем, выровнять, накрыть вторым пластом, концы подвернуть на несколько сантиметров, проткнуть в двух местах вилкой. Готовить минут тридцать, соблюдая температуру 180 градусов. Остудить чуть-чуть египетский фытыр, посыпать сахарной пудрой. Можно употреблять и горячим, и холодным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5388,'Соединить ингредиенты, перемешать венчиком, налить в формочку. Приготовить начинку: соединить все продукты для начинки. Намазать ее на тесто и распределить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5388,'Готовить минут тридцать, соблюдая температуру 180 градусов. Следить, чтобы кокосовая стружка не подгорела. Спустя десять минут, после начала готовки, накрыть кухен с кокосом фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5389,'Налить в кастрюльку сливки, воду, посолить. Довести до кипения. Медленно насыпать манку, постоянно мешать до однородности. Сделать огонь минимальным, накрыть кастрюлю крышкой. Готовить минут тридцать, помешивая, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5389,'Каша',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5390,'Получается сочное и ароматное мясо. Намазать сотейник топленым маслом (или сливочным). Уложить слой мяса, порезанного на мелкие кубики. Посыпать солью, приправами. Сверху выложить слой лука, порезанного на полукольца. На него натертую морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5390,'Сверху слой тонко нашинкованной капусты. Посыпать солью. Если слои получились тонкие, то их можно повторить. Посыпать сверху сыром и намазать майонезом. Готовить ароматное мясо под шубой в духовке до появления корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5441,'Смесь влить в форму из силикона или обычное блюдо, смазанное маслом и застеленное пищевой пленкой. Заморозить. При готовности перевернуть семифредо с цуктами и фисташками на тарелку, посыпать ягодами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5391,'Сделать бисквитное тесто: растереть сливочное масло и сахар. Вбить яйца поочередно, взбить. Насыпать разрыхлитель, ванилин, муку, просеянную. Замесить тесто. Поделить пополам, в одну часть насыпать какао-порошок, перемешать. Формочку смазать маслом, вылить сначала одно тесто, потом второе сверху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5391,'Поставить формочку на тридцать минут в духовку, готовить при 180 градусов. Растопить шоколад и масло, соединить в однородную смесь. Остудить кекс «День и ночь», полить глазурью, охладить. Перед подачей порезать на кусочки, украсить мятой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5392,'Почистить мандарины, поделить на дольки, измельчить с помощью блендера. Чтобы убрать кожицу, можно протереть пюре с мандарин через сито (можно этого не протирать). Если протереть, то вкус будет нежнее. Соединить в блендере сгущенное молоко, сметану, мандариновое пюре, перемешать. Перелить в контейнер из пластика, отправить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5392,'Через каждые 60 минут доставать и размешивать, чтобы мороженое было насыщено кислородом и не было льдинок. Перемешивать интенсивно. Оставлять в холоде часов двенадцать – ночью можно не перемешивать. Украсить мандариновое мороженое сиропом. Для этого сок нескольких мандарин прогреть с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5393,'Отварить в соленой воде креветки, положить лавровый лист, перец-горошек. Откинуть на дуршлаг, охладить. Сварить картофель и морковь, дать остыть, почистить. Отварить яйца. Почистить и порезать авокадо и огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5393,'Выложить один слой на другой, каждый смазывая майонезом. Крупно потертый картофель, крупно потертая морковка, крупно потертое яйцо, огурец, авокадо, креветки. Украсить овощной салат с креветками и авокадо можно лимонными дольками, зеленью и креветками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5394,'Вымыть яблоки, снять кожуру, убрать серединку. Измельчить в блендере в пюре или мелко потереть. Залить яблочки кефиром в холодном виде, взбить миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5394,'Положить чуть-чуть корицы и сахарный песок, взбить. Перед подачей разлить яблочный коктейль на кефире по бокалам, можно украсить кусочком яблока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5395,'Сварить картофель в кожуре, поперек разрезать на 3 части. Между ними положить колбасный сырок, обернуть все ломтиком бекона. Отправить сэндвич из картофеля в духовку минут на двадцать. Сырок не должен расплавиться, а бекон поджариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5396,'Отварить пасту, как написано на упаковке в инструкции, слить жидкость, промыть холодной водой. Чеснок и луковицу измельчить. В сковороде растопить и нагреть оливковое и сливочное масла. Положить чесночок, лук, обжаривать минуты три. Бросить в сковороду креветки и готовить несколько минут. Выжать сок лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5396,'Добавить вино, острый соус. Посыпать перцем и солью. Размешать, сделать маленький огонь. Снять с огня сковороду, переложить макароны, размешать. Если необходимо приправить. Посыпать пасту с креветками тертым сыром пармезан и измельченной петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5397,'Почистить яблоки от семян и кожуры. Потереть, отжать сок, положить цедру и сахар. Положить яблочное пюре на противень, застеленный специальной бумагой и намазанной маслом, разровнять. Посыпать корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5397,'Разделить желтки и белки. Взбить желтки, насыпать сахар, снова взбивать минуты три. Насыпать разрыхлитель и муку. Размешать. Взбить белки до эластичных пиков, осторожно вмешать в тесто. Равномерно уложить тесто на яблочную массу. Готовить минут двадцать, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5397,'Когда бисквит будет готов, накрыть противень полотенцем, перевернуть начинкой вверх, прямо на полотенце. Убрать бумагу. Помогая полотенцем, завернуть рулетиком, чтобы начинка из яблок была внутри. Чуть-чуть посыпать рулет с яблочной начинкой сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5398,'Поставить на огонь воду. Взять две или три рыбы. Хорошо почистить: отрезать голову, избавиться от внутренностей, срезать плавники и хвостик. Порезать на кусочки по два сантиметра каждый.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5398,'Сложить в нержавеющую кастрюлю все продукты, минут пять кипятить, потом охладить. Сложить рыбу в охлажденный рассол, накрыть тарелочкой. Кушать скумбрию пряного посола можно на следующий день.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'Брюшко или мякоть рыбы промыть кипяченой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'Сыр и вареные яйца натереть на любой терке, смешать с майонезом и поставить в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5399,'В соленой воде отваривать минут двадцать филе курицы, порезать на средние кусочки, положить мясо в салатник. Сделать сверху майонезную сетку. Шампиньоны отварить (если используются грибочки консервированные, то необходимо обжарить их без масла, чтобы ушла жидкость), порезать, положить равномерно на мясо, сделать сеточку майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5399,'Порезать огурцы, положить слоем на грибочки. Сделать майонезную сеточку. Крупно потереть сыр, распределить слоем по огурчикам, снова сделать майонезную сетку. Порезать помидоры на кубики, положить их на сыр. Дать салату «Красная шапочка» настояться и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5400,'Положить в воду желатин, отставить на шестьдесят минут, чтобы он набух. Приготовить бисквит: яйца взбить и сахар. Насыпать муку, размешать. Застелить формочку бумагой или намазать маслом. Налить тесто в формочку, готовить минут тридцать, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5400,'Белки взбить с сахаром, сахар должен раствориться. Можно взять перепелиные яйца. Разбухший желатин поставить на огонь. Мешать до полного растворения. Добавить лимонную кислоту. Охладить до комнатной температуры, налить в белки, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5400,'Вылить белковую смесь на бисквит, поставить в холодильник для застывания. Взять шоколад, растворить в молоке на минимальном огне, осторожно вылить сверху. Выровнять. Украсить торт «Птичье молоко» семечками, орешками или чем-то другим по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'Сахар, молоко, яйца и соль смешать, аккуратно всыпать муку, вымесить густое, но не слишком крутое, тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'Тесто следует хорошенько помять, чтобы оно не приставало к столу, раскатать тонким жгутом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'Жгут нарезать одинаковыми тонкими полосками, концы которых защипнуть, и сформовать сушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'Вскипятить воду, посолить, положить в нее сушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'После того, как они всплывут, нужно их достать и разложить на полотенце, подождать пока обсохнут, затем разложить на лист для запекания, заранее смазанный маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5401,'Русские сушки по-домашнему запечь до готовности в духовке, разогретой до средней температуры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5402,'Взбить в емкости несильно холодное молоко, жидкий мед и яйца. В другой посуде соединить все сухие продукты, кроме орехов. В полученную смесь вылить медовую массу, размешать. Тесто будет, как на оладушки. Высыпать измельченные орешки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5402,'Вылить в формочку на 2/3 тесто, готовить минут тридцать, соблюдая температуру 180 градусов. Готовность медово-ореховых кексиков  проверять нажатием. Если они упругие, значит, готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5403,'Ингредиентов брать столько, сколько планируется делать капустки. Нашинковать все, что можно нашинковать. Положить в емкость, например, пластиковый контейнер. Посолить, налить чуть-чуть уксуса, накрыть крышкой, встряхнуть. Спустя минут двадцать капуста готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5404,'Растереть творог, вбить яйцо, положить сметанку, насыпать соду, соль, сахар, муку, размешать (может потребоваться побольше муки). Стол посыпать мукой, замесить тесто. Раскатать тоненькие жгуты. Порезать любой длины. Обжарить трубочки с четырех сторон на масле. Посыпать батончики из творога сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5405,'Поделить тесто пополам, один кусок раскатать и положить на сковороду или противень, чтобы свисали краешки. Намазать тоненький слой горчицы. Сверху положить слой ветчины (желательно использовать нарезку).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5405,'На ветчину положить тоненько порезанный сыр в виде ромашки (лучше тоже использовать нарезку), посыпать приправами, например, свежим тимьяном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5405,'Раскатать второй кусок, вырезать круг, накрыть им начинку, сверху прикрыть свисающими краешками первого куска. Защипнуть. В центре пирога сделать отверстие. Белок смешать с водой. Полученной смесью смазать французский пирог и поставить на сорок минут в духовку. Готовить при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5406,'Соединить яйца, сахар, соль, налить половину кефира, непрерывно помешивая, медленно насыпать муку. Замесить тесто. Налить остальной кефир, тщательно размешать и добавить соду. С помощью большой ложки выложить на сковороду тесто маленькими порциями. Готовить оладьи на кефире с двух сторон до образования корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'Покрыть помидоры сметаной, перемешанной с измельченным чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Состоит из двух блоков: масляного и тестяного. По методу Пьера Эрме тестяной блок необходимо упаковать в масляный. Чтобы слоистость была идеальной, довольно двух двойных и одного одинарного тура. Получается очень легкое и нежное тесто, с очень тоненькими слоями. Тестяной блок: соединить и размешать масло и муку, в воду добавить уксус и соль, вылить в тесто. Раскатать тесто прямоугольной формы приблизительно десять на пятнадцать сантиметров. Завернуть в пленку, отправить часа на полтора в холодильник. Туда же положить коврик и скалку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Масляный блок: медленно с помощью миксера, не взбивая, проработать масло, чтобы получился гладкий крем, потом муку. Сформировать маленький прямоугольник, обернуть пленкой, положить в холод часа на полтора. Вынуть масляное тесто, раскатать на холодом, посыпанном мукой коврике, чтобы получился прямоугольник. В середину положить тестяной блок, накрыть, хорошенько запечатать края. Раскатать прямоугольник приблизительно пятьдесят на семнадцать сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Перед тем как использовать масляный блок, его нужно вынуть из холодильника и дать ему немного полежать, чтобы он не ломался, а стал эластичным. Сколько времени держать тесто зависит от температуры в помещении, если тепло, то тесто оттает быстрей. Если масло начинает таять, то после того, как в него упаковано тесто, положить тесто в холод. Размер торта в принципе не важен. Только нужно учитывать, что толщина теста должна быть один сантиметр, а ширина раза в три меньше длины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Сложить в виде книги (двойной тур). Завернуть в пленку, отправить на полтора часа в холодильник. Коврик и скалку тоже. Затем все повторить, обернуть в пленку и в холодильник на ночь. Раскатать тесто, сложить в виде письма (простой тур), на шестьдесят минут в холодильник. Раскатать прямоугольное тесто приблизительно 60 на 40 сантиметров, толщиной 3 миллиметра. При помощи ножа для пиццы обрезать краешки, порезать на шесть квадратов 20 на двадцать сантиметров, положить в холод на тридцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Перед тем как начать готовить, в нескольких местах сделать проколы с помощью вилки. Выпекать коржи минут двадцать, соблюдая температуру 200 градусов. Главное, чтобы коржи пропеклись равномерно и приобрели золотисто-коричневатый цвет. А также необходимо следить, чтобы не подгорел верх и низ, во время того, пока корж будет пропекаться внутри. Но это уже зависит в основном от индивидуальных особенностей духовки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Крем: довести до кипения молоко, положить ваниль. Отдельно соединить желтки, крахмал и сахар, взбить с помощью венчика. Влить тонкой струйкой 1/2 молока в смесь из желтков, непрерывно взбивая. Полученную смесь вылить в молоко, продолжать взбивать. Все довести до кипения на минимальном огне. Положить хорошее масло и сгущенное молоко. Насыпать соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5407,'Все коржики разрезать или разобрать руками (как удобней, потому что слои с легкостью друг от друга отходят) на несколько частей по высоте. Смазать коржи. Отставить торт «Наполеон» при комнатной температуре, чтобы он пропитался. Потом сверху положить груз, то есть накрыть плоской тарелочкой, а на нее положить бутылку молока или пачку соли и отправить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5408,'Приготовить курицу. По желанию: можно просто ее отварить, а можно отварить, а потом немного обжарить. Кому, как нравится. Пока мясо находится в процессе готовки, порезать капусту на тоненькие полоски. Порезать дольками помидоры. Мелко потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5408,'Когда курица будет готова, разобрать мясо на маленькие кусочки (волокна). Приготовить соус: измельчить в блендере чеснок с майонезом, зеленью и двумя капельками лимонного сока до однородности. Чеснок и лимон класть по вкусу. Данную процедуру можно сделать вручную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5408,'Салат «Цезарь» не заправлять, соус подавать отдельно. Каждый должен сам налить его себе в тарелку. Даже если застолье затянется, салатик сохранит привлекательный внешний вид и великолепный вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5409,'Залить желатин молоком и оставить на шестьдесят минут для набухания. Когда он набухнет, поставить на минимальный огонь и довести до абсолютного растворения, непрерывно помешивая. Насыпать в желатин обыкновенный и ванильный сахар, мешать до растворения, охладить до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'Посыпать блюдо тертым сыром, запечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5409,'Протереть творог блендером или через сито до консистенции похожей на пасту. В желатин положить сметану, интенсивно размешать. Соединить с творожной смесью. Разделить ее пополам, в одну часть насыпать какао, размешать. В формочку вылить часть без какао, отправить в холодильник или в морозилку минут на пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5409,'Когда первая часть застынет, вылить вторую, отправить в холодильник. После застывания ванильно-шоколадное желе  порезать на порционные кусочки. В качестве украшения использовать шоколад или фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5410,'Вскипятить молоко, аккуратно ввести манную крупу, при этом все время мешать молоко, посластить, посолить, добавить кусочек сливочного масла, варить пока каша не загустеет, потом ее остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5410,'Отделенные желтки растереть с сахаром, переложить к хорошо промытому и вымоченному изюму, добавить все в кашу и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5410,'Взбитые белки, аккуратно помешивая, ввести в кашу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5410,'Манная каша с изюмом «Русская печь» в духовке, разогретой до средней температуры, в районе получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5411,'Растопить на водяной бане, то есть над емкостью с кипящей водичкой, сливочное масло и шоколад до однородности. Отдельно взбить интенсивно белки до пиков. Положить желтки, насыпать сахарную пудру, взбить. Яичную смесь вылить в емкость с растопленным шоколадом. Перемешать при помощи лопатки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5411,'Насыпать муку. Необходимо знать, что соединять с яичной смесью, следует уже остывший шоколад. Если он будет горячим, то ничего не получится. Насыпать чуть-чуть какао-порошка, снова размешать при помощи лопатки (не миксером). Должна получиться тягучая, густая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5411,'Вылить массу в формочки (можно взять или силиконовые, или керамические). Наполнять не полностью, так как во время готовки тесто поднимется. Отправить на восемь минут в духовку, выпекать при температуре 180 градусов. Достать фондан с темным шоколадом, охладить, подавать лучше в теплом виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5412,'Порезать сырок на кубики, положить в баночку из стекла. Приготовить маринад: обжарить на масле измельченный чесночок и имбирь, можно положить куркуму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5412,'Соединить сок лимона, масло, мед, пряности, поджаренный имбирь с чесночком. Вылить масляную смесь в банку с сыром, положить веточку петрушки сверху. Закрыть баночку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5413,'Растереть масло и сахар, вбить яйца, размешать. Насыпать муку, разрыхлитель – замесить тесто. Почистить яблоки, убрать семена. Порезать на тоненькие ломтики. Застелить противень бумагой, положить 2/3 теста, разровнять. Сверху равномерно положить яблоки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5413,'Из остального теста сделать косички, то есть, скатать жгутики, приплюснуть, сделать надрезы. Положить косички на пирог. Готовить пирог минут тридцать, соблюдая температуру 180 градусов. Приготовить крем: смешать сахар и сметанку. Вылить крем на горячий пирог. Остудить пирог с яблоками в сметанном креме и порезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5414,'Развести дрожжи в теплой воде. Соединить в посуде муку, соль и сахар. Налить молоко, растительное масло, вбить яйцо, размешать до однородности. Перелить тесто в разведенные дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5414,'Перемешать. Накрыть емкость полотенцем, отправить в тепло минут на сорок. Смазать сковороду маслом, поставить на огонь. Выкладывать оладушки. Обжаривать дрожжевые ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5415,'Измельчить печенье, пользуясь скалкой или блендером. Растаявшее сливочное масло вылить в печенную крошку, размешать. Смазать маслом чашку мультиварки. Переложить смесь, утрамбовать руками или с помощью стакана. Поставить мультиварочную емкость в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5415,'Приготовить начинку из банана: измельчить бананы с помощью блендера, добавить лимонный сок, чтобы фрукт не стал темным. Отдельно взбить блендером сахар, сметану, яйца и творог. Творожную массу соединить с банановым пюре, взбить. Достать из холодильника емкость с масляной массой, вылить очень осторожно сверху начинку из банана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5415,'Закрыть мультиварку крышкой, выбрать режим «Выпечка», готовить 65 минут. Когда пройдет время, выключить мультиварку, но не открывать ее приблизительно минут 60, чтобы творожный пирог с бананом и печеньем настоялся. Спустя час осторожно вынуть пирог и кушать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9454,'Время приготовления – 35 минут, температура – около 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5416,'Взять спелую клубнику небольшого размера. Убрать плодоножки, помыть ягодки, переложить в сито, чтобы стекла вода. Переложить в посуду. В другой емкости сварить сироп: разбавить сахар водой, поставить вариться. Готовить сироп минут семь до загустения, но не белого цвета. Чтобы проверить готовность, набрать чуть-чуть сиропа ложкой и подуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5416,'Он должен стать немного вязким. Вылить горячий сироп на клубнику, накрыть крышкой, дать остыть. Ягоды в этот момент пускают сок, и сироп становится жиже. Остальную клубнику процедить через сито, полученный сок поставить минут на семь на огонь. Положить клубнику в посуду и залить горячим сиропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5416,'Снова подождать, пока клубника совсем остынет. Снова повторить действия. По желанию можно сделать сироп более густым. Для этого насыпать сахар и хорошо прокипятить. После трех таких действий разложить ягоды клубники в стерилизованные банки, залить кипящим сиропом, закатать варенье из клубники крышками, укрыть одеялом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5417,'Растереть обезжиренный творог с яйцом. Крупно натереть морковь и яблоко. Все соединить и перемешать. Добавлять соль и сахар не нужно. Поставить запеканку из творога в духовку. Готовить минут двадцать, соблюдая температуру 230-250 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5418,'Разогреть духовку до 175 градусов. Смазать формочку маслом и посыпать мукой. Взбить сливочное масло и сахар, взбить до воздушной смеси. Положить ванилин и сливки. Размешать. Просеять разрыхлитель и муку, медленно высыпать в основу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5418,'Взбить белки до пиков. Понемногу ввести в основу, осторожно размешать, белки при этом не должны осесть. Перелить в небольшую емкость 1/3 теста, перемешать с растопленным шоколадом до однородности. Вылить 1/2 светлого теста в формочку, выровнять с помощью лопатки. Вылить темное тесто, закрыть оставшимся светлым тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5418,'При помощи ножа на сыром тесте нарисовать легкий рисунок, например, какой-нибудь зигзаг. Выпекать минут 35.Приготовить клубничный соус: переложить клубнику и сахар в кастрюльку, довести до кипения. Охладить. Полить им готовый пирог. Мраморный пирог с клубничным соусом можно подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5419,'Высыпать муку на поверхность. Потереть маргарин, замесить. Сформировать лунку, положить сметану. Добавить соду, можно по желанию ее погасить, но это не обязательно. Сделать из смеси колобок, отправить минут на сорок в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5419,'Приготовить начинку: порезать и обжарить лук. Выложить фарш и обжарить все вместе. Потереть сыр, добавить яйца и белки. Соединить с фаршем. Переложить в тесто. Разделить на несколько частей, одна чуть-чуть меньше другой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5419,'Большая часть станет основой, раскатать ее. Противень застелить бумагой, чтобы пирог не прилип, не пригорел и удобней было его вынимать. Положить тесто на противень, сверху начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5419,'Раскатать часть поменьше, накрыть ею начинку, чтобы она не вытекла, закрепить краешки. Намазать тесто желтками при помощи кисточки. Отправить пирог с мясным фаршем и сыром в разогретую духовку минут на 45, готовить при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5420,'Нагреть духовку до двухсот градусов. Соединить пюре и овощи или тертый сыр. Посыпать перцем и солью. Сформировать шарики. Разбить яйца, произвольно взбить вилкой. Обвалять крокеты в муке, окунуть в яйцо, обвалять в сухариках.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5420,'Переложить крокеты на противень, смазанный немного маслом, готовить минут десять. Вынуть крокеты из картофеля с грибами и сыром, перевернуть, держать еще минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5421,'Порезать мясо на продолговатые куски, отбить, посыпать солью, перцем. Порезать лук на полукольца, грибы на пластинки, грушу на маленькие куски. Сыр порезать на полоски по 0,5 сантиметров. Обжарить лук, добавить грибочки, минут десять тушить. Охладить. Положить грушу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5421,'На каждый кусок положить чуть-чуть начинки, полоску сыра, свернуть рулетики, перемотать ниткой, можно сколоть зубочистками. Положить на противень, смазанный маслом. Отправить минут на десять в духовку, соблюдая температуру 180 градусов. Рулеты из свинины с сыром полить вином, отправить минут на пятнадцать в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5442,'По диагонали разрезать хлеб, рыбье брюшко или мякоть нарезать длинными полосками, крабовые палочки – поперек продолговатыми пластиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5422,'Перемешать сахар и масло, положить цедру, ваниль, вбить яйцо. Постепенно насыпать муку. Замесить мягкое тесто. Формочку 22 на 24 сантиметра застелить бумагой. Разровнять по ней тесто и отправить в холодильник. Сделать крем: соединить сахар, муку, цедру, ваниль. Вбить желтки, налить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5422,'Размешать, чтобы получилась гладкая смесь. Налить оставшееся молоко. Поставить на огонь. Чтобы не образовались комки, непрерывно помешивать. Остудить. Готовый корж остудить, намазать кремом, можно добавить в крем пищевую краску. При помощи овощечистки заготовить ленты для роз с кожицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5422,'Поставить воду, насыпать чуть-чуть сахара, положить лепесточки будущих роз из яблок. После закипания положить желатин, предварительно прочитав на упаковке инструкцию. Переложить лепестки на тарелочку, остудить, скручивать по три лепестка, вставлять по кругу. Между розочками на пироге «Букет роз» по желанию выдавить узоры при помощи кондитерского мешка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5423,'Взять посуду среднего размера, положить печеньки слоями, горкой. Кофе смешать с сахаром. Осторожно вылить его на бисквиты, постараться, чтобы ни одно печенье не было дискриминировано. Пока кофе впитывается в бисквиты, положить маскарпоне в отдельную посуду, взбить с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5423,'Порезать стручки ванили вдоль, убрать семена. Соединить с маскарпоне. Остальные стручки засунуть в сахарницу. Взбивая маскарпоне, медленно влить алкоголь. Должна получиться масса по консистенции схожей с нежным, гладким кремом.  Если крем получился слишком густой, то налить чуть-чуть сока апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5423,'Оставшийся сок вылить на бисквит. Положить ванильный маскарпоне на бисквит. С шоколадки осторожно ножом снять стружку и высыпать ее на крем. Также украсить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5424,'Вымыть и порезать зеленый лук. Его понадобиться много – целая сковорода. Чуть-чуть прогреть с маслом, чтобы он стал мягче. Посыпать перцем, солью. Положить яйца, порезанные на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5424,'Приготовить тесто: растопить масло, посыпать солью и сахаром, вылить кефир, взбитые яйца. Насыпать муку, разрыхлитель, перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5424,'Смазать формочку маслом, вылить большую часть теста. Положить начинку, сверху оставшееся тесто. Выпекать заливной пирог с луком минут 35. Немного остудить, накрыв полотенцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5425,'Приготовить начинку: измельчить лук и вареные яйца. Посыпать солью. Если начинка слишком рассыпчатая, то положить чуть-чуть растаявшего сливочного масла. Посыпать по вкусу молотым перцем. Приготовить тесто: налить кефир в емкость, насыпать соду, размешать, подождать реакции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5425,'Когда кефир перестанет пениться, насыпать соль, сахар, вбить яйца, добавить растительное масло. Взбить вилкой. Медленно насыпать муку, замесить тесто, оно не должно прилипать. Отделять от теста маленькие куски, сделать лепешки, а из них пирожки. Пожарить быстрые пирожки на кефире на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5426,'Поделить тесто пополам. Из каждой части сформировать пласт. Поверхность тола посыпать сахаром, на него положить пласт, прижать его немного к сахару. Сверху тоже посыпать сахаром. На глаз определить центр теста, скатать его в рулетик до середины. Сделать тоже с противоположной стороны. Во время сворачивания подсыпать сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5426,'Порезать получившийся рулетик на печенья по 1,5 сантиметра в ширину. Переложить на противень, застеленный специальной бумагой, на расстоянии четыре сантиметра друг от друга. Повторить процедуру со вторым пластом. Отправить в разогретую духовку. Готовить печенье «Слоеные ушки» минут тридцать, соблюдая температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5427,'Нагреть до двухсот градусов духовку. Мясо со всех сторон посыпать перцем, солью. Обжарить филе на разогретой сковороде. Соединить прессованный чеснок со сливками, положить горчицу, тимьян, посыпать чуть-чуть перцем и солью. Размешать. Мелко натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5427,'Готовое филе переложить в формочку для выпекания. Вылить сверху сливочный соус. Посыпать сыром. Минут на двадцать отправить духовку. Чтобы мясо было сочным, важно его не передержать. Подавать горячим. В качестве гарнира для куриного филе в сливочном соусе подойдет лучше всего картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6946,'Из теста сделать колбаску, порезать на кружочки. Положить простое печенье на противень, готовить минут десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5428,'Измельчить крабовое мясо, нашинковать капусту. В капусту добавить сок лимона, размешать, минут пять дать настояться. Смешать в глубокой посуде капусту, крабовое мясо, кукурузу без жидкости. Перемешать капустный салат с крабовыми палочками, заправить майонезом. Салат схож с классическим крабовым, но с капустой. Получается приятный, свежий вкус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5429,'Смешать сметану с сахаром, перетереть творог также с сахарным песком. Все соединить. Развести желатин так, как написано на упаковке, влить в творожно-сметанную массу. В разъемную форму выложить любые фрукты, например, порезанную клубнику и кусочки банана. Залить массой и поставить в холодильник до застывания. При подаче творожно-фруктовый десерт-желе выложить на блюдо и нарезать на порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5430,'Промыть грудки и нарезать на порции. Посолить, посыпать молотым черным перцем, тертым имбирем, натереть карри и давленым чесноком, добавить соевый соус. Оставить мясо для маринования на один час. На сковороде разогреть небольшое количество растительного масла, добавить мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5430,'Прогреть до однородного состояния. Выложить грудки, жарить на медленном огне до золотистой корочки со всех сторон. В конце жарки куриные грудки по-восточному посыпать семечками кунжута, перемешать, еще немного прогреть и снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5431,'Какао-порошок и сахар смешать, влить немножко кипятка, мешать пока консистенция не станет однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5431,'К полученной массе, все время помешивая, добавить оставшийся кипяток, горячие сливки либо молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5431,'Какао на горячем молоке или сливках при подаче можно украсить корицей и взбитыми сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5432,'Филе освободить от костей, нарезать кусочками среднего размера. Порезать репчатый лук полукольцами, обжарить до золотистого цвета, добавить курицу, жарить пять минут на среднем огне. Посолить, всыпать немного черного перца, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5432,'Перемешать и еще обжарить. Для приготовления соуса смешать молоко, немного муки, рубленый чеснок. Соль, перец молотый – по вкусу. Полученной смесью залить блюдо, прогревать под крышкой, помешивая. В конце приготовления курицу с чесноком в молоке посыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5433,'Сырое куриное филе нарезать на куски, которые поместятся в двухлитровой стеклянной банке. Натереть мясо солью и перцем. Сложить куски в сухую чистую банку на три четверти объема, пересыпать слои тонко нарезанным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5433,'Сверху – несколько лавровых листочков, накрыть несколькими слоями фольги, прижать ее к мясу. Поставить банку в холодную духовку, включить температуру до 180 – 200 градусов. Прогреть курицу в собственном соку в этом режиме два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5434,'Нарезать репчатый лук мелкими кубиками. Соединить говяжий фарш, нарезанный лук, сырое яйцо, приправу Хмели-сунели, соль по вкусу. Перемешать. Сформовать плоские котлеты такого же диаметра, что и готовые булочки для бургеров, выложить на лист пищевой пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5434,'Сверху бутерброды также накрыть пищевой пленкой, переложить в морозильную камеру. Булочки разрезать поперек на две равные части. Обжарить их на растительном масле до образования румяной корочки и остудить. Для соуса перемешать майонез и готовую горчицу. Намазать смесью срезы булочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5434,'Разогреть на сковороде рафинированное растительное масло, выложить котлеты из морозилки, обжарить по 5 –7 минут с каждой стороны, вторую сторону обжарить под крышкой. Вымыть и обсушить бумажными полотенцами листья зеленого салата, разложить их на нижние части булочек, поверх – котлета и ломтик сыра, затем ломтик помидора, красный лук, нарезанный кольцами. Накрыть чизбургер по-домашнему второй частью булочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5435,'Растереть сырые яйца с сахарным песком и ванилином. Влить стакан кефира, всыпать просеянную муку, добавить соду, погашенную уксусом. Перемешать. Готовое тесто разделить на две части, в одну добавить какао-порошок. Выпечь в формах два коржа, «белый» нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5435,'Приготовить сметанный крем: взбить миксером сметану с сахаром. Обмакнуть в него кубики светлого коржа. Остальной частью смазать темный, шоколадный корж, выложить в него кусочки в сметанном креме в виде горки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6947,'Взять нарезку телятины. Обмотать каждый кусочек мяса беконом или сырной ветчиной, закрепить ниткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5435,'Для приготовления глазури налить молоко в кастрюлю, вскипятить. Добавить сахарный песок, какао, варить в течение четырех минут. Положить сливочное масло, прогревать еще три минуты. Залить торт «Ванька кучерявый» готовой глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5436,'Расстелить на ровной поверхности макису, обернуть ее пищевой пленкой. Лист нори разрезать пополам, положить параллельно пластинкам циновки из бамбука, блестящая сторона должна быть внизу. Смочить руки рисовым уксусом, готовый отваренный рис распределить по листу водорослей плотно и ровно. Дальний край на один сантиметр оставить без риса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5436,'Натереть сыр «Пармезан» и посыпать им массу сверху. Лист нори перевернуть, рис должен оказаться внизу, положить немного соуса Васаби посередине. Плавленый сыр нарезать квадратами, уложить по поверхности ролла. Отрезать острым ножом под небольшим углом кусочек семги толщиной восемь миллиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5436,'Рыбу выложить вдоль листа нори. Добавить отваренные отдельно креветки в качестве начинки. Скатать роллы, начинку придерживать пальцами. Выложить роллы с семгой и креветками на блюдо и нарезать. Украсить свежими помидорами и тобико.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5437,'Для приготовления коржей замесить тесто из пяти яиц, стакана сахара, соды, погашенной уксусом, щепотки ванилина и стакана муки. Яйца с сахаром предварительно взбить в пену. Размешать и выложить массу в смазанную форму с высокими бортами. Готовность выпечки проверить зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5437,'Готовый корж с помощью острого ножа разрезать вдоль на две половины. Крошки оставить для посыпки. Для приготовления темных коржей смешать ингредиенты в тех же пропорциях, но добавить какао-порошок. Готовую выпечку также разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5437,'Для крема растереть добела мягкое сливочное масло. Смешать отдельно молоко с мукой и сахарным песком, поставить на тихий огонь, прогреть, до кипения не доводить. Массу охладить. Добавлять в масло эту смесь по одной столовой ложке, взбивать. Влить ложку коньяка и щепотку ванили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5437,'Промазать полученным кремом коржи, чередуя цвета. Торт «Кудряш» обмазать заварным кремом. Смешать крошки разного цвета и обсыпать выпечку со всех сторон. Поставить готовое блюдо в холодильник на ночь для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5438,'Для бисквита хорошо просеять муку. Отделить белки от желтков. Белки взбить с сахаром, добавить ванилин. Когда масса станет густой – добавить желтки, по ложке, продолжая взбивать. Вмешать в массу муку порциями, перемешивать осторожно, тесто должно остаться воздушным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5438,'Вылить тесто в смазанную форму, поставить в духовку, печь в течение 25 минут при температуре 190 – 200 градусов. При готовности духовку выключить и дать постоять бисквиту еще пять минут при закрытой дверце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5438,'Для начинки хорошо размять творог, добавить сметану, размятый банан, взбить. Выпеченный корж разделить на три части, промазать вареньем, выложить начинку из творога, сверху на торт «Любимый» – дольки бананов, тертый шоколад.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5439,'Рыбу вымыть, почистить и выпотрошить. Залить тушки холодной водой на два часа. Нарезать скумбрию на порционные куски, сложить в емкость, посолить, поперчить, добавить сахар по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5439,'Снова залить рыбу холодной кипяченой водой, накрыть тарелкой, поставить под небольшой гнет на сутки в холодильник. Хранить приготовленную слабосоленую скумбрию можно в течение двух-трех дней в маринаде, затем переложить в банки и залить растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5440,'Отварить и нарезать куриную грудку кубиками. Обжарить шампиньоны с луком, соль и перец молотый – по вкусу. Отварить и натереть морковь. Натереть яблоко без кожицы и семян, измельчить грецкие орехи. Отварить яйца, желтки и белки измельчить отдельно, натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5440,'Уложить ингредиенты на блюдо, каждый слой промазать майонезом, верх посыпать тертым куриным белком. Из отваренной моркови вырезать тонкие ленты, оформить салат «Подарок» бантом, половинками черри, зеленью петрушки и укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5441,'Отделить желтки от белков. Желтки взбить с сахаром до состояния светлой массы, белки взбить отдельно до плотной пены. Взбить жирные сливки. Все три массы аккуратно смешать. Добавить рубленые фисташки, апельсиновые цукаты, любые свежие или размороженные ягоды, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5443,'Для приготовления теста смешать сливочное масло с сахарным песком и растереть полученную смесь добела. Добавить сырые яйца, соду, погашенную уксусом или лимонным соком, аккуратно перемешать. Добавить просеянную муку, тесто должно быть мягким. Поставить его в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5443,'Очистить грецкие орехи. Отщипнуть от готового теста небольшой кусочек, положить орех в середину, скатать шарик. «Орешки» печь на противне в течение получаса при температуре 220 градусов. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5443,'Для приготовления крема взбить сметану с сахаром. Каждый «орешек» обмакнуть в этот крем, выложить на блюдо в форме горки. Растопить горький шоколад и полить верх торта, имитируя стекающую «лаву». Торт «Вулкан» должен постоять несколько часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5444,'Для приготовления пирога понадобится замороженная вишня или ягоды из компота, в том и другом случае нужно отцедить жидкость, удалить косточки, если они есть. Начинку можно «разбавить» ежевикой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5444,'Для теста смешать сырые яйца, мягкое сливочное масло, сахар, перемешать с помощью венчика или миксера. Добавить сметану, разрыхлитель, просеянную пшеничную муку. Вымесить, массу можно дополнительно взбить миксером. Выложить тесто в смазанную маслом форму, сверху – вишневая начинка. Посыпать кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5444,'Печь в духовке в течение 20 – 25 минут, до румяного цвета. Приготовить кокосовую глазурь: соединить сахар и сметану, ванилин и стружку, хорошо перемешать. Испеченный пирог полить смесью и печь еще 20 – 30 минут, остудить. Пирог «Вишневый шик» лучше подавать холодным, его можно подержать в холодильнике несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5445,'Хорошо взбить белки, ввести желтки по одному, снова взбить. Добавить частями просеянную муку и цедру лимона, перемешать. Форму для выпечки застелить бумагой, вылить тесто. Печь 30 – 35 минут при температуре 190 – 200 градусов. Остудить и разрезать на два равных коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5445,'Для крема: замочить желатин в небольшом количестве воды. Отдельно смешать творог со сливками, всыпать сахарную пудру. Смесь взбить в блендере, добавить любые консервированные фрукты, нарезанные небольшими кусочками, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5445,'Один из коржей переложить в разъемную форму, сверху – творожная масса, накрыть вторым коржом. Дать постоять в холодильнике около шести часов. При подаче сладкий бисквит с творожным кремом посыпать сахарной пудрой, можно использовать бумажные шаблоны, чтобы получились белые фигурки на светло-коричневом фоне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5446,'Мелко нарезать помидор и листья зеленого салата. Натереть твердый сыр. Разделать куриную грудку на мелкие кусочки и потушить в течение 20 минут на тихом огне. Жидкость должна выпариться, затем мясо можно немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5446,'Смешать ингредиенты, добавить консервированную красную фасоль без жидкости. Заправить салат с фасолью и куриной грудкой легким майонезом или сметаной. При подаче салат посыпать готовыми сухариками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5447,'Для приготовления коржа смешать крошку от печенья, мягкое сливочное масло и сахар. Массу выложить и утрамбовать на дне круглой формы. Печь в течение 8 – 10 минут до образования золотисто-коричневой корочки. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5447,'Для начинки разогреть и довести до кипения сливочное масло, ванилин и коричневый сахар. Проварить, добавить сгущенное молоко. Прогревать на среднем огне, при постоянном помешивании, в течение 3 – 4 минут. Снять с огня и вылить на корж-основу. Поставить в холодильник на два часа, масса должна полностью охладиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5447,'Взбить в миксере готовые взбитые сливки с сахарной пудрой и ванилином. Тонко нарезать спелый банан, добавить к сливкам и перемешать. Выложить смесь на основу, охладить в течение часа и подать. При подаче Пирог «Баноффи»  украсить тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5448,'Вымыть клубни, положить в холодную воду, довести до кипения, варить шесть минут. Картофель остудить и очистить от кожуры. Куриную грудинку промыть, обсушить бумажными полотенцами, порезать большими кусками. Очистить и нарезать шампиньоны, репчатый лук – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5491,'Морепродукт вынуть, откинуть на дуршлаг, нарезать кольцами или полосками шириной в 1 см. Для приготовления кляра смешать муку с молоком, добавить яичные сырые белки, снова перемешать, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5448,'На разогретой сковороде с растительным маслом обжарить куриное мясо до образования румяной корочки, выложить на тарелку. В той же сковороде обжарить лук, добавить грибы, прогревать до выпаривания жидкости. Всыпать муку, не переставая помешивать, влить молоко, перемешанное со сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5448,'Добавить обжаренное куриное мясо, соль, перец. В огнеупорную форму выложить полученную массу, сверху – тертый на крупной терке картофель. Блюдо посыпать большим количеством тертого твердого сыра. Печь куриную грудку с грибами под шубой из картофеля на среднем огне в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5449,'Нашинковать полкочана свежей пекинской капусты. Мелко порезать крабовые палочки и консервированные ананасы. Смешать очищенные коктейльные креветки с остальными ингредиентами, добавить зернышки граната. Заправить салат «Стрелы Амура» майонезом, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5450,'Приготовить шесть видов различных цветных желе, как написано на упаковке. Поставить в холодильник до застывания. При готовности нарезать на кубики острым горячим ножом, перемешать. Отдельно растворить два пакетика желатина, полстакана холодной воды, дать набухнуть в течение двух минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5450,'Добавить в смесь кипяченую воду и перемешать. Влить банку сгущенного молока, смесь еще раз перемешать и охладить. Холодную массу вылить на желе и поставить десерт на ночь в холодильник. При подаче нарезать десерт-желе на квадраты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5451,'Просеять муку, добавить сахарный песок, щепотку соли, яйца, сок, молоко. Взбить массу вручную или с помощью миксера до однородности. Очистить яблоки от сердцевины и кожуры, нарезать кольцами толщиной 1,5 – 2 см. Присыпать молотой корицей. Обвалять в муке, затем обмакнуть в кляр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5451,'Жарить на разогретом растительном масле с двух сторон до золотистого цвета. «Колечки» выложить на бумажные полотенца, удалить, таким образом, лишний жир. При подаче яблоки в кляре посыпать сахарной пудрой. К десерту – ванильное мороженое, взбитые сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5452,'Мелко нарезать зеленый лук. Натереть сыр «Российский», нарезать кусочками ветчину. Все ингредиенты смешать, добавить сырое яйцо для связки. Готовое слоеное тесто раскатать, нарезать небольшими прямоугольниками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5452,'Выложить луковую начинку, смазать водой края, свернуть пополам и залепить. Пирожки должны получиться квадратной формы. Смазать верх пирожков с зеленым луком и ветчиной взбитым яйцом, печь около получаса при температуре 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5453,'Кастрюлю наполнить водой, добавить топленое масло и сахар, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5453,'Все время помешивая, ввести муку, взбивать массу до полного отлипания теста от кастрюли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5453,'Снять тесто с плиты и немного охладить, не переставая мешать ввести яйца, добавить соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5453,'В отдельной кастрюле закипятить жир, в него, зачерпывая ложкой, класть тесто, готовить до появления румяной  корки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5453,'После приготовления заварные пышки по-домашнему нужно выложить на бумагу, чтобы в нее впитался весь жир.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5454,'Сырые яйца взбить в миксере с сахарным песком и ванилином в течение 5 – 10 минут на большой скорости. Масса должна увеличиться в объеме в 3 – 4 раза. Всыпать порциями хорошо просеянную муку, перемешать массу аккуратно, движениями сверху вниз. Форму для выпечки застелить бумагой, смазать маслом и присыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5454,'Вылить тесто в форму, верх закрыть фольгой. Печь при температуре 170 градусов около получаса, затем убавить до 150 градусов и печь еще 25 – 30 минут. Дверку духовки не открывать. Готовому ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5455,'Растереть сахар с яйцами и ванилином из пакетика. Добавить растопленное сливочное масло, сметану, взбить. Всыпать муку, просеянную вместе с разрыхлителем. Взбить до образования однородной массы вручную или с помощью миксера. Формы для выпечки заполнить тестом на две трети объема. Печь ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5456,'Соединить мясной фарш, отваренный до полуготовности рис так, как написано на упаковке. Отдельно измельчить и обжарить репчатый лук. Белую булочку замочить в воде на несколько минут, отжать. Перемешать ингредиенты в однородную массу, сформовать небольшие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Выкладываем котлеты на сковородку и ударной дозой огня заставляем их подрумяниться, как и положено котлетам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5456,'Форму для запекания смазать сливочным маслом, поставить в духовку на 15 – 20 минут, печь при температуре 160 градусов. Залить стаканом сливок, соль – по вкусу. Тушить мясные тефтели с рисом в духовке еще 40 минут при температуре 170 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5457,'Очистить от пленок говяжью печень, нарезать на кусочки и перемолоть в блендере или через мясорубку. Добавить сырые яйца, молоко, соль и перец – по вкусу. Всыпать муку и перемешать до однородного состояния. «Тесто» должно быть полужидким. Для приготовления начинки натереть морковь, порубить лук, обжарить то и другое на растительном масле до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5457,'Добавить в массу рубленый чеснок и майонез по вкусу. На разогретой сковороде обжарить печеночные блинчики с двух сторон. Прослоить торт «Печеночный» полученной овощной начинкой и дать немного постоять для пропитывания при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5458,'Сырые яйца взбить с сахарным песком, добавить мёд, мягкое сливочное масло или маргарин. Массу поставить на огонь, довести до кипения, снять с огня. Всыпать пищевую соду и вновь прогреть на плите, помешивать, масса должна увеличиться в два раза. Снять кастрюлю с огня и всыпать муку. Перемешать, дать остыть до 40 градусов. Тесто должно получиться средней густоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5458,'Раскатать тонкие коржи, выпечь до светло-коричневого цвета. Количество может быть разным: от четырех до восьми. Для приготовления крема перемешать молоко, сахар, сырые яйца, муку или крахмал, смесь довести до кипения, остудить. Добавить растопленное сливочное масло. Массу взбить венчиком или с помощью блендера . Коржи промазать полученным кремом и поставить торт «Рыжик» в холодильник для пропитывания на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5459,'Желатин залить небольшим количеством воды, оставить на 20 минут для набухания, затем прогреть. Влить в сметану сгущенное молоко, всыпать ванилин из пакетика. Перемешать до однородного состояния все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5459,'Полученную смесь разделить на две части, в одну добавить какао-порошок. Силиконовые формочки заполнить сначала темной смесью, затем разлить белую массу, накрыть пищевой пленкой и поставить в холодильник. При подаче формочки перевернуть на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5460,'Натереть на мелкой терке сырую морковь, на крупной – любые плавленые сырки. Чеснок порубить или пропустить через пресс. Массу заправить майонезом и поперчить по вкусу. Выложить полученную закусочную массу в готовые тарталетки, в середину положить по консервированной маслине, вдавить её внутрь начинки. Придать смеси форму шарика, украсить веточкой зелени или рубленым зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5461,'Крупные яблоки очистить от кожуры, удалить сердцевину, нарезать кружками толщиной в один сантиметр. Обжарить их на растительном масле с двух сторон до золотистого цвета в течение нескольких минут, кружочки должны сохранить форму. При обжаривании фрукт можно немного посыпать сахарным песком, тогда он карамелизуется.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5461,'Нарезать кольцами репчатый лук, обжарить до зарумянивания в том же масле, в котором жарились кружки яблок. Выложить на тарелку. Очистить от пленок и сухожилий телячью печень. Нарезать кусочками, обвалять в муке. Обжарить в том же масле, что и лук, по две-три минуты с каждой стороны, добавить соль по вкусу. Выложить на блюдо телячью печень, сверху – яблоки и лук, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5462,'Белокочанную или пекинскую капусту мелко порезать, немного перетереть руками, чтобы стала мягче и дала сок. Если белокочанная капуста жестковата, её можно предварительно залить кипятком на пять минут или поварить 10 минут при слабом кипении. Дать стечь воде, откинуть на дуршлаг. Для теста взбить сырые яйца с сахарным песком, солью и молотым перцем. Добавить пшеничную муку, просеянную вместе с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5462,'Тесто должно получиться полужидким. Перемешать тесто с капустой, выложить массу в смазанную маслом или застеленную бумагой форму для выпечки. Затянуть фольгой, печь в духовке в течение 40 минут при температуре 220 градусов. Фольгу снять, шарлотку из капусты допечь до образования румяной золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5490,'Молоко довести до кипения, остудить до комнатной температуры. Всыпать сахарную пудру, положить мягкое сливочное масло, ванилин из пакетика. Взбить массу с помощью миксера или вручную, венчиком, до однородного состояния в течение 3 – 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5463,'Перемолоть в блендере пшеничные хлопья в мелкую крошку. Добавить молотую паприку, красный жгучий и душистый перец, соль. Массу перемешать. Куриные грудки обвалять в полученной острой смеси, выложить на смазанный противень. Печь в течение 8 – 10 минут, перевернуть, потушить чикен наггетс  в духовке еще пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5464,'Обжарить на масле нарезанное филе осетрины, добавить нашинкованный лук, порезанные грибы, томатную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5464,'Поместить в кастрюлю полученную смесь, посолить, добавить перец, немного воды, горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5464,'Тушить в районе 20 минут до полной готовности рыбы, затем добавить сметану и готовить 3-5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5464,'Кастрюлю снять с огня, гуляш из рыбы с грибами по-русски разложить по тарелкам, украсить измельченной петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5465,'Отварить спагетти в кипящей воде с солью и небольшим количеством оливкового масла. Нарубить чеснок, выжать сок лимона, четверть плода нарезать ломтиками. Лимон и сок перемешать с рубленой зеленью петрушки, хлопьями красного перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5465,'На растопленном сливочном масле обжарить измельченный чеснок, выложить очищенные креветки, соль и перец – по вкусу. Прогревать в течение пяти минут, снять с огня. Влить острую смесь с лимоном. Пасту отцедить, переложить в сковороду с креветочной смесью и хорошо перемешать спагетти с креветками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5466,'Соединить сырое яйцо с молоком и солью, взбить вилкой. На кусочек хлеба для тостов положить ветчину и сыр, нарезанные тонкими пластинками, накрыть другим кусочком хлеба. Разрезать получившийся сэндвич на два равных треугольника. Разогреть на сковороде растительное масло. Бутерброды быстро обмакнуть в яично-молочную смесь, обвалять в панировочных сухарях, жарить с двух сторон. Подать гренки с начинкой в горячем виде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5467,'Нарубить ножом куриную грудку, чеснок, репчатый лук, зелень петрушки и укропа. Всыпать молотый черный перец, соль по вкусу, куркуму. Добавить взбитое вилкой яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5467,'Разогреть масло на сковороде, котлеты выкладывать ложкой. Обжарить с одной стороны на сильном огне в течение одной-двух минут, перевернуть, тушить под крышкой с другой стороны еще три-четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5468,'На тонкий лаваш намазать мягкий плавленый сыр Виола или Хохланд, Президент. Сверху – тонкие пластинки слабосоленой семги или форели. Плотно свернуть рулет и убрать в холодильник на три-четыре часа для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5469,'Готовый зефир поломать на кусочки, взбить в блендере вместе со сливками до однородного состояния. Порезать на четвертинки клубнику, очистить и нарезать кубиками киви. В чашку или креманку выложить клубнику и киви, прослоить зефирным кремом. Сверху десерт посыпать тертым шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5470,'Тонко нарезанный соломкой бекон и мелко нарубленную луковицу обжарить на оливковом масле в течение 5 – 10 минут на тихом огне. Влить белое сухое вино, прогреть две-три минуты. Затем всыпать картофель, нарезанный кубиками, тушить в течение 10 – 15 минут. Специи, соль – по вкусу. Влить сливки, прогреть еще минуту и снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5470,'Половину обжаренной массы выложить в блюдо для запекания, затем слой тертого рассольного сыра Реблошон, снова картофельно-сырная смесь. Печь до образования золотистой корочки в течение 30 – 45 минут. Картофель «Тартифлетт» с беконом подать горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5471,'Печень очистить от пленок, нарезать на кусочки и пропустить через мясорубку. Добавить молоко, яйца, растительное масло и пшеничную муку. Массу перемешать до однородного состояния, выпечь блинчики на смазанной растительным маслом сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5471,'Отдельно обжарить измельченные лук и морковь, нарезать соленые огурцы. Печеночные блинчики выложить на тарелку, промазать майонезом с чесноком и прослоить обжаренными овощами и огурцами. Сверху – морковь и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5472,'Натереть сыр, измельчить чеснок или пропустить его под пресс. Смешать оба ингредиента, заправить по вкусу майонезом. Тонко нарезать ветчину, на середину ломтиков выложить полученную начинку, скатать в рулет и заколоть зубочисткой или декоративной шпажкой. Отварить яйцо, очистить, натереть, посыпать рулетики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Огонь уменьшаем, доливаем воды в сковороду и тушим уже на небольшом огне до полной готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5473,'Смешать яйцо с сахаром, взбить немного вилкой или венчиком. Влить молоко и масло, снова взбить. Отдельно смешать просеянную пшеничную муку, картофельный крахмал, какао-порошок и разрыхлитель, всыпать в яичную смесь и замесить тесто. Дно формы для запекания выложить пергаментом или бумагой для выпечки, вылить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5473,'Печь в микроволновой печи в течение трех минут. Аккуратно отделить корж от формы ножом по краю, перевернуть выпечку на решетку, остудить. Выпечь два белых и один темный корж. Для приготовления крема взбить сметану с сахарным песком, положить вишню без косточек, промазать массой коржи бисквита «Макро в микро».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5474,'Говяжьи почки вымыть, убрать сало и все лишнее, нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5474,'Мелко порезать очищенный лук и огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5474,'В кастрюлю с водой сложить почки, отварить до полуготовности, затем добавить огурцы, лук, соль, перец и варить до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5474,'Подается калья из говяжьих почек заправленная сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5475,'Протереть в пюре творог с бананами, добавить сахарный песок, соль, взбить. Всыпать муку, сырые яйца, сметану, продолжать взбивать после добавления каждого ингредиента. Вылить смесь в форму для выпечки, печь в течение 1 часа 10 минут при температуре 150 градусов. Дать остыть и поставить на ночь в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5476,'Смешать сырое яйцо, молоко, растительное масло, взбить. Добавить какао-порошок, снова взбить, затем всыпать сахарный песок, взбить, просеянную пшеничную муку и щепотку соли по вкусу. Хорошо вымешанную массу поставить в микроволновую печь на три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5477,'Консервированные ананасы отцедить от жидкости, выложить на блюдо. Кусочками листьев зеленого салата прикрыть дырочки посередине ломтиков. Для приготовления начинки нарезать кубиками вареные яйца, крабовые палочки, твердый сыр. Заправить по вкусу майонезом. Выложить начинку на ананасы горкой, подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5478,'Молоко налить в толстостенную эмалированную или керамическую посуду, варить на тихом огне до получения кремового цвета. Жидкость необходимо постоянно помешивать. Топленое молоко охладить, влить сметану, хорошо перемешать и поставить на два-три часа для загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5479,'Нарезать свежие шампиньоны, обжарить на небольшом количестве растительного масла, соль и перец – по вкусу. Натереть сырую морковь, обжарить до мягкости и посолить. Отварить куриное филе, в воду добавить соль и лавровый лист, перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5479,'Отварить картофель и яйца, натереть на терке по отдельности. Нарезать и обжарить лук. Выложить салат слоями: картофель, грибы, майонез «сеточкой», кусочки отваренной курицы.  Затем обжарку из лука и моркови, снова майонез, яйца, тертый твердый сыр, майонез. При подаче салат «Бонапарт» можно украсить грибами и зеленью, блюдо можно охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5480,'Нарезать соломкой ветчину, натереть на крупной терке твердый сыр, яблоко без кожуры и сырую морковь. Добавить сухарики, заправить массу майонезом, добавить раздавленный зубчик чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5481,'Кефир перемешать с пищевой содой, смесь оставить на пять минут. Добавить сырые яйца, соль, стакан муки. Массу хорошо перемешать. Начинка: сырое, прокрученное через мясорубку, мясо, кубики лука. Молотый перец, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5481,'Форму для выпекания смазать маслом, присыпать мукой и вылить половину полученного теста. Выложить мясную начинку, залить оставшимся тестом. Печь пирог «Быстрее и легче не бывает» в течение 40 минут при температуре 170 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5482,'Куриную или телячью печень отварить, натереть на крупной терке. Куриную можно не тереть, а порезать мелкой соломкой. Маринованные огурцы нарезать мелкими кубиками. Отварить и натереть на крупной терке морковь. Репчатый лук нарезать мелкими кубиками, обжарить на сковороде с маслом до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5482,'Отварить яйца, белки натереть. Выложить салат слоями в блюдо с высокими бортиками прямоугольной или овальной формы. Порядок слоев: половина печени, майонез, половина луковой обжарки, половина маринованных огурцов, морковь. Сверху – морковь, майонез, белки, майонез. Слои печени, лука и огурцов повторить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Очистить говядину от пленок и сухожилий, разрезать на 5 пластин, отбить каждую с двух сторон, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5484,'Сливочное масло комнатной температуры взбить с сахарным песком, влить сырое яйцо, молоко, всыпать разрыхлитель. Добавить пшеничную муку, замесить тесто, оно должно получиться мягким. Раскатать массу в пласт толщиной 6 – 7 мм. Выдавить лепешки с помощью формочки для кекса. Переложить их на противень, печь при температуре 180 – 200 градусов в течение 15 минут. Выпечка должна зарумяниться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5485,'Куриное филе промыть и обсушить с помощью бумажных полотенец. Нарезать на небольшие кусочки. Пшеничную муку смешать с солью, перцем, специями. В смеси обвалять мясо и обжарить на масле со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5485,'Нарезать мелко репчатый лук, лесные грибы. Обжарить лук, затем добавить грибы и обжарить все вместе. Очистить и нарезать картофель кубиками средней величины, выложить их на дно горшочков для запекания. Поверх – обжаренное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5485,'Натереть твердый сыр, добавить к нему сметану, любые специи, давленый чеснок, немного воды и рубленую зелень укропа, петрушки, кинзы, перемешать. Залить смесью мясо с картофелем. Печь картофель с грибами и куриным филе в горшочке в духовке при температуре 230 градусов в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5486,'Свиное или куриное мясо хорошо отбить. Приготовить смесь из майонеза, аджики, перца и чеснока, соль – по вкусу. Смазать мясо и оставить для маринования на два часа. Лесные грибы обжарить с репчатым луком, по окончании посолить, поперчить, положить майонез и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5486,'Натереть сырок Дружба, добавить тертый чеснок, майонез, сырое яйцо, соль, по щепотке куркумы и карри. Можно добавить любые другие приправы, перемешать. Смазать противень маслом, выложить мясо, нарезанное кусочками, по краю – помидоры кружочками, грибы. Сверху вылить яичную смесь. Печь свинину с грибами около получаса при температуре 250 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5487,'Вымыть апельсины и лимоны, залить кипятком, через 5 – 10 минут фрукты вытащить. С трех апельсинов и всех лимонов снять цедру с помощью острого ножа или теркой. Отжать сок, это можно сделать вручную, разрезав плоды на дольки, или с помощью соковыжималки. Сок вылить в большую посуду, добавить воду и цедру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5487,'Оставшуюся белую часть кожуры завернуть в марлю и опустить в смесь. Варить массу в микроволновой печи в течение 20 – 25 минут на полной мощности. Кожура должна стать мягкой, её нужно отжать и выбросить. Всыпать сахарный песок, перемешать, варить еще полчаса на той же мощности. Апельсиново-лимонный джем должен увариться, загустеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5488,'Смешать с оливковым маслом панировочные сухари, соль и перец – по вкусу. Выложить массу ровным слоем в емкость для запекания, печь при температуре 190 градусов в течение 5 – 10 минут. Сухари должны приобрести золотистый цвет. Остудить, посыпать тертым сыром Пармезан. Запечь красный болгарский перец, его и консервированные в собственном соку помидоры взбить в крошку в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5488,'Баклажан обвалять в соли, положить на бумажное полотенце, печь в микроволновой печи 10 минут. Подсушенный овощ остудить, порезать на кубики, перемешать с оливковым маслом. Еще немного масла разогреть в глубокой сковороде, обжарить кубики баклажана в течение 10 минут, помешивать. Переложить обжарку в другую посуду. В ту же сковороду добавить еще немного масла, прогреть рубленый чеснок, орегано и хлопья красного перца. Добавить томатное пюре с перцем, соль, увеличить огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5488,'Влить воду и всыпать макароны, «спиральки» или «пружинки». Тушить под крышкой до готовности пасты. Если соус получился слишком густым – влить еще полстакана воды. В готовую массу всыпать стакан тертого сыра Пармезан, баклажаны, соль и молотый перец. Перемешать, сверху выложить сыр Моцарелла, посыпать сухарями и запечь сырную пасту в духовке до расплавления сыра и образования румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5489,'В подсоленной воде отварить куриное филе, хорошенько остудить, порезать соломкой, сложить в салатник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5489,'Нарезать кубиками картофель, огурцы – соломкой, яйцо потереть на крупной терке, измельчить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5489,'К куриному мясу добавить овощи, яйцо, горошек, петрушку, перец и соль, все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5489,'Майонез, томатную пасту и лимонный сок смешать, полученным соусом заправить блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5489,'Украсить Салат из курицы с овощами по-уральски зеленью, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5491,'Разогреть масло в сковороде с толстым дном до средней температуры. Кольца кальмара обмакивать в кляр и жарить до золотистого цвета. Выкладывать кальмары в кляре на бумажные полотенца для удаления излишков жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5492,'Очистить и натереть кабачок. Добавить пшеничную муку, манную крупу, сырые желтки и соль. Массу хорошо перемешать и испечь блинчики. Куриный фарш перемешать со взбитыми белками, влить молоко, соль и перец – по вкусу. Испечь куриные блинчики того же размера и толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5492,'Обжарить тертую морковь и нарезанный репчатый лук. Добавить любую рубленую зелень, чеснок и майонез. Тонкими кружками нарезать помидоры. Выложить на дно блюда кабачковый блин, на него – куриный, затем слой овощной обжарки и помидоры. Слои повторить несколько раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5493,'Взбить яйца с сахаром, масса должна побелеть и увеличиться в объеме. Добавить сметану, перемешать. Влить растопленное охлажденное сливочное масло, ванилин из пакетика. Всыпать просеянную пшеничную муку и любые молотые орехи, гашеную уксусом или лимонным соком пищевую соду. Готовое тесто разделить на две части, в одну всыпать столовую ложку какао-порошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5493,'Выпечь два коржа при температуре 160 градусов в течение получаса, каждый разрезать пополам. Для приготовления крема взбить жирную сметану с сахаром и ванилином. Массой прослоить коржи, верх и бока также смазать кремом и посыпать традиционный «Сметанник» рублеными орехами или крошкой, оставшейся от коржей. Дать постоять в течение 10 – 12 часов для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5494,'Скумбрию разморозить, выпотрошить через спину через разрез от головы до хвоста. С другой стороны спинного плавника также сделать надрез, отделить хребет, разрезать его у головы и хвоста и удалить. Вынуть внутренности, ребра, жабры, тушку хорошо вымыть щеткой. Порубить репчатый лук, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5494,'Добавить нарезанные шампиньоны или другие грибы, продолжать жарить до готовности. Отдельно потушить овощи, можно использовать замороженную овощную смесь: цветную капусту, горох, стручковую фасоль, цветную капусту, морковь. Соль и перец – по вкусу. Овощи соединить с грибной обжаркой и рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5494,'Рыбное филе выложить брюшком на смазанный противень, возле хвоста половинки филе сколоть зубочистками, чтобы рыба приняла форму лодочки. Соль, перец молотый – по вкусу, сбрызнуть рыбу лимонным соком. Выложить фарш, посыпать тертым твердым сыром, залить сливками и печь скумбрию с шампиньонами в течение 20 – 25 минут в духовке при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5495,'Желатин из пакетика залить небольшим количеством холодной кипяченой воды, как указано на упаковке, оставить на час для набухания. Довести до кипения, но не кипятить, остудить. Взбить сливки с сахарным песком, добавить сыр маскарпоне, перемешать, влить желатиновую массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5495,'Печенье измельчить с помощью блендера  или пропустить через мясорубку. Растопить сливочное масло и перемешать с крошкой. Массу выложить в форму для выпекания средней величины, прижать руками, утрамбовать, поставить в холодильник. Сливочно-желатиновую массу выложить на основу, поставить чизкейк без выпечки в холодильник еще на 3 – 4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5496,'Отделить белки от желтков. Растереть в глубокой миске желтки с ванильным сахаром и стаканом обычного сахарного песка, влить молоко, перемешать. Отдельно развести картофельный крахмал в стакане воды, влить в яичную массу, перемешать, взбить до однородного состояния, поставить на водяную баню. Варить до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5496,'Готовый крем остудить, добавить мягкое сливочное масло, взбить миксером до пышности. Желатин из пакетика замочить в воде на 20 минут, прогреть на тихом огне, на водяной бане до полного растворения, помешивать. Процедить. Влить тонкой струйкой в крем, перемешивать. Отдельно взбить сырые белки с сахаром, добавить в массу и также перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5497,'Отварить куриное яйцо вкрутую. Порвать руками листья зеленого салата, промыть и выложить на блюдо. Нарезать помидоры, очищенный свежий огурец, несколько мелких маринованных огурчиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5523,'Можно предварительно опустить их в горячую воду. Смазать сырной массой и свернуть трубочками. Поверхность крабовых палочек «Очаровашки» смазать майонезом и посыпать тертыми желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5497,'Выложить все ингредиенты на листья салата, добавить мелкий маринованный репчатый лук. Полить маслом от лососевых консервов. Выложить сам лосось кусочками, сверху – кружки яйца, поперчить, украсить лососевый салат майонезом с помощью ложечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5498,'Творожный сыр смешать со сметаной до однородного состояния. Посолить по вкусу. Вымыть и обсушить редис, огурцы, сладкий болгарский перец. Перец нарезать соломкой, удалить семена. Огурец и редис натереть на терке, излишки влаги отжать. Ветчину также нарезать соломкой. Выложить ингредиенты слоями: перец, огурец, ветчина, редис. Каждый слой промазать творожной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5499,'Для блюда нужно взять одинаковое количество всех продуктов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5499,'Очищенные и отваренные овощи измельчить с помощью крупной терки, мелко покрошить вареные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5499,'В чистые бокалы или стаканы выложить слоями и промазать майонезом картофель, измельченный зеленый лук, морковь, порезанную мелкими кусочками рыбу, яйца, свеклу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5499,'Самый последний слой хорошенько промазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5499,'Украсить Слоеный салат «Новогодний» со скумбрией зернами граната, натертым желтком и поставить в холодильник, потом подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5500,'Смешать пшеничную муку с водой, в которой растворены сухие дрожжи. Добавить соль и сахарный песок. Накрыть тесто тканью и убрать на час в теплое место для набухания клейковины. Разогреть на сковороде немного растительного масла, печь постные оладьи на среднем огне с двух сторон по две минуты, под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5501,'Маринованный красный перец нарезать полосками, лук репчатый – полукольцами, маслины без косточек – на половинки. Смешать все ингредиенты, добавить заранее отваренную фасоль и консервированный зеленый горошек, зелень петрушки. Для заправки смешать оливковое масло, сок одного лимона, рубленый чеснок, соль и молотый перец – по вкусу. Залить смесью салат «Буковинский» и дать постоять 3 – 4 часа для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5502,'Куриную грудку нарезать небольшими кусочками, шампиньоны – кубиками. Добавить рубленый репчатый лук. В массу влить сырые яйца, сметану, всыпать свежую или сушеную зелень укропа, картофельный крахмал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5502,'Соль, молотый перец, рубленый зубчик чеснока – по вкусу. Котлеты из куриного филе с грибами выкладывать на сковороду ложкой, обжаривать с двух сторон под крышкой в течение нескольких минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5503,'Выпечь полтора десятка тонких блинчиков. Формочки для трубочек смазать растопленным сливочным маслом, обернуть готовыми блинчиками внахлест. Чтобы блинчики лучше держались в месте соединения, можно смазать их чуть взбитым яйцом или остатками теста. Излишки обрезать по форме конуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5503,'Печь в духовке до затвердевания, снять, остудить. Для приготовления начинки протереть творог через сито, смешать со сливками с сахаром, взбитыми в крепкую пену. В массу добавить цедру лимона или апельсина, ванилин. Наполнить творогом трубочки из блинчиков, полить растопленным на водяной бане шоколадом. Подать сразу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5504,'Немного взбить сырые яйца, смешать с растительным маслом. Перемешать вместе сухие дрожжи, соль, сахарный песок, всыпать в яичную смесь. Подогретое молоко разбавить водой и также влить в смесь. Всыпать просеянную пшеничную муку, замесить тесто, оно должно быть мягким по консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5504,'Выложить в смазанную маслом миску, накрыть полотенцем, дать тесту постоять, оно должно подойти, увеличиться в объеме. Для соуса смешать сметану с майонезом, добавить готовую столовую горчицу, рубленый чеснок, мелко нарезанную свежую петрушку, укроп или базилик. Молотый перец – по вкусу, влить немного лимонного сока и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5504,'На застеленный бумагой для выпечки противень выложить раскатанные лепешки для пиццы, их будет четыре штуки. На края положить сыр Моцарелла и завернуть внутрь, придавить. Наколоть коржи вилкой, смазать частью сметанно-майонезного соуса, посыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5504,'На сыр выложить любые продукты для пиццы: репчатый лук, колбасу Салями, грибы, сладкий болгарский перец, помидоры. Посыпать оставшимся тертым сыром и запечь домашнюю пиццу на белом соусе в течение 15 – 18 минут. Вынуть готовую выпечку, нарезать на порции и подать с оставшимся соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5505,'Отварить свежие кальмары в течение двух-трех минут. Тушки остудить, нарезать кольцами или полосками. Отварить неочищенные креветки с добавлением лаврового листа, душистого перца-горошка. Остудить и очистить. Морепродукты сбрызнуть лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5505,'Нарезать красный болгарский перец соломкой, порубить зеленую петрушку, нарезать маринованную морскую капусту. Все ингредиенты смешать, заправить салат «Балерина» оливковым маслом и поперчить по вкусу. Дать салату постоять в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5506,'Темный шоколад поломать на кусочки, залить молоком, прогреть до расплавления шоколада, как только масса начнет закипать – снять с огня. Отдельно растереть сырые яичные желтки, сахарный песок, картофельный крахмал и какао-порошок. Ввести эту смесь в горячую шоколадную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5506,'Если крем будет густоват, можно долить молоко. Емкость вновь поставить на тихий огонь, прогреть до загустения. Крем переложить в миску, добавить мягкое сливочное масло и взбить миксером или венчиком. Готовый десертный шоколадный крем разложить в вазочки, охладить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5507,'Отварить куриную грудку, для приготовления блюда понадобится бульон. Мясо вынуть, его можно использовать для приготовления другого блюда. Нарезать ветчину, отваренные молочные сосиски, добавить в бульон. Отдельно обжарить на растительном масле рубленый репчатый лук и тертую морковь. Обжарку добавить в бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5507,'Туда же положить порезанные маринованные огурцы, оливки и белые свежие грибы, разрезанные пополам. Положить в суп лавровый лист и другие специи, довести до кипения, варить на умеренном огне в течение 15 минут. При подаче в куриную солянку положить в кастрюлю ломтики свежего лимона и рубленую зелень петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5508,'Отварить картофель, воду слить, приготовить пюре с добавлением сливочного масла, остудить. Добавить тертый твердый сыр, «Российский» или «Пармезан», мелко нарубленную зелень укропа и муку. Должно получиться густое картофельное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5508,'Руки смочить в воде, сформовать круглые лепешки, положить на них пластинки маринованных шампиньонов в качестве начинки, края соединить. Котлеты обвалять в пшеничной муке и обжарить под крышкой на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5508,'Для приготовления соуса натереть свежий огурец и отжать от излишков жидкости. Пропустить чеснок через пресс, порубить зелень укропа. Влить сметану и майонез, соль – по вкусу. Хорошо перемешать. Подать соус к котлетам из картофеля и сыра с грибами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5509,'Картофель и лук помыть, почистить и отдельно потереть на любой терке, слить жидкость и смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5509,'В картофельную смесь ввести взбитое, посоленное, поперченное яйцо и все хорошо перемешать, в разогретое на сковороде масло выложить ложкой получившуюся массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5509,'Картофельные драники обжарить до румяной корочки на умеренно сильном огне, подавать горячими и со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5510,'Крупу промыть и выложить на смазанный маслом противень. Нарезать репчатый лук и чеснок, насыпать то и другое поверх гречки. Следующий слой – кусочки куриного мяса, посыпанные приправой хмели-сунели. Полить курицу сметаной, подлить в противень горячую подсоленную воду и посыпать тертым твердым сыром. Печь курицу с гречкой  в духовке в течение часа, до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5511,'Сливочное масло положить в сотейник, растопить в течение полуминуты. Всыпать рубленый репчатый лук, шампиньоны, подержать в СВЧ-печи три минуты под крышкой. Один раз перемешать. Отдельно взбить яйца, молоко, половину указанного количества тертого сыра Чеддер, измельченную зелень петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5511,'Соль и перец – по вкусу. Массу перелить в сотейник, прикрыть крышкой неплотно, прогреть в СВЧ-печи еще три минуты. Омлет должен осесть. При подаче посыпать быстрый омлет остатками сыра Чеддер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5512,'Хорошо взбить сырые желтки, они должны побелеть. Продолжая взбивать, подливать порциями растительное масло. Когда масса начнет тянуться – влить уксус, смесь побелеет и станет чуть жиже. По вкусу добавить соль, сахарный песок и уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5529,'Из охлажденного теста скатать шарики, положить их в суп, добавить зелень, варить в течение 10 минут на среднем огне. При подаче суп с сырными шариками посыпать рубленым укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5513,'Желтки комнатной температуры взбить в пену, каплями добавить оливковое масло и сок половины лимона, продолжать взбивать. Затем всыпать соль и сахар, сухую горчицу, еще стакан оливкового масла. Оливковое масло можно заменить любое рафинированное, лимонный сок – на уксус или раствор лимонной кислоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5514,'Желтки взбить, добавить сахар, соль, черный молотый перец и готовую горчицу и снова взбить. Вливать порциями растительное рафинированное масло, продолжать взбивать. Добавить уксус, отделенный белок и снова взбить. Можно добавить еще соль и уксус по вкусу, немного сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5515,'Взбить яичные желтки до побеления. Добавить тертый или пропущенный через мясорубку хрен и готовую горчицу, взбивать еще полминуты. Постепенно подливать растительное масло, взбивать массу еще в течение 4 – 5 минут. Затем влить уксус, всыпать соль и сахарный песок, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5516,'В емкость для запекания положить сливочное масло, нарезанное кусочками. Сверху выложить свиной или говяжий фарш, посыпать тертым твердым сыром. Залить блюдо сметаной и печь в духовке, в течение часа, при температуре 150 – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5517,'Смешать маргарин комнатной температуры, добавить сметану, всыпать муку и разрыхлитель из пакетика. Замесить тесто, положить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5517,'Охлажденное тесто раскатать, вырезать кружочки с помощью рюмки или формочкой для выпекания, посыпать ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5518,'Репчатый лук нарезать полукольцами, говядину – брусочками среднего размера. Обжарить мясо на разогретой сковороде в течение 20 минут, переложить в емкость с толстым дном. Обжарить лук в течение пяти минут, добавить в него немного томатной пасты, пожарить еще две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5518,'Обжарку переложить к мясу. Залить блюдо водой, положить хорошо промытый чернослив. Соль и перец – по вкусу. Тушить говядину с луком и черносливом под крышкой в течение 30 – 40 минут на умеренном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'Стаканом сметаны залить манную крупу и отставить на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'Сахар, яйцо и соль взбить, добавить сливочное масло и снова взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'К полученной массе добавить залитую сметаной манку и перемешать, ввести муку и вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'Полученное тесто вылить в форму, смазанную маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'В духовку поместить форму и готовить при 200 градусах 45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5519,'Пока манник на сметане классический будет готовиться, его нужно проверять зубочисткой – если она сухая, то пирог можно доставать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5520,'Сливочное масло растопить и немного остудить. Куриные яйца взбить с сахарным песком с помощью миксера, влить масло и перемешать. Протереть творог, добавить в массу ванилин, просеянную через сито пшеничную муку, погашенную уксусом или лимонным соком соду, влить масляную смесь, снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5520,'Выложить тесто в формы для выпечки, на две трети объема. Печь в духовке в течение получаса, готовность проверить зубочисткой. Выпечку выложить, полить растопленным на водяной бане шоколадом, посыпать творожно-масляные кексы сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5521,'Красную фасоль замочить на несколько часов, отварить почти до готовности. Нарезать репчатый лук, порубить чеснок, то и другое обжарить с грибами, можно взять замороженные шампиньоны. Всыпать фасоль, любые сухие приправы по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5521,'Выложить в горшочек для запекания фасолевую смесь, влить немного отвара, оставшегося от приготовления фасоли. Положить кусочек сливочного масла, лавровый лист, потушить красную фасоль с шампиньонами в духовке в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5522,'Сахарный песок всыпать в ковшик с толстым дном, поставить на средний огонь и довести до кипения. Варить до тех пор, пока не образуется масса карамельного, янтарного, цвета. Добавить сливочное масло, нарезанное кусочками, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5522,'Массу снять с огня и тонкой струйкой влить жирные сливки, перемешать до однородного состояния. Остудить карамельный соус до комнатной температуры, переложить в банку и поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5523,'Отварить яйца, отделить белки от желтков и раздельно натереть. Соединить белки, тертый твердый сыр, рубленый чеснок, заправить массу майонезом и перемешать. Крабовые палочки разморозить и аккуратно развернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5524,'Смешать сахар и какао-порошок. Добавить немного молока, размешать, влить оставшееся молоко. Довести массу до кипения на среднем огне, помешивать. В начале кипения добавить сливочное масло, уменьшить огонь и вновь дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5524,'Снять емкость с огня, всыпать просеянную через сито пшеничную муку, помешивать, вновь вскипятить. Остудить, всыпать ванильный сахар из пакетика, перемешать. Разлить натуральный «Домашний» шоколад в формочки, смазанные сливочным маслом. Можно использовать формочки для приготовления льда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5525,'Приготовить песочное тесто: растереть сливочное масло с сахарным песком, добавить просеянную муку вместе с разрыхлителем, сырое яйцо и соль. Тесто вымесить, поставить на полчаса в холодильник. Смазать маслом разъемную форму, выложить раскатанное тесто. Печь в течение 15 минут при температуре 200 градусов. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5525,'Замочить желатин так, как написано на пакетике. Подогреть и остудить. Протереть творог, добавить сахар и ванилин из пакетика. Свежую клубнику вымыть, просушить, приготовить стакан пюре и смешать с творогом.  Взбить сливки, соединить с творогом и желатином, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5525,'Нарезать полстакана клубники кусочками и добавить в крем. Массу поставить в холодильник на час. Клубничный, розовый, крем выложить на корж. Сверху песочный торт с творожно-клубничной начинкой украсить порезанными ягодами, поставить в холодильник еще на 3 – 4 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5526,'Хорошо промыть лимон, разрезать пополам, выдавить сок. Стейк форели промыть в большом количестве холодной воды, обсушить бумажным полотенцем. Рыбу выложить в тарелку, посолить, поперчить по вкусу, полить лимонным соком, сбрызнуть оливковым маслом, оставить на полчаса для маринования.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5526,'Разогреть на сковороде сливочное масло, всыпать муку, помешивать, чтобы не образовались комочки. Влить тонкой струйкой сливки, продолжать помешивать. Промыть зелень укропа, порубить, добавить в соус, довести смесь до кипения. Огонь выключить, смеси дать постоять под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5526,'Противень смазать растительным маслом, в том числе и бортики. Выложить рыбу, печь при температуре 180 – 200 градусов в течение 20 минут. Сразу выложить на блюдо для подачи, полить стейк форели сливочно-укропным соусом. Блюдо подать горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5527,'Разогреть масло, обжарить мелко нарезанный лук, морковь и сладкий болгарский перец. Добавить томатную пасту, обжарить все вместе еще две минуты. Подлить воду и выложить очищенный картофель. Соль и перец – по вкусу, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5527,'Натереть репчатый лук и чеснок. Замочить рис в горячей воде на полчаса. Перемешать мясной фарш со всеми ингредиентами, посолить и поперчить, вымесить. Сформовать тефтели, выложить в кипящий бульон на картошку. Варить мясные тефтели до готовности риса и картофеля, добавить специи по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5528,'Разбить яйца и аккуратно отделить белки от желтков. Белки взбить в пену, постепенно добавлять сахар. Затем ввести желтки, по одному, масса должна значительно увеличиться в объеме. Все это можно сделать с помощью венчика, вручную, или миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5528,'В яичную массу добавить манную крупу и разрыхлитель, осторожно перемешать движениями снизу вверх. Выложить смесь в смазанную и присыпанную мукой сковороду или форму с бортиками высотой в пять сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5528,'Печь при температуре 180 градусов в течение 20 – 25 минут, готовность выпечки проверить зубочисткой, она должна остаться сухой. Остудить. Довести молоко до кипения, но не кипятить. Всыпать сахарный песок, ванилин из пакетика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5528,'Остывшую выпечку нарезать на части и залить горячей молочной смесью в той же сковороде, где она готовилась. Жидкость должна полностью впитаться. Охладить блюдо в холодильнике. Сербский «Кох» подавать с ложечкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5529,'Твердый сыр натереть на мелкой терке, добавить сливочное масло, сырое яйцо и перемешать. Всыпать просеянную пшеничную муку, замесить тесто и поставить его в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5529,'Мелко нарезать репчатый лук и сладкий болгарский перец, натереть очищенную морковь. Овощи обжарить и добавить в кипящую воду или бульон. Очистить и нарезать картофель кубиками, тоже добавить в бульон, соль – по вкусу. Варить суп в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5530,'Сладкий болгарский перец очистить и разрезать на несколько частей или соломкой. Приготовить маринад из воды, уксуса, растительного масла, сахара и соли. Залить болгарский перец маринадом, варить в течение пяти минут, выложить в стерильные, пропаренные, банки вместе с рассолом, закатать, укутать одеялом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5531,'Баклажаны разрезать вдоль на четыре или восемь частей, в зависимости от размера плода. Обжарить на растительном масле. Сладкий болгарский перец очистить от семенных камер и обжарить целиком. На дно банки уложить зелень петрушки, укропа, чеснока, баклажаны, по три перца, половинки помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5531,'Всыпать по чайной ложке соли и влить по чайной ложке уксуса на пол-литра овощей, стерилизовать под крышкой в течение получаса от начала закипания воды. Закатать овощную закуску в маринаде, перевернуть и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5532,'Крабовые палочки на несколько секунд положить в горячую воду, затем раскрутить. Натереть твердый сыр, добавить пропущенный через пресс чеснок, майонез, рубленый укроп, смешать. Начинкой намазать палочки, скрутить, в центр воткнуть по перышку зеленого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5532,'Уложить рулетики «поленницей» на блюдо, промазать слои майонезом. Всю «пирамиду» смазать майонезом с боков, посыпать натертыми крабовыми палочками. Поставить закуску «Монастырская изба» в холодильник на несколько часов, затем нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5533,'Плоды нарезать пластинками, вдоль. Посолить и оставить на полчаса для удаления горечи, затем промыть холодной водой. Обжарить на растительном масле с двух сторон. Натереть морковь, помидоры и репчатый лук нарезать. Все три ингредиента обжарить на сковороде, на растительном масле, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5533,'Ломтики баклажана намазать обжаркой и сложить их вместе, имитировать целый плод. Выложить на противень, полить растительным маслом, печь баклажаны с овощами в течение 10–15 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5534,'Обжарить шампиньоны или другие грибы, измельчить в блендере вместе с копченой колбасой и твердым сыром Пармезан или Российским. Массу заправить майонезом и выложить на смазанный кетчупом хлеб. Прогреть в духовке в течение 5–7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5535,'Перемешать творог, сырые яйца, манную крупу, вяленую клюкву, вишню или изюм без косточек, сахарный песок, ванильный сахар из пакетика, тертую цедру одного лимона. Дно и борта формы для выпечки застелить бумагой, печь при температуре 170 градусов в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5535,'Масса должна стать твердой по краям, но остаться мягкой в середине. Смешать сметану, сырое яйцо и сахарный песок. Выложить массу на выпеченный первый слой, печь в течение 10–15 минут, до загустения. Творожную запеканку с изюмом подать к столу в теплом или холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5536,'Отварить пасту так, как указано на этикетке. В сковороду положить сливочное масло, подлить оливковое, обжарить на этой смеси очищенный и измельченный чеснок. Добавить креветки, обжарить, соль и перец – по вкусу, посыпать нарубленной зеленью петрушки, орегано.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5536,'Натереть сыр Пармезан, добавить в креветочную массу, залить соком лимона, огонь выключить. Выложить пасту с сыром и креветками на блюдо, сверху – креветки, залить соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5537,'У свежих огурцов срезать кончики, порубить зеленый укроп и зубчики чеснока. Все переложить в пакет из полиэтилена, добавить соль, потрясти, чтобы ингредиенты перемешались. Положить во второй пакет для надежности и выдержать в холодильнике в течение 6 – 8 часов. Время от времени содержимое пакета перетряхивать, не открывая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5538,'Форму для запекания смазать маслом и выложить куриную грудку, нарезанную кусочками. Соль и молотый перец – по вкусу, посыпать курятину молотой паприкой. Нарезать кружочками помидор, выложить на мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5538,'Залить всю массу жирными сливками, они должны скрыть курицу наполовину. Натереть сычужный сыр, посыпать запеканку ровным слоем. Печь курицу с сычужным сыром в сливках в духовке в течение часа. При готовности блюда должна получиться корочка золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'На крупной терке натереть сырой картофель, положить его на лук, добавить перец и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Помидоры нарезать полукольцами, обмакнуть в сметану, выложить на картофель, посыпать перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5539,'Куриное филе промыть, положить в кастрюлю с кипящей водой, посолить, варить около получаса. Мясо остудить, нарезать на мелкие кусочки. Натереть твердый сыр и отваренные яйца. Обжарить на сковороде, в духовке или в микроволновой печи, миндаль, затем его также измельчить с вручную на терке или кофемолкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5539,'Ягоды винограда разрезать пополам, удалить косточки, если они есть. Выложить в блюдо слоями: курица, сыр, яйца, тертые орехи. Все слои промазать майонезом. Верх салата «Тиффани» украсить половинками винограда контрастных цветов, посыпать орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5540,'Сливочное масло комнатной температуры взбить с сахарной пудрой ванильным сахаром, масса должна побелеть. Добавить сгущенку в несколько приемов, взбить на максимальной скорости. Добавить коньяк или десертное вино. Творожную массу протереть через сито в готовый масляный крем, хорошо перемешать и взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5541,'Для приготовления теста нарезать сливочное масло на небольшие кубики. Залить кипящей водой, всыпать пшеничную муку порциями, помешивая ложкой. Тесто должно получиться мягким и тягучим. Слепить 10 – 12 шариков. Выложить на присыпанную мукой поверхность стола. Для начинки мелко нарубить зеленый лук, петрушку и укроп. Смешать всё с творогом, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5541,'Раскатать тесто в тонкие лепешки, сложить их по две, пересыпав мукой, раскатать. На половину выложить начинку, слепить чебурек в форме полумесяца. Жарить на сковороде, на растительном масле, огонь – выше среднего. Выпечка должна приобрести золотистый цвет. Излишки жира можно удалить, если выложить болгарские чебуреки на бумажные полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Смешать какао, муку и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'До получения однородной массы взбивать сахар и размягченное масло, постепенно вбивать по одному яйцу, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Обе смеси соединить, влить молоко и перемешать, перелить в форму, смазанную маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Духовку прогреть до 180-200 градусов, запечь массу в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Когда пирог будет готов, нужно его остудить, не вынимая из формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Для приготовления глазури растопить масло, добавить какао и поварить 1 минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Кастрюльку снять с плиты, влить сгущенное молоко и добавить сахарь, хорошенько перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Прямо в форме смазать готовый пирог, отставить. чтобы пропитался и полностью остыл.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5542,'Остывший пирог разрезать, полученные пирожные в шоколадной глазури по-домашнему подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5543,'Нарезать соломкой помидоры, свежие и маринованные огурцы, сыр. Мелко нарезать крабовые палочки и зелень. Заправить массу майонезом или растительным маслом. Перед подачей добавить в салат ржаные сухарики брусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5544,'Отварить до готовности куриное филе, охладить и нарезать кубиками. Измельчить репчатый лук, обжарить на растительном масле, порезать шампиньоны пластинками, добавить к луку и еще обжарить. Также остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5544,'Нарезать соломкой красный сладкий болгарский перец, твердый сыр – кубиками. Ингредиенты смешать, добавить морковь по-корейски, консервированную кукурузу, заправить майонезом. Украсить салат «Мозаика» зеленым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5545,'Яблоки очистить от кожуры и семенных камер и нарезать крупными кусочками. Сливочное масло комнатной температуры растереть с сырыми яйцами, масса должна побелеть. Влить молоко, всыпать просеянную пшеничную муку с разрыхлителем, соль, корицу на кончике ножа, ванилин из пакетика, тертую цедру лимона. Должно получиться полужидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5545,'Вылить в смазанную форму для выпечки половину теста, выложить яблоки, залить оставшейся массой. Печь флорентийский ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5546,'Отварить куриное филе. Измельчить и обжарить репчатый лук с морковью. Соленый огурец нарезать мелкими кубиками. Все ингредиенты измельчить в блендере вместе с чесноком. Добавить соль и молотый перец, майонез, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5546,'Готовый тонкий лаваш намазать полученной смесью, свернуть рулетом, плотно, обмотать пищевой пленкой. Положить в холодильник на три часа. Подать закусочный рулет из лаваша, нарезав на кусочки, на листьях зеленого салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Все запечь в течение 1 часа, включив режим «выпечка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5547,'Растереть в однородную массу творог, сахарный песок и яйца. Всыпать картофельный крахмал, тертую цедру лимона, перемешать. Добавить вяленую клюкву и снова перемешать. Натереть охлажденное сливочное масло на терке, добавить сахар и муку, массу перетереть руками в крошку. Всыпать какао-порошок, растереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5547,'Высыпать в форму для запекания половину шоколадного штрейзеля, затем – творог с яйцами, разровнять, накрыть второй половиной шоколадной массы. Печь сырник в течение 45 минут при температуре 190 градусов, выпечка должна подняться и отстать от стенок. Остудить львовский сырник, затем вынуть из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5548,'У разрезанных вдоль кабачков удалить сердцевину, так, чтобы получились «лодочки». Посолить. Обжарить грибы с луком, шампиньоны или любые лесные. Выложить в кабачковые «лодочки», сверху полить сметаной или смесью сметаны с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5548,'Положить помидоры, нарезанные дольками, рубленую зелень, посыпать тертым твердым сыром. Запекать лодочки из кабачков с грибами можно под слоем фольги или без нее, до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5549,'Обезжиренный творог, сгущенное молоко и желтки перемешать. Влить сметану и ряженку, добавить мягкое сливочное масло. Белки взбить с сахарным песком в крепкую пену. Осторожно вмешать в творожную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5549,'Просеять пшеничную муку с разрыхлителем, всыпать в творог и перемешать. Тесто должно быть полужидким. Вылить тесто в форму для выпечки, выложить дольки яблок. Печь при температуре 170 градусов в течение 40–50 минут, выпечка должна зарумяниться. Творожный пирог с яблоками  остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5550,'Смешать до состояния однородности сахарный песок, пшеничную муку, молоко, сырые яйца, всыпать ванильный сахар. Массу варить до загустения на тихом огне, не давая закипеть, постоянно помешивать венчиком. Крем снять с огня, добавить какао-порошок, снова перемешать. Остудить в миске с холодной водой. Добавить сливочное масло, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5550,'Для приготовления теста смешать сахар, мёд, сырые яйца, пищевую соду и мягкое сливочное масло комнатной температуры. Смесь поставить на водяную баню, помешивая, варить в течение пяти минут, масса должна стать однородной. Снять с огня, добавить какао-порошок, перемешать, всыпать просеянную пшеничную муку. Перемешивать ложкой до тягучести, затем замесить тесто на присыпанной мукой поверхности. Поделить массу на восемь одинаковых частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5550,'Застелить противень пергаментом, присыпать мукой. Раскатать коржи, обрезать по форме тарелки до размера в 20 см. Печь при температуре 180 градусов в течение 3 – 5 минут. Готовые коржи остудить на решетке. Промазать масляным кремом, посыпать любыми рублеными орехами. Приготовить глазурь: смешать молоко, какао-порошок, сахар, сливочное масло и сметану. Варить на тихом огне в течение двух минут, масса должна загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5550,'Бока торта намазать остатками масляного крема, верх полить шоколадной глазурью. Выпечку поставить в холодильник на пять минут. Обрезки от коржей выпечь до золотистого цвета, измельчить в крошку, посыпать ими бока шоколадного торта «Дамский каприз». Дать постоять при комнатной температуре в течение 3 – 4 часов (можно прикрыть крышкой или пленкой), затем – в холодильник до окончательного охлаждения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5551,'Куриное филе тщательно вымыть и обжарить на растительном масле. Остудить, порезать мелкими кусочками. Отдельно отварить куриные яйца. Заморозить плавленый сырок в течение 20 минут в морозильной камере, затем натереть. Порубить очищенный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5551,'Все продукты перемешать, добавить соевый соус и майонез. Нанести массу равномерно на тонкий лаваш, свернуть рулетом и поставить на час в холодильник, закуска должна пропитаться. При подаче рулетики из лаваша нарезать на ломтики, украсить зеленью петрушки, кинзы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5552,'Взбить яйца в устойчивую пену, влить стакан молока, соль, сахарный песок. Постепенно, порциями, всыпать в смесь пшеничную муку, перемешать. Влить остатки молока, снова перемешать, затем – растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5552,'Смесь взбить вручную, венчиком, или миксером. Выпечь ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Свинину порезать небольшими кусками, сложить в мультиварку, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5553,'Лук нашинковать, распределить поверх мяса, добавить соль, перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5554,'Взбить яйца венчиком, добавить творог, манную крупу, пшеничную муку, соль и ванилин из пакетика. Массу хорошо перемешать, всыпать горсть изюма, оставить для набухания на полчаса. Из полученной массы сформовать сырники, обвалять их в муке, обжарить на сковороде с двух сторон по несколько минут, до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5555,'Лимоны вымыть, выжать сок с помощью насадки. Вскипятить воду с растворенным сахарным песком, добавить цедру лимона, веточки мяты, поварить в течение 5 – 7 минут. Кастрюлю поставить в емкость с холодной водой, дать остыть. Из остывшего сиропа удалить мяту и лимонные корки, жидкость процедить в кувшин, добавить лимонный сок, перемешать, охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5556,'Отварить вкрутую куриные яйца. Обжарить на оливковом масле нарезанные кусочками куриные грудки, до образования золотистой корочки. Незадолго до окончания обжаривания мясо посолить по вкусу и добавить чеснок, нарезанный тонкими пластинками. Натереть сыр Пармезан или Российский.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5556,'Листья зеленого салата порвать руками или крупно нарезать и выложить на тарелку. Сверху – куриное мясо и яйца, разрезанные на четыре части. Затем разложить помидоры черри, разрезанные на половинки, белые сухарики, посыпать салат «а-ля Цезарь» сыром. Полить соусом Американский цезарь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5557,'Кислые яблоки очистить от кожицы и семенных камер, нарезать крупными кусочками, выложить в форму для выпечки, предварительно смазанную маслом. Смешать просеянную пшеничную муку с манной крупой, сахаром, влить стакан кефира, растопленное сливочное или растительное масло, соль, пищевую соду, ванилин из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5557,'Массу хорошо перемешать, должно получиться полужидкое тесто. Залить тестом яблоки, печь при 200 градусах в течение получаса. Готовность пирога проверить зубочисткой, яблочная шарлотка должна быть сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5558,'Замесить тесто из растопленного маргарина, сметаны, пищевой соды и просеянной пшеничной муки. Поставить в холодильник на 20–30 минут. Мелко нарезать для начинки репчатый лук, обжарить на растительном масле, добавить сырые куриные яйца, тертый плавленый сыр. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5558,'Разделить тесто на две части, раскатать в виде одинаковых лепешек. На первую выложить луковую начинку, накрыть второй и защипать края. Выпечь пирог с плавленым сыром в духовке до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5559,'Сыр натереть на крупной терке. Взбить яйца с молоком, добавить в сырную массу, хорошо перемешать. Смазать противень растительным маслом, выложить один слой лаваша. Намазать сырной массой, снова лаваш, должно получиться пять-шесть слоев. Верх смазать сливочным маслом. Печь в духовке при температуре 180 градусов в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5560,'Взбить с помощью блендера твердый и плавленый сыр, яйца. Масса должна получиться однородной. Противень застелить бумагой для выпечки, вылить полученную массу, печь в течение получаса при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5560,'Приготовить куриный фарш, посолить и поперчить по вкусу, добавить измельченный чеснок, зелень, сладкий болгарский перец, тщательно перемешать. Вынуть из духовки выпеченную сырную лепешку, намазать фаршем, свернуть в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5560,'Печь в духовке еще в течение получаса при той же температуре, рулет накрыть фольгой. Готовое блюдо вынуть из духовки и накрыть полотенцем, чтобы оно осталось мягким. Подать закусочный рулет с куриным фаршем к столу, нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5561,'Натереть морковь и твердый сыр. Очистить копченую колбасу и нарезать тонкой соломкой. Натереть или пропустить через пресс чеснок. Ингредиенты перемешать, добавить консервированную кукурузу без жидкости. Заправить майонезом по вкусу. Салатную массу переложить в чашку, предварительно застеленную пищевой пленкой. Уплотнить и поставить салат с копченой колбасой в холодильник на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5562,'Для приготовления теста для бисквита взбить сырые яйца с сахарным песком, добавить просеянную муку и перемешать. Выпечь корж, нарезать кубиками. Нарезать консервированные ананасы и свежие бананы кусочками, апельсины – кружками. Взбить сметану с сахаром, добавить растворенный, набухший и остывший желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5726,'Залить холодной водой, посолить и дать закипеть, варить 3 минуты, воду из кастрюли слить, картофель остудить, включить разогревать до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5562,'В разъемную форму выложить апельсины в один слой, затем кубики бисквита, смешанные с третью общего количества крема. Следующий слой – банановый, снова бисквит с кремом, ананасы. Сверху – остатки крема с бисквитом. Форму плотно закрыть пищевой пленкой и оставить в холодильнике на 3 – 4 часа для пропитывания. При подаче перевернуть торт «Фруктовая нежность» на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5563,'Пшеничную муку просеять и смешать с пекарским порошком. Отдельно смешать растительное масло, сметану, сырой яичный желток, сахар, ванилин из пакетика. Массу хорошо перемешать до однородного состояния. Месить руками, пока тесто перестанет прилипать к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5563,'Сформовать «колбасу» толщиной в три сантиметра, нарезать кусочками толщиной в один сантиметр. Заготовки не для печенья немного расплющить на присыпанной мукой поверхности. Печь печенье на сухой сковороде с тефлоновым покрытием на минимальном огне, по 2–3 минуты с каждой стороны, до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5564,'Смешать муку, сахарный песок, сырые куриные яйца, пищевую соду, разрыхлитель, какао-порошок, ванильный сахар из пакетика. Влить молоко, растительное масло. Добавить стакан кипятка и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5564,'Должно получиться жидкое тесто. Емкость для микроволновой печи смазать растопленным сливочным маслом, вылить массу, прогревать в режиме «Выпечка» в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5564,'Для приготовления крема смешать жирные сливки с сахарной пудрой. Корж разрезать пополам, прослоить, верх и бока торта также смазать кремом. Посыпать торт «Заварной шоколад» тертым темным или молочным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5565,'Растопить темный шоколад со сливочным маслом на тихом огне, постоянно помешивать. Смешать сырые куриные яйца с сахаром, всыпать соль и пищевую соду, добавить просеянную муку и ванилин из пакетика, в массу постепенно добавить шоколадно-масляную смесь. Форму для выпекания смазать растопленным сливочным маслом, вылить половину теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5565,'Печь при температуре 180 градусов в течение 15–20 минут. При готовности отодвинуть края коржа от формы лопаткой, осторожно перевернуть выпечку на плоскую тарелку. Выпечь второй корж. Каждый разрезать на две части и остудить .Для крема перемешать протертый творог, сметану, сахарный песок и жирные сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5565,'Массу поставить в холодильник. Для приготовления помадки разогреть в сотейнике сливочное масло, добавить к нему сметану, какао-порошок и сахарный песок, варить до однородной густой консистенции, помешивать. Коржи промазать полученным творожным кремом, верх полить помадкой. Украсить шоколадно-творожный торт взбитыми сливками и тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'На стол горкой насыпать половину муки, в середине сделать ямку и разбить туда яйцо, добавить соль, молоко, уксус, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Измельчить в крошку маргарин и оставшуюся муку, затем быстро вымесить руками до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Первое тесто раскатать, уложить сверху второе, полученный пласт сложить конвертом, обсыпать мукой и раскатать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Потом тесто еще раз припудрить, сложить, накрыть полотенцем и оставить на 15 минут на холоде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Скатку и охлаждение теста проделать еще 3-4 раза, в конце тесто раскатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Духовку разогреть до 240 градусов и испечь корж размером на весь лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Приготовить крем: сахар и яйцо взбить, влить чуть-чуть молока, добавить крахмал с мукой и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'В приготовленную массу добавить остальное молоко, ванилин.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Крем отправить на маленький огонь либо водяную баню, постоянно помешивая, варить пока не загустеет.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Емкость снять с плиты, по одной ложке, все время мешая, добавить 1/3 мягкого масла, остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Остальные 2/3 масла добавить в остуженный крем и взбить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Готовый корж разделить пополам, уложить полученные части друг на друга, лишнее срезать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Приготовленным кремом промазать первый корж, положить на него второй, снова промазать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5566,'Обрезки от коржа измельчить в крошку, посыпать торт Наполеон с заварным кремом по-домашнему.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5726,'Приготовить смесь из оливкового масла, рубленой зелени, раздавленного чеснока и соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5567,'Натереть плавленый сыр, смешать с рубленым чесноком и майонезом. Намазать смесью ломтики белого батона, положить по тонкому кружочку очищенного киви, украсить зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5568,'Натереть твердый сыр. Мелко порубить сладкий болгарский перец, зелень петрушки, укропа. Все ингредиенты перемешать, посолить по вкусу. Куриные грудки хорошо отбить, смазать майонезом и оставить для пропитывания на 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5568,'Затем посолить по вкусу. Выложить начинку на мясо, свернуть рулетами. Каждый плотно завернуть в фольгу, печь при температуре 180 градусов. Фольгу развернуть, посыпать блюдо кунжутными семечками, печь еще 15 минут. При подаче готовые рулеты «Конфетти» разрезать на части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5569,'Для приготовления теста взбить сырые яйца со щепоткой соли, постепенно добавить сахарный песок. Должна получиться плотная, тягучая, пена. Пшеничную муку просеять, перемешать с яичной массой, осторожно, движениями снизу вверх. Тесто должно остаться пышным. Вылить тесто в застеленную бумагой для выпечки форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5569,'Стенки дополнительно смазать растопленным сливочным маслом. Печь корж при температуре 200 градусов в течение 25 – 30 минут. Остудить, дать полежать бисквиту несколько часов. Разморозить ягоды клубники, взбить их в пюре с помощью блендера. Добавить сахарный песок, быстрорастворимый желатин, оставить на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5569,'Прогреть массу на огне до растворения желатина, до кипения не доводить. Начинку остудить. Взбить сливки с ванильным сахаром. Влить клубничное пюре, перемешать. Вылить ягодную начинку на корж в форме и поставить торт «Ленивец» с клубникой в холодильник на три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5570,'Для приготовления ликера понадобятся плоды лимона желтого цвета, примерно одного размера, спелые, с тонкой кожицей. Плоды промыть водой и обсушить. Острым ножом снять цедру, мякоть разрезать пополам и выжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5570,'В бутыль из стекла поместить лимонный сок, снятую цедру и спирт. Оставить для настаивания на 30 дней в темном прохладном помещении. Затем содержимое отфильтровать через хлопчатобумажную ткань. Из воды и сахара сварить сироп, остудить. Соединить сироп с лимонным экстрактом. Смесь разлить в бутылки и оставить ликер «Лимончелло» еще на 30 дней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5571,'Репчатый лук и колбасу нарезать кубиками, обжарить на растительном масле. Добавить тертый твердый сыр, майонез. Массу перемешать. Тонкий лаваш разрезать на четыре квадрата каждый, выложить колбасную начинку, свернуть конвертами. Обжарить конвертики на растительном масле до образования золотистой корочки, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5572,'Очистить креветки. Репчатый лук и стебли сельдерея нарезать и обжарить на оливковом масле. Всыпать пшеничную муку, томатную пасту, смесь потушить в течение двух – трех минут. Влить молоко, бульон, перемешать. В суп добавить креветки, базилик, острый соус и соль – по вкусу. Варить в течение 8–10 минут. При подаче итальянский суп с креветками посыпать нарезанным зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5573,'Перед приготовлением мясо обжарить в течение 4–5 минут на сковороде, это поможет удержать в продукте все соки и ароматы. Положить в мультиварку вместе с тертой или нарезанной брусочками морковью, короткими полосками репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5573,'В блюдо подлить воду, белое вино или лимонный сок вместе с цедрой, положить веточки сухого или свежего тимьяна, соль и перец – по вкусу. Готовить в режиме «Выпечка» в течение 40 минут, несколько раз перемешать. Затем еще час подержать телятину с морковью в режиме «Тушение».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5574,'Сыры Камамбер и Гауда нарезать кусочками среднего размера. Отдельно взбить сырое яйцо с помощью вилки. Смешать пшеничную муку и разрыхлитель. В чашу блендера всыпать все сухие ингредиенты, нарезанное кусочками сливочное масло, белый молотый перец, молотую паприку. Добавить половину яичной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5574,'Массу размешать до образования крошки, высыпать на присыпанную мукой поверхность и замесить тесто. Поставить массу на 30 – 60 минут в холодильник. Очистить фисташки и арахис от шелухи, потереть руками, порубить ножом. Также для посыпки можно также использовать мускат, кунжутные семечки, мак, свежий молотый белый перец. Оставшуюся яичную смесь перемешать со сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5726,'Обмакнуть каждую дольку в масляную смесь, выложить картофель на противень и запечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5574,'Тесто из холодильника еще раз промесить руками, тонко раскатать на листе бумаги для выпечки. Вырезать печенье с помощью разных формочек, «сердечки», «кружочки» и «звездочки» смазать яйцом, посыпать орехами. Печь сырное печенье с орехами в духовке, при температуре 180 – 200 градусов, до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5575,'Размешать сахарный песок в теплой воде. Добавить сухие дрожжи. Оставить на 10 минут до появления пены. Добавить соль, оливковое масло и просеянную пшеничную муку. Замесить густое тесто, поставить его на час в теплое место. Нарезать колбасу Пепперони кружочками, сыр Моцарелла – тонкими пластинками, можно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5575,'Тесто разделить на две части, тонко раскатать на присыпанной мукой поверхности, вырезать круги при помощи тарелки большого диаметра. Переложить на посыпанный мукой противень. Смазать соусом для пиццы, выложить сыр и колбасу, печь при температуре 220 градусов в течение 20–25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5575,'Для приготовления соуса к пицце «Пепперони» помидоры залить кипятком на несколько минут и снять кожицу. Порезать на кусочки, измельчить в блендере в пюре. Почистить и нарезать красный лук и чеснок, то и другое обжарить на оливковом масле в течение 2–3 минут. Влить томатное пюре, тушить все вместе на среднем огне, пока не испариться жидкость и соус не станет густым. Добавить орегано и базилик, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5576,'Сыр крупно натереть на терке, всыпать в готовое заварное тесто, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5576,'В кондитерский мешок выложить тесто, на лист, смазанный маслом, выдавить его тонкими брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5576,'Печь печенье в духовке при 180-200 градусах 15-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5576,'Растопить шоколад, полить готовое печенье, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5576,'Когда выпечка остынет, подать сырное заварное печенье в шоколаде к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5577,'Творог размять. На разогретую сковороду положить сливочное масло, творог, сгущенное молоко, прогревать смесь на тихом огне, она должна загустеть. Добавить щепотку кардамона, огонь выключить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5577,'Готовую творожную массу разделить на две части, в одну добавить чайную ложку свекольного сока, хорошо перемешать. Из белого творога слепить небольшие шарики, сделать оболочку из розового творога, и наоборот.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5578,'Нагреть столовую ложку оливкового масла в сковороде большого размера. Мелко порубить репчатый лук, обжарить в течение пяти минут. Затем добавить измельченный чеснок и жарить еще одну минуту. Следующий ингредиент – бекон, порезанный мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5578,'Прогревать еще 10–12 минут, помешивать. Бекон должен приобрести золотистую корочку, стать хрустящим. Нарезать очищенный от семян горький перец чили на крупные куски, добавить к нему листья базилика, мелко порубить. Полученную острую смесь добавить в обжарку, туда же всыпать очищенные кедровые орешки, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5578,'Влить белое вино, содержимое банки томатов в собственном соку, соль и перец. Тушить на тихом огне в течение 10–15 минут. Отварить спагетти так, как указано на упаковке. Смешать с полученным соусом, разложить в тарелки, посыпать спагетти «Аматричана» тертым сыром Пармезан.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5579,'Смешать измельченное шоколадное или любое песочное печенье, например, Юбилейное с молотой халвой. Добавить рубленые грецкие орехи и растопленное сливочное масло. Масса должна получиться однородной. Выложить ее в застеленную пищевой пленкой форму ровным слоем. Поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5579,'Для приготовления суфле желатин растворить в воде, прогреть до 60 градусов, остудить до 25 градусов. Взбить сливки в крепкую, тянущуюся, пену. Влить желатин и перемешать вручную или с помощью миксера, на небольшой скорости. На основу из печенья выложить ягоды свежей клубники, разрезанные пополам. Залить торт «Халва и клубника» сверху суфле с желатином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5580,'Смешать пшеничную муку, какао-порошок, разрыхлитель, соль. Отдельно смешать коричневый и обычный сахар, шоколадную пасту Нутелла или аналогичную, размягченное сливочное масло. Вбить сырое яйцо, добавить ванилин. Обе смеси перемешать. Выложить тесто в смазанные маслом формочки для выпечки пончиков, их нужно заполнять на три четверти объема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5726,'Запеченный картофель «Айдахо» по-американски будет готов через 20 минут, подать горячим, украсив зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5580,'Печь в течение 7 –9 минут. Вынуть из духовки, остудить, аккуратно, острым ножом, отделить пончики от стенок формочек, вынуть и полностью остудить. Смешать сахарную пудру, Нутеллу, молоко и ванилин из пакетика. Намазать пончики с шоколадной пастой полученным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5581,'Нарезать белый батон и подсушить ломтики в тостере, каждый кусочек разрезать на две половины. Тонко нарезать помидоры, уложить на хлеб. Смешать тертый твердый сыр, чеснок и майонез, перемешать. Смесь выложить на помидоры. Украсить бутерброды зеленью укропа или петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5582,'Форму для выпечки смазать растительным маслом. Выложить макароны, сверху – нарезанную ветчину или копченую колбасу. Перец черный молотый, другие специи – по вкусу. Перемешать молоко с водой, посолить, залить макароны с колбасой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5582,'Можно использовать только молоко. Форма должна быть с высокими бортиками. Посыпать блюдо тертым сыром, закрыть форму фольгой. Печь в течение 30 минут на сильном огне. Фольгу снять, дать запеканке из макарон с карбонатом зарумяниться еще в течение 15–20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5583,'Выпечь тонкие блины по любимому и проверенному рецепту. Форму для выпекания выстлать пищевой пленкой, оставить длинные, свисающие, края. Выложить готовые блины внахлест, смазать внутреннюю сторону размягченным сливочным маслом. Отваренную говядину или курятину, индюшатину, пропустить через мясорубку вместе с обжаренным репчатым луком и рублеными грецкими орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5583,'Массу перемешать и заправить майонезом. Натереть любой твердый сыр, добавить измельченный чеснок, соль по вкусу, также заправить майонезом. На оставшиеся блины выложить полученную мясную начинку, свернуть рулетами. На листья зеленого салата – начинку с сыром, тоже свернуть рулетами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5583,'Выложить сырные и мясные рулеты в форму, на блины, в шахматном порядке в два или три слоя. Сверху закрыть концами блинов, завернуть пленку и поставить блюдо под груз на 10–12 часов. При подаче нарезать закуску «Шахматы» ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5584,'Просеять пшеничную муку, добавить разрыхлитель и сахарный песок. Отделить белки от желтков. Последние смешать с соком лимона, растительным маслом. Белки взбить с оставшимся сахаром в пену. Постепенно обе смеси соединить, белковую массу порциями вмешать в желтковую. Всыпать в яичную массу мучную смесь, в три приема, перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5584,'Готовое бисквитное тесто выпечь в форме при температуре 175 градусов в течение 30 – 40 минут. Корж остудить, разрезать по горизонтали острым ножом на две-три части. Молоко вскипятить вместе со стручком ванили. Смешать сырые яйца с сахаром и картофельным крахмалом. Влить в смесь тонкой струйкой в горячее молоко, постоянно помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5584,'Крем поставить на средний огонь, довести до кипения, через две минуты с огня снять. Добавить сливочное масло, охладить, накрыть посуду пищевой пленкой. Промазать коржи этим кремом. Для приготовления глазури нагреть сливки, смешать с растопленным на водяной бане шоколадом. Смесью полить бостонский кремовый торт сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5585,'Приготовить дрожжевое тесто, затем выложить его на стол, припудренный мукой, разделить на 2-3 одинаковых куска.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5585,'Придать каждой полученной части форму круга, раскатать в колбаски так, чтобы серединки получились утолщенными, а концы более острыми.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5585,'Из полученных колбасок сделать жгут, придать ему форму калача, уложить на лист, отставить примерно на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5585,'Перед началом выпекания смазать калач русский яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5585,'Духовку разогреть до 210-220 градусов, выпекать калач в районе 30 минут, пока он не подрумянится и не будет готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5586,'Приготовить тесто для «корзиночек». Смешать на поверхности стола или на доске просеянную муку со щепоткой соли, положить кусок масла из холодильника. Ножом порубить смесь в крошку величиной с горошину. Пересыпать в миску, добавить ледяную воду и быстро скатать тесто в шар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5586,'На дно небольших формочек для выпечки выложить по кусочку теста, распределить его равномерно по поверхности, поставить в холодильник. Форель очистить от костей и кожи, филе нарезать тонкими полосками. Смешать сырые яйца со сливками, добавить тертый мускатный орех, размороженный шпинат, отжатый от излишков влаги, тертый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5586,'Массу перемешать. Выложить в формочки часть смеси из шпината, затем полоски форели в виде рулетов, их немного «утопить» в заливочной массе. Печь при температуре 180 градусов в течение 50 минут, до готовности. Закусочные корзиночки с форелью и шпинатом украсить листьями зеленого салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5587,'Отварить куриные яйца, крупную морковь, свеклу, клубни картофеля. Все овощи и яйца натереть по отдельности, мелко нарезать репчатый лук. Разбавить майонез сметаной. На тарелку поставить кольцо-форму для салатов. Выложить слой свеклы, морковь, картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5587,'Каждый слой промазывать майонезной смесью. Верх салата украсить кусочками или ломтиками малосольной сёмги. Поставить в холодильник на два-три часа. При подаче снять кольцо, украсить салат «Семга на шубе» тертым сыром, зеленью петрушки, луковым пером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5588,'Куриное филе пропустить через мясорубку, добавить перемолотую говядину и свинину, перемешать. Всыпать отваренный рис, молотую зиру, паприку, любые сухие травы, мелко нарезанный репчатый лук, тертый корень имбиря. Посолить массу по вкусу, добавить куриное яйцо для связки. Вымесить и поставить на два часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5588,'Для теста перемешать муку, вбить одно яйцо и неполный стакан теплой воды. Перемешать, накрыть тканью, дать постоять в течение получаса для набухания клейковины. Раскатать тесто в тонкий пласт, дать подсохнуть в течение 15 минут. Свернуть в «колбасу» и нарезать полосками. Приготовить куриный бульон из супового набора, в конце варки добавить по вкусу соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5588,'Приготовить из охлажденного фарша фрикадельки среднего размера. Положить в горячий бульон. Затем добавить обжаренный до золотистого цвета рубленый репчатый лук. Огонь убавить до минимального уровня. Всыпать лапшу, варить до готовности. При подаче лапшу с фрикадельками украсить половинками отваренных перепелиных яиц (их можно не резать, а разломить руками), свежей рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5589,'Взбить вилкой сырое яйцо. Отдельно просеять пшеничную муку с разрыхлителем, всыпать сахарную пудру, ванильный сахар из пакетика. Добавить яйцо, рафинированное растительное масло, молоко, массу тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5589,'Прямоугольную форму для выпекания смазать жиром, присыпать мукой. Вылить приготовленное тесто. Вишню и ежевику очистить, обсушить. Растереть творог с остатками сахарной пудры, ванилином. Добавить яйцо и влить оставшееся молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5589,'Творожно-яичную массу выложить на тесто, посыпать ягодами, вдавить их в творог. Печь при температуре 180 градусов в течение 35–40 минут, до образования золотистой поверхности. Пирог вынуть из духовки, остудить, нарезать на порции. При подаче пирог с ежевикой и вишней посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5590,'На крупных, спелых, помидорах сделать крестообразный надрез, положить в кипяток, через 10 минут переложить в холодную воду. Кожицу снять. Нарезать на крупные дольки. Красный болгарский перец также нарезать дольками. Мелко накрошить морковь, чеснок, листочки базилика и репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5590,'Все ингредиенты обжарить на оливковом масле. Переложить овощи в кастрюлю большого размера, превратить с помощью блендера в кашицу. Добавить бальзамический уксус, соус Табаско, молотый мускатный орех, любые специи, бокал белого вина. Перец чили, молотый черный перец и соль – по вкусу. Поставить смесь на огонь на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5590,'Обжарить на оливковом масле королевские креветки и крупные мидии, добавить специи и соль. Для приготовления гренок хлеб для тостов нарезать кубиками и обжарить на сковороде. Разлить готовый итальянский суп с морепродуктами в тарелки, добавить морепродукты, еще немного бальзамического уксуса, положить гренки и посыпать тертым сыром Грана падано.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5591,'Мелкие клубни картофеля очистить, разрезать пополам и выложить в миску. Добавить оливковое масло, соль и перец, перемешать и выложить на противень в один слой. Печь в течение 40 минут до золотистой корочки при температуре 200 градусов. В процессе приготовления картофель два раза перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5591,'Противень вынуть из духовки, картофель остудить. Смешать в миске соль, оливковое масло, мелко нарубленный чеснок, сок лимона, готовую столовую горчицу и майонез. Залить полученной смесью картофель и подать картофельный салат по-испански к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5592,'Нарезать крупными дольками свежие помидоры, огурец. Красный и салатный лук, сладкий болгарский перец нарезать кольцами. Порвать руками листья зеленого салата. Салатницу натереть чесноком для аромата, выложить в неё смесь овощей и маслины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5592,'Перемешать. Для соуса взбить оливковое масло, виноградный уксус, соль, орегано. Полить салат, посыпать порванными листочками базилика. Нарезать кубиками или пластинками брынзу, выложить поверх греческого салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5593,'Готовый, отваренный, рис переложить в неметаллическую посуду, полить смесью рисового уксуса с сахаром и солью. Длинный, парниковый, огурец очистить от кожицы, удалить семена, нарезать полосками. Также нарезать полосками филе слабосоленого лосося. Разрезать пополам авокадо, вынуть косточку, очистить от кожуры, нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5593,'Выложить рис на листья нори. Ребром ладони сделать желобок посередине риса, смазать его соусом «Васаби». Положить по кусочку лосося и огурца или лосося и авокадо. Роллы свернуть с помощью макису, сжать руками, чтобы уплотнить рис. Нарезать на шесть-восемь кусочков, нож при нарезании окунать в воду. Подать роллы с лососем, авокадо и огурцом с маринованным имбирем, «Васаби», соевым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5594,'Перемешать небольшое количество молока с разрыхлителем. Сырые яйца взбить с сахаром, ванилином из пакетика в пену. Влить тонкой струйкой растительное масло, перемешать. Всыпать просеянную пшеничную муку, тертую цедру лимона, молочную смесь. Замесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5594,'Раскатать тесто в «колбаску», нарезать небольшими кусочками, скатать шарики величиной с грецкий орех. Выложить на застеленный бумагой противень, печь в течение 15–20 минут при температуре 180 градусов. Выпечку немного остудить и чайной ложкой осторожно вынуть часть серединки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5594,'Вынутую мякоть измельчить руками в крошку, сбрызнуть ромом. Отдельно перемешать сахарный песок и ванилин, какао-порошок, добавить мягкое сливочное масло, взбить с помощью миксера. Добавить крошку, вымесить, начинить выпеченные заготовки, соединить их по две штуки. Для украшения можно использовать пищевые красители или сок свеклы и моркови, вишни.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5594,'Один бочок печенья покрасить кулинарной кисточкой в красный цвет, обмакнуть в сахарный песок.  Другую сторону – в оранжевый краситель и тоже обмакнуть. Выложить на блюдо, дать обсохнуть. Можно украсить пирожное «Персик» любыми зелеными листочками, их нужно вымыть, обсушить полотенцем, воткнуть черешком между половинками «персиков».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5595,'В кастрюлю сложить измельченную капусту, поварить его до мягкости, с помощью дуршлага слить всю жидкость, оставить остывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5595,'В разогретое на сковороде масло положить нашинкованный лук и сухую капусту, помешать, добавить специи, соль и перец, обжарить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5595,'Пресное тесто раскатать, вытиснуть кружки, на половину каждого положить полученную начинку, сформовать вареники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5595,'Вскипятить и посолить воду, опустить вареники с кислой капустой, достать, как только они всплывут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5595,'Масло растопить и перед подачей полить им вареники.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5596,'Приготовить тесто из пшеничной муки высшего сорта, воды, сырого яйца и соли. Вымесить крутое тесто, завернуть в пищевую пленку и поставить на час в холодильник. Готовое тесто разделить на две части, очень тонко раскатать, тесто должно просвечивать на свет. Смазать поверхность топленым маслом, свернуть рулетом, посыпав мукой, чтобы тесто не слиплось. Свернуть «улиткой», завернуть в пленку и поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5596,'Нарезать баранину и курдючное сало мелкими кубиками со стороной в полсантиметра. Репчатый лук порубить еще мельче. Перемешать, посолить, поперчить, всыпать специи, перемешать. Начинке дать постоять в течение 10 –15 минут. Готовое тесто извлечь из холодильника, нарезать на кусочки по пять сантиметров. Поставить их срезом на стол и расплющить рукой, затем раскатать до диаметра 12–15 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5596,'Положить по ложке фарша, защипать края. Форму пирожков можно сделать любую – треугольную, прямоугольную, круглую. Приготовить льезон: взбить молоко с яйцом. Смазать пирожки, посыпать кунжутными семечками. Печь самсу с бараниной по-узбекски при температуре 210 – 220 градусов в течение 30–35 минут, до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5597,'Емкость мультиварки смазать сливочным маслом, выложить тонко нарезанный бекон, плотно прислонив ломтики  к стенкам чаши, они должны из нее свисать. Приготовить свиной фарш, перемешать с сырым куриным яйцом, посолить и поперчить по вкусу. Натереть сырой, очищенный, картофель, чуть посолить и отжать лишнюю жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5597,'Добавить тертый твердый сыр, яйцо и майонез, массу перемешать. Нарезать шампиньоны, обжарить с рубленым репчатым луком на сливочном масле. Выложить мясной фарш на бекон, затем – картофельную массу, грибы. Закрыть трехслойный пирог с мясом сверху «лепестками» бекона. Поставить блюдо в режим «Выпечка» на один час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5598,'Смешать сахарный песок, какао-порошок, молоко, мягкое сливочное масло. Массу довести до кипения на среднем огне, постоянно помешивать. Кипятить полторы минуты. Снять с огня, добавить щепотку ванилина из пакетика, арахисовое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5598,'Перемешать и всыпать овсяные хлопья, можно грубого помола. Выложить смесь на застеленный бумагой для выпечки противень, формируя печенье любой формы. Оставит шоколадное печенье для остывания и застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'До готовности отварить рис, полить его смесью из уксуса, сахара и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'Очищенный лук мелко порезать, на крупной терке натереть морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'Рыбу и огурец порезать кубиками, мелко порубить вареные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'Смешать с яйцом рубленую зелень и зеленый лук, добавить немного майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'На блюдо выложить слоями салат: рис, семга, майонез, укроп, лук, огурец, соль, майонез, смесь яйца с зеленью и зеленым луком, морковь, снова майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5599,'Салат из семги под шубой украшается на ваше усмотрение, перед подачей поставить блюдо в холодильник, чтобы оно пропиталось.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5600,'Отварить картофель в мундире, затем почистить, нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5600,'Порезать сельдь, огурцы, яблоки, отварную свеклу, яйца и отварное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5600,'Смешать сметану, уксус, горчицу, зелень и тертый хрен.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5600,'Полить полученной заправкой салат и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5600,'Старорусский рыбный салат с мясом и яблоком охладить, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5601,'Очищенную, вымытую, выпотрошенную рыбу, без кожи и костей, порезать пластами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5601,'Смешать водку, сахар, рубленый укроп и соль, полученным соусом смазать рыбу, на сутки поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5601,'Лосось (кету) семужного посола перед подачей нарезать тонкими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5601,'Замариновать можно кету, нерку, форель или осетра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'Вымытые и очищенные яблоки нарезать кружочками толщиной по полсантиметра, извлечь семена и посыпать сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'Смешать сметану вместе с желтками яиц, сахаром, солью и мукой, хорошенько перемешать, добавить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'В густую пену взбить белки, аккуратно мешая ввести в приготовленную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'В приготовленное тесто обмакнуть каждый кружок яблока, переложить на сковороду с разогретым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'Яблоки обжарить до появления корочки золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5602,'Жареные в тесте яблоки подать к столу, предварительно посыпав сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5603,'Смешать в небольшой емкости жидкий мед, коричневый сахар, оливковое масло, соевый соус, готовую столовую горчицу и рубленый чеснок. Прогревать на тихом огне в течение 15 минут. Смазать готовым пряным маринадом филе лосося, жарить стейки на гриле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5604,'Для приготовления заправки смешать оливковое масло высокого качества, бальзамический уксус, лимонный сок, соль и молотый черный перец. Персики разрезать пополам, удалить косточки, каждую половину разрезать еще на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5604,'Помидоры красного и желтого цвета нарезать толстыми кружками. На блюдо выложить персики, обычные помидоры и помидоры-черри, рубленые стебли сельдерея. Присыпать солью, порванными руками листьями мяты. Полить салат с персиками и помидорами готовой заправкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5605,'Шампиньоны порезать пластинками, обжарить. Натереть на терке морковь, порезать лук кубиками, то и другое обжарить отдельно. Выложить слоями: грибы, лук, морковь. Все слои повторить, каждый присаливать и смазывать майонезом. Верх также смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5606,'Из куриного филе и репчатого лука приготовить фарш. Влить молоко, сырые яйца, массу переложить в блендер и взбить в однородную, гладкую массу. Соль и перец – по вкусу. Должна получиться жидкая масса без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5606,'Натереть сыр, добавить в куриную массу, всыпать муку и перемешать. Разогреть на сковороде небольшое количество растительного масла. Выпечь блинчики из куриного филе с сыром с двух сторон. Готовое блюдо подать со сметаной и овощной нарезкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5607,'Отварить куриную грудку, нарезать кубиками, ветчину – соломкой. Натереть отваренные куриные яйца, кубиками нарезать красные спелые помидоры и маринованные огурцы. Твердый сыр мелко натереть, порубить зелень петрушки, укропа. Сметану посолить по вкусу, хорошо перемешать, заправить салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5608,'Тщательно промыть куриные грудки, разрезать на кусочки среднего размера. Очистить и тонко нарезать чеснок, всыпать специи. Залить массу кефиром, перемешать и поставить в холодильник для маринования на час или полтора. Достать из холодильника пропитавшееся маринадом куриное мясо, тушить куриную грудку в кефире в духовке в течение 40 минут при температуре 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5609,'Отварить в мундире картофель, клубни очистить, нарезать кубиками, обжарить на растительном масле. Продукт выложить в салатницу и дать остыть. Добавить размятые консервированные шпроты, кубики свежего, спелого помидора. Посолить и поперчить по вкусу. Картофельный салат залить маслом от рыбных консервов. Украсить веточками укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5610,'Крупного карпа выпотрошить, вымыть, обсушить бумажными салфетками. Нарезать тушку на порционные куски, посолить, сбрызнуть свежим лимонным соком, поставит на час в холодильник для маринования. Затем кусочки обвалять в муке, обжарить на растительном масле, выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5610,'Копченую грудинку-шпик нарезать тонкими ломтиками, репчатый лук – тонкими полукольцами. Добавить лавровый лист, перец-горошек, все вместе немного обжарить. Рыбу переложить на сковороду, влить кипяченую воду, посыпать сушеной зеленью базилика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5610,'Тушить под крышкой в течение 15 минут на среднем огне. Крышку снять, прогревать до испарения воды. Добавить сливочное масло, растопить. Карпа выложить на блюдо, полить полученным от обжарки соусом. Обжарку с грудинкой и луком выложить рядом с рыбой, посыпать карп «А-ля Белая дама» свежим базиликом или зеленой петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5611,'Тушки кальмаров хорошо очистить, поскрести щеткой, промыть, отварить в подсоленной воде в течение двух минут. Нарезать соломкой, обжарить на растительном масле одну минуту. Отварить куриные яйца и рис. Измельчить репчатый лук и морковь, обжарить вместе на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5611,'Отдельно обжарить шампиньоны, также на сливочном масле. Собрать послойно: кальмары, размятый куриный белок, отваренный рис, консервированную кукурузу без жидкости, морковно-луковую обжарку, грибы. Все слои салата «Сытный» промазать майонезом. Верх украсить раскрошенным желтком, зеленью укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5612,'Белокочанную капусту нарубить, перемешать с укропом, высыпать смесь в форму для запекания. Растопить сливочное масло или маргарин и залить капустную начинку. Взбить яйца, добавить майонез и сметану, соль и перец – по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5612,'Всыпать просеянную пшеничную муку, перемешанную с разрыхлителем, замесить жидкое тесто. Вылить его на капусту, запечь ленивый капустный пирог в духовке до готовности, должна получиться аппетитная, румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5613,'Мясо индейки с бедренной части, без кости, натереть солью и перцем, положить в смесь гранатового соуса и сухого красного вина на сутки. Нарубить очищенные грецкие орехи. Мясо из маринада намазать готовой сладкой горчицей, посыпать «Прованскими травами» и орехами. Свернуть мясо в виде рулета, перевязать нитками, обсыпать сладкой паприкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5613,'Форму для выпечки застелить фольгой, выложить рулет и закрыть свободным краем фольги. Печь при температуре 230 градусов в течение 36 минут. Фольгу раскрыть, убавить огонь до 180 градусов, продолжать печь, поливая оставшимся маринадом, в течение получаса. Блюдо остудить, поставить в холодильник, снять нитки. Подать рулет из филе индейки на стол в охлажденном виде, нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10727,'Через сутки тушенку можно употреблять в пищу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5614,'Разморозить и обсушить филе пангасиуса, нарезать на кусочки, пропустить через мясорубку вместе с репчатым луком и белым хлебом, предварительно замоченным в молоке или воде. Излишки воды или молока отжать. Соль и перец, специи для рыбы – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5614,'Из приготовленного рыбного фарша слепить небольшие лепешки, на середину каждой выложить по мешочку икры окуня. Сформовать зразы. Запанировать зразы из рыбы с икрой окуня в муке, обжарить на разогретом растительном масле с двух сторон. Перед обжариванием изделия можно запанировать в сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5615,'Замесить тесто, вручную или в хлебопечке, из пшеничной муки, теплой воды, сахарного песка, соли, сухих дрожжей. Готовую массу разрезать на кусочки, величиной с грецкий орех. Растопить сливочное масло, всыпать соль, сухой или свежий давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5615,'Массу перемешать. Шарики из теста обмакивать в масляную смесь и выкладывать в форму для выпечки кекса. Натереть твердый сыр, посыпать им слой «шариков». Выложить второй слой, снова посыпать сыром, поставить в теплое место на полчаса, тесто должно подняться, увеличиться в объеме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5615,'Печь до готовности в духовке, при 180 градусах. Через 15 минут после начала выпечки прикрыть форму фольгой, чтобы сыр не подгорел. В конце приготовления фольгу снять и еще немного допечь до получения золотистой корочки, полное время выпечки: 30 – 35 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5616,'Нарезать яблоки кубиками, смешать пшеничную муку с пекарским порошком, ванилином из пакетика. Взбить мягкое сливочное масло с сахарным песком и яйцами, всыпать муку, яблоки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5616,'Полученную массу переложить в смазанную маслом форму, которую также можно посыпать панировочными сухарями. Печь в течение 45 минут при температуре 170 – 180 градусов. Выпечку остудить, вынуть из формы, порезать на порции, посыпать сахарной пудрой. Подавать сладкий пирог к чаю, кофе, молоку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5617,'Груши хорошо вымыть и очистить от кожицы и сердцевины. Нарезать мякоть кусочками. Добавить сахарный песок, влить свежий сок лимона, перемешать. Оставить на два часа для пропитывания. Переложить массу в кастрюлю, довести до кипения, варить на тихом огне в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5617,'Половину фруктов вынуть, измельчить в блендере или вручную, с помощью толкушки. Вернуть в кастрюлю. Отдельно, на сковороде без масла, прожарить мак. Переложить к грушам, проварить варенье из груш с маком в течение 5 – 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5618,'Круглый рис промыть, залить водой. Довести до кипения, а затем уменьшить огонь, варить в течение 15 минут под крышкой. Огонь выключить, дать постоять 10 минут, переложить в другую посуду и полить рисовым уксусом. Макису обернуть пищевой пленкой, выложить половину листа нори.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5618,'Выложить рис, равномерно размазать мокрой рукой. Свернуть ролл, придать ему квадратную форму. Нарезать свежую форель или семгу ломтиками одинаковой длины, уложить плотно на ролл, накрыть ковриком и прижать филе. Нарезать роллы «А-ля Филадельфия» острым мокрым ножом на шесть-восемь одинаковых кусочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5619,'Домашний творог протереть через сито или пропустить через мясорубку. Добавить мягкое сливочное масло и перемешать, масса должна получиться однородной. Соль и перец – по вкусу. Очистить и тонко нарезать клубни картофеля кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5619,'Смазать сливочным маслом глубокую форму для запекания. Выложить слой кружков, посолить, поперчить. Затем распределить тонкий ровный слой творога. Выложить несколько таких слоев, пока не закончатся ингредиенты, сверху – картофель. Форму закрыть фольгой, печь при температуре 200 градусов в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5619,'Натереть твердый сыр. Для приготовления заливки взбить яйца, влить сметану, посолить и поперчить, всыпать молотый мускатный орех или другие специи. Снять фольгу, залить яичной массой картофель, посыпать сыром. Печь запеканку из картофеля с творогом и сыром в течение получаса, затем огонь выключить и прогреть блюдо в духовке еще 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5620,'Налить в посуду горячую воду и растворить в ней соль. В другую посуду насыпать муку и в центр горки влить горячую воду по частям, каждый раз перемешивая тесто. Вымесить до однородности. Тесто должно отставать от рук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Выпекать каждый корж нужно до полной готовности в разогретой духовке при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5620,'Намочить хлопковое полотенце и прикрыть тесто на 20–30 минут. Сухую сковороду без масла разогреть на плите. От теста отрезать кусочек размером с яйцо и раскатать его тонко–тонко в лепешку. Сразу класть на сковородку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5620,'Когда на лепешке появятся темные пятна и пузыри, перевернуть ее на другую сторону и обжарить. Лепешку снять со сковороды и убрать на деревянную разделочную доску. Немного сбрызнуть на лепешку холодной воды и укрыть чистым сухим полотенцем. Таким же образом обжарить армянский лаваш из всего теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5621,'Промыть курицу и разрезать на некрупные куски. Лук порезать полукольцами. В форму на дно налить воды и положить лук. Курицу намазать майонезом и обсыпать приправой и солью. Если есть желание, то добавить к приправам чеснок, фенхель или другие приправы по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5621,'Тушку курицы положить в форму на лук и закрыть крышкой. Поставить форму в нагретую до 180 градусов духовку. У формы с курицей «Без проблем» через 40 минут запекания открыть крышку и оставить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5622,'Чеснок измельчить и перемешать с остальными ингредиентами, кроме капусты. Капусту нашинковать мелко, посолить, перемешать, тщательно сжимая руками, чтобы капуста стала мягче и немного дала сок. На противень налить немного растительного масла и смазать его поверхность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5622,'Выложить капусту. При желании добавить к ней зеленый лук. Вылить яичную смесь сверху на капусту. Сыр потереть сверху на запеканку и поставить противень в духовку на 200 градусов. Время запекания блюда – 20 минут. Остудить и порезать запеканку из капусты на порционные кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5623,'Подсолить воду и отварить рис. К нему добавить сливочное масло. Сыр потереть, зелень покрошить. Смешать сыр, зелень, креветки и кукурузу. Рис и сырно-кукурузную массу перемешать и добавить яйца, взбитые с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5623,'Добавить к рису специи и хорошо вымесить. Выложить полученную массу в формочки или в отдельную форму для выпечки. Поставить рисовую запеканку с креветками выпекаться на 20 минут в духовку, нагретую до 200 гр. Охлажденную запеканку вынуть из формочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5624,'Лук порезать и обжарить. Перемешать с порезанной на кусочки курицей и заправить майонезом. Курицу с луком положить в салатник первым слоем. Морковь и яйца отварить, потереть на терке крупно и заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5624,'Морковь и яйца выложить вторым слоем в салатник. Потереть сыр и порезать консервированные ананасы. Заправить майонезом и уложить в салатник верхним слоем. Грецкие орехи порубить ножом и посыпать салат «Валентина».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5625,'Растереть с сахаром масло и добавить сметану и щепотку соли. Перемешать. Муку и разрыхлитель просеять вместе и добавить к масляной смеси. Замесить тесто. Разделить тесто ножом на 8 равных частей. Каждую часть сразу на бумаге для выпечки тонко раскатать, в процессе присыпая мукой. Тесто обрезать в форме круга диаметром 25 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5625,'При температуре 180 градусов выпечь коржи до румяного цвета. Взбить для крема сметану и сахар. Сливки и сахар тоже взбить .Сливки и сметану аккуратно вилкой перемешать вместе. Коржи сложить стопкой, промазывая их кремом. Оставить торт «Мишка на севере» на ночь и утром украсить свежей малиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5626,'Порезать куриную грудку на кусочки произвольного размера. Посолить и обсыпать немного красным перцем или другой любимой приправой. Обжарить куриные кусочки на растительном масле. Замочить на пару часов фасоль и отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5626,'Лук и салатный перец порезать соломкой. На сковородке обжарить вначале лук, потом добавить чрез 5 минут к нему перец и еще через 5 минут выложить на сковородку фасоль. Добавить соль, перец, другие приправы. Потушить 5–6 минут. Куриное филе с фасолью и перцем выложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5627,'Мед смешать с сахаром и содой, влить яйца и добавить масло. Массу поставить на паровую баню и постоянно помешивая, чтобы не сварились яйца, дождаться растворения сахара и масла. Муку всыпать к медовой массе и размешать. Остудить, накрыв пленкой и убрав в холодильник на 10–12 часов. Затем достать тесто их холодильника и оставить при комнатной температуре еще на 4 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Разложить на холодном противне ломтики бекона, выставить температуру в 200 градусов и отправить его в холодную духовку на 20 минут для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5627,'Противень застелить бумагой для выпечки, которую немного намазать маслом. Поставить на бумагу бортик от разъемной формы и влить внутрь бортика 2 ст. л. теста. Размазать его тонко. Поставить противень в духовку на 7–10 минут в зависимости от мощности духовки. Температура выпекания – 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5627,'Коржи золотистого цвета вынуть и подрезать по кругу и вместе с бумагой вынуть. Оставить остужаться. Выпечь остальные коржи, их всего получится 5 штук. Один из коржей выпекать больше по времени, пока он не станет темно-коричневым. Измельчить этот корж в блендере до крошки. Для крема взбить сметану и сахар. Отдельно взбить до крепкой пены сливки и соединить аккуратно со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5627,'Порубить грецкие орехи и измельчить на мелкие кусочки чернослив. Выложить на плоское блюдо коржи, смазанные кремом, при этом поверх крема выкладывать поочередно орехи и чернослив. Последний корж посыпать крошкой с орехами. Бока у медового торта «Особенный» обсыпать крошкой, перемешанной с орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5628,'Порезать мясо и отбить кулинарным молоточком. Посыпать перцем, солью, чесноком и смазать майонезом. Свернуть каждый мясной кусочек в рулет и обвалять в муке. Форму смазать и уложить в нее рулеты. Поставить запекаться на 20 минут. Температура запекания – 250 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5628,'Порезать грибы и лук. Обжарить их вместе на сковородке. Сметану перемешать с солью, перцем, водой или готовым бульоном. Грибы и лук выложить в форму с мясом, полить соусом. Поставить мясные рулеты в грибном соусе снова в духовку на 40 минут при 230 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5629,'Творог взбить блендером или прокрутить на мясорубке. Впрочем, если хочется, то можно оставить творог не взбитым, тогда готовая запеканка будет с крупинками творога. Перемешать творог с яйцами, всыпать сахар и добавить масло, порезанное на мелкие кусочки. Для аромата добавить ванилин. В творог положить кусочки кураги и промытый и обсушенный изюм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5629,'Форму смазать сливочным маслом. Масло стоит нанести толстым слоем, тогда запеканка легко отделится. Обсыпать сухарями форму изнутри и вылить творожную массу. Остатки сухарей высыпать на творог сверху. Духовку нагреть до 150–160 градусов, не выше. Творожную запеканку выпекать 30 минут. Потом выключить духовку и оставить форму в ней еще на 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5630,'Для начинки покрошить лук и перемешать с сырым куриным белком. Добавить майонез и перемешать. Из предложенных продуктов замесить тесто и разделить его на комочки. Комочки раскатать в лепешки и вложить в них внутрь начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5630,'Края лепешки защипнуть как у беляшей и потом лепешки с начинкой раскатать скалкой. Сковородку нагреть и обжарить сырные лепешки с зеленым луком на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5631,'Курагу, изюм и другие сухофрукты по вкусу залить горячей водой и замочить. Промыть и порезать на мелкие кусочки. Орехи порубить ножом мелко. Мед и сахар добавить к растопленному маслу и нагревать пока масса не станет однородная по составу. Снять с огня. В медовую смесь высыпать овсяные хлопья и выложить орехи с сухофруктами. Перемешать. Нагреть духовку до 180 градусов. На противень выложить пекарскую бумагу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5631,'Овсяно-медовую массу выложить ровным слоем на противень и разровнять силиконовой лопаткой. Толщина козинаков должна быть 1,5 см. Поставить противень на полчаса в духовку и затем достать и остудить. Порезать овсяные козинаки на прямоугольные  кусочки и выложить на блюдо. Можно в медовую массу добавить мак, семена подсолнечника или банан. С бананом козинаки будут мягче.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5632,'Перетереть желтки с сахаром. Смешать затем с маслом. Добавить разрыхлитель и муку. Вымесить тесто. Намазать маслом противень или можно застелить его пекарской бумагой. Выпекать коржи 15–20 минут, поставив в нагретую до 180 градусов духовку. Коржи промазать сгущенкой и выложить друг на друга. Сверху и с боков торт «Песочный» тоже намазать сгущенным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5633,'Перемешать продукты. Сковородку с маслом нагреть и ложкой выложить массу. Обжарить оладьи до румяного цвета на среднем огне. Жарить их с двух сторон по очереди. Куриные оладьи с сыром выложить на блюдо. В качестве гарнира к ним подойдут овощи. Подавать горячими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Переложить кусочки на полотенце из бумаги и дать впитаться излишкам жира, в этом случае бекон получится красивым и хрустящим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5634,'Сыр потереть на крупной терке. Замесить тесто из сыра, кефира, муки, соли и соды. В качестве начинки можно взять любую колбасу, сосиски или ветчину. Ее нужно натереть на терке или порезать очень мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5634,'Вместо колбасы можно добавить потертый острый сыр другого сорта. Или жареный лук, вареная морковь, отварные яйца – начинка может быть из того, что есть в холодильнике. Все продукты для начинки покрошить. Слепить сырные лепешки из теста с начинкой и пожарить или выпечь в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5635,'Благодаря добавлению водки к тесту, чебуреки по этому рецепту получаются мягкими внутри и с хрустящей корочкой снаружи. А что еще нужно для идеальных чебуреков! Воду довести до кипения и посолить. Положить в кипяток масло, перемешать и сразу всыпать 0,5 стакана муки. Размешать тщательно лопаткой до исчезновения комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5635,'Массу остудить и влить в нее водку и добавить яйцо. Перемешать и, подсыпая небольшими порциями остальную муку, замесить тесто. Тесто должно быть без комочков и однородным. Если тесто липнет к рукам, то нужно добавить еще немного муки. Убрать тесто в сторонку, оно должно выстояться. Через полчаса вымесить тесто и оставить еще на полчаса выстаиваться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5635,'Итого спустя час выстаивания можно лепить чебуреки, тесто будет готово. Пока выстаивается тесто, приготовить фарш. Для него очищенные луковицы пропустить через мясорубку и перемешать с мясным фаршем. Для вкуса добавить перец, зелень петрушки или кинзы, соль. От теста отрезать кусок размером с мяч для тенниса и раскатать тонко–тонко в лепешку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5635,'На нее положить фарш с одной половины теста. Второй половиной теста накрыть и края слепить, выдавливая воздух. Края должны быть тщательно слеплены, чтобы избежать вытекания сока. Обжарить чебуреки в кастрюле с толстым дном или во фритюрнице. Кастрюлю можно заменить сковородой с высокими бортиками. Масла для обжаривания должно быть налито много.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5635,'Чебуреки выкладывать по 2–3 штуки и обжаривать до золотистости с каждой стороны. Готовые чебуреки выкладывать на бумажные полотенца. Чебуреки со свининой по-домашнему стоит есть еще горячими. Тогда они полнее раскрывают свой восхитительный вкус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5636,'Замочить хлеб в молоке. Яйца отварить и порезать мелко. Овощи пожарить на сковороде с небольшим количеством масла. Сделать фарш, смешав мясо, хлеб, соль и перец. Добавить сырое яйцо и хорошо фарш вымесить руками. Расстелить фольгу или пищевую пленку на столе и выложить на нее фарш. Разровнять слоем в 1 см и сформировать из фарша прямоугольник. Фарш намазать слой майонеза и присыпать тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5636,'Выложить сверху рядами пожаренные овощи, нарезанные мелко яйца, грибы, маленькие кусочки соленых огурцов. Посыпать начинку сыром и аккуратно свернуть фарш в рулет. Переложить на смазанный противень. Мясной рулет обмазать сверху майонезом и посыпать остатками тертого сыра. Поставить противень с мясным рулетом «Удиви гостей» в духовку на 20 минут для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5637,'Отварить рис почти до готовности. На сковороде пожарить лук и морковь. Рыбу разрезать на кусочки. В форму для запекания выложить слоями рис, рыбу (ее немного прижать к рису руками, как бы слегка утопив), жареные овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5637,'Залить содержимое формы сметаной, при желании немного разбавив ее водой, например, если сметана слишком густая. Запекать рисовую запеканку с горбушей и овощами в духовке 40 минут. При этом за 10 минут до конца посыпать натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5638,'Порезать рыбу на порционные кусочки и засыпать солью. Убрать рыбу в прохладное место на половину суток. Достать рыбу из соли и промыть под проточной водой. Залить на 5 часов 6% уксусом. Если уксус 9%, то разбавить его водой наполовину. В банку или контейнер выложить рыбу, затем посыпать перцем, потом слой лука. И так чередовать. Залить емкость с рыбой растительным маслом и оставить хек мариноваться еще на 12 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5639,'Сделать печеночный фарш. Перемешать фарш из печени с луком, мукой, сметаной и яйцом. Фарш посолить и поперчить по вкусу, если есть желание, то добавить любимые приправы. Взбить полученную массу в блендере до однородности. Пожарить на сковороде печеночные блины одинаковые по размеру. Для начинки порезать мелко лук и грибы. Морковь мелко потереть. Чеснок раздавить через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5639,'Обжарить грибы, лук, морковь и чеснок на медленном огне. Смешать с майонезом, сметаной и порезанной зеленью. Добавить еще одну дольку порезанного чеснока. Перемешать. Блины из печени смазать начинкой и уложить в стопку. Промазать бока тортика начинкой. Потереть плавленый сырок на терке (предварительно положив его на 10–15 минут в морозилку). Посыпать им печеночный торт «Прощай фигура» и сверху красить свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5640,'Промыть овощи и нарезать их на кружки. Нарезать на порционные кусочки грудку. Овощи и грудку вперемешку сложить в форму. Сверху посыпать солью и при желании перцем. Духовку разогреть предварительно до 200 градусов. Поставить на полчаса запекаться овощи и мясо. Потереть сыр и смешать с майонезом. Достать форму и намазать овощи с грудкой. Поставить индейку с овощами запекаться еще на 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5641,'Мясо порезать кубиками. Очищенный огурец порезать на мелкие кусочки. Слить с грибов маринад и крупные грибы порезать на 2–3 части. С горошка тоже слить жидкость. Лук порезать на мелкие колечки. Потереть крупно сыр. Выложить в салатницу и перемешать все ингредиенты, заправить салат «Летисия» майонезом, посолив и поперчив.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5642,'Включить духовку нагреваться до 200 гр. Чеснок, соль и два вида перцев перемешать. Разогреть оливковое масло на сковородке и выложить в нее фарш с луком. Обжарить фарш до готовности и выложить к нему смешанные специи. Перемешать. Добавить на сковородку помидоры, предварительно очищенные и измельченные. Потушить фарш и помидоры 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5642,'Пасту по инструкции отварить до полуготовности. Воду с пасты слить. Взять высокую форму, в нее на дно налить немного соуса. Макароны выложить стоя в форму. Остальной соус вылить на макароны и посыпать их двумя сырами. Поставить пирог в духовку на полчаса. Выключить духовку и не вынимать пасту-пирог  с мясным фаршем еще 15 минут. Подавать на стол это блюдо лучше всего со свежим базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5643,'Ножом порубить масло вместе с какао и сахаром до состояния мелкой крошки. Можно вначале масло потереть крупно на терке, а затем руками растереть масло с остальными продуктами. Всыпать муку, перемешать крошку и затем добавить желтки. Замесить тесто. Оно должно быть достаточно липким, чтобы слипаться в комок, но при этом при надавливании пальцами оно должно рассыпаться. Для начинки смешать творог с желтком и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5643,'При желании можно добавить пару ложек сметаны. Смазать разъемную форму маслом и обсыпать внутри мукой. Выложить в нее половину теста. Сверху выложить творожную начинку и на нее вторую половину теста. В духовку, разогретую до 180 градусов поставить форму с ватрушкой минут на 30.В это время взбить белки и сахарную пудру блендером до крепкой пены. И выкладываем потом на ватрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5643,'Выпекаем еще дополнительно 15–20 минут. Температуру в духовке чуть уменьшить. По истечении времени духовку выключить, но шоколадную королевскую ватрушку не вынимать, чтобы белковая масса не осела. Пирог вынуть из формы, для этого острым ножом обвести аккуратно по периметру стенок формы. Можно в начинку добавить кусочки фруктов, например, абрикосы, бананы, изюм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5644,'Отварить рис в течение 20–25 минут в кастрюле с большом количестве воды. Варить, пока рис не сварится и даже немного переварится. Рисинки не должны начать слипаться. Слить воду с риса и выложить его в дуршлаг, чтобы вся вода стекла. Обсушить рис на бумажных полотенцах. Застелить противень листом пергаментной бумаги. Выложить на противень сваренный и обсушенный рис в один слой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5644,'Нагреть духовку до 100 градусов. Противень с рисом поставить сушиться на 1,5–2 часа, пока он полностью не высохнет. Когда рис высушится полностью, достать его из духовки. Разогреть на сковородке масло без запаха. Его должно быть достаточно чтобы рис не лежал на дне сковородки, а плавал во фритюре. Масло не должно начать дымится. Когда масло разогреется, кидать в него рис небольшими порциями. И как только он начнет вздуваться вынуть его из масла шумовкой. Чтобы убрать лишнее масло, выложить воздушный рис на бумажные полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5650,'Противень размером примерно 33х45 см застелить бумагой для выпечки и смазать бумагу тщательно сливочным маслом. Нагреть духовку заранее до 105–110 градусов. Мед, ваниль и перчики взбить в блендере до получения однородного пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5645,'Ягоды смородины перебрать, убрать черенки и листики, промыть от пыли. Сложить чистые ягоды в кастрюлю и залить водой по рецепту. Варить ягоды до тех пора, пока смородина не разварится. Блендером измельчить ягоды в воде. Пропустить измельченную смесь через сито, чтобы убрать оставшиеся крупные шкурки и косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5645,'Добавить в протертую массу сахар и поставить опять варить. Уварить смородиновый сироп до густоты так же, как варят варенье. Капнуть смородиновый сироп на холодную тарелку. Сироп готов, если капля не растечется, а сохранит свою форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5645,'Разлить сироп по формочкам или в одну большую форму. Можно использовать формочки для кексов, для фигурного льда. Когда мармелад из смородины подсохнет и станет густым, разрезать его острым ножом на кусочки или выложить на блюдо целиком. Обсыпать сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5646,'Смешать тщательно сухие ингредиенты. Добавить муку и постепенно в миску влить молоко. Замесить густое тесто. Густоту можно регулировать, разбавляя тесто дополнительно молокой или добавляя до нужной густоты муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5646,'Обвалять сосиски в муке, чтобы потом на них лучше держалось тесто. Взять шпажки и надеть на них сосиски. Перелить тесто в узкий и высокий сосуд. Например, в коктейльный бокал или небольшая вазочка. В сковородку налить масла толщиной примерно в 2–2,5 см. Нагреть хорошо масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5646,'Сосиски на шпажках опустить в бокал с тестом и прокрутить вокруг оси. Выложить сосиску на сковородку. Как только тесто на одной стороне прихватилось, нужно сразу поворачивать сосиску на другую сторону. И так со всех сторон. Тогда кляр будет ровным и гладким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5646,'Появляющиеся уголки, выравнивать лопаткой, аккуратно приглаживая. Когда сосиска «Корн Дог» будет умеренно золотистой, вынуть ее и положить на бумажное полотенце. Так по очереди обжарить все сосиски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5647,'Помидоры обдать кипятком, с них тогда легко можно снять шкурку. Порезать их кубиками. Порезать полукольцами репчатый лук. Чеснок измельчить с помощью чеснокодавилки. Куриные голени обжарить на сковороде по 2 минуты на каждой стороне. Снять с огня и переложить в глубокое блюдо. Помидоры и лук выложить на сковородку, где жарилась курица.  Через 5 минут положить к овощам курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5647,'Оставить тушиться на 15 минут. Затем добавить чеснок, зелень и оливки. Убавить огонь и тушить 10 минут все вместе. Ингредиенты для греческих лепешек смешать и замесить тесто. Оставить под хлопковым полотенцем на 20 минут для расстойки. Подошедшее тесто разделить на 4 части и раскатать каждую в лепешку. Обжарить на сухой сковороде. На блюдо выложить лепешку, рядом с ней курицу по-средиземноморски с овощами и соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5648,'Порезать огурцы, колбасу на кубики. Потереть сыр, картофель и морковь. Морковь на мелкой, все остальное на крупной терке. Мелко порезать лук. Яйца разделить на белки и желтки. И натереть их по отдельности. Выложить салат слоями в салатник. Между слоями смазывать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5648,'Вначале огурцы, затем картофель, лук и сыр. Потом выложить морковь, смешанную с измельченным чесноком и майонезом. На нее положить колбасу, посыпать белками, а сверху желтками. На салате «Колобок» сверху выложить глаза, нос и рот колобка маленькими кругляшками огурца и листиками зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5649,'Слоеное тесто достать из холодильника и разморозить в течение 1 часа при комнатной температуре. Масло нагреть на сковородке и пожарить 6 яиц с укропом, солью и перцем. Добавить ветчину кубиками и тоже обжарить. Яйца и ветчину убрать со сковородки в сторонку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5649,'Тесто выложить на рабочую поверхность, которую предварительно присыпать мукой. Раскатать тесто в квадрат и разрезать его на 4 равные части. Положить немного начинки из яиц и ветчины на уголок каждого квадрата из теста. Посыпать начинку 1 ст. л. тертого сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5649,'В воде намочить пальцы и намочить края лепешек. Загнуть квадраты по диагонали, чтобы получился треугольник. Края фигурно прижать вилкой. Оставшееся яйцо взбить и обмазать все пирожки сверху. Поставить пирожки на противне выпекаться в духовку. Температура в духовке — 200 градусов. Время приготовления пирожков с яйцом, сыром и ветчиной 18–20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Порезать помидоры кружочками толщиной по полсантиметра, сложить листья салата по размеру тоста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5650,'Массу перелить на противень и поставить в духовку сушиться в течение 5 часов. Через половину указанного времени открыть духовку и перевернуть противень другой стороной для равномерного просушивания и пропекания. Проверить основу на готовность через 4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5650,'Если она уже застыла, то можно вынуть и остудить. Пока основа для рулета из фруктовой кожи застывает, нужно взбить крем для начинки. Сыр, сахар и ваниль взбить миксером. Нанести ровным слоем на основу и скрутить в трубочку. Нарезать рулет и подать к чаю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5651,'Отварить пасту. Курицу порезать, посолить, поперчить. Добавить раздавленный чеснок (1 дольку) и 1 ст. л. горчицы. Оставить мариноваться. Масло нагреть в сковороде и пожарить грибы. Раздавить дольку чеснока и добавить к грибам. Снять с огня и переложить со сковороды на блюдо. В этой же сковороде обжарить курицу и тоже убрать со сковороды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5651,'Налить в сковороду вино, томить пока его не станет в 2 раза меньше. Добавить сметану и остальную горчицу. Перемешать и варить до загустения. Положить грибы и курицу в соус, перемешать. Если соус густой, то разбавить его немного водой, из-под пасты. Пасту выложить на тарелку с грибами и курицей в винно-горчичном соусе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5652,'Для приготовления необходимо смешать все подготовленные продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5653,'Разбить в емкость яйца, взбить с помощью миксера или венчика, чтобы получилась воздушная пенка. Протереть творог через ситечко или очень хорошо размять вилкой. Переложить творог в яйца, насыпать сахар, соль и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5653,'Все перемешать. Взять маленький кусок теста, скатать шарик, чуть-чуть приплюснуть. Так поступить со всем тестом. Обвалять в муке. Обжарить аппетитные ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5654,'Налить в емкость мультиварки масло, обжарить, не закрывая крышку, измельченный лук на режиме «Выпечка». Положить к луку натертую морковь, готовить в том же режиме минут пять. Крышку оставлять открытой. Почистить картофель, порезать на брусочки, положить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5654,'Налить воду, закрыть крышку, включить режим «Тушение» на двадцать минут. Нашинковать тоненько капусту, добавить к овощам в мультиварку, размешать, готовить в том же режиме еще минут десять. Положить томатную пасту размешать. Включить режим «Тушение» еще минут на пять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5655,'Соединить творог и измельченный чесночок, положить сметану, укроп, перец, соль. Перемешать. Измельчить огурец и болгарский перец красного цвета. Порезать помидор на кружки, на каждый выложить начинку из творога. Посыпать огурцом и перцем. Украсить помидоры с творогом и чесноком укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5656,'Разогреть духовку до 180 градусов. Соединить в большой емкости сахар, муку, соль, соду, порошок-какао. В середине смеси сделать углубление, налить растительное масло, уксус, питьевую воду, ваниль. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5656,'Смазать маслом несколько формочек круглой формы, распределить в них тесто. Готовить коржи минут сорок. Проверять готовность зубочисткой. Хорошо охладить. Взбить сливки, чтобы получилась пена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5656,'Корж переложить на блюдо, намазать обильно сливками, положить слой клубники, порезанной на две или четыре части. Накрыть вторым коржом, намазать сливками, сверху положить клубнику. Торт с клубникой и сливками можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5657,'Соединить соду и сметану. Добавить растопленное сливочное масло, размешать до однородности. Медленно насыпать муку. Проверить, если тесто прилипает к рукам, насыпать еще муки. Замесить тесто, разделить пополам. Порезать дольками лимоны или апельсины, не срезая кожуры, взбить в блендере. Насыпать стакан сахара. Разогреть духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5657,'Положить один кусок теста в формочку – это основа. Равномерно распределить, сделать бортики. Положить начинку, размазать по тесту. Второй частью теста накрыть начинку. Намазать пирог взбитым желтком. Проткнуть лимонный пирог вилкой, готовить минут тридцать. Охладить, выложить из формочки, посыпать закрытый лимонный пирог сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5658,'Филе курицы (лучше брать большие ровные кусочки) чуть-чуть отбить, посыпать перцем, солью. Положить в мясной фарш болгарский перец, порезанный кубиками, измельченный лук, чесночок, насыпать перец, соль, вбить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'слой четвертый – грибы с луком (посолить и поперчить),',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'слой пятый – огурец (посолить),',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5658,'Порезать шампиньоны пластинками. Потереть сыр. Мясо положить в формочку, положить сверху фарш с перцем, вокруг грибы, в середину сыр. Отправить минут на сорок в духовку, готовить курицу с мясным фаршем и грибами при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5659,'Сделать шоколадный слой. Растопить на водяной бане сливочное масло и шоколад. Смешать в однородную смесь. Взбить миксером яйца и сахар минут пять. Муку соединить с какао. Шоколад вылить к взбитым яйцам, размешать, шоколад не должен осесть на дно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5659,'Просеять муку с какао к полученной смеси, осторожно размешать, убирая комки. Сделать слой творожный. Перемолоть в блендере до однородности бананы, сахар, творог и яйца. Смазать формочку маслом. Тоненько выложить шоколадную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5659,'Произвольно выложить смесь творожную, не выравнивая. С помощью спички сделать красивые линии, соединяя слои. Затем таким же образом чередовать слой за слоем. Готовить шоколадный торт «Сюрреалист» минут тридцать, соблюдая температуру 175 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5660,'Почистить и потереть яблоки. В емкости соединить яйцо, творог, яблоки, корицу, сахар и муку. На сковороде разогреть масло. Намочить руки, сформировать сырники, пожарить со всех сторон. Подавать творожные сырники со сгущенкой или сметанкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5661,'Смешать в блендере масло, сахарную пудру до пышной смеси, добавить ваниль. Сделать мощность блендера меньше, не прекращая взбивать, насыпать крахмал, муку. Тесто должно быть мягким, но не жидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5661,'На противень, застеленный специальной бумагой, используя кулинарный мешочек, выдавить печеньки на расстоянии двух сантиметров друг от друга. Поставить противень часа на полтора в холодильник. Готовить печенье «Тающий момент» минут тридцать, соблюдая температуру 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5662,'Измельчить чесночок и лук, посыпать перцем, солью. Высыпать смесь на мясо, размешать, поставить часов на шесть в прохладное место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5663,'Измельчить чесночок, соединить с остальными продуктами. Вылить маринад на мясо, поставить на ночь в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5664,'Порезать филе курицы на куски, насыпать специи, налить оливковое масло, сок лимона, размешать. Мариновать минут тридцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5665,'Пропустить лук через мясорубку, бросить лавровый лист, добавить перец, растительное масло, хмели-сунели. В маринад уложить кусочки мяса, размешать, отставить в прохладное место часов на шесть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5666,'Соединить вино и масло, положить специи и розмарин, вылить маринад на мясо, отставить минут на тридцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5667,'Смешать творог и масло, насыпать муку, ванилин, соль, замесить тесто. Сделать пласт толщиной миллиметра три. Вырезать квадратные печеньки. Посыпать сахаром. Выпекать печенье «Творожное» до готовности при температуре 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5668,'Сделать опару. Смешать муку, теплое молоко, сахар, сухие дрожжи. Поставить в тепло на тридцать минут. Положить в опару другие ингредиенты, соль, мешать приблизительно десять минут, пока тесто не станет эластичным. Накрыть тесто полиэтиленом, поставить часа на полтора в тепло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5668,'Поделить на двенадцать частей, скатать шарики приблизительно по сто грамм каждый, отставить минут на десять. Все куски поделить еще на три части. Раскатать все скалкой, в результате должно получиться 36 штук. Взять три лепешки для одной булочки, сложить пополам, снова пополам. Можно брать любой джем, он не будет вытекать, потому что укладываются вниз уголком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5668,'Положить булочки в ячейки формочки для маффинов, вниз уголком, в каждую по три лепешки. Дать настояться минут сорок. Смазать каждую дрожжевую булочку с джемом молочно-яичной смесью, посыпать гранулированным сахаром. Готовить минут тридцать, соблюдая температуру 200 градусов. В месте соединения булочки расслаиваются.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5669,'Замесить тесто: насыпать в емкость муку, сахарный песок, маргарин, порезанный на кубики, соль, взбить яйца. В отдельной посуде погасить соду уксусом, добавить ко всем ингредиентам. Размять вилкой маргарин и осторожно все размешать. Можно использовать миксер с насадкой для теста. Затем выложить тесто на стол, поработать руками. Когда тесто будет готово, положить его часа на полтора в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'последний слой – опять мясо.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10932,'Сверху залить остатками яично-йогуртовой смеси.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5669,'В это время заняться приготовлением крема: положить в емкость сгущенное молоко, грецкие орешки. Орехи предварительно необходимо побить скалкой, терка в этом случае может не подойти, так как получится слишком мелко. Очень хорошо размешать крем и отправить в холодильник. Достать тесто, сделать маленькие заготовки. Необходимо из теста сформировать много шариков, диаметром по полтора сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5669,'Поставить сковородку на огонь, разложить тесто по ячейкам. Закрыть, готовить минуты две. Снять сковороду, вытряхнуть половинки орешков, снова сложить. Повторять процедуру, пока не закончится тесто. Остудить печеньки, обломать лишние края, наполнить половинки кремом и соединить по две штуки. Выложить на тарелку, украсить печенье «Орешки» сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5670,'Высыпать в емкость сухие дрожжи, развести подогретым молоком(1/4 стакана), насыпать соль и сахар. Поставить дрожжи в тепло, чтобы подошли. Муку просеять, насыпать сахар, соль, вбить яйца, аккуратно налить теплое молоко, постоянно мешая, вылить дрожжи. Перемешать до однородности. Следить, чтобы исчезли комки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5670,'Добавить растопленное сливочное масло или растительное. Размешать. Накрыть крышкой, поставить в тепло, чтобы тесто подошло. Повторять процесс раза четыре, каждый раз тесто перемешивать. Следить, чтобы тесто не «убегало». Если емкости не будет хватать, перелить в посуду большего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5670,'Тесто должно подходить, в общем, более двух часов. На сковороду налить чуть-чуть растительного масла, налить часть теста.  Когда пропечется одна сторона, поддеть лопаткой, осторожно перевернуть ажурный блинчик на другую сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5671,'Крупно потереть масло, соединить с солью и яйцом. Налить теплую воду, размешать. В муку насыпать какао, просеять, насыпать в яичную массу, замесить тесто. Завернуть в полиэтилен, отправить минут на тридцать в холод. Вымыть и порезать яблоки или груши на тоненькие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5671,'Разделить тесто на две части. Каждую тонко раскатать, положив на полотенце. Посыпать пласты крошкой сухарей, немного не походя до краев. Положить сверху изюм, груши (яблоки) и миндаль. Посыпать корицей и сахаром. Подогнуть краешки, используя полотенца, свернуть рулетики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5671,'На противень постелить бумагу, намазать маслом. Осторожно переложить штрудель, готовить минут 45, соблюдая температуру 200 градусов. Через каждые пятнадцать минут смазывать шоколадный штрудель с грушей сливочным маслом. Готовые рулеты посыпать сахаром, порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5672,'Духовку разогреть до 210 градусов. Разрезать грудки на несколько частей вдоль, должно получиться четыре штуки. Положить их на дно формочки, посыпать со всех сторон перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5672,'Положить на мясо зубчики чеснока, лимонную цедру, оливковое масло, розмарин. Хорошенько перемешать. Отправить в духовку минут на двадцать. Налить в формочку вино или бульон и сок лимона. Курице с чесноком и лимоном дать постоять минут пять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Подготовить овощи: в принципе не важно, как будут порезаны овощи. Если порезать крупно, то получится великолепный гарнир из овощей. Если порезать мелко, то форму свою овощи потеряют, но блюдо станет невероятно сочным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Почистить и мелко натереть морковь, чтобы не перекладывать, проще тереть сразу на тарелочку. Почистить и порезать лук как угодно: на кольца, полукольца, мелкие кубики и так далее. Переложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'У болгарского перца отрезать хвостик, разрезать пополам. Убрать семена, помыть проточной водой. Порезать на кубики или соломку. Положить в тарелочку. Взять маленький кусочек имбиря, срезать кожицу. Натереть имбирь или очень мелко порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Получается замечательное сочетание при добавлении имбиря в свинину. Вкус особенно понравится любителям острого. Подготовить мясо: желательно приобретать свинину, как на шашлык, то есть, чтобы в мякоти были небольшие прожилки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Порезать на кубики среднего размера. Очень важно резать поперек волокон, чтобы мясо получилось мягким и сочным. Порезанное мясо сложить в емкость, положить чесночок, имбирь, соевый соус, зелень. На тридцать минут отправить в холодильник мариноваться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7369,'Телятина тушеная с овощами под соусом из сметаны подается горячей и посыпанной измельченной зеленью петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Приготовить мясо с овощами: разогреть духовку до 180 градусов. Взять фольгу, нарезать на необходимое количество частей. Положить фольгу на листик, загнуть краешки, положить маринованную свинину, порезанный лук, перец и морковь. Посыпать перцем и солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5673,'Хорошенько завернуть краешки, в одном месте оставить маленькое отверстие для выхода пара. Отправить лист со свининой с овощами в фольге на несколько часов в духовку. Чтобы мясо было запеченным, в конце готовки раскрыть фольгу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5674,'Порезать все продукты на брусочки одного размера. Филе курицы обжарить, посыпав приправой для курицы, чтобы мясо приобрело золотистый оттенок. В конце готовки посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5674,'Обжарить ветчину до румяного цвета. Выложить ржано-пшеничный хлеб на противень, посыпать солью, чуть-чуть полить растительным маслом. Поставить в духовку, соблюдая температуру 250 градусов, подсушивать до легкого поджаривания. Помидоры оставить свежими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5674,'Выложить на плоскую тарелочку сломи: обжаренная курица, половина помидор, чтобы мясо пропиталось соком, обжаренная ветчина. Сверху намазать заправкой, состоящей из аджики, майонеза и чесночка. Положить остальные помидоры. Перед подачей на салат «Кармен» насыпать горкой гренки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5675,'Отделить белки от желтков. Желтки растереть с сахаром (150 г). Положить подтаявшее масло, погашенную соду, эссенцию ванилина, муку и соль. Взбить. Разделить пополам, одна часть должна быть побольше второй. Часть, которая побольше выложить на противень и равномерно распределить. Часть поменьше отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5675,'Крупно потереть на тесто яблоки или разложить ягоды клубники, порезанные пластинками. Взбить белки и сахар (100 г), вылить смесь на пирог. На белки потереть тесто из холодильника. Готовить минут сорок, соблюдая температуру 170 градусов. Если тесто начнет пригорать, то накрыть его фольгой. Яблочный пирог «Мечта» перед подачей охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5676,'Приготовить начинку: тоненькой соломкой порезать грибы, лук и курицу. Обжарить лук на оливковом масле. Положить к луку мясо. Минут через пять бросить грибы, посыпать перцем, солью. Обжаривать, пока не испарится жидкость. Положить сметанку, готовить минут пять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5676,'Отварить ракушки, откинуть на дуршлаг, чуть-чуть остудить. Брать ложкой начинку, нафаршировать все ракушки, покрывая тертым сыром. Начиненные ракушки отправить жульен с курицей в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5677,'Размять картофель, добавить яйцо, сыр, крахмал, размешать. При помощи чайной ложечки сделать маленькие шарики, обжарить во фритюре. Подавать пампушки из картофеля как гарнир или отдельное блюдо. На растительном масле обжарить лук, добавить перец и чесночок, чуть-чуть подсоленной воды. Полить пампушки этой смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5678,'Тонко нарезать сыр, помидор, форель, огурец, шнитт-лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5678,'Приготовить из растертых в ступке чеснока, анчоусов и йогурта соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5678,'Из белого хлеба сделать тосты (сильно не зажаривать).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5678,'Намазать соусом кусочек хлеба и поочередно выложить на него лист салата, помидор, огурец, сыр, шнитт-лук, форель и второй кусочек хлеба, все слои повторить и накрыть третьим тостом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5678,'Перед подачей на стол клаб сэндвич с сыром, овощами и рыбой скрепить шпажкой и срезать с него корки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5679,'Развести дрожжи, сахар и соль в теплой воде или молоке, чтобы все растворилось. В жидкость просеять муку, положить сметанку и растительное масло. Отдельно взболтать яйцо, 1/2 часть налить в тесто, остальное оставить для смазки. Заместить мягкое тесто. Добавить муку, если оно липнет к рукам. Накрыть тесто теплым полотенцем, отложить в тепло минут на тридцать, чтобы оно поднялось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5679,'Отварить в соленой воде рис. Раскатать из теста пласт овальной или прямоугольной формы. Разметить условно в середине эллипс, нарезать от него к краешкам косые полосы толщиной по полтора сантиметра. На эллипс положить рис. Сверху положить рыбное филе, предварительно обваленное в перце, соли, приправах, соке лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5693,'Отправить яблоки в духовку в формочках для выпекания. Готовить минут двадцать, соблюдая температуру 180 градусов. Достать из духовки, посыпать яблоки с творогом и изюмом, сахарной пудрой, на крышечки положить по листику мяты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5679,'На рыбку положить лук, порезанный на полукольца. Уложить порезанные полоски на начинку в форме косички. Тесто эластичное, поэтому полоски можно вытянуть, сложить вдвое, сплести косичку. Сформировать плавники, хвост и голову. Загнуть лишние края. Смазать оставленным яйцом. Готовить рыбный пирог с рисом минут тридцать, соблюдая температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5680,'Почистить и отварить картофель. Слить воду, вбить яйцо, положить сливочное масло. Сформировать из пюре тефтели, обвалять в муке, пожарить. Мелко порезать и обжарить лук. Порезать грибы на небольшие кусочки, положить к луку, жарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5680,'Насыпать муку, посыпать перцем, солью, добавить сливки, чуть-чуть потушить. Смазать формочку маслом, положить тефтельки, полить соусом, отправить на пять минут в духовку. Готовить тефтели из картофеля под грибным соусом при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5681,'Почистить бананы, порезать на четыре кусочка вдоль и поперек. Растопить масло на антипригарной сковороде. Положить бананы вниз плоской стороной, обжаривать по несколько минут с двух сторон. Подавать жареные бананы теплыми с взбитыми сливками или мороженым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5682,'Приготовить ванильный пудинг: смешать сахарную пудру, желток, яйца, крахмал, соль. Налить молоко. Кастрюльку сполоснуть холодной водой, стряхнуть хорошенько воду. Налить молоко, насыпать сахар, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5682,'Снять с огня, вылить молоко в яичную смесь, непрерывно мешать, чтобы не сварились яйца. Вылить смесь в кастрюлю, поставить на огонь. Варить минут пять, помешивая время от времени. Снять с огня, положить ванилин и масло. Если есть комочки, процедить через марлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5682,'Накрыть емкость полиэтиленом, на несколько часов отправить в холодильник. Взбить сливки, осторожно ввести в пудинг. Застелить формочку фольгой. Положить на дно печенье, выложить пудинг со сливками. Снова слой печенья, на него пудинг и так далее. Сверху должен быть слой печенья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5682,'Должно получиться три слоя печенья и два пудинга или шесть печенья и пять пудинга. Отправить в холодильник. Приготовить шоколадную глазурь: растопить сливочное масло и шоколад. Перемешать. Охладить. Нанести глазурь на торт-эклер из печенья. Поставить для охлаждения в холодильник минимум на шесть часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5683,'Смешать сахар с маслом и растереть, вбить яйца и перемешать все до однородности, добавить овсяные хлопья, тщательно размешать еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5683,'Всыпать в полученную смесь муку, смешанную с разрыхлителем, мелкие кусочки шоколада, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5683,'Накрыть миску с тестом и убрать примерно на час в холодильник (за это время хлопья чуть размокнут и станут мягче).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5683,'Достать тесто и включить на разогрев духовку до 180 градусов, сформовать  небольшие плоские лепешки, выложить с расстоянием на смазанный противень (с учетом увеличения размера в 2 раза) и отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5683,'Овсяное печенье по-домашнему с шоколадом будет готово через 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5684,'Нарезать тонкими пластинками бекон и обжарить до хруста на среднем огне, выложить на бумажное полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5684,'Сварить вкрутую яйца, почистить и измельчить, добавить мелко порубленные листья салата, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5684,'Пожарить в жире от бекона до мягкости мелко нашинкованный лук-шалот 2 минуты, влить уксус, смешанный с солью, дать закипеть и тушить 10 секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5684,'Быстро смешать горячее содержимое сковороды с яичной смесью, добавить к салату бекон, посолить, поперчить, заправить маслом, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5684,'Салат ромен по-американски с яйцами и беконом подается к столу сразу после приготовления.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5685,'Нарезать одинаковыми кубиками мясо и колбасу, обжарить говядину в растительном масле 7 минут, засыпать колбасу и жарить еще 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5685,'Нашинковать мелко лук, измельчить чеснок и сладкий перец, нарезать ломтиками черешки сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5685,'Добавить все к мясу, поперчить смесью из перцев, посолить и на среднем огне тушить 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5685,'Всыпать рис, перемешать, обжарить 2 минуты, добавить бульон, заправить лавровым листом, дать закипеть, сделать огонь минимальным и тушить 20 минут, закрыв крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5685,'Готовый американский ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10944,'Замесить полужидкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5686,'Ребрышки посыпать перцем и солью, пожарить до румяной корочки. В кастрюльку положить душистый перец, лавровый листик, половину лука, порезанного на полукольца, мясо. Налить чуть-чуть бульона или воды, тушить. Крупно порезать картофель, обжарить, положить к мясу. Капусту нашинковать, морковь порезать соломкой, чуть-чуть обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5686,'Положить обжаренную капусту на слой картофеля. Добавить разведенную томатную пасту или томат, не перемешивая, поставить на огонь, готовить овощное рагу с капустой и свининой до полной готовности. Жидкости не должно быть очень много, она не должна покрывать всю капусту, потому что овощи дадут сок. Посолить блюдо по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5687,'Положить, не разрезая кусок ветчины в кастрюлю, залить водой и при сильном нагреве дать закипеть. Убавить огонь, заправить перцем, солью, всыпать фасоль и варить примерно час до полного размягчения фасоли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5687,'Дать мясу чуть остынь в бульоне, вынуть и нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5687,'Оставить в кастрюле с фасолью примерно стакан жидкости, положить мясо, заправить перцем, солью, перемешать и немного подогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5687,'Копченую ветчину с зеленой фасолью по-американски подавать в глубоких тарелках с чесночным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5688,'Размягчить маргарин или масло при комнатной температуре или растопить в микроволновой печи. Положить в масло сахар, вбить яйца, налить кефир, размешать. Насыпать соду, медленно насыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5688,'Перебрать ягоды смородины, вымыть, чуть-чуть обсушить, положить в тесто, размешать ложкой. Разложить тесто в специальные формочки. Не докладывать тесто до верха, так как маффины поднимутся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5688,'Выпекать маффины «Чудо-ягода» со смородиной минут тридцать, соблюдая температуру 170 градусов. Вынуть формочки из духовки, охладить, вынуть и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5689,'Замесить тесто. На противень, застеленный бумагой и смазанный маслом, положить шарики по величине, как грецкий орех, на некотором расстоянии друг от друга. Готовить при 180 градусов. Противень размещать посередине духовки, чтобы верх был румяным, а низ не подгорел.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5689,'В готовых сферах вырезать серединки, чтобы внутри получилась пустота. Приготовить начинку: смешать сахар, какао, сметану. Измельчить крошку, вырезанную из сфер, положить в крем, размешать. Должна получиться вязкая, не сухая и не очень жидкая начинка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5689,'Положить начинку в сферы, склеить, как персики. Обмакнуть каждое пирожное в варенье или сок смородины, сразу обвалять в сахаре. Положить пирожные «Персики» со сметанным кремом на противень, чтобы пропитались.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5690,'Сделать из батона сухарики. Порезать все на крупные кубики, заправить салат майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5691,'Разогреть духовку до двухсот градусов. Желательно брать нежирную свинину, где очень тоненький слой сала и жира. Если на кусочке много жира, то частично его необходимо срезать. Поскрести шкурку ножом, мясо хорошенько промыть, обсушить. Разрезать свинину вдоль, не дорезая 1 сантиметр до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5691,'Развернуть Кусок мяса станет тоньше, но длиннее. Положить мясо на столе вниз шкурой. Раздавить чесночок, смешать с солью. Насыпать в чесночную смесь молотый перец, орегано, хлопья красного перца. Натереть мясо. Скрутить мясо плотно рулетом, шкурка должна быть снаружи. Обмотать крепкой нитью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5691,'Завернуть полученный рулетик в фольгу, сложенную в несколько слоев. Положить на противень с решеткой. Отправить на несколько часов в духовку. Проткнуть мясо тоненьким ножом в центре. Если просочился прозрачный сок, значит, рулетик готов. Чтобы шкурка не была жесткой, рулет должен лежать шкуркой вниз. Обмазать пряный рулет из свинины выделенным соком, снова положить в духовку минут на двадцать пять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5692,'Измельчить лук, порезать на мелкие кусочки шампиньоны. Пожарить на растительном масле. Нарезать колбаску тоненькой соломкой. С фасоли слить жидкость. Положить все в салатник, размешать. Заправить салат «Фасолинка» майонезом. Если необходимо, посыпать солью. Можно положить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5693,'Вымыть и обсушить яблоки. Срезать крышечку, с помощью чайной ложечки достать сердцевину. Положить творог в емкость, вбить яйцо, положить по вкусу сахар, изюм, перемешать. Переложить массу в яблоки, накрыть срезанными крышечками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5694,'Разогреть духовку. Формочку застелить бумагой, смазать любым маслом и посыпать мукой. Соединить какао, муку, соль и соду. Соединить отдельно масло, воду, сахар, кофе и уксус. Взбить, чтобы растаял сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5694,'Соединить смеси, размешать до однородности. Налить тесто в формочку, готовить минут сорок. Охладить и порезать. Сверху посыпать влажный шоколадный пирог тертым шоколадом или покрыть шоколадным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5695,'Включить духовку, нагреть до 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5695,'Взбить сахар со сливочным маслом, добавить яйцо продолжить взбивать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5695,'Всыпать постепенно, не прекращая размешивать, смесь муки, пекарского порошка и корицы, влить в тесто эспрессо и молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5695,'Смазать круглую форму маслом, переложить в нее тесто и поставить выпекать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5695,'Через час пирог с медом и орехами «Эспрессо» по-американски будет готов, дать пирогу остыть и залить сверху медом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5696,'Помыть филе курицы под проточной водой, порезать на маленькие кусочки. Почистить лук, порезать на тоненькие полукольца. Положить лук на сковороду, обжарить. Потереть морковь на терке для корейской моркови, так она будет красивой и быстро прожарится. Лук жарить минуты три, затем положить морковь и обжаривать все вместе. Когда овощи хорошенько прожарятся, добавить мясо, во время тушения курица впитает запах и вкус обжаренных овощей. Порезать соломкой сладкий перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5696,'Положить перец в сковороду, обжаривать вместе с курицей, морковью и луком. Перемешать. Соединить в емкости кетчуп, томатную пасту, перец и соль. Размешать до однородности. Когда мясо приобретет золотистую корочку, вылить смесь в сковороду, размешать, добавить воду, посыпать перцем, солью, приправами. Сделать огонь максимальным. После закипания сделать маленький огонь и тушить под крышкой минут пятнадцать. Несколько раз перемешивать. Гуляш из куриной грудки с болгарским перцем подавать с макаронами или картофельным пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5697,'Соединить яйца, муку и майонез. Перемешать. Вылить тесто в формочку для выпекания. Приготовить начинку: сначала слой колбасы, потом лук, помидоры. Насыпать слой тертого сыра. Можно посыпать зеленью. Поставить быструю пиццу в духовку, готовить минут пятнадцать, соблюдая температуру двести градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5698,'Порезать сосиски на мелкие кубики, положить в глубокую посуду. Порезать на кубики помидор, измельчить зелень, положить к сосискам. Добавить прессованный чесночок. Выложить к продуктам кетчуп и майонез, размешать. Положить на противень хлеб, на каждый кусочек положить чуть-чуть начинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5698,'Посыпать молотым перцем. Крупно натереть сыр, посыпать им сверху все кусочки. Но сыра не должно быть очень много, так как в процессе готовки он начнет растекаться. Поставить быстрые горячие бутерброды на пятнадцать минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5699,'Порезать филе курицы на большие куски, обжарить с приправами. Посыпать перцем, карри, солью. Отварить яйца, крупно порезать. Крупно нарезать перец и помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5699,'Порезать лук на полукольца, замариновать. Порезать на продолговатые брусочки ржаной хлеб, подсушивать минут семь в духовке при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5699,'Тщательно промыть и просушить салатные листья, положить на тарелку. На салат выложить ингредиенты слоями в следующем порядке: мясо, лук, помидоры, перец, сухари, яйца. Полить салат из курицы соусом тартар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5700,'Измельчить в кухонном комбайне печенье. Добавить какао, ванилин, сахар, корицу, размешать. Растопить масло, налить в печенье. Подогреть чуть-чуть молоко, влить в массу тоненькой струйкой. Сделать из теста пирожные. Отправить пирожные «Картошка» в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5701,'Развести дрожжи в теплом молоке, положить масло, насыпать муку и соль. Замесить тесто. Чтобы тесто было при выпекании мягким, оно должно чуть-чуть липнуть. Порезать колбасу и помидоры, лук на полукольца, зелень мелко. Растопить масло. Крупно натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5701,'Раскатать тесто по противню, намазать топленым маслом, кетчупом. Положить слой лука, колбасы, помидоров. Посыпать зеленью, сыром, залить пиццу «Праздничную» майонезом. Готовить в духовке минут пятьдесят, соблюдая температуру 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Всего через несколько суток ягодную жвачку можно пробовать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5702,'Обжарить лук до прозрачного состояния в небольшом количестве масла. Положить фарш, приправы, обжаривать фарш вместе с луком. Добавить помидоры и готовить, пока вся жидкость не испарится. Порезать грибочки и отдельно пожарить их в небольшом количестве масла. Посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5702,'Приготовить соус Бешамель: растопить в кастрюльке масло. Насыпать муку, обжаривать секунд шестьдесят, непрерывно помешивая. Тоненькой струйкой налить молоко, не переставая помешивать соус. После закипания посыпать перцем, солью, добавить мускатный орех. Готовить минуту, снять соус с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5702,'Взять формочку, желательно стеклянную с высокими бортиками. Налить в нее соус, положить листы лазаньи. Выложить слой фарша, лука и помидоров. Насыпать сыр пармезан, вновь полить соусом. Положить листы лазаньи, соус, после этого слой грибов и посыпать пармезаном. В конце положить листы лазаньи, полить соусом, посыпать сыром Гауда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5702,'Отставить лазанью минут на шестьдесят, накрыть фольгой, отправить минут на двадцать в духовку. Готовить при температуре 150 градусов. Убрать фольгу, выпекать до готовности. Домашняя мясная лазанья с соусом Бешамель должна приобрести золотистый оттенок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5703,'Взять большую кастрюльку, налить воду, посолить, поставить на огонь. Порезать баклажаны вдоль, в виде лодочек, должен получиться вместительный кармашек. Положить баклажаны в кипящую воду. Если они всплывут, ничего страшного, накрыть крышкой, подождать, копа они станут мягче и поменяют цвет. Это может занять от пяти до десяти минут – в зависимости от количества овощей. Положить баклажаны на наклонную поверхность. Придавить их доской или любым другим грузом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5703,'Подождать, пока сечет жидкость. Подготовить обыкновенный лук и порей, чесночок разделить на зубчики, болгарский перец. Подготовить приправы и специи. Приготовить маринад, используя черный перец горошком, лавровый лист, душистый горошек. Положить в воду сахар, уксус, чтобы получился кисло-сладкий вкус. Затем насыпать соль. Обжарить на растительном масле лук, положить семена кориандра. Добавить лук порей, сладкий перец, размешать.  Положить чесночок, сухую зелень, приправы. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5703,'Положить в сковороду зеленый лук, свежую зелень, морковь, убрать с огня, размешать. Поставить баклажаны, посуду для маринования, овощную смесь, зелень, приправы. Если в баклажанах осталась жидкость, отжать ее руками. Раскрыть баклажаны – лодочки, начинить зеленью, начинкой. Овощей не должно быть много. Уложить баклажаны плотно и залить кипящим маринадом. Придавить маринованные баклажаны с овощами, чтобы они были полностью погружены в жидкости. Емкость поставить на семь дней в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5704,'Отваривать сосиски минут десять. Снять пленку, охладить. Помыть и порезать помидоры на маленькие кубики. Положить в глубокий салатник. Порезать на такие же кубики твердый сыр. Измельчить зеленый лук, положить в емкость для салата. Если используется репчатый лук, то порезать его на полукольца. Выдержать пару минут в кипятке, положить в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5704,'Можно по вкусу добавить зелень петрушки или укропа. Тогда салат приобретет более изысканный и насыщенный вкус. Холодные сосиски порезать на колесики. Положить к остальным ингредиентам. Размешать, посыпать солью. Заправить салат «Баварский» с сосисками и помидорами майонезом, разложить по тарелочкам и подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5705,'Добавить к смеси муки, дрожжей, сахара и соли (3 ч.л.) теплую воду и масло (4 ст.л), замесить мягкое тесто и убрать для поднятия в теплое место на 90 минут',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5705,'Натереть на терке пармезан, мелко покрошить чеснок, помидоры, добавить соль (1 ч.л.), орегано и базилик, все хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5705,'Обжарить до мягкости измельченные баклажаны, лук, цуккини, сладкий перец, дать овощам остыть и смешать с мелко порезанным сыром моцарелла, включить разогреваться духовку до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5705,'Достать тесто, слегка вымесить, разложить по смазанной маслом сковороде, сформировать по краям бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5705,'Выложить овощную начинку с моцареллой на тесто, залить сверху томатно-чесночной смесью с пармезаном, запекать 10 минут с нижним подогревом, затем пицца фаршированная сыром и овощами по-чикагски выпекается еще 30 минут, но уже в режиме среднего подогрева.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5706,'Почистить, помыть, крупно потереть морковь и обжарить на растительном масле. Почистить лук, вымыть, порезать на тоненькие полукольца, обжарить. Переложить обжаренные овощи в салатник, чуть-чуть охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5706,'Огурец и колбасу порезать кубиками. Положить все к обжаренным овощам. Положить сухарики Кириешки. Все продукты размешать, заправить салат «Обжорка» майонезом. Украсить зеленью и подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5707,'Залить желатин, оставив грамм 5-10 на клубничное пюре, молоком, отставить минут на пятнадцать. Поставить на медленный огонь. Нагреть, постоянно помешивая. Молоко не должно закипеть. Снять с огня, когда желатин растворится. Охладить. Вылить в глубокую посуду йогурт, насыпать сахар, добавить лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5707,'Взбить хорошенько миксером. Отлить 1/3 часть смеси в отдельную посуду, насыпать какао-порошок, размешать. Вылить смесь в специальную съемную формочку, отправить на двенадцать минут в морозильную камеру, достать, вылить всю оставшуюся смесь. Отправить в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5707,'Приготовить клубничное пюре: в блендере соединить сахар и ягоды клубники. Положить оставшийся желатин в воду, оставить минут на десять. Нагреть на тихом огне, мешая. Охладить вылить в пюре из клубники. Перемешать, вылить на застывший йогуртовый десерт. Отправить йогуртовый торт с клубникой без выпечки в морозильную камеру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5708,'Достать масло их холодильника, чтобы оттаяло. Духовку разогреть до 170 градусов. Отрезать макушку чесночных головок таким образом, чтобы каждый зубчик было видно. Положить головки на лист для выпекания, покрытый фольгой, сбрызнуть оливковым маслом. Готовить пятьдесят минут, чеснок должен стать мягким. Когда чеснок станет холодным, выдавить зубчики из шкурок, порезать крупно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5708,'Натереть сыр, измельчить петрушку. Соединить сыр, масло, чеснок, петрушку и соль. Порезать хлеб, разложить на лист для выпекания. Включить гриль или духовку разогреть до 240 градусов. Намазать чесночное масло на кусочки хлеба. Готовить хлеб с чесночным маслом под грилем или в духовке минуты четыре, должен стать поджаристым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5709,'Разрезать кабачок вдоль, вычистить серединку. Измельчить филе курицы. Обжарить. На второй сковороде обжарить измельченные овощи. Сначала лук с морковью, потом перец и помидоры. Держать на огне несколько минут. Можно добавить баклажаны, цветную капусту и так далее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5709,'Можно использовать серединку кабачка. Нафаршировать кабачки. Уложить мясо, в сверху овощи. Положить кусочек масла, соль, карри. Завернуть в фольгу. Готовить минут сорок. Фольга сделает блюдо ароматным и сочным. Перед подачей посыпать фаршированные кабачки с овощами и курицей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5710,'Натереть кабачки, разогреть сковороду, налить оливковое масло, обжарить тертые кабачки. Выложить на дуршлаг, подождать, пока стечет жидкость. Обжарить на сковороде измельченный чеснок и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5710,'Взбить в емкости венчиком яйца с солью. Взять любой мягкий сыр, например, фету. Измельчить вилкой сыр и смешать с измельченной зеленью. Вылить туда яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5710,'Выложить смесь из кабачков, сыра, яиц, чеснока, зелени и лука в формочку для выпекания, смазанную маслом. Посыпать все сыром. Поставить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5711,'Вымыть проточной водой и измельчить зелень. Вымыть помидоры и порезать на маленькие дольки. Вымыть сладкий перец, почистить от семян, порезать соломкой. Почистить чеснок, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5711,'Соединить все ингредиенты, посыпать сахаром, солью, полить любым маслом, уксусом. Разложить по баночкам, накрыть крышками из капрона. Отправить часов на восемь в холодильник. Хранить зеленые помидоры по-корейски в подвале или холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5712,'Почистить болгарский перец, вынуть семена. Тоже сделать и с острыми стручковыми перцами. Почистить чеснок и измельчить. Соединить перечисленные продукты и пропустить через мясорубку. Положить зелень, масло, уксус, посыпать солью, сахаром. Перемешать. Помыть помидоры, порезать на четыре части. Если они маленькие, то можно просто разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5712,'Взять 3-литровую чистую банку, сначала положить хрен (корень, лист), сверху помидоры слоем, на них положить перцы с чесноком, опять помидоры, затем перцы и так, пока баночка не будет полной. Закрыть банку крышкой из капрона. Хранить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5713,'Помыть и чуть-чуть обсушить помидоры, порезать половинками. Почистить чесночок и болгарский перчик, пропустить через мясорубку, соединить. Вымыть морковь, потереть. Измельчить любую зелень по вкусу. Выложить в баночку (лучше брать 3-литровую) все продукты слоями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5713,'Помидоры (срезами вверх), сверху перец с чесноком, дальше морковь, сверху слой зелени. Повторить слои в той же последовательности. Так заполнится вся банка. Между слоями, в нескольких местах положить совсем чуть-чуть горького красного перца и специи по вкусу (базилик и так далее).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5713,'Приготовить маринад: соединить соль с маслом, уксусом и сахаром, мешать пока не растворится соль и сахар. Вылить маринад в банку, накрыть крышкой из капрона, перевернуть и поставить помидоры по-корейски с морковью и чесноком в холодильник часов на десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5714,'Порезать кружками кабачки, порезать луковицу. Посыпать специями, солью. Осторожно перемешать. На пластинки порезать плавленый сырок, перемешать с кабачками. Добавить растительное масло, готовить на маленьком огне, пока не растворится сырок, непрерывно помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5714,'Подготовить формочку, смазать маслом. Взбить яйца, добавить к кабачкам. Выложить смесь в формочку. Готовить кабачковую запеканку с плавленым сыром до румяной корочки, соблюдая температуру 180 градусов. Чуть-чуть охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5715,'Приготовленная по данному рецепту квашеная капуста получается хрустящей, безумно вкусной и очень быстро готовится. Заквашивается в рассоле, поэтому руками мять не нужно. Очень легкий рецепт, который проверен годами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5715,'Приготовить рассол: растворить сахар и соль в теплой воде. Очистить капусту от первых листьев, разрезать пополам, нашинковать на терке, в комбайне или с помощью ножа. Крупно потереть морковь. Переложить морковь в капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5715,'Переложить смесь в банку, чуть-чуть утрамбовать. В середине положить пару лавровых листов и перец горошком. Вылить в баночку рассол, чтобы он полностью покрыл капусту. Уйдет от 1,2 до 1,5 литров рассола, в зависимости от того, как порезана капуста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5715,'Неплотно закрыть банку крышкой или накрыть бинтиком, сложенным в два раза. Поставить в глубокую емкость, потому что при брожении рассол будет подниматься и выливаться через край. Оставить приблизительно на трое суток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5715,'Следить, чтобы вся капуста была в рассоле. Если его мало, то утрамбовать овощи вилкой. Если в помещении высокая температура, то через 48 часов капуста будет готова. После чего квашеную капусту с морковью нужно отправить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5716,'Почистить и измельчить чесночок при помощи чесночницы. Разогреть масло на сковороде, положить чесночок. Положить сливки, вскипятить. Почистить креветки, бросить в сковороду. Хорошенько перемешать, тушить минут десять. Помыть и измельчить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5716,'Посыпать смесь в сковороде зеленью. Перемешать, тушить минуты три. Выложить креветки на тарелку, тушить соус до загустения. Положить креветки в густой соус. Перемешать, готовить креветки с чесноком под сливочным соусом приблизительно три минуты. Перед подачей выложить на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5717,'Почистить рыбу, выбросить внутренности, порезать на средние кусочки, посыпать солью, запанировать в муке, пожарить. Положить измельченный лук, чесночок, перец, налить вино, воду. Тушить минут семнадцать. При подаче тушеную рыбу посыпать зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5718,'Выложить в глубокую сковороду кусок подкопченного окорока шкуркой вниз, влить кока-колу, добавить нашинкованный лук, дать закипеть, уменьшить нагрев и тушить мясо 2,5 часа, накрыв крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5718,'Разогреть духовку до температуры в 240 градусов, дать окороку чуть остыть и снять с него шкурку, переложить его на застланный фольгой противень, сделать ножом на жире насечку в виде сетки и воткнуть в места пересечения линий по бутончику гвоздики, обмазать кусок глазурью из патоки, порошка горчицы и сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5718,'Отправить свиной окорок в соусе из кока-колы на 15 минут запекаться в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5719,'Соединить ингредиенты так, как они написаны, не считая масла. Накрыть и отправить в тепло на шестьдесят минут. После этого тесто не перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7878,'В чашу блендера влить сливки, положить кукурузу, измельчить.','https:https://st.vkuso.ru/data/cache/thumb/69/3fb09fde2126069_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5720,'Порезать картофель и отварить. Порезать ветчину на полоски, обжарить. Лук порезать на полукольца, отдельно обжарить. Соединить лук с ветчиной. Добавить отваренный картофель, посыпать перцем, солью, картофель по-крестьянски осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5721,'Порезать сырые овощи: помидор на кубики, синий лук на кольца, чеснок, кинзу. Положить в салатник. Печень обвалять в муке и пожарить на масле. Положить к остальным овощам, размешать. Накрыть теплый салат с печенью крышкой и оставить минут пятнадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5722,'Вымыть персики, удобно сделать это с помощью простой ткани белого цвета из хлопка. Она хорошо избавляет персики от налета, руки при этом не повреждаются. Порезать персики на дольки, убрать косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5722,'Обдать кипятком лимон, порезать с цедрой на квадратики, таким же образом порезать корни имбиря и цукаты. Засыпать персики сахаром, подождать, пока растворится сахар. Проходит приблизительно 120 минут, сочные персики выделяют много сока. Лимон можно положить в конце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5722,'Готовить варенье на тихом огне в три раза по пять минут. Желательно варить 2 раза, на ночь оставить, утром проварить третий раз. Готовность проверять, капнув немного на тарелочку. Если варение не растекается, то можно закатывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5722,'Достать палочку корицы и выбросить. Благодаря корице варенье приобретет необыкновенно розоватый оттенок. Разложить горячее персиковое варенье с лимоном и корицей по простерилизованным банкам, закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5723,'Поместить в миксер муку и соль, взбивать на маленькой скорости, постепенно положить сливочное масло, насыпать муку, налить холодную воду. Перемешать до однородности, обернуть тесто в полиэтилен, прижать, чтобы получился ровный пласт. Положить минут на шестьдесят в холодильник. Намазать маслом формочку со съемными стенками, застелить специальной бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5723,'Раскатать тоненько тесто, обильно посыпать мукой. Переложить тесто в формочку, сформировать из теста бортики. Поставить формочку с тестом в холодильник минут на двадцать. Нагреть духовку до 160 градусов. Застелить тесто специальной бумагой, насыпать сверху рис, горох или фасоль в качестве утяжелителя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5723,'Готовить минут сорок до золотистой корочки. Осторожно достать утяжелитель и бумагу. Не выключать духовку. Приготовить начинку: нагреть масло на сковороде. Бросить порезанные грибы, посыпать перцем, солью, готовить минут пять, грибы должны стать мягче. Сделать огонь меньше, положить сливочное масло, измельченный лук, тимьян, готовить минут двенадцать, помешивая, пока грибы не приготовятся. Посыпать перцем, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5723,'Охладить. На дно основы положить 1/3 сыра и 1/2 грибов. Измельчить в блендере сливки, молоко, яйца, соль, перец горошком, мускатный орех до однородности. Залить грибы 1/2 смеси. Закрыть 1/3 сыра и оставшимися грибами. Вылить остальную молочную смесь, посыпать сыром. Готовить пирог «Очень грибной» приблизительно полтора часа. Достать из формочки, выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5724,'Измельчить лук, потереть морковь, помидоры пропустить через мясорубку. Поочередно обжарить лук и морковь. Вылить помидоры в глубокую посуду (например, кастрюльку), уваривать на 1/3 часть. Перец минуты на три поместить в кипящую воду, выложить на дуршлаг, снять кожуру, пропустить через мясорубку. Порезать кружочками баклажаны, тушить до румяного цвета. Если имеется большая сковорода, то можно обжарить на ней.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5724,'Пропустить через мясорубку. Соединить в большой емкости морковь, лук, баклажаны, укроп, помидоры, петрушку, перец. Посыпать перцем, солью, готовить минут тридцать на тихом огне. Минут за пять до конца готовки положить в овощную икру из баклажанов и перца измельченный чесночок. Ошпарить банки кипятком, прокипятить крышки, в горячие баночки сложить икру. Поставить стерилизоваться минут на восемьдесят. Вынуть баночки, закатать, поставить вниз крышкой, накрыть одеялом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5725,'Порезать куриные грудки тоненькими пластинками, осторожно отбить, посыпать перцем и солью. С одной стороны намазать сыром, свернуть рулетик внутрь сыром. Обернуть рулет полоской бекона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5725,'Положить рулетик в формочку, посыпать любыми специями. Готовить куриные рулетики в беконе минут пятьдесят, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10989,'Кабачки вымыть, нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5727,'Натереть все ингредиенты мелкой соломкой, посыпать солью. Отставить, чтобы овощи пустили сок. Добавить муку, яйцо, чесночок, посыпать перцем, дракабаники обжарить. Можно положить чуть-чуть сметанки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5728,'Приготовить тесто: мягкий маргарин, положить к нему взбитые яйца, муку, посыпать солью. Замесить тесто. Накрыть, отправить на тридцать минут в холодильник. Измельчить и обжарить лук, положить грибы, готовить минут десять. Почистить и отварить до полуготовности картофель. Взбить отдельно яйца, молоко, сметану, муку и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5728,'Раскатать тесто, положить в формочку, загнуть краешки в виде бортиков. На дно положить картофель, лук с грибами, вылить заливку. Готовить минут шестьдесят, соблюдая температуру 170 градусов. Необходимо следить, чтобы пирог с картошкой и грибами подрумянился и пропекся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5729,'Отварить креветки в специях (соль, лавровый листик, перец горошком). Отварить картофель, яйца, почистить, потереть. Нарезать креветки пополам, разделить на несколько частей. Выложить в салатник слои: 1/2 креветок, картофель, яйца, креветки, икра. Все слои смазывать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5729,'Поставить салат минимум часов на шесть в холод. Перед подачей салат «Креветки под шубой» украсить кусочками лимона, зеленью, остальными креветками, розочкой из помидора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5730,'Взять куриные окорочка, отделить мякоть от костей. Грибы порезать на соломку. Измельчить лук. Потушить под крышкой грибы, когда испарится жидкость, налить растительное масло, бросить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5730,'Обжарить лук, положить к нему тертый сыр. Переложить грибной фарш на блюдо, охладить. Посыпать мясо перцем и солью. Положить на мясо грибной фарш, свернуть рулетик. Перевязать его нитью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5730,'Смазать противень маслом, выложить на него рулетики, отправить в духовку, готовить минут шестьдесят. С готовых куриных рулетов с шампиньонами снять нить, разрезать на несколько частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5731,'Порезать все овощи соломкой, перемешать с маслом и уксусом. Положить в баночки, закрыть крышками из капрона. Хранить овощной салат с капустой в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5732,'Соединить сметану с яйцами, маслом и солью. Насыпать разрыхлитель и муку. Получится жидковатое тесто. Взять разъемную формочку 23 сантиметра. Смазать маргарином. Вылить в нее тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5732,'Соединить творог, фрукты и яйца. Положить ложечкой на тесто по кругу и в середине. Готовить ленивую творожную ватрушку минут сорок, соблюдая температуру 225 градусов. Немного охладить и достать из формочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5733,'Отварить гречку и охладить. На растительном масле обжарить грибы, морковь и лук. К гречке положить обжаренные грибочки, размоченный хлеб, зелень, посыпать специями. Размешать (например, в блендере).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5733,'Из гречневого фарша сделать котлетки, обвалять в панировочных сухариках. Пожарить постные гречневые котлеты с грибами на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5734,'В подсоленной воде сварить куриное филе. Охладить и измельчить мясо. Отварить яйца, остудить, почистить, крупно потереть. Также крупно потереть сыр, яблоко, огурцы. Размешать, заправить салат «Облако» майонезом, посыпать солью. Переложить салат в салатник, посыпать укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5735,'Взять телятину или мясо курицы. Порезать мясо на кусочки, посыпать перцем, солью, положить несколько ложек майонеза или чуть-чуть подсолнечного масла. Оставить минут на пять. Порезать полукольцами лук и замариновать на три минуты в уксусе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5735,'Порезать помидор, болгарский перец, картофель, кабачок, потереть сыр. Отрезать квадратный кусок фольги, на дно положить кабачок, помидор, сладкий перец, кубики картофеля, посыпанного перцем и солью, мясо, маринованный лук, кусочек сливочного масла, завернуть узелки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5735,'Отправить узелки из фольги с мясом на сорок минут в духовку, охладить, посыпать сыром, поставить еще минут на пять. Время готовки зависит от вида мяса, например, курица готовится быстрей. Получается очень вкусное и сочное мясо с овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Подрумянить хлеб в тостере (сильно не зажаривать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5736,'Смешать майонез с небольшим количеством оливкового масла, раздавленным зубчиком чеснока и соусом Табаско (или свежемолотым перцем).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Остудить галеты с черешней и корицей. Посыпать сахарной пудрой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5737,'Залить желатин водой и дать настояться. Поставить желатин на огонь, насыпать сахар, помешать, чтобы полностью растворился сахар. Убрать с огня, охладить. Растопить шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5737,'Вылить смесь в миксер, положить мед, растопленный шоколад, минут десять перемешивать до однородности. Перелить смесь в формочку, на шестьдесят минут отправить в холод. Когда шоколадный зефир станет твердым, порезать на кубики, обвалять в какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5738,'Соединить яйца, сгущенное молоко, добавить соду, гашенную уксусом, насыпать муку, размешать, замесить не сильно крутое тесто. Скатать тесто колбаской, порезать на небольшие куски, скатать шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5738,'Пожарить шарики до золотистого цвета на сковороде. Выложить пончики на салфетку – она впитает лишнее масло. Обвалять пончики на сгущенке в сахарной пудре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5739,'Развести дрожжи в теплом молоке или питьевой воде, насыпать сахар. Когда дрожжи станут пениться, сделать тесто. Соединить ингредиенты, замесить тесто. Чтобы не было сильно жидким, насыпать еще муку. Также тесто не должно липнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5739,'Отправить дрожжевое тесто в тепло часа на два. Несколько раз обмять и на третий формировать пирожки. Застелить противень бумагой, положить пирожки, намазать яйцом, готовить до зарумянивания при температуре двести градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5740,'Приготовить фарш: обжарить грибы, измельченный лук, тертую морковь. Посыпать перцем, солью. Соединить продукты с яйцом и фаршем. Из готового слоеного теста вырезать кружки, в 1/2 кружков сделать отверстия с помощью рюмки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5740,'На целый кружок положить фарш, накрыть кружком с отверстием, краешки придавить вилкой, намазать яйцом, посыпать сыром, отправить в духовку минут на тридцать, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5740,'Подавать сытные гусарики с мясным фаршем со сметанным соусом и зеленью. Чтобы приготовить сметанный соус, необходимо выдавить чеснок в сметану, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5741,'Смешать в кастрюльке сливочное масло, сахар, соль и воду. Поставить на огонь, довести до кипения и незамедлительно снять. Дать остыть. Просеять разрыхлитель и муку. В муку выложить остывшую массу. Получится масляное тесто. Сформировать шар, обернуть полиэтиленом, положить часа на три в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5741,'Достать и порезать шар на пять или шесть частей, чтобы было удобней. Присыпать поверхность мукой, раскатать пласт толщиной три миллиметра. Тесто раскатать осторожно, потому что оно сильно крошится и ломается. Намного удобней раскатывать небольшие кусочки. Вырезать из подготовленного теста заготовки для печенья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5741,'Для этого можно использовать абсолютно любые формочки. Постелить специальную бумагу на противень, выложить печенье, готовить минут пятнадцать, соблюдая температуру 180 градусов. Когда печенье «Маленький принц» станет румяным, вынуть и остудить. Не доводить до сильно румяного состояния, чтобы печенье оставалось рассыпчатым и нежным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5742,'Готовятся за пятнадцать минут. Вымыть изюм и измельчить в блендере. Соединить все ингредиенты. Все смешать до однородности. Сделать шарики по 2,5 см в диаметре. Обкатать в измельченном орехе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5743,'Нарезать хлеб и смазать оливковым маслом. Обжарить в духовке. На все кусочки положить слайс моцареллы и лосося. Соединить чесночный порошок, мед, соевый соус. Побрызгать данной смесью все бутерброды. Посыпать хрустящие кростини измельченным зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5744,'Порезать куриное филе на полоски или маленькие кусочки. Смазать формочку маслом, выложить мясо. Посыпать солью. Вымыть и порезать помидоры на кружочки. Положить на филе. Порезать грибы, положить на помидоры, посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5744,'Крупно натереть сыр, положить его в сметану, посыпать солью, перемешать. Полученную смесь положить на запеканку из куриного филе. Готовить минут сорок, соблюдая температуру 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5745,'Отварить яйцо, разделить белки и желтки. Измельчить белки, размять желтки. Мелко натереть сыр. Измельчить чесночок. Соединить все, перемешать с майонезом. Раскрутить крабовые палочки, тоненьким слоем положить начинку, закрутить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5745,'Отправить минут на пятнадцать в морозилку. Порезать палочки наискосок. Выложить в виде хризантемы. В центр хризантемы из крабовых палочек положить огурец и украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5746,'Приготовить тесто: взбить мягкое масло (предварительно вынутое из холодильника) и сахар до однородности. Вбивать по очереди яйца, добавить соль и ванильный экстракт. Насыпать просеянную муку с разрыхлителем. Размешать. Налить молоко, снова размешать. Разложить тесто по формочкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5746,'Готовить минут тридцать, соблюдая температуру 175 градусов. Остывшие капкейки остудить, сделать кремовую шапочку. Желательно использовать кондитерский шприц с разными насадками. Приготовить крем (масляной): миксером взбить мягкое масло, медленно насыпая 1/2 часть сахарной пудры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5746,'Добавить ваниль, налить молоко. Перемешать, насыпать остальную сахарную пудру. Приготовить крем (сливочный): взбить сыр с маслом до однородности. Добавить сахарную пудру и ванильный экстракт. Чтобы получить цветной крем для классических капкейков, добавить пищевые красители.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Растопить 8 ст.л. масла (несоленого), отделить 3 желтка от яиц, а 8 яиц по отдельности разбить в разные стаканы, кексы разрезать на две части вдоль и слегка подрумянить в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Поджарить бекон (сильно не зажаривать) с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Взбить на средней скорости блендером желтки, лимонный сок, 4 ч.л. теплой воды, соус Табаско и соль (0,5 ч. л.) постепенно добавляя растопленное масло, когда соус примет кремообразное состояние переложить его в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Вылить в высокую большую кастрюлю 4 литра воды и нагреть до кипения, добавить лавровый лист, весь уксус и соль (2 ч.л.), дать еще раз закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Размешать быстро и энергично воду до образования воронки, аккуратно по одному выкладывать яйца и варить по 3 минуты до затвердения белка, достать шумовкой из кастрюли и положить на полотенце из бумаги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5747,'Блюдо яйца «бенедиктинские» подается так: на половинку кекса поочередно выкладываются бекон, яйцо, соус, сверху яйца посыпать паприкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5748,'Отварить филе курицы, отдельно яйца, остудить. Почистить яйца, отделить друг от друга и мелко потереть желтки и белки. Мелко порезать филе или разделить на волокна. Распарить чернослив, порезать на маленькие кусочки, измельчить орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5748,'Крупно потереть сыр. Положить слоями в подходящую посуду: мясо, желтки, чернослив, сыр, орехи, белки. Все слой промазывать майонезом, солить по вкусу. Дать салату с куриным филе и черносливом пропитаться в холодильнике, украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5749,'Приготовить тесто: смешать 1/2 теплого молока и мед, дрожжи и муку. Размешать, накрыть и отправить в тепло минут на тридцать. Добавить обычный и ванильный сахар, яйцо, подтаявшее масло, остальное молоко, соль, муку. Смешать вилкой, месить руками в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5749,'Если начнет липнуть к рукам, отставить, муку досыпать не нужно. Отправить в теплое место минут на тридцать. После этого поделить на восемь частей, сформировать шарики, накрыть полотенцем, отставить в сторону. Если сильно липнет, присыпать мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5749,'Приготовить начинку: порезать персики на тоненькие дольки. Соединить сахар, яйцо, творог, крахмал. Взбить в блендере, чтобы получилась однородная творожная масса. На поверхности, присыпанной мукой, раскатать шарик из теста, чтобы оно приобрело прямоугольную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5749,'В центр положить творог. Если начинки будет больше, то булочка будет более сочной. На начинку положить персики. Накрыть тестом. Краешки прижать чуть-чуть вилкой. Оставшееся тесто тоненько порезать ножом, нарезанные полосочки загнуть на булочку или обычно, или крест-накрест',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5749,'Намазать булочки желтком, крепким чаем или молоком. Готовить минут двадцать, соблюдая температуру 180 градусов. Посыпать булочки с творогом и персиками сахарной пудрой или простым сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5750,'Просеять муку, насыпать на стол, сделать ямку. Налить воду, растительное масло, посыпать солью, осторожно перемешать. Вымешивать минуты четыре, обернуть в полиэтилен, отставить минут на тридцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5750,'Поделить тесто на десять кусочков, обвалять в муке. Раскатать лепешки толщиной по два миллиметра. Разогреть сковороду, выложить тесто. Готовить тонкий лаваш по тридцать секунд с каждой стороны. Выложить друг на друга, накрыть мокрым полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Другие яблоки порезать на кубики.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5751,'Соединить все продукты, кроме сосисок, замешать тесто. Поделить тесто на шесть частей, накрыть влажной тканью, отставить минут на десять. Раскатать один кусок в тоненький овальный пласт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5751,'На середину положить венскую сосиску. Сделать с нескольких сторон пять горизонтальных надрезов. По очереди наложить полосочки теста друг на друга. Фиксировать низ теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5751,'Оставить тесто на тридцать минут в теплом месте. Когда тесто поднимется раза в полтора, положить сверху кетчуп или майонез, петрушку. Готовить венские сосиски в дрожжевом тесте минут пятнадцать, соблюдая температуру 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5752,'Порезать на тонкие куски куриную грудку, отбить. Порезать на тонкие ломтики свежие шампиньоны, обжарить на растительном и сливочном масле, посыпать перцем, солью, положить молотый мускатный орех. На каждый кусочек мяса выложить чуть-чуть грибов и кусочек голландского сыра. Свернуть рулетик и положить в формочку швом вниз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5752,'Разрезать картофель на несколько частей, надрезав не до конца ломтиками. Положить картофель между рулетиками. Посыпать перцем, солью, налить пятнадцати процентные сливки. Готовить куриные рулетики в сливках под фольгой, пока не приготовится картофель, время от времени поливать соусом. Любители лука могут добавить его к шампиньонам во время жарки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5753,'Взбить белки и желтки в пену. Медленно насыпать просеянную муку, размешать, посыпать солью. Аккуратно соединить белки с желтками. Размешать. Разогреть духовку до 150 градусов. Намазать противень маслом, посыпать мукой. Кондитерский шприц наполнить тестом (отверстие должно быть приблизительно четырнадцать миллиметров).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5753,'Выдавить на противень палочки по десять сантиметров в длину. Вместо шприца можно взять новый полиэтиленовый пакет. Необходимо положить в него тесто, отрезать уголок. Соединить сахарную пудру и сахар. 1/2 частью смеси посыпать. Подождать, пока растворится сахар – на это уйдет минут десять. Насыпать на печенье «Савоярди» остальной сахар. Через пару минут отправить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5754,'Разогреть духовку до 190 градусов. Несколько формочек по восемнадцать сантиметров намазать маслом, застелить специальной бумагой. Взбить в большой посуде сахар и сливочное масло до кремовой смеси. Взбить яйца, переложить в масляную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5754,'Чтобы не произошло сворачивания, взбивать, после каждого добавления. Насыпать муку, осторожно размешать ложкой. Поделить тесто на две части. Готовить минут двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5754,'Чтобы коржи не осели в середине, не открывать духовку до конца готовки. Проверять готовность зубочисткой, предварительно убедившись через стекло, что коржи приобрели золотистый цвет. Если зубочистка остается чистой, то формочки можно вынимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5754,'Оставить на пару минут прежде, чем вынуть из форм. Остудить коржи, намазать вареньем и обыкновенным масляным кремом. По желанию бисквит «Королевы Виктории» с джемом посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5755,'Взять казанок, положить ингредиенты слоями. Каждый слой посыпать перцем, солью. Налить сверху тертые помидоры. Закрыть как можно плотней крышкой. Готовить ароматное рагу полтора часа на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5756,'Положить йогурт в марлю, сложенную вдвое, посыпать солью, размешать. Загнуть краешки, привязать к ложке. Положить в баночку отвисать, чтобы стекла жидкость. На это уйдет от двенадцати часов до пяти суток. Время зависит от того, какая консистенция сыра нужна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5756,'Спустя необходимое время, сыр готов к употреблению. Можно замариновать сыр из греческого йогурта в оливковом масле с приправами и острыми специями. Хранится в холодильнике приблизительно пять суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5757,'Натереть маргарин, добавить муку, сметану (9 ст.л.), соду, гашенную уксусом, сметану и замесить тесто, разделить на 2 части и убрать его в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5757,'Нашинковать лук полукольцами, обжарить на маргарине до прозрачности, остудить, добавить сметану (3 ст.л.), крупно натертый сыр, вбить яйца, начинку поперчить и подсолить, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5790,'Смазать чашу для мультиварки маслом, вылить тесто. В середину вылить начинку. Готовить ватрушку в режиме «Кекс» минут пятьдесят. Минут пять подержать нежную творожную ватрушку под крышкой и потом вынимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5757,'Половину теста раскатать в прямоугольный пласт, выложить его в форму или противень, а на него равномерным слоем начинку. Накрыть сверху вторым пластом и тщательно защипать края, сделать на пироге несколько проколов вилкой и отправить в духовку, выпекать при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5757,'Пирог луковый с сыром по-американски будет готов через 30 минут, подавать его к столу надо холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5758,'Замесить тесто, накрыть полиэтиленом или полотенцем, отправить в тепло на шестьдесят минут. Когда тесто подойдет, вынуть из емкости, положить на стол, посыпанный мукой. Разделить тесто пополам, растянуть руками, придать руками форму прямоугольника. Посыпать тесто тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5758,'Сложить тесто за краешки сыром внутрь, чтобы было три слоя. Разрезать слоеное тесто на полоски по 1 сантиметру в ширину. Из двух кусочков получится приблизительно 32 полосочки. Разложить порезанные полоски на расстоянии 1 сантиметр друг от друга. Через каждый кусочек теста положить по ломтику бекона, растягивать тесто до длины бекона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5758,'Взять полоски теста и бекона за кончики, скрутить. Положить скрученные полосочки на противень, застеленный бумагой. Накрыть полотенцем, отправить на шестьдесят минут в тепло. Поставить дрожжевые палочки с сыром и беконом в духовку, сбрызнуть водой из пульверизатора, готовить минут пятнадцать, соблюдая температуру 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5759,'Соединить все ингредиенты для маринада, сложить в него курицу, отправить на пару часов в холодильник. Соединить ингредиенты для панировки. Обвалять в панировке мясо, выложить его на решетке. Обжарить мясо с двух сторон, выложить на противень, готовить хрустящее филе в панировке минут двенадцать, соблюдая температуру 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5760,'Порезать мясо, обжарить, положить в кастрюльку, налить воду, довести до кипения, убрать пенку. Уменьшить огонь, закрыть крышкой, посолить, готовить часа полтора. Порезать баклажаны на кольца, если большие, то на полукольца. Залить водой, посолить, оставить минимум на шестьдесят минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5760,'Слить воду, обжарить баклажаны выложить на тарелку. Порезать лук-порей и репчатый. Обжарить, положить баклажаны, посыпать приправами, солью, налить томатный сок, соевый соус. Достать мясо из бульона, положить к баклажанам, налить чуть-чуть бульона, осторожно размешать. Тушить телятину с баклажанами под крышкой минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5761,'Духовку разогреть до 190 градусов, формочку намазать маслом. Порезать картофель на кружочки по восемь миллиметров. Поместить порезанный картофель в большую емкость, наполнить водой. Сливочное масло растопить на сковороде, минут пять потушить лук, чтобы он стал мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5761,'Положить измельченный чесночок, тушить еще секунд шестьдесят. Налить смесь цельного молока и жирных сливок. Довести до кипения и отставить. Слить воду, обсушить картофель бумажным полотенцем. Переложить 1/2 картофеля в формочку. Соединить перец с солью, посыпать картофель. Высыпать тертый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5761,'Повторить процедуру с оставшимся картофелем, сыром, перцем и солью. Нагреть молочно-сливочную смесь до кипения, вылить на картофель. Чуть-чуть прижать картофель, чтобы он утонул в сливках. Закрыть блюдо фольгой, готовить картофель с сыром и сливками в духовке посередине шестьдесят минут. Снять фольгу, готовить минут тридцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5762,'Апельсин разрезать на две части. Осторожно срезать кожицу, порезать мякоть на кубики. Порезать курицу, измельчить орехи. Соединить с сушеной вишней или клюквой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5762,'Соединить ингредиенты, заправить салат майонезом, любимым соусом или натуральным йогуртом. Поместить куриный салат с вишней в кожицу от апельсина, подавать с соусом и салатными листьями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5763,'Разрезать филе вдоль пополам. Посыпать перцем и солью. Завернуть в бекон. Обжарить на сухой сковороде минут шесть. Переложить на тарелку, накрыть фольгой. Мелко потереть морковь и картофель. Добавить в массу яйцо, посыпать перцем, солью. Измельчить брокколи, посыпать солью, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5776,'Соединить все сухие ингредиенты. Налить теплое молоко, вбить яйца, положить масло, цедру, ванилин. Замесить мягкое тесто. Если нужно – насыпать еще муки. Положить тесто в посуду, отправить в тепло. Приблизительно через шестьдесят минут тесто увеличится в несколько раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5763,'Добавить чуть-чуть мелко натертого сыра. Налить растительное масло на сковороде. Положить ½ картофельно-морковной смеси, разровнять. Положить сверху мясо в беконе. Выложить брокколи, завернуть картофельные края. Обжарить. Отдельно обжарить грибы с луком. Сервировать на тарелочке грибы, потом бульбургеры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Разрезать куриные грудки как для шницеля и слегка отбить, для придания сочности и мягкости мясу его надо замариновать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Для маринада раздавить пару зубчиков чеснока, смешать с майонезом, молотым черным перцем и солью, полученной смесью обмазать грудки и отправить в холодильник на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Смешать оливковое масло с раздавленным зубчиком чеснока и перцем, дать настояться полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Маринованную курицу запанировать в сухарях и зарумянить в растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Приготовить из белого хлеба сухари: нарезать его кубиками (корочку предварительно срезать) по одному сантиметру, сбрызнуть чесночным маслом, подрумянить в горячей духовке, кубики нельзя пересушивать, они должны хрустеть, но оставаться мягкими внутри.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Для соуса взбить в миксере желтки яиц, сок лимона, горчицу и зубчик измельченного чеснока, постепенно влить, не прекращая взбивать, оливковое масло и понемногу всыпать натертый пармезан (50 г).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5764,'Натереть стенки салатницы чесноком, порезать огурцы, сыр, листья салата нарвать руками, добавить курицу, нарезанную брусочками, сухари, добавить половину соуса, на салат сверху выложить порезанные маслины и залить салат «Цезарь» по-американски с маслинами и огурцами оставшимся соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5765,'Осторожно порезать рыбу на тоненькие пластинки. Выложить их на пленку внахлест в два ряда. На пластинки положить слой сыра, один ряд листиков зелени. Свернуть рыбу с сыром в рулетик, отправить на несколько часов в холод. Порезать рулетик острым ножом на кусочки, положить закуску «Нежность Дракона» на салатные листья. Украсить перышками лука, зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5766,'Соединить в глубокой емкости кефир, сметану, соль, сахар, яйцо, растительное масло. Медленно насыпать муку и соду, быстро замесить тесто. Если нужно подсыпать муку, но не забивать тесто. Посыпать стол мукой, сформировать пирожки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5766,'Во время жирки пирожки хорошо поднимаются и могут лопнуть, поэтому не нужно класть слишком много начинки. Разогреть масло. Пропекать пирожки из теста на сметане не только с двух сторон, но и по бокам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5767,'Подготовить все необходимые ингредиенты. Приготовить куриный бульон, отварив кости курицы. Если имеется готовый бульон, то на приготовление уйдет гораздо меньше времени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5767,'Почистить и вымыть овощи. Измельчить лук, натереть морковь. Обжарить лук на растительном масле, положить морковь жарить до мягкости. Порезать сосиски на кубики, положить к овощам, обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5767,'Измельчить зелень, вымыть картофель, почистить, порезать на кубики. Картофелем заниматься в последнюю очередь. Положить все ингредиенты в мультиварку, налить бульон, посыпать солью. Поставить на режим тушение на шестьдесят минут, закрыть крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5767,'Порезать сыр на маленькие кубики. За пару минут до конца готовки открыть крышку и положить зелень и сыр. Перед подачей суп из плавленых сырков в мультиварке еще посыпать зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5768,'На приготовление блюда уходит двадцать минут. Приготовить фарш из мяса, чеснока и лука. Сделать из него тефтельки, сразу обжарить. Несколько минут отваривать брокколи. Порезать помидоры на кубики. Минут пять отваривать картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5768,'Приготовить соус бешамель: в сотейнике растопить сливочное масло, насыпать муку, обжарить, постепенно влить сливки или молоко, непрерывно взбивая, налить бульон, довести до кипения, не прекращая мешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5768,'Посыпать солью, тмином, мускатным орехом. Положить в формочку тефтели и овощи. Вылить соус, готовить двадцать минут, соблюдая температуру 200 градусов. Посыпать запеканку с тефтелями и брокколи тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5782,'Смазать формочку сливочным маслом, на дно положить порезанные яблоки без кожуры, равномерно распределить. Залить яблоки тестом, насыпать корицу, отправить шарлотку на сметане на 35 минут в духовку, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5769,'Залить изюм горячей водой, оставить минут на десять. Слить воду, посушить изюм на салфетке. Налить воду в маленькую кастрюльку, насыпать мак, кипятить шестьдесят секунд, снять с огня, дать настояться минут десять. Растворить дрожжи в теплом молоке, насыпать сахар, муку, помешать, отставить смесь минут на десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5769,'Процедить мак, дать стечь воде, насыпать в изюм муку, размешать. Соединить соль, растительное масло, сахар обыкновенный и ванильный, яйцо. Насыпать в опару муку, размешать, вылить смесь с маслом, положить изюм, мак, размешать. Насыпать муку, размешать, положить сливочное масло, вымесить, чтобы масло равномерно разошлось. Насыпать оставшуюся муку, замесить тесто, если нужно, насыпать еще чуть-чуть муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5769,'Накрыть тесто, отправить на шестьдесят минут в тепло. В формочку постелить промасленную бумагу. Тесто чуть-чуть обмять, разделить на десять частей, сформировать шарики, поместить в формочку, накрыть салфеткой, отставить минут на двадцать. Включить духовку на двести градусов. Намазать булочки с маком и изюмом взбитым яйцом, посыпать сахаром. Готовить до золотистого оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5770,'С киви снять кожуру, разделить пополам, поместить в блендер, добавить кокосовую стружку, мед, перемолоть до однородной смеси. Сделать шарики по размеру с грецкий орешек, панировать каждый в кокосовой стружке. Отправить на пару часов киви «Рафаэлло» в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5771,'Перемолоть капусту в блендере или через мясорубку. Главное, чтобы она была, как потертая на мелкой терке. Мясо пропустить через мясорубку. Использовать свинину или говядину. Можно взять оба вида. Важно, что фарш не был очень жирным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5771,'Перемолоть чесночок и лук. Соединить все продукты, по вкусу добавить: разные виды перца, соль. Вбить яйца и перемешать. Сформировать котлеты, обвалять в сухариках. Готовить сочные капустно-мясные котлетки на сковороде, хорошо смазанной маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5772,'Порезать грибы на кубики, обжарить, добавив мелко порезанный лук, в конце посыпать перцем, солью. Насыпать тертый сыр, налить сливки, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5772,'Отбить филе курицы, посыпать перцем, солью, в середину положить фарш из грибов, свернуть бомбочкой, обернуть в фольгу, смазанную маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5772,'Готовить минут тридцать, соблюдая температуру 200 градусов. Снять с куриных бомбочек с сыром и грибами фольгу, запекать еще минут десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5773,'Измельчить чесночок и лук, обжаривать минуты три. Положить фарш, жарить минут двадцать. Снять кожицу с томатов, измельчить. Посыпать перцем и солью. Можно положить сушеный орегано, тушить минут пять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5773,'Растопить масло, насыпать муку, обжаривать несколько минут. Налить молоко. Помешивать до загустения на тихом огне. По консистенции должна получиться смесь, как жидковатая сметана. Выключить огонь и мешать, пока соус не остынет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5773,'Потереть сыр. Положить три листа для ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5774,'Взбить масло и сахар. Вбить яйцо, взбить. Насыпать муку с содой и положить шоколад. Выложить тесто ложкой на специальную бумагу. Готовить минут двадцать, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5774,'В период выпекания американское печенье с шоколадом приплюснется, поэтому форму ему можно не придавать. Если насыпать меньше муки, то они будут тоньше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5775,'Разогреть в сковороде смесь из 2 ст.л. сливочного масла и 1 ст.л. оливкового, обжарить до мягкости мелко нашинкованный лук около 5 минут, добавить нарезанные тонкими пластинками грибы и жарить еще 5 минут, посолить, поперчить, перемешать и переложить все в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5775,'Взбить в глубокой миске яйца со сливками, добавить порезанные листики эстрагона, соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5775,'Вытереть сковороду бумажным полотенцем, нагреть на сильном огне, выложить остаток сливочного масла, вылить яичную смесь, прогреть, помешивая пока не схватится треть омлета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5775,'Выложить на его середину луково-грибную смесь полосой, свернуть омлет пополам или подогнуть края к середине и готовить еще около минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5775,'Готовый омлет «Американский» с грибами и эстрагоном выложить на подогретую тарелку и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Подготовить тушку трески, положить в холодную воду, дать закипеть, убрать пену и варить еще 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5776,'Размять тесто и раскатать на столе, присыпанном мукой. Должен получиться прямоугольник 35 на 44 сантиметра, толщиной в 1 сантиметр, разрезать пласт на квадратики 7 на 7 сантиметров. В центр квадратиков положить чуть-чуть джема. Закрыть квадрат, склеить краешки. Сделать данную процедуру со всем джемом и тестом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5776,'Положить булочки на противень, смазать по бокам маслом, чтобы не слиплись. Разогреть духовку. Намазать булочки яйцом, отставить минут на двадцать, чтобы они стали еще больше. Готовить минут тридцать, до золотистой корочки. Посыпать дрожжевые булочки с ягодным джемом сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5777,'Взбить яйца, сахар и соль. Готовить тесто желательно в блендере: получается однородное, качественное тесто, причем очень быстро. Влить молоко, опять взбить. Насыпать муку, взбить, чтобы исчезли комочки. Непрерывно взбивая, вылить остальное молоко. Тесто должно быть жидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5777,'Выпекать блинчики. Нужно сделать тесто разных цветов. Для этого 1/3 часть теста вылить в отдельную посуду, чтобы делать узоры на блинах. В остальное тесто насыпать какао, размешать до однородности, чтобы комочки исчезли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5777,'Разогреть сковороду, налить масло, распределить по сковороде, разогреть. Налить совсем чуть-чуть теста, распределить его по сковороде. Выпекать. Взять немного теста чайной ложечкой, нарисовать любые узоры на блине. Перевернуть шоколадный блинчик, выпекать с другой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5778,'Взбить яйца и сахар, насыпать соль, ванильный сахар, налить молоко. Просеять муку, смешать с дрожжами, разрыхлителем, перемешать, высыпать к яйцам, положить сливочное масло, перемешать. Отправить в тепло часа на полтора. Положить в формочку, оставить минут на шестьдесят. Готовить минут 25, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5778,'Приготовить заливку: варить воду с сахаром, пока сахар не растворится. Налить ром или коньяк. Достать бабу, проткнуть шпажкой, полить медленно сиропом. Смешать сахарную пудру с водой и украсить ромовую бабу этой глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5779,'Порезать клубнику, оставив одну ягоду для украшения. Смесь для пудинга развести в молоке, подождать несколько минут, отправить в холодильник на две минуты. Взбить миксером сыр маскарпоне до кремообразной консистенции. Налить кофе, взбитые сливки и пудинг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5779,'Обмакнуть каждое печенье в кофе и сразу выложить 1/3 часть в салатник с плоским дном. Сверху положить 1/3 часть клубники, 1/3 тертого шоколада, столько же смеси маскарпоне. Так выложить еще два слоя. В конце класть маскарпоне и шоколад. Украсить клубничный тирамису-трайфл оставленной клубникой. Отправить часа на четыре в холод, желательно на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5780,'Приготовить тесто: соединить теплую воду, дрожжи и сахар. Положить в смесь соль и оливковое масло. Переложить тесто в кухонный комбайн, месить тесто минут двадцать. Положить в емкость с растительным маслом, накрыть, отставить часа на полтора. Когда подойдет тесто, ½ часть раскатать в пласт 25 на 40 сантиметров. Положить сверху томатный соус, со всех краев оставлять сантиметров по шесть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5780,'Сверху выложить тертый сыр, положить порезанную ветчину и салями. Чуть-чуть взбить яйцо, смазать им краешки. Узкие края завернуть, завернуть все в рулетик, положить на противень. Намазать рулет яйцом, посыпать сыром, сделать поперек разрезы через каждые четыре сантиметра. Посыпать сухой травкой: орегано или петрушкой. Готовить пиццу «Стромболи» минут двенадцать, соблюдая температуру 240 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5781,'Нагреть духовку. Взбить сливочное масло, ваниль, сахар до кремообразной массы. Насыпать соль, корицу. Размешать. Насыпать медленно соду и муку. Размешать. Положить йогурт, размешать до однородности. Почистить и порезать яблоки на кубики. Положить в тесто, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5781,'Перелить тесто в формочку, смазанную маслом. Посыпать сахаром и корицей. Отправить в духовку в самый низ, готовить минут пятьдесят, проверять зубочисткой. Подавать нежный яблочный пирог с йогуртом, сметаной или сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5782,'Взбить яйца миксером до пышной пены, медленно добавить сахар, муку, сметану, соду, гашенную уксусом. Тесто должно быть, как жидкая сметанка. Положить корицу, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Нарезать мелко сельдерей и добавить в бульон, варить 10 минут, процедить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5783,'Порезать баклажаны на две части, порезать на толстые ломтики. Отваривать минут пять в подсоленной воде, откинуть на сито, чуть-чуть отжать. Почистить и потереть морковь на терке для корейской моркови, положить измельченный перец, прессованный чесночок, укроп, масло, уксус, специи. Размешать. Положить баклажаны в не окисляющуюся емкость, полить маринадом, отправить маринованные баклажаны минут на пятнадцать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5784,'Растопить пару минут в микроволновке шоколад и сливочное масло. Взбить яйца и сахар, насыпать разрыхлитель, муку, добавить масло, шоколад, коньяк. Замесить тесто. Готовить в микроволновке минут семь в термостойкой емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5784,'Приготовить крем: взбить яйцо и сахарную пудру, смешать с мягким сливочным маслом, положить или растопленный шоколад, или ваниль по вкусу. Остудить бисквит и разрезать поперек на четыре части, каждую смазать кремом, посыпать шоколадный торт крошкой шоколада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5785,'Взбить в блендере все ингредиенты, отставить минут на пять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5786,'Размягчить масло, перемешать с сахаром. Положить творог. Перемешать. Если смесь очень густая, налить сливки или молоко. Вбить яйца. Насыпать муку и разрыхлитель. Добавить изюм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5786,'Сделать из теста 22 кексика. Заполнить формочки не до конца, отправить минут на тридцать в духовку, соблюдать температуру 200 градусов. Готовность кексиков из творога с изюмом проверять зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5787,'Порезать луковицу на полукольца. Налить в кастрюльку чуть-чуть растительного масла, положить лук, тмин, размешать, обжарить до золотистого оттенка. Можно положить кусок сала, грудинки или бекона, порезанный мелко. На средние кусочки порезать мясо. Убрать середину из перцев, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5787,'Положить в кастрюлю, обжаривать минут пять. Положить мясо и измельченный чесночок. Посыпать перцем и солью. Налить в мясо пиво, чтобы оно было полностью покрыто. Довести до кипения, сделать огонь меньше, тушить минут девяносто. За пять минут до конца готовки добавить в гуляш из свинины на пиве измельченную зелень по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5788,'Соединить муку, разрыхлитель и ванильный сахар, положить подтаявшее масло, смешать все в крошку. Сформировать ямку в смеси, вбить яйца и положить сметанку. Замесить эластичное тесто. Завернуть в полиэтилен, отправить на тридцать минут в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5788,'Разогреть духовку. Соединить орехи, корицу и сахар. Положить восемь пластов теста на сковороду, каждый смазав сливочным маслом. Все пласты посыпать обильно ореховой смесью, накрыть следующим пластом вверх маслом. Использовать всю смесь, оставив совсем немного. Остальное тесто положить сверху, намазать сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5788,'Разрезать пахлаву с помощью острого ножа на маленькие кусочки в форме ромба. Поставить кастрюльку с водой в духовку на самую нижнюю полку. Пахлаву поставить над водой, выпекать 120 минут. Важно, чтобы в кастрюльке всегда была вода.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5788,'По желанию можно приготовить сироп: в кастрюльку с водой насыпать сахар, положить лимонную цедру и сок. Кипятить минут пятнадцать, на маленьком огне. Положить мед, варить еще минут пять. Снять лимонную цедру, остудить. Готовую пахлаву с грецким орехом остудить, залить сиропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5789,'Приготовить картофельное тесто для сосиски: почистить картофель, натереть. Вбить яйцо, посыпать перцем, солью, размешать. Насыпать муку, размешать. Подготовить сосиски: влажными руками взять чуть-чуть картофельного теста, распределить так, что сосиска была закрыта со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5789,'Обвалять массу в муке. Повторить процедуру со всем тестом. Разогреть масло, положить крупно порезанный чесночок. Следить, чтобы он не сгорел. Вынуть чеснок из сковороды. Обжарить сосиски в картофеле до золотистой корки. Выложить на салфетки, чтобы стекло масло. Порезать сосиски в тесте из картофеля на кусочки, подавать с любым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5790,'Приготовить начинку: соединить творог, сахар, яйца, манку или крахмал. Взбить миксером. Приготовить тесто: взбить в пену яйца и сахар, положить сметанку, топленное масло, размешать. Положить какао и муку. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Разделать рыбу на филе и положить обратно в суп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Нашинковать мелко лук, нарезать перец соломкой. Припустить овощи на оливковом масле до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Нарезать картофель кубиками, опустить в кипящий бульон, варить 15 минут. Добавить овощи, залить горячее молоко, подсолить, поперчить, проварить все 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5791,'Перед подачей суп молочный из трески с перцем и сельдереем посыпать измельченной зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5792,'Приготовить тесто: соединить яйца, майонез, молоко, соду, муку, соль. Размешать. Вылить тесто в формочку. Положить на него куски рыбного филе так, чтобы они погрязли в тесте. Выпекать рыбный пирог до готовности. В конце посыпать измельченной зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5793,'Поджарить на сухой сковороде грецкие орехи, измельчить руками или порубить крупно. Отварить филе курицы, охладить порезать на кубики. Мелко натереть сыр, на средние кусочки порезать ананасы. Все соединить и заправить салат «Новогодний» майонезом, или уложить слоями, сделав один слой майонеза, украсить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5794,'Обжарить грибы и лук, выложить на дуршлаг, чтобы стек жир. Грудинку обжарить с карри, яйца порезать на кубики, положить майонез или сметанку, посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5794,'Положить на блюдо, придать форму гриба, ножку сделать из мелко натертого белка, посыпать укропом, шляпку сделать из вареной моркови, мелко натертой, внизу шляпку посыпать сыром. Салат с куриной грудкой и грибами можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5795,'В большую емкость сложить разломанное печенье, изюм, орехи, положить цедру и сок лимона, растительное масло. Перемешать. По вкусу насыпать сахар, если его не хватает. Разделить тесто на восемь частей, очень тоненько раскатать на треугольники в длину, соответствующие формочке. Положить вдоль большой стороны начинку и завернуть рулетик. Подготовить восемь рулетиков и положить их в формочку, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5795,'Сверху рулетики смочить чуть-чуть водой, посыпать сахарком. Надрезать все рулеты наискосок, в каждый налить немного масла, чтобы разрезы красиво подрумянились. Готовить штрудель с печеньем, орехами и изюмом при температуре 180 градусов, пока не станет румяным. Порезать рулетики на порционные кусочки, по надрезам, которые были намечены. Охладить перед подачей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5796,'Подогреть оливковое масло. Выложить ломтики хлеба, обжарить до хрустящей корки шестьдесят секунд. Разобрать вилкой рыбу на мелкие кусочки. Измельчить укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5796,'Положить рыбку в емкость, добавить укроп, сливочный сыр. Размешать. Положить рыбную массу на хлеб, украсить бутерброды с сыром и лососем кусочком огурца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5797,'В большой емкости взбивать яйца и сахар минут десять, чтобы смесь стала пышной. Не переставая взбивать, медленно влить теплое сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5797,'Просеять сверху муку и крахмал, перемешать с помощью венчика, подливая теплую воду. Когда тесто будет однородным, отставить на тридцать минут. Нагреть вафельницу, намазать сливочным маслом, выпекать. Хрустящие вафли скрутить трубочкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5798,'В микроволновой печи растопить шоколад. Отставить, чтобы остыло. В большой емкости взбивать несколько минут сливочное масло с сахаром. Когда шоколад чуть-чуть остынет, положить его в масляную смесь. Налить ванильный экстракт. Взбить до однородности. Вбить яйца (по одному), после каждого взбивать минут по пять. Вымесить хорошо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5798,'Формочку смазать маслом, раскатать из теста пласт, переложить в формочку, сформировать бортики. Отправить в духовку минут на пятнадцать, соблюдая температуру 180 градусов. Достать из духовки охладить. Налить начинку, отправить в холодильник часа на три, а желательно на всю ночь. Подавать с шоколадными завитками и взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5798,'Для приготовления завитков необходимо растопить шоколад, вылить на блюдо, выровнять по поверхности, оставить тоненький слой шоколада. Подождать, пока остынет и станет твердым. Провести с силой железной лопаткой, отдирая шоколад от поверхности. Украсить французский пирог завитками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5799,'Сварить куриные грудки и порезать их на кубики. Оливки и сельдерей порезать на колечки. Измельчить зеленый лук. Приготовить соус: соединить оливковый рассол, майонез, сок лимона, горчицу, перец и соль. Соединить все ингредиенты, полить соусом, салат с курицей, оливками и сельдереем размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5813,'Застелить противень пергаментом, сделать печенье, разложить на листе, отправить в духовку и выпекать 15-20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5800,'Взбить масло и сахар, вбить яйцо насыпать соль, муку, пекарский порошок. Замесит тесто, сделать шарики, отправить минут на тридцать в холодильник. Взять формочку 25 на 15 сантиметров, постелить специальную бумагу, положить тесто. Готовить минут тринадцать, соблюдая температуру 180 градусов. Смешать творог, обыкновенный и ванильный сахар, вбить яйцо, насыпать крахмал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5800,'Крупно натереть яблоки, насыпать корицу, сахар, панировочные сухарики, размешать. Соединить все продукты для масляной крошки, растереть руками до состояния крупной крошки. Выложить творожную смесь на тесто, на нее положить яблоки, посыпать крошкой. Готовить творожный чизкейк-шарлотку минут сорок, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5801,'Просеять муку. В теплое молоко насыпать дрожжи и сахар. Размешать. Вбить яйцо, положить мягкое масло. Медленно насыпать муку, замесить тесто. Отставить, чтобы оно стало в несколько раз больше. Соединить яйца, сметанку, сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5801,'Чуть-чуть взбить венчиком, чтобы растворился сахар. Раскатать тесто, сформировать в форме сковороды. Выложить тесто в формочку, положить начинку. Готовить сметанник на дрожжевом тесте минут сорок, соблюдая температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'Положить куски курицы в миску, посыпать солью (1ст.л.), залить молоком, выдержать ночь в холодильнике, это сделает мясо сочным и нежным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'Переложить в кастрюлю содержимое миски, дать закипеть на среднем огне, убавить нагрев и варить до готовности, молоко свернется, но это не страшно: вкус блюда не пострадает.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'Мясо достать и дать ему остыть, в полиэтиленовый пакет засыпать муку, соль (1 ч.л.), кайенский перец, встряхивая пакет все хорошо смешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'Запанировать кусочки курицы в получившейся смеси, обмакнуть во взбитое яйцо и опять в муку, отставить на 15 минут пропитаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'В глубокой чугунной сковороде как следует разогреть масло и зарумянить каждый кусочек с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5802,'Куриные ножки и бедра жареные по-южному выкладывается на листья салата и сразу подается к столу, в качестве гарнира можно предложить картофель-фри, овощной салат или рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5803,'Сделать тесто: смешать растопленное масло или маргарин с другими ингредиентами, налить тесто в формочку. Готовить минут пятьдесят, соблюдая температуру 175 градусов. Остудить и поделить пополам. Сделать крем: используя молоко и манную крупу, сварить кашу. Когда молоко закипит, медленно насыпать манку, непрерывно мешая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5803,'Варить минут пять. Отдельно взбить подтаявшее масло и сахар. Соединить манную кашу, стружку, масляную смесь. Перемешать. Намазать холодные коржи. Сверху торт «Bounty» намазать шоколадной глазурью (растопить шоколад). Отправить тортик в холодильник, чтобы глазурь застыла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5804,'Натереть куриные грудки специями, обжарить на среднем огне до готовности, переворачивая куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5804,'Нагреть в чугунной сковороде столовую ложку масла, обжарить нарезанный мелко перец и кукурузу, насыпать 0,5 ст.л. пряностей, перемешать и обжарить 5 минут, добавить 3 стакана воды, рис и измельченный бульонный кубик, дать закипеть и тушить до мягкости риса примерно 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5804,'За несколько минут до готовности положить кусочки ананаса и влить жидкость из банки, все перемешать и хорошо прогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5804,'Куриные грудки по-луизиански с ананасом и рисом подавать следующим образом: горкой выложить на блюдо рис, а сверху жареные грудки курицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5805,'Включить разогревать духовку до 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5805,'Взбить в миске яйца, постепенно добавляя остальные ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5805,'Вылить получившуюся смесь в форму смазанную маслом и отправить запекаться в нагретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5805,'Запеканка с кукурузой по-американски будет готова примерно через час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'Нагреть до кипения пол-литра воды, засыпать сахар и дать закипеть еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'Опустить в сироп очищенные от кожуры и семенной коробки яблоки и слегка проварить. Вынуть плоды и положить в глубокий лоток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'В другой посуде разварить кожуру, а затем протереть ее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5813,'Овсяное печенье с изюмом, орехами и коньяком остудить на противне, а затем снять и переложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'Залить заранее намоченный набухший желатин кипятком (400 мл), нагреть до растворения, смешать с сиропом и пюре из кожуры. Если жидкости получилось меньше литра, то добавить кипяток и размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'Залить яблоки полученной смесью и убрать на холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5806,'Перед подачей яблоки со сливками по-американски украсить взбитыми сливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5807,'Крылышки замочить в соленой воде на 1 час, в результате мясо получится более мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5807,'Разрезать в районе суставов каждое на три части, концы крыльев не использовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5807,'Приготовить из раскрошенных кукурузных хлопьев, сухарей, трав, муки, имбиря, сушеного чеснока и перца панировку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5807,'Обвалять крылышки в смеси и обжарить в сильно разогретом масле примерно по 10 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5807,'Переложить хрустящие куриные крылышки в панировке на полотенце из бумаги и дать впитаться излишкам жира.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5808,'Взбить яйца венчиком, добавить нашинкованную зелень, посолить, поперчить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5808,'Разогреть сковороду, налить чуть масла, вылить яичную смесь, дать немного схватиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5808,'Выложить по центру мелко нарезанный сыр, лопаточкой загнуть края омлета к центру в форме конверта, закрыть крышкой и запечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5808,'Разрезать ржаную булочку и омлет пополам, смазать одну половинку булочки томатной пастой, положить кусочки перца, тонко нарезанные кольца помидора, кусочек омлета, сделать еще один такой же сэндвич американский с сыром и яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5809,'Приготовить банановое пюре, смешать его с лимонным соком и ванилином, включить духовку для разогрева на 280 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5809,'Перемешать миксером муку, разрыхлитель, яйцо, пюре из бананов, сливочное масло и мед до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5809,'Разложить подготовленное тесто по формочкам и поставить выпекаться, после выпекания ванильные банановые кексы поместить в холодное место на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5810,'Отварить курицу и мелко нарезать, очистить и порезать яблоко небольшими кубиками, нашинковать лук и сельдерей, натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5810,'Смешать майонез со сметаной, карри, медом, имбирем и лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5810,'Соединить курицу, лук, яблоко, морковь, майонезный соус, добавить перец, клюкву, соль и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5810,'Салат из курицы по-американски с карри и клюквой можно подать с поджаренными хлебцами или сделать из него начинку для сэндвича.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5811,'Помидоры нарезать вдоль кольцами, поставить разогревать в чугунной сковороде масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5811,'Разбить в миску яйцо и взбить венчиком, смешать соль с панировочными сухарями и перцем. Кольца помидора окунуть в яйцо и потом в сухари.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5811,'Подготовленные кусочки помидора зарумянить в масле с двух сторон и переложить на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5811,'В оставшееся после обжарки на сковороде масло добавить по столовой ложки муки на каждую ложку масла, все перемешать, залить теплым молоком, варить, помешивая до густоты сметаны, посолить, поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5811,'Залить обжаренные помидоры на тарелке молочным соусом, зеленые помидоры в панировке под молочной подливой подавать горячими, украсив веточками зелени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5812,'Отделить желтки от белков, взбить из белков пену, добавляя понемногу сахар, добавить желтки, изюм, измельченные орехи и соду, включить на разогрев духовку до 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5812,'Добавить к полученной смеси кукурузную муку и вымесить все до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5812,'Разложить по формочкам тесто и отправить в духовку, безглютеновые кукурузные кексы с орехами и изюмом выпекать 30-35 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5812,'В готовые кексы кондитерским шприцем можно ввести варенье или крем, сверху смазать медом и присыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5813,'Для блюда возьмите мелкие хлопья и изюм тогда готовое печенье будет иметь более аккуратную форму и нежную консистенцию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5813,'Залить на ночь вымытый изюм коньяком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5813,'Смешать весь сахар, добавить маргарин, яйцо, взбить миксером, в полученную смесь залить воду (3 ст.л.), коньяк (1 ст.л.), соль (1 ч.л.), всыпать муку, фундук, изюм, замесить однородное тесто, включить духовку для разогрева на 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5815,'Добавить консервированный горошек, заправить куриный салат по-руэнски с горошком, апельсинами и яблоками майонезом, перемешать и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5816,'Взять рыбу, почистить, выпотрошить, промыть. Отрезать плавники, голову, отложить – они пригодятся на уху. Порезать рыбку на средние кусочки. Почистить много лука и порезать полукольцами. Взять кастрюльку с толстыми стенками, положить слой лука, слой рыбки, опять лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5816,'Приготовить маринад и залить рыбку: соединить растительное масло, сахар, томатный соус, уксус, соль и воду в маленькой кастрюльке. Перемешать и поставить на тихий огонь, томить под крышкой на протяжении трех часов.  Затем добавить душистый перчик, лавровый лист, накрыть крышкой, томить еще минут сорок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5817,'Вымыть говядину в холодной воде. Порезать мясо на кусочки, положить в сковороду, смазанную маслом и подогретую. Чуть-чуть обжарить на большом огне, чтобы мясо было румяным. Помыть морковь, петрушку и лук, порезать крупно и пассировать с томатной пастой. Положить овощи к мясу, налить бульон, посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5817,'Накрыть крышкой, готовить на тихом огне минут шестьдесят. Вымыть чернослив, положить его к мясу, тушить до готовности. Подавать на плоском блюде. На мясо выложить овощи, с которыми оно готовилось. Полить бульоном, посыпать говядину с черносливом и овощами измельченной петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5818,'Отварить грудку курицы в соленой воде до полной готовности. Вымыть шампиньоны, порезать, обжарить на масле (сливочном). Отварить, почистить яйца, крупно потереть. Натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5818,'Выложить салатик слоями в следующем порядке: мясо, грибы, корейскую морковь, яйца, сыр. После грибочков и яиц, салат «Паутинка» смазать майонезом. Из моркови сделать сверху паутинку, из горошка и маслин – паука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5819,'Размять творог, вбить яйца, перемешать. Насыпать соль, сахар, манку. Размешать, отставить минут на двадцать. Вымыть и посушить изюм, положить в творог, размешать. Столовой ложкой брать тесто и обвалять в манной крупе. Лепить сырники. Обжаривать сырники с изюмом и манкой со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5820,'Перебрать и промыть гречку, подсушить на бумажном полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5820,'Нарезать кубиками по 2-3 см мясо, поджарить на разогретом сливочном масле, посолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5820,'Нашинковать лук и добавить к мясу, всыпать гречневую крупу, добавить крупно натертую морковь и нарезанный соломкой сладкий перец, кетчуп, все перемешать, залить бульоном (на 1 см выше содержимого сковороды).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5820,'Тушить кашу до готовности при слабом нагреве 20-25 минут, пока не впитается весь бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5820,'Гречневая каша со свининой по-купечески перед подачей должна настояться 15 минут, разложить кашу по тарелкам, присыпать рубленой зеленью, подать соленые помидоры или квашеную капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5821,'Крылья поделить по суставу, получается на три части. Кончики не выбрасывать, из них можно сварить вкусный, легкий бульон. Плечи и предплечья положить в глубокую емкость, посыпать солью, отставить на пару часов, а желательно на 24 часа. Этого времени хватает, чтобы соль вытянула влагу, мясо становится плотнее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5821,'Обсушить подготовленные кусочки мяса полотенцем. Разогреть в кастрюльке с толстыми стенками оливковое или растительное масло. Чтобы проверить готовность мяса, необходимо бросить в него небольшой кусок сырого, сухого картофеля, он должен за полминуты обжариться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5821,'Запанировать крылья в муке, пожарить в кипящем масле. Сильно не ужаривать. Готовые крылья выложить на салфетку, чтобы стек лишний жир. Приготовить соус: почистить и измельчить чесночок и лук. Растопить в кастрюльке с толстым дном сливочное масло и чуть-чуть растительного.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5821,'После масло разогреется, положить лук, чеснок, чуть-чуть обжарить до мягкого состояния. Положить томатную пасту, лечо, кориандр, посыпать солью и перцем, довести до кипения. Положить в соус жареные куриные крылья, прогреть все вместе, непрерывно мешая, курица должна быть полностью покрыта соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5828,'Сварить до мягкости фасоль (замочить заранее), добавить порезанный соломкой болгарский перец, тонко нашинкованную капусту и нарезанный брусочками картофель, проварить борщ 15-20 минут на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5822,'Отварить курицу, удалить кожу и кости. Измельчить мясо. Картофель и томаты порезать на кубики. Почистить и измельчить лук, положить в емкость, обдать кипятком, чтобы исчезла горечь, воду слить. Сложить мясо курицы и овощи в глубокую емкость. С кукурузы слить сок, зернышки насыпать в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5822,'Посыпать солью, все размешать. Приготовить заправку: соединить сок лимона и майонез. Можно положить горчицу, тогда будет поострей. Размешать. Положить салат с кукурузой, курицей и помидорами на плоскую тарелку горкой, полить заправкой. Украсить салатик яйцом, зеленью и помидорками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5823,'Сделать корж: соединить и размешать муку, яйцо, сахар, сметанку, соду гашенную уксусом (разрыхлитель), положить мак. Так же сделать еще корж, положить изюм, в третий добавить орехи или чернослив. Выпечь и охладить коржи. Приготовить крем: масло взбить со сгущенкой, намазать коржи, украсить торт «Королевский» фруктами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5824,'Замешать тесто в кухонном комбайне. Просеять муку, насыпать сахар, дрожжи, размешать. Вбить яйцо, налить теплое молоко, положить масло, посыпать солью. Месить тесто минут двадцать. Оставить на шестьдесят минут в теплом месте. Тесто должно стать в несколько раз больше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5824,'В это время приготовить крем: растереть крахмал и желтки, добавить молоко, чтобы смесь стала жидковатой. Закипятить молоко, налить медленно в яично-молочную массу, непрерывно мешая с помощью венчика. Сделать смесь густой, на это понадобится несколько минут. Накрыть крем полиэтиленом, чтобы не образовалась пленочка. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5824,'Посыпать стол мукой. Положить тесто, посыпать мукой. Раскатать пласт приблизительно тридцать на сорок сантиметров. Намазать пласт кремом, посыпать крошкой шоколада. Скатать рулетиком, порезать на кусочки. Положить в формочку специальную бумагу, намазать ее сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5824,'Булочки осторожно положить в формочку на расстоянии между друг другом, так как они поднимутся. Отставить булочки минут на сорок, чтобы поднялись. Отправить на 45 минут в духовку, соблюдая температуру 160 градусов. Охладить булочки-бриоши с кремом патисьер на решетке. Перед подачей украсить сахарной глазурью: смесь сахарной пудры и сока лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5825,'Сделать опару: соединить муку, дрожжи, воду. Воды много не нужно добавлять, так как тесто должно быть тугим. Отставить часа на три. Приготовить основу замеса: соединить муку, воду, масло, сахар и соль. Чуть-чуть перемешать. Порезать опару ножницами ил порвать на кусочки. Соединить основу с опарой. Размешать. Месить минуты две, отставить минут на двадцать. Можно добавить чуть-чуть воды. Смотреть на тесто, если будет очень сложно соединить, то налить грамм пять воды. Еще минут десять мешать и отставить на пятьдесят минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5825,'Обмять тесто, поделить на восемь частей. Сформировать колобки. Обмять кусочки внутрь и лепить, как пирожки. Класть гладкой поверхностью вверх. Придавить колобок ладонью, чтобы получилась лепешка. Отставить минут на сорок. Сформировать выпечку. В центре сделать отверстие, слепить бублик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5825,'Подравнивать каждый бублик по три раза. Каждый раз накрывать бублики полотенцем, отставлять на несколько часов. Закипятить в кастрюльке воду, положить на дуршлаг бублик. Варить секунд десять и выложить на противень. Посыпать украинские бублики по ГОСТу маком, отправить в духовку минут на пятнадцать. Готовить, соблюдая температуру 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5826,'Порезать овощи на кубики. Почистить рыбу от чешуи, обрезать жабры, плавники. Выпотрошить, промыть. В формочку сложить овощи. Посыпать перцем, солью, размешать руками. Положить рыбу на овощи, сверху выложить колечки помидоров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5826,'Посыпать перцем и солью. Посыпать тимьяном, побрызгать оливковым маслом. Формочку накрыть фольгой. Готовить запеченную рыбу с картошкой и помидорами минут сорок, соблюдая температуру 200 градусов. Снять фольгу, выпекать еще пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5827,'Растопить масло при комнатной температуре, взбить, медленно наливая сгущенное молоко. Измельчить в мясорубке печенье. Порезать на маленькие кусочки мармелад. Соединить печенье с кремом, положить мармелад, завернуть все в специальную бумагу, формируя продолговатую форму. Отправить часа на четыре в холод. Порезать на кусочки, положить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5828,'Добавить в холодный борщ без мяса «Ставропольский» соль, перец и сахар за 5 минут до конца варки, подавать борщ охлажденным со сметаной и зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5829,'В одну емкость налить жидкие продукты: яйца, лимонный сок, молоко, масло. Размешать. Разрезать белый шоколад на маленькие кусочки. В другую емкость положить сухие продукты: разрыхлитель, сахар, муку, соль, шоколад. 1/2 часть подготовленного шоколада оставить для украшения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5829,'Размешать. Пересыпать сухую смесь в жидкую. Аккуратно перемешать. Если остались маленькие комочки, то ничего страшного, главное, чтобы сильно перемешивать, так как кексы станут очень жесткими. Положить в массу ягоды. Если ягоды замороженные, то перед добавлением нужно их разморозить. Аккуратно смешать ягоды и тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5829,'Положить бумагу в формочку, аккуратно положить тесто до верха, чтобы в процессе готовки получался красивый купол. Украсить кексы белым шоколадом. Если нет в наличие специальной бумаги, то готовить минут двадцать, соблюдая температуру 180 градусов. Когда ягодные кексики с белым шоколадом приобретут золотистый цвет, достать их из духового шкафа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5830,'Растереть чеснок с душистым и черным перцем, солью. Намазать полученной смесью сало (желательно грудинку с мясной прослойкой). Завернуть в полиэтилен несколько раз. Стараться, чтобы не попал внутрь воздух. Оставить на ночь мариноваться. Налить в кастрюльку воды, положить сало, варить несколько часов, оставить остывать в воде. После остывания отправить вкуснейшее сало по-домашнему в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5831,'Порезать сыр на кубики по полтора сантиметра. В глубокую емкость вбить яйца, взбить. В другую насыпать сухари для панировки. Сырные кубики обмакивать во взбитые яйца, потом в сухари, таким образом, несколько раз. Готовить жареный сыр по-чешски секунд по сорок с каждой стороны на большом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5832,'Крупно потереть кабачок, слить сок. Вбить яйцо, насыпать муку, посыпать солью. Замесить тесто. Положить равномерно тесто на сковороду, смазанную маслом. Пожарить блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5832,'Потереть морковь, порезать луковицу, обжарить. Добавить тертый сыр, прессованный чесночок. Положить майонез. Можно положить зелень. Намазать начинкой блинчики. Отставить кабачковый торт с овощами и сыром для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5833,'Порезать семгу на кубики диаметром приблизительно три сантиметра. Соединить сок лимона, соевый соус, сахар, белое вино, лук, имбирь, чесночок, смешать в блендере. Вылить маринад на рыбу, мариновать семгу в винном маринаде часов двенадцать, дать стечь жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5833,'Из остального маринада приготовить соус. Вылить в ковш и довести до кипения. Взбить крахмал со сливочным маслом. Порезать на тоненькие полосочки зеленый лук, обжарить на сливочном масле. Осторожно соединить продукты, посыпать перцем, солью. Подавать соус отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5834,'Смешать в стакане сырые дрожжи, сахар, влить чуть теплой воды (должна лишь прикрыть дрожжи).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5834,'Когда дрожжи поднимутся добавить соль с яйцами, все хорошо взбить и долить теплой воды до полного стакана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5834,'Порубить с маргарином просеянную муку, вылить из стакана дрожжевую смесь, замесить мягкое тесто и слепить пирожки с начинкой из творога.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5834,'Дальше пирожки с творогом из быстрого дрожжевого теста можно готовить в духовке или обжарить на сковороде, из указанного количества продуктов получится примерно 25 пирожков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5835,'Приготовить омлетные блины. Взбить яйца, муку, посыпать солью, положить соду. Пожарить на сковороде несколько омлетных блинов. Намазать их майонезом, насыпать укроп, осторожно свернуть рулетики. Когда они остынут, разрезать их поперек на кусочки толщиной от 50 миллиметров до 1 сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5835,'Приготовить салат. В салатник положить пленку, чтобы свисали краешки, плотно положить рулеты. Крупно натереть огурцы и картофель. Положить в формочку 1/2 картофеля, чтобы не развалились рулеты, уплотнить. На картошку положить тертые огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5835,'На кубики порезать мясо или колбасу, измельчить лук, положить горошек, майонез, размешать, и положить массу на огурчики. Накрыть остальным картофелем. Накрыть пленкой, оставленной по краешкам, размять и отправить часа на четыре в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10993,'Добавляем муку и замешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5835,'Сверху пленку убрать, перевернуть салатник на плоскую тарелку, убрать емкость с пленкой. Украсить салат «Оливье» рулетами из омлета, листиками петрушки, кружками оливок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5836,'Приготовить корж. Соединить мюсли с сахарным песком. Хорошенько размешать и переложить в разъемную формочку, покрытую специальной бумагой. Отправить корж в холодильник. В это время замочить в воде желатин. Откинуть маринад на сито, чтобы стекла жидкость. Соединить творог, сыр, сок лимона, йогурт, сахар, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5836,'Достать из воды желатин, позволить жидкости стечь. Распустить в кастрюльке на маленьком огне. В отдельной емкости постепенно соединить крем и желатин, сначала несколько ложек крема, затем положить остальной. Охладить. Положить взбитые сливки в крем, размешать. Добавить маринад, размешать. Готовым кремом смазать корж, выровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5836,'Отправить йогуртовый торт с мандаринами в холодильник часа на три для охлаждения. После этого достать тортик из формочки, сверху положить дольки мандаринов, порезанных на куски. Подогреть апельсиновый конфитюр и вылить его на торт, посыпать мюсли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5837,'Размягченный маргарин смешать с половиной нормы сметаны. Всыпать пшеничную муку, замесить тесто, соль – по вкусу. Выложить массу в смазанную форму для выпечки, сформовать бортики. Печь в течение 10 минут при 200 градусах, насыпав на корж фасоль или горох в качестве груза. Для начинки обжарить грибы на растительном масле с репчатым луком и солью, сначала обжарить лук, затем – грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5837,'Для заливки смешать сметану с сырым куриным яйцом и взбить с помощью блендера на минимальной скорости. Вынуть из коржа бобовые, выложить грибную начинку, залить сметанно-яичной смесью. Печь в течение 40 – 45 минут в духовке, за пять минут до окончания приготовления посыпать грибной пирог-жульен тертым сыром. Подать блюдо в теплом или холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5838,'Пшеничную муку хорошо просеять через частое сито. Добавить сырые яйца, сахарный песок и соль. Влить два стакана молока, тщательно перемешать до однородной массы, в которой не должно быть комочков. Влить сливки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5838,'Растопить на водяной бане сливочное масло, немного остудить и ввести в тесто. Масса должна легко растекаться по сковороде. Выпечь бабушкины тонкие блинчики с двух сторон, сковороду смазать небольшим количеством растительного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5839,'Приготовить смесь из яиц, меда, сахарного песка, размягченного сливочного масла. Все ингредиенты перемешать, поставить кастрюлю с массой на тихий огонь или на водяную баню и прогреть, постоянно помешивая. Всыпать пищевую соду. Тесто должно подняться, значительно увеличиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5839,'Убрать кастрюлю с плиты, немного остудить, постепенно вмешать муку. Получившийся липкий ком выложить на присыпанную мукой поверхность. Разделить на шесть «колобков», быстро раскатать лепешки. Ровно обрезать кря с помощью крышки или блюда соответствующего размера. Коржи выпечь до светло-коричневого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5839,'Приготовить крем из сахарного песка со сметаной, массу взбить и добавить ванилин. Прослоить коржи кусочками чернослива и полученным сметанным кремом, смазать им верх и бока. Обрезки также выпечь, измельчить и присыпать торт.  Поставить медовый торт со сметаной и черносливом в холодильник на несколько часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5840,'Для теста сливочное масло взбить с сахарным песком, добавить сырое куриное яйцо, всыпать просеянную пшеничную муку. Замесить мягкое и эластичное тесто. Поставить на полчаса в холодильник. Охлажденное тесто разделить на четыре части, раскатать коржи. Можно сделать это между листами бумаги для выпечки. Выпечь на этой же бумаге в духовке, при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5840,'Коржи можно сделать круглыми или квадратными, прямоугольными. Промазать торт кислым джемом или вареньем, например, брусничным или клюквенным. Завернуть в фольгу, поставить под груз на несколько часов. При подаче обмазать верх и бока выпечки тем же джемом, что использовался для прослаивания коржей. Обсыпать идеальный песочный торт крошками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5847,'В винегрет постный по-русски можно добавить отварную или консервированную белую (для контраста) фасоль, а придать кислоту – квашеной капустой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10993,'Добавляем остывший фарш. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5841,'Взбить сырые яйца и сахарный песок с помощью венчика. Массу поставить на водяную баню, добавить сливочное масло, мед, пищевую соду, перемешать. Постепенно, порциями, всыпать пшеничную муку. Масса начнет темнеть, через 10 минут заварное тесто снять с огня, всыпать еще немного муки, перемешать. Массу поставить в холодильник на час или два.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5841,'Разрезать тесто на пять «колобков», раскатать на присыпанной мукой поверхности тонкими лепешками. С помощью тарелки вырезать круги нужного диаметра. Выпечь на застеленном бумагой противне при температуре 190 градусов до готовности, коржи должны приобрести темно-золотистый цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5841,'Приготовить крем из мягкого сливочного масла и сгущенного молока. Прослоить коржи, верх также смазать полученной смесью, обсыпать крошкой, оставшейся от выпечки. Дать торту «Каприз» постоять для пропитывания в течение нескольких часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5842,'Отварить креветки в течение трех минут. Разрезать пополам помидоры черри, всыпать консервированные оливки, нарезать сыр фета в масле с травами. Перемешать. Если для приготовления использовался простой сыр без масла, то добавить в салат оливковое масло и прованские травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5843,'Натереть на терке сырой очищенный картофель. Влить сырое яйцо, всыпать по вкусу соль и молотый черный перец. Массу перемешать и выложить на ломтики белого батона. Обжарить с растительным маслом с двух сторон до румяной корочки. Гренки с картофелем подать горячими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Залить мясо холодной водой и поставить варить, дать закипеть и удалить пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Разрезать луковицу вдоль на две половинки, разогреть сухую сковороду и обуглить срез луковицы, положить в бульон и варить час, такая процедура придаст бульону еще больший аромат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Посолить бульон и варить еще час, убрать с плиты, мясо вынуть и дать чуть остыть, включить на разогрев духовку до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Очистить и порезать кубиками морковь, лук, картофель, обжарить лук с морковью, добавить в конце томатную пасту, перемешать и нагревать еще 2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Вынуть из бульона лук, переложить тушеные овощи в кастрюлю, добавить крупу гречки, нашинкованную капусту, порезанное мясо, заправить перцем, солью, лавровым листом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Закрыть плотно вместо крышки фольгой и отправить в горячую духовку, щи «Русские» с гречкой и говядиной будут готовы через полтора часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5844,'Разлить щи по подогретым тарелкам и добавить сметану, можно украсить зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5845,'Разрезать крылья вдоль сустава на две части, подрумянить на масле и переложить в казан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5845,'Нарезать картофель брусочками, лук нашинковать полукольцами, все поджарить в сковороде на смеси сока от крыльев и масла до мягкости, добавить кетчуп, залить стаканом бульона (можно кипятком) и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5845,'Залить зажаркой курицу в казане, добавить картофель, поперчить, посолить, заправить по вкусу специями, закрыть крышкой и довести до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5845,'Жаркое из куриных крылышек и картофеля будет готово примерно через 30-40 минут. разложить жаркое по тарелкам и посыпать рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5846,'Натереть очищенную половину картофеля на мелкой терке, заправить чайной ложкой розмарина, другую половину – на крупной, смешать вместе обе части и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5846,'Натереть лук (тоже на мелкой терке), добавить картофель, поперчить, всыпать по щепотке сухого базилика и молотого кориандра, подсыпать 3 ст.л. муки, перемешать, драники из картофеля и лука с розмарином получатся более красивыми и аппетитными, если при замешивании картофельной массы добавить еще и куркуму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5846,'Обжарить драники на хорошо разогретом растительном масле, как обычные оладьи 7-8 мин (за это время перевернуть один раз).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5846,'Выложить на подогретые тарелки, подать горячими со сметаной, как второе, а можно и вместо хлеба к супу или борщу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5847,'Сварить все овощи в кожуре до готовности, остудить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5847,'Нарезать кубиками свеклу, кислые огурцы, картофель, морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5847,'Мелко нашинковать репчатый лук (или зеленый), добавить к овощам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5847,'Заправить винегрет маслом, смешанным с горчицей и уксусом, перемешать, посолить, поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5848,'Обжарить нарезанные грибы (жидкость должна полностью выпариться), засыпать натертую морковь и лук, жарить еще 5 минут, подсолить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5848,'Смешать в сковороде грибы, лук, морковь и капусту, перемешать, прогреть все 2 минуты и дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5848,'Эта начинка для пирожков из капусты, моркови и грибов – прекрасная альтернатива мясу в дни поста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5849,'Пастеризованное молоко заквасить, можно просто оставить на двое или трое суток при комнатной температуре. Другой вариант: прогреть до 40 градусов, добавить ложку кефира, оставить на сутки. Поставить на огонь и довести до кипения. Взбить вручную, венчиком, четыре сырых яйца и кислое молоко. Масса должна получиться средней густоты. При закипании молока огонь уменьшить, помешивая, ввести яичную смесь. Прогревать до створаживания: масса должна разделиться на плотную массу и сыворотку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5849,'Через 7–10 минут смесь откинуть на дуршлаг или сито, предварительно выстланное марлей, дать стечь жидкости. Красный сладкий перец мелко нарезать, порубить зеленый укроп. То и другое добавить в сырную массу, посолить, хорошо перемешать. Выложить сыр в любую форму, утрамбовать, придавить грузом, оставить на 8–10 часов. Готовый домашний сыр с красным перцем вынуть, натереть солью и поставить в холодильник на час или два, завернув в пищевую пленку или пакет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5850,'Это блюдо — некое подобие ухи, основное отличие – это использование в процессе приготовлении рассола, соленых огурцов и лимонов с большим количеством специй. Вкуснее всего суп калья из рыбы по-русски получается из жирной морской рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5850,'Нарезать крупно картофель, нашинковать морковь и положить в кипяток, добавить корень петрушки и варить 20 минут на малом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5850,'Вскипятить рассол, вылить в суп, положить куски рыбы, мелко нарезанные огурцы и лук, варить еще 20 минут, приправить лавровым листом и шафраном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5850,'Добавить перед окончанием варки в калью измельченные укроп и эстрагон, заправить перед подачей соком лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5851,'Нарезать репчатый лук, добавить сухие приправы для куриных окорочков, размять руками, чтобы выделился сок. Добавить томатный сок или консервированные помидоры в собственном соку, либо свежий порезанный помидор. Влить немного майонеза, нарезанный сладкий болгарский перец, перемешать. Обмазать смесью окорочка и оставить на час для маринования.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5851,'Нарезать очищенный картофель тонкими кружочками, посолить, поперчить по вкусу, добавить сметану, перемешать. Выложить на противень, застеленный фольгой: картофель в середине, по краям – окорочка. Печь около часа при 220 градусах. При готовности блюда полить картофель с курицей смесью сметаны и домашней аджики. Через пять минут духовку выключить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5852,'Размягчить сливочное масло, взбить с сахарным песком. Добавить яйца по одному, продолжать взбивать. Всыпать просеянную муку с разрыхлителем, влить молоко, смешанное с какао-порошком, кофе. Замесить однородное тесто. Переложить массу в чашу мультиварки, печь в течение получаса в режиме «Выпечка» или в режиме «Мультиповар» в течение 40 – 45 минут при температуре 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5852,'Готовый кекс осторожно вынуть и остудить на решетке. Разрезать на две части по горизонтали острым ножом. Для приготовления крема перемешать сыр маскарпоне и вареную сгущенку, взбить, промазать коржи. Верх кекс-торта также смазать сырным кремом, сделать рисунок из «дорожек» с помощью вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5853,'Форму для выпекания смазать оливковым маслом. На дно выложить замороженные пельмени из магазина. Смешать сметану, томатную пасту, воду, посолить и поперчить по вкусу. Вылить соус на пельмени, печь в духовке при 190 градусах в течение получаса. За пять минут до готовности посыпать пельмени в сметанно-томатном соусе тертым сыром и допечь до образования румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5854,'В больших готовых булочках для хот-догов вырезать «кармашек», смазать майонезом. Куриные филе разрезать пополам, вдоль, посолить и поперчить по вкусу. Из сладких болгарских перцев разного цвета удалить плодоножки и семена. Нарезать ломтиками. Тонко нарезать красный репчатый лук, порубить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Соль, сахар и муку смешать, в получившейся смеси растереть в мелкую крошку сливочное масло и поставить емкость в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5854,'Филе обжарить на сковороде, в растительном масле, до готовности, с двух сторон по три минуты. Остудить и порезать тонкими ломтиками. В сковороду, где обжаривалась курица, добавить лук и перец, прогревать в течение 5–7 минут до готовности перца. Переложить в смесь филе, тертый твердый сыр, перемешать. Положить курицу с болгарским перцем в булочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5855,'Пропустить через мясорубку куриное филе, очищенный картофель. Перемешать, добавить тертый сыр, нарезанный чеснок, сырые куриные яйца, манную крупу. Соль и молотый перец – по вкусу. Добавить сушеный тимьян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5855,'Массу вымесить и дать постоять в течение 20 минут для набухания крупы. Сформовать котлеты из курицы с картофелем и сыром, жарить на сковороде до готовности, с двух сторон, под крышкой. Можно допечь до готовности в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5856,'Филе курицы измельчить в мясорубке с репчатым луком. Добавить сырой желток, массу вымесить, соль и молотый перец – по вкусу. Сформовать небольшие котлеты, обмакнуть во взбитый венчиком белок, затем – в панировочные сухари. Обжаривать на сковороде, на среднем огне, до образования румяной корочки. Для приготовления соуса обжарить измельченный лук и рубленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5856,'Отдельно смешать муку с холодной водой, хорошо размешать, чтобы не было комочков, постепенно, порциями, влить теплую воду. Смесь процедить через ситечко, влить в луковую обжарку, помешивать. Посолить и поперчить, положить лавровый лист, довести до кипения. В закипевший соус добавить сметану, дать покипеть до загустения. Полить готовые куриные котлетки луковым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5857,'Просеять через мелкое сито пшеничную муку, добавить охлажденное и натертое сливочное масло или маргарин. В другой посуде смешать кефир со сметаной, смесь вылить в емкость с мукой. Замесить тесто, поставить его в холодильник на несколько часов. Обжарить на тихом огне грецкие орехи. Промыть курагу и чернослив, залить на 10 минут кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5857,'Готовое охлажденное тесто разделать на лепешки, очень тонко раскатать на присыпанной мукой поверхности. Нарезать на треугольники-сегменты, от центра–к краю. На широкие части выложить начинку из чернослива и орехов (или кураги и орехов), скатать  рогалики. Выложить полученные изделия на присыпанный мукой противень, печь рогалики с черносливом и курагой в течение 20–25 минут при температуре 185–200 градусов. Выпечку остудить, посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5858,'Для приготовления коржей: просеять пшеничную муку вместе с разрыхлителем, добавить порезанное кусочками сливочное масло или маргарин, сахарный песок, соль, сырой желток. Замесить песочное тесто. Скатать массу в виде «колобка», завернуть в пищевую пленку и поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5858,'Выложить тесто в разъемную форму, наколоть вилкой в нескольких местах, печь при 180 градусах в течение 20 минут. Корж вынуть из духовки, остудить. Для крема замочить желатин так, как указано на упаковке, нагреть и процедить. Смешать с помощью блендера творог, сметану, сахарный песок, ванилин из пакетика, желатиновую массу. Залить полученной смесью корж, поставить на час в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5858,'Замочить желатин в воде на 40 минут, прогреть, процедить. Вымыть виноград, удалить веточки. Разогреть в кастрюле в кастрюле белое мускатное вино с лимонным соком и сахаром. Влить в смесь желатин, немного остудить. Выложить ягоды винограда на застывший крем, залить желе с вином, поставить торт «Зеленый мускат» с виноградом в холодильник еще на четыре часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5859,'Приготовить крошку. Для этого пшеничную муку и сливочное масло порубить ножом, добавить сахарный песок и разрыхлитель. Массу растереть в крошку. Для начинки смешать творог, сырые яйца, обычный и ванильный сахар. Массу взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5859,'Разъемную форму для выпечки застелить бумагой, выложить крошку и начинку в три слоя. На дне формы должна быть крошка, последний слой – тоже крошка. Печь в духовке при температуре 180 градусов в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5859,'Для заливки смешать сгущенное молоко со сметаной. Растопить темный шоколад на водяной бане, добавить сметану. Горячую венгерскую ватрушку залить в форме сметанно-молочной смесью, шоколад вылить каплями, сделать вилкой или зубочисткой разводы. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Муку, соль, разрыхлитель и соду просеять и убрать в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5860,'Для теста смешать сырое яйцо и сахар, массу взбить. Добавить просеянную пшеничную муку, ванильный сахар из пакетика или лимонную цедру, немного пищевой соды, майонез. Тесто должно получиться полужидким. Застелить противень бумагой для выпечки, выложить печенье столовой ложкой. Печь при температуре 200 градусов в течение 7–10 минут. Печенье на майонезе охладить, затем снять с противня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5861,'Взбить сгущенное молоко с сырыми яйцами. Всыпать пищевую соду, молотую корицу, просеянную пшеничную муку, перемешать. Нарезать очищенные от кожицы и семян, порезанные на мелкие кусочки, зеленые яблоки. Добавить в тесто. Массу выложить в емкость для запекания, предварительно её нужно смазать сливочным маслом. Печь шарлотку в микроволновке в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5862,'Нарезать филе слабосоленой форели и горбуши горячего копчения небольшими кусочками. Отварить и нарубить куриные яйца, свежие и соленые огурцы нарезать кубиками. В смесь добавить консервированную кукурузу без жидкости, измельченный зеленый лук, петрушку. Массу перемешать и заправить рыбный салат по вкусу майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5863,'Отварить курицу, остудить и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5863,'Помидоры, огурцы, ветчину некрупно нарезать, смешать курицу, ветчину и нарезанные овощи, посолить, добавить майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5863,'Готовый салат мясной «Русская красавица» выложить в салатник, украсить ломтиками помидоров и вареных яиц, сверху посыпать натертым сыром и измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5864,'Отварить яйца, охладить, очистить. Аккуратно разрезать пополам, желтки вынуть. Слить масло с консервированной печени трески. Репчатый лук нарезать или натереть. Рыбную печень, желтки и лук размять вилкой, добавить майонез. Можно размешать массу с помощью блендера до однородного состояния. Готовую начинку выложить в половинки яиц, украсить красной икрой, листочком петрушки или веточкой укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5865,'Просеять пшеничную муку, добавить несоленое сливочное масло, нарезанное кубиками, соль, натертый сыр, молоко. Замесить тесто, сформовать шарики-булочки, выпечь в духовке в течение 15–20 минут при температуре 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5866,'Расстелить на противне два куска фольги большого размера. Налить немного оливкового масла, положить филе лосося. Каждый кусок смазать соусом песто из базилика. Нарезать кружками помидоры средней величины, выложить на рыбу так, чтобы они покрыли всю верхнюю часть тонким слоем. Завернуть филе в фольгу. Печь при температуре 230 градусов в течение 15 минут. Вынуть из духовки, охладить в течение 2–3 минут. Открыть фольгу, подать блюдо горячим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5867,'Клубни картофеля очистить и нарезать тонкими кружками. Промыть под холодной проточной водой, чтобы удалить лишний крахмал. Откинуть на сито или дуршлаг, дать воде стечь, обсушить с помощью бумажных полотенец. Растопить сливочное масло. Порубить репчатый лук, обжарить на растительном масле до прозрачности, переложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5867,'В ту же сковороду выложить картофель тонким слоем в виде «чешуи». Посыпать частью лука и рубленой зеленью петрушки, полить небольшим количеством сливочного масла, соль и перец – по вкусу. Слои повторить несколько раз, пока форма не заполниться почти доверху. Жарить картофель на плите в течение 15 минут на среднем огне, затем полить остатками сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5867,'Допечь блюдо до готовности в течение 20–25 минут в духовке, при температуре 220 градусов, до образования румяной корочки. Готовую запеканку вынуть, провести ножом вдоль стенок сковороды, затем перевернуть форму на блюдо. При подаче картофель «Анна» посыпать рубленым зеленым укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5868,'Перемолоть в блендере сырую куриную грудку, морковь, репчатый лук и чеснок. Мелко нарезать грибы, например, размороженные подосиновики или маслята. Вмешать в основную массу. Добавить сырое яйцо, молоко, соль и молотый перец, муку. Смесь должна быть жидкой и однородной по консистенции. Вылить массу в смазанную форму, печь суфле из курицы с грибами при температуре 180 градусов в течение 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5869,'Довести воду в кастрюле до кипения, подсолить по вкусу, влить 2 – 3 столовые ложки растительного масла, отварить ракушки почти до готовности, выложить в дуршлаг, дать стечь воде и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Замесить тесто, оно должно быть крутым, добавить растопленное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5869,'Смешать свиной и говяжий фарш с размятой рикоттой, нарезанным и обжаренным репчатым луком, зеленью петрушки и базилика. Посолить, поперчить по вкусу, добавить соус бешамель, скатать шарики такого размера, чтобы они свободно вошли в «ракушки».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5869,'Остывшие макаронные изделия начинить фаршем, выложить в форму для запекания или на противень с высокими бортиками. Залить ракушки с мясным фаршем соусом бешамель, печь при 180 градусах в течение 20–25 минут. Подать с листочками петрушки и белым сухим вином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5870,'Нагреть воду в кастрюле на плите, нарезать плавленые сырки на небольшие кусочки. Как только вода закипит – положить сырные кубики, прогревать и перемешивать массу до полного растворения. Половину содержимого банки с кукурузой без жидкости измельчить до состояния пюре в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5870,'Оставшиеся целые зерна положить в суп, влить пюре, добавить сушеный укроп и петрушку, поварить в течение 5 – 10 минут.  При желании суп можно сделать гуще, если добавить в него немного кукурузного крахмала, предварительно разведенного в холодной воде. Сырно-кукурузный суп еще раз перемешать и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5871,'Фиолетовый репчатый лук и морковь нарезать кубиками, обжарить на растительном масле до готовности. Всыпать в обжарку мелко нарезанные шампиньоны, посолить и поперчить, добавить сухие ароматные травы или только сухой укроп. У сладких болгарских перцев разного цвета срезать крышечки, удалить семена, заполнить смесью из овощей и грибов, поставить в кастрюлю, закрыть срезанными крышечками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5871,'Залить блюдо томатным соком, если он слишком густой – разбавить водой до нужно консистенции. Добавить лавровый лист, перец-горошек. Очистить клубни некрупного картофеля, разрезать на половинки, положить в кастрюлю. Тушить фаршированные перцы с овощами и грибами в течение 30–40 минут на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5872,'Куриное филе хорошо вымыть, нарезать на кусочки, посолить, поперчить, обжарить на сковороде на растительном масле. Потушить под крышкой еще в течение получаса. Для приготовления соуса нарезать репчатый лук и чеснок, положить в сковороду, жарить с растительным маслом до получения золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5872,'Массу превратить в пюре с помощью блендера. Луковое пюре смешать со сметаной, солью, карри, всыпать красный молотый сладкий перец. Нарезать зелень, добавить в соус. Влить воду или бульон, посолить по вкусу, перемешать. Перелить соус в кастрюлю или сотейник, положить курицу, потушить гедлибже из куриного филе еще 10–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5873,'Истолочь чеснок в ступке, добавить уксус, мед, острую пасту чили или нарезанный на кусочки перец. Соль и молотый перец – по вкусу. Натереть смесью свинину с косточкой. Нарезать репчатый лук кольцами, уложить на мясо и под мясо. Емкость плотно закрыть, поставить в холодильник на несколько часов или на ночь. Мясо в маринаде периодически поворачивать',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5873,'Удалить с мяса лук и твердые составляющие из маринада, чтобы исключить возможность горения продуктов при обжаривании. Окорок выложить на противень или на сковороду, печь при температуре 220 градусов в течение 15 минут. Полить мясо выделившимся соком, вылить на противень маринад без лука, убавить температуру до 200 градусов, печь еще 15–20 минут. Очистить мелкие клубни картофеля, перемешать так, чтобы он со всех сторон оказался смазанным соком от мяса и жиром, печь до полуготовности в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5873,'Добавить мелкую очищенную морковь, нарезанную крупными кусочками, также перемешать с соком и маслом, печь 20–25 минут. Проверить спицей или ножом готовность мяса: если вытекает светлый сок, то противень нужно вынуть, накрыть фольгой и оставить на 15 минут. Приготовить гремолату: порубить чеснок и петрушку, натереть цедру лимона на мелкой терке. Посыпать запеченную свинину с овощами этой смесью перед подачей на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5874,'Смешать муку, сахар, добавить яйца, сметану, немного присолить, получившееся тесто раскатать пластом не более 4 мм толщиной, разрезать на квадратные заготовки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5874,'Растереть творог с яйцами и сахаром, готовую творожную начинку выложить небольшими порциями на уголок квадратов из теста, завернуть квадраты, придавая им форму сочней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Взять другую миску и взбить вместе с сахаром размягченное сливочное масло комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5874,'Подготовленные сочни выложить на лист, тщательно смазанный маслом, для румяной корочки смазать сочни сверху сметаной, поставить в разогретую духовку, запекать до легкого зарумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5874,'Подавать к столу готовые сочни творожные на сдобном пресном тесте со сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5875,'Репчатый лук очистить и измельчить на терке или с помощью блендера. Добавить в куриный фарш, вбить сырое яйцо, смесь перемешать. Мелко нарезать зелень петрушки, натереть сыр. Смешать с фаршем, соль и перец молотый – по вкусу. Сформовать небольшие котлеты, обжарить в небольшом количестве растительного масла на среднем огне до румяной корочки. Подать куриные котлетки в горячем виде с любым гарниром и соусом, зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5876,'Мелкой соломкой нарезать заранее отваренные куриные сердечки и ветчину, маринованные шампиньоны – мелкими кубиками. Свежий огурец и зеленое яблоко натереть соломкой, такой, какая делается для приготовления моркови по-корейски. Натереть любой твердый сыр. Все ингредиенты перемешать, заправить майонезом. Выложить массу в небольшие салатницы, посыпать салат с куриными сердечками сыром и положить по веточке свежего укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5877,'Для приготовления теста смешать просеянную пшеничную муку, какао-порошок, соль. С помощью миксера взбить сливочное масло с сахарным песком, добавить сырой желток. Всыпать мучную смесь, небольшими порциями, перемешать до однородного состояния. Скатать тесто в «колобок», завернуть его в пищевую пленку, поставить в холод на 15 минут. Охлажденное тесто раскатать в тонкую лепешку, выложить в форму с небольшими бортиками, корж часто наколоть вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5877,'Печь при температуре 180 градусов в течение получаса. Остудить. Для начинки влить воду в кастрюлю небольшого размера. Всыпать сахарный песок, влить патоку, довести смесь до кипения. Прогревать, помешивать, жидкость должна стать насыщенного медового цвета. Добавить сливочное масло, жирные сливки, перемешать. Всыпать обжаренный, очищенный фундук, прогревать массу на среднем огне ещё в течение нескольких минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5877,'Готовую начинку вылить в тарт, поставить блюдо в духовку на 18–20 минут. Вынуть форму, остудить. Для приготовления крема взбить с помощью миксера сливки, скорость уменьшить, добавить сахарный песок и ореховый ликер. Украсить выпечку растопленным на водяной бане темным шоколадом. Подать шоколадный тарт с фундуком со взбитыми сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5878,'Небольшие шампиньоны промыть и обсушить. Разогреть растительное масло в сковороде «вог» или казане, выложить грибы, обжарить на сильном огне. Добавить порезанный полукольцами репчатый лук, жарить в течение 3–4 минут, огонь убавить до минимального, накрыть блюдо крышкой, тушить еще 15 минут, два-три раза массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5878,'Нашинковать морковь, добавить в грибы, огонь увеличить. Все вместе обжаривать еще 5–7 минут. Отрезать по половине плода красного и желтого сладкого перца или использовать один плод красного цвета, нашинковать, положить в сковороду с грибами, тушить пять минут. Соль – по вкусу. Добавить куркуму, паприку, базилик и майоран.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5878,'В плов всыпать половину нормы риса, еще немного посолить, добавить специи для плова, выложить оставшийся рис, сверху – специи, соль. Положить в середину головку чеснока, срезать с нее нижнюю часть. Блюдо залить кипящей водой, она должна покрыть рис на один сантиметр. Тушить плов с грибами и болгарским перцем на тихом огне под крышкой в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5879,'Тщательно вымыть, очистить и нарезать кружочками клубни картофеля. Репчатый лук нарезать кубиками. Оба ингредиента смешать, добавить соль и молотый перец, любые сухие специи. Массу выложить в форму для запекания слоем в пять сантиметров, залить молоком. Поверх запеканки выложить нарезанное кусочками сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5879,'Печь при температуре 200 градусов в течение 15 минут, затем температуру убавить до 150 градусов, печь еще 40 минут. Еще вариант: сделать температуру минимальной и оставить блюдо в духовке на 2–3 часа. При подаче посыпать запеченный картофель в молоке зеленым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5880,'Желатин размешать в воде так, как написано на пакете. Прогреть через 40–60 минут после замачивания, не кипятить. Масса должна быть однородной, остудить. Замесить тесто из муки, яиц, сахарного песка и пищевой соды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5880,'Печь при температуре 180 градусов в течение 15 минут. Готовый бисквит остудить, нарезать на небольшие кубики. Цитрусовые очистить от кожуры, апельсины нарезать кружками, мандарины разобрать на отдельные дольки. Бананы и ананасы очистить и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5880,'Взбить сметану с сахаром, добавить ванилин, остывший желатин, перемешать быстро, иначе желатин застынет. Для приготовления десерта понадобится форма с разъемными бортиками. Выложить в нее часть бисквитных «кубиков», сверху – фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5880,'Залить кремом, выложить оставшуюся выпечку и фрукты, залить остатками желатиновой массы. Готовый торт накрыть пищевой пленкой, поставить на ночь в холодильник. Торт-желе «Фруктовый Новый год» вынуть из формы, перевернуть на большую тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5881,'Сырые яйца комнатной температуры разделить на желтки и белки. Для приготовления соуса понадобятся первые. Мягкое сливочное масло, желтки и сок лимона взбить с помощью ручного блендера. В загустевшую смесь добавить мелко нарезанный чеснок, соль по вкусу, молотый перец. Майонез с чесноком перемешать, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5882,'Смешать пшеничную муку, сухие дрожжи, немного соли. В сухую массу добавить маргарин, влить воду и молоко. Замесить тесто. Скатать массу в шар, поставить в теплое место на полтора часа. Затем тесто обмять, оставить еще на 10 минут. Разделить на пять частей, каждую раскатать в прямоугольники, скрутить, края защипать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5882,'Дать изделиям постоять еще в течение получаса. Сделать косые надрезы острым ножом, смазать поверхность смесью молока с сырым желтком. Печь домашние молочные батоны при температуре 180 градусов в течение 20–30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5883,'Приготовить одну опару из дрожжей, муки (3 ст.л.), сахара (1 ст.л.) и молока (150 мл), дать постоять 15 минут, для другой взять по 2 ст.л. муки и сахара, добавить соль, залить молоком (350 мл), смешать с первой и дать постоять 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5883,'Растереть сахар и желтки с растопленным маргарином, сметаной и подсолнечным маслом, добавить 2 взбитых белка и постепенно 5 стаканов муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5883,'Соединить все и замесить эластичное тесто, дать ему подойти, обмять и дать подойти снова, включить на разогрев до 170 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5883,'Сделать небольшие пирожки, для сохранения сока выкладывать вишню на небольшое количество манной крупы и посыпать сахаром, края тщательно защипать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5883,'Смазать пирожки с вишней из сдобного теста сверху яичным белком и отправить в духовку на 20-25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5884,'Нарезать батон на ломтики, залить молоком. Оставить на 10 минут, отжать излишки жидкости. Пропустить через мясорубку куриное филе. Добавить хлебную массу, соль и перец–по вкусу. Смесь вновь пропустить через мясорубку. Добавить сливочное масло комнатной температуры, перемешать. Слепить, обвалять в муке, обжарить биточки из куриного филе с двух сторон до румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5885,'С куриных окорочков аккуратно снять кожицу «чулком». Филе отделить от кости, нарезать небольшими кусочками, добавить кубики нежирной свинины такого же размера. Замариновать мясо в домашнем майонезе с горчицей в течение получаса. Отдельно очистить и нарезать кусочками апельсин, выдавить чеснок. Соль и перец – по вкусу, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5885,'Наполнить «чулки» из кожи начинкой, края завернуть и закрепить зубочисткой. Обжарить на раскаленной сковороде со всех сторон, до образования румяной корочки. Переложить куриные окорочка со свининой в форму для запекания, довести до готовности в духовке при температуре 180 градусов в течение 20 минут. При подаче нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5886,'Хорошо взбить сырые куриные белки. Натереть твердый сыр, оба ингредиента смешать. Сформовать шарики величиной с яйцо, обвалять их в панировочных сухарях и обжарить во фритюре до золотистого цвета. Выложить сырные шарики на бумажные полотенца, дать впитаться излишнему жиру. Подать с обжаренными веточками петрушки, дольками лайма.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5887,'Перемешать и взбить оливковое масло, чеснок, сахарный песок, соль  и молотый перец – по вкусу. Противень застелить пищевой фольгой. Нарезать помидоры кружками, выложить на фольгу, сбрызнуть масляной смесью. Печь в течение 20–25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Добавить цедру лимона, вбивать по одному яйцу, хорошо перемешивая после добавления каждого яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5887,'Растопить на сковороде сливочное масло, температура должна быть средней. Обжарить ломтики хлеба с двух сторон. На очень горячую сковороду высыпать тертый сыр пармезан, жарить до коричневой корочки. Снять с огня и поломать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5887,'На каждый тост нанести козий сыр, выложить по два-три кружка обжаренных помидоров, уложить их «чешуей». Посыпать рубленой зеленью базилика, петрушки, розмарина. Сбрызнуть бутерброды с помидорами бальзамическим уксусом, украсить кусочками жареного пармезана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5888,'Картофель очистить, вымыть, отварить, хорошо обсушить. Клубни растолочь в пюре. Остудить, добавить муку и сырое яйцо. Массу перемешать, она должна быть эластичной и не липнуть к рукам. Отварить говяжью печень, пропустить через мясорубку или измельчить с помощью блендера. Очистить и нарезать репчатый лук, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5888,'Соединить с печенью, посолить и поперчить. Добавить две ложки пюре из картофеля, перемешать. Из пюре сформовать лепешки, выложить печеночную начинку, соединить противоположные края. Слепить «пирожки». Обвалять зразы в панировочных сухарях либо просто смазать верхнюю часть чуть взбитым сырым желтком. Печь зразы из картофеля в духовке при температуре 180–200 градусов в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5889,'Для приготовления начинки очистить и нарезать стебель лука-порея и репчатый лук. Вымыть, очистить и нарезать морковь маленькими кубиками. На растительном масле обжарить репчатый лук, затем смесь моркови с колечками лука-порея. Обжарка должна приобрести золотистый цвет. Очистить и нарезать ломтиками шампиньоны, ветчину – кубиками. Оба ингредиента добавить в овощную обжарку, соль и перец – по вкусу, подержать на огне пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5889,'Взбить сырые куриные яйца со сливками, посолить, всыпать тертый мускатный орех. Массу соединить с жареными ингредиентами. Плоды сладкого желтого и красного перца разрезать пополам вдоль, очистить. Половинки наполнить начинкой, выложить на противень, влить немного мясного бульона и печь в течение 15–20 минут. Нарезать ломтиками сыр моцарелла. Достать из духовки почти готовые перцы с шампиньонами и ветчиной, положить по ломтику, печь еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5890,'Очистить кальмаров или разморозить, если они уже очищены. Отварить рис до полуготовности, воду немного посолить. Отварить яйца. Мелко нарезать крабовые палочки, натереть сырую морковь, добавить зелень и рубленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5890,'Все ингредиенты смешать, заправить майонезом. Нафаршировать кальмары. Форму или противень смазать растительным маслом, промазать фаршированные тушки майонезом, поставить в духовку на полчаса, температура – 220 градусов. При подаче кальмары «Белоснежка» посыпать рубленой зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5891,'Охлажденное сливочное масло порубить ножом вместе с мукой. Добавить сырое яйцо, сахарный песок, быстро перемешать. Сформовать шар, обернуть пленкой, положить в холод на полчаса. Для приготовления заливки взбить вручную, венчиком, сметану, сырые яйца, сахарный песок, ванильный сахар, пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5891,'Вымыть клубнику, удалить «хвостики», разрезать на две или четыре части. Форму для пирога выстелить песочным тестом, наколоть вилкой в нескольких местах. Выложить ягоды, залить сметанным кремом. Печь пирог с клубникой в сметанной заливке при температуре 180 градусов в течение 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5892,'Отварить куриные яйца, остудить, порубить. Обжарить грецкие орехи, очистить от пленки. Измельчить очищенное яблоко, ошпаренный репчатый лук, чернослив, натереть твердый сыр. С копченых куриных окорочков снять кожицу, филе нарезать мелкими кубиками. Все ингредиенты уложить слоями в виде «рога изобилия», промазывая майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5892,'Слои должны располагаться в таком порядке: куриное мясо, лук, яблоко, сыр, мелко нарезанный чернослив. Поставить в холодильник для пропитывания. Перед подачей нанести на салат «сеточку» из майонеза с помощью кондитерского шприца. В каждый «ромб» положить по половинке грецкого ореха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5903,'Из цветных перцев удалить семена, плоды хорошо вымыть, опустить на две минуты в кипяток, быстро охладить в холодной. Стерилизовать банки на пару. Перцы вложить один в другой, «пирамидки» уложить в банки вертикально. Можно просто сплющить плоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Месить вручную, в течение 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5893,'Вымыть, очистить и тонко нарезать клубни среднего размера. Выложить картофель в ледяную воду, добавить кубики льда, на время оставить. Затем переложить на полотенце и обсушить. Противень выстелить бумагой для выпечки, выложить картофель «чешуей», посыпать сушеными травами, сбрызнуть оливковым маслом. Печь до образования золотистой корочки. Вынуть картофельные чипсы из духовки, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5894,'Зажарить филе курицы и мясо, нарезать кубиками, нашинковать мелко лук, нарезать небольшими кубиками огурец и вареную свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5894,'Смешать аккуратно все ингредиенты и уложить горкой в салатник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5894,'Закуска «Окрошка» по-русски перед подачей поливается смесью сметаны и кваса, сверху закуску украсить нарезанным зеленым луком, ломтиками маринованной сливы, выложить вокруг квашеную капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5895,'Небольшой вилок капусты нашинковать, посолить, перетереть руками, чтобы выделился сок. Для приготовления теста взбить яйца с солью, кефиром или сметаной. Пшеничную муку перемешать с содой, всыпать в кефирную смесь. Тесто должно быть полужидким, как для приготовления оладий.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5895,'Начинку отжать от излишней жидкости, выложить в форму. Растопить сливочное масло, полить капусту. Залить массу тестом, печь в течение 30–40 минут при температуре 180 градусов. Быстрый наливной пирог с капустой должен зарумяниться. Перевернуть готовое блюдо на тарелку и подать к столу в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5896,'Красный репчатый лук нарезать и смешать с винным уксусом. Добавить оливковое масло, перемешать. В течение двух минут обжарить семена кориандра на сухой сковороде, растолочь в ступке, перемешать с острым красным молотым перцем и оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5896,'Тонкими дольками нарезать помидоры, выложить в блюдо для салата. Добавить измельченный чеснок, оливки, маринованный лук, масляную заправку. Салат с помидорами и оливками хорошо перемешать и посыпать рубленой кинзой. Соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5897,'Натереть свежую морковь и яблоки вместе с кожурой. Очистить и нарезать кубиками апельсин или грейпфрут, перегородки удалить. Ингредиенты перемешать, добавить жидкий мед. Блюдо можно посыпать небольшим количеством корицы. Заправить натуральным йогуртом или сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5898,'Плавленый сырок охладить в морозильной камере в течение 20 минут. Натереть. Также натереть чеснок, сваренные вкрутую куриные яйца. Все ингредиенты перемешать с майонезом и измельченным укропом. Нарезать кружками помидоры, на каждый выложить сырную массу, украсить зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5899,'Очистить киви, лайм, авокадо, все ингредиенты взбить до однородной массы. Выложить массу в креманки, украсить кусочками бананов, тонко нарезанным киви, листочками мяты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5900,'Нашинковать и потереть руками нашинкованную белокочанную капусту. Нарезать соломкой вареную колбасу, репчатый лук – полукольцами. Посолить салат по вкусу, заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5901,'Тонко нашинковать свежую капусту. Натереть очищенную морковь, нарезать сладкий болгарский перец полосками. Репчатый лук, помидоры и огурцы нарезать кубиками. Овощи переложить в эмалированную кастрюлю. Влить растительное масло, всыпать сахар, соль, перец-горошек, положить лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5901,'Массу довести до кипения, варить на тихом огне в течение часа, помешивая. В конце приготовления влить уксус. Готовую заготовку разложить в стерилизованные на пару банки и закатать. Перевернуть вверх дном. Остывшую овощную солянку хранить в прохладном месте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5902,'Сырые яичные белки взбить в пену, всыпать сахарную пудру, влить лимонный сок. Замочить в воде желатин на час в холодной воде, прогреть, остудить, затем тонкой струйкой влить в белковую массу, взбить. Сварить какао, кипятить пять минут, до легкого загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5902,'Влить еще одну порцию растворенного желатина. В форму для десерта вылить смесь какао с желатином, поставить в холодильник, затем выложить слой белковой массы, поставить в холод еще на 15 минут. Оставшееся какао подогреть, влить в форму, снова остудить в течение часа или полутора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Солянка сборная мясная с говядиной и почками подается со сметаной и измельченной зеленью петрушки, украшается тонкими ломтиками лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11096,'Влить немного воды, тушить почти до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5903,'Приготовить заливку из воды с сахарным песком, солью, лимонной кислотой, вскипятить. Залить болгарский перец, стерилизовать литровые банки в течение 20 минут, трехлитровые – 25 минут. Закрыть крышками, закатать, остудить в перевернутом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5904,'Отварить картофель в мундире, остудить, почистить и растолочь в пюре, немного посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5904,'Готовое пюре смешать со скисшим молоком, тщательно вымесить, выложить получившуюся массу в плотно закрывающуюся емкость и оставить на 3-4 дня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5904,'Получившуюся тестообразную картофельную массу повторно вымесить, разделать на небольшие шарики, оставить для просушки в затененном месте, затем закуску выдержать в бочке или глиняной посуде в течение 15 дней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5904,'Чем дольше будет выдерживаться закуска русская «Картофельный сыр», тем вкуснее она станет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5905,'Немного нагреть молоко, растворить в нем сухие дрожжи, сахарный песок, соль. Массу перемешать и оставить на 10 минут. Затем влить растительное масло, всыпать просеянную пшеничную муку. Замесить тесто, оно должно быть мягким и эластичным. Положить его в посуду, накрыть полотенцем, поставить в тепло на полтора часа. Тесто должно увеличиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5905,'Разделить подошедшее тесто на шарики небольшого размера, серединки примять и положить внутрь немного натертого твердого сыра. Края собрать вокруг начинки, закрутить. Получившиеся пампушки выложить на застеленный пергаментом противень швом вниз. Смазать чуть взбитым желтком, оставить на полтора часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5905,'Печь в течение 20 минут при температуре 200 градусов. Для приготовления соуса натереть чеснок, влить в массу растительное масло и немного воды, перемешать. Горячие, только что выпеченные, сырные пампушки, смазать соусом, накрыть полотенцем, оставить на 15 минут, жидкость должна впитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5906,'Свежий огурец  и плавленый сыр нарезать соломкой. Можно использовать любой твердый сыр. Листы нори разрезать пополам. Циновку положить в пакет из целлофана, поверхность смочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5906,'Недорогую рыбу, например, горбушу, заранее засолить. Готовое филе нарезать длинными кусочками. Отварить круглый рис, выложить на циновку. Руки должны быть мокрыми, тогда масса не будет прилипать. Выложить огурцы и рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5906,'Придать роллам квадратную форму, бруски разрезать пополам. Приготовить кляр из яйца и панировочных сухарей, можно добавить семена кунжута или заменить ими сухари. Обмакнуть закуску в смесь, обжарить темпурные роллы со всех сторон до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5907,'Свежие шампиньоны почистить, нарезать, посолить по вкусу, жарить на среднем огне под крышкой. Избыток жидкости слить, долить в сковороду растительное масло. Очистить и нарезать репчатый лук, обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5907,'Отварить и нарезать кубиками куриную грудку, яйца, свежие огурцы. Все ингредиенты выложить в салатник, добавить консервированную маринованную кукурузу без жидкости, перемешать. Соль и молотый перец – по вкусу. Заправить салат «Зодиак» майонезом, снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5908,'Отварить три куриных яйца. Отварить куриную грудку, мелко нарезать. Семь яиц разбить, всыпать специи и зелень по вкусу, добавить кусочки филе. Смесь взбить в течение нескольких минут, можно с помощью блендера. Форму для выпечки прямоугольной формы смазать растительным маслом, присыпать манной крупой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5908,'Вылить половину яичной массы, выложить в ряд отваренные яйца, залить оставшейся массой, крутые яйца должны оказаться внутри запеканки. Печь омлет «Мишна» при температуре 220 градусов в течение 15–20 минут. Немного остудить в форме, затем перевернуть ее на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5909,'Свиное мясо промыть и обсушить. Если верхний слой – жир, надрезать его в виде «сеточки». Смешать цедру лимона, розмарин, перец-горошек, сушеный чеснок и кориандр смешать с морской солью и оливковым маслом. Массу тщательно растереть в ступке или измельчить с помощью блендера. Натереть филе смесью со всех сторон. Завернуть мясо для маринования в пищевую пленку, поставить в холодильник на два часа или на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5984,'Нашинковать мелко лук, можно измельчить в блендере, натереть или измельчить блендером картофель. Добавить к смеси яйцо, манку, немного воды, чуть присолить, поперчить, полчаса дать смеси постоять. Слепить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5909,'За два часа до запекания мясо вынуть, подержать при комнатной температуре. Освободить филе от пленки, положить в жаропрочную посуду с решеткой. Печь при температуре 200 градусов в течение 15 минут, затем огонь уменьшить до 170 градусов, печь блюдо еще в течение часа. Проверить готовность острым ножом или спицей – из мяса не должна вытекать жидкость. Вынуть мясо, подать сочную свинину с ароматной корочкой горячим через 15 минут или полностью охлажденным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5910,'Помидор вымыть, разрезать на кружки, натереть твердый сыр. Вымыть и порубить зелень укропа и петрушки, кинзы. Ветчину тонко нарезать кружками. Тонкий армянский лаваш сбрызнуть охлажденной водой, выложить на сковороду, смазанную сливочным или растительным маслом. Обжарить с одной стороны, перевернуть, края должны свисать за бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5910,'В середину лепешки положить кружок помидора, посолить по вкусу, сверху – кружок ветчины. Залить сырым яйцом, соль и перец – тоже по вкусу. Посыпать тертым твердым сыром и зеленью. Края лепешки завернуть к центру, жарить до образования румяной корочки. Перевернуть, посыпать сыром и тоже обжарить. Подать закуску в лаваше в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5911,'Зубчики чеснока очистить, разрезать пополам и немного обжарить на оливковом масле. Морского карася посолить, натереть сухими травами – орегано, тимьяном, шалфеем, базиликом и майораном, оливковым маслом. Смесь черного, розового и зеленого перца – по вкусу. С одной стороны тушки сделать глубокие поперечные надрезы, вложить тонкие дольки лимона. Внутрь рыбы – свежий розмарин и обжаренный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5911,'Тушки положить на противень, его нужно предварительно застелить бумагой для выпечки. Полить рыбу маслом, которое осталось после обжаривания чеснока. Приправить щепоткой сахарного песка. Печь при температуре 210 градусов в течение 25 – 35 минут. При подаче украсить дорада дольками лимона и веточками свежего розмарина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5912,'Для приготовления теста нужно смешать сухие дрожжи, теплое молоко и стакан пшеничной муки. Смесь накрыть и дать постоять. Смешать сливочное масло, сахарный песок и соль миксером или вручную до гладкой консистенции. Добавить два яйца, перемешать, затем всыпать муку 1,25 стакана и дрожжевую смесь. Массу перемешать до однородного состояния, обмять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5912,'Слепить булочки среднего размера, накрыть влажной тканью или смазанной растительным маслом пленкой, оставить. Тесто должно увеличиться в объеме в два раза. После выстойки булочки выпечь в течение 15 минут при температуре 180 градусов. Семгу нарезать кусочками и обжарить на сильном огне, переворачивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5912,'Для соуса растереть в ступке с солью половину зубчика очищенного чеснока, добавить отваренный картофель. Массу размять, влить по вкусу лимонный сок. Взбить венчиком, вливая понемногу оливковое масло. Можно добавить сыр, жирные сливки. Собрать бутерброды: разрезать готовые булочки по горизонтали и прослоить листьями свежего салата, рыбой, соусом. Проткнуть мини-бургеры с семгой деревянными палочками, закрепить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5913,'В небольшой кастрюле смешать сахарный песок, ванилин, сухое молоко. Небольшими порциями влить стакан молока, помешивать. Еще четвертую часть стакана молока отдельно смешать с картофельным крахмалом. Смесь в кастрюле довести до кипения, влить крахмальную смесь, перемешать до загустения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5913,'Смесь процедить через сито, накрыть пленкой и остудить. Взбить холодные сливки в пену. Смешать с «киселем» из молока. Массу перелить в формы, воткнуть палочки, заморозить в течение нескольких часов. Для глазури шоколад и сливочное масло смешать в равных пропорциях и прогреть на водяной бане до однородного состояния, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5913,'Немного остудить. Формочки с эскимо вынуть из морозильной камеры, окатить кипятком, достать мороженое. Быстро окунуть в теплую глазурь, подержать в руке для застывания. Снова положить эскимо в шоколадной глазури в морозилку на лист бумаги для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5914,'Клубни картофеля вымыть, тщательно очистить кожуру щеткой. Выложить на выстеленный пергаментом противень, в нескольких местах наколоть вилкой, полить маслом. Посолить, печь в течение 75–90 минут при температуре 175 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Далее добавить ваниль и перемешать, влить молоко – перемешать, всыпать мучную смесь – перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5914,'Смешать давленый чеснок, сметану, рубленую зелень лука и укропа, петрушки, соль и молотый перец. Влить Вустерский соус. Готовую, испеченную, картошку разрезать не до конца, наполнить сметанной начинкой. Ее можно еще посыпать свежей рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5915,'Свинину нарезать нетолстыми ломтиками, подготовленное к маринованию мясо выложить в глубокую керамическую посуду, добавить лавровый лист, нарезанные полукольцами лук и сладкий перец, залить квасом и выдержать на холоде 2 суток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5915,'Маринованную свинину вынуть из посуды, обсушить салфетками и обмазать кашицей из чеснока с солью, кусочки мяса обжаривать на решетке примерно 50-60 минут, периодически обливая выделившимся соком и топленым салом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5915,'Готовую буженину маринованную с луком в квасе украсить рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5916,'Помидоры одинакового размера и степени зрелости вымыть и вырезать плодоножку. На место плодоножки вставить по очищенному зубчику чеснока. Для рассола размешать в воде соль, сахарный песок, гвоздику, черный перец-горошек. Вскипятить в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5916,'Залить жидкостью помидоры, плотно уложенные в банке, на дно положить листья черной смородины. Добавить по чайной ложке уксусной эссенции, сверху–веточки укропа с семенами. Закрыть банки стерильными крышками, закатать. Остудить помидоры «Просто класс» в перевернутом положении, закутать в одеяло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5917,'Творог выложить в кастрюлю и размять вилкой. Влить куриные яйца, всыпать сахарный песок, перемешать. Всыпать пшеничную муку, снова перемешать. Из получившейся массы скатать небольшие шарики, обвалять и расплющить в муке. Выложить на разогретую сковороду с растительным маслом. Обжарить творожные сырники по две минуты с каждой стороны до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5918,'Поставить мед на водяную баню, растопить. Отдельно взбить в пену сырые яичные белки. Ввести в мед, перемешать деревянной ложкой до получения однородной консистенции, продолжать прогревать в течение 45 минут. Масса должна загустеть и посветлеть. Добавить обжаренный миндаль, нарезанную курагу, натертую цедру половины лимона. Продолжать варить и помешивать. Густую массу перелить в форму, выстеленную пергаментом или восковой бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5918,'Сверху нугу также закрыть бумагой, она не должна заветриться. Оставить массу на два часа или на всю ночь в сухом, проветриваемом помещении. Готовое торроне нарезать на длинные полоски, это нужно делать острым ножом. Обернуть сладость в пергамент, каждый кусочек отдельно. Хранить мягкую нугу с курагой и миндалем в сухом и прохладном месте, можно в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5919,'Сварить всмятку яйцо. Отдельно два сырых яйца взбить венчиком, можно использовать миксер, посолить, поперчить, добавить рубленую петрушку. Нарезать хлеб на брусочки, залить яичной массой. Застелить фольгой противень, смазать растительным маслом, выложить массу с гренками, посыпать тертым твердым сыром. Печь при температуре 180 градусов в течение пяти минут, гренки должны стать золотистого цвета. Подать гренки в теплом виде, с яйцом всмятку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5920,'Отварить картофель в «мундире», очистить, нарезать кубиками. Смешать кипяченую воду с уксусом и сахаром, замариновать репчатую луковицу небольшого размера.  Порезать филе сельди кубиками, выложить на нее нарезанный маринованный лук. Натереть морковь, перемешать с давленым чесноком. Свежие огурцы также нарезать кубиками. Все ингредиенты перемешать, украсить салат с сельдью и овощами нарезанным зеленым луком, листочками петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5921,'С белого батона снять корочку, она не понадобится, наломать мякиш кусочками, залить молоком, помять. Говядину или свинину вымыть, нарезать на кусочки и пропустить через мясорубку. Можно использовать то и другое мясо в равных пропорциях. Готовый фарш посолить, поперчить, влить сырые яйца, размоченный батон, давленый чеснок. Массу хорошо перемешать. Сформовать котлеты, выложить на смазанный маслом или застеленный бумагой противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5927,'Соль и молотый перец – по вкусу. Всыпать пшеничную муку, перемешанную с разрыхлителем. Поставить в холод на полчаса. Противень покрыть пергаментом, выложить массу в виде оладий. Печь капустные оладьи при температуре 180 градусов в течение 20–25 минут, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11096,'Через полчаса положить тмин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5921,'Почистить и нарезать тонкими кружками луковицу, кружков должно быть столько же, сколько получилось котлет. Нарезать такое же количество кружков помидоров и сыра. Желательно, чтобы вся нарезка была примерно одного размера. Котлеты смазать соусом Кетчуп, выложить на каждую лук, смазать майонезом, затем помидор и снова майонез, сверху – сыр. Закуску поставить в духовку, печь котлеты из говядины под овощами в течение получаса при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5922,'Нежирную свинину нарезать небольшими кубиками, посолить солью с добавлением сухого чеснока или морской. Добавить гречневую крупу и жареные грибы, любую приправу. Залить массу двумя стаканами воды, перемешать. Все ингредиенты переложить в пакет для запекания, выложить на противень. Печь гречку со свининой на среднем огне в течение 40 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5923,'Растопить в кастрюле сливочное масло или маргарин. Разбавить его теплым молоком. Всыпать сухие дрожжи, сахарный песок, соль. Массу перемешать и дать постоять в течение пяти минут. Затем добавить просеянную пшеничную муку. Снова перемешать. Массу выложить на посыпанную мукой поверхность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5923,'Немного вымесить. Готовое тесто разделить на четыре части, каждую раскатать в прямоугольник. Разложить готовое картофельное пюре вдоль той стороны, которая длиннее, свернуть рулетом, защипать края. Разделать на пирожки ребром ладони, затем разрезать ножом. Выложить пирожки-малышки на противень, печь при температуре 180 градусов в течение 20–30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5924,'Смешать в чаше блендера свежую клубнику, натуральный йогурт, жирные сливки, сахарный песок, лимонный сок, приправить смесь щепоткой молотой корицы. Масса должна получиться однородной. Вылить смесь в форму для замораживания, поставить в морозильную камеру на два часа. Мороженое достать через два часа, оно не должно застыть полностью. Переложить в блендер, взбить, снова убрать клубничное мороженое в морозилку на два часа. Операцию повторить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Приготовить из мяса и шпика фарш, подлить немного воды, посолить, поперчить, добавить натертую на терке лимонную цедру, перемешать и деликатно взбить, готовый фарш охладить в течение 2 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Отварить замоченные грибы, мелко нарезать и поджарить на растительном масле вместе с луком и щепоткой молотой гвоздики, когда грибы немного остынут, приправить сливочным маслом и мелко нарубленной зеленью, присолить, тщательно перемешать полученный грибной фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Мясной фарш разделать на деревянной доске на небольшие порции, скатать из них шарики , затем на ладони сделать из них лепешки, положить в серединку каждой ложку грибной начинки, края мясной лепешки защипать и сформировать круглые тефтели.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Запанированные в муке тефтели подрумянить в растительном масле до образования корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Подготовить овощи для гарнира, картофельные дольки обжарить с луком до полуготовности, морковь нарезать кружочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'В сотейник или кастрюлю выложить тефтели, залить смесью из сметаны или разведенной томатной пасты с сахаром и перцем, на тефтели положить подготовленные картофель, морковь, лук, горошек и лавровый лист, тушить в течение 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5925,'Подавать тефтели «Российские» с грибами и гарниром со свежей зеленью, зеленым горошком и картофелем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5926,'Смешать в кастрюле сахарный песок и желатин. Влить полстакана белого вина, оставить для набухания на несколько минут. Долить в смесь остатки вина, перемешать, поставить на тихий огонь и довести до кипения, перемешать, варить на медленном огне в течение минуты или двух.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5926,'Массу снять с огня и остудить. Влить лимонный сок. Бананы очистить, нарезать кружками, выложить в формочки для кексов из силикона. Залить желатиновой массой, поставить в холод на два часа. Желе из белого вина должно полностью застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5927,'Тонко нарезать белокочанную капусту, опустить в кипящее молоко на несколько минут, она должна осесть. Нарезку отбросить на сито, остудить. Перемешать бланшированную капусту с сырым яйцом, сметаной, тертым твердым сыром, рубленой зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5960,'Подать котлеты из осетрины в панировке из грибного соуса с консервированным зеленым горошком, украсить веточками петрушки и ломтиками лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5928,'Готовое слоеное тесто без дрожжей нарезать полосками шириной в один-два сантиметра. Выложить на противень, запечь до светло-коричневой корочки при температуре 200–220 градусов. Остудить при комнатной температуре. Несколько полосок отложить для украшения. Мягкое сливочное масло комнатной температуры взбить в миксере, влить сгущенное молоко, еще раз взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5928,'Влить коньяк, снова взбить. На пищевую пленку выложить слоями «палочки» из теста и крем. Остатками крема покрыть готовый торт со всех сторон. Пленку завернуть так, чтобы десерт принял форму полена. Поставить на ночь в холодильник. Оставленные «палочки» измельчить в крошку, обсыпать охлажденный торт. Выложить торт «Слоеное полено» на блюдо, подать, нарезав на кусочки и украсив на свой вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5929,'Смешать молоко, просеянную муку, сахар, щепотку соли и куркуму. В массе не должно быть комочков. Жарить блины на топленом масле, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5930,'Филе курицы тщательно вымыть, удалить все пленки и жилы, обсушить с помощью бумажного полотенца. Грудки хорошо обвалять в соли крупного помола или морской. Добавить специи: хмели – сунели, кориандр, смесь молотых перцев, паприку. Натертое специями мясо положить в лоток или кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5930,'Придавить грузом на 4–5 часов. Мясо обсушить полотенцем, развесить для просушивания. Через сутки продукт попробовать на вкус, если жесткость нормальная–снять и нарезать острым ножом или слайсером на тонкие пластинки. Подать карпаччо из куриного филе с рукколой, дольками лимона, посыпать тонко нарезанным сыром пармезан.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5931,'Луковую шелуху залить водой, добавить целую неочищенную луковицу, соль, молотый кардамон, перец-горошек. Смесь поставить на огонь, довести до кипения, варить пять минут. Нарезать свиное сало кусками по пять сантиметров шириной. Положить в рассол, варить в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5931,'Мелко нарезать или натереть чеснок. Перемешать черный и красный молотый перец, красный перец кусочками, добавить тмин. Сало вынуть из кастрюли, остудить, натереть чесноком и специями, можно дополнительно нашпиговать чесноком. Завернуть домашнее сало в фольгу, положить в морозильную камеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5932,'Просеять пшеничную муку. Взбить сырые яйца, перемешать со сметаной, мукой и пищевой содой. Добавить черный молотый перец и розмарин. Спелые помидоры разрезать пополам, удалить семенные камеры, мякоть нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5932,'Такими же кубиками нарезать ветчину, твердый сыр, оливки без косточек. Все ингредиенты добавить в тесто и перемешать. Вылить тесто с начинкой в форму, печь при температуре 180 градусов в течение 45 минут. Пирог с ветчиной и оливками проверить на готовность с помощью зубочистки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5933,'Перемешать манку с кефиром, крупу добавлять порциями. Оставить на полчаса для набухания. Отдельно взбить яйца с сахарным песком, всыпать пищевую соду, ванилин, растопленное сливочное масло или маргарин. Обе смеси соединить, всыпать пшеничную муку, массу перемешать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5933,'Две формы для выпечки смазать растительным или сливочным маслом, присыпать манной крупой. Разлить тесто, печь в духовке при средней температуре в течение 20 минут, затем огонь убавить и допечь пироги еще в течение 20 минут. Готовые манники на кефире можно смазать сливочным маслом и посыпать сахарной пудрой. Подать со сметаной или сгущенным молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5934,'Отварить картофель, морковь, куриные яйца. Натереть. Брокколи варить не больше трех-четырех минут. Для соуса нарезать соломкой ветчину или отваренное мясо, натереть соленые огурцы. Все ингредиенты смешать и заправить майонезом. Отваренные овощи выложить на блюдо слоями: картофель, морковь, яйца, брокколи, слои салата «Адвент» промазать соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5935,'Нарезать орехи макадамия, маршмеллоу, фруктовое желе разного цвета. Добавить обжаренные фисташки, сушеную клюкву, перемешать. Белый шоколад поломать на кусочки, прогреть в микроволновой печи в течение 45–50 секунд, перемешать, прогревать еще полминуты, снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5935,'Залить шоколадом орехово-фруктовую смесь, перемешанную массу вылить в форму, разровнять. Поставить десерт «Каменистая дорога» в холодильник на два часа в холодильник, можно на ночь. Нарезать любыми фигурками, их можно хранить в течение двух недель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11120,'Удалить плодоножки и остатки соцветия.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5936,'Баклажаны нарезать тонкими ломтиками, посыпать солью и оставить для удаления горечи. Тонко нарезать помидоры такими же ломтиками. Измельчить очищенный чеснок, петрушку, перец чили, добавить соль, черный молотый перец, растительное масло. Массу растереть с помощью вилки. Яйцо взбить с молоком, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5936,'Пластинки баклажана обмакивать в яичную смесь и обжаривать с двух сторон на разогретом растительном масле, выложить на тарелку. Горячие кружки смазать чесночной массой, положить по ломтику помидора, сверху другой баклажан, повторить слои несколько раз. Готовые острые баклажаны должны постоять для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5937,'Индюшиную голень, куриную грудку и молодую курицу хорошо вымочить в холодной воде, положить в кастрюлю.  Добавить корень петрушки, крупную луковицу, лавровый лист–по вкусу. Довести до кипения, огонь убавить до минимального, варить около часа. Пену снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5937,'Через час вынуть грудку, еще через час–курицу, индюшачье мясо варить еще два часа. Соль и перец–по вкусу. Бульон остудить. Отварить куриные яйца, очистить и разрезать пополам. Также отварить морковь и нарезать «звездочками» или любыми другими фигурками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5937,'Разобрать руками и нарезать мясные продукты. На дно каждой формочки для холодца положить по половинке яйца, срез должен быть внизу. Затем–морковь и мясо. Залить холодец из курицы бульоном, остудить при комнатной температуре, окончательно дать застыть в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5938,'Очистить луковицу, нарезать кольцами, жарить на сковороде в течение пяти минут. Вымыть филе говядины, нарезать тонкими полосками, жарить вместе с луком 15 минут, затем посолить по вкусу, добавить рубленый чеснок, куркуму, молотый красный перец, жарить еще 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5938,'Вымыть сливы, разрезать на половинки, вынуть косточки, разрезать еще раз пополам. Порубить зелень петрушки. То и другое выложить к мясу с луком, влить йогурт, тушить 20 минут. Добавить к говядине со сливами консервированный зеленый горошек и еще немного прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5939,'Свежие огурцы хорошо вымыть, разрезать вдоль. Для маринада смешать сахар, рафинированное растительное масло, уксус, все ингредиенты – в равных пропорциях. Всыпать соль, молотый черный перец, давленый чеснок. Залить огурцы, дать заготовке постоять в течение полутора часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5939,'Плотно сложить огурцы в банки в вертикальном положении. Залить маринадом, простерилизовать полулитровые банки в течение 15 минут, литровые –20 минут. Закатать, остудить в перевернутом виде. Хранить нарезанные огурцы в прохладном месте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5940,'Смешать свежие дрожжи с теплым молоком и сахарным песком. Поставить в теплое место на 20 минут. Добавить взбитое яйцо и теплое картофельное пюре, ванильный сахар из пакетика. Ингредиенты перемешать. Всыпать в массу половину нормы просеянной пшеничной муки, соль, тертый мускатный орех, вымешать. Положить в тесто мягкое сливочное масло, подсыпать остатки муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5940,'Масса должна получиться мягкой и чуть липкой. Тесто поставить в тепло на час или полтора, объем должен увеличиться в два раза. Обмять, вымесить, раскатать в пласт толщиной один сантиметр, нарезать квадратами небольшого размера. Дать постоять еще в течение получаса. Обжарить картофельные пышки в большом количестве растительного масла, они должны хорошо зарумяниться. Перед подачей посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5941,'Замочить и отжать батон, пропустить его с луком и свежим картофелем через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5941,'Добавить к массе фарш и яйцо, посолить, поперчить, все хорошо взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5941,'Сформовать котлеты, запанировать в сухарях, обжарить котлеты из мясного фарша «Русские» на сильно разогретом растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5942,'Крупные куски говядины положить в кастрюлю, добавить нарезанную морковь, луковицу, соль и лавровый лист. Залить водой, довести до кипения, огонь уменьшить и варить еще полтора-два часа до готовности мяса, под крышкой. Готовое, мягкое, мясо охладить в бульоне в течение получаса. Вынуть, остудить, порвать на волокна руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6017,'Охлажденное тесто раскатать в тонкий пласт 3–4 мм, выложить в разъемную форму. Сформовать бортики высотой 3–4 см, края ровно обрезать. На дно пирога выложить обжаренный лук, затем сыр, ветчину, зеленый лук, орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5942,'Нарезать полукольцами большую луковицу, сладкий перец желтого, красного и зеленого цвета – полосками. Жарить на растительном масле 10 минут до мягкости овощей. Добавить рубленый чеснок, острый перец чили, молотую корицу и соль по вкусу, прогреть все вместе полминуты. Добавить томаты в собственном соку, размять ложкой, тушить еще пять минут. В смесь влить два стакана говяжьего бульона, положить мясо, тушить говядину 10 минут, помешивать. При подаче украсить блюдо зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5943,'Свиную вырезку нарезать на куски толщиной в сантиметр, посолить, поперчить по вкусу и хорошо отбить. Для начинки нарезать мелкими кубиками шампиньоны и очищенный от семян болгарский перец. Обжарить на сковороде со сливочным маслом нарезанный кубиками репчатый лук, добавить грибы и перец, посолить, поперчить. Через пять минут добавить заранее отваренный рис, измельченную зелень петрушки и укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5943,'Перемешать. На каждый отбитый кусок мяса выложить начинку, свернуть рулетом и заколоть зубочистками, можно обвязать нитками. Обжарить крученики из свинины на растительном масле, в процессе приготовления огонь постепенно уменьшать. Блюдо на несколько минут поставить в духовку. При подаче нитки или зубочистки убрать, украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5944,'Для теста развести дрожжи в теплой воде. Смешать муку для пиццы и пшеничную, просеять. Влить оливковое масло, посолить. Размять в гладкое тесто, доливая постепенно теплую воду и разведенные дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5944,'Массу разделить пополам, скатать в три «колобка», подержать в теплом месте в течение часа, накрыть полотенцем. Приготовить соус. Промыть и обсушить зеленый базилик, мелко нарезать. С помощью блендера смешать томаты в собственном соку, посолить, добавить базилик, орегано и оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5944,'Тесто раскатать на столе, смазать приготовленным соусом, посыпать тертым сыром. Выложить колбасу пепперони, нарезанную тонкими кружочками. Выпечь до готовности. Порезать пиццу «Пепперони» на восемь частей, украсить листочками свежего базилика, края смазать оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5945,'Немного нагреть молоко, развести в нем дрожжи, дать постоять 10 минут. Добавить куриное яйцо, сахарный песок, соль, всыпать муку. Перемешать, поставить в тепло на час, емкость накрыть крышкой или тканью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5945,'Силиконовые формочки или противень смазать растительным маслом, выложить тесто, затем по чайной ложке любого густого варенья или джема, снова тесто. Печь «слоеные» оладьи в духовке при 180 градусах, в течение 15 минут. Готовые оладьи с джемом смазать растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5946,'Нарезать кубиками репчатый лук, потушить на сливочном масле вместе с хорошо промытым шпинатом. Отварить куриные яйца, очистить, разрезать пополам, вынуть желток. Измельчить его вместе с твердым сыром, луковой обжаркой, посолить, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5946,'Консервированные очищенные помидоры измельчить в блендере, вылить в прямоугольную форму для выпечки, лучше из силикона. Нафаршировать яйца сырной массой со шпинатом, положить в форму, печь при температуре 185 градусов в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5947,'Отварить и остудить куриное филе, клубни картофеля, куриные яйца. Мелко нарезать репчатый лук, залить винным уксусом. Мелко нарезать курицу и консервированные шампиньоны. Картофель, свежие или маринованные огурцы, яйца и твердый сыр натереть. Выложить ингредиенты салата «Курочка под шубой» слоями, промазать майонезом. Порядок слоев: куриное мясо, огурцы, картофель, грибы, лук, яйца, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5948,'Отварить очищенные клубни картофеля, куриные яйца и морковь. Продукты очистить и нарезать кубиками. Также нарезать кубиками соленые огурцы, репчатый лук и свежие шампиньоны. Лук и грибы обжарить вместе на растительном масле. Все ингредиенты выложить в салатницу, добавить консервированный зеленый горошек, заправить салат «Оливье» майонезом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5949,'Морковь очистить и натереть. Репчатый лук нарезать полукольцами. Оба ингредиента потушить в небольшом количестве воды. Бланшировать в кипятке в течение двух минут спелый помидор, снять кожицу. Плод нарезать кружками. Сладкий болгарский перец очистить от семян и нарезать в виде соломки. Натереть маложирный твердый сыр. Куриные грудки отбить, посолить и поперчить по вкусу, обвалять в муке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5949,'Выложить куриные отбивные на противень, сверху–тушеный лук и морковь, затем слой болгарского перца, помидор, полить натуральным йогуртом. Маслины разрезать пополам, выложить на йогурт, посыпать тертым сыром. На противень налить немного воды или бульона, выложить мясо, печь куриные отбивные под овощами и сыром при 200 градусах до готовности. Подать с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5950,'Тушку курицы положить на брюшко, надрезать по всей длине позвоночника, только кожу и тонкий слой мяса. Кожу держать пальцами, острым ножом надрезать мякоть вдоль ребер до бедренного сустава. Отделить бедренную кость от остальной части костяка. Таким же образом отделить сустав крыла. То же самое проделать с другой стороны. Остов отделить от килевой части тушки и выдернуть. Освободить от филе киль, вырезать рогаткообразную кость в передней части курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5950,'Вывернуть бедра, удалить бедренную кость. Удалить лопатки, вынуть крылья. Все извлеченные кости использовать для варки бульона. Почти полностью освобожденную от костей тушку посолить и поперчить изнутри и снаружи, дать постоять в течение часа. Для приготовления начинки измельчить ломтики белого хлеба, свинину, репчатый лук. Это можно сделать как вручную, так и с помощью кухонного комбайна. Натереть сыр и замороженное сливочное масло, добавить рубленую зелень, соль, молотый перец, тертый мускатный орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5950,'Сырое яйцо взбить в пену, влить в начинку, осторожно перемешать. Переложить начинку в куриную тушку, зашить ниткой. Гузку удалить или заправить внутрь курицы. В форму для запекания влить несколько ложек оливкового масла, всыпать сухой шалфей. Тушку положить грудкой вниз. Печь фаршированную курицу по-тоскански при температуре 180 градусов до образования румяной корочки. ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5951,'Поставить варить в подсоленной воде утку, периодически снимая пену, нарезать морковь и картофель кубиками, нашинковать мелко лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5951,'Добавить за 30 минут до готовности мяса порезанные овощи, измельченные помидоры и сметану, дать закипеть, посолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5951,'Суп из утки по-домашнему разлить по тарелкам и украсить измельченной петрушкой, добавить нарезанное филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5952,'Измельчить ванильное печенье, порубить миндаль, смешать оба продукта со сливочным маслом или маргарином комнатной температуры. Выложить в форму для выпекания. Смешать сгущенное молоко, свежую или размороженную малину, апельсиновый ликер, сок лимона. Отдельно взбить сливки, соединить с ягодной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5952,'Вылить в форму на печенье. Поставить в холодильник на два часа. Украсить свежими ягодами, листочками мяты, взбитыми сливками, шоколадными фигурками. Перед подачей малиновый десерт подержать 15 минут при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5953,'Развести дрожжи в молоке, добавить сахарный песок, муку, соль, почти всё сливочное масло, оставить кусочек для смазывания. Вымесить мягкое тесто, оно не должно приставать к рукам. Накрыть тканью, оставить на час. Сухофрукты, изюм, сушеную клюкву, залить кипятком, через две минуты отцедить. Добавить цукаты, приготовленные из лимона и апельсина, залить ромом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5953,'Перемешать, оставить на час. Подошедшее тесто перемешать с сухофруктами и молотым миндалем, имбирем, мускатом, корицей, кардамоном. Выложить массу на присыпанную мукой поверхность, раскатать и придать форму штоллена, то есть свернуть в три слоя. Переложить тесто на сухой противень, накрыть полотенцем еще на 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5953,'Печь при температуре 190 градусов в течение 60–70 минут, пирог должен зарумяниться. Вынуть выпечку, немного остудить и натереть оставшимся сливочным маслом, сразу же посыпать сахарной пудрой. Остудить рождественский штоллен, хранить в холодильнике или в прохладном месте, можно завернуть в фольгу или в пергамент.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5954,'Очистить клубни крупного картофеля, натереть половину на крупной, а половину – на мелкой терке. Перемешать обе массы, соль – по вкусу. Соединить свиной фарш с яйцом, нарезанной морковью и репчатым луком. Посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5967,'Вместо ветчины можно брать сыр, только добавлять его уже в практически готовую начинку. Раскатать из созревшего теста лепешки, положить начинку, защипать, слегка раскатать. Жарить сырные лепешки с грибами и ветчиной в сковороде в разогретом масле при среднем нагреве под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5954,'Взять в руку часть картофельной массы, отжать, сделать лепешку, положить на середину начинку. Сверху накрыть картошкой, сформовать зразы продолговатой формы. Лучше это делать мокрыми руками. Обжарить зразы из картофеля с мясным фаршем на масле до золотистого цвета. В дальнейшем блюдо можно разогреть в микроволновой печи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5955,'Взбить сырые белки в крепкую пену, постепенно всыпать сахарный песок, продолжать взбивать. Влить сок лимона. На бумаге для выпечки начертить два круга среднего размера, выложить безе. Выпечь два коржа при температуре 110 градусов в течение 2,5–3 часов. Остудить в духовке. Коржи подровнять по бокам, крошку не выбрасывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5955,'Отдельно, на водяной бане, растопить темный шоколад, облить им коржи. Для приготовления крема сварить карамель из сахара и небольшого количества воды, жидкость в процессе варки должна приобрести золотисто-коричневый оттенок. Немного остудить. Взбить жирные сливки со сгущенным молоком и пудингом из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5955,'Постепенно влить карамель, массу перемешивать лопаткой. Нанести на первый корж половину крема, накрыть вторым, смазать верх и бока. Верх торта-безе с карамелью посыпать крошкой, оставшейся от обрезки коржей, украсить свежей клубникой, целой или порезать на дольки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5956,'Размять консервированную рыбу, лучше всего подходит тунец. Отварить, очистить, измельчить куриные яйца. Нарезать маринованные огурцы, натереть морковь, порубить пучок зеленого лука. Массу перемешать, всыпать молотые сухари, укроп. Заправить салат «Рыбный» майонезом и сразу подать, пока не размокли сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5957,'Смешать кефир, сметану, майонез, вбить сырые куриные яйца, всыпать соль и пищевую соду, пшеничную муку, её нужно просеять. Масса должна получиться средней густоты, как для оладий. Половину теста выложить в форму, поверх–тонко нарезанный картофель или обжаренные грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5957,'Следующий слой–размятые консервы из рыбы, жидкость слить. Вместо рыбы можно положить отваренное рубленое яйцо с зеленым луком. Вылить на начинку вторую половину теста, равномерно размазать ложкой. Печь пирог «Быстрый и вкусный» при температуре 160 – 180 градусов до зарумянивания. Подавать к столу в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5958,'Нарезать плоды баклажана кружочками толщиной 8 мм. Жарить на растительном масле с двух сторон. Помидоры обдать кипятком и очистить от кожицы. Мякоть натереть или пропустить через мясорубку. Очистить от семенных камер сладкий болгарский перец, каждый разрезать на 6 – 8 частей. Репчатый лук очистить и также разрезать на 6 – 8 частей. Обжарить на тихом огне, добавить перец, жарить еще 8 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5958,'К обжарке добавить помидоры, потушить всё вместе еще 5 – 7 минут. На дно формы для запекания выложить баклажаны, посолить и поперчить по вкусу, посыпать рубленым чесноком, выложить слой овощной заливки. Слои повторять, пока не закончатся продукты. Тушить блюдо под крышкой на тихом огне в течение 8 – 10 минут. При подаче баклажаны с овощами в томатном соусе посыпать листиками свежего базилика или укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5959,'Свеклу очистить, нарезать соломкой и посолить. Добавить уксус, перемешать. Положить массу в посуду для варки супа, добавить жир, собранный с предварительно сваренного мясного бульона, томатную пасту, сахарный песок, соль, немного муки, влить еще немного уксуса и тушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5959,'Морковь, петрушку и лук нарезать соломкой, спассеровать на столовом маргарине. В кипящий бульон положить сырой нарезанный картофель, добавить тушеную свеклу, пассеровку, варить борщ до готовности. За 5–10 минут до окончания варки в зеленый борщ положить нарезанный щавель, шпинат, зеленый лук, специи–по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5960,'Нарезать осетрину ломтиками по 1,5-2 см, разложить в ряд на глубокой сковороде, добавить полстакана бульона, тушить под крышкой при слабом нагреве до готовности, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5960,'Отварить грибы до мягкости, нарезать на небольшие кусочки, потушить в масле (1 ч.л.).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5960,'Взбить муку с маслом, добавить горячий бульон  из рыбы, грибы, влить сливки, варить при помешивании до сгущения соуса, подсолить, поперчить, заправить лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5960,'Покрыть остывшую рыбу густо соусом, поставить на холод и дать застыть, куски осетрины в застывшем соусе запанировать в крошках хлеба, подрумянить во фритюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5961,'Для приготовления дипа смешать майонез с соусом чили, мелко нарубленным репчатым луком, нарезанным сельдереем. Влить по вкусу лимонный сок. Массу взбить венчиком. Промыть очищенные тигровые креветки, обсушить с помощью бумажного полотенца. Перемешать несладкую кокосовую стружку с панировочными сухарями. Взбить сырые куриные яйца с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5961,'В казане или другой толстостенной посуде раскалить растительное масло. Креветки попеременно обмакивать в яичную смесь и обваливать в панировке, снова в яйце и в панировке. Обжарить с обеих сторон до золотистой корочки. Чтобы удалить лишний жир – нужно выложить обжаренные креветки в кокосовой темпуре на бумажное полотенце. Подать с соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5962,'Вымыть кабачки, обсушить, нарезать кружками. Посыпать солью и дать постоять, выделившуюся жидкость слить. Обжарить с двух сторон до готовности, выложить на бумажные салфетки, дать впитаться лишнему жиру. Отварить картофель в «мундире», остудить. Клубни очистить и нарезать кубиками. Порубить чеснок, соленые огурцы нарезать полукружьями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5962,'Натереть морковь, обжарить с чесноком до готовности. Порубить зелень петрушки, добавить в обжарку, посолить по вкусу. Для формирования «тортиков» понадобятся глубокие пиалы. Их нужно застелить пищевой пленкой, на дно выложить морковную обжарку, полить майонезом. Следующий слой – кабачки, кружки плотно прижать ко дну и стенкам формочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5962,'На кабачки – морковь, майонез, картошка, посолить, чеснок, пропущенный через пресс. Далее – майонез, огурцы, майонез, кабачки, чеснок, кабачки. Массу хорошо прижать, закрыть пищевой пленкой и поставить в холодильник для пропитывания на час-полтора. Подать кабачковые тортики, аккуратно перевернув на тарелку, пленку снять. Украсить «тортики» зеленью петрушки и помидорами черри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5963,'Капусту разобрать на соцветия, отварить до мягкости. При закипании воды немного подсолить. Приготовить кляр из молока с мукой и яйцом. Соцветия обмакнуть в массу и обжарить со всех сторон на растительном масле до золотистого цвета. Выложить цветную капусту в кляре на блюдо, украсить майонезом, посыпать зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5964,'Баклажан вымыть, нарезать кружками, положить в емкость вместе с растительным маслом, нашинкованным укропом, пропущенным через пресс чесноком. Посолить по вкусу, перемешать. Нарезать помидор ломтиками, натереть твердый сыр. Смазать форму растопленным сливочным маслом, посыпать панировочными сухарями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5964,'Выложить слой баклажан, затем помидоры, полить майонезом. Слои повторить в этом же порядке, посыпать сыром. Печь баклажаны с помидорами при температуре 200 градусов в течение 20–25 минут. Блюдо остудить, разрезать на порционные куски, подать с веточками зеленого укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5965,'Клубни картофеля, примерно одинакового размера, вымыть, порезать на дольки, чтобы получить 6-8 кусочков. Высыпать его в глубокую миску, облить маслом, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5965,'Насыпать в суповую тарелку специи, сухари, соль, хорошо перемешать, обвалять ломтики со всех сторон, разложить на противне, отправить в духовку с температурой чуть выше 200 градусов. Картофель в пикантной панировке будет готов примерно через 40 минут, когда покроется темной корочкой. За время запекания ломтики желательно несколько раз перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5966,'Порезать на маленькие кубики курицу и твердый сыр, перемешать, добавить порубленный чеснок, по паре столовых ложек густой сметаны, муки и крахмала, вбить яйца, приправить карри, подсолить, поперчить, убрать в холодильник минимум на час. Достать фарш, порезать ананасы, если используются колечки, кусочки можно сразу перемешать с фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5966,'Хорошо разогреть масло, куриные котлетки с ананасами и сыром обжарить с двух сторон, прикрыв крышкой. Получается вкусное блюдо с необычным вкусом, подавать можно и горячим и холодным с любым гарниром или использовать для приготовления бутербродов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5967,'Разболтать в чуть теплом кефире соду и соль с сахаром, всыпать измельченный сыр и муку, хорошо вымесить. Нашинковать помельче лук, обжарить до изменения цвета, добавить порезанные грибы и маленькие кубики ветчины (сосисок, колбасы), пару минут обжарить все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'В формы для кексов, смазанные сливочным маслом, разлить тесто и посыпать все холодной крошкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5968,'Растереть стружку маргарина с сахаром и яйцами, всыпать муку и разрыхлитель, перемешать до получения мягкого теста, убрать на пару часов в холодильник, достать разделить на одинаковые 4 колобка. Взбить белки с добавлением сахара и лимонной кислоты в устойчивые пики, орехи обжарить, удалить коричневую корочку, измельчить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5968,'Форму помазать маргарином, один колобок равномерно распределить по дну, смазать 1\4 белков, присыпать частью орехов, выпечь такие же 3 коржа, дать остыть. Сделать из мягкого, взбитого добела масла, и сгущенного молока, добавляя его небольшими порциями крем, разделить его на две порции: 2\3 и 1\3. В 1\3 всыпать орехи, добавить половину шоколадной пасты. Приготовить из шоколада, растопленного на водяной бане, сливок и масла шоколадную массу, разделить ее пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5968,'Теперь осталось только собрать пляцок «Ореховое наслаждение». Взять один корж, положить орехами вверх, покрыть равномерно половиной чистой шоколадной массы, поверх нанести масляный крем, накрыть другим коржом, перевернув его орехами вниз. нанести на него шоколадную массу с орехами. Далее положить следующий корж, но орехами наверх, смазать масляным кремом. Осталось уложить последний корж, орехи должны быть внизу, промазать остатками крема, щедро присыпать орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5969,'Прокрутить мясо с луком и хлебом, добавить желток, фарш подсолить, поперчить, перемешать. Для приготовления начинки смешать порубленное яйцо, натертый твердый сыр, нашинкованную петрушку, перья зеленого лука, раздавленный прессом чеснок, добавить масло, приправить специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5969,'Из сметаны с разрыхлителем и мукой приготовить кляр. Скатать из фарша колобок, сплюснуть его, положить по центру начинку, тщательно залепить края. Погрузить куриные зразы в кляр, зажарить в масле до желаемой корочки и полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5970,'Замочить хлеб в молоке и отжать, вбить в фарш яйцо, добавить измельченный лук, хлеб, сметану (1 ст.л.), присолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5970,'Сформовать котлеты, обвалять в муке и зарумянить в растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5970,'Переложить их в глубокую сковороду, залить сметаной и тушить под крышкой на слабом огне, подавать котлеты в соусе из сметаны можно будет через 15-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5971,'Измельчить  чеснок, перемешать с оливковым маслом, приправой для рыбы, лимонным соком, имбирем, цедрой. Добавить по вкусу в маринад перец, паприку, подсолить, поперчить. Подготовленного карпа хорошо натереть маринадом, поместить в пакет, держать сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5971,'Уложит рыбу на противень, выпекать пастрому из карпа в духовке при 220 градусах около получаса. В процессе запекания карпа надо перевернуть, чтобы зажаристая корочка образовалась на обеих сторонах тушки, подавать блюдо с дольками лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5972,'Картофель хорошо помыть под проточной водой щеточкой, поставить варить в подсоленной воде. Перемешать сливочное масло, сметану, тертый сыр и чеснок, приправить солью и перцем, хорошо перемешать. Включить и прогреть духовку до 200 градусов. Клубни разделить вдоль, промазать маслом, разложить чесночно-сырный картофель на противне, поставить на четверть часа в уже прогретую духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5973,'Сформовать и зажарить котлетки как обычно, сложить в глубокую форму. Мелко нашинковать лук, крупно натереть морковь, порезать консервированные грибы, сухие измельчить блендером. Разогреть масло, обжарить до изменения цвета лук, всыпать морковь, кусочки грибов, добавить кетчуп, хорошую сметану, сухие грибы, протушить все вместе минут 5. За это время разболтать в стакане теплой воды мясную подливу «Магги». Переложить зажарку на традиционные котлеты по-новому, залить подливкой, томить, прикрыв крышкой треть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5974,'Переложить морковку в дуршлаг, чуть промыть, слить фасоль, ветчину нашинковать соломкой, нашинковать мелко лук и обжарить, дать остыть. Болгарский перец желтого (но можно и другого) цвета порезать на тонкую соломку. Объединить все ингредиенты салата, всыпать сухарики, перемешать, приправить блюдо майонезом с небольшим количеством горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5975,'Взбить мелкий сахар с яйцами, прибавить сметану и распущенное масло, перемешать, всыпать муку с ванилином и разрыхлителем, вымесить тесто по густоте как сметана, всыпать порезанный чернослив. Включить прогреваться духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5975,'Подготовить форму, залить тестом, поставить минут на 40 в духовку. Приготовить для простого и вкусного торта любой крем по вкусу. Готовый бисквит аккуратно вынуть из формы, чуть остудить, разделить на два коржа, щедро смазать кремом, оформить верх, дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5976,'Отварное мясо порезать на кубики, обжарить нашинкованный лук, добавить нарезанные грибы. Выпечь на сухой сковороде из пары взбитых подсоленных белков и одного яйца блинчик, разрезать его на квадраты. Смешать все ингредиенты, заправить салат «Белковый» смесью из раздавленного чеснока, йогурта, перца, соли, осторожно перемешать, убрать на пару-тройку часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5977,'Пару небольших ананасов разделить на две половины, вынуть всю мякоть, порезать на кубики, также нарезать остальные фрукты, все перемешать, добавить обжаренные кусочки орехов. Дать половинкам ананаса без мякоти немного постоять и покрыться соком, положить в каждую по ложечке йогурта, разложить в них салат «Ананас», присыпать шоколадной стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5978,'Порезать рыбу на одинаковые кусочки, присолить, оставить в покое на пару часов. Перемешать муку и сухари, можно добавить любимые специи, обвалять со всех сторон кусочки, обжарить в хорошо разогретом масле. Натереть крупно морковь, луковицу нашинковать на полукольца, обжарить вместе с рыбой с добавлением сливочного масла, залить смесь сливками. Тушить минтай в сливках под овощами под крышкой на малом огне четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5979,'Для приготовления креветочно-грибного соуса распустить масло, спассировать на нем кусочки лука, добавить креветки или раковые шейки, любые (только не вешенку) нарезанные грибы, перемешать, обжарить все вместе. Влить в сковороду вино, уварить примерно до половины, чтобы соус стал густым, теперь добавить сливки, сдобрить перцем-солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5979,'Последний штрих – положить порезанные на кусочки мясистые помидоры. Смешать соус с отварными спагетти, тушить спагетти с креветками и грибами еще около 5 минут, подавать блюдо принято горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5980,'Очень аккуратно без разрывов снять с тушки кожу, оставить последний сустав на крыльях и на ногах. Нашинкованный лук тушить до мягкости в растительном масле, прокрутить мясо, сердечки и печень, перемешать с луком, яйцом, манкой и специями. Фарш тщательно вымешать, наполнить им шкуру, зашить все отверстия, слегка сплюснуть тушку, уложить в глубокую форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5980,'Запекать фаршированную курицу по-одесски около часа при температуре духовки 180 градусов, за 15-20 минут до окончания несколько раз полить ее выделившимся соком. Вынуть курицу из формы, переложить на блюдо, подать с любым гарниром горячей или охлажденной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5981,'Грудку порезать на квадратные кусочки, подсолить, перемешать с майонезом и соевым соусом, убрать часа на 4 в холодильник, а лучше оставить там ночевать. Нашинковать тонко лук, присыпать сахаром, слегка помять руками, побрызгать уксусом и соевым соусом, хорошо перемешать. Насадить кусочки мяса на шампуры, поджарить шашлычки «Якитория» на сковороде. Переложить шашлычки на блюдо, прикрыть маринованным луком, подать с большим количеством сезонных овощей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5982,'Взбить сахар и размягченное масло, вбить яйца, добавить творог с ванилином, соду, разрыхлитель и муку, вымесить тесто. Заполнить тестом круглую форму, испечь при температуре 180 градусов корж для торта–дабл, он будет готов через 40 минут, бисквит остудить, разрезать на две части. Взбить творог, сметану и сахар, промазать коржи торта кремом, оставить на пару-тройку часов в холодильнике для хорошей пропитки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Отварить мясо и почки (отдельно), дать остыть в бульоне, промыть почки водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Зажарить на масле мелко нашинкованный лук, добавить пасту и немного прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Почистить огурцы и нарезать соломкой, припустить до мягкости на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Нарезать брусочками мясо, почки и чуть их обжарить, смешать с порезанной ветчиной, сосисками, положить маслины или оливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5983,'Переложить все в кастрюлю, добавить лук, огурцы, залить бульоном, нагреть до кипения, посолить, поперчить, бросить лавровый лист, проварить солянку 5 минут на медленном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7760,'Говяжье мясо порезать на порционные куски, положить их в кипящую воду на 1-1,5 часа и приготовить бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5985,'Обмыть лимоны щеткой в кипятке, порезать на ломтики, удалить косточки. Смешать паприку с солью, пересыпать кусочки лимона, добавить нашинкованный чеснок и по желанию другие приправы, хорошо перемешать, дать постоять около часа, чтобы лимоны пропитались.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5985,'Заполнить лимонами банку, утрамбовать залить соком, а сверху на сантиметр – оливковым маслом, закрыть крышкой, дать квашеным лимонам с чесноком постоять 8-10 дней, хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5986,'Порезать на куски довольно крупного карпа, подсолить, присыпать перцем, уложить в сотейник, залить уксусом, положить бутоны гвоздики, дать постоять полчаса. Влить ложку масла, добавить сухари и пиво, варить карпа по-еврейски до полной готовности, в конце положить лимонную цедру и чуть сахара, при подаче полить рыбу соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5987,'Все ингредиенты для теста тщательно перемешать, до образовании мягкой массы. Творог протереть до однородной массы, вбить яйцо, всыпать нашинкованный мелко укроп, чуть подсолить, перемешать. Растянуть тесто в продолговатый батон, разрезать примерно на 12 кусочков, из каждого раскатать по лепешке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5987,'На половину лепешки уложить начинку, прикрыть второй, края защипать. Обжарить самые быстрые пирожки в хорошо разогретом масле до образования хрустящей корочки аппетитного соломенного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5988,'Обжарить муку с маслом до кремового цвета, молоко довести до кипения, тонкой струйкой, помешивая влить к муке, уварить соус до густоты, заправить его мускатным орехом, подсолить, поперчить. Всыпать сырную стружку, перемешать, убрать сковороду с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5988,'Взбить белки с небольшим количеством соли, желтки по одному вмешать в соус, добавить белки, аккуратно перемешать. Формочки чуть смазать маслом, притрусить мукой, наполнить сырной массой, но не полностью: готовое суфле поднимется. Выпекать сырное суфле в духовке около трети часа при нагреве 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5989,'Филе сварить в подсоленной воде (не переваривать иначе мясо будет суховатым), дать остыть, лучше прямо в бульоне, чтобы не заветривалось, порезать на кубики.  Грибы порезать на ломтики, зажарить до золотистости, открыть ананасы, сцедить, измельчить, как и курицу. Крупно потереть сыр, порубить зелень кинзы, все перемешать, всыпать в салат «Сытый кум», обжаренные орехи без шелухи, приправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5990,'Порезать на куски весь сыр, достать из холодильника яйца, взбить с небольшим количеством соли, насыпать в два блюдца муку и сухари. Начинать панировать сыры с муки, но голландский предварительно обмакнуть в яйцо, далее для остальных яйцо, сухари, снова яйцо и сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5990,'Растопить и нагреть сливочное масло, но лучше готовить жареный сыр на топленом масле, осторожно, чтобы не повредить панировку обжарить брусочки со всех сторон. Есть блюдо обязательно горячим, можно дополнить измельченной зеленью, а любители необычных вкусов могут попробовать его с брусничным вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5991,'Развернуть лаваш, листы смазать фаршем, оставить в покое минут на 15, тогда лаваш при сворачивании не прорвется, а будет эластичным. Взболтать яйца с добавлением майонеза или сметаны, кетчупом и специями, подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5991,'Переложить рулеты в промазанную маслом форму, залить полученной смесью, она должна прикрывать пирог «Лаваш в заливке» с мясным фаршем минимум на 1,5 сантиметра или чуть выше. Поставить на полчаса в духовку, можно готовить блюдо и в мультиварке — час в режиме выпечка, минут за 5-7 до окончания присыпать натертым твердым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5992,'Нарезать мясо на полосы, измельчить сладкий перец, морковь, чеснок, сельдерей, лук. Из смеси муки с яйцами, приправленной перцем и солью приготовить кляр. Хорошо перемешать разбавленный ананасовый сироп и томатную пасту, сдобрить солью, перцем, довести до кипения. Мясо окунуть в кляр, обжарить в раскаленном масле до появления корочки и приятного запаха.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5992,'На другой сковороде обжарить до изменения цвета лук, затем всыпать чеснок с сельдереем, размешать. Добавить болгарский перец, морковку и ананасы, прожарить все вместе 3-4 минуты, объединить тушеные овощи с мясом, влить в сковороду соус. Говядина в кисло-сладком соусе будет готово минут через 10-15. Идеальным гарниром к блюду послужит рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Поставить в холодильник на ночь. При подаче на стол снять бортики.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5993,'Замесить из всех ингредиентов на молоке тесто, дать постоять 40 мин в тепле, затем обмять, сформовать небольшие шарики, переложить в форму. Нашинковать зелень укропа, натереть в кашицу чеснок, всыпать розмарин, кинзу, майоран, залить маслом, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5993,'Обмазать будущие чесночные булочки этой пряной смесью и дать постоять треть часа для пропитки, затем отправить на 40 минут в духовой шкаф. Готовый хлеб пропитать чесночным маслом еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5994,'Почистить рыбу, аккуратно выпотрошить и вырезать жабры, тщательно промыть проточной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5994,'Положить в холодную воду, посолить, нагреть до кипени и проварить после еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5994,'Порезать крупно картофель, морковь – кубиками, высыпать все в кастрюлю и добавить очищенную головку лука целиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5994,'Заправить уху лавровым листом, горошками душистого перца, зеленью петрушки и целым черным перцем, залить водку, прикрыть крышкой и снять с плиты, дать настояться 15 минут, луковицу вынуть из кастрюли и выбросить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5994,'Перед подачей уху с водкой по-старорусски можно заправить оливками, украсить тонкими ломтиками лимона и посыпать зеленью укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5995,'Перемешать муку с яйцами, подогретым медом, содой, сахаром, молотой гвоздикой и корицей, вымесить пластичное тесто, раскатать в сантиметровый пласт. Вырезать формочками или рюмкой медовое печенье, переложить на противень промазанный маслом, выпечь до готовности, присыпать сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5996,'Залить 3 ст.л. желатина стаканом воды, другую часть желатина — 5 гр залить половиной стакана воды, дать постоять и хорошо набухнуть. Печенье измельчить в крошку блендером, тщательно перемешать с распущенным сливочным маслом. Выложить маслянистую массу в круглую форму, утрамбовать, поставить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5996,'Сложить в миску порезанные на кубики плоды киви, засыпать сахарным песком, влить лимонный сок, добавить большую порцию желатина, прогреть, помешивая на водяной бане до растворения сахара и желатина, дать остыть. Положить творог в чашу миксера, превратить в однородную массу без комочков, объединить со смесью киви и желатина, перемешать, добавить охлажденные и взбитые в крепкие пики сливки, хорошо все смешать.  Достать форму с основой, уложить на  нее творожную массу, поставить опять в холодильник на 4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5996,'Для украшения верха творожного торта с киви, можно приготовить желе. Для этого смешать меньшую часть желатина с парой ст.л. сахарного песка и ст.л. сока лимона, помешивая прогреть при слабом нагреве на водяной бане до исчезновения кусочков желатина, дать остыть. Порезать плоды киви на кусочки, уложить красиво поверх торта, вылить сверху желе, поставить застыть в холодильник, бока десерта обсыпать измельченными фисташковыми орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5997,'Для начинки натереть сыр, курицу мелко нарезать, добавить майонеза, перемешать. Из готового теста сформовать пирожки, запекать треть часа в духовке при температуре около 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5998,'Тщательно вымыть зелень, мелко нашинковать вместе с луком, капусту мелко нарезать. Перемешать кефир с растопленным маслом, всыпать сахар, вбить яйца, подсолить, перемешать. Окончательный штрих – засыпать в жидкую основу муку и разрыхлитель, очень тщательно перемешать до получения однородного теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5998,'Половину, а лучше чуть больше теста вылить в смазанную форму, сверху уложить начинку, залить остатками теста. Поставить пирог с капустой и зеленью в духовку с температурой около 200 градусов минут на 35-40, достать, прикрыть льняной тканью, дать немного остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (5999,'Сложить в блендер колбасу, сало, твердый сыр, чеснок, орехи, приправить перцем, взбить паштет в однородную массу. Порезать перец на маленькие кусочки, перемешать с паштетом, готовую массу переложить в банку, закрыть обязательно крышкой, до использования сохранять в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6000,'Овощи кроме редьки и лука натереть в разные емкости, облить соком лимона для сохранения яркого цвета, перемешать. Лук очень мелко порубить, яйца натереть по отдельности с редькой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6039,'Подготовить тушку стерляди, натереть смесью соли с перцем внутри и снаружи, убрать на холод на 60 минут, обжарить на сливочном масле лук, нарезанный полукольцами, включить на разогрев духовку до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6000,'Взять плоское блюдо, выложить салат «Витаминный тортик» послойно соблюдая следующий порядок: свекольный, луковый, яичный, майонезный, морковный, из редьки, яблочный, закончить майонезным. Для приготовления салата по вкусу можно использовать смесь майонеза со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6001,'Замесить из взбитой сгущенки, яиц и просеянной муки с разрыхлителем тесто, дать постоять в покое около четверти часа. Приготовить из сахарной пудры, взбитой со сливками до состояния крепких пиков крем, поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6001,'Застелить форму пергаментом, равномерно распределить по нему пару столовых ложек теста, испечь в прогретой духовке очень тонкий корж при температуре порядка 230 градусов понадобится всего около 5 минут. Приготовить еще 4 такие же коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6001,'Все коржи торта «Молочная девочка» промазать кремом, а верх и бока покрыть глазурью, для ее приготовления хорошо перемешать все ингредиенты, дать смеси закипеть, а потом остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6002,'Весь сахар взбить тщательно на большой скорости с белками до устойчивого состояния, отложить пару-тройку ложек массы, убрать в холодильник. Перевести блендер на малую скорость, положить желтки, муку, цедру, а в конце влить сок и масло. Тщательно, но аккуратно все перемешать, переложить форму, которую до этого промазать маслом или маргарином и притрусить мукой или манкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6002,'Выпекать апельсиновый бисквит около 50 минут, не превышая температуры в 180 градусов, первые треть часа, а лучше полчаса дверцу духового шкафа, во избежание  оседания бисквита, открывать не рекомендуется. Пока корж горячий промазать его белками, которые ждали своего часа в холодильнике, если есть желание, то бока десерта можно присыпать измельченными в крошку вафлями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6003,'Разболтать в сладкой теплой воде кусочек дрожжей, подождать образования на поверхности жидкости «шапки». Перемешать половину стакана масла с подсоленной мукой, соединить с активными дрожжами, вымесить тесто, которое не будет прилипать к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6003,'Отрезать порционные кусочки теста, формовать руками, смазанными маслом в шарики. Затем их расплющить, положить любую (сладкую, овощную, мясную) начинку. Тщательно залепить, слегка сдавить между ладонями, выпекать в сильно разогретом масле, шов должен быть внизу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6004,'Тщательно отделить белки, убрать их в холодильник, всыпать в желтки сахар, взбить на высоких оборотах миксера до образования массы с кремовым цветом. Включить для прогрева до 200 градусов духовку. Взбить хорошо охладившиеся белки в устойчивые мягкие пики, начинать процесс на низкой скорости вращения, доведя постепенно до максимальной. Всыпать небольшими порциями, не переставая взбивать, оставшийся сахар. В результате должна получиться крепкая   масса, не вытекающая из емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6004,'Соединить желтки и белки, осторожно снизу вверх перемешать, смешать какао и муку, просеять в миску, объединить с хорошо вымешанными яйцами. Долго лучше не мешать, иначе можно получить «низкий» бисквит. Переложить тесто в подготовленную и смазанную форму, поставить ее в прогретую духовку, температуру понизить на 30 градусов. Выпекать шоколадный бисквит чуть больше получаса, дверцу открывать не стоит – бисквит может «упасть».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6004,'Готовность коржа покажет тест на спичку, после втыкания в корж она должна оставаться сухой. Дать бисквиту остыть прямо в форме, аккуратно ножом отделить от краев формы, переложить на решетку, остудить полностью, разрезать на несколько коржей. Коржи пропитать сиропом, промазать любым кремом, верх можно оформить фруктами, орехами, взбитыми сливками или глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6005,'Положить масло в посуду с толстым дном (кастрюлю или сковороду), добавить желтки и молоко, готовить блюдо надо на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6005,'Поставить посуду с масляной смесью в большую кастрюлю с кипящей водой, довести, помешивая, соус до загустения, добавить уксус, сахар, молотый черный перец, посолить, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6005,'Если соус новгоpодский масляный получился слишком густым, то можно его разбавить небольшим количеством горячей водой, этот соус рекомендуется подавать к любым горячим овощным блюдам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6113,'Кусок мяса натереть подготовленной смесью из специй, со всех сторон промазать приготовленным маринадом, по всему куску уложить чесночные пластики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6006,'Клубни картофеля очистить и тонко нарезать. Форму смазать оливковым маслом, выложить слой картофеля, затем бекон, поперчить, посыпать тонко нарезанным репчатым луком. Следующий слой – картофельный, посолить, поперчить, намазать томатным соусом. Посыпать тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6006,'Вымыть и нарезать кружками кабачки цуккини, выложить на сыр, тоже посолить и поперчить, посыпать сухими травами базилика и майорана. Добавить полоски сладкого болгарского перца, картошку, соль, молотый перец, томатный соус, лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6006,'Верх запеканки выложить картофелем, еще полить томатным соусом и посыпать тертым твердым сыром. Накрыть фольгой, печь в течение 30–35 минут при температуре 220 градусов. Фольгу удалить, запеканку из картофеля с овощами и беконом подрумянить под грилем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6007,'Свиное мясо нарезать крупными кусочками. Перед приготовлением филе замариновать в любой подходящей смеси в течение 12 часов. Обжарить свинину до образования румяной корочки на растительном масле. Репчатый лук нарезать на кружочки, а потом на четвертинки, морковь натереть. Порезать очищенный картофель тонкими дольками, как для приготовления чипсов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6007,'На дно противня выложить сначала лук, затем морковь, картофель. Соль и перец–по вкусу, приправить сухим базиликом. На картофель – дольки шампиньонов, снова картофель. Посолить, поперчить, посыпать специями. Следующий слой – свинина. Готовый мясной бульон смешать с жиром, оставшимся от жарки мяса, полить блюдо. Вместо бульона можно взять разведенный кубик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6007,'Закрыть массу двумя слоями фольги, поставить в духовку на час, готовить при температуре 200 градусов. Фольгу снять, допечь еще в течение 10–15 минут. Готовое жаркое из свинины с шампиньонами посыпать рубленой зеленью укропа, петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6008,'Для приготовления меренги взбить белки, постепенно всыпать сахарную пудру. Для теста взбить сырые желтки со сметаной и разрыхлителем, масса должна значительно увеличиться в объеме. Добавить сливочное масло комнатной температуры, перемешать. Всыпать пшеничную муку, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6008,'Разделить тесто на десять кусочков, скатать «колобками» и поставить в холодильник на час или два. Охлажденное тесто тонко раскатать на присыпанной мукой поверхности, выложить на лепешку часть меренги, посыпать рублеными орехами. Поставить корж в разогретую до 180 градусов духовку на пять-шесть минут. Затем огонь убавить до 120 градусов, печь еще 10 – 12 минут. Выпечь все коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6008,'Для кофейного крема понадобится сливочное масло комнатной температуры, его надо взбить до пышного состояния. Смешать со сгущенным молоком, какао-порошком и растворенным, в небольшом количестве воды, кофе. Масса должна стать однородной. Убрать крем в холодильник. Готовые коржи остудить, промазать кофейным кремом, поставить в холодильник на два часа для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6008,'Для белкового крема всыпать в кастрюлю сахарную пудру, подлить воду, перемешать и прогреть до кипения. Сварить сироп. Капелька получившейся массы должна застывать в холодной воде. Отдельно взбить белки с небольшим количеством соли или лимонным соком. Продолжать взбивать, влить  белки горячий сироп, быстро взбить в течение двух минут. Готовый торт «Облако в штанах» украсить заварным кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6009,'Макароны гнезда выложить в сковороду с высокими бортиками, предварительно смазанную растительным маслом. Залить водой, она должна покрыть макароны. Довести до кипения под крышкой, убавить огонь, крышку приоткрыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6009,'Обжарить с рубленым луком и морковью мясной фарш. Влить томатный соус «Кетчуп», всыпать сушеные орегано и базилик, соль – по вкусу. Выложить почти готовые гнезда в форму для запекания, в середину – обжаренный фарш, посыпать тертым сыром, печь в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6010,'Сырые яйца взбить с сахарным песком, добавить разрыхлитель, просеянную пшеничную муку и взбить вручную или с помощью блендера. Противень застелить бумагой и смазать растительным маслом. Вылить тесто тонким слоем в 3–5 мм, запечь в течение 15 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6017,'Для заливки перемешать яйца со сметаной, взбить венчиком или вилкой. Залить смесью пирог. Поставить форму в духовку. Печь при температуре 180 градусов в течение 20 – 25 минут. Подать пирог с сыром бри и ветчиной в теплом или холодном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6010,'Готовый бисквит перевернуть на влажное кухонное полотенце, бумагу убрать, корж закрутить вместе с тканью в рулет. Остудить. Для приготовления крема смешать творог со сметаной, всыпать сахарный песок, ягоды пареной брусники. Массу взбить с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6010,'Осторожно раскрутить полотенце с рулетом, ткань убрать, смазать бисквит кремом, закрутить обратно. Готовую выпечку украсить остатками крема, тертым темным шоколадом. Дать бисквитному рулету постоять для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6011,'Растопить сливочное масло, добавить сгущенное молоко, кокосовую стружку, перемешать. Поставить готовый крем в холодильник на полчаса. Из охлажденного крема слепить шарики, в серединку положить целый фундук. Обвалять в стружке. Поставить конфеты «Рафаэлло» в холодильник еще на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6012,'Филе любой рыбы, например, лосося, хорошо вымыть, обсушить при помощи бумажных полотенец. Посолить и поперчить по вкусу, сбрызнуть лимонным соком, посыпать сушеным укропом, оставить на время для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6012,'Морковь, репчатый лук, баклажан почистить. Морковь натереть, лук нарезать полукольцами. Баклажан разрезать вдоль, посолить, оставить на время для удаления горечи, помыть под струей холодной воды, нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6012,'Обжарить на растительном масле морковь, добавить лук, затем баклажан. Посолить массу по вкусу, добавить смесь сушеных трав. Потомить овощи до готовности на тихом огне. Выложить обжарку на рыбу. Залить сметаной, печь рыбу под овощной шубой в разогретой духовке в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6013,'Взбить сырые яйца, кефир и масло, можно не солить, если сыр для начинки соленый. Для начинки натереть сыр, перемешать с рубленой зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6013,'Смазать маслом сковороду, выложить пять тонких лавашей один на другой, промазывая взбитой смесью. Затем – сырная начинка, сверху – пять оставшихся лавашей, каждый слой также промазать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6013,'Остатки кефирной массы вылить сверху, поставить на сильный огонь, блюдо закрыть крышкой. Когда нижняя часть пирога из лаваша прожарится – перевернуть и дожарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6014,'Муку просеять, желтки отдельно взбить венчиком. Влить желтки в муку, добавить сахарный песок, мягкое сливочное масло или маргарин, всыпать соль. Перемешать, в смесь можно добавить молотую корицу. Быстро замесить тесто, поставить в холод на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6014,'Охлажденное тесто нарезать на лепешки среднего размера. В каждой сделать углубление руками или с помощью донышка стаканчика или рюмки, формочкой. Посыпать рублеными орехами, залить густым вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6014,'Печь при 220 градусах в течение 15–20 минут, остудить песочное печенье с вареньем на противне. При подаче посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6015,'Сырое яйцо взбить с сахарным песком, щепоткой соли и ванилином. Добавить протертый творог, перемешать для однородности. Массу переложить в миску, добавить манку. Сформовать «колбаску» и нарезать её небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6015,'Довести воду до кипения, посолить, всыпать ленивые вареники, перемешать, дождаться, кода всплывут. Поварить еще две-три минуты и вынуть шумовкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6016,'Нарезать мелко зеленый лук, пересыпать в глубокую тарелку и помять до выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6016,'Покрошить туда слегка черствый черный хлеб, залить охлажденной кипяченой водой, добавить ложку подсолнечного масла, посолить и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6016,'Тюря на воде русская – прекрасное освежающее легкое блюдо для жаркой погоды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6017,'Для приготовления теста просеять пшеничную муку, добавить соль. Нарезать кубиками сливочное масло, положить в муку, растереть руками до состояния крошки. Нужно сделать это быстро, в течение нескольких минут. Влить ледяную воду, также быстро замесить тесто. Сформовать из массы шар, завернуть в пищевую пленку или полиэтилен, поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6017,'Для начинки нарезать репчатый лук на тонкие полукольца. Разогреть в сковороде сливочное масло, положить лук, жарить до зарумянивания. Сыр «Бри» нарезать ломтиками, ветчину – кубиками. Порубить перо зеленого лука, очищенные грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'Просеять пшеничную муку вместе с какао-порошком и разрыхлителем. Ввести в яичную смесь. Всыпать тертый темный шоколад, молотый миндальный орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6018,'Кефир смешать с манной крупой, дать настояться, манка должна набухнуть. Сырые куриные яйца разделить на белки и желтки, белки взбить в пену, можно с помощью миксера, в течение 8 – 10 минут. Желтки смешать с творогом, ванилином и разрыхлителем до однородного состояния, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6018,'Обе смеси соединить, немного взбить миксером. Добавить взбитые белки, аккуратно перемешать сверху вниз. Чашу мультиварки смазать сливочным маслом, вылить тесто, печь в течение часа, затем еще час подержать блюдо в режиме подогрева. Открыть, остудить. Перевернуть запеканку из творога на решетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6019,'Овсяные хлопья перемолоть в муку. Спелый банан очистить, размять вилкой или с помощью блендера до состояния пюре. Хорошо взбить сырое яйцо, добавить банановое пюре, просеянную пшеничную муку, молоко. Все взбить, тесто должно получиться полужидкой консистенции. Разогреть сковороду с антипригарным прикрытием, выпечь оладьи из банана без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6020,'Смешать творог, сырые куриные яйца, соду, погашенную уксусом, пшеничную муку, подсолнечное масло. Тесто раскатать, выложить мясной фарш со специями. Скрутить в трубочку, нарезать на кусочки, толщиной в  1 см. Обжарить творожные шанежки на сковороде с большим количеством растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6021,'Мясо нарезать на небольшие кусочки. Лук нарезать полукольцами, сладкий болгарский перец – соломкой. Разогреть в толстостенной посуде растительное масло. На сильном огне обжарить мясо тремя-четырьмя порциями до румяной корочки. Выложить на тарелку. Огонь уменьшить, положить в кастрюлю лук, жарить в течение пяти  минут, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6021,'В кастрюлю положить обжаренное мясо, предварительно размятые консервированные томаты в собственном соку вместе с жидкостью. Посолить и поперчить по вкусу. Влить стакан горячей воды. Массу довести до кипения, огонь уменьшить, тушить свинину с томатами и сладким перцем под крышкой до полной готовности мяса в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6022,'Маргарин растереть с сахарным песком, добавить сырые яйца, сметану, овсяные или мультизлаковые хлопья, всыпать муку и соду, быстро перемешать. Форму для выпекания смазать маргарином, выложить на дно полученную массу. Протереть творог через сито. Смешать со сметаной, яйцами, манкой, мукой или крахмалом, сахарным песком и стружкой кокоса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6022,'Вылить творожную начинку на тесто, печь при 200 градусах 30–40 минут. Чтобы получить румяную корочку, сначала блюдо нужно закрыть фольгой, а через 15 минут открыть и допечь. Готовность проверить деревянной палочкой, спичкой. Пирог с творогом остудить, вынуть из формы. Верхний слой смазать сиропом, присыпать кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6023,'Отделить белки от желтков. Смешать кефир с сахаром и желтками. Белки взбить в пену. Смешать кефирную смесь с белковой массой, добавить муку и разрыхлитель. Замесить тесто, добавить рубленые грецкие орехи, изюм, мак.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6023,'Тесто выложить в небольшие, смазанные маслом, формочки, лучше из силикона. Поставить в духовку. Печь кексики на кефире в течение 35–45 минут при температуре 200 градусов. Готовность выпечки проверить зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6024,'Натереть морковь на крупной терке, добавить сахарный песок, растопленное сливочное масло, яйца. Погасить пищевую соду уксусом, влить в массу, всыпать пшеничную муку. Замесить тесто, выложить ровным слоем на противень, выпечь в духовке при 180 градусах до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6024,'Приготовить крем из сливочного масла и сгущенного молока в равных пропорциях. Корж разрезать острым ножом по горизонтали. Промазать морковный торт кремом, покрыть им верх торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6025,'Обжарить на рафинированном подсолнечном масле мелко нарезанный лук, рубленый чеснок, мускатную тыкву на среднем огне. Тушить до светло-коричневого цвета в течение пяти-шести минут, помешивать. Влить воду или куриный бульон, продолжать тушить. Приготовить пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6025,'Добавить готовую, заранее отваренную, пасту и тертый твердый сыр. Влить молоко, массу потушить на сковороде, помешивать. Всыпать молотый мускатный орех, соль и перец–по вкусу. Пасту с сыром подать в горячем виде, посыпать рубленой зеленью петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6127,'Промазать медовый бисквит вареной сгущенкой или смесью «варенки» со сливочным маслом или сметаной. Верх залить шоколадной глазурью, посыпать рублеными орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6026,'Довести воду до кипения, посолить, отварить макароны лингвини до готовности, в течение семи минут. Откинуть. Растопить немного сливочного масла на большой сковороде. Обжарить ломтики свежих шампиньонов на среднем огне, до мягкости. Переложить обжарку на тарелку. В той же сковороде растопить еще масло, прогреть с рубленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6026,'Добавить сливочный сыр, разминать его ложкой, продукт должен расплавиться. Всыпать рубленую петрушку и базилик, прогревать пять минут. Влить кипящую воду, перемешать до однородного состояния. В готовый сливочный соус добавить готовые креветки и грибы, прогреть. Массу перемешать с отваренными макаронами, подать пасту со сливочным сыром и шампиньонами к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6027,'Смешать размягченное сливочное масло и сметану в течение 10 минут, постепенно добавить муку, соду (погасить небольшим количеством воды), влить подсоленную воду, вымесить однородное и гладкое тесто, дать постоять (пусть набухнет клейковина).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6027,'Приготовить из протертого творога, яиц, сахара и муки начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6027,'Разделить тесто на шарики величиной с орех, раскатать из них лепешки, на середину каждой выложить по ложке начинки из творога, разровнять, не доходя до краев 5-6 мм, сверху «Калитки» — пирожки поморские с творогом смазать щедро сметаной и зарумянить до готовности в духовке при среднем нагреве.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6028,'Приготовить несколько начинок: отварить яйца, порубить, смешать с майонезом и зеленым луком, можно добавить сметану. Массу перемешать и выложить на первый корж. Для второго коржа – размятая консервированная в масле рыба. Для третьего – творожный сыр с зеленью, луком, яйцом, майонезом. Следующая прослойка: мягкий сыр с зеленью и кусочками лосося. Для пятого коржа: рубленые яйца с зеленым луком и майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6029,'Перемолоть в кухонном комбайне овсяные хлопья не быстрого приготовления, добавить так же перемолотые хлопья быстрого приготовления. Всыпать корицу, розовую гималайскую соль, пищевую соду. При помощи блендера перемешать очищенные бананы с кокосовым маслом, сиропом агавы, ванильным экстрактом, долить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6029,'Обе смеси соединить, перемешать до однородного состояния. Выложить тесто в форму с разъемными краями, немного обжать. Оставшиеся бананы нарезать и выложить сверху. Измельчить в блендере еще часть овсяных хлопьев, кокосового сахара и кокосового же масла. Массу выложить на бананы, не прижимать. Печь овсяный торт с бананами в течение 25–30 минут до зарумянивания верхней корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6030,'Пшеничную муку просеять с разрыхлителем, добавить по вкусу соль и молотый перец, всыпать мускатный орех, перемешать. Отдельно взбить с помощью венчика яйца, желток, влить молоко, всыпать сахарный песок. Массу перемешать и тонкой струйкой влить в муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6030,'Для приготовления начинки мелко нарезать копченую курицу, маринованные опята, зелень. Перемешать сметану с чесноком, пропущенным через пресс, добавить к курице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6030,'В небольшие формочки для кексов выложить по полторы столовые ложки теста, сверху – начинка, залить остатками теста. Присыпать тертым сыром, печь блинные кексы при температуре 180 градусов в течение 20–25 минут. Подать в теплом или горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6031,'Отварить клубни картофеля. Отдельно довести до кипения жирные сливки со сливочным маслом и чесноком. Довести до кипения, снять с огня. Картофель растолочь, посолить и поперчить по вкусу, влить горячую сливочную массу, хорошо перемешать. Добавить творог, зеленый лук, все перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6032,'Отварить клубни картофеля, приготовить пюре, остудить. Отварить морковь и свеклу, то и другое нарезать тонкими брусками. На бамбуковый коврик положить пюре ровным слоем, затем овощи, нарезанное крутое яйцо, намазать майонезом, положить полоску малосольной сельди. Завернуть ролл с помощью коврика, обжать, придать квадратную форму, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6038,'Приготовить маринад из сырого яйца, картофельного крахмала, соли и перца. Положить в смесь печень на 30–40 минут. Обжарить печень в крахмале на растительном масле с двух сторон, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6087,'Отварить яйца, белки отделить от желтков, измельчить то и другое. Отварить и натереть свеклу, смешать с рубленым чесноком и майонезом. Натереть твердый сыр, нарезать любую зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6033,'Для приготовления начинки смешать мягкий творог, сахарный песок, подогретое молоко, ванилин и ванильный пудинг из пакета. Массу взбить при помощи миксера. Отдельно соединить растопленное сливочное масло, теплое молоко, сахар, ванилин. Всыпать немного пищевой соды или разрыхлителя, пшеничную муку. Тесто вымешать. Треть переложить в отдельную посуду, добавить какао-порошок, перемешать до однородного цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6033,'В форму для выпечки кексов выложить половину «белого» теста, затем половину «темного», следующий слой – творожная начинка, затем консервированные абрикосы, сироп слить. Фрукты закрыть «темным» тестом, сверху – «белое». Печь в духовке в течение часа при температуре 180 градусов. Готовую выпечку вынуть, остудить в форме. Перевернуть творожный кекс на тарелку, полить густым абрикосовым джемом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6034,'Смешать молоко и кипящую воду, в теплой смеси растворить ложку сахарного песка, сухие быстрорастворимые дрожжи. Закваску поставить в теплое место на 15 минут. В хлебопечку всыпать просеянную пшеничную муку, ванильный сахар из пакетика, соль, растопленное сливочное масло, взбитое яйцо, влить сок и всыпать тертую цедру апельсина. В конце замеса влить воду с дрожжами. Можно замесить тесто вручную, оставить в чаше на час для подъема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6034,'Для приготовления начинки залить миндальные орехи кипятком и оставить на 10 минут. Очистить кожуру, после ошпаривания она легко снимется. Продукт подсушить на сковороде в течение двух минут. Орехи остудить, перемолоть, добавить сахарную пудру, молотую корицу, несколько капель миндальной эссенции, сырой белок для связки. Можно добавить ложку холодной воды, если смесь получилась слишком густая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6034,'Подошедшее тесто переложить на присыпанную мукой поверхность, разрезать на равные части. Раскатать тонкие лепешки, выложить ореховую начинку. Скатать рулетами, растянуть в длину, скрутить в жгут, завязать в узел или просто соединить концы в «кольцо».  Выложить подготовленные «кольца» на смазанный растительным маслом и присыпанный мукой противень. Можно воспользоваться силиконовым ковриком, в этом случае смазка не потребуется.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6034,'Острым ножом сделать сверху неглубокие надрезы по диагонали, чтобы стала видна начинка. Накрыть изделия пленкой и, сверху, полотенцем на полчаса. Поднявшиеся «колечки» смазать смесью молока с желтком. Печь апельсиновые булочки с миндалем при температуре 180 градусов в течение 20 минут, выпечка должна хорошо зарумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6035,'Смешать пшеничную муку со сливочным маслом, какао-порошком, массу порубить ножом. Добавить сахарный песок, сырые яйца, замесить тесто. Поставить массу на полчаса в холодильник. Охлажденное тесто достать, раскатать в лепешку, выложить на смазанный противень. Печь в духовке в течение 30–40 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6035,'Корж остудить, разрезать на четное количество квадратов. Половину заготовок смазать малиновым вареньем и посыпать рублеными грецкими орехами. Накрыть второй половиной квадратов, оставшимся вареньем смазать верх и бока печенья, обсыпать теми же орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6036,'Фасоль замочить в воде на 2–3 часа. Воду слить, положить продукт в кастрюлю, залить свежей водой так, чтобы она покрыла фасоль на 2 см. Варить почти до готовности. Копченые свиные хрящики или ребрышки нарезать, добавить нарезанные сардельки, копченую грудинку и окорок. Разогреть сковороду, обжарить сначала грудинку, через 5 – 6 минут все остальные ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6036,'В обжарку положить мякоть помидоров, резаный чеснок, потушить. Массу вылить в фасоль, добавить много рубленой кинзы, винный уксус. Соль, лавровый лист, молотый черный перец–по вкусу. Перемешать и тушить фасоль с копченостями по-венгерски в течение 40 минут на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6037,'Тонкими дольками нарезать помидоры, свежие огурцы–полукольцами. Ветчину–тонкой соломкой или кубиками. Натереть твердый сыр, все ингредиенты перемешать, заправить специями, полить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6038,'В крахмале можно обваливать перед обжариванием не только печень, но и котлеты, рыбу, вместо муки. Образующаяся корочка не дает испаряться влаге, блюда получаются сочными. Свиную или говяжью печень очистить от пленок, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Свинину с прослойками жира порезать на брусочки.','https:https://st.vkuso.ru/data/cache/thumb/b9/921af02461ef0b9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6039,'Разрезать стерлядь на две части, смазать маслом большую сковороду, выложить на нее рыбу и поставить в духовку, запекать 15 минут, смазать рыбу сметаной и запекать дальше, чтобы куски подрумянились, выложить сверху кольца лука и смазать опять сметаной, отправить в духовку и довести до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6039,'Стерлядь под сметаной по-волжски, подается к столу в горячем виде украшенная зеленью и кусочками лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6040,'Мясо надрезать в виде «книжки», по вкусу посолить и поперчить. Нарезать кружочками морковь. Слить жидкость от консервированных ананасов. Для приготовления маринада смешать майонез, готовую столовую горчицу, сухой базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6040,'Мясо проложить ананасом и морковью, залить маринадом. Посыпать сухим орегано, поставить в холодильник на два часа или на всю ночь. Свинину-книжку с морковью и ананасом запечь в духовке до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6041,'Филе окуня промыть, обсушить, натереть солью и перцем со всех сторон. Смешать майонез и кетчуп или томатный соус, смазать внутреннюю сторону рыбного филе. Также поступить с другим филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6041,'На одну тушку положить очищенные креветки, накрыть другим, перевязать ниткой. Запанировать изделие в муке, жарить на растительном масле на сковороде с двух сторон, во время приготовления блюдо накрыть крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6041,'Можно запечь в духовке без панировки. Готовую рыбу немного остудить, снять нитки. Подать морского окуня с креветками с отваренными макаронами, зеленью, кружком тонко нарезанного лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6042,'Желатин из пакетика залить небольшим количеством охлажденной кипяченой воды, оставить на 10 минут для набухания. В сотейнике нагреть молоко, добавить щепоть соли, растворимое кофе, смесь размешать и снять с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6042,'Растереть сырой желток с коричневым или обычным сахаром, ванилином из пакетика, прогреть на водяной бане в течение одной-двух минут. Массу постоянно взбивать вручную или миксером, чтобы яйцо не свернулось. Продолжая взбивать, влить в массу теплое молоко с кофе, взбивать еще две-три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6042,'В желтковую массу влить набухший желатин, прогреть на водяной бане еще одну-две минуты, продолжать взбивать. Крем снять с бани, влить кофейный ликер, огонь выключить, продолжать взбивать до полного остывания. Жирные сливки взбить в пену, соединить с кремом, осторожно перемешать и поставить на час или два в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6042,'Готовую, загустевшую, массу разложить в креманки, формочки или кофейные чашки. Посыпать рублеными орехами, листочками свежей мяты, измельченным шоколадом. Поставить кофейный крем в холодильник еще на час или два и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6043,'Отварить куриное филе с солью и специями, нарезать на кусочки и немного обжарить. Порезать маринованные грибы, например, маслята. Отварить, очистить и измельчить куриные яйца, натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6043,'Продукты выложить в салатницу слоями в таком порядке: куриное мясо, грибы, мелко нарезанная морковь по-корейски, яйца. Все слои промазывать майонезом. Сверху салат «Три цветка» с грибами и курицей полить майонезом и посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6044,'Грудку нарезать, замочит на 20 минут в вине, обжарить. Отдельно приготовить обжарку из репчатого лука, моркови и нарезанных шампиньонов. Добавить сметану, немного воды, довести до кипения. В обжарку положить куриное мясо, еще немного потушить. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6045,'Треску нарезать на кусочки, кости удалить. Заправить специями, полить свежим лимонным соком. Для приготовления кляра смешать кефир, пищевую соду. После появления пузырьков влить сырое яйцо, всыпать сахарный песок, пшеничную муку, посолить по вкусу. Тесто должно быть похоже на жидкую сметану.  Каждый кусочек рыбы обмакивать в кляр и обжаривать на сковороде на растительном масле с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6046,'Приготовить жидкое тесто из кефира или кислого молока, сырых куриных яиц, пищевой соды, соли, сахарного песка, просеянной пшеничной муки. Хорошо взболтать, венчиком или с помощью блендера, в тесте не должно быть комочков, масса должна быть однородной, средней густоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6087,'Салат выложить «башенкой», с помощью разъемных бортиков. Слои располагать в таком порядке:  селёдочный, белки, свекольный, желтки, тертый сыр. Посыпать селедочный салат зеленью петрушки, укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6046,'Обжарить толстые оладьи на подсолнечном масле с двух сторон, можно воспользоваться формочками для жарки яиц. Готовые блины аккуратно разрезать ножом до половины, а потом еще немного вглубь. Положить по чайной ложке красной икры. При подаче блинчики с икрой можно украсить веточками зеленого укропа и петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6047,'Нарезать кубиками красную рыбу, семгу или форель, обжарить со всех сторон. Залить кипятком замороженные креветки, очистить, посолить и поперчить по вкусу. Также обжарить в течение трех минут, добавить зелень петрушки, укропа и соевый соус по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6047,'Массу выложить в пиалу, плотно прижать, утрамбовать. Перевернуть закуску «Сказка» на блюдо, украсить свежим, тонко нарезанным, огурцом и красной икрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6048,'Отварить мясо целым куском, удалить пену, положить в бульон не разрезая морковь и луковицу, заправить бульон лавровым листом, горошками черного перца, посолить, сделать минимальный нагрев, прикрыть крышкой и готовить до размягчения мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6048,'Нашинковать капусту и лук, мелко нарезать сладкий перец, помидоры, грибы – ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6048,'Убрать из кастрюли луковицу и выкинуть, морковь нарезать кубиками, вынуть и нарезать брусочками мясо, положить морковь и мясо обратно в щи, добавить грибы, капусту с перцем и лук, поставить варить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6048,'Добавить в конце варки чеснок и измельченную зелень, попробовать щи с шампиньонами и мясом, и если надо, то подсолить, заправить при подаче в тарелках сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6049,'Телячью, куриную или индюшачью печень очистить от пленок, нарезать, залить красным сухим вином, дать постоять в течение часа. Натереть репчатый лук на мелкой терке, добавить в него красный и черный перец, сухие травы, соль. Перемешать, должна получиться кашица.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6049,'Маринованную печень обсушить с помощью бумажных полотенец, обвалять в луковой смеси, затем – в панировочных сухарях. Жарить на растительном масле со всех сторон. Подать печень индейки на листьях зеленого салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6050,'Очистить репчатый лук, мелко нарезать и обжарить с растительным маслом до золотистого цвета. В процессе обжаривания добавить смесь любых специй для куриного мяса. Отдельно отварить куриное филе, яйца, нарезать оба продукта мелкими кубиками, маринованные шампиньоны – тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6050,'Очистить и обжарить на сухой сковороде грецкие орехи, измельчить большую часть, оставить несколько штук для украшения блюда. Все приготовленные ингредиенты смешать, салат «Шерлок» посолить и поперчить по вкусу, заправить майонезом. Украсить оставшимися орехами. Другой вариант: составляющие выложить слоями, промазать майонезом. В куриный слой можно добавить мелкорубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6051,'Для приготовления блюда можно использовать любой густой фарш или смесь двух-трех фаршей, соль и перец молотый – по вкусу. Скатать из массы шарики, расплющить в мокрых ладонях или на столе в тонкие лепешки. Не нужно лепить котлеты, пусть порции будут неровными по краям, как настоящая отбивная.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6051,'Отдельно взбить яйца, в другую емкость насыпать панировочные сухари, смешанные с солью, специями и гранулированным или сушеным чесноком. Вместо сухарей можно взять пшеничную муку. Отбивные из мясного фарша аккуратно запанировать в сухарях, затем обмакнуть в яичную смесь. Жарить на растительном масле с обеих сторон до образования румяной, хрустящей, корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6052,'Крабовые палочки разморозить, нарезать кружочками. Брынзу слабого посола нарезать небольшими кусочками. Разобрать, порвать руками или порубить салат айсберг, помидоры черри разрезать пополам, огурцы – половинками кружочков.  Для заправки смешать легкий майонез, кетчуп, готовую столовую горчицу. Смесью залить салат «Капелька росы», перемешать. Солить не нужно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6053,'Перемешать в емкости пшеничную муку с солью, постепенно влить кипяченую воду, перемешать. Готовое тесто скатать в «колобок», завернуть в пищевую пленку или полиэтилен, положить в холодильник на 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6053,'Охлажденное тесто раскатать в лепешку толщиной в один сантиметр. Выложить в смазанную растительным маслом форму для запекания. Краям теста придать волнистую форму. Печь пи 220 градусах в течение 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11120,'Промыть в дуршлаге, дать хорошо стечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6053,'Температуру уменьшить до 165 градусов. Выложить тонкие ломтики бекона, тертый твердый сыр, мелко нарезанный репчатый лук. Взбить в миске яйца, перемешать с отдельно взбитыми сливками, массу вылить на начинку. Соль, молотый черный и красный, каенский, перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6053,'Печь пирог «Лотарингия» с беконом в течение 45 – 50 минут. Проверить готовность с помощью ножа, он должен остаться сухим. Перед подачей дать постоять в течение 10 минут. Посыпать рубленой зеленой петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6054,'Твердый сыр нарезать на бруски. Замесить густое тесто из сырых яиц, пшеничной муки, соли, молотого перца, кипяченой воды. Кусочки сыра обмакивать в тесто и обжаривать на сковороде с маслом с двух сторон. Обжаренные бруски окунуть в сметану, выложить на тарелку, посыпать любой неострой приправой и рубленой зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6055,'Отварить клубни картофеля, яйца, натереть оба продукта. Отварить и обжарить куриную, индюшачью или телячью печень, также натереть. Измельчить репчатый лук и морковь, приготовить обжарку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6055,'Выкладывать в салатницу слоями, каждый присаливать и промазывать майонезом. Верх салата с куриной печенью посыпать тертым сыром и украсить веточками зеленого укропа, морковью по-корейски, зернами консервированной кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6056,'Твердый сыр, сваренное вкрутую яйцо и белки натереть на мелкой терке. Репчатый лук мелко нарезать, добавить лососевую стружку, майонез, ингредиенты перемешать. Салатную массу выложить в готовые вафельные лодочки. Украсить тертым желтком, выложить рыбную икру, мелкую, например, мойвы. Положить по черной оливке без косточки. Лодочки выложить на хорошо вымытые и обсушенные листья фиолетового салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6057,'Взбить яйца с сахарным песком, добавить 1/2 банки вареного сгущенного молока, всыпать муку, влить 100 г сметаны, пищевую соду, погашенную уксусом. Массу перемешать и выпечь 3 коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6057,'Для крема перемешать сметану и 1 ст.л. сахара, промазать коржи. Остатки сгущенки взбить со сливочным маслом, намазать верх и бока торта. Посыпать торт «Соня» рублеными орехами, тертым шоколадом, сделать «завитки» с помощью ножа или вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6058,'Из соленых килек вытащить хребет вместе с ребрами, получатся два небольших филе. Нарезать кольцами репчатый лук. Порубить зелень петрушки. Петрушку насыпать на дно тарелки, выложить лук. Сбрызнуть яблочным или винным уксусом, растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6058,'Нарезать мелкой соломкой красный сладкий перец и очищенный маринованный огурец. Завернуть в каждое филе кильки по кусочку огурца и перца. Выложить роллы из кильки на луковый слой, еще немного сбрызнуть растительным маслом, украсить листочками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6059,'Очистить от шкурки яблоки (лучше кислые) и мелко порезать, натереть черный хлеб (черствый) на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6059,'Распустить в кастрюле масло, высыпать в него слоями часть хлеба, потом яблоки, посыпать их смесью корицы и сахара, сверху изюм или любое варенье, а потом опять слой хлеба, полить верх шарлотки из черного хлеба по-старорусски маслом и запечь до готовности при средней температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6060,'Мелко нарезать репчатый лук, порубить чеснок. То и другое обжарить на оливковом масле до прозрачности. Добавить белое сухое вино и мидии, потушить на сильном огне в течение 5 – 8 минут. Соль и перец – по вкусу. Выложить мидии в другую емкость, дать остыть. Для заправки раздавить чеснок под прессом, смешать с оливковым маслом, добавить рубленый базилик и свежий сок лайма, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6060,'Нарезать сладкий болгарский перец и помидоры, нашинковать кинзу и петрушку. Перемешать в большой миске нарезанные листья зеленого салата, дольки помидоров, добавить нарезанные овощи и зелень. Полить заправкой, соль и молотый перец – по вкусу. Выложить приготовленную массу в салатницу, сверху положить мидии, сбрызнуть малиновым уксусом. Украсить сваренными вкрутую и нарезанными яйцами, подать салат с мидиями к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6061,'Нарубить полусладкий шоколад, залить водой или крепким кофе, растопить смесь на тихом огне в небольшой емкости. Снять с огня, перемешивать до однородного состояния. Немного остудить. Отдельно, с помощью миксера, взбить желтки, добавить сахар порциями, постепенно, продолжать взбивать. Влить теплую шоколадную смесь, взбить всё вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6061,'В другой посуде превратить в плотную пену сырые яичные белки с небольшим количеством соли. Четверть полученной массы переложить в шоколад, перемешать, добавить оставшиеся белки порциями. Противень смазать растительным или сливочным маслом, застелить пергаментом или вощеной бумагой. Готовое тесто вылить в подготовленную форму, поверхность разровнять. Печь при температуре 175 градусов в течение 15 минут. Остудить немного под влажным полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6061,'На теплый, мягкий, корж насыпать какао-порошок, перевернуть, убрать пергамент и тоже посыпать. Свернуть лепешку в рулет при помощи полотенца, остудить. Жирные сливки взбить с сахарной пудрой, ванилином. Рулет осторожно развернуть, ткань убрать. Смазать корж полученным кремом, снова свернуть и выложить на блюдо, шов должен быть внизу. При подаче шоколадный рулет нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6062,'Нарезать вдоль на тонкие полоски сосиски. Такими же длинными ломтиками нарезать твердый сыр, они должны быть немного короче. На полоски сосисок положить по полоске сыра, свернуть маленькими рулетами, заколоть зубочистками и запечь в духовке в течение 7 – 10 минут. Подать закуску на листьях зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6063,'Отварить любые макароны. Тушку семги отделить от кожи острым ножом, удалить кости. Нарезать рыбу средними кубиками. Соль и перец – по вкусу, полить соком лимона. Оставить на полчаса для маринования. Разогреть оливковое, подсолнечное или сливочное масло, обжарить рыбу в течение 3 – 5 минут. Помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6063,'Влить в сковороду подогретые сливки. Добавить соль и черный или красный молотый перец, карри, осторожно перемешать. Прогреть на среднем огне, довести до кипения, огонь выключить. Всыпать измельченный чеснок, зелень, тертый твердый сыр и еще раз перемешать. Готовую семгу в сливочном соусе выложить на макароны и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6064,'Очистить и порубить чеснок и обжарить на оливковом масле  течение минуты. Добавить томатное пюре или пасту, соль и сахарный песок.  Сыр фета нарезать мелкими кубиками. Добавить к томатному соусу, убавить огонь, прогреть массу в течение 20 минут. В конце добавить мелко нарезанный базилик. Отварить макароны фарфалле, слить воду. Выложить на тарелки, полить соусом и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6065,'Клубни картофеля очистить и нарезать. Посыпать морской солью и острым молотым перцем, перемешать. Обжарить на хорошо разогретом оливковом масле, помешивать, до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6065,'Подготовленный картофель выложить в форму для запекания. На оставшемся масле обжарить рубленый репчатый лук, чеснок и шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6065,'Разрезать пополам помидоры черри, добавить в обжарку. Посолить и поперчить, посыпать  укропом. Печь картофель с грибами и помидорами в течение 20 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6066,'Клубни картофеля очистить, нарезать тонкими кружочками. В толстостенной сковороде разогреть оливковое масло, посыпать перцем и солью, жарить на среднем огне в течение 10 минут до золотистого цвета. Нарезать зеленый лук, белые части стебля измельчить отдельно от зеленых. Первые добавить к картофелю. Туда же добавить кубики ветчины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6066,'В глубокой емкости смешать сырые яйца, молоко, всыпать тертый сыр. Смесь хорошо взбить, всыпать рубленый зеленый лук. К почти готовому картофелю влить яичную смесь, она должна равномерно распределиться по сковороде. Прогревать одну-две минуты, края блюда должны пропечься. Поставить сковороду с картофельной фриттатой в духовку еще на 15–20 минут. Перед подачей блюдо должно постоять пять минут, подать в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6067,'Очистить и нарезать мелкими кубиками репчатый лук, морковь, корень сельдерея, клубни картофеля. Все подготовленные овощи перемешать с веточками розмарина и рубленым чесноком, обжарить на оливковом масле в течение восьми минут. Овощную смесь остудить, добавить говяжий фарш, соль и молотый перец – по вкусу. Влить половину взбитого яйца для связки. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6067,'Раскатать готовое слоеное тесто в виде прямоугольника. Выложить начинку в виде «колбаски», края теста смазать яйцом, скрутить в рулет. Края закрепить. Выложить изделие на противень, смазать яйцом всю поверхность, печь рулет «Веллингтон» в течение часа при температуре 175 градусов до образования золотисто-коричневой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6068,'Для приготовления варенья понадобятся плотные плоды, свежие, только что с дерева, без пятен и червоточин. Яблоки вымыть, вырезать сердцевину, нарезать мякоть дольками в 5–10 мм толщиной. Уложить в кастрюлю плоды пополам с сахарным песком, в равных пропорциях. Оставить до утра. Поставить варенье на небольшой огонь, довести до кипения, поварить пять минут и выключить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6068,'Через несколько часов процедуру повторить. Снова оставить на ночь. На третий день доварить продукт до готовности в течение 10–15 минут, капли сиропа на блюдечке должны держать форму, не растекаться. Душистое варенье из яблок разложить в стерильные банки небольшого размера, закатать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6069,'Разрезать небольшой кочан на четвертинки, переложить в глиняную, нержавеющую или эмалированную посуду, добавить мяту или тмин, анис, залить кипящим рассолом, дать остыть под гнетом, для быстрого заквашивания в остывший рассол добавить корочку черного хлеба и поставить в тепло, капуста заварная на закуску будет готова через 3-4 дня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6069,'Перед подачей капусту заправить маслом, можно добавить бруснику или клюкву.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6070,'Сливочное масло комнатной температуры растереть с сахаром, добавить сметану и пищевую соду. Замесить мягкое тесто. Разъемную форму для выпечки смазать сливочным маслом, выложить раскатанное тесто, сформовать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6070,'Для начинки кисло-сладкие яблоки очистить от кожуры и сердцевины, нарезать дольками или произвольно.  Для заливки соединить сметану с сырым яйцом, растертым с сахарным песком. Добавить пшеничную муку. Массу перемешать, в ней не должно быть комочков. Выложить на корж начинку, полить сметанно-яичной массой, печь яблочный пирог при 170 градусах в течение 40–45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6071,'Приготовить свиной фарш, соль–по вкусу. Шампиньоны вымыть, обсушить, нарезать кусочками, обжарить вместе с репчатым луком, посолить. Отварить куриные яйца вкрутую. Готовое слоеное тесто раскатать, посыпать тертым сыром ламбер или любым другим, аналогичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6071,'Выложить слой мясного фарша, затем–грибы. Сверху–нарезанные вареные яйца, посолить. Рулет свернуть, положить на противень швом вниз, смазать сверху немного взбитым желтком. Печь рулет с мясным фаршем при температуре 180 градусов около часа, должна образоваться золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6072,'Измельчить юбилейное печенье в крошку. Отдельно растопить сливочное масло, подлить в крошку, хорошо перемешать. Чашу мультиварки выложить бумагой для выпечки, нарезать её полосками, края должны выступать из чаши, с их помощью пирог можно будет достать из емкости неповрежденным. Дно смазать сливочным маслом, выложить «тесто», примять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6072,'Для приготовления крема смешать сыр с сахарной пудрой, это можно сделать вручную, ложкой, или с помощью миксера. Добавить яйца по одному, снова перемешать, положить тертую цедру лимона. Влить сливки, перемешать, должна получиться гладкая и однородная масса. Вылить крем на песочный корж. Прогревать в режиме «Выпечка» в течение часа или немного меньше. Остудить в мультиварке, вынуть чизкейк, поставить в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6073,'Сметану взбить с сахарным песком, добавить нарезанные кружками очищенные бананы. Сахарное печенье замочить на несколько секунд в молоке, выложить слоем на блюдо. Сверху–сметанный крем с бананами, снова печенье, слои повторить несколько раз. Поставить тортик из печенья на полчаса в холодильник и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6074,'Очистить и разрезать пополам бананы. Форму для запекания смазать маслом, сбрызнуть лимонным соком, чтобы бананы не потеряли цвет. Выложить плоды. Взбить с помощью блендера до однородного состояния творог, сметану, сок и цедру половины лимона, добавить мед или джем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6074,'Влить сырые яйца и еще раз хорошо взбить. Всыпать манку или положить поленту, перемешать. Массу вылить на бананы, разровнять. Поставить в духовку на полчаса, печь при температуре 180 градусов. Выпечка должна стать упругой на ощупь и приобрести золотистый цвет. Творожную запеканку немного остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6080,'С помощью миксера или венчика поочередно вмешать сахарный песок, просеянный какао-порошок, ванилин. По одному вбить сырые яйца. Всыпать просеянную пшеничную муку, щепотку соли. В последнюю очередь всыпать измельченные и слегка обжаренные грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6075,'В небольшом количестве оливкового масла обжарить рубленый репчатый лук, он должен стать прозрачным. Добавить куриное филе, нарезанное кусочками. Когда мясо посветлеет, положить в сковороду нарезанный кубиками сладкий желтый болгарский перец. Массу перемешать, прогреть в течение нескольких минут, всыпать порошок шафрана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6075,'В сковороду с курицей и овощами всыпать рис арборио, посолить по вкусу, прогреть две-три минуты. Влить белое полусухое вино небольшими порциями, продолжать помешивать. Дать вину впитаться, влить горячий куриный бульон. Добавить консервированную кукурузу, жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6075,'Блюдо продолжать прогревать, при необходимости подливать бульон. В конце приготовления ризотто поперчить и досолить, если есть такая необходимость. Подать блюдо горячим, посыпать ризотто с курицей тертым сыром, украсить веточкой любой зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6076,'Нарезать твердый сыр и ветчину соломкой. Отварить яйца, очистить, нарезать кубиками, порубить репчатый лук. Нарезать зелень укропа и петрушки. Все ингредиенты смешать и заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6077,'Растопить сливочное масло, смешать с сахарным песком, просеянной пшеничной мукой, кокосовым ликером и стружкой. Форму для выпекания застелить пергаментом, выложить массу, разровнять и на полчаса поставить в холодильник. Затем корж испечь в течение 15 минут при температуре 200 градусов. Выпечка должна зарумяниться. Остудить. Для приготовления крема замочить желатин из пакетика в небольшом количестве холодной воды. Подсушить на сковороде без жира целый очищенный миндаль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6077,'Перемешать до однородного состояния сгущенное и кокосовое молоко, ванильный сахар. Отжать желатин, прогреть на тихом огне до полного растворения. Добавить в желатиновую массу несколько ложек кокосовой смеси, перемешать, поставить на полчаса в холодильник. Взбить сливки в пену, вмешать в охлажденный крем, добавить миндаль. Вокруг выпеченного коржа закрепить кольцо от разъемной формы, залить крем, поставить торт «Рафаэлло» в холод для застывания на четыре часа или на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6078,'Приготовить заварное блинное тесто. Для этого нужно перемешать сырые куриные яйца с сахарным песком и солью. Влить оливковое масло и молоко. Просеять в смесь пшеничную муку, тщательно растереть, в тесте не должно быть комочков. Влить крутой кипяток, оставить смесь на 15 минут. Тесто должно получиться гладким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6078,'Для приготовления ванильного соуса растопить в кастрюле небольшого объема сливочное масло, добавить коричневый сахар, соль – по вкусу. Массу хорошо перемешать. Влить жирные сливки, всыпать кукурузный крахмал. Варить соус в течение 5–7 минут на тихом огне. Огонь выключить, снять с плиты, добавить ванилин из пакетика и перемешать. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6078,'Тесто для блинов разделить на две части, в одну из них всыпать какао-порошок, перемешать. Выпечь на смазанной растительным маслом сковороде светлые и темные блинчики. На темный блин положить светлый и наоборот. Свернуть рулетами. Разрезать рулетики из блинов пополам, выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6079,'Куриное филе нарезать на плоские куски, отбить молоточком на кухонной доске. Поперчить по вкусу и обмазать с двух сторон майонезом. Сложить отбивные друг на друга. Майонез можно заменить на готовую столовую горчицу. Нарезать крупную луковицу полукольцами. Очистить и нарезать пластинками клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6079,'Сковороду нагреть, смазать подсолнечным маслом. Выложить половину картофель в два слоя, оба слоя посолить по вкусу. Сверху – мясо, лук, тертый твердый или плавленый сыр, он должен полностью закрыть продукты. Полить майонезом средней жирности. Печь блюдо при температуре 230 градусов в течение часа. Картофель по-королевски должен полностью пропечься, это можно проверить спичкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6080,'Готовить блюдо в силиконовой форме или в обычной форме для запекания, в таком случае её нужно заранее разогреть и смазать сливочным маслом. Растопить горький шоколад, поломанный кусочками, со сливочным маслом на водяной бане. Массу помешивать, она должна стать тягучей и однородной. Выключить огонь, смесь немного остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6087,'Филе слабосоленой сельди освободить от костей и нарезать кусочками средней величины. Измельчить красный репчатый лук, перемешать с рыбой и майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6080,'Тесто хорошо перемешать и перелить в форму. Печь брауни из горького шоколада в течение получаса при температуре 180 градусов. Готовность проверить спичкой или зубочисткой, они должны остаться сухими. Достать пирог из духовки, немного охладить и вынуть из формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6081,'Консервированную горбушу выложить на блюдо и хорошо размять с помощью вилки. Отварить куриное яйцо, очистить, нарезать кубиками. Порубить зеленый лук. Смешать лук, яйца и майонез, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6081,'Лаваш для рулета прямоугольной формы выложить на стол, смазать майонезом. На половину лепешки выложить яичную начинку, на другую половину – рыбную. Нарезать кубиками или пластинками помидоры, выложить на один край вместе с листьями зеленого салата. Свежий огурец нарезать длинными «лентами» и выложить внахлест в середине лаваша, на стыке начинок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6081,'Завернуть рулет со стороны помидорной начинки. Обернуть закуску в пищевую пленку, положить в холод на два часа или на ночь. Перед подачей рулеты из лаваша нарезать на кружочки, украсить маслинами, зеленью укропа, петрушки, базилика, «чашечками» из сверенного вкрутую белка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6082,'Кефир подогреть до 40 градусов. Смешать с сухими дрожжами и небольшим количеством пшеничной муки, оставить на 15 минут. Влить готовую опару в муку, замесить тесто. В конце замешивания добавить растительное масло. Тесто должно получиться мягким и эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6082,'Накрыть массу полотенцем, поставить в тепло на час. Через час тесто обмять, разделить на три «колобка», дать им подняться, подержать под тканью еще полчаса. Каждый «колобок» размять руками на посыпанной мукой поверхности в толстые лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6082,'Приготовить любую начинку: мясной фарш с луком и пряными травами, картошка с тертым сыром, свекольная ботва с сыром и зеленью. Можно приготовить сладкую начинку. Выложить массу на лепешку, защипать края сверху в виде кулечка. Размять «кулечек» в плоскую лепешку руками. Печь пироги из домашнего теста при температуре 220 градусов в течение 20–25 минут, готовую выпечку смазать сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6083,'Малиновый или клубничный сироп вылить в кастрюльку, добавить сахарный песок, варить на тихом огне до загустения, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6083,'Охладить белки в холодильнике, взбить. Развести желатин так, как написано на упаковке. Загустевшую смесь снять с огня, влить взбитые сливки и желатин, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6083,'Форму для зефира посыпать сахарной пудрой, массу переложить в форму, сверху также посыпать пудрой. Поместить ягодный зефир в холодильник на два-три часа. Вырезать фигурки в форме сердечек или ромбиков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6084,'Перемешать творог, сахарный песок, манную крупу, молоко и мягкое сливочное масло комнатной температуры. Разбить яйца. Массу перемешать, оставить на 40 минут, крупа должна набухнуть. Печь в форме, в духовке, при температуре 180–200 градусов до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6085,'Свиную шейку нарезать и отбить. Приготовить начинку: натереть твердый сыр, мелко нарезать маринованные огурцы, добавить рубленый обжаренный лук, влить яйцо для связки, перемешать. Свернуть в виде трубочки и положить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6085,'Блюдо закрыть пищевой фольгой, печь рулетики из свинины в течение часа при температуре 180–200 градусов. Фольгу снять, оставить рулеты в духовке еще на полчаса, до зарумянивания. Посолить, поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Хлеб порезать ломтиками, яйца взбить с молоком, добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Вишни или сливы помыть и извлечь кости, отжать немного сока и засыпать сахаром ягоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Промазать маслом и чуть присыпать сухарями форму для выпечки, выложить в нее нарезанный хлеб, который перед выкладкой нужно обмакнуть в яичную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Поверх хлеба распределить слой вишни или сливы, слои повторять  пока последним не окажется хлеб.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Далее необходимо подготовленную шарлотку залить оставшейся смесью, отправить форму в духовку со средней температурой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6086,'Запекается Шарлотка из хлеба с вишней по-польски до образования румяной корочки в пределах 30-40 минут, перед подачей посыпается сахаром, смешанным с ванилином.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Обжарить на масле до светлой корочки.','https:https://st.vkuso.ru/data/cache/thumb/93/ef43c2f2b16fd93_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6088,'Растопить сливочное масло, всыпать сахарный песок, растереть. Добавить сырые куриные яйца, перемешать. Можно воспользоваться блендером или сделать это вручную. Всыпать картофельный крахмал, в заключение–пшеничную муку. Перемешать или взбить. Тесто должно быть по консистенции похожим на сметану. Разогреть вафельницу, влить столовую ложку теста, выпечь вафли до светло-коричневого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6089,'Пшеничную муку смешать с разрыхлителем, сахарным песком, ванилином из пакетика, сырыми яйцами, сливочным маслом комнатной температуры. Можно сделать это руками или с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6089,'Форму для выпечки с высокими бортиками выстлать пекарской бумагой. Выложить тесто, сформовать края, утрамбовать, наколоть вилкой в нескольких местах, сверху также застелить бумагой. Печь в течение 12 минут в духовке, нагретой до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6089,'Для приготовления начинки смешать творог, сахар, ванилин, сливки, ягоды черники, свежие или размороженные. Перемешать венчиком. Вылить на готовый корж, печь пирог с творогом и черникой при температуре 180–200 градусов в течение получаса, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6090,'Отварить картофель, яйца и филе курицы. Все продукты остудить, нарезать кубиками, оставить один желток для украшения. Также нарезать маринованные огурцы, репчатый лук, сладкий красный болгарский перец – длинными кусочками средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6090,'Все ингредиенты, кроме перца, перемешать, заправить майонезом, соль–по вкусу. Выложить салат на блюдо горкой, можно поместить массу в глубокую емкость круглой формы, утрамбовать и аккуратно перевернуть в салатницу. Сверху уложить перец, по всей поверхности. Натереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6090,'Размять вилкой оставленный желток, добавить немного майонеза для связки, сформовать шарик. Обвалять его в сыре и поместить на верхушку салата в качестве «помпона». Желток можно не измельчать, смазать поверхность майонезом и в таком виде обвалять в сыре. Остатками посыпать салат «Красная шапочка» по краю, получится импровизированная «опушка», и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6091,'Нагреть на среднем огне смесь молока, сахарного песка и сливочного масла. Отдельно смешать сырые желтки с сахаром, пшеничной мукой и небольшим количеством молока, всыпать ванильный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6091,'В кастрюлю с молоком вылить желтковую смесь, делать это медленно, одновременно взбивать. Варить две минуты, остудить. Печенье окунать в теплое молоко, выкладывать на лоток слоями, промазывать охлажденным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6092,'Курицу вымыть, обсушить, снять кожицу, ножки и крылышки оставить. Куриное филе отделить от костей, пропустить через мясорубку, можно воспользоваться блендером. Замочить в молоке белый батон, оставить набухать. Ветчину нарезать соломкой или кубиками. Натереть твердый сыр, порубить любую зелень: петрушку, укроп, кинзу. Нарезать сладкий красный болгарский перец кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6092,'Для приготовления начинки смешать приготовленный куриный фарш, отжатый от лишней жидкости батон, сыр, ветчину, перец, зелень, влить сырые яйца, молоко или сливки. Соль и перец–по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6092,'Куриную кожу посолить, поперчить изнутри и снаружи, можно сбрызнуть коньяком, внутрь уложить начинку. Отверстие сколоть с помощью зубочисток или зашить. Сверху тушку смазать майонезом, ножки и крылья связать нитками, чтобы курица сохранила первоначальную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6092,'Подготовить противень: смазать поверхность растительным маслом или майонезом, уложить курицу. Печь фаршированную курицу при температуре 160–180 градусов в течение 1,5 часов, поливать бульоном или выделяющимся соком. За 5–10 минут до окончания приготовления добавить температуру, должна получиться румяная корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6093,'Воду и сливочное масло довести до кипения. Всыпать пшеничную муку, прогревать, помешивая массу деревянной ложкой до тех пор, пока масса не загустеет и не соберется в шарик. Снять с огня, остудить в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6093,'Переложить массу в чашу миксера, влить сырые яйца, перемешать до однородного состояния. Перелить тесто в кондитерский мешок. Противни застелить бумагой и смазать маслом. Выдавить эклеры, между ними должно остаться пространство. Печь в заранее разогретой до 200 градусов духовке в течение 25–30 минут. Выпечку остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6093,'Для приготовления начинки взбить желтки с сахарным песком до состояния крема. Всыпать муку и картофельный крахмал. Довести на тихом огне до кипения молоко с ванилью. Во взбитые яйца влить стакан молока, перемешать, а затем полученную смесь перелить обратно в молоко. Яйца не должны свернуться. Крем хорошо взбить до густоты, снять с огня и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6093,'Растопить в микроволновой печи шоколад со сливками в течение минуты. Глазурь хорошо перемешать. Остывший крем переложить в кондитерский мешок, сделать в эклерах небольшие отверстия и начинить массой. Окунуть готовые изделия в шоколадную глазурь, можно посыпать эклеры с кремом рублеными орехами, дать застыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6094,'Смешать просеянную муку с сахарным песком, всыпать разрыхлитель, соль – по вкусу. Добавить ягоды черной смородины, свежие или размороженные. В другой емкости смешать молоко с растительным маслом, яйцами. Обе массы перемешать. Разложить в формы, печь маффины до готовности в течение получаса. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6095,'Куриное филе нарезать ломтиками толщиной в один сантиметр. Мясо немного отбить, выложить на дно формы, оно должно быть закрыто полностью. Соль и молотый перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6095,'Клубни картофеля нарезать очень тонко, посолить и поперчить, выложить на филе. Полить майонезом и посыпать тертым твердым сыром. Накрыть форму фольгой, печь в течение часа при температуре 180–200 градусов. Через час фольгу снять, картофель по-царски подрумянить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'Из рыбных отходов, моркови, репчатого лука и петрушки сварить бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'Приготовить фарш, смешав для него рыбу, белый хлеб, лук репчатый, соль, молоко, муку, перец и яйцо, смоченными в воде руками сформовать небольшие фрикадельки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'На медленном огне варить подсоленный и процеженный бульон, в который следует опускать запанированные в муке фрикадельки на 10-15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'Для соуса необходимо смешать муку, сметану, лимонный сок или уксус, измельченные корнишоны, соль, все перемешать с выпаренным бульоном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'Полученный соус закипятить и сложить в него готовые фрикадельки, протушить в течение нескольких минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6096,'Рыбные фрикадельки в соусе с корнишонами по-польски в соусе можно подать к столу с кашей, овощным салатом или картофелем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6097,'Форель, лосось или семгу нарезать кубиками. Очистить от кожицы помидор, семена удалить, мякоть нарезать кусочками. Порубить репчатый лук, пропустить через пресс очищенный чеснок. На сковороде с оливковым маслом обжарить лук и чеснок в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6097,'Добавить рыбу, помидоры, соль и молотый перец, свежий или сушеный тимьян. Прогревать в течение 4 – 5 минут. Подлить сливки, перемешать, тушить еще 3–4 минуты. Можно всыпать немного тертого сыра. Добавить отваренные макароны, перемешать, огонь выключить. Выложить феттучини с семгой на тарелки, посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6098,'Смешать заранее просеянную пшеничную муку, соль и сахарный песок. Соединить кефир с водой и влить смесь в муку. Также добавить сырые яйца, взбить массу венчиком, перемешать, разбить комочки, смесь должна быть однородной. Растопить сливочное масло, влить в тесто. Выпечь блины на сухой раскаленной сковороде с антипригарным покрытием. Обжарить блины на кефире до румянца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6099,'Грибы нарезать, сбрызнуть топленым сливочным маслом, смешать с нарубленным чесноком и листочками тимьяна. Печь в духовом шкафу в течение 20 минут при температуре 200 градусов. Смешать любой мягкий сыр и сыр фета, сырое яйцо, соль и молотый перец – по вкусу. Добавить молотый мускатный орех, тертый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6099,'Для приготовления блюда понадобится прямоугольная форма с высокими бортиками. На дно постелить листы готовой, купленной в магазине, лазаньи. Выложить грибную начинку, затем смесь сыров, посыпать «Пармезаном», все слои повторить несколько раз. Накрыть пергаментом, укутать в фольгу, печь в течение получаса, затем фольгу и бумагу убрать, допечь лазанью с сыром и грибами еще 10–15 минут, должна образоваться румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'Дрожжи и сахарный песок растворить в небольшом количестве теплого молока, поставить смесь в теплое место на 15–20 минут. Должна образоваться пенная «шапочка». В оставшемся молоке разболтать соль и сырые яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'Пшеничную муку просеять в большую емкость, влить дрожжи, молочно-желтковую смесь, растопленное сливочное масло. Массу замесить, тест должно быть мягким и липким. Вымешивать в течение 10–15 минут, переложить в смазанную растительным маслом емкость. Закрыть миску пищевой пленкой, поставить в тепло для подъема. Через 1,5–2 часа тесто обмять, дать снова подойти, еще раз обмять через час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'Для начинки тонко нашинковать белокочанную капусту. Натереть морковь, порезать лук, то и другое обжарить на растительном масле. В обжарку добавить сливочное масло, капусту, тушить массу под крышкой, затем её убрать и выпарить жидкость. Соль и перец  добавить в конце приготовления. Снять с огня, остудить, всыпать рубленую зелень. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'Готовое тесто выложить на присыпанную мукой поверхность, разделить на кусочки, скатать в шарики, накрыть пленкой на 10–15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'«Шарики» раскатать в лепешки средней толщины, примерно в полсантиметра. Выложить капустную начинку, защипать. Выложить пирожки на застеленный бумагой противень, швом вниз. Накрыть полотенцем, оставить еще на 20 минут. За несколько минут до выпечки смазать разболтанным яйцом или смесью сырого желтка с молоком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6100,'Печь пирожки с капустной начинкой в течение 20–25 минут при температуре 180–200 градусов. Пирожки должны хорошо зарумяниться. Готовую выпечку смазать растопленным сливочным маслом и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6101,'Песочное печенье измельчить с помощью блендера в крошку. Можно сделать это вручную, скалкой в полиэтиленовом пакете. Растопить сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6101,'Крошку высыпать на дно разъемной формы, залить маслом и перемешать, массу утрамбовать руками или стаканом. Выложить на «корж» вареное сгущенное молоко, следующий слой–очищенные и разрезанные вдоль бананы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6101,'Отдельно взбить сливки с сахарной пудрой, выложить на бананы. Посыпать тертым темным шоколадом. Десерт «Баноффи пай» поставить в холодильник на 1,5–2 часа. При подаче осторожно снять разъемное кольцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6102,'Смешать оливковое масло и винный уксус. Добавить мед и раздавленный чеснок, зернистую горчицу, закрыть банку крышкой. Содержимое встряхнуть в течение двух–трех минут. Перед заправкой салата чеснок убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6103,'Взбить яйца с сахарным песком, добавить разведенные дрожжи, молоко, соль, мягкое сливочное масло, просеянную муку и щепотку ванилина. Можно добавить столовую ложку рома или ликера. Скатать массу в шар, поставить на час в теплое место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6103,'Тесто раскатать в прямоугольник на присыпанной мукой поверхности. Смазать сливочным маслом, посыпать сахаром и корицей. Завернуть в рулет. Разрезать на кусочки с помощью нитки. Синнабоны поставить в посуду для запекания на торец, почти вплотную. Поместить в тепло на 10 минут, а затем выпечь в течение 25 минут при температуре 170 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6103,'Для приготовления поливки смешать растопленное сливочное масло, молоко, сахарную пудру. Полить смесью готовую дрожжевые булочки, дать соусу впитаться в течение двух-трех минут и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6104,'Соевым соусом залить креветки, уложить на них тонко нарезанный лимон или лайм, посыпать измельченным луком, все замариновать в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6104,'Извлеченные из маринада креветки завернуть в полоски бекона, выложить их на решетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6104,'Креветки в беконе запеченные в духовке готовятся 3-5 минут при температуре 2000 С, затем перекладывается на блюдо, украшается зеленью, помидорами черри и ломтиками лайма или лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6105,'Нарезать яблоки, выложить в смазанную оливковым маслом форму. Посыпать молотой корицей, перемешать. Взбить сырые куриные яйца, добавить сахар порциями, продолжать взбивать. Всыпать муку и разрыхлитель, перемешать. Полученной массой залить яблочную начинку. Печь шарлотку с кислыми яблоками при температуре 200 градусов в течение 25–30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6106,'Просеять сахарный песок, пшеничную муку и какао-порошок. Добавить соль, пищевую соду и разрыхлитель. Смесь пересыпать в чашу миксера, влить молоко, вбить яйца, влить растительное масло, можно добавить ванилин из пакетика. Взбить на средней скорости в течение двух минут. Влить кипящую воду, тесто должно получиться жидким. Взбить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6106,'Круглые формы для коржей смазать сливочным маслом и посыпать мукой. Влить полученную массу, печь в течение 30–35 минут при температуре 180 градусов. Готовность выпечки проверить спичкой или зубочисткой, она должна остаться сухой и чистой. Остудить в течение 10 минут, достать коржи из форм и полностью остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6106,'Для приготовления крема взбить сливочное масло, постепенно, порциями, всыпать сахарную пудру, какао-порошок, влить молоко. Добавить ванилин и взбить, масса должна получиться гладкой и однородной. Остывшие коржи шоколадного торта промазать полученной смесью, ею же обмазать верх и бока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6107,'Отделить сырые желтки от белков, белки охладить. До однородной пышной массы взбить желтки, сахарный песок и ванильный сахар. Масса должна посветлеть. Порциями влить растопленное и охлажденное сливочное масло, продолжать взбивать. Всыпать просеянную пшеничную муку, влить йогурт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6107,'Отдельно взбить охлажденные белки и вмешать в основную массу, осторожно, движениями снизу вверх, чтобы масса не осела. Чтобы белки легче взбивались, в них можно добавить щепотку соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6107,'Прямоугольную форму смазать сливочным маслом, вылить тесто, поставить в духовку. Печь в течение часа при температуре 160 градусов. Пудинг из йогурта достать, охладить, посыпать шоколадной стружкой, дать постоять в холодильнике в течение нескольких часов, для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6108,'Смешать в небольшой емкости сливочное масло и жирные сливки. Прогреть, масло должно полностью растаять. Взбить сырые яйца с сахарным песком до пышности, добавить ванильный сахар, всыпать просеянную пшеничную муку, размешать до однородного состояния. Постепенно влить сливочно-масляную смесь, непрерывно помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6108,'Всыпать в тесто крупно нарубленный темный шоколад, перемешать. Смазать маслом и присыпать мукой форму, вылить тесто. Печь сливочно-шоколадный пирог при температуре 170 градусов в течение 35–40 минут. Готовый пирог перевернуть на решетку и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6109,'Яблоки очистить от семян и кожицы, натереть мякоть на крупной терке. Взбить сырые яйца в густую пену, миксером или венчиком, добавить молоко, сахарный песок, тертые яблоки, заранее просеянные муку, какао-порошок, разрыхлитель и растопленное сливочное масло, немного остывшее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6109,'Тесто перемешать и вылить в смазанную сливочным маслом форму. Печь в течение часа при температуре 190 градусов. Готовность выпечки проверить зубочисткой. При подаче шоколадный пирог посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6110,'Взбить творог с яйцами, добавить половину нормы молока, соль и сахарный песок. Всыпать пшеничную муку. В оставшееся молоко всыпать пищевую соду, перемешать. Соединить смесь с творожной массой, взбить. Для начинки обжарить грибы с репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6110,'Разогреть сковороду, налить порцию теста, огонь убавить, накрыть крышкой. Как только низ блина подрумяниться – выложить грибную начинку и сложить его с помощью лопатки пополам. Снова накрыть сковороду крышкой на одну – две минуты. Блинчик-пирожок перевернуть и допечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6111,'Нарубить репчатый лук, нарезать шампиньоны пластинками. Разогреть в толстостенной кастрюле немного растительного масла, обжарить лук в течение 3–4 минут. Добавить грибы, прогревать еще 5–7 минут. В другой емкости растопить сливочное масло, вмешать в него муку, обжарить в течение минуты или двух.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6111,'Постепенно, помешивая, влить куриный, говяжий или овощной бульон. Довести смесь до кипения. Всыпать грибную обжарку, снова довести до кипения. Измельчить массу с помощью блендера. Соль и молотый перец – по вкусу. Подержать грибной крем-суп на тихом огне еще семь минут, влить сливки, дать закипеть и снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6112,'Измельчить с помощью блендера куриное филе вместе с очищенным репчатым луком, молоком, сырыми яйцами и мягким сливочным маслом комнатной температуры. Вместо блендера можно использовать мясорубку. Добавить по вкусу соль и перец, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6112,'Расстелить на столе пищевую пленку, положить на край две ложки получившегося фарша. Закрутить массу в сосиску, немного утрамбовать, пленку отрезать, скрутить, как конфету, связать концы. Таким же образом поступить со всеми сосисками. Варить нежные куриные сосиски в кипящей воде в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6113,'Далее мясо нужно завернуть в пленку и убрать на 4 часа в холодильник, потом пленку снять и мясо обернуть в фольгу, отправить в духовку, прогретую до 200 градусов, минимум на 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6113,'Свиной карбонат с чесноком запеченный в духовке необходимо перед подачей охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6114,'Для приготовления теста смешать предварительно просеянную пшеничную муку, сахарный песок и куриные яйца. Влить тонкой струйкой кефир, в который была предварительно добавлена пищевая сода. Перемешать. Следующий ингредиент – мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6114,'Пятую часть массы вылить в смазанную растительным маслом форму, печь при температуре 25 градусов в течение пяти минут. В духовку поставить какую-нибудь емкость с водой. Таким же образом выпечь еще четыре коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6114,'Приготовить крем: смешать сахарный песок с мукой и яйцами, влить тонкой струйкой горячее кипяченое молоко. Массу быстро перемешивать, чтобы не свернулись яйца. Смесь остудить, добавить сливочное масло комнатной температуры, ванильный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6114,'Коржи промазать получившимся кремом, украсить торт на кефире рублеными грецкими орехами, тертым шоколадом. Поставить выпечку на ночь в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6115,'Вымыть и нарезать свежие грибы, порубить репчатый лук. То и другое обжарить на растительном масле, соль – по вкусу. Натереть любой твердый сыр, добавить измельченный чеснок, сметану и майонез, хорошо перемешать. Очистить и очень тонко, пластинками, нарезать клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6115,'Форму для запекания смазать растительным маслом, влить немного воды, выложить половину картофеля, поперчить, посолить. Смазать получившейся сырной смесью, выложить грибную начинку, сверху–оставшийся картофель и снова сырная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6115,'Картофельную запеканку с грибами поставит в духовой шкаф на полчаса, печь при температуре 250 градусов. В конце приготовления посыпать любой рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6116,'Взбить сырые куриные яйца с сахаром, всыпать предварительно просеянную пшеничную муку, влить молоко небольшими порциями, добавить две–три ложки растительного масла. Выпечь блины на раскаленной сковороде с двух сторон, до образования румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6117,'Перемешать с помощью блендера молоко, сырые куриные яйца, пшеничную муку, добавить соль, сахарный песок и ванилин. Влить растопленное сливочное масло, массу снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6117,'Смазать формочки для маффинов, влить полученное тесто. Печь при температуре 200 градусов в течение 20 минут. В процессе приготовления блинчики надуваются, как шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6117,'Готовым немецким блинчикам дать постоять в выключенной духовке до остывания, аккуратно достать из форм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6118,'Перемешать с помощью кухонного комбайна оливковое масло, лимонный сок, лук-шалот, сушеный орегано, свежую петрушку и чеснок. Соль и перец молотый–по вкусу, масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6118,'Крупные клубни картофеля очистить и нарезать длинными полосками. В большой емкости смешать нарезку с четвертью приготовленного соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6118,'Картофель выложить в блюдо для запекания, одним слоем. Печь до появления золотистой корочки в течение 45–60 минут. В середине приготовления массу перевернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6118,'При подаче картофель по-гречески выложить на блюдо, еще немного сбрызнуть масляным соусом. Украсить веточками зеленой петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6119,'Срезать верхушки у плотных помидоров, довольно осторожно извлечь мякоть при помощи чайной ложки так, чтобы не повредить стенки овоща.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6119,'Смешать с майонезом нарезанную кубиками ветчину и горошек, слегка подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6119,'Подготовленные помидоры нафаршировать приготовленной массой, закрыть срезанными верхушками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6119,'Помидоры с начинкой из ветчины и зеленого горошка охладить и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6120,'Куриную грудку нарезать мелкими кубиками со стороной в пять миллиметров. Посолить и поперчить по вкусу, вбить сырые куриные яйца, майонез, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6120,'В массу добавить рубленый зеленый лук, пшеничную муку, перемешать. Тесто должно быть жидким. Разогреть  сковороду, выкладывать массу столовой ложкой, обжаривать котлеты по-французски с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11120,'Завинтить крышку термоса, оставить на всю ночь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6121,'Перемешать мед и сахарный песок в сотейнике, поставить на тихий огонь. Довести массу до кипения, варить в течение 7–10 минут, до янтарного цвета. Добавить размягченное сливочное масло комнатной температуры, понемногу, частями. Влить нагретые сливки. Варить массу до загустения, капля на холодной поверхности не должна растекаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6121,'Противень застелить хорошо промасленным пергаментом, в противном случае ириски к нему прилипнут. Вылить «ирисочную» массу, дать остыть. Еще мягкие медовые ириски нарезать острым ножом на квадраты или другие фигурки, дать полностью остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'Припустить в сотейнике измельченную квашеную капусту, отварить до готовности сушеные грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'Отдельно обжарить нарезанную кусочками свинину, затем порезанное сало.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'На сковороде пассировать вместе мелко нашинкованный лук и пасту томатную.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'К капусте добавить готовую свинину, сало, лук, грибы и поставить тушиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'Добавить нарезанную кубиками копченую грудинку и колбасу, соль, вино, перец, пассированную муку за 10-15 минут до окончания варки и все перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6122,'Необходимо подавать Бигус по-польски с мясом и квашеной капустой горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6123,'В нижнюю часть духовки поставить противень, застеленный фольгой, с солью, выставить температуру в 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6123,'Некрупную курицу натереть изнутри и снаружи солью и перцем, нафаршировать дольками чеснока, петрушкой, тимьяном. Выложить тушку на решетку, разрез должен быть вверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6123,'Печь курицу а-ля гриль в течение 15–20 минут, перевернуть, продолжать переворачивать через каждые 10-15 минут. Всего на приготовление понадобится час или полтора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6124,'Мягкое сливочное масло комнатной температуры взбить с сахарным песком до состояния крема. Ввести яйца, продолжать взбивать. Добавить заранее протертый творог, ванильный сахар, лимонный сок и цедру. Перемешать массу до однородного состояния. Всыпать пшеничную муку, просеянную вместе с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6124,'Должно получиться мягкое и нежное тесто. Всыпать рубленый миндаль, цукаты. Изюм замочить на ночь в роме, перед добавлением в массу обсушить и обвалять в муке. Все ингредиенты перемешать. Готовое тесто разделить на две равные части, сформовать батоны. Ладонью сделать в каждом углубление ближе к одному из концов, меньшую часть «накинуть» на большую.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6124,'Пирог выложить на противень, предварительно застеленный бумагой для выпечки. Готовить в духовом шкафу в течение часа, если выпечка начнет слишком темнеть–накрыть фольгой или пергаментом и допечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6124,'Теплый бездрожжевой штоллен полить растопленным сливочным маслом, посыпать сахарной пудрой. Когда масло впитается – смазать еще раз и снова посыпать пудрой. Завернуть выпечку в фольгу, пирог должен выстояться в течение двух-трех недель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6125,'В кастрюльке с высокими бортами смешать молоко, сахарный песок или пудру, сливочное масло. Довести смесь до кипения на тихом огне. Огонь увеличить, варить 10 минут, затем выключить, массу остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6126,'Курагу на час замочить в холодной воде. Мелко измельчить в блендере, вбить сырое яйцо, нежирный йогурт, снова взбить. Ввести молотые овсяные хлопья, смесь пшеничных и овсяных отрубей, всыпать пищевую соду и ванилин. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6126,'Печь тесто в течение 15 минут при температуре 160 градусов. Остудить. Корж разрезать по горизонтали на два коржа острым ножом. Для начинки смешать мягкий творог и вишню без косточек. Прослоить массой коржи, поставить десерт в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6127,'Взбить сырые куриные яйца, сахарный песок и мед до образования плотной белой массы, она должна увеличиться в четыре раза. Всыпать просеянную пшеничную муку, перемешать осторожно, движениями снизу вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6127,'Форму для выпекания застелить бумагой. Выпечь бисквит при температуре  170–180 градусов до готовности, проверить спичкой или зубочисткой: она должна остаться сухой. Остудить в форме, аккуратно отделить от стенок ножом и выложить на стол, разрезать на три равных коржа по горизонтали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6135,'Для приготовления заправки смешать дижонскую горчицу, лимонный сок, яблочный уксус. Порциями влить оливковое масло, немного посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6128,'Картофель очистить, нарезать ломтиками, жарить на растительном масле в течение семи минут, должна образоваться румяная корочка. Нарезать репчатый лук, положить его к картофелю, добавить молотый перец, соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6128,'Подлить немного воды и потушить под крышкой пять минут. Залить, разбавленной в соотношении «один к одному», деревенской сметаной с водой, тушить картофель по-деревенски в течение 20 минут, до готовности, под крышкой, на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6129,'Разрезать вдоль небольшие булочки или багет. Натереть плавленые сырки, отваренные вкрутую яйца, добавить мелко измельченный чеснок, майонез, соль–по вкусу. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6129,'Половинки булочек намазать сырной смесью. Тонкими пластинками нарезать крабовые палочки, выложить «цветком», в середину – зернышко консервированной кукурузы, украсить бутерброды «Крабовые цветы» листочками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6130,'Приготовить тыквенное пюре, смешать с сахарным песком, ванилином, водой, всыпать молотую корицу, душистый перец, молотый имбирь. Массу поставить на огонь и довести до кипения. Огонь убавить, варить 15 минут, помешивать до образования густой массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6130,'Полученный сироп хранить в холодильнике, в небольшой баночке с плотной крышкой. В кувшин налить немного готового тыквенного сиропа, добавить горячий яблочный сидр, перемешать. Сверху положить взбитые сливки, сбрызнуть сиропом и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6131,'Мелко нарезать куриную грудку, шампиньоны, репчатый лук, обжарить до готовности на растительном масле. Соль и перец – по вкусу. Добавить сметану, довести массу до кипения. Снять с огня. Недлинный багет разрезать пополам вдоль, вынуть мякиш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6131,'Заполнить приготовленной начинкой, выложить в застеленную фольгой форму. Посыпать блюдо тертым твердым сыром. Украсить дольками помидоров, зеленью, пластинками обжаренных грибов, запекать фаршированный багет в духовке в течение 20 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6132,'Для приготовления блюда понадобится квашеная капуста, её можно приготовить с тмином или добавить его потом, в процессе приготовления. Поместить продукт в кастрюлю с толстыми стенками или в казан. Можно добавить нарезанную морковь, если её нет в капусте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6132,'Порезать кольцами лук-порей, кружочками – «Охотничьи» или «Баварские» колбаски. В массу добавить замороженный шпинат, приправы для овощей. Влить томатную пасту, можно добавить сахарный песок, если смесь оказалась излишне кисловатой. Влить воду, оливковое масло, тушить капусту с баварскими колбасками под крышкой на тихом огне в течение полутора часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6133,'Порезать на четвертинки помытые помидоры, переложить в кастрюлю, налить небольшое количество воды и отправить на огонь, отварить помидоры до готовности, затем через ситечко протереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6133,'К томатному пюре добавить бульон, промытый и очищенный от мусора рис, продолжать варить пока рис не будет полностью готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6133,'Выложить в супницу очищенный и нарезанный тонкими кружочками огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6133,'Перед тем, как снять с огня кастрюлю, суп нужно заправить сметаной и перемешать, затем отставить его до полного остывания и охлаждения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6133,'Холодный суп томатный польский с рисом и огурцом налить в подготовленную супницу и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6134,'Смешать просеянную пшеничную муку, соль и соду. В большой миске смешать сахарный песок, сливочное масло комнатной температуры. Должна получиться кремообразная масса. Добавить сырые яйца, перемешать миксером или вручную. Порциями всыпать мучную смесь, влить натуральный йогурт. Осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6134,'Смешать с водой какао-порошок, разбить комочки. Треть теста перелить в отдельную емкость и перемешать с какао. В «белое» тесто добавить ванильную эссенцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6134,'Форму для выпечки смазать сливочным маслом. На дно вылить половину «белого» теста, затем «темное», снова «белое». Печь кекс с влажной шоколадной начинкой при температуре 180 градусов в течение 45–55 минут. Остудить выпечку в форме, вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6134,'Для приготовления глазури растопить белый шоколад в микроволновой печи или на водяной бане. Полить кекс. Растопить таким же образом темный шоколад и сделать полоски на поверхности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6135,'Выложить на тарелку вымытые листья салата ромен или руккола. Выложить ветчину, нарезанные помидоры и голубой сыр кусочками. Залить заправкой, перемешать, молотый перец–по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'Промытым и разрезанным вдоль пополам огурцам придать форму лодочек, вынув всю мякоть при помощи ложки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'С внешней стороны срезать кожуру огурцов так, чтобы они получились устойчивыми, и посолить их.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'Помидор залить кипятком, затем снять кожуру, порезать его пополам, извлечь семена и сок, мякоть мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'Четверть очищенного репчатого лука, крабовые палочки и сыр мелко порезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'Все соединить, добавить лимонный сок, перец, майонез, соль и перемешать, получившуюся массу выложить в лодочки из огурцов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6136,'Огуречные лодочки с крабовым салатом охлаждаются и подаются к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6137,'Отделить белки от желтков. Взбить первые в миксере на низкой скорости, порциями добавить сахарный песок, всыпать ванилин. Просеять в белковую массу пшеничную муку, осторожно перемешать, движениями снизу вверх.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6137,'Выпечь бисквит при температуре 180–200 градусов в течение 35–40 минут, дверцу духовки не открывать, иначе выпечка осядет. Готовый классический бисквит вынуть, перевернуть на тарелку и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6138,'Смешать порезанный кубиками сыр, сливки, сахар, муку, разрыхлитель, яичные желтки и до однородности взбить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6138,'Из белков яиц сделать устойчивую пену, которую затем добавить к получившейся сырной массе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6138,'В смазанные маслом формочки выложить готовую смесь, далее нужно в глубокий противень составить все формочки, влить в него воду так, чтобы до середины формы были покрыты водой, отправить противень в духовку, разогретую до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6138,'Сырное новогоднее суфле с малиной готовится в течение 30 минут, затем поливается малиной, растертой с сахаром, либо малиновым вареньем и теплым подается к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6139,'Для приготовления коржей смешать пшеничную муку, сгущенное молоко, яйцо, пищевую соду, погашенную уксусом. Тесто должно получиться эластичным, поделить его на восемь кусочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6139,'Раскатать каждую порцию приготовленного теста в лепешки, они должны совпадать по диаметру с размером сковороды. Коржи обжарить по минуте с каждой стороны. Выпечку ровно обрезать, остатки измельчить в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6139,'Для крема смешать молоко, сахарный песок, яйца, пшеничную муку и ванилин. Поставить массу на средний огонь, прогревать до загустения. Снять с огня, добавить в крем сливочное масло, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6139,'Теплым кремом промазать обжаренные коржи, посыпать крошкой. Оставить торт «Светлана» для пропитывания при комнатной температуре на час, затем убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6140,'Отварить очищенные клубни картофеля, нарезать кубиками. Обжарить грибы с репчатым луком. Отварить морковь, свинину, нарезать кубиками. Так же нарезать свежий огурец и натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6140,'Продукты выложить слоями: картофель, грибная обжарка, морковь, свинина, огурец. Все слои промазать майонезом, полить соусом верх салата, посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6141,'Растопить сливочное масло, остудить. Два раза просеять пшеничную муку с кукурузным крахмалом. Смешать в большой емкости сырые куриные яйца и сахарный песок. Поставить смесь на водяную баню, прогревать на тихом огне, взбивать миксером на высокой скорости, масса должна увеличиться втрое. Крем снять с огня, продолжать взбивать еще две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6141,'Поверх массы еще раз просеять муку с крахмалом, перемешать с помощью лопатки. Тонкой струйкой влить разведенный в горячей воде гранулированный кофе, затем – растопленное сливочное масло, снова перемешать. Дать крему постоять в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6141,'Тесто выложить в формочки, печь в течение 10–12 минут при температуре 190 градусов. Готовность выпечки проверить шпажкой или зубочисткой. Кофейные мадленки остудить, вынуть из формочек, посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6142,'Нарезать свинину небольшими кусочками. Посыпать приправой для мяса, смесью перцев, влить столовый уксус  и лимонный сок. Массу перемешать, оставить для маринования на время от двух до шести часов в холодном месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6142,'Рукав для запекания завязать с одной стороны, выложить на дно лук, на него – мясо. Рукав завязать с другой стороны, сделать два – три прокола в верхней части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6142,'Печь при температуре 250 градусов в течение 50 минут. Затем рукав разрезать, блюдо полить выделившимся соком и печь шашлык из свинины еще полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6143,'Куриное филе нарезать мелкими кусочками, репчатый лук – полукольцами, очищенный сырой картофель – тонкими кружками. Смазать растительным маслом форму для запекания. Выложить кусочки филе, посыпать смесью хмели-сунели и черным молотым перцем. Сверху – лук, кружки картофеля в виде «черепицы».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6143,'Натереть твердый сыр, половину массы смешать со сливками. Добавить по вкусу любимые специи, соль, давленый чеснок. Полученной заливкой полить слой картофеля и выложить еще один. Снова полить, посыпать сверху оставшимся сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6143,'Печь куриное филе под картофелем и сыром в течение 35 минут при температуре 200 градусов, запеканка должна покрыться аппетитной золотисто-коричневой корочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Промыть королевские креветки в панцире и с головой в чистой воде. Панцири и головы удалить, обжарить то и другое на растительном масле в течение двух минут, должен выделиться сок. Переложить в мелкое сито, обжать масло, перелить обратно в сковороду, добавить рубленый чеснок и прогреть в течение 30–40 секунд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Обжарить на сковороде «длинный» рис, на среднем огне, в течение одной-двух минут. Влить овощной бульон или воду, довести до кипения, посолить. Тушить под крышкой в течение 25 минут на тихом огне, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Мелко очистить и нарезать репчатый лук, морковь–кубиками, сладкий болгарский перец – соломкой, семенные коробки удалить. Довести до кипения подсоленную воду, отварить размороженный зеленый горошек в течение пяти минут, откинуть на дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Разогреть масло в чистой сковороде, выложить лук, соль и перец–по вкусу. Быстро обжарить в течение минуты или двух. Добавить морковь, перемешать, прогревать до мягкости. Положить в обжарку болгарский перец, готовить еще 4 – 5 минут. Всыпать зеленый горошек, жарить еще одну–две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Почти готовые овощи сдвинуть в сторону, на край сковороды, положить рубленый чеснок, через минуту все перемешать. На креветочных «тушках» сделать на спинке надрез, удалить «черную вену», добавить в овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6144,'Соединить рис с овощами, посолить и поперчить, дать массе настояться в течение пяти минут под крышкой. При подаче рис с креветками, зеленым горошком и перцем посыпать рубленой зеленью укропа, петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6145,'Рис хорошо промыть проточной водой, залить на 15–20 минут кипятком, он должен набухнуть. В кипящую воду положить вилок молодой белокочанной капусты на две – три минуты. Вынуть, разобрать на листья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6145,'Мелко нарезать репчатый лук, натереть морковь, нарезать шампиньоны. В течение нескольких минут спассеровать лук на растительном масле, добавить морковь с грибами, жарить еще несколько минут. В обжарку добавить мелко нарезанный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6145,'Куриное филе пропустить через мясорубку, добавить луково-морковную обжарку, рис, любые специи, массу хорошо перемешать. Для приготовления соуса натереть на терке помидоры, пропустить через сито, отделить семена. Полученную томатную пасту смешать со сметаной. Вместо помидоров можно взять готовую томатную пасту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6145,'Смазать сливочным маслом формочки для маффинов. Выложить по капустному листу, так, чтобы края свисали из форм. В каждую выложить фарш и по одной или две столовые ложки томатно-сметанного соуса. Свободной частью листьев формочки закрыть, можно положить дополнительные листики. Полить сверху оставшимся соусом, запечь ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'С помощью миксера смешать картофельный крахмал, сахарный песок, сухие дрожжи и соль. Всыпать просеянную пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'Молоко прогреть со сливочным маслом в небольшой емкости, остудить в течение минуты. Добавить в массу ванилин из пакетика, перемешать все ингредиенты, включая мучную смесь, с помощью миксера, затем взбить на небольшой скорости. Вбить по одному яйцу, всыпать остатки муки. Замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'Выложить приготовленное тесто в смазанную маслом миску, закрыть, оставить на час. Масса должна увеличиться вдвое.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'Для «начинки» перемешать коричневый сахар, молотую корицу, картофельный крахмал. Тесто раскатать в виде прямоугольной лепешки. Смазать растопленным сливочным маслом, насыпать корично-сахарную смесь ровным слоем, можно воспользоваться ситом. Сформовать рулет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'Изделие нарезать нетолстыми кусочками, раскатать их в лепешки, присыпать остатками коричной смеси с обеих сторон. Сложить лепешки вплотную друг к другу в смазанную маслом форму для запекания, прогреть в духовке до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6146,'Приготовить глазурь из сахарной пудры, ванилина и горячей воды. Массу прогреть до однородного состояния. Полить разваливающийся хлеб с корицей глазурью и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6147,'Отварить картофель в «мундире», очистить и размять в пюре. Всыпать пшеничную муку, посолить по вкусу. Разделить массу в «колбаску», разделить на кругляши, раскатать в лепешки. Обжарить на сухой сковороде в течение двух минут с двух сторон. Горячие норвежские лепешки смазать сливочным маслом и подать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6148,'Крепкое вино влить в кастрюлю, примерно до 70 градусов подогреть на медленном огне, затем засыпать сахар и специи, не переставать мешать пока сахар не растает.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6148,'К вину добавить коньяк, полукольца лимона и апельсина, поварить на слабом огне еще в районе 1 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6148,'Глинтвейн с коньяком по-немецки подается горячим, дополненный свежим апельсином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6149,'Плоды очистить и нарезать кубиками. Переложить в глубокую емкость, полить лимонным соком и посыпать мелким сахарным песком, аккуратно перемешать. Лимонный сок обязателен, он не даст яблокам почернеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6149,'Выложить получившийся продукт в один слой на противень, сушить в духовке в течение полутора часов, до готовности. Яблоки вынуть и дать остыть прямо на противне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6149,'Корицу и гвоздику прогреть на сухой сковороде на среднем огне в течение двух минут. Переложить в ступку, тщательно истолочь, можно воспользоваться блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6149,'В большой миске смешать черный чай, молотые специи и яблоки. Хранить смесь в герметично закрывающейся емкости, например, в жестяной банке. Заваривать яблочный чай, как обычный чай.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6150,'Снять цедру с одного, хорошо вымытого и обсушенного, лимона. Взбить мягкое сливочное масло, постепенно, порциями, добавлять сахарный песок. Всыпать мак и цедру, просеянную муку и кукурузный крахмал, его можно заменить на картофельный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6150,'Вымесить тесто, переложить в прямоугольную форму для запекания, наколоть массу вилкой в нескольких местах, нарезать на небольшие квадраты или ромбы. Печь при температуре 190 градусов в течение пяти минут, температуру убавить и печь еще 20 минут. При подаче посыпать лимонные квадратики с маком сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6151,'Нарезать репчатый лук, обжарить на масле, переложить в жаровню. Консервированную кукурузу отцедить, положить поверх лука. Следующий слой–сырой рис. Посолить по вкусу, добавить пряности. Залить кипящей водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6151,'Куриные окорочка посолить и поперчить, натереть молотой паприкой, выложить на рис. Количество окорочков – по количеству едоков. Жаровню накрыть пищевой фольгой, ленивый рис тушить до готовности в разогретой духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6152,'Репчатый лук нарезать, обжарить, добавить любое копченое мясо, ветчину, нарезанную кубиками. Жарить на среднем огне в течение трех минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6152,'К пшеничной муке добавить соль и перец, влить подогретое молоко, перемешать, масса должна быть однородной, без комочков. Очень тонко нарезать кружочками очищенный картофель. Натереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6152,'Треть картофельной нарезки выложить в форму для запекания, посыпать третьей частью смеси копченостей с луком. Следующий слой – треть сырной массы, полить третьей частью молока. Слои повторить еще два раза в том же порядке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6152,'Блюдо закрыть фольгой, печь картофель с карбонадом и сыром в разогретой духовке в течение 40 минут. Фольгу снять, печь еще 20 минут, до образования румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6153,'Приготовить фарш из свинины, говядины, сырого яйца, солью и перца. Добавить немного отваренного до полуготовности риса, сушеную зелень. Массу перемешать, приготовить небольшие фрикадельки. В течение нескольких минут подержать в морозильной камере, они должны «схватиться».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6153,'Для теста смешать сметану или кефир с сырыми яйцами, солью, пшеничной просеянной мукой, пищевой содой и разрыхлителем, всыпать сухое молоко. Для приготовления можно использовать смесь сметаны и кефира, продукты нужно взять в равной пропорции. В результате должно получиться полужидкое тесто однородной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6153,'Форму смазать растопленным сливочным маслом, вылить тесто, выложить на него фрикадельки, немного вдавить в массу, на половину высоты. Печь при температуре 175–180 градусов в течение получаса. Блюдо вынуть, посыпать тертым твердым сыром и допечь до готовности, должна получиться румяная корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6153,'Горячий пирог с фрикадельками и сыром вынуть из духовки, немного остудить, достать из формы. Подать, нарезав на порции, украсить веточками укропа, петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6154,'Сметану разлить в три емкости, в каждую добавить по столовой ложке сахарного песка. Растопить на водяной бане горький темный шоколад, перелить в первую порцию, перемешать. Во вторую часть добавить вареное сгущенное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6154,'Выложить смеси в стаканы или креманки слоями: сначала шоколадную, затем немного сметаны со сгущенкой, сверху – обычную сметану с сахаром и полить десерт «Геометрия» остатками шоколадной сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6155,'Смешать в емкости большого размера сахарный песок, просеянную пшеничную муку, разрыхлитель, какао-порошок. Добавить соль и пищевую соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6155,'Отдельно взбить сырые куриные яйца с молоком, растительным маслом, ванильным экстрактом. Перелить яичную массу в сухую мучную смесь, взбить в течение двух минут на средней скорости. Влить кипящую воду, перемешать до образования однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6155,'Две формы среднего диаметра смазать растопленным сливочным маслом. Вылить тесто поровну, печь в течение 30–35 минут при температуре 175 градусов. Готовые коржи полностью остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6155,'Отдельно взбить жирные сливки с сахарной пудрой и ванилином в плотную, устойчивую, пену. Промазать кремом коржи, положить слой консервированной вишни. Остатками крема намазать верх и бока торта «Черный лес». Сверху уложить вишни и посыпать тертым темным шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6156,'Перемешать сухое молоко или детскую смесь с какао-порошком. Добавить мягкое сливочное масло комнатной температуры, вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6156,'Поставить на огонь воду, всыпать сахарный песок, прогреть, до кипения не доводить, продолжать помешивать. Готовый сироп охладить, влить порциями в молочно-шоколадную массу, должен получиться густой крем с мягкой текстурой, гладкий, без комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6156,'Форму прямоугольной формы выстлать пленкой, выложить любое печенье к чаю, в один слой. Полить кремом, затем снова печенье, сделать несколько таких слоев. Торт с шоколадным кремом поставить в холодильник на несколько часов для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Для приготовления теста отделить белки от желтков, первые поставить в холодильник. Желтки взбить с сахарным песком, можно воспользоваться блендером, должна получиться пышная светлая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Переложить желтковую массу в миску, добавить просеянную через сито пшеничную муку, аккуратно перемешать, в массе не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Взбить в крепкую, плотную, пену охлажденные белки. Добавить порциями оставшийся сахарный песок, он должен раствориться, а масса стать гладкой и блестящей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Аккуратно, движениями снизу вверх, соединить белки с мучной массой, она не должна осесть. Перемешивать лучше лопаткой из силикона. Переложить тесто в кондитерский мешок или шприц.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Отсадить на застеленный пергаментом противень заготовки для печенья, они должны быть продолговатыми, в виде палочек, длина: 10 – 12 см. Посыпать сахарной пудрой, через сито, два раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6157,'Оставить на 10–15 минут, затем выпечь  до готовности в течение 10–12 минут при температуре 190–200 градусов, печенье «Дамские пальчики» должно приобрести золотисто-бежевый цвет, не пересушивать. Достать выпечку из духовки, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Говяжью печень порезать порционными кусочками и отбить через пленку, затем запанировать в муке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'Тесто вылить в смазанную форму, печь при температуре 180 градусов в течение получаса. Готовый корж остудить и разрезать острым ножом по горизонтали на три части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Для начала нужно обжарить кусочки на масле растительном до подрумянивания с одной стороны, потом их посолить и поперчить, перевернуть на вторую сторону и обжарить также как и первую.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Когда печень будет готова, ее следует переложить на бумажное полотенце, которое впитает ненужный жир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Порезать ломтиками яблоки, очищенные от кожуры, обжарить их на умеренном огне до мягкости на процеженном масле, которое осталось после жарки печени, затем достать из масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Далее в это же масло отправить луковые кольца, добавить соль, карри, паприку и обжарить до легкой мягкости, при этом постоянно помешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Когда все ингредиенты будут готовы, на блюдо выложить сначала яблоки, затем печень, и в конце лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6158,'Перед подачей печень с луком и яблоками по-берлински разогревается в микроволновке 2-3 минуты при полной мощности или 5-7 минут в духовке при 175 градусах.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6159,'Взбить с помощью венчика или вилки сырое яйцо, соль, сахарный песок и пищевую соду. Можно сделать это с помощью миксера. Влить майонез и кефир, взбить. Кефир можно заменить сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6159,'В массу всыпать просеянную муку, перемешать до состояния жидкой сметаны. Белокочанную капусту без кочерыжек тонко нашинковать, посолить и поперчить по вкусу, помять руками, чтобы появился сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6159,'Форму для выпекания смазать маслом. Налить половину теста, выложить капусту, залить второй половиной теста. Печь заливной пирог с капустной начинкой в течение 20–30 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6160,'Клубни картофеля отварить до полуготовности, затем обжарить на сковороде. Сладкий красный болгарский перец нарезать кубиками. Мясной фарш немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6160,'Выложить в горшочки слоями: картофель, фарш, перец, сверху–по кусочку плавленого сыра, залить порции молоком. Печь картофель с мясным фаршем в течение 20–25 минут до готовности. В горячем виде смесь можно перемешать и подать к столу. Украсить листочками петрушки, укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6161,'Смешать сырые куриные белки с сахарным песком, ванилином и лимонной кислотой. Массу взбить с помощью миксера, поставить на водяную баню, продолжать взбивать и прогревать в течение 15 минут. Загустевший, тянущийся белковый крем снять с бани, взбить еще в течение трех минут и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6162,'Смешать молоко и воду, немного нагреть, либо влить в молоко горячую воду. Всыпать сахарный песок и сухие дрожжи. Массу перемешать, оставить на 15 минут, дрожжи должны «заработать», вспениться. Вбить сырые яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6162,'Влить в закваску растопленное сливочное масло, посолить, массу взбить венчиком. Постепенно всыпать просеянную пшеничную муку, перемешать ложкой. Тесто накрыть полотенцем, оставить на час или полтора, в теплом месте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6162,'Готовое тесто раскатать в лепешку толщиной в сантиметр. Вырезать кружочки с помощью кружки или рюмки, стакана. В казане или другой посуде с толстым дном раскалить масло или маргарин, изделия обжарить. Масла должно быть много, лепешки должны в нем плавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6162,'Выложить выпечку на бумажные салфетки, полотенца, чтобы удалить избыток жира. При подаче пончики «Нежнейшие» посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6163,'Сырые яйца взбить с сахарным песком, добавить сметану и размягченный маргарин, продолжать взбивать. Пшеничную муку перемешать с разрыхлителем. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6163,'Противень застелить бумагой, выложить тесто ровным слоем, печь до образования светло-золотистой корочки при температуре 180 градусов. Вырезать кружки из теплого коржа с помощью стакана или формочки. Печенье сложить друг на друга, накрыть пакетом, выпечка не должна засохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6163,'Обрезки от коржа поставить в остывающую духовку и подсушить. Затем измельчить в мелкую крошку для обсыпки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6163,'Для приготовления крема перемешать сгущенное молоко, мягкое сливочное масло. Вместо обычной можно использовать вареную сгущенку. Другой вариант крема: сыр Филадельфия, сгущенное молоко, взбитые сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6163,'Полученным кремом намазать половину кружков, сложить попарно. Обмазать бока, обвалять в крошках. Верх печенья также смазать кремом и обвалять. Поставить пирожные «Домашние» в прохладное место на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Для приготовления теста смешать заранее просеянную пшеничную муку, сахарный песок и соль. Сливочное масло нарезать небольшими кусочками, всыпать в смесь, быстро измельчить в крошку руками или с помощью блендера. Добавить сырое куриное яйцо, так же быстро замесить тесто. Собрать массу в «колобок», немного раскатать между двумя листами бумаги для выпекания, положить на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Через час охлажденное тесто раскатать, выложить в форму, поставить в холод еще на 10 минут. Форму для выпекания застелить бумагой, выложить песочную лепешку, сформовать бортики в 3 – 4 см. Сверху корж застелить бумагой и насыпать фасоль, горох или рис. Печь при температуре 170 градусов в течение 15 минут, груз и бумагу удалить, печь еще 5–10 минут, до готовности. Корж остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Для крема замочить желатин из пакетика в холодной воде на 10 минут. Отдельно взбить сырые желтки. Сварить сироп из воды, сахара, цедры и сока половины лимона. Смесь медленно влить в желтки, продолжать взбивать до пышности, масса должна посветлеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Нагреть сливки, растворить в них желатин. Остатки сливок взбить, смешать с яичным кремом. Добавить сливочно-желатиновую массу, перемешать. Вылить в выстеленную пищевой пленкой форму меньшего диаметра, чем та, в которой выпекался корж. Убрать крем в морозилку до застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Приготовить пюре из малины или клубники. Всыпать 80 грамм сахарного песка, прогреть до 45 – 50 градусов. Еще 40 грамм сахара смешать с пектином, добавить в ягодное пюре. Массу довести до кипения, варить в течение двух минут. Остудить, половину смеси залить в выпеченный корж, поставить в морозильную камеру. Вторая половина пригодится для глазури.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6164,'Нагреть глазурь до 35 градусов. Из формы вынуть застывший крем, полить глазурью. Положить в цент «корзинки» с желе, украсить тарт с лимонным муссом по краям свежей малиной одного размера или половинками ягод клубники.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6165,'Вскипятить воду, подсолить, положить креветки, варить в течение 3 – 5 минут. Полностью охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6165,'Очистить от семенных камер сладкий красный болгарский перец, нарезать тонкими ломтиками. Крупно нарезать хорошо вымытый зеленый салат. От консервированной кукурузы отцедить жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6165,'Все ингредиенты перемешать, посолить по вкусу, добавить майонез, посыпать салат «Сеньорита» сухими прованскими травами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Водой залить фасоль в соотношении 1:5, дать настояться при комнатной температуре в течение 6-8 часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Затем переложить ее в сотейник, влить свежую чистую воду, дать закипеть, затем посолить и отварить до мягкости, убавив огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Чернослив помыть в холодной воде, высушить и измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'С готовой фасоли слить воду, но нужно оставить 3-4 ст.л. отвара, переложить все в чашу блендера и приготовить из фасоли и отвара пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Оливковое масло разогреть в сотейнике, добавить базилик, чеснок, чили и все это прогреть буквально 10 секунд, затем снять с огня и заправить фасолевое пюре, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Далее нужно добавить сливочное масло, сок лимона и чернослив, тщательно перемешать, сверху положить кусочек сливочного масла и переложить в посуду для хранения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6166,'Помазка на хлеб из чернослива и фасоли хранится в холодильнике и подается на стол в качестве холодной закуски.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6167,'Белокочанную капусту тонко нашинковать, положить в кипяток на 10 минут. Нарезать репчатый лук полукольцами, потушить на сковороде с растительным маслом до прозрачности. Добавить фарш, прогревать, пока мясо не посветлеет. Смешать натуральный йогурт с томатной пастой, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6167,'Форму для выпечки смазать растительным маслом, выложить в неё половину приготовленной капусты с фаршем, полить половиной соуса из йогурта. Сверху выложить остатки капусты, полить остатками йогурта, смазать взбитыми яйцами. Запеканку из капусты с куриным фаршем поставить в разогретую до 180 градусов духовку на 30–40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'Для приготовления теста отделить сырые желтки от белков. Первые взбить с сахарным песком и небольшим количеством подогретой воды. Белки взбить отдельно, в крепкую пену, подмешать к желткам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9643,'Взбить сырые куриные яйца с обезжиренным творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'Для приготовления начинки из свежей или размороженной вишни вынуть косточки. Сок слить в сотейник, добавить сахарный песок, молотую корицу, прогреть, сахар должен раствориться. Влить коньяк, виски или вишневый ликер. Готовым теплым сиропом пропитать выпеченные коржи. Отдельно взбить сливки с сахаром и ванилином из пакетика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'На первый корж выложить половину вишни, промазать кремом между ягодами. Другой способ: намазать крем и «утопить» в нем ягоды. Выложить второй корж, операцию повторить. Остатками крема намазать бока и верх торта, украсить рубленым темным шоколадом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6168,'Поставить десерт в холодильник на два часа. Верх торта «Шварцвальдская вишня» украсить целыми вишнями, посыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6169,'Отделить белки от желтков. Перетереть желтки с сахарным песком до побеления. Белки взбить с помощью миксера или вручную, венчиком, в плотную пену. Порциями добавить оставшийся сахар, стакан просеянной пшеничной муки, перемешать. Влить оставшиеся белки и снова осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6169,'Выпечь коржи при температуре 180 градусов. Желатин залить половиной стакана холодной кипяченой воды на полчаса. Затем массу прогреть до растворения, не кипятить. Сметану взбить с сахаром, влить тонкой струйкой желатин и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6169,'Форму с высокими бортиками застелить пищевой пленкой, на дно выложить нарезанные фрукты или ягоды, затем поломанный руками маленькими кусочками бисквит, снова слой фруктов, повторить несколько раз. Всю массу залить сметанной смесью с желатином. Можно заливать послойно. Накрыть сверху бисквитом, прижать и поставить на ночь в холодильник. При подаче бисквитный тортик перевернуть на блюдо, пленку снять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6170,'Просеять в емкость пшеничную муку, пекарский порошок, посолить. Отдельно взбить натуральный йогурт с сахарным песком, сырыми яйцами, цедрой лимона, добавить ванильный экстракт. Порциями ввести сухие ингредиенты в йогуртовую смесь. Влить растительное масло, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6170,'Форму для выпекания застелить пекарской бумагой, смазать маслом и присыпать мукой. Вылить тесто и печь при температуре 180 градусов в течение 50 минут. В небольшой кастрюле смешать лимонный сок и сахарный песок. Варить до полного растворения сахара, сироп должен стать прозрачным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6170,'Готовый горячий кекс в форме проткнуть в нескольких местах деревянной палочкой и полить сиропом. Он должен полностью впитаться, остывшую выпечку вынуть из формы. Для приготовления глазури смешать сахарную пудру с лимонным соком и полить смесью холодный лимонный кекс на йогурте, дать застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6171,'Смешать протертый творог, сырое яйцо, сахарный песок, соль. Пшеничную муку перемешать с разрыхлителем или содой, подмешать к творожной массе в несколько приемов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6171,'Для начинки смешать творог, сахарный песок, яйцо, массу растереть, дать постоять одну-две минуты, перемешать еще раз. Сахар должен раствориться. Можно добавить тертую цедру лимона,  ванильную эссенцию или сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6171,'Формочки для выпекания смазать сливочным маслом. Выложить тесто, равномерно распределить, положить творожную начинку. Печь творожные ватрушки при температуре 180–200 градусов в течение 10–12 минут. Можно выпечь один большой пирог, в таком случае время выпечки увеличится до получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6172,'Отделить белки от желтков. Белки охладить в течение 10 минут. Взбить блендером в плотную пену, всыпать в конце лимонную кислоту и щепотку соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6172,'Творог протереть через сито. Соединить желтки, сгущенное молоко, ванильный сахар, взбить с помощью блендера до однородности. Аккуратно ввести белковую массу, перемешать ложкой или лопаткой, движениями снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6172,'Чашу мультиварки смазать растительным маслом, выложить массу, печь в течение 40 минут в режиме «Выпечка». Готовую запеканку из творога на сгущенке оставить в мультиварке под крышкой на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6173,'Куриные яйца подержать в холодильнике, взбить в пену, масса должна увеличиться в два раза. Отдельно растопить сливочное масло с поломанным кусочками шоколадом, это можно сделать на водяной бане или в микроволновой печи, в пароварке. Взбитые яйца частями добавить в смесь, перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9643,'По желанию добавить фруктозу и сахарозаменитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6173,'Формочки для выпекания обернуть в два слоя фольги. Поставить в глубокую миску или на противень с горячей водой, она должна доходить до середины форм. Печь в духовке, на нижней полке, при температуре 160 градусов в течение 15–20 минут, до готовности. Готовые шоколадные пирожные оставить охлаждаться на два часа или на ночь, вынуть из формочек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6174,'Замесить из пшеничной муки и теплой воды тесто. Накрыть пленкой на несколько минут, пока готовится начинка. Для приготовления фарша мелко нарезать зеленый лук. Натереть тщательно очищенный корень имбиря и чеснок на мелкой терке. Все ингредиенты соединить с мясным фаршем и хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6174,'Разделить на восемь частей и тесто и фарш. Каждую часть теста раскатать в тонкую лепешку диаметром 22–26 см, на нее выложить фарш, закрыв три  четверти части лепешки. Сделать надрезы от краев к центру, накрыть тестом четверть начинки. Свернуть накрытую тестом часть так, чтобы получилась половинка круга. Сложить пополам еще раз, края слепить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6174,'Жарить лепешки на сухой, заранее разогретой, сковороде по 3–5 минут с каждой из двух сторон, при закрытой крышке. Готовые китайские лепешки с мясным фаршем смазать растопленным сливочным маслом, оно должно впитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6175,'Пшеничную муку просеять, перемешать с разрыхлителем, добавить ванилин из пакетика. Растереть сырой куриный белок с сахаром, добавить творог, молоко и растопленное сливочное масло, перемешать. Всыпать муку, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6175,'Готовое тесто разделить на шесть кусочков, каждый – еще на три части. Раскатать на присыпанной мукой поверхности три полоски длиной в 20–30 см каждая, сплести в «косичку».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6175,'Противень покрыть бумагой, выложить изделия, смазать смесью желтка с молоком. Сверху можно посыпать сахарным песком, молотыми грецкими орехами, кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6175,'Оставить творожные косички на 15–20 минут на противне, они должны увеличиться в размере. Печь при температуре 180–200 градусов в течение 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6176,'Форель порезать длинными узкими пластиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6176,'Сливочное масло растопить в микроволновке, лук измельчить, хлеб перемолоть в крошку, грильяж также растолочь в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6176,'Каждый рыбный пластик свернуть в рулетик, одной стороной обмакнуть в растопленное масло и опустить в хлебную крошку, выложить на блюдо, сверху украсить грильяжем и луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6176,'Затем рулетики из форели с грильяжем в хлебной крошке охлаждаются и подаются к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6177,'Растопить горький шоколад со сливочным маслом, можно сделать это на водяной бане или в микроволновой печи. Сырые куриные яйца взбить с сахарным песком, ванильным сахаром, солью. Порциями добавить шоколадно-масляную смесь. В конце взбивания всыпать пшеничную муку. Массу хорошо перемешать, она должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6177,'Формочки для выпекания смазать сливочным маслом, выложить ложкой тесто, посередине положить целую ягоду вишни, свежую или замороженную. Поставить блюдо в духовку на 6–10 минут, печь при температуре 180 градусов. При готовности американских брауни середина должна остаться жидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6178,'Замороженную рыбу нарезать на кусочки, репчатый лук–кольцами, очищенный чеснок–пластинками. Все ингредиенты перемешать с приправами: душистым перцем-горошком, молотой смесью перцев. Залить столовым или яблочным уксусом и любым растительным маслом, лучше использовать оливковое. В маринад можно добавить немного лимонного сока, по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6178,'Маринованную скумбрию с луком можно подать к столу через 20 минут или разложить в банки и поставить на сутки в холодильник. В процессе маринования содержимое банок два раза встряхнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6179,'Мягкий маргарин растереть с сахарным песком и сырым яйцом, всыпать пшеничную муку, соль, гашеную пищевую соду, замесить крутое тесто. Разделить его на две равные части: одну положить в морозильную камеру на 15 минут, вторую раскатать, выложить на противень, намазать любым вареньем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6179,'Натереть на крупной терке тесто из морозилки, насыпать на варенье, начинка должна полностью скрыться. Печь печенье «Натертыш» при температуре 180 градусов в течение 15 минут. Выпечку нарезать квадратиками или ромбиками в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9643,'Добавить нарезанные кубиками грушу и банан.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6180,'Готовое песочное печенье перемолоть с помощью блендера. Растопить сливочное масло, перелить в крошку, перемешать. Формочки для выпекания смазать сливочным маслом, выложить основу, немного утрамбовать, поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6180,'Соединить в блендере творожную массу, молоко и сахарный песок, перетереть до образования пасты. Всыпать в несколько приемов молотую кокосовую стружку и влить сырые куриные яйца. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6180,'Выложить часть начинки на песочную основу, сверху–нарезанные консервированные персики, дольками, залить их остатками творожной смеси. Печь творожники с персиками в течение часа при температуре 165 градусов. Поставить на дно духовки емкость с водой. Готовой выпечке дать полностью остыть в холодильнике в течение нескольких часов, можно оставить на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6181,'Маргарин растереть в крошку с пшеничной мукой, добавить соль и сахарный песок. Половину полученной массы выложить в форму, распределить и на бока. Для приготовления начинки натереть два хорошо вымытых лимона или апельсина, косточки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6181,'Всыпать стакан сахара, столовую ложку картофельного крахмала. Выложить массу на крошку, посыпать сверху остатками. Печь при температуре 180 градусов. Ватрушку остудить, залить готовым апельсиновым желе для торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6182,'Растопить сливочное масло, добавить сахарный песок, сырое яйцо, хорошо перемешать. Влить соду, погашенную столовым уксусом, какао-порошок, просеянную пшеничную муку, тщательно перемешать еще раз. Порубить любые орехи, добавить в тесто. Должна получиться полужидкая масса, поставить ее в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6182,'Наполовину застывшее тесто раскатать шариками. Выложить на противень или на два: между печеньем должны остаться зазоры в несколько сантиметров. Печь шоколадное печенье в течение 15 минут при температуре 180 градусов. Тесто также можно выкладывать на противень мокрой столовой ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6183,'Довести воду до кипения, всыпать рис, варить в течение 5–7 минут. Воду слить, дать остыть. Натереть на средней терке морковь, измельчить репчатый лук и чеснок, его можно пропустить через пресс. Все ингредиенты перемешать с мясным фаршем. Сформовать тефтели с помощью столовой ложки или руками, их нужно смочить водой, чтобы продукт не прилипал. Выложить в форму для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6183,'Для приготовления подливки растопить сливочное масло, обжарить репчатый лук, нарезанный полукольцами. Тушить в течение пяти минут. Добавить морковь, тушить еще пять минут, до мягкости продуктов. Влить томатную пасту, варить в течение полминуты. Всыпать пшеничную муку, прогреть еще одну или две минуты, массу помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6183,'Затем влить теплый куриный бульон, порциями, варить подливу еще 15 минут. Снять с огня и влить жирные сливки. Соль и перец – по вкусу. Залить соусом тефтели. Противень накрыть пищевой фольгой, печь при температуре 200 градусов в течение 40–50 минут. Подать мясные тефтели в качестве самостоятельного блюда или с гарниром, полив его сливочной подливкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Картофель очистить и отварить до полной готовности, затем слить воду и дать подсохнуть картофелю в течение нескольких минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Затем из картофеля сделать пюре, немного его охладить, добавить яичные желтки, муку, сливочное масло и все хорошенько перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Сформовать котлеты из получившейся массы, запанировать их в сухарях или муке и со всех сторон обжарить в масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Для приготовления подливки необходимо холодной водой залить ошпаренные кипятком сушеные грибы на 2 часа, затем отварить при слабом кипении в течение 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Когда грибы будут готовы, их нужно тонко нашинковать, процедить отвар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'На сливочном масле пассировать, постоянно помешивая, мелко порезанный лук, далее добавить грибы и все вместе прожарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Отдельно прогреть муку со сливочным маслом до светло-желтого цвета, снять с огня, тонкой струйкой влить, помешивая, грибной отвар, затем добавить все к грибам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6184,'Соус поварить 10 минут, затем посолить, поперчить по вкусу, перед снятием с огня нужно добавить сметану, затем полить им котлеты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Положить мелко нарезанный чесночок, обжаривать несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'Мак размолоть в кофемолке. В небольшом сотейнике нагреть молоко, добавить сливочное масло, сахарный песок, щепотку соли. Массу почти довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'Отдельно взбить сырые куриные яйца, влить половину горячей молочной смеси, тонкой струйкой, помешивать венчиком, яйца не должны свернуться. Обе молочные смеси перемешать, прогреть на тихом огне до загустения. Всыпать мак, перемешать и остудить. Масса может получиться очень густой, в таком случае её можно разбавить теплым молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'Для приготовления теста необходимо перемешать сахарный песок, немного пшеничной муки и сухие дрожжи, залить остывшей кипяченой водой, оставить в тепле на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'В другой емкости смешать молоко с солью и сахаром. Растопить сливочное масло. Взбить сырое куриное яйцо и дополнительный желток. Все ингредиенты перемешать. Влить дрожжевую закваску, всыпать просеянную муку, замесить тесто, оно не должно быть излишне «крутым». Оставить в тепле на час или полтора, масса должна увеличиться в два-три раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'Ткань или полотенце выложить на поверхность для раскатывания, посыпать мукой. Сверху выложить тесто, раскатать его в большой прямоугольник, края не должны быть толстыми. Выложить начинку, равномерно ее распределить. Свернуть рулет по длинной стороне, разрезать пополам. Каждый вытянуть вдоль, сложить в три раза. Накрыть изделия полотенцем и оставить на полчаса в тепле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6185,'Форму и рулеты с маковой начинкой перед выпечкой смазать маслом, выложить и поставить в разогретую до 200–220 градусов духовку на 40–50 минут. На нижнюю полку поставить емкость с водой. Изделия не должны подгореть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6186,'Взбить венчиком яйца, добавить сахарный песок и соль. Влить кефир или простоквашу, всыпать пищевую соду, влить растопленное сливочное масло, добавить молотый черный перец. Натереть твердый сыр, всыпать в смесь вместе с рубленой зеленью и мелко нарезанным репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6186,'Соединить пшеничную муку с разрыхлителем, вмешать в общую массу, она должна стать однородной. Разогреть вафельницу, выпечь вафли с зеленым луком и сыром, хорошо подрумянить, они должны напоминать чипсы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6187,'В подсоленной воде отварить спиральки или рожки, слить воду, дать макаронам остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6187,'Помидоры и болгарский перец порезать кубиками, тонкими ломтиками нарезать ветчину, на крупной терке натереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6187,'Все подготовленные ингредиенты смешать с консервированной кукурузой, заправить овощной салат по-итальянски с ветчиной, макаронами и сыром майонезом и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6188,'Поджарить измельченный лук с морковью. Добавить любое мясо: свинину, говядину, телятину, можно курятину или индюшатину, порезанную средними кусочками, посолить и поперчить по вкусу. Немного обжарить, затем влить воду и потушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6188,'В другую емкость влить кефир, всыпать соль и пищевую соду, перемешать. Добавить пшеничную муку, перемешать, дать тесту немного постоять, должна набухнуть клейковина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6188,'Отдельно обжарить очищенный некрупный картофель, нарезанный четвертинками. Добавить его в мясную смесь, подлить еще немного воды, продолжать тушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6188,'Тесто тонко раскатать, смазать растительным маслом, раздавленным чесноком, посыпать поверхность рубленым укропом. Свернуть рулетом и разрезать на кусочки по 1,5 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6188,'При готовности картофеля выложить сверху нудли, накрыть крышкой, можно еще подлить воду, тушить на тихом огне 15 минут. При подаче посыпать нудли по-украински свежей петрушкой и рубленым укропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Маргарин и щепотку соли добавить в ¾ стакана воды и закипятить, далее всыпать соду, муку (140 г), растереть так, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Полученную массу отправить на средний огонь, постоянно помешивая прогреть до гладкости, потом снять емкость с огня, добавить яйца и растереть до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Из теста сделать валик диаметром 3 см и разрезать его на трехсантиметровые кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Противень смазать жиром, присыпать мукой (20 г), выложить на него кусочки из теста, отправить в разогретый духовой шкаф.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Пшеничную муку просеять, смешать с сахарным песком и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Готовить пирожки до подрумянивания в районе 15-20 минут, потом убавить нагрев и запечь до готовности, когда пирожки будут готовы не вынимать их из духовки еще несколько минут, потом достать и охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'В кастрюлю с водой добавить жир и потушить в ней мелко нарезанные грибы примерно 10-15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'На сковороде с жиром обжарить муку, добавить бульон и чуть проварить, затем добавить грибы, сметану, соль и вбить желток.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Хорошо перемешав добавить лимонный сок и измельченную рыбу, снова перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'С готовых пирожков срезать верхушки, заполнить их приготовленной начинкой, накрыть верхушками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6189,'Пирожки с рыбно-грибной начинкой из заварного теста отправить в горячую духовку еще на 5 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6190,'Отварить до готовности свеклу и картофель в «мундире». Остудить, кожицу очистить. То и другое нарезать кубиками. Отварить куриные яйца, очистить и отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6190,'Выложить салат на плоское блюдо слоями: картофель, свекла, нарезанные кубиками желтки, кусочки чернослива, белки. Все слои промазать майонезом. Чернослив лучше предварительно залить кипятком на 10–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6190,'Салат сверху также намазать майонезом и посыпать рублеными грецкими орехами. Также можно украсить салат зернами спелого граната. Поставить салат «Графский» в холодильник для пропитывания на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6191,'Измельчить с помощью блендера лед, выложить в стаканы или другую посуду воронкообразной формы. Можно обойтись без блендера, порубить лёд специальным ножом для колки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6191,'Очистить плоды киви, разрезать пополам. Взбить в блендере до однородности киви, апельсиновый сок, натуральный йогурт без вкусовых и цветовых добавок и мед.  Разлить смузи с киви в стаканы на лед, перемешать и сразу подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6192,'Порезать филе на куски, прокрутить, используя среднюю решетку на мясорубке. Добавить в мясо замоченную в молоке и хорошо отжатую булку, размягченное масло, натертый плавленый сыр, вбить яйцо, приправить порубленной зеленью, перцем, солью, очень хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6192,'Сформовать небольшие по размеру котлеты из курицы, обвалять в муке, но лучше в молотых сухарях, обжарить до корочки с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6193,'Порезать перья зеленого лука, зеленые и черные оливки. Сыр перемешать с майонезом в однородную массу, сыр натереть. Все смешать, добавить перец, смазать крекеры сырной закуской с оливками, разложить на плоском блюде и сразу подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6194,'Довести до кипения куриный бульон, добавить шафран, залить мидии вином, поставить на сильный огонь, готовить около 3 минут, достать шумовкой, отвар не выливать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6194,'Грудку порезать, обжарить в разогретом оливковом масле до изменения цвета, переложить в тарелку. В этой же сковороде обжарить минут 5 кусочки чоризо, сложить к мясу, а в полученном масле обжарить порубленный чеснок, лук, добавить тимьян, перцы и чили, обжарить до размягчения около 5 минут. Сковороду лучше использовать с высокими бортиками и широким дном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6194,'Всыпать в сковороду рис, сдобрить паприкой и лавровым листом, обжарить, помешивая пару минут. Залить отваром от мидий, бульоном, добавить чоризо и курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6194,'Поместить сковороду в прогретый до 150 градусов духовой шкаф, держать треть часа до готовности риса, достать, положить помидоры, мидии, масло, специи, потомить паэлью с морепродуктами и беконом еще 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6194,'Быстро обжарить в хорошо прогретом оливковом масле креветки, добавить в сковороду кальмаров, прогреть все вместе около минуты. Уложить на рис кольца кальмаров, креветки и порезанный на дольки лимон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6195,'Взбить яйцо, добавить для ароматизации персиковый сироп (можно любой другой), залить молоком, нагреть, взбивая венчиком на небольшом огне практически до кипения, но кипеть не давать, иначе молоко может свернуться. Дать смеси остыть, поставить очень простое мороженое на 5 часов (за это время перемешать раза 3-4) для полного застывания в морозилку. Готовый десерт разложить по формочкам, оформить шоколадной стружкой, кокосом, дроблеными орехами, облить сиропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Отдельно взбить вилкой сырые куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6196,'Нарезать на маленькие кубики мясо, перемешать с майонезом, грибы – кусочками, протереть на мелкой терке сыр, а белки и желтки отварных яиц — по отдельности в разные емкости. Выложить салат «Ночь» послойно в следующем порядке: смесь мяса с майонезом, кусочки грибов, майонез, яичные белки, опять майонез, сырная стружка, майонез, яичные желтки. Верх салата по вкусу оформить зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6197,'Почистить бананы, обрезать 2,5-3 см суженного края, насадить полученные цилиндры плодов на палочки. Противень небольшого размера или разделочную доску застелить пергаментом, переложить «эскимо» из бананов, оставить (можно на три часа) ночевать в морозильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6197,'Растопить (удобнее на водяной бане или в микроволновке) шоколад, опустить в него бананы так, чтобы они равномерно оделись в шоколадную шубу. Сразу обвалять замороженные бананы в смеси разноцветного конфетти и обжаренных дробленых орехов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6198,'Из муки, маргарина, молока, дрожжей, яиц и соли вымесить тесто, раскатать его пластом в 5 мм, вырезать прямоугольники 6х8 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6198,'Воду подсолить и отварить свежую нарезанную капусту, далее прокрутить ее через мясорубку, слив перед этим воду и отжав капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6198,'Жареное или тушеное мясо порубить, мелко нашинкованный лук обжарить, все соединить с капустой, добавить перец и соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6198,'На подготовленные куски теста уложить валиком начинку, сформовать пирожки и переложить на противень швом вниз, дать пирожкам подойти, а потом смазать их яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6198,'Духовку разогреть и запечь в ней капустные пирожки с мясом до образования румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6199,'Очистить средние по размеру картофелины, разрезать на дольки, если они будут мелкими, то достаточно крестом на 4 части, отварить в подсоленном кипятке до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6199,'Приготовить из масла с соевым соусом, чесноком, солью и специями эмульсию. Слить отвар, картофелю дать остыть, залить эмульсией, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6199,'Смазать противень с высокими бортиками маслом, разложить картофельные дольки, поставить картофель в соевом соусе на четверть часа в духовку, дать приобрести аппетитный «загар».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6200,'Развести соль в воде до получения крепкого рассола, чтобы не тонуло сырое яйцо. Ориентировочно для приготовления литра раствора потребуется примерно 4,5 столовых ложек крупной соли. В полученный рассол положить горошки душистого перца, гвоздички, лавровый лист, прокипятить, дать остыть, процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6200,'Подготовленную вырезку поместить в охлажденный рассол, закрыть кастрюлю крышкой, оставить в холодильнике на пару-тройку дней, несколько раз в день кусок переворачивать, мясо должно плавать в рассоле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6200,'Вынуть мясо, обсушить, положить на наклонную поверхность, придавить грузом, дать стечь излишкам рассола. Втереть с усилием в мясо сухие приправы, а затем не жалея хорошо обвалять в них.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6200,'Смесь специй подбирать по вкусу, но с достаточно большим содержанием красного перца. Он выполняет роль основного консерванта. Обернуть кусок марлей, положить в закрытую посуду, оставить на неделю в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6200,'Достать мясо, обвалять еще раз в специях, поменять марлю на свежую, повесить в хорошо проветриваемое место, например, в кухне на карниз шторы. Вяленое мясо с приправами будет готово через одну-две недели (зависит от размера куска). Мясо лучше готовить в зимнее время, поскольку есть отопление и воздух в кухне более сухой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6201,'Отварить в подсоленной воде со специями печень, дать остыть, крупно натереть, также натереть и сыр, и яблоки, и яйца, нашинковать на мелкий кубик лук. Собрать салат «Печень под шубой» послойно, промазывая каждый майонезом, в следующем порядке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6201,'Разровнять на блюде слой печени, подсолить, далее положить лук, потом яблоки, подсоленные яйца, окончить сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6202,'Нарезать курицу на брусочки или средние кубики, лук–полукольцами, а потом обжарить и переложить на полотенце из бумаги для впитывания излишек масла. Объединить все ингредиенты для салата, приправить майонезом, подсолить, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7614,'Измельчить блендером обжаренные миндальные (часть оставить целыми) и грецкие орехи, добавить пару бананов и взбить до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6203,'Измельчить в пюре по отдельности плоды киви, банана, клубники. Осторожно сложить послойно фрукты: киви, следом банан, закончить клубникой. Убрать на полчаса трехслойный мусс в холодильник, подавать десерт хорошо охлажденным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6204,'Отварить в кипящей воде со специями креветки, удалить панцири. Если есть возможность, то лучше брать свежие, а не отварные и замороженные креветки, тогда они будут более сочными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6204,'Изюминка итальянского салата–соус. Для его приготовления перемешать майонез со сметаной и размятым чесноком, добавить до получения розоватого цвета сладкий кетчуп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6204,'Нарезать или порвать листовой салат, выложить на плоскую тарелку, сверху разложить креветки, облить соусом, украсить нарезанным колечками помидором, подавать к столу охлажденным, можно с сухим белым вином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6205,'В чашу комбайна засыпать муку, подсолить, добавить масло, порубить (сильно мелко не надо) в маслянистую крошку, влить воду из морозилки, вымесить тесто, скатать в ком, сплющить и раскатать в круг. Заполнить тестом подготовленную форму, проколоть его несколько раз вилкой, выпекать основу минут 15 при 200 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6205,'Расплавить в сковороде на сильном огне сахар, следить, чтобы сильно не темнел. Как только цвет карамели станет слегка коричневатым, то в сковороду подлить чуть нагретой воды и перемешать до получения густого красивого сиропа коричневого цвета, сделать средний огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6205,'Погрузить в сироп кусочки яблока, добавить ваниль, перемешать, тушить до размягчения и выпаривания из плодов сока, положить масло, хорошо перемешать. Переложить начинку, пахнущую ирисками, в миску, дать ей остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6205,'Готовую основу для пирога с яблоками и вареной сгущенкой наполнить яблочно-карамельной начинкой, перемешать в блендере сгущенное молоко и яйца, вылить на начинку. Выпекать пирог минут 40 до сгущения заливки при температуре в 170 градусов. Десерт остудить, присыпать сахарной пудрой с орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6206,'Перемешать крахмал с мукой, пекарским порошком, содой, ванильной эссенцией, влить воду до получения кляра жидкой консистенции, нарезать бананы. Обмакнуть полностью кусочки бананов в кляр, обжарить в хорошо разогретом масле до красивого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6206,'Из сахара с водой приготовить в сковороде для бананов золотистую карамель, обмакнуть в нее обжаренные бананы и сразу погрузить в охлажденную в морозилке воду, а затем обсыпать обжаренным кунжутом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6207,'В крошку порубить кусочки маргарина вместе с мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6207,'К дрожжам добавить сахар, молоко, соль, смешать все с мучной массой, сразу же вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6207,'Из раскатанного толщиной в 5 мм теста сделать прямоугольники 6х9 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6207,'Положить на середину каждого прямоугольника тертый сыр, скрутить рулетики, переложить на лист смазанный жиром, дать пирожкам подойти.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6207,'Пирожки польские с сыром плавленым промазать яйцом и отправить в горячую духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'Приготовить желаемое количество тонких блинчиков на молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'Мелко нашинкованный лук пассировать до прозрачности в растопленном на сковороде масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'Затем добавить печень, накрыть крышкой и жарить 12 минут, потом добавить мускатный орех, посолить и влить коньяк.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'С помощью блендера из печеночной смеси сделать пюре, добавить масло и до однородности перемешать, переложить получившийся паштет в керамическую посуду и накрыть, дать полностью остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'Для приготовления соуса нужно вишни без косточек и красную смородину положить в сотейник, влить винный уксус, засыпать сахар и, все время помешивая, варить до загустения на умеренном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6208,'Положить в центр каждого блинчика небольшое количество паштета, края их собрать и с помощью зубочисток или перьев зеленого лука закрепить, рядом налить готовый соус из ягод – вот в таком виде блинчики с домашним паштетом из печени индейки подаются на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6209,'С хлеба срезать корочки и с помощью формочки вырезать канапе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6209,'Нарезанные тонкими ломтиками яблоки, сбрызнуть лимонным соком, лук нашинковать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6209,'На канапе намазать икру, сверху положить нарезанную сельдь, затем яблоко и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'Из маргарина, молока, муки, дрожжей, сахара, яйца и соли приготовить тесто, которое затем раскатать толщиной в полсантиметра и разрезать на прямоугольники размером 6х8 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'В кастрюлю уложить нарезанную тонкими ломтиками печень без пленок, нарезанное кубиками сало, порезанный кольцами лук, влить небольшое количество воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'Потушить в районе 10-15 минут, если нужно – доливать воду, затем порубить до однородности, перемешать с перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'На прямоугольники из теста выложить начинку, придать форму пирожков и разложить на смазанный противень швами вниз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'После того как пирожки с телячьей печенью по-польски подойдут, их нужно смазать яйцом и поставить в духовку, разогретую до средней температуры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6210,'Пирожки запекаются до образования золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Солью натереть тушку не очень жирной утки, в гусятнице разогреть масло и поместить в нее утку, которую на сильном огне обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Затем уменьшить огонь, добавить нарезанный небольшими кольцами лук и тушить, время от времени вливая отвар из грибов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Для приготовления отвара нужно грибы залить 500 мл воды и отварить до готовности на маленьком огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Когда утка будет полностью готова, ее нужно остудить и порезать на 4-6 частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'К соусу, который остался в гусятнице, добавить сметану, муку, рубленые грибы и все перемешать, затем переложить куски утки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Все перемешать так, чтобы утка равномерно покрылась соусом, поставить на плиту и покипятить 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Подсоленным бульоном залить крупу и на сильном огне поварить ее 10 минут, затем положить масло и перемешать, готовую кашу поставить в разогретую духовку, чтобы упрела.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6211,'Утка по-краковски с грибным соусом и гарниром подается следующим образом: на тарелку выкладывается кольцом каша, в центр получившегося круга выкладывается  утка, блюдо поливается горячим соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6212,'Для начинки перемешать репчатый мелко нарезанный лук, сухари и сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6212,'Отбить нарезанное тонкими и широкими пластами мясо и смазать его подготовленной начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6212,'Затем каждый кусок мяса скрутить в трубочку и закрепить зубочисткой, растереть перцем, солью и запанировать в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6212,'Приготовленные зразы из говядины с начинкой из сухарей по-варшавски обжарить на раскаленном масле, сложить в сотейник, влить бульон и протушить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6212,'Перед подачей зразы полить соусом, который получился после тушения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6213,'Нашинковать соломкой очищенный кабачок и баклажан, на сковороде разогреть масло и обжарить в нем овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6213,'К овощам добавить нарезанный лук, спаржу (если есть желание), помидор, все перемешать со сметаной, поперчив и посолив.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6213,'Еще несколько минут все обжарить, далее засыпать тертый сыр, перемешать и переложить полученную смесь в кокотницы, в каждую вбить по яйцу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6213,'Овощной жульен с яйцом готовится около 10 минут в духовке, разогретой до 180-200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6214,'Отварить яйца вкрутую и остудить под холодной водой, почистить, разрезать вдоль пополам и выложить в миску, при этом осторожно вынув желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6214,'К желткам добавить тунца с небольшим количеством его масла, измельченный укроп, мелко натертый сыр, лук, майонез, все перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6214,'Скатать из готовой массы шарики, обвалять их в крошке из фисташек, каждый шарик уложить в половинки подготовленных яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6214,'Яйца с начинкой из тунца и сыра в фисташках перед подачей охлаждаются и украшаются по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6215,'Залить сухофрукты водой, в другой емкости – рис. Налить в казан масло, поставить нагреваться, после появления легкого дымка засыпать полукольца лука, дать ему зазолотиться, затем положить соломку моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6215,'Засыпать в казан сухофрукты, добавить барбарис, налить воды так, чтобы она совсем чуть-чуть прикрыла содержимое, прикрыть крышкой, сделать малый огонь, тушить около получаса без видимого бурления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Орехи разных сортов порубить, натереть цедру одного мандарина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6215,'Промыть рис, высыпать в казан, долить (на пару сантиметров выше риса) воды, тушить минут 40, подсолить, всыпать чуть перца, зиру, готовить без крышки на слабом огне, сильного бурления не допускать не желательно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6215,'Когда уровня воды не будет видно, то проверять его наличие можно пронизыванием деревянной палочкой. При необходимости, если ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6215,'Готовый бухарский плов с сухофруктами накрыть крышкой, дать постоять полчаса, осторожно размешать, переложить ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'Обжарить до подрумянивания на сливочном масле хлеб, нарезанный небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'Натереть на терке очищенный сырой картофель и отжать с него всю жидкость, добавить стакан горячего молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'На оставшейся части молока сварить манную кашу, добавить ее к картофельной массе, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'Яйцо немного взбить, перемешать его с картофельно-манной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'На лепешки поделить получившуюся массу, положить на середину каждой обжаренный хлеб, придать форму галушек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6216,'Галушки из картофеля с хлебом по-польски готовить в кипящей слегка подсоленной воде до полного всплывания, достать и подать на стол, полив сметаной или сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6217,'Порезать очищенные бананы на маленькие кусочки, разложить тонким слоем на тарелке, убрать ее в морозилку на пару часов. Переложить хорошо охлажденные фрукты в комбайн, измельчить до состояния пюре. Можно для вкуса добавить крошку шоколада или любые другие фрукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6218,'Небольшие формочки смазать маслом, растопить с добавлением масла шоколад, используя водяную баню, чуть остудить. Включить для прогревания до 190 градусов духовку. Яйца взбить в густую кремоподобную массу с добавлением сахара, добавить растопленный шоколад, хорошо размешать, всыпать частями просеянную муку, замесить тесто, разложить по формочкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6218,'Выпекать пудинг из горького шоколада треть часа в прогретой духовке пока пудинг не станет подниматься и растрескиваться. Перед подачей к столу присыпать сахарной пудрой или какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6219,'Взбить сметану с яйцами, сахаром и маргарином, смешать подсоленную муку с содой, частями добавить к масляно-яичной смеси, тщательно перемешать до состояния эластичного теста, дать созреть четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6219,'Разделить тесто на комочки, раскатать каждый в лепешку, зажарить лепешки на сметане на малом огне в разогретой сковороде, накрыв крышкой. Вторую сторону лепешек выпекать без крышки. Готовить их можно и без масла, кушать лучше горячими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6220,'Смешать муку, соль, сахар, влить молоко, вбить, перемешивая по одному все яйца. Порезать на ломтики очищенные яблоки сладкого сорта, побрызгать лимонным соком, вмешать в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6220,'Поставить на средний огонь сковороду с толстым дном, растопить масло, прогреть, выложить ложкой небольшие порции теста, выпекать оладьи по-немецки с яблоками до появления дырочек, потом перевернуть на другую сторону, обжарить еще пару минут. Подать со сметаной, вареньем или сгущенкой, а можно присыпать смесью корицы с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6221,'Промыть рис до прозрачной воды, отварить в подсоленной воде вместе с куркумой. Морковку крупно натереть, лук порезать на мелкие кубики, капусту очень тонко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6221,'Обжарить до золотистости лук в разогретом масле, всыпать морковку, жарить, помешивая все вместе около 5 минут. Приготовить фарш, сдобрить перцем, специями, солью, хорошо перемешать. Включить для прогревания до 180 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6221,'Смазать небольшим количеством масла форму, выложить на дно слой риса, разровнять, накрыть слоем капусты, чуть присолить, смазать томатной пастой, слегка разбавленной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6221,'Далее уложить слой из фарша, а на него морковку с луком и промазать сметаной, поставить форму в духовку, вкусная рисовая запеканка с овощами и фаршем будет готова примерно через час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6222,'Перемешать с кефиром размятые с помощью вилки бананы, всыпать промытый изюм. Добавить смесь просеянной муки с разрыхлителем, тщательно все перемешать до образования однородного теста. Заполнить тестом формочки, готовить банановые маффины порядка 40 минут в духовке с температурой не выше 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6223,'Перед приготовлением хлеба муку необходимо просеять. Половину ее, вместе с сухими ингредиентами, пересыпать в миску, добавить масло, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6223,'Влить по частям всю воду, постепенно подмешать остатки муки, должно получиться тесто, не липнущее к рукам. Скатать его в шар, смазать маслом, прикрыть тканью, убрать на час в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6223,'Присыпать стол мукой, положить тесто и последний раз вымесить еще раз, переложить на смазанный маслом противень, смазать маслом, сделать по верху несколько насечек, поставить на 40 минут в прогретую не выше 50 градусов духовку, на дно поставить сковороду с водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6223,'Повысить температуру почти до 200 градусов, готовить белый хлеб при этой температуре полчаса. Достать готовую буханку, спрыснуть водой, прикрыть льняным полотенцем, оставить в покое до остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6224,'Отварить куриное филе в подсоленной воде, остудить (если позволяет время, то, не вынимая из бульона), порезать на средние кубики, на такие же кубики – мясистые помидоры, лук – на мелкие кубики. Вареные яйца разрезать, вынуть желтки, натереть белки и желтки в отдельные тарелки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6224,'Выложить вареный рис на тарелку так, чтобы он напоминал силуэт птички, промазать его равномерно майонезом, уложить поверх кубики из филе, опять майонез. Далее пришла очередь слоя лука и опять майонез, потом – желтки, майонез, наконец, слой из белков и опять майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6224,'Выложить снегирю грудку из кусочков помидора, голову, хвост и крылья из четвертинок (надрезать вдоль) маслин, на место глаз положить помидоры. Зеленые веточки сделать из лука-порея. Оставить салат «Снегирь» на пару часов пропитаться и подать этот празднично-яркий салат к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6225,'Крупно натереть очищенную от кожуры и семян мякоть тыквы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6225,'Колбасу измельчить любым удобным способом и смешать с тертой тыквой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6225,'Яйцо и сливочное масло растереть и смешать с тыквенно-колбасной смесью, добавить соль, муку и перец и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6225,'На сковороде с раскаленным маслом обжарить оладушки из тыквы и колбасы по-польски до подрумянивания со всех сторон, подать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6226,'Начинку из мороженого приготовить накануне. Для этого взбить хорошие сливки в пышную массу, добавить сгущенку, влить экстракт ванили и кофейный ликер, взбить до однородной массы, переложить в лоток, закрыть и отправить ночевать в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6226,'На другой день включить на прогрев до 180 градусов духовку, просеять муку, всыпать какао, сахар (лучше мелкий), добавить небольшие кусочки сливочного масла, растереть руками до образования маслянистой крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6226,'Промазать дно и стенки формы маслом, разложить тесто на дно, захватывая и бортики, заполнить заготовку горохом или бобами, выпекать около 10 минут, охладить. Для приготовления ганаша нагреть сливки до начала кипения, положить кусочки шоколада, убрать с плиты, мешать до получения однородной жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6226,'Выложить на остывшую основу тарта половину ганаша, захватывая бортики. Через треть часа, когда шоколад чуть схватится, положить начинку из мороженого, запаковать пищевой пленкой, убрать на час в морозильник, достать, распределить по поверхности остатки ганаша, охлаждать еще полчаса. Достать хорошо охлажденный тарт в шоколадной глазури, присыпать дроблеными орехами и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6227,'Подготовить мясо, помыть, зачистить, порезать на пласты не толще 1 см, подержать  пару часов в маринаде. На сильном огне хорошо разогреть сухую сковороду, быстро (не более, чем по 2 минуты) припечь мясо с каждой стороны для сохранения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6227,'Прикрыть дно керамической формы нашинкованным луком, на него выложить мясо, прикрыть кружочками помидоров. Полить маринадом, накрыть форму фольгой, запекать (180 гр.) около 40 минут. Удалить фольгу, засыпать верх свинины с помидорами ровным слоем сыра, залить сливками и еще 10 минут подержать в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6228,'Разделать грудку, если есть кожа–удалить, порезать на кусочки, обжарить, специи добавить по вкусу, перемешать, прогреть еще минуту-другую. Порезать овощи, приправить майонезом. Расправить лаваш, выложить мясо, промазать кетчупом, прикрыть двумя ложками овощного салата, разровнять, свернуть лист лаваша конвертиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6229,'Закуска из сушеных грибов в панировке подается прямо в сковороде, а в качестве гарнира используется припущенная в масле свежая петрушка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6230,'Отварить яйца, разрезать вынуть желтки, размять до состояния пасты вилкой, перемешать мягкое масло и коричневый сахар, добавить соль, ванилин, объединить с желтками, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6230,'Разделить массу пополам, одну часть оставить без изменения, во вторую добавить порошок какао, перемешать, подмешать к каждой порции муку. Каждый вид теста (светлое и темное) раскатать в одинаковые пласты (примерно 14х9 см).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6230,'Сложить пласты друг на друга, чуть сжать, положить на полчаса в холодильник. Достать тесто, обрезать ровно края, разделить на 4 одинаковых по ширине ленты. Сложить ленты попарно: светлую на темную, темную на светлую.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6230,'Порезать каждую сложенную пару на брусочки сантиметровой ширины. Разложить песочное печенье «Сабле» на выстланный пекарской бумагой противень, поместить его минут на 15 в духовку с температурой чуть ниже 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6231,'Обернуть в фольгу промытую нечищеную свеклу и до мягкости запечь ее в духовке, затем остудить и почистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6231,'Отваренные вкрутую, остуженные и очищенные яйца пополам разрезать вдоль, аккуратно извлечь желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6231,'К крупно натертой свекле добавить мелко натертые желтки и сыр, измельченный чеснок, перемешать все до однородности с майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6231,'Половинки подготовленных яиц нафаршировать получившейся свекольной массой, сверху положить по порционному кусочку слабосоленой сельди.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6231,'Яйца фаршированные свеклой, сыром и сельдью, украсить рукколой и измельченным зеленым луком, подавать их можно как порционно, так и все сразу на одном блюде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Порезать очень мелко овощи, грудинку, раздавить и измельчить чеснок. Нагреть в глубокой кастрюле, желательно с толстым дном, масло, положить сливочное масло, перемешать и дать маслу растаять. Сложить все овощи, грудинку, чеснок в кастрюлю обжарить минут 7-9, постоянно помешивая, пока овощи не размякнут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Добавить смесь фаршей, равномерно с усилием распределить ложкой по сковороде, чтобы не оставалось комков, обжарить в течение 5 минут до появления коричневатой корочки. Огонь должен быть большой, чтобы фарш зажарился, а не превратился в тушеный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Добавить молоко, размешать, дать закипеть и побурлить при помешивании около четверти часа, до полного впитывания молока в мясо, добавить вино и повторить нагрев, аналогично молоку, должна получиться ароматная масса кремового цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Положить в соус «Болоньез» помидоры и томатную пасту, заполнить освободившуюся из-под помидоров банку водой, вылить в соус, добавить пряные травы и соль, перемешать, разминая помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Убавить нагрев до минимального, прикрыть крышкой, оставить щель для выхода пара, если она без отверстия, тушить пару часов, а лучше дольше, без сильного бурления, периодически, раз в 20 минут перемешивая, соус должен стать густым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6232,'Отключить нагрев, дать постоять под крышкой, отварить макароны, разложить по тарелкам, полить соусом, сразу подать, можно сверху положить несколько листиков базилика, рядом поставить натертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6233,'Для приготовления основания-корзинки измельчить до состояния крошки печенье, перемешать с маслом и яйцом. Заполнить тестом дно формы, смазанной маслом, не забыть сделать еще и бортики, поставить на четверть часа в духовку с температурой 180 градусов (прогреть до нее заранее).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6233,'Положить в желтки крахмал, влить лимонный сок, добавить сгущенку, взбить все вместе. Заполнить полученным кремом готовое основание-коринку, присыпать порезанным на кусочки черносливом. Выпекать американский пирог-торт примерно 12-13 минут. Пока десерт остывает тщательно, до пиков устойчивой формы, взбить сливки и сахарную пудру. Вынуть пирог из формы, оформить сливками и стружкой черного шоколада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6234,'Разрезать каждый пряник вдоль на 3 пластины, несколько штук оставить для крошки, бананы – на кружочки. Всыпать в сметану какао, сахар, взбить до однородности и полного растворения сахара и увеличения крема в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Ввести в муку яйца, добавить орехи, цедру, вымесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6234,'Разложить пряничные пластинки вплотную друг к другу на плоском блюде, просветы заполнить раскрошенными пряниками. Промазать «корж» кремом, уложить бананы, прикрыть их кремом и опять выложить пряники. Повторить все пока не закончатся пряники, верх бананового торта посыпать измельченным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6235,'Хорошо перемешать в небольшой емкости масло со сметаной и желтком, всыпать сахар, размешать. В большую миску просеять муку и разрыхлитель, очень тщательно перемешать, постепенно влить предыдущую смесь, вымесить до получения мягкого теста, не липнущего к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6235,'Придать колобку теста цилиндрическую форму диаметром около 2-3 сантиметров, порезать шайбочками сантиметровой толщины, слегка расплющить, толщина печенья не должна быть более сантиметра, иначе в центре не пропечется.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6235,'Обжарить мягкое ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6236,'Отварить чищенный картофель до полной готовности в соленой воде, слить отвар, положить масло, размять до состояния пюре, вбить яйца, всыпать чуть муки, вымешать до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6236,'Вылепить из нее котлетки или круглые биточки, обжарить картофельные котлеты до золотистости в сильно разогретом масле на среднем огне. Подавать котлеты с любым салатом из овощей, а можно и как дополнение к мясным блюдам, отдельно поставить сметану, кетчуп или грибной соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6237,'Раскатать из готового пласта теста прямоугольник, разложить сосиски, свернуть в трубочку, тщательно обмять края вилкой, можно просто залепить, смазать взболтанным яйцом, обсыпать кунжутом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6237,'Разрезать рулет на кусочки по 5 см, разложить сосиски в тесте на застеленный бумагой противень. Отправить минут на 20 в прогретую до 200 градусов духовку, подавать горячими с горчицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6238,'Залить дрожжи подогретой до теплого состояния водой, подсолить, всыпать порциями муку, вымесить до крутого теста, накрыть его тканью, поставить в тепло для созревания и набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6238,'Почистить спелую (полезнее ярко оранжевого цвета) тыкву, удалить семена, порезать кубиком, объединить с мелко порубленным луком и шкварками, добавить чуть сахара, подсолить, сдобрить помолотым непосредственно перед добавлением (получается более душистым) перцем, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6238,'Готовое к выпечке тесто поделить на небольшие (напоминающие размером грецкий орех) шарики, раскатать их в сочни, как для пельменей. Положить на каждый по ложке начинки, защипать до получения четырехугольной формы. Самсу с тыквой и салом смазать взбитым с водой яйцом, разложить на противень, смазанный жиром. Готовое блюдо подать с охлажденной сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6239,'Развернуть лист армянского лаваша, разделить на две части, положить на каждую половину начинку из сыра и ветчины (можно заменить на колбасу), свернуть, как больше нравится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6239,'Разогреть сковороду, обжарить лаваш с ветчиной и сыром с одной и другой стороны до расплавления твердого сыра, разрезать пополам, подать вместе с острым кетчупом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6240,'Взбить яйца с сахаром, чтобы сахар полностью растворился, и образовалась смесь кремового оттенка. Протереть творог через ситечко, желательно несколько раз, чтобы он был однородным и воздушным. Насыпать в творог манную крупу, затем растопленное масло, соль, потом взбитые яйца, перемешать, поставить в холодильник минут на шестьдесят.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6240,'Тесто сначала будет вязким, некрутым, но когда манка набухнет (в холодильнике), тесто окрепнет. Если есть какие-то сомнения, то можно досыпать чуть-чуть манки или муки – увлекаться не стоит, так как тесто не будет нежным, и кнедлики получатся твердые.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6240,'Приготовить посыпку: потереть батон или измельчить в комбайне. На сковороде растопить сливочное масло, обжарить крошки с сахаром, чтобы получился золотистый цвет. Можно посыпать готовую крошку ванилью, корицей, цедрой апельсина или лимона, кардамоном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6240,'Помыть клубнику (сливы, абрикосы и так далее), убрать плодоножки, веточки, листики (косточки). Вскипятить подсоленную воду в широкой кастрюльке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6254,'Налить в формочку, готовить минут пятьдесят. Сделать глазурь: нагреть сливки, добавить шоколад, мешать, пока все не растворится. Этой глазурью полить шоколадный пирог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Положить порезанный перец и баклажан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6240,'Для лепки кнедликов посыпать мукой доску и руки. Взять кусок теста по размеру, как большой грецкий орех, расплющить в лепешку, осторожно завернуть ягоду. Покатать, чтобы образовался шарик. Положить кнедлики из творога с клубникой в воду, варить минуты три, после того, как она всплывут. Достать шумовкой, обвалять в сухариках.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6241,'Обжарить отдельно друг от друга лук, сладкий перец и шампиньоны. Отваривать в подсоленной воде рис минут десять, пополоскать, остудить. Мелко порезать куриную грудку, обжарить, посыпать специями. Смешать мясо с рисом и овощами, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6241,'Соединить половину сыра, яйца и сметану, залить рисо-овоще-мясную массу. Намазать формочку оливковым маслом, положить массу, посыпать остальным сыром. Готовить запеканка из риса с курицей, овощами и грибами минут 25, соблюдая температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6242,'Взбить желтки с солью, сметаной, сахаром и пивом. Насыпать муку, снова взбить, добавить еще пиво, воду. Взбить в пену белки, добавить в тесто, осторожно размешать. Жарить тонкие блинчики на сковороде, смазанной маслом. Зажаривать только с одной стороны, на которой будет начинка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6242,'Приготовить начинку: перекрутить несколько раз в мясорубке вареную говядину, лук, морковь. Добавить бульон, соль, перец, петрушку. Закрутить начинку в блинчики, смочить в яйцах, взбитых с молоком, обвалять в сухариках, обжарить пивные блинчики с мясной начинкой на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6243,'Потереть крупно картофель. Крупно потереть вареную морковь. Разделить белки от желтков. По отдельности крупно потереть. Подморозить и потереть плавленый сырок. Крабовые палочки измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6243,'Выложить салат слоями, начиная снизу: картофель, крабовые палочки, белки, морковку, плавленый сыр, желтки. Все слои салата крабовыми палочками по желанию посыпать перцем, солью, намазать сметаной или майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6244,'Приготовить крем: подогреть чуть-чуть молоко, в нем растворить желатин. Отделить белки от желтков. Желтки взбить с сахаром до пены. Растереть творог в однородную смесь в блендере, соединить с молоком, потом выложить взбитые желтки. Положить в массу сыр филадельфия. Взбить белки с солью до пиков. Осторожно ввести в крем. Отставить в сторону, чтобы он схватился.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6244,'Приготовить тесто: все соединить, перемешать, разлить по силиконовым формочкам. Выпекать в микроволновой печи минуты четыре. Пышные коржи разрезать вдоль и пополам. Взять силиконовую формочку, чуть-чуть присыпать дно просеянным какао, положить подзастывший крем, посыпать какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6244,'Заварить сладкий кофе, можно добавить ароматизатор, например, ром. Обмакивать тесто в кофе, сразу доставать и выкладывать на крем. Затем опять какао, повторять, пока не закончатся коржи. Поставить в холодильник, ждать, пока застынет крем. Поставить форму в горячую воду, чтобы краешки отошли от формочки, перевернуть торт «',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6245,'Нарезать кусочками филе сельди, оливковое масло и горчицу перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6245,'В баночку положить перец-горошек, лист лавровый, уложить слой сельди, мелко нарезанный лук, залить половиной горчичного соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6245,'Затем положить в такой же последовательности все остальные ингредиенты, посыпать измельченным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6245,'Банку, закрытую крышкой, подержать в холодильнике минимум на 12 часов, затем кусочки рыбы переложить на плоское блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6245,'Сельдь закусочная под горчичной заливкой посыпается зеленым луком перед подачей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6246,'Сделать бисквит: смешать в емкости обычный и ванильный сахар, яйца. Взбивать минуты три миксером на большой скорости. Налить молоко. Добавить растительное масло. Насыпать муку, разрыхлитель, размешать миксером до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6246,'Застелить формочку 19 на 19 сантиметров промасленной бумагой, готовить минут тридцать, соблюдая температуру 180 градусов. Чуть-чуть остудить. Перевернуть, убрать бумагу. Приготовить соус: соединить в кастрюльке сахар, молоко, шоколад и какао, довести до кипения. Охладить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6255,'Отварить до готовности хорошо промытый картофель в мундире, затем остуженный и очищенный прокрутить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'Смешать муку, яйцо, сахар, соду, сливочное масло и сметану, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6246,'Разрезать бисквит на шестнадцать кубиков. Тонко обрезать краешки. Обмакивать четыре стороны в соус. Каждую сторону держать по пятнадцать секунд, чтобы хорошо пропитались. Дать стечь. Обмакнуть с четырех сторон в стружку кокоса. Поставить нежные бисквитные пирожные на дно, верх чуть-чуть смазать соусом, посыпать стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6247,'Растопить и смешать шоколад со сливочным маслом. Можно растапливать на тихом огне, не переставая мешать, чтобы не пригорело. Положить сгущенное молоко, размешать. Насыпать в крем стружку кокоса, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6247,'Положить крем «Рафаэлло» в стеклянную баночку, поставить в холодильник часа на четыре. Если крем сделан для украшения торта или пирожного, то можно применять сразу. А уже готовое изделие поставить в холод для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6248,'Отварить яйца, остудить, почистить, измельчить. Добавить майонез, размешать. Помыть свежие огурцы, потереть на терке для корейской моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6248,'Собрать бутерброды: чуть-чуть намазать хлебцы майонезом, положить огурцы, сверху яйца, на них куски горбуши. Бутерброды с огурцом и горбушей по желанию можно украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6249,'Измельчить лук, пожарить на растительном масле. Отварить яйца, охладить, почистить, порезать на кубики. Порезать на кубики мясо курицы. Свежий огурчик порезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6249,'Соединить все продукты, положить корейскую морковку. Посыпать перцем, солью. Заправить салат «Шедевр» с копченой курицей майонезом. Выложить салатик на блюдо, украсить измельченным зеленым лучком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6250,'В сковороде растопить на маленьком огне сливочное масло. Разбить в емкость яйца, чуть-чуть взбить венчиком, налить сливки, посыпать солью. Перемешать. Налить на сковороду с маслом. Лопаткой подтягивать краешки яичницы к середине, быстро перемешать болтунью. Через секунд сорок убрать яичницу с огня, добавить песто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6250,'Порезать на ломтики помидор, положить на тарелку. Положить яичницу, украсить кусочками прошутто. Приправить яичницу-болтунью с прошутто молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6251,'Помыть апельсины, тоненько порезать на ломтики вместе с кожурой. Убрать косточки, положить в «мешочек», сделанный из марли, сложенной в несколько слоев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6251,'Налить в кастрюльку яблочный сок, положить порезанные апельсины и «мешок» с косточками. Довести до кипения, готовить минут сорок на тихом огне – цедра должна стать мягкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6251,'Насыпать сахар, готовить, перемешивая, минут пять, чтобы сахар растворился. Увеличить огонь, минуты четыре смесь должна покипеть. Убрать с огня, снять пену, достать косточки. Подождать минут пятнадцать, чтобы апельсиновый мармелад остыл. Разложить по теплым стерилизованным банкам, закатать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6252,'Почистить стейки семги, посыпать перцем, солью, обложить лимонные дольки. Завернуть рыбку в фольгу, положить на противень. Готовить минут двадцать, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6253,'Отделить желтки от белков, разлить по различным емкостям. В обе емкости насыпать по 1/2 стакана сахара. Размешать блендером, чтобы получились однородные массы. Вместо блендера можно применять венчик. В каждую емкость насыпать по 1/2 стакана муки, перемешать до однородности блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6253,'Взять одну из емкостей, вылить содержимое во вторую емкость, снова все взбить. Благодаря отдельному взбиванию белков и желтков, тесто получается очень пышным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6253,'Формочку, например, силиконовую, намазать сливочным маслом, на дно положить почищенные от кожуры и семечек груши, яблоки или порезанные бананы. Насыпать чуть-чуть вишни. Залить приготовленным тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6253,'Готовить пирог «Любимый» минут двадцать, соблюдая температуру 200 градусов. Готовность проверять зубочисткой, она должна с легкостью проходить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6254,'Разогреть духовку до 160 градусов. Взять формочку 26 сантиметров, застелить пергаментом. Поломать шоколад на куски, положить масло, налить молоко, растопить на водяной бане, перемешать до однородной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6254,'Взбивать яйца и сахар, пока масса не увеличится раза в два. Соединить какао, муку и разрыхлитель, просеять, насыпать в яичную смесь. Аккуратно и быстро размешать, налить шоколадную смесь, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Подавать лучше сразу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6256,'Поломать горький шоколад на плитки, сложить в огнеупорную емкость. Посыпать специями. Налить сливки, добавить молоко. Довести до кипения, помешивая венчиком. Разлить горький шоколад по чашечкам и подавать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6257,'Почистить и помыть желудки. Варить минут сорок, добавив приправу для супа. Почистить и порезать лук, крупно потереть морковь. Обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6257,'Достать желудки из бульона, порезать. Положить к овощам, обжарить. Налить в сковороду немного воды, положить сметану, выложить зажарку, посыпать перцем. Размешать, готовить куриные желудки со сметаной под крышкой минут пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6258,'Соединить масло, сахар и шоколад, нагреть на водяной бане. Размешивать, чтобы получилась однородная смесь. Положить коричневые и белые шоколадные чипсы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6258,'Когда шоколад растает, положить половину чашки сгущенного молока. Остудить. Положить в шоколадную массу сгущенку и лед. Смешать с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6258,'Подавать горячий шоколад со взбитыми сливками, мини-шоколадной стружкой и маршмеллоу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6259,'Пакетики с желе растворить и разлить по цветам по емкостям. Залить желатин холодной водой, отставить для набухания, затем разогреть, чтобы весь желатин растворился. Разлить жидкость по чашечкам с цветным желе. Размешать, поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6259,'Залить желатин холодной водой, отставить, чтобы он набух. Положить в чашку застывшее цветное желе, порезанное на кусочки. Взбить с помощью миксера чуть-чуть сметану с ванилином, сахаром, лимонной кислотой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6259,'Нагреть желатин до полного растворения, тоненькой струей влить в сметанную смесь. Размешать миксером, положить к порезанному желе. Размешать все ложкой, положить в формочку, например, силиконовую, отставить десерт «Осколки счастья» часа на два для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Растворить дрожжи в молоке. Положить в большую емкость все ингредиенты для теста, кроме масла. Перелить в тесто дрожжевую смесь, замесить эластичное тесто. Месить на протяжении трех минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Сделать из теста квадрат небольшого размера, положить на поднос, посыпанный мукой, накрыть пакетом, завернуть краешки, чтобы не проходил воздух. Отправить поднос часа на два в холодильник, лучше поставить на ночь. Крупно натереть сливочное масло, отправить в холодильник, чтобы не растаяло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Посыпать стол мукой, достать тесто и масло из холодильника. Раскатать тесто в квадрат приблизительно 40 на 40 сантиметров. В середину положить натертое масло, распределив его по всей поверхности. Завернуть краешки внахлест, хорошо защипнуть. Нужно делать это, как можно быстрей, чтобы практически не нагревать тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Раскатать квадрат в продольном направлении. Каждый раз чуть-чуть приподнимать тесто, чтобы оно не прилипло к поверхности. Длина прямоугольника должна быть приблизительно в три раза больше, чем ширина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Сложить тесто втрое, в виде делового письма. В середине сделать пальцем углубление. Переложить тесто на блюдо, посыпанное мукой, накрыть полиэтиленом. Отправить минут на тридцать в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Снова раскатать тесто, поднимать, сделать три углубления. Раскатать четвертый раз, чтобы получился прямоугольник 30 на 75 сантиметров, в толщину 4 миллиметра. Разрезать тесто вдоль на две части. Порезать полосы на 6 или 7 прямоугольников с основанием 9 сантиметров. В каждом сделать надрез.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Взбить яйца и молоко. Намазать яйцом поверхность круассанов, краешки оставлять свободными. Начинать заворачивать треугольники от основания, осторожно растягивая их в стороны надреза. Во время сворачивания не сжимать сильно тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6260,'Положить круассаны на противень, намазать яйцом, поставить в тепло часа на два. Нагреть духовку, снова смазать яйцом, поставить в духовку. Готовить минут двадцать, соблюдая температуру 220 градусов. Охлаждать классические круассаны на решетках.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6261,'Тоненько порезать огурец и авокадо. Порезать тонкими слайсами лосось. Положить нори на циновку. Разложить на «шершавой» поверхности нори рис, чтобы он покрывал весь лист. Перевернуть нори вниз рисом. Промазать вдоль васаби. Положить сыр, авокадо, огурец на середину нори.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Они должны почти касаться друг друга.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6261,'Свернуть ролл, осторожно выровнять краешки. На не разрезанный ролл сверху положить слайсы лосося, при помощи циновки придать форму. Можно обработать рыбку при помощи горелки. Осторожно порезать ролл филадельфия на 8 частей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6262,'Перетереть творог. Положить ваниль. Не переставая растирать, вбивать по одному яйцу. Насыпать сахар. Добавить ромовую эссенцию. Насыпать манную крупу, размешать. Налить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6262,'Насыпать разрыхлитель, положить сухофрукты, размешать. Отставить минут на двадцать, чтобы лишняя жидкость впиталась в манку. Намазать противень маслом, посыпать панировочными сухариками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6262,'Положить массу на противень. Намазать запеканку из творога сметаной, чтобы образовалась золотистая корочка. Отправить в духовку минут на пятьдесят, готовить при 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6263,'Соединить масло и шоколадные капли, растапливать в микроволновой печи секунд тридцать, чтобы полностью растаяли, перемешать. Насыпать сахар, размешать. Добавить яйцо, ванильный экстракт, размешать венчиком. В отдельной емкости смешать соль, муку, какао, соду. Соединить смеси, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6263,'Расстелить полиэтилен или специальную бумагу, из теста сформировать колбаску, положить на пленку, завернуть, затянуть кончики. Отправить на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6263,'Разогреть духовку до 180 градусов. Холодную колбаску вынуть из холодильника, порезать на кружочки. Застелить противень бумагой, разложить кружочки. Готовить минут семнадцать. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6263,'Взбить сливочный сыр, насыпать сахарную пудру, налить молоко, размешать. На одно печенье положить начинку, другое смазать арахисовым маслом, соединить. Повторить процедуру с остальными печеньями «Choco pie».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6264,'В большую емкость просеять муку. Насыпать дрожжи в теплое молоко. Размешать. Накрыть, поставить минут на двадцать в тепло. Спустя время насыпать в молоко с дрожжами сахар, соль, добавить желтки. Взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6264,'Положить теплое сливочное масло. Размешать. В муку влить получившуюся смесь. Замесить тесто. Накрыть, отправить минут на сорок тепло, чтобы тесто поднялось.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6264,'Посыпать мукой стол, раскатать тесто в толщину 1 сантиметр, вырезать пончики, отставить минут на тридцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6264,'Разогреть масло. Обжарить со всех сторон пончики. Пончики должны на половину быть покрыты маслом. Положить воздушные пончики на салфетки, посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6265,'Почистить фрукты от кожуры, порезать на большие кусочки, убрать косточки из винограда. Порезанные киви, банан, яблоко и виноград в блендер, налить стакан предварительно приготовленного чая. Взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6266,'Нашинковать капусту, посыпать солью, тщательно обмять руками. Положить кукурузу, зеленый горошек. Порезать на кубики колбасу и яйца. Добавить в салат. Заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6267,'Смешать в блендере разрыхлитель, муку, соль, сахар, мягкое масло. Размешать, чтобы получилась песочная крошка. Налить молоко, перемешать. Вбить яйца, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6267,'Обдать кипятком апельсины, при помощи мелкой терки снять цедру. Из апельсинов выдавить сок, вылить в тесто. Если тесто становится очень жидким, то насыпать чуть-чуть муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6267,'В практически готовое тесто добавить цедру, размешать. Положить тесто в маленькие формочки для кексов, поставить в духовку. Выпекать до готовности – проверять спичкой. Достать кексы из формочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6267,'Приготовить крем: смешать творожный сыр, ваниль, корицу, пудру, чуть-чуть сушеной цедры или цукатов. Перед подачей украсить апельсиновые капкейки шапочкой из крема.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6268,'Разделить молоко пополам. Одну часть нагреть до теплого состояния, снять с огня, медленно насыпать сахар, муку и соль, быстро размешать венчиком до однородности. В полученную молочную смесь вбить яйца, размешать. Вылить вторую часть молока, чуть-чуть растительного масла, чтобы блинчики не прилипали к сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6268,'Во время выпекания не нужно смазывать сковороду маслом. Набирать блинную массу в половник, в другую руку брать сковороду, выливать тесто из половника, вращая сковороду, чтобы оно растеклось. Переворачивать, когда подрумянятся краешки. Взять руками блин за края, перевернуть, готовить секунд тридцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6268,'Так выпекать все блины. На середину всех тонких блинов на молоке положить кусок сливочного масла, завернуть трубочками. Отправить в микроволновую печь секунд на сорок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6269,'Растворить в части молока дрожжи и сахар. Процедить. Долить остальное молоко, вбить яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6269,'Насыпать муку, соль, размешать до однородности. Поставить в тепло часа на полтора, накрыв полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6269,'Обмять и жарить на сковороде, желательно чугунной, политой маслом. Дрожжевые оладушки должны быть приблизительно 6 миллиметров в толщину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6270,'Подготовить необходимые продукты. Отварить яйца, крупно потереть. Крупно потереть плавленый сыр. Соединить в емкости яйца, сыр, прессованный чеснок, заправить майонезом, размешать, измельчить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6270,'На краешек всех кусочков ветчины положить чуть-чуть начинки, свернуть рулетики. Перевязать их полосками сыра. Краешки закуски «Вкусные свитки» обмакнуть в майонез, а потом в измельченную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6271,'В посуду среднего размера вбить яйца. Насыпать муку и щепотку соли. Налить молоко, хорошо перемешать при помощи венчика, чтобы получилась однородная масса. Тесто должно быть чуть-чуть гуще жидкой сметанки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6271,'Намазать сковороду растительным маслом, сильно разогреть. Из теста приготовить не очень тоненькие блинчики. Хорошо промыть свежую зелень укропа, подсушить, измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6271,'Блинчик смазать небольшим количеством майонеза, посыпать измельченным укропом. Сверху положить ломтики сыра. На него порезанную ветчину. Блинчик с начинкой свернуть рулетиком. Такую процедуру сделать с остальными блинчиками. Порезать закусочные рулетики из блинов одинакового размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6272,'Соединить манную крупу, творог, обычный и ванильный сахар, перемешать. Отправить творожную смесь минут на двадцать в холодильник. Поделить на шарики одинакового размера. Внутрь положить по ягодке клубники. Придать форму сырников.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6272,'Обвалять их в муке, пожарить на сковороде до румяного цвета со всех сторон. Накрыть крышечкой, выключить огонь, подождать минут десять, чтобы они дошли. Остудить. Взбить к сырникам из творога с клубникой сметану с сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6273,'Положить на фольгу: порезанный картофель, репчатый лук, порезанный кольцами, порубленный куриный окорочок, чесночок и чернослив, порезанные на маленькие кусочки, измельченные грецкие орешки, помидорки, порезанные на кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6273,'Посыпать все перцем, солью. Завернуть фольгу. Отправить в духовку минут на девяносто, соблюдать температуру 210 градусов. Можно поставить куриный окорок с овощами и черносливом в фольге на угольки костра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6274,'Соединить яйца и сахар, насыпать муку. Сделать негустое тесто. Намазать маслом сковороду или противень, посыпать мукой, с помощью ложки положить тесто. Оно должно чуть-чуть растечься. Разровнять лепешки ложкой. Нагреть духовку. Поставить противень, готовить лепешки до желтого оттенка и румяных краев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6274,'Горячие лепешки достать и свернуть с одного края. Чтобы не остыло и не поломалось тесто, делать это необходимо очень быстро. Можно сворачивать просто руками, а можно одеть хозяйственные перчатки. Бисквитное тесто довольно податливо, пока горячее, поэтому останется в таком виде, в каком свернули. Можно сделать любой масляный крем для быстрых пирожных: чем больше масла, тем лучше будет форма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6274,'Соединить сахар и муку, вбить яйцо, размешать. Налить теплое молоко, перемешать, поставить на огонь. Готовить, непрерывно мешая. Когда крем станет густым, убрать и охладить. Когда он будет холодным, положить подтаявшее сливочное масло и ванилин. Взбить до однородности. Остудить. С помощью кондитерского шприца или обычного пакетика выложить крем в подготовленные лепешки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6275,'В воду насыпать желатин и отставить минут на десять. Налить в кастрюльку молоко, положить мед, сливки, поставить на огонь, довести до кипения, убрать. Положить шоколад, размешивать до растворения. Положить желатин, перемешивать, пока не растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6275,'Добавить йогурт, интенсивно взбить. Разложить массу по формочкам, отставить минут на двадцать. Перед подачей панна коту из шоколада остужать минимум четыре часа. Украсить тертым шоколадом или взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6276,'Сыр порезать некрупно, положить в небольшой сотейник, поставить на огонь. Когда сыр подтает, налить сливки, размешать, довести до кипения. Из-за плесени не получится абсолютно однородной массы, но так и должно быть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6276,'Нарезать мясо поперек волокон на кусочки по два сантиметра. Обжарить до золотистой корки с двух сторон, приправить солью, перцем, готовить. Подавать индейку с соусом из голубого сыра в горячем виде. На гарнир лучше всего подходят овощи или рис.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6277,'Нарисовать на листе бумаги контуры будущего торта, чтобы сделать одинаковые коржи. В данном случае 25 на 18. Сначала заварное тесто выложить по контуру. Насадка с круглым отверстием. Нарисовать полоски вдоль, а потом поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6277,'Выпекать до румяного оттенка, соблюдая температуру 200 градусов. Следующий корж делать по-другому, а именно, вторые полоски – косые. Коржей должно быть четыре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6277,'В отверстие положить фрукты, намазать кремом. Но можно сделать наоборот – намазать кремом, сверху положить порезанные фрукты, например, персики, вишню, бананы. Накрыть коржом и придавить. Намазать кремом, украсить белым шанти. Положить сверху фрукты: черешню, бананы, груши, персики. Отправить летний торт «Тропиканка»в холодильник для застывания и пропитки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6278,'Приготовить соус: в лимонный и апельсиновый сок насыпать сахар, закипятить, положить масло. Если смесь жидковатая, то положить чуть-чуть крахмала, разведенного в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6278,'Просеять муку, сахар и соль. Взбить молоко, яйца, свекольный сок и сливки. Все ингредиенты класть по очереди, мешая каждый раз. Отставить минут на шестьдесят, насыпать мак, обжаривать с двух сторон на сливочном масле, складывать розовые блины треугольником.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6279,'Поделить цветную капусту на соцветия, положить в блендер. Взбить, чтобы были небольшие куски, положить в блендер другие ингредиенты. Взбить размешать. Налить оливковое масло на сковороду, обжарить оладьи из цветной капусты до золотистой корки с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'Обжарить на масле промытые, очищенные и порезанные пластиками грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'Сладкие перцы промыть, извлечь семена и нашинковать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'Зелень помыть, просушить и порубить, надавить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'Масло, уксус, надавленный чеснок, перец и соль перемешать для приготовления заправки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'На дно салатника выложить листья салата, разложить перец и грибы, посыпать зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6280,'Полить готовой заправкой салат из грибов и сладкого перца и поставить на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6281,'Налить в кастрюльку воду и поставить на огонь. Порезать картофель, мелко порезать морковь и лук. В кипящую воду переложить картофель, соль и лавровый листик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6281,'Обжарить на сливочном масле морковь и лук до мягкого состояния, налить в конце сливки. Положить к картофелю макароны. Положить в емкость плавленый сырок, налить чуть-чуть горячего бульона, мешать, пока не растворится сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6281,'Положить подготовленный сыр в кастрюлю с картофелем и макаронами, добавить обжаренные овощи со сливками и ветчину, порезанную на кубики. Варить сырный суп со сливками и ветчиной пару минут после закипания. Посыпать перцем, зеленью. Сделать сухарики: порезать на кубики хлеб, подсушить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6282,'Почистить кальмары, пока они не разморозились, отварить грибочки. Измельчить лук, кальмары порезать на полосочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6282,'Обжаривать лук, кальмары и грибы не больше трех минут, чтобы кальмары не стали резиновыми. Переложить полученную смесь в огнеупорную прозрачную формочку с высокими краями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6282,'Смешать сметану с майонезом 1 к 1, залить смесью блюдо. Посыпать сверху сыром. В майонезе достаточно соли, поэтому ее добавлять совсем чуть-чуть. Отправить грибной жульен с кальмарами в духовку, готовить минут пять, после закипания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6283,'Соединить в емкости соль с мукой. В небольшой миске смешать молоко с водой. Подогревать шестьдесят секунд в микроволновке при полной мощности. Вылить горячую молочную смесь в муку, размешать вилкой. Вылить воду с молоком в муку, размешивать вилкой, пока тесто не загустеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7621,'Посыпать яичницу «Миш-маш» на завтрак по-болгарски измельченной зеленью петрушки, подавать блюдо горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6283,'Взять кухонную доску, чуть-чуть посыпать поверхность мукой. Положить тесто на доску, месить секунд шестьдесят. Разделить тесто пополам. Из каждого кусочка сформировать шар, накрыть минут на пять влажной салфеткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6283,'Из одной части раскатать скалкой круг среднего размера. Руками хорошо промазать его растительным маслом и вновь раскатать. Накрыть влажной салфеткой минут на пять. Сделать то же со второй частью. Повторите все то же со второй частью теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6283,'Взять первую часть, раскатать вновь в небольшой круг, посыпать 1/4 емкости порезанного зеленого лука. Скатать тесто в плотный рулетик, начиная с краев. Из получившегося свертка сделать спираль. Накрыть чуть-чуть влажной салфеткой минут на пять. Сделать то же со вторым куском теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6283,'Разогреть сковороду, добавить растительное масло. Раскатать тесто, уложить на сковороду. Обжарить со всех сторон. Разрезать, подавать питы с зеленым луком с горчичным или соевым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6284,'Порезать куриные грудки на средние куски, посыпать солью, положить соду. Сбрызнуть мясо соком лимона, добавить крахмал. Отставить минут на пятнадцать, обвалять все кусочки в муке. Жарить на растительном масле. Во время жарки мясо раздуется, карбонад из куриного филе станет сочным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6285,'Растопить 2/3 шоколада на водяной бане. Когда от совсем растопится, размешать, положить остальную часть шоколада, размешать и оставить еще на шестьдесят секунд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6285,'Варить сливки до появления пузырьков, чуть-чуть остудить, положить в сливки шоколад. Размешать, посыпать солью. Положить ванилин и сок лимона. Перемешать, положить клюкву и лесные орешки. Выложить смесь на поднос, отправить ирис с вяленой клюквой и орехами в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6286,'Разогреть на сковороде чуть-чуть сливочного масла, пожарить печень на большом огне до золотистого оттенка. Насыпать перец, соль, долить воду, коньяк. Сделать огонь тише, тушить минут двадцать под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6286,'Перекрутить готовую печень через мясорубку или взбить с помощью блендера. Перемешать паштет и сливочное масло, положить в формочку, разровнять. Отправить минут на тридцать в холодильник, чтобы паштет застыл.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6286,'Подогреть сок граната, растворить в нем желатин, насыпать сахар. Остывший сок вылить на паштет, вновь отправить в холодильник, лучше на ночь. Куриный паштет под гранатовым желе должен застыть хорошо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Приготовить бисквит: отделить белки от желтка. Взбить желтки и сахар, чтобы получилась воздушная смесь белого цвета. Добавить воду, взбивать не останавливаясь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Взбить белки, соль и сахар до пиков. Отдельно соединить муку и разрыхлитель, просеять, чтобы смеси перемешались, и мука обогатилась кислородом. Насыпать муку в желтки, размешать до однородности. Медленно ввести белки. Размешать способом складывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Постелить специальную бумагу в разъемную формочку, смазать растительным маслом. Положить в формочку бисквитное тесто, отправить в горячую духовку. Готовить минут тридцать, соблюдая температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Остудить бисквит на решетке, разрезать на две части. Можно чуть-чуть пропитать коржики сахарным сиропом. Например, сиропом шиповника, разбавленного в воде. Одну часть бисквита положить в формочку, что он готовился.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Сделать смородиновый мусс: красную и черную смородину (например, замороженную) разморозить, слить образовавшуюся жидкость, измельчить при помощи блендера. Добавить сахар и сухое молоко. Все взбить. Положить творог. Вновь взбить. В конце налить густой йогурт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Приготовить предварительно раствор желатина, как написано в инструкции. Добавить в мусс, размешать, отправить минут на пять в холодильник. На бисквитный корж, положенный в формочку, налить 2/3 мусса. Положить второй корж, прижать. Распределить оставшийся мусс. Отправить минут на шестьдесят в холодильник. Сделать крем: соединить сметану и сгущенное молоко. Взбить при помощи миксера, медленно доливать лимонный сок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6287,'Достать тортик из формочки обмазать кремом. Отправить торт «Смородиновое настроение» минут на тридцать в холодильник. Украсить стружкой кокоса. Посыпать тортик ягодами, разложить листики мяты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Нагреть духовку, готовить минут пятнадцать.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Порезать лук и морковь на кубики. Чуть-чуть пассировать в кастрюльке на растительном масле (для маленького ребенка пассировать не нужно, просто положить после тушения мяса).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Взять лопатку или шейку говядины. Порезать на маленькие кусочки. Положить в кастрюльку с овощами. Обжарить на большом огне, помешивать, чтобы оно не зажарилось. Говядина выделит сок. Накрыть крышечкой, тушить минут пятнадцать в своем соку, пока он не выкипит.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Время от времени открывать крышку и помешивать. Для маленького ребенка в мясо сразу наливать чуть-чуть кипятка. Воды должно быть столько, чтобы она прикрывала мясо. Тушить до мягкости на среднем огне (приблизительно минут сорок).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Обдать помидор кипятком, подержать несколько минут в микроволновой печи, чтобы кожица легко снялась. Снять кожуру с помидора, размять его и положить в мясо. Посыпать солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Тушить еще приблизительно минут пять, бросить порезанный картофель, налить воду, чтобы картофель был покрыт ею, но не полностью. Если налить много воды, то получится жидковато. Бросить лавровый листик. Накрыть крышечкой, тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6288,'Размешать картофель. Чуть-чуть бульона отцедить в кружечку. Остудить, добавить муку, размешать с помощью вилки, чтобы исчезли комочки. Вылить смесь в блюдо. Это сделает картофель более вязким. Можно этого не делать, картофель в тарелке будет смотреться целостно и не очень жидко. Если мало жидкости, то ее можно не отцеживать, а развести муку в теплой воде. Размешать. Довести тушеный картофель с говядиной до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6289,'Все мягкие сырки порезать на кубики, остальные потереть. Ингредиенты положить в емкость, размешать, медленно налить воду, замесить тесто. Сделать шар, положить в пакет из полиэтилена, убрать минут на тридцать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6289,'Приготовить начинку: взбить чуть-чуть сливки, вбить яйца, все взбить. Смесь должна быть, как густая сметана. Смазать формочку маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6289,'Достать тесто, чуть-чуть отложить теста для внутренней перегородки. Раскатать тесто, положить его в формочку, сформировать бортики. Остальное тесто разделить пополам. Первую часть использовать, как перегородку по диаметру. Другую часть разделить еще на две части и сделать перегородки перпендикулярно первой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6289,'Разлить сливочно-яичную смесь по секторам, но так, чтобы осталось место для сыра. Сверху положить сырок, в каждый сектор разный. Посыпать разными специями. Моцареллу посыпать базиликом, голубой сыр – черным перцем, ольтермани посыпать паприкой, мягкий сыр посыпать черным кунжутом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6289,'Разогреть духовку. Поставить пирог на вторую полку. Готовить минут сорок пять, соблюдая температуру 180 градусов. Подавать пирог «Четыре сыра» теплым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6290,'В сыворотку насыпать сахар обычный и ванильный, положить творог, соль. Вбить яйцо в емкость, половину желтка отделить для смазывания, остальное перелить в смесь, взбить до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6290,'В просеянную муку насыпать дрожжи, медленно насыпать в творожную смесь, замешать миксером, используя насадку для теста. Когда масса будет отставать от стенок, положить растительное масло, сформировать из теста шар. Завернуть в полиэтилен, отправить в тепло, чтобы подходило, например, в духовку с включенной лампочкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6290,'Когда поднимется тесто, поделить его на три кусочка. Каждый раскатать в круг, порезать на сегменты, на широкую сторону положить джем, чуть-чуть выравнивая в направлении острого угла. Свернуть рулетик. Согнуть дугой, концы наложить друг на друга, чтобы получился калачик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6290,'Положить на противень, застеленный пергаментом. Намазать калачи желтком, разведенным водой. Готовить творожные калачики с джемом минут пятнадцать, соблюдая температуру 220 градусов. Достать противень, побрызгать водой, накрыть, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6291,'Приготовить омлеты: Желтый: взбить яйца, сливки, тертый сыр, муку и соль. Жарить на сковороде под крышкой. Красный: соединить предыдущие ингредиенты, добавить молотый красный перец, нежный кетчуп. Зеленый: к ингредиентам желтого омлета добавить измельченную петрушку и чуть-чуть укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7637,'Сварить в подсоленной воде картофель в мундире, почистить и порезать кружочками, ветчину нарезать маленькими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6291,'Приготовить начинку: красный болгарский перец порезать на маленькие кубики, обдать кипятком, осторожно отжать, положить сыр и майонез. Размешать. Собрать тортик: на красный омлет положить половину крема, сверху зеленый омлет, крем, желтый омлет. Поделить закусочный торт с разноцветным омлетом на кусочки. Украсить цветочками, сделанными из майонеза, помидоров черри и зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6292,'Смешать в емкости овсяные хлопья и манку. Налить кефир, размешать, отставить на 120 минут. Взбить яйца, добавить в емкость. Насыпать сахар, соду, соль. Налить масло, размешать. Из не очень густого теста жарить блинчики на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6293,'До готовности отварить бурый рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6293,'Помидор крупно нарезать, сладкий перец нашинковать соломкой, шампиньоны порезать пластиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6293,'Петрушку разобрать на листочки, нетолстыми полукольцами порезать лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6293,'Приготовленные овощи смешать с отваренным рисом, подсолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6293,'Салат из овощей и бурого риса приправить  маслом оливковым либо заменить его бальзамическим уксусом и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6294,'Положить в сотейник сливочное масло, поставить на плиту, растопить. Разделить белки и желтки. Сотейник с растопленным маслом, насыпать просеянную муку, мешая венчиком. Сделать огонь тише, мешать венчиком несколько минут. Насыпать сахар, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6294,'Соединить корицу и цедру половины лимона. Положить в сотейник. Побить венчиком, чтобы из цедры извлеклись ароматические масла. Налить молоко, не переставая мешать. Перемешивать, пока крем не закипит, убрать с плиты, минут пять охладить. Взбить желтки по одному, очень быстро, чтобы не свернулись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6294,'Натереть большую плоскую тарелку растительным маслом, чуть-чуть присыпать сухарями для панировки. Переложить равномерно крем по емкости, должна быть толщина 2 сантиметра. Охладить, отправить в морозилку часа на три. Крем должен хорошо застыть, чтобы можно было резать. Белки перемешать с помощью вилки, не взбивая. Разрезать крем на треугольники, ромбики или квадратики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6294,'Очень быстро, чтобы крем не растаял, каждый кусок обвалять в муке, белках, и сухарях. Обжарить в масле. Масла должно быть много и оно должно быть разогретым. Процесс должен быть быстрым, чтобы крем, который запечатан внутри, не схватился. В результате корочка должна быть хрустящей, а начинка жидкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6294,'Переложить на салфетку, чтобы впиталось лишнее масло. Подавать жареное молоко с корицей к чаю с жидким вареньем или ягодным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6295,'Отварить пасту до состояния аль-денте. В маленькой емкости соединить специи. Положить креветки в полиэтиленовый пакет, насыпать специи, встряхнуть. Нагреть на сковороде масло, обжарить креветки. Несколько минут. Отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6295,'Добавить оливковое масло, выдавить чесночок. Помешивая время от времени, спустя 60 секунд положить в сковороду сахар и помидоры. Еще спустя несколько минут положить в сковороду креветки, половину базилика. Оставить на минимальном огне на пять минут, иногда помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6295,'Слить пасту, оставить четверть стакана жидкости, в которой варилась. Положить пасту снова в кастрюлю. Сверху выложить начинку с соусом. Вылить оставленную жидкость. Размешать. Подавать пасту с креветками, базиликом и помидорами горячую, посыпать перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6296,'Вымыть изюм, залить кипятком, отставить на тридцать минут. Порезать куриные грудки на куски, пожарить. Измельчить и пожарить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6296,'Крупно натереть сыр, мелко порезать огурцы. Смешать все ингредиенты, выдавить чесночок, заправить салат «Сытный» майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6297,'Отварить филе курицы и измельчить. Порезать маслины на кружочки. Мелко натереть сыр, заправить майонезом, размешать. Отложить чуть-чуть сыра и маслин для украшения. На большую плоскую тарелку выложить салат в виде дольки арбуза. Пока салат пропитывается, заняться украшением.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6297,'Вырезать у огурца мягкую серединку, оставить для оформления жесткую часть, такую же процедуру сделать с помидорами. Мякоть можно съесть. Огурец крупно натереть, помидоры мелко порезать, маслины разрезать вдоль на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7668,'Пред подачей к столу слоеный салат с курицей, картофелем, сыром и киви охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6297,'На арбузную дольку выложить куски помидора вверх мякотью, так, чтобы он покрыл весь салат, и не осталось светлых промежутков. Сделать белую полосу из тертого сыра, зеленую полоску из огурца, как корку арбуза. Выложить на салат «Арбуз» из маслин арбузные косточки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6298,'Картофель, запеченный с сыром и травами, сочетается с грибами, помидорами, курицей. Хрустящий картофель вкусен и сам по себе. Порезать картофель, положить в соленую воду. Порезать или натереть сыр. Смешать травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6298,'Разогреть духовку, противень побрызгать оливковым маслом, положить на него картофель. Посыпать травами, сыром и петрушкой. Полить оливковым маслом, по сыру распределить куски сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6298,'Запекать картофель по-итальянски в духовке минут тридцать, после этого повернуть противень и готовить минут двадцать. Картофель станет золотистым. Посыпать перцем, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6299,'Разогреть духовку. В посуду налить кефир, насыпать манную крупу, размешать, отставить на шестьдесят минут. Взбить миксером яйца и сахар, соль, корицу. Переложить в разбухшую манку. Просеять в массу муку, налить мед, перемешать миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6299,'Положить соду, немного взбить, перелить все в формочку, смазанную маслом. Оставить минут на десять. Отправить медовый пирог с манкой на кефире в духовку минут на тридцать, готовность проверять деревянной палочкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6300,'Натереть сыр, выдавить чесночок, положить мягкое масло, измельченную зелень, размешать. Разогреть духовку. Сделать в батоне надрезы, наполнить сырной начинкой. Завернуть в фольгу, отправить минут на двадцать в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6300,'Приоткрыть фольгу, оставить минут на пять, чтобы батон стал румяным. Подавать хрустящий батон, порезав на ломтики острым ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6301,'Мелко поломать печенье, положить в блендер, добавить изюм, корицу, порезанные бананы. Вскипятить молоко, вылить в блендер, взбить. Налить молочный коктейль в бокалы, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6302,'Взбить масло и сахар до пышной смеси, вбить яйцо, взбить миксером. Растопить шоколад, охладить. Положить в яичную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6302,'Отдельно смешать сухие продукты, переложить в шоколадную смесь, замесить тесто. Завернуть в пакет, отправить на шестьдесят минут в холод. Разогреть духовку. Противень застелить бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6302,'Из холодного теста сформировать шарики, как орехи. Обвалять их в сахарной пудре, разложить на противень, посыпать пудрой сверху. Выпекать печенье «Снежные вершины» минут пятнадцать, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6303,'Для приготовления заправки перемешать соевый соус, горчицу, винный уксус и мед в желаемых количествах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6303,'Очищенные от кожицы и косточек авокадо и яблоко порезать брусками, сбрызнуть лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6303,'Брусками нарезать также сыр, помидоры и рыбу, добавить к авокадо и яблоку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6303,'Далее к подготовленным ингредиентам всыпать кунжут, орешки, рукколу и перемешать, полив заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6303,'Дно салатника уложить листьями салата, переложить салат с яблоком, авокадо, семгой, сыром и орешками, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6304,'Приготовить опару: в подогретое молоко насыпать муку и дрожжи. Размешать до однородной массы. Накрыть теплым полотенцем, отправить в тепло минут на тридцать для поднятия.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6304,'Вбить яйца, насыпать соль, сахар, положить ванильную эссенцию, масло. Размешать до однородной смеси. Опять накрыть полотенцем, отправить в тепло на тридцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6304,'Порезать яблочки на маленькие кубики или потереть. Тесто должно увеличиться в три раза. Добавить яблочки, перемешать. Отправить в тепло минут на двадцать. После этого тесто не перемешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6304,'Разогреть сковороду, налить масло, рядом поставить стакан с водой. Опускать ложку в воду, брать ею тесто и сразу выкладывать на сковороду. Готовить до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6304,'На разогретой сковороде дрожжевые оладьи с яблоками поднимаются мгновенно, главное во время переворачивать, чтобы они не сгорели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6320,'Измельчить орехи. Подрумянить на сковороде хлопья. Положить мед, орехи и изюм. Нагреть смесь, быстро мешая, чтобы мед распределился по хлопьям. Охладить хлопья, помешивая, чтобы не слиплись хлопья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6305,'Разделить белки и желтки. Взбить белки с водой и солью, насыпать сахар, положить желтки. Перемешать. Насыпать муку. Вылить тесто в формочку, смазанную маслом, поставить в духовку, готовить минут двадцать, соблюдая температуру 250 градусов. Охладить готовый корж. Перемешать творожную массу с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6305,'Отдельно замочить желатин, когда он станет мягким, отжать и растворить на минимальном огне. Положить в желатин чуть-чуть творога, вылить все в творожную массу. Размешать. Когда схватится желатин, переложить массу на корж в формочке, отправить на тридцать минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6305,'Порезать клубнику, положить на застывший творог. Растворить желатин в холодной воде, насыпать сахар, поставить на огонь, довести до кипения, помешивая. Вылить горячую жидкость на ягоды, отправить в холод. Спустя двадцать минут торт «Майская нежность» с клубникой готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6306,'Соединить сахар и муку. Отдельно смешать половину молока и желтки. Соединить смеси. Перемешать, чтобы не было комков. В остальное молоко добавить ванильную эссенцию, поставить на огонь. Довести до кипения и убрать. Осторожно влить 1/3 молока в яично-молочную массу, размешать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6306,'Вылить смесь обратно в молоко. Готовить до загустения. Когда крем закипит, готовить не больше 60 секунд, снять с огня. Перелить крем в холодную емкость. Положить в крем сливочное масло. Очень аккуратно и медленно размешать. Если мешать быстро, то классический заварной крем будет жидким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6307,'Порезать грудку курицы на кусочки по три сантиметра. Отбить мясо, посыпать перцем или солью. Порезать грибочки на кубики. Разогреть большую сковороду, смазать маргарином или маслом (сливочным). Положить курицу, обжарить минут восемь, переворачивая время от времени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6307,'Разогреть вторую сковороду, пожарить грибы. Положить к грибам прессованный чесночок. Жарить минут восемь на большом огне. Отставить в сторону. В маленькую посуду выдавить сок лимона. Сбрызнуть им мясо. Равномерно выложить на грудку грибы. Добавить сливки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6307,'Подождать, пока соус загустеет, но не давать закипеть, на очень тихом огне. Оставить куриной грудки с грибами в сливках на плите минут на десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6308,'Порезать мелко колбасу, помидоры колечками, крупно потереть сыр. Сделать соус: соединить прессованный чесночок с майонезом, посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6308,'Осторожно развернуть лаваши, свернуть на две части. На них положить слой тертого сыра, колбасы, помидор, сверху соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6308,'Свернуть и отправить фаршированный лаваш минуты на четыре в микроволновку или на десять минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6309,'Порезать рыбу на крупные куски, выложить в форму (желательно керамическую), посыпать перцем, солью. Если имеются порционные формы, то использовать их. Вымыть помидоры, нашинковать кружочками, черри порезать на две части. Положить сверху рыбки. Чуть-чуть посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6309,'Смешать горчицу со сметаной. Крупно натереть сыр, добавить в горчичную смесь. Разбавить сливками. Распределить смесь по помидорам. Отправить форму с треской с помидорами в духовку на 25 минут, соблюдая температуру 180 градусов. Сыр должен расплавиться и образовать корку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6310,'Подготовить продукты: почистить картофель, вымыть, порезать соломкой приблизительно по 6 миллиметров. Промыть водой, смыть крахмал, чтобы во время готовки картофель не слипался. Обтереть картофель полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6310,'Нагреть сковороду, налить масло. Почистить чесночок, положить его и розмарин на тридцать секунд в масло, чтобы картофель стал ароматным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6310,'Положить картофель, не перемешивать. Это очень важно – картофель должен поджариться. Только после этого посыпать перцем, солью, размешать, отставить на пару минут, не убавляя огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6310,'Когда картофель опять поджарится, перемешать, если нужно, посыпать солью. Готовить жареную картошку необходимо на большом огне и переворачивать только 2-3 раза, тогда обязательно будет хрустящая корочка. В конце можно добавить прессованный чесночок, но это не обязательно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6311,'Приготовить тесто и вылить в формочку, сверху положить тесно дольки яблок. Сверху вылить приготовленную взбитую заливку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Поставить тесто для подъема в тепло на час, масса должна увеличиться в два раза.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6312,'Приготовить заправку: взбить в блендере все продукты секунд тридцать до однородности. Порезать все ингредиенты для салата, положить в большой салатник. Посыпать перцем, солью, размешать. Заправить обильно соусом, размешать. Посыпать итальянский шопский салат специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6313,'Смешать яйца, муку, разрыхлитель, сыр и соль. Если сыр достаточно соленый, то соль не добавлять. Развести данную массу йогуртом, сметаной или кефиром, чтобы она стала похожа на густую сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6313,'Разогреть маленькую сковороду (диаметром приблизительно 20 сантиметров), смазать маслом, вылить сырную смесь, посыпать зеленью по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6313,'Жарить хачапури под крышкой, когда края станут румяными, а верх схватится, перевернуть и готовить быстрые хачапури под крышкой до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6314,'Отварить и остудить свеклу, морковь, картофель. Почистить, мелко натереть на терке все овощи отдельно. Отварить, охладить, почистить яйцо, отделить белки от желтков, мелко натереть их отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6314,'Порезать половину филе сельди на маленькие кусочки, остальное на прямоугольные пластинки 1 на 2 сантиметра. Почистить лук, измельчить, обдать кипятком, чтобы исчезла горечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6314,'В одну емкость положить натертую свеклу, морковь, кусочки селедки, половину тертого желтка и белка, лук, заправить майонезом. Можно приготовить майонез самостоятельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6314,'Измельченный картофель равномерным слоем распределить по коврику для роллов, тоненько выложить на картофель начинку, сформировать ролл. Аккуратно порезать ролл «Сельдь под шубой» на небольшие куски, украсить сверху прямоугольниками сельди, тертым яйцом, зеленым лучком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6315,'Порезать колбасу на ломтики в толщину, как сосиски. Разрезать поперек на две части. Приготовить кляр: соединить молоко, яйцо, майонез, насыпать сахар и соль. Взбить вилкой. Просеять в смесь муку, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6315,'Обмакивать колбасу полностью в кляр. Разогреть масло, выложить колбаску, обжарить под крышкой с двух сторон до корочки. Убрать колбасу в кляре на салфетку, чтобы она впитала масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6316,'Сварить рисовую кашу: на литр молока стакан риса. Отлить чуть-чуть молока. Когда молоко закипит, посолить, насыпать вымытый рис, желательно круглый. Чуть-чуть дать покипеть, насыпать сахар, положить масло. Готовить, мешая, до загустения, чтобы не подгорела. Снять кашу с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6316,'Вырезать из яблок серединку, порезать на дольки. Соединить яйца с молоком. Смазать противень маслом, положить половину каши, на нее яблоки, остальную кашу. Полить молоком, смешанным с яйцами. Покрыть яблоками. Отправить рисовую бабку с яблоками в духовку минут на двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6317,'Мелко потереть сыр. Измельчить зелень, порезать или порвать салат. Порезать соломкой огурец, очень мелкой соломкой порезать или крупно натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6317,'Лаваш положить в полиэтиленовый пакет или завернуть в бумагу, чтобы было удобно хранить. На первый лист выложить сыр, уложить второй лист, намазать половиной соуса, посыпать огурцом, салатом и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6317,'Выложить сверху третий лист лаваша, смазать второй половиной соуса. Положить морковь и сладкий перец. Помогая пленкой, осторожно свернуть рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6317,'Не следует класть очень много начинки, так как все будет разваливаться, лаваш начнет рваться. Посыпать начинкой лаваш, распределить равномерно, чтобы было удобно сворачивать в закусочный рулет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6318,'Отварить целый кочан капусты, листья должны хорошо отходить. Пока варится капуста, потушить чесночок, измельченный лук, положить тертый кабачок, морковь, посыпать перцем, накрыть крышкой. Томить овощи приблизительно тридцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6318,'Замочить в горячей воде рис, чтобы он чуть-чуть набух. Слить воду, перемешать рис с фаршем. Разделить овощную смесь пополам, одну часть положить к рису с мясом, остальное отправить в бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6318,'Начинку завернуть в листики капусты. Обжарить конвертики 60 секунд на оливковом масле. Налить воду, чтобы покрывали голубцы. Положить сверху остальную смесь, готовить 60 минут. Минут за пятнадцать положить томатную пасту. Перед подачей голубцы с мясной начинкой и овощами полить сметаной, посыпать измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Добавить промытые листочки мяты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6320,'С яблока срезать кожуру, вырезать середину. Порезать, положить в блендер, положить ягоды, сделать пюре. Размять творог. Положить в бокал слоями все продукты. Слоеный десерт из творога перед подачей немного охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6321,'Взбить сливки, размешать со сгущенным молоком, налить коньяк. Налить коньяк. Перелить смесь в контейнер, отправить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6321,'Спустя 60-90 минут достать, размешать. Вновь отправить в морозилку. Полить мороженое «Крем-брюле» шоколадным сиропом или фруктовым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6322,'Выжать из грейпфрута сок с помощью блендера или соковыжималки. Налить в кастрюльку воду, насыпать сахар, положить мяту. Поставить на огонь, довести до кипения, чтобы растворился сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6322,'Вынуть мяту, выжать сок, выбросить мяту. Смешать в блендере приготовленный сироп с грейпфрутовым соком. Остудить грейпфрутово-мятный коктейль и подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6323,'Вымыть и почистить от кожуры, помыть виноград. Измельчить в блендере или комбайне фрукты. Налить яблочный сок, размешать. Положить в стакан полстакана льда, налить лимонад, перемешать. Украсить кружками киви и винограда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6324,'Взбивать яйца с сахаром и ванилью минут пятнадцать на большой скорости. Нагреть духовку. Поставить шоколад и масло в микроволновую печь секунд на тридцать. Размешать, поставить еще на тридцать секунд, повторять, пока не получится жидкая однородная смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6324,'Ввести в яйца шоколад, разрыхлитель и муку, взбивать несколько минут, положить остальной шоколад, подождать, пока шоколад не растопится. Выложить шарики на противень, отправить минут на семь, готовить, пока они чуть-чуть не треснут. Дать печенью из молочного шоколада постоять минуты четыре на противне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6325,'Разрезать на две части авокадо, убрать косточку, снять кожуру, порезать на куски. Перец почистить от семян, обрезать подножку, порезать на кусочки. Порезать на кусочки семгу. Порезать ломтиками стебли сельдерея.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6325,'Порезать сыр на тоненькую соломку, положить измельченную зелень, полить лимонным соком. Размешать, положить салат «Фобос» в салатник, смазанный лимонной коркой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6326,'Порезать кочан капусты на кусочки с кочерыжкой, порезать свеклу на кружки, почистить чеснок, порезать горький перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6326,'В кастрюльку сложить слоями: капусту, свеклу, чесночок, горький перчик, перец черный горошком, повторять слои, пока до края не останется пять сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6326,'Закипятить воду, положить соль. Залить горячим рассолом овощи, положить гнет и накрыть крышкой. Капуста по-гурийски будет готова спустя пять дней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6327,'Порезать баклажаны наискосок, сделать фарш, как на котлетки. На все кусочки баклажанов выложить фарш, прижать и сделать лепешки. Обвалять в муке, затем в подсоленном взбитом яйце, пожарить вниз фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6328,'В емкость налить кефир, разбить яйца, просеять муку, насыпать соду. Все размешать. Приготовить начинку: крупно натереть сыр, добавить яйца. Поделить тесто на четыре части. Их поделить еще на две части, одну больше другой. Раскатать лепешки 50 миллиметров толщиной. Не делать лепешки очень толстые, так как тесто поднимется, и будет казаться тяжелым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6328,'Лепешки должны по диаметру быть чуть-чуть больше сковороды. На лепешку побольше положить 1/4 сырной начинки, равномерно распределить, отступив от краешков. Лепешку поменьше положить сверху, защипнуть краешки. На сковороду положить лепешку вниз швом, жарить под крышкой на тихом огне минут семь. Можно готовить на масле или без него. Перевернуть хачапури по-тбилисски и готовить минуты четыре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Отварной картофель порезать в виде небольших долек, противень застелить пекарской бумагой, выложить на нее картофель, посолить и поперчить, смазать одной столовой ложкой масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Перцы разных цветов порезать пополам, вынуть семена, разложить на картофель вверх шкуркой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Противень с овощами поставить в духовой шкаф, нагретый до 200 градусов на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Через 10 минут вынуть перцы, дать остыть под влажным полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'К картофелю добавить ломтики буженины, смазать блюдо заправкой из карри с маслом, запекать еще 4 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Утрамбовать.','https:https://st.vkuso.ru/data/cache/thumb/ae/210dea85b3875ae_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Дно салатника выложить нарванными листьями салата, сыр натереть на терке либо порезать мелкими кусочками, с перцев осторожно снять шкурку и порезать ломтиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'На листья салата уложить остывший картофель и буженину, добавить перец и сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6329,'Овощной салат с бужениной и моцареллой поперчить, посолить, полить соусом из масла и лимонного сока и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6330,'Осторожно отделить желтки от белков. Желтки разложить по маленьким формочка. Взбить белки с солью в пену. В них не должно быть остатков желтков, емкость и насадки должны быть сухими. Желательно, чтобы белки были комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6330,'Натереть сыр и посыпать белки, распределить по поверхности. Нагреть духовку, постелить лист для запекания фольгой или специальной бумагой. Положить на противень взбитые белки в виде «гнезд». В центр положить желтки. Запекать яйца в пуховом гнезде в духовке минут шесть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6331,'Порезать шампиньоны. Обжаривать минут восемь. Потереть морковь, обжарить. Разделить брокколи на соцветия, на маленькие кусочки. Брокколи может быть или свежей, или замороженной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6331,'Если в замороженном виде, то разморозить, чтобы проще было резать на кусочки. Порезать картофель. Закипятить воду в кастрюльке, положить подготовленные продукты, посыпать солью, готовить минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6331,'Крупно потереть сырки. Положить их в суп, готовить минут пять, пока не расплавятся сырки. Посыпать сырный суп с шампиньонами и брокколи сушеным укропом. Дать супу потомиться минут десять. Подавать с сухарями или гренками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6332,'Разогреть духовку. На противень положить хлеб. Намазать оливковым маслом, отправить в духовку минут на десять. Достать противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6332,'Смешать прессованный чесночок с порезанными помидорами, уксусом и оливковым маслом. Положить на хлеб моцареллу, помидоры. Поставить противень минут на семь в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6332,'Достать, побрызгать оливковым маслом. Посыпать теплую брускетту с помидорами и сыром измельченным базиликом, перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6333,'Можно использовать в приготовлении как крупный картофель, так и мелкий. Его необходимо отварить. Если картофель очень большой, то разрезать его пополам. Очистить от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6333,'Чайной ложкой достать серединку, вбить в отверстие перепелиное яйцо, посыпать перцем, солью. Мелко потереть сыр, посыпать сверху картофель. Оправить минут на тридцать в духовку, готовить картофель «Сюрприз» при 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6334,'Тесто на кефире получается не сухое, чуть-чуть хрустящее, тоненькое, как «бархат». В емкость налить кефир, вбить яйцо, насыпать соль. Взбить вилочкой. Насыпать муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6334,'Густую массу положить на стол, замесить среднее тесто. Отставить минут на двадцать. Приготовить начинку: смешать фарш с луком, специями и бульоном или водой. Размешать. Начинка должна быть немного жидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6334,'Разделить тесто на десять кусочков. Каждый раскатать, в центр положить начинку. Сделать чебурек. Чтобы не вытек сок, краешки раскатать скалкой. Лишнее тесто срезать. Жарить чебуреки на кефире на растительном масле с обеих сторон до румяного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6335,'Варить рыбку минут семь. Крупно натереть сыр. Разрезать булочку с кунжутом. Из одной булочки получается два бутерброда. Намазать булочку майонезом. На майонез положить куски красной рыбки. Рыбка вареная легко расслаивается, поэтому ее можно красиво разложить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6335,'На рыбу положить тертый сыр. Готовить в духовке при температуре 180 градусов минут пятнадцать. Когда сыр расплавится, бутерброды с семгой можно доставать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6336,'Желательно использовать горшочки среднего размера, они удобней. Порезать лук, разложить его по горшочкам. Предварительно на дно положить кусочек масла, лучше топленого.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6336,'Порезать мясо на средние кусочки, также разложить по горшочкам. Посыпать перцем, солью и приправами. Отправить горшочки в духовку минут на шестьдесят. Соблюдать температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6336,'Затем положить в горшочки грибы, сметану, в которую заранее положить несколько маленьких ложек горчицы. Процесс делать очень осторожно, чтобы не обжечься. Накрыть крышками и готовить еще минут двадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Дать напитку закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6336,'В конце разложить тертый сыр, когда он расплавится, говядину с шампиньонами и сметаной в горшочках можно доставать. Посыпать зеленью и подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6337,'Смешать фарш с измельченным луком, яйцом, хлебом, размоченным в молоке, специями и солью. Хорошо все размешать, слепить котлеты. Почистить картофель, порезать кружочками. Также порезать кружками помидоры и баклажаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6337,'В огнеупорную емкость по краю выложить по очереди овощи: сначала картофель, затем баклажаны, помидоры. В центр формочки положить котлетки. Приготовить заливку: в молоко положить сметану, вбить яйцо, размешать. Вылить заливку на котлеты и овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6337,'Крупно потереть сыр, посыпать им блюдо. Отправить формочку в разогретую духовку. Готовить минут 45, соблюдая температуру 200 градусов. Подавать котлеты «Полосатый рейс» с гарниром, в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6338,'Порезать белокочанную капусту тоненькой соломкой, пекинскую полосками не более 1 сантиметра. Перед добавлением белокочанную капусту посолить и помять руками, чтобы она стала сочной. Из помидора вырезать серединку, порезать на небольшие ломтики. Почистить луковицу, порезать на тоненькие полукольца. Колбасу порезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6338,'Подготовленные ингредиенты положить в емкость, заправить майонезом, посыпать перцем, солью, размешать. Если сухарики будут использоваться магазинные, то можно не солить. Перед подачей салат из капусты с помидорами и колбасой отправить минут на двадцать в холодильник. Посыпать измельченной петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6339,'В кипящую воду добавить чуть-чуть сахара и соли, закинуть спаржу и поварить 3 минуты, затем достать и переложить в посуду со льдом, когда спаржа остынет, нарезать ее наискосок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6339,'Грибы порезать пластиками, посолить и обжарить на масле, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6339,'На блюдо выложить прожаренные грибы, сверху распределить спаржу, обсыпать рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6339,'Яйца разрезать на четвертинки и уложить на салат, для заправки смешать масло оливковое, бальзамический уксус и лимонный сок и слегка взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6339,'Грибной салат со спаржей и яйцами полить приготовленным соусом, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6340,'Разогреть духовку. Смазать формочку тоненько сливочным маслом. Просеять муку, соду и разрыхлитель. Отставить. Взбить сливочное масло, постепенно насыпать сахар, продолжать взбивать, пока масса не станет воздушной и легкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6340,'В отдельной емкости взбить белки, добавить масло, яйцо. Насыпать муку, налить кефир, сок лимона, размешать до однородности. Готовить минут сорок, проверять при помощи зубочистки. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6340,'Налить в желатин теплую воду, отставить, чтобы он набух. Взбить сметану и сахар. Вылить в смесь желатин, размешать. Отправить в холодильник минут на тридцать. Порезать фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6340,'Стеклянную формочку застелить пленкой, намазать растительным маслом, посыпать сахаром. Разрезать корж пополам. Начиная с середины, разложить дольки фруктов. На них равномерно намазать охлажденный крем, корж, крем, опять корж. Коржики можно пропитать соком апельсина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6340,'Отправить тортик в холодильник на ночь. Наполнить большую емкость горячей водой, аккуратно опустить формочку на несколько минут. Нужно делать все осторожно, чтобы вода не попала в торт. Перевернуть торт с фруктами и сметанным кремом на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6341,'Соединить все продукты для коржика. Сделать рассыпчатое тесто. Утрамбовать его в формочке диаметром 21 сантиметр. Чизкейк будет невысокий. Готовить корж минут на пятнадцать, соблюдая температуру 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6341,'Залить желатин холодной водой, отставить, чтобы набух. В творожную массу потереть белый шоколад. Сливки взбить с сахаром. Массы соединить. Нагреть желатин, довести до комнатной температуры, соединить со сливочной массой. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6341,'Уложить в разъемную формочку кокосовый корж, налить сверху сливочную смесь, разровнять, отправить английский чизкейк с кокосовой стружкой в холод желательно на ночь. Достать чизкейк из формочки, по вкусу украсить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6350,'Отварить, почистить и мелко порезать яйца. Измельчить лук, размять, чтобы он дал сок, соединить с яйцами. Порезать семгу полосочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Снять брусничный морс с листочками мяты с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6342,'В емкости соединить сельдерей, креветке, йогурт, лук. Заправить майонезом. Посыпать приправами. Разложить на тарелочке ломтики огурца. Положить сверху по большой ложке салата, посыпать салат с креветками на огурцах зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6343,'Помыть яблоки. Срезать шкурку (если она не жесткая, то не срезать), крупно натереть или измельчить в блендере. Смешать яйца и сахар. Положить ванильный сахар, насыпать муку и соду. Муку добавлять медленно, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6343,'Разогреть сковороду не очень сильно, чтобы оладьи пропекались, а не подгорали. Жарить яблочные оладушки на растительном или сливочном масле. Подавать с медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6344,'Растереть желток и сливочное масло до однородной массы, насыпать сахар или сахарную пудру, развести молоком, насыпать муку. Должно получиться жидковатое тесто без комков. Положить в смесь взбитые белки и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6344,'Испечь тоненькие блинчики. Такие, чтобы их не нужно было переворачивать. Если ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6345,'Закипятить воду, посолить. Куриные грудки посыпать смесью базилика, перца, орегано, соли. Разогреть сковороду, положить масло, обжаривать курицу минуты четыре. Чуть-чуть остудить, порезать кубиками. Отварить спагетти, оставить половину стакана жидкости, остальную слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6345,'Обжарить в той же сковороде чесночок, помидоры, сбавить огонь, готовить минуты четыре. Положить спагетти, чуть-чуть жидкости. Положить мясо, свежий измельченный базилик, размешать. Подавать спагетти с куриной грудкой и помидорами с тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6346,'Почистить имбирь, мелко потереть. Порезать лимон на тоненькие кружки, выжать сок, положить цедру. Добавить пряности, например, гвоздику. Налить кипяток, положить мед, размешать. Накрыть имбирный чай полотенцем, отставить, чтобы настоялся часа на три.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6347,'Почистить и крупно потереть морковь. Удалить середину яблок, порезать на средние кусочки. Залить изюм кипятком, оставить минут на десять, обсушить, положить к моркови и яблокам. Порубить орехи не очень мелко, добавить в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6347,'Приготовить заправку: соединить апельсиновый сок и сок лайма, положить корицу, масло, размешать, вылить в салат. Украсить витаминный морковный салат орехами и корицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6348,'Нагреть молоко, насыпать сахар, дрожжи, муку и отправить в тепло, пока не образуется «шапка». Вбить яйца, положить растительное масло или мягкий маргарин. Насыпать соль, муку и сахар, замесить мягкое тесто. Смазать его растительным маслом, отправить минут на сорок в тепло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6348,'Приготовить пудинг: Налить в емкость молоко, насыпать сахар и порошок пудинга, размешать, чтобы не было комков. Остальное молоко довести до кипения и вылить в молочную смесь. На маленьком огне приготовить пудинг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6348,'Чуть-чуть остудить пудинг, положить сметану, перемешать. Из теста раскатать прямоугольник приблизительно толщиной два сантиметра. Разложить по поверхности пудинг, свернуть рулетиком. Защипнуть краешки. Порезать рулетик на куски по четыре сантиметра, намазать желтком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6348,'Положить кусочки в круглую формочку и поставить на расстойку: нагреть духовку до 50 градусов, выключить, побрызгать внутри водой, поставить формочку с пирогом минут на двадцать. Готовить пирог «Улитка» с ванильным пудингом минут тридцать, соблюдая температуру двести градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'В кипящую воду закинуть очищенный и промытый картофель, добавить бульонный кубик, отварить картофель до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'Затем из картофеля сделать пюре, перемешать его с молоком или сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'Не переставая толочь, всыпать в пюре соль, перец и хлопья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'Полученный суп довести до кипения, помешать и снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'Если вдруг суп очень густой, нужно добавлять молоко или сливки до тех пор, пока не получиться нужная консистенция.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6349,'Молочно-картофельный крем-суп со сливками перед подачей спрыснуть оливковым маслом, украсить измельченной зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6350,'Растереть до однородности масло, творог и яйцо, насыпать муку, столько, чтобы тесто было мягким и не прилипало. Скатать из теста шарик, обернуть в пленку, отправить минут на двадцать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Неровные свисающие края обрезать.','https:https://st.vkuso.ru/data/cache/thumb/53/0aa5d61b4b22753_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6350,'Тесто поделить пополам, раскатать. На противень постелить специальную бумагу. Положить один пласт, по нему распределить луковую начинку, на нее слой семги. Накрыть вторым пластом теста, скрепить краешки, намазать пирог из творожного теста взбитым яйцом, готовить до румяности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6351,'Порезать печень на тоненькие брусочки, обжарить. Порезать соломкой лук и морковь, пожарить. Соединить печень, огурчики, лук с морковью, измельченный чесночок, яйцо, посыпать перцем и солью. Заправить салат с печенью майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6352,'Измельчить лук и перец, обжарить с томатной пастой, майонезом, перцем и солью. Намазать омлет фаршем, положить начинку, свернуть рулетиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6352,'Осторожно положить на смазанный противень, готовить минут тридцать, соблюдая температуру 230 градусов. Чтобы рулет из омлета с куриным фаршем не сгорел, можно накрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6353,'Взять для рассола холодную питьевую воду, растворить в ней крупную соль. В раствор положить чесночок, перец горошком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6353,'Положить сало, поставить в холод минимум на два дня. Достать сало, подсушить салфеткой, хорошенько, со всех сторон посыпать соленое сало перцем и молодым укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6354,'Нашинковать капусту, обдать кипятком. Филе курицы, морковь и лучок пропустить через мясорубку. Объединить капусту, морковь, лук, фарш, геркулес в сухом виде. Посыпать перцем, укропом, солью. Размешать.Вбить яйцо, перемешать. Влажными руками сделать котлеты, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6354,'Сделать соус: соединить сметану, томатную пасту, посыпать солью и сушеными травками. Налить воду, положить кетчуп, майонез. Слить лишнее масло со сковороды, залить соусом котлеты, довести до кипения. Тушить на минимальном огне ленивые голубцы с куриным фаршем минут тридцать под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6355,'Измельчить зелень петрушки, чесночок пропустить через чеснокодавку. Соединить петрушку с чесноком, посыпать молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6355,'Надрезать вдоль сардельки или сосиски, положить в надрез чесночную массу. Намазать майонезом, посыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6355,'Положить сосиски на решетку, поставить в самый низ. Готовить сосиски с чесноком и сыром в духовке минут десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6356,'Насыпать в емкость муку, добавить тертое масло, перемешать, вбить яйцо, посыпать солью, положить сметану. Замесить тесто, отправить на тридцать минут в холодильник. Порезать картофель и мясо, добавить лук, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6356,'Поместить тесто в формочку, сформировать бортики, выложить начинку, налить заливку. Готовить пирог с курицей и картошкой минут пятьдесят, соблюдая температуру 180 градусов. Чуть-чуть остудить, порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6357,'Разобрать на волокна филе курицы. Порвать на кусочки салат. Почистить перец от семян, порезать на колечки. Положить мелкий зеленый горошек. Положить измельченное мясо, кусочки киви, лук, порезанный на тоненькие колечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6357,'Посыпать перцем, солью, полить соком лимона и оливковым маслом. Размешать. Положить салат с курицей и киви на блюдо, можно посыпать сушеной петрушкой и чуть-чуть обжаренные кедровые орешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6358,'Предварительно достать из холодильника маргарин или масло, чтобы растаяли. Смешать ингредиенты и замесить тесто. Разложить тесто в формочки, смазывать их не нужно, так как тесто и так жирное. Готовить пирожные минут пятнадцать, соблюдая температуру 180 градусов. Достать из духовки, остудить, вынуть из формочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6358,'Приготовить крем: взбить белки до густой пены. Сварить сироп из сахара, воды, уксуса. Уваривать после закипания минут восемь. Ввести тоненькой струйкой сироп во взбитые белки, положить лимонную кислоту, взбивать несколько минут. Должен получиться глянцевый крем. Перетереть ягоды и сахар, положить во все корзиночки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6358,'Крем положить в кондитерский мешок, красиво выложить на ягодную начинку. Отправить в холодильник. Можно украсить пирожное «Корзиночка» ягодами. Пирожные получаются воздушные и вкусные.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'Мелко порезать лук, измельчить чеснок, цуккини порезать кубиками, потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6359,'Фарш смешать с чесноком, луком, базиликом, хлебной крошкой, сырым яйцом, солью, тертым сыром и перцем, перемешав до однородности, сформовать небольшие фрикадельки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6360,'Взбить яйца и сметану. В отдельной емкости смешать какао, сахар, соду, гашенную уксусом, муку, добавить сметанную смесь. Перемешать до однородности, разделить пополам, готовить в духовке несколько коржей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6360,'Приготовить крем: смешать какао с сахаром и яйцом, взбить, налить воду, положить масло, поставить на тихий огонь. Непрерывно помешивать, так как быстро пригорает. После закипания готовить несколько минут, остудить. Должен получиться крем, как повидло. Когда коржи остынут, намазать их кремом. Украсить шоколадный торт «Негр» можно грецкими орешками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6361,'Вымыть чечевицу, почистить и измельчить лук и морковь. Положить в кастрюльку лук, перемешивать пять минут, добавить морковь, мешать пять минут. Положить чечевицу, размешать, налить бульон, размешать. Довести до кипения, минут тридцать готовить на маленьком огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6361,'Измельчить все в блендере, перелить в кастрюльку, налить молоко, посыпать перцем, солью, размешать, закипятить. Сбрызнуть лимонным соком, размешать. Обрезать хлеб, порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6361,'Положить в формочку, выпекать минут десять, соблюдая температуру 210 градусов. Распустить масло в емкости, добавить паприку. Разлить турецкий чечевичный суп по тарелкам, бросить кубики подсушенного хлеба, сбрызнуть маслом с паприкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6362,'Измельчить в блендере хлопья, положить растертый творог, вбить яйца, налить кефир. Осторожно вмешать в тесто ягодки, отставить минут на пятнадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6362,'Разогреть антипригарную сковороду, готовить оладьи под крышкой по три минуты со всех сторон. Подавать оладьи из хлопьев и черники со смесью меда и йогурта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6363,'Раскрошить печенье, орешки не сильно мелко. Растопить масло, насыпать сахар, какао, положить сгущенное молоко. Когда масло растает, греть на маленьком огне минут восемь. Помешивать непрерывно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6363,'Положить в сладкую массу орешки с печеньем, размешать, выложить на блюдо. Залить тортик растопленным шоколадом. Украсить тортик без выпечки половинками орехов. Отправить в холодильник для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6364,'Налить все ингредиенты в кастрюльку, довести до кипения, готовить до карамельного цвета. Должна быть не жидкая смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6364,'Приготовить бисквит: соединить масло и сахар, насыпать муку, перетереть в крошку. Переложить в формочку, прижать, готовить минут тридцать, соблюдая температуру 160 градусов. Охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6364,'Когда бисквит остынет, залить соусом, полить печенье «Твикс» шоколадной глазурью. Когда застынет, порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6365,'Помыть свежие огурчики, морковь, яблоки порезать на тоненькую соломку, каждый салатный лист разделить на четыре части. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6365,'Заправить салат из свежих овощей сметаной, положить сахар, соль, сок лимона.  Украсить помидорами, порезанными на ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6366,'Растопить на тихом огне сливочное масло, сахар, сливки, кипятить не нужно. Снять с огня. Положить стружку кокоса. Размешать. Полученную массу переложить в формочку или на противень небольшого размера, предварительно покрытые специальной бумагой. Отправить в холодильник на шестьдесят минут. Если нужно быстрей, то можно поставить в морозильную камеру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6366,'Вынуть конфеты из холодильника и порезать, как настоящие батончики (кончики закруглять), убрать в холодильник на всю ночь. Если нет времени ждать, то поставить ни три часа в морозилку. Но лучше, конечно, на ночь. Глазировать батончики. Взять молочный шоколад (именно молочный, потому что с темным совсем другой вкус).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6366,'Поломать плитку на кубики, положить на тарелочку, залить обыкновенным рафинированным маслом, не имеющим запаха, хватит нескольких столовых ложек. Поставить секунд на сорок в микроволновую печь. Можно также делать на водяной бане. Размешать смесь до однородности. Чтобы добиться нужной консистенции, добавить масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6366,'Над тарелкой с глазурью держать конфетку и с помощью ложки поливать. Чтобы было удобней, положить конфетку на решетку, вилку или лопатку с отверстиями. Глазурь мгновенно схватывается на холодных шоколадках, красиво и равномерно ложится. Дальше можно брать шоколадки «Баунти» руками и обмакивать в глазурь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'От полученного теста отделить 2/3 и раскатать в пласт, который затем переложить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6367,'Потереть цедру апельсина. На горячую сухую сковороду насыпать половина сахара, положить цедру. Жарить 60 секунд. Положить клюкву, готовить минуты три.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6367,'Раскатать тесто на поверхности, присыпанной мукой. Положить клюкву, скатать рулетик, порезать на одинаковые кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6367,'Формочку смазать маслом, положить в разъемную форму. Посыпать клюквенный пирог корицей и сахаром. Готовить 25 минут, соблюдая температуру 180 градусов. Посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6368,'Подготовить смесь из желатина и молока, оставив желатин набухать в стакане теплого молока 30 минут. Затем в массу влить оставшееся теплое молоко и немного подержать на медленном огне, но не кипятить. В отдельной миске промыть изюм и залить кипятком, орехи измельчить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6368,'Творог для торта лучше выбирать сухой, чтобы его можно было протереть через сито. В творог добавить сахар, сметану, ванилин, измельченные орехи и изюм. Тщательно размешать и ввести желейную массу. Аккуратно перемешать ложкой творожное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6368,'Для творожного торта подойдет любая съемная форма. Дно формы выложить очищенными дольками цитрусов: мандарины, апельсины. Затем выложить слой творожной массы, утрамбовав ложкой и аккуратно разровняв бока. На творог опять очищенные фрукты: киви, банан, персик. Опять творог. Слои можно чередовать в любом порядке, фрукты смешивать или выкладывать отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6368,'Последний слой творожный, сверху засыпать тертым шоколадом, кокосовой стружкой или полить растопленным шоколадом. Приготовленный торт поставить на холод на 3 часа. Перед подачей на стол, творожный торт «Волшебный» с фруктами вынуть из формы и порезать на порционные куски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6369,'Традиционный гуляш готовится из говядины или телятины. Мясо внимательно очистить от плевы и жил, затем порезать на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6369,'Обжарить мясные кусочки на раскаленной сковороде с небольшим количеством растительного масла. Когда мясо обжарится со всех сторон до румяной корочки, добавить порезанный соломкой лук и сладкий перец. Добавить соль, перец и специи по вкусу. Огонь сделать средним.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6369,'Через 5 минут тушения мяса с овощами в сковороду высыпать паприку, томатную пасту и влить виноградное вино. Накрыть крышкой и тушить гуляш 1 час на очень медленном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6369,'Когда мясо станет мягким, добавить в гуляш сметану и протушить еще 10 минут. Густой ароматный гуляш со сладким перцем идеально сочетается с гарниром из макарон или картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'Для теста на чебуреки необходимо обязательно просеять муку, чтобы она обогатилась кислородом и, тесто получилось воздушным. Насыпать горку из муки, сделать углубление и налить в него молоко, посолить по вкусу. Тесто месить руками, тщательно разминая все грудки. Во время вымешивания влить водку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'Вымесить крутое тесто, так, чтобы не липло к рукам, но и не совсем твердое. Сделать шарик и, завернув в пищевую пленку, отложить в холодильник на 30 минут. В итоге получается хрустящая жареная корочка в жареных чебуреках.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'Фарш готовим из молотого лука, мяса, соли, перца и кефира. Все измельчить на мясорубке или блендере, влить кефир и очень тщательно вымесить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'Главное в приготовлении чебуреков – это тесто. Если оно правильно замешано, значит, половина работы сделана. Теперь необходимо его раскатать. Охлажденное тесто раскатать в пласт толщиной в 2 см, затем свернуть в три раза и опять раскатать. Опять свернуть втрое и раскатать очень тонко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'Этот тонкий пласт свернуть тугим рулетом и нарезать на маленькие кусочки острым ножом. Скалку смазать маслом и раскатать из каждого кусочка тонкий пласт, муку не использовать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'На каждый пласт положить ложку фарша и сформировать чебуреки, обрезав лишнее тесто по бокам. Чтобы края хорошо слиплись, прижать вилкой. Слепленные чебуреки должны полежать 15 минут на столе, чтобы тесто отдохнуло перед жаркой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6374,'Начинку разложить по тарталеткам, сверху присыпать тертым сыром и поставить в духовку для запекания на 15 минут. Когда сыр подрумянится, жульены в тарталетках готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6375,'До готовности отварить в подсоленной воде картофель в мундире, сварить вкрутую яйца, дать и тому, и другому остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6370,'В сковороде раскалить масло, желательно рафинированное, чтобы не было лишнего запаха жареного масла. В горячее масло очень аккуратно опускать чебуреки с сочной мясной начинкой и жарить с двух сторон на среднем огне. Золотистая корочка говорит о готовности, аккуратно вынуть со сковороды жареные чебуреки при помощи вилки и положить на бумажное полотенце.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6371,'Твикс готовится из песочного печенья и карамели. Для приготовления песочного теста необходимо размять сливочное масло с мукой, солью и сахаром. Получается крошка, которую следует тщательно размять и утрамбовать в форму для выпекания. В духовке песочное тесто выпекать 20 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6371,'Чтобы приготовить карамель, необходимо растопить на сковороде 20 грамм сливочного масла, затем влить сгущенное молоко. Томить массу на очень медленном огне 20 минут, пока она не начнет карамелизироваться – загустевать. Так готовится наша карамель, не сложно и быстро.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6371,'Охлажденное песочное тесто не стоит вынимать из формы, сверху его залить карамелью, разравнять края ложкой. Плитки черного шоколада растопить на водяной бане, затем вылить жидкий шоколад сверху на карамель. Поставить печенье в холодильник на 2 часа. Готовый шоколад «Твикс» порезать на порционные кусочки, можно тонкими полосками, как в рекламе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6372,'Для приготовления теста необходимо растереть мягкое сливочное масло (маргарин) с просеянной мукой. В получившуюся крошку добавить взбитое яйцо, тертый сыр. Вымесить очень мягкое сырное тесто, посолить по вкусу. Сформировать из теста шарик, завернуть в пищевую пленку и положить на 30мнут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6372,'Начинка для классического жульена – грибы с курицей, тушенные в сметане. Очистить лук, порезать мелким кубиком и обжарить на растительном масле. К золотистому луку высыпать порезанные грибы. Если грибы мороженные, значит необходимо отжать лишнюю жидкость, если сушеные – замочить в воде на пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6372,'Когда грибы приобретут золотистую корочку, добавить к ним вареное куриное мясо, порезанное на небольшие кусочки. Немного обжарить. К готовому мясу и грибам влить сливки и сметану, посыпать мукой. Тушить 10 минут, посолить, поперчить по вкусу. Когда масса начнет загустевать, выключить огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6372,'Охлажденное тесто выложить в форму для выпечки, аккуратно закрыв все бока формы. Запечь тесто в духовке 15 минут, чтобы оно не было сырым, но и не полностью готовым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6372,'Выложить всю начинку на тесто и посыпать тертым сыром. Чем больше сыра на пироге, тем вкуснее получается жульен. Выпекать пирог «Курино-грибной жульен» в духовке 20 минут, пока сыр не приобретет золотистый цвет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6373,'Основа для пирога–песочное тесто. Для его приготовления необходимо растереть маргарин или сливочное масло с просеянной мукой в крошку. Затем добавить взбитое яйцо, сметану, соль и вымесить очень эластичное тесто. Скатать в шарик, обернуть в пищевую пленку и убрать на 30 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6373,'Для начинки используется вареный картофель и мясо. Картофель отварить в кожуре, затем очистить и порезать мелким кубиком. Мясо отварить в подсоленной воде до готовности, охладить и порезать кубиком. Лук очистить, порезать соломкой и обжарить на растительном масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6373,'Смешать все ингредиенты. Посолить, поперчить по вкусу, можно добавить любимые приправы, травы. Тесто выложить в форму для запекания, аккуратно распределив по бортам. Выложить всю начинку, распределив по всей поверхности равномерно. На начинку вылить яичную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6373,'Для приготовления яичной смеси необходимо взбить миксером яйца со сметаной, молоком и приправами. Затем высыпать мелко нарезанную зелень. Пирог с курицей и картофелем запекать в духовке 45 минут при температуре 180 градусов. Золотистая корочка сверху и румяные бока пирога говорят о его готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6374,'Для приготовления жульена необходимо отварить куриное мясо в подсоленной воде, затем порезать его на небольшие кусочки. Грибы обжарить на растительном масле с луком. Затем смешать курицу и грибы, залить сливками, присыпать мукой  и тушить на медленном огне до сгущения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6375,'Остывшие яйца мелко порубить, картофель, колбасу и огурцы нарезать одинаковыми кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6375,'Перед подачей окрошка с вареной колбасой на квасе перекладывается в тарелку, заливается несладким квасом, подается заправленная ложкой сметаны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6376,'Булочки следует разрезать на две половинки вдоль и вынуть мякоть. Крошки обжарить до хрустящего состояния на сливочном масле и высыпать в миску. Начинка для пиццы может состоять из мяса, овощей, грибов, колбасы, зелени, яиц, сыра. Колбасу или мясо измельчить, порезав на мелкие кусочки, овощи очистить и нарезать кубиками, грибы обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6376,'Смешать ингредиенты для начинки, добавить обжаренные крошки, сливки. Наполнить начинкой булочки, посыпать тертым сыром и отправить в духовку на 10 минут. Если смазать противень под булочками растительным маслом, пиццы будут немного поджаренными.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6376,'Заготовки под булочки-пиццы можно готовить заранее и хранить в морозильной камере. Потом быстрое приготовление в микроволновке или духовке и, завтрак готов через 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6377,'В состав входит авокадо, который следует почистить от кожуры, вынуть косточку и порезать на мелкие кубики. Затем порезанный фрукт полить соком лимона, чтобы зеленый цвет не потемнел.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6377,'Креветки очистить и обжарить на сливочном масле до розового цвета. Если креветки уже вареные, тогда с них следует слить лишнюю жидкость и полить небольшим количеством лимонного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6377,'В большую миску высыпать кукурузу, порвать листья салата, авокадо, порезанные кубиком огурец и сладкий перец. Все перемешать, майонез добавить перед подачей на стол. В салатницу выложить красивой горкой праздничный салат и украсить креветками, перепелиными яйцами и свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6378,'Для приготовления коблера необходимо порезать батон на тонкие кусочки, как на бутерброд. Каждый кусок смазать тонким слоем сливочного масла. В приготовленную круглую форму для запекания выложить ломтики хлеба ребром, но с промежутком в 3-4 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6378,'Помидоры порезать на тонкие кружочки и выложить между ломтиками батона. Ветчину нарезать очень тонко и вложить кусочки между хлебом, так, чтобы получилась гармошка из батона, помидора и ветчины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6378,'Приготовить смесь для заливки. Венчиком взбить яйца, посолить, добавить молотый перец и мускатный орех. Влить молоко и еще раз взбить венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6378,'Молочно-яичной смесью залить батон и посыпать сыром, натертым на средней терке. Во время приготовления молочная смесь и сыр максимально впитаются в хлеб, поэтому чем больше сыра будет сверху на коблере, тем вкуснее и румянее будет блюдо. Когда сыр зарумянится, коблер с ветчиной можно доставать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6379,'Самое полезное и не калорийное куриное мясо – грудка, поэтому в салате следует использовать именно его. Отварить грудку в подсоленной воде 20 минут. Затем охлажденное мясо порезать на небольшие кубики или порвать на волокна. Сложить мясо в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6379,'Самое полезное брокколи–свежее. Но можно использовать мороженое. Обдать брокколи кипятком, порвать на соцветия и сложить в салатницу. Маринованный огурец порезать на маленькие кубики или на длинные тонкие полоски, смотря, как измельчена курица. Добавить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6379,'Все ингредиенты перемешать и посолить щепоткой соли. Соль использовать йодированную или морскую пищевую. Соус для салата подойдет сметанный или майонез. Можно смешать майонез и сметану в равных пропорциях. Украсить салат «90-60-90» свежей зеленью, чем больше, тем лучше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6380,'Приготовить наливное тесто из кефира, яиц, сахара и муки. Для этого яйца взбить с сахаром миксером в пену. В кефире развести соду, гашенную уксусом. Теперь соединить две смеси и всыпать муку. Размешать тесто, по консистенции оно получается, как густая сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6380,'Форму для выпечки застелить бумагой и вылить треть теста. Выпекать в духовке корж 15 минут, до золотистого цвета. Во время выпекания корж поколоть вилкой. Так испечь три коржа. Крем для торта приготовить из кефира и сахара. Смешать ингредиенты и хорошо размешать. Чтобы сахар растворился, кефир можно немного подогреть, но не кипятить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6380,'Смазать коржи кефирным кремом, сложить. Для украшения торта «Если пропадает кефир» использовать продукты в наличии: кокосовую стружку, свежие фрукты, изюм, орехи, конфеты, шоколад.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6381,'Для салата-закуски необходимо отварить куриное мясо. Лучше использовать филе, чтобы потом порезать его на ровные плоские кусочки. Но можно вареное мясо порвать на волокна и выкладывать горкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6381,'Помидоры вымыть, просушить и порезать на тонкие кружочки. Листья салата хорошо вымыть и просушить. Выкладываем лист салата, на него кружок помидора, затем куриное мясо. На мясо полить соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6381,'Соус вкуснее использовать пикантный, чтобы подчеркнуть вкус салата. Отлично сочетается с мясом и помидорами сметанный соус с чесноком или соус из йогурта, горчицы, чеснока и молотого перца. Можно использовать обычный майонез, но лучше домашнего приготовления. На соус посыпать тертый сыр и еще раз полить соусом. Салат-закуску из курицы на помидорах украсить обжаренными кедровыми орешками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6382,'Для оладушек необходимо печень перемолоть на мясорубке, добавить жареный лук, яйцо и немного муки. Жидкое тесто выкладывать на сковороду, смазанную растительным маслом и жарить оладушки с двух сторон на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6382,'Охлажденные оладушки намазать майонезным соусом с чесноком с двух сторон. В майонез можно добавить мелко порезанную зелень или ложку горчицы. Затем оладушек с соусом окунуть в мелко натертый сыр. Выложить на широкую тарелку оладушки, украсив порезанными свежими овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6382,'Для украшения закусочных пироженок из печени лучше выбирать яркие цветные овощи–тертую морковь, мелко порезанный болгарский перец, тонко порезанный помидор. Выкладывать овощи на свое усмотрение и вкусовое предпочтение.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6383,'Натереть на терке необходимое количество сыра и приготовить несложное тесто. Смешать все сухие ингредиенты: муку, сахар, чесночный порошок и разрыхлитель, посолить щепоткой соли. Сливочное масло порезать на маленькие кубики и выложить к сухим ингредиентам. Все тщательно размять руками, чтобы получилась крошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6383,'В сухую смесь вылить теплое молоко и тертый сыр. Вымесить мягкое тесто, притрусить мукой, чтобы не липло к рукам. Все тесто скатать в рулет диаметром 5 см и нарезать острым ножом кусочки, чтобы получились маленькие лепешечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6383,'Противень для выпекания застелить пергаментной бумагой, духовку разогреть до 220 градусов. На бумагу, смазанную жиром, выложить сырные шарики и поставить в духовку на 15 минут. Температуру снизить до 200 градусов. Румяные ароматные мини-булочки с чесноком и сыром выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6384,'Батон нарезать на ломтики толщиной 2 см. В миске взбить яйцо венчиком, посолить и поперчить. Сыр натереть на терке и высыпать в яичную смесь. Колбасу и огурец порезать очень мелкими кубиками, добавить к яичной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6384,'Противень смазать растительным маслом и положить хлеб. На хлеб выложить смесь и поставить в духовку. Горячие бутерброды будут готовы через 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Нашинковать тонко капусту, говядину порезать тонкой соломкой, редис и огурцы натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'На разогретое в сковороде масло отправить мясо, обжарить говядину 2 минуты на среднем огне, потом добавить капусту, два вида молотого перца, соль, все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Убавив огонь, протушить 10 минут, переложить на блюдо или в тарелку, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Отварить лапшу в посоленной воде, далее остудить ее под холодной проточной водой, переложить в неглубокую миску, добавить немного растительного масла и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'С соевым соусом, перцем, уксусом, солью, растительным маслом перемешать мелкорубленные чеснок и кинзу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Яйца разбить в миску и чуть посолить, влить 2 ст.л. воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Из полученной яичной массы испечь несколько тонких омлетов, остудить, затем тонкими трубочками свернуть и нарезать тонкой лапшой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'В ледяной воде тщательно размешать соль, уксус, сахар, соевый соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6385,'Холодный корейский суп «Кукси» с говядиной подавать следующим образом: переложить в тарелку немного капусты с говядиной, далее уложить порезанный омлет, лапшу и салат из овощей, в готовое блюдо влить соус.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6391,'Взбить яйца, сахар до состояния крема, положить сгущенное молоко, сметану, взбить до однородности. Насыпать какао, муку, размешать венчиком. Погасить соду уксусом, добавить в смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6386,'Чтобы тесто получилось воздушным необходимо сахар, а лучше пудру, взбить с мягким сливочным маслом до получения пышной массы, похожей на густой крем. Желтки отделить от белков и добавить в масляную смесь по одному желтку, продолжая взбивать миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6386,'Белки взбить в пышную пену, соединить с масляной смесью. Добавить разрыхлитель. Затем постепенно всыпать муку, размешивая ложкой. Тесто должно получиться очень мягким, но не густым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6386,'Идеально чистые формочки наполнить тестом на 3/4. Сверху выложить начинку из творога. Для приготовления творожной начинки смешать творог, взбитые яйца с сахаром, ванилин и сливки. Все тщательно взбить миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6386,'Сверху начинки выложить вишенку или цукаты, сухофрукты. Выпекать кексы 25 минут при температуре 180 градусов. Готовность проверить спичкой. Румяные кексы с творожной шапкой остудить и посыпать по желанию сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6387,'Сначала надо приготовить карамель из сахара. Для этого стакан сахара растопить на сковороде, постоянно помешивая. Затем ОЧЕНЬ АККУРАТНО влить стакан воды в расплавленную карамель. Томить воду с карамелью, чтобы полностью сахар растворился. Это карамельный цвет нашего лимонада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6387,'Лимон и мяту помыть и нарезать на небольшие кусочки. Затем все сложить в кипящий сироп и отставить настаиваться 1 час. За это время сироп остынет и приобретет насыщенный лимонный аромат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6387,'Сироп процедить через марлю, налить в двухлитровую бутылку. Затем дополнить до верха сильногазированной водой. Закрутить лимонад плотно крышкой и положить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6388,'Для приготовления тефтелей необходимо отварить рис до полуготовности в подсоленной воде. Если рис отварить до готовности, то тефтели могут разваливаться во время жарки. Лук порезать мелким кубиком и обжарить до прозрачности на сковороде. Фарш немного отбить, чтобы мясо приобрело плотность и, тефтели получились сбитыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6388,'Соединить фарш, жареный лук, рис, яйцо, посолить по вкусу. Тщательно вымесить фарш. Сформировать тефтельки размером с грецкий орех. Обвалять в муке и обжарить на растительном масле до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6388,'Затем в сковороду с обжаренными тефтелями влить стакан горячей воды, немного подсоленной, лавровый листик и ложку томатной пасты. Накрыть крышкой и дать покипеть на медленном огне минут 10.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6388,'В теплой воде развести муку и сметану, хорошо размешать комочки. Эту смесь вылить в сковороду, накрыть крышкой и немного потрусить сковороду, чтобы тефтели окунулись в мучную подливку. Протушить 15 минут на медленном огне. Подавать мясные тефтели с подливкой к гарниру из картофеля, спагетти или овощному рагу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6389,'Измельчить хлопья в блендере или кофемолке. Просеянную муку соединить с содой. Мягкое сливочное масло растереть с сахаром, добавить взбитое яйцо, мед и сметану. Тщательно все размешать. В эту массу высыпать измельченные хлопья и муку с содой. Вымесить тесто, чтобы можно было набирать ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6389,'Противень застелить бумагой для выпечки, ложкой выложить тесто. Выпекать овсяное печенье 15 минут при температуре 200 градусов. Чтобы печенье было более полезное и вкусное, можно добавить измельченные орехи или изюм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6390,'Приготовить бисквит: смешать яйца, сахар, муку. Разделить тесто пополам, пропитать сиропом: смешать коньяк или ликер с водой, насыпать сахар, размешать. Желательно использовать формочку с отстегивающимися бортиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6390,'Приготовить крем-суфле: Первый слой: замочить желатин в воде, измельчить бананы в блендере, взбить сметану с сахаром, чтобы масса была пышной, можно добавить 35-процентные сливки. Все соединить, налить желатин. Вылить массу на первый слой бисквита. Отправить в холодильник на шестьдесят минут, чтобы все застыло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6390,'Второй слой: смешать сметану, взбитые сливки, сахар, желатин. Получается светлое сливочное суфле, которым заливается второй бисквит, уложенный на застывший ранее крем. Отправить в холодильник. Третий слой: перетереть клубнику с сахаром, варить, пока растает сахар, добавить желатин, вылить сверху, отправить бисквитный торт с суфле в холодильник на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8092,'Нарезать небольшими кубиками помидоры, выложить на лаваш вместе с измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6391,'Застелить формочку бумагой, распределить тесто, готовить минут двадцать, соблюдая температуру 180 градусов. Когда остынет, убрать бумагу, порезать пышку продольно на три одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6391,'Взбить сливки до состояния крема, медленно насыпать сахар. Тоненько порезать бананы. Смазать пышку кремом, выложить слой бананов, потом крем, сверху пышку, намазать кремом и так далее. Бока подравнять, со всех сторон и сверху намазать кремом. Сверху и бока посыпать стружкой кокоса, украсить торт с банановым кремом клубничкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6392,'Приготовить тесто: взбить сахар и яйца. Растопить на водяной бане мед и сливочное масло. В конце положить соду. Продолжать мешать на водяной бане до образования пены.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6392,'Убрать с бани, положить взбитые яйца, замесить тесто, насыпая медленно муку. Тесто не должно липнуть. Сделать из него круг, поделить на восемь частей. Из каждой раскатать корж толщиной пять миллиметров. Сначала форма может быть произвольной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6392,'Готовить все коржи по четыре минуты. В теплом состоянии обрезать по тарелочке, остатки оставить для присыпки. Приготовить крем: смешать сметану и обыкновенный и ванильный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6392,'Обильно намазать коржи кремом, лучше, пока они теплые. Измельчить обрезки в блендере, посыпать торт «Медовик» со сметанный кремом через ситечко. Отправить тортик в холодильник часов на десять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6393,'Разогреть духовку до 180 градусов. Смешать в большой емкости сметану, мягкое сливочное масло, сахар. Насыпать медленно разрыхлитель и муку, сделать песочное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6393,'Пропустить тесто через мясорубку, сформировать средние лепешки или комочки, положить их на противень, смазанный маслом. Если мясорубка отсутствует, то отщипывать шарики и выкладывать на противень. Готовить минут пятнадцать, соблюдая температуру 180 градусов, до коричневатого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6393,'Приготовить крем: соединить мягкое масло и вареную сгущенку, смешать до однородности. Отправить на какое-то время в холодильник. Приготовленное печенье чуть-чуть покрошить руками. Раскрошенное печенье положить в емкость с кремом, размешать. Выложить всю смесь горкой на блюдо, убрать торт «Муравейник» на шестьдесят минут в холодильник для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6394,'Срезать корешки с рукколы, положить в блендер, влить масло. Посыпать солью. Нарезать лосося маленькими квадратиками. Отрезать восемь тоненьких долек лимона, остальное выжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6394,'Соединить порезанного лосося с лимонным соком, сметаной и 3/4 измельченного лука. Положить в емкость, накрыть полиэтиленом, отправить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6394,'На сервировочную тарелочку положить 1/8 смеси тартара. Прижать выпуклой поверхностью ложки. Выложить порезанный лимон. Сбрызнуть «Тартар» из лосося приготовленным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6395,'Взбить желтки с половиной сахара до пышной, светлой массы. Белки взбить до плотной массы. Насыпать остальной сахар, взбить. Соединить две массы. Насыпать просеянную муку и какао, размешать, аккуратно, двигаясь от краев к центру. По краю осторожно влить растопленное, охлажденное масло, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6395,'Взять формочку размером 23 сантиметра, смазать маслом, присыпать мукой. Вылить в нее тесто, готовить минут тридцать, соблюдая температуру 200 градусов. Дать постоять на решетке часов восемь. То есть, готовый бисквит минут пять охладить в формочке, перевернуть на решетку и отставить минимум на восемь часов на кухне. Решетка не даст отмокнуть дну бисквита.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6395,'Смешать желтки сначала с водой, налить сгущенное молоко. Варить на маленьком огне до сгущения. Можно использовать водяную баню. Остудить сироп, налить к маслу, взбитому предварительно с ванильным сахаром. Наливать по чуть-чуть, взбивая. В конце насыпать какао.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6395,'Разрезать бисквит на три части вдоль, прослоить кремом. Сверху торт намазать джемом. Налить шоколадную помаду: растопить на водяной бане масло и шоколад. Глазурь для торта «Прага» необходимо делать с запасом, так как она стекает.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6396,'Чуть-чуть взбить яйцо, 1/4 часть оставить, чтобы смазать сырники сверху. Протереть творог через ситечко, если он крупный. Смешать яйцо, творог, сахар и соль. Положить манную крупу, перемешать. Отставить минут на двадцать, чтобы манка разбухла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Добавить охлажденный сок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6396,'Сделать влажными руками плоские сырники круглой формы, обвалять в муке, уложить на противень, с фольгой, смазанной маслом. К оставшемуся яйцу добавить чайную ложку молока или воды, взбить, смазать сырники сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6396,'Поставить минут на десять в духовку, соблюдая 200 градусов. Подавать сразу. Сырники из творога с манкой в духовке получаются внизу с золотистой корочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6397,'Смешать ингредиенты, завернуть в бекон. Обжарить сырники в беконе под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6398,'Помыть лимон, снять цедру. Выдавить чуть-чуть сока. Растереть сахарную пудру и масло, положить цедру и сок. Перемешать до однородности. Вбить яйца, положить творог и манку. Переложить равномерно смесь в формочку, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6398,'Готовить минут шестьдесят, соблюдая температуру 180 градусов. Остужать пирог минут тридцать в приоткрытой духовке. Осторожно вынуть из формочки, переложить на блюдо, посыпать творожник «Лимонный» сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6399,'Тесто необходимо приготовить за день. Соединить тертое холодное сливочное масло с мукой, перемешать, положить творог, посыпать солью, сразу размешать, отправить в холодильник на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6399,'Приготовить начинку: на топленом масле чуть-чуть обжарить лук, порезанный кубиками. Положить фарш, обжаривать вместе. Приправить, готовить минут пятнадцать на среднем огне. Охладить, соединить с яйцом, зеленью, белком, сметаной, если требуется снова приправить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6399,'Поделить тесто на неодинаковые части. Кусок побольше раскатать в лепешку 50 миллиметров толщиной. Помогая скалкой, переложить пласт на противень, застеленный пергаментом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6399,'Равномерно распределить начинку, если она очень влажная, сначала посыпать тесто молотыми орехами. Раскатать второй кусок, положить на начинку, защипнуть краешки, из обрезков раскатать пласт, порезать на полосочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6399,'Намазать пирог желтком, смешанным с молоком. Украсить румынский пирог с мясным фаршем полосками теста, намазать желтком, посыпать кунжутом. Отправить в духовку на 25 минут, готовить при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6400,'Отварить картофель и мелко натереть. Положить майонез, посыпать солью, положить на блюдо слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6400,'Порезать лук полукольцами, пожарить, положить на картофель. На лук положить мелко потертые яйца, полить майонезом. На него потереть сыр, налить майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6400,'Болгарский перец порезать на кубики, соединить с майонезом, положить на сыр, можно посыпать простой и вкусный салат кубиками перца без майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6401,'Хорошо вымыть свеклу, морковь, картофель, отварить и очистить от кожуры. Желатин замочить в четверти стакана холодной воды на 30-40 минут, затем прогреть на водяной бане до полного растворения, но не кипятить. Перемешать с майонезом и сливочным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6401,'Свеклу и морковь натереть на мелкой терке, картофель – на крупной. Все овощи немного посолить. Нарезать кусочками очищенную слабосоленую сельдь, удалить косточки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6401,'Застелить рабочую поверхность пищевой пленкой в несколько слоев, полосы должны располагаться внахлест. Можно положить под пленку полотенце – свернуть рулет будет проще.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6401,'Выложить слоями свеклу, картофель, морковь, сельдь, каждый слой промазывать майонезной смесью. Слои должны быть разной величины, каждый последующий меньше предыдущего, сельдь выложить по вертикали, неширокой полосой в треть общей ширины. Свернуть салат-рулет «Сельдь под шубой», положить в холодильник до полного застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6402,'Для торта нужно приобрести готовые бисквитные коржи в магазине. Для приготовления крема размягченное сливочное масло комнатной температуры взбить со сгущенным молоком, добавить кокосовую стружку. Сливки взбить отдельно и соединить с кремом, добавлять порциями, осторожно перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6402,'Кремом смазать коржи, выложить их друг на друга. Бока и верх также обмазать сливочной массой, посыпать кокосовой стружкой. Оставить торт «Рафаэлло» при комнатной температуре на несколько часов для пропитывания, затем поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6403,'Осетровое филе порезать на кусочки, добавить перец и соль, покрыть мукой, обмокнуть во взбитом яйце, запанировать сухарями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11128,'Перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6403,'В оставшееся после жарки филе масло засыпать муку, перемешать и слегка протушить, затем залить рыбный бульон, дать закипеть и убрать с огня, далее положить соль, сметану, перец, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6403,'В разогретый до 200 градусов духовой шкаф отправить форму с рыбой, политой готовым соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6403,'Готовится осетр в панировке по-польски в сметанном соусе до появления румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6404,'Для теста отделить сырые желтки от белков. Последние взбить с сахарным песком, добавить желтки и осторожно перемешать, продолжать взбивать. Отдельно смешать сметану с какао-порошком, добавить в яичную массу. Всыпать просеянную пшеничную муку, разрыхлитель, вымешать, разделить массу пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6404,'Форму смазать маслом, выпечь поочередно два коржа в течение получаса каждый, температура – 180 градусов. Для первого крема сварить манную кашу на молоке, она должна быть без комочков. Всыпать сахарный песок, положить сливочное масло, перемешать. Массу остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6404,'Для второго крема измельчить крекеры, перемешать крошку со сгущенным молоком и цельным обжаренным арахисом. Остывшие коржи сложить в следующем порядке: корж, половина манного крема, весь арахисовый крем, остатки первого крема, накрыть вторым коржом. На водяной бане или в микроволновой печи растопить шоколад, полить им торт «Сникерс». Готовый десерт можно украсить арахисом или просто нарисовать ножом узоры на шоколадной глазури.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Для сиропа соединить в сотейнике воду, сахарный песок и глюкозу или кукурузный сироп. Массу перемешать, довести до кипения, подержать на огне в течение нескольких секунд. Остудить, хранить в холодильнике, в закрытой емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Измельчить миндаль в муку, всыпать сахарную пудру, влить сироп, взбить до однородного состояния. Пасту из миндаля прогреть в микроволновой печи, добавить сахар, желтки по одному, в конце – яйца целиком. Оставшиеся белки взбить в плотную пену, постепенно вводить сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Шоколад растопить на водяной бане, вмешать сливочное масло, затем ввести небольшое количество белковой массы, перемешать, влить миндальную смесь. Всыпать сухие ингредиенты: просеянную пшеничную муку, какао-порошок. В последнюю очередь ввести остатки белков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Застелить противень бумагой для выпечки, распределить часть полученного теста тонким слоем, печь при температуре 180 градусов в течение 10 минут. Готовность коржа проверить спичкой или зубочисткой. Таким же образом испечь три одинаковых коржа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Приготовить шоколадный ганаш. Растопить шоколад в микроволновке или на водяной бане. Довести до кипения сливки, но не кипятить, добавить мёд, перемешать. Треть медовой массы влить в шоколад, перемешать, затем ввести остальную смесь, порциями. Остудить ганаш до 35 – 40 градусов, взбить блендером до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Приготовить шоколадную глазурь, для этого замочить в холодной воде желатин. Отдельно соединить воду, какао-порошок, сахарный песок и сливки. Массу довести до кипения, подержать на огне минуту, затем остудить до 50 градусов. Отжать желатин и ввести в горячую смесь, перемешать и остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Первый корж выложить на дно разъемной формы, смазать абрикосовым джемом, слой должен быть ровным. Затем полить частью шоколадного ганаша, разровнять. Остальные коржи прослоить также, сверху – джем и шоколад. Выпечку убрать в холодильник на 12 часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6405,'Шоколадный «Захер» вынуть, снять бортики, покрыть теплой глазурью, прогретой до 35 градусов. Поставить торт в холодильник на шесть часов или больше. За час до подачи десерт вынуть, дать согреться при комнатной температуре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6406,'Картофель в мундире отварить, остудить и очистить, затем размять, брынзу хорошенько растереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6406,'Поверхность стола посыпать мукой, положить размятый картофель и соединить его с просеянной мукой, посолить, затем вбить яйца, вымесить картофельное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6406,'Готовое тесто разделить на несколько частей, каждую из которых скатать валиком диаметром в 3 см, порезать их на ломтики, придав им круглую форму, выложить в середину каждого круга по ложке растертой брынзы, края защипнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8092,'Добавить готовую морковь по-корейски, её можно дополнительно нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6406,'На сковороде растопить масло сливочное, смешать его с подсушенными и чуть подрумяненными сухарями, перед тем как подать к столу, полить кнели картофельные по-польски с брынзой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6407,'Очищенные бананы и клубнику нарезать, оставить одну ягоду для украшения. С помощью миксера взбить нежирный творог с холодным молоком в кремообразную массу, влить две столовые ложки заваренного кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6407,'Выложить треть бананов на дно салатницы с плоским дном, затем – слой клубники, тертый темный шоколад, творожную массу. Слои повторить еще два раза, в том же порядке, сверху должен быть творог и тертый шоколад. Положить оставленную ягодку клубники, поставить тирамису с творогом в холод на четыре часа, можно на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6408,'Большое куриное филе нарезать небольшими кусочками, репчатый лук – тонкими полукольцами.  Обжарить на сухой сковороде семена тмина, прогревать до появления легкого аромата, затем истолочь в ступке, посыпать ими куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6408,'Разогреть в сотейнике оливковое масло, обжарить курицу и лук, массу помешивать. Кукурузный крахмал развести в апельсиновом соке, добавить тертую цедру одного апельсина, массу перелить к курице, всыпать куркуму, прогревать филе куриное с апельсиновым соусом в течение двух минут. Соль и перец молотый – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6409,'Сливочное масло размягчить, смешать с мелко нарубленным укропом, посолить массу по вкусу. Завернуть в виде «колбаски» в пищевую пленку и положить в морозильную камеру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6409,'Отделить малое куриное филе от большого. Последнее прорезать острым ножом вдоль с утолщенной стороны, как если бы мы разрезали корж для приготовления торта. Разрезать не до конца, затем «раскрыть» филе, как книжку. И малое, и большое филе хорошо отбить с обеих сторон. Натереть солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6409,'Вынуть масло из холодильника, разрезать пополам и выложить на каждое большое филе по половинке. Сверху накрыть малыми филе, плотно завернуть, сформовать продолговатые котлеты. Заворачивать плотно, масло при обжаривании не должно вытечь. Котлеты завернуть в пищевую пленку, положить в морозильную камеру на 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6409,'Достать охлажденные котлеты, обмакнуть в пшеничную муку, затем в кляр, приготовленный из молока и яиц, в последнюю очередь – в панировочные сухари. Снова обмакнуть в кляр и сухари.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6409,'Разогреть на сковороде большое количество растительного масла, обжарить котлеты во фритюре, со всех сторон, до образования золотистой корочки. Выложить котлеты по-киевски в посуду для запекания и довести блюдо в духовке до готовности в течение 4 – 5 минут, температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6410,'Курицу вымыть обсушить полотенцем, выложить в емкость. Тушку сбрызнуть и натереть кунжутным маслом. Перемешать коричневый сахар, кунжутное семя, молотый корень имбиря, соль и давленый чеснок, добавить чайную ложку красного кайенского перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6410,'Смесью присыпать курицу со всех сторон, выложить на противень на спинку, печь курицу с кунжутом и имбирем в течение 20 – 25 минут при температуре 215 градусов до образования коричневатой хрустящей корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6411,'Отварить куриную грудку, нарезать крупными ломтиками. Кусочками такого же размера нарезать копченую куриную грудку. Репчатый лук порезать полукольцами, ошпарить кипятком. Отварить перепелиные яйца, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6411,'Перемешать лук с курицей, добавить маринованные опята, черный молотый перец – по вкусу. Заправить майонезом, лучше, если он будет домашнего приготовления, перемешать. Разложить салат «Мужская мечта» в порционные тарелки, сверху – перепелиные яйца, разрезанные пополам, украсить перышками зеленого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6412,'Залить курагу горячей водой, через некоторое время жидкость слить, плоды сполоснуть и обсушить с помощью бумажных полотенец. Куриные филе разрезать вдоль, отбить молотком, накрыв пленкой. Посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6412,'На каждую пластинку мяса выложить по 8-10 штук плодов кураги, по 3–4 колечка горького красного перца, по веточке розмарина, укропа или шалфея, можно добавить по вкусу любые другие специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6464,'Влить в пюре половину желатинового раствора, хорошо перемешать, уложить 3/4  полученной массы равномерным слоем на хорошо застывший корж, дать застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6412,'Мясо с начинкой скатать в рулетики. Расстелить на рабочей поверхности пищевую пленку в два слоя, завернуть в нее рулеты и крепко перевязать концы. Положить в кастрюлю, полностью залить водой, варить в течение 40 минут. При готовности закусочные рулетики из курицы с курагой вынуть, остудить, удалить пленку, нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6413,'Зачистить кусок печени от пленок, залить молоком, дать постоять треть часа, прокрутить, добавить яйцо и лук, сдобрить специями, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6413,'Всыпать муку до получения густого «теста», консистенция его должна напоминать обычное тесто для оладий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6413,'Нагреть в сковороде масло, обжарить котлетки из свиной печени с двух сторон до коричневатой корочки, подать с салатом, картофельным пюре или рисом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6414,'Взбить яйца с добавлением небольшого количества воды при помощи венчика, подсолить, поперчить. Разогреть сковороду, высыпать в нее нашинкованный лук, брокколи, протушить 3-5 минут, подсолить, поперчить, добавить порезанный шпинат, протушить все вместе еще несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6414,'Залить овощи разболтанными яйцами, перемешать, дать пару минут схватиться под крышкой, полить соусом, присыпать пиццу-омлет сыром, разложить по поверхности колбасу. Убрать крышку, сковороду поместить на 3-4 минуты под бройлер, присыпать зеленью петрушки и хлопьями сухого красно перца, подать сразу к столу вместе с тостами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6415,'Подготовить тушку рыбы, порезать на куски, переложить ее в форму для запекания, присыпать перцем, подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6415,'Смазать рыбу майонезом, присыпать мелкой сырной стружкой, поставит в духовку с температурой 180 градусов, запеченная горбуша под сыром, будет готова примерно через полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Муку вместе с маслом порубить, дрожжи растереть с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'К муке, маслу и дрожжам с сахаром вбить  1 яйцо,  добавить соль, 2 яичных желтка, сметану, хорошенько перемешать и сразу же приготовить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Тесто раскатать в прямоугольник, толщина которого 5 мм, разделить его пополам так, чтобы вышло два прямоугольника размером  30х10 или 30х12 см',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Через мясорубку пропустить колбасу, смешать ее с тертым сыром, сухарями и сырым яйцом, массу тщательно растереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Подготовленную начинку выложить валиком на тесто, отступая от краев по 2 см, плотно свернутое тесто приплюснуть тупым ребром ножа, сделать решетку и порезать как на ленивые вареники.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Лист для выпечки смазать маслом и припудрить мукой, разложить на нем пирожки с сырно-колбасной начинкой из песочного дрожжевого теста, поставить в тепло для поднятия, затем промазать яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6416,'Духовку прогреть до средней температуры и отправить в нее противень с пирожками на 20-30 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6417,'Для кляра разболтать яйца с пивом, всыпать муку, тщательно перемешать, подсолить, поперчить. Подготовить лук, порезать на кольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6417,'Налить в прогретую глубокую сковороду масло слоем в 1 см, раскалить его. Погрузить кольца в кляр, осторожно положить в сковороду, обжарить с одной и другой стороны до желаемого румяного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6417,'Переложить луковые кольца в кляре на полотенце из бумаги или салфетки. Когда излишки масла впитаются можно присыпать кольца по вкусу любимыми специями, сразу подать аппетитно хрустящую закуску к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6418,'Сложить в блендер медовые шарики либо хлопья, кусочки замороженных бананов (можно кубики льда и бананы), всыпать сахар, влить молоко. Добавить для улучшения вкуса бананового коктейля ванильный сахар, взбить, разлить по высоким стаканам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6419,'В картофельное пюре добавить яйцо, перемешать, переложить в форму промазанную маслом, разровнять верх, прикрыть тонким слоем томатной пасты, разложить сосиски, присыпать натертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6419,'Поставить запеканку с сосисками в духовку с температурой чуть ниже 185 градусов, достать через 15 минутной зеленью, присыпать измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6420,'Включить для прогрева до 175 градусов духовку. Перемешать фарш с овсяными хлопьями, луком, кукурузной мукой. Вбить яйцо, добавить томатный сок, сухари панировочные, чуть воды, соус барбекю, уксус, сахар, подсолить, влить чайную ложку жидкого дыма. Хорошо вымешать, заполнить фаршем форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6420,'Перемешать в мисочке коричневый сахар с горчицей, кетчупом и парой ложе жидкого дыма до однородности, промазать фарш сверху, поставить выпекать в уже прогретую духовку. Мясная буханка «Митлоф» будет готова примерно через час, подавать к столу с любым гарниром, блюдо вкусно как в горячем, так и в охлажденном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6421,'Смешать (не взбивая) яйца с сахаром и стружкой кокоса в однородную массу, включить духовку, дать прогреться до 180 градусов. Скатать из «теста» небольшие шарики, переложить на застланный пергаментом противень. Вкусное хрустящее печенье «Кокосанка» будет готово примерно через 25-30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6422,'Подготовленные отбивные обмакнуть в смесь муки, тимьяна, перца и соли, обжарить их в сильно разогретом масле. Мясо вынуть, а на этом масле обжарить кубики лука, нарубленный чеснок и грибы, всыпать в конце остатки панировки, перемешать, обжарить все вместе около полутора-двух минут, долить куриным бульоном, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6422,'Уменьшить нагрев, продолжать тушить до сгущения соуса, добавить рукколу, прогреть еще пару минут. Подавать горячую свинину с рукколой и грибами вместе с соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6423,'Кочан разрезать на четвертинки, вырезать кочерыжку, отварить минут 10 в крутом кипятке, хорошо отцедить, остудить, прокрутить на мясорубке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6423,'Раздавить прессом чеснок, натереть лук, объединить с капустой, добавить муку, зелень, яйцо, подсолить, перемешать. Сформовать из фарша капустные котлетки, обжарить до корочки темно соломенного цвета, подать с любым соусом или сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6424,'Уложить на плоскую тарелку салат в следующем порядке. Первый слой – кубики куриной грудки, смазать майонезом. Второй – тонко нашинкованные кольца маринованного лука. Третий из крупно натертых яиц, покрытых майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6424,'Далее уложить слой из мелко тертого сыра, смазанного майонезом. Последний слой в салате «Маринара» — подсоленные и поперченные мелкие кубики мякоти помидора без косточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6425,'Перемешать с размятым сыром, сметаной и брынзой порубленный чеснок, перец порезать на небольшие кубики, маслины – на кружочки, объединить с сырной массой. Разрезать кочанчик капусты пополам, аккуратно промазать листики одной половинки тонким слоем полученной смеси, повторить все со второй половинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6425,'Сложить их вместе, «запеленать» плотно пищевой пленкой. Положить закуску «Пекинская мозаика» с сыром на пару часов в холодильник. Достать закуску, порезать на шайбочки, обрызгать лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6426,'Сварить рис в подсоленной воде (должен быть рассыпчатым), отдельно — морковь и яйца, хорошо все остудить. Первым слоем тела «овечки» будет крупно натертая морковка, затем сыр, натертый на такой же терке. Далее уложить размятые рыбные консервы, чуть подсолить их и поперчить, присыпать нашинкованным мелко луком, а потом прикрыть майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6426,'Теперь выложить слой крупно натертых яиц с майонезом, убрать слоеный салат «Овечка» в холодильник минимум на час-полтора для пропитки. Достать блюдо, выложить из слоя риса «шкурку» овечки, оставить место головы свободным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6426,'Для оформления копытцев пару плодов маслин разрезать вдоль. Остальные семь штук мелко покрошить, выложить на место головы, сделать из половинки маслины ухо, а из другой, слегка подрезанной, сделать зрачок глаза, уложив его на каплю из майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6427,'Чеснок измельчить с помощью чесночницы, перемешать его с сыром «Филадельфия», майонезом, тертым сыром, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6427,'Свеклу порезать тонкими кружочками, сложить кружки один на одного, обрезать их так, чтобы получились треугольники одинакового размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6427,'Полученные треугольнички промазывать подготовленной начинкой, уложить их друг на друга до нужной высоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6427,'Закуска новогодняя из свеклы и сыра подается следующим образом: готовые треугольники выкладываются на плоскую тарелку, украшаются зеленью, поливаются маслом и посыпаются рублеными орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6428,'Отварить до готовности под крышкой рис, дать постоять четверть часа, выложить в миску, добавить рисовый уксус, сахар, подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6471,'Продукты выложить на блюдо слоями: картофель, рыба, лук, яйца, сыр. Все слои промазать майонезом, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6428,'Перемешать с рисом пару столовых ложек икры тобико (цвет любой), разрезать лист нории на две одинаковые части поперек перфорации. Руки слегка смочить водой, переложить окрашенный рис на нории, разровнять, завернуть на один оборот вокруг огурца, разрезать вдоль огурца на две равные части, а потом еще раз пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6428,'Разложить на бамбуковом коврике вторую половинку листа нори, положить на нее 2\4 ролла, срезы должны смотреть наружу, с помощью коврика приподнять нори.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6428,'В середину поместить любую начинку (овощи, либо японский омлет или т.п.). Для ролла «Мозаика» взять немного лосося, прикрыть его оставшимися двумя четвертинками ролла. В результате получится ролл оригинальной квадратной формы, порезать его очень острым ножом на равные четыре части (края подровнять). К столу роллы подавать с вассаби и маринованным корнем имбиря.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6429,'Натереть яблоко без шкурки на терке, объединить с яйцом и творогом, хорошо перемешать. Приготовить формочки для микроволновки, разложить массу почти до самого верха, поскольку суфле при выпечке практически не поднимается, поставить их на 5 минут в микроволновку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6429,'Готовность творожного суфле с яблоком в микроволновке проверить, потрогав осторожно верх десерта. Если на пальце нет следа от творога, то суфле готово, в противном случае подержать в печке еще пару минут. Выпекать этот десерт можно и в духовке, вместо яблок, возможно, использовать любые другие любимые фрукты по сезону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6430,'Добавить к рыбному фаршу прокрученную луковицу, всыпать молотые сухари, приправить белым перцем, подсолить, перемешать. Скатать небольшие фрикадельки, разложить их по формочкам, задвинуть в духовку с температурой чуть ниже 2000 градусов минут на 5.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6430,'Из смеси сливок с тертым сыром, приправленным перцем и солью приготовить соус. Вынуть формочки из духовки, промежутки между фрикадельками заполнить соцветиями брокколи (если не любите эту капусту, то можно обойтись и без нее), залить соусом. Поставить фрикадельки из рыбы под сыром запекаться в духовку на треть часа при температуре порядка 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6431,'Залить дрожжи парой столовых ложек теплой воды. Засыпать в миску муку с сахаром, добавить масло, по щепотке ванили и соли, дрожжи, порезанное на кусочки яйцо, вымесить тесто до гладкой однородной массы, оставить его для созревания на пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6431,'Раскатать в полусантиметровый пласт, вырезать песочно-дрожжевое печенье формочками, стаканом или просто порезать ножом на сегменты, обмакнуть одну сторону заготовки в сахар. Переложить печенье на противень , задвинуть минут на 15 в духовку с температурой порядка 185 градусов, выпекать до коричневатой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6432,'Перемешать яйца с молоком, можно для простоты использовать блендер, всыпать манку, все вместе еще раз очень хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6432,'Форму обложить кружочками банана, залить полученной смесью, установить в пароварку. готовить минут 40. Достать готовый банановый пудинг, остудить, порезать на порции и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6433,'Сварить курицу и яйца, лук порезать на мелкие кубики, обжарить на масле до золотого цвета. Остывшее мясо порезать на довольно мелкие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6433,'Выложить на плоское блюдо слой обжаренного до золотистости лука, далее – курятину, присыпать крупно натертым белком, промазать майонезом. Далее выложить кукурузу и прикрыть ее крупно натертым яблоком (без кожуры), побрызгать соком лимона и  промазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6433,'Натереть крупно замороженный плавленый сырок, выложить этот слой на яблоки с майонезом и тоже промазать его верх тонким слоем майонеза. Присыпать верх слоеного салата «Нежная курочка» мелко натертыми желтками и убрать его в холодильник минимум на час для пропитки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6434,'Запеченную или отваренную куриную грудку нарезать тонкой соломкой, маринованные грибы – пополам, полутвердый сыр любого сорта – кубиками. Консервированные ананасы отцедить от жидкости, обсушить, нарезать кубиками среднего размера. Все ингредиенты перемешать, посолить по вкусу, перемешать и заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6472,'Голени хорошо промыть холодной водой, кожу лучше удалить. Для приготовления маринада смешать соевый соус, майонез, зерна горчицы, карри, давленый чеснок. Массу перемешать, положить куриное мясо на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6435,'Перемешать пищевую соду с пшеничной мукой, перетереть массу руками в крошку с охлажденным и нарезанным маргарином. Влить кефир, замесить тесто, сделать это быстро, чтобы масса не успела согреться. Положить тесто на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6435,'Часть теста отделить, раскатать в тонкий пласт прямоугольной формы. Нарезать его на полоски, ширина – 8 мм, можно сделать это с помощью ножа для пиццы. Разложить на каждой полоске вишенки без косточек, близко друг к другу, посыпать ягоды сахаром. Защипнуть края теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6435,'Готовые «трубочки» свернуть «улитками», каждую соединить со следующей, в единую полоску, одновременно сворачивая в спираль. Делать это нужно уже на застеленном бумагой противне или в форме из силикона. Печь кольцевой пирог с вишней при температуре 180 градусов в течение получаса. При подаче выпечку посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6436,'Сыр моцарелла нарезать на небольшие квадратики. В три небольшие мисочки выложить пшеничную муку, сухари для панировки, кляр из взбитых с молоком яиц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6436,'Каждый кусочек сыра по очереди окунуть в муку, затем – в яйцо, и в сухари. В сковороде или в кастрюле растопить сливочное масло, довести до кипения. Слой масла должен быть в пять сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6436,'Порциями, по несколько квадратиков опускать в масло на одну минуту. На поверхности должна образовываться золотистая корочка. Доставать сырные кубики шумовкой. Сразу выкладывать на бумажные полотенца для впитывания излишков жира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6437,'Приготовить тесто из пшеничной муки, сахарного песка, яиц, пищевой соды, погашенной уксусом. Массу разделить на две части, в одну добавить какао-порошок. Вылить в посуду для выпечки обе смеси, друг на друга. Выпечь до готовности, проверить спичкой или зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6437,'Залить кипящей водой желатин, поставить на огонь, до кипения не доводить. Взбить сливки со сметаной и сахарным песком, влить остывший желатин, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6437,'Готовый бисквит произвольно нарезать, любыми фигурками, кубиками, пластинками. Большую полукруглую чашу застелить пищевой пленкой. Каждый кусочек обмакивать в желатиновый крем и выкладывать в чашу. Поставить торт «Нежный» на ночь в холодильник, утром посыпать тертым темным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6438,'С хлеба срезать всю корочку и перемолоть его в крошку, добавить масло растопленное , перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6438,'Рыбу порезать кубиками, также нарезать очищенное яблоко, мелко нашинковать очищенный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6438,'Яблоко смешать с луком, солью и сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6438,'В форму в виде круга или квадрата выложить слои: рыба, половина хлебной крошки, яблоко с луком и сметаной, хлебная крошка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6438,'Тартинки слоеные с яблоками и лососем поставить в холодильник на 1 час, далее по бортикам формы провести ножом, перевернуть ее дном вверх на блюдо плоской формы, украсить зеленью и поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6439,'Испечь тонкие блинчики по любимому рецепту, понадобится шесть штук. Натереть плавленый сыр на мелкой терке, добавить в массу давленый чеснок, рубленую зелень, майонез, перемешать. Тонко нарезать свежие огурцы и помидоры, можно сделать это с помощью шинковки, сладкий болгарский перец любого цвета – полосками. Отварить сосиски, очистить от пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6439,'Расстелить на рабочей поверхности пищевую пленку, выложить два блина, намазать сырной начинкой, выложить третий блин, снова намазать, затем выложить слоями огурцы и помидоры, посолить, поперчить по вкусу, добавить майонез. Накрыть тремя блинчиками, промазать остатками начинки, выложить перец и сосиски. Свернуть закусочный рулет из блинов, сосиски окажутся в середине, обмотать пленкой, поставить в холод на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6440,'Свиные копченые ребрышки залить водой, поставить на огонь, варить в течение часа. Мясо остудить, отделить от костей. Промыть горох в холодной воде, добавить в бульон вместе с мясом, варить еще полчаса. Мелко измельчить репчатый лук, натереть морковь на средней терке, нарезать кусочками бекон или грудинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6440,'Обжарить грудинку на сухой сковороде. Всыпать лук и морковь, жарить все вместе до полуготовности. Можно добавить тертый корень петрушки или пастернака–вкус супа будет насыщеннее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8092,'Лаваш аккуратно свернуть в трубочку, затем разрезать на две-три части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6440,'Очистить клубни картофеля, нарезать кубиками, добавить в суп и варить в течение пяти минут. Затем добавить грудинку с овощами, соль и молотый перец – по вкусу. Варить до готовности картофеля. За десять минут до окончания варки положить лавровый лист. Суп снять с огня, оставить на 10 – 15 минут для настаивания. При подаче лавровый лист вынуть, положить рубленую зелень. Подать к гороховому супу с ребрышками и грудинкой свежий черный хлеб.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6441,'Тщательно вымыть брокколи, стручковую фасоль, мелкую морковь, пучок петрушки. Капусту разобрать на соцветия. В кипящую воду положить фасоль и морковь, варить до готовности, в течение 10 минут. В другой кастрюле отварить брокколи, опускать в кипяток, через 7–10 минут вынуть. Вода должна быть подсоленной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6441,'Морковь выложить в тарелку, фасоль и капусту откинуть на дуршлаг и окатить ледяной водой. У фасоли отрезать «хвостики» и разрезать стручки на несколько частей. Нагреть в сковороде оливковое масло, выдавить в него чеснок, прогреть, убавить огонь. Выложить овощи, перемешать, жарить две-три минуты. Петрушку мелко нарезать. Переложить овощи в глубокую посуду, посолить по вкусу, добавить зелень петрушки, свежий лимонный сок. Перемешать и подать гарнир из брокколи и моркови к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6442,'Для теста перемешать кефир с сырыми куриными яйцами, солью, пищевой содой и мукой, предварительно просеянной. Тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6442,'Смазать противень растительным маслом, посыпать панировочными сухарями, выложить тесто, разровнять по всей поверхности. Соус кетчуп нанести в виде решетки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6442,'Нарезать шампиньоны соломкой, колбасу – соломкой или кубиками. Все ингредиенты выложить на тесто, посыпать пиццу тертым твердым сыром и запечь в духовке до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6443,'Говяжье мясо отварить до готовности в подсоленной воде. Остудить, бульон слить, но не выливать. Репчатый лук нарезать кольцами, обжарить в течение 7 – 10 минут до прозрачности. Всыпать немного муки, жарить до образования золотистой корочки в течение трех-пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6443,'Вымыть и очистить гранат. Перемешать с луком, влить столовую ложку уксуса, бульон, потушить 10 минут. Готовую говядину нарезать на небольшие кусочки. В форму выложить половину гранатового соуса, сверху – мясо, полить остатками смеси, выложить оставшуюся говядину. Блюдо посыпать панировочными сухарями, полить растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6443,'Форму накрыть пищевой фольгой, тушить блюдо в течение 20 минут при температуре 180 градусов. Фольгу снять, прогревать запеченную говядину с гранатовым соусом еще 15 минут до образования золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6444,'Свежий ананас очистить от сердцевины и верхней части, нарезать мякоть кубиками. Стебель сельдерея нарезать ломтиками, продольные волокна можно удалить, если они слишком жесткие. Измельчить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6444,'Филе лосося выложить на рабочую поверхность кожей вниз, острым ножом, аккуратно, срезать филе. Кожу залить холодной водой, небольшим количеством, чтобы она только покрыла продукт. Довести до кипения, пену удалить, огонь убавить, посолить, всыпать перец-горошек, лавровый лист, варить около 20 минут. Рыбное филе нарезать кубиками, такими же, как ананас.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6444,'Большую сковороду или вог с антипригарным покрытием раскалить с растительным маслом. Положить рыбу, жарить в течение двух минут, кусочки переворачивать, затем убрать со сковороды. Следующие продукты для обжаривания: ананас, сельдерей, чеснок. В смесь влить соевый соус, сок ананаса, полстакана или чуть больше рыбного бульона из кожи. Тушить пять-шесть минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6444,'Развести кукурузный крахмал небольшим количеством холодной воды, вылить в сковороду. Прогревать, пока соус не загустеет и не станет прозрачным. Рыбу вернуть на сковороду, перемешать и прогреть. Жареный лосось с ананасом и сельдереем подать в горячем виде с хорошо охлажденным розовым шампанским.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6445,'Измельчить с помощью блендера или мясорубки сырой очищенный картофель и репчатый лук. Белый хлеб или булочку замочить в молоке, дать набухнуть. Не отжимая, добавить в мясной фарш, можно подлить молоко. Вбить сырое яйцо, добавить картофельную массу, посолить и поперчить. Можно также добавить столовую ложку готовой горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11129,'Заранее достать ягоды из морозилки, дать оттаять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6445,'Фарш вымесить, влить ложку растительного масла. Оставить на десять минут. Разогреть на сковороде растительное масло, сформовать котлетки мокрыми руками. Выложить их на сковороду, огонь убавить, жарить мясные котлетки до готовности с двух сторон, после переворачивания накрыть блюдо крышкой и потушить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6446,'Порезать  багет на кусочки размером с желаемую высоту стаканчика, удалить из них мякоть. Нарезать небольшими кубиками брынзу (сырок), сладкий перец, колбасу, помидор. Яйцо взболтать и вылить к нарезке, перемешать, заполнить хлебные стаканчики из багета полученной начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6446,'Присыпать мелкой сырной стружкой, отправить на треть часа в духовку с температурой порядка 180 градусов. Подать закуску сразу к столу, либо обернуть в фольгу и разогреть непосредственно перед едой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6447,'Подготовить грибы, сварить, оставить несколько штук для украшения салата, остальные нарезать и обжарить с добавлением масла. Натереть сыр на терке со средними отверстиями, чеснок раздавить прессом, колбасу и огурец порезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6447,'Все ингредиенты объединить (немного сыра отсыпать), всыпать измельченную петрушку (чуть оставить для украшения), подсолить, приправить майонезом, аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6447,'Выложить массу на достаточно широкое и плоское блюдо в форме прямоугольника, используя столовую ложку наметить крышу «домика», обсыпать со всех сторон сыром. Завершить красивый салат на праздник выкладыванием из соломки «крыши», из нее же сделать «окно», прикрепить его на майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6447,'Присыпать свободное пространство вокруг измельченной петрушкой. На эту травку «высадить»  несколько небольших опят и грибочек из яйца и ломтика помидора.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6448,'Подготовить и почистить овощи, лук нашинковать, морковку порезать, сделать зажарку с небольшим количеством масла. Помидоры облить крутым кипятком, удалить шкурку, порезать дольками, добавить половину нарезки в зажарку, тушить минут 5 все вместе. Срезать у огурцов жесткую шкурку, если семена крупные – удалить, порезать брусочками, зелень порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6448,'В кипящую подсоленную воду положить дольки картофеля, проварить минут 5-6 при слабом кипении, засыпать огурцы, положить зажарку, остаток помидоров, тушенку, приправить специями. Для более острого вкуса в рассольник с тушенкой можно влить немного рассола от огурцов, проварить около 10 минут. Перед самым окончанием засыпать зелень, к столу рассольник подавать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6449,'Нарезать мясо на ломтики, присолить и обжарить на части сливочного масла, добавить порезанный кубиками лук, поперчить и жарить пока лук не зарумянится, залить бульоном, тушить пока мясо не будет мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6449,'Почистить овощи и нарезать тонкими кружочками, лук-сеянец очистить и оставить целиком, грибы нарезать пластинками, отварить все в воде с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6449,'Слить воду, переложить овощи и грибы к мясу, хорошо прогреть и выключить нагрев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6449,'В сотейнике распустить оставшееся масло, засыпать муку, обжарить ее, но не допускать пожелтения, залить бульоном, и дать закипеть, вылить соус на мясо, добавить сметану, лимонный сок, подсолить, поперчить, положить лавровый лист и прокипятить 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6449,'Телятина с овощным гарниром под сметанным соусом подается горячей, сверху посыпается рубленой петрушкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6450,'Поставить нагревать до кипения воду с куркумой. Разогреть в сковороде масло, положить гвоздику, корицу, кардамон и миндаль, обжаривать на среднем огне до изменения цвета у ореха, всыпать рис и еще пару минут прогреть помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6450,'Пересыпать содержимое сковороды в уже закипевшую воду, размешать, увеличить нагрев, дать сильно закипеть. Сделать слабый нагрев, закрыть крышкой, проварить минут 15 до впитывания всей воды, рис должен стать мягким. Минут за 7 до окончания варки засыпать горошек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6450,'Перемешать рис с зеленым горошком и миндалем, снять с плиты, дать дойти еще минут 5 под плотно закрытой крышкой, подать к столу в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6472,'Крупно нарезать очищенную морковь, красный лук – полукольцами. Маринад слить, в мясо добавить лук и морковь. Обжарить в течение трех-пяти минут на растительном, лучше оливковом, масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6451,'Обмыть апельсины кипятком, можно с помощью щетки, чтобы не осталось воскового слоя из консервантов. Разрезать каждый плод на 8 частей, удалить шкурку, нарезать ее на тонкие полоски, залить водой, дать постоять 3 дня, воду заменять ежедневно по 5 раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6451,'Воду слить, полоски промыть, срезать белую часть, завернуть каждую улиткой, нанизать бусами на нитку, залить холодной водой. Проварить их 3-4 раза по трети часа, каждый раз наливать свежую воду, и споласкивать «бусы».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6451,'Сварит сироп, погрузить «бусы», дать закипеть, проварить полчаса при слабом кипении, остудить. Все повторить еще раз, а в конце влить сок лимона. Когда варенье из апельсиновых корок остынет достать связки корочек, убрать нитки, разложить по баночкам, убрать на хранение в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6452,'Вымыть и почистить грибы, порезать на кусочки небольшого размера, обжарить в разогретом масле. Лук нашинковать как можно мельче, порезать на небольшие квадратные кусочки отварное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6452,'На большую тарелку выложить слой мяса, потом майонез, лук  и опять майонез, присолить, присыпать мелко потертым сыром, прикрыть грибным слоем, промазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6452,'Последним слоем в салате «Клубничка» будут мелкие кубики помидора, украсить верх блюда листиками, вырезанными из пластинок огурца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6453,'Распустить на водяной бане шоколад, можно воспользоваться микроволовкой, смазать жидким шоколадом силиконовые формочки, захватывая и стенки, и дно, отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6453,'Для приготовления начинки клубнику (размороженную) и сахар перемешать до состояния пюре. Растворить в паре столовых ложек горячей воды быстрорастворимый желатин, перемешать с ягодным пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6453,'Достать формочки, заполнить начинкой, убрать обратно в холодильник. Приготовить вторую порцию из 5 гр желатина и пары столовых ложек кипятка, смешать ее со взбитыми с сахаром сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6453,'Дополнить формочки взбитыми сливками (чуть сливок оставить), но не до самого верха, положить в каждую формочку сверху по готовому бисквитному печенью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6453,'Прогреть в микроволновке сливки, залить оставшееся пространство в формочках, поставить шоколадные корзиночки с клубникой и печеньем в холодильник. Нагреть еще раз оставшийся растопленный и затвердевший шоколад, смазать десерт, дать застыть, вынуть из формочек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6454,'Перемешать ликер, вино, с добавлением сахара и цедры, добавит сока лимона, кусочки груши и яблока, тщательно перемешать. Поставить сангрию с белым вином часа на 4 в холодильник. Перед подачей напиток процедить и долить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6455,'Обжарить в масле кусочки шампиньонов на среднем огне, влить через 5 минут пару-тройку столовых ложек соевого соуса, перемешать, немного обжарит все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6455,'Положить в сковороду к грибам кусочки помидоров, обжарить 3-4 минуты или чуть больше, грибы должны быть полностью готовы. Всыпать нашинкованную зелень и лук, подсолить, поперчить, приправить специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6455,'Взбить молоко вместе с яйцами, перцем и солью, поджарить омлет под крышкой на слабом огне минут 8-10, перевернуть, готовить еще около минуты, перевернуть обратно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6455,'Выложить на половинку омлета начинку, прикрыть сыром, завернуть омлет с грибами, помидорами и сыром пополам, слегка придавить, оставить под закрытой крышкой до полного расплавления сыра. Подавать омлет с овощами и свежей булочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6456,'Включить духовку, довести температуру до 180 градусов. Взбить яйца вместе с сахаром до состояния крепкой пены, перемешать с охлажденным растопленным маслом, всыпать ванильный сахар с мукой, солью и содой, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6456,'Заполнит подходящую форму тестом, поместить ее в прогретую духовку примерно на полчаса или чуть больше, дать остыть, разделить на кусочки размером 4х4 сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6456,'Для крема взбить сметану хорошего качества и сахар. Каждый кусочек коржа погружать в крем, а затем фигурно выложить так, чтобы получился торт «Снеговик», присыпать верх стружкой кокоса, украсить морковкой и изюмом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6481,'Сделать из картофельной массы шарики и обвалять их в перце с укропом, сверху новогодний салат-гарнир из овощей «Ёлочные шары» украсить петелькой из зеленого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6457,'Всыпать в портвейн специи, перемешать, вылить часть на дно формы, уложить курицу, присыпать солю, убрать на 17 часов в холодильник. Достать мясо, очень хорошо промыть, обтереть бумажным полотенцем, обсыпать паприкой и смесью из перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6457,'Обернуть мясо в марлю, положить на 3 суток в холодильник.  Все сыровяленые куриные грудки готовы, но можно еще на сутки подвялить в прохладном месте, например, в кладовой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6458,'Обжарить куриное филе, порезанное на кусочки до полуготовности, ананас очистить и порезать на кубики небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6458,'Помидоры измельчить блендером, сдобрить перцем и солью, объединить с курицей, протушить треть часа и добавить ананас, курица с ананасом будет готова через 5-7 минут. При желании томатный соус можно сгустить добавлением небольшого количества муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6459,'Грудинку нарезать по два куска на порцию, натереть солью и поперчить, быстро обжарить на масле и переложить в другую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6459,'Мелко нарезать чеснок, нашинковать лук, добавить муку, смесь подрумянить в мясном соке с маслом от жарки, залить теплой водой, кипятить 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6459,'Добавить в соус промытую фасоль, проварить 10 минут и переложить к мясу, разогреть духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6459,'Обжарить помидоры нарезанные ломтиками, протереть и смешать с мясом, смесь подсолить, добавить перец, лавровый лист, поставить тушиться в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6459,'Готовая телятина тушеная в духовке с помидорами и фасолью поливается вином и присыпается измельченной зеленью петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6460,'Обжарить в сотейнике со столовой ложкой сливочного и оливкового масла нашинкованную капусту до появления коричневатого цвета, присолить, размешать. Добавить натертые помидоры без кожуры, чайную ложку сахарного песка, тушить пока не испарится жидкость, в другой сковородке обжарить фарш. Отдельно обжарить до золотистости нашинкованную луковицу, смешать с фаршем, сдобрить перцем и солю, жарить до испарения всей жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6460,'Порезать все подготовленные овощи на кубики: морковку, сладкий перец, лук. Заполнить наполовину четырехлитровую кастрюлю водой, всыпать овощи, добавить фарш, проварить до размягчения и готовности овощей, приправить бульон перцем, подсолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6460,'Добавить в суп «Чехословацкий» обжаренную капусту, довести до кипения и 5 минут проварить. Заключительный штрих – всыпать в кастрюлю нашинкованную зелень, влить столовую ложку сока лимона, подержать на плите еще минуту, отключить нагрев, дать постоять под крышкой четверть часа. Разлить суп по тарелкам, отдельно подать нашинкованную зелень и сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6461,'Залить зачерствевший хлеб молоком, когда станет мягким, слить оставшееся молоко. Смешать все ингредиенты для фрикаделек, с небольшим нажимом скатать шарики. Разложить дедушкины фрикадельки на противне, застланном пергаментной бумагой, выпекать в прогретой до 200 градусов духовке четверть часа, затем переложить их в сотейник и тушить до готовности в соусе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6462,'Нагреть в сковородке масло, всыпать тмин, карри, перемешать, прогреть около минуты, положить кубики куриного филе, обжарить до полной готовности, переложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6462,'На масле, оставшемся после мяса, обжарить кусочки яблок и полукольца лука в течении 5 минут, положить мясо, добавить курагу, порезанную на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6462,'Добавить в курицу карри с яблоками зеленый горошек, залить бульоном, сдобрить солью и перцем, перемешать, потомить под крышкой около 5 минут. В качестве гарнира отлично подойдет отварной рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6463,'Нарезать кубиками сыр и перец, у ломтей черного хлеба срезать корки, порезать на кубики обжарить на оливковом масле вместе с чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6463,'Все ингредиенты салата с перцем и кукурузой выложить послойно, не перемешивая в салатник, добавить кукурузу, приправить оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6464,'Растолочь печенье до состояния крошки, перемешать с маслом до образования маслянистой крошки, уложить в форму, утрамбовать аккуратно ложкой, дать застыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6464,'Подготовить, согласно инструкции на упаковке раствор желатина, приготовить из персиков с добавлением сахара пюре, несколько штучек оставить для украшения торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6464,'Смешать лимонный сок и йогурт, добавить цедру и сахар. Соединить со смесью остатки желатина и взбитые хорошо сливки, уложить последним слоем торта, накрыть его оставшейся частью желе. Дать торту с персиками и йогуртом хорошо охладиться часа три в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6465,'Репчатый лук очистить, нарезать соломкой, залить кипящей водой на 5 – 7 минут. Воду слить, всыпать в лук пшеничную муку. Порубить зелень петрушки, укропа и сельдерея.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6465,'Натереть сырой очищенный картофель, морковь, на крупной терке. Все ингредиенты смешать, влить растительное масло, посолить, добавить специи, перемешать. Сформовать котлеты, жарить их, как оладьи, до золотистой корочки, с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6465,'Готовые обжаренные луковые котлеты переложить в другую сковороду и потушить на небольшом огне под крышкой до готовности, в течение 15 – 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6466,'Обжарить шампиньоны маленького размера. Сырую куриную грудку нарезать небольшими кусочками, клубни очищенного картофеля – кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6466,'Курицу и картофель выложить в смазанную форму по кругу, сверху – грибная обжарка, кольца репчатого лука. Соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6466,'Растворить в молоке порошок карри, залить блюдо, посыпать гратен из картофеля тертым твердым сыром. Поставить форму в духовку, печь при температуре 180 градусов в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6467,'Цыплят разделать на небольшие куски, каждый из них надрезать. Приготовить соус из сметаны, соуса кетчуп, аджики, добавить приправу хмели-сунели. Курицу положить в маринад на три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6467,'Нарезать полукольцами репчатый лук, ошпарить, воду слить. Добавить столовый уксус, черный перец. Снова залить водой и оставить на 15 минут, жидкость слить. Нарезать очищенный картофель, перемешать с небольшим количеством сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6467,'Расстелить на рабочей поверхности пищевую фольгу, смазать маслом, выложить картофель, лук, маринованную курицу, посыпать тертым сыром. Завернуть фольгу с боков, сделать импровизированные «горшочки». Печь цыплят с картофелем в духовке до готовности, температура: 200-220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6468,'Нарезать длинной соломкой перец, огурец разрезать вдоль тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6468,'Легкая сырная закуска с огурцом и перцем готовится из твердых сортов сыра, сначала его надо охладить, потом нарезать длинными прямоугольниками, отставить и дать время нагреться, тогда сыр не будет ломаться при скручивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6468,'Положить посередине на сырный прямоугольник пластинку огурца, на нее 3-4 кусочка сладкого перца, свернуть рулетом и связать перышком зеленого лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6468,'Для придания луку эластичности опустить перед использованием на 2-3 секунды в горячую воду, а затем сразу в холодную, вместо лука закуску можно скрепить шпажками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6469,'Отварить в подсоленной воде почти до готовности макаронные «ракушки» или «спиральки», они должны остаться чуть твердыми. Добавить содержимое банки консервированного тунца, массу предварительно размять вилкой. Порубить половину красной репчатой луковицы, лук-шалот тонко нарезать. Половину болгарского перца большого размера нарезать полосками, помидор – дольками. Все ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6469,'Массу заправить майонезом по вкусу. Добавить свежий укроп или чайную ложку сушеного, сушеный сельдерей, свежий тимьян, соль и молотый черный перец – также по вкусу. Влить сок лимона. Салат еще раз хорошо перемешать, поставить в холодильник на два часа для пропитывания. Перед подачей сытный салат с макаронами, овощами и тунцом украсить дольками крутого куриного яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6470,'Смешать сырые яйца, соль, сахарный песок, немного водки и просеянную пшеничную муку. Замесить крутое тесто, накрыть влажной тканью, оставить на полчаса для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6470,'Готовое тесто тонко раскатать, нарезать полосками, в середине каждой сделать надрез и вывернуть наружу. Жарить во фритюре из растительного масла, переворачивать. Готовый домашний хворост посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6471,'Натереть отваренную картошку, яйца, твердый сыр. Нарезать репчатый лук и обдать кипящей водой. Консервированную скумбрию в масле размять вместе с жидкостью, вынуть кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Или удалить излишки жидкости в режиме «Гречка» (около часа), добавив перед началом специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6472,'Развести сметану в холодной воде. Добавить сушеный укроп, перемешать. Соусом залить курицу с овощами, огонь убавить, накрыть крышкой, тушить куриные ножки с овощами при средней температуре в течение 10 – 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6473,'Нарезать сливочное масло средними кубиками. С помощью блендера смешать его с мукой, солью и сахарным песком. Смесь выложить на противень, разровнять и утрамбовать. Печь коржи при температуре 180 градусов в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6473,'Положить в сковороду немного сливочного масла, вылить сгущенное молоко, массу поварить до карамелизации, изменения цвета. Выложить на готовый холодный корж, разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6473,'Отдельно, на водяной бане, растопить шоколад, вылить на карамель. Домашнее печенье для миллионеров поставить в холод для застывания, при подаче нарезать квадратиками или ромбиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6474,'Просеять пшеничную муку, добавить сливочное масло, нарезанное кубиками, творог. Массу быстро порубить ножом в крошку. Влить сырой желток, замесить тесто, скатать его в «колобок», завернуть в пищевую пленку и поставить в холодильник на 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6474,'Готовое тесто раскатать на присыпанной мукой рабочей поверхности в прямоугольник, нарезать треугольниками. Присыпать изделия сахарным песком и молотой корицей, завернуть рогаликами. Выложить на противень, поставить в морозильную камеру на полчаса. Печь рогалики из творожного теста при температуре 200 градусов в течение 25 – 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6475,'Кедровую дощечку для гриля вымочить в воде в течение двух часов, она должна быть под водой полностью. Затем рабочую поверхность для запекания смазать чесноком и смазать оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6475,'Стейки лосося хорошо вымыть под проточной водой, смазать со всех сторон оливковым маслом. Гриль разогреть до 220 градусов. Поместить влажную доску с рыбой на гриль, закрыть крышку, проверять, древесина должна дымиться, но не гореть. Через 20 – 30 минут блюдо должно быть готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6475,'Для соуса сальса нарезать кубиками мякоть авокадо, помидоры, красный репчатый лук. Крупно порубить кинзу, перемешать все ингредиенты, добавить сок и цедру лайма, оливковое масло. Смесь поставить в холодильник на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6475,'Подать соус к копченому филе лосося, блюдо украсить тонко нарезанным лимоном. Его можно немного карамелизировать, обжарить в течение нескольких минут на сковороде. Посыпать свежей зеленью укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6476,'Нарезать кружками довольно крупные спелые помидоры, кожицу можно заранее снять, если ошпарить плоды кипятком. Размять брынзу с помощью вилки, если для приготовления начинки используется творог, то его нужно посолить по вкусу. Добавить любую порезанную зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6476,'В кипящей воде перемешать сахарный песок, соль, влить растительное масло, всыпать пшеничную муку. Замесить мягкое тесто, дать постоять для набухания клейковины в течение получаса. Тесто разделить пополам, половину массы раскатать в большую, тонкую, лепешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6476,'Выложить на тесто помидоры, на расстоянии друг от друга в три сантиметра. Сверху каждого кружка – сырная начинка, накрыть пирог второй лепешкой того же диаметра. Стаканом вырезать пирожки, ориентируясь на контуры кружков помидоров. Делать это нужно аккуратно, чтобы края пирожков хорошо склеились.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6476,'Жарить пирожки «Бомбочки» в большом количестве растительного масла, на раскаленной сковороде, с двух сторон, до готовности и румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6477,'Приготовить тесто. Дрожжи растворить в теплом молоке с сахарным песком. Поставить в тепло, должна появиться пенка, смесь начнет пузыриться. В оставшемся, тоже теплом, молоке растворить соль, влить сырые яйца и разболтать. Просеять пшеничную муку в отдельной емкости. Влить в нее дрожжи, молочно-желтковую смесь, растопленное сливочное масло. Замесить мягкое и липкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6477,'Вымешанную массу поместить в смазанную растительным маслом миску, поставить в тепло для подъема или на ночь в холодильник. Когда тесто увеличиться в размере в два-три раза – обмять смазанными маслом руками, снова дать подойти. Сразу же разделать на небольшие булочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6495,'Отварить и нарезать говядину, клубни картофеля. Слить жидкость от консервированной красной фасоли. Нарезать репчатый лук, маринованные огурцы, помидоры и маслины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6477,'Смазать форму для выпечки с высокими бортиками маслом, выложить булочки на расстоянии друг от друга в два сантиметра. Сбрызнуть водой, затянуть форму пленкой или фольгой, поставить заготовки в холодильник на 6 – 8 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6477,'Изделия достать, пленку убрать. Смазать дрожжевые булочки смесью молока с сырым желтком или разболтанным яйцом, посыпать кунжутным семенем. Поставить в холодную духовку, затем включить огонь, печь при 200 градусах в течение 35 минут. Должна образоваться золотистая, румяная корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6478,'Смешать топленое масло, сырое яйцо, сахарный песок и соль. Добавить протертый творог, массу хорошо размять. Посыпать небольшим количеством пшеничной муки. Рабочую поверхность также присыпать мукой, скатать «колбаски». Муки добавить столько, чтобы руки не клеились к тесту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6478,'Готовую «колбаску» нарезать наискосок, положить в кипящую воду, дождаться, когда ленивые вареники из творога всплывут. Достать шумовкой, подать со сметаной или медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Для первого теста растопить пачку маргарина, смешать со стаканом просеянной муки. Для второй массы стакан сметаны взбить с яйцами, добавить пшеничную муку, замесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Второе тесто разрезать на шесть частей, тонко раскатать, намазать первым тестом, коржи сложить один на другой, скрутить в виде рулета. Положить изделие в кулек и поставить в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Рулет разрезать поперек на 18-20 частей, толщиной по 1,5 см. Половину отправить охлаждаться, вторые тонко раскатать. Коржи должны быть ровными, можно их обрезать с помощью тарелки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Печь поочередно, на сухом противне, духовка должна быть сильно разогрета. Это делается быстро, достаточно прогревать коржи с каждой стороны по полторы-две минуты. Сложить их друг на друга. То же самое проделать с охлажденным тестом из холодильника. Обрезки испечь тоже.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Для приготовления крема пшеничную муку перемешать с сахарным песком, сухую смесь всыпать в кипящее молоко. Массу вымесить, дать загустеть, остудить. Взбить с мягким сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6479,'Промазать коржи кремом, верх и бока торта «Старый Наполеон» посыпать измельченными выпеченными обрезками, поставить в холод на 12 часов для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6480,'Сливочное масло или маргарин разрезать на несколько частей, дать согреться при комнатной температуре. В большой емкости взбить сырые куриные яйца с сахаром, можно делать это с помощью миксера. Добавить погашенную уксусом или лимонным соком соду, снова взбить, положить масло или маргарин, мелко порубить, снова взбить. Должна получиться однородная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6480,'Подсыпать пшеничную муку, когда миксер окажется бесполезным – продолжать добавлять муку и мешать ложкой, затем вымешать руками. Тесто должно быть мягким, но недолжно липнуть к рукам. Если липнет – подсыпать еще муку. Готовое тесто завернуть в пищевую пленку и поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6480,'Противень для выпекания выстлать бумагой или посыпать мукой. Достать охлажденное тесто, отрезать четверть, остальное вернуть в холодильник. Придать тесту форму «колбаски», пропустить через мясорубку. Как только из решетки покажутся «колбаски» длиной пять-семь сантиметров, их нужно приподнять и срезать ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6480,'Выкладывать «хризантемы» на противень поочередно. Закончится тесто – достать следующую «порцию» из холодильника и продолжить приготовление. Все операции нужно делать быстро, чтобы масса не успевала согреваться. Наполненный противень поставить в разогретую духовку, печь печенье «Хризантемы» при температуре 200 градусов, примерно, в течение 35–40 минут. Следить за готовностью выпечки. Готовое печенье остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6481,'Эта не дорогая и простая в исполнении нарядная закуска станет прекрасным украшением праздничного стола, подать можно как отдельное блюдо, а можно и как гарнир к мясу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6481,'Отварить яйца и картофель в мундире, очистить и натереть на крупной терке, все смешать, добавить майонез и подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6481,'Очистить разноцветные сладкие перцы и нарезать на мелкие кубики, добавить рубленый укроп и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6811,'Спассировать на масле мелко нашинкованный лук, добавить почки, прогреть и всыпать муку, налить вино и перемешать, слегка уварить смесь и влить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6482,'Сосиску надрезать на одинаковые кусочки, не прорезать до конца. Свернуть их в виде «колечек», скрепить зубочистками или деревянными шпажками. Выпустить в миску яйца, добавить майонез, соль, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6482,'Разогреть на сковороде сливочное или растительное масло, обжарить сосиски с одной стороны, перевернуть. Залить в середину «кольца» яично-майонезную смесь, прогреть до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6482,'При подаче выложить яйцо в сосиске на хорошо вымытые листья зеленого салата, посыпать мелко нарубленной петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6483,'Смешать неострую горчицу с зернами, добавить молотый перец чили, давленый чеснок, соль по вкусу. Мясо намазать полученной смесью, завернуть в пищевую пленку, оставить в холодильнике на четыре часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6483,'Бумагу для выпекания нарезать таким образом, чтобы в неё можно было положить мясо, а концы собрать в виде «узелка». Лист намочить, положить маринованное мясо, завязать бечевкой. То же самое проделать с другим куском. Оба завернуть в еще один слой бумаги, положить готовый «сверток» в огнеупорную форму, накрыть крышкой. Печь ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6484,'Смешать в емкости кокосовую стружку, овсяные хлопья, какао-порошок. В другой мисочке смешать мед и сырое яйцо. Вылить в сухую смесь, перемешать вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6484,'Из получившегося теста сформовать «шайбы» толщиной 6–8 мм. Выложить на пергамент. Печь в разогретой духовке при температуре 180 градусов в течение 15–20 минут. Бока должны потемнеть. Готовое кокосовое печенье перевернуть и подержать в духовке еще одну-две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6485,'Растопить сливочное масло, добавить протертый творог, пшеничную муку, массу перемешать, вымесить тесто. Разделить на небольшие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6485,'Каждый «колобок» раскатать в круг, разрезать на сегменты. В основание положить начинку, например, любимое варенье, скрутить, каждый творожный рогалик посыпать сахарным песком. Выложить изделия на противень, печь при температуре 200 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6486,'Любое печенье раскрошить, должны остаться и целые кусочки. Перемешать какао-порошок с сахаром. Растопить сливочное масло с молоком, всыпать сухие ингредиенты, держать на огне до растворения сахарного песка, до кипения не доводить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6486,'Всыпать печенье в несколько приемов, должна получиться густая липкая масса. Скатать три «колбаски», каждую завернуть в пищевую пленку. Положить чайную колбаску в холодильник на шесть часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6487,'Взбить в миске венчиком сырое куриное яйцо, сахарный песок, соль и немного сливок. Добавить в смесь растопленное сливочное масло, снова взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6487,'В массу ввести пшеничную муку, замесить мягкое и эластичное тесто, оно не должно липнуть к рукам. Выложить его в смазанную форму для выпечки, сформовать бортики. Поставить корж в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6487,'Для начинки перемешать с помощью блендера творог, сливки, куриные яйца, сахарный песок, ванилин из пакетика, картофельный крахмал, взбить массу до однородного состояния. Вымыть вишню, удалить косточки, ягоды откинуть на дуршлаг, лишняя жидкость должна стечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6487,'В охлажденную заготовку для коржа выложить творожную начинку, разровнять. Воткнуть и немного утопить в массе ягоды вишни. Печь пирог с творогом и вишней при 180 градусах в течение 45–55 минут. Готовый пирог остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6488,'Нарезать куриное филе на кубики среднего размера, обжарить на подсолнечном масле до золотистого цвета в течение 10–15 минут. При готовности мяса подсыпать муку, перемешать и жарить еще две-три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6488,'Влить только что вскипевшую воду. Перемешать, мука должна хорошо размешаться. Влить сметану, снова перемешать. Добавить дижонскую горчицу с зернышками. Накрыть блюдо крышкой, тушить куриное филе со сметанно-горчичным соусом до готовности. Если соус получается густоватым, можно добавить еще немного сливок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6489,'Отварить почти до готовности спагетти или любые макароны. Обжарить на сковороде мелко нарубленную луковицу, на любом растительном масле, но лучше – на оливковом. Добавить любой мясной фарш, обжарить все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6495,'Выложить ингредиенты слоями в следующем порядке: мясо, лук, фасоль, огурцы, картофель, помидоры. Все слои промазывать майонезом. Сверху – маслины. Верх салата «Коварство и любовь» оформить в виде сердца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6489,'В обжарку добавить плавленый сыр, перемешать, сыр должен расплавиться. Затем положить пропущенный через пресс чеснок, томатную пасту, прогреть, влить небольшое количество воды. Соус посолить и поперчить по вкусу, прокипятить в течение пяти минут, добавить рубленую зелень петрушки, кинзы. Подать спагетти в соусе «Болоньезе».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6490,'Разрезать кочан, вырезать кочерыжку, разобрать на листья, промыть, срезать утолщения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6490,'Свернуть листья в рулет и мелко нашинковать, посолить и тщательно размять руками, выделившийся сок слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6490,'Переложить капусту в салатник, заправить уксусом с маслом и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6490,'Подавать салат из краснокочанной капусты в уксусе по-румынски лучше через час, когда он настоится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6491,'Перекрутить в фарш куриное филе. Нарезать кружочками консервированные оливки без косточек, сладкий болгарский перец – небольшими полосками. Все ингредиенты перемешать, всыпать рубленую зелень петрушки, по вкусу посолить и поперчить. Перемешать. Натереть сыр на средней терке, перемешать с сырыми яйцами. Противень застелить бумагой, смазать ее оливковым маслом. Выложить сырную массу, разровнять. Печь в течение пяти минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6491,'На одну половину сырного квадрата выложить фарш, накрыть второй половиной. Сворачивать вместе с бумагой, на которой сыр запекался, ее края подогнуть со всех сторон, чтобы не вытек сок. Печь при той же температуре в течение получаса. Закусочный рулет из курицы в сыре достать из духового шкафа, немного остудить, нарезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6492,'Для блюда понадобится любой фарш: куриный или из индейки, свинина, смешанная с говядиной в равных пропорциях. Прокрученный через мясорубку репчатый лук смешать с мясом, добавить рис, отваренный до полуготовности, соль – по вкусу. Массу вымесить руками. Можно добавить сырое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6492,'Сформовать тефтели, обвалять их в пшеничной муке. Выложить на разогретую сковороду с растительным маслом, обжарить с одной стороны в течение трех-пяти минут. Затем перевернуть, обжарить еще столько же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6492,'Залить блюдо кипящей водой, уровень–до половины тефтелей. Добавить немного соли, томатную пасту, заранее разведенную в воде, лавровый лист. Накрыть посуду крышкой и тушить 10–15 минут на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6492,'Развести в половине стакана воды ложку сметаны, перемешать, добавить муку. Хорошо вымесить, в смеси не должно быть комочков. Вылить в тефтели. Закрыть крышкой, встряхнуть, придерживая крышку. Тушить мясные тефтели в подливке еще 15–20 минут на тихом огне, жидкость должна кипеть. Можно в середине приготовления перемешать, добавить кипяток, если подливка получилась слишком густая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6493,'На готовый лаваш намазать творожный сыр хохланд с зеленью. Нарезать кубиками соленую семгу и плотный, мясистый, помидор. Семенные камеры можно удалить. Выложить на сыр то и другое, поперчить по вкусу. Затем слой хорошо вымытого и обсушенного зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6493,'Скрутить лаваш в рулет, завернуть в пищевую пленку. Положить в холодильник, подать к столу, нарезав на кусочки. Для приготовления рулета из лаваша можно использовать любой салат или микс из нескольких, например, с морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6494,'Сырые куриные желтки растереть с сахарным песком и ванилином из пакетика. Добавить мягкое сливочное масло комнатной температуры, хорошо перемешать. Всыпать муку, небольшими порциями, каждый раз массу вымешивать ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6494,'Половину приготовленного теста положить в другую емкость, скатать в «колобок». Во вторую добавить какао-порошок, вымесить и также скатать в комок. Оба теста положить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6494,'Раскатать «светлое» тесто в тонкий пласт, толщиной в полсантиметра. Вырезать кружки с помощью формочки. На каждом кружке сделать вмятину, не прорезая, по центру – два или четыре сквозных отверстия, сымитировать пуговицу. Точно также поступить с «темным» тестом. Обрезки слепить в шар, снова раскатать, повторить все операции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6494,'Аккуратно, с помощью ножа или лопатки, переложить «пуговицы» на застеленный бумагой противень. Печь песочное печенье «Пуговицы» в разогретой до 180 градусов духовке в течение 20 минут. Остудить и подать к столу к чаю или кофе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6496,'Взбить с помощью венчика сырые куриные яйца и молоко, соль и перец – по вкусу. Отставить смесь в сторону. Коктейльные креветки обдать кипятком, очистить от хвостиков. Воду отцедить. Нарезать белую часть лука-порея или обычного, зеленого лука. Мелко порубить зелень петрушки и зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6496,'На среднем огне, на сковороде, растопить сливочное масло пополам с оливковым. Всыпать белый лук, обжарить в течение полминуты. Добавить креветки, жарить 30 секунд. Огонь увеличить, вылить яичную массу. В процессе приготовления постоянно перемешивать омлет лопаткой. Готовый омлет с креветками снять с огня, добавить зелень, перемешать и выложить на тарелки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6497,'Разогреть в сковороде растительное масло, обжарить на нем мясной фарш. Соль и перец молотый – по вкусу, можно добавить любимые специи. Клубни картофеля очистить и нарезать кубиками, добавить в мясо, жарить все вместе в течение пяти-семи минут, до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6497,'В стакане теплой воды развести томатную пасту, добавить очищенный и натертый чеснок, соль. Массу перелить к картофелю, тушить под крышкой в течение 25–30 минут на тихом огне. При готовности жареный картофель с фаршем посыпать рубленой зеленью, украсить помидорами черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Пшеничную муку и разрыхлитель просеять, смешать с помощью блендера с кубиками сливочного масла. Должна получиться мучная крошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Взбить с сахаром куриное яйцо, влить в крошку, замесить тесто, оно не должно прилипать к рукам. При необходимости подсыпать еще немного муки. Готовое тесто завернуть в пищевую пленку и поставить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Для начинки смешать творог, сметану, манную крупу и желтки. Добавить ваниль. Массу перетереть в блендере до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Для суфле яичные белки взбить в плотную пену со щепоткой соли. Постепенно всыпать сахарную пудру, продолжать взбивать. Холодное тесто выложить в застеленную бумагой или смазанную маслом форму, слепить невысокие бортики. Выложить творожную начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Блюдо печь при температуре 180 градусов в течение 20–30 минут. Форму вынуть из духовки, выложить поверх пирога суфле, разровнять и снова выпечь в течение 10–15 минут при температуре 140 градусов. Поверхность выпечки должна стать золотистой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6498,'Выключить духовку, открыть дверку, оставить торт-пирог «Слезы ангела» для остывания. Вынуть через 40 минут, остудить полностью и вынести на холод. Примерно через час-полтора на поверхности появятся «слезы».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6499,'Залить молоком нарезанный на ломтики пшеничный хлеб или батон, включить духовку для разогрева.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6499,'Смазать маслом форму, обсыпать сухарями или мукой, лишнее стряхнуть, выложить хлеб на дно, сверху присыпать тертой брынзой, опять положить слой хлеба и брынзу и т.д., последним слоем должен быть хлеб.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6499,'Взбить молоко с яйцом и солью, добавить для цвета щепотку куркумы, перемешать. Смазать поверхность шарлотки маслом, вылить молочную смесь, присыпать натертым сыром, поставить в духовку и запечь до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6499,'Выпекается шарлотка из хлеба и брынзы по-румынски при средней температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6500,'Филе отбить. Противень смазать растительным маслом, выложить курицу. Соль и перец – по вкусу, сухие специи – по желанию, можно добавить сушеный базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6500,'Помидоры тонко нарезать поперек, выложить на куриное мясо, посыпать свежей рубленой зеленью и тертым твердым сыром. Печь куриное филе с помидорами при температуре 180 – 200 градусов в течение 15 – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6501,'Творог взбить с помощью миксера до однородности, в массе не должно быть комочков. Растопить в микроволновой печи сливочное масло. Влить в творог вместе с двумя куриными яйцами, дополнительным желтком, всыпать сахарный песок. Массу взбить миксером, всыпать пшеничную муку. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6501,'На посыпанной мукой рабочей поверхности раскатать полученное тесто в виде колбаски. Обвалять ее немного в муке, нарезать ломтиками по полсантиметра. Вскипятить воду, посолить. Опускать вареники порциями и варить до всплывания на поверхность. Достать изделия шумовкой, полить сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6811,'Очистить от кожицы и семян помидоры, мелко порезать, выложить к почкам, тушить до сгущения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6501,'Приготовить соус. Для этого вымыть свежие ягоды клубники, положить в блендер вместе с сахаром, перемолоть в пюре. Полить массой горячие ленивые вареники по-итальянски и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6502,'Приготовить песочное тесто по классическому рецепту из муки, масла, сахарного песка и щепотки соли. Положить в холодильник. Для начинки хорошо вымыть лимон и прокрутить его через мясорубку. Лучше взять плод с толстой корочкой. Смешать массу с сахарным песком, оставить для растворения. Попробовать на вкус, при необходимости норму сахара можно увеличить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6502,'Холодное тесто разделить на две неравные части. Большую часть раскатать и выложить в форму для выпечки, сформовать бортики. На тесто выложить начинку из лимона, накрыть меньшей частью теста, также раскатанного в лепешку. Края соединить с помощью вилки. Печь песочный пирог с лимонной начинкой при температуре 200 градусов в течение 20 минут, затем духовку выключить и оставить в ней пирог еще на 10–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6503,'Отварить до готовности морковь, остудить, очистить и натереть. Мелко нарезать куриное филе и обжарить его на сковороде в течение 10 минут, посолить по вкусу. Отварить и натереть куриные яйца, нарезать маринованные шампиньоны и репчатый лук, его можно залить на 10 минут кипятком, чтобы удалить лишнюю горечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6503,'Кусочки филе выложить на блюдо, смазать майонезом. Следующий слой – морковь, майонез, грибы, майонез, лук, яйца, майонез. Отцедить от жидкости консервированную кукурузу, обсыпать ею салат со всех сторон. Выложить вокруг ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6504,'Натереть на терке кабачок, отжать лишнюю жидкость. Добавить сырые яйца, всыпать зелень, муку, разрыхлитель. Массу посолить и поперчить по вкусу, хорошо перемешать. Выложить «тесто» в смазанную маслом форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6504,'Тонко нарезать спелые помидоры, выложить на пирог. Смазать чуть взбитым желтком. Печь при температуре 180 градусов до готовности. Посыпать быструю пиццу из кабачка тертым твердым сыром и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6505,'Каждую куриную грудку разрезать по диагонали на две равные половины. Острым ножом разрезать карман с одной стороны каждого кусочка, делать это аккуратно, насквозь прорезать не надо. Каждый кармашек наполнить сыром. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6505,'Застелить противень фольгой. В небольшие емкости насыпать пшеничную муку, во вторую – разбить яйцо, в третью – сухари для панировки. В яйца добавить немного воды и взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6505,'Каждый кусочек курицы с начинкой обмакивать в муку, затем – в яйцо и сухари. Обжаривать на раскаленной сковороде с растительным маслом в течение двух-трех минут с каждой стороны. Должна образоваться хрустящая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6505,'Обжаренную курицу переложить на противень и печь кармашки из куриного филе с сыром в течение 25 минут при температуре 180 градусов. Время приготовления зависит от величины карманов. Подать блюдо в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6506,'Филе разрезать пополам. В три небольшие тарелочки положить взбитое яйцо, во вторую – растопленное сливочное масло с рубленым чесноком, в третью – тертый сыр пармезан, смешанный с панировочными сухарями, сушеным орегано, соль – по вкусу. Форму застелить бумагой для выпечки, смазать растопленным сливочным маслом с чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6506,'Куриное мясо обмакнуть сначала в яйцо, затем в смесь сухарей и сыра, выложить в форму. Филе смазать оставшимся чесночным маслом, печь в течение получаса при температуре 200 градусов. Во время приготовления блюдо один раз достать из духовки и перевернуть куриное филе в сырной панировке на другую сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6507,'Для приготовления начинки мелко нарубить репчатый лук, свежие шампиньоны нарезать пластинками. На среднем огне разогреть растительное масло, обжарить лук в течение четырех минут, помешивать. Добавить грибы и еще немного обжарить. Всыпать заранее отваренный рис, посолить и поперчить, перемешать. Отставить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6507,'С куриной тушки срезать мясо, выложить в чашу блендера. Вбить сырое яйцо, добавить зелень, раскрошенный белый хлеб для тостов, без корочки. Массу порубить, добавить перец и соль. Вместо блендера можно использовать мясорубку: прокрутить мясо, добавить размоченный в молоке хлеб, остальные ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Специи лучше помещать в марлевом мешочке и после окончания варки удалить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6507,'Сформовать плоские зразы на ладони, положить начинку с грибами, залепить края. Обвалять изделия в панировочных сухарях. Разогреть на сковороде растительное масло, жарить зразы из курицы с грибами и рисом по шесть-семь минут с каждой стороны. После переворачивания потушить под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6508,'Перемешать кефир в миске или в комбайне с сахарным песком. Добавить подсолнечное масло, пищевую соду, заранее просеянную пшеничную муку. Тесто вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6508,'Смазать форму для выпекания растительным маслом, вылить тесто, печь при температуре 210–220 градусов в течение 20 минут. Готовность выпечки проверить с помощью спички или зубочистки. Готовый нищий кекс разрезать острым ножом на коржи по горизонтали, промазать любым кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6509,'Поставить варить яйца, помыть огурцы и если кожура очень жесткая, то почистить, нарезать брусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6509,'Почистить яйца, желтки мелко накрошить (часть оставить для украшения), белки порубить, нарезать как можно мельче зелень петрушки, укропа и перья лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6509,'Смешать огурцы с яйцами и зеленью, перемешать, подсолить, заправить майонезом. сметаной или их смесью, добавить сок лимона, перемешать еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6509,'Переложить салат из огурцов и яиц к празднику в глубокий салатник, присыпать сверху желтком, из зелени выложить кольцо, а верхушку салата украсить цветком из тонких ломтиков огурца, свернув их розочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6510,'Куриное филе немного отбить и мелко нарезать. Добавить к нему мелко нарезанный репчатый лук, соль и молотый перец, вбить сырое яйцо. Массу хорошо перемешать, сформовать небольшие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6510,'Форму для запекания смазать сливками, выложить шарики, их можно обвалять в муке. Печь при температуре 180 градусов в течение 10–15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6510,'Для приготовления заливки натереть твердый сыр, добавить давленый чеснок и сливки. Готовым соусом полить каждый куриный шарик, поставить в духовку еще на 15–20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6511,'Репчатый лук нарезать соломкой, стебель сельдерея – тонкими поперечными ломтиками. Натереть очищенную морковь, измельчить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6511,'На сковороду выложить сливочное масло, влить растительное, лучше оливковое. На этой смеси до прозрачного состояния обжарить лук и чеснок, добавить сельдерей и морковь, прогревать на среднем огне в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6511,'Выложить говяжий фарш на горячую сковороду с маслом, жарить, помешивая лопаткой. Другой вариант: сначала обжарить тонко нарезанный бекон, а на вытопленном свином жире – фарш. Когда мясо обжарится – влить белое сухое вино, и прогреть до испарения жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6511,'Влить в фарш мясной бульон, положить немного томатного пюре. Вместо пюре можно добавить кусочки очищенных от кожи помидоров. Добавить все овощи, любимые специи, обязательно – сушеный базилик и молотый черный перец, тушить под крышкой на тихом огне в течение часа. Блюдо периодически помешивать, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6511,'Отварить спагетти так, как указано на упаковке, паста должна остаться немного твердоватой. В соус добавить сливки, перемешать, довести до кипения. Подать спагетти «Болоньезе»  в горячем виде, соус выложить сверху.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6512,'Отварить морковь, свеклу и клубни картофеля в «мундире». Все продукты охладить до комнатной температуры, очистить, натереть отдельно на крупной терке. Соленую сельдь также очистить и нарезать кусочками, косточки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6512,'На плоское блюдо большого диаметра выложить тертый вареный картофель, полить майонезом. Сверху – сельдь, нарезанный зеленый лук, снова полить майонезом. Следующий слой–тертая вареная морковь, майонез, свекла, майонез. Поставить салат «Сельдь под шубой» на несколько часов в холодильник для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6513,'Плод лимона хорошо вымыть, натереть цедру, выдавить сок. В толстостенной кастрюле растопить сливочное масло, добавить сахарный песок и кукурузный крахмал, соль, цедру и сок лимона, массу довести до кипения. Через минуту огонь выключить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6513,'В миске взбить сырые желтки, влить в них часть лимонного крема, затем вылить получившуюся смесь обратно в оставшийся крем, огонь убавить, варить смесь до загустения. Подать лимонный крем в креманках, украсить листочками свежей мяты и дольками свежего лимона или лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6514,'Готовое слоеное бездрожжевое тесто разморозить, разрезать пополам. Раскатать каждую часть в прямоугольник, смазать половиной нормы творожной начинки, до краев не доходить. Свернуть рулетами, заворачивать с узкого края, защипнуть, перевернуть швом вниз и нарезать кусочками толщиной в три-четыре сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6514,'Оба рулета выложить на застеленный пергаментом противень, смазать немного взбитым сырым яйцом, посыпать кунжутным семенем. Печь слойки с творожной начинкой при температуре 200 градусов до готовности, должна получиться золотистая корочка. Готовую выпечку остудить, посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6515,'Филе лосося нарезать небольшими кусочками. Для приготовления маринада смешать соевый соус, жидкий мед, готовую столовую горчицу. Рыбу переложить в маринад, поставить в холодильник на два часа или на ночь. Маринованное филе лосося посыпать кунжутным семенем и обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6516,'Для приготовления маринада в небольшой емкости разогреть оливковое масло на среднем огне. Добавить целые, но очищенные от кожицы, зубчики чеснока, сушеный или свежий розмарин, жгучий красный перец, нарезанный хлопьями. Пассеровать смесь на тихом огне в течение 8 – 10 минут. Чеснок не должен подгореть, иначе соус будет заметно горчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6516,'Снять смесь с огня, остудить. Влить лимонный сок, всыпать крупную соль и молотый черный перец. Отсоединить от куриной тушки кожицу, мясо смазать маринадом, и под кожей, и сверху. Нарезать несколько зубчиков очищенного чеснока пополам вдоль, положить их под кожицу грудки и бедрышек. Можно так же поступить с веточками розмарина, кружочками лимона. Выжатыми половинками лимона нафаршировать брюшко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6516,'Ножки курицы связать крепкой ниткой, крылышки заправить за шею. Положить подготовленную тушку грудкой вниз в форму для запекания, накрыть пищевой пленкой. Другой вариант: положить продукт в большой плотный полиэтиленовый пакет. Поставить тушку в холодильник на 2 – 4 часа или на ночь. За час до приготовления птицу вынуть из холодильника, дать согреться и запечь курицу в чесночном маринаде грудкой вниз в форме, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6517,'Желатин замочить в небольшом количестве холодного молока, оставить на час или два для набухания, затем прогреть до однородного состояния, но не кипятить. В горячую массу всыпать сахарный песок и ванилин из пакетика, размешивать до растворения твердых ингредиентов и процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6517,'Творог протереть через сито, если он зернистый, добавить сметану и взбить смесь с помощью миксера. Добавить желатин, снова перемешать, разделить массу на две части: в одну влить растопленный на водяной бане темный шоколад, другую оставить, как есть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6517,'Белую массу вылить в холодную форму, поставить в холодильник на полчаса, шоколадную остудить при комнатной температуре. На загустевшую массу в форме выложить очищенные бананы, нарезанные половинками, залить темной смесью. Десерт из творога с бананом убрать на ночь в холодильник, до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6518,'Картофель в «мундире», морковь, куриные яйца, отварить до готовности. Картофель очистить и натереть, так же поступить с морковью. Консервированную печень трески отцедить от масла, размять вилкой. Мелко нарезать зеленый лук, чернослив – соломкой. Белок отделить от желтка, измельчить по отдельности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6518,'Выложить на блюдо слоями: картофель, майонез, печень трески, лук, майонез, морковь, майонез, чернослив, майонез. Верх салата посыпать белками, смазать майонезом, посыпать желтком. Украсить салат «Печень трески под шубой» зеленью петрушки, поставить в холодильник на два-три часа для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Отварить филе курицы и нарезать кубиками, приготовить из масла, меда, сока лимона, горчицы и молотой паприки соус, все ингредиенты взбить, масло добавлять порциями, присолить, поперчить, взбивать примерно 7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Залить в кастрюлю холодную воду, дать закипеть, посолить и положить фасоль, после закипания проварить 3 минуты, если для приготовления используются стручки свежей фасоли, то время варки надо увеличить до 7 минут, содержимое кастрюли вылить в дуршлаг, облить ледяной водой и дать ей стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Нашинковать лук, залить кипятком на пару секунд и обсушить, в половину соуса высыпать лук, добавить курятину, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6519,'Выложить первым слоем в салатник капусту, на нее – смесь соуса, лука, мяса и цитрусовых, полить сверху куриный салат со стручковой фасолью и апельсином оставшейся половиной соуса, равномерно распределить по поверхности тертую морковь, украсить елочкой из стручков фасоли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6520,'Сложить чистую марлю в несколько раз, поместить ее в дуршлаг, а дуршлаг поставить на кастрюлю чуть большего диаметра. Выложить горкой сметану, от ее жирности зависит жирность конечного продукта, чем она больше – тем меньше будет сыворотки. Продукт должен быть холодным. Марлю завязать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6520,'Сверху, на дуршлаг, выложить груз весом от двух до четырех килограммов, это может быть гиря. Поставить массу в холод на три дня. За это время вся сыворотка стечет в емкость. Хранить сыр Маскарпоне можно в холодильнике в течение нескольких дней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6521,'Смешать просеянную пшеничную муку, пищевую соду, соль, разрыхлитель. Отдельно размять очищенные спелые бананы в пюре, добавить сахарный песок, вбить яйцо, влить растительное масло, лучше оливковое, и экстракт ванилина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6521,'Всыпать в массу мучную смесь, перемешать до однородного состояния. Добавить рубленые грецкие орехи, снова перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6521,'Готовое тесто разлить в формочки на три четверти объема, выложить по чайной ложке Нутеллы, осторожно перемешать по кругу зубочисткой, должны получиться «спиральки». Печь кексы с бананом в течение 20–25 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6522,'Печенье поломать небольшими кусочками. Сгущенное вареное молоко взбить с помощью миксера с мягким сливочным маслом, сметаной. Смесь добавить в печенье, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6522,'Выложить приготовленную массу горкой на тарелку, верх посыпать тертым темным или молочным шоколадом и маком. Поместить торт «Муравейник» из печенья в холодильник на полчаса, затем нарезать и подать к чаю или кофе, какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6523,'Любые свежие грибы нарезать кубиками и обжарить на растительном масле. Порубить и обжарить лук. Нарезать кубиками ветчину или вареное мясо, копченую курицу. Выложить салат на блюдо слоями: ветчина, грибы, натертые отваренные куриные яйца, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6523,'Все слои промазать майонезом, будет лучше, если это будет соус домашнего приготовления. Салат «Красная шапочка» украсить мелкими кусочками помидоров, уложить их плотно, по всей поверхности салата. Если плоды не очень плотные, семенные камеры можно вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6524,'Нарезать кусочками ветчину и шампиньоны, можно соломкой или кубиками. Грибы взять свежие, предварительно отваренные в подсоленной воде, или консервированные, соленые, в таком случае блюдо будет острее. Натереть на крупной терке твердый сыр. Все ингредиенты соединить. Сцедить жидкость от консервированной кукурузы, добавить зерна в основную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6524,'Приправить салат молотым черным перцем, пропущенным через пресс чесноком, перемешать, заправить майонезом по вкусу. На блюдо поставить кольцо от разъемной формы, в центр – пустую банку или стакан. Между ними выложить салат, плотно утрамбовать, должно получиться «кольцо». Банку и бортики от формы осторожно убрать, салат поправить, он должен держать форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6524,'Украсить салат «Рождественский» с ветчиной листочками вымытой и просушенной петрушки или зеленью укропа, можно рукколой. Очистить морковь, нарезать тонкими лентами с помощью овощечистки. Оформить венок. Можно положить сладкий желтый перец, нарезанный кружками, половинки или кольца маслин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6524,'Бант также сделать из моркови, украсить горошком из капелек майонеза. На морковных лентах можно что-то написать майонезом с помощью кондитерского шприца, например, краткие пожелания с праздником.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6525,'Сковороду почти до краев наполнить водой. Влить белый уксус, довести жидкость до кипения, а затем уменьшить огонь. Осторожно разбить яйца, они не должны растечься. Снять кастрюлю с огня, накрыть крышкой на пять минут. Осторожно, шумовкой, достать яйца. Обжарить белые тосты, выложить на каждый по два ломтика тонко нарезанного бекона, положить по яйцу-пашот.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6543,'Смешать картофель и фасоль, добавить порезанный кубиками лук, заправить сметаной, добавить по вкусу уксус, горчицу, сахар, посолить, поперчить, для пикантности можно добавить пару щепоток сухой мяты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6525,'Для приготовления соуса: взбить сырые яичные желтки с соком лимона, добавить растопленное сливочное масло, немного взбить, влить горячую воду. Соль и перец – по вкусу. Полить смесью яйца «Бенедикт» на бутербродах и украсить петрушкой или зеленым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6526,'Для приготовления бисквитного теста взбить сырые куриные желтки с сахарным песком, двумя третями от общего количества. Белки взбить отдельно, со щепоткой соли, в плотную пену, всыпать оставшийся сахар и еще немного взбить. Обе массы перемешать. В белковую смесь всыпать просеянную пшеничную муку вместе с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6526,'Форму для выпечки застелить бумагой, вылить тесто, печь при температуре 180 градусов в течение получаса. Готовность коржа проверить с помощью спички или зубочистки. Бисквит вынуть из формы, дать постоять четыре часа или ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6526,'Для мусса всыпать в толстостенную кастрюлю сахарный песок, растопит до карамельного цвета, не перемешивать, только встряхивать. Влить нежирные горячие сливки, перемешать. Снять массу с огня, добавить сливочное масло. Размешать до полного растворения, добавить белый шоколад. Через полминуты перемешать и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6526,'Карамельную массу смешать с кокосовой стружкой. Отдельно взбить жирные сливки и вмешать в мусс. Готовый бисквит разрезать по горизонтали на коржи, промазать кремом. Оставить кокосово-карамельный торт в холодильнике на два часа, затем обмазать края остатками крема, украсить стружкой. Снова поставить в холодильник на два часа или больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6527,'Корень сельдерея, морковь, репчатый лук очистить и нарезать соломкой. В перечисленной последовательности продукты обжарить на растительном масле в сотейнике. Соль и перец – по вкусу. Добавить нарезанную соломкой сырую курицу, обжарить до изменения цвета, она должна побелеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6527,'Гречневую крупу тщательно перебрать, промыть в холодной воде. Добавить в обжарку, всыпать сушеные ягоды барбариса, очищенные зубчики чеснока целиком. Смесь разровнять, добавить индийскую приправу панч пурен или любую другую, влить два стакана кипящей воды, посолить. Блюдо довести до кипения, прогревать под крышкой на тихом огне до испарения влаги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6527,'Когда влага полностью испарится, а гречка будет готова – перемешать содержимое сотейника, собрать ингредиенты к центру в виде горки, накрыть крышкой, прогревать гречневый плов с курицей и сельдереем на плите в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6528,'Растопить в форме немного сливочного масла. Тонкий армянский лаваш сбрызнуть водой для размягчения, постелить в форму, края должны свисать за ее пределы. Поверхность лепешки смазать майонезом или сметаной, можно использовать смесь этих двух ингредиентов, выложить слой тонко нарезанной ветчины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6528,'Помидоры нарезать колечками, положить сверху, посыпать тертым сыром и рубленой зеленью, эти два ингредиента можно заранее перемешать. Разбить сырые куриные яйца, они должны сохранить форму, желтки – остаться целыми. Начинку завернуть свисающими краями и обжарить яичницу с ветчиной в лаваше с двух сторон на среднем огне до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6529,'Черствый белый хлеб замочить в небольшом количестве молока. Прокрутить через мясорубку куриное мясо, свинину с прослойками, репчатый лук, хлеб. По вкусу добавить соль и молотый черный перец. Влить еще немного молока, фарш вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6529,'Для приготовления начинки натереть на крупной терке любой твердый сыр, смешать с сырыми яйцами, сметаной, зеленью укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6529,'Мокрыми руками сформовать из фарша небольшой «колобок», немного расплющить, сделать углубление, выложить в него сырную массу.  Котлеты «Гнезда» печь на противне при температуре 200 градусов в течение 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6530,'Отваренные куриные грудки нарезать соломкой, отварить куриные яйца до готовности, разделить на белки и желтки, то и другое натереть. Измельчить репчатый лук, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6530,'Ингредиенты выложить на блюдо для салата слоями: обжаренный лук, излишки масла слить, курица, белки, банан, нарезанный кружками и сбрызнутый лимонным соком, сыр, желтки, тертые грецкие орехи. Все слои салата «Нежность» промазывать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6554,'Теперь следует аккуратно завернуть края лаваша, чтобы начинка была надежно завернута внутри. Обжарить ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6531,'Домашний творог растереть с ванильным сахаром. Отдельно смешать сырые куриные яйца с сахарным песком, добавить соль. Пищевую соду погасить укусом, добавить в яйца. Добавлять порциями в яичную массу творог и пшеничную просеянную муку. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6531,'Неширокий казан с высокими бортиками влить растительное масло, нагреть на тихом огне. Мокрыми руками слепить небольшие «колобки» и жарить на раскаленном масле, поворачивая. Шарики не должны пригореть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6531,'Равномерно обжаренные пончики из домашнего творога выложить на бумажную салфетку для впитывания лишнего жира, переложить на тарелку, при подаче посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6532,'Большие, неповрежденные, клубни картофеля в «мундире» хорошо вымыть и обсушить. Каждый клубень завернуть в фольгу. Количество – по числу едоков. Выложить клубни на решетку в духовом шкафу, печь при температуре 200 градусов в течение полутора часов. Готовность проверить ножом, клубни должны стать мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6532,'Приготовить один из следующих наполнителей или сразу несколько: тертый твердый сыр с мелко нарезанными крабовыми палочками и майонезом, мелко нарезанная ветчина с тертым сыром, рубленой зеленью и майонезом, рыбные консервы в томате в размятом виде, с овощами. Еще несколько вариантов: консервированные баклажаны с измельченным чесноком, мелко нарезанное соленое сало с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6532,'Готовый, испеченный картофель достать из духовки, фольгу развернуть, оставить ее в виде «тарелочки». Клубень разрезать накрест или пополам, но не до конца, внутреннюю часть мякоти немного размять. Добавить кусочек сливочного масла, давленый чеснок, соль и зелень петрушки и укропа, перемешать картофельную массу с этими ингредиентами. Для постного варианта использовать растительное масло. Сверху положить один из наполнителей-салатов, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6533,'Отварить яйца вкрутую и очистить, мелко нарубить и смешать с распущенным маслом, лимонным соком и солью, мелко нашинковать зелень петрушки, всыпать в польский сливочный соус из яиц к рыбе, хорошо перемешать, при подаче полить соусом вареную рыбу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6534,'Прозрачную рисовую лапшу залить холодной водой, оставить на 10 минут. Жидкость слить, залить блюдо кипятком на пять минут, воду слить, промыть лапшу под струей воды в дуршлаге.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6534,'Морковь сладкий болгарский перец разного цвета нарезать соломкой, спассеровать на растительном масле до мягкости. Перец не должен потерять цвет. Мелко покрошить чеснок, положить в обжарку в конце приготовления. Овощи остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6534,'Обжарку смешать с рисовой лапшой и свежим нарезанным огурцом. Влить уксус, посолить салат «Фунчоза с овощами» по вкусу, добавить соевый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6535,'Нарезать в равных пропорциях соломкой свежие грибы, репчатый лук, отваренное куриное филе, морковь по-корейски, свежие огурцы. Последний ингредиент можно натереть на крупной терке. Грибы обжарить с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6535,'Дно салатницы смазать майонезом, выложить продукты в такой последовательности: грибы с луком, куриная грудка, морковь, огурец. Слои ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6536,'Отделить желтки от белков. Первые взбить с молоком и сахарным песком до образования однородной массы. Белки взбить в плотную пену, добавить в желтковую смесь, осторожно перемешать. Всыпать пшеничную муку, картофельный крахмал, разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6536,'Массу вымешать, добавить растительное масло. Печь блинчики-панкейки на сковороде с антипригарным покрытием, она должна быть хорошо разогрета. Прогревать по одной минуте с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6537,'Крупную рыбу вымыть, удалить боковые плавники. Тонким, острым ножом сделать надрезы на спинке с обеих сторон от хребта. Осторожно, руками и ножом, отделить от хребта реберные кости. Острыми ножницами перерезать хребет у головы, вынуть. Удалить ребра, внутренности, черную пленку на брюшке. Срезать жабры на голове. Рыбу снова вымыть, обсушить, натереть солью и перцем, отставить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6542,'Пока выпекается грудка, следует приготовить дип. Измельчить промытую зелень, выдавить чеснок, свежий огурец очистить от кожуры и семян. Соединить несладкий йогурт, огурец, зелень, чеснок, посолить и поперчить по вкусу. Этот вкусный соус идеально подходит к хрустящим куриным кусочкам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6537,'Для приготовления начинки до полуготовности отварить рис. Можно использовать смесь белого и дикого риса. Массу охладить, смешать с куркумой и измельченной черемшой. Влить лимонный и апельсиновый сок, оливковое масло. Начинку хорошо перемешать. Полученный рыбный «карман» наполнить рисовой начинкой, посыпать сушеными хлебными крошками, сбрызнуть оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6537,'Выложить фаршированную рыбу на застеленный бумагой для выпечки или фольгой противень. Фольгу или бумагу нужно хорошо смазать растительным маслом. Печь фаршированную скумбрию с рисом в течение 20 минут при температуре 180 градусов, до зарумянивания. Подать рыбу можно как в теплом, так и в холодном виде. Украсить тонко нарезанным лимоном, можно и саму тушку дополнительно сбрызнуть лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6538,'Смешать сахарный песок, молоко и сливочное масло, массу перемешать, варить в течение 15 минут. Всыпать просеянную пшеничную муку, какао-порошок, варить еще 10 минут. Разлить в маленькие, смазанные маслом, формочки в виде «цветочков» или «сердечек», дать застыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6539,'Отварить куриные яйца, натереть твердый сыр. В сыр добавить давленый чеснок, майонез, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6539,'Вымыть разноцветные болгарские перцы, срезать верхушку, вынуть семена. Сырной массой с майонезом выложить дно и бока перцев изнутри, укладывать массу плотно, прижимая к стенкам. Поместить по целому очищенному яйцу, свободное пространство наполнить остатками сырной массы, ее же уложить сверху, начинку-яйцо не должно быть видно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6539,'Поставить перцы в емкость, накрыть крышкой, отправить в холодильник на два–четыре часа или на ночь. При готовности нарезать фаршированные перцы кольцами острым ножом. Украсить целыми веточками укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6540,'Мандарины хорошо вымыть, нарезать кружками. Сварить сироп из сахара и воды, положить в него цитрусовые, проварить в течение пяти минут.  С трех мандаринов снять цедру, из мякоти приготовить пюре. Еще из одного плода выжать сок, его нужно добавить в сироп после варки первых мандаринов. Жидкость немного покипятить, чтобы смесь загустела и выпарилась.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6540,'Взбить сырые желтки с половиной стакана сахара, добавить в смесь цедру, мандариновое пюре и манку. Перемешать. Белки взбить отдельно, осторожно вмешать их в мандариновое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6540,'В форму для выпекания выложить кружки мандаринов, залить тестом, печь в течение 35–40 минут при температуре 180 градусов. Если выпечка начнет слишком быстро темнеть – накрыть фольгой. При готовности полить выпечку пирог мандариновым сиропом, вернуть в выключенную духовку для пропитывания и полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6541,'Немного подогреть молоко, добавить сухие дрожжи и сахарный песок, массу перемешать и оставить на 10 – 15 минут. Отдельно взбить сырые яйца с помощью вилки, добавить мягкое сливочное масло, дрожжи, какао-порошок, порциями всыпать просеянную муку. Тесто вымесить, сформовать шар, оставить на 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6541,'Подошедшее тесто разделить пополам, из каждой половины раскатать прямоугольник толщиной три миллиметра. Размягчить сливочное масло, перемешать с сахаром. Смесью смазать тесто, посыпать рублеными грецкими орехами. Свернуть в рулет, разрезать на кусочки по три-четыре сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6541,'Выложить кусочки рулета на противень, через полчаса смазать их маслом, печь шоколадное печенье при температуре 180 градусов в течение 25–30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6542,'Куриную грудку необходимо хорошо промыть и порезать на небольшие полоски. Сложить кусочки в миску, посолить, присыпать приправами (перец черный и красный, орегано), добавить давленый чеснок, соевый соус и кефир. В этом маринаде курочка должна промариноваться 1 час в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6542,'Куриные кусочки необходимо присыпать мукой, затем каждую полоску вмокнуть во взбитое яйцо. Потом следует секретный кляр, который придаст курочке своеобразную хрустящую корочку. Измельчить чипсы и соединить с натертым сыром. В этой массе обвалять курицу и выложить на противень для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6542,'Запекать куриную грудку в пальтишке 20 минут при температуре 200 градусов. При наличии в духовке функции гриль выпекать 15 минут. Готовое блюдо имеет аппетитную золотистую корочку и изумительный аромат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11173,'Очистить перцы от перегородок, положить начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6543,'Выложить салат картофельный с фасолью и сметаной в салатник, посыпать измельченным зеленым луком, украсить листиками салата, салат получится более привлекательного вида, если взять белую и красную фасоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6544,'Свежие томаты обдать кипятком и снять жесткую кожуру. Затем томаты порезать мелким кубиком, половину высыпать в блендер. Туда же добавить чеснок, перец чили и взбить до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6544,'Нагреть сковороду с ложкой растительного масла. Вылить полученный томатный сок и добавить оставшиеся рубленые томаты, консервированную фасоль. Томить 5 минут на медленном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6544,'Зеленый авокадо необходимо очистить от кожуры и нарезать мякоть мелким кубиком. Кинзу вымыть и мелко порубить. Лепешки тортильяс обжарить на растительном масле с двух сторон по 30-40 секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6544,'На разогретую сковороду, смазанную растительным маслом, разбить 2 яйца, не повредив желток. Жарить под крышкой 2 минуты, чтобы яйцо «схватилось». Затем белок полить ароматным томатным соусом, а сверху все яйца засыпать тертым сыром. Посолить и поперчить по вкусу. Накрыть крышкой и через 10 секунд снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6544,'На широкую тарелку положить поджаренную лепешку, полить томатным соусом и выложить жареные яйца. Посыпать яйца по-мексикански кубиками авокадо и свежей кинзой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6545,'Мясо необходимо порезать на куски и отбить. Чтобы не порвать волокна при отбивании, следует на кухонный молоток надеть кулек и отбивать не сильно, так чтобы мясо не рвалось, а слегка мялось. Отбивные посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6545,'Противень для запекания смазать сливочным маслом и вылить сухое вино. Затем выложить слой лука, порезанного кольцами. На лук выложить свиные отбивные. Если кусочки получились толстыми, тогда мясо выкладывать немного на расстоянии, чтобы не накладывались один на один.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6545,'Мясо посыпать приправами и снова выложить слой лука. На лук выложить слой жареных грибов и посыпать все давленым чесноком. Все следует залить сметанным соусом из сметаны и майонеза в равных количествах и посыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6545,'Запекать в духовке при температуре 190 градусов до образования золотистой корочки. Отбитая свинина очень быстро готовится, но если куски толстые или мясо жесткое, тогда время готовности стоит увеличить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6545,'Свиные отбивные с сыром и грибами, подавать в противне, в котором запекались. Так будет сохранена форма блюда и не нарушится баланс вкуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6546,'Для пирога необходимо приготовить песочное тесто. Для этого порубить сливочное масло (маргарин) с мукой, добавить лимонную цедру и взбитые яйца с сахаром. Вымесить мягкое тесто, завернуть пленкой и поставить в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6546,'Яблоки очистить от семян и кожуры, порезать кубиком. На сковороде томить яблоки на сливочном масле с сахаром, корицей и лимонным соком. Когда яблоки станут мягкими отставить сковороду, яблоки остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6546,'Тесто разделить на 3 части. Одну часть раскатать очень тонко и выложить в форму для выпекания, поколоть вилкой. Выложить яблоки на тесто.Теперь необходимо сделать заливку для пирога. Взбить молоко, яйца, сахар, корицу и смесь для пудинга. Поставить заливку на огонь и довести до кипения. Этой заливкой полить яблоки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6546,'2 части теста необходимо раскатать тонко и нарезать длинными полосками, чтобы хватило на всю длину пирога. Украсить пирог полосками из теста. Выпекать яблочный пирог с изюмом по-немецки 1 час при температуре 200 градусов. Когда остынет, притрусить сахарной пудрой или смазать взбитыми сливками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6547,'Творог протереть через сито, яйца взбить с сахаром до получения пышной пены. Соединить яичную смесь, растопленное масло, разрыхлитель. Взбивая, добавляем творог, вымесить . Затем всыпать муку и вымесить мягкое тесто, по консистенции гуще, чем густая сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6547,'Формочки для маффинов заполнить тестом наполовину. Выпекать 15 минут до румяной корочки. Готовые остывшие пирожные украсить сахарной пудрой, взбитыми сливками или фруктовым джемом. Сверху творожные маффины можно украсить ягодкой малины или клубнички.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Сварить мякоть курицы, нарезать брусочками, сыр порезать такими же длинными кусочками, включить духовку для разогрева.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6548,'Сделать посередине одной оливки небольшой надрез вдоль, удалив тонкую дольку из оливки. Этот надрез заполнить плавленым сыром или немного подсоленным творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6548,'Вареную морковь очистить и порезать на колечки. В каждом колечке вырезать маленький треугольник. В это колечко вдеть зубочистку, сверху нанизать оливку с сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6548,'Взять отдельно оливку и вырезать в середине небольшую дырочку, чтобы вставить морковный треугольник–носик. Эту голову пингвинчика надеть на зубочистку с творожной оливкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6549,'Тонкий лаваш расстелить на столе и намазать смесью из сметаны и томатного соуса. Сметану можно заменить майонезом, вкус не меняется.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6549,'На соус выкладывать порезанные ингредиенты: обжаренный фарш, зелень, тертый сыр, сладкий перец. От количества свежей зелени и болгарского перца будет зависеть аромат блюда, а мясная начинка сделает блюдо сытным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6549,'Свернуть лаваш рулетом и смазать верх сметаной или майонезом. Противень смазать растительным маслом и положить рулет, запекать 20 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6549,'Лаваш с начинкой вкусный как холодный, так и горячий. Горячий лаваш можно полить сметанным соусом, смешанным с давленым чесноком и рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6550,'Корейскую морковь необходимо немного измельчить, порезав длинную соломку на несколько частей. Сыр натереть на крупной терке или порезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6550,'Крабовые палочки и вареные яйца порезать тонкой соломкой или небольшим кубиком. Зелень измельчить, чеснок пропустить через пресс. Соединить все ингредиенты и заправить салат майонезом. Посолить, поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6551,'Заранее подготовьте бумажные полоски с написанными строчками предсказаний. Для приготовления печенья необходимо приготовить жидкое тесто. Взбить яичные белки венчиком, взбивая добавить сахар, ванилин, масло, соль, крахмал и воду. Затем всыпать муку и сделать наливное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6551,'Противень застелить пергаментной бумагой и налить ложкой тесто, сформировав лепешки диаметром 8-10 см. Выпекать лепешки  10-15 минут при температуре 180 градусов. Золотистые лепешки достать из духовки и приступить к оформлению предсказаний.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6551,'На каждую лепешку положить листик с предсказанием, сложить лепешку пополам и перегнуть еще пополам. Чтобы зафиксировать форму треугольника, не ломая печенье, вложите его в формы для кексов, чтобы печенье с предсказаниями остыло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6552,'Слоеное тесто необходимо раскатать очень тонко, присыпая качалку мукой. Порезать мелким кубиком колбасу, сыр натереть на терке. Смешать сыр с колбасой и выложить эту начинку на одну половину теста. Второй половиной накрыть, края хорошо защипнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6552,'Стаканом вырезать кружочки из теста с начинкой. Выложить кружочки на противень для выпекания, сверху смазать взбитым яйцом и щедро присыпать кунжутом. Выпекать в духовке 20 минут при температуре 180 градусов. Золотистые булочки с колбасой и сыром подавать горячими или охлажденными.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6553,'Сварить из костей и копченой грудинки бульон, грудинку достать и порезать кубиками, добавить и проварить овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6553,'Капусту, положить в кипяток, закрыть крышкой, дать закипеть, после этого проварить до мягкости без крышки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6553,'Порезать лук кубиками и обжарить на сале, добавить муку, перемешать и обжарить все вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6553,'Процедить бульон, переложить в него капусту, нагреть до кипения, развести небольшим количеством бульона зажарку и вылить в кастрюлю, добавить грудинку, влить капустный рассол, подсолить, поперчить, бросить лавровый лист, варить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6553,'Подавать щи польские из квашеной капусты с вареным картофелем и сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6554,'Противень смазать сливочным маслом и разложить лаваш, чтобы края его свисали по бокам формы. Немного смочить лаваш водой. Лаваш необходимо смазать сметаной или майонезом, это на любителя. Выложить слой порезанной кубиками ветчины или колбасы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6554,'На колбасу выложить кольца помидор, затем присыпать все тертым сыром., посыпать рубленой зеленью. На начинку разбить 3 яйца, чтобы не повредился желток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Достать из блюда, закрыть плотно фольгой, готовить минут двадцать.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Почистить лук, промыть его под проточной водой. Порезать его на разделочной доске на полукольца, переложить в свободную емкость. Почистить ножом морковь, промыть под проточной водой. Натереть ее на среднюю терку, переложить в свободную миску. Налить в сковороду растительное масло, поставить на средний огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Когда масло разогреется, с помощью ложки положить порезанный лук, постоянно помешивать, тушить минут семь, лук должен приобрести золотистый оттенок. Затем положить в сковороду измельченную морковь, помешивать ложкой, тушить, пока морковь не станет мягкой. Выключить огонь, переложить начинку в свободную миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Выложить куриную печень на доску, при помощи ножа почистить ее от пленки, жира и так далее. Порезать на средние кусочки. Промыть под проточной водой, переложить в сито, чтобы стекла жидкость. Положить кусочки печени в блендер, налить молоко, измельчить до однородности на средней скорости. Перелить смесь в емкость, хорошо перемешать венчиком, посыпать солью, добавить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Снова перемешать, медленно насыпать муку, размешивая непрерывно жидкость венчиком, чтобы не было комков. Тесто должно получиться, как на оладьи. Если оно сильно густое, то можно налить чуть-чуть молока. Взять сковороду диаметром 10-11 сантиметров. Поставить на большой огонь, разогреть без масла. Когда сковорода сильно раскалится, сделать огонь меньше, на дно налить чуть-чуть растительного масла. Делать это следует только вначале, остальные будут готовиться на масле, оставленном от печеночного теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Набрать половником жидкость из емкости, вылить на сковороду. Круговыми движениями распределить печеночное тесто тоненьким слоем по поверхности сковороды. Обжаривать блин минут семь с одной стороны, с помощью деревянной лопатки быстро перевернуть на другую сторону, обжарить. Таким образом приготовить все лепешки, пока не закончится печеночное тесто. Выложить блины друг на друга на плоской тарелочке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Вылить в тарелку майонез. Пропустить чеснок через чеснокодавку. Добавить в майонез. Посыпать солью, размешать смесь до однородности. Помыть укроп и петрушку под проточной водой. Положить на бумажное полотенце, чтобы впиталась лишняя вода. При помощи ножа измельчить зелень, высыпать в майонезно-чесночную заправку. Когда печеночные блинчики остынут, начинать приготовление торта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'Положить на широкую плоскую тарелочку одну лепешку. В центр положить заправку из майонеза, чеснока и зелени, распределить равномерно по поверхности. Сверху положить луково-морковную начинку, распределить по поверхности заправки. Сверху положить вторую лепешку, ее намазать таким же образом и так со всеми лепешками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6555,'В результате получится праздничный торт из куриной печени с овощами. По бокам намазать чесночно-майонезной заправкой. Чтобы тортик настоялся, нужно накрыть его пищевой фольгой и отправить часа на два в холодильник. Достать тортик из холодильника, снять фольгу, порезать на порционные куски и подавать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6556,'Почистить банан и порезать на небольшие кусочки. Переложить в блендер творог, яйца, сахар, ванилин и банан, размешать до однородности. Получится жидковатая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6556,'Насыпать столовую ложку муки, размешать до однородности. Так досыпать муку, пока консистенция не будет средней вязкости. Не сыпать слишком много муки, так как сырники будут, как резиновые.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6556,'Налить на сковороду растительное масло, разогреть. Налить тесто с помощью столовой ложки на сковороду. Жарить несколько минут с одной стороны, перевернуть и жарить с другой стороны. Накрыть сковороду крышкой, чтобы сырники из творога с бананом пропарились.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6557,'Разогреть духовку. Взбить яйца и столовую ложку воды. Во второй посуде соединить сухарики и тертый пармезан. Баклажан порезать на диски и окунать каждый сначала в яйца, потом обвалять в сухариках. Выложить на противень, поставить минут на тридцать в духовку. За это время один раз необходимо перевернуть противень другой стороной для равномерного запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6564,'Соединить майонез и сметану в пропорции 1 к 1, посыпать перцем, солью, положить прессованный чеснок. Крупно потереть сыр. Мелко порезать болгарский перец, помидоры на тоненькие кружки. Измельчить кинзу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6557,'Приготовить начинку: соединить базилик и другие шесть ингредиентов, кроме яиц. Положить на дно емкости для запекания половину стакана начинки. Потом слой баклажанов. На них положить 3/4 томатного соуса, половину стакана сырно-творожной начинки, 1/3 моцареллы, 1/4 фонтины. Положить так же еще один слой, закончить необходимо томат-пастой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6557,'Накрыть емкость фольгой, поставить минут на 35 в духовку. Убрать фольгу, посыпать оставшейся частью моцареллы и фонтины. Готовить запеченные баклажаны «Пармеджано» еще минут десять – сыр должен расплавится, а соус закипеть. Остудить и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6558,'Порезать авокадо и помидоры на небольшие кубики. Перемешать с уксусом, оливковым маслом, солью, орегано, перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6558,'Положить смесь без сока на чиабатту, обжаренную предварительно на углях. Порезать на небольшие кубики. Подавать брускетты с помидорами и авокадо, украсив базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6559,'Соединить в кастрюле вино, чеснок, сок лимона, перец горошком, воду и лавровый лист. Довести до кипения, уменьшить огонь. Положить осьминога, готовить минут 45. Убрать кастрюльку с огня, оставить в жидкости (желательно готовить за несколько дней до приготовления салата). Достать осьминога, положить в емкость, закрыть, отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6559,'В оставленной жидкости отваривать минуты три почищенные креветки и кальмара, так же остудить. Таким же образом поставить в холодильник. В этой же жидкости несколько минут отваривать лук, морковь, сельдерей. Слить маринад, овощи остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6559,'С осьминога снять тоненькую кожицу и присоски. Минут на шестьдесят замариновать в оливковом масле, петрушке и чесноке. Нагреть гриль. Обжаривать осьминога минут десять. Порезать. Соединить с другими ингредиентами и соком апельсина. Оставить часов на двенадцать мариноваться. Добавить в салат из маринованных морепродуктов перец и оливковое масло. Подавать с осьминогом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6560,'Потереть мелко крабовые палочки, белки и желтки. Формочку застелить полиэтиленом. Порезать рыбу полосочками, обложить ими стенки и дно формочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6560,'Положить слой риса, яиц, крабовых палочек, промазывать кремом. Поставить блюдо на ночь в холодильник. Достать, накрыть тарелкой, перевернуть рыбный салат-торт. Украсить салатик красной икрой и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6561,'Взять несколько тарелок. На одной смешать соль и муку. В другую налить молоко, вбить яйца, положить масло, размешать. Вылить яично-молочную смесь в тарелку с сухими продуктами, вымешивать чуть-чуть липкое, эластичное тесто. Накрыть его мокрым полотенцем, отставить минут на пятнадцать, чтобы тесто настоялось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6561,'Тоненько раскатать, противень намазать маслом, положить на него тесто, вытянуть его по размеру противня, оно должно быть чуть-чуть прозрачным. Выложить любую начинку, готовить пиццу «Домашняя» минут десять, соблюдая в духовке температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6562,'Выложить кусок любого мяса на противень и поместить в нагретую духовку, запекать до полной готовности, время от времени поливать выделяющимся соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6562,'Довести до кипения литр воды, добавить лавровый лист, сахар, перец, соль, кипятить еще 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6562,'Положить готовое мясо в маринад (жидкость должна полностью покрывать кусок), положить сверху груз, оставить мариноваться на 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6562,'Достать мясо, обсушить, нарезать на ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6562,'Далее мясо достать из маринада, обсушить и нарезать, запеченное мясо маринованное для нарезки прекрасный вариант мясной нарезки для новогоднего стола, хранить в холодильнике, завернув в пергамент.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6563,'Взять крабовые палочки, корейскую морковь, яйца, майонез и оливки без косточек. Порезать крабовые палочки на шайбочки, оливки на кружочки. Яйца порезать на кубики. Корейскую морковь можно не резать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6563,'Положить ингредиенты в емкость, заправить майонезом. Размешать, посыпать солью при желании. Разложить салат с морковью и оливками в креманки, украсить крабовыми палочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6564,'Порезать баклажаны вдоль на дольки в толщину 0,7 сантиметров, посыпать солью, отставить минут на пятнадцать, чтобы выделился сок. Обжарить лук, отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6572,'Залить вымытый изюм на 15 минут теплой водой, достать и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6564,'Баклажаны промокнуть салфеткой, чтобы убрать сок, намазать соусом, положить чуть-чуть жареного лука, болгарский перец, опять соус, посыпать зеленью. Положить порезанные помидоры, чуть-чуть посыпать солью, еще немного соуса, посыпать сыром. Готовить запеченные баклажаны минут двадцать в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6565,'Насыпать в кефир соду, размешать. Насыпать сахар, вбить яйца, размешать. Насыпать какао, муку, разрыхлитель, размешать. Получится тесто, как густая сметанка. Готовить тоненькие коржи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6565,'Сделать заварной крем: смешать, молоко с мукой, яйцом и сахаром. Размешать, поставить на огонь. Мешая, довести до кипения. Снять с огня, когда крем станет густым. Положить сливочное масло, взбить. Можно насыпать ванильный сахар. Остудить. Намазать коржики кремом. Посыпать торт «Ноченька» какао. На ночь отправить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6566,'Измельчить крабовые палочки. Почистить чеснок и мелко потереть.Крупно потереть сыр и положить в емкость, добавить чесночок. Размешать. Вымыть укроп, обсушить и измельчить. Порезать лаваш на четыре одинаковых прямоугольника. На один кусочек намазать плавленый сыр, посыпать его укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6566,'Сверху положить крабовые палочки. Накрыть все вторым куском лаваша. На второй лаваш положить начинку таким же образом, накрыть третьим пластом, снова положить начинку, накрыть четвертым пластом лаваша, прижать. Порезать брикет на средние куски. Смешать муку с яйцами и солью, чуть-чуть взбить. Обмакивать гренки из тонкого лаваша в яичную смесь и обжаривать с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6567,'Включить духовку. Порезать шампиньоны на пластинки, обжарить на оливковом масле минут пять. Положить прессованный чесночок и измельченный укроп. Томить секунд шестьдесят.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6567,'Слить жидкость с томатов, порезать на кусочки. Порезать хлеб поперек и вдоль, не дорезая до середины. Должна получиться решетка из квадратов 2 на 2 сантиметра. Побрызгать хлеб оливковым маслом, начинить томатами, грибами. Посыпать закусочный хлеб потертым сыром, отправить в духовку минут на пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6568,'Порезать маргарин на небольшие порции, потереть. Перемешать с мукой, чтобы получилась крошка. Соединить со сметаной, замесить тесто. Отправить в морозилку минут на тридцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6568,'Чуть-чуть раскатать, посыпать сахаром, раскатать, вкатывая сахар, чтобы толщина была 0,5 сантиметров. Порезать на ромбики. Положить на противень, готовить простое ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6569,'Налить в емкость молоко и масло, взбить блендером. Взбивать четыре минуты. В середине взбивания насыпать соль и добавить горчицу. Попробовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6569,'Когда масса будет белой и густой, как сметана, налить лимонный сок, взбивать не прекращать. Смесь быстро станет густой и примет вид майонеза. Наливать в майонез без яиц приблизительно две ложки сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6570,'Сделать шарики: соединить творог, сахар. Желтки, крахмал, кокос. Размешать до однородности. Сформировать шарики. Сделать тесто: отделить желтки от белков. Взбить желтки, сахар и ванилин до гладкой светлой смеси. Положить растопленный шоколад. Насыпать разрыхлитель, крахмал, муку, какао, соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6570,'Взбить белки до пиков. Осторожно ввести в массу и перемешать с помощью лопатки действиями сверху вниз. Застелить формочку специальной бумагой, положить шарики, вылить сверху шоколадное тесто. Готовить 35 минут, соблюдая температуру 180 градусов. Полить шоколадный пирог с шариками из творога шоколадной глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6571,'Порезать лаваш на большие треугольники. Измельчить лук и обжарить на масле, положить к нему фарш, размешать. Добавить к фаршу крупно потертый сырой картофель. Тушить до готовности, посыпать перцем, солью, по желанию положить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6571,'Взять треугольник лаваша, на край положить начинку, по бокам согнуть края, свернуть трубочкой. Смазать чуть-чуть противень растительным маслом, положить трубочки, чередуя с сырной начинкой и мясной. Класть трубочки плотно друг к другу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6571,'Соединить ингредиенты для заливки, размешать, залить бёреки, оставить на время, чтобы впиталась жидкость–приблизительно шестьдесят минут. Поставить ленивый бёрек в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6572,'Отварить свеклу, очистить, отложить часть для оформления, остальную крупно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11180,'Муку можно добавить, если есть необходимость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6572,'Смешать свеклу с творожной массой, переложить на плоское блюдо, украсить сладкий свекольный салат с изюмом, творогом и орехами тонкими ломтиками свеклы, выложив из них розочку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6573,'Отварить куриную грудку в соленой воде, охладить, порезать на кубики. Почистить и порезать на кубики болгарский перец. Соединить мясо и перец, заправить майонезом. На плоскую тарелку положить смесь в виде головы лошадки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6573,'Отварить яйца и разделить желтки и белки. Мелко натереть желтки, соединить с майонезом, покрыть смесью салатик, чтобы слой перца с курицей был закрыт. Посыпать мелко потертыми белками. Обжарить грибы, выложить из них ноздри, глаза и гриву лошади. Оставить салат «Белая лошадь» на несколько часов для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6574,'Сделать омлет: положить в емкость яйца, потертый сыр, майонез, манную крупу, перемешать до однородности. Отставить, чтобы манка набухла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6574,'Сделать начинку: взять лук и фарш. Луковицу измельчить и обжарить на растительном масле. Измельчить в блендере, соединить с фаршем, перцем и солью, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6574,'Постелить на противень бумагу, смазать маслом. Вылить тесто, готовить до небольшого зарумянивания при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6574,'Бумагу убрать, свернуть рулетик. Завернуть в фольгу. Готовить минут сорок, соблюдая температуру 180 градусов. Охладить в фольге, чтобы сок не вытек, а впитался в рулетик. Порезать рулет из омлета с куриным фаршем, подавать в горячем или холодном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6575,'Положить в чистую банку специи. Утрамбовать не очень плотно огурцы. Залить чистой водой. Закрыть крышкой и взболтать, чтобы соль хорошо растворилась. Отправить в холодильник. Приблизительно через три недели холодные огурчики можно употреблять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6576,'Смешать молоко и дрожжи. Насыпать по желанию сахар. Размешивать, пока не растворится сахар, и дрожжи не смешаются с молоком. Поставить емкость с дрожжами в тепло минут на пятнадцать. Должна появиться шапочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6576,'Просеять в посуду муку. Согреть предварительно масло и растереть его с мукой в крошку. Вбить яйца. Вылить молоко с дрожжами, размешать, чтобы получилось плотное тесто. Отправить часа на три в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6576,'Брать понемногу теста, разделывать пирожки, чтобы тесто не растаяло, держать его в холоде. На противне пирожки не расстаивать, сразу ставить в духовку. Если тесто для удачной выпечки нужно быстро, то яйца не добавлять и в холодильник ставить минут на тридцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6577,'Взбить яйца, соль, сахар и разрыхлитель. Налить молоко, свекольный сок или пюре, размешать при помощи венчика. Насыпать муку, размешать. Налить растительное масло, замесить тесто. Испечь блинчики на сухой разогретой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6577,'Измельчить в блендере очищенный апельсин, положить яблоко, почищенное и потертое. Насыпать сахар. Поставить на огонь, тушить минут шесть. Добавить сливочное масло и разломанный шоколад. Непрерывно помешивая, нагревать, пока не растает шоколад. Остудить крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6577,'Положить блины стопочкой, каждый промазывать кремом. Поставить тортик из блинов с шоколадным кремом часа на три в холодильник. Украсить можно потертым черным или молочным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6578,'Помыть мясо курицы, промокнуть бумажным полотенцем, порезать на кубики приблизительно по 2 на 2 на 2 сантиметра, посыпать перцем, солью, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6578,'Тоненько порезать на полупрозрачные кружки почищенный картофель. Можно использовать терку или комбайн, чтобы заготовки были одинаковой толщины. Крупно потереть твердый сыр, порезать лук полукольцами или перьями, оторвать от стебля листья тимьяна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6578,'Смазать огнеупорную посуду растительным маслом, положить мясо, распределить равномерно. Положить сверху луковую нарезку. Выложить плотными рядами порезанный картофель, посыпать перцем, солью, приправами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6578,'Залить молочными сливками практически до верха. Чтобы снизить калорийность, можно взять молоко. По всей поверхности разложить куски сливочного масла, посыпать густо сырной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6583,'Разогреть растительное масло на сковороде, положить на нее котлетки при помощи ложки, обжаривать по три минуты с каждой стороны. Должна получится золотистая корочка, но не зажаривать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6578,'В конце разложить листья розмарина, накрыть фольгой, оставить немного свободного пространства. Поставить в духовку. Готовить минут пятьдесят, соблюдая температуру 180 градусов. Минут за пять до конца готовки убрать фольгу, дать зарумяниться сырной корочке. Подавать куриное филе с луком под картофелем со свежими или солеными овощами, зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6579,'Отварить рис. Почистить авокадо и порезать на маленькие кубики. Отварить яйцо и порезать на мелкие кубики. Почистить свежий огурец, порезать на маленькие кубики. Подержать креветки секунд шестьдесят в кипящей воде. Чуть-чуть заморозить сливочный сыр филадельфия, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6579,'Уложить салат «Сушивкус» слоями: рис, авокадо, сливочный сыр, подсоленное чуть-чуть яйцо, майонез, свежий огурчик, креветки, сливочный сыр. Перед подачей украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6580,'Миндаль залить кипятком, чтобы почистить от кожуры. Снять кожуру. Обсушить и измельчить в комбайне, чтобы получилась мелкая пудра. Смешать ее с сахарной пудрой. Несколько раз пропустить через ситечко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6580,'Отделить желтки от белков. Взбить белки и сахар, вводя его постепенно. Взбивать до густой смеси. Добавить пищевой краситель коричневого цвета. Добавить 1/3 сахарно-миндальной смеси, осторожно размешать лопаткой. Положить остальную массу, осторожно размешивать, приподнимая смесь. Размешивать до однородности массы, н, чтобы она не была очень жидкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6580,'Покрыть противень специальной бумагой. Кондитерский мешок диаметром 8 миллиметров заполнить тестом, выдавить макароны на расстоянии 5 сантиметров друг от друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6580,'Намочить палец, прихлопнуть верхушку всех макарон, чтобы воздух вышел. Подсушить минут тридцать. Отправить макароны минут на тринадцать в духовку, соблюдать температуру 150 градусов. Приоткрыть духовку. Через минуту открыть духовку полностью и дать остыть макаронам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6580,'Приготовить шоколадную глазурь: соединить в емкости шоколад, разломанный на куски, сахар и сливки. Поставить емкость на водяную баню, довести до однородности, непрерывно мешая. Нанести глазурь на половину макарунов, накрыть второй. Поставить шоколадные макаруны на сутки в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6581,'Взбить желтки, ванилин и сахар. Положить масло, взбить до однородной массы. Соединить муку и разрыхлитель. Размешивая лопаткой, насыпать в тесто муку. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6581,'Поделить на три одинаковые части. Отправить минут на тридцать в холодильник. Сделать безе: взбить белки и сахар до пиков. Добавить несколько капель сока лимона или соль, чтобы легче было взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6581,'Раскатать из теста пласт на противне, застеленном бумагой. Нанести сверху 1/3 белков. Готовить коржи минут тридцать, соблюдая в духовке температуру 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6581,'Сделать крем: взбить вареное сгущенное молоко и масло до однородности. Обжарить арахис на сухой сковороде, почистить, порубить на куски. Чуть-чуть оставить для обсыпки. Высыпать орехи в крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6581,'Положить на плоскую тарелку корж, намазать половиной крема. Положить второй корж – вниз безе, намазать остальным кремом. Положить третий корж, вверх безе. Украсить торт «Иван-да-Марья» растопленным шоколадом и орехами. Поставить на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6582,'Выбрать для блюда большой кусок мякоти свинины, промыть, обсушить, натереть равномерно солью, обсыпать со всех сторон мукой, зарумянить в сильно разогретом жире. Переложить мясо в сотейник, влить жир, оставшийся после жарки, присыпать майораном или тмином, добавить немного бульона, потушить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6582,'Лук нарезать на кольца, яблоки очистить от семенной коробки и нарезать дольками, положить все к мясу и довести до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6582,'Вынуть мясо и яблоки, в оставшуюся жидкость добавить обжаренную муку и протертые яблоки, подсолить, дать соусу закипеть и процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6582,'Подавать к столу филе свинины тушеное с яблоками по-польски нарезанным на ломтики и политым соусом. на гарнир – соленые огурцы, вареный картофель, квашеная капуста, тушеная свекла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6583,'Положить в одну емкость манную крупу, фарш, сметанку, горчицу, яйцо, соль, сахар, специи. Измельчить зелень, положить к ингредиентам, хорошенько размешать. В результате получается жидковатый фарш, его удобней брать ложкой, а не руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6583,'Налить чуть-чуть воды в сковороду, накрыть крышкой, сделать средний огонь, тушить котлетки из индейки минут десять. Пять минут с одной стороны и пять с другой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6584,'Взять банку на 3 литра, добавить заранее промытый и порезанный в виде долек апельсин. Сюда же следует положить сахар и влить водку. Все ингредиенты аккуратно перемешать. Взять кипяченую охлажденную воду и залить ей ингредиенты в банке до того уровня где сужается горлышко. Закрыть банку, используя полиэтиленовую крышку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6584,'Емкость с содержимым отправить на подоконник, банка должна простоять не более 1-ой недели. Каждый день тщательно следует содержимое перемешивать. Спустя неделю, почти готовый напиток необходимо поцедить, для этого нужно использовать марлевый отрез. Ягоды аккуратно отожмите. Хранится малиновый ликер с апельсином в прохладном месте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6585,'Нарезать баклажаны в виде тонких длинных ломтиков, затем переложить в емкость небольших размеров, добавить небольшое количество соли и воды. По истечении 30-ти минут слить жидкость и аккуратно выложить баклажаны на тарелку, застеленную бумажным полотенцем. Порезать помидоры в виде ломтиков. Измельчить зелень и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6585,'Взять емкость переложить в нее измельченную зелень с чесноком и добавить майонеза, ингредиенты тщательно помешать. Поставить сковороду на огонь, влить небольшое количество масла и нагреть его. Положить в разогретое масло кусочки баклажанов и обжарить их с каждой стороны до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6585,'Положить обжаренные ломтики овоща на плоское блюдо. Сверху смазать баклажаны майонезной массой и аккуратно положить помидорные ломтики. По своему вкусу можете посыпать черным молотым перцем и солью. Далее свернуть баклажаны с помидорами в виде рулетика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6586,'Разрезать банан поперек, а затем две половинки разрезать вдоль еще раз пополам, должно получиться четыре банановых кусочка. Вставить в каждый банановый кусочек палочки и выложить на лист пергаментной бумаги. Отправить в морозильную камеру на несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6586,'Как только бананы немного заморозятся, взять кружку, заполнить шоколадом и растопить его в микроволновке. Все банановые кусочки по очереди опустить в шоколадную массу. Взять лист пергаментной бумаги и аккуратно выложить на него бананы в белом шоколаде и снова отправить в морозильную камеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6587,'Нарезать головку лука, шампиньоны в виде мелких кубиков и обжарить на предварительно разогретой сковороде с добавлением растительного масла. Обжаривайте до тех пор, пока лук с грибами не приобретет золотистый цвет. Куриное филе отбить с помощью кухонного молотка и посыпать черным молотым перцем и солью. Очистить картофель и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6587,'Подготовленное куриное филе переложить в термостойкую емкость, выложить на него обжаренный лук с шампиньонами, далее нарезанные заранее в виде полуколец помидоры и перья зеленого лука, посолить, засыпать потертым картофелем и снова посолить. Залить сметаной, также можете использовать майонез. Разогреть духовой шкаф до 180 градусов и отправить куриную грудку под шубой запекаться на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6588,'В большой посуде соединить муку, сахар, крахмал и соль. Налить молоко, размешать. Вбить яйцо, положить растопленное сливочное масло. Взбить при помощи венчика. Пожарить, как обычные блины, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6588,'Сделать начинку: соединить сметану, сгущенное молоко и творог. Намазать начинку на блин. Можно положить несколько блинов рядом внахлест, чтобы получилось полотно из блинов. На край положить кусочки бананов, туго свернуть в виде ролла. Порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6588,'Сделать соус: соединить в ковшике необходимые ингредиенты, подогреть, чтобы соус стал жидким. Рулетики из блинов с нежным кремом полить соусом и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6589,'Снять цедру с лимона. Растереть творог и сахар. Вбить яйцо, растереть. Насыпать манную крупу, муку, добавить цедру. Перемешать до однородности. Накрыть пленкой, отправить на ночь в холодильник. Набрать воду в кастрюлю. Поставить на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6589,'Мокрыми руками скатать из теста шарики, придавить вилкой. Посолить воду. Опустить вареники в кипящую воду, подождать, пока всплывут. Достать, добавить в ленивые вареники из творога любые ягоды и масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6590,'Разрезать на две части маргарин или масло, дать постоять, чтобы стало мягким. В большой емкости с помощью миксера взбить яйца и сахар, добавить погашенную соду, взбить. Положить масло, порубить его, взбивать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6590,'Медленно насыпать муку, пока удобно взбивать миксером. Насыпать по чуть-чуть муку, перемешивать ложкой. Когда станет тяжело мешать ложкой, вылить тесто в остальную муку, перемешивать руками. Тесто должно получиться мягким и не прилипать. Если липнет, то насыпать немного муки, вымешать. Накрыть тесто пленкой, отправить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6590,'Нагреть духовку до 200 градусов. Посыпать противень мукой или застелить специальной бумагой. Достать тесто, отрезать 1/4, остальное отправить в холодильник. Сформировать из теста колбаску, пропустить через мясорубку. Когда тесто прокрутится на 5-7 сантиметров, приподнять его снизу рукой и срезать ножом. Получается форма цветочка с основанием. Положить на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6590,'Очистить остатки теста с решетки, и сделать следующий цветок. Когда тесто закончится, достать из холодильника, отрезать еще часть и продолжать. Делать все быстро, чтобы заготовки не потеряли форму. Наполненный противень отправить в духовку, готовить приблизительно 35-40 минут. Посыпать печенье «Хризантема» сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6591,'Готовится закуска очень просто и легко. Порезать баклажаны на брусочки. Нагреть на сковороде несколько ложек растительного масла, обжарить пару зубчиков измельченного чеснока. Положить баклажаны, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6591,'Насыпать сахар, налить соевый соус. Обжаривать 5 минут, чтобы баклажаны стали мягкими. Баклажаны не должны быть слишком мягкими. Положить в закуску из баклажанов остальной чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6592,'Порезать филе на кусочки, посыпать перцем, солью, обжарить на растительном масле, помешивать до готовности. Отварить в подсоленной воде макароны, отбросить на дуршлаг. Растопить в емкости сливочное масло, положить горчицу, сметану, тертые яйца, налить белое вино, добавить измельченную зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6592,'Соединить куриное филе и макароны, полить соусом. Перемешать. Перед подачей посыпать спагетти с куриным филе в сметанном соусе тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Тщательно промыть в теплой воде, засыпать солью и выскоблить щеткой рубец, промыть проточной холодной водой и поставить варится, нагреть до кипения, вылить воду, а рубец обдать холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Сварить костный бульон, отлить примерно половину, в оставшуюся часть положить рубец и варить 4 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Добавить в конце варки половину овощей, оставшиеся овощи порезать соломкой и обжарить на растопленном жире.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Подрумянить на другой сковороде до золотистого цвета муку, залить бульоном и дать закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Дать мясу остыть в бульоне, вынуть и нарезать тонкой соломкой, положить вместе с обжаренными овощами в соус, посолить, поперчить, добавить мускатный орех.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6593,'Разлить суп из рубца «Фляки» по-варшавски по суповым тарелкам, отдельно подать натертый сыр, молотый красный перец, молотый имбирный корень и майоран.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6594,'Разделать рыбу, осторожно удалить косточки. Приготовить смесь для рыбы. Соединить прессованный чеснок, орегано, паприку, соль, оливковое масло. Размешать. Намазать смесью филе скумбрии, отставить на 30-40 минут мариноваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6594,'Положить специальную бумагу или фольгу на жаропрочный лист. Осторожно выложить филе кожей вверх, чуть-чуть посыпать солью. Отправить на 10 минут в духовку, соблюдать температуру 220 градусов. Чтобы рыба была зажаренной, оставить в духовке еще на 10-15 минут. На гарнир к запеченной скумбрии с чесноком подавать картофель, посыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6595,'Взбить все ингредиенты для бисквита. Начинать следует с масла и сахара, налить молоко, добавить желтки, насыпать муку, ванильный сахар, разрыхлитель. Постелить на противень специальную бумагу, распределить смесь тоненьким слоем. Чтобы не разрезать бисквит, можно готовить его одновременно в двух формах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6595,'Взбить сахар и белки, чтобы получилась густая меренга. Распределить ее по бисквиту, посыпать миндалем. Отправить на 15-20 минут в духовку, соблюдать температуру 180 градусов. Меренга поднимется и станет больше. Немного охладить торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6595,'Сделать крем из сливок. Разделить бисквит на две части, осторожно переложить в форму одну часть. Намазать лучший торт с миндалем кремом, накрыть второй частью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6596,'Приготовить тесто: соединить в емкости масло, миндальную крошку, муку, соль и 25 грамм сахара. Растереть руками все в крошку. Добавить желтки. Во время замешивания теста, подливать воду. Положить тесто между листами пергамента, тоненько раскатать. Перенести тесто, используя бумагу, в форму, намазанную маслом. Сформировать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6596,'Соединить рикотту, яйца и сахар. Насыпать крахмал, добавить пастообразный творог. Положить начинку в форму с тестом. Готовить 30 минут, соблюдать температуру 200 градусов. Остудить. Почистить мандарины, убрать косточки. Выложить дольки мандарин на остывший тарт. Приготовить желе, как написано в инструкции. Залить им тарт с мандаринами и подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6597,'Мелко потереть сыр. Взбить сметану, яйцо, посыпать перцем, добавить прессованный чеснок, 2/3 сыра. Перемешать. Намазать массой листы лаваша, посыпать сыром. Порезать лаваш на кусочки, положить на сухой противень, готовить чипсы из лаваша до золотистой корочки, соблюдать температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6598,'Отварить картофель, потереть, выложить на блюдо в виде апельсиновой дольки. Сделать майонезную сетку. Порезать на кубики филе курицы, положить на картофель слоем, покрыть майонезной сеткой. Порезать мелко лук, выложить на мясо, покрыть майонезом, равномерно распределить вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6598,'Порезать на кубики маринованные огурцы, намазать майонезом. Отварить морковь, мелко потереть. Выложить морковь на внешнюю часть дольки. Остальную поверхность покрыть тертым сыром, сделать сегменты морковью. Отправить салат «Апельсиновая долька» на несколько часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6599,'Чуть-чуть подогреть молоко. Развести в нем дрожжи, насыпать несколько ложек муки и сахара. Перемешать, отправить в тепло. Просеять остальную муку, положить охлажденное и натертое масло. Перетереть массу руками. Сформировать горку, в середине сделать углубление. Вылить в углубление опару. Замесить тесто. Отправить в холодильник минут на 40.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6599,'Когда тесто остынет, достать и разделить на 4 части. Раскатать 4 пласта толщиной 2 миллиметра. Посыпать корицей и сахаром. Порезать каждый круг на 8 секторов, сформировать рогалики. Положить на противень. Отправить в духовку, готовить до золотистого цвета, соблюдать температуру 180 градусов. Посыпать вкусные синнабоны сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6600,'Взбить при помощи венчика 2 яйца и сахар, подогреть на водяной бане, чтобы сахар растворился полностью. Взбить миксером до густой пены. Налить теплый кефир или ряженку, растительное масло. Просеять муку, добавить соль, пакетик ванильного сахара. Соединить все и перемешать венчиком или миксером, чтобы исчезли все комочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6600,'Насыпать маленькую ложку соды, отставить минут на 5. Выпекать на сухой сковороде. По размеру панкейки получаются больше, чем оладьи, но меньше блинчиков. Набирать тесто в небольшой половник и выливать в середину хорошо нагретой сковороды. Тесто само распределяется по поверхности сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6600,'Если начинают появляться пузырьки, то панкейк необходимо быстро перевернуть. Вторую сторону выпекать совсем недолго. Пышный панкейк переложить со сковороды на тарелку, налить следующую порцию теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6601,'Нагреть духовку до 180 градусов. Взбить масло и сахар до пышного состояния. Вбить яйца. Добавить ванильный экстракт, орехи, насыпать какао, соль. Перемешать до однородности. Соединить муку и разрыхлитель. Ввести в тесто небольшими порциями. Перемешивать после каждой порции до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6601,'Сделать из теста колбаску мокрыми руками. Положить на противень, застеленный пергаментом. Выпекать 20-25 минут, должны появиться трещинки. Достать, порезать на кусочки по 1-1,5 сантиметра. Разложить шоколадно-миндальное печенье на противне, отправить на 8-10 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6602,'Почистить картофель, порезать на пластинки толщиной 1 сантиметр. Почистить баклажаны, порезать на такие же пластинки. Намазать овощи оливковым маслом, выложить на противень, застеленный специальной бумагой. Готовить в горячей духовке до полуготовности, приблизительно 15 минут, соблюдать температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6602,'Для приготовления баклажанов можно использовать сковороду-гриль. Почистить и измельчить сельдерей и лук. Обжаривать 7-10 минут на большой сковороде на оливковом масле. Добавить фарш, перемешать. Соединить воду, вино, томаты в собственном соку. Вылить в фарш. Посыпать перцем, солью, положить базилик, орегано. Довести до кипения, убрать с огня. Потереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6602,'Взять прямоугольную форму, намазать маслом, выложить слой картофеля. На картофель положить 1/2 баклажанов. Добавить фарш с жидкостью и остальные баклажаны. Приготовить соус бешамель: нагреть молоко. Растопить сливочное масло в кастрюле с толстым дном. Насыпать муку, обжаривать 2 с половиной минуты, помешивая.  Медленно налить горячее молоко, готовить 5 минут, постоянно помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6602,'Посыпать соус перцем, солью, убрать с плиты. Вылить соус в форму с фаршем и овощами, посыпать тертым сыром, равномерно распределить. Отправить форму на 40 минут в духовку, соблюдать температуру 180 градусов. Если соус сверху сильно потемнеет, то накрыть блюдо фольгой. Перед подачей дать греческой мусаке с баклажанами настояться 7-10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6603,'Сварить из костей крепкий бульон, добавить порезанные морковь и корень петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6603,'Сварить отдельно рис, не разваривать, он должен получиться рассыпчатым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6603,'Приготовить из муки и масла пассировку, добавить ее в процеженный бульон, довести до кипения, всыпать рис, положить тонкие пластинки лимона без кожуры, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6603,'Разлить лимонный суп по-польски с рисом по тарелкам и заправить сметаной, вкус супа должен получиться слегка кисловатым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6604,'Приготовить рассол: налить в кастрюлю воду, насыпать сахар, молотый перец, соль, налить уксус 70%. Довести до кипения. Вымыть капусту, порезать на 8-10 частей. Почистить морковь, крупно потереть, положить к капусте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6604,'Почистить и измельчить чеснок. Залить горячим рассолом, перемешать несколько раз. Отправить капусту в горячем рассоле в холодильник на 24 часа. Через сутки можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6605,'Замороженный маргарин руками растереть с мукой и сахаром в крошку. Взять форму диаметром 28 сантиметров, выложить в нее крошку, утрамбовать, отправить в холодильник на 20 минут. Отправить на 25-30 минут в духовку, соблюдать температуру 180 градусов. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6605,'Соединить в емкости воду и сахар, довести до кипения. Положить масло, добавить сгущенное молоко, лимонный сок. Перемешать, готовить 20 минут. В самом конце положить обжаренные орехи, например, фундук, остудить. Полученную нугу вылить на корж, равномерно распределить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6605,'Растопить шоколад, вылить на нугу, отправить в морозилку или в холодильник. Порезать печенье на треугольники. Можно подавать треугольники «Три слоя» на десерт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6606,'Порезать курицу на средние кусочки. Обжарить на растительном масле и морковью и луком. Порезать картофель на кольца или крупные кубики. Насыпать 2 ложки муки. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6606,'Положить картофель. Налить воду, чтобы она покрывала картофель. Насыпать специи. Накрыть жаркое по-домашнему крышкой, тушить. Минут за 10 до конца готовки положить 3 лавровых листа. После приготовления листы убрать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6607,'Взбить мягкое масло и сахар до пышной смеси. Положить желтки, взбить, чтобы желтки равномерно распределились в массе. Насыпать муку и сразу замесить мягкое тесто. Поместить тесто в пакет или завернуть в пленку, отправить в холодильник минимум на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6607,'Вынуть тесто, выложить формочку диаметром 26 сантиметров. Равномерно распределить тесто по дну формы. Часть теста скатать в виде жгута, сделать бортик. Нагреть духовку. Сделать в тесте проколы вилкой, чтобы оно не вздулось.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6607,'Выпекать 7-10 минут, соблюдать температуру 180-200 градусов. Взбить белки и сахар до пиков. На готовый корж выложить начинку, на нее взбитые белки. Отправить песочный пирог с ягодами и меренгой минут на 30 в духовку. Перед подачей на стол остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6608,'Постелить в форму фольгу в несколько слоев. Порезать лук на кружочки, положить в форму. Порезать картофель на ломтики, положить сверху лука. Посыпать солью, специями. Соединить сметану или майонез с солью, специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Почистить лук, морковь, картофель. Порезать овощи на кубики.','https:https://st.vkuso.ru/data/cache/thumb/e0/f1e50393f5f4de0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6608,'Намазать смесью куриные голени, положить сверху картофеля. Крупно потереть сыр, посыпать блюдо. Накрыть фольгой, осторожно скрепить края с нижним листом. Готовить куриные голени с картофелем в фольге 60 минут, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6609,'Скатать из поперченного и посоленного фарша маленькие шарики. Обвалять лепешки в муке. Обжарить на горячем масле со всех сторон. Готовятся домашние отбивные очень быстро.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6610,'Растереть творог. Вбить яйцо, положить сметану, насыпать соль, сахар, муку и соду. Перемешать. Замесить тесто. Посыпать поверхность мукой. Из полученной массы раскатать тоненькие жгутики. Порезать на трубочки любой длины. Обжарить со всех сторон до золотистого оттенка. Посыпать творожные трубочки сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6611,'Просеять муку, положить кусочки масла. Перетереть в крошку, положить сметану. Замесить однородное мягкое тесто. Если тесто не эластичное и твердое, то добавить сметану. Завернуть в пленку, отправить на 60 минут в холодильник. Дать тесту отойти полчаса. Разделить на 3-4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6611,'Раскатать пласт толщиной 3 миллиметра на поверхности, посыпанной мукой. Разрезать на квадраты 7 на 7 сантиметров, в центр положить варенье, свернуть в рожок. Защипнуть края, сформировать кифлики. Выпекать 15-25 минут, соблюдать температуру 200 градусов. Готовые булочки-кифлики с вареньем обмакнуть в сахарной пудре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Отварить вкрутую перепелиные яйца, остудить и нарезать на половинки, оставить несколько штук для украшения салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Помыть и залить кипятком изюм, хорошо промыть листья салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Сварить в подсоленном кипятке стручки фасоли (около 10 минут), отцедить и дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Измельчить листья салата руками, смешать с фасолью, высыпать обсушенный изюм, половинки яиц, крупно натертый сыр и аккуратно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Приготовить соус, для этого добавить в растертые с горчицей желтки (2 шт.) мед, соль и продолжая взбивать частями (по 1 ч.л.) масло, в конце в соус положить раздавленный прессом чеснок и лимонный сок, подсолить, слегка поперчить и хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Соус необходимо готовить непосредственно перед подачей салата к столу, т.к. он при стоянии расслаивается.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6612,'Салат с фасолью, перепелиными яйцами, сыром и изюмом полить сверху соусом и украсить половинками яиц.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6613,'Нагреть духовку. Намазать формочки маслом. В емкости соединить сухие продукты. В отдельной емкости взбить яйца, медленно добавить сметану. Положить подтаявшее масло, взбить. Вмешать в массу сухие ингредиенты, отставить, чтобы разбухла. Разложить тесто по формочкам. Готовить шоколадные маффины на сметане в духовке 15-20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6614,'Соединить яйца и молоко, используя блендер. Насыпать манную крупу, хорошо взбить. Почистить бананы, порезать на кружки, выложить в специальную форму. Залить бананы смесью, отправить в мультиварку на 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6614,'Достать пудинг из мультиварки, дать чуть-чуть остыть, чтобы жидкость, выступающая из блюда, впиталась обратно. Разрезать пудинг «Банановый рай» на кусочки и подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6615,'Отделить желтки и белки. В емкости взбить белки, используя миксер. Отдельно взбить желтки и сахар до однородности. В желтки насыпать муку, перемешать, чтобы не было комков. Влить в массу белки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6615,'Постелить на противень бумагу. Осторожно распределить тесто. Нагреть духовку. Выпекать рулет 15 минут, соблюдать температуру 180 градусов. Свернуть бисквит с бумагой. Приготовить крем: смешать в посуде сметану и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6615,'Осторожно развернуть бисквит. Распределить по нему крем. По краю выложить банан, порезанный на кусочки. Осторожно свернуть рулет. Подавать рулет с бананом в охлажденном виде, чтобы он пропитался.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6616,'Нагреть духовку до 160 градусов. Вымыть сливы, убрать косточки, обтереть, порезать на дольки, выложить в цельную форму. Взбить молоко с яйцами. Молоко можно заменить жирными сливками, но тогда пирог будет жирнее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6616,'Насыпать сахар, ванильный экстракт, муку. Если ягоды сладкие, то сыпать меньше сахара, если не очень сладкие, то меньше. Взбить венчиком до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Использовать с фаршем рикотту, она поможет не высушить рожки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6616,'Вылить полученную массу на сливы, готовить 1-1,5 часа, пока пирог не станет золотистого цвета. В конце посыпать пирог со сливами молотыми фисташками или сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6617,'Соединить сметану с сахаром или медом, растереть ложкой. Мелко потереть шоколад. Намочить руки, положить на ладонь творожную массу, используя ложку. Сделать лепешку, в центр положить 1⁄2 финика или миндальный орех.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6617,'Завернуть начинку, чтобы получился шарик, обвалять в шоколадной стружке. Положить пирожные из творога на блюдо, отправить на полчаса в холодильник, чтобы они охладились.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6618,'Нашинковать капусту, порезать огурцы соломкой. Смешать капусту с огурцами, заправить соком лимона и оливковым маслом. Размешать. Измельчить укроп. Размять сыр, смешать со сметаной, положить чеснок, насыпать измельченный укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6618,'Перемешать. Осторожно перемешать овощи и заправку. Солить нет необходимости, так как сыр соленый сам по себе. Можно чуть-чуть посыпать капустный салат черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6619,'Аккуратно воткнуть в половинки яблока целые гвоздики. Порезать апельсин на кружки. Нагреть в кастрюле яблочный сок на небольшом огне. Когда нагреется, насыпать сахар, мешать, пока не растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6619,'Добавить остальные продукты. Довести до кипения, готовить 15 минут. Достать яблоки, апельсин, корицу, гвоздики. Разлить горячий яблочный сидр по чашкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6620,'Отварить вкрутую яйца, разрезать поперек, убрать желтки, острые концы белков срезать для устойчивости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6620,'Смешать паштет с 3 желтками, сметаной, рублеными орехами, подсолить, добавить чуть мускатного ореха и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6620,'Наполнить половинки белков полученной массой, посыпать сверху двумя оставшимися тертыми желтками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6620,'Яйца фаршированные паштетом со сметаной и орехами выкладываются на листья салата в плоское блюдо, украшаются зеленью и охлаждаются.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6621,'Соединить все продукты, отставить на 30 минут. Насыпать разрыхлитель. Перемешать. Готовить в духовке до сухой спички, соблюдать температуру 200 градусов. Сверху на ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6622,'Все ингредиенты взбить до состояния густой сметаны. Разделить тесто пополам. В одну часть насыпать маленькую ложку какао. Приготовить 2 коржа. Когда они остынут, разрезать их вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6622,'Сделать крем: взбить сметану и сахар. Намазать коржи кремом. Можно добавить цукаты или орешки. Посыпать сверху какао. Дать домашнему тортику на кефире настояться 3 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6623,'Порезать соломкой яйца и курицу. Потереть сыр. Измельчить орехи. Каждый ингредиент соединить с майонезом, можно подсолить. Чуть-чуть сыра оставить для украшения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6623,'Выложить слои: курицу, орехи, сыр, яйца. По краям посыпать салат сыром. Сверху на салат «Первый снег» положить половинки винограда и сыр в виде снежинок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6624,'Подготовить овощи, как на суп. Почистить картофель и порезать на небольшие кубики. Крупно потереть морковь, лук порезать на полукольца. Во время подготовки овощей, поставить на огонь воду для бульона. Крупно потереть маринованные огурцы, порезать лимон на кружочки. Порезать разные виды колбасы и копчености.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6624,'Положить картофель в кипящую воду, добавить перышки зеленого лука. Минут 10 варить овощной бульон на среднем огне. Приготовить заправку для супа. На масле обжаривать минуту морковь и лук, положить к овощам в сковороду лимон и огурцы, пассировать еще минуту, добавить томатную пасту, готовить еще минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6624,'Отправить заправку в бульон. Попробовать на вкус, посыпать перцем, солью. Можно добавить сахар, чтобы вкус стал более мягким. Когда картофель в солянке будет готов, положить колбасу, копчености, зелень. Можно добавить маслины. Сделать минимальный огонь, готовить сытную солянку с колбасой 3-5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6625,'Потереть яблоки, соединить с яйцом и творогом. Отправить на 5 минут в микроволновку. Посыпать корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6626,'Осторожно снять с голени кожу, используя нож. Прорезать пленку с голени, пока не дойдет до кости. Протыкать ножки, чтобы впиталось предварительно приготовленное ароматное масло. Приготовить его следующим образом: положить в сливочное масло соль, перцы, прессованный чеснок, добавить оливковое или растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6626,'Натереть мясо маслом, снова одеть «чулок», намазать остальным маслом. Порезать картофель на крупные куски, выложить его на противень, посыпать солью, сверху положить помидоры, порезанные на кусочки. На овощи выложить голени. Выпекать 50 минут, соблюдать температуру 200 градусов. Можно подавать запеченные голени индейки с травами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6627,'Порубить блендером помидор, перец, чеснок, лук с добавлением итальянских трав и базилика с томатной пастой, переложить соус в сковороду с маслом, тушить до испарения большей части сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6627,'Смазать противень маслом, уложить раскатанную из теста лепешку, смазать томатным соусом, разложить кусочки моцареллы, прикрыть кружочками помидора, а потом опять сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6627,'Запекать пиццу «Маргарита» в прогретой до 200 градусов духовке до расплавления сыра и подрумянивания краев. Готовую выпечку присыпать порубленным базиликом и тертым твердым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6628,'Курицу вымыть, обсушить, разрезать на 8 частей, поперчить, присолить, быстро обжарить. Обжарить полукольца лука до светло-желтого цвета, по отдельности обжарить кусочки грибов и орехи, хорошо вымыть и обсушить изюм. Для сметанного соуса растопить масло, добавить муку, обжарить до появления орехового запаха, развести сметаной, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6628,'Разложить мясо по горшочкам, добавить изюм, орехи, лук, грибы, залить соусом. Поставить жаркое из курицы с грибами по-русски на треть часа в духовку с температурой 180 градусов, готовое жаркое присыпать мелко порезанной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6629,'Обжарить нашинкованный лук и чеснок, добавить кусочки помидоров, перемешать обжарить пару минут, влить бульон, добавить кусочка хлеба (3 больших), порезанного на кубики и без корок, массу подсолить и поперчить. Тушить на малом огне под крышкой около 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6629,'Разлить томатный суп по горшочкам, положить в каждый по куску хлеба, хорошо натертого чесноком, присыпать сырной стружкой, побрызгать маслом, убрать запекаться в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6630,'Приготовить из ржаной или овсяной муки закваску (жур), в керамической посуде развести муку со стаканом воды, убрать в теплое место на 3-4 дня для брожения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6630,'Сварить из костей и грудинки с добавлением моркови и корня петрушки бульон и процедить, грудинку порезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6630,'Добавить в бульон жур, нагреть до кипения, положить грудинку, посолить, заправить растертым с солью чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6630,'Жур по-польски с копченой грудинкой подавать с вареным картофелем, политым растопленным маслом, украсить в тарелке зеленью петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6631,'Порубить тушку на порционные куски, порезать овощи кубиками, спассеровать лук, переложить на тарелку, спассеровать морковь, грибы отварить, порезать на кусочки. По горшочкам разложить порубленное мясо, картофель, лук и морковку, грибы, полить верх соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6631,'Поставить цыплят с картошкой в горшочке на 40 минут в духовку, через полчаса присыпать тертым сыром. Для приготовления соуса поджарить на сухой сковороде муку, чуть охладить, залить горячим бульоном от грибов, хорошо перемешать до однородного состояния, проварить треть часа, добавить сметану, подсолить, проварить еще минут 5.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6632,'Нашинкованный лук и кусочки мяса разложить по горшочкам, всыпать в каждый 3 ст.л. вымытой гречневой крупы, добавить кусочки лаврового листа, залить любым бульоном. Поставить гречку со свининой в горшочке на час в духовку, готовить на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6633,'Обжарить сосиски с луком, отдельно с луком – грибы, подрумянить соломку из картофеля на масле. В горшочки налить чуть воды, положить картофель, подсолить, добавить грибы и сосиски, положить по ложке хорошей сметаны. Поставить картофель с сосисками и грибами в горшочке в духовку с температурой около 150 градусов на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6634,'Порезать мясо на кусочки, присолить, поперчить, быстро обжарить до легкой корочки, сложить в горшочки. Положить кусочки картофеля, жаренный лук, нашинкованную зелень, чернослив, закрыть горшочки с телятиной и черносливом крышкой, тушить в духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6658,'Капуста цветная в кляре с карри подается на широком блюде, вокруг, как рождественский венок, выкладывается зелень, украшается оливками, помидорами черри, половинками перепелиных яиц или другими продуктами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6635,'Картофель порезать, нашинковать и обжарить лук, сложить в горшочки, поперчить красным перцем, тушить до мягкости картофеля. Добавить томатную пасту, ломтики огурца, и кубики рыбы, влить подсоленные сливки, закрыть крышкой. Отправить филе рыбы с картофелем по-орхидски в духовку, тушить до готовности, достать присыпать порубленной зеленым луком, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6636,'Почистить баклажаны, порезать на средние кубики, чуть присолить, дать постоять час. Грибы отварить, чуть остудить, мелко порубить, обжарить на сливочном масле с кубиками лука. Отжать кубики баклажанов, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6636,'Заполнить горшочки баклажанами, грибами, добавить сверху кружочки отварных яиц, прикрыть слоем баклажанов, положить сметану. Поставить баклажаны с грибами в горшочке в духовку, запекать до готовности, достать, присыпать нашинкованной зеленью, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6637,'Порезать печенку на ломтики, поперчить, посолить, запанировать в муке, обжарить в сливочном масле до полуготовности. Отварить замоченные грибы, немного остудить, порезать на кусочки, обжарить с измельченным луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6637,'Положить в горшочки печень, грибы, залить по половине стакана грибного бульона в каждый, добавить половине стакана сметаны, по ложке томатного пюре, отправить на 20 минут в духовку. К печени с грибами подать соленые огурцы, свежий салат или квашеную капусту. По желанию к грибам и печени можно добавить обжаренный картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6638,'Растереть мягкое масло и сахар, добавить измельченный миндаль и яйцо, перемешать. Добавить смесь просеянной муки с разрыхлителем, вымесить тесто, заполнить форму, смазанную маслом, сформовать бортики. Поместить минут на 10 в духовку, предварительно разогретую до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6638,'Для приготовления крема растереть муку с сахаром, молоко хорошо подогреть (не кипятить), добавить к желткам, перемешать, поставить на плиту, варить, помешивая до сгущения. Достать основу из теста, уложить вишню, сверху – крем. Выпекать вишневый пирог под кремом примерно 25 минут при температуре 180 градусов, дать остыть, нарезать на куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6639,'С мешать аджику, майонез, перец, чеснок, посолить, залить отбитые куски мяса, дать постоять два часа. Нашинковать лук, порезать грибы, обжарить до готовности с чайной ложкой майонеза, посолить, поперчить. Натереть крупно охлажденный сырок, добавить раздавленный прессом чеснок, яйцо, куркуму, карри, столовую ложку майонеза, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6639,'Противень смазать маслом, разложить мясо, вокруг – помидоры и грибы, на мясо положить смесь из яйца и сыра, выпекать ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6640,'Протереть сквозь сито или растереть творог до пастообразного состояния, взбить яйцо с добавлением сахара и ванили до появления крепкой пены, смешать с творогом. Добавить просеянную муку и разрыхлитель, влить сметану, вымесить тесто. Раскатать в форме колбаски, порезать  на кусочки, скатать из каждого небольшой шарик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6640,'Для удобства руки смазать маслом. Обжарить творожные шарики на сковороде в хорошо прогретом масле на среднем огне. Выловить подрумяненные шарики, разложить на бумажном полотенце, переложить на блюдо, присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6641,'Смешать в кастрюльке масло, какао, сгущенку, прогреть, помешивая до получения густой массы около 10 минут. Снять с плиты, дать остыть, скатать из смеси небольшие шарики, присыпать вкусные шоколадные кексы кокосовой стружкой, орехами, сахарной пудрой или цветной кондитерской присыпкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6642,'Хорошо перемешать до однородности взбитые яйца, протертый творог, муку, соль, манку, ваниль, добавить промытый и обсушенный изюм, перемешать, дать постоять полчаса. Сформовать сырники с изюмом, обсыпать мукой, обжарить с двух сторон, подать с вареньем или сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6643,'Взбить яйца с добавлением сахара, всыпать разрыхлитель с мукой (желательно предварительно просеять), вымесить тесто. Заполнить тестом форму, смазанную маслом, выпекать десерт около 10 минут при температуре 180 градусов, достать, дать бисквиту остыть, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Каждую часть теста раскатать в овал диаметром примерно 12-15 см и, отступив от края где-то 3 см, выложить крем, закрыть его тестом и тщательно залепить все края, а оставшийся край теста нарезать полосками и сформовать булочку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6643,'Взбить до густого состояния сливки с сахаром, положить маскарпоне, смешать все на низкой скорости, влить бейлиз, осторожно перемешать, порезать на мелкие кусочки клубнику. В креманки положить часть крема, далее – бисквит, крем, кусочки клубники, крем, бисквит, крем. Поставить десерт с бисквитом, клубникой и кремом на некоторое время в холодильник, а можно и сразу подать к столу, оформить листочками мяты и клубникой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6644,'Смешать маскарпоне с желтками, растертыми с сахаром, добавить отдельно взбитые белки, осторожно перемешать. В креманки положить немного крема, далее – ягоды и палочки, быстро смоченные в смеси кофе и ликера (коньяка), прикрыть оставшимся кремом. Посыпать порционное тирамису мелко натертым шоколадом, убрать перед подачей часов на 5 в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6645,'Подготовить желатин по инструкции на пакетике. Перемешать сахар и желтки, подогреть до образования густой массы, удобным способом растопить шоколад, все смешать. Сливки взбить с сахаром, объединить с желтковой массой, добавить раствор желатина, хорошо перемешать. Разложить по креманкам, заполнить их только на 2\3, убрать на 4 часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6645,'Для соуса сахар перемешать с вишней, влить 100 мл воды, нагреть до кипения, варить  5 минут. В 100 мл воды разболтать крахмал, вылить к ягодам, перемешать, дать закипеть, убрать с плиты, дать остыть. Выложить соус на шоколадное суфле, вернуть креманки на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6646,'Залить желатин стаканом воды, перемешать, дать постоять и набухнуть. Приготовить кофе с сахаром, влить половину порции желатина, перемешать. Закипятить сладкое молоко, смешать с оставшимся желатином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6646,'Раствор кофе налить слоем в 2 см в широкий стакан, дать полностью застыть в холодильнике, налить молочный слой, дать застыть, долить кофе, дать желе «Кофе с молоком» окончательно застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6647,'Сварить картофель в мундире, облить холодной водой и очистить, сделать пюре, добавить масло, яйцо, муку, подсолить полученное негустое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6647,'Поджаривая и помешивая, подрумянить манную крупу, залить тремя стаканами кипятка, посолить и перемешать, оставить кашу остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6647,'Перекрутить на мясорубке обжаренные потроха, соединить их с манной кашей, поперчить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6647,'Раскатать 3 прямоугольника из картофельного теста, длина должна равняться размеру противня, выложить вдоль длинного края начинку, свернуть рулетом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6647,'Перед выпечкой каждый картофельный рулет с потрохами смазать растительным маслом, запекать рулеты 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6648,'Приготовить желатин по инструкции на упаковке, приготовить пюре из ягод, протереть от косточек на сите. Перемешать ягодное пюре с сахаром, залить водой, нагреть до растворения сахара, влить раствор желатина, перемешать (не кипятить!). Заполнить полученной массой наполовину креманки, поставить десерт на 7 часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6648,'Для приготовления суфле из сливок подготовить замоченный желатин, нагреть до полного растворения, остудить. Взбить в пышную устойчивую массу сахар со сливками, смешать с раствором желатина. Достать десерт-желе с красной смородиной, положить в каждую порцию сливочное суфле, присыпать мелко натертым шоколадом, убрать на 4 часа в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6649,'Нашинковать мяту, перемешать к кусочками клубники, измельчить печенье. Взбить смесь сахара и сливок, положить рикотту, хорошо все перемешать, разложить десерт в подходящие емкости, уложить поверх клубничную смесь, прикрыть слоем риккоты и сливок, посыпать крошкой из печенья и положить опять сливки с рикоттой, убрать десерт на 2 часа в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6650,'В половину стакана всыпать желатин, перемешать, дать постоять. Влить в сотейник сливки, всыпать сахар, перемешать, добавить семена ванили, нагреть почти до кипения, но не кипятить, влить желатин, перемешать, убрать с плиты, дать остыть. Заполнить составом креманки примерно до половины объема или чуть меньше, убрать на 5 часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6650,'Подготовить для вишневого желе желатин, нагреть вишню, сахар и стакан воды до кипения, проварить минут 5, процедить, перемешать с раствором желатина, дать остыть, вылить на застывшие хорошо сливки. Панна котту с вишневым желе перед подачей к столу убрать на 4 часа в холодильник для застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6651,'Залить дрожжи чуть теплым молоком, добавить пару столовых ложек масла и чуть-чуть сахара, перемешать, накрыть полотенцем, убрать в тепло на полчаса. Вбить яйцо, всыпать сахар с солью, влить йогурт, перемешать, порциями всыпать просеянную муку, вымешивая тесто (около 20 минут), вливать по столовой ложке оставшееся масло до получения эластичного теста, слегка прилипающего к рукам. Скатать гладкое тесто в шар, поместить в глубокую миску, прикрыть тканью, дать постоять час, обмять тесто, оставить стоять еще на полтора часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6651,'Присыпать стол мукой, переложить тесто, сформовать цилиндрическую заготовку в форме батона, разрезать на три части, дать постоять четверть часа. Для начинки натереть крупно сыр, перемешать его с яйцом, добавить растопленное масло, еще раз перемешать до однородности, разделить на равные три части. Раскатать три лепешки толщиной не более полутора сантиметров, по центру положить начинку, края хорошо защипать, положить на стол швом вниз, осторожно раскатать до диаметра примерно 20 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6651,'Смазать противень маслом, уложить на него очень сытные хачапури, смазать верх разболтанным яйцом, дать постоять полчаса. Наколоть вилкой, сделать по центру небольшое отверстие, поместить в прогретую до 200 градусов духовку, выпекать около трети часа до зарумянивания, подождать минут десять и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6652,'Крупно натереть морковь, тонко нашинковать капусту белокочанную, помять ее руками, порубить петрушку, у краснокочанной удалить центральную жесткую часть, нашинковать и помять до выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6652,'Перемешать все с кукурузой, добавить заправку, осторожно перемешать, убрать на пару часов в холодильник. Для заправки салата «Витаминный» перемешать с йогуртом соль, горчицу, сахар, уксус, перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6653,'Растереть творог с мягким маслом и сахарной пудрой, растопить на водяной бане или в микроволновке шоколад. Формочки смазать полностью (силиконовой кисточкой) шоколадом, поставить минут на 20 в морозилку, достать, наполнить творожной смесью, сделать в центре углубление, положить любое варенье, прикрыть творогом. Смазать домашние творожные сырки шоколадом, поставить в морозилку на полчаса, вынуть из формочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6654,'Растереть яйцо с сахаром и сметаной, добавить подсоленную муку, соду, перемешать, полученное тесто обернуть пленкой и убрать в холодильник. У апельсина удалить косточки, взбить блендером вместе с кожурой с добавлением сахара и крахмала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6654,'Вынуть тесто из холодильника, раскатать, положить ровным слоем начинку, свернуть в трубочку, убрать рулет в холодильник минут на 20, достать разрезать на 3 см кусочки. Разложить мягкие булочки с апельсином на смазанном противне, выпекать примерно треть часа при температуре 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6655,'Смазать противень маслом, включить для прогрева до 200 градусов духовку, подготовить капусту, помыть, оборвать листья. Перемешать йогурт с лимонным соком, чесноком, порошком чили, карри, тмином, чесноком и перцем, залить маринадом капусту. Готовить цветную капусту по-королевски около 40 минут в духовке, вынуть, дать 10 минут постоять, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6656,'Порезать мясо на кусочки, обжарить до золотистой корочки в масле, положить полукольца лука, перемешать, обжарить 3-5 минут. Добавить перец, порезанный соломкой, четвертинки шампиньонов, крупно натертую морковь с томатной пастой, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6656,'Вылить в сковороду воду (чуть больше стакана), тушить полчаса при малом нагреве, несколько раз свинину с шампиньонами и сладким перцем перемешать во время готовки, если потребуется, то подлить еще воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6657,'Все ингредиенты поместить в чашу блендера, смешать, перелить крем-ликер в бутылку, убрать в холодильник. Употреблять можно сразу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6658,'Помыть цветную капусту и разломить на соцветия, отварить в соленом кипятке 10 минут, откинуть на дуршлаг и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6658,'Взбить смесь из яиц, воды, карри и соли в однородную массу, разогреть масло на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6658,'Обвалять капусту в муке, насадить на вилку и обмакнуть в яичную смесь, выложить в сковороду и обжарить, в процессе несколько раз перевернуть, меняя стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Застелить пекарской бумагой противень, уложить на него все булочки и оставить на полчаса для расстойки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6659,'На плоскую тарелку выложить слои в следующем порядке: холодное отварное мясо, порезанное соломкой, крупно натертое яблоко с майонезом, натертый крупно картофель с майонезом, тертая свекла, морковка по-корейски, слой из майонеза. Украсить салат «Король» мелко порезанным укропом или по своему усмотрению.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6660,'Блендером взбить холодные белки до состояния мягких устойчивых пиков, сахар всыпать порциями, взбивать до блестящей крепких пиков. Застелить противень промасленной бумагой, высадить кольцами из мешка белковую массу, выпекать около полутора часов при температуре 100 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6660,'Для крема перемешать в однородную массу творог, сметану и сахар в блендере. Заполнить безе кремом, готовые белковые корзиночки с творогом оформить ягодами клубники, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6661,'Перемешать с творогом сахар, желтки и сметану, порциями добавить муку с ванилином и разрыхлителем, замесить тесто, чтобы не прилипало к рукам. Порезать очищенные яблоки, сбрызнуть лимонным соком, присыпать корицей и сахаром, перемешать начинку. Выстлать форму пергаментом, смазать маслом, заполнить тестом, сформовать бортики, положить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6661,'Поставить пирог с яблоками на творожном тесте запекаться в духовку с температурой 180 градусов примерно на 25 минут. Приготовить меренгу из взбитых миксером белков с добавлением сахара или сахарной пудры. Достать форму, покрыть пирог меренгой, вернуть в духовку с температурой 160 градусов на четверть часа, готовую выпечку остудить и достать из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6662,'Отварить яйца, желтки измельчить вилкой до состояния пасты. Сахар перемешать с мягким маслом, ванилином, солью, желтками. Полученную массу разделить пополам, добавить в одну порошок какао, хорошо перемешать. В каждую часть добавить по 140 г  муки, вымесить два вида теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6662,'Раскатать каждое в пласт, положить друг на друга, чуть прижать, убрать в холодильник минут на 40, достать срезать ровно края, разрезать на 4 одинаковые пластины. Сложить пластины вместе так, чтобы слои чередовались, порезать кусочками шириной по сантиметру. Противень выстлать бумагой, разложить французское печенье, выпекать около 15 минут при температуре 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6663,'Приготовить блины (20 шт.) по любому рецепту, разморозить вишню, удалить косточки. Можно испечь творожные блинчики. Растереть творог, яйца, сахар, соду и соль в однородную массу, заварить кипятком, хорошо перемешать. Небольшими порциями всыпать муку, вымешать до необходимой консистенции вместе с маслом. Приготовить стопочку блинчиков, накрыть миской минут на 10, чтобы они размякли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6663,'Взбить миксером все ингредиенты для сметанного крема. На плоском блюде сформировать тортик из блинов с вишневой начинкой. Выложить на блинчик вишневую начинку, свернуть трубочкой, сложить на блюдо горкой основание из 5 трубочек, далее 3-2-1. Залить кремом, оформить шоколадом, убрать на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6664,'На водяной бане растопить масло или сливочный маргарин, дать остыть. Включить для разогрева до 200 градусов духовку. Насыпать в глубокую миску сахар, залить маслом, вбить яйца, добавить ванилин, хорошо вымешать. Муку перемешать с разрыхлителем, порциями всыпать в миску, вымесить тесто, разделить на 2 части (одна поменьше), убрать маленькую в морозильник на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6664,'Уложить большую на противень в виде коржа,  уложить на нее варенье, крупно натереть на него тесто из морозилки. Поставить кучерявый ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6665,'В чаше миксера перемешать муку (предварительно просеять) с дрожжами, всыпать сахар, вбить яйца, перемешать, влить подогретое молоко с маслом, замесить тесто, накрыть тканью, дать подойти минут 30, убрать на 4 часа в холодильник. Второй вариант – подходит 2 часа, а при раскатывании добавит муки. Присыпать стол мукой, раскатать тесто по длине 2-х шоколадок, а в ширину – 3-х, лишнее тесто обрезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6665,'Переместить, используя скалку, тесто на противень с пергаментом, положить по центру полторы плитки шоколада, ножом отметить контур, выложить на него халву или орехи, или кружки банана. Нарезать свободные края теста на полоски по ширине равной кубику шоколада, заплести их, слегка растягивая, в косичку. Косичка из дрожжевого теста с шоколадом прикрыть тканью, дать постоять полчаса в тепле, смазать верх яйцом, выпекать примерно полчаса при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6666,'Размягченное масло смешать с яйцом, добавить сахар, сметану, соль, соду, тщательно перемешать, сыпать стакан муки, перемешать. Высыпать на стол стакан муки, на него поместить сметанную массу, вымесить тесто, разрезать на 2 части, раскатать каждую в круглый пласт толщиной не более 5 мм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6666,'На половину круга выложить творожную начинку, на него уложить колбасу, прикрыть пластинами сыра, завернуть край теста и прижать их. Проколоть пирог с сыром, творогом и копченой колбасой вилкой, поместить на противень, выстланный промасленной бумагой. Смазать верх разболтанным яйцом, выпекать около четверти часа при температуре 220 градусов до появления золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6667,'Отварить филе курицы до готовности, накрыв крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6667,'Нашинковать мелко лук и замариновать в уксусе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6667,'Порубить мелко вареные яйца, куриное филе нарезать небольшими кубиками, подсолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6667,'Слоеный куриный салат «Скорпион» выложить слоями на плоское блюдо: курица, маринованный лук, корейская морковь, яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6667,'Промазать каждый слой майонезом кроме верхнего, оформить салат изображением скорпиона из черных оливок, охладить перед подачей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6668,'Постелить на стол макису, обернуть ее пленкой, разрезать лист нори на 2 части, расположить его блестящей стороной вниз (параллельно пластинкам) на циновке. Смочить рисовым уксусом руки, взять рис, разложить на листе нори, 1 см противоположного края оставить свободным, на рис выложить крупную стружку сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6668,'Перевернуть нори рисом вниз, положить поверх квадратики сыра, кусочек семги и креветки. Приподнять край у макису, свернуть роллы с сыром, семгой и креветками, разложить их на тарелке, украсить ломтиками помидора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6669,'Кабачок крупно натереть, смешать с яйцом, добавить тертый сыр, раздавленный зубок чеснока, подсолить, поперчить, хорошо перемешать, добавить муку, еще раз перемешать. Жарить кабачковые оладьи с сыром на масле до коричневой корочки, подавать со сметанным соусом и порубленной зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6670,'Разболтать в теплом молоке дрожжи, добавить через 5 минут подсоленную муку, сахар, мягкое масло, ведерко со смесью поставить в хлебопечку на режим «замес теста», дать тесту подойти, разделить на 7 шариков, прикрыть их полотенцем, дать постоять минут 15. Присыпать стол мукой, раскатать из шарика круг, загнуть край теста от края к центр, повторить, только загибать тесто снизу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6670,'Раскатать в полосу шириной чуть больше бекона, надрезать длинный край через каждый сантиметр. Уложить на тесто ломтик бекона и соломку из сыра, свернуть в трубочку, чтобы получился цветок, повторить все с остатками теста. Промазать маслом форму, заполнить «цветами», прикрыть пленкой, дать подойти. Выпекать пирог «Цветы» с сыром и беконом примерно 45 минут в духовке с температурой 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6671,'Подготовить высокую форму, смазать ее маслом, уложить на дно макароны, на них – нарезанный карбонад (колбасу или ветчину), по вкусу добавить специи, поперчить. Молоко подсолить, добавить воды (можно и без нее), но пропорцию жидкость-макароны необходимо выдержать, залить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6671,'Присыпать верх запеканки крупно тертым сыром, форму хорошо «запаковать» фольгой. Выпекать запеканку «Ленивая»  полчаса на большом огне, осторожно удалить фольгу, продолжить выпекать еще минут 20, дать блюду чуть остыть и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6672,'Сварить яйца в крутую, морковь натереть, орехи порубить, перемешать орехи и морковь с майонезом, подсолить. Уложить на плоское блюдо вафельный лист, нанести майонезную сеточку, уложить размятую вилкой рыбу, прикрыть вторым коржом. Нанести опять майонезную сеточку, уложить морковную смесь, смазать майонезом, прикрыть вафельным коржом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6672,'Нанести на него майонез, присыпать тертым яйцом и порубленной зеленью, чуть присолить, закрыть коржом. Смазать его майонезом, присыпать сырной стружкой.  Закусочный торт с сыром и скумбрией можно приготовить без майонеза, заменив его на смесь йогурта с горчицей, в морковку можно добавит тертый чесночный зубчик. Убрать торт в холодильник на пару часов, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Далее смазать булочки яичным желтком и запечь их в течение 15 минут в духовке при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6673,'Слегка подогреть молоко, залить дрожжи, добавив немного сахара, дать подойти. Яйца взбить, добавить мягкий маргарин и сахар, перемешать. В тазик для замешивания теста вылить дрожжи, добавить смесь яиц с маргарином, хорошо перемешать. Добавить часть подсоленной муки, перемешать, добавить смесь муки и воды (клейковина), всыпать остатки муки, тщательно вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6673,'Дать тесту подойти в тепле, приготовить начинку из размягченного в микроволновке маргарина и смеси корицы с коричневым сахаром. Из теста раскатать прямоугольный пласт, смазать растопленным маргарином, присыпать начинкой, скатать с усилием в трубочку, разрезать на кусочки. Выпекать домашние булочки с корицей около получаса при температуре 175 градусов. Для крема смешать мягкое масло со сливочным сыром и пудрой, смазать им булочки, украсить по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6674,'Включить для прогрева до 180 градусов духовку, взбить масло и сахар до побеления, ввести по одному желтки, влить кофе, ванильный сахар, перемешать, просеять в смесь муку в смеси с какао и разрыхлителем, тщательно перемешать. Взбить в крепкую пену белки с сахаром и солью, осторожно смешать с тестом, заполнить массой форму, смазанную маслом, выпекать бисквит до готовности, вынуть из формы, проколоть в нескольких местах зубочисткой, пропитать крепким кофе, дать окончательно остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6674,'Закипятить молоко, смешать сахар с желтками, крахмалом и кофе, залить молоком, варить пока не загустеет, дать крему остыть, смешать с ликером и раствором желатина. Взбить сливки до состояния крепкой пены, перемешать с кремом, в отдельной емкости взбить белки и пару ложек сахара до пиков, аккуратно перемешать с кремом. Корж переложить опять форму, залить кофейный торт-мусс кремом, убрать его на ночь в холодильник, провести ножом вдоль бортика и осторожно вынуть торт из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6675,'Лук нашинковать кубиками, кабачок порезать кубиками, обжарить на масле, подсолить, дать остыть, подготовить перцы для фарширования, срезать донце, убрать семена. Перемешать фарш с кабачками и рисом, добавить один перчик, порезанный на кубики, подсолить, поперчить, хорошо перемешать, заполнить перцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6675,'Приготовить зажарку из тертой моркови и лука, добавить перец, готовить до мягкости, добавить томатный сок, подсолить, поперчить, добавить лавровые листики, дать закипеть, вылить к перцам. Поставить фаршированный болгарский перец с мясной начинкой тушится на медленном огне около 50 минут, перед подачей готовые перцы посыпать порубленной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Для приготовления теста взбить масло с сахаром, добавить расплавленный шоколад, перемешать, добавить по одному желтки, взбить в пушистую светлую массу. Оставшиеся белки взбить с сахаром в гладкую массу, просеять смесь муки, разрыхлителя и соли. В шоколадную массу порциями добавить муку, чередуя ее с белками, аккуратно перемешать лопаточкой снизу вверх, чтобы смесь не потеряла пышности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Заполнить тестом смазанную маслом форму, обернуть ее несколькими слоями фольги, чтобы края сильно не подсыхали, выпекать порядка 40 минут при температуре 180 градусов. Слегка остудить корж, вынуть из формы, дать окончательно остыть на решетке, разрезать на три части, пропитать ромом, обернуть каждый в пленку, убрать в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Для приготовления карамели в сотейнике с толстым дном растопить сахар, добавить горячие сливки, через 30 секунд размешать, добавить соль, масло, проварить минут 5, дать остыть, перелить в миску, оставить до следующего дня. Для приготовления меренги перемешать сахар и белки, прогреть их на среднем огне на водяной бане, мешая венчиком, чтобы растворился сахар, взбивать дальше до пышной устойчивой пены, окончательно взбить в комбайне до глянцевого состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Разогреть духовку до 100 г, на силиконовый коврик выложить 2 коржа примерно по 20 см в диаметре, поставить в духовку, температуру понизить до 70 градусов, выпекать (подсушивать) 1,5 часа до образования сухой корочки, дать остыть. Для крема порубить слегка обжаренный арахис, сгущенку взбить с маслом до пышного состояния, перемешать с орехами, делать непосредственно перед сборкой торта «Сникерс», чтобы крем сильно не застыл в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Сделать в блендере из отварной фасоли пюре, добавить измельченный зубок чеснока и специи, поперчить, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Смешать две порции карамели примерно по 120 г с 40 г пасты из арахиса, каждую аккуратно и равномерно нанести на корж, сильно не давить, иначе коржи расплющатся, присыпать тертым шоколадом, прикрыть меренговыми коржами. Отложить 200 г крема, остаток разделить пополам. Смазать меренговый корж, прикрыть коржом с бисквитом карамелью и меренгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6676,'Осторожно смазать кремом, прикрыть третьим коржом, смазать его и бока торта остатками крема с пастой из арахиса. Для приготовления глазури перемешать какао и сахарную пудру, просеять смесь в сотейник, влить молоко, добавить масло, прогреть, перемешивая до однородности, слегка остудить, залить верх торта, далее оформить по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6677,'Порезать охлажденное масло на кубики, просеять подсоленную муку, перетереть их в крошку, вбить яйцо, тщательно перемешать, всыпать натертый сыр, быстро вымесить тесто, обернуть в пленку, убрать на час в холодильник. Достать колобок, раскатать в пласт, вырезать любыми формочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6677,'Выстлать пергаментом противень, уложить печенье, смазать верх каждого желтком, разболтанным с небольшим количеством воды, присыпать семенем кунжута. Наколоть сырное печенье в нескольких местах вилкой, выпекать около четверти часа при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6678,'Порезать на кусочки по 5 мм 2/3 палочек, порубить обжаренный арахис, перемешать их. Добавить сгущенку (вареную) и растопленное масло, вымешать до однородности. Переложить десерт в форму, выстланную пергаментом, поставить в холодильник на пару-тройку часов, а лучше на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6679,'Обжарить полукольца лука до зарумянивания, добавить кусочки грибов, довести до готовности, дать остыть. Порезать маленькими кубиками перец, яйца, ветчину, сыр, перемешать с грибами. Заправить майонезом, перемешать, оформить зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6680,'Порезать все ингредиенты маленькими кубиками, нашинковать зеленый лук, всыпать сцеженный горошек, заправить салат майонезом, подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6681,'Удалить из окорочка кости, разобрать на волокна, порезать лук маленькими кубиками, обдать кипятком, картофель нарезать тоже кубиками. Порубить яйца, сыр крупно натереть, все перемешать, добавить кукурузу без жидкости. Добавить в ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6682,'Натереть крупно свеклу и сыр, чеснок раздавить прессом, добавить кусочки кальмаров, подсолить. Заправить майонезом, дать постоять, оформить веточками зелени, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6683,'Сварить креветки, сыр, яйца и помидоры без семян порезать на маленькие кубики, нарезать на кусочки семгу, посолить и все перемешать. Добавить в салат «Коралл» майонез, аккуратно перемешать, переложить в салатницу, украсить розочками из семги и веточками укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6684,'Порезать овощи и яйца на маленькие кубики, крабовые палочки – кусочками. Перемешать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6685,'Курицу, яйца, огурцы порезать кубиками, морковку по-корейски на кусочки, сыр крупно потереть. Все перемешать, посолить, заправить майонезом, еще раз перемешать, выложить горкой в салатницу, посыпать нашинкованным зеленым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6686,'Отварить грудку, дать остыть в бульоне, порезать кубиками, яйца мелко порубить, натереть крупно сыр, отдельно – отварную морковь, чеснок раздавить прессом или очень мелко натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6686,'Перемешать рис с морковью, яйцами, мясом, всыпать сыр, добавить чеснок, подсолить, заправить салат «Неженка» майонезом. На плоское блюдо поставить кулинарное кольцо, заполнить салатом и убрать его, оформить верх салата зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6687,'Разрезать помидоры, удалить семена, порезать на кубики, порубить яйца, зеленый лук нашинковать. Курицу порезать кубиками, смешать с другими ингредиентами, добавить горошек, заправить салат смесью сметаны и майонеза, украсить по вкусу, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6688,'На плоскую тарелку выложить слои в следующем порядке: рис, сыр, рыба, белки, огурец, желтки. Каждый слой салата смазать майонезом, украсить, дать постоять пару часов, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6699,'Когда пройдет отведенное время, замариновавшиеся куски мяса следует достать из маринада и выложить их в форму, в которой они будут запекаться, сверху уложить пару кусочков лимона и слегка промазать курицу сметаной, необходимо накрыть все крышкой либо фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Посыпать печенье овсяными хлопьями, прижать ладонью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6689,'В чашу комбайна поместить просеянную муку, добавить масло, сахар, яйцо, перемешать до получения крошки на большой скорости, переложить на стол быстро вымесить, обернуть в пленку, на час убрать в холодильник. Включить для разогрева до 180 градусов духовку, тесто положить на стол, присыпанный мукой, несколько минут помять, раскатать в пласт около 3 мм толщины, вырезать разными формочками печенье.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6689,'Выстлать противень пергаментной бумагой, разложить новогоднее печенье, дать постоять четверть часа, поместить в духовку с подходящей для выпечки температурой, выпекать до золотистости около 10-15 минут, дать остыть на решетке, украсить по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6690,'Для приготовления крема необходимо смешать в небольшой кастрюльке яйца, муку, молоко, ванильный и простой сахар, отправить кастрюлю на огонь, дать массе загустеть, затем добавить в нее масло, убрать с огня и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6690,'Для теста нужно со сгущенным молоком соединить муку, гашеную уксусом соду и яйцо, перемешать и вымесить эластичное тесто, которое затем разделить на несколько кусочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6690,'Подготовленные куски теста раскатать по форме сковороды, затем наколоть вилкой и обжарить на сковороде с обеих сторон без использования масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6690,'Теплые коржи следует обрезать, придав всем одинаковую и ровную форму, каждый корж промазать приготовленным кремом, последний слой посыпать крошками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6690,'Готовый торт домашний на сковороде с заварным кремом поставить в холодильник на два часа, затем подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6691,'Куриное филе нарезать кусочками среднего размера. Выложить мясо в кастрюлю с толстым дном, залить водой так, чтобы она покрыла продукт на два пальца. Тушить на тихом огне в течение часа. Ошпарить и очистить помидоры от кожицы. Нарезать репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6691,'Овощи переложить в кастрюлю с капустой. Натереть морковь, нарезать баклажаны кубиками и красный сладкий болгарский перец кусочками. То и другое также положить в кастрюлю. Затем всыпать рубленую зелень и зубчики чеснока. Потушить рагу из овощей с куриным филе до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6692,'Отварить куриную грудку. Промыть гречневую крупу. Нашинковать морковь соломкой, нарезать репчатый лук, овощи обжарить на сковороде на оливковом масле. Нарезать соломкой очищенный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6692,'Добавить в куриный бульон гречку, варить до полуготовности в течение 15 минут. Добавить обжарку, через 10 минут – нарезанные помидоры и картошку. Варить гречневый суп до готовности картошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6693,'Аккуратно отделить желтки от белков. Белки взбить с несколькими каплями лимонного сока или со щепоткой соли. Взбить миксером белки в пену, сахарный песок всыпать порциями. Добавить пищевой кондитерский краситель зеленого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6693,'Застелить противень бумагой, выдавить первый слой для елочек-безе, затем второй и третий. Украсить цветной посыпкой, поставить изделия в духовой шкаф на полтора часа. Температура выпекания – 120 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6694,'Вымыть куриное филе, залить водой и довести до кипения на сильном огне. Огонь уменьшить, пенку снять, посолить по вкусу, варить в течение 20 минут, до готовности. Филе вынуть, остудить и нарезать кусочками в полтора сантиметра в ширину. Для приготовления заправки очистить и измельчить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6694,'Оливковое масло взбить с чесноком, горчицей, лимонным соком. Бульон еще раз довести до кипения, выложить свежемороженую зеленую фасоль, готовить до мягкости около семи минут. Отбросить на дуршлаг. Отварить яйца «в мешочек» в течение пяти минут. Обдать холодной водой, очистить, разрезать на половинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6694,'Помидоры черри также разрезать пополам, маслины – кружочками. Положить в миску вымытый и обсушенный салат руккола, помидоры и фасоль, влить часть заправки и перемешать. Добавить нарезанные маслины, перемешать еще раз. Готовый салат «Нисуаз» с курицей разложить в тарелки, сверху – яйца и кусочки курицы. Полить оставшейся заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6699,'Форму поставить в духовку с температурой 200 градусов примерно на 20 минут, затем понизить температуру до 175 градусов и запекать еще где-то 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6699,'Курица в медовом маринаде запеченная с лимоном, подается с картофелем, зеленью и дольками лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6695,'Картофель вымыть под проточной водой, отварить в мундире в течение 25 минут. Подержать клубни в холодной воде. Снять кожуру, нарезать мякоть кубиками. У зеленой фасоли отрезать кончики, опустить в кипяток, подсолить. Варить в течение двух или трех минут, до полуготовности. Откинуть продукт на дуршлаг, залить охлажденной водой. Этот нехитрый прием позволит сохранить яркий зеленый цвет фасоли. Сладкий болгарский перец запечь в духовке, температура приготовления – 200 градусов. На овощах должны появиться подпалины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6695,'Переложить перец на 10 минут в полиэтиленовый пакет, закрыть. Снять кожицу, удалить семенные камеры. Мякоть нарезать кубиками, помидоры – кольцами. Положить сырые яйца в холодную воду, дождаться закипания, варить 10 минут. Переложить в холодную воду, затем очистить и разрезать каждое яйцо на четыре части. Консервированного тунца выложить на бумажные полотенца, чтобы удалить лишнее масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6695,'Для заправки нарезать очищенный чеснок, перемешать его с белым винным уксусом, молотым черным перцем и солью по вкусу. Оливковое масло влить тонкой струйкой, взбивать венчиком. Должна получиться смесь, похожая на эмульсию. Выложить на тарелки вымытые листья зеленого салата, сверху – картофель, фасоль, перец, помидоры, рыба и яйца. Украсить маслинами без косточек и анчоусами. Полить салат «Нисуаз» с тунцом соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6696,'Обычные помидоры нарезать крупными кусочками. Посолить и поперчить, посыпать свежим нарезанным базиликом, тертой цедрой лимона, полить оливковым маслом, оставить для маринования. Картофель очистить и нарезать крупными кусками, отварить в подсоленной воде до готовности, но не переваривать. Слить воду. Две или три ложки оливкового масла разогреть, обжарить картофель до появления румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6696,'Свежую или мороженую фасоль отварить в течение нескольких минут, она должна остаться хрустящей. Отжать, обжарить на той же сковороде, где готовился картофель. В кипяток добавить соль, перец-горошек, любую зелень. Варить филе лосося в течение нескольких минут. Маленькие кофейные чашечки смазать сливочным маслом, влить яйца. Поставить емкости в кастрюлю с кипящей водой, варить до готовности. Яйца вынуть и разрезать каждое на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6696,'Для заправки вбить в посудину желток. Добавить горчицу, соль, перец, растительное масло добавлять порциями, взбивать миксером на большой скорости. В готовую массу добавить уксус. Если майонез получился слишком густым, то можно добавить немного кипяченой воды. Всыпать сушеный или свежий эстрагон, перемешать. На тарелку выложить листья салата, полить частью соуса, выложить картофель, фасоль, оливки, помидоры, яйца. Лосося поломать кусочками и выложить сверху, полить оставшимся соусом и подать салат «Нисуаз» с лососем на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6697,'В подогретой воде нужно размешать сахарный песок, натуральный мед, соль и растительное масло хорошего качества, без запаха. Пшеничную муку просеять отдельно вместе с пищевой содой, добавить в смесь, перемешать. Курагу промыть и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6697,'Формочку для кекса смазать маслом и посыпать мукой. Выложить тесто, печь до золотистого цвета, температура – 180 градусов. Готовность медового кекс с курагой можно проверить с помощью зубочистки. Кекс немного остудить, переложить на блюдо и посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6698,'Небольшие яблоки очистить от кожицы и натереть на мелкой терке. Отдельно перемешать заранее просеянную муку, разрыхлитель, соль и сахар. Яблочную массу перемешать с кипяченой водой и растительным маслом. Постепенно, порциями, всыпать муку, тесто помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6698,'Добавить сушеную клюкву, еще раз осторожно перемешать. Готовое тесто выложить в формочки, смазанные маслом или выстеленные бумагой. Печь постные кексики в течение получаса или чуть больше, до золотистой корочки, температура – до 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6699,'Курицу порезать на куски, смазать солью и смесью перцев, уложить их в емкость, залить растопленным медом, разложить крупные ломтики лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6699,'Все хорошенько перемешать, при этом нужно посильнее надавливать на лимонные ломтики, отставить в сторону на 40 минут, чтобы мясо промариновалось.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Когда булочки будут готовы, нужно их накрыть полотенцем и не доставать еще 10-15 минут, а по истечении данного времени украсить с помощью сахарной пудры.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6700,'Бананы очистить и размять вилкой, они должны быть очень спелыми. Хорошо перемешать с сахаром и растительным маслом. Всыпать муку, молотую корицу или микс специй для выпечки, разрыхлитель. Хорошо перемешать, можно добавить молотые орехи или изюм. Форму для выпекания смазать маслом, печь в течение 40 минут. Если банановый кекс начнет подгорать – накрыть фольгой. Остудить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6701,'Форму для выпекания прямоугольной формы смазать растительным маслом, посыпать мукой. Отдельно, в миске, перемешать семена льна с теплой водой. Дать постоять в течение пяти минут. Перемешать сахар с мукой, пшеничной или цельнозерновой, солью, пищевой содой, разрыхлителем и специями – корицей, мускатным орехом, гвоздикой и имбирем. Столовую ложку полученной смеси добавить в изюм и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6701,'Воду с маслом соединить, влить полученную жидкость в сухие ингредиенты и перемешать. Всыпать тертую морковь, изюм, нарезанную кубиками мякоть ананаса, яблока или банана. Тесто вылить в подготовленную форму. Время выпекания – от 45 до 55 минут. Готовность проверить спичкой или зубочисткой. Постный морковный кекс остудить на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6702,'Готовый вишневый сироп перемешать с растительным маслом и теплой водой. Всыпать пшеничную муку, ванильный сахар из пакетика, разрыхлитель и молотую корицу. Перемешать массу до однородного состояния, добавить свежую или размороженную вишню. Форму смазать маслом, выложить тесто, печь в течение 35 минут, температура приготовления – 180 градусов. Готовый кекс с вишней посыпать сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6703,'Очистить миндаль, бланшировать фундук. Орехи обжарить на сковороде до золотистого цвета. В посуду с толстым дном положить мед и сахарный песок, прогреть на среднем огне, должен получиться сироп. Варить на среднем огне до густоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6703,'Какао-порошок и муку просеять в миску, добавить сухофрукты и орехи, смесь корицы, кардамона, душистого перца, муската. Перемешать, полить горячим сиропом, перемешать еще раз. Форму среднего размера выстелить бумагой, перелить тесто, печь пряник «Панфорте» в течение 45 минут при температуре 160 градусов. Готовый пирог остудить, посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6704,'Куриную грудку отварить до готовности в подсоленной воде в течение получаса. Бульон, оставшийся после варки, можно заморозить и использовать в дальнейшем для приготовления супа. Капусту брокколи разделить на соцветия, варить в подсоленной воде в течение пяти – семи минут до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6704,'Мясо отделить от костей, нарезать небольшими кусочками. Мелко накрошить белый репчатый лук, по желанию продукт можно спассеровать на растительном масле. Перемешать курицу, лук и брокколи в форме для запекания, досолить и поперчить по вкусу. Натереть сыр на крупной терке, перемешать его со сливками, жирным молоком или сметаной, разбавленной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6704,'Залить овощи и мясо полученной смесью. Печь куриное филе с брокколи под соусом в духовом шкафу в течение 20 минут, температура – от 170 до 180 градусов. Должна получиться аппетитная корочка. Подать блюдо в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6705,'Молодую, не слишком большого размера, тушку утки вымыть, отрезать кончики крыльев, удалить кожу на шее и жир возле хвоста, выпотрошить. Для маринада в большой емкости перемешать соль с черным молотым перцем, сушеным розмарином и орегано. Влить яблочный уксус и оливковое масло. В полученную смесь переложить утку, закрыть крышкой, оставить на четыре-пять часов при комнатной температуре, можно – на ночь в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6705,'За время пропитывания тушку лучше несколько раз перевернуть. Яблоки среднего размера разрезать на четвертинки, серединки удалить. Три-четыре дольки оставить, остальные выложить в миску, посолить и поперчить, сбрызнуть растительным маслом и перемешать. Маринованную утку вынуть, выложить в смазанную растительным маслом форму для запекания. Можно использовать специальную форму с решеткой внутри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6709,'Куриное филе нарезать на кусочки среднего размера. Натереть очищенную и вымытую морковь, репчатый лук нарезать кубиками. Обжарить на масле мясо в течение трех-пяти минут, огонь–сильный, продукт помешивать. Отдельно обжарить лук, он должен стать мягким, добавить морковь, потушить все вместе несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Постелить на противень специальную бумагу, смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6705,'Начинить тушку яблоками, по желанию добавить четверть луковицу и половину морковки. Остатки яблок выложить в форму возле утки. Поставить птицу в духовой шкаф, температура приготовления – 190 градусов, время запекания – по полчаса на каждые полкилограмма мяса. Во второй, по времени, половине запекания утку поливать выделившимся соком со дна формы. Из готовой тушки вынуть запеченные яблоки и нарезать ломтиками среднего размера, их можно использовать как гарнир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6705,'В кастрюлю небольшого размера с толстым дном или в сотейник подлить немного жира из формы, положить яблоки из утки, молотую корицу и коричневый сахар. По желанию добавить изюм без косточек. Прогреть ингредиенты на сильном огне в течение пяти минут. Яблоки должны стать коричневатыми, карамель образует очень приятный вкус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6705,'Готовый гарнир можно обратно положить в тушку или подать отдельно. Еще один вариант: к запеченным яблокам добавить вареный рис, булгур или приготовленный кускус. Запекать утку с апельсинами и яблоками можно и со смесью яблок и апельсинов, нарезанных крупными дольками вместе с кожурой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6706,'Разогреть на сковороде растительное масло, обжарить на нем нарезанный кольцами, полукольцами или произвольно репчатый лук. Сырое куриное филе нарезать также произвольно, любой толщины и длины. Мясо посолить и поперчить, посыпать приправой для курицы и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6706,'Открыть банку с маринованными шампиньонами, маринад слить. Грибы нарезать, добавить к снятой с плиты курице, перемешать. Отдельно, в миске, взбить сырые куриные яйца, влить сливки, всыпать тертый сыр и нашинкованную зелень. Соль и перец – по вкусу, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6706,'Слоеное тесто, купленное в магазине, разморозить, раскатать по размеру формы для выпекания. Форму смазать растительным маслом, выложить лепешку так, чтобы получились невысокие бортики. Всыпать куриную начинку с грибами, утрамбовать. Сверху полить яичной массой и прикрыть края тестом. Печь пирог с куриной грудкой и шампиньонами при температуре 200 градусов в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6707,'Для приготовления опары перемешать подогретое молоко с небольшим количеством муки, сахаром и содержимым пакетика с быстрорастворимыми дрожжами. Смесь перемешать и дать постоять в тепле в течение 15 минут. Для теста добавить в готовую опару треть стакана растительного масла и соль. Муку всыпать постепенно, порциями. Замесить руками мягкое тесто, оно не должно липнуть к рукам, но и не должно быть излишне тугим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6707,'Плотность массы регулировать по своим ощущениям. Накрыть массу увлажненным полотенцем, поставить в тепло на 15 минут, оно должно подняться. Если время есть – расстойку можно увеличить до часа. Готовое дрожжевое тесто немного обмять и использовать для приготовления пирогов и пирожков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6708,'Для приготовления теста смешать в миске обезжиренный творог с растопленным сливочным маслом, добавить сахарный песок, соль, ванильный сахар из пакетика. Отдельно перемешать просеянную муку с разрыхлителем. Добавить мучную смесь к творожной, замесить. Дно формы застелить бумагой для выпекания, края самой формы смазать маслом. Выложить тесто, разровнять руками. Форму поставить в холодильник на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6708,'Для приготовления вишневой начинки можно использовать свежую, размороженную или консервированную вишню из сиропа. Косточки вынуть. Взбить размягченное сливочное масло и половину нормы сахарного песка, добавить сок лимона и ванильный сахар. Массу еще раз взбить. Отделить белки от желтков. Желтки перемешать с начинкой и добавить обезжиренный творог. Отдельно перемешать картофельный крахмал с мукой и разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6708,'Добавить в творожную начинку, перемешать. Сырые белки взбить с остатками сахарного песка в плотную пену, также вмешать в начинку. Охлажденную форму вынуть из холодильника, выложить на тесто половину творога, вишню, слои повторить. Для украшения пирога смешать до образования крошки муку, миндаль, сахар и мягкое сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6708,'Насыпать на поверхность будущей выпечки ровным слоем. Печь в течение 40 минут при температуре 160 градусов. Чтобы блюдо не подгорело, последние 20 минут пирог лучше печь под листом фольги. Остудить чизкейк с вишней в духовке в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6709,'В воду всыпать муку, влить сметану и майонез, хмели-сунели, молотую паприку, соль и сахарный песок. Ингредиенты перемешать, довести смесь до кипения, добавить обжарку и мясо. Тушить массу на тихом огне в течение 10 минут. В конце приготовления куриного филе в сметане добавить рубленую зелень и измельченный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6710,'Пекинскую капусту или любой листовой салат мелко нарезать. Отварить курицу, филе нарезать мелкими кусочками, сладкий болгарский перец – небольшими кубиками. Отцедить от жидкости зеленый горошек, всыпать в миску с салатом. Следующие ингредиенты – отваренное и измельченное куриное яйцо, нарезанный репчатый лук сладкого сорта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6710,'Все составляющие перемешать, посолить по вкусу и заправить майонезом. Выложить массу в салатницу, верх разровнять. Нарезать помидоры небольшими кусочками, посолить и посыпать нарезанной зеленью укропа. Выложить ими верхний слой салата «Красная шапочка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6711,'Из чернослива вынуть косточки, залить мякоть кипящей водой и оставить на час или полтора для набухания. Мандарины очистить от пленок и кожуры, поделить на дольки. Сырое куриное филе разрезать вдоль пополам. Куски выложить на разделочную доску с пищевой пленкой внахлест, хорошо отбить. Продукт посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6711,'Очищенные грецкие орехи порубить острым ножом или перемолоть с помощью блендера. Половиной крошек посыпать отбитое мясо. На ореховый слой выложить чернослив, целый или нарезанный. Следующий слой – дольки мандаринов, орехи. Нафаршированное филе скрутить в рулет, ровный и плотный. Концы пленки туго затянуть, чтобы она не развернулась во время приготовления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6711,'Переложить продукт в пароварку или в дуршлаг, поставленный на кастрюлю с умеренно кипящей водой. Сверху рулет накрыть крышкой, варить еще тридцать пять или сорок минут. Готовую закуску вынуть, остудить, удалить пленку. Куриный рулет с мандаринами нарезать ломтиками толщиной в полтора сантиметра, наискосок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6712,'Отварить в кожуре клубни картофеля, морковь. Ингредиенты остудить, очистить, отварить яйца. Картофель и морковь нарезать мелкими кубиками. Белки мелко порубить. Перемешать продукты в миске вместе с кубиками свежего огурца, вареной колбасы или сосисок. Заправить массу майонезом, при необходимости посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6712,'На большом плоском блюде выложить силуэт петуха, присыпать его тертым желтком. Выложить из кусочков помидоров гребешок, бородку, клюв, глаз – из перца. Крыло и хвост сделать из того же помидора, полосок болгарского перца и зелени. Травку сделать из зелени петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'Муку, корицу, крахмал и соль смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'Начать взбивать сахар вместе с яйцами, а когда объем массы слегка увеличится и сама она станет чуть светлее — перестать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'В яично-сахарную смесь постепенно всыпать мучную, продолжать взбивать до однородной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'Опрыснуть маслом растительным, мукой присыпать разъемную форму для запекания, на дно выложить пластинки яблок, залить все приготовленным тестом так, чтобы фрукты были полностью покрыты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'Форму поставить в духовку, разогретую до 180 градусов, выпекать в районе 40 минут до подрумянивания верха, готовность проверить с помощью спички или зубочистки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6713,'Когда шарлотка с яблоками по-домашнему в духовке немного остынет, форму нужно снять и украсить верх пирога сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6714,'Для приготовления опары в чашу миксера просеять немного муки, добавить свежие дрожжи и воду. Быстро, в течение двух минут, замесить тесто, оно должно быть липким. Массу накрыть крышкой и оставить на час в тепле. В подошедшую опару добавить яйца, оставшуюся муку, сахарный песок и соль. Замесить тесто в течение восьми минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6714,'В конце приготовления влить растопленное сливочное масло, продолжать мешать две минуты. На этом этапе масса должна быть мягкой, но гладкой. Накрыть продукт, поставить в тепло на полчаса, а затем на час в холодильник. По желанию тесто в холоде можно оставить на ночь. Раскатать массу в лепешку толщиной в один сантиметр. Вырезать круги при помощи формочек, в середине каждого – отверстие, сделанное с помощью формочек меньшего диаметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Смешать йогурт и рубленую зелень, заправить перцем, посолить и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6714,'Оставить заготовки на расстойку на 45 минут. Разогреть в сковороде растительное масло, должны пойти пузырьки. Жарить пончики с двух сторон, по полминуты, до получения золотистого цвета. Выложить готовые бублики на бумажное полотенце для впитывания лишнего жира. Посыпать изделия сахарной пудрой или полить шоколадной глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6714,'Для приготовления шоколадной глазури плитку нужно поломать кусочками, залить жирными сливками и прогреть на огне до растворения шоколада. Можно приготовить глазурь из сгущенного молока: обычное молоко прогреть и смешать со сгущенным. Пончики «Донатс» с глазурью из белого шоколада: продукт поломать кусочками, залить сливками и прогреть до растворения шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6715,'Сырые куриные яйца взбить, поджарить два яичных блина. Остудить, нарезать тонкой соломкой. Так же, соломкой, нарезать свежие огурцы, размороженные крабовые палочки. Сыр сулугуни нарезать частями, чтобы получилась соломка средней длины. Все ингредиенты перемешать и заправить по вкусу майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6716,'Хорошо охлажденное куриное филе нарезать кубиками. Добавить сырые куриные яйца, майонез, всыпать картофельный крахмал, молотый черный перец, соль, рубленую зелень и нарезанный кубиками плавленый сыр. Ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6716,'На сковороду налить растительное масло, прогреть, массу из курицы и сыра выкладывать в виде котлет. Подрумянить, перевернуть на другую сторону. Жарить куриные котлетки с сыром недолго, в течение нескольких минут, не пересушивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6717,'Сухой творог размять, добавить сырое куриное яйцо, манную крупу. Массу разделить на равные порции. Сформовать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6718,'Яблоко большого размера очистить и натереть на терке. Добавить в миску творог, кефир, сметану, все хорошо перемешать. Следующие ингредиенты – большое яйцо, сахарный песок, ром, цедра лимона, соль по вкусу, молотая корица, несколько капель ванильной эссенции. Пшеничную муку просеять вместе с разрыхлителем, добавить в остальную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6718,'Тесто должно получиться не очень густым, липким. Перемешивать ингредиенты можно вилкой. Большое количество растительного масла разогреть на сковороде. Пончики небольшого размера, с грецкий орех, выкладывать двумя чайными ложками. Жарить пышные пончики с яблоком на несильном огне, с каждой стороны по две-три минуты. Выложить на бумажные полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6719,'Поставить на огонь сковороду, растопить ложку сливочного масла. Дно застелить лавашем, края лепешки должны свисать. Разбить сверху яйца, посолить, поперчить, посыпать тертым сыром сулугуни. Края аккуратно завернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6719,'Жарить на тихом огне в течение двух минут, когда появится корочка – перевернуть на другую сторону при помощи лопатки. Еще раз посыпать изделие сыром, накрыть крышкой, прогреть три-четыре минуты. Выложить яичницу с сыром в лаваше на блюдо, нарезать кусочками и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6720,'Творог не должен быть влажным, если он мокрый, его лучше подвесить в марле над емкостью, чтобы стекла лишняя жидкость. Протереть продукт через сито, крупинки удалить. Перемешать с мукой, сметаной и половиной сырого желтка, сахаром или сахарной пудрой. Дать немного постоять. Перемешивать лучше ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6720,'Для приготовления теста положить в миску размягченное сливочное масло, сырое яйцо, сахарную пудру и соль, все вместе взбить до гладкости. Большую часть муки перемешать с разрыхлителем. Всыпать смесь небольшими порциями в масло, перемешивать лопаткой и руками. Должно получиться мягкое и эластичное тесто. Всыпать остаток муки, скатать колобок, дать постоять 15–20 минут. Готовое тесто поделить на кусочки по 35–40 грамм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6720,'Каждый кусочек раскатать в колбаску, а затем в овальную лепешку. Стол присыпать мукой, чтобы тесто не прилипало. Выложить начинку, накрыть второй половиной, не защипывать. Противень смазать маслом. Выложить нежнейшие сочники, смазать желтком, растворенным в воде, использовать кулинарную кисточку. Время выпекания – от 17 до 20 минут, температура – 200 градусов. Время и температура зависят от возможностей духового шкафа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6751,'На каждый кусок мяса выложить подготовленную смесь, куриное филе запечь с сыром и грибами в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Нагреть в кастрюле масло, положить лук с морковью. Обжаривать минут 5, пока лук не будет прозрачным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6721,'Крабовые палочки разморозить и нарезать кусочками среднего размера. Нарезать кубиками свежие помидоры и яблоки, все ингредиенты перемешать. Отдельно отварить рис и добавить в салат, еще раз перемешать. Натереть твердый сыр, добавить в основную массу. В центр блюда поставить небольшую банку или стакан. Выложить салат, сформовать кольцо, прижать массу к стенкам банки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6721,'Нарезать зеленый лук и укроп, посыпать кольцо, оставшиеся веточки укропа выложить по кругу целиком. Из двух крабовых палочек сделать свечки: разрезать каждую пополам, с одной стороны сделать надрез вдоль. Из кусочка помидора вырезать «пламя», вставить в отверстие. Украсить свечками кольцо, посыпать салат «Рождественский венок» зеленым горошком и кусочками помидоров, овощи будут имитировать елочные игрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6722,'Щавель и шпинат промыть проточной водой. Залить кипяченой водой, варить несколько минут. Откинуть на дуршлаг, отцедить воду, взбить зеленую массу миксером в глубокой емкости. Влить заранее приготовленный мясной бульон. Болгарский перец нарезать кубиками, редис – кружочками, порубить зелень, выложить нарезанные яйца, сваренные вкрутую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6723,'Отварить яйца вкрутую, остудить, очистить. От консервированной трески отцедить масло. Зеленый лук вымыть и обсушить. От консервированного зеленого горошка слить жидкость. Маринованные огурцы нарезать кубиками, измельчить печень, лук и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6723,'Все ингредиенты перемешать, заправить майонезом, перемешать. Для украшения салата с печенью трески использовать листочки петрушки и четвертинки отваренных яиц.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6724,'На сковороде обжарить лук, затем добавить фарш, перец, соль и томатную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6724,'На крупной терке натереть кабачки, сок отжать, кружочками нарезать помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6724,'Сметану взбить с яйцами и солью, сыр крупно натереть на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6724,'Промазать маслом форму, уложить на дно половину подготовленных кабачков, затем фарш и снова кабачки, сверху выложить помидоры и вылить яично-сметанную смесь, все посыпать сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6724,'Мясная запеканка из кабачков с сыром и помидорами готовиться не дольше 35 минут в духовке при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6725,'Перемешать молотую овсянку и цельнозерновую муку, добавить стевию и разрыхлитель. В полученную смесь влить смесь яйца с обезжиренным кефиром. Лимон нарезать небольшими кусочками, вынуть косточки, мякоть и цедру измельчить при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6725,'Добавить полученную массу в тесто, сформовать печенье. Противень застелить пергаментом, выложить печенье. Время выпекания лимонного печенья – 15 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6726,'Свежемороженую сельдь подержать при комнатной температуре. Очистить репчатый лук, чеснок и морковь. Рыбу очистить от костей, нарезать кусочками. Залить уксусом, оставить на полчаса. Морковь натереть на терке, предназначенной для приготовления по-корейски, лук нарезать полукольцами, чеснок очистить и пропустить через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6726,'Отцедить филе, добавить к рыбе овощи, соевый соус, растительное масло, кунжут и соль по вкусу. Все ингредиенты хорошо перемешать, поставить сельдь «Хе» с морковью и луком на два часа в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6727,'Отварить куриные яйца, разрезать так, чтобы одна часть была больше на треть. Меньшая станет шляпкой, большая – ножкой. Вынуть желтки, выложить в отдельную миску. Заварить крепкий чай, положить в него шляпки, дать покипеть в течение 10 – 15 минут. На вкус яиц это никак не повлияет, но шляпки станут коричневыми.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6727,'Для приготовления начинки добавить в желтки майонез и печень трески, перемешать вилкой, нафаршировать ножки. Надеть шляпки, подать закуску «Грибочки» к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6728,'Отварить пасту в большой кастрюле с водой. На сковороде растопить сливочное масло, добавить оливковое. Очистить и раздавить чеснок, прогревать в масле минуту. Добавить очищенные креветки без хвостиков. Прогреть продукты в течение трех-пяти минут, переложить в другую посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6752,'Муку просеять, мягкое масло протереть с творогом в однородную массу, объединить с мукой (всыпать ее порциями), добавить соду, перемешать до образования эластичного и мягкого теста, прикрыть его тканью, дать постоять полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6728,'В сковороду положить томатную пасту или консервированные томаты, добавить красный и черный перец, соль, готовить на тихом огне в течение пяти минут, помешивать. В загустевший соус выложить промытую и отцеженную пасту, креветки. Перемешать пасту с креветками, попробовать, при необходимости досолить. Мелко нарезать зелень петрушки, посыпать пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6729,'Куриные грудки разрезать на пластинки. Приготовить рассол из воды, молока, соли. Замочить мясо на ночь. Грудки вынуть, обсушить, свернуть рулетом и перевязать веревкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6729,'Перемешать специи: молотую паприку, чили, жидкий натуральный мед, молотый кориандр, мускатный орех, куркуму, подлить соевый соус, оливковое масло, положить измельченный зубчик чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6729,'Обмазать смесью филе. Время запекания в духовке – полчаса, температура – 220 градусов. Остудить пастрому из куриной грудки в духовом шкафу, вынуть и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6730,'Бананы очистить и нарезать. Консервированные ананасы нарезать кусочками или кольцами, высыпать в кастрюлю вместе с жидкостью из банки. Добавить кокосовую стружку сахарный песок по вкусу, сок одного или двух лимонов. Все ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6730,'Довести до кипения, часто помешивать. Огонь уменьшить, варить 10 минут. Взбить при помощи блендера до однородности и уварить до нужной консистенции. Перелить банановое варенье в стерильные банки, хранить в холодильнике в течение месяца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6731,'Промыть куриное филе, обсушить с помощью бумажных полотенец. Неровные кусочки и жир удалить. Порезать филе по горизонтали на кусочки средней толщины. Отбить молотком. Для приготовления кляра взбить сырые куриные яйца, посолить, всыпать муку, подлить воду. Взбить венчиком, в смеси не должно быть комочков. Разогреть сковороду с растительным маслом. Обмакивать кусочки филе в кляр и жарить на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6732,'Рыбу очистить, вымыть. Залить холодной водой, поставить на огонь. Когда вода закипит – снять пену, бульон готовить на тихом огне в течение 20-25 минут. Готовое мясо отделить от костей, разделить на кусочки среднего размера. Нарезать небольшими кубиками репчатый лук, сладкий болгарский перец и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6732,'Подготовленные овощи обжарить на растительном масле. Очистить от кожуры клубни картофеля, также нарезать кубиками. В подготовленный бульон переложить картофель и овощи, довести суп до кипения, добавить нарезанный плавленый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6732,'Варить все вместе в течение 10 – 12 минут до мягкости картофеля. Вымыть и нарезать шпинат, добавить в кастрюлю вместе с рыбными кусочками, посолить и поперчить сырный суп по вкусу, всыпать молотую паприку. Через две минуты после закипания снять кастрюлю с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6733,'Соединить муку, гашеную соду и сахарозаменитель, перетереть руками в крошку. Для приготовления начинки творог перемешать с ванилью, сахарозаменителем и сырыми куриными яйцами. Застелить противень бумагой для выпекания, распределить тесто-крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6733,'Сверху выложить творожную массу, выровнять и посыпать крошкой. Отправить в духовой шкаф на полчаса, до появления румяной корочки. При подаче творожный пирог нарезать небольшими квадратиками. По желанию посыпать выпечку тертым шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6734,'Сливочное масло растопить и охладить. Плиточный шоколад порубить мелкими кубиками или использовать для приготовления готовые шоколадные капли. Отдельно, в чашке, соединить какао-порошок, пищевую соду, муку и сахарный песок. Добавить шоколад и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6734,'В другую емкость разбить куриные яйца, взбить венчиком. Подлить остывшее масло и перемешать. Очистить от кожуры спелые бананы, приготовить пюре с помощью вилки или блендером. Переложить в яйца, перемешать, всыпать сухую смесь с мукой, еще раз перемешать лопаткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6734,'Должно получиться однородное тесто, без комков. Форму для выпекания смазать маслом, выложить массу, поставить в духовой шкаф для выпекания. Время приготовления – до одного часа, температура – до 180 градусов. Шоколадно-банановый кекс вынуть, дать немного остыть и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6758,'Пластины лаваша порезать нарезать по размерам сковороды,  разогреть на среднем огне сковороду со сливочным маслом. Кусочки лаваша обмакнуть в миску с подсоленной водой, дать ей стечь, выложить на сковороду, дать подрумяниться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6735,'Лимоны хорошо вымыть и высушить. Срезать цедру с помощью ножа для чистки овощей, залить кожуру спиртом, плотно закрыть и поставить в темное и прохладное место. В течение десяти дней настойку встряхивать. Затем приготовить сахарный сироп. Всыпать песок в кастрюлю, добавить воду, прогревать на тихом огне до растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6735,'Снять с плиты, остудить. Лимонную настойку процедить через сито. Вылить в сироп, перемешать, разлить в бутылки с помощью воронки, дать постоять еще пять дней. Поставить лимончелло в морозильную камеру, употреблять через сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6736,'Отварить пасту до полуготовности в течение семи – девяти минут. Нарезать репчатый лук и чеснок, полосками – бекон. Натереть твердый сыр. Взбить вилкой желтки, добавить сухие травы, сливки и соль. Сковороду нагреть, влить оливковое масло, обжарить чеснок и лук до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6736,'Положить бекон, жарить все вместе еще две – три минуты. Влить сливки со специями, смесь довести до кипения, всыпать сыр, перемешать. Выложить на пасту «Карбонара» с беконом часть соуса, посыпать дополнительной порцией сыра и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6737,'Перемешать соевый соус с медом и томатной пастой. Смесь хорошо перемешать и прокипятить. Обмакнуть в нее курицу, нарезанную на кусочки, со всех сторон. Готовить мясо на противне или гриле, жарить до образования румяной корочки. Куриную грудку в азиатском стиле снять с огня и посыпать семенами кунжута. Приготовить на гарнир рис и овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6738,'Поломать на кусочки шоколад, добавить сахарный песок, влить молоко, прогревать на среднем огне, помешивать. Смесь почти довести до кипения, она должна стать однородной. Подать горячей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6739,'Нарезать картофель тонкими ломтиками в три или четыре миллиметра. Залить подсолнечным маслом, встряхнуть, посолить и поперчить. Выложить чипсы в один слой на противень. Поставить в духовой шкаф, температура приготовления – 200 градусов. Печь до золотистого цвета в течение 13–15 минут. Вынуть противень из духовки, еще раз посыпать домашние чипсы солью и перцем. Остудить на решетке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6740,'Мелко нарезать очищенный лук, чеснок, спассеровать овощи на масле в течение пяти минут, они должны стать полупрозрачными. Жаростойкую посуду для выпекания смазать оливковым маслом. Нарезать кружочками обычный кабачок и цуккини, томаты и картофель, поместить в форму вперемешку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6740,'Продукты посолить, поперчить по вкусу, присыпать тимьяном и тертым сыром. Накрыть емкость фольгой, печь запеканку из овощей в течение получаса, температура приготовления – 200 градусов. Фольгу убрать, блюдо продолжать запекать еще в течение 15 – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Яйца и сахар взбить, всыпать просеянные через ситечко какао, муку, разрыхлитель и соду, влить растопленное масло, тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Готовое тесто поделить на 2 части, испечь тонкий и стандартный коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Остывший тонкий корж отложить, а стандартный разрезать пополам вдоль на одинаковые части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Водку смешать с вишневым сиропом и пропитать ей коржи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Взбить сахар со сливками и соединить все с вишней, получившимся кремом промазать каждый корж.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'Распределить по верхнему коржу оставшиеся сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6741,'К столу подается шварцвальдский торт «Черный лес» с вишней и украшенный тертым шоколадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6742,'Яблоки очистить от кожуры и семян, нарезать тонкими ломтиками. Сложить в миску, побрызгать лимонным соком, чтобы не потемнели. Приготовить тесто из яиц и сахарного песка. Сахар всыпать тонкой струйкой, взбивать до растворения. Ввести муку частями, осторожно перемешать. Чашу мультиварки смазать маргарином или сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6742,'Вылить часть тесто на дно, уложить слой яблок, присыпать их сахаром и молотой корицей. Выложить оставшееся тесто. Поставить режим выпекания на один час. После окончания приготовления будет лучше, если блюдо постоит еще 15 минут. Готовую яблочную шарлотку выложить, украсить на свой вкус, например, посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6770,'Противень застелить бумагой для выпечки, выложить квадратики шахматного печенья, печь в духовом шкафу в течение 10–15 минут при температуре 180–190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Налить бульон или воду. Довести до кипения, убрать пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6743,'Смешать манку с простоквашей или кефиром. Дать постоять для набухания 50–60 минут. Отдельно взбить яйца с сахаром, добавить в манку вместе с растопленным и охлажденным маргарином и с мукой, смешанной с пищевой содой. Посолить, перемешать. Добавить ягоды и еще раз осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6743,'Готовое тесто вылить в форму, смазанную маслом и присыпанную сухарями. Можно использовать силиконовую форму, в этом случае смазка и посыпка не потребуется. Время выпекания ягодного манника–от 40 до 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6744,'Нарезать небольшими кубиками сыр и колбасу, ветчину, отваренную или копченую курицу или сосиски. Готовое слоеное дрожжевое тесто раскатать в пласт толщиной в полсантиметра. Выложить начинку, подогнуть края и скрутить рулет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6744,'Разрезать на порции, переложить слойки с сыром и колбасой на противень и посыпать семечками кунжута. Время выпекания – от 20 до 25 минут, должна получиться золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6745,'Нарезать хорошо вымытый и обсушенный укроп. В натуральный йогурт без вкусовых и цветовых добавок влить лимонный сок, добавить укроп и измельченный чеснок. Все ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6746,'Апельсины вымыть, обдать кипящей водой для удаления горечи и загрязнений. Плоды хорошо вытереть, положить на ночь или на два часа в морозильную камеру. Нарезать, пропустить через мясорубку. Массу залить холодной кипяченой водой, дать постоять в течение 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6746,'Процедить через дуршлаг, а затем через сито или марлю в несколько слоев. Добавить еще воду, сахарный песок и лимонную кислоту. Размешать, разлить апельсиновый сок в бутылки, дать постоять в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6747,'Сложить готовые бублики в емкость, залить молоком так, чтобы они были покрыты жидкостью. Оставить на 30 – 40 минут для набухания, помешивать, чтобы изделия не всплывали. В фарш добавить мелко нарезанный лук, пропущенный через пресс зубчик чеснока, молотый перец и соль по вкусу. Добавить сметану и хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6747,'Большой противень смазать растительным маслом, выложить бублики, в каждый – по шарику фарша, вдавить внутрь. Поставить в горячую духовку на 15 минут, температура приготовления – 150 градусов. Натереть сыр, посыпать им готовые бублики с фаршем, вернуть в духовой шкаф на две или три минуты, сыр должен расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6748,'Пласт готового слоеного теста из магазина раскатать так, чтобы квадрат превратился в прямоугольник. Разрезать тесто в длину на полоски любой ширины. Каждую вторую полоску завернуть наверх, делая сгиб посередине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6748,'У самого сгиба, в центре, положить венскую сосиску, накрыть полосками теста, нечетные полоски завернуть вверх. Те же манипуляции проделать с другой стороной теста. Смазать сосиски в тесте желтком, посолить и поперчить по вкусу. Температура запекания–200 градусов. Тесто должно подрумяниться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6749,'Для начинки отварить в крутую яйца, хорошо остудить, мелко порубить, перья лука обмыть, вытереть, нашинковать помельче, подсолить, слегка сдобрить молотым перцем, перемешать с яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6749,'Перемешать тщательно хорошую сметану с сахаром и солью, добавить распущенное масло, размешать, влить взбитые яйца, полученную смесь хорошо перемешать. Всыпать по частям муку с разрыхлителем, вымесить тесто до получения консистенции густой манной каши.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6749,'Смазать форму для выпечки маслом, а затем присыпать молотыми сухарями, заполнить наполовину тестом, положить слой начинки, залить остатками теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6749,'Поместить форму в прогретый до 200 градусов духовой шкаф, оставить на 35-40 минут, до появления аппетитной золотисто-соломенного цвета корочки. Достать заливной пирог, дать немного остыть, прикрыв тканью, переложить на широкую тарелку и порезать на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6750,'Подготовить рульку, зачистить, вымыть, хорошо вытереть, кусок щедро сдобрить перцем солью, проварить полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6750,'Достать, чуть остудить, слегка надрезать в нескольких местах, переложить на противень с бортиками. Поставить свиную рульку «Хаскл» в духовку с температурой 230-240 градусов на полтора-два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6751,'Разложить на противне отбитое филе курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6751,'Грибы и репчатый лук нарезать, на терке потереть сыр, все это смешать со сметаной, солью, майонезом, перцем, петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6752,'Раскатать из созревшего теста 5 мм пласт, толще не надо, иначе творожное печенье плохо пропечется, порезать на квадраты. Каждый обмакнуть одной стороной в сахарный песок, выложить на него начинку (орехи, мак, изюм), углы загнуть к центру и посильнее сжать пальцами. Верх подготовленного печенья обмакнуть еще раз в сахар, разложить на смазанном маргарином противне, задвинуть его на треть часа в уже прогретую до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6753,'Смазать подходящую по размеру форму маслом, выстелить бумагой для выпечки. Измельчить обжаренный орех, в сыр всыпать сахар, влить экстракт ванили, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6753,'Поставить в микроволновку и растопить масло с шоколадом, в блендере или вручную взбить сахар вместе с яйцами, перемешать их с шоколадной смесью и какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6753,'Добавить ореховую крошку и просеянную муку, вымешать тесто, заполнить им половину формы, далее положить слой из сырной смеси, залить его остатками теста. Выпекать двухцветные брауни с орехом примерно 45 минут в духовке с температурой чуть ниже 185 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6753,'Для оформления верха готового десерта перемешать жидкий шоколад и сливочное масло, молоко, какао и сахарную пудру, довести до однородного состояния в миксере, дополнить украшение дробленым орехом, когда глазурь застынет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6754,'Лапшу для приготовления блюда, если не хочется возиться, можно взять, конечно, и готовую, но с домашней будет вкуснее. Всыпать в чашу комбайна муку, вбить яйца, подсолить, замешивать 5 минут, готовое тесто завернуть в пленку, дать полежать треть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6754,'Вымесить его еще один раз, раскатать, как для приготовления пельменей, нарезать лапшу, чуть подсушить, сварить с добавлением соли. Разогреть в казане растительное масло, обжарить кубики мяса до коричневатой корочки, всыпать полукольца лука, через пару-тройку минут всыпать кубики моркови, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6754,'Жарить 10 минут, следить, чтобы не пригорало, мясо должно стать мягким, всыпать кубики картошки, размешать, тушить еще 10 минут, добавить капусту, кубики сладкого перца и помидора, тушить все вместе 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6754,'Влить в казан кипящую воду на 2 пальца выше содержимого, всыпать специи, подсолить, поперчить, тушить около получаса. За 5 минут до окончания приготовления ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6754,'Разложить в глубокие миски лапшу, на нее положить овощи и мясо, добавить бульон, посыпать измельченную зелень. Кто любит, то может добавить к лагману с говядиной и домашней лапшой еще и ложечку сметаны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6755,'Растереть в глубокой посуде яйца вместе с сахаром до побеления, добавить сметану, творог, всыпать муку с содой, перемешать с использованием блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6755,'Яблоки с кислинкой порезать на дольки, побрызгать соком лимона, уложить в промазанную маслом форму, залить тестом, выпекать пирог «Шарлотка с творожным намеком»  в духовке, прогретой до 190 градусов, через 40 минут ароматная выпечка будет готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6756,'Клубни картофеля помыть, очистить, разрезать на 2 половинки вдоль, теперь каждую надрезать на тоненькие ломтики поперек, но не до конца. Включить прогреваться до 180 градусов духовой шкаф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6756,'Нарезать помидоры острым ножом на полукольца, ветчину–на небольшие кусочки. Вложить в надрезы каждого клубня по кусочку помидора и ветчины, чередуя их друг с другом, присолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6756,'Переложить картофель в форму смазанную маслом, на каждый положить по небольшому кусочку масла.  Поставить картофельные ракушки в достаточно прогретый духовой шкаф на 40 минут. Примерно за 7-10 минут до окончания готовки присыпать половинки картофеля сырной стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6757,'Натереть сыр, порезать мелко сосиски, добавить муку, сметану, чуть чеснока, вбить яйцо, тщательно перемешать котлетную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6757,'Измельчить для панировки несладкие кукурузные хлопья. Сформовать котлетки, обвалять в слегка подсоленной муке, яйцах и в конце в хлопьях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6757,'Обжарить сырные котлетки в сильно разогретом масле до красивой корочки песочного цвета, подавать лучше их лучше с салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'Лук репчатый порезать и немного обжарить также на масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'Отварить до готовности куриную печень, порезать крупными кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11197,'Добавить ледяную воду, вбить одно яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6758,'Вылить на лаваш яйцо, быстро размазать его по поверхности, дать немного схватится белку, присыпать измельченными крабовыми палочками, а затем сыром. Осторожно перевернуть лаваш вниз сыром, прожарить  лаваш с крабовыми палочками до пышности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6758,'После прожарки яйца и расплавления сыра убрать блюдо с огня, свернуть конвертом или в рулет, присыпать нарубленной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6759,'Картофель помыть, очистить, порезать его и ножки шампиньонов кружочками, сдобрить перцем, подсолить, влить сметану, перемешать, переложить в форму, промазанную маслом, выпекать полчаса при температуре около 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6759,'Отрезанные шляпки грибов, поперчить, присолить, смазать густой сметаной (по желанию майонезом), наполнить их мелкими кубиками сыра и помидоров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6759,'Достать форму, влить полстакана бульона (кипятка), уложить фаршированные шляпки, готовить картофель с шампиньонами в духовке еще полчаса или чуть больше до появления красивой запеченной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6760,'Нашинковать на тонкие полукольца салатный лук, порезать их на кубики, залить подслащенным уксусом с небольшим количеством соли, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6760,'Чеснок раздавить прессом, зелень петрушки мелко порезать, перемешать с достаточно густой сметаной, поперчить, посолить, добавить маринованный лук, соус еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6760,'Быстро подрумянить отварную грудку курицы, порезанную на небольшие кубики в сильно разогретом масле. Все овощи порезать примерно на одинаковые кусочки и перемешать, добавить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6760,'Порезать лаваш на полосы требуемой ширины, промазать соусом, уложить начинку из курицы и овощей. Свернуть с небольшим нажимом лаваш в трубочку, быстро обжарить домашнюю шаурму с курицей на хорошо разогретой сковороде-гриль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'Перед тем как начать готовить, нужно положить плавленые сырки в морозильник, чтобы они затвердели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'В кастрюлю влить воду и поставить ее на огонь, очищенные картофель и лук порезать кубиками, морковь – ломтиками и все сложить в кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'Замороженные плавленые сырки крупно потереть на терке, порезать копчености.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'За несколько минут до готовности картофеля добавить в кастрюлю копчености и дать покипеть пару минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'Затем закинуть натертые сырки и не снимать кастрюлю с огня до тех пор, пока сырки полностью не растают.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6761,'Далее суп картофельный с копченостями и плавленым сыром поперчить и посолить, убрать с огня, добавить измельченный укроп и петрушку, дать настояться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6762,'Нарезать или натереть капусту тонкой красивой соломкой, огурцы  соленые или свежие (в сезон)–на маленькие кубики, добавить кукурузу, всыпать в последнюю очередь 150 гр сухариков. Заправить капустный салат с сухариками майонезом, перемешать и сразу подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6763,'Готовое тесто достать заранее, пусть нагреется до комнатной температуры, уложить в форму, сделать бортики, сделать на дне много наколок вилкой. Поставить в прогретую не выше 200 градусов духовку минут на 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6763,'Перемолоть в кофемолке мак, смешать с манкой, молоко нагреть почти до кипения, положить сахар, всыпать, помешивая маковую смесь, проварить с помешиванием 5 минут, дать начинке пирога остыть, переложить на готовую основу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6763,'Для заливки взболтать (не взбивать) с сахаром сметану и яйца, добавить для аромата ванильный сахар, а для большей густоты чайную ложку муки (с горкой), вылить на начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6763,'Выпекать маковый пирог со сметанной заливкой минут 35 при температуре, не превышающей 180 градусов, остудить и подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6764,'Включить и прогреть до180 градусов духовку, порезать бананы на шайбочки, присыпать для аромата ванильным сахаром. Растопить масло, всыпать полстакана сахара, добавить 3 желтка, перемешать, всыпать муку, вымесить плотное песочное тесто, положить в пакет, а затем – в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6764,'Промазать форму маслом, выложить ее тестом, уложить сверху бананы, промазать жирной хорошей сметаной с добавлением кокосовой стружки, ванилина, сахарной пудры. Отправить основу пирога на 20 минут в уже прогретую духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Положить картофель. Готовить 15-20 минут. Положить лавровый лист, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6764,'Приготовить из сахара и оставшихся трех белков воздушный легкий крем, взбивать не менее 10 минут, когда быстрый банановый пирог будет почти готов смазать получившимся кремом, присыпать раздробленными орехами или украсить цукатами, вернуть на пару-тройку минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6765,'Подготовить мякоть куриной грудки, порезать на кусочки, присолить, притрусить молотым перцем, паприкой, перемешать, дать настояться полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6765,'Обжарить в масле до золотистости тоненькие пластинки чеснока, вынуть их, а в этой же сковороде обжарить при небольшом нагреве, периодически переворачивая, мясо. Влить чуть воды, нагрев уменьшить, готовить еще треть часа, накрыв крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6765,'Крупно натертый сыр смешать со сливками, всыпать мелко порубленную пряную зелень, залить курицу, размешать. Готовить куриное филе с чесноком и сыром еще 15 минут при едва заметном кипении, подавать блюдо к столу в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6766,'Присыпать небольшим количеством муки стол, расправить лист готового теста, порезать на треугольники. Положить на основание каждого выбранную начинку, например, шоколад, свернуть в форме рулетика, смазать верх каждого разболтанным яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6766,'Уложить французские круассаны на противень, застланный пергаментом, выпекать около 20-30 минут, маленькие рогалики будут готовы уже через 15 минут, температура духовки должна быть заранее доведена до 210-220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6767,'Разрезать на две одинаковые половинки булочки, зарумянить  срезы на разогретой сковороде без масла. Порезать огурец чуть наискосок на одинаковые по толщине кусочки. Нашинковать на тонкие полукольца лук, присыпать щепоткой сахара и соли, облить уксусом, размешать, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6767,'Сформовать по размеру булочек плоские котлетки, обвалять в сухарях, обжарить с 2 сторон на сильно разогретой сковороде до появления коричневатой корочки. В идеале лучше использовать сковороду-гриль, но можно и на обычной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6767,'Смазать нижнюю половинку булочки соусом, прикрыть листом салата. На него уложить горячую котлету, смазать кетчупом, прикрыть дольками огурца, присыпать промаринованным луком, завершить «сборку» бургера ломтиком сыра. Наконец уложить верхнюю половинку булочки, смазанную соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6768,'Помыть молодые ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6768,'Натереть сильно охлажденный плавленый сырок на терке, перемешать с пропущенным через пресс чесноком и майонезом. Помидор порезать на полоски, зелень разобрать на маленькие веточки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6768,'Намазать каждую холодную пластинку кабачка сырной смесью, накрыть помидором, положить рядом по веточке каждой зелени, свернуть в трубочку. Уложить рулетики из кабачков с сыром на листья салата (каждый на свой), сложить на широкое блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6769,'Куриные грудки, без кожи, отварить в подсоленной воде в течение 15–20 минут, до готовности. Можно добавить лавровый лист, перец-горошек. Вынуть мясо из воды, остудить. Белокочанную капусту без кочерыжки посолить и помять руками до выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6769,'Куриное филе порезать небольшими кусочками, добавить капусту, тертый твердый сыр, перемешать. Залить майонезом по вкусу, еще раз перемешать. Посыпать капустный салат с куриным филе сухариками или гренками, сразу подать, пока они не размокли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6770,'Отварить вкрутую куриные яйца, очистить, отделить желтки от белков. Желтки хорошо размять с помощью вилки, белки для этого блюда не понадобятся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6770,'Сливочное масло комнатной температуры смешать с коричневым сахаром, ванилином из пакетика, желтками и солью по вкусу. Массу разделить на две равные части, в одну из них добавить какао-порошок и перемешать до однородного состояния. Всыпать просеянную пшеничную муку, оба теста замесить по отдельности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6770,'Светлое и темное тесто раскатать в пласты прямоугольной формы и одинакового размера. На темную лепешку положить светлую, прижать, положить в холодильник на полчаса или чуть больше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6770,'Двухцветную заготовку разрезать на четыре пластины, вдоль, они должны быть одинаковой ширины. Сложить их по две, чтобы цвет чередовался. Полученные «брусочки» нарезать на кусочки в один сантиметр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'Для заправки следует смешать оливковое масло, молотые кориандр и имбирь и соевый соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Для приготовления цитрусовых в сиропе нарезать тонкими ломтиками апельсин, мандарин, кумкваты. Добавить тертую цедру, сахарный песок, стакан воды. Смесь довести до кипения, варить до полупрозрачности долек. Цедру откинуть на сито или дуршлаг, а фруктовые дольки обсушить на бумажном листе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Для приготовления коржа брауни сливочное масло и шоколад растопить на водяной бане. Сырые яйца взбить с коричневым сахарным песком, перемешать с шоколадной смесью, всыпать пшеничную муку, фундук и две трети сваренных кумкватов. Осторожно перемешать, движениями снизу вверх. Разъемную форму смазать маслом, вылить тесто, печь в течение получаса при температуре 200 градусов. Остудить корж в форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Приготовить миндальный бисквит джоконда: взбить сырые яйца в пышную массу, добавить просеянную пшеничную муку, молотый миндаль и растопленное сливочное масло. Массу осторожно перемешать. Белки взбить отдельно, осторожно вмешать в основную массу. Разделить её на две половины: в одну добавить какао-порошок, в другую – немного пищевого красителя оранжевого цвета и цедру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Застелить противень бумагой, выложить тесто полосками, с помощью кондитерского мешка, печь при 200 градусах в течение 20 минут. Полоски остудить. Они не должны быть пересушенными, иначе могут сломаться при сгибании.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Для мусса растопить черный шоколад. Всыпать цедру, отваренную в сахарном сиропе, выложить смесь на бумагу, дать застыть и поломать на кусочки. Замочить в части апельсинового сока желатин. Оставшийся сок смешать с сахаром и мякотью маракуйи, прогреть почти до кипения, добавить желатиновую смесь. Охладить до состояния киселя, взбивать с помощью миксера, скорость должна быть максимальной, в течение 15 минут. В готовый мусс положить кусочки шоколада.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Корж брауни выровнять ножом, выложить в форму. По краю поставить бортик из бисквита, в середину торта вылить мусс. Блюдо поставить в холодильник для полного застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6771,'Для желе замочить желатин в соке, сироп, оставшийся от варки цитрусовых, нагреть до кипения, влить в желатиновую массу, проварить до полного растворения. Дольки фруктов выложить на торт «Тигрис», смазать кисточкой апельсиновым желе, дать застыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6772,'Для приготовления теста растопить горький шоколад со сливочным маслом на водяной бане. Массу помешивать, она должна стать однородной. Готовую смесь убрать с плиты, немного остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6772,'В готовую, немного остывшую массу ввести сахарный песок, просеянный какао-порошок, ванилин. Ингредиенты перемешивать с помощью миксера или венчика. Вбить по одному яйца. Каждый раз массу взбивать. Всыпать просеянную пшеничную муку, немного соли. Смесь перемешать, добавить рубленые грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6772,'Тесто перемешать до однородного состояния, перелить в нагретую, смазанную маслом, металлическую форму или в форму из силикона. Печь брауни при температуре 180 градусов в течение получаса. Готовность выпечки проверить зубочисткой, она должна остаться влажной. Пирог можно доставать, он должен покрыться корочкой, но быть недопеченным внутри, очень важно этот пирог не пересушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6772,'Готовую выпечку охладить, достать «Брауни» с грецким орехом из формы, при подаче украсить сахарной пудрой, ягодами и шариками мороженого.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6773,'Картофельные клубни вымыть, положить в холодную воду. Отварить до готовности. Воду слить, продукт остудить, размять в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6773,'В холодное пюре всыпать муку, должно получиться мягкое тесто. Слепить «колбаску» в два сантиметра толщиной, нарезать на квадратные кусочки острым ножом. Каждый кусочек чуть придавить вилкой и обвалять в небольшом количестве муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6773,'Для соуса обжарить измельченный репчатый лук на оливковом масле, он должен стать прозрачным. Добавить томатную пасту, соль и молотый перец – по вкусу. Смесь перемешать, прогреть в течение 20 минут на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6773,'Картофельные клецки отварить в подсоленной воде до готовности, они должны всплыть. Вынуть их шумовкой, сразу положить в томатный соус. Перемешать, снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'Горячей водой на 5-7 минут залить фунчозу, потом перекинуть ее на ситечко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'В районе 8-10 минут на растительном масле обжарить крупно нарезанные шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6774,'Сложить в миску все подготовленные ингредиенты: фунчозу, печень, лук, грибы и готовую морскую капусту, полить приготовленной заправкой теплый салат из фунчозы и куриной печени, хорошенько перемешать, украсить петрушкой и подать к столу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6775,'Взбить сырые куриные яйца с сахарным песком, добела. Всыпать заранее просеянную пшеничную муку, хорошо перемешать лопаткой. Форму для выпечки застелить бумагой, вылить тесто, разровнять. Печь при температуре 180 градусов в течение 8–11 минут. Через восемь минут духовку открыть и проверить готовность теста: при нажатии пальцем оно должно подниматься обратно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6775,'Тканевое хлопчатобумажное полотенце присыпать сахарной пудрой, выложить бисквит, бумагу убрать, скрутить рулет прямо с полотенцем, остудить. Для приготовления крема смешать немного молока с кукурузным крахмалом, остальное довести до кипения, влить крахмальную массу. Варить в течение минуты, масса должна загустеть. Помешивать. Плиту выключить, массу охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6775,'Растопить темный шоколад со сливочным маслом на водяной бане, немного остудить. Яблочный сок перемешать с сахарным песком до растворения последнего. Смешать крахмальную массу со сладким молоком, коньяком, крем взбить. Развернуть бисквит, пропитать яблочным соком с сахаром, распределить крем: в середине слой должен быть толще. Скрутить рулет «Чешский», полить оставшимся шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6776,'От буханок белого хлеба отрезать верхушки. Срезать корочки. Разрезать мякиш на «коржи» толщиной в один сантиметр. Для крема перемешать творожный сыр, майонез и жирную сметану, поперчить по вкусу. Если масса получилась слишком густая – можно добавить немного сливок. Немного крема отложить для смазывания боков торта, остальной разделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6776,'В первую добавить мелко нарубленные отваренные яйца и зеленый лук, перемешать. Во вторую – кусочки красной копченой рыбы, кеты или горбуши, зеленый укроп. Смазать хлебный «корж» яичным кремом, положить на него второй, смазать «рыбным». Продолжать складывать хлеб, промазывая кусочки в том же порядке. Бока скандинавского закусочного торта смазать отложенным кремом, дать постоять в холодильнике от получаса до двух часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6777,'Взбить в блендере до однородного состояния творог, натуральный йогурт и сырые куриные яйца. Должна получиться однородная масса, похожая на сметану. Всыпать половину чайной ложки молотой корицы, немного ванили. Массу еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6777,'Очистить от кожуры бананы, нарезать на половинки вдоль. Выложить плоды на дно жаропрочной посуды, залить творожной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6777,'Печь десерт в духовом шкафу при температуре 180 градусов в течение получаса. Банановая запеканка должна загустеть и приобрести золотистую корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6778,'Приготовить маринад из майонеза, готовой столовой горчицы и соуса кетчуп. Добавить по вкусу соль и специи. Намазать смесью куски мяса, положить в холодильник на ночь. Нарезать кружками репчатый лук и спелые помидоры, свежие шампиньоны нарезать дольками, твердый сыр натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6778,'Выложить маринованное мясо на лист фольги, сверху – колечки лука и помидоры, грибы. Завернуть, поставить на гриль или в духовку на 50 минут, печь при температуре 200 градусов. Почти при готовности блюда аккуратно раскрыть фольгу, посыпать каждый кусок свинины тертым сыром и допечь в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6779,'Нарезать кубиками куриное мясо и сыр. Добавить охлажденное и натертое сливочное масло, вбить куриные яйца, всыпать картофельный крахмал, зелень, соль, перец и другие специи по вкусу. Массу поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6779,'Сформовать котлеты, жарить с двух сторон до образования румяной корочки. Подать котлетки «Нежность» с веточками зеленого укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6780,'Консервированного в собственном соку тунца поломать на кусочки. Отварить куриные яйца и нарезать кубиками. Такими же кубиками нарезать маринованные огурцы. Все ингредиенты смешать, добавить консервированный зеленый горошек, заправить блюдо майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Постоянно помешивая поварить на среднем огне пока крем не начнет булькать, затем готовый крем нужно снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Когда крем остынет, положить в него сливочное масло, слегка все взбить, добавить миндаль, лимонный сок и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6781,'Перемешать сахарный песок, какао-порошок, просеянную пшеничную муку и разрыхлитель, можно добавить по вкусу молотую гвоздику, имбирь, корицу, мускатный орех. Отдельно взбить сырые куриные яйца с сахаром до пышности, всыпать сухие ингредиенты, аккуратно перемешать. Тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6781,'Противень застелить бумагой для выпечки, смазать маслом. Вылить тесто так, чтобы оно равномерно растеклось по поверхности. Печь при температуре 180 градусов в течение 12 минут. Корж переложить на решетку, бумагу снять, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6781,'Для приготовления крема растопить шоколад на водяной бане. Сыр маскарпоне комнатной температуры взбить миксером вместе с прогретым коньяком, влить шоколадную массу, перемешать с помощью миксера на минимальной скорости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6781,'Из картона вырезать трафарет в виде шишки. Готовую выпечку разрезать на прямоугольники, положить друг на друга и на картон, углы срезать, придать бисквиту форму шишки. Слои промазать получившимся кремом, остатками – верх торта. Выложить поверхность шоколадными драже, имитируя «чешуйки», они должны находить друг на друга, поставить торт «Еловая шишка» в холодильник для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Хорошо охлажденное сливочное масло порезать на крупные куски, посыпать пшеничной мукой и порубить в крошку средней величины, это нужно делать острым ножом. Всыпать щепотку соли. Быстро перетереть смесь руками, высыпать в миску, влить ледяную воду, перемешать массу еще раз, в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Выложить готовое песочное тесто в круглую форму, равномерно распределить по дну и по бортикам. Форму с «корзинкой» поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Для начинки очистить и натереть морковь полосками, можно использовать овощечистку, нарезать таким же образом кабачки цуккини прямо с кожурой. Оба овоща должны быть измельчены примерно одинаково.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Вынуть форму с тестом из холодильника, выкладывать овощные полоски, спиралью, двигаясь от краев к центру, цуккини чередовать с морковью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Для заливки смешать чуть взбитые сырые яйца, подлить сливки, перемешать, всыпать специи: молотый мускатный орех, тертый чеснок, посолить по вкусу. Натереть сыр, перемешать с основной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6782,'Залить яичной смесью овощи, она должна проникнуть и между полосками. Печь пирог «Овощная идиллия» при температуре 180 градусов в течение часа, на нижней полке духовки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6783,'Нарезать филе семги кубиками, помидоры бланшировать в кипятке, очистить от кожицы и семян, нарезать кусочками. Мелко нарубить репчатый лук, чеснок раздавить под прессом. Налить на сковороду оливковое масло, положить чеснок и лук, жарить в течение минуты. Добавить рыбу и помидоры, посолить, поперчить, положить листочки тимьяна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6783,'Прогревать смесь еще четыре-пять минут. Влить сливки, перемешать и вновь прогреть в течение трех минут. Можно добавить тертый сыр. Отварить пасту так, как указано на упаковке. Феттучини с красной рыбой выложить на тарелки, полить соусом, посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'Из одного яйца получается 2 кораблика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'Отварить желаемое количество яиц, пополам их разрезать вдоль, достать все желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'Сыр потереть на терке, извлеченные яичные желтки растереть с сыром, майонезом, солью и черным перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'Каждую половинку белков наполнить получившейся начинкой, сверху выложить немножко красной икры, вместо которой также можно взять горошек или кукурузу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'На зубочистку или шпажку наколоть треугольную или прямоугольную полоску сыра и воткнуть в половинку яйца в виде паруса, проделать такое со всеми корабликами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6784,'Закуску «Кораблики» из яиц с красной икрой можно подать как на общем большом блюде, так и порционно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6785,'Рыбу очистить, порезать кусочками. Вскипятить воду, добавить соль, сахарный песок, перец-горошек, кориандр и молотый перец. Влить растительное масло, кипятить смесь в течение минуты, затем влить уксус. Маринад остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6785,'Нарезать полукольцами репчатый лук. Сложить рыбу вместе с луком, вперемешку, в емкость, залить скумбрию с пряностями маринадом на сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8210,'Отделить белки от желтков. Желтки взбить и добавить в уваренную смесь, снять  с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6786,'Смешать кефир, сырые куриные яйца, растительное масло, добавить измельченный с помощью блендера в пюре кабачок. Отдельно смешать пшеничную муку, сахарный песок, соль, пищевую соду и разрыхлитель. Добавить сухую смесь к жидкой. В тесто, по желанию, можно добавить ванилин. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6786,'Разогреть сковороду, смазать растительным маслом, выкладывать оладьи столовой ложкой. Жарить пышные оладьи с кабачком на среднем огне, под крышкой, с одной стороны, затем перевернуть и дожарить с другой, уже без крышки. Должна получиться румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6787,'Отварить до готовности куриные яйца, морковь. Овощ очистить, остудить. Отварить рис, также охладить. Слить жидкость от рыбных консервов, сардин или тунца, кости вынуть, мякоть размять вилкой. Промыть и порубить зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6787,'В салатницу выложить слой отваренного риса, затем – рыба, зеленый лук, поперчить, смазать майонезом. Следующий слой – тертые белки, посолить, полить майонезом, затем тертая морковь, майонез, тертые желтки. Салат «Мимоза» накрыть крышкой или пищевой пленкой и поставить в холодильник для пропитывания на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6788,'Мелко нарезать очищенный чеснок и репчатый лук. Растопить сливочное масло на сковороде, обжарить то и другое в течение двух минут. Добавить очищенные креветки, прогревать еще две-три минуты. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6788,'Влить в сковороду сливки, довести смесь до кипения. Добавить рубленую петрушку, огонь выключить. Отварить пасту так, как указано на упаковке. Смешать с креветочным соусом и подать быструю пасту с креветками к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6789,'Нарезать красный репчатый лук полукольцами, красный и желтый сладкий болгарский перец – соломкой. Нашинковать зеленый лук и китайскую капусту, отваренную курицу измельчить кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6789,'Для приготовления заправки смешать сметану, столовую горчицу, давленый зубчик чеснока, соль и перец. Все ингредиенты выложить в салатницу, перемешать, полить соусом и подать салат «Курочка-Снегурочка» к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6790,'Нарезать ошпаренный кипятком чернослив, отварное мясо курицы порезать или разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6790,'Обжарить грибы и репчатый лук на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6790,'Вареные яйца и свежий огурец измельчить с помощь терки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6790,'Куриный салат «Меркурий» с грибами и черносливом выложить слоями, каждый из которых нужно промазать майонезом (кроме луково-грибного слоя) и слегка посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6790,'Последовательность слоев следующая: сначала чернослив, потом курица, затем грибы и лук, далее яйца, последний слой — огурец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6791,'Смешать соль, сахарный песок, молотый перец и паприку. На лист пищевой пленки выложить часть веточек укропа, затем половину сухой смеси. Сверху–филе кеты, горбуши, семги, с кожей, кости вытащить, можно воспользоваться пинцетом. Затем – остатки смеси и укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6791,'Рыбу со специями хорошо обернуть, уложить под гнет, поставить в холодильник. Два раза в день тушки переворачивать. Блюдо будет готово через два-три дня, филе нужно промыть теплой водой, при подаче соленую красную рыбу нарезать и полить растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6792,'Разделить сырые яйца на желтки и белки. Белки взбить с сахарным песком в плотную пену. Отдельно взбить желтки с сахаром до побеления. Всыпать пакетик ванилина, влить коньяк и положить сливочный сыр маскарпоне. Массу перемешать до однородного состояния. Осторожно ввести белки, движениями снизу вверх, масса должна остаться пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6792,'Печенье савоярди положить в кофе или в малиновый сироп. В напиток или сироп также можно добавить коньяк или другой алкоголь. В десертные формочки выложить пропитанное кофе печенье, залить кремом. Посыпать десерт какао-порошком, можно украсить свежими ягодами малины, листочком мяты. Поставить «',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Из муки, дрожжей, сахара, соли и сухих сливок или сухого молока, взбитого и соединенного с водой яйца вымесить липкое тесто, добавить цедру лимона и растопленное сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Миску с тестом накрыть полотенцем и отставить на 2 часа, чтобы оно подошло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Крахмал развести в молоке, влить яичные желтки, добавить лимонную цедру, срезанную лентой, ванилин и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6793,'Булочки с кремовой начинкой «Крем-де-Паризьен» могут быть и шоколадными: просто в момент приготовления теста нужно 2-3 ст. л. муки заменить таким же количеством какао-порошка, а сливочное масло для крема заменить шоколадом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6794,'Рис и маленькие креветки раздельно отварить до готовности и дать им полностью остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6794,'На одной половине листа нори распределить рис, перевернуть нори рисом вниз и на второй стороне – отваренные креветки, икру летучей рыбы, сливочный сыр, завернуть лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6794,'На пленку уложить филе семги, затем на рыбу переложить ролл.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6794,'С помощью макисы завернуть все в пленку и порезать на кусочки прямо через пленку острым ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6794,'Сливочный ролл с икрой тобико украшается по желанию и подается к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'Сахар и яйца растереть, добавить к ним растительное масло, молоко, муку, разрыхлитель и крахмал, тесто должно получиться жидковатое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'В разъемную форму вылить получившееся тесто и выпекать корж в течение 20-25 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'В холодной воде замочить желатин, виноград (лучше взять без косточек) помыть и просушить, 2/3 ягод порезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'Смешать творожный сыр, сахар, лимонный сок и йогурт, в полученный крем добавить размоченный желатин и взбитые сливки, все осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'Застелить пергаментом разъемную форму, положить уже остывший корж, слегка промазать его подготовленным кремом, распределить по всему коржу порезанный виноград и залить все оставшимся кремом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'Постучать формой об пол для того, чтобы пузырьки воздуха, возникшие между кремом и виноградом, вышли, затем поставить ее в холодильник на два часа, после чего достать и убрать бортик любым удобным способом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6795,'Изумрудный торт с виноградом и фундуком осторожно переложить на блюдо, украсить фундуком и виноградом, подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6796,'Налить в кастрюлю воду, положить сливочное масло и посолить. Довести смесь до кипения, снять с огня, при активном помешивании всыпать пшеничную муку. Продолжать мешать, масса должна стать густой и легко отставать от стенок кастрюли. Дать тесту остыть в течение пяти минут, вбить яйца, перетереть массу толкушкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6796,'Смазать противень маслом или маргарином или выложить бумагой для выпечки. Тесто выкладывать с помощью кулинарного шприца, оставлять между эклерами свободное пространство, они увеличатся в объеме. Печь пирожные при температуре 200 градусов в течение 20 минут. Затем температуру убавить до 150 градусов, посушить выпечку еще полчаса. Духовку выключить, открыть дверку, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6796,'Для крема всыпать в небольшую кастрюлю пшеничную муку, вбить сырые яйца. Размешать массу до однородного состояния, в ней не должно быть комочков. В другую емкость вылить молоко и всыпать сахарный песок. Варить до закипания. Сладкую смесь влить в яичную тонкой струйкой, быстро и интенсивно перемешивать. Поставить крем на средний огонь и выпарить жидкость, продолжать мешать. Огонь выключить, добавить сливочное масло и ванилин из пакетика, хорошо перемешать. Крем нужно быстро остудить, кастрюлю можно поставить на слой льда или в холодную воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6796,'Эклеры разрезать сбоку, начинить кремом с помощью шприца или ложкой. Для глазури растопить шоколад на водяной бане вместе со сливочным маслом. Добавить сахарную пудру, молоко, ванилин. Перемешать, оставить массу на 10 минут, уварить до загустения, затем немного остудить. Эклеры смазать глазурью с помощью кулинарной кисти. Домашние эклеры с кремом в шоколадной глазури на 10 минут поставить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6797,'Нарезать кубиками сырую куриную грудку. Очистить и вымыть репчатый лук, нарезать кубиками. Разогреть на сковороде растительное масло, выложить филе, посыпать специями, посолить и обжарить в течение пяти минут. Добавить измельченный лук, тушить еще пять минут. В сковороду влить сметану, массу перемешать и прогревать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6798,'Вымыть томаты, обдать кипятком и очистить от кожицы. Нарезать одинаковыми кружками. Натереть твердый сыр. Приготовить кляр из твердого сыра, сырых яиц, майонеза и пшеничной муки. Соль и перец молотый добавить по вкусу, массу перемешать, она должна получиться густой и вязкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6798,'Обмакнуть в кляр помидоры, выложить ложкой на сковороду с разогретым растительным маслом. Жарить с двух сторон до образования золотистой корочки. Помидоры в сырном кляре выложить на бумажное полотенце, дать впитаться лишнему жиру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6799,'Томаты в собственном соку, давленый зубчик чеснока, сливочное масло и морскую соль выложить в большую сковороду, довести до кипения на среднем огне. Огонь убавить, прогревать 45 минут без крышки, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6799,'Панировочные сухари положить в большую емкость, залить молоком, перемешать, оставить для набухания на 10 минут. Добавить говяжий фарш, тертый сыр, сырые яйца, рубленую зелень петрушки, морскую соль и молотый перец – по вкусу. Замесить фарш руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6799,'Сформовать шарики небольшого размера, выложить на противень. Печь в течение 20 минут при температуре 175 градусов. Переложить в сковороду с томатным соусом. Потушить все вместе еще 10–15 минут. Подать шарики из говяжьего фарша с заранее отваренной пастой, посыпанной тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6800,'В кастрюлю с водой положить лавровый лист, добавить перец и соль, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6800,'Грудинку порезать на порционные куски и положить в кастрюлю так, чтобы вода покрывала ее на два пальца, поварить на небольшом огне в течение 40 минут',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6800,'Когда грудинка будет готова, ее необходимо убрать в место с комнатной температурой на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6800,'Для маринада смешать специи, молотый черный и красный перец и измельченный чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6800,'По истечении отведенного времени обмазать все кусочки мяса приготовленным маринадом, переложить в емкость или завернуть в фольгу и отставить в сторону на 1 час, после чего вареная свиная грудинка по-домашнему помещается в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6801,'Почистить лук и чеснок, ошпарить кипятком, обрезать верхушку луковицы, вынуть сердцевину, растолочь ее в ступке вместе с чесноком, добавить перец, масло, соль и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6801,'Наполнить полученной массой луковые чашечки, смазать слегка противень маслом и',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6801,'выложить лук запеченный в сухарях фаршированный чесноком на противень, присыпать панировочными сухарями и отправить в духовку до зарумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6802,'Выбрать мясистые, спелые и красивые перцы, лук нарезать тонкими кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6802,'Вымыть перцы, запечь на сковороде (периодически поворачивая), переложить в кастрюлю, подсолить, накрыть салфеткой и дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6802,'Снять с перцев кожуру и выложить в салатник, заправить маслом, уксусом, добавить лук, рубленый укроп и нарезанные помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6802,'После приготовления салат с помидорами и печеным болгарским перцем должен час-два настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6803,'Говядину, свинину или куриную грудку отварить в подсоленной воде. Цветную капусту вымыть, разобрать, также отварить в подсоленной воде в течение 7–10 минут. Отварить куриные яйца. В большую миску выложить консервированную кукурузу без жидкости и отваренное мясо, нарезанное квадратиками. Добавить нарезанные яйца, оставить немного желтка и белка для украшения. В салат добавить нарезанные маслины, рубленую петрушку. Соль и перец – по вкусу, заправить массу майонезом и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6803,'Выложить салат на большое блюдо в виде овечки, лежащей на боку, можно сделать это с помощью трафарета, вырезанного из пленки. Верх выложить соцветиями капусты, это будет шерстка, мордочку покрыть измельченными маслинами. Ушки также сделать из разрезанных маслин, на зубочистке, ее прикрыть соцветием. Ноги – половинки маслин, намазанные майонезом. Глаза – из яичного белка, маслины и кунжутного семечка, смазанного майонезом для прилипания или маленького кусочка белка. Ноздри – из полосок маслин, рот и хвостик–из капусты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6804,'Молодые клубни картофеля очистить и нарезать брусками, толщиной в сантиметр. Отдельно взбить сырые яичные белки в пену, добавить сладкую молотую паприку и черный перец, массу перемешать. Смешать яичную массу с картофелем, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6804,'Противень застелить бумагой для выпечки, выложить бруски картофеля, печь в течение 7–10 минут при температуре 200 – 220 градусов. Бумагу убрать и допечь картофель фри на противне до образования золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11201,'В середине оставить отверстие для бульона.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6805,'Взбить сырые яйца. Растопить сливочное масло или маргарин на водяной бане, влить яйца, добавить манную крупу, сахарный песок и разрыхлитель. Массу хорошо перемешать. Всыпать просеянную пшеничную муку и снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6805,'Добавить ягоды малины, клубники, земляники, черники, голубики. Форму для выпекания смазать маслом и посыпать мукой, вылить тесто, печь ягодный манник при температуре 180 градусов в течение 40 минут. Верх выпечки должен зарумяниться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6806,'Для приготовления теста растереть творог с сырыми яйцами, влить теплый кефир, пищевую соду, соль и пшеничную муку. Замесить тесто, оно должно получиться густым по консистенции. Для начинки натереть твердый сыр, добавить измельченный чеснок и зелень укропа, сметану, массу хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6806,'Разогреть сковороду с растительным маслом. Тесто выкладывать ложками, между оладьями оставлять расстояние. Из сырной начинки слепить «лепешки» и выложить на тесто. Обжарить оладьи «Хачапури» с двух сторон до зарумянивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6807,'Молоко прогреть в микроволновой печи, положить в него хлеб без корочки и дать пропитаться. В готовый говяжий фарш добавить размоченный хлеб, пшеничную муку, щепотку соли, зиры, перца и паприки. Сформовать тефтели и обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6807,'Для соуса в небольшой емкости разогреть мед, добавить винный уксус, все вместе прогреть. Влить апельсиновый сок, огонь добавить, помешивая, выпаривать до половины объема. Добавить томатную пасту, карри, соль по вкусу, перемешать. Тефтели залить томатным соусом и прогревать под крышкой в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6807,'Для гарнира нарезать кубиками баклажаны, замочить в подсоленной воде на 10 минут для удаления горечи. Обжарить овощ до готовности, можно еще немного подсолить. Очистить и нарезать кубиками картофель, обжарить до образования золотистой корочки, в конце приготовления посолить. Подать овощи с мясными тефтелями, украсить листочками петрушки и укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6808,'Булочки для хот-дога осторожно разрезать пополам, но не до конца, смазать соусом кетчуп. Вложить в разрез сосиски. Нарезать консервированные огурцы и свежие помидоры кружками, выложить по одну и другую сторону, на сосиску выдавить горчицу и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6808,'Натереть твердый сыр, посыпать хот-доги. Выложить закуску на противень, поставить в нагретую духовку, печь в течение 15 минут, сыр должен расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6809,'Разделить на желтки и белки сырые куриные яйца. Белки взбить в крепкую пену, желтки перемешать с сахарным песком и взбить до побеления. В желтковую массу влить молоко, жидкий мед, растительное масло, всыпать пшеничную муку, какао-порошок и разрыхлитель. Массу хорошо перемешать, осторожно соединить со взбитыми белками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6809,'Выпечь два коржа, поочередно, на противне с высокими бортиками в течение 10 – 15 минут при температуре 180 градусов. Осторожно вынуть и остудить. Приготовить крем-желе, для этого смешать сгущенное молоко с медом и половиной молока. Отдельно замочить желатин из пакетика до набухания, смешать с оставшимся молоком. Смесь прогреть, но не кипятить, помешивать, должна получиться однородная масса. Соединить её с медовой смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6809,'В другой емкости взбить сливки с сахарным песком, вместо сливок можно взять сметану. Постепенно влить первую смесь, перемешать и поставить в холодильник. Приготовить глазурь из какао-порошка с молоком и сахарным песком, довести смесь до кипения, добавить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6809,'Собираем торт: первый корж намазать молочным кремом из холодильника, накрыть вторым коржом, верх полить глазурью. Пирожное «День-Ночь» поставить в холодильник, при подаче разрезать на прямоугольники.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6810,'Мелко нарезать лук-шалот, обжарить на сливочном масле до мягкости. Добавить тертую цедру лимона и давленый чеснок. Влить сок одного лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6810,'Противень застелить бумагой для выпечки или фольгой, выложить филе форели, соль и перец – по вкусу. Сверху – луковая смесь, посыпать рубленой зеленью укропа. Печь филе форели в течение 12–17 минут. Готовое блюдо сбрызнуть остатками лимонного сока, еще посыпать укропом и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6811,'Промыть почки, нарезать на пластинки, залить водой и дать закипеть, воду слить, залить опять водой и довести до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6811,'Телячьи почки тушеные по-румынски с рисом подать на большой тарелке, полить соусом со сковороды, украсить веточками зелени и пластинками соленого огурца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6812,'Растопить в сотейнике сливочное масло, прогреть в нем мелко нарубленный чеснок. Всыпать ложку пшеничной муки и немного обжарить. Влить сливки, помешивать, масса должна получиться однородной и немного загустеть. Подлить немного кипяченой воды, всыпать соль, смесь перцев, лавровый лист. Смесь довести до кипения, выключить и подержать под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6812,'Натереть морковь и репчатый лук. Нарезать кружками клубни картофеля, выложить в форму, посолить и поперчить по вкусу, полить растительным маслом. На картофельную «подушку» выложить стейки форели, немного посолить, накрыть морковно-луковой массой, сверху – соус из чеснока.  Печь форель с чесночным соусом на картофеле при температуре 180 градусов в течение 40–45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6813,'Для начинки пропустить через мясорубку свинину и говядину в равных пропорциях, добавить репчатый лук. Соль и перец – по вкусу, влить немного холодной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6813,'Замесить постное дрожжевое тесто из муки, воды, «живых» дрожжей, сахарного песка, соли и растительного масла. Когда масса подойдет – обмять, вновь дать подняться, разделить на небольшие шарики размером с яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6813,'Раскатать шарики в лепешки, в центр каждой положить начинку, сформовать беляши, закладывая тесто складками  к центру. Жарить на раскаленной сковороде с маслом, сначала с той стороны, где отверстие. Беляши с мясным фаршем перевернуть, обжарить до корочки с другой стороны. Подать выпечку в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6814,'Плоды вымыть, обсушить, нарезать кружками. Выложить на блюдо, посолить и поперчить по вкусу. Смазать закуску майонезом, посыпать тертым твердым сыром. Запечь в течение 15 секунд в микроволновой печи, сыр должен немного расплавиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6815,'Кусочки куриной грудки отбить, посыпать солью и перцем, сухими травами, например, тимьяном. Делать это лучше под пленкой. Приготовить соус из сметаны, соли и перца, мелко нарубленного чеснока, сладкой дижонской горчицы и белого сухого вина. В соус также можно положить траву тимьяна. Смесь взбить, вылить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6815,'На отбитую курятину положить по кусочку тонко нарезанной ветчины такого же размера и по ломтику плавленого сыра для бутербродов. Сверху посыпать сушеным тимьяном, завернуть рулетами, выложить в соус. Рулеты можно для надежности скрепить шпажками. Посыпать тертым сыром. Печь рулетики из куриной грудки при температуре 200 градусов в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6816,'Для коржей нужно приготовить тесто из сырого яйца, банки сгущенного молока, пшеничной муки и погашенной уксусом пищевой соды. Сковороду разогреть, смазать растительным рафинированным или сливочным маслом. Если сковорода антипригарная, то жир не понадобится. Поочередно выпечь несколько коржей, с двух сторон, переворачивать аккуратно, лопаткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6816,'Готовые коржи обрезать с помощью тарелки до одинакового размера. Обрезки перемолоть в крошку.  Для приготовления крема сырые куриные яйца растереть с сахарным песком, ванилином. Всыпать муку, перемешать до однородного состояния. В полученную смесь тонкой струйкой влить молоко. Поставить массу на средний огонь, прогревать до загустения, постоянно помешивать. Как только крем начнет закипать – снять с огня, добавить сливочное масло и еще раз хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6816,'Для повседневного варианта торта промазать коржи горячим кремом, им же смазать верх и бока и посыпать крошкой от коржей. Для праздничной выпечки разделить массу на две части, в одну добавить какао-порошок. Промазать коржи, чередуя цвета. Две ложки «темного» крема оставить. Бока торта «Идеальный» намазать «белым» кремом, посыпать крошкой, верх смазать белым кремом, выровнять. В остатки «темного « крема добавить черный шоколад, прогреть, перемешать. Наполнить массой кондитерский шприц, поделить поверхность выпечки на 16 частей, зубочисткой «нарисовать» спираль от центра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Залить в керамической емкости дрожжи теплым молоком, размешать до однородности, добавить 1 яйцо, майонез, масло, подсолить и перемешать, постепенно всыпать в смесь предварительно просеянную муку, замесить мягкое тесто (но оно должно держать форму), отставит тесто на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Раскатать тесто в удлиненный эллипс, разложить вдоль одного края курицу и сыр. Аккуратно завернуть край, завернуть в рулет, сформовать из него тело змеи, выделить хвост и голову.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Переложить змейку на застланный пергаментом противень, выложить на спинке плетенку из теста, сделать из гвоздичек или можжевельника глаза, можно использовать и пару изюминок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Взбить яйцо, смазать спинку змеи и присыпать кунжутом, отправить в духовку, запекать при средней температуре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Когда горячий рулет «Змея» с начинкой из курицы и сыра будет готов, переложить на удлиненное блюдо, украсить листьями салата, дольками помидора и веточками зелени.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6817,'Эта закуска станет оригинальным украшением праздничного стола.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6818,'Очистить и нарезать клубни картофеля, всыпать в кипящую воду. Очистить морковь и репчатый лук, измельчить, обжарить на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6818,'В полуготовый суп с картофелем добавить плавленые сырки, перемешать, сыр должен разойтись. Добавить обжарку, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6818,'Стейк лосося нарезать, положить в суп, варить еще в течение семи минут. В конце добавить измельченную зелень, молотый перец, варить сырный суп три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6819,'Выложить в емкость две трети банки вареной сгущенки, вбить сырые куриные яйца, добавить сахарный песок, массу взбить с помощью миксера. Всыпать пшеничную муку, гашеную соду или разрыхлитель, перемешать. В почти готовое тесто всыпать крупно измельченные грецкие орехи, добавить изюм, можно обойтись без него. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6819,'Тесто вылить в чашу мультиварки, выставить режим «Выпечка» на 65 минут. Также можно выпечь пирог в духовке, в таком случае для приготовления понадобится 40 минут и температура 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6819,'Остатки вареной сгущенки залить молоком, нагреть до растворения. Готовый пирог с орехами залить этой смесью в горячем виде, дать пропитаться. Посыпать орехами и дать блюду постоять два часа при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6820,'Смешать сырое яйцо с молоком, залить смесью хлопья быстрого приготовления, оставить на полчаса для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6820,'Мелко нарезать репчатый лук, измельчить чеснок, добавить то и другое в готовый куриный фарш, перемешать до однородности. Добавить хлопья, соль и перец молотый – по вкусу, молотую паприку. Массу вымесить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6820,'Разогреть на сковороде растительное масло, куриные котлетки выкладывать ложкой. Жарить с двух сторон на сильном огне, затем его уменьшить и допечь блюдо под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6821,'Залить теплым молоком в керамической емкости дрожжи, хорошо перемешать, добавить по желанию яйца, сахар и все смешать, всыпать постепенно всю муку, должно получиться нежное и воздушное тесто, оставить его на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6821,'Раскатать из теста прямоугольник и разрезать на три узкие части, разрезать очищенный банан вдоль на две половины, затем каждую вдоль на три части, включить на разогрев духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6821,'Выложить на каждый прямоугольник теста друг за другом по три длинных кусочка банана, завернуть тесто в рулет, сформовать из него змейку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6821,'Застелить противень пергаментом, присыпать мукой и переложить змеек, смазать каждую взбитым яйцом и присыпать корицей, сделать из темных изюминок глаза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6821,'Запечь новогодние пирожки с бананом «Змейки» при средней температуре до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6822,'Смешать творог и сырые куриные яйца, всыпать сахарный песок и кокосовую стружку, лучше мелкую. Перемешать, выложить массу в форму и запечь в микроволновой печи в течение трех минут на максимальной мощности. Творожное «Баунти» можно посыпать сахарной пудрой и украсить ягодами вишни.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6823,'Разогреть смесь меда, сливочного масла и сахарного песка до полного растворения на тихом огне. Снять с плиты. Просеять через сито в равных пропорциях кориандр и гвоздику, добавить молотый или мелко нарезанный корень имбиря, перемешать, добавить корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6838,'Для приготовления салата нужно отварить свеклу насыщенного бордового цвета. Готовый корнеплод очистить и натереть на крупной терке.  Залить горячей водой чернослив, дать набухнуть, вынуть из воды, хорошо обсушить, удалить косточки, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6823,'В медовую смесь добавить соль и какао-порошок, смесь пряностей. Остудить массу до 40 градусов, вбить яйца, всыпать пшеничную муку, просеянную вместе с разрыхлителем. Замесить некрутое тесто, скатать его в «колобок», завернуть в пищевую пленку, поставить в холодильник на два-три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6823,'Рабочую поверхность посыпать мукой, тонко раскатать тесто, толщиной в шесть миллиметров. Вырезать с помощью формочки «человечков». Противень смазать маслом, выложить заготовки для пряников, печь в течение 10 минут при температуре 180 градусов. Переложить выпечку на решетку, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6823,'Приготовить глазурь из сахарной пудры с лимонным соком. Смешивать ингредиенты постепенно, лимонный сок можно заменить водой или молоком. Раскрасить пряничные человечки глазурью можно так, как подскажет фантазия: нарисовать глаза и рот, сделать контуры одежды, снежинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6824,'Для приготовления грибной начинки шампиньоны вымыть, очистить, нарезать кубиками. Жарить на растительном масле до готовности. Отдельно обжарить мелко нарубленный репчатый лук, добавить его в грибы, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6824,'Для мясной начинки промыть рис, отварить до готовности, должна получиться рассыпчатая каша. Отварить мясо в подсоленной воде с лавровым листом, перцем-горошком. Остудить, пропустить через мясорубку. Мелко нарезать репчатый лук, обжарить, добавить тертую морковь. Обжарку добавить в мясо вместе с рисом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6824,'Нарезать крупными кубиками клубни очищенного картофеля, отварить до готовности, воду посолить. Картофель отцедить, обсушить и растолочь в пюре, в нем не должно быть комочков. Вбить два яйца, всыпать пшеничную муку, вымесить эластичное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6824,'Мокрыми руками сформовать из картофельной массы лепешку, в середину положить мясную или грибную начинку, слепить зразу. Выложить на рабочую поверхность, посыпанную мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6824,'Отдельно взбить сырые куриные яйца, посолить и поперчить. Зразы обмакнуть во взбитое яйцо, обвалять в панировочных сухарях. Обжарить котлеты с растительным маслом на раскаленной сковороде, по три минуты с каждой стороны. Должна образоваться румяная корочка. Подать картофельные зразы в горячем виде со сметаной, соусом Тартар или чесночным, украсить зеленью петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6825,'Мясо мелко нарезать, выложить в огнеупорное блюдо. Посолить и поперчить по вкусу. Отдельно взбить сырые куриные яйца со сметаной, посолить, залить смесью филе. Нарезать помидоры кружками, уложить на запеканку. Печь в течение 30–40 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6826,'Просеять пшеничную муку, смешать с солью, сахаром, какао-порошком. Добавить сливочное масло и растереть массу в крошку, влить холодную воду, быстро замесить. Убрать в морозильную камеру на 15–20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6826,'Смешать творог с манкой и сахарным песком, вбить сырые яйца, перемешать массу с помощью блендера до однородного состояния. Дать постоять, крупа должна набухнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6826,'Смазать маслом форму для выпекания, выложить творожную смесь, любые свежие или размороженные ягоды, например, бруснику и вишню без косточек. Сверху – тертое на крупной терке замороженное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6826,'Печь пирог при температуре 200 градусов в течение получаса, затем огонь убавить на 20 градусов и допечь еще столько же. Готовую творожную запеканку с тертым тестом остудить в форме, затем переложить на тарелку. Посыпать сахарной пудрой и украсить свежими ягодами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6827,'Хорошо взбить сырые куриные яйца, сахар и ванилин из пакетика. Влить растительное масло, молоко, всыпать какао-порошок. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6827,'Смешать просеянную пшеничную муку и разрыхлитель. Сухую смесь всыпать в жидкую, соединить с помощью миксера. Вылить готовое тесто в форму для выпечки, среднего размера, печь при температуре 180 градусов в течение 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6827,'Для приготовления крема понадобится шоколадная паста Нутелла или нуга. Растопить на водяной бане темный шоколад, добавить пасту. Отдельно взбить сливки, положить в крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6827,'Разрезать выпеченный корж по горизонтали на три части, промазать готовой массой. Поставить выпечку на ночь в холодильник. Приготовить глазурь из растопленного шоколада и жирных сливок. Полить смесью шоколадный торт, посыпать шоколадной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6828,'Отварить рис и выложить в креманки. Намазать майонезом. Нарезать кубиками слабосоленую семгу, сверху – майонез. Порубить укроп, посыпать салат, снова смазать майонезом. Натереть по отдельности вареные желтки и белки, выложить в таком же порядке на салат «Сама нежность», также промазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Отварить филе курицы, остудить в бульоне (мясо будет более мягким), нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Сварить в мундире картофель и морковь, облить холодной водой, почистить и дать остыть, картофель нарезать небольшими кубиками, присолить, морковь оставить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Сварить яйца, остудить, почистить, разделить на белки и желтки, белки натереть на мелкой терке, желтки не нужны, можно использовать для другого салата, мелко порубить маринованные грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Выложить салат на плоское блюдо слоями: грибы, мясо, картофель, белки, каждый слой и бока смазывать майонезом (кроме последнего).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Сделать из кружков моркови щеки, из отрезанной вдоль пластинки – нос, из брусочков выложить рот, из маслин оформить глазки и реснички.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6829,'Салат куриный с картофелем и грибами «Снеговик» перед подачей на стол должен пропитаться минимум 1 час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6830,'Порезать мякоть свинины на кубики примерно по 30 г, подсолить и зажарить их до аппетитной корочки на разогретом свином жире.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6830,'Добавить мелко нарезанный чеснок и лук к мясу, очистит от кожицы и семян помидоры, нарезать и переложить к остальным ингредиентам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6830,'Очистить сладкий перец от семян, нашинковать тонкой соломкой и высыпать в сковороду, все посолить, поперчить, добавить по вкусу мелко порезанный острый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6830,'Перемешать содержимое сковороды и тушить 15 минут, далее влить вино и дать смеси закипеть, накрыть крышкой, снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6830,'Горячая токитура по-румынски со свининой подается к столу с мамалыгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Разрезать огузок говядины на пластины по 1,5-2 см, тонко отбить, втереть смесь соли и перца, оставить пропитаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Нарезать кубиками морковь, корень сельдерея, нашинковать лук, обжарить все на растительном масле вместе с нарезанной корейкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Добавить нарубленную зелень петрушки, смесь посолить, поперчить и перемешать, включить на разогрев духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Выложить ложкой на кусочки говядины смесь и свернуть в рулеты, скрепить зубочистками, но можно перевязать нитками (перед подачей удалить), обжарить с разных сторон в раскаленном масле, влить бульон и убрать в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Сварить из бульона, томатной пасты с мукой и масла соус, заправить его солью и перцем, добавить вино, прокипятить 15 минут, процедить, залить им зразы говяжьи с овощами и тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6831,'Подать на гарнир к зразам лучше всего рассыпчатый рис или картофель.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Нарезать окорок на 10 пластинок, аккуратно отбить с двух сторон, присолить и поперчить, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Порезать мелко лук и обжарить, добавить нарезанные грибы (отварные сушеные -предварительно отжать), тушить пока не испарится вся жидкость, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Смешать луково-грибную смесь с порубленной зеленью петрушки и измельченным яйцом, посолить и поперчить, все перемешать, включить разогреваться духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Выложить по ложке грибной начинки на каждый кусочек мяса и свернуть их в рулет (края мяса спрятать внутрь), скрепить зубочистками или обвязать нитками, перед подачей на стол не забыть их удалить, переложить рулетики в кастрюлю с разогретым маслом и убрать в духовку на 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Приготовить из бульона, муки и масла соус, тщательно размешать, чтобы не было комочков, прокипятить 15 минут и влить сметану, дать закипеть и процедить соус, залить зразы соусом и тушить еще 20 минут в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6832,'Подать зразы из свиного окорока с грибами с рассыпчатым рисом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Натереть на средней терке вареную свеклу, отжать сок, смешать с измельченными жареными орехами и специями, сварить белую фасоль и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Поджарить в оливковом масле пропущенный через пресс чеснок, добавить его в свеклу и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11231,'Всыпать муку порциями, помешивать ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Поставить по центру плоского блюда стакан, выложить вокруг кольцом половину фасоли (оставить 1 ст.л. для украшения), сверху слой равномерно смазать половиной йогурта, выложить на него половину свеклы (1 ст.л. сохранить для украшения), все слои повторить и осторожно вытащить стакан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6833,'Украсить закусочный торт из свеклы с орехами и йогуртом веточками укропа и «ягодами» из фасоли и свеклы, перед подачей на стол торт должен настояться 1 час (лучше больше).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6834,'Отварить по отдельности курицу и говядину, дать остыть и нарезать вместе с огурцом соломкой, все слегка подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6834,'Натереть крупно яйцо и сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6834,'Для соуса смешать не острый кетчуп и майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6834,'Салат выкладывать на блюдо слоями: мясо говядины, куриное мясо, ветчина, соленый огурец, яйцо, сыр, каждый слой смазать соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6834,'Сверху оформить мясной салат-ассорти «Новогодний каприз» гранатовыми зернами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6835,'Ванильный сахар хорошо перемешать с обычным сахарным песком. Добавить сырые куриные яйца и дополнительные желтки, взбить, масса должна увеличиться в два-три раза. В смесь всыпать просеянную пшеничную муку, какао-порошок, осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6835,'Оставшиеся два сырых белка хорошо взбить со щепоткой соли и остатками сахара до плотной, гладкой, пены. Массу аккуратно ввести в тесто, перемешивать движениями снизу вверх. Застелить противень бумагой или положить «коврик» из силикона. Вылить приготовленное тесто, печь в течение 10–12 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6835,'Готовый корж снять с противня, удалить бумагу и немного охладить. Для крема смешать миксером сыр маскарпоне и сгущенное молоко, масса должна стать однородной. Остывшую выпечку разрезать на два коржа по горизонтали, острым ножом. Промазать кремом. Подровнять края, готовый торт разрезать на пирожные. Растопить шоколад на водяной бане и смазать им верх и бока. Поставить пирожные а-ля «Киндер Дэлис» в холодильник на 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6836,'Просеять в большую емкость пшеничную муку. Отдельно, в воде, растворить сахар и соль. В муке сделать «лунку», влить раствор, небольшое количество водки, растительное масло. Массу хорошо вымесить, обернуть пищевой пленкой, оставит на час при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6836,'Для начинки лучше всего использовать говяжье и баранье мясо в свежем виде, вместе или один из этих видов. Если мясо мороженое, то его нужно оттаивать в холодильнике в течение 12 – 24 часов, в таком случае потери мясного «сока» будут минимальными.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6836,'Мясо и внутренний говяжий жир пропустить через мясорубку с крупной решеткой. Порубить очищенный репчатый лук, истолочь  острым ножом. Перемешать с фаршем, добавить рубленую кинзу или петрушку, соль, черный молотый перец, зиру. Массу перемешать, попробовать на вкус, при необходимости можно досолить. Влить в фарш полтора стакана воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6836,'Раскатать тесто скалкой в очень тонкую лепешку толщиной три миллиметра. Нарезать с помощью блюдца круги среднего диаметра. Выложить на середину фарш, сложить пополам и защипать края. Жарить хрустящие чебуреки с бараниной и говядиной в большом количестве масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6837,'Мягкое сливочное масло комнатной температуры взбить миксером. Всыпать сахарную пудру, снова взбить. Добавить пасту Нутелла и еще немного взбить. Отделить сырые белки от желтков. Последние добавить в ореховую массу, продолжать взбивать. Всыпать пшеничную муку, просеянную вместе с какао-порошком и разрыхлителем, молотый фундук, влить молоко. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6837,'Оставленные белки взбить с помощью миксера. Третью часть получившейся массы добавить в основную смесь, аккуратно перемешать. Затем добавить вторую треть белков, в конце замеса–остатки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6837,'Емкость для мультиварки смазать растительным маслом, вылить тесто. Готовить в течение 50 минут в режиме «Выпечка». Блюдо вынуть, остудить 10 минут, вынуть пирог и остудить на тарелке окончательно. Нагреть в микроволновой печи темный шоколад вместе со сливочным маслом, несколько раз перемешать. Получившейся однородной массой смазать шоколадный пирог с Нутеллой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7436,'Хорошо прогреть сковороду с маслом, сделать умеренный огонь, ложкой выложить оладушки из печени, обжарить с каждой стороны до чуть коричневой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6838,'Мелко нарезать соленые огурцы. Чеснок очистить, нашинковать, а затем растереть. Натереть очищенное от кожицы и семян яблоко. Грецкие орехи немного прогреть в духовке, натереть или истолочь. Все ингредиенты соединить, перемешать, заправить майонезом по вкусу. Верх салата «Пиковая дама» можно посыпать рублеными грецкими орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6839,'В теплом молоке смешать дрожжи с сахарным песком, оставить в тепле на 10 – 15 минут. Вместо молока можно взять воду. Растопить сливочное масло, смешать его с помощью венчика с яичным желтком. Всыпать муку, немного соли, влить дрожжевую смесь. Массу перемешать, замесить тесто. Положить «колобок» в емкость, смазанную растительным маслом, оставить в тепле на полтора – два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6839,'Для приготовления начинки растопить сливочное масло, всыпать сахарный песок и молотую корицу. Тонко раскатать тесто толщиной в один сантиметр, выложить две трети начинки. Свернуть в рулет, положить швом вниз, прижать. Разрезать заготовку вдоль, не дорезая до конца один-два сантиметра. Половины рулета переплести между собой и сформовать круг. Булочку с корицей смазать остатками начинки, печь при температуре 200 градусов в течение 20–25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6840,'Просеять муку, соединить с разрыхлителем и ванильным сахаром из пакетика. Отдельно взбить венчиком сырые куриные яйца с сахарным песком. Добавить в массу мягкое сливочное масло, перемешать. Следующий ингредиент – сметана, вновь перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6840,'Просеять пшеничную муку с разрыхлителем, всыпать в яичную смесь, замесить тесто, оно должно получиться мягким. Скатать массу в «колобок» положить в холодильник на два-три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6840,'Готовое холодное тесто вынуть, раскатать на посыпанной мукой рабочей поверхности в пласт толщиной 4 – 8 мм, вырезать с помощью формочек печенье. Чтобы тесто не прилипало, формы нужно посыпать мукой, вместо них можно воспользоваться обычной рюмкой или просто разрезать пласт из теста на квадраты или ромбики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6840,'Выложить изделия на сухой противень, печь печенье «Сметанное» в духовке при температуре 180 градусов в течение 15–20 минут. Готовую выпечку посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6841,'Очистить и тонко нарезать клубни картофеля. Присыпать солью. Также очистить репчатый лук, разрезать его пополам, порубить. Острым ножом нарезать томаты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6841,'На сковороду налить две ложки оливкового масла, разогреть. Обжарить на среднем огне картофель в течение пяти минут, помешивать. Всыпать рубленый лук, перемешать, тушить под крышкой на небольшом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6841,'Отдельно взбить вилкой сырые яйца, соль и молотый перец – по вкусу. Всыпать содержимое сковороды, добавить зеленый горошек  и помидоры. Влить еще немного растительного масла, греть на среднем огне в течение минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6841,'Смесь перелить в сковороду, огонь убавить до минимума, прогревать в течение 15 минут. Когда жидкость испариться – омлет перевернуть, готовить еще пять минут. Подавать картофельную тортилью в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6842,'Промыть гречку, обсушить, прокалить на сухой сковороде. Залить продукт 2,5 литрами воды, положить в суп крупную луковицу целиком, варить на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6842,'Измельчать свежие овощи и постепенно добавлять в суп. Натереть морковь. Болгарские перцы красного и зеленого цвета нарезать кубиками. Помидоры измельчить, добавить в суп вместе с вытекшим соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6842,'Для фрикаделек смешать говяжий фарш с сырым куриным яйцом, всыпать измельченный репчатый лук, молотую паприку, соль и перец – по вкусу. Массу перемешать, сформовать фрикадельки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6842,'Огонь увеличить, всыпать мясные изделия, луковицу вынуть. Варить 7–10 минут. В конце приготовления добавить давленый чеснок, лавровый лист, соль, огонь выключить, варить еще 10–15 минут. Подать гречневый суп с мясными фрикадельками с измельченным укропом и нарезанным зеленым луком, поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6843,'Шампиньоны нарезать небольшими кусочками, обжарить до готовности на растительном масле. Свиное филе нарезать на куски и хорошо отбить, обжарить до появления золотистой корочки. На крупной терке натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6843,'Обжаренные отбивные выложить в форму, сверху – грибы. Посыпать блюдо тертым сыром, печь свинину с шампиньонами в духовом шкафу до появления корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6844,'Из булочек для хот-догов вынуть мякиш, покрошить. Нарезать кубиками сыр и колбасу, перемешать с хлебной массой, влить майонез. Полученной смесью нафаршировать булочки, запечь в духовом шкафу до готовности. Готовое блюдо можно посыпать свежей зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6845,'Творог протереть через сито или взбить с помощью блендера до однородности. Добавить сметану, манную крупу, сырые куриные яйца, сахарный песок. Массу перемешать до однородного состояния. Форму для выпекания смазать растопленным сливочным маслом, вылить готовое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6845,'Блюдо поставить в заранее разогретую до 180 градусов духовку на 30–50 минут. Должна образоваться золотистая корочка. Запеканку остудить. Для приготовления ягодного соуса положить в сотейник замороженные ягоды клубники и вишни, поставить на тихий огонь. Когда масса согреется – добавить сахар, помешивая, довести смесь до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6845,'Сахарный песок должен полностью раствориться. В небольшом количестве воды развести картофельный крахмал, вылить в ягоды, помешивать. Уварить соус до густоты и немного остудить. Полить смесью готовую творожную запеканку, украсить ложкой густой сметаны и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6846,'При помощи миксера взбить сырые куриные яйца с сахарным песком, должна получиться пышная масса однородной консистенции. Всыпать просеянную пшеничную муку и ванильный сахар из пакетика, продолжать взбивать. Готовое тесто выложить в заранее смазанную растопленным сливочным маслом форму для выпекания, лучше, если она будет разъемной. Печь в течение 40 минут при температуре 220 градусов. Бананы и киви, яблоки и апельсины очистить и нарезать максимально тонкими ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6846,'Чистую форму застелить пищевой пленкой. В небольших формочках приготовить цветные желе, так, как написано на пакетиках, воды наливать немного, масса должна получиться плотной. Два вида желе остудить в холодильнике, одно – при комнатной температуре. Готовый корж разрезать по горизонтали острым ножом. Одну половину пропитать частью жидкого желе, смазать сгущенным молоком и посыпать рублеными грецкими орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6846,'Накрыть сверху второй половиной коржа, который также нужно пропитать желе и посыпать орехами. Сверху равномерно выложить ломтики фруктов, на них – охлажденное желе. Поставить десерт на 15 минут в холодильник. Готовое блюдо полить остатками третьего желе. Поставить разноцветный желейно-фруктовый торт в холод еще на 6 – 8 часов, до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6847,'Хорошо промыть лимон под струей холодной воды, обсушить, натереть цедру. Из мякоти выдавить сок. Промыть зелень петрушки, нашинковать. Очистить чеснок и нарубить. Смешать в емкости сушеный орегано, сметану, лимонный сок, цедру, чеснок, растительное масло, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6847,'Массу перемешать до однородного состояния. Всыпать петрушку, снова перемешать. Куриные голени хорошо промыть, обтереть с помощью бумажных полотенец, кожу можно срезать. В пластиковый или полиэтиленовый пакет положить куриное мясо, перелить маринад. Плотно закрыть, перемешать, поставить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6847,'Затем выложить маринованную курицу в форму для запекания, печь в нагретой до 180 градусов духовке в течение 45–60 минут. Блюдо должно покрыться румяной корочкой. Готовые куриные ножки в сметанном маринаде достать из духовки и подать в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6848,'Взбить мягкое сливочное масло с сахарным песком и яйцом. Добавить просеянную пшеничную муку, разрыхлитель, кукурузный крахмал, сделать это в два приема. Выложить готовое тесто в кондитерский мешок с насадкой диаметром в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6848,'Отсадить на смазанный сливочным маслом противень печенье в виде завитков, спиралек, на расстоянии три сантиметра друг от друга. Печь в течение 10 минут при температуре 200 градусов. Приготовить крем из взбитых сливок с сахарной пудрой. Выпечку полностью остудить и прослоить печенье «Ванильные поцелуи» кремовой массой, «склеивая» печенье по две штуки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6855,'Тонкий армянский лаваш положить на смазанный маслом или застеленный пергаментом противень. Смазать кетчупом, сверху – тонкий слой любого фарша с луком, специями, солью. Поставить в нагретую духовку, печь в течение пяти минут при температуре 175 градусов. В горячем виде скрутить лепешку в трубочку. Блюдо подать к бульону или к шурпе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6849,'Воду довести до кипения, добавить лавровый лист, душистый перец, крупные куски стебля сельдерея, специи для куриного мяса, соль – по вкусу. Положить куриное филе, варить в течение 20 минут с момента закипания. Огонь выключить, мясо остудить в бульоне. Тонкими кружочками нарезать помидор, остывшее филе – пластинками. Пропустить через пресс очищенные зубчики чеснока, смешать с курицей.  Пластинками средней толщины нарезать лекгоплавкий сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6849,'Разморозить готовое слоеное или дрожжевое тесто, нарезать на восемь одинаковых квадратов, немного раскатать. На один край лепешек положить куриное мясо, на него – по ломтику помидора, сверху – сыр, смесь перцев и «итальянские травы» или мелко нарезанную зелень. Тесто сложить пополам, накрыть начинку и хорошо защипать, руками или с помощью вилки. Готовые слойки выложить на застеленный бумагой противень, можно воспользоваться силиконовым ковриком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6849,'Противень с заготовками для выпечки затянуть пищевой пленкой, поставить в тепло на 40 минут. Слойки должны увеличиться в объеме. Смешать сырой желток с небольшим количеством воды. Смесью смазать булочки, посыпать кунжутом. Печь блюдо в разогретой духовке при температуре 190–200 градусов в течение 12–15 минут, до готовности. Слойки с куриным филе, помидорами и сыром должна приобрести золотистую корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6850,'Готовое слоеное тесто раскатать в тонкую лепешку по размеру противня. Застелить поверхность бумагой для выпекания, выложить заготовку для пиццы, смазать томатной пастой. Сверху – колбаса Пепперони, нарезанная тонкими кружками. Сверху полукольца репчатого лука, кружки помидоров, нарезанные оливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6850,'Посыпать поверхность толстым слоем тертого сыра. Печь блюдо в духовке при температуре 200 градусов в течение 15 – 20 минут, до готовности. Домашнюю пиццу с колбасой Пепперони вынуть, немного остудить, нарезать на порции и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6851,'Противень застелить пищевой фольгой, смазать маслом. Смешать зерновую и обычную дижонскую горчицу, оливковое масло, растопленное сливочное масло, лимонный сок, давленый чеснок, сухой орегано, цедру лимона, соль – по вкусу. Массу взбить венчиком до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6851,'Выложить в маринад очищенный и нарезанный дольками картофель, его можно поперчить и еще немного посыпать крупной солью. Перемешать, смесь выложить на противень в один слой, печь в течение 20 минут при температуре 220 градусов. Затем противень перевернуть, печь еще 25 минут при той же температуре, до образования золотистой корочки. Подавать пряный картофель в горчице в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6852,'Отварить свеклу, очистить, нарезать на небольшие кусочки. Измельчить с помощью блендера вместе с майонезом, солью и молотым кориандром, до состояния пюре. Влить немного лимонного сока по вкусу. Желатин замочить в холодной воде, так, как написано на пакетике, дать набухнуть, прогреть, но не кипятить, влить в свекольную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6852,'Снова взбить блендером. Из ржаного хлеба вырезать круглые заготовки. Малосольное филе сельди очистить, удалить кости, нарезать на кусочки. Выложить в металлические кольца для десертов слоями хлеб, сельдь, свекольный мусс. Поставить сельдь под шубой «Новогодние свечи» на час в холодильник, при подаче кольца снять, украсить зеленью, кусочками лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6853,'Мягкий маргарин размять вместе с творогом, пшеничной мукой, ванилином из пакетика. Готовое тесто тонко раскатать, вырезать кружки с помощью стакана. Одну сторону обмакнуть в сахарный песок, сложить «сахарной» стороной внутрь, свернуть вчетверо. Верх также посыпать сахаром  и хорошо подрумянить в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6854,'Растереть пшеничную муку с замороженным маргарином, натертым на крупной терке. Добавить творог, замесить тесто, оно не должно быть слишком крутым. Разделить массу на две части, поставить в холодильник на два часа. Отдельно взбить два сырых белка с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6854,'Охлажденное тесто тонко раскатать в прямоугольник, смазать белковой массой, посыпать очищенными и измельченными грецкими орехами. Свернуть рулетом, смазать желтком со всех сторон, разрезать кусочками толщиной в один-полтора сантиметра. Выложить заготовки для печенья срезом вниз на противень, на расстоянии друг от друга. Печь печенье «Розочки» до готовности при температуре 190 – 200 градусов в течение 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6856,'Домашней творог смешать с сырыми куриными яйцами, цедрой цитрусовых и специями, растереть. Если творог зернистый, то его лучше заранее измельчить с помощью блендера. Всыпать заранее замоченный изюм, его можно подержать не в воде, а в ароматном чае. Добавить хлопья или отруби, оставить тесто на полчаса. Если масса получается суховатой, добавить немного сметаны или молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6856,'Для выпечки понадобятся формочки из силикона, их не нужно смазывать или присыпать мукой. Выложить творожное тесто, утрамбовать, печь в течение 20 минут при температуре 180 – 200 градусов. Вынуть полезные сырники из формочек и подать со свежими ягодами черешни, вишни, малины, ежевики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6857,'Печень вымыть, нарезать средними кусочками, выложить в дуршлаг и дать обтечь. Мелко нарезать репчатый лук, обжарить на сковороде с растительным маслом. Очистить апельсины, удалить белую прослойку, мякоть нарезать кубиками, положить в луковую массу. Раздавить боковой стороной ножа очищенный чеснок, также добавить в лук. Посыпать смесь солью, молотым мускатным орехом, жарить все вместе в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6857,'Добавить печень, массу перемешать, жарить на сильном огне еще пять минут, помешивать. Огонь убавить, тушить блюдо под крышкой еще 20 – 25 минут. Следующий ингредиент – каперсы, прогреть пять минут. Рис промыть в холодной воде, она должна стать прозрачной. Откинуть крупу на дуршлаг. Выложить в кипящую воду, варить под плотно закрытой крышкой в течение 12 минут в таком порядке: три минуты – на сильном огне, девять – на маленьком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6857,'Огонь выключить, подождать еще 12 минут, крышку не открывать. Затем положить сливочное масло, посолить по вкусу и перемешать. С помощью разъемной формы выложить рис на хорошо вымытые и обсушенные листья зеленого салата в виде «башенки». Украсить тонким кружком апельсина. Вокруг риса – куриная печень с каперсами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6858,'Сырые куриные яйца взбить в пену с помощью миксера. Добавить сахарный песок, соль, еще раз хорошо взбить. К массе добавить сухое молоко, просеянную пшеничную муку и пищевую соду. Должно получиться жидкое тесто, консистенция такая, как на блины. На противень постелить бумагу для выпечки, вылить тесто тонким слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6858,'Печь в течение 5–7 минут при температуре 180 градусов. Но полученный «корж» намазать вареное сгущенное молоко тонким слоем, положить очищенный банан целиком и быстро, пока выпечка не остыла, свернуть в рулет. Сверху быстрый рулетик посыпать тертой шоколадной или кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6859,'Песочное печенье, например, со вкусом топленого молока, немного поломать, измельчить в крошку с помощью блендера. Таким же образом измельчить цукаты и миндальные орехи. Все сухие ингредиенты сложить в одну емкость, влить немного рома и перемешать. Вмешать небольшими порциями сыр Маскарпоне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6859,'Тесто должно получиться пластичным. Сформовать конусы-елочки, размер – на вкус кулинара. Воткнуть шпажки на два сантиметра в основание каждого конуса, получившиеся заготовки охладить в холодильнике в течение получаса. Распустить на водяной бане белый шоколад. Для приготовления блюда понадобится кусок пенопласта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6859,'На охлажденные елочки с помощью кондитерской кисти нанести шоколад, сразу же обмакнуть в смесь фисташковых орехов кондитерской посыпки в виде жемчужин, это будут елочные игрушки. Готовые пирожные на палочке «Рождественская елочка» воткнуть в пенопласт для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6860,'В большой емкости смешать индюшачий фарш, куриные яйца, панировочные сухари, сушеный орегано и мелко нарубленный свежий базилик. Добавить семена тмина, дижонскую горчицу, чесночную соль, черный молотый перец, кайенский красный перец и хлопья красного перца. Массу хорошо перемешать, слепить небольшие шарики. Противень смазать маслом, печь в течение 15 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6860,'Для приготовления соуса нагреть сковороду на среднем огне, вылить на нее томатный соус, добавить нарубленный свежий базилик, орегано, хлопья красного перца, нарезанные грибы, сыр Моцарелла, нарезанный большими кусками. Прогревать до загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Взять чайную ложечку с верхом дрожжей. Просеять в емкость муку, насыпать дрожжи, перемешать (можно растворить дрожжи в молоке), помешивая налить теплое молоко тоненькой струей, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6860,'Готовые фрикадельки переложить в соус, полить каждый шарик полученной смесью, сверху положить целые листья базилика. Сыр выложить в любом порядке. Прогревать фрикадельки из индейки в течение пяти минут на среднем огне, до расплавления сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6861,'Мягкое сливочное масло взбить с сахарным песком. Отделить желтки от белков, первые добавить в масляную смесь, хорошо взбить. Всыпать миндальную муку, цедру лайма и лимонный сок. Добавить ванильную эссенцию или ванилин из пакетика, массу снова хорошо перемешать. Отложенные белки взбить в плотную пену, осторожно вмешать в основную смесь, перемешивать движениями снизу вверх. Должна получиться пышная однородная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6861,'Форму для выпекания смазать растопленным сливочным маслом. Вымыть свежие абрикосы, удалить косточки, нарезать плоды на четвертинки. Выложить фрукты в форму, посыпать сахарным песком, можно использовать коричневый сахар, это придаст выпечке карамельный привкус. Тесто выложить сверху, на абрикосы, печь в течение 35–40 минут при температуре 170 градусов. Миндальный пирог с абрикосами должен покрыться золотистой корочкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6862,'Мягкий маргарин растереть с сахарным песком и сырыми куриными желтками. Белки взбить в пену отдельно, добавить в желтковую массу, перемешать. Влить погашенную уксусом соду. Постепенно, порциями, ввести пшеничную муку, тесто должно получиться мягким, но не липнущим к рукам. Поставить его в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6862,'Нагреть формочку для выпечки, смазать маслом. Из теста слепить «орешки», размером меньше грецкого ореха. Выпечь до готовности. Для начинки смешать вареную сгущенку, любые рубленые орехи, обломки от выпечки. В каждую половинку положить в орешки начинку и соединить по две.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6863,'Мясо нарезать кусками произвольного размера и формы, выложить в форму для запекания. Очистить репчатый лук, нарезать полукольцами и положить сверху. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6863,'Для приготовления соуса растопить на сковороде с толстым дном 100 г сливочного масла, добавить пшеничную муку. Массу хорошо перемешать, в ней не должно быть комочков. Влить молоко тонкой струйкой, соус посолить и поперчить, добавить немного молотого мускатного ореха. Варить массу до загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6863,'Полить третьей частью смеси мясо с луком. Нарезать произвольно сырые шампиньоны, выложить на лук, также полить соусом. Следующий слой – помидоры, полить остатками соуса. Сверху свинину с овощами под соусом посыпать тертым сыром, печь в течение 45 – 50 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6864,'Целую тушку рыбы весом от двух до трех килограммов вымыть под проточной водой, удалить внутренности, жабры, чистить не нужно. Вымыть зелень петрушки и укропа, также вымыть и нарезать кольцами свежий лимон. Противень застелить фольгой в два слоя, высыпать на нее половину нормы каменной соли. Толстолобика уложить сверху, вставить в жабры по колечку лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6864,'Брюшко натереть небольшим количеством соли, положить зелень, целыми веточками, кольца лука и лимона. Сверху, на тушку, насыпать оставшуюся соль, завернуть в фольгу. Печь блюдо в течение часа или полутора при температуре 180 градусов. Противень вынуть, фольгу снять, соль счистить, она снимется вместе со шкуркой. Запеченный толстолобик можно подавать как в горячем, так и в холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6865,'Отделить белки от желтков. Первые взбить в крепкую пену, продолжая взбивать, всыпать сахарный песок и, по одному, ввести желтки. Масса должна увеличиться в объеме. В смесь добавить разрыхлитель, манку, пшеничную муку, осторожно перемешать. Форму или сковороду с высокими бортиками смазать маслом и присыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6865,'Вылить тесто, печь при температуре 180 градусов в течение 20–25 минут. Готовность выпечки проверить зубочисткой. Молоко довести до кипения, но не кипятить, добавить ванилин и сахар, перемешать. Немного остывший сербский кох нарезать на части и полить молоком, жидкость должна полностью впитаться. Блюдо охладить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6866,'Смешать пшеничную муку, соль и разрыхлитель. Отдельно взбить мягкое сливочное масло с сахаром. Добавить яйцо, ванилин, свежий лимонный сок, взбивать массу в течение 20–30 секунд с помощью миксера. Добавить муку небольшими порциями, продолжать взбивать на низкой скорости. Вмешать кунжут, его можно заранее немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6866,'На противень постелить бумагу для выпечки, выложить лепешки на некотором расстоянии друг от друга. Печь в течение 8 – 15 минут при температуре 180 градусов. Через шесть минут после начала выпечки можно перевернуть на другую сторону. Остудить кунжутное печенье, подать к чаю или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6867,'Взбить сырые куриные яйца с сахарным песком в крепкую пену. На мелкой терке измельчить свежую морковь, цедру апельсина. Отдельно просеять пшеничную муку, всыпать молотую корицу и тертый мускатный орех. Изюм замочить в теплой воде, дать набухнуть, затем жидкость слить, продукт обсушить на бумажных полотенцах, обвалять его в муке. В яичную массу добавить растительное масло и несколько капель ванильного экстракта, морковь. Перемешать, всыпать изюм, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6867,'Погасить пищевую соду уксусом или лимонным соком, ввести в тесто, затем всыпать мучную смесь со специями, перемешать до однородного состояния, в массе не должно быть комочков. Форму для выпекания смазать растительным маслом, влить полученное тесто, печь при температуре 180–190 градусов в течение 45 минут. Готовность выпечки проверить зубочисткой или любой деревянной палочкой. Остудить пирог в форме, в течение 15 минут, затем вынуть и выложить на решетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6867,'Для приготовления лимонного крема натереть цедру с половины хорошо вымытого лимона, из мякоти выдавить сок. Отдельно взбить сгущенное молоко со сметаной, через пять минут добавить часть натертой лимонной цедры, влить тонкой струйкой лимонный сок, массу продолжать взбивать. Крем должен загустеть. Выложить его поверх остывшего морковного пирога, разровнять, пусть часть массы стечет на бока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6868,'Для приготовления сыра лучше использовать настоящее домашнее молоко. Вскипятить жидкость. Отдельно взбить сырые куриные яйца со сметаной, всыпать соль и специи, можно использовать паприку, адыгейскую соль, сушеный или свежий чеснок, зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6868,'В кипящее молоко вылить яично-сметанную смесь, поварить до тех пор, пока сгустки всплывут, а жидкость осядет. Массу вылить в застеленный марлей дуршлаг, дать стечь сыворотке, можно поставить груз на час. Затем домашний сыр вынуть, марлю снять, накрыть тарелкой или крышкой, охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6869,'Поломать темный горький шоколад на кусочки, добавить сливочное масло, массу растопить на водяной бане, затем остудить в течение двух – трех минут. Белки оделить от желтков, последние хорошо перемешать, а белки взбить в пену вместе со щепоткой соли. Влить желтки в шоколад, перемешать, затем готовую массу влить в белки, порциями, осторожно перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6869,'Готовый шоколадный мусс разлить в формочки или чашки, поставить в холодильник на два часа или больше. За 15 минут до подачи блюда на стол вынуть его из холодильника, дать десерту согреться при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6870,'Для приготовления начинки замочить в теплой воде сухофрукты: курагу, чернослив без косточек, сушеную вишню, вяленые яблоки, нарезанные кольцами. Каждый сухофрукт замачивать отдельно. Можно заливать не теплой водой, а кипятком, если продукты слишком сухие. При готовности жидкость слить, ягоды и фрукты перемолоть с помощью блендера или пропустить через мясорубку, также каждый отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6870,'Для теста смешать сахарный песок со сметаной, добавить сырые куриные яйца и разрыхлитель. Всыпать порциями просеянную пшеничную муку. Вымесить массу ложкой, а затем руками, продолжать подсыпать муку до тех пор, пока масса перестанет быть липкой. Тесто должно быть эластичным, но мягким, скатать его в шар и поставить в холодильник в емкости под крышкой на полчаса или час. Готовое охлажденное тесто разделить на восемь частей. Каждую раскатать в лепешку прямоугольной формы на присыпанной мукой рабочей поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6870,'На тесто выложить разную начинку, каждую лепешку свернуть в рулет, начиная от широкой стороны к центру, сложить их в виде «книжки», защипнуть концы. Противень застелить бумагой, выложить заготовки, печь до получения румяного цвета при температуре 180 градусов. Готовую выпечку остудить, нарезать нетолстыми кусочками в два сантиметра шириной, разложить в разные тарелки, чтобы не перепутать начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7460,'В кастрюлю налить вино, поставить ее на средний огонь и нагреть спиртное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Смешать в емкости сахар, нарезанные лимон и яблоки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6870,'Дно разъемной формы выстелить бумагой, зажать кольцом, лишнюю бумагу обрезать, оставить края в два-три сантиметра. Приготовить крем из сметаны и сахарного песка. Каждый кусочек выпечки обмакивать в сметанную массу, выкладывать в форму в любом порядке. Остатки крема вылить сверху. Форму накрыть, поставить в холод на 10 – 12 часов. Если весь крем впитается, можно долить сверху еще немного сметаны с сахаром. Готовый торт вынуть из формы, с помощью ножа отделить его от стенок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6870,'Кольцо снять, торт выложить на большое блюдо, бумагу на дне можно оставить. Приготовить помадку из молока, сахара, сливочного масла, прогреть смесь в толстостенной кастрюле. Поломать кусочками темный шоколад, положить в массу, прогреть на тихом огне до полного растворения шоколада. Массу снять с огня, немного остудить и залить охлажденный торт, лучше это делать с помощью ложки, глазурь должна растечься на бока. Украсить новогодний торт «Трухлявый пень» готовыми шоколадными «грибами».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6871,'Сырое куриное яйцо смешать с сахарным песком, массу взболтать вилкой. Влить молоко и растительное масло, снова взбить. Отдельно смешать пшеничную муку, картофельный крахмал, какао-порошок, разрыхлитель. Смесь просеять в жидкие ингредиенты, замесить тесто, оно должно быть жидким по консистенции. На дно формы для выпечки положить лист пергамента, вылить приготовленное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6871,'Печь в микроволновой печи при мощности в 1000 Вт в течение трех минут. Отделить ножом выпечку от стенок формы, выложить корж на решетку, остудить, затем разрезать по горизонтали на две-три части. Для приготовления крема взбить сметану с сахарным песком, промазать массой коржи. Верх бисквита за 3 минуты украсить тертым темным шоколадом и свежими ягодами любого сорта, например, вишней или черешней, ежевикой, малиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6872,'Очистить репчатый лук, нарезать тонкими полукольцами. Порубить чеснок. Смешать в миске чеснок, белые сухари для панировки, сушеные травы: базилик, орегано, петрушку, добавить соль. Влить сырые куриные яйца, перемешать. Добавить тертый сыр, снова перемешать, должна получиться однородная масса. Говядину разрезать вдоль волокон широким ножом, не до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6872,'Пласт посолить и поперчить, выложить начинку и равномерно распределить по поверхности. Свернуть филе в рулет, перевязать шпагатом или другой прочной нитью. Выложить на сковороду нарезанный лук, сверху – рулет, швом вниз. Налить белое сухое вино и томатный сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6872,'Закрыть блюдо фольгой для запекания, поставить в духовку, печь в течение двух часов при температуре 180 градусов. Рулет вынуть, остудить. Снять фольгу, разрезать шпагат, нарезать мясо на кусочки по полтора-два сантиметра. Выложить банкетный рулет на тарелки, полить соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6873,'Отварить в подсоленной воде куриное филе, в отвар добавить черный и душистый перец-горошек, лавровый лист. Мясо остудить в бульоне, затем мелко нарезать, поперчить, можно добавить немного приправ и майонез, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6873,'Мелко порезать отваренные вкрутую яйца, свежие огурцы и маринованные грибы. Выложить в салатницу слоями: куриная грудка с майонезом, грибы, нанести майонезную «сеточку». Затем выложить огурцы, майонез, яйца и снова майонез. Слоеный салат с куриным филе украсить на свой вкус и поставить в холодильник на два часа для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6874,'Всыпать в воду сахарный песок, размешать, добавить сухие дрожжи, поставить смесь на 10 минут в теплое место. Просеять пшеничную муку, посолить, добавить растительное масло, лучше оливковое, дрожжи. Массу вымесить, слепить «колобок», положить в емкость, накрыть пленкой и убрать в тепло на два часа. Готовое подошедшее тесто разделить пополам, вымесить, раскатать лепешки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6874,'Для начинки можно использовать сосиски, сыр, сладкий болгарский перец, соленый или маринованный огурец, майонез и томатный соус. На лепешки выложить по краю половинки кружков сосисок, край завернуть и защипать, сделать небольшие надрезы, чтобы сосиски были видны. В центр пирогов выложить остальную начинку. Печь пиццу с вкусным краешком в течение 10–15 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Растопить сливочное масло, соединить с сахаром, солью, яйцом, положить в тесто, медленно насыпать просеянную муку. Замесить тесто, положить в емкость, смазанную маслом, накрыть, поставить на шестьдесят минут в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6875,'Выложить творог домашнего приготовления в кастрюлю, влить горячее молоко и варить в течение 10 минут. Массу откинуть на сито, жидкость должна стечь. Переложить в емкость, добавить сырое яйцо, сливочное масло, влить воду, посолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6875,'Варить в течение 10 минут, помешивать, смесь должна стать тягучей. Выложить сырную массу в форму, предварительно смазанную маслом, придавить грузом. В творожный сыр можно добавить тертый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6876,'Открыть консервированную рыбу, например, сайру в масле, размять вилкой. Отварить и остудить куриные яйца, нарезать, порубить зелень укропа и лука. Все ингредиенты перемешать. Смешать отдельно стакан кефира со стаканом пшеничной муки, влить сырое яйцо, всыпать пищевую соду, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6876,'Сковороду смазать маслом, вылить тесто, сверху выложить рыбную начинку, оставить края в один сантиметр. Печь в течение 25 минут. Через 20 минут наливной пирог с зеленью и рыбной консервой достать, посыпать тертым твердым сыром, допечь еще в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6877,'Отбить мясной фарш, чтобы он стал мягким и нежным. Лук очистить от кожуры и нарезать очень мелким кубиком, соединить с фаршем. Чем больше лука, тем сочнее получается бризоль. Мясную начинку посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6877,'Вафельные кружочки смазать фаршем и закрыть вторым кружочком, сформировать сэндвич. Яйца взбить, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6877,'Вафельные котлетки обмокнуть во взбитое яйцо и обжарить на сковороде с растительным маслом. Масла в сковороде должно быть столько, чтобы бризоль погрузилась наполовину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6877,'Жарить во фритюре котлетки до золотистого цвета с двух сторон. Затем вынуть на бумажное полотенце, чтобы убрать лишний жир. Подавать вафельные бризоли с салатом из свежих овощей или гарниром из картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6878,'Сварить пшено до полуготовности. Воды использовать меньше на четверть. В вареное пшено добавить сгущенное молоко и сливочное масло, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6878,'Форму для пирога смазать сливочным маслом, посыпать манной крупой. Выложить пшено со сгущенкой и посыпать орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6878,'Выпекать пшенник в духовке 30 минут. Затем аккуратно достать из духовки и полить сметаной с сахаром. Поставить форму в духовку еще на 15 минут. Готовый пшенник имеет золотистую корочку. Остывший пирог порезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6879,'Помидоры обдать кипятком и снять толстую кожуру. Сыр натереть на крупной терке. Лук очистить и порезать мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6879,'Яйца взбить венчиком и вылить на раскаленную сковороду с толстым дном, смазанную растительным маслом. Когда одна сторона поджарится, выложить начинку из помидора, сыра и лука сверху на омлет ровной дорожкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6879,'Завернуть в омлет начинку на сковороде, сформировав рулет. Посыпать сверху сыром и накрыть крышкой на 3-5 минут. Когда сыр расплавится, омлет по-французски готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6880,'Соединить кефир комнатной температуры, соду, соль и сахар. Когда пойдет реакция соды, всыпать просеянную муку и замесить тесто, консистенции густой сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6880,'Начинка для оладьев готовится из мясного фарша и жареного лука. Чтобы избавиться от лишнего масла в жареном луке, необходимо откинуть лук на дуршлаг после жарки и подождать пока масло не стечет. Посолить и поперчить начинку по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6880,'Раскалить сковороду и налить немного растительного масла. Столовую ложку теста выложить на сковороду и сразу вложить в него ложку мясной начинки., примяв немного ложкой ко дну сковороды. Залить сверху ложкой теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6880,'Жарить на среднем огне, но следит, чтобы ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6881,'В теплом молоке развести дрожжи, добавить щепотку сахара и соли. Отставить на 15 минут, чтобы дрожжи хорошо растворились. Яйца взбить с сахаром миксером, добавить ванилин, растопленное сливочное масло и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6881,'В молоко всыпать постепенно просеянную муку, вымешивать. Затем влить масляную массу, хорошо вымесить, добавляя муку. Тесто получается мягким и блестящим. Сложить в миску и поставить в теплое место на час. Чтобы процесс ускорить, поставить миску на водяную баню.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7760,'Перебрать и тщательно промыть гречневую крупу, очищенный картофель нарезать, крупно потереть на терке морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6881,'Теперь необходимо приготовить начинку для рулета. Отварить мак в 2 стаканах воды, затем настоять под крышкой 5-7 минут. Слить воду, выложив мак в сито. Перемолоть вареный мак на мясорубке или перебить в блендере. В мак добавить сахар, цукаты, орехи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6881,'Тесто раскатать в прямоугольник, сверху нанести слой топленого сливочного масла или просто натереть слегка масло на терке. Затем выложить начинку и свернуть рулет. Выложить рулет на противень, который застелен бумагой для выпечки. Можно накрыть рулет пленкой, чтобы тесто быстрее подошло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6881,'Перед тем как ставить противень в духовку необходимо смазать верх рулета яйцом и поколоть немного вилкой. Выпекать рулет 40 минут при температуре 180 градусов. Румяный маковый рулет с изюмом необходимо остудить на решетке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6882,'Растопить плитку черного шоколада на водяной бане. Следить, чтобы шоколад не закипел. Затем добавить в него сливочное масло, порезанное на кубики. Отдельно взбить миксером белки до острых пиков, затем постепенно всыпать сахарную пудру и желтки. Взбить миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6882,'Лопаткой перемешать белки и остывшую шоколадную массу, добавляя просеянную муку. Чтобы фондан получился с более насыщенным шоколадным вкусом, необходимо всыпать какао и хорошо размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6882,'Тесто получается тянущееся. Формы необходимо наполнить на 3/4, так как во время выпечки фондан увеличится в размере. Выпекать в духовке 8 минут при температуре 180 градусов. Подавать теплым. Украсить фондан шоколадный веточкой мяты или свежими фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6883,'Взбить яйцо с сахаром и добавить в натертый сырок. Теперь в сырную массу необходимо добавить соду, гашеную лимонным соком или уксусом. Добавить в тесто муку и вымесить очень мягкое тесто. Из теста отрезать небольшие кусочки, сформировать колбаски и соединить их края, чтобы получились колечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6883,'В сковороде раскалить растительное масло. Масла должно быть много, чтобы пончики жарились во фритюре. В горячее масло опускать аккуратно колечки и жарить с двух сторон до золотистой корочки. Румяные ароматные пончики сложить на бумажное полотенце, чтобы стек лишний жир и присыпать уже охлажденные сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6884,'Орехи стоит немного обжарить на сковороде и подробить. Сгущенку необходимо смешать с какао-порошком. Соединить орехи, сгущенку и сахар (если хотите сильно сладкие конфеты). Варить смесь 15 минут на очень медленном огне, постоянно помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6884,'Форму для конфет можно брать любую–противень, формочки, тарелки. Застелить фольгой дно и стенки, смазать сливочным маслом и выложить шоколадно-ореховую массу. Охладить и убрать в холодильник на 2 часа. Холодный пласт нарезать на небольшие квадратики, шоколадно-ореховые тянучки можно сложить в пакет или коробку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6885,'Курицу необходимо помыть и порезать на небольшие порционные кусочки. Те овощи, которые добавите к курочке также необходимо помыть и порезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6885,'Трехлитровую банку вымыть и высушить. Выкладывать слоями курицу и овощи, пересыпая все пряностями и солью. Слой курицы, посолить, поперчить, лавровый лист. Теперь овощи, посолить немного и пряности. Так до конца банки. Большая курица займет всю банку. Но если банка занята не полностью, это не беда, вкус все равно не пострадает.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6885,'Когда все будет сложено в банку, накрыть новой крышкой для закатки без резинки и поставить в холодную духовку. Банку установить на противень, который максимально поднять вверх.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6885,'Курица в банке готовится 1,5 часа. За это время она пропарится в собственном соку и пропитается ароматом трав и специй. Хозяйка сама может экспериментировать по добавлению овощей, этим можно создать свой неповторимый рецепт и с гордостью демонстрировать его гостям. Готовую курочку выложить из банки в глубокую тарелку, украсить свежей зеленью, подавать с запеченным картофелем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'В тесто для нашего бисквита необходимо большое количество яиц, которые необходимо хорошо взбить миксером. Когда масса увеличится в два раза, постепенно всыпать сахар. Взбивать миксером массу, пока не растворится сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7460,'Затем нужно добавить пряности и коричневый сахар, сделать маленький огонь, размешать все и довести до кипения, но надо следить, чтобы вино не закипело.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'Затем, снизив скорость миксера до минимума, постепенно высыпать муку. Маленькими порциями подсыпать муку, пока тесто не примет нужную консистенцию. Дно алюминиевой кастрюли застелить пергаментной бумагой, а крышку замотать в полотенце. Жира для смазывания кастрюли не использовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'Вылить тесто в кастрюлю и поставить на плиту. На огонь сразу ставить нельзя! Необходимо использовать чугунную сковороду или железный лист под кастрюлю, чтобы не было сразу большого перепада температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'Кастрюлю плотно закрыть крышкой в полотенце и поставить на печь. За время приготовления бисквита нельзя открывать крышку кастрюли. Выпекать корж 45-60 минут на очень медленном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'Когда пойдет аромат выпечки, можно проверить бисквит на готовность спичкой. Если тесто не налипает, можно кастрюлю снимать с огня. Аккуратно перевернуть кастрюлю на стол, чтобы бисквит вышел. Можно ножом провести по стенкам кастрюльки, чтобы помочь коржу отсоединиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6886,'Высокий бисквит для тортов на плите разрезать на 3 части по горизонтали и смазать любимым кремом. Чтобы коржи были немного мокрыми, использовать пропитку из сахарного сиропа и коньяка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6887,'На сковороду положить столовую ложку сливочного масла и очищенные кусочки яблок, добавить сахар. Томить яблоки в сливочном масле 5 минут под накрытой крышкой, пока они не станут мягкими. Готовую начинку выложить на тарелку и остудить. Приготовить творожное тесто. Для этого необходимо соединить творог с растительным маслом и молоком, вымешивать, добавляя сахар и соль по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6887,'В муку всыпать разрыхлитель и добавить в творожную массу. Замесить мягкое тесто. Теперь необходимо тесто разделить на небольшие шарики в диаметре 5 см. Из шарика сформировать лепешку, ее наполнить начинкой. Защипнуть края пирожков, чтобы начинка во время приготовления не вытекла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6887,'Противень застелить бумагой для выпечки. Выложить пирожки на противень, верх теста смазать яичным желтком. Противень поставить в духовку для выпекания на 20 минут при температуре 180 градусов. Румяные готовые творожные пирожки остудить и присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6888,'Отварить куриную грудку, измельчить и выложить на блюдо. Сделать сеточку из майонеза. Затем мелко нарезанные соленые огурцы или потертые на среднюю терку. Следующий слой из лука. Среднюю луковицу очистить, мелко нарезать и ошпарить кипятком, чтобы убрать горечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6888,'Посыпать порезанный лук на огурцы. Сеточка из майонеза. Вареные яйца очистить и натереть на средней терке или мелко покрошить. Сделать яичный слой, затем тонкая сеточка из майонеза. Затем вареную морковь очистить и натереть на средней терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6888,'Сделать слой, слегка полить майонезом. За морковью сделать слой из зеленого горошка и мелко нарезанный чернослив. На салате нарисовать тонкую сеточку из майонеза. Контраст ярких цветов салата «Прага» будет виден через прозрачные стенки блюда и, конечно, на тарелке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6889,'Отварить цветную капусту в подсоленной воде в течение 3 минут. Лучше этот процесс проводить с уже разделенной на соцветия капустой, так она проварится равномерно и быстро. Затем слить воду и выложить капусту на противень, смазанный растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6889,'Куриное филе, порезанное на тонкие полоски, необходимо обжарить на растительном масле до румяной корочки. Посолить и поперчить по вкусу. Выложить филе на цветную капусту и залить яично-сырным соусом. Для приготовления соуса следует взбить яйца со сливками или молоком в однородную массу и добавить тертый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6889,'Добавить соль и перец по вкусу. Также по вкусу добавить тертый чеснок. Духовку разогреть до 180 градусов и поставить противень с запеканкой на 35-40 минут. Когда появится румяная корочка, запеканка из цветной капусты готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6890,'В муку добавить холодное сливочное масло и растереть его в крошку. Затем в эту крошку влить сметану и немного посолить. Теперь следует вымесить мягкое тесто, сформировать шар и, завернув в пленку, положить на холод на 2-3 часа. Охлажденное тесто разделить на 6-7 частей. Каждую часть очень тонко раскатать и выпекать коржи в духовке. Коржи пекутся очень быстро, главное следить, чтобы они не сгорели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Насыпать муку, соль, специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6890,'Для приготовления классического заварного крема необходимо закипятить часть молока, затем в кипящее молоко влить массу из взбитых яиц с сахаром, молока и муки. Тщательно мешать молоко, чтобы не свернулось комочками. Крем постоянно мешать, не допускать кипения. Затем снять с огня и немного остудить. Охлажденный крем взбить со сливочным маслом и ванилином. Когда все коржи испекутся, необходимо все смазать кремом и сложить торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6890,'Неровные края обрезать через некоторое время, когда коржи немного пропитаются, чтобы торт не поломался. Промазанный торт поставить на ночь под пресс. Можно использовать противень, на который поставить банку с водой. Утром подравнять края торта «Наполеон», обрезав лишнее и промазать верхний слой кремом, посыпать дроблеными орехами и обрезками коржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6891,'Вишневую начинку можно готовить по своему вкусу, контролируя количество сахара. Ягоды очистить от косточек, засыпать сахаром и варить на очень медленном огне, постоянно помешивая. Кофе растворить в ложке кипятка. Холодное сливочное масло или сливочный маргарин растереть с мукой, затем соединить с кофе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6891,'Яйца взбить венчиком и вливать по не многу в масляную смесь. В просеянную муку всыпать разрыхлитель и добавить к остальным ингредиентам. Вымесить мягкое тесто. Вишню откинуть на сито, чтобы слить лишнюю жидкость. Ягоды высыпать в тесто и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6891,'Формы для кексов тщательно вымыть, высушить и смазать сливочным маслом. Формы наполнить на половину тестом и поставить в духовку на 30 минут при температуре 180 градусов. Готовность проверить спичкой. Готовые кофейные кексы с вишневой начинкой остудить, вынуть из формы и хорошо пропитать верх вишневым сиропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6892,'Скумбрию холодного копчения разобрать на мелкие кусочки, удалив кости и кожу. Теперь необходимо выкладывать слоями ингредиенты салата. Первый слой скумбрия, затем тонкая сетка майонеза. Вареный картофель очистить от кожуры и натереть на средней терке. Полить слегка майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6892,'Вареную морковь очистить и натереть на средней терке, майонез. Вареные яйца очистить и натереть на средней терке, сетка майонеза. Сверху посыпать зеленым горошком. Салат «Объедение» должен настояться перед подачей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6893,'Для приготовления хрустящих креветок в панировке необходимо выбирать крупных моллюсков, от этого зависит вкус блюда и его внешний вид. Креветки  очистить, удалив голову и кишечную вену, хвостик оставить. Хлеб высушить в духовке до хрустящей корочки, затем измельчить в мелкую крошку. К хлебным крошкам добавить пармезан и мелко нарезанную зелень кинзы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6893,'На сковороде распустить сливочное масло, добавить растительное и сильно разогреть. В масляную смесь окунать креветки, которые предварительно обмакнули в муку, затем в яйцо и в хлебные крошки с сыром пармезаном. Обжарить креветки в хлебных крошках с сыром до золотистой корочки. Затем вынуть шумовкой и выложить на бумажное полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6894,'Взять любой сыр твердых сортов и нарезать его полосками или квадратиками толщиной не меньше 1 см. Теперь каждый кусочек следует обмакнуть в муку (основа), затем в яйцо (пышность) и сухари (хрустящая корочка), затем повторить еще 2 раза. Каждый кусочек сыра должен пройти окунание в «панцирь» 3 раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6894,'На сковороде раскалить растительное масло. В кипящее масло аккуратно вкладывать сыр и жарить во фритюре до золотистой корочки. Жареный сыр в панировке выкладывать на бумажное полотенце, чтобы убрать лишний жир. Блюдо невероятно вкусное горячим, так как под хрустящей корочкой вытекает нежный сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6895,'Из булок выбрать мякоть, оставив тонкую корочку для наполнения вкусной начинкой. Теперь необходимо приготовить жульен. Нарезать лук мелким кубиком и обжарить на растительном масле до мягкости. Затем добавить в него грибы и протушить. В готовые грибы влить сливки, посолить по вкусу. Тушить 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6895,'На другой сковороде обжарить фарш на растительном масле. Добавить соль и приправы по вкусу. Соединить обжаренный фарш и грибы в сливочном соусе. Этой начинкой необходимо начинить формы из булочек. Противень смазать сливочным маслом и поставить булочки для выпекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7460,'Разлить Глинтвейн вечерний по бокалам, украсить лимоном и подать гостям.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6895,'Сыр потереть на мелкой терке и посыпать каждый жульен. Вместо тертого сыра можно использовать сыр для сендвичей, так блюдо выглядит еще аппетитнее. Духовку разогреть до 200 градусов и поставить противень с жульеном. Выпекать 5 минут, пока сыр полностью не расплавится. Жульен с мясным фаршем в булочках подавать горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Приготовить бисквит: отделить белки от желтков. Для желтков взять посуду побольше, потому что в ней необходимо замесить все ингредиенты. Белки убрать в холодильник. Добавить к желткам четыре больших ложки теплой воды. Взбивать с помощью миксера до пышной пены – приблизительно три минуты. Добавить половину сахара, взбивать до его растворения. В итоге получится плотная практически белая пенка. Отставить емкость с желтками в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Достать из холодильника белки. Насыпать щепотку соли и несколько капель сока лимона. Взбивать до устойчивой пены белого цвета, постепенно увеличивая скорость – примерно четыре минуты. Постепенно насыпать сахар, продолжать взбивать две минуты, пока не растворится сахар. Белки станут воздушными и плотными, как крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'В посуду с желтками просеять муку, аккуратно смешать на маленькой скорости, переложить белки, размешать. Процесс необходимо делать быстро, чтобы яйца не потеряли воздушность. Вылить тесто в круглую формочку, готовить в духовке, разогретой до 180 градусов. Готовить бисквит минут тридцать. За это время открывать духовку. Убедиться в готовности можно, нажав на верхнюю корочку, если останется углубление, то необходимо подержать бисквит в духовке, если корочка восстановится, то он готов. Духовку выключить, оставив в ней бисквит минут на пять. Достать, остудить, отставить на пару часов, желательно на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Можно приготовленный бисквит пропитать. Соединить три больших ложки сахара и 1/2 стакана воды, готовить сироп, пока сахар не растворится. Охладить сироп, соединить с ванильным экстрактом (можно соединить с ванильной эссенцией, ванилином, ромом или коньяком). Разрезать бисквит на несколько коржей и пропитать хорошо сиропом, в том числе краешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Приготовить начинку: соединить творог и две большие ложки сахара, чтобы почувствовать вкус ягод, начинку делать несильно сладкую. Отставить на 60 секунд, хорошо растереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Взбить в высокой посуде сливки. Чтобы лучше взбивалось, посуду со сливками поставить в емкость большего размера с холодной водой, можно даже положить лед. Перед взбиванием можно поставить сливки в морозилку минут за пятнадцать. При взбивании постепенно увеличивать скорость миксера, чтобы сливки не брызгали, они должны стать густыми.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Подготовить желатин, как сказано в инструкции, часто пакетик рассчитывается на 500 миллилитров жидкости. Для начинки взять ½ пакетика, остальную часть оставить для украшения. ½ желатина залить кипяченной холодной водой, отставить минут на десять. Растворить на маленьком огне, не доводя до кипения. Охладить, но не дать желатину остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Соединить взбитые сливки, остывший желатин и творог при помощи миксера. Аккуратно подмешать ягоды, чтобы не помялись. Предварительно помыть ягоды и обсушить салфеткой. Черника придает сиреневый цвет, поэтому можно сделать красивые рисунки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Пока схватывается желатин, собрать тортик. Положить в формочку корж, намазать начинкой и осторожно разровнять. Положить сверху второй корж. Отправить в холодильник на несколько часов для застывания. Достать из формочки творожный торт-суфле. Осторожно обрезать краешки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6896,'Взбить остальные сливки, закрепить их желатином, как и для начинки. Остальной желатин замочить в трех больших ложках воды, подогреть на тихом огне. Украсить торт.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6897,'Хорошо просеять несколько раз в емкость сухие ингредиенты и разрыхлитель. Мелко натереть апельсиновую цедру, ошпарив предварительно кипятком, и кусок имбиря. Залить шоколад сливками, растопить в микроволновой печи или на водяной бане. Чуть-чуть охладить. Взбить яйца и сахар в густую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'В это время приготовить начинку. Взять несколько небольших куриных окорочков, вареное яйцо, свежий укроп, перец, соль, сырое яйцо для смазывания пирожков, по желанию кунжут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Добавить в фарш чеснок, яйца, батон, заранее замоченный в молоке, мускатный орех, соль. Перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6897,'В посуду с сухой смесью положить 1/3 яичного крема, осторожно перемешивая и поворачивая посуду по кругу, налить растопленный шоколад. Перемешать. Остальные яйца вмешать в несколько приемов. Налить смесь в смазанную емкость мультиварки, готовить в режиме «Выпечка» шестьдесят минут. Дать настояться минут пять в режиме «Сохранения температуры». Открыть мультиварку, чуть-чуть охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6897,'Выжить сок из половины апельсина, соединить с ликером. Силиконовой кисточкой смочить теплый пирог смесью, дать настояться в чаше минут семь. Достать при помощи вставки пароварки, остудить на решетке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6897,'В микроволновой печи растопить 2/3 поломанного шоколада и остальную ликерную смесь. Положить в подогретую смесь остальной шоколад, поломанный на маленькие кусочки, вымешать. Вылить на пирог и поставить на тридцать минут в холод, можно на ночь. Подавать пирог «Аромат страсти» ванильным мороженным и кофе с коньяком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6898,'Заранее приготовить вишню, залив ее на несколько часов водкой, можно оставить с вечера на ночь',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6898,'Приготовить тесто: развести кипятком какао. Положить маргарин или масло, яйца, сахар, муку и остальные ингредиенты. Размешать. Тесто получается, как жидкая сметана. Поделить на две части, испечь коржики. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6898,'Приготовить крем: нагреть молоко, растворить в нем хорошо сахар. Охладить. Взбить масло, тоненькой струей налить в него молоко, взбивая. Поделить крем на три части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6898,'Снять середину с одного коржа, оставить только тоненькие стенки. Второй коржик разрезать на две части вдоль.  Один отложить, а второй измельчить вместе с мякотью первого коржа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6898,'В 2/3 крема положить кусочки коржа, вишню, размешать, наполнить пустой коржик. Накрыть оставшейся половинкой коржа, намазать торт «Пьяная вишня» оставшимся кремом. На тортик потереть шоколад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6899,'Отварить гнезда тальятелле, как написано в инструкции. Варить пасту необходимо в большой кастрюльке в достаточном количестве воды. Разогреть оливковое масло на сковороде, обжарить чуть-чуть измельченный лук, порезанное куриное филе, чеснок, мясо должно стать белого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6899,'Положить к мясу в сковороду порезанные шампиньоны, обжаривать несколько минут, чтобы грибы стали мягче. Проверить готовность тальятелле: если макароны готовы, снять с огня, воду не сливать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6899,'Положить к грибам с мясом сметану, осторожно размешать, кипятить на маленьком огне несколько минут, добавить тертый пармезан и томатную пасту. Размешать содержимое сковороды при помощи лопатки, посыпать перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6899,'Слить воду с тальятелле в другую посуду. Осторожно положить пасту в сковороду с соусом, размешать. Если необходимо добавить чуть-чуть воды, чтобы паста была сочной. Перед подачей посыпать пасту тальятелле с соусом из грибов с курицей измельченной петрушкой и остальным тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6900,'С баранины срезать жир. Положить обрезки в казан с толстыми стенами. Порезать мясо на большие куски, положить на жир, посыпать перцем, солью. Почистить баклажан, порезать на кубики, посыпать солью, отставить минут на десять, отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6900,'Нашинковать крупно болгарский перец, луковицу, морковь. Порезать на полукруглые кусочки помидоры. Уложить на мясо слоями овощи: лук, сверху морковь, баклажаны, сладкий перец, помидоры. Чуть-чуть посыпать перцем, солью, измельченной зеленью, чесноком. Накрыть казанок крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6900,'Тушить овощное рагу с жирной бараниной на маленьком огне часа два, не размешивая. Добавлять воду нет необходимости, овощи пустят сок сами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6901,'Соединить шоколад и масло, положить в микроволновую печь, растопить, размешать до однородности. Насыпать сахар, размешать до растворения. Разбить яйца в отдельную емкость, взбить до однородности с помощью венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6901,'Когда остынет шоколадная масса, добавить смесь из яиц, взбить до однородности. Положить натертую цедру лимона, насыпать муку, размешать. Налить в формочку, отправить в духовку, готовить минут тридцать, соблюдать температуру 180 градусов. Остудить тортик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6901,'Положить трафарет на шоколадный французский торт, посыпать сахарной пудрой, осторожно снять трафарет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'В небольшой посуде взбить яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Отварить окорочка, снять кожицу, мясо отделить от косточек, мясо измельчить в блендере, кухонном комбайне или просто мелко порезать. Посыпать перцем, солью, добавить потертое яйцо, несколько ложек бульона, в котором готовилась курица, чтобы начинка была сочной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Подошедшее тесто положить на стол, чуть-чуть обмять, разделить на части, раскатать круг, в центр положить чуть-чуть начинки. Краешки защипнуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Уложить пирожки на противень, застеленный специальной бумагой, вниз швами. Отправить пирожки в теплую духовку минут на двадцать для расстойки или накрыть пленкой и поставить в тепло. После этого намазать пирожки с курицей размешанным яйцом, посыпать по желанию кунжутом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6902,'Разогреть духовку на 190 градусов, готовить пирожки до золотистого оттенка. Пирожки с курицей и яйцом в готовом виде положить на решетку, накрыть тканью, дать немного остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6903,'Подготовить ингредиенты. Растопить сливочное масло, остудить в морозильной камере или холодильнике. Понадобится растопленное, охлажденное масло. Во время охлаждения масла соединить муку, соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6903,'В отдельной посуде взбить яйца и молоко. Вылить ½ молочной смеси в муку. Хорошенько размешать до однородной консистенции. Положить охлажденное масло. Размешать. Перелить остальную молочную смесь. Размешать венчиком, чтобы получилась густая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6903,'Нагреть на среднем огне сковороду, побрызгать маслом, желательно использовать масляный спрей. Если такого спрея под рукой нет, то после того как масло набрызгано на сковороду, разогреть его и убрать лишнее с помощью бумажной салфетки. Налить на сковороду ¼ емкости молочной смеси. Равномерно распределить тесто. Если сковорода обыкновенная, то прокрутить ее, чтобы тесто распределилось по всей поверхности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6903,'Готовить секунд 30 блинчик с одной стороны. Когда краешки блинчика станут коричневеть быстро перевернуть его, используя лопатку. Если тесто приготовлено правильно, то все блинчики будут ровными, тонкими и золотистыми. Не будет ни одного блина комом. Со второй стороны выпекать блинчик секунд двадцать, чтобы он не был пересушенный. Снять готовый блин со сковороды, положить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6903,'Приготовить начинку: понадобится сыр Филадельфия и абрикосовый джем. Намазать на половинку блинчика с изнаночной стороны тоненький слой сыра Филадельфия. Рядом положить маленькую ложечку джема. Свернуть блинчик в форму треугольника. Украсить сахарной пудрой. Можно просто положить французский блинчик треугольником и полить медом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6904,'Почистить лук и картофель. Измельчить овощи в кухонном комбайне. Переложить в дуршлаг, чтобы стекла жидкость. Вбить в картофель яйцо, насыпать муку, перец, соль. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6904,'Сформировать шарики. Положить в разогретое масло и чуть-чуть придавить лопаткой. Обжарить оладьи из картофеля до золотистой корочки со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6905,'Вскипятить воду, посыпать солью, положить лук, готовить, пока идет подготовка овощей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6905,'Положить морковь, картофель, перец и лавровый листик. Помыть гречку, высыпать в суп. В конце в легкий гречневый суп положить масло и измельченную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6906,'Порезать куриную грудку на порционные куски. Отбить, посыпать перцем, солью. Отставить чуть-чуть настояться. В отдельной емкости смешать майонез с яйцами, мукой и зеленью. Посыпать перцем, солью. Потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6906,'На каждый кусок отбитой курицы положить ложкой яичную массу. Положить на разогретую сковороду вниз яичной смесью. Посыпать сыром. Осторожно залить отбивную соусом. Обжарить отбивные из куриного филе со всех сторон до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6907,'Помыть и порезать фрукты. Положить все порезанные фрукты в емкость, залить вином. Засыпать сахаром, размешать, отправить в холодильник на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6907,'Перед подачей во все бокалы положить чуть-чуть льда. В качестве украшения использовать дольки апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6908,'Порезать куриное филе на средние кусочки. Положить на раскаленную сковороду и чуть-чуть обжарить на масле. Положить к курице потертую морковь, измельченный чеснок и лук. Размешать и обжаривать минут семь. Убавить пламя.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Прогреть сливочное масло вместе с оливковым в кастрюле с толстым дном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6908,'Положить сметанку, муку, томатную пасту, размешать, тушить минут пять. Налить воду в сковороду, аккуратно размешать, посыпать солью, довести до кипения. Тушить на маленьком огне минут двадцать. В конце в гуляш из куриного филе положить специи и лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6909,'Перемешать все в блендере, дать постоять минимум минут тридцать, а желательно часа два.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6910,'Сделать фарш, положить лук, зелень, насыпать перец, соль. Положить лаваш. Намазать фаршем. Свернуть рулетик, сделать то же со вторым листом. Сделать заливку из кетчупа, майонеза, яиц. Намазать кастрюльку для микроволновой печи растительным маслом, свернуть рулетики улиткой. Вылить заливку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6910,'Включить микроволновую печь готовить пятьдесят минут в режиме «Выпечка». Выключить и не открывать крышку еще минут пятнадцать. Потом минут десять подержать пирог «Ленивец» с открытой крышкой. Взять емкость пароварки, поставить в кастрюльку, перевернуть кастрюльку. Можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6911,'Порезать кабачки на дольки по 0,5 сантиметра. Взбить яйцо и молоко. Соединить сыр, муку и панировочные сухари. Посыпать перцем, солью, добавить молотый сушеный чеснок. Все ломтики кабачка обмакивать в яично-молочную смесь, запанировать сырной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6911,'Положить кабачки на противень, запекать минут двадцать, соблюдая температуру 220 градусов. Можно украсить чипсы из кабачка базиликом или ломтиками помидора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6912,'Очень мелко нашинковать капусту, присыпать солью, обмять руками, чтобы появился сок и стала мягче.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6912,'Крупно потереть лук, положить в капусту, налить кефир, вбить яйцо, насыпать разрыхлитель, муку, размешать, если необходимо досыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6912,'Разогреть на сковороде чуть-чуть растительного масла, обжаривать оладьи из капусты на среднем огне. Сложить на бумажное полотенце.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6913,'Приготовить тесто: насыпать в посуду муку, добавить соль, растительное масло. Налить кипяток. Размешать до однородности. Остудить тесто. Срезать мясо с окорочка, порезать на кусочки. Крупно потереть сыр, измельчить зеленый лук, посыпать солью. Размешать. Слепить пирожки: присыпать стол мукой, ложкой выложить тесто. Вымесить чуть-чуть, досыпая при необходимости муку, чтобы тесто не липло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6913,'Поделить тесто на шесть частей. Раскатать каждую в тоненький круг диаметром приблизительно двенадцать сантиметров. На 1/2 круга положить 1/6 мяса, посыпать солью. Сверху положить 1/6 часть сырной массы. Сформировать пирожок, придавить по краешку вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6913,'Разогреть на сковороде растительное масло. Положить пирожки, жарить с одной стороны до золотистого цвета, затем с другой. Сделать огонь минимальным, накрыть крышкой, готовить минут десять. Подавать чебуреки с курицей и сыром в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6914,'Порезать мясо на небольшие кусочки, посыпать перцем, солью, итальянскими травами, отставить минут на тридцать мариноваться. Почистить картофель и порезать на небольшие кубики, мелко порезать лук, крупно потереть морковь, порезать перец на небольшие брусочки или кубики, порезать помидоры полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6914,'Положить подготовленные ингредиенты слоями. Сначала картофель, посыпать чуть-чуть солью, намазать майонезом или сметаной. Затем положить слой моркови, сверху болгарский перец, на него помидоры, посыпать солью. Далее положить измельченный лук и в конце маринованное мясо. Обильно намазать сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6914,'Налить воду, чтобы накрывала последний слой. Готовить под крышкой минут тридцать, соблюдая температуру 220 градусов. Снять крышку, посыпать сыром, поставить жаркое из овощей со свининой в горшочках еще минут на тридцать в духовку уже без крышки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6915,'Смешать просеянную муку и соль, положить порезанное на кубики масло. Смешать, чтобы получилась крупная крошка. Вбить яйцо и воду, чтобы тесто собралось в комок, завернуть в пленку, отправить минут на шестьдесят в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6915,'Разогреть до 180 градусов духовку, раскатать тесто, положить в формочку размером 24 сантиметров. Сформировать маленькие бортики, сделать проколы вилкой, отправить минут на десять в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6915,'Намазать тесто медом, положить по кругу абрикосы, посыпать сахаром, вновь отправить абрикосовый тарт в духовку, готовить, пока не станут мягкими абрикосы, а тесто золотистым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6916,'Ингредиенты крупно потереть и выложить слоями. Слой вареного тертого картофеля, второй слой отваренных тертых яиц. Третий слой жареной тертой печени. Четвертый слой жареного лука и моркови. Все слои салатика с куриной печенью промазывать майонезом и чуть-чуть солить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6917,'Залить манную крупу кефиром, отставить набухать приблизительно шестьдесят минут. Насыпать муку, сахар, положить мягкий маргарин, гашеную соду, перемешать. Положить тесто в формы на 2/3, готовить в разогретой духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6917,'Залить остывшие кексы глазурью. Для этого необходимо растопить темный шоколад на микроволновке. Заливать при помощи кулинарного шприца или обыкновенного пакета, срезав уголок. Сверху манные кексы с шоколадом посыпать кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6918,'Смешать ингредиенты, предназначенные для соуса, перелить в глубокую формочку для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6918,'Соединить ингредиенты, предназначенные для фрикаделек, размешать. Сформировать средние по размеру фрикадельки, положить в формочку с соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6918,'Поставить формочку минут на пятнадцать в духовку, посыпать говяжьи фрикадельки тертым чеддером и готовить минут десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6919,'Смазать грудки со всех сторон оливковым маслом, посыпать перцем, солью. Обжарить до золотистой корочки на среднем огне. Положить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6919,'Сделать огонь меньше, обжарить лук-шалот приблизительно шестьдесят секунд. Положить сливочный сыр, добавить лимонный сок и бульон. Размешать, посыпать куриные грудки зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6920,'Мелко порезать морковь, лук, шампиньоны, филе курицы, обжарить на растительном масле. Посыпать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6920,'Приготовить тесто: взбить с помощью миксера сметану, молоко, яйца, муку и соль. Должно получиться тесто, как на оладушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6920,'Положить одну часть теста в разогретую емкость, положить равномерно начинку, налить остальное тесто сверху.  Поставить заливной пирог на режим «Выпечка» минут на 45.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6921,'Порезать лаваш на поперечные полосочки. Порезать сыр на ломтики по ширине, как ленточки лаваша, чтобы приблизительно два раза можно было его обернуть. Взбить яйца при помощи вилки, чуть-чуть посыпать солью и другими специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6921,'Все ломтики сыра обернуть полосками лаваша, окунуть в яйцо, обжаривать минут пять на сковороде с двух сторон. Готовятся довольно быстро. Положить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6922,'Крупно порезать все овощи для супа и грибы, отваривать минут двадцать в небольшом количестве воды. Процедить через ситечко. Грибы и овощи пюрировать в блендере, добавить сливки, если необходимо процедить бульон. Посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6922,'Остальной бульон сохранить, так как супы-крема густеют и при разогревании их хорошо разводить бульоном. Довести до кипения, выключить огонь, дать супчику настояться минут двадцать. Подавать с чесночными гренками, зеленью. Употреблять крем-суп из белых грибов в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6922,'Приготовить гренки: духовку разогреть до 180 градусов. Положить на противень ломтики хлеба. Подсушить до золотистого оттенка в духовке. Натереть теплые гренки чесноком со всех сторон. Порезать на небольшие кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6923,'Взбить сахар и яйца, насыпать соль, ваниль, добавить водку, гашеную соду, сметанку. Перемешать, насыпать муку. Вымесить тесто. Не сильно тонко раскатать (чуть-чуть меньше сантиметра), вырезать формочкой, печь на горячей сковороде. Перед подачей пышки «Любаша» посыпать пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6924,'Растворить соль в стакане воды. Помыть филе курицы, опустить в соленую воду часа на три, а желательно на ночь оставить в прохладном месте. Достать мясо, ополоснуть. Связать ниткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6924,'Приготовить смесь для обвязывания: смешать растительное масло, паприку, измельченный чеснок, мускатный орех, соль, мед. Намазать смесью равномерно мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6924,'Выложить филе на специальную бумагу или фольгу. Отправить мясо в разогретую духовку, готовить минут двадцать, соблюдая температуру 250 градусов. Оставить пастрому из куриного филе в духовке до полного остывания, чтобы лучше сохранилась форма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6932,'Поставить формочку в разогретую духовку, готовить минут тридцать, соблюдая температуру 180 градусов. Проверять готовность апельсиновой шарлотки спичкой. Посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6925,'Потереть вареный картофель, вбить яйца, посыпать перцем, солью. Размешать. Переложить картофельное тесто в формочку для пиццы, распределить равномерно. Намазать кетчупом. Положить колбаску, покрыть сыром. Поставить картофельную пиццу в духовку, готовить при 180 градусов, пока сырок не расплавится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6926,'Порезать лук на кубики, мелко потереть морковь. На сковороду налить масло и поставить на огонь. Положить морковь и лук, чуть-чуть обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6926,'Положить рис, размешать, пропитать двадцать секунд. Налить два стакана воды, размешать, накрыть крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6926,'Минут через десять посыпать солью, размешать, накрыть рис на сковороде крышкой. Оставить минут на пятнадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Соединить дрожжи, воду и сахар. Когда смесь запенится, налить оливковое масло, осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Медленно насыпать муку с солью. Когда тесто станет густым, что невозможно будет мешать ложкой, месить его руками, пока оно не станет послушным и мягким. Сформировать шарик. Положить в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Когда тесто увеличится раза в два, раскатать в толстую колбаску, разрезать на восемь частей. Из каждой сформировать шар, из него раскатать лепешку диаметром около пятнадцати сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Духовку разогреть до 260 градусов. Положить лепешку на решетку. Отправить питу запекаться. Минут через десять, когда пита надуется, вынуть из духовки, положить следующую лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Приготовить начинку: порезать помидоры на кружки, лук на тоненькие кольца. Мелко потереть морковь. Соединить овощи, положить кукурузу, посыпать солью, специями, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6927,'Надрезать продольно каждую питу, положить начинку, несколько листиков салата, порезанные овощи, тоненький кусок ветчины. Питу с ветчиной, овощами и кукурузой можно подавать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6928,'Сделать фарш, обжарить его с изюмом и луком. Посыпать специями, побрызгать оливковым маслом. Остудить. Раскатать тесто, положить начинку: фарш – несколько оливок и тоненький кусочек яйца. Взбить яйцо и молоко. Плотно скрепить края, чтобы начинка не вытекла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6928,'Намазать пирожки смесью молока с яйцом. Готовить минут тридцать, соблюдая температуру 175 градусов. Подавая пирожки с мясом и изюмом, посыпать зеленым луком и свежей петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6929,'Порезать филе курицы на маленькие кубики или измельчить блендером. Порезать на кубики любой твердый сыр, соединить с курицей. Измельчить чеснок, положить к мясу с сыром. Добавить яйца, посыпать перцем, солью, посыпать карри. Положить сметанку, крахмал, муку. Перемешать, отправить минут на сорок в холодильник, чтобы котлетки были нежными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6929,'Достать смесь, положить в нее кусочки консервированных ананасов. Размешать. Жарить котлеты со всех сторон на растительном масле, накрыв крышкой. Выкладывать, как оладушки с помощью ложки. Котлетки из курицы с ананасами будут вкусней, если жарить их на смеси сливочного масла и растительного.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6930,'Высыпать в емкость «Малютку». Можно взять сухое жирное молоко, но вкус тогда получится не такой нежный. Насыпать ванилин, сахарную пудру, растаявшее сливочное масло. Перемешать руками до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6930,'Разрезать по бокам полиэтиленовый пакет. В центр положить массу шириной сантиметров семь, толщиной пол сантиметра. На середине пласта осторожно в виде бантика выложить густую вареную сгущенку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6930,'Соединить края целлофана, чтобы масса свернулась и сформировалась колбаска с начинкой. Развернуть пакет, порезать колбаску на куски. Обвалять их в кунжуте. Положить десерт «Чудо» минут на тридцать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6931,'Вымыть крылышки, обсушить бумажным полотенцем, намазать прессованным чесноком, посыпать перцем, солью, добавить паприку, сок лимона, залить соевым соусом. Размешать, оставить часа на три мариноваться. Жарить пикантные крылышки на сильно прогретых углях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6932,'Взбить миксером яйца и сахар, насыпать муку, перемешать. Смазать сливочным маслом формочку для запекания, налить 1/3 теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6932,'Почистить апельсины от косточек и кожуры, поделить на дольки, разрезать пополам. Положить половину почищенных апельсинов на тесто, залить 1/3 теста, положить остальные апельсины, вылить оставшееся тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6933,'Измельчить крекер при помощи комбайна или мясорубки. Положить мягкое сливочное масло, прессованный чеснок, белок. Перемешать. Намазать сливочным маслом разъемную формочку диаметром двадцать сантиметров, посыпать мукой. Положить в формочку основу чизкейка, выровнять поверхность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6933,'Сделать сырный слой. Соединить в емкости яйца, рикотту, творожный сыр. Чуть-чуть взбить миксером. Насыпать перец, соль, сушеный тимьян. Положить тертый твердый сыр. Перемешать продукты ложкой. Налить сырную массу на основу. Выпекать чизкейк минут шестьдесят, соблюдая температуру 180 градусов. Остудить и отправить на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6933,'Помыть перец, положить в формочку, застеленную пергаментом. Запекать до мягкости, соблюдая температуру 180 градусов. Время от времени переворачивать. Дать перчику остыть в духовке, убрать семена, плодоножки. Перед подачей украсить чизкейк «розочками» из перца. Порезать перец на полосочки шириной 1 сантиметр, свернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6933,'Положить «розочки» из перчика на остывший чизкейк, посыпать перец солью. Смазать перец при помощи кисточки смесью бальзамического уксуса и оливкового масла. Украсить чизкейк с болгарским перцем листиками базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6934,'Соединить в небольшой кастрюльке соевый соус, сахар, перец, уксус, крахмал, разведенный в прохладной воде, тертый чеснок, имбирь. Довести до кипения, помешивая, соус должен стать густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6934,'Намазать противень маслом. Положить курицу. Полить хорошенько соусом, поставить минут на тридцать в духовку, готовить, соблюдая температуру 220 градусов. Минут через семь перемешать, чтобы курица терияки пропиталась соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6935,'Прокрутить печень через мясорубку. Насыпать муку, соду, соль, налить молоко, вбить яйца. Пожарить блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6935,'Обжарить измельченный лук и потертую морковь. Намазать блины майонезом, проложить обжаренной морковью и луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6936,'Приготовить ореховую нугу. Измельчить в блендере орехи и добавить к нуге. Подготовить пергамент, намазать сливочным маслом, постелить на разъемную формочку или формовочное кольцо по размеру тортика. Поставить нугу в морозилку часов на шесть, а желательно на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6936,'Сделать бисквит: отделить белки от желтков. Взбить желтки, сахар, масло и воду. Насыпать разрыхлитель, муку, какао, соль. Взбить белки до пиков. Постепенно подмешать белки к мучной массе до однородности. Намазать разъемную формочку сливочным маслом, положить тесто, отправить минут на пятьдесят в духовку, соблюдая температуру 180 градусов. Охладить бисквит, достать из формочки, разрезать на четыре одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6936,'Приготовить крем: взбить сливочное масло и сахарную пудру добела. Постепенно добавить вареную сгущенку, взбивать. Положить в крем жареные орехи, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6936,'Положить первый корж, намазать половиной орехового крема. Положить на крем второй корж, на него положить корж ореховой нуги. На него положить еще бисквит. Сверху намазать остальным кремом, накрыть  коржом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6936,'Приготовить глазурь: растопить сливочное масло. Насыпать сахар и какао. Когда растворится сахар, положить сметану, размешать. Добавить орехи, покрыть глазурью торт, поставить торт «Сникерс» с ореховой нугой в холодильник минут на сорок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6937,'Насыпать в кефир соду, перемешать. Когда перестанет пениться, добавить остальные продукты, замесить тесто. Завернуть его в полиэтилен, отложить часа на два. Порезать колбаски на кусочки, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6937,'Поделить тесто на куски, раскатать не сильно тонкие лепешки. Положить на них начинку: детям колбаску и сыр, взрослым острый хрен или горчицу и колбаску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6937,'Сформировать пирожки. Жарить на растительном масле до румяного оттенка. Можно сделать без корочки, для этого положить ленивые пирожки в кастрюльку, накрыть крышкой–они чуть-чуть отмякнут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6938,'Просеять муку с сахарной пудрой в емкость. Насыпать какао. Чуть-чуть взбить яйца и растопленное сливочное масло, насыпать соль, долить молоко. Соединить сухую смесь и жидкую. Пожарить тоненькие шоколадные блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6946,'Просеять в одну емкость сахар и муку. Положить мягкое сливочное масло, добавить желтки, цедру лимона. Размешать до однородной смеси. Минут десять месить, чтобы получилось эластичную форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6939,'Порезать лук на кубики, мелко потереть имбирь. Нагреть бульон. Мелко порезать помидоры. Измельчить кинзу. Разогреть в кастрюльке растительное масло, положить имбирь и лук. Обжаривать, мешая. Посыпать специями, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6939,'Насыпать в кастрюльку чечевицу. Обжаривать минуту, помешивая. Налить горячий бульон. Уменьшить огонь, готовить десять минут. Добавить помидоры с соком, посыпать солью. Размешать, варить еще минут десять, чтобы чечевица стала мягкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6939,'Убрать с огня, положить кинзу. Размешать. Подавать суп с чечевицей в индийском стиле, посыпав колечками зеленого лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6940,'Смешать сметану (ряженку, кефир), яйца, соль, сахар, соду, гашеную уксусом, муку. Слепить и пожарить пирожки. Их получается довольно много. Можно разогревать их на сковороде под крышкой или в микроволновой печи. Начинка: фарш из любого мяса обжарить с луком, соединить с картофельным пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6941,'Измельчить рис в муку при помощи кофемолки. Перемалывать понемногу, сразу просеивать через мелкое ситечко, чтобы не попадались мелкие частички.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6941,'Перемешать рисовую муку с пшеничной, вбить яйцо, насыпать соль, долить воду, замесить крутое тесто. Плотней, чем для пельменей. Приготовить лапшу, используя ручную лапшерезку. Раскатать тоненько тесто, посыпать хорошенько мукой, пропустить через лапшерезку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6941,'Пожарить на оливковом масле кабачок, порезанный соломкой, до золотистого оттенка, помидор, порезанный на дольки, луковицу, порезанную на полукольца, рыбу, порезанную на кубики, чесночок на кружочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6941,'Вскипятить в кастрюльке воду, положить пожаренные овощи и рыбу. Добавить устричный соус, закипятить. Посыпать солью, положить рисовую лапшу. После закипания, выключить плиту, дать супчику постоять минут десять. Разлить вкусный суп с рисовой лапшой по тарелочкам, в каждую положить по 1/2 вареного яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6942,'Тоненько порезать листика шпината, оливки, лук, вяленые помидоры. Положить на тарелку лепешку, по желанию положить всего понемногу. Добавить потертую моцареллу, орегано, фету, хлопья красного перца. Не нужно класть много.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6942,'Сковороду нагреть. Положить лепешку с начинкой на сковороду, накрыть ее второй лепешкой без начинки. Когда краешки нижней лепешки станут коричневыми, перевернуть. Снять со сковороды кесадилья по-гречески, порезать на четыре части ножом для пиццы. Повторить с другими лепешками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6943,'Соединить соль, сахар, яйца. Взбить венчиком или миксером на маленьких оборотах. Налить молоко, воду. Не переставая мешать, понемногу насыпать просеянную муку. Влить масло, размешать. Перемешивать как угодно, главное, чтобы не образовались комочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6943,'Смазать сковороду салом или растительным маслом. Можно соединить растительное масло со сливочным, растопив его, смазывать сковороду при помощи силиконовой кисточки. Выпекать тонкие блинчики к завтраку с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6944,'Порезать и отбить мясо. На каждый кусок положить по ломтику сыра, сверху положить порезанные грибы, несколько долек чеснока. Можно измельчить его и соединить с грибочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6944,'Собрать края отбивных в мешочек, связать ниточкой, можно сложить зубочистками. Положить каждый мешочек в фольгу, которую предварительно необходимо свернуть в виде пиалы, посыпать перцем, солью, переложить в формочку, накрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6944,'Поставить минут на пятнадцать в духовку, снять фольгу, дать подрумяниться приблизительно минут десять. Сыр расплавится и вытечет в пиалу из фольги, соединить с соком от жаренья, не затрачивая времени, можно сделать вкусный соус. Если сыр не расплавился и остался в мешочке из свинины, то подавать желательно с соусом, сваренным отдельно, или сметанкой, перемешенной с зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6945,'Помыть листья салата, порезать на средние кусочки. На крупные кубики порезать огурцы, положить в салат. Порезать помидоры на средние кубики, положить в салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6945,'Порезать на маленькие кубики сыр фета, добавить в салат. Положить измельченный укроп, осторожно размешать. Посыпать перцем, солью, заправить маслом оливковым, бальзамическим уксусом. Добавить в овощной салат щепотку кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6946,'Разогреть духовку. Застелить противень специальной бумагой, намазать маслом, посыпать мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6947,'Растопить сливочное масло в кастрюльке с непригораемым дном и высокими стенками. Переложить мясо, чуть-чуть обжарить, переворачивая время от времени, крышкой не накрывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6947,'Когда мясо станет румяным – минут через пятнадцать налить белое вино, не накрывая крышкой, томить мясо, пока вино не испарится почти полностью. Нужно следить, чтобы мясо не прилипло ко дну.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6947,'Разогреть духовку до 180 градусов, положить мясо в формочку, полить соусом, оставшимся в кастрюльке, отправить в духовку. Переворачивать мясо каждые пятнадцать минут, поливать соусом, образовавшимся в формочке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6947,'Минут через сорок убавить температуру до 150 градусов, запекать мясо еще шестьдесят минут, переворачивать телятину в беконе через каждые двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6948,'Натереть свинину солью и смесью перцев, сделать дырочки с помощью ножа, засунуть в них чесночок, порезанный в длину, положить в посуду, застеленную фольгой (намазать фольгу растительным маслом). Положить с несколькими грибочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6948,'Потереть шампиньоны, сыр, измельчить красный острый перчик, добавить большую ложку майонеза для связки, перемешать. Осторожно и красиво выложить на мясо. Отправить на тридцать минут в духовку, выпекать острую свинину с шампиньонами и сыром, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6949,'Взбить яйца с солью. Положить майонез и сметанку. Размешать. Досыпать муку с содой. Замесить тесто. Сделать начинку: порезать зеленые перья лука, отваренные яйца. Посыпать солью. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6949,'Можно пирог готовить в мультиварке или духовке. Вылить половину теста в емкость мультиварки, смазанную маслом. Положить начинку, сверху распределить оставшееся тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6949,'Готовить пирог с зеленым луком и яйцом в мультиварке в режиме «Выпечка» пятьдесят минут. За семь минут до конца готовки перевернуть пирог. Вынуть готовый пирог из емкости. Остудить и можно подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6950,'Помыть яблоки, обсушить, порезать на четыре части, сердцевину вырезать. Если кожура очень жесткая, то срезать ее. Порезать яблоко на тоненькие дольки. Положить их в емкость, чтобы не потемнели сбрызнуть лимонным соком, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6950,'Миксером взбить яйца в пышную пенку. Насыпать сахар, не переставая взбивать. Ввести осторожно муку, используя большую ложку, размешать сверху вниз, чтобы тесто вобрало в себя муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6950,'Намазать формочку маслом, чуть-чуть припудрить мукой. Положить в нее яблочные дольки, вылить сверху тесто. Готовить минут 35, соблюдая температуру 180 градусов. Пока пирог будет готовиться, дверцу не открывать, так как он может опасть. Когда на ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6951,'Хорошенько помыть картофель, отварить в кожуре. Чуть-чуть остудить, почистить. Каждую картошку завернуть в несколько полосок бекона, положить в формочку, поставить в духовку, готовить минут десять, соблюдая температуру 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6951,'Во время готовки картофеля, приготовить соус. Разогреть в кастрюльке с толстым дном сливочное масло, насыпать муку, аккуратно, чтобы не появились комочки, налить бульон, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6951,'Убрать с огня, положить сметанку, насыпать перец, соль, добавить сок лимона, размешать. Вылить соус на картофель, отправить минут на пятнадцать в духовку. Посыпать картошку в беконовой одежке свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6952,'Мелко потереть сыр. Помыть и обсушить петрушку, измельчить. Просеять муку. Выдавить чесночок через чеснокодавку. Взбить яйца, соль и сахар при помощи миксера в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6952,'Подогреть слегка молоко, вылить в яичную смесь, размешать. Насыпать муку, разрыхлитель, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6952,'Всыпать сыр, положить чесночок, порезанную петрушку, налить масло. Снова размешать миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6952,'Жарить сырные блинчики с петрушкой на сковороде, смазанной один раз маслом. Готовые блинчики намазать чуть-чуть сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6953,'Порезать сыр, ветчину на очень маленькие кубики. Измельчить зелень (желательно укроп). Взбить яйца, перец и соль. Положить сметанку, размешать. Налить оливковое масло, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6953,'Положить сыр, ветчину, зелень, размешать. Насыпать разрыхлитель, муку, замесить тесто, на вид, как густая сметана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Обкрутить шашлыки по спирали, уложить на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6953,'Положить тесто по формочкам на 2/3, отправить в духовку, готовить тридцать минут, соблюдая температуру 180 градусов. Проверять готовность сухой зубочисткой. Остудить кексики с ветчиной и сыром на решетке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6954,'Положить в емкость яйца, соль, сахар. Взбить венчиком. Влить молоко и растопленное масло. Насыпать муку, размешать, чтобы исчезли комочки. Готовить на сковороде тоненькие блинчики без масла до золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6955,'В большой сковороде растопить масло сливочное. Положить картофель, лук, готовить, пока картофель не будет золотисто-коричневый. Положить сладкий перец. Добавить грибочки, готовить, пока не станут мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6955,'Сгрести овощи в одну сторону, на остальном месте поджарить бекон или колбасу. Полностью прожарить полностью мясо. Соединить с овощами, посыпать специями, положить шпинат, готовить минуту. Отдельно взбить молоко и яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6955,'Если сковорода большая, то сгрести в сторону мясо и овощи, поджарить омлет, добавив чуть-чуть масла. Если сковорода не достаточно большая, то приготовить омлет отдельно. Потом соединить с овоще-мясной массой. Наполнить тортильи начинкой, подавать бурито с беконом, грибами и картофелем с любым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6956,'Смешать миксером молоко, сахар, какао, растительное рафинированное масло. Поделить на две части. В одну  положить ванильный сахар, яйца, разрыхлитель, муку. Взбить при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6956,'Намазать формочку маслом, вылить массу с мукой, готовить минут 25, соблюдая температуру 180 градусов. Проверять готовность сухой зубочисткой. На готовый пирог вылить вторую часть смеси. Остудить (желательно оставить на ночь) и порезать необычное пирожное на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6957,'Мелко натереть сыр. То же сделать с чесноком. Половину сыра соединить с сушеным укропом и яйцом. Эту смесь использовать для покрытия запеканки, чтобы образовалась румяная аппетитная корочка. Остальной сыр соединить с яйцом, майонезом и чесноком. Это заготовка для запеканки. Ее необходимо приготовить заранее, чтобы тертый картофель не успел потемнеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6957,'Крупно потереть картофель, положить в заготовку. Посыпать перцем, солью. Взять формочку диаметром 26 сантиметров, выложить запеканку. Покрыть смесью из укропа, сыра, яиц. Отправить запеканку из тертого картофеля на сорок минут в духовку, запекать, соблюдая температуру 180 градусов. Должна появиться румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6958,'Отварить яйца вкрутую, порезать дольками. Порезать на тоненькие ломтики сыр моцарелла или скаморца. Приготовить томатный соус: положить на сковороду почищенные и порезанные на маленькие кусочки томаты, добавить чуть-чуть оливкового масла, насыпать сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6958,'Накрыть крышкой, потомить минут пятнадцать. Открыть крышку, выпарить почти всю жидкость, чтобы соус был густоватым. Если используются приготовленные на гриле замороженные баклажаны, то предварительно их не размораживать. Если нет, то порезать баклажаны вдоль, чтобы получились дольки по пол сантиметра в толщину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6958,'Пожарить в масле или приготовить на гриле, положить на салфетки, чтобы впиталось масло. Намазать формочку маслом, выложить слоями ингредиенты: баклажаны, тоненький слой томатного соуса, по ломтику сыра на каждый кусочек баклажана. Потом по дольке яйца на каждый баклажан. Посыпать тертым пармезаном. Должно получиться три слоя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6958,'Сверху обильно посыпать пармезаном, полить оливковым маслом. Готовить в духовке минут 25, соблюдая температуру 180 градусов, на пармезане должна образоваться золотистая корочка. Духовку выключить, оставить запеканку из баклажанов с сыром и помидорами минут на пять отдыхать. Подавать в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6959,'Порезать говядину на кусочки по три сантиметра, желательно использовать грудинку. В пятилитровую кастрюлю положить говядину и крупно порезанный репчатый лук. Можно добавить лавровый листик. Поставить кастрюльку на плиту, готовить бульон приблизительно шестьдесят минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6959,'Приготовить зажарку: порезать сало на кусочки по одному сантиметру. Сало должно быть домашнего копчения – должен быть ярко выражен вкус копчености. Такое сало сложно найти в продаже, поэтому можно применять жидкий дым, который можно найти в больших супермаркетах. Но более яркий вкус получается с салом, копченным в домашних условиях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6959,'Обжаривать сало на сковороде, пока не получатся шкварки, но не пережаривать. При использовании жидкого дыма необходимо при обжарке сала добавить три больших ложки его. Крупно потереть морковь, свеклу, порезать на кружочки лук, положить в сковороду к обжаренному салу, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6959,'Обжаривать, пока зажарка не будет одного цвета, в конце положить томатную пасту, размешать, обжаривать еще шестьдесят секунд. Зажарка должна иметь ярко выраженный запах копченостей. Положить зажарку в готовый бульон. Чтобы цвет свеклы и вкус копченостей стал ярче, положить в борщ половинку мелко порезанного лимона без кожуры. Варить минут десять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6959,'Шинковать капусту, когда борщ приобретет свекольного цвета, положить капусту в кастрюльку, варить пятнадцать минут, положить порезанный по 0,5 сантиметров картофель. Варить еще пятнадцать минут. Подавать украинский борщ с копченым салом, положив сметанку и украсив зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6960,'Загрузить все ингредиенты в хлебопечь, поставить режим «тесто». В период замеса подсыпать чуть-чуть муки. Когда работа хлебопечки закончена, положить тесто на стол, присыпанный мукой. Разделить его на четыре части. Раскатать в виде узеньких, длинных лепешек, свернуть рулетиком. Положить их в смазанную хлебную формочку, накрыть полотенцем, отставить на расстойку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6960,'Использовать формочку 24 на 10 сантиметров. Включить духовку на максимальную температуру, чтобы прогрелась. Тесто в это время должно подняться. Уменьшить в духовке температуру до 190 градусов, поставить хлеб. Выпекать до румяной корочки. Перед готовкой не смазывать ничем. После выпечки вынуть из формочки, выложить хлеб «Облако» на полотенце, прикрыть его краешками полотенца, отставить остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6961,'Взбить маскарпоне и сахар, положить сливки, взбитые до тягучего, густого состояния, снова взбить. Измельчить в блендере клубнику с сахаром. Положить в прямоугольную формочку слой бисквитного печенья, залить 1/2 смеси клубники с сахаром. Распределить равномерно 1/2 сырно-сливочной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6961,'Положить второй слой бисквитов, вылить остальную смесь клубники с сахаром. Выложить сверху остальную сырную массу, с помощью лопатки разровнять поверхность. Остальные ягоды порезать вдоль на четыре части, выложить кусочками клубники поверхность десерта. Поставить клубничный тирамису для пропитки в холодильник на пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6962,'Поделить тесто на две части. Раскатать два пласта: один положить в формочку для запекания из фольги или бумаги. Из второго пласта вырезать, как можно больше сердечек. Приготовить начинку: соединить с сахаром порезанную клубнику, заварить водой крахмал, довести до кипения с клубникой, чтобы чуть-чуть загустел.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6962,'Охладить, положить в формочку. Начиная от краев положить плотно сердечки внахлест. В центре оставить дырочку. Намазать желтком, посыпать сахаром, готовить клубничный сердечный пирог минут двадцать, соблюдая температуру 200 градусов. Должна получиться золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'Подогреть молоко, насыпать сахар, дрожжи, добавить муку, замесить тесто по консистенции, как жидкая сметанка. Накрыть пленочкой, отставить минут на двадцать, чтобы образовалась шапочка. Соединить яйца, соль, сахар, растительное масло в емкости, в которой будет замешено тесто. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'Подогреть молоко, налить в него опару, размешать, соединить масляную и яичную смесь. Насыпать пол килограмма муки и размешать при помощи ложки. Досыпать остальную муку. Может потребоваться больше муки, вымешивать руками. Когда тесто будет отставать от стенок емкости, перестать принимать муку, выложить тесто на стол, начать месить, тщательно, чтобы получилась однородная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'Намазать тесто растительным маслом, положить в емкость, намазанную маслом. Накрыть пленкой, поставить в теплое место часа на полтора, чтобы тесто увеличилось раза в два. Обмять тесто в посуде, снова закрыть пленкой, отставить часа на полтора. В это время заняться приготовлением начинки. К этому тесту подойдет начинка и сладкая, и несладкая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6984,'Соединить яйцо и кефир. В отдельной емкости соединить разрыхлитель, муку, сахар и соль. Соединить сухие и влажные смеси. Добавить тертое яблоко, перемешать. Получается невязкое тесто, чуть-чуть гуще сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'В брусничной начинке нет ничего сложного. Соединить бруснику и сахар. Чуть-чуть подавить ложкой, чтобы появился сок, добавить крахмал. Снова обмять тесто, накрыть полотенцем. Рядом поставить противень и начинку. Раскатывать и присыпать ничего не нужно, весь процесс будет делаться на весу. Руки намазать растительным маслом (делать это необходимо несколько раз).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'Оторвать от теста кусок по размеру с маленькое яйцо. Руками размять лепешку по размеру, как ладонь. В центр положить маленькую ложку начинки, как бы закрыть ладошку, второй рукой залепить тесто. Оно легко лепится. Начинки не должно быть очень много, чтобы она не просачивалась. Аккуратно подправить форму пирожка, чуть-чуть приплюснуть и положить на противень швом вниз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'На один противень помещается приблизительно двадцать пирожков, а всего из данного количества теста получается приблизительно 35 штук (плюс-минус пять штук). Перед началом выпечки накрыть пирожки полотенцем, поставить минут на двадцать для расстойки. Разогреть духовку до 180 градусов. Взболтать яйцо, намазать им пирожки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6963,'Выпекать минут десять с обдувом в режиме верх-низ. После этого еще минут пять готовить без обдува. Необходимо смотреть по цвету – пирожки должны приобрести румяную красивую корочку. Готовые пирожки с брусникой намазать растопленным сливочным маслом, сложить в емкость, накрыть полотенцем, дать полежать минут пятнадцать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6964,'Приготовить тесто: чуть-чуть взбить яйца до однородности. Насыпать сахар, положить мед, масло. Подогреть на водяной бане, поставив, посуду в кастрюльку с кипящей водой. Масло, яйца и мед должны превратиться в однородную смесь. Чтобы процесс ускорился, время от времени помешивать. Убрать с плиты, добавить гашеную соду. Размешать, масса должна побелеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6964,'Насыпать частями муку, вымешать при помощи ложки. Тесто должно быть липкое, вязкое. Больше муку не досыпать, тесто такое и должно быть. Намазать противень маслом. Положить на середину противня 1/5 часть теста. Подготовить тарелочку диаметром 25 сантиметров или крышку от кастрюльки, растянуть тесто в круг. Тесто будет липнуть к рукам, так и должно быть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6964,'Растянуть круг по диаметру немного больше, чем крышка. Чем равномерней получится круг, тем ровней получится корж. Отправить в духовку, разогретую на 200 градусов. Готовить минут восемь. Коржик должен стать темным и приобрести красноватый цвет, но краешки не должны пересохнуть и стать темными. Готовый корж обрезать в теплом виде при помощи той же крышки или тарелки. Если у крышки острые краешки, то нож можно не использовать. Если края плохо обрезаются от коржа, применить нож.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6964,'Таким же образом приготовить остальные коржи, получается пять штук. Каждый раз необходимо намазывать противень маслом. Можно использовать несколько противней, так будет и проще и быстрей. Пока готовится один корж, второй можно уже растягивать. Полученные обрезки от коржей измельчить при помощи  блендера. Приготовить крем: взбить до плотности сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6964,'Насыпать обычный и ванильный сахар, положить сметану, взбивать, пока сахар не растворится. Положить на большую тарелку первый корж. Намазать приблизительно 1/5 частью крема. Получается  слой крема довольно толстый, затем он немного впитается в коржик. Таким образом положить остальные коржи. Каждый смазывать кремом. Последний корж тоже намазать кремом, обмазать тортик по бокам. Отправить торт «Медовик» со сметанным кремом в холодильник часа на четыре для пропитки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6965,'Порезать огурцы и свеклу на кубики, добавить прессованный чесночок, положить горошек. Заправить майонезом, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6966,'Отварить картофель в кожуре, почистить, крупно натереть. Взять овальное блюдо, выложить слоями. Сначала положить картофель, намазать его майонезом. Второй слой состоит из измельченного зеленого лука. Взять копченый окорочок, отделить мясо от кости, мелко порезать мясо. Третий слой – половина порезанного мяса, намазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6975,'Готовый пласт достать, накрыть полотенцем, остудить минут пятнадцать, намазать кремом, свернуть рулетик. Крем можно использовать творожный, сметанный, заварной, масляный или меренг – по желанию. Можно торт-рулет «Легче легкого» посыпать сахарной пудрой. Украсить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Коржи (основу пиццы) намазать соусом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6966,'Четвертый слой – порезанные маринованные огурчики. Пятый – оставшийся порезанный окорочок. Намазать майонезом. Шестой слой – тертый сыр. Отварить яйца, почистить, крупно потереть. Седьмой слой – тертые яйца, намазать майонезом. Украсить салат «Ананас» перышками зеленого лука и половинками грецких орешков, но можно использовать и другие варианты, например, киви – грибы и так далее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6967,'Приготовить тесто: насыпать в сметану соль и соду, положить мягкий маргарин. Насыпать в массу столько муки, чтобы тесто было, как пластилин и не прилипало к рукам. Отставить минут на пятнадцать. Куриную грудку порезать на небольшие кусочки. Картофель порезать на кубики. Положить картофель к грудкам. Мелко порезать лук. Добавить к картофелю с мясом. Все размешать, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6967,'Взять чуть-чуть теста, сделать блины по размеру, как ладонь. Внутрь положить начинку. Свернуть в виде полузакрытой корзиночки, защепляя краешки, в центре оставить открытое место. Положить на противень специальную бумагу, намазанную растительным маслом. На бумагу положить курники. Подогреть до 220 градусов духовку, готовить домашние курники минут двадцать, пока не образуется румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6968,'Замариновать рыбное филе приблизительно минут на тридцать. Для этого полить рыбу соком лимона и соевым соусом. Можно использовать любую рыбку без костей. Посыпать красным и черным перцем, солью, куркумой, любыми специями. Подготовить емкость, в которой будет готовиться рыба. На дно положить картофель, порезанный на тоненькие ломтики. Резать необходимо, как можно тоньше, чтобы он хорошо пропекся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6968,'На картофель положить порезанный на полукольца лук. Посыпать перцем, солью, другими специями, зеленью. Сверху выложить рыбу. Добавить помидор, выложить сверху лук. Вновь положить картофель, посыпать солью, специями, зеленью. Полить майонезом, посыпать мелко потертым сыром. Отправить емкость в духовку на 45 минут, соблюдать температуру 180 градусов. Достать через 45 минут и разложить волшебную рыбку с картофелем по тарелочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6969,'Почистить большую редьку, крупно потереть. Посыпать солью, размешать, положить в дуршлаг, помещенный в кастрюльку, чтобы стек сок. Порезать мелко куриный жирок с кожей, обжарить на растительном масле, на большом огне, затем убавить его.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6969,'Когда шкварки станут румяными, положить лук, порезанный тоненькой соломкой. Посыпать солью. Жарить до золотистого оттенка, помешивая. Остудить. Положить редьку с куриными шкварками в емкость, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6970,'Взять ровный, плотный кусочек мяса прямоугольной формы. Сделать на ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6970,'Порезать сыр на ломтики, помидоры на кольца, чесночок измельчить. В надрезы положить помидор, чеснок и сыр. Можно положить ломтики грибов. Завернуть мясо в фольгу, положить на противень, отправить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6971,'Посыпать перцем и солью майонез, добавить прессованный чесночок, размешать. Положить куриные грудки на противень, намазанный растительным маслом, смазать мясо подготовленным майонезом. Мелко потереть сыр, посыпать им мясо. Поставить куриные грудки с сыром минут на шестьдесят в духовку, соблюдать температуру 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6972,'Соединить все продукты, кроме воды и масла. Смешать их блендером до однородной массы. Не переставая смешивать, осторожно влить оливковое масло. Налить воду, вновь перемешать. Добавить заправку в основное блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6973,'Подготовить ингредиенты: порвать на волокна отваренное куриное филе, обжарить шампиньоны и лук, крупно порезать яйца, крупно потереть сыр, майонез, корейскую морковь. Выложить салатик слоями в глубокую емкость, каждый слой намазывать майонезом. Сначала положить отваренное филе, грибы с луком, корейскую морковь, яйца, посыпать салат «Рафаэлло» сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6974,'Взбить яйца и сахар, ввести постепенно муку. Намазать лист растительным маслом, с помощью маленькой ложки положить количество лепесточков для одной розы. Выпекать минуты три, соблюдать температуру 200 градусов. Лепестки в горячем виде формировать на сладкой соломке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6975,'Все соединить, вылить в формочку, выпекать минут 25, соблюдать температуру 210-250 градусов. Данное тесто подойдет и для рулетиков. Выложить тоненько тесто на смазанную маслом специальную бумагу. Отправить в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6976,'Залить дрожжи теплым молоком, отставить минут на десять, чтобы настоялись и появилась пенная шапочка. Насыпать сахар, ваниль, положить масло, вбить яйцо и белок (желток оставить для смазки пирога). Насыпать понемногу просеянную предварительно муку, замесить тесто. Выложить в емкость, накрыть полиэтиленом, отправить в тепло минут на шестьдесят. Тесто должно подняться в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6976,'Спустя время обмять тесто и отставить еще на пятьдесят минут, чтобы повторно поднялось. Когда тесто поднимется раза в два-три, обмять его, чтобы вышли пузырьки воздуха, поделить на две части, раскатать прямоугольники по семь миллиметров в толщину. Поделить тесто зрительно на три части вдоль, на крайних частях сделать десять надрезов под углом 45 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6976,'На серединку прямоугольника насыпать чуть-чуть крахмала, чтобы не растекалась начинка. На середину одного пласта положить дорожку джема из клюквы, на середину второго – лимонный джем. На джем насыпать еще чуть-чуть крахмала. Заплести косичку, намазать пироги сверху желтком. Можно посыпать еще кунжутом или маком. Готовить новогодние плетенки «Проще простого» минут тридцать, соблюдать при этом температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6977,'Начинать готовить тортик необходимо с основы. Для этого в блендере или кухонном комбайне измельчить печенье в крошку. Если нет под рукой техники, использовать скалку, обернуть печенье в пакет и раскатать скалкой. Предварительно подержать в тепле сливочное масло, чтобы оно подтаяло. Если на это нет времени, то растопить его на водяной бане или в микроволновой печи. В емкость с крошкой печенья насыпать муку, хорошенько размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6977,'Взять разъемную формочку для торта диаметром приблизительно 22 сантиметра. На дно постелить специальную бумагу, положить тесто из печенья на дно формочки, распределить равномерно, утрамбовать. Отправить тесто минут на тридцать в холодильник. Приступить к основной части тортика – желейному крему. Залить желатин водой, минут на десять оставить набухать или сделать так, как рекомендуется на упаковке. Поставить желатин на маленький огонь, подогреть не более, чем до пятидесяти градусов, нельзя кипятить. Мешать жидкость, пока желатин не растворится полностью. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6977,'Заранее протереть творог через ситечко. Должна получиться гладкая, не зернистая масса, насыпать обычный и ванильный сахар, положить сметану. Взять лайм, срезать с обоих краев примерно 1/4 части, выжать сок (получится приблизительно две большие ложки). Среднюю часть лайма использовать для украшения. Взбивать, пока сахар не растворится. Желательно делать это в глубокой емкости, чтобы не брызгала сметана. Во взбитую массу достаточно медленно налить желатин, не переставая взбивать. Вылить получившийся крем в формочку на основу из печенья, снова поставить тортик в холодильник часа на два.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6977,'Взять желе, готовить так, как сказано в инструкции на упаковке, но воды необходимо налить на сто миллилитров меньше. Подождать, пока желе остынет, достать тортик, на застывший сметано-творожный слой вылить желе. Отправить готовый желейный торт с лаймом в холодильник часов на пять, чтобы застыли все слои. Перед подачей достать тортик из формочки. Украсить, например, можно сформировать завитушки из лайма, порезанного на тоненькие кружочки и положить листики лайма.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6978,'Помыть картофель, залить холодной водой, отварить в кожуре до готовности. Слить воду, залить холодной водой, чтобы остыл, почистить. Отварить отдельно яйца вкрутую, залить холодной водой, остудить, почистить. Соединить майонез с почищенным и прессованным чесночком. Если майонез очень густой, то чуть-чуть разбавить холодной кипяченой водой, размешать. Блюдо для салатика приложить к листу бумаги вверх дном, обвести карандашом, вырезать. Нарисовать на круге мордочку овечки, осторожно ее вырезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6978,'Бумагу с контуром в виде головы овцы положить на блюдо, чуть-чуть намочить водой, чтобы она не смещалась с места – это делать не обязательно, но так проще выкладывать салат. Крупно потереть картофель, выложить первый слой салатика. Чуть-чуть посыпать перцем и солью. Намазать майонезом с чесноком. Отрезать два куска копченого мяса, вырезать ушки для овечки, отложить в сторону. К примеру, можно вырезать два кружка (обвести ножом стакан, потом срезать 1/3 кружка, остальные 2/3 – ушко).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6978,'Оставшееся мясо порезать на небольшие кубики, выложить второй слой. Намазать майонезом. В отдельные емкости потереть белки и желтки: белки потереть крупно, желтки – мелко. Выложить слой желтков. Не смазывать майонезом. Порезать на кубики маринованные или соленые огурчики, выложить четвертый слой. Хорошенько намазать салатик сверху и по бокам майонезом. Выложить белок, покрыть им бока и верх салатика. Намазать майонезом место, где будет овечья челка, посыпать крупно натертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6978,'Осторожно убрать бумагу, придерживая краешки салата обратной стороной ножа или кулинарной лопаткой. Положить на блюдо подготовленные овечьи ушки. Отправить салатик часа на три в холодильник для пропитки. Украсить салат «Овечка»: глаза, рот и ресницы сделать из черных маслин, из кусочка маслины и болгарского перчика сделать цветок, нарисовать серединку цветка, уши, зрачки майонезом. Можно использовать в качестве украшения веточку зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6979,'Вымыть и почистить овощи, выложить слоями в емкость. Сначала лук, порезанный полукольцами. Затем свеклу, потертую крупно. Далее так же потертую морковь. Перец, порезанный тоненькой соломкой, помидоры, порезанные на полукружки. Посыпать солью, сахаром. Полить маслом, уксусом. Перемешать, поставить на тихий огонь. Когда выделится сок, увеличить огонь, готовить 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6979,'В горячем виде разложить по банкам и закатать. Заправка для борща зимой будет просто находкой. Необходимо будет сварить бульон, положить картофель, капусту, чуть-чуть поварить. Положить заправку из банки, измельченный чеснок, через 7-10 минут можно подавать вкусный борщ со сметаной и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6980,'Приготовить начинку для ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6980,'Посыпать сыром. Отправить на 7 минут в духовку, соблюдать температуру 180 градусов. Получаются хрустящие горячие бутерброды с сочной начинкой, которые особенно придутся по вкусу детям.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6981,'Разморозить тесто. Порезать вдоль на полоски по 2 сантиметра.  Порезать колбасу на тоненькие кружочки, разрезать на 2 части. На полоску, внахлест, положить кусочки колбасы так, чтобы конец остался свободным. Свернуть в виде рулета. Конец подвернуть под низ.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6981,'Застелить противень пекарной бумагой, выложить заготовки, подождать, пока они подойдут. Готовить колбасные «Розочки» из слоеного теста при температуре, указанной на упаковке от теста, 15-20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6982,'Приготовить опару. Налить в емкость теплую воду и молоко, насыпать дрожжи, сахар, 4 большие ложки муки. Перемешивать, пока дрожжи не растворятся. Накрыть пленкой, отставить на полчаса, чтобы поднялась «шапочка». Убрать пленку с опары, увеличенной в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6982,'Добавить майонез, постепенно насыпать просеянную муку. Замесить тесто, накрыть пленкой, поставить на полтора часа в тепло. Выложить тесто для пирожков на стол, обмять, чтобы вышел воздух.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6983,'Чуть-чуть взбить яйцо миксером. Постепенно добавить сахар, каждый раз взбивая. Налить растительное масло без запаха. Налить кефир, добавить холодную воду. Перемешать венчиком. Добавить уксус, перемешать, отставить. Соединить какао, муку, соду, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6983,'Высыпать в первую смесь. Перемешать венчиком. Взять форму размером 35 на 25, постелить в нее специальную бумагу, налить тесто. Выпекать до готовности, соблюдать температуру 180 градусов. Желательно сильно не запекать, чтобы коржи не получились очень сухими. Перевернуть корж на полотенце, дать остыть. Таким же образом приготовить еще один корж. Желательно дать коржам полежать приблизительно 6 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6983,'Разрезать коржи поперек, чтобы получилось 4 штуки. Коржи получаются очень нежные, поэтому переносить необходимо, используя полотенце. Приготовить крем: взбить миксером мягкое сливочное масло. Положить сливочный сыр. Взбивать, пока масса чуть-чуть не загустеет. Добавить крем из фундука. Взбить. Отправить в холодильник на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6983,'На следующий день собрать торт. Намазать все коржи кремом, а также верх и бока. Сделать ганаш: поломать шоколад на куски, положить в горячие сливки, перемешать до однородности. Остудить ганаш, вылить на влажный шоколадный торт. Отправить на 4-5 часов в холод, чтобы ганаш застыл.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7676,'Отварить нечищеный картофель в подсоленной воде, почистить, сделать пюре, но не однородное, а с небольшими целыми кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6984,'Нагреть сковороду, налить тоненький слой масла, столовой ложкой положить тесто на сковороду, слегка придавить, чтобы получилась форма оладушка. Пожарить до золотистого цвета, перевернуть. Обжарить пышные оладьи с яблоком несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6985,'Протереть творог через сито, положить сметану, перемешать. Помыть фрукты, почистить ананас и киви. Отрезать плодоножку у клубники. Разрезать клубнику на 4 части, ананас и киви порезать на брусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6985,'Приблизительно на 1/3 часть от края блина положить полосой смесь из творога и сметаны. Рядом выложить фрукты, свернуть блин в виде рулета. Повторять процесс, пока не закончится начинка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6985,'Отправить в холодильник на полтора часа. Перед подачей порезать сладкие творожные роллы с фруктами на маленькие кусочки, разложить на блюдо, посыпать стружкой шоколада.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6986,'Соединить творог, мед и йогурт. Перемешать, используя блендер. Взять полиэтилен, посыпать цветной кокосовой стружкой всю поверхность пленки. Распределить по пленке массу из творога, осторожно сформировать прямоугольник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6986,'Разложить на твороге чернослив, порезанный на кусочки, свернуть творог в виде рулета, помогая пленкой. Отправить в холод. Выложить творожные роллы с черносливом на тарелку, украсить орехами или фруктами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6987,'Отделить куриное филе от косточки, порезать на большие куски, посыпать солью и перцем. Подготовить три емкости. В одну вбить яйцо, в другую насыпать муку, в третью – панировочные сухари. Обмакнуть каждый кусочек мяса в муку, затем в яйцо, потом в сухарики. Стряхнуть лишние сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6987,'Нагреть в сковороде растительное масло, чтобы было покрыто дно. Положить на сковороду запанированные кусочки мяса. Не класть много кусочков, в процессе готовки они не должны соприкасаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6987,'Жарить куриные наггетсы с двух сторон, пока не появится корочка. Выложить на тарелку, покрытую салфетками, чтобы они впитали лишнее масло. Подавать в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6988,'Разрезать на четыре одинаковые части лист лаваша. Размять вилкой творог, чуть-чуть посыпать перцем, солью, положить йогурт, измельченную петрушку. Перемешать. Разрезать помидоры на четыре части, убрать семена и жидкость, порезать на кусочки. Мелко потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6988,'Положить начинку из творога на кусочки лаваша, на начинку положить кусочки помидоров, тертый сыр. Свернуть, обжарить рулеты из лаваша с творогом и помидорами на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6989,'Разобрать цветную капусту на соцветия. Закипятить воду, посолить, отваривать капусту 4-5 минут. Выложить на дуршлаг, дать остыть. Сделать панировку: соединить сыр, сухари, паприку, чесночный порошок. Взбить яйца вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6989,'Постелить на противень специальную бумагу, намазать растительным маслом. Окунуть куски капусты в яйцо, потом обвалять в панировке, выложить на противень. Запекать цветную капусту с сыром 15 минут в духовке, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6990,'Чуть-чуть отбить ровные и большие кусочки куриного филе, посыпать солью и перцем. Добавить в мясной фарш лук, порезанный мелко, болгарский перец, порезанный на кубики, чеснок. Добавить перец, соль. Вбить в фарш яйцо. Порезать грибы на небольшие пластинки. Потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6990,'Положить в форму подготовленное филе, выложить на мясо фарш с перцем. По кругу выложить кусочки шампиньонов. В середине посыпать сыром. Отправить куриное филе с грибами и мясным фаршем в горячую духовку, выпекать приблизительно 35 минут, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6991,'Порезать куриное филе на кусочки, отбить. Посыпать перцем, солью, отложить в сторону. Сделать кляр. Потереть на средней терке или измельчить в блендере лук. Вбить яйца, положить сметану, майонез. Посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6991,'Порциями ввести муку. Перемешать содержимое до однородности. Обмакнуть мясо в кляр, обжарить на растительном масле, накрыв крышкой. Выложить куриные отбивные на блюдо, украсить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6992,'Соединить черный перец, соль, сахар, молотый чили на плоской тарелке. Просушить насухо стейки из семги, обвалять их в подготовленной смеси. Нагреть на сковороде оливковое масло. Выложить семгу, готовить на небольшом огне, переворачивая. Лосось должен с обеих сторон карамелизоваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6992,'Приготовить соус из апельсина. Срезать с апельсина цедру, выжать сок в емкость. Измельчить цедру и имбирь. Разрезать вдоль перец чили, убрать семена. Мелко порезать кусочек перца (количество перца зависит от вкуса).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6992,'Добавить в апельсиновый сок воду в объеме сока. Положить имбирь, цедру, чили, довести до кипения. Попробовать соус на вкус. Если необходимо, добавить перец, сахар. Процедить. Подавать острый стейк семги в соусе с зеленым салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6993,'Разморозить тесто, раскатать, сделать проколы вилкой. Выпекать четыре коржа, соблюдая температуру 180 градусов. Обрезать неровные края, сделать крошку для посыпки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6993,'Сделать крем: взбить яйца, сахар, муку. Довести до кипения молоко, ввести приготовленную смесь, помешивая. Мешать, пока не загустеет крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6993,'Положить в крем сливочное масло, дать ему растаять. Остудить крем. Намазать коржи, посыпать крошкой, отправить торт «Наполеон» на ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6994,'Порезать куриную грудку на маленькие кусочки, обжарить на растительном масле. Посыпать перцем, солью. Нашинковать капусту. Порезать болгарский перец, помидоры, огурцы. Порезать мелко остывшую курицу. Измельчить зелень. Сделать соус из сметаны. Соединить сметану и прессованный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6994,'Посыпать солью, перемешать. Добавить кетчуп и сметану. Перемешать. Порезать лаваш. На него положить начинку на расстоянии 4 сантиметра от края. Подогнуть боковые края лаваша, подогнуть, закрутить шаверму с куриным филе в виде рулета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6995,'Вымыть огурцы, срезать шкурку, если она грубая. Порезать на бруски или кружки. Посыпать солью, размешать, отставить на 20 минут, чтобы выделился сок. Слить сок, добавить уксус, соевый соус, острый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6995,'Нагреть масло на сковороде, выключить, насыпать кунжут – следить, чтобы не сгорел. Соединить огурцы и кунжут с маслом, положить прессованный чеснок. Хорошенько перемешать. Отправить на 1-2 часа в холодильник, чтобы огурцы по-корейски настоялись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6996,'Сделать в грудках кармашки, положить в них одинаковое количество сыра. Края мяса сколоть зубочистками, чтобы во время приготовления сыр не выливался. Приготовить три панировки – яйцо, взбитое с черным перцем, смесь муки и черного перца, панировочные сухари.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6996,'Окунуть мясо в муку, потом в яйцо, в последнюю очередь обвалять в сухарях. Обжаривать 3-5 минут на сковороде. Переложить на противень, готовить 20 минут, соблюдать температуру 200 градусов. Подавать куриные грудки с сыром со свежей зеленью, рисом, овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6997,'Подготовить ингредиенты. Измельчить лук, обжарить. Остудить лук в холодильнике. В фарш положить лук, мускатный орех, масло, хлебные крошки, цедру. Вбить яйца, посолить, поперчить. Перемешать. Сформировать небольшие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6997,'Положить заготовки на противень, выпекать в горячей духовке 15 минут, соблюдать температуру 200 градусов. Достать шарики. Нагреть сливки на водяной бане. Соединить сливки и горячий бульон. Осторожно переложить шарики в форму. Залить приготовленными сливками. Отправить на 20 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6997,'Достать шарики, слить соус в посуду. Растопить сливочное масло, насыпать две большие ложки муки, чуть-чуть обжарить муку. Вылить в сковороду сливочный соус, на тихом огне готовить шарики со сливочным соусом, пока соус не загустеет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6998,'Порезать продукты на средние брусочки. Баклажаны, не замачивая в соли, обжарить на раскаленном масле. Постоянно помешивать. За несколько минут до конца готовки добавить к баклажанам соевый соус. Перемешать. Использовать желательно натуральный соевый соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6998,'Отставить баклажаны, чтобы они остыли. Порезать на брусочки брынзу или адыгейский сыр и помидоры. Положить в салатник все ингредиенты. Салат можно не заправлять, так как баклажаны впитывают масло во время жарки – его достаточно. Добавить в салат с баклажанами рубленные грецкие орехи и зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6999,'При помощи блендера взбить сыр, яйца, плавленые сырки до однородности. Постелить на противень специальную бумагу, вылить полученную смесь. Отправить на 30 минут в духовку, соблюдать температуру 200 градусов. Куриный фарш посыпать перцем, солью, добавить болгарский перец, зелень, чеснок. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11231,'Вбить яйца по одному, перемешивать ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (6999,'Достать лепешку из духовки, положить на стол. Равномерно распределить по лепешке сырой фарш. Свернуть в виде рулета, вернуть на 30 минут в духовку, прикрыв рулет фольгой. Достать готовый сырно-яичный рулет, прикрыть полотенцем. Когда остынет, порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7000,'Положить в кефир молотый перец, измельченный укроп, чеснок. Размешать. Порезать грудку на кусочки, положить в кефир, отставить на 30-60 минут, чтобы замариновалось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7000,'Положить мясо на сухую сковороду. Добавить чуть-чуть маринада. Тушить куриную грудку в кефире по готовности, накрыв крышкой. Время от времени подливать соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7001,'Отварить рис до полуготового состояния. Соединить с фаршем. Мелко порезать морковь и лук, обжарить на сковороде. Положить зажарку в фарш. Добавить перец, соль, майонез. Перемешать. Сделать тефтели, положить в формочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7001,'Приготовить подливу: соединить томатный соус, воду, майонез, сметану, муку. Посыпать по вкусу перцем и солью. Полить соусом тефтели. Запекать тефтели с рисом 30 минут, соблюдать температуру 180-200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7002,'Взбить яйца и сахар. Когда масса станет пышной, добавить сметану и растопленное масло, продолжая взбивать. Насыпать муку, разрыхлитель, ванилин. Перемешать. Вымыть яблоки, почистить, порезать на 4 части, удалить серединку, порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7002,'Замочить изюм, слить воду, просушить. Намазать форму маслом, присыпать сухариками. В форму налить 1/2 теста. Выложить яблоки с изюмом. Залить остальным тестом. Выпекать в духовке 20 минут, соблюдать температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7002,'Достать пирог, посыпать присыпкой. Для присыпки: смешать муку и сливочное масло, растереть в крошку, насыпать сахар. Перемешать. Отправить яблочный пирог «Домашний» на 20 минут в духовку. Убрать кольцо, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7003,'Положить в ковшик ягоды, сок и цедру лимона, соль, сахар. Готовить на среднем огне 3 минуты, помешивая. Ягоды должны полопаться. Положить ягоды в блендер, измельчать минуту. Положить сливки, сметану. Снова взбить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7003,'Попробовать, добавить по вкусу сок лимона или сахар. Лучше готовить в мороженице. Если ее нет, то налить смесь в контейнер. Отправить в морозилку до застывания. Каждые 30 минут перемешивать черничное мороженое венчиком или ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7004,'Начинать приготовление с моркови. Разрезать ее пополам вдоль, а потом кольцами по 5-8 миллиметров. Измельчить лук и чеснок. Обжарить чеснок с луком в кастрюле на оливковом масле. Залить куриным бульоном, положить морковь. Если бульона нет, то налить воду и насыпать любые приправы и специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7004,'Положить фрикадельки. Чтобы они не прилипли друг к другу, опускать их по одной и в разные части кастрюли. Время от времени прокалывать морковь. Варить несколько минут. Накрыть крышкой, дать настояться 20 минут. Подавать суп с фрикадельками со свежим хлебом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7005,'Нагреть духовку до 180-190 градусов. Взбивать яйца и сахар, пока не получится пышная смесь. Постепенно насыпать муку, перемешать. Положить изюм, миндаль, мелко порезанную курагу. Перемешать. Сделать из теста батончики. Положить на противень, удерживая расстояние.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7005,'Чуть-чуть прижать батончики, выпекать 30 минут. Оставить их на решетке на 10 минут, чтобы остыли. Порезать батоны под углом на кусочки толщиной 1 сантиметр. Разложить бискотти на противень, готовить 10 минут. Остудить. По желанию можно обмакнуть в шоколад. Подавать бискотти с чаем или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7006,'Порезать грибы на 2-4 части. Если они мелкие, то можно не резать. Налить в посуду оливковое масло, положить прессованный чеснок. Насыпать перец, приправы, соль. Добавить уксус. Вылить смесь к шампиньонам, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7006,'Мариновать 15-20 минут, переложить в формочку, отправить в духовку. Запекать 15-20 минут, соблюдать температуру 200 градусов. В процессе готовки несколько раз перемешивать шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7007,'Насыпать в емкость 200 грамм муки, порезать масло. Растереть руками в крошку. Положить желтки, насыпать сахар и разрыхлитель. Замесить тесто, постепенно добавляя муку, если необходимо. Если не получается замесить, то добавить ложку воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Отварить мякоть свинины с морковью, картофелем, сельдереем, луком и лавровым листом, мясо перекрутить на мясорубке с мелкой решеткой, добавить нарезанные мелкими кубиками овощи и масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7007,'Постелить на противень или в форму размером 25 на 30 или 20 на 30 сантиметров специальную бумагу. Края бумаги должны чуть-чуть выступать за бортики, чтобы проще было достать корж. Раскатать тесто, намотать на скалку, переложить в форму. Равномерно распределить тесто. Выложить по всей поверхности замороженные ягоды или варенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7007,'Взбить сахарную пудру и 4 белка. Добавить крахмал. Размешать. Выложить меренгу на ягоды. Равномерно распределить. Посыпать орехами. Выпекать 40 минут, соблюдая температуру 180 градусов. Чтобы не подгорали белки, можно накрыть фольгой. Приготовить крем: налить молоко в кастрюлю с антипригарным покрытием, насыпать сахар, крахмал, ванилин, муку. Добавить желток. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7007,'Готовить на тихом огне, пока крем не станет густым. Непрерывно помешивать. Остудить. Достать готовый корж, остудить. Аккуратно переложить корж с противня на поднос. Разрезать пополам. Взбить сливочное масло, постепенно добавлять остывший крем, взбивая. Отправить ягодный слоеный пляцок в холодильник, чтобы крем застыл. Покрыть один корж кремом. Вторую часть коржа положить сверху, прижать. Отправить на 2 часа в холодильник. Порезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7008,'Взбить мягкое сливочное масло и сахар. Положить творог. Размешать. Насыпать муку, разрыхлитель, ванильный сахар. Вымесить тесто. Завернуть в полиэтилен, отправить в холод на 30 минут. Количество муки зависит от влажности творога. Вымыть яблоки, снять кожуру, удалить семена, разрезать на 2 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7008,'В серединку яблок положить начинку. В качестве начинки можно использовать финики без косточек, чернослив, курагу, грецкий орех, ирис, даже мандаринки. Разделить тесто пополам. Одну часть раскатать, выложить на противень, сделав бортики. На пласт положить яблоки начинкой вниз, присыпать корицей. Если яблоки не сладкие, то посыпать сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7008,'Использовать форму размером 20 на 30 сантиметров. Раскатать вторую часть теста, положить на яблоки. Защипнуть края, сверху намазать пирог желтком. Готовить 40-60 минут, соблюдать температуру 180 градусов. Посыпать готовый пирог из творожного теста сахарной пудрой. Подавать пирог теплым с ванильным мороженым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7009,'Миксером чуть-чуть взбить белки, насыпать ванилин, сахар, лимонную кислоту. Поставить на водяную баню. Взбивать 10-15 минут до пышной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7009,'Когда крем будет наворачиваться на венчик, снять с плиты, взбивать несколько минут. Остудить белковый крем, добавить красители. Можно украшать кремом торт или делать десерты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7010,'Для начинки необходимо приготовить фарш, как на пельмени. Перемолоть рубленое мясо с луком, добавить по вкусу перец и соль. Пожарить блины, свернуть в бендерики. Когда готово 10 блинов, можно приступить к сборке. Разрезать блинчики пополам. На каждую часть положить чуть-чуть фарша. Свернуть 1/2 блина с фаршем в виде треугольника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7010,'Получается вдвое больше вкусных блинчиков с курицей. Можно обжарить небольшое количество блинов, а остальные сложить в контейнер и отправить в морозилку. В любой момент можно достать и обжарить на сливочном масле. Перед обжариванием можно окунуть блинчики с куриным фаршем в яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7011,'Взбить белок до пиков. Перетереть смородину в пюре. Залить желатин водой, и добавить подсластитель. Поставить на огонь, мешать, пока не растворится. Добавить желатин в белок, взбить, ввести пюре из смородины. Взбить миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7011,'Переложить суфле в форму, дать чуть-чуть остыть. Отправить в холодильник на несколько часов. Когда застынет осторожно извлечь торт-суфле со смородиной из формы, порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7012,'Взбить яйца, сливки и приправы. Ветчину и помидоры порезать на тоненькие ломтики. Мелко потереть сыр. Раскатать тесто для пирога, положить на горячую сковороду. Посыпать ветчиной, сыром. Полить сливочно-яичной смесью. Выложить кусочки помидора. Отправить на 8 минут в духовку. Достать и дать сырному пирогу отстояться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7013,'Приготовить тесто: взбить масло и сахар, вбить яйцо, взбить. Добавить ванильный экстракт. Просеять муку с разрыхлителем. Ввести в тесто ½ муки, перемешать. Налить молоко, перемешать. Добавить остальную муку. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Вбить в массу желтки, посолить и поперчить, взбить в отдельной посуде белки, все тщательно смешать, включить для разогрева духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7013,'Сделать карамель: нагревать масло и сахар на сковороде, пока не растворятся крупинки. Добавить корицу. Налить карамель в форму. Положить бананы, порезанные на ломтики по 0,5 сантиметров. Сверху распределить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7013,'Готовить 20 минут, соблюдать температуру 180 градусов. Готовый бананово-карамельный пирог отставить на 3 минуты, затем перевернуть на блюдо, чтобы бананы оказались сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7014,'Нашинковать капусту. Крупно потереть помидоры, кожура должна остаться в руках. Нагреть в сотейнике ложку сливочного и ложку оливкового масла. Обжарить капусту, пока она не станет чуть-чуть карамельного цвета. Посыпать солью, размешать. Положить к капусте тертые помидоры. Насыпать маленькую ложку сахара. Тушить, пока не испарится жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7014,'В другой сотейник положить ложку сливочного и ложку оливкового масла. Обжарить измельченный лук. К луку добавить фарш. Насыпать перец, соль. Обжаривать, пока не испарится жидкость. Порезать лук, болгарский перец, морковь на кубики. В кастрюлю на 4 литра положить фарш, порезанные овощи, налить 2 литра воды, варить, пока не приготовятся овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7014,'Насыпать перец и соль. Положить тушеную капусту, готовить пять минут после закипания. Положить измельченную петрушку и укроп, добавить ложку сока лимона. Через минуту выключить суп. Если необходимо, досыпать перец, соль. Дать сытному супу с овощами и мясным фаршем 15 минут настояться. Подавать с измельченной зеленью и сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7015,'Взять филе, пропустить через мясорубку. Залить молоком, отставить на 30-40 минут. Почистить чеснок. Превратить фарш в молоке в пюре при помощи блендера. Положить в пюре горчицу, чеснок, посыпать солью и специями. Взять соломенный коврик, постелить пищевую пленку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7015,'Используя кондитерский шприц, выложить пюре из курицы в виде полоски любой длины. Оставлять по три сантиметра на кончиках пленки. Во время сворачивания постараться не оставлять воздух в сосисках. Плотно свернуть, завязать кончики. Отправить сосиски из куриного филе в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7016,'Приготовить блины: перемолоть хлопья в порошок, взбить яйцо и соль. Налить воду и теплый кефир. Насыпать перемолотые хлопья. Все взбить. Готовить на сухой сковороде. Приготовить начинку: растереть творог, яйцо, ванилин, подсластитель, измельченную курагу. Перемешать. Положить чуть-чуть начинки на блин, свернуть в виде рулетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7016,'Намазать маслом форму. Выложить начиненные блины по спирали. Сделать заливку: чуть-чуть взбить яйца и подсластитель, положить йогурт, перемешать до однородности. Вылить заливку на блины, отправить блинный пирог в духовку на 30-35 минут, соблюдать температуру 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7017,'Растереть творог и яйца, добавить помидор, порезанный на маленькие кубики, зелень, перец, крупно натертый сыр. Переложить массу в силиконовую форму для кексов, заполнять до самого верха. Отправить на 20 минут в духовку, соблюдать температуру 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7017,'Достать из духовки, чуть-чуть остудить. После остывания серединка запеканок слегка осядет. Перед подачей в центр мини-запеканок с овощами можно положить ложку сметаны или йогурта, украсить измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7018,'Хорошо вымыть груши, подсушить, разрезать на 4-6 частей. Вместо груш можно использовать любые другие фрукты или ягоды. Налить чуть-чуть воды в кастрюлю, положить груши, отправить на огонь. Варить груши до мягкого состояния. Если используются сочные ягоды, то воду можно не наливать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7018,'Измельчить груши, используя блендер, протереть через сито. Получившееся пюре поместить в кастрюлю, отправить на огонь. Насыпать сахар по вкусу, варить приблизительно 5 минут на тихом огне, чтобы растворился сахар. Замочить желатин в воде, отставить на 2 минуты. Вылить желатин в горячее пюре, размешать. Если желатин полностью не растворяется, то немного подогреть пюре, но не кипятить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7018,'Постелить в форму специальную бумагу, вылить массу. Когда желе застынет, то будет держать форму. Посыпать сахаром рабочую поверхность, положить застывшее желе, присыпать сахаром. Можно порезать ножом или выдавить формочками для печенья. Желательно перед подачей дать конфетам-желе с грушей немного подсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'Вдоль пополам разрезать пряники, кружками нарезать очищенные бананы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7019,'Порезать отварное мясо на небольшие кусочки или перекрутить через мясорубку. Измельчить и обжарить лук. Положить к мясу, посыпать перцем, солью, положить измельченную зелень, размешать. Начинка готова, можно приступать к приготовлению теста. Потереть кабачки. Если они старые, то почистить и удалить семена. Налить кефир, вбить яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7019,'Намазать сковороду оливковым маслом, прогреть, налить тесто, распределить по сковороде. Сразу на край блина положить начинку. При помощи лопатки поддеть вторую сторону блина, накрыть ею начинку. Прижать, чтобы скрепились края, обжаривать чебуреки из кабачков с куриной грудкой до румяного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7020,'Почистить картофель и быстро мелко потереть, чтобы он не потемнел. Потереть или измельчить блендером лук. Положить к картофелю. Сок от картофеля слить. Тесто посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7020,'Нагреть растительное масло на сковороде, осторожно выкладывать по ложке теста из картофеля. Жарить картофельные драники с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7021,'Отварить куриную грудку. Нагреть духовку до 200 градусов. Приготовить добавку к мясу: положить на сковороду замороженные грибы, выпарить жидкость, не накрывая крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7021,'Измельчить лук, добавить к шампиньонам, обжарить на маленьком огне. Если необходимо, долить оливковое масло. Приготовить тесто: разбить яйца в посуду, посыпать перцем, солью, добавить разрыхлитель, муку. Налить молоко, взбивать до однородности. Получится жидкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7021,'Собрать все ингредиенты: добавить в тесто отваренное мясо, порезанное на кусочки, грибы с луком, посыпать сухой зеленью и приправами. Перемешать, выложить в форму, отправить пирог с куриным филе и шампиньонами на 35-40 минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7022,'Соединить соевый соус и кетчуп. Порезать рыбное филе на порции. Каждый кусочек обмакивать в томатно-соевый соус и складывать в отдельную емкость. Посыпать чесночным порошком или измельченным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7022,'Отправить в холодильник на несколько часов, чтобы замариновалась. Обвалять рыбу в муке с солью, обжаривать на горячей сковороде. Подавать рыбное филе с картофельным пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7023,'Залить кипятком мак и изюм, отставить на 60 минут. Обсушить. Растереть яйцо, сахар и сметану, насыпать муку с содой. Взбить. Разделить тесто на 3 равные части. В каждую часть добавить свой наполнитель, приготовить 3 коржа. Выпекать 30 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7023,'Сделать крем: смешать желтки, сахар и молоко. Варить 7 минут, пока не загустеет. Остудить. Взбить масло, положить в крем. Отправить массу в холодильник. Намазать коржи остывшим кремом. Популярный торт можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7024,'Сделать тесто: взбить белки, медленно насыпать щепотку соли и 2 ложки сахара. Взбить желтки с ванилином и сахаром, который остался. Продолжая взбивать, налить масло. Осторожно соединить смеси. Просеять муку и разрыхлитель. Аккуратно размешать, чтобы сохранился объем. Отдельно соединить кофе, какао и воду, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7024,'Постелить пергамент на противень (36 на 28 сантиметров), чуть-чуть намазать растительным маслом. Осторожно выложить 2/3 теста. Распределить по противню. В оставшееся тесто добавить смесь кофе с какао, перемешать. Выложить сверху светлого теста в виде клякс. Нарисовать узоры зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7024,'Выпекать 15-20 минут, соблюдать температуру 180 градусов. Готовый пласт накрыть полотенцем, перевернуть, снять пергамент. Аккуратно свернуть горячий пласт в виде рулета вместе с полотенцем. Дать остыть. Приготовить крем: взбить сметану, сахарную пудру, загуститель для сливок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7024,'Растопить шоколад на водяной бане. Размять банан до состояния пюре, смешать с коньяком и шоколадом, перемешать. Соединить бананово-шоколадную смесь и сметанный крем. Когда рулет остынет, развернуть, намазать кремом. Свернуть рулет. Подровнять краешки. Подавать мраморный бисквитный рулет холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7025,'Просеять муку, сделать горку с углублением. Влить в углубление яйцо, ложку воды, насыпать соль. Собрать с краев муку к центру, чтобы не вытекли яйцо с водой. Замесить тесто, постепенно добавляя остальную воду, пока оно не будет однородным. Накрыть полотенцем, отставить на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'С сахарной пудрой смешать сметану, не слишком мелко покрошить грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7025,'Сделать начинку: почистить лук, измельчить, чуть-чуть обжарить. Соединить свиной и говяжий фарш, положить лук, прессованный чеснок. Посыпать перцем, солью, налить чуть-чуть кипятка, перемешать до однородности. Раскатать тесто, вырезать круги по 7-8 в диаметре. Края раскатывать тоньше, чем середину. Защипнуть тесто, слегка оттягивая края и собирая складочками. В середине оставить отверстие.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7025,'В позницу налить воду, закипятить, положить лавровый лист. Обмакивать дно каждой позы в растительное масло и выкладывать на решетку позницы. Накрыть крышкой, готовить 20 минут на пару. Выложить сочные манты с мясным фаршем на блюдо, подавать с соевым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7026,'Взбить масло, сахар, вбить яйцо, насыпать муку. Заместить мягкое тесто. Отправить на полчаса в холодильник. Нагреть духовку. Поделить тесто на 4 части, тоненько раскатать пласты в форме круга или квадрата (форма не имеет значения). Постелить на противень специальную бумагу, выпекать каждый корж в духовке по несколько минут. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7026,'Обрезать краешки, чтобы коржи получились ровными. Обрезанные части сохранять для посыпки. Намазать торт джемом или вареньем, завернуть в фольгу, придавить чем-нибудь тяжелым, отставить минимум на 2 часа. Когда торт с джемом пропитается, то станет мягче. Намазать сверху и по бокам кремом, посыпать измельченными обрезками коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7027,'Порезать рыбу стейками. На противень постелить фольгу, выложить лук, под каждый стейк положить по ломтику лимона. Стейки посыпать перцем, солью, полить соком лимона, положить по кусочку томата, лавровый лист. Накрыть фольгой, готовить рыбу в фольге 30 минут, соблюдать температуру 180-200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7028,'Взбить яйца, сахар, положить сметану, добавить соду, ванильный сахар. Насыпать просеянную муку. Отставить тесто. Вымыть яблоки, вырезать тоненьким ножом сердцевину. Если у яблок тоненькая кожура, то срезать ее не нужно. Быстро порезать яблоки на кусочки, чтобы они не успели потемнеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7028,'Выложить кусочки яблок в форму. Если форма не силиконовая, то намазать ее маслом и посыпать сухарями. Если форма силиконовая, то ее смазывать не нужно, но в ней нельзя разрезать пирог ножом. Посыпать яблоки корицей. Залить яблоки тестом, отправить в духовку. Готовить 45 минут, соблюдать температуру 180 градусов. Остудить. Посыпать быструю шарлотку сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7029,'Вымыть мясо, порезать на средние кусочки. Посыпать перцем, солью, перемешать. Подготовить банки, крышки. На дно банок положить душистый перец, лавровый лист, положить мясо, но не плотно, так как будет выделяться сок. Снизу в духовке поставить противень с водой. Прикрыть банки железными крышками, отправить в холодную духовку. Нагреть ее до 250 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7029,'Когда мясо закипит, сделать температуру 150 градусов, тушить 3 часа. Пока готовится мясо, вытопить жир. Порезать сало на кусочки, положить на сковороду и на медленном огне вытапливать жир. Вылить его в готовое мясо. Вынуть банки из духовки, закатать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7029,'Перевернуть, проверить на герметичность, перевернуть. Когда сок застынет, то должен оказаться внизу, а сверху шапочка из жира. Хранить тушенку из свинины можно в течение года при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7030,'Измельчить зеленый лук. Сардельку порезать на маленькие кусочки. Взбить яйца, добавить сметану, перемешать. Насыпать муку, соль. Добавить порезанную сардельку, зеленый лук, перемешать. Обжарить на горячей сковороде с двух сторон, как блинчики. Готовую быструю лепешку посыпать тертым сыром, сложить пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7031,'Нарезать очищенные грибы и отварить четверть часа, переложить в дуршлаг, дать стечь воде. Ножки порезать на 2 части, переложить в миску, добавить полукольца лука и майонез, хорошо перемешать, дать постоять полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7031,'Дно формы выложить кружочки картофеля, подсолить, залить половиной стакана воды, уложить на него грибы, лук и сверху – ножки. Поместить форму в прогретую до 200 градусов духовку, достать куриные ножки с картофелем и грибами через полчаса, присыпать щедро тертым сыром, запекать еще четверть часа, подать горячими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7032,'Натереть крупно сырую морковь и сыр, колбасу порезать соломкой, смешать все с кукурузой, заправить майонезом, перемешанным с мелко натертым чесноком, аккуратно перемешать, можно не солить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7033,'Вылить сгущенку в миску, вбить яйца, взбить венчиком. Соду погасить соком из половинки лимона, вылить в миску. Постепенно, постоянно перемешивая, всыпать чуть подсоленную муку. Должно получиться жидкое тесто без комочков, вылить его на противень, выстланный промасленным пергаментом, поместить в прогретую до 150 градусов духовку на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7033,'Достать подрумяненое тесто для рулета, смазать творожной массой с курагой, можно пропитать до этого его коньяком или ликером. Свернуть осторожно промазанный пласт в трубочку, порезать рулет на сгущенном молоке на кусочки, разложить на блюде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7034,'Включить для прогрева до 180 градусов духовку, готовое тесто раскатать до 2 мм, разрезать на 4 квадрата. Выстлать противень бумагой для выпечки, положить тесто, выпекать каждый корж минут 7-10, можно потом разрезать каждый вдоль еще на 2 части для лучшей пропитки кремом. Охлажденные сливки взбить до густоты , постепенно влить в крем сгущенку (взбивать не переставать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7034,'Уложить корж на плоское блюдо, смазать кремом, присыпать черникой, разровнять ее, прикрыть следующим коржом, смазать его кремом и присыпать малиной, продолжить укладку с оставшимися коржами. Смазать верх и бока слоеного торта с черникой и малиной кремом, присыпать измельченными обрезками от коржей, убрать торт на 5 часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7035,'Взбить яйца до состояния пышной пены, всыпать сахар, взбить еще раз, добавить творог, тщательно вымешать. Постепенно, не прекращая взбивать, всыпать небольшими порциями муку с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7035,'Застелить форму пергаментом, поместить в нее тесто, разложить дольки слив, выпекать творожный пирог со сливами в уже прогретой до 170 градусов духовке примерно минут 30-40 до появления золотистого цвета на поверхности, дать остыть, достать из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7036,'Перемешать тонко нарезанное филе, ломтики чеснока, подсолить, поперчить, добавить майонез, перемешать, оставить на треть часа. Натереть крупно сыр, лук порезать на тоненькие кольца, картофель – на кружочки, сметану перемешать со специями, солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7036,'Уложить в смазанную форму лук, на него – картофель, смазать сметанным соусом, прикрыть сверху кусочками курицы, присыпать слоем сыра, все повторить до окончания ингредиентов. Верх ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7037,'Для соуса прогреть смесь из сахара, кукурузного сиропа и воды, дать ей закипеть, варить на сильном огне до однородности. Убрать соус с плиты, добавить, постоянно перемешивая, сливки, подсолить, добавить масло, перемешать, дать полностью остыть. В кастрюльке смешать какао и стакан сливок, нагреть на среднем огне, дать закипеть, прикрутить огонь до слабого, готовить примерно полминуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7037,'Убрать смесь с плиты, положить кусочки шоколада, перемешать до полного его растворения, добавить полстакана сливок, перемешать, перелить в миску. Перемешать в сотейнике полстакана сливок, сахар, молоко и корицу, дать смеси, помешивая, закипеть на сильном огне, убрать с плиты, дать остыть под крышкой час. Взбить желтки, вынуть из сливочной смеси палочки корицы, поставить кастрюлю на плиту, прогреть на среднем нагреве почти до кипения, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7037,'В полученную смесь очень осторожно и медленно влить взбитые яйца, перемешать, поставить на плиту, варить при помешивании до сгущения. Процедить сквозь сито к шоколадной смеси, размешать, быстро охладить на ледяной бане, убрать в холодильник на пару часов, а лучше на ночь. Перелить смесь в миску, заморозить шоколадное мороженое с корицей в машинке для мороженого.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7038,'Обжарить на сильном огне полукольца лука и тертую крупно морковь почти до готовности, кальмаров порезать кольцами, положить к овощам, приправить специями, подсолить, влить сметану, перемешать, тушить минуты 4. Всыпать к кальмарам с овощами в сметане мелко порубленные укроп, петрушку и чеснок, размешать, дать закипеть, убрать с плиты. Подавать блюдо с любым гарниром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7039,'Взбить до пышной массы мягкое масло с сахаром (добавлять порциями) на большой скорости миксера, добавить ваниль, перемешать. Вбить по одному яйца, после каждого перемешивать, перейти на среднюю скорость миксера, добавить постепенно творог и манку. Форму или чашу мультиварки промазать маслом, заполнить творожной массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Подавать в горячем виде, посыпать измельченным укропом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7039,'Готовить запеканку с творогом в мультиварке на режиме «Выпечка», в духовке, прогретой до 180 градусов, около 45 минут. У мультиварки крышку не открывать 10 минут, переложить запеканку на блюдо, остудить, уложить на верх колечки киви, залить «желе для торта» (готовить по инструкции на пакетике), дать застыть, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7040,'Венчиком взбить яйца с молоком и солью до появления легкой пенки, всыпать муку с содой, перемешать, добавить зиру, тимьян, кориандр, куркуму, смесь перцев, размешать. Холодное вареное филе порезать на кусочки, сыр крупно натереть, перемешать все с тестом, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7040,'Заполнить смесью смазанную форму, готовить запеканку из куриной грудки около 35 минут в прогретой заранее до 200 градусов духовке. Осторожно вынуть запеканку из формы, подать к столу, блюдо вкусное и в холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7041,'Кабачки, крупно натертые, сложить в миску, чуть присолить, дать постоять около 20 минут, отжать от сока. Порубить мелко зелень, высыпать к кабачкам, вбить яйца, посолить, поперчить, хорошо перемешать. Всыпать в смесь муку с разрыхлителем и раскрошенный сыр, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7041,'Жарить оладьи из кабачков на среднем огне в хорошо разогретом масле, выкладывать столовой ложкой, готовить около 3 минут с каждой стороны до золотистости. Готовые оладьи выкладывать на многослойное бумажное полотенце, а потом на блюдо. Для соуса к йогурту добавить раздавленный чеснок, чуть присолить, перемешать, подать в соуснике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7042,'Для приготовления начинки сложить в чашу блендера корейскую морковку, йогурт, вареные яйца, чеснок, добавить майонез, взбить в однородную массу. Нанести ее на пластинки сыра, свернуть в рулетики, обвалять сырные трубочки в измельченном укропе, предварительно можно слегка их смазать горчицей, или майонезом, или йогуртом для лучшего приставания зелени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7043,'Включить и прогреть в режиме конвекции духовку до 170 градусов. Сухие ингредиенты (кроме сахара) просеять, перемешать с маслом воду в небольшом ковшике и довести до кипения. Взбить белки до появления устойчивых пиков, всыпать половину нормы сахара, взбить в крепкую пену. Желтки перемешать с оставшимся сахаром и тоже взбить в светлую пышную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7043,'Перемешать с осторожностью желтки с белками, всыпать смесь сухих ингредиентов, еще раз перемешать, влить закипевшее с водой масло, вымешать до однородного состояния. Залить тесто в форму, застеленную промасленной бумагой, выпекать заварной бисквит около 20 минут, пробуя деревянной зубочисткой. Бисквит остудить, поместить в пакет, дать постоять около 8 часов, разрезать вдоль на коржи, пропитать любым кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7044,'Порезать хлеб на треугольные ломтики, обжарить в масле с двух сторон, натереть зубчиком чеснока, смазать сметаной. В разные емкости натереть белок и желток, на половину кусочка хлеба выложить желток, другую прикрыть белком, сверху уложить шпроты, оформить зеленью, можно добавить по тонкому колечку огурца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7045,'Порезать (старый предварительно почистить) кабачок на кружки, слегка их присолить. Хорошо разогреть масло в сковороде, обжарить кабачки, примерно по минуте с каждой стороны, переложить их в форму. Присыпать частью натертого сыра, положить еще слой кабачков, а на них мелко порезанные помидоры без шкурки (половину), прикрыть слоем из кабачков, все повторить, на последнем слое выложить колечки лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7045,'Для заливки разболтать яйцо с солью, добавить сливки, взбить, используя венчик, до получения однородной массы, вылить в форму на кабачки, присыпать сыром, поместить запеканку из кабачков с помидорами на треть часа в нагретую до 180 градусов духовку до подрумянивания сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7046,'Порезать баклажаны вдоль на тонкие полосы овощечисткой, присолить, дать постоять примерно треть часа, сок слить, выложить внахлест на дно смазанной маслом формы, на них – отбитую курицу, присолить, присыпать специями с перцем и порубленным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7046,'Далее выложить кружки помидора, промазать майонезом с горчицей, присыпать сырной стружкой, поместить в духовку. Готовить куриное филе под баклажанами и сыром в духовке примерно полчаса при температуре 180 градусов, подавать блюдо горячим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'Емкость для торта застелить пищевой пленкой так, чтобы свисали края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Разморозить и вымыть скумбрию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7047,'Хорошо перемешать мед с имбирем, переложить в сотейник, поставить на малый огонь, варить леденцы от кашля полтора часа, постоянно помешивая, до состояния «застывающей капли». Разлить массу по смазанным маслом силиконовым формочкам, дать застыть. Пока масса жидкая можно добавить еще отвар из корня солодки, для исчезновения кашля есть по 3 шт. в день.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7048,'Просеять 300 гр муки в миску, всыпать разрыхлитель, ванильный и обычный сахар, перемешать, натереть на терке замороженное масло или маргарин, перемешать с мукой до образования маслянистой крошки. Вбить в смесь яйца, вымесить тесто, оно не должно прилипать к рукам. Смазать форму маслом, заполнить тестом, разровнять его по дну, сформовать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7048,'Чернику (мороженую не оттаивать) перемешать с крахмалом для впитывания лишнего сока, положить на тесто. Для приготовления заливки перемешать хорошо сметану, ванильный и обычный сахар, вылить на ягоды. Поместить форму с ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7049,'Взбить подсоленные яйца с сахаром, влить чуть подогретое молоко, всыпать порциями муку в смеси с разрыхлителем, добавить масло, перемешать до образования однородного теста, разогреть сковороду, испечь блинчики (7-8 шт.), дать им остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7049,'Нарезать лосось на тонкие полосы, смазать блин сыром, уложить на него рыбу, свернуть в рулет, убрать их в холодильник на треть часа. Затем, чтобы получились рулетики из блинов с лососем, нарезать свернутые блины на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7050,'Натереть крупно сыр, моцареллу порезать на кусочки, перемешать с измельченной зеленью, добавить смесь сметаны с майонезом, посолить, поперчить, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7050,'Лаваш нарезать на прямоугольники (20х15 см), положить на широкий край пару ст.л. сырной смеси, загнуть края, завернуть трубочкой, дать постоять минут 5 для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7050,'Разогреть в сковороде масло, обжарить лаваш с сыром до аппетитной корочки на небольшом огне с 2-х сторон. Подавать блюдо горячим с любимым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7051,'Перемешать сметану с порубленной петрушкой и кусочками бекона, тестом выложить форму, заполнить этой массой. Разбить 4 яйца, чтобы желток оставался целым, вылить аккуратно на смесь, присыпать специями. Поставить форму в духовку, заранее прогретую до 200 градусов, завтрак «Утренний» будет готов примерно через 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7052,'Натереть крупно очищенный кабачок, добавить яйцо, перемешать, всыпать сырную стружку, добавить раздавленный прессом чеснок, подсолить, поперчить, перемешать. Добавить к смеси муку, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7052,'Разогреть в сковороде масло, обжарить оладьи из кабачка с сыром с двух сторон до золотистой корочки. Подавать со сметаной, смешанной с мелко порезанной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7053,'Залить кусочки куриного филе молоком, дать постоять час-полтора. Наложить на дно банки несколько слоев фольги, отогнуть края, снять формочку с банки, можно готовить блюдо и в обычных формочках. Установить формы на противень, смазать маслом, уложить на дно кружочки картофеля, поперчить, присолить, прикрыть полукольцами лука, далее положить филе, опять чуть присолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7053,'Взболтать яйца и майонез, вылить в каждую формочку по паре ст.л., если не хватит, то можно сделать еще одну порцию, положить по кружочку помидора, немного чеснока, присыпать сыром. Отправить куриное филе «Сюрприз» на треть часа в духовку с температурой 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7054,'Протереть сквозь сито творог, вбить яйца, всыпать муку, перемешать до однородности, добавить банановое пюре, перемешать еще раз, заполнить массой форму. Выпекать банановый чизкейк до появления румяной корочки при 180 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7055,'Порезать ветчину на кусочки, грибы – пластинками, маслины – кружочками. В салатник положить мясо, порубленные яйца, кукурузу и все остальную нарезку, перемешать, добавить майонез, чуть подсолить, окончательно перемешать. Подать салат можно порционно, тогда на дно широких стаканов надо положить по салатному листу, а потом сам салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7056,'Крупно нарубить обжаренные грецкие орехи, натереть сыр, отварное и охлажденное филе и ананас порезать на кусочки, перемешать мясо с кукурузой. Все смешать, всыпать орехи, добавить майонез, перемешать, переложить салат с куриным филе в салатницу, присыпать орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7057,'Сухой творог положить в кастрюлю, влить молоко, нагреть на малом огне, варить, помешивая четверть часа, после отделения сыворотки и закипания проварить еще 10 минут, откинуть на дуршлаг, дать хорошо стечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7057,'Переложить творог в кастрюлю, вбить яйцо, добавить масло, соду с солью, проварить на медленном огне около 10 минут, после образования гладкой и тянучей массы варить еще 5 минут. Смазать маслом форму, быстро заполнить горячей массой, дать остыть, убрать творожный сыр в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7058,'В небольшую кастрюльку с толстым дном положить сахар, масло, соль, залить водой (370 мл), дать закипеть, убрать с плиты, вмешать муку, поставить опять на плиту, нагревать помешивая до получения однородной массы, которая легко отстает от стенок, снять с плиты. Добавить по одному яйца, тщательно вымешивая после каждого тесто, переложить его в мешок (шприц), отсадить на промасленный пергамент маленькие профитроли (около 50 шт.), можно для этого пользоваться и чайной ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7058,'Поместить противень в уже прогретую до 220 градусов духовку, выпекать до золотистости примерно 25 минут, духовку не открывать. Приготовить крем из взбитых с сахаром до светлой массы желтков, добавить муку, взбить еще раз до однородности. Закипятить молоко (отлить 120 мл), очень маленькими порциями влить, постоянно взбивая к желткам. Полученную смесь прогреть, помешивая на сильном огне до сгущения. Если крем получиться через чур густым, то влить оставленное молоко и перемешать, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7058,'Добавить маленькими порциями (по 1 ст.л.) масло, каждый раз тщательно вымешивать, добавить растопленный удобным способом шоколад, окончательно тщательно перемешать крем, прикрыть пленкой, остудить. Заполнить кремом кондитерский шприц, начинить профитроли. Для приготовления карамели довести до кипения на сильном огне смесь воды с сахаром, варить, убавив нагрев до «твердого шарика» (капнуть в воду и получить твердую каплю).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7058,'Для сборки крокембуша свернуть из ватмана конус, заварные пирожные обмакивать в карамель и укладывать на блюдо горкой, украсить орехами, цветной присыпкой или орехами. Для изысканности можно обернуть крокенбуш паутинкой из карамели. Для этого сложить «спинками» 2 вилки, обмакнуть в карамель и с ускорением обвести несколько раз вокруг выстроенного конуса',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7059,'Прогреть в сковороде масло с паприкой и куркумой, положить картофель, присолить, поперчить, жарить, переворачивая до образования аппетитной корочки. Смешать куркуму, соль, паприку, перец и чуть–чуть масла до однородной массы, обвалять курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7059,'Обжарить крупно порезанный лук, добавить курицу, обжарит со всех сторон, в конце положить веточки розмарина, готовить еще пару минут, слить масло, вынуть зелень, добавить готовую картошку, еще розмарин, лук, залить стаканом воды, тушить курицу с картофелем и луком около получаса на малом огне под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7060,'Натереть сыр, перемешать в глубокой миске с творогом, вбить яйца, добавить подсоленную сметану с перцем, всыпать порубленный укроп, перемешать. Разогреть сковороду с маслом, обжарить ленивые сырные лепешки с двух сторон, переложить на несколько слоев салфеток, порезать на кусочки',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7061,'Порубить мелко яйца, порезать на кубики колбасу, перец, огурцы, перемешать все с кукурузой, заправить салат «Разноцветный',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7062,'Натереть тыкву, отжать сок, смешать с тертым яблоком. Для теста смешать яйца, масло, всыпать сахар и др. ингредиенты, перемешать, добавить цедру и сок лимона, перемешать все с тыквой. Заполнить тыквенным тестом форму, смазанную маслом, выпекать нереально вкусный пирог из тыквы до готовности при 180-200 градусах. Готовый пирог присыпать через ситечко сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7063,'Залить дрожжи теплой водой, подсолить, добавить сахар и масло, всыпать муку, перемешать, влить кипяток (стакан), вымесить тесто. Сформовать пирожки с любой начинкой, например из картофельного пюре с печенью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7064,'Перемешать мягкое масло со сметаной, всыпать просеянную муку и соль, замесить тесто, чтобы не прилипало к рукам, колобок раскатать в пласт, порезать на квадраты 5х5, по центру положить джем, свернуть в конвертик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Тесто замесить из мелко порубленного сливочного масла и муки, соли, воды, смешанной с уксусом, поделить на 12 кусков и поместить их на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7064,'Переложить печенье с джемом на противень, выстланный промасленным пергаментом, выпекать при 200 градусах в заранее прогретой духовке около четверти часа, готовую выпечку присыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7065,'Взбить до состояния пены миксером сахар с четырьмя яйцами, а в дугой емкости – молоко с маслом, сахаром и какао. Смесь разделить пополам, одну часть перемешать с яичной смесью и взбить, добавить смесь муки с ванилином и разрыхлителем, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7065,'Смазать маслом чашу мультиварки, вылить тесто, выпекать шоколадное Кухэ на режиме «Выпечка» примерно час. Готовый бисквит полить шоколадным сиропом, поставить пропитаться в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7066,'Включить для прогрева до 180 градусов духовку. Измельчить филе в блендере или просто мелко порубить, добавить майонез, подсолить , поперчить, перемешать до однородности, еще раз добавить мягкое масло, перемешать. Батон порезать на толстые ломти (по 5-6 см), бока натереть чесноком, выбрать из каждого чуть-чуть мякоти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7066,'Кусочки обмакнуть в молоко, углубление заполнить начинкой. Смазать противень маслом, выложить горячие бутерброды с куриным филе, запекать полчаса, минут за 5 до готовности присыпать стружкой сыра, дать ему расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7067,'Натереть на терке замороженный плавленный сыр, крупно натереть вместе с палочками, рыбу мелко порезать. Переложить все в миску, добавить чеснок, раздавленный прессом, майонез, всыпать порубленный укроп, перемешать. Слегка смочить руки, скатать в небольшие шарики, красиво разложить на плоском блюде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7068,'Нарезать фрукты на тонкие ломтики, засыпать сахаром, дать потомиться с сахаром часов 5, достать, плотно скрутить, скрепить зубочисткой, варить в сиропе около получаса, вынуть, достать зубочистки. Разложить варенье в форме роз по стерилизованным банкам, залить горячим сиропом, можно с корицей и ванилином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7069,'Смешать сметану и манку, оставить на час, перемешать миксером со взбитыми с сахаром яйцами, ванилином и содой. Добавить в смесь цукаты, изюм, орехи, вылить в промазанную маслом форму, выпекать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7070,'Разрезать лаваш на кусочки, смазать кетчупом, потом фаршем с луком, полить взбитым подсоленным яйцом, свернуть трубочкой. Разогреть хорошо масло, обжарить трубочки из лаваша с каждой стороны до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7071,'Срезать у одного апельсина корки, залить водой, прокипятить 10 минут, процедить, дать набухнуть желатину, залив его водой. В отвар всыпать сахар, половину желатина, довести до кипения (не кипятить!). У второго апельсина снять цедру, отжать из 2 апельсинов сок, перелить к желатину с соком, добавить цедру. Закипятить молоко с обычным и ванильным сахаром, положить оставшуюся порцию желатина, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7071,'В глубокую форму налить апельсиновую заготовку для десерта, поставить в холодильник, когда застынет аккуратно (по ложке) влить молочную смесь, отправить в холодильник, процедуру повторить пока не закончится жидкость, оставить десерт «Апельсиновое чудо» для окончательного застывания на 6 часов в холодильнике. Осторожно перевернуть на плоское блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7072,'Испечь блинчики по любому рецепту, огурец почистить, порезать на полоски. На блины намазать слой сыра, положить рыбу и кусочки огурца, свернуть блины с семгой в трубочку. Перед подачей на стол разрезать каждый на кусочки',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7073,'Перемешать в глубокой миске дрожжи с сахаром и мукой, влить стакан воды, вымесить тесто, оставить в теплом месте на полчаса. Орехи измельчить, поджарить, перемешать с медом, порубленным розмарином, поперчить, посолить, чуть подогреть. Теплое молоко перемешать с маслом, влить в тесто, перемешать, всыпать ореховую смесь, вымесить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7073,'Сформовать батон хлеба с грецкими орехами и розмарином, уложить на противень, выстланный пергаментом, дать постоять в тепле, прикрыв тканью, около трети часа, выпекать в прогретой до 220 градусов духовке примерно 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7074,'Из подготовленных ингредиентов вымесить эластичное тесто, поделить его примерно на 20 шариков, прикрыть их тканью, дать постоять 20 минут. Из каждого шарика (по очереди) раскатать лепешку очень тонкую, затем растянуть аккуратно руками до прозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Обвалять плоды попеременно в пшеничной муке, взбитом яйце и в сухарях для панировки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7074,'Хорошо прогреть сухую сковороду, обжарить с двух сторон (по паре секунд на каждой) раскатанную лепешку. Сложить лепешки лаваша в стопку, сбрызгивая для эластичности водой, прикрыть пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7075,'Включить для прогрева до 200 градусов духовку, масло порезать на кусочки, шоколад поломать, все вместе растопить на водяной бане, хорошо перемешивая до получения однородной массы, дать чуть остыть. Взбить в миксере желтки с парой яиц и сахаром в устойчивую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7075,'Объединить обе смеси, всыпать подсоленную муку, перемешать осторожно до однородности. Заполнить тестом формочки, промазанные маслом, выпекать шоколадные влажные кексы с жидкой начинкой около 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7076,'Подготовить рыбу, помидор порезать на крупные полукольца, смазать маслом листы лаваша, уложить на середину тушку рыбы. Рыбу поперчить и посолить, приправить специями, в брюшко уложить помидоры и кусочки масла с веточками укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7076,'Свернуть лаваш конвертом, перевернуть, обернуть тщательно вторым листом лаваша, чтобы не было зазоров, для надежности можно использовать еще один лист. Прогреть заранее до 180 градусов духовку, уложить конверт, запеченная рыба в лаваше будет готова примерно через час. При подаче нарезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7077,'Отварить филе до готовности, нашинковать лук кубиками, морковь мелко натереть, картофель порезать кубиками. Вынуть курицу, засыпать в кипяток картофель, добавить, после возобновления кипения, лук и морковь. Дать еще раз закипеть, засыпать промытый рис, варить почти до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7077,'Нарезать на кусочки филе, вернуть в кастрюлю, добавить плавленный сырок, хорошо перемешать. Всыпать в сырный суп с куриным филе мелко нарезанную зелень, дать закипеть, прикрыть крышкой, дать постоять минут 15 и разлить по тарелкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7078,'Сварить курицу, охладить в бульоне, порезать мелкими кубиками, огурцы – соломкой. Кольцо смазать слегка майонезом, положить на блюдо, заполнить половиной мяса, придавить ложкой, смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7078,'Выложить слой из половины опят, смазать майонезом, положить огурцы тоже половину и смазать майонезом, убрать кольцо, уложить поверх аккуратно слой из половины морковки. Оформить верх салата с опятами, огурцом и корейской морковкой натертым сыром, из оставшихся продуктов собрать еще один порционный салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7079,'Натереть цедру с половины апельсина, выдавить сок, тушку рыбы надрезать с обеих сторон. Хорошо перемешать йогурт с соком и цедрой, добавить измельченный чеснок, перец, посолить, тщательно перемешать, смазать обильно рыбу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7079,'Сложить фольгу вдвое, уложить рыбу, подогнуть края, сделать конверт. Запекать скумбрию в фольге около получаса при температуре 200 градусов, подавать с салатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7080,'Ломти тостового хлеба разрезать по диагонали, намазать на треугольники сыр. На пластинку лосося положить немного сыра с фаршированной оливкой и кусочком помидора (перца), свернуть и уложить на хлеб. Украсить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7081,'Порезать огурцы на полоски по 2 мм толщиной, хлеб – на квадраты и смазать их маслом. Насадить на шпажки для канапе полоски огурца гармошкой, чтобы получилось подобие елочки, воткнуть в хлеб, разложить канапе «Елочка» на плоском блюде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7082,'Нарезать батон ломтями примерно по 1,5 см толщиной, намазать их маслом и разрезать на 2 равные части. Порезать на кружочки огурцы с яйцами, разложить на хлеб. Каждую рыбку насадить на зубочистку, воткнуть в хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7083,'Выемкой для приготовления печенья (в форме звездочки) нарезать кусочки из хлеба для тостов, обжарить их на хорошо разогретой сковороде до появления золотистого цвета с обеих сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7083,'Дать немного остыть, смазать сыром (маслом), положить кусочек лосося, твердого сыра и лимон, прикрыть другой «звездочкой». Для украшения новогодних канапе положить на верх по кусочку лимона и по веточке петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7084,'Из перечисленных ингредиентов испечь блины, остудить, положить блин на большую тарелку, промазать тонким слоем творожного сыра, на другой блин выложить слой из рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7084,'Все повторить с остальными блинами. Проткнуть блины шпажками и вырезать канапе из блинов любым удобным способом, оформить маслинами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11231,'Время выпекания – от 20 до 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7085,'Багет нарезать ломтями, дать подсохнуть в духовке, дыню и голубой сыр порезать кубиками. Заполнить кулинарный шприц мягким маслом с любой фигурной насадкой, высадить его небольшими кусочками на батон, вокруг выложить дыню и сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7086,'Хлеб нарезать с помощью формочек кружочками, огурец нарезать вдоль на кружочки. Смазать мягким сыром хлеб, положить по кружочку огурца и кусочку лосося, поперчить. Украсить канапе веточками зелени, побрызгать соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7087,'Перемешать взбитые яйца со сгущенкой, всыпать порциями смесь из муки и разрыхлителя, взбить до однородности, должно получиться тесто по густоте как на оладьи. Нарисовать на листе пергамента круг, постелить его на противень, по центру круга вылить пару-тройку ст. л. теста, распределить равномерно по всей площади. Выпекать корж 5 минут при 180 градусах, готовый корж сразу снять с пергамента и подравнять до необходимого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7087,'Приготовить из смеси сахарной пудры и мягкого сыра крем. Перемешать хорошо взбитые сливки со сливочным сыром, всыпать стружку кокоса и еще раз тщательно перемешать. Сложить остывшие коржи в стопку, промазывая каждый кремом, верх торта «Кокосовый рай» смазать и присыпать стружкой кокоса, украсить можно ягодами или шоколадом, перед употреблением дать постоять час-полтора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7088,'Залить горячей водой желатин, остудить, развести по инструкции желе дать остыть, поломать печенье, шоколад измельчить ножом. Взбить с сахаром сметану с добавлением ванильного сахара, влить желатиновый раствор, взбить все вместе, перемешать с изюмом и крекерами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7088,'Заполнить этой массой на 1/3 разъемную форму, присыпать шоколадом, залить следующей порцией, посыпать шоколадом, вылить остаток смеси. Убрать тортик без выпечки в холодильник, порезать виноградинки, удалить косточки, выложить на тортик, залить желе, вернуть в холодильник, дать застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7089,'Смешать яйца, кефир, сахар, масло, всыпать 4 ст. л. муки, влить соду, погашенную уксусом, вымешать до однородного состояния. Отделить 1/3 теста, смешать с парой ложек какао и 6 ст л. муки, перемешать до получения мягкого теста. К 2/3 теста добавить 14 ст. л. муки, вымесить до однородности, разделить пополам. Раскатать один в пласт, на него уложить коричневый, прикрыть вторым белым пластом, свернуть в трубочку и разрезать на 2 части, а потом – на отдельные пряники.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7089,'Форму промазать маслом, каждый кусочек скатать в шарик, заполнить ими форму, выпекать мягкие пряники в белой глазури около получаса при температуре 175 градусов. Приготовить из взбитого белка и сахарной пудры глазурь, сложить пряники в миску, залить глазурью, перемешать, вынуть, дать застыть, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7090,'Приготовить миксером творожную пасту с сахарной пудрой, маслом и кусочками чернослива. Выстелить форму пленкой, разложить печенье (предварительно обмакнуть в кофе), смазать пастой, прикрыть следующим слоем печенья, смазать пастой и т. д.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7090,'Прикрыть форму блюдом, аккуратно перевернуть, удалить пленку, бока и верх тортика с черносливом смазать творожной пастой, присыпать крошкой, измельченного печенья, дать пару часов постоять, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7091,'Взбить до однородности яйца и сметану 20% с сахаром, всыпать порциями (по ст. л.) муку, добавить соду, взбить до получения жидкого теста, всыпать какао, перемешать. Форму промазать маслом, выстлать пергаментом, смазать маслом, заполнить тестом, выпекать корж примерно 40 минут при 200 градусах, готовность проверять зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7091,'Бисквит охладить, разделить вдоль на 2 части (одна очень тонкая, около 1 см – основа), большую порезать на кубики. Для крема взбить в густую массу сметану 25% и пудру, отложить часть для смазки верха. В оставшийся крем положить кубики ананаса, персиков, порубленные на кусочки орехи, кубики бисквита, хорошо, но аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7091,'Основу пропитать сиропом от ананасов, выложить на него фруктовую смесь с кусочками бисквита, разровнять с небольшим нажимом ложкой. Залить верх торта «Дон Панчо» остатками крема, убрать в холодильник. Растопить удобным способом шоколад, перемешать с маслом, полить полосами тортик, дать схватиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Затем каждый кусочек раскатать в тонкий корж, а чтобы коржи не прилипали к столу, нужно с обеих сторон посыпать их мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7092,'Нашинковать полукольцами лук, картофель, перец, морковь порезать на кубики, помидоры – на кусочки, базилик, зелень и чеснок мелко нашинковать. Обжарить отбивные с двух сторон до коричневой корочки, всыпать лук, готовить еще 5 минут до подрумянивания лука. Добавить кубики моркови, жарить 10 минут, всыпать сладкий перец, убрать мясо, перемешать и жарить овощи 5 минут при сильном нагреве.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7092,'Положить помидоры, всыпать тмин, перемешать, готовить четверть часа до их размягчения. Добавить картофель, половину базилика, зелени, посолить, перемешать, тушить 5 минут. Влить к овощам 2,5 стакана воды, дать закипеть, добавить чеснок, уложить на дно мясо, прикрыть со всех сторон овощами, дать закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7092,'Уменьшить нагрев, подсолить, тушить лагман с бараниной под крышкой полчаса, за это время отварить феттучини. В порционные чаши разложить феттучини, по бараньей отбивной, полить овощным соусом, посыпать зеленью, сразу подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7093,'Почистить чеснок, измельчить на терке или раздавить прессом, смешать с перцем, солью, карри, тщательно растереть пестиком, влить без кислинки кефир, хорошо перемешать. Добавить сметану, измельченную зелень (можно без нее), хорошо размешать, дать соусу для шаурмы постоять полчаса, хранить плотно закрытым в холодильнике, но не более 2 дней.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7094,'Смешать кетчуп, майонез, горчицу, измельченный чеснок, приправу для курицы, добавить соль, хорошо перемешать. Крылышки положить в глубокую миску, залить полученной смесью, перемешать, убрать в холодильник на 4 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7094,'Уложить крылышки в рукав, запекать 45 минут в духовке с температурой 180 градусов. За 10 минут до окончания достать пикантные крылышки, разрезать рукав, увеличить нагрев до 210 градусов, готовить до появления румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7095,'Из подсоленной воды с перцем, сахаром и лавровым листом приготовить маринад. Грудки курицы разрезать, чтобы получить две половинки, положить в лоток залить маринадом, накрыть пленкой, убрать примерно на сутки в холодильник. Достать мясо, обмыть от маринада под струей воды, хорошо обсушить с помощью салфетки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7095,'Для приготовления глазури смешать мед с соевым соусом, маслом, перцем, паприкой, чесноком, обмазать грудки со всех сторон, дать постоять 3 часа. Завернуть грудки рулетом, обвязать с усилием ниткой, поместить на ночь в холодильник. Прогреть до 160 градусов духовку, противень застлать фольгой, уложить грудки, запекать бастурму из курицы в духовке примерно час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7095,'После 40 минут запекания повысить температуру до 180 градусов, а мясо облить, выделившимся соком. Готовую бастурму достать из духовки, дать ей остыть, порезать на тонкие ломтики и хорошо охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7096,'Из готового теста в формочках испечь тарталетки, подогреть молоко, всыпать сладкий кокос, дать закипеть на среднем огне. Размешать в миске до однородности желток, яйцо, муку и сахар, медленно (тонкой струйкой) влить горячее молоко, постоянно перемешивая, полученную смесь поместить в кастрюлю, дать закипеть, проварить пару минут, помешивая. Добавить к массе кокос и экстракт ванили, хорошо вымешать. Заполнить начинкой тарталетки, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7096,'Тарталетки достать из формочек, положить на каждую ломтики банана. Из взбитых с кукурузным крахмалом (добавлять по желанию) охлажденных жирных сливок с добавлением сахара, экстракта ванили приготовить крем. Разложить его на тарталетки так, чтобы прикрыть ломтики банана полностью, убрать пирожное с бананово-кокосовой начинкой до подачи к столу в холодильник. При желании посыпать верх стружкой кокоса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7097,'Включить для прогрева до 180 градусов духовку, противень  застелить пергаментом. Хорошо перемешать какао, сахарную пудру, соль и муку. В другой посуде взбить с помощью венчика смесь из яичных белков, яйца и ванили до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7097,'Соединить обе смеси, очень хорошо перемешать, всыпать шоколадную стружку и еще раз перемешать. Полученную массу выкладывать на противень столовой ложкой с промежутками в 5 см, выпекать шоколадное печенье около 16 минут, подавать к столу остывшими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7130,'Приготовить из творога, желтка и сахара начинку. Заполнить формочки на 2/3 высоты тестом, в каждую положить сверху начинку, выпекать шоколадные маффины-ватрушки при 175 градусах около трети часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7098,'Взбить по отдельности: желтки с сахаром, а белки с добавлением щепотки соли. Смешать все со взбитыми сливками (белки добавлять последними), если есть, то добавить наполнитель (шоколад, орехи). Поставить сливочный пломбир в морозилку, вкусное лакомство будет готово через 6 часов, когда полностью замерзнет. За это время пару-тройку раз пломбир перемешать, чтобы в массе не было кристалликов льда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7098,'У кого есть электровафельница можно разложить готовый пломбир в испеченные вафли, свернутые конусом. Для приготовления смешать 4 яйца, по 100 гр сливочного масла и сахара, влить чуть молока, всыпать муку, тесто должно напоминать сметану средней густоты. Горячие вафли свернуть конусом, слегка сдавить края, чуть подержать, чтобы они схватились, готовые рожки заполнить пломбиром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7099,'Растворить в стакане воды пару чайных ложек соли, залить вымытую грудку, дать постоять ночь. Достать филе, свернуть в рулончик, туго, с усилием перевязать по всей длине ниткой. Смешать для маринада масло, натертый чеснок, жидкий мед, соль, паприку, мускатный орех, хорошо смазать мясо со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7099,'Поместить филе в форму с небольшим количеством масла, готовить куриное филе в духовке с температурой 220 градусов около 20 минут. Готовое блюдо остудить в духовке, снять нитки, порезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7100,'Вымешать мягкое масло с просеянной мукой, разрыхлителем, яйцом, сливками и сахаром, до образования достаточно крутого теста, завернуть его в пленку, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7100,'Для начинки взбить в блендере сливки с творогом и сахаром в гладкую массу. Тесто разделить на 2 половины, одну – крупно натереть в форму, равномерно распределить по дну.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7100,'Прикрыть ровным слоем творожной начинки, на нее натереть вторую часть теста. Выпекать тертый пирог с творожной начинкой в прогретой до 180 градусов духовке чуть больше получаса, порезать теплый пирог на кусочки, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7101,'Лист лаваша сложить в 2 раза, вырезать круг, который будет чуть больше формы, чтобы сделать бортики. Натереть сыр, разделить на 3 части, уложить один круг лаваша в форму, присыпать 1/3 частью сыра, прикрыть вторым кругом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7101,'Смазать смесью кетчупа с майонезом, присыпать опять 1/3 частью сыра, на него уложить кружочки копченой колбасы, на нее – помидоры, присыпать нашинкованным зеленым луком, завершить все слоем оставшейся сырной стружки. Отправить эконом пиццу на лаваше минут на 7 в духовку, достать, нарезать, присыпать пряной зеленью (по желанию), сразу подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7102,'Измельчить любым способом печенье, часть поломать на небольшие кусочки, смешать обе массы. Шоколад растопить в смеси с молоком и маслом, перемешать с печеньем, добавить орехи и изюм, тщательно перемешать, убрать в холодильник. Сладкой массой можно заполнить коробку из-под сока, тогда домашний щербет получится правильной прямоугольной формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7103,'Очистить картофель, порезать  на кусочки, бланшировать его в кипятке пару-тройку минут, подготовить скумбрию, убрать все кости, разрезать на кусочки, натереть сыр. Форму смазать маслом, положить на дно половину картофеля, поперчить, посолить, промазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7103,'Прикрыть картофель слоем рыбы, тоже поперчить ее и посолить, промазать майонезом, выложить остаток картофеля, полить майонезом, присыпать сырной стружкой. Поместить форму в прогретую до 190 градусов духовку, готовить запеканку из картофеля со скумбрией около 40 минут до румяного верха, достать, чуть остудить порезать на куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7104,'Разбавить молоко водой, всыпать соду, подсолить, вбить яйцо, добавить сахар, тщательно перемешать венчиком. Всыпать небольшими порциями муку, постоянно взбивая до исчезновения комочков, дать постоять тесту полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7104,'Разогреть сковороду, смазать маслом, пожарить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7105,'Залить желатин водой, малину прогреть в сотейнике до кипения, убрать с плиты, осторожно протереть сквозь сито, переложить пюре опять в сотейник, всыпать сахар, постоянно мешая довести массу до кипения, убрать с огня, дать немного остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7234,'Сверху положить сыр. Свернуть рулетики. Если сделано все правильно, то рулеты во время приготовления не раскроются. Чтобы подстраховаться, можно скрепить их зубочистками. Нагреть растительное масло на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7105,'Перемешать ягодную смесь с желатином до его полного растворения, хорошо охладить, взбить в пышную плотную массу миксером около 10 минут. Малиновый зефир переложить в форму, поставить на 10 часов в холодильник, порезать десерт на квадратики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7106,'Залить желатин горячей водой, перемешать до полного его растворения, дать остыть, за это время несколько раз перемешать. Всыпать сахар в сметану комнатной температуры, взбить блендером, перемешать блендером с раствором желатина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7106,'Крупно порезать бананы, разложить по формам, залить смесью сметаны с желатином, убрать сметанное желе с бананом на пару часов в холодильник, перед подачей к столу присыпать крупно натертым шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7107,'Разложить кубики картофеля и фрикадельки в горшочки, чуть присолить, выложить поверх грибы, обжаренные с луком. Перемешать подсоленную сметану с водой, залить в горшочки на 3/4 объема.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7107,'Поставить фрикадельки с картошкой и грибами в холодную духовку, довести до температуры 180-200 градусов, готовить 40 минут, присыпать тертым сыром, готовить еще четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7108,'В глубокую миску с молоком вбить яйца, подсолить, смешать (не взбивать) венчиком. Смазать маслом форму (чем она будет меньше, тем выше получится омлет), перелить яичную смесь. Готовить омлет как в детстве при 180 градусах около получаса до коричневатой корочки, пока она не появится духовку не открывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7109,'Замочить молоком желатин, далее поступать по инструкции на пакетике, творог взбить блендером в пастообразную однородную массу без комочков. Перемешать творог с сахарозаменителем и разбухшим желатином, тщательно перемешать блендером, разложить диетический зефир по формочкам, убрать на пару часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7110,'Взбить сахар, муку, яйца, соль, влить молоко, хорошо взбить, испечь 4 блинчика. Нашинковать кубиками лук, порезать ломтиками грибы, обжарить лук на масле до прозрачного состояния, добавить грибы, обжарить все вместе, дать остыть, порубить зелень, крупно натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7110,'Нарезать кубиками филе, перемешать с грибами, положить половину сыра, всыпать зелень, поперчить, подсолить, тщательно перемешать. На край каждого блинчика уложить начинку, скатать в трубочку. Смазать форму маслом, уложить в нее яичные блинчики с грибами и курицей, смазать их майонезом или сметаной, присыпать сыром, запекать около получаса при температуре примерно 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7111,'Разогреть масло, обжарить до прозрачности кубики лука, добавить паприку, перемешать, положить нарезанное филе, слегка посолить, перемешать, тушить, закрыв крышкой, до полуготовности, периодически помешивать. Если надо, то понемногу вливать горячую воду. Добавить к мясу кубики сладкого перца, раздавленный прессом чеснок и кусочки помидора, тушить до размягчения перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7111,'Разболтать в половине стакана холодной воды ст. л. Муки, перемешать со сметаной в однородную смесь, вылить в сковороду. Куриное филе в сметанном соусе поперчить, посолить, довести смесь до кипения, тушить пару минут, убрать блюдо с плиты, подавать к столу с любым гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7112,'Залить дрожжи теплым молоком, всыпать сахар, перемешать, убрать в тепло, дать опаре подняться. Разболтать с солью яйца, влить растительное масло, подсолить, хорошо перемешать, объединить с опарой. Всыпать муку, вымесить тесто, прикрыть пленкой, убрать в тепло на полчаса. Включить для прогрева до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7112,'Порезать ветчину на кубиками или соломкой, сыр мелко натереть.скатать из теста круглую лепешку, смазать форму, переложить в нее тесто. Смазать поверхность томатной пастой, разложить ананасы с ветчиной, присыпать сыром. Выпекать пиццу «Гавайская» около 25 минут, сразу подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7113,'Вымесить из всех ингредиентов тесто, смазать форму маслом, заполнить тестом. Включить прогреваться духовку. Открыть консервы, слить масло, размять в пюре вилкой, всыпать порубленную зелень и яйца, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7113,'Выложить начинку на тесто, оставляя не заполненным пространство около бортиков. Поместить форму в духовку на треть часа, достать, присыпать тертым сыром, вернуть бюджетный рыбный пирог на 5 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Перенести коржи на противень на скалке, проколоть вилкой несколько дырочек и выпечь каждый корж при температуре 1800 С.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7114,'Перемешать муку с сахаром, влить молоко, перемешать, прокипятить до сгущения, добавить масло, разделить пополам. В одну часть добавить ванильный сахар, а во вторую – какао. Прогреть обе смеси для большего сгущения, разлить ванильно-шоколадный пудинг по порционным стаканам, украсить, убрать на час в холодильник, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7115,'Натереть твердый сыр, моцареллу нарезать на небольшие кусочки, смешать с измельченной зеленью, влить майонез со сметаной, подсолить, поперчить, тщательно перемешать начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7115,'Нарезать лаваш прямоугольниками 20х15 см, положить на край пару столовых ложек начинки, свернуть трубочкой, края подвернуть внутрь, оставить минуты на 4 для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7115,'Обжарить лаваш с сырной начинкой в растительном масле со всех сторон до аппетитно похрустывающей корочки на небольшом огне, подавать блюдо горячим с любимым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7116,'Охлажденные сырки и яйца натереть на терке, лук порезать на мелкие кубики, перемешать, чуть подсолить, добавить красный перец и майонез, перемешать еще раз. Нанести массу на кусочки батона, переложить их на противень, запекать гренки с плавленым сыром при 200 градусах до золотистости и появления приятного аромата, отключить нагрев, дать гренкам дойти в горячей духовке до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7117,'Нарезать курицу на кусочки, перемешать с раздавленным чесноком, паприкой, желатином, солью, порубленной зеленью, перцем. Заполнить смесью рукав для запекания, завязать концы, поместить в форму , дать постоять час, проткнуть пакет в двух местах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7117,'Поместить форму в духовку с температурой 180 градусов на 50 минут, вынуть форму, придавить пакет с мраморным куриным мясом грузом, дать остыть, оставить в холодильнике на ночь. Вынуть форму, удалить рукав, порезать мясо на пластинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7118,'Разболтать в небольшом количестве молока по чайной ложке сахара и муки, добавить дрожжи, оставить на 10 минут. Взбить яйцо, влить молоко, всыпать сахар, добавить опару и масло, тщательно перемешать, порциями всыпать муку до получения чуть липкого мягкого теста, вымесить его пока не начнет отставать от рук, дать постоять (около часа) и подойти. Для приготовления начинки перемешать масло с сахаром с добавлением корицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7118,'Раскатать из теста пласт, смазать смесью масла, завернуть в рулет, разрезать на части, положить в форму, дать постоять примерно 40 минут. Выпекать булочки «Синнабоны» при 160 градусах, около 15 минут до румяной нежной корочки, довести до готовности при 200 градусах около 20 минут. Для приготовления глазури размешать с молоком сыр до однородности, всыпать сахарную пудру, размешать, облить чуть остывшие булочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7119,'Разогреть на среднем огне масло, обжарить за пару минут кубики лука и порубленный чеснок, добавить специи и зелень, обжаривать до тех пор, пока чеснок не начнет темнеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7119,'Добавить сахар с помидорами, перемешать, прикрутить огонь до минимума, нагревать до готовности. Положить в сковороду отваренную пасту, нашинкованный базилик, сыр, перемешать, подавать пасту с сыром к столу горячей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7120,'Лук мелко нашинковать, обжарить на масле до прозрачности, кусочки курицы измельчить блендером, но не до состояния фарша, добавить к луку, поперчить, подсолить, перемешать, переложить в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7120,'Приготовить из картофеля пюре, вбить яйцо, перемешать. Столовую ложку с горкой пюре расплющить на ладони, смоченной водой в лепешку, положить куриную начинку, слепить котлетку, обжарить котлеты из картофеля с одной и другой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7121,'Залить куриное филе тремя литрами воды, подсолить, поперчить, проварить до готовности, достать мясо. Всыпать в кипящий бульон рис, проварить 10 минут, добавить кубики картофеля, тертую морковь, кубики лука, варить около 7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7121,'Добавить порезанное мясо, варить супчик с курицей и рисом до полного размягчения картофеля, всыпать кусочки сыра, перемешать, убрать с плиты, подавать с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7122,'Порезать рыбу на порции, посолить, поперчить с каждой стороны, картофель порезать на кружочки, выложить его в смазанную форму, поперчить, посолить, прикрыть кусочками рыбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Муку, ванилин и сахар перемешать с яичными желтками, влить коньяк и опять размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11231,'Пирожные должны стать золотистого цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7122,'Натереть чайную ложку цедры, присыпать каждый кусочек рыбы, побрызгать соком лимона, смазать сметаной, присыпать сырной стружкой. Поставить форму с филе рыбы под шубой в духовку на полчаса, готовить при температуре 180 градусов. Разложить рыбу по тарелкам, присыпать измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7123,'Разрезать бананы вдоль на 2 части, воткнуть в каждую по шпажке, переложить на доску, убрать в морозилку минут на 20. На водяной бане растопить поломанный на кусочки шоколад, влить растительное масло, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7123,'Насыпать в блюдца порубленные орехи и присыпку разных цветов, обмакнуть банан в шоколад, обвалять в орехах и присыпке. Убрать эскимо из банана для застывания шоколада в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7124,'Подготовить мясо, порезать на полосы, обжарить в разогретом масле до коричневатой корочки, нашинковать лук полукольцами, добавить к мясу, перемешать, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7124,'Добавить муку, быстро сразу перемешать, залить стаканом горячей воды, тушить на малом огне под крышкой около 50 минут, посолить, добавить специи. Залить мясо смесью горчицы со сметаной, готовить мясо с горчицей и сметаной еще около получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7125,'Растопить на водяной бане поломанный шоколад с маслом (можно использовать микроволновку), всыпать сахар, перемешать до получения однородной массы. Сложить в глубокую миску все сухие ингредиенты вместе с сухофруктами, переложить в чашу миксера шоколадную смесь, вбить одно за другим 3 яйца (после каждого перемешивать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7125,'Добавить небольшими порциями смесь сухих ингредиентов с орехами, взбивать все время на малой скорости. Скатать из получившейся массы небольшие шарики, слегка сплюснуть, переложить на противень, выстланный пергаментом. Выпекать шоколадные пряники с изюмом около 20 минут в предварительно разогретой до 180 градусов духовке',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7126,'Нарезать курятину на кубики, с корейской морковью и кукурузой, добавить в салат «Пикантный» майонез, перемешать дать постоять полчаса, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7127,'В кастрюльку с толстым дном налить молоко, поломать шоколад, всыпать сахар, добавить желтки, прогреть на водяной бане до сгущения, дать остыть. Перемешать со взбитыми до устойчивой пены сливками, разложить шоколадный пломбир по формочкам, убрать в холодильник, перед подачей украсить по своему вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7128,'Перемешать все сухие ингредиенты, взбить яйца, добавить к ним масло, взбить, влить молоко и всыпать сухую смесь небольшими порциями, после каждого добавления хорошо взбивать до образования густого теста влить стакан кипятка, хорошо взбить до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7128,'Подготовить форму, выстлать пергаментом, смазать маслом, заполнить половиной теста, выпекать около получаса при 180 градусах до «сухой спички», повторить для второй части теста. Для сливочного крема взбить масло и вареную сгущенку до однородности, порубить обжаренные орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7128,'Испечь обычное безе из взбитых трех белков со стаканом сахара. Заполнить массой кондитерский мешок, высадить безе на противень, выстланный бумагой, печь-сушить 1,5 часа при 110 градусах, дать остыть в духовке. У готового коржа срезать подсушенные края, смазать его кремом, выложить на него безе, промежутки тоже заполнить кремом, присыпать орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7128,'Накрыть другим коржом, смазать верх трюфельного торта кремом, присыпать орехами, убрать в холодильник. Растопить шоколад с маслом, перемешать, полученной глазурью покрыть торт, дать застыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7129,'Включить прогреваться до 200 градусов духовку. Готовые пласты теста раскатать, чтобы оно увеличилось примерно в полтора раза, нарезать каждый на 6 частей, по краю на каждый выложить жирную сметану (идеально —  домашнюю), положить на нее малину, слегка присыпать сахаром, свернуть аккуратно в трубочки. Переложить слоеные трубочки с малиной в форму, смазать разболтанным желтком, поставить примерно на полчаса в духовку, готовые трубочки присыпать сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7130,'Вбить в кефир пару яиц и белок, добавить растопленные шоколад и масло, всыпать сахар, перемешать. Перемешать муку с какао, разрыхлителем и содой, объединить со смесью жидких ингредиентов, тщательно вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'В сотейнике довести молоко до кипения, влить в него подготовленную мучную смесь, хорошо перемешать и поставить на маленький огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7131,'Обжарить в разогретом масле порубленный чеснок с перцем чили, через пару минут добавить полукольца лука и розмарин. Когда лук подрумянится положить грибы, жарить до образования золотистой корочки, подсолить, поперчить. Отварить картофель в мундире, очистить, порезать на кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7131,'Приготовить заливку из взбитых яиц со сливками и натертым сыром, поперчить, подсолить, перемешать. Выложить на дно формы грибы, кусочки моцареллы, затем кружочки картофеля, посолить, поперчить, залить сырносливочной смесью, присыпать сырной стружкой. Выпекать сырную запеканку с грибами при 180 градусах примерно 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7132,'Обжарить орехи минут 5, для насыщенного вкуса можно 10 минут при температуре 180 градусов, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7132,'Пересыпать орехи в чашу блендера, добавить мед с солью, взбить около минуты, постепенно добавляя масло до получения гладкой массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7132,'Довести арахисовое масло до нужной консистенции можно погружным блендером, переложить в баночку, хранить в холодильнике до 2 месяцев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7133,'Взбить венчиком до однородного состояния молоко с сырыми куриными яйцами, обычным и ванильным сахаром. Соду, погашенную уксусом, перемешать с мукой и постепенно ввести в тесто. Массу помешивать, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7133,'Разогреть сухую сковороду, жарить ванильные панкейки до появления золотисто-коричневой корочки. Готовые блинчики полить жидким медом и растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7134,'Желатин залить холодной водой на полчаса. В набухший продукт добавить какао-порошок, мёд, обезжиренное молоко. Поставить смесь на тихий огонь, нагревать до тех пор, пока полностью не растворится какао. До кипения не доводить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7134,'Вмешать обезжиренный творог, перемешать и превратить смесь в однородную массу при помощи блендера. Творожное суфле разлить в формы, поставить в холодильник на два часа, можно на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7135,'Сырые куриные яйца отварить вкрутую, очистить, натереть на крупной терке. Любой твердый или полутвердый сыр натереть на мелкой терке. Через пресс пропустить зубчики чеснока. Любимую свежую зелень хорошо вымыть, обсушить и мелко порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7135,'Соединить в миске все перечисленные ингредиенты, добавить майонез, перемешать. Полученную начинку завернуть в оттаявшие и развернутые крабовые палочки, выложить их на блюдо горкой, посыпать холодную закуску оставшимся тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7136,'Пшеничную муку просеять вместе с ванилином из пакетика. Отдельно перемешать кефир с пищевой содой, дать постоять десять минут. Сырое куриное яйцо взбить с сахарным песком и солью, добавить растительное масло. Яичную смесь перемешать с кефирной. Порциями всыпать муку с ванилином, перемешивать. Тесто не должно получиться тяжелым. Если масса липнет к рукам – смазать её поверхность растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7136,'Стол присыпать мукой, выложить тесто и раскатать его в толстую, двухсантиметровую, лепешку. Фигурки вырезать с помощью формочек для печенья или обычным стаканом. Кружочки можно надрезать с четырех сторон к центру, не до конца. В процессе обжаривания из таких заготовок получатся цветочки. Жарить пышки-малышки как оладьи, с двух сторон, на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7137,'Рис для роллов варить по следующей схеме: крупу предварительно промыть в холодной воде. Залить новой порцией воды из соотношения: одна часть риса на 1 и 1/4 часть воды. Довести до кипения, огонь убавить, прикрыть крышкой, через 14 минут снять кастрюлю с огня. По желанию добавить рисовый уксус, перемешать и остудить. Любую красную слабосоленую рыбу, например, форель или семгу, нарезать длинными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7137,'Очистить авокадо и также нарезать вдоль. Коврик или циновку для роллов обернуть пищевой пленкой. Лист нори разрезать пополам и положить блестящей стороной на коврик. Руки смочить в воде с уксусом. Выложить слой отваренного риса: с одной стороны оставить полтора сантиметра нори без начинки, с другой стороны рис должен выйти за границы нори тоже на полтора сантиметра. Циновку свернуть вдвое, перевернуть так, чтобы рис оказался внизу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7260,'Убрать морские гребешки со сковороды и добавить в нее сок лимона и вино, чуть-чуть потушить, получившийся соус вылить на гребешки, посыпать морские гребешки в лимонном соусе цедрой и петрушкой и сразу подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7137,'Посредине выложить начинку из рыбы и авокадо. Свернуть ролл, аккуратно обжать, придав ему квадратную или круглую форму. Должен получиться ролл рисом наружу. Обильно посыпать рулет кунжутным семенем. Дать роллу немного полежать, нарезать на ровные и одинаковые роллы с красной рыбой ножом, смоченным в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7138,'Куриную грудку вымыть, отварить. Мясо охладить, отделить от костей, нарезать и размять в кашицу. Из половинки хорошо вымытого лимона выдавить на курицу сок. Посыпать перцем и посолить по вкусу. Массу перемешать и дать постоять в течение 15 – 20 минут в холодном месте, для пропитывания. Покрыть мясо слоем майонеза, сверху – кусочки консервированных ананасов и сладкая кукуруза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7139,'Пшеничную муку насыпать в миску, посередине сделать углубление. Влить минеральную воду, сметану, водку, всыпать сахар и соль. Все ингредиенты перемешать ложкой. Вымесить массу на столе, присыпанном мукой. Накрыть салфеткой и дать полежать, затем еще раз вымесить. Готовое тесто очень тонко раскатать, толщина лепешки – один миллиметр. Чтобы было удобнее, массу лучше поделить на несколько частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7139,'Полученные пластины скатать в нетугие рулеты. По желанию поверхность лепешки перед скручиванием смазать растопленным сливочным маслом, но можно обойтись и без этого. Острым ножом нарезать рулет из теста под углом в 45 градусов. Толщина кусочков – по два сантиметра. Свободный край прищипнуть к тесту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7139,'В глубокой сковороде раскалить большое количество растительного масла. Кусочки жарить во фритюре с двух сторон до получения золотистой корочки. Обжаренную пахлаву выложить на бумажное полотенце для впитывания излишков жира. Приготовить сироп из воды, сахарного песка и натурального меда. Поварить на огне, помешивать. Жидкость должна пузыриться. В готовый сироп окунуть уже наполовину остывшую медовую пахлаву.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7140,'Формы для выпекания застелить фольгой, смазать растопленным сливочным маслом. Духовой шкаф прогреть до 180 градусов. Для приготовления коржей взбить размягченное сливочное масло с сахарным песком в течение трех-пяти минут до состояния пышности. Вбить сырые куриные яйца по одному, продолжать взбивать еще одну или две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7140,'Красный пищевой краситель перемешать с какао-порошком. Можно добавить немного воды, смесь должна быть похожей по консистенции на сметану. Ввести полученный краситель в масляную смесь, взбивать на низкой скорости. Кефир и пшеничную муку добавлять поочередно, продолжать взбивать. В конце приготовления посолить, всыпать ванильный сахар или влить немного ванильного экстракта, соду, погашенную винным или яблочным уксусом. Все ингредиенты еще раз хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7140,'Разложить тесто в формы, поставить в духовой шкаф на полчаса или немного больше: проверить готовность с помощью зубочистки или спички. Коржи остудить. Для крема взбить размягченное сливочное масло в течение двух-трех минут, всыпать сахарную пудру, взбивать еще минуту, масса должна стать пышной. Ввести мягкий сливочный сыр, взбивать еще минуту. В конце приготовления добавить ванильный экстракт и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7140,'Крем поставить в холодильник на 15–20 минут. Для приготовления имитации крови перемешать кофе с медом и сгущенным молоком, добавить краситель красного цвета или свекольный сок, загустить крахмалом. Промазать остывшие коржи кремом, перед подачей страшно красивый торт сбрызнуть смесью с красителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7141,'Белки сырых куриных яиц отделить от желтков. Первые взбить в плотную пену, добавить сахарный песок в несколько приемов. Далее вводить желтки, массу продолжать взбивать. Смесь должна увеличиться в объеме в два-три раза, все процедуры можно проделать с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7141,'В массу всыпать манную крупу, разрыхлитель, муку, все ингредиенты осторожно перемешать ложкой движениями от краев к середине. Сковороду или форму с невысокими бортиками смазать маслом и присыпать мукой по всей внутренней поверхности. Выложить тесто, корж печь при температуре 180 градусов в течение 20–25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7163,'Затем рулет свернуть в форме улитки. Верх смазать топленым сливочным маслом. Булочки поставить в теплое место, чтобы они подошли. Выпекать в духовке 20 минут при температуре 180 градусов. Готовые румяные булочки «Ensaimadas» посыпать сахаром или пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7141,'Готовность изделия можно проверить зубочисткой. Отдельно довести до кипения молоко, но не кипятить, добавить ванилин и сахар. Корж, остывший наполовину, нарезать на порционные кусочки и полить молочной смесью в той же сковороде, где он готовился. Жидкость должна впитаться полностью. Поставить десерт-бисквит в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7142,'Противень прямоугольной формы смазать маслом, застелить бумагой для выпекания. Белки отделить от желтков и взбить первые в плотную, тянущуюся массу. Желтки взбить с сахарным песком, всыпать пищевую соду и какао. Ввести белки в желтки, осторожно, чтобы масса не опала. Готовое тесто перелить на противень. Печь в течение семи или десяти минут, температура приготовления – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7142,'Готовый корж переложить на смоченное водой кухонное полотенце, осторожно скрутить в рулет и остудить. Остывшее изделие раскрутить, бумагу снять. Поставить на огонь молоко с мукой, довести смесь до густой консистенции. Снять с огня, вбить сырое яйцо. Остудить массу полностью. Сливочное масло комнатной температуры перемешать с мучным кремом и разделить массу на две неравные части: 60/40.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7142,'В меньшую часть добавить ванильный сахар, в большую – какао-порошок, смешанный с сахарной пудрой. Половину темного крема оставить для украшения. На корж осторожно намазать ванильный и шоколадный крем слоями. Выложить очищенные ровные бананы вдоль, скрутить рулет. Верх покрыть остатками шоколадного крема и присыпать какао-порошком. Шоколадно-банановый рулет поставить в холодильник на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7143,'В емкость всыпать пшеничную муку, сахар, соду, соль, какао-порошок, ванилин из пакетика, крахмал. Влить уксус, холодную воду, растительное масло. Ингредиенты тщательно перемешать венчиком, вылить в разъемную форму, смазанную маслом. Тесто поставить в духовой шкаф на 25 минут, температура приготовления – 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7143,'Пирог вынуть, остудить и выложить на тарелку. Для заливки влить в кастрюлю молоко с водой или только воду, прогреть. Добавить сахар, всыпать какао-порошок, перемешать. В небольшом количестве воды развести крахмал, перелить в кастрюлю тонкой струей. Перемешивать до появления первых пузырей, снять, остудить, смесью залить шоколадный пирог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7144,'Растворить в теплой воде сахар и крахмал, затем влить соевый соус, уксус, добавить перец и тертый имбирь, чеснок. Варить соус на очень медленном огне, постоянно помешивая, пока не загустеет. Куриное мясо хорошо вымыть и высушить. Полить соусом мясо и оставить для пропитки на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7144,'Противень смазать растительным маслом, выложить мясо на противень и полить оставшимся соусом. Поставить курицу в разогретую духовку на 30 минут при температуре 200 градусов. Во время приготовления необходимо переворачивать мясо и поливать соусом. Подавать курицу терияки с традиционным вареным рисом или рисовой лапшой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7145,'Смешать до однородности творог и мягкое сливочное масло, замесить тесто, добавив смешанный с мукой разрыхлитель, затем раскатать его, вырезать кружки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7145,'В сахар обмакнуть круги теста со всех сторон и сформовать печенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7145,'На дно противня положить пекарскую бумагу, разложить на нее печенье.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7145,'Выпекать творожное печенье в сахаре при 180 градусах до подрумянивания, когда все будет готово, вынуть противень из духовки, дать печенью полностью остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7146,'Выбрать ровные крупные яблоки и очистить их от кожуры и сердцевины. Начинять яблоки можно разнообразной начинкой, например, измельченная курага, изюм, грецкие орехи, цукаты. Смешать их с коричневым сахаром или медом и растопленным сливочным маслом. Все хорошо перемешать и начинить яблоки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7146,'Чтобы придать красивую форму яблочка, вместо хвостика вставить палочку корицы. Запекать яблоки 10 минут в духовке при температуре 180 градусов, постоянно поливая соком апельсина или мандарина. Запеченные яблочки с сухофруктами очень вкусны сразу после духовки, когда ароматный сироп льется из сочной мякоти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7164,'Яйца сварить, порезать соломкой белки, а желтки сложить отдельно. Первый слой из яичных белков, затем сетка из майонеза. Следующий слой — вареное куриное мясо, порезанное мелким кубиком, майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Разрезать брюшко, выпотрошить рыбку, голову при этом не отрезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7147,'Курицу замочить на 30 минут в холодной воде, затем варить в подсоленной воде, собирая пену. Вареный окорочок необходимо разобрать на небольшие кусочки, удалив кости. Очистить морковь и лук, порезать маленьким кубиком. Картофель и перец также нарезать небольшими кубиками. Все сложить в кипящий бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7147,'Затем порезать зелень и высыпать в бульон к овощам, чтобы насытить ароматом и витаминами. Через 10 минут после кипения овощей засыпать макароны и специи. Выключить бульон и оставить настаиваться под крышкой. В это время приготовить сухарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7147,'Порезать батон белого хлеба и запечь в духовом шкафу, затем полить чесночным маслом. В тарелку для супа налить горячий куриный бульон, добавить сливки, посыпать чесночными гренками. Украсить сливочный суп с курицей дольками свежего помидора, варенными перепелиными яйцами и свежей зеленью. В конце вылить ложку тыквенного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7148,'Сначала следует замочить желатин в холодной воде на 10 минут, затем довести его до кипения, но не кипятить. Теперь необходимо взбить миксером смесь из сметаны, кефира и сахара в пышную массу. Когда начнет образовываться пена, вылить охлажденный желатин. Взбивать еще 3 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7148,'Пышную пенистую массу разлить по бокалам и выставить на холод на 3-4 часа. Украсить корицей, молотым миндалем или мускатным орехом. Воздушный молочный десерт для детей можно украсить свежими ягодами или цитрусами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7149,'Фарш для митлофа (мясного батона) приготовить из свинины и говядины. Чтобы мясо легко перемололось, оно должно быть немного мороженым. В фарш добавить давленый чеснок. В сковороде обжарить мелко нарезанный лук до золотистого цвета, затем добавить к нему порезанные шампиньоны. Чтобы грибы не были сильно водянистыми, их лучше не мыть, а счистить грязь ножом или салфеткой. В конце жарки добавить к грибам базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7149,'Мякоть батона замочить в молоке или в теплой воде. Смешать в большой миске мякоть батона, грибы, фарш и яйцо, хорошо вымесить, посолить и поперчить по вкусу. Фарш «любит», когда его отбивают, для этого всю мясную смесь закутать пленкой и отбить тупым предметом. Из этого фарша необходимо сделать батон, который выложить на смазанный маслом противень. Обернуть тонкими ломтиками бекона, закрыв батон со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7149,'Для аромата посыпать митлоф розмарином и поставить в духовку для запекания при температуре 200 градусов. Через 10 минут уменьшить газ и томить батон до готовности. Во время приготовления необходимо поливать митлоф соком, который вытекает из фарша и бекона. Готовый батон должен постоять в противне, чтобы блюдо напиталось мясным соком и ароматом трав. Теплый мясной батон порезать на порционные кусочки и подавать со свежим овощным салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7150,'Измельчить в блендере очищенный киви и лимон. Киви и лимон богаты на содержание витамина С, а это самый известный противовирусный элемент. К этой смеси добавить банан, измельчить в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7151,'Очистить морковь и натереть на крупной терке. Гречку промыть, а сыр перетереть в крошку руками. Теперь дело за созданием неповторимого аромата блюда. В сковороде на растительном масле обжарить семена кумина до тех пор, пока они не набухнут. Затем добавить молотый черный перец и куркуму. В эту смесь пряностей выложить тертую морковь и немного протушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7151,'В морковь всыпать сыр, перемешать и обжарить. Через 5 минут всыпать гречку, долить воды в пропорции 1:2, посолить и накрыть сковороду крышкой. Гречка готовится на медленном огне, а пока следует подготовить перцы. Каждый перец очистить от сердцевины, семян, срезав верхушку с хвостиком. Закипятить воду и обдать перцы кипятком, чтобы они стали мягче. Теперь можно начинять их гречкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7151,'В кашу добавить немного топленого масла, чтобы подчеркнуть неповторимый аромат. Каждый перец начинить гречкой очень плотно и сложить на противень, смазанный растительным маслом. Противень поставить в духовку на 10 минут. Теперь необходимо подготовить соус, смешав блендером сметану, горчицу и рубленую зелень. Этим соусом полить перчики и поставить в духовку на завершающий процесс. Через 7-10 минут фаршированные перцы с гречкой под соусом готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'Мешочки из блинов с начинкой из куриного мяса, перевязать с помощью перышка зеленого лука или сырной веревочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7152,'Куриное филе помыть и порезать на небольшие кубики. Обжарить на оливковом или растительном масле курицу 10 минут, затем вынуть шумовкой и сложить отдельно. В этом масле, где готовилась курица обжарить лук шалот до мягкого состояния. Если масла мало, необходимо долить еще 1-2 ложки. Затем высыпать овощную смесь и тимьян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7152,'Тушить овощную смесь 4-5 минут, аккуратно помешивая ложкой. Затем к овощам добавить бульон, закипятить. В это время развести в стакане теплого бульона кукурузный крахмал и влить в остальной бульон, кипятить, пока не загустеет. Затем в загущенный бульон высыпать обжаренную курицу и сметану, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7152,'Начинку выложить в форму с высокими бортами. Слоеное тесто раскатать не очень тонко и накрыть им форму с курино-овощной начинкой. Куриный пирог с овощной смесью выпекать в духовке 20 минут при температуре 180 градусов. Когда верх зарумянится, пирог готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7153,'В теплом кефире развести соду, когда пройдет реакция, добавить соль и сахар. Затем всыпать просеянную муку и вымесить мягкое нежное тесто. Скатать тесто в шарик и завернуть пищевой пленкой, оставить его «отдыхать» на 30 минут. В это время необходимо подготовить начинку для хачапури. Взбить блендером творог, тертый сыр и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7153,'Тесто разделить на 4 части и раскатать из каждой тонкую лепешку. Затем в центр положить начинку, защипнуть края в центре и раскатать в лепешку качалкой. Жарить без масла на сковороде с толстым дном. Обжарить хачапури «Проще не бывает» с двух сторон до золотистой корочки. Вкуснейшие грузинские лепешки готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7154,'Взбивание миксером яиц создает пышную пену, но не подходит для жарки омлета. Чтобы создать нужную консистенцию, необходимо яйца взбивать венчиком, добавив молоко и соль. Когда в яичной массе появятся пузырьки, значит, пора жарить омлет. Мы будем его запекать в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7154,'Форму смазать сливочным маслом, вылить яичную смесь и поставить в духовку на 10 минут при средней температуре 180-190 градусов. Когда появится золотистая корочка, пышный омлет готов. Через пару минут омлет немного опадет, это нормальная реакция из-за смены температуры воздуха. Вкус от этого не поменяется, а структура будет очень пышной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7155,'Чтобы тесто для блинов получилось идеальным, можно использовать для смешивания продуктов комбайн или миксер. Так все ингредиенты отлично перемешаются, комочков не будет, и блинчики получатся более нежными. Взбить яйца с сахаром в пену, затем добавить ванилин и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7155,'Влить теплое молоко. Всыпать просеянную муку до консистенции теста жидкой сметаны. В последнюю очередь влить растительное масло. Сковороду раскалить и налить в нее 2 ложки растительного масла. Масло нагреется быстро, но необходимо подождать еще пару минут, когда оно начнет «кипеть» на сковороде, так блины не пристанут, а первый блин не будет комом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7155,'Половником набрать тесто и вылить на сковороду, равномерно распределяя по всей поверхности, переворачивая сковороду в разные стороны. Выпекать блин с двух сторон до румяной корочки, переворачивать при помощи лопатки. Горячие блинчики на молоке смазать сливочным маслом, для сладости присыпать сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Чтобы приготовить блинное тесто необходимо смешать муку, картофельный крахмал, молоко, сахар, яйцо и растительное масло, испечь необходимое количество тонких блинов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Мелко нарезать маслины, яйца, ветчину и огурцы, пополам порезать помидоры черри, на крупной терке потереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Торт выкладывать слоями: тонким слоем майонеза промазать блин, выложить тонкий слой любого нарезанного ингредиента, смазать майонезом и чередовать блин с начинкой, смазывая каждый новый слой майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Последний слой промазать майонезом, хорошо обсыпать тертым сыром и украсить помидорами черри либо яйцом или рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Перед подачей закусочный блинный торт с ветчиной, сыром и овощами необходимо поставить в микроволновую печь на 5-7 минут или на 10 минут в духовку, чтобы он запекся.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7156,'Подавать блюдо можно и холодным, и горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'На крупной терке натереть сыр и вареные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приклеить на глазурь украшения.','https:https://st.vkuso.ru/data/cache/thumb/1e/f50cb1ffbe5001e_434x295.jpg',32);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7157,'Взбить миксером яйца с сахаром в пышную пену, затем всыпать муку постепенно, чтобы не нарушить пышность массы. Разогреть духовку до 200 градусов. Форму для выпекания застелить бумагой для выпечки и смазать сливочным маслом. Вылить половину теста в форму, затем сделать банановый слой. Для этого бананы порезать тонкими кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7157,'Выложить слой бананов и вылить остальную часть теста. Поставить бисквит в духовку на 40 минут, выпекать при температуре 200 градусов. Румяную и очень ароматную шарлотку с бананом остудить и посыпать сахарной пудрой. Пудру для вкуса можно смешать с корицей, какао или ванильным сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7158,'Сначала необходимо подготовить домашние сухарики. Батон белого хлеба нарезать маленькими квадратиками, присыпать солью и приправой и высушить в духовке. Нашинковать капусту и сложить в миску для салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7158,'Сыр натереть на крупной терке. Копчености нарезать мелким кубиком. Соединить все ингредиенты, добавить консервированную кукурузу. Перед подачей на стол в капустный салат добавить майонез и посыпать сухариками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7159,'Смешать все жидкие ингредиенты: кефир, яйца, растительное масло. Для ускорения процесса в помощь придут миксер или комбайн. В другой посуде смешать сухие ингредиенты: муку, соду, какао и сахар. Затем все соединить и вымесить наливное тесто. Форму для торта разогреть и смазать растительным маслом, затем вылить все тесто и поставить в духовку для выпекания на 50 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7159,'Пирог очень хорошо поднимается, корж получается пышный приятного шоколадного цвета. Готовый охлажденный пирог разрезать вдоль на 3 части и смазать кремом. Для лучшей пропитки использовать сметанный крем. Для его приготовления необходимо взбить мягкое сливочное масло, густую сметану и сахар в пышную массу. Добавить ванилин. Но можно использовать менее жирный крем – заварной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7159,'Довести до кипения молоко. Растереть яйца с сахаром в пену и добавить муку, постепенно вмешивая. В кипящее молоко очень медленно вливать яичную смесь, постоянно помешивая, чтобы не было комочков. Варить крем до густой массы. Охладить и взбить с мягким сливочным маслом. Смазанный кремом торт «Фантастика» украсить тертыми орехами, шоколадом или молотым печеньем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7160,'Очищенный банан и ягоды сложить в блендер и измельчить в пюре. Затем влить по вкусу мед и йогурт. Перемешать до пышной массы. Выложить массу в приготовленные формы для мороженного и охлаждать 3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7161,'Сосиски разрезать на тонкие длинные полоски. Сверху положить такую же полоску сыра. Свернуть рулетом и проколоть зубочисткой, чтобы улитка держалась. Запекать в духовке 10 минут до румяных бочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7162,'Если изюм сухой, тогда его следует замочить в кипятке на 15 минут, затем воду слить и подсушить. Изюм измельчить, можно блендером. Если получится вязкая масса, это не повлияет на вкусовые качества, главное, чтобы не было крупных изюмин. Соединить мягкий маргарин, сахар, изюм, ванилин, корицу и растирать массу в течение 5-7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7162,'В горячей кипяченой воде растворить соль и вылить в тесто, одновременно всыпать овсяную муку. Мешать 4 минуты тесто, чтобы овсянка немного набухла. Затем всыпать просеянную пшеничную муку и влить гашеную соду. Мешать. Добавить варенье. Теперь мешать тесто 6 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7162,'Теплое мягкое послушное тесто раскатать в пласт толщиной 1 см и вырезать круглыми формочками печенье. Противень застелить бумагой для выпечки и выложить все печенье. Выпекать овсяное печенье по ГОСТу в духовке 10 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7163,'В миске смешать сухие дрожжи, сахар, соль и муку. Если воспользоваться миксером или кухонным комбайном, дело пойдет веселее. Затем добавить воду, растительное масло и яйца. Вымесить мягкое тесто, которое не липнет к рукам. Скатать шарик и накрыть пищевой пленкой. Тесто должно подойти и увеличиться в размере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7163,'Затем этот шарик разделить на 4 части и каждую раскатать в тонкий пласт по форме квадрат. Нанести слой сливочного масла, смазав обильно всю поверхность теста. На одну сторону расположить начинку из фруктов с сахаром и пряностей. Свернуть тесто, сформировав тонкий аккуратный рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Перемешать в миске стружку кокоса, миндальную муку, сахарную пудру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7164,'Посыпать мелко нарезанным луком, затем слой маринованных грибов, порезанных кубиком или тонкими пластинками. Полить майонезом. На грибочки выложить слой порезанных мелким кубиком свежих огурцов, затем опять грибы, майонез. Теперь засыпать тертым сыром, сделать майонезную сетку. Верхний слой салата с курицей и шампиньонами из яичных желтков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7165,'Чтобы фасоль сварилась быстрее, ее необходимо на ночь замочить. Так вылезут возможные червячки, а фасоль немного набухнет. В кипящий бульон высыпать фасоль и варить до мягкости. На растительном масле обжарить нашинкованную капусту, посолить, добавить специи и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7165,'Тушить капусту до мягкости. Отдельно необходимо обжарить томатную пасту с небольшим количеством воды, затем в нее высыпать капусту и протушить 5 минут. Высыпать содержимое сковороды в кастрюлю с вареной фасолью. Порезать кружочками колбаски, добавить в суп. Варить 15 минут, чтобы насытились ароматом все ингредиенты. В завершении добавить в густой фасолевый суп перчик чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7166,'Киви порезать на маленькие кусочки. Соединить с мелко порезанным бананом. Слегка помять. Насыпать сахар, добавить желатин. Варить минут семь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'С помощью блендера из груши сделать пюре, смешать его с хлопьями и корицей, все хорошо перемешать и тонким слоем выложить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'Противень поместить в прогретую духовку, постоянно посматривая, выпечь на маленьком огне до появления золотистого цвета, готовый и полностью остывший корж измельчить в блендере в муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'В блендере измельчить в пюре изюм, добавить к нему кофе, все вместе еще раз измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'Творог смешать с измельченным изюмом и коньяком, тщательно перемешать, в получившуюся массу добавить муку из коржа, снова перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'Из полученной однородной массы сформовать пирожные, обвалять их в какао-порошке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7167,'Низкокалорийное пирожное «Картошка» на несколько часов поместить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7168,'Соединить все сухие ингредиенты. Налить воду, оливковое масло. Хорошенько перемешать. Тесто должно быть густое. Накрыть влажной салфеткой, отправить в тепло минут на тридцать. Тесто тоненько раскатать или размять руками на формочку, противень или сковороду, можно также сделать порционные пиццы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7168,'Намазать тесто тоненьким слоем майонеза. Положить сверху порезанную колбаску, помидоры, маслины. Обильно посыпать сыром. Готовить пиццу из дрожжевого теста минут 25, соблюдая температуру 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7169,'Растопить маргарин или масло, дать остыть, насыпать ванильный и обыкновенный сахар, вбить яйца, насыпать муку, хорошенько размешать. Готовить в вафельнице. Чтобы приготовить крем, взять вареную сгущенку, сливочное масло, размешать. Начинить трубочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7170,'Соединить яйцо и молоко, посыпать перцем, солью, мелко порезанным укропом. Взбить смесь при помощи вилки или венчика. Порезать хлеб. Выложить ломтики хлеба в молочно-яичную смесь, оставить, чтобы хорошенько пропитались. В это время поставить на плиту сковороду с растительным маслом, подогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7170,'Обжаривать гренки со всех сторон, если в тарелочке осталась яичная смесь, то осторожно вылить ее на гренки. На приготовленные гренки положить по тоненькому кружочку помидора, чуть-чуть посыпать перцем, солью. Посыпать гренки потертым сыром, отправить под гриль, сыр должен растаять и появиться аппетитная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7171,'Порезать масло в холодном виде на небольшие кусочки, взбить в кухонном комбайне или при помощи миксера, посыпать солью, обыкновенным и ванильным сахаром. Яйцо и желток, чуть-чуть взбить в отдельной емкости, медленно влить в основную смесь. Гасить соду уксусом, добавить в тесто. Муку просеять, замесить тесто. Ненадолго отправить тесто в холодильник (пока готовится повидло).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7171,'Поделить тесто пополам (если противень большой, то можно не делить). Раскатать тесто, чтобы получилась толщина 5 миллиметров (тесто не поднимается в духовке, поэтому можно сделать толщину до 8 миллиметров). Накрутить тесто на скалку, переложить на противень, застеленный специальной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'Все подготовленные ингредиенты смешать с орехами, заправить майонезом, поперчить, посолить и тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7171,'Выпекать до зарумянивания, соблюдая температуру 240 градусов. Не стоит долго готовить, потому что может получиться рассыпчатый сухой корж, а не мягкий коржик для пирожного. Все духовки разные, поэтому трудно выбрать точное время приготовления. В одной духовке тесто будет выпекаться 8 минут, а в другой 15 минут. Таким же способом приготовить второй корж. Обрезать коржи, обрезки использовать для присыпки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7171,'Намазать один корж 1/2 частью приготовленного повидла. Второй корж положить сверху. Коржи получаются очень ломкие и нежные, поэтому лучше сразу их не обрезать. Желательно сначала обмазать нижний корж, не трогая краешки, положить второй, а потом уже обрезать. Сверху выложить оставшееся повидло. Посыпать крошкой. Желательно дать постоять часа два, чтобы песочное пирожное стали мягче, разрезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7172,'Приготовить тесто: развести дрожжи теплой водой. Насыпать муку в емкость, посыпать солью, добавить масло. Вылить разведенные дрожжи. Вымесить в посуде, а потом усердно мять, пока не перестанет липнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7172,'Положить в чашку, накрыть и отставить минут на шестьдесят. Тесто увеличится раза в три. Затем снова помять. Поделить на две части. Раскатать, чтобы получился равномерный круг или другая геометрическая фигура – по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7172,'Пока подходит тесто, заняться приготовлением соуса. Взять овощной набор, измельчить, потушить, пожарить. Положить чесночок и любые другие специи по вкусу. Основу для пиццы намазать соусом, засыпать каким-нибудь мясом. Положить грибочки, помидоры, сыр. Готовить пиццу на тонком тесте минут двадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7173,'Приготовить глазурь: растопить масло, соединить с какао. Медленно, чередуя, насыпать сахарную пудру, налить молоко, взбить до однородности. Добавить ваниль, хорошенько перемешать. Нагреть духовку до 175 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7173,'Две большие круглые формочку для торта намазать сливочным маслом. Просеять разрыхлитель, муку, какао, сахар, соль, соду. Взбить яйцо, влить молоко, оливковое масло, добавить ванилин. Взбивать минуты две с помощью миксера. Налить горячую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7173,'Замесить тесто, разлить равномерно по подготовленным формочкам. Выпекать минут 35. Готовность проверять зубочисткой. Остудить. Намазать между коржиками глазурью, а также всю поверхность снаружи. Посыпать идеальный шоколадный торт тертым шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7174,'Насыпать соль и приправы в фарш, добавить яйцо, хорошенько размешать до однородности. Из полученного фарша сделать шарики среднего размера. Посыпать тертым сыром. Разморозить и тоненько раскатать готовое слоеное тесто, порезать на длинные полоски шириной приблизительно по 1 сантиметру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7174,'Данными слоеными полосочками обмотать шарики, намазать взбитым желтком, сверху посыпать кунжутом. Отправить в духовку, готовить до золотистого цвета, соблюдать температуру 180 градусов. Подавать соленые клубочки с фаршем с овощным салатом или просто овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7175,'Отварить яйца, мелко натереть отдельно белки и желтки. Мелко натереть крабовые палочки и сыр. Смешать желтки, сыр, кукурузу, прессованный чесночок, крабовые палочки. Заправить салатик майонезом, если нужно посыпать солью. Скатать шарики, хорошенько обвалять в белках, сделать снеговиков. Украсить морковью, из маслин сделать пуговицы и глаза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7176,'Порубить масло или маргарин с мукой при помощи ножа, чтобы получилась крошка. Насыпать разрыхлитель, сахар, добавить яйцо. Замесить тесто. Получается песочное тесто, месить его долго не следует. Перестать месить, когда получится однородный комок. Отправить тесто в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7176,'Сделать начинку: помыть фрукты, порезать на средние кубики. Добавить ложку крахмала. Взбить яйца со сметанкой, обычным и ванильным сахаром, мукой. Выложить тесто в формочку, сделать бортики. Положить на тесто фрукты, залить кремом. Готовить песочный пирог с фруктами в сметанной заливке в духовке минут сорок при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7177,'Предварительно достать из холодильника яйца и сливочное масло. Залить дрожжи теплым молоком, добавить сахар, муку, хорошенько размешать, отставить минут на пять. В отдельной емкости растереть яйцо, обычный и ванильный сахар, растительное масло, соль. В смесь из дрожжей и молока насыпать просеянную муку, размешать, соединить с яичной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7177,'Положить 1/2 часть сливочного масла, хорошенько размешать, масло должно распределиться равномерно. Насыпать еще половину стакана просеянной муки, перемешать. Положить остальное масло, насыпать муку. На столе, посыпанном мукой, замесить тесто, положить в кастрюльку, смазанную растительным маслом. Накрыть крышкой, отправить в теплое место приблизительно на шестьдесят минут. Если тесто плохо поднялось, то время увеличить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7177,'В то время, пока тесто подходит, приготовить пудинг, как написано на упаковке, переложить в емкость, время от времени перемешивать, чтобы не появилась корочка. Когда тесто подойдет, положить его на стол, присыпанный мукой, разделить на семь частей, из каждой части сделать пласт, в центр положить чуть-чуть пудинга. Свернуть трубочками, краешки чуть-чуть растягивать, таким образом сделать все заготовки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7177,'На противень постелить пергамент, намазать сливочным маслом. Из каждой трубочки сформировать «улитку», загнув края под низ, положить на противень. Накрыть пленочкой, отставить минут на двадцать, чтобы булочки окончательно поднялись. Нагреть до 180 градусов духовку, булочки намазать взбитым яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7177,'Отправить в теплую духовку, в горячей булочки могут полопаться. Готовить, пока не станут слегка золотистыми. Добавить температуру до 200 градусов и печь до готовности. Достать булочки «Улитки» с пудингом из духовки, посыпать сахарной пудрой, при желании намазать сиропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7178,'Отварить яйца, картофель, морковь. Остудить и почистить. Открыть консервированную горбушу, слить жидкость, переложить в емкость, размять вилочкой. Положить к горбуше крупно потертый картофель, мелко потертую морковь. Размешать. Положить мелко потертые яйца и сыр. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7178,'Помыть и измельчить зеленый лучок. Положить в салатик. Налить соевый соус. Заправить сметаной, размешать до однородности. Из получившейся массы руками сформировать шарики, по величине, чуть-чуть больше грецкого ореха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7178,'Обжарить на сухой сковороде кунжут до золотистого оттенка. Обвалять в кунжуте каждый шарик. Переложить готовые салатные шарики «А-ля Мимоза» на тарелочку. По желанию украсить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7179,'Помыть сердечки, откинуть на дуршлаг, при необходимости обработать. Разогреть сковороду, добавив небольшое количество масла, положить сердечки, посыпать перцем, солью, готовить под крышкой, перемешивая время от времени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7179,'Измельчить лук, обжарить на другой сковороде, переложить в сковороду к сердечкам. Когда они дадут много сока, сделать огонь тише, готовить приблизительно минут тридцать. Если во время готовки сердечек сок не появился, то добавить примерно стакан бульона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7179,'Приготовить заправку: для этого соединить йогурт, измельченную зелень, прессованный чесночок. Когда испарится жидкость раза в два, подливка должна загустеть. Добавить сыр, размешать до однородности. Заправить йогуртом с порубленной зеленью, добавить чуть-чуть крахмала для загустения. Хорошенько размешать сердечки куриные в соусе из сыра, если есть необходимость – досолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7180,'Соль, муку и перец смешать, в полученной смеси обвалять куриные окорочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7180,'В жаровне растопить масло, затем уложить окорочка, посыпать их приправой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7180,'Запечь курицу до появления золотистого цвета, постоянно поливать образующимся во время готовки соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7180,'Запеченные куриные окорочка в муке подаются горячими с гарниром по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7181,'Приготовить бисквит: миксером минуты четыре взбивать яйца, скорость постепенно увеличивать. Насыпать по частям сахар или сахарную пудру, взбивать еще приблизительно минуту. Насыпать муку, еще минуту взбивать. Взять формочку со съемным бортиком, намазать маслом, постелить пергамент.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7181,'Положить в формочку тесто, отправить минут на 25 в духовку, соблюдать температуру 190 градусов. Приготовить крем: соединить в сотейнике молоко с сахаром, поставить на плиту. Отдельно соединить муку с яйцом и крахмалом. Медленно в емкость налить горячее молоко, перемешать до однородности, снова вылить в сотейник. Помешивая, довести до кипения, кипятить секунд 60.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'Каждый пряничный ломтик обмакнуть в сметану, уложить на дно миски, образовавшиеся пробелы заполнить пряничными обломками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7181,'Убрать с огня, положить сливочное масло, в готовый крем можно положить сгущенное молоко или взбитые сливки, так крем получится еще воздушней и вкусней, однако, калорийней. Переложить крем в посуду, накрыть полиэтиленом, остудить. Когда бисквит остынет, обильно намазать его кремом, отправить минут на 25 в холодильник. На крем сверху положить ягоды, полить желе, отправить тирольский пирог в холод еще часа на три минимум.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7182,'Приготовить тесто: растереть мягкое масло, сахар, желтки, соль. Просеять муку в полученную массу, замесить тесто. Сделать шарик. Приготовить начинку: смешать сметану, творог, яйца, сахар, размять до однородности. Размешать ягоды и крахмал, положить в начинку, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7182,'Разогреть духовку, выложить тесто в формочку диаметром 20 сантиметров, сделать бортик приблизительно 4 сантиметра. Вылить начинку. Отправить минут на 45 в духовку. Осторожно достать пирог из формочки, остудить, чтобы схватилась начинка. Охлажденный пирог «Ягодное искушение» разрезать на кусочки и подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7183,'Почистить лук, порезать на полукольца. Крупно порезать овощи, сложить в салатник. Положить сверху лучок, маслины, порезанный на крупные кусочки сыр фета. Греческий салат заправить орегано, соком лимона, оливковым маслом, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7184,'Взбить мягкое масло и сахар, не переставая взбивать положить яйца, творог, соду, ванилин и разрыхлитель. Насыпать муку, замесить тесто. Переложить его в формочку диаметром 23 сантиметра, смазанную маслом. Выпекать минут сорок, соблюдать температуру 180 градусов, проверять зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7184,'Остывший корж поделить пополам, намазать между ними слой крема. Чтобы приготовить крем, взбить творог со сметаной, насыпать по вкусу сахар. Влага из крема впитается, получится плотная прослойка по дабл-творожному торту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7185,'Порезать укроп, лук порей, кинзу. Вместо порея подойдет обыкновенный репчатый лук. Раскатать лаваш, намазать 1/2 сливочного плавленого сыра. На сыр положить семгу или другую красную соленую рыбку, порезанную на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7185,'На начинку положить второй лист лаваша, прижать чуть-чуть ладонью. Намазать его сыром, перемешать порезанную предварительно зелень, равномерно положить. Осторожно завернуть справа налево, завернуть в пакетик, отправить рулет из тонкого лаваша с семгой в холодильник минут на шестьдесят для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7186,'Разогреть духовку до 210 градусов. Намазать квадратную формочку растительным маслом. В большую посуду положить кукурузу, фасоль, кинзу, зеленый лук, орегано, тмин, чесночок, посыпать солью. Положить на дно формочки тоненький слой помидоров (приблизительно 1/5 от всего количества).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7186,'Покрыть четырьмя пластинами лазаньи. На пластины положить 1/3 часть смеси с фасолью. На нее положить равным слоем 1/4 часть помидоров, побрызгать чуть-чуть острым соусом. Посыпать 1/4 сыра. Повторить слои еще несколько раз, то есть лазанья, фасоль, помидорки, сыр, снова лазанья и так далее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7186,'Плотно закрыть формочку фольгой. Выпекать минут 45, или пока лазанья не станет мягкой. Убрать фольгу, готовить еще минут пять, чтобы расплавился сыр. Достать из духовки, дать настояться мексиканской лазанье приблизительно минут десять перед нарезкой и подачей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7187,'Взбить яйца, налить молоко, насыпать обычный и ванильный сахар. Взбивать до однородной консистенции. Насыпать муку с разрыхлителем. Вновь хорошенько взбить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7187,'При помощи ложки сформировать панкейки, обжаривать на маленьком огне (жарить, не добавляя масло, получается ровная текстура). Когда появятся пузырьки, перевернуть пышные американские панкейки, на каждой стороне жарить приблизительно шестьдесят секунд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7188,'Насыпать в посуду манку, муку, ванильный и обычный сахар, стружку кокоса, разрыхлитель, хорошенько размешать. Налить кефир или йогурт, растительное масло. Взбить чуть-чуть с помощью вилки в стакане яйцо. Вылить яйцо в общую смесь. Размешать, чтобы получилась средняя густота.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'Взять плоское блюдо, в центр которого поставить стакан или бутылку, вокруг выложить готовый салат, слегка придавить ложкой, затем осторожно убрать бутылку или стакан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'Перед подачей куриный салат «Леший» с грибами и сыром оформить маслинами и зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7188,'Формочку 25 на 25 сантиметров намазать маслом. Налить тесто, потрясти формочку, чтобы тесто разошлось равномерно. На тесто выложить миндальные орешки ровным слоем, не вдавливая. Отправить в духовку, разогретую до 180 градусов. Готовить минут сорок. Приготовить сироп: положить в среднюю кастрюльку сахар, сок лимона, воду. Довести до кипения, не переставая перемешивать, кипятить минуты три. Охладить минут двадцать сироп и приготовленный пирог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7188,'Разрезать пирог при помощи острого ножа на прямоугольники, не вынимая из формочки. В серединке каждого кусочка должно быть по орешку. Полить пирог охлажденным сиропом, используя ложку. Сироп должен залить поверхность пирога, орешки и чуть-чуть разрезы. Остудить арабскую сладость «Басбуса» полностью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7189,'Варить на маленьком огне, пока леденцы не станут темными. После этого убрать с огня, разлить по формочкам. Если все сделано во время, то застынут быстро, если сняты рано, то получится густая, вязкая карамель, которая даже в морозильной камере не застынет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7190,'Масло или маргарин взбить с яйцом и сахаром, к получившейся массе добавить рубленый шоколад, ванилин, затем всыпать разрыхлитель с мукой, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7190,'Смазать противень маслом, вылить на него полученное тесто небольшими кружками – примерно в 5 см диаметром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7190,'Быстрые шоколадные печенья в духовке выпекаются при 190 градусах в течение 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7191,'Залить дрожжи 3/4 стакана теплого молока, насыпать 3/4 стакана муки, размешать, отставить минут на тридцать. Соединить оставшееся молоко, желтки, соль, сахар, ваниль, тесто, перемешать до однородности, досыпать 1/2 стакана муки, размешать. Положить масло, перемешивать, пока все масло не впитается.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7191,'Постепенно, перемешивая, досыпать оставшуюся муку, тесто должно начать отходить от стенок. Оно должно в результате получиться однородным, гладким, чуть-чуть липким, мягким и влажным. Накрыть пленкой, отправить в холодильник минимум на два часа. Раскатать тесто на столе, посыпанном мукой, должен получиться пласт толщиной шесть миллиметров, вырезать круги при помощи стакана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7191,'На середину круга положить по квадратику шоколада и по несколько кусочков маршмеллоу. Накрыть сверху кружочками, чуть-чуть прижать краешки, предварительно края можно намазать молоком, лучше липло тесто. При помощи того же стакана вырезать круги, чтобы защипнулись краешки. Оставить минут на 10-15.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7191,'Жарить пончики «Восторг» с шоколадным кремом в большом количестве горячего масла со всех сторон на среднем огне, пока они не станут золотистыми. Посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7192,'Чтобы приготовить песочное тесто, сложить все ингредиенты, кроме муки, в большую емкость, взбить до однородности (все ингредиенты должны быть комнатной температуры). Насыпать муку, замесить мягкое тесто. Разделить тесто на четыре части, раскатать на специальной бумаге, чтобы можно было вырезать квадраты 18 на 18 сантиметров. Все раскатанные части положить минут на пятнадцать в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7192,'Отправить коржи (по очереди) в духовку, выпекать минут по двенадцать при температуре 200 градусов. Дать остыть, не снимая бумаги. Один корж, который будет наверху, заглазировать помадой. Помаду растопить, насыпать какао, размешать. Вылить на холодный коржик, размазать. Приготовить крем, для этого предварительно сделать и остудить сироп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7192,'Чтобы сделать крем, соединить молоко и желток, процедить, насыпать сахар, довести до кипения на маленьком огне, уваривать пару минут до загустения, сироп должен быть похож на сгущенное молоко. Остудить, время от времени размешивая. Взбить масло, насыпать ванильный сахар, медленно добавить сироп, хорошенько взбить. Налить коньяк.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7192,'Две ложки крема отложить в корнетик с красивой насадкой, в остальной крем насыпать какао, взбить. Разделить крем на четыре части. Собрать тортик, намазывая каждый коржик кремом. Последним положить заглазированный пласт. По бокам намазать кремом, посыпать крошкой, украсить орешками, былым кремом, буше, шоколадом. Отправить песочный торт «Ленинградский»  в холодильник на несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Варить, постоянно помешивая, до тех пор, пока масса не загустеет и не станет похожа на густую сметану, затем снять сотейник с огня и дать крему остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7193,'Отделить желтки от белков. Белки взбивать минут пять. Насыпать сахар, взбивать еще минут десять. Добавить желтки, вновь взбить. Насыпать муку с разрыхлителем. Размешать до однородности. Перелить тесто в разъемную формочку, застеленную специальной бумагой. Готовить бисквит минут пятьдесят, соблюдая температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7193,'Приготовить крем: обжарить на сухой сковороде помытый арахис, очистить от шелухи. Поломать на куски крекер. Хорошенько взбить масло со сгущенным молоком. Добавить крекер и арахис. Размешать. Бисквит должен неплохо подняться. Остудить бисквит, разрезать на две части. Нижний коржик смазать кремом, накрыть вторым коржом, отправить торт «Сникерс» в холодильник, чтобы крем чуть-чуть застыл.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7193,'По желанию украсить. Например, покрыть шоколадом: растопить молочный шоколад, соединить с молоком, покрыть тортик полностью. Можно посыпать какао или стружкой шоколада. Можно выложить снежинку из сникерса, порезанного на тоненькие дольки, бока посыпать миндальными орешками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7194,'Взбить при помощи блендера до однородности майонез, авокадо, порезанный на маленькие кусочки, лимонный сок, прессованный чеснок, посыпать перцем, солью. Налить  чуть-чуть оливкового масла, чтобы была достигнута желаемая кондиция, размешать заправку для цезаря.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7195,'Мясо залить холодной водой, готовить часа два, пока не станет мягким, посыпать перцем, солью. Измельчить мясо в блендере. Соединить в большой посуде молоко, муку, яйца.  Насыпать сахар, соль. Размешать до однородности. Добавить в тесто растительное масло, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7195,'Пожарить тоненькие блинчики без масла с одной стороны, сложить в стопку вверх жареной стороной. Порезать лук на 1/4 кольца, обжарить на среднем огне до золотистого цвета. Переложить обжаренный лук в фарш, размешать. Положить по большой ложке начинки на каждый блинчик, свернуть поджаренной стороной внутрь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7195,'Блины в свернутом виде обжарить со всех сторон перед подачей. Или посыпать потертым сыром, отправить на пару минут в духовку, чтобы расплавился сырок. Подавать традиционные блинчики с говядиной со сметанкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7196,'Отварить куриные грудки, остудить, порезать. Соединить и размешать до однородности яйца, муку, соус Ранч, молоко. Порезать кинзу, потереть сыр. Соединить мясо, сыр, яично-молочную смесь, муку и часть зелени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7196,'Смесь выливать не всю — представить, что это заправка для салата. Оставшуюся смесь использовать позже. Остальная кинза тоже пригодится. Посыпать чуть-чуть мукой формочку для запекания. Выложить курицу при помощи ложки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7196,'Добавить остальную яично-молочную смесь и муку. Готовить минут двадцать, соблюдая температуру 180 градусов. Готовые куриные маффины с сыром посыпать остальной кинзой. Охладить и подавать. Можно неплохо дополнить сальсой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7197,'Сделать блины: взбить в кухонном комбайне яйца с солью и сахаром. Добавить ваниль, жидкие продукты, потом сухие. Взбивать минуты две до однородной жидкой смеси. Пожарить блины на горячей сковороде. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7197,'Приготовить крем: взбить сливки, добавить маскарпоне, хорошенько размешать. Сделать ганаш: довести до кипения сливки, залить ими измельченный шоколад. Размешивать, пока шоколад полностью не растворится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7197,'Собрать тортик: взять блинчик, намазать кремом, накрыть вторым блином, намазать сгущенным молоком и так дальше: крем, сгущенное молоко, ганаш, сгущенное молоко до верхнего слоя. Покрыть верхний слой кремом, посыпать стружкой шоколада. Отправить 30-слойный блинный торт в холодильник часа на четыре для пропитки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7198,'Сделать кокосово-творожные шарики. Творог перетереть через ситечко, перемешать со стружкой кокоса, положить желток. Хорошенько перемешать массу. Скатать небольшие шарики, диаметром приблизительно два сантиметра, разложить на дощечке, отправить на тридцать минут в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7198,'Приготовить тесто: смешать в посуде мягкое сливочное масло и сметану до однородности. Вбить яйца, насыпать сахар, хорошенько размешать, медленно влить молоко, продолжая перемешивать массу. Насыпать муку, соединенную с разрыхлителем. Тесто перемешать и разлить поровну в две емкости.  В одну из емкостей насыпать какао-порошок, снова размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Тщательно вымыть внутри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7198,'Вылить тесто без какао в формочку, смазанную предварительно сливочным маслом. На него вылить тесто с какао. На него выложить кокосово-творожные шарики, чуть-чуть придавливая, чтобы на 1/2 часть они погрузились в тесто. Отправить формочку с тестом в духовку минут на сорок, готовить пляцок, соблюдая температуру 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7198,'Приготовить крем: соединить муку и сахар, налить в смесь холодное молоко. Поставить посуду на маленький огонь, довести до загустения, не переставая помешивать. В конце положить сливочное масло. Полить пляцок «Нежность» охлажденным кремом и можно подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'Взбить миксером, не спеша всыпая сахар, яичные белки, за раз добавить по одному желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'После желтков добавить муку и аккуратно перемешать массу лопаткой, затем добавить джем и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'В застеленную пекарской бумагой форму вылить тесто ровным слоем, отправить на 10 минут в разогретую до 180 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'Готовый и полностью остывший корж порезать на квадратики размером 1х1 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'В чаше блендера взбить сливочное масло, растопленный шоколад и сахарную пудру, после добавить ром и молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'Далее на минимальной скорости продолжить взбивать до однородности, затем добавить подготовленные квадратики, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'Из получившейся массы сформировать рулет, обвернуть его пищевой пленкой, положить на ночь в морозилку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7199,'После того, как шоколадный рулет в глазури с ромом полежит в морозилке в течение ночи, его нужно залить глазурью из смешанного растопленного шоколада с маслом, дать глазури застыть и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7200,'Все соединить, взбивать не нужно. В конце налить кипяток (с плиты). Размешать, получится очень жидкое тесто, перелить сразу в чашу мультиварки, смазанную сливочным маслом. Готовить в режиме «Выпечка» минут шестьдесят.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7200,'Тесто должно подняться под самую крышку мультиварки, разрезать на четыре коржика. Сделать любой крем, например, шоколадный: растопить четыре плитки шоколада, соединить с жирной сметаной. Смазать коржи кремом и подавать шоколадный бисквит к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7201,'Поджарить лучок и морковку. Положить мясо, порезанное на средние кусочки, посыпать перцем, солью. Чуть-чуть обжарить, залить водой, тушить до готовности, подливать при необходимости водичку. Во время готовки мяса приготовить нудли. В посуду налить кефир, насыпать соль, соду, перемешать. Медленно насыпать муку, перемешать. Тесто должно быть тугое, отставить его в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7201,'Отдельно поджарить картофель, если картофель среднего размера, то разрезать его на четыре части. Жарить до готовности. Когда мясо будет готово, положить к нему картофель, долить воду, чтобы она покрывала картофель. Чтобы приготовить нудли, раскатать тоненько тесто, намазать растительным маслом, выдавить чесночок, размазать по тесту, посыпать измельченным укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7201,'Свернуть рулетик, порезать на кусочек по 1,5 сантиметра шириной. Когда картофель приготовится, положить сверху нудли по-украински, если необходимо, подлить воду и посолить. Накрыть крышкой, тушить минут пятнадцать на слабом огне. Нудли станут больше. Посыпать петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7202,'Вскипятить молоко и сливки, варить минуты три. Насыпать сахарную пудру, перемешать, снять с огня. Растопить шоколад на водяной бане, он должен стать жидким. Перелить шоколад в молочную смесь, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7202,'В отдельной емкости соединить 50 миллилитров сливочную смесь и желатин. Дать желатину разбухнуть, перелить в основную смесь сливок и шоколада. Перемешать, охладить, разлить по формочкам, отправить в холод, чтобы шоколадная паннакота застыла. Украсить по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7203,'Залить курагу горячей водой, промыть, слить воду, посушить курагу с помощью полотенца. Освободить филе курицы от маленьких боковых филешек, завернуть в пленку, отбить молоточком, чтобы получился тоненький слой. Чуть-чуть посыпать солью филе, разложить на мясе горький перец чили, курагу, шалфей, свернуть в рулетики, отложить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7233,'Положить ломтики имбиря в сироп. Варить на большом огне, пока имбирь не станет прозрачным и не вберет в себя сахар. Аккуратно обвалять имбирь в сахаре. Выложить цукаты из имбиря на бумагу подсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7203,'Положить на столе полиэтилен: несколько слоев внахлест, и еще слой посередине для прочности. Каждый рулетик на краешек пленочки, по краям обложить оставшиеся маленькие филешки, свернуть рулеты в пленке, укатывать плотно. Краешки хорошо завязать, чтобы получились плотные колбаски. Переложить их в кастрюльку с толстым дном. Налить воду, чтобы она покрывала рулетики. Готовить минут 45. После застывания порезать рулетики с курагой на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7204,'Порезать только зеленую часть пекинской капусты не крупно. Курицу порезать на маленькие кубики. Крупно потереть сыр. Слить сок с ананасов, положить их в салатник. Добавить сухари. Размешать капустный салат с майонезом, посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7205,'Соединить творог, сахар, яйца, пряности, перемешать. Взять формочки в виде сердечек, положить в них приготовленную массу. Готовить минут двадцать, соблюдать температуру 180 градусов. Можно положить в сырники ягоды, порезанные фрукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7206,'Измельчить печенье, положить корицу, масло, размешать, чтобы получилась крошка, высыпать в формочку, застеленную фольгой или пергаментом. Утрамбовать равномерно по дну формочки, отправить в холодильник минут на двадцать. Приготовить начинку: залить желатин 1/4 стакана воды, минут на десять оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7206,'Поставить на водяную баню или тихий огонь, мешать, пока желатин не растворится. Взбить до гладкости сливочный сыр. Налить молоко, насыпать сахарную пудру. Поделить смесь на три части. В одну часть положить белый шоколад. Во вторую молочный шоколад, в третью темный шоколад. Во все части добавить по равной части желатина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7206,'Взбить сливки в пену, добавить по 1/3 в каждую часть. На основу вылить массу с белым шоколадом. Дать чуть-чуть застыть. Вылить сверху массу с молочным шоколадом, позволить чуть-чуть застыть. В конце вылить массу с темным шоколадом. Отправить в холодильник часа на три, чизкейк должен полностью застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7206,'Чтобы сделать шоколадные завитки, растопить шоколад, вылить на гладкую поверхность, позволить полностью застыть. Поставить на шоколад острый нож горизонтально. Нажимая равномерно на лезвие, тянуть нож на себя, размер стружки регулировать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7206,'Взбить сливки, вылить на тортик, украсить шоколадными завитками. Чтобы сделать шоколадное украшение, нарисовать узор на пергаменте, обвести растопленным шоколадом, позволить трехслойному чизкейку застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7207,'Разморозить тесто при комнатной температуре. Порезать на полосочки по два сантиметра. Порезать колбаску на тоненькие кружки, разрезать их пополам. На полоску, чуть-чуть внахлест, положить колбаски, конец оставлять свободным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7207,'Свернуть в рулетик. Конец подвернуть под низ «розочки». Положить на противень, застеленный бумагой, розочки, позволить подойти. Выпекать минут двадцать, соблюдая температуру, указанную на упаковке для теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7208,'Все ингредиенты порезать. Сложить так, чтобы они не сливались по цвету. Курицу обжарить на сильном огне, чтобы сверху была корочка, а внутри мясо было сочным. Можно положить в салатик бекон или ветчину. Соединить все ингредиенты для заправки, полить приготовленной заправкой кобб-салат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7209,'Потереть сыр, помыть зелень, обсушить и измельчить. Соединить сыр и порезанную зелень, положить в кастрюльку небольшого размера, поставить на водяную баню. Подогревать, не переставая помешивать, пока не расплавится сырок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7209,'Положить полученную сырную массу между несколькими слоями пленки, раскатать скалкой, чтобы получился тоненький пласт. Тонко порезать рыбку. Убрать верхнюю пленку, положить кусочки рыбы на пласт сыра, сформировать рулетик, отправить на тридцать минут в холодильник, убрать пленку, порезать закусочный рулет на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'Приготовить тесто для будущих блинов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'Для этого необходимо в молоке развести яйца, влить растопленное сливочное масло, медленно всыпать муку, соль и сахар, перемешать и испечь на горячей сковороде нужное количество блинов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'На отдельной сковороде обжарить лук, добавить к нему курицу, порезанную мелкими кусочками, посолить и чуть прожарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'Затем курицу залить сливками так чтобы они слегка покрыли мясо и потушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7210,'В центр каждого блина выложить готовую курино-луковую начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7211,'Соединить стакан манной крупы со стаканом кефира. Взбить яйца, насыпать сахар. Растопить маргарин или сливочное масло. Все соединить, насыпать муку и соду. Размешать. Получившееся тесто разделить на несколько частей. В часть поменьше насыпать какао. Переложить обе части в формочку и выпечь в духовке. Украсить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7212,'Подготовить ингредиенты. Просеять муку. Положить мягкое сливочное масло. Все порубить, чтобы получилась крошка. Желательно делать это руками, тогда крошка будет более однородной. Взбить при помощи вилки яйцо с солью, налить воду, чтобы получилось 250 миллилитров смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7212,'Смешать масляную крошку с яичной смесью. Замесить эластичное тесто, не липнущее к рукам. Накрыть полотенцем или полиэтиленом, отставить на тридцать минут. Оно будет еще эластичней. Поделить тесто приблизительно на двенадцать частей. Из каждой части скатать шарик, накрыть полотенцем. Брать по одному шарику и тоненько раскатывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7212,'На получившуюся лепешку положить шаблон круглой формы, к примеру, дно от формочки для выпечки. Вырезать. Сделать проколы вилкой. Обрезать лепешки можно после приготовления, чтобы корж не потерял форму. Тесто эластичное, раскатывается легко. Выпекать приблизительно четыре минуты, соблюдать температуру 200 градусов. Коржик должен приобрести коричневый оттенок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7212,'Во время готовки первого коржа раскатать другие, чтобы процесс был непрерывным. Приготовление коржей занимает минут сорок. В готовом виде коржики положить друг на друга. Приготовить крем: соединить яйца, муку, сахар. Взбить венчиком до однородности. Медленно налить теплое молоко, хорошенько вымешивать венчиком. Готовить крем на среднем огне, не переставая помешивать, чтобы не было комочков, и он не подгорел. Готовый густой крем убрать с огня, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7212,'Взбить мягкое сливочное масло, медленно добавить заварной крем, взбивать, чтобы крем полностью соединился с маслом. Намазать коржи кремом. Каждый раз прижимать корж к предыдущему. Украсить торт «Нежный Наполеон» по желанию. Можно посыпать тортик кокосовой стружкой, растопленным шоколадом или просто посыпать крошкой, измельчив один коржик.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7213,'Приготовить крем: взять кастрюльку с антипригарным покрытием, положить в нее все ингредиенты для крема, кроме масла. Готовить на тихом огне, помешивать, пока не станет густым. Охладить до комнатной температуры. Приготовить тесто: в кастрюле с антипригарным покрытием соединить все ингредиенты для теста, кроме муки. Готовить на маленьком огне минут пятнадцать, масса должна увеличиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7213,'Убрать с огня, положить какао. Размешать. Насыпать муку, размешать. Получится мягкое тесто. Минут через двадцать оно потвердеет. Поделить тесто на пять частей. Раскатать каждую часть в прямоугольники 20 на 25 сантиметров. Выпекать минут пять, соблюдая температуру 200 градусов. Время готовки зависит от духовки, возможно, необходимо будет готовить еще минуты три.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7213,'Взбить сливочное масло, положить небольшими порциями крем, взбить. Намазать четыре коржа кремом. Положить сверху пятый крем, на него вылить теплую шоколадную глазурь. Чтобы ее сделать, смешать шоколад с растительным маслом, растопить на водяной бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7213,'Оставить на ночь, чтобы пропитался. Чтобы срез был аккуратным, можно отправить торт «Спартак» на несколько часов в холодильник. Обрезать краешки острым ножом, порезать тортик в виде пирожных, нанести полосочки белым или молочным шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7214,'Поджарить окорочка, отделить от косточек мясо. Отварить морковь и яйца. Выложить салат слоями: мясо, перемешенное с майонезом, на него потертую морковь, намазать майонезом, выложить слой порезанных шампиньонов, намазать майонезом, потом измельченный лук и потертые яйца, намазать майонезом, дальше слой мелко потертого сыра, майонезом не мазать. Порезать на четыре части оливки, положить сверху. Посыпать верхний слой измельченным желтком. Украсить салат «Подсолнух» чипсами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7215,'Отварить в соленой воде язык. Затем переложить его в холодную воду, почистить от кожуры, порезать на тоненькие кружки. Порезать на небольшие кубики репчатый лучок, обжарить на масле. Помыть грибы, обсушить, порезать на тоненькие пластинки, положить к луку. Жарить, пока жидкость не испарится. Посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7215,'Соединить прессованный чеснок, измельченные орехи и лук, обжаренный с грибами. Выложить получившуюся массу на кусочки языка, сформировать рулетики. Положить их на противень, залить сметанкой, отправить на десять минут в духовку, соблюдать температуру 180 градусов. Положить закусочные рулеты из языка на тарелочку, украсить грецкими орешками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7216,'Соединить ингредиенты, варить минут десять на маленьком огне. Убрать с огня. В отдельной емкости смешать яйцо, любую сметану, насыпать сахар, перемешать, вылить на массу, снятую с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7216,'Положить измельченное печенье (удобно раздавливать его с помощью скалки). Положить все в пакет, придать форму колбаски, отправить колбаску «Минутка» в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7217,'Потереть капусту на терке. Почистить морковь и потереть на терке для корейской моркови. На ней же потереть соленые огурцы с кожурой (она после терке будет не жесткой). Порезать лук, ошпарить кипятком, слить воду минуты через три, так он останется хрустящим, а горечь исчезнет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7217,'Заправить огурцы, капусту, лук и морковь небольшим количеством майонеза. На лаваш положить половину начинки, заправить слегка майонезом (во время сворачивания рулета он равномерно растечется), посыпать солью. Свернуть рулетик. В принципе его можно резать и кушать, но есть вариант значительно лучше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7217,'Разогреть на большом огне с растительным маслом сковороду, положить рулетики вниз швом. Обжаривать хрустящую закуску с каждой стороны по несколько минут на большом пламени. Лаваш станет аппетитным на вид и замечательным на вкус. Начинка не успеет потушиться и будет хрустящей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7218,'Порезать капусту на тоненькую соломку, ошпарить, налить молоко, тушить минут тридцать. Обжарить фарш, морковь, лук, измельченный чесночок, посыпать перцем, солью. Взбить яйца, несколько столовых ложек майонеза и муки, в получившуюся смесь положить остывшую капусту, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7218,'В специальную формочку положить половину яично-капустной смеси, после этого разложить фарш, на него положить остальную капусту. Намазать соусом (смесь кетчупа и сметаны). Готовить капустную запеканку с мясом минут тридцать при средней температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7219,'Превратить печенье в крошку, используя блендер. Растопить масло, остудить, положить к печенью. Замесить тесто, оно будет мокрое и рассыпчатое. Формочку для выпечки застелить пищевой пленкой. На нее положить тесто, равномерно распределить по поверхности, хорошенько придавить. Отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7219,'Развести, как написано в инструкции, пакетированное желе, залить в емкость, напоминающую по форме формочку для выпекания, но ниже и меньшего объема. Отправить в холодильник для застывания. Спустя некоторое время положить киви, порезанное на дольки. Но есть одно но. Если ананас и киви положить в желе в свежем виде, то они способны нейтрализовать действие желатина. Поэтому если оно не застывает, то необходимо растопить на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7219,'В это время развести в горячей воде еще желатин, перелить в сироп с киви. Снова отправить в холодильник. Желе должно застыть приблизительно через четыре часа. Подержать емкость чуть-чуть в горячей воде, чтобы желе без труда отошло от посуды. Сверху накрыть формочкой для торта, перевернуть, так оно окажется посередине. Довести молоко практически до кипения, вылить его на желатин. Как можно лучше размешать до полного растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7219,'Взбивать с помощью миксера сахар и сметану, пока полностью не растворится сахар. Во время взбивания добавить ваниль. В процессе приготовления пробовать крем, он должен быть сладким на вкус, потому что позже необходимо долить пресное молоко. Не переставая взбивать, тоненькой струей влить молоко, смешенное с желатином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7219,'Если все сделать правильно, то комочки не появятся, и желатин не схватится быстро от холодной сметанки. Данную смесь аккуратно вылить в свободное место в формочке, отправить минут на шестьдесят в холодильник. Этого времени вполне должно хватить, чтобы желатин схватился. Осторожно снять бортики и пленочку. Готовый торт-желе из сметаны и киви будет приблизительно весить 2,5-3 килограмма.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'Разрезать на кусочки отварную куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7220,'На сковороде обжарить порезанный лук, затем его убрать и обжарить также порезанные шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7221,'Почистить и порезать на полукольца лук. Порезать мясо на ломтики по 1 сантиметру в ширину. Отбить кусочки кухонным  молотком. Посыпать перцем, солью. На всех кусочках сделать несколько разрезов по вертикали, чуть-чуть отступив от верха. Сделать косичку, краешки сколоть зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7221,'Положить лук в посуду, помять его слегка руками, чтобы выделился сок. Положить косички, выдавить лимонный сок, добавить горчицу. Как можно лучше размешать руками. Мариновать минут 40-60. Обвалять косички со всех сторон в муке. Разогреть растительное масло на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7221,'Положить мясо, готовить на сильном огне минуты три. Перевернуть косички на другую сторону, обжаривать еще минуты три. Сделать огонь меньше, готовить пару минут, пока мясо полностью не будет готово. Убрать зубочистки, подавать мясные косички из свинины в горячем виде с любым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7222,'Порезать филе на средние кусочки. Измельчить имбирь, чесночок, лук. В сотейник налить несколько больших ложек растительного масла, разогреть на сильном огне. В несколько заходов обжарить мясо до образования румяной корочки, готовить по три минуты. Переложить курицу в тарелочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7222,'Сделать огонь тише, положить лук, готовить минут пять, помешивая. Положить чесночок, имбирь, приправы, готовить секунд шестьдесят, помешивая. Положить в сотейник рис, размешать так, чтобы каждое зернышко риса было покрыто маслом. Жарить секунд шестьдесят. Налить бульон или воду, посыпать солью по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7222,'Довести до кипения, сделать огонь минимальным, готовить, накрыв крышкой, пока не приготовится рис, жидкость должна впитаться, на это уйдет минут 25 (время зависит от сорта используемого риса). Минут за семь до готовности переложить в сотейник обжаренное филе, размешать курицу с рисом и карри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7223,'Взбить яйцо и сахар, насыпать муку, влить молоко. Поставить на огонь, готовить, не переставая мешать, пока смесь не загустеет. Приготовленный крем процедить, охладить, положить сливочное масло. Все вместе взбить. Все коржики намазать кремом. На тортик положить киви и консервированную вишню. Краешки фруктово-кокосового тортика посыпать стружкой кокоса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7224,'Вариант первый: пропустить через мясорубку мясо курицы. Измельчить чесночок, положить его в приготовленный фарш. Добавить в фарш яичные белки, сливки, приправы, как можно лучше вымесить до однородности. Переложить получившийся фарш в фольгу, плотно завернуть, кончики закрутить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7224,'Фольгу завернуть в несколько слоев пищевой пленочки, кончики завернуть ниткой, чтобы не вытекала вода. Положить в кастрюльку с водой, таким образом, чтобы колбаска была погружена в воду, готовить минут сорок. Достать из воды, охладить. Отправить куриную колбаску на ночь в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7224,'Вариант второй: начинить кишки. Кончики связать ниткой. В получившейся колбаске сделать два-три прокола тоненькой иголкой. Довести воду до кипения, подсолить. Варить куриную колбаску на маленьком огне. Охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7225,'Порезать язык на ломтики, положить на тарелочку, намазать майонезом, сверху разложить по кружку вареного яйца, намазать майонезом, разложить помидоры, разложенные на кружочки. Сверху язык по-королевски посыпать тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7226,'Перемешать ингредиенты, вылить в сковороду или формочку, готовить в духовке до румяного оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7227,'Приготовить рассол: налить литр воды, насыпать специи и соль, поставить на огонь, довести до кипения. Убрать с огня, полностью остудить. Взять шприц, обколоть мясо рассолом по всей поверхности. Это поможет мясу равномерно просолиться. Переложить обколотое мясо в посуду, залить рассолом, который остался, придавить гнетом, поставить на трое суток в холодное место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7227,'Один раз в сутки переворачивать мясо, чтобы оно просолилось, как можно равномерней, и сохранился равномерный цвет. Просоленную ветчину свернуть, как можно плотней, и обвязать шпагатом или туго завернуть в стрейч-пленку. После этого начинается процесс варки. Этот процесс считается самым сложным, потому что он требует периодического контроля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7234,'Порезать сыр на ломтики, ветчину порезать на тоненькие слайсы. Разрезать куриную грудку на три части. Каждый отбить кулинарным молоточком. Подсолить. На каждый кусочек мяса положить по два слайса ветчины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7227,'Воду нагреть до 85 градусов, опустить в нее ветчину. Сделать огонь тише, варить часа два, при этом контролировать, чтобы температура воды не поднималась выше 80 градусов. В результате получится красивая и сочная ветчина. Чтобы измерять температуру, желательно использовать кулинарный градусник. Достать приготовленную ветчину, обмакнуть сначала в горячую воду, затем в холодную.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7227,'Остудить и отправить в холодильник на ночь, чтобы в ветчине разошлась соль и соки. Если отрезать кусок от ветчины в теплом виде, то может показаться, что она пересоленная, однако, утром, когда ветчина пропитается, вкус будет совершенно другой. Хранить ветчину домашнюю из свиного окорока можно в холодильнике около четырех дней, потому что, кроме соли, в ней не содержатся других консервантов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7228,'С помощью миксера взбить яйцо, сахар и масло. Соединить муку с содой и солью, высыпать в яичную смесь. Вымешать тесто. Поломать шоколад на маленькие кусочки, положить в тесто, снова размешать. Намочить руки и сформировать шарики, приплюснуть их при помощи вилки. Готовить печенье с шоколадом минут пятнадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7229,'Намазать формочку растительным маслом, на дно положить мясо, порезанное на кусочки. Соединить пряности и соль, посыпать мясо. Обжарить на сковороде порезанный лучок до золотистого оттенка. Туда же положить грибы. Обжаривать вместе с луком. Переложить обжаренные грибы и лук на мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7229,'Сверху разложить картофель, порезанный на полукольца, посыпать пряностями и солью. Отдельно соединить сладкий перец, порезанный на кубики, натертую морковь, прессованный чесночок, порезанный острый перец, майонез. Положить массу в формочку на картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7229,'Посыпать тертым сыром. Накрыть формочку фольгой, отправить на шестьдесят минут в духовку, соблюдать температуру 200 градусов. Убрать фольгу, готовить запеченное мясо с овощами и грибами в духовке еще минут пятнадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'Кусками толщиной не больше 2 см нарезать говяжье филе или вырезку поперек волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'Измельчить очищенный чеснок, тонкими кольцами порезать лук, из перца извлечь семена и нарезать его полосками, очень тонкими дольками порезать помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'На сильно разогретую сухую сковороду выложить мясо, чуть смазанное растительным маслом со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'Обжарить мясо с каждой стороны в течение 4 минут на большом огне, посолить и поперчить, после чего переложить на чистую тарелку и убрать в теплое место или духовку, разогретую до 50 градусов, чтобы оно не остыло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'В сковороде, где жарилось мясо, обжарить до мягкости на среднем огне подготовленный чеснок, перец и лук в районе 7-10 минут, затем нужно добавить дольки помидоров, потушить не больше 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7230,'Готовые овощи выложить на мясо, мексиканский бифштекс с овощами украсить зеленью и подать горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7231,'Взбить чуть-чуть яйца и сахар. Положить кокосовую стружку, размешать до однородности. Из массы сделать шарики среднего размера, выжить на противень, застеленный пергаментом.  Готовить печенье «Кокосанка» в разогретой духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7232,'Промыть картофель, почистить, разрезать на четыре части, разложить на противень. Чуть-чуть посыпать солью. Поделить куриные бедрышки на две части. Это можно легко сделать при помощи острого ножа, только важно попасть в сустав. Если гостей будет немного или совсем не будет, то можно бедрышки не разрезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7232,'Посыпать мясо перцем, солью, выложить на картофель. Духовку разогреть, поставить противень с мясом и картофелем. Держать в духовке, пока картофель не приготовится. Во время готовки из куриных бедрышек вытопится жирок, стечет на дно и картофель им пропитается.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7233,'Почистить имбирь от кожицы. Порезать на длинные или круглые ломтики. Залить водой (она должна полностью покрывать имбирь), готовить минут пятьдесят, имбирь должен стать мягким и несильно жгучим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7233,'Приготовить сироп: растворить сахар в 1/2 стакана воды, довести до кипения. Откинуть отваренный имбирь на дуршлаг, позволить жидкости стечь. Можно применять отвар в приготовлении имбирного чая. Только необходимо быть осторожным, так как он весьма жгучий. Разбавлять следует один к одному.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Все коржи, кроме одного, промазать получившимся кремом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7234,'Положить рулеты. Обжаривать до золотистого оттенка со всех сторон. Вылить в сковороду сливки. Выдавить чесночок. Посыпать перцем, зеленью. Тушить рулетики «Кордон Блю» на маленьком огне, пока сливок не станет в два раза меньше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7235,'Отварить свеклу и морковь. Остудить, почистить. Отварить яйца, остудить, почистить. Положить отдельно желтки и белки. Мелко потереть сыр, поделить пополам. Мелко натереть в отдельные емкости морковь, свеклу, так же отдельно соединить с порциями сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7235,'К свекле положить йогурт, тертый желток. К моркови – прессованный чесночок, йогурт, тертый белок. Сделать шарики из свекольной смеси, внутрь каждого шарика закатать по кусочку грецкого ореха или чернослива. То же самое сделать из морковной смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7235,'Если массы получились не очень влажные, и шарики плохо формируются, то положить еще чуть-чуть йогурта. Переложить получившиеся шарики на плоскую тарелочку, украсить йогуртом и зеленью. Отправить овощные шарики минут на тридцать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7236,'Мягкое сливочное масло растереть с сахаром, разрыхлителем, желтком, гашеной содой. Медленно ввести муку, чтобы тесто получилось песочное и мягкое. Переложить в формочку, намазанную маслом и посыпанную мукой. Диаметр формочки должен составлять 20-25 сантиметров, распределить равномерно по дну, слегка заступать на бортики, отправить минут на тридцать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7236,'Выложить на тесто слой фруктов. На них положить творожную начинку. Чтобы приготовить творожную начинку, растереть творог, сахар, цедру лимона, яйца, ваниль, крахмал до кремообразного состояния. Сделать кудряшки: соединить стружку, сахар, масло, посыпать пирог. Выпекать пирог «Кудряшкин» минут шестьдесят, соблюдать температуру 180 градусов, накрыв фольгой. Через сорок минут, после начала готовки, фольгу убрать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7237,'Нагреть заранее духовку до 180 градусов. Использовать формочку для торта диаметром двадцать сантиметров. Просеять муку с солью в посуду большого размера. Насыпать сахар. Положить масло, втереть его осторожно пальцами в смесь, чтобы она была похожа на маленькие хлебные крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7237,'Соединить молоко и сметану. Добавить остальные ингредиенты, размешать до однородности. Смазать формочку маслом, посыпать мукой. Перелить в нее массу. Разровнять поверхность ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7237,'Выпекать минут шестьдесят до готовности. Достать из духовки, позволить формочке остыть, переложить на решетку до полного остывания. Хранить ливанский пирог изюмом с финиками в посуде, плотно закрывающейся.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7238,'Соединить в посуде теплое молоко, дрожжи и сахар, накрыть крышкой, отставить на десять минут. В емкость миксера насыпать муку, обычный и ванильный сахар, соль, перемешать. Налить молочно-дрожжевую смесь. Размешать. Положить белки, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7238,'Добавить масло, порезанное на кусочки. Месить на первой скорости минут пять, затем на второй скорости минут десять. Накрыть салфеткой, положить в теплое место, чтобы тесто увеличилось в несколько раз. Поделить тесто на две-три части. Раскатать на столе, присыпанном мукой. Вырезать круги диаметром приблизительно восемь сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7238,'Соединить три круга вместе, скатать плотно вместе. В центре разрезать ножом, получится два цветочка. Поставить их в формочку. Накрыть крышкой, отставить минут на 45. Разогреть духовку до 180 градусов. Готовить минут 25. Когда пирог из булочек «Букет роз» будет готов, посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7239,'Порезать помидоры, куриную грудку, тыкву на кубики. В посуду вбить яйца, размешать. Потереть сыр, чесночок порезать на ломтики. Положить в формочку тыкву и помидоры. Сверху положить куриное филе, порезанное на кусочки. Чуть-чуть уплотнить, залить яйцами. Положить на них ломтики чесночка, посыпать зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7239,'Посыпать базиликом или какой-либо другой приправой. Положить слой тыквы и помидор, можно положить курицу. Посыпать все сыром. Отправить в духовку минут на пятьдесят. Готовить запеканку с курицей и тыквой при 210 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Отварить рис (круглый-непропаренный), лучше до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Выложить на пласты говядины начинку, свернуть рулетом, перевязать нитками или скрепить зубочистками, переложить зразы в сотейник с подогретым маслом и отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Прокрутить лук и фарш через мясорубку, положить рис, посыпать солью. Можно лук просто измельчить и заранее обжарить до прозрачного состояния. После этого соединить с рисом и фаршем. Посыпать солью. Помять смесь руками. Сделать тефтели небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Обвалять в муке. Положить сковороду с горячим растительным маслом, на некотором расстоянии друг от друга. Обжаривать минуты три с одной стороны. Сразу не накрывать крышкой, чтобы тефтельки не развалились. Осторожно перевернуть, обжарить со второй стороны минуты три, тефтели должны схватиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Залить стаканом кипятка приблизительно до половины уровня тефтелек. Добавить чуть-чуть соли, томатную пасту, разведенную водой, лавровый листик. Накрыть крышкой, готовить тефтельки в подливке 10-15 минут на небольшом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Развести сметану в половине стакана теплой воды, добавить 1 ст.л. муки, хорошо размешать, вылить в тефтели. Закрыть крышкой и хорошенько встряхнуть, чтобы перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7240,'Тушить 15-20 минут на слабом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7241,'Потереть на терке яблоко, чернослив нарезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7241,'Смешать творог, яблоко, йогурт и чернослив, массу посыпать корицей и ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7241,'Емкость с творожной массой отправить в микроволновку и запекать 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7241,'Готовая творожная запеканка с яблоками в микроволновке за 5 минут должна полностью остыть и пропитаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7242,'Поставить казан на огонь. В это время почистить картофель (одна должна быть по размеру приблизительно с куриное яйцо). Если картофель большой, то разрезать его на одинаковые кусочки. Когда нагреется казан, налить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7242,'Порезать мясо на куски по три-пять сантиметров. С нескольких кусков срезать пленки и жирок. Это важная часть. Когда разогреется масло, положить срезанный жир, позволить накалиться. Если мясо было с косточкой, то положить косточку. Можно бросить пару кусков мяса. Достать поджарки, отложить в сторону, в казан положить подготовленный картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7242,'Время от времени переворачивать. В конце подсолить. Переложить готовый картофель в посуду, накрыть крышкой, чтобы не остыла, отставить в сторону. Положить в масло порезанное мясо, обжарить. Положить лук, порезанный на полукольца. Затем положить морковь, порезанную на брусочки по шесть миллиметров в толщину. Готовить минут пять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7242,'Добавить капусту, порезанную соломкой или кубиками. Подержать казан минут десять с открытой крышкой до полумягкого состояния капусты. Налить стакан воды, накрыть крышкой. Через пятнадцать минут поднять крышку, проверить готовность.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7242,'Если практически готово, то положить томатную пасту или помидоры, почищенные от кожуры, размешать, положить поджаренный картофель, аккуратно размешать, накрыть крышкой, готовить минут пять на тихом огне. Проверить овощное рагу в казане на соль, посыпать порезанным чесночком, зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7243,'Растереть творог и сахар, вбить яйца. Просеять в массу смесь просеянной муки, разрыхлителя, ванилина. Налить в казан растительное масло, разогреть. Намочить руки, взять чуть-чуть теста, скатать шарики диаметром по три сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7243,'Положить шарики в горячее масло, обжаривать, пока пончики не всплывут и не станут коричневого оттенка. Вынимать пончики шумовкой. Убавить огонь, остальные пончики жарить на тихом огне. Пончики выкладывать на пергамент, чтобы лишнее масло стекло. Посыпать творожные пончики сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7244,'Сварить кофе, насыпать по вкусу сахар, размешать, налить свежевыжатый грейпфрутовый сок. Посыпать кофейный напиток натертым шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7245,'Положить в фарш хлеб, замоченный в молоке и мелко порезанный лук. Посыпать перцем, солью, перемешать. Натереть сыр и яйца для начинки. Сделать кляр: взбить яйца и майонез, насыпать муку, соду, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7245,'Из приготовленного фарша сформировать лепешку, положить на нее начинку и небольшой кусок сливочного масла. Слепить котлетку. Обмакивать котлетки «Птичье молоко» в кляр, обжаривать на растительном масле со всех сторон до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7461,'Торт Наполеон с коньяком украсить сверху отложенным и покрошенным коржом и можно подавать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7246,'Растворить в воде дрожжи, отставить минут на пять, чтобы пошла реакция. Отдельно взбить яйца. Не переставая взбивать на маленькой скорости, насыпать соль и сахар. Растопить в кастрюльке сливочное масло, когда оно начнет пениться, налить молоко и выключить огонь. Позволить смеси чуть-чуть остыть, чтобы не свернулись яйца. Перелить масляную смесь в яичную. Взбить, добавить дрожжи, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7246,'Насыпать по стакану муки, после каждого стакана перемешивать на маленькой скорости. После четвертого стакана муки взбивать минут пять, после этого проверить, хватает ли в тесте муки. Если тесто с легкостью отходит от стенок, то муку больше не добавлять. Если отходит плохо, то насыпать еще стакан муки (не больше). Накрыть тесто пленкой, отправить часа на четыре в холодильник (можно на ночь). Когда тесто увеличится в два раза, достать его их холодильника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7246,'Приготовить апельсиновую глазурь: растопить масло, вылить его в емкость с сахаром. Добавить сок и цедру апельсина. Размешать. Получится достаточно густая глазурь. Переложить тесто на поверхность, присыпанную мукой. Раскатать, намазать глазурью, не доходить до краев коржа на несколько сантиметров. Осторожно завернуть корж с начинкой в виде ролла. Кисточкой смахнуть прилипшую муку. Разрезать ролл на 24 одинаковые части. Для этого разрезать ролл на две части, каждую часть пополам и так далее, пока не будет 24 части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7246,'Намазать маслом формочку для маффинов. Положить получившиеся булочки в формочку. Поставить ее на противень, застеленный пергаментом, чтобы вытекшая глазурь не причинила вред духовке. Поставить булочки в тепло, чтобы они поднялись раза в два. После этого отправить на пятнадцать минут в духовку, соблюдать температуру 190 градусов. Переместить апельсиновые булочки остывать на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7247,'Предварительно распечатать записки с высказываниями и порезать на тоненькие полоски. Взбить белки и сахар, влить растопленное масло, насыпать муку, взбить с помощью миксера. Тесто должно быть жидковатое. На противень постелить пергаментную бумагу, разогреть духовку до 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7247,'Зачерпнуть маленькой ложкой тесто, положить на противень, осторожно круговыми движениями выпуклой стороной ложечки распределить тесто, чтобы получился тоненький блин приблизительно 12 сантиметров диаметром. Отправить в духовку, готовить приблизительно восемь минут, краешки печенья должны стать коричневатого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7247,'Достать печенье, осторожно, помогая лопаткой, отделить от бумаги, в центр положить записку с предсказанием, свернуть печенье пополам, сгиб печенья положить на краешек стакана, согнуть пополам. Чтобы печенье не распалось, поставить его на тридцать секунд в рюмочку.  Так не нужно постоянно держать китайское печенье и ждать его застывания, форма зафиксируется в рюмке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'Очищенный картофель очень тонко порезать, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'Лук очистить и измельчить, нарезать помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'На среднем огне в сковороде разогреть оливковое масло, обжарить в нем не более 5 минут картофель, при этом все время помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'Затем положить лук, интенсивно перемешать, сковороду закрыть крышкой, уменьшить  огонь, готовить периодически помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'В небольшой мисочке вилкой взбить яйца с перцем и солью, в получившуюся смесь добавить обжаренные овощи, горошек и помидоры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'В районе минуты прогреть на сковородке оставшееся оливковое масло, затем влить яично-овощную смесь и готовить 15 минут на самом маленьком огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'После того как испарится практически вся жидкость, необходимо омлет перевернуть на другую сторону и продолжить готовить в течение 5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7248,'Омлет «Тортилья» с картофелем по-испански подается в горячем виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7249,'Порезать мясо на средние кусочки. Порезать лук на кольца или полукольца. Замариновать мясо с луком, посыпать перцем, солью, добавить по вкусу уксус. Выдавить 1/3 лимона, размешать руками. Отправить мясо часа на три в холодильник. Налить на горячую сковороду оливковое масло, готовить свинину по-мужски минут двадцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7462,'С помощью блендера взбить до однородности нарезанный замороженный банан, очищенное и порезанное манго, лед, кокосовое молоко, ананас и коровье молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7250,'Нашинковать мелко капусту, посыпать солью, подавить, чтобы появился сок, потереть морковь, измельчить укроп, с кукурузы слить сок. Приготовить заправку: выдавить чесночок в оливковое масло, налить чуть-чуть уксуса или сока лимона. Соединить ингредиенты, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7251,'На приготовление вкусного десерта уходит минут десять. Поломать шоколадку на куски, растопить в микроволновой печи. Кукурузные хлопья руками размять, чтобы получились очень мелкие хрустящие кусочки. Соединить измельченные хлопья и изюм. Растаявший шоколад с помощью ложки превратить в однородную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7251,'В посуду с шоколадом пересыпать смесь изюма с хлопьями, осторожно размешать. Постелить на блюдо фольгу, с помощью маленькой ложки выложить небольшие шоколадные горочки. Удобно использовать несколько ложек, одной зачерпывать смесь, второй сдвигать с ложки на блюдо. Поставить шоколадные хрустелки с изюмом в холодильник минут на десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7252,'На приготовление салата уходит минут десять. Соединить ингредиенты, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7253,'Нагреть сливочное масло на сковороде. Обжаривать минут пять грибы и прессованный чеснок. Посыпать перцем, солью, готовить, пока грибочки не выпустят сок и не станут коричневыми. Снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7253,'Остудить, соединить с рикоттой. Чуть-чуть взбить яйца, обжаривать омлет минуты по три с каждой стороны на сливочном масле. Чуть-чуть остудить, на один край положить начинку, скрутить рулет из омлета с грибами и сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7254,'Потереть на терке лук, положить в фарш, посыпать перцем, солью, добавить яйцо, перемешать. Почистить картофель, мелко натереть, посыпать перцем, солью, положить сметанку, яйцо и муку, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7254,'Выложить ложкой на сковороду с разогретым маслом, на картофельную массу положить лепешку из мясной смеси, сверху опять картофельную массу, обжаривать драники с мясным фаршем до золотистого цвета со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Подготовить ингредиенты. Приготовить корж: растопить сливочное масло. Измельчить печенье. Сделать это можно несколькими способами: сложить печенье в пакет, раскрошить скалкой или измельчить печенье в блендере. Второй способ наиболее удобный, легкий и качественный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Вылить в крошку из печенья масло. Можно использовать любое печенье: шоколадное, овсяное, бисквитное и так далее. Можно положить миндальную крошку или вообще заменить этой крошкой или мукой печенье. Размешать крошку и масло. Выложить массу на дно разъемной формочки диаметром 25 сантиметров. Примять равномерно сначала ложкой, затем плоским дном стакана. Отправить в холодильник, чтобы коржик застыл.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Приготовить сироп: растворить в воде на маленьком огне сахар. Когда он растворится, сделать огонь больше, довести сироп до кипения. Кипятить секунд шестьдесят. Снять с огня. Взбить желтки. Не переставая взбивать, тоненькой струей влить сироп. Взбивать, пока не остынет масса. Должна получиться гладкая, кремообразная, светлая, объемная масса. Развести в воде порошковый желатин. Смешать сыр с лимонным соком и цедрой. Взбить до однородности. Влить желатин, вновь взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Смешать сырную массу и желтковую. Отдельно взбить сливки до пиков. Нельзя переусердствовать, чтобы сливки не превратились в творог. Добавить в массу сливки. Осторожными, медленными движениями снизу вверх вмешать сливки в сырную смесь. Удобно использовать для этого силиконовую лопатку. Делать все осторожно и не спеша, чтобы масса не опала. Размешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Получившуюся массу вылить в формочку на корж. Накрыть полиэтиленом, отправить в холодильник на ночь или хотя бы часов на шесть. За этот период времени чизкейк «созреет» и станет более насыщенным. Украсить чизкейк перед подачей. Для этого можно использовать различные ягоды и фрукты в свежем виде, джемы, варенье, консервированные фрукты и так далее.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7255,'Взбить сливки до мягких пиков. Переложить в кондитерский мешочек, сделать бортики, чтобы с краев не стекал вишневый сок, но можно обойтись без бортиков – покрыть лимонный чизкейк топингом. Осторожно выложить вишни с соком на чизкейк, начиная с центра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7462,'В результате получится освежающий и вкусный коктейль «Тропический» с кокосовым молоком, бананом и манго',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7708,'Подать к столу горячей с любым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7256,'Приготовить бисквит: взбить белки до твердых пиков, в конце насыпать сахар. Положить желтки, размешать. Насыпать муку с порошком для выпечки, осторожно размешать. Перелить в формочку 15 на 25 сантиметров, застеленную специальной бумагой. Готовить 25 минут, соблюдать температуру 180 градусов. Так же сделать второй бисквит.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7256,'Приготовить пудинговый крем: размешать в половине стакана холодного молока сахар и порошок пудинга. Остальное молоко довести до кипения. Налить кипящее молоко на растворенный пудинг, готовить, помешивая, пока масса не станет густой. Позволить пудингу остыть. Растереть масло, добавлять постепенно холодный заварной крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7256,'Приготовить яблочный крем: почистить яблоки, крупно натереть, положить в кастрюльку, насыпать сахар, готовить. Положить в горячее пюре из яблок сухое желе, подогреть. Остудить. Смочить бисквит пуншем, выложить 1/2 часть пудингового крема. После выложить крем из яблок, на него остальной пудинговый крем. Растворить в кипятке синее желе. Вылить желе на бисквит сверху. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7256,'Приготовить сливочный крем: взбить сливки до устойчивых пиков, в конце насыпать сахарную пудру. Желатин растворить в горячей воде, перелить во взбитые сливки. Выложить сливочный крем на синее застывшее желе. Чтобы приготовить присыпку, нужно обжарить ингредиенты в кастрюльке. Остудить. Посыпать ими пляцок «Радуга Весенняя».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7257,'Растереть сливочное масло с яйцом и сахаром. Можно использовать миксер, чтобы получилась однородная масса. Положить сметану, насыпать соду и муку. Замешать тесто. Разогреть духовку до 180 градусов. Переложить на противень тесто, разровнять по поверхности. Готовить корж минут 25, должна появиться золотистая корочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7257,'Приготовить крем: вскипятить молоко с сахаром, в конце насыпать ванильный сахар. Развести крахмал в холодной воде, не спеша, тоненькой струей вылить получившуюся смесь в кипящее молоко. Должен получиться молочный кисель. Положить в него мягкое сливочное масло, взбить. Поломать испеченный корж на кусочки, перемешать с киселем. Коржик должен пропитаться кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7257,'Застелить формочку пленкой, выложить на нее пропитанный корж, превратившийся в однородную смесь, накрыть концами пленочки. Придать полу готовому тортику овальную форму, отправить в холодильник часа на три. Достать спустя три часа тортик, перевернуть на плоскую тарелочку, вставить палочку, как в эскимо. Можно приступить к декорации торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7257,'Приготовить черную и белую глазурь. Готовить одинаковыми способами, но в отдельных мисках. Растопить на водяной бане черный и белый шоколад, добавить сливки, размешать до однородности. Половину тортика покрыть белой глазурью, вторую половину черной. Отправить в холодильник, чтобы глазурь застыла. Сверху вкуснейший торт «Эскимо» для сладкоежек можно украсить лесными орешками, измельченным арахисом, стружкой кокоса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7258,'Духовку разогреть до 180 градусов. Помыть изюм. Соединить и растереть творог, сахар и манную крупу. Положить изюм, размягченный банан, размешать. Если смесь очень сухая, то положить чуть-чуть сметаны, чтобы тесто было вязким и густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7258,'Переложить тесто в формочку, застеленную несколькими слоями фольги и намазанную маслом. Готовить минут сорок, намазать поверхность сметанкой, готовить еще двадцать минут до золотой корочки. В конце можно включить минуты на три гриль. Запеканку из творога с изюмом и бананом можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7259,'Измельчить в блендере чесночок, положить укроп, добавить оливковое масло, сделать несколько оборотов. Вымыть и обсушить филе. Положить в формочку для запекания или на противень вниз кожей. Заранее противень намазать маслом. Сверху на рыбу положить чесночную смесь, отправить в холодильник мариноваться часа на два.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7259,'Разогреть духовку до 190 градусов. Готовить минут пятнадцать. Главное не передержать, чтобы рыба не была сухой. Если мякоть легко можно разделить на кусочки при помощи вилки, значит, филе лосося с чесноком и зеленью в духовке готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7260,'Обсушить гребешки с помощью бумажного полотенца. Посыпать перцем и солью. Растопить на небольшом огне сливочное масло. Обвалять гребешки в смеси перца, соли и сахара, положить на сковороду, с каждой стороны обжаривать по несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7261,'Порезать куриные грудки на тоненькие продольные ломтики поперек волокон. Мелко натереть сыр твердых сортов. Можно использовать швейцарский, пармезан, российский – каждый сорт придает наггетсам различные оттенки вкуса. Яйцо взбить с помощью вилки до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7261,'Соединить муку с перцем, солью в тарелочке. Солью не переусердствовать, особенно если соленый сыр. При использовании пармезана соль можно не класть. Обмакивать мясо по очереди в муку, яйцо, сыр. Обжаривать мясо на небольшом огне. Жарить куриные наггетсы до легкой золотой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7262,'Взять рыбное филе (на свой вкус) и порезать его небольшими кусочками, тонкими кружками нарезать помидоры, чеснок измельчить, крупно натереть сыр, мелко порубить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7262,'На дно формы для запекания уложить рыбное филе, поперчить и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7262,'На рыбный слой разложить помидоры, затем идет слой чеснока, который тоже нужно посолить и поперчить, промазать томатной пастой, последним слоем должен быть тертый сыр, отправить форму в духовой шкаф.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7262,'Рыба «Мечта» запеченная с помидорами и сыром запекается 35-40 минут при температуре 180 градусов, перед подачей украшается зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7263,'В мягкий маргарин положить сметану, муку и соду. Замесить тесто. Отправить на несколько часов или на ночь в холодильник. Вынуть тесто из холодильника, поделить на три части. Каждую раскатать в пласт в форме противня. Осторожно намотать рулон на скалку, перенести на противень. Чуть-чуть подсыпать муки, чтобы тесто не прилипало.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7263,'Готовить коржи минут десять, соблюдать температуру 180 градусов. Когда коржи станут румяными – они готовы. Могут образоваться во время приготовления пузырьки, но они исчезнут после пропитки. Остывшие коржики намазать майонезом, нанести начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7263,'На первый корж – потертый плавленый сырки, на второй – отваренные яйца, на третий – измельченные рыбные консервы. Сверху слоеный пирог с рыбой и плавленым сыром посыпать потертым вареным яйцом, крошкой от коржиков, оставшейся после «подравнивания» краев пирога.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7264,'Порезать лук на полукольца, крупно потереть морковь, обжаривать минут пять на растительном масле. Положить грибы, порезанные на четыре части. Через минуты три положить колбаски, порезанные на колечки. Положить в сковороду измельченную капусту, тушить под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7264,'Когда капуста станет мягкой, добавить томатную пасту, насыпать сахар, посыпать перцем, солью, побрызгать соком лимона, размешать. Тушить капусту с колбасками и грибами минут 25 под крышкой, помешивая время от времени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7265,'Соединить муку, разрыхлитель, соль и сахар. Добавить яйца, перемешать до однородности. На противень постелить пергамент, намазать любым маслом. Распределить тесто по бумаге, готовить шесть минут, соблюдать температуру 180 градусов. Должна появиться румяная корочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7265,'Во время готовки теста поставить кастрюльку на плиту. Налить джем и чуть-чуть подогреть его. Достать коржик из духовки, положить на стол. Снять бумагу, намазать поверхность коржа вареньем. Свернуть рулетик, обильно посыпать сахарной пудрой. Позволить быстрому рулету с джемом остыть, можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7266,'Разморозить при комнатной температуре слоеное тесто. Вырезать при помощи острого ножа сердечки. Чтобы было удобно, можно вырезать трафарет из картона. Сердечек должно получиться от шести до восьми штук. Соединить творожный сыр, обычный и ванильный сахар, желток, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7266,'Помыть яблоки, почистить кожуру, вырезать серединку. Порезать яблоки на четыре части, каждую четвертинку разрезать на тоненькие ломтики или дольки. На каждое сердечко положить по большой ложке творожного крема. На творожный крем положить ломтики яблок, до краев не доходить приблизительно два сантиметра, во время приготовления краешки теста должны подняться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7266,'С помощью кисточки намазать сиропом или медом, на серединку положить вишенку, отправить в духовку. Готовить минут двадцать, соблюдать температуру 220 градусов. Посыпать сердечки из слоеного теста с яблоками сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7463,'В кастрюльку влить молоко, поставить на огонь, когда оно закипит, всыпать кукурузную муку и варить, все время помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7267,'Выдавить сок из половинки лимона. Тщательно следить, чтобы не попали с соком мякоть и косточки. Вместо сока лимона можно использовать бальзамический уксус. Добавить пять больших ложек оливкового масла (или подсолнечного). Смешать ингредиенты с помощью вилки до однородности. Насыпать перец, соль, снова перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7268,'Промыть луковую шелуху, залить водой (1,5 литра), дать закипеть, всыпать 2 столовых ложек крупной соли, перемешать, варить еще 5-7 минут. Сало помыть, зачистить, нарезать примерно двухсотграммовые кусочки. Переложить его в кастрюлю, покрыть со всех сторон шелухой, если сало будет выступать над поверхностью воды, то долить еще.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7268,'Для приготовления маринада измельчить лавровый лист, раздавить чеснок, перемешать все с красным и черным перцем. Достать кусочки сала, высушить с помощью многослойного бумажного полотенца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7268,'Втереть в них с усилием «маринад», а затем обмазать со всех сторон, запаковать сало с чесноком в фольгу, определить в морозильную камеру. Через 12 часов вкуснейшее нежное сало будет готово. Порезать его на тонкие ломтики, подать к столу с черным хлебом, кто любит, может добавить чесночок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7269,'Мелко нашинковать лук и обжарить на масле до появления золотистого цвета, добавить порезанное на маленькие кубики филе, обжаривать четверть часа. Сдобрить перцем, посолить, перемешать все с томатной пастой, прогреть 3-5 минут. Сварить до готовности макароны, объединить с зажаркой, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7270,'Почистить небольшие шампиньоны, порезать, обжарить до готовности, приправить перцем и солью, добавить чуть молотой гвоздики, перемешать. Из половины кусочков хлеба сделать рамочки, мякоть отложить. Разложить на противне целые кусочки, на них положить рамочки. Половину рамочек заполнить грибами, на них уложить по кусочку помидора, присыпать сырной стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7270,'На оставшихся кусочках поднять рамочку и положить по пластинке ветчины, опустить рамку, накрыть кружками помидора, вбить по яйцу. Задвинуть противень с 8 необычными ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7271,'Довести до кипения небольшое количество воды, положить мускатный орех и палочку корицы, проварить минут 5-7, всыпать сахарный песок, перемешать, закрыть, дать постоять минут 15 и остыть. Влить свежеотжатый сок от 2 апельсинов и небольшого лимона, перемешать, разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7272,'Напечь обычных блинов, промазать маслом, сложить в стопку. Для приготовления начинки смешать отварной рис, натертые яйца и сыр, добавить сметану и порубленную зелень, желающие могут еще добавить обжаренный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7272,'На каждый блин ровным слоем нанести столовую ложку начинки, свернуть в рулончик, переложить все их в форму. На фаршированные блины положить ветчину, порезанную соломкой, присыпать слоем сыра. Поставить форму на треть часа в духовку с температурой 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Добавить яйца и сахар в размягченное сливочное масло,  все перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Муку соединить с разрыхлителем, солью, всыпать все в яичную смесь, приготовить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Форму устелить пекарской бумагой, выложить  половину  всего теста, сделать бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Оставшуюся часть теста поставить в холодильник не больше чем на полчаса, чтобы тесто стало твердым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Далее необходимо в разогретую до 160 градусов духовку поставить подготовленную форму на 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Когда это время пройдет, температуру увеличить до 1900 и выпекать корж еще 7 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Для начинки нужно смешать с ванильным сахаром ягоды или мелко нарезанные фрукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Через 7 минут вынуть форму, на корж выложить подготовленную фруктовую или ягодную начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Застывшее тесто натереть на терке, посыпать им начинку и отправить форму еще на 30 минут в духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7273,'Готовый тирольский фруктово-ягодный пирог можно при желании оформить веточками мяты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7274,'Овощи почистить и порезать, духовку включить для прогрева чуть выше 210 градусов. Распустить и прогреть в сковороде сливочное масло, всыпать лук, чуть обжарить, добавить морковку и картофель, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7463,'Яйца взбить, добавить порошок для выпеки, соль, мелко нарезанный зеленый лук, тертый сыр чеддер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7274,'Жарить овощи минут 12-13, посыпать их мукой, перемешать, влить бульон с молоком, размешать, прогреть пару минут. Влить коньяк, положить куски курицы, затем горошек, приправить тимьяном, зеленью петрушки и шалфеем, поперчить, присолить, перемешать, разложить овощи по горшочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7274,'Раскатать из слоеного теста сочни такого размера, чтобы плотно закрыть горшочки, смазать «крышечки» из теста разболтанным желтком яйца. Выпекать куриный пирог в горшочках в уже прогретой духовке примерно 10 минут, прикрыть горшочки листом фольги, закрепить, выдержать в духовке еще треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7275,'Замесить из всех ингредиентов с помощью миксера тесто, бананы порезать на кружочки. Каждый кусочек обмакнуть в тесто, а затем обжарить во фритюре. Для приготовления карамели смешать масло, сахар и воду, прогреть до появления коричневатого цвета. Обмакнуть в нее обжаренные кусочки, разложить бананы в карамели на смазанном маслом широком блюде, подождать до схватывания карамели и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7276,'Тщательно перемешать с холодной водой уксус, добавить взбитые яйца, слегка подсолить. Включить прогреться до 180 градусов духовку. Сильно охлажденное масло протереть на крупную терку, соединить его с просеянной мукой, порубить ножом до образования маслянистой смеси. Собрать ее горкой с углублением по центру, влить в него смесь яиц, вымесить тесто, разделить полученный шар на 11-12 частей, на час положить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7276,'Холодные шарики теста раскатать (доставать по 1-2), положив на пергаментную бумагу, вырезать из каждого круг по диаметру формы, проколоть в нескольких местах вилкой, выпечь минут 14-17 в прогретой духовке вместе с обрезками до золотистости, дать остыть. Приготовить из смеси яиц, муки и сахара с добавлением холодного молока крем, прогреть, помешивая, на медленном огне (кипеть не давать), добавить для ароматизации ванилин, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7276,'Хорошо промазать коржи кремом, собрать их в стопку. Обрезки сложить в блендер, измельчить до состояния крошки смазать кремом верх и бока торта «Наполеон», обсыпать крошкой. Убрать десерт минимум на 12 часов в холодильник, а лучше дать ему там переночевать, чтобы коржи размякли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7277,'Хорошо помыть клубни картофеля щеткой, очистить, натереть, либо мелко разбить блендером, отжать сок, также поступить с луком. Добавить к смеси яйцо с мукой, поперчить, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7277,'Разогреть сковороду, налить масло, прогреть его, выложить небольшие блинчики. Обжарить картофельные драники с одной и другой стороны до хрустящей золотой корочки. Нагрев уменьшить, прикрыть крышкой сковороду, прогревать еще 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7278,'Сварить из сахара и воды сироп, дать ему остыть. Желатин залить парой столовых ложек очень горячей воды, размешать, дать ему раствориться, смешать с ягодами клубники, влить сок лимона, тщательно растереть смесь до однородности. Добавить к смеси остывший сироп и взбитый в пену белок, хорошо перемешать. Переложить клубничный щербет в мороженицу, дать десерту хорошо застыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7279,'Промыть хорошо рисовую крупу, залить водой, дат постоять. В сотейнике с хорошо прогретым маслом обжарить лук и морковь при среднем нагреве. Всыпать кусочки курицы без кожи, обжарить до побеления мяса. Влить воды, чтобы она покрыла мясо. тушить четверть часа, подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7279,'Откинуть рис на дуршлаг, переложить его в сотейник, сверху уложить слой мяса, залить на сантиметр выше его уровня водой. добавить пару лавровых листиков, размешивать не надо, выставить максимальный нагрев, дать закипеть, нагрев уменьшить в два раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7279,'Как только вся жидкость впитается и не будет заметна на поверхности, закрыть крышкой. Прикрутить огонь до минимума довести рис до полной готовности. Только после этого ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7280,'Из всех ингредиентов замесить тесто, дать ему постоять час. Разболтать яйца с сахаром, влить сметану, осторожно перемешать до однородности. Полученное тесто раскатать в круглый пласт на пару-тройку сантиметров больше формы, уложить его в форму, сформовать бортики, уложить на основание начинку, завернуть бортики внутрь. Отправить татарский пирог «Сметанник» минут на 30-35 в прогретую до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8332,'Тесто посолить и всыпать в него предварительно измельченный зеленый лук, все еще раз размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7281,'Порезать лук и чеснок, обжарить пару минут в разогретом масле при среднем нагреве. Добавить все специи и измельченную зелень, обжаривать пока чеснок не станет золотистым. положить сахар и помидоры, перемешать. Сделать нагрев минимальным, обжаривать еще некоторое время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7281,'Пасту положить в кипящую соленую воду, варить почти до готовности, сцедить воду, перемешать ее с соусом, всыпать порезанный базилик и натертый сыр. Паста с помидорами, сыром и базиликом тщательно перемешать, подавать к столу горячей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7282,'На мелкой терке натереть имбирь, банан порезать на кусочки, сложить в блендер. добавить выжатый сок, тщательно взбить, разлить по стаканам, добавить в каждый по соломинке. Этот бодрящий коктейль пить лучше утром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7283,'Порезать лук на полукольца, грибы – пластинками, морковь натереть. Обжарить грибы в разогретом масле до полного испарения жидкости, теперь всыпать морковь, жарить все еще минут 7-8, сдобрить перцем и солью, влить сметану, перемешать, убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7283,'Срезать у перчин верхушки, удалить тщательно все семена, заполнить начинкой из грибов с луком и морковью. Сложить фаршированный перец с грибной начинкой в керамическую форму, закрыть каждый перчик срезанной верхушкой, отправить в прогретую до 200 градусов духовку минут на 25.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7284,'В большую миску сложить часть нарезанных крабовых палочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7284,'Вареные, охлажденные и очищенные яйца нарезать или потереть на терке, добавить к крабовым палочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7284,'В миску с яйцами и крабовыми палочками добавить кукурузу без сока, нарезанный мелко зеленый либо репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7284,'Все перемешать и не меньше чем на 15 минут убрать салат в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7284,'Когда ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7285,'Порезать помидор очень острым ножом на тонкие ломти вместе с грибами. Куски хлеба смазать маслом с двух сторон, обжарить с одной и другой стороны до золотистой корочки. Уложить на куски хлеба сыр, помидор, грибы, полить соусом, накрыть сковороду с итальянскими бутербродами-гриль крышкой, дать сырной стружке расплавиться, через пару-тройку минут перевернуть куски и закрыть опять крышку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7286,'В кастрюлю с широким дном налить воду, подсолить, добавить корицу и лаврушку, когда она закипит всыпать фасоль. Дать еще раз закипеть , прикрыть наполовину крышкой, нагрев уменьшить, варить до размягчения примерно треть часа, в процессе варки снимать пену. Овощи порезать на кубики, высыпать к фасоли, добавить масло и порошок куркумы, варить под крышкой до полной готовности фасоли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7286,'В сковороде распустить пару столовых ложек топленого масла, добавить кумин и перец, прогреть до потемнения, добавить тертый имбирь и асафетиду, обжарить все вместе несколько секунд, помешивая. Вылить содержимое сковороды в кастрюлю с фасолевым супом «Дал Таркари», крышку закрыть, подержать суп на слабом огне еще минут 5 и убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7287,'Смешать все ингредиенты для крема кроме масла, проварить помешивая на слабом огне до сгущения крема, остудить, сварить яблочное повидло, приготовить тесто. Перемешать все ингредиенты для теста кроме муки в сотейнике с толстым дном, проварить смесь минут 10-15 до увеличения объема. убрать сотейник с плиты, засыпать всю муку, тщательно перемешать до получения мягкого теста, остудить его, масса станет слегка тверже.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7287,'Разделить ком теста на 4 части, раскатать каждый в прямоугольник, перенести с помощью скалки на противень, выстланный бумагой, довести до готовности в прогретой до 200 градусов духовке. Масло взбить с кремом (добавлять порциями), смазать половиной крема корж, прикрыть другим, промазать джемом из яблок, прикрыть следующим коржом, смазать остатками крема, прикрыть последним коржом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7287,'Бока  присыпать крошкой от обрезки коржей, верх покрыть шоколадной глазурью. Глазурь приготовить из разогретого на водяной бане шоколада с маслом. Убрать все сооружение в холодильник, оставить там на ночь. Утром достать, порезать на медовое пирожное, разложить на блюде, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7299,'Нарезать небольшими кусочками филе курицы. Натереть очищенную морковь на крупной терке. Обжарить морковь и мясо на масле в течение 10 минут, затем потушить под крышкой еще пять минут. Выложить рис в миску, добавить курино-морковную смесь. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7288,'Для приготовления теста смешать и перетереть руками в крошку пшеничную муку, сливочное масло или маргарин комнатной температуры, сахарный песок и какао-порошок. Для начинки взбить сырые куриные яйца с сахаром до пены, добавить творог, сметану, ванилин из пакетика и просеянную пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7288,'Для выпечки понадобится разъемная форма среднего диаметра, ее нужно смазать маслом, высыпать чуть больше половины песочного теста. Вылить творожную начинку, сверху выложить оставшуюся крошку. Печь торфяной пирог при температуре 180 градусов в течение 40 – 50 минут. Готовый пирог осторожно вынуть из формы, он может развалиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7289,'Замесить жидкое тесто для блинов из молока, сырых яиц, сахарного песка и соли по вкусу. Влить немного растительного масла и размешать. Выпечь блинчики с двух сторон на сковороде с антипригарным покрытием. Для начинки нашинковать капусту, потушить на растительном масле с небольшим количеством воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7289,'Отдельно, на другой сковороде, обжарить куриное филе на смеси сливочного и подсолнечного масла. Порубить репчатый лук, добавить к обжаренному мясу, прогреть, лук должен стать прозрачным. Соединить капусту с мясом, влить ложку томатной пасты, перемешать, посолить, поперчить, потушить массу до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7289,'Выложить на готовые блинчики по ложке начинки, свернуть конвертом. В другой емкости взбить сырые яйца с солью, влить немного воды. Отдельно насыпать панировочные сухари, лучше, если они будут домашними. Завернутый блин обмакнуть в яичную смесь, запанировать блинчики с начинкой из курицы и капусты в сухарях, обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7290,'Для приготовления бисквита перемешать с помощью миксера сырые куриные яйца, сахарный песок и ванильный сахар. Через три минуты добавить молоко, продолжать взбивать еще три минуты. Влить растительное масло, всыпать разрыхлитель, пшеничную муку. Масса должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7290,'Форму застелить промасленной бумагой, вылить тесто, печь корж в течение получаса при температуре 180 градусов. Выпечку немного остудить, перевернуть, бумагу удалить. Приготовить соус из молока, сахарного песка, какао-порошка и шоколада. Все ингредиенты сложить в небольшую емкость, довести до кипения, смесь остудить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7290,'Бисквит разрезать на шестнадцать кубиков. Тонко обрезать края, обмакнуть со всех сторон в соус, немного подержать, чтобы выпечка пропиталась. Затем обмакнуть нежное пирожное в кокосовую стружку с четырех сторон, поставить на блюдо, верх также полить соусом и посыпать стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7291,'Очистить и натереть морковь, лучше это сделать на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7291,'Посолить блюдо по вкусу, добавить майонез, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7291,'Так же поступить с твердым сыром, а вот очищенный чеснок лучше мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7292,'Творог протереть сквозь сито, в нем не должно быть комочков. Добавить мягкое сливочное масло и сырое яйцо, перемешать. Всыпать пшеничную муку, ванилин и разрыхлитель. Замесить мягкое и эластичное тесто, оно не должно липнуть  к рукам, при необходимости муку можно добавить. Скатать массу в «колобок», накрыть пленкой и оставить на 20 минут. Разделить тесто на две части, раскатать, нарезать кружочки с помощью стакана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7292,'Каждый кружок одной стороной обмакнуть в сахар, свернуть пополам, снова обмакнуть, свернуть сахарной стороной внутрь, обмакнуть «четвертинки». Выложить заготовки на застеленный пергаментом противень, сахарной стороной вверх. Печь печенье «Уголки» в течение 20 минут, печенье должно стать золотистым. Снять с пергамента и подать в теплом виде с чаем или кофе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7293,'Для начинки смешать мак с сахаром, добавить ванилин, влить горячее молоко, размешать, сахар должен раствориться. Остудить. Таким же образом приготовить ореховую начинку из очищенного и раздробленного фундука, сахарного песка, ванилина и молока. Для теста смешать пшеничную муку с сухими дрожжами, сахаром, добавить соль, массу перемешать. Нарезать сливочное масло, добавить в сухую смесь, влить желток и молоко, замесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Теперь добавим в прокрученное мясо лук, хлеб (предварительно отжать от молока), перец и соль по вкусу, а также яичный желток. Все тщательно перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7293,'Разделить на две части, завернуть каждую в пищевую пленку, оставить в холодильнике на полчаса. Охлажденное тесто раскатать на присыпанной мукой рабочей поверхности в тонкие прямоугольники. Края обрезать острым ножом. Выложить ровным слоем начинку, до краев не доходить, противоположные короткие края завернуть на начинку. Скрутить изделие в рулет, наколоть вилкой. Форму застелить пергаментом, выложить рулеты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7293,'Смазать яичным желтком, оставить в прохладном месте, но не в холодильнике, на 45 минут, желток должен полностью высохнуть. Белки взбить, намазать рулеты, оставить до полного высыхания на полтора часа или на ночь. Выпечь рулеты с маком и орехами при температуре 180 градусов в течение 20–30 минут, поверхность должна подрумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7294,'В емкости перемешать с овсяными хлопьями манную крупу, полученную смесь залить кефиром, перемешать и отставить на 2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7294,'В миску с настоявшейся смесью добавить взбитые яйца, соль, соду, сахар и растительное масло, перемешать, должно получиться не слишком густое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7294,'На сковороде испечь небольшие оладьи без муки манно-овсяные на кефире.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7295,'Кочан капусты очистить от верхних поврежденных листьев, их можно положить на дно кастрюли с толстыми стенками. Еще один крупный лист оставить для накрывания блюда сверху. Кочан опустить в кипяток, обваривать в течение пяти минут с каждой стороны. Готовые бланшированные листья снимать, воду не выливать: она понадобится для заливки. Полуотваренные листья остудить, острым ножом срезать уплотнения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7295,'Нарезать репчатый лук мелкими кубиками, натереть морковь. Овощи обжарить на растительном масле до образования коричневатой корочки. Отварить рис до полуготовности. Свинину пропустить через мясорубку. Для начинки перемешать мясо, рис, половину овощной обжарки, соль и перец – по вкусу. Выложить готовую начинку на листья капусты, скрутить в рулеты, края завернуть внутрь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7295,'На листья, выложенные в толстостенную посуду, поместить голубцы вплотную друг к другу. Для приготовления заливки смешать майонез, томатный соус, остатки обжарки, посолить и поперчить. Готовый соус развести водой, оставшейся от бланширования капусты. Изделия должны быть покрыты полностью. Накрыть блюдо крышкой и тушить в течение трех – четырех часов при температуре 175 градусов. Подать вкусные ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7296,'Сырые куриные желтки смешать с сахаром и ванилином, массу взбить до однородности в пышную массу. Влить молоко, перемешать, смесь поставить на средний огонь. Довести до кипения, но не кипятить, огонь убавить, варить до загустения в течение 20–25 минут. Масса должна напоминать сгущенное молоко. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7296,'В плотную пену взбить жирные сливки, влить яично-молочную смесь, снова все взбить. В процессе замерзания десерт перемешать два – три раза, в таком случае он будет однородным. После последнего перемешивания массу разложить в формочки или стаканчики, накрыть, поставить сливочное мороженое в морозильную камеру до окончательного замерзания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7297,'Для приготовления основы перемешать отваренные спагетти, сырые куриные яйца, тертый твердый сыр. Массу выложить в смазанную маргарином форму. Верх намазать кетчупом, выложить произвольно нарезанную колбасу или ветчину. Посыпать тертым сыром. Печь пиццу из макарон в духовке при температуре 180 градусов в течение 7–10 минут. Яйцо должно затвердеть, а сыр – расплавится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7298,'Сырые куриные белки смешать с сахаром с помощью миксера, массу поставить на водяную баню. Нагреть до 70 градусов, продолжать взбивать венчиком. Снять смесь с огня, взбить миксером до остывания и увеличения объема в два раза, на это потребуется 10 – 12 минут. В крем-безе добавить мягкое сливочное масло, порциями, каждый раз взбивать. Массу немного посолить, добавить любой вкусовой наполнитель и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7299,'Разогреть в кастрюле оливковое масло, всыпать рис, перемешать. Залить массу кипящей водой, она должна полностью покрыть крупу, соль–по вкусу. Прогревать на тихом огне до полного испарения воды. Чеснок очистить, каждый зубчик разрезать пополам. Добавить в рис, перемешать, влить еще немного воды и готовить на медленном огне в течение 7–10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8332,'Жарить оладьи с обеих сторон в хорошо разогретом растительном масле на маленьком огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7300,'Любые части курицы, кроме крылышек, вымыть под проточной водой, обсушить бумажными полотенцами. Куриное мясо посолить, поперчить, намазать аджикой. Оставить мариноваться на полчаса. Растопить на сковороде смесь сливочного и растительного масла, обжарить нарезанный на четвертинки репчатый лук, он должен приобрести золотистый цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7300,'Лук выбросить, в ароматном масле обжарить куски курицы по несколько минут с каждой стороны, до золотистой корочки. Выложить в жаропрочную форму. На небольшой сковороде без масла обжарить столовую ложку пшеничной муки до золотисто-коричневого цвета. Налить немного куриного бульона, натурального или из кубика, добавить сливки, смесь прогреть, соль и перец молотый – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7300,'Добавить раздавленный чеснок, довести массу до кипения, всыпать муку, перемешать, соус должен загустеть, но в нем не должно быть комочков. Залить смесью курицу. Поставить острые куриные окорочка в сливочном соусе в нагретую до 180 градусов духовку на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7301,'Перемешать сахарный песок, мед, сливочное масло и содержимое пакетика с ванилином. Залить топленым молоком. Варить в течение получаса на среднем огне, помешивать. Масса должна загустеть, приобрести яркий карамельный цвет. Формочки для льда смазать растительным маслом, разлить смесь, поставить ирис «Тянучки» в морозильную камеру на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7302,'Репчатый лук нарубить, обжарить с оливковым маслом, добавить рубленую говядину и телятину в равных пропорциях. Отдельно отварить макароны в подсоленной воде в течение четырех минут. Дно формы залить готовым соусом бешамель. Наполнить каннеллони начинкой с помощью чайной ложки, уложить первый слой на соус, посыпать тертым сыром пармезан. Выложить второй слой фаршированных макаронных изделий, залить оставшимся соусом, посыпать сыром и запечь в течение 20 минут при температуре 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7303,'Для приготовления теста перемешать кефир с растительным маслом, немного прогреть, добавить по вкусу соль и сахарный песок. Пшеничную муку просеять, смешать с сухими дрожжами, влить порциями кефирную смесь, замесить тесто. Накрыть тканью, поставить в тепло на полчаса. Приготовить несколько начинок. Первая: накрошенные вареные яйца с зеленым луковым пером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7303,'Для начинки с квашеной капусты основной продукт отжать от рассола, порубить, добавить обжаренный лук, масло, потушить до готовности. В конце посолить и всыпать немного сахара, крутое нарезанное яйцо – по желанию. Начинка с солеными огурцами: основной продукт очистить от кожицы, нарезать ломтиками, припустить с небольшим количеством воды под крышкой. Откинуть на сито, смешать с крутым рубленым яйцом и пассерованым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7303,'Для начинки с грибами соленый продукт нужно хорошо промыть, отжать и порубить. На сковороде сначала обжарить рубленый лук с маслом, затем добавить грибы, обжарить все вместе. Сформовать небольшие пирожки с разными начинками. Противень застелить промасленной бумагой, выложить пирожки «Чисто закусочные» швом вниз. Дать постоять в течение 10 минут, смазать немного взбитым яйцом, печь при температуре 200 градусов, до образования золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7304,'Сыр сулгуни нарезать пластинками, выложить слоем в чугунную сковороду или керамическую форму. Посыпать нарезанными помидорами, печь в духовом шкафу в течение 7–10 минут до расплавления сыра. Блюдо вынуть, посыпать сухим орегано и сразу подать на стол.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7305,'В чаше блендера измельчить крупно порезанный чеснок, оливки, половину петрушки и оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7305,'В форму для запекания уложить филе лосося, опрыснуть ее оставшимся оливковым маслом, поперчить и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7305,'Поверх рыбы распределить подготовленную в блендере массу, листья оставшейся петрушки, кружочки помидоров, все присыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7305,'Лосось запеченный с маслинами, помидорами и сыром при 200 градусах в духовке готовится не больше получаса, украшается перед подачей лимоном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7306,'Филе нарезать, натереть солью и перцем, смазать растительным маслом, выложить на противень. Отварить грибы, например, лисички, в подсоленной воде, остудить, мелко нарезать. Порубить репчатый лук, обжарить вместе с грибами, всыпать немного муки и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11339,'Влить мясной сок, добавить томатную пасту.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7306,'Смешать сметану с солью, перцем, специями, разбавить водой, добавить обжарку. Соус прогреть до загустения. Форель поставить в духовку на 15 минут, печь при температуре 220 градусов. Блюдо вынуть, полить грибным соусом, посыпать сыром. Печь форель под грибным соусом в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7307,'Для приготовления крема смешать сырые куриные желтки с сахарным песком, добавить кокосовую стружку и снова перемешать. Всыпать просеянную пшеничную муку, влить горячее молоко. Массу варить до загустения на среднем огне, помешивать. Готовый крем можно оставить для остывания на ночь при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7307,'Для печенья взбить с помощью миксера мягкое сливочное масло и сахарную пудру. Влить желтки, перемешать, всыпать какао-порошок, взбить. Смесь должна стать однородной. Добавить разрыхлитель и часть муки, перемешать ложкой, затем всыпать остатки муки. Замесить тесто на рабочей поверхности, присыпанной мукой, скатать колбаской.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7307,'Завернуть изделие в пищевую пленку или пакет, поставить в морозильную камеру на полчаса. Нарезать «колбасу» кружками, выложить их на противень, застеленный бумагой для выпекания. Между изделиями должно быть расстояние. Печь при температуре 180 градусов в течение 10 минут. Остудить, намазать готовым кремом, склеить печенье по две штуки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7307,'Готовое шоколадное печенье с кокосом можно полить шоколадной глазурью или помадкой, украсить кремом. Для его приготовления сливочное масло взбить с сахарной пудрой, ванилином, добавить растопленный темный шоколад. Нанести крем на печенье с помощью кондитерского мешка, посыпать кокосовой стружкой, украсить готовыми шоколадными фигурками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7308,'Шесть креманок или формочек для запекания смазать сливочным маслом и поставить в холодильник. На среднем огне прогреть смесь из темного шоколада, сливок, молока. Довести до кипения, шоколад должен растаять. Влить яичные желтки. Белки взбить отдельно в пену, всыпать сахарный песок, частями, продолжать взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7308,'Четверть полученной массы ввести в шоколад, перемешать, затем добавить остальную. Разложить суфле в креманки, печь при температуре 190 градусов в течение 20–25 минут. Взбить сливки с сахаром и ванилином, поставить в холодильник. Шоколадное суфле вынуть из духовки, посыпать пудрой, выложить по ложке сливок и сразу подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7309,'Куриную грудку нарезать на шницели. Каждый отбить. В небольшую емкость вбить сырые куриные яйца, взболтать, посолить. Разогреть сковороду с небольшим количеством масла. Шницели обмакнуть в панировочные сухари, затем в яйцо. Жарить по две минуты с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7310,'Приготовить жидкое тесто из пшеничной муки, пива, сырого желтка. Всыпать соль и тертый мускатный орех. Массу вымешать, в конце добавить взбитый белок. Шампиньоны целиком обмакивать в смесь и жарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7311,'Куриное филе нарезать небольшими кубиками, обжарить до полуготовности, соль и молотый перец – по вкусу. Натереть на крупной терке сыр. Картофельные клубни очистить, нарезать ломтиками, посолить и перемешать в пакете. Выложить в формочки слоями: картофель, куриное мясо, грибной или чесночный соус, сыр. Печь гратен с куриным филе при температуре 175 градусов в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7312,'С помощью кухонного комбайна взбить просеянную пшеничную муку с охлажденным сливочным маслом в крошку. Влить немного холодной воды. Выложить массу на рабочую поверхность, сформовать диск. Обернуть его пищевой пленкой и положить в холодильник на час или на сутки. Охлажденное тесто раскатать в лепешку по размеру формы для выпечки, выложить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7312,'Приготовить крем из молотого миндаля, сливочного масла, яйца, дополнительного белка, миндального экстракта. Массу взбивать при добавлении каждого нового компонента. Вылить смесь на корж в форму. Очистить груши от кожицы и внутренней части, нарезать на мелкие дольки. Сбрызнуть лимонным соком, чтобы не почернели, переложить в крем и слегка вдавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7312,'Печь при температуре 190 градусов в течение 50–55 минут. Начинка должна покрыться золотисто-коричневой корочкой. В небольшой кастрюле нагреть воду или бренди с абрикосовым джемом. Готовый пирог «Груши в миндальном креме» смазать жидкостью, остудить до комнатной температуры и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11339,'Все вместе тушить на тихом огне 15 или 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7313,'Взбить яйцо с сахарным песком. Добавить сметану, снова взбить. Погасить уксусом соду, добавить в яичную массу и снова взбить. Из яблок удалить семенные камеры, лучше взять сорт Антоновка, но можно и сладкие, в таком случае их можно дополнить черной и красной смородиной. Если ягоды замороженные, то размораживать их не нужно. Ввести в тесто пшеничную муку, взбить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7313,'Половину готового теста вылить в смазанную форму среднего диаметра, уложить ломтики яблок, ягоды. Залить оставшимся тестом, печь в течение получаса или чуть больше при температуре 180 градусов. Готовность шарлотки с яблоком проверить зубочисткой. Пирог перевернуть на блюдо и подать в горячем или холодном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7314,'Приготовить несколько коржей с разным составом ингредиентов. Первый – шоколадный, состав: сахарный песок, мука, сметана, сода, погашенная уксусом, сырые куриные яйца, растопленное сливочное масло, какао-порошок. Яйца взбить с сахаром в пену, добавить масло и сметану, еще раз взбить, всыпать соду и муку, какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7314,'Второй корж: те же составляющие, но вместо какао – мак, предварительно запаренный кипящей водой. Для третьего коржа – стакан рубленых грецких орехов. Приготовить крем из сливочного масла и сгущенного молока, смесь должна быть однородной, поставить на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7314,'Выпечь три коржа по отдельности в смазанной маслом форме в течение 25–30 минут до готовности, проверить спичкой или зубочисткой. Коржи полностью охладить, промазать охлажденным кремом, покрыть им же верх и бока выпечки. Подержать торт «Сказка» в холодильнике в течение 8–12 часов, можно оставить на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7315,'Отварить яйца вкрутую, залить холодной водой, затем очистить и нарезать. Очистить и нарезать зеленую фасоль. Переложить её в кипящую воду с солью, отварить в течение 5–10 минут, до мягкости. Готовый продукт охладить в дуршлаге под струей холодной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7315,'На среднем огне разогреть небольшое количество сливочного масла, добавить отваренную фасоль и обжарить в течение пяти минут, помешивать. Переложить ингредиент в салатник, сверху – давленый чеснок, яйца. Соль – по вкусу, заправить салат из зеленой фасоли майонезом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7316,'Форму или другую термостойкую посуду застелить фольгой. Если используется керамическая емкость, то ее достаточно смазать маслом. Нарезать очищенные бананы колечками, выложить на дно, затем высыпать половину нормы ягод черники, свежей или замороженной. Посыпать начинку молотой корицей, полить медом, накрыть фольгой и печь в течение 15 минут при температуре 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7316,'Смешать овсяные хлопья с половиной нормы рубленых грецких орехов, разрыхлителем и остатками корицы. Отдельно взбить обезжиренное молоко с сырым куриным яйцом, ванилином из пакетика и медом. Вынуть запеченную начинку из духового шкафа, посыпать смесью с хлопьями, залить молочно-яичной массой, она должна распределиться равномерно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7316,'Посыпать пирог оставшимися грецкими орехами и черникой, печь в течение получаса при той же температуре до образования золотистой корочки. Подать овсяный пирог с черникой и бананом в теплом виде, посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7317,'Растворить в чашке теплой воды сахарный песок, соль, дрожжи. Влить растительное масло. Смесь перемешать, вбить сырые яйца, всыпать пшеничную муку. Тесто должно получиться мягким, оно не должно прилипать к рукам. Если прилипает – можно добавить еще немного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7317,'Переложить массу в емкость, смазанную маслом, дать подойти, обмять через 15 минут, процедуру повторить еще несколько раз в течение часа. Сформовать булочки, дать им постоять еще час, затем выпечь в течение 20–25 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7318,'Вырезать из бумаги небольшие полоски бумаги, шесть на один сантиметр, написать на них хорошие пожелания, поздравления. Белки отделить от желтков, взбить в течение 10 секунд, всыпать ванилин, влить растительное масло, продолжать взбивать до образования пены. В другую емкость всыпать сахарный песок, картофельный крахмал, соль и пшеничную муку, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Пришла очередь яичных белков. Взбиваем их и тоже вливаем в фарш, перемешивая до получения однородной массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'В другой мисочке перемешать масло с водой и соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7318,'Перемешать ингредиенты с помощью миксера, масса должна получиться однородной. Вбить яйца, продолжать взбивать. Бумагу для выпечки смазать сливочным маслом, тесто выкладывать ложкой, в виде небольших лепешек, между ними должно быть расстояние. Печь при температуре 180 градусов в течение 11 минут, выпечка должна приобрести золотистый оттенок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7318,'Пожелания вложить в печенье, придать выпечке нужную форму, «повесив» его на бортик чашки. Готовые изделия, уже в свернутом виде, поместить в формочки для маффинов, печь печенье с предсказаниями еще 5–10 минут при той же температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7319,'Растереть творог с сахарным песком, ванилином, вбить сырое яйцо. Готовое тесто раскатать в лепешку толщиной один сантиметр. Кружки вырезать с помощью большой чашки, нижней ее стороной надавить на середину, но не прорезать. Выстелить пергаментом противень, переложить на него ватрушки, намазать начинкой выдавленный кружок посередине лепешек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7319,'Подержать в тепле в течение 15–20 минут, затем выпечь при температуре 180 градусов в течение 15–20 минут, выпечка должна приобрести золотистый оттенок. Ватрушки с творогом  вынуть, переложить на ткань или пергамент, сбрызнуть холодной водой и подержать под полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7320,'Отделить сырые желтки от белков. Последние взбить с половиной сахарного песка в плотную пену. Отдельно взбить желтки с остатками сахара, он должен полностью раствориться, а масса посветлеть. Влить желтковую смесь в белковую, перемешать, делать это аккуратно. Просеять вместе какао-порошок и пшеничную муку, всыпать часть этой смеси в яичную массу, перемешать, затем всыпать остатки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7320,'Из пергамента вырезать три круга, размазать тесто, печь при температуре 200 градусов в течение 20 минут. Остудить коржи в течение получаса. Острым ножом подровнять края. Приготовить крем из мягкого сливочного масла, сгущенного молока, в конце всыпать какао-порошок и перемешать. Прослоить приготовленным кремом коржи, оформить темным тертым шоколадом. Края домашнего торта так же можно обмазать сливочным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7321,'Для приготовления блинчиков нужно смешать сырое куриное яйцо с небольшим количеством молока или воды, посолить по вкусу, взбить вилочкой. Из этой омлетной массы приготовить яичный «блинчик». Таким же образом испечь еще пять штук. Мелко нарезать шампиньоны, обжарить их на растительном масле, соль–в конце жарки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7321,'Приготовить куриный фарш, посолить и поперчить, всыпать специи для курицы. Блинчик смазать куриным фаршем, майонезом, выложить грибную начинку, свернуть рулетом. Противень смазать маслом, выложить бризоли с куриным фаршем, смазать майонезом и посыпать тертым твердым сыром. Печь в разогретой духовке при температуре 200 градусов в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7322,'Отварить морковь, натереть, она потребуется для украшения блюда. Еще один корнеплод натереть и спассеровать на растительном масле вместе с нашинкованным репчатым луком. Отварить куриные яйца и куриную грудку. Мясо мелко порезать, яйца разделить на желтки и белки. Маринованные шампиньоны отцедить от рассола, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7322,'Выложить салат слоями на большую тарелку в таком порядке: морковная обжарка, куриная крудка, майонез, шампиньоны, майонез, тертый твердый сыр с давленым чесноком, майонез, накрошенные желтки, майонез, белки, часть оставить для украшения, завершить слоем майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7322,'Верх салата «Долька апельсина» посыпать отваренной морковью, она должна полностью закрыть поверхность. Из оставленного белка сделать «прожилки», имитирующие дольки апельсина. Дать блюду постоять в течение двух часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7323,'Хорошо промыть плоды апельсина, срезать верхушку и место крепления черенка, сделать несколько вертикальных надрезов, кожуру снять. Белую часть удалить, оранжевую нарезать полосками и замочить ее на два часа в холодной воде. На тихом огне разогреть воду с сахарным песком, кипятить сироп до полного растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7323,'Всыпать подготовленные корочки, варить на тихом огне до мягкости, в течение получаса. Достать корочки с помощью сита, обвалять в сахарном песке и выложить на противень, застеленный бумагой. Апельсиновые цукаты высушить, хранить в плотно закрытой стеклянной банке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Посыпать рыбу перцем, солью, побрызгать лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7324,'Маргарин растопить в микроволновой печи, добавить сахарный песок, сырые куриные яйца, перемешать. Затем влить сметану, всыпать соль и снова перемешать. В массу всыпать просеянную пшеничную муку, разрыхлитель. Тесто вымешать. Готовый «колобок» на время оставить. Перемешать творожную массу с сахаром, сырым яйцом, небольшим количеством муки и ванилином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7324,'Рабочую поверхность посыпать мукой или смазать растительным маслом, выложить тесто, раскатать и нарезать кружками с помощью чашки. Творожную начинку выложить на край кружка, свободной половинкой накрыть начинку, бока немного защипать. Сочники с творожной начинкой выложить на смазанный растительным маслом противень. Смазать немного взбитым яйцом и печь в духовом шкафу при температуре 180 градусов в течение 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7325,'Замесить тесто из сырых яиц, сахарного песка и муки. Раскатать в пласт толщиной два миллиметра, разрезать на полосы разной ширины, от трех до шести с половиной сантиметров, каждая должна быть шире предыдущей на один сантиметр. Сложить друг на друга, начиная с самой широкой, для склеивания промазывать яйцом или водой. В середину полос положить скалку, нарезать тесто на полосы шириной три-четыре миллиметра, таких групп полосок должно быть семь или восемь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7325,'Середину цветов хорошо продавливать, она не должна развалиться. Полоски теста расправить, жарить во фритюре до готовности. Маслу дать стечь, можно обсушить выпечку на бумажных полотенцах. Выложить выпечку на тарелку, украсить любимым вареньем или джемом, он должен быть густым, можно посыпать печенье «Хризантемы» сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7326,'Нарезать тонкий армянский лаваш на квадратики, завернуть в них кусочки сыра и ветчины. Обжарить на масле с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7327,'Выложить в емкость смесь орехов, изюма, кураги, чернослива, фруктовых цукатов. Залить апельсиновым соком и оставить на ночь. Затем всыпать разрыхлитель, размешать, добавить муку, снова перемешать. Форму для выпекания смазать маслом и обсыпать манной крупой. Выложить массу, выпечь до готовности при температуре 180–190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7328,'Отварить рис басмати до полуготовности, откинуть на дуршлаг. Всыпать приправы для плова, куркуму, шафран или Сары кек. Разогреть на сковороде сливочное масло, добавить рис и дать постоять. Отварить курицу до состояния полуготовности. Отделить от костей, порвать руками на кусочки, обжарить вместе с измельченным пассерованным репчатым луком, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7328,'Дно и стенки посуды смазать сливочным маслом, обсыпать кунжутными семечками или фисташками. Вымесить гладкое тесто из воды, соли, пшеничной муки, смеси растопленного сливочного и растительного масла. Тонко раскатать толщиной в полсантиметра, перенести в форму, края должны свисать наружу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7328,'Насыпать слой риса, затем выложить курицу, снова рис. Начинку полить растопленным сливочным маслом и закрыть внахлест тестом. Поставить бочонок из теста с пловом в духовой шкаф на 30–45 минут, печь при температуре 190 градусов. Готовое блюдо опрокинуть на тарелку и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7329,'Перемешать пшеничную просеянную муку, воду комнатной температуры, соль и сухие дрожжи. Тесто должно получиться негустым, его нужно накрыть полотенцем или крышкой и подержать для набухания клейковины при комнатной температуре в течение 12 часов, можно оставить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7329,'Противень для выпечки посыпать мукой или выстелить пергаментом. Выложить тесто в виде сердечка или круга, острым ножом сделать надрезы, печь в духовке при температуре 250 градусов в течение 40–50 минут. При готовности должна образоваться золотистая корочка. Готовый хлеб выложить на решетку, накрыть полотенцем и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Выкладываем хлеб, предварительно избавившись от корочек и разрезав его на кусочки, и заливаем молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Режем лук и прожариваем на сливочном или растительном масле. Только не до золотистой корочки — в этом блюде корочка лука не важна, главное, его консистенция. Необходимо, чтобы он стал мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Прокручиваем мясо на мясорубке. И свинину, и говядину желательно прокрутить вместе, равномерно чередуя кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7330,'Лепим котлетки или мясные фрикадельки и обкатываем их в панировочных сухарях. Если их под рукой не оказалось, то вполне сгодится и мука.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Спассировать на масле муку, всыпать нарезанную небольшими кубиками корейку, залить бульоном от варки свинины, проварить соус полчаса, процедить, вылить на зразы, заправить сметаной и тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7331,'Перед подачей к столу зразы из говядины и свиного фарша по-румынски освободить от ниток и зубочисток, украсить дольками лимона, на гарнир сварить рассыпчатый рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7332,'Очистить от пленок и сухожилий мясо, нарезать на 5 пластин, хорошо отбить, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7332,'Разогреть половину масла, поджарить до прозрачности лук, всыпать рис и порезанные грибы, обжарить 10 минут, залить бульоном, подсолить и поперчить, убрать тушить на 20 минут в нагретую духовку, остудить готовую начинку, смешать с измельченной зеленью и яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7332,'Разложить начинку равномерно на мясо, свернуть пластины в рулеты, обвязать нитками или скрепить зубочистками, переложить на противень, смазанный маслом, зарумянить в духовке 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7332,'Смешать и взбить сметану, вино и муку, залить зразы и тушить еще 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7332,'Нарезать и отварить картофель, отдельно – зеленый горошек, зразы из говядины с грибами, рисом и зеленым горошком подать с картофелем, украсить веточками петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7333,'Печенье поломать на кусочки, измельчить в блендере в крошку. Растопить сливочное масло, добавить в печенье, перемешать. Добавить домашний творог, сахарную пудру, вымесить массу руками. Вымыть и очистить свежую клубнику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7333,'Отщипывать от теста небольшие кусочки, разминать в лепешки, в середину положить по ягодке. Скатать шарик так, чтобы ягода оказалась внутри. Творожные шарики обвалять в кокосовой стружке, выложить на блюдо и поставить в холодильник на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7334,'Просеять на стол муку в виде конуса, сделать на вершине углубление, засыпать половину семян тмина, вбить 2 целых яйца и 1 белок, добавить размягченное масло соль и молоко, вымесить тесто до мягкости и убрать на 30 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7334,'Включить нагреваться духовку, достать тесто и раскатать до толщины 0,5 см, нарезать брусочки длиной около 10 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7334,'Переложить полоски на смазанный маслом противень, покрыть взбитым яичным желтком и присыпать тмином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7334,'Выпекаются соленые палочки из теста с тмином по-румынски на среднем огне до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7335,'Для приготовления теста перемешать небольшое количество молока с сырым яйцом, желтком, пшеничной мукой, солью и ванильным сахаром из пакетика. Массу перемешать, в ней не должно быть комочков. Ввести остатки молока, тесто должно получиться жидким. Оставить на 20 минут для набухания, затем испечь восемь блинчиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7335,'Отдельно смешать мягкое сливочное масло с пудрой, ванилином, цедрой, взбить. Добавить сырые желтки, сметану и протертый творог. Взбить с сахаром белки, соединить с творожной массой, всыпать изюм без косточек. Смазать блинчики получившейся начинкой, свернуть в трубочку, разрезать пополам, уложить в предварительно смазанную форму для выпекания разрезами вверх, как «черепицу».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7335,'Поставить блюдо в духовой шкаф на 10 минут, температура–180 градусов. Приготовить заливку: смешать молоко, сырое яйцо, желток, сахарный песок и сметану, массу взбить. Залить смесью австрийские блинчики с творогом, печь в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7336,'Зеленую чечевицу залить водой и варить под крышкой, не доводя до кипения, в течение 15 минут на тихом огне. В большой сковороде на среднем огне обжарить нарезанный лук-шалот и рубленый чеснок до полупрозрачного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7336,'Добавить рубленую зелень свежего тимьяна, сушеный базилик и орегано, хлопья красного перца, нарезанный сладкий зеленый и красный болгарский перец, очищенный от семян. Смесь жарить в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7336,'Отдельно смешать нарезанные свежие или консервированные томаты, зеленую нарезанную петрушку, соль по вкусу, прогреть. Влить массу в основную. Сверху выложить готовую поленту толстым слоем. Печь пастуший пирог в течение 15 минут, можно еще посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7337,'Филе курицы нарезать брусочками, очистить и мелко нарезать репчатый лук. Вылить на сковороду растительное масло, разогреть на сильном огне. Выложить мясо, обжарить до побеления, активно помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7337,'Всыпать лук, перемешать, жарить еще две–три минуты, посолить по вкусу, посыпать карри. Долить сливки, перемешать, блюдо довести до кипения. Тушить на тихом огне, без крышки, через 20 минут соус должен загустеть. Подать куриное филе карри с отваренным рисом, не перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7338,'Для теста растопить в кастрюльке сливочное масло, разбавить его молоком. Смесь должна быть теплой, добавить в неё сухие дрожжи, сахарный песок и соль. Перемешать, дать постоять в течение пяти минут. Всыпать порциями просеянную муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7338,'Приготовить несколько начинок, например, картофельное пюре с обжаренным луком и отваренным мясом, пропущенным через мясорубку, или вареные накрошенные яйца с зеленым луком. Тесто выложить на присыпанную мукой поверхность, немного вымесить. Разделить на шесть одинаковых кусочков, каждый раскатать в прямоугольник толщиной три миллиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7338,'Начинку выложить вдоль длинной стороны, свернуть в рулет, защипать края. Ребром ладони «распилить» колбаску на кусочки. Выложить пирожки-малышки на противень, печь при температуре 180 градусов при температуре 25–30 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7339,'Для приготовления теста взбить сырые куриные яйца с сахарным песком. Всыпать просеянную пшеничную муку с разрыхлителем, перемешать. Тесто должно получиться средней густоты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7339,'Противень смазать маслом, можно выложить бумагой для выпекания, если использовать силиконовый коврик – жир не понадобится. Наливать по чайной ложке теста на некотором расстоянии друг от друга. Печь в течение пяти минут при температуре 180 градусов. Заготовки накрыть полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7339,'Для приготовления крема перемешать сметану с сахарным песком и какао-порошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7339,'Заготовки обмакивать в крем, выкладывать на плоское блюдо. Таким образом сделать несколько слоев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7339,'Приготовить глазурь из сахара, сметаны и какао. Массу прогреть, но не кипятить, покрыть торт «Черепаха», украсить шоколадом. Выпечку можно недолго подержать в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7340,'Приготовить фарш из куриного филе, смешать с мелко нарубленным репчатым луком, чесноком, пармезаном, сырым яйцом, соль и молотый перец – по вкусу. Панировочные сухари насыпать в тарелку. Сформовать шарики, обвалять в сухарях, выложить на застеленный бумагой противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7340,'Печь в течение получаса при температуре 190 градусов. В большую емкость налить томат-пасту и нагреть на тихом огне. Довести массу до кипения, выложить готовые шарики, тушить под крышкой в течение получаса. При подаче фрикадельки из куриного филе посыпать тертым сыром моцарелла, он должен немного расплавиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Протереть сквозь крупную терку вареную морковь и огурцы, если кожица на огурцах жесткая, то лучше ее срезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Нашинковать лук мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Яйца сварить, дать остыть, отделить белки от желтков и натереть в отдельные емкости тоже на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Нарезать рыбу тонкими пластинками, оставить 5 штук на оформление салата, остальную рыбу нарезать на кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Открыть консервированную кукурузу и слить всю жидкость, добавить ее к моркови, белкам и огурцам, посолить, заправить майонезом и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7341,'Выстелить плоское блюдо листьями зеленого салата и выложить на него салат, сверху уложить на него кубики рыбы, посыпать натертыми желтками, украсить салат «Новогодние огни» из яиц, семги и овощей сеточкой из майонеза, розой из ломтиков рыбы, красной икрой и веточками петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7342,'Испечь два или три «коричневых» блинчика с добавлением какао-порошка. Сливочный сыр смешать с сахарной пудрой. Блинчики обрезать квадратами, намазать сладкий сыр. Произвольно нарезать очищенный киви и клубнику. Выложить на слой сыра, сверху также покрыть сыром и плотно завернуть. Нарезать роллы на кусочки, украсить тертым шоколадом и фруктами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7343,'Замочить деревянные шпажки на час в воде. Гриль нагреть до средней температуры. Кусочки лосося насадить, чередуя с дольками лимона. Сбрызнуть изделия оливковым маслом, соль и молотый перец – по вкусу. Выжать сверху половину лимона. Жарить на гриле в течение трех минут до готовности рыбы. Шпажки снять с огня, подождать пять минут. Подать лосось-гриль с соусом Дзадзики и лимоном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7344,'Тонкими полукольцами нарезать репчатый лук, стебель сельдерея – поперек, ломтиками, красный острый перец – колечками. Чтобы уменьшить его остроту, семена можно удалить. Овощи обжарить до прозрачности лука, помешивать. Говяжью вырезку очистить от пленок и нарезать соломкой поперек волокон. Обжарить на сильном огне, помешивая, до изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7344,'Добавить красную консервированную фасоль в собственном соку и томатное пюре. Массу прогреть, посолить по вкусу, лишняя жидкость должна выпариться. В конце добавить мелко нарезанный лук. Готовые тортильи прогреть на сухой сковороде с обеих сторон, можно воспользоваться микроволновой печью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7344,'Лепешки должны стать мягкими. В каждую завернуть начинку, свернуть «кулечком», один край должен остаться открытым. Нижнюю часть буррито с красной фасолью и говядиной обернуть фольгой, чтобы было удобно держать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7345,'Смешать сметану с солью и перцем, давленым чесноком, лимонной цедрой, рубленым зеленым луком и петрушкой. Всыпать панировочные сухари, перемешать. Форму для запекания смазать маслом, выложить куриные грудки, поверх вылить смесь со сметаной, посыпать тертым сыром. Печь при температуре 200 градусов в течение 20–25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7346,'Нарезать репчатый лук, натереть морковь. Овощи обжарить на сковороде до готовности. Накрошить в салатницу отваренное куриное мясо, добавить красную и белую консервированную фасоль. Салат «Обжора» заправить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7347,'Рыбу очистить, посолить и поперчить. Нагреть оливковое масло на сковороде, выложить рыбу, жарить в течение 6–8 минут на несильном огне. Тушку перевернуть и обжарить с другой стороны. Выложить на рыбу нарезанные зеленые оливки, каперсы, помидоры черри колечками, нарезанный соломкой и обжаренный красный болгарский перец, это можно сделать на гриле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7347,'Готовить три минуты. Залить блюдо белым сухим вином, дать алкоголю впитаться, посолить по вкусу. Посыпать рубленой петрушкой. Огонь выключить, при подаче сбрызнуть жареную камбалу  оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7348,'Разделать на филе очищенную от шкурки сельдь, промыть, обрезать с белого батона корки и замочить в воде, нарезать крупными кусками лук и кислое яблоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7348,'Хлеб отжать и пропустить все дважды через мясорубку, добавить к пасте мягкое сливочное масло, посолить, поперчить, сбрызнуть лимонным соком и хорошо перемешать, добавить по вкусу чуть сахара и убрать на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7348,'Нарезать отварной картофель и очищенные от семян кисло-сладкие яблоки на кружочки, сбрызнуть их лимонным соком, каждый кружок смазать форшмаком и чередуя собрать в четырехслойные башенки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7348,'Украсить салат «Башня» с форшмаком из сельди зеленью петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7349,'Подготовить мясо, очистить от пленок и сухожилий, обсушить бумажным полотенцем, включить разогревать до средней температуры духовку, втереть равномерно в кусок телятины соль и перец, нашпиговать салом, смазать лист для запекания жиром и переложить мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7349,'Влить к телятине вино и отправить примерно на полтора часа в духовку, если мясо суховатое, то необходимо периодически подливать на противень бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7349,'Порезать готовое фрикандо из телятины в вине на ломти и подать с овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7350,'Куриные яйца отварить и нарезать кружочками. Измельчить зелень укропа, добавить в сыр филадельфия, перемешать. Масса должна получиться однородной. Несколько формочек, чашечек или глубоких рюмок выстелить пищевой пленкой, края должны свисать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7350,'Выложить ломтики малосольного лосося, заполнить формы начинкой, положить кусочки крабовых палочек, снова начинка. Сверху – кружок яйца, закрыть ломтиком рыбы. Края пленки завернуть, плотно прижать и утрамбовать. Поставить в холодильник на несколько часов. Нарезать кружками лимон, выложить на блюдо, перевернуть на него чашечки с сырной закуской.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7351,'Поставить сито в кастрюлю, положить в него чистую и плотную ткань, можно полотенце, вылить сметану. Накрыть содержимое краями, убрать заготовку на ночь в холодильник. Назавтра смешать отцеженную массу с сахарным песком и взбить при помощи миксера. Сметанный крем должен быть густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8332,'Подавать оладьи на кефире с зеленым луком в горячем виде с йогуртом или сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7352,'Шампиньоны маленького размера вымыть, посолить и посыпать сахаром, корейской или любой кавказской приправой, полить уксусом, тушить в течение 10 минут. Добавить растительное масло, крупно нарезанный лук и чеснок. Потушить сочные грибочки в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7353,'Вымыть яблоки, вырезать сердцевину. Сделать небольшие проколы или надрезы по всей окружности плода, чтобы кожица не лопнула при термообработке. Отдельно смешать коричневый сахарный песок, молотую корицу, кедровые орешки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7353,'Полить внутри яблоки лимонным соком, выложить в смазанную сливочным маслом форму. В каждый фрукт положить ореховую начинку, сверху – «пробка» из сливочного масла. Печь в духовке при температуре 45–50 минут до мягкости. Во время приготовления запеченные яблоки поливать сиропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7354,'Сварить хороший, крепкий, кофе. Добавить по вкусу сахар и ликер, смесь перемешать. Взбить в пену сырые желтки с сахаром. Отдельно взбить белки в крепкую пену. Взбить венчиком сыр маскарпоне. Добавлять в сырную массу желтковую массу, порциями, каждый раз взбивать с помощью блендера на низкой скорости. Масса должна быть однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7354,'Затем по ложке добавить взбитый белок, осторожно перемешивать лопаткой. Немного получившегося сырного кремы выложить на дно формочки. Печенье савоярди обмакнуть в сироп, сразу же выкладывать на слой крема. Сделать два или три слоя, это зависит от высоты формы. Накрыть десертную массу кремом, украсить какао-порошком, его можно насыпать через сито. Поставить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7355,'Выжать сок из мякоти лимонов, смешать с ягодами малины. Соединить сырые куриные яйца с сахарным песком, перемешать. Лимонную смесь нагреть почти до кипения, ввести в яичную смесь, помешивать. Поставить на тихий огонь, варить до полного загустения. В готовый крем добавить сливочное масло и охладить. Для приготовления желе нагреть воду, добавить в неё малиновый сироп и желатин или агар-агар. Массу хорошо перемешать, дать закипеть, варить в течение двух минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7355,'Получившуюся массу вылить в емкость с большой площадью, слой не должен превышать пяти миллиметров, он должен застыть при комнатной температуре. Для бисквита перемешать растворимый кофе и какао-порошок в горячей воде, смесь должна получиться однородной и гладкой, остудить. Смешать в большой миске пшеничную муку, разрыхлитель, соду и соль, сахарный песок. Взбить сырые желтки, соединить их с растительным маслом без запаха, кофейной смесью, перемешать. Соединить мучную массу с шоколадно-масляной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7355,'Отдельно взбить в крепкую пену белки, добавить в шоколад, перемешать снизу вверх с помощью лопатки, порциями. Готовую бисквитную массу вылить в форму, печь при температуре 180 градусов в течение 40–50 минут, проверить готовность деревянной зубочисткой, она должна остаться сухой. Готовую выпечку остудить и вынуть из формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7355,'Для крема взбить сливки с сахарной пудрой до вязкости, добавить белый шоколад, растопленный на водяной бане. Остывший бисквит разрезать на две части по горизонтали острым ножом, обе половинки смазать кремом из сливок, на нижнюю часть нанести лимонно-малиновую начинку, накрыть второй половиной бисквита. Верх и бока торта смазать сливочным кремом, дать немного застыть. Украсить готовое блюдо маленькими кубиками желе, розочками, вылепленными из мастики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7356,'Крупу хорошо промыть и дать стечь жидкости. Налить в кастрюлю две чашки воды, довести до кипения, положить рис. Перемешивать не нужно, дать каше закипеть, убавить огонь, варить в течение 15–20 минут до полного выкипания воды. Масса не должна пригореть. Свежий ананас очистить от кожуры, удалить сердцевину, нарезать ломтиками. Сковороду нагреть, выложить ломтики ананаса, жарить по две минуты с каждой стороны без масла, до золотистого цвета. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7356,'Мелко нарезать репчатый лук и чеснок, остывший ананас–кубиками. На среднем огне разогреть оливковое масло, добавить чеснок и лук, обжарить до прозрачности. Выжать апельсиновый сок, добавить сахар, перемешать. К луку добавить сок и ананасы, тушить на среднем огне до выпаривания жидкости. Ананасы смешать с рисом. При подаче полить рис с ананасом соевым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7463,'Смешать все подготовленные ингредиенты, аккуратно переложить в форму, разровнять специальной лопаткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7357,'Нарезать на кусочки багет, сбрызнуть оливковым маслом, сверху выложить помидоры, нарезанные на четыре части, посыпать тертый сыром моцарелла. Блюдо посыпать сухими итальянскими травами: базиликом, тимьяном, орегано. Поставить гренки в духовку, разогретую до 220 градусов на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7358,'Разделать грудинку телятины на кусочки по 2 на порцию, втереть в них соль с перцем и зарумянить на сковороде с растительным маслом, добавить мелко порезанный лук, томатную пасту, муку, влить литр теплой воды с вином, убавить огонь и проварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7358,'Очистить и промыть корень сельдерея, нарезать брусочками примерно по 1,5 см и обжарить на раскаленном масле, переложить в кастрюлю, залить оставшимся от мяса соусом, проварить до готовности на медленном огне, включить разогреваться духовку до средней температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7358,'Растопить в небольшой кастрюле до светло-коричневого цвета сахар с ложкой воды, убрать с плиты и влить столовую ложку теплой воды, перемешать, вылить карамель к сельдерею, добавить куски мяса и на 10 минут отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7358,'Телятина тушеная по-румынски с сельдереем подается к столу горячей и посыпанной рубленой зеленью петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7359,'Отварить куриные яйца, очистить. Мелко нарезать отваренную куриную грудку. Разбить семь яиц, добавить мясо, специи, взбить с помощью блендера в течение нескольких минут. Форму смазать растительным маслом, посыпать манной крупой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7359,'Вылить половину получившейся массы, выложить яйца в ряд, залить оставшимся тестом. Печь омлет «Мишна» при температуре 220 градусов в течение 20 минут, до готовности. Дать блюду немного остыть в форме, затем перевернуть на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7360,'Капустные листья нарезать на прямоугольники или квадраты. Натереть морковь, свеклу также натереть или мелко нарезать. Выложить продукты слоями в кастрюлю: капуста, морковь, свекла, капуста. Каждый слой пересыпать рубленым чесноком. Можно, по желанию, добавить острый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7360,'Приготовить маринад из воды, сахарного песка, соли, лавровых листа, горошин черного душистого перца. Довести до кипения, снять с огня, влить столовый уксус, смесью залить капустную массу. Сверху накрыть массу тарелкой, положить груз. Капуста с чесноком в маринаде будет готова через три дня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7361,'Укроп вымыть, обсушить, сорвать нежные веточки. Сливочное масло размягчить при комнатной температуре. Измельчить в блендере укроп с очищенным чесноком. Вмешать все это в масло, посолить по вкусу, влить несколько капель лимонного сока. Выложить массу на циновку для суши, застеленную пленкой. Сформовать колбаску, завернуть, поставить чесночно-укропное масло в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7362,'Сырые куриные яйца смешать с сахарным песком, взбить в течение нескольких минут до получения пышной светлой массы. Всыпать просеянную пшеничную муку, влить сливки, в которые добавлена ванильная мякоть или сахар. Смесь перемешать. Формочки смазать сливочным маслом, посыпать мукой, выложить тесто на две трети объема. В центр каждой формочки положить по кусочку молочного шоколада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7362,'Печь в течение получаса при температуре 180 градусов. Готовые бисквиты охладить, затем вынуть из формочек. Для приготовления глазури растопить в микроволновой печи сливочное масло и молочный шоколад по отдельности, затем смешать. Можно воспользоваться водяной баней. Всыпать какао-порошок, перемешать и полить сливочные кексы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7363,'Приготовить блинчики, для них понадобится пшеничная мука, сырые куриные яйца, сливки, ванилин, молоко, соль и сахарная пудра. Все ингредиенты смешать с помощью блендера или вручную, тесто должно напоминать по консистенции густые сливки. Разогреть на сковороде масло, обжаривать блины только с одной стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7363,'Для начинки: взбить на большой скорости сливки. Постепенно всыпать сахарный песок, смесь должна загустеть. Затем добавить какао-порошок, Амаретто и экстракт миндаля. Массу еще раз взбить в плотную пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7369,'Разогреть остаток сливочного масла, обжарить муку, но не до желтого цвета, влить бульон, дать закипеть, процедить, заправить сметаной, лимонным соком, перцем, солью, вылить на мясо с овощами и прокипятить 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7463,'Сырный хлеб с луком в духовке выпекать полчаса при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7363,'Для крема нагреть на тихом огне жирные сливки, положить наломанный кусочками темный шоколад, перемешать, шоколад должен растопиться. Также влить немного Амаретто, смешать до однородности. Каждый слой блинчиков промазать и шоколадным кремом, и начинкой. Остатками крема покрыть весь торт из блинов сверху и с боков. Перед подачей блюдо охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7364,'Сырые куриные яйца взбить с сахарным песком, добавить вишневое или смородиновое варенье. Отдельно смешать кефир с пищевой содой, влить в основную массу. Всыпать пшеничную муку, перемешать. Тесто не должно быть густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7364,'Выпечь два коржа на противне с высокими бортиками, печь в течение 20–25 минут, затем каждый разрезать на две части по горизонтали. Коржи торта «Трухлявый пень» пропитать сиропом или водой, смешанной с вареньем. Для крема взбить сметану с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7365,'Клубни картофеля очистить и быстро натереть, мякоть не должна успеть потемнеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7365,'Репчатый лук также натереть или измельчить с помощью блендера, добавить в картошку. Излишки жидкости слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7365,'Массу посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7365,'Разогреть на сковороде растительное масло, выложить тесто ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7365,'Жарить картофельные драники на среднем огне с двух сторон до золотисто-коричневой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7366,'Сливочное масло или маргарин размягчить до комнатной температуры, смешать с сахарным песком. Добавить мед или патоку, сырой желток. Отдельно смешать пшеничную муку, соль, пищевую соду, разрыхлитель. Всыпать специи: молотую корицу, гвоздику, мускатный орех, измельченный имбирь. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7366,'Массу завернуть в пищевую пленку, поставить в холод на час. Присыпать рабочую поверхность мукой или постелить силиконовый коврик, раскатать охлажденное тесто в пласт, толщиной полсантиметра. С помощью формочек вырезать фигурки, разложить на застеленном пергаментом противне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7366,'Печь в течение 8–10 минут при температуре 180 градусов. Края должны подрумяниться. Приготовить глазурь из яичного белка, лимонного сока, сахарной пудры. Перемешать, полить имбирное печенье и дать застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7367,'Перемешать пшеничную муку, какао-порошок, картофельный крахмал, соль, пищевую соду. С помощью миксера взбить в течение трех минут мягкое сливочное масло с двумя видами сахара: обычным и коричневым. Вбить сырое яйцо и добавить ванилин. Постепенно, на низкой скорости, всыпать мучную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7367,'Перемешать до однородности, добавить M&M’s. С помощью чайной ложки выложить небольшие порции теста на противень на некотором расстоянии друг от друга. Печь в течение восьми минут, края выпечки должны затвердеть. Мягкое шоколадное печенье остудить на решетке, переложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7368,'В миске перемешать пшеничную муку, сахарный песок и соль. Развести смесь из сухих и свежих дрожжей в подогретом молоке. Влить полученную смесь в муку, перемешать. Оставить на 15 минут, когда появятся пузыри – вбить желток и яйцо целиком, добавить растопленное сливочное масло, лимонную цедру и изюм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7368,'Перемешать массу, замесить тесто. Накрыть емкость с тестом крышкой или тканью, оставить на час в тепле. Когда масса увеличится вдвое – разрезать её на девять частей. Из каждой скрутить длинную и толстую «колбаску», из четырех сплести «косичку», края закрепить. Остальные «жгуты расположить справа и слева, переплести по своему усмотрению, закрепить зубочистками, оставить «плетенку» под полотенцем еще на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7368,'Заготовку смазать взбитым яичным белком и украсить миндальными хлопьями. Печь чешский пирог «Ваночка» в течение 50 минут при температуре 175 градусов до образования золотисто-коричневой корочки. Готовую выпечку посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7369,'Нарезать телятину одинаковыми ломтиками, посолить, поперчить, обжарить мясо на части сливочного масла, добавить мелко порезанный лук и чуть перца, обжаривать пока лук не станет золотистым, залить все бульоном и довести до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7369,'Нарезать кружками морковь, картофель, сельдерей, почистить лук-сеянец и грибы, отварить все в соленой кипящей воде, слить воду, переложить овощи к мясу, перемешать и прокипятить несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Измельчить зелень, лук, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7370,'Пшеничную муку вместе с разрыхлителем и солью просеять в небольшую посудину. Нарезать кубиками сливочное масло, добавить в сухую смесь. Перетереть руками в мелкую крошку. Мелко порубить лепестки свежего розмарина или тимьяна, добавить в тесто вместе с тертым сыром пармезан или любым другим сортом, твердым или полутвердым. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7370,'Влить натуральный йогурт и молоко, можно обойтись одним молоком. Вымесить тесто, выложить на посыпанную мукой рабочую поверхность, раскатать в круг толщиной два сантиметра. Вырезать кружочки с помощью формочки, ее лучше обмакивать в муку, чтобы тесто не прилипало. Противень смазать сливочным маслом, присыпать мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7370,'Сконы разложить на некотором расстоянии друг от друга, смазать немного взбитым желтком. Присыпать тертым сыром, украсить листочками розмарина. Печь при температуре 220 градусов в течение 15–20 минут, булочки-сконы должны подняться и приобрести золотистую корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7371,'Смешать просеянную пшеничную муку, сахарный песок, сухие дрожжи и соль. Отдельно перемешать жидкие ингредиенты: молоко, яйца, растопленное сливочное масло. Смесь должна быть комнатной температуры или чуть теплее. Обе смеси соединить, замесить тесто. Всыпать муку, масса должна получиться мягкой и эластичной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7371,'Положить тесто в большую емкость, накрыть пищевой пленкой, поставить в тепло для подъема, на это потребуется от 40 минут до часа. При увеличении массы в два раза её нужно обмять, снова оставить, и еще раз обмять. Раскатать готовое тесто в прямоугольную лепешку толщиной около сантиметра. Смазать ее растопленным сливочным маслом, посыпать сахарным песком, какао-порошком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7371,'Отдельно замочить в кипятке изюм, дать набухнуть, слить и подсушить. Свернуть тесто в виде плотного рулета с короткой стороны. Нарезать ломтями толщиной полтора-два сантиметра. Застелить бумагой противень, выложить заготовки для булочек, оставить между ними свободное пространство. Смазать взбитым яйцом, печь завиванцы с изюмом в течение получаса при температуре 180 градусов, до образования золотисто-коричневой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7372,'Сырые куриные белки взбить в пену, постепенно, порциями, всыпать сахарный песок. Взбить в плотную массу. В другой емкости смешать пшеничную муку, остатки сахара, соль и разрыхлитель. Массу взбивать с помощью миксера на средней скорости, добавить растительное масло, ванилиновый экстракт, молоко. Смесь взбивать в течение 30 секунд, затем влить остатки молока, добавить сырые желтки. Перемешать до однородного состояния, ввести белки. Перелить тесто в смазанную форму, печь в течение 50–60 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7372,'Выпечку вынуть из духовки, остудить в форме в течение 15–20 минут, вынуть и полностью остудить. Корж разрезать по горизонтали на три равные части. На нижнюю часть намазать клубничный или малиновый джем, сверху – взбитые сливки. Остальные коржи также промазать. Остатки сливок нанести по всей поверхности торта, украсить фруктами, ягодами. Поставить норвежский торт с фруктами в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7373,'Отварить говядину, разобрать на волокна. Натереть соленые огурцы, пропустить через пресс чеснок и перемешать с огурцами. Отварить куриные яйца и также натереть. Очистить и нарубить грецкие орехи, немного обжарить на сухой сковороде. Выложить салат слоями: мясо, майонез, огурцы с чесноком, майонез, отваренные яйца, майонез. Верх посыпать грецкими орехами. Поставить салат «Принц» в холодильник для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7374,'Баклажан вымыть и нарезать вдоль в виде тонких полосок. Посолить, положить в миску, оставить на полчаса, чтобы ушла горечь. Баклажан вымыть и высушить, сбрызнуть оливковым маслом и обжарить на гриле. Для начинки смешать сыр фета, рубленые орехи, йогурт, специи по вкусу. Паста должна получиться густой. Полоски баклажана остудить, намазать начинкой, свернуть и закрепить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7375,'В кастрюлю с толстым дном влить воду, добавить душистый перец, майоран, лавровый лист, молотый перец, сахарный песок, соль, чеснок, майонез. Смесь вскипятить, остудить. В готовый холодный маринад положить свиное филе без костей, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Намазать начинку на отбивные и свернуть в рулеты, перевязать нитками или сколоть зубочистками. Переложить рулеты на противень, залить водой (1/2 стакана), плотно закрыть фольгой и убрать в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7375,'Варить мясо в течение пяти минут, снять с огня. Оставить мясо в рассоле на ночь, утром довести до кипения и снова поварить в течение пяти минут. Оставить на несколько часов. Филе вынуть, обернуть фольгой или бумагой, хранить экспресс-буженину в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7376,'Мягкое сливочное масло или маргарин взбить с сахаром, добавить по одному сырые яичные желтки, продолжать взбивать. Вмешать картофельный крахмал, пшеничную муку, влить воду. Отдельно взбить в пену белки, добавить в тесто, осторожно перемешать. Тесто должно получиться полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7376,'Выпечь трубочки в вафельнице в течение двух или трех минут. Готовую выпечку осторожно снять лопаткой или ножом, в горячем виде свернуть в трубочки, переложить на блюдо. Начинить вафельные трубочки можно любым кремом, например сметанным или приготовленным из сгущенного молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7377,'Опустить пасту в кипящую воду, варить в течение десяти минут. Сырые куриные яйца взбить с тертыми сырами пекорино и пармезаном. Нарезать тонкой соломкой панчетту, обжарить, добавить яйца. В полученную массу переложить пасту, перемешать. Украсить спагетти карбонара тертым сыром пармезан, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7378,'Два противня застелить бумагой для выпечки. Готовое слоеное тесто разморозить и раскатать в квадрат. Взбить венчиком в миске сырое яйцо, воду, молотый перец и сухую горчицу. Этой острой смесью смазать тесто. Присыпать лепешку тертым сыром, зеленью рубленого тимьяна и розмарина, солью. Начинку немного прижать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7378,'Нарезать тесто на неширокие полоски, скрутить в виде «спиралек», начинка должна оказаться на внутренней стороне. Переложить на противень и печь при температуре 190 градусов в течение 10–15 минут, должна образоваться золотистая корочка. Пряные сырные палочки перевернуть и печь еще три-четыре минуты. Подать блюдо в теплом виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7379,'Положить подготовленный язык в кастрюлю с подсоленной водой, варить до готовности, достать, обдать холодной водой, снять кожу и нарезать кубиками, бульон процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7379,'Обжарить на жире мелко нарезанный лук, добавить морковь порезанную кубиками, нашинкованную капусту и потушить почти до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7379,'Залить овощи смесью после варки языка и говяжьим бульоном, добавить язык, ломтики черного хлеба, дать закипеть и положить кубики картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7379,'Борщ из свиного языка по-польски варить на сильном огне 15 минут, заправить перцем, солью, снять с плиты, перед подачей дать настояться, отдельно подать сметану и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7380,'Киви очистить, лайм нарезать на дольки, добавить листочки свежей мяты. Ингредиенты выложить в большой бокал, хорошо раздавить с помощью толкушки, фрукты должны пустить сок. Добавить лед в пропорции две трети к одной трети фруктовой массы. Влить жидкий мед, имбирный эль, перемешать. Добавить содовую, перемешать. Бокал украсить долькой очищенного киви и мятой. Подать детский коктейль «Мохито» с соломинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7381,'Плоды разрезать вдоль на две половины. Ножом сделать надрезы на мякоти крест-накрест, посыпать солью, оставить на 20–30 минут, за это время уйдет горечь. Промыть, отжать. Нарезать репчатый лук небольшими кубиками, обжарить на оливковом масле до золотистого цвета. Прокрутить мясо через мясорубку, добавить в луковую обжарку, прогреть в течение 20 минут, соль и перец–по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7381,'Нарезать маленькими кубиками шампиньоны, обжарить на оливковом масле, посолить и поперчить. Из баклажан вынуть мякоть ложкой, нарезать, обжарить на оливковом масле пять-семь минут. В «лодочки» выложить слоями: мясной фарш с луком, баклажановую мякоть, грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7381,'Посыпать начинку тертым чесноком. Печь при температуре 200 градусов в течение 10 минут. Залить блюдо сметаной, посыпать тертым сыром и мелкорубленной зеленью, печь фаршированные баклажаны еще 10 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7382,'Готовое слоеное тесто разморозить при комнатной температуре, накрыв тканью, чтобы не образовалась корочка. Вырезать по восемь прямоугольников из каждой пластины. Отдельно немного взбить желток, смазать им тесто, печь при температуре 200 градусов в течение 12–15 минут до образования золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Свиные рулеты с яблоком и яйцом будут готовы через 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'В брюшко рыбы положить петрушку, лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7382,'Для приготовления крема сливки нужно взбить с сахарной пудрой, добавить сыр маскарпоне, перемешать. Готовые прямоугольники разрезать на три части каждый, промазать сливочным кремом и украсить десерт «Мильфей» свежей клубникой или ежевикой, кусочками любых фруктов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7383,'Банан разрезать пополам, выложить на него шарики мороженого. Посыпать сладостями, теми, что найдутся в холодильнике: зефиром, маршмаллоу, кондитерской посыпкой, полить сплит фруктовым соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7384,'Миндальные орехи залить кипятком, очистить от кожуры, затем смолоть ядрышки с помощью кофемолки. Для приготовления коржа растереть сливочное масло с сахаром, добавить сырые яйца и перемешать. Всыпать пшеничную муку и разрыхлитель, замесить тесто. Форму для выпекания смазать маслом или выстелить бумагой, выложить тесто, сформовать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7384,'На тесто также постелить бумагу для выпечки, насыпать горох или фасоль, поставить в горячую духовку, печь при температуре 180 градусов в течение 20 минут. При готовности наполнитель убрать, его можно использовать многократно. Корж остудить. Для начинки залить яблоки водой, посыпать сахаром, добавить лимонный сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7384,'Поставить вариться на средний огонь, через 15 минут добавить немного Sheridan’s. Остудить фрукты в сиропе, разрезать пополам и вынуть косточки. Для приготовления франжипана перемешать готовый молотый миндаль, сахар, муку, вбить яйца и мягкое сливочное масло комнатной температуры. Перемешать массу до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7384,'Выложить на остывший песочный корж франжипан, половинки яблок, располагая их срезом вниз, немного «утопить». Печь яблочный пирог в течение получаса при температуре 200 градусов. Готовое блюдо остудить и нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7385,'Очистить судака, приготовить филе, нарезать на куски, обвалять в муке и слегка обжарить, нашинковать капусту, лук нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7385,'Переложить овощи в сотейник, добавить шампиньоны, нарезанные пластинками, тушить 10 минут, добавить натертое яблоко, томатную пасту, лавровый лист, несколько гвоздичек, подсолить, поперчить, перемешать, выложить сверху рыбу, закрыть крышкой и тушить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7385,'Подавать бигос с судаком по-польски можно и горячим, и холодным с консервированными помидорами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7386,'Спелую, сладкую, грушу разрезать пополам, удалить сердцевину, сверху сделать надрезы по всей длине. Готовое слоеное тесто из магазина раскатать, положить плод, отрезать лишнее, отступив от края груши по полтора сантиметра, грушу немного вдавить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7386,'Тесто смазать яйцом, взбитым со щепоткой сахарного песка. В надрезы насыпать тростниковый сахар. Печь груши в слоеном тесте при температуре 180 градусов в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7387,'Протереть творог через сито, добавить сок и цедру половины лимона, всыпать сахарную пудру, влить натуральный йогурт без добавок и красителей. Массу хорошо перемешать. Замочить желатин так, как написано на пакетике, в холодной кипяченой воде. Отдельно вскипятить молоко, немного остудить, добавить желатин, прогреть до растворения на тихом огне. Добавить смесь в творог, перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7387,'Удалить плодоножки у свежей клубники, разрезать каждую ягоду пополам. Форму для приготовления десерта выстелить пищевой пленкой. Выложить половину приготовленной творожной массы. Ягоды превратить в пюре с помощью блендера, добавить сахарную пудру и белое сухое вино, вылить начинку на творог, сверху–оставшийся творог, поставить блюдо в холодильник для застывания. При подаче перевернуть десерт из творога на блюдо, полить клубничным соусом сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7388,'Для приготовления теста перемешать мягкое сливочное масло с сахарным песком и ванилином из пакетика. Добавить сметану, перемешать. Смешать пшеничную муку с разрыхлителем, сухую смесь соединить с жидкой. Вымесить тесто, оно должно быть гладким и эластичным. Разделить готовую массу на 16 частей. Каждый кусочек скрутить в жгутик длиной 20 сантиметров, раскатать скалкой, ширина полоски – восемь сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Достать противень, снять фольгу, полить рулетики выделившимся соком, поставить на 5 минут в духовку для зарумянивания, противень опять накрыть фольгой, дать остыть и снять нитки, подавать можно как горячее блюдо, так и в качестве холодной закуски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7388,'Смешать свежую, консервированную или размороженную вишню с сахаром и картофельным крахмалом. В середину раскатанной лепешки положить ягоды, края соединить и защипать, должно получиться «бревнышко». Положить заготовку швом вниз. Все «бревнышки» должны быть одинакового размера. Одну лепешку оставить без вишневой начинки, это будет основа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7388,'Противень выстлать бумагой, выложить «бревнышки» порознь и выпечь в течение 15 минут при температуре 200 градусов. Также выпечь основу-лепешку. Для крема смешать сметану с сахарным песком, массу взбить. Формируем торт: основу намазать сметаной, выложить «полешки», сначала пять штук, потом четыре, три, два, одно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7388,'Можно положить в основание больше «бревнышек», торт будет большего размера. Каждый слой промазывать сметанным кремом. Верх выпечки смазать кремом, посыпать рублеными грецкими орехами и тертым шоколадом. Оставить торт «Монастырская изба» с вишней на шесть-восемь часов для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7389,'С птицы аккуратно снять кожу. Мясо нарезать кусочками. Обжарить грибы, остудить, добавить к курице, посыпать специями, очищенными фисташками, перемешать. Полученную начинку выложить на кожу, свернуть рулетом, завернуть в фольгу, концы хорошо закрутить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7389,'Печь в течение 50 минут при температуре 200–210 градусов. Блюдо вынуть из духового шкафа, остудить и поставить в холодильник на пять-шесть часов или на сутки. Готовый рулет «Праздничный» освободить от фольги, нарезать ломтикам и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7390,'Острым ножом отрезать верхнюю часть помидоров в виде зубчиков. Ложкой вынуть мякоть вместе с семенами. Каждый помидор натереть солью изнутри и поставить срезами вниз на бумажное полотенце, лишняя жидкость стечет через 20–30 минут. Вилкой размять адыгейский сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7390,'Вымыть и мелко нарезать зеленый лук, укроп, петрушку. Зелень добавить в сырную массу. Очистить и пропустить через пресс чеснок, добавить в смесь вместе с майонезом или сметаной. Перемешать, соль – по вкусу. Каждый помидор наполнить мягким сыром, поставить на блюдо и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7391,'Смешать соевый соус, яблочный сок, мед, рисовый уксус. Добавить кунжутное семя, корейский красный перец, тертый зубчик чеснока, имбирь, мелко нарезанный лук-шалот. Соединить сырые куриные белки с солью и пищевой содой, немного взбить, намазать крылышки. Курицу запечь на решетке. Соус подать отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7392,'Молоко прогреть в микроволновой печи до 40 градусов. Всыпать сухие дрожжи, немного сахарного песка, перемешать. Оставить смесь на пять минут, до появления пузырьков. Растопить сливочное масло, взбить с сахаром при помощи миксера. Вбить сырые яйца, добавить дрожжевую смесь, соль и молоко. Перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7392,'Всыпать пшеничную муку порциями, замесить тесто. Выложить в миску, накрыть тканью, оставить на час или полтора, масса должна увеличиться вдвое. Готовое тесто разрезать на шесть частей одинакового размера, слепить шарики, обернуть в пленку, чтобы не заветривались. Раскатать первый шарик в лепешку среднего размера, разрезать на шесть или восемь треугольников-сегментов, от центра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7392,'Намазать небольшим количеством шоколадной пасты, например, Нутелла или любимым джемом. Начиная с широкой стороны, скрутить изделия в рогалики, придать им форму полумесяца. Выложить заготовки на противень, смазать взбитым яйцом, посыпать сахарным песком. Оставить в таком виде на полчаса, тесто должно немного подняться. Печь рогалики с джемом и шоколадом при температуре 190 градусов в течение 20 минут. Должна образоваться золотисто-коричневая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Нарезать свинину полосками толщиной по 1,5 см, отбить с двух сторон, накрыв пищевой пленкой, чтобы не было брызг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Приготовить из растительного масла и лимонного сока смесь для маринада, втереть в каждый кусок мяса смесь соли и перца, обмакнуть в маринад, сложить в стопку друг на друга, оставить мариноваться на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7393,'Измельчить в блендере до однородности вареные яйца, кислое яблоко, зелень, чеснок и сливочное масло, приправить солью и перцем, разогреть до 180 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Мелко порубить зелень, переложить в глубокую миску и перемешать с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Порезать яйца, мелко нарезать бекон, крупно порезать чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7394,'Смешать пшеничную муку, соль, дрожжи, добавить мягкий маргарин, молоко и немного воды. Замесить тесто, оно должно быть эластичным. Можно воспользоваться миксером. Сформовать «колобок», положить его в миску, накрыть тканью, оставить на 90 минут. Обмять подошедшее тесто, оставить еще на 10 минут. Разделить тесто на пять частей одинакового размера, раскатать в прямоугольники среднего размера. Скрутить, края зажать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7394,'Выложить заготовки для багетов на застеленный бумагой противень, накрыть полотенцем, оставить еще на полчаса. Взбить желток с небольшим количеством молока, смесью смазать поверхность теста, сделать неглубокие надрезы. Печь венские багеты в духовом шкафу при температуре 180 градусов в течение 18–20 минут. Остудить полностью, на решетке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7395,'Готовое слоеное тесто разморозить, раскатать в виде квадрата или круга. Измельчить с помощью блендера очищенный чеснок, зеленый базилик, сыр, зелень петрушки, очищенный от кожуры помидор. В готовую смесь добавить оливковое масло. Намазать смесь на тесто, посыпать петрушкой и выпечь фокаччу в духовке в течение 25 минут при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7396,'Нарезать большое яблоко на кружочки, удалить семена, сбрызнуть соком лимона, взять самые большие по диаметру кусочки (5шт.) и обрезать края в виде звездочки, положить самую большую «звездочку» вниз, а на нее поменьше и так далее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7396,'Для придания елочке объема необходимо укладывать между колечками и треугольные обрезки яблок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7396,'Украсить десертную «Новогоднюю елку» из яблока и клюквы ягодками клюквы и поставить в центр блюда с фруктовой нарезкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7397,'Свежие куриные яйца хорошо вымыть в теплой воде, отделить белки от желтков. Белки взбить вместе со щепоткой соли или соком лимона в плотную пену. Желтки взбить отдельно, с сахаром, добавить сыр маскарпоне, перемешать. Соединить обе яичные массы, перемешать осторожно, масса должна остаться пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7397,'В холодный крепкий кофе влить немного любого коньяка. Печенье савоярди окунать в кофейную смесь, выложить в подготовленные формы для десерта. Покрыть кремом, выложить второй слой печенья, слой крема. Поставить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7398,'Каждый клубень вымыть, обернуть в фольгу, выложить в термостойкую форму и печь в духовке в течение часа. Ломтики бекона обжарить до золотистого цвета, мелко нарезать. Натереть твердый сыр, порубить зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7398,'Картофель вынуть из духовки, разрезать пополам, ложкой, осторожно, вынуть мякоть из картофелин, сделать из нее пюре. В массу добавить сметану, зеленый лук, соль и молотый перец – по вкусу. Заполнить «лодочки» начинкой, сверху положить сыр и бекон, печь картофель в духовке при температуре 175 градусов в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7399,'Очистить и натереть клубни картофеля. Лишнюю жидкость отжать. Очистить и натереть репчатый лук, смешать с картофелем, добавить сырые куриные яйца, пшеничную муку, соль и молотый перец. Хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7399,'В большой сковороде разогреть масло, выкладывать оладьи столовой ложкой, жарить по две-три минуты с каждой стороны, до образования золотисто-коричневой корочки. Готовые драники-латкес выложить на бумажное полотенце, лишний жир должен впитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7400,'Смешать творог, соль, сахарный песок и пшеничную муку. Масса не должна липнуть к рукам. Скатать в «колбаску», обвалять в пшеничной муке, нарезать, каждый сырник обвалять в муке. Разогреть масло, добавить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7401,'Промыть говядину и свинину проточной холодной водой, положить в воду, довести до кипения на сильном огне. Огонь убавить, появляющуюся пену снимать ложкой. Варить бульон около полутора часов, мясо должно стать мягким, проверить вилкой или острым ножом. В середине приготовления добавить несколько лавровых листьев и горошин черного перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7401,'Брусочками нарезать очищенный репчатый лук, сырую свеклу и морковь – тонкой соломкой. Белокочанную капусту нашинковать, корень сельдерея также нарезать соломкой, его можно заменить корнем петрушки. Готовое мясо вынуть из бульона и нарезать на порции. Бульон отцедить, вернуть в кастрюлю, посолить по вкусу, положить мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Помидоры порезать небольшими кубиками, зеленый лук – средними колечками, сыр натереть на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7401,'Солить бульон нужно в конце варки. Положить в суп капусту, варить до ее готовности. Положить свеклу, морковь, лук и сельдерей, вместе с растительным маслом, в другую емкость, влить немного бульона, массу потушить под крышкой на тихом огне в течение 20 минут. В процессе тушения смесь перемешивать, она не должна пригореть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7401,'В середине готовки добавить нарезанные помидоры без кожицы, сахарный песок и уксус. Прогревать до готовности. Овощи добавить в очень вкусный борщ, перемешать, огонь выключить, подержать блюдо под крышкой. При подаче положить в тарелки сметану и рубленую зелень укропа и петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7402,'Апельсины и лимоны вымыть, лучше с помощью щетки. Залить плоды кипятком, подержать в нем в течение 5–10 минут. С трех апельсинов и двух лимонов снять цедру, можно сделать это с помощью терки или острого ножа, нарезать тонкой соломкой. Выжать сок из мякоти. Налить его в посуду, которая поместиться в микроволновой печи, влить воду, положить цедру. Белую часть с плодов завернуть в марлю, опустить в сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7402,'Накрыть емкость пленкой, перемешать, варить в течение 20–25 минут, кожура должна размягчиться, ее нужно отжать и выбросить. Всыпать сахарный песок, варить еще полчаса на сильном огне. Готовый джем должен хорошо увариться, загустеть, капелька не должна растекаться на поверхности блюда. Заготовку разлить в чистые банки, их лучше простерилизовать, апельсиново-лимонный джем остудить, хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7403,'Молоко и растительное масло комнатной температуры влить в стакан. Взбить с помощью блендера в течение минуты на большой скорости. Посолить, влить лимонный сок или уксус, горчицу. Массу снова взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7404,'Для приготовления блюда понадобится разъемная форма среднего диаметра, ее нужно выложить промасленным пергаментом. Растолочь в крошку печенье, смешать с растопленным сливочным маслом и молоком, массу уложить на дно, прижать, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7404,'Бананы комнатной температуры очистить и превратить в пюре. Замочить быстрорастворимый желатин в лимонном соке, прогреть на водяной бане, смешать с пюре из банана, поставить в холодильник на 10–15 минут. Масса должна немного застыть, но не превратиться в желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7404,'Отдельно протереть через сито творог, добавить лимонную цедру, мед, сметану, взбить. В другой емкости взбить сливки с ванилином и сахарной пудрой. Добавить в творог банановое пюре, сливочную массу, снова всё взбить. Готовый крем выложить в форму, поставить чизкейк с бананом в холодильник на несколько часов или на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7405,'Зеленый лук хорошо промыть и нарезать. Прогреть его со сливочным маслом на сковороде, он должен осесть и стать мягким. Растопить сливочное масло, всыпать сахарный песок, соль, влить кефир, взбитые куриные яйца. Смешать пшеничную муку с разрыхлителем, добавить в жидкую массу, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7405,'Форму для выпечки смазать маслом, вылить большую часть теста, затем–начинка и оставшееся тесто. Печь при температуре 200 градусов в течение 35 минут. Остудить заливной пирог под полотенцем, нарезать на порции и подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7406,'Тушку цыпленка натереть снаружи и изнутри солью, поместить в емкость. Залить птицу ледяной водой, оставить в холодильнике на три часа или больше. В небольшой миске смешать оливковое или очищенное сливочное масло с молотой паприкой и давленым чесноком. Тушку отмыть от соли, положить внутрь несколько веточек богородской травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7406,'Натереть со всех сторон полученной масляной смесью. Поставить блюдо в духовку, печь при температуре 200 градусов в течение 20–30 минут, затем ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7407,'В большой емкости смешать пшеничную муку, соль, молотый красный и черный перец. В другой миске смешать муку с кефиром и сырыми яйцами. Взбить венчиком до однородности. Хорошо раздробить готовые картофельные чипсы. Репчатый лук очистить, нарезать широкими кольцами в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7407,'Противень застелить пергаментом, смазать растительным маслом. Поставить в духовку, нагретую до 200 градусов на восемь минут. Масло должно начать «шипеть». Луковые кольца вывалять в мучной смеси, окунуть в тесто, дать стечь лишнему, вывалять в чипсах. Готовый лук выложить на противень, печь по восемь минут с каждой стороны. Горячие луковые кольца посыпать крупной солью по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7408,'Отделить сырые белки от желтков. Первые взбить в крепкую пену. Желтки взбить с молоком, молотой корицей и сахаром. Вмешать взбитые белки, сделать это осторожно, чтобы они не осели. Нарезать тонкими ломтиками белый черствый хлеб. Вымыть кисло-сладкие яблоки, сердцевину вынуть, мякоть нарезать поперечными ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7408,'Форму для выпекания смазать маслом, вылить немного полученного теста. Яблоки и хлеб выкладывать слоями, пока не заполнится вся форма. Сверху вылить остатки яичной массы, дать постоять в течение 10 минут. Печь пирог в течение 45 минут при температуре 180–200 градусов. За 10 минут до готовности положить на нежнейшую шарлотку кусочки сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7409,'Смешать сметану с водой в равных пропорциях, добавить любые специи для картофеля, перемешать. Клубни картофеля очистить, нарезать тонкими кружками, выложить слоями на смазанный противень. Каждый слой посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7409,'Залить блюдо сметанной смесью, поставить в духовой шкаф на 45–50 минут. Блюдо вынуть, посыпать тертым сыром, поставить картофель в сметане еще на 15 минут, должна образоваться аппетитная румяная корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7410,'Замесить из растопленного маргарина, муки, разрыхлителя и соли мягкое тесто, скатать в шар, обернуть пищевой пленкой и убрать на 30 минут в холодное место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7410,'Слить жидкость из банки с консервированной сайрой, рыбу измельчить вилкой, добавить рубленный зеленый лук и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7410,'Взбить для заливки яйца со сметаной и мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7410,'Раскатать из теста тонкий прямоугольный пласт, поместить на смазанный маслом противень, сформовать бортики. Разровнять по поверхности консервы с луком и залить равномерно смесью взбитых яиц, присыпать сверху измельченным укропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7410,'Выпекать открытый рыбный пирог с сайрой и сметаной 50-60 минут, духовку выключить и оставить пирог внутри еще на 15 минут, подавать можно горячим или охлажденным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7411,'Нарубить хорошо промытый зеленый лук. Порезать зеленые и черные консервированные оливки с паприкой. Натереть твердый сыр и размять сливочный сыр с майонезом. Массу поперчить, положить оливки и лук, добавить тертый сыр. Сырный салат хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7412,'Замесить жидкое тесто из пшеничной муки, сырого яйца, пахты, мягкого сливочного масла и соли. В кастрюлю с водой положить курагу, чернослив, сушеный инжир. Добавить стручок ванили, кипятить пять минут. Выпечь блины с двух сторон. Перед подачей свернуть их конвертиками, положить начинку внутрь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7413,'Большую кастрюлю заполнить водой на 12 сантиметров, довести до кипения на среднем огне. При закипании положить куриные яйца, варить 13 минут. В другую емкость налить холодную воду, положить лед, горячие яйца поместить в эту ледяную «ванну». Подержать пять минут, вынуть, воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7413,'Яйца очистить, нарезать вертикально, желтки вынуть. Добавить в них майонез и два вида горчицы: дижонскую и желтую, хорошо перемешать, можно сделать это с помощью комбайна. Добавить укроп, перец, соль, зеленый лук, полить вустерским соусом. В каждую «лодочку» из яичного белка положить часть смеси, украсить пером зеленого лука, нарезанным редисом, паприкой. Подать фаршированные пряные яйца в охлажденном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7414,'У тушки удалить голову и внутренности, хорошо промыть, нарезать кусочками. Очистить и нарезать кольцами или полукольцами репчатый лук. В стеклянную банку уложить рыбу слоями с луком и гвоздикой, горошинами черного душистого перца, лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7414,'Довести воду до кипения, всыпать соль, сахарный песок и влить растительное масло. Смесь остудить, залить раствором рыбу, накрыть крышкой, поставить в холод. Скумбрия домашнего посола будет готова примерно через сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7415,'Прогреть молоко, всыпать дрожжи, сахарный песок, смеси дать постоять до появления пузырьков. Добавить растительное масло, просеянную пшеничную муку. Замесить некрутое тесто, накрыть его тканью, поставить в тепло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7415,'Поднявшееся тесто обмять, разделить на десять частей. Каждый кусок раскатать в тонкие прямоугольные лепешки, на один край положить нарезанный плавленый сыр, второй край надрезать. Свернуть рулетом, не плотно, начинать сворачивать с края, где лежит сыр. Края защипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7415,'Выложить булочки на застеленный пергаментом противень, оставить на 25 минут, накрыть полотенцем. Перед выпечкой поверхность булочек с плавленым сыром смазать взбитым желтком. Печь в течение 15 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7416,'Приготовить опару из муки, молока, быстродействующих дрожжей. Оставить её на ночь, на 8–10 часов. Для второй опары смешать соль и сахарный песок, пшеничную муку, всыпать в первую опару, замесить тесто, накрыть пищевой пленкой, оставить на час, масса должна увеличиться в полтора раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7416,'Добавить сахар, яйцо, масло, муку, замесить тесто, оно должно быть мягким и липким. Разделать его на 15 частей, скатать в шарики, «колобки» немного прижать рукой и оставить на час на расстойку. Для приготовления начинки смешать творог, сахар, сметану, яйца и ванилин. Оставить на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7416,'В заготовках для булочек сделать углубления с помощью донышка стакана, смазать немного взбитым яйцом, выложить творожную начинку. По желанию дрожжевые ватрушки с творогом можно посыпать изюмом. Еще раз смазать взбитым яйцом, печь при температуре 230–240 градусов в течение 20–25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7417,'Отделить белки от желтков. Желтки смешать с сахарным песком, добавить растопленное сливочное масло, всыпать муку. Должно получиться плотное тесто. Поставить его на полчаса в холодильник. Охлажденный продукт выложить в форму. Сверху–слой очищенных и нарезанных бананов, залить сметаной, лучше жирной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7417,'Поставить в духовой шкаф на 20 минут. Оставшиеся белки взбить с сахаром. Выпечку вынуть, выложить белок, поставить в духовку еще на три минуты. Затем сразу перенести банановый пирог в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7418,'Замесить из подсоленной муки, масла, дрожжей с добавлением сахара мягкое тесто на смеси воды с молоком. Отделить от него примерно 150 г, остаток обернуть в пленку и убрать на пару-тройку часов в холодильник. Приготовить пасту из воды и какао, тщательно смешать с отложенным тестом, обернуть в пленку, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7418,'Раскатать между двумя пластами пергамента масло в прямоугольник 20х15см, положить в холодильник. Присыпать стол небольшим количеством муки, раскатать с небольшим усилием в пласт 45х25 см, уложить по центру охлажденное масло, сложить конвертом. Повернуть его на 90 градусов, раскатать опять в прямоугольник, сложить, обернуть пленкой, убрать на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7418,'Вынуть тесто, повторить все процедуры, убрать на полчаса в холодильник, проделать все еще раз и убрать минимум на полчаса (можно и на ночь) в холодильник. Раскатать коричневое тесто в прямоугольник 40х20 см, в такой же пласт раскатать белое тесто, смазать его водой с помощью кисти, уложить на него коричневый пласт. Разрезать кусок пополам, убрать половину в морозильник (может храниться до 2 месяцев).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7418,'Раскатать прямоугольник примерно 38х20 см, нарезать из него 8 треугольников, сделать у основания насечку, чуть растянуть, свернуть в рулет. Разложить двухцветные круассаны на противне, накрыть пленкой, дать подойти, из взбитого с молоком яйца приготовить глазурь, смазать их верх. Положить на противень силиконовый коврик, уложить на достаточном расстоянии друг от друга круасаны. Выпекать около 20 минут до золотистой корочки в прогретой до 200 градусов духовке, достать выпечку, дать чуть остыть, подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7419,'Порубить мелко лук и чеснок, обжарить до золотистости на масле, добавить шампиньоны, порезанные кубиками, протушить около 7 минут, добавить фарш, перемешать, обжарить минут 5. Положить к грибам томатную пасту, базилик, подсолить, поперчить, тушить при помешивании полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7419,'В сотейнике растопить масло, всыпать муку, хорошо перемешать, чуть обжарить. Закипятить молоко с добавлением мускатного ореха, дать немного остыть, влить тонкой струйкой в сотейник,перемешать, чтобы не было комочков, дать закипеть, подсолить, перемешать, снять соус с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7419,'Выложить дно формы листами для лазаньи, положить фарш, прикрыть листами, положить соус, фарш, опять соус, присыпать сырной стружкой, все повторить. Разогреть духовку до 180 градусов, поставить форму в духовку, лазанья с мясным фаршем будет готова через 45 минут, подавать к столу пока горячая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Для заправки смешать сметану, сахар и майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11340,'Мясо хорошо промыть в холодной воде и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7420,'Дать воде закипеть, положить брокколи, проварить после повторного закипания 3 минуты, откинуть на дуршлаг, сразу погрузить его в холодную воду с кубиками льда примерно на минуту. Влить в миску половину минеральной воды, всыпать муку, положить желток, раздавленный прессом чеснок, посолить, поперчить, тщательно перемешать, влить остаток воды, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7420,'Добавить в кляр взбитый в крепкую пену белок, осторожно перемешать, прогреть хорошо масло в кастрюле с толстым дном. Наколоть соцветия на вилку, обмакнуть в кляр, обжарить порциями в масле. Переложить капусту брокколи в кляре на бумажное полотенце, разложить в тарелки, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7421,'Добавить в фарш лук, вбить яйцо, посолить, поперчить, охладить 15 минут в  холодильнике. Обжарить половинки булочки до золотистости, приготовить котлеты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7421,'Собрать чизбургер: смазать булочку соусом, уложить на нее листья салата, далее–котлету, сыр, на него положить лук и колечки помидора, смазать соусом, прикрыть второй половинкой булочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7422,'Порезать кружочками огурцы, лук и помидоры, порезать салат. Приправить фарш солью и перцем, перемешать, сформовать котлеты, соответствующие размеру булочек. Разогреть масло, положить лук, обжарить до золотистости, посолить, поперчить, переложить в тарелку, в этой же сковороде обжарить котлеты по 3 минуты с одной и другой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7422,'Разрезать для классического бургера булочки на 2 половинки. Смазать одну майонезом, положить салат, лук, котлету, пластинку чедера, кружки помидора и огурца, вторую половинку булочки смазать кетчупом, прикрыть бургер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7422,'Для кетчупа сложить кусочки помидора (семена удалить) в сотейник, добавить лук, паприку, уксус, чеснок, поперчить, проварить на малом огне полтора часа, протереть сквозь сито, дать остыть. Для майонеза смешать горчицу и желток, маленькими порциями влить масло, постоянно взбивая, поперчить и подсолить, влить уксус и хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'Для теста смешать дрожжи, муку, соль, молоко, сахар, яйцо и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'Грибы порезать мелко, натереть сыр на терке, колбаски очистить от шкурки и порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'Далее переложить тесто в форму, смазать столовой ложкой оливкового масла, промазать томатным соусом или пастой, посыпать грибами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'На грибы выложить рубленные итальянские колбаски, затем тертый сыр и соль с перцем, сверху полить оставшимся маслом оливковым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'Разогреть духовку до 220 градусов и запечь пиццу в течение 20 минут, тесто должно затвердеть и подрумяниться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7423,'Пицца с грибами, сыром и итальянскими колбасками украшается петрушкой и тертым сыром, затем подается к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7424,'Перемешать фарш с Табаско и соевым соусами, всыпать порубленный укроп, поперчить, тщательно перемешать, часть можно заморозить для другого раза. Сделать из него котлетки размером по диаметру булочек, порезать фиолетовый лук средними кусочками. Разогреть в сковороде масло, положить лук, сахар, перемешать, обжарить на малом огне 20 минут, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7424,'Из смеси кетчупа, майонеза и горчицы приготовить соус, нарезать кружочками помидоры с огурцами, сыр – пластинками котлеты обжарить с обеих сторон. Положить на котлеты, пока они горячие по пластинке сыра. Булочки разрезать на 2 части, подрумянить срезы на сухой сковороде, смазать их соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7424,'Собрать домашние гамбургеры: положить на нижнюю часть булочки пару колечек помидора, далее – огурцы и салат с рукколой, потом уложить котлету с сыром, слой карамелизированного лука, прикрыть верхушкой булочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7425,'Порезать овощи кольцами , лук замариновать на треть часа в растворе воды с сахаром, фарш подсолить, разделить пополам, сделать две лепешки, обжарить с двух сторон на масле. Убрать гамбургеры со сковороды, обжарить в остатках масла срезы лепешек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7425,'Собрать гамбургер с ржаным хлебом в следующем порядке: смазать лепешку кетчупом, уложить котлету, смазать ее горчицей, уложить поверх овощи, прикрыть второй половинкой лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7436,'Вымыть печень, снять пленку, вырезать сосуды, прокрутить на мясорубке, можно измельчить в блендере. Влить в массу молоко, вбить яйца, всыпать муку, добавить соду, поперчить и подсолить, хорошо размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7426,'Разрезать вдоль филе, запанировать, обмакнуть в яйцо, потом в подсоленную и поперченную муку, обжарить с маслом до золотистого цвета. Салат порвать, помидоры порезать на кубики. Лепешки промазать майонезом, уложить на них салат, кусочки помидора, курицу, свернуть домашний твист в трубочку, обжарить на гриле до хрустящей корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7427,'Обжарить кусочки шампиньонов около 10 минут вместе с тертой морковью. Разобрать брокколи на соцветия, картофель порезать кубиками. Дать воде закипеть, положить все ингредиенты, подсолить, проварить 10 минут. Всыпать в суп охлажденные и натертые сырки, размешать, дать им раствориться. Посыпать сырный суп укропом, подать с румяными пшеничными сухариками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7428,'Разложить на поверхности теста кусочки ветчины, сыра, скатать в трубочку, нарезать на шайбы толщиной по 3 см, уложить в смазанную форму. Для соуса прогреть в кастрюльке масло с горчицей и медом, перемешать, залить в форму с сырной улиткой, поставить на час в холодильник, затем поставить на 25 минут в прогретую до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7429,'Прогреть немного смесь воды с молоком, положить дрожжи с сахаром, размешать, всыпать немного муки, тщательно перемешать, поставить в тепло на четверть часа. Вбить в смесь яйцо, добавить мягкое масло, ванилин, посолить, размешать, всыпать остаток муки, вымесить тесто, убрать в тепло на час, разделить на 9 комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7429,'Раскатать часть в овальные лепешки, сделать голову и клюв, сделать надрезы, половину загнуть вверх–это крылья. Из изюминок сделать глаза. Выпекать булочки «Жаворонки» около 25 минут в заранее прогретой до 180 градусов духовке. Смазать верх булочек маслом, дать чуть остыть, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7430,'Порезать мелко грибы, обжарить до полной готовности, огурец и печень нарезать соломкой, сыр крупно натереть. Все смешать, чуть посолить, приправить салат из печени майонезом с добавлением горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7431,'Размягчить масло в микроволновке, всыпать половину сахара, присолить, добавить ванильный сахар, хорошо размешать, вмешать по одному яйца, добавить остальной сахар, еще раз размешать, влить все молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7431,'Просеять смесь муки и разрыхлителя, замесить тесто. Помыть ягоды, обсушить, высыпать в тесто, размешать. Духовку прогреть до 180 градусов, заполнить формочки на 2/3 тестом, выпекать маффины с черникой около получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7432,'Включить для прогрева до 175 градусов духовку, растереть сахар с маслом, ванильным сахаром и солью. Вмешать по одному все яйца, добавить разрыхлитель, муку (просеянную) и сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7432,'Заполнить тестом смазанную форму, порезать яблоки на дольки, побрызгать соком лимона, разложить на тесто, поставить пирог с яблоками на 12 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7432,'Для заливки перемешать яйца со сметаной и сахаром, достать пирог, залить смесью, вернуть на 50 минут в духовку, готовую выпечку присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7433,'Разболтать яйца с солью, взбивая влить кипяток, затем кефир, всыпать муку с содой, добавить сахар с растительным маслом, тщательно перемешать, дать постоять 10 минут. Выпекать блинчики на кипятке на хорошо прогретой сковороде с двух сторон до золотистого соломенного цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7434,'В 1/2 бульона добавить измельченный хлеб, нарезать петрушку и грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7434,'Кусочки куриного филе обжарить в разогретом на сковороде сливочном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7434,'Затем положить к мясу нарезанные грибы, влить немного бульона куриного и варить около 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7434,'Обжаренное мясо и грибы, яичные желтки, хлеб и бульон, хорошенько взбить с помощью блендера, перелить в кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7434,'В суп-пюре из курицы и грибов по-французски добавить сливки, соль, оставшийся бульон, перец и орех мускатный, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7435,'Перемешать хорошо все ингредиенты, заполнить половиной теста форму, уложить начинку из риса твердого сыра и семги, залить остатками теста. Нагреть духовку до 180 градусов, поместить в нее форму самый простой заливной пирог будет готов через 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7435,'Начинку еще можно сделать из консервированной в масле сайры, рыбу размять, добавить рис, яйца, пару ложек майонеза, зелень, посолить, поперчить. Либо перемешать обжаренные с луком и капустой грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11353,'Пшеничную муку просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7436,'Переложить на бумажное многослойное полотенце, дать остыть. Для соуса порубить мелко чеснок, измельчить зелень, перемешать со сметаной. Смазать оладушки соусом, соединить попарно, выложить на блюдо, присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7437,'Натереть замороженное масло на терке, перемешать с мукой, содой и сахаром до получения маслянистой крошки. Для начинки перемешать творог с яйцами и сахаром. Круглую форму промазать маслом, заполнить половиной крошки, утрамбовать ложкой, сформовать бортики. Выложить поверх творожную начинку, выпекать ватрушку «Королевскую» около получаса в прогретой заранее до 180 градусов духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7438,'Порезать рыбу, нашинковать зелень и лук, натереть сыр мелко, все смешать и подсолить, добавить перец, перемешать. Нарезать на ломти батон, пропитать их молоком, чуть отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7438,'Уложить батон в смазаную маслом форму, сделать углубление в каждом кусочке, положить туда рыбную смесь, промазать майонезом, отправить в духовку. Готовить гнездышки с рыбным филе около 40 минут при 180 градусах, присыпать сырной стружкой, вернуть на 5 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7439,'Порезать мясо на кусочки, лук нашинковать кубиками, зелень мелко порубить. Разогреть масло, слегка обжарить мясо добавить лук, специи, подсолить, поперчить, закрыть крышкой, протушить минут 10 на малом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7439,'В томатную пасту влить воду, перемешать вилкой до однородности, вылить к мясу, дать закипеть, накрыть крышкой, готовить 20 минут, помешивая. За 3 минуты до готовности всыпать в мясную подливу из говядины зелень, подавать с любым овощным и крупяным гарниром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7440,'Подготовить филе, обсушить салфетками, порезать на маленькие кусочки. В глубокой тарелке перемешать подсоленную муку с перцем и специями, обвалять мясо в смеси, обжарить в масле. Нашинковать мелко лук, обжарить, добавить кусочки грибов, готовить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7440,'Картофель порезать кубиками, разложить по горшочкам, сверху – мясо, а на него положить лук с грибами. Залить смесью сметаны, разбавленной водой, со специями, чесноком (раздавить прессом) и зеленью. Поместить картошку с курицей в сметане на 40 минут в духовку с температурой 230 градусов. Поставить горшочки на тарелки и сразу подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7441,'Обжарить кусочки куриной грудки на сухой сковороде, перемешать их с подсоленным майонезом и специями (куркума, красный перец, зира, гвоздика, кориандр), дать полчаса постоять и промариноваться. Обжарить 10 минут, добавить сметану, протушить еще 5 минут под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7441,'Нашинковать тонко лук, спассеровать в масле на сильном огне около  3 минут, добавить крупно тертую морковь, приправить смесью перцев, душистым перцем, подсолить, перемешать, тушить под крышкой на малом огне 10 минут. Нарезать на кубики картофель, уложить на дно горшочков, добавить грудку, а на нее уложить морковь с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7441,'Положить в каждый горшочек по 5 ст.л. тушеных помидоров с перцем, залить соусом от жареной грудки. Поставить горшочки с куриной грудкой и картофелем на 70 минут в духовку с температурой 200 градусов, если прогреть заранее, то хватит 60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7442,'Порезать копченую грудку на ломтики, выложить на плоскую тарелку, далее положить нарезанные шампиньоны, хорошо смазать майонезом. На него уложить слой из накрошенного плавленого сырка, присыпать измельченными сухариками, а затем – порубленным до состояния крупной крошки соленым арахисом. Украсить салат «Искушение» веточками зелени, подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7443,'Перемешать подсоленный творог с крупно натертым сыром, лаваш порезать на пласты. В глубокий противень выложить слой лаваша, промазать кефиром, разложить творожную начинку. Смазать кефиром еще один лист лаваша, уложить на начинку, смазать творогом и т.д., закончить слоем из лаваша. Верх пирога из лаваша посыпать натертым сыром и нашинкованным укропом, поставить выпекаться на полчаса в духовку с температурой 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7444,'Для приготовления теста взбить слегка кефир с яйцами и растительным маслом. В другой емкости перемешать все сухие ингредиенты: какао, муку с содой и сахар, добавить взбитые яйца, хорошо перемешать. Заполнить массой смазанную маслом форму, выпекать корж в прогретой до 200 градусов духовке около 50 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8346,'Картофель нарезать кубиками, мясо порезать кусочками, яйца мелко потереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7444,'Готовый корж разрезать вдоль острым ножом на 3 части, смазать кремом, верх оформить дробленым орехом и шоколадной стружкой. Для приготовления сметанного крема взбить сметану, сахар и масло в однородную смесь. Для заварного крема взбить яйца с сахаром до белой массы, постепенно всыпая муку, продолжить взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7444,'Закипятить молоко и добавить, тщательно мешая в него полученную смесь вместе с ванилью, дать остыть. Добавить в крем мягкое масло, тщательно вымешать  до однородного состояния, убрать на полчаса в холодильник, достать и промазать торт «Фантастика».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7445,'Отварить по отдельности мясо, овощи и яйца, все остудить. Салат собрать слоями (каждый промазать майонезом) в следующем порядке: мелкие кубики картофеля, курица, яйца с морковью, крупно натертые огурцы, грибы, тертый сыр. Убрать ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7446,'Взбить в густую пену сахар с яйцами, влить кефир с содой, взбить все вместе, всыпать постепенно муку, вымесить тесто похожее на густую хорошую сметану. Вылить тесто в смазанную форму, выпекать при температуре 180 градусов, готовность проверять зубочисткой. Остудить готовый корж, разрезать на 2 части. Для крема растереть сахар с мягким маслом, смешать со сметаной и взбить, смазать коржи, верх торта «Черный принц» оформить шоколадом с орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'Мелко натереть сыр и яйца с помощью терки, мелко порубить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'Отварной рис, яйца и зелень смешать, добавить перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'В центр каждого блина положить подготовленную начинку, свернуть конвертик, уложить все конвертики в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'На растительном масле спассировать мелко нарезанный лук, затем добавить ветчину, порезанную кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'Обжаренный лук и ветчинe выложить на блины и разровнять, посыпать сверху мелко натертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'Форму отправить в духовку с температурой 180 градусов и запекать в течение 25 минут до подрумянивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7447,'Запеченные блины с рисом, ветчиной, яйцами и сыром достать из духовки, переложить на блюдо и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7448,'Растопить на водяной бане шоколад со сливочным маслом с добавлением сахарной пудры до состояния однородной массы, убрать с плиты, дать остыть 10 минут. Перемешать до однородности смесь подсоленной муки с какао и разрыхлителем. Взбить с яйцами (добавлять постепенно) шоколадную массу, порциями добавить муку, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7448,'Тестом заполнить смазанную маслом форму, поставить в прогретую до 180 градусов духовку примерно на 45 минут, проверить готовность спичкой, если следов не остается, то корж готов. Для крема перемешать сок лимона с медом, белками, ванилью, сахарной пудрой, прогреть, помешивая на водяной бане. После приобретения смесью однородности взбить ее до пышного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7448,'Для приготовления хрустящей прослойки к растопленному шоколаду добавить сливочное масло и сливки, дать смеси чуть остыть перемешать с воздушным рисом. Разрезать корж на 3 части, смазать первый корж торта от Джейми Оливера хрустящей прослойкой, далее–кремом, накрыть вторым коржом, повторить процесс. Верх торта украсить попкорном и кусочками шоколада.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7449,'Разобрать мандарины и апельсин на дольки, переложить в кастрюлю, влить стакан воды. Поставить кастрюлю через 8 часов на плиту, варить на малом огне с добавлением имбиря. После закипания проварить, помешивая полтора часа, всыпать сахар с ванилином еще полтора часа. Разлить ароматное мандариновое варенье по баночкам, закатать крышками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7450,'Картофель крупно натереть, отжать излишки сока, смешать с яйцом, сдобрить перцем и солью, добавить муку, перемешать. Поджарить круглые картофельные оладьи небольшого размера с двух сторон, переложить их на бумажное полотенце. На каждое основание канапе положить по веточке зелени и кусочку рыбы, скрепить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7451,'Отварить картофель, порезать лук на мелкие кубики, морковь измельчить на средней терке, чеснок раздавить прессом. Грибы обжарить, добавить лук с морковью, чеснок, приправить специями, перемешать, обжарить 10 минут под крышкой, добавить сметану, тушить еще 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7464,'Салат нужно выложить слоями: в емкость с зеленью выкладываем яйца, бекон, чеснок, помидоры, лук зеленый, сыр, зеленый горошек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11353,'Яйца с сахаром взбить, добавить пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7451,'Размять картофель с добавлением молока и желтка, подсолить, перемешать пюре. Смазать маслом противень, выстлать пергаментом, выложить горками пюре, сделать в каждой углубление, положить в них грибную начинку. Поставить  картофельные гнезда с шампиньонами на 20 минут в духовку, готовые гнездышки украсить зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7452,'Смешать мягкое масло с кокосовой стружкой, сахаром, специями, влить коньяк, вбить яйцо, тщательно вымешать. Всыпать в смесь по маленьким порциям муку с разрыхлителем, вымесить тесто, обернуть пленкой, убрать на полчаса в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7452,'Скатать из теста три шарика разного диаметра, соединить их, прикрепить шарики-ножки и шарики-ручки, а на голову–ведерко, уложить печенье «Веселые снеговики» на противень, выстланный пергаментной бумагой. Сделать из шоколадных капель глаза и пуговицы на туловище, выпекать 25 минут при температуре около 200 градусов. Готовое печенье присыпать сахарной пудрой, сделать из мармелада снеговикам носы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7453,'Обжарить грибы и лук, отварить и порезать грудку, порубить яйца, огурец мелко порезать. Собрать послойно салат «Березка»: грибы с луком, грудка с майонезом, натертый крупно белок, огурец с майонезом, желток. Нарисовать майонезом ствол березки и веточки, полоски сделать из кусочков маслин, а листву – из нашинкованного зеленого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7454,'Нарезать мелко лук и грибы, обжарить с маслом до готовности, яйца сварить. Выложить салат «Изабелла» слоями в следующем порядке, промазывая каждый майонезом: окорочок, грибы, лук, порубленные яйца, кубики соленого огурца, морковь корейская. Украсить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7455,'Подготовит куриные ножки, вымыть, обсушить. Перемешать ингредиенты для маринада, залить ножки, поставить в холодильник на всю ночь. Противень выстлать фольгой, смазать маслом, уложить куриные ножки, прикрыть другим листом фольги, по бокам противня вылить по половине ст.л. воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7455,'Поставить куриные ножки с соусом Терияки в духовку на полчаса, готовить при температуре 200 градусов. Снять верхний слой фольги, полить выделившимся соком, вернуть на 20 минут в духовку, подать с любым гарниром и домашней аджикой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7456,'Довести до кипения подсоленную воду с маслом и сахаром, снять с плиты, всыпать просеянную муку, замесить тесто. Разогреть масло (фритюр) до 190 градусов, выдавить в него из кондитерского мешка небольшие колбаски (чурросы), обрезая острым ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7456,'Обжаривать чуррос около 2 минут, вынуть, переложить на бумажное многослойное полотенце. При подаче посыпать смесью молотой корицы и сахарной пудры, а к нему подать шоколадный соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7457,'Порезать филе на кубики, перец очистить и нарезать тоже на мелкие кубики. Отварить в подсоленной воде соцветия цветной капусты 5 минут, порезать ее на кубики. Все смешать, добавить крупно натертый сыр и зелень, вбить яйца, добавить муку со сметаной, подсолить, поперчить, хорошо перемешать, убрать на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7457,'Разогреть в сковороде растительное масло, сформовать мокрыми руками небольшие куриные котлетки с овощами, обжарить их до золотистости с двух сторон при небольшом нагреве. Готовые котлетки выложить в сотейник, прикрыть крышкой на 5-7 минут, подать к столу с овощным, крупяным гарниром или любым салатом с овощами по сезону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7458,'Творожную массу, яйцо и творог смешать, добавить ванильный сахар, муку и тщательно все размешать, далее добавить изюм и еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7458,'На присыпанной мукой поверхности из полученной массы сформуйте сырники, затем переложите их на разогретую сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7458,'Ванильные сырники изюмом обжарить со всех сторон до золотисто-коричневатого цвета на умеренном огне, подать с вареньем, сметаной или посыпать перед подачей сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7459,'Сварить картофель в «мундире», грибы обжарить с луком на масле, посолить, поперчить, перемешать. Натереть теплый картофель на терке, вбить яйцо, всыпать муку, перемешать поперчить, подсолить, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7459,'Скатать из массы шарики, сплюснуть, положить фарш из грибов, залепить края, придать форму котлеты. Обжарить зразы из картофеля с грибной начинкой до золотистости на масле с двух сторон. Сразу подать к столу вместе со сметаной или любым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Натереть скумбрию чесночком, завернуть каждую рыбку в фольгу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7465,'Кексы лимонные с крошкой и глазурью запечь при 175 градусах в районе 45-55 минут, а когда они остынут, полить их глазурью из смешанного лимонного сока с сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7466,'Молоко взбить с яйцами, добавить ваниль, кардамон, все хорошо взбить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7466,'В получившуюся смесь окунуть каждый тост, переложить на подогретую до 180 градусов сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7466,'Тосты с ванилью и кардамоном по-французски обжарить на масле с каждой стороны до подрумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7467,'Аккуратно отделить от белков желтки яиц, смешать их с лимонной предварительно измельченной цедрой и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7467,'Все ингредиенты взбить с помощью миксера до густой массы однородной консистенции, добавить апельсиновый ликер, еще раз чуть-чуть взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7467,'Гоголь-моголь с ликером распределить по бокалам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7468,'Смешать с сахаром и солью кефир, добавить муку и соду, быстро замесить тесто без комочков, добавить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7468,'Сковороду с толстым дном разогреть, смазать маслом и выложить первую порцию небольших оладушек, но их не размазывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7468,'Пышные оладушки на кефире без яиц жарятся под крышкой на среднем огне, на стол подаются в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Посыпать перцем и солью свиную отбивную, обжарить со всех сторон в течение 6 минут в нагретом в тяжелом сотейнике масле, с помощью щипцов переложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'В сотейнике оставить столовую ложку жира, остальной слить, огонь уменьшить и пассировать в нем измельченный репчатый лук не дольше 4 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Потом добавить уксус и перемешать, подождать пока испарится жидкость (не дольше 4 секунд).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Обратно в сотейник переложить мясо, влить сливки, 1/2 стакана воды, добавить мелкорубленые листья петрушки и шалфея, без крышки тушить в районе 5-6 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Не выключая огонь, достать мясо и положить на чистое блюдо, постоянно помешивая продолжить варить соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Когда соуса останется примерно 3 столовые ложки, снять сотейник с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7469,'Свиная отбивная со сливками, луком и шалфеем подается с картофельным пюре, свежей петрушкой и политая готовым соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7470,'У рыбы удалить хвост и голову, тщательно вычистить и вымыть все тушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7470,'Для приготовления рассола в кастрюлю налить воду, всыпать соль, сахар, луковую шелуху и чайную заварку, закипятить, остудить, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7470,'В емкость выложить подготовленную рыбу, влить рассол, закрыть крышкой и убрать в место с комнатной температурой на 4 дня, в течение которых, утром и вечером, нужно переворачивать рыбу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7470,'По прошествии 4 дней, рыбу надо достать из рассола, переложить в чистую емкость, хранить в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7470,'Скумбрия копченая в рассоле по-домашнему прекрасно сочетается с солеными грибами, квашеной капустой и отварной картошкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7471,'Отделить от желтков яичные белки, тщательно взбить их с капелькой соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7471,'Творог, сахар, ванилин, манную крупу, сметану и изюм перемешать до однородности, осторожно ввести взбитые белки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7471,'Маслом смазать форму для выпечки, постелить лист пергаментной бумаги, распределить подготовленную творожную массу, отправить форму в разогретый духовой шкаф.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7471,'Вкуснейшая запеканка из творога с манкой и изюмом выпекается в течение 45 минут, подается с ягодным вареньем, сметаной или сгущенным молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7472,'Тонкими ломтиками нарезать картофель, полукольцами порезать лук, майонез смешать с тертым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7472,'Кусочками порезать говяжье мясо, добавить молотый черный перец, сушеный чеснок, кориандр или любые другие специи по желанию и все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7472,'В форму, смазанную предварительно растительным маслом, равномерным слоем выложить подготовленный картофель, посыпать его перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7472,'На картофельный слой уложить 1/2 от всего мяса, затем лук, на лук – половину сырно-майонезной смеси, каждый слой повторить еще раз в неизменном порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7709,'Разогреть духовку до 220 градусов. Разложить на противень перцы, запечь 15 минут, переложить их в пакет, завязать, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7472,'Форму отправить в разогретый духовой шкаф, выпекать говядину по-французски с картофелем в духовке при 190 градусах в районе часа, а перед подачей оформить блюдо зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'Печенье сложить в полиэтиленовый пакетик, размельчить в не мелкую крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'Сливочное сильно охлажденное масло порубить, добавить к печенью, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'Получившуюся массу переложить в форму, ровно распределить так, чтобы были двухсантиметровые бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'В течение 15 минут запекать тесто при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'Для начинки необходимо взбить яичные желтки, затем к ним добавить сгущенное молоко, постоянно взбивая, влить лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'По истечении 15 минут вынуть форму и равномерно распределить по пирогу приготовленную начинку, отправить пирог обратно еще на 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7473,'Готовый пирог из печенья со сгущенным молоком украсить фруктами, ягодами или взбитыми сливками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7474,'Отварить очищенный картофель, натереть сыр, порезать лаваш на прямоугольники по  длине сосиски, а длиной около 20 см. Добавить в картофель масло, приготовить пюре, поперчить, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7474,'Смазать прямоугольник пюре, посыпать сыром, уложить на край сосиску, свернуть в трубочку. Обжарить сосиски в сырно-картофельной шубке в хорошо прогретом масле со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7475,'Нарезать мясо, чуть обжарить, влить к нему немного кипятка, положить тертую морковку и кубики лука, тушить с добавлением масла. Добавить еще воды, чтобы мясо было немного покрыто водой, тушить до готовности около часа, за 10 минут до окончания посолить, добавить лавровые листики, горошки перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7475,'Смешать чайную ложку томатной пасты, столовую муки с теплой водой (0,5 стакана), добавить столовую ложку сметаны, хорошо все перемешать, чтобы разбить все комочки. Вылить тонкой струйкой в мясо, постоянно помешивая, тушить еще 10 минут все вместе. Сварить картофель, размять до состояния пюре, влить подогретое подсоленное молоко, перемешать. Подавать гуляш из говядины с пюре и подливой в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7476,'Мясо и отварить до готовности, яйца – вкрутую, орехи подсушить на сковородке. Салатник застелить пленкой, выложить слой из тертой мелко морковки, утрамбовать аккуратно ложкой, смазать майонезом, присыпать слоем порубленных орехов, опять смазать майонезом. Сцедить кукурузу (отложить немного для оформления), выложить третьим слоем, смазать майонезом, на него уложить крупно натертые яйца и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7476,'Нарезать мясо небольшими кубиками, положить на яичный слой, смазать майонезом, выложить последний слой из натертого крупного картофеля, придавить его слегка ложкой. Осторожно перевернуть салатник на плоскую тарелку, удалить пленку, промазать верх и бока майонезом, присыпать их гранатовыми зернами. Оформить мясной салат с гранатом порубленными перьями зеленого лука и зернами кукурузы',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7477,'Перемешать все ингредиенты для теста, разделить на 8 одинаковых кусочков. Раскатать один в корж по размеру сковороды, обжарить на разогретой сковороде примерно по минуте с каждой стороны, обрезать ровно края, обрезки сохранить для присыпки, повторить все для других коржей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7477,'Приготовить крем, перемешать все ингредиенты (масло не брать), прогреть, помешивая до сгущения массы, добавить масло, дать раствориться, перемешать. Промазать кремом коржи, сложить в стопку, смазать бока быстрого торта, присыпать крошкой от обрезки, дать постоять и пропитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7478,'В чаше миксера взбить при высокой скорости сахар с яйцами около 5 минут в плотную белую массу, добавить муку, аккуратно перемешать, вылить массу на выстланный бумагой противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7478,'Выпекать рулет по ГОСТу около 15 минут в духовке с температурой 190 градусов. Готовый бисквит выложить на полотенце, удалить бумагу, промазать сметанным кремом или вареньем, свернуть в трубочку, дать немного постоять для пропитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7486,'Слегка прогреть яблочный сок, положить разбухший желатин, предварительно его отжать, перемешать, дать раствориться желатину. Положить в раствор пару столовых ложек сырной смеси, перемешать, объединить с остатками смеси, добавить взбитые сливки. Заполнить основу полученной массой, прикрыть пленкой, дать остыть пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7479,'Взбить смесь сахара и яиц в пышную массу. Прогреть до кипения сливки с ванильным экстрактом, сразу снять с плиты, влить тонкой струйкой, взбивая смесь желтков. Перелить все в металлическую емкость, остудить, накрыть, убрать на пару часов в морозильную камеру холодильника. Подготовить ягоды, переложить их в кастрюльку, влить четверть стакана воды, всыпать пару столовых ложек сахара, проварить на малом огне до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7479,'Свежую смородину подвергать тепловой обработке не надо. Приготовить из ягод с помощью блендера пюре, (остудить если смородина была замороженной) перемешать с массой из холодильника, прикрыть фольгой, вернуть мороженое со смородиной на 4 часа (ночь) в морозильную камеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7480,'Замесить тесто на воде, прикрыть пленкой, заняться начинкой. Нашинковать мелко перья лука, чеснок с имбирем мелко натереть, хорошо перемешать с фаршем, разделить его и тесто на 8 частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7480,'Раскатать тонкие лепешки диаметром чуть больше 20 см, на 3/4 лепешки намазать начинку, надрезать от центра к краю, прикрыть 1/4 начинки тестом, накрытую часть свернуть для получения половины круга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7480,'Сложить его пополам, чтобы получить 1/4 круга, края теста тщательно залепить. Лепешки с мясным фаршем обжарить с 2-х сторон на сухой сковороде под крышкой, готовые лепешки, пока они горячие, промазать сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Растворить в половине стакана теплого молока дрожжи, размешать и оставить до образования на поверхности пены (около 15 минут).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Растопить и добавить к дрожжам сливочное масло, сахар, соль, вбить яйцо, перемешать, постепенно добавляя муку, замесить тесто, накрыть тканью и оставить его на пару часов созревать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Приготовить из нарезанного филе рыбы и сладкого перца начинку (перец нарезать сломкой шириной по 2-2,5 см), включить на разогрев духовку до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Раскатать из теста круг (толщиной около 2 мм), отступив от края 4 см выложить по окружности полоску начинки, загнуть края круга, полностью накрыв начинку тестом, края хорошо защипать, порезать полученный валик на кусочки шириной по 3-4 см и вывернуть начинкой наружу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Положить по центру теста оставшиеся кусочки рыбы, сладкий перец, помидоры, сыр, присыпать приправами, дать постоять минут 10-15 и выпечь в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7481,'Открытый пирог с сыром, рыбой и овощами будет готов примерно через полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7482,'Нарезать батон на ломти, сыр с колбасой крупно натереть, смешать их с кетчупом и майонезом в однородную массу. Выложить на ломти полученную массу толстым слоем, прикрыть кружочками помидора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7482,'Переложить самую ленивую пиццу на противень, смазанный маслом, запекать около трети часа в прогретой до 180 градусов духовке, подавать к столу в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7483,'Перемешать все ингредиенты, вылить в высокий бокал, подать сразу к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7484,'Все ингредиенты нарезать тонкой соломкой, зелень мелко порубить, заправить майонезом, перемешать, переложить в салатник, оформить по желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7485,'Измельчить печенье до состояния крошки, перемешать с растопленным маслом. Обернуть форму в фольгу, чтобы получился бортик, заполнить маслянистой крошкой, слегка придавить ложкой, поставить выпекать на 10 минут в прогретую до 170 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7485,'Перемешать миксером сахар с маскарпоне, добавить по одному яйца, перемешать на малой скорости до однородности, добавить растопленный шоколад с маслом, перемешать. Достать основу для чизкейка, заполнить шоколадной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7485,'В противень с бортиками налить воды, поставить форму, выпекать около часа при температуре 170 градусов. Достать готовый чизкейк с белым шоколадом, остудить, отделить от краев формы ножом, убрать на ночь в холодильник, перед подачей нарезать теплым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7486,'Сложить сухари в пакет, измельчить скалкой до состояния мелкой крошки, обжарить слегка миндаль, растопить масло, для основы все перемешать с добавлением сахара. Заполнить массой форму, уплотнить руками, закрыть пленкой, поставить в холодильник. Залить желатин водой, натереть цедру с лимона, отжать сок. Смешать с маскарпоне ванильный и обычный сахар, влить сок лимона, добавить цедру, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11353,'Влить теплый кефир, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7486,'Порезать яблоки на тонкие пластинки, протушить в смеси из пары ложек сока лимона и яблочного сока с добавлением сахара примерно 3 минуты. Залить желатин водой, дать постоять, отжать, растворить в яблочном соке, предварительно его подогреть, дать желейному раствору остыть. Перемешать желе с яблоками, залить яблочный чизкейк сверху на крем, прикрыть форму пленкой, убрать на 3 часа в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7487,'Включить для разогрева до 180 градусов духовку, подготовить форму, выстлать дно пергаментом. Для основы растопить масло, перемешать с крошкой печенья и сахаром, выложить слоем в форму, разровнять, утрамбовать, выпекать 10 минут, дать остыть на решетке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7487,'Перемешать на малой скорости сыр с подсоленной мукой и сахаром, добавить цедру лимона, ваниль, лимонный сок, желтки, яйца, перемешать, добавить сметану, размешать еще раз до однородности. Уложить полученный крем на основу чизкейка, поставить в уже разогретую духовку на 10 минут, снизить температуру, выпекать еще 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7487,'Отключить нагрев, приоткрыть дверцу, дать остыть пару часов в духовке. Хорошо перемешать сок лимона, сахар и сметану, выложить верхним слоем чизкейка «Нью Йорк», прикрыть форму пленкой, убрать в холодильник на всю ночь, подать с соусом из клубники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7488,'Положить в крепкий пакет печенье, прокатать скалкой, перемешать с растопленным маслом, заполнить разъемную форму, слегка придавить руками, поставить в холодильник. Для начинки перемешать блендером сметану с ванилью, творогом и сахаром, из черники приготовить в блендере пюре, добавить его в половину творога, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7488,'Залить желатин водой, дать постоять, нагреть сливки, смешать с набухшим желатином, перемешать до растворения, добавить в каждую половину творожной смеси, размешать. По центру основы выкладывать поочередно светлую и темную творожную смесь, разровнять, поставить творожный чизкейк с черникой в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7489,'Включить и прогреть духовку до 180 градусов. Перемешать молотый кофе, муку, сахар и какао, добавить масло, перетереть до получения маслянистой крошки, вбить яйцо, хорошо перемешать. Взять форму диаметром 25 см, выложить на дно слой крошки, сформовать небольшие бортики, отправить на 8 минут в горячую духовку, достать, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7489,'Смешать сахар с мягким сыром, парой столовых ложек муки, сахаром, добавить полторы столовых ложки смолотых зерен кофе, перемешать. Вбить и размешать по одному все яйца, положить сметану, влить эспрессо, сливочный ликер, перемешать. Заполнить начинкой корж чизкейка, отправить в духовку с температурой 225 градусов на 10 минут, понизить температуру до 120, выпекать еще около 50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7489,'Провести по окружности формы ножом, дать остыть, прикрыть и убрать в холодильник минимум на 4 часа, а лучше на ночь. Оформить верх кофейного чизкейка стружкой шоколада, зернами кофе, порошком какао.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7490,'Заполнить пакет поломанным на кусочки печеньем, прокатать скалкой до получения крошки, перемешать ее с маслом. Выстлать круглую разъемную форму пленкой, заполнить крошкой, утрамбовать, сформовать бортики, поставить в холодильник, заняться начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7490,'Смешать сахарную пудру, маскарпоне, взбитые сливки, влить коньяк, добавить порошок какао, растопленный шоколад, все перемешать. Полученную начинку разложить на основании шоколадного чизкейка, убрать его в холодильник на всю ночь, оформить порошком какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Замесить на холодной воде из муки с добавлением соли и нарубленного сливочного масла тесто, завернуть пленкой и положить в холодильник на полчаса, включить на разогреваться до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Раскатать тесто в пласт чуть больше формы, сформовать бортики, проколоть вилкой по всей поверхности, поставить выпекаться примерно на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Залить молоком филе рыбы, приправить горошками черного перца и тимьяном, дать постоять 15 минут, слить молоко и убрать в холодильник, рыбу нарезать на маленькие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Смешать сливки, яйца, добавить холодное молоко, хорошо взбить, картофель нарезать небольшими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7491,'Уложить на готовый корж филе рыбы, нарезанный кубиками картофель, разровнять, посолить, поперчить, залить аккуратно сливочно-молочной смесью, поставить в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7492,'Перекрутить мясо, подсолить, поперчить, добавить измельченный чеснок, все хорошо перемешать, добавить рис, вбить яйцо, хорошо смешать до однородности. Сформовать шарики, уложить на смазанный маслом противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7492,'Для приготовления соуса натереть крупно морковь, лук нашинковать полукольцами, обжарить на масле до мягкости, подсолить, влить немного воды, добавить сметану и муку, перемешать, довести соус до кипения, залить тефтели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7492,'Поставить тефтели под сметанным соусом на 35 минут в духовку, готовить при температуре 180 градусов, подавать к столу в горячем виде с любым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7493,'Подмороженное куриное филе нарезать тонкими кусочками. Положить в полиэтиленовый пакет и отбить. Отдельно натереть плавленый сыр на крупной терке. Вбить сырые куриные яйца, добавить специи и молоко. Смесь взбить венчиком до получения однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7493,'Кусочек отбитого филе обвалять в панировочных сухарях, обмакнуть в сырный кляр и еще раз обвалять. Выложить на сковороду с разогретым подсолнечным маслом, жарить отбивные из курицы с двух сторон до получения аппетитной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7494,'Для приготовления пирожных понадобится кастрюля с толстым дном. Влить в емкость воду и положить сливочное масло, довести до кипения. Масло должно полностью раствориться. В кипящую жидкость всыпать всю пшеничную муку, кастрюлю снять с огня. Хорошо перемешать заварное тесто деревянной ложкой. Масса должна загустеть и начать отставать от стенок кастрюли. Соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7494,'Емкость опустить в таз с холодной водой, налитой на треть объема. Отдельно взбить сырые куриные яйца, влить их в тесто порциями, продолжать взбивать. По консистенции масса должна получиться текучей. Перелить тесто в кондитерский мешок, отсадить пирожные на противень, застеленный пергаментом. Полоски должны достигать семи-восьми сантиметров в длину. Время выпекания – от 20 до 25 минут, температура – 200 градусов. Затем температуру нужно уменьшить до 160 градусов, допечь изделия в течение 10 – 15 минут. Во время приготовления духовку нельзя открывать: тесто осядет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7494,'Для крема перемешать в кастрюле молоко с сахарным песком и ванилином из пакетика. Поставить на огонь средней мощности, довести жидкость до кипения. Снять, немного остудить. Отдельно перемешать муку с остатками сахара, вбить сырые желтки и перемешать при помощи венчика. Влить горячее молоко, перемешивать. В результате должна получиться яично-молочная однородная смесь. Перелить крем в кастрюлю, поставить на тихий огонь, варить до загустения, продолжать помешивать венчиком. В конце приготовления добавить немного растопленного сливочного масла и еще раз перемешать. Готовые домашние эклеры остудить, наполнить кремом при помощи кондитерского шприца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7495,'По отдельности замочить в кипятке изюм и маковое семя. Через час воду слить, ингредиенты обсушить. Сырое куриное яйцо растереть со сметаной и сахарным песком, всыпать муку, перемешанную с пищевой содой. Все взбить. В треть массы добавить грецкие орехи, во вторую часть–изюм, в третью-мак. Испечь три коржа. Температура приготовления–180 градусов, время–полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7495,'Для приготовления крема перемешать молоко с желтками и сахаром. Проварить до загустения на тихом огне в течение семи минут. Остудить массу до комнатной температуры. Взбить мягкое сливочное масло до пышности, добавить в крем. Готовую смесь охладить, а затем промазать ею остывшие коржи торта с наполнителями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7496,'Для приготовления теста взбить сырые куриные белки, добавить сахарный песок и немного соли. Желтки взбить отдельно с остатками сахара и ванилином из пакетика. Постепенно, порциями, влить растительное масло без запаха. Осторожно соединить белковую массу с желтковой, перемешивать движениями снизу вверх, чтобы сохранился объем. Перемешать муку с разрыхлителем, просеять. Отдельно смешать растворимый кофе с какао-порошком и водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7501,'Внизу духовки поставить противень с водой. Накрыть банки металлическими крышками, поместить в холодную духовку, затем разогреть её до 150 градусов. Время тушения – около трех часов. Пока готовится мясо – нарезать сало маленькими кусочками, выложить в жаровню или на сковороду, топить на тихом огне. Мясо залить полученным жиром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11376,'Отварить перловую крупу до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7496,'Застелить пергаментом противень, смазать растительным маслом. Вылить две трети теста и разровнять. В оставшуюся массу добавить какао-кофейную смесь, перемешать. Выложить ложкой на светлое тесто в хаотичном порядке, нарисовать узоры зубочисткой. Печь в течение 15 – 20 минут, температура приготовления – 180 градусов. Готовый корж накрыть тканью или полотенцем, перевернуть и снять пергамент. Горячий пласт свернуть, помогать полотенцем, он не должен разломиться. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7496,'Для приготовления крема взбить сметану и сахарную пудру со специальным загустителем для сливок, который можно приобрести в магазине. Растопить молочный или горький шоколад на водяной бане. Спелый банан очистить и размять в пюре. Соединить массу с шоколадом, ромом или коньяком, перемешать до однородного состояния. Соединить банановую смесь со сметанным кремом. Рулет мраморный осторожно развернуть и смазать полученной массой. Снова свернуть и обрезать края. К столу выпечку подать охлажденной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7497,'Пшеничную муку просеять, насыпать горкой. Сделать небольшое углубление, вбить сырое куриное яйцо, ложку ледяной воды, соль. Сгрести муку к середине, замесить тесто, добавить еще немного воды. Масса должна стать однородной и эластичной. Тесто накрыть увлажненным полотенцем, оставить на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7497,'Для приготовления начинки репчатый лук очистить и порубить, немного обжарить на растительном масле. Перемешать готовый свиной и говяжий фарш, добавить лук, соль, измельченный чеснок, молотый перец, кипяток, перемешать до однородного состояния. Раскатать готовое тесто, вырезать кружки диаметром от семи до восьми сантиметров. Края должны быть тоньше, чем середина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7497,'В центр положить фарш, тесто защипнуть складками, в середине оставить отверстие. Налить воду в позницу, вскипятить, добавить лавровый лист. Выложить позы на решетки, дно каждого изделия обмакивать в растительное масло. Готовить на пару в течение 20 минут, крышка должна быть плотно закрыта, вода–кипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7497,'Изделия выложить на блюдо, отдельно подать соевый соус. Едят манты с мясной начинкой горячими, руками. В отверстие, оставленное сверху, можно капнуть немного соевого соуса, осторожно выпить сок, выделенный фаршем и луком во время приготовления, а затем съесть начинку и тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7498,'Мягкое сливочное масло взбить с сахарным песком, вбить яйцо и добавить пшеничную муку. Должно получиться мягкое и эластичное тесто. Поставить его на полчаса в холодильник. Разделить готовую массу на четыре части, раскатать в тонкие коржики, это можно сделать между двумя листами бумаги, на ней же и выпечь изделия в течение нескольких минут, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7498,'Края обрезать, крошки сохранить для украшения. Готовый торт промазать кислым джемом или вареньем, например, брусничным, завернуть в лист фольги и поставить под груз на несколько часов для пропитывания. При подаче бока и верх простого тортика намазать джемом и посыпать крошками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7499,'Любую красную рыбу нарезать стейками. Противень застелить листом фольги, выложить кусочки лимона и нарезанный репчатый лук. Филе разместить сверху, посолить и поперчить, побрызгать лимонным соком, положить по кусочку помидора, лавровый лист. Закрыть фольгой, печь красную рыбу в фольге полчаса, температура приготовления – от 180 до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7500,'Взбить сырые куриные яйца с сахарным песком, добавить ванильный сахар, сметану, пищевую соду. Всыпать просеянную муку. Дать тесту постоять для набухания клейковины. Из яблок вырезать сердцевину, нарезать кусочками, кожицу можно не убирать, если она тонкая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7500,'Выложить фрукты в форму, смазанную маслом и присыпанную сухарями. Если использовать силикон – такую подготовку делать не нужно. Посыпать начинку молотой корицей. Залить тестом, печь при температуре 180 градусов. Время приготовления – около 45 минут. Сладкую шарлотку остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7501,'Свинину промыть, нарезать кусочками среднего размера, соль и перец молотый – по вкусу, перемешать. Выложить продукт в небольшие стеклянные банки, заранее хорошо промытые. Стерилизовать не обязательно. На дно банок выложить по два лавровых листа, горошины душистого перца. До верха банки должно остаться по два-три сантиметра свободного пространства.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Отправить в горячую духовку, готовить минут шестьдесят.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7501,'Вынуть банки из духового шкафа, закатать, перевернуть и проверить на герметичность. Перевернуть обратно, сок должен быть внизу, жир – наверху. Хранить такую домашнюю тушенку из свинины можно при комнатной температуре или в прохладной кладовке. Время хранения – около года.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7502,'Зеленый лук быстро нарезать, покрошить кубиками сардельку. Взбить сырые яйца, добавить сметану, перемешать. Всыпать пшеничную муку, соль по вкусу, лук и сардельку, еще раз перемешать. Жарить как блины, на раскаленной сковороде, с двух сторон. При готовности быструю лепешку сверху посыпать тертым сыром, сложить пополам и подать к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7503,'В большой емкости перемешать пшеничную или рисовую муку, картофельный крахмал, щепотку соли и сахарный песок. Подлить молоко, перемешать. Вбить сырые куриные яйца, растопленное сливочное масло. Ингредиенты взбить при помощи венчика. Жарить как обычные блины, с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7503,'Для приготовления начинки смешать сметану с творогом и сгущенным молоком. Намазать блин. По желанию можно выложить два или три блина для основы, внахлест. На край выложить банан, нарезанный дольками, свернуть в ролл. Обжать, нарезать на кусочки. Приготовить соус из сахара, какао-порошка, мягкого сливочного масла и сметаны. Массу прогреть, полить рулетики из блинов и подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7504,'Огурцы вымыть и разрезать каждый вдоль на четыре части. Приготовить заправку: перемешать сахарный песок с солью, молотым перцем и сухой горчицей. Пересыпать в огурцы. Влить растительное масло, уксус и воду, еще раз перемешать. Очистить и измельчить чеснок, добавить в основную массу, оставить на три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7504,'Пропитанные приправами огурцы плотно разложить в небольшие банки, залить получившимся маринадом. Поставить банки в кастрюлю, дно застелить полотенцем. Время стерилизации – 15 минут после начала кипения. Прикрыть емкости металлическими крышками. Готовые огурчики в горчичной заливке закатать, перевернуть, укутать одеялом до полного остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7505,'Вылить пиво в кастрюлю, добавить гвоздику, корицу, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7505,'Процедить пиво, перелить в кастрюлю и поставить на слабый огонь, чтобы не остывало.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7505,'Желтки растереть с сахаром, постепенно подливая горячее пиво, смесь должна загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7505,'Подать к столу горячий пивной «Польский» суп с гренками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7506,'Замесить тесто из муки, мягкого сливочного масла, щепотки соли и нежирной сметаны. Поставить массу в холодильник на три часа или на ночь. Холодное тесто вынуть, разделить пополам, каждую тонко раскатать и вырезать круги диаметром около 30 сантиметров. Наколоть их ножом или вилкой, печь при температуре 200 градусов, время – от 20 до 35 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7506,'Коржи остудить на решетке. Можно выпечь квадратные заготовки, а потом обрезать. Для крема вскипятить молоко с сахарным песком. Третью часть молока взбить с яйцами, всыпать крахмал и муку, перемешать до однородного состояния. Во время взбивания крахмально-мучной смести горячее молоко влить тонкой струйкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7506,'Массу перелить в небольшую кастрюлю и варить до густоты. Выложить корж в форму, на него вылить горячий крем, оставить немного для украшения. На крем уложить второй корж, намазать остатками, поставить в холод на три или четыре часа. На готовый польский пирог выложить свежую малину, плотно, ягодка к ягодке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7507,'Говяжьи почки разрезать пополам, залить охлажденной водой, подержать три часа, затем промыть, залить свежей порцией воды, варить до готовности. Остудить, нарезать кубиками. Подсолить воду и отварить в ней говядину и свинину, остудить, также нарезать кубиками. Бульон не выливать. Очищенный лук и чеснок мелко нарезать, на горячую сковороду выложить кусочки сала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7507,'Выложить лук, обжарить. Добавить томатную пасту и нарезанные маринованные огурцы, прогреть. В оставшийся бульон положить мясные продукты, добавить обжарку, чеснок, черный и красный молотый перец, соль. Варить в течение семи минут. Готовую мясную солянку с почками и салом разлить в тарелки, заправить сметаной по вкусу, положить колечки маслин и ломтики лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7613,'Протереть через сито творог, можно пропустить через мясорубку, вбить яйца, добавить сахар и ванилин, хорошо перемешать, постепенно всыпать муку и вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7508,'Супчик с охотничьими колбасками очень ароматен, такой рецепт трудно забыть. Репчатый лук нарезать кольцами, обжарить на растительном масле. Готовый мясной бульон довести до кипения, выложить луковую обжарку, томатную пасту, мелко нарезанные маринованные огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7508,'Следующий ингредиент – сладкий болгарский перец кольцами, картофель, нарезанный кубиками, приправить лавровым листом. Смесь варить на тихом огне. За 10 минут до готовности положить нарезанные колбаски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7508,'Готовый суп заправить каперсами, соль и перец – по вкусу, добавить сахарный песок. Солянку с охотничьими колбасками и каперсами разлить в тарелки, положить по ложке сметаны и по кусочку лимона. В это блюдо можно также добавить копченую грудинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7509,'Морковь и лук нарезать соломкой, обжарить на масле до готовности вместе с томатной пастой. Соленые огурцы нарезать, жарить без масла до выпаривания влаги. Нарезать ломтиками сосиски и сардельки, лимон – дольками, копченую курицу – кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7509,'Куриное мясо залить водой, варить 20 минут. Выложить в бульон прочие мясопродукты, овощи, оливки. Варить мясную солянку с копченой курицей еще 15 минут, соль и перец – по вкусу. При подаче в тарелки положить кусочки лимона, каперсы, сметану, маслины. Каждую порцию щедро посыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7510,'Для приготовления солянки с беконом и сердцем уйдет немного больше времени, но это блюдо того стоит. Нежирную грудинку на косточке выложить в кастрюлю, залить водой, довести до кипения, пену снять. Нарезать морковь и лук, положить в суп, варить в течение полутора часов, кипение – минимальное. Бульон отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7510,'С кости снять мясо, нарезать средними кусочками. Нарезать кружками охотничьи колбаски, мелкими кубиками – бекон. Выложить бекон на раскаленную сковороду, вытопить жир, положить мелко нарезанный лук, пассеровать 10 минут. Удалить у сердца сосуды и прожилки, субпродукт нарезать кубиками, положить к луку, жарить на огне до золотистой корочки. Обжарку переложить в бульон, варить полчаса на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7510,'Соленые огурцы мелко нарезать, обжарить. Колбаски выложить на сковороду вместе с топленым маслом, добавить огурцы, огуречный рассол и томатную пасту. Довести смесь до кипения, переложить в суп, посолить по вкусу и поперчить. Потомить солянку с говяжьим сердцем и беконом  под крышкой в течение 15 минут. При подаче заправить сметаной, маслинами, петрушкой и кусочками лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7511,'Солянка с грибами особенно вкусна, если она приготовлена с настоящими лесными опятами. Мелко нарезать копченую колбасу, сосиски и сардельки, все обжарить на растительном масле. Отдельно жарить репчатый лук с морковью. Маринованные огурцы мелко накрошить, положить в морковную обжарку, прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7511,'Нарезать сладкий болгарский перец, помидоры ошпарить и очистить от кожицы, мякоть мелко нарезать. Добавить то и другое в обжарку, положить томатную пасту и перемешать. Сердца очистить, залить водой, посолить, варить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7511,'Добавить картофель, зажарку, колбасу. Добавить обжаренные опята, долить огуречный рассол, положить перец-горошек, соль – по вкусу. Довести солянку с опятами и куриным сердцем до кипения, варить на тихом огне полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7512,'Прогреть молоко до комнатной температуры, перемешать с сухими дрожжами и сахарным песком, поставить в тепло на 15 минут. Всыпать пшеничную муку, влить растительное или растопленное сливочное масло, добавить соль. Замесить тесто. Готовую массу разделить на восемь частей. Можно использовать готовое тесто, купленное в магазине. Раскатать его по размеру сосисок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7512,'Каждую сосиску закатать в тесто, надрезать поперек на 10 или 12 частей. Кусочки теста с сосиской развести в разные стороны и одновременно развернуть вверх. Противень смазать растительным маслом, выложить булочки. Перемешать молоко с яйцами, смесью смазать заготовки, посыпать их твердым тертым сыром. Время выпекания булочек с сосисками  в духовке – 20 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7532,'Крупу промыть, залить стаканом воды, сварить до готовности без соли. Отдельно на сковороде обжарить репчатый лук и тертую морковь. В уже остывающую гречку добавить соевый соус. Гречку пересыпать в обжарку, перемешать, сверху разбить яйцо и запечь под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7513,'Кабачки очистить от кожуры, нарезать пластинками толщиной в один сантиметр. Посолить и поперчить, можно добавить давленый чеснок, перемешать. Для приготовления кляра растереть сырое куриное яйцо с солью, добавить примерно полстакана кефира или простокваши. Также можно использовать пиво, молоко или обычную воду. Досыпать муку так, чтобы получилось полужидкое тесто, гуще, чем для блинов, но жиже, чем тесто для оладий.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7513,'Кабачки обвалять в муке, окунуть в кляр, обжарить на подсолнечном масле с двух сторон. Слишком загустевший от муки кляр можно разбавить простоквашей или соком от кабачков. Приготовить сметанный соус из нарезанной свежей зелени укропа и петрушки, базилика, пропущенного через пресс чеснока, соли и сметаны, подать кабачки в кляре и соус к столу отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7514,'Мягкое сливочное масло и сахар мелкого помола растереть с помощью блендера или ложкой. Добавить сначала яйцо, а затем сметану, растереть или взбить до растворения сахарного песка, на это потребуется несколько минут. Смесь должна получиться нежной, похожей на крем. Просеять в массу муку с разрыхлителем и солью, лопаткой или ложкой замесить тесто. Оно должно быть липким, поставить массу в холодильник на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7514,'Приготовить начинку из творога, сахара, манной крупы, яичного белка и сметаны. Желток оставить для смазывания верха. Ингредиенты положить в комбайн и взбить венчиком в течение нескольких минут, получится пышная однородная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7514,'Разделить охлажденное тесто на 14 или 16 частей, раскатать небольшие лепешки, стол присыпать мукой. Можно раскатать все тесто сразу, вырезать кружки стаканом или выемкой. На каждую лепешку положить начинку, загнуть половину сверху, прижать по краю, но не защипывать. Готовые сочни смазать желтком. Печь сочни с творогом в духовом шкафу при температуре 210 – 220 градусов в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7515,'Вылить пиво в кастрюлю, положить ржаной хлеб без корок, дать закипеть, добавить сахар, тмин, сливочное масло, соль и еще раз нагреть до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7515,'Измельчить все в блендере и разбавить двумя стаканами кипятка, подавать польский пивной суп «Граматка» или «Фарамушка» горячим с гренками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7516,'Смешать сметану с мукой, растопленным маслом и желтками яиц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7516,'Добавить к смеси слегка подогретое пиво, нагреть до кипения, выключить нагрев, дать постоять 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7516,'Положить перед подачей в пивной суп со сметаной по-варшавски гренки из батона и посыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7517,'Нарезать хлеб на кусочки по 0,5 см (не более), корку срезать, можно взять уже порезанный хлеб для тостов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7517,'Разложить хлеб на пленке внахлест, сверху накрыть концом пленки и прокатать скалкой с некоторым усилием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7517,'Смазать полученный пласт мягким сыром, выложить на него кусочки форели, присыпать измельченной зеленью лука и свернуть в рулет, завернуть в фольгу и убрать в холодное место на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7517,'Хлебные роллы с сыром и форелью подаются нарезанными поперек на кусочки, каждый кусочек смазывается майонезом и присыпается поджаренным кунжутом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7518,'Любую вареную или копченую колбасу нарезать соломкой, шампиньоны – кубиками. Сырковую массу и сметану перемешать до однородного состояния. Лаваш смазать полученной массой, выложить колбасу, посыпать грибами, тертым твердым сыром. Свернуть лепешку рулетом, нарезать на порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7518,'Жарить на разогретой сковороде, с обеих сторон, на растительном масле. Должна получиться золотисто-коричневая корочка. Выложить жареный лаваш с колбасой и грибами на салфетку для впитывания лишнего жира. При подаче украсить листочками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7519,'Сладкий болгарский перец, шампиньоны и репчатый лук накрошить и по отдельности обжарить. Отварить рис в подсоленной воде в течение 10 минут, промыть холодной водой и охладить. Мелко нарезать куриную грудку, обжарить со специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7519,'Соединить все ингредиенты: мясо, рис, овощи и грибы, мороженый зеленый горошек. Перемешать сметану с яйцами и тертым сыром, залить смесь. Форму для выпекания смазать оливковым маслом, выложить массу, посыпать остатками сыра. Печь рисовую запеканку с овощами и курицей в течение 25 минут, температура – около 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7520,'Для приготовления плотной массы творог растереть с сырым куриным яйцом, сахаром и ванилином из пакетика. Всыпать крахмал, хорошо перемешать, в тесте не должно быть комочков. Для пышной шоколадной части сырое яйцо взбить с сахаром и ванилином. Подлить кефир, перемешать, всыпать муку и разрыхлитель, все ингредиенты взбить в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7520,'Добавить какао-порошок, затем влить растительное масло, еще раз хорошо перемешать. Тесто должно получиться густым и однородным. Форму для выпекания смазать маслом, выложить шоколадное тесто ровным слоем, творожную массу разместить хаотично, нарисовать любые узоры деревянной палочкой. Температура выпекания – до 180 градусов, время – от 40 до 45 минут. Готовность творожного пирога проверяется зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7521,'В мисочке перемешать сухие ингредиенты – соль, сахарный песок, пищевую соду, пшеничную муку. Взбить с помощью миксера сырое куриное яйцо с молоком и рафинированным растительным маслом. Взбить ингредиенты в пышную пену на больших оборотах. Масса должна значительно увеличиться в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7521,'Соединить сухую смесь с молочной также при помощи миксера. Сухую сковороду разогреть, налить тесто столовой ложкой, печь до появления пузырей. Перевернуть панкейки на молоке деревянной лопаткой, жарить с другой стороны до готовности. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7522,'С помощью миксера взбить молоко с растительным маслом, сахаром и какао-порошком. Половину полученной смеси перелить в отдельную емкость. Вбить сырые куриные яйца, муку, просеянную вместе с разрыхлителем, всыпать ванилин из пакетика. Массу взбить миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7522,'Тесто вылить на заранее смазанный маслом противень. Время приготовления в духовке – полчаса, температура – 175 градусов. Готовый корж вынуть, немного остудить и полить оставшейся шоколадной смесью. Остудить шоколадные пирожные окончательно и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7523,'Размягчить сливочное масло, взбить с сахарным песком при помощи миксера. Постепенно всыпать муку, смешанную с разрыхлителем, вбить сырые куриные яйца, добавить творог и тертую цедру небольшого лимона, натертую на мелкой терке. Должно получиться воздушное, негустое тесто. Переложить массу в формы, печь лимонные кексы в течение 35–40 минут, время зависит от возможностей духовки. Температура приготовления–180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7524,'Сливочное масло заморозить, а затем натереть, нужно сделать это быстро. Продукт снова поставить  в морозильную камеру еще на две минуты. Перемешать ложкой с пшеничной мукой и щепоткой соли. Сделать небольшое углубление посередине, вбить яйцо, две ложки ледяной воды, очень быстро замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7524,'Завернуть массу в пленку, поставить в холод на полчаса. Затем тесто разделить на две неравные части: две трети и одну треть от общей массы. Меньшую часть вернуть в холодильник, большую раскатать и переложить в форму. Накрыть фольгой, насыпать любой груз, например, горох, поставить в духовой шкаф на 15 минут, температура выпекания – 200 градусов. Груз удалить, печь еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7524,'Приготовить начинку: крупными кусочками нарезать рыбу, брынзу – кубиками. Шпинат разморозить, перемешать в кастрюле с рыбой и брынзой. Добавить несколько ложек сметаны, соль – по вкусу. Выложить начинку на корж, накрыть верхним слоем теста и наколоть в нескольких местах вилкой. Поставить пирог с семгой и брынзой в духовой шкаф на 80 минут, температура приготовления – 180 градусов. В конце выпечку смазать яйцом и допечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7525,'Ребрышки вымыть и обсушить, удалить лишний жир и пленки. Перемешать в небольшой емкости порошковый чеснок, эстрагон, молотый перец чили, базилик, копченую или обычную молотую паприку, соль. Втереть смесь в ребрышки. Завернуть в два слоя фольги, швы должны быть плотными, чтобы не вытекала выделяющаяся жидкость. Поставить в духовой шкаф на два часа, температура приготовления – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7525,'Незадолго до окончания тушения приготовить соус из кетчупа, красного винного уксуса, коричневого сахара, ингредиенты хорошо перемешать. Вытащить свиные ребрышки из духовки и намазать полученной смесью одну сторону. Поставить допекаться в режиме гриля в течение пяти минут, огонь – слабый. То же самое проделать с другой стороной. Блюдо можно готовить и на открытом, но непрямом огне. На гарнир – запеченная картошка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7526,'Мясо нарезать кубиками небольшого размера, обжарить с растительным маслом на сковороде. Влить немного воды, положить лавровый лист, тушить блюдо под крышкой до готовности на тихом огне. Отдельно перебрать гречневую крупу, залить ее кипятком, оставить на пять минут для набухания, затем воду слить. Мелко нарезать репчатый лук, обжарить на сковороде вместе с тертой морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7526,'Овощи добавить в мясо вместе с измельченным чесноком, соль и перец – по вкусу. Всыпать гречку, долить горячую воду, крупа должна быть покрыта на палец. Довести гречку по-купечески до кипения, накрыть, томить под крышкой до тех пор, пока вся жидкость не впитается. Огонь выключить, положить кусочек сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7527,'Крупу промыть, варить до мягкости. Отварить куриные яйца. Мелко нарезать очищенный репчатый лук. Разогреть на сковороде растительное масло, обжарить лук до прозрачности. Натереть морковь, добавить в лук, жарить все вместе в течение пяти – семи минут, помешивать, чтобы продукты не пригорели. Обжарку переложить в крупу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7527,'В той же сковороде обжарить нарезанные грибы в течение десяти минут, до готовности. Переложить грибы в гречку. Готовые яйца очистить и нарезать ножом кубиками или с помощью яйцерезки, добавить в гречку, все ингредиенты перемешать. Подавать гречку по-русски к столу как отдельное блюдо или как гарнир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7528,'Выложить мясной фарш на сковороду, через две минуты добавить нарезанный сладкий болгарский перец и очищенные от кожуры помидоры. Продукты обжарить, в конце приготовления добавить соль, любые специи. Лук можно обжарить отдельно. Отварить гречку в бульоне, использовать готовые кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7528,'Соединить фарш и гречку, вымешать, дать постоять, накрыть тканью. Разложить в горшочки и посыпать тертым твердым сыром любого сорта. Поставить в духовой шкаф на 20–30 минут, температура приготовления – 200 градусов. При появлении румяной корочки душеновскую гречку вынуть и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7529,'Крупу перебрать, хорошо промыть в проточной воде. Нарезать морковь и репчатый лук, овощи обжарить в кастрюле небольшого размера, на сливочном масле. В этой же емкости блюдо будет запекаться в духовке. Нарезать мелкими кубиками буженину, ветчину, грудинку, добавить в овощи, перемешать и обжарить. Можно добавить немного воды или бульона. Всыпать специи, паприку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7529,'Поверх готовой обжарки высыпать крупу, ингредиенты не перемешивать. Долить бульон или воду. При закипании пенку снять, накрыть, поставить гречку с овощами и копченостями в заранее разогретую духовку. Температура приготовления – 180 градусов, время – 40 минут. Время зависит от возможностей духовки, вода должна выкипеть полностью. Должно получиться ароматное, вкусное и разваристое блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7530,'Репчатый лук очистить и мелко нарезать. Спассеровать на масле до золотистого цвета. Добавить в обжарку фарш. Отдельно ошпарить помидоры, снять кожицу, мякоть нарезать кубиками небольшого размера. Кастрюльку с водой поставить на огонь. Добавить соль, гречку, лавровый лист. Довести до кипения, огонь убавить, закрыть крышкой, варить до готовности. Нарезать морковь, переложить ее к фаршу с луком, перемешать, обжарить до готовности фарша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7530,'Добавить соль по вкусу, помидоры, молотый черный и красный перец, паприку. Все вместе потушить в течение пяти минут, огонь – средний, через пять минут крышку снять, варить еще пять минут. Соус должен загустеть. По желанию добавить томатную пасту. Переложить фарш с овощами, перемешать, подать гречку с мясным фаршем и томатами к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7531,'Свинину или говядину нарезать кусочками небольшого размера, выложить на дно горшочка. Репчатый лук нарезать тонкими кольцами или полукольцами, положить поверх мяса. Добавить лавровый лист, перебранную и промытую гречку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7531,'Отдельно вскипятить воду, развести в ней порошковый бульон, залить содержимое горшочка. Можно использовать обычный овощной или мясной бульон. Накрыть горшочек крышкой, поставить в духовой шкаф на час, температура приготовления – от 180 до 190 градусов. При подаче гречневую кашу заправить сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7566,'Украсить морковный салат «Шикака» с сыром и изюмом зернами граната и веточками петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7709,'Порезать брынзу на кусочки, растереть ложкой, вбить яйцо, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7533,'Грибы очистить, вымыть, нарезать и обжарить вместе с репчатым луком на сливочном масле. Соль и молотый перец – по вкусу. Готовые ингредиенты разложить в горшочки, насыпать в каждый заранее промытую крупу, ее должно быть в три-четыре раза больше по объему, чем грибов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7533,'Залить бульоном из кубиков или обычным, мясным или овощным. Жидкость должна покрывать крупу на два пальца. Перемешать, поставить в духовой шкаф на 25 минут, тушить под крышками, температура приготовления – 200 градусов. Крышки снять, подержать гречку с грибами в горшочках еще 10 минут в выключенной духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7534,'Деревянные шпажки замочить в воде на полчаса. Филе курицы нарезать длинными полосками, нанизать гармошкой. Приготовить маринад из сахарного песка, кориандра, растительного масла и соевого соуса, соли, перца и пропущенного через пресс чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7534,'Опустить шпажки в маринад, накрыть пищевой пленкой, поставить на два часа в холодильник. Маринованное мясо выложить в форму, поставить шашлычок из куриного филе в заранее разогретую до 200 градусов духовку на 20 минут. Один раз шпажки перевернуть, должна получиться золотистая корочка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7535,'Для приготовления блюда понадобится жирная сельдь. Тушку нужно разморозить на нижней полке холодильника. Отрезать голову, удалить жабры, разрезать брюшко, удалить внутренности. Вдоль спинки разрезать кожу, снять ее от головы к хвосту, с обеих сторон. Делать это нужно аккуратно, чтобы не оторвались кусочки мяса. Вырезать плавники и удалить хвост, достать хребет. Разделяем тушку пополам со спины, вынимаем ребра и другие мелкие кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7535,'Филе нарезать небольшими кусочками шириной в два сантиметра. Нарезать тонкими кружками лимон, лук – кольцами, натереть морковь. Все продукты выложить в банку слоями: лук – на дно, затем лавровый лист, немного моркови, лимон, сахарный песок, молотый перец. Сверху – сельдь, слои повторить несколько раз, их нужно уплотнять. Заполненную банку закрыть крышкой, поставить в холодильник. Через день или два сельдь по-голландски будет готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7536,'Куриное филе нарезать небольшими кусочками, добавить перетертые томаты или разведенную водой томатную пасту, соевый соус, кунжутное масло, натуральный мед и красный перец. Ингредиенты хорошо перемешать, оставить мариноваться на час при комнатной температуре. Разогреть сковороду, выложить мясо с маринадом, обжарить в течение двух минут, перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7536,'Прогревать без крышки. Жарить куриное филе в медовом соусе еще две минуты, снова перевернуть. Должна получиться румяная корочка. Накрыть блюдо крышкой и тушить в течение двух или трех минут. Вся тепловая обработка должна занять не более десяти минут, иначе курица может стать жесткой и невкусной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7537,'Перемешать овсяные хлопья, нежирное молоко, белок, какао-порошок, свежезаваренный кофе. Добавить подсластитель по вкусу, это может быть обычный сахарный песок или любой сахарозаменитель. Обычную фарфоровую чашку смазать маслом, налить смесь, поставить в микроволновую печь на две минуты, мощность – максимальная.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7538,'В емкости для миксера соединить сухие дрожжи с мукой, солью, сахарным песком. Перемешать, добавить сырое куриное яйцо, растительное масло, теплую воду. Перемешать ингредиенты ложкой, а затем насадкой с крючком. Месить тесто в течение десяти минут, до эластичного состояния. Переложить массу в миску, заранее смазанную маслом, прикрыть пищевой пленкой, поставить в тепло. Тесто должно увеличиться в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7538,'Застелить противень для выпекания бумагой. Тесто разделить на четыре равные части. Смазать пекарскую бумагу мягким сливочным маслом. Части теста растянуть в прямоугольники, каждый хорошо смазать тем же мягким сливочным маслом. Любую начинку выложить вдоль по большей стороне, свернуть булочки в рулеты, а затем закрутить в виде улитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7538,'Выложить изделия на противень, верх смазать сливочным маслом и поставить в тепло на 30 или 40 минут. Разогреть духовой шкаф, печь булочки в течение 20 минут при температуре 180 градусов. Готовые испанские булочки посыпать сахарной пудрой и остудить на решетке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7567,'Сделать на шкурке свиной грудинки насечки в виде ромбиков по 2 см, натереть мясо смесью перцев и соли со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9745,'Подавать запеченную скумбрию с петрушкой и луком, украсив зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7539,'Вымыть шампиньоны, нарезать и обжарить на масле вместе с нарезанным репчатым луком до готовности. Перец и соль – по вкусу. Натереть на терке нежирный сыр любого сорта. Нарезать зелень лука, укропа, петрушки. Разложить на столе лист армянского лаваша, сверху – обжарка с грибами, второй слой–зелень и сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7539,'Начинку разровнять так, чтобы она не доходила до края. Верхний и нижний край подогнуть внутрь, чтобы не вытек расплавившийся сыр. Затем весь лаваш свернуть рулетом. Отдельно взбить сырое куриное яйцо и смазать заготовку. Печь рулет из лаваша с сыром и грибами в течение 15 минут, температура приготовления – 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7540,'Собранные молодые стрелки чеснока тщательно вымыть и отрезать жесткую часть. Выложить на бумажное полотенце для обсушивания. Переложить продукт в чашу блендера, посолить, влить растительное масло, измельчить. Должна получиться красивая паста насыщенного изумрудного цвета. Переложить ее в контейнер, заморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7541,'Взбить два яичных желтка, одно целое яйцо, добавить соль и сахар. Постепенно ввести молоко и муку. Отдельно взбить два оставшихся белка и добавить их в основную массу, осторожно перемешать. Половину получившегося теста вылить в заранее смазанную маслом форму, выложить свежую или размороженную вишню, залить остатками теста. Время выпекания – от 20 до 30 минут, температура – 200 градусов. Подавать клафути с вишней на стол в охлажденном виде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7542,'Просеять муку, соль и пекарский порошок. Отдельно перемешать размягченное сливочное масло, сахарный песок и греческий йогурт. Использовать миксер, взбить массу на средней или высокой скорости в течение двух минут. Скорость убавить, вбить сырое куриное яйцо, ингредиенты еще раз взбить, смесь должна стать пышной и легкой. Добавить молоко и экстракт ванили.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7542,'Перемешать муку с полученной жидкой смесью, добавить шоколадную стружку. Переложить тесто в выложенную пергаментом и смазанную маслом форму для выпекания. Сверху – разрезанные пополам ягоды клубники. Время приготовления – один час, температура – 220 градусов. За 10 – 15 минут до конца клубнично-шоколадный пирог из духовки вынуть и посыпать шоколадными стружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7543,'Готовое слоеное тесто из магазина разморозить. Для приготовления начинки натереть сыр на крупной терке. Части курицы хорошо вымыть и обсушить. Мясо отделить от костей, нарезать кубиками небольшого размера. Разогреть в сковороде растительное масло, обжарить куриное мясо со всех сторон на сильном огне в течение трех – четырех минут. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7543,'Репчатый лук очистить и нарезать тонкими полукольцами. На другой сковороде также разогреть масло и обжарить лук до получения золотистого цвета. Стол присыпать мукой, выложить тесто, разрезать его на равные части. Каждую немного раскатать в одном направлении, чтобы не нарушить структуру продукта.  Выложить обжаренный лук, мясо, посыпать сыром. Закрыть слойку оставшимся, свободным краем лепешки, в нескольких местах надрезать. Край можно украсить роликом для нарезания сетки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7543,'Края теста хорошо соединить и смазать белком. Для прочности можно пройтись по краю вилкой. Застелить противень бумагой для выпекания, выложить изделия, смазать немного взбитым яйцом. Духовку разогреть заранее, температура приготовления – 180 градусов, время – от 30 до 40 минут. Слойки с курицей и сыром должны приобрести золотистый цвет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7544,'Свиное мясо нарезать на куски, тонко отбить с двух сторон, посолить и поперчить по вкусу. Шампиньоны и очищенный репчатый лук нарезать кубиками, обжарить на растительном масле до полуготовности. Натереть сыр, измельчить зелень петрушки. Соединить лук, грибы, зелень и сыр, молотый перец, соль. Готовую начинку выложить на мясо, сформовать овальные котлеты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7544,'Смочить изделия в яйце и обвалять в муке. Поверх выложить тертый картофель, аккуратно прижать к котлете. На сковороде разогреть растительное масло, отбивные жарить с двух сторон до получения золотистой корочки. Готовые котлеты с грибами в картофельной шубе переложить на блюдо, довести до готовности в микроволновке в течение пяти или десяти минут. Украсить сеточкой из майонеза и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7613,'Посыпать стол мукой, раскатать тесто в жгут диаметром примерно 2,5 см, нарезать кусочками шириной 1,5 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7545,'Белки взбить в стойкую пену, добавить сахарный песок мелкого помола или пудру, взбить еще раз до плотности. Подлить лимонный сок, ванильный экстракт, всыпать крахмал. Взбить массу в третий раз до растворения сахара. Противень застелить пергаментом, на обратной стороне бумаги нарисовать круги от 16 до 18 сантиметров в диаметре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7545,'Присыпать пергамент сахарной пудрой, чтобы меренги не прилипли. Выложить массу в форме двух кругов, печь при температуре 130 градусов в течение 40 – 50 минут, затем температуру увеличить до 170 градусов, печь еще пять – семь минут. Изделия вынуть из духового шкафа и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7545,'Для приготовления крема взбить жирные сливки, масса должна получиться густой и плотной. Всыпать сахарную пудру, добавить ванильный экстракт, взбить. Один корж смазать половиной полученного крема, выложить половину ягод малины. Накрыть вторым коржом, украсить ягодами и остатками крема. Десерт «Павлова» с малиной присыпать рублеными фисташками, сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7546,'Отделить желтки от белков, яйца должны быть охлажденными. Взбить белки в плотную пену, чтобы продукт лучше взбивался, в него нужно добавить щепоть соли. Желтки взбить с сахаром и ванилином. В полученную массу добавить половину белков, массу осторожно перемешать ложкой. Всыпать просеянную муку порциями, в нее заранее должен быть вмешан разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7546,'Осторожно ввести остатки белков. Форму для выпекания ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Выбрать для приготовления закуски слабосоленую жирную сельдь и сладкий лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Разделать сельдь на филе и порезать на кусочки, отварить картофель в мундире, нашинковать мелко лук, натереть на терке сыр, сырую морковь и картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Смешать сыр с морковью, добавить раздавленный прессом чеснок, заправить майонезом и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Выложить слоями в форме змеи на овальное блюдо в следующей последовательности: сельдь, лук, картофель (смазать растительным маслом), морковь с сыром (голову оформить из этой же смеси).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Нарезать тоненькими колечками маслины и выложить сверху в виде змеиной кожи, дополнить оформление закуски зеленью петрушки и укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7547,'Новогодняя сельдь под змеиной шубой станет прекрасным украшением праздничного стола.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7548,'Взбить яйца с сахаром до увеличения массы в два раза. На этот процесс понадобится не менее десяти минут. Добавить кипяток, ванилин и растительное масло. Готовое тесто вылить в форму, печь в заранее разогретой духовке, температура – 180 градусов. Время зависит от возможностей кухонной техники. Готовность бисквита на кипятке проверить спичкой или зубочисткой. Перевернуть форму вверх дном и поставить на решетку до остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7549,'Белки взбить, добавить соль и сахар, кислоту. Масса должна получиться мягкой. Всыпать муку, перемешанную с сахарной пудрой, осторожно перемешать. Тесто выложить в прямоугольную форму небольшого размера или в круглую. Время выпекания – от 20 до 30 минут, температура – 180 градусов. Остудить ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7550,'Яйца перемешать и взбить с молоком до появления пены. Добавить маргарин, немного соды, погашенной уксусом, ванильный сахар. Все ингредиенты быстро перемешать. Всыпать муку, замесить мягкое тесто. Скатать массу в колобок, обернуть пищевой пленкой, поставить песочное тесто в холод на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Морковь, картофель и свеклу отварить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Все овощи остудить и очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Репчатый лук измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Селедочное филе нарезать небольшими кусочками. Внимательно отнестись к наличию костей, их нужно аккуратно удалить. Овощи натереть на терке с мелкими ячейками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Выложить на блюдо первый слой картофеля и смазать майонезом, который можно приготовить самостоятельно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Выложить сельдь, еще раз смазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7551,'Следующие слои – лук, майонез, морковь, майонез, свекла. Верх сельди под шубой украсить узорами из того же майонеза, посыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7567,'Промыть, обсушить курагу и чернослив, мелко нарезать, измельчить скалкой орехи, все хорошо перемешать, включить для разогрева до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Перемешать с сухими ингредиентами до получения смеси, похожей на густую сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7552,'Филе слабосоленой сельди нарезать мелкими кусочками. Морковь, картофельные клубни и свеклу отварить по отдельности. Все овощи очистить и натереть, измельчить репчатый лук. Отварить яйца вкрутую, очистить, натереть на терке или порубить. Хорошо промыть и обсушить зеленый лук, мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7552,'Выложить на блюдо слой сельди, затем – слой лука, смазать домашним или покупным майонезом. Далее выложить слоями картофель, свеклу, морковь. Слои присаливать и пропитывать майонезом. Края сельди под шубой выровнять, бока и верх смазать майонезом, украсить веточками укропа, посыпать измельченным яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7553,'Выложить на тарелку кусочек черного хлеба. На хлеб поставить форму для салата и вдавить бортики, часть хлеба должна оказаться внутри. Срезанные края убрать. Мелкими кубиками нарезать филе лосося, выложить на хлеб. На слой рыбы выложить кубики отваренного картофеля, полить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7553,'Далее – слой моркови, также нарезанной кубиками, майонез, кубики свеклы, майонез. Форму снять, бока получившейся башенки посыпать зеленым луком, украсить лосось под шубой веточками петрушки и укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7554,'Селедочное филе нарезать маленькими кусочками. Неочищенный картофель, свеклу и морковь отварить до готовности. Овощи остудить, очистить, натереть на крупной терке. Отдельно очистить и измельчить репчатый лук. Сварить вкрутую яйцо, натереть. Маринованные огурчики нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7554,'Выложить половину готового картофеля на блюдо большого размера, следующие слои – сельдь и лук, майонез. Далее – морковь, часть свеклы, яйца, все слои пропитывать майонезом, соль – по вкусу. Сверху выложить остатки картофеля и маринованные огурцы, свеклу. Верх разровнять, полить майонезом и поставить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7555,'Традиционную свеклу, картофель и морковь отварить до готовности в подсоленной воде. Овощи остудить, очистить и мелко натереть либо нарезать кубиками. Филе сельди измельчить. Репчатый лук и яблоко очистить и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7555,'На дно большого плоского блюда выложить слой картофеля, майонез. Следующие слои – сельдь, репчатый лук, яблоко, свекла. Каждый ингредиент промазывать майонезом. Соль – по вкусу. Готовую ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7556,'Расстелить на разделочной доске пищевую пленку. Отварить овощи. Свеклу натереть, отжать излишки сока, массу выложить на поверхности пленки, соль и перец – по вкусу. Должны остаться свободные края со всех сторон по три – четыре сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7556,'На свеклу выложить слой тертого картофеля, он должен быть на сантиметр уже, чем слой свеклы. На картофель нанести сеточку из майонеза с помощью кондитерского мешка. Затем – слой тертой моркови, он должен быть еще меньше, смазать майонезом. В центре выложить маринованную селедку с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7556,'Края пленки аккуратно поднять с краев к середине, завернуть, рулет обжать. Поставить салат-рулет в холод на ночь или на пять – шесть часов для пропитывания. При подаче пленку удалить, края массы обрезать с обеих сторон. Верх сельди под шубой рулетом украсить майонезом, подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Для приготовления блинчиков использовать проверенный домашний рецепт, они должны быть тонкими. Длиннозерный рис отварить в слегка подсоленной воде, жидкость слить. Нарезать кубиками репчатый лук, обжарить на растительном масле до золотистого цвета, разделить на три равные части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Грибы очистить, перебрать, нарезать, жарить на масле до выпаривания жидкости. Добавить одну часть лука, перец молотый и соль – по вкусу. Массу охладить. Куриную печень вымыть, нарезать небольшими кусочками, обжарить в течение нескольких минут, добавить вторую часть лука, перец и соль. Также охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Свиной фарш обжарить, помешивая и разбивая комки, добавить оставшийся лук, соль и перец, мелко нарезанную зелень. Отдельно нарезать зеленый лук, немного обжарить и соединить с нарезанной зеленью, измельченными крутыми яйцами, соль и перец добавить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Для приготовления теста сухие дрожжи перемешать с пшеничной мукой и сахарным песком, влить треть стакана подогретого молока. Ингредиенты перемешать, масса должна стать однородной. Поставить в тепло для увеличения объема.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7567,'Положить смесь орехов и сухофруктов на мясо равномерным слоем, завернуть в рулет и перевязать нитками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Сливочное и подсолнечное масло нагреть. В отдельной мисочке взбить яйца с солью. Влить опару, подогретое молоко, перемешивать. Порциями всыпать заранее просеянную муку, тесто должно получиться гладким. В конце замешивания постепенно добавить жир. Колобок присыпать мукой, накрыть пленкой, тканью и поставить в тепло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Вилкой взбить сырые куриные яйца, влить массу во все начинки равномерно, для связки ингредиентов. Длинную прямоугольную форму застелить пищевой пленкой, положить блины так, чтобы они легли внахлест, а по бокам свисали. Выложить начинки слоями, порядок – любой, разделять блинными полосками. Обжать, уплотнить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Накрыть начинку блинами. Подошедшее тесто разделить на две части. Каждую раскатать в лепешку средней толщины: от полсантиметра до сантиметра. На один пласт выложить начинку, завернутую в блинчики, накрыть второй половиной теста, края прижать, лишнее тесто убрать. Украсить кулебяку так, как подскажет кулинарная фантазия, можно вылепить из остатков теста цветы или колоски.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7557,'Пирог накрыть пленкой, оставить на полчаса. Смазать смесью взбитого желтка с маслом, печь до получения корочки, температура – 190 градусов. Если верх начнет подгорать, то его нужно накрыть фольгой. Готовую домашнюю кулебяку положить на деревянную доску, время выстаивания – 15 минут. Подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7558,'Выложить на ровную поверхность квадратное песочное печенье. Намазать сырковой массой, слои несколько раз повторить. Сверху – тонко нарезанные ломтики банана и киви. Поставить торт на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7559,'У куриных сердечек отрезать открытую часть, в ней находится немало жира. Промыть субпродукты от крови и замочить в очень холодной воде на полчаса. После еще раз промыть и обсушить. Измельчить очищенный чеснок, крупно нарезать перец чили, удалить семена. Натереть корень имбиря.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7559,'Перемешать лимонный и апельсиновый сок, добавить соевый соус, чили, чеснок, черный перец, имбирь. В готовый маринад положить сердечки, хорошо перемешать, накрыть крышкой и поставить в холодильник на два или три часа. За это время продукты несколько раз перемешать. Можно воспользоваться вакуумным контейнером, в этом случае процесс маринования займет не больше 30–40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7559,'Сердечки нанизать на деревянные шпажки, жарить на сковороде на небольшом количестве растительного масла. Желательно наличие антипригарного покрытия. Вынуть шпажки, в сковороду влить белое сухое вино, воду или апельсиновый сок. Вернуть куриные сердечки на шпажках в сковороду, прогревать две минуты, переворачивать. Подать к столу горячими, посыпать семечками кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7560,'Сыр натереть на крупной терке, мелко нарезать несколько перышек зеленого лука. В миску большого размера выложить готовое картофельное пюре, куриное яйцо, пшеничную муку, сыр и зеленый лук. Перец молотый – по вкусу. Хорошо перемешать. Сформовать руками двенадцать небольших шариков, расплющить их в лепешки толщиной в один – полтора сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7560,'Обвалять изделия в муке, выложить в заранее разогретое масло. Жарить с обеих сторон до золотистой корочки по три – четыре минуты с каждой стороны. Добавлять на сковороду масло по мере необходимости. Выложить готовые оладьи из картофельного пюре на бумагу для впитывания лишнего жира, посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7561,'Яблоки очистить, вырезать сердцевину, мякоть нарезать кусочками небольшого размера. Выложить в фольгу, завернуть и поместить в форму для запекания. Печь при температуре 180 градусов в течение получаса. Остудить и превратить в пюре. Можно дополнительно протереть массу через сито, чтобы не было комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7561,'Замочить в воде агар, оставить на полчаса. Разрезать палочку ванили, семена вынуть. Добавить в пюре сахарный песок, семена ванили и белок, взбить. Агар прогреть, довести до кипения, тоже добавить сахар. Еще раз довести до кипения. Варить в течение пяти минут, постоянно помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7561,'Влить горячий сироп в яблочное пюре с белком. Взбить до получения плотной массы. Отсадить ванильно-яблочный зефир на бумагу с помощью кондитерского мешка. Можно использовать силиконовый коврик или обычную разделочную доску. Оставить при комнатной температуре на три – четыре часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Отварить сладкую свеклу темно-бордового цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7562,'Перемешать муку с содой, солью и разрыхлителем, смесь просеять. Добавить овсяные хлопья быстрого приготовления. Размягчить сливочное масло, растереть его с сахарным песком, ванилином. Масляную смесь взбить при помощи миксера до получения пышной белой массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7562,'Вбить яйца по одному, продолжать взбивать еще две минуты. Вмешать мучную смесь порциями. Замесить тесто ложкой, а потом руками. Масса должна стать однородной. Добавить шоколадные капли. Масса должна легко лепиться, если тесто получилось жидковатым – в него можно добавить муку или хлопья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7562,'Отделить кусочки ложкой, скатать, сформовать шарики. Разложить их на противне, между изделиями должно быть расстояние. Шарики расплющить. Печь овсяное печенье с шоколадом при температуре 180 градусов в течение 18 минут, время зависит от возможностей духовки. Немного остудить, переложить на решетку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7563,'Отварить в мундире картофель, морковь, яйца, все почистить, овощи и отварную телятину нарезать небольшими кубиками, подсолить, вилкой размять желтки яиц, белки натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7563,'Промыть в дуршлаге опята и мелко порезать, часть оставить для оформления, нарезать мелкими кубиками лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7563,'Приготовить из смеси майонеза с горчицей и перцем заправку для салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7563,'Выкладывать салат на круглое блюдо слоями в следующем порядке: мясо-майонез, лук-майонез, картофель-майонез, морковь, желтки-майонез, белки, верх оформить зеленью и целыми шляпками опят.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7563,'Салат из телятины с опятами и картофелем поставить в холодильник, через час можно подавать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7564,'Куриное филе тщательно вымыть и высушить. Нарезать небольшими полосками в длину. Разогреть сковороду с растительным маслом. Обжарить куриные полоски на масле до белого цвета, посолить и поперчить по вкусу. Теперь необходимо очистить картофель и натереть на крупной терке. Через пару минут, когда выступит картофельный сок, слить, отжав тертый картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7564,'Посолить и добавить яйца, муку. Эту массу выложить на разогретую сковороду, распределив по всей поверхности, чтобы получился блин. Не стоит делать его сильно толстым, иначе картофель не прожарится внутри. Когда одна сторона приобретет золотистый цвет, картофельный блин перевернуть при помощи лопатки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7564,'Затем на одну половину картофеля выложить полуготовую курицу и присыпать тертым сыром с зеленью. Через пару минут накрыть курицу второй половинкой блина, как одеялом. Когда сыр расплавится, а картофель подрумянится со всех сторон, куриное филе в ажуре готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Вынуть заранее из холодильника масло и дать ему размякнуть, обжарить орехи, очистить от шелухи, раскатать скалкой в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Взбить яйца с маслом, влить молоко, постепенно всыпать муку, добавить смесь соды с уксусом, сахар (не обязательно), замесить упругое тесто, убрать его на полчаса в морозильную камеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Прогреть духовку до 180 градусов, выстелить противень пергаментом и натереть на него тесто, поставить на 20 минут зарумяниться в духовку, дать чуть остыть и поломать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Взбить мягкое масло миксером 2 минуты, добавить вареную сгущенку с ванильным сахаром и взбить смесь до однородной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Смешать полученный крем с орехами и крошкой, поставить смесь на полчаса в холодильник, затем выложить на блюдо в виде тела змеи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7565,'Торт «Змея» с орехами и шоколадом оформить тертым белым шоколадом, растопленной смесью темного шоколада и сгущенки нарисовать узоры на спине змейки, из круглых драже сделать глаза, из кусочков чернослива – реснички, посыпать мятой, украсить кусочками мармелада. На кончик хвоста надеть колечко из сушки, перед подачей к столу торт надо охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7566,'Натереть крупно морковь, потушить с изюмом на масле до мягкости, добавить соль и сахар, отварить свеклу, почистить, измельчить на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7566,'Протереть на мелкой терке сыр, чеснок, перемешать и разделить на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7566,'Поджарить и порубить ножом грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7566,'Выложить салат на блюдо в следующем порядке: морковно-изюмная смесь, майонез, чеснок с сыром, свекла, майонез, вторая половина чесночного сыра, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Отварить яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7567,'Обернуть рулет фольгой, переложить на противень и поставить запекать в духовку, примерно через 1 час фольгу снять и запекать еще полчаса (по 15 минут с каждой стороны), чтобы мясо зарумянилось.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7567,'Перед подачей остывший рулет из грудинки с сухофруктами и орехами нарезать на куски и переложить на широкое блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7568,'Почистить и нарезать небольшими кубиками шампиньоны и лук, обжарить и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7568,'Нарезать вареные яйца, крабовые палочки и свежие огурцы такими же кубиками, соединить с грибами, измельченной петрушкой, посолить, размешать, салат заправить майонезом и переложить в салатник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7568,'Праздничный салат из грибов, яиц и крабовых палочек перед подачей охладить, украсить розой из помидора и веточками зелени петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7569,'Очистить грибы, лук, нарезать кубиками и обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7569,'Натереть крупно сыр, мелко порезать зелень петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7569,'Смешать фарш с грибами, сырым яйцом, сыром, сметаной, заправить солью и перцем, хорошо перемешать, включить разогреваться духовку до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7569,'Смочить руки и сформовать продолговатые колбаски, обмакнуть в сметану, обвалять в сухарях, переложить на предварительно смазанный маслом противень, запекать котлеты мясные «Камыши» с грибами и сыром полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7569,'Готовые котлеты по одной насадить на длинные деревянные шпажки, переложить на плоское блюдо декорировать листьями из перьев зеленого лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7570,'Натереть специями и солью свиные отбивные, дать постоять, включить разогреваться до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7570,'Переложить куски мяса в форму для запекания, сверху посыпать луком, нашинкованным полукольцами, положить ягоды кисло-сладкого винограда, залить сливками и отправить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7570,'Запеченная со сливками свинина под виноградом будет готова через 35-40 минут, через 30-35 минут после начала запекания посыпать тертым сыром и еще 5 минут запекать, готовую свинину перед подачей посыпать измельченным базиликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7571,'Подготовить баранину на косточке, отбить, натереть молотым перцем и солью, переложить в подходящую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7571,'Нашинковать полукольцами лук, засыпать баранину, добавить измельченный чеснок, базилик, залить гранатовым соком и оставить на час промариноваться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7571,'Достать мясо из маринада, салфеткой из бумаги обсушить куски, переложить на хорошо разогретую массивную чугунную сковороду, обжарить, довести мясо до готовности в духовке, подавать баранину на кости маринованную в гранатовом соке горячей с измельченным базиликом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7572,'Почистить кабачки, удалить семена и измельчить на крупной терке, отжать тщательно сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7572,'Натереть на крупной терке сыр, смешать его с измельченным чесноком и зерненым творогом (жидкость слить), посолить, перемешать, вбить в творожно-сырную смесь яйца и аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7572,'Переложить кабачки на противень, предварительно смазанный растительным маслом, залить равномерно яичной смесью, слегка перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7572,'Выпекать блюдо при 250 градусах, ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7573,'Поломать на кусочки шоколад, переложить в миску, дать сливкам закипеть и вылить в шоколад, дать постоять, тщательно перемешать, охладить и убрать в холодильник, чтобы ганаш стал густым (периодически проверять степень застывания).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7573,'Вынуть миску их холодильника, брать ганаш чайной ложкой, скатывать из него  небольшие шарики размером чуть меньше грецкого ореха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7573,'Готовые простые шоколадные трюфели по-домашнему обвалять в смеси какао с измельченными грецкими орехами или в вафельной крошке с колотыми леденцами, охладить конфеты минимум полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7573,'Эти трюфели пару недель можно хранить в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7574,'Разморозить готовое тесто, раскатать в тонкий слой, разрезать сосиски на 4 части, взбить яйца со сметаной и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7574,'Переложить тесто в форму, разложить равномерно по поверхности сосиски, залить яичной смесью. Запечь быстрый пирог из слоеного теста с сосисками при 180 градусах, чтобы он стал золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'На дно формы уложить пергамент, промазать бока маслом, заполнить тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7575,'Сварить очищенный картофель, слить воду, добавить сливки или молоко, масло, сделать достаточно густое пюре, заправить солью, перцем, мускатным орехом, пюре чуть остудить, вбить яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7575,'Слегка обжарить на масле морковь, чеснок, лук, добавить мясной фарш, тушить на среднем огне 5-6 минут, уменьшить огонь, готовить 5 минут, всыпать зеленый горошек, продолжать тушить еще 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7575,'Форму смазать сливочным маслом, выложить третью часть пюре, потом – фарш, накрыть оставшейся частью пюре, смазать сметаной, посыпать натертым сыром, выпекать при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7575,'Картофельная запеканка с мясом, сыром и зеленым горошком будет готова через полчаса, подать ее горячей с кетчупом или сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7576,'Отбить слегка куриное филе до выравнивания толщины куска, обжарить в небольшом количестве масла со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7576,'Смешать вино, соевый соус, мед, вылить полученный соус в мясо, поперчить, посолить, сделать сильный огонь, жарить, периодически поливая соусом и переворачивая, около 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7576,'Готовое блюдо для удобства порезать на небольшие пластинки, куриное филе с медом и соевым соусом по-японски подается с рисом и брокколи, гарнир полить соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7577,'Отварить брокколи (не разваривать), окатить соцветия холодной водой, дать постоять, нарезать дольками сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7577,'Подготовить куриное филе: отбить, посолить, поперчить, на пласт мяса положить несколько кусочков сыра и брокколи, свернуть в рулет, скрепить края зубочистками, обжарить со всех сторон на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7577,'Переложить рулеты в сотейник, добавить к маслу после обжарки мяса бульон, молоко, заправить паприкой, чесноком, молотым перцем, посолить, варить, помешивая, 5-7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7577,'Залить мясо соусом и отправить в духовку, рулетики из куриного филе с брокколи и сыром будут готовы через 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7578,'Взбить яйца с молоком (кефиром), добавить разрыхлитель, постепенно помешивая всыпать муку до консистенции теста на оладьи, заварить стаканом крутого кипятка, тщательно перемешать, влить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7578,'Выпекать с обеих сторон на сильно разогретой сковороде как обычные блины, блины на молоке или кефире заварные подавать к столу горячими со сметаной, маслом, вареньем или сгущенкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7579,'Подготовить и замочить в воде на 30-40 минут изюм, протереть сквозь сито творог, вбить яйца, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7579,'Обсушить и слегка обвалять в муке изюм, смешать с творогом, добавить к творогу муку, сахарную пудру, перемешать до однородности и поставить на 40-50 минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7579,'Сформовать из творожной массы сырники, обжарить с двух сторон в разогретом масле до аппетитной корочки, переложить на бумажные салфетки для впитывания масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7579,'Положить в разогретую сковороду сметану и мед в равных пропорциях, хорошо перемешать и дать прогреться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7579,'При подаче сырники диетические из творога с изюмом полить подливкой из меда и сметаны, присыпать смесью сахарной пудры с корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7580,'Нарезать куриную грудку тонкими ломтиками, обжарить на сливочном масле до аппетитной корочки, нарезать помидоры кружочками, взбить молоко с яйцами, заправить молотым мускатным орехом и перцем, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7580,'Переложить мясо в форму для запекания, уложить сверху помидоры, залить яичной смесью, равномерно присыпать натертым сыром, отправить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7580,'Омлет с сыром, курицей и помидорами будет готов примерно через 15 минут, готовый омлет перед подачей к столу посыпать мелко измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7581,'Взбить сахар с яйцами, влить 1/2 банки сгущенки (взбивать не прекращать), сметану, всыпать какао-порошок (оставить 1 ложку для крема), влить в тесто гашеную уксусом соду, размешать, всыпать постепенно муку, тесто не должно быть густым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7581,'Выстелить форму для торта пергаментом, смазать маслом, присыпать мукой, вылить тесто, отправить запекаться в духовку при 180 градусах, корж будет готов примерно через 50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7581,'Нагреть, постоянно размешивая в течение получаса на медленном огне вино с сахаром, взбить мягкое масло с ложкой какао и оставшейся сгущенкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7581,'Остудить корж, разрезать на 3 части, пропитать каждую вином и смазать кремом, верх торта украсить орехами и ягодами, для улучшения вкуса торт «Сказка» с вином и сгущенкой необходимо на несколько часов убрать в холодильник для пропитки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7582,'Взбить сахар с маслом, вбить яйца по одному, добавить протертый сквозь сито творог, просеянную муку, цедру лимона, влить сок и гашеную соком соду, все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7582,'Подготовить форму для выпечки, смазать маслом, присыпать мукой, переложить в нее тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7582,'Выпекать творожный кекс с лимонным соком около 50 минут при 170 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7583,'Залить крабовые палочки кипятком на пару минут, слить воду и аккуратно их развернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7583,'Нашинковать мелко лук, нарезать грибы, измельчить на терке яйца и сыр, добавить сметану, слегка посолить, хорошо перемешать, выложить начинку на развернутую палочку, разровнять и свернуть рулетиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7583,'Убрать крабовые палочки, фаршированные грибами и яйцом, на несколько часов в холодильник, достать, нарезать, выложить на блюдо, украсить веточками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7584,'Промыть тщательно сухофрукты, залить горячей водой, когда размякнут взбить в блендере с молоком (яблочным соком), хлопьями и медом до гомогенного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7584,'Подавать овсяный смузи с изюмом и курагой в охлажденном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7585,'Смешать фарш из филейной части и лопатки, всыпать измельченный лук, добавить яйцо, соус барбекю, горчицу, заправить молотым перцем чили, чесночным порошком, молотым черным перцем, мускатным орехом, солью, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7585,'Накрошить крекеры и высыпать в фарш, аккуратно перемешать до гомогенного состояния. Сформовать из массы рулет, обернуть весь пластинками бекона, промазать сверху соусом барбекю, отправить запекаться в нагретую духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7585,'Фаршированный рулет в соусе барбекю с беконом будет готов примерно через час. Готовый рулет перед подачей к столу остудить и нарезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7586,'Сделать надрез в курином филе в виде кармашка, заполнить его нарезанным сыром со специями, сколоть края мяса зубочистками, чтобы расплавленный сыр не вытек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7586,'Натереть мясо черным молотым перцем, обернуть полосками бекона по кругу со всех сторон, переложить в форму, запечь при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7586,'Запеченное в беконе куриное филе с сыром будет готово через час, подавать блюдо лучше с овощами, удалив зубочистки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7587,'Взбить миксером яйца комнатной температуры с сахаром в пышную пену. Мед поставить на паровую баню и высыпать в него соду. Помешивая мед ложкой, необходимо достичь светлой вязкой консистенции. Вымешивая яйца, следует их соединить с медом, аккуратно и медленно вводя горячий мед по чайной ложке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7587,'Затем в эту пышную массу добавить постепенно муку, мешая лопаткой или венчиком, чтобы не нарушить структуру воздушного теста. Форму для бисквита смазать маслом и вылить тесто. Чтобы в бисквит не поднимался горкой во время выпечки, необходимо ложкой провернуть по часовой стрелке тесто, сформировав неглубокую воронку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7587,'Выпекать 40 минут при температуре 180 градусов. Золотистый бисквит остудить и разрезать вдоль на 3 части. Затем смазать каждую часть сиропом, сверху взбитым кремом. Медовик со сливочным кремом получится сочнее, если пропитается в течение нескольких часов, но консистенция бисквита такова, что торт сразу получается нежным и сочным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7588,'Лук очистить и порезать кубиком. Обжарить лук на растительном масле до нежно-золотистого цвета. Сильно не стоит зажаривать, чтобы у пирога не было сильного лукового привкуса. Вареные яйца очистить и порезать мелким кубиком и соединить с луком и тертым сырком. В начинку добавить специи по вкусу и соль. Также высыпать в начинку рубленую свежую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7588,'Для приготовления теста необходимо растереть маргарин с мукой, затем добавить сметану и соду. Вымесить мягкое тесто и разделить его на 2 части. Завернуть каждую в пищевой пакет и положить на холод на 30 минут. Раскатать одну часть теста в пласт и вложить в форму для выпекания, сформировать бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7613,'Довести до кипения подсоленную воду, бросить по отдельности вареники, дать им всплыть, вынуть шумовкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7588,'Высыпать всю начинку и накрыть второй частью теста, раскатанной  в пласт. Защипнуть края, верх смазать желтком. Выпекать пирог в духовке 50 минут при температуре 180 градусов. Золотистый ароматный пирог с сыром и луком порезать на порционные кусочки, подавать теплым со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7589,'Обжарить лук до золотистого цвета на растительном масле. Затем высыпать лук в кипящую воду и варить 30 минут. Через полчаса всыпать в кипящую воду порезанную кубиком копченую колбасу, лавровый лист, перец и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7589,'Варить еще 30 минут на медленном огне. После влить закваску и посолить суп по вкусу. Консистенция польского журека немного загустеет. В конце влить сметану и прокипятить 5 минут. Отставить суп с огня и накрыть крышкой, чтобы напитался вкусом и запахом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7590,'Свежий огурец и копченую колбасу порезать, с кукурузы слить жидкость и высыпать в салатницу. Яйца взбить и пожарить омлет на растительном масле. Затем порезать омлет на ровные полоски, размером, как остальные продукты. Соединить все ингредиенты и добавить майонез. По вкусу посолить и поперчить. Украсить простой салатик с омлетом свежей зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7591,'Орехи необходимо перемолоть в муку. Получится жирная ореховая масса, которая хорошо ведет себя в тесте. Соединить с мукой и разрыхлителем, посолить. Белки и желтки разделить. Желтки взбить с мягким сливочным маслом и сахаром. Продолжая взбивать масло, всыпать по не многу муку с орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7591,'Охлажденные белки взбить в пену. Чтобы пена быстро взбилась, необходимо добавить щепотку соли и сахарную пудру. Пышную белковую массу ввести аккуратно в тесто, перемешивая лопаткой, чтобы не повредить воздушность. Форму застелить пергаментом и смазать растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7591,'Вылить тесто, разровнять лопаткой по всей поверхности и поставить выпекаться в духовку на 40 минут при температуре 180 градусов. Готовый бисквит остудить. Теперь необходимо приготовить шоколадный ганаш. Сначала из сахара приготовить карамель. Сахар высыпать в кастрюльку или сковороду с толстым дном и нагревать на медленном огне, пока сахар не превратиться в жидкую карамель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7591,'Тем временем на огне закипают сливки со щепоткой соли. Как только карамель будет готова, необходимо влить в нее горячие сливки и хорошо перемешать. Карамельные сливки необходимо соединить с поломанной плиткой шоколада и поставить на водяную баню, чтобы масса стала однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7591,'В ганаш добавить сливочное масло, размешать на водяной бане. Однородную массу взбить блендером в густой ганаш. Бисквит разрезать на две половины вдоль. Первую часть обильно смазать апельсиновым джемом, накрыть второй половинкой и залить шоколадной глазурью. Украсить венский торт с орехами и апельсиновым джемом орехами или дольками апельсина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7592,'Картофель очистить и натереть на крупной терке. Взбить яйца с солью и перцем, влить в картофель. Раскалить сковороду и налить пару ложек растительного масла. Вылить на сковороду картофельное тесто, как для блина. Обжарить с двух сторон до золотистой корочки. Свернуть блинчик рулетом и подавать картошечку «Скоростная» со сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7593,'Сначала необходимо включить духовку на 200 градусов. Из апельсина необходимо отжать свежий сок и натереть цедру. Имбирь натереть на мелкую терку. Оливковое масло налить в небольшую миску, добавить соевый соус, апельсиновый сок и цедру, имбирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7593,'Капусту вымыть и выложить на противень. Сверху полить соусом и поставить в духовку для запекания на полчаса. Капуста брюссельская в апельсиновом соусе очень вкусная теплой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7594,'Из окорочков удалить косточку, оставив на мясе шкуру. Отбить мясо из окорочков, накрыв его пленкой. Затем посолить и поперчить по вкусу. Зелень и чеснок измельчить и сложить в отдельную миску. Филе вымыть, посолить и поперчить. На отбитое мясо положить филе и посыпать обильно чесноком с зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7594,'Плотно свернуть мясо рулетом и обмотать фольгой, а чтобы не раскрутилось, обернуть ниткой. Куриные рулеты готовить в пароварке в течение 1 часа. Готовые диетические рулеты из курицы охладить, затем удалить фольгу и нитки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7613,'Подавать к столу ленивые вареники из творога к завтраку горячими со сметаной и растопленным маслом',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7595,'Соединить сливочное масло или маргарин с мукой и перетереть в крошку. Добавить соль и сахар, затем яйца. Вымесить крутое тесто, обернуть пищевой пленкой и поставить в холодильник на 30 минут. Тыкву очистить от кожуры и отварить до мягкой консистенции. Затем измельчить блендером в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7595,'Добавить сливки, яйца, сахар, соль и пряности. Хорошо взбить блендером в однородную массу. Тесто разложить по форме, сформировав бортики. Вылить начинку и поставить в духовку запекаться. Выпекать пирог с тыквой 30 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7596,'Взбить яйца, майонез и сметану. Затем добавить муку и замесить наливное тесто. Начинка для пиццы может быть разной, все, что есть в холодильнике: колбаса, вареное мясо, жареные грибы, помидоры, сладкий перец, жареный лук. Но обязательным ингредиентом является сыр, который необходимо натереть на крупную терку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7596,'Вылить тесто на раскаленную сковороду и высыпать порезанную начинку. Засыпать все тертым сыром и накрыть сковороду крышкой. Жарить пиццу 20 минут, пока сыр не расплавится. Горячую ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7597,'Соломку необходимо разложить ровно в ряд на листе для выпечки, который предварительно смазать сливочным маслом. Поставить миску на водяную баню. В ней соединить пол пачки сливочного масла и конфеты ириска или коровка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7597,'Когда масса станет однородной, вылить все на соломку, равномерно распределив. Затем соломку в ирисе свернуть рулетом при помощи бумаги. Ровный рулет положить в холодильник до полного остывания. Когда сладкая колбаска остынет, нарезать тонкими кружочками и подавать к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7598,'Рыбу почистить и хорошо помыть. Нарезать на порционные куски, посолить и поперчить по вкусу. Положить в пароварку и готовить 15 минут. В это время следует приготовить ароматный соус из клюквы и лимона. Клюкву помыть и отварить в воде с медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7598,'Затем в кастрюлю добавить сок и цедру половины лимона и лайма. Эту массу варить, помешивая и разминая клюкву. Когда ягоды станут мягкими, их следует протереть через сито. Готовую форель выложить на тарелку и полить соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7599,'Куриную печень необходимо очистить от плевы, хорошо помыть и обжарить на растительном масле до готовности. Во время приготовления посолить и поперчить печень. Хлеб нарезать маленькими кубиками и обжарить до хрустящей корочки или засушить в духовке. Лук очистить и порезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7599,'Сковороду раскалить и обжарить лук на растительном масле до мягкости. Затем в сковороду с луком влить уксус и жарить еще минуту на очень медленном огне. Добавить сахар и соль. Лук остудить. Для заправки в салат необходимо смешать растительное масло, уксус, давленый чеснок, специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7599,'Помидоры черри разрезать на равные половинки. Для выкладывания салата необходимо использовать широкие тарелки, чтобы хорошо легли листья салата. Чистые сухие листья салата положить в центре тарелки, затем выложить половинки помидор и жареный лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7599,'Сверху тонкие ломтики бекона, которые полить заправкой. Посыпать гренками. Последний слой – теплая куриная печень, полить заправкой. По вкусу посыпать теплый салат с куриной печенью и гренками молотым перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7600,'Смешать холодную воду с молоком, всыпать хлопья, сварить овсяную кашу (жидкую).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7600,'Остудить кашу, растереть вилкой, вбить яйцо, добавит сахар, соль, все смешать, выпекать как обычные блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7600,'Этот рецепт низкокалорийных овсяных блинчиков хорошо подойдет для диетического завтрака.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7601,'Аккуратно разрезать грудку вдоль волокон на небольшие полоски, которые отбить кухонным молоточком. Чтобы мясо не порвалось, закройте его кульком и несильно отбейте. Посолить и поперчить каждый кусок. Выложить отбитые куриные кусочки на пищевую пленку, сформировав широкий пласт, немного накладывая края, друг на друга.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7601,'Для соуса песто можно использовать свои любимые травы: петрушку, укроп, мяту. Но основным ингредиентом является базилик. Чеснок измельчить до кашицы. Смешать травы, чеснок, оливковое масло, тертый пармезан блендером на малых оборотах. Соус песто нанести на куриные кусочки, затем посыпать порезанной курагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7760,'Все подготовленные ингредиенты переложить в кипящий бульон, добавить молотый перец, лавровый лист, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7601,'Свернуть рулет из курицы с курагой и песто, при помощи пленки. Завернуть рулеты в фольгу и поставить в духовку на 20 минут при температуре 180 градусов. Рулет можно порезать горячим и подавать с гарниром, но можно предлагать, как холодную закуску со свежими овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7602,'Свеклу необходимо отварить и остудить. Затем натереть на средней терке. Шоколад растопить на водяной бане, не допуская закипания. В растопленный шоколад влить горячий черный кофе и сливочное масло, порезанное кубиками. Размешать шоколадную массу и остудить. Муку просеять и соединить с какао и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7602,'Отделить белки от желтков. Желтки растереть в пену, белки взбить в пену. В белки подсыпать постепенно сахар, продолжая взбивать. Затем в шоколадную массу добавить желтки и натертую свеклу. Перемешать лопаткой. Очень аккуратно ввести белки, перемешать. Добавить муку с какао. Вымесить тесто по консистенции густой сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7602,'Форму для выпечки застелить пергаментной бумагой и вылить тесто. Поставить в разогретую духовку на 30 минут при температуре 180 градусов. Готовый корж остудить и разрезать на две части. Пока выпекается корж необходимо приготовить крем и глазурь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7602,'Для крема взбить блендером сливки, сливочное масло, какао и сахарную пудру. Когда масса станет однородной и пышной, крем готов. Глазурь для торта готовить на водяной бане. Соединить все ингредиенты, томить, постоянно помешивая. Шоколадный торт из свеклы смазать кремом и украсить глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7603,'Обжарить мелко нарезанные грибы, добавив для вкуса и аромата чеснок. Затем в этой сковороде обжарить лук, порезанный кубиком и тертую морковь. Сварить пшено до готовности. В фарш добавить обжаренные овощи, сырое яйцо, посолить и поперчить, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7603,'Из мясной массы сформировать шарики размером с теннисный мяч, выложить на противень. Затем в каждом шарике сделать небольшое углубление и вложить в него жареные грибы. Сыр натереть на средней терке и посыпать каждое «гнездышко». В противень добавить немного воды, накрыть крышкой и поставить в духовку на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7603,'Гнездышки из мясного фарша тушатся под крышкой, затем немного зажариваются с одной стороны. Готовое блюдо выложить на широкую тарелку и украсить свежей зеленью, в середине тарелки выложить вареное пшено со сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7604,'Подготовить яблоки: помыть, удалить в целых плодах сердцевину, нарезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7604,'Смешать с просеянной мукой соль, разрыхлитель, соду, вбить яйцо, добавить сметану, вымесить жидкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7604,'Обмакнуть яблочное колечко в тесто и сразу обжарить в хорошо нагретом масле с 2 сторон, подавать яблочные круги в тесте с медом, вареньем, кленовым сиропом и лучше в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7605,'Протереть творог сквозь сито, смешать до однородной массы в блендере с яйцами, сахаром и небольшим количеством соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7605,'Всыпать для более мягкой консистенции манку, перемешать, добавить муку и еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7605,'Присыпать стол мукой, раскатать из творожного теста жгут диаметром примерно в 5 см, нарезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7605,'Расположить часть вареников на разделочной доске присыпанной мукой в один слой и заморозить, пересыпав в пакет, для будущего использования.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7605,'Довести до кипения в большой кастрюле воду (можно добавить сахар), всыпать вареники, варить небольшими порциями, когда ленивые вареники с манкой и творогом всплывут, разложить их по тарелкам, полить сметаной, вареньем, сгущенкой или медом, украсить свежими ягодами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7606,'Замочить любую фасоль в воде минимум на 4 часа, воду отцедить, переложить в кастрюлю, залить кипятком, отварить до готовности не закрывая крышкой, фасоль должна стать мягкой, но не развариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7606,'Нарезать лук на мелкие кубики и поджарить на растительном масле, орехи измельчить в блендере, смешать фасоль с луком, добавить растертый чеснок, орехи, заправить перцем, солью и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7606,'Подавать салат Лобио из фасоли с орехами охлажденным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7607,'Смешать муку с крахмалом, вбить яйцо, влить молоко, всыпать сахар, какао, посолить, перемешать, растопить шоколад и добавить к блинному тесту, поджарить блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7607,'Сварить из молока, крахмала и ванильного сахара крем, для этого дать закипеть молоку (400 мл), развести в холодном молоке (100 мл) крахмал с сахаром и постоянно помешивая влить тонкой струйкой в горячее молоко, дать крему загустеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7607,'Смазать каждый блин кремом, сложить стопкой и убрать в холодильник, через 1 час блинный торт с какао и шоколадом можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7608,'Приготовить из мякоти говядины фарш, заправить солью, перцем, добавить обжаренный лук, перемешать и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7608,'Очистить картофель, сварить, пропустить через мясорубку, вбить яйцо, добавить сливочное масло, заправить перцем и солью, масса должна получиться не очень густой, для получения такой консистенции к картофелю можно добавить чуть сливок, сметаны, бульона и тщательно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7608,'Скатать из массы небольшие шарики, сплюснуть их, выложить по центру фарш сформовать пирожки, обвалять в муке и обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7608,'Подать картофельники с мясом горячими со сметаной или грибным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7609,'Дать закипеть воде с маслом и солью, постепенно всыпать смесь муки с крахмалом, постоянно помешивать, варить до тех пор, пока тесто не перестанет прилипать к стенкам кастрюли (около 2 минут), охладить тесто, по одному втереть пару яиц, добавить натертый сыр и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7609,'Смазать противень маслом, выложить столовой ложкой небольшие порции теста, выпекать около 20 минут (духовку во время выпечки не открывать) при 220 градусах, срезать верхушки булочек и охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7609,'Пропустить плавленый сыр и ветчину сквозь мелкую решетку мясорубки, положить половину майонеза, взбить миксером, добавить постепенно вторую половину майонеза, всыпать в смесь нарезанный мелкими кубиками маринованный огурец, приправить перцем, солью и хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7609,'Заполнить начинкой булочки и прикрыть срезанными верхушками, готовые булочки с муссом из сыра и ветчины переложить на блюдо, присыпать паприкой и украсить зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7610,'Подготовить капусту, разобрать на соцветия, сварить в соленой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7610,'Разогреть в глубокой сковороде масло, всыпать муку, обжарить, помешивая пару минут, сделать нагрев меньше, быстро размешивая влить постепенно молоко, добавить к соусу сметану, заправить мускатным орехом, перцем, солью, перемешать и убрать с плиты, включить на разогрев духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7610,'Переложить отваренные соцветия в форму, залить сверху соусом, присыпать (не жалея) тертым сыром и отправить в духовку, когда сыр расплавится и станет золотистого цвета, цветная капуста под сыром в соусе бешамель будет готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7611,'Протереть через сито и взбить с яйцами творог, добавить половину кислого молока (можно смесь кефира с молоком), добавить сахар, посолить, всыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7611,'Добавить к оставшемуся молоку соду и тщательно перемешать, соединить с творожной массой, добавить масло, смесь хорошо взбить, консистенция массы должна напоминать густую сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7611,'Подготовить любую начинку: варенье, тушеную капусту, обжаренные с луком грибы, отварную курицу, творог, жареную печень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7611,'Разогреть сковороду, налить порцию теста, сделать меньше огонь, накрыть крышкой, как только низ блинчика зажарится, положить как можно ближе к центру начинку, свернуть блинчик с помощью лопаточки пополам, закрыть сковороду крышкой на пару минут, перевернуть блинчик и накрыть опять крышкой на 1-2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7611,'Блинные пирожки с начинкой лучше подавать горячими со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7612,'Нарезать мякоть свинины (можно куриные грудки) ломтиками, посолить, поперчить, натереть картофель на крупной терке, нашинковать лук кольцами, измельчить сыр на крупной терке, раздавить чеснок, нарезать помидоры полукольцами и обмакнуть в майонез, порубить мелко зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7612,'Выложить слоями на смазанный маслом противень мясо, лук, картофель, помидоры и смазать майонезом, запекать 50 минут при температуре 220 градусов, а за 10 минут до окончания запекания равномерно по поверхности распределить чеснок, посыпать сыром и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7612,'Убрать в духовку и через 3-5 минут запеченное мясо с сыром и картошкой, будет готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Выпекать треть часа при 180 градусах до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7614,'Сформовать из полученной массы шарики, поместить внутрь каждого по целому ядру миндаля, обвалять в стружке из кокоса и выложить в один слой на красивое блюдо, украсить ягодами и взбитыми сливками, убрать на 2-3 часа в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7614,'Десерт рафаэлло с миндалем в домашних условиях станет прекрасным украшением любого праздничного стола.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7615,'Разрезать пополам охлажденные грейпфруты, вынуть ложкой мякоть, измельчить в блендере, добавить жидкий мед и смешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7615,'Грейпфрутовый фреш «Эликсир красоты» не только вкусный, но и полезный напиток, т.к. содержит пектин, способствует нормализации обмена веществ и выведению излишек холестерина из организма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7616,'Нагреть сливки (смесь сливок с молоком), но не доводить до кипения, взбить сахар с желтками и порошком растворимого кофе, влить, помешивая постепенно сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7616,'Вылить полученную смесь в кастрюльку, нагреть (закипеть не давать) помешивая до сгущения, снять с плиты, процедить, прикрыть пищевой плёнкой до касания поверхности смеси, дать остыть и поставить в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7616,'Взбить охлажденную смесь миксером и убрать в морозилку, через 2 часа достать и еще раз взбить, повторить процедуру несколько раз до получения однородной консистенции без кристалликов льда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7616,'Переложить мороженое после последнего взбивания в форму для кекса выстеленную пергаментной бумагой, поверхность разровнять, сварить кофе, обмакнуть печенье и слегка вдавливая разложить его по поверхности мороженого, убрать в морозилку, дать полностью застыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7616,'Накрыть форму блюдом и перевернуть десертное мороженое «Тирамису» печеньем вниз, украсить бока и поверхность тертым шоколадом или порошком какао, резать десерт горячим ножом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7617,'Растереть сахар с творогом в однородную массу, добавить большую часть кокосовой стружки и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7617,'Скатать шарики не больше грецкого ореха, в середину вставить орех фундука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7617,'Обвалять творожные Рафаэлло с фундуком в кокосовой стружке, переложить на блюдо и убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7618,'Вылить молоко в высокую кастрюльку, добавить сахарную пудру, масло, нагреть, помешивая, на слабом огне, чтобы пудра и масло растворились, увеличить огонь до среднего, довести смесь до кипения, варить, помешивая 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7618,'Вылить все в банку, дать остыть, убрать в холодильник на ночь, сгущенное молоко в домашних условиях может сначала показаться жидковатым, но после охлаждения оно загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7619,'Очистить и отварить морковь, картофель до готовности, добавить перец за 10 минут до окончания варки, он успеет передать свой аромат другим овощам, но не разварится в кашу и его можно будет без труда вынуть из кастрюльки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7619,'Нашинковать и обжарить на сливочном масле луковицу до приятного золотистого цвета, измельчить отварные овощи блендером до состояния пюре, оставить в кастрюльке пару стаканов бульона, добавить в кастрюлю плавленый сыр, размешать блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7619,'Разлить сырный крем-суп по тарелкам, украсить рубленой зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7620,'Нарезать немного замороженное филе курицы на мелкие кубики, также нарезать лук, вбить яйцо, добавить майонез и крахмал, заправить перцем, солью, всыпать измельченную зелень и хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7620,'Охладить фарш минут 30 в холодильнике (он может храниться несколько дней в холодильнике), выкладывать ложкой в разогретое растительное масло, жарить как оладьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7620,'Готовые ароматные и сочные котлеты из филе курицы с майонезом выложить на полотенце из бумаги: пусть излишки жира впитаются, переложить котлеты на блюдо, украсить веточками петрушки и дольками помидоров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7621,'Нашинковать лук, обжарить его до легкого «загара» на растительном масле, очистить от кожуры помидоры и нарезать на небольшие кубики, высыпать к луку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7621,'Нарезать болгарский перец мелкими кубиками, добавить к помидорно-луковой смеси, обжарить под крышкой до мягкости, накрошить в сковороду брынзу, залить взбитыми яйцами, слегка посолить (не обязательно) и поперчить, накрыть крышкой, зажарить до готовности яиц.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7621,'Этот вкусный завтрак можно приготовить и в духовке. Когда перец станет мягким выложить смесь в огнеупорную форму, присыпать измельченной брынзой, залить взбитыми яйцами, поставить в духовку на 5-7 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7622,'Отварить мак в воде в течение 15 минут, затем откинуть на сито, чтобы стекла вода и перемолоть с сахаром. Обжаренные орехи добавить к маку или посыпать сверху при формировании рулетов. Для  теста необходимо в теплом молоке растворить дрожжи, добавить 1-2 ложки сахара и дать постоять 10-15 минут, чтобы образовалась пена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7622,'Яйца взбить миксером с сахаром и солью, выложить в молоко, добавить растопленное масло или маргарин. Всыпать просеянную муку и вымесить мягкое тесто. Сложить тесто в кастрюлю и поставить в теплое место, чтобы оно подошло. Для того чтобы отлично и быстро подходило тесто, можно поставить кастрюлю с тестом в большую миску с горячей водой. При остывании воды, подливать горячую. Тесто должно подойти 2 раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7622,'Все тесто поделить на несколько равных частей, которые раскатать в пласт толщиной 2 см. Выложить маковую начинку, посыпать орехами и свернуть рулет. Противень застелить бумагой для выпечки, выложить рулеты на расстоянии друг от друга. Смазать верх яичным желтком. Выпекать маковый рулет с орехами в духовке 35-40 минут при температуре 180 градусов. Готовые остывшие рулеты посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7623,'В небольшом количестве теплого молока растворить крахмал. Остальное молоко поставить на медленный огонь, постоянно помешивая довести до кипения. Шоколад разломать на маленькие кусочки и добавить в молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7623,'Когда шоколад полностью растворится, в молоко влить крахмальную смесь. Варить горячий шоколад до тех пор, пока напиток не загустеет. Разлить в чашки и можно наслаждаться шоколадным вкусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7624,'Очистить семгу от шкуры и костей и нарезать на небольшие полоски размером 3-4 см. Замочить дрожжи в теплом молоке, через 5 минут добавить сахар, взбитые яйца, соль, масло. Затем всыпать просеянную муку и замесить некрутое мягкое тесто. Отставить на 30-40 минут в теплое место, чтобы оно увеличилось в размере в 2 раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7624,'Подошедшее тесто выложить в форму для выпечки, размять в пласт толщиной 3 см. На тесто положить рыбные кусочки на расстоянии 1 см друг от друга, сформировав круг и отступив от края 5 см. Затем этим краем теста накрыть рыбу и защипнуть край в середине круга. Ножом сделать небольшие ровные надрезы по тесту, где спрятана рыба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7624,'В середину пирога выложить маленькие кусочки семги и посыпать порезанными томатами и сладким перцем. Сыр натереть на терке и посыпать сверху пирога. Форму поставить в разогретую духовку на 30 минут при температуре 180 градусов. Готовый пирог с семгой и овощами имеет красивую золотистую корочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7625,'Творог протереть через сито, чтобы масса была без комочков. Затем в творог добавить взбитые яйца с сахаром, ванилин, корицу. В конце в массу добавить просеянную муку с разрыхлителем и вымесить очень мягкое творожное тесто. Посыпать стол и руки мукой, тесто скатать в колбаску и нарезать на маленькие кусочки. Придать руками форму правильных шариков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7625,'В глубокой кастрюле или сковороде с толстым дном раскалить масло для фритюра. Окунать в кипящее масло шарики и жарить до золотистого цвета. Готовые творожные пончики выложить на бумажное полотенце, чтобы убрать лишнее масло. Когда пончики из творога остынут, посыпать сверху сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7626,'Вафельница должна разогреться до максимума, чтобы тесто не прилипало. Яйца взбить с сахаром миксером в пену, затем добавить растопленное масло или маргарин. Просеять муку. Добавлять муку постепенно, взбивая тесто. Взбивать до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7626,'На разогретую вафельницу класть 1 полную ложку теста, прижать верхней частью и печь вафлю 2 минуты до золотистого цвета. Затем снять и быстро скрутить трубочку, оставив в середине место для начинки. Когда все вафельные трубочки остынут, их можно начинять. Наполнить кондитерский шприц сгущенным молоком и выдавить в трубочку. Домашние вафли готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7636,'Замочить желатин в воде, чтобы он набух. Затем слить воду, а желатин развести с теплым молоком, добавить творог, мед и какао-порошок. Ингредиенты взбить блендером или миксером в пышную однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7627,'Все ингредиенты для теста смешать, вымесить до крутого состояния, накрыть пленкой и поставить в холодильник на 10 минут. В это время следует заняться начинкой из мака. Мак необходимо измельчить. Для этого подойдет кофемолка. Затем добавить к маку манную крупу, перемешать и высыпать в кипящее молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7627,'Добавить сахар, варить мак с манкой 5 минут, пока масса начнет густеть. Начинку остудить. Тесто достать из холодильника, разделить на 2 равные части. Одну половинку раскатать и выложить в форму для пирога, закрыв стенки формы. Выложить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7627,'Сверху закрыть пирог второй половиной раскатанного теста. Выпекать 30 минут в духовке при температуре 200 градусов. Румяный пирог с маковой начинкой проверить на готовность спичкой. Когда остынет, посыпать сахарной пудрой или украсить свежими фруктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7628,'Просеять муку и какао в миску, добавить яйца, растопленное масло, влить молоко, тщательно перемешать, дать тесту постоять 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7628,'Раскалить сковороду, налить половником порцию теста, жарить как обычные блины (примерно по 1 минуте с каждой стороны)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7628,'Смазать каждый блин шоколадной пастой, положить ложку малины, разровнять и свернуть блин в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7628,'Подавать блины шоколадные с начинкой с мороженым и натертым шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7629,'Для выпечки кекса необходимо выбирать специальную форму с дыркой посередине. Форму смазать сливочным маслом, духовку включить на 200 градусов. Тесто лучше готовить при помощи миксера, так оно получается очень пышным и без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7629,'Мягкое масло взбить в миске с сахаром до пышной массы. Затем добавлять постепенно яйца, сметану и просеянную муку с содой, солью и ванилином. Консистенция готового теста чуть гуще сметаны. Персики порезать на небольшие кусочки, пересыпать их небольшим количеством муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7629,'В форму выложить часть теста, посыпать персиками, затем опять тесто и персики, сверху залить все тестом. Поставить в духовку на 20 минут при температуре 160-170 градусов. Готовность проверить спичкой. Готовый кекс остудить и смазать фруктовой глазурью. Для глазури смешать миксером сливки, сахарную пудру и сок. Нанести на персиковый кекс и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7630,'Смешать в тарелке травы — салат фриссе, листья шпината и сливочный хрен. Полить небольшим количеством майонеза, посолить по вкусу. Копченый угорь порезать порционными кусочками, придав форму треугольников. Также порезать папайю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7630,'Клубнику вымыть и нарезать дольками, помидоры черри разрезать пополам. На широкую тарелку выложить горкой зелень, сверху помидоры, кусочки папайи и дольки клубники. По бокам салата с папайей и клубникой разложить копченый угорь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7631,'Стакан кефира взбить со стаканом сахара. Муку смешать с содой и какао, добавить к кефиру. Взбить тесто, чтобы растворились все комочки. Тесто получается наливным. Форму смазать сливочным маслом, вылить все тесто и поставить в духовку на 30 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7631,'Чтобы корж после выпечки был ровным, необходимо в тесте сделать небольшую воронку ложкой, распределяя тесто ближе к краям. Готовый пирог остудить и разрезать вдоль на две ровные половинки. Сметану взбить с сахаром в пышную массу. Промазать слои тортика сметанным кремом, сверху украсить тертым шоколадом. Шоколадный торт «Обыкновенное чудо» должен пропитаться в течение суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7632,'Тесто выложить в формочки, убрать лишнее тесто. Наколоть тесто вилкой. Застелить фольгой тесто и положить небольшой груз, чтобы слоеное тесто не поднималось. Через 10 минут убрать фольгу и довести тарталетки до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7632,'Обжарить на сковороде белые грибы, порезанные дольками. Лук почистить, нарезать полукольцами и обжарить на растительном масле до золотистого цвета. Взбить венчиком яйца со сливками, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7632,'В тарталетки положить обжаренный лук, затем грибы, залить яичной смесью и поставить в духовку на 20 минут. Когда тарталетки с луком и белыми грибами приобретут золотистую корочку, можно вынимать из духовки. Подавать теплыми или охлажденными.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7636,'Разлить в подготовленные формочки и поставить в холодильник до полного остывания. Украсить диетический шоколадный чизкейк веточкой мяты или долькой апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Приготовим бисквит. Отделить белки и желтки. Желтки взбить с сахаром в пену, белки отдельно взбить миксером в густую пену до острых пиков, постепенно всыпать сахар, чтобы не осела пена. Соединить белки и желтки. Муку просеять, всыпать по не многу в яичную смесь, мешать ложкой, чтобы не осела пышность.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Форму для бисквита посыпать мукой или положить бумагу для выпечки, смазанную маслом. Выложить тесто и поставить в духовку на 30 минут при температуре 200 градусов. Готовый бисквит достать из духовки и дать постоять 10 минут в форме. Затем разрезать на две равные части вдоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Теперь необходимо приготовить маковый бисквит. Мак измельчить на кофемолке. Масло растопить, соединить с сахарной пудрой, маком, яйцом, желтком и мукой, взбивать в пышную массу. Белки взбить миксером в пышную пену и выложить в остальное тесто, размешать ложкой. Тесто выложить в форму и выпекать 20 минут при температуре 180 градусов. Готовый маковый бисквит остудить и отложить в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Теперь необходимо приготовить лимонный сироп. Закипятить воду, добавить сахар. Ломтики лимона залить горячей сладкой водой и отложить на 2-3. Для лимонного крема следует взять цедру одного лимона и лимонный сок с двух лимонов, добавить сахар, яйца, перемешать и отставить на 1 час. Затем процедить эту смесь через сито или марлю, отжать и добавить крахмал. Варить на очень медленном огне до загустения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Накрыть крем пленкой и поставить в холодильник. Сразу отложить немного лимонного крема для смазывания боков торта, остальную часть взбить с творогом. Теперь соберем торт. Каждую часть бисквита пропитать лимонным сиропом. Половину бисквита смазать лимонно-творожным кремом, затем положить маковый бисквит, смазать кремом, опять половинку бисквита, смазать лимонным кремом, обмазывая все бока торта. Поставить на 1 час в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'В это время необходимо приготовить швейцарскую меренгу. Готовить ее правильно на водяной бане, чтобы получилась пышная и блестящая масса. Сахарную пудру смешать с белками и взбивать на водяной бане до блеска и острых пиков. Меренгой следует смазать весь торт, затем сверху выложить толстым слоем оставшуюся часть и красиво разровнять по всей поверхности торта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7633,'Если меренга становится непластичной, начните ее взбивать венчиком, и она опять приобретет свою необходимую консистенцию. Готовый маково-лимонный торт с меренгой поставить в разогретую духовку до 200 градусов на 2 минуты для обжига.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7634,'Кусок говяжьего мяса вымыть и обсушить бумажным полотенцем. Посолить и поперчить по вкусу. Натереть чесноком и паприкой, полить 2 ложками растительного масла. Для сочности и красивой формы, мясо стянуть кулинарной нитью, обмотав в одном направлении.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7634,'Мясо обжарить на растительном масле до румяной корочки со всех сторон. Жарить по 3-4 минуты с каждой стороны, аккуратно переворачивая кусок вилкой. Разогреть духовой шкаф до 120 градусов. Положить мясо на дно жаропрочной сковороды. Готовить ростбиф 3-4 часа, часто переворачивая в разные стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7634,'Внутри мясо должно оставаться розовым, температура внутри куска не больше 60 градусов. Готовый ростбиф вынуть из духовки и оставить отдыхать полчаса, затем снять нить. Подавать мясо с соусом из хрена или горчицей. Говяжий ростбиф медленного приготовления подается охлажденным, на гарнир – зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7635,'В теплом молоке развести дрожжи, сахар и щепотку соли. Оставить в теплом месте на 30 минут, пока опара не увеличится в 2 раза. Когда в тесте образуется «воронка», значит, опара готова. Добавить стакан подсолнечного масла и просеянную муку. Вымешивать до однородного состояния. Тесто поставить в теплое место, чтобы оно поднялось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7635,'Пока подходит тесто, следует замочить изюм горячей водой, затем просушить. Взять небольшую часть теста, раскатать в пласт, смазать растопленным сливочным маслом и посыпать изюмом. Скатать в рулет и нарезать острым ножом на небольшие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7635,'Противень смазать растительным маслом, выложить булочки. Каждую смазать взбитым яйцом и посыпать кунжутом. Оставить на противне в теплом месте на 20-30 минут, чтобы булочки «подошли». Затем противень поставить в горячую духовку на 30 минут. Пышные булочки «Ачма» с румяной корочкой готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7637,'Переложить картофель в огнеупорную форму, сверху слой ветчины, залить смесью сметаны с яйцами, мукой, солью и тертым сыром (часть оставить для присыпки).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7637,'Выложить на заливку еще слой картофеля, кусочки масла и присыпать сыром, отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7637,'Картофель с сыром и ветчиной в духовке будет готов через 45 минут, нарезать на порции и подать к столу горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7638,'Куриное филе необходимо нарезать на ровные длинные кусочки. Чтобы мясо хорошо резалось, его можно подморозить. Раскалить сковороду и налить пару столовых ложек растительного масла. Затем выложить туда куриные кусочки и обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7638,'Не нужно жарить до румяной корочки, когда мясо побелеет, следует вылить к нему соевый соус. Так как соус соленый, солить мясо не требуется. Но и соус необходимо лить в меру, чтобы не перенасытить мясо его вкусом и запахом. Протушить мясо в соусе 2 минуты и выложить в кастрюльку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7638,'Сладкий перец помыть и очистить от семян. Нарезать на полоски по размеру, как мясо и обжарить на той же сковороде, где жарилась курочка. Жарить на сильном огне с добавлением растительного масла, чтобы перец не потерял свой вкус и полезные свойства. Когда перец станет мягким, выложить к курице. Лук очистить и нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7638,'На сильном огне обжарить лук 2 минуты, постоянно помешивая. Затем влить ложку соевого соуса и жарить еще 1 минуту. Из лука выделится сок, который смешается с соевым соусом и придаст блюду неповторимый вкус и аромат. Но это еще не все. Теперь к луку следует добавить сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7638,'В этой смеси соусов необходимо карамелизировать лук. Золотистый, невероятно вкусный лук добавить к курице и перцу, затем все аккуратно перемешать. Подавать куриное филе с карамельным луком с гарниром из картофеля и свежим салатом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7639,'Натереть сыр на мелкой терке, посолить и поперчить по вкусу. Вбить одно яйцо, перемешать. Чеснок очистить и выдавить через пресс к сыру, перемешать. Муку просеять и добавлять понемногу в сырную массу. Вымешивать тесто, чтобы не прилипало к рукам. Тесто должно быть достаточно мягким, не забитым мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7639,'Руки присыпать мукой и разделить тесто на маленькие шарики, обвалять каждый в муке. В раскаленную сковороду налить растительное масло, выложить сырные шарики и жарить на среднем огне с каждой стороны до румяной корочки. Готовые шарики достать шумовкой и выложить на бумажное полотенце. Когда стечет лишний жир, сырные шарики с чесноком можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7640,'Бананы – источник калия, используется в торте в замороженном виде. По вкусу, как банановое мороженое. Очистить бананы от кожуры и положить в морозильную камеру на 3-4 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7640,'Грецкие орехи – природный антиоксидант, их употребление крайне важно для улучшения самочувствия человека. Огромное количество витаминов и микро-, макро-элементов, что содержаться в орехах, могут способствовать излечению от многих болезней. Этот чудо продукт необходимо измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7640,'Также измельчить финики, соединить с ореховой массой. Форму для торта использовать с разъемными боками, чтобы потом легче вынуть торт. Распределить орехово-финиковую смесь по всей форме, захватив бока. Затем выложить банановый крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7640,'Чтобы торт получился интересным, ярким, можно бананы соединить с другими фруктами для создания ярких цветов. Например, с черникой. Половину банановой массы взбить с ягодами черники. Выложить крем слоями. Разровнять лопаткой мороженый крем и можно угощать чернично-финиковым тортом гостей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7641,'Свежие томаты очистить от кожуры и перемолоть в блендере. Чеснок пропустить через пресс. Зелень измельчить и всыпать к томатному соусу. Имбирь и огурец порезать тонкой соломкой. Лук порей вымыть и нарезать ровными кольцами средней толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7641,'Древесные грибы замочить на 10-15 минут, затем нарезать полосками. Измельчить сельдерей. Сладкий перец порезать тонкими полосками, перец чили тонкими колечками. Грибы шампиньоны нарезать тонкими пластинками, если грибы крупные, поделить пополам. Отделить немного зелени, овощей и грибов для презентации блюда, остальное использовать в приготовлении.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Дать остыть. Разрезать вдоль на 2 части, одну положить в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7641,'Соединить суймоно, бульон-заправку качукка, грибы и овощи, закипятить. Затем выложить кольца поррея, шампиньоны, огурец и перец чили. При подаче посыпать сверху зеленью, украсить томатный суп «Томато сиру» полосками огурца и палочкой корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7642,'Для приготовления теста на блины необходимо все ингредиенты тщательно взбить миксером или блендером, чтобы разбить комочки. Сначала яйца взбить с сахаром и солью. Затем добавить молоко. Просеянную муку соединить с ванилином и всыпать понемногу в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7642,'Взбивать миксером до получения жидкого однородного теста по консистенции жидкой сметаны. В конце влить растительное масло. Жарить блины на раскаленной сковороде с двух сторон. Мак варить в молоке 10 минут. Затем остудить и добавить мед или сахар. В остывшие блинчики завернуть маковую начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7643,'Яблоки и груши взять в равных пропорциях, очистить от кожуры и семян, нарезать на небольшие кубики или тонкие слайсы. Для приготовления теста следует взбить размягченное масло или маргарин с сахаром. Можно перетереть руками в крошку. Затем добавить яйца, хорошо взбить миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7643,'Муку просеять, соединить с ванилином. Добавить к масляной смеси муку и вымесить мягкое некрутое тесто. Порезанные фрукты соединить с тестом. Форму смазать сливочным маслом и присыпать сахаром, так получится хрустящая корочка на шарлотке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7643,'Выложить тесто, разровнять и поставить в духовку на 50-60 минут при температуре 180 градусов. Готовность яблочно-грушевой шарлотки проверить спичкой. Яблоки очень любят специю корицу. Поэтому ее можно смело добавить во фруктовую нарезку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7644,'Крабовые палочки измельчить на кубики. Яйца отварить, затем очистить и порезать мелким кубиком или натереть на средней терке. С консервированной кукурузы слить жидкость. Рис отварить до готовности. Лук мелко порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7644,'В прозрачную салатницу выкладывать слоями. Сначала рис, смазать майонезом. Затем слой кукурузы. На кукурузу выложить слой крабовых палочек и смазать майонезом. Яйца смешать с майонезом и выложить слоем на палочки. Украсить слоеный крабовый салат луком и свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7645,'При помощи миксера взбить яйца с сахаром, посолить по вкусу и добавить молоко. Просеять муку и добавить разрыхлитель, какао. Муку постепенно всыпать в тесто, продолжая взбивать миксером. По консистенции тесто будет, как жидкая сметана. Раскалить сковороду, смазать растительным маслом. Наливать порцию теста на сковороду и жарить блин с двух сторон. Готовые блинчики остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7645,'Для начинки необходимо замочить изюм, высушить, затем смешать с творогом и сахаром. В каждый блинчик завернуть немного начинки и сложить аккуратной горкой. Шоколадные блинчики можно заворачивать по-особенному, например, в форме конфетки. Завязать края шоколадных блинчиков с творогом полоской кураги или чернослива.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7646,'Сначала необходимо замочить желатин, чтобы он немного набух. Затем поставить на медленный огонь и нагреть, чтобы желатин растворился полностью. Кусочки ананасов взбить блендером со сливками и сахарной пудрой. Затем в эту массу ввести 2/3 разведенного желатина, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7646,'Приготовить формочки небольшого диаметра для наполнения. Выложить в формочку ананасовую массу и поставить в холодильник для застывания. Когда мусс станет застывать, сверху выложить тонкие дольки ананасов, немного вдавив их в поверхность мусса. Поставить опять на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7646,'В это время необходимо сварить крепкий кофе, добавить сахар по вкусу и вылить остаток желатина. Остудить и вылить сверху на ананасовый застывший мусс. Это будет вторая половина. Когда десерт «Ананас в кофе со сливками» полностью застынет, можно снять формочку, очень аккуратно провести острым ножом по краям формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7647,'На раскаленной сковороде обжарить бекон, порезанный полосками. Если бекон не жирный, добавить ложку растительного масла. Затем снять на тарелку, а в сковороду вылить яйца, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7647,'Яйца мешать во время жарки, пока полностью не приготовятся. Зеленый лук мелко нарезать и посыпать яйца во время приготовления, чтобы блюдо пропиталось луковым ароматом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8367,'В глубокую тарелку положить кешью, полить кукурузным сиропом.','https:https://st.vkuso.ru/data/cache/thumb/14/5d0bc68ea905714_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7647,'На широкой тарелке порвать салатные листья, посыпать зеленью, выложить бекон и жареные яйца. Смешать в равных долях горчицу, лимонный сок и оливковое (растительное) масло. Полить теплый салат с беконом и яйцами заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7648,'Размешать в холодном молоке манку и сварить манную кашу, дать остыть, включить на разогрев духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7648,'Взбить желтки со 100 г сахара, смешать с творогом и добавить ванилин, изюм и цедру лимона, взбить миксером, смешать творожную массу с манной кашей и еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7648,'Отдельно взбить с оставшимся сахаром яичные белки, добавить к творогу с манкой, аккуратно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7648,'Смазать растительным маслом огнеупорную форму, переложить смесь и отправить в духовку запекаться до зарумянивания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7648,'Готовый пудинг из творога и манки остудить и подать со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7649,'Срезать у батона концы, достать мякиш, мелко порезать колбасу, мясо, яйца, сыр, перец и помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7649,'Растереть масло со смесью горчицы и хрена, добавить к нарезанной смеси, посолить и все хорошо перемешать. Можно добавить порезанный на кубики мякиш батона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7649,'Плотно нафаршировать батон смесью и положить в холодильник, перед подачей батон фаршированный мясом и сыром нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7650,'Нарезать курицу (можно взять несколько окорочков) на порции, кожу удалить, переложить куски в сотейник, залить смесью воды со сметаной, дать закипеть, отлить стакан бульона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7650,'Добавить в сотейник предварительно замоченные (минимум на 3 часа) сухие белые грибы вместе с жидкостью, уменьшить нагрев до минимального, тушить курицу до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7650,'В сковороде на сливочном масле потушить мелко нашинкованный лук, развести, помешивая, в остывшем стакане бульона постепенно 2 ст.л. муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7650,'После того как курица сварится, переложить из сковороды в кастрюлю лук и мучную заправку, когда курица тушеная с грибами в сметанном соусе закипит, поперчить и посолить по вкусу, дать покипеть пару минут и выключить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7651,'Нарезать бананы, яблоки, выложить их слоем на дно огнеупорной формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7651,'Смешать яйца, творог, сахар, сметану, залить смесью фрукты в форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7651,'Включить на разогрев духовку до 200 градусов, поставить форму и запечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7651,'Яблочно-банановая творожная запеканка будет готова примерно через 30-40 минут, фруктовую начинку можно менять по своему вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7652,'Сварить очищенный картофель и морковь до мягкости, воду слить, овощи размять до состояния пюре, добавить 2 яйца, посолить и перемешать, включить на разогрев духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7652,'Измельчить блендером куриное филе до состояния фарша, добавить измельченный шпинат (или молодую крапиву) и перемешать, заправить перцем и солью, вбить яйцо и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7652,'Смазать форму маслом, переложить половину овощного пюре и разровнять, поверх выложить смесь шпината с курицей, закрыть оставшимся пюре, по поверхности равномерно разложить порезанное на кусочки сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7652,'Выпекать картофельно-морковную запеканку с курицей и зеленью около 40 минут при температуре 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7653,'Протереть сквозь сито нежирный и некислый творог с сахаром, ванилином, влить молоко, взбить смесь и добавить замороженную клубнику.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7653,'Переложить творожную массу в вазочки и охладить, подать творожный десерт с молоком и клубникой к столу можно будет через час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7654,'Протереть творог через сито, добавить сахар, манку, разрыхлитель, ваниль, вбить яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7654,'Подготовить формочки, смазать маслом, включить на разогрев духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7654,'Переложить подготовленную творожную массу в формочки и отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7654,'Запеканка из творога с манной крупой выпекается 25 минут при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7655,'Взбить яйцо с сахаром до полного его растворения, добавить постепенно муку, растопленное масло и как следует взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7655,'Разложить тесто по формочкам (примерно по 1 ст.л.), хорошо зарумянить в духовке, чтобы вафли хрустели, свернуть сразу их в трубочки. Дать им остыть и наполнить кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7655,'Для крема как следует взбить масло и вареную сгущенку, вафельные трубочки с кремом из сгущенки выложить горкой на блюдо и присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7656,'Добавить в кефир мелко порезанный чеснок, соль, травы и перец, залить полученным маринадом куриные бедра на 20-25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7656,'Очистить картофель и нарезать на дольки, переложить их в форму для запекания, добавить оливковое масло, приправить перцем, солью, травами, раздавить ножом зубчики чеснока и распределить равномерно по поверхности картофеля.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7656,'Разрезать на 4 части помидоры черри, положить на картофель куски курицы и залить маринадом, разложить между кусками мяса четвертинки томатов и отправить форму в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7656,'Запеченная с картофелем курица, маринованная в кефире, готовится 40 минут при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Распустить сливочное масло, наломать на кусочки шоколад, помешивая довести до однородной консистенции, заварить в теплой воде растворимый кофе с ванилином и солью, смешать с масляно-шоколадной смесью, включить на разогрев до 175 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Взбить сахар с яйцами до увеличения объема вдвое (примерно 5 минут), всыпать какао, перемешать до однородной массы, смешать с кофейно-шоколадной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Вылить полученное для основы тесто в форму, отправить в духовку, запекать около 50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Приготовить мусс для заливки торта, смешав масло с разрыхлителем и кусочками белого шоколада, растопить смесь в микроволновке в течение 30 секунд (пару раз перемешать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Взбить сахар с желтками, поставить посуду на водяную баню примерно на 5 минут пока содержимое не загустеет, снять с огня, всыпать ванилин и добавить смесь масла с белым шоколадом, влить 2 ст.л. сливок, хорошо перемешать, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Взбить в крепкую пену сливки (1,5 стакана), ввести треть в шоколадную смесь, перемешать, добавить оставшуюся часть и еще раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7657,'Готовую остывшую основу торта залить муссом и на час поставить на холод. Достать из холодильника трюфельный торт с белым шоколадным муссом и украсить присыпкой из какао-порошка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7658,'Нарезать свинину на порционные куски, отбить, втереть смесь перца с солью, дать постоять, раскалить в высокой чугунной сковороде (сотейнике) масло, быстро обжарить мясо с одной и с другой стороны, переложить отбивные на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7658,'Слить из сковороды почти весь жир с мясным соком (оставить 1 ст.л.), уменьшить нагрев и обжарить мелко порезанный лук около 3-4 минут, добавить уксус, продолжать помешивая нагрев пока вся жидкость не испарится (около 3 секунд).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7658,'Опять положить отбивные, залить в сковороду полстакана воды, сливки, добавить порубленный шалфей и петрушку, тушить около 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7658,'Переложить мясо на блюдо, дать ему постоять, доварить соус пока практически вся жидкость не испарится и не останется около 3 ст.л., подавать отбивную из свинины в сливках с картофельным пюре, посыпать рубленной петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7659,'Подготовить куриные грудки, аккуратно острым ножом надрезать вдоль и раскрыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7659,'Накрыть мясо пленкой и слегка отбить, присолить, поперчить, выложить слой рубленой зелени, а по центру – вареное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7659,'Свернуть мясо в рулет, сформовать биточек, обмакнуть в сырое яйцо, обвалять в сухарях и обжарить до золотистого цвета в раскаленном масле со всех сторон и после этого тушить еще 30 минут в духовке при температуре 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7659,'Готовые биточки из куриных грудок с яйцом нарезать на ломтики и подать к столу, биточки можно есть горячими и холодными.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7660,'Залить манку кефиром и дать набухнуть 30 минут, растопить масло (маргарин), взбить его с сахаром, ванилином и яйцами, погасить соду и смешать все с набухшей манкой и кефиром, постепенно всыпать просеянную муку, вымесить тесто до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7660,'Вылить подготовленное тесто в смазанную маслом форму и отправить в микроволновку, манник на кефире в микроволновке готовить при мощности 600 Вт в течение 6-7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7661,'Налить молоко в миску, растворить соль, положить помытые грудки, накрыть пленкой и убрать на ночь в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11376,'Лук нарезать, морковь нашинковать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7661,'Раздавить чеснок, смешать со специями, медом, оливковым маслом и соевым соусом, полученной смесью смазать грудки и дать постоять полчаса, обвязать плотно шпагатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7661,'Куриная пастрома со специями запекается 20 минут при температуре 250 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7662,'Смешать молоко, сухое молоко и сахар в кастрюле с толстым дном, проварить на слабом огне, при постоянном помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7662,'Варить пока масса не станет коричневатой и чуть загустеет, т.е. будет напоминать домашнюю сгущенку, потребуется около часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7662,'Добавить сливочное масло, варить дальше, через какое-то время получится хорошая сливочная масса, подходящая для смазывания коржей для торта. Осторожно, переваривать нельзя!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7662,'Варить до густоты и темного цвета, сделать пробу «капля — шарик». Капнуть чуть-чуть массы на холодную поверхность и скатать шарик, если хорошо катается и не пристает к рукам, то конфеты «Коровка» домашнего приготовления уже готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7662,'Переложить помадку на пергамент, раскатать скалкой и нарезать на квадратики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7663,'Сварить кофе, бананы и мороженое порезать на кусочки, поместить все в блендер и залить молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7663,'Выставить среднюю скорость и взбивать примерно около 3 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7663,'Кофейный коктейль с бананом и мороженым перед подачей желательно охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7664,'Нарезать грибы, нашинковать лук, потушить в сотейнике, добавить белое вино, приправить перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7664,'Порезать филе кубиками и подрумянить на масле до полуготовности, сформовать из готового слоеного теста шар и снова раскатать в пласт, равномерно распределить филе курицы по поверхности, а сверху выложить грибы, скатать тесто в рулет и запечь при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7664,'Курица с шампиньонами в тесте будет готова через 30 минут, подавать горячей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7665,'Подготовить рыбу, нарезать на стейки (толщиной примерно по 1,5-2 см), присолить и поперчить кусочки с двух сторон, включить на разогрев до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7665,'Разложить стейки на блюде, сбрызнуть с одной стороны соком лимона, смоченной стороной вниз выложить в форму, выстеленную фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7665,'Измельчить на мелкой терке сыр, смазать кусочки рыбы майонезом, присыпать сыром и убрать в духовку, температуру убавить до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7665,'Горбуша под майонезом и сыром в духовке будет готова примерно через 30-40 минут (готовность можно проверить вилочкой), когда зарумянится сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7666,'Проварить, помешивая, 20 минут на водяной бане взбитые с медом и сахаром яйца с добавлением сливочного масла и соды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7666,'Снять массу с плиты, добавить муку, замесить тесто, убрать на час в теплое место, затем включить на разогрев духовку до 200 градусов, разделить тесто на 7-8 частей, раскатать тонкие коржи, навернуть их на скалку, перенести на противень, выпекать по одному до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7666,'Взбить размягченное масло с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7666,'Смешать молоко и яйца, добавить ванилин и муку, перемешать, варить на слабом огне пока масса не стане густой, добавить в остывший крем масло с сахаром и тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7666,'Дать коржам остыть, смазать кремом, украсить по вкусу, убрать десерт в холодильник на ночь, чтобы торт с заварным кремом «Бабушкин Рыжик» хорошо пропитался.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7667,'Смешать хорошо в блендере молоко, порошок кофе, сахар, взбивать пока сахар не растворится, добавить водку и еще раз перемешать, дать ликеру настояться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7667,'Подавать сливочный ликер домашнего приготовления охлажденным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7668,'Отварить куриное филе в подсоленной воде под крышкой с добавлением черного перца и лаврового листа на слабом огне в течение часа, остудить, разобрать мясо на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7668,'Нарезать мелко колбасный сыр, вареные яйца, натереть отваренные морковь и картофель, разделить все продукты на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7668,'Поставить в центр блюда перевернутый стакан, выложить кольцом вокруг  него слои в следующем порядке: курица, картофель, морковь, майонез, яйца, повторить еще раз все слои, стакан убрать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7668,'Смазать салат со всех сторон майонезом, нарезать киви на кружочки, разрезать их пополам, украсить салат укропом и киви.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7669,'Приготовить куриный бульон, добавить зажарку из моркови с луком, проварить  на медленном огне 5 минут, всыпать жареные шампиньоны, дать покипеть 2-3 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7669,'Нарезать ломтиками картофель, высыпать в бульон, проварить 10 минут и добавить порезанные на кусочки плавленые сырки, мешать пока сыр не растворится, заправить солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7669,'Готовый сырный картофельный суп с шампиньонами должен постоять под крышкой 20-30 минут, подать с измельченной зеленью и сухариками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7670,'Измельчить блендером или мелко порубить лук, смешать с куриным фаршем, заправить солью и перцем, переложить массу в форму, сверху слоями уложить помидоры и сладкий перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7670,'Натереть картофель на терке, поперчить, посолить, влит ложку масла, выложить на перец, смазать сметаной, посыпать натертым сыром, выпекать овощную запеканку с сыром и куриным фаршем около 40 минут при 190 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7671,'Подготовить разъемную форму: выложить на дно пергамент, смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7671,'Измельчить в крошку печенье, добавить растопленное масло и молоко, перемешать, плотно уложить на дно формы, убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7671,'Приготовить из бананов пюре, растворить на водяной бане, предварительно замоченный в соке лимона желатин, смешать с пюре, поставить в холодильник на 15 минут, масса должна чуть «схватиться», но не превратиться в желе!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7671,'Протереть сквозь сито творог, влить сметану, добавить мед и цедру лимона, чуть-чуть взбить, в другой посуде взбить сахарную пудру, ванильный сахар и сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7671,'Смешать и взбить творог, сливки, банановое пюре, выложить смесь в форму, убрать чизкейк банановый с творогом без выпечки на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7672,'Включить на разогрев до 175 градусов духовку, смазать круглую форму с отверстием в центре маслом и присыпать порошком какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7672,'Смешать муку, сахар, какао, соду, разрыхлитель, соль, взбить в гомогенную смесь на малой скорости в миксере кофе, масло, молоко, яйца, ванилин, постепенно всыпать мучную смесь, окончательно взбить тесто на средней скорости около 5 минут, перелить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7672,'Выпекать простой шоколадный пирог 45 минут, охладить, посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7673,'Отделить белки от желтков, взбить миксером желтки с ванилью и сахаром (смесь должна побелеть).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7673,'Добавить протертый сквозь сито творог, взбить до однородной массы, засыпать манку и чернику, отдельно взбить белки и аккуратно соединить с творожной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7673,'Переложить все в смазанную форму, выпекать при 180 градусах, запеканка из творога с черникой будет готова через полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7674,'Смешать в большой миске просеянную муку с солью и дрожжами, влить в углубление в центре воду с маслом, перемешать движением от краев к центру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7674,'Тщательно вымесить пластичное тесто и убрать в тепло на час (в два раза должен увеличиться объем).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7674,'Нарезать кольцами лук, включить на разогрев до 220 градусов духовку, раскатать из теста круглую лепешку, смазать сверху томатным соусом, разложить лук, сверху – бекон и шарики из моцареллы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7674,'Аппетитная пицца с беконом и сыром Моцарелла будет готова через 20-25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7675,'Для основы смешать просеянную муку и разрыхлитель, смесь порубить с маслом (предварительно его охладить), добавить яйцо, сахар, вымесить тесто, завернуть его в пленку, убрать на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7675,'Для начинки смешать в блендере до однородности творог, сметану или густые сливки, сахар, желтки и манку, добавить ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7675,'Для суфле белки взбить с сахарной пудрой в крепкую пену (всыпать пудру постепенно).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7675,'Достать тесто, переложить в форму, равномерно распределить по дну слоем в полсантиметра, сверху выложить творожную начинку, запекать полчаса при 180 градусах, вынуть и выложить сверху суфле, запекать еще 15 минут, чтобы верх торта стал золотистым, вынуть и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7675,'Торт «Слезы ангела» с творогом и суфле должен максимально охладиться тогда на поверхности выступят небольшие капельки золотистого цвета, давшие ему название.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Убрать бисквитный шоколадно-абрикосовый торт в холодильник на ночь.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7676,'Сварить очищенную рыбу в небольшом количестве воды в течение 5 минут, разделать на филе, измельчить на небольшие кусочки, смешать с картофельным пюре, добавить мелко нарезанную зелень петрушки, лук, масло, заправить зернами кумина, молотым черным перцем, солью, влить слегка взбитые с натертым сыром яйца, размешать, включить для разогрева на 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7676,'Разложить смесь по формочкам и поставить запекать до образования  так ценящейся в этом блюде корочки, классический  тажин с рыбой и картофелем высотой в 3 см будет готов через 20 минут, подавать блюдо с оливками или свежими овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7677,'Сварить телячью печень в подсоленной воде, измельчить на терке с крупными отверстиями, если готовить из куриной печени, то ее можно просто порезать мелкой соломкой, т.к. она более мягкая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7677,'Сварить морковь, измельчить на терке с крупными отверстиями, лук порезать на мелкие кубики и зарумянить на масле, нарезать огурчики на небольшие кубики, у вареных яиц отделить белки от желтков, измельчить белки на крупной терке, а желтки отложить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7677,'Уложить салат слоёный с печенью «Печёнкин» в высокое блюдо следующим образом: половину печени, майонез, половину лука, половину огурцов, морковь, майонез, белки, майонез, снова печень, лук, огурцы, густой слой майонеза, в конце посыпать измельченными на мелкой терке желтками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7678,'Смешать тщательно все ингредиенты, переложить в банку, закрыть крышкой и выдержать в прохладном месте ночь, использование в рецепте молока не даст горчице постареть, готовую горчицу с мёдом по-домашнему хранить в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7679,'Залить порошок магазинного желе зеленого цвета 2 ложками кипятка, размешать до исчезновения комочков, влить вместо воды, указанной на упаковке столько же водки, разлить по формочкам в виде елочек, дать застыть в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7679,'Переложить из формочек готовое алкогольное новогоднее желе «Jello Shots» на плоское блюдо, украсить «снегом» из кокосовой стружки и фигурной кондитерской присыпкой в виде звездочек и шариков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7680,'Взбить размягченное сливочное масло со сметаной и сахаром до однородного состояния, добавить фрукты, всыпать маленькие крекеры, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7680,'Выстелить дно формы пленкой, переложить готовое тесто, накрыть пленкой, разровнять и слегка примять, дать переночевать в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7680,'Достать, переложить на тарелку и украсить фруктовый сливочно-сметанный торт без выпечки, исходя из своей фантазии.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Подготовить форму для выпечки: застелить пергаментом, смазать маслом, присыпать мукой, включить разогреться до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Смешать разрыхлитель, просеянную муку, соль, а в другой миске ванилин с молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Взбить миксером масло (размягченное) с сахарной пудрой до состояния воздушности, вбить по одному яйца, взбивать смесь после каждого.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Засыпать постепенно в молоко мучную смесь, взбивать после каждого добавления, должна получиться воздушная масса, разделить ее по мискам на 5 частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Одну часть оставить белой, в другие добавить краситель, количество красителя в каждой следующей порции должно увеличиваться, чтобы получилось 5 разнообразных оттенков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Выпекать коржи по одному по 20 минут, остывшие коржи промазать джемом или глазурью из взбитого с сахарной пудрой масла и щепотки соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7681,'Промазать его сверху глазурью, украсить торт с глазурью и джемом «С днем рождения!» кондитерской присыпкой и убрать на четверть часа в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'Творог пожирнее при необходимости отжать через марлю, пропустить через мясорубку или протереть через сито, чтобы консистенция получилась кремообразной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'Белки, отделенные от желтков, взбить с щепоткой соли в устойчивую пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'В пышную массу взбить желтки с сахаром, затем добавить творог, лимонную цедру, изюм, 100 г мягкого сливочного масла и манную крупу, все вымешать до получения однородной массы, в конце добавить взбитые белки и осторожно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7717,'Смазать кастрюлю кокосовым маслом, выложить полученную массу и запечь в духовом шкафу при температуре 150 градусов в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'В форму, предварительно смазанную маслом и посыпанную мукой, переложить полученную массу, поставить ее в разогретую до 190 градусов духовку и запекать сырник в течение 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'На среднем огне разогреть сливочное масло и сахар, затем добавить какао и сметану,  постоянно помешивая довести глазурь до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7682,'Готовый львовский сырник с глазурью переложить на тарелку или блюдо, полить приготовленной глазурью и на некоторое время поставить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7683,'С помощью мелкой терки измельчить любой сыр, чеснок очень мелко нарезать и добавить к сыру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7683,'В сырно-чесночную смесь добавить небольшое количество майонеза, тщательно все размять и мешать до получения пластичной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7683,'Поместить внутрь каждой оливки по одному миндальному орешку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7683,'Из приготовленной массы сделать шарики, в середину которых поместить заранее подготовленные оливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7683,'Вымыть укроп, очень хорошо его просушить и порезать как можно мельче, затем запанировать в нем шарики из сыра с оливками и миндалем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Миндаль залить кипятком, затем очистить его от кожуры, обсушить и измельчить любым удобным способом в мелкую пудру, которую потом смешать с сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Полученную смесь просеять через мелкое ситечко 2 раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Белки, отделенные от желтков, взбить со щепоткой сахара, а когда они начнут подниматься, постепенно ввести сахар (по одной чайной ложке), продолжать взбивать до густой пены.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Далее необходимо добавить желтый пищевой краситель, 1/3 часть миндально-сахарной пудры, все аккуратно перемешать с помощью лопатки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'В белковую массу всыпать оставшуюся часть пудры, продолжать аккуратно помешивать до получения однородной массы (масса не должна получиться слишком жидкой).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Готовым тестом заполнить кондитерский мешок, диаметр которого 8 мм, и с его помощью выдавить на застеленный пекарской бумагой противень макаруны, расстояние между которыми должно быть 5 см.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Для того чтобы из макарун вышел весь воздух, каждую нужно прихлопнуть намоченным пальцем, дать подсохнуть в течение получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'После отведенного времени отправить противень на 13 минут в разогретую до 150 градусов духовку, затем приоткрыть дверцу духовки, а через минут открыть духовку полностью, дать остыть макарунам.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'При помощи миксера взбить сахарную пудру со сливочным масло, постепенно добавить лимонный сок, получившийся крем выложить на одну половину печенья и сверху накрыть второй.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7684,'Перед подачей следует лимонное печенье «Macarons» поставить на 24 часа в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Порезать куриное отварное филе мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Нарезать лук полукольцами, облить кипятком и замариновать в смеси сахара, соли и капли уксуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Светлый изюм промыть, залить на несколько минут кипятком, порубить грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Морковь и сыр натереть на терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Салат из куриного филе «Французская любовница» необходимо выложить слоями: курица, маринованный лук, изюм, морковь, сыр, орехи; каждый слой салата смазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7685,'Салат украшается кубиками апельсина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'Куриную печень промыть, очистить от плёночек, измельчить с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'К измельченной печени влить молоко и растительное масло, вбить яйца, посолить, всыпать муку, все хорошенько перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'На сковороде, разогретой и смазанной маслом, из получившегося печеночного теста испечь лепешки, похожие на блины и обжаренные со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'На терке натереть морковь, порезать полукольцами лук, овощи смешать, посолить и обжарить в районе 5-7 минут до золотистого цвета на растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'Торт выложить следующим образом: лепешку промазать майонезом, выложить на нее слой обжаренных овощей, сверху снова положить смазанную майонезом лепешку, продолжать до тех пор, пока не закончатся лепешки и начинка, последний слой смазать майонезом и украсить петрушкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7686,'Торт из куриной печени с морковью можно подавать к столу, как в холодном, так и в теплом виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'На пряники выложить слой банановых кружочков, следующим слоем опять пряники, повторять выкладывать торт до тех пор, пока последним слоем не окажутся пряники.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'Последний банановый слой (но не пряничный!) посыпать измельченными грецкими орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7687,'На ночь поставить торт из пряников со сметаной без выпечки в холодильник, на следующий день пропитавшийся торт перевернуть на плоское блюдо, снять с него пленку и украсить какао и тертым шоколадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7688,'Разрезать куриное филе пополам, чуть-чуть отбить, поперчить, посолить и полить соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7688,'Взбить сырые яйца, мелко натереть на терке сыр и добавить к взбитым яйцам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7688,'Каждый подготовленный кусок мяса сначала запанировать в муке, потом в сырно-яичном кляре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7688,'Отбивные из курицы в кляре с сыром обжарить со всех сторон до готовности на растительном масле, после чего разложить на бумажном полотенце и дать всему лишнему жиру стечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7689,'Не очень крупными кубиками порезать мясо, сковороду раскалить и быстро обжарить на ней мясо, которое потом разложить по горшочкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7689,'Репчатый лук и морковь помыть и очистить, лук нарезать мелко, морковь порезать соломкой, обжарить овощи на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7689,'Уложить слоем на мясо обжаренные лук и морковь, следующим слоем выложить тонкие колечки маринованных огурцов, заключительным слоем выложить крупные кубики очищенного картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7689,'Во все горшочки влить немного бульона, все полить майонезом и посыпать сверху тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7689,'Жаркое из свинины и картофеля в горшочках запекается при 190 градусах в духовке в течение 50 минут, после чего достается из нее и стоит еще 15 минут, а затем украшается зеленью и подается к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'В чаше миксера смешать молоко, дрожжи и теплую воду, отставить чашу на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Затем в тесто добавить соль, муку, яйца, сахар и на медленной скорости взбивать до полного скрепления теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Размягченное сливочное масло нарезать кубиками и добавить в тесто небольшими порциями, взбить тесто еще раз до однородности, обернуть и убрать на ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'На следующий день раскатать тесто в пласт 1,5 см толщиной, вырезать желаемое количество больших кругов, выложить их на присыпанный мукой противень, закрыть пищевой пленкой и дать подняться в районе 2,5-3 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'После того, как пончики подойду, обжарить их с обеих сторон не больше 2-3 минут в кипящем масле, выложить на застеленное бумажным полотенцем блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Полстакана сахара смешать с лимонной цедрой и обвалять в полученной смеси каждый пончик, отложить остужаться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Для приготовления крема необходимо взбить вместе с сахаром яичные желтки, влить лимонный сок и еще раз взбить до получения однородной консистенции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Емкость с кремом отправить на паровую баню и дать ему загустеть (цвет у крема должен получиться светло-желтым).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Когда крем загустеет, снять его с плиты, постепенно ввести сливочное масло, размешать и убрать крем в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Каждый пончик проткнуть деревянной палочкой, наполнить получившимся кремом при помощи шприца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7690,'Пончики с заварным лимонным кремом можно подавать как порционно, так и на общем блюде.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Очистить и мелко нарезать репчатый лук, обжарить на сковороде до прозрачности, поставить в холодильник для остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Добавить в фарш лук вместе с сырыми яйцами, солью, молотым перцем и мускатным орехом. Всыпать цедру лимона, хлебные крошки, влить растопленное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Массу перемешать и сформовать шарики небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Выложить изделия на противень, поставить в горячую духовку на 15 минут, температура приготовления – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Отдельно разогреть на водяной бане жирные сливки, влить горячий бульон, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Переложить готовые мясные шарики в глубокий противень и полить смесью сливок и бульона. Поставить в духовой шкаф на 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Вбить сырое куриное яйцо, погашенную пищевую соду, можно подлить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7691,'Блюдо достать, соус слить в отдельную мисочку. На сковороде растопить сливочное масло, добавить 2 ст.л. муки, прожарить в течение минуты. Подлить сливочно-бульонный соус, варить на тихом огне до загустения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Картофель помыть и отварить прямо в мундире, петрушку и зеленый лук порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Кубиками нарезать лук репчатый и ветчину, в масле сливочном обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Обжаренный лук и ветчину смешать с тертым сыром, рубленой петрушкой и зеленым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Каждую отваренную до готовности картофелину очистить, разрезать пополам и извлечь мякоть, нарезать ее кубиками, смешать с тертым сыром и ветчиной, осторожно и тщательно перемешать с перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Картофельные половинки нафаршировать получившейся начинкой и соединить, запанировать в муке, потом в яйце, в конце опять в муке, во фритюре обжарить до образования золотой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7692,'Фаршированный ветчиной и сыром картофель в кляре можно подавать как отдельно, так в качестве гарнира.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7693,'Сварить кофе, охладить, всыпать сахар, перемешать, влить ром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7693,'Разлить кофейный пунш с мороженым и ромом по бокалам, положить в каждый мороженое, оформить взбитыми сливками, сразу подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7694,'Взбить размягченное масло с яйцом и сахарной пудрой, положить мед, добавить муку с разрыхлителем (предварительно просеять), специи, имбирь и порошок какао, вымесить упругое тесто, положить его на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7694,'Из охлажденного теста раскатать небольшие шарики, сплюснуть, обсыпать сахарной пудрой, переложить медово-имбирные пряники на противень, выстланный пергаментом, выпекать не более 12 минут при температуре 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7695,'Очистить морковь, измельчить блендером, тушить в прогретой сковороде со 100 мл воды до полной готовности. Почистить яблоки, удалить семена, измельчить в блендере, всыпать к морковке, тушить до мягкости и испарения всей жидкости. Перемолоть в блендере геркулес, добавить мед, чуть муки, подсолить, вымесить тесто вместе с яблоками до однородности, снять с плиты, переложить в другую посуду, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7695,'На плоскую тарелку насыпать панировку из сухарей, сформовать яблочно-морковные оладушки с геркулесом, обвалять, обжарить в разогретом масле с двух сторон до красивой золотистой корочки, подавать блюдо со сметаной или вареньем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7696,'Предварительно разморозить крабовые палочки, вкрутую отварить куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7696,'Очищенный чеснок порубить мелко ножом, очищенные яйца порезать не крупными кубиками, крабовые палочки нарезать небольшими ломтиками поперек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7696,'От кожуры очистить апельсин, разделить его на дольки, которые необходимо очистить от пленочки и порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7696,'Все подготовленные ингредиенты смешать с консервированной кукурузой, заправить  майонезом и осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7696,'Салат из крабовых палочек',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7697,'На дно жаропрочной формы разложить кусочки хлеба, присыпать половиной мелко порубленного укропа, поверх уложить кусочки сыра, прикрыть кусочками хлеба, а потом – сыром, присыпать укропом. Перемешать молоко с яйцами, подсолить, поперчить, полить смесью хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7697,'Форму с сырно-укропной стратой закрыть пленкой, убрать на 8 часов, а лучше на всю ночь, в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7697,'Достать, запекать полчаса в заранее разогретой до 180 градусов духовке, подавать блюдо горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7698,'Отварить до готовности рисовую лапшу, откинуть на дуршлаг, промыть водой. Ананас порезать на кубики, грибы вместе с овощами – соломкой. Раздавить чеснок прессом, имбирь измельчить на самой мелкой терке, мясо порезать тонкими брусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7698,'Разогреть вок, налить масло, прогреть, обжарить быстро мясо, переложить его на бумажное полотенце. В сковороду положить имбирь, чеснок, чуть прогреть, добавить овощи с грибами, довести почти до готовности. Добавить кусочки ананаса, обжарить все вместе еще 3-4 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7698,'Влить лимонный сок, соевый соус, добавить помидоры, протертые сквозь сито и немного сока из банки с ананасами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7718,'Желатин из пакетика залить стаканом холодной воды на полчаса, продукт должен набухнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7698,'Когда овощи будут полностью готовыми, положить в сковороду мясо, лапшу, тщательно и аккуратно перемешать кисло-сладкую телятину, чуть прогреть, переложить на подогретое плоское блюдо и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7699,'Всыпать в чашу блендера подсоленную муку, положить кусочки охлажденного масла, взбить до получения маслянистой крошки, влить кефир, вбить яйцо, добавить воду и уксус, вымесить тесто, убрать его на полчаса-час, завернув предварительно в пленку, в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7699,'Слегка присыпать мукой стол, раскатать основу для галеты диаметром около 40 см. Поместить ее на выстланный пергаментом противень, выложить по всей площади кружочки помидоров, отступив пару см от края для формирования бортика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7699,'Перемешать масло с тимьяном, тертым чесноком, добавить перец, подсолить, равномерно полить помидоры, сделать бортик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7699,'Отправить деревенскую галету с тимьяном, помидорами и моцареллой в прогретую до 200 градусов духовку. Через 20 минут разложить сверху кусочки моцареллы и веточки тимьяна, выпекать 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7700,'Взбить в пышную массу сахарную пудру, масло и сахар. Всыпать ваниль, положить желтки и еще раз взбить. Всыпать муку с солью, замесить на малой скорости тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7700,'Разделить колобок на 2 половины, раскатать колбаски около 5 см в диаметре, длиной примерно 15 см, каждую завернуть в пленку, положить на пару-тройку часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7700,'Тесто достать, порезать на кругляшки, переложить их на противень, выпекать ванильное печенье около четверти часа в духовке с температурой 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7701,'В чашу миксера всыпать сахар, вбить яйца, добавить ванильный сахар, взбить 3 минуты на высокой скорости, влить молоко, продолжить взбивать еще 3 минуты. Добавить масло, муку с разрыхлителем, все вымесить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7701,'Форму выстлать промасленной бумагой для выпечки, заполнить тестом, выпекать полчаса при температуре 180 градусов, дать чуть остыть, вынуть бисквит из формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7701,'В небольшую кастрюльку с толстым дном влить молоко, всыпать сахар, порошок какао, положить кусочки шоколада, размешать, дать закипеть, снять соус с плиты, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7701,'Холодный бисквит разделить на 16 кубиков, предварительно срезав тонкий слой с краев. Каждую сторону кубика подержать в соусе по 15 секунд, дать ему стечь, обвалять нежное бисквитное пирожное в стружке кокоса. Выложить каждое на плоское блюдо, верх еще раз смазать соусом и присыпать стружкой кокоса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7702,'Миндаль залить крутым кипятком, удалить кожуру, дать обсохнуть, измельчить в мелкую пудру с помощью комбайна, перемешать ее с сахарной пудрой, просеять дважды на мелком сите. Добавить к белкам чуть сахара, взбить, пока масса не начнет подниматься, всыпать чайную ложку сахара, взбить, еще добавить сахар и т.д., пока весь не кончится. К полученной меренге добавить краситель желтого цвета и треть миндальной смеси, очень осторожно  все перемешать. Добавить остаток смеси, перемешать до получения однородной массы, наполнить ею пекарский мешок с насадкой диамером в 8 мм.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7702,'Противень выстлать пекарской бумагой, высадить макаруны с расстоянием в 5 см, чтобы они не слиплись, когда начнут подниматься. Смочить палец водой, слегка прихлопнуть верхушку каждого пирожного, дать постоять полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7702,'Поместить на 13 минут в прогретую до 150 градусов духовку, на минуту немного приоткрыть дверцу, а затем открыть и дать выпечке остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7702,'Положить мягкое масло в миксер, добавить сахарную пудру, взбить, постепенно вливая лимонный сок, намазать полученным кремом половину макарунов, прикрыть оставшимися, поставить лимонно-миндальные макаруны на сутки в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7703,'Замесить тесто из размягченного масла, муки и ледяной воды, завернуть в пленку, поместить на полчаса в холодильник, включить духовку, прогреть до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7703,'Для приготовления начинки слегка измельчить блендером мякоть отварной курицы, добавить остальные ингредиенты, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7717,'Смешать овсяную муку, сывороточный протеин, молотую корицу и мускатный орех, поломанный кусочками темный шоколад, разрыхлитель, пищевую соду и любой сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11376,'Овощи обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7703,'Присыпать стол мукой, раскатать тесто в пласт, перенести на скалке в форму, прижать к дну и бортикам, излишки теста срезать. Поставить минут на 5-7 форму в холодильник. Достать, заполнить подготовленнной начинкой, отправить куриный киш с сыром в духовку. Готовить до зарумянивания сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7704,'Для приготовления основы тарта измельчить в крошку печенье, смешать с мягким маслом и какао, заполнить маслянистой массой форму, поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7704,'В чаше миксера взбить сахар, сливочный сыр, творог, яйца, добавить растопленный шоколад, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7704,'В охлажденную форму разложить 1/2 половинок печенья Oreo, полить шоколадной начинкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7704,'Выпекать шоколадно-творожный тарт «Oreo» примерно 45 минут при температуре 170 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7704,'Готовый десерт остудить и поставить на пару-тройку часов, а лучше на ночь, в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'Разогреть сковороду, влить масло, хорошо прогреть, обжарить нашинкованный кубиками лук до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'Добавить укроп, раздавленный прессом чеснок, подсолить, положить нашинкованные грибы, перемешать, прикрыть',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'сковороду крышкой, до тех пор, пока грибы не пустят сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'Убрать крышку, обжарить содержимое сковороды до полного выпаривания жидкости, снять с плиты, дать остыть',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'минут 10-15.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'Взбить яйцо, хорошо перемешать, всыпать муку, смешать до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7705,'Выпекать грибные оладушки с двух сторон до золотисто-соломенного цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Почистить и порезать лук на полукольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Почистить кабачок от кожуры, порезать на кубики. Если кабачок молодой, то кожуру можно не срезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Помыть и порезать на кусочки шампиньоны. Обжарить в мультиварке грибы в режиме «Выпечка». Переложить к шампиньонам кабачок и лук, жарить до мягкого состояния. Овощи с грибами можно обжаривать не в мультиварке, а на сковороде, на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Выложить обжаренные овощи на тарелку. Положить в мультиварку куриную грудку, порезанную на кубики, чуть-чуть потушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Почистить и тонко порезать картофель. Положить в емкость мультиварки, смазанную маслом, картофель, сверху грибную начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Соединить сметану с несколькими ложками воды. Полить начинку сметанной смесью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Почистить и измельчить чеснок, положить к запеканке. Положить еще слой картофеля. Все слои посыпать солью и перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Потереть сыр, посыпать запеканку. Готовить блюдо 50 минут в режиме «Выпечка».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7706,'Подавать картофельную запеканку с грибами и шампиньонами в мультиварке со свежими овощами и зеленым салатом в горячем виде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7707,'Сцедить черные оливки без косточек и зеленые, смешать с фаршированными перцем. Добавить лимонную цедру, перемешать, добавить кубики феты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7707,'Для заправки перемешать до однородной массы столовую ложку лимонного сока с двумя ложками масла. Влить ее к оливкам с фетой, добавить укроп, перемешать. Приправить рыбу смесью чесночного порошка с базиликом и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7707,'Разогреть сковороду-гриль с парой ложек масла, обжарить рыбные стейки с обеих сторон (по 2-3 минуты).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7707,'Разложить сёмгу на гриле и оливковый салат с фетой за 10 минут на подогретую плоскую тарелку и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7708,'Обжарить на масле нашинкованный лук и грибы, посолить, поперчить, перемешать. Всыпать в фарш с луком молотые сухари, добавить натертый сыр, поперчить, посолить, приправить прованскими травами, хорошо все перемешать в однородную массу. Измельчить вяленые помидоры, моцареллу порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7708,'Пластинки бекона разложить на дне формы, концы его должны свисать с краев формы. Уложить на него треть фарша, чуть-чуть утрамбовать, сверху положить моцареллу с вялеными помидорами, слегка придавить ложкой, опять – слой фарша, прикрыть смесью грибов с луком. Завершить остатком фарша, прикрыть свисающей частью ломтиков бекона. Накрыть форму мясной запеканки в беконе с грибами фольгой, отправить в духовку с температурой 200 градусов на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7708,'Осторожно удалить фольгу, дать верху запеканки зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7709,'Удалить с перцев шкурку, срезать донышки, вынуть семена. Заполнить перцы брынзой, начинку сильно не утрамбовывать, окунуть во взбитые яйца, обвалять в молотых сухарях. Обжарить перец, фаршированный брынзой в сильно разогретом масле равномерно со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7709,'К столу подать пока блюдо еще теплое.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7710,'Хорошо промыть рис до прозрачной воды, залить подсоленной водой, сварить до готовности, прикрыв кастрюлю крышкой, на очень слабом огне (30 минут). Порезать очищенное яблоко на дольки, побрызгать соком лайма.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7710,'Обжарить филе курицы в хорошо разогретом масле, поперчить, посолить, присыпать карри, перемешать, влить кокосовое молоко, протушить 7-8 минут при среднем нагреве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7710,'Добавить ломтики яблока, горох, помешивая тушить куриное филе с яблоком еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7710,'Переложить на блюдо рис, тушеное с горохом и яблоком филе курицы, полить соком от обжарки, присыпать измельченнным кешью и зеленым луком. Украсить дольками лайма.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Если у вас сушеные грибы, то их нужно помыть, залить горячей водой, отставить на 60 минут. Снова помыть, порезать. Жарить на масле 25 минут на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Измельчить лук, крупно потереть морковь. Обжарить морковь и лук до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Куриное филе отварить, порезать, положить в основание салата. Намазать мясо майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Потереть вареные яйца, выложить слой. Положить жареную морковь с луком. Намазать слой майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Положить грибы, посыпать мелко потертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7711,'Украсить слоеный салат с жареными грибами, курицей и сыром можно измельченным зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7712,'Порезать все соломкой. Огурец можно крупно потереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7712,'Намазать тарелку майонезом. Положить слой жареных грибов с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7712,'Вторым слоем положить отварную куриную грудку. Намазать майонезом. Положить слой корейской моркови. Слой свежего огурца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7712,'Намазать слоеный салат «Восторг» с грибами и курицей майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7713,'Пожарить с обеих сторон два подходящих по размеру куска семги, по вкусу посыпать приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7713,'Натереть огурец на терке и соединить все ингредиенты для заправки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7713,'Собрать бургер в произвольной последовательности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7713,'Сделать картофель по-деревенски. Порезать на дольки картофель, посыпать перцем, солью. Отправить на 30 минут в духовку. В конце побрызгать оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7713,'Подавать домашний фастфуд из семги можно с любым соком, например, грейпфрутовым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7714,'Снять кожицу с одного хорошо вымытого апельсина. Отжать сок из остальных апельсинов и лимона. Нарезать полукольцами репчатый лук. Куриное филе нарезать кусочками. В сок из цитрусовых добавить острый красный перец, раздавленный чеснок, соль, перемешать вместе с нарезанным луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7714,'Положить филе курицы в полученный маринад, поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7714,'Мясо вынуть, маринад процедить, лук выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7714,'Обжарить филе на растительном масле, подлить маринад и потушить в течение 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7714,'В конце приготовления добавить цедру и йогурт, потушить еще пять-семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7715,'Филе нарезать небольшими кусочками, переложить в чашу блендера. Вбить сырой куриный белок, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7715,'Добавить в массу немного лимонного сока, лимонный перец, соцветия брокколи, измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7715,'Выложить смесь в пароварку, посыпать тертым сыром «Пармезан». Емкость должна быть защищена от попадания воды, её можно закрыть пищевой пленкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7715,'Готовить в пароварке в течение 20 – 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7716,'Взбить сырой яичный белок в густую пену, добавить протеин, разрыхлитель, часть творога. Массу еще раз взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7716,'Часть получившегося творожного теста выложить в формочку из силикона, затем – кусочки черешни, залить оставшейся частью теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7716,'Поставить кекс в духовку на 10 – 15 минут или в микроволновую печь на две-три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7716,'Оставшийся творог смешать с сахарозаменителем и какао-порошком. Массу намазать на уже готовую выпечку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7718,'Смесь поставить на тихий огонь, прогревать до растворения какао, не кипятить. Добавить маложирный творог, перемешать. Превратить продукты в однородную массу с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7718,'Разлить суфле в формы, поставить в холодильник на два часа, можно на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7718,'Перед подачей окунуть дно формочки в кипяток и перевернуть на тарелку, украсить десерт темным тертым шоколадом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Почистить и вымыть картофель, порезать на маленькие кубики. Положить в кастрюлю с водой, варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Порезать на маленькие кубики всю колбасу. Использовать 3 разновидности колбасы: копченную, краковскую, вареную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Порезать соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Почистить и измельчить лук, крупно потереть морковь. Пропустить через пресс или измельчить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Налить в сковороду чуть-чуть растительного масла, обжарить морковь и лук. Когда овощи обжарятся, положить измельченный чеснок, колбасу, соленые огурцы, томат. Потушить 5 минут, время от времени мешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Переложить содержимое сковороды в кастрюлю с картофелем, налить стакан огуречного рассола. Попробовать солянку на соль, если необходимо посыпать перцем, солью. Добавить приправы. Готовить 5 минут. ',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7719,'Выключить солянку с вареной и копченой колбаской, дать настояться 15 минут. Перед подачей украсить солянку оливками и ломтиком лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7720,'В горячем обезжиренном молоке растворить какао-порошок и ванилин. Залить смесью грецкие орехи, оставить на десять минут, затем измельчить с помощью блендера вместе с жидким мёдом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7720,'Массу тонким слоем выложить на тарелку, поставить в морозильную камеру на три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7720,'Готовую сладость нарезать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7721,'Смешать пшеничные отруби с разрыхлителем, какао-порошком, ванилином, сухим молоком, сахарозаменителем на свой вкус. Добавить сырое куриное яйцо, размешать, влить молоко, замесить тесто. Оно должно быть полужидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7721,'Вылить смесь в формочки и запечь до готовности в СВЧ.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'Дрожжи и сахар растворить в теплом молоке, далее вбить 2 яйца и посолить молочную массу, оставить миску в теплом месте максимум на 50 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'По прошествии отведенного времени массу смешать с мукой и замесить тесто, которому дать подойти дважды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'Порубить мелко оставшиеся отваренные вкрутую яйца, нарезать зеленый лук, посолить и слегка растереть, добавить к яйцам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'Посыпать стол мукой, на нее выложить готовое тесто и раскатать его в жгут, который нарезать на куски, из этих кусочков скатать шарики, раскатать их в лепешки, в центр каждой выложить яично-луковую начинку, края каждой лепешки защипать, придать форму пирожка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'Обжарить пирожки с каждой стороны до подрумянивания на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7722,'Готовые жареные пирожки с начинкой из зеленого лука и яйца подать на большом блюде к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7723,'Порезать огурцы на кружки, а маслины на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7723,'Нанизать на зубочистки помидор, кусочек огурца, половину маслины, кубик феты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7723,'Смешать оливковое масло, орегано и черный перец и перед подачей сбрызнуть этим соусом греческие шпажки с сыром фета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Положить в двухлитровую кастрюлю обычный, коричневый и ванильный сахар, сливки, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Поставить кастрюлю на небольшой огонь, опустить кулинарный термометр, варить, пока температура не будет 118 градусов, время от времени помешивать. Это займет 30-35 минут. Масса будет густой и вязкой. Если нет термометра, то можно  пустить две капли кипящей массы в холодную воду. Если капли затвердеют, то карамель можно снимать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Добавить масло и алкоголь. Перемешать и готовить несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Перелить массу в глубокую посуду, застеленную полиэтиленом. Можно использовать конфетные формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Отправить конфеты в холодильник. Когда тягучие ириски остынут, то достать их из форм. Если масса была залита одним шаром, то снять пленку и порезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7724,'Завернуть каждую конфету в пищевую пленку или пергамент, чтобы тягучие ириски с ликером не слиплись.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Когда закипит, сделать огонь тише, посыпать солью. Готовить 20 минут, убрать пену. Чечевица должна стать мягкой, но сохранить форму. Если осталась жидкость, то слить ее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Помыть и порезать на ломтики шампиньоны. Пожарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Помыть и почистить перец, лук, морковь. Нарезать и пожарить на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Добавить несколько ложек соуса ткемали, посыпать перцем и солью, посыпать прованскими травами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7725,'Переложить грибы в сковороду, размешать. Насыпать чечевицу, размешать. Подавать зеленую чечевицу с грибами и соусом ткемали, посыпав зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Нагреть духовку до 225 градусов. Соединить чеснок, масло, специи в маленькой емкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Отдельно соединить йогурт и  пару ложек масла со специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Грудки разрезать на несколько частей, намазать несколькими ложками масла со специями, посолить. Выложить на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Соединить в отдельной емкости помидоры, нут (жидкость из банки предварительно слить) и половину измельченной кинзы. Добавить йогурт, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Положить помидоры, кинзу и нут с йогуртом вокруг куриных грудок. Отправить на 20-30 минут в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7726,'Подавать запеченные куриные грудки с нутом в томатах, посыпав свежей кинзой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7727,'Рыбное филе нарезать брусками, обвалять в муке, яйца взбить и смешать с солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7727,'Сыр измельчить с помощью мелкой терки, перемешать с панировочными сухарями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7727,'Каждый рыбный кусок опустить в яйцо, затем обвалять в панировке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7727,'На смазанный маслом растительным противень выложить рыбные кусочки, запечь рыбные палочки в панировке с сыром в районе 15-20 минут при 230 градусах, подавать с любым соусом, который нравится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7728,'Отбить мясо, положить в посуду, намазать соевым соусом. Оставить мариноваться на ночь или две.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7728,'Обжарить маринованное мясо на кукурузном масле с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7728,'Полить стейки вишнево-клюквенным соусом или подавать его в отдельной маленькой мисочке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Соединить соль с дрожжами (при использовании прессованных свежих дрожжей, взять 50 грамм и растереть с солью). Налить молоко, насыпать сахар, добавить муку, положить размягченное сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Замесить негустое тесто, которое перед разделкой присыпать мукой, чтобы не липло к рукам. Положить его в посуду, отправить в холод на 4 часа. Данное тесто несильно поднимается, но станет пышнее и больше во время приготовления. Тесто можно хранить в холодильнике 3 суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Перед готовкой достать тесто из холодильника, оставить, чтобы оно чуть-чуть нагрелось. Если готовить из теста предполагается через 2-3 дня, то на следующий день следует добавить соду, чтобы оно не стало кислым. Гасить соду не нужно. Это не повлияет на вкус, но тесто можно будет сохранить около 2 суток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Можно выбрать любую начинку, например, грецкие орехи, сухие фрукты, сливочное масло и сахар. Сделать из теста пласт толщиной приблизительно 8 миллиметров, вырезать круги, положить в центр орехи и сухие фрукты, присыпать сахаром, положить маленький кусок масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Защипнуть края, скатать колобки приступить в формовке пирога. Собрать пирог, дать расстояться около 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Намазать разболтанным яичным желтком, готовить, соблюдая температуру 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Чтобы придать пирогу дополнительный блеск, намазать чуть-чуть растопленным сливочным маслом или растительным, используя специальную кисть. Накрыть полотенцем, сложенным пополам, отставить на 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Если у пирога сладкая начинка, то намазать сахарным сиропом, который приготовить из сахара, воды, глюкозы, меда или фруктозы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7729,'Подавать пирог «Гроздь винограда» из хрущевского теста горячим или холодным.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7730,'Клубни картофеля очистить, нарезать кусочками, варить в подсоленной воде в течение 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7730,'Затем добавить в кастрюлю не размороженный зеленый горошек, варить еще столько же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7730,'Воду слить, добавить сырые куриные яйца и размять толкушкой. Всыпать пшеничную муку, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7731,'Взбить вилкой яйца с соевым соусом и солью до однородного состояния, капнуть на сковороду с тефлоновым или аналогичным антипригарным покрытием растительное масло, аккуратно вытереть салфеткой, салфетку не выбрасывать, переложить на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7731,'Вылить 1/4 часть взбитых яиц, снять сковороду и поворачивая в разные стороны равномерно распределить тонким слоем, если появятся пузыри их необходимо проколоть, а нагрев уменьшить, когда омлет достаточно схватится, взять две лопаточки и скрутить его в рулет к противоположной стороне сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7731,'Смазать сковороду промасленной бумагой и налить очередную порцию, приподнять первый рулетик и дать жидкости затечь под него, повторить процедуру со скручиванием, сделать еще два таких рулетика, перевернуть на другую сторону, подрумянить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7731,'Переложить готовый японский омлет-рулетик на доску, нарезать на косые полоски, есть его лучше горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'Нагреть до 175 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'В большой посуде взбить миксером размягченное масло, яйца, ваниль, сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'Отдельно соединить соль, корицу, соду. Потихоньку ввести в яично-масляную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'Перемешать, положить изюм и измельченные орехи. Перемешать до однородности, отправить на 60 минут в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'Положить маленькие порции на противень, застеленный специальной бумагой. Чуть-чуть придавить сверху дном стакана.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7732,'Готовить овсяное печенье с орехами, корицей и изюмом 10 минут. Важно не передержать. Остудить и подавать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7733,'Белокочанную капусту мелко нарезать, залить водой, добавить немного растительного масла, тушить в кастрюле до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7733,'В продолжающую кипеть массу всыпать манку тонкой струйкой, чтобы не образовались комочки. Варить, постоянно помешивая, в течение 10 – 15 минут. Массу немного охладить, досолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7733,'Сформовать небольшие котлеты овальной формы, обвалять в панировочных сухарях, обжарить или запечь, можно приготовить в пароварке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7734,'Для приготовления коржа смешать сырые куриные белки с водой, клетчаткой и стевией по вкусу. Дать массе постоять в течение трех-пяти минут для набухания. Выпечь в духовке или на сухой сковороде в течение пяти-десяти минут при температуре 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7734,'Для приготовления крема смешать протеин, воду и какао-порошок. Масса должна по густоте напоминать сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7734,'Для соуса замороженные ягоды поставить в микроволновую печь на две-три минуты вместе со стевией.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7734,'Протеиновый крем выложить на корж, свернуть рулетом. Сверху выпечку полить ягодным сиропом и поставить в холодильник на несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Растопить на медленном огне сливочное масло с сахаром и сливками. Убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Положить ванилин и стружку кокоса. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Положить смесь в форму, утрамбовать, отправить минимум на два часа в морозилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Достать смесь, порезать на квадраты или небольшие полоски. Снова отправить на несколько часов в морозилку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Растопить шоколад, покрыть им батончики. Покрывать можно разными способами: поливать шоколадом сверху, окунуть в шоколад и так далее. Глазурь высыхает быстро. Положить батончики на фольгу или полиэтилен, чтобы удобно было снимать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7735,'Домашние батончики Баунти со сливками можно украсить по своему вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7736,'Свежие грибы вымыть и нарезать, обжарить на сковороде с антипригарным покрытием, посолить при необходимости. Лисички дадут сок. Когда это произойдет, накрыть блюдо крышкой и тушить на среднем огне до выпаривания жидкости. Затем в течение нескольких минут грибы можно жарить без крышки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7736,'Отдельно взбить сырые куриные яйца, добавить обезжиренный творог, перец и соль – по вкусу. Массу хорошо взбить. Залить готовые грибы полученной яичной смесью, перемешать, распределить по сковороде равномерно и допечь на медленном огне до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7736,'Блюдо снять, дать постоять и подать в теплом виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7737,'Разрезать филе курицы пополам, чуть отбить, сбрызнуть лимонным соком, поперчить, подсолить,  измельчить мелко на терке сыр, взбить яйца, смешать их.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7737,'Запанировать кусочки филе в муке, окунуть в яичную смесь, обжарить до готовности, переложить отбивные из куриного филе в сырном кляре на полотенце из бумаги для удаления излишков масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'Куриную грудку нарезать крупными кубиками, полить оливковым маслом с солью и перцем и дать немного постоять для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'Обжарить мясо до золотистой корочки на сковороде, снять с огня и отставить в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'Репчатый лук и стебель сельдерея нарезать, лук и сладкий болгарский перец двух цветов – полукольцами, сельдерей порубить. Измельчить чеснок. Овощи тушить на оливковом масле в сковороде, до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'Обжаренное мясо и овощи разделить на четыре одинаковые порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'На лист бумаги для выпечки выложить кусочки грудки, посыпать зеленью орегано, сверху – слой овощей. В каждую «порцию» добавить сыр, нарезанный кубиками среднего размера. Края «конверта» завернуть. Положить изделия на противень, смазанный маслом, сбрызнуть водой, печь в течение получаса до тех пор, пока куриное мясо не станет нежным и мягким.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7738,'Готовое блюдо полить небольшим количеством оливкового масла и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7739,'Взбить белки в плотную пену, желтки перемешать, можно обойтись без них. Натереть нежирный сыр, смешать с овсяной мукой, постепенно добавить белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7739,'Противень смазать маслом, выложить тесто ложкой в виде печений. Печь в течение 15 минут при температуре 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Разделить белки и желтки. Растереть желтки и 150 г сахара, положить сметану, мягкое масло, соль, взбивать, пока сахар не растает.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Просеять муку и разрыхлитель. Насыпать в масляную смесь мучную. Вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Отправить 1/4 теста в морозилку. Оставшееся тесто выложить в формочку, распределить, сделать бортики. Отправить тесто в формочкее на 30 минут в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Вырезать в яблоках (лучше использовать сорт яблок Антоновка, но можно и любые кислые) серединки, крупно потереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Вынуть из холодильника формочку, разложить на тесто подготовленные яблоки, можно по желанию присыпать корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Взбить белки, насыпать 150 г сахара, ваниль, взбивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Положить взбитые белки сверху яблок. Достать оставшееся тесто из морозилки, потереть его, разложить по поверхности пирога.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7740,'Готовить сливочно-яблочный пирог с суфле 30-40 минут при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7741,'Корнеплод очистить, натереть на мелкой терке. Желтки отделить от белков, первые взбить до посветления, вторые – в плотную массу со щепоткой соли. Перед взбиванием белки лучше охладить, процесс пойдет быстрее.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7741,'Соединить творожную массу с желтками, тертой морковью, белки добавить в последнюю очередь. Перемешивать смесь аккуратно, движениями снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7741,'Смазать растительным маслом форму для выпечки, выложить творожно-морковную массу, разровнять. Посыпать любыми орехами или кунжутным семенем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7741,'Печь блюдо в духовке в течение 40 минут при температуре 180 градусов. При подаче нарезать запеканку на квадраты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7742,'Белки яиц охладить и взбить в плотную пену вместе с небольшим количеством лимонного сока. Мягкий творог смешать с желтками, сахарным песком, нежирной сметаной и картофельным крахмалом. Последний ингредиент добавить в последнюю очередь. Всыпать ванилин из пакетика. Осторожно вмешать взбитые белки. Масса должна быть жидкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7742,'Выложить смесь в чашу мультиварки, поверхность разровнять, поставить режим «Выпечка». Во время приготовления крышку не открывать, иначе масса осядет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7742,'При готовности блюдо подержать под крышкой в течение часа, затем чашу вынуть и остудить при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7742,'Поставить суфле в холодильник на два часа. Выложить десерт на решетку, а потом переложить на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7742,'Приготовить глазурь из сахара, молока, какао-порошка и сливочного масла. Вылить теплую массу в центр запеканки и поставить в холодильник еще на пять часов или на ночь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7760,'За несколько минут до готовности необходимо добавить в суп с говядиной и гречкой рубленую зелень и измельченный зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Смешать сахар и порошок какао, залить 10 г желатина холодной водой для шоколадного слоя, дать набухнуть, перемешать с сахарной смесью, подогреть до полого растворения желатина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Смазать форму маслом, вылить желатиновую смесь, убрать в морозильную камеру на полчаса для застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Залить стаканом холодного молока оставшиеся 20 г желатина, дать разбухнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Взбить маскарпоне, сметану, сливки, стакан сахара в густую массу, подогреть слегка желатин и вылить в полученную массу, все взбить, оставить остывать на 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Вынуть форму из морозилки, залить белой молочной смесью, дать постоять ночь в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7743,'Достать форму и перевернуть на широкое блюдо, торт «Птичье молоко» по-домашнему без выпечки просто выскользнет из формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7744,'Взбить в миксере или вилкой сгущенное молоко с яйцами, смешать с протертым творогом, изюмом и ванильным сахаром, переложить массу в подготовленную форму, запекать при 160 градусах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7744,'Примерно через час простая запеканка из 3-х ингредиентов будет готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7745,'Включить на разогрев духовку (200-215 градусов), нарезать на дольки вымытый молодой картофель в кожуре, переложить на застеленный бумагой противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7745,'Смешать растительное масло, травы и паприку, кисточкой смазать смесью картофельные дольки, слегка присыпать смесью соли и перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7745,'Запекать на среднем уровне духовки 15 минут, переставить на верхний и выдержать еще 15 минут, если картофель будет сыроват, подержать еще 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7745,'Запеченный пряный картофель в духовке можно приготовить и из старого картофеля, но тогда придется ждать готовности чуть дольше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Довести до кипения 250 мл воды, добавить соль, масло и дать еще раз закипеть, всыпать, помешивая, просеянную муку, тщательно размешать до получения плотного теста, легко отстающего от стенок, включить на разогрев духовку до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Слегка взбить яйца, добавить, постоянно перемешивая, по частям тесто (по 2 ст.л.), должна получиться держащая форму однородная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Застелить противень кондитерской бумагой, чуть смазать маслом, переложить тесто в плотный пакет, отрезать уголок и выдавить на противень небольшие колбаски на расстоянии друг от друга, т.к. тесто сильно поднимается.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Поставить противень на полчаса в духовку, дать, как следует подняться, выключить, 15 минут не вынимать иначе осядут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Пока печется основа сделать нежный и густой крем из взбитого со сливками маскарпоне и сахарной пудры, убрать на холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7746,'Заполнить хорошо остывшую основу кремом из шприца или через разрез сбоку, готовые эклеры домашние со сливочным кремом разложить на блюде, присыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'В кефирно-яичной смеси замочить на 15-20 минут листы лаваша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'С помощью крупной терки натереть сыр, творог и брынзу, все смешать с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'Взять антипригарную форму, смазать ее бортики чайной ложкой растительного масла, застелить не отжатым листом лаваша так, чтобы его края свисали.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'На лаваш выложить 1/2 часть всей сырной массы, накрыть вторым листом лаваша и распределить по нему оставшуюся часть начинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'Слой начинки накрыть последним листом лаваша, свисающие края первого листа завернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'По верхнему слою пирога равномерно распределить оставшуюся яично-кефирную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7747,'Запечь сырный пирог с творогом из лаваша в духовке при 250 градусах до появления румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Замочить булку в небольшом количестве молока, измельчить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Вымыть капустные листья, готовить 5-7 минут в соленой воде, обдать холодной водой, выложить на дуршлаг, чтобы стекла жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Положить в фарш лук, яйцо, отжатую булку, зелень, перец, соль, неострую горчицу. Размешать, положить в огнеупорную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Сформировать каравай, обложить внахлест листьями капусты. Сверху положить полоски бекона. Готовить 45 минут, соблюдая температуру 150-175 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Ополоснуть под холодной водой куриные грудки, насухо их вытереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Сделать соус: нагреть масло в сковороде, поджарить чуть-чуть муку, долить молоко, бульон, довести до кипени, варить 5 минут. Положить половину тертого сыра, подождать, пока он растает. Посыпать перцем, солью, добавить мускат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7748,'Полить рулет сырным соусом, посыпать тертым сыром. Готовить мясной рулет в сливочно-сырном соусе 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'Полукольцами нарезать репчатый лук, помидоры порезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'Филе горбуши смазать солью и перцем, полить лимонным соком, с помощью терки натереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'На подготовленный лист фольги выложить первым слоем небольшое количество лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'Вторым слоем уложить подготовленное рыбное филе, третьим – опять репчатый лук, который необходимо полить чайной ложкой оливкового масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'В завершение нужно положить на луковый слой по два кружка помидора и посыпать их натертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'Перед тем, как отправить рыбу в духовку, следует завернуть края фольги таким образом, чтобы получилась лодочка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7749,'Запеченная в духовке горбуша с сыром и помидорами готовится в течение 20 минут при температуре 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7750,'Куриную грудку порезать порционными кусками, завернуть каждый кусок в пакетик и отбить, затем мясо посолить и посыпать любыми приправами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7750,'Для того, чтобы приготовить кляр, необходимо натереть очищенный картофель на мелкой терке, тщательно отжать весь сок, добавить муку, соль и яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7750,'Каждую отбивную запанировать сначала в муке, а затем окунуть в получившийся кляр и распределить по куску мяса картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7750,'Отбивные из куриных грудок в картофельном кляре обжариваются со всех сторон до подрумянивания на раскаленной сковороде с маслом, при этом огонь должен быть максимальным или чуть-чуть меньше максимального.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'Из молока, муки, соли, растительного масла, сухих дрожжей и сахара замесить тесто, которое нужно укрыть полотенцем, а затем убрать в теплое место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'После того как тесто станет в два раза больше, его следует разделить на 16 частей (около 50 г каждый кусочек), снова накрыть их полотенцем и дать чуть подняться в районе 30 и более минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'С помощью блендера измельчить в однородную массу чеснок, размягченное сливочное масло и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'В середине каждой подошедшей булочки острым лезвием ножа (можно кулинарными ножницами) сделать небольшой надрез и заполнить булочку получившейся чесночной начинкой (1 булка = 1 ч.л. начинки).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'Яичный желток взбить, смазать им начиненные булочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'Противень отправить в духовку на  180 градусов и запекать булочки 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7751,'Готовые чесночные домашние булочки можно подавать с чаем, борщом или бульоном.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7752,'Картофель помыть и очистить от кожуры, разрезать на четвертинки, до готовности отварить в слегка подсоленной воде, после чего слить всю воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7752,'Для приготовления соуса нужно нагреть на сковороде 1 ст.л. сливочного масла, добавить чеснок и влить молоко, готовить в течение 10 минут, а когда чеснок станет мягким, посыпать его мускатным орехом и перемешать, снять соус с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7752,'В кастрюлю к картофелю влить получившийся соус, приготовить картофельное пюре и добавить  в него соль, оставшееся сливочное масло, нарезанный зеленый лук и  перец черный молотый, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7752,'Полученное картофельное пюре с чесноком и зеленым луком смешать со сметаной, тертым сыром и крем-фрешем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7753,'Для приготовления соуса смешать сметану, соль, горчицу, молотый перец и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7753,'Полукольцами нарезать репчатый лук, соломкой порезать красный и желтый перец, нашинковать китайскую капусту и зеленый лук, кубиками нарезать филе курицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7753,'Сложить подготовленные продукты в миску, перемешать, полить салат с куриным филе, пекинской капустой и перцем полученной заправкой и украсить измельченным зеленым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'От кожуры очистить кабачки, извлечь все семечки, порезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'Потереть на крупной терке морковь, помидоры и чеснок  мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11413,'Затем говядину вынуть, нарезать, подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'В глубокую сковороду влить столовую ложку растительного масла, выложить морковь и кабачки, залить овощи 1/2 стакана воды, сковороду закрыть крышкой, затем поставить ее на средний огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'После того как кабачки станут мягкими нужно добавить еще 2 ложки масла и нарезанные помидоры, по вкусу посолить и тщательно все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'Не накрывая крышкой, потушить еще пару минут, затем положить подготовленный чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7754,'Подается икра из кабачков домашнего приготовления украшенной рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7755,'Смешать творог, сахар, яйца и сметану так, чтобы получилась однородная масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7755,'По дну формы для запекания разложить очищенные и нарезанные яблоки и бананы, сверху вылить на них получившуюся творожную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7755,'Поставить форму в духовой шкаф, разогретый до температуры в 200 градусов, все выпекать не меньше одного часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7755,'По прошествии одного часа духовку следует выключить, но в течение 10 минут запеканка из творога с яблоком и бананом должна еще постоять в духовке с закрытой дверцей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7756,'Нарезать на стейки (толщина каждого должна быть полтора-два сантиметра) рыбу, каждый кусок с каждой стороны натереть перцем и солью, одну сторону сбрызнуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7756,'Застелить фольгой дно формы, выложить на фольгу сбрызнутой стороной филе, смазать рыбу майонезом, а сверху посыпать мелко натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7756,'Горбуша под сыром выпекается на протяжении 40 минут в духовке при 180 градусах, пока не зарумянится сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'За 2 часа до начала готовки достать из холодильника масло, чтобы оно при комнатной температуре подтаяло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Из муки, сахара, соды, сметаны и подтаявшего масла необходимо замесить пластично-эластичное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Из приготовленного теста сформовать толстые колбаски около 10 см в длину, завернуть их в полиэтиленовый пакет, положить на 20 минут в морозилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Для начинки нужно смешать творог, сахар и сметану, кружочками порезать бананы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Натереть на крупной терке подмерзшее тесто, смазать форму маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'На дно выложить первым слоем 2/3 всего теста, вторым слоем распределить равномерно творожную массу, оставив по краям по 1 сантиметру без начинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Третьим слоем выложить банановые кружки, на них последним слоем уложить оставшееся тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Фому отправить в духовку на 40 минут при 200 градусах.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'В кастрюле закипятить воду, добавить дольки лимона, сахар и базилик, дать опять  закипеть, а затем выключить огонь и оставить напиток настаиваться под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Чтобы напиток не получился горьковатым, через 15 минут необходимо достать из него все лимонные дольки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7757,'Готовый пирог остудить в течение 1-1,5 часов, затем нарезать и подать творожно-банановые пирожные с напитком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7758,'Смешать муку (1/4 стакана оставить), соль, соду и лимонную цедру, с помощью миксера в течение 3 минут взбить до воздушного состояния сахар со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7758,'Далее, продолжая взбивать, постепенно вбить яйца, влить лимонный сок, йогурт и молоко, не спеша всыпать муку и ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7758,'Клубнику нарезать и смешать с оставшейся мукой, после чего полученную смесь добавить в тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7758,'В смазанную сливочным маслом форму влить тесто, и поставить ее в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7758,'Выпечь кекс клубничный на йогурте при 160 градусах на протяжении 1 часа, затем дать полностью остыть, достать из формы, украсить сахарной пудрой, подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'В горшочек положить порезанный кубиками картофель и фрикадельки, слегка посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'Сверху выложить обжаренные с луком грибы, влить разведенную с водой сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'Горшочек на 3/4 наполнить водой, добавить еще немного соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'Горшок поставить в не разогретую духовку, настроить температуру градусов на 180-200, и готовить блюдо 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'Через 40 минут посыпать грибы тертым сыром, продолжить готовить еще 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7759,'Готовые фрикадельки с грибами и картофелем под сыром перед подачей можно украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Взбить в кремообразную массу сливочное масло, добавить простой и ванильный сахар и продолжить взбивать, когда масса станет больше и посветлеет – остановиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Добавить все яйца по одному, перемешивая хорошенько тесто каждый раз, и сметану, тесто еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Смешать с мукой разрыхлитель, просеять через сито, пересыпать в тесто и тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Поделить полученное тесто на две части, затем в одну из которых просеять какао и хорошенько перемешать, чтобы не было комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'В смазанную сливочным маслом форму для кекса выложить подготовленное тесто слоями: один слой – столовая ложка белого теста, второй слой – столовая ложка шоколадного теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Форму отправить в духовку и выпекать мраморный кекс в духовке при 180 градусах 50 минут, проверить готовность кекса спичкой или зубочисткой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7761,'Готовый кекс необходимо остудить, а при желании полить шоколадной глазурью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7762,'Сахар и яйца взбить в пену, добавить к ним массу из размягченного сливочного масла и творога, все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7762,'Добавить ванилин и разрыхлитель и снова тщательно перемешать, всыпать муку и вымесить тесто',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7762,'В получившуюся массу добавить нарезанный на небольшие кусочки банан, все еще раз перемешать .',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7762,'Далее подготовленным тестом наполнить силиконовые формочки, смазанные сливочным маслом, поставить их в разогретый до 160-180 градусов духовой шкаф и выпекать на протяжении 35 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7762,'Готовые маффины из творога с бананом подавать с йогуртом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Масло сливочное растопить в сковороде, в течение 3-4 минут обжарить в нем порезанный бекон, а затем добавить репчатый мелко нарезанный  лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Далее добавить порезанные яблоки, по истечении 3 минут снять сковороду с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Всыпать апельсиновую цедру и панировочные сухари, все перемешать,  добавить перец и соль, дать получившейся массе полностью остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'На сырое индюшачье мясо выложить остывшую начинку, скрутить рулет, положить его в емкость для запекания, смазать солью, перцем и сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Отправить форму с рулетом в разогретую духовку, запекать блюдо на протяжении 2,5 часов при температуре в 190 градусов (если вдруг кожица слишком быстро становится коричневой, рулет можно обернуть фольгой), пока температура мяса не станет 70 градусов по термометру для мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Кленовый сироп смешать с апельсиновым соком, получившимся соусом необходимо время от времени поливать рулет, по истечении отведенного времени индейку достать из духовки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7763,'Далее необходимо проверить температуру мяса (70 градусов), оставшимся соусом смазать рулет из индейки фаршированный беконом и яблоками и поставить на 20 минут  обратно в духовку, после чего образовавшимся во время запекания от мяса соком полить разрезанную индейку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'В небольшой мисочке смешать разрыхлитель, соду, соль и муку, отставить емкость в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'Взять большую миску, взбить в ней миксером на маленькой скорости 200 г сахара со сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'Добавить в массу ваниль, вбить яйца, все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'В три подхода, не торопясь, всыпать в большую миску (с взбитой массой) кислое молоко и мучную смесь следующим образом: сначала мука, потом молоко, снова мука, затем опять молоко и так до конца, пока последней не будет всыпана мука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'После того, как все ингредиенты окажутся в большой миске, тесто необходимо тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'Готовое тесто нужно распределить по всему противню, сверху равномерным слоем выложить свежую малину, и посыпать все 2 ст.л. сахара.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'Противень отправить в предварительно разогретую духовку, выпекать пирог с малиной на кислом молоке при 180 градусах до образования золотистой корочки в районе 35-40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'Готовность пирога следует проверить зубочисткой или деревянной шпажкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7764,'После того, как пирог будет готов, необходимо оставить его в выключенной и закрытой духовке еще на 10 минут, а затем подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Затем отбитое мясо разрезать на одинаковые по ширине тонкие полоски, слегка присыпать их солью и отставить на несколько минут в сторону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Далее взять три мисочки или тарелочки: в первой смешать муку, соль и перец, во второй чуть-чуть взбить яйца, а в третью насыпать панировочные сухари.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Каждый кусочек мяса сначала запанировать в муке, потом в яйце, и в конце в сухарях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Сковороду с растительным маслом разогреть на среднем огне, выложить куриные палочки, обжарить их со всех сторон на протяжении 2-3 минут, снять с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7765,'Готовые хрустящие куриные палочки в панировочных сухарях можно подавать как на общем блюде, так и порционно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7766,'Готовое слоеное тесто развернуть, чуть раскатать и нарезать на длинные полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7766,'На каждую полосочку теста выложить предварительно натертый сыр, скрутить полоску, приподнимая каждый край к центру, осторожно скрепить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7766,'На дно противня постелить лист бумаги для выпечки, смазать его растительным маслом, начиная от центра по порядку выкладывать «колбаски», скрепляя их между собой, в результате должна получиться «улитка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7766,'Верх «улитки» необходимо смазать яичным желтком, затем посыпать кунжутными семечками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7766,'Сырный пирог с кунжутом из слоеного теста готовится в разогретой духовке до подрумянивания в районе 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Кочан свежей капусты хорошенько промыть, очистить, разрезать пополам и мелко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Репчатый лук очистить и, также как капусту, мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'В сковороде разогреть на среднем огне оливковое масло, затем в течение 2 минут поджарить на нем, периодически помешивая, лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Далее к луку добавить нашинкованную капусту, соль и перец, перемешать и потушить все 15-20 минут, при этом все время помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Взять небольшую кастрюлю, влить туда сметану и слегка подогреть (не варить!!!) ее на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'На терке натереть сыр и 1/2 его часть добавить в сметану, туда же выдавить чеснок и все перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Когда сметанный соус будет готов, его нужно перелить к капусте, тщательно все перемешать и убрать с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Далее следует приготовить из воды, перца, яиц, паприки и соли смесь для будущего омлета, готовой смеси хватает на приготовление 3-х порций омлета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'В большой сковородке на разогретом растительном масле испечь омлет, готовится он в течение 5 минут, переворачивать его не нужно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Когда омлет прожарится, на одну его половину необходимо выложить 1/3 часть капустной начинки, после чего начинку надо закрыть второй половиной омлета.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7767,'Снять омлет с сыром и капустной начинкой с огня, посыпать петрушкой и оставшейся частью тертого сыра.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Куриное мясо отварить до готовности, полностью остудить и порезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Огурцы и листья салата также мелко нарезать, натереть сыр на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Первым слоем на дно стакана или салатника выложить куриное мясо, немного смазать его майонезом, но не стоит мясо придавливать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Вторым слоем выложить огурцы, снова немного майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Третий слой – тертый сыр, также чуть промазанный майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Последним слоем должны быть листья салата, их не нужно смазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7768,'Сверху можно украсить салат из курицы с сыром маслинами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Куриные ножки хорошо промыть, удалить с них всю кожу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Взбить яйцо, кетчуп и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Любым удобным способом измельчить арахис, переложить его в тарелку или полиэтиленовый пакетик, добавить специи и панировочные сухари, все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Далее необходимо запанировать каждую куриную ножку в подготовленном яйце, потом в сухарях, а в конце полностью покрыть ножку подготовленной сухой смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7769,'Когда ножки будут полностью запанированы, их нужно поджарить в течение получаса на раскаленной (190 градусов) сковороде с растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Измельчить продукт с помощью блендера и оставить в холодильнике на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Готовым коржам дать полностью остыть, один из коржей (по желанию) разрезать вдоль на две равные части – это станет основой будущего торта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Основу положить на блюдо, вторую половину коржа порезать на кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Второй корж, который не был выбран для основы, необходимо также порезать небольшими кусочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Все кусочки сложить в миску, добавить к ним не мелко нарезанные бананы, влить весь йогурт и хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'На корж-основу выложить получившуюся массу, утрамбовать и придать форму купола.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Верх торта полить банановым йогуртом, который можно заменить натуральным йогуртом, смешанным с сахарной пудрой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Поставить торт на несколько часов, а лучше всего на всю ночь, в холодильник, чтобы он полностью пропитался.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7770,'Украсить торт «Панчо» с йогуртом и бананами можно следующим образом (по желанию): шоколад растопить с растительным маслом, бананы разрезать вдоль на 2-3 части, одну сторону смазать шоколадной глазурью и приложить к торту; в конце поверхность торта полить оставшейся глазурью и посыпать орехами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7771,'Отварить до готовности рис, дать ему остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7771,'Мелкими кубиками порезать свежие огурцы, измельчить зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7771,'Рис перемешать с соком от рыбы, добавить в него лук и огурцы, все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7771,'Рыбу очистить от крупных костей и размять вилкой, после чего добавить ее к остальным ингредиентам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7771,'Простой салат из рыбы, риса и огурцов посолить, поперчить, заправить майонезом (достаточно трех столовых ложек), хорошо перемешать и на 1 час поставить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Мелкими кубиками порезать лук, чеснок пропустить через чесночницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'В сковороде разогреть растительное масло и на протяжении 5-8 минут обжарить лук и чеснок, они должны приобрести легкую золотистость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Через 8 минут к чесноку и луку добавить измельченную колбасу, периодически помешивая обжарить все вместе 5-7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'На мелкой терке натереть очищенные кабачки, отжать весь сок и переложить в сковороду, при необходимости долить небольшое количество масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Тушить все на среднем огне до тех пор, пока жидкость полностью не испарится, после чего снять сковороду с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Кипятком ошпарить помидоры, снять кожицу, натереть их на крупной терке, и любым удобным способом слить весь сок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Мелко натереть сыр, укроп и зеленый лук измельчить, слегка взбить вилкой яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Все подготовленные продукты смешать, добавить отваренный без соли, промытый и откинутый на дуршлаг рис, 100 г сыра, сметану, специи, хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Смазать небольшим количеством растительного масла форму, переложить в нее готовую овощную массу, разравняв верх с помощью ложки и присыпав оставшейся частью тертого сыра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Форму отправить в предварительно разогретую до 160 градусов духовку, выпекать блюдо не меньше 1 часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7772,'Овощная запеканка с рисом и сыром по-французски будет полностью готова, когда сыр хорошо зарумянится.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7773,'Крабовое мясо измельчить с помощью блендера (можно порвать руками на мелкие кусочки).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7773,'Крупно натереть небольшой молодой кабачок на терке, отжать весь сок и посолить, мелко натереть небольшую морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7773,'К подготовленным ингредиентам добавить яйцо, измельченные петрушку, укроп и зеленый лук, молотый перец, крахмал и сладкий соус чили, тщательно все перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7773,'Из получившейся массы сформировать котлеты небольшого размера (при желании запанировать в сухарях) и выложить на предварительно разогретую сковородку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7773,'Котлеты из крабового мяса с морковью и кабачками необходимо с каждой стороны обжарить по 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'Молодые кабачки тщательно промыть и вместе с кожицей потереть на средней терке (если кабачки зрелые, их нужно почистить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'Весь лишний сок слить, добавить муку, соль, яйцо и все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Готовый, выпеченный бисквит разрезать на части, пропитать крепким, заваренным кофе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'На среднем огне в сковородке с антипригарным покрытием разогреть растительное масло, выложить ложкой получившееся жидкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'С обеих сторон оладьи обжарить, после чего выложить на тарелку с бумажной салфеткой, чтобы весь лишний жир впитался в бумагу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'Для приготовления соуса нужно смешать натуральный йогурт, чеснок, пропущенный через пресс, и измельченную зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7774,'Подать зеленые оладьи из кабачков с йогуртовым соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7775,'Яблоки помыть и очистить от кожуры, порезать ломтиками и прогреть на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7775,'На крупной терке натереть промытую и очищенную морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7775,'Взбить яйца, при этом необходимо постепенно вливать молоко, затем посолить и добавить корицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7775,'На дно формы выложить подготовленные яблоки, на них – слой тертой моркови, которую нужно залить молочно-яичной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7775,'Поместить форму в духовой шкаф и запекать омлет с морковью и яблоком при 180 градусах в районе 15-20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7776,'С каждого вымытого и обсушенного помидора срезать верхушку и осторожно извлечь всю мякоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7776,'Полученные «емкости» поперчить, посолить, промазать маслом, вбить по яйцу таким образом, чтобы желток не повредился, добавить еще немного соли и перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7776,'Подготовленные помидоры поместить в сковороду или форму, смазанную маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7776,'Яичница с зеленью в помидорах запекается в духовом шкафу при 180 градусах в течение 20-25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7776,'Прежде, чем подавать блюдо к столу, его нужно украсить рубленой зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'Обжарить на сливочном масле нарезанные грибы, измельчить 1 морковь и 1 головку репчатого лука, с двух обданных кипятком помидоров снять кожицу и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'До полуготовности отварить промытый и очищенный рис, пассировать морковь, помидоры, лук на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'В емкости смешать отваренный рис, пассированные овощи, обжаренные грибы, рубленый базилик, соль, зелень, молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'Из перцев удалить семена, получившиеся «горшочки» нафаршировать подготовленной начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'Для приготовления зажарки нужно на растительном масле снова пассировать оставшиеся помидоры, морковь и лук, затем добавить к ним томатный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'В казанок или толстодонную кастрюлю уложить подготовленные перцы, залить готовой зажаркой, сверху посыпать измельченной зеленью',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7777,'На маленьком огне на протяжении 30-40 минут тушить перец, фаршированный грибами, рисом и морковью, либо в духовке, либо на плите.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7778,'На тонкие пластинки нарезать вдоль куриное филе, каждую пластинку положить в целлофановый пакетик и отбить молоточком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7778,'Взбить в отдельной мисочке яйца, добавить нашинкованную пекинскую капусту и соль, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7778,'В заранее смазанную маслом форму уложить мясные пластинки, залить их яично-капустной смесью, запечь в духовке в районе 20 минут при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7778,'Перед подачей запеченное куриное филе с пекинской капустой и яйцом украсить зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Мелко нарезать немного отбитое филе курицы, репчатый лук мелко нашинковать, яйцо взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Далее в миску сложить мясо и лук, влить яйцо, поперчит, посолить и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Из получившейся массы сформовать небольшой величины шарики, уложить их в форму, предварительно смазанную жирными сливками, запекать 10-15 минут при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Для приготовления заливки необходимо смешать со сливками мелко натертый сыр и пропущенный через пресс чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Из духовки вынуть форму, каждый шарик полить получившейся заправкой, поставить форму обратно еще на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7779,'Готовые шарики из куриного филе в сливочно-сырном соусе подойдут как для праздничного стола, так и для ежедневного.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'С помощью блендера измельчить печенье в мелкую крошку, растопить сливочное масло и смешать с печеньем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Почистить лук и мелко нарезать, после чего его следует поджарить на жире до корочки золотистого цвета, мясо нарезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'На дно разъемной формы постелить лист пекарской бумаги, уложить масляную массу, разровнять и чуть прижать ладонями, поставить форму на 30-40 минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'В сливках замочить желатин и оставить набухать, а спустя полчаса полностью растворить (не кипятить!), помешивая, на водяной бане, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'Для крема смешать йогурт, сахар, творожный сыр, ванилин и сок лимона, добавить разбухший и остывший желатин, тщательно все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'На застывший корж ровным слоем выложить получившийся крем, снова убрать форму в холодильник на 2 часа, чтобы застыл крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7780,'Затем украсить торт йогуртовый с печеньем и вишней без выпечки половинками вишенок и залить теплым желе, после чего поставить в холодильник и дать застыть окончательно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Для того чтобы замесить гладкое тесто необходимо: сперва смешать муку, яичные желтки, дрожжи, разрыхлитель и сахар, затем добавить мягкое сливочное масло, молоко и воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Далее нужно завернуть получившееся тесто в пищевую пленку или целлофан и на 20 минут отложить в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Смешать для начинки сахар с измельченными орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'На листе пекарской бумаги начертить квадрат (размер — 30х30 см), тесто разделить на 3 одинаковые части, по шаблону раскатать 3 квадратных листа из теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Дно противня устелить листом пекарской бумагой, уложить первый корж, смазать его абрикосовым вареньем, посыпать сверху подготовленной начинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Накрыть начинку вторым коржом, его также смазать вареньем и посыпать орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Второй корж накрыть третьим, всю поверхность которого наколоть вилкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'В заранее разогретую до 170 градусов духовку поместить противень с коржами, выпекать все в течение 50 минут, затем вынуть и полностью остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Для глазури надо растопить шоколад вместе со сливками и маслом на водяной бане, мешать пока глазурь не станет гладкой, после чего поверхность пирога равномерно залить получившимся кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7781,'Как только глазурь схватится, необходимо при помощи горячего ножа нарезать венгерское абрикосовое пирожное «Жербо» с орехами на части.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7782,'Для начинки необходимо мелко порубить сладкий перец, петрушку и укроп, на терке натереть сыр, все смешать и посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7782,'Филе куриных грудок тщательно отбить, обмазать каждое майонезом, на 40 минут убрать в сторону, после чего слегка посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7782,'Подготовленную начинку равномерно распределить по каждой грудке, свернуть каждый кусок мяса в рулет, который затем завернуть в фольгу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7782,'В районе 40 минут запечь рулетики при 180 градусах, по прошествии отведенного времени развернуть фольгу, посыпать мясо кунжутом, отправить противень обратно в духовку еще на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7782,'Куриные рулетики в кунжуте с сыром и перцем перед подачей разрезаются на 4 части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7783,'Очень мелкими кубиками нарезать филе курицы, с помощью крупной терки натереть сыр, добавить небольшое количество майонеза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7783,'Подготовленные ингредиенты сложить в емкость, посолить и поперчить, добавить приправу по вкусу и хорошо перемешать все руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7783,'Из получившейся массы сделать котлеты, запанировать каждую в сухарях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7783,'Котлеты из рубленного мяса курицы с сыром обжарить до образования золотистой корочки в растительном масле на сковороде, подавать с гарниром или салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'Нарезать соломкой копченую куриную грудку, на мелкой терке натереть яичные желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'В кипятке на несколько минут замочить чернослив, после чего, как и курицу, нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'Шампиньоны порезать кусочками, обжарить с нашинкованным репчатым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'Свежий огурец помыть, обсушить и нашинковать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'В любую форму, миску или салатник выложить салат из копченой курицы с грибами и черносливом слоями, каждый из которых нужно промазать майонезом:',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'слой первый – мясо,',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'слой второй – желтки,',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'слой третий – чернослив,',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7784,'В конце украсить салат следующим образом: тремя мелко натертыми яичными белками выложить одну половину поверх мясного слоя, вторую половину выложить такими же белками, только сначала их нужно пару минут прокипятить в крепком чае, между светлой и темной частями выложить разделительную полоску из измельченных маслин.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7785,'Взбить вместе сырые куриные яйца, сахарный песок и молоко. Добавить в смесь зернышки ванили из стручка, подлить апельсиновый ликер и все хорошо взбить.','https:https://st.vkuso.ru/data/cache/thumb/4f/c8f5a997000d24f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7785,'Сдобную булку нарезать, окунуть в яичную смесь и дать пропитаться.','https:https://st.vkuso.ru/data/cache/thumb/7a/6e6509778a9d77a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7785,'Большую сковороду прогреть на огне средней мощности, добавить сливочное масло. Выложить тосты на горячую сковороду, жарить на среднем огне по две минуты с каждой стороны, должна получиться румяная корочка.','https:https://st.vkuso.ru/data/cache/thumb/bf/60fe47b7f708bbf_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7785,'Готовые изделия выложить на сервировочные тарелки, хорошо полить жидким натуральным мёдом, присыпать сахарной пудрой, добавить нарезанные фрукты или свежие ягоды, украсить листочками мяты.','https:https://st.vkuso.ru/data/cache/thumb/50/034ab1b8a0e3b50_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7786,'К сыру, натертому на мелкой терке, добавить желтки, взбитые с молоком, сахар, соль и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7786,'Взбить в отдельной емкости яичные белки, добавить их в сырное тесто и все тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7786,'На сковороде хорошо разогреть сливочное масло и пожарить в нем сладкие сырные блины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7787,'Хлеб обжарить на сковороде и смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7787,'На каждый кусочек выложить ветчину, ананас и сыр и отправить на 1-2 минуты в микроволновку',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Неочищенный от шелухи чеснок обжарить на среднем огне на сковороде без масла. Через 10 – 15 минут продукт должен стать мягким и почернеть в нескольких местах. Снять сковороду с огня, дать чесноку остыть.','https:https://st.vkuso.ru/data/cache/thumb/43/ae581834fdc8c43_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Нарезать не кусочки среднего размера красный сладкий болгарский перец, большой огурец без семян, спелые помидоры без кожицы.','https:https://st.vkuso.ru/data/cache/thumb/c7/1c6e8271a4c83c7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Остывший чеснок очистить.','https:https://st.vkuso.ru/data/cache/thumb/61/d7de8235faeff61_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Чеснок и помидоры добавить в кухонный комбайн, перемолоть в пюре. Готовую смесь переложить в миску.','https:https://st.vkuso.ru/data/cache/thumb/28/a21ee18b1d32128_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Затем измельчить перец и огурцы, не в пюре, должны сохраниться мелкие кусочки.','https:https://st.vkuso.ru/data/cache/thumb/e2/e9f9d2640ef79e2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7788,'Все ингредиенты перемешать, залить томатным соком, добавить специи, красный винный уксус и соус «Табаско». Подать блюдо охлажденным с домашними сухариками или гренками, рублеными отваренными яйцами и кусочками мякоти авокадо.','https:https://st.vkuso.ru/data/cache/thumb/cf/c04b3d53637d2cf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7789,'Чтобы приготовить тесто необходимо смешать молоко, сахар, яйца, соль и муку, вымешивать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7789,'На средний огонь поставить сковородку, влить и разогреть растительное масло, пожарить в нем блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7789,'Обжарить с нашинкованным репчатым луком мясной фарш, добавить перец и соль по вкусу, после чего перекрутить все на мясорубке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7789,'В каждый готовый блин завернуть получившуюся начинку, обжарить на растительном масле блинчики домашние с мясной начинкой со всех сторон, к столу подавать со сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7790,'Свежие или размороженные шампиньоны или опята нарезать и обжарить в сковороде на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7790,'Очистить и нарезать репчатый лук, добавить его в грибы, прогревать вместе до готовности, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7790,'Белки отделить от желтков, первые взбить с помощью миксера, вторые размять. То и другое соединить, подлить молоко, посолить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7790,'Залить готовой смесью луково-грибную обжарку, прогреть в течение трех-пяти минут на среднем огне, накрыть крышкой еще на одну минуту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7790,'Натереть на мелкой терке твердый сыр, вымыть немного зелени укропа, измельчить. Готовое блюдо посыпать сверху зеленью и сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'В зажарку добавить молотый красный перец и подготовленное мясо, закрыть крышкой и оставить тушиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Чеснок потереть на мелкой терке или пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Куриное филе нарезать и немного отбить. Сформовать котлету: кусочки мяса сложить стопкой, завернуть в пищевую пленку и отбить молотком. Приправить филе чесночной солью по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/cb/56acf604211becb_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Взбить сырые куриные яйца. Мясо обвалять в муке, окунуть в яичную смесь, запанировать в сухарях.','https:https://st.vkuso.ru/data/cache/thumb/0c/658a9684cace70c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Нарезать зелень салата и крупный помидор. Для заправки перемешать майонез, столовую горчицу, соус «жидкий дым» и щепоть чесночной соли.','https:https://st.vkuso.ru/data/cache/thumb/28/54130688ac6b928_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Котлеты в панировке обжарить с двух сторон до золотистой корочки, допечь в духовом шкафу при температуре 180 градусов в течение пяти или десяти минут до готовности.','https:https://st.vkuso.ru/data/cache/thumb/e2/701884031984ae2_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Отдельно обжарить бекон и приготовить яичницу-глазунью.','https:https://st.vkuso.ru/data/cache/thumb/a0/6b4e58f1a24d6a0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7791,'Чиабатту разрезать поперек на две половины. Каждую половину – продольно на две части, смазать приготовленным майонезным соусом. На одну половину выложить зелень салата и помидоры, сверху – ломтик твердого сыра, куриную котлету, еще раз смазать соусом. Следующие слои – бекон, сыр, яичница. Все ингредиенты накрыть второй половиной чиабатты. Чикенбургер из чиабатты по фирменному рецепту прогреть в СВЧ и подать на стол.','https:https://st.vkuso.ru/data/cache/thumb/05/1e8fa05bfb55205_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Сперва нужно для рулетов со сладким перцем приготовить начинку: смешать горчицу, майонез, рубленый укроп, соль и молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Затем приготовить начинку для рыбных рулетов: в миску выложить сливочный сыр, добавить к нему рубленый укроп, майонез, мелко натертую лимонную цедру, влить сок лимона и все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Промытые перцы порезать на две равные части, вынуть сердцевину, уложить на противень, спрыснуть растительным маслом и запекать 20 минут при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Затем переложить перцы в миску, закрыть пищевой пленкой и отставить на 10 минут, после чего с перцев снять кожуру и нарезать мякоть соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Смазать один тонкий лаваш горчичной начинкой и выложить сверху нашинкованные перцы и ломтики ветчины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Сырной начинкой смазать второй лаваш, сверху выложить тонкие пластинки слабосоленой рыбы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Каждый лаваш свернуть в рулет и нарезать на роллы шириной в 2-3 см.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7792,'Подавать роллы из лаваша с красной рыбой и ветчиной можно либо порционно, либо на общем блюде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7793,'Соединить в глубокой посуде яйца, соль и сахар.','https:https://st.vkuso.ru/data/cache/thumb/af/d4aa9b2204233af_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7793,'Взбивать миксером, пока не получится смесь светло-желтого цвета. Аккуратно ввести в яичную смесь ванилин, муку и соду. Осторожно перемешать, медленно взбить миксером. Должно получиться тесто, как густая сметана.','https:https://st.vkuso.ru/data/cache/thumb/47/b264fbea3817747_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7793,'Намазать форму сливочным маслом, посыпать специальными сухарями.','https:https://st.vkuso.ru/data/cache/thumb/72/5d774fc2c447f72_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7793,'Вылить в форму ½ теста. Выложить ягоды, посыпать сахаром. Залить вишню оставшимся тестом.','https:https://st.vkuso.ru/data/cache/thumb/ff/d3c82e527e6baff_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7793,'Готовить 45 минут при температуре 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/a1/4c183fe096ef0a1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7794,'В кастрюлю с толстым дном насыпать сахарный песок, влить воду. Сироп помешивать, довести до кипения, подержать на огне две-три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7794,'Влить молоко тонкой струйкой, довести все вместе до кипения, варить на тихом огне до загустения массы, периодически помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7794,'Всыпать через сито какао-порошок, перемешать до однородного состояния. Дать покипеть минуту, огонь выключить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Порезать фрукты, убирая косточки и обрезая подпорченные места.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Вымыть. Переложить в эмалированную емкость, налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Закипятить, процедить. Горячий сок налить в банки, закатать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Убрать кожуру из массы, которая осталась. Насыпать сахар. Получается густая смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Вылить ее тоненьким слоем на доску, смазанную маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Оставить на солнце на день, чтобы масса засохла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7795,'Обрезать ножом края, перевернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11435,'Продукт остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Как только жидкость выкипит смешать чеснок с тмином, добавить к мясу и подлить небольшое количество воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Тушить на слабом огне 20-25 минут, помешивая, и доливая немного воды, если требуется, чтобы мясо тушилось, а не варилось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Почистить картофель и нарезать мелкими кубиками, отправить его к мясу в сковородку и тушить еще 15-20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Мелко порезать помидор и сладкий перец и добавить в блюдо на огне, добавить мясной бульон и домашнюю или готовую лапшу и дать ей свариться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7796,'Суп-гуляш из говядины с картофелем по-закарпатски подаётся горячим, по желанию может быть добавлена сметана, майонез или зелень прямо в тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Мелко порезать крабовые палочки. Почистить чеснок от оболочки, мелко потереть. Крупно потереть сыр, положить в емкость, добавить чеснок. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Вымыть и обсушить укроп. Измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Разрезать лаваш на 4 одинаковых прямоугольника.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Один кусок лаваша намазать плавленым сыром, присыпать зеленью. Положить сверху крабовые палочки. Накрыть вторым кусочком лаваша. Сверху снова положить начинку. Повторять процесс, пока не останется последний кусок лаваша. Положить на начинку четвертый кусок лаваша, прижать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Порезать брикет на маленькие кусочки при помощи острого ножа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Соединить яйца, соль и муку. Чуть-чуть взбить массу. Намазать заготовки гренок яичной смесью, обжарить на масле с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7797,'Получается очень вкусная закуска из тонкого лаваша и крабовых палочек.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7798,'Мелко нарезать на кусочки или нарезать сливочный ирис. Лучше взять продукт, который ломается.','https:https://st.vkuso.ru/data/cache/thumb/4c/99fb26a24f4ed4c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7798,'Растопить его на водяной бане с добавлением сливок.','https:https://st.vkuso.ru/data/cache/thumb/da/90592f922aa3eda_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7798,'Снять массу с огня, подмешать сливочное масло, смесь должна получиться блестящей и гладкой.','https:https://st.vkuso.ru/data/cache/thumb/ed/e9d663f1f0253ed_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7798,'Смазать форму рафинированным растительным маслом. Налить растопленный ирис, утопить в массе по сушеной ягоде клюквы или обжаренному и очищенному фундуку.','https:https://st.vkuso.ru/data/cache/thumb/71/8da323d13f1f171_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7798,'Растопить на водяной бане темный шоколад, добавить в него сливки, делать это постепенно. Готовые конфеты покрыть шоколадной массой и поставить на несколько часов в морозилку, затем достать их из формочек.','https:https://st.vkuso.ru/data/cache/thumb/83/b02326b06701c83_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7799,'Яйца разбить в тарелку, хорошенько взбить до белой пены и добавить к ним мелко порубленную зелень, у перца срезать плодоножку, порезать вдоль, удалить семена и нарезать мелкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7799,'Соединить ингредиенты: яйца, перец, хлебные крошки, фарш и перемешать руками до получения однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7799,'Форму для выпекания выстелить пергаментом и добавить немного растительного масла, мясную массу выложить в форму и выпекать в духовке примерно 1,5 часа при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7799,'Перед тем, как достать рулет из куриного мяса и говядины по-американски из формы, необходимо дать ему настояться около 20 минут, так как сок, который он пустил во время выпекания, должен впитаться обратно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7799,'Перед подачей блюдо переворачивается на разделочную доску, нарезается и охлаждается.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7800,'Порезать соломкой семгу или форель, посыпать перцем, солью. Положить к рыбе рис, мидии, креветки. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7800,'Приготовить соус: в горячую посуду налить молоко или сливки. Довести до кипения, налить белое сухое вино, оливковое масло, перемешать, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7800,'Потереть сыр, положить в соус, размешать, поставить на маленький огонь. Мешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7800,'Взять булку хлеба круглой формы, срезать верх, вынуть всю мякоть. Получится емкость из хлеба. Положить в данную емкость рис с морепродуктами, залить соусом. Посыпать зеленью, накрыть верхушкой. Отправить жульен на 5-10 минут в духовку, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7801,'Кока-колу влить в кастрюлю, добавить масло, какао-порошок и нагревать на среднем огне, после чего всыпать сахар и, помешивая, дождаться момента, когда сахар и масло полностью растворяться, после чего кастрюлю убрать с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7801,'Муку перемешать в тарелке с солью и содой, в отдельной посуде взбить яйцо и влить его в смесь колы и сахара, которая уже остыла, муку так же добавить в колу и перемешать все содержимое емкости до однородной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7801,'Тесто выложить в подготовленные формочки, немного не доливая до краев, выпекать капкейки по-американски с колой около 25 минут при температуре 180 градусов, готовность проверяется нажатием на кекс – блюдо готово, если серединка упругая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7802,'Растереть в крошку масло с мукой, добавить крахмал и разрыхлитель, творог, перемешать, вбить яйца, всыпать сахар, смешать до однородности, накрыть тесто пленкой, на час поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7802,'Очистить от кожуры яблоки, удалить семенную коробку, нарезать тонкими ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7802,'Подготовить форму для выпекания, часть теста распределить по дну, выложить на него  яблоки, присыпать сахаром, накрыть оставшейся частью теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7802,'Пирог творожный с яблочной начинкой выпекать около 30-40 минут в нагретой до 170 градусов духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7803,'Просеять муку, залить подсоленной водой дрожжи, всыпать сахар, размешать до растворения, засыпать половину муки, перемешать, добавить масло, 150 г тертого сыра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7803,'Всыпать постепенно вторую половину муки, вымесить тесто, убрать в смазанную маслом миску, накрыть и поставить в теплое место на полтора часа, чтобы тесто подошло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7803,'Включить для разогрева на 200 градусов духовку, противень застелить промасленной бумагой, обмять подошедшее тесто, руки смазать маслом, выложить с промежутками небольшими порциями на противень, должно получиться 12-13 шариков, дать расстояться 20 минут, смазать яйцом, присыпать оставшимся (100 г) сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7803,'Сырные булочки из дрожжевого теста будут готовы примерно через полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7804,'Подготовить смесь просеянной муки с сахаром и разрыхлителем, нарезать на кусочки охлажденное масло, растереть его руками с мукой, добавить тертую цедру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7804,'Разогреть до жидкого состояния мед, добавить к тесту, хорошо вымесить тесто и разделить на две части, из каждой части получиться должно порядка 20 штук печенья, половину печенья перед выпечкой посыпать измельченными орехами, готовое греческое медовое печенье с орехами и начинкой охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7804,'Взбить из сливочного масла, меда и сахарной пудры начинку, смазать начинкой и попарно соединить обычное печенье и ореховое.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7805,'Взбить в блендере мед, йогурт, ванилин до однородности, нарезать киви на тонкие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7805,'Выложить стенки ломтиками киви, аккуратно залить йогурт, украсить парфе из йогурта с киви миндальными хлопьями, подавать сразу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Подготовить форму, смазать маслом, включить на разогрев до 220 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Порезать филе лосося тонкими ломтями, полить лимонным соком, базилик и укроп мелко покрошить, сыр измельчить на терке, смешать в чашке творог со сливками, всыпать зелень, влить лимонный сок, посолить, поперчить, перемешать, начинка должна быть солоноватой на вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Перелить кипящую воду в широкую миску, аккуратно опустить листы лазаньи, подержать 3-4 минуты, воду слить в другую емкость, залить пласты холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Выложить на дно формы несколько листов лазаньи, чтобы полностью покрыли дно, влить пару столовых ложек воды от вымачивания, накрыть 13 частью филе лосося, чуть подсолить, выложить на рыбу 1/3 творожной смеси, сверху зеленый горошек и пласты лазаньи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Все слои повторить, закончить надо пластами лазаньи, каждый слой можно полить парой ложек воды оставшейся от вымачивания, верх лазаньи хорошо посыпать сыром (не жалеть сыр), сбрызнуть водой, выпекать около 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7806,'Блюдо будет готово, когда зарумянятся листы лазаньи и приготовится лосось, подавать лазанью с зеленым горошком и лососем обязательно горячей, так лучше всего ощущается ее неповторимый вкус!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Приготовить малиновое желе. Замочить желатин в воде, как написано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Измельчить малину с сахаром в блендере, протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7816,'Смазать плетенку с маком по-домашнему желтком, через 15 минут поставить на 20 минут в духовку, выпекать при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Нагреть желатин в микроволновой печи, главное не перегреть. Добавить в малиновый сок. Вылить в формочку диаметром 12 сантиметров. Отправить на 4-5 часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Приготовить бисквит: взбить яйца и сахар. В отдельную емкость просеять какао, муку, разрыхлитель. Осторожно высыпать в яичную массу. В конце положить масло. Вылить в форму, намазанную маслом. Диаметр формы – 16-18 сантиметров. Отправить в разогретую духовку на 10-12 минут, соблюдать температуру 180 градусов. Остудить на решетке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Приготовить мусс. Замочить желатин. Взбить маскарпоне, сливки, ликер, пудру на медленной скорости. Распустить желатин в воде. Переложить отдельно 1/3 мусса, соединить с желатином. В несколько приемов положить оставшийся мусс.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Собрать торт: в кондитерское кольцо положить бисквит, пропитать соусом из малины, соединенным с водой. На него вылить ½ мусса. Отправить на 2 часа в холод, чтобы мусс застыл.  Достать из формы малиновое желе, выложить на остывший мусс, вылить остальной. Отправить в холодильник на ночь или минимум на 5 часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7807,'Достать сливочный торт-суфле с малиной из формы, украсить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Разморозить фило, желательно в упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Измельчить орехи с корицей и сахаром (лучше рубить орехи не очень мелко). Положить в смесь чуть-чуть обжаренного кунжута. Отставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Растопить масло, поставить рядом с рабочим местом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Подготовить стеклянную форму или с антипригарным покрытием. Во время работы с тестом фило, его нужно всегда заворачивать в пленку. Тесто такое тонкое, что быстро засыхает и ломается. Намазать форму маслом, положить лист фило, чтобы он по размеру был, как дно формы. Не страшно, если тесто порвалось, важно, чтобы было 2 целых листа, которые будут наверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Нанести на первый лист растопленное масло, используя кисточку. Положить сверху второй лист, намазать. Если листов много, то можно положить третий. Выложить на листы орехи. Можно чуть-чуть полить сиропом. Сверху положить 2 листа, намазанные маслом. Сверху начинку, сироп, тесто, начинку, сироп. Повторять процедуру, пока не закончатся листы фило. Последний слой начинки накрыть несколькими целыми листами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Порезать пахлаву на ромбовидные куски при помощи острого ножа. Сильно нагреть оставшееся сливочное масло с растительным. Полить смесью масел пахлаву. Отправить в духовку, соблюдать температуру 180-200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Налить в кастрюлю ингредиенты для сиропа, нагреть, кипятить 2-3 минуты. Сироп должен стать прозрачным. Налить сироп в сковороду, добавить мед, довести почти до кипения. Залить сиропом готовую пахлаву, чтобы он заполнил все щелочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7808,'Отправить медовую пахлаву с грецкими орехами и миндалем на 5 минут в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7809,'Измельчить печенье в крошку (должно получиться примерно 1/2  стакана) и смешать с растопленным сливочным маслом, переложить в формочки, прижать смесь ко дну, чтобы сформовать основу чизкейка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7809,'Взбить блендером на небольшой скорости сметану с крем-сыром буквально 3-4 секунды, масса должна стать однородной, долго не взбивать, иначе образуется много воздушных пузырьков и чизкейк может потрескаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7809,'Всыпать сахарную пудру, вбить яйцо и взбить до однородного состояния, влить апельсиновый сок и осторожно перемешать, разлить по формочкам, поставить в микроволновку на 2 минуты при мощности 700 Вт, вынуть, когда масса в центре начнет пузыриться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7809,'У готового чизкейка в микроволновке за 5 минут середина будет желеобразная, но после остывания застынет, когда формочки достаточно остынут убрать на пару часов в холодильник, перед подачей чизкейк можно украсить какао-порошком или ягодами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7810,'Чуть-чуть взбить яйцо, отделить ¼ часть, чтобы смазывать сырники сверху. Протереть творог через сито или пюрировать в комбайне. Смешать яйцо и творог, насыпать сахар, перемешать. Насыпать манную крупу, перемешать. Отставить на 20 минут, чтобы манка набухла.','https:https://st.vkuso.ru/data/cache/thumb/61/89d80c5b2d39461_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7817,'Сварить густой сироп из воды и сахара, при опускании небольшой порции сиропа на ложке в холодную воду должен получаться мягкий шарик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Овсяные хлопья также измельчить в блендере или в кофемолке в муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7810,'Влажными руками сформировать сырники-шайбы, обвалять в муке, выложить на противень, застеленный силиконовым ковриком или фольгой. Оставленную часть яйца взбить с маленькой ложкой молока или воды. Намазать смесью сырники сверху. Отправить на 10 минут в духовку, соблюдать температуру 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/8d/b0f5e1341bef08d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7810,'Творожные сырники получаются красивые и вкусные.','https:https://st.vkuso.ru/data/cache/thumb/5b/e4d6d984620385b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Мелко натереть кабачок, отжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Вбить яйца, налить кефир, посыпать солью и измельченной петрушкой. Перемешать. Постепенно насыпать муку, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Налить ложку растительного масло, насыпать соду, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Отставить на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Намазать нагретую сковороду растительным маслом, сформировать блин, жарить с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7811,'Намазать кабачковые блинчики сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7812,'Залить желатин холодной водой (1 стакан), выждать полчаса до набухания, влить молоко, мед, всыпать какао, поставить на слабый огонь, нагреть до растворения какао (не кипятить!).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7812,'Добавить протертый сквозь сито творог или готовую обезжиренную творожную массу, хорошо перемешать, переложить в блендер, взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7812,'Разлить смесь по формочкам, убрать в холодильник на пару часов, а можно и на ночь, утром вкусный диетический завтрак суфле творожное с шоколадным вкусом готов, для любителей сладкого можно добавлять больше меда.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'Расстелить лаваш, намазать его майонезом. Можно добавить чуть-чуть кетчупа.','https:https://st.vkuso.ru/data/cache/thumb/97/b512b9fb9832297_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'Накрыть листьями салата (заранее вымыть их и обсушить).','https:https://st.vkuso.ru/data/cache/thumb/96/82c3572cf404396_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'Почистить отваренные яйца, измельчить. Выложить на салатные листья. Чуть-чуть намазать слой яиц майонезом.','https:https://st.vkuso.ru/data/cache/thumb/a3/65113dff0e507a3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'Порезать соломкой крабовые палочки, распределить по поверхности. Можно крабовые палочки не резать, а раскрутить их и разложить их, чтобы получился слой.','https:https://st.vkuso.ru/data/cache/thumb/97/95ceb61919ef597_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'В последнюю очередь использовать огурцы. Порезать их длинной соломкой, выложить на слой из крабовых палочек. Туго свернуть лаваш в рулетик. Скручивать осторожно, потому что он хорошо пропитывается майонезом.','https:https://st.vkuso.ru/data/cache/thumb/a8/4f5b59a6c48c8a8_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7813,'Отправить в холодильник, чтобы рулет из лаваша с крабовыми палочками и листьями салата пропитался. Порезать на кусочки, разложить на тарелке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7814,'Сварить круглый рис, измельчить половину ананаса, смешать с рисом, взбить сливки с пудрой в густую массу и соединить с рисовой смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7814,'В формовочное кольцо (можно вырезать из пластиковой бутылки) выложить кружочек ананаса, сверху – рисовую массу, охладить, снять кольцо и украсить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7814,'Рисовый пудинг с консервированными ананасами готовится из круглых сортов риса, подавать с фруктами, шоколадом или сладким соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7815,'Нарезать небольшими кубиками филе, грибы, нашинковать мелко лук, слегка обжарить со специями, почистить и нарезать мелко картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7815,'Подготовить форму, смазать маслом, уложить пласт готового слоеного теста, а на него начинку из курицы и грибов, посолить, сверху – картофель, присыпать измельченной зеленью, залить пару ложек воды в центр, накрыть вторым пластом теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7815,'Завернуть края, в середине пирога сделать небольшое отверстие, обильно смазать яичным желтком, выпекать кубете с курицей и грибами 40-50 минут при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7816,'Проварить в небольшом количестве воды мак около получаса, слить воду, всыпать сахар, пропустить через мясорубку, добавить яичный белок и мед, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7816,'Развести теплым молоком дрожжи, посолить, добавить сахар, влить растопленное сливочное масло, вбить яйцо, всыпать просеянную муку, вымесить тесто и дать ему подойти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7816,'Раскатать из теста лепешку в форме овала, смазать сливочным маслом, разложить маковую начинку, разровнять ее, свернуть из теста рулет, по бокам сделать косые надрезы и слегка развернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Порезать шоколадно-кофейные брауни с помадкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7817,'Взбить холодные белки до состояния крепкой пены, не прекращая взбивать, аккуратно влить кипящий сироп, не попадая на венчик миксера, иначе сироп разлетится к стенкам посуды и сразу загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7817,'После увеличения объема крема продолжать взбивать еще 3-4 минуты, по вкусу в белковый заварной крем для тортов можно добавить лимонный сок, а в сироп – ваниль, крем хорошо сохраняет форму и не опадает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7818,'Нарезать на ломтики баклажаны, присолить, присыпать смесью итальянских трав и поставить запекать в духовку с температурой 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7818,'Нашинковать мелко лук и подрумянить в половине масла, нарезать кубиками куриную грудку, обжарить в другой сковороде мясо на оставшемся масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7818,'Достать баклажаны, переложить на них мясо, сверху выложить лук, присыпать измельченным на терке сыром, запекать15 минут, подавать баклажаны, запеченные с курицей под сыром, горячими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7819,'Включить нагреваться духовку до 180 градусов, варить вымытый картофель в кожуре 6 минут после закипания, дать остыть и почистить (класть картофель в холодную воду).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7819,'Куриную грудку и грибы нарезать на небольшие кусочки, лук порезать кубиками, подрумянить в нагретом масле мясо, выложить на тарелку, в оставшемся масле поджарить лук, добавить грибы, жарить, пока не испариться жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7819,'В смесь грибов добавить муку, перемешать, влить сливки с молоком (не переставать мешать), добавить кусочки курицы, посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7819,'Перелить соус в форму для запекания, положить сверху натертый на крупной терке картофель, подсолить и присыпать не жалея натертым сыром и измельченной зеленью, поставить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7819,'Курица, запеченная с грибами под картофелем, будет готова примерно через полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Перемешать пшеничную муку, сахарный песок, быстродействующие дрожжи и соль в емкости большой глубины. Подлить оливковое масло, воду, вымесить тесто: оно должно получиться липким и упругим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Миску смазать тонким слоем масла, поместить в нее тесто, накрыть увлажненным полотенцем и поставить в тепло на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Масса должна увеличиться в объеме в полтора-два раза. Рабочую поверхность присыпать мукой, выложить поднявшееся тесто, разделить его на шесть или семь одинаковых частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Каждую часть скрутить в колбаску, края соединить, защипнуть. Накрыть бейглы полотенцем, оставить на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'В большой кастрюле вскипятить воду с добавлением мёда. Опускать в кипящую жидкость подготовленные изделия на полминуты, переворачивать шумовкой и варить еще столько же.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Вынуть бейглы все той же шумовкой, положить на слой бумажных полотенец для впитывания влаги. Подсохшие изделия обмакнуть в маковое семя или кунжут, выложить на противень, застеленный пергаментом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Печь в заранее разогретой до 220 градусов духовке до образования коричневатой корочки. Остудить выпечку на решетке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7820,'Любые овощи, филе лосося или семги нарезать небольшими ломтиками. Остывшие бейглы нарезать вдоль, прослоить сливочным сыром, рыбой и овощной нарезкой, подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7821,'Смешать в блендере кефир, творог, бананы, взбить до однородной массы, разложить творожный десертный крем с бананом по креманкам, украсить тертым шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7822,'Приготовить крем: растереть яйцо и сахар, насыпать муку. Растереть с мягким сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7822,'Пропустить творог несколько раз через мясорубку. Можно использовать кухонный комбайн или просто перетереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7822,'Соединить смеси, поставить на огонь. Постепенно из жидкого - крем превратится в густой. Постоянно помешивать, очень чувствуется, если крем подгорает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7822,'Приготовить тесто: соединить все ингредиенты (сливочное масло, сметану, сахар, яйца, соду, мед, муку), замесить негустое тесто. Разделить пополам, положить в форму, готовить корж 15 минут, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7822,'На теплые коржи нанести теплый крем, отставить на несколько часов, затем отправить нежный торт с творожным заварным кремом в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7823,'Добавить в мягкое масло сахар, ваниль, взбить 5 минут, вбить яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7823,'Смешать соль, разрыхлитель, просеянную муку и частями добавлять смесь во взбитое масло, каждый раз хорошо перемешивать, должно получиться не липкое твердое тесто, поставить его на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7823,'Достать небольшой кусочек теста, раскатать в «колбаски», сформовать в виде пальцев, когда порция кончится, то взять следующую.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7823,'Расплавить шоколад, влить чуть воды, промазать место для ногтя, положить орех миндаля, слегка придавить, выпекать печенье «Ведьмины пальчики» на Хэллоуин около 20 минут в духовке с температурой 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7824,'Порезать огурцы на брусочки, посыпать солью, размешать. Отставить на 20 минут, слить сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7824,'Добавить прессованный чеснок, перец, налить обычный и соевый соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7824,'Нагреть масло, насыпать кунжут, перемешать. Вылить смесь на огурцы, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7824,'Сложить огурчики с кунжутом по-корейски в емкости, дать им пропитаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Сухие дрожжи перемешать с водой  и сахарным песком, оставить на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Просеять муку в миску. Отдельно перемешать яйца с сахарным песком, добавить сметану. Смесь вылить в муку, влить дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Вымесить тесто, в конце добавить мягкий маргарин, масса должна получиться гладкой. Получившееся тесто поставить на ночь в холодильник или оставить в тепле до увеличения объема в два раза. Если тесто охладилось, то перед дальнейшим приготовлением его нужно согреть при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Для начинки промыть маковое семя, воду слить, добавить сахарный песок и новую порцию воды, массу растереть пестиком. Варить на тихом огне в течение 10 – 15 минут. На время оставить для набухания. Если масса растерта не очень тщательно, то в нее можно добавить панировочные сухари.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Согревшееся тесто разделить на три части, каждую раскатать в прямоугольник в полсантиметра толщиной, выложить начинку, свернуть рулетом. Разрезать изделие вдоль, три-пять сантиметров оставить неразрезанными.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7825,'Обе части развернуть вверх начинкой, свернуть жгут. Изделие выложить на застеленный пергаментом противень, оставить на полчаса для расстойки. Печь в течение получаса или чуть меньше. Подавать к столу остывшим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7826,'Свежевыжатый грейпфрутовый или апельсиновый сок перемешать со свежим или замороженным шпинатом, бананами, кусочками крупного зеленого яблока, овсяными или ржаными отрубями, мёдом, льдом.','https:https://st.vkuso.ru/data/cache/thumb/6e/8c46f50513c376e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7826,'Взбить в блендере до однородности.','https:https://st.vkuso.ru/data/cache/thumb/e3/731014d345bbce3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7826,'Разлить в высокие бокалы и сразу подать с трубочкой.','https:https://st.vkuso.ru/data/cache/thumb/ab/2b26d9f7b68c6ab_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7827,'Нарезать баклажаны кубиками, присыпать солью, убрать в холодильник на полчаса, мелко порезать морковь, нашинковать лук, нарезать сладкий перец соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7827,'Высыпать овощи в чашу мультиварки, готовить 15 минут в режиме «Выпечка», добавить кубики баклажанов, режим не менять, готовить еще 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7827,'Опустить на несколько секунд помидоры в кипяток и очистить от кожицы, раздавить чеснок прессом, измельчить зелень и стручковый перец, добавить все в чашу к обжаренным овощам, переключить режим на «Тушение», посолить, сдобрить специями, готовить 50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7827,'Кавказское блюдо аджапсандал в мультиварке получается довольно острым и ароматным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Сахарный песок растворить в воде на огне. Отдельно нарезать бананы, положить в сироп, варить 30 – 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/ca/40a3b32f29dbaca_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Мелко нарезать изюм, миндаль, курагу.','https:https://st.vkuso.ru/data/cache/thumb/e3/0ebfe05b7942fe3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Бананы должны потемнеть, превратиться в однородную массу, когда это произойдет – добавить в смесь остальные ингредиенты.','https:https://st.vkuso.ru/data/cache/thumb/65/05fcd9ed5a07365_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Всыпать сухое молоко, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/8d/a9a5fd659bb178d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Влить растопленное сливочное масло.','https:https://st.vkuso.ru/data/cache/thumb/d1/e352ff1ad580fd1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7828,'Массу выложить в форму, накрыть пищевой пленкой и поставить в морозилку на полчаса или час.','https:https://st.vkuso.ru/data/cache/thumb/81/68ee0ddf3489f81_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Смешать с ржаной мукой, ванилином и корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Поставить на огонь воду в кастрюльке. Когда она закипит, положить замороженные креветки, насыпать соль, положить лавровый листик, перец горошком. Варить минут пять, когда бульон закипит – креветки готовы. Выловить креветки, процедить бульон, поставить на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Почистить картофель, порезать на средние кубики. Почистить и вымыть лук и морковь, порезать, как для первого блюда, например, на маленькие кусочки. Лук можно положить в целом виде. После этого выловить его и выбросить, если кто-то в семье не любит лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Положить в бульон картофель, лук, морковь. Варить минут пятнадцать на среднем огне, овощи должны стать мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Измельчить плавленые сырки: или порезать на кубики, или натереть. Положить сырки в кипящий бульон, размешать. Варить минут семь, сырки должны раствориться. Если необходимо, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Почистить отваренные креветки. Две штуки оставить с хвостиками, они станут украшением для готового блюда. Положить креветки в суп, позволить нагреться несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7829,'Можно подавать сырный суп к столу, разлив его по тарелочкам и украсив креветками. Сверху посыпать измельченной петрушкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7830,'Нарезать говядину на небольшие кусочки, переложить в чашу мультиварки, выставить режим «Выпечка» и готовить 20 минут, добавить нашинкованный лук и порезанную мелко морковь, готовить еще 6 минут, режим не переключать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7830,'Добавить измельченный прессом чеснок, томатную пасту, любимую приправу для мяса, посолить, переключить режим на «Тушение» и готовить 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7830,'Порезать картофель на крупные кубики, а соленые огурцы кружочками, пересыпать их к овощам и мясу, залить бульоном, тушить азу из говядины по-татарски в мультиварке до готовности 1,5 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7830,'Это простое, но очень вкусное блюдо для домашнего воскресного обеда.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7831,'Нарезать мясо для азу, залить масло в чашу мультиварки, переложить в нее мясо, засыпать замороженные овощи (подобрать состав овощей по вкусу), посолить, добавить любимые специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7831,'Включить режим «Выпечка», готовить 40 минут, открыть крышку, добавить лавровый лист, горошки черного перца, переключить на режим «Подогрев», блюдо азу из овощей в мультиварке будет готово через 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7832,'Растворить сахар в половине кипяченого молока, дать остыть до 35 градусов, влить оставшееся молоко, «Актимель», тщательно взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7832,'Перелить смесь в мультиварку, включить на  «Подогрев», выдержать 25 минут, отключить нагрев и оставить актимель в мультиварке на 7-8 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7832,'Удобнее готовить напиток вечером, утром выпить по стаканчику, а остаток разлить по банкам и убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Приготовить тесто для бисквита: взбить по отдельности белки с сахаром и желтки, смешать с просеянной мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Выпекать в горячей духовке минут тридцать, соблюдать температуру 180 градусов, в период готовки дверцу духовки не открывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Приготовленный бисквит остудить на решетке, срезать верх таким образом, чтобы получился корж приблизительно 2 сантиметра в толщину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Приступить к крему: залить желатин водой, позволить набухнуть, довести до растворения на огне, но не дать закипеть. Остудить. Разделить яйца на желтки и белки. Взбить желтки и сахарную пудру до посветления.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Несколько больших ложек смеси соединить с желатином, положить данную смесь в емкость большого размера с сахарно-желтковой смесью, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Положить маскарпоне комнатной температуры, перемешать, чтобы получилась однородная гладкая масса. Взбить белки и соль в крутую пену.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'В несколько приемов смешать желтково-сырную смесь и белки, аккуратно размешать движениями снизу вверх.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Положить корж в формочку, сверху налить крем. Отправить минут на шестьдесят в холодильник, чтобы схватился крем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Порезать клубнику на ломтики, уложить на застывший крем. Приготовить желе из пакетика, как сказано в инструкции. Остудить до комнатной температуры, залить клубнику.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'В филе с луком вбить яйцо. Добавить ложку муки и майонеза. Перемешать все продукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7833,'Поставить торт с маскарпоне и клубникой часа на четыре в холодильник. Осторожно провести тоненьким ножом вдоль бортика формочки, снять его.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'Соединить в миксере муку и дрожжи. Насыпать сахар, вбить яйца. Нагревать минуту молоко с маслом. Вылить в миксер с мукой. Месить тесто в миксере 5 минут. Накрыть емкость пленкой, поставить в тепло на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'После этого отправить в холодильник на 4 часа минимум, чтобы проще было работать с тестом. Можно в холод не отправлять, тогда нужно отправить в тепло на несколько часов и при раскатывании сыпать немного больше муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'Раскатать тесто на столе, чуть-чуть присыпанном мукой. Должен получиться пласт из 3  шоколадок в ширину и 2 в длину. Наметить контур, обрезать лишние края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'На противень постелить пергамент. Используя скалку, перенести тесто на противень. В центре пласта положить 1,5 плитки шоколада, выделить контур при помощи ножа.','https:https://st.vkuso.ru/data/cache/thumb/63/3f1ae53330efb63_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'По контуру выложить халву. Халву можно заменить измельченными орехами, бананом, порезанным на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/04/76f903812805a04_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'Сверху положить 1,5 плитки шоколада.','https:https://st.vkuso.ru/data/cache/thumb/c3/f9e457c00e86bc3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'Тесто без шоколада порезать на полосочки по ширине, как кубик шоколада. С каждой узкой стороны пирога оставлять поля. Начать плести косичку: загнуть поля, на них – поперечные полосочки, чуть-чуть растягивая в процессе плетения.','https:https://st.vkuso.ru/data/cache/thumb/77/e10e25bdb2a6377_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7834,'Накрыть косичку полотенцем, поставить в тепло на 30 минут. Намазать яйцом, отправить на 30 минут в духовку, соблюдать температуру 170-180 градусов. Можно подавать косичку с шоколадом к чаю.','https:https://st.vkuso.ru/data/cache/thumb/4c/dace6122de7744c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7835,'Растереть творог, вбить яйца, перемешать, посолить, добавить сметану, масло, всыпать смесь муки (кукурузная и пшеничная), хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7835,'Смазать чашу маслом, переложить смесь в мультиварку, выставить режим «Выпечка», аливанка в мультиварке будет готова через 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7835,'Подавать аливанку к столу лучше горячей, это молдавское блюдо в мультиварке получается ароматным и сочным, для любителей сладкого можно добавить в творожную смесь сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7836,'Оставить сливочное масло при комнатной температуре, чтобы оно подтаяло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7836,'Взбить масло венчиком, насыпать сахарную пудру, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7836,'Насыпать какао-порошок, ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7836,'Растереть, чтобы получилась однородная смесь. Выложить в силиконовую смесь, отправить в морозилку на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7836,'Переложить масло в пластиковый контейнер, хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7837,'Порезать куриное филе на кубики 1-1,5 сантиметра, перекрутить мясо в мясорубке. Порезать мелко грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7837,'Обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7837,'Сделать фарш, положить обжаренные грибы, положить измельченный чеснок, вбить яйца, посыпать перцем, солью. Размешать, вымесить фарш.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7837,'Вымыть свиные кишки, заполнить их фаршем. Сделать колбаски по 15-20 сантиметров и проколоть по всей длине.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7837,'Запекать домашние колбаски из курицы и грибов в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7838,'Отделить желтки от белков, взбить белки, постепенно всыпая 2 мультистакана сахара, и добавить по одному желтки, добавить маленькими порциями в смесь муку, какао, осторожно перемешать, влить гашеную лимонным соком соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7838,'Вылить все в мультиварку, выставить режим «Выпечка», готовить торт со сметаной и ананасами в мультиварке 50-60 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7838,'Срезать у готового коржа верхушку около 1 см, порезать мелкими кубиками, приготовить из взбитой с сахаром сметаны крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7838,'Выложить на корж крем, измельченные орехи, кубики ананаса, кусочки коржа, повторить слои три раза, верх торта полить сметаной, украсить тертым шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Запекать перцы, переворачивая время от времени, 30 минут в духовке, соблюдать температуру 190 градусов. Поместить в пакет, отложить на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Снять с перцев кожуру, порезать на полоски.','https:https://st.vkuso.ru/data/cache/thumb/d6/a61db4ac0e076d6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Влить мёд, ввести воду порциями, замесить эластичное тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Отбить куриную грудку, стараться, чтобы получились прямоугольные кусочки. Положить 5 ломтиков бекона друг на друга. Ломтики должны пересекаться. Положить на бекон отбитое мясо. Посыпать перцем, солью, чуть-чуть намазать растительным маслом и прессованным чесноком. Посыпать орегано, измельченной петрушкой.','https:https://st.vkuso.ru/data/cache/thumb/10/1a94e07b847f310_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Положить сверху полоски перцев, кусочки сыра.','https:https://st.vkuso.ru/data/cache/thumb/d6/93d1aea3d3973d6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Свернуть рулетик, перевязать нитью.','https:https://st.vkuso.ru/data/cache/thumb/30/58383fecb992630_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Повторить процесс со второй грудкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Нагреть растительное масло, обжарить рулетики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Положить куриный рулет с болгарским перцем в беконе в форму, отправить на 15 минут в духовку, соблюдать температуру 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7839,'Остудить рулеты, порезать на кусочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Для приготовления блюда понадобится кастрюля с толстым дном. Растопить в ней сливочное масло и горький черный шоколад. Масса должна быть однородной, не кипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Снять с огня, всыпать сахарный песок и перемешать до растворения. Немного остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Вбить сырые куриные яйца по одному, каждый раз смесь взбивать миксером. Добавить несколько капель ванильного экстракта. В смесь просеять пшеничную муку, соль, какао-порошок, разрыхлитель, перемешать, емкость накрыть пленкой, поставить на час в холодильник, можно на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Противень застелить пергаментом или положить коврик из силикона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'В небольшую миску насыпать сахарную пудру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Отщипнуть немного охлажденного теста, скатать в шарик, хорошо обвалять в пудре и выложить на противень. То же самое проделать с остальным тестом, изделия выкладывать на расстоянии четырех сантиметров друг от друга.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7840,'Печь в заранее разогретой до 160 градусов духовке в течение 10 – 15 минут. Сахарная пудра потрескается и придаст печенью оригинальный внешний вид.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7841,'Отварить и почистить яйца, проколоть их много раз вилкой, нарезать вдоль волокон лук, налить в мультиварку масло слоем в 3 см., добавить зиру, перец красный, куркуму, лавровый лист, перец черный и прочие любимые специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7841,'Включить мультиварку на режим «Выпечка», когда масло нагреется положить яйца, обжарить 10 минут до подрумянивания, вынуть на блюдо, высыпать в чашу порезанный лук, обжарить до золотистого цвета, добавить разведенную в небольшом количестве воды томатную пасту, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7841,'Подлива для анда кари в мультиварке будет готова через 10 минут, переложить яйца в соус и оставить их в режиме «Подогрев» на 15 минут, подается это блюдо обычно с вареным рисом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Нагреть духовку. Форму 20 x 5 сантиметров намазать сливочным маслом, постелить специальную бумагу, которую чуть-чуть намазать маслом и посыпать какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Растопить на водяной бане 340 г шоколада (мелко нарубленного) и масло. При этом следует убедиться, что емкость, в которой находится масло с шоколадом, не прикасается к воде. Убрать с огня, размешать. Соединить какао, эспрессо и ваниль, мешать, пока какао не растворится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Добавить смесь в растопленный шоколад. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Насыпать сахар, мешать, пока он не растворится. Вбить по одному яйцу, каждый раз перемешивать. Важно, чтобы яйца не свернулись.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Просеять муку с солью, медленно насыпать в основную массу. Положить измельченные орехи, куски порубленного шоколада. Мешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Перелить тесто в формочку, готовить 30-40 минут. Готовность проверять зубочисткой. Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Для приготовления помадки - положить мелко нарубленный шоколад в термическую посуду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'В кастрюле соединить сливки и растворимый кофе, держать на небольшом огне, пока кофе не растворится. Убрать с огня, накрыть крышкой, отставить на полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Процедить смесь через сито в кастрюлю. Положить мед, поставить на огонь, довести до кипения. Мешать, пока мед не растворится. Убрать с огня.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7842,'Залить шоколад горячими сливками. Отставить на несколько минут. Перемешать шоколад до однородности. Залить помадкой остывший брауни. Распределить ровным слоем, отставить на 3 часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Порезать на средние кусочки свинину. Обжаривать на растительном масле на большом огне 5 минут, потом 10 минут на маленьком огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Порезать лук. Порезать грибы на кусочки вдоль. Потушить на растительном масле 10 минут со сливочным маслом и луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Крупно потереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Вымыть, почистить и отварить картофель. Готовый картофель порезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Положить ингредиенты в горшочек: картофель, затем свинину, майонез, сверху лук и грибы, посыпать сыром. Накрыть горшочки крышкой. Поставить в холодную духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7843,'Готовить мясо в горшочке с шампиньонами и сыром 20 минут при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7844,'Десяток куриных крылышек хорошо осмотреть и удалить остатки перьев.','https:https://st.vkuso.ru/data/cache/thumb/e2/46240ccb1a352e2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7844,'Положить в кастрюлю, залить водой, посолить и поставить на огонь. Довести до кипения, снять пену, убрать с плиты и остудить прямо в бульоне. Крылышки вынуть.','https:https://st.vkuso.ru/data/cache/thumb/60/1caa86616923160_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7844,'Приготовить льезон. Смешать, яйца, молоко и воду. Его можно сделать острее, если добавить острый перец, молотую паприку, давленый чеснок. Обвалять в муке. Обмакнуть в льезон. После льезона крылышки запанировать в кукурузных хлопьях. Дать изделиям полежать 20 минут, чтобы панировка хорошо впиталась, один раз перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/16/faeafab08171e16_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7844,'Растительное масло разогреть до температуры 180 градусов, быстро обжарить крылышки во фритюре в течение 30 – 60 секунд.','https:https://st.vkuso.ru/data/cache/thumb/04/5b5725482319904_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7845,'Отделить аккуратно желтки от белков, взбить сахар с белками, смешать растительное масло, апельсиновый сок, желтки, добавить все к белкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7845,'Смешать с разрыхлителем просеянную муку, постепенно добавить к яичной смеси, всыпать измельченную цедру апельсина, перемешать, вылить смесь в чашу мультиварки, выставить режим «Выпечка», готовить бисквит с апельсиновым соком и цедрой в мультиварке 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7845,'Этот вкусный бисквит можно использовать как отдельный десерт, или как основу для различных тортов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7846,'Соединить апельсиновый джем с соком одного апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7846,'Порезать на колечки перец чили, убрать зерна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7846,'Мариновать очищенные креветки в данной смеси 15-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7846,'Креветки обвалять в крахмале, обжарить на оливковом масле. Спустя 5-7 минут перелить в сковороду апельсиновый маринад, дать кристаллизироваться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7846,'Положить в апельсиновой глазури с перцем чили в салатник, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Довести до кипения масло и воду в кастрюльке на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Насыпать муку, сделать минимальный огонь. Готовить, помешивая, пока не получится шар, отстающий от дна кастрюли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Убрать с плиты, переложить шарик в большую емкость. Вбить яйца, взбивать после каждого яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Сформировать однородное тесто. Переложить его в форму 22 x 33 сантиметра. Отправить на 35 минут в духовку, соблюдать температуру 200 градусов. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Для приготовления шоколадного слоя растапливать в микроволновке 1 минуту масло и шоколад. Размешать. Продолжать нагревать с интервалом в 20 секунд до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Положить ванилин. Просеять сахарную пудру, насыпать ее в шоколадную смесь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Налить в смесь воду, мешать, пока не образуется пастообразная однородная масса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Нанести шоколадный слой на основу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Для приготовления крема взбить в посуде сливочный сыр до воздушности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Налить молоко, взбить. Добавить пудинг, взбить до загустения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Сделать из крема слой на шоколаде.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7847,'Завершить торт – эклер взбитыми сливками. Украсить шоколадным сиропом. При помощи зубочистки нарисовать линии. Отправить в холодильник для пропитки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'Промыть и обсушить бумажным полотенцем куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'Мясо порезать тоненькой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'Почистить лук, порезать на мелкие кубики как можно мельче.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'Соединить куриное филе с луком. Посыпать перцем, солью, мариновать несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7848,'Выкладывать оладьи ложкой на горячую сковороду с растительным маслом. Жарить по несколько минут с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7849,'Взбить миксером кефир с яйцами, натереть на терке сыр, лаваш нарезать (один оставить целым) на квадраты размером с ладонь, смазать чашу мультиварки маслом, выложить дно целым лавашем, края приподнять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7849,'Обмакивать остальные кусочки в кефирную смесь и выкладывать сверху внахлест, пересыпать каждый слой сыром, должно получиться 3-4 слоя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7849,'Накрыть верх пирога концами целого лаваша, залить оставшейся смесью кефира, положить кусочки масла, выставить мультиварку на режим «Выпечка» на 40 минут, по истечении указанного времени перевернуть пирог, ачма с сыром из лаваша в мультиварке будет готова через 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7849,'Грузинский пирог ачма — вкусное и сытное блюдо для завтрака, можно есть и холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Вымыть курицу, подсушить, порезать на кусочки, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Разогреть растительное масло, чуть-чуть обжарить курочку до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Выложить мясо в огнеупорную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Оставить в сковороде 3 ложки масла, обжарить измельченный лук, прессованный чеснок. Выложить лук с чесноком в форму на курицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Растопить в той же сковороде сливочное масло, насыпать ложку муки, перемешать до однородности, чтобы не было комков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Соединить бульон и молоко, посыпать перцем, солью, вылить в муку соус. Довести до загустения, помешивая, приблизительно это займет 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7850,'Вылить соус на курицу, посыпать травами, накрыть блюдо фольгой. Отправить в духовку на 30 минут. Запекать курицу в сливочно-молочном соусе с тимьяном и розмарином, соблюдая температуру 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7851,'Растопить на сковороде сливочное масло, обжарить измельченный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7851,'Выложить креветки, посыпать солью, приправить красным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7851,'Налить вино, сок одного лимона, добавить орегано.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7851,'Спустя несколько минут сделать огонь больше, готовить, пока не испарится вино на 1/3. Креветки в винном соусе с орегано подавать со свежим багетом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7852,'Нарезать вымытые баклажаны кружками, подсолить, на полчаса убрать в холодильник, порезать на кусочки мясо, переложить на дно мультиварки, выложить на него полукольца лука, сдобрить прованскими травами, солью, лавровым листом, перцем, зернами горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7852,'Положить на лук слой баклажанов, а на него нарезанные кольцами помидоры, покрыть сеточкой из майонеза, следующим слоем выложить натертую морковь с зеленью, мелко нашинкованный чеснок, баклажаны, помидоры, сдобрит перцем, смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7852,'Выставить мультиварку на режим «Выпечка», баклажаны тушеные с мясом в мультиварке будут готовиться в собственном соку 40 минут, для блюда лучше всего использовать молодые, сине-черные, вытянутые, немного недозрелые плоды баклажанов, а майонез можно заменить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7853,'Потереть яйца и сыр. Соединить с прессованным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7853,'Заправить майонезом, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7853,'Положить начинку на ветчину, порезанную на кружочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7853,'Закрутить, положить на тарелку вниз швом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7854,'Вчерашний, немного подсохший батон нарезать кубиками, полить оливковым маслом и обжарить на сухой сковороде со всех сторон до золотистого цвета. Также сухарики можно запечь в духовке при температуре 180 градусов в течение 10 минут, один раз перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7854,'Нарезать кубиками помидоры, натереть сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7854,'Приготовить заправку из бальзамического уксуса, горчицы, сметаны, оливкового масла, соли и перца. Ингредиенты взбить венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7854,'Вымыть зеленый салат, высушить, порвать руками на небольшие кусочки, выложить в общую салатницу или порционно. Сверху – обжаренные сухарики и помидоры, посыпать блюдо сыром, полить заправкой перед подачей на стол, чтобы хлеб не успел размокнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7855,'Приготовить в блендере пюре из банана и клубники, добавить «Активию», нагреть молоко в микроволновой печи 1 минуту, влить его в смесь,  хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Распределить лапшу по двум тарелочкам, залить горячим бульоном, посыпать измельченной петрушкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7855,'Разлить взбитую смесь по стеклянным стаканчикам, прикрыть пленкой, закрепить резинкой, положить на дно чаши мультиварки небольшое полотенце или силиконовый коврик, поставить стаканчики, залить горячей (но менее 100 градусов) водой до уровня заполнения стаканчиков, выставить режим «Подогрев» и время 20 минут, выждать после окончания режима 1 час (крышку не открывать), еще раз нагреть клубнично-банановый йогурт в мультиварке 20 минут в режиме  «Подогрев».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7855,'Дать йогурту остыть, убрать на пару часов в холодильник, достать и подать полезный напиток к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7856,'Кусочки мяса отбить со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/6a/2df0c3d30bd776a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7856,'Посолить и поперчить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/fb/a0f97702a6cfffb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7856,'Выложить на раскаленную сковороду с грилем.','https:https://st.vkuso.ru/data/cache/thumb/29/dad49ffb6b9a429_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7856,'Жарить три-четыре минуты с каждой стороны, время приготовления зависит от толщины мяса. Можно обжарить филе на обычной сковороде или на открытом огне.','https:https://st.vkuso.ru/data/cache/thumb/fd/eee2fbaf70a4cfd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7856,'Выложить на тарелку, накрыть фольгой или еще одной тарелкой, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/1d/9d3ac43d9df711d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7857,'Очистить репчатый лук, морковь и чеснок. Бекон и овощи нарезать небольшими кубиками. Разогреть оливковое масло в большой кастрюле, выложить все ингредиенты, прогревать в течение пяти-семи минут.','https:https://st.vkuso.ru/data/cache/thumb/26/980d3395aa8ac26_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7857,'Положить нарезанный цуккини, готовить еще четыре минуты, овощи должны стать мягкими.','https:https://st.vkuso.ru/data/cache/thumb/6f/fbb82f882e8246f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7857,'Нарезать шпинат и зеленую петрушку. В кастрюлю добавить зелень, нарезанные помидоры, свежий зеленый горошек, спаржу. Залить массу горячим бульоном или водой, довести до кипения, поперчить и посолить по вкусу. Положить макароны-ракушки, варить восемь минут.','https:https://st.vkuso.ru/data/cache/thumb/ba/9ed87e71674a5ba_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7857,'Суп снять с огня. Мелко нарезать зеленый базилик, положить в кастрюлю, накрыть крышкой на две минуты. Готовое блюдо разлить в тарелки, посыпать тертым сыром «Пармезан».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7858,'В небольшое количество теплой воды добавить сахарный песок, ложку пшеничной муки и сухие дрожжи. Когда появится «шапочка» и дрожжи заработают – добавить оливковое масло, муку и соль. Замесить тесто, положить его в пакет из целлофана, воздух выпустить. Пакет завязать и положить в холодильник на два-три часа или на ночь. За час перед началом приготовления тесто достать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7858,'Для приготовления соуса «Сальса Верде» нарезать травы: петрушку, укроп, зеленый лук и базилик, положить в блендер. Добавить дижонскую горчицу, филе анчоусов и оливковое масло. Ингредиенты превратить в однородную массу, можно досолить по вкусу, если есть необходимость.','https:https://st.vkuso.ru/data/cache/thumb/24/6909d99ee6e0b24_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7858,'Раскатать тесто на присыпанной мукой поверхности, толщина прямоугольной лепешки – полсантиметра или чуть больше. Щедро смазать пласт зеленым соусом.','https:https://st.vkuso.ru/data/cache/thumb/da/06fa14291ad3dda_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7858,'Свернуть его в рулет и нарезать ломтиками по одному сантиметру.','https:https://st.vkuso.ru/data/cache/thumb/16/ef35db02388ee16_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7858,'Аккуратно перенести изделия на застеленный бумагой противень, выложить плашмя и немного расплющить. Украсить мини-фокаччи кружочками оливок. Печь при температуре 200 градусов в течение 15 – 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/85/77f46e966437385_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7859,'Погасить соду кефиром, всыпать сахар, вбить яйцо, тщательно перемешать, протереть творог через сито, добавить пюре из банана, размешать, соединить с яйцом и сахаром, всыпать постепенно муку, замесить тесто чуть гуще, чем для обычной жарки на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7859,'Выложить тесто ложкой в чашу, жарить творожно-банановые оладьи на кефире в мультиварке при открытой крышке 10-15 минут в режиме «Выпечка», перевернуть на другую сторону, крышку закрыть, жарить еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7859,'Необычные вкусные оладушки готовы, подавать к чаю с вареньем, сгущенным молоком, медом или сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7860,'Тушки мелких кальмаров выпотрошить, удалить шкурку, продукт нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7878,'Порезать пару кусочков белого хлеба на кубики, присыпать солью, чуть обжарить в подсолнечном масле.','https:https://st.vkuso.ru/data/cache/thumb/0e/b333ef3deaf720e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7860,'На сковороде разогреть немного оливкового масла, накрошить сушеный или свежий перец чили, насыпать щепоть копченой паприки, положить кальмары. Жарить две минуты на сильном огне, снять с плиты и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7860,'Заранее отварить нут или использовать консервы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7860,'Вымыть и обсушить микс зеленых салатных листьев, добавить морепродукты, нут и кабачок цуккини.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7860,'В сковороду, где жарились продукты, выдавить лимонный сок, налить оставшееся оливковое масло, заправку посолить по вкусу. Перемешать, залить соусом салат и сразу подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7861,'Растереть творог, вбить яйцо, добавить сахар, всыпать постепенно порциями смесь муки и разрыхлителя, тщательно вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7861,'Раскатать тесто в лепешку, разрезать на две части, положить на середину каждой банан, скатать в рулет, нарезать каждый рулет кусочками примерно по 2 см толщиной, переложить сырники в чашу мультиварки смазанную маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7861,'Выставить режим «Выпечка», жарить сырники из творога с бананом в мультиварке 15 минут, перевернуть и жарить еще 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7861,'Эти сырники с «солнышком» из банана съедят на завтрак даже самые капризные малыши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7862,'Белый хлеб высшего сорта нарезать кубиками, выложить на застеленный бумагой для выпечки противень. Сбрызнуть оливковым маслом, посолить, посыпать сушеными прованскими травами вместе с нарезанным чесноком. Печь сухарики при температуре 150 градусов в течение 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7862,'Разморозить креветки, очистить, выложить на противень, также сбрызнуть оливковым маслом и посолить. Запечь в духовом шкафу в течение семи минут, температура – 140 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7862,'Пекинскую капусту мелко нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7862,'Добавить креветки и заправить смесь соусом «Тартар». Можно взять магазинный или приготовить самостоятельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7862,'Салат посыпать сухариками вместе с рубленым зеленым укропом. Перемешать и сразу подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'В кастрюле разогреть ложку оливкового масла, добавить измельченный репчатый лук, пассеровать продукт до мягкости в течение двух-трех минут на медленном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'Копченый бекон нарезать небольшими кусочками, добавить к луку, обжарить до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'Добавить в массу рис для ризотто, перемешать, огонь увеличить, влить белое сухое вино, прогревать две минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'Куриный бульон подогреть, вливать понемногу в основную массу, помешивать до выпаривания жидкости. Через 20 минут рис должен стать мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'Помидоры черри на веточке положить на противень, сбрызнуть оливковым маслом, поперчить и посолить. Поставить овощи в духовой шкаф на пять-шесть минут. Переложить помидоры на тарелку, накрыть, чтобы не остыли.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7863,'Добавить в ризотто сыр «Маскарпоне» и мелко нарезанный базилик. Выложить блюдо на тарелки, сверху украсить веточками запеченных помидоров черри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7864,'Замороженное филе горбуши подержать при комнатной температуре в течение часа или взять свежее. Нарезать филе на кусочки небольшого размера, вымыть и обсушить бумажным полотенцем.','https:https://st.vkuso.ru/data/cache/thumb/e7/d2ac5be982cf5e7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7864,'Петрушку, орегано и укроп вымыть и мелко нарезать, каждый вид зелени положить в отдельную мисочку или пиалу. Если под рукой нет свежей зелени, можно использовать сушеную или специи для рыбы.','https:https://st.vkuso.ru/data/cache/thumb/fb/b942ee5f3ac7afb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7864,'В форму для запекания налить оливковое масло, выложить филе, полить лимонным соком, посолить и поперчить, дать постоять в течение 10 – 15 минут. Разогреть духовку до 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/1e/3c341402970771e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7864,'Залить рыбу сливками, посыпать зеленью и готовить в течение 30 – 40 минут, время зависит от размера и толщины кусочков.','https:https://st.vkuso.ru/data/cache/thumb/59/8bc0536d771f459_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7864,'Готовое блюдо немного остудить и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/1d/62f1b544589c81d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7865,'Нарезать баранину на куски, промыть и обсушить, смазать маслом, сдобрить черным перцем, посолить, выложить дно большой миски свежим розмарином, уложить на него мясо, сверху присыпать розмарином, накрыть пленкой, убрать в холодильник и выдержать 3-4 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7865,'Вылить оливковое масло в чашу мультиварки, переложить в нее мясо, жарить баранину на режиме «Выпечка» по 15 минут с каждой стороны до золотистой корочки с открытой крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7865,'Нашинковать лук полукольцами, переложить на мясо, присыпать розмарином, залить вином, включить режим «Тушение», баранина с розмарином в вине в мультиварке будет готова через час, мясо получается нежным, очень ароматным и мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7866,'Подготовить доску, постелить специальную бумагу или фольгу. Помыть клубнику, хорошо высушить. Убедиться, что клубника совершенно сухая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7866,'Растопить темный шоколад. Окунуть в шоколад каждую ягодку, выложить их на доску с бумагой или фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7866,'Растопить белый шоколад. Отправить шоколад в полиэтиленовый пакет, отрезать уголок, украсить спиралью 1/3 ягод, покрытых темным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7866,'Вторую часть ягод, покрытых темным шоколадом посыпать измельченными орешками, третью часть оставить без изменений.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7866,'Поставить доску с  клубникой в темном и белом шоколаде с орехами в холодильник на полчаса, чтобы застыл шоколад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7867,'Очистить и мелко нашинковать лук, обжарить с добавлением масла 10 минут в режиме «Выпечка», всыпать муку, пассировать, но без изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7867,'Влить бульон, размешать до исчезновения комочков, переключить в режим «Тушение», готовить белый соус «Велюте» в мультиварке 10 минут, дать чуть остыть, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7867,'Чтобы на остывшем соусе не образовалась пленка необходимо сбрызнуть маслом, соус универсальный, сочетается с любыми блюдам из мяса, рыбы или курицы, на его основе, если развести молоком или сливками, можно приготовить суп-пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7868,'Отварить яйца и креветки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7868,'Порезать батон на маленькие кубики, обжарить до золотистого цвета на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7868,'Измельчить листья салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7868,'Собрать салат: обжаренные сухарики, листья салата, яйца, порезанные крупно, почищенные креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7868,'Осторожно размешать, заправить майонезом, посыпать салат из креветок и яиц с сухариками солью и перцем, украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7869,'Разделать, вымыть и просушить рыбу. Натереть перцем и солью внутри и снаружи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7869,'Соединить сок 1 лимона и 1 апельсина, измельченную зелень, масло. Положить рыбу в маринад на 60 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7869,'Выложить рыбу в форму, сверху положить лимонные дольки, чуть-чуть полить маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7869,'Готовить 20 минут в духовке, соблюдать температуру 190-200 градусов, поливать периодически маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7869,'Посыпать пряную скумбрию с лимоном орешками, продолжать готовить 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Порезать сливы на четвертинки или половинки, убрать косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Побрызгать сливы коньяком или ромом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Взбить яйца миксером, порциями подсыпать сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Насыпать просеянную муку с разрыхлителем. Размешать, чтобы получилось без комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Взбить миксером сметану или йогурт. Осторожно ввести в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Форму намазать маслом, присыпать мукой или сухариками, положить сливы, залить тестом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Отправить формочку в горячую духовку. Готовить 50 минут, соблюдать температуру 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7870,'Остудить шарлотку со сливами и коньяком. Можно при желании посыпать сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Просеять крахмал через ситечко, налить молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Взбить яйцо вилкой, налить молоко с крахмалом, посыпать солью, размешать. Если сразу соединить крахмал и яйцо, то образуются комочки, а это нежелательно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Среднюю сковороду намазать чуть-чуть маслом, нагреть на большом огне. Вылить в сковороду яичную смесь. Покачать сковороду, чтобы омлет распределился по всей поверхности сковороды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Готовить на большом огне, омлет должен стать снизу румяным. Перевернуть, готовить несколько минут со второй стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7871,'Убрать со сковороды омлет, свернуть рулетом. Острым ножом порезать на полоски. Если блинчик остывший, то его удобно порезать на тоненькие полоски. Если рулет горячий, то на более толстые.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7872,'Замесить из всех ингредиентов тесто, дать постоять, выставить мультиварку на режим «Подогрев», дать слегка прогреться, отключить, присыпать чашу мукой, положить тесто, закрыть крышку, оставить тесто на час, пусть хорошо подойдет в тепле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7872,'Включить режим «Выпечка», готовить домашний белый хлеб в мультиварке 1 час, перевернуть и поставить еще на 30 минут, хлеб получается ароматным и вкусным',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7873,'Соединить все сухие продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7873,'Отдельно соединить жидкие ингредиенты, взбить вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7873,'Смешать сухие продукты с жидкими. Перемешать в однородную смесь. Получится негустое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7873,'Налить в формочки по 1-1,5 ложки теста, положить сверху ложку варенья, на него опять тесто. Таким образом, заполнить формочки на 2/3.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7873,'Отправить на 25 минут в духовку. Можно подавать маффины с джемом от Джейми Оливера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Перетереть творог через сито, чтобы он был без крупинок. Соединить творог и мягкий маргарин или масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Разделить желтки и белки. Положить желтки в творожную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Соединить муку и соду, просеять в смесь, замесить тесто. Получается мягкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Сформировать шар, отправить на 10-15 минут в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Вымыть вяленую вишню, подсушить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Поделить тесто пополам, раскатать на пергаменте, посыпанном мукой. Из теста должен получиться прямоугольник приблизительно в 3 миллиметра, по размеру 15 на 20 сантиметров. Отправить в холодильник, чтобы проще было свернуть рулет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Сделать начинку: взбить белки и щепотку соли до мягкой пены. Налить уксус или сок лимона, взбивать, медленно добавлять сахарную пудру и ванильный сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Достать из холодильника пласт теста. Чуть-чуть обрезать неровные краешки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Распределить ½ белковой смеси тоненьким слоем, от краев отступать 1 сантиметр. Положить сверху ½ вишни. Свернуть по длинной стороне рулет, помогать пергаментом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Разрезать рулет острым ножом на кусочки по 3-4 сантиметра, стараться не давить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Выложить на противень, застеленный пергаментом. Из обрезков теста раскатать маленькие лепешки, положить в них начинку из белка, чуть-чуть защипнуть края. Положить к остальным булочкам.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7874,'Готовить нежные творожные булочки с вяленой вишней 20-30 минут до легкого румянца, соблюдать температуру 160 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7875,'Почистить картофель, порезать на бруски по 1 сантиметру.','https:https://st.vkuso.ru/data/cache/thumb/fe/fb753c3e0ca6dfe_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7875,'Взбить белки до пены. Посыпать перцем, солью, добавить сладкую паприку. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/e7/97afd27db3abde7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7875,'Положить картофель в глубокую емкость. Перелить взбитые белки, перемешать, чтобы все кусочки картофеля были покрыты белками.','https:https://st.vkuso.ru/data/cache/thumb/d7/f4de1e59def5fd7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7875,'Застелить противень специальной бумагой, положить на нее равномерно картофель. Готовить в духовке 7-10 минут, соблюдать температуру 200-220 градусов.','https:https://st.vkuso.ru/data/cache/thumb/3e/b66119534a0193e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7875,'Убрать бумагу и продолжать запекать картофель фри с яичным белком без масла до золотистого цвета.','https:https://st.vkuso.ru/data/cache/thumb/ac/e9eed420d8a78ac_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7876,'Нарезать свинину на небольшие кубики, переложить на дно чаши мультиварки, сверху – кубики картофеля, присыпать полукольцами лука, добавить кусочки грибов (заранее замочить), поперчить, посолить, готовить бешбармак из свинины в мультиварке 50 минут в режиме «Тушение».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7876,'Пока готовится мясо замесить тесто из муки, воды и яйца, раскатать в тонкий пласт, нарезать на квадратики, отварить в кипятке 1 минуту, выложить на блюдо, а на них мясо с грибами и картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7876,'Это казахское блюдо получается в мультиварке нежирным и более легким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7877,'Порезать на ломтики очищенный картофель, лук нарезать на тонкие колечки, переложить в миску. Подсолить, поперчить, аккуратно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7877,'Смазать противень маслом, разложить ломтики картофеля, уложить сверху кубики сала, поместить в прогретую до 220 градусов духовку, запеченный картофель с салом и лучком будет готов через 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Раскатать его тонко на бумаге для выпекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7878,'Вылить сквозь сито в сотейник, чтобы убрать оставшиеся частички кукурузы.','https:https://st.vkuso.ru/data/cache/thumb/34/7cbe7843ac1ef34_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7878,'Массу нагреть до кипения и снять крем-суп из кукурузы со сливками с плиты.','https:https://st.vkuso.ru/data/cache/thumb/25/c2be2977c567225_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7878,'Разлить по тарелкам, положить в каждую по ложке брусничного соуса и гренки.','https:https://st.vkuso.ru/data/cache/thumb/d9/92fdb6f252161d9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7879,'Вскипятить молоко в режиме «Варка на пару», дать остыть примерно до 40 градусов, всыпать пакетик закваски и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7879,'Приготовленные баночки с крышками обдать кипятком, разлить в них смесь молока с закваской, чашу мультиварки помыть, положить на дно полотенце, поставить баночки, залить водой до половины высоты баночек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7879,'Включить режим «Йогурт», если его нет, то «Подогрев», оставить бифидум в мультиварке на 7 часов, в конце готовки можно добавить в баночки кусочки фруктов, накрыть крышками, убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7879,'Рецепт приготовления напитка подойдет для любой мультиварки у которой есть режим с температурой 37-40 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7880,'Положить свежую или размороженную вишню без косточек в сотейник вместе с выделившимся соком, добавить мед и сок одного апельсина, при слабом нагреве дать закипеть, помешивая варить около минуты.','https:https://st.vkuso.ru/data/cache/thumb/d0/873d224b4e9b4d0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7880,'Разболтать в холодной воде крахмал, медленно, помешивая влить к ягодам, варить соус до загустения, добавить листики мяты, размешать, убрать с плиты.','https:https://st.vkuso.ru/data/cache/thumb/9b/994b77eb051819b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7880,'Дать вишнево-апельсиновому соусу с мятой минут 5 настояться, подавать к столу теплым.','https:https://st.vkuso.ru/data/cache/thumb/76/55090faf4144576_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7881,'Перемешать хорошо сахар,  масло, вбить яйца, перемешать, объединить с просеянной мукой, какао- порошком и разрыхлителем. Смешать с помощью миксера до образования однородного теста (если будет слишком густым, то добавить к массе чуть молока или жидкого шоколада).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7881,'Включить для прогрева до 190 градусов духовку. Заполнить тестом формочки до середины, положить по кусочку шоколада, прикрыть его тестом (можно еще присыпать стружкой шоколада).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7881,'Поставить кексы из какао с шоколадной сердцевиной в разогретую духовку примерно на 20 минут. Готовность десерта определить с помощью зубочистки, когда она останется практически сухой, то кексы можно считать готовыми.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7881,'Достать формочки, дать полностью остыть и вынуть кексы. Приятного чаепития!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7882,'Нарезать картошку и морковь, нашинковать капусту и лук, переложить все в мультиварку, всыпать фасоль, добавить натертый корень петрушки, заправить томатной пастой, залить бульоном, посолить, добавить сахар, влить растительное масло и уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7882,'В чашу для варки на пару положить свеклу, разрезанную на четвертинки, установить над овощами с бульоном, готовить час в режиме «Тушение».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7882,'Вынуть и остудить свеклу, натереть, переложить к остальным овощам, перемешать, выставить режим «Варка на пару» и довести борщ с фасолью без мяса в мультиварке до кипения, долго не кипятить, т.к. борщ потеряет цвет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7882,'В дни поста борщ можно готовить на грибном или овощном отваре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Порубить замороженное масло, добавить муку (просеянную), соль и сахар, продолжить рубить до образования крупной маслянистой крошки, добавить пару желтков, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Положить в тесто пару ложек хорошей сметаны, смешать все вместе, убрать колобок теста в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Застелить пергаментом форму для выпечки, заполнить тестом, разровнять, утрамбовать, поставить на полчаса в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Охлажденную форму поместить в уже разогретую до 180 градусов духовку, выпекать основу для домашнего твикса минут 20, достать, дать чуть остыть, осторожно извлечь из формы, окончательно охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'В кастрюле с толстым дном прогреть сгущенное молоко с маслом до появления светло карамельного цвета, убрать с плиты.  Основу твикса быстро, но аккуратно покрыть сваренной карамелью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Поломать шоколадную плитку на кусочки, высыпать в сухой сотейник, растопить, помешивая, чтобы глазурь не пригорела, на водяной бане, прогреть минуты 2-3.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Равномерно полить жидким шоколадом со всех сторон корж, покрытый карамелью, поместить минимум на 4 часа, а лучше чуть больше, в холодильник, но не в морозильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7883,'Хорошо охладившийся десерт нарезать на палочки и подать к чаю или кофе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7884,'Отварить до готовности крупные куски рыбы со специями и петрушкой в слегка подсоленной воде.','https:https://st.vkuso.ru/data/cache/thumb/e5/57b282049362ae5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7884,'Вынуть из бульона рыбу, дать ему закипеть, положить морковь, порезанную на тонкие кружки и кубики картофеля, добавить луковицу, разрезанную на четвертинки, варить около 25 минут.','https:https://st.vkuso.ru/data/cache/thumb/46/7d3ab9240439a46_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7884,'Дать остыть, юшку сцедить на мелком сите, чтобы была прозрачной, рыбу измельчить на небольшие кусочки, перемешать с вареными овощами, таким образом начинка для ухи из судака в пирожке готова.','https:https://st.vkuso.ru/data/cache/thumb/00/093bd3e4f427200_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7884,'Раскатать из готового теста сочни среднего размера, положить по столовой ложке начинки, защипать и запечь в духовке. Пирожки к столу подавать с теплым бульоном, который можно присыпать порубленной зеленью укропа.','https:https://st.vkuso.ru/data/cache/thumb/53/bbd58bc8bd6ab53_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7885,'Очищенный банан порезать на кусочки, пюрировать блендером с погружной насадкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7885,'Влить маленькими порциями молоко, взбить банановый мусс-коктейль еще раз, разлить в бокалы, желательно чуть охладить. Приятного аппетита!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Нашинковать базилик и укроп, добавить к мягкому сливочному маслу вместе с цедрой лимона, чуть подсолить, перемешать, дать начинке постоять.','https:https://st.vkuso.ru/data/cache/thumb/3b/e3d692ca8d89a3b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Рыбу ополоснуть водой, если остались мелкие косточки – удалить, обтереть двухслойными салфетками, филе разрезать пополам.','https:https://st.vkuso.ru/data/cache/thumb/4c/853e59b852f544c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Выстлать противень пергаментной бумагой, уложить пласт теста, размером в 2 раза больше, чем филе, положить на него одно филе спинкой вниз, поперчить, присолить. Аккуратно равномерно размазать по поверхности рыбы масляную начинку.','https:https://st.vkuso.ru/data/cache/thumb/b3/f232a81cd3536b3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Прикрыть вторым пластом филе, поперчить, присолить.','https:https://st.vkuso.ru/data/cache/thumb/eb/b1df098910c26eb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Взболтать яйцо, смазать поверхность теста вокруг рыбы, завернуть край теста на рыбу, придавить, чтобы получилось подобие конверта, излишки теста срезать.','https:https://st.vkuso.ru/data/cache/thumb/0f/4a4baa539f1af0f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Верх теста промазать яйцом, сделать острым ножом насечки.','https:https://st.vkuso.ru/data/cache/thumb/0b/37d0f7e2d9ea80b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7886,'Поставить в заранее прогретую до 190 градусов духовку на 25 минут, чтобы поверхность теста слала золотисто соломенного цвета. Подавать к столу можно блюдо, как в теплом виде, так и в холодном.','https:https://st.vkuso.ru/data/cache/thumb/d3/6bf0fcf065b7fd3_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7887,'Засыпать в мультиварку промытую бруснику, всыпать сахар, мед, измельченный блендером лимон с кожурой, приправить несколькими бутончиками гвоздики и варить брусничное варенье с лимоном в мультиварке на режиме «Тушение» 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7887,'По окончанию варки крышку не открывать, оставить на 2 часа, затем разлить по баночкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7888,'Приготовить тесто, половину раскатать в достаточно тонкий круг, включить и прогреть до 260 градусов духовку, противень промазать маслом, уложить основу пиццы, сформовать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7888,'Промазать томатным соусом, уложить кружочки чоризо, моцареллу, присыпать сухим орегано, полить из ложки маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7888,'Поставить пиццу с чоризо на тонком тесте на нижнюю полочку духовки, выпекать под наблюдением 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7888,'Как только края начнут зарумяниваться, а сыр плавиться, вынуть пиццу из духовки и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7889,'Срезать с тыквы корку, порезать на ломти, разложить на противне, выстланном пекарской бумагой, между ними разложить очищенные зубочки чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7889,'Тыкву посолить, поперчить, присыпать смесью прованских трав, смазать каждый кусочек маслом, побрызгать уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7889,'Запекать тыквенные дольки с чесноком около 40 минут при температуре 175 градусов пока они не станут мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Для приготовления начинки понадобится белый шоколад, его нужно поломать на кусочки. Стручок ванили разрезать пополам, вынуть семена.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7890,'Отбить мясо, поперчить, посолить, присыпать приправами, втереть их в мясо, сделать острым ножом надрезы с внутренней стороны куска, нарезать яблоко (без кожуры) на тонкие пластинки, нафаршировать мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7890,'Смешать сметану с раздавленным чесноком, полить половиной соуса мясо, свернуть в рулет и связать шнуром, щели скрепить зубочистками, выложить мясо в чашу, полить соусом, запекать в режиме «Выпечка», буженина из свинины с яблоками в мультиварке будет готова через 2,5 часа, затем переложить мясо на блюдо, разрезать, украсить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7890,'Чтобы блюдо получилось сочным надо выбирать свинину пожирнее, а яблоки для аромата лучше взять кисло-сладких сортов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Вымыть сухофрукты, залить кипяченой водой, поместить на пару минут в микроволновку, почистить яблоки.','https:https://st.vkuso.ru/data/cache/thumb/7a/46126192640027a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Яблоки и клубнику порезать на тонкие ломтики.','https:https://st.vkuso.ru/data/cache/thumb/56/484587db8ddb456_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Коричневый сахар взбить с яйцами до светло-коричневой массы.','https:https://st.vkuso.ru/data/cache/thumb/30/819128831c3df30_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Всыпать в смесь корицу, влить растопленное масло, тщательно перемешать, порциями всыпать разрыхлитель с мукой, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b8/4dd15e1d482a0b8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Добавить дробленые орехи (половину нормы), фрукты, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/75/249c92f49df0975_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Смазать форму для орехового пирога с сухофруктами и яблоками маслом, заполнить тестом.','https:https://st.vkuso.ru/data/cache/thumb/5d/d3505f39532685d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Поверх выложить сухофрукты, посыпать остатками ореховой крошки.','https:https://st.vkuso.ru/data/cache/thumb/ed/3eb4eb8f387a0ed_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7891,'Выпекать 45-60 минут, готовый пирог достать, дать остыть четверть часа и вынуть из формы.','https:https://st.vkuso.ru/data/cache/thumb/01/5dd9adc7346c501_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7892,'Прогреть духовку до 180 градусов, подготовить противень, выстлать двумя слоями фольги, промазать маслом. Порубить мелко лук, чеснок, петрушку, перемешать с растопленным маслом.','https:https://st.vkuso.ru/data/cache/thumb/62/2c6988965605962_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7892,'Хлеб порезать на кубики.','https:https://st.vkuso.ru/data/cache/thumb/dc/914d12b5bd1cbdc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7892,'Равномерно полить чесночным маслом с зеленью.','https:https://st.vkuso.ru/data/cache/thumb/6d/365ecb4b170876d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7892,'Обернуть хлеб фольгой, оставить в духовке на 10 минут, достать осторожно развернуть фольгу, присыпать хлеб тертым чеддером.','https:https://st.vkuso.ru/data/cache/thumb/64/0d543f5c0f1d464_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7892,'Отправить противень с горячим бутербродом с чеддером и чесноком еще на четверть часа в духовку до расплавления сыра, дать закуске немного остыть, посыпать порубленной зеленью петрушки.','https:https://st.vkuso.ru/data/cache/thumb/d7/5a72adae9bc70d7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7893,'Вареники считаются традиционным украинским блюдом, а приготовить вареники с картошкой на курином бульоне в мультиварке можно одновременно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7893,'Промыть куриные кости, сложить в чашу мультиварки, залить холодной водой, выставить режим «Тушение», готовить 3,5 часа, за полчаса до окончания добавить в бульон морковь, лук, приправить душистым перцем, лавровым листом, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7893,'Пока вариться бульон приготовить из указанных ингредиентов тесто, начинку и слепить вареники, для начинки приготовить густое картофельное пюре и смешать с обжаренным луком, она не должна быть сухой и с достаточным количеством жареного лука, перчить и солить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7893,'Смазать контейнер для варки на пару маслом, переложить вареники, вставить контейнер в чашу над бульоном, переключить режим на «Варка на пару», готовить 20 минут, подавать вареники в тарелке со сметаной, а бульон процедить и налить в пиалу или чашку для бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7894,'Залить нут водой, дать постоять ночь, утром промыть, залить новой порцией чистой воды, поставить варить, дать закипеть, всыпать четверть чайной ложки соды, удалить пену, закрыть крышкой, сделать нагрев минимальным, проварить два часа до полного размягчения нута.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7894,'Перец смазать маслом, обернуть в фольгу, отправить на 20 минут в прогретую заранее до 220 градусов духовку. Дать остыть прямо в фольге, удалить ее, убрать с перца шкурку и хвостик с семенами, сок слить в чашу блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Тесто раскатать в лепешку прямоугольной формы, выложить начинку, скатать рулет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Соединить творог и масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7894,'Обжарить семя зиры на сухой сковороде, кунжут измельчить в кофемолке, объединить их, добавить соль, растереть. В чашу блендера положить нут, нарезанный чеснок, перец, специи, влить лимонный сок, масло, измельчить хумус со сладким перцем и чесноком до состояния пасты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7895,'Помыть, почистить фрукты, если надо, то порезать, взвесить нужную порцию для одной закладки,  фрукты по весу должны составлять 1/4 от объема чаши мультиварки, для двухлитровой – 0,5 кг фруктов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7895,'Вынуть косточки из абрикосов, переложить в чашу, засыпать сахаром, добавить сок из половины лимона, полностью снять клапан для пара, иначе варенье может «убежать».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7895,'Выставить режим «Выпечка», готовить абрикосовое варенье с лимоном в мультиварке 1 час, не забывать помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7895,'Разложить готовое варенье по стерильным банкам, закатать крышкой, перевернуть, укрыть одеялом, дать остыть, для улучшения вкуса можно при варке в чашу добавить горсть миндаля, если варенье готовится как заготовка на зиму, то орехи кладут прямо в банку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7896,'Перемешать просеянную муку с содой, порошком какао, разрыхлителем. Взбить размягченное масло и сахарную пудру (всыпать порциями) до получения светлой и пышной массы, вбить яйцо, взбить еще раз, добавить муку, перемешать. Колобок теста разделить на 4 части, поставить на 20 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7896,'Включить и прогреть до 180 градусов духовку, раскатать одну порцию теста в пласт, вырезать небольшие кружочки, разложить на противне, застеленном пергаментом, выпекать  печенье «Орео» 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7896,'Взбить масло до побеления, всыпать сахарную пудру, еще раз взбить. Чуть подогреть сливки, частями, продолжая взбивать, влить к маслу. Должна получиться воздушная однородная масса, в конце взбивания по желанию можно добавить ваниль. Промазать половину кружочков кремом, накрыть оставшимися, убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7897,'Включить для разогрева до 180 градусов духовку, положить в чашу миксера яйца, сахар, творог, добавить чуть соды, подсолить. Взбивать 7 минут до получения однородной массы на средней скорости.','https:https://st.vkuso.ru/data/cache/thumb/5e/c7227b34285955e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7897,'Срезать с половинки лимона цедру, банан мелко порезать, а можно крупно натереть, смешать с творожной массой до однородности.','https:https://st.vkuso.ru/data/cache/thumb/43/3b5f3dbfc3cef43_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7897,'В глубокой миске перемешать муку, сливочное масло, сахар, соду, соль до получения крошки.','https:https://st.vkuso.ru/data/cache/thumb/4d/ac22726f6cf914d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7897,'Круглую форму смазать маслом, дно выстлать пергаментом, заполнить половиной крошки, положить творожную начинку, прикрыть второй половиной крошки. Выпекать насыпной творожно-лимонный пирог с бананом при 180 градусах около часа.','https:https://st.vkuso.ru/data/cache/thumb/bb/605ba3252cdbcbb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7898,'Вымыть все овощи, переложить целиком в чашу мультиварки, залить водой, выставить режим «Варка на пару», время задать 30 минут, затем остудить, почистить, нарезать на кубики, сложить в миску, добавить капусту, кубики соленых огурцов, мелко нашинкованный лук, заправить соком лимона, маслом и посолить, любители могут добавить консервированную или вареную фасоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7898,'По второму способу, чтобы приготовить винегрет в мультиварке с квашеной капустой, надо предварительно нарезать овощи на кубики, переложить в сетчатый контейнер варки на пару, а в чашу залить пару стаканов воды, включить мультиварку на режим «Варка на пару» и готовить полчаса, остудить, смешать с остальными компонентами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7899,'Растереть сахар с яйцом, добавить разрыхлитель с содой и сметану, тщательно перемешать, постепенно всыпать муку, перемешанную с какао, имбирем, корицей и ванилином, хорошо вымесить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7899,'Смазать чашу мультиварки маслом, переложить тесто, выставить режим «Выпечка», обсыпать вишню мукой, выложить сверху на тесто, слегка вдавить, готовить шоколадно-вишневый кекс в мультиварке 1 час, дать остыть, полить растопленным шоколадом или глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7900,'Подготовить овощи, рис и мясо, разогреть пустую чашу в режиме «Выпечка», обжарить куски мяса 5 минут до растапливания жира (в курятину придется добавить чуть масла), всыпать половину тертой моркови и тонко нарезанный лук, влить 5 ст.л. масла, обжарит 5 минут в режиме «Выпечка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7900,'Всыпать промытый рис, оставшуюся морковь, залить бульоном, посолить, приправить специями, в составе которых желательно должна присутствовать зира, добавить не чищеные зубчики чеснока, готовить плов из свинины, баранины или курицы в мультиварке 1 час в режиме «Плов», чеснок перед подачей к столу вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7901,'Залить дрожжи слегка подогретым молоком, вымесить тесто, дать постоять в теплом месте час. Припорошить стол мукой, раскатать в тонкий пласт тесто, вырезать кружки подходящей по размеру кружкой, чтобы они соответствовали по диаметру кружочкам колбасы.','https:https://st.vkuso.ru/data/cache/thumb/f8/8194c049da164f8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7901,'Положить колбасу между двумя кружками теста.','https:https://st.vkuso.ru/data/cache/thumb/dc/72f641cebaa47dc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7901,'Надрезать острым ножом 8 лучей от края к центру через равное расстояние, но центральную часть не затрагивать.','https:https://st.vkuso.ru/data/cache/thumb/17/45f7e3478d2a417_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7901,'Два соседних сектора развернуть друг от друга градусов на 60, колбаса в разрезах поднимается практически вертикально.','https:https://st.vkuso.ru/data/cache/thumb/36/23e60654e845236_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7901,'Верх колбасных цветочков из теста смазать разболтанным желтком, переложить их на противень, поместить в духовку с температурой 180 градусов, выпекать до готовности.','https:https://st.vkuso.ru/data/cache/thumb/70/f772eadbf532370_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7902,'Приготовить фарш, добавить протертый лук, вбить яйцо, сдобрить черным перцем и солью, перемешать, сформовать котлеты, переложить их в контейнер для варки на пару.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7902,'Высыпать готовую мороженую смесь в смазанную маслом чашу мультиварки, посолить, установить сверху контейнер с котлетами, включить режим «Тушение», паровые котлеты в мультиварке с гавайской смесью будут готовы через 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Поставить банку сгущенки вариться на 3 часа, чернослив хорошо вымыть, нарезать кусочками, залить ликером на 4 часа.','https:https://st.vkuso.ru/data/cache/thumb/18/fdff49c0a856118_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Включить прогреваться до 180 градусов духовку. В желтки всыпать половину сахара, взбить до густоты и появления белесоватого цвета.','https:https://st.vkuso.ru/data/cache/thumb/e8/0cd618e1a06f0e8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Холодные белки поместить в сухую посуду, всыпать щепотку соли и несколько капель сока лимона, взбить до устойчивых пиков. Смешать желтки с парой-тройкой ложек белков, потом добавить еще белки, осторожно перемешать заворачивающимися движениями от дна к верху.','https:https://st.vkuso.ru/data/cache/thumb/3b/953ddc1f450953b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Всыпать порциями в смесь, просеянную подсоленную муку с порошком какао, очень осторожно вымесить тесто, чтобы смесь не опала. Взять несколько ложек полученной смеси, влить масло, перемешать с оставшейся массой. Заполнить тестом подготовленную форму, выстланную пергаментом, поставить на 40-45 минут в духовку,','https:https://st.vkuso.ru/data/cache/thumb/e8/5d59e72c0a900e8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Готовую бисквитную основу для шоколадного торта с черносливом и со сливочно-карамельным кремом лучше не доставать сразу из формы, а дать ей минут 10 остыть, вынуть из формы, положить на решетку и полностью остудить.','https:https://st.vkuso.ru/data/cache/thumb/7c/3c5d5d6f2b5987c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Взбить вареную сгущенку венчиком в однородную массу, поставить охлаждаться в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/8c/f928dd64715d48c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Сцедить чернослив.','https:https://st.vkuso.ru/data/cache/thumb/4c/2fa73354af80b4c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Холодные сливки и пакетик загустителя взбить в плотную устойчивую массу.','https:https://st.vkuso.ru/data/cache/thumb/1a/2e34185ff704c1a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Положить во взбитую сгущенку, две ложки воздушных сливок, перемешать, повторить несколько раз. Перемешать основную массу сливок со смесью сгущенки и сливок до однородного состояния в густую воздушную массу.','https:https://st.vkuso.ru/data/cache/thumb/d8/97ee010c6ad60d8_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Готовый бисквит разрезать вдоль на 4 коржа.','https:https://st.vkuso.ru/data/cache/thumb/5d/25fb5b92362055d_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'На корж выложить чернослив, прикрыть его кремом, далее положить еще корж и т.д., стопку поставить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/6b/20fdac85083386b_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Вырезать из бумаги для выпечки диск по размеру кастрюльки с отверстием по центру. Закипятить в этой кастрюльке воду с сахаром при сильном нагреве, убавить огонь до среднего, положить цедру одного апельсина и очищенные груши.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Разрезать на шестнадцать частей, поставить в форму для выпекания рядами, плотно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7903,'Сливки чуть подогреть, всыпать поломанный на кусочки шоколад, перемешать до растворения кусочков, положить сливочное масло, перемешать, дать остыть. Достать промазанные коржи из холодильника, облить глазурью, вернуть опять в холодильник и дать ему там переночевать, украсить орехами, шоколадной стружкой и т.п. Приятного чаепития!','https:https://st.vkuso.ru/data/cache/thumb/a5/53e55a4584c22a5_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7904,'Формочки смазать маслом, духовку включить и прогреть до 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/e6/b81ef042c8b73e6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7904,'Перемешать горошек, мелко порезанный помидор, лук, заполнить формочки.','https:https://st.vkuso.ru/data/cache/thumb/70/f1af15132bf5370_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7904,'Залить по столовой ложке сливок, разбить по яйцу, подсолить, поперчить.','https:https://st.vkuso.ru/data/cache/thumb/ab/bd81a1f45bb3bab_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7904,'Добавить еще по ложке сливок.','https:https://st.vkuso.ru/data/cache/thumb/c5/ef196fa8a836dc5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7904,'Готовить яичницу с помидорами и горошком в духовке на водяной бане. Установить формочки в сковороду, налить воду, поставить в прогретую духовку, запекать до готовности яиц.','https:https://st.vkuso.ru/data/cache/thumb/38/a7576eae008c438_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7905,'Разогреть до кипения в чаше мультиварки масло на режиме «Тушение», положить мясо, готовить 10 минут, затем всыпать измельченный лук, готовить в текущем режиме еще 15 минут, добавить нарезанный на большие куски картофель, томатную пасту, залить бульоном из кубиков',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7905,'Картофель порезать большими кусочками и добавить в кастрюлю, тушить до окончания программы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7905,'Снять в чашку жир с бульона, вынуть мясо и картофель, долить воды до середины чаши, дать закипеть, опустить в бульон лапшу, варить в режиме «Тушение» 8-10 минут, переложить лапшу на широкое блюдо, сверху – картофель с мясом, полить мясо с картофелем и лапшой по-туркменски в мультиварке снятыми с бульона «вершками» с измельченным луком, подавать это туркменское блюдо горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7906,'Размять ягоды клюквы, залить половиной стакана воды, размешать, отжать сок, выжимки залить 300 мл воды, всыпать сахар, дать закипеть, процедить, выжимки выбросить.','https:https://st.vkuso.ru/data/cache/thumb/ee/3b9dac9a7b7dfee_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7906,'К процеженному отвару добавить манку, проварить клюквенный мусс с манкой до сгущения.','https:https://st.vkuso.ru/data/cache/thumb/be/bc596305d4a96be_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7906,'В остывшую массу влить сок, взбить до увеличения объема и изменения цвета. Мусс разложить по формочкам, присыпать шоколадной стружкой, оформить ягодами, убрать в холодильник','https:https://st.vkuso.ru/data/cache/thumb/c0/07f1f4b4badf4c0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7907,'Перемешать в миске сгущенку, размягченное масло, какао-порошок, алкоголь и сироп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7907,'Добавить измельченное в крошку печенье (часть оставить), хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7907,'Скатать из массы небольшие шарики. Обвалять домашние конфеты с ромом в оставленной крошке, переложить на плоское блюдо, убрать на час или больше в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Дрожжи залить чуть теплым молоком, добавить муку, яйца, сливочное масло, сахар, соль. Вымесить эластичное упругое тесто, убрать на полчаса в тепло. Когда тесто подойдет обмять его, дать постоять еще полчаса, чтобы оно увеличилось в объеме еще раз.','https:https://st.vkuso.ru/data/cache/thumb/70/da7a179d85d1a70_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Для начинки крупно натереть сыр, добавить яйца, смесь муки с разрыхлителем и немного соли, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b2/bb3a6ee27debeb2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Размять брынзу вилкой, порубить фисташки, перемешать их с сыром, половину орехов оставить.','https:https://st.vkuso.ru/data/cache/thumb/2d/ff1aa6c4da6562d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Разделить тесто на равные кусочки.','https:https://st.vkuso.ru/data/cache/thumb/0d/0bf7e477ef0b70d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Раскатать каждый в прямоугольник, положить по центру начинку, смазать края булочек с сырной начинкой и фисташками желтком, разболтанным с водой.','https:https://st.vkuso.ru/data/cache/thumb/00/88c8e283d79f800_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Свернуть вовнутрь так, чтобы начинка из сыра осталась открытой. Присыпать противень мукой, излишки стряхнуть, разложить булочки, промазать верх желтком, дать постоять треть часа, присыпать оставшимися орехами.','https:https://st.vkuso.ru/data/cache/thumb/66/9cec564e350e366_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7908,'Выпекать полчаса в уже прогретой до 180 градусов духовке. Достать, прикрыть полотенцем.','https:https://st.vkuso.ru/data/cache/thumb/63/eb4b89c4ffa0c63_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Половину бисквита выложить на дно формы, сверху – часть яичного крема. Процедуру повторить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7909,'Нарезать говядину на кусочки, нашинковать мелко лук, перец нарезать полосками, чашу мультиварки смазать маслом, прикрыть дно слоем лука, на него выложить слой перца, а сверху мясо, присыпать мясо приправами, посолить, сбрызнуть соком лайма и залить бульоном, говядина с болгарским перцем по-кубински в мультиварке готовится от 4 до 6 часов (последнее предпочтительнее) в режиме «Тушение», горячее, ароматное и нежное мясо прекрасно сочетается с отварным рисом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7910,'Вымочить печень в воде около часа, слить воду, промыть и нарезать печень на небольшие кусочки, нашинковать тонкими полукольцами лук, натереть морковь, налить в чашу мультиварки растительное масло, разогреть, обжарить печень, лук и морковку в режиме «Выпечка» 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7910,'Добавить в сметану муку, специи, воду, размешать, залить печень, установить мультиварку в режим «Тушение», говяжья печень со сметаной в мультиварке будет готова через 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7911,'Прогреть сковороду налить масло, положить зелень шпината, несколько раз перевернуть, чтобы его разморозить, прогреть еще 15 минут до испарения воды.','https:https://st.vkuso.ru/data/cache/thumb/e1/fa48f709392cfe1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7911,'Взбить до однородного состояния подсоленное молоко и яйцо.','https:https://st.vkuso.ru/data/cache/thumb/84/ee7f55f6a1eec84_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7911,'Приподнять шпинат лопаточкой залить под него немного яичной смеси, остальную вылить сверху, накрыть сковороду крышкой, готовить омлет с зеленью шпината и семгой еще 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/9d/f0b3b2c224abb9d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7911,'Разложить горячий омлет по тарелкам, добавить на каждую по кусочку семги.','https:https://st.vkuso.ru/data/cache/thumb/62/e53e185c65e8e62_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7912,'Толстодонную кастрюлю нагреть, влить растительное масло, до легкого золотистого оттенка обжарить мелко нарезанный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7912,'Затем добавить к луку измельченный чеснок, семена тмина, венгерскую паприку, все посолить, поперчить и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7912,'Томатную пасту смешать с бульоном, перелить в кастрюлю, размешать, дать закипеть, после чего сделать огонь минимальным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7912,'Говядину порезать крупными кубиками, переложить в кастрюлю с луком, готовить без крышки час-полтора: мясо должно стать мягким и нежным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7912,'Готовый венгерский гуляш из говядины с подливкой посыпать рубленой зеленью и подать вместе с любимым гарниром, например, картофельным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7913,'Сварить картофель, размять в пюре, вбить в него яйцо, всыпать муку, добавить перец, соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7913,'Переложить массу на противень, промазанный маслом, прикрыть слоем мелко порезанных помидоров, присыпать сыром, положить пластинки грибов, посыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7913,'Выпекать картофельную пицца с моцареллой и грибами около получаса при температуре порядка 200 градусов. Перед подачей к столу блюдо чуть остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7914,'Размягченное масло перемешать руками с подсоленной мукой до образования мелкой крошки, влить 3 ст.л. молока, добавить желток, вымесить тесто, убрать на 15 минут в холодильник. Достать хорошо охлажденное тесто, раскатать между листами пленки в 2 мм пласт, положить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7914,'Смазать форму маслом, застелить пергаментом, заполнить тестом, сделать бортики, засыпать грузом (горохом). Выпекать основу для киша с сыром рикотта и шпинатом в прогретой до 180 градусов духовке 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/f0/ec4099ad01698f0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7914,'Потушить 2 минуты шпинат со сливочным маслом, убрать с плиты, дать остыть. Смешать в миске крахмал, яйцо, белок, остатки молока, рикотту и шпинат, начинку подсолить, поперчить. Достать основу, высыпать горох, заполнить начинкой.','https:https://st.vkuso.ru/data/cache/thumb/e7/8dea46a803f0de7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7914,'В духовке понизить температуру до 160 градусов, выпекать киш 45 минут.','https:https://st.vkuso.ru/data/cache/thumb/b0/801bf9d783f81b0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Всыпать в чашу блендера подсоленную муку, добавить масло, взбить в маслянистую крошку, влить холодную воду, взбить до получения достаточно густого теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Сформовать шар, обернуть пленкой, переложить его в глубокую миску, поставить на полчаса в холодильник. Если нет времени готовить дальше, то можно его оставить там на пару дней, тогда перед готовкой дать ему постоять в комнате треть часа и дать оттаять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Насыпать какао, пудру и ароматизатор. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Разрезать стручок ванили, добавить семена ванили к грушам вместе со стручком, прикрыть сверху вырезанным кружком, чтобы погрузить по максимуму груши в сироп. Отрегулировать нагрев, чтобы кипение было только чуть заметно, проварить груши 15 минут до размягчения, дать остыть, не доставая из сиропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Раскатать тесто в круг по размеру формы, поместить в форму, излишки обрезать, застелить бумагой, засыпать горохом или фасолью, чтобы при выпечке дно не поднялось, выпекать треть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Высыпать утяжелитель, дать основе для десерта с грушевой начинкой и заварным кремом остыть, температуру духовки снизить до 175 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Груши разрезать на 4 части, разложить на основу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Полстакана сахара взбить с яйцом в густую пену, постепенно всыпать муку, влить сливки, добавить соль и ванильный экстракт или бренди, еще раз взбить до получения гомогенной массы, залить груши.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7915,'Выпекать в прогретой духовке 10 минут, присыпать слегка обжаренными миндальными лепестками, перемешанными со столовой ложкой сахара. Продолжить выпечку еще треть часа до легкого потемнения крема, дать остыть, порезать на куски.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Взбить яйца вместе с сахаром, не спеша ввести муку, замесить тесто, из которого испечь бисквит.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Холодной водой залить желатин и убрать емкость в сторону на 30 минут, после чего прогреть его до полного растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Сливочное масло взбить, подмешать в него сгущенное молоко, добавить мед, желатин, ром и кофе, тщательно все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Готовый бисквит разрезать вдоль, чтобы получилось два одинаковых коржа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Один бисквитный корж смазать половиной подготовленного крема, сверху аккуратно положить второй корж, по бокам торта распределить печенье в виде забора.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7916,'Собранный торт бисквитный из печенья «Трубочки» украсить оставшейся половиной крема и тертым шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Засыпать в чашу миксера муку, сахар, какао порошок, вбить яйца, добавить миндальную муку, желтки, перемешать пару минут при средней скорости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Взбить белки и сахарную пудру до устойчивой пены, объединить с тестом, осторожно перемешать. Выпекать бисквит при 180 градусах до готовности, дать остыть, разрезать вдоль на 4 части, коржи можно выпечь и по отдельности, если так удобнее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Для приготовления сиропа дать воде с сахаром закипеть, влить ликер и отжатый малиновый сок, перемешать, уварить до слабой густоты. Взбить блендером сахарную пудру с малиной, протереть сквозь сито, удалить косточки, добавить малиновый ликер, прогреть при слабом нагреве до 40 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Шоколад поломать на кусочки, растопить в микроволновке или на водяной бане, положить мягкое масло, измельченную с сахарной пудрой малину, добавить ликер, хорошо перемешать, дать остыть. Поставить на пару часов в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Для приготовления мармелада, прогреть сахар с малиной до однородности, взбить блендером, протереть сквозь сито, убрать все косточки, перелить в сотейник с толстым дном, поставить на плиту, положить агар-агар, прогреть до кипения, залить в круглую форму, дать застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Для приготовления глазури растворить глюкозу в сливках, дать закипеть, перемешать с растопленным шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Собрать торт «Малиново-шоколадный трюфель» в нижеследующем порядке. Уложить корж в кольцо, равномерно пропитать остывшим сиропом, нанести треть ганаша, прикрыть вторым коржом, пропитать еще раз сиропом, уложить ровным слоем мармелад, уложить еще один корж, полить сиропом, нанести ганаш, прикрыть последним коржом, промазать с боков и сверху оставшимся ганашом, украсить торт охлажденной глазурью и поставить его в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7917,'Достать, оформить орехами, ягодами малины и пищевым золотом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7918,'Перемешать просеянную пшеничную муку, молотую корицу, пекарский порошок, соль и сахарный песок. Вбить сырое куриное яйцо, влить молоко, перемешать, дать постоять при комнатной температуре 20 минут, чтобы набухла клейковина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7918,'Влить растопленное сливочное масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7924,'Сырое куриное яйцо растереть с сахаром, сливочным маслом и холодной водой.','https:https://st.vkuso.ru/data/cache/thumb/71/b8231cea1b00e71_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7918,'Жарить блины на горячей сковороде без жира, по минуте с каждой стороны. Выложить на тарелку стопкой, в таком виде выпечка будет дольше остывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7918,'Для приготовления соуса вымыть яблоки, удалить сердцевину и очистить кожуру, мякоть нарезать дольками. В емкости с толстым дном перемешать сливочное масло и коричневый сахар, добавить корицу и яблоки. Тушить смесь в течение 10 минут до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7918,'Соус выложить поверх панкейков и полить яблоки кленовым сиропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Картофель промыть под водой, очистить от кожуры и отварить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Кубиками порезать помидоры, мелко нашинковать репчатый лук и до золотистого оттенка обжарить его на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'К луку добавить подготовленные помидоры и жарить все вместе не больше 3-х минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Затем к овощам положить фарш, добавить соль и молотый перец, перемешать и жарить все до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Из кастрюли с картофелем слить воду и, добавив соль и сливочное масло, сделать из картофеля пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Обжаренный с луком и помидорами фарш переложить в форму для запекания, поверх мясного слоя выложить картофельное пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Второй слой аккуратно разровнять и посыпать его мелко натертым сыром, поставить форму в духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7919,'Готовится запеканка с фаршем, помидорами и картофелем на протяжении 35 минут в духовке при 180 градусах.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7920,'Сырки положить в морозилку – в дальнейшем их будет легче измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7920,'Вымыть, очистить и нарезать кубиками клубни картофеля. Переложить в кастрюлю с водой, поставить вариться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7920,'Очистить и натереть морковь, обжарить на растительном масле. Вместе с корнеплодом можно обжарить измельченный репчатый лук.  Добавить в суп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7920,'Отделить от костей мякоть копченого окорочка, мелко нарезать и также добавить в суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7920,'Натереть сырки, выложить в кастрюлю, прогреть, помешивая до полного растворения, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7921,'Консервированного лосося поломать вилкой, вынуть косточки, мякоть перемешать с мелко нарезанным красным репчатым луком, влить оливковое масло, лимонный сок, молотый перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7921,'На куски хлеба намазать сыр, выложить рыбно-луковую массу, помидоры, нарезанные ломтиками, кусочки листьев латука. Накрыть бутерброды оставшимся хлебом, прижать начинку и разрезать каждый сэндвич по диагонали пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7922,'Для приготовления маринада перемешать кетчуп, соевый соус, коричневый сахар, сок апельсина. Корень имбиря очистить и натереть на мелкой терке. Все ингредиенты хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/9c/7a0219b4a62d69c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7922,'Сырое куриное филе нарезать кусочками.','https:https://st.vkuso.ru/data/cache/thumb/7c/ab6aa6aca9ea47c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7922,'Залить маринадом. Сверху массу прижать тарелкой, дать постоять полчаса для пропитывания.','https:https://st.vkuso.ru/data/cache/thumb/b7/8cfec81fdd203b7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7922,'Противень сбрызнуть растительным маслом. Курицу наколоть на небольшие шпажки вместе с кусочками очищенного ананаса. Выложить их в духовку на полчаса, температура приготовления – 200 градусов. Важно блюдо не передержать, иначе шашлык станет сухим и жестким.','https:https://st.vkuso.ru/data/cache/thumb/7c/804442dd621d67c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'До полной готовности отварить картофель в подсоленной воде, после чего дать ему остыть и снять с него кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'Подготовленные картофелины разрезать вдоль пополам и вынуть чайной ложкой из каждой половинки мякоть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'Изъятую мякоть порезать кубиками, мясо, срезанное с окорочка, и промытые помидоры также порезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'В большой миске смешать помидоры, копченое мясо, картофельную мякоть и мелкорубленую зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'Добавить в массу небольшое количество соли и молотого перца, тщательно все перемешать вместе с майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'Половинки картофеля (без мякоти) нафаршировать получившейся начинкой и посыпать сверху мелко натертым сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7923,'Запекать фаршированный картофель с курицей, помидорами и сыроa в духовке, разогретой до 180 градусов, до полного зарумянивания сыра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Сделать из массы колбаски или шарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7924,'Всыпать просеянную муку с разрыхлителем, консистенция теста должна быть эластичной. Распределить массу форме для выпекания и поставить в духовку, нагретую до 190 градусов. Печь изделие до золотистого цвета.','https:https://st.vkuso.ru/data/cache/thumb/56/6d54936c4f52256_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7924,'Для начинки натереть очищенные яблоки, добавить в массу рубленые грецкие орехи, остатки сахара, ванилин, молотую корицу, кардамон. Готовый корж вынуть из духовки, выложить начинку, поставить пирог обратно и допечь до готовности, температура приготовления – та же.','https:https://st.vkuso.ru/data/cache/thumb/08/9f67d461ef69208_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Репчатый лук нарезать мелкими кубиками. Половину смешать с фаршем, для его приготовления лучше взять свинину и говядину в равных пропорциях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Вбить в массу сырое куриное яйцо, всыпать панировочные сухари и итальянские травы. Соль и перец добавить по вкусу. Сформовать мокрыми руками небольшие шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Разогреть в кастрюле оливковое масло, обжарить фрикадельки с двух сторон и вынуть из кастрюли. Очистить и мелко нарезать чеснок. Обжарить его вместе с оставшимся луком на оливковом масле в той самой кастрюле, где готовились фрикадельки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Влить заранее приготовленный мясной бульон и томаты в собственном соку, очищенные от кожицы. Смесь довести до кипения, накрыть крышкой, прогревать в течение 15 минут на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Натереть сыр на крупной терке. Нарезать тонкими ломтиками багет или чиабатту. Посыпать их тертым сыром, выложить на противень. Печь в заранее разогретой духовке в течение 10 минут при температуре 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Перелить суп в блендер, измельчить, посолить, поперчить, добавить щепотку сахарного песка и бальзамический уксус. Положить в суп измельченный базилик и фрикадельки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7925,'Подать блюдо с готовыми гренками и сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7926,'Подготовить все овощи, вымыть и обсушить, изюм тщательно помыть, высыпать в десертное вино, дать постоять минимум полчаса, а лучше больше.','https:https://st.vkuso.ru/data/cache/thumb/b3/398b6bb930216b3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7926,'Все необходимые для заправки ингредиенты  перемешать и взбить. Кроме сока половины лимона в заправку можно добавить и цедру.','https:https://st.vkuso.ru/data/cache/thumb/24/8a76ec6ba5fe324_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7926,'Яблоки разрезать на две части, а потом еще раз пополам и на более мелкие дольки, но не менее сантиметра, иначе они поломаются при перемешивании.  Сложить яблоки и изюм в достаточно глубокую миску, влить 5 столовых ложек заправки, перемешать, чтобы ломтики не потемнели.','https:https://st.vkuso.ru/data/cache/thumb/30/5ecda1361285c30_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7926,'Стебли сельдерея очистить от внешней кожицы с помощью овощечистки, порезать кусочками толщиной в пару миллиметров, всыпать к яблокам, перемешать, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/7e/ad615fd6f51e47e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7926,'Плоскую тарелку выложить по кругу листьями салата, всыпать к яблокам дробленые орехи, размешать, переложить на листья салата, облить соусом, присыпать для красоты орехами.','https:https://st.vkuso.ru/data/cache/thumb/e7/754a356ba86d1e7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7927,'Включить духовку, температуру довести до 175 градусов. Выстлать противень фольгой, кусочки курицы обмазать маслом, присолить, поперчить, переложить на противень, отправить на полчаса в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7927,'Лук мелко нарубить, морковь и сельдерей нарезать тонкой соломкой, чеснок выдавить через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7927,'В суповую кастрюлю влить масло, прогреть, обжарить чеснок, морковь, лук, сельдерей, добавить тимьян и лавровые листики, обжарить минут 7 до размягчения овощей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7927,'Вынуть мясо, разделить на волокна, удалить кожу с костями, залить в кастрюлю разбавленный водой бульон, дать супу  закипеть, положить курятину и рис, проварить полчаса при слабом нагреве.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7927,'При подаче в тарелки влить немного лимонного сока, к столу подать простой куриный суп с сельдереем и рисом пока еще горячий.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7928,'Насыпать на стол просеянную муку с солью, разрыхлителем и сахаром, сделать горку с отверстием на верхушке конуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7928,'Перемешать сок апельсина, яйца, масло, ванилин, залить в отверстие, замесить тесто, завернуть его в пленку, отправить в холодильник на пару-тройку часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7932,'Еще раз перемешать и дожарить до готовности.','https:https://st.vkuso.ru/data/cache/thumb/3e/8e9d751a3765d3e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7928,'Разделить колобок на 4 части, раскатать из каждого прямоугольник, смазать сливочным маслом, а затем вареньем, присыпать смесью дробленого ореха с изюмом, свернуть каждый в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7928,'Порезать рулеты на 12-14 частей, переложить булочки к чаю с малиновым вареньем на промазанный маслом и выстланный пергаментом противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7928,'Присыпать верх булочек сахаром с корицей, готовить минут 25-30 в заранее прогретой до 190 градусов духовке. Приятного чаепития!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Сливочное масло прогреть на сковороде, добавить нарезанный репчатый лук и потомить до мягкости. Снять с огня и немного остудить.','https:https://st.vkuso.ru/data/cache/thumb/69/354fb9b0c22df69_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Перемешать в большой емкости фарш из свиной шеи, майоран, лук, перец и соль.','https:https://st.vkuso.ru/data/cache/thumb/19/045347f09367019_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Промыть среднезерный рис проточной холодной водой.','https:https://st.vkuso.ru/data/cache/thumb/66/6f1326594203166_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Добавить рис в фарш, перемешать еще раз.','https:https://st.vkuso.ru/data/cache/thumb/04/8e7489986f35d04_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Вырезать у капусты кочерыжку, кочан опустить в кипящую воду на минуту. Вынуть, снять те листья, которые стали мягкими. Снова опустить остатки кочана в кипяток, вынуть, снять новую порцию листьев. Повторять процедуру несколько раз, пока все листья не будут сняты.','https:https://st.vkuso.ru/data/cache/thumb/2b/3c69bc4a34b0a2b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'На каждый лист положить небольшое количество фарша, завернуть. То же самое проделать с остальными порциями.','https:https://st.vkuso.ru/data/cache/thumb/6e/c9a36e26fdaa16e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'В сотейнике или глубокой кастрюле большого размера разогреть растительное масло, выложить голубцы в один слой, обжарить в течение двух минут, перевернуть и снова обжарить. Влить бульон или воду, соль – по вкусу. Закрыть блюдо крышкой, неплотно, чтобы выходил пар. Томить в течение получаса, голубцы несколько раз перевернуть. Добавить заранее протертые помидоры, перемешать и прогреть еще 20 минут, через 10 минут изделия перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/c6/fda5063d3eefdc6_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7929,'Воду перемешать с сахаром и мукой до однородного состояния. Смесь влить в голубцы вместе со сливками, посолить, перемешать. Томить еще 10 минут до загустевания соуса. Снять с огня, накрыть крышкой, оставить еще на 10 минут.    При подаче полить получившейся подливой.','https:https://st.vkuso.ru/data/cache/thumb/0e/30cf8aace93d50e_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Выложить очищенные грецкие орехи в форму для запекания, посушить в духовом шкафу при температуре 180 градусов в течение 10 – 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Сырые куриные яйца взбить с ряженкой и сахарозаменителем, добавить просеянную ржаную и гречневую муку с разрыхлителем, кукурузный крахмал, молотую корицу и сахарозаменитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Очищенную морковь натереть на мелкой терке, добавить в тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Орехи поломать кусочками среднего размера и добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Тесто перемешать, разлить в формочки и печь до готовности, проверить деревянной палочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7930,'Сыр рикотта взбить с мягким творогом, ванилью и сахарозаменителем. Остывшие коржи намазать полученным кремом, оставить для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7931,'Тонко нарезать очищенные и хорошо вымытые клубни картофеля.','https:https://st.vkuso.ru/data/cache/thumb/43/610dc528a59e843_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7931,'Соединить молоко, сливки, измельченный чеснок и прогреть смесь до загустения.','https:https://st.vkuso.ru/data/cache/thumb/4a/0ea75d824d8de4a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7931,'Форму смазать сливочным маслом, выложить картофель в один слой, соль и перец – по вкусу, посыпать тертым твердым сыром.','https:https://st.vkuso.ru/data/cache/thumb/5d/85bae9158ca495d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7931,'Слои чередовать до заполнения формы. Полить молочно-чесночной смесью, еще раз посыпать сыром и печь в течение 40 – 50 минут при температуре 175 градусов.','https:https://st.vkuso.ru/data/cache/thumb/40/9d9ac38f1972140_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7932,'Отварить фарфалле так, как указано на упаковке, в подсоленной воде. Куриную голень нарезать небольшими кусочками. Сливочное масло растопить вместе с оливковым. Мясо без соли обжарить в течение пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/72/3844c0d86a4da72_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7932,'Подлить натуральный мёд и соевый соус, перемешать и жарить до готовности. Попробовать мясо на вкус, если соли недостаточно – можно добавить соевый соус, если мало сладости – добавить мёд.','https:https://st.vkuso.ru/data/cache/thumb/5a/5604732d52a7a5a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7932,'Добавить к мясу готовые фарфалле, влить четверть стакана отвара от макарон, тушить две-три минуты, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/7b/3d9552edece7c7b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7933,'Перемешать сливочный сыр и «Рикотту», острый соус из перца чили «Харисса», мёд. Смесь должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7933,'Выложить её в обычный полиэтиленовый мешок с отрезанным кончиком или в кондитерский рукав. Полученной массой начинить оливки с удаленной косточкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7933,'Смешать с тертым сыром «Пармезан» панировочные сухари. Отдельно взбить сырое куриное яйцо. В третью миску всыпать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7933,'Фаршированные оливки обвалять в муке, окунуть в яйцо и присыпать сухарями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7933,'Растительное масло разогреть в кастрюле, обжаривать оливки порциями, до получения золотистой корочки. Вынуть шумовкой, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Песочное печенье размолоть в крошку любым доступным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Растопить сливочное масло, остудить, добавить в печенье. Замесить тесто, оно должно быть мокрым, но рассыпчатым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Застелить пищевой пленкой разъемную форму для запекания. Выложить тесто на дно, распределить равномерно по всей поверхности, поставить в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Желе со вкусом киви развести так, как написано на упаковке, перелить в емкость и поставить в холодильник для застывания. Затем добавить киви, нарезанное дольками. Еще одну порцию желатина развести горячей водой, долить в киви и снова убрать блюдо в холодильник до полного застывания, на это уйдет не менее четырех часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Довести почти до кипения молоко, залить им желатин, перемешать и дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Взбить сметану с сахарным песком с помощью миксера. Сахар должен полностью раствориться. Добавить ванилин, масса должна быть сладкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Влить тонкой струйкой молочно-желатиновую смесь, продолжать мешать. В массе не должны появиться комочки. Смесь осторожно вылить в форму с киви, поставить в холод еще на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7934,'Снять бортики, удалить пищевую пленку, выложить десерт на блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'В отдельную емкость просеять миндальную муку и сахарную пудру, добавить половину сырых куриных белков и хорошо перемешать с помощью лопатки до однородности. Дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'В небольшую кастрюлю влить воду, высыпать сахар, поставить сироп на огонь средней мощности, прогревать до кипения, помешивать. Максимальная температура – 118 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Вторую половину сырых белков взбить с лимонным соком до мягких пиков. Не переставая взбивать, влить с краю тонкой струйкой сахарный сироп. Взбивать еще три-четыре минуты, пока масса не остынет до 25 градусов. В несколько этапов добавить данную смесь к миндально-сахарной, перемешивать осторожно, движениями снизу вверх. Ингредиенты должны полностью соединиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Переложить массу в кондитерской мешок с насадкой круглой формы, отсадить изделия на лист пергамента или коврик из силикона. Кружки должны быть маленькими, диаметр – три сантиметра. Можно сделать трафареты на обычной бумаге с разметкой двух кружков, расположенных один внутри другого, диаметр первого – три сантиметра, второго – четыре. Выложить кружки под пергамент, они будут просвечивать. Отсаживать тесто по размеру меньшего кружка, во время отстаивания оно разойдется и достигнет второго. Чтобы избавиться от лишнего воздуха, можно постучать запястьем по дну приподнятого противня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Печь изделия в духовом шкафу при температуре 160 градусов в течение 12 – 14 минут. Перед окончанием выпечки дверцу духовки можно немного приоткрыть, чтобы выпустить лишний воздух. Если печенье готовится с миндальной мукой, то поверхность макаронс покроется корочкой очень быстро. Тесто, содержащее только сахарную пудру, подсыхает хуже, может понадобиться следующий график приготовления: выпекание в течение пяти минут при температуре 80 градусов, пятиминутная выстойка, основная выпечка при высокой температуре, заключительная выстойка в течение получаса или часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Готовые изделия переложить на ровную поверхность, через несколько минут макаронс легко отойдут от коврика или пергамента.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7958,'Отдельно размять в пюре мякоть авокадо, поперчить и посолить по вкусу, добавить немного лимонного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'В емкость небольшого объема влить жирные сливки, добавить к ним стручок и семена ванили, довести до кипения на тихом огне. Стручок удалить, сливки вылить на шоколад, дать постоять в течение полминуты, перемешать до соединения ингредиентов. Массу поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7935,'Крем должен загустеть, но остаться пластичным и мягким. Переложить массу в кондитерский мешок, использовать круглую насадку. Отсадить крем на макаронс, накрыть вторыми половинками, поставить изделия в холодильник на 12 – 24 часа. Длительная выстойка поможет добиться идеальной консистенции.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7936,'Хорошо вымыть сливы и груши, с плодов снять кожицу, мякоть нарезать кубиками и обжарить на сковороде с сахарным песком. Кусочки должны карамелизироваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7936,'Подготовленные фрукты выложить в форму для выпекания. Для приготовления мучной смеси перетереть сливочное масло с пшеничной мукой в крошку, добавить нарубленный на кусочки молочный шоколад. Насыпать полученную массу на фруктовую начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7936,'Печь десерт при температуре 190 градусов в течение 15 – 20 минут. Крошка должна немного подрумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Для блинчиков взбить сырые куриные яйца с водой и молоком, добавить соль по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/eb/852b5ac8c2cdfeb_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Сковороду разогреть, смазать оливковым маслом, вылить часть яичной смеси, распределить её по поверхности, огонь – средний. При первых признаках схватывания верхнего слоя, блинчик скрутить в рулет с помощью лопатки, перенести на тарелку и разрезать на несколько частей. Таким же образом поступить с остальными блинами.','https:https://st.vkuso.ru/data/cache/thumb/14/bc2affa59470114_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Куриное филе нарезать на тонкие средние куски, посыпать мясо солью, измельченным чесноком, приправой хмели-сунели и молотым перцем. Жарить с двух сторон на сильном огне по две-три минуты.','https:https://st.vkuso.ru/data/cache/thumb/56/d5ae2c29e333956_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Плод авокадо разрезать пополам, косточку вынуть, кожуру очистить, мякоть нарезать пластинками. Сбрызнуть лимонным соком, чтобы поверхность не почернела.','https:https://st.vkuso.ru/data/cache/thumb/14/aeb0b747500a814_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Вымыть рукколу, дать обсохнуть. Очистить и немного обжарить на сухой сковороде кедровые орешки.','https:https://st.vkuso.ru/data/cache/thumb/88/fa143fd411edc88_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7937,'Зеленый салат выложить в центр тарелок вместе с орешками, полить оливковым маслом, по краям выложить несколько кусочков блинчиков и нарезанный авокадо. Выложить куриное мясо, полить блюдо бальзамическим уксусом.','https:https://st.vkuso.ru/data/cache/thumb/d8/7b3f5cc589175d8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7938,'Намазать тонкий лаваш плавленым сыром, положить хорошо вымытые и обсушенные листья зеленого салата, кусочки филе малосольного лосося, завернуть рулет. Изделие обжать, уплотнить, нарезать поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7938,'Другой вариант: специальным ножом, предназначенным для чистки овощей, нарезать свежий огурец тонкими и длинными пластинками. Выложить на ровную поверхность, следующий слой – лосось, кусочки очищенного авокадо, свернуть рулет и сколоть его шпажкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7938,'Для третьего варианта понадобится тонкий омлет. Готовый продукт нарезать полосками, выложить малосольную рыбу, сладкий перец, свернуть рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7939,'Сварить сироп из воды и сахара, песок растворить в воде во время закипания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7939,'Довести температуру до 110 градусов, влить лимонный сок. Проварить до 115 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7939,'Сироп быстро охладить, поместив емкость в посуду со льдом. Когда температура массы достигнет пятидесяти градусов – взбить с помощью насадок для теста 10-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7939,'Смесь должна не только побелеть, но и затвердеть. Оставить на сутки. Затем помадку прогреть до 50 градусов, разбавить водой до нужной консистенции, покрыть выпечку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Перемешать муку с солью. Отдельно развести дрожжи в воде с сахаром. Вбить сырое куриное яйцо, всыпать просеянную муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Влить растопленное сливочное масло, замесить тесто. Время вымешивания – десять минут. Оставить в тепле, объем должен увеличиться в два раза. Тесто обмять, дать подойти еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Для приготовления начинки очистить и нарезать репчатый лук, добавить мясной фарш, жарить до изменения цвета, соль и перец – по вкусу. Прогревать до готовности, всыпать свежую зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7940,'Дать постоять в течение 40 минут, смазать верх смесью сметаны с сырым яйцом. Время выпекания – полчаса, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7941,'Телятину подготовить, порезать на куски примерно 3х3 см.','https:https://st.vkuso.ru/data/cache/thumb/6d/867a32f45535e6d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7941,'Нашинковать нижнюю часть (белую) стеблей лука, имбирь очистить и порезать тонкой соломкой, чеснок порубить. Прогреть в сковороде смесь кукурузного и кунжутного масел с добавлением сахара, когда появится карамель положить лук, имбирь, чеснок, добавить бадьян с корицей, тщательно перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a5/a5b69d5bf748ca5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7941,'Положить мясо, еще раз размешать, чтобы соус полностью покрыл кусочки, прожарить пару минут.','https:https://st.vkuso.ru/data/cache/thumb/5b/0e919edd033be5b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7941,'Влить соевый соус, воду, вино, тушить полчаса под крышкой, помешивая.','https:https://st.vkuso.ru/data/cache/thumb/17/692431b3dcb9717_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7941,'За это время тушеная телятина по-красному станет достаточно мягкой, а соус – густым.','https:https://st.vkuso.ru/data/cache/thumb/1e/e7dba9958ff791e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Замесить на подсоленном кефире с добавлением в конце соды тесто, муку всыпать порциями и перемешивать.','https:https://st.vkuso.ru/data/cache/thumb/2f/7485aa2723ff62f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Готовое тесто прикрыть пленкой, дать полчаса на созревание.','https:https://st.vkuso.ru/data/cache/thumb/63/88b476fe6018563_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Приготовить фарш с чесноком и луком, подсолить, поперчить, хорошо вымесить.','https:https://st.vkuso.ru/data/cache/thumb/6f/4c522014351666f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Из теста раскатать пласт не более 3 мм толщиной, вырезать кружки.','https:https://st.vkuso.ru/data/cache/thumb/ee/c65dc1e1d0828ee_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'На каждый положить примерно по чайной ложке фарша и по одной соленой соломке, чтобы она выглядывала сантиметра на 3 и хорошо держалась.','https:https://st.vkuso.ru/data/cache/thumb/b5/19bc191a99396b5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Сочник тщательно залепить, разрезать пополам на 2 «ножки», обмакнуть в разболтанное яйцо, обвалять в сухарях.','https:https://st.vkuso.ru/data/cache/thumb/14/ca438efcad5ec14_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Обжарить «Перепелиные ножки» под крышкой в хорошо разогретом масле с одной и другой стороны.','https:https://st.vkuso.ru/data/cache/thumb/56/20d3454d448da56_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7942,'Приготовить сливочно-лаймовый соус из йогурта, кефира, майонеза, сока лайма, чеснока, зелени кинзы, тмина и сухой петрушки, все поместить в блендер, подсолить, поперчить и хорошо взбить. Перед подачей желательно охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7943,'Чеснок порезать на тоненькие пластинки, обжарить до зарумянивания в сильно разогретом масле, убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7943,'Сыр измельчить на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7943,'Ломти хлеба чуть подсушить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7943,'Помидоры порезать на кольца, уложить на хлеб, полить маслом с чесноком, присыпать стружкой из сулугуни.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7943,'Поместить закуску аля Маргарита в микроволновку до расплавления сыра на пару минут, украсить листьями базилика и сразу подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Порезать цукини кубиками среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/a6/98505030db3a7a6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Брокколи поломать на соцветия.','https:https://st.vkuso.ru/data/cache/thumb/c3/9f4cc3a83a1b7c3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Порезать морковь, нашинковать лук.','https:https://st.vkuso.ru/data/cache/thumb/0d/da2167a4dde2b0d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Все овощи поместить в кастрюлю.','https:https://st.vkuso.ru/data/cache/thumb/6f/209bacc00ee956f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Залить водой, чтобы только их покрыть, довести до кипения, присолить, проварить около 10 минут. Готовые овощи переложить в холодную воду, а затем в блендер и приготовить из них пюре.','https:https://st.vkuso.ru/data/cache/thumb/1f/0a547ba11e5351f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Добавить нашинкованный укроп, кубики сыра, еще раз взбить.','https:https://st.vkuso.ru/data/cache/thumb/9e/9d9d0350c9bb09e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Отварить креветки, почистить, подрумянить в разогретом сливочном масле с лимонным соком, присолить.','https:https://st.vkuso.ru/data/cache/thumb/f5/ea2602b474c1bf5_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7944,'Разлить овощной суп–пюре по тарелкам, положить в каждую креветки, сверху посыпать натертым сыром и порубленной зеленью.','https:https://st.vkuso.ru/data/cache/thumb/dc/80479a9e30812dc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Мелко порезать лук, натереть крупно морковь, обжарить в масле до готовности, положить лавровый лист, закрыть крышкой, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/76/7f6ebe5720f5a76_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Обработать печень, промыть, вырезать протоки.','https:https://st.vkuso.ru/data/cache/thumb/99/434eaa00619e199_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Положить на специальную бумагу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Разбить в блендере до состояния пюре. Вбить яйца, всыпать муку, добавить пару столовых ложек сметаны и посолить.','https:https://st.vkuso.ru/data/cache/thumb/1a/bb1df351e9b0c1a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'На разогретом масле нажарить из полученной массы коржи-блинчики, дать им полностью остыть.','https:https://st.vkuso.ru/data/cache/thumb/0b/57947dfef7fe00b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Перемешать майонез, сметану, измельченную зелень и чеснок, соус перемешать. Собрать торт печеночный «Освежающий», положить корж смазать соусом, накрыть другим коржом, промазать морковной зажаркой, накрыть коржом.','https:https://st.vkuso.ru/data/cache/thumb/9a/0fed015125f369a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Смазать соусом, уложить на него тертые огурцы и корж.','https:https://st.vkuso.ru/data/cache/thumb/00/fbb0971790af300_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7945,'Операцию повторить, верх оформить по желанию.','https:https://st.vkuso.ru/data/cache/thumb/81/1365574d1b41781_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7946,'Растопить масло и шоколад на слабом огне, всыпать сахар, вбить яйцо, добавить ванильный экстракт, размешать, всыпать муку, очень хорошо все смешать, убрать с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7946,'Формочки смазать маслом, залить смесью, выпекать шоколадные кексики около 10 минут при 220 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7946,'Достать, как только верх чуть затвердеет, дать постоять 10 минут и вынуть из формочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7947,'Для пасты понадобится половина авокадо, репчатый лук, 1 ч.л. лимонного сока, соль, перец, 1 ч.л. оливкового масла. Смесь перемолоть с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7947,'Для второго вариант понадобится половина авокадо, давленый чеснок, 1 ч.л. оливкового масла, 1 ч.л. лимонного сока, перец молотый, соль. Массу растереть вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7948,'Сыр натереть на терке, добавить отваренное измельченное яйцо, майонез, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7948,'Хлеб для тостов подсушить на сковороде без масла или в тостере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7948,'Намазать смесью, сверху положить кусочек копченой колбасы или ветчину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Болгарский перец запечь до готовности в духовом шкафу, температура – 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Переложить в пакет на полчаса, затем очистить от семян и кожицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Лук-порей мелко нарезать и потушить со сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Всыпать муку, обжарить, а затем разбавить жирными сливками. Соль и перец – по вкусу, всыпать немного молотого мускатного ореха.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Полученный соус соединить с перцем, перемолоть при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7949,'Перелить готовый крем в креманки, украсить кусочками сыра моцарелла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7950,'В воду добавить сахарный песок, соль, душистый перец-горошек, гвоздику, лавровый лист, грибы. Ингредиенты довести до кипения, варить семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7950,'Влить уксус, варить под крышкой еще семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7950,'Оставить грибы в маринаде до остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7950,'При подаче на стол грибы можно нафаршировать сливочным сыром с чесноком и зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7950,'Для хранения заготовку разложить в банки и залить растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Растопить в кастрюльке 100 г сливочного масла, добавить к нему какао-порошок и сахар, мешать пока консистенция массы не будет однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Далее нужно вбить яйцо и всыпать ванилин, еще раз перемешать и снять емкость с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Добавить в масляную массу вафельные крошки, кокосовую стружку, орехи, хорошенько все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Смазать квадратную форму сливочным маслом, распределить по ней полученное тесто и спрессовать его, убрать форму с тестом на 20 минут в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Миксером взбить 70 г размягченного сливочного масла до кремообразного состояния, влить молоко и всыпать порошок для приготовления ванильного пудинга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Не прекращая взбивать массу, ввести в нее частями сахарную пудру, вылить получившуюся смесь на слой, который простоял в холодильнике 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Снова убрать форму в холод и не доставать, пока второй слой полностью не загустеет.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Для третьего слоя нужно в небольшой кастрюльке или сотейнике растопить оставшееся сливочное масло и кусочки шоколада, дать массе немного остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Получившуюся шоколадную массу распределить по кремовому слою и опять поместить форму в холодильник, пока последний слой не начнет твердеть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Далее нужно ножом наметить размеры будущих пирожных и, прежде чем шоколад застынет, десерт необходимо разрезать горячим ножом (начисто вытирать его после каждого разреза).',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7951,'Перед подачей канадское десертное пирожное «Нанаимо» следует охладить, а уже потом подавать пирожные к столу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7952,'Булочки для хот-дога или багет надрезать вдоль не до конца. Подсушить их на сухой сковородке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7952,'Картофель очистить и нарезать тонкой соломкой, выложить на сковороду с заранее прогретым растительным маслом. Посолить, поперчить. Обжарить до появления хрустящей румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7952,'На этой же сковороде обжарить сосиски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7952,'Маринованные огурцы и мясопродукты выложить на листья зеленого салата, начинку поместить в разрез булочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7952,'Сверху – слой жареного картофеля и «сеточка» из майонеза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Желатин замочить в воде, дать набухнуть, прогреть до полного растворения, посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Половину нормы моркови нарезать пластинками, вторую часть натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Сладкий болгарский перец и курагу нарезать соломкой, рыбное консервированное филе – кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Форму смазать, застелить бумагой для выпекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Продукты выложить слоями: морковь пластинками, зеленый консервированный горошек, часть рыбы, соль и перец по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Далее – половина нормы зелени укропа, половина сладкого перца, третья часть желатина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Верхние слои – курага и клюква, перец, укроп, рыбное филе, соль и молотый перец, зеленый горошек, тертая часть моркови, остатки желатина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7953,'Блюдо поставить в духовой шкаф на 40 минут, температура приготовления – 200 градусов. На ночь кушанье поместить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7954,'Приготовить несколько видов масел: сливочное с тертой колбасой, сливочное с тертым сыром и сливочное с рубленой зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7954,'Кусок серого  хлеба намазать зеленым маслом, накрыть вторым куском хлеба, намазать колбасным маслом, накрыть хлебом, намазать сырным маслом. Верхний слой – хлеб.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7954,'Положить в холодильник для застывания, затем аккуратно нарезать поперек, чтобы полоски были ровными.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7955,'Перемешать муку с разрыхлителем, солью и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7955,'Охлажденное сливочное масло натереть на терке, все ингредиенты быстро перетереть в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7955,'Вбить сырое куриное яйцо, замесить тесто. По необходимости можно добавить немного холодной воды. Готовый продукт поставить на полчаса в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7955,'Раскатать, разделить по формам. Наколоть вилкой в нескольких местах, поставить в морозильную камеру на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7955,'Достать из морозилки и выпекать от 10 до 15 минут, температура – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7956,'Сырную массу можно приготовить двумя способами: перемешать тертый сыр с рублеными отваренными яйцами и майонезом или тертый сыр со сливочным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7956,'Нарезать кубиками сладкий перец, мякоть авокадо, ветчину, крабовые палочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7956,'Начинки закатать в сырную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7956,'Каждый сырный шарик запанировать. Использовать разные виды панировки: закуску с ветчиной закатать в сухари с сухим чесноком, с крабовыми палочками – в сухарях с накрошенным желтком, с авокадо – в сухарях с рубленой зеленью, с болгарским перцем – в сухарях с молотой паприкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7957,'Хорошенько взбить яйца миксером, добавить к ним сахар и ванильный сахар, не торопясь подмешать частями муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7957,'Яблоки помыть, очистить от кожуры, достать все косточки и нарезать каждое яблоко небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7957,'Форму промазать маслом, после чего посыпать манной крупой или простой мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7957,'Далее нужно либо выложить дно формы кусочками яблок, добавить немного клюквы и залить все тестом, либо вылить в форму половину теста, распределить по нему яблоки с клюквой и влить остальное тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7957,'Выпекается ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7958,'Приготовить пасту с помощью блендера: смешать сливочный сыр, морковь и крабовые палочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7975,'Банан очистить, размять, взбить с молоком до образования однородной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7958,'Хлеб тостовый подсушить в тостере или на сковороде, вырезать кружки диаметром 5 см. На один кружочек из хлеба намазать крабовую смесь, закрыть вторым, сверху – пюре с авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Отварить куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Очистить и нарезать на кусочки мякоть грейпфрута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Курицу, болгарский перец и зеленую часть китайской капусты нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Перемешать мясо с майонезом, его же добавить в 1/2 часть капусты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Собрать послойно: куриное мясо, грейпфрут, консервированная сладкая кукуруза, сладкий перец, пекинская капуста с майонезом. Каждый слой разровнять, чуть утрамбовать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7959,'Посыпать блюдо свежей рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7960,'До полной готовности отварить картофель, после чего сделать из него пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7960,'В большой емкости хорошенько перемешать пюре, тертый сыр, муку, яйцо, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7960,'Добавить в полученную массу соль, сметану, рубленый укроп и специи, перемешать еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7960,'Из получившегося теста сформовать котлеты, которые обжарить до подрумянивания на сковороде с большим количеством растительного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7960,'Готовые котлеты из картофеля с сыром и укропом подавать к столу в горячем виде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'В трехлитровую кастрюлю поместить куриное филе, залить его водой и дать бульону закипеть, после чего его нужно посолить (1 ч.л.), добавить перец (2 горошины) и несколько лавровых листиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'После закипания варить бульон в течение 20 минут, по истечении которых вынуть мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'Очищенный картофель и лук порезать кубиками, на терке потереть морковь, плавленый сыр потереть на терке (можно порезать небольшими кубиками).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'В кипящий бульон закинуть подготовленный картофель и с момента закипания варить его не дольше 5-7 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'Масло сливочное растопить на сковородке, сначала выложить лук, далее добавить к нему морковь, овощи чуть-чуть поперчить, посолить, слегка обжарить и переложить в суп, который продолжить варить снова 5-7 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'Далее положить в суп порезанное небольшими кусочками куриное мясо, по прошествии 4 минут добавить в суп подготовленный плавленый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'Содержимое кастрюли тщательно перемешать и снять емкость с супом с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7961,'Французский сырный суп с курицей перед подачей посыпать рубленой зеленью и подать к столу, при желании дополнив гренками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7962,'Перемешать обезжиренный творог и пищевую соду, оставить массу на час при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7962,'Подходящую емкость, форму или мисочку застелить пищевой пленкой. Добавить к творогу молоко, соль, сырое куриное яйцо, смесь взбить при помощи блендера до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7962,'Массу переложить в кастрюлю, греть на тихом огне, помешивать. Творожная смесь должна полностью расплавиться, это произойдет через 5 – 10 минут. Подержать продукт на огне еще столько же времени, помешивать, не доводить до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7962,'Готовый сыр переложить в другую емкость, накрыть сверху пищевой пленкой, поставить в холодильник на три-четыре часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7963,'Перемешать творог, целое сырое куриное яйцо и дополнительный белок, всыпать овсяную крупу или измельченные хлопья, молотую корицу или другие специи. В смесь по желанию можно добавить сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7963,'Выложить тесто на противень в виде лепешек, печь в течение 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7964,'Мелко порезать помытые помидоры (лучше не слишком сочные, или слить лишний сок), измельчить зелень, мелко натереть твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7964,'Сложить все подготовленные ингредиенты в миску, добавить пропущенный через чесночницу (пресс) чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7964,'Содержимое миски тщательно перемешать с майонезом, выложить получившуюся начинку на картофельные чипсы (лучше всего выкладывать начинку прямо перед подачей на стол, т.к. чипсы могут размякнуть).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7964,'Сверху чипсы с сыром и помидорами на закуску украшаются маслинами или оливками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7965,'Стручки красного болгарского перца крупного размера очистить от семенных камер, испечь до готовности, снять кожицу, мякоть посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7975,'Все ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7965,'Отдельно перемешать сырое яйцо, нарезанную зелень петрушки, сельдерей, кинзу, укроп, тертую брынзу. Массу поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7965,'Наполнить испеченные стручки, смочить в яйце, обжарить на сковороде в течение нескольких минут с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7966,'Черешковый сельдерей бланшировать в кипящей воде с солью, проварить в течение двух минут, сразу охладить в другой емкости, с холодной водой. Нарезать продукт на небольшие кусочки, ширина – один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7966,'Для соуса перемешать сметану или оливковое масло с приправой «Васаби» и рисовым уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7966,'Тигровые креветки отварить, нарезать кусочками, сладкий красный болгарский перец – кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7966,'Смесь заправить полученным соусом, соль и перец – по вкусу. Перемешать. Подать салат в охлажденном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7967,'Сырые куриные яйца охладить, отделить желтки от белков. Белки взбить в плотную пену с помощью миксера, затем добавить ванилин и сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7967,'Противень застелить бумагой для выпечки, сухой чайной ложкой выложить полученную массу в виде небольших лепешек. Вместо ложки можно взять кондитерский мешок или шприц.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7967,'Поставить блюдо в теплую духовку на час, температура для выпекания: 80 – 100 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7967,'Для крема соединить какао-порошок и воду, масса должна быть густой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7967,'Готовые безе соединить по два с помощью шоколадного крема и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7968,'Большое яблоко очистить от кожуры, натереть, добавить сырое куриное яйцо, не зернистый творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7968,'Ингредиенты перемешать вилкой, выложить в формочки до верха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7968,'Поставить суфле на пять минут в микроволновую печь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7968,'Перевернуть десерт на тарелку, посыпать молотой корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7969,'Багет нарезать поперек, с помощью формочки сделать небольшие круглые отверстия.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7969,'Смазать сливочным маслом, в отверстия вставить свернутые розочками тонкие ломтики красной рыбы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7969,'Закуску украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7970,'Куриное филе отварить в подсоленной воде, остудить, нарезать кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7970,'Томаты нарезать полукольцами, пекинскую капусту нашинковать и полить свежим лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7970,'Твердый сыр натереть на терке с мелкими ячейками. Мелко покрошить зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7970,'Салат выкладывать на тарелку слоями: капуста, помидоры, курица. Соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7970,'Смазать массу сметаной, посыпать сыром и луком. Слои повторить в том же порядке, сверху должен оказаться сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7971,'Малосольную красную рыбу мелко нарезать, перемешать с рубленой зеленью и сливочным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7971,'Из помидоров примерно одного размера удалить сердцевину, наполнить полученной массой, украсить свернутым ломтиком рыбы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7972,'Очистить, мелко нарезать и обжарить репчатый лук, добавить измельченный помидор, заранее отваренное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7972,'Начинку выложить на половину лаваша, по краю выложить тонкие полоски сыра, накрыть второй половинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7972,'Жарить с двух сторон на сковороде, сыр должен расплавиться и соединить края лепешки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7972,'Готовый чебурек можно смазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7973,'Клубни картофеля отварить, размять вилкой до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7973,'Рыбу горячего копчения перебрать, удалить все кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7973,'Репчатый лук мелко нарезать и ошпарить кипятком, чтобы ушла лишняя горечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7973,'Все продукты соединить, добавить майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7974,'Ломтики хлеба подсушить на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7974,'Мелко нарезанный репчатый лук быстро обжарить, добавить квашеную капусту, прогреть все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7974,'В этой же сковороде обжарить тонко нарезанные ломтики колбасы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7974,'В часть обжаренной капусты добавить майонез, во вторую половину – тертое яблоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7974,'Капустную массу выложить на хлеб, сверху – ломтики колбасы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7975,'Половину нормы овсяных хлопьев измельчить при помощи блендера или кофемолки. Добавить какао-порошок и кокосовую стружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7975,'Форму для выпекания выложить бумагой. Сформовать из массы шарики мокрыми руками, немного приплюснуть, лепешки выложить на противень или в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7975,'Печь в течение 20 минут при температуре 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Рис выложить в кастрюлю и залить водой, она должна покрывать крупу на полтора сантиметра. Варить до полного впитывания влаги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Куриное филе пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Мелко нарезать белокочанную капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Смешать все компоненты, добавить сырое яйцо, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Из готового фарша сформовать небольшие котлеты круглой формы, выложить в сковороду с бортиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Для подливы смешать консервированные томаты в собственном соку со сметаной, лучше это сделать с помощью блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Порубить зелень петрушки и укропа, добавить в соус, посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7976,'Залить смесью голубцы, тушить блюдо под крышкой в течение получаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7977,'Краснокочанную капусту нарезать в виде тонкой соломки, немного помять руками, чтобы продукт стал мягче.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7977,'Морковь очистить и натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7977,'Удалить у красного болгарского перца семенные камеры, нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7977,'Для приготовления заправки смешать оливковое масло, соль, лимонный сок, молотый черный перец. Заправить соусом салат и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7978,'Филе рыбы хорошо вымыть и разделить на четыре порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7978,'Чеснок и лимон очистить, натереть или порубить с помощью кухонного комбайна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7978,'Добавить уксус, белое сухое вино, тертый имбирь, соль, сахарный песок и соль. Массу растереть до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7978,'Куски рыбы натереть полученным маринадом, поставить в холодильник на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7978,'Каждый кусок с добавлением маринада завернуть в фольгу, печь в духовом шкафу при температуре 180 градусов в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'Цуккини и баклажаны нарезать кольцами, сладкий желтый болгарский перец – треугольниками, шампиньоны – пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'Приготовить соус из лимонного сока, оливкового масла и измельченной зелени петрушки, чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'Овощи обжарить на сковороде-гриль в течение четырех минут с одной стороны, перевернуть и прогреть еще две минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'Во время приготовления продукты смазать масляным соусом. Выложить мясо на сковороду, обжарить две минуты, затем перевернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'В глубокую салатницу выложить салатные листья и рукколу, полить тем же соусом. Сверху выложить еще теплые овощи и говядину.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7979,'Полить блюдо остатками заправки, украсить веточками розмарина и помидорами черри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7980,'Тыкву очистить от кожицы, если она не слишком плотная, то можно этого не делать. Нарезать продукт на ломтики произвольной формы, выложить на противень, застеленный бумагой для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7980,'Головку чеснока поделить на дольки, очистить, положить к тыкве. Овощи поперчить и посолить, смазать оливковым маслом с помощью кулинарной кисти, посыпать сухими прованскими травами, полить бальзамическим уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7980,'Печь блюдо при температуре 175 градусов в течение 40 минут. Продукты должны стать мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7981,'Небольшую луковицу и чеснок мелко порубить и обжарить в сотейнике с растительным маслом, на приготовление обжарки понадобится три-четыре минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7981,'Добавить томатную пасту, прогреть еще две минуты. Влить в массу овощной или куриный бульон, посолить по вкусу, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7981,'Всыпать рис, перемешать, потомить под крышкой в течение 15 минут на небольшом огне. Жидкость должна выпариться полностью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7982,'Положить в чашу мультиварки сливочное масло и томатную пасту, выставить режим «Выпечка», помешивая, обжарить смесь 10 минут, переложить томат в миску, залить листья капусты кипятком, дать постоять 10 минут, после чего листья разобрать, если готовить блюдо из зимней капусты, то листья придется чуть проварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7989,'Разбить яйцо, перемешать, влить соду, гашенную уксусом, сахар и муку. Смесь вымешать блендером, разлить по формочкам, заполнив их на 2\3.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7982,'Приготовить из свинины, говядины и лука фарш, дважды пропустив через мясорубку, или взять готовый, промыть рис, смешать с фаршем, приправить черным перцем, посолить, добавить для пикантности немного порошка листьев мяты, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7982,'Выложить на лист капусты немного фарша, свернуть ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7983,'Чеснок очистить и мелко порубить. Измельчить зелень петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7983,'Разогреть на среднем огне, на сковороде, оливковое масло. Добавить подготовленный чеснок, прогреть, через две минуты добавить петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7983,'Стейки вымыть, обсушить с помощью бумажных полотенец, посолить по вкусу и выложить на сковороду. Кусочки не должны касаться друг друга. Добавить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7983,'Жарить рыбу в течение 10 – 12 минут, перевернуть лопаткой, жарить с другой стороны еще столько же времени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7983,'Готовый хек выложить на тарелки, полить зеленым соусом и сразу подать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7984,'Хлебные тосты подсушить в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7984,'Каждый кусочек намазать сыром и прогреть до расплавления в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7984,'Сверху положить груши, нарезанные пластинками, на другие бутерброды – хурму или просто полить сыр медом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7985,'Перемешать оливковое масло с кардамоном, паприкой, солью, перцем, свежим измельченным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7985,'Тыкву очистить и нарезать кусками толщиной в сантиметр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7985,'Намазать полученным маринадом и оставить для пропитывания на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7985,'Обмакнуть в муку, жарить на масле с двух сторон до румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7986,'Готовить блюда из гороха обычным способом хлопотно: варить надо долго, постоянно мешать и следить, чтобы не пригорело, но использование современной техники позволяет сэкономить время и приготовить вкусное пюре из гороха в мультиварке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7986,'Хорошо промыть дробленый горох, засыпать в мультиварку, залить водой, посолить, вместо соли можно использовать 1/3 бульонного кубика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7986,'Готовить в режиме «Тушение» 2,5 часа, через 1,5 часа можно всыпать нашинкованный мелкими кубиками лук, после отключения добавить сливочное масло и дать потомиться с закрытой крышкой, по истечении 10 минут можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7986,'Во время поста вместо сливочного можно добавить перед включением прямо в воду с горохом пару ложек растительного масла, блюдо вкусное и горячее и холодное',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7987,'Нарезать соломкой сладкий перец и морковку, помидоры – дольками, чеснок и зелень порубить.','https:https://st.vkuso.ru/data/cache/thumb/20/efd1671f4407720_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7987,'Сложить все в керамическую форму, присыпать кедровыми орешками, посолить, полить маслом.','https:https://st.vkuso.ru/data/cache/thumb/ef/588756707030aef_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7987,'Поставить форму в духовку на треть часа, после того, как перец и помидоры чуть запекутся, овощи перемешать и уложить на них подсоленную рыбу, поперчить, вернуть в духовку. Рыбное филе с запеченными овощами будет готово через 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/eb/7ab61e74c5027eb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7987,'На подогретую большую тарелку положить овощи, сверху – рыбу, посыпать петрушкой, побрызгать лимонным соком.','https:https://st.vkuso.ru/data/cache/thumb/dd/cf58960d87dcadd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Филе помыть, обсушить, надрезать, сделать кармашек, аккуратно отбить. Приправить мясо перцем, посолить.','https:https://st.vkuso.ru/data/cache/thumb/0b/a1ab1293b47b70b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Вложить в прорезь по ломтику сыра с ветчиной.','https:https://st.vkuso.ru/data/cache/thumb/7c/79d42f50dc3417c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Сколоть обе половинки зубочистками.','https:https://st.vkuso.ru/data/cache/thumb/1b/f79c98942b0271b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Взбить яйцо с небольшим количеством воды.','https:https://st.vkuso.ru/data/cache/thumb/4d/4cdedbc56e24b4d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Обвалять шницель «Кордон блю» с сыром и ветчиной в муке, обмакнуть в яйцо, а потом в сухари.','https:https://st.vkuso.ru/data/cache/thumb/c0/f7ec6387baf92c0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Положить шницели на четверть часа в морозилку. Раскалить в сковороде масло, обжарить с каждой стороны до золотистой хрустящей корочки.','https:https://st.vkuso.ru/data/cache/thumb/52/abe5f8dc729c452_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7988,'Прогреть духовку до 200 градусов, довести блюдо до готовности (6-7 минут), убрать зубочистки, подать к столу в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7989,'Залить манку кефиром, оставить на 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Отправить колбаски из творога минут на 15 в морозилку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7990,'Перемешать быстродействующие дрожжи с сахаром, водой, солью, мукой, майонезом, маслом и коньяком, вымесить тесто, убрать в тепло, дать подняться.','https:https://st.vkuso.ru/data/cache/thumb/e7/5ed2b8eebbf10e7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7990,'Измельчить лук с грибами, обжарить по отдельности, перемешать, влить сметану, протушить 10 минут, можно положить еще и порубленную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7990,'Духовку прогреть до 160 градусов. Раскатать из теста два пласта, один должен быть чуть больше, чтобы сформовать бортики. Смазать форму маслом, положить тесто, сделать бортики высотой около 2 см, заполнить начинкой.','https:https://st.vkuso.ru/data/cache/thumb/92/96104c1c18b0d92_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7990,'Прикрыть пирог второй половинкой теста, хорошо защипать края, по центру сделать небольшое окошечко. Выпекать пирог примерно 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/f0/23a9de05a8a4ef0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7990,'Достать, смазать верхнюю корочку сливочным маслом, прикрыть тканью, дать постоять минут 15 и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/68/a9a08b488ff1068_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7991,'Замочить в холодной воде на ночь не лущеный горох (можно на 2-3 часа), нарезать кусочками мясо, выставить режим «Выпечка», обжарить 10 минут, нашинковать лук, натереть морковь, всыпать в мультиварку, обжарить еще 10 минут, добавить нарезанный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7991,'Всыпать разбухший горох, залить водой, приправить черным перцем, гвоздикой, лавровым листом, посолить, переключить режим на «Тушение», готовить гороховый суп с копчеными свиными ребрышками в мультиварке полтора часа (готовность определить по гороху), выключить и дать настояться, но можно есть сразу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7991,'Разлить по тарелкам, добавить гренки, присыпать измельченной зеленью, сдобрить по вкусу ложечкой сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7992,'Грибы замочить в кипятке на полчаса, отжать, порезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7992,'Обжарить колечки лука, а потом грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7992,'Отварить рис, перемешать с грибами и луком, немного прогреть, добавить соевый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7992,'Приготовить из пары яиц омлет, порезать на полоски, добавить его и нашинкованную мелко зелень в рис с грибами, осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7993,'В форму уложить ломти черного хлеба, присыпать укропом, положить по ломтику сыра.','https:https://st.vkuso.ru/data/cache/thumb/54/02086dfb0aab154_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7993,'Прикрыть хлебом, уложить опять сыр и присыпать укропом.','https:https://st.vkuso.ru/data/cache/thumb/54/8b98fe23ea97254_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7993,'Взбить вилкой молоко с яйцами, подсолить, поперчить, вылить в форму.','https:https://st.vkuso.ru/data/cache/thumb/25/8839a6e8556f325_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7993,'Укрыть форму пленкой, поставить в холодильник на 8 часов или на всю ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7993,'Разогреть до 180 градусов духовку, поставить хлебный укропно-сырный пирог, выпекать полчаса, подавать горячим.','https:https://st.vkuso.ru/data/cache/thumb/40/4836de42bce1940_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7994,'Взболтать яйца с сахаром, влить молоко, растопленное масло, всыпать муку, вымесить тесто, разделить на 3 части, обернуть пленкой, убрать в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7994,'Крупно натереть тесто, выложить на промазанный маслом пергамент тонким слоем, испечь несколько коржей при 160 градусах до темно золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7994,'Для приготовления торта порубить обжаренные орехи, руками размять крошу, перемешать все с вареной сгущенкой, выложить в глубокую тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7995,'Лимоны вымыть под горячей водой, обдать кипятком, разрезать, выдавить сок в глубокую миску.','https:https://st.vkuso.ru/data/cache/thumb/75/4091797b8cce075_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7995,'Всыпать сахар, положить половинки, добавить мяту, ваниль или ванильный сахар, розмарин.','https:https://st.vkuso.ru/data/cache/thumb/8f/95b8e4c9c91ab8f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7995,'Закипятить воду, залить в лимоны, размешать, дать постоять полчаса и остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7995,'Перелить сквозь сито лимонад с мятой и розмарином в кувшин и поставить в холодильник, подать со льдом мятой и ломтиками лимона.','https:https://st.vkuso.ru/data/cache/thumb/d9/c5a350e130efcd9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7996,'Смазать дно чаши мультиварки растительным маслом, порезать мясо как для гуляша, переложить в чашу, а сверху – нашинкованный лук, мелко порезать картофель и высыпать на лук, на него слоями нарезанный полукольцами сладкий перец, кружочки моркови, помидоров, кубики баклажана и порезанную капусту, каждый слой приправить по вкусу и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Десерт поставить в холодильник на ночь, утром вынуть из формы и посыпать какао-порошком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7996,'Закрыть крышку, выставить режим «Тушение», а время 2 часа, после приготовления разложить по тарелкам, присыпать измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7996,'Дамлама в мультиварке будет вкуснее, если все овощи будут нарезаны мелко, для любителей можно добавить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7997,'Замочить фасоль на ночь, слить воду, залить в кастрюлю 2,5 литра свежей воды, высыпать фасоль, варить, закрыв крышкой практически до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7997,'Натереть крупно морковь, картофель порезать брусочками, нашинковать лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7997,'Из моркови с луком сделать зажарку, добавить в конце томатную пасту, перемешать, протушить, снять с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7997,'Когда фасоль будет мягкой положить в фасолевый супчик картофель, а чуть позже томатную заправку, проварить 10 минут до полной готовности картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7997,'За пару минут до окончания варки выдавить в кастрюлю чеснок, добавить зелень, лавровый лист. К столу подавать со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7998,'Поместить все ягоды в блендер, влить сахарный сироп, взбить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7998,'Разлить граниту по формочкам, поставить в морозилку на 5 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7998,'Раз в час смесь перемешивать до полного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7999,'Нашинковать капусту и лук, нарезать на кубики картофель, измельчить на терке морковь, разрезать на четвертинки свеклу, поместить все овощи кроме свеклы в чашу мультиварки, залить водой, заправить специями, посолить, сверху установить контейнер пароварки со свеклой, закрыть крышку, выставить режим «Тушение» на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7999,'Вынуть свеклу, оставив мультиварку в режиме «Подогрев», дать свекле немного остыть, измельчить на терке или порезать на кубики, полить соком лимона, положить томатную пасту, переложить смесь в мультиварку, перемешать, выдавить несколько долек чеснока, всыпать измельченную зелень, приправить по вкусу и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (7999,'Готовый постный борщ без зажарки в мультиварке должен настояться, при подаче к столу в тарелки добавить по ложечке сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Обжарить в масле кубики моркови и нашинкованный лук.','https:https://st.vkuso.ru/data/cache/thumb/c0/24e729da62335c0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Порезать грибы на кусочки и добавить в сковороду, перемешать, тушить 10 минут на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/95/f7608959fee0595_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Порезать кубиками молодой кабачок, высыпать его к грибам и моркови.','https:https://st.vkuso.ru/data/cache/thumb/a7/b94301e81ebf2a7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Приправить овощи карри имбирем, карри и шафраном, посолить, перемешать, тушить еще 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/26/c47d4619d654626_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Нарезать кубиками помидор добавить к овощам вместе с раздавленным прессом чесноком, перемешать, тушить 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/8a/175e6302ec4598a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8000,'Снять с плиты, посыпать порубленным укропом.','https:https://st.vkuso.ru/data/cache/thumb/d8/2634fa027f241d8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'Хорошо перемешать разрыхлитель, сахарную пудру, имбирь молотый, влить охлажденную воду и масло, вымесить тесто, завернуть в пленку, положить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'Из лимона отжать сок, вылить в порезанные груши, перемешать, орехи порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'На бумагу для выпечки положить тесто, накрыть вторым листом, раскатать в пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'Уложить кусочки груши, края теста завернуть внутрь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'Выпекать галету около 15 минут в духовке при температуре 200 градусов, снизить нагрев до 180 градусов, выпекать еще полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8001,'Присыпать ореховой крошкой и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8002,'Засыпать промытую гречку в чашу мультиварки, залить водой в обычной пропорции 1:2, добавить соль, выставить режим «Гречка», через полчаса гречка в мультиварке будет готова, дать потомиться с закрытой крышкой минут 10-15, разложить по тарелкам и добавить в каждую сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8002,'Интересно, что в Индии гречку называли когда-то черным рисом, а в ряде других стран — «черной пшеницей», поскольку каша получалась черного цвета, ее считали пищей для бедняков, в отличие от белого риса, который ели аристократы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8003,'Клубни примерно одного размера почистить, разрезать вдоль, сделать с помощью чайной ложки подобие лодочек.','https:https://st.vkuso.ru/data/cache/thumb/db/727896a66ce73db_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Шоколад растопить на водяной бане.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8003,'Из порезанного на кубики филе с добавлением лука, соли, перца петрушки и пары ложек майонеза приготовить фарш, заполнить с горкой половинки картофеля.','https:https://st.vkuso.ru/data/cache/thumb/a1/c019abf1600aca1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8003,'Для подливки перемешать стакан подсоленной воды с майонезом и перцем. Переложить картофельные лодочки, фаршированные мясом в рукав, влить подливку, тщательно завязать и поднять края рукава, поставить в духовку швом вверх, готовить полчаса при среднем нагреве.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Порезать овощечисткой цукини тонкими «ленточками».','https:https://st.vkuso.ru/data/cache/thumb/02/da3cc7f5a2dae02_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Смазать каждую сливочным сыром.','https:https://st.vkuso.ru/data/cache/thumb/c4/fb9338d875924c4_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Порезать морковь, перец и огурец соломкой.','https:https://st.vkuso.ru/data/cache/thumb/a0/36da11ff29447a0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Выложить с краю на сыр.','https:https://st.vkuso.ru/data/cache/thumb/ab/7979d050522d9ab_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Свернуть цукини в трубочку.','https:https://st.vkuso.ru/data/cache/thumb/e6/2bf5b5c3d1eb0e6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8004,'Закрепить вегетарианские овощные роллы со сливочным сыром деревянной зубочисткой.','https:https://st.vkuso.ru/data/cache/thumb/67/bd4d9c8329e0867_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Для приготовления соуса перемешать кетчуп и лимонный сок, добавить специи и еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/af/b80957c3a4596af_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Измельчить грибы.','https:https://st.vkuso.ru/data/cache/thumb/b1/9e438a80cc28eb1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Подготовленные ножки уложить в форму.','https:https://st.vkuso.ru/data/cache/thumb/4c/e1f701d022a5b4c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Посолить, полить равномерно соусом, треть соуса оставить.','https:https://st.vkuso.ru/data/cache/thumb/4a/4a75d25e70f5d4a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Положить слой грибов, залить остатками соуса. Долить к куриным ножкам с грибами и специями воды (до половины формы).','https:https://st.vkuso.ru/data/cache/thumb/28/5a1c967a59cd128_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8005,'Готовить при 200 градусах около 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8006,'В чашу мультиварки положить сливочное масло, нашинкованный лук, замороженные грибы, перемешать, добавить перебранную и промытую гречневую крупу, залить все бульоном, посолить, выставить на режим «Гречка», когда по окончании режима (примерно через 30 минут) гречка в мультиварке с грибами и луком будет готова перемешать ее, подавать со сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8007,'Помидоры порезать кружочками, перец – крупными кусками, нашинковать лук, порезать сельдерей и огурцы, консервы размять, все перемешать. Подсолить, поперчить, заправить майонезом, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/77/7971577e2e3ac77_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8007,'Собрать сэндвич с тунцом и солеными огурчиками: булочку разрезать пополам, уложить листики салата, смазать пастой из рыбы, уложить сверху помидоры, перец и зелень.','https:https://st.vkuso.ru/data/cache/thumb/38/093b38efeda4238_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Порезать курицу на тонкие полосы, уложить в глубокую миску, залить смесью лимонного сока с мускатным орехом, солью и перцем, перемешать, слегка помять, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/5e/487d4cdb260ad5e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Сварить морковь, обжарить в масле лук, добавить грибы, слегка обжарить, влить сливки, размешать, немного протушить.','https:https://st.vkuso.ru/data/cache/thumb/72/dd4d4ece4dbb472_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Подготовить форму, смазать маслом, дно и стенки выложить частью мясных полосок.','https:https://st.vkuso.ru/data/cache/thumb/a5/6a404f389df22a5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Обсыпать сырной стружкой.','https:https://st.vkuso.ru/data/cache/thumb/c3/018b5cc908f66c3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Уложить слой грибов, прикрыть крупно натертой морковью.','https:https://st.vkuso.ru/data/cache/thumb/82/bfc45b18e99b382_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Выложить оставшиеся кусочки мяса по спирали.','https:https://st.vkuso.ru/data/cache/thumb/92/409d77415103792_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8008,'Поставить форму с пирогом «Чайная роза» с мясом и грибами в заранее прогретую до 200 градусов духовку на полчаса, слить выделившийся сок, присыпать сыром. Вернуть форму в духовку до его расплавления и подрумянивания. Готовому блюду дать постоять 10 минут и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/c7/a9103f4cf10f3c7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8009,'Перебрать и промыть речку, нарезать свежие или замороженные шампиньоны, нашинковать лук, натереть морковь, переложить лук в чашу с растительным маслом, обжарить в режиме «Выпечка» 10 минут, добавить фарш и морковь, прожарить еще 10 минут, всыпать грибы, обжарить 20 минут, добавить крупу, залить водой, посолить, переключить на режим «Гречка», через 30 минут гречневая каша с грибами и мясом в мультиварке будет готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Отправить в холодильник на 30 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Крупно натереть морковь, мелко нашинковать лук, вынуть из сковороды мясо, обжарить лук до мягкости, всыпать морковь, жарить еще 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/45/da1631e16c9bf45_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Очистить клубни картофеля, порезать каждый на кусочки (4-6 шт.), переложить в миску, залить подсоленной сметаной, оставить на треть часа для пропитки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Заполнить картофелем горшочки до половины, далее добавить морковку, мясо и лук, доложить до верха горшочки картофелем. В каждый влить немного воды и сметаны, чтобы покрыть верх картофеля.','https:https://st.vkuso.ru/data/cache/thumb/bc/54c4c3631c92ebc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Положить по кусочку масла, плотно закрыть фольгой. Поставить в духовку с температурой 200 градусов на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/4d/7406f91f31f194d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Удалить осторожно фольгу, продолжить готовить в духовке еще полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8010,'Тушеная картошка с мясом и сметаной в горшочках должна покрыться корочкой золотистого цвета. Присыпать рубленной петрушкой, молотым черным перцем и зернами горчицы.','https:https://st.vkuso.ru/data/cache/thumb/b5/63b4c034e4beeb5_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Поджарить орехи на сухой сковороде, измельчить до состояния мелкой крошки.','https:https://st.vkuso.ru/data/cache/thumb/e3/c07210d88dbbfe3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Перемешать в однородную массу с просеянной мукой, какао-порошком и разрыхлителем.','https:https://st.vkuso.ru/data/cache/thumb/f2/5200c00dc2b4df2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Разбить в чашу миксера яйца, взбить на максимуме минуту.','https:https://st.vkuso.ru/data/cache/thumb/80/1408715130b8580_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Всыпать сахарный песок, взбить еще 7 минут при высокой скорости. Всыпать порциями мучную смесь, вымешивать после каждого добавления деревянной лопаточкой. Влить масло и минералку.','https:https://st.vkuso.ru/data/cache/thumb/69/fa0330244c66469_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Смазать чашу мультиварки маслом, притрусить мукой. Заполнить тестом чашу, выставить режим «Выпечка» и время 65 минуты.','https:https://st.vkuso.ru/data/cache/thumb/9f/4a821627e025b9f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Температура для духовки чуть меньше – 150 градусов, готовить бисквит на минералке около 45 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Для приготовления ганаша поломать на кусочки плитку шоколада. Закипятить подсоленные сливки, в ковше довести до состояния темной карамели сахар, влить сливки, размешать до однородности, добавить масло, перемешать до полного его растворения, влить к шоколаду, перемешать до однородности, взбить блендером.','https:https://st.vkuso.ru/data/cache/thumb/63/3781ccaae5a2763_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8011,'Для пропитки смешать сгущенку, ликер и молоко, равномерно полить остывший бисквит, сверху покрыть шоколадной смесью.','https:https://st.vkuso.ru/data/cache/thumb/b4/2013049913d0db4_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8012,'Подготовить печень: куриную промыть и нарезать, а если готовить из говяжьей, то вымочить около часа в холодной воде, а потом нарезать, лук мелко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8012,'Смазать чашу мультиварки растительным маслом, переложить печень, засыпать луком, готовить 15 минут в режиме «Выпечка», добавить гречневую крупу, залить водой, сдобрить черным перцем и солью, влить сметану, готовить кашу гречневую с печенью в мультиварке на режиме «Плов» до сигнала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8012,'Готовое блюдо разложить по тарелкам, посыпать измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Из подсоленной муки с разрыхлителем и сахаром с добавлением масла и яйцом вымесить тесто, обернуть комок в пленку, положить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Поместить тесто в смазанную форму, заполнить дно начинкой из смеси яйца, сахара, сока лимона с добавлением (порциями) творога, молока, крахмала, масла, сухого ванильного крема, разровнять творожную массу лопаточкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Выпекать творожный пирог с красной смородиной и меренгой полчаса в духовке при температуре 170 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Для приготовления меренги взбить в устойчевые пики подсоленные белки, всыпать порциями сахар, взбивать в однородную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Покрыть пирог меренгой, распределить равномерно по поверхности красную смородину, поместить на четверть часа в духовку с температурой 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8013,'Готовый десерт остудить, присыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8014,'Порезать на небольшие кусочки сыр, сложить в сотейник, прогреть на малом огне до расплавления, влить сливки размешать, снять с плиты.','https:https://st.vkuso.ru/data/cache/thumb/7a/d2bedb0fae53d7a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Раскатать тесто в толщину 3-4 миллиметра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8014,'Индейку порезать на куски толщиной примерно по 2 см, обжарить со всех сторон до золотистости, сдобрить перцем, посолить, перемешать, жарить филе индейки до готовности.','https:https://st.vkuso.ru/data/cache/thumb/c1/2c7d4f770a0fcc1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8015,'Нарезать морковь, нашинковать мелко лук, смазать чашу маслом, обжарить на режиме «Выпечка» 10 минут, всыпать гречку, перемешать, обжаривать 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8015,'Нарезать на средние кубики картофель, высыпать в чашу, обжарить 10 минут, залить водой, подсолить, готовить постный гречневый суп в мультиварке на режиме «Тушение» 1 час, в конце варки (за 10 минут) добавить петрушку и лавровый лист.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8016,'Рыбу порезать на кубики, помидоры без кожицы и семян – маленькими кусочками.','https:https://st.vkuso.ru/data/cache/thumb/13/dcd4abca36c4c13_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8016,'Чеснок раздавить прессом, лук порубить, обжарить в разогретом масле около минуты.','https:https://st.vkuso.ru/data/cache/thumb/d6/6fec7136cb498d6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8016,'Добавить кусочки рыбы, помидоры, приправить перцем, тимьяном, солью, перемешать, готовить примерно 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/cb/2ad5c0922dc50cb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8016,'Залить сливками, осторожно перемешать, готовить еще 4 минуты, можно добавить по вкусу пармезан.','https:https://st.vkuso.ru/data/cache/thumb/fe/4244009c73b14fe_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8016,'Положить в сковороду отваренные феттучини, аккуратно размешать. Снять с плиты, разложить по тарелкам, присыпать пармезаном.','https:https://st.vkuso.ru/data/cache/thumb/d2/74c7c5f9707fdd2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Залить желатин водой, дать постоять минут 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Растопить масло, убрать с плиты, всыпать сахар, лимонную цедру, подсолить, влить лимонный сок, перемешать, добавить желтки, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Смесь нагреть на малом огне, варить помешивая до загущения, но кипеть не давать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Положить желатин, размешать, дать хорошо остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Взбить блендером сахар и сливки до появления крепких пиков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8017,'Половину смеси осторожно смешать с лимонным муссом, разложить по креманкам, сверху уложить оставшуюся часть сливок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8018,'Порезать лук мелкими кубиками, обжарить 10 минут в режиме «Выпечка», всыпать мелко нарезанные грибы, жарить еще 11 минут, залить содержимое чаши водой, добавить черный молотый перец, посолить, готовить соус в мультиварке 20 минут в режиме «Тушение», по окончанию всыпать натертый сыр, влить сметану, тушить еще 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8018,'Грибной соус с сыром в мультиварке универсальный: сочетается и с мясом, и с овощами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Включить и прогреть до 180 градусов духовку. Перемешать шоколад, масло, сахарную пудру, соединить с желтками, сахарный песок взбить с белками, объединить с шоколадной массой. Заполнить полученной смесью форму, выпекать порядка 20 минут, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Для крема перемешать молоко с сахаром, желтками, солью, взбить до получения густой массы на паровой бане. Разбухший желатин залить теплым молоком, добавить пасту из фисташек, влить коньяк, взбить до однородности, остудить, перемешать со взбитыми сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Прогреть конфитюр, перемешать с коньяком, смазать остывший корж, выложить фисташковый крем, убрать десерт на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Прогреть 80 г сливок на слабом огне, всыпать кусочки молочного шоколада, ванильный сахар, нугу, подсолить, перемешать, кипеть не давать. Дать желатину набухнуть в воде 10 минут, отжать, соединить с теплыми сливками. Сахар взбить с оставшимися сливками, всыпать орехи. Аккуратно перемешать сливки с шоколадной массой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Достать из холодильника хорошо остывшую форму, покрыть фисташковый крем слоем шоколадного и убрать еще раз на час в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8019,'Разбухший желатин залить подогретыми сливками, всыпать какао, добавить черный шоколад и масло, перемешать в однородную массу. Довести до кипения воду с сахаром, проварить пару-тройку минут, перемешать с шоколадной массой, дать хорошо остыть, покрыть глазурью верх торта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Прогреть духовку до 150 градусов, в глубокой емкости взбить сахарную пудру и масло в пышную массу.','https:https://st.vkuso.ru/data/cache/thumb/32/6bec1bb056ece32_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Добавить яйцо, еще раз взбить.','https:https://st.vkuso.ru/data/cache/thumb/c9/2a8e215e073f7c9_434x295.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Всыпать в смесь муку с ванилью и солью, взбить до однородности, тесто убрать в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/7e/052d5d582aa3a7e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Хорошо охлажденное тесто раскатать на пергаменте, переложить на противень, поместить в духовку на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/aa/3f5eb9afbdca2aa_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Для начинки в микроволновке растопить карамель в смеси с подсоленным молоком.','https:https://st.vkuso.ru/data/cache/thumb/09/37d8a5538dfca09_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Вылить на готовое печенье ровным слоем, дать карамели схватиться, нарезать на прямоугольники произвольного размера, убрать на четверть часа в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/49/d14cc8c837e6249_434x295.jpeg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Поломать на небольшие кусочки шоколад, растопить на водяной бане, обмакнуть печенье в шоколад.','https:https://st.vkuso.ru/data/cache/thumb/ee/a7ff71d6dc404ee_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8020,'Разложить на пергаментной бумаге для застывания, убрать конфеты с карамелью и печеньем в шоколадной глазури на 5-7 минут в холодильник до полного застывания глазури.','https:https://st.vkuso.ru/data/cache/thumb/5d/a26faa1ed48695d_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8021,'Почистить и нарезать любые грибы, выставить режим «Тушение», растопить масло, всыпать нашинкованные морковь и лук, нарезанную на кубики картошку и грибы, добавить черный перец, посолить, тушить 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8021,'Всыпать муку, перемешать до однородного состояния, долить до желаемой густоты воды, тушить суп грибной с картофелем в мультиварке еще 20 минут, добавить измельченную зелень и раздавленный прессом чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8022,'Порубить масло с мукой, солью и сахаром до получения маслянистой крошки.','https:https://st.vkuso.ru/data/cache/thumb/a4/fc99a1ec2e01fa4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8022,'Груши очистить и порезать, побрызгать соком лимона.','https:https://st.vkuso.ru/data/cache/thumb/e0/a72e443cec575e0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8022,'Разложить по формочкам грушу и шоколад, сверху уложить крошку, выпекать грушевый крамбл с горьким шоколадом примерно полчаса при температуре 180 градусов до золотистости.','https:https://st.vkuso.ru/data/cache/thumb/2b/c1e9a1801b1a62b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8023,'Порезать лук кубиками, обжарить на масле, добавить порезанные грибы, перемешать, обжарить все вместе. Крупно натереть морковь, переложить к грибам, добавить мелкие кусочки мяса, закрыть сотейник крышкой, тушить около получаса до полной готовности мяса.','https:https://st.vkuso.ru/data/cache/thumb/81/f81459b23c76481_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8023,'Разрезать одинаковый по размеру картофель вдоль клубня на 4 части, положить к мясу. Содержимое сотейника подсолить, приправить специями, добавить стакан воды, тушить на пару под крышкой около четверти часа.','https:https://st.vkuso.ru/data/cache/thumb/4f/58e71b4fcccac4f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8023,'Для приготовления нудлей замесить тесто на кефире с солью и содой. Для начинки раздавить прессом чеснок, перемешать с маслом, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/9d/0a13d0988a30d9d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8023,'Раскатать из теста тонкий пласт, промазать чесночной начинкой, свернуть в трубочку, порезать на кусочки шириной примерно по 1см.','https:https://st.vkuso.ru/data/cache/thumb/44/bcf117085d99844_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8023,'Уложить на картофель, влить немного воды, дать жаркому с мясом, грибами и нудлями проварится под крышкой минут 10, подавать блюдо к столу горячим.','https:https://st.vkuso.ru/data/cache/thumb/54/0d721cd3433d954_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8024,'Залить перловую крупу кипятком, дать постоять, мелко нашинковать лук, высыпать в чашу с маслом, обжарить на режиме «Выпечка» 10 минут, добавить тертую морковь, обжаривать еще 10 минут, помыть и нарезать грибы, всыпать в чашу, оставить в прежнем режиме на 15 минут с закрытой крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8024,'Нарезать брусочками картофель, добавить к грибам и моркови, всыпать размоченную перловку и натертый корень петрушки, залить водой до нужной консистенции, посолить, перемешать, готовить суп из грибов с перловкой в мультиварке 1 час на режиме «Тушение».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8025,'Включить для прогрева духовку, заварить крепкий кофе из пары ложек на стакан воды, дать ему хорошо остыть. Перемешать все сухие ингредиенты вместе с погашенной уксусом содой.','https:https://st.vkuso.ru/data/cache/thumb/c2/8f98228cb202fc2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8025,'Влить по стакану сока от вишен и масла, добавить кофе, взбить до однородности миксером.','https:https://st.vkuso.ru/data/cache/thumb/8f/2bc23e657ffbf8f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8025,'Форму слегка смазать маслом, притрусить мукой, заполнить половиной теста, выложить на него тонкие кружочки банана и вишню.','https:https://st.vkuso.ru/data/cache/thumb/b7/5ba4ff1218c08b7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8025,'Залить второй частью теста.','https:https://st.vkuso.ru/data/cache/thumb/49/56aa39e9bccdf49_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Положить сахар и топленое масло, размешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8025,'Выпекать постный шоколадно-кофейный пирог с вишней и бананами примерно 45 минут, готовность проверить зубочисткой, дать остыть и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/cf/62cfc304a46bacf_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8026,'Промыть в холодной воде, почистить и нарезать грибы, лук мелко нашинковать кубиками и поджарить 10 минут в режиме «Выпечка», добавить грибы, порезанный картофель, выдавить чеснок, готовить на том же режиме 30 минут с закрытой крышкой, после окончания влить бульон, добавить специи, посолить, режим не менять готовить 10 минут, перелить в блендер, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8026,'Пюре перелить в мультиварку, влить сливки, дать закипеть на режиме «Варка на пару», обжарить в духовке кубики батона или белого хлеба, разлить суп-пюре из грибов в мультиварке по тарелкам, добавить сухарики, присыпать измельченной зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8027,'Приготовить пюре из картофеля, отваренного в «мундире» (чтобы лучше чистился обдать пока горячий холодной водой), сдобрить перцем, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8027,'Обжарить до мягкости на разогретом масле мелко посеченную капусту, тертую морковь,  нашинкованный лук (примерно 20 минут), подсолить, поперчить, перемешать начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8027,'Примерно пару ложек пюре положить на ладонь, сплющить в плоскую лепешку, положить начинку, края тщательно защипать, сформовать продолговатую зразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8027,'Обвалять картофельные постные зразы с капустой в сухарях, обжарить с двух сторон до золотистости, подавать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8028,'Положить в кастрюлю с водой нарезанный картофель и промытое пшено, проварить после закипания четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8028,'Порезать охлажденный плавленый сырок на кубики, переложить в кастрюлю, помешать, дать полностью раствориться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8028,'Добавить в нежный сливочный суп в холодные дни кусочки рыбы, посолить, проварить 5-7 минут, всыпать порубленную зелень, положить кусочек сливочного масла, размешать. Снять кастрюлю с плиты, дать постоять перед подачей под крышкой четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8029,'Достать тесто из морозилки за 40 минут до приготовления, прогреть духовку до 175 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8029,'Разрезать размороженное тесто на 8 прямоугольников, а потом каждый на 2 треугольника. Положить шоколадную начинку на широкий край, свернуть в рогалик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8029,'Переложить быстрые круассаны с шоколадной начинкой на противень, смазать верх яйцом, взбитым с небольшим количеством воды, выпекать 25 минут до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8030,'Прогреть до 200 градусов духовку, раскатать тесто в круглый пласт, промазать форму маслом, заполнить тестом, нанести слой кетчупа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8030,'Подготовить и нарезать овощи, грибы обжарить вместе с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8030,'Разложить начинку равномерным слоем на кетчуп, смазать постным майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8030,'Выпекать пиццу с грибами, помидорами и сладким перцем в середине духовки около четверти часа, подавать обязательно горячей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8031,'Подготовить грибы: помыть, почистить, нарезать, раздавить чеснок прессом, четвертинку яблока порезать на три части, переложить все в чашу мультиварки, добавить специи, мед, уксус, выставить режим «Варка на пару», задать время 10 минут, чаша 15 минут будет нагреваться, а потом пойдет время отсчета, по окончанию маринованные грибы в мультиварке остудить, разложить по стеклянным банкам, убрать на 10 часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8032,'Для начинки приготовить классическое картофельное пюре, перемешать его с обжаренными с луком грибами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8032,'Дрожжи развести в теплой воде, добавить сахарный песок, немного муки, перемешать и дать подойти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8032,'Опару влить в муку, добавить оставшуюся воду, растительное масло, соль и соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8032,'Тесто быстро вымесить, на это потребуется от семи до восьми минут. Поставить в тепло, объем массы должен увеличиться в два раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8032,'Рабочую поверхность смазать растительным маслом, тесто нарезать на порции и раскатать, дать постоять 20 минут. Сформовать пирожки, жарить на масле с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8033,'Приготовить из очищенного вареного картофеля пюре, немного остудить, влить ложку масла, добавить пару ложек муки и два желтка, хорошо вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8033,'Сформовать котлеты, запанировать в сухарях, обжарить на жире с обеих сторон до золотистости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8033,'Приготовить соус для картофельных котлет из пюре с грибной подливой. Промыть грибы, обдать кипятком, на пару часов залить водой, поставить варить. Через 50 минут отвар процедить, грибы тонко нашинковать. Порезать на кубики лук, обжарить в сливочном масле, добавить грибы, тушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8033,'Прогреть на сухой сковороде муку, добавить масло, обжарить до появления слегка желтого цвета, снять с плиты, влить помешивая (порциями) грибной отвар. Соединить его с грибами, довести до кипения, варить соус 10 минут, посолить, добавить чуть перца, сметану, перемешать, снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8033,'Разложить котлеты по тарелкам, полить горячим соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8034,'Приготовить пюре из картофеля, добавить яйцо, муку, соль, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8034,'Чуть смочить руки, ладонями сформовать лепешку продолговатой формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8034,'Выложить на середину сосиску, залепить края, равномерно обвалять сосиску в пюре из картофеля в муке со всех сторон, обжарить в хорошо прогретом масле до хрустящей корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8034,'Излишки масла удалить бумажным полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8035,'Помыть груши, очистить кожуру, удалить семенную коробку, порезать на небольшие кусочки, апельсиновую корку прокрутить на мясорубке, переложить все в чашу мультиварки, всыпать сахар и лимонную кислоту, готовить грушевое повидло в мультиварке, помешивая, 2 часа на режиме «Тушение», разложить по банкам, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8036,'Порезать капусту на куски, отварить до готовности, измельчить в комбайне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8036,'Сварить картофель с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8036,'Нашинковать лук порей (использовать зеленую и белую части), залить молоком, поперчить, тушить пока не станет мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8036,'Приготовить из картофеля пюре, добавить лук вместе с молоком, размешать, положить капусту, перемешать до однородности и получения светло-зеленого цвета, пюре картофельное с капустой по-ирландски хорошо прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8036,'Сделать по центру пюре углубление, заполнить растопленным маслом, размешать, подать к столу горячим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8037,'Взбить в пену подсоленные яйца с сахаром, влить сливки (стакан), еще раз взбить, добавить гелевый пищевой краситель, порциями муку, хорошо вымешивать после каждого добавления, в конце добавить оставшиеся сливки, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8037,'Влить в тесто растительное масло и погашенную соду, тщательно вымешать до однородного состояния, оставить на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8037,'Обжарить зеленые панкейки ко Дню св. Патрика на среднем огне с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8038,'Измельчить до состояния крошки печенье, перемешать с маслом, переложить в формочку, утрамбовать, готовить основу для мини-чизкейка одну минуту в СВЧ на мощности 700 Вт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8038,'Перемешать блендером творог, сметану, яйцо, сахар и ваниль в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8038,'Заполнить половину формочки с основой начинкой, поставить в СВЧ на 2 минуты с мощностью 700 Вт, повторить еще раз, но готовить минуту (мощность не менять).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8038,'Достать чизкейк, дать остыть, убрать минимум на 2 часа в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8039,'Очистить шкурку и нарезать груши вдоль на четвертинки, удалить семена, переложить фрукты в мультиварку, засыпать сахаром, залить осторожно, чтобы не смыть сахар, по стенке водой с лимонным соком, выставить режим «Выпечка», варить десерт из груш в мультиварке под крышкой 20 минут, после отключения крышку не открывать, выдержать 25 минут, десерт можно подавать и теплым, и холодным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8040,'Подготовить высокую форму, смазать маслом, положить макароны, прикрыть слоем нарезанной на кусочки ветчиной, приправить специями, поперчить.','https:https://st.vkuso.ru/data/cache/thumb/f9/2316c751e2a76f9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8040,'Смешать молоко с подсоленной водой, залить в форму, присыпать сырной стружкой.','https:https://st.vkuso.ru/data/cache/thumb/27/d3c6b7c22ad7227_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8040,'Форму закрыть фольгой, выпекать макаронную запеканку с сыром и ветчиной полчаса на среднем огне, осторожно удалить фольгу, готовить еще четверть часа.','https:https://st.vkuso.ru/data/cache/thumb/5c/799cf9f5a12fd5c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8041,'Взбить до однородной массы сахарную пудру с шоколадной пастой.','https:https://st.vkuso.ru/data/cache/thumb/3d/abb5f9c51a7a73d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8041,'Распределить ее по формочкам, поставить на треть часа в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/23/4fbfe83e9928123_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8041,'Порезать фрукты на тонкие ломтики, пончик разрезать вдоль на 2 половинки.','https:https://st.vkuso.ru/data/cache/thumb/10/979a1afe5f79510_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8041,'Ломтики фруктов (кроме банана) уложить на одну половинку сладкого бургера.','https:https://st.vkuso.ru/data/cache/thumb/c1/2b545325184d3c1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8041,'Сверху уложить слой шоколадной пасты, накрыть ломтиками банана и второй половинкой пончика, скрепить шпажкой.','https:https://st.vkuso.ru/data/cache/thumb/27/e92a117bb0d4927_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8042,'Нарезать мякоть мяса на куски, порезать на крупные куски сладкий болгарский перец и помидоры, нашинковать лук кольцами, измельчить на терке морковь, влить в чашу мультиварки подсолнечное масло, переложить овощи, лук, мясо. Добавить муку, заправить перцем, посолить, выставить режим «Выпечка», оставить на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8042,'Перемешать, бросить пару листиков лаврового листа, перец горошком, залить воду, переключить на «Тушение», готовить гуляш говяжий с овощами в мультиварке 1 час, блюдо при подаче украсить в тарелке веточкой зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Перемешать муку с яйцами, добавить сахар.','https:https://st.vkuso.ru/data/cache/thumb/38/40a31f75ef10938_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Влить порциями подсоленную воду.','https:https://st.vkuso.ru/data/cache/thumb/53/c68d16b36c74f53_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Вымесить тесто, прикрыть его тканью, дать постоять минут 20.','https:https://st.vkuso.ru/data/cache/thumb/6f/07e8fb858387f6f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Тоненько раскатать, вырезать любой формочкой кружочки.','https:https://st.vkuso.ru/data/cache/thumb/a0/7c0b0de437fdea0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Отварить картофель, сделать пюре пока горячий, добавить шкварки, обжаренные с луком грибы, подсолить, перемешать начинку для вареников с картошкой, шкварками, грибами и луком. На каждый кружок положить по ложке начинки, тщательно защипать края.','https:https://st.vkuso.ru/data/cache/thumb/42/3a01e1ba350ee42_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8043,'Сварить в подсоленной воде, разложить на блюдо, смазать смальцем с жаренным луком и шкварками, подать к ним сметану.','https:https://st.vkuso.ru/data/cache/thumb/a5/eba539682ed40a5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'Включить и прогреть духовку до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'Выстлать дно формы пергаментом, смазать маслом, присыпать мукой, излишки стряхнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'В просеянную муку всыпать какао, соду, подсолить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'В глубокую миску влить воду с маслом, кофе, всыпать сахар, ванильный экстракт, винный уксус, взбить смесь до его полного растворения. Объединить обе смеси, вымесить тесто, заполнить форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'Выпекать супер влажный шоколадно-кофейный пирог без яиц  около 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8044,'Готовый пирог остудить, порезать  на куски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8045,'Крупно натереть сыр, ломти хлеба намазать маслом, помидоры и колбасу порезать на кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8045,'Смазать форму маслом, заполнить хлебом (выкладывать веером), проложить между ломтями колбасу и помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8045,'В молоко вбить яйцо, взбить вилкой, подсолить, сдобрить перцем, перемешать, залить горячие бутерброды веером с колбасой, помидорами и сыром, присыпать обильно сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8045,'Поставить форму в прогретую духовку на четверть часа до расплавления сыра, подать сразу к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8046,'Порезать мясо на кубики, обжарить порциями в сильно разогретом масле.','https:https://st.vkuso.ru/data/cache/thumb/ec/6ca9c80756d07ec_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8046,'Овощи порезать на кубики. Сложить все мясо в сковороду, добавить овощи, обжарить минут 7 все вместе.','https:https://st.vkuso.ru/data/cache/thumb/cb/b9dc180b91297cb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8046,'Залить бульоном, дать закипеть, сделать нагрев минимальным, варить примерно час. За 10 минут до готовности добавить мелко нашинкованную петрушку и чеснок.','https:https://st.vkuso.ru/data/cache/thumb/30/d7528ad7559a130_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8046,'Отварить для вкуснейшего домашнего лагмана из телятины лапшу по инструкции на упаковке, переложить в дуршлаг, дать хорошо стечь.','https:https://st.vkuso.ru/data/cache/thumb/0a/76460d2b3a6c40a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8046,'Разложить по тарелкам лапшу, добавить овощи с мясом и бульоном, посыпать зеленью.','https:https://st.vkuso.ru/data/cache/thumb/39/dda29f7aea5a939_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8047,'В воде до готовности отварить яйца, после чего их остудить и очистить от скорлупы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8047,'Мелко нашинковать репчатый лук, смешать со свиным фаршем, добавить в луково-мясную массу кумин, шалфей (приправы для свинины), получившейся массой смазать поверхность всех яиц, после чего каждое запанировать в муке или сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Положить массу в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8047,'Далее яйца в свином фарше по-шотландск либо запечь в духовке в течение 20 минут, либо же в большом количестве растительного масла обжаривать до корочки в районе 1 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8048,'Смешать миксером до однородности сахар, половину банана, масло, мед, стакан муки, стакан теплой крепкой заварки.','https:https://st.vkuso.ru/data/cache/thumb/cc/ff133f9e06840cc_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8048,'В другой стакан муки добавить соду и соль, перемешать, высыпать в тесто, смешать с помощью миксера, вылить в подготовленную форму.','https:https://st.vkuso.ru/data/cache/thumb/a6/28004253d75e9a6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8048,'Выпекать апельсиновый торт с лесными орехами и бананом в горячей (180 градусов) духовке порядка 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/a5/0a50d68491feda5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8048,'Для крема в чашу блендера положить половину банана, дольки апельсина, очищенные от пленочек, орехи и цедру от одного апельсина, все превратить в пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8048,'Бисквит разрезать вдоль на 3 одинаковых коржа, промазать коржи и верх торта, оформить кусочками банана, посыпать орехами, дать постоять пару часов для пропитки.','https:https://st.vkuso.ru/data/cache/thumb/bc/b1b20976ece61bc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8049,'Разрезать пополам вдоль сосиски, с обеих сторон сделать 2 надреза (будущие лапки), каждую половинку сосисок снова разрезать пополам: должно получиться 4 лапки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8049,'Каждую сосиску порезать на 3 части: концы сосиски – головы черепах, на которых нужно сделать ротик, надрезав сосиску ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8049,'Сформовать из готового фарша котлеты, воткнуть в нее сосиску-голову, сосиски-лапки, сосиску-хвост (сделать его из оставшегося кусочка сосиски), для панциря нужно нарезать полосками бутербродный сыр и выложить его сеточкой на котлету.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8049,'Накрыть котлеты с сыром для детей «Черепашки» фольгой, поместить в духовку и выпекать при 180 градусах 35 минут, за несколько минут до готовности фольгу снять и дать сыру запечься.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Для приготовления главной составляющей, блинов, взбить сырые яйца с молоком, всыпать пшеничную муку, сахар и соль. Мелко накрошить зелень, добавить в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Жарить блины на заранее разогретой сковороде с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Нарезать кружками вымытые и обсушенные помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Любой сыр натереть на крупной терке, очистить шампиньоны, нарезать их пластинками, немного обжарить и посолить по вкусу. Можно добавить пропущенный через пресс чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Выложить на дно формы блин, на него – помидоры, соль и перец – по вкусу, далее – грибы. Посыпать сыром с чесноком, накрыть вторым блином, слои повторить несколько раз. Сверху – блин, тертый сыр, поставить пирог на 15 – 20 минут в разогретую духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8050,'Подать блинный торт с грибами, сыром и помидорами холодным или горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8051,'Крылышки разрезать на две-три части, выложить на противень.','https:https://st.vkuso.ru/data/cache/thumb/98/f0709dca3174998_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8051,'Смешать соус барбекю, сливовый и «Вустерский».','https:https://st.vkuso.ru/data/cache/thumb/2c/95b20b9d5483e2c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8051,'Полить смесью крылышки.','https:https://st.vkuso.ru/data/cache/thumb/51/dea9c80ebdade51_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8051,'Перемешать, поставить блюдо в духовку на 20 минут, температура приготовления – 220 градусов. В процессе термообработки крылышки два раза перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/f2/7becb45f6f643f2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Свежие или размороженные стейки тунца обсушить бумажным полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Острую горчицу перемешать с оливковым маслом и тертой цедрой одного лимона. Полученной смесью намазать рыбу и оставить для маринования на полчаса при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Для приготовления салата обжарить на сковороде без масла очищенные кедровые орешки, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Орегано, базилик, петрушку вымыть, обсушить и нарубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Перемешать нарезанные помидоры, лук-шалот, лимонный сок и оливковое масло, посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Добавить травы, кедровые орехи и тертый сыр «Пармезан». Ингредиенты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Разогреть на антипригарной сковороде оливковое масло. Стейки запанировать в сухарях, выложить на сковороду. Жарить по две минуты с каждой стороны. Филе должно остаться немного сыроватым внутри.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8052,'Переложить рыбу на тарелки, сверху выложить салат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Смочить руки водой, разделить тесто на четыре части, скатать из них тонкие батоны, диаметр – три сантиметра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Противень застелить ковриком для выпекания, выложить заготовки на некотором расстоянии друг от друга. Время выпекания – от 15 до 17 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8053,'Готовые бискотти вынуть из духовки, нарезать по диагонали ломтиками. Печь еще от пяти до семи минут при той же температуре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8054,'Свиную вырезку нарезать порционными кусками, после чего каждый кусок отбить как можно тоньше, смазать перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8054,'Раскатать готовое слоеное тесто в прямоугольный пласт, затем нарезать его одинаковыми квадратами, на середину каждого квадрата выложить по кусочку подготовленного мяса, завернуть тесто конвертиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8054,'На противень постелить фольгу или пекарскую бумагу, которую необходимо промазать растительным маслом, швом вниз выложить на противень отбивные из свиной вырезки в слоеном тесте, присыпать каждый конверт кунжутом, убрать противень с заготовками в предварительно разогретую до 180-200 градусов духовку и выпекать на протяжении 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8054,'Готовые конвертики можно подавать как отдельную горячую закуску, так и в качестве дополнения к супу или бульону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8055,'Соединить сливки, коричневый сахар, какао-порошок и 50 г измельченного черного шоколада.','https:https://st.vkuso.ru/data/cache/thumb/09/41c1799f2aaf009_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8055,'Смесь довести до кипения на среднем огне, помешивать. Прогревать в течение пяти минут, снять с огня.  Ввести оставшийся шоколад, сливочное масло, перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/ac/60c474feddcd3ac_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8055,'Для орехового мусса соединить сливочный сыр, щепотку соли, арахисовое масло, охлажденные сливки, сахарную пудру.','https:https://st.vkuso.ru/data/cache/thumb/3c/ad4a2442d63883c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8055,'Взбить при помощи миксера в пышную массу.','https:https://st.vkuso.ru/data/cache/thumb/01/6dffc5715179a01_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8055,'Песочное печенье раскрошить и насыпать крошки в стаканы, полить ореховым муссом, добавить шоколадный соус. Слои чередовать.','https:https://st.vkuso.ru/data/cache/thumb/47/bcb7f4800f9b547_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Соединить сахар, сухие дрожжи и теплую воду. Отдельно просеять пшеничную муку с солью. Жидкую смесь соединить с сухой, хорошо перемешать. Тесто должно получиться гладким и эластичным.','https:https://st.vkuso.ru/data/cache/thumb/6b/a3a29496db3486b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Добавить сливочное масло комнатной температуры и еще раз вымесить.','https:https://st.vkuso.ru/data/cache/thumb/2d/cad3544cef1772d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Поместить тесто в миску, оставить подходить, затем разрезать на 15 одинаковых частей, каждый кусочек – еще на три части: большую и 2 маленьких.','https:https://st.vkuso.ru/data/cache/thumb/c6/818578076f665c6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Каждую заготовку скатать в шарик и оставить на 15 – 20 минут. Затем заготовки слегка сплюснуть и снова дать подойти.','https:https://st.vkuso.ru/data/cache/thumb/5e/e92b0b05375d55e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Скрепить маленькие шарики с большими в виде ушек и поместить на противень. Печь в течение 11 минут при температуре 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/b0/1ca14d041a637b0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8056,'Булочки остудить и оформить шоколадом в виде мордочек.','https:https://st.vkuso.ru/data/cache/thumb/3b/68e034642e1ae3b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8057,'В чашу блендера влить минеральную воду и кефир, добавить к ним нежирный творог, изюм и замороженную клубнику, тщательно взбить все ингредиенты блендером, после чего разлить по формочкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8057,'Будущее домашнее диетическое мороженое убрать до полного застывания в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8058,'Филе ласося разделить на 2 куска по 200 г., тщательно удалить все косточки, перемешать соевый соус, масло, орегано и лимонный сок, залить рыбу, оставить на час или больше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8058,'Для соуса обжарить нашинкованный шалот с маслом, добавить вино, почти полностью выпарить его, влить воду со сливками, выпарить на одну треть объема, заправить зернистой горчицей, подсолить, поперчить, убрать с плиты, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8058,'Разложить рыбу на противне, выстланном бумагой для выпечки, поместить филе лосося на треть часа в прогретую до 200 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8058,'К готовому лососю подать остывший соус, оформить блюдо тонкими полукольцами лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'Для начинки смешать свежую или замороженную чернику, сахар и крахмал, выложить слоем на тесто в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8059,'Запечь яблоки без сердцевины при 200 градусах около часа, приготовить из них пюре, дать остыть, взбить с добавлением белка до пышной светлой массы, напоминающей меренгу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8059,'Сварить сахарный сироп: поставить на огонь 150 г воды и 350 г сахара, подождать пока сироп нагреется до 80 градусов и всыпать еще 50 г сахара и агар-агар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8059,'Когда температура сиропа будет 110 градусов, влить его тоненькой струйкой к пюре, взбить до плотных устойчивых пиков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8059,'Отсадить из кондитерского мешка яблочный зефир на пергамент, оставить на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8060,'Клубни промыть, не чистить, сварить, дать немного остыть.','https:https://st.vkuso.ru/data/cache/thumb/5f/b532eb9aec6fc5f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8060,'Подсолить творог, растереть до исчезновения комочков.','https:https://st.vkuso.ru/data/cache/thumb/48/b6a048776112748_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8060,'Картофель очистить, порезать на кружки по 0,5-0,7 см, половину выложить на дно формы, смазанной маслом, слегка присолить.','https:https://st.vkuso.ru/data/cache/thumb/02/24978b79d662702_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8060,'Сверху равномерным слоем распределить творожную массу, прикрыть второй половиной картофеля, залить взбитыми со сливками или сметаной желтками.','https:https://st.vkuso.ru/data/cache/thumb/61/0d51cfd2fd51661_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8060,'Поставить форму с картофелем по-княжески на 45 минут в духовку. Готовый картофель присыпать натертым плавленным сыром и зеленью, подавать к столу в горячем виде.','https:https://st.vkuso.ru/data/cache/thumb/41/9ede90bbdb0d041_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8061,'На паровой бане растопить шоколад, тщательно промазать им при помощи кисточки дно и стенки формочек, которые затем убрать на 5 минут в морозилку, далее опять промазать растопленным шоколадом все формочки и снова поместить их на 5 минут в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8061,'Сливочное масло натереть на мелкой терке, взбить его вместе с творогом, ванилином и сахарной пудрой, пока масса не станет однородной, по подготовленным формочкам распределить творожную начинку (в нее можно добавить сухофрукты или орехи), сверху залить ее оставшимся растопленным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8061,'Убрать домашние творожные глазированные сырки на 10 минут в морозилку, чтобы они застыли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8062,'Замочить в подогретом молоке булку, перья зеленого лука мелко нашинковать, перемешать булочку с фаршем, луком, яйцом, приправить специями, посолить, всыпать столовую ложку муки, хорошо вымесить.','https:https://st.vkuso.ru/data/cache/thumb/42/b33258993244142_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8062,'Сформовать котлетки из свинины с зеленым луком, запанировать в муке.','https:https://st.vkuso.ru/data/cache/thumb/f9/c7e8dfe3999adf9_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8062,'Обжарить в хорошо разогретом масле, одну сторону на среднем огне, другую – на слабом. Либо жарить на сильном, а потом дать дойти 10 минут в разогретой духовке.','https:https://st.vkuso.ru/data/cache/thumb/39/a87d85131e47939_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8063,'Хорошо промыть изюм, на 5 минут поместить в горячую воду, дать набухнуть, обсушить, смешать с двумя щепотками муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8063,'В глубокую миску просеять муку, подсолить, положить сахар, ванилин, дрожжи, изюм хорошо перемешать, залить теплой водой (добавлять тонкой струйкой), перемешать, добавить еще муки (стакан), семена льна, изюм и масло, перемешать, всыпать остатки муки, вымесить тесто, смазать миску маслом, положить тесто, прикрыть тканью, убрать на час в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8063,'Притрусить стол мукой, переложить тесто, примять, раскатать в пласт, промазать его маслом, бока прямоугольника свернуть внахлест от краев к центру, раскатать, еще раз промазать маслом и также свернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8063,'Нарезать свернутое тесто на кусочки, конец каждого повернуть на 90 градусов. Уложить постные витые булочки с изюмом на противень, застланный пергаментом, промазанный маслом, накрыть тканью, поставить в тепло на треть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8063,'Поместить противень в прогретую до 180 градусов духовку, выпекать булочки до золотистости, переложить булочки на блюдо, присыпать сахарной пудрой, можно добавить к ней корицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8064,'Для первого слоя порезать помидоры на кубики, отжать от сока, добавить раздавленный чеснок, подсолить, переложить в форму, смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8064,'Вторым слоем уложить порезанные крабовые палочки, смазанные майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8064,'Третий слой салата из крабовых палочек – кукуруза с майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8064,'Четвертый слой – тертый сыр с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8064,'Верх оформить сухариками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'Раскатать в пласт оставшееся тесто, поместить его поверх начинки, закрыв тем самым пирог, сделать в центре небольшую дырочку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'В разогретой до 165-175 градусов духовке выпекать пирог 35-40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8065,'Готовому изделию дать 20-30 минут постоять, если ',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Добавить к взбитым яйцам масло, сахар, мед, прогреть размешивая на водяной бане до образования массы однородного состава.','https:https://st.vkuso.ru/data/cache/thumb/98/523f66ad7a19998_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Погасить соду, добавить к массе, всыпать муку, очень хорошо перемешать до получения вязкого теста.','https:https://st.vkuso.ru/data/cache/thumb/6c/4768b5ddd4f406c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Начертить на пергаменте круг, по центру выложить пару ложек теста, мокрой ложкой равномерно размазать по поверхности бумаги. Выпекать коржи до золотистости около 5-7 минут при температуре 200 градусов, пока он горячий выровнять края, оставить крошку для обсыпки верха, удалить бумагу.','https:https://st.vkuso.ru/data/cache/thumb/2d/89b184b73f4f82d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Для приготовления крема перемешать сметану хорошего качества в вареной сгущенкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Коржи медового торта с кремом из сгущенки и сметаны собрать и промазать кремом в разъемной форме (так крем не будет растекаться).','https:https://st.vkuso.ru/data/cache/thumb/15/e8e44faac7e5115_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8066,'Измельчить крошку от обрезков коржей в блендере, присыпать верх торта, а можно еще добавить к ней любые дробленые орехи.','https:https://st.vkuso.ru/data/cache/thumb/f0/c44d32dbba395f0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8067,'Для приготовления домашнего бутерброда булочку разрезать не до конца сверху или сбоку. Осторожно развернуть, как книжку, и прогреть на сковороде или на гриле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8067,'Сосиски наколоть в нескольких местах и прогреть тоже на гриле или на сковороде со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8067,'Поместить сосиску в булочку, полить кетчупом, готовой столовой горчицей и подать блюдо горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8068,'Отварить размороженных и очищенных от внутренностей кальмаров в течение 2-3 минут (больше не нужно) в кипящей подсоленной воде, пока они не станут белыми, а шкурка не свернется, по истечении 2-3 минут достать тушки из воды, дать им слегка остыть, от шкурки очистить посредством ножа, нарезать тушки тонкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8068,'На огне хорошо разогреть сковороду, положить немного сливочного масла, когда оно растопится, поместить подготовленных кальмаров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8068,'На большом огне в районе 2 минут обжарить мясо, не забывая помешивать, пока жидкость не испарится, а кальмары не свернутся, мясо посыпать мукой, быстро перемешать, 10-20 секунд дать муке чуть обжариться, добавить сметану, влить кипяток таким образом, чтобы кальмары почти покрылись водой, накрыть сковороду крышкой, сделать огонь поменьше и в течение 1 минуты потушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8068,'Далее добавить в кальмары в сметанном соусе молотый перец и соль, хорошо перемешать и потушить еще 1 минуту, подавать готовое блюдо можно с картофельным пюре или в качестве холодной или горячей закуски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8069,'Для приготовления блюда понадобится творог, его можно протереть через сито или оставить непротертым, соединить с яйцами и сахарным песком и взбить. В конце добавить ванилин из пакетика или горошинки из стручка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8069,'Для теста охлажденное масло нарезать кусочками и перетереть с сахаром и мукой в крошку, добавить пищевую соду и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8069,'Круглую или квадратную форму для выпекания смазать жиром, посыпать мукой. Выложить две трети теста, начинку из творога, половинки абрикосов или мягкую курагу. Фрукты можно немного вдавить в творожную массу. Сверху – оставшаяся треть теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8069,'Печь при температуре 180 градусов в течение 35 – 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Замороженную вишню подержать при комнатной температуре до оттаивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Два куриных яйца растереть с сахаром и солью, ванилином, влить воду, перемешать до растворения сахарного песка, добавить мягкое сливочное масло и перемешать. Масло будет плавать сверху хлопьями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Постепенно всыпать заранее просеянную муку, тесто должно получиться тугим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Накрыть массу чашкой и оставить на 40 минут для набухания клейковины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8075,'Белки взбить до пиков.','https:https://st.vkuso.ru/data/cache/thumb/48/94f7f2e6496b848_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Смешать сахар, муку, сметану и сливочный сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Готовый продукт очень тонко раскатать, смазать поверхность маслом, выложить вишни без сока тонким слоем, присыпать сахаром, мукой, свернуть в рулет. Он не должен быть тугим. Концы защипать и подвернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Застелить противень промасленной бумагой, перенести на него рулет, смазать слегка взбитым яйцом, наколоть ножом в нескольких местах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Выпекать штрудель в течение получаса при температуре 210 градусов, духовку разогреть заранее.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8070,'Переложить готовую выпечку на решетку для остывания, прикрыть тканью. При подаче рулет нарезать, присыпать сахарной пудрой, молотой корицей, сухарями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8071,'Клубни картофеля очистить и отварить в подсоленной воде. Растереть готовый продукт до пюреобразного состояния с помощью терки или блендера. Подлить растительное масло по вкусу. Должна получиться масса, похожая на тесто. По необходимости можно подсыпать немного муки.','https:https://st.vkuso.ru/data/cache/thumb/95/aeb5a68e5411595_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8071,'Любые грибы, например, вешенки или шампиньоны, хорошо промыть и очистить. Грибы отварить до готовности и мелко нарезать. Репчатый лук очистить, нарезать кубиками небольшого размера, обжарить, добавить в грибы, посолить, поперчить и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/c5/0b195fed4f4e4c5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8071,'Картофельное тесто разделить на порции, на лепешки выложить начинку.','https:https://st.vkuso.ru/data/cache/thumb/53/f7d3c8989281a53_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8071,'Свернуть вдвое, сформовать зразы в виде капли, грибы должны оказаться внутри. Изделия обвалять в панировочных сухарях или в муке. Жарить на сковороде или запечь в духовке, второй способ предпочтительнее.','https:https://st.vkuso.ru/data/cache/thumb/93/c8012c764338093_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8072,'В большой миске смешать мягкий или  хорошо растертый творог, маргарин сахар и яйца, муку с разрыхлителем смешать отдельно и подмешать ее в творожную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8072,'Перемешивать массу до тех пор, пока тесто не получится упругим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8072,'В тонкий пласт раскатать получившееся тесто, а чтобы во время раскатки оно не прилипало к скалке, ее необходимо периодически посыпать мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8072,'Из тестяного пласта вырезать желаемое количество кругов, каждый из которых сложить пополам, далее все круги необходимо еще раз сложить пополам и переложить на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8072,'Выпекаются печенье «Творожные сладкие уголки» в духовке при 180 градусах 25-30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8073,'Приготовить из очищенного картофеля подсоленное пюре с молоком и сливочным маслом, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/7b/fe3f3193c0fb17b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8073,'Из лука и мяса приготовить фарш, обжарить его на масле, сыр натереть.','https:https://st.vkuso.ru/data/cache/thumb/6d/27636a8e456ed6d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8073,'У формы смазать бока и дно маслом, уложить слой пюре, на него – фарш.','https:https://st.vkuso.ru/data/cache/thumb/06/cae8584ff7db506_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8073,'Присыпать сыром, прикрыть слоем пюре.','https:https://st.vkuso.ru/data/cache/thumb/ee/8710cfb026706ee_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8073,'Разболтать яйцо, смазать верх бифарше, отправить форму на полчаса в духовку, разогретую до 180 градусов. Подавать к столу со сметаной и зеленью.','https:https://st.vkuso.ru/data/cache/thumb/6d/9ef2dafe5a08e6d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Нашинковать сельдерей и лук.','https:https://st.vkuso.ru/data/cache/thumb/5b/d1257ffdafe445b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Растопить в сотейнике масло, пересыпать туда сельдерей, лук и брокколи, тушить до мягкости.','https:https://st.vkuso.ru/data/cache/thumb/30/d1ccbd8bfe5bb30_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Добавить соус велюте, варить четверть часа до полного размягчения овощей.','https:https://st.vkuso.ru/data/cache/thumb/04/8446b9054039c04_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Перелить суп в чашу блендера, разбить до состояния пюре.','https:https://st.vkuso.ru/data/cache/thumb/d9/d880d63b37dded9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Протереть крем-суп  из брокколи, лука и сельдерея через сито, поместить в кастрюлю.','https:https://st.vkuso.ru/data/cache/thumb/b7/f13daa34df32eb7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Добавить бульон до желаемой густоты, поперчить, присолить.','https:https://st.vkuso.ru/data/cache/thumb/e0/312f84e37ebede0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Прогреть на малом огне, влить хорошо подогретые сливки, перемешать, снять с плиты.','https:https://st.vkuso.ru/data/cache/thumb/3a/82cd7c04841c03a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8074,'Разлить по тарелкам, оформить кусочками бланшированной брокколи.','https:https://st.vkuso.ru/data/cache/thumb/ac/8734200de20ccac_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8075,'В блендере порубить мясо до состояния фарша, посолить, поперчить, добавить сушеную зелень, желтки, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/4a/1d956e78a0db44a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8075,'Обжарить котлеты воздушные из куриной грудки на сливочном (топленом) масле, выкладывать на сковороду фарш ложкой. Одну сторону жарить 4 минуты при среднем нагреве, вторую под крышкой 3 минуты, подавать с овощами.','https:https://st.vkuso.ru/data/cache/thumb/a8/67af58c4960caa8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'В миску всыпать ванильный сахар, вбить к нему яйцо и перемешать, влить теплое молоко, снова перемешать и всю смесь процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'Для приготовления карамели необходимо на сковороде нагреть, помешивая, сахар, пока он не станет желаемого цвета, после чего разлить его по формочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'После того, как карамель полностью остынет, полить ее сверху яично-молочной заливкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'В большую форму составить формочки с заготовкой, поместить ее в духовку и до половины меньших формочек залить емкость кипятком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'Готовить Карамельный флан по-испански при 150 градусах на протяжении 1 часа, остудить его до комнатной температуры, на несколько часов поместить формочки с фланом в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8076,'Когда содержимое формочек застынет, вдоль стенок каждой формочки нужно провести ножом, перевернуть их на тарелку и вынуть флан, популярный во всем мире десерт испанской кухни.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8077,'Перемешать разрыхлитель и просеянную муку с сахарной пудрой (100 г), растереть в маслянистую крошку со 150 г масла, добавить яйцо, замесить мягкое тесто, обернуть его пленкой, убрать в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8077,'Для приготовления крема отжать лимонный сок, добавить растопленный остаток масла и сахарную пудру с парой яиц, перемешать, прогреть минут 5 на малом огне до сгущения, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8077,'Застелить форму пергаментом, на 2/3 заполнить тестом, сформовать бортики и ровное дно, заполнить основу кремом прикрыть сеточкой из теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8077,'Простой песочный пирог с лимонной начинкой выпекать полчаса при температуре 180 градусов, остудить, подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8078,'Мясо поставить варить вместе с целой морковкой и луковицей, дать закипеть, удалить пену, варить на малом огне около часа, снимая пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8078,'Морковь достать, порезать кубиками, лук выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8078,'Готовое мясо «разобрать» на небольшие кусочки, вернуть в бульон вместе с морковью, приправить специями, пару минут прокипятить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8078,'Отварить яйца, порезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8078,'Налить куриный бульон в супницу, добавить сухарики и яйца, присыпать зеленью, отдельно подать сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8079,'Подготовить окорочка, толстую кожу лучше удалить, присолить, поперчить.','https:https://st.vkuso.ru/data/cache/thumb/42/0c67e0c7c579b42_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8079,'Выложить на противень полукольца лука, на него уложить окорочка, положить под каждый чернослив, прогреть духовку до 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/b3/257b2bb847a30b3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8079,'Промежутки между мясом заполнить четвертинками картофеля, полить равномерно соком одного апельсина.','https:https://st.vkuso.ru/data/cache/thumb/2c/a127bfcfdc9ad2c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8079,'Другой апельсин порезать  на дольки, уложить на мясо, часть – на картофель. Поставить противень с куриными окорочками с картофелем под апельсинами на 25 минут в прогретую духовку. Полить картофель и окорочка образовавшимся соком с противня, вернуть еще на полчаса в духовку, достать полить еще раз соком, вернуть на четверть часа в духовку.','https:https://st.vkuso.ru/data/cache/thumb/10/8d53d72ad31d310_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8080,'Порезать мелко грибы, обжарить на масле минут 5, добавить нашинкованный кубиками лук, посолить, перемешать, жарить около четверти часа.','https:https://st.vkuso.ru/data/cache/thumb/07/b29f857f5499407_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8080,'Обжарить в другой сковороде фарш, поперчить, посолить, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/1f/9cc79597801201f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8080,'Тесто раскатать по размеру превышающему форму в 2 раза, присыпать форму небольшим количеством муки, уложить тесто, прикрыть его начинкой, разровнять, накрыть второй половиной теста, тщательно залепить.','https:https://st.vkuso.ru/data/cache/thumb/c3/e263643edd34fc3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8080,'Присыпать верх слоеного пирога с грибами и фаршем сырной стружкой, выпекать полчаса при температуре 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/60/59663990caa7160_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8081,'Перемешать апельсиновый сок, желтки, куантро, сливки, соль, цедру и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11435,'Нарезать тонкими дольками и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8081,'Положить хлебную гармошку на минуту в смесь, перевернуть, переложить в формы, разрезы багета заполнить фруктами или сыром, присыпать коричневым сахаром, завернуть в пленку, поставить на всю ночь в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8081,'Положить на каждый тост апельсиновый по-французски по небольшому кусочку масла. Поставить формы в прогретую до 180 градусов духовку на полчаса, перед подачей присыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Взбить сырые куриные яйца с сахаром с помощью венчика или блендера. Масса должна загустеть. Добавить еще яйца и сахар, продолжать взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Выдавить сок из хорошо вымытого лимона, натереть цедру, то и другое добавить в яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Всыпать заранее просеянную муку, ванильный сахар из пакетика, ингредиенты перемешать..',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Смазать противень растительным маслом, присыпать мукой, выложить готовое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Печь пирог при температуре 160 градусов в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Корж остудить, разрезать пополам вдоль и промазать абрикосовым джемом. Половинки пирога соединить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8082,'Для сиропа развести в воде сахарную пудру, прогреть до 40 градусов, влить молоко, перемешать, немного охладить. Полить пирог сверху.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Сливочное масло растереть с мукой и сахарным песком. Взбить с желтком сметану, добавить в тесто, быстро замесить, масса не должна согреться. Готовый продукт завернуть в пищевую пленку и поставить на час в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/19/58ab7e9dbfcd919_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Ядра грецких орехов с корицей и сахаром поместить в чашу блендера, порубить в крошку.','https:https://st.vkuso.ru/data/cache/thumb/f6/6a7cf2a6e1596f6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Духовку разогреть до 180 градусов. Тесто из холодильника вынуть, разделить на три части. Первую тонко раскатать на присыпанной мукой поверхности, посыпать сахарно-ореховой смесью.','https:https://st.vkuso.ru/data/cache/thumb/e9/68b2c912a67f9e9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Разрезать тесто на 16 частей от центра, можно использовать нож для пиццы.','https:https://st.vkuso.ru/data/cache/thumb/00/fac78186fca3000_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Каждый сегмент свернуть в рожок.','https:https://st.vkuso.ru/data/cache/thumb/c5/eecb165066579c5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Выложить изделия на пергамент или силиконовый коврик. Противень с рожками вставить в разогретую духовку, печь в течение 10 – 12 минут до подрумянивания.','https:https://st.vkuso.ru/data/cache/thumb/aa/4ee9778e506b3aa_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8083,'Выпечку вынуть, переложить на решетку для остывания. При подаче посыпать изделия сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/63/bd413323719c763_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8084,'В миску или кастрюльку влить молоко, замочить в нем сушки и оставить на 30 минут, чтобы они стали чуть мягче.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8084,'В это время через мясорубку пропустить вместе с луком свиной фарш, добавить молотый перец, посолить по вкусу, вбить сырое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8084,'Размякшие сушки достать из молока, в отверстие каждой поместить немного мясной начинки, смазать все сушки майонезом, при желании сверху посыпать тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8084,'На средний огонь поставить сковородку, выложить в нее подготовленные сушки и жарить все под крышкой (не уменьшая и не увеличивая огонь).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8084,'Готовые сушки со свиным фаршем выложить на большое блюдо и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8085,'Клубни картофеля вымыть и отварить вместе с кожурой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8085,'Продукт остудить, очистить, нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8085,'Добавить соль, молотый острый красный перец, чеснок, паприку, растительное масло и семена кориандра, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8085,'Выложить смесь на противень, печь при температуре 180 градусов в течение 20 – 25 минут до получения золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8086,'Прогреть сковороду, налить масло, всыпать куркуму, паприку, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/2c/dacc109ffb4fe2c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8086,'Положить в сковороду крупно нарезанный картофель, поперчить, посолить, обжарить до корочки со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/27/2ed8c733a002d27_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8086,'В небольшом количестве масла перемешать куркуму, соль, перец, паприку, окунуть в смесь курицу.','https:https://st.vkuso.ru/data/cache/thumb/1b/2e384f367aa431b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8086,'Крупно порезать лук и обжарить на масле, обжарить курицу со всех сторон, с добавлением розмарина.','https:https://st.vkuso.ru/data/cache/thumb/cf/4b935b02c981ccf_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11436,'Чеснок очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8086,'Масло слить, убрать розмарин, положить к мясу картофель и лук и еще пару веточек розмарина, влить в курицу и картофель с куркумой и паприкой стакан холодной воды, прикрыть крышкой тушить полчаса на слабом огне.','https:https://st.vkuso.ru/data/cache/thumb/60/8e315be62c1df60_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'В кастрюльку влить воду, всыпать желатин (50 г) и дать постоять ему столько минут, сколь указано в инструкции, затем поставить кастрюльку с желатином на огонь, нагревать его до тех пор, пока он полностью не растворится, после чего слегка остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'Взбить миксером йогурт комнатной температуры вместе с сахаром и соком лимона, не спеша влить молоко, все время помешивая, ввести желатин, еще раз взбить смесь миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'От полученной массы отделить 1/4 часть и добавить в нее какао-порошок, хорошенько перемешать, в разъемную форму влить шоколадную массу, поставить в морозилку на 10 минут для того, чтобы она застыла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'После того, как схватится шоколадный слой, на него необходимо вылить светлую массу (оставшиеся 3/4 подготовленной йогуртовой смеси) и снова убрать в холодильник, чтобы слой застыл.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'Проделать с желатином все то же самое, что делалось для йогуртовых слоев, но взять уже не 50 г, а всего лишь 10 г, с помощью блендера сделать из клубники пюре, всыпать сахар, влить чуть остывший желатин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8087,'На уже застывший светлый слой вылить слой клубничный, убрать форму в холод, после полного застывания можно подавать йогуртовый торт-желе с клубникой к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8088,'Перемешать просеянную муку с разрыхлителем и солью, добавить сметану, яйцо, 50 г сахара, 100 г размягченного сливочного масла, вымесить до получения гладкого теста, обернуть его пленкой, убрать в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8088,'Растопить в сковороде 50 г масла, всыпать 100 г сахара, нагревать около 5 минут до получения золотистой карамели, вылить пока горячая в форму, распределить быстро по дну, бананы разрезать вдоль, уложить срезом в карамель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8088,'Раскатать тесто чуть больше формы, уложить на бананы, края подогнуть внутрь. Татен банановый с карамелью готовить при 200 градусах около 35 минут, готовую выпечку прикрыть блюдом, быстро и аккуратно перевернуть, осторожно снять форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8089,'Слегка подогреть молоко, положить в него дрожжи, сахар, масло, соль, размешать, постепенно всыпать муку, хорошо вымесить минут 25 не сильно липнущее к рукам тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8089,'Прикрыть тесто тканью, поставить в тепло, чтобы тесто поднялось.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8089,'Порезать помидор, лук, ветчину, перец, натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8089,'Тесто для пиццы с перцем и ветчиной раскатать, смазать сметаной, кетчупом, уложить начинку, присыпать сыром, выпекать около получаса до подрумянивания краев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8090,'Картофельные клубни небольшого размера вымыть, очистить жесткой щеткой или ножом. Не разрезать, залить кипятком так, чтобы вода покрыла картофель. Довести до кипения на среднем огне, посолить, варить 20 – 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8090,'Для приготовления соуса нарезать любую зелень и несколько маринованных огурцов. Отдельно растереть зернистую горчицу с кленовым сиропом. Перемешать огурцы, зелень горчицу и сметану, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8090,'С картофеля слить воду, клубни подсушить в кастрюле на слабом огне, потряхивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8090,'Каждую картофелину разрезать пополам и, пока не остыла, залить сметано-горчичным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8090,'Накрыть блюдо крышкой и дать постоять пять минут для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Очистить и отварить картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Нарезать лаваш прямоугольниками по ширине сосисок, длина – от 15 до 20 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Растолочь картофель, посолить, поперчить, добавить сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Пюре намазать тонким слоем на лаваш, посыпать сыром, выложить на край сосиску и завернуть её рулетом. Таким же образом поступить со всеми сосисками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8091,'Разогреть на сковороде растительное масло, обжарить сосиски в лаваше со всех сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8092,'Свинину или другое мясо промыть проточной водой, нарезать небольшими кусочками, обжарить до готовности в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8092,'Два лаваша разложить на рабочей поверхности вместе, намазать майонезом по всему периметру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8093,'Макароны «Фузилле» или «Пенне» отварить в подсоленной воде в течение 10 минут. Жидкость слить, пасту откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8093,'Помидоры черри разрезать пополам, добавить сыр «Фета», черные маслины, молотый черный перец, сбрызнуть оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8093,'Переложить макароны, перемешать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Любым удобным способом измельчить очищенный чеснок и перец чили, всыпать соль по вкусу, влить 1 ст.л. сока лимона, добавить имбирь, куркуму, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Далее продолжить добавлять специи: черный молотый перец, кумин, мускатный орех, кориандр, гвоздику на кончике ножа, влить йогурт (60 г) и все тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Промыть под проточной водой куриное филе, на каждом куске сделать надрезы, приготовленной из йогурта, чеснока и специй пастой натереть мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Затем эту же пасту распределить по всем имеющимся на мясе разрезам, сложить куски в большую емкость, накрыть крышкой и оставить на 35-40 минут мариноваться при комнатной температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Очищенный репчатый лук разрезать пополам, после чего одну порезать не слишком толстыми полукольцами, при этом разделяя их меж собой, и сложить в миску с холодной водой, а вторую половину измельчить и отложить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'На противень уложить замаринованные куриные куски, полить сверху мясо растительным маслом (1 ч.л.) и запекать 10 минут в разогретой духовке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'По истечении отведенного времени мясо нужно перевернуть, снова полить оставшимся маслом и продолжить запекать, пока куски не покроются легкой золотистой корочкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Для приготовления йогуртового соуса необходимо смешать йогурт (100 г) с красным молотым перцем, нашинкованным луком и 1 ч.л. лимонного сока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8094,'Готовое куриное филе со специями в йогуртовом соусе посыпается высушенными от воды луковыми полукольцами и подается к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8095,'Сырые куриные яйца взбить с молоком. Всыпать пшеничную муку, просеянную вместе с разрыхлителем, перемешать до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/f3/62ef9023b319df3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8095,'Выпечь блинчики маленького размера до готовности на раскаленной сковороде.','https:https://st.vkuso.ru/data/cache/thumb/43/edb2dacae4c1a43_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8095,'Немного остудить, смазать орехово-шоколадной пастой «Нутелла».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8095,'Нарезать очищенные бананы и крупные ягоды клубники.','https:https://st.vkuso.ru/data/cache/thumb/6e/67d0851bcc91a6e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8095,'Насадить кусочки на шпажки вместе с блинчиками, вперемешку.','https:https://st.vkuso.ru/data/cache/thumb/4b/a4aecd8acde344b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Тыкву завернуть в фольгу и печь до готовности при температуре 180 градусов. Продукт превратить в однородное, мягкое пюре при помощи погружного блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Сырые куриные яйца взбить с белым и коричневым сахаром в пышную белую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Добавить 1 стакан пюре, растительное масло без запаха и растопленное сливочное масло. Еще раз взбить, масса должна загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Перемешать молотую корицу, разрыхлитель, соль и пищевую соду. Порциями ввести сухие ингредиенты в тесто, подливать молоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Готовое тесто поставить на час в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Печенье отсадить на застеленный пергаментом противень с помощью кондитерского мешка, верхушки выровнять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Печь при температуре 180 градусов, время – от 15 до 17 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8096,'Взбить охлажденные сливки с сахарной пудрой, добавить ванильный экстракт и творожный сыр. Еще раз немного взбить. На одну половинку печенья отсадить крем, накрыть второй половинкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'Осторожно отделить от желтков белки, желтки взбить вместе с сахаром (1,5 стакана) и ввести в массу муку, белки же поместить на некоторое время в холодильник,',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'Сливочное масло крупно натереть, добавить в яично-мучную смесь, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'Соком лимона погасить соду, добавить в тесто, также всыпать ванильный сахар, хорошенько все вымесить, частями подмешивая муку, положить готовое тесто в холод на полчаса, после чего переложить его на пекарскую бумагу и раскатать в пласт в 3 мм толщиной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8123,'Перемешать муку с сахаром, добавить масло, перетереть до получения маслянистой крошки, всыпать какао, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'На противень переложить получившийся круг теста и сделать бортики, по тесту равномерным слоем распределить вишни без косточек, отправить противень на 15 минут в духовку, разогретую до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'За несколько минут до готовности пирога его необходимо вынуть из духовки и покрыть ягоды ровным слоем предварительно взбитых с 1/2  стакана сахара яичных белков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8097,'Убрать пирог вишневый с безе обратно в духовку, готовить в районе 4-х минут, пока белок не станет нежно-бежевого цвета, готовый пирог нарезать пока он еще горячий и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8098,'В ножках сделать проколы острием ножа, сложить в глубокую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8098,'Смешать жидкий мед, дижонскую горчицу, белый винный уксус, чеснок, подсолнечное масло, соль, соевый соус, свежемолотый черный перец, промазать курицу, закрыть фольгой, поставить мариноваться в холодильник на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8098,'Прогреть духовку до 220 градусов, переложить ножки в форму, поместить ее на среднюю полку духовки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8098,'Запекать куриные ножки в горчично–медовом маринаде около 40 минут, поливая остатками маринада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8098,'Готовность блюда проверить ножом. Если выделится прозрачная жидкость, то ножки можно доставать и подавать к столу, присыпав порубленной зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8099,'Втереть в куриные голени (можно взять бёдра, грудку) специи и соль, обжарить в масле до золотистости, выложить на тарелку.','https:https://st.vkuso.ru/data/cache/thumb/64/cc55d1c5d8dcb64_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8099,'В оставшееся масло положить кубики лука, обжарить до прозрачного состояния, добавить натертую морковку, положить кубики перца и кусочки помидора, перемешать все с раздавленным чесноком, тушить около 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/29/2ce0094cc527b29_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8099,'К овощам влить бульон или воду, добавить рис, подсолить, перемешать, дать закипеть, тушить полчаса (смотреть по готовности риса) при среднем нагреве.','https:https://st.vkuso.ru/data/cache/thumb/11/cec34122638d611_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8099,'За 7 минут до готовности добавить кукурузу и горошек, перемешать, если надо, то подсолить.','https:https://st.vkuso.ru/data/cache/thumb/7d/2a872362d482b7d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8099,'Разложить по верху голени, закрыть крышкой, огонь сделать минимальным, томить 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/e6/2174a420367ede6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8100,'Нагреть в глубокой сковороде смесь растительного и сливочного масла, всыпать полукольца лука, закрыть крышкой, тушить примерно 20 минут до прозрачности, посолить, добавить сахар, поджарить лук до коричневого состояния.','https:https://st.vkuso.ru/data/cache/thumb/3e/18992ce9434793e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8100,'Уменьшить нагрев, добавить муку, помешивая тушить пару-тройку минут до пастоподобного состояния. Добавить бульон с вином, положить лавровый лист, дать закипеть, варить луковый суп под крышкой 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/8a/397618c4474768a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8100,'Нарезать багет на куски, полить маслом, подсушить в духовке или сковороде.','https:https://st.vkuso.ru/data/cache/thumb/fe/bc30ca0a0780efe_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8100,'Положить румяные кусочки батона на суп, присыпать сыром, запечь в прогретой духовке до зарумянивания сыра, подавать к столу сразу.','https:https://st.vkuso.ru/data/cache/thumb/5b/9caecfd95f4455b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Большую посуду для СВЧ печей поставить в микроволновку и при полной мощности разогреть на протяжении 7 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Посредством скалки раскатать каждое куриное филе, нарезать их кубиками так, чтобы одна сторона равнялась 4 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Маслом сливочным промазать нагретую емкость, сложить в нее подготовленное куриное мясо и чуть прижать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Далее, не накрывая крышкой, обжарить мясо в течение 4-х минут на полной мощности, перевернуть на другую сторону и обжарить еще 1 минуту, не уменьшая мощность.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Курицу посолить, поперчить красным и черным перцем, добавить рис, влить куриный или овощной бульон, закрыть посуду крышкой, все при той же полной мощности варить блюдо 6 минут, спустя 5 минут после того, как оно закипит, его необходимо размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'В рисово-мясную массу положить грибы, овощи (за исключением зелени) и овощную смесь из очищенной брюквы, репы, горошка и моркови, тщательно перемешать, в очередной раз добавить перец и соль, опять накрыть емкость крышкой, тушить плов с курицей, грибами и овощами в микроволновке на всей мощности 3 минуты, после чего все еще раз размешать и закрыть крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'Мощность микроволновой печи убавить до средней и не больше 1 минуты готовить, в течение этой минуты плов следует перемешать дважды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8101,'В конце достать посуду из микроволновки, не снимая крышки, плов на 10 минут оставить при комнатной температуре, снова посолить и поперчить, посыпать сверху рубленой петрушкой и подать со свежим багетом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8102,'Масло предварительно охладить, порезать на кусочки, растереть с просеянной мукой и разрыхлителем, до получения маслянистой крошки, всыпать сахар, вбить яйцо, тщательно перемешать, тесто обернуть пленкой, убрать на полчаса в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/56/ede47d414bb1a56_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8102,'Для начинки протереть сквозь сито творог, добавить сладкую сметану, яйца, перемешать миксером в однородную смесь.','https:https://st.vkuso.ru/data/cache/thumb/f6/6bb298b15c35cf6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8102,'Заполнить тестом форму, сделать бортики высотой 5 см.','https:https://st.vkuso.ru/data/cache/thumb/60/c8055841db03d60_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8102,'Положить начинку, засыпать ягодами. Выпекать открытый пирог с творожной начинкой и ягодами в уже прогретой духовке (180 градусов) около 35 минут, дать остыть, достать из формы.','https:https://st.vkuso.ru/data/cache/thumb/c4/932420e476cc8c4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8103,'Срезать у слегка черствой булочки верх, удалить мякоть и минут 5 подсушить в духовке с температурой 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/d4/9eb2393ea7693d4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8103,'Нарезать на кубики сыр и грибы, чуть подсолить, приправить специями.','https:https://st.vkuso.ru/data/cache/thumb/b4/ce86ec9c575bab4_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8103,'Заполнить подсушенные булочки, но не вровень с краями.','https:https://st.vkuso.ru/data/cache/thumb/da/06e562d78132cda_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8103,'Осторожно разбить в каждую по яйцу, поместить завтрак в булочке с грибами и сыром на 20 минут в духовку, а срезанные верхушки минут на 5.','https:https://st.vkuso.ru/data/cache/thumb/bf/35341de846c82bf_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8104,'Вымыть грибы и зелень, подрумянить кунжут.','https:https://st.vkuso.ru/data/cache/thumb/60/c52048242afd160_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8104,'Порубить чеснок и зелень.','https:https://st.vkuso.ru/data/cache/thumb/35/ad70ae6c7160335_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8104,'Для маринада смешать уксус с соевым соусом и маслом, добавить специи с зеленью и чесноком, всыпать кунжут, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/51/419fbe3faf54a51_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8104,'Грибы отварить (после закипания 15 минут), сцедить, дать остыть, переложить в банку залить шампиньоны по-корейски маринадом, закрыть крышкой, поставить на ночь в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/20/56368df32523720_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8105,'Натереть крупно сыр, лук нашинковать маленькими кубиками, обжарить на масле до прозрачности, добавить фарш, перемешать, жарить 10 минут, помешивая. Начинку подсолить, поперчить, добавить томатной пасты, перемешать, жарить еще пару-тройку минут.','https:https://st.vkuso.ru/data/cache/thumb/3f/8c1bdb85f503c3f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8105,'На лист лаваша положить половину фарша, разровнять, присыпать половинной порцией сыра, покрыть 3 ст.л. сметаны или майонеза, свернуть в трубочку. Остатки фарша и сыра положить на второй лист и свернуть.','https:https://st.vkuso.ru/data/cache/thumb/46/0b36cacc6726b46_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8105,'Яйца взбить с солью и сметаной.','https:https://st.vkuso.ru/data/cache/thumb/c2/f6bb53d8dd1c5c2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8105,'Промазать форму маслом, положить по спирали оба рулета, залить взбитой с яйцами сметаной. Выпекать мясной пирог-рулет из лаваша около получаса при температуре 200 градусов в заранее прогретой духовке, подавать пирог к столу горячим.','https:https://st.vkuso.ru/data/cache/thumb/a1/c51df77d0f041a1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'Порезать мясо на куски весом примерно 80-100 г, поместить в глубокую посуду, добавить очищенные и нарезанные кубиками овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'Очищенный измельченный чеснок вместе с грецкими орехами, соком и цедрой апельсина, специями и травами добавить к мясу и овощам, в емкость влить вино, чтобы оно покрыло ее содержимое, убрать в холодильник на 12-24 часа, чтобы мясо хорошо замариновалось.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'По прошествии отведенного времени достать из холодильника емкость с мясом и дать ему прогреться до комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'Как только мясо станет нужной температуры, его нужно достать из маринада, обсушить салфеткой, смазать перцем и солью, в чугунную жаровню влить 1/2 оливкового масла, обжарить в нем до зарумянивания мясо порциями на сильном огне, переложить обжаренные куски в миску, убрать в сторону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'На дуршлаг откинуть замаринованные овощи (маринад не выливать!!), после чего их нужно обсушить с помощью салфетки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'На остальной половине масла также на сильном огне обжарить кусочки свиной  грудинки, добавить маринованные овощи, чуть подрумянить, положить томатную пасту и 1-2 минуты пассеровать, помешивая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'К овощам добавить мясо, размешать, влить маринад, накрыть крышкой, в течение 1 часа тушить в духовке при 150 градусах, после чего снизить температуру до 125 градусов и томить все минимум 3-4 часа, затем из соуса достать мясо, сам соус процедить через ситечко, выжав жидкость из овощей (они уже не понадобятся), удалить с поверхности жир, перелить обратно в жаровню и немного уварить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8106,'Вернуть в соус мясо, прогреть его и подать говядину тушеную в вине по-провансальски вместе с полентой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8107,'Порезать филе на полосы, обжарить до золотистости.','https:https://st.vkuso.ru/data/cache/thumb/50/e1f505ed3a72c50_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8107,'Положить тщательно промытые грибы в кипящую воду, проварить минут 10, порезать на 4 части.','https:https://st.vkuso.ru/data/cache/thumb/52/e54e7c9f738bd52_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8107,'Тонко нашинковать капусту, огурцы – полукольцами.','https:https://st.vkuso.ru/data/cache/thumb/9e/91dce994f9e219e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8107,'Объединить все компоненты, перемешать с майонезом.','https:https://st.vkuso.ru/data/cache/thumb/a0/7aeec02a92678a0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8107,'Порезать хлеб на  кубики, подсушить до хруста в духовке, дать остыть, пересыпать в кулек. Перемешать масло с раздавленным чесноком, поместить в пакет к сухарям, завязать и потрясти для лучшего перемешивания. Разложить на блюде салатные листья, положить салат, сверху уложить (непосредственно перед подачей) сухарики.','https:https://st.vkuso.ru/data/cache/thumb/fb/37be0bfc2c0e0fb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8108,'Взбить растопленное масло с сахаром до получения пышной белой пены, вбить яйца перемешать.','https:https://st.vkuso.ru/data/cache/thumb/04/47060cc51d26f04_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8108,'Отдельно перемешать просеянную муку с ванилином и разрыхлителем, перемешать с яичной смесью до получения слегка комковатого теста, влить молоко, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/25/251ec666d17a025_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8108,'Наполнить формочки на 4/5. Поставить классические капкейки в прогретую до 200 градусов духовку на 20-30 минут (зависит от объема формочки).','https:https://st.vkuso.ru/data/cache/thumb/65/e9e7006a3cf6e65_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8108,'Готовые кексики установить на решетку и покрыть глазурью. Для ее приготовления к сахарной пудре добавить пару чайных ложек воды и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/ce/42d508a6efbffce_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8109,'Подготовленную куриную печень заправить солью и перцем, поджарить в разогретом масле, равномерно полить коньяком и поджечь, фламбировать около 2 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8109,'Обжарить отдельно смесь чеснока и лука, добавить ложку сахара, перемешать, нарезать небольшими кубиками яблоко, хурму, нектарин, высыпать к луку, залить апельсиновым соком,  потушить несколько минут, включить разогреваться до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8109,'Выложить в смазанные маслом формочки для запекания слой печени, затем фруктово-луковый слой, присыпать сверху сыром, отправить в духовку до зарумянивания сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8109,'Подать печень куриную с сыром и фруктами можно в формочках, а можно более оригинально: разрезать апельсин пополам, вынуть мякоть и все разложить в полученные «корзиночки».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8110,'Нашинковать и обжарить в масле лук около 5 минут, всыпать тертую морковь, продолжить жарить еще 5 минут, добавить фарш, перемешать, жарить еще 5 мин., затем положить томатную пасту.','https:https://st.vkuso.ru/data/cache/thumb/ca/462e49c77b349ca_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8110,'Растопить в сотейнике масло, добавить молоко, всыпать, постоянно мешая, муку (просеянную), нагревать порядка 10 минут, пока состав не начнет сгущаться, всыпать мускатный орех, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/de/a1e4cc3ad9d3ade_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8110,'Положить несколько ст.л. соуса на дно мультиварки, равномерно размазать, положить крест-накрест листы лазаньи, положить еще порцию соуса, далее – фарш и сыр, процедуру повторить, верх лазаньи – сырный слой. Выпекать лазанью в мультиварке полчаса.','https:https://st.vkuso.ru/data/cache/thumb/10/fa00e88181f1610_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8111,'Обжарить на сковороде с чесноком, луком и специями фарш, добавить майонез, перемешать, жарить еще пару минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8111,'Из картофеля приготовить пюре, вбить яйцо, всыпать нашинкованную зелень и муку, вымесить тесто для картофельных ватрушек с курицей и луком, остудить, разделить на небольшие кусочки, скатать шарики и приплюснуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8111,'Разложить заготовки на выстланный пергаментом и смазанный маслом противень, смазать верх яйцом, положить поверх начинку, присыпать сырной стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8111,'Выпекать ватрушки примерно четверть часа в духовке при  температуре 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Залить промытый рис кипятком на 2 см выше зерен, дать постоять полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Лук нашинковать небольшими кубиками, обжарить в масле до золотистости, добавить крупно натертую морковь, прожарить 5 минут, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Положить к овощам кубики свинины, перемешать, закрыть крышкой, тушить 20 минут, добавить томатной пасты, зиры, специй, подсолить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Пересыпать на сковороду распаренный рис, еще раз хорошо перемешать, залить кипятком на 2 см выше уровня, накрыть крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Готовить плов на сковороде со свининой около 35 минут, пока вся жидкость не впитается.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8112,'Блюдо перемешать, отключить нагрев, дать постоять еще минут 20, подавать в горячем виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8113,'Включить для прогрева до 180 градусов духовку. Мягкое сливочное масло взбить с молоком, сахаром и яйцом, всыпать муку, перемешанную с разрыхлителем, ванилин, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8113,'Раскатать его в пласт чуть больше 0,5 см, вырезать любой формочкой коржики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8113,'Разложить на противне заготовки коржиков молочных с ванилью, выпекать 15-20 минут до золотистости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8114,'Взбить в кремообразную массу сахар с мягким маслом, по одному вбить яйца, перемешивая хорошо после каждого, всыпать ваниль, перемешать. Соединить с подсоленной и просеянной мукой с добавлением разрыхлителя, вымесить до однородности тесто.','https:https://st.vkuso.ru/data/cache/thumb/b7/7a9c1b355cb0eb7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8114,'Выстлать форму пергаментом, заполнить тестом, разровнять его, уложить половинки абрикосов.','https:https://st.vkuso.ru/data/cache/thumb/23/e5aa812578c8623_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8114,'Выпекать бисквитный абрикосовый пирог примерно 40 минут. Готовность проверять зубочисткой, если сухая, то пирог готов, достать из духовки, вынуть из формы, присыпать сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/8e/04923edc8681f8e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8115,'Нарезать свиную корейку пластинами примерно по 2 см толщиной, накрыть пленкой и аккуратно отбить, втереть в куски смесь итальянских трав, соль и черный перец, оставить на 15 минут, включить разогреваться духовку до 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8115,'Нарезать кружками помидоры, лук тонкими полукольцами, шампиньоны – крупными кусочками, переложить мясо на противень, сверху разложить кружки помидоров, присыпать луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8115,'Смешать сметану и тертый чеснок, смазать этим соусом лук, выложить на него грибы, присыпать крупно натертым сыром и нашинкованным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8115,'Запекать свинину с грибами по-деревенски 40 минут, потом увеличить нагрев и готовить до зарумянивания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Подготовить желатин, согласно инструкции на пачке только воду заменить на молоко.','https:https://st.vkuso.ru/data/cache/thumb/ae/2fce6787b59eeae_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Растереть масло, яйца с творогом и сахаром, влить остуженный молочно-желатиновый раствор, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/29/b866183c0e0b729_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Дно у разъемной формы заполнить печеньем, промежутки между ними засыпать крошкой, сверху вылить творожную смесь.','https:https://st.vkuso.ru/data/cache/thumb/de/b70a5ac903516de_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Поставить форму в холодильник примерно на 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/72/c864a722be0d272_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Достать заготовку творожно-малинового торта из печенья, уложить на него малину.','https:https://st.vkuso.ru/data/cache/thumb/42/9fca3042f69a242_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8116,'Приготовить по инструкции на упаковке желе, дать остыть, залить ягоды, убрать опять в холодильник минимум на 4 часа.','https:https://st.vkuso.ru/data/cache/thumb/dd/f82fd78b0c9eedd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8117,'Порезать лук и кабачки на кружочки, присыпать специями и солью, перемешать, добавить пластинки плавленого сырка, еще раз хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8117,'Влить масло, помешивая, прогреть на малом огне до полного расплавления сыра, влить взбитые яйца, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8117,'Форму смазать маслом, заполнить овощной смесью, готовить кабачковую запеканку «Касэрол»  с плавленым сыром  в прогретой до 190 градусов духовке до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8136,'Измельчить в блендере овсянку и клубнику, влить сырое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Замесить гладкое тесто, как для пирожков, только чуть-чуть круче, прикрыть полотенцем, дать хорошо подойти в теплом месте, обмять, поставить еще раз подняться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Припустить с небольшим количеством воды рыбу и порезать мелко, отварить рис и картофель в мундирах, порезать клубни на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Обжарить кубики лука до прозрачности на масле, добавить нашинкованный зеленый лук, жарить еще пару-тройку минут, положить рис, рыбу, картофель, подсолить, размешать, дать начинке для постного рыбного пирога с картофелем и луком хорошо остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Раскатать из теста пласт, оставить чуть-чуть для украшения, разложить начинку, придавить слегка руками. Разрезать по краям тесто полосками по 4 см, далее уложить косичкой, как на фото.','https:https://st.vkuso.ru/data/cache/thumb/77/0e8bc1133c9e177_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Верхнюю часть выложить в форме головы, а нижнюю в форме хвоста. Из остатков теста скатать лапки, глаза и брови.','https:https://st.vkuso.ru/data/cache/thumb/bd/7914131427696bd_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Используя ножницы сделать зубы и шероховатости кожи, смазать верх пирога маслом с добавлением щепотки сахарной пудры, выпекать при 190 градусах до золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/10/dbd5ff245ae4c10_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8118,'Готовую выпечку переложить на деревянную досточку, прикрыть льняным полотенцем, дать постоять минут 10 и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/15/89af1d642eb7715_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8119,'Взбить до состояния пышной массы сахар и яйца, всыпать гашеную соду и порциями муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8119,'В форму вылить 2/3 теста, к остальной части добавить какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8119,'На тесто в форме выложить обваленные в муке ягоды и порции темного теста в произвольном порядке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8119,'Выпекать простой тортик с ягодами полчаса в духовке с температурой 180 градусов готовность проверять спичкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8119,'Хорошо перемешать сахар и сметану, холодный корж, разделить вдоль на 2 части, промазать кремом и полить на верх торта.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Желтки перемешать с сахаром, солью и маслом.','https:https://st.vkuso.ru/data/cache/thumb/1c/584629fa3e5061c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Влить молоко, перемешать, небольшими порциями, перемешивая засыпать муку. В однородное тесто добавить белки, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/cb/fbf092e531fe3cb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Очистить яблоки и нарезать тонкими кружками. Разогреть хорошо сковороду, смазать маслом или кусочком сала. Положить на сковороду яблоки.','https:https://st.vkuso.ru/data/cache/thumb/f4/eb51c07bb85fcf4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Залить яблоки тестом, зажарить.','https:https://st.vkuso.ru/data/cache/thumb/aa/1f651022c3420aa_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Перевернуть, зажарить с другой стороны.','https:https://st.vkuso.ru/data/cache/thumb/a4/2dc8ff65a4284a4_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8120,'Горячие блины свернуть трубочкой, разложить по тарелкам, полить медом, можно присыпать сахарной пудрой с корицей или полить вареньем.','https:https://st.vkuso.ru/data/cache/thumb/39/b81ac3278c0ba39_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8121,'Тщательно взбить сахар с яйцами, перемешать с остальными ингредиентами для коржа, выпекать полчаса, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8121,'В чашу блендера положить творог, всыпать сахар, добавить, ванилин, немного сметаны и взбить до однородной массы, добавить раствор желатина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8121,'Холодный корж для торта с творожно-клубничной прослойкой разрезать пополам, положить один в разъемную форму, уложить на него клубнику, залить творожной смесью, поставить на четверть часа в морозилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8121,'Накрыть второй половинкой коржа, оформить клубникой, залить желе, поставить на час в морозилку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8122,'Расплавить на сковороде сахар с добавлением растительного масла, почистить имбирь, разрезать кусочек пополам и положить в сковороду с карамелью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8122,'Мелко нашинковать зелень петрушки и базилик, потереть сыр, нарезать мелко соленые огурцы, перемешать, заправить майонезом, включить для разогрева на 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8122,'Кусочки свинины немного отбить, надрезать вдоль, чтобы получились кармашки, посолить, поперчить, нафаршировать их смесью сыра, зелени и майонеза, переложить отбивные в сковороду с карамелью и обжарить по 5 мин с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8122,'Положить мясо на противень, запекать в духовке 5-7 минут, подавать свинину с сыром запеченную в карамели горячей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8136,'Для начинки перемешать нежирный творог, изюм, ванилин и корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8123,'В творог добавить сахар, растереть вилкой, добавить гашеную соду, сметану, вбить яйца, всыпать кусочки чернослива, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8123,'Третью часть крошки  выложить в форму, поверх разместить половину творожной начинки, прикрыть таким же количеством крошки, далее положить опять слой начинки, завершить слоем из остатков крошки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8123,'Выпекать пирог из песочной крошки с творогом и черносливом минут 50 при температуре 180 градусов, дать остыть, вынуть из формы, оформить растопленным шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8124,'Столовый уксус развести водой вместе со свежими куриными желтками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8124,'Непрерывно помешивать, поставить на огонь и прогреть на водяной бане. Смесь снять с огня, продолжать взбивать до полного остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8124,'В другой емкости перемешать готовую горчицу, соль, черный молотый перец, цедру и лимонный сок. Полученную массу добавить к остывшей яичной массе, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8125,'Для приготовления начинки взбить с помощью миксера полстакана сахарного песка с сырыми куриными яйцами, добавить творог. Взбить в пышную массу. Если творог был с крупинками, то продукт лучше предварительно растереть до состояния пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8125,'Приготовить тесто: размягченное сливочное масло взбить с сахарным песком, всыпать разрыхлитель, измельченные овсяные хлопья. Тесто должно быть рассыпчатым, крошащимся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8125,'В форму для выпекания всыпать две трети приготовленного теста. Сверху положить творожную начинку, замороженные ягоды черники, клюквы, клубники или малины, вдавить их в творожную массу, засыпать остатками теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8125,'Можно использовать один вид ягод или сделать микс из нескольких. Печь при температуре 180 градусов в течение 40 минут, до образования золотистой корочки. Дать блюду остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8126,'Капусту брокколи вымыть, обсушить, разделить на соцветия. Вскипятить подсоленную воду, выложить капусту, оставить вариться на три минуты. Переложить соцветия из кипятка в ледяную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8126,'Промыть, очистить и нарезать морковь. Натереть сыр чеддер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8126,'Растопить в кастрюле сливочное масло. Добавить четверть стакана пшеничной муки. Перемешать, подержать на огне три-четыре минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8126,'Влить молоко или сливки, овощной бульон. Добавить мускатный орех, прогревать под крышкой, готовить 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8126,'Положить репчатый лук, морковь и капусту, варить суп в течение получаса. Через полчаса снять крышку, размять овощи. Добавить половину нормы тертого сыра. Перемешать, сыр должен расплавиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8127,'Поместить в шейкер ликер Трипл-Сек или Куантро, текилу, лед, сок лайма. Потрясти, отфильтровать ото льда, вылить в бокал.','https:https://st.vkuso.ru/data/cache/thumb/93/2e9c6476a2ab793_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8127,'Края бокала должны быть посыпаны солью. Для этого нужно сделать следующую процедуру: на тарелку налить сок лайма, на вторую насыпать соль. Взять бокал за ножку, обмокнуть его в сок и сразу в соль. Лишнее стряхнуть. Получается красивый белый соленый поясок.','https:https://st.vkuso.ru/data/cache/thumb/7e/25aa44113058f7e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Приготовить тесто 1: просеять в посуду муку и разрыхлитель. Положить сметану, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Приготовить тесто 2: просеять муку и разрыхлитель, положить подтаявшее сливочное масло, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Оба вида теста скатать в шар, положить на стол, посыпанный мукой.','https:https://st.vkuso.ru/data/cache/thumb/dc/0b4c06aa3c3f6dc_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Раскатать оба шара, чтобы получился пласт в 1,5 сантиметра толщиной. Положить один пласт на другой. Раскатать их вместе в пласт 1 сантиметр толщиной.','https:https://st.vkuso.ru/data/cache/thumb/8a/ead631c5307878a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Сложить конвертом. Повторить процедуру еще 3 раза. Сложить тесто конвертом, обернуть пленкой, отправить на 30 минут в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/47/643611674cff947_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Достать тесто из холодильника, раскатать в прямоугольник 0,5 сантиметров толщиной.','https:https://st.vkuso.ru/data/cache/thumb/54/96397b4cf268654_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Разделить пласт на две длинные полоски. Порезать полоски на треугольники с основанием по 4-5 сантиметров. У основания положить начинку, свернуть в виде рогалика, при этом чуть-чуть растягивать уголки, чтобы центр не был очень толстым.','https:https://st.vkuso.ru/data/cache/thumb/2e/21d1a82153add2e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Разложить рогалики на противень на расстоянии друг от друга. Готовить 12-15 минут, соблюдать температуру 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8128,'Остудить рогалики, посыпать сахарной пудрой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8129,'Натереть отваренный в мундире картофель на крупной терке, слегка присолить, слить масло из шпрот, рыбу измельчить, огурец нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8129,'Поставить на плоское блюдо разъемную круглую форму без дна. Выложить первый слой – тертый картофель (треть), на него уложить шпроты, затем опять картофель и огурец, закончить слоем картофеля и мелко порезанными маслинами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8129,'Снять форму, украсить сверху слоеный картофельный салат со шпротами и маслинами листьями салата и целыми рыбками шпрот, присыпать поджаренным кунжутом, для улучшения вкуса салат перед подачей лучше охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Порезать лук, крупно потереть морковь. Обжарить лук, добавить морковь. Жарить, пока морковь не станет мягкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Почистить картофель, порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Крупно порезать грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Обязательно сполоснуть горшки холодной водой. Положить в горшочки по кусочку сливочного масла, по куриной ножке. Разложить одинаковое количество порезанного картофеля и грибов. Добавить по ложке зажарки, 1/3 маленькой ложки соли. Посыпать немного приправой, чтобы не сбился вкус грибов. Налить бульон или воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Закрыть крышками. Отправить в духовку на 1,5-2 часа, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8130,'Посыпать суп с грибами и курицей в горшочках зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8131,'Взбить миксером яйца и сахар миксером. Насыпать 1,5 стакана муки. Еще раз взбить. Получается тесто среднее по консистенции. Насыпать ванилин.','https:https://st.vkuso.ru/data/cache/thumb/7f/d5824f68696627f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8131,'Выложить яблоки в форму.','https:https://st.vkuso.ru/data/cache/thumb/5e/c640c4d48e7225e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8131,'На яблоки вылить тесто.','https:https://st.vkuso.ru/data/cache/thumb/5c/6266a25d9d28f5c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8131,'Отправить на 30-40 минут в духовку. Перевернуть форму, осторожно снять.','https:https://st.vkuso.ru/data/cache/thumb/e5/039320e06792ee5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8131,'Когда любимая шарлотка с яблоками по-домашнему остынет, посыпать пирог сахарной пудрой. Подавать к чаю.','https:https://st.vkuso.ru/data/cache/thumb/02/5c9d446afe99102_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8132,'Соединить все продукты. Вылить смесь в высокий пластиковый контейнер, так как кекс увеличится. Накрывать крышкой не нужно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8132,'Готовить кекс в микроволновке при высокой мощности. Получается шоколадный кекс с овсянкой за 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Нарезать отварные креветки (мелкие можно не резать), переложить в салатник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Удалить из авокадо косточку, почистить, нарезать кубиками, сбрызнуть лимонным соком и высыпать к креветкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Приготовить из масла, уксуса и меда соус для салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Разрезать апельсин пополам, вынуть аккуратно мякоть, удалить пленки, нарезать на кубики, добавить к смеси креветок и авокадо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Добавить в миску салата мелко нашинкованный лук, заправить соусом, посолить, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8133,'Украсить края апельсиновых «чашечек» зубчиками, переложить в них салат из креветок с апельсином и авокадо и убрать на холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'Нагреть масло в сковороде. Положить имбирь, горчицу горошком, чеснок. Обжаривать, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'Когда смесь станет золотистой, положить морковь. Обжаривать, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'Равномерно разложить кусочки курицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'Обжарить с каждой стороны по 5-7 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'Добавить соус из сметаны и томатной пасты. Если соус густой, то обильно намазать соусом курицу. Если соус жидкий, то вылить его на содержимое сковороды. Накрыть сковороду крышкой, чуть-чуть убавить огонь, тушить курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8134,'В конце готовки посыпать филе из курицы под томатным соусом карри и паприкой, чтобы блюдо стало ароматным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8135,'Поместить все продукты в большую емкость, измельчить блендером, чтобы получилось пюре. Должно получиться однородное, среднее по консистенции тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8135,'Выложить массу ложкой на горячую сковороду с растительным маслом. Обжаривать оладьи из творога и манки с бананом несколько минут со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11436,'Пропустить через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8136,'В форму для выпекания вылить тесто, поставить в духовку на 5 – 10 минут. Сверху выложить творожную массу, печь еще полчаса при невысокой температуре, торт не должен пригореть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8136,'Остывшую выпечку разрезать пополам вдоль, выложить куски друг на друга, должно получиться четыре слоя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8137,'Геркулес перемолоть в муку, добавить жидкий натуральный мёд, сырое куриное яйцо, белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8137,'Влить кефир, приготовить блинное тесто. Дать тесту постоять до набухания хлопьев.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8137,'Добавить разрыхлитель, ванилин из пакетика, молотую корицу, какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8137,'Выложить в форму нарезанные пластинками яблоки без сердцевины, залить полученной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8137,'Печь до готовности в течение получаса, температура приготовления – 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8138,'Обжарить в течение 2-3 минут кольца ананаса на разогретой сковороде гриль смазанной оливковым (подсолнечным) маслом, затем перевернуть на другую сторону, и также обжарить 2-3 минуты, кольцам дать остыть и нарезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8138,'Подготовленную куриную печень пожарить до готовности, заправить солью и молотым черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8138,'Приготовить из оливкового масла, бальзамического уксуса и соевого соуса заправку для салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8138,'Выложить салатник измельченными руками листьями салата, добавить кусочки ананаса, куриную печень, полить заправкой, перемешать, добавить орешки, сверху салат с куриной печенью, ананасом и кедровыми орехами посыпать сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8139,'Перетереть в однородную массу творог и спелый очищенный банан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8139,'Добавить молотую овсяную крупу или хлопья, перемешать руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8139,'Готовое тесто убрать на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8139,'Сформовать небольшие шарики, обвалять в кокосовой стружке, немного сплющить, выложить на застеленный бумагой противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8139,'Разогреть духовку до 180 градусов, готовить печенье в течение 12-15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8140,'Свежую или замороженную клубнику взбить с помощью блендера в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8140,'Отдельно в воде замочить желатин на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8140,'Ягодное пюре прогреть на огне при постоянном помешивании, добавить по вкусу сахарный песок или сахарозаменитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8140,'Влить набухший желатин, перемешать, разлить в формочки. Украсить орешками или фруктами, поставить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8141,'Удалить внешние листья и ножки у брюссельской капусты. Промыть овощ в воде с добавлением лимонного сока или уксуса, это позволит продукту не потерять естественный цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8141,'Вскипятить воду с солью, положить горсть капусты, закрыть крышкой. В начале закипания всыпать еще горсть. Операцию повторять до тех пор, пока вся капуста не окажется в кастрюле. Крышку снять. Весь процесс отваривания займет 20 – 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8141,'Растопить на сковороде сливочное масло вместе с растительным, вмешать смесь в пшеничную муку, перемешать, готовить две минуты. Влить молоко порциями, помешивать, готовить восемь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8141,'Капусту выложить в дуршлаг, промыть холодной водой, затем выложить на сковороду, перемешать с мучным соусом. Переложить готовое блюдо на тарелку, посыпать измельченной зеленью петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8142,'Перемешать овсяные хлопья и манную крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8142,'Залить смесь кефиром, оставить на два часа или на ночь для набухания. Это обязательно, в противном случае блинчики просто развалятся в процессе обжаривания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8142,'Взбить венчиком сырые куриные яйца, добавить в крупу вместе с пищевой содой. Еще раз все перемешать, снова взбить венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8142,'Выкладывать массу на сковороду ложкой, обжаривать с двух сторон до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8143,'Стручковую фасоль отварить в воде в течение двух минут, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8143,'Нарезать соломкой куриную грудку, репчатый лук, сладкий болгарский красный перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8143,'Мясо обсушить бумажным полотенцем и обжарить на сковороде, на оливковом масле, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8143,'Лук бланшировать в кипятке в течение пяти минут, затем перец, прогреть пять минут, затем фасоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Вбить яйца по одному, перемешать на низкой скорости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8143,'Соединить овощи с грудкой, тушить все вместе три-пять минуты. Салат снять с огня, влить соевый соус и бальзамический уксус, соль и молотый перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8144,'Очистить у крупных и сладких яблок верхнюю треть. Аккуратно вырезать сердцевину. Выскоблить ложкой часть мякоти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8144,'Смешать сырой яичный желток с мягким творогом, сахаром, ванилином из пакетика. Начинить полученной смесью яблоки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8144,'Поставить десерт в жаропрочную форму, подлить немного воды, печь в течение 25 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8144,'Подать яблоки на стол в теплом виде, можно полить жидким натуральным мёдом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8145,'Салат руккола разобрать, вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8145,'Помидоры черри разрезать пополам или на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8145,'Приготовить заправку из оливкового масла, красного бальзамического уксуса, соевого соуса, мёда, измельченного зубчика чеснока. Взбить массу вилкой до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8145,'Выложить салат на порционные тарелки, сверху – помидоры черри, полить заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8145,'Чайной ложкой выложить кусочки мягкого козьего сыра. Подать на стол сразу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8146,'Отварить куриную грудку 20 минут на режиме «Тушение», измельчить мясо, цветную капусту, морковь и очищенные порезанные кабачки в блендере, чуть посолить, переложить в чашу с бульоном, выставить режим «Тушение», готовить детское пюре из курицы и овощей в мультиварке полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8146,'Вкус пюре можно разнообразить, добавляя различные ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8147,'Залить листья винограда кипятком, дать постоять полчаса, промыть рис, готовый фарш смешать с рисом, приправить специями, посолить, влить чуть воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8147,'Срезать у листьев основание, завернуть в них фарш конвертиками, переложить в мультиварку, немного посолить, придавить грузом, залить до половины водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8147,'Долма в мультиварке готовится на режиме «Тушение» полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8147,'Приготовить в блендере из сметаны, зелени и чеснока соус, разложить готовую долму по тарелкам, подать с соусом, посыпать измельченной зеленью, по желанию можно тушить не в воде, а в соусе, для блюда вместо свежих листьев можно использовать заготовленные впрок соленые или квашеные листья винограда.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8148,'Промыть рис, залить водой, варить на тихом огне до полуготовности, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8148,'Подлить молоко, посолить, варить кашу до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8148,'Вымочить курагу в апельсиновом соке в течение часа или оставить на ночь. Нарезать набухший сухофрукт на кусочки, добавить в рисовую кашу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8149,'Яблоки вымыть, плоды разрезать пополам, вынуть сердцевину, мякоть нарезать тонкими ломтиками или натереть на специальной терке для чипсов, толщина нарезки – полтора-два миллиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8149,'Отдельно смешать коричневый сахар с молотой корицей. Яблочные ломтики обвалять в приготовленной смеси с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8149,'Застелить пергаментом противень, выложить ломтики, поставить в горячую духовку. Печь по часу с каждой стороны, температура – 100 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Любую рыбу очистить и разделать, вымыть, варить в течение 20 минут с репчатым луком, он должен быть крупно нарезан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Соль и перец – по вкусу, добавить любимые специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Готовый рыбный бульон процедить в другую емкость, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Нарезать картофель и лук-порей, всыпать в блюдо, варить 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Рыбное филе нарезать кусками и положить в суп, варить еще пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8150,'Для приготовления заправки смешать пшеничную муку с молоком, разбить комочки. Смесь должна стать однородной, влить её в суп и поварить еще несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Помыть помидоры, облить кипятком, снять шкурку, нарезать на крупные куски, нашинковать мелко лук, переложить в мультиварку, готовить полтора часа на режиме «Тушение».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Дать массе остыть, протереть сквозь сито или измельчить блендером, дать постоять, далее можно поступить двояко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Или слить лишнюю жидкость, переложить смесь опять в чашу мультиварки, всыпать специи, выставить режим «Варка на пару», готовить 15 минут, должно хорошо прокипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8151,'Разлить приготовленный кетчуп в домашних условиях в мультиварке по баночкам, можно при желании закатать крышками для длительного хранения. Для любителей «кислинки» добавить в конце варки столовую ложку яблочного уксуса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8152,'Подготовить, помыть и обсушить свинину, натереть смесью масла с раздавленным чесноком, укропом, солью и черным перцем, положить в контейнер, дать постоять пару часов в холодильнике (можно ночь).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8152,'Переложить мясо в чашу мультиварки, залить маринадом, готовить 15-20 минут в режиме «Выпечка», перевернуть и еще 15-20 минут, затем переключить в режим «Тушение» на 3 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8152,'Открыть крышку после отключения, подержать готовое мясо в чаше, чтобы подсохло, буженина в мультиварке по-домашнему вкусная как горячее блюдо, так и как холодная закуска.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Приготовить пакетики разноцветного желе, сократив воду в два раза. Можно взять желатин и покрасить его ягодным соком (ложку желатина залить половиной стакана сока). Дать настояться 30 минут, нагреть на водяной бане, пока не растворится. Разлить по формочкам, отправить в холод на час.','https:https://st.vkuso.ru/data/cache/thumb/76/1b24c87988f3576_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Порезать на треугольники и квадраты, которые будут добавлены внутрь торта и использованы для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Приготовить бисквит: взбить яйца и сахар в пену, насыпать муку. Взбить, вылить в форму.','https:https://st.vkuso.ru/data/cache/thumb/c2/11f1362b408f5c2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Готовить 20 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/42/728ee13c37b7e42_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Порезать бисквит на кусочки 1 на 1 сантиметр.','https:https://st.vkuso.ru/data/cache/thumb/d1/6c05c1b4c4242d1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Залить желатин молоком или кипяченой водой. Перемешать, подождать, пока набухнет, растворить на водяной бане.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Взбить творог, сметану, сахар, ванилин, сыр маскарпоне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Остудить желатин, вылить в творожную массу. Взбить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Положить порезанный цветной желатин и кусочки бисквита. Перемешать, положить в форму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Произвольно разложить по поверхности кусочки бисквита, чтобы получилась имитация основы торта. Вдавливать кусочки в массу, чтобы получилась ровная поверхность.','https:https://st.vkuso.ru/data/cache/thumb/47/3ea94fabc085c47_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Накрыть торт, отправить на 3 часа в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/6e/5b18d55131a056e_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8153,'Перевернуть на блюдо. Украсить торт-чизкейк «Разноцветные льдинки» кусочками желе.','https:https://st.vkuso.ru/data/cache/thumb/50/4888bc26b2d2750_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8154,'Замесить на воде тесто из предложенных ингредиентов (масло не добавлять), накрыть тканью, отставить на 1 час, затем добавить масло, вымесить, разделить пополам, для более тонкой основы можно разделить и на три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8154,'Смазать маслом чашу, сделать из бумаги для выпечки две длинных полоски, поместить их в чашу крест-накрест, чтобы потом можно было легко достать пиццу, распределить равномерно по дну одну часть теста, смазать смесью кетчупа (томатной пасты) и майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8154,'Нарезать все продукты для начинки, выложить поверх смазанного коржа, присыпать натертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8154,'Готовится пицца в мультиварке по-домашнему 45-60 минут в режиме «Выпечка», остатки теста можно положить в морозилку и хранить для другого раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8154,'Пицца – это универсальное блюдо, можно приготовить из любых ингредиентов, которые есть в наличии или остались после застолья, получается всегда вкусно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8155,'Крупно потереть кабачки, отжать сок. Добавить к кабачкам прессованный чеснок, соль.','https:https://st.vkuso.ru/data/cache/thumb/19/1064284d5a21919_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8155,'Растворить муку в небольшом количестве молока, перемешать. Налить остальное молоко, вбить яйца, перемешать, посолить.','https:https://st.vkuso.ru/data/cache/thumb/4e/6a3e54d37bfc54e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8155,'Намазать форму сливочным маслом, разложить кабачки, залить смесью из яиц. Добавить зелень, разложить кусочки помидоров без кожуры. Посыпать омлет тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/43/2d3ad4a640ffd43_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8155,'Отправить на 30-35 минут в духовку, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/62/b2ff49a63710a62_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Взбить яйца, творог, сахар до однородности.','https:https://st.vkuso.ru/data/cache/thumb/08/7971e618d5e1108_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Добавить йогурт, ванильную эссенцию. Взбить. Насыпать муку, взбить до однородности. Должна получиться пышная масса.','https:https://st.vkuso.ru/data/cache/thumb/39/228765e4d207f39_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Положить в тесто ягоды. Осторожно размешать. Если ягоды замороженные, то не размораживать.','https:https://st.vkuso.ru/data/cache/thumb/57/c24721029a51c57_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Намазать формочки сливочным маслом. Разложить массу в формочки.','https:https://st.vkuso.ru/data/cache/thumb/2d/7feb00cb4e5452d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Отправить на 40 минут в духовку.','https:https://st.vkuso.ru/data/cache/thumb/af/2ef6b7374869caf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8156,'Окунуть ягоды в кленовый сироп или жидкий мед. Украсить запеканку.','https:https://st.vkuso.ru/data/cache/thumb/9a/25a19e6b4aaa89a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8157,'Вскипятить молоко с содой на режиме «Молочная каша», влить в горячее молоко растворенный в воде сахар, переключить в режим «Тушение», сгущенка в мультиварке по-домашнему будет готова через 2 часа (за это время размешать 5-6 раз).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8157,'Отходить далеко лучше не надо: может убежать. Готовую сгущенку остудить, убрать в холодильник, она станет гуще.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Подготовить куриные бедрышки: мясо отделить от косточки. Это ускорит процесс приготовления. Кожу необходимо тоже снять. Посыпать мясо солью и перцем.','https:https://st.vkuso.ru/data/cache/thumb/b4/b2556db27b3b1b4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Подготовить овощи. Взять помидоры – подойдут как свежие, так и консервированные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Почистить чеснок, вымыть зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Измельчить чеснок или пропустить через пресс. Порубить лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Поставить сковороду на огонь, налить масло. Обжаривать чеснок и лук минуту.','https:https://st.vkuso.ru/data/cache/thumb/08/4e4fdaf53381f08_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'С помидор снять кожуру, мякоть измельчить. С консервированных помидор шкурка снимается без проблем. Со свежих помидор легче снять шкурку, если на минуту положить их в кипяток, слить воду, залить холодной водой. Через 30 секунд кожура очень легко снимется.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Сделать средний огонь, выпарить почти всю жидкость, не накрывая крышкой. Через 10 минут насыпать специи: перец, соль, 2-3 щепотки сахара. Добавить орегано, базилик. Перемешать все, попробовать на вкус. Убрать сковороду с огня.','https:https://st.vkuso.ru/data/cache/thumb/fe/882dac4733269fe_434x295.jpeg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Панировочные сухари можно сделать из залежавшихся кусочков батона (просто покрошить их).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Потереть сыр на средней терке, соединить с сухариками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'В три разные тарелки положить панировку, взбитое яйцо, муку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Взять бедрышки. Обвалять в муке, потом в яйце, потом в сырных сухарях.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Нагреть сковороду, налить растительное масло, положить бедрышки. Обжаривать приблизительно по 3-4 минуты со всех сторон. Чтобы корочка была хрустящая, крышкой не накрывать. Если бедрышки большие, то время приготовления увеличится. За счет того, что мясо снято с кости, оно готовится достаточно быстро.','https:https://st.vkuso.ru/data/cache/thumb/24/c47655760103124_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Дальше есть три варианта. Можно положить томатный соус на готовые бедрышки, посыпать сыром, накрыть крышкой, готовить несколько минут, чтобы расплавился сыр.','https:https://st.vkuso.ru/data/cache/thumb/94/6e8f055bb41e394_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Если бедрышек много, то подойдет второй способ: переложить бедрышки со сковороды на противень, намазать томатной смесью, посыпать сыром, отправить под гриль или подержать в горячей духовке, пока сыр не расплавится.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8158,'Также можно переложить бедрышки в керамическую посуду, распределить сверху томатный соус. Потереть сыр, посыпать мясо.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8159,'Взять холодное молоко, вылить в большую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8159,'Добавить кофе, сахар, мед, сахарозаменитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8159,'Взбивать миксером 30 секунд на средней скорости, минуту на большой скорости. Масса увеличится приблизительно в три раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8159,'Масса быстро оседает, поэтому ее необходимо съесть сразу после приготовления.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8160,'Мелко нарезать луковицу, натереть морковь, нарезать соломкой кабачок. Помидор ошпарить и снять кожицу, мякоть измельчить. Нарезать пластинками шампиньоны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8160,'Морковь и лук обжарить на растительном масле до золотистого цвета на тихом огне. Добавить в обжарку грибы, еще немного обжарить, положить нарезанные помидоры и кабачки, потушить несколько минут.  Можно добавить немного воды, чтобы масса не пригорела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8160,'Затем влить остальную воду, положить лавровый лист, соль, довести до кипения и добавить домашнюю лапшу или макароны, приготовленные  из твердых сортов пшеницы. Прогревать на среднем огне до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8161,'Репчатый лук и чеснок мелко нарезать. Добавить мясной фарш, влить соевый соус, посолить по вкусу, всыпать сушеный базилик и черный молотый перец. Массу перемешать вручную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8161,'Расстелить на столе пищевую пленку, выложить мясную смесь, придать ей форму «буханки». Пленку снять, рулет переложить в форму для выпекания. Прогревать 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8161,'Запеканку смазать томатной пастой, печь еще столько же времени. Еще раз смазать «буханку» томатной пастой, печь до готовности. Блюдо вынуть из духовки и дать немного остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8162,'Подготовить куриные сердечки, обжарить в растительном масле до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8162,'Нашинковать мелко лук, порезать огурцы, вареную морковь (можно взять корейскую) и сердечки нарезать соломкой, перемешать, натереть крупно яйца, высыпать в салат, заправить майонезом, черным перцем, солью, все аккуратно смешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8162,'Переложить салат из куриных сердечек с морковью и огурцами в салатник, перед подачей желательно охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8163,'Яблоко очистить от сердцевины и кожуры, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8163,'Отварить овсяные хлопья так, как написано на упаковке, довести до кипения на небольшом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8163,'Кашу переложить в тарелку, добавить жидкий натуральный мёд, посыпать яблоками, молотой корицей и измельченными грецкими орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8164,'Приготовить маринад из соевого соуса, растительного масла, мёда, очищенного и натертого имбиря, измельченной цедры, апельсинового сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8164,'Полученной смесью натереть куриные крылышки, сложить в емкость и поставить на три часа в холодильник для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8164,'Противень смазать растительным маслом, выложить крылышки, печь при температуре 180 градусов в течение 30 – 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8164,'При подаче выложить изделия на хорошо вымытые и обсушенные листья зеленого салата, украсить перьями зеленого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8165,'Плод авокадо разрезать пополам, удалить косточку. Вынуть часть мякоти ложкой, сделать выемку под яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8165,'Противень смазать маслом, выложить авокадо срезами вверх, вылить яйца в приготовленные «лунки».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8165,'Печь блюдо в течение 15 – 20 минут, до полной готовности. Можно посыпать молотым перцем, зеленью, сухими травами, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Смешать при помощи миксера дрожжи с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Насыпать соль, муку, сахар, вбить яйца. Перемешивать несколько минут на маленькой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Положить сливочное масло. Перемешивать 5-6 минут до однородности. Масса должна отставать от стенок. Если необходимо, досыпать несколько ложек муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Намазать большую емкость растительным маслом, положить тесто. Накрыть пищевой пленкой, отправить в холодильник на 6-15 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Посыпать стол мукой, раскатать тесто до толщины 1 сантиметр. Вырезать круги диаметром 7-8 сантиметр. Выложить заготовки на поверхность, посыпанную мукой. Накрыть пленкой, намазанной маслом. Отставить на несколько часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Приготовить начинку из свежей клубники. Порезать клубнику, измельчить в блендере. Вылить массу в сотейник, насыпать сахар, добавить сок лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Варить 20 минут, помешивая. Остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Нагреть масло в кастрюле или сковороде. Обжарить пончики со всех сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Выложить пончики на салфетки, чтобы стек жир. Обвалять пончики в ванильном сахаре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8166,'Выложить начинку в кондитерский мешок с насадкой диаметром 6-7 миллиметров. Наполнить пончики начинкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8167,'Отварить и нарезать мелкими кубиками филе индейки, огурец (без шкурки), кальмары, лук, все перемешать, заправить майонезом и посолить, отварить яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8167,'Выложить салатник измельченными листьями салата, высыпать на них крупно натертые белки яиц, смазать майонезом, добавить слой мясной смеси, равномерно присыпать крупно натертым сыром, смазать майонезом, присыпать мелко натертыми желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8167,'Салат с индейкой, кальмарами и огурцом будет еще вкуснее, если перед подачей к столу его охладить, украсить измельченной зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8168,'Перетереть в крошку мягкое сливочное масло и муку. Насыпать сахар, вбить яйцо. Сформировать из теста шар, обернуть в полиэтилен. Отправить в холодильник на 30 минут. Если шар не получается, то добавить в тесто ложку холодной воды.','https:https://st.vkuso.ru/data/cache/thumb/cb/3a8104bdc2b47cb_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8168,'Почистить яблоки, вырезать семена. Порезать яблоки на 2 части. На каждой половинке сделать ножом сеточку.','https:https://st.vkuso.ru/data/cache/thumb/81/eb26b46d923ed81_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8168,'Приготовить заливку: взбить яйца и сахар, положить сметану, снова взбить.','https:https://st.vkuso.ru/data/cache/thumb/5f/d7d4cf2553a305f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8168,'Раскатать тесто в пласт, переложить его в формочку, намазанную сливочным маслом и посыпанную манной крупой или мукой. Лишнее тесто обрезать. Выложить на тесто порезанные яблоки, вылить сметано-яичную заливку.','https:https://st.vkuso.ru/data/cache/thumb/85/9a87506e847f985_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8168,'Готовить пирог с яично-сметанной заливкой и яблоками в духовке 30-35 минут.','https:https://st.vkuso.ru/data/cache/thumb/ff/cb1996065a17bff_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Вымыть чернослив и курагу проточной водой. Налить горячую воду, отставить на 15-20 минут, чтобы сухофрукты размякли.','https:https://st.vkuso.ru/data/cache/thumb/b4/891aea6898963b4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Обжарить чуть-чуть арахис на сухой сковороде. Остудить, почистить от кожуры. Измельчить.','https:https://st.vkuso.ru/data/cache/thumb/f1/f3e3cc6ac473af1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Разбить яйца в емкость для теста. Насыпать сахар, перемешивать 10 минут. Добавить соду. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Порезать сухофрукты на кусочки, положить в тесто.','https:https://st.vkuso.ru/data/cache/thumb/cb/94f23e149e7fdcb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Добавить измельченные орехи. Все перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/b6/19408ff756098b6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Медленно насыпать муку. Должно получиться тесто чуть-чуть гуще, чем на оладьи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Намазать форму растительным маслом, налить тесто, отправить в духовку на 30 минут, соблюдать температуру 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Чтобы пирог лучше пропекся, во время готовки сверху его необходимо накрыть пергаментной бумагой или фольгой, и увеличить температуру до 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8169,'Готовый бисквитный пирог с черносливом, орехами и курагой достать из формы, остудить и посыпать сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/9a/84414b09214a79a_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Промыть баранью ногу, удалить лишний жир, сделав 16 разрезов, нашпиговать чесноком (каждый зубчик разрезать вдоль на 4 части), равномерно втереть смесь перца и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Приготовить из 3 ст.л. масла и вина маринад, заправить его измельченной цедрой лимона и частью тимьяна, залить мясо и на 4 часа убрать в холодное место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Переложить мясо в большую посуду с оставшейся частью тимьяна и поставить в духовку (предварительно разогреть ее до 220 градусов), запекать 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Нарезать крупно лук, посыпать им мясо, уменьшить нагрев на 30 градусов и запекать еще час, гриль не включать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Процедить маринад, добавить бульон, кипятить пока объем не уменьшится на 2\3 от первоначального.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Нарезать крупно помидоры, измельчить зелень петрушки, открыть фасоль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'Перелить в сковороду 2 ст.л. растительного масла, положить помидоры, веточки розмарина, потушить, добавить фасоль и лук из мяса, прогреть, перемешать, всыпать петрушку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8170,'На плоское блюдо выкладывается фасоль, а на нее баранья нога, запеченная в духовке с фасолью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8171,'Помидоры, свежие огурцы, сладкий перец и отваренную курицу нарезать кусочками средней величины. Покрошить перо зеленого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8171,'Все ингредиенты перемешать, добавить раздавленный чеснок, консервированную кукурузу. Салат заправить подсолнечным или оливковым маслом, соль и молотый перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8171,'Сверху выложить «белые» домашние сухарики. Перемешать перед подачей, чтобы они не успели разбухнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8172,'С помощью блендера или мясорубки превратить в фарш куриное филе вместе  с очищенным чесноком. Вбить сырое куриное яйцо, массу посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8172,'Отдельно отварить морковь, корнеплод натереть на крупной терке, вмешать в куриный фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8172,'Антипригарную форму смазать небольшим количеством растительного масла. Руки тоже смазать маслом и сформовать шарики размером с грецкий орех или чуть больше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8172,'Выложить их в форму, печь в духовом шкафу в течение 15 – 20 минут, в процессе приготовления один-два раза перевернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8173,'Перемешать обезжиренный творог, сырые белки, пшеничную муку и измельченные яблоки без кожицы и семян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8173,'Добавить по вкусу сахарную пудру и молотую корицу. Застелить противень бумагой для выпекания, выложить сырники. Печь при температуре 180 градусов в течение 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Цедру апельсина натереть, из мякоти выдавить сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Желатин замочить в холодной воде на 10 минут, затем добавить в массу половину полученного апельсинового сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Сырые куриные желтки взбить в пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Отдельно довести до кипения молоко, всыпать цедру, сахарный песок, поварить смесь в течение двух минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Влить остатки апельсинового сока, ввести желтки тонкой струйкой. Варить массу на тихом огне в течение 12 минут, помешивать. Смесь немного остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8174,'Желатиновую массу поставить на минуту в микроволновую печь или прогреть на водяной бане, до кипения не доводить. Влить в молочно-апельсиновую смесь, перемешать и разлить в порционные формочки, дать застыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8175,'Овсяные хлопья залить водой, дать каше настояться, на это потребуется 15 – 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8175,'Очистить и натереть яблоко, смешать пюре с хлопьями и обезжиренным творогом, вручную, с помощью ложки, или блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8175,'Мокрыми руками сформовать небольшие шарики, придать им овальную форму, немного расплющить, выложить на противень, застеленный пекарской бумагой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8175,'Печь при температуре 180 градусов в течение получаса. Верх печенья должен немного подрумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8176,'Вымыть и обсушить большой кусок свинины бумажным полотенцем, нашпиговать чесночными зубчиками, равномерно втереть черный перец, включить на разогрев до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8176,'Высыпать на противень половину соли, сделать в центре углубление, положить мясо, присыпать его розмарином и засыпать сверху остатками соли, чтобы получилась горка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8176,'Свинина с чесноком, запеченная в соли, будет готова через два часа, перед подачей на стол разбить соляную корку и извлечь мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8177,'Спелое яблоко очистить от семенных камер и кожуры, нарезать крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8177,'Измельчить с помощью блендера овсяную крупу, добавить яблоки, сырые куриные белки, корицу, молоко, сахарозаменитель, соль на кончике ножа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8177,'Массу хорошо перемешать, должно получиться жидкое тесто. Разогреть сковороду с антипригарным покрытием, затем огонь уменьшить, выпечь блинчики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Почистить ананас от шкуры и сердцевинки, мякоть порезать на кубики. Необходимо, чтобы получилось 300 грамм чистого ингредиента.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Стебель сельдерея порезать на куски, если имеются жесткие волокна, то заранее их удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Разложить рыбу на стол вниз кожей, срезать филе, используя острый нож. Опустить кожу в кастрюлю, налить холодную воду, довести до кипения. Убрать пенку, убавить пламя, посыпать специями и солью, готовить 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Порезать филе на кубики, немного крупней, чем ананас.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Налить в большую сковороду ложку растительного масла. Положить филе рыбы, готовить 3-5 минут, осторожно перемешав, убрать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Положить в сковороду ананас, сельдерей, добавить соевый соус, чеснок, сок ананаса, рыбный бульон, который получился от варки. Готовить 5-6 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Развести крахмал с 2 маленькими ложками воды, вылить в сковороду. Готовить, пока соус не станет густым и прозрачным.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8178,'Положить рыбу обратно в сковороду, размешать, прогреть. Подавать лосося с ананасами под соусом в горячем виде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8179,'Растереть в ступке пряности: черный перец, мускатный орех, орегано, кориандр и корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8210,'Какао-порошок залить водой, прогреть на водяной бане до растворения, добавить сахарозаменитель. Продолжать варить, смесь помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8179,'Мелко нашинковать зелень петрушки, перемешать с размягченным сливочным маслом, раздавленным или мелко нарезанным чесноком. Добавить несколько капель лимонного сока, массу хорошо перемешать, соль – по вкусу. Сформовать небольшие кнели и заморозить в камере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8179,'Пропустить через мясорубку филе говядины. Мелко нарезать репчатый лук, чеснок, любую зелень, натереть сыр. Все перечисленные ингредиенты можно измельчить с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8179,'Добавить смесь в мясной фарш вместе с манной крупой, солью и частью растертых пряностей. Все перемешать и оставить на час в холодильнике для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8179,'Руки смазать маслом, сформовать лепешки. В центр каждой положить по кусочку замороженного зеленого масла, края завернуть. Подготовленные зразы уложить в пароварку, посыпать остатками специй, готовить в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8180,'В кастрюлю положить все продукты, поставить на маленькое пламя. Готовить, помешивая, пока полностью не растворится шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8180,'Перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8180,'Разлить имбирный горячий шоколад с молоком по чашкам и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'Измельчить в муку овсяные отруби.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'Растворить дрожжи из пакетика в теплом молоке с добавлением сахарного песка. Оставить смесь на некоторое время, она должна начать пузыриться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'К дрожжам добавить отруби, кукурузный крахмал, сырое куриное яйцо, посолить. Массу хорошо перемешать и дать постоять в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'Готовое тесто выложить на лист бумаги для выпекания, смазать тонким слоем томатного пюре, посыпать измельченным орегано.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'Распределить начинку: соцветия брокколи, кусочки желтого и красного болгарского перца, колечки красного лука, консервированные томаты и грибы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8181,'Натереть сыр, посыпать пиццу. Печь при температуре 180 градусов в течение 20 минут. Подать пирог можно с чесночным соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8182,'Разогреть чугунную сковороду с маслом, обжарить, переворачивая, кусок говядины примерно 10 минут, включить на разогрев духовку до 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8182,'Положить в толстостенную форму для запекания порезанный лук, чеснок и лавровый лист, сверху уложить мясо, посолить, поперчить, закрыть крышкой или фольгой, поставить в духовку, мясо будет готово через два часа, но уже после 30 минут запекания снизить температуру до 150 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8182,'Перед подачей говядину выложить на блюдо, закрыть фольгой и дать постоять 15 минут, потом нарезать ломтиками, полить выделившимся соком, а сверху выложить лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8182,'Говядина, запеченная в духовке по этому рецепту, получается сочной и просто тает во рту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8183,'Измельчить заранее почищенные креветки, поделить на соцветия брокколи. Порезать сыр на маленькие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8183,'В формочки налить по ложке оливкового масла, выложить подготовленные ингредиенты: в первую формочку брокколи, во вторую – креветки. Сверху в каждой форме распределить сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8183,'Вымыть яйца. Разбить по несколько яиц в каждую форму на сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8183,'Посыпать специями и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8183,'Отправить в духовку на 15-20 минут, соблюдать температуру 180 градусов. Украсить яйца кокот с креветками и брокколи листиками свежего базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Для коржа перемешать овсяные и пшеничные отруби, яйца, мягкий обезжиренный творог и сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Смесь вылить в форму из силикона, печь в течение 20 минут при температуре 180 градусов. Остудить, корж из формы не вынимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Смешать сыр филадельфия с мягким творогом, сахарозаменителем, цедрой и соком половины лимона. Добавить  два куриных яйца, плюс дополнительный желток с 1 ст.л кукурузного крахмала. Массу вымешать на небольшой скорости с помощью миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Взбить отдельно оставшийся белок в плотную пену, осторожно вмешать в творожно-сырную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Вылить начинку на готовый корж, поставить в духовой шкаф на 40 минут, температура выпекания – 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8190,'Разогреть в сковороде сливочное масло, равномерно подрумянить мясо, переложить в двухлитровую форму для запекания, включить на разогрев духовку до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8184,'Оставшийся лимонный сок разбавить водой, добавить 1 ст.л. кукурузного крахмала и сахарозаменитель по вкусу. Прогреть смесь до загустения в микроволновой печи. Готовый чизкейк немного остудить и полить верх лимонным топпингом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Подготовить продукты. Нагреть духовку до 190 градусов. Намазать маслом форму 22 сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Взбивать несоленое сливочное масло и сахар, пока масса не станет воздушной. Добавить ваниль и желток. Взбить.','https:https://st.vkuso.ru/data/cache/thumb/a6/df88c77fa3cf5a6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Отдельно просеять муку, соль, какао-порошок. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b9/0b6f923f0862db9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Соединить мучную смесь и масляную, перемешать. Должно получиться пастообразное тесто.','https:https://st.vkuso.ru/data/cache/thumb/c7/416c8c478e4a8c7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Переложить его в форму. Распределить равномерно, чтобы получилась толщина 1,5 сантиметра. Если тесто липнет к рукам, то смочить руки холодной водой. Отправить на 20-25 минут в духовку.','https:https://st.vkuso.ru/data/cache/thumb/c4/0c17ff8b41849c4_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Приготовить шоколадную заливку. Растопить масло и шоколад.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Почистить орехи. Потолочь в ступе или измельчить молотком.','https:https://st.vkuso.ru/data/cache/thumb/9f/64926b4a5f82f9f_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Достать из духовки готовый шортбред. Сразу распределить по поверхности шоколад.','https:https://st.vkuso.ru/data/cache/thumb/55/443227a4717bc55_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Посыпать орешками, придавить чуть-чуть ладонью.','https:https://st.vkuso.ru/data/cache/thumb/c7/ed1a1e831964dc7_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8185,'Можно подавать шоколадный шортбред с орешками.','https:https://st.vkuso.ru/data/cache/thumb/fc/c9b857625b071fc_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8186,'Разрезать подготовленные и обсушенные ребрышки: по 2 на порцию, положить их в кипящую воду и проварить 30 минут, включить на разогрев до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8186,'Приготовить сладкий ароматный маринад для ребрышек, для этого смешать пюре из яблок с сахаром, лимонным соком, кетчупом, черным молотым перцем, паприкой, корицей, солью, чесночным порошком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8186,'Переложить ребрышки на противень, смазать маринадом, дать постоять 30 минут, запекать около часа, в процессе запекания периодически смазывать ребрышки свиные в сладком соусе по-канадски маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Порезать ½ стебля лука-порея, сладкий перец.','https:https://st.vkuso.ru/data/cache/thumb/c2/55f17daf1b870c2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Вымыть грибы, отделить ножки, шляпки тоненько порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Порезать на маленькие кусочки куриное филе, посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/8f/27b9005a517fe8f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Нагреть на сковороде чуть-чуть сливочного масла, положить мясо, перец, лук, грибы. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/95/0d4f5362cc35d95_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Когда овощи будут мягкими, положить перец горошком, залить сливками.','https:https://st.vkuso.ru/data/cache/thumb/9e/1d29884b211a29e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Чтобы соус стал гуще, можно добавить чуть-чуть крахмала. Постоянно помешивать, пока не получится нужная консистенция. По необходимости можно долить воды.','https:https://st.vkuso.ru/data/cache/thumb/0e/be7d744de09950e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8187,'Отварить рис, положить на тарелку, сверху выложить мясо и овощи. Можно подавать филе из курицы с овощами и рисом.','https:https://st.vkuso.ru/data/cache/thumb/c2/d1c69ea01fce7c2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8188,'Творожную массу взбить с сырым яйцом. Добавить жидкий натуральный мёд, маковое семя, нарезанное яблоко. Если кожура не очень грубая, то её можно не удалять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8188,'Готовить массу в пароварке в течение 25 минут или запечь в духовке при температуре 200 градусов в течение 15 – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8188,'Готовое блюдо остудить до теплого состояния и подать, полив жидким свежим мёдом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Измельчить и обжарить на сливочном масле грибы и лук, посыпать перцем и солью. Насыпать ложку муки, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Переложить грибную массу в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Соединить молоко и яйцо, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Вылить заливку на грибы с луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Крупно потереть сыр, посыпать жульен сверху.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8189,'Готовить жульен с шампиньонами до золотистой корочки, соблюдать температуру 180 градусов. Подавать в горячем виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8190,'Нарезать подготовленную постную говядину кубиками, запанировать мясо в муке смешанной с черным молотым перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Посыпать тертым сыр, размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8190,'В освободившуюся сковороду положить нарезанный чеснок, измельченную морковь и лук, тушить 5-10 минут (пусть лук станет мягким), добавить вино, измельченную петрушку, тимьян, маринад, слитый с грибов, лавровый лист, прогреть и залить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8190,'Говядина тушеная в вине по-бургундски в духовке запекается 2,5 часа, перед запеканием мясо накрыть крышкой или фольгой, снять крышку, добавить консервированные грибы, запекать еще 30 минут, подавать блюдо в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'Вымыть спелое авокадо, разрезать на 2 части, достать косточку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'При помощи ложки достать мякоть, положить на тарелку. Размять мякоть до состояния пюре, налить ложку сока лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'Отварить курицу в соленой воде. Когда мясо остынет, порезать на маленькие кусочки, посыпать перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'Подсушить в тостере хлеб.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'Намазать на хлеб пюре из авокадо, положить кусочки мяса, листья салата, кусочек помидора, сверху накрыть кусочком хлеба.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8191,'Разрезать сэндвич с курицей, помидорами и авокадо по диагонали.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8192,'Баклажан очистить от кожуры, мякоть нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8192,'Выложить овощ на противень в один слой, прогреть в духовом шкафу в течение 15 минут, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8192,'Измельчить очищенные грецкие орехи, пропустить через пресс чеснок, порубить зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8192,'Все ингредиенты перемешать, заправить натуральным несладким йогуртом, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8192,'Салат выложить на блюдо горкой, украсить листочками свежей зелени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8193,'Плоды груши разрезать пополам, мякоть выбрать. Получившиеся лодочки сбрызнуть лимонным соком, чтобы не почернели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8193,'Вынутую мякоть порубить, смешать с жидким цветочным мёдом и нежирным творогом. Начинить массой груши и поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8194,'Куриное яйцо взбить в небольшой емкости, добавить овсянку или отруби, клетчатку, подлить молоко, всыпать какао-порошок, разрыхлитель и заменитель сахара. По желанию можно добавить ваниль и молотую корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8194,'Массу хорошо перемешать и оставить на 10 минут для набухания овсянки. Еще раз перемешать все ингредиенты, поставить чашку на три – пять минут в микроволновую печь. Выпечку вынуть, немного остудить и разрезать на четыре коржа. Каждый щедро пропитать соком апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8194,'Сложить торт: первый корж смазать натуральным йогуртом с добавлением сахарозаменителя, выложить ягоды вишни или черники, клубники или голубики. Лучше использовать свежую клубнику, остальные ягоды могут быть размороженными. Сверху – второй корж, операцию повторять, пока не закончатся коржи. Обмазать верх и бока десерта йогуртом и поставить в холод на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Растопить сливочное масло. Измельчить печенье в крошку при помощи блендера. Перемешать печенье и масло.','https:https://st.vkuso.ru/data/cache/thumb/e1/685435e8747b7e1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Постелить в форму специальную бумагу, положить смесь из печенья, равномерно распределить, чуть-чуть утрамбовать, используя деревянную ложку. Отправить на 15-20 минут в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/06/a47ce3c30e78206_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Хорошо взбить творог в блендере, положить к творогу сливочный сыр, взбить.','https:https://st.vkuso.ru/data/cache/thumb/c6/a41fb0ded6e83c6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Взбить сливки, сахар и ваниль до стойких пиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Взбить яйца, соль и сахар.','https:https://st.vkuso.ru/data/cache/thumb/4e/ab624c78499074e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Перемешать две смеси.','https:https://st.vkuso.ru/data/cache/thumb/a7/d13fbac1789a9a7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Выложить на печенье слоем. Нагреть духовку, поместить форму в посуду с водой, чтобы она на 1/3 не доходила до краев формы. Готовить чизкейк 75 минут.','https:https://st.vkuso.ru/data/cache/thumb/80/9e8c93c0b512780_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Затем отправить его минимум на 4 часа в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8195,'Перед подачей разрезать чизкейк острым ножом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8196,'Натереть промытые и обсушенные куски мяса солью и черным молотым перцем, духовку включить на разогрев до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8196,'Добавить в сухари петрушку, орегано, тимьян, базилик и оливковое масло, все перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Подавать супермакароны с фаршем и кукурузой горячими, посыпав зеленым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8196,'Обвалять куски мяса в сухарной панировке и переложить на противень для запекания, свиная вырезка, запеченная в панировочных сухарях, будет готова через 35-50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8196,'Готовность мяса можно проверить по цвету среза: оно не должно быть розовым, перед подачей и нарезкой дать свинине остыть минут 10.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Мелко натереть сыр. Соединить муку и крахмал.','https:https://st.vkuso.ru/data/cache/thumb/3f/f075dad8a86573f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Налить в кастрюлю воду, положить сливочное масло, порезанное на кубики, насыпать соль. Когда закипит добавить муку с крахмалом, перемешать, чтобы тесто отставало от стенок. Убрать с плиты, чуть-чуть охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Вбить по одному яйцу, после каждого перемешивать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Вымесить тесто, насыпать сыр, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/49/0df82eae4fdb649_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Нагреть духовку до 220 градусов. Используя маленькую ложку или кондитерский мешок, выложить на противень, посыпанный мукой, булочки на расстоянии друг от друга.','https:https://st.vkuso.ru/data/cache/thumb/f3/b52599090c105f3_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Готовить 20 минут. Духовку с готовыми булочками некоторое время не открывать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Когда булочки остынут, разрезать их не до конца горизонтально, заполнить любой начинкой или салатом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Одни булочки наполнить смесью тертого сыра с майонезом и прессованным чесноком. Другие смесью икры мойвы, творожного сыра и консервированной семги.','https:https://st.vkuso.ru/data/cache/thumb/58/908343e41e0ba58_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8197,'Можно подавать заварные французские «Гужеры» с начинкой.','https:https://st.vkuso.ru/data/cache/thumb/3e/c070290ed96343e_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'На маленьком огне довести до кипения молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Насыпать соль, сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Тонкой струей добавить в молоко манную крупу, непрерывно помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Не переставая мешать, готовить 4 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Положить сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Добавить коньяк, готовить еще минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8198,'Можно подавать кашу манную с коньяком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8199,'Натереть обмытый, высушенный и обмазанный маслом кусок говяжьей вырезки смесью розмарина, майорана, черного молотого перца, измельченного прессом чеснока и соли, духовку включить на разогрев до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8199,'Переложить мясо в огнеупорную форму, смазанную маслом, говяжья вырезка, запеченная с майораном и розмарином, будет готова через 40-50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8200,'Измельчить с помощью блендера изюм без косточек, чернослив, очищенные грецкие орехи. Добавить сырые куриные белки, льняное семя, овсяные хлопья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8200,'Застелить противень бумагой для выпекания, распределить полученную смесь тонким слоем в полсантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8200,'Печь при температуре 100 градусов в течение часа или полутора. За это время масса должна высохнуть. Горячий корж нарезать квадратами или другими фигурками и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8201,'Капусту опустить в кипящую воду на пять минут и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8201,'Размять брынзу вилкой, соединить со сливками, соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8201,'Все ингредиенты перемешать и украсить листочками зеленой петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8202,'В течение 10 – 15 минут отварить в кипящей воде брокколи, брюссельскую и цветную капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8202,'Отдельно, с помощью миксера, взбить сырые куриные яйца с молоком. Добавить эстрагон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8202,'Натереть половину нормы сыра, остальной нарезать кубиками или небольшими брусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8202,'Отваренные овощи выложить в форму, смазанную маслом, добавить кубики сыра. Массу залить яичной смесью, печь в духовом шкафу в течение 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8202,'Вынуть форму из духовки, посыпать тертым сыром и допечь блюдо еще 20 минут, должна образоваться золотистая корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Обжарить на растительном масле фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Положить лук, чеснок. Перемешать, обжаривать минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Налить 250 миллилитров воды, 250 миллилитров соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Положить кукурузу, посыпать приправами, посолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Положить оставшейся томатный соус, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Готовить 5-7 минут под крышкой на среднем огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8203,'Налить 450 миллилитров воды, размешать, готовить под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Измельчить щавель. Добавить в суп, готовить, пока он не станет цвета хаки. Если нужно, посолить и поперчить. Готовить 7 минут, положить зелень.','https:https://st.vkuso.ru/data/cache/thumb/57/1b3980daf6bb657_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Убрать с огня. Отварить яйца, рассчитывая половину яйца на человека. Порезать на кубики.','https:https://st.vkuso.ru/data/cache/thumb/bf/ace22c78d0fc5bf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8204,'Подавать украинский зеленый суп со щавелем и яйцом со сметаной и укропом.','https:https://st.vkuso.ru/data/cache/thumb/31/df9723732b8f431_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Положить в кастрюлю все жидкие компоненты для соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Положить прессованный чеснок и тертый имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Готовить 10-15 минут, но не доводить до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Натереть рыбу со всех сторон молотым перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Нагреть на сковороде ложку растительного масла, обжарить рыбу с двух сторон до корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8205,'Подавать жареного лосося под соево-медовым соусом с рисом на гарнир.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Обжарить бекон, но не до сильного хруста, выложить на бумажное полотенце и дать впитаться излишкам жира.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Нашинковать мелко лук и обжарить в этой же сковороде, переложить в тарелку и дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Разрезать филе курицы вдоль на две половины, прикрыть пленкой и аккуратно отбить, присолить, натереть молотым перцем, побрызгать соком лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Разложить вдоль каждого кусочка по несколько пластинок бекона, на них – лук и натертый сыр, свернуть рулетом, закрепить зубочистками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Разогреть оливковое масло, обжарить рулеты со всех сторон по 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Рулеты из куриного филе с начинкой из бекона и сыра переложить в форму и поставить в духовку на 20 минут, закрыть фольгой и продолжать запекать еще 3 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Налить в сковороду вино и выпарить до уменьшения объема в 2 раза, добавить сливочное масло и порубленный чеснок, перемешать, нагревать 2-3 минуты, засыпать муку, все размешать, залить сливки, бульон, дать закипеть и проварить, убавив огонь, 5 минут, готовый соус процедить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8206,'Вынуть из рулетов перед подачей зубочистки, нарезать на куски и полить соусом перед подачей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Слабосоленую семгу порезать на тоненькие куски. Положить кусочки семги на дно креманки.','https:https://st.vkuso.ru/data/cache/thumb/94/c1d9d49f4675e94_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Отварить картофель, порезать на маленькие кубики. Положить его на кусочки рыбы.','https:https://st.vkuso.ru/data/cache/thumb/de/bd8cc95512408de_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Мелко порезать лук. Обжарить на растительном масле. Остудить обжаренный лук, положить на картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Отварить яйцо, размять вилкой. Выложить измельченное яйцо на лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Порезать яблоко с кожурой на маленькие кубики. Положить его сверху яйца.','https:https://st.vkuso.ru/data/cache/thumb/0f/df4ec04d5349e0f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8207,'Залить ингредиенты сметаной, посыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/da/44e755cf939c2da_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8208,'Подготовить продукты. Натереть свеклу, добавить свежий огурец, порезанный на маленькие кусочки, и листья салата.','https:https://st.vkuso.ru/data/cache/thumb/a6/4dc67825f30b3a6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8208,'Положить редис, порезанный соломкой, измельченный укроп.','https:https://st.vkuso.ru/data/cache/thumb/ed/84e57a8631512ed_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8208,'Отварить яйцо, охладить, разрезать пополам. Положить яйцо ко всем овощам.','https:https://st.vkuso.ru/data/cache/thumb/2d/c3428c483895a2d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8208,'Добавить воду, уксус, насыпать сахар, соль. Размешать, дать холодному борщу с огурцом и редиской постоять 5-10 минут.','https:https://st.vkuso.ru/data/cache/thumb/fb/94c354b6622f5fb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8209,'Сварить в большой кастрюле до готовности индейку с бульонными кубиками и лавровым листом (примерно 2 часа), по вкусу можно подсолить, вынуть мясо и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8209,'Добавить к бульону вино, убрать крышку и упарить объем до 3 чашек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8209,'Отделить мясо от костей, освободить от кожи и нарезать, добавить рубленый чеснок, тимьян, нашинкованный лук, шалфей, петрушку, поперчить, переложить смесь в форму, залить бульоном и поставить застывать на холод минимум на 6 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8209,'Чтобы достать из формы зельц из голени индейки необходимо поместить дно формы на несколько секунд в горячую воду, накрыть блюдом и аккуратно перевернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Добавить ванильный экстракт, размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8210,'Белки взбить в плотную массу и осторожно вмесить в немного остывший шоколад, движениями снизу вверх, вылить в форму, поставить в духовку на восемь минут. Температура приготовления – 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8210,'Десерт остудить и поставить на ночь в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8211,'Вымыть крупные помидоры, срезать верхнюю часть, чайной ложкой аккуратно вынуть середину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8211,'Отдельно взбить куриное яйцо и дополнительный белок с тертым сыром, солью, молотым перцем, добавить рубленую зелень укропа и петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8211,'Готовую смесь влить в томатные чашечки, прикрыть срезанными крышками-верхушками, запечь блюдо на максимальной мощности в СВЧ-печи в течение трех минут, до готовности. Яичная масса должна свернуться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8212,'Снять кожу с грудки, мясо нарезать на кусочки, жарить без масла до образования золотистой корочки. Использовать сковороду с антипригарным покрытием или керамическую, можно подлить немного воды. Не допускать пригорания продукта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8212,'Взбить яйца, посолить и поперчить по вкусу. Посыпать сухим укропом и перемешать с курицей, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8213,'Нашинковать белокочанную капусту. Репчатый лук нарезать крупными кубиками, морковь – кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8213,'На сковороде с антипригарным покрытием прогреть оба ингредиента. Масло не требуется, можно подлить немного воды или томатного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8213,'Всыпать рубленый зеленый лук. Добавить капусту, тушить на максимальном огне до легкого золотисто-коричневого оттенка. Массу помешивать, чтобы продукты не пригорели. В процессе приготовления можно подлить еще немного томатного сока, всыпать любимые специи. Огонь уменьшить до минимума.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8213,'Добавить бурый рис, подлить воду или все тот же томатный сок. Тушить блюдо под крышкой до полной готовности риса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8214,'Сельдерей натереть на терке с мелкими отверстиями, высыпать в блендер, влить сок, воду, добавить кориандр и сахар, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8214,'Процедить пунш ананасовый с сельдереем сквозь сито и охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8215,'В емкость вылить концентрированное молоко без сахара и сгущенное молоко с сахаром. Добавить сок одного лимона. Массу перемешать, немного взбить. Должен получиться жидкий крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8215,'Форму для торта застелить пищевой пленкой, выложить песочное печенье, залить кремом, снова печенье, крем – слои повторять, пока форма не наполнится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8215,'Поставить торт на ночь в холодильник для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8216,'Горький шоколад натереть или поломать небольшими кусочками. Кокосовую стружку обжарить в духовке вместе с лепестками миндаля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8216,'Для основы перемешать размягченное сливочное масло, сахарный песок, большой желток и экстракт ванилина. Всыпать пшеничную муку, какао-порошок и разрыхлитель для теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8216,'Застелить противень бумагой для выпекания, выложить получившееся тесто, сформовать диск с небольшим бортиком. Поставить в духовой шкаф на девять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8216,'Вынуть выпечку из духовки, посыпать шоколадной крошкой, вернуть в духовку на минуту: шоколад должен растопиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8216,'Изделие вынуть, шоколад размазать, посыпать кокосовой стружкой и миндалем. Выложить свежую малину. Пиццу сбрызнуть растопленным белым шоколадом и подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Разморозить половину упаковки слоеного теста, купленного в магазине. Раскатать и выложить в форму для выпекания с высокими бортиками. В нескольких местах наколоть вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Духовой шкаф разогреть до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Для приготовления начинки нарезать зеленый и репчатый лук, натереть сыр на терке с крупной решеткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Репчатый лук обжарить на сливочном масле, добавить нарезанные грибы, перемешать, добавить морскую соль и поперчить, обжарить еще немного. Остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Отдельно взболтать сырые куриные яйца со сливками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Добавить в грибную массу зеленый лук, яичную массу, поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8217,'Начинку выложить в форму для запекания, поставить пирог в духовой шкаф на 30 – 40 минут. На поверхности должна образоваться золотистая корочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Порезать свеклу на кубики среднего размера, отправить в салатник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8218,'Сахарный песок растворить в воде, всыпать сухие дрожжи. Отдельно растопить сливочное масло, добавить в общую смесь. Пшеничную муку просеять с солью, добавить в дрожжевой раствор, замесить тесто. Если тесто прилипает к рукам, то можно подсыпать еще немного муки. Обернуть тесто в пищевую пленку, поставить в тепло на час. Масса должна подойти, заметно увеличиться в размерах.','https:https://st.vkuso.ru/data/cache/thumb/44/3e9615a14eb5a44_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8218,'Раскатать её в лепешку толщиной в несколько миллиметров, на половину поверхности нанести мягкое сливочное масло комнатной температуры. Оставить на несколько минут. Пласт свернуть вдвое, закрыв намазанную часть теста не намазанной, положить в морозильную камеру на 20 минут, еще на час – в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8218,'Пласт снова раскатать, еще раз намазать маслом, повторить все процедуры по порядку. Круассан будет пышнее, если слоев немного. Готовое слоеное тесто раскатать в лепешку прямоугольной формы и нарезать треугольниками. Желательно раскатывать в одну сторону, чтобы не нарушить слои.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8218,'Для начинки порубить очищенный от шкурки миндаль с ванилином и сахарным песком. Распределить смесь по поверхности теста, свернуть в трубочку, начинать от широкого края до угла. Придать изделию форму полумесяца. Повторить то же самое с остальным тестом. Заготовки должны подойти при комнатной температуре, затем их нужно смазать желтком и поставить в духовой шкаф.','https:https://st.vkuso.ru/data/cache/thumb/c8/3fc76d7257a72c8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8218,'Время выпекания – пять минут, температура – 220 градусов. Далее температуру понизить до 185 градусов, печь изделия еще от 15 до 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Приготовить рассол для маринования, для этого смешать сахар с солью и всыпать в кипяченую воду, добавить молотый черный перец, залить полученным маринадом мясо и убрать в холодное место на сутки, через 24 часа мясо вынуть, промыть в прохладной воде и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Нашинковать мелко половину лука, засыпать в блендер, добавить чеснок, 2 ч.л. оливкового масла и столько же кардамона, измельчить все в пюре, включить на разогрев духовку до 350 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Зарумянить оставшийся лук в оливковом масле, переложить сверху кусочки свинины, присыпать перцем, посолить, смазать полученным пюре и обжарить мясо на сильном огне с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Переложить свинину на противень и запекать в духовке около часа, затем закрыть фольгой и продолжить запекать еще 15-20 минут, уменьшив нагрев до 150 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Обжарить на сковороде грибы с луком на оливковом масле, переложить все в кастрюлю и залить сливками с бульоном, приправить кардамоном и дать закипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Смешать отдельно растопленное сливочное масло с мукой и вылить смесь в кастрюлю, проварить до сгущения соуса примерно 5-7 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8219,'Свинина в сливочном соусе с грибами и кардамоном подается нарезанной на куски.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Развести пачку дрожжей, добавить немного молока и сахарного песка. Высыпать пшеничную муку на плоское блюдо большого диаметра, сделать углубление в середине, вбить сырое яйцо, влить дрожжевую смесь, положить сливочное масло, нарезанное на кусочки, добавить остатки молока. Месить массу до тех пор, пока она не перестанет липнуть к рукам. Поставить в тепло на три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Для приготовления начинки обязательно понадобится свежий молочный сыр сулугуни, его нужно натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'От теста отрезать большой кусок, раскатать в лепешку круглой формы, тонкую, в полсантиметра. В центр положить сырную начинку.','https:https://st.vkuso.ru/data/cache/thumb/ab/3e58bd11f2ea9ab_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Края теста собрать к центру и хорошо защипать.','https:https://st.vkuso.ru/data/cache/thumb/a2/3b6d7512c7edfa2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Перевернуть изделие швом вниз и раскатать скалкой. В середине сделать отверстие небольшого диаметра, для выхода воздуха.','https:https://st.vkuso.ru/data/cache/thumb/22/2158a8f82ca2622_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Приготовить смазку из сметаны и желтка, покрыть хачапури, посыпать дополнительной порцией тертого сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8220,'Присыпать противень мукой, выложить пироги, поставить в духовку для запекания: температура приготовления – 210 градусов, время – от шести до семи минут.','https:https://st.vkuso.ru/data/cache/thumb/68/fe73779f530ac68_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8484,'На каждую лепешку посыпать сахар с корицей, прижать, свернуть, еще раз посыпать, прижать и свернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8221,'Фасоль любого вида замочить с вечера на всю ночь.  Рис отварить до полуготовности, картофелину – до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8221,'С помощью блендера измельчить сырую фасоль в однородную массу, добавить раскрошенную картошку, пищевую соду, соль, пшеничную муку, смесь молотых перцев, перец чили, паприку, асафетиду, тертый имбирь, карри, специи гарам масала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8221,'Все ингредиенты хорошо перемешать, добавить рис в конце. Сформовать шарики размером с грецкий орех или чуть больше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8221,'Для приготовления соуса использовать томатную пасту или свежие помидоры. Если используется второй вариант, то 2 помидора нужно измельчить блендером, перемешать с солью, подлить растительное масло и воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8221,'Ёжики выложить в форму, залить томатным соусом доверху, добавить несколько лавровых листочков, кардамон и гвоздику. Поставить кушанье на несильный огонь на полчаса, тушить под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8222,'Аккуратно отделить белки от желтков. Для приготовления блюда лучше использовать домашние яйца большого размера. Добавить в желтки сахарный песок, массу взбить до посветления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8222,'Налить молоко в сотейник, добавить половину стручка ванили и все семена. Довести смесь до кипения. Молоко процедить, чтобы удалить семена и стручок. Горячим, тонкой струйкой, влить молоко в желтковую смесь. Крем активно перемешивать венчиком, чтобы желток не свернулся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8222,'Смесь перелить в сотейник или в жаропрочную миску и поставить на тихий огонь на водяную баню. Уварить крем в течение пяти или шести минут, массу перемешивать деревянной ложкой, она должна быть умеренно густой. По желанию в крем можно добавить ликер «Амаретто» или бренди.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8223,'Куриные окорочка вымыть, нарезать и натереть специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8223,'Налить на сковороду растительное масло, выложить мясо и поставить на огонь. Натереть на крупной терке очищенную морковь, добавить к окорочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8223,'Мелко нарезать репчатый лук, также всыпать на сковороду. Все ингредиенты тушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8223,'Переложить окорочка в порционные горшочки, добавить по две ложки риса, влить воду так, чтобы её уровень был на полтора-два сантиметра выше крупы. Соль – по вкусу. По желанию можно добавить неочищенный чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8223,'Горшочки закрыть крышками и поставить в духовой шкаф на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8224,'Разрезать ягоды вишни на две половинки, можно взять мороженые ягоды, взбить в пену яйца (добавлять по одному) с маслом, добавить коньяк, бренди или ром, цедру и сок апельсина, цедру лимона, все хорошо перемешать, перелить смесь в посуду с измельченными сухофруктами (курага, инжир, вишня, чернослив, сушеные ягоды, изюм и т.д.), орехами  (фундук, грецкие орехи, орехи пекан или миндаля), фруктами в сахаре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8224,'Смешать просеянную муку с разрыхлителем и солью, постепенно всыпать в ореховую массу и замесить тесто, включить на разогрев духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8224,'Застелить смазанным маслом пергаментом съемное дно формы с высотой бортиков 20 см, выложить и разровнять тесто, рождественский пирог с орехами и сухофруктами по-английски выпекать 1 час при 160 градусах, а потом еще 1,5 часа при 150 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8224,'Проверять периодически готовность деревянной зубочисткой, после готовности теста на ней практически не должно оставаться влажных следов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8224,'Полностью остудит пирог, смазать коньяком, ромом или бренди, используя кисточку, обернут фольгой, перед подачей украсить взбитыми белками с сахаром, присыпать натертой цедрой лимона и апельсина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Из всех продуктов замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/b6/eb4eac5fb172fb6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Сформировать шар, положить на поверхность, посыпанную мукой. Налить кипяток в большую керамическую емкость. Когда посуда нагреется, вылить воду, сразу накрыть ею тесто, дождаться, пока остынет, повторить процедуру минимум 3 раза.','https:https://st.vkuso.ru/data/cache/thumb/7e/19dd8f09a84097e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Эта технология делает тесто очень эластичным, из него можно скатать пласт 2-3 миллиметра.','https:https://st.vkuso.ru/data/cache/thumb/a1/85789af746691a1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Порезать перец и грибы. Подсолить. Обжаривать на сливочном масле 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/c6/35f0ddba0180ec6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Порезать на кубики яйца и сыр. Положить в салатник к свекле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Положить на тесто сыр, порезанный на пластинки. На нем равномерно распределить фарш.','https:https://st.vkuso.ru/data/cache/thumb/43/784982f9dce1c43_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Сверху перец и грибы.','https:https://st.vkuso.ru/data/cache/thumb/ad/d551949a731d5ad_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Свернуть рулет с короткой стороны.','https:https://st.vkuso.ru/data/cache/thumb/40/c2a8d16be417840_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Аккуратно переложить рулет на противень, намазанный маслом, готовить в духовке 40-45 минут на среднем огне, чтобы середина пропеклась, при это не подгорел низ.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8225,'Спустя полчаса после начала готовки, намазать штрудель желточно-молочной смесью, снова отправить в духовку. Когда образуется румяная корочка, штрудель с мясом, грибами и болгарским перцем готов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Помидоры небольшого размера нарезать кружками по полсантиметра толщиной. Часть томатов измельчить с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Нарезать репчатый лук полукольцами, измельчить два зубчика чеснока. То и другое обжарить на заранее разогретом растительном масле. Переложить в обжарку измельченные помидоры, соль и молотый перец – по вкусу. Смесь потушить в течение двух минут, добавить петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Содержимое сковороды переложить в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Длинные крупные баклажаны нарезать толщиной в полсантиметра. Выложить овощи в миску в один слой, посыпать поваренной солью. Точно также поступить со всеми слоями. Подождать полчаса, для отделения сока.','https:https://st.vkuso.ru/data/cache/thumb/52/d186204cfea2252_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Пропустить через мясорубку говядину, лучше, если в ней будет немного жира. Если мясо постное, то в него можно положить немного свиного сала и прокрутить все вместе через мясорубку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Очистить и измельчить репчатый лук и два-три зубчика чеснока с помощью блендера. Добавить измельченные овощи в фарш вместе с кинзой, зирой, кориандром, петрушкой. Массу посолить и поперчить, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Сформовать небольшие котлеты, обжарить на растительном масле, на сильном огне, по полторы-две минуты с каждой стороны.','https:https://st.vkuso.ru/data/cache/thumb/bb/5d5d9b74dc972bb_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Отцеженные баклажаны хорошо вымыть в холодной воде, отжать. Пластины обжарить до румяного цвета с обеих сторон, после каждой порции овощей подливать масло в сковороду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Готовые баклажанные пластинки выкладывать на бумажные салфетки для впитывания лишнего жира. Выложить две пластинки на поверхность стола или плоскую тарелку, в середину – котлету, края овоща завернуть, сверху – кружок помидора, все слои закрепить с помощью зубочистки.','https:https://st.vkuso.ru/data/cache/thumb/cd/2776b35dfeb8fcd_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8226,'Точно также поступить со всеми остальными котлетами. Выложить изделия в форму с томатной массой, поставить в нагретую духовку. Готовить в течение 15 минут, духовку выключить, дать блюду постоять еще пять минут, дверцу не открывать.','https:https://st.vkuso.ru/data/cache/thumb/d8/25507b9cd281ad8_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'Свежие куриные яйца хорошо вымыть в теплой воде. Разбить, отделить желтки от белков. Последние взбить со щепоткой соли или соком лимона в плотную пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'Желтки взбить с сахаром, добавить сыр Маскарпоне и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'Белковую массу соединить с желтковой, смешивать аккуратно, движениями снизу вверх.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'В холодный крепкий кофе добавить коньяк. Печенье «Савоярди» быстро окунуть в кофе и выложить в формочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'Сверху намазать крем, постучать по столу, чтобы он равномерно распределился. Выложить второй слой печенья, снова крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8227,'Поставить десерт в холодильник на три часа или больше. Перед подачей посыпать тирамису тертым шоколадом или какао-порошком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'У больших и спелых помидоров срезать верхушки, ложкой удалить сердцевину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'Для приготовления начинки куриную грудку нарезать кубиками небольшого размера. Чеснок очистить, измельчить вместе с листьями орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'Мясо положить в кастрюлю небольшого размера, добавить половину чайной ложки бальзамического уксуса и оливкового масла, орегано и соль. Кастрюлю поставить на средний огонь, долить немного воды и поварить, помешивая, до готовности курицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Переложить полученную смесь в стеклянную емкость, прикрыть пленкой и убрать в холодное место на 4 часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'Помидорные чашечки натереть солью и смазать оливковым маслом, выложить на застеленный пергаментом противень. Поставить в духовку на пять минут, температура – 150 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'При готовности мяса огонь выключить, добавить несколько листочков базилика, обезжиренную сметану и свежие огурцы, нарезанные соломкой. Овощ можно нарезать с помощью терки, предназначенной для измельчения моркови по-корейски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8228,'Полученную начинку хорошо перемешать, добавить соль и перец по вкусу и выложить ложкой в помидоры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8229,'Твердый сыр натереть, готовое слоеное тесто немного раскатать и нарезать полосками шириной три-четыре сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8229,'На каждую полоску намазать творожный сыр и посыпать твердый. Аккуратно завернуть, края защипать, чтобы получилась фаршированная колбаска.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8229,'Все колбаски выложить в круглую форму в виде улитки, смазать немного взбитым желтком, посыпать семенем кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8229,'Поставить пирог в разогретый духовой шкаф на 20 минут. Температура приготовления – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8230,'С помощью миксера взбить сахарный песок с мягким сливочным маслом до кремового состояния. Вбить по одному сырые яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8230,'Всыпать просеянную муку, какао-порошок и разрыхлитель, взбить массу миксером на низкой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8230,'Форму для пирога смазать сливочным маслом, застелить пергаментом. Тесто перелить, печь в течение 30 – 40 минут, готовность проверить зубочисткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8230,'Дать постоять 10 минут, затем выпечку вынуть и выложить на блюдо. На тихий огонь поставить жирные сливки и наломанный горький шоколад. Прогреть, помешивая, до полного растворения шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8230,'Глазурь остудить до комнатной температуры. Пирог сначала поставить в холодильник на полчаса, а потом залить глазурью и снова охладить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8231,'Втереть в рыбу смесь соли и перца, поджарить с двух сторон, переложить на тарелку и накрыть, чтобы семга оставалась теплой, взбить и отставить сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8231,'Влить в оставшееся масло после жарки рыбы вино, выпарить до 1/3 от первоначального объема, добавить взбитые сливки и проварить несколько минут, приправить солью, перцем, горчицей, уварить соус до густоты сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8231,'Разложить семгу под соусом из сливок и горчицы по тарелкам, украсить колечками лука порея и веточками укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Перемешать пшеничную муку, какао-порошок, пищевую соду и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Растопить сливочное масло, добавить в теплое молоко вместе с уксусом и ванильным экстрактом. Всыпать сухую смесь ингредиентов и замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Дно двух разъемных форм застелить пергаментом, бока смазать маслом. Тесто выложить поровну, разровнять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Печь в заранее разогретой духовке в течение 15 – 20 минут при температуре 180 градусов. Проверить готовность с помощью спички или зубочистки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Размягченное масло с сахаром взбить, добавить сметану, сахарную пудру и ванильный экстракт, взбить до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Готовые коржи остудить в формах в течение 10 минут, выложить на пергамент. На остывшую основу выложить половину крема с помощью кондитерского мешка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8232,'Сверху положить половину нормы консервированной вишни в густом сиропе. Накрыть вторым коржом, процедуру повторить. Дать постоять торту в холодильнике один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8233,'Смазать маслом форму для запекания, выложить в неё филе любой белой рыбы в один или два слоя. Дно должно быть полностью закрыто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8233,'Разложить вокруг соцветия цветной капусты и брокколи. Посыпать блюдо морской солью, поперчить, полить жирными сливками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8233,'Добавить размороженный зеленый горошек, поставить в духовку, разогретую до 200 градусов, на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Растворить в шампанском соль, добавить белый перец, влить 2 стакана молока, хорошо перемешать и дать закипеть на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Смешать горячую смесь с яичными желтками и взбить венчиком, порубить по отдельности яйца, красный лук, петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Размешать крахмал в оставшемся молоке, перелить в сковороду, взбивая проварить до сгущения примерно 5-7 минут, остудить, смешать с кремом из желтков и шампанского.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Положить на дно широкой рюмки друг за другом столовую ложку измельченных яиц, по чайной ложке лука и петрушки, 2 ч.л. красной икры, 2 ст.л. крема из шампанского, сверху 1 ст.л. черной икры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8234,'Закуска из икры и яиц раскладывается в таком же порядке по остальным рюмкам, накрывается пленкой и ставится в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'С помощью кухонного комбайна смешать песочное печенье с мягким сливочным маслом. Масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'Выложить тесто в разъемную круглую форму, распределить равномерно, утрамбовывая пальцами. Поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'Желатин залить кипятком и немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'В комбайне протереть творог до однородности, массу взбить миксером вместе с сахарным песком и сливками. Количество сахара можно увеличить или уменьшить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'Влить приготовленный желатин, лимонный сок, всыпать ванилин из пакетика, взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'Творожную массу разделить на семь частей, и подкрасить с помощью пищевых красителей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8235,'В форму выложить красный творог, поставить на полчаса в холодильник. Затем – оранжевый слой, снова отправить в холодильник на 30 минут. По очереди выложить все слои, каждому дать подмерзнуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8236,'Спелые авокадо разрезать пополам вдоль, косточку удалить, мякоть вынуть ложечкой. Сбрызнуть её лимонным соком, чтобы не изменила цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8236,'Мелко нарезать шампиньоны, белое отваренное куриное мясо, консервированные креветки, очищенный банан и мякоть авокадо. Часть креветок оставить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8236,'Нашинковать соломкой шпинат и зеленый салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8236,'Для заправки перемешать майонез с солью, сахаром и перцем, заправить смесью подготовленные ингредиенты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8236,'Наполнить полученной смесью авокадо, украсить оставшимися креветками и веточками укропа и петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8237,'Большой спелый банан очистить, измельчить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8237,'Добавить финики без косточек, обезжиренный сухой творог, еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8237,'Влить в массу натуральный йогурт без добавок, всыпать сухое молоко, растворимый кофе или кофейный экстракт, мёд, смесь взбить миксером и поместить в морозилку на три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8237,'Каждые полчаса контейнер вынимать, содержимое перемешивать ложкой. Оставить десерт в холодильнике на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8238,'Мак измельчить на кофемолке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8238,'Сырые белки взбить с половиной нормы сахара до получения устойчивой пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8238,'Мягкое сливочное масло взбить с остатками сахара, добавить желтки и ванилин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8238,'Перемешать с маком, порциями ввести взбитые белки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8238,'Выпекать в духовке от 25 до 30 минут, температура – 175 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8239,'Перемешать сахар с белком и ванилином из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8239,'Влить молоко, всыпать муку, замесить тесто, в нем не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8239,'Размазать небольшое количество массы по холодной поверхности сковороды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8239,'Жарить на небольшом огне с двух сторон, свернуть кульком или трубочкой в теплом виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8240,'Паштеты готовятся на основе сливочного сыра. Для первого в равных пропорциях смешать нарезанное отваренное или копченое мясо, сыр. Превратить в пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8240,'Для второго состава перемешать 50 г сыра с жареными грибами. Также измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8240,'Для третьей намазки очистить и натереть на терке свежий огурец, отжать сок. Зелень измельчить, пропустить чеснок через пресс, ингредиенты перемешать со 100 г сливочного сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8241,'Обжарить в сотейнике на оливковом масле лук в течение 4 минут, добавить цедру апельсина, кружки помидора, оливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8241,'Апельсины почистить, разобрать на дольки, удалить все жилки и пленки, переложить к луковой смеси, тушить 10 минут на слабом огне под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8241,'Подготовленную рыбу разрезать на порционные куски, положить в сотейник, приправить перцем, посолить, добавить в случае необходимости воды, присыпать щепоткой измельченного укропа и поставить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8251,'Выложить по сосиске и по кусочку сыра в лист и плотно завернуть рулетом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8241,'Рыбное филе с оливками и апельсинами будет готово через 15 минут, разложить блюдо по тарелкам и украсить веточками свежей зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8242,'Отваренное куриное филе нарезать мелкими кубиками, маринованные шампиньоны – пластинками, очищенный корень сельдерея натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8242,'Ингредиенты выложить в салатницу, заправить по вкусу майонезом. Блюдо украсить целыми маринованными шампиньонами и листочками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8243,'На хлеб выложить тертый сыр, лист зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8243,'Отваренное или обжаренное мясо нарезать соломкой и смешать с измельченным сладким болгарским перцем, добавить майонез, массу перемешать и выложить сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8243,'Еще раз посыпать сыром, накрыть вторым ломтиком хлеба. Обжарить бутерброд с двух сторон до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8244,'Творог размять с сахарным песком, сырым яйцом, всыпать ванильный сахар из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8244,'Добавить крахмал и муку, ориентироваться лучше на глаз, по консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8244,'Разогреть масло на сковороде, сформовать сырники, жарить на среднем огне с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8245,'Сливочное мало и сгущенное молоко должны быть комнатной температуры. Порубить ножом очищенные орехи. Ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8245,'Промазать начинкой печенье квадратной или прямоугольной формы, накрыть сверху другим печеньем. Поставить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8246,'Прямоугольный лаваш расстелить на столе, выложить на него нарезанную колбасу, посыпать тертым сыром, закрыть частью лаваша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8246,'На второй «этаж» положить измельченный сладкий болгарский перец, тертый сыр, закрыть частью лаваша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8246,'Следующий слой – тертый сыр с чесноком и зеленью. Лаваш выложить на сковороду, шов должен оказаться внизу, поджарить с двух сторон. При подаче разрезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8247,'Нарезать соломкой морковь, лук, белокочанную капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8247,'Капусту протереть с солью, чтобы она дала сок, выложить на горячую сковороду. Томатную пасту развести с водой, долить в капусту, потушить до полуготовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8247,'Лук и морковь обжарить, добавить в капустную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8247,'Отдельно растопить сливочное масло, прожарить муку, влить воду, посолить, перемешать, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8247,'Добавить полученную подливу в капусту, приправить перцем, лавровым листом, посолить, добавить сахар. Прогревать до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Убрать мякоть свинины на полчаса в морозильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Выложить в кипящую воду с сахаром и уксусом клюкву с яблоками, варить до размягчения, процедить, фруктам дать обсохнуть, отвар не выливать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Вылить отвар в сотейник и прокипятить до уменьшения объема в половину, измельчить яблоки и клюкву в комбайне до состояния пюре, включить на разогрев духовку до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Нарезать свинину на пластинки, отбить, втереть смесь перца, соли, имбиря и горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Положить на мясо яблочно-клюквенную начинку, завернуть в рулет, перевязать нитками, переложить рулет на фольгу, полить фруктовым отваром, аккуратно завернуть края фольги и отправить в духовку, жарить до готовности 40-50 минут',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8248,'Рулет из свинины с яблоками и клюквой за 7-8 минут до окончания жарки освободить от фольги, чтобы он подрумянился сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8249,'Тушки кальмаров очистить, отварить в течение минуты в подсоленном кипятке, дать постоять под крышкой три или четыре минуты. Нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8249,'Морковь и картофель отварить, нарезать кубиками среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8249,'Маринованные огурцы и крутые яйца нарезать мелкими кубиками. Все ингредиенты переложить в салатницу, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8250,'Брынзу  (или любой другой сыр) натереть или размять.  Добавить пищевую соду, муку, сырое яйцо, кефир. Замесить тесто, оно должно получиться гладким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8250,'Половину массы или чуть больше вылить на сухую горячую сковороду. Разложить ломтики сыра, залить оставшимся тестом. Жарить с двух сторон до румяной корочки под крышкой, затем без нее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8251,'Пекинскую капусту разобрать, оставить только мякгую часть листьев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8252,'Отварить говядину, нарезать соломкой, редьку дайкон также нарезать или натереть на терке. Добавить тертое яблоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8252,'Репчатый лук очистить, измельчить, обжарить на растительном масле, все ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8252,'Соль и молотый перец – по вкусу, заправить сметаной или майонезом, еще один вариант – растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8252,'Перемешать, украсить рубленой зеленью и крутыми отварными яйцами, разрезанными на четвертинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Натереть на терке сыр и колбасу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Измельчить зелень и сельдь без косточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Перемешать мягкое сливочное масло с колбасой в равных пропорциях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Второй вариант: масло и сыр.  Сыра взять в два раза больше, чем масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Третья намазка: масло и сельдь, в пропорции один к одному.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Четвертая – зелень, масло и соль, по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8253,'Намазать на хлеб, подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8254,'Смешать в блендере сок ананаса, лимонад и сок клюквы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8254,'Разлить смесь по холодным бокалам, наполняя их на 2/3 и долить пивом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8254,'Праздничный клюквенно-ананасовый пунш подавать к столу охлажденным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8255,'На кусочек черного хлеба положить пластинку сыра, затем колбасу, нарезанный укроп, снова пластинку сыра, верхний слой – белый хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8255,'Прогреть сковороду, бутерброды можно готовить без масла. Выложить изделия, жарить до румяной корочки с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8256,'Насыпать муку горкой, налить воду, в которой растворена соль, добавить растительное масло, замесить тесто, оно должно быть гладким. Оставить на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8256,'Для приготовления начинки, обжарить репчатый лук, перемешать его с отваренным и растолченным картофелем. Пюре посолить и поперчить по вкусу, добавить рубленый укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8256,'Для приготовления тыквенной начинки обжарить чеснок с луком, добавить тертую мякоть тыквы, потушить до готовности, поперчить и посолить, добавить  петрушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8256,'Разделить тесто на десять частей, раскатать тонкие лепешки. Положить на половинку начинку, закрыть второй половинкой, края залепить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8256,'Жарить на сухой сковороде до румяной корочки. Готовый кутаб сбрызнуть водой или смазать маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8257,'Хлеб чиабатта нарезать кусочками толщиной по полтора сантиметра, посушить в тостере или на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8257,'Пока продукт не остыл – натереть его чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8257,'Перемешать нарезанный базилик и помидоры, посолить, поперчить, заправить оливковым маслом. Выложить салат на чиабатту, полить отделившимся соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8258,'Сырое яйцо перемешать с мукой, солью, перцем, мелко нарезанным репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8258,'Намазать смесью ломтики хлеба, обжарить на заранее разогретом масле до румянца с двух сторон. Начинать выкладывать бутерброды на сковороду нужно луком вниз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Противень смазать растительным или оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Репчатый лук нарезать кольцами и выложить первым слоем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Второй слой – порезанный кружочками картофель, соль и перец – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/d9/d91d6d475008dd9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Третий слой – мясной фарш, затем нарезанные шампиньоны.','https:https://st.vkuso.ru/data/cache/thumb/0b/faab27e37346e0b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Блюдо засыпать тертым сыром и намазать смесью сметаны и майонеза в равных пропорциях.','https:https://st.vkuso.ru/data/cache/thumb/74/f5bc36a36590c74_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8259,'Печь до готовности, температура приготовления – 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/d0/2069d5bbc400ed0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8260,'Полоски бекона подрумянить на сухой сковороде, а затем выложить на бумажные полотенца для впитывания излишков жира.','https:https://st.vkuso.ru/data/cache/thumb/52/b7cf1b99e9c8c52_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8260,'Отварить и крупно нарубить куриные яйца. Добавить горчицу, майонез, паприку, соль и цедру лимона по вкусу. Массу перемешать.','https:https://st.vkuso.ru/data/cache/thumb/02/ddcfcfa1c220202_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8260,'Подрумянить хлеб в тостере или на сухой сковороде, немного остудить.','https:https://st.vkuso.ru/data/cache/thumb/1e/62daf5301a6651e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8260,'Смазать бутерброды сливочным маслом, выложить яичную смесь, бекон, на него – полоски свежих грунтовых огурцов.','https:https://st.vkuso.ru/data/cache/thumb/7f/d64dc81e661077f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8260,'Закуску накрыть вторым кусочком хлеба, также смазанным сливочным маслом. Сэндвич прижать и разрезать на два треугольника, по диагонали. То же самое проделать с оставшимися ингредиентами.','https:https://st.vkuso.ru/data/cache/thumb/c6/fb704961199eec6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8261,'Залить в шейкер красный вермут, бурбон, добавить несколько капель биттера ангастура, крошку льда, хорошо встряхнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8261,'Разлить Коктейль Манхеттен Бурбон по бокалам, украсить цедрой лимона и ягодкой вишни на шпажке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8262,'Сырые куриные грудки посолить и поперчить, сбрызнуть лимонным соком и оставить на полчаса для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8262,'Пароварку или кастрюлю прогреть. Застелить дно пароварки листом пергамента, выложить мясо. Накрыть крышкой, варить в течение 20 – 25 минут, до готовности. Если термообработка происходит в кастрюле – понадобится средний огонь.','https:https://st.vkuso.ru/data/cache/thumb/be/05a6e78e40330be_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8262,'На сковороду налить бальзамический уксус, всыпать мелкий сахар, добавить соевый соус и куриный бульон, положить чеснок. Соус уварить до состояния сиропа и снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8262,'На сковороду с готовой глазурью выложить грудки кожей вниз, прогреть на среднем огне в течение двух минут с каждой стороны.','https:https://st.vkuso.ru/data/cache/thumb/a6/73a75ed9280bba6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8262,'Убрать сковороду с огня, дать постоять две-три минуты, порезать на порции и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/c6/f499e227f4411c6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8263,'Налить в шейкер апельсиновый ликер «Трипл-сек», лимонный сок, водку, хорошо встряхнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8263,'Разлить коктейль «Камикадзе» с ликером и водкой по бокалам, украсить долькой лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Для приготовления бисквитного теста взбить сырые куриные яйца с сахарным песком в пышную пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Добавить просеянную пшеничную муку в два-три приема, каждую порцию вмешивать ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Чашу мультиварки смазать сливочным маслом, вылить тесто, поставить выпекаться на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Для цитрусовой прослойки понадобятся сочные и спелые мандарины и апельсины. Фрукты очистить и нарезать небольшими кусочками. Пленки можно удалить или оставить.','https:https://st.vkuso.ru/data/cache/thumb/a9/feec9264fdb98a9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Переложить нарезанные плоды на сковороду, посыпать сахарным песком, влить сок половины лимона. Варить массу на большом огне в течение пяти минут, огонь выключить, массу остудить.','https:https://st.vkuso.ru/data/cache/thumb/73/536fc73d631c573_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Готовый корж вынуть из мультиварки, остудить и разрезать поперек на три части.','https:https://st.vkuso.ru/data/cache/thumb/23/7f6ff66e3485923_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Взбить сметану с сахаром. На нижний корж вылить половину апельсиновой массы, распределить по поверхности. Сверху – четверть общей массы сметанного крема.','https:https://st.vkuso.ru/data/cache/thumb/8b/1b2ff6f304ec68b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'На второй корж поместить оставшуюся фруктовую смесь и еще четверть сметанного крема. Накрыть последним коржом, намазать верх и бока остатками крема.','https:https://st.vkuso.ru/data/cache/thumb/52/dd6d98b9440ee52_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8264,'Оставить десерт для пропитывания на час. Готовый торт посыпать тертым шоколадом, нарезать на порции и подать к чаю или кофе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Изюм без косточек залить кипящей водой, оставить на несколько минут. У помидор срезать верхушки.','https:https://st.vkuso.ru/data/cache/thumb/f8/cd3ca9aa83371f8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Мякоть аккуратно вынуть чайной ложкой. Получившиеся чашечки перевернуть и поставить на бумажное полотенце для стекания лишнего сока.','https:https://st.vkuso.ru/data/cache/thumb/84/a3ad3b1353b7c84_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Красные болгарские перцы разрезать пополам, семена вынуть, хвостики оставить.','https:https://st.vkuso.ru/data/cache/thumb/f7/414e2f359af6cf7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Мелко нарубить лук-шалот и очищенный чеснок, зелень петрушки и мяты.','https:https://st.vkuso.ru/data/cache/thumb/ac/c55ed35fd0cceac_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Мякоть помидоров мелко нарезать. С изюма слить воду, продукт обсушить на бумажном полотенце.','https:https://st.vkuso.ru/data/cache/thumb/3f/1d809dce0cd913f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Разогреть на сковороде оливковое масло, лук и чеснок обжарить до золотистого цвета, добавить молотый миндаль и хорошо перемешать, несколько орешков оставить для украшения.','https:https://st.vkuso.ru/data/cache/thumb/06/4b688b74c6e8d06_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Разогреть на сковороде большое количество растительного масла, обжарить перцы с двух сторон до образования румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Всыпать в массу длиннозерный рис, изюм, мякоть помидора, рубленую мяту и зелень петрушки. Все ингредиенты перемешать и снять с огня. Соль и перец молотый – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/ad/a187d62530320ad_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Духовку разогреть до 200 градусов. Чашечки помидоров вытереть бумажным полотенцем, сбрызнуть оливковым маслом и выложить вместе с перцами в форму для запекания. Нафаршировать то и другое начинкой, поставить закуску в заранее разогретую духовку на 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/5c/5a07e050fdf275c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8265,'Оставшийся миндаль перемолоть с зеленью петрушки. Овощи вынуть из духовки, посыпать ореховой смесью и сбрызнуть оливковым маслом. Поставить блюдо в духовку еще на 20 минут, орехи должны стать золотистыми.','https:https://st.vkuso.ru/data/cache/thumb/a4/b284fde539da0a4_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Очистить помидоры от кожицы: надрезать плоды крест накрест и опустить в кипяток на несколько минут.','https:https://st.vkuso.ru/data/cache/thumb/27/bb190f8f91fd527_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Кожицу снять, семечки вынуть ложкой.','https:https://st.vkuso.ru/data/cache/thumb/73/581b6ce49da7373_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Очистить свежий спелый огурец от кожуры и семян.','https:https://st.vkuso.ru/data/cache/thumb/1e/e9e1afb9038341e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Крупно нарезать красный сладкий болгарский перец, репчатый лук, чеснок. Все овощи переложить в блендер, взбить. Подлить винный уксус, всыпать панировочные сухари и соль.','https:https://st.vkuso.ru/data/cache/thumb/66/54b05068196a566_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Оливковое масло добавить постепенно, небольшими порциями. Соль и перец – по вкусу, можно добавить уксус. Должен получиться полужидкий суп. Если блюдо слишком густое – его можно разбавить томатным соком или кипяченой водой.','https:https://st.vkuso.ru/data/cache/thumb/7f/5d9dcdb342c397f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Кастрюлю с блюдом накрыть пищевой пленкой или крышкой, поставить в холодильник на два часа.','https:https://st.vkuso.ru/data/cache/thumb/6e/98d133922c8da6e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'Отдельно приготовить сухарики: нарезать кубиками хлеб, сбрызнуть оливковым маслом, поставить на полчаса в горячую духовку.','https:https://st.vkuso.ru/data/cache/thumb/59/45310cd60043059_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8266,'На гарнир нарезать зеленый сладкий перец и свежий огурец.','https:https://st.vkuso.ru/data/cache/thumb/d4/5034f0049755ad4_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8267,'Бросить в рюмку ягодку вишни, налить дынный ликер, сверху осторожно влить водку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8267,'Дынный коктейль «Русско-японская война» надо сразу подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Печенье из пачек, например, «Юбилейное», поместить в полиэтиленовый пакет. Завязать и побить сверху молотком для отбивания мяса или скалкой. Мелкая крошка не нужна, должны остаться кусочки среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/da/6b5e2dcf668fcda_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Очищенные грецкие орехи и кешью подрумянить на сковороде без масла. Изюм, сушеную вишню или клюкву промыть.','https:https://st.vkuso.ru/data/cache/thumb/e9/e9c8869b71354e9_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'В сотейник поместить сахарный песок, какао-порошок, сливочное масло и немного молока.','https:https://st.vkuso.ru/data/cache/thumb/22/10734126d544e22_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Смесь прогреть на тихом огне до однородного состояния. Глазурь немного остудить.','https:https://st.vkuso.ru/data/cache/thumb/f9/af252c7c2a3a3f9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Всыпать крошку от печенья.','https:https://st.vkuso.ru/data/cache/thumb/6b/d39ccc27d64486b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Добавить сухофрукты и орехи.','https:https://st.vkuso.ru/data/cache/thumb/06/b4af8723e11ce06_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Массу выложить на пищевую пленку, свернуть, уплотнить, края закрепить. Поместить колбаску в морозильную камеру на 45 минут, затем её можно переложить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/58/2b27e7986a81658_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8268,'Перед подачей изделие обвалять в сахарной пудре, нарезать.','https:https://st.vkuso.ru/data/cache/thumb/a8/35fb51a5b022aa8_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8269,'Пшеничную муку и сырые куриные яйца взбить при помощи венчика. Влить молоко и растопленное сливочное масло.','https:https://st.vkuso.ru/data/cache/thumb/fa/5cb8df6eead56fa_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8269,'Испечь блины, как обычно, с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/58/325bd3a1198c558_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8269,'Для приготовления соуса растопить в небольшой кастрюле масло, добавить просеянную муку, массу перемешать, она должна быть похожа на сметану. Влить молоко и проварить соус до загустения. Молотый перец, соль, мускатный орех – по вкусу. В конце добавить сушеный инжир, нарезанный ломтиками.','https:https://st.vkuso.ru/data/cache/thumb/18/58f0215e404d318_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8269,'Блинчики подать с горячим соусом.','https:https://st.vkuso.ru/data/cache/thumb/01/0cafa6239080001_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8270,'Сухие макароны без всякой предварительной обработки выложить в глубокую сковороду или на противень.','https:https://st.vkuso.ru/data/cache/thumb/76/365400e70a9c476_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8270,'Нарезать репчатый лук, добавить в макароны.','https:https://st.vkuso.ru/data/cache/thumb/86/639f639139ebf86_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8270,'Натереть или нарезать морковь, выложить поверх лука.','https:https://st.vkuso.ru/data/cache/thumb/96/2c66c607d4d9a96_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8270,'Следующий слой – мясной фарш с солью, перцем, приправами. Томатную пасту развести в воде, добавить по вкусу сахарный песок. Залить запеканку, можно добавить немного воды, продукты должны быть покрыты жидкостью полностью.','https:https://st.vkuso.ru/data/cache/thumb/78/26072aaff8bac78_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8270,'Поставить в духовой шкаф на 30 – 40 минут, прогревать до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8271,'Влить в шейкер со льдом персиковый ликер, водку, сок клюквы и апельсина, тщательно встряхнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8271,'Разлить коктейль «Новогодний секс на пляже» по высоким бокалам, украсить тонкой долькой апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Для приготовления теста понадобится сырое куриное яйцо, пшеничная мука и кефир. Замесить тесто, оно должно быть мягким и эластичным. Разделить его на шарики среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Нарезать мясо на небольшие кусочки или приготовить фарш. Репчатый лук и очищенный картофель нарезать кубиками. Ингредиенты для начинки соединить, поперчить, посолить, добавить специи и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Каждый кусочек теста раскатать в лепешку, в середину выложить картофельно-мясную начинку и кусочек сливочного масла.','https:https://st.vkuso.ru/data/cache/thumb/c5/5d2ac0e804fd0c5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Края беляшей собрать оборкой, не защипывая полностью, изделие должно напоминать мешочек.','https:https://st.vkuso.ru/data/cache/thumb/7f/1303574144bc57f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Противень застелить пергаментом, выложить беляши, смазать их взбитым яйцом, поставить в духовку, разогретую до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'В процессе приготовления в оставленные отверстия подливать воду, это нужно сделать три-четыре раза за все время выпекания: начинка будет сочной, не пересохнет. Время приготовления – 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8272,'Для соуса ошпарить помидоры, снять кожицу. Мякоть нарезать мелкими кубиками, потушить на сковороде с растительным маслом, солью, перцем, яблочным уксусом. В конце добавить горчицу, рубленый чеснок и тертые маринованные огурцы. Ингредиенты перемешать, беляши подать с полученным соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Охлажденное сливочное масло натереть на крупной терке.','https:https://st.vkuso.ru/data/cache/thumb/6d/b229d245151046d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Перетереть его вместе с мукой в крошку, добавить сахарную пудру, ваниль и хорошо перемешать. Добавить миндальную муку, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a5/907291889f0ada5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Темный ром взбить вместе с яйцом.','https:https://st.vkuso.ru/data/cache/thumb/55/9c8ecbf6ee29755_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'В середину сухой смеси влить яйцо и вымесить тесто быстрыми движениями.','https:https://st.vkuso.ru/data/cache/thumb/5a/09180112f00775a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Тесто скатать в шар, обернуть в пищевую пленку, убрать в холодильник на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Духовку нагреть до 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Рабочую поверхность присыпать мукой. Тесто раскатать в виде длинной полоски шириной в пять сантиметров, толщина – до полутора сантиметров.','https:https://st.vkuso.ru/data/cache/thumb/18/3d494c8aad1db18_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Нарезать полосками до полутора сантиметров в ширину, должны получиться брусочки.','https:https://st.vkuso.ru/data/cache/thumb/08/26575a4d78c3e08_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Сформовать полумесяцы, края не должны быть тонкими, иначе подгорят.','https:https://st.vkuso.ru/data/cache/thumb/58/2194a948f34e458_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Противень застелить пекарской бумагой, печь в течение 10 – 15 минут в верхней части духовки.','https:https://st.vkuso.ru/data/cache/thumb/d5/7e55672a8d17bd5_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8273,'Готовое печенье не должно слишком зарумяниться. Остудить его на противне, переложить на блюдо и посыпать сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/d3/fc27887b5aa06d3_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Сладкие перцы запечь в духовом шкафу. Накрыть пищевой пленкой на 15 минут, остудить, аккуратно очистить от семян и кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Брынзу размять или натереть на крупной терке, добавить творог, нарезанную зелень базилика, мяты, петрушки и укропа, измельченный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Мелко нарезать помидор, отжать сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11445,'Массу перемешать и довести до кипения.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8274,'Сложить плоды на бумажное полотенце для удаления лишнего жира. Подать холодными, в качестве закуски, или теплыми, как второе блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'Говяжьи ребрышки вымыть, обсушить бумажным полотенцем, натереть солью и молотым перцем, оставить для пропитывания на пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'Разогреть сковороду с растительным маслом. Обжарить мясо со всех сторон на сильном огне.','https:https://st.vkuso.ru/data/cache/thumb/eb/85683a079afabeb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'Влить куриный бульон и белое сухое вино. Добавить чернослив, перемешать и довести до кипения.','https:https://st.vkuso.ru/data/cache/thumb/5b/67a58aae2c09e5b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'Огонь убавить до минимального, прикрыть емкость крышкой, неплотно, пар должен выходить. Тушить в течение полутора-двух часов, мясо время от времени переворачивать. В конце приготовления оно должно стать мягким и легко отходить от костей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'Снять с огня, дать постоять в течение 15 – 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8275,'К блюду можно подать картофельно-яблочное пюре. Приготовить его так же, как картофельное, но треть клубней заменить яблоками: плоды очистить и отварить вместе с картофелем, но добавить на пять минут позже основного продукта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Чтобы приготовить светлое тесто, нужно смешать муку, соду (можно негашеную), сметану, сахар и размягченный маргарин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Для шоколадного теста следует смешать те же ингредиенты что и для светлого, только к ним еще надо добавить какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Заместить в обеих мисках пышное тесто, каждое из которых разделить на 2 части,должно получиться 2 светлых и 2 темных части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Все 4 куска теста раскатать в круги диаметром 25 см, в течение 10-12 минут испечь в духовке коржи при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Для приготовления глазури и крема взбить с сахаром сметану, всыпать мак и снова взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Из готовых коржей и крема собрать торт: сначала корж, замет крем, снова корж и так до конца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Оставшийся крем довести до кипения, немного поварить на слабом огне, периодически помешивая, получившейся глазурью аккуратно полить поверхность торта.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8276,'Шоколадно-сметанный торт с маком на 3-4 часа поставить в холодильник, при желании можно оставить его там на всю ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Раскалить растительное масло на сковороде, всыпать круглый рис, обжарить его в течение минуты до прозрачного состояния.','https:https://st.vkuso.ru/data/cache/thumb/bf/b4856689e09b5bf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Влить в рис горячую воду или бульон, немного, жидкость должна впитаться. Налить следующую порцию, продолжать до тех пор, пока рис не впитает всю влагу и не станет мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Массу помешивать деревянной лопаткой. Всыпать сушеный базилик. Рис немного остудить.','https:https://st.vkuso.ru/data/cache/thumb/3c/c93dc174ee68b3c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Добавить тертый сыр «Пармезан». Смесь разровнять в форме и полностью охладить.','https:https://st.vkuso.ru/data/cache/thumb/63/2e145822e77ab63_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Взболтать сырое куриное яйцо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Взять в ладонь небольшое количество готового ризотто, в центр положить шарик «Моцареллы», вдавить.','https:https://st.vkuso.ru/data/cache/thumb/5c/8a0acd97b5b965c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Сформовать шарик, обмакнуть в яйцо.','https:https://st.vkuso.ru/data/cache/thumb/4b/33c007ae94eb34b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Обвалять в сухарях.','https:https://st.vkuso.ru/data/cache/thumb/cc/066d37ec747b6cc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Обжарить в растительном масле.','https:https://st.vkuso.ru/data/cache/thumb/1e/deb89e49f8cd01e_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8277,'Выложить готовые изделия на бумажные салфетки для впитывания излишков жира. Подать сразу, в горячем виде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'Зелень салата и свежие огурцы нарезать и выложить в салатницу.','https:https://st.vkuso.ru/data/cache/thumb/03/2b454e08ca4e803_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'У спаржи удалить жесткие кончики на полтора-два сантиметра.','https:https://st.vkuso.ru/data/cache/thumb/06/d1fd1d811928d06_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'Отварить в кипящей подсоленной воде в течение двух-трех минут после начала закипания. Продукт быстро процедить и сполоснуть проточной холодной водой. Крупно порезать, стрелки отложить в сторону, стебли добавить в салатную зелень.','https:https://st.vkuso.ru/data/cache/thumb/4d/aeabfc618234b4d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'Кусочек белого хлеба нарезать кубиками и подсушить на сковороде без масла.','https:https://st.vkuso.ru/data/cache/thumb/a6/75a9b7c2edbf5a6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Намазать влажный шоколадный торт по бокам и сверху. По желанию украсить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'Поместить в блендер сок лимона, оливковое масло, натуральный мёд, готовую сладкую горчицу, лук-шалот, зеленый базилик, подлить воду. Измельчить ингредиенты до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/6a/b760debcb2d826a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8278,'Половину заправки перемешать с салатной зеленью. Разложить салат в тарелки, сверху – гренки, стрелки спаржи, кусочки копченого лосося. Полить блюдо остатками заправки.','https:https://st.vkuso.ru/data/cache/thumb/e3/4fe98c64cb43ce3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8279,'Готовые пласты лазаньи отварить в подсоленной воде до полуготовности, выложить в дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8279,'Мясной фарш обжарить в масле вместе с томатной пастой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8279,'Мелко нашинковать белокочанную капусту и репчатый лук, оба продукта обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8279,'Форму для выпекания смазать маслом, выложить пласты лазаньи вперемешку с капустой и с мясом. Посыпать блюдо тертым сыром, время выпекания – от 15 до 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8280,'Яйца вымыть, убрать на 3 дня в морозилку, достать, дать полежать в тепле час, аккуратно разбить, разделить желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8280,'Обжарить подсоленные белки, переложить на тарелку, по центру каждого положить по желтку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8280,'Вокруг желтков выложить кольцом красную икру, украсить укропом, подать с ржаным хлебом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'Взбить сахар с яйцами, растереть  с размягченным маргарином, добавить смешанную с погашенной уксусом содой муку и замесить льющееся негустое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'В заранее промазанную маслом и обсыпанную манной крупой форму вылить получившуюся массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'Выпекать корж около 40 минут при 190 градусах, готовность его проверить шпажкой или зубочисткой, испеченному коржу дать остыть, разрезать пополам вдоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'Для крема из манной крупы и молока сварить негустую кашу, охладить ее, взбить вместе с маслом, заранее растертым со сгущенным молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'Для приготовления глазури смешать какао, сливочное масло, молоко и сахар, держать до полного растворения сахара на огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8281,'Собрать торт «Птичье молоко» с манным кремом из всех компонентов, полить глазурью и дать ей застыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Острым ножом отрезать верхнюю часть головки чеснока. Поместить овощ на лист фольги, посолить, сбрызнуть оливковым маслом, завернуть.','https:https://st.vkuso.ru/data/cache/thumb/5b/531726099abe75b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Печь в духовом шкафу в течение 45 минут до мягкости.','https:https://st.vkuso.ru/data/cache/thumb/6e/738809b6088ae6e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Очистить репчатый лук и нарезать полукольцами. В кастрюле разогреть сливочное масло, добавить подготовленный лук и веточку тимьяна. Жарить на среднем огне, помешивая, до карамелизации лука, он должен приобрести румяный цвет. Тимьян вынуть и выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Готовый запеченный чеснок остудить в течение 10 минут, очистить и выдавить мякоть на тарелку, полить маслом, в котором продукт запекался.','https:https://st.vkuso.ru/data/cache/thumb/f3/9fee7c0e14f38f3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Размять вилкой. Чесночное пюре переложить в лук.','https:https://st.vkuso.ru/data/cache/thumb/c5/fc774ce26d61ec5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Очистить и нарезать кубиками клубни картофеля. Промыть их под проточной водой, добавить в лук и залить горячим бульоном. Варить до готовности картофеля. Два стакана жидкости слить, отставить в сторону.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Овощи взбить блендером до получения гладкой однородной массы, долить оставленную жидкость до получения нужной консистенции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8282,'Всыпать тертый сыр, помешивая, довести суп до кипения и сразу выключить огонь. Соль и перец молотый – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/b7/3f47ace536912b7_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8283,'Очистить яблоко, порезать.','https:https://st.vkuso.ru/data/cache/thumb/70/30c549b64b97870_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8283,'Переложить вместе с другими ингредиентами в блендер.','https:https://st.vkuso.ru/data/cache/thumb/1e/164b3d3654fe41e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8283,'Взбить до состояния однородного пюре.','https:https://st.vkuso.ru/data/cache/thumb/26/b8e1dfdcf449026_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8283,'Перелить смузи в высокий стакан, оформить карамельным сиропом.','https:https://st.vkuso.ru/data/cache/thumb/3e/5de5555b507a73e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8284,'Порезать мясо, обжаривать на горячей сковороде несколько минут без масла. Порезать лук, обжаривать на сливочном масле, пока не станет мягким. Нарезать капусту, крупно потереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Посыпать солью, заправить майонезом, посыпать пряностями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8284,'Соединить, посыпать солью, позволить минут десять постоять. Почистить яблоко от кожуры, порезать на кубики. Взять горшочек, выложить все слоями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8284,'Сверху мясо, посыпать перцем. Яблоки, капуста с луком и морковью. Опять мясо, яблоки, посыпать перцем. Они должны быть последним слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8284,'Накрыть крышечкой, отправить капусту с мясом в горшочке в духовку минут на шестьдесят, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8285,'Обжарить в сливочном масле предварительно порезанную тонкими ломтиками куриную грудку до подрумянивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8285,'На дно формы выложить обжаренное мясо, сверху распределить кружки помидоров, залить все тщательно посоленной и поперченной взбитой молочно-яичной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8285,'Посыпать поверхность омлета тертым сыром, поместить форму на 15 минут в микроволновку под гриль или духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8285,'Легкий омлет с обжаренной курицей, помидорами и сыром будет полностью готов, как только зарумянится сыр, перед подачей омлет посыпается рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8286,'Измельчить на терке лук, сложить в кастрюлю с толстым дном, влить пару столовых ложек масла, нагреть, обжарить 2-3 минуты, добавить чеснок, раздавленный прессом и томатное пюре, всыпать соль, орегано, сахар, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8286,'Дать смеси закипеть на среднем огне, тушить около 10 минут при слабом нагреве без крышки, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8286,'Прогреть духовку до 200 градусов, грудки слегка отбить, подсолить, в достаточно широкой миске разболтать подсоленные яйца, в другую насыпать сухари и мелко натертый пармезан.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8286,'В сковороде разогреть растительное масло, грудку посолить, окунуть в яйцо, потом обвалять в сухарях с сыром, обжарить до появления корочки со всех сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8286,'В форму налить половину томатного соуса, положить грудки, вылить поверх остатки соуса. Присыпать куриные грудки в томатном соусе по-итальянски порубленным базиликом и тертым сыром, выпекать около 20-25 минут в уже прогретой духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8287,'Почистить лук, порезать тоненькими полукольцами. Перемешать лук, сметану, паприку, соль, острый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8287,'Чтобы сделать начинку соединить жареные грибочки, отварной рис, измельченное вареное яйцо, зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8287,'В почищенные кальмары положить начинку, отправить в горшочки. На фаршированные кальмары выложить соус, посыпать тертым сыром и поставить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8288,'В слегка подсоленной воде отварить картофель в мундире, очистить и нарезать его кружками, мелко порубить ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8288,'В подготовленную форму выложить слой картофеля, затем слой ветчины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8288,'Смешать с мукой, яйцами, тертым сыром и солью сметану, получившейся заправкой залить ветчину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8288,'Далее выложить снова картофельный слой, сверху положить небольшой кусок сливочного масла, посыпать тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8288,'Запеченный с ветчиной картофель в сметане готовится на протяжении 40-45 минут в духовом шкафу, а подается порционно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8289,'Порезать на кубики морковь, картофель, кабачки. Порезать произвольно чесночок и лук. Обжарить под крышкой на смеси растительного и сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8289,'Положить морковь, тушить минут пять. Добавить кабачки, картофель, готовить под закрытой крышкой минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8289,'Добавить несколько больших ложек сладкой паприки, маленькую ложку молотого чили, залить бульоном, чтобы сантиметра на полтора покрывал смесь, оставить побулькать минут семь под крышкой. Выключить, чуть-чуть остудить, измельчить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8289,'Добавить сливки, поставить на огонь, довести практически до кипения. Выключить огонь, дать картофельному супу с кабачками настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8290,'Свиную шейку отбить через пищевую пленку или полиэтиленовый пакет, поперчить, посолить, при желании натереть специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8290,'В форму или противень налить растительное масло, выложить кусочки отбитого мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8290,'Полукольцами или кольцами порезать лук, выложить его, не разделяя, на мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8290,'На слой лука выложить пластинки помидоров, хорошо промазать их майонезом и посыпать крупно натертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11450,'Выставить режим «Выпечка» на 35 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8290,'Емкость с заготовкой поместить в духовку, запекать мясо в течение 25 минут при 180 градусах, затем мясо по-французски с помидорами должно настояться в районе 15 минут, подавать блюдо можно с зеленью и любым гарниром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8291,'Крупно потереть картофель. Отжать руками, чтобы избавиться от лишней жидкости. Вбить яйца, насыпать соль, муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8291,'Обвалять в муке тушки тилапии. С двух сторон прижать к рыбке массу из картофеля. Осторожно положить рыбу на горячую сковороду с маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8291,'Жарить на среднем огне. Когда с одной стороны будет корочка, перевернуть и готовить с другой стороны. Сделать огонь тише, жарить тилапию до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8292,'Порезать цукини на тоненькие полоски вдоль. Можно использовать овощечистку. Полосочки должны быть такие тонкие, чтобы их можно было скрутить, но не должны при этом рваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8292,'Тарелку большого размера сбрызнуть или равномерно смазать оливковым маслом, посыпать перцем и солью. Выложить полоски цукини, прижать, перевернуть. Это легкий способ приправить хрупкие полосочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8292,'Порезать семгу на небольшие брусочки. Намазать все полоски цукини тоненьким слоем сливочного сыра, с нижнего и верхнего края оставлять примерно по 1 сантиметру, по бокам по 0,5 сантиметров. Сверху положить кусочек семги, осторожно завернуть в виде рулетика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8292,'Каждый положить горизонтально вниз швом, чтобы форма цукини зафиксировалась. Повторить процесс с каждой полосочкой. Подавать рулетики из цукини с семгой в вертикальном виде, украсить укропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8293,'Отмерить полторы чашки воды, налить в ковшик, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8293,'Отмерить одну чашку хлопьев, насыпать, помешивая, положить промытый изюм, посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8293,'Отмерить полторы чашки молока, налить маленькими порциями, доводить каждый раз до кипения, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8293,'Варить кашку до густой консистенция, помешивать. Обычно на приготовление уходит минут пятнадцать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8293,'Положить в готовую овсяную кашу с изюмом кусок сливочного масла, варенье или мед.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Приготовить тесто: просеять в посуду муку, крупно потереть в нее маргарин. Вбить яйцо, насыпать соль, влить воду. Замесить тесто, отправить его на тридцать минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Сделать начинку: лук порезать на маленькие кубики, обжарить на растительном масле. Положить к луку грибы, порезанные на тоненькие пластинки. Посыпать перцем, солью, готовить минут пять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Отварить куриное филе в соленой воде, достать, остудить. Порезать мясо на маленькие кубики, добавить грибочки. Перемешать. Приготовить заливку: налить в посуду сливки, потереть сыр. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Из холодильника достать тесто, раскатать в пласт. Переложить пласт в формочку. Ничем смазывать формочку (размером 24 сантиметра) не нужно. У теста сделать бортики. Осторожно обрезать краешки при помощи фигурного ножа. Вдавить обрезки по дну формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Положить начинку в подготовленную форму. Помидоры разрезать пополам, разложить по начинке вниз срезом. Сверху залить заливкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8294,'Отправить пирог «Киш лорен» с курицей и грибами в духовку минут на сорок, соблюдать температуру 180 градусов. Сверху тесто должно стать подрумяненным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Приготовить коржи: соединить растительное масло с водой. Перемешать муку, ванилин, какао и разрыхлитель. Высыпать в одну емкость, мешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Вылить все в формочку, застеленную специальной бумагой, отправить в духовку, соблюдать температуру 180 градусов. Выпекать до готового состояния, проверять до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Во время готовки бисквита, приготовить начинку. Соединить кокосовую стружку и половину банки сгущенного молока, положить сливочное масло, перемешать. Растопить на водяной бане молочный шоколад.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Остудить готовые коржи, разрезать вдоль на несколько частей. Одну половинку намазать оставшимся сгущенным молоком, вторую шоколадом. На одну часть положить начинку, накрыть второй частью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8295,'Приготовить глазурь: растопить горький шоколад, перемешать со сливочным маслом и водой. Перемешать до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8296,'В газированной воде размешать муку, добавить соль, молоко, сахар, ванилин и взбитые яйца, тесто тщательно размешать до однородного состояния, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8296,'Хорошо разогреть сковородку, испечь на ней блины, которые необходимо со всех сторон обжаривать до подрумянивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8296,'Перед тем как подавать блины на газированной воде с молоком, их нужно смазать джемом, повидлом или вареньем, сложить в 2 или 4 раза, залить фруктовым сиропом либо посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8297,'Освободить икру от пленок, смешать с измельченным луком, сливками. Посыпать перцем, солью, травами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8297,'Вылить смесь из икры в формочку, намазанную маслом, или небольшую чугунную сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8297,'Запекать минут тридцать до румяного оттенка, соблюдать температуру 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8298,'Насыпать в молоко соль и закипятить. Соединить яйца и сметанку, взбивать не нужно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8298,'Сметану тоненькой струей налить в кипящее молоко. По вкусу насыпать специи и зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8298,'После закипания, готовить, помешивая, минуты четыре. Должны образоваться крупные хлопья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8298,'Процедить, используя марлю, когда остынет, чуть-чуть отжать, положить под гнет. После остывания сыр сулугуни отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8299,'Промыть замоченную фасоль, отварить в кипящей воде. Затем пролить ее через дуршлаг, оставить на какое-то время, чтобы стекла жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8299,'Положить на тарелочку брынзу, размять вилкой, чтобы получились мелкие частицы. Измельчить почищенный чесночок и чистую петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8299,'Соединить все ингредиенты: чеснок, зелень, фасоль и брынзу. Украсить салат из фасоли лимонной цедрой, посыпать паприкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8300,'Соединить в глубокой емкости все продукты в любой последовательности. При помощи блендера чуть-чуть взбить массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8300,'Осторожно разлить смесь по формочкам. Вставить палочки. Заморозить. Мороженое должно находиться в морозилке пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8301,'Включить духовку, температуру в ней довести до 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8301,'Перемешать в чаше блендера манку, творог, яйцо, сметану, желток от одного яйца, сахар и  ванильный сахар в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8301,'Взбить отдельно пару белков в устойчивую пену, осторожно объединить с творожной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8301,'Смазанную маслом форму, обсыпать сухарями, стряхнуть лишние крошки, заполнить ее творожной массой, отправить в уже прогретую до нужной температуры духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8301,'Творожная запеканка будет готова примерно через час, отключить нагрев, форму какое-то время не доставать, пусть она чуть остынет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8302,'Смешать в кастрюле молоко, сахар и сухое молоко, поставить ее на огонь и, постоянно помешивая, варить массу на самом маленьком огне пока молочная масса не станет коричневатого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8302,'Как только масса приобретет нужный оттенок, к ней необходимо добавить сливочное масло и продолжить варить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8302,'Варится карамель по-домашнему не меньше 90 минут: если ее не доварить, получится вареная сгущенка, если наоборот переварить – ириски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8303,'Отобрать примерно одинаковые небольшие картофелины цилиндрической формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8303,'Смазать с помощью кисти сковороду, в которой будем готовить картофель, маслом, на крупном зубчике чеснока сделать сеточку насечек и обмазать дно и стенки сковороды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8303,'Оставшийся чеснок измельчить на мелкой терке в кашицу, добавить к сливочному маслу, хорошо перемешать, присолить, поперчить, еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8303,'Довести подсоленную воду до кипения, положить, не очищая картофель, сварить почти до готовности, слегка остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8303,'Порезать клубни вдоль на тоненькие ломтики, но до конца не дорезать, поместить на сковороду, смазать их чесночным маслом. Запекать картошку с маслом и чесноком около получаса при 180 градусах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8304,'Нашинковать тонко редис и огурцы, зелень укропа очень мелко порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8304,'Сложить в блендер орехи, влить лимонный сок, воду, добавить соль, асафетиду, мед, взбить до образования однородного соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11494,'Они должны быть небольшими, одного размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8304,'Переложить овощи в глубокую пиалу, залить салат из редиса ореховым соусом, хорошо перемешать, чтобы овощи пропитались.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8305,'Гречку поместить в глубокую миску, всыпать муку, соль, вбить сырые куриные яйца, массу хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b9/b7ed67d45e278b9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8305,'Разогреть на сковороде растительное масло, выложить тесто в виде оладий.','https:https://st.vkuso.ru/data/cache/thumb/bd/abc713b747f41bd_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8305,'Жарить две минуты до появления румяной корочки, перевернуть и обжарить с другой стороны. Тарелку застелить бумажным полотенцем, выложить оладьи.','https:https://st.vkuso.ru/data/cache/thumb/65/62497c70ee77965_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8305,'Для приготовления соуса перемешать хрен, сметану и соль.','https:https://st.vkuso.ru/data/cache/thumb/61/13c03bf90091161_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8305,'Готовые оладьи выложить на сервировочную тарелку, сверху – красный лук, соус, кусочки малосольной семги и хорошо вымытый кресс-салат.','https:https://st.vkuso.ru/data/cache/thumb/e2/b2cf9119bd7f5e2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Приготовить фарш из говядины и свинины в равных пропорциях. В воде замочить кусочек белого пшеничного хлеба с удаленной корочкой.','https:https://st.vkuso.ru/data/cache/thumb/35/6f6a91e1229d035_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Репчатый лук мелко нарезать, добавить в фарш вместе с размоченным хлебом, перемешать, посолить и поперчить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/da/44e87285d0a74da_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Нарезать любую зелень, добавить мяту в основную массу вместе с сырым яйцом.','https:https://st.vkuso.ru/data/cache/thumb/da/93d7acb312649da_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Вымесить фарш до однородного состояния, сформовать круглые тефтели. Обжарить изделия на разогретой с растительным маслом сковороде до получения румяной корочки.','https:https://st.vkuso.ru/data/cache/thumb/31/f843a4082679231_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Для соуса свежие помидоры надрезать и опустить на одну-две минуты в кипяток, кожуру снять, мякоть измельчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Можно использовать готовое томатное пюре, его нагревают в кастрюле, солят и доводят до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Обжаренные тефтели выложить в кипящий соус, прикрыть крышкой неплотно, чтобы свободно выходил пар. Тушить блюдо в течение 20 минут до готовности.','https:https://st.vkuso.ru/data/cache/thumb/5c/c19310bd540665c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8306,'Готовые тефтели подать, полить соусом, посыпать рубленой зеленью.','https:https://st.vkuso.ru/data/cache/thumb/5b/75e4745530e415b_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8307,'В густой крем блендером или миксером взбить сливки, молоко и пудинг, полученную смесь смешать с творогом, предварительно перемешанным с сахаром, все хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8307,'На дно формы выложить первым слоем смоченное в молоке печенье, вторым слоем – 1/2 всего крема, затем снова слой печенья и последним слоем — оставшуюся часть крема.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8307,'Для приготовления шоколадной глазури нужно растопить сливочное масло, горький шоколад, сахар и молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8307,'Получившейся глазурью покрыть весь творожный торт в глазури с печеньем без выпечки, поставить его на несколько часов в холодильник, чтобы он пропитался, а глазурь застыла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8308,'Свиную вырезку вымыть и обсушить бумажным полотенцем. Переложить мясо в пакет со специями «греческая смесь», подлить масло из виноградных косточек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8308,'Пакет закрыть, мясо перетереть в маринаде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8308,'Вырезку достать и выложить на гриль. Жарить с каждой стороны по 10 минут, дать постоят пять минут, нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8308,'Подать блюдо со свежим зеленым укропом и накрошенным сыром «Фета».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Куриные грудки натереть солью и молотым перцем. Завернуть мясо в пищевую пленку и немного отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Разогреть на сковороде оливковое масло и обжарить грудки до готовности с двух сторон в течение 15 – 20 минут. Для приготовления блюда можно использовать сковороду-гриль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Готовые грудки остудить, нарезать полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Отварить вкрутую куриные яйца, немного остудить и разрезать на четыре части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Смесь зеленых салатов хорошо вымыть и просушить, порвать на части и выложить в глубокую миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Вымыть свежие помидоры и огурцы, нарезать большими полукольцами и кольцами, в зависимости от диаметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Репчатый лук очистить и тонко нарезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Все овощи перемешать с зеленым салатом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11494,'Выложить на противень, сбрызнуть водой, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Для приготовления заправки соединить натуральный мёд, свежий лимонный сок, неострую горчицу, оливковое масло. Смесь хорошо взбить с помощью венчика. Две трети заправки добавить к овощам, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8309,'Разложить салат в сервировочные тарелки, поверх распределить курицу и яйца. Готовое блюдо посыпать каперсами и полить остатками заправки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8310,'Тушку рыбы промыть, обсушить, нарезать порциями, натереть белым свежемолотым перцем и солью по вкусу. Выложить филе на дно жаропрочной посуды одним слоем.','https:https://st.vkuso.ru/data/cache/thumb/72/f77151f9e6b5672_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8310,'На небольшой сковороде разогреть смесь сливочного и растительного масла, добавить измельченный репчатый лук и жарить до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8310,'Добавить лесные грибы, соль и перец, прогревать в течение четырех-пяти минут, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/f2/6d3a9fd69c46af2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8310,'Подлить сливки, перемешать. Полученным сливочно-грибным соусом залить рыбу. Распределить смесь равномерно, поставить в заранее разогретый духовой шкаф, печь в течение 20 минут при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8310,'Почти готовое блюдо посыпать рубленой зеленью петрушки и тертым сыром «Пармезан». Допечь в течение 10 минут, сыр должен подрумяниться. Подать блюдо к столу горячим.','https:https://st.vkuso.ru/data/cache/thumb/e0/c2c199346b268e0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Срезать у длинных огурцов кончики, разрезать в длину на 4 части, а потом каждую – на 4 ломтика, переложить их в миску, присолить, дать постоять треть часа, пусть появится сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Взять до конца не размороженное мясо, нарезать соломкой потоньше, лук – полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Вылить из миски с огурцами сок, слегка их отжать, добавить горкой острый красный перец, размолотый кориандр, всыпать сахар, выдавить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'На сильном огне разогреть сковороду с маслом, всыпать мясо, обжарить при помешивании около минуты до сухой коричневой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Добавить лук, размешать, сдобрить соевым соусом, обжарить еще около пары минут, очень хорошо перемешать и залить огурцы горячей смесью, дать постоять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Нарезать болгарский перец соломкой, выложить на мясо и залить уксусом. Через 5 минут перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8311,'Подать овощи с говядиной по-корейски можно либо в горячем виде, либо полностью остывшими.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8312,'Зачистить и вымыть кусок мяса, обсушить, нарезать на небольшие кусочки, зажарить до коричневатой корочки на предварительно раскаленной сковороде около 10 минут (нагрев уменьшить до минимума).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8312,'Подготовить и порезать овощи на одинаковые кусочки, примерно как мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8312,'Засыпать их в мясо, обжарить пару-тройку минут, влить соевый соус, увеличить нагрев, перемешать и быстро обжарить все вместе до появления карамельного цвета, добавить в конце приготовления достаточно много мелко порезанного горького перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8312,'Подать свинину с кабачками в соевом соусе к столу с большим количеством разной зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8313,'Включить для прогрева до 180 градусов духовку, порезать на кубики охлажденное масло, всыпать сахар, влить молоко, чуть подсолить, постепенно всыпать муку, вымесить тесто. Раскатать его в пласт на присыпанном мукой столе, уложить в форму, сформовать бортики, излишки убрать. Выпекать основу  для вкусного шоколадного тарта с шоколадной глазурью около 12-15 минут.','https:https://st.vkuso.ru/data/cache/thumb/e1/e866b7af98d3ae1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8313,'Плитки шоколада поломать на куски, положить в миску с маслом, влить закипевшие сливки, перемешать до растворения и получения однородной массы.','https:https://st.vkuso.ru/data/cache/thumb/06/839105d34739006_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8313,'Взбить белки с добавлением соли, добавить желтки, смешать с шоколадной смесью, вылить в готовую основу, отправить в уже прогретую духовку минут на 25, вынуть тарт, дать пару часов остыть.','https:https://st.vkuso.ru/data/cache/thumb/24/fca2e37a1ef8524_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8313,'Для приготовления глазури сливочное масло и шоколад залить  кипящими сливками, тщательно размешать, нанести ее на пирог, дать застыть.','https:https://st.vkuso.ru/data/cache/thumb/b7/25e2415448550b7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8314,'Подготовить грибы и картофель, вымыть, очистить, порезать на 4 части. Хорошо прогреть в сковороде масло, добавить кари, перемешать, обжарить за 5 минут грибы.','https:https://st.vkuso.ru/data/cache/thumb/fd/07137a8f026b4fd_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8314,'Положить картофель, влить стакан воды, подсолить, дать закипеть, сделать минимальный нагрев, закрыть крышкой, тушить картофель с карри и грибами четверть часа. Всыпать размороженный горошек, тушить еще 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/2e/f0bc8ff94aad22e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8314,'За пару минут до готовности влить молоко кокоса, добавить порубленную зелень.','https:https://st.vkuso.ru/data/cache/thumb/a3/cd01776655e9aa3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Отварить до готовности куриную грудку, очищенные картофель и морковь, яйца и грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Готовое мясо мелко порезать, грецкие орехи измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Крупно натереть на плоское сервировочное блюдо ровным слоем порцию моркови, сыра, картофеля и одно яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Смазать все майонезом и поверх него распределить подготовленное мясо и орешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Далее продолжить собирать куриный салат с шампиньонами и орешками следующим образом: слой картофеля; слой майонеза; слой яиц; слой моркови;  слой сыра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8315,'Всю поверхность салата украсить отварными шампиньонами и убрать блюдо на 8 часов в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Порезать небольшими брусочками очищенный ананас и сыр, филе куриной голени аккуратно отбить, посолить, присыпать перцем с обеих сторон.','https:https://st.vkuso.ru/data/cache/thumb/9c/4cecb739f320e9c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Уложить на край мяса начинку, свернуть трубочкой.','https:https://st.vkuso.ru/data/cache/thumb/97/25bcf894985b997_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Скрепить деревянной зубочисткой или обвязать шпагатом.','https:https://st.vkuso.ru/data/cache/thumb/c8/975346f7d8e6ac8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'На плоскую тарелку высыпать кукурузную муку, обвалять голени.','https:https://st.vkuso.ru/data/cache/thumb/76/6c57260f971b776_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Хорошо разогреть в сковороде масло, обжарить куриную голень с сыром и ананасом на большом огне до появления корочки со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/c5/0261bb04400acc5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Для соуса перемолоть в блендере часть ананаса с сахаром.','https:https://st.vkuso.ru/data/cache/thumb/01/603f837f2484001_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8316,'Вылить соус в форму, переложить туда голени, поставить на 15 минут в прогретую до 200 градусов духовку, подавать блюдо горячим.','https:https://st.vkuso.ru/data/cache/thumb/c8/b18da2b39f6cdc8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8317,'Прогреть сковороду, положить масло, нагреть его до образования пузырьков и легкого бурления, добавить сахар, мешать до изменения цвета на коричневый, влить сметану, довести до кипения, отключить нагрев.','https:https://st.vkuso.ru/data/cache/thumb/67/e43905b9fdf8867_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8317,'Добавить в смесь сухое молоко, очень хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d2/7b6b0aa3ba1e2d2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8317,'Переложить в форму, сверху засыпать обжаренным арахисом. Примять орехи руками, убрать карамельные конфетки с арахисом на полчаса в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/04/fa3adde9c186904_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8317,'Достать, порезать на небольшие кусочки очень острым ножом.','https:https://st.vkuso.ru/data/cache/thumb/e4/684d3d959bbcae4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8318,'Сметану смешать с солью, молотым перцем и чесноком, предварительно измельченным с помощью чесночницы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8318,'Выложить промытые куриные грудки в форму, хорошенько смазать сметанным соусом и посыпать мелко натертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8318,'Убрать форму с мясом в духовку и запекать при 180 градусах на протяжении 50 минут .',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8318,'Подаются грудки куриные под сметанно-чесночным соусом в горячем виде с любимым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8319,'Включить духовку, прогреть ее до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8319,'Растереть сахар с подсоленными яйцами и ванилином, добавить масло, тщательно все смешать, влить йогурт, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8319,'В полученную смесь небольшими порциями всыпать муку и разрыхлитель, вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8319,'Подготовить формочки, смазать маслом, заполнить тестом, поместить их в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8319,'Ванильно-йогуртовые маффины будут готовы через полчаса, достать, дать остыть, присыпать через ситечко сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'Сварить в чуть подсоленной воде спагетти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'В яйца добавить перец, подсолить, взбить.','https:https://st.vkuso.ru/data/cache/thumb/76/01597e253327076_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'Добавить измельченный с зеленью чили.','https:https://st.vkuso.ru/data/cache/thumb/33/51bc0fffe75d733_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'Осторожно перемешать с пастой.','https:https://st.vkuso.ru/data/cache/thumb/34/1514e69c2037134_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11504,'Кефир взбить с яйцом, солью, сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'Разогреть в сковороде с тефлоновым покрытием масло, вылить смесь, готовить фриттату из спагетти с перцем чили под крышкой на малом огне до образования золотистой корочки с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/18/b8ea76751e28418_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8320,'На плоской тарелке разложить салатные листья, побрызгать их смесью масла и уксуса, уложить фриттату, подать к столу пока не остыла.','https:https://st.vkuso.ru/data/cache/thumb/37/72c066379f4e437_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Нарезать картофель на небольшие кубики.','https:https://st.vkuso.ru/data/cache/thumb/1a/e8264c63bb0ec1a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Нарезать морковь на небольшие кубики.','https:https://st.vkuso.ru/data/cache/thumb/18/0985d934d2dff18_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Грудку – на средние и обжарить 7 минут на масле.','https:https://st.vkuso.ru/data/cache/thumb/7f/0c43a0f23353f7f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'В кипящую воду положить кубики овощей, проварить 20 минут, всыпать мясо, варить 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Приправить картофельно-куриный суп с плавленым сыром перцем, лавровым листом, солью, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Положить в конце варки охлажденные сырки, порезанные на кубики, размешать до полного их растворения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8321,'Добавить в суп мелко порубленную зелень, проварить около 5 минут, снять с плиты, дать перед подачей немного постоять под крышкой.','https:https://st.vkuso.ru/data/cache/thumb/6f/4ab116fbea3d46f_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8322,'В пластмассовую бутылку объемом 1,5 литра любым удобным способ всыпать муку, соль и сахар, встряхнуть, чтобы все перемешалось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8322,'Далее влить в бутылку с сухой смесью яйца, кефир (молоко) и растительное масло, закрутить крышку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8322,'Тщательно встряхивать бутылку, пока ее содержимое хорошенько не перемешается.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8322,'Сковородку смазать растительным маслом и разогреть, выливать тесто прямо из бутылки, наклоняя сковородку в стороны для равномерного распределения теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8322,'Испечь желаемое количество блинов на молоке или кефире из бутылки  обычным способом, подавать готовые блины со сметаной, маслом или любой другой добавкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8323,'Измельчить блендером все ингредиенты заправки.','https:https://st.vkuso.ru/data/cache/thumb/8f/ba859080985ed8f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8323,'Переложить 1\3 в глубокую миску, добавить лук и листовую зелень, подсолить, перемешать, выложить на салатную тарелку.','https:https://st.vkuso.ru/data/cache/thumb/5a/a966f22d7c4d65a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8323,'Сверху положить кружочки помидора, присыпать измельченными маслинами, полить их 1\3 заправки, положить моцареллу, полить остатками заправки.','https:https://st.vkuso.ru/data/cache/thumb/fb/53f2a8b7cd2e2fb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8323,'Приправить салат с сыром моцарелла под травяной заправкой свежемолотым черным перцем, посолить, по краю разложить ветчину.','https:https://st.vkuso.ru/data/cache/thumb/0c/3925f6cb4cc5b0c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8324,'Из всех ингредиентов замесить не липнущее к рукам тесто, прикрыть тканью, дать созреть треть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8324,'Посыпать стол мукой. Из половины теста раскатать пласт, нарезать прямоугольники, в середине каждого сделать прорезь, продеть в нее один край и слегка растянуть, также поступить со второй половиной теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8324,'Хорошо разогреть масло, обжарить кефирный хворост к чаю с 2 сторон. Готовую выпечку присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8325,'Поломать шоколад на небольшие кусочки, поместить вместе с молоком (сливками) и маршмеллоу в кастрюльку с толстым дном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8325,'Довести на малом огне все до жидкого состояния, периодически помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8325,'Шоколадную глазурь остудить около четверти часа и покрыть ею торт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Порезать и обжарить на масле ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Лук с перцем порезать на кубики, перемешать с ветчиной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Влить молоко, добавить муку, перемешать, вбить яйца, поперчить, посолить, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Форму застелить бумагой, смазанной маслом, заполнить яичной смесью, поставить в прогретую до 180 градусов духовку на четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Достать, присыпать крупной сырной стружкой, отправить яичный рулет с ветчиной, перцем и сыром еще на 5 минут в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8326,'Запеканку осторожно завернуть в трубочку, используя бумажную подложку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Прогреть желтки на водяной бане, постепенно всыпая сахар и взбивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Когда сахар растворится влить в тягучий крем алкоголь, убрать с водяной бани.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Нагреть молоко практически до кипения, убрать с плиты, осторожно влить тоненькой струйкой (постоянно перемешивая) в желтковую массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Полученную смесь поместить в кастрюлю, проварить при среднем нагреве до консистенции сметаны, постоянно мешая, чтобы смесь не пригорела (кипеть не давать!), убрать с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Поместить крем на водяную баню (холодную), дать хорошо остыть, поставить в холодильник, охладить до +5 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Охлажденные сливки взбить до появления мягких устойчивых пиков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Приготовить в блендере банановое пюре с лимонным соком. Перемешать хорошо охлажденный крем и пюре, добавить сливки, очень осторожно перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Фризер заполнить полученной массой, дальше готовить сливочно-банановое мороженое с коньяком согласно инструкции к аппарату.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8327,'Переложить готовое мороженое в контейнер, поставить в морозилку до полного застывания примерно на 3-4 часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Крупно нарезать очищенные грибы, обжарить их на протяжении 5 минут в разогретом сливочном масле (2 ст. л.) на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Образовавшуюся в сковородке жидкость перелить в какую-нибудь емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Грибы посолить, добавить мелко нарезанный очищенный лук, еще 2 ст. л. сливочного масла и жарить все вместе с еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Тщательно перемешать сметану с мукой, не спеша влить в массу жидкость от грибов, добавить черный перец и соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'В сковороду с грибами перелить получившийся соус и, периодически помешивая, потушить грибы на слабом огне 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Сыр мелко натереть, кокотницы смазать чесноком и выложить в них обжаренные грибы с соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8328,'Посыпать грибной жульен подготовленным сыром и убрать на 7-8 минут в разогретую до 200 градусов духовку до образования корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'Для начинки порезать помидоры на кружочки, брынзу измельчить вилкой, если используете творог, то его слегка подсолить, добавить измельченную зелень, раздавленный прессом чеснок, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'Для приготовления теста растворить в кипятке сахар с солью, влить масло, разболтать, перемешать с мукой, вымесить достаточно эластичное тесто в шарик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'Разделить его на 2 части, раскатать в пласт толщиной примерно в полсантиметра, сначала одну, потом другую.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'На один пласт разложить нарезанные помидоры с расстоянием примерно в 3 см, прикрыть их остальной начинкой, а сверху – другим пластом теста и чуть прижать ладонями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'Взять стакан или кружку, накрыть каждый кусочек помидора и вырезать пирожки, дополнительно залепить края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8329,'Обжарить пирожки «Бомбочки» с брынзой в большом количестве сильно разогретого масла с одной и другой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8330,'Перемешать в глубокой миске молоко с яйцами, всыпать сахар, перемешать, просеять в смесь муку, размешать до исчезновения комков, влить масло, перемешать, добавить соду и еще раз перемешать, заварить смесь закипевшей водой, тщательно перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8330,'Прогреть сковороду для блинов, смазать жиром, вылить тесто, вращая сковороду распределить его по всей поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8330,'Обжарить заварные блинчики на молоке к завтраку с одной стороны, перевернуть лопаточкой и обжарить с другой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8331,'Подготовить мясо, порезать на средние кусочки вместе с салом, прокрутить на мясорубке, фарш поперчить, подсолить, добавить в него сухие травы и кубики свинины, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8331,'Завязать один конец оболочки для колбасы узлом, заполнить фаршем, не доходя 5 сантиметров до края, плотно завязать, повторить все для остальных колбас, полчаса дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8331,'Переложить домашнюю колбасу с итальянскими травами на противень, налить на него немного воды, поставить в прогретую духовку (200 градусов) минут на 30-45.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8332,'Кефир влить в миску, всыпать к нему соду и хорошенько перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8332,'Вбить в кефир 1 целое яйцо и 1 желток, всыпать муку (если кефир жидковат, муки можно взять чуть больше, не забыв добавить немного соды) и перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11504,'Всыпать дрожжи и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Поставить опару из четверти стакана подогретой воды, дрожжей, чайной ложки сахара и муки, дать смеси подняться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Перемешать растопленное масло с парой желтков и молоком, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Объединить смесь с опарой и остатками муки, подсолить, всыпать сахар, вымесить тесто, дать ему подняться, обмять, дать еще раз подняться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Разделить шар теста на несколько частей, каждую раскатать полоской по 5 см толщиной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Обернуть каждую вокруг трдла или скалки, смазать их белком, обвалять в молотом миндале с корицей и сахаром.','https:https://st.vkuso.ru/data/cache/thumb/d8/e1f2ed36d3b03d8_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8333,'Выпекать чешские миндальные булочки около трети часа до зарумянивания, подавать к столу горячими.','https:https://st.vkuso.ru/data/cache/thumb/34/3f2a02e9862b034_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8334,'Залить молоком желатин, дать постоять 10 минут, аккуратно подогреть, дать желатину полностью растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8334,'В сотейнике перемешать сливки с сиропом, ванилью и сахарной пудрой.','https:https://st.vkuso.ru/data/cache/thumb/aa/2af39a3769072aa_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8334,'Добавить желатин.','https:https://st.vkuso.ru/data/cache/thumb/83/aa69bdf9c154b83_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8334,'Перелить в креманку, дать итальянскому ягодному десерту панна-котта застыть.','https:https://st.vkuso.ru/data/cache/thumb/67/67d1e66da6b9c67_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8335,'Нашинковать мелко лук и чеснок, помидоры и перец болгарский порезать на небольшие кусочки, обжарить все пару минут, добавить фарш, перемешать, жарить до готовности, всыпать порубленную петрушку и перец, влить бульон, приправить специями, перемешать, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8335,'Дрожжи залить теплой водой, добавить соль и сахар, перемешать, влить в муку, вымесить однородное тесто, дать постоять примерно 40 минут. Из теста раскатать тонкие лепешки, нанести слой фарша-начинки, выпекать при температуре 240 градусов в течение 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Натереть на терке отварной картофель, твердый сыр и ветчину (колбасу), переложить все в большую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Добавить в миску с подготовленными ингредиентами измельченный зеленый лук и сырые яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Ингредиенты поперчить, при желании посолить и хорошенько перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Всыпать в ту же миску муку и снова тщательно перемешать ее содержимое, чтобы получилась однородная масса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Отщипнуть от массы кусочек, придать ему форму биточка и обвалять в муке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Сделать желаемое количество биточков и обжарить их все до готовности с двух сторон на сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8336,'Подавать картофельные биточки с ветчиной и сыром на завтрак со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8337,'Сварить крепкий кофе, остудить, вылить в чашу блендера, добавить молоко и мороженое, перемешать на средней скорости до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8337,'Разлить коктейль «Coffee Milkshake» по высоким бокалам, влить шоколадный сироп, при желании оформить еще и шариком мороженого с шоколадной стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8338,'Порезать баклажаны на кружочки или небольшие кусочки, присыпать солью, дать постоять, обсушить салфеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8338,'Каждый кусочек обвалять в крахмале, обжарить на сковороде с большим количеством масла с двух сторон, выложить на бумажное, сложенное в несколько слоев полотенце, переложить на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8338,'В другой сковороде в небольшом количестве разогретого масла обжарить имбирь, добавить чеснок, болгарский перец, уксус и соевый соус, перемешать, залить баклажаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8338,'Присыпать сверху белым перцем, кунжутом и сахаром, добавить зеленый лук, перемешать, подать к столу как самостоятельное блюдо или можно вместе с рисом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8339,'Орехи и семечки порубить в блендере до состояния крупной крошки, финики порезать на кусочки, сделать из очень спелого банана пюре, смешать все с овсяными хлопьями в однородную массу, добавить сок лимона, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8339,'Противень застелить пекарской бумагой, смазать маслом, выложить массу, разровнять в сантиметновый слой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8339,'Запекать домашние мюслевые батончики с бананом не менее 20 минут при температуре 180 градусов. После остывания разрезать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8340,'Перемешать муку с мягким маргарином или маслом руками в маслянистую крошку, добавить желток, сметану, вымесить тесто, поместить тесто в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8340,'Для приготовления печенья отрезать немного теста, раскатать, нарезать ножом для пиццы на треугольники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8340,'Положить белок в одну миску, в другую всыпать сахар, каждое печенье обмакнуть только одной стороны в белок, а потом в сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8340,'Переложить сухой стороной на присыпанный мукой противень, выпекать при 180 градусах до изменения цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8341,'Грибы обработать, порезать на пластинки, чеснок с луком мелко нашинковать, зелень и мяту порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8341,'Обжарить до прозрачности лук, потом добавить чеснок с грибами, петрушкой и мятой, поперчить, чуть присолить, тушить четверть часа на малом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8341,'Отдельно потушить 5 минут в разогретом масле тимьян.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8341,'Телятину помыть, обсушить, порезать на 4 куска, поперчить, обжарить с тимьяном с двух сторон по 3 минуты, сделать минимальный нагрев, жарить еще 4 минуты. Снять телятину со сковороды и держать в тепле, например, завернуть в фольгу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8341,'В сковороду с соком от мяса налить вино, довести до кипения, положить грибы, овощи и зелень. Телятину разложить на тарелки вместе с грибами и соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Муку просеять и перемешать с разрыхлителем, какао, сахаром и пряностями.','https:https://st.vkuso.ru/data/cache/thumb/0a/bdbfff3c12d300a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Мелко поломать шоколад (небольшое количество оставить крупными).','https:https://st.vkuso.ru/data/cache/thumb/77/8bf4034751e3e77_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Перемешать миксером йогурт с яйцами и маслом, объединить с мучной смесью, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/fe/5e30b51b33aabfe_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Всыпать шоколад, перемешать еще раз.','https:https://st.vkuso.ru/data/cache/thumb/cb/47bbb769034a6cb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Форму выстлать пергаментом, смазать маслом, присыпать слегка мукой, заполнить тестом.','https:https://st.vkuso.ru/data/cache/thumb/c1/644fc95d045b6c1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Выпекать пряничный шоколадный пирог около часа в духовке с температурой 175 градусов.','https:https://st.vkuso.ru/data/cache/thumb/2a/7816fc01c8dd02a_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8342,'Для приготовления глазури высыпать в глубокую миску треть стакана сахарной пудры, по чайной ложке влить лимонный сок, перемешать до образования однородной густой массы, остывший пирог покрыть глазурью, оформить мандариновыми дольками, дать застыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8343,'Мелкими кубиками порезать филе 1 сельди, сыр крупно потереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8343,'Мелко нарезать промытый зеленый лук (маринованный репчатый лук) и укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8343,'Переложить в большую миску все подготовленные ингредиенты, добавить майонез и тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8343,'Готовые тарталетки наполнить получившейся начинкой и выложить корзиночки с сельдью и сыром на большое сервировочное блюдо',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8344,'Взбить сахар и яйца, добавить масло и муку с разрыхлителем, перемешать до получения однородного теста.','https:https://st.vkuso.ru/data/cache/thumb/51/2a7c639e6058e51_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8344,'Бананы порезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8344,'Из взбитого яйца со сметаной, мукой и сахаром приготовить заливку.','https:https://st.vkuso.ru/data/cache/thumb/cb/f7592aa0ac79acb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8344,'Переложить тесто в форму, сформовать бортики, уложить банан, вылить сверху яичную смесь.','https:https://st.vkuso.ru/data/cache/thumb/4d/8db23feb3782d4d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8344,'Выпекать нежный банановый пирог со сметанной заливкой треть часа в прогретой заранее до 180 градусов духовке.','https:https://st.vkuso.ru/data/cache/thumb/a3/3f600bb6d7640a3_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8345,'Подготовить мясо, помыть, порезать на куски среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/61/80c970cfd67ef61_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8345,'Подрумянить в небольшом количестве масла, чуть присолить.','https:https://st.vkuso.ru/data/cache/thumb/dd/71caec74f985bdd_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8345,'Нашинковать лук.','https:https://st.vkuso.ru/data/cache/thumb/f5/2895d53d3d05af5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8345,'Переложить мясо в кастрюльку с толстым дном, залить небольшим количеством воды, всыпать лук, тушить минут 40.','https:https://st.vkuso.ru/data/cache/thumb/4b/3b3326b77b7874b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8345,'Добавить молотый перец, соль, порубленный мелко чеснок. Протушить свинину с луком и чесноком 10 минут, подать с любимым гарниром, посыпать верх порубленной зеленью.','https:https://st.vkuso.ru/data/cache/thumb/47/4d25d5eab0bf747_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8346,'Отварить до готовности очищенный картофель, яйца и куриную грудку, на сковороде с растительным маслом обжарить грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8346,'Залить чернослив на 15 минут кипятком, после чего порезать его средними кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8346,'Далее собрать салат «Венеция», выкладывая продукты слоями в разъемную форму: чернослив, куриное мясо, майонез, картофель, майонез, обжаренные грибы, яйца, майонез, крупно натертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8346,'Верх салата украсить свежим огурцом, натертым на средней терке или нарезанным тонкими колечками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8347,'Порубить в мелкую крошку кубики охлажденного масла с мукой, вбить яйцо, вымесить крутое тесто, поставить его в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/93/39b315b46fdfe93_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8347,'Перемешать творог с печеной тыквой, измельченной в пюре','https:https://st.vkuso.ru/data/cache/thumb/0e/e545f35a72f500e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8347,'Всыпать сахар, влить сливки, добавить какао, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/73/e9bb5f54a51f773_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8347,'Достать тесто, раскатать в пласт, переложить в форму, сделать бортики.','https:https://st.vkuso.ru/data/cache/thumb/bc/a167a9b79c378bc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8347,'Разложить тыквенную начинку, присыпать апельсиновой цедрой. Шоколадно-творожный чизкейк с тыквой выпекать при температуре 200 градусов около получаса. Выпечку можно есть и горячей, и холодной.','https:https://st.vkuso.ru/data/cache/thumb/50/0ec9df58de34850_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Довести до кипения бульон, положить в него нарезанный картофель и морковь, варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Обжарить на масле нашинкованный лук и часть моркови до мягкости.','https:https://st.vkuso.ru/data/cache/thumb/a1/e55d40b16df84a1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Сырок порезать на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/12/9cff76645fefa12_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Вынуть шумовкой часть картофеля и моркови, оставшиеся овощи измельчить погружным блендером или пестиком, вернуть отложенные овощи в суп.','https:https://st.vkuso.ru/data/cache/thumb/b7/9ba2d56a24816b7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Положить в кастрюлю сырок, перемешать, чтобы он полностью расплавился, добавить в куриный суп с плавленым сырком и картофелем зажарку. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/94/343c64b110f3094_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8348,'Разлить суп по тарелкам, украсить веточкой зелени, подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/e5/fd509230374e9e5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8349,'Вымесить из творога с маслом, мукой, яйцом, солью и разрыхлителем нежное тесто, положить его в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8349,'Сварить в сковороде карамель из смеси сахара с водой, всыпать яблоко, порезанное на кубики, перемешать, варить около 3 минут, снять с плиты, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8349,'Охлажденное тесто достать из холодильника, раскатать, вырезать любой подходящей формой круги, поместить в центр начинку, присыпать корицей, сформовать творожные пирожки с яблочной начинкой и корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8349,'Переложить пирожки на противень, смазать верх сладким молоком, выпекать полчаса при температуре 180 градусов. Готовую и чуть остывшую выпечку присыпать смесью корицы и сахарной пудры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8350,'В однородное тесто смешать творог, сахар и манную крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8350,'Мокрыми руками отщипнуть от теста кусок и сделать из него лепешку, в центр которой положить немного вареной сгущенки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8350,'Сверху закрыть начинку еще одной тестяной лепешкой и сформовать сырник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8350,'Проделать все то же самое с остальным тестов и слегка обвалять каждый сырник в муке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8350,'Обжарить сырники на манке с вареной сгущенкой на сковородке до подрумянивания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Окатить печень кипятком и сразу охладить, удалить пленку, залить на час молоком, затем порезать на куски сантиметровой толщины, но не солить, запанировать в муке.','https:https://st.vkuso.ru/data/cache/thumb/0c/d3655c9d393670c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Обжарить печень в сильно разогретом масле по полторы минуты с каждой стороны.','https:https://st.vkuso.ru/data/cache/thumb/7f/72536b48386407f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Переложить куски на бумажное полотенце, обсушить от масла, дать остыть, мелко натереть.','https:https://st.vkuso.ru/data/cache/thumb/6e/5447bc82617616e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Сварить рис, окатить его холодной водой.','https:https://st.vkuso.ru/data/cache/thumb/fe/3a9a1093fcd23fe_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Яйца отварить, разделить на желток и белок и натереть на мелкой терке.','https:https://st.vkuso.ru/data/cache/thumb/df/f2e7d54ca281ddf_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Сыр натереть на мелкой терке.','https:https://st.vkuso.ru/data/cache/thumb/a3/bc62ffe1cdf88a3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Открыть и сцедить кукурузу.','https:https://st.vkuso.ru/data/cache/thumb/bb/cae8d07ee4f7cbb_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8366,'Накрыть второй лепешкой, чуть-чуть прижать. Нагреть сэндвичи по несколько минут с каждой стороны. Так же приготовить другие сэндвичи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Приготовить майонез из взбитых венчиком с сахаром, лимонным соком, горчицей и солью желтков. Влить в смесь, продолжая взбивать, тоненькой струйкой масло, взбивать до белой однородной массы, подержать майонез час на холоде.','https:https://st.vkuso.ru/data/cache/thumb/94/b64a37939f7db94_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8351,'Выложить салат на плоское блюдо слоями: печень, рис, далее кукуруза с сыром, белки яиц, желтки. Слои сыра, печени и риса смазать майонезом.','https:https://st.vkuso.ru/data/cache/thumb/22/1fc436706930922_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8352,'Смазать ободки бокалов соком лайма, обмакнуть в сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8352,'Положить в чашу миксера малину, добавить лаймовый сок и сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8352,'Влить ром, ликер, добавить 1 чашку ледяной стружки, хорошо взболтать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8352,'Разлить малиновый Дайкири с ликером по бокалам через ситечко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8353,'Порезать промытое мясо на длинные полоски.','https:https://st.vkuso.ru/data/cache/thumb/f2/b6c32223f250cf2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8353,'Обжарить в небольшом количестве разогретого масла, залить водой так, чтобы только закрыть мясо, подсолить, тушить около часа.','https:https://st.vkuso.ru/data/cache/thumb/fa/bd42bee1c85f7fa_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8353,'Обжарить на растительном масле полукольца лука и грибы.','https:https://st.vkuso.ru/data/cache/thumb/a7/ce7dcedecfa13a7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8353,'Смешать с мягким мясом. Готовить тушеную говядину с шампиньонами и луком еще 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/da/534703aa2a435da_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Растопить шоколад любым удобным способом.','https:https://st.vkuso.ru/data/cache/thumb/b4/825058ddb8702b4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Маршмеллоу размягчить в микроволновке (хватит несколько секунд).','https:https://st.vkuso.ru/data/cache/thumb/67/6aa5b34b5c33d67_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Перемешать оба компонента, влить сливки, ликер или сок.','https:https://st.vkuso.ru/data/cache/thumb/d0/9041f7534736cd0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Добавить масло, хорошо вымешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/bd/5a886023a7b47bd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Полученную массу переложить в чашу миксера, всыпать сахарную пудру, размешать.','https:https://st.vkuso.ru/data/cache/thumb/c2/869f127d3a3a3c2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Застелить стол фольгой или пленкой, смазать маслом, переложить на нее мастику из горького шоколада и маршмеллоу, раскатать по размеру торта.','https:https://st.vkuso.ru/data/cache/thumb/9d/92d8626272c119d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8354,'Остатки можно обернуть пленкой и убрать в холодильник, перед использованием положить в микроволновку на 10-20 сек в режиме «разморозка».','https:https://st.vkuso.ru/data/cache/thumb/28/a28dc7c0a1f0c28_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Влить воду в небольшую кастрюльку, дать ей закипеть, после чего сделать минимальный огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Добавить в воду масло, чуть-чуть соли, быстро ввести муку и перемешивать, пока тесто не перестанет прилипать к стенкам посуды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Получившейся массе дать немного остыть, затем вбить 1 яйцо и хорошо все перемешать, затем порциями ввести оставшиеся яйца: должно получиться очень густое тесто, которое не будет стекать с ложки и не растечется по пергаменту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Духовку разогреть до 200 градусов, противень выстелить пекарской бумагой, кондитерский мешок наполнить готовым тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Выдавить на подготовленный противень тесто и отправить заготовки на 20 минут в разогретую духовку (температура должна быть именно 200 градусов!).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'По истечении отведенного времени температуру духовки снизить до 170-180 градусов и выпекать эклеры, не открывая духовку, до образования золотисто-румяного цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Готовым пирожным дать постоять в закрытой духовке 5-10 минут, затем еще столько же времени они должны постоять в открытой духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Для крема взбить при помощи миксера творожную массу с фруктовым йогуртом до однородной воздушной массы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Достать из духовки заготовки и наполнить их получившимся кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8355,'Подавать пирожное эклеры с йогуртно-творожным кремом на большом сервировочном блюде, присыпав при желании сахарной пудрой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'Все ингредиенты для крема (кроме масла) поместить в сотейник с толстым дном и антипригарным покрытием, проварить, помешивая на малом огне до сгущения, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'Перемешать ингредиенты для теста (кроме муки), проварить четверть часа на малом огне, снять с плиты, всыпать муку, тщательно перемешать, дать тесту полчаса остыть, разделить на 4 равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11504,'Тесто вымесить, оставить в тепле на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'Каждый колобок раскатать в прямоугольник примерно 18х25 см, перемеместить на противень (предварительно выстлать пергаментом), намотав на скалку, выпекать до румяного цвета при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'Добавить по частям в крем сливочное масло, постоянно продолжая взбивать. Коржи положить друг на друга, подровнять края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'На первый корж положить 1\2 крема, накрыть другим коржом, смазать слоем яблочного джема. Накрыть третьим коржом и смазать остатками крема, на него уложить последний корж.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8356,'Верх медового торта с яблочным джемом оформить шоколадной глазурью из масла и шоколада, растопленного на водяной бане, бока присыпать измельченными в крошку обрезками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8357,'Перемешать  муку, сахар, разрыхлитель, масло до образования маслянистой крошки, добавить к смеси яйцо, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8357,'Стол притрусить мукой, раскатать в пласт, переложить на противень, сделать бортики, убрать на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8357,'Достать противень, тесто в нескольких местах наколоть слегка вилкой, поместить в прогретую до 200 градусов духовку на 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8357,'Для приготовления начинки в миксере смешать творог, яйцо, растопленное масло, сахар, крахмал, муку, ванильный сахар и цедру одного лимона. Заполнить основу творожным кремом, разложить на него половинки слив срезом вверх.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8357,'Для присыпки пирога перемешать муку, сахар, корицу, ванильный сахар и охлажденное масло. Посыпать пирог крошкой и отправить на 20 минут в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Срезать у кочана капусты низ и отправить в кипящую воду. Через минуту листья начнут постепенно отделяться от кочана. Выбрать 15 больших и хороших листиков, положить на салфетки, чтобы остыли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Обжарить на оливковом масле чеснок, лук, сельдерей до золотистого оттенка. Положить на сковороду фарш, обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Добавить томатную пасту, порезанные помидоры, налить чуть-чуть воды. Посыпать специями и измельченным чили. Тушить 5-10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Добавить по вкусу 2 вида уксуса, насыпать сахар и соль. Тушить до готового состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Соединить рикотту, мускатный орех, молотый перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Выложить лазанью. Положить слой фарша, на него листья капусты, сверху рикотту. В такой последовательности выкладывать слои, пока не закончится фарш. Готовить 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Спустя 20 минут от начала готовки, достать лазанью, посыпать тертой моцареллой. Отправить в духовку еще на 15 минут. Достать, чуть остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8358,'Посыпать лазанью из капустных листьев с рикоттой свежим измельченным орегано, побрызгать оливковым маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Просеять муку и соль.','https:https://st.vkuso.ru/data/cache/thumb/5b/f702e4c02a8695b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Взбить яйца и молоко до однородной смеси.','https:https://st.vkuso.ru/data/cache/thumb/4b/abc2cb1ba9a114b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Смешать жидкую смесь и сухую.','https:https://st.vkuso.ru/data/cache/thumb/a6/748c6f970816ba6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Налить 40 грамм растопленного масла, размешать. Отправить тесто на несколько часов в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/d6/c3d5c562a8ef1d6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Обжарить блинчики на сливочном масле.','https:https://st.vkuso.ru/data/cache/thumb/19/687ef03ef128519_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Намазать ореховой пастой Nutella. Сверху выложить кусочки клубники.','https:https://st.vkuso.ru/data/cache/thumb/5e/42862a624bd995e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8359,'Сложить блины вчетверо и подавать крепы с пастой Nutella и клубникой.','https:https://st.vkuso.ru/data/cache/thumb/93/4f9ffeb21617f93_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Перемолоть фундук и миндаль при помощи блендера.','https:https://st.vkuso.ru/data/cache/thumb/c8/a1f49f8b5e2d3c8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Крупно натереть тыкву. Мелко натереть цедру апельсина. Разделить белки и желтки, растереть сахар с желтками. Положить их к тыкве, добавить цедру, орехи. Насыпать соду, размешать.','https:https://st.vkuso.ru/data/cache/thumb/c2/caa306560064ac2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Выжать апельсиновый сок. Насыпать муку, размешать. Взбить белки. Медленно вести белки в тесто.','https:https://st.vkuso.ru/data/cache/thumb/d8/20b6e0f7d113dd8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Намазать формочку сливочным маслом. Вылить в форму тесто. Готовить в духовке 45-50 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/da/8b0462271ed55da_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8367,'Нагреть духовку до 180 градусов. Соединить в небольшой емкости цедру апельсина и специи.','https:https://st.vkuso.ru/data/cache/thumb/f9/971146d97813cf9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Достать готовый пирог из формы, подождать, пока полностью остынет на решетке. Растопить молочный шоколад удобным способом.','https:https://st.vkuso.ru/data/cache/thumb/1f/1453ac1fde9b21f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Распределить шоколад по пирогу. Можно сделать узор.','https:https://st.vkuso.ru/data/cache/thumb/d3/929d192b5140cd3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8360,'Порезать тыквенно-ореховый пирог в молочном шоколаде на кусочки и подавать.','https:https://st.vkuso.ru/data/cache/thumb/27/d69b0fc46577427_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'В кастрюлю налить молоко и поставить на средний огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'Всыпать в молоко, все время его мешая, сахар и соль, дать молоку закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'Как только молоко закипит, влить в него кефир и мешать, пока содержимое кастрюли не свернется.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'Получившуюся массу откинуть на марлю, завязать ее на узел и подвесить на 15 минут над раковиной, чтобы стекла сыворотка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'В отдельной емкости тщательно взбить яйцо с небольшим количеством лимонной кислоты (на кончике ножа).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'В яичную массу переложить получившийся творог и взбить все до однородного пышного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8361,'Сыр «Филадельфия» в домашних условиях готовится просто и далее используется по желанию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8362,'Положить в блендер все ингредиенты, измельчить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8362,'Отправить смесь в холод на 30-40 минут для охлаждения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8362,'Сделать шарики, обвалять в какао-порошке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Приготовить рис, как написано в инструкции. Слить воду, отставить рис в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Измельчить в кухонном комбайне томаты, чтобы получился соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'В средней сковороде нагреть 2 большие ложки масла. Положить чеснок, порезанный красный перец, готовить 30 секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Вылить в сковороду измельченные томаты, убавить огонь, готовить 20 минут. Посыпать перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Куриные окорочка отварить и разделать на небольшие кусочки. Насыпать в емкость муку, перец, соль. Хорошо обвалять куриные окорочка в данной смеси.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Нагреть масло на другой сковороде. Положить грудки, обжаривать по 5 минут с каждой стороны. Переложить из сковороды, отставить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'В сковороду с томатами налить сливки, готовить 5 минут. Попробовать на вкус, если необходимо, посыпать приправами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8363,'Насыпать в томатную смесь рис, перемешать. Положить туда же грудки. Подавать рис с куриными окорочками и томатами, украсив свежим базиликом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Замочить нут на 8-10 часов.','https:https://st.vkuso.ru/data/cache/thumb/0b/d065d00f917a50b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Когда он разбухнет и впитает воду, положить нут в блендер. Добавить измельченный лук, чуть-чуть воды. Измельчить смесь, посыпать солью.','https:https://st.vkuso.ru/data/cache/thumb/b1/dc3c89c698d1ab1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Добавить булгур, измельченный чеснок и кинзу. Перемешать, отставить, чтобы булгур стал мягче.','https:https://st.vkuso.ru/data/cache/thumb/96/880fce985839d96_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Добавить разрыхлитель, чили, растертую зиру. Размешать, добавить чуть-чуть муки.','https:https://st.vkuso.ru/data/cache/thumb/72/26fcad77bf8e572_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Сделать шарики. Обвалять в муке.','https:https://st.vkuso.ru/data/cache/thumb/cb/a3f6463ac2d0ccb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Нагреть масло в глубокой сковороде. Опустить будущий фалафель в сковороду при помощи шумовки, готовить несколько минут до золотистости.','https:https://st.vkuso.ru/data/cache/thumb/46/e18e6ac458dda46_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8364,'Выложить фалафель с булгуром и кинзой на чистое полотенце, чтобы избавиться от жира.','https:https://st.vkuso.ru/data/cache/thumb/85/1e66a0e60f05a85_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8365,'Для соуса смешать мед, соль, тимьян, измельченный лук-шалот и молотый красный перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8365,'Подготовленное филе форели переложить в форму (блюдо) для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8365,'Смазать рыбу получившимся медовым соусом и запекать под нагретым бройлером (нагреватель в верхней части духовки) в течение 10-12 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8365,'Подается форель в меду, запеченная в фольге, с любимым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8366,'Порезать шампиньоны на тоненькие пластины. Потереть сыр. Почистить от семян перец, тоненько порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8366,'Положить в растопленное масло порезанные грибы, жарить 3-5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8366,'Положить кукурузную тортилью на горячую сковороду, намазанную растительным маслом. На тортилью положить сыр, сверху грибы, потом перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8367,'Посыпать специями и цедрой, перемешать, чтобы орешки были покрыты смесью со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/58/4f6aedcfd844e58_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8367,'Постелить пергамент на противень, положить орехи.','https:https://st.vkuso.ru/data/cache/thumb/e6/5cdb51b1be6ace6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8367,'Готовить кешью со специями в апельсиновом сиропе 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/57/ad7848852c1e557_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'Подготовить ингредиенты. Разрезать окорочка пополам. Соединить корицу, соль, мускатный орех, перец. Обвалять курицу в специях, отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'Измельчить лук, чеснок порезать поперек пополам. Положить шафран в горячий бульон (воду). Отставить, чтобы настоялся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'На большом огне, на оливковом масле в сковороде с антипригарным покрытием обжарить мясо, чтобы появилась золотистая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'Поставить другую сковороду с толстым дном (например, казан). Обжарить лук, чтобы он стал мягким, но не зажарился.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'Курицу переложить в казан на слой из лука. Сделать минимальный огонь. Положить к мясу веточку шалфея, чеснок, налить бульон или воду с шафраном. Положить палочку корицы, разломанную пополам. Накрыть крышкой, готовить на маленьком огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'В это время подготовить яблоки: почистить от кожуры, вырезать сердцевину, порезать на дольки. Растопить сливочное масло. Положить мед, выложить яблоки. Увеличить огонь. Перемешать. Яблоки должны карамелизоваться, помешивать периодически, пока яблоки не приобретут карамельный оттенок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8368,'Приготовленные яблоки положить к курице. Готовить все на тихом огне под крышкой около 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Разрезать баклажаны пополам вдоль, осторожно убрать мякоть при помощи ложки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Порезать мякоть на маленькие кубики, посыпать солью, оставить на 15 минут. Промыть мякоть под проточной водой, отжать, подсушить полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Почистить лук, кабачок, порезать овощи на маленькие кубики. Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Налить на сковороду оливковое масло, обжарить овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Отдельно чуть-чуть взбить яйцо, налить сливки, положить порезанную на кубики брынзу, посолить, поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8369,'Наполнить баклажаны поджаренными овощами, сверху полить сливочной смесью с сыром и отправить в разогретую до 200 градусов духовку на 20-30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'Нарезать промытое мясо курицы на порционные куски и замариновать их в течение получаса в соевом соусе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'Далее в миску с мясом добавить кетчуп и горчицу, вбить яйца, все содержимое миски поперчить и посолить по вкусу, хорошенько перемешать и убрать в сторону на 1 час, чтобы курица еще промариновалась.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'В сковородку влить растительное масло, разогреть его и выложить подготовленные кусочки курицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'Обжаривать мясо на среднем огне со всех сторон, пока на нем не образуется золотистая корочка, после чего посыпать его молотой паприкой и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'Накрыть сковородку крышкой и на маленьком огне жарить мясо в течение 20 минут, не забывая помешивать (при необходимости во время жарки можно влить немного воды).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8370,'Готовое куриное мясо в пикантном маринаде подается порционно вместе с картофельным пюре, овощами или рисом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8371,'С помидора снять кожуру. Разрезать на две части, раздавить в небольшой емкости, добавить оливковое масло и измельченный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8371,'Багет разрезать вдоль, но не разрезать до конца. Намазать половинки внутри томатным соусом, в середину положить хамон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8372,'Почистить и порезать картофель, отварить. Мелко нарезать отваренный картофель.','https:https://st.vkuso.ru/data/cache/thumb/e3/35d70218b1a05e3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8372,'Яйца отварить вкрутую, нарезать кольцами.','https:https://st.vkuso.ru/data/cache/thumb/74/d787a206567eb74_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8372,'Петрушку и красный лук мелко нарезать.','https:https://st.vkuso.ru/data/cache/thumb/16/e50334ea77be516_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8372,'Заправить салат смесью майонеза и сметаны. Посыпать специями. Перемешать картофельный салат с красным луком и яйцами, отправить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/9b/2bb7d837532f59b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Свежий огурец разрезать вдоль пополам, затем – тонкими ломтиками. Крупный стебель сельдерея также нарезать тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'Нагреть масло, чтобы оно стало жидким или оставить его при комнатной температуре, чтобы оно стало мягким. Соединить подготовленное масло с сахаром, растереть.','https:https://st.vkuso.ru/data/cache/thumb/e3/da3a71075fdbce3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'Добавить яйца, перемешать. Чтобы ускорить процесс, можно использовать блендер.','https:https://st.vkuso.ru/data/cache/thumb/0a/0626d21243aad0a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'Добавить крахмал. Он сделает вафли песочными и хрустящими.','https:https://st.vkuso.ru/data/cache/thumb/aa/642f50f52617caa_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'Насыпать муку, взбить блендером или перемешать.','https:https://st.vkuso.ru/data/cache/thumb/74/54d5f853c035274_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'Должно получиться тесто, напоминающее по консистенции сметану.','https:https://st.vkuso.ru/data/cache/thumb/ac/ef3a3113ddb38ac_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8373,'В разогретую вафельницу налить 1 большую ложку теста. Готовить до золотистого оттенка.','https:https://st.vkuso.ru/data/cache/thumb/02/48643ba1b84fa02_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8374,'Отварить картофель в кожуре, почистить. Вымыть и порезать грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8374,'Нагреть 2 ложки масла на сковороде. Положить грибы, тушить 15 минут. Помешивать время от времени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8374,'Блендером или через мясорубку измельчить грибы. Добавить картофель, размять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8374,'Добавить соль, измельченный укроп, размешать. Насыпать муку, хорошо перемешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8374,'Закипятить воду. Влажными руками, используя маленькую ложку, сформировать шарики. Опустить их в кипящую воду. Готовить постные фрикадельки из грибов и картофеля 10 минут. Когда всплывут, достать из воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'Застелить форму для торта (лучше разъемную) фольгой и смазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'В небольшую кастрюльку влить сливки и положить сливочное масло, поставить посуду на огонь, сливки с маслом растопить и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'В миску поломать шоколад, залить его готовой масляно-сливочной смесью и мешать, пока содержимое миски не превратиться в однородную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'В получившуюся шоколадную массу добавить предварительно поломанное на кусочки печенье, аккуратно все перемешать и переложить в подготовленную форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'Поверхность будущего торта разровнять и убрать на 3 часа в морозильную камеру до затвердения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'Застывший шоколадный торт из печенья в глазури без выпечки осторожно переложить из формы на блюдо и снять фольгу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'В маленькую кастрюльку снова влить сливки, положить масло и довести все до кипения, после чего залить ею шоколад и перемешать все до однородности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'Получившейся шоколадной глазурью полить торт, аккуратно распределив ее по всей поверхности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8375,'Дать глазури пару минут схватиться и можно подавать лакомство к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'С вечера промыть и замочить фасоль. Отваривать 50-60 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'Почистить, вымыть картофель, порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'Почистить, вымыть лук и морковь. Морковь крупно потереть или порезать соломкой, лук порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'Вымыть рис. Закипятить в кастрюле воду, положить готовую фасоль. Когда закипит, положить картофель, рис и половину лука и моркови. Готовить 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'Нагреть сковороду, налить растительное масло. Обжаривать оставшийся лук и морковь 4-6 минут, помешивая. Насыпать муку, тушить минуту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8376,'Положить в суп зажарку, перец черный молотый, соль. Варить 5-10 минут. Добавить в фасолевый суп с картофелем и рисом измельченную зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8377,'Сырое куриное яйцо и дополнительный белок взбить с нежирным творогом, добавить сахарозаменитель и фрукты, нарезанные кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8377,'Поставить смесь на три минуты в микроволновку. Форма для выпекания должна быть высокой: суфле в процессе приготовления поднимается. При готовности верхний слой запеканки должен стать плотным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Для приготовления заправки мелко порубить очищенный красный лук и зелень укропа. Добавить в смесь сметану или натуральный йогурт, посолить по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Куриные грудки разрезать вдоль пополам, натереть солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Разогреть на среднем огне, на сковороде, немного растительного масла. Выложить филе и жарить с каждой стороны по две-три минуты. Вынуть мясо и остудить, нарезать небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8378,'Выложить на блюдо листья зеленого салата, предварительно вымытые и обсушенные. На листья – полученную смесь, полить заправкой и подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8379,'Для приготовления начинки нарезать зеленый укроп и перо лука. Смешать с творогом, всыпать куркуму, влить молоко, добавить давленый чеснок, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8379,'В каждом филе курицы сделать острым ножом глубокий разрез, выложить начинку в полученный «кармашек». Филе намазать растительным маслом и обвалять в панировочных сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8379,'Изделия выложить в огнеупорную форму, печь при температуре 200 градусов в течение 20 минут, время от времени поливать выделяющимся соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8380,'На дно небольшой кастрюли налить немного воды, затем молоко. Довести жидкость до кипения, добавить овсяные хлопья, перемешать. Прогревать в течение 15 – 20 минут на среднем огне, до разваривания хлопьев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8380,'Отдельно очистить и размять банан, добавить ванильный экстракт. Кашу снять с плиты, добавить банановое пюре. Емкость накрыть крышкой, дать постоять еще пять минут для пропаривания, подать на стол.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8381,'У рыбы удалить внутренности вместе с жабрами. Снять кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8381,'Филе сбрызнуть лимонным соком и поместить в пароварку. Прогревать в течение 15 – 20 минут. Молотый черный перец, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8382,'Нарезать бананы и яблоки, можно обойтись только яблоками или только бананами. Выложить фрукты на дно формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8382,'Отдельно перемешать творог с сырыми куриными яйцами, натуральным йогуртом, сахарозаменителем, например, стевией. Залить смесью фрукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8382,'Печь в течение часа при температуре 200 градусов. Печь выключить, дверку не открывать еще 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Разогреть духовку до 175 градусов, смазать форму сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'В миске смешать мед, какао-порошок, яйца и корицу, перемешать до однородной консистенции без комков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Добавить масло, муку, перец чили и греческий йогурт, мешать, пока не получится однородная масса без комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Получившееся тесто перелить в подготовленную форму и убрать ее в духовку на 30-35 минут, после чего дать испеченному коржу полностью остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Молотый кофе смешать с густыми сливками и убрать получившуюся смесь на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Утром при помощи миксера взбить смесь в густую кремообразную массу с устойчивыми пиками, смазать ей готовый корж.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8383,'Перед подачей шоколадный торт с кофейным кремом по-мексикански украсить тертым шоколадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8384,'Клубни картофеля очистить, нарезать небольшими кусочками, положить вариться в воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8384,'Отдельно натереть морковь на крупной терке, порезать очищенный репчатый лук кубиками. Потушить то и другое на растительном масле в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8384,'Обжарку добавить в кастрюлю вместе с плавлеными сырками, нарезанными кусочками. Суп мешать, пока сыр не раствориться полностью. Соль – по вкусу. Варить в течение получаса, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8385,'Нарезать красный болгарский перец, репчатый лук, морковь. Овощи обжарить на оливковом масле в течение четырех-пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8385,'Всыпать зеленый горошек без жидкости, прогревать еще пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8385,'Добавить рис басмати или парбоилд, разровнять по всей поверхности. Влить воду, прогревать до почти полного впитывания жидкости рисом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8385,'В рис добавить приправы: молотый перец, шафран, сухую зелень, кориандр, сладкую паприку. Соль – по вкусу. Сгрести рис горкой, дать пропариться под крышкой и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8386,'Отварить куриное филе, нарезать кусочками. Тонко нашинковать пекинскую капусту. Красные помидоры нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8386,'Добавить в смесь консервированную кукурузу и красную фасоль в собственном соку, жидкости слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8386,'Влить натуральный йогурт без вкусовых добавок, приправить измельченным чесноком, соль – по вкусу. Салат перемешать и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8387,'Сырую куриную грудку разрезать вдоль так, чтобы получился «кармашек». Мясо натереть перцем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Порезать айву и яблоки на 4 части, удалить семечки, поместите их внутрь гуся, зашить или сколоть зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8387,'В «кармашек» положить, очищенные от кожицы и перегородок, дольки апельсина. Изделия завернуть в фольгу, печь в духовом шкафу при температуре 200 градусов в течение 20 – 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Деревянные шпажки замочить в холодной воде на полчаса. Духовой шкаф разогреть до 220 градусов или приготовить угли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Половину куриного фарша обжарить на сковороде в течение минуты или двух, массу постоянно помешивать, продукт должен изменить цвет, не должно остаться кусочков розового цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Отдельно перемешать кунжутное масло и мисо-пасту  до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Перемешать готовый и сырой фарш, добавить колечки зеленого лука, масляную смесь и половину соуса Якитори.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Фарш хорошо вымесить: 30 перемешиваний по часовой стрелке и столько же – против часовой стрелки. Масса должна быть липкой, но плотной, хорошо держаться на шпажке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Сформовать небольшие колбаски, похожие на люля-кебаб, котлеты или круглые тефтели, нанизать на шпажки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Открытый конец шпажки обмотать фольгой, чтобы древесина не обуглилась и не загорелась. Изделия выложить на смазанный противень или в форму для выпекания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8388,'Смазать дополнительной порцией соуса Якитори при помощи кулинарной кисти, печь в течение 6 – 10 минут, перевернуть один раз. Колбаски должны подрумяниться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8389,'Смешать творог, сырое куриное яйцо, соль и ванильную эссенцию. Сахарный песок или пудра – по вкусу. Массу растереть до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8389,'Всыпать просеянную пшеничную муку, смесь снова хорошо растереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8389,'Доску присыпать мукой, выложить творожное тесто, посыпать мукой сверху и раскатать в лепешку толщиной до одного сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8389,'Вырезать вареники с помощью формочек или просто нарезать квадратиками со стороной в три-четыре сантиметра. Формочку лучше окунуть в муку, чтобы тесто не прилипало.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8389,'Варить изделия в подсоленной воде, опускать в кипяток, они должны всплыть. Через три минуты после всплытия вареники вынуть с помощью шумовки, выложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8390,'Слабосоленое филе форели или семги нарезать небольшими кубиками, побрызгать свежим лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8390,'Отварить куриные яйца вкрутую, также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8390,'Любой твердый сорт сыра натереть на мелкой терке. Ингредиенты хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8390,'Добавить мелко порезанную зелень укропа, сметану. Заправлять салат лучше перед самой подачей на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8390,'Этот салат можно выложить слоями: яйца, рыба, зелень, сыр. Слои промазывать сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8391,'Куски сырого мяса хорошо отбить. Отдельно измельчить очищенный чеснок, нашинковать лук-репку, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8391,'Массу выложить на говядину, соль и молотый перец – по вкусу. Свернуть трубочкой, жарить до готовности на раскаленной сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Желатин замочить в воде так, как написано на пакетике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Ржаные сухари, вяленые яблоки, курагу и изюм измельчить с помощью мясорубки или блендера. Влить жидкий мёд, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Вылить и равномерно распределить массу на дне разъемной формы. Стенки формы должны быть смазаны маслом или обернуты пищевой пленкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Яблоко и банан очистить от кожуры, нарезать то и другое тонкими ломтиками, выложить фрукты на корж.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Набухший желатин прогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Перемешать с помощью блендера молоко, банан, творог, молотую корицу и сахарный песок. Массу взбить, влить немного остывший желатин, перемешать и вылить смесь в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8392,'Чизкейк остудить в холодильнике до полного застывания желатина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8393,'Перемешать в небольшой кастрюле сахарный песок и какао-порошок, делать это до тех пор, пока не исчезнут комочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8393,'Влить воду, поставить на огонь, довести до кипения, помешивать. Готовый сироп довести до загустения, снять с плиты, добавить экстракт ванилина по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8393,'Смесь поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8394,'Разогреть на сковороде сливочное масло, обжарить кубики репчатого лука, добавить куриное филе, нарезанное брусочками, прогреть несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8395,'Приготовить с вечера кубики льда: в каждую ячейку формы для льда положить по веточке укропа, залить водой, убрать в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8395,'Отварить картофель (не чистить), дать остыть, почистить, нарезать на кубики, огурцы порезать на такие же по размеру кубики, ветчину нашинковать соломкой, редис – тонкими кружочками, яйца мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8395,'Мелко нашинковать укроп, зеленый лук, петрушку, ссыпать все в глубокую миску, посолить, аккуратно и тщательно перемешать, залить кефиром, размешать, дать чуть постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8395,'Разлить окрошку на кефире с редисом по тарелкам, положить в каждую порцию по несколько кубиков льда.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Темный шоколад поломать на кусочки и растопить на водяной бане или в микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Сырые куриные яйца разделить на желтки и белки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Желтки взбить с 1/4 стакана сахара (50г) в пышную и светлую массу в течение пяти минут, затем соединить с остывающим шоколадом с помощью миксера, скорость – средняя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Белки взбить в пену тоже вместе с 2 ст.л. (25 г) сахаром до получения гладкой и блестящей массы. Добавить в желтковую четверть белковой массы, перемешать лопаткой, влить оставшуюся смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Сбрызнуть противень растительным маслом, выстелить бумагой для выпекания. Вылить тесто, разровнять, печь в течение 15 – 18 минут в заранее разогретой до 175 градусов духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Выпечку вынуть, перевернуть на еще один лист бумаги, верхний снять, изделие остудить и поставить на полчаса в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Для приготовления крема взбить сливки с сахарной пудрой до получения тягучей массы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Остывший корж разрезать на несколько частей, прослоить их кремом с помощью кондитерского кулька.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8396,'Верх торта посыпать тертым темным шоколадом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Растворить желатин в холодном молоке, дать постоять в течение пяти минут для набухания. Поставить кастрюльку на плиту, массу прогреть, до кипения не доводить. Желатин должен полностью раствориться. Смесь охладить.','https:https://st.vkuso.ru/data/cache/thumb/69/d6f876ea83ac969_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Отдельно соединить сметану с творогом','https:https://st.vkuso.ru/data/cache/thumb/9e/2fa3d2a57ae859e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Добавить сахарный песок или мёд по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/53/4a3fa3b9a9bdb53_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Все ингредиенты перетереть с помощью погружного блендера или миксера.','https:https://st.vkuso.ru/data/cache/thumb/7d/6713a88e41aac7d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Долить массу с желатином, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/c6/6f52705279be7c6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Всыпать ягоды или кусочки любых фруктов, перемешать ложкой.','https:https://st.vkuso.ru/data/cache/thumb/39/62d599cd2b88f39_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Готовую смесь для суфле разлить в порционные формы и поставить в холодильник на два-три часа или на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8397,'Десерт украсить фруктами или ягодами и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/e5/4313b61da89e0e5_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8398,'Сварить и остудить яйца и картофель, нашинковать мелко зеленый лук, растереть в кастрюле с солью, смешать с нарезанными яйцами, редисом, огурцом и картофелем, залить холодным квасом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8398,'Разлить окрошку с редисом на квасе по тарелкам, положить в каждую по столовой ложке сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Пшеничную муку просеять вместе с солью. Отдельно взбить сырые яйца с молоком до однородного состояния, обе смеси соединить порциями.','https:https://st.vkuso.ru/data/cache/thumb/00/839f76a0eab4900_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Влить растопленное сливочное масло и перемешать. Полученное тесто убрать на час или два в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/0f/8c7beb03fc95a0f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Поджарить блинчики на сливочном масле с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/57/7b85ee136ed5e57_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Смазать ореховой пастой «Нутелла».','https:https://st.vkuso.ru/data/cache/thumb/3c/bf9a1c4f57aca3c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Разложить на начинку обжаренные орехи.','https:https://st.vkuso.ru/data/cache/thumb/e0/25ff76db7e828e0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Затем зерненный творог.','https:https://st.vkuso.ru/data/cache/thumb/4c/d58e2b94fcb8b4c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Бананы и клубнику порезать ломтиками и также выложить сверху.','https:https://st.vkuso.ru/data/cache/thumb/b0/e7999f699ab74b0_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8399,'Свернуть блины трубочками, украсить дополнительной порцией «Нутеллы», налитой на блинчик полосками, подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/c5/30e64b5b75ccec5_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8400,'Для приготовления основной массы понадобится куриный фарш, заранее замоченный в холодной воде и размятый белый батон, репчатый лук, измельченный чеснок, сырое куриное яйцо и любимые специи. Все ингредиенты хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8400,'Кусочек сыра завернуть в тонкий ломтик ветчины – это и будет начинка. Сформовать котлеты, обвалять в панировочных сухарях. Жарить до готовности, с двух сторон до румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Размягченное сливочное масло взбить с сахарным песком в пышную массу.','https:https://st.vkuso.ru/data/cache/thumb/83/099e0b3da31ca83_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Добавить яйцо и ваниль, взбить еще раз. Натереть на мелкой терке мякоть тыквы, перемешать с пшеничной мукой, разрыхлителем и солью.','https:https://st.vkuso.ru/data/cache/thumb/11/0eba47939ac9f11_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Замочить в теплой воде курагу с изюмом, дать набухнуть, обсушить. Курагу нарезать на небольшие кусочки. Всё вмешать в мучную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Добавить сушеный имбирь, молотую корицу, измельченный мускатный орех. Очищенные грецкие орехи обжарить и порубить ножом, перемешать. Осторожно объединить мучную и масляную смеси.','https:https://st.vkuso.ru/data/cache/thumb/29/0f546e2bbe22629_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Формочки для кекса смазать маслом, вылить тесто, печь в течение 35 – 40 минут в духовом шкафу при температуре 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/e6/379ef2364aae0e6_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8401,'Для приготовления крема натереть цедру апельсина, отжать сок. Положить в кухонный комбайн крем «Маскарпоне», влить сливки, добавить сахарную пудру, немного взбить до однородного состояния. Добавить цедру апельсина, сок, все вместе еще раз взбить до пышности. Подать готовый кекс холодным или теплым, с сырным кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8402,'Разбавить мацони 1:1 водой, поставить в холодильник, отварить мякоть говядины, остудить, порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8402,'Нашинковать мелко укроп, кинзу, зеленый лук, огурцы почистить и нарезать на кубики, все смешать, посолить, добавить чуть сахара, еще раз хорошо перемешать, залить окрошку по-азербайджански холодным мацони.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Всыпать в емкость половину нормы муки, перемешать с натертым охлажденным сливочным маслом. Добавить оставшуюся муку и размять тесто до равномерного состояния, влить стакан любого пива. Масса должна получиться эластичной, если она будет липнуть к рукам – добавить муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Вылить растительное масло на разогретую сковороду, добавить измельченный репчатый лук. Овощи обжарить, добавить говяжий и свиной фарш в равных пропорциях, прогревать до полуготовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Мелко нарезать свежие шампиньоны и всыпать в обжарку, прогреть до готовности, добавить красную консервированную фасоль без жидкости, томаты в собственном соку, лавровый лист, соль по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Тушить смесь до выпаривания жидкости, затем остудить. Лавровый лист удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Разделить тесто на две неравные части, большую часть раскатать для нижней части пирога.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Застелить противень бумагой для выпекания, выложить тесто, сформовать бортики. Добавить начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Меньшую часть теста раскатать, накрыть начинку, уголки скрепить с основанием. В тесте сделать отверстия для выхода воздуха, поверхность смазать сырым желтком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8403,'Поставить противень в заранее разогретую духовку на полчаса. Подать пирог горячим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Яблоки очистить от кожуры и семечек и нарезать кубиками, чернослив – на четыре части.','https:https://st.vkuso.ru/data/cache/thumb/f2/85e3ca34134b6f2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Желтки отделить от белков, добавить в них просеянную пшеничную муку, ванилин, разрыхлитель, растительное масло, ингредиенты перемешать.','https:https://st.vkuso.ru/data/cache/thumb/9d/5aac74fe8a35e9d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Белки также взбить с сахаром в пышную массу.','https:https://st.vkuso.ru/data/cache/thumb/8e/c880fa165bcfd8e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Перемешать обе смеси, тесто должно получиться пышным и жидковатым.','https:https://st.vkuso.ru/data/cache/thumb/cf/6be596acc3c60cf_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Застелить противень бумагой для выпекания, смазать растительным маслом. Выложить чернослив и яблоки, посыпать молотой корицей.','https:https://st.vkuso.ru/data/cache/thumb/1e/6a801574df6a01e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Залить все тестом, печь при температуре 20 – 25 минут при температуре 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/d7/12a23adc2fcbcd7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Перемешать простой свекольный салат с яйцом и сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8404,'Горячий корж свернуть в рулет, остудить и посыпать сахарной пудрой, а затем нарезать.','https:https://st.vkuso.ru/data/cache/thumb/ac/6efee985605b8ac_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8405,'Поставить вариться яйца, мясо и язык, хлебный квас убрать в морозилку, нарезать небольшими кубиками окорок, огурцы, остывшие говядину и язык.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8405,'Мелко нашинковать зеленый лук, растереть, добавив соль, к остывшим желткам добавить горчицу,  соль, сметану, сахар, растереть, белок мелко порубить или натереть, смешать с луком,  развести квасом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8405,'Всыпать в квас все нарезанные ингредиенты, перемешать, попробовать, если надо добавить еще чуть соли, дать постоять, разлить окрошку мясную с окороком и языком по тарелкам, украсить нашинкованным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Приготовить блинное тесто из теплого молока, яиц, соли, пищевой соды и пшеничной муки. Испечь блинчики размером 30 на 30 сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Для начинки на разогретой сковороде обжарить морковь, шампиньоны, репчатый лук, нарезка – произвольная. Соль и специи – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/3c/7eec8c44890f33c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Низ формы смазать маслом. Если форма квадратная, то блины можно обрезать. Выложить три блина, смазать сметаной, затем – начинка, плавленый сыр.','https:https://st.vkuso.ru/data/cache/thumb/ec/b8cff03bccee7ec_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Затем обрезки нижних блинов или те, которые не получились.','https:https://st.vkuso.ru/data/cache/thumb/99/f1c35cbb1e18599_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Снова три блина, начинка, сыр, блины, сметана и сыр.','https:https://st.vkuso.ru/data/cache/thumb/4a/5bb582eddaa824a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8406,'Печь в течение получаса при температуре 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Нарезать репчатый лук.','https:https://st.vkuso.ru/data/cache/thumb/56/ac04f0b87415f56_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'В кастрюлю налить оливковое или подсолнечное масло, обжарить лук.','https:https://st.vkuso.ru/data/cache/thumb/bc/d60ecab701d5fbc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Тыкву очистить и нарезать кубиками.','https:https://st.vkuso.ru/data/cache/thumb/3d/cb1688cb11c563d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Переложить в обжарку, прогреть все вместе, соль и молотый перец – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/f8/77eddb704f935f8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Подлить воду, варить тыкву до мягкости.','https:https://st.vkuso.ru/data/cache/thumb/6e/eb8577ba9aa016e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Готовую массу измельчить с помощью блендера, подливая бульон. В таком виде суп можно подавать к столу или добавить в него сливки и немного прогреть на тихом огне.','https:https://st.vkuso.ru/data/cache/thumb/b1/267b0307e9a45b1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Бекон нарезать, сыр «Пармезан» натереть, можно использовать любой другой твердый сорт. Пластинки бекона обжарить на сухой сковороде.','https:https://st.vkuso.ru/data/cache/thumb/f9/548afa9f06a23f9_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8407,'Готовый суп разлить в порционные тарелки, выложить бекон и посыпать сыром, подать сразу.','https:https://st.vkuso.ru/data/cache/thumb/a6/50f5129bcc8caa6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8408,'Томаты, свежий огурец, сладкий перец и чеснок измельчить с помощью блендера до однородной консистенции.','https:https://st.vkuso.ru/data/cache/thumb/13/962a2444ae7ed13_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8408,'Влить бальзамический уксус и оливковое масло. Соль и перец – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/e6/9df808acbb837e6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8408,'Все еще раз хорошо перемешать блендером, по желанию добавить зелень базилика или петрушки.','https:https://st.vkuso.ru/data/cache/thumb/c9/81dd0b7adf97fc9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8409,'Отварить морковь, картофель, яйца, дать остыть, нарезать, добавить для разнообразия зеленый горошек, измельченные кубиками огурцы, посолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8409,'Залить все по вкусу взбитым с водой холодным кефиром со щепоткой черного перца или квасом, всыпать измельченную зелень кинзы (на любителя), укропа и петрушки с зеленым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8409,'Для мясоедов можно добавить отварную телятину, ветчину или колбасу, если окрошка с зеленым горошком готовится на квасе, то при подаче добавить в тарелки сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8410,'Брынзу размять вилкой, добавить измельченную зелень укропа и петрушки, сырое яйцо для связки и размороженный шпинат.','https:https://st.vkuso.ru/data/cache/thumb/27/7be172b2b08bc27_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8410,'Готовое слоеное тесто из магазина разрезать квадратиками со стороной в 15 сантиметров.','https:https://st.vkuso.ru/data/cache/thumb/49/6ccca2e93519a49_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8410,'В центр выложить начинку.','https:https://st.vkuso.ru/data/cache/thumb/63/96bee0f67189163_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8416,'Картофель очистить, нарезать крупными кусками, влить сметану, посолить и также добавить давленый чеснок. Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8410,'Закрепить углы теста посередине, не защипывать, начинка должна быть видна. Изделия выложить на противень, застеленный пергаментом. Печь в духовом шкафу в течение получаса.','https:https://st.vkuso.ru/data/cache/thumb/27/5a26ab08a677d27_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'Яйца отварить в кипящей воде в течение 10 минут, охладить, почистить.','https:https://st.vkuso.ru/data/cache/thumb/cf/8815010b79117cf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'Майонез перемешать с натуральным йогуртом без добавок, свежемолотым черным и белым перцем, соль – по вкусу. Всыпать рубленую зелень петрушки. Немного перемешать.','https:https://st.vkuso.ru/data/cache/thumb/25/424cc19eeafab25_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'На дно салатницы выложить немного полученного соуса, рубленые яйца.','https:https://st.vkuso.ru/data/cache/thumb/63/d1bf7c80cdc9c63_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'Слои повторить.','https:https://st.vkuso.ru/data/cache/thumb/49/908eabccce1a249_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'Хлеб чиабатта подсушить в тостере, смазать тонким слоем размягченного сливочного масла.','https:https://st.vkuso.ru/data/cache/thumb/ad/f1dc0c991c3fdad_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8411,'На него выложить яичную массу и слой красной икры.','https:https://st.vkuso.ru/data/cache/thumb/af/e7e783b079de2af_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8412,'Нарезать лимон, лайм и апельсин.','https:https://st.vkuso.ru/data/cache/thumb/aa/22ead2c949845aa_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8412,'Ягоды облепихи поварить в воде пять минут на огне средней мощности, немного размять.','https:https://st.vkuso.ru/data/cache/thumb/e3/10020a7b0e2c7e3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8412,'Перелить воду вместе с размятыми ягодами в бокалы, добавить кружки цитрусовых, палочки корицу, тростниковый сахар, клубнику, гвоздику и свежую мяту. Дать постоять еще пять минут.','https:https://st.vkuso.ru/data/cache/thumb/76/889758c1a933e76_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8413,'Поставить вариться картофель, куриное филе, яйца, остудить, нарезать мелко мясо, а картофель, огурец и редис – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8413,'Отделить белки от желтков: белок порубить, желток растереть с горчицей, зелень укропа мелко нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8413,'Все ингредиенты смешать, посолить, аккуратно перемешать, залить охлажденным негазированным таном,  перед подачей окрошка на тане должна настояться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8414,'Телятину пропустить через мясорубку, посолить и поперчить, влить жирные сливки и всыпать молотый мускатный орех.','https:https://st.vkuso.ru/data/cache/thumb/23/8d7f24135622823_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8414,'Все ингредиенты хорошо перемешать с помощью миксера. В полученную смесь добавить хлебные крошки, фарш перемешать руками, он должен получиться эластичным, но мягким.','https:https://st.vkuso.ru/data/cache/thumb/1f/9da8588ff20111f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8414,'Сформовать небольшие котлеты круглой или классической формы. Нагреть на сковороде топленое масло. Каждую котлету обвалять в дополнительной порции крошек, выложить на сковороду. Жарить до появления золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/d4/88728c1b030f5d4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8414,'Почти готовые изделия переложить на противень и отправить в духовку на пять минут, температура приготовления – 220 градусов.','https:https://st.vkuso.ru/data/cache/thumb/8e/46d51351fdc8e8e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Репчатый лук тонко нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Очистить, вымыть и тонко нарезать клубни картофеля. Уже нарезанный продукт еще раз промыть, чтобы удалить лишний крахмал. Ломтики обсушить полотенцем.','https:https://st.vkuso.ru/data/cache/thumb/7f/d402fdf63ac5a7f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'В сковороде разогреть оливковое масло, обжарить лук до мягкости и прозрачности.','https:https://st.vkuso.ru/data/cache/thumb/31/197cce8f5266f31_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Добавить картофель, перемешать и готовить еще 10 – 15 минут. Во время жарки продукты помешивать.','https:https://st.vkuso.ru/data/cache/thumb/74/3db49d2b4c41874_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Взбить сырые куриные яйца, нарезать свежие листочки розмарина. Картошку посолить, поперчить, посыпать розмарином и молотым мускатным орехом, перемешать и довести до готовности.','https:https://st.vkuso.ru/data/cache/thumb/12/5c96aebc6f58812_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Готовую обжарку переложить в яйца, перемешать, выложить обратно на смазанную сковороду. Готовить на огне средней мощности, под крышкой, жарить до подрумянивания омлета с нижней стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'Крышку снять, переложить омлет на тарелку, перевернуть, затем снова переместить на сковороду и жарить еще две-три минуты, уже без крышки.','https:https://st.vkuso.ru/data/cache/thumb/d8/cc5ad6aa1e7a2d8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8415,'При подаче нарезать массу на порционные кусочки.','https:https://st.vkuso.ru/data/cache/thumb/7a/f5aff424f57377a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8416,'Перемешать растительное масло с солью, красным молотым перцем, давленым чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11512,'Долить кефир комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8416,'Курицу выложить в рукав для запекания, вокруг выложить картофель. Поставить блюдо в заранее разогретую духовку, печь в течение двух часов или дольше, до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8417,'Сварить яйца, картофель, остудить, почистить, нарезать их на кубики, огурцы очистить (старые), нарезать кубиками размером чуть меньше картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8417,'Редиску нашинковать очень тонкими кружочками, зелень мелко порубить, яйца нарезать также как и огурцы, смешать сметану с горчицей, солью, перцем, заправить смесью овощи, осторожно перемешать, залить минеральной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8417,'Убрать окрошку на минеральной воде в холодильник, дать настояться минимум полчаса, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8418,'Всыпать сахарный песок в большую миску, добавить цедру лайма и лимона. Все перемешать, оставить на полчаса, ингредиенты можно перетереть руками.','https:https://st.vkuso.ru/data/cache/thumb/ec/9ecb23dc2421eec_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8418,'Добавить соки лайма и небольшого лимона, сырые куриные яйца, продукты перемешать.','https:https://st.vkuso.ru/data/cache/thumb/82/6d244e71eb00082_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8418,'Темный шоколад растопить со сливочным маслом, это можно сделать в микроволновой печи. Теплую массу добавить в яичную смесь.','https:https://st.vkuso.ru/data/cache/thumb/31/9feb3161b2e7f31_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8418,'Всыпать какао-порошок, муку, разрыхлитель, перемешать еще раз. Готовое тесто перелить в форму для выпекания, заранее смазанную маслом и присыпанную мукой.','https:https://st.vkuso.ru/data/cache/thumb/d3/e0b284850bce6d3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8418,'Температура приготовления – 180 градусов, время – до получаса. Готовая выпечка должна остаться немного влажной, сыроватой внутри.','https:https://st.vkuso.ru/data/cache/thumb/ff/cb5ed05d51cb5ff_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Отварить картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Нарезать полукольцами репчатый лук, обжарить на растительном масле в течение двух-трех минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Добавить грибы, жарить все вместе до выпаривания влаги.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Из картофеля приготовить пюре, подлить подогретые сливки, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Обе массы, грибную и картофельную, соединить, всыпать рубленую зелень укропа и петрушки, соль и молотый перец. Еще раз хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Слоеное бездрожжевое тесто раскатать в тонкий пласт, нарезать прямоугольниками. Выложить на противень по два пласта, печь при температуре 200 градусов в течение 12 минут, до легкого подрумянивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'На противень выложить один корж, промазать начинкой, посыпать тертым сыром, слои повторять. Верх просто присыпать сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8419,'Печь собранный торт еще пять минут при той же температуре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Перемешать в миске с помощью венчика сырые куриные яйца, соль и сахарный песок. Если хочется сделать блинчики слаще – норму сахара можно увеличить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Влить цельное молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Всыпать муку, еще раз перемешать массу до однородного состояния. Добавить остатки молока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Тесто должно быть легко льющимся. Чтобы тесто получилось еще нежнее, в него можно влить полстакана или стакан крутого кипятка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Добавить растительное масло, перемешать и оставить для набухания на 15 – 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Чугунную или другую толстостенную сковороду для блинов разогреть, смазать небольшим количеством растительного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'В центр посуды вылить черпак или полчерпака теста. Поворачивать сковороду так, чтобы оно быстро растеклось по поверхности. Жарить блины с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Для крема всыпать в кастрюлю сахар, желтки, добавить муку, все перемешать венчиком. Влить теплое кипяченое молоко, непрерывно помешивая. Довести до кипения, снять с огня и охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'Очистить и разрезать пополам бананы, каждую часть – еще на три.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8420,'На каждый готовый блинчик выложить слой заварного крема и ломтик банана. Блинчик завернуть в рулет. Таким же образом поступить со всеми изделиями.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8421,'Отварить клубни картофеля в мундире, остудить, почистить, вымыть редис, огурец, зелень. Все нарезать на кубики, укроп и петрушку мелко нашинковать, переложить в глубокую салатницу, добавить нарезанный на кубики адыгейский сыр, заправить соком лимона, специями, солью, сахаром, тщательно перемешать, разложить по тарелкам, залить кефиром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8421,'В качестве напитка к окрошке вегетарианской на кефире подать огуречный напиток. Приготовить просто: положить в стакан минералки по кусочку огурца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8421,'Блюдо подавать хорошо охлажденным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8422,'Куриные яйца взбить с молоком, растопленным сливочным маслом и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8422,'Пшеничную муку заранее просеять вместе с солью, ввести порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8422,'Сотейник разогреть, растопить немного масла, влить тесто, сверху распределить ягоды черники, малины, земляники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8422,'Печь при температуре 200 градусов в течение 20 минут, до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8422,'Готовое блюдо украсить ореховой пастой «Нутелла» и посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Зиру прогреть на сковороде, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Кунжутное семя перемолоть в муку блендером.','https:https://st.vkuso.ru/data/cache/thumb/17/2f8408ea86a9f17_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Добавить сок лимона, чеснок, соль и немного оливкового масла, взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Добавить консервированный нут, еще раз взбить в однородную массу. Можно использовать натуральный бобовый продукт, но его нужно будет вымачивать в течение восьми часов или готовить на пару.','https:https://st.vkuso.ru/data/cache/thumb/8f/d7e55bbdb7a3f8f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Всыпать зиру, добавить оставшийся нут, масляную заливку, взбить.','https:https://st.vkuso.ru/data/cache/thumb/c1/2e66ed1acdd90c1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Нарезать куриное филе, репчатый лук, баклажан, помидоры черри.','https:https://st.vkuso.ru/data/cache/thumb/42/57d0a141bd55c42_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Овощи обжарить отдельно от мяса, то и другое приправить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/d4/61a2012d769e8d4_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Тортильи разогреть в микроволновой печи, смазать их хумусом.','https:https://st.vkuso.ru/data/cache/thumb/c9/057dc06cba906c9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Равномерно разложить куриное филе и овощи.','https:https://st.vkuso.ru/data/cache/thumb/52/97485f7362c4252_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Свернуть изделия в роллы, обжать, уплотнить, завернуть в пищевую пленку.','https:https://st.vkuso.ru/data/cache/thumb/02/a0aba1f9047a302_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8423,'Убрать в холодильник на час или два. Каждый ролл разрезать пополам и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/52/2d1248ae49c0452_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8424,'Взбить жирный кефир с водой и специями, убрать в холодильник. Очистить огурцы, мелко нарезать, орехи порубить в блендере, укроп мелко нашинковать,',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8424,'Зелени должно быть много, т.к. для окрошки Таратор по-болгарски он —  один из ингредиентов, а не приправа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8424,'Добавить специи, перемешать, разложить по тарелкам, залить холодной кефирной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'Крупу залить водой, накрыть крышкой, поставить на сильный огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'Репчатый лук измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'В закипевшую воду ввести щепотку соли. Огонь убавить, блюдо накрыть крышкой, варить гречку до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'Вымыть шампиньоны, очистить и нарезать пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'Разогреть растительное масло на сковороде, всыпать семена кардамона, измельченный перец чили, чеснок, лук, грибы, подлить соевый соус и сок лимона. Все вместе обжарить в течение двух-трех минут на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8425,'Всыпать готовую гречневую крупу, по желанию можно добавить еще немного соевого соуса, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8426,'Размягченное сливочное масло взбить с сахарным песком, сметаной и ванилином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8426,'Муку просеять, всыпать в основную массу. Замесить тесто, разделить на две половины, каждую обернуть пищевой пленкой, поместить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8426,'Рабочую поверхность присыпать мукой, раскатать тесто в прямоугольник и нарезать полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8426,'По всей длине выложить любое густое повидло, свернуть рулетом, нарезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8426,'Заготовки выложить на противень, печь в заранее разогретой духовке при температуре 180 – 190 градусов в течение 20 минут до готовности. Готовое печенье остудить, посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8427,'Для приготовления теста взбить миксером сахарный песок с яйцами, добавить теплое молоко, растопленное сливочное масло, просеянную муку и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8427,'Печь в формочках.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8428,'Срезать с буханки черного хлеба корки, нарезать на ломти, подсушить в духовке, натереть чесноком, порезать на небольшие по размеру кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11518,'Отварить изделия в подсоленном кипятке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8428,'Нашинковать мелко репчатый лук и перья зеленого лука, разложить вместе с хлебом по тарелкам, посолить, залить холодным квасом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8428,'Впрок тюри с квасом не готовят, а подают к столу всегда сразу, чтобы хлеб сильно не размокал. Для придания блюду более сильного аромата и дополнительного вкуса в тюрю можно добавить зелень укропа, сельдерея, отдельно подать соленые или малосольные огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'В просеянную муку всыпать сахар, соль и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'Растопить масло в теплой воде, порциями. Помешивая, влить в мучную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'Вымесить тесто до эластичности, поставить на полтора часа в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'Тонко нашинковать капусту, проварить 5 минут в кипящей воде, сварить яйца, слегка в небольшом количестве масла обжарить кубики лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'Сцеженную капусту перемешать со сливочным маслом, порубленными яйцами и луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8429,'Слепить пирожки, переложить на противень, прикрыть тканью, дать постоять, смазать верх разболтанным яйцом, поместить на 35 минут в прогретую до 180 градусов духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Дрожжи размешать с половиной стакана воды и чайной ложкой сахара, дать постоять четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Смешать с теплой водой яйца, майонез, соль, соду, сахар, влить «ожившие» дрожжи, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Небольшими порциями всыпать муку, замесить тесто. Влить масло, окончательно вымесить тесто до готовности, прикрыть тканью поставить на полтора часа в тепло до увеличения объема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Для приготовления начинки обжарить фарш в масле, добавить капусту, отжатую от сока, тертую морковь, сахар, нашинкованный лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Обжарить все около четверти часа, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Раскатать в пласт тесто, вырезать любой формой кружки примерно по 7, 5 см в диаметре. В центр каждого положить начинку, защипнуть только с концов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'Подходящую форму застелить пергаментом и смазать маслом, уложить «лодочки» по кругу начиная от центра. Второй круг укладывать между заготовками первого, заполнить так всю форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8430,'выпекать пирог «Соты» с квашеной капустой и фаршем в прогретой до 180 градусов духовке около 50 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Перемешать подсоленную муку с сахаром, добавить кубики масла, растереть до получения крошки, добавить охлажденную воду, сметану. Вымесить тесто, обернуть его в пленку, убрать на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Присыпать стол мукой, раскатать тесто в пласт, вырезать кружочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Противень застелить пергаментом, разложить половину кружков, положить по шпажке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Яблоки очистить, порезать маленькими кубиками, добавить сахар и корицу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Выложить на кружки яблоки, половину чайной ложки джема, закрыть вторым кружком, залепить тщательно края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8431,'Смазать верх пирожков с повидлом и яблоками на палочке разболтанным желтком, наколоть вилкой, выпекать 25 минут в прогретой до 175 градусов в духовке. При подаче посыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8432,'Сварить в подсоленной воде рыбу, слить воду, остудить, нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8432,'Очистить от кожуры редьку и огурцы, нарезать кубиками огурцы, редьку натереть, зелень укропа, петрушки и лук мелко нашинковать. Сварить яйца и картофель в мундире, дать остыть, очистить, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8432,'Растереть в миске лук с горчицей, солью, сахаром, влить немного кваса. В другой глубокой миске смешать огурцы, картофель, яйца, зелень, растертый лук и редьку, перемешать, залить белым квасом (он более кислый), добавить кусочки рыбы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8432,'Разлить охлажденную окрошку с рыбой и редькой по тарелкам, положить в каждую по столовой ложке сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8433,'Взбить блендером творог с ванилином и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8433,'Скатать из массы небольшие шарики, обвалять полезные творожные конфетки с орехами в шоколадной крошке, уложить на блюдо, поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Подготовить тушку птицы, срезать излишний жир, очень острым ножом сделать насечки «крест на крест», втереть в кожу и внутрь смесь соли, тимьяна, перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Перед подачей посыпать зеленью петрушки прямо в тарелках.','https:https://st.vkuso.ru/data/cache/thumb/e0/a90a9917967e8e0_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Гуся уложить на противень, налить немного воды, прикрыть фольгой, поместить в духовку с температурой 200 градусов, поливать соком с противня через каждые полчаса, готовить 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Для глазури перемешать в сотейнике сок от пары апельсинов, мед и апельсиновый джем, нагреть на маленьком огне, уварить в два раза до получения тягучей массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Слить жир с противня, удалить фольгу, смазать птицу глазурью, со всех сторон, повторить с промежутком в четверть часа 4 раза до появления на коже апельсиново-медовой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8434,'Обложить гуся в апельсиново-медовой глазури айвой, блюдо будет готово через 3 часа. Переложить тушку на большое блюдо, вынуть зубочистки, порезать на кусочки айву.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Подготовить мясо, обмыть, обсушить, разрезать на равные части.','https:https://st.vkuso.ru/data/cache/thumb/a1/5bdd1cb46cd54a1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Измельчить блендером (или мелко нарезать ножом и помять) листья тимьяна, розмарин, перемешать с солью.','https:https://st.vkuso.ru/data/cache/thumb/46/d24d44da275dd46_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'В полученной массе обвалять мясо, прогреть духовку до 200 градусов, быстро обжарить куски в оливковом масле до корочки со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/56/cd5bc10fdc50056_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Переложить мясо в форму, поставить на четверть часа в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Добавить в сок от обжарки масло, разогреть, обжарить кубики лука до золотистости, налить в сковороду вино, уварить в 2 раза, перемешивая накрошить руками сыр, дать ему полностью растворится.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Влить сливки, хорошо перемешать, выключить плиту, дать минуту постоять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Добавить по маленькому кусочку оставшееся масло, каждую следующую порцию добавлять только после растворения предыдущей.','https:https://st.vkuso.ru/data/cache/thumb/da/e0cd6073b9376da_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Перед подачей соус протереть сквозь сито.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8435,'Вынуть телячью вырезку с пикантным сырным соусом и травами из духовки, дать 10 минут постоять, порезать толщиной примерно по 1, 5 см, разложить на подогретые тарелки, полить соусом, подать с печеными овощами.','https:https://st.vkuso.ru/data/cache/thumb/7f/a26ab9a3c44ea7f_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8436,'Овсянку крупного помола залить горячей водой, остудить, добавить мягкий творог, типа «Валио».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8436,'Отдельно натереть яблоко без кожицы и семян. Яичный белок и тертое яблоко перемешать с овсянкой, всыпать молотую корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8436,'Противень застелить бумагой для выпекания или пергаментом. Печь в духовом шкафу при умеренной температуре в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8437,'Гречневую крупу перемолоть любым способом: можно воспользоваться кофемолкой. Не обязательно в муку, пусть останутся кусочки, не просеивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8437,'Очистить яблоки и натереть на крупной терке. Добавить гречку, ржаные отруби, оливковое масло, мёд, кефир или ряженку. Массу хорошо перемешать, оставить для набухания на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8437,'Тесто должно хорошо склеиваться, не рассыпаться в руках. Если получилось суховатым – добавить еще немного кефира.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8437,'Готовую смесь разделить на шарики, расплющить в лепешки. В качестве присыпки можно использовать мак, кунжутные семечки или рубленые орешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8437,'Печь при температуре 150 градусов в течение 40 – 50 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8438,'Отделить ботву молодой свеклы от корнеплодов, отварить по отдельности до мягкости. Нарезать и отварить щавель (3 минуты), обдать кипятком крапиву, дать стечь воде, измельчить ботву, щавель, крапиву и корнеплоды. Все смешать, добавит нарезанный мелко зеленый лук, и кубики свежего огурца, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8438,'Растереть горчицу с тертым хреном, цедрой лимона и сахаром, влить чуть кваса, перемешать, добавить к овощам и зелени. Хорошо размешать, залить смесью белого и хлебного кваса, убрать на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8438,'Отварить с луком, укропом, лавровым листом и черным перцем рыбу в подсоленной воде. Подавать ботвинью традиционную с рыбой на трех тарелках: одна с колотым льдом, вторая с кусочками рыбы, третья с ботвиньей. Едят это освежающее блюдо холодным, поэтому периодически подкладывают в тарелку кусочки льда. Отдельно подается свежий ржаной хлеб. Рыбу можно заменить раками или креветками. Не традиционно —  подать еще и сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Осторожно перемешать и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'Выжать сок лимона. Поместить все ингредиенты в чашу блендера, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/8e/fdac3739573a78e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'Перелить в высокий лоток.','https:https://st.vkuso.ru/data/cache/thumb/b2/da8fadfa77eaab2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'Поставить на пару часов в морозильник.','https:https://st.vkuso.ru/data/cache/thumb/f2/981205a9032aff2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'Достать ягодно-йогуртовое мороженое со сливками, перемешать блендером еще раз.','https:https://st.vkuso.ru/data/cache/thumb/0a/236c643a6d53d0a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'Вернуть в лоток и убрать в морозильник. Через два часа процедуру повторить и оставить на всю ночь.','https:https://st.vkuso.ru/data/cache/thumb/06/48cb610d0dcd406_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8439,'За полчаса до подачи к столу достать мороженое из морозилки.','https:https://st.vkuso.ru/data/cache/thumb/95/3df302fcdafc395_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8440,'Порезать грудку на кубики.','https:https://st.vkuso.ru/data/cache/thumb/c1/1113329783910c1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8440,'Нарезать лук мелкими кубиками, обжарить в масле на среднем огне 10 минут, добавить мясо, влить сливки, тушить 5 минут, убрать с плиты.','https:https://st.vkuso.ru/data/cache/thumb/d0/f014c6cda9d6bd0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8440,'Натереть мелко сыр, разложить жульен с курицей и сыром в тарталетки, присыпать сырной стружкой.','https:https://st.vkuso.ru/data/cache/thumb/b5/196784449c799b5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8441,'Сварить куриную грудку, картофель в мундире и яйца, дать остыть, нарезать мясо на кубики (кожу снять), очищенный картофель – кубиками чуть мельче курицы, яйца порубить. Остывший бульон убрать в холодильник для заливки окрошки днестровской с курицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8441,'Помыть зелень, редис и огурцы, обсушить, нарезать овощи на кубики, зелень мелко',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8441,'нашинковать. Смешать все ингредиенты, добавить молотый черный перец, посолить, залить смесью холодного бульона и сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8442,'Разделать рыбу на филе, тщательно удалить все кости.','https:https://st.vkuso.ru/data/cache/thumb/3a/e7af53e038f6c3a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8442,'Порезать цукини на брусочки.','https:https://st.vkuso.ru/data/cache/thumb/30/7a264e2e7f29330_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8442,'Сложить в пароварку вместе со спаржей, добавить рыбу, посолить, поперчить, готовить 7 минут.','https:https://st.vkuso.ru/data/cache/thumb/36/25f3b014c384e36_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8442,'Выжать сок лимона. Все ингредиенты для соуса хорошо смешать, подсолить, поперчить.','https:https://st.vkuso.ru/data/cache/thumb/92/e0dda02eeace892_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8442,'Выложить на середину большой тарелки цукини, поперек - столбики спаржи, прикрыть рыбой, вокруг налить соус. Оформить сибас на пару под лимонно-медовым соусом зеленью и луком пореем.','https:https://st.vkuso.ru/data/cache/thumb/95/4bbcfc2e20b6795_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8443,'Проварить на водяной бане смесь какао с водой, всыпать сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8443,'Желтки взбить, добавить в какао, перемешать, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8443,'Белки взбить до появления устойчивых пиков, перемешать тщательно с шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8443,'Заполнить полученной смесью форму, выпекать ПП–брауни на десерт 8 минут при температуре духовки 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8443,'Дать десерту остыть, поместить на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8444,'Прогреть духовку до 190 градусов, подготовить форму, смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8444,'Перемешать сахар, соль, муку и разрыхлитель, залить пивом, еще раз тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8444,'Нашинковать мелко укроп, сыр натереть, перемешать с тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8444,'Заполнить тестом форму, прикрыть пленкой, убрать на треть часа в тепло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8444,'Смазать верх сырного хлеба на пиве с укропом маслом, выпекать 40 минут, перед подачей дать полностью остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8445,'Отварить картофель, остудить, нарезать вместе с огурцами на кубики, зелень нашинковать, порубить белки вареных яиц, желтки растереть и смешать со сметаной, присолить и все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8445,'Залить сухофрукты парой стаканов кипятка, нагреть до кипения, закрыть крышкой, оставить на 4 часа, процедить, добавить чуть сахара, еще раз прокипятить, охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8445,'Овощную смесь с зеленью и яйцами залить холодным узваром, размешать, попробовать, добавить в окрошку на настое из сухофруктов лимонный сок, перемешать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8446,'Разрезать филе вдоль, положить в пакет, отбить с 2 сторон, посолить, сдобрить итальянскими травами, посыпать тертой моцареллой.','https:https://st.vkuso.ru/data/cache/thumb/00/99d6fa43a0af200_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8446,'Порезать персики на дольки, уложить на сыр, свернуть мясо в трубочку, обвязать ниткой.','https:https://st.vkuso.ru/data/cache/thumb/b9/c945e5c120eb3b9_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8446,'Переложить куриные рулетики с персиками и травами на смазанную форму, смазать верх рулетиков маслом, положить на них несколько веточек тимьяна. Выпекать в прогретой до 190 градусов духовке около 25 минут, подавать к столу пока горячие.','https:https://st.vkuso.ru/data/cache/thumb/a4/e9b605a82ecaba4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8447,'Хорошо вымыть картофель, обернуть клубни пленкой, поместить на пару-тройку минут в микроволновку на 600 Вт.','https:https://st.vkuso.ru/data/cache/thumb/bb/25dac673d04fabb_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8447,'Аккуратно удалить шкурку, порезать на крупные куски.','https:https://st.vkuso.ru/data/cache/thumb/8a/1d96d4e3db5928a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8447,'Разогреть в сковороде масло, обжарить чеснок с луком, положить картофель, кусочки сливочного масла, приправить солью и карри.','https:https://st.vkuso.ru/data/cache/thumb/ff/a367c759e9e1eff_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8447,'Перед подачей жареный картофель с карри и чесноком присыпать молотым черным перцем.','https:https://st.vkuso.ru/data/cache/thumb/72/393ec2024678b72_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8448,'Застелить противень пергаментом, положить хлопья, дробленные орехи, миндаль (предварительно порубить), семечки тыквы и подсолнечника, кунжут и семена льна. Подсушить все около 7 минут при температуре порядка 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8448,'Пересыпать в глубокую миску, добавить клюкву с изюмом, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8448,'Помешивая, прогреть на среднем огне в глубокой сковороде около 5 минут смесь меда с маслом и сахаром до появления коричневатого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8448,'Залить карамелью злаки, быстро и тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8448,'Переложить орехово-злаковое печенье с изюмом и клюквой в форму, выстланную пергаментом, прикрыть еще листом бумаги и с усилием уплотнить, дать постоять пару часов, разрезать острым ножом на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8449,'Нарезать отварную говядину и картофель на кубики, белки яиц порубить (2 яйца оставить для украшения целыми), желтки растереть с горчицей, солью и сахаром, влить чуть кваса, размешать, добавить остальной квас, убрать на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8449,'Очистить и нарезать огурцы на кубики, укроп и треть зеленого лука мелко нашинковать, остаток лука растереть с солью, добавить мясо, яйца и картофель, перемешать, залить холодным квасом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8449,'Разлить окрошку мясную на квасе по тарелкам, положить в каждую по столовой ложке сметаны, по половинке яйца, чуть посыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Обжарить в кастрюле с маслом чеснок и лук.','https:https://st.vkuso.ru/data/cache/thumb/c6/2c4e72c17a213c6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Влить бульон, приправить паприкой, подсолить, дать закипеть.','https:https://st.vkuso.ru/data/cache/thumb/76/9cac591cc85c476_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Положить в бульон кусочки шампиньонов, проварить под крышкой примерно 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/b8/7e5c2b3002b86b8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Снять луково-чесночную похлебку с шампиньонами с плиты, крышку не снимать, дать постоять 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/aa/7e3beed0eca53aa_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Разрезать пополам перепелиные яйца и положить в похлебку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Обжарить с добавлением масла кубики хлеба со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/af/8b3dd33b80119af_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8450,'Подать похлебку с гренками и порезанной зеленью (можно положить в каждую тарелку).','https:https://st.vkuso.ru/data/cache/thumb/83/e330cd203513083_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Окорочка залить холодной водой, сварить бульон.','https:https://st.vkuso.ru/data/cache/thumb/73/f7dd4c54439a573_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Лук с чесноком порубить и обжарить в сливочном масле до изменения цвета в кастрюле с толстым дном.','https:https://st.vkuso.ru/data/cache/thumb/e3/db5b961826512e3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Горошек поставить размораживаться.','https:https://st.vkuso.ru/data/cache/thumb/78/6dce772fb516678_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Сельдерей с морковкой порезать на кубики, высыпать к луку, перемешать, жарить 5 минут на малом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Брокколи разобрать по соцветиям, черешки удалить, картофель порезать на кусочки небольшого размера.','https:https://st.vkuso.ru/data/cache/thumb/cc/802c5a7059767cc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Переложить все к овощам, присолить, перемешать, залить бульоном, варить до мягкости овощей (брокколи не переваривать).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'Чуть остывшее мясо порезать на полоски.','https:https://st.vkuso.ru/data/cache/thumb/ed/f966823d02041ed_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8451,'За 10 минут до готовности овощей положить спагетти, проварить куриный суп с брокколи и спагетти пару минут, всыпать горошек, добавить мясо.','https:https://st.vkuso.ru/data/cache/thumb/f9/c5df9568e3c98f9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Сушеные бананы измельчить на мясорубке или с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8452,'Нарезать на маленькие кубики язык, отварную говядину, ветчину и огурцы. Зеленый лук нашинковать и растереть с солью, яичные белки порубить. Желтки растереть со сметаной, солью, горчицей и сахаром, влить чуть кваса, перемешать долить остальной квас. Залить все ингредиенты квасом, размешать, разлить по тарелкам, присыпать измельченным укропом. Квас для приготовления окрошки сборной мясной надо брать хорошо охлажденный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8453,'Сахарозаменитель, например, стевию, соединить с кефиром, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8453,'Вымыть, очистить и натереть морковь, яблоко, смешать с сырым яйцом, кефиром, нежирным творогом. Добавить по вкусу молотую корицу и ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8453,'Вылить массу в формочку из силикона, поставить в горячую духовку, печь до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8454,'Мелко нарезать репчатый лук. Кабачок натереть на мелкой терке, лишнюю жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8454,'Добавить готовый фарш из курицы или индейки, сырые куриные яйца или только белки для диетического варианта.  Молотый перец, соль, тертый имбирь – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8454,'Сформовать из полученной массы небольшие котлеты. Для приготовления понадобится сковорода с антипригарным покрытием, либо обычная, смазанная растительным маслом. Жарить изделия с двух сторон, до образования румяной, аппетитной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8455,'Гречневую крупу залить стаканом кипятка, соль – по вкусу. Довести смесь до кипения, варить в течение пяти минут на среднем огне. Огонь убавить до слабого, накрыть кастрюлю крышкой, готовить полчаса. Добавить кусочек сливочного масла, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8455,'Отдельно сырые куриные яйца залить водой, нагреть до кипения, варить в течение 10 минут. Сразу переложить в холодную воду и очистить. Нарезать кубиками маленького размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8455,'Порубить перо зеленого лука, укроп, смешать с яйцом, приправить молотым перцем, солью, полить растительным маслом. Готовую гречку разложить в тарелки, на гарнир – зелень, кусочки крутых яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Натереть вымытую и очищенную морковь, нарезать репчатый лук, пропустить зубчики чеснока через пресс. Все ингредиенты перемешать с куриным фаршем, вбить сырой желток, соль, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Отдельно взбить в пышную пену белок и добавить в общую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Смешать тертый сыр с густой сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Руки смочить водой, сформовать из готового фарша лепешку, положить в середину сырную начинку, поверх – слой фарша.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Котлету обвалять в пшеничной муке, жарить на растительном масле, с двух сторон. Должна образоваться румяная корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Изделия переложить в форму для запекания, поставить в предварительно разогретую духовку, печь при температуре 180 градусов в течение 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Для приготовления грибного соуса мелко порубить лук и нарезать сырые шампиньоны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Растопить на сковороде сливочное масло, обжарить лук до прозрачного состояния. Всыпать грибы, прогревать до испарения жидкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'В конце приготовления обжарку посолить по вкусу, приправить молотым мускатным орехом. Влить сливки, перемешать, готовить 5-7 минут на тихом огне.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8456,'Перемешать воду с картофельным крахмалом, смесь тонкой струйкой влить в соус, помешивать, прогревать две минуты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8457,'Разобрать цветную капусту на соцветия. Хорошо промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8457,'В большой емкости смешать оливковое масло, рубленый чеснок, четверть стакана тертого сыра пармезан.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8457,'Добавить в масляную смесь цветную капусту, перемешать, она должна покрыться маслом и сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8457,'Выложить смесь на противень, застеленный фольгой. Посолить, поперчить по вкусу. Печь в духовом шкафу в течение 45 минут, поворачивать каждый 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8458,'Помыть и почистить огурцы, нарезать на кубики, белки яиц отделить от желтков и порезать на небольшие кубики, крабовые палочки тоже. Желтки растереть с перцем, солью, горчицей, сметаной и мелко порубленным укропом, перемешать, влить чуть кваса и перемешать до однородной массы, долить оставшийся квас и убрать на холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Для приготовления коржа залить овсяные хлопья йогуртом, можно взять обезжиренный с фруктовым вкусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Зажарку измельчить блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8458,'Редис нашинковать кружочками, смешать в глубокой миске с остальными подготовленными ингредиентами, залить охлажденной смесью кваса, размешать, разлить окрошку с крабовыми палочками по тарелкам, украсить веточками зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8459,'Мелко нарезать филе хека или тилапии.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8459,'Очистить и натереть репчатый лук и морковь, перемешать с рыбой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8459,'Влить в смесь сметану, вбить сырое куриное яйцо, добавить тертый сыр, соль и специи. Перемешать фарш ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8459,'Сформовать маленькие котлеты, жарить на сковороде, на растительном масле, на небольшом огне. Время приготовления – 3-4 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'Из муки, соли, масла, яиц и воды приготовить тесто, которое затем поместить в кондитерский мешок с диаметром отверстия 2 см и отсадить на застеленный бумагой для выпечки противень 30 шариков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'В течение 10 минут выпекать в духовке шарики при температуре 220 градусов, потом уменьшить до 180 градусов и выпекать еще 25 минут, готовые шарики остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'Для крема и посыпки на сковороде поджарить, а затем измельчить орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'Желтки смешать с водой, процедить, переложить в кастрюльку, добавить к ним сгущенное молоко и на медленном огне варить все, пока масса не загустеет (как заварной крем), после чего массу остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'До белого цвета взбить размягченное сливочное масло с сахарной пудрой, затем небольшими порциями добавить в сваренную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'В яично-масляную смесь влить коньяк, всыпать подготовленные орехи, тщательно взбить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'При помощи корнетика начинить готовым кремом через дырку каждый шарик, дать им остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'Помаду разогреть, добавить воду или ореховый ликер.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8460,'Каждое пирожное «Орешек» с ккремом, насадив на вилку, обмакнуть в помадку и сразу же посыпать орехами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'Яйца поместить в кастрюльку с водой,  дать воде закипеть и отварить яйца в пределах 10 минут, после чего залить холодной водой, чтобы они остыли, а затем мелко натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'Измельчить на мелкой терке  крабовые палочки, так же измельчить и сыр (на мелкой терке).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'Выложить в салатник подготовленные яйца, сыр, ½ часть крабовых палочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'К ингредиентам добавить майонез и раздавленный в чесночнице чеснок, перемешать все до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'Из получившейся массы скатать шарики, размер которых не больше мячика для настольного тенниса, каждый из них запанировать в оставшейся части крабовой стружки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8461,'На тарелку выложить сырно-крабовый салат шариками «Рафаэлло», украсить зеленью и порезанной крабовой палочкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'Всыпать манную крупу в холодное молоко, перемешать и поварить в течение 5 минут до загустения, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'Яичные желтки взбить со 100 г сахара, влить в творог, добавить ванилин и взбить все миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'В получившуюся смесь добавить манную массу, еще раз взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'С оставшимся сахаром взбить белки, добавить их в творожно-манную массу и перемешать, по желанию добавить изюм и/или цедру лимона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'Выложить тесто в заранее смазанную растительным маслом форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'Выпекать творожно-манный пудинг с изюмом в духовом шкафу при 180 градусах до появления золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8462,'Готовый пудинг остудить, при желании можно подать его со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Выжать из апельсина и лимона сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'В кипящую воду влить апельсиновый и лимонный сок, положить лавровый лист, горошки черного перца, присолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Добавить все морепродукты, после повторного закипания убрать с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Отварить отдельно в подсоленной горячей воде фасоль около минуты, откинуть на дуршлаг, облить ледяной водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Для заправки средиземноморского салат из морепродуктов и фасоли смешать в мисочке чеснок, раздавленный прессом, сок лайма и масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Помидоры порезать на половинки, базилик и зелень порубить, сельдерей мелко порезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8463,'Поместить все в большую глубокую миску, добавить морепродукты и фасоль, поперчить, присолить, залить заправкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Натереть морковь на мелкой терке, на крупной – яблоки или грушу, или и тот и другой продукт в равных пропорциях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Мелко нарезать ананас, добавить в полученное тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Нарезать хорошо вымытые и обсушенные сухофрукты, сушеную клюкву. Добавить пекарский разрыхлитель. Массу еще раз хорошо перемешать и выложить в форму для выпечки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Поверхность будущего пирога хорошо разровнять. Печь корж в течение 50 минут при температуре 160 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Для крема взбить с помощью блендера чернику с йогуртом, добавить творог. Поставить емкость в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8464,'Остудить корж, выложить на него крем с черникой, поставить десерт в холод на несколько часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'Филе положить на рабочую поверхность, накрыть пищевой пленкой и немного отбить ребром ладони.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'На сухую сковороду без масла насыпать черный перец, кориандр, зиру, жарить на среднем огне две минуты, пряности должны усилить свой аромат, но не подгореть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'Растолочь пряную смесь в ступке с помощью пестика, добавить очищенный чеснок, немного соли, все вместе растереть еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'Мелко порубить кинзу, добавить к пряностям вместе с куркумой и тертым пармезаном, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'Влить небольшое количество оливкового масла, взбить. Масса должна получиться похожей на пюре с комочками. При необходимости добавить соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8465,'Полученной сложной смесью натереть филе, положить его в пароварку и готовить в течение 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8466,'Филе пропустить через мясорубку, смешать с рубленным репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8466,'Перемешать сырые куриные яйца с чесноком и зеленью, измельчить с помощью мельницы или блендера, добавить в фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8466,'Всыпать просеянную пшеничную муку, соль и перец, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8466,'Сформовать шарики мокрыми руками, выложить в пароварку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8467,'В сырые куриные белки добавить немного лимонного сока, взбить в плотную пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8467,'Ложку агар-агара положить в воду, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8467,'Тонкой струйкой влить желеобразную массу в белковую, при этом смесь должна находиться в работающем миксере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8467,'Продолжать взбивать, добавить сахарозаменитель, разведенный в воде протеин – по желанию. Также можно добавить любой ароматизатор.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8467,'Массу быстро переложить в форму и поставить в холодильник. После застывания разрезать десерт на кусочки или подать его с ложечкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'Мелкими кубиками нарезать морковь,  репчатый лук и стеблевой сельдерей, мелко нарезать очищенный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'В кастрюле с оливковым маслом обжарить до мягкости подготовленные овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'Из говядины при помощи мясорубки сделать фарш, который затем добавить к уже мягким после обжарки овощам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'В кастрюлю также добавить перец и соль, жарить, постоянно помешивая, до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'Далее к мясу добавить орегано, томатное пюре (не путать с томатной пастой!), базилик и, периодически помешивая, тушить не меньше 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'По прошествии 5 минут в кастрюлю влить горячую воду и тушить все на маленьком огне на протяжении 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'В соответствии с инструкцией приготовить пасту, откинуть ее на дуршлаг.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'Добавить в готовый соус сливки комнатной температуры или хотя бы подогретые.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'В соус опустить макароны, хорошенько перемешать и все переложить в форму, обильно посыпать крупно натертым сыром «Моцарелла».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8468,'Выпекается паста с соусом болоньезе в духовке при 200 градусах до полного зарумянивания, подается к столу в горячем виде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Сырое куриное яйцо разделить на желток и белок, взбить то и другое по отдельности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'В желтковую массу вмешать геркулес, отруби и стевию. Ввести взбитый белок, сделать это аккуратно, движениями снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Разогреть духовку, выпечь получившуюся массу в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8469,'Белок и желток второго яйца также взбить по отдельности. В желток добавить творог, стевию, влить нежирное молоко и распущенный агар-агар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8470,'Вымыть яблоки, удалить сердцевину и кожицу. Из мякоти приготовить пюре с помощью блендера или натереть на терке с мелкими ячейками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8470,'Залить массу охлажденным кефиром и взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8470,'В готовый напиток добавить молотую корицу на кончике ножа, натуральный мёд, снова взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8470,'Разлить коктейль в бокалы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8471,'Творог разделить на две части. В первую добавить натуральный мёд и сметану, во вторую – сахарную пудру и свежую клубнику. Обе смеси взбить при помощи блендера до образования пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8471,'Застелить стол пищевой пленкой, равномерно присыпать розовой кокосовой стружкой, сверху – творожная смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8471,'Разрезать чернослив на половинки, выложить на творог, отступить от края. Завернуть творожную массу в рулет, помогая себе пищевой пленкой. Рулет еще раз обернуть пленкой, уплотнить, придать круглую или квадратную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8471,'То же самое проделать с клубничной смесью и кокосовой стружкой белого цвета. Чернослив заменить на четвертинки свежего банана, нарезанного вдоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8471,'Рулеты убрать на полчаса в холодильник. Когда масса охладиться и станет плотной – её можно будет нарезать на «роллы».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8472,'Репчатый лук очистить и нарезать, потушить, не допуская подрумянивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8472,'Куриные сердечки хорошо вымыть холодной водой, удалить сосуды и лишний жир, выложить на сковороду. Прогревать на среднем огне, помешивать. Субпродукт должен потерять розовый цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8472,'Влить натуральный йогурт без цветовых и вкусовых добавок, перец молотый и соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8472,'Содержимое сковороды перемешать, огонь убавить, тушить под крышкой в течение получаса. При готовности сердечек, они должны стать мягкими, крышку снять, выпарить оставшуюся жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Свежие огурцы вымыть, разрезать на половинки, затем – ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Промыть помидоры, разрезать пополам или на четыре части. Для салата лучше использовать мелкие плоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Слить жидкость от консервированной фасоли, выложить содержимое банки в салатницу. Сверху – нарезанные овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Тунцовое консервированное мясо покрошить вилкой на крупные кусочки, выложить поверх овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Красный лук нарезать полукольцами, украсить салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8473,'Готовое блюдо сбрызнуть свежим лимонным соком и оливковым маслом, можно добавить немного итальянских трав, соль и молотый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8474,'Перемешать постный говяжий фарш, соль, петрушку, чеснок, молотый перец и тмин, вбить яйцо и еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8474,'Получившийся фарш разделить на 20 частей и из каждой сформовать фрикадельки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8474,'Измельчить с помощью блендера репчатый лук, молотый черный перец, помидоры, мускатный орех и соль, полученную массу переложить в кастрюлю, добавить томатную пасту, довести до кипения и уменьшить огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8474,'В соус осторожно поместить все фрикадельки, закрыть крышкой и на маленьком огне тушить 40-45 минут, помешивая время от времени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8474,'Подать готовые фрикадельки говяжьи в томатном соусе к столу, предварительно украсив свежей петрушкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8475,'Приготовить салат по традиционному рецепту: мелко нарезать крабовые палочки, покрошить отваренные яйца, отварить рис, перемешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8475,'Сформовать шарики, обвалять их в тертом сыре, выложить на тарелку в виде пирамиды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8476,'Сырой картофель очистить и натереть на терке, слить лишнюю жидкость, массу посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8476,'Тонким слоем выложить массу на смазанную маслом, разогретую сковороду. Жарить до румяной корочки с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8476,'Малосольное селедочное филе нарезать полосками вдоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8476,'Выложить на картофельную лепешку зеленый сельдь, зеленый салат, свежий нарезанный огурец, любую зелень. Завернуть рулетом, нарезать поперек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8477,'Растопить на сковороде сливочное масло, всыпать ложку сахарного песка, перемешать, выложить измельченные яблоки, посыпать молотой корицей, потушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8484,'Треугольники выложить на противень, печь при температуре 180 градусов от 20 до 25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8477,'На тонкий лаваш насыпать ложку сухарей, выложить яблоки, концы завернуть, свернуть рулет. Точно так же поступить со вторым изделием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8477,'Сверху смазать маслом или полить сливками, посыпать сахаром. Время выпекания – 20 минут, температура – 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8478,'Тыкву очистить от кожицы и семечек, мякоть натереть на крупной терке, потушить до готовности на сковороде, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8478,'Всыпать сахарный песок, манную крупу, перемешать, долить молоко и положить ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8478,'Массу прогреть в течение трех минут. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8478,'Сформовать котлеты, запанировать в сухарях или в муке. Жарить с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8479,'Масло соединить с молоком, прогреть до растаивания масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8479,'Перемешать продукты с помощью миксера или блендера, масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8479,'До взбивания продукт охладить в холодильнике в течение пяти или шести часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Смешать муку с солью и сахаром, влить воду, добавить чуть взбитые яйца, дрожжи активированные и замесить тесто – эластичное и гладкое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Смазать миску маслом, переложить в нее замешенное тесто, на 40 минут поставить в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Уже подошедшее тесто поделить на 5 кусков, каждый из которых раскатать в круг 25 см в диаметре и  промазать заранее растопленным сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Для начинки смешать сливочное масло с брынзой, разделить массу на 5 частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'По каждому уже промазанному кругу теста равномерно распределить подготовленную начинку и скрутить рулеты, которые надо слегка перекрутить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Форму диаметром 30 см и с высокими бортиками обмазать маслом, выложить в нее пирог следующим образом: необходимо по очереди закручивать тесто по нетугой спирали (во время выпекания пирог увеличится в 2 раза), когда пирог будет уложен, поставить форму на 20 минут для расстойки в теплое место.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Для заливки надо чуть-чуть взбить яйца с сахаром, влить молоко и получившейся смесью залить пирог.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'При 180 градусах пирог с брынзой по-болгарски выпекать в духовке на протяжении 45 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8480,'Когда пирог будет полностью готов, его необходимо на 10-15 минут накрыть льняным полотенцем, а уже потом подавать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8481,'Новое – хорошо забытое старое, простой и сытный завтрак для детей и взрослых.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8481,'Белый или черный хлеб нарезать ломтиками в сантиметр толщиной, в середине сделать отверстия для яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8481,'Выложить на сковороду, вбить сырые яйца, подождать, когда свернутся, перевернуть, положить сыр и прогреть бутерброды под крышкой. Сыр должен расплавиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8482,'Спелый авокадо нарезать тонкими ломтиками, выложить на заранее подсушенный в тостере хлеб. Поперчить и посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8482,'Сбрызнуть любым растительным маслом, например, оливковым. Сверху по желанию положить по кусочку колбасы, сыра или любого овоща.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8483,'В муку всыпать соль, порубить охлажденное сливочное масло вместе с мукой. Влить немного холодной воды с добавлением лимонного сока. Готовое тесто скатать в шар, поставить в холод на 30 или 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8483,'Тесто раскатать, выложить в форму для выпекания, сформовать бортики. Положить груз (можно использовать горох или чечевицу, насыпанную на бумагу для выпекания), печь в духовом шкафу в течение 12 минут. Затем груз вынуть, прогревать корж еще шесть минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8483,'Очистить и натереть свежую тыкву, потушить до готовности на сковороде, жидкость должна выпариться, посолить по вкусу. Превратить начинку в пюре при помощи блендера, добавить сгущенное молоко, яйца, имбирь, корицу и гвоздику, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8483,'Выложить начинку на корж, печь в течение 40 минут, температура – 175 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8484,'В муку всыпать соль, немного разрыхлителя, натереть охлажденное сливочное масло. Ингредиенты перетереть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8484,'Перемешать молотую корицу с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8484,'Тесто поделить на кусочки, каждый раскатать в лепешку, можно сделать это скалкой или сформовать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8504,'Наполнить перцы, поставить их в соус, потушить в течение сорока минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8485,'Грудки мелко нарезать, положить в горшочек, добавить зелень и нарезанный помидор, положить специи, соль, лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8485,'Налить воду, она должна покрывать мясо. Перемешать, поставить блюдо на час в духовой шкаф, готовить при температуре 180 – 200 градусов. Вода не должна выкипеть, при необходимости её можно подлить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8486,'Сырые куриные белки смешать с одним целым куриным яйцом. Добавить половину очищенного банана, ложку овсяной муки, растворенный в горячей воде сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8486,'Массу переложить в блендер, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8486,'Вылить смесь на сковороду с антипригарным покрытием, без масла. Сверху выложить нарезанное кубиками яблоко, очищенное от семенных камер. Будущий пирог посыпать молотой корицей, накрыть крышкой, прогревать на очень тихом огне, пока «Шарлотка» не поднимется.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8487,'Сварить и остудить свеклу, картофель и морковь. Морковь, огурцы, свеклу нарезать на мелкие кубики, картофель измельчить на терке. Перья зеленого лука нашинковать и растереть с солью до мягкости и выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8487,'У вареных яиц отделить желтки и растереть с горчицей, белки мелко покрошить. Перемешать лук, картофель, сметану и желтки, добавить овощи, огурцы, сахар, залить холодным квасом, дать чуть постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8487,'Разлить окрошку овощную по тарелкам, добавить в каждую мелко нашинкованную зелень укропа. Вместо моркови и свеклы для приготовления блюда можно взять репу и цветную капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Для приготовления коржа перемешать шоколадный протеин, овсяную муку, клетчатку, перезрелый банан, яичные белки, дополнительное целое яйцо. В массу по желанию можно добавить отруби.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Влить молоко или воду, довести до консистенции бисквитного теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Массу переложить в форму и выпечь до готовности при температуре 180 градусов. Готовность блюда проверить спичкой или зубочисткой: она должна остаться сухой. Торт остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Отдельно развести растворимый кофе, пропитать корж.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Для приготовления суфле развести желатин в молоке, прогреть до растворения, но не кипятить. Перелить массу в чашу блендера, добавить оставшееся молоко, добавить протеин со вкусом крема, взбить массу в течение минуты на большой скорости. Дать смеси постоять в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Пять белков подержать в холодильнике, затем взбить в плотную пену с каплей лимонного сока. В белковую массу постепенно ввести основную протеиновую смесь, сахарозаменитель добавить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Готовую массу выложить на выпеченный бисквит, поставить в холодильник на два часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Для приготовления глазури смешать какао-порошок без сахара с водой или молоком, добавить сахарозаменитель, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8488,'Должна получиться смесь средней густоты. После застывания покрыть торт полученной глазурью с помощью кулинарной кисти.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Приготовить тесто для блинчиков: смешать сырые куриные белки и одно дополнительное целое яйцо с овсяными отрубями, клетчаткой, сахарозаменителем. Добавить протеин со вкусом шоколада или овсяную муку, молоко. Масса должна быть жидкой, как для блинчиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Накалить сковороду с антипригарным покрытием, налить тесто, поставить на средний огонь. Жарить по 30 секунд с каждой стороны или только с одной. Таким же способом выпечь до десятка блинов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Для начинки смешать творог с протеином, добавить сахарозаменитель, взбить в крем с помощью блендера. Можно добавить немного молока, если масса получилась суховатой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Желатин залить молоком, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Половину смеси влить в ягодный или фруктовый джем, вторую половину – в творожную массу, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8489,'Собрать торт: первый блин смазать творогом, второй – джемом, так проделать со всеми блинами, начинка должна чередоваться. Верх десерта смазать творогом, украсить по желанию и поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8490,'Нарезанный на квадраты хлеб посушить, смазать сливочным маслом, выложить по пластинке сыра. Каждый квадрат разрезать на два треугольника. Тонко нарезать колбасу, наколоть на зубочистку в виде парусов. Установить на хлеб, флажок можно сделать из кусочка свежего огурца или сладкого перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8490,'Другой вариант выложить на хлеб колбасу, затем листья зеленого салата. Божью коровку сделать из помидоров черри, маслин, глаза – из майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8490,'Третий вариант: приготовить начинку из тертого сыра и майонеза, можно добавить зелень. Тонко нарезать колбасу, выложить сырную начинку, свернуть кулечки и сколоть их зубочисткой. Выложить на кусочки хлеба прямоугольной формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8491,'Нарезать яблоки некрупными кубиками, полить лимонным соком, чтобы не почернели. Добавить в массу молотую корицу, ванилин, изюм и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8491,'Отдельно приготовить массу из творога, овсяной муки и йогурта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8491,'Обе смеси соединить, еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8491,'Массу выложить в формочки из силикона, поставить в духовку, печь в течение получаса или чуть больше при температуре 180 – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8491,'Остудить десерт в формочках, осторожно вытащить, посыпать молотой корицей и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8492,'Сварить картофель в мундире и яйца, дать остыть, очистить, измельчить на терке вместе с огурцами (шкурку почистить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8492,'Нашинковать мелко репчатый лук, растереть до выделения сока, измельчить укроп и перья зеленого лука, нарезать колбасу на кубики, подсолить, добавить майонез, горчицу, осторожно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8492,'Взбить кефир с газированной минеральной водой 1:1, залить полученную смесь. Воду для окрошки на минеральной воде с кефиром надо выбирать нейтрального вкуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8493,'Отварить говядину. Нарезать мясо кубиками среднего размера, перемешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8493,'Покрошить репчатый лук. Измельчить орехи, чернослив, зелень, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8493,'Нарезать кубиками баклажан, посолить, оставить на полчаса, чтобы ушла горечь, промыть проточной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8493,'На сковороде обжарить лук, добавить баклажаны, довести до мягкости, добавить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8493,'Выложить на тарелку слой мяса, затем чернослив, майонез, посыпать орехами. Следующие слои: баклажаны, майонез, орехи, зелень. Смазать бока майонезом, посыпать орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8494,'Чиабатту или другой вкусный хлеб нарезать, подсушить в духовом шкафу или в тостере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8494,'Помидоры нарезать толстыми ломтиками, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8494,'Моцареллу нарезать чуть тоньше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8494,'Выложить на хлеб по кружку сыра, помидора, по листочку базилика, слои можно повторить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8494,'Полить готовую закуску оливковым маслом и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8495,'Смешать сырой яичный белок, протеин, кокосовое масло, какао-порошок и соду, погашенную уксусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8495,'Массу взбить с помощью блендера, добавить овсяную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8495,'Противень застелить фольгой или пергаментом. Мокрыми руками сформовать из полученной массы шарики, расплющить в небольшие печенья.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8495,'Печь в течение 8 – 10 минут. Выпечку охладить и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8496,'Смешать тимьян, крупную морскую соль, молотый черный перец, замариновать в смеси яичный желток на 6 часов, осторожно промыть. В квас добавить горчицу и молотый черный перец, поставить охлаждаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8496,'Почистить огурец, удалить семена, нарезать на кубики, поставить греть воду, подсолить. Стебель сельдерея и петрушку (корень) порезать на кубики, бланшировать в кипящей воде, добавить мороженый зеленый горошек. Почистить кусочек корня имбиря, мелко нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8496,'Нагреть сковороду, быстро обжарить морской гребешок, нарезать лосось крупными кубиками, редис нашинковать тоненькими кружочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8496,'Разложить в тарелки смесь всех ингредиентов, залить холодным квасом, посолить. Украсить окрошку с лососем и гребешками веточкой базилика, положить в каждую порцию по столовой ложке сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Сварить картофель в мундире, очистить, остудить, нарезать на кубики. Молодую свеклу нарезать (вместе с ботвой) на кубики, отварить в 2 стаканах воды, дать ботвинье остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Налить масло в кастрюлю, постепенно всыпать муку и вымесить до однородной массы, нагреть на среднем огне, влить, постоянно помешивая, теплую сыворотку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8505,'Соединить горчицу со сметаной, добавить соль и перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Взбить смесь сметаны с кислым молоком, добавить небольшое количество муки с маслом и горячей сыворотки, хорошо перемешать, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Натереть половинку свеклы урожая прошлого года, отжать сок, вылить в кастрюлю к сыворотке, добавить отварную молодую свеклу вместе с ботвой и отваром, перемешать, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Разложить порции картофеля по тарелкам, залить смесью сыворотки и ботвиньи. Сверху ботвинью на сыворотке и кислом молоке посыпать нашинкованным укропом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8497,'Для блюда надо взять молодую свеклу с ботвой и старую из урожая прошлого года.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8498,'Смешать кефир, молоко, соль и паприку в хлопьях. Смесь поставить на водяную баню, прогреть до образования хлопьев, но не кипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8498,'Перелить массу в ситечко с марлей, дать стечь сыворотке в течение двух часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8498,'Придавить полученную массу грузом в один килограмм, поставить в холодильник. Сыр будет готов через два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8499,'В небольшую кастрюлю положить быстрозамороженный горох, рубленую петрушку, сахарный песок, соль по вкусу. Залить смесь холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8499,'Довести до кипения, огонь убавить и варить еще 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8499,'Готовый горох вместе с отваром превратить в пюре с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8499,'Добавить сливки, довести до кипения на тихом огне, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8499,'Суп досолить при необходимости, всыпать любимые специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8500,'Отварить яйца и мякоть баранины, остудить, нарезать на маленькие кубики, взбить кефир с водой, убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8500,'Почистить огурцы и нарезать мелко вместе с луком, порубить зелень укропа. Смешать все ингредиенты, залить смесью кефира. Дать ашхабадской окрошке с бараниной полчаса настояться в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Для приготовления коржа перемешать муку с солью и сахаром, добавить разрыхлитель, нарезанное охлажденное сливочное масло. Продукты перетереть в крошку. Вбить желток, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Переложить массу в форму, наколоть вилкой, поставить в морозильную камеру на 20 или 30 минут. Время выпекания – от 10 до 12 минут, температура – 175 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Для прослойки взбить белок с солью, сахар всыпать порциями. Ввести обычную и миндальную муку, выложить на застеленный пергаментом противень в виде круглой лепешки. Посыпать сахарной пудрой, печь при 190 градусах, время – от шести до семи минут. Бумагу снять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Для первого чизкейка перемешать сливочный сыр с жирными сливками, сырыми куриными яйцами, сахаром, любым фруктовым пюре. Если пюре не очень сладкое, то норму сахарного песка можно увеличить. Яйца вводить по одному.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Вылить полученную массу на основание, печь в течение получаса, температура – 165 градусов. В духовку под чизкейк поставить емкость с водой. Изделие остудить, дать постоять в холодильнике в течение пяти или шести часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Для приготовления второго чизкейка растопить белый шоколад, добавить сливочный сыр, сливки, ванильный сахар из пакетика, ягоды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8501,'Выложить белковую прослойку на первый чизкейк, затем ягоды, залить смесью для второго чизкейка. Торт положить в холод до застывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8502,'Натереть сыр, смешать с рубленой зеленью, чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8502,'Нарезать полосками тонкий лаваш, завернуть в него сырную начинку, обернуть два раза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8502,'Палочки обмакнуть в яйцо и обвалять в сухарях, жарить с двух сторон до румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8503,'Отварить говядину, картофель и свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8503,'Мясо нарезать тонкой соломкой, овощи и яблоко натереть на крупной терке. Морковь по-корейски немного измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8503,'Собрать салат: нижний слой – говядина, затем яблоко, майонез, картофель, майонез, свекла, морковь, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8504,'Подготовить сладкий болгарский перец, вынуть семенные камеры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8504,'Морковь, лук и кабачок измельчить и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8504,'Перемешать рис, заранее отваренный до полуготовности, мясной фарш, большую часть овощей, посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8504,'К оставшимся овощам добавить помидоры или томатный соус, немного воды, смесь довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8505,'Выложить слои в следующем порядке: лук, сельдерей, яблоко, заправка, натертое отваренное яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8506,'Сварить яйца, дать остыть, порубить, вымыть картофель, отварить (не чистить), дать остыть, очистить и порезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8506,'Срезать с огурца шкурку, нарезать на небольшие кубики, редис нашинковать кружочками, вареную колбасу (можно мясо) нарезать на такие же кубики, перья зеленого лука мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8506,'Все ссыпать в глубокую миску, добавить соль, аккуратно перемешать, залить холодным пивом. Дать окрошке с колбасой на пиве немного настояться, разлить по тарелкам, добавить (по желанию) по ложке сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Отварить курицу, нарезать кубиками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Отваренную морковь, маринованные огурцы, репчатый лук нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Обжарить грибы с луком до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Натереть сыр, половину перемешать с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Выложить продукты слоями: куриное мясо, грибы, огурцы, отваренная морковь, майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8507,'Посыпать оставшимся сыром, свежей рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'С помощью миксера взбить в пену сырые куриные яйца, добавить любой сахарозаменитель, клетчатку, ванилин, корицу, протеин и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'Массу хорошо перемешать, можно сделать это с помощью вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'Тесто вылить в формочки и поставить в духовку на 10 минут, температура приготовления – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'Готовую выпечку разрезать на три части по горизонтали, лучше делать это острым ножом, чтобы выпечка не развалилась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'Аминокислоты развести с водой, пропитать жидкостью коржи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8508,'Для приготовления крема смешать творог с протеином, можно использовать продукт с клубничным вкусом. Собрать коржи, промазывая каждый готовым творожным кремом. Поставить блюдо в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8509,'Грудку промыть, нарезать нетолстыми длинными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8509,'Залить кефиром, добавить соль и специи, поставить в холодильник для маринования на полтора-два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8509,'Смешать овсяные отруби с пряными травами и паприкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8509,'Обвалять кусочки мяса в овсяной смеси, поставить в разогретую до 180 градусов духовку, печь в течение 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8510,'Картофель, отварить в мундире, дать остыть, очистить и порезать на кубики, мелко нарубить отварные яйца. Очистить от шкурки огурцы, измельчить на терке вместе с редиской.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8510,'Нарезать маленькими кубиками салями, перья зеленого лука нашинковать и растереть с солью. Все ингредиенты сложить в кастрюлю, залить холодным кефиром и газированной водой, посолить, перемешать. Для любителей слегка кислого вкуса в окрошку с салями на кефире и газированной воде можно добавить яблочный уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8511,'Шампиньоны обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8511,'Отдельно смешать оливковое масло, столовый уксус, готовую столовую горчицу, рубленый чеснок, молотый перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8511,'Грибы выложить в полученный соус и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8511,'Вымыть помидоры черри и салат «Ромен», свежий огурец. Нарезать. Салат порвать руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8511,'Продукты выложить в салатницу, сверху – грибы, сбрызнуть остатками соуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8512,'Рис отварить в подсоленной воде до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8512,'Измельчить морковь и лук, обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8512,'Перемешать рис с половиной овощей, поперчить и посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8512,'Жесткую часть кочана пекинской капусты срезать, оставшуюся разобрать на листья.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8512,'Мясной фарш и рис выложить на листья, свернуть трубочками. Выложить на сковороду с оставшимися овощами, подлить томатный сок, потушить до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8513,'Для приготовления начинки в емкость с толстым дном насыпать сахарный песок, поставить на огонь. Жирные сливки прогреть до кипения, ввести их в карамелизованный сахар, помешивать. Прогреть смесь до полного растворения комков, всыпать ванильный сахар, половину нормы соли, нарезанные яблоки без кожицы. Потушить начинку до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8513,'Для приготовления штройзеля охлажденное сливочное масло, муку, сахар, перетереть в крошку и поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8513,'Для приготовления основы мягкое масло комнатной температуры перетереть с остатками сахарного песка, ввести сырые яйца по одному, всыпать соль, часть муки и разрыхлитель, влить молоко. Перемешать, всыпать оставшуюся муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8513,'Форму для выпекания кекса смазать маслом, присыпать мукой, выложить тесто. На основу положить яблочную начинку, посыпать масляной крошкой. Время выпекания – 35 минут, температура – 165 градусов. Выпечку остудить, вынуть из формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Куриное мясо с ножек, белые грибы, картофель, морковь, баклажан и репчатый лук нарезать кубиками среднего размера. Часть картофеля можно нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Белые грибы не нуждаются в предварительной термальной обработке, их нужно просто нарезать. Если грибы другие – их отваривают в кипятке в течение пяти минут, а затем измельчают.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Кубики картофеля перемешать с куриным мясом, посолить и поперчить, пластинки – посолить и перемешать со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Разложить мясо с картофелем в горшочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Лук обжарить, добавить грибы, прогреть до выпаривания лишней влаги, посолить и выложить поверх мяса с картофелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Баклажаны и морковь обжарить в течение трех минут, посолить по вкусу, выложить поверх грибов, сверху – пластинки картофеля.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Тушить в духовке под крышкой, температура – 200 градусов, время – от 30 до 40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8514,'Посыпать тертым сыром, поставить в духовой шкаф на 10 минут без крышки. Сыр должен расплавиться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8515,'Белки и желтки разделить. Первые взбить со щепоткой соли, вторые – с солью и перцем. То и другое можно сделать при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8515,'Ингредиенты соединить, всыпать муку, вымешать, выложить на пергамент. Время выпекания – 10 минут, температура – 165 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8515,'Измельчить чеснок, нарезать лук, обжарить вместе. Добавить грибы, прогреть, в последнюю очередь положить помидоры. Прожарить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8515,'Выложить грибную начинку на готовый омлет, посыпать тертым сыром, аккуратно свернуть рулетом, нарезать поперек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8516,'Приготовить маринад из чеснока, измельченной зелени, лимонного сока, паприки, соли, черного перца и растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8516,'Удалить косточки из слив. В куске свиного карбонада сделать глубокий надрез в виде кармана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8516,'Натереть мясо маринадом со всех сторон и внутри, нафаршировать сливами, сколоть шпажкой, оставить на час для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8516,'Прогревать в заранее разогретой духовке при температуре 250 градусов в течение получаса, перевернуть, температуру снизить на 50 градусов, печь  еще 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8516,'Снизить температуру до 180 градусов, накрыть мясо фольгой и готовить еще 40-50 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8517,'Сварить яйца и картофель, дать остыть, очистить, желтки порубить, картофель и белки нарезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8517,'Нашинковать редис кружочками, зелень порубить, колбасу и огурцы нарезать на кубики, огурцы также можно натереть на терке. Зеленый лук немного примять для появления сока. Все переложить в глубокую миску, посолить, аккуратно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8517,'Разложить по тарелкам, залить хорошо охлажденным квасом, подавать окрошку с колбасой на квасе классическую со сметаной и измельченной зеленью. Вместо кваса можно использовать воду с лимонной кислотой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8518,'Нашинковать белокочанную капусту, помять с солью, чтобы она дала сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8518,'Отдельно отварить куриное филе, разобрать на волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8518,'Испечь блинчики по любимому рецепту, тонко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8518,'Все ингредиенты перемешать, заправить натуральным йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8519,'Очистить и натереть на мелкой терке морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8519,'Промыть сушеный инжир и крупную курагу, замочить в теплой воде на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8519,'Сложить ингредиенты в чашу блендера, добавить мякоть и цедру апельсина. Взбить смесь в однородную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8519,'Сформовать шарики, внутрь положить по орешку кешью, обвалять в кунжутном семени или кокосовой стружке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8519,'Положить изделия в морозильную камеру. В застывшем виде конфеты можно переложить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'Нарезать сырые шампиньоны тонкими пластинками, положить в смесь оливкового масла и соевого соуса, дать постоять для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'Цветную капусту разобрать и измельчить в блендере. Полить смесью лимонного сока и кунжутного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'Нарезать сырой огурец и морковь соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'Выложить листья зеленого салата на лист нори, сверху – слой цветной капусты, которая заменит рис, грибы, полоски овощей, кусочки любой красной рыбы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'При помощи циновки роллы туго скрутить, «шов» смазать водой, сбрызнуть всю поверхность изделия.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8520,'Дать постоять в течение пяти минут для пропитывания. При подаче нарезать на шесть-восемь частей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8521,'Крепкие, не переспелые, бананы нарезать, положить в морозильную камеру на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8521,'Продукт взбить с помощью блендера с какао-порошком и размороженной вишней.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8521,'Готовую смесь подать в порционной посуде, например, в креманках.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8522,'Сварить куриное мясо, вынуть, дать остыть, нарезать на небольшие кубики, бульон также остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8522,'Сварить яйца, картофель, остудить, нарезать на кубики, огурцы очистить и нарезать, редис нашинковать тонкой соломкой, измельчить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8522,'Все смешать, подсолить, добавить чуть черного молотого перца, залить холодным бульоном, заправить смесью майонеза и сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8522,'Для придания окрошке на курином бульоне пикантного вкуса можно добавить горчицу и  уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8523,'Только красный или смесь разноцветных болгарских перцев нарезать соломкой, семенные камеры удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8523,'Вымыть шампиньоны, немного обсушить, нарезать кусочками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8523,'Обжарить продукт на сковороде вместе с кусочками куриной грудки. Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8523,'Сыр натереть на крупной терке, добавить в общую массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8523,'Салат не нужно солить и перчить, заправить смесь соком лимона, выложить в салатницу и украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'Промыть куриное филе, хорошо отбить на рабочей поверхности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'Отдельно смешать молотый перец с солью, смесью натереть мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'В чашу мультиварки налить воду, выложить филе, нарезанный кружочками репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'Сверху – натуральный йогурт, вылить по половине столовой ложки на филе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'Также на каждое филе положить по кружку помидоров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'Поставить режим «Тушение» на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8524,'После окончания приготовления посыпать блюдо тертым твердым сыром и прогреть еще пять-семь минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8525,'Измельчить с помощью блендера в равных количествах изюм, курагу, финики без косточек, добавить грецкие орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8525,'Из готовой смеси сформовать шарики, оставить для подсыхания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8526,'Сварить яйца и картофель, нарезать небольшими кусочками. Разрезать охотничьи колбаски вдоль на 2 половины, а затем нарезать поперек на тоненькие кусочки. Вареную колбасу нарезать на кубики, очистить огурец от толстой шкурки и нарезать также.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8526,'Редис разрезать на четвертинки и каждую нашинковать, порубить укроп, нарезать мелко перья зеленого лука. Все аккуратно смешать, посолить, добавить майонез, размешать и залить хлебным квасом. Дать окрошке с охотничьими колбасками чуть постоять, разлить по тарелкам, добавить в каждую укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8527,'Черный шоколад растопить на водяной бане со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8527,'Всыпать сахар и соль, ванилин, массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8527,'Ввести сырые куриные яйца по одному, всыпать разрыхлитель и какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8527,'Добавить измельченный шоколад или дропсы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8527,'Печь в течение 25 минут в квадратной форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8528,'Перемешать муку с манной крупой, солью, сахаром и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8528,'Очистить яблоки от кожицы и семенных камер, натереть и добавить клюкву или бруснику.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8528,'Треть полученной мучной смеси выложить в форму, следующий слой – яблоки, тертое сливочное масло, затем снова сухие продукты, оставшуюся начинку, еще немного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Растопить сливочное масло, смешать его с мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8528,'Сверху – остатки мучной смеси и тертое масло. Время выпекания – 40 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8529,'Промыть опята в проточной воде, отварить в кипятке в течение пяти минут. Воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8529,'В свежую закипевшую воду положить грибы, соль, сахар, лавровый лист, перец-горошек, гвоздику.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8529,'Перемешать, довести до кипения, пену снять, варить до полной готовности. Влить уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8529,'Подготовить банки, разложить грибы до плечиков. Маринад еще раз довести до кипения, прокипятить листья смородины и укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8529,'Укроп и листья смородины разложить в банки поверх грибов, залить жидкостью, закрыть крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Перемешать в крошку разрыхлитель с мукой, солью, сахарным песком и тертым сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Добавить в массу сметану, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Форму смазать маслом, распределить тесто, поставить на полчаса в морозильную камеру. Потом в духовой шкаф на 10 минут, температура – 175 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Очистить яблоки, нарезать мелкими кусочками, потушить со сливочным маслом на сковороде, добавить сахар по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Перемешать крахмал с сахаром, ванилью, сырыми яйцами, молоком, довести крем на плите до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8530,'Выложить яблочную начинку на основание, крем – сверху. Печь в духовке 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8531,'Капусту брокколи отварить в кипящей воде в течение десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8531,'Накрошить лук и чеснок, обжарить, влить сухое белое вино, половину жидкости выпарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8531,'Влить сливки, довести соус до кипения, переложить брокколи и измельчить все блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8531,'Соль и перец молотый – по вкусу. Довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8532,'Вымыть редиску и огурец, очистить огурец, разрезать на 2 половинки, нарезать тонкими пластинками, редиску измельчить на терке. Орехи прокалить, почистить от шелухи, измельчить, чеснок раздавить прессом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8532,'Сметану взбить миксером, всыпать орехи, молотый черный перец, посолить, добавить чеснок, перемешать, убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8532,'Достать сметану, смешать с редиской и огурцом, разлить окрошку на сметане с грецкими орехами по тарелкам украсить рубленым укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8533,'Свежие огурцы разрезать пополам, вынуть сердцевину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8533,'Отжать от мякоти сок, перемешать ее с измельченной зеленью,  творогом, чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8533,'Массой наполнить огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8534,'Лимон очистить, нарезать, добавить сахарный песок, всыпать крахмал и сварить кисель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8534,'Перемешать муку с разрыхлителем, добавить сахар, тертое масло, перетереть в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8534,'В три четверти смеси добавить немного воды и замесить тесто. Сформовать основание, поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8534,'Перемешать творожную массу с обычным и ванильным сахаром, вбить яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8534,'На охлажденное основание выложить кисель с лимоном, творог и оставшуюся крошку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8535,'Замесить тесто из гречневой и пшеничной муки, сырых яиц, молока, сахарного песка, соли, пищевой соды, растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8535,'Оставить на полчаса, затем выпечь на смазанной сковороде с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Муку перемешать с солью, подогретой водой, растительным маслом. Тесто должно получиться однородным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Смазать тесто растительным маслом, накрыть горячей миской на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Яблоки нарезать тонкими ломтиками, перемешать с цедрой и лимонным соком или с вымытым изюмом без косточек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Раскатать тесто в тонкий пласт, вытянуть до прозрачности, присыпать панировочными сухарями, выложить яблочную начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Посыпать обычным и ванильным сахаром. Скатать рулет, выложить в заранее смазанную форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Верх смазать сливочным маслом, печь при температуре 190 градусов в течение 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8536,'Готовую выпечку смазать маслом и посыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8537,'Белки комнатной температуры взбить со щепоткой соли в крепкую пену, частями ввести сахар и ванилин. Масса должна получиться глянцевой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Добавить в сковороду бульон, положить лавровый лист и шафран.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8537,'Отсадить безе при помощи ложки или кондитерского мешка. Температура выпекания – 100 градусов, время – до полного высыхания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8538,'Замесить однородное жидкое тесто из молока, муки, яиц, сахара и соли. Поставить в холодильник на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8538,'Разделить сливочное масло на шесть формочек, поставить в духовой шкаф, прогреть до закипания при температуре 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8538,'Быстро разлить тесто и вернуть в духовку. Температуру снизить на 20 градусов, через 15 минут – еще на 20. Еще через 10 минут огонь можно погасить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8539,'Подготовить кальмаров, отварить в соленом кипятке 3-5 минуты, дать остыть, нарезать на кубики. Сварить картофель и яйца, остудить, картофель и белки нарезать на небольшие кубики, желтки растереть с сахаром, сметаной, горчицей, добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8539,'Почистить огурцы, нарезать на небольшие кубики, перья зеленого лука порезать и растереть с солью до выделения сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8539,'Размешать в кастрюле холодный хлебный квас со смесью сметаны, всыпать все ингредиенты, посолить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8539,'Разлить овощную окрошку с кальмарами на квасе в тарелки, положить в каждую по ложке сметаны, сверху присыпать зеленью укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8540,'Смешать в миске творог и натуральный йогурт, масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8540,'Добавить жареные или отваренные на пару куриные грудки, нарезанные на кусочки, без кожи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8540,'Отцедить жидкость от сладкой консервированной кукурузы, измельчить свежие огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8540,'Все ингредиенты перемешать и выложить на тонкий лаваш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8540,'Сверху посыпать листьями зеленого салата, поперчить по вкусу. Лаваш плотно свернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Натереть на мелкой терке кабачок, лишнюю жидкость отцедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Мелко порубить острым ножом очищенный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Смешать куриный фарш, нежирный творог, рубленую свежую зелень, чеснок и кабачок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Смочить руки холодной водой, сформовать котлеты круглой формы, немного приплюснуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Разогреть сковороду с антипригарным покрытием, обжарить котлеты без масла с двух сторон, до образования золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8541,'Огонь убавить, потушить блюдо под крышкой в течение пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8542,'Луковицу небольшого размера нашинковать полукольцами, красный болгарский перец – соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8542,'Мороженые креветки положить в кипящую подсоленную воду, подержать до готовности, очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8542,'Отварить рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8542,'Разогреть на сковороде оливковое масло, выложить лук и перец, обжаривать в течение семи минут, довести перец до полуготовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8542,'Добавить креветки, жарить одну минуту, затем – рис и соевый соус по вкусу. Смесь поставить на тихий огонь, тушить в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Из форели вырезать филейную часть. Брюшко, плавники, голову залить водой на два-три сантиметра, варить на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Почти при готовности бульон посолить, положить перец-горошек и лавровый лист, добавить огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Жидкость процедить. Нарезать кубиками очищенную и вымытую картошку, натереть морковь, порубить лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Все ингредиенты добавить в процеженный бульон, варить на огне средней мощности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Филе очистить от костей и кожи, нарезать небольшими кусочками. При готовности картофеля добавить рыбу и влить сливки, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8543,'Проварить суп в течение нескольких минут, до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Скумбрию горячего копчения очистить от костей и кожи, лососевое малосольное филе нарезать тонкими ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Для запекания подойдет форма для приготовления кекса, застеленная пищевой пленкой. Сначала выложить на неё ломтики лосося, в том числе и на бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Отдельно перемолоть творог с зеленью укропа с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Замочить желатин так, как написано на упаковке, в холодной воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Довести до кипения молоко, снять с огня. Влить набухший желатин, перемешать до растворения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Вылить массу в форму на основу.','https:https://st.vkuso.ru/data/cache/thumb/87/d401a31de141187_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Добавить в смесь немного творога, хорошо перемешать, затем соединить с остальным продуктом, перемешать до состояния однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Переложить массу на красную рыбу, сверху – скумбрия. Покрыть будущую запеканку остатками крема и ломтиками лосося.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Края пищевой пленки завернуть на рыбу, поставить изделие под груз, подходящий по весу и размеру.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8544,'Закуску охладить в холодильнике в течение трех-четырех часов, можно оставить её на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8545,'Взбить кефир с водой убрать в холодильник, сварить картофель в мундире, дать остыть, почистить, нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8545,'Помыть репу, почистить, нашинковать тоненькой соломкой, отварить до мягкости. Хрустящие малосольные огурчики порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8545,'Ссыпать все ингредиенты в глубокую миску, добавить раздавленный прессом чеснок, хорошо перемешать. Залить холодным кефиром, дать постоять, разлить окрошку с репой и малосольными огурцами в тарелки, украсить измельченной зеленью укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8546,'Нарезать куриную грудку, кислое яблоко, белок крутого куриного яйца и твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8546,'Для заправки перемешать натуральный йогурт без добавок с готовой горчицей, молотым перцем, солью. Можно добавить немного свежего лимонного сока, по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8546,'Заправить соусом салат, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Репчатый лук очистить и мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Вымыть сырые шампиньоны, нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'На разогретой сковороде обжарить лук в течение пяти-семи минут, до подрумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Добавить грибы, потушить еще 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Вымыть куриное филе, нарезать небольшими кусочками, выложить в форму. Посолить, добавить сушеные травы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Массу перемешать, сверху выложить грибную обжарку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Для приготовления соуса «Бешамель» налить молоко в небольшую кастрюлю, добавить молотый белый перец, соль, щепотку муската. Перемешать, поставить смесь на плиту, всыпать муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Довести массу до кипения, постоянно помешивать венчиком. Огонь убавить. Прогревать смесь до загустения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Полученным соусом полить куриное филе, посыпать тертым сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8547,'Печь при температуре 200 градусов в течение получаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8548,'Бананы очистить, размять с помощью вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8548,'Добавить в пюре молотый миндаль или орехи кешью, мелко нарезанные сушеные финики и инжир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8548,'Всыпать ванильный порошок, цельнозерновую муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8548,'Масса должна получиться плотной, муку при необходимости можно добавить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8548,'Сформовать маленькие шарики, обвалять в кокосовой стружке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Куриное филе перемолоть дважды с помощью мясорубки или в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Добавить в фарш сырое куриное яйцо, влить молоко, массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Соль, зелень, рубленый чеснок добавить по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Отрезать кусок пищевой пленки прямоугольной формы. Выложить фарш ближе к краю, завернуть пленку трубочкой, массу уплотнять руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Свернуть сосиску, обмять, чтобы вышел воздух. Завязать концы узелками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Такие изделия можно хранить в морозильной камере и использовать при необходимости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'Для отваривания сосиски положить в кипящую воду, варить семь минут на среднем огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8549,'В процессе приготовления мясо должно посветлеть. При подаче пленку удалить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'Овсяные хлопья выложить в миску, залить кефиром или молоком, оставить на 20 минут для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'Отдельно взбить сырые куриные яйца с сахарозаменителем и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'Добавить в смесь пищевую соду, погашенную лимонным соком, тертое яблоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'Жарить оладьи до образования румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8550,'К блюду можно приготовить йогуртовый соус с измельченной малиной, земляникой или клубникой. Смесь взбить или перемешать, полить оладьи при подаче.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Для приготовления травяного соуса порубить зелень базилика, укропа, кервеля, петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8551,'Отварить яйца, морковь и картофель, дать остыть, почистить. Нарезать овощи и белки кубиками. Укроп порубить, добавить растертые желтки яиц, горчицу, сметану, перец, чуть соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8551,'Промыть в дуршлаге соленые грибы, дать стечь воде, переложить на бумажное полотенце, мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8551,'Вымыть редис с огурцами, нашинковать редис тонкими пластинками, огурцы – кубиками, нарезать перья зеленого лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8551,'Смешать все в подходящей по объему кастрюле, добавить смесь сметаны с горчицей, залить холодным хлебным квасом, перемешать. Дать окрошке с грибами и горчицей настояться и можно наслаждаться необычным вкусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8551,'Когда будете солить блюдо, помните, что грибы соленые, добавляйте соль осторожно и пробуйте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Мясо разрезать на тонкие пластинки, немного отбить, посолить и поперчить, дать полежать и пропитаться специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Для приготовления начинки натереть на крупной терке очищенную морковь, добавить в массу тертый сыр, рубленую зелень петрушки, пропущенный через пресс чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Смесь перемешать, добавить йогурт, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Начинку завернуть в куриные филе, закрепить нитками или зубочистками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Обжарить рулеты до образования золотистой корочки, нитки снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8552,'Уложить изделия на противень или в сковороду, влить немного куриного бульона или воды, запечь в духовке в течение 30 – 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Перемолотые в муку овсяные отруби смешать с неперемолотыми отрубями, ванилином и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Сырой куриный белок взбить со щепоткой соли, добавить сахарозаменитель, взбить в плотную пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Влить воду, оливковое масло, смесь перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Смешать сухую и белковую смесь, дать постоять, отруби должны разбухнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Застелить бумагой противень или положить коврик из силикона. Выложить печень с помощью столовой ложки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8553,'Печь в течение 15 – 20 минут при температуре 220 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8554,'Сырое куриное яйцо взбить с солью, влить кефир или натуральный йогурт без красителей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8554,'Всыпать соду, сахарозаменитель, клетчатку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8554,'Должно получиться довольно густое тесто, оно не должно стекать с ложки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8554,'Разложить массу в формы, поставить в духовку на 15 – 20 минут, печь на максимальной температуре, затем температуру уменьшить и допечь в течение часа на минимуме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8555,'Подготовить рыбное филе, сварить (воду чуть подсолить), достать из бульона, дать остыть, нарезать небольшими кусочками. Рассол и квас убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8555,'Сварить яйца, картофель, морковь, хорошо остудить, очистить, нарезать овощи и белки на кубики, желтки порубить. Огурцы, если старые — очистить от кожуры, нарезать на такие же кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8555,'Нашинковать репчатый лук, петрушку, эстрагон, укроп, зеленый лук. Зелень ссыпать в глубокую миску, залить рассолом, оставить на полчаса настаиваться. Добавить рыбу и все овощи, аккуратно перемешать, дать постоять еще полчаса и залить хлебным квасом. Посолить, поперчить, влить в окрошку с рыбой и огуречным рассолом сок из половинки лимона, перемешать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8555,'Для блюда выбирать не костистую и сладковатую рыбу, например линь, судак, окунь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8556,'Киви очистить, разрезать пополам, выложить в блендер, перемолоть с мёдом, кокосовой стружкой. Масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8556,'Слепить шарики из готовой смеси размером с грецкий орех, обвалять в стружке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8556,'«Конфеты» положить в разовые бумажные формочки и поставить в холодильник на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8557,'Смешать в сотейнике обезжиренное молоко или воду с желатином из пакетика, оставить на десять минут для набухания по инструкции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8557,'Добавить зернышки ванили или жидкую ваниль, любой ароматизатор: клубника, миндаль, роза, малина. Можно всыпать пищевой краситель. Смесь перемешать, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Массу смешать со сливками, добавить сырые яичные желтки, тертый корень хрена, цедру лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Отправить на 45 минут в духовку, соблюдать температуру 160 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8557,'Прогреть до растворения желатина в течение двух-трех минут, не кипятить. Снять массу с огня, добавить сахарозаменитель, перемешать, остудить. Можно подержать в морозильной камере две-три минуты. Смесь должна не только остыть, но и начать схватываться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8557,'В таком состоянии продукт перелить в миску и взбить миксером на большой скорости до плотного состояния. Процесс может занять от пяти до двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8557,'Выстелить форму пищевой пленкой, вылить массу, сверху закрыть пленкой, поставить в холодильник до застывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8558,'Капусту брокколи (можно замороженную) выложить в кипящую воду на полминуты. Вынуть, разрезать на соцветия.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8558,'Нарезать куриное филе. В форму для тушения положить курицу, брокколи, специи, сметану. Перемешать. Тушить до готовности в течение 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8559,'Филе курицы нарезать кубиками небольшого размера. Посолить и поперчить по вкусу, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8559,'Добавить пропущенный через пресс чеснок, посыпать итальянскими травами. Выложить массу в форму для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8559,'Нарезать помидоры черри половинками или обычную помидору – ломтиками, консервированные оливки отцедить и порезать колечками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8559,'Выложить то и другое на мясо, посыпать сверху нежирным тертым сыром. Печь в заранее разогретой духовке при температуре 180 градусов в течение 45 – 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'Вымыть, обсушить и нарезать кружочками кабачок, баклажан, помидоры и сладкий болгарский перец. Баклажаны и кабачки немного присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'Форму для запекания смазать растительным маслом, выложить овощи слоями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'Для приготовления соуса смешать пропущенный через пресс чеснок, рубленый острый перец чили, измельченную зелень укропа, зеленый базилик, растительное масло, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'Полить овощи полученной смесью, накрыть фольгой, поставить на 45 минут в духовку, температура приготовления – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'При готовности фольгу снять, сбрызнуть рататуй свежим лимонным соком, выложить несколько маслин и допечь в течение 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8560,'Готовое блюдо подержать под крышкой в течение 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Филе курицы промыть, чернослив замочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Мясо отбить с двух сторон, затем разрезать пополам и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Поверх кусочков выложить пропущенный через пресс чеснок, разложить нарезанный чернослив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Куриные кусочки скрутить в рулетики, закрепить их зубочистками или шпажками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Отдельно приготовить соус из сметаны и сырого куриного яйца. Смазать рулеты приготовленным соусом, печь в духовке в течение 30 – 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8561,'Перед подачей шпажки вытащить, нарезать рулеты на дольки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8562,'Почистить стебли ревеня, нарезать на 3-4 части вдоль, а потом тонкими ломтиками поперек, прокипятить в небольшом количестве воды несколько минут, процедить (воду оставить).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8562,'Отварить морковь и яйца, остудить, нарезать морковь и белки на маленькие кубики. Растереть горчицу с желтками, всыпать соль, перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8562,'Нашинковать редис кружочками, перья лука промыть, обсушить, порубить. Пересыпать все в кастрюлю, посолить, добавить горчицу с желтками, перемешать аккуратно, залить холодным квасом, перемешать еще раз. При подаче окрошку украсить измельченным укропом. Для любителей кислых блюд в окрошку с ревенем, морковью и редисом можно влить отвар ревеня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8563,'В чашу блендера поместить зеленый виноград, апельсин без корочки, но с белой оболочкой (в ней много витаминов и клетчатки), разрезанный на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8563,'Добавить свежий ананас, порезанный на кусочки, банан, кусочки моркови, свежий, хорошо промытый шпинат, яблоко без семечек, пищевой лед. Включить блендер на одну минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Семгу промыть проточной холодной водой и обсушить с помощью бумажного полотенца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Нарезать филе кусочками, посолить и поперчить по вкусу, сбрызнуть лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Смазать оливковым маслом форму для запекания, положить рыбу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8573,'Поставить в морозильную камеру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8564,'Готовым соусом полить рыбу, поставить в духовку, печь при температуре 200 градусов в течение 25 минут. Должна появиться румяная золотистая корочка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8565,'Измельчить мякоть бананов в блендере, добавить овсяные хлопья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8565,'В полученную густую массу добавить изюм и семечки подсолечника, оставить на пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8565,'Выкладывать печенье на фольгу, силиконовый коврик или бумагу для выпекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8565,'Печь при температуре 170 градусов до золотистой корочки в течение 20 – 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8566,'Кабачки очистить от кожицы и семян, натереть на крупной терке. Лишнюю жидкость отжать, добавить яйцо, соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8566,'Мелкими кубиками нарезать куриное филе, посолить, посыпать любимыми специями, обжарить на оливковом масле в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8566,'Массу из кабачков распределить ровным слоем по стенкам и дну формочек из силикона. В центр поместить куриное филе, посыпать его тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8566,'Поставить закуску запекаться при температуре 200 градусов в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8567,'Сварить свежие яблоки (100 г) или сухофрукты (25 г) 2 стаканами кипятка, довести до кипения, оставить на 4 часа под крышкой, процедить и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8567,'Сварить картофель, яйца, дать остыть, нарезать картофель и почищенные огурцы на кубики, белки порубить, размять тщательно желток вилкой, добавить чуть сметаны, размешать до однородного состояния, добавить оставшуюся сметану, перемешать еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8567,'Нашинковать мелко зеленый салат, петрушку и укроп. Все ингредиенты сложить в кастрюлю, заправить сметаной, залить холодным настоем фруктов, посолить. Для еще большей кислоты любители могут добавить в окрошку на фруктовом отваре чуть лимонного сока.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8568,'Пищевой желатин замочить в стакане воды на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8568,'Лишнюю воду слить (если останется), поставить массу на тихий огонь, добавить обезжиренный творог, молоко, какао-порошок, мёд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8568,'Смесь перемешать до однородного состояния с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8568,'Влить в форму и поставить в холодильник до полного застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8569,'Смешать овсяные хлопья, разрыхлитель, пищевую соду, щепотку морской соли крупного помола, ванилин, половину размятого банана, протеин (можно муку), коричневый сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8569,'Отдельно взбить молоко с сырым яйцом или только белком, растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8569,'Обе смеси соединить, масса должна быть однородной. Можно добавить небольшое количество молока, если тесто получилось густоватое.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8569,'Жарить блины с двух сторон до золотистой корочки. Готовое блюдо украсить какао-порошком, тертым шоколадом, рублеными орехами или бананом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8570,'Слить жидкость от консервированного тунца, добавить оливки, разрезанные пополам, без косточек. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8570,'Добавить цедру и сок лимона, рубленую петрушку, еще раз перемешать и заправить оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8570,'Соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8571,'В блендере измолоть финики, орехи кешью, миндаль или грецкие.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8571,'Добавить соль и молотую корицу, довести массу до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8571,'Готовую смесь плотно уложить в формочки для тарталеток, поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8571,'Очищенные бананы и натуральный йогурт взбить в блендере, добавить ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8571,'Перелить полученный крем в формочки, украсить тонко нарезанным киви, поставить в холод еще на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8572,'Перемешать белок сырого яйца, столовую ложку клетчатки, обжарить на сковороде с тефлоновым покрытием, без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8572,'Куриное филе также обжарить с томатами черри. Добавить специи, соль по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8572,'Выложить на готовый блинчик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8572,'Сверху – начинка из красного болгарского перца, репчатого лука. Залить белком сырого яйца, поставить в микроволновую печь на одну-две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8572,'Готовую пиццу достать, посыпать рубленой зеленью петрушки и укропа, любыми приправами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8573,'Взбить при помощи миксера нежирный кефир, творог, банан, изюм и воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8573,'Разлить готовую смесь в формочки или в стаканчики из-под йогурта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8574,'Выложить массу на корж, поставить в духовой шкаф еще на полчаса. Печь при небольшой температуре, блюдо не должно пригореть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8574,'Немного остудить, разрезать пополам и положить их друг на друга: получится четыре слоя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8575,'Желатин растворить в теплой воде, оставить на 20 минут для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8575,'Взбить с помощью блендера, добавить обезжиренное молоко и протеин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8575,'Массу разлить в формочки, поставить в холодильник на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8576,'Домашний сыр и томаты нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8576,'Из зерненого творога отцедить жидкость, соединить с помидорами и сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8576,'Ингредиенты перемешать, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8576,'Добавить немного рубленого чеснока, по желанию. Перед едой посыпать блюдо измельченной петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8577,'Очистить мясо от пленок, помыть, обсушить, нарезать на куски примерно 3х3 см, порезать на крупные кольца очищенный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8577,'Из томатного и соевого соуса с добавлением имбиря, молотого черного перца и соли приготовить маринад. Если вместо томатного соуса использовать магазинный кетчуп, то предварительно следует развести его с водой в пропорции 1 к 1.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8577,'Переложить мясо в кастрюлю, засыпать лук, перемешать, вылить маринад, тщательно все смешать, на несколько часов убрать на холод. Разрезать крупные помидоры на половинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8577,'Мясо и помидоры нанизать на шампуры, полить маринадом, зажарить шашлык из свиной шеи на мангале. Во время готовки шампуры переворачивать и поливать смесью соевого соуса с водой. Подавать блюдо горячим с маринованным луком и зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8578,'Смешать какао-порошок с овсяной мукой, сахарозаменителем, разрыхлителем. Последний ингредиент можно заменить погашенной уксусом пищевой содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8578,'Отдельно перемешать кефир или варенец, нарезанный на мелкие кусочки банан и сырое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8578,'Всыпать муку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8578,'Готовое тесто разложить в формочки, поставить в духовку для выпекания на полчаса, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8579,'Баклажаны вымыть, разрезать вдоль, плодоножку сохранить. Отварить в кипящей воде с солью в течение 15 – 20 минут, откинуть на дуршлаг и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8579,'Приготовить начинку из творога, тертого сыра, зелени, чеснока, яйца. Добавить размятые вилкой сердцевины баклажанов. Начинку посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8579,'Нафаршировать баклажановые «лодочки».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8579,'Противень застелить пергаментом, поместить баклажаны, печь при температуре 180 градусов в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8580,'Свинину помыть, очистить от сухожилий, пленок, нарезать средними кусками, переложить в глубокую миску, засыпать кольца лука, залить маринадом из томатного сока со специями для шашлыка и солью, перемешать. Прикрыть миску пленкой и отправить на ночь в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8580,'Плотно насадить мясо на шампуры, поместить в тандыр. Пока шашлык из свинины в тандыре будет запекаться поливать его маринадом или сбрызгивать чуть разбавленным вином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8581,'Куриную грудку освободить от костей, перемолоть на мясорубке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8581,'Прокрутить брокколи и репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8581,'В смесь добавить сырое куриное яйцо, манку, молоко, соль, перец и чеснок – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8581,'Перемешать массу руками, фарш должен быть жидким, как тесто на оладьи. При необходимости норму молока можно увеличить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8581,'Разогреть сковороду, выпечь котлеты под крышкой, смесь выкладывать столовой ложкой. Готовить на тихом огне, жарить с двух сторон по несколько минут, до образования корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8582,'Сырой яичный белок взбить в пену, добавить отруби, овсяные хлопья, йогурт, сахарозаменитель и специи. Массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8582,'Часть смеси поставить в морозильную камеру на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8582,'Большую часть выложить в форму для выпекания, готовить при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8582,'Свежие ягоды перетереть или превратить в пюре. Можно просто раздавить клубнику ложкой, если она достаточно спелая. Сахарозаменитель добавлять по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Сделать глазурь: соединить масло и сливки в сотейнике, нагреть, но не кипятить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8582,'Достать из духовки выпеченную основу, выложить начинку и замороженное тесто, его нужно натереть на терке. Блюдо снова поставить в духовой шкаф на 15 – 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8583,'Куриное филе нарезать мелкими кубиками со стороной в полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8583,'Мясо посолить и поперчить по вкусу, добавить сырые куриные яйца, сметану, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8583,'Всыпать пшеничную муку и нарезанный зеленый лук, снова перемешать. Тесто должно быть жидким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8583,'Выкладывать массу на разогретую сковороду столовой ложкой, жарить с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8584,'Нарезать филе курицы небольшими квадратиками, переложить в большую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8584,'Приготовить из смеси лимонного сока с горчицей, оливковым маслом, пряностями и сахаром маринад, солить пока не надо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8584,'Залить маринадом мясо, перемешать, прикрыть пленкой, убрать на час в холодильник, но лучше подержать часа 4. Шпажки залить водой, пусть пропитаются влагой, тогда при жарке они не будут гореть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8584,'Достать мясо, нанизать плотно на шпажки, посолить. Запекать шашлык из куриного филе на шпажках до желто-коричневой корочки, во время жарки поливать разведенным маринадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8584,'Подавать блюдо с зеленью, маринованным луком и овощами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8585,'Перемешать в миске яичные белки, обезжиренный творог и сметану. Массу взбить с помощью блендера в течение трех минут до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8585,'Добавить по чуть-чуть сахарозаменитель и протеин с ягодным вкусом, взбивать еще пару минут до получения воздушной консистенции. В тесте не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8585,'Емкость для выпекания выложить бумагой для выпечки. Вылить готовую массу, равномерно распределить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8585,'На верхней решетке разместить форму с будущей выпечкой, на нижнюю поставить емкость с водой. Печь при температуре 180 градусов в течение 30 – 40 минут. Во время приготовления духовку не открывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8585,'Чизкейк остудить при комнатной температуре. Размороженную малину взбить в сироп, полить пирожное. Сахарозаменитель в массу лучше не добавлять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8586,'Смешать с помощью комбайна сахарный песок, нежирный творог и яйца, массу хорошо перемешать, добавить натуральный йогурт. Еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8586,'Всыпать манку, масса должна быть без комочков, однородной. Всыпать чернику или другие лесные ягоды и осторожно перемешать массу вручную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8586,'Смесь перелить в смазанную маслом и присыпанную сухарями форму. Печь при температуре 180 градусов в течение 30 – 35 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8586,'Огонь выключить, остудить запеканку в течение 10 – 15 минут в духовке, затем охладить при комнатной температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8587,'Подготовить рыбу: почистить, удалить голову, хвост, хребет и кости, выпотрошить, промыть, обсушить, нарезать на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8587,'Можно пожарить и стейки, но тогда ждать придется дольше, зато кости не надо будет вынимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8587,'Из смеси сока лимона, пряностей, вина, соли и сахара приготовить маринад, залить рыбу и убрать в холодное место примерно на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8587,'Насадить куски рыбы на шампуры, запечь шашлык из судака на мангале. К готовому блюду подать белый соус и свежие овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8588,'Смешать для маринада мед с оливковым маслом, чесноком и соевым соусом, посолить, всыпать пряности и хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8588,'Порезать филе курицы небольшими кусочками, переложить в миску, залить маринадом, прикрыть пленкой, дать постоять на холоде 1 час, а лучше около трех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8588,'Нарезать лук кольцами (покрупнее), насадить на шпажки поочередно с мясом, положить в чашу мультиварки, полить маринадом. Задать режим «Жарка» или «Выпечка». Шашлык их курицы в мультиварке будет готов минут через 40-50. Мясо получается мягким и сочным, подать с кетчупом, свежими огурцами, помидорами и зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8589,'Подготовить кусок свинины, нарезать на одинаковые кубики, лук порезать полукольцами, смешать с мясом, добавить приправы для шашлыка, влить уксус, не солить, хорошо вымешать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8598,'Для глазури взбить растопленное и охлажденное сливочное масло, ваниль, какао-порошок и сахар, влить молоко, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8589,'Оставить мариноваться не мене чем на 5 часов, а лучше оставить в холодильнике на ночь. Достать мясо, добавить соль, перемешать, нанизать плотно кусочки друг к другу на шампуры. Жарить шашлык из свинины в уксусе на мангале над раскаленными углями, следите, чтобы не появлялось пламя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8590,'Овсяные хлопья перемолоть в муку. Смешать с молоком, сырым яйцом, солью, погашенной уксусом или лимонным соком пищевой содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8590,'Добавить теплую воду при необходимости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8590,'Жарить блинчики на антипригарной сковороде, без масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8590,'Приготовить начинку из обезжиренного творога, рубленого укропа или любой другой зелени, чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8590,'Свернуть блинчики конвертом, треугольником, трубочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8591,'Сливки охладить, взбить на небольшой скорости с сахарным песком или мёдом, масса должна загустеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8591,'Промыть свежие ягоды клубники, «хвостики» срезать. Можно использовать размороженный продукт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8591,'Выложить на тарелку хлебец, намазать сливочной массой, выложить ягоды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8591,'Таким же образом сделать несколько слоев, украсить блюдо клубникой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8591,'Дать пирожным постоять в течение 5 – 10 минут в холодильнике для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8592,'Приготовить желе так, как написано на пакетике, но воды взять в два раза меньше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8592,'Смеси дать постоять, довести до кипения, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8592,'Массу остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8592,'На дно емкости выложить фрукты или ягоды. Добавить немного остывшую желейную массу в сметану, влить ягодный сироп или мёд, сахарную пудру, по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8592,'Смесь взбить до появления пузырьков, вылить в емкость с ягодами и поставить на час-два в холодильник. Желе должно полностью застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'В большой емкости смешать сахарный песок, крахмал, ванилин и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'Добавить обезжиренное молоко, взбивать смесь до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'Поставить кастрюлю на средний огонь, помешивая, довести до кипения. Варить в течение минуты, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'Половину полученной смеси перелить в блендер, добавить кружочки очищенных бананов, нарезанные или порванные руками листья базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'Ингредиенты взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8593,'Пюре комнатной температуры перелить в формочки, поставить в морозилку на шесть часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8594,'Натереть на средней терке морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8594,'Яблоки очистить от семенных камер и кожуры, нарезать небольшими кубиками и сбрызнуть лимонным соком, чтобы не почернели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8594,'Хорошо промыть изюм без косточек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8594,'Все три ингредиента смешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8595,'Смешать хороший деревенский творог с сырыми куриными яйцами, кокосовой и овсяной мукой. Соль и сахарозаменитель – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8595,'Из готовой массы скатать шарики или нарезать раскатанное «тесто» на квадратики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8595,'Отварить на тихом огне в течение трех-пяти минут, пока не всплывут. Немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8596,'В блендер выложить сывороточный ванильный протеин, замороженную смородину, влить молоко, добавить по вкусу стевию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8596,'Массу взбивать в течение трех-четырех минут. Масса должна получиться гладкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8597,'Перемешать сырые куриные яйца с обезжиренным жидким творогом, добавить овсяные отруби, картофельный крахмал, шоколадный протеин, растворимый кофе, разрыхлитель, влить ром. Сахарозаменитель – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8597,'Массу взбить, выложить в формы, печь в течение получаса при температуре 170 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8598,'Смешать просеянную муку с солью, содой, какао-порошком, включить на разогрев духовку. Взбить сахар и мягкое несоленое сливочное масло, влить молоко, вбить яйцо, всыпать ваниль, взбить хорошо миксером до однородного состояния на медленной скорости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8598,'Подготовить противень, выложить тесто столовой ложкой (или ложкой для мороженого) с промежутком в 2 см, выпекать при 180 градусах примерно 10-12 минут. Достать противень, положить на каждое печенье разрезанную пополам зефирину. Слегка вдавить, отправить в духовку примерно на 2 минуты. Нагревать 2-2,5 минуты, пока зефир не начнет плавиться, достать и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8598,'Положить по столовой ложке глазури на каждую половинку зефира и разровнять. Шоколадное печенье в глазури с зефиром убрать в прохладное место до затвердевания глазури.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Овсянку быстрого приготовления залить сырыми куриными яйцами  (если допускаете содержание жиров) или только белками, дать постоять для набухания в течение часа или полутора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Перемешать массу с помощью вилки или блендера. Каша должна быть однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Банан очистить, превратить в пюре, добавить в овсянку и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Всыпать молотую корицу, влить мёд или добавить любой сахарозаменитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Погасить пищевую соду лимонным соком, вмешать в тесто. Если тесто получилось густоватым – можно влить немного молока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8599,'Жарить блинчики до румяной корочки на среднем огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'Листья салата промыть и обсушить с помощью бумажных полотенец, нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'От консервированного тунца слить жидкость, рыбу размять вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'Помидоры вымыть, обсушить и нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'Ингредиенты перемешать, при необходимости досолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'Добавить консервированную кукурузу без жидкости и нарезанные кружками консервированные маслины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8600,'Салат заправить оливковым маслом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'Коричневый рис промыть. В небольшой емкости вскипятить воду, добавить продукт, приготовить так, как написано на упаковке, под крышкой. Воду слить, рис остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'Противень застелить пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'С помощью блендера измельчить семечки подсолнуха. Добавить рис, тертую морковь, рубленый чеснок, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'Массу хорошо перемешать, она должна получиться липкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'Сформовать котлеты, они должны быть тонкими, похожими на лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8601,'Печь на противне в течение 20 минут, в середине выпечки изделия перевернуть. Вынуть из духовки и подать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8602,'Капусту белокочанную потушить в воде, до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8602,'За пять-шесть минут до окончания термообработки добавить помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8602,'Куриную грудку тушить отдельно, также с водой, добавить приправы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8602,'Смешать куриное мясо с капустой, прогреть вместе две-три минуты, продукты должны пропитаться. Поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8603,'Вымыть яблоки, очистить от семенных камер и кожуры. Натереть плоды на мелкой терке или превратить их в пюре с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8603,'Залить яблоки холодным кефиром, взбить миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8603,'В напиток добавить молотую корицу и мёд, снова взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8603,'Коктейль разлить в бокалы, украсить ломтиками яблок, сбрызнуть их лимонным соком, чтобы не почернели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8604,'Положить в миску протеиновый порошок, добавить овсяные хлопья, какао-порошок, измельченный фундук, молотую корицу, сухое обезжиренное молоко, арахисовое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8604,'Массу хорошо перемешать руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8604,'Скатать небольшие шарики, каждый обвалять в кокосовой стружке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8605,'Бананы очистить, размять в пюре с помощью комбайна. Добавить творог, мягкий творожок, сырые желтки, манную крупу. Ванилин и сахарозаменитель – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8605,'Массу взбить до однородного состояния. Отдельно взбить белки в плотную пену, вмешать в основную массу движениями снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8605,'Поставить в духовой шкаф, печь при температуре 180 градусов, огонь постепенно снижать до 150 градусов, всего на приготовление потребуется 40 минут. Перед подачей блюдо охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8606,'Для приготовления мороженого смешать с помощью блендера мякоть банана, нежирный творог, ванильный или шоколадный протеин. Заморозить в силиконовой форме, контейнере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8606,'Другой вариант: смешать натуральный йогурт, любые замороженные ягоды и протеин, заморозить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8606,'Для миндального мороженого смешать молоко из миндаля, ванильный протеин, карамельный сироп на фруктозе или с сахарозаменителем, заморозить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8606,'Для приготовления клубничного мороженого смешать  миндальное молоко, ягоды клубники, ванильный экстракт, ванильный протеин, заморозить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8607,'Из готовой массы сформовать шарики, внутрь положить промытые и обсушенные сухофрукты. Начинку можно не делать отдельно, а перемолоть вместе с остальными ингредиентами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8607,'Готовые «пряники» выложить на пергамент или на силиконовый коврик. Печь в духовке в течение 20 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8608,'Для приготовления десерта понадобится любой свежий ягодный или фруктовый сок. Смешать 5 столовых ложек сока и желатин из пакетика, дать постоять в течение двух-трех минут, затем смесь прогреть минуту в микроволновой печи. Остудить, влить оставшийся сок. Поставить желе на 20 минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8608,'Замороженные, оттаявшие или свежие ягоды черники, клубники и малины разложить в формочки, порционные мисочки или стаканы. Залить желатиновой смесью, поставить в холодильник на два часа, до полного застывания. Подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8609,'Крупные, спелые помидоры нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8609,'Очистить гранат, смешать зерна с помидорами, нарезанным зеленым луком и рублеными листьями кинзы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8609,'Перед подачей салат посолить, перемешать. Подать блюдо в охлажденном виде или комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8610,'Куриное филе нарезать кусочками средней величины, ананасы – чуть мельче.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8610,'Для маринада смешать кетчуп и соевый соус, положить в смесь мясо, поставить в холодильник на полчаса или больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8610,'Нанизать маринованную курицу на шпажки вместе с ананасами, вперемешку. Смазать противень маслом или застелить его бумагой для выпекания, выложить шашлыки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8610,'Печь в духовом шкафу в течение 35 – 40 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8611,'Филе с кожей натереть солью и молотым перцем, обжарить на оливковом масле на большой сковороде, кожа должна быть сверху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8611,'После появления румяной корочки переложить продукт в форму для выпекания, кожа – внизу. Помидоры черри разрезать пополам, выложить на филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8611,'Так же порезать черные маслины без косточек, выложить поверх помидор, посыпать очищенными кедровыми орешками. Приправить специями по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8611,'Поставить форму в духовой шкаф, печь в течение 12 – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8611,'Перед подачей посыпать блюдо горстью свежего рубленого базилика, разложить в тарелки, сбрызнуть оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Желатин из пакетика замочить в воде на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'От консервированных ананасов слить жидкость. Отложить шесть кружочков для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'С помощью блендера приготовить смесь из творога, ананасов и бананов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Набухший желатин прогреть, но не кипятить, немного остудить и залить в творожно-фруктовую массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Отдельно взбить сырые куриные белки, лучше это сделать со щепоткой соли.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Смешать белковую массу с творожной, осторожно, лопаточкой, движениями снизу вверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Готовую смесь разложить в небольшие формочки для десерта или креманки, украсить оставленными кружками ананаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8612,'Суфле охладить в течение двух-трех часов в холодильнике, подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8613,'Свежие огурцы вымыть, отрезать кончики. Кожуру можно удалить, если она горчит. Нарезать мякоть брусками, сперва вдоль, затем поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8613,'Белокочанную капусту нашинковать мелко или крупно, помять руками, если появился лишний сок – слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8613,'Зеленый листовой салат вымыть, нарезать или порвать руками. Перемешать все подготовленные ингредиенты в салатнице, добавить консервированную кукурузу без сока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8613,'Посолить блюдо по вкусу, полить растительным маслом, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8614,'Сварить до готовности горошек и капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8614,'Разбить в миску яйцо, влить молоко, приправить перцем и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8614,'Выложить вареные овощи в формочки, залить взбитой яичной смесью, украсить дольками помидора, убрать в духовку или микроволновку. Запечь омлет с помидорами, горошком и цветной капустой  до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Куриное филе отварить до полуготовности, нарезать, немного обжарить на растительном масле. Мясо переложить в казан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Добавить шоколад, мешать до растворения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Промыть холодной водой стручки молодой зеленой фасоли, отделить от твердых частей, поломать сами стручки на две-три части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Отварить фасоль в небольшом количестве воды до готовности, она должна легко разламываться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Нарезать тонкими кольцами репчатый лук, помидоры – кружками. То и другое обжарить на растительном масле, которое осталось от приготовления курицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Добавить рубленую зелень петрушки, кинзы, нарезанный чеснок, посыпать смесь по вкусу солью и перцем, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Овощи переложить к куриному мясу, добавить фасоль, долить немного воды, она должна покрыть мясо с овощами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8615,'Тушить блюдо на тихом огне в течение 10 – 15 минут. Блюдо подать в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Свежие шампиньоны хорошо промыть, разрезать на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Грибы сбрызнуть лимонным соком, посолить и поперчить по вкусу, добавить растительное масло. Дать продукту немного постоять, пропитаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Натереть на крупной терке твердый сыр, например, «Пармезан» или «Российский».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Листовой салат хорошо вымыть и порвать на кусочки руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Отдельно отварить перепелиные яйца, очистить, разрезать на половинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8616,'Все ингредиенты смешать, половинки яиц выложить сверху, в качестве украшения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Смешать яичные белки, сывороточный протеин, какао-порошок, обезжиренный творог. Массу взбить в течение пяти-шести минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Смесь поместить в антипригарную форму с тонкими стенками. Печь в предварительно нагретом духовом шкафу в течение 15 минут при температуре 170 градусов. Пирог охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Для приготовления крема взбить обезжиренный творог с сывороточным протеиновым порошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Выпечку разделить на пять частей, покрошить её в креманки или бокалы для десерта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Залить готовым кофе, подождать, пока кусочки пирога не пропитаются.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Сверху выложить творожно-протеиновый крем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8617,'Блюдо можно подать на стол сразу или на ночь поставить в холодильник. При подаче на стол посыпать десерт какао-порошком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8618,'Сливочное масло разогреть на сковороде. Грибы нарезать и обжарить вместе с раздавленным чесноком, на это потребуется не больше пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8618,'Обжарку посолить и поперчить по вкусу и продолжать прогревать до потемнения грибов, они должны пустить сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8618,'Снять емкость с огня. Смешать массу с рикоттой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8618,'Сырые куриные яйца немного взбить, обжарить на сливочном масле по две-три минуты с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8618,'Готовый омлет немного остудить, выложить начинку на один край, скрутить рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8619,'Яблоко нарезать кусочками, выложить в форму с высокими бортиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8619,'Печь в микроволновой печи, начинка не должна доходить до краев чаши.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8619,'К яблокам добавить любые любимые ягоды, все посыпать сахарным песком и молотой корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8619,'Отдельно взбить яичные белки с ванилином и разрыхлителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8619,'Залить смесью фрукты, накрыть крышкой форму и поставить в микроволновку на три-четыре минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Для приготовления начинки вымыть куриную печень, нарезать произвольными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Очистить репчатый лук, нарезать небольшими кубиками, обжарить на растительном масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Добавить кусочки печени, готовить в течение трех-четырех минут, помешивать. Соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Массу остудить, измельчить с помощью блендера до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Филе курицы надрезать в виде «кармашка», распластать. Накрыть мясо пищевой пленкой, с помощью скалки раскатать в пласт, пленку убрать.','https:https://st.vkuso.ru/data/cache/thumb/80/3b2c808d82e1680_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Курицу посолить и поперчить, положить в центр каждого «пласта» по четвертой части печеночной начинки.','https:https://st.vkuso.ru/data/cache/thumb/22/52344a3d7213822_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Скатать изделия в рулеты, перевязать нитками.','https:https://st.vkuso.ru/data/cache/thumb/10/c46a317c7c37110_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Насыпать сахарную пудру, взбить до однородности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Разогреть растительное масло на большой сковороде, обжарить на нем фаршированные грудки по три-четыре минуты с каждой стороны, должна получиться золотистая корочка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8620,'Переложить грудки в форму для запекания, добавить немного куриного бульона, печь при температуре 200 градусов в духовом шкафу. Перед подачей нитки удалить.','https:https://st.vkuso.ru/data/cache/thumb/b6/bd501938c678bb6_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'В глубокую емкость небольшого размера насыпать соль, влить воду, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Положить в раствор грудку индейки или две куриных, дать пропитаться в течение двух часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Мясо вынуть из рассола, обсушить с помощью бумажных салфеток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Застелить противень фольгой, выложить грудки, сделать надрезы и нашпиговать дольками очищенного чеснока, намазать смесью растительного масла и молотых перцев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Приправы можно использовать любые, например, смесь паприки и чили.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Поставить блюдо в духовку, нагретую до 250 градусов, печь в течение 20 минут, затем подержать мясо при закрытой дверце еще два часа или больше.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8621,'Пасторма до подачи должна полностью остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Филе курицы пропустить через мясорубку или измельчить с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Добавить в готовый фарш сырой куриный желток, подлить молоко, посолить. Массу хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Отдельно взбить белок, смешать с фаршем, добавить пшеничную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Натереть на крупной терке сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Форму для выпекания смазать сливочным маслом, положить половину фарша, насыпать сыр, сверху – оставшийся фарш.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8622,'Поверхность запеканки смазать сметаной, досолить и запечь в духовом шкафу при температуре 200 градусов в течение получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8623,'Смешать сырое куриное яйцо, обезжиренное молоко, измельченные с помощью кофемолки или блендера овсяные хлопья. Добавить, по желанию, ваниль или ванилин из пакетика, стевию и молотую корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8623,'Масса должна получиться однородной, при этом жидкой, как тесто для блинов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8623,'Выпечь блинчики на тихом огне, на сковороде с антипригарным покрытием, без масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8623,'Отдельно смешать ягоды или фрукты с густым йогуртом, смесью начинить блинчики и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Овсяные хлопья или несладкие мюсли измельчить с помощью кофемолки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Соединить их с ржаными или пшеничными отрубями, молотой корицей и разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Отдельно взбить в пену сырые куриные белки с сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Кефир или йогурт взбить с желтками до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Соединить эту массу с сухой смесью и осторожно ввести взбитые белки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8624,'Вылить массу на противень, печь в духовом шкафу в течение 15 – 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8625,'Перемешать обезжиренный творог, шоколадный протеин, половину нормы молотых хрустящих хлебцев. Должна получиться густая паста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8625,'Её нужно брать чайной ложкой, формовать округлые пирожные и обваливать в оставшихся сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8626,'Перемешать сырые яичные белки с овсяными хлопьями, замороженными ягодами, протеином, молотой корицей, стевией и кокосовой стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8626,'Массу вылить в формочки и поставить в микроволновую печь на пять минут в режим подогрева.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8626,'Затем дать выпечке подрумяниться в режиме гриля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8626,'Перед подачей выпечку остудить в течение двух часов, такие кексы едят в холодном виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Сырое куриное яйцо разделить на желтки и белки, составляющие по отдельности взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'В желтковую массу вмешать отруби, стевию, геркулес.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Осторожно ввести белок, перемешать движениями сверху вниз и поставить в духовку, печь в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Белок и желток второго яйца взбить так же, по отдельности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'В желток добавить творог, молоко, стевию и набухший агар-агар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Массу взбить до состояния крема, вмешать отдельно взбитые белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Готовый бисквит разрезать на части по горизонтали, пропитать заваренным кофе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11529,'Оставить под салфеткой на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Половину выложить на дно формы, сверху – творожный крем, снова корж. Операцию повторить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8627,'Десерт поставить в холодильник на ночь, утром вынуть из формы, посыпать какао-порошком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8628,'Яблоко натереть на терке, всыпать гречневую муку, положить отруби, мёд, влить оливковое масло, кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8628,'Массу хорошо перемешать и оставить на 15 – 20 минут для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8628,'Если тесто получилось суховатым – добавить еще немного кефира. Масса не должна рассыпаться и быть пластичной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8628,'Разделить тесто на небольшие порции, слепить шарики, каждый расплющить в лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8628,'Выложить на противень, печь при температуре 150 градусов в духовом шкафу в течение часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'Отварить в мундире картофель, остудить, почистить, нарезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'Грибы обтереть влажной салфеткой, порезать на тонкие пластинки, лук нашинковать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'Обжарить бекон и выложить на бумажное полотенце, в вытопленном жире обжарить шампиньоны и переложить в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'Долить на сковороду масла и обжарить кружки картофеля со всех сторон, добавить лук и обжаривать еще 5 минут. Выложить сверху грибы, чуть перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'Взбить венчиком яйца с солью, черным молотым перцем, кайенским перцем, тмином. Залить содержимое сковороды яичной смесью, тушить на маленьком огне 10-12 минут, выложить поверх ломтики бекона, присыпать колечками из шнитт-лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8629,'К столу подать запеканку из картофеля с беконом и грибами в горячем виде, по вкусу можно приправить кетчупом или тертым хреном со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Для приготовления коржа перемешать творог, овсянку, яичный белок и протеин. Можно сделать это с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Массу выложить в форму, поставить на 20 минут в духовку, печь при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Готовый корж остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Приготовить желатиновую массу так, как указано на упаковке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Смешать творог, желатин, протеин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Залить смесью корж, поставить в холодильник на 20 – 40 минут или больше, подождать, пока не затвердеет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Отдельно взбить ежевику с подготовленным желатином и сахарозаменителем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8630,'Вылить массу на творожный слой, поставить в холодильник на час или на всю ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8631,'Каждое куриное филе разрезать вдоль на две тонкие пластинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8631,'Мясо посолить и поперчить по вкусу, обвалять в цельнозерновой муке, излишки панировки стряхнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8631,'Обжарить филе на небольшом количестве  растительного масла, по две-три минуты с каждой стороны, огонь должен быть сильным. Переложить в тарелки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8631,'Растопить сливочное масло, смешать с рубленой зеленью петрушки, базилика, добавить свежий лимонный сок. Готовой смесью полить грудки и подать блюдо к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8632,'Шампиньоны нарезать, обжарить с измельченным репчатым луком на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8632,'Вскипятить воду, растворить в ней плавленый сыр, при необходимости добавить соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8632,'Смесь прокипятить в течение двух минут, добавить готовую обжарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8632,'Разлить суп в тарелки и добавить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8633,'Очистить и нарезать крупными кубиками свежие огурцы, помидоры, кабачки и баклажаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8633,'Пропустить чеснок через пресс, добавить шафран, орегано, базилик, чабрец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8633,'Смесь выложить на противень или в большую форму, полить оливковым маслом и поставить в духовку на 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8633,'Вынуть, перемешать, посолить, допечь еще в течение получаса до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8634,'Рыбу очистить, вымыть, посолить и поперчить по вкусу, сбрызнуть свежим соком половины лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8634,'Поставить филе на два-три часа в холодильник, для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8634,'Нарезать кубиками свежие помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8634,'Маринованную камбалу выложить в форму, сверху – помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8634,'Печь в духовке, при температуре 180 градусов, в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8635,'Обезжиренный творог смешать с сырым куриным яйцом с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8635,'Отдельно натереть яблоко, добавить в массу вместе с молотыми отрубями и разрыхлителем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8635,'Массу выкладывать на противень, застеленный бумагой для выпечки, чайной ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8635,'Печь в течение получаса при температуре 180 – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Филе курицы пропустить через мясорубку или измельчить с помощью блендера вместе с нежирной сметаной или натуральным йогуртом. Фарш должен получиться однородным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Разморозить цветную капусту, также измельчить в блендере или мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Натереть морковь. Смешать все три ингредиента.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Отдельно взбить с солью охлажденное сырое куриное яйцо и дополнительный белок, добавить в фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Массу поперчить, всыпать любимые специи, сушеную зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8636,'Выложить смесь в контейнер для пароварки, посыпать сверху тертым сыром, готовить в течение 40 – 45 минут. При подаче суфле нарезать на порции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8637,'Приготовить однородную массу из мёда, ванили, нежирного творога, молотой корицы и воды с помощью блендера или миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8637,'Далее смешать продукты в миске с арахисовым маслом и сывороточным протеином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8637,'В массу добавить овсяную муку и тертый миндаль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8637,'Для приготовления из смеси батончиков понадобится противень с ячейками либо обычный глубокий противень: в этом случае массу потом нужно будет нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8637,'Запечь до готовности, поставить в холодильник на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8638,'Перемешать сырые яичные белки, клетчатку, какао-порошок, шоколадный протеин, молотую корицу, кофе, цедру лимона или апельсина, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8638,'Добавить пищевую соду, погашенную уксусом, мягкое сливочное масло. Массу взбить до однородного состояния и поставить на час в духовой шкаф.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8639,'Хорошо перемешать обезжиренный творог, клетчатку, сырое куриное яйцо, молоко, сахарозаменитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8639,'Полученную массу выложить на противень в виде лепешек, поверхность предварительно застелить фольгой или бумагой для выпекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8639,'Поставить в духовку, печь при температуре 180 градусов в течение 20 – 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8640,'Смешать натуральное арахисовое масло, казеиновый протеин со вкусом шоколада, ванили или орехов, какао-порошок, обезжиренный греческий йогурт, измельченный арахис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8640,'Готовую массу разделить на десять частей, сформовать батончики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8640,'Отдельно приготовить шоколадную глазурь. Для этого растопить кокосовое масло на тихом огне, опустить поломанный на кусочки темный шоколад, массу растопить, постоянно помешивать. Можно добавить натуральный подсластитель, например, стевию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8640,'Протеиновые батончики покрыть полученной смесью или окунуть в неё.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Замочить желатин в холодной кипяченой воде так, как написано на пакетике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Для начинки перемешать с помощью блендера обычный обезжиренный творог, можно зернистый, мягкий творог, сырые куриные белки, сахарозаменитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Выложить массу в форму небольшого размера, можно силиконовую, поставить в духовку на 15 минут, температура выпекания – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Готовую запеканку вынуть из формы, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Для приготовления глазури смешать набухший желатин с холодным молоком. Массу прогреть на тихом огне до растворения желатина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Всыпать кукурузный крахмал, какао-порошок, сахарозаменитель. Вмешать желтки, уварить до загустения при постоянном помешивании. Смесь снять с огня, немного остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'В форму, в которой готовилась запеканка, вылить половину готовой глазури, выложить запеканку, залить остатками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8641,'Поставить в холодильник на час или два, до полного застывания глазури. Готовый десерт достать из формы и нарезать порциями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8642,'Смешать шоколадный протеин, белок, немного воды, добавить, по желанию, стевию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8642,'Выпечь блинчики на сковороде с антипригарным покрытием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8642,'Для приготовления крема перемешать с помощью блендера клубничный протеин, творог, кефир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Горячий гаспачо с мясом перемешать, варить около 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8643,'Небольшой кочан пекинской капусты вымыть, тонко нашинковать, переложить в салатник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8643,'Отваренную грудку освободить от костей и кожи, нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8643,'У сладкого болгарского перца удалить семенные камеры, плод нарезать соломкой, огурцы – ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8643,'Все продукты перемешать, добавить консервированную кукурузу без жидкости и рубленую зелень петрушки, укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8643,'Салат посолить по вкусу, заправить сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8644,'Большие спелые бананы размять вместе с геркулесом, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8644,'Лист для выпечки смазать маслом, выложить массу в виде лепешек, выпечь в течение 15 минут при температуре 150 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8645,'Твердый сыр натереть на крупной терке, измельчить очищенный чеснок. Оба ингредиента перемешать с творогом, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8645,'Куриное филе надрезать, хорошо отбить с двух сторон, натереть солью. Выложить на каждую «пластинку» творожную начинку, скрутить в рулеты и закрепить края зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8645,'Каждое изделие обжарить с двух сторон по несколько минут, до образования золотистой корочки, сложить в форму и запечь в течение 25 минут при температуре 180 – 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8646,'Смешать ржаную муку, сырое куриное яйцо, кефир, размятый спелый банан и клетчатку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8646,'По вкусу добавить сахарозаменитель, всыпать пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8646,'Массу оставить на 20 минут для набухания продуктов, затем выложить в формочки из силикона, печь в течение 30 – 40 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8647,'Перемешать сырые куриные желтки, сахарозаменитель, разрыхлитель, овсяную муку, клетчатку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8647,'Отдельно взбить сырые белки, в плотную пену. Аккуратно перемешать с желтковой массой, движениями снизу вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8647,'Расформировать смесь в плоскую форму из силикона, печь в течение 8 минут при температуре 150 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8647,'Для начинки смешать хорошо размятый творог с какао-порошком и сахарозаменителем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8647,'Выложить творожную массу на корж, свернуть в виде рулета, оставить на 10 минут, чтобы бисквит пропитался.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8648,'Подготовить форму для выпечки, смазать стенки маслом, включить на разогрев духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8648,'Растереть протертый через сито творог (лучше использовать пастообразный или мелкими крупинками) с яичными желтками, сметаной, добавить сахар и ванильный сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8648,'Всыпать смесь манной крупы с разрыхлителем, тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8648,'Взбить белки в пену, смешать с творожной массой, добавить ягоды по желанию, аккуратно перемешать, переложить в форму для выпечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8648,'Выпекать творожный манник с ягодами до готовности примерно 50 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Половину заявленной нормы геркулеса и семена льна перемолоть в блендере в муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Пересыпать её в глубокую емкость, всыпать остатки геркулеса, пищевую соду, по щепотке соли и молотой корицы, цедру апельсина, молотый миндаль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Взболтать кокосовое молоко комнатной температуры, долить лимонный сок, оставить смесь на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Натереть на мелкой терке зеленые яблоки, отжать сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Размять вилкой спелый очищенный банан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'В сухие ингредиенты добавить растительное масло без запаха, перемешать, выложить фрукты и долить кокосовое молоко. Быстро перемешать, но не вымешивать, только соединить компоненты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Формы для кексов застелить бумагой для выпекания или вложить бумажные капсулы. То и другое не потребуется, если кексы будут выпекаться в силиконовых емкостях.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Тесто выложить ложкой, до верха, украсить ягодами вишни: по ягодке на кекс.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8649,'Печь в течение 20 – 25 минут, готовность проверить спичкой. Выпечку вынуть, остудить и подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8650,'Нарезать кубиками свежий огурец и помидоры.','https:https://st.vkuso.ru/data/cache/thumb/68/a0fb0ef9ad10768_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8650,'Сыр «Фета» поломать руками.','https:https://st.vkuso.ru/data/cache/thumb/5d/9e6ca88805cb85d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8650,'Все ингредиенты перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a8/51182ec431ccba8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8650,'На готовые начос намазать хумус, его можно приобрести в магазине или приготовить самостоятельно.','https:https://st.vkuso.ru/data/cache/thumb/05/9e6bd499e233c05_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8650,'В центр большого блюда выложить салат, по краям разложить смазанный хумусом начос.','https:https://st.vkuso.ru/data/cache/thumb/e1/ad4c4f1d26b84e1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Порвать руками салатные листья нескольких сортов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Нарезать зеленый лук, петрушку, базилик и укроп. Все ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Помидоры черри разрезать пополам, перемешать с зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Для приготовления заправки измельчить анчоусы, каперсы, вяленые томаты, добавить винный уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Перемешать, соль и молотый перец – по вкусу. Нарезать кольцами репчатый лук, вареные куриные яйца – небольшими ломтиками, консервированное филе тунца разобрать на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8651,'Продукты выложить на салатные листья вместе с заправкой. Блюдо сбрызнуть оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8652,'Нарезать куриное филе, подсолить, обжарить до желтоватой корочки. Лук нашинковать полукольцами и  слегка обжарить, добавить измельченные грибы и все вместе обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8652,'Отварить яйца, очистить, порезать, смешать с мясом, грибами и горошком, добавить майонез,  помешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8652,'В салат с грибами, курицей и зеленым горошком можно всыпать по желанию порезанную на кубики отварную морковь или сухарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8653,'Просеять через сито пшеничную муку, разрыхлитель и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8653,'В отдельной емкости перемешать жидкий или засахарившийся, но растопленный, мёд с молоком, растительным маслом и сырыми куриными яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8653,'Смесь подлить к муке, взбить все миксером или венчиком до однородного состояния. Тесто должно быть густым, без комочков. При необходимости можно добавить муку. Дополнительными добавками могут стать молотая корица или сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8653,'Жарить оладьи на растительном масле с двух сторон до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8654,'Приготовить томатное пюре из очищенных от кожуры плодов. Мякоть пюрировать при помощи блендера. Массу можно дополнительно пропустить через сито, чтобы отделить семечки.','https:https://st.vkuso.ru/data/cache/thumb/fe/406b38eb671e1fe_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8654,'Прогреть пюре на тихом огне, помешивать. Ввести сахарный песок, морскую соль, оливковое масло. Варить соус в течение двадцати минут, он должен загустеть.','https:https://st.vkuso.ru/data/cache/thumb/8c/3ea09f67e85858c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8654,'За пять минут до конца приготовления добавить измельченный чеснок, сушеный базилик и орегано. Смесь охладить и использовать для приготовления пиццы.','https:https://st.vkuso.ru/data/cache/thumb/62/27fbf5541699362_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8655,'Хорошо перемешать обезжиренный творог, оливковое масло, протеин со вкусом капучино или любым другим, шоколадным, всыпать молотые миндальные орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8655,'Добавить немного ванили и молотой корицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8655,'Сформовать батончики мокрыми руками, положить в морозильную камеру на час или два.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8656,'Хорошо перемешать обезжиренный творог и сырые куриные яйца, соль – по вкусу, добавить сушеную или свежую рубленую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8656,'Массу выпечь под крышкой в течение 7 – 10 минут на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Гречку отварить до готовности в подсоленной воде, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Куриное филе пропустить через мясорубку, то же проделать с гречневой кашей и чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Репчатый лук накрошить мелкими кубиками, обжарить на масле до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Добавить обжарку в фарш вместе с сырым куриным яйцом, соль и перец – по вкусу, вымешать. Готовая масса не должна прилипать к рукам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Отдельно отварить 3 яйца вкрутую, накрошить вместе с зеленым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8657,'Сформовать зразы с начинкой, обжарить на тихом огне до готовности, подать в горячем виде.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8658,'Грудку промыть, сбоку вырезать «карман» острым ножом. Натереть любыми специями для курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8658,'Для начинки натереть сыр, смешать с кефиром и давленым чесноком. Массу хорошо перемешать, выложить в «карманы», место разреза скрепить зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8658,'Готовые изделия можно присыпать небольшим количеством оставшегося сыра или специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8658,'Смазать небольшим количеством масла форму для выпекания, выложить грудки, разрез должен быть вверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8658,'Поставить блюдо в духовку, печь в течение 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8659,'Разрезать куриную грудку вдоль, немного отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8659,'Разогреть на сковороде растительное масло, положить веточки тимьяна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8659,'Грудку натереть солью и черным молотым перцем, выложить на разогретую сковороду, обжарить с каждой стороны по пять-семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8659,'Отдельно, на другой сковороде, обжарить нарезанные полосками овощи, сначала баклажаны, в течение двух-трех минут, затем – репчатый лук, в заключение – сладкий болгарский перец. Все вместе потушить еще 20 минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8659,'На тарелку выложить листья зеленого салата, сверху – овощную обжарку, третий слой – куриное мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8660,'Куриное филе вымыть, снять кожицу, потушить мясо на сковороде до золотистого цвета, добавив немного воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8660,'Нарезать небольшие помидоры, огурцы, измельчить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8660,'На тарелку выложить хорошо промытые и обсушенные листья зеленого салата, сверху – нарезку из овощей в любом порядке, остывшую, нарезанную курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8660,'Посыпать блюдо зеленью, заправить оливковым маслом и подать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Смешать геркулес, кокосовую стружку, протеин, сухое молоко, сырые куриные белки, сахарозаменитель, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Форму для выпекания смазать оливковым, миндальным или тыквенным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Печь массу для батончиков при температуре 165 градусов в течение 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Остывший «корж» нарезать брусками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Отдельно развести какао-порошок водой, добавить сахарозаменитель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8661,'Готовой глазурью полить батончики, посыпать остатками кокосовой стружки и поставить в холодильник для застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Первым этапом приготовить рис, перебрать, промыть до чистой воды. Переложить рис в небольшую кастрюлю, всыпать бадьян (звездный анис), измельченный корень имбиря, посолить, поперчить, залить водой, закрыть крышкой и дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Уменьшить нагрев и варить, не снимая крышки, около 10 минут. Снять крышку, убрать специи, которые всплыли на поверхность, добавить измельченные перья лука, натертый на мелкой терке имбирь, перемешать, отставить в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Теперь готовим курицу.  Разогреть кунжутное масло (можно заменить растительным или арахисовым), выдавить чеснок, натереть на мелкой терке имбирь, порезать зеленый лук, все жарить около минуты, добавить куски курицы и обжарить с 2 сторон до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Смешать для соуса сахар, рисовый уксус, соевый соус, воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Смешать готовое куриное филе, добавить приправу 5 специй, влить соус, перемешать, дать закипеть, снять с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8662,'Подавать курицу с рисом и пряным соусом следующим образом: разложить рис по тарелкам, сверху положить мясо, полить соусом, присыпать измельченными перьями зеленого лука.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8663,'Сварить овощной бульон из сельдерея и моркови, измельченного репчатого лука, стебля лука-порея. Добавить рубленую зелень петрушки, лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8663,'В лист пергамента завернуть филе семги, шпинат. Рыбу можно сбрызнуть свежим лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8663,'Полученные бумажные «конверты» опустить в горячий бульон, накрыть крышкой, варить в течение пяти минут. Выложить рыбу и зелень на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8664,'Телятину нарезать на тонкие полоски.','https:https://st.vkuso.ru/data/cache/thumb/26/7fe18800bdc0e26_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8664,'Полить соевым соусом и оставить мариноваться.','https:https://st.vkuso.ru/data/cache/thumb/e1/8c952348d88b8e1_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8664,'Таким же образом нарезать морковь, сладкий болгарский перец, тыкву, порубить чеснок.','https:https://st.vkuso.ru/data/cache/thumb/82/56a13fc569a0c82_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8664,'Обжарить овощи в сковороде вок или в утятнице, в любой другой посуде с толстым дном, затем добавить мясо и зеленый лук.','https:https://st.vkuso.ru/data/cache/thumb/63/ec3db7cac5e0163_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8664,'Отдельно отварить фунчозу в течение двух-трех минут. Лапшу добавить в смесь мяса и овощей, подержать на огне в течение трех-пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/39/f6b556294c10a39_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8665,'Порезать отварную курицу, смешать с пекинской капустой, нарезанной на полоски, нашинкованным зеленым луком, помидорами, заправить соусом, а перед подачей добавить ананас.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8665,'Салат с курицей, ананасами и помидорами поперчить и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8666,'Нарезать на небольшие кусочки филе курицы, добавить сухой быстрорастворимый желатин, перец, измельченный чеснок,  паприку, зелень, посолить, все тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8666,'Переложить смесь в пакет для запекания, хорошо закрепить концы, поместить в лоток для запекания, запекать 50 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8666,'Вынуть рулет из курицы с чесноком «Мраморный», дать остыть, поставить в холодильник для окончательного застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8666,'Вынуть рулет из формы,  нарезать на кусочки, выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'Нарезать филе рыбы на крупные куски, поперчить смесью из острых перцев, чуть посолить и дать постоять полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'Нашинковать лук полукольцами, порезать помидоры на четвертинки, а сельдерей – тонкими круглыми пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'Сварить в мундире картофель до полуготовности, дать остыть, почистить, порезать тонкими кружочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'В миску влить оливковое масло, всыпать растертый розмарин, посолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'Положить картофель, сельдерей, помидоры, лук, все хорошо смешать с маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8667,'Переложить куски лосося на противень, поверх картофеля, запечь при температуре 180 градусов. Запеченный лосось с картофелем, сельдереем и помидорами черри будет готов примерно через полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'Зеленую стручковую фасоль отварить в течение нескольких минут, откинуть на дуршлаг и промыть проточной ледяной водой. Такой нехитрый прием позволит сохранить зеленый цвет продукта.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'Отварить вкрутую куриные яйца, очистить, разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'Нарезать помидоры черри пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'Для приготовления заправки смешать бальзамический уксус, дижонскую горчицу, оливковое масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'В миску выложить маслины без косточек, консервированного туннесца без жидкости, помидоры и фасоль, полить заправкой, посолить и поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8668,'Салат перемешать, разложить в тарелки, сверху украсить половинками крутого яйца и зеленью петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Желатин залить небольшим количеством молока, оставить для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Перемешать в сотейнике сливки, остатки молока, добавить хороший кофе крупного помола. Сливочную смесь довести до кипения, снять с огня, накрыть крышкой и дать постоять в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Еще раз подогреть, добавить сахарозаменитель, желатин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Готовую смесь процедить через сито и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Для приготовления кофейного желе желатин залить холодной водой, оставить на несколько минут для набухания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Сварить натуральный кофе со щепоткой сушеного имбиря, распустить в нем желатин, затем процедить и остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Ножом для чистки овощей снять цедру с хорошо вымытых апельсинов, нарезать её полосками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Залить цедру кипящей водой на две минуты, откинуть на дуршлаг и пролить холодной водой, таким образом можно удалить горечь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Мякоть апельсинов очистить от пленок, из остатков отжать сок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Очистить и натереть корень имбиря.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Ингредиенты поместить в кастрюлю, добавить цветочный мёд, готовить 20 минут, помешивать. Должна получиться густая и однородная масса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Подсушить в духовке или на сухой сковороде очищенный фундук, крупно порубить с помощью блендера.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8669,'Залить в форму желе и панна-котту слоями, каждому предыдущему слою дать застыть в холодильнике. Выложить сверху любимый конфитюр.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8670,'Измельчить сыр на мелкой терке, всыпать крахмал, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8670,'Выложить ложкой смесь тонким слоем на сковороду, дать расплавиться, снять с огня и дать чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8670,'Переложить сырный блинчик на перевернутый вверх дном стакан, слегка обмять пальцами, дать застыть, снять со стакана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'После остывания залить кейк глазурью.','https:https://st.vkuso.ru/data/cache/thumb/61/b515d7dfd1a4561_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8670,'Использовать для корзиночек из сыра любую начинку, сочетающуюся с сыром. Очень вкусны сырные тарталетки с креветками, огурцом и укропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Приготовить тесто из муки, воды, щепотки соли и сахара, сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Массу вымесить, раскатать и поставить в духовой шкаф на 15 – 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/62/d9116152efba562_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Для приготовления соуса смешать сметану, растительное масло, асафетиду, куркуму, прованские травы. Варить в течение двух-трех минут.','https:https://st.vkuso.ru/data/cache/thumb/af/0f15608758a72af_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Обжарить баклажаны и кабачки, нарезанные пластинками, до золотистой корочки на растительном масле.','https:https://st.vkuso.ru/data/cache/thumb/ba/ee52ed492a152ba_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Основу вынуть из духового шкафа и смазать горячим соусом, поверх выложить обжаренные овощи.','https:https://st.vkuso.ru/data/cache/thumb/a9/b52019b62a793a9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Посыпать начинку измельченным болгарским перцем, полить соусом и поставить в духовку еще на пять-семь минут.','https:https://st.vkuso.ru/data/cache/thumb/35/affdb954ae91835_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Вынуть, выложить сверху помидоры.','https:https://st.vkuso.ru/data/cache/thumb/ac/77237f5273c71ac_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Еще раз полить соусом.','https:https://st.vkuso.ru/data/cache/thumb/42/54e3141c2750b42_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8671,'Посыпать тертым твердым сыром. Запечь пиццу в течение нескольких минут и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/4b/3ed3ac7bb33744b_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Куриное филе вымыть, нарезать кубиками средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Приготовить маринад из соевого соуса, бальзамического уксуса, рубленого чеснока, сухих трав, молотого перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Положить в готовую смесь мясо, подержать в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Вымыть и очистить морковь, натереть на крупной терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Разморозить капусту брокколи, разделить на соцветия, посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Курицу выложить на горячую сковороду без жира, тушить под крышкой в течение пяти минут, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Добавить морковь, тушить еще три-четыре минуты, огонь – средний. Добавить брокколи, перемешать, прогреть под крышкой еще пять-семь минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8672,'Отдельно смешать сливки и творожный или сливочный сыр. Смесь подлить в основную массу, довести до кипения, тушить на тихом огне пять-семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8673,'Сыр Моцарелла и замороженные баклажаны нарезать кубиками. То же самое проделать со свежими помидорами.','https:https://st.vkuso.ru/data/cache/thumb/8a/64cb80c709e238a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8673,'Сыр «Пармезан» натереть на терке. Все ингредиенты перемешать, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8673,'Выложить в форму готовое слоеное тесто из магазина, наколоть его вилкой в нескольких местах, сделать небольшие фигурные бортики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8673,'Выложить начинку, сбрызнуть оливковым маслом. Печь в духовом шкафу при температуре 180 градусов в течение 20 – 25 минут.','https:https://st.vkuso.ru/data/cache/thumb/56/f79d9ce30595a56_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Включить духовку на 180-190 градусов, смешать одну ложку оливкового масла с панировочными сухарями, сдобрить черным перцем и солью. Выложить смесь на противень, убрать в горячую духовку примерно на 7-10 минут, дать чуть остыть, присыпать тертым пармезаном (40 г).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Взбить блендером мелко нарезанный, печеный красный перец, помидоры, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Нарезать баклажаны небольшими кубиками, обвалять в соли, переложить на салфетку, дать впитаться соку, затем поставить подсушить в микроволоновку на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Нагреть  масло в сковороде и обжарить остывшие баклажаны (10 минут), переложить в миску. В сковороду долить масло, обжарить орегано, измельченный чеснок и молотый перец чили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Сварить под крышкой макароны, смешать с томатным пюре, всыпать оставшийся пармезан с баклажанами. Выложить сверху моцареллу, присыпать сухарями и поставить в духовку. Готовить до расплавления сыра (7-10 минут).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8674,'Присыпать сырную пасту с баклажанами и перцем, запеченную в духовке измельченным свежим базиликом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8675,'Растереть в ступке чеснок с пряностями и солью до кашицы, влить масло, перемешать в кашицу для получения маринада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8675,'Нарезать  куриное мясо на полоски по 2 сантиметра толщиной, залить маринадом, перемешать, убрать в холодное место на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Добавить лук-порей, морковь, любые специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8675,'Разогреть сковороду, налить масло, положить сахар, выжать сок лайма,  корочки лайма тоже положить на пару минут для аромата, нагреть до растворения сахара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8675,'Переложить на сковороду мясо в маринаде, перемешать, всыпать кубики ананаса, накрыть крышкой, готовить примерно 5 минут на среднем огне. Не пережарить: мясо станет сухим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8675,'Курица с ананасами и лаймом подается к столу в горячем виде с вареным рисом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Растопить на плите кокосовое масло, отдельно просеять муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Перемешать с помощью венчика оба ингредиента, добавить пищевую соду, миндальную муку, соль, какао-порошок, тростниковый сахар, вбить сырые куриные яйца, вмешать кокосовое и оливковое масло, молоко, винный уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Взбить массу до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Тесто вылить в форму, печь в течение 45 минут, готовность проверить зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Бисквит остудить, разрезать на две или три части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Для крема: шоколад растопить со сливками, остудить, убрать в холодильник. Взбить сыр «Маскарпоне», добавляя охлажденный ганаш из холодильника и немного сахарной пудры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Коржи покрыть шоколадным кремом, добавить чернику, ежевику.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8676,'Торт покрыть ганашем. Для ганаша: растопить шоколад 140 г с 90 мл сливок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8677,'Филе курицы пропустить через мясорубку вместе с репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8677,'В фарш добавить куриные яйца, рубленую зелень укропа и петрушки, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8677,'Жарить котлеты на сковороде или на гриле, до готовности. Должна получиться аппетитная румяная корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8678,'Нарезать мелко фрукты, размять мороженое, смешать с измельченным печеньем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8678,'Смешать сгущенное молоко и сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8678,'Выложить фруктовый десерт в высокие стаканы слоями: чередуя слои фруктов с мороженым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8678,'Залить фрукты молочно-сметанной смесью, убрать в морозилку на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Овсяные хлопья измельчить с помощью кофемолки. Соединить с отрубями, ржаными или пшеничными, молотой корицей, разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Отдельно взбить сырые куриные белки с сахарной пудрой, в пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Нежирный кефир или йогурт взбить с желтками до однородного состояния. Соединить смесь с сухими продуктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Осторожно ввести взбитые белки, перемешивать движениями снизу вверх.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Противень застелить бумагой для выпекания, вылить готовую массу, печь при температуре 180 – 200 градусов в течение 15 – 25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8679,'Полученный корж разрезать по горизонтали острым ножом, промазать любым кремом или густым вареньем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Картофель очистить и нарезать тонкими пластинками. Можно использовать молодые клубни.','https:https://st.vkuso.ru/data/cache/thumb/cf/b8ab514d51851cf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Форму для запекания смазать растительным маслом, выложить картофель, продукт посолить и поперчить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/08/5daf570d8d69808_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Поверх выложить филе семги, нарезанное кусочками. Можно сбрызнуть рыбу лимонным соком.','https:https://st.vkuso.ru/data/cache/thumb/25/7a1ec60a0ef3225_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Следующий слой – полукольца репчатого лука, их лучше предварительно обдать кипятком для удаления горечи.','https:https://st.vkuso.ru/data/cache/thumb/c9/c2eb682dd6288c9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Для приготовления соуса смешать сметану, молотый черный перец с солью и зеленью укропа, добавить воду.','https:https://st.vkuso.ru/data/cache/thumb/8f/f029cab6a0dfe8f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8680,'Полить смесью блюдо, поставить его в духовой шкаф на 40 минут, температура приготовления – 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/40/a86c644fbd70440_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8681,'Смешать миксером на малых оборотах яйца со сгущенкой, влить растопленное сливочное масло и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8681,'Добавить к массе муку (предварительно просеять), ванильный сахар (по желанию) и разрыхлитель, тщательно перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8681,'Подготовить форму: смазать маслом, присыпать мукой. Вылить тесто в форму, печь кекс на сгущенном молоке чуть более получаса при температуре духовки 150 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8701,'Переложить овощной салат с курицей и кальмарами в салатницу, посолить, залить сметаной и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8681,'Дать постоять готовой выпечке 10 минут в форме, вынуть и остудить окончательно. Присыпать кекс сахарной пудрой, подать к чаю с лимоном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8682,'Измельчить сыр на мелкой терке, всыпать в муку, смешать руками в крошку с охлажденным маслом. Вливать по ложке воды и вымешивать до тех пор, пока тесто не станет однородным, оставить на 1 час в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8682,'Включить на разогрев до 200 градусов духовку. Достать тесто, очень тоненько раскатать, вырезать формочками фигурки или просто нарезать на квадратики, наколоть каждый кусочек вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8682,'Переложить крекеры «Квадратики» с сыром на противень, печь порядка 10 минут, без присмотра не оставлять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8682,'В крекеры по вкусу можно добавить зелень, паприку или немного острого красного перца, тогда получится прекрасная закуска к пиву.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8683,'Перемешать натуральный мёд, соль, молотый перец, оливковое масло, тертую цедру двух лимонов и сок одного плода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8683,'Куриное филе выложить в форму для запекания, сверху вылить смесь, равномерно размазать её по курице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8683,'Поставить форму в духовку, разогретую до 180 градусов, печь в течение получаса или чуть больше, несколько раз поливать маринадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8683,'Филе должно стать золотисто-коричневым, жидкость – выпариться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8683,'Готовые грудки вынуть, остудить, нарезать и подать с дольками апельсина, запеченными до легкой карамелизации.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8684,'Взбить яйцо, соду, сахар и масло, смешать какао и муку, размешивая, постепенно всыпать в подготовленное тесто. Вымешивать пока тесто не перестанет липнуть к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8684,'Отделить от куска теста четвертую часть и отложить. Большую часть распределить по дну формы, сформовать бортики примерно в 3 см и отправить на 20 минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8684,'Смешать вместе все ингредиенты для крема (миксер не применять!) и выложить на охлажденное тесто. Из меньшей части теста скатать шарики и «утопить» в творожной начинке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8684,'Отправить форму в духовку, разогретую до 180 градусов. Пирог с творожным кремом будет готов через 40-50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Сливочное масло комнатной температуры взбить в пышную массу вместе с сахаром до белого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Растопить шоколад в микроволновой печи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Отдельно натереть цедру хорошо вымытого апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'В масляную смесь добавить жидкий шоколад и цедру, взбить смесь еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Отдельно смешать какао-порошок с мукой и разрыхлителем. В масляную смесь влить молоко и сырые куриные яйца, все взбить еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Просеять в смесь сухие ингредиенты, замесить тесто, оно должно получиться гладким и однородным, без комочков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Взять две формы разного размера, одна должна свободно помещаться в другой. Меньшую емкость смазать сливочным маслом, вылить в неё тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Большую форму наполнить водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Форму с тестом затянуть фольгой, поместить в большую емкость с водой. Поставить на плиту, довести воду до кипения, огонь уменьшить до среднего.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Варить полтора часа – уровень воды не должен меняться, вода должна немного кипеть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Готовое блюдо снять с плиты и остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Готовый торт вынимается легко, при остывании его размеры уменьшатся.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Для глазури перемешать сахарный песок со сметаной, какао-порошком и сливочным маслом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8685,'Поставить смесь на тихий огонь, варить три минуты на среднем огне, остудить. Вылить глазурь в центр торта – она сама растечется по поверхности ровным слоем.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8686,'Крупно порезать помидоры (можно разрезать на 2 части), измельчить на мясорубке чеснок, болгарский и жгучий перец, порубить зелень, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8686,'Переложить послойно в банку объемом 3 л: помидоры-овощи-зелень. Залить содержимое банки заправкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8686,'Закрыть банку крышкой, перевернуть крышкой на тарелку и отправить ночевать в холодильник. Утром помидоры по-корейски можно уже кушать. Банку можно поставить в нормальное положение, пока верхний слой съедите, нижний тоже будет готов. Через день блюдо становится еще вкуснее!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8687,'Включить на разогрев до 180 градусов духовку. Натереть цедру двух лимонов, высыпать в оливковое масло, добавить соль, сок лимона, перец, жидкий мед, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8687,'Филе курицы уложить в форму для запекания, вылить на нее приготовленную лимонную смесь. Отправить в горячую духовку, запекать куриные грудки в лимонном соусе с медом примерно полчаса до аппетитного золотистого цвета. Периодически поливать маринадом. В конце жарки его почти не останется. Подавать мясо порезанным на ломти с кружочками лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8688,'Промыть и подготовить говяжий язык, положить в кастрюлю вместе с морковью и половинкой луковицы, залить холодной водой, сдобрить солью и лавровым листом. Варить 2 часа, проверять готовность вилкой: легко входит – мясо готово.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8688,'Отварной говяжий язык вынуть из бульона, дать чуть остыть и снять шкурку (когда язык остынет, сделать это будет тяжелее). Мясо нарезать на ломтики, подать с горчицей или хреном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8689,'Отварить очищенный картофель, приготовить из него пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8689,'Обжарить на масле мелко покрошенный лук, добавить грибы, продолжить обжаривать до испарения всей жидкости, посолить, дать немного остыть и измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8689,'Переложить массу в кастрюлю к картофельному пюре, влить сливки, поперчить, посолить. Измельчить все блендером до однородного состояния. Дать грибному супу-пюре с картофелем закипеть, посыпать зеленью и подать к столу. К этому нежному супчику можно подать белые сухарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8690,'Смешать соль, разрыхлитель и муку. В другой миске смешать до однородного состояния сахар, переспелые бананы, растительное масло, яйцо, смешать с мукой, постепенно вливая молоко. Взять 1/3 часть теста и всыпать к нему корицу, перемешать, переложить в кондитерский мешок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8690,'Выложить на разогретую сковороду белое тесто, а из мешка нанести на него узор. Обжарить блинчики банановые с корицей с двух сторон до желто-коричневого цвета. К блинам подать сметану, сливочное масло, мед или варенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8691,'Натереть сыр на терке, мелко нарезать укроп. Перемешать миксером все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8691,'Обжарить хачапури на скорую руку на сковороде в разогретом масле до аппетитной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8692,'Потереть очищенные клубни картофеля на крупной терке, посолить, размешать и отжать лишний сок и воду. Вбить в массу яйца, мелко нарезать или выдавить через пресс чеснок, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8692,'Разогреть в сковороде растительное масло, выложить в кипящее масло столовой ложкой картофельную смесь в форме тонких оладий для лучшего прожаривания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8692,'Готовые драники из картошки, прожаренные с обеих сторон до золотистого цвета, переложить на несколько сложенных салфеток, чтобы избавиться от лишнего жира. Подавать драники горячими со сметаной или кетчупом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8693,'Очистить клубни картофеля, отварить вместе с капустой брокколи.','https:https://st.vkuso.ru/data/cache/thumb/3d/29c8ffe0336973d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8693,'Влить в отдельную кастрюлю сливки, добавить сливочное масло, кориандр, асафетиду и соль. Все ингредиенты хорошо перемешать и довести до кипения.','https:https://st.vkuso.ru/data/cache/thumb/5f/3b6b048bf4c025f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8693,'Всыпать пшеничную муку, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/92/9620efcf1321192_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8693,'Полученную смесь вылить в картофель и брокколи, взбить с помощью блендера.','https:https://st.vkuso.ru/data/cache/thumb/b6/bc4647b3c3b9bb6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Растопить темный шоколад со сливочным маслом на водяной бане.','https:https://st.vkuso.ru/data/cache/thumb/e1/2aa6aa8573717e1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Взбить сырые куриные яйца с сахаром.','https:https://st.vkuso.ru/data/cache/thumb/21/75150140786e521_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Обе массы перемешать.','https:https://st.vkuso.ru/data/cache/thumb/0a/c22ea5b1e4dec0a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Всыпать пшеничную муку, еще раз перемешать. Можно использовать блинный или обычный продукт высшего сорта. Дно формы для выпекания застелить пергаментом, вылить массу.','https:https://st.vkuso.ru/data/cache/thumb/ab/bbd4a673ef3e2ab_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Отдельно растопить белый шоколад.','https:https://st.vkuso.ru/data/cache/thumb/76/9d2fab91f087c76_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Перемешать с яйцом творожный сыр, добавить белый шоколад, перемешать до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/d1/8422962eac0e4d1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Влить творожную смесь в шоколадную, разровнять.','https:https://st.vkuso.ru/data/cache/thumb/5d/e34c22825aba45d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Печь брауни в заранее разогретой до 150 градусов духовке, время – около часа. Серединка пирога должна остаться сыроватой. Блюдо остудить в форме, дать постоять несколько часов.','https:https://st.vkuso.ru/data/cache/thumb/97/90b3dbdc0350697_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8694,'Затем выпечку вынуть, переложить на блюдо, верх посыпать какао-порошком или тертым шоколадом.','https:https://st.vkuso.ru/data/cache/thumb/46/176a72c738f1546_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8695,'Подготовить баклажаны, порезать на кружочки, посолить, дать постоять 30 минут, сцедить сок, пожарить в разогретом растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8695,'Для соуса смешать измельченный чеснок, сметану, аджику и зелень укропа. Разложить обжаренные баклажановые кружочки на блюдо, полить соусом, выложить еще один слой и снова полить соусом, посыпать укропом. Подать баклажаны в остром соусе с брынзой или адыгейским сыром, базиликом и петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8696,'На большой сковороде прогреть сливочное масло, всыпать сахарный песок. Прогреть смесь до карамельного оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8696,'Добавить любые фрукты или размороженные ягоды, потушить. Довести соус до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8696,'Отдельно растворить картофельный крахмал в холодной воде, влить в соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8696,'Добавить свежий сок лимона, уварить соус до загустения, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8696,'Влить ликер «Амаретто», перемешать. Снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'В майонез выдавить чеснок, хорошо перемешать. На большое блюдо, в центр, поставить небольшую банку или стакан. Вокруг слоями выложить нарезанные продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Первый слой: отваренное куриное филе, нарезанное кусочками, с солью и перцем по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Второй слой: кубики киви, тонко намазать майонез с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Третий слой: натертые куриные белки, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Четвертый слой: заранее отваренная и натертая на крупной терке морковь, майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Пятый слой: тертое яблоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Верх и бока готового салата обмазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Натереть желтки, посыпать верх салата.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8697,'Оставить блюдо для пропитывания на час в холодильнике. Банку из центра удалить, кольцо украсить тонко нарезанными кружками киви.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8698,'Перетереть творог с ванилином, яйцами и сахаром, добавить масло, сметану, манку, перемешать до однородного состояния. Зажечь и разогреть до 180-200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8698,'Подготовить формы для кексов: сбрызнуть водой, посыпать манкой, металлические формочки сначала смазать маслом. Разложить творог по формочкам, выпекать творожные кексы-сырники в духовке 20-30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8698,'Разложить сырники по тарелкам, полить сметаной с добавлением сахара или вареньем. При замешивании в творог можно добавить изюм, кусочки фиников, курагу, корицу и чуть куркумы для цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8699,'Разогреть на небольшой сковороде растительное масло, быстро обжарить говяжью вырезку со всех сторон. Снять с огня, завернуть в лист фольги и положить в морозилку на 45 – 60 минут.','https:https://st.vkuso.ru/data/cache/thumb/b5/c29ab397a4d98b5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8699,'Вынуть филе и тонко нарезать. Плоской стороной ножа расплющить мясо по всей поверхности, кухонными молотками не пользоваться.','https:https://st.vkuso.ru/data/cache/thumb/46/41d1ee940d08046_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8699,'Выложить на большую сервировочную тарелку рукколу, сверху – слой мяса. Соль и перец молотый – по вкусу. Перемешать лимонный сок, бальзамический уксус, оливковое масло и соевый соус. Полученной смесью равномерно полить мясо.','https:https://st.vkuso.ru/data/cache/thumb/bd/1d73efac07932bd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8700,'Обжарить измельченный лук с мелко нарезанной морковкой 5 минут, прокрутить на мясорубке и смешать с рыбой, пропущенной через мясорубку, и мякишем белого хлеба, замоченным в молоке и так же пропущенным через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8700,'Смешать рыбный фарш с отварным рисом, вбить яйцо, посолить, поперчить и тщательно пермешать. Сформовать и зажарить котлеты рыбные в панировке до золотистой корочки (предварительно обвалять в сухарях) на сильном огне, потом на медленном огне под крышкой довести до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8701,'Отварное куриное филе порезать на кубики, отварное филе кальмаров – соломкой, яблоки, перец и помидоры – тоже на небольшие кубики. Кубики яблок побрызгать соком лимона. Капусту обмыть и мелко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Нарезать мясо на порционные куски, заправить черным перцем, зеленью тимьяна, дать постоять полчаса в тепле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Нашинковать половину лука кубиками, остальную – кольцами, натереть крупно сыр. Поджарить кубики лука на сливочном масле, переложить в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Растопить сливочное масло, всыпать муку, обжарить минуты три, влить, постоянно помешивая небольшими порциями молоко, добавить в конце сливки, проварить несколько минут. Снять соус с плиты, чуть остудить, всыпать сыр, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Застелить противень фольгой, смазать маслом, выложить кольца лука, сверху – мясо, а на него жареный лук, залить сверху соусом из сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Мясо по-французски со сливками и пармезаном запекать около часа, сначала при 180 градусах, а потом при 150 градусах. Чтобы верхняя корочка не подгорела можно в конце прикрыть фольгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8702,'Блюдо всегда получается очень нежным и вкусным. Если нет свежего тимьяна, то можно пользоваться и сухим, но без него мясо будет уже не «французским».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8703,'Добавить к протертому через сито творогу йогурт и сметану, размешать, добавить желтки, взбитые до белого состояния с сахаром, белки взбить в устойчивую пену и аккуратно добавить к творожной массе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8703,'Сварить кофе, дать остыть, влить миндальную эссенцию и хороший коньяк. Печенье смочить в кофе, переложить в формочки, сверху – массу из творога, повторить процедуру. Отправить десерт Тирамису творожный на ночь в холодильник, но если очень не терпится, то можно есть и через несколько часов, посыпав порошком какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8704,'С помощью блендера  или миксера взбить творог с яйцами, добавить по вкусу сгущенное молоко и ваниль (при желании), все вместе взбить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8704,'Духовку разогреть до 180 градусов, форму смазать сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8704,'В подготовленную форму переложить получившуюся творожную массу и поместить тесто в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8704,'Запекать ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8704,'При желании готовое лакомство можно подать с вареньем, джемом, шоколадным соусом или свежими ягодами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'Обжарить рис до коричневого оттенка на оливковом масле.','https:https://st.vkuso.ru/data/cache/thumb/e9/6b9b2cae598ede9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'Вымыть перец, разрезать на две части, удалить семена и сердцевину. Протереть, положить в форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'В салатнице соединить рис, песто, помидоры, порезанные на маленькие кубики, измельченные миндальные орешки. Если орешки свежие, то можно их не чистить.','https:https://st.vkuso.ru/data/cache/thumb/88/fc5b21be45d3b88_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'Полученную смесь разложить в перцы, накрыть форму фольгой. Готовить в духовке 35 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/ad/7f51952b67a30ad_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'Крупно натереть сыр Грана Падано. Снять фольгу с формы, посыпать перцы натёртым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8705,'Отправить в духовку на 5 минут, чтобы образовалась корка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8706,'Взбить молоко и яйца, поперчить, чуть посолить, нарезать ветчину, помидоры, сыр натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8706,'Обжарить на сливочном масле 2/3 смеси, положить на нее начинку. Дать омлету чуть зарумянится и свернуть к центру сковороды в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8706,'Передвинуть омлет на середину, а освободившееся место заполнить омлетной массой, выпекать до подрумянивания, полностью свернуть омлет в трубочку. Рулет из омлета с ветчиной, помидорами и сыром порезать и сразу подать к столу в горячем виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8707,'Порезать овощи на крупные кубики.','https:https://st.vkuso.ru/data/cache/thumb/2e/66b741922207a2e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8707,'Положить сельдь, лук и сельдерей, порезанные на кубики.','https:https://st.vkuso.ru/data/cache/thumb/7a/79bb8758a18707a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8707,'Заправить все маслом от сельди. Поперчить, размешать.','https:https://st.vkuso.ru/data/cache/thumb/ec/a4e2a0d5bc5dbec_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8707,'Положить винегрет с сельдереем и селёдкой в салатницу, украсить луком-пореем и рукколой.','https:https://st.vkuso.ru/data/cache/thumb/f3/37a47f493843bf3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8708,'Смешать для заливки соевый соус с крахмалом, лимонным соком, отставить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8708,'Все ингредиенты порезать одинаковыми небольшими кусочками. Очень быстро обжарить в воке (большая китайская сковорода с выпуклым дном и высокими стенками) мясо малыми порциями на растительном масле до корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8708,'Также порциями обжарить и овощи, следить, чтобы не пережарились. Выдавить через пресс в последнюю порцию овощей чеснок, добавить порубленную зелень, размешать и всыпать мясо и остальные овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8708,'Вылить в сковороду заливку и размешать, прожарить 1-2 минуты и убрать с плиты. Заливку в стир-фрай из свинины с шампиньонами надо наливать порциями, как только блюдо приобретет «глянец» больше не добавлять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Отварить овощи, почистить от кожуры. Размять картофель. Лаваш разрезать на 4 части.','https:https://st.vkuso.ru/data/cache/thumb/e0/9ff8d678290e3e0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Постелить на стол полиэтилен, положить на него лист лаваша, намазать его тонким слоем майонеза. Лучше использовать лаваш средней толщины, так как после пропитки майонезом, он сохраняет форму. Если лаваш очень тонкий, то он не подойдет. Отваренную свеклу остудить, крупно натереть. Положить на лаваш, намазанный майонезом. Прижать ладонью.','https:https://st.vkuso.ru/data/cache/thumb/ab/484ea6145f481ab_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Сверху положить второй лаваш, намазать тоненьким слоем майонеза.','https:https://st.vkuso.ru/data/cache/thumb/fc/a67c03685c8a8fc_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Мелко натереть отваренную морковь. Распределить по лавашу, края закрывать начинкой.','https:https://st.vkuso.ru/data/cache/thumb/d6/fc8b81ea5bdcbd6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Положить сверху третий лист, намазать майонезом.','https:https://st.vkuso.ru/data/cache/thumb/c1/37e9a23cc7a2cc1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Крутое картофельное пюре выложить ложкой на лаваш, равномерно распределить, прижать ладонью. Слои должны быть не очень толстые.','https:https://st.vkuso.ru/data/cache/thumb/22/168708a58cdfd22_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Свернуть лаваш рулетом. Сворачивать по короткой стороне, тогда получится больше слоев.','https:https://st.vkuso.ru/data/cache/thumb/a2/4fae5ff0d5813a2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Завернуть в пищевую пленку, края закрутить. Отправить на 30 минут в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/37/f1737cb74c62137_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8709,'Достать рулетик, порезать на кусочки по 3-4 сантиметра. Положить на блюдо. На каждый кусочек положить по кусочку соленой селедки. Украсить сельдь под шубой в тонком лаваше зеленым луком.','https:https://st.vkuso.ru/data/cache/thumb/06/5a219076a404e06_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Взбить творог блендером, добавить 100 грамм сметаны. Должна получиться гладкая смесь без комков.','https:https://st.vkuso.ru/data/cache/thumb/bc/3d2e28ca51799bc_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Разделить желтки и белки. Взбить белки с 1/2 стакана сахара. Постепенно добавить в белки половину стакана растительного масла, не имеющего запах, половину стакана муки и 5 желтков.','https:https://st.vkuso.ru/data/cache/thumb/5f/cf7e3202251575f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Положить часть массы в формочку с высокими стенками. В оставшуюся часть положить взбитый творог.','https:https://st.vkuso.ru/data/cache/thumb/b8/b67d18b14d3cfb8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Посолить, насыпать половину стакана сахара, налить 1/3 стакана молока, ванильный сахар. Вымесить при помощи миксера, аккуратно вылить в форму на первый слой, который после этого по краям поднимется.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Отправить в горячую духовку на 40-60 минут, соблюдать температуру 180-200 градусов. Торт увеличится и приобретет коричневый оттенок.','https:https://st.vkuso.ru/data/cache/thumb/ce/58ae66b74f079ce_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Достать из духовки, намазать смесью сметаны и сахара. Отправить в горячую выключенную духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8710,'Разложить по торту свежие или консервированные ягоды или фрукты. Вылить на них желе, состоящее из 2 стаканов сиропа, где бланшировались фрукты и 1 стакана подготовленного желатина. Можно подавать творожно-фруктовый чизкейк с желе.','https:https://st.vkuso.ru/data/cache/thumb/b3/10bbb25bbf82fb3_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8711,'Прогреть духовку чуть выше 200 градусов, на противень постелить фольгу, разложить кружки помидоров, сбрызнуть их смесью масла с перцем, чесноком, сахаром и солью, выпекать 20-25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8711,'Обжарить на сковороде в сливочном масле ломтики хлеба с двух сторон. Раскалить сковороду и высыпать тертый пармезан, обжарить до хруста, убрать с плиты и поломать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8711,'Каждый кусок хлеба присыпать козьим сыром, положить 2-3 кольца помидора, посыпать зеленью, побрызгать уксусом, оформить бутерброды с запеченными помидорами и сыром хрустящими кусочками пармезана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'На растительном масле спассеровать измельченный репчатый лук, сыр крупно потереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Картофель очистить, крупно натереть на терке, добавить соль и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8726,'Влить половину нормы сливок, затем остальные, порциями, продолжать помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Отварные яйца порезать меленькими кусочками и смешать с молотым перцем и столовой ложкой майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Из фарша (он должен быть как для котлет) сделать круглые лепешки диаметром в 10 см каждая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Противень застелить пергаментом и выложить на него подготовленные лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Подготовленные продукты распределить слоями на каждую мясную лепешку в следующем порядке: жареный лук, измельченные яйца, тертый картофель и тертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8712,'Залить все получившиеся стожки майонезом и запекать их при 180 градусах на протяжении 30-35.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8713,'С помощью блендера (можно вручную) из творога (обязательно не водянистого)  и банана сделать однородное пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8713,'Добавить в эту творожно-банановую массу молотую овсяную крупу или крупно молотые овсяные хлопья и замесить тесто, которое затем поместить на 1 час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8713,'Из подмерзшего теста сформировать шарики, обвалять каждый в молотых (рубленых) орехах, маке или кокосовой стружке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8713,'Каждую заготовку чуть приплюснуть и переложить на предварительно смазанный маргарином противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8713,'Выпекать творожно-банановое печенье  не дольше 15 минут в духовке, разогретой до 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8714,'Промытый стейк лосося натереть солью с обеих сторон и переложить на фольгу, распределенную по противню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8714,'Посыпать рыбу по вкусу черным молотым перцем и сушеным базиликом, сверху выложить дольки лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8714,'Края фольги завернуть так, чтобы стейк полностью под ней «спрятался» и убрать противень на 25 минут в разогретую до 180-200 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8714,'Готовый лосось с лимоном и базиликом, запеченный в фольге, подается в горячем виде с любимым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Соединить в емкости творог, манную крупу, ванилин, сахар, желток.','https:https://st.vkuso.ru/data/cache/thumb/61/80a3c3d8caffb61_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Разделить массу на 4 части. В каждую часть насыпать по 20 грамм разноцветной кокосовой стружки.','https:https://st.vkuso.ru/data/cache/thumb/58/9c3a1f8491cf758_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Слепить по 4 шарика каждого цвета, отправить на 30 минут в холод.','https:https://st.vkuso.ru/data/cache/thumb/3e/d860201a6de633e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Приготовить тесто: растереть миксером подтаявшее масло и сахар. Взбить яйца и 1 белок. Положить сметану. Насыпать муку, просеянную с разрыхлителем. Разделить тесто на несколько частей: 2/3 и 1/3.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'В часть поменьше насыпать просеянный какао-порошок. Готовить корж в формочке 20 на 20 сантиметров 25-30 минут, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Готовый корж выложить на решетку, остудить, разрезать пополам.','https:https://st.vkuso.ru/data/cache/thumb/cf/de7a2734e7ed0cf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Положить в форму тесто без какао. Выложить на пласт кокосовые шарики. Готовить 35-40 минут при температуре 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/4e/5093b7091cc1b4e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Достать готовую выпечку, дать остыть. Приготовить крем: взбить сметану и сахарную пудру.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Собрать пляцок: положить шоколадный корж, намазать кремом. Сверху положить белый корж, намазать кремом. На него положить шоколадный корж, промазать сметанным кремом. Обрезать неровные краешки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Украсить кондитерской посыпкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8715,'Отправить творожный пляцок с цветными шариками на несколько часов в холодильник, чтобы пропитался.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Нагреть воду в сотейнике, насыпать сахар, перемешать. Подождать, пока сахар растворится, чуть-чуть покипятить сироп. Убрать сироп с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Взбить, чтобы от немного помутнел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Положить молотый миндаль, добавить взбитые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Варить несколько минут, смесь должна отставать от стенок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Положить смесь на доску, посыпанную сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Вымесить массу, посыпая сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Слепить из марципана фигурки, можно скатать шарики или порезать на квадраты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8716,'Завернуть в пергамент или фольгу, хранить в контейнере с плотной крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Развести дрожжи в теплом молоке, насыпать сахар, несколько ложек муки. Поставить опару на 15 минут в теплое место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Переложить готовые кунжутные трубочки с сыром на тарелку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'В емкость просеять муку, вбить яйцо, положить творог, сливочное масло, порезанное на куски, насыпать соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Влить опару, замесить среднее по консистенции тесто. Накрыть пленкой, отправить в тепло, чтобы тесто поднялось.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Через 30 минут обмять тесто, складывая его.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Через 60 минут можно приступать к работе. Разделить тесто на 4 одинаковые части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Из каждой раскатать жгут, их кончики скрепить вместе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Чтобы проще было плести, на край поставить емкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Крайний правый жгут положить на третий, затем под второй и вернуть на первый. Повторять процедуру, пока не закончатся жгуты. Концы подвернуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Накрыть пленкой. Отправить в теплое место на 30 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Затем намазать творожный цопф взбитым яйцом, посыпать маком или кунжутом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8717,'Выпекать 40 минут, соблюдать температуру 190 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8718,'В чашу кухонного комбайна сложить творог, геркулес, разрыхлитель, молотую корицу и яичные белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8718,'Взбить все ингредиенты до однородности, перелить массу в большую миску и аккуратно подмешать в нее малину (замороженную или свежую).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8718,'На сковороде обжарить оладушки овсяные с малиной на среднем огне с каждой стороны (на одну сторону уйдет где-то 1-2 минуты).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8718,'Готовые оладушки переложить на тарелку и подать горячими либо с малиновым вареньем, либо с йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Промыть овощи, порезать баклажаны на круги в толщину 1 сантиметр, посыпать солью. Отставить на 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/50/0fc6724b989fd50_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Таким же способом порезать кабачок.','https:https://st.vkuso.ru/data/cache/thumb/7b/cbd8f77478a097b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Пожарить кабачки в масле, переложить на тарелку.','https:https://st.vkuso.ru/data/cache/thumb/6e/f0b92295f58226e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Пожарить баклажаны и переложить на салфетку, чтобы впитался жир.','https:https://st.vkuso.ru/data/cache/thumb/a9/13272089c99a1a9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Мелко потереть чеснок. Соединить с измельченной зеленью.','https:https://st.vkuso.ru/data/cache/thumb/61/4146b7f2bd8c061_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Выложить кабачки, посолить, посыпать чесноком с зеленью, побрызгать уксусом.','https:https://st.vkuso.ru/data/cache/thumb/d6/4fcbf7e6518f3d6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Сверху положить баклажаны, посыпать солью, чесноком с зеленью. Повторить процесс.','https:https://st.vkuso.ru/data/cache/thumb/b4/5bbb0b433f677b4_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8719,'Положить в емкость, отправить ассорти из жаренных баклажанов и кабачков на несколько часов в холод.','https:https://st.vkuso.ru/data/cache/thumb/70/bd9808b603c7c70_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Просеять муку в емкость, налить ½ молока, вбить яйца, насыпать соль, сахар, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Налить масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Влить остальное молоко. Отставить на 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Если необходимо, добавить молоко. Тесто должно получиться жидкое, чтобы хорошо растекалось по сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Нагреть сковороду, один раз намазать растительным маслом. Выпекать тоненькие блины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Сделать начинку: соединить творог, яйцо, ванилин, сахар. Можно положить изюм.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Разрезать блины на 4 части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Из треугольников свернуть голубцы с начинкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Намазать сливочным маслом огнеупорную емкость, положить блинчики.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Ряды перекладывать сливочным маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8720,'Готовить 15-20 минут, соблюдать температуру 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Взять муку твердых сортов пшеницы. Насыпать в большую посуду или на стол, как удобно. В середине горки муки сделать ямку, налить в нее оливковое масло, вбить яйца, насыпать соль.','https:https://st.vkuso.ru/data/cache/thumb/a5/1e793282e5bc3a5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Используя вилку, осторожно смешать ингредиенты, очень маленькими порциями добавляя муку. Когда из масла, яиц и соли получится однородная масса, вмешать оставшуюся муку.','https:https://st.vkuso.ru/data/cache/thumb/80/1ee84084fe91180_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Затем начать смешивать руками. Когда все смешается, замесить тесто. Вымешивать 15 минут, чтобы получилось гладкое, цельное тесто.','https:https://st.vkuso.ru/data/cache/thumb/ff/7e8a3c5c27b31ff_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Завернуть тесто в пленку, отставить на 30-60 минут.','https:https://st.vkuso.ru/data/cache/thumb/30/439520019029830_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Растопить на водяной бане шоколад, постепенно добавить 4 больших ложки сливок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Разделить тесто на 3 части. Один кусок положить на стол, посыпанный мукой.','https:https://st.vkuso.ru/data/cache/thumb/a0/47cdd11e8c039a0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Приплюснуть тесто руками, завернуть в виде конвертика.','https:https://st.vkuso.ru/data/cache/thumb/cf/0588105fd37a7cf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Приплюснуть один край, раскатать. Опять свернуть в виде конвертика, но в другом направлении. Так создастся нужная структура и плотность теста. Раскатать. Каждый раз при раскатывании подсыпать чуть-чуть муки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Повторять данную процедуру, пока тесто не приобретет шелковистый, тоненький, плотный вид. Придется раскатать и сложить приблизительно 12 раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'Приготовленное тесто отставить минимум на 2 часа, чтобы оно подсушилось. Можно отставить на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8721,'После этого можно хранить домашнее тесто для лазаньи или пасты в холодильнике.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Измельчить орехи, ананасы, бананы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Просеять муку и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Насыпать соль, корицу и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Взбить яйца и масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Выложить яично-масляную смесь в муку, осторожно размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Добавить орехово-фруктовую смесь, ванилин, налить сироп, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Взять 3 формочки по 22 сантиметра, разложить тесто равными частями. Готовить 45 минут, соблюдать температуру 180 градусов. Готовность проверять зубочисткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Взбить все ингредиенты для крема, намазать коржи, сложить стопкой, чтобы получился торт.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Обжарить на сухой сковороде орешки, посыпать сахаром, перемешивать, пока карамель не покроет орехи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8722,'Остудить, украсить ореховый торт «Колибри».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8723,'Смешать кефир, сахар, соль, соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8723,'Медленно ввести просеянную муку, не прекращая помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8723,'Долить растительное масло, размешать венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8723,'Пожарить оладьи на горячей сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8723,'Намазать оладьи ореховой пастой. Украсить кусочками клубники и бананов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'В большую миску влить кефир (или простоквашу), добавить к нему сахар, яйцо,  соду и соль, тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'Всыпать в кефирную массу муку и замесить не тугое тесто, накрыть его чистым полотенцем и оставить на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'Далее поделить тесто на желаемое количество одинаковых кусочков и каждый раскатать в круглую лепешку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'Для начинки тщательно перемешать до однородности творог, яйцо, рубленый укроп, молотый перец и соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'В центр каждой тестяной заготовки выложить немного получившейся начинки, хорошенько защипнуть края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'Сложить вареники в пароварку и готовить их в течение 35 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8724,'Готовые вареники  с творогом и укропом на пару «искупать» в топленом сливочном масле и подать к столу со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Растворить в теплой воде дрожжи, насыпать соль, сахар, положить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Медленно насыпать в жидкость муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Вымесить тесто, переложить в емкость, намазанную растительным маслом, накрыть полотенцем, отправить на 30 минут в теплое место.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Приготовить томатный соус: соединить все продукты для соуса, отправить на сковороду, готовить 15-20 минут, разминая томаты при помощи ложки, чеснок раздавить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Положить маленькую ложку томатной пасты, посыпать солью, тушить несколько минут, отставить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Порезать колбасу на кружки. Порезать грибы, перец, лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Поделить тесто на 4 части (будет четыре средних пиццы). Тоненько раскатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Положить тесто на противень, намазанный растительным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Тонко нанести слой томатного соуса, посыпать сырами пармезан, моцарелла, выложить порезанную колбасу, перец, грибы, лук. Посыпать сыром моцарелла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8725,'Отправить пиццу с колбаской из индейки, грибами и сладким перцем в духовку на 15 минут, соблюдать температуру 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8726,'Сливочное масло и темный шоколад разогреть на водяной бане, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8726,'Всыпать столовую ложку какао-порошка. Добавить сгущенку, еще раз размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Покрыть орешки шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'В хлебопечке приготовить тесто из муки, яйца, растительного масла, соли,  воды, молока, сахара и сухих дрожжей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'При отсутствии хлебопечки тесто нужно приготовить руками из тех же ингредиентов, только после замеса его нужно поставить в теплое место на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'Раскатать готовое тесто в жгут, порезать его одинаковыми кусочками и каждый скатать в шарик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'Выложить на смазанный растительным маслом противень тестяные заготовки и убрать их на полчаса в теплое место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'По прошествии отведенного времени сделать на каждой булочке надрез в виде креста, смазать все яичным белком и посыпать кунжутными семечками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8727,'Выпекать  нежные булочки с кунжутом при 180 градусах на протяжении 1 часа, подавать со сливочным маслом (при желании).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Целые кокосы поставить на 10 минут в разогретую духовку. Вынуть, завернуть в полотенце.','https:https://st.vkuso.ru/data/cache/thumb/71/82b0b3fde441171_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Поставить в кастрюлю большого диаметра и ударить молотком так, чтобы скорлупа раскололась. Сок сцедить.','https:https://st.vkuso.ru/data/cache/thumb/0c/fa9e48c7b50590c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Мякоть вынуть с помощью ложки или ножа, измельчить блендером в стружку.','https:https://st.vkuso.ru/data/cache/thumb/45/8607c0f58fa1245_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Сливочное масло растереть с сахарным песком. В массу вводить яйца и дополнительные сырые желтки по одному.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'В конце влить кокосовое молоко и положить мякоть. Хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/eb/bbe1a4b529613eb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Смазать маслом формы для маффинов, наполнить полученной массой.','https:https://st.vkuso.ru/data/cache/thumb/11/db04a7d419bd611_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Поставить заготовки на противень, наполненный водой до краев. Печь в духовом шкафу течение получаса при температуре 180 градусов. Верх кексов должен хорошо подрумяниться.','https:https://st.vkuso.ru/data/cache/thumb/ec/b8af4e6b4ef76ec_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8728,'Достать форму, дать остыть, вынуть куиндимы.','https:https://st.vkuso.ru/data/cache/thumb/21/7909e732bc68a21_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8729,'Желатин замочить в воде на три-четыре минуты, как написано на упаковке.','https:https://st.vkuso.ru/data/cache/thumb/73/5852c22bb689273_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8729,'Довести до кипения, но не кипятить сметану в небольшом сотейнике. Снять с огня, ввести желатин, хорошо перемешать с помощью венчика, добавить сливочный сыр. Перемешать ингредиенты до однородного состояния и растворения желатина.','https:https://st.vkuso.ru/data/cache/thumb/65/9c871a3069e1d65_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8729,'Массу немного остудить, положить в неё малосольный лосось и рыбу холодного копчения. Соль – по вкусу, добавить цедру лимона, зеленый укроп. Всё хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/df/b30712bb730e0df_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8729,'Форму для выпекания застелить пищевой пленкой, переложить массу, разровнять и утрамбовать. Поставить в холод на 6 – 8 часов.','https:https://st.vkuso.ru/data/cache/thumb/11/10b38749f007311_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8729,'Вынуть мусс из формы, потянув за пленку. Нарезать на порции, украсить веточками укропа.','https:https://st.vkuso.ru/data/cache/thumb/81/b6dbae825963781_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Отварить до готовности в подсоленной воде клубни картофеля, процедить, приготовить пюре.','https:https://st.vkuso.ru/data/cache/thumb/b5/aa84eddf7554fb5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Прогреть 200 мл сливок, до кипения не доводить. Влить в картофельную массу, вбить яйцо. Все ингредиенты хорошо перемешать, масса должна стать однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Разогреть в форме или в сковороде сливочное масло, добавить лук, цедру лимона и чеснок, потомить до подрумянивания лука.','https:https://st.vkuso.ru/data/cache/thumb/ec/a22e27d2e6c86ec_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Выложить филе трески, нарезанное кусочками. Влить 100 мл сливок и снять блюдо с огня. Рыбу посолить по вкусу и посыпать рубленой зеленью петрушки.','https:https://st.vkuso.ru/data/cache/thumb/46/2bd62d2ec606f46_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Сверху выложить слой пюре так, чтобы он покрыл всю поверхность.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Отдельно перемешать тертый сыр «Пармезан» с сухарями, посыпать смесью запеканку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8730,'Поставить блюдо в духовой шкаф, печь при температуре 200 градусов, время – от 20 до 25 минут. Верх должен хорошо подрумяниться.','https:https://st.vkuso.ru/data/cache/thumb/e9/66d1990383ab5e9_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'За день до приготовления выпечки сделать настой из молока, молотой корицы, смеси «Пять специй», порошка ванили, инвертного сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Порезать лук на 4 части и кольцами.','https:https://st.vkuso.ru/data/cache/thumb/d4/f951a309f8359d4_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Все перечисленные ингредиенты сложить в сотейник, прогреть, снять с огня, накрыть крышкой и оставить на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'На следующий день взбить до состояния помадки мягкое сливочное масло и темно-коричневый сахар мусковадо, гречишный мёд, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Вбить по одному сырые куриные яйца, каждый раз хорошо перемешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'В конце подмешать цедру лимона и апельсиновые цукаты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Сверху просеять муку пшеничную и гречишную, разрыхлитель.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Добавить частями ароматизированное молоко, массу перемешивать лопаточкой вручную.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Айву очистить и нарезать кубиками, всыпать в основную массу, еще раз перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Готовое тесто выложить в одну большую или несколько маленьких форм для выпекания. Печь при температуре 180 градусов, время – от 25 до 45 минут. Время зависит от возможностей духовки и размера формы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Готовые кексы остудить на решетке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Для приготовления глазури понадобится горький шоколад, растительное масло из абрикосовых или виноградных косточек или обычное, подсолнечное.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8731,'Ингредиенты прогреть, остудить до 30 градусов и полить смесью кексы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8732,'Грибы очистить и нарезать, потушить в течение 15 минут с растительным маслом, соль – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/cd/b053c9cc62cdacd_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8732,'Влить сливки, всыпать молотый перец и орегано. Потомить от пяти до десяти минут.','https:https://st.vkuso.ru/data/cache/thumb/4b/8d35da7fbfaac4b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8732,'Отварить макароны фарфалле и натереть сыр «Пармезан».','https:https://st.vkuso.ru/data/cache/thumb/1f/db55735a39ab51f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8732,'В порционную тарелку выложить пасту, затем грибы в соусе, посыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/7e/3457873572e327e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8733,'Фасоль замочить заранее, на ночь. Перед приготовлением продукт промыть под проточной струей холодной воды.','https:https://st.vkuso.ru/data/cache/thumb/3c/8a432b365711b3c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8733,'Переложить фасоль в большую кастрюлю, залить новой порцией воды и довести до кипения на сильном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8733,'Положить в кастрюлю остальные ингредиенты: мелко нарезанные помидоры без кожицы, молотую асфетиду, морковь, корень сельдерея с листьями, томатную пасту, влить оливковое масло. Добавить сахар, черный молотый перец.','https:https://st.vkuso.ru/data/cache/thumb/46/3546b7c13047746_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8733,'Снова поставить кастрюлю на огонь, довести до кипения, огонь убавить и варить суп под крышкой в течение часа. Фасоль должна стать мягкой.','https:https://st.vkuso.ru/data/cache/thumb/26/2b2c2376eab1e26_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8733,'Посолить по вкусу, при подаче посыпать блюдо рубленой петрушкой.','https:https://st.vkuso.ru/data/cache/thumb/c4/93b658edd1397c4_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8734,'Растопить на водяной бане любой шоколад. Смазать им формочки с помощью силиконовой кисти. Поставить формы в морозильную камеру на пять или десять минут. Если получились «пробелы» –  еще раз нанести шоколад и вернуть формочки в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8734,'Творог растереть с сахарной пудрой, мягким сливочным маслом и ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8734,'Вынуть формочки, наполнить полученной массой на треть объема, положить в центр начинку: джем, карамель или кокосовую стружку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8734,'Заполнить емкости творожной смесью доверху, смазать верх шоколадом и снова убрать в холодильник. Подавать батончики холодными.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Разрезать перец на две части, убрать семена. Положить на противень, застеленный специальной бумагой, намазанной маслом, срезом вниз. Отправить на 20-25 минут в духовку, соблюдать температуру 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/60/04fb5e736beac60_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Во время готовки перцев заняться приготовлением теста. Просеять муку в широкую емкость, насыпать дрожжи, приправы, соль. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/dc/fb944d2e8c036dc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Сделать углубление, налить теплую воду, положить несколько ложек несладкого питьевого йогурта и томатного пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Замесить тесто, отправить на 30-40 минут в теплое место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Готовый перец переложить в посуду, накрыть крышкой, отставить, чтобы остыл.','https:https://st.vkuso.ru/data/cache/thumb/02/5c4c3d2d6ce3b02_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Снять кожуру, порезать мякоть на квадратики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Положить порезанные перцы в тесто. Мешать, пока перец равномерно не распределится по тесту.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Намазать форму маслом, положить тесто. Накрыть полотенцем, отправить в тепло на 30 минут.','https:https://st.vkuso.ru/data/cache/thumb/5b/82b350eec0c005b_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Намазать тесто маслом, посыпать приправами, крупной солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Отправить на 30 минут в духовку, соблюдать температуру 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Достать хлеб с запеченным болгарским перцем из формы, остудить на решетке под полотенцем.','https:https://st.vkuso.ru/data/cache/thumb/ce/6ed9251946c79ce_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8735,'Когда хлеб остынет, порезать и подавать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Промыть укроп, подсушить бумажным полотенцем. Измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Соединить сливочный сыр, укроп и молотый перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Намазать сыр на кусочки хлеба, сложить стопкой, чуть-чуть уплотнить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Разрезать заготовку на 4 части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Каждую часть разрезать поперек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Положить на заготовки по куску семги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8736,'Можно подавать полосатые бутерброды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8737,'Потереть сыр и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8737,'Положить майонез, посыпать перцем, солью. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8737,'Вырезать из ломтиков хлеба фигурные заготовки. Обжарить их на растительном масле до румяного цвета.','https:https://st.vkuso.ru/data/cache/thumb/3e/31291585936943e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8737,'Натереть со всех сторон чесноком. Намазать бутерброды-звездочки сырной массой.','https:https://st.vkuso.ru/data/cache/thumb/66/a68eaa2a9020166_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'К сливочному сыру добавить майоран, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Раскатать из сливочного сыра пласт прямоугольной формы толщиной 6-8 миллиметров между двумя плотными пленками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Убрать верхнюю пленку, распределить по сыру салями, чуть-чуть уплотнить руками.','https:https://st.vkuso.ru/data/cache/thumb/eb/1a0eabc968c9eeb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Накрыть пленкой, осторожно перевернуть заготовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Убрать верхнюю пленку, распределить по сыру чуть-чуть зелени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Осторожно плотно свернуть ролл, зафиксировать форму пленкой, скрепить шпажками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Отправить в холодильник на 4-8 часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Осторожно убрать пленку, порезать ролл из салями на порции, подавать с крекерами.','https:https://st.vkuso.ru/data/cache/thumb/e6/4f68566cd1a27e6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8738,'Можно подавать вкусные роллы к праздничному столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Положить в кипящую воду макароны, отваривать 8 минут, обсушить.','https:https://st.vkuso.ru/data/cache/thumb/f7/6e45af903e6a6f7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Сварить куриную грудку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Соединить в кастрюле соус чили, сливочное масло, уксус, вустерский соус, чеснок, кайенский перец, соль. Довести до кипения. Перемешать. Покрыть смесью кусочки мяса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Смешать в посуде молоко, кукурузный крахмал. Довести до кипения. Положить ложку сливочного масла, тертый чеддер. Перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/1f/ae789edbdc82b1f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Соединить макароны и сливочный соус.','https:https://st.vkuso.ru/data/cache/thumb/05/2aa9ecbba784505_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Осторожно перемешать курицу и макароны.','https:https://st.vkuso.ru/data/cache/thumb/df/ea9523bbd9cc6df_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8739,'Положить все по тарелкам, украсить зеленым луком и крошкой голубого сыра. Подавать макароны с куриным филе под сырным соусом сразу.','https:https://st.vkuso.ru/data/cache/thumb/21/3685505f65c4c21_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Вбить в посуду яйцо. Крупно потереть сыр. Соединить с яйцом. Налить растительное масло, воду. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a9/d41e178644714a9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Погасить соду в уксусе или лимонной кислоте. Добавить в тесто. Посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Насыпать муку, замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/6b/3debd721d42bd6b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Поделить тесто на средние куски. Получается приблизительно двадцать кусков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Взбить яйцо венчиком или вилкой, посыпав по вкусу перцем и солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Раскатать кусочки в тоненькую лепешку. Намазать взбитым яйцом. Присыпать кунжутом.','https:https://st.vkuso.ru/data/cache/thumb/bc/117726a950864bc_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Свернуть в виде трубочек.','https:https://st.vkuso.ru/data/cache/thumb/9d/5003fd6a7e45a9d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Сверху намазать трубочки яйцом, посыпать кунжутом.','https:https://st.vkuso.ru/data/cache/thumb/52/8724359cf59da52_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8740,'Выложить трубочки на противень, намазанный маслом. Готовить 20-30 минут, соблюдать температуру 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11639,'Через тридцать минут подать к столу.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Очищенный чеснок мелко порезать и смешать с солью, перцем чили и черным молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Влить в эту смесь 1 ст.л. воды и оливковое масло, хорошенько перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Каждую куриную грудку со всех сторон обвалять в получившемся маринаде и оставить мясо на 15-20 минут, чтобы оно слегка промариновалось.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Затем курицу нужно в течение 10 минут обжарить на гриле с каждой стороны, после чего нарезать желаемыми кусочками (соломкой или небольшими кубиками).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Кукурузу отварить до готовности и снять с початка, красный лук помыть, очистить и мелко порезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Помидор, болгарский красный перец, кинзу и авокадо помыть, порезать небольшими кубиками, листья салата также помыть и порвать их руками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Все подготовленные ингредиенты (кроме курицы и сыра) смешать с соком лайма, посыпать тертым сыром чеддер.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Поверх сыра распределить порезанное куриное мясо и спрыснуть его острым соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8741,'Подавать салат с помидорами, перцем и курицей-гриль порционно или в большой миске, при желании его можно украсить чипсами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Порезать баклажаны на ломтики. Чуть-чуть посыпать солью. Отставить баклажаны на 2 часа, чтобы они пустили влагу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Нагреть в кастрюле оливковое масло. Положить измельченный чеснок, осторожно готовить минуту, чтобы появился аромат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Положить порезанные на кубики помидоры. Кипятить 15 минут на маленьком огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Посыпать перцем, солью, добавить базилик.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Соединить тертый пармезан с панировочными сухарями. Положить в неглубокую посуду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'В другую посуду насыпать муку, в третью - взбитые яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Нагреть духовку до 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'На дно листов для выпечки налить по большой ложке оливкового масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Обтереть ломтики баклажанов бумажным полотенцем. Обвалять каждый ломтик баклажана в муке, потом в яйцах.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Посыпать смесью сыра с сухарями.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Положить на промасленный лист в кастрюлю. Чуть-чуть полить маслом каждый слой баклажанов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Отправить баклажаны в духовку. Готовить 20 минут, на полуготовности перевернуть, пока не станут румяными.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Достать из духовки, остудить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Положить на дно кастрюли томатный соус. 1/3 ломтиков положить на дно кастрюли, покрытой соусом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'На баклажаны положить половинки моцареллы. Посыпать тертым сыром.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Положить на баклажаны еще треть сыра. Полить ломтики соусом.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'На слой соуса положить оставшийся порезанный сыр моцарелла. Посыпать сыром пармезан.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'На сыр положить оставшиеся баклажаны, полить соусом, посыпать пармезаном.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Готовить 35 минут, соблюдать температуру 180 градусов.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8742,'Оставить баклажаны с помидорами в пармезане на 10 минут, чтобы блюдо остыло.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Порезать кабачки на кубики. Добавить измельченную петрушку и укроп. Посыпать солью, специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Соединить сметану и горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Добавить яйца, тертый сыр (5 ст.л.), посыпать солью, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Положить кабачки, смесь из сыра, сметаны, яиц в форму, равномерно распределить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Посыпать тертым сыром (4-5 ст.л.)',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8743,'Можно сделать больше одного слоя. Готовить кабачки 35-40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Сделать опары: взять широкую и глубокую емкость. В теплой воде размешать муку, сахар, насыпать дрожжи. Осторожно перемешать. Накрыть полотенцем, отправить в тепло на 15-20 минут, чтобы поднялись дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Соединить ½ муки и теплое молоко. Добавить опару. Размешать венчиком. Накрыть емкость полотенцем, отправить на 60 минут в тепло.','https:https://st.vkuso.ru/data/cache/thumb/79/374209283405f79_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Приготовить начинку: протереть творог через сито. Вбить яйца, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/68/47135eff2ac3068_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Положить ложку сливочного масла. Добавить ванильную эссенцию, сахарную пудру. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d2/c83618f0c9138d2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11675,'Мелко порубить чеснок и лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Залить изюм кипятком, отставить на 5 минут. Добавить к творогу, размешать.','https:https://st.vkuso.ru/data/cache/thumb/50/4e1912b732f6450_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'За час тесто должно подняться в несколько раз.','https:https://st.vkuso.ru/data/cache/thumb/6f/f47d3684421f86f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Просеять муку, насыпать соль. Перемешать. Добавить сливочное масло, яйцо. Замесить тесто, чтобы оно отставало от рук. Если тесто прилипает, то насыпать чуть-чуть муки. Должно получиться упругое, легкое, эластично тесто.','https:https://st.vkuso.ru/data/cache/thumb/07/bb70f366e29f107_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Разделить тесто на одинаковые части, сделать шарики. Накрыть заготовки полотенцем, отставить на 10 минут, чтобы они стали пышней.','https:https://st.vkuso.ru/data/cache/thumb/62/8da90e0af076962_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Посыпать стол мукой. Раскатать шарики в лепешки. Положить начинки. Защипнуть краешки. Сформировать шарики нужной формы.','https:https://st.vkuso.ru/data/cache/thumb/d0/b071269c5b989d0_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Разложить на противень вниз швом, застеленный бумагой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Отставить пирожки на 20 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Нагреть духовку до 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Сделать смесь из молока, сливок, взбитого яйца. Намазать пирожки. Посыпать кунжутом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8744,'Готовить дрожжевые пирожки с изюмом и творогом 15-20 минут. Остудить на решетке.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Приготовить тесто. Соединить какао, разрыхлитель, муку. Положить масло. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Взбить яйца. Положить в тесто яйца, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Намазать противень маслом или постелить бумагу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Положить тесто, равномерно распределить. Готовить 15-20 минут, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Остудить корж. Вырезать из коржа круг, как трафарет использовать посуду емкостью 1,2 литра. Отложить круг.','https:https://st.vkuso.ru/data/cache/thumb/9e/1e1ba1b5781929e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Постелить в емкость пищевую пленку. Вырезать из оставшегося коржа треугольники. Положить в емкость.','https:https://st.vkuso.ru/data/cache/thumb/4c/a89580bf96da54c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Приготовить крем: измельчить орехи, шоколад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Взбить сахарную пудру и сливки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Положить орехи, размешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Положить шоколад, размешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Добавить вишню, размешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Выложить крем в посуду с коржом. Накрыть кругом.','https:https://st.vkuso.ru/data/cache/thumb/83/f134eeaad3a8b83_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Отправить на 6-8 часов в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8745,'Перед подачей миндально-вишневый торт «Цукотто» перевернуть, украсить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Порубить смесь орехов, натереть на терке шоколад и смешать его с сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Протереть творог через сито и хорошенько растереть его с растопленным сливочным маслом до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Влить в творожную массу сметану, всыпать сахарно-шоколадную смесь и орехи, добавить цедру одного лимона и тщательно все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Застелить формочки для пасхи пищевой пленкой (края пленки должны свисать), сделать на пленке пару-тройку надрезов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Наполнить подготовленные формочки творожной массой и накрыть свисающими краями пищевой пленки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'На каждую формочку сверху положить какой-либо груз и убрать все заготовки на 6-8 часов в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'По прошествии отведенного времени на каждую чистую тарелку перевернуть формочку с пасхой вниз широкой частью, аккуратно снять формочку и пленку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8746,'Пасха с  горьким шоколадом и орехами готова.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Бланшировать брокколи, после закипания 3 минуты.','https:https://st.vkuso.ru/data/cache/thumb/1c/67ca50b060ffa1c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Предварительно подготовить воду со льдом. Достать брокколи, используя шумовку, положить на 5-10 минут в воду.','https:https://st.vkuso.ru/data/cache/thumb/a7/d9b33486cceeda7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Взбить масло миксером, насыпать сахар, взбить.','https:https://st.vkuso.ru/data/cache/thumb/1e/c9436b740a0bc1e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Добавить по одному яйцу. Взбить.','https:https://st.vkuso.ru/data/cache/thumb/64/a3e68c2151cda64_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Соединить в отдельной посуде сухие продукты.','https:https://st.vkuso.ru/data/cache/thumb/5f/ad8a8d5929eef5f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Смешать две смеси, положить мелко потертый сыр.','https:https://st.vkuso.ru/data/cache/thumb/ec/ec56927431462ec_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Намазать формы маслом.','https:https://st.vkuso.ru/data/cache/thumb/52/ba2ecf2f7340552_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11681,'Перелить в большую бутыль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Положить в них по ложке теста. Обсушить брокколи бумажным полотенцем. Положить на тесто по соцветию, подходящему по размеру, чуть-чуть вдавить.','https:https://st.vkuso.ru/data/cache/thumb/31/4e2826eda758a31_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'На соцветие положить по ложке теста. Сформировать, чтобы тесто прикрыло брокколи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Нагреть духовку до 180 градусов. Готовить 20-30 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8747,'Достать маффины из формочек.','https:https://st.vkuso.ru/data/cache/thumb/c9/6ff8de4ab0211c9_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Порезать лук, обжарить на разогретом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Сделать сухари. Порезать хлеб на кубики, отправить на 10-15 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Опустить замороженную брокколи в бульон или кипящую воду. Посолить. Варить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'В конце добавить обжаренный лук. Обычно на это уходит 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Измельчить все в блендере до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Отправить все снова в кастрюлю. Посыпать перцем, налить сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Подогреть, не доводить до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8748,'Положить в суп-пюре из брокколи со сливками сухарики и подавать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Вымыть мясо под струей воды.','https:https://st.vkuso.ru/data/cache/thumb/e9/0d9b3f6c6c0b9e9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Обсушить бумажными салфетками.','https:https://st.vkuso.ru/data/cache/thumb/ff/aa24910cc150aff_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Натереть голени солью и специями, отправить в холодильник на 20-60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Промокнуть салфеткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Раскалить оливковое масло в чугунной или керамической сковороде. Положить голени. Пожарить на большом огне с каждой стороны по 1,5-2 минуты.','https:https://st.vkuso.ru/data/cache/thumb/50/13d3a5807009f50_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Постелить пергамент на противень, установить решетку, положить мясо, чтобы куски не соприкасались.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8749,'Готовить, соблюдая температуру 190-200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Вымыть мясо под струей воды.','https:https://st.vkuso.ru/data/cache/thumb/e9/0d9b3f6c6c0b9e9_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Обсушить салфетками.','https:https://st.vkuso.ru/data/cache/thumb/b0/49d705948d153b0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Посыпать солью, отставить на пару минут.','https:https://st.vkuso.ru/data/cache/thumb/08/8cb999005daaf08_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Промокнуть салфеткой. Намазать кусочки мяса смесью лимонного сока и меда. Посыпать специями.','https:https://st.vkuso.ru/data/cache/thumb/94/9b53f4587b94a94_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Постелить на противень пергамент, положить мясо на некотором расстоянии.','https:https://st.vkuso.ru/data/cache/thumb/17/afd95183cd6e017_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8750,'Готовить, соблюдая температуру 190-200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Сделать тесто: соединить муку с кипятком, замесить эластичное тесто. Тесто получится не таким тягучим – не будет рваться, и будет удобно работать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Отставить на некоторое время, раскатать лепешки. Сделать любую начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Если есть возможность, то приобрести кунжутное масло. Оно сделает любой салат очень вкусным. А овощной начинке к пельменям придаст изюминку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Кунжутное масло можно заменить оливковым или несколькими каплями обычного.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Из лепешек, раскатанных из теста, сделать форму звезды – красиво защипнуть концы звезд, каждый лепесток подогнуть, второй конец зажать у основания. Чтобы получился цветок, соединить между собой лепесточки, прижать середину.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8751,'Отправить пельмени «Букет цветов» с любимой начинкой в пароварку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Соединить муку с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Растворить в воде сахар и дрожжи, насыпать соленую муку. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Отправить тесто в холодильник на 8-10 часов, чтобы поднялось.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Разогреть духовку до 250 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Положить тесто на стол, присыпанный мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Поделить на 4 части, сформировать овалы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'В центре распределить тертый сыр, несколько кусочков помидора, перца чили.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Края лепешки закрутить жгутиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Вбить яйцо в центре, посыпать перцем, солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8752,'Готовить пиде с яйцом, помидорами и сыром до румяной корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Налить молоко в кастрюлю, посолить, поставить на огонь, закипятить, мешать, чтобы не подгорело.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Взбить яйца, соединить со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8762,'Готовить кексики с курагой из манки и кефира 40 минут, соблюдать температуру 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Убавить огонь, налить яично-сметанную смесь в молоко, готовить 5-6 минут, непрерывно помешивая, пока сыворотка не отделится от творога.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Постелить на сито или дуршлаг сложенную в 2 слоя марлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Под сито поставить кастрюлю, налить сырную смесь, подождать, пока сыворотка стечет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Сито с сыром поставить в емкость, накрыть свисающими краями марли, положить сверху тарелку поменьше диаметром, на тарелку поставить литровую банку с водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8753,'Отставить на 4-6 часов, через 60 минут можно поставить сыр в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Растолочь печенье в крошку. Удобно использовать пакет и деревянную скалку.','https:https://st.vkuso.ru/data/cache/thumb/0a/58ad0b72e850b0a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Добавить к крошке несколько больших ложек сливочного масла, одну ложку сахара.','https:https://st.vkuso.ru/data/cache/thumb/e7/7c4f35aab3109e7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Соединить сметану, творог и сахар.','https:https://st.vkuso.ru/data/cache/thumb/52/7f00c15bbf87d52_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Отдельно взбить сливки.','https:https://st.vkuso.ru/data/cache/thumb/dc/52b125d595c43dc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Осторожно ввести в творожную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8754,'Слоями сложить в стакан печенье, крем, разрезанную пополам клубнику. Украсить чизкейк из печенья и клубники без выпечки листиками мяты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8755,'Растопить сливочное масло с шоколадом, отставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8755,'Взбить желтки, сахар, коньяк. Должна получиться густая, как крем масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8755,'Насыпать в желтки корицу и просеянный крахмал, добавить растопленный шоколад с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8755,'Взбить белки, в 3 приема добавить желтки, после каждого добавления осторожно перемешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8755,'Вылить тесто в форму, готовить в духовке 25-30 минут, соблюдать температуру 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'Селедку разделить так, чтобы получилось 2 филе, достать из каждого куска все имеющиеся кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'Тонкими пластинами нарезать помытый огурец, половину болгарского перца порезать квадратиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'Яйца и морковь отварить до полной готовности, очистить и порезать мелкими кубиками, зелень измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'В небольшую миску влить 100 мл кипятка и полностью растворить в нем 1 ст. л. желатина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'2-3 ст. л. желатиновой массы тщательно перемешать с 3-4 ст. л. майонеза, добавить подготовленное яйцо и морковь, еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'На пищевую пленку выложить первый кусочек филе сельди, распределить по нему половину морковно-яичной массы, выложить половину огуречных пластинок и столько же квадратиков перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'По перцу распределить оставшуюся морковно-яичную массу, затем оставшийся огурец и болгарский перец, накрыть «конструкцию» вторым кусочком рыбного филе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'С помощью пищевой пленки плотно свернуть заготовку в рулет или «колбаску», края пленки завязать и убрать в холодильник на всю ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8756,'За несколько минут до подачи, закуску из сельди с красным перцем достать из холодильника и снять с нее  пленку, а затем рулет нарезать на кусочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Отварить и остудить свеклу, почистить крупно потереть.','https:https://st.vkuso.ru/data/cache/thumb/f8/2332516d1dad8f8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Положить в салатницу слоем. Покрыть свеклу майонезом.','https:https://st.vkuso.ru/data/cache/thumb/ed/b954a78610127ed_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Размять грецкий орех, это будет третий слой салата.','https:https://st.vkuso.ru/data/cache/thumb/39/36487b379730839_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Мелко потереть яйца, уложить четвертый слой. Яйца не приминать, чтобы они не пропитались свеклой.','https:https://st.vkuso.ru/data/cache/thumb/a9/da435b2110e83a9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Мелко потереть сыр, выложить пятый слой.','https:https://st.vkuso.ru/data/cache/thumb/cb/d38e05ae7bc68cb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Намазать майонезом.','https:https://st.vkuso.ru/data/cache/thumb/14/5f75941b3710114_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8757,'Украсить слоеный салат из свеклы, сыра и грецких орехов на свое усмотрение. Например, можно сделать из арахиса цветочки, края посыпать измельченной зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'В теплой воде промыть клюкву, влить бренди и дать настояться в течение 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'На разделочной доске расположить мясо, не доходя до низа 5 мм сделать вдоль волокон надрез посередине.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'Мясо раздвинуть руками, внутри пласта сделать поперек глубокие надрезы слева и справа, до каждого края не доходя по 5 мм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'Как книгу раскрыть мясо, если есть утолщенные места – надрезать их, накрыть мясо пищевой пленкой, молотком отбивать до тех пор, пока толщина слоя не станет 1,5-2 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'Мясо натереть перцем, солью, посыпать тимьяном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'В грубое пюре измельчить при помощи блендера вымоченную клюкву, тонким слоем выложить ее на подготовленное мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'Свернуть все в рулет, кулинарной нитью обвязать, посолить и поперчить, спрыснуть маслом оливковым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'В заранее разогретой до 180 градусов духовке запечь мясной рулет с бренди и клюквой в районе 50-60 минут, время от времени поливая рулет выделяющимся соком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8758,'Подавать готовое блюдо можно как горячим, так и холодным.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'В миску влить холодную воду, добавить холодное сливочное масло, нарезанное на кусочки, муку, щепотку соли и яйцо, массу перемешать и замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Рабочую поверхность присыпать мукой, раскатать на ней получившееся тесто и переложить тестяную заготовку в форму диаметром 26 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'По всему тесту в форме распределить пекарскую бумагу и высыпать на нее в качестве груза бобы, горох или фасоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Поставить форму с тестом на 5-7 минут в духовку, нагретую до 200 градусов, чтобы основа подрумянилась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Далее достать форму из духовки, убрать бумагу с грузом и поставить форму обратно в духовку еще на 6 -8 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Брокколи и шампиньоны отварить в подсоленной воде 5 минут, остудить, нарезать',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Зеленый, желтый, красный  болгарские перцы  порезать кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'В большой посудине взбить яйца со  сливками, добавить сыр Гауда, подготовленный перец, брокколи, грибы и кукурузу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Тщательно все перемешать с солью и молотым перцем, распределить получившуюся начинку по испеченной тестяной основе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Присыпать сыром моцарелла, натертым на крупной терке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8759,'Поставить форму с пирогом в духовку и выпекать овощной киш с грибами в течение 15 минут до образования золотисто-коричневой корочки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Почистить лук, порезать на тоненькие полукольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Нагреть сковороду, налить 6 больших ложек соевого соуса. Когда он закипит, положить лук, посыпать сахаром. Готовить несколько минут, помешивая.','https:https://st.vkuso.ru/data/cache/thumb/4f/cd0c28587c5b34f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Порезать куриное филе на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/7f/8611703042d8c7f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Положить мясо на сковороду, перемешать с соусом. Когда курица побелеет, осторожно перевернуть и готовить еще несколько минут.  Филе готовится очень быстро, буквально за четыре минуты.','https:https://st.vkuso.ru/data/cache/thumb/d4/429808500470ad4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Отдельно взбить яйца до однородности – не солить.','https:https://st.vkuso.ru/data/cache/thumb/30/e3b0c75d4c5ba30_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Вылить яйца в сковороду, чтобы они полностью покрыли мясо. Накрыть крышкой, готовить 3-4 минуты – не перемешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Измельчить зеленый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Горочкой выложить на тарелку рис, отваренный на пару.','https:https://st.vkuso.ru/data/cache/thumb/b2/aa877c180c6bab2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'На рис осторожно положить омлет. Чтобы было удобно, разделить его на треугольные части.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8760,'Посыпать омлет «Оякодон» с рисом и куриным филе измельченным луком. Подавать горячим.','https:https://st.vkuso.ru/data/cache/thumb/61/f24d8c739dad461_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8761,'В миске круговыми движениями не спеша смешать молоко и яйца, когда масса приобретет однородный цвет добавить в нее соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8761,'Смазать формочки или одну большую форму сливочным маслом и не доверху заполнить подготовленной яично-молочной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8761,'Духовку разогреть до 200 градусов и поставить в нее заполненные емкости на 30 минут, из которых первые 15-20 минут дверцу не открывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8761,'По истечении отведенного времени нежный и пышный  омлет осторожно достать из духовки и либо подать прямо в формочках, либо аккуратно его из них извлечь и выложить на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8762,'Взбить яйцо и белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8762,'Насыпать разрыхлитель, соль. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8762,'Медленно ввести манную крупу, быстро мешая массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8762,'Заполнить формочки на 2/3, в середину положить курагу. Отправить в горячую духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Налить воду в большую кастрюлю, посолить, довести до кипения. Положить брокколи, готовить несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Достать брокколи и положить в ледяную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Остывшие соцветия подсушить, отставить в сторону на время.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Поджарить на масле морковь с луком. Отставить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Налить на сковороду ¼ стакана топленого масла, насыпать муку, несколько минут помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Смешать сливки с молоком. Аккуратно ввести сливочно-молочную смесь, потом овощной бульон, взбивая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Положить мускатный орех, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Накрыть крышкой, готовить 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Сделать огонь минимальным, положить морковь, лук, брокколи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Если масса очень густая, то добавить еще бульон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Перемешать, накрыть крышкой еще на 25-30 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Растолочь брокколи, положить ½ тертого сыра.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Посыпать крем-суп из брокколи с сыром Чеддер перцем, солью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8763,'Остальной сыр горкой уложить в каждую тарелку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8764,'Подготовить продукты, порезать филе на тоненькие пластинки.','https:https://st.vkuso.ru/data/cache/thumb/00/d0374be6d26c300_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8764,'Обжарить мясо на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8764,'Приготовить соус: взбить воду и майонез, положить прессованный чеснок. Залить курицу данной смесью.','https:https://st.vkuso.ru/data/cache/thumb/8f/2b5414240610f8f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8764,'Посыпать измельченной зеленью. Готовить куриное филе в майонезном соусе с чесноком 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/88/13987f906bd6a88_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Сделать тесто: растворить в воде сахар и соль. Просеять муку в большую посуду, положить масло, растереть руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Налить в муку воду с солью и сахаром, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Положить на поверхность стола, вымесить хорошо, если необходимо добавлять муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Должно получиться нелипкое, упругое, мягкое тесто. Обернуть полиэтиленом, отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Приготовить начинку: нагреть масло, поджарить фарш с измельченным луком на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Добавить порезанные помидоры и перец. Готовить 20 минут под крышкой на умеренном огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'В конце положить порезанные маслины, прессованный чеснок. Посыпать перцем, солью, специями. Тушить 5 минут, отставить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Достать тесто, раскатать тоненький пласт.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Используя большую кружку, вырезать кружки диаметром 10-12 сантиметров.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'На середину положить по большой ложке начинки. Защипнуть тесто с трех сторон, чтобы получился треугольник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Выложить на противень, застеленный ковриком, намазать желтком, посыпать кунжутом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8765,'Готовить 30 минут, соблюдать температуру 190 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8766,'Растворить крахмал в стакане холодного молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8766,'Молоко, которое осталось, вылить в кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8766,'Насыпать какао, корицу, сахар, ванильный сахар. Помешивая, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8766,'Тоненькой струей налить молоко с крахмалом, размешать миксером, готовить 10 минут, помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8766,'Разлить по емкостям, посыпать тертым шоколадом, сахаром. Отправить самый шоколадный пудинг на десерт на 2 часа в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Подготовить продукты. Порезать бекон на полоски, обжарить на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/9e/bf2845c7e9aca9e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Почистить картофель, отваренный в кожуре, порезать на кружки.','https:https://st.vkuso.ru/data/cache/thumb/01/26d9192e8a30001_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Порезать яблоко и огурец на кубики. Побрызгать яблоки соком лимона.','https:https://st.vkuso.ru/data/cache/thumb/93/1b56b375b78ee93_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Нашинковать лук.','https:https://st.vkuso.ru/data/cache/thumb/d4/86b1f5477c777d4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Размешать.','https:https://st.vkuso.ru/data/cache/thumb/0b/085d4e4fa0d0c0b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Приготовить соус: взбить сметану и уксус. Добавить щепотку соли, сахара, перца.','https:https://st.vkuso.ru/data/cache/thumb/8b/1ab057dd407c78b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8767,'Измельченный укроп можно положить в соус, или посыпать им шведский картофельный салат со сметанным соусом, после заправки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Достать грудки из маринада, вымыть, обсушить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11681,'Всыпать сахарный песок, поставить гидрозатвор.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'С помощью кухонного комбайна измельчить очищенный миндаль в муку, всыпать к нему сахарную пудру и перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Стручок ванили разделить вдоль, достать семена и смешать их с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Частями добавляя ванильно-сахарную смесь, взбивать белки в пену, пока консистенция белковой массы не будет похожа на консистенцию не очень сухого безе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Далее подмешать в массу миндальную смесь и быстро ее размешать, получившимся жидким тестом наполнить кондитерский мешок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Выстелить противень бумагой для выпечки, выдавить на него с помощью мешочка круглые печенья, каждое по 4 см в диаметре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Оставить заготовки на 30-40 минут, чтобы затвердели, после чего отправить противень с заготовками в разогретую до 150 градусов духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Выпекать печенье 8-10 минут, затем достать готовые изделия из духовки и оставить остывать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Смазать сторону одного печенья шоколадной пастой, сверху накрыть начинку другим печеньем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8768,'Макаруны совсем не обязательно делать с шоколадной пастой, начинка для изделий может быть совершенно любой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8769,'Подготовить продукты. Выложить грибы на дуршлаг, промыть водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8769,'Порезать говядину соломкой.','https:https://st.vkuso.ru/data/cache/thumb/61/c70749e7ee28e61_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8769,'Порезать огурцы.','https:https://st.vkuso.ru/data/cache/thumb/f4/ced340b474886f4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8769,'Смешать все с опятами. Аккуратно посыпать перцем, солью, потому что, как правило, все ингредиенты уже соленые.','https:https://st.vkuso.ru/data/cache/thumb/07/6d98985e8b28107_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8769,'Добавить измельченный лук. Заправить салат «Вечерний Владивосток» с постной говядиной майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Подготовить продукты. Установить противень наверху духовки, нагреть до 260 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Подготовить яблоки: помыть, срезать кожуру, вырезать сердцевину. Разрезать яблоко на две части, порезать на тоненькие ломтики.','https:https://st.vkuso.ru/data/cache/thumb/48/45ba92f1b702f48_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Соединить в емкости муку, соль и гранулированный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'В другой емкости соединить яйца, жирные сливки, молоко, сок лайма и ванильную эссенцию. Перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/1a/228aee8cfe8f01a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Добавить в муку жидкие продукты. Перемешивать венчиком 20-30 секунд. Убрать в сторону.','https:https://st.vkuso.ru/data/cache/thumb/b8/3cb29a3f4f2d7b8_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Нагреть сковороду, растопить сливочное масло. Выложить яблоки, корицу, коричневый сахар.','https:https://st.vkuso.ru/data/cache/thumb/98/03dcd26835cb298_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Жарить приблизительно 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/b6/86d3c7daafb8eb6_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Быстро залить яблоки яично-молочной смесью, отправить сковороду в духовку. Убавить огонь до 225 градусов. Печь 18 минут.','https:https://st.vkuso.ru/data/cache/thumb/44/8b716427c494d44_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Вытащить яблочный немецкий панкейк с корицей, чтобы отделить от сковороды, использовать лопатку.','https:https://st.vkuso.ru/data/cache/thumb/97/472314918a2ac97_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8770,'Перевернуть панкейк вверх дном на тарелку, посыпать сахарной пудрой, порезать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Отделить сырую скумбрию от косточек, порезать на кубики.','https:https://st.vkuso.ru/data/cache/thumb/86/e1cd48238778286_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Довести до кипения воду, положить лапшу, кусочек имбиря, готовить по инструкции.','https:https://st.vkuso.ru/data/cache/thumb/e9/e389be2156ee4e9_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Обжарить лук.','https:https://st.vkuso.ru/data/cache/thumb/e4/b880bd632e32ee4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Положить скумбрию, обжарить до готовности. Добавить соевый соус и специи.','https:https://st.vkuso.ru/data/cache/thumb/76/0bbd4a2d418ea76_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Положить оливки и помидоры, потушить.','https:https://st.vkuso.ru/data/cache/thumb/aa/9957ba3bb6a63aa_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8771,'Выложить рагу на готовую лапшу. Перемешать рисовую лапшу по-китайски со скумбрией.','https:https://st.vkuso.ru/data/cache/thumb/b1/80d0af2f69ecbb1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Сделать маринад: добавить в воду лавровый лист, сахар, гвоздику, соль, перец горошком и душистый.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Довести до кипения, охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Разрезать куриную грудку вдоль, до конца не дорезать. Раскрыть, как книжку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Положить одну грудку в маринад, завернуть в пленку, отправить в холодильник. Вторую грудку положить в подсоленное молоко, отправить в холодильник на ночь.','https:https://st.vkuso.ru/data/cache/thumb/57/458b02eb49f6b57_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Скрутить грудку и плотно связать шпагатом, мариновать 2-3 часа.','https:https://st.vkuso.ru/data/cache/thumb/c2/0e336fa82c8cac2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Налить воду в мультиварку, поставить емкость пароварки, положить рулеты, накрыть крышкой. Готовить 30 минут на режиме «На пару», спустя 15 минут перевернуть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Если грудка маленькая, то достаточно 7-10 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Убрать емкость пароварки, слить воду, намазать чашу растительным маслом, поставить режим «На пару», поджарить грудку, чтобы пастрома стала красивой на вид.','https:https://st.vkuso.ru/data/cache/thumb/57/d276b9a2cc32b57_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Положить пастрому на фольгу, завернуть, остудить, отправить в холодильник.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Подсушить веточку розмарин в духовке, чтобы легко было ее поджечь.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Положить пастрому на блюдо, осторожно зажечь розмарин, когда прогорит, положить на пастрому, плотно закрыть сверху. Дым придаст блюду запах костра.','https:https://st.vkuso.ru/data/cache/thumb/2e/47322ff6695822e_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8772,'Получается вкусная куриная пастрома с чесноком на пару, подкопченная розмарином.','https:https://st.vkuso.ru/data/cache/thumb/c6/574cdc1f58f49c6_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Разобрать цветную капусту на соцветия. Варить 5-7 минут в подсоленной кипящей воде, крышкой не накрывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Достать капусту шумовкой. Воду, в которой она варилась, не сливать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'На сухой сковороде обжарить муку, убрать с плиты. Соединить сливки и капустный отвар (220-250 мл), вылить тоненькой струей в муку, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Если соус не загустел, то поставить на тихий огонь и, помешивая, довести до густого состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Добавить мускат, паприку, перец, соль, размешать. Переложить соус в посуду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Намазать форму сливочным маслом, посыпать сухариками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Чуть-чуть взбить яйца, ввести в остывший соус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Положить ½ капусты, полить ½ соуса, посыпать сухарями, ½ сыра. Таким же образом выложить остальные продукты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8773,'Готовить 20 минут, соблюдать температуру 180 градусов. 5 минут выпекать запеченную цветную капусту под сливочным соусом с сыром под грилем, соблюдать температуру 200 градусов. Готовое блюдо посыпать петрушкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Клубни картофеля очистить, нарезать кубиками средней величины, залить их водой. Варить после закипания в течение пяти-семи минут.','https:https://st.vkuso.ru/data/cache/thumb/8c/ca1201949da478c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Для приготовления обжарки нарезать репчатый лук и шампиньоны, натереть морковь.','https:https://st.vkuso.ru/data/cache/thumb/c8/94d97efabedb1c8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Влить немного растительного масла, грибы и овощи жарить три минуты, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/53/3da67da5ec56c53_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Смесь добавить в суп, варить все вместе до десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Плавленый сыр нарезать кусочками, добавить в кастрюлю вместе со сливками или молоком. Дать закипеть, снять с огня.','https:https://st.vkuso.ru/data/cache/thumb/22/e52f6718599ae22_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8774,'Порубить зеленый укроп, положить в суп, накрыть крышкой на десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'Из свиного или говяжьего мяса приготовить фарш или приобрести готовый в магазине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'Добавить нарезанную кинзу и репчатый лук, соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'В ступке растолочь сушеные томаты, кориандр и зиру.','https:https://st.vkuso.ru/data/cache/thumb/66/1f064e227251766_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'Смесь добавить в фарш и хорошо перемешать. Можно использовать свежие томаты, в таком случае их нужно ошпарить, снять кожицу и удалить семенные камеры, а мякоть натереть.','https:https://st.vkuso.ru/data/cache/thumb/57/646c2ff95736457_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'Из готового слоеного теста вырезать с помощью чашки круглые заготовки.','https:https://st.vkuso.ru/data/cache/thumb/3c/2ed316c48f1cb3c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'В центре лепешек тесто примять, смазать поверхность томатным соусом, выложить начинку, края должны остаться свободными.','https:https://st.vkuso.ru/data/cache/thumb/b8/0aa190a3a83ddb8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'Печь изделия до готовности, в течение 20 – 25 минут, до получения румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'За пять минут до окончания тепловой обработки включить режим гриля.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8775,'При подаче украсить пирожки сметаной и листочками кинзы, можно сбрызнуть лимонным соком и присыпать горячую выпечку сухой молотой паприкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Соединить лук и скумбрию, посолить, поперчить, посахарить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'Ветчину «Прошутто» нарезать полосками шириной в два-три сантиметра. Шпинат промыть, крупно нарезать или порвать листочки руками, мелко порубить чеснок.','https:https://st.vkuso.ru/data/cache/thumb/c8/91120ea343d60c8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'Для соуса разбить яйцо, отделить белок от желтка. Желтки соединить с мелко натертым сыром «Пармезан» и рикоттой. Массу перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b8/5e51448ef84edb8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'Спагетти отварить в подсоленной воде, на это потребуется семь минут. Воду слить через дуршлаг, макаронные изделия вернуть в кастрюлю. На горячие спагетти вылить сырный соус и быстро перемешать. Нужно уловить момент, когда желток свернется на горячих макаронах – это признак готовности блюда.','https:https://st.vkuso.ru/data/cache/thumb/65/5f7fe4951590f65_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'Оливковое масло разогреть на сковороде, обжарить на нем ветчину с каждой стороны по полминуты, огонь – средний.','https:https://st.vkuso.ru/data/cache/thumb/98/66c2c36088b2998_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'Переложить обжарку к макаронам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8776,'В течение трех-пяти минут, до мягкости, прогреть шпинат и чеснок, также переложить к спагетти и перемешать. Приправить готовую пасту свежим молотым черным перцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Лук-порей нарезать полукольцами, сельдерей и морковь – тонкой соломкой, клубни картофеля очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'В кастрюле с толстым дном растопить сливочное масло. Овощи обжарить до мягкости на огне средней мощности в течение десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Добавить курицу, подрумянить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'В кастрюлю влить заранее сваренный куриный бульон, положить картофель, черный перец-горошек и лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Суп довести до кипения, томить на тихом огне в течение получаса. Курица должна стать мягкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Вынуть тушку из кастрюли и отделить мясо от костей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Отдельно взбить сырой желток со сливками, добавить горячий бульон, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8777,'Смесь влить в суп, быстро взболтать, поперчить и посолить. Куриное мясо вернуть в суп, прогреть, до кипения не доводить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8778,'Приготовить из горчицы, соевого соуса, меда, уксуса, соли и перца глазурь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8778,'Включить на разогрев до 180 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8778,'Подготовленный кусок свиной вырезки переложить в огнеупорную форму, облить равномерно глазурью и отправить запекаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8778,'Свинина в глазури из меда, горчицы и соевого соуса будет готова примерно через час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8778,'Готовое мясо вынуть из духовки и перед подачей к столу дать постоять 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Для приготовления теста перемешать пшеничную муку, несоленое сливочное масло комнатной температуры, соль и воду. Масса должна быть липкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Тесто выложить в форму для выпекания, края пласта должны образовать бортики. Чтобы массе легче было придать готовую форму, её лучше подержать полчаса в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Тесто наколоть вилкой в нескольких местах. Корж выпекать в духовом шкафу при температуре 200 градусов в течение 10 – 12 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Для приготовления начинки хорошо взбить жирные сливки с яйцами, добавить накрошенный сыр «Фета».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Репчатый лук измельчить и обжарить на оливковом масле в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Добавить шампиньоны, жарить еще пять-семь минут, добавить перец и другие специи по желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Начинку выложить на корж, залить яичной смесью, покрошить остатки сыра, посыпать зеленым луком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8779,'Пирог поставить в духовой шкаф на 20 минут. Когда время закончится – подержать выпечку еще пять минут в выключенной духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Тушку вымыть, обсушить с помощью бумажных полотенец, разделить на части, грудки аккуратно вырезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Все части натереть солью, сушеным майораном и перцем, оставить на десять минут для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Красный репчатый лук очистить и разрезать на четыре части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Куриный или утиный бульон довести до кипения. В сковороду с толстым дном выложить кусочки утки, кожа должна быть внизу, поставить на огонь средней мощности. Когда вытопится часть жира – огонь увеличить, подрумянить куски утки со всех сторон, переложить их в котелок с толстыми стенками или в кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11681,'Время брожения – полторы недели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'В той же сковороде обжарить нарезанный четвертинками лук до румяной корочки. Влить красное сухое вино, всыпать сахарный песок, помешивать. Довести смесь до кипения и перелить её вместе с луком к мясу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Добавить замороженные вишни и горячий бульон, соль, накрыть кушанье крышкой и довести до кипения на огне средней мощности. Огонь уменьшить до минимальной величины, тушить два или два с половиной часа, это зависит от величины утки и возможности духовки, до того момента, когда мясо начнет отходить от костей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Блюдо снять с огня и дать постоять. Заранее разогреть духовку до 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Выложить утиные грудки на сковороду с толстым дном кожей вниз, поставить на средний огонь. Когда кусочки подрумянятся – перевернуть их на другую сторону, жарить еще две-три минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8780,'Переложить в огнеупорное блюдо кожей вверх и поставить еще на десять минут в духовку. Готовое мясо вынуть, подержать при комнатной температуре пять-десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Приготовить сироп. В кастрюлю небольшого размера положить сливочное масло, всыпать сахар. Массу растопить, перемешать до однородного состояния, она должна быть похожа на ириску. Влить горячее молоко, небольшими порциями, перемешивать. Снять с плиты и продолжать мешать до остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Для приготовления теста соединить пшеничную муку, нарезанное кубиками сливочное масло, положить всё в кухонный комбайн, добавить сироп и сырой куриный желток. Замесить тесто. Если масса получилась пластичной – в нее ничего добавлять не надо, если крошится – добавить для связки сырой куриный белок и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Тесто тонко раскатать, вырезать звездочки. В половине фигурок сделать отверстия круглой формы.','https:https://st.vkuso.ru/data/cache/thumb/9f/5535e2515c6fe9f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Противень застелить бумагой для выпекания.  Печь то и другое при температуре 200 градусов в течение десяти минут.','https:https://st.vkuso.ru/data/cache/thumb/c3/d17b019eaecd6c3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Заготовки для печенья охладить, намазать звездочки густым джемом из апельсина, а заготовки с отверстиями покрыть полосками глазури, приготовленной из сахарной пудры и ликера, прогретой до кипения.','https:https://st.vkuso.ru/data/cache/thumb/6f/1440dcfe3e90b6f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8781,'Когда горячая глазурь на печенье застынет – положить звездочки с отверстиями на звездочки с джемом. Перед подачей на стол печенье должно полежать в течение часа или двух.','https:https://st.vkuso.ru/data/cache/thumb/cf/c44d7c2e70921cf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8782,'Перемешать кефир, майонез, сметану. Лучше использовать продукты средней жирности, они гуще по консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8782,'Добавить карри, хмели-сунели, сладкую молотую паприку, пропущенный через пресс чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8782,'Ингредиенты перемешать, оставить на два-три часа, чтобы специи набухли и разошлись.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Салатные листья вымыть и обсушить, порвать руками. Выложить зелень в глубокую миску.','https:https://st.vkuso.ru/data/cache/thumb/ae/d023cf1b79135ae_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Нарезать кубиками свежие помидоры и огурцы, перемешать с салатом.','https:https://st.vkuso.ru/data/cache/thumb/62/5e33bcc68261862_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Для приготовления заливки соединить соевый соус, мёд, оливковое масло и дижонскую горчицу. Посолить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/e7/9733f5b38d227e7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/be/36139427ac02bbe_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Филе семги нарезать небольшими квадратиками.','https:https://st.vkuso.ru/data/cache/thumb/49/916538fe8895249_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Обжарить рыбу на оливковом масле до золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/4d/20d1d7ec540734d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8783,'Теплые кусочки выложить на салат и заправить медовым соусом, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/b8/b1db9cced5661b8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'Порезать промытое мясо (говядину, баранину, конину) соломкой и сложить его в казан с разогретым растительным маслом, немного обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'Тонкими полукольцами нарезать лук, добавить его к мясу и обжаривать, пока лук не станет мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'На крупной терке натереть огурцы, добавить их вместе с томатной пастой и небольшим количеством воды (бульона) в казан с мясом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'Накрыть казан крышкой и тушить его содержимое до готовности мяса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8794,'Яблоки средней величины очистить от кожуры и семян, нарезать ломтиками, потушить со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'Очищенный картофель порезать соломкой и обжарить в отдельной сковородке, за несколько минут до готовности переложить его в казан с мясом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8784,'Добавить к мясу  молотый перец, соль, измельченный чеснок и лавровый лист,аккуратно перемешать и тушить сытное азу по-татарски до полной готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8785,'Сырые куриные яйца взбить в пену с помощью миксера. Влить воду и взбить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8785,'Посолить, добавить пищевую соду, сахарозаменитель, ржаную муку, молотые льняные семечки и снова взбить. Масса должна быть средней густоты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8785,'Ложку смеси налить в вафельницу, закрыть, печь две минуты, до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8786,'Обезжиренный творог смешать с оливковым маслом, протеином со вкусом шоколада, молотыми миндальными орехами. Ваниль и молотая корица – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8786,'Из полученной массы мокрыми руками слепить батончики и положить в морозильную камеру на час или два.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8787,'Перемешать яичный белок с клетчаткой и кардамоном, кориандром и цедрой лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8787,'На фольгу выложить кусочки куриного филе, сформовать «лодочку», залить полученной смесью, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8787,'Печь в течение получаса при температуре 250 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8788,'Нарезать куриное филе кусочками средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8788,'Смешать рисовый уксус и соевый соус, замариновать курицу в этой смеси на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8788,'Обжарить филе в кунжутном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8788,'Огонь убавить, добавить стручковую фасоль, очищенные кедровые орешки, кунжутное семя, тушить в течение 15 минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8789,'Приготовить из раздавленного прессом чеснока, семян кунжута, имбиря, рубленого лука,  соевого соуса, растительного масла и сахара маринад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8789,'Переложить свиную вырезку в форму, равномерно полить маринадом и поставить минимум на 3 часа в холодное место. За это время кусок надо несколько раз перевернуть, чтобы мясо как следует промариновалось. Минут за 20-30 до окончания маринования включить на разогрев до 190 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8789,'Слить маринад, мясо положить в огнеупорную форму и запечь.  Свинина в маринаде из соевого соуса, имбиря и кунжута будет готова примерно через 50 минут. Дать мясу чуть остыть и разрезать на пластины толщиной по 4-5 сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8789,'Прокипятить  маринад из соевого соуса, имбиря и кунжута в течение 5 минут и перед подачей полить нарезанное мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8790,'Перемешать овсяную муку, сывороточный протеин, молотую корицу и мускатный орех, кусочки темного, горького, шоколада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8790,'Добавить пекарский порошок, пищевую соду, сахарозаменитель, мёд, сырые куриные яйца, размятые бананы, ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8790,'Смесь продуктов переложить в кастрюлю, смазанную кокосовым маслом. Печь при температуре 150 градусов в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8791,'Куриную грудку измельчить в мясорубке или в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8791,'Добавить мягкий творог, сырые куриные белки, соль, перец, чеснок, любые приправы. Массу хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8791,'Сформовать сардельки, закатать их в пищевую пленку. Варить в пароварке в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8792,'Филе куриной грудки нарезать в виде «книжки», до конца не дорезать один сантиметр. Мясо развернуть, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8792,'В центр положить кружок апельсина без кожуры, завернуть «конвертом».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8792,'Отдельно смешать ржаную цельнозерновую муку, перец, соль, сухой розмарин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8792,'«Конверт» обвалять в сухой смеси, печь в духовом шкафу при температуре 180 градусов в течение 15 – 20 минут или жарить на сильном огне по 5-7 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8793,'Репчатый лук нарезать, обжарить на оливковом масле до золотистого цвета. Пропустить через пресс очищенный чеснок. Добавить молотую корицу, свежий лимонный сок, потушить еще минуту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8793,'Влить нежирное или обезжиренное молоко, положить разобранную капусту брокколи. Довести смесь до кипения, огонь убавить. Тушить до полной готовности, в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8793,'Готовую смесь измельчить с помощью блендера. Куриное филе нарезать, обжарить на оливковом масле до образования корочки. Соединить курицу с пюре из брокколи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11700,'Развести желатин в горячей воде, дать набухнуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8794,'В емкость положить пшеничную муку, ванилин, соль, вбить сырые куриные яйца, перемешать. Влить молоко, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8794,'В сковороде или в форме для выпекания растворить сливочное масло, вылить часть готовой смеси, положить яблоки, залить остатками. Печь в духовом шкафу при средней температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8795,'Овсяные хлопья крупного помола залить горячей водой, дать набухнуть, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8795,'Натереть  очищенные от кожуры и семян яблоки и грушу, в равных пропорциях. Добавить нежирный творог, чернику. Все ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8795,'Массу переложить в форму для выпекания, сверху посыпать молотой корицей и ванильным сахаром. Печь блюдо в течение 25 – 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8796,'Подготовить яблоки, очистить, удалить семена, порезать на кусочки, сложить в кастрюльку, всыпать ягоды, влить половину стакана воды, добавить мед (3 ст.л.), проварить, помешивая до сгущения начинки.','https:https://st.vkuso.ru/data/cache/thumb/91/222a1e77a677791_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8796,'Натереть черствый хлеб на терке, слегка подсушить его на сковороде, добавить растопленное масло, корицу и мед, перемешать, прогреть 3 минуты до получения влажной маслянистой крошки, снять с плиты, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/3e/78ef8604a3a3a3e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8796,'Подготовить форму, заполнить на 2/3 крошкой, ложкой сформовать бортики, положить остывшую начинку, разровнять, покрыть оставшейся крошкой.','https:https://st.vkuso.ru/data/cache/thumb/b7/c81472eddabc7b7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8796,'Выпекать бруснично-яблочный пирог с корицей примерно полчаса в духовке при температуре 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Взбить сахар и мягкое масло, вбить яйца, перемешать, влить лимонный сок, добавить цедру.','https:https://st.vkuso.ru/data/cache/thumb/4f/396617b4586c24f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Постепенно всыпать просеянную муку, перемешать до образования теста. Включить для прогрева до 180 градусов духовку.','https:https://st.vkuso.ru/data/cache/thumb/56/d7176fd2a92b856_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Подготовить формы, промазать маслом, притрусить мукой, наполнить на 2/3 тестом. Выпекать 25 минут, проверить готовность можно деревянной зубочисткой.','https:https://st.vkuso.ru/data/cache/thumb/d8/567991a5feab2d8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Для приготовления лимонного курда нагреть сок с сахаром, размешать, вбить по одному яйца, перемешать, добавить муку, тщательно все перемешать, добавить масло, перемешать, убрать курд с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Приготовить меренгу из взбитых с сахарной пудры белков до состояния устойчивых пиков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'В остывших кексах срезать верхушку, удалить часть середины, наполнить курдом, накрыть срезанной частью.','https:https://st.vkuso.ru/data/cache/thumb/2d/3af01691e0c3d2d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8797,'Верх лимонных капкеков с начинкой оформить меренгой. Поставить десерт на минуту в прогретую до 200 градусов духовку для зарумянивания меренги.','https:https://st.vkuso.ru/data/cache/thumb/fa/76b14931ba6cdfa_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8798,'Приготовить из смеси  растительного масла, тмина, горчицы, раздавленного чеснока, соли и перца маринад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8798,'Дать полежать свиной лопатке в маринаде полчаса, нашинковать кольцами лук. Разогреть до 180 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8798,'Переложить лук на противень, залить пивом, а сверху уложить мясо (жирной стороной вниз) и укрыть сверху слоем фольги. Запекать лопатку час, а потом перевернуть кусок и продолжить запекание еще  2,5 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8798,'Переложить мясо на блюдо, дать постоять 20 минут и нарезать на порционные ломти, сок с жиром от запекания слить в сковороду. Дать жидкости закипеть, добавить сливочное масло, растопить, влить крахмал, разведенный в паре ложек воды, снизить до минимума нагрев. Помешивая, проварить соус до загустения примерно 5-8 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8798,'Свиная лопатка, запеченная  с пивом, политая соусом, подается к столу горячей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Почистить и хорошо вымыть рыбу, уложить на лист фольги (рулон не отрывать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Вымыть и порезать лимон на полукольца, вымыть и нашинковать зелень, можно добавить тимьян, розмарин и тимьян.','https:https://st.vkuso.ru/data/cache/thumb/49/4344f974b625849_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Раскрыть брюшко семги, натереть лимонным перцем и солью с прованскими травами.','https:https://st.vkuso.ru/data/cache/thumb/39/8dc11c83aecc639_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Заполнить дольками лимона и зеленью.','https:https://st.vkuso.ru/data/cache/thumb/eb/6deb1c5f06f90eb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Смазать формочки для маффинов маслом.','https:https://st.vkuso.ru/data/cache/thumb/b7/019de00070f12b7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Влить в брюшко пару столовых ложек соевого соуса, посолить верх и низ тушки.','https:https://st.vkuso.ru/data/cache/thumb/b9/fa6552f5a1223b9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Прикрыть фольгой, завернуть края, чтобы получился пакет, дать постоять около часа.','https:https://st.vkuso.ru/data/cache/thumb/59/aa528db860ad159_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Переложить форель на противень, поставить на 20-30 (зависит от размера тушки) минут в уже прогретую до 180 градусов духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8799,'Достать рыбу, осторожно удалить фольгу, «выпотрошить», отделить филе и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8800,'Порезать разные сорта сыра на тонкие ломтики, разложить их на половину кусочков хлеба, прикрыть другими кусочками, смазать тосты с обеих сторон маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8800,'Разогреть сковороду, разложить тосты, между ними расположить веточки тимьяна, обжаривать 2-3 минуты, перевернуть кусочки, придавить крышкой, меньшей по диаметру, чем сковорода, жарить еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8801,'Присыпать стол мукой, раскатать пласт готового слоеного теста, нарезать его длинными треугольниками.','https:https://st.vkuso.ru/data/cache/thumb/47/5fe8b7ff8665547_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8801,'На широкую сторону положить по кусочку шоколада, свернуть, начиная с этой стороны в трубочку.','https:https://st.vkuso.ru/data/cache/thumb/ac/d618f8bdfbb25ac_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8801,'Смазать круассаны взбитым яйцом, разложить на противне, выстланном пергаментом, поместить в прогретую до 220 градусов духовку на 15-30 минут.','https:https://st.vkuso.ru/data/cache/thumb/d1/1deb8af4a935ad1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8801,'Посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8802,'Прогреть в сковороде растительное масло, обжарить панир (можно заменить мягким сыром «Калининградский») до золотистой корочки, переложить его в тарелку.','https:https://st.vkuso.ru/data/cache/thumb/f2/d1cfa4a9ebb81f2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8802,'Обжарить (10 секунд) в оставшемся масле кориандр и пажитник.','https:https://st.vkuso.ru/data/cache/thumb/06/297e26615dfb006_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8802,'Добавить к специям нашинкованную капусту и нарезанный картофель, подсолить, перемешать, жарить под крышкой четверть часа.','https:https://st.vkuso.ru/data/cache/thumb/d0/67bc02a50b559d0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8802,'Добавить панир, тушить сабджи с капустой, картофелем и паниром до готовности еще пару-тройку минут.','https:https://st.vkuso.ru/data/cache/thumb/75/756ac69e867e275_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8803,'Перемешать масло, йогурт без добавок, орегано, раздавленный прессом чеснок, молотый черный перец и соль, добавить мелко натертую цедру лимона.','https:https://st.vkuso.ru/data/cache/thumb/ca/d95cd61d33c7cca_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8803,'Влить пару ложек лимонного сока, добавить порубленную зелень петрушки.','https:https://st.vkuso.ru/data/cache/thumb/03/e5a6860657f0703_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8803,'Положить курятину в пакет, залить этим маринадом, завязать, аккуратно слегка помять для перемешивания, положить на полчаса в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/67/a1da6aebb0a3467_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8803,'Курицу по-гречески под йогуртом обжарить на гриле (сковороде), а можно запечь 45-60 минут в духовке, разогретой до 190 градусов, поместив мясо в глубокую форму.','https:https://st.vkuso.ru/data/cache/thumb/ea/9175ab1837403ea_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8804,'Втереть в подготовленное филе говядины крупную морскую соль, дать чуть постоять пока разогревается в сковороде подсолнечное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8804,'Обжарить мясо, периодически поворачивая для равномерного зарумянивания и дать ему чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8804,'Смазать филе готовым печеночным паштетом и обложить со всех сторон тонко нарезанными пластинками грибов. Включить духовку на разогрев до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8804,'Расправить пласт слоеного теста, положить на него  кусок мяса, аккуратно защипать тесто вокруг филе и обмазать его взбитым яичным желтком и отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8804,'Говядина в слоеном тесте с грибами и паштетом  будет готова через 50-60 минут. Подавать блюдо к столу можно и в горячем и в холодном виде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Отварить макароны почти до готовности.','https:https://st.vkuso.ru/data/cache/thumb/d1/82725fc611094d1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Обжарить бекон, чтобы он оставался мягким, переложить на многослойное бумажное полотенце для подсыхания, порезать.','https:https://st.vkuso.ru/data/cache/thumb/49/c64ac2e6bf89949_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Включить для прогрева до 210 градусов духовку. Грибы нарезать, разложить на противне, присыпать перцем и солью, сбрызнуть маслом, размешать осторожно руками, поместить в уже нагретую духовку, готовить треть часа.','https:https://st.vkuso.ru/data/cache/thumb/a2/44719874da926a2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Промыть гречку, подсушить ее на сковороде, намазанной маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Растопить столовую ложку масла, спассеровать лук при слабом нагреве, чтобы он стал коричневато-золотистого цвета (минут 10).','https:https://st.vkuso.ru/data/cache/thumb/d5/7866a62533efcd5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Измельчить сыры: твердые – натереть, мягкие – покрошить.','https:https://st.vkuso.ru/data/cache/thumb/d5/529dafce4efb5d5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'В сотейнике с толстым дном растопить масло, всыпать муку, перемешать, влить молоко, проварить, помешивая 5 минут до сгущения соуса, добавить сметану, подсолить, поперчить, размешать, прогреть, но кипеть не давать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Взбить яйца, влить, продолжая взбивать, четверть стакана еще горячего соуса, хорошо размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Полученную смесь вылить в оставшийся в сотейнике соус, перемешать до однородности, всыпать сыры, размешать еще раз до их полного расплавления.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Смешать соус с макаронами, довести макароны с сыром, грибами и беконом до готовности в духовке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Для этого половину лука поместить на смазанный маслом противень, затем выложить на него половину макарон и половину грибов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8805,'Прикрыть все половиной голубого сыра с беконом, далее повторить все слои, верхним должен быть беконовый слой, поставить блюдо на 20 минут в духовку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Мясо порезать на пластинки, на такие же – сладкий перец.','https:https://st.vkuso.ru/data/cache/thumb/f5/17573a302c7d4f5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Нашинковать лук.','https:https://st.vkuso.ru/data/cache/thumb/7c/89ccfd8bef53b7c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Порубить чеснок.','https:https://st.vkuso.ru/data/cache/thumb/56/e34813c3de10a56_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Перья лука порезать на кусочки по 3 см.','https:https://st.vkuso.ru/data/cache/thumb/bc/750110e132a63bc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Смешать все соусы с добавлением сахара.','https:https://st.vkuso.ru/data/cache/thumb/6e/dbe2e2b94e1796e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Разогреть ложку масла в сковороде, обжарить кешью на среднем огне до золотистости, переложить на салфетку.','https:https://st.vkuso.ru/data/cache/thumb/f5/af2312b2d0c1df5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'В оставшемся масле обжарить пару минут перчики чили, переложить их на салфетку.','https:https://st.vkuso.ru/data/cache/thumb/fd/ac180beaaef70fd_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'После этого обжарить около минуты чеснок, сделать нагрев сильнее, положить курицу и репчатый лук, обжарить до побеления мяса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Влить в сковороду пару столовых ложек воды и перемешанный заранее соус, все хорошо перемешать еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8806,'Положить в сковороду сладкий перец, обжарить минуту, добавить орехи и перья зеленого лука, перемешать Гай Пад Мед с кешью, прогреть около минуты и снять с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8807,'Взбить мелкий сахар с яйцами, всыпать муку и разрыхлитель, добавить масло и какао, тесто тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8807,'Заполнить тестом смазанную маслом форму, отправить на полчаса в духовку с температурой 160 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8807,'Остывший корж для торта «Несквик» со сметанным кремом разрезать на 3 части, одну оставить целой, остальные порезать на небольшие кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8807,'Взбить сгущенку со сметаной и парой ложек какао, перемешать с кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8807,'На целый корж выложить полученную смесь, присыпать измельченными орехами, на ночь убрать торт в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Порубить чеснок, нашинковать лук, обжарить на масле до прозрачности.','https:https://st.vkuso.ru/data/cache/thumb/24/3914e10e8eddc24_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Всыпать муку, хорошо перемешать до исчезновения комочков, прогреть пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Добавить в соус молоко, майоран, мускатный орех, соль, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/1c/b00d3c204bd0c1c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Под крышкой довести до густого состояния.','https:https://st.vkuso.ru/data/cache/thumb/32/e6955cbb2c7de32_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Порезать мясо на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/d7/229e2380d04d0d7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Разложить по кокотницам.','https:https://st.vkuso.ru/data/cache/thumb/9d/0355643e8dd079d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Положить сверху шпинат.','https:https://st.vkuso.ru/data/cache/thumb/7b/14f58b2d85ce87b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Полить соусом.','https:https://st.vkuso.ru/data/cache/thumb/41/eb0ade936a8f741_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8808,'Запечь курицу с копчёным мясом под соусом бешамель до зарумянивания в режиме «гриль».','https:https://st.vkuso.ru/data/cache/thumb/bf/686b7821a39afbf_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Обрезать с кусочков хлеба корки.','https:https://st.vkuso.ru/data/cache/thumb/50/5e59264890adb50_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Вырезать формочкой круглые донышки для корзиночек.','https:https://st.vkuso.ru/data/cache/thumb/a5/63601e4d98804a5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Уложить на дно кружочки хлеба. Для формования стенок кусочек хлеба разделить пополам, у одной вырезать треть, другую оставить целой.','https:https://st.vkuso.ru/data/cache/thumb/43/654ed2dfd47eb43_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Уложить вокруг донышка.','https:https://st.vkuso.ru/data/cache/thumb/7e/a12e671599b677e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Смазать растопленным маслом, присыпать сырной стружкой.','https:https://st.vkuso.ru/data/cache/thumb/ee/3f46675701d77ee_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Положить бекон.','https:https://st.vkuso.ru/data/cache/thumb/76/d3a5156ff076f76_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Добавить яйцо, подсолить, обсыпать травками.','https:https://st.vkuso.ru/data/cache/thumb/88/c80466b8c8dea88_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8809,'Выпекать 20 минут при температуре 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/22/62b3083a2391722_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8810,'Налить в маленькую кастрюльку сок, ром, добавить имбирь, корицу, довести на слабом огне почти до кипения (не кипятить!), нагревать 5 минут постоянно помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8810,'Перелить ромовый пунш с корицей в графин, добавить лимон, подать пунш в высоких бокалах с соломинкой и украсив край бокала тонким ломтиком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Включить для разогрева до 150 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Взбить белки до состояния крепкой пены.','https:https://st.vkuso.ru/data/cache/thumb/68/aad98c40f8f5e68_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Желтки – с сахаром, добавить частями муку, хорошо вымешать, подсолить.','https:https://st.vkuso.ru/data/cache/thumb/15/af75de204cf8915_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Ввести аккуратно в полученную массу белки и желтки, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/41/ffcef9216806941_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Промазать противень маслом, обсыпать мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Заполнить тестом шприц, высадить палочки по 10 см.','https:https://st.vkuso.ru/data/cache/thumb/35/dd7efe60d62d435_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Перемешать сахар и сахарную пудру, взять половину смеси, присыпать бисквитные палочки «Савоярди» к кофе, дать постоять 10 минут (до растворения сахара), обсыпать оставшимся сахаром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8811,'Через пару минут отправить в уже прогретую духовку, выпекать до легкой золотистости.','https:https://st.vkuso.ru/data/cache/thumb/de/9b74a1771fc20de_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8812,'Перемешать молоко, масло, воду, подсолить, нагреть смесь до кипения, всыпать муку, вымешать не снимая с плиты пару-тройку минут до получения эластичного теста, дать постоять, чуть остыть.','https:https://st.vkuso.ru/data/cache/thumb/db/0fcc70affad11db_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8812,'Вбить и втереть одно яйцо, затем другое, поступить так со всеми яйцами.','https:https://st.vkuso.ru/data/cache/thumb/95/d3aadecd4fce395_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8812,'Все, заварное тесто на молоке и масле готово, из него получаются аппетитные булочки и другая выпечка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'В первую очередь необходимо приготовить все ингредиенты. Почистить чесночок, почистить и порезать крупно картофель. Измельчить зелень, порезать на кусочки свинину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'На горячую сковороду налить растительное масло, положить свинину, обжарить до образования корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'Порезать лук на полукольца, положить его в сковороду к свинине.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'Обжарить картофель во фритюре, посыпать солью, выложить его в сковороду к мясу и луку,  размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'Порезать чесночок на тоненькие пластинки, порубить соломкой. Положить чеснок к мясу и картофелю. Посыпать специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'Положить чуть-чуть порезанной зелени. Добавить помидоры, порезанные на тоненькие дольки. Размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8813,'Аккуратно положить оджахури на тарелочки. Посыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8814,'Растопить сливочное масло, как можно лучше взбить его с ванилином и сахаром, вбить яйца (по одному), не прерывая взбивание.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8814,'Налить молоко, положить цедру лимона, разрыхлитель и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8814,'Приготовить начинку: все ингредиенты для начинки перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8814,'Вылить ½ теста в формочку, намазанную маслом, осторожно выложить по всей поверхности начинку, залить остальным тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8814,'Выпекать особенный лимонный пирог с творожной начинкой минут 35, соблюдать температуру 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Размягчить масло, растирать, пока не образуется белая масса.','https:https://st.vkuso.ru/data/cache/thumb/73/80c762eff6db873_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Положить творог, насыпать ванильный сахар, муку, размешать.','https:https://st.vkuso.ru/data/cache/thumb/95/eb9162beedb0195_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Раскатать тесто, чтобы получился пласт в толщину около трех миллиметров. При помощи стакана вырезать кусочки.','https:https://st.vkuso.ru/data/cache/thumb/05/43e1cb94be11f05_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Каждый из них присыпать сахаром и сложить на две части. Снова посыпать сахаром, вновь сложить.','https:https://st.vkuso.ru/data/cache/thumb/09/0faba6f64fa8309_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Чуть-чуть сверху посыпать сахаром, положить на противень, застеленный специальной бумагой.','https:https://st.vkuso.ru/data/cache/thumb/aa/0ce429a76dd75aa_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8815,'Отправить в духовку, готовить простое творожное печенье с ванильным сахаром до золотистого цвета при температуре 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/cd/579c5bb41cbc6cd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8816,'Почистить ананас, порезать на тоненькие кружки, обмакнуть в сироп, они должны хорошо пропитаться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8816,'Разложить на противне, застеленном специальной бумагой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8816,'Поставить в духовку на небольшой огонь, высушивать ананасовые чипсы до коричневого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Телятину нарезать кусками толщиной в полтора-два сантиметра поперек волокон.','https:https://st.vkuso.ru/data/cache/thumb/60/7c7088995f8f160_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Накрыть мясо пищевой пленкой, отбить до толщины в полсантиметра.','https:https://st.vkuso.ru/data/cache/thumb/bd/0c27ba9bc5a82bd_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'В емкость большого диаметра насыпать пшеничную муку, прованские травы и соль. Ингредиенты перемешать, обвалять в смеси отбитое мясо.','https:https://st.vkuso.ru/data/cache/thumb/6d/7bb98740c403f6d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Разогреть сковороду с небольшим количеством растительного масла, обжарить отбивные с двух сторон по полминуты.','https:https://st.vkuso.ru/data/cache/thumb/26/cb4beba75a57726_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Если блюдо будет готовиться в несколько приемов, то отвалившуюся панировку и мясной сок лучше удалять, чтобы они не пригорели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'До приготовления соуса готовое мясо накрыть и убрать в тепло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'На оставшемся в сковороде масле обжарить накрошенный репчатый лук и чеснок, овощи должны стать прозрачными.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Влить белое сухое вино, дать покипеть две – три минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8817,'Добавить травы, жирные сливки, готовить, помешивая, еще какое-то время, соус должен немного загустеть. При необходимости посолить. При подаче обжаренное мясо полить соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8818,'Взбить в блендере сок и мякоть ананаса, влить кокосовое молоко (можно заменить ананасовым ликером), смешать все до однородности, перелить в графин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8818,'Измельчить блендером лед, добавить сироп, перемешать все до однородности, вылить к смеси в графин и добавить ром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8818,'Коктейль ромовый «Пина Колада» разлить по бокалам, верх украсить ломтиком ананаса, вставить соломинку и сразу подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Выдавить сок из апельсина. Выдавить или измельчить чесночок. Потереть имбирь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Соединить несколько ложек воды и большую ложку соевого соуса. Добавить чили, хорошенько растворить сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Порезать лук на полукольца, таким же образом поступить со сладким перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Порезать куриное филе. Хорошенько разогреть сковороду с двумя каплями растительного масла и обжаривать мясо секунд шестьдесят, должна появиться легкая корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Положить перец, лук, жарить минуты три, помешивая. Увеличить огонь, налить соус, помешивая, держать на огне две минуты, пока не загустеет соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8819,'Достать «апельсиновую» курицу, подать с рисом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Приготовить тесто из сахарного песка (200 г), сметаны, маргарина, муки и пекарского порошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Массу разделить на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Сырые белки взбить в пену, добавить сахар (200 г) и какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Форму для выпекания смазать маслом, выложить и распределить половину теста, сверху – часть белковой массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Посыпать орехами, тертым шоколадом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Корж поставить в духовой шкаф и печь до готовности при температуре 180 градусов. Точно также выпечь второй корж.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8820,'Для крема сварить манную кашу. Дать каше остыть. Взбить сливочное масло с сахаром, добавить цедру лимона.  Добавить всё в кашу и хорошо взбить. Промазать коржи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8821,'Для приготовления теста всыпать в кастрюлю с толстым дном сахар и соль, подлить молоко и воду, положить сливочное масло. Смесь довести до кипения, помешивать деревянной ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Обжарить измельченный лук, фарш, крупно потертую морковь до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8821,'Всыпать всю муку сразу, перемешать, огонь убавить до среднего. Тесто помешивать до тех пор, пока оно не станет однородным и податливым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8821,'Снять с огня, выложить в кухонный комбайн, взбивать на высокой скорости, добавить сырые яйца по одному. Все операции можно провести вручную, но это займет гораздо больше времени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8821,'Массу переложить в кондитерский мешок или в полиэтиленовый пакет, отсадить пирожные на противень, предварительно застеленный пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8821,'Печь изделия в духовом шкафу при температуре 190 градусов в течение семи минут. Затем дверцу приоткрыть и прогревать изделия еще 13 – 18 минут до образования золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Духовку разогреть. Раскатать тесто для пиццы в форму прямоугольника, положить на противень, застеленный специальной бумагой.','https:https://st.vkuso.ru/data/cache/thumb/91/139d8abb1ba1e91_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Первым слоем положить, чередуя, ветчину, салями, пепперони.','https:https://st.vkuso.ru/data/cache/thumb/8d/edee1973cf7c08d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Затем выложить слоями сыры, базилик, снова сыры, базилик.','https:https://st.vkuso.ru/data/cache/thumb/48/698b58f60b12748_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'При помощи острого ножа сделать надрезы с двух сторон прямоугольника.','https:https://st.vkuso.ru/data/cache/thumb/d1/85c55050f95dfd1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Переплести их в виде косички.','https:https://st.vkuso.ru/data/cache/thumb/34/5ec95aac202df34_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Сверху побрызгать оливковым маслом, присыпать орегано.','https:https://st.vkuso.ru/data/cache/thumb/a2/dee46b8c95de9a2_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8822,'Выпекать минут пятнадцать до золотистой корочки. Чуть-чуть остудить стомболли, подавать с соусом маринара.','https:https://st.vkuso.ru/data/cache/thumb/30/354231501c38f30_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Мелко нарезать лук, веточки базилика, острый перец чили, чеснок.','https:https://st.vkuso.ru/data/cache/thumb/25/dc6aa3651b9d725_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Все ингредиенты перемешать с горчицей, фаршем и рублеными орехами.','https:https://st.vkuso.ru/data/cache/thumb/ff/e5486ce662a6dff_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Фарш годится любой, можно взять свинину и говядину в равных пропорциях. Массу перемешать и сформовать котлеты. Их диаметр должен немного превышать размер булочек, высота – два сантиметра. Сформованные котлеты выложить на лист пергамента, накрыть таким же листом сверху, изделия поставить в холодильник на 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/78/b5e97464270c378_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Для приготовления соуса понадобится нейтральный йогурт или сметана, накрошенный голубой сыр, сок половины лайма. Все ингредиенты хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/c5/bdd1b10833276c5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Обычную сковороду или сковороду-гриль разогреть, обжарить булочки без масла со стороны среза. Должна появиться золотистая корочка. Эту операцию можно провести на открытом огне, если есть такая возможность.','https:https://st.vkuso.ru/data/cache/thumb/59/755ea35fc272c59_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'Обжарить котлеты, по три минуты с каждой стороны.','https:https://st.vkuso.ru/data/cache/thumb/82/57397128736c182_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8823,'На булочку выложить лист хорошо вымытого зеленого салата, пластинки помидоров, котлеты, сметанно-сырный соус и красный лук нарезанный колечками, по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8824,'Всю свежую мяту поделить на 4 части и разложить листья по 4 высоким бокалам со льдом. Смешать в шейкере ром и мультифруктовый сок, разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8824,'Украсить коктейль «Тропический мохито» тонкими ломтиками фруктов и сразу подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8825,'Телячью вырезку обмотать сырой ветчиной или беконом, закрепить ниткой.','https:https://st.vkuso.ru/data/cache/thumb/82/c89f57096b0a682_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8825,'В глубокой кастрюле с антипригарным покрытием дна растопить сливочное масло. Положить мясо, обжарить без крышки в течение 15 минут, переворачивать.','https:https://st.vkuso.ru/data/cache/thumb/72/f0d397adaa8bb72_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8825,'Когда вырезка подрумянится – влить белое сухое вино, потомить без крышки, влага должна выпариться.','https:https://st.vkuso.ru/data/cache/thumb/8d/dc9289deb0e9f8d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8825,'Переложить мясо в форму для запекания, полить остатками соуса из кастрюли, поставить в духовой шкаф. Переворачивать телятину каждые 10 – 15 минут, поливать выделяющимся соком. Температура приготовления – 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/0a/6c58ba482e5870a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8825,'Через 40 минут температуру убавить до 150 градусов, продолжать печь мясо еще час, продолжая поливать соком и переворачивать каждый 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/c8/619871903e56cc8_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Положить томатную пасту, как можно лучше размешать. Положить гречку на мясо и овощи, налить кипяток, чтобы вода чуть-чуть покрывала гречку. Насыпать соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Тушить под крышкой на маленьком огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Положить в гречку по-купечески измельченный чесночок, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8826,'Можно положить лавровый листик, молотый черный перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8827,'Смешать просеянную муку со 130 г сахарной пудры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8827,'Добавить к смеси нарезанное и охлажденное сливочное масло, вымесить тесто до состояния крошки, влить чуть взбитое яйцо и воду, месить до однородности, убрать в холодильник на час (обернуть пленкой). Включить на разогрев духовку до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8827,'Припудрить стол мукой, раскатать тесто в пласт толщиной примерно в 5 мм, вырезать формочками разнообразные фигурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8827,'Смазать противень маслом и переложить на него печенье, выпекать 12-15 минут, вынуть их из дуковки и дать полностью остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8827,'Взбить в крепкую пену сахарную пудру и белки, смазать глазурью остывшее новогоднее печенье « Елочка» и дать высохнуть, подать как десерт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Куриное филе разрезать посередине острым ножом. Посолить и поперчить внутри и снаружи полученный кармашек. Сложить подготовленные филе друг на друга и оставить для пропитывания на 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/32/5e4eee74a1b2432_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Для приготовления начинки смешать рикотту и рубленые листочки розмарина.','https:https://st.vkuso.ru/data/cache/thumb/15/e9e087f7f270a15_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Очистить и нарезать пластинками чеснок, положить в середину кармашков. Часть можно мелко нарубить и смешать с начинкой. Положить начинку.','https:https://st.vkuso.ru/data/cache/thumb/23/87ad83f3efa7723_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Края кармашков закрепить зубочистками.','https:https://st.vkuso.ru/data/cache/thumb/5b/6fb3b1222484a5b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Разогреть на сковороде растительное масло, можно взять оливковое. Положить филе, обжарить с двух сторон по пять минут, до появления румяной корочки. Если филе очень свежее, то времени для приготовления потребуется еще меньше, по три минуты на каждую сторону.','https:https://st.vkuso.ru/data/cache/thumb/01/1474521dbd45d01_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8828,'Огонь убавить, положить на сковороду кусочек сливочного масла, накрыть блюдо крышкой, жарить 10 минут. Готовность мяса проверить острым ножом – вытекающий сок должен стать прозрачным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8829,'Свиную грудинку и куриные сердечки нарезать кусочками. Выложить мясо и субпродукты в кастрюлю, залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8829,'Нарезать кубиками очищенный картофель, натереть на терке морковь. Овощи добавить в суп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8829,'Всыпать фигурную лапшу, сушеную ароматную смесь, состоящую из молотой паприки, лука, чеснока и укропа, перец-горошек, свежую зелень, влить немного растительного масла, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8829,'Готовить блюдо на тихом огне в течение часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8830,'Смешать в чаше блендера сок лайма, кампари, ром, куантро, разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8830,'Перед подачей коктейль с ромом  и ликерами  Кампари и Куантро украсить свежими листиками базилика, можно добавить лед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8831,'Порубить очищенный чеснок.','https:https://st.vkuso.ru/data/cache/thumb/5b/3e01b31bdaf3d5b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8831,'В небольшой емкости перемешать соевый соус, мёд, кунжутное или оливковое масло.','https:https://st.vkuso.ru/data/cache/thumb/5b/05bdd6ed3689c5b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8831,'Добавить куриное мясо, нарезанное кусками, можно использовать крылышки, бёдра, голень. Дать курице помариноваться в течение 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/16/7e1ac84de974e16_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8831,'Противень застелить фольгой зеркальной стороной вверх. Выложить куски на некотором расстоянии друг от друга, полить остатками маринада. Можно добавить еще немного мёда, намазав его на курицу.','https:https://st.vkuso.ru/data/cache/thumb/6a/b9fe08090f7c16a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8831,'Печь при температуре 220 градусов в течение часа. Для проверки мясо надрезать – оно не должно быть розовым внутри. Готовое блюдо посыпать кунжутным семенем и рубленым зеленым луком.','https:https://st.vkuso.ru/data/cache/thumb/92/ec83c8ad77c1592_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Клубни картофеля очистить и отварить в подсоленной воде, размять в пюре.','https:https://st.vkuso.ru/data/cache/thumb/f5/dd543e01b2ee5f5_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Замесить тесто, часа на два отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Разогреть духовку. Сформировать из теста шарики с грецкий орех.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Отварить треску также в подсоленной воде с лавровым листом и душистым перцем-горошком в течение 10 – 12 минут. Бульон слить, рыбу обсушить на бумажном полотенце, поломать вилкой или руками на мелкие кусочки, удалить косточки.','https:https://st.vkuso.ru/data/cache/thumb/14/94867dd81c7df14_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Филе перемешать с картофелем, добавить измельченный чеснок и рубленую зеленую петрушку.','https:https://st.vkuso.ru/data/cache/thumb/12/7f8be0bff0e5612_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Ввести сырые куриные яйца по одному, перемешивать массу до однородности.','https:https://st.vkuso.ru/data/cache/thumb/74/6ed798c7fe58e74_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Сформовать крокеты с помощью двух столовых ложек или мокрыми руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8832,'Разогреть большое количество растительного масла, жарить изделия небольшими партиями до образования золотистой корочки. Для удаления лишнего жира выложить готовые крокеты на бумажное полотенце.','https:https://st.vkuso.ru/data/cache/thumb/53/c771823016ee053_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8833,'Нагреть сковороду. Положить банан, порезанный на ломтики, сбрызнуть медом. Жарить минуты четыре с каждой стороны до карамельного оттенка. Убрать со сковороды, отложить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8833,'Разогреть сковороду на небольшом огне, смазать маслом. Нанести на кусочек хлеба тоненький слой сливочного масла, положить  на сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8833,'Положить сверху бананы, сливочный сыр, на него еще ломтик хлеба, намазанный маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8833,'Готовить бутерброд минуты четыре, обжаривать со всех сторон, пока сыр не расплавится и не поджарится. Подавать сливочно-банановый бутерброд с сыром теплым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Измельчить лук, добавить в фарш. Посыпать перцем, солью, приправами по вкусу.  Почистить картофель, порезать на тоненькие кружочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Сделать заливку, соединить муку, майонез, сметану, яйца, посыпать солью, чуть-чуть взбить вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Намазать сливочным или растительным маслом стенки и дно чаши мультиварки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Положить первый слой картофеля. Чуть-чуть посыпать солью. На картофель положить чуть-чуть заливки, чтобы она скрепила картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Сверху положить слой фарша. Примять его слегка руками, чтобы он плотно лежал на картофеле. Полить фарш заливкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'На фарш положить еще слой картофеля. Чуть-чуть посолить. Второй слой картофеля сделать тоньше первого и кружочки должны быть порезаны тоньше. Полить оставшейся заливкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Закрыть мультиварку крышечкой, включить режим «Запекание» минут на 60.  Когда пройдет час, проверить картофель на готовность. Если он не приготовился, то готовить еще минут 15. Время приготовления картошки в мультиварке зависит от сорта картофеля.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Когда картофельная запеканка с фаршем в мультиварке будет готова, открыть крышку и позволить ей остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8834,'Вставить в чашу мультиварки емкость для готовки на пару, перевернуть чашу мультиварки. Запеканка с легкостью выйдет.  Переложить блюдо на тарелочку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8835,'Вылеть джин, вермут,  лимонный сок в чашу блендера. Включить блендер и перемешать смесь в течение нескольких секунд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8835,'Коктейль Вермут и Джин с лимонным соком разлить по высоким стаканам с дробленым льдом, украсить по вкусу и сразу подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'Взбить белки до пены при помощи венчика. Насыпать сахар, чуть-чуть взбить. Добавить ванилин, желтки, хорошенько растереть.','https:https://st.vkuso.ru/data/cache/thumb/2b/2a0c5a57a87fd2b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'Соду погасить уксусом или соком лимона, добавить в тесто.','https:https://st.vkuso.ru/data/cache/thumb/8c/c8bd0f341dd928c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'Растопить масло и налить в тесто.','https:https://st.vkuso.ru/data/cache/thumb/d5/8cd5ae472792ad5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'В самом конце постепенно насыпать муку. Получится густое тесто.','https:https://st.vkuso.ru/data/cache/thumb/92/0155f9782509492_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'Готовить вафли в вафельнице. В горячем виде свернуть в трубочку.','https:https://st.vkuso.ru/data/cache/thumb/8b/b3acb0f9bd7ef8b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8836,'Наполнить вафли вареной сгущенкой с помощью кондитерского шприца.','https:https://st.vkuso.ru/data/cache/thumb/76/c3950c8bda16c76_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Растопить масло с шоколадом на водяной бане. Положить в массу чуть взбитые яйца с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Насыпать соль, муку, разрыхлитель, добавить орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Вводить муку поочередно с жидкостью (водой, молокой, вином).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11712,'Обезжиренный творог взбить с сахаром и сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8837,'Положить печенье на противень, застеленный специальной бумагой, на определенном расстоянии. Готовить приблизительно 13 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'Измельчить в блендере печенье или потолочь в крошку. Намочить печенье соком яблока, вымесить, чтобы получилась консистенция пластилина. Положить равномерно на дно разъемной формочки диаметром двадцать сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'Приготовить начинку: взбить йогурт, творог, сахар, цедру, лимонный сок до однородной, гладкой формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'В смесь медленно ввести крахмал и яйца. Хорошенько взбить. Положить начинку на основу, распределить равномерно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'Обернуть формочку для чизкейка фольгой, поставить в посуду побольше, наполненную водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'Отправить посуду с водой и чизкейком в духовку минут на пятьдесят, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8838,'Выключить духовку, не вынимать чизкейк диетический еще часа два. Охладить, украсить ягодным соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8839,'В емкости соединить молоко и яйца. Вылить смесь на сковороду, подождать секунд шестьдесят. Посыпать итальянской приправой. При помощи лопатки ровно распределить массу по сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8839,'Положить на лепешку тортилья яичную смесь, посыпать сыром, накрыть второй частью лепешки, обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8839,'Перевернуть, обжаривать еще секунд шестьдесят до золотистого цвета. Перед подачей кесадилью с сыром Монтерей Джек и яйцами разрезать на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8840,'Мелко потереть морковь, крупно - яйца, яблоко без кожуры, крабовые палочки. На блюде сделать майонезную сетку, положить тертую морковь, сетку из майонеза, тертые яйца, майонез, слой тертых яблок, майонез, крабовые палочки, майонез, кукурузу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8840,'Кукурузу поливать майонезом не нужно, она является украшением салатика. Украсить салат «Кудрявый» зеленью. Для пропитки отправить салатик в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Подготовить предварительно фасоль. Перебрать, вымыть, замочить в воде минимум часов на пять, а желательно на ночь, тогда она хорошо набухнет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Вновь промыть фасоль водой, высыпать в кастрюльку, залить водой, готовить часа два. Откинуть фасоль на дуршлаг, позволить стечь воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Почистить лук, порезать не очень крупно, обжарить на масле до золотистого оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Положить к луку горячую фасоль, перемешать. Фасоль должна впитать аромат жареного лука. Томить на тихом огне, следить, чтобы фасоль не подгорала.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Измельчить зелень. В посуду выдавить лимонный сок, насыпать специи, положить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Пропустить чесночок через пресс. Измельчить при помощи блендера грецкие орехи. Положить орехи и чеснок в смесь из зелени, специй и сока лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Перемешать все продукты, переложить в сковороду с фасолью. Влить 0,25 стакана воды, накрыть крышкой, тушить минут десять на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8841,'Позволить блюду настояться минут пятнадцать, можно подавать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8842,'Сырые куриные яйца взбить с сахарным песком, влить кефир, ввести муку, какао-порошок, разрыхлитель, ванилин, тертый черный шоколад. Влить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8842,'Полужидкое тесто разлить в формы для маффинов, печь в течение 20 минут, температура – 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8842,'Для крема взбить белки с сахарной пудрой, добавить краситель по желанию. Остывающие капкейки украсить кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8843,'Крабовые палочки разморозить и нарезать кусочками по одному сантиметру. Такими же кусочками нарезать ананас.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8843,'Наколоть продукты на шпажки в таком порядке: маслины, ананас, кусочек крабовой палочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8844,'Репчатый лук нарезать тонкими полукольцами и обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8844,'Сыр, маринованные огурцы и грибы, копченую куриную грудку нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8844,'Все ингредиенты перемешать и заправить майонезом по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8845,'Темный хлеб нарезать квадратиками, свежий огурец – тонкими пластинками при помощи ножа для чистки овощей, соленую семгу – кубиками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8845,'Намазать хлеб плавленым сыром. Кусочек рыбы закрутить в огурец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11712,'Масса должна получиться нежной и однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8846,'Готовое слоеное тесто нарезать кружками. В половине заготовок вырезать серединку, чтобы получились кольца. Соединить полукольца с кружками, печь в духовом шкафу в течение 15 – 20 минут, температура – 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8846,'Для приготовления салата нарезать кубиками мякоть авокадо, вареные яйца, красную соленую рыбу. Оливки мелко нарезать, смесь заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8846,'Готовый салат выложить в готовые тарталетки, сверху украсить красной икрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8847,'Испечь из слоеного теста небольшие кружочки в качестве основы для канапе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8847,'Намазать готовые изделия плавленым сыром, перемешанным с рубленым укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8847,'На шпажку наколоть отваренную креветку и оливку, воткнуть в основу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8848,'Отварить куриную грудку в воде с добавлением соли, лаврового листа, розмарина, черного и душистого перца-горошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8848,'Обжарить нарезанные грибы с репчатым луком, посолить и поперчить по вкусу, добавить сушеный тимьян.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8848,'Выложить салат на блюдо: первый слой – куриная грудка, майонез, второй – грибы, майонез, третий – тертый сыр, майонез. Сверху – тертые белки. Все слои повторить еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8848,'Украсить тертым желтком, веточками укропа и ягодами калины в виде елочных игрушек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8849,'Готовое слоеное дрожжевое тесто нарезать квадратами. В двух углах, находящихся друг против друга, сделать надрезы для формирования бортика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8849,'Смазать заготовки из теста взбитым яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8849,'В центр положить кусочек сыра, затем несколько кусочков груши, ее лучше нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8849,'Время выпекания – 15 минут, температура – 200 градусов. Посыпать рублеными грецкими орехами и печь еще пять минут. Полить слойки жидким медом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8850,'Скумбрию натереть специями для рыбы, перцем, солью, сделать в тушках несколько надрезов и поместить в них дольки лимона. Дать постоять для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8850,'Запечь при температуре от 180 до 190 градусов, время – от получаса до 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8851,'Взбить сырые куриные яйца с молоком и ванилином, добавить подсластитель по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8851,'Перемешать кукурузную и рисовую муку, какао-порошок, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8851,'Ввести сухую смесь в  яичную постепенно, порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8851,'Добавить в полученное тесто вишню и шоколад. Время выпекания – от 40 до 50 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8852,'Для приготовления блюда понадобится такой кусок свинины, который можно скрутить рулетом. Мясо нашпиговать пластинками чеснока, натереть солью, перцем, прованскими травами, паприкой, сушеным чесноком, молотым укропом, розмарином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8852,'Намазать филе зернистой дижонской горчицей, рулет плотно скрутить, перевязать. Печь в течение часа в фольге и 20 минут без фольги для получения румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8852,'Остудить, отправить в холодильник. Нить снять, закуску нарезать тонкими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8853,'Приготовить тесто из молока, яиц, сахарного песка. Ингредиенты перемешать при помощи миксера. Муку всыпать постепенно, порциями, дать постоять. Испечь блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8853,'Нарезать шампиньоны, репчатый лук, то и другое обжарить на сковороде, посолить, поперчить, по желанию добавить сушеный тимьян. Начинку остудить и завернуть в блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8854,'Перемешать творог с яйцом и сахарным песком, немного посолить, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8854,'Ввести муку, можно добавить соду для воздушности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8854,'Тесто выложить ложкой на горячую сковороду, печь под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8855,'Жирные сливки соединить с молоком, добавить половину нормы сахара, прогреть на тихом огне до появления пузырьков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8855,'Сырые желтки взбить с остатками сахара в плотную пену, добавить 2 ст.л. теплой молочной смесьи. Взбить миксером, влить желтки в молочную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8855,'Спелые бананы измельчить в блендере, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8855,'Варить джелато на тихом огне, доводим до 85 градусов. Готовность десерта можно проверить ложкой: масса не должна стекать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8855,'Смесь остудить, поставить в морозильную камеру, перемешивать по одному разу в час. Через пять или шесть часов десерт готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8856,'Для приготовления теста перемешать творог с яйцом, ванилином, сахарным песком, ингредиенты перемешать. Добавить мягкое сливочное масло, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8856,'Муку всыпать постепенно, замесить тесто. Массу положить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8856,'Любые фрукты нарезать тонкими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8856,'Тесто вынуть из холодильника, разделить на три части, тонко раскатать, толщина лепешки не должна превышать два миллиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8856,'Выложить фрукты, края оставить свободными. Завернуть так, чтобы не вытек сок, посыпать сахаром, печь в течение 20 или 30 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8857,'Разлить по высоким фужерам шампанское, добавить по одному кубику сахара, горький бальзам ангостура, бренди, перемешать и сразу подать коктейль с бренди и сухим шампанским к столу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8858,'Залить булгур водой в пропорции стакан крупы на полтора – воды, подсолить, отварить до полного впитывания воды.','https:https://st.vkuso.ru/data/cache/thumb/71/c624bdee10b4671_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8858,'Мелко порубить листья петрушки и мяты.','https:https://st.vkuso.ru/data/cache/thumb/ea/d519f8653aaebea_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8858,'Порезать мелко довольно твердый помидор и перец чили очень острым ножом.','https:https://st.vkuso.ru/data/cache/thumb/ba/2d6ec1fef0431ba_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8858,'Для заправки восточного табуле с булгуром смешать оливковое масло, лимонный сок, перец, дать салату примерно час постоять в холодильнике и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/fc/c9476bfde915cfc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Для приготовления блюда лучше использовать смешанный фарш, состоящий из говядины и свинины в равных пропорциях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Репчатый лук очистить, нарезать, добавить в фарш вместе с солью, молотым перцем, чесноком, рубленой зеленью петрушки, влить немного холодной воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Массу хорошо перемешать и поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Для соуса очистить и нарезать небольшими кубиками баклажаны, залить холодной подсоленной водой, чтобы вышла горечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Измельчить лук и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Сладкий болгарский перец очистить от семенных камер, мякоть нарезать небольшими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Натереть на крупной терке кабачок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Ошпарить помидоры, кожицу снять, мякоть также натереть на крупной терке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Разогреть на сковороде растительное масло, обжарить чеснок и лук до прозрачного состояния.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Добавить отжатые баклажаны и потушить овощи в течение двух-трех минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Затем положить в сковороду измельченный болгарский перец и кабачок, тушить еще столько же.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'В последнюю очередь добавить столовую ложку томатной пасты и помидоры, прогревать на тихом огне до испарения жидкости и мягкости овощей.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Соль и перец – по вкусу, добавить мелко нарезанную зеленую петрушку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Готовый соус можно дополнительно измельчить с помощью блендера или оставить так, как есть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Постоявшее тесто раскатать в тонкую лепешку, выложить на неё фарш тонким ровным слоем. Один край оставить пустым.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Свернуть рулет, уплотнить руками, нарезать на кусочки по три-четыре сантиметра толщиной.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Огнеупорную форму смазать растительным маслом, выложить кусочки на срезы, между ними налить овощной соус.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Кушанье залить свежим овощным бульоном, жидкость должна находиться на уровне верхнего края пельменей.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8859,'Блюдо отправить в духовой шкаф на полчаса или чуть больше. Температура приготовления – 180 градусов.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8860,'Нарезать на тонкие пластинки кусочек имбиря, переложить в шейкер и для аромата чуть выдавить ложкой сок. Залить водку, добавить немного дробленого льда, тщательно встряхнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8860,'Разлить водку с имбирем по фужерам, положить лед и долить фужеры шампанским, украсить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Сладкий болгарский перец и красный острый перец вымыть и высушить.','https:https://st.vkuso.ru/data/cache/thumb/c4/849662a5d3d1ac4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Острый перец залить кипящей водой на пять минут, затем процедуру повторить, после такой обработки продукт легко и просто очистится.','https:https://st.vkuso.ru/data/cache/thumb/01/9aca556aab06201_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Нарезать кружочками спелый банан, выложить на корж в любом порядке, залить киселем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Удалить из тех и других перцев перегородки и семена.','https:https://st.vkuso.ru/data/cache/thumb/8e/f8c4ca5acd12f8e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Очистить репчатый лук.','https:https://st.vkuso.ru/data/cache/thumb/f9/e4799e03fa585f9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Перцы измельчить с помощью кухонного комбайна или острым ножом. Так же поступить с луком-репкой.','https:https://st.vkuso.ru/data/cache/thumb/27/b697b30d05cfe27_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Тонко нарезать очищенный лимон, белую оболочку удалить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Перемешать в кастрюле сахарный песок, яблочный уксус, перцы, лимон, любые пряности и лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Поставить смесь на огонь, довести до кипения, огонь убавить, варить полчаса. Для удобства специи и лимон можно положить в тканевый мешочек.','https:https://st.vkuso.ru/data/cache/thumb/46/bb18a1751579246_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Дать соусу постоять под крышкой до утра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'На следующий день массу вновь довести до кипения, огонь убавить, варить до нужной консистенции в течение двух часов. Соус периодически помешивать, он не должен пригореть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'В процессе приготовления вынуть пряности, крупные не перемолотые кусочки овощей, если таковые нечаянно попадут в джем.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8861,'Готовый продукт разлить в небольшие баночки, закрыть их крышками, укутать полотенцем до полного остывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8862,'Вымыть и обсушить курицу, обрезать крылышки.','https:https://st.vkuso.ru/data/cache/thumb/19/2715de8b1d30519_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8862,'Понадобится веревка длиной в три раза больше размера курицы. Положить тушку на стол грудкой верх, шейкой к себе. Веревку продеть под курицей, рядом с хвостовой частью, затем вокруг ножек, концы веревки скрестить, натянуть их вдоль боков и бёдер, крылышки плотно прижать. Плотно затянуть узел вокруг шейки.','https:https://st.vkuso.ru/data/cache/thumb/0d/a773d7ec7eb870d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8862,'«Связанную» тушку посолить и поперчить.','https:https://st.vkuso.ru/data/cache/thumb/fe/0b5ce85b12b68fe_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8862,'Приготовить мирпуа – овощную смесь из репчатого лука, моркови и стеблей сельдерея. Все перечисленные овощи нарезать на одинаковые кусочки, мелкие приготовятся быстрее, на приготовление более крупной нарезки понадобится больше времени.','https:https://st.vkuso.ru/data/cache/thumb/84/649316a4ca23584_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8862,'Противень сбрызнуть растительным маслом, выложить овощи, поставить решетку, на неё выложить курицу. Тушку можно положить и на саму подушку из овощей, но на решетке она прожарится более равномерно. Блюдо поставить в нагретую до 190 градусов духовку на 45 – 60 минут, время зависит от возможностей духового шкафа и величины курицы. Готовить, пока тушка не покроется тонкой хрустящей золотистой корочкой.','https:https://st.vkuso.ru/data/cache/thumb/5b/ceaebdbba39085b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Лимон вымыть и обсушить, цедру с половины плода натереть не мелкой терке, сок отжать.','https:https://st.vkuso.ru/data/cache/thumb/86/a650a0103233886_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Довести воду до кипения, растворить темный гречишный мёд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Отдельно взбить с сахарным песком сырые куриные яйца и дополнительные желтки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Добавить в массу разрыхлитель, лимон, корицу, молотый имбирь, растолченную гвоздику, мускатный орех.','https:https://st.vkuso.ru/data/cache/thumb/98/093c8bfc83e6798_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Влить медовую воду, смесь еще раз хорошо взбить вручную или с помощью блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Постепенно, порциями, ввести в массу пшеничную муку. Тесто должно получиться мягким.','https:https://st.vkuso.ru/data/cache/thumb/81/89d564c2c0c4f81_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Накрыть его пищевой пленкой и оставить на шесть часов при комнатной температуре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Получившуюся массу еще раз вымесить, раскатать в лепешку толщиной в один сантиметр, нарезать формочками пряники.','https:https://st.vkuso.ru/data/cache/thumb/88/3686e316084e688_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Изделия выложить на застеленный бумагой противень. Печь пряники в течение 20 минут при температуре 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/11/84b034f613dbf11_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8863,'Остывшую выпечку можно полить глазурью. Для её приготовления перемешать теплую воду с сахарной пудрой, прогреть на небольшом огне в течение нескольких минут.','https:https://st.vkuso.ru/data/cache/thumb/1d/202927978f27a1d_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Сливочное масло прогреть в кастрюле, пока не растает, постепенно добавить пшеничную муку, помешивать, чтобы не образовались комки. Мука должна впитать все масло.','https:https://st.vkuso.ru/data/cache/thumb/cf/b8deb11ae13f3cf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Все овощи сложить в емкость большого размера, полить уксусом, посыпать сухими специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Постепенно влить молоко, продолжать помешивать и прогревать на тихом огне, добавить по вкусу соль и молотый перец. Если масса получилась слишком густой – добавить молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Всыпать мускатный орех, сливочное масло, пряности, по желанию – тертый хрен.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Белые грибы, можно размороженные, прокипятить в течение пяти-семи минут в подсоленной воде, промыть холодной водой. Продукт переложить на сковороду и припустить на растительном масле в течение 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/f0/6552922c0e909f0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Соус перемешать с грибами, подержать на тихом огне, помешивать, он должен загустеть. Если слишком густо – разбавить смесь молоком, выключить огонь и дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/f1/c154542d8f645f1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8864,'Отварить макароны, любые: феттуччини, рожки, пенне, спагетти. Выложить их на тарелку, полить соусом, посыпать рубленой зеленью.','https:https://st.vkuso.ru/data/cache/thumb/66/1bda17bec7b7166_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Куриное филе нарезать вдоль тонкими пластинками, а затем полосками, солить не нужно.','https:https://st.vkuso.ru/data/cache/thumb/70/de4e8e4dde2b870_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Раскалить на сковороде растительное масло, выложить мясо, придавая ему различную форму. Жарить со всех сторон до получения золотистой корочки. Выложить полоски на бумажное полотенце для впитывания лишнего жира.','https:https://st.vkuso.ru/data/cache/thumb/fc/1a172d397fd5cfc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Мелко нашинковать репчатый лук, обжарить до получения золотистого цвета, перемешать с мясом.','https:https://st.vkuso.ru/data/cache/thumb/ee/b5cb980103b30ee_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Зеленые яблоки очистить от семенных камер, мякоть нарезать кубиками, сбрызнуть лимонным соком, чтобы не почернела.','https:https://st.vkuso.ru/data/cache/thumb/60/1cf100d46740660_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Отваренный в мундире картофель очистить и нарезать кубиками. Перемешать все подготовленные ингредиенты, добавить рубленый чеснок.','https:https://st.vkuso.ru/data/cache/thumb/ad/02caaabdb28a8ad_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Для соуса смешать натуральный йогурт без вкусовых и цветовых добавок, подлить лимонный сок, всыпать рубленую зелень кинзы и укропа, молотый перец, положить мёд.','https:https://st.vkuso.ru/data/cache/thumb/a2/b08bfec64844ea2_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8865,'Выложить в порционную тарелку горсть промытых салатных листьев. Перед подачей курицу с овощами и фруктами прогреть на сковороде без масла, огонь – средний. Смесь выложить в тарелку, отдельно подать соус.','https:https://st.vkuso.ru/data/cache/thumb/92/449f5f1ec148292_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'Смешать для маринада мед и сок лимона, соевый соус, имбирь и половину сливочного масла, присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'Нарезать грудки индейки на порционные кусочки, переложить в миску, залить маринадом, убрать в холодное место на полтора часа, чтобы выделился сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'За 15 минут до окончания маринования включить духовку, пусть она разогреется до 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'Поместить мясо в форму для запекания, полить оливковым маслом, запекать примерно 30 минут, чтобы появилась румяная корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'Слить в сковороду из формы выделившийся при запекании мяса сок, поперчить, добавить сахар, вторую половину масла, хорошо разогреть и обжарить кусочки ананаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8866,'Запеченная индейка  с медом, имбирем и соевым соусом перед подачей поливается ананасовым соусом и украшается кусочками ананаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8867,'Пресное, слоеное тесто, купленное в магазине, раскатать, нарезать треугольниками.','https:https://st.vkuso.ru/data/cache/thumb/53/a3db9f8f130e953_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8867,'Выложить их на смазанный маслом противень, расположив по кругу.','https:https://st.vkuso.ru/data/cache/thumb/0b/5a3dc94096e4a0b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8867,'Сверху – ломтики бекона, тертый твердый сыр.','https:https://st.vkuso.ru/data/cache/thumb/f5/4333faf40512cf5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8867,'Поверх сыра – отваренные измельченные яйца, засыпать остатками сыра.','https:https://st.vkuso.ru/data/cache/thumb/ea/487d2fe494bcbea_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8867,'Края теста завернуть внутрь, каждый кончик защипнуть. Пирог смазать взбитым с молоком желтком, посыпать кунжутным семенем, печь в разогретой духовке в течение получаса, при температуре 180 – 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/76/842c2501bed1c76_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8868,'Брокколи отварить в течение пяти минут, вынуть из горячей воды, опустить в ледяную. Такая обработка позволит сохранить первоначальный зеленый цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8879,'Отварить картофель, свеклу и куриную грудку. Овощи натереть на терке, мясо нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8868,'Сырые куриные яйца взбить с молоком, добавить замороженную овощную смесь: зеленый горошек, морковь, зеленую стручковую фасоль, кукурузу, сладкий болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8868,'Продукты перемешать, добавить рубленую петрушку и укроп, перец молотый и морская соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8868,'Готовую массу вылить в огнеупорную форму, соцветия брокколи вставить вертикально. Печь в духовом шкафу при температуре 170 градусов в течение 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Для приготовления теста перемешать в чашке сырое куриное яйцо, сметану, кефир, растительное и растопленное сливочное масло комнатной температуры. Соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Пищевую соду погасить уксусом, добавить в основную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Всыпать просеянную пшеничную муку, замесить тесто. Массу накрыть тканевой салфеткой и оставить на время приготовления начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Для начинки нарезать любое мясо с некоторым количеством жира. Для этой цели подойдет смесь говядины, баранины и гусятины. Можно взять один вид мяса, например, баранину или говядину. Вид нарезки – небольшие кубики со стороной в полтора-два сантиметра, продукт измельчить острым ножом или с помощью комбайна.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Точно так же нарезать очищенный картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Мелко измельчить репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Ингредиенты для начинки перемешать, поперчить и посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Для приготовления блюда понадобится готовый куриный или говяжий бульон. Если его нет, налить в сотейник воду, добавить сливочное масло, соль, довести смесь до кипения, поварить две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Чугунную толстостенную сковороду обмотать полотенцем с внешней стороны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Тесто разделить на большую и малую части в пропорции один к трем.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'От меньшей части отделить небольшой кусочек, он понадобится в качестве пробки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Оставшуюся часть разделить надвое.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Большую часть теста раскатать так, чтобы лепешка свисала со сковороды на пять-шесть сантиметров со всех сторон. Сверху выложить мясную начинку.','https:https://st.vkuso.ru/data/cache/thumb/d7/7574a7adfd63fd7_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Края лепешки поднять вверх и защемить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Оставшуюся часть теста раскатать в качестве крышки, накрыть ею будущую выпечку, соединить с боковыми краями теста.','https:https://st.vkuso.ru/data/cache/thumb/a0/17a49bb47ae5ca0_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Еще один оставшийся кусок использовать в качестве украшения с лучеобразными надрезами: выложить лепешку на пирог, надрезы защемить попарно.','https:https://st.vkuso.ru/data/cache/thumb/be/b1e559275587ebe_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'В середине выпечки сделать небольшую дырочку и прикрыть её «пробкой» из теста. Это отверстие необходимо для вливания бульона.','https:https://st.vkuso.ru/data/cache/thumb/09/1df7eaef3c09509_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Смазать пирог растопленным сливочным маслом, поставить в духовой шкаф на два или два с половиной часа, температура приготовления – 200 градусов.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Через час или полтора после начала приготовления пирог вынуть, открыть пробку, влить стакан бульона или водно-масляную смесь, снова закрыть пробку и допечь пирог в духовке.','https:https://st.vkuso.ru/data/cache/thumb/c4/b9493560c978dc4_434x295.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Если верх выпечки уже хорошо зарумянился, а начинка не готова – нужно взять бумагу для выпекания, смять её, смочить холодной водой и в таком виде выложить на пирог. Способ спасет блюдо от преждевременного пригорания.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Готовность пирога определяется готовностью его начинки, её можно попробовать, открыв «пробку».',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8869,'Пирог подавать на стол горячим, в той самой форме, в которой он готовился. Крышку пирога нарезать по кругу, каждому едоку положить в тарелку по кусочку этой крышки. Оставшуюся выпечку нарезать вместе с дном, подать нижнюю часть также с начинкой.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Баклажаны нарезать тонкими ломтиками, кожуру не чистить. Посыпать овощи солью, дать постоять два часа, чтобы ушла горечь и лишняя влага. Обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Красный болгарский перец нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Нарезать репчатый лук тонкими полукольцами, по желанию замариновать: посолить, добавить сахар и уксус, залить кипящей водой, через 30 минут воду слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Натереть морковь с помощью специальной терки «по-корейски».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'В сотейник налить растительное масло, положить рубленый чеснок, черный перец, мед, имбирь, налить соевый соус. Смесь прогреть, но не доводить до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8870,'Полить овощи, поставить в холодильник на два часа для пропитывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8871,'Баклажаны нарезать кусочками небольшого размера, посолить и оставить на два часа. Промыть от лишней соли, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8871,'Лук очистить, нарезать тонкими полукольцами, посолить, посыпать сахаром, добавить уксус и залить кипятком. Через полчаса жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8871,'Отварить яйца, очистить, нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8871,'Соединить все ингредиенты, поперчить, заправить майонезом или сметаной, можно использовать смесь того и другого в соотношении один к одному.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8872,'Нарезать кубиками квашеную капусту, отваренный картофель, порубить зеленый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8872,'Посолить, поперчить, заправить растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8873,'Яйца с сахарным песком взбить в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8873,'Сметану перемешать с манкой, оставить постоять на 10 или 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8873,'В яичную массу добавить творог, ванилин, цедру половины лимона, взбить массу при помощи погружного блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8873,'Добавить сметану с манкой, взбить',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8873,'Выпекать при температуре 180 градусов 35-45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8874,'Жирные сливки прогреть, до кипения не доводить, снять с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8874,'Всыпать в сотейник сахарный песок, влить воду, варить от шести до восьми минут на среднем огне. Довести массу до янтарного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8874,'Снять с огня, влить сливки тонкой струйкой, помешивать. Варить пять или шесть минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8874,'Всыпать соль, добавить сливочное масло, ингредиенты перемешать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8874,'Перелить массу в емкость для хранения, это может быть пластиковый контейнер или обычная стеклянная банка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Замесить тесто: соединить топленое сливочное масло с молоком и с сахарным песком, солью, сырыми куриными яйцами, сухими дрожжами и мукой. Оставить массу на час или полтора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Обмять тесто, оставить еще на полчаса, затем раскатать в виде прямоугольной лепешки толщиной в полсантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Смазать поверхность мягким сливочным маслом, посыпать смесью сахарного песка и молотой корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Свернуть рыхлый рулет, затем нарезать его на булочки шириной от четырех до пяти сантиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Выложить изделия на противень, немного обмять края, оставить промежутки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Печь при температуре 180 градусов, время – от 25 до 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Для приготовления глазури перемешать сахарную пудру с лимонным соком, добавить творог.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8875,'Полить смесью теплые булочки и подать их к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'Приготовить тесто из мягкого сливочного масла, сахара, яиц, муки. Можно добавить немного воды. Замесить тесто, оно должно получиться однородным, поставить в холодильник на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'Вынуть тесто, раскатать, разложить в формы, печь в течение 15 – 20 минут, температура приготовления – 180 градусов. Выпечку остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'Сварить заварной крем: в молоко добавить ванилин и сахар, перемешать, поставить на тихий огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'В начале закипания влить жидкую смесь из муки и яиц. Крем помешивать, чтобы исключить возможность пригорания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'Загустевшую массу снять с огня, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8876,'Разлить массу в тарталетки, украсить сезонными фруктами, полить готовым кондитерским желе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8877,'Размягченное сливочное масло перемешать с сахарным песком, вбить сырое яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8877,'Всыпать муку, ванилин из пакетика, пищевую соду, овсяные хлопья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8877,'Сформовать печенье мокрыми руками, выложить на противень, застеленный пергаментом, поставить в духовой шкаф на 15 – 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8878,'Отделить белки от желтков. Белки взбить с сахарным песком, желтки перемешать с творогом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8878,'В творожно-яичную массу влить молоко и всыпать муку, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8878,'Добавить белки, чернику, перемешать. Обжарить оладьи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8879,'Выложить салат слоями: картофель, морковь по-корейски, куриная грудка, лук, свекла, грецкие орехи, сверху – зерна граната. Слои промазывать майонезом.  Для того чтобы сформовать массу в виде браслета, можно использовать стакан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8880,'Взбить яйца, всыпать сахарный песок, ванилин, влить кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8880,'Добавить муку, разрыхлитель для теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8880,'Однородную массу перелить в форму и выложить поверх половинки слив без косточек. Время выпекания – 40 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8881,'Отварить картофель, нарезать вместе с маринованными огурцами и охотничьими колбасками, репчатым луком. Порубить зелень петрушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8881,'Заправить салат горчицей, растительным маслом, посолить, поперчить по вкусу. Добавить сушеные травы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8882,'Мягкое сливочное масло перемешать с мукой, вбить яйцо, добавить тертый сыр. Соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8882,'Готовое тесто поставить на два часа в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8882,'Массу раскатать, обрезать в круг и разделить на сегменты, на восемь частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8882,'Время выпекания в духовом шкафу – от 15 до 20 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8883,'Подготовить (очистить от кожуры, удалить семена) сочные яблоки, порезать дольками, положить в сковороду, добавить сок лимона, сахар, тушить помешивая на сильном огне около 5 минут. Переложить их в блендер, долить сок от тушения и сделать пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8883,'Добавить к полученной смеси ликер, перемешать и переложить в форму. Взбить в густую пену белок яйца, добавить к содержимому формы и аккуратно перемешать, поставить в морозилку застывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8883,'Когда масса застынет на половину перемешать еще раз и опять убрать на холод. Процедуру повторить еще 2-3 раза, чтобы яблочный сорбет с апельсиновым ликером получился воздушным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8883,'Перед подачей с лимона срезать цедру в форме спирали и украсить сорбет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8884,'Соединить молоко с сахаром и сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8884,'Довести до кипения на тихом огне. Варить в течение десяти минут на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8885,'Готовое слоеное тесто нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8885,'Сыр и колбасу натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8885,'Одну полоску теста смазать майонезом, другую – соусом «Кетчуп».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8885,'Выложить на одну из полосок любую начинку, накрыть второй полоской и повернуть края в разные стороны так, чтобы получилась спираль. Выпечь 20-25 минут при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8886,'Отварить картофель, размять с яйцом, посолить и поперчить по вкусу, всыпать часть муки и замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8886,'Разделить массу на четырнадцать частей, сформовать лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8886,'Выложить начинку из тертого сыра и ветчины, накрыть второй лепешкой. Раскатать скалкой и обжарить на тихом огне до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8887,'Мягкое сливочное масло взбить со сгущенным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8887,'Готовое печенье обмакнуть в крепко заваренный кофе, выложить послойно, промазать кремом из сгущенки и измельченных орехов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8887,'Поставить в холод на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'Дать тесу оттаять, лук нашинковать небольшими кубиками вместе с ветчиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'В сковороде разогреть масло, обжарить кубики лука с ветчиной, всыпать порубленную петрушку, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/73/3d3a9bcceaada73_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'Крупно натереть сулугуни высыпать в сковороду, хорошо размешать, попробовать, если надо, то присолить.','https:https://st.vkuso.ru/data/cache/thumb/49/19415a9457b6749_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'Разрезать каждый пласт теста пополам, сделать в углах диагональные надрезы, уложить на тесто начинку (по полной ст.л.), защипать углы с каждой стороны, далее соединить их посередине крест на крест.','https:https://st.vkuso.ru/data/cache/thumb/d9/55c6ee0e5f1d3d9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'Включить для прогрева до 200 градусов духовку, выстлать противень пергаментом, промазать маслом, разложить слойки с ветчиной, сулугуни и зеленью на противень, смазать разболтанным желтком верх каждой слойки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8888,'Поместить противень в духовку, выпекать в уже прогретой духовке около 40 минут. Когда слойки будут готовы слегка присыпать их молотым перцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Поставить блюдо в холодильник на три часа, до полного застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8889,'Взбить в устойчивую пену яйца, ввести, не прекращая взбивать, по частям сахар, ваниль и молотый мускатный орех. В процессе взбивания влить постепенно молоко, сливки, коньяк и ром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8889,'Перед подачей напиток из сливок, рома и коньяка желательно охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8890,'Отварные макароны уложить на дно формы для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8890,'Помидоры порезать на тонкие кружочки, разложить на макароны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8890,'Присыпать измельченным на терке сыром с перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8890,'Чеснок порезать на крупные ломтики, положить сверху запеканки, равномерно тонко промазать слоем майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8890,'Выпекать макароны с помидорами и чесноком под сыром до полной готовности примерно минут 20, к столу подавать блюдо пока горячее. Можно присыпать порубленной зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'Сырые яйца взбить со щепоткой соли в плотную пену, сахарный песок добавлять постепенно, порциями. Влить стакан кефира, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'В отдельной емкости перемешать муку и разрыхлитель, какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'В яичную смесь влить растительное масло, взбивать миксером, постепенно вводить сухие ингредиенты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'Темный шоколад нарезать ножом на кусочки, ввести в основную массу, осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'Смазать маслом форму для выпекания, вылить тесто, поставить в духовой шкаф на 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8891,'Готовность проверить палочкой или зубочисткой. Растопить на водяной бане или в микроволновой печи белый шоколад и сливочное масло. Полить помадкой кекс.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Растопить масло, нагреть молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Соединить все продукты для теста, замешивать 5 минут, накрыть, отправить в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Тесто должно подняться в несколько раз. Можно замешивать в хлебопечке на режиме «Тесто» - полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Сделать начинку: протереть творог через сито, положить ваниль, желтки, сливочное масло, цедру.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Насыпать сахар, крахмал. Перемешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Раскатать тесто в прямоугольник, поделить его на 12 частей, в центр положить начинку: 3-4 черешни, обваленных в крахмале, и большую ложку творога.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Защипнуть сначала два противоположных конца квадрата, потом еще два.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Переложить на противень, застеленный бумагой. Накрыть полотенцем, отставить на 30 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8892,'Нагреть духовку до 190 градусов, намазать творожные конвертики с черешней яйцом, взбитым с ложкой воды. Готовить 25 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Приготовить соус: смешать оливковое масло, майонез, прессованный чеснок, специи.','https:https://st.vkuso.ru/data/cache/thumb/00/87060c55df1ea00_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Намазать соусом основу для пиццы.','https:https://st.vkuso.ru/data/cache/thumb/86/4d13090dcfba186_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Порезать мясо на тоненькие ломтики, положить на пиццу. Маслины порезать на колечки.','https:https://st.vkuso.ru/data/cache/thumb/6a/c8031f9a8f1ce6a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Распределить сверху измельченный лук и томаты черри. Чуть-чуть посыпать солью.','https:https://st.vkuso.ru/data/cache/thumb/f3/db699cae136aaf3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Положить кусочки моцареллы. Сверху потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/2e/e2d4ac6f3af8c2e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8893,'Готовить пиццу со свининой, помидорами черри и моцареллой в духовке 25-30 минут, соблюдать температуру 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/9e/f293669c5e92d9e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8894,'Измельчить зелень.','https:https://st.vkuso.ru/data/cache/thumb/0f/e511a0d82ff620f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8894,'Соединить горчицу и сметану.','https:https://st.vkuso.ru/data/cache/thumb/5c/f1df09fe4155d5c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8894,'Добавить зелень, размешать.','https:https://st.vkuso.ru/data/cache/thumb/e0/7411e14e7d3f9e0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8895,'Подготовить продукты. Крупно потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/f2/bb44d18a7df7bf2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8895,'Крупно потереть сливочное масло.','https:https://st.vkuso.ru/data/cache/thumb/be/512226dea2f25be_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8895,'Пока не растаяло масло, быстро замесить сырное тесто. Раскатать тонко. Порезать тесто на полоски.','https:https://st.vkuso.ru/data/cache/thumb/9f/3448ac1d3bbf59f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8895,'Положить полоски на противень. Посыпать кунжутом.','https:https://st.vkuso.ru/data/cache/thumb/6c/61f166ee511a66c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8895,'Готовить в духовке 7-8 минут, соблюдать температуру 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/2f/1403f0b224e832f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Почистить бананы, размять вилкой в глубокой посуде.','https:https://st.vkuso.ru/data/cache/thumb/64/42b33241dd3c064_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Насыпать сахар, добавить слегка взбитое яйцо, мягкое сливочное масло. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/60/95d8a672f220560_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Отдельно соединить остальные сухие продукты: соль, дрожжи, муку, соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Добавить в банановую смесь.','https:https://st.vkuso.ru/data/cache/thumb/e8/a403e8a192b5ae8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Намазать сливочным маслом формочки, присыпать мукой. Нагреть духовку до 190 градусов. Наполнить формочки тестом.','https:https://st.vkuso.ru/data/cache/thumb/53/6c382443611b653_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Выпекать 20-25 минут. Достать из духовки, чуть-чуть остудить.','https:https://st.vkuso.ru/data/cache/thumb/b7/3f0f1aaf86054b7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Достать из формочки, положить на полотенце до полного остывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8896,'Украсить банановые маффины глазурью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Отварить в соленой воде свинину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Порезать отваренное мясо на средние квадратики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Порезать лук на полукольца, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Слить жидкость с ананаса, порезать мелко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Порезать оливки на кружочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Соединить оливки, мясо, лук, кукурузу, ананасы. Заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8897,'Размешать продукты, дать салату с кукурузой, свининой и ананасом настояться в холодильнике несколько часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8898,'Подготовить продукты. Нашинковать капусту соломкой.','https:https://st.vkuso.ru/data/cache/thumb/d7/9ad947bee80c5d7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8898,'Насыпать щепотку соли, перца. Добавить соевый соус, половину ложечки сладкой паприки. Перемешать руками, чтобы капуста выделила сок. Отставить на 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/37/b3eb37a26c99437_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8898,'Порезать томат и колбасу.','https:https://st.vkuso.ru/data/cache/thumb/a4/0cec242c8970fa4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8898,'Положить к капусте.','https:https://st.vkuso.ru/data/cache/thumb/0a/171120339225f0a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8898,'Заправить салат из пекинской капусты и колбасы с паприкой оливковым маслом. Добавить зелень, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8899,'Подогреть молоко до теплого состояния, вылить в большую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8899,'Положить дрожжи, насыпать ложку сахара, размешать венчиком, накрыть полотенцем, отправить в тепло на 10-15 минут.','https:https://st.vkuso.ru/data/cache/thumb/ae/864138f0ffb5aae_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8899,'Взбить яйца. Добавить яйца, соль, муку, оставшийся сахар в молоко. Перемешать до однородности. Накрыть посуду, отставить на полтора часа, чтобы тесто увеличилось.','https:https://st.vkuso.ru/data/cache/thumb/41/1ed2747ec637d41_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8899,'Нагреть на сковороде растительное масло, положить ложкой оладьи на сковороду, обжарить со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/76/2b2eb71f8deaa76_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Растопить сливочное масло, обжарить лук на сковороде. Положить чеснок, готовить пару минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Вымыть грибы, отделить ножки и шляпки.','https:https://st.vkuso.ru/data/cache/thumb/fc/fbb7603d66b49fc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Соединить сыры, посыпать перцем и солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Соединить золотистый лук и сырную начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Наполнить шляпки грибов.','https:https://st.vkuso.ru/data/cache/thumb/14/0a5b29d10106514_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Порезать бекон на узкие полосочки, завернуть грибы. Зафиксировать шпажками.','https:https://st.vkuso.ru/data/cache/thumb/3f/0234bf62df8953f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8900,'Готовить в горячей духовке или на гриле до готовности бекона. Во время готовки поливать фаршированные грибы портобелло в беконе соусом.','https:https://st.vkuso.ru/data/cache/thumb/c1/d4a18db4e5254c1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Положить в сотейник все продукты. Можно использовать обычный сахар или сахарную пудру.','https:https://st.vkuso.ru/data/cache/thumb/17/cbcb0901356cd17_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Мед можно заменить сиропом глюкозы.','https:https://st.vkuso.ru/data/cache/thumb/98/68255de4ad4b498_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Держать на огне, помешивая, пока не растопится масло, и не смешаются ингредиенты. Довести массу до температуры 122-123 градуса.','https:https://st.vkuso.ru/data/cache/thumb/a4/0edaa74282751a4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Выложить карамель в форму, застеленную пергаментом. Использовать форму с бортиками, высота не должна превышать 1-1,5 сантиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Спустя 3 часа отправить карамель в холодильник, чтобы она схватилась.','https:https://st.vkuso.ru/data/cache/thumb/8f/12a7903f6d6cc8f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8901,'Мокрым ножом порезать карамель. Если карамель очень застыла, то нагреть нож в кипятке. Можно посыпать конфеты миндальной мукой, пудрой.','https:https://st.vkuso.ru/data/cache/thumb/11/e06a11bd189c511_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8902,'Очистить и слегка проварить (если необходимо) для начинки грибы, процедить, порезать и обжарить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8902,'Сделать в каждой подготовленной и обсушенной грудке разрез в виде глубокого кармашка для наполнения его начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8902,'Вложить в каждый кармашек ломтики сыра, потом грибы и опять пластинки сыра, добавить нашинкованную мелко петрушку, чуть-чуть поперчить, сбрызнуть оливковым маслом, аккуратно завернуть в фольгу, поместить в нагретую до 190 градусов  духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8902,'Запеченная грудка индейки с  сыром и грибами будет готова примерно через полчаса. Перед подачей каждую грудку прямо в фольге переложить на тарелку (фольгу приоткрыть) и украсить веточками петрушки и зеленым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8903,'Рис промыть в нескольких водах, последняя должна стать прозрачной. Залить теплой водой для набухания на некоторое время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8903,'Стенки мультиварки смазать сливочным маслом. Выложить рис, влить кипяченую воду, молоко, сахар и соль добавить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8903,'Ингредиенты перемешать, закрыть крышку и выставить режим «Молочная каша».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8904,'Хорошо промыть рис и выложить в мультиварочную чашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8904,'Промыть изюм в подогретой воде, отжать излишки влаги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8904,'Переложить в чашу, добавить воду, молоко, сливочное масло, соль и сахарный песок, массу перемешать, закрыть крышку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8904,'Выставить режим «Молочная каша».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8905,'Курагу промыть, нарезать кубиками. Промыть изюм и рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8905,'Все ингредиенты переложить в чашу, залить водой, добавить топленое молоко, выставить режим «Каша» или «Молочная каша».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8905,'Готовое блюдо перемешать, потомить еще 10 или 15 минут в режиме «Подогрев».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8906,'Помыть в кипятке и обсушить лимоны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8906,'Острым ножом для овощей, а лучше специальным, аккуратно (без белой кожуры) срезать цедру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8906,'Переложить кожуру в банку, залить водкой, закрыть крышкой. Поставить на 10 дней в прохладное темное место. Периодически содержимое банки необходимо встряхивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8906,'Через 10 дней сварить обычный сахарный сироп и остудить его.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8906,'Смешать процеженную водочную настойку и сироп, перелить обратно в банку, настаивать ликер «Лимончелло» по-домашнему минимум месяц, но для лучшего вкуса – больше. Подавать к столу ликер лучше охлажденным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8907,'Сложить в чашу мультиварки пропаренный рис, сливочное масло, посолить и залить водой. Варить в режиме «Гречка» или «Крупа».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8907,'После окончания приготовления влить в кашу прогретые сливки, всыпать тертый сыр, перемешать и прогреть блюдо под крышкой в течение пяти или семи минут в режиме «Подогрев».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8908,'Цветную капусту и брокколи разобрать на соцветия.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8908,'Молодой кабачок нарезать кубиками, стручковую фасоль – кусочками, сладкий болгарский перец – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8908,'Добавить консервированную кукурузу, свежий или замороженный зеленый горошек, нарезанные зубчики чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8908,'Овощи переложит в мультиварку, добавить заранее промытый рис, специи, соль – по вкусу. По желанию положить кусочек сливочного или топленого масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8908,'Влить воду, она должна покрыть продукты на один сантиметр, закрыть крышку, выставить режим «Крупа», «Рис» или «Гречка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Варить коричневый рис или басмати (3 чашки воды на 1 чашку риса) пока вода полностью не впитается в продукт. Снять кашу с огня, оставить для остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Морковь очистить и нарезать небольшими кубиками, таким же образом нарезать сладкий болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'На сковороде разогреть небольшое количество оливкового масла, положить морковь и перец, добавить острый перец чили, подлить соевый соус. Тушить в течение нескольких минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Пропустить через пресс чеснок, накрошить очищенный имбирь, то и другое добавить в сковороду, немного обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Капусту кале или савойскую нарезать, положить в обжарку, сбрызнуть смесь оливковым маслом, тушить 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Следующий ингредиент – грибы, продукт вымыть и нарезать, добавить в сковороду, прогревать две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Лук-репку нарезать, всыпать в овощную смесь вместе с кунжутными и тыквенными семечками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8909,'Через две минуты добавить рис и соевый соус. Тушить блюдо до готовности, рис должен впитать все овощные соки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8910,'Для начинки необходимо отварить яйца в течение 20 минут. Затем очистить их от скорлупы и разрезать на две ровные половинки вдоль. Белки отложить в сторону, а желтки соединить с тертым сыром, вареной морковью и чесноком. Все тщательно перемешать и добавить немного сметаны или майонеза. Теперь этой начинкой заполнить белки и соединить их в форму яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8910,'Фарш для котлет приготовить обычным образом: в фарш добавить измельченный лук и размоченный в воде хлеб, посолить по вкусу. Этот фарш необходимо отбить, чтобы уплотнить консистенцию. Всю массу кидать на стол 15-20 раз. Таким образом, из мяса выделяется белок, что помогает скрепить наши котлеты во время приготовления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8910,'Из отбитого фарша лепим зразы. Для этого отщипнуть небольшую часть фарша, размером с кулак, распределить на ладони и поместить в середину лепешки фаршированное яйцо. Затем соединить фарш со всех сторон, сформировав котлету. Взбить яйца и обмокнуть в него готовые котлеты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8910,'Теперь можно придать форму нашим «ежикам». Для этого немного вытянуть мордочку, приподняв вверх, и сделать глазки и носик из кусочков маслин или перца горошка. По всей поверхности котлетки воткнуть тонкую вермишель, чтобы дополнить образ съедобного «ежика».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8910,'Зразы выложить на противень, смазанный маслом и запечь в духовке 40-50 минут. Чем тоньше слой фарша, тем меньше времени требуется на приготовление. Готовые зразы «Веселые ежики» подавать горячими, с гарниром из картофеля и свежих салатных листьев.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8911,'Шоколад растопить на водяной бане. Учитывать, что черный горький шоколад придаст печенью такой же горьковатый вкус, а молочный шоколад смягчит вкус печенья и сделает его более нежным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8911,'Для теста просеять муку и соединить с сухими ингредиентами: разрыхлителем, солью и корицей. Яйца взбить с сахаром в пену. Затем, продолжая взбивать, ввести очень аккуратно растопленный шоколад. Когда масса станет однородной, всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8911,'Взбивать миксером или венчиком. Консистенция теста должна быть гуще, чем сметана. Готовое тесто поставить на холод на ночь, минимум на 2 часа. Когда тесто охладится, можно выпекать печенье. Разогреть духовку, противень застелить бумагой для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8911,'Из теста скатать шарики, размером с грецкий орех, выложить на противень на расстоянии 5-7 см и щедро посыпать сахарной пудрой. Поставить в духовку на 15 минут. Выпекать при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8911,'Во время выпечки тесто расплывется, и печенье приобретет плоскую форму. Готовность проверить спичкой, если спичка сухая, значит пора доставать. Шоколадное печенье с корицей остудить и можно подавать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Подготовить тунца. Если используется целая, замороженная рыба, то разморозить ее, почистить, вымыть, отрезать голову, плавники, порезать на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Почистить и порезать картофель на кубики приблизительно 1 на 1 сантиметр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Почистить и порезать морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Почистить и порезать лук на полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Вымыть стручковую фасоль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'На дно формочки налить растительное масло. Положить первый слой – ½ лука.','https:https://st.vkuso.ru/data/cache/thumb/43/122cb7448cdee43_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'На лук положить второй слой – кусочки рыбы.','https:https://st.vkuso.ru/data/cache/thumb/3c/344e23c80e9683c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Положить ½ картофеля и моркови.','https:https://st.vkuso.ru/data/cache/thumb/bc/26a7ad08fd922bc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Последний слой – стручковая фасоль.','https:https://st.vkuso.ru/data/cache/thumb/51/5f0d0c642374751_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Повторить аналогичные действия, но без тунца. Положить слоями оставшийся лук, картофель, морковь, фасоль.','https:https://st.vkuso.ru/data/cache/thumb/c5/8b07b5b24bf2ec5_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Посыпать блюдо перцем, солью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Положить лавровый лист, майонез.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8912,'Накрыть фольгой или крышкой, готовить в духовке приблизительно 60 минут. Получается очень вкусный запеченный тунец со стручковой фасолью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Сделать бисквит. Просеять муку и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Растопить шоколад (120 г). Желательно использовать темный шоколад, который содержит более 70 процентов какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Взбить масло (170 г) и сахар на средней скорости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Сахар желательно использовать коричневый, тогда торт будет ароматнее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Непрерывно взбивая, добавить желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Добавить в масляно-яичную массу положить шоколад.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Подмешать молоко и мучную смесь. Размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Взбить до пиков соль, белки, лимонную кислоту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Подмешать взбитые белки к шоколадному тесту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Подготовить форму диаметром 23 сантиметра или несколько форм диаметром 20 сантиметров.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Намазать форму маслом, постелить пергамент.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Налить в форму тесто. Готовить 35-40 минут, соблюдать температуру 180 градусов. Проверять готовность зубочисткой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Остудить бисквит в формочке. Снять форму, перевернуть бисквит на решетку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Можно хранить бисквит 3 дня в холодильнике, завернув в фольгу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Сделать шоколадный крем. Растопить шоколад, 200 миллилитров сливок довести до кипения.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Вылить сливки в шоколад, перемешать. Налить 200 миллилитров холодных сливок, размешать. Накрыть емкость пленкой, отправить в холодильник на 3-4 часа. Взбить.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Сделать крем для покрытия. Растопить шоколад.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Добавить в шоколад мед, перемешать.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Довести до кипения сливки, вмешать в шоколад. Охладить массу, положить мягкое масло.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Взбить до однородности, отправить в холодильник на несколько часов.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Собрать торт. Коржи можно разделить вдоль на две части, каждую обильно намазать шоколадным кремом.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Крем для покрытия взбить, намазать им верх и бока торта.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8913,'Отправить Шоколадный бисквитный торт «Пища Дьявола» в холодильник на пару часов.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Насыпать в кастрюлю промытый рис, залить 3 кружки воды. Довести до кипения, уменьшить огонь, готовить 30-35 минут. Если осталась жидкость – слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Подсушить на сковороде орехи пекан, семечки и грецкие орехи 4-5 минут. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Взбить в блендере овсяную крупу, положить семечки и орехи, взбивать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/6f/ac07c0851c6a96f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Добавить специи, чеснок, отваренный рис, лук, яйцо, взбивать до состояния фарша.','https:https://st.vkuso.ru/data/cache/thumb/03/1d1068b5f137903_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Намочить руки холодной водой, поделить фарш на 8 частей. Скатать шарики, сделать лепешки. Можно хранить в холодильнике.','https:https://st.vkuso.ru/data/cache/thumb/4f/ef6e0e87664c14f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Порезать красный лук на кольца. Готовить на сковороде или гриле, посыпав щепоткой сахара и соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Нагреть на гриле или сковороде растительное масло. Обжаривать котлеты с каждой стороны по 6-8 минут. Положить на котлеты по тоненькому ломтику сыра.','https:https://st.vkuso.ru/data/cache/thumb/18/99b790a1bff7b18_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8914,'Намазать хлеб растительным маслом, обжаривать по несколько минут с каждой стороны. Собрать вегетарианские бургеры с рисовыми котлетами.','https:https://st.vkuso.ru/data/cache/thumb/b9/dea98cd578721b9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Нагреть масло в большом сотейнике, обжаривать 1 минуту измельченный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Добавить остальные ингредиенты для соуса, кроме воды, размешать.','https:https://st.vkuso.ru/data/cache/thumb/af/a508141f827caaf_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Налить воду, перемешать, довести до кипения. Томить на тихом огне 15-60 минут, в зависимости от необходимой консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Убрать соус с огня, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Соединить 150 грамм сыра и 60 миллилитров соуса, размешать.','https:https://st.vkuso.ru/data/cache/thumb/28/1b4c08aee3c2928_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Подогреть лепешки в микроволновке до мягкого состояния. Начинить лепешки сырной массой.','https:https://st.vkuso.ru/data/cache/thumb/a7/97e9b6a86c5afa7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Свернуть плотные роллы, положить швом вниз в форму. Налить чуть-чуть соуса.','https:https://st.vkuso.ru/data/cache/thumb/a5/0be18392e32b3a5_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Посыпать сыром. Посыпать измельченным зеленым луком, оливками.','https:https://st.vkuso.ru/data/cache/thumb/0a/89fdb883f78fe0a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8915,'Готовить 20 минут, соблюдать температуру 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Намазать маслом форму диаметром 24 сантиметра. Порезать картофель на ломтики, положить в форму. Посыпать солью.','https:https://st.vkuso.ru/data/cache/thumb/5e/097e48532072d5e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Отдельно взбить яйца, черный перец, соль.','https:https://st.vkuso.ru/data/cache/thumb/21/63e9dd4376f0a21_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Положить сметану, взбить венчиком.','https:https://st.vkuso.ru/data/cache/thumb/68/921dbe47abc1968_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Порезать ½ лука-порея на тоненькие кольца. Можно заменить его на репчатый лук.','https:https://st.vkuso.ru/data/cache/thumb/ec/540c3b06598b4ec_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Порезать на кубики сыр эдам, сыр фета, потереть, соединить с луком, положить все в емкость со сметаной. Размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Залить смесью картофель.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Порезать помидоры на тоненькие клинья. Положить сверху.','https:https://st.vkuso.ru/data/cache/thumb/75/1b5c8ea4d406675_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8916,'Готовить картофельную тортилью с сыром и луком 40 минут, соблюдать температуру 175 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Подготовить продукты. Порезать цукини на тоненькие кружки.','https:https://st.vkuso.ru/data/cache/thumb/a2/6b3ff14ec67afa2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Порезать лук на очень тоненькие кольца.','https:https://st.vkuso.ru/data/cache/thumb/96/c3f401efb671896_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Крупно потереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/5e/569fe0e8c2ee95e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Взбить в глубокой емкости яйца, чтобы получилась пышная пена.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Соединить муку, перец, соль и другие приправы.','https:https://st.vkuso.ru/data/cache/thumb/ca/87f1f8237009dca_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Перелить взбитые яйца в емкость побольше. Насыпать муку, размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Налить молоко, перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/86/c4839889cda3f86_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Добавить растительное масло, перемешать венчиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Добавить дижонскую горчицу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Положить тертый сыр. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/24/73a0b572047f524_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Добавить в тесто лук и цукини. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/36/fe2717ac1e5b936_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8917,'Выложить массу в форму, смазанную маслом. Готовить 35-40 минут, соблюдать температуру 200 градусов. Дать простой запеканке из цукини чуть-чуть остыть.','https:https://st.vkuso.ru/data/cache/thumb/09/2499a92bf7f9609_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Начинать необходимо с крема, так как ему необходимо будет время для остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Снять полосками цедру с лимона, выжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Соединить желтки, сахар, крахмал, молоко. Держать на медленном огне. Довести до кипения, помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Положить цедру, налить сок, варить, пока не загустеет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Положить шоколад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Остудить крем, накрыть пленкой. Отправить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Приготовить коржи: взбивать 5 минут белки, яйца и полстакана сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'В конце добавить 2 большие ложки растительного масла, маленькую ложку ванильной настойки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Соединить соль, муку, молотый мак, пекарский порошок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Осторожно, складывая, перемешать сухую смесь и взбитые яйца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Перелить на лист, застеленный специальной бумагой, распределить равномерно, готовить 7-8 минут, соблюдать температуру 200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Достать корж, накрыть листом бумаги, полотенцем, остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Убрать верхний лист, с ним снимется тоненькая пленка.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Разрезать поперек на три части.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Взбить сливки, положить желтковый крем и тертый шоколад.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8918,'Собрать маково-сливочный торт «Царица Эстер».',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8919,'Яйца взбить, влить кефир, всыпать сахар, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8919,'Перемешать муку, разрыхлитель и соду и всыпать эту смесь в кефирно-яичную массу, перемешать, добавить предварительно растопленное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8919,'Из получившегося теста испечь на горячей сковородке оладьи, которые нужно переворачивать после того, как на всей поверхности появятся пузырьки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8919,'Готовые королевские панкейки на кефире полить сладким вишневым соусом, вареньем или посыпать сахарной пудрой и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8920,'Смешать говяжий фарш с измельченным в крошку хлебом, мелко порубленным луком, яйцом, присолить, поперчить, переложить и разровнять одинаковым по толщине слоем по поверхности пищевой пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11726,'На небольшом огне поджариваем,переворачиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8920,'Измельчить на крупной терке сыр, ветчину нарезать на полоски. Включить на разогрев до 350 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8920,'Разложить по поверхности слоя фарша равномерно кусочки ветчины, присыпать измельченным сыром, завернуть осторожно в рулет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8920,'Положить рулет в форму (смазать предварительно ее маслом), отправить в горячую духовку. Мясной рулет «Кордон блю» с ветчиной и сыром будет запекаться примерно час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Соединить в емкости сахарную пудру, муку и цедру апельсина. В центр смеси вбить яйцо.','https:https://st.vkuso.ru/data/cache/thumb/50/10d7a9f1adeec50_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Замешивать тесто, медленно добавлять ½ молока. Размешивать, пока не исчезнут комки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Налить растопленное масло и остальное молоко. Размешать, отставить на 30 минут. Должна получиться консистенция, как сливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Выпекать средние по размеру блины.','https:https://st.vkuso.ru/data/cache/thumb/4d/c90d1b6b024884d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Приготовить соус: соединить сок лимона и апельсина, добавить ликер и цедру лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Вылить смесь на холодную сковороду, насыпать сахарную пудру. Нагреть на тихом огне, помешивая, пока не растворится пудра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Положить сливочное масло. Мешать, пока не растворится масло. Варить 3-4 минуты на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/3d/40985adcdde423d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Положить блин в соус, обвалять со всех сторон, сложить в 4 раза, отодвинуть к краю сковороды. Таким образом, поступить с 4 блинами.','https:https://st.vkuso.ru/data/cache/thumb/97/52a13f36d1de797_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Прибавить огонь, подогревать блины 1 минуту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Побрызгать блинчики коньяком, поджечь свечкой или длинной спичкой – фламбировать. Сразу убрать с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8921,'Выложить теплые блинчики «Сюзетт» с апельсиново-лимонным соусом на тарелку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'Порезать грудку на маленькие кубики.','https:https://st.vkuso.ru/data/cache/thumb/d2/f410c48a127d7d2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'Снять кожуру с помидоров, порезать мякоть на кубики.','https:https://st.vkuso.ru/data/cache/thumb/dd/20baa25c3ce35dd_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'Нагреть на сковороде чуть-чуть оливкового масла. Обжаривать бекон 3-4 минуты. Положить к грудинке измельченный лук, обжаривать несколько минут.','https:https://st.vkuso.ru/data/cache/thumb/56/94aed176354b056_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'Отварить спагетти аль-денте – вытащить немного раньше. Откинуть спагетти на дуршлаг.','https:https://st.vkuso.ru/data/cache/thumb/a1/cf2f89e8bbbe1a1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'К хорошо обжаренной грудинке с луком добавить порезанные помидоры. Посыпать перцем, солью, готовить 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/27/33648ace284df27_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8922,'Положить в сковороду спагетти, размешать, подогревать несколько минут на тихом огне, убрать с плиты. Подавать пасту Аматричиана по-итальянски сразу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8923,'Отварить картофель и морковь, остудить, очистить, нарезать маленькими кубиками. Включить разогреваться до 380 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8923,'Взбить венчиком яйцо, добавить, не прекращая взбивать масло, йогурт, постепенно всыпать смесь муки с разрыхлителем. Все аккуратно и тщательно смешать, добавить измельченные овощи, мелко нашинкованную зелень и базилик, присолить, поперчить, перемешать осторожно еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8923,'Смазать хлебную форму маслом, переложить смесь и запекать до образования сверху хлеба золотистой корочки (примерно около часа).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8923,'Картофельно-морковный  хлеб с зеленью подается к столу охлажденной, украсить веточками петрушки и базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Растирать желтки и сахар миксером несколько минут.','https:https://st.vkuso.ru/data/cache/thumb/37/61f331af13a8337_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Добавить сливки, чуть-чуть взбить, чтобы продукты перемешались.','https:https://st.vkuso.ru/data/cache/thumb/ac/fcbdefcdd728aac_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Вылить массу в посуду, поставить на водяную баню. Помешивать, чтобы масса не закипела. Готовить 10-15 минут. Можно налить в крем несколько ложек сливок или молока, чтобы он сильно не нагревался, или на полминуты убрать емкость с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Поставить посуду со сливочно-яичной массой в холодную воду. Несколько минут остужать, помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Положить кусочки банана, взбить до однородности.','https:https://st.vkuso.ru/data/cache/thumb/48/816fdd5e688a848_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Добавить крупно порубленные, обжаренные орехи и шоколад, поломанный на крупные куски.','https:https://st.vkuso.ru/data/cache/thumb/f0/30644327c4b67f0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Перелить массу в специальный контейнер для замораживания, отправить в морозилку, чтобы мороженое застыло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8924,'Во время замораживания желательно шоколадно-банановое мороженое с грецкими орехами несколько раз перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8925,'Все фрукты, которые используются, требуют очистки от кожуры и семян. Яблоки и айву очистить и порезать на маленькие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8925,'Закипятить 1,5 литра воды и высыпать яблоки и ягоды клюквы. Варить на медленном огне 45 минут. Отдельно варить в 1,5 литрах воды айву.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8925,'Через сито с марлей, сложенной в 6 слоев, процедить ягодный отвар. Затем этот сок процедить повторно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8925,'2 литра получившегося сока разбавляем 1 килограммом сахара. Довести до кипения, затем варить, снимая пенку на очень медленном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8925,'Заливать желе «Райский сад» в стерильные банки, укутать в плед на ночь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8926,'Очистить картофель и порезать его на тонкие кружочки. Форму для запекания смазать маслом и посыпать давленым чесноком. Иногда для аромата достаточно смазать зубком чеснока стенки формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8926,'Выложить ровные слои картофеля, красиво накладывая их друг на друга. В разрезе будет виден этот процесс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8926,'Для заливки необходимо смешать сливки, яйца, мускатный орех, соль и перец. Залить картофель, сверху щедро посыпать тертым сыром. На сыр положить маленькие кусочки сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8926,'Поставить картофель в духовку на 50 минут при температуре 200 градусов. Когда появится румяная корочка, картофель «Дофине» готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8926,'Перед подачей посыпать рубленым зеленым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8927,'Из семги отделить филе, промыть и просушить бумажным полотенцем. Выложить на тарелку кожей вниз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8927,'Теперь приступим к засолке. Посыпать солью рыбу, затем выложить слой лимонных долек и посыпать рубленым укропом. Затем необходимо сложить две половинки рыбы так, чтобы маринад остался внутри, а кожа рыбы была сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8927,'Завернуть семгу в пищевую пленку и положить в холодильник на сутки. Через данное время рыбу промыть и просушить. Готовую малосольную семгу хранить в холодильнике под пищевой пленкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8928,'Отбить куски свинины в тонкие пласты. Шпинат обжарить на сливочном масле с добавлением лука порея. Через 15 минут тушения, посыпать шпинат мускатным орехом и посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8928,'Измельчить отварную куриную грудку с чесноком и сыром до однородного состояния.  На свиную отбивную нанести слой шпината, затем полить сверху куриной смесью. Свернуть рулетик и заколоть для надежности зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8928,'Разогреть сковороду, налить пару ложек растительного масла и обжарить рулеты до образования золотистой корочки. Пока жарятся рулеты, приготовить подливу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8928,'Томаты обдать кипятком и снять кожицу. Нарезать маленьким кубиком томаты и морковь. Жарить на раскаленной сковороде овощи с добавлением тимьяна, давленого чеснока. Когда томаты приобретут приятную корочку, добавить белое вино и тушить еще 5 минут. Эту смесь измельчить в блендере до однородной консистенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8928,'Рулеты из мяса со шпинатом выложить на противень, полить томатной подливой и поставить в духовку на 30 минут при температуре 180 градусов. Подавать со спагетти или картофельным пюре. Также в подачу включить свежие овощи и зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8929,'В миске смешать сухие ингредиенты: муку с разрыхлителем, солью, корицей и мускатным орехом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8929,'В чаше соединить мягкое масло, сахар, яйцо, ванилин и банан, блендером взбить. В эту массу добавить сухие продукты и вымесить тесто до консистенции густой сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8929,'Разогреть духовку, формы для кексов смазать сливочным маслом. Каждую формочку наполнить тестом на 3/4 и поставить в духовку для выпекания. Пончики выпекать 12-15 минут при температуре 170-180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8929,'Пока пекутся пышки, следует приготовить присыпку. Сахар смешать с корицей, сливочное масло растопить в духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8929,'Готовые банановые пончики остудить, затем каждый окунуть в сливочное масло и обвалять в сахарной смеси.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Приготовить тесто: соединить масло, муку, соль, разрыхлитель. Вымесить тесто, положить сыр, бекон, посыпать перцем, солью. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8930,'Отобрать картофель среднего размера, тщательно вымыть. Смешать муку и соль в целлофановом пакете, туда выложить мокрый картофель и хорошо встряхнуть пакет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8930,'Духовку разогреть до 200 градусов. Выложить мучной картофель на противень и поставить запекаться на 1 час. Готовность проверять спичкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8930,'Готовый картофель следует начинить смесью из пряностей и трав. Для этого каждую картошечку следует разрезать вдоль, не дорезая до конца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8930,'Для начинки смешать творог с чесноком. В разрезанный печеный картофель вложить ложку начинки и посыпать сверху рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8931,'Дрожжи развести в теплой воде, добавить соли и немного сахара. Яйцо взбить с сахаром, маргарин растопить на водяной бане. Соединить все ингредиенты, добавить муку и вымесить очень мягкое послушное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8931,'Поставить в теплое место для подъема. Тесто должно подойти 3 раза, затем лепим пышки. Все тесто разделить на шарики размером с яйцо. Дать подойти им в течение 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8931,'Затем шарики раскатать в рулет и соединить в кольцо. Раскалить сковороду, налить растительное масло, жарить с двух сторон до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8931,'Готовые ленинградские пышки выложить на бумажное полотенце и дать остыть. Посыпать сахарной пудрой перед подачей к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8932,'Ягоды можно использовать свежие и мороженые. Смородину следует взбить блендером в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8932,'Яйцо взбить с сахаром, добавить мягкое масло, взбитые ягоды и муку. Цвет теста становится очень красивым, из него будем лепить формовое печенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8932,'Готовое тесто положить в холодильник на 30 минут, а тем временем включить духовку и приготовить формочки для печенья. Раскатать охлажденное тесто в пласт и выдавить фигурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8932,'Противень застелить бумагой, выложить лиловое печенье и поставить выпекать в духовку на 15 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Мякоть или филе свинины нарезать кусочками, накрыть пищевой пленкой, сильно отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Снять пленку, каждый кусочек натереть солью, перцем и снова чуть отбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Подготовленное мясо переложить в емкость, всыпать специи для шашлыка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'В миску с мясом положить нарезанный небольшими кусочками лук, сильно помять его вместе с мясом и оставить все на 2 часа мариноваться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Примерно за 1 час до приготовления шашлыка в отдельной емкости замариновать лук. Для этого нужно нашинковать лук полукольцами, сложить в миску, залить кипятком. Далее влить туда уксус, всыпать сахар, соль, при желании добавить сок лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Противень застелить бумагой для выпечки, отрезать рукав для запекания по длине немного большей противня, одну сторону завязать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Выложить в рукав замаринованный лук, аккуратно его распределить, сверху выложить подготовленное мясо, но не перемешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Второй конец рукава завязать, сделать сверху несколько проколов, поместить противень в предварительно разогретую духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Запекать шашлык из свинины в духовке на луковой «подушке» в течение часа — полтора на максимальной температуре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8933,'Готовый шашлык достать из рукава, выложить на блюдо и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'Тесто для пирога готовить при помощи миксера. Взбить масло с сахаром в воздушную массу. Затем добавить к маслу желток и молоко с ванилином. Взбивать 5 минут, затем всыпать муку. Вымесить наливное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'Для приготовления сырной начинки следует взбить миксером сливочный сыр с сахаром, добавить яйцо и желток. Взбивать до пышной массы. Для аромата всыпать ванилин. Крем поставить в холодильник на 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'Для коричневых шариков необходимо соединить все ингредиенты и вымесить руками в однородную массу, затем слепить шарики размером с грецкий орех.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'Духовку разогреть до 180 градусов. Форму для выпечки смазать сливочным маслом. Вылить половину теста, разровнять ложкой. Затем выложить сырную начинку. Оставшуюся часть теста соединить с коричневыми шариками, вылить в форму на сырную начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9615,'Лаваш намазать несладким йогуртом, майонезом или сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'Поставить пирог в духовку на 50 минут и выпекать при температуре 180 градусов. Готовый пирог с сырной начинкой и корицей следует остудить, затем поставить в холодильник на 3-4 часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8934,'В это время приготовить сырную глазурь. Взбить сыр и масло миксером в однородную массу. Добавить ванилин и сахар, взбить. Охлажденный пирог смазать глазурью и подавать к чаю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Для приготовления основы необходимо взбить блендером сливочное масло с сахаром. Продолжая взбивать, добавить яйца и крошку печенья. Затем ввести муку. Тесто получится песочной консистенции, его необходимо выложить в форму для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Чтобы корж хорошо снялся, выпекать необходимо на кальке или фольге. Основу выпекать 15 минут при температуре 200 градусов. Песочный корж вынуть из духовки и охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Для приготовления лимонной начинки следует взбить желтки в пену. Когда желтки побелеют, ввести молоко, взбивать 5 минут. Затем влить лимонный сок и продолжить взбивание 30 секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Начинку вылить в форму на охлажденную основу, выпекать 10 минут, пока начинка не «схватится». Затем охладить. Готовая часть пирога должна постоять на холоде в течение 4 часов. Для этого обернуть пищевой пленкой форму и убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Теперь стоит заняться меренгой. Закипятить стакан воды, высыпать 2 ложки сахара и вылить кукурузный сироп. Довести смесь до кипения. Взбить белки в крепкую пену, затем постепенно всыпать сахар и влить холодный сироп. Взбивать 5-7 минут до пышной консистенции всей массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8935,'Готовую меренгу выложить на готовые коржи. Разровнять лопаткой поверхность и поставить в горячую духовку на 2 минуты. Когда появится румяная корочка, пирожные с лимонной начинкой и меренгой готовы. Теперь необходимо остудить и нарезать на порционные кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8936,'В сковороде с толстым дном обжарить лук и чеснок на оливковом масле. Так как блюдо будет готовиться в сковороде, поэтому стоит выбирать глубокую посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8936,'Когда лук обжарится, высыпать тертую морковь. Тушить, помешивая 5 минут. Затем в сковороду высыпать чечевицу, влить бульон и добавить сахар. Сковороду накрыть крышкой и тушить чечевицу 20 минут, периодически помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8936,'В миске смешать бальзамический уксус, тимьян, соль и перец, прогреть на огне 30 секунд. В готовую кисло-сладкую чечевицу добавить смесь из уксуса и трав, хорошо перемешать и накрыть крышкой, чтобы блюдо пропиталось ароматом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8937,'Растереть сливочное масло с сахаром. Затем добавить яйца по одному, продолжая взбивать миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8937,'Муку просеять и соединить с разрыхлителем и солью. Все смешать и вымесить густое тесто, но довольно мягкое и послушное.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8937,'Изюм запарить в кипятке на 15 минут, затем просушить, добавить в тесто. Ложкой наполнить формы для кексов тестом и поставить в духовку на 40 минут при температуре 180 градусов, готовность проверить спичкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8937,'Румяные кексики с изюмом охладить и посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8938,'Взбить сливочное масло с сахаром в пышную массу. Затем ввести яйца по одному. В просеянную муку добавить соль и разрыхлитель. Соединить муку и масляную смесь, вымесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8938,'Сварить крепкий кофе, остудить и соединить с какао и корицей. Тесто разделить на 2 равные части. В одну добавить кофе, вымесить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8938,'Форму для кекса посыпать сухарями и выложить тесто белое и кофейное в шахматном порядке. Затем поводить по тесту ложкой, формируя хаотичный узор.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8938,'Форму поставить в духовку на 20 минут при температуре 200 градусов, затем уменьшить газ и выпекать еще 20 минут. Кофейный кекс с корицей остудить и посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8939,'Обернуть бамбуковый коврик пленкой. Положить на него половину листа нори вниз блестящей стороной. На него, сместив на сантиметр вверх, влажными руками положить готовый рис, распределить равномерно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8939,'Накрыть ковриком рис, прижать, перевернуть, раскрыть. Нори окажется наверху. Положить на нори сыр филадельфия. Сыр можно равномерно распределить по водорослям или положить дорожкой посередине будущего ролла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'Выпекать овсяные «Блонди» с медом и шоколадными каплями при 180 градусах на протяжении 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8939,'Порезать тоненькой соломкой авокадо и огурцы. Часть роллов «Филадельфия» можно приготовить с огурцом, а остальные с авокадо. Положить их в центре ролла и осторожно свернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8940,'Почистить и порезать картофель на тоненькие кружки. Лук порезать на колечки. Помыть мясо и порезать на средние брусочки. Соединить майонез и прессованный чесночок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8940,'Посыпать мясо солью, перемешать с чесночной смесью. Смешать майонез, прессованный чеснок, измельченную зелень и соль. Смешать с порезанным картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8940,'Достать противень, намазать маслом. Положить на него слоями: картофель, лук, мясо, лук, картофель. Отправить на сорок минут в духовку, соблюдать температуру 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8940,'Достать противень, посыпать потертым сыром, поставить картофель по-французски с мясом в духовку еще минут на двадцать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8941,'Нарезанный чеснок обжарить примерно 1 минуту на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8941,'Положить томатную   пасту (можно пюре из томатов), мелко нарезанный кубиками сыр фета, на  минимальном огне готовить соус в районе 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8941,'За несколько минут до готовности соуса добавить 10 листочков измельченного базилика, соль и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8941,'Перемешать предварительно отваренные макароны фарфалле с томатным соусом и сыром Фета и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8942,'Порезать шампиньоны и лук, обжарить на небольшом количестве растительного масла. Порезать на кубики окорочок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8942,'Приготовить заправку: соединить горчицу, сметанку и майонез. Перемешать все ингредиенты: лук с грибами, окорочок, морковь, заправку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8942,'Выложить на блюде салат, украсить корзинкой из тоненько порезанного сыра, сверху положить зелень для букетика и цветочки из вареной свеклы, моркови, яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8943,'Соединить масло с сахаром, перемешать миксером. Вбить яйца (по одному), насыпать по вкусу соль. Насыпать просеянную муку и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8943,'Вымесить тесто, переложить на противень, застеленный специальной бумагой. На тесто положить сливы, порезанные на две части (красиво будут смотреться сливы, выложенные сердцевиной вверх).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8943,'Готовить сливовый пирог из New York Times до румяной корочки, соблюдать температуру 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Порезать лук на полукольца, обжарить. Добавить молотый черный перец, сушеный тимьян, соль.','https:https://st.vkuso.ru/data/cache/thumb/3f/4c5495f60ccdb3f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Взять мясо без костей. Порезать на маленькие кубики, срезать жир и удалить пленку.','https:https://st.vkuso.ru/data/cache/thumb/9c/3293ee9f725399c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Положить баранину в кастрюлю, на нее выложить обжаренный лук.','https:https://st.vkuso.ru/data/cache/thumb/3c/c989e04d772cc3c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Добавить порезанный чернослив, помидоры.','https:https://st.vkuso.ru/data/cache/thumb/c3/00998b5b8130fc3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Чернослив предварительно замочить. В процессе готовки ягоды возьмут в себя жир и сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8944,'Налить два стакана воды. Выбрать режим «Тушение», готовить 2 часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8945,'Развести в воде дрожжи, насыпать половину муки. Отставить часа на два. Положить остальные продукты, последней насыпать муку. Отставить еще часа на два. Порезать тесто на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8945,'Из каждого сделать пласт, намазать творожной смесью, свернуть рулетиком. Сделать из рулета кольцо, концы скрепить, сделать надрезы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8945,'Позволить настояться изделию, намазать яйцом, готовить булочки «Солнышко» с творогом до золотистого оттенка, соблюдать температуру 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8946,'Помыть, почистить и мелко потереть морковь. Помыть апельсин, мелко потереть кожуру, не трогая белую мякоть. Вымыть курагу, мелко порезать. Соединить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8946,'Почистить от белой пленочки апельсин, поделить на дольки, порезать на небольшие куски, положить к моркови. Отдельно взбить яйца с сахаром, насыпать ванилин. Соединить муку с разрыхлителем, просеять, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8946,'Положить натертые ингредиенты, размешать до однородности. Остальные две моркови почистить порезать на тоненькие ленты, используя овощечистку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8946,'Налить в кастрюльку воду, насыпать сахар, приготовить сироп. Положить в сироп морковные ленты, варить на среднем огне минут пять. Выловить ленты шумовкой, переложить на полотенце.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8946,'Формочки намазать маслом, перелить в них тесто. Из морковных лент скрутить розочки, вставить в тесто. Намазать цветы растопленным сливочным маслом. Готовить морковно-апельсиновое пирожное минут сорок, соблюдая температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Взбить 2 яйца со стаканом сахара.','https:https://st.vkuso.ru/data/cache/thumb/cd/540497f163babcd_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Поставить на водяную баню, положить несколько ложек меда.','https:https://st.vkuso.ru/data/cache/thumb/1f/bc2c6f48ad5351f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Убрать с плиты, положить соду, маргарин. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/2e/6dc19fa6a31f22e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Насыпать муку, замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/7a/408e22bc9b49d7a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Поделить тесто приблизительно на семь частей.','https:https://st.vkuso.ru/data/cache/thumb/84/7e989e126946d84_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Тонко раскатать каждую часть, обрезать края. Сделать в коржах надрезы ножом, чтобы не вздулись. Выпекать по одному коржу в духовке.','https:https://st.vkuso.ru/data/cache/thumb/58/2a91aaed099be58_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Приготовить крем: перемешать стакан сахара, крахмал, ложку муки, растворимый кофе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Налить в смесь молоко, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Когда крем остынет, положить сливочное масло, размешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/e6/7859fc665b03ae6_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8947,'Намазать коржи кремом, посыпать крошкой от коржей, пудрой, шоколадом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Для приготовления блинного теста необходимо взбить с солью и сахаром яйцо, влить молоко и взбить смесь миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Небольшими порциями не спеша  всыпать муку, гашенную уксусом соду, при этом не переставать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Пожарить желаемое количество блинов следующим образом: на разогретую с растительным маслом сковороду влить тесто и распределить его по всей поверхности, готовым блинам дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Для того чтобы приготовить начинку для блинчиков, нужно в подсоленной воде до полной готовности отварить  картофель и затем сделать из него пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Нарезать заранее очищенные шампиньоны, мелко нашинковать репчатый лук и обжарить его до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Далее к луку надо добавить подготовленные грибы, тушить все вместе, пока не испарится вся жидкость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Луково-грибную массу хорошенько перемешать с картофельным пюре, при желании ее можно поперчить и посолить, а чтобы сделать начинку мягче и сочнее, можно перемешать ее с майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'На каждый блин выложить готовую остывшую начинку, завернуть его в трубочку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8948,'Блинчики с начинкой из картофеля и шампиньонов подавать в горячем виде, дополнив сметаной.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'На среднем огне разогреть в сковородке небольшое количество растительного или оливкового масла, обжарить в нем до золотистого цвета в течение 10 минут очищенный и порезанный на тонкие четвертинки репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Шампиньоны промыть, очистить и порезать некрупными кусочками, добавить к луку и при периодическом помешивании готовить 10-15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Луково-грибную готовую массу переложить в миску, добавить предварительно натертый сыр и сваренные вкрутую, порубленные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Все тщательно перемешать, добавить черный молотый перец и соль по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Поперек волокон нарезать свинину кусочками в 0,7-0,8 см толщиной. Каждый кусок мяса со всех сторон натереть солью и перцем, тщательно отбить их с помощью кухонного молотка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'На каждый подготовленный мясной кусок выложить примерно 2 столовые ложки готовой начинки, свернуть мясо рулетиком, обмотать ниткой или скрепить деревянными шпажками/зубочистками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'В большую сковородку влить масло и разогреть его на среднем огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Рулеты из свинины с грибами обжарить, начиная с бокового шва, с обеих сторон, после чего извлечь нить, шпажки или зубочистки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'В форму для запекания уложить обжаренные рулеты, влить жирные сливки и полтора стакана воды, добавить соль и перец.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8949,'Запечь рулеты из свинины с грибами и сыром моцарелла в течение получаса при температуре 190 градусов до зарумянивания, подавать в теплом виде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Подготовить бекон для печенья: обжарить его на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/1c/368eeeb6abe481c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Раскатать тесто в пласт приблизительно 1 сантиметр толщиной, вырезать любые фигурки: рыбки, квадраты, треугольники.','https:https://st.vkuso.ru/data/cache/thumb/20/7646f0ecc23f320_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Положить заготовки на противень, отправить в духовку на 15 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/2c/2617d0ed452bb2c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8950,'Когда фигурное печенье с сыром и беконом остынет, можно подавать его к пиву, добавить к обеду или есть, как простое печенье.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Порезать багет на кусочки по 12-15 миллиметров толщиной наискосок. Обжарить с двух сторон на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/ab/a264dbbd7bfc2ab_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Почистить чеснок, натереть им обжаренные кусочки с одной стороны.','https:https://st.vkuso.ru/data/cache/thumb/0f/e683e3da1f3130f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Намазать натертую чесноком сторону свежим оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Порезать сыр моцареллу на тоненькие пластинки по размеру, как подготовленный багет.','https:https://st.vkuso.ru/data/cache/thumb/2a/9139553506a1f2a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Испечь перец, остудить, удалить семена. Порезать перец на маленькие ломтики.','https:https://st.vkuso.ru/data/cache/thumb/bc/4fd498f02b30cbc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'На каждый кусочек подготовленного хлеба положить по кусочку сыра, разноцветный запеченный перец, листик базилика. Можно при этом соблюдать любые пропорции и последовательность.','https:https://st.vkuso.ru/data/cache/thumb/61/9992579a422ea61_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8951,'Положить бутерброды с моцареллой и болгарским перцем на тарелку и подавать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8952,'Багет дневной давности порезать на небольшие кубики, обвалять в пропущенном через пресс чесноке и сушеном базилике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8952,'Далее все подготовленные кубики переложить на противень, полить сверху растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8952,'Поместить противень в разогретую до 200 градусов духовку и выпекать до румяной корочки. И через  5-10 минут пикантные сухарики с базиликом можно подать гостям.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'В миску всыпать муку, добавить сливочное масло, щепотку соли, соду (на кончике ножа), все растереть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'Влить кислое молоко или кефир, вбить яйца, замесить тесто (мягче, чем для пельменей), постепенно подмешивая муку, оставить на некоторое время полежать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'Для начинки мелкими кубиками нарезать сырой картофель, любое мясо и репчатый лук, поперчить, посолить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'От «полежавшего» теста отщипнуть кусок, раскатать его в лепешку (не тонкую), в центр положить подготовленную начинку, защипнуть края (как у хинкали), но оставить в середине небольшое отверстие.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'На выстеленный бумагой для выпечки противень уложить все пирожки, отправить его в духовку, заранее разогретую до 200 градусов, для начала на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'По истечении этого времени внутри каждого пирожка должна появиться жидкость, как только это произойдет, в пирожки нужно положить по кусочку масла (сливочного) и поставить обратно в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'Спустя еще 20 минут бульон в пирожках должен выкипеть, а сами изделия – подрумяниться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'Теперь необходимо каждый пирожок смазать яйцом, опять вернуть противень в духовку на 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8953,'Готовые татарские пирожки с картофелем, мясом и луком сложить в контейнер, накрыть крышкой или полотенчиком, дать слегка обмякнуть, после чего, либо есть так, либо подать к супу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Подготовить продукты.','https:https://st.vkuso.ru/data/cache/thumb/39/d116c55b2e64339_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Взбить яйцо с сахаром. Насыпать просеянную муку, перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/c8/d8205f7eab1c0c8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Налить молоко, мешать, чтобы растворились комочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Добавить растительное масло. Приготовить тоненькие блины на горячей сковороде, намазанной жиром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Почистить яблоко, порезать соломкой. Насыпать сахар и корицу. Размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Порезать соломкой бананы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Промыть изюм и ошпарить кипятком.','https:https://st.vkuso.ru/data/cache/thumb/6a/5162700fa4e856a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Соединить творог и изюм. Насыпать ванильный сахар.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Положить массы на блины, свернуть каждый трубочкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Блинчик без начинки намазать взбитым яйцом. Положить на него три блина с начинками, завернуть.','https:https://st.vkuso.ru/data/cache/thumb/49/56a7138c5d3ce49_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Растопить на сковороде сливочное масло. Обжарить блин с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/5a/7e7bf2e44a8635a_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Отправить в духовку на 5 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/0d/c0708d0aa5d8d0d_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8954,'Готовые фруктово-творожные блинчики порезать и подавать со сметаной и медом. Можно украсить мятой и малиной.','https:https://st.vkuso.ru/data/cache/thumb/e5/81c91d2a7cc75e5_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8955,'Очищенные кальмары отварить  1-2 минуты в подсоленной воде, после чего нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8955,'Помидоры промыть и также как и кальмаров, нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8955,'Через чесночницу пропустить очищенный чеснок, крупно потереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8955,'Сложить в миску все ингредиенты, заправить их майонезом и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8956,'Смешать яйца, соль, сахар, йогурт или сметану, растительное масло. Чуть-чуть взбивая, насыпать дрожжи, налить теплую воду. Когда дрожжевые гранулы растворятся, по частям насыпать муку. Замесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8956,'Подготовить овощи для начинки: нашинковать красный чили тоненькими кольцами, убирая семена, лук и томаты порезать на кубики, измельчить зелень, чеснок порезать на тоненькие пластины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8956,'Обжарить на горячем растительном масле до полупрозрачного состояния луково-чесночную нарезку. Положить фарш, размешать, обжаривать минуты четыре. Положить чили, помидоры, специи, добавить томатную пасту. Размешать до однородности, тушить минут пять. На последней минуте тушения положить зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8956,'Остудить ароматную смесь. Разделить тесто на восемь одинаковых частей. Из каждой заготовки раскатать вытянутую, тоненькую лепешку. В середине распределить мясную начинку. Поднять краешки и скрепить в виде лодочки, оставлять продолговатое отверстие.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8956,'Разбить яйца, размешать, влить в открытую сердцевину по несколько больших ложек, по желанию посыпать сыром. Переложить турецкую пиццу «Pide»  на противень, застеленный специальной бумагой, намазать яичной смесью бортики, готовить минут 35, соблюдать температуру 180 градусов, предварительно разогрев духовку до 220 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8957,'Сварить в соленой воде вермишель, слить воду. Не промывать, заправить растительным маслом, не имеющим запах, чтобы вермишель сразу не склеилась. Можно добавить растопленное сливочное масло. Можно использовать вермишель, которая была сварена раньше, а также различные небольшие рожки и измельченные отварные макароны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8957,'Перекрутить через мясорубку отварное мясо. Почистить лук, измельчить и чуть-чуть пассировать на сковороде на растительном масле, не зажаривать. Прокрученное мясо положить на сковороду, размешать. Положить содержимое сковороды в посуду с вермишелью. Лук в запеканку можно не класть. В этом случае мясо, после прокручивания, сразу смешать с вермишелью. Однако лук придает блюду улучшенный вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8957,'Отдельно взбить в емкости яйцо и молоко или бульон, чуть-чуть подсолить, перелить в вермишель с мясом. Размешать, если требуется, досолить. Смазать формочку 18 на 25 на 5 сантиметров маслом, присыпать сухариками. Выложить равномерно вермишель и мясо. Сверху можно намазать или яйцом, или сметаной, или маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8957,'Отправить в духовку, готовить до румяного цвета, соблюдать температуру 170 градусов. Остудить готовую запеканку из вермишели с мясом, перед подачей порезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8958,'Включить духовку, разогреть до 220 градусов. Сделать тесто: соединить яйцо, кефир, оливковое масло, насыпать сахар, соль, соду. Вылить смесь в просеянную муку, перемешать. Замесить тесто, подсыпать чуть-чуть муки, пока не перестанет липнуть к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8958,'Сделать начинку: вымыть и измельчить зелень, потереть сыр, соединить творог и сырое яйцо. Тесто разделить на части (получится от четырех до восьми частей), раскатать их в лепешки, на каждую из них положить четвертую часть начинки, завернуть края и защипнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8958,'Раскатать все начиненные шарики в лепешки среднего размера, положить на противень. Намазать растопленным сливочным маслом. Удобно готовить лепешки на специальном пергаменте, смазанном растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8958,'Выпекать на верхней полочке по одному противню минут пятнадцать, соблюдать температуру 220 градусов. В период приготовления лепешки могут значительно вздуться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8958,'Кушать воздушные сырные лепешки теплыми. Можно сочетать с красным вином и с салатиком из свежих овощей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Первый слой состоит из мелко порезанного огурца и авокадо, сливочного сыра и листьев пекинского салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Второй слой - филе семги, порезанное на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Третий слой: красный и желтый перец, порезанный соломкой, на перец нанести тоненький слой майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Четвертый слой состоит из мелко натертого белка, смазанного тоненьким слоем майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Пятый слой – это потертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Порвать листья пекинского салата руками, посыпать блюдо, на листья положить креветки, побрызгать соком апельсина или лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8959,'Украсить слоеный салат-торт «Семужный» кедровыми орехами и подавать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8960,'Смешать в глубокой кастрюльке коричневые палочки или измельченную корицу, имбирь, кардамон, гвоздику, черный или белый перец, мускатный орех, сок ананаса или апельсина (можно также использовать лимонад или другой сок).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8960,'Положить лимон или апельсин, порезанный на тоненькие кружочки. Залить мед или какой-нибудь другой подсластитель, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8960,'Убавить огонь, добавить любимый чай (зеленый, белый или ройбуш), готовить 15-90 минут. Чем дольше, тем насыщенные будет в результате вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8960,'Процедить чай, разлить в чашечки, подавать пряный цитрусовый чай в теплом или холодном виде с ломтиками лимона или апельсина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8961,'Грибы отмочить, затем их отварить и отжать. Обжарить с репчатым луком подготовленные грибы. Предварительно отваренный картофель в «мундире» почистить и нарезать кубиками. Крупно натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8961,'В емкость сложить картофель, перец, грибы и сыр, все хорошо перемешать. Готовое (размороженное) слоеное тесто разрезать на одинаковые прямоугольники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8961,'Внутреннюю сторону каждого кусочка промазать чуть взбитым яйцом, выложить подготовленную начинку, свернуть в кулечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8961,'На противень уложить все получившиеся кулечки, смазать их оставшимся яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8961,'При 200 градусах выпекать кулечки слоеные с грибами в течение 15 минут в духовке. Перед подачей украсить рубленой петрушкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8962,'Смешать белки с солью, взбивать, пока не получится крепкая пена. Насыпать сахар, еще чуть-чуть взбить, смесь должна стать густой и тягучей. У белков должен появиться блеск. Важно, что сахар растворяться не должен, потому что во время выпечки он закарамелизуется.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8962,'Раскатать тесто так тонко, насколько это возможно, вырезать круги при помощи стакана. Тесто, которое осталось, снова скатать и раскатать. На серединку каждого круга положить по маленькой ложке белков. Закрепить чуть-чуть краешки теста, как у вареника, но до конца не залеплять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8962,'Положить на противень, застеленный специальной бумагой, смазанной маслом. Между печеньками должно быть некоторое расстояние. Получится приблизительно два листка для выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8962,'Выпекать печенье «Губы Анжелины Джоли» минут сорок, соблюдать температуру 160 градусов. В горячем виде они очень хрупкие. Когда остынут, можно подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'В миску влить кефир, добавить к нему хлопья и соду, перемешать, убрать в сторону на 10 минут, чтобы хлопья набухли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'Кабачок помыть, снять кожуру, натереть на терке, слить и отжать всю лишнюю жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'В кефирно-хлопьевую смесь добавить кабачок, всыпать сахар, посолить и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'С разрыхлителем смешать муку, просеять смесь в тесто и хорошо размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'Оладушки овсяные с кабачком до полной готовности жарить на медленном огне под крышкой на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8963,'Подавать готовые оладьи можно со сметаной, сгущенным молоком или вареньем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8964,'Выжать из апельсина сок. Соединить горчицу, сок, апельсиновый джем, кориандр, соевый соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8964,'Порезать рыбу на порционные куски, выложить в формочку для запекания, залить маринадом. Отставить минут на тридцать. По желанию можно посыпать семечками кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9029,'Рядом положить измельченные яйца, ветчину, авокадо, фету, разрезанные на половинки черри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8964,'Отправить в разогретую духовку, готовить лосося с апельсиновым джемом минут пятнадцать, соблюдать температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8964,'Подавать можно с любым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Порезать куриное филе на средние кусочки. Помыть грибы, мелко их порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Соединить грибы с мясом, приправами, чесноком, паприкой, хорошенько перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Упаковать содержимое в жаропрочный рукав, туго завязать его, прокалывать не нужно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Отправить минут на 45 в духовку, соблюдать температуру 170 градусов. Определить готовность можно по запаху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Достать, завернуть буженину из курицы с шампиньонами в фольгу, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8965,'Порезать на пласты, подавать с гарниром или как самостоятельное блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8966,'Сделать начинку: мелко потереть морковь. Разломать сыр. Обжаривать сыр с морковью на сковороде минут десять. Посолить, поперчить, добавить куркуму, сливки. В конце положить измельченный укроп и петрушку. Начинка для зраз может быть какой угодно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8966,'Слепить картопляники: смазать руки растительным маслом или намочить водой. Взять чуть-чуть пюре, сделать толстенькую лепешку. Если пюре получилось жидковатое или не склеивается, то насыпать чуть-чуть муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8966,'Лепешку держать в руках, положить сверху начинку, осторожно свернуть ее, по краешкам склеить. Обвалять зразу со всех сторон в муке, положить на сковороду с разогретым растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8966,'Можно положить зразы на противень, смазанный маслом, отправить минут на тридцать в духовку, пока не образуется корочка. Обычно картопляники с сыром и морковью подаются с кетчупом или сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8966,'Можно приготовить соус из орехов. Соединить все ингредиенты в блендере, почистив заранее перец от семян. Перемешивать, пока орехи максимально не измельчатся.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8967,'Перемешать соус до однородности. Посыпать курицу солью, внутри и снаружи намазать соусом (если курица порезана на куски, то залить соусом). Мариновать мясо часа три в прохладном месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8967,'Положить курицу на противень спинкой или кожей вниз, отправить в разогретую духовку (противень предварительно застелить фольгой). Готовить минут пятнадцать, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8967,'Порезать яблоки на дольки. Противень достать из духовки, перевернуть куриные бедра в изумительном соусе, выложить яблочные дольки. Выпекать еще минут 25.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8968,'Разморозить тесто, развернуть, раскатывать не нужно. С помощью формочки для кексов вырезать фигурки. Сформировать ракушку. Нижнюю угловую часть примять пальцами в нескольких местах, это место плотного крепления, давить на тесто – оно не должно в данном месте подняться, сделать не глубокие надрезы от края к середине.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8968,'Осторожно намазать ракушки взбитым желтком, чтобы он не попал на края и в надрезы, так как тесто в этих местах не поднимется. Поставить противень с ракушками минут на пятнадцать в разогретую духовку, соблюдать температуру 180 градусов. Достать и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8968,'Если ракушки из слоеного теста не раскрылись, то разрезать, на нижнюю часть положить какую-нибудь начинку. Хорошо подходит салат из морепродуктов, необычно смотрится, когда из ракушки выглядывает осьминог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8969,'Поломанное печенье и порубленные орехи сложить в посуду. Растопить в кастрюльке шоколад и сливочное масло до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8969,'Насыпать сахар, какао, перемешать, налить сгущенное молоко, размешать, довести до кипения и сразу убрать с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8969,'Приготовленную массу вылить на печенье. Размешать, завернуть в пленку, придать форму колбаски, отправить в холод. Через часа четыре снять пленку, шоколадное салями обвалять в пудре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8970,'Духовку разогреть. Соединить муку, овсяные хлопья, корицу, разрыхлитель, сахар, соль. Порезать масло на небольшие кусочки, положить в сухую смесь, растереть руками, чтобы получилась крупная крошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8970,'Положить 2/3 массы на дно формочки, намазанной маслом или застеленной специальной бумагой. Массу выровнять, прижать. Сверху положить перетертую чернику, посыпать остальной овсяной крошкой (прижимать не нужно).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11749,'Снять с огня, остудить, перелить в кувшин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8970,'Готовить овсяное печенье с черникой минут 35, слой ягод должен уплотниться. Остудить и порезать на порционные куски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8971,'Взбить яйца и сахар. Положить масло комнатной температуры, взбить. Налить молоко такой же температуры, взбить. Просеять муку, насыпать маленькими порциями, вымесить тесто – оно должно быть жидким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8971,'Нагреть вафельницу, используя кондитерскую кисть, намазать растительным маслом, прокалить. Налить в электровафельницу пару ложек теста, плотно накрыть крышкой, готовить, пока не подрумянится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8971,'Доставать готовую выпечку из вафельницы при помощи вилки или ножа. Сразу сворачивать. Можно приготовить любой крем и начинить им домашние вафли на молоке, используя кондитерский шприц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8972,'Нагреть сливки, но не кипятить. Разломать и положить шоколад в горячие сливки, масло, перемешать до однородности. Остудить, накрыть крышкой, отправить на ночь в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8972,'Взять массу ложкой (она, как пластилин), скатать шарики, обвалять в просеянном с сахарной пудрой какао. Хранить шоколадный трюфель в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8973,'Сливочное масло нарезать кубиками, смешать его с сахаром и яйцом, хорошо перемешать. В масляную массу добавить муку и вымешивать тесто до эластичного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8973,'Разделить готовое тесто на две одинаковые части, добавить в одну из них какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8973,'Каждый кусочек теста раскатать в тонкий пласт, светлый пласт наложить на темный, скатать рулет. Рулет нарезать на кружки по одному сантиметру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8973,'Пекарской бумагой застелить противень, выложить подготовленные круги и выпекать печенье песочное «Улитка» с какао в течение 30 минут при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8974,'Для каждого коржа взбивать яйца и сахар минут по пятнадцать при помощи миксера на большой скорости. Сделать скорость миксера минимальной, осторожно насыпать просеянную муку с содой. Выполнить процедуру три раза отдельно для каждого коржика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8974,'Готовить коржи в мультиварке минут по пятьдесят в режиме «Выпечка». После готовности крышку не открывать сразу, чтобы корж не осел. Так готовить три коржа – простой, с шоколадом и с изюмом. Остудить, каждый намазать сиропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8974,'Сделать крем из сливочного масла и сгущенного молока. Намазать тортик кремом, поставить часов на шесть в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8974,'Сделать глазурь для украшения праздничного бисквита - растопить на тихом огне сливочное масло, добавить молоко, сахар, вареную сгущенку. Готовить минут семь, помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Поставить на медленный огонь мед и соду, держать, пока масса не вспенится, постоянно помешивать. Взбить яйца, ванилин, сахар, соль. Порезать на кусочки масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'В смесь из меда положить масло, после этого, помешивая, остальное. Перемешать, насыпать муку, чтобы консистенция была, как густая сметанка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Положить в формочку, намазанную маслом и присыпанную мукой, отправить минут на тридцать в духовку, соблюдать температуру 160 градусов. Проверять готовность зубочисткой, если не липнет, то готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Во время приготовления медовика, сделать крем. Взбить сметану, ванилин, сахарную пудру. Поделить массу на две одинаковые части. В одну положить помытый и обсушенный, порезанный чернослив. Поставить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Когда корж приготовится, достать из духовки, сразу разрезать вдоль пополам. Крем с черносливом положить практически весь на горячий корж. Сметанка не растекается, очень быстро пропитывается.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Дать остыть, намазать оставшимся кремом с черносливом, положить второй корж. Сверху намазать сметанный кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8975,'Украсить медовый торт «Гости на пороге» по желанию орешками, шоколадом, крошкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Нагреть сливки, налить в рисовые хлопья, накрыть. Отставить, чтобы хлопья набухли и остыли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Соединить сахар и щепотку ванилина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Вымыть лимон, мелко потереть цедру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Разделить белки и желтки. Взбить белки и соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Закарамелизовать вишню в ½ меры масла и сахаре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Положить в рисовые хлопья желтки, цедру лимона, ванильный сахар, размешать, вмешать взбитые белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Намазать сливочным маслом форму для запекания, положить ½ рисовой массы, сверху карамельную вишню. На нее остальную рисовую массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Раскидать сверху оставшееся масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8976,'Готовить пудинг 25-30 минут, соблюдать температуру 200 градусов. Подавать вишневый пудинг из рисовых хлопьев в теплом виде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8977,'Налить в сотейник сок апельсина, добавить лук, кипятить, пока не испарится половина сока. Добавить воду, гранатовый сок, кипятить, пока не выпарится половина жидкости. Налить мед, перемешать, кипятить, мешая, пока смесь не загустеет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8977,'Убрать с огня, насыпать гранат, посыпать перцем, размешать, остудить. Отбить куриные грудки до толщины полтора сантиметра. Развернуть лист, на половину положить мясо, накрыть второй половиной, сделать то же со второй грудкой. Чуть-чуть прижать рукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8977,'Нагреть сковороду без масла. Положить куриную грудку, обжаривать минут по семь с каждой стороны. Выключить огонь, убрать листы. Подавать куриное филе по-итальянски с гранатовым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8978,'Порезать семгу на небольшие удлиненные куски (приблизительно 3 на 7 сантиметров), побрызгать лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8978,'Сделать кляр: взбить яйцо и соль, постепенно насыпать муку, налить минеральную воду, чтобы консистенция получилась, как на оладьи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8978,'Обвалять кусочки рыбы в тесте, выложить на сковороду с горячим растительным маслом. Обжаривать филе семги в кляре минут по семь со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8979,'Сливочное масло (размягченное) смешать с яичными желтками и вымешивать массу, пока консистенция не будет кремообразной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8979,'В получившуюся массу просеять муку, всыпать сахар и замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8979,'Получившееся тесто разделить на желаемое количество кусочков, из которых скатать небольшие шарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8979,'Противень застелить пекарской бумагой, выложить на него все шарики и слегка их придавить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8979,'В духовом шкафу выпекать печенье песочное «Нежность» при 200 градусах в течение 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Перемолоть или порубить орехи, перемешать с крошкой от печенья. Насыпать какао.','https:https://st.vkuso.ru/data/cache/thumb/af/ce4b8dd0dcb2aaf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Приготовить крем: налить чуть-чуть молока в ванилин, муку и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Размешать венчиком, чтобы не было комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Взбить яйцо, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Остальное молоко вылить в кастрюльку, подогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'В горячее молоко вылить тонкой струйкой молочно-яичную смесь, постоянно помешивать на маленьком огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Когда смесь станет густой, положить масло, мешать, пока не растворится.','https:https://st.vkuso.ru/data/cache/thumb/63/354caaf252ff863_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Убрать с плиты. Медленно в горячий крем насыпать крошку.','https:https://st.vkuso.ru/data/cache/thumb/19/fe876fb0f8a1319_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Сформировать пирожные. Обвалять в какао.','https:https://st.vkuso.ru/data/cache/thumb/db/b5b99ac23bf55db_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8980,'Украсить заварное пирожное «Картошка» с какао по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/b8/16affeba06e86b8_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8981,'Отварить фасоль, слить воду. Порезать морковь, лук по диагонали и картофель. Положить все к фасоли, залить кипятком, варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8981,'Порезать бекон и колбасу (копченое мясо, ветчину), положить к овощам, варить минут пятнадцать. Заправить все солью, чесночком, зеленью. Позволить закипеть, посыпать перцем, солью, отставить кастрюльку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8981,'Приготовить тесто для лапши. Отварить ее в соленой воде, воду слить. Положить лапшу в суп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8981,'Подавать фасолевый суп с колбасой и домашней лапшой желательно добавив большую ложку уксуса, чтобы суп был кисленьким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8982,'Нагреть духовку. Вымыть и почистить морковь. Если морковь большая, то разрезать ее разрезать ее по диагонали на тоненькие кружки.','https:https://st.vkuso.ru/data/cache/thumb/48/e54fe0c6dcd1b48_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8982,'Положить на противень, перемешать с оливковым маслом. Посыпать перцем, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8982,'Отправить на 25-30 минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8982,'Выложить на тарелку, положить на теплую морковь петрушку и фету. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/e6/71a1ef3d08abce6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9029,'Полить салат с ветчиной, авокадо и помидорами черри соусом и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8982,'Можно завернуть запеченную морковь с петрушкой и сыром фета в коппу или бекон.','https:https://st.vkuso.ru/data/cache/thumb/ca/d6851e77fe7faca_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8983,'Подготовить ингредиенты. Положить в кастрюльку с толстым дном смородину и специи, налить воду. Поставить на средний огонь, готовить, пока не полопаются и не станут мягкими практически все ягоды, приблизительно минут 25. В процессе готовки помешивать ягоды, давить их ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8983,'Откинуть смородину и специи на ситечко, застеленное несколькими слоями марли. Цедить часов восемь в холодильнике, сок больше не выжимать, так как сироп может получиться мутным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8983,'Когда пройдет время, отмерить необходимое количество сока, перелить в кастрюльку. Отмерить необходимое количество сахара, насыпать к соку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8983,'Довести до кипения, кипятить минут пять на большом огне, помешивать и снимать пену. Сахар должен раствориться, а сироп приобрести нужную консистенцию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8983,'Разлить горячий сироп по баночкам. Закрыть крышками, перевернуть дном вверх. Накрыть банки со смородиновым сиропом, оставить постепенно остывать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8984,'На порционные кусочки порезать рыбное филе, каждый кусок обмазать черным молотым перцем, специями, солью, сбрызнуть лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8984,'На крупной терке потереть предварительно помытый и очищенный картофель. В миску с тертым картофелем вбить яйцо, всыпать муку, хорошенько все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8984,'В получившемся картофельном кляре запанировать подготовленные рыбные кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8984,'Разогреть на сковородке оливковое масло и со всех сторон обжарить на нем форель с лимонным соком в картофельном кляре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8984,'Затем сделать огонь поменьше, закрыть крышкой и готовить в течение получаса. Подать к столу с овощами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Нагреть духовку до 175° С.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Вырезать из яблока серединку, порезать на мелкие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Соединить в емкости овсяные хлопья, яблоко, корицу, изюм, сахар, мускатный орех, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Положить растопленное масло, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Положить смесь в огнестойкую посуду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Налить молоко, отправить на 25-30 минут в духовку, чтобы масса пропиталась молоком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Посыпать овсянку корицей, налить чуть-чуть молока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8985,'Можно подавать запеченную овсянку с яблоком, изюмом и корицей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8986,'Соединить сливочное масло комнатной температуры со стружкой. В несколько приемов положить сгущенное молоко. Размешать до однородности, отправить минут на шестьдесят в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8986,'Готовую массу набирать ложкой, добавлять по одному орешку. Скатать шарик, орешек должен быть внутри. Панировать шарик в стружке кокоса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8986,'Отправить «Рафаэлло» с кешью в холодильник минут на тридцать, но можно подавать сразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Разрезать цитрусовый плод на две части. Выдавить сок в посуду, вырезать ножом или ложкой мякоть.','https:https://st.vkuso.ru/data/cache/thumb/c8/1daa5b328c540c8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Промыть форму, промокнуть салфеткой. Отмерить необходимое количество агар-агара.','https:https://st.vkuso.ru/data/cache/thumb/29/c1cea6d7b27c529_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Добавить к соку, поставить на плиту, добавить варенье. Довести до кипения. Процедить массу через сито.','https:https://st.vkuso.ru/data/cache/thumb/67/65ed3c4fb5bdb67_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Положить половинки цитрусовых в формы для кексов. Вылить полученную смесь в половинки цитрусовых. Отправить в холодильник на ночь.','https:https://st.vkuso.ru/data/cache/thumb/25/74d8a84d09df325_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Когда желе приготовится, положить фрукты на доску плоской стороной вниз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Разрезать лимоны и лаймы на три части острым ножом, апельсины порезать на 4 части.','https:https://st.vkuso.ru/data/cache/thumb/d2/1a49f80f7404ed2_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Срезать лишнюю шкурку, разложить на тарелки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8987,'Можно подавать малиновое желе с агар-агаром в цитрусовых корочках.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8988,'Поломать шоколад, поместить на паровую баню, растопить, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8988,'Воздушный шар окунуть в жидкий шоколад, несколько раз провернуть по своей оси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8988,'Дать заготовке остыть примерно треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8988,'Осторожно проколоть, аккуратно удалить шар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8988,'Уложить на тарелку мороженое, присыпать дробленым орехом, сверху поставить шоколадный шар, перед самой подачей облить растопленной карамелью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Тонко нарезать бекон, зажарить и обсушить от жира.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Обжарить орехи и семечки до золотистости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Сыр произвольно настрогать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Авокадо порезать на тонкие ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Салатные листья приправить маслом с перцем, уксусом и солью, осторожно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8989,'Разложить зеленый салат с беконом и авокадо по тарелкам, уложить сверху авокадо, стружку сыра и бекон, присыпать орешками с семечками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Выжить сок из грейпфрута. Перемешать все ингредиенты заправки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Сыр измельчить на мелкой терке, хорошо разогреть сковороду, выложить по щепотке сыра, обжарить полминуты до получения ажурных сырных чипсов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Переложить их лопаточкой на полотенце из бумаги, дать остыть и хорошо подсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Грушу порезать на тонкие ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Листья салата порвать на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Ветчину порезать соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Всыпать в салат с пармской ветчиной, грушей и сырными чипсами ягоды брусники, влить заправку, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8990,'Переложить салат в тарелку, разложить сверху высохшие чипсы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8991,'В пару стаканов любого белого вина, всыпать сахар, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8991,'Залить виноград в банке, убрать минимум на 12 часов в холодильник, чтобы ягоды пропитались вином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8991,'Достать ягоды, дать им обсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8991,'Насыпать немного сахара в тарелку, обвалять со всех сторон каждую ягодку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8991,'Сложить пьяный виноград в белом вине на плоское блюдо в один ряд, прикрыть пергаментной бумагой, поместить на 4 часа в морозилку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Перемешать все ингредиенты (миндаль и рисовую муку не трогать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Накатать примерно 10-12 шариков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Насыпать в плоскую тарелку рисовую муку, обкатать их со всех сторон в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Обжарить сырники с миндалем и пармезаном до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Положить друг на друга два бумажных полотенца, уложить на них сырники, затем переложить на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8992,'Присыпать миндальной крошкой, отдельно поставить на стол холодную сметану.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8993,'Приготовить соус: порезать лук на маленькие кубики. Крупно потереть морковь. Обжарить овощи на сковороде с горячим растительным маслом. Положить в фарш прессованный чеснок и яйцо. Посыпать перцем, солью. Добавить сухую или измельченную зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8993,'Хорошенько размешать фарш, отбить о дно посуды. Намочить руки холодной водой, скатать шарики (по размеру, как вишня). Чтобы было удобней, рядом поставить емкость с водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8993,'В сковороду к овощам осторожно положить один слой фрикаделек. Налить молоко или сметанку, разведенную водой. Фрикадельки не перемешивать, пока они не поменяют цвет. После этого перемешать. Готовить, пока полностью не выпарится молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8993,'Положить помидоры, мелко порезанные, или томатную пасту. Размешать, чуть-чуть посыпать солью. Добавить сухую смесь болгарских перцев и прованских трав.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8993,'В отдельной посуде отварить спагетти, подсолив воду, до полуготового состояния. Подавать спагетти с мясными фрикадельками в соусе, украсив зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8994,'Растопить масло, насыпать сахар. Размешать. Вбить яйца. Взбить все с помощью венчика. Налить кефир, размешать, положить соду (гасит не нужно) или разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8994,'Положить потертую цедру лимона. Насыпать муки столько, чтобы консистенция была гуще, чем на оладушки. Оно должно равномерно распределиться по формочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8994,'Смазывать формочки нет необходимости. Положить в них тесто на 2/3 чуть-чуть потрясти, чтобы все пустоты заполнились. Отправить печенье «Медвежонок Барни» в духовку, готовить минут 25.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8995,'Порезать мелко картофель, отварить в подсоленной воде. Слить воду и размять картофель. Положить масло, вбить яйцо, размешать. Насыпать муку, вымесить тесто. Переложить в разъемную формочку, сделать бортики. Пока готовится начинка, отправить тесто в морозильную камеру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8995,'Порезать мелко перец, чуть-чуть обжарить. Измельчить лук, обжарить отдельно, положить мясо, мелко порезанное, обжаривать практически до готовности, посыпать солью. Положить перец, помидоры, порезанные на маленькие кубики, положить начинку на тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8995,'Соединить молоко, сливки и томатную пасту. Вбить яйцо, чуть-чуть взбить. Посыпать перцем, солью. Вылить на начинку. Готовить открытый пирог с мясом на картофельном тесте минут сорок, соблюдать температуру 200 градусов. Минут за десять до конца готовки, посыпать пирог потертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8996,'Разогреть духовку. Намазать маслом четыре керамических формочки небольшого размера (приблизительно по 180 миллилитров). Чуть-чуть присыпать сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8996,'Насыпать в емкость сахар, соль, кофе, добавить яйца, взбивать несколько минут. Поломать на маленькие кусочки шоколад, положить в посуду, добавить сливочное масло, поставить в микроволновую печь. Перемешивать каждые двадцать секунд, пока не расплавится шоколад и масло. Позволить массе чуть-чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8996,'Вылить массу в емкость с сахаром, кофе и яйцами. Насыпать муку, взбивать до однородности с помощью венчика. Вылить тесто в формочки, поставить на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8996,'Готовить в духовке минут одиннадцать, не больше. Можно подавать кексы с жидкой начинкой к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8997,'Соединить ингредиенты, смешать до однородности. Получится жидкое тесто. Вылить смесь на холодную сковороду, заранее намазанную растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8997,'Сверху положить любую начинку на ваше усмотрение. Верхним слоем пиццы должен стать сыр (слой должен быть толстым).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8997,'Поставить на средний огонь, накрыть крышкой. Сыр расплавится - вкуснейшую пиццу на сковороде можно подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8998,'Порезать лук на полукольца, помидоры порезать на небольшие кусочки, слить сок с тунца, размять вилкой, не доставая из банки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8998,'Слить сок с кукурузы. Соединить помидоры, тунец, лук, кукурузу, заправить сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8999,'Посыпать перцем и солью мясо. Обвалять в муке. Положить на сковороду с растопленным сливочным маслом, обжарить. Вылить на индейку шампанское. Накрыть крышкой, сделать огонь меньше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (8999,'Приблизительно через час прибавить огонь, чтобы выкипел соус, налить половину от нормы сливок, готовить филе индейки в шампанском еще пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9000,'Подготовить ингредиенты. Почистить, вымыть, порезать картофель, положить кастрюльку, налить воду, чтобы она покрыла картофель. Подсолить. Варить на маленьком огне до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9000,'В это время подготовить ингредиенты для заправки: соединить половину емкости сливок и половину молока. Слить с отваренного картофеля воду. Сделать пюре при помощи миксера. Положить сливочное масло, прессованный чесночок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9000,'Нагреть духовку. Нагреть смесь на тихом огне, но не кипятить. Положить в картофель и взбить до пышного состояния. Положить пюре в формочку, потереть сверху сыр. Отправить в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9000,'Достать, когда сыр станет румяным. Готовое картофельное пюре под сыром можно порезать на квадраты, можно с помощью формочки вырезать аппетитные кружки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9001,'За полтора часа до готовки разморозить при комнатной температуре слоеное тесто. Почистить лук от шелухи, порезать на полукольца. Обжарить лук, во время обжарки посыпать молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9001,'Приготовить заливку: взбить яйца и сметану. Крупно потереть сыр, положить в яичную смесь, размешать. Раскатать 2/3 размороженного теста, положить в формочку, сделать маленькие бортики (приблизительно три сантиметра высотой), лишнее обрезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9001,'На тесто положить обжаренный лук. Распределить равномерно сырно-яичную заливку. Загнуть бортики к середине. Оставшееся тесто порезать на полоски, положить крест-накрест, как сетку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9001,'Намазать сверху остатками яичной заливки или желтком. Готовить луковый пирог «Onion Pie» минут 25, соблюдать температуру 220 градусов. Подавать или холодным, или горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9002,'Приготовить начинку: мелко потереть сыр, чесночок, измельчить петрушку. Размешать, положить в смесь мягкое сливочное масло. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Сварить картофель в подсоленной воде, дать ему остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9002,'Порезать батон по диагонали, насквозь не прорезать. Надрезы заполнить начинкой. Завернуть закуску в фольгу, отправить минут на двадцать в духовку, соблюдать температуру 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9002,'Открыть фольгу, отправить батон с чесноком и сыром еще минут на пять в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9003,'Отваривать рис минут пятнадцать, а яйца вкрутую. Из листа нори вырезать основу для пингвинов. Клюв и лапки вырезать из моркови. Отваренное яйцо завернуть в заготовку из нори. Добавить лапы и клюв.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9003,'Приготовленный рис соединить с подтаявшим сливочным маслом. Положить рис в круглую емкость, чуть-чуть утрамбовать. Подготовить большое блюдо. Перевернуть на него рис – это иглу. Из листа нори вырезать дверь для иглу. Разместить посередине.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9003,'Поставить на блюдо пингвинов, выложить маленькую рыбку, по желанию украсить. Рис с яйцом и соленой рыбой можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9004,'Порезать баклажаны на тоненькие полоски. Получится приблизительно двенадцать лепестков. Посыпать лепестки солью, положить слоями в дуршлаг, оставить минут на шестьдесят.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9004,'Выжать из баклажанов жидкость, промокнуть бумажным полотенцем. На дно кастрюльки или глубокой сковороды нагреть в духовке два сантиметра масла. Обжаривать три-четыре лепестка минуты по четыре. Доставать щипчиками из масла, положить в дуршлаг или на бумажные полотенца, чтобы лишний жир стек. Повторить процедуру с остальными баклажанами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9004,'Приготовить начинку: в емкости смешать сухари, цедру, сок, рикотту, соль, тимьян. Нагреть духовку. Положить томатную пасту тоненьким слоем в емкость для запекания. На один краешек обжаренного баклажана положить по ложечке начинки, скрутить рулетики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9004,'Положить все рулеты вниз швом на томатную пасту. На каждый рулетик положить по ложке сливок. Готовить итальянские инвольтини из баклажана минут 25, рулеты должны потемнеть. Посыпать тертым сыром перед подачей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9005,'Развести щепотку сахара и дрожжи в теплом молоке, отставить минут на пятнадцать. Просеять муку, положить цедру 1 апельсина, соль, ваниль, тимьян. В муку добавить опару, сок половинки апельсина, измельченные орехи, яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9005,'Замесить тесто, накрыть, отправить минут на шестьдесят в тепло. Нагреть духовку. Поделить тесто на три части. Раскатать три колбаски, сплести косу. Накрыть полотенцем, отставить минут на тридцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9005,'Готовить минут сорок, заранее смазать косичку желтком, разбавив чуть-чуть молоком. Готовую плетенку с анисом и фундуком намазать апельсиновым джемом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9006,'Порезать курицу на маленькие кусочки. Смешать в большой емкости первые шесть ингредиентов. Отправить минут на шестьдесят в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9006,'Приготовить сэндвич. Разрезать булочку или питу, вложить листья зеленого салата, сверху положить охлажденный куриный салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9007,'Залить желатин кипяченной холодной водой минут на сорок. Насыпать в желатин половину сахара, нагреть на небольшом огне до растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9007,'Взбить охлажденные белки с лимонной кислотой. Медленно насыпать в белки оставшийся сахар, взбивать, пока не растворится сахар. Вылить в смесь желатин, взбивая на маленьких оборотах. Отставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9007,'Взбить сгущенное молоко и мягкое масло. Ввести данную смесь в белки, насыпать ванильный сахар. Намазать формочку маслом, присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9007,'Положить суфле, чтобы пирожное «Птичье молоко» застыло, отправить в холодильник. Растворить на водяной бане шоколад, полить пирожные глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9008,'Взбить с помощью блендера все продукты, разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9009,'Вымыть и обсушить свинину. Почистить чесночок, разрезать зубчики вдоль. Мясо проткнуть острым ножом. Вставить в проколы чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9009,'Натереть мясо солью, приправами, накрыть полиэтиленом, отставить часа на полтора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9009,'Завернуть в фольгу, готовить свинину с чесноком в духовке часа четыре, соблюдать температуру 220 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9010,'Замесить тесто, накрыть, отставить минут на сорок. Вымыть и просушить зелень, крупно порезать, размешать. В зелень добавить яйцо, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9010,'Крупно потереть мягкий сыр, положить в зелень. Поделить тесто на кусочки. Раскатать тоненькие лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9010,'На одну сторону положить начинку, свернуть пополам, залепить. Отправить афарары с зеленью минут на пятнадцать в предварительно разогретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9011,'Разогреть духовку. Противень чуть-чуть намазать жиром. Стол присыпать мукой, развернуть тесто, раскатать пласт 25 на 20 сантиметров. На тесто положить слой нутеллы, равномерно распределить, посыпать орешками (по желанию).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9011,'Свернуть рулетик к середине с противоположных сторон. Центр намочить водой, чтобы рулеты сошлись в середине. Разрезать с помощью острого ножа на кусочки по 1 сантиметру в толщину, положить на противень, присыпать сахаром. Готовить ушки с нутеллой минут пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9012,'Приготовить мясной соус: на оливковом масле обжарить измельченный лук, посыпать солью. Положить мясной фарш, приправы, тушить. Положить томатный соус, тушить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9012,'Приготовить белый соус: на сливочном масле обжарить муку, постепенно налить молоко, перемешивая, насыпать молотый мускатный орех и соль. Готовить до момента, когда закипит и загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9012,'Порезать сыр на ломтики или потереть. Отварить макаронные изделия до полуготового состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9012,'Подготовить формочку, намазать маслом, бока обложить фольгой. Собрать лазанью слоями: макароны, сыр, полить белым соусом, фарш и еще несколько таких слоев.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9012,'Готовить ленивую лазанью из макарон в духовке минут шестьдесят, соблюдать температуру 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9013,'Взбить при помощи блендера апельсиновый и лимонный сок, банан, мед. Разлить по бокалам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9014,'Растереть масло и сахар, взбить с помощью венчика. Положить творог (если он крупный, то протереть через ситечко). Взбить до однородности. Положить несколько яиц или одно яйцо и желток. Взбить. Насыпать просеянную муку и разрыхлитель. Взбить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9014,'Залить кипятком изюм, подождать, пока набухнет. Слить воду, обсушить, положить в тесто. Накрыть формочку 18 на 9 специальной бумагой, намазать маслом, налить тесто. Готовить минут шестьдесят, соблюдать температуру 170 градусов. Готовность проверять зубочисткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9014,'Купить в магазине помадку, которая готовится пять минут. Залить пакет не кипяченой, но горячей водой, отставить минут на пять, чтобы помадка стала мягкой.  Чтобы получилась однородная масса, размять пальцами пакет. Срезать уголок, покрыть содержимым пакета творожный кекс, позволить застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Разогреть духовку. Соединить муку, соду, соль, порошок-какао. В другой посуде с помощью миксера перемешать мягкое сливочное масло, два вида сахара. Взбивать минуты три на небольшой скорости, масса должна быть воздушной и легкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Взбить яйца и 2 чайные ложки экстракта ванили, переложить в смесь масла и сахара. Медленно, маленькими порциями ввести в данную смесь сухие ингредиенты, кефир, воду, чередовать их. Взбивать на маленькой скорости до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Две круглые формочки намазать маслом, посыпать мукой. Вылить тесто, готовить минут 35. Готовность проверять зубочисткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Приготовить крем. Миксером взбить сливки, сыр, экстракт ванили( 1 ч.л.), сахарную пудру. Положить половину Нутеллы, взбивать до однородности. Отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Оставшуюся пасту оставить при комнатной температуре, так как застывшей Нутеллой будет сложно намазать коржи. Готовым коржикам позволить минут десять остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9015,'Нижний корж намазать шоколадной пастой, отправить минут на пятнадцать в холодильник. Сверху на застывшую Нутеллу нанести крем. Накрыть вторым коржом, покрыть кремом весь шоколадно-ореховый торт с сыром и Нутеллой. Посыпать орешками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'Муку смешать с разрыхлителем и солью, просеять в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'В отдельной миске смешать масло, яйца, сахар, ванилин, кардамон и мед, добавить подготовленную муку, перемешать до однородности (смесь должна получиться густой).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'Далее добавить в массу шоколадные капли, затем овсяные хлопья, тщательно перемешать все еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'Получившееся тесто переложить в предварительно смазанную сливочным маслом и посыпанную мукой форму, разровнять верх при помощи мокрой ложки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'За это время приготовить соус бешамель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9016,'Готовую выпечку остудить, не извлекая из формы, после чего аккуратно достать и нарезать на квадратики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9017,'Взбить масло, сахар, вбить яйца, налить кефир, насыпать муку, разрыхлитель, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9017,'Вылить тесто в формочку, намазанную маслом, положить ягоды сверху (можно замороженные), посыпать сверху сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9017,'Готовить пирог с вишней минут тридцать, соблюдать температуру 200 градусов. Позволить остыть в формочке, по желанию украсить сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9018,'Мясо порезать соломкой.','https:https://st.vkuso.ru/data/cache/thumb/e6/6d3e71803bff4e6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9018,'Чуть обжарить в казане на хорошо прогретом масле, всыпать тонкие полукольца лука, готовить до его прозрачности, постоянно помешивая.','https:https://st.vkuso.ru/data/cache/thumb/66/32b266b22399066_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9018,'Положить томатную пасту, добавить чуть воды, тушить под крышкой до полной готовности говядины.','https:https://st.vkuso.ru/data/cache/thumb/11/8a3ba93ff9d1511_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9018,'Обжарить картофель, нарезанный соломкой в растительном масле, порезать огурцы на ломтики.','https:https://st.vkuso.ru/data/cache/thumb/a9/dba500aefef9ba9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9018,'Положить все в казан к мясу, поперчить, подсолить, положить лавровый лист, выдавить в азу по-татарски из телятины с солеными огурцами чеснок. Осторожно все перемешать, тушить до полной готовности на слабом огне.','https:https://st.vkuso.ru/data/cache/thumb/0b/bbc5f0aa148550b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Взбить масло с добавлением сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Вмешать по одному все яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Перемешать сухие ингредиенты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Объединить обе смеси, всыпать в полученную массу 2/3 драже.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Перемешать, заполнить подготовленную форму, посыпать верх драже.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9019,'Выпекать пирожное брауни с шоколадным драже при 175 градусах примерно 25 минут, остудить, нарезать на кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9020,'Порезать кролика на восемь порционных кусочков, обжарить в половине растопленного масла до золотистости. Посыпать перцем, солью. Переложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9020,'Растопить остальное масло, обжаривать минут семь шампиньоны до румяного цвета. Посыпать перцем, солью. Положить мясо к грибам, налить вино, подогревать пару минут. Налить бульон, положить букет гарни. Плотно накрыть крышкой, тушить минут сорок на минимальном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9020,'В небольшом сотейнике разогреть оливковое масло, пожарить листья шалфея секунд тридцать в несколько приемов. Они станут ярко-зелеными и хрустящими. Шалфей очень быстро горит, поэтому не стоит отходить от плиты. Положить шалфей на салфетки, посыпать солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9020,'Достать из сковороды кролика с грибами, положить на тарелочку, травы выбросить. Сковороду убрать с плиты, чуть-чуть взбить желтки и сливки, налить бульон, быстренько перемешать. Поставить на маленький огонь, готовить минут пять, помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9020,'Соус должен стать густым. Чтобы желтки не отделились, не следует доводить до кипения. Посыпать перцем и солью. Вылить соус на фрикасе из кролика с грибами, посыпать листиками шалфея.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Филе чуть отбить, мелко порезать, перемешать с кубиками лука, добавить яйцо, поперчить, посолить, хорошо вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Смазать форму сливками, заполнить ее небольшими шариками из фарша.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Запечь куриные шарики из филе в сливочно-сырной заливке в прогретой до 180 градусах духовке четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Для заливки измельчить на мелкой терке сыр, влить сливки, добавить раздавленный прессом чеснок, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Полить на каждый шарик и вернуть еще на четверть часа в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9021,'Подавать с любым овощным салатом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9022,'Перемешать молоко и соду. В кухонный комбайн насыпать муку, коричневый сахар и разрыхлитель, взбить. Положить порезанное сливочное масло, взбить до рыхлой крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9022,'Насыпать половину массы в круглую формочку, застеленную специальной бумагой, утрамбовать. В оставшуюся массу вбить яйцо, положить мускатный орех, взбить. Налить молочную смесь, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9022,'Налить смесь в формочку, выложить сверху грецкие орешки, готовить армянский пирог с мускатным орехом минут пятьдесят, соблюдать температуру 175 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Отдельно натереть шоколад: только горький или горький и молочный в равных пропорциях.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9023,'Подогреть сгущенное молоко и масло сливочное. Положить кэроб или какао, размешать. Положить орешки. Насыпать сухое молоко, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9023,'Из получившейся массы сформировать шоколадные конфеты произвольной формы, отправить в холодильник для затвердения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Лук нарезать полукольцами, измельчить чеснок и обжарить все в сковороде, добавив небольшое количество оливкового масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Лук-порей нарезать кольцами или полукольцами, 5 помидоров — кубиками, часть зелени порубить, добавить все в чесночно-луковую смесь и потушить до загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Далее туда же добавить грибы и продолжить все тушить до полной готовности, поперчить, посолить, добавить орегано, сушеный базилик, смесь итальянских трав, перемешать и убрать в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Для соуса «Бешамель» необходимо растопить в сотейнике или кастрюле масло сливочное, всыпать муку и, все время хорошо помешивая, чуть обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Далее нужно понемногу влить молоко, постоянно помешивая, уварить соус так, чтобы он стал похож на не очень жирную сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Кубиками нарезать ветчину, зелень измельчить, крупно натереть сыр, кружочками порезать помидоры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Слоями выложить в огнеупорной форме будущую лазанью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'В духовку, перед этим  разогретую до 190 градусов, поставить форму с заготовкой на 20 минут, по истечении отведенного времени достать форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9024,'Выложить сверху круги помидоров, посыпать оставшейся зеленью и сыром и продолжить запекать еще 25 минут, готовую лазанью с шампиньонами и ветчиной подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9025,'Нагреть духовку до 180 градусов. Почистить от семечек и кожуры. Крупно порезать яблоки (разрезать каждое на восемь частей).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9025,'Тесто не взбивать. Просто соединить все ингредиенты в емкости. Все продукты нужно вынуть из холодильника предварительно. Лучше использовать не холодные яйца. Масло должно подтаять, чтобы легче было соединить его с остальными ингредиентами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9025,'Разрезать вдоль стручок ванили, соскрести семена с помощью ножа.  Насыпать муку, сахар и разрыхлитель. Перемешать. Намазать формочку сливочным маслом, равномерно положить порезанные яблоки. Сверху распределить довольно жидкое тесто. Просто повыше поднять посуду повыше, разлить смесь на фрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9025,'Отправить в духовку минут на тридцать. Поверхность должна хорошенько пропечься. Яблоки к этому времени станут мягкими, сверху появится корочка. Подавать пирог «Яблочный пудинг» желательно теплым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9026,'Порезать куриное филе на кусочки среднего размера, положить в посуду, налить соевый соус. Положить томатную пасту, насыпать сахар, добавить яблочный уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9026,'Насыпать красный болгарский перец, порезанный тоненькими полосочками, ананасы, порезанные кусочками. Размешать, отставить мариноваться минут на пятьдесят. Разогреть сковороду, обжаривать куриное филе в кисло-сладком соусе минут пятнадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9027,'Поломать на маленькие кусочки горький шоколад, растопить с молоком. Измельчить орешки и курагу, используя молоток или блендер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9027,'Соединить орехи, растопленный шоколад, мед и курагу, охладить. Из получившейся смеси скатать небольшие шарики, снова остудить, обвалять в какао, кунжуте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9028,'Замочить в холодной воде желатин приблизительно минут на тридцать. Протереть творог через ситечко. Соединить творог и половину сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9028,'Разогреть желатин на водяной бане до растворения. Постепенно размешивать. После этого остудить до комнатной температуры, положить творог, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9028,'Взбить сливки и остальной сахар. В несколько приемов добавить взбитые сливки в творог, размешать. Перед дальнейшим использованием творожный крем лучше немного охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9029,'Хорошо перемешать все компоненты соуса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9029,'Салат крупно порвать, разложить на плоском блюде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11802,'Мякоть нарезать кусочками по десять сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Растопить в сотейнике масло, всыпать столовую ложку муки, очень хорошо перемешать до исчезновения комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'После появления белой пены, влить молоко, подсолить, перемешать, прогреть до загустения соуса, снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Порезать картофель на кружочки, лук – тоненькими колечками, сыр натереть, мясо аккуратно отбить, разделить пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'В порционные формы уложить слой лука, накрыть его мясом, присолить и положить кусочки картофеля.','https:https://st.vkuso.ru/data/cache/thumb/74/5d349779acc5674_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Полить мясо соусом.','https:https://st.vkuso.ru/data/cache/thumb/e1/326fcce6d3656e1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Присыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/0f/432c8da873cff0f_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9030,'Поместить формы в разогретую до 200 градусов духовку на 25 минут, к столу подавать прямо в формах.','https:https://st.vkuso.ru/data/cache/thumb/e0/68ccb553f541de0_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9031,'Растворить сахар в воде, влить уксус, посолить, добавить масло, перемешать, нагреть рассол, прокипятить 5 минут, залить капусту, разобранную на соцветия.','https:https://st.vkuso.ru/data/cache/thumb/c1/128c63f68a2cbc1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9031,'Морковь измельчить на специальной терке для корейских салатов, но если ее нет, то на обычной крупной, пересыпать к капусте, добавить приправу, раздавленный прессом чеснок и порубленную петрушку.','https:https://st.vkuso.ru/data/cache/thumb/87/1585e17bf1e2e87_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9031,'Дать закуске цветная капуста с морковкой, маринованная по-корейски постоять в холодильнике не менее 6 часов, а лучше оставить там на всю ночь.','https:https://st.vkuso.ru/data/cache/thumb/c2/baab4fc3d9abfc2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9031,'Утром капусту уже можно будет пробовать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9032,'Порезать мясо поперек волокон, каждый кусочек должен весить приблизительно сто грамм. Обильно посыпать апельсиновым перцем. В горячую сковороду добавить сливочное или оливковое масло, разогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9032,'Положить кусочки мяса, жарить до аппетитной корочки. Когда образуется корочка, посыпать солью. Налить бульон, бальзамический уксус, вино. Довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9032,'Положить лист малабарской корицы. Убавить огонь, накрыть крышкой, готовить на маленьком огне минут шестьдесят. Подавать острую говядину в красном вине с гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9033,'Раскатать тесто в тоненький большой круг, в середине сделать надрезы, по диаметру намазать смесью майонеза и кетчупа, положить начинку. Начинка может состоять из ветчины, грибов, жаренных с луком, помидоров, сыра, соли, приправы для пиццы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9033,'Из середины уголки теста завернуть на начинку, будет схоже с короной. Готовить до зарумянивания теста, соблюдать температуру 180 градусов. Достать из духовки, порезать королевскую пиццу на кусочки, на каждом куске сверху должен быть уголок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9034,'Соединить в миксере масло, мед, яйца, пахту. Взбивать минуты четыре, до состояния воздушности. Положить банановое пюре, размешать. Отдельно соединить сухие продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9034,'Медленно ввести в банановую смесь сухую, чередовать с черникой. Размешать до однородности. Обжарить банановые блины с черникой на масле до золотистой корочки со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9035,'Развести не крутое, очень мягкое тесто. Отправить в тепло, чтобы поднялось. Обмять. Отрезать кусок теста, обвалять в муке, раскатать в колбаску, порезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9035,'Обмять в муке, чуть-чуть раскатать скалкой. Должно получиться четное число кусочков. На кружочек положить начинку. Накрыть вторым кружочком. Лишнее обрезать стаканом. Плотно скрепить краешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9035,'Положить пончики в кастрюльку или глубокую сковороду с горячим маслом. Жарить с двух сторон. Обязательно следить за температурой масла, чтобы оно не было очень горячим, так как пончики снаружи могут сгореть, а внутри не пропечься.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9035,'Достать, положить на полотенце, чтобы масло стекло. Подавать пончики «Вкуснющие» горячими, посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9036,'Постелить в формочку пищевую пленку, слоями выложить ингредиенты, все слои промазывать майонезом. Перед подачей формочку перевернуть, пленочку убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9036,'Слои: потертая отваренная печень, тертые отваренные яйца, мелко порезанные огурчики, отваренный рис, тертая отваренная морковь, тертый адыгейский сыр, зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'В сыр добавить взбитые сливки и немного взбить миксером.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9037,'Залить водой луковицу, стебли укропа и петрушки, соль, пряности для рыбы, вскипятить. В данном бульоне минут десять отваривать филе минтая, порезанное на порционные кусочки, после повторного закипания сделать огонь минимальным. Достать рыбу. Убрать бульон с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9037,'Разогреть на сковороде сливочное масло, обжарить муку, положить сметану, насыпать перец, сахар, разбавить процеженным бульоном до необходимой консистенции соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9037,'Взбить желтки, хрен, уксус, зелень с помощью блендера. Осторожно ввести в соус, убрать с огня. Залить отваренного минтая соусом, плотно закрыть, минут на десять отставить, чтобы рыба обогатилась ароматами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Для приготовления блинного теста необходимо смешать муку, сахар, щепотку соли, молоко,  яйцо и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Испечь из него 9 блинов, края которых обрезать по тарелке (диаметр ее должен быть меньше диаметра блинов на 10-20 мм).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Взбить в крем сливки (35%) вместе с сахарной пудрой, аккуратно перемешать с творогом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Собрать торт следующим образом: 1-й, 2-й и 3-й блины смазать кремом, 4-й блин – джемом, 5-й, 6-й и 7-й блины – опять промазать кремом, 8-й – как и 4-й, джемом, 9-й – кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Бока торта промазать кремом и на 2 часа убрать его в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'На 5 минут залить миндаль кипятком, после чего снять с него кожицу и не очень мелко измельчить при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Воду смешать с сахаром и крахмалом, сварить кисель, в который за пару минут до готовности добавить корицу, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9038,'Готовым киселем залить блинный торт с творожно-вишневым кремом, украсить измельченными ореха и опять поставить в холод, но уже на 1 час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9039,'Взять вареные яйца, разрезать, чтобы получилось две части: 1/3 часть - толстая, 2/3 – тонкая. Тоненькая часть будет шляпкой гриба, толстая – ножкой. Вынуть из яйца желток и положить в отдельную посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9039,'Сделать крепкий чай, бросить в него шляпки, дать им покипеть минут пятнадцать. Чай сделает шляпки коричневыми. Вкус от этого не изменится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9039,'Приготовить начинку: положить к желткам майонез и печень трески. Размешать, используя вилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9039,'Нафаршировать «Грибочки-боровички» начинкой и накрыть коричневыми шляпками. Если отверстие от желтка маленькое, то его можно осторожно увеличить ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9040,'Порезать куриное филе на большие кубики. Быстро обжарить на горячей сковороде. Порезать лук, сладкий перец и морковь на маленькие кубики. Разогреть на сковороде масло, обжаривать порезанные овощи минут семь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9040,'Налить соевый соус. Положить томатную пасту, тушить все вместе минут пятнадцать. В конце положить чили, прессованный чесночок. Положить куриное филе. Размешать, держать на огне минуты три.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9040,'Посыпать зеленью, посыпать перцем, солью. На гарнир к курице в кисло-сладкой соусе подавать отварной рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9041,'Влить в фарш молоко, перемешать, убрать на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9041,'Добавить специи, еще раз перемешать, заполнить фаршем кондитерский шприц или п/э пакет, срезать у него уголок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9041,'На прямоугольник из пищевой пленки выдавить «колбаску» фарша, осторожно свернуть, концы плотно завязать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9041,'Закипятить воду, положить домашние куриные колбаски с молоком, варить 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9042,'Перемешать (не взбивать!) сгущенку с яйцами, смешать с просеянной подсоленной мукой, ванилином и разрыхлителем, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9042,'Притрусить стол мукой, положить тесто, раскатать в сантиметровый пласт. Двумя подобранными формами, например, рюмкой и стаканом вырезать кольца.','https:https://st.vkuso.ru/data/cache/thumb/55/b2e64206971f555_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9042,'В кастрюльке разогреть масло, опустить в него любую деревянную палочку, если появятся пузырьки, то уже можно жарить пончики из сгущенки без дрожжей, одновременно опускать по 3-4 штуки, жарить до появления золотистой корочки со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/87/883ceb9719b9d87_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9042,'Пончики выловить, уложить на тарелку, выстланную салфетками, дать впитаться маслу.','https:https://st.vkuso.ru/data/cache/thumb/c9/9828fb8253f17c9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Добавить шоколадную стружку, перемешать массу до однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9042,'Переложить пончики на блюдо, присыпать сахарной пудрой, часть можно окунуть в растопленный шоколад, а потом присыпать стружкой кокоса и дать полчаса постоять.','https:https://st.vkuso.ru/data/cache/thumb/89/ae8ebaa58b0f089_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9043,'Растопить в кастрюльке масло или маргарин, налить холодную воду, насыпать соль и соду на кончике ножа, кипятить, не убирая с огня, насыпать муку, размешать. Когда тесто заварится, убрать с плиты, вбить яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9043,'Выкладывать тесто с помощью большой ложки на противень, намазанный маслом и присыпанный мукой. Отправить в разогретую до 220 градусов духовку, готовить минут пятнадцать. Когда пирожные поднимутся, уменьшить огонь до 200 градусов, готовить еще минут пятнадцать. Открыть дверцу, позволить готовому изделию чуть-чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9043,'Закипятить молоко и сахар, чуть-чуть остудить, положить сливочное масло (подтаявшее), хорошенько растереть. Пока пирожные остывают, отправить крем в холодильник. Осторожно надрезать пирожные и начинить кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9043,'Приготовить шоколадную глазурь: вскипятить воду с сахаром, растереть какао и масло. В масляную смесь тоненькой струей налить теплый сироп, размешать. Покрыть заварные пирожные с кремом глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9044,'Порезать свинину на кружки толщиной по несколько сантиметров толщиной. Завернуть мясо в полоску бекона, скрепить ниткой. Обжаривать на сковороде-гриль минуты по три с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9044,'Почистить, вымыть лук, разрезать вдоль на 4 части. Порезать сельдерей. Соединить сладкую горчицу, брусничный соус, оливковое масло, соль, соевый соус, перец, перемешать до однородности. Если соус очень густой, то налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9044,'Вылить соус на сельдерей и лук, размешать. Положить в формочку овощи в соусе, сверху положить свиные медальоны. Обдать кипятком апельсин, посушить, порезать на тоненькие кружочки. Положить апельсин в формочку. Посыпать перцем, солью, порезать измельченным чили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9044,'Готовить минут тридцать, соблюдая температуру 180 градусов. Каждые десять минут поливать медальоны соусом. Подавать медальоны из свинины с красным луком и беконом, посыпав зеленью. Нитки убрать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9045,'Нашинковать лук кольцами, уложить на дно формы, выстланной двумя слоями фольги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9045,'Клубни картофеля разрезать вдоль на 4 части, уложить на лук, присолить, присыпать специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9045,'Перемешать майонез (сметану) с солью, специями, окунуть в смесь голени, положить их на картофель.','https:https://st.vkuso.ru/data/cache/thumb/da/2a7b2ade00d69da_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9045,'Посыпать куриные голени крупно натертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/89/c667e2b481b1a89_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9045,'Накрыть форму фольгой, тщательно скрепить с нижним листом, запекать при 200 градусах примерно час.','https:https://st.vkuso.ru/data/cache/thumb/46/033055931a17946_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9046,'Поделить на две части молоко. Одну из них нагреть на огне до теплого состояния. Убрать с огня, медленно насыпать соль, сахар, муку, перемешать при помощи венчика до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9046,'В полученную смесь вбить яйца, размешать. Налить остальное молоко, чуть-чуть растительного масла, чтобы блинчики во время жарки не прилипали к сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9046,'Выпекать блины: смазывать сковороду маслом не нужно. Набрать блинную массу в половник, в другую руку взять сковороду, вылить содержимое половника на середину сковороды, вращать сковороду, чтобы тесто распределилось по всей поверхности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9046,'Перевернуть блин, когда его краешки подрумянятся. Для этого взять руками блин за краешек, быстро перевернуть, жарить секунд тридцать. Так готовить все блины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9046,'На середину каждого блинчика положить кусок сливочного масла, свернуть трубочкой. Отправить тонкие блинчики на молоке секунд на сорок в микроволновую печь при средней мощности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9047,'Измельчить в блендере орехи до крошки. Разделить зефир на половинки. У всех зефиров обрезать кончики, чтобы получилась плоская форма.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9047,'Приготовить заварной крем: смешать яйца, сахар, чуть-чуть взбить, используя венчик. Налить молоко, постоянно мешать, не давать закипеть. Варить до густого состояния. Остудить. Взбить чуть-чуть масло миксером. Не переставая взбивать, медленно добавить молочно-яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Кастрюлю вновь поставить на огонь, влить сливки, посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9047,'Взять разъемную формочку, постелить специальную пленку. На дно положить половинки зефира, постараться заполнить все отверстия обрезками от зефира. Намазать зефир холодным заварным кремом. Посыпать орехами, утрамбовать их.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9047,'Положить вновь слой зефира, намазать кремом, снова посыпать орехами. Утрамбовать все слои, чтобы получился плотный тортик. Третий слой тортика (последний) тоже намазать оставшимся заварным кремом, посыпать измельченным печеньем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9047,'Утрамбовать, украсить по желанию. Сверху торт из зефира затянуть пленкой, отправить в холодное место на 24 часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Обжарить или потушить курицу, дать остыть, мелко порезать.','https:https://st.vkuso.ru/data/cache/thumb/a6/7bef8feea85c4a6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Натереть замороженный сырок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Натереть на тёрке яйца.','https:https://st.vkuso.ru/data/cache/thumb/b3/b41468c93e0d4b3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Порубить мелко чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Перемешать все продукты с майонезом и соевым соусом.','https:https://st.vkuso.ru/data/cache/thumb/40/c008ce5f67ea440_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Смазать смесью лаваш.','https:https://st.vkuso.ru/data/cache/thumb/55/dc65a3980266b55_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9048,'Свернуть лаваш в трубочку, отправить Рулеты из лаваша с куриным филе, яйцом и плавленым сырком в холодильник примерно на час, пусть хорошо пропитаются, достать, порезать на небольшие рулетики.','https:https://st.vkuso.ru/data/cache/thumb/a4/155cd41e62b42a4_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9049,'Приготовить соус: соединить все компоненты и сок половины лимона. Порезать на порционные куски ребрышки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9049,'Положить в посуду, залить приготовленным соусом. Отставить часа на три в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9049,'Разложить на противне, готовить на гриле или в духовке, полить свиные ребрышки остатками соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9050,'Разрезать лаваш на квадраты, сыр – на пластинки, для кляра перемешать майонез с яйцами, крахмалом и солью.','https:https://st.vkuso.ru/data/cache/thumb/b4/73b8cacc6383ab4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9050,'Уложить пластинки сыра на лаваш, свернуть в форме конвертиков.','https:https://st.vkuso.ru/data/cache/thumb/18/b2a045eaf818618_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9050,'Хорошо разогреть в сковороде масло, каждый конвертик обмакнуть в кляр, а затем обжарить сырные конвертики из лаваша по минуте (примерно) с каждой стороны.','https:https://st.vkuso.ru/data/cache/thumb/96/6d980bc69d21c96_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9050,'Подавать в горячем виде.','https:https://st.vkuso.ru/data/cache/thumb/19/903f198952d5c19_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9051,'Выложить тесто на противень, на него положить начинку, завернуть, как конвертик. Сначала картофель, на него мясо, сверху положить лук, сливочное масло, порезанное на большие куски. Масла положить побольше, тогда пирог будет вкусный и сочный. Чтобы пирог был ароматный добавить лавровый листик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9051,'Закрыть конверт, намазать желтком, сделать проколы вилкой в двух местах, отправить в духовку приблизительно минут на шестьдесят, соблюдать 200 градусов. Минут через тридцать уменьшить температуру до 160 градусов. Порезать греческий пирог «Кубите» на кусочки, можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9052,'Сделать «бер нузает». Во время кипячения масла соединить в посуде муку, миндаль, мед, сахар и белки. Позволить маслу чуть-чуть остыть, добавить в миндально-мучную массу (все время мешать). Размешать хорошенько, положить шоколад, вновь размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9052,'Тесто положить в кондитерский мешочек, выдавить в формочки для мини-маффинов, чтобы они были наполнены на 2/3. Готовить в духовке минут тридцать. Печенье должно стать золотистым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9052,'Приготовить помадку: соединить в маленькой кастрюльке молоко и напаж, довести до кипения, убрать с плиты, положить измельченный шоколад, он должен полностью быть покрыт сливками. Отставить секунд на шестьдесят, перемешать до однородности. Массу должна стать блестящей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9052,'Достать из духовки птифуры, позволить им остыть, достать из формочки, покрыть остывшей шоколадной помадкой. Отправить птифур «Финанcье» с шоколадом в холодильник, чтобы застыла помадка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9053,'В центр лаваша (диаметром 20 см) разбить яйцо, равномерно размазать его с помощью вилки от центра к краям.','https:https://st.vkuso.ru/data/cache/thumb/05/e087e94bd369705_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9053,'Посыпать тертым сыром, слегка поперчить, посолить.','https:https://st.vkuso.ru/data/cache/thumb/19/811781a23b2e819_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9053,'Сложить треугольничком.','https:https://st.vkuso.ru/data/cache/thumb/6f/f63be721d97ee6f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Довести кушанье до кипения, варить несколько минут на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9053,'Обжарить армянскую Ёку до золотистого цвета в разогретом сливочном масле, положить швом вниз, а затем перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/2d/910e9660e63002d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9053,'Сразу подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/50/93ec98f7d5a4650_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9054,'Отварить макароны, как написано на упаковке. Измельчить чесночок и лук. Обжарить до золотистости на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9054,'Положить фарш, налить сливки. Если используется сырой фарш, то обжарить его до полной готовности, не переставая помешивать, разделять комочки при помощи деревянной лопатки, должна исчезнуть краснота мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9054,'После этого добавить сливки. Хорошенько размешать, тушить минут десять на минимальном огне, чтобы сливки не закипели. Положить томатную пасту, соус, орегано, петрушку. Перемешать. Тушить минут десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9054,'Посыпать перцем, солью, положить мускатный орех, размешать. Фарфалле с соусом «Болоньезе» можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Нарезать грибы, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Помидоры и лук порезать на полукольца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Высыпать к грибам лук, жарить до готовности, переложить на тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Порезать мясо на пласты шириной примерно по полтора см, накрыть пленкой, отбить с одной и другой стороны через пленку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Застелить противень пергаментом, разложить отбивные, смазать их горчицей, присолить, поперчить.','https:https://st.vkuso.ru/data/cache/thumb/7c/7d45eb418c67a7c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Уложить поверх грибы.','https:https://st.vkuso.ru/data/cache/thumb/d7/308c29a01e1b1d7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Прикрыть помидорами.','https:https://st.vkuso.ru/data/cache/thumb/5b/71e2b44fb04255b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Присыпать французские отбивные из свинины с грибами в духовке натертыми сырами (первый – адыгейский, второй – твердый сыр).','https:https://st.vkuso.ru/data/cache/thumb/e8/2eb5dabc7965ee8_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9055,'Отправить на 35-40 минут в духовку. Подавать отбивные горячими.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9056,'Взбить в блендере банан, положить сливочное масло, потом другие компоненты для блинов, взбить до однородности. Перелить тесто в посуду, накрыть пленкой, отправить минут на шестьдесят в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9056,'Холодное тесто взбить, обжаривать блинчики на горячей сковороде с двух сторон до румяного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9056,'Сделать начинку: взбить сливочный сыр до воздушности, медленно добавить йогурт, насыпать ванилин, сахар. Взбить до воздушной, однородной массы. Положить начинку между каждым блинчиком, оставшийся крем нанести на тортик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9056,'Сделать глазурь: взбить миксером сливки, сахар коричневый, масло в кастрюльке на средней скорости. Довести до кипения, огонь сделать тише, готовить минут десять, помешивать. Добавить соль, ванилин, измельченные орехи. Залить торт из банановых блинчиков глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9057,'Подогреть чуть-чуть кефир, главное не перегревать. Насыпать соль, сахар, налить растительное масло, размешать. Соду добавлять не нужно. Медленно насыпать муку. Тесто должно получиться эластичным, но не тугим, поэтому муку насыпать небольшими порциями, а не сразу. Если тесто получится тугое, то не будет воздушных пузырьков, которые делают тесто невероятно вкусным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9057,'Разделить соду на три части. Посыпать стол мукой, раскатать тесто в пласт, имеющий толщину 1 сантиметр. Одной частью соды равномерно посыпать тесто. Сложить тесто в три слоя. Сложить 1/3 часть с одной стороны, потом с другой. После этого еще в три слоя. Получится сверток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9057,'Снова его раскатать, чтобы толщина была 1 сантиметр, посыпать второй частью соды, снова сложить. Еще раз раскатать и повторить процедуру. В результате три раза раскатать тесто, посыпать содой и сложить. Тесто после каждого раза будет пористей и пышней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9057,'Готовое тесто накрыть пакетом или какой-нибудь посудой, отставить минут на сорок, чтобы поднялось. В это время приготовить начинку и можно приступать к жарке. Чтобы бездрожжевое тесто на кефире было пышным, не нужно его сильно мять, обращаться с ним следует нежно и аккуратно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9058,'Очистить киви от кожуры, порезать на пластинки по 1 сантиметру толщиной. В каждый кусочек фрукта воткнуть палочку для мороженого.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9058,'Растопить шоколад. Положить в шоколад корицу. Каждый кусочек фрукта окунуть в растопленный шоколад.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Подать к столу горячим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9058,'Отправить десерт в морозилку минут на пятнадцать, чтобы застыл шоколад. Выложить киви в шоколадной глазури на блюдо и подавать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9059,'Соединить тмин, соль, розмарин, орегано. Положить ножки на противень, обильно посыпать смешанными приправами. Запекать мясо до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9059,'Отмерить масло. Положить в него измельченную петрушку. Измельчить чесночок. Положить потертый пармезан, размешать. Полить соусом курицу. Отправить куриные ножки с чесноком и сыром минут на семь в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Взбить сливочное размягченное масло до однородности с перцем, творогом и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Промытый и очищенный картофель порезать довольно тонкими кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Смазать форму маслом, в нее выложить 1/3 нарезанного картофеля, а на него – 1/3 творожной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Далее снова 1/3 часть картофеля, наверх 1/3 творога, опять оставшийся картофель и творог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Разровнять самый последний слой влажной лопаточкой, накрыть фольгой, хорошо подоткнуть края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'В духовку, разогретую до 190 градусов, поставить форму и запекать блюдо на протяжении 1 часа 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'По прошествии времени форму из духовки достать, фольгу снять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Йогурт  (использовать натуральный без добавок) взбить в легкую пену с перцем, яйцами и солью, получившейся заливкой покрыть картофель.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9060,'Температуру в духовке убавить до 180 градусов и поместить форму обратно еще на 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9061,'Сделать опару. Растворить дрожжи и сахар в теплом молоке, насыпать муку, вымесить, отправить в тепло, чтобы увеличилось в два раза. Соединить желтки, сахар, растереть добела.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9061,'В опару насыпать соль, добавить сахарно-желтковую массу, остальную муку и растопленное масло. Хорошо вымешать, пока тесто не начнет отставать от стенок. Чтобы тесто собралось в кучу, можно намазать руки растительным маслом. Накрыть емкость с тестом полотенцем, отправить в тепло часа на полтора. За это время один раз его обмять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9061,'Сделать намазку. Отварить и потолочь картофель, добавить молоко, сливочное масло, взбить в негустое пюре. На одну шанежку должна уйти одна маленькая ложка с горкой пюре. Шанег будет двенадцать штук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9061,'Намазать противень сливочным маслом. Сформировать из теста шаньги. Оторвать кусочек, как большое куриное яйцо, скатать плотный шарик, размять пальцами лепешку диаметром сантиметров десять. Положить на противень, отставить минут на двадцать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9061,'Обмазать лепешки пюре, используя маленькую ложечку. Разболтать вилкой сметану, с помощью кисточки намазать тоненьким слоем картофель. Отправить уральские картофельные шаньги минут на пятнадцать в духовку, соблюдать температуру 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9062,'Разогреть духовку. Отварить пасту, как написано на упаковке. Растопить в сковороде сливочное масло, налить бульон, насыпать специи, добавить пармезан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9062,'Положить ветчину, порезанную соломкой, петрушку, перемешать пасту с соусом. Положить в формочку для запекания. Сверху разбить яйца, посыпать чеддером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9062,'Готовить запеченную пасту с ветчиной и яичницей минут двадцать, пока яйца не схватятся.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9063,'Взять филе, сбоку сделать надрез, будет похоже на кармашек. Положить в «кармашек» порезанный сыр, чуть-чуть специй. Чтобы не вытек сыр, краешки осторожно сделать прокол и скрепить зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9063,'Посыпать мясо специями. Можно чуть-чуть посыпать филе солью, перцами, травами. Взять полоску бекона, завернуть ими филе по спирали, чтобы мясо было закрыто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9063,'Переложить куриное филе с беконом и сыром  в глубокую формочку, выпекать минут шестьдесят, соблюдать температуру 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9064,'Почистить картофель, порезать на соломку по пять миллиметров. Взбить яйца. Слить с тунца жидкость, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9064,'На сковороде нагреть масло (растительное), пожарить омлет, помешивать. В том же масле обжарить картофель, положить тунец. Положить обратно яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9064,'Посыпать специями. Подавать жареный картофель с омлетом с кетчупом или соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Из всех еще горячих половинок удалить маленькой ложкой немного мякоти, чтобы получилось небольшое отверстие.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9065,'Обжарить свиной фарш на горячей сковороде. Почистить и мелко порезать лук, натереть морковь. Спустя тридцать минут положить морковь и лук в фарш, накрыть крышкой, тушить минут десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9065,'Нагреть воду в маленькой кастрюльке, после закипания осторожно опустить «гнездо» минуты на полторы, положить все на противень. В гнезда положить приготовленную начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9065,'Нагреть духовку, в противень налить чуть-чуть воды (приблизительно до середины макарон), отправить минут на тридцать. Во время запекания макарон, потереть сыр. Спустя тридцать минут достать из духовки противень, посыпать тальятелле по-флотски сыром, отправить еще минут на пять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9066,'Вбить в кефир яйцо, насыпать соль, сахар, добавить растительное масло, размешать. Просеять муку, насыпать соду, перемешать, высыпать в кефирную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9066,'Замесить мягкое тесто, подсыпать муку, чтобы тесто стало мягким и держало форму. Оно должно чуть-чуть липнуть к рукам. Нельзя насыпать очень много муки, так как хачапури будут жесткими. Накрыть тесто салфеткой и отставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9066,'Крупно потереть сыр, вбить яйцо, размешать. Из теста сделать колбаску, разрезать на девять частей. Сделать лепешки. На середину каждой лепешки положить сырную начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9066,'Собрать края в середине, подтягивая, слепить. Получившийся мешочек перевернуть, чуть-чуть раскатать, перевернуть, раскатать не сильно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9066,'Готовить хачапури на горячей сковороде без масла с двух сторон до золотистости. Чтобы лучше пропеклись, накрыть крышкой. Намазать тбилисские хачапури сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9067,'В маленькой емкости взбить соевый соус, имбирь, сок лайма. Отставить в сторону. Разогреть на сковороде масло на небольшом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9067,'Посыпать перцем, солью стейки тунца, положить на горячую сковороду. Жарить на одной стороне стейки минуты четыре, перевернуть, жарить столько же еще четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9067,'Приготовить соус, наклонять сковороду, чтобы он растекся по всей сковороде. Тушить стейки в соусе секунд тридцать, перевернуть на другую сторону, тушить еще секунд тридцать, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9067,'Сделать гарнир. Смешать порезанные огурцы и помидоры. Заправить кунжутным маслом, уксусом, перцем, солью. Подавать стейк из тунца со свежими овощами, украсив измельченным зеленым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9068,'На сковороде на масле на небольшом огне обжарить лук, измельченный перец, хлопья красного перца. Обжаривать минуты четыре до прозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9068,'Соединить данную смесь с оливками, добавить масло. Перемешать, насыпать соль, добавить сок лимона. Хранить острые оливки в холодильнике в герметичной емкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9069,'Разогреть духовку. Порезать куриное филе вдоль на маленькие отбивные, посыпать перцем, солью, накрыть пленочкой, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9069,'Можно использовать какие угодно грибы, например, лисички. Если необходимо отварить грибы и порезать. Пожарить на растительном масле, посыпать перцем, солью. Положить к грибам, порезанный лук, пожарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9069,'Налить сливки или сметанку, довести до кипения, снять с огня. Почистить помидоры от кожуры, порезать на полукольца или кольца. Уложить в формочку куриное филе, на него положить грибы с соусом, сверху помидоры, зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9069,'Сверху положить порезанные маслины, посыпать сыром. Готовить минут двадцать. Готовое куриное филе с грибами и маслинами украсить зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Любым удобным способом взбить сахар с яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'В яично-сахарную массу добавить сливочное, предварительно размягченное масло, ванильный сахар, сметану и все еще раз тщательно взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Муку просеять, перемешать с разрыхлителем, постепенно подмешать в масляно-яичную массу, замесить упругое и мягкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Полученное тесто разделить на желаемое количество небольших кусочков, после чего скатать каждый кусок в шарик.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Пополам разрезать каждый тестяной шарик, выложить все заготовки на заранее смазанный маслом растительным противень, на небольшом друг от друга расстоянии.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Поставить противень в духовку на 20 минут при 200 градусах, после чего достать половинки из духовки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11809,'Картофель нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'В «ямки» положить чуть-чуть вареного сгущенного молока, проделать то же самое с остальными заготовками, затем посредством сгущенки склеить между собой по две половинки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Чтобы украсить печенье «Персики» с вареным сгущенным молоком, необходимо натереть на терке сырую морковь и свеклу. В 2 слоя сложить марлю, в середину поместить часть натертой свеклы и свернуть шариком, и то же самое сделать с морковью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9070,'Бока печенья подкрасить подготовленными морковными и свекольными марлевыми шариками, посыпать готовые изделия сахаром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9071,'Помыть вешенки, осторожно освободить от стебля, постараться не оставлять сильно длинных ножек. Если шляпки очень большие, то разрезать их вдоль на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9071,'Уложить грибочки в посуду, подходящую по объему (например, в кастрюлю на пять литров). Положить сверху порезанный укроп, пряности: зерна гвоздики, перец горошком. Налить воду практически до верхних краев кастрюльки, поставить на плиту вариться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9071,'Когда вода закипит, насыпать сахар и соль. Перемешать, позволить рассолу закипеть, добавить уксус. Оставить вариться на тихом огне минут на тридцать. Вешенки не нуждаются в термической обработке, как лесные грибочки. Главное во время готовки пробовать маринад на вкус, насыпать соль, чтобы он в результате был чуть-чуть пересоленный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9071,'Отставить кастрюльку в сторону, позволить грибам остыть, переложить в стеклянную баночку. Выловить из маринада пряности, укроп, тоже положить в банку, налить маринад, чтобы он чуть-чуть прикрыл грибочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9071,'Остальной маринад вылить. Гнет не нужен. Необходимо только ложкой немного примять грибы в банке. Закрыть банку крышкой, отправить в холодильник. Спустя 24 часа маринованные вешенки будут готовы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9072,'Отварить филе и яйца. Порезать на кубики. Порезать на кубики яблоки и сыр. Разрезать виноградинки пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9072,'Смешать приготовленные ингредиенты, заправить салат из куриного филе майонезом, осторожно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9073,'В молоко насыпать желатин, варить на небольшом огне, непрерывно мешая. Не позволять закипеть. Убрать с плиты, остудить. Отдельно взбить сметану, сливки, сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9073,'Медленно добавить молоко с желатином. Намазать маслом стеклянную формочку, положить половину крема. В остальную часть добавить чуть-чуть красителя. Положить вторым слоем. Отправить в холодильник минут на тридцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9073,'Растворить желе в кипятке. Отставить, чтобы остыло до комнатной температуры. Залить им остывшее суфле. Отправить торт-суфле «Птичье молоко» в холодильник часа на два, чтобы желе полностью застыло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9074,'Приготовить тесто. Измельчить в блендере какао, соль, орехи в пыль, положить в блендер финики без косточек, взбить до однородности. Поделить тесто на две части. Завернуть в пленочку, отправить в холодильник для охлаждения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9074,'Сделать глазурь. Взбить до однородности авокадо, финики без косточек, сироп агавы, насыпать какао, взбить. Положить один слой теста на формочку для пирога со съемными бортами, утрамбовать. Положить пару ложек шоколадной глазури, перетертые ягоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9074,'Осторожно сверху положить второй слой теста. Снять с формочки бортики, распределить по поверхности глазурь. Положить на шоколадный торт с финиками несколько веточек смородины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9075,'Пока размораживается тесто, залить мак крутым кипятком, отставить, чтобы набух. Вымыть и замочить изюм. Когда разморозится тесто, чуть-чуть раскатать его или растянуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9075,'Взбить сахар и белок, процедить мак, положить в белки, перемешать. Положить данную смесь на тесто, посыпать изюмом, можно посыпать чуть-чуть сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9075,'Свернуть рулетик, порезать на небольшие куски, позволить немного постоять. Намазать желтком, соединив его с молоком, чуть-чуть посыпать маком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9075,'Положить булочки с изюмом и маком на противень, отправить минут на восемнадцать, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9076,'Положить в кастрюльку подготовленную чернику, залить горячим семидесятипроцентным сиропом из сахара и воды(700 г сахара на 300 мл воды), отставить часа на четыре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'Руками порвать листья салата, измельчить укроп, петрушку и зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9076,'Готовить на тихом огне, убирая пенку. В конце добавить лимонную кислоту. Разлить варенье из черники в прогретые баночки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9077,'Чуть-чуть подогреть конфеты, чтобы они раскатывались как тесто. Для этого подержать пару секунд без обертки в микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9077,'Из каждой конфеты сделать тонкий пласт, с помощью рюмочки вырезать круги, как на пельмени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9077,'Из кружков сформировать розочки на шпажке. Кружки – это лепесточки, а шпажка – стебель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9078,'Порезать тоненько помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9078,'Порезать моцареллу, вставить в надрезы с базиликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9078,'Сбрызнуть салат маслом, посыпать перчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9079,'Растопить маргарин. Просеять разрыхлитель и муку. Перетереть муку и дрожжи. Вбить яйца, положить маргарин, налить молоко. Замесить тесто, положить в пакет, отправить часа на два в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9079,'Разогреть духовку. Поделить тесто на пять частей. Насыпать горочкой сахар с корицей (корицу можно не добавлять). На сахар положить кусок теста, раскатать лепешку толщиной миллиметров пять. Порезать на части, свернуть рогаликом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9079,'Можно использовать начинку, например, мармелад, конфеты джелли. Положить на тесто, скрутить. Положить сахарные рогалики на противень, готовить минут двадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9080,'Порезать томаты на небольшие кубики. Раздавить маслины или разрезать на две части. Почистить рыбку от кожи и косточек. Измельчить петрушку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9080,'Разогреть масло на среднем огне, минуты две обжаривать измельченный чесночок. Положить рыбу, порезанную на большие кусочки. Обжаривать до румяного цвета, стараться, чтобы куски были целыми. Посыпать перцем, солью, полить вином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9080,'Одновременно поставить вариться спагетти. Когда выпарится вино, положить помидоры. Тушить минут десять, добавить каперсы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9080,'Перемешать петрушку и маслины, делать это аккуратно, чтобы рыба осталась целой. Когда сок чуть-чуть выпарится, аккуратно выложить содержимое на пасту. Пасту с белой рыбой и каперсами можно подавать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Тесто сделать предварительно и раскатать на специальной бумаге. Вместе с бумагой свернуть тесто в трубочку, завернуть в полиэтилен, отправить в холодильник. Чтобы не тратить силы и время, можно купить готовое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Тесто делается следующим образом: соединить муку, соль и сахар. Положить кусочки масла, размешать руками. Налить воду, перемешать. Сделать шар из приготовленного теста, завернуть в пленку, отправить на тридцать минут в холодильник. Раскатать тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Растопить масло на сковороде, насыпать сахар, ждать карамелизации. Вылить горячую карамель в формочку, предварительно намазав маслом бортики. Существуют специальные формочки, предназначенные для перевернутых пирогов. Они слегка сужаются в глубину и имеют бортики, чтобы легче было переворачивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Порезать бананы на кружочки, каждый кружочек по 1 сантиметру. Выложить их в формочку на карамель (не имеет значения - остыла она или нет). Положить сверху тесто. Лишнее тесто обрезать по бортикам формочки. Убрать края в форму по кругу, проткнуть тесто вилкой в двух местах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Поставить в духовку минут на двадцать, соблюдать температуру 190 градусов. Когда тесто приобрело румяный оттенок, пройтись ножом по краям формочки, чтобы убедиться, что пирог не прилип, накрыть формочку тарелкой, перевернуть. Часть карамели впитается в бананы, остальная осталась на пироге.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9081,'Когда банановый тарт остывает, образуется тоненькие хрустящие ниточки. Можно приготовить шоколадный соус, но без него тоже вкусно, так как пирог уже сладкий.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9082,'Крупный репчатый лук нарезать, спассеровать на сковороде с небольшим количеством воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9082,'Помидоры ошпарить, снять кожицу, мякоть натереть и добавить в лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9082,'Плоды кабачков нарезать кубиками, если они молодые, то кожицу можно не снимать. Положить в обжарку, добавить томатную пасту, перец чили и соль, тушить в течение 20 – 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9082,'В готовое рагу переложить заранее отваренную или консервированную фасоль, рубленый чеснок и зелень петрушки и укропа – по вкусу. Тушить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Свежие белые грибы вымыть, два оставить для украшения блюда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9083,'Чернослив без косточек, изюм, инжир и курагу хорошо промыть замочить на полчаса в кипятке. Набухшие продукты обсушить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9083,'На сухой раскаленной сковороде обжарить овсяные хлопья, переложить в миску, перемешать с мёдом. Если мед густоват, его можно растопить на водяной бане.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9083,'Все ингредиенты перемешать, залить холодным нежирным кефиром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9084,'Куриную грудку вымыть, нарезать длинными брусками средней толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9084,'Залить мясо нежирным кефиром, добавить приправы, соль, оставить для маринования в холодильнике на час или два.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9084,'Мелкую овсянку смешать с сухими травами и паприкой. Если в наличии крупная овсянка, то её можно размолоть, но не доводить до состояния муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9084,'Замаринованное мясо обвалять в овсяной смеси,  выложить на противень или в емкость для запекания, поставить в разогретую духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9084,'Готовить в течение 20 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9085,'Очистить и нарезать кусочками спелый банан, добавить ягоды клюквы, молоко и лёд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9085,'Смесь взбить до однородности, подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9086,'Натереть на терке  крупное, сочное, сладкое яблоко, добавить пшеничную муку, сахарный песок, белок одного яйца, смесь перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9086,'Выложить массу в стопки или в небольшие стеклянные пиалы, поставить на полторы минуты в микроволновку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9086,'При подаче перевернуть формочки на блюдо, полить мёдом, посыпать молотой корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9087,'Ополоснуть под проточной водой грибы и куриное филе, обсушить бумажным полотенцем, измельчить. Мелко порубить петрушку и лук. Крупно потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9087,'Разогреть на сковороде сливочное и растительное масла, обжарить мясо до румяной корочки, посыпать перцем, солью. Положить мясо на тарелочку. В той же сковороде чуть-чуть обжарить лук, положить грибы, тушить, пока выпарится жидкость, посыпать перцем, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9087,'Положить мясо в сковороду, положить сметанку, тушить минут десять на тихом огне. Срезать у булочек верхушку, убрать мякоть, оставить не очень тоненькие стенки. Положить в булочку приготовленный жульен. Соединить сыр и петрушку, посыпать сыром и петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9087,'Положить булочки на противень, готовить минут двадцать в духовке, соблюдать температуру 170 градусов. Переложить жульен с курицей и грибами в булочках на тарелки. Подавать в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9088,'Порезать кальмары. Соединить в отдельной посуде муку, перец и соль. Отдельно в содовой замочить минут на десять кольца кальмаров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9088,'Соединить чесночный соус чили, мед, масло кунжутное. В кастрюльку налить масло приблизительно на пять сантиметров, нагреть масло. Каждое колечко кальмара обмакнуть в муку с перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9088,'Жарить минуты две, достать на бумажное полотенце, чтобы масло стекло и кольца кальмаров остались хрустящие.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9089,'Взбить с помощью вилки яйца, сметану, муку, майонез, соль. Порезать продукты для начинки. Потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9089,'Вылить тесто на смазанную сковороду, выровнять, разложить помидоры, сверху перец и лук, на них мясо(можно брать любое, на ваш вкус), посыпать сыром. Накрыть пиццу крышкой, готовить минут двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Очистить, вымыть и натереть на мелкой терке сочную морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Добавить сырые куриные яйца, цедру половины лимона, лимонный сок, молотую корицу по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Всыпать манку (до консистенции густой сметаны), влить погашенную уксусом пищевую соду, влить мёд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Массу перемешать и поставить в духовой шкаф на 40 – 50 минут, температура – 180 градусов. Готовность коржа проверить с помощью зубочистки или спички, они должны остаться сухими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Грецкие орехи запечь в духовке при температуре 160 градусов, вынуть, посыпать солью в горячем виде, положить немного сливочного масла, перемешать и измельчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Перемешать любой творожный сыр, например, «Хохланд» или «Маскарпоне», с грецкими орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Собрать торт, если корж толстый, то его нужно разрезать по горизонтали острым ножом на несколько частей или выпечь тонкие коржи, чтобы их не нужно было резать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9090,'Промазать выпечку творожным кремом, каждый слой посыпать солеными орешками. Дать блюду пропитаться и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9091,'Вымыть яблоки, очистить от кожуры, удалить семенные камеры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9091,'Натереть мякоть на терке или измельчить в пюре с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9091,'Залить массу охлажденным кефиром, взбить с помощью миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9091,'Добавить в коктейль молотую корицу и мёд, еще раз взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9091,'При подаче разлить полученную смесь в бокалы, украсить ломтиками яблок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9092,'Натереть на крупной терке очищенные клубни картофеля, репчатый лук, твердый сыр ветчину или любые другие колбасные изделия.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9092,'Вбить в массу сырые куриные яйца, всыпать муку и рубленую зелень укропа. Соль и перец молотый – по вкусу. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9092,'Выкладывать смесь на сковороду с растительным маслом ложкой, придавая изделиям форму оладий.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9092,'Жарить до золотистой корочки с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9093,'Растопить и остудить масло. Взбить яйца и сахар, положить сметану, соду, маргарин, муку. Положить тертые яблоки, осторожно размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9093,'Положить тесто в формочку, намазанную маслом и посыпанную сухариками. Готовить кекс на сметане минут пятьдесят, соблюдать температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Приготовить безе: нагреть духовку до 175 градусов. Нарисовать с помощью карандаша на бумаге для выпечки круг в двадцать сантиметром диаметром, положить на противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Для приготовления безе взбить с помощью миксера белки. Медленно насыпать сахар. Не переставать взбивать, пока не образуются устойчивые пики. Убедиться, что растворился весь сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Осторожно ввести в смесь крахмал, вишневую водку, уксус, размешать. Положить на бумагу для выпечки безе, выровнять крем лопаткой по формочке, он должен поместиться на круге, предварительно нарисованном. Сделать углубления для начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Убавить температуру в духовке до ста градусов, выпекать часа полтора до хрустящего сухого состояния. Выключить духовку, открыть дверцу, сушить еще часов пять, пока не остынет духовка. Достать безе, когда духовка полностью остынет, так как оно сломается и сядет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Приготовить начинку: с вишни слить сок, оставить несколько больших ложек. Замочить ягоды в емкости в соку и вишневой водке, пока безе сушится. Соединить сахар, творожный сыр, большую ложку водки. Взбить сливки до пиков. Осторожно ввести сливки в творожную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9094,'Когда будет готово безе, положить творожную начинку, на нее положить вишню в соку. Переложить торт Павлова «Черный лес» на блюдо, украсить и подавать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Хорошо промытую и очищенную от пленок говяжью или свиную печень пропустить через мясорубку, вбить сырое яйцо, влить молоко, всыпать пшеничную муку и соль, перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Полученный фарш раскатать в виде блинов и выпечь на смазанной жиром сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Для приготовления начинки натереть на крупной терке морковь, обжарить её вместе с измельченным луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Пропустить через пресс чеснок, перемешать его с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Каждый печеночный блинчик смазать чесночной смесью, прослоить обжаренными овощами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'На верхний блин положить только майонез с чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9095,'Дать блюду немного постоять для пропитывания и посыпать верх рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9096,'Помытую, очищенную, нарезанную морковь и картофель отварить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9096,'Когда овощи будут готовы, слить с них воду, любым удобным способом сделать картофельно-морковное пюре, вбить туда яйцо и положить сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9096,'Зеленый и репчатый лук мелко порезать. Выложить в миску шпроты (предварительно слив масло), с помощью вилки их размять, добавить подготовленный лук, петрушку и укроп, перец и соль, все хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9096,'Сформовать из приготовленного картофельно-морковного пюре шарики (диаметр каждого – 4,5 см), в середине каждого сделать углубление и поместить в него начинку (по 1 ч. л.), края сомкнуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9105,'Посыпать яичный коблер тертым сыром. Готовить в духовке, пока не подрумянится сыр и не приготовится омлет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9096,'Каждый получившийся шарик запанировать в муке, в разогретом масле обжарить картофельные биточки с зеленью и шпротами до подрумянивавшейся корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Духовой шкаф разогреть до 176 градусов, выложить очищенные грецкие орехи, печь в течение 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/e6/a81b291aa7f87e6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Продукт вынуть, остудить, разрезать на небольшие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'В емкости небольшого размера взбить при помощи миксера несоленое мягкое сливочное масло и сахарный песок до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/1f/3c6c4b8e2baf61f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Вбить яйцо, добавить ванильный экстракт, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Отдельно смешать соль, пищевую соду, молотую корицу и пшеничную муку.','https:https://st.vkuso.ru/data/cache/thumb/8e/78f762b90994a8e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Добавить сухую смесь в масляную, аккуратно соединить все ингредиенты. Всыпать готовые запеченные орехи и овес.','https:https://st.vkuso.ru/data/cache/thumb/bc/0e329581a15b0bc_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Для разделения теста использовать ложку для формирования мороженого. Чтобы масса не прилипала – смочить ложку водой.','https:https://st.vkuso.ru/data/cache/thumb/21/789bf058ef40721_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Печенье выложить на застеленный пергаментом противень на расстоянии в пять сантиметров друг от друга.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Шарики придавить сверху обычной чайной ложкой, также смоченной водой.','https:https://st.vkuso.ru/data/cache/thumb/8d/764209702ac6f8d_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9097,'Печь изделия в течение 13 минут до светло-золотистого цвета. Вынуть и  остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9098,'Помыть яблоки, почистить от кожуры. Удалить серединку. Порезать на дольки. Налить в кастрюльку чуть-чуть воды, чтобы она покрыла дно, положить яблоки и корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9098,'Накрыть крышкой, готовить на медленном огне минут пятнадцать, яблоки должны быть мягкими. Добавить сок половины лимона, насыпать сахар. Варить минут десять на тихом огне, затем взбить в блендере яблоки. Яблочный соус можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Соединить в емкости какао, муку, соль, соду. В другой посуде соединить соду, муку, соль. Отставить. Приготовить шоколадное тесто. Взбить сахар и маргарин. Вбить яйцо. Взбить до однородной массы. Смешать мучную смесь с какао и яичную. Замесить руками тесто, положить орехи. Помять, чтобы равномерно распределились орехи. Поделить тесто пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Сделать два бревнышка, положить на противень, застеленный пергаментом. Чтобы сократить время выпечки, сделать заготовки невысокими и широкими. Отправить противень в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Приготовить банановое тесто. Взбить сахар и маргарин, вбить яйцо, положить банановое пюре. Взбить до однородной массы. Насыпать в смесь соду, муку, соль, замесить. Если тесто очень жидкое, то насыпать еще чуть-чуть муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Приготовленное тесто поделить пополам, сделать форму бревнышек. Достать противень с миндально-шоколадными заготовками из холодильника. На шоколадное тесто положить банановое. Если свисают края, то срезать лишнее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Придавить чуть-чуть рукой, заготовку двух цветов отправить в духовку. Выпекать минут тридцать, соблюдать температуру 170 градусов. Поверхность двойных бискотти должна чуть-чуть потрескаться и стать румяной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9099,'Достать из духовки. Позволить минут пять остыть, порезать печенье острым ножом, чтобы была ширина 1 сантиметр. Выложить на противень, отправить минут на десять в духовку. Остудить печенье на решетке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Смазать сливочным маслом форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Нарезать очищенный картофель и выложить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Перемешать молоко и сливки, всыпать муку, соль, перец молотый, измельченный чеснок, перемешать и залить полученной смесью картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Прикрыть блюдо фольгой, печь в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Фольгу снять, подержать еще 20 – 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Перед подачей посыпать кушанье тертым сыром, подержать в духовке еще три-пять минут до расплавления продукта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9100,'Присыпать блюдо мелко нарезанным зеленым луком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'В кипящей воде не больше 5 минут поварить перепелиные яйца, затем их полностью остудить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'Под проточной водой помыть зелень и овощи, пополам порезать яйца и помидоры черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'Тонкими пластинами порезать помытые шампиньоны и обжарить грибы в сковороде с растительном масле до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'Для заправки смешать сок лимона, майонез, молотый перец, прованские травы и соль, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9101,'В большой салатник поместить все подготовленные ингредиенты и перемешать, полить салат лионский с томатами черри и шампиньонами заправкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Вешенки и репчатый лук мелко нарезать, жарить до золотистого цвета на растительном масле. Обжарку откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Измельчить зелень укропа, кинзы, петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Растереть брынзу вилкой или руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Чеснок раздавить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Все перечисленные ингредиенты соединить, соль и молотый перец – по вкусу, массу перемешать.','https:https://st.vkuso.ru/data/cache/thumb/75/f257bc4d1dc4275_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Отварить в кипящей воде в течение трех минут пасту каннеллони. Откинуть продукт на дуршлаг, затем разрезать поперек на две части.','https:https://st.vkuso.ru/data/cache/thumb/c3/8bef2cfc2a0e7c3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Каждую половинку наполнить грибным фаршем, переложить изделия в форму для запекания.','https:https://st.vkuso.ru/data/cache/thumb/68/b98eb3508093c68_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Для заливки соединить перепелиные яйца со сливками, массу взбить, посолить, добавить сухие травы, всыпать тертый сыр и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/dd/eddb94c1343d6dd_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Залить смесью каннеллони, верх посыпать остатками сыра.','https:https://st.vkuso.ru/data/cache/thumb/37/77d2e4b072be737_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9102,'Печь в заранее разогретой духовке в течение 40 минут. При подаче посыпать рубленой зеленью и еще одной порцией сыра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Сырое куриное филе тонко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Очищенный чеснок нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Перемешать куриное мясо с майонезом, чесноком, солью и молотым перцем, другими специями по вкусу. Дать смеси постоять 20 минут для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Нарезать тонкими кольцами репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Натереть твердый сыр на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Перемешать сливки или сметану с солью, перцем, специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Нарезать тонкими кружками очищенный картофель.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Форму для выпекания смазать маслом, выложить слой лука, на него – слой картофеля.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Сверху – сметанный соус и кусочки куриного филе, выложенные друг к другу вплотную.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Посыпать блюдо тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Слои повторять до тех пор, пока не закончатся продукты. Сверху – сыр.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Запеканку поставить в заранее разогретую духовку, печь в течение 35 – 55 минут. Готовность можно проверить зубочисткой или ножом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9103,'Готовую запеканку немного остудить и подать на стол теплой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Куриное филе отварить и порезать соломкой, а затем немного обжарить на растительном масле вместе с соломкой острого красного перца и измельченным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Ингредиенты хорошо перемешать, через минуту или две всыпать консервированную кукурузу, влить томатный соус, посолить по вкусу, добавить специи: красный и черный молотый перец, кориандр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Смесь жарить на огне средней мощности в течение пяти минут, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Готовую тортилью посыпать тертым сыром и нашинкованным зеленым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'На середину выложить обжаренное куриное филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Другой вариант: если тортилья готовилась из пшеничной муки, то её можно легко свернуть в виде рулета, завернуть в фольгу и запечь в течение пяти минут в духовке при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9104,'Изделие из кукурузной муки свернуть не получится – оно сломается. Также можно аккуратно согнуть лепешку с курицей пополам и немного обжарить до золотистого цвета с двух сторон на растительном масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9105,'На ломтики батона намазать тоненький слой сливочного масла. Поставить их на «ребро» в формочку, смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9105,'Вымыть помидоры и порезать на кружочки. Положить кусочки ветчины и помидоров между ломтиками батона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9105,'Взбить яйца, молоко, мускатный орех, посыпать перцем, солью. Данной смесью залить батон с помидорами и колбасой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9106,'Взять три лимона большого размера. Снять и высушить цедру. Залить желатин кипяченой холодной водой, отставить, чтобы размок, минут на десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9106,'Перемешать воду и сахар, поставить на плитку. Довести до кипения, чуть-чуть уварить. Снять сироп с огня, налить желатин. Налить сок лимона, процеженный через ситечко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9106,'Размешать ароматную жидкость, размешать, вылить в формочку. Накрыть крышкой, отправить в холодильник на пару часов. Разрезать лимонный мармелад на кубики, обмакнуть со всех сторон в сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9107,'Отрезать соцветия цветной капусты, варить приблизительно 45 минут в подсоленной кипящей воде. Слить воду в посуду, она пригодится позже.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9107,'Потереть стебель капусты или измельчить в миксере. Поджарить цветочки капусты на растопленном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9107,'Выбрать капусту и насыпать на сковороду муку. Налить воду, которая была слита, готовить помешивая, пока смесь не начнет сгущаться. Налить молоко, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9107,'Положить цветочки, подготовленный стебель. Положить тертый сыр, осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9107,'Подавать сырный суп с цветной капустой горячим, посыпать сверху сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9108,'Порезать тоненько лук. Положить его в посуду, налить масло, уксус, посыпать перцем, сахаром, солью. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9108,'Порезать буженину. Положить огурцы, фасоль. Положить измельченную зелень. Лук добавить в последнюю очередь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9109,'Замесить тесто для блинчиков. Измельчить лук и чесночок, обжарить до прозрачности на масле. Положить порезанную морковь, перец, сельдерей. Жарить минут пять, помешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9109,'Положить фарш, перец, соль, сладкую молотую паприку, обжаривать фарш, помешивая, приблизительно минут двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9109,'Готовить блины, одну сторону оставлять бледной, чтобы позже обжарить с начинкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9109,'На румяную сторону положить начинку. Чуть-чуть обжарить блинчики с мясом на масле, начинать со стороны соединения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9110,'Просеять муку, насыпать соль, положить холодное масло, порезанное на кубики, порубить в крошку в кухонном комбайне. Налить воду, быстро замесить тесто. Сформировать шар, завернуть в пищевую пленку, отправить на тридцать минут в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9110,'Достать из холодильника, положить в формочку, сформировать бортики. Предварительно тесто необходимо тоненько раскатать. Сделать проколы вилкой, отправить минут на двадцать в духовку, соблюдать температуру 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9110,'Можно заняться овощами. Порезать на небольшие кубики. Разогреть масло на сковороде, обжарить лук, чуть-чуть подсолить. Он не должен зажариться. Почистить и порезать баклажан, положить на лук, обжарить. Положить перец, кабачок, в последнюю очередь помидор.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9110,'Обжаривать овощи до мягкости. Соединить сметану и яйца, посыпать перцем, солью. Достать тесто из духовки, вылить на него начинку, поставить снова в духовку минут на тридцать. Минут за пять до конца готовки посыпать киш с овощной начинкой тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9111,'Положить в творог яйца, соль, ваниль, сахар. Размешать. Налить молоко, насыпать манную крупу. Размешать. Поделить тесто пополам. В одну насыпать какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9111,'Смазать формочку маслом, положить сначала белое, потом коричневое тесто и так далее, пока не закончится тесто. Сделать запеканку можно несколькими способами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9111,'Отправить в духовку минут на сорок, соблюдать температуру 170 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9111,'Или можно сделать в микроволновой печи. Включить на самую большую мощность, установить таймер на десять минут. Не доставать из печи еще минуты две.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9111,'Достать творожно-манную запеканку «Зебра» из формочки, остудить, порезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9112,'Испечь несколько тонких блинчиков по любимому и поверенному рецепту, в тесто добавить маковое семя, предварительно подсушенное на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9112,'Для начинки соединить натуральный мёд, лимонный сок, рикотту, ингредиенты взбить до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9112,'Выложить готовую начинку на каждый блинчик, свернуть их рулетами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Для приготовления бисквита отделить белки от желтков. Белки поставить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/36/e32f33352288d36_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'В желтковую массу добавить немного теплой воды, взбить её миксером в течение двух-трех минут в пышную пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Всыпать половину нормы сахарного песка, продолжать взбивать до растворения продукта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Вынуть охлажденные белки, посолить, влить несколько капель лимонного сока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Взбивать сначала без сахара, увеличить скорость. На весь процесс уйдет три-четыре минуты.','https:https://st.vkuso.ru/data/cache/thumb/41/551edb3c9731c41_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Порциями, постепенно, добавить оставшийся сахарный песок, продолжать взбивать до полного растворения. Сахар лучше взять мелкий.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Просеять в емкость с желтками муку, аккуратно перемешать на тихой скорости, затем добавить белки и еще раз перемешать. Взбитые продукты не должны потерять воздушность.','https:https://st.vkuso.ru/data/cache/thumb/d7/3dc7fff62ce95d7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Готовое тесто перелить в форму и печь при температуре 180 градусов в течение получаса. Дверку духового шкафа не открывать, чтобы выпечка не осела. Готовность коржа определяется надавливанием: углубление должно быстро восстановиться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Духовку выключить, оставить выпечку на пять минут, затем вынуть и оставить на несколько часов, можно на ночь.','https:https://st.vkuso.ru/data/cache/thumb/4c/ab7b73e526fe44c_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Разрезать бисквит на два коржа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Растворить в воде сахар, сварить сироп, остудить, добавить ванильный экстракт, пропитать коржи.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Для начинки смешать творог с сахарным песком, оставить на минуту, а затем растереть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Отдельно взбить сливки и поставить в морозильную камеру на 15 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Половину пакетика желатина залить небольшим количеством кипяченой охлажденной воды, оставить на 10 минут, а затем прогреть, до кипения не доводить. Немного остудить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Перемешать с помощью миксера сливки с творогом и желатином. Подмешать ложкой заранее промытые и обсушенные ягоды черники и голубики.','https:https://st.vkuso.ru/data/cache/thumb/44/6fdabd8bca43d44_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Выложить в форму нижний корж, на него выложить начинку, накрыть вторым коржом, поставить торт в холодильник до застывания на два часа.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Готовую выпечку вынуть, подровнять края.','https:https://st.vkuso.ru/data/cache/thumb/30/a18aeefb5a0c130_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9113,'Для украшения взбить сливки, добавить растворенный желатин. Залить массой торт, украсить теми же ягодами, что использовались для начинки.','https:https://st.vkuso.ru/data/cache/thumb/dd/93005bcd9531edd_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9114,'Обжарить на сковороде в течение трех-четырех минут мясной фарш, посолить и переложить на тарелку вместе с появившимся соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9114,'Обжарить мелко нарезанный репчатый лук и помидоры на той же сковороде, добавить рубленый укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9114,'Для приготовления молочного соуса пшеничную муку размешать в молоке, посолить и довести до кипения, снять с огня. Соус должен немного загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9114,'Форму смазать маслом, выложить тонкий армянский лаваш, фарш, еще один лаваш, овощную обжарку, сверху – третью лепешку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9114,'Залить блюдо молочным соусом, посыпать тертым сыром, печь в духовом шкафу 30 – 40 минут до румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9115,'Разрезать каждую куриную грудку по горизонтали так, чтобы в результате получились нетолстые шницели.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9115,'Молоко чуть-чуть подсолить и опустить в него сырые шницели на 30-60 минут, по истечении отведенного времени мясо обсушить (бумажным полотенцем).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9115,'Смешать сливочное и растительное масла, в полученной смеси с обеих сторон обжарить куриные шницели.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9115,'На средний огонь поставить кастрюльку со сливками, добавить сыр и при постоянном помешивании растворить его. Убрать емкость с огня, дать соусу слегка загустеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9115,'Подавать куриный шницель в соусе из горгонзолы и сливок с рисом или пастой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Для приготовления блинного теста перемешать молоко с яйцами и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Муку подсыпать постепенно, до нужной густоты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'В конце добавить пищевую соду, погашенную лимонным соком или уксусом, растопленное сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Испечь блины средней толщины, без дырочек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Для крема перемешать сливочный сыр «Маскарпоне» с сахарной пудрой. Лучше сделать это вручную.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Выложить на блюдо блинчики, промазать их сырной начинкой. Сверху торт покрыть остатками крема.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9116,'Готовый десерт подержать в холодильнике в течение пяти часов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Для приготовления начинки распустить на сковороде сливочное масло, добавить сахарный песок и нарезанные зеленые яблоки без кожуры.','https:https://st.vkuso.ru/data/cache/thumb/62/223488582147562_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Накрыть сковороду крышкой, потомить содержимое в течение трех-пяти минут, до мягкости. Крышку снять, начинку остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Соединить молоко с творогом, сахаром, растительным маслом, солью, всыпать просеянную муку, разрыхлитель.','https:https://st.vkuso.ru/data/cache/thumb/68/76cffa6f5f66f68_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Готовое тесто разделить на десять шариков.','https:https://st.vkuso.ru/data/cache/thumb/5b/9be5d913cf8fe5b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Каждый раскатать в лепешку, выложить яблочную начинку и защипать края.','https:https://st.vkuso.ru/data/cache/thumb/f8/5b337a5f3290af8_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Для выпекания изделия выложить на лист пергамента, смазать яйцом.','https:https://st.vkuso.ru/data/cache/thumb/25/b754711297fc725_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9117,'Печь в духовом шкафу в течение 20 – 25 минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'Для теста понадобится сахар, пшеничная мука, сливочный размягченный маргарин или сливочное масло, разрыхлитель. Ингредиенты перемешать, перетереть в крошку. Это можно сделать при помощи блендера, кухонного комбайна или руками. Если перемешивание делается механическим способом, то масло или маргарин должны быть мягче. Поставить массу в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/04/eecadef3bba5c04_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'В сухой творог ничего добавлять не нужно, во влажный продукт можно досыпать немного муки. Перемешать его с сырыми куриными яйцами, сахаром и ванильной эссенцией или ванилином. Смесь взбить погружным блендером, она должна стать блестящей, воздушной и однородной.','https:https://st.vkuso.ru/data/cache/thumb/2c/b4024feb643092c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'Для выпекания понадобится разъемная форма, застеленная бумагой. Бортики смазать маслом или маргарином. Насыпать в форму больше половины охлажденной крошки, разровнять, но не утрамбовывать.','https:https://st.vkuso.ru/data/cache/thumb/4f/8348ae9cef92f4f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'Сверху выложить творожную начинку и насыпать сушеную вишню, изюм или цукаты. Следующий слой – оставшаяся крошка. Духовку разогреть до 180 – 190 градусов, поставить форму, печь в течение 50 минут. Пирог должен зарумяниться.','https:https://st.vkuso.ru/data/cache/thumb/67/014aa415144eb67_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'За пять минут до окончания выпечки приготовить заливку из сметаны и сгущенного молока. Полить пирог смесью.','https:https://st.vkuso.ru/data/cache/thumb/a0/5d3834388caeaa0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'Можно сделать любые узоры из растопленного горького шоколада или шоколадного сиропа. Пирожное поставить на ночь или на два часа в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/48/04ecb01017ac448_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9118,'Десерт отделить от бортиков ножом, вынуть, нарезать на ромбы, квадраты, прямоугольники, подать к чаю.','https:https://st.vkuso.ru/data/cache/thumb/16/5b990f12a869c16_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'В небольшой емкости разогреть какао-порошок с сахаром, солью и водой.','https:https://st.vkuso.ru/data/cache/thumb/78/54f995dbd4d1478_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Смесь взбить венчиком до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/33/3c22abc64937733_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Довести массу до легкого кипения, помешивать на протяжении шести минут: сахар должен растаять и превратиться в густой сироп.','https:https://st.vkuso.ru/data/cache/thumb/c7/e6983ef00aad5c7_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Снять его с огня, ввести ванилин, и свежий концентрированный кофе. Все вместе взбить венчиком.','https:https://st.vkuso.ru/data/cache/thumb/62/7fbf6c224ee6562_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Перелить сироп в банку для хранения, оставить на час, затем закрыть закручивающейся крышкой.','https:https://st.vkuso.ru/data/cache/thumb/35/1a4d5aad5285035_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Для подачи перемешать немного сиропа с обычным, кокосовым или миндальным молоком, подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9119,'Заготовка хранится в холодильнике в течение месяца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Перемешать сырые яйца, творог, муку и сахарный песок, должна получиться густая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'В большой кастрюле довести воду до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Мокрыми руками скатать из творожной массы небольшие шарики величиной с грецкий орех, аккуратно опустить в кипяток с помощью шумовки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Через минут шарики всплывут – их нужно вытащить и положить новую порцию. Отварить все шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Для приготовления заливки перемешать сахар с маком и сметаной, немного взбить вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Духовку разогреть до 180 градусов, большую форму для запекания или несколько маленьких смазать сливочным маслом, выложить шарики, залить сладкой сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9120,'Печь в течение получаса или чуть меньше.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Натереть на крупной терке по отдельности отварную свеклу и морковь, картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Так же поступить с яблоком небольшого размера, плавленым сырком и отваренным куриным яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Репчатый лук нарезать, залить на минуту кипящей водой, промыть холодной, чтобы ушла лишняя горечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Слабосоленый лосось нарезать аккуратными кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Выложить салат на блюдо слоями: отварная свекла, соль, майонез.','https:https://st.vkuso.ru/data/cache/thumb/32/d5b8ad6144dc432_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Далее - отварная морковь, соль, майонез.','https:https://st.vkuso.ru/data/cache/thumb/09/5db3bbfd641a809_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Следующие слои – отварная картошка, майонез, сыр, яйцо, тертое яблоко, ошпаренный лук.','https:https://st.vkuso.ru/data/cache/thumb/c3/fac0537c9cf46c3_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Поверх – рыба. Оставить салат на час для пропитывания.','https:https://st.vkuso.ru/data/cache/thumb/fe/565ecc909f36bfe_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9121,'Кольцо снять, блюдо украсить на свой вкус и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/41/e5bbaa59cb02e41_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'Мясо нарезать на куски в 1 см толщиной, слегка отбить, поперчить и посолить все по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'Полукольцами порезать репчатый лук,  кружками нарезать картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'Форму для запекания смазать растительным маслом, выложить продукты слоями: сначала 1/3 часть лука, затем мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'Далее выложить оставшийся лук, промазать его майонезом, на него уложить картофель, который нужно посолить и тоже промазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'Блюдо поставить в духовой шкаф и в течение 1-1,5 часов запекать  при 175 градусах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9122,'За 15 минут до полной готовности картофель запеченный с мясом и луком посыпать предварительно натертым сыром, а перед подачей украсить зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9123,'Приготовить тесто для пиццы или купить готовое. Мелко порезать оливки, смешать с базиликом. Разогреть духовку до 220 градусов. Тесто поделить на несколько частей. Одну часть взять и тоненько раскатать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9123,'Распределить равномерно ¾ тертого сыра по тесту, чуть-чуть вмять руками. Сложить тесто пополам, чтобы сыр был внутри. Посыпать остальным сыром, снова завернуть. Начать месить. Месить, пока сыр не распределится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9123,'Вновь тоненько раскатать сырное тесто, как пиццу, порезать на полоски по 1 сантиметру в ширину. Посыпать противень мукой, выкладывать полосочки теста, каждую скручивать по спирали. Между полосками оставлять интервал приблизительно 1 сантиметр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9123,'Взять второй шар теста, сделать то же самое, но выкладывать на тесто базилик с оливками. Положить скрученные полоски теста на противень. Отправить первый противень в разогретую духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9123,'Готовить минут восемь. Палочки должны подрумяниться и подняться. Вынуть, отправить второй противень. Позволить итальянским гриссини с оливками и сыром остыть и подавать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9124,'В большой посуде соединить дрожжи, мед и воду. Отставить минут на пять, чтобы дрожжи начали пениться. Насыпать муку и соль (морскую). Руками замесить однородное тесто. Оставить в емкости, смазанной маслом минут на тридцать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9124,'Когда тесто поднимется, выложить его на доску, посыпанную мукой. Поделить на 5-6 частей. Из каждой раскатать тоненький «шнур», который необходимо будет разрезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9124,'С помощью блендера взбить в крошку сыр, розмарин, орегано, тимьян. Положить в большую посуду. Соединить масло и прессованный и порошковый чесночок. Окунуть каждую палочку в масло, обвалять во взбитой смеси.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9124,'Положить палочки на противень, застеленный специальной бумагой. Готовить минут семнадцать, соблюдать температуру 200 градусов, сыр должен стать коричневым. Сразу снять сырно-чесночные палочки, чтобы сыр не успел затвердеть и пристать к противню.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9125,'Сделать сухарики. Порезать хлеб на кубики, обвалять в прессованном чесноке, подсушить в микроволновой печи или на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Ножки отделить от шляпок, крупно порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9125,'Потереть яйца, измельчить чесночок, крупно потереть сыр. Слить сок с кукурузы и фасоли. Смешать все ингредиенты, посыпать перцем, солью, заправить майонезом, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9125,'Положить на тарелочку, при помощи ножа осторожно придать форму цилиндра, посыпать салат с фасолью чесночными сухарями, украсить веточкой укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9126,'Приготовить начинку. Обжарить чуть-чуть кедровые орешки, укроп порезать не очень мелко, но и не крупно. Потереть цедру лимона. Соединить все с сыром. Добавить сок половины лимона. Размешать. Порезать огурец на полосочки. Начинка готова.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9126,'Взять бамбуковую циновку (обычно ее продают в качестве коврика – подставки для посуды). Положить на нее пищевую пленку. На нее выложить с небольшим перехлестом рыбу, тоненько порезанную. Положить на рыбу начинку толщиной примерно по 6 миллиметров, на середину положить пару кусочков порезанного огурчика. Огурец придаст свежесть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9126,'Завернуть, сформировать колбаску. Закрутить торцы колбаски. Осторожно поместить колбаску в холодильник, чтобы она чуть-чуть застыла. Достать, развернуть, мокрым ножом разрезать наискосок. Выставить вкусную пародию на суши в тарелочку, украсить лимончиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9127,'Отварить постную говядину, нарезать мясо тонкими полосками. Маринованные грибы нарезать брусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9127,'Красный сладкий перец очистить от семян, вымыть, нарезать соломкой. Порезать перья зеленого лука, листья салата – по желанию. Все ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9127,'Для соуса смешать натуральный йогурт с хреном или готовой столовой горчицей, подлить лимонный сок, всыпать соль и молотый перец. Заправить салат полученным соусом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Отваренное куриное мясо и сладкий болгарский перец нарезать соломкой, свежий огурец – тонкими кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Промыть листья зеленого салата, обсушить, нашинковать длинными, тонкими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Очистить яблоко, вынуть сердцевину, нарезать мякоть соломкой, кубиками или натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Очистить апельсин от кожицы, косточек и пленок, нарезать мякоть ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Для заправки натереть цедру апельсина, перемешать с жидким мёдом, подлить лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Все нарезанные продукты соединить, посолить по вкусу, заправить молотым перцем и соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9128,'Смесь выложить на блюдо, украсить зеленью и ломтиками апельсина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9129,'Соединить муку, соду, разрыхлитель, сахар, соль. Взбивать яйца приблизительно минуты три, чтобы они превратились в пену. Налить молоко, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9129,'Насыпать сухие компоненты, осторожно размешать. Растопить масло, налить в тесто, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9129,'Наливать на сковороду небольшими порциями (если блинчики прилипают, то смазать сковороду чуть-чуть маслом, если нет, то масло не добавлять).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9129,'Каждый панкейк по-американски готовить минуты по две с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9130,'Филе лосося нарезать кусочками, репчатый лук – кольцами, ингредиенты перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9130,'Для приготовления маринада смешать белое сухое вино, лимонный сок, молотый перец, тмин, шалфей и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9130,'Залить рыбу с луком полученной смесью, поставить в холод на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9130,'Сладкий желтый перец нарезать квадратиками, нанизать на палочки вместе с рыбой и колечками лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9130,'Жарить шашлыки в духовке, температура – 200 градусов, можно воспользоваться грилем. Палочки периодически поворачивать и сбрызгивать остатками маринада.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9131,'Картошку и репчатый лук порезать, поместить в кипящий бульон и отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9131,'Для галушек приготовить тесто: муку смешать с яйцом и щепоткой соли. Тесто мешать до тех пор, пока консистенция его не будет напоминать густую сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9131,'Набирать по ¼ столовой ложки готовое тесто и опускать ложку прямо в кипящий бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9131,'На растительном масле (лучше постном), поджарить оставшуюся морковь и лук, получившейся зажаркой заправить суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9131,'Варить куриный суп с украинскими галушками до полной готовности, затем посолить, заправить зеленью. Подавать блюдо лучше со сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9132,'Сделать соус. Растопить масло. Насыпать муку, налить сливки, молоко. Готовить до загустения, помешивать. Измельчить базилик, зубчик чесночка и петрушку, посыпать перцем, солью, добавить хмели-сунели. Высыпать измельченную зелень со специями в густой соус, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9132,'Замесить тесто, если оно получилось суховатое, то налить чуть-чуть воды. Получается очень мягкое сметанное тесто. Отставить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9132,'Заняться подготовкой куриной грудки. Порезать ее на средние кусочки, чуть-чуть посолить. Раскатать тесто в круг, вырезать несколько видов кружков, одни маленькие, другие побольше. У маленьких вырезать серединку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9132,'Сформировать пирожки. Кружки побольше посыпать манкой, положить кусочки курицы, намазать соусом. Накрыть кружками поменьше, защипнуть краешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9132,'Положить пирожки на противень, намазанный маслом. Готовить куриные грудки в тесте в духовке минут 35, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9133,'Соединить сметану и соду. Добавить растопленное масло, размешать до однородности. Небольшими порциями начать насыпать муку. Насыпав полтора стакана муки, проверить, если тесто липнет к рукам, насыпать еще полстакана. Если тесто не липнет, можно не насыпать. Замесить тесто, поделить пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9133,'Порезать лимоны или апельсины небольшими дольками с кожурой, взбить в блендере. В смолотый лимон насыпать сахар. Нагреть духовку до 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9133,'Одну часть теста выложить, как основу. Распределить тесто по формочке, сделать небольшие бортики. Положить начинку, размазать равномерным слоем по основе. Размять руками вторую часть теста, закрыть ею начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9133,'Намазать пирог взбитым желтком, чтобы была золотистая корочка. Проткнуть лимонный  пирог вилкой. Готовить минут тридцать. Остудить, выложить из формочки, посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9134,'Овсяные хлопья перемолоть, смешать с сырым белком, водой и молотой корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9134,'Готовое тесто выложить в форму для выпекания, сформовать бортики. Печь при температуре 180 градусов в течение 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9134,'Для приготовления начинки перетереть творог с фруктами с помощью блендера. Добавить сырой белок, ванилин, мёд. Массу еще раз перетереть блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9134,'Вылить начинку на корж, снова поставить в духовку и допечь в течение 45 – 50 минут при той же температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Рыбу натереть перцем, солью, пряными травами, выложить в форму, заранее смазанную оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Печь в духовом шкафу при температуре 200 градусов в течение 15 – 18 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Грибы вешенки обжарить на масле в течение семи-восьми минут, соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Клубни картофеля очистить и нарезать ломтиками в сантиметр толщиной. Обжарить на сильном огне в течение десяти минут, должна получиться румяная корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Накрыть крышкой и потушить еще семь-восемь минут на тихом огне, соль – в конце приготовления.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Произвольно нарезать свежие помидоры и огурцы, посолить и поперчить, добавить зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Салат можно заправить сметаной, маслом или йогуртом без вкусовых добавок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9135,'Выложить в тарелки горками картофель и грибы, по окуню на порцию, салат подать отдельно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'Вымыть молодые кабачки, отрезать кончики. Крупно потереть. Отделить желтки от белков. Добавить к тертым кабачкам желтки, насыпать разрыхлитель, муку, соль. Размешать все до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'В белки насыпать небольшую щепотку соли, взбить. В несколько приемов вылить взбитые белки в кабачковую массу. Осторожно перемешать. На противень постелить бумагу для выпечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'Чтобы легче было отделить коржи, можно сбрызнуть оливковым или растительным маслом, вылить тесто равномерно распределить. Отправить минут на сорок в духовку, соблюдать температуру 180 градусов. Вынимать, когда корж приобретет золотистый оттенок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'Приготовить начинку: вымыть грибы, посушить. Порезать шампиньоны на кубики или соломкой. Измельчить лук и чесночок. Обжарить чеснок, лук, затем грибы минут десять. Налить сливки, тушить минут семь, смесь должна стать достаточно густой. Посыпать перцем, солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Шляпки тонко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'Осторожно отделить готовый корж от бумаги, положить обратно, свернуть в рулетик. Позволить чуть-чуть остыть. Мелко потереть сыр. Помыть и высушить зелень. Измельчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9136,'Выложить грибную начинку на коржик. Посыпать тертым сыром. Последний слой измельченная петрушка и укроп. Свернуть рулет из кабачка с сыром и шампиньонами, при этом придерживать края бумаги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'В теплую воду добавить сухие дрожжи и сахарный песок, оставить на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Филе курицы отварить в течение 20 минут с солью и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'В опару добавить яичный желток, сметану, размягченное сливочное масло и соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Постепенно, порциями, всыпать пшеничную муку. Замесить тесто, оно должно быть однородным, мягким и эластичным, легко тянуться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Скатать в шар, накрыть тканью, поставить в тепло на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Отваренное куриное мясо нарезать мелкими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Свежие грибы вымыть, очистить, нарезать дольками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Можно использовать консервированный продукт, в этом случае нужно слить маринад.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Измельчить зелень петрушки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Для приготовления соуса растопить в глубокой сковороде сливочное масло, всыпать муку и перемешать, комочки разбить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Влить куриный бульон и молоко, еще раз перемешать, прогревать в течение двух минут до загустения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Добавить курицу, грибы и зелень, посолить, поперчить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Кроме петрушки можно добавить орегано и базилик.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Поднявшееся тесто разделить на две части: большую и меньшую. Большую часть раскатать на присыпанной мукой поверхности, выложить в форму, смазанную маслом и также присыпанную мукой. Края растянуть, сформовать бортики.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Выложить начинку, утрамбовать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Меньшую часть теста раскатать в лепешку, положить сверху, скрепить края.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'В центре сделать дырочки для выхода пара. Поверхность смазать молоком или желтком.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9137,'Печь в заранее разогретой духовке, время – от 30 до 40 минут, температура – 180 градусов.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Сварить бульон из мяса на кости, например, лопатки. Варить бульон с половиной моркови и половиной луковицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Приготовить зажарку из лука, моркови, соленых огурцов, порезанных на кубики. Жарить минут семь, положить томатную пасту, готовить еще семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Порезать сосиски на кружки, сервелат соломкой. Все обжаривать минут пять на сильном огне. Достать мясо, порезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Положить в бульон капусту, зажарку, маслины, порезанные на кружочки, налить смесь рассолов от огурцов и маслин. На большие кубики порезать картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Добавить перец горошком и лавровый листик. Готовить минут десять, в завершение положить обжаренные сосиски и сервелат и порезанное мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9138,'Добавить прессованный чесночок, посыпать мясную солянку с сервелатом зеленью. Снять с плиты, позволить настояться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9139,'Разогреть духовку. Формочку 15 сантиметров застелить специальной бумагой. Яйца и сахар взбивать минут пять. Нагреть молоко и ваниль, соединить с яичной смесью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9139,'Насыпать просеянную смесь муки и разрыхлителя. Положить цедру, розовый краситель. Размешать до однородности. Перелить тесто в формочку. Готовить минут пятьдесят.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9139,'Приготовить крем: взбить масло, добавить сливочный сыр, взбить до однородности. Насыпать ванилин и сахарную пудру. Взбить, отправить в холодильник, если крем очень жидкий.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9139,'Выложить тортик: разрезать коржик на три части. Намазать их кремом. Оставшимся кремом намазать коржи снаружи. Посыпать розовый торт кокосовой стружкой и украсить розами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'В эмалированную миску всыпать сахар, вбить яйца, добавить мед, тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Поставить миску на маленький огонь, довести до растворения сахара при постоянном помешивании, но не дать массе загустеть (она должна струйкой стекать с ложки).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Добавить соду, хорошенько перемешать, всыпать муку и замесить такое тесто, чтобы оно чуть прилипало к рукам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Готовое тесто разделить на желаемое количество равных кусков и из каждого раскатать корж. Каждый корж равномерно наколоть вилочкой в нескольких местах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'В духовке при 220 градусах выпекать каждый корж до красноватого цвета в районе 3-5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'На ровную поверхность выложить готовые коржи, по форме будущего торта обрезать, получившиеся обрезки поместить в остывающую духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Для приготовления крема необходимо взбить сахар со сметаной до однородной массы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Из остывших коржей и крема собрать торт: корж промазать кремом, сверху выложить следующий корж, снова крем и так до тех пор, пока не закончатся коржи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Бортики и верх получившегося торта промазать оставшимся кремом, посыпать измельченными обрезками, сверху украсить тертым шоколадом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9140,'Торт «Медовик» домашний со сметанным кремом отправить на 12 часов в холодильник, чтобы он пропитался и коржи стали мягкими.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Приготовить тесто из сырых яиц, сахарного песка, сметаны, какао-порошка, пищевой соды, соли и пшеничной муки. Ингредиенты взбить с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Готовое тесто выложить в форму, печь в духовом шкафу до готовности на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Готовый корж остудить, разрезать поперек на две части: нижняя часть должна быть толще.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Для крема перемешать сметану с сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Оба коржа пропитать полученной смесью, можно наколоть вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Верх торта полить оставшимся кремом, посыпать тертым шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Другой вариант украшения: приготовить глазурь из молока, сахара и какао-порошка, прогреть на огне до растворения продуктов, добавить сливочное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9141,'Полить готовый торт.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Отварить свеклу, натереть на крупной терке, выложить в салатник.','https:https://st.vkuso.ru/data/cache/thumb/a2/ef2b6e95ccc3ba2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Нашинковать пекинскую капусту, выложить сверху.','https:https://st.vkuso.ru/data/cache/thumb/94/6a711aa496e6394_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Отварить куриные яйца, очистить, нарезать кубиками.','https:https://st.vkuso.ru/data/cache/thumb/69/725d30e1ff26a69_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Измельчить любую пряную зелень.','https:https://st.vkuso.ru/data/cache/thumb/e3/464d10e2a37d3e3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Мелко нарезать очищенные дольки чеснока или пропустить их через чеснокодавку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9142,'Все ингредиенты перемешать, посолить по вкусу. Салат заправить майонезом или смесью майонеза с простоквашей или сметаной. Подать блюдо к столу.','https:https://st.vkuso.ru/data/cache/thumb/96/1f8e814d0ea4296_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9143,'Охладить яйца, отделить желтки от белков, до пены взбить белки, ввести маленькими порциями сахар, взбивать, пока он не растворится, минут семь. Получится глянцевая пена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9143,'Положить на противень специальную бумагу, ложкой выложить безе. Сделать примерно пять безе с пиками, поставить их сверху. Выпекать в духовке минут 150, соблюдать температуру 100 градусов. Увеличить температуру до 120 градусов, готовить минут 25, охладить безе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9143,'Измельчить чернослив и орешки, можно перекрутить через мясорубку. Взбить сливочное масло при помощи миксера, положить сгущенное молоко, размешать с черносливом и орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9143,'Положить на тарелочку ложку крема, размазать и выложить на него безе по диаметру тарелки, положить сверху второй ряд безе, каждую часть смазывать кремом. Сложить торт «Графские развалины» горкой, охладить и подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9144,'Приготовить бисквит: отделить желтки от белков, последние взбить в пену. Постепенно насыпать сахар, взбить до воздушной массы. Когда масса будет плотной и белой, постепенно добавить желтки, взбитые предварительно чуть-чуть венчиком, при этом, не переставая, взбивать белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9144,'Насыпать муку, просеянную с ванилином. Тесто не месить, а осторожно вымешивать ложкой снизу вверх. Должно получиться очень воздушное тесто. Вылить приготовленное тесто в формочку, смазанную маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9144,'Отправить минут на двадцать в духовку, соблюдать температуру 190 градусов. Бисквит поднимется раза в три. Важно не открывать дверцу духовки, чтобы не осел.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9149,'Перемолоть все до однородной густой массы. Сразу не класть все ингредиенты, регулировать консистенцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9144,'Остудить минут пять бисквит в формочке, перевернуть на решетку, отставить часа на три. Разрезать на три пласта. Приготовить крем: соединить воду, сгущенное молоко и желтки. Поставить смесь на маленький огонь, готовить до сгущения. Взбить масло и ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9144,'Охладить густую смесь, добавить в масло, взбитое с ванильным сахаром. Добавлять понемногу, взбивая. Собрать торт «Елизавета»: все слои бисквита промазывать кремом. По вкусу украсить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Для приготовления теста пшеничную муку просеять в емкость, сделать в середине углубление.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Взбить вилкой целое яйцо и отделить половину. Влить холодную воду и растительное масло, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Переложить массу на присыпанный мукой стол, вымесить. Тесто не должно быть липким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Завернуть его в пленку, дать постоять в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Для приготовления начинки натереть «Российский» сыр или любой другой, полутвердый.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Лосось или другую красную рыбу нарезать ломтиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'На сковороде растопить сливочное масло, выложить свежий шпинат и прогреть до мягкости, помешивать. Снять с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Перемешать рыбу, сыр, яйцо и шпинат, посолить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Выложить на стол льняное полотенце, присыпать его мукой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'В центр выложить тесто, раскатать в большую и тонкую лепешку прямоугольной формы. Когда раскатывать тесто станет невозможно – растянуть его руками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Длинную сторону присыпать панировочными сухарями, оставить не присыпанными по два сантиметра снизу и сверху и 15 сантиметров с правой стороны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Выложить начинку поверх посыпки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Скрутить рулет с помощью ткани, поднимая её за края, тесто защипать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Выложить штрудель на противень, застеленный пергаментом, верх смазать растопленным сливочным маслом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Печь изделие в течение 35 минут, температура приготовления – 200 градусов.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9145,'Готовый штрудель вынуть, через 10 минут нарезать на куски, посыпать молотой сладкой паприкой и подать к столу.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9146,'Отварить бобы и брокколи в кипящей воде минуты две, слить воду. Чтобы овощи не изменили цвет, положить их в ледяную формочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9146,'На четыре тарелки положить салат, брокколи, бобы, порезанное авокадо, яйца, вареные креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9146,'Взбить майонез, воду, кунжутное масло. Данной заправкой сбрызнуть салаты, посыпать кунжутом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Гладкой стороной молоточка немного отбить свиные отбивные с обеих сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Натереть подготовленное мясо молотым перцем, солью, спрыснуть соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Разогреть на сковороде небольшое количество растительного масла и обжарить на нем отбивные в течение 2-3 секунд с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Обжаренное мясо переложить на противень, выложить на него обжаренные до готовности шампиньоны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Накрыть грибы ломтиком сыра и убрать противень на 15 минут в духовку, нагретую до 180-200 С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9147,'Свиная отбивная запеченная под сыром и грибами подается в горячем виде, предварительно посыпанная измельченным зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9148,'Нагреть духовку. Намазать растительным маслом прямоугольную или квадратную формочку. В емкости соединить мед, сахар, растительное масло, воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9148,'Поставить на средний огонь, подогревать, помешивая, пока не растворится мед и сахар. Убрать с огня, охладить до 40 градусов. Положить соду в массу, она будет пениться и увеличится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9148,'Насыпать какао, пряности, положить орехи. Размешать насыпать просеянную муку. Должна получиться консистенция, как густая сметанка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9148,'Положить тесто в формочку, выровнять лопаткой, отправить в духовку минут на тридцать. Проверять готовность зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9148,'Перед тем как вынимать из формочки, охладить постную медовую коврижку, посыпать сахарной глазурью (смесь лимонного сока и сахарной пудры).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9149,'Налить в емкость оливковое масло, положить чесночок, базилик, тертый пармезан, кедровые орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Накрыть бутерброд вторым кусочком хлеба.','https:https://st.vkuso.ru/data/cache/thumb/f4/220f8462ddeedf4_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'Замариновать лучок. Порезать его не очень мелко, залить горячей водой, налить уксус. Можно мариновать просто в уксусе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'Мясо порезать на куски по 2 на 2 сантиметра. Посыпать перцем, солью. Обмазать майонезом, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'Положить в фольгу четверть помидора, нарезанного на ломтики. На него положить четверть болгарского перца, порезанного на кубики. Сверху картофель, порезанный на кубики. Посыпать солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'На картофель положить мясо, на него лук. Завернуть все осторожно, чтобы не порвалась фольга. Так четыре раза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'Готовить минут шестьдесят, соблюдать температуру 180 градусов. Пока запекаются узелки, потереть сыр. Спустя 60 минут достать узелки, открыть, посыпать сыром, не закрывать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9150,'Отправить минут на пятнадцать в духовку. Подавать на тарелке в горячем виде, посыпать узелки с говядиной зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9151,'Сделать начинку: положить ингредиенты в небольшую соусницу, поставить на огонь, время от времени мешать, пока не растворится сахар. Варить минут десять до золотистого цвета. Чем дольше варить карамель, тем гуще она будет. Остудить отправить в холодильник часа на два минимум.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9151,'Сделать печенье: взбить миксером на средней скорости масло и сахар. Вбить яйцо, насыпать ванилин, взбивать минуты две. Соединить муку и соль, просеять смесь, медленно ввести в тесто, увеличивать скорость миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9151,'Завернуть тесто в пленочку, отправить минут на шестьдесят в холодильник. Раскатать тесто толщиной 0,5 сантиметров. При помощи крышки от бутылки или формочки вырезать кружочки. Сделать дырочки штопором, положить заготовки для печенья в формочку или на противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9151,'Отправить минут на пятнадцать в холодильник. Готовить до золотистого цвета, соблюдать температуру 185 градусов. Оставить печенье «Пуговки» остывать на противне. Промазать заготовки карамелью, соединить две части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9152,'Помыть и обсушить гречневую крупу. Обжаривать минут семь на сухой сковороде. Она должна стать золотистого цвета. Положить сливочное масло, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9152,'Убрать массу с огня, положить в кастрюльку, залить двумя стаканами подсоленного кипятка. Закрыть крышкой, минут пятнадцать не открывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9152,'Порезать лук соломкой, обжарить на растительном масле. Измельчить петрушку и отваренные яйца. В готовую гречневую кашу положить яйца, обжаренный лук, зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9153,'Приготовить сухарики: разогреть духовку, с хлеба срезать корочку, мякоть порезать на кубики, посыпать итальянскими травами. Добавить чуть-чуть оливкового масла, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9153,'Отправить в духовку. Секунд через шестьдесят сделать температуру минимальной. Минут через десять духовку выключить, оставить минут на пять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9153,'Порезать пекинскую капусту, рыбу порезать на кубики. К рыбке и капусте положить черри, порезанные на 4 части, тертый сыр, яйца, порезанные крупно, укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9153,'Сделать соус: положить в майонез измельченный укроп и чесночок. Желательно брать легкий майонез, или использовать часть йогурта и две части майонеза. Порционно добавить в салат «Сардиния» сухарики, чтобы не размокли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9154,'Репчатый лук и шампиньоны нарезать мелкими кубиками, обжарить на растительном масле, посолить, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9154,'Отваренный заранее рис смешать с грибной обжаркой, добавить сырое куриное яйцо, всыпать картофельный крахмал, соль и перец, любые другие специи. Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9154,'Фарш набирать ложкой, обваливать в муке, формовать небольшие биточки. Жарить с двух сторон на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'Замочить желатин в воде так, как написано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'Растворить в молоке немного сахара, часть жидкости влить в желатин, поставить на полминуты в микроволновую печь или прогреть на плите, до кипения не доводить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'Смешать полученную смесь и остатки молока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'Часть массы отлить, подогреть, смешать с горячим шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'В порционные формочки налить шоколадное молоко, поставить для застывания в холодильник, сверху – остатки молока с желатином.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9155,'Поставить десерт для полного застывания в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Сварить в подсоленной воде предварительно очищенный и порезанный кубиками картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Сделать из готового картофеля однородное пюре, добавить в него сливочное масло, тертый сыр и яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Мелко нарубленный лук обжарить до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Добавить к луку подготовленный фарш, соль и черный молотый перец, все перемешать и готовить 10 минут при средней температуре, снять сковороду с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Форму для запекания сперва смазать подсолнечным маслом, а затем посыпать дно и стенки панировочными сухарями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'На дно подготовленной формы выложить ½ часть готового картофельного пюре, затем распределить по нему обжаренный фарш с луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Поверх мясного слоя выложить оставшееся картофельное пюре, которое затем посыпать тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Убрать форму в разогретый до 180 градусов духовой шкаф и запекать блюдо в течение 30 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9156,'Подается готовая ',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9157,'Филе нарезать на кусочки, добавить репчатый лук, овсяные отруби, соль и перец, столовая горчица – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9157,'Массу прокрутить через мясорубку несколько раз, масса должна получиться нежной и пластичной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9157,'Пищевую пленку разрезать на прямоугольники, выложить фарш, плотно свернуть, сформовать сосиски, завязать концы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9157,'Положить в кипящую воду, отварить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Сделать маринад: налить в кастрюльку воду, насыпать сахар, соль, добавить уксус, перец горошком, лавровый лист. Довести до кипения, убрать с огня, охладить. Налить минеральную воду. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Вымыть курицу, по хребту разделить пополам, положить в маринад. На мясо положить тарелочку, чтобы курица утонула в маринаде. Убрать кастрюльку с маринадом часов на двенадцать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Положить замаринованную курицу в формочку, налить несколько больших ложек маринада. Накрыть сверху крышкой или фольгой, готовить в духовке минут двадцать, соблюдать температуру 200 градусов. Убрать фольгу или крышку, готовить еще минут двадцать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Пока мясо запекается, приготовить чесночный соус. Положить в емкость прессованный чеснок, добавить сок лимона, масло, перец, соль, измельченную петрушку. Налить воду, отставить, чтобы настоялся. Достать мясо, обильно намазать чесночным соусом. Пока готовится курица, заняться пастой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Отварить пасту, как написано на упаковке, слить воду. Заняться соусом. В сотейнике с высокими бортиками соединить муку, молоко и сливочное масло. Подогреть на небольшом огне, непрерывно мешать, пока сливочное масло не растворится. Добавить в соус горчицу, сливки, перец, соль, крупно натертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9158,'Перемешать, довести до кипения. Готовить минут пять до загустения. Положить пасту пенне в соус, размешать, прогреть равномерно. Жареную курочку с пастой пенне и соусом можно подавать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9159,'Растопить шоколад. Намазать формочки с помощью силиконовой кисточки тоненьким слоем шоколада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9159,'Убрать минуты на четыре в морозилку. Если появились пробелы, то нанести на них шоколад и вновь отправить минуты на три в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9159,'Растереть творог и сахарную пудру, мягкое сливочное масло, ванилин. Достать формочки, наполнить на 1/3 творожной массой, в середину положить начинку, наполнить творогом до конца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9159,'Намазать творожные сырки шоколадом, отправить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9160,'Подогреть молоко до теплого состояния, вбить яйца, насыпать соду, добавить 1/3 стакана растительного масла, размешать. Насыпать какао, размешать. Тоненькой струей ввести муку. Тесто должно быть, как сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9160,'Выпекать блинчики по 20 сантиметров диаметром. Готовые блинчики намазать сливочным маслом. Соединить сметану, творог, ванилин, сахар, перемешать, чтобы не было крупинок творога, до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9160,'Взять блин, намазать начинкой, скрутить трубочкой, так же поступить с другими блинами. Сложить на тарелочку, отправить в холодильник приблизительно на шестьдесят минут, чтобы схватилась начинка. Достать, порезать на небольшие роллы «Доброе утро».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Измельчить сладкий перец и свежий огурец, вид нарезки – соломка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9161,'Соединить лимон с водой в большой емкости. Положить в воду порезанные яблоки, чтобы они не потемнели. Растопить в сковороде сливочное масло на небольшом огне. С яблок слить воду, положить в сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9161,'Тушить несколько минут, помешивая. Насыпать корицу и коричневый сахар, варить несколько минут, помешивая. Соединить воду и крахмал. Вылить в сковороду, размешать. Варить минуту, чтобы начинка загустела. Убрать с огня, чуть-чуть остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9161,'Разогреть духовку. Развернуть листы слоеного теста, загладить трещины, прижимать их вместе. Разрезать листы на четыре квадратика. Положить ложкой яблоки в центр каждого квадратика. Сложить краешки от одного угла к другому, чтобы получился треугольник, склеить краешки вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9161,'Положить на противень на расстоянии двух сантиметров друг от друга. Готовить минут двадцать пять в заранее разогретой духовке, конвертики должны вздуться и чуть-чуть подрумяниться. Полностью охладить, покрыть глазурью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9161,'Для приготовления глазури соединить молоко, сахарную пудру, ваниль в маленькой посуде. Регулировать количество молока, сахарной пудры до нужной консистенции. Полить остывшие треугольники с яблоками глазурью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9162,'Смолоть в блендере геркулес в порошок. Добавить остальные продукты, взбить коктейль до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9163,'Взбить яйца, не переставая взбивать, насыпать сахар, ваниль, соль. Влить молоко, продолжая взбивать. Ввести крахмал, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9163,'Взбивая ввести растопленное сливочное масло. Не останавливаясь, влить тоненькой струйкой крутой кипяток. Оставить минут на тридцать, чтобы тесто настоялось, выпекать блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9163,'Для тонких блинчиков на молоке можно использовать любую начинку, например, вареную сгущенку, изюм, грецкие орехи. Положить начинку на один краешек, накрыть боковыми сторонами, свернуть блинчик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9163,'Еще можно намазать вареньем или положить бекон и свернуть трубочкой. Вкусно получается и без начинки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9164,'Залить сливками хлеб. Кусочки должны хорошенько пропитаться. Пока хлеб пропитывается, перемесить чесночок, мясо, лук в мясорубке. Отправить туда же хлеб, пропитавшийся сливками. Посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9164,'Размешать готовый фарш. Крупно потереть сыр. Размешать. Сформировать котлетки. Нагреть на сковороде масло. Все котлеты обвалять в сухариках. Положить на сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9164,'Жарить до золотистого цвета с двух сторон. Нагреть духовку, переложить котлеты с сыром на противень. Отправить в духовку минут на десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9165,'Слить сок с кукурузы и фасоли, положить в посуду. Положить сухарики и измельченную зелень. Посыпать салат перцем, солью, заправить все майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9166,'Снять кожуру с томатов (ошпарить кипятком, тогда кожура легко снимется). Измельчить плоды в блендере или протереть через ситечко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9166,'Положить щепотку свежей измельченной кинзы, лимонный сок, черный перец, соль. Подавать коктейль «Мулатка Мэри» в холодном стакане, положив дольку лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9167,'Взбить яйца, сахар, положить мягкое сливочное масло, насыпать муку с разрыхлителем, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9167,'Замесить тесто (не вымешивать долго). Отправить в холодильник минут на двадцать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9167,'Раскатать, вырезать фигурки, готовить в горячей духовке. Песочное печенье посыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9168,'Порезать лук кольцами, обжарить. Картофель порезать на тоненькие ломтики. Измельчить чесночок и зелень. Намазать формочку сливочным маслом. Выложить картофель, между ломтиками прокладывать лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9168,'Посыпать перцем, солью. Положить чесночок, зелень, мускатный орех. Залить сливками, посыпать сверху крупно натертым сыром. Накрыть крышкой или прикрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9168,'Готовить при температуре двести градусов минут сорок. Снять крышку или фольгу, отправить картофельную запеканку в духовку минут на 25. Картофель должен приготовиться, а сыр подрумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9169,'Взбивать яйца и сахар минут семь. Насыпать муку, вымесить тесто. Положить его в формочку, смазанную маслом. Отправить в горячую духовку, готовить минут 25, соблюдать температуру 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9643,'Поставить массу в микроволновую печь на три минуты. Суфле должно подняться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9169,'Пропитать корж компотом из вишни. Сверху выложить вишню без косточек. Сделать крем: взбить сливки и сахар. Добавить маскарпоне, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9169,'Покрыть кремом вишню. Мелко потереть шоколад. Посыпать пирог «Наслаждение» шоколадом, отправить часа на три в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Положить рульку в кастрюлю, добавить луковицу, разрезанную пополам, крупно порезанную морковь, чесночок. Насыпать перец, гвоздику. Залить светлым пивом, чтобы оно покрывало продукты, можно чуть-чуть разбавить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Довести до кипения, посыпать солью, убавить огонь, накрыть крышкой, варить до готовности. Мясо должно отставать от косточки, это займет часа полтора-два, в зависимости от веса рулек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Приготовить соус: соединить сахар и мед, разбавить несколькими большими ложками бульона, нагреть до полного растворения. Положить горчицу, перемешать, налить пиво, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Подготовить рульку для запекания. По всей поверхности сделать ножом неглубокие надрезы в виде ромба, положить в формочку для запекания, облить соусом, отправить на сорок минут в духовку, разогретую до 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Время от времени поливать соусом (приблизительно через каждые десять минут). Минут через двадцать перевернуть свиную рульку по-немецки на другую сторону для равномерного запекания. За пять минут до конца готовки поднять температуру до 230 градусов, чтобы образовалась корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9170,'Заняться капустой: мелко порубить лук, обжарить до золотистого цвета, положить капусту, налить примерно стакан бульона. Положить тмин, лавровый листик, можжевеловые ягоды. Тушить минут сорок на среднем огне до мягкости, помешивая. Если необходимо, подливать бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9171,'Сделать маринад, соединив и перемешав, все продукты для него. Разрезать тушку цыпленка на части, выложить на противень. Полить маринадом, отправить минут на шестьдесят в холодильник мариноваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9171,'Разогреть духовку до 190 градусов. Порезать лук на дольки, выложить. Измельчить чесночок, посыпать курицу. Порезать апельсин на тоненькие кружки, выложить на курицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9171,'Отправить в духовку на шестьдесят минут. Апельсины начнут подгорать – ничего страшного. Во время готовки смазывать мясо и апельсины маринадом. Достать из духовки блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9171,'От цыплят в маринаде с апельсином будет довольно много сока. Можно полить им гарнир, получается невероятно вкусно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9172,'Порезать ананасы, ветчину и вареные яйца кубиками, на средней терке натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9172,'Репчатый лук очистить, измельчить, сложить в небольшую миску и на 1-2 минуты залить кипятком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9172,'По прошествии отведенного времени сложить все подготовленные ингредиенты в большую миску или салатник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9172,'Заправить содержимое посудины майонезом, добавить немножко кетчупа и тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9172,'Убрать салат с ветчиной и ананасом в холодильник на целую ночь, чтобы он настоялся.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Для приготовления крема перемешать сливки, сливочное масло, щепотку соли и кусочки горького или молочного шоколада. Добавить ванильный сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Смесь прогреть на небольшом огне, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Как только крем станет однородным – его нужно снять с огня, остудить, можно поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Отдельно перемешать молоко с ромом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Каждую пластинку готовой мацы опустить в смесь, выложить на блюдо и промазать готовым шоколадным кремом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9173,'Сверху торт также намазать кремом. Изделие убрать в холод на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Тонко нарезать бекон, обжарить на сухой сковороде до образования корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Подрумянить на сковороде с одной стороны кусочки хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'На не обжаренную сторону намазать майонез.','https:https://st.vkuso.ru/data/cache/thumb/1b/09a1b19f091171b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Выложить по ломтику бекона и сыра.','https:https://st.vkuso.ru/data/cache/thumb/96/fe4e1645958ab96_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Затем мясо.','https:https://st.vkuso.ru/data/cache/thumb/04/7e7f93929857c04_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9174,'Следующий слой – ломтики помидора, красный лук, листья хорошо вымытого и обсушенного зеленого салата.','https:https://st.vkuso.ru/data/cache/thumb/51/b852fdc7f20ef51_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Зелень нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Влить в глубокую емкость кефир, всыпать пищевую соду, перемешать и оставить смесь на пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Лимон хорошо вымыть, обдать кипятком, снять цедру, выдавить сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'То и другое добавить в кефир, всыпать сахарный песок. На поверхности должны появиться пузырьки.','https:https://st.vkuso.ru/data/cache/thumb/a5/552d7b29a9479a5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Подмешать заранее просеянную пшеничную муку.','https:https://st.vkuso.ru/data/cache/thumb/59/f4c6d1c7c0eef59_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Массу перемешать ложкой или силиконовой лопаткой, полученное тесто должно быть однородным и воздушным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Прогреть сковороду, влить растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9175,'Выкладывать по ложке теста, печь оладьи с двух сторон до золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/51/026bdbbaf8cb651_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Для приготовления основы необходимо взбить сырое куриное яйцо со щепоткой соли с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'В отдельной емкости соединить растительное масло с молоком и сахарным песком, добавить взбитое яйцо, массу хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Дрожжи соединить с просеянной пшеничной мукой, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Тесто должно получиться крутым, плотным, его нужно накрыть тканью и дать постоять в течение получаса или больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Раскатать массу в круглую лепешку, размер – на пять сантиметров больше формы. Саму форму для выпекания застелить бумагой, смазать растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Выложить тесто, придавить, сформовать бортики, лишнее срезать, это можно сделать ножницами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Для начинки взбить яйца, добавить остатки сахара, взбить еще раз до пышной консистенции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Добавить жирную сметану и пакетик ванилина, смешать венчиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Готовую массу перелить в основу. По желанию из остатков масла можно сделать украшения для бортика.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Время выпекания – от 40 до 45 минут, температура – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'При готовности начинка-заливка должна пружинить – это можно проверить пальцем.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9176,'Перед подачей пирог остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9177,'Очищенные бананы разрезать на две половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9177,'Смешать воду с крахмалом, мукой, яичным белком и оливковым маслом (можно использовать кунжутное)',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9177,'Разогреть растительное масло в сковороде или кастрюле с толстыми стенками, обмакнуть половинки банана в кляр, обжарить со всех сторон до золотистого колера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9177,'Смешать  мед  с соком  лимона, слегка нагреть в кастрюле на слабом огне  и полить полученным соусом бананы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9177,'Бананы в медово-лимонной глазури присыпать кунжутом или сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Готовое слоеное тесто из магазина разморозить на кухне, раскатать и нарезать неширокими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Обмотать полосками сосиску так, чтобы с одной стороны остался незакрытый кусочек для лица.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Температура выпекания – 220 градусов, время – от 15 до 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Готовые хот-доги вынуть, немного остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Глаза можно сделать из горчицы, кетчупа или горошин перца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9178,'Подать булочки с кетчупом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Капусту бланшировать, в воду можно для цвета добавить немного куркумы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Сырые куриные яйца взбить с молоком, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Небольшие формы смазать подсолнечным рафинированным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Выложить цветную капусту, сверху – нарезанные ломтиками помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Залить продукты яично-молочной смесью и посыпать тертым твердым сыром, «Российским» или «Пармезаном».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Поставить блюдо в духовой шкаф на 25 минут, температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9179,'Подать запеканку в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'В миске смешать муку, яйцо и воду, чтобы получилось тесто, консистенция которого будет похожа на теста для пельменей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'В готовый фарш добавить измельченный лук, соль и перец, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Подготовленное тесто разделить на желаемое количество кусочков и каждый раскатать в лепешку: размер лепешки должен быть немного больше, чем размер лепешки на манты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11809,'Залить водой, чтобы удалить излишки крахмала.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Смазать каждую получившуюся лепешку подготовленным фаршем, свернуть в рулет и хорошо защепить края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Порезать луковицу полукольцами, крупно натереть морковь, очищенный от семян и серединки болгарский перец порезать полукольцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'На сковороду с маслом выложить подготовленные овощи, добавить к ним очищенный чеснок и немного обжарить. Далее в овощи подмешать желаемое количество томатной пасты, соли и любимых приправ.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Содержимое сковородки перемешать и выложить на тушеные овощи подготовленные рулеты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Залить рулеты водой таким образом, чтобы она их покрывала почти полностью и на маленьком огне тушить блюдо до полной готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9180,'Готовые рулеты с мясом, тушеные в соусе подавать в горячем виде, украсив при желании рубленой зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9181,'Смазать маслом формочки для маффинов, включить на разогрев  духовку на 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9181,'Поломать шоколад, сложить в сотейник, добавить сливочное масло, чуть нагреть, хорошо перемешать до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9181,'Взбить миксером сахар, 3 желтка и  3 яйца, примерно около 3 минут, влить шоколад, всыпать муку и щепотку соли, тщательно размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9181,'Заполнить полученной массой формочки, отправить португальские горячие пирожные с горьким шоколадом на 10 минут в духовку. Вынуть готовый десерт, обсыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9182,'Смешать в глубокой миске яйца, треть банки сгущенки, сахар, взбить миксером, всыпать смесь разрыхлителя с мукой, вымесить тесто. Всыпать половину крупноизмельченных орехов, изюм, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9182,'Перелить смесь в подготовленную форму, выпекать в горячей духовке около 40 минут при 180 градусах до состояния «сухой спички».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9182,'Смешать в сотейнике остаток сгущенки и молоко, подогреть, довести до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9182,'Готовый пирог с грецкими орехами, сгущенкой и изюмом остудить прямо в форме, полить молочным кремом, присыпать орехами, дать перед подачей настояться несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'В небольшую кастрюльку влить молоко, всыпать обычный сахар, ванильный сахар, муку и крахмал. Поставить на огонь и, не переставая мешать, нагревать массу, пока не появится редкое бульканье: консистенция крема должна напоминать густую манную кашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Затем выключить огонь и мешать крем в течение 3-х минут, чтобы он не пригорел, после чего оставить крем остывать, время от времени его перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Размягченное сливочное масло взбить со сливками и порциями ввести в остывшую заварную массу: должен получиться нежный воздушный крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Один бисквитный корж нарезать полосками по 4-5 см в ширину, второй положить на дно разъемной формы и из подготовленных бисквитных полосок выложить бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Смазать дно и бортики из бисквита джемом и по нижнему смазанному коржу распределить подготовленный заварной крем (толщина слоя около 1 см).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Уложить на кремовый слой по кругу сперва целые бананы, а затем плоды, разрезанные на части.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'По бананам до самых краев бортиков распределить заварной крем и накрыть все третьим коржом, который затем смазать джемом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Верх торта промазать оставшимся кремом и хорошенько посыпать оставленной после нарезания полосок бисквитной крошкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'Убрать торт с бананами и джемом в холодильник либо на 6 часов, либо на всю ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9183,'С застывшего торта аккуратно снять бортик формы, переложить изделие на сервировочное блюдо или нарезать порционными кусками и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9184,'Почистить от прожилок филе утки, кожу надсечь ромбами, положить мариноваться в соевом соусе и меде. Поставить на плиту сотейник, сделать минимальный огонь, положить филе утки вниз кожей. Со стороны кожи готовить минут двенадцать, перевернуть и готовить еще семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9184,'Накрыть мясо крышкой, выключить огонь и оставить минут на восемь, чтобы филе дошло до готовности. Помыть листья салата, высушить салфеткой. Порезать дайкон тоненькой соломкой, замочить минут на пять в холодной воде, чтобы вышла острота и горечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Прикрыть листом бумаги для выпечки и вернуть в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9184,'Сделать заправку: соединить и перемешать все продукты в посуде, положить измельченный зеленый лук. Разрезать огурчики пополам в длину, вырезать семена, порезать на длинные бруски, кожицу оставлять. Порезать звездочками карамболу, разделить лайм на сегменты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9184,'Разогреть ложку масла на сковороде, обжарить до золотистости орешки кешью. Насыпать паприку, тростниковый сахар, добавить измельченные горошины розового перца. Когда растопится сахар, все размешать, орехи должны покрыться пряной карамелью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9184,'В большой посуде соединить проростки, огурцы, дайкон, лайм, карамболу, салатные листья, орешки кешью, заправить все заправкой, разложить по тарелочкам. Порезать утку на ломтики, поделить по порциям, положить грудку на азиатский салат сверху.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Охлажденное сливочное масло нарезать кубиками, добавить заранее просеянную пшеничную муку, порубить тесто в крошку ножом.','https:https://st.vkuso.ru/data/cache/thumb/42/d1dc7c2d2f64442_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Добавить в массу сушеный розмарин и сырое яйцо, дополнительный желток и ледяную воду.','https:https://st.vkuso.ru/data/cache/thumb/a3/ae47e7e4655a9a3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Полученное песочное тесто скатать в шар, поставить в холодильник на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/64/f741cde3d572464_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Отварить куриную грудку, нарезать филе мелкими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Натереть сыр сулугуни на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Консервированную белую фасоль в томатном соусе откинуть на сито, дать стечь жидкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Крупно порубить зеленую петрушку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Перемешать фасоль, куриное мясо, зелень и сыр, соль и молотый перец – по вкусу. По желанию можно добавить лимонный сок.','https:https://st.vkuso.ru/data/cache/thumb/bc/54aeb3b00e923bc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Готовое тесто раскатать в тонкий пласт толщиной в полсантиметра. Форму смазать маслом и присыпать панировочными сухарями, сделать бортики высотой в пять сантиметров. Лишнее тесто удалить.','https:https://st.vkuso.ru/data/cache/thumb/7b/4f4853360328f7b_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Выложить начинку, сверху посыпать остатками сыра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Печь в течение 50 минут при температуре 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9185,'Готовый пирог должен постоять 15 – 20 минут, затем его можно подать на стол.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9186,'Бананы очистить от кожуры и разрезать на 3 равные части, с помощью коктейльной трубочки вынуть из каждой части сердцевину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9186,'Шоколад растопить и обмакнуть в него низ каждого банана, обсыпать шоколадную поверхность дроблеными орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9186,'Поместить будущий десерт с бананами в шоколаде в холодильник, чтобы шоколад затвердел.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9186,'Кондитерский шприц наполнить шоколадной пастой и заполнить ей «пустоту» в каждом охлажденном банане.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Очистить чеснок, порубить его ножом максимально мелко.','https:https://st.vkuso.ru/data/cache/thumb/86/521bdb4bbbf7686_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Свежий базилик хорошо вымыть проточной водой, измельчить. Нарезать кубиками свежие помидоры.','https:https://st.vkuso.ru/data/cache/thumb/4c/17129e53b0be34c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Все перечисленные ингредиенты сложить в миску, перемешать, подлить оливковое масло, соль – по вкусу. Блюдо накрыть пищевой пленкой, дать постоять час или два при комнатной температуре, соус должен хорошо настояться.','https:https://st.vkuso.ru/data/cache/thumb/7a/c72c83f73b64f7a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Отдельно отварить до готовности макароны в кипящей подсоленной воде.','https:https://st.vkuso.ru/data/cache/thumb/d2/22a7bbba14f07d2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Выложить продукт на дуршлаг, а затем вернуть в кастрюлю, залить соусом, посыпать тертым сыром «Пармезан».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9187,'Массу перемешать и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9188,'Разогреть духовку. В большой посуде соединить корицу, соду, муку, разрыхлитель, гвоздику. Насыпать душистый перец, сахар, соль. Вбить яйцо, добавить большую ложку молока и половину растопленного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9188,'Положить тесто в полиэтиленовый пакет или кондитерский мешочек. Срезать уголок пакета, выдавить тесто в формочку, намазанную маслом, заполнив на половину. Готовить в духовке минут восемь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9188,'Растопить остальное масло с несколькими ложками молока и шоколадом, поломанным на куски. Отправить на огонь, держать, пока ингредиенты не соединятся. Обмакнуть имбирные пончики с корицей в глазурь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11816,'Поставить режим «Жарка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9189,'Сделать крем: взбить масло (размягченное) с сахарной пудрой. Налить коньяк, добавить кофе и желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9189,'Намазать кремом печенье, посыпать кофейный торт миндалем. Отправить часов на восемь в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9190,'Порезать ветчину и твердый сыр соломкой, перемешать, вбить яйцо, добавить чуть молотого перца и майонез, хорошо размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9190,'Ломти хлеба смазать полученной пастой, переложить на противень, поместить в прогретую до 180 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9190,'Готовые горячие бутерброды можно  будет подать к столу уже через четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Отварить макароны так, как написано на упаковке, воду подсолить.','https:https://st.vkuso.ru/data/cache/thumb/e6/81bdeac6e071fe6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Полутвердый сыр натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Растопить в сотейнике сливочное масло, помешивать лопаточкой.','https:https://st.vkuso.ru/data/cache/thumb/90/729b1bed0376790_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Всыпать муку и хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/e5/06e4f02207912e5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Подлить молоко, помешивать до закипания.','https:https://st.vkuso.ru/data/cache/thumb/72/d77a16fe8528c72_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Огонь выключить, добавить тертый твердый сыр, любые специи, например, паприку и молотый чеснок. Еще раз хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/63/a243c7f1ff79e63_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Можно добавить немного воды или молока, соус станет глянцевым, гладким.','https:https://st.vkuso.ru/data/cache/thumb/e6/157c0c92c3685e6_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9191,'Перелить в готовую пасту.','https:https://st.vkuso.ru/data/cache/thumb/26/7434b9a0210e426_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9192,'Приготовить из картофеля пюре, перемешать его с яйцом, маслом и натертым сыром, присолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9192,'Обжарить нашинкованный лук до золотистости, смешать его с мясным фаршем, яйцом, рисом, присолить, поперчить, хорошо перемешать, по желанию добавить нашинкованную зелень и пряности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9192,'Заполнить картофельным пюре небольшие формочки (смазать маслом) для кексов, по центру выложить с горкой фарш. Присыпать сыром, выпекать куриные тефтели в духовке с температурой чуть выше 185 градусов около 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Каждый кабачок помыть и порезать на кружки 1,5-2 см толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Все кружочки посыпать солью и черным молотым перцем, выложить заготовки на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Духовку разогреть до 180  градусов и запекать в ней кабачки в течение 7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Помидоры помыть и нарезать кружочками, по истечении 7 минут достать кабачки из духовки и положить на каждый по кружочку помидора.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Убрать противень обратно в духовку на 5 минут, после чего посыпать кабачки тертым сыром и запекать блюдо, пока не расплавится сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9193,'Готовые запеченные в духовке кабачки под сыром с помидорами подавать в горячем виде, при желании посыпав рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9194,'Яйца разболтать в однородную массу, слегка присолить. Вылить смесь на разогретую сковороду с растопленным сливочным маслом, обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9194,'Прямо на сковороде на половину рулета положить пластинки ветчины и листья рукколы, свернуть в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9194,'Переложить рулет из омлета на блюдо, порезать поперек на несколько кусочков, есть лучше горячим. Отдельно можно подать сметану, кетчуп или другой соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Сахарный песок перемешать с водой, довести до кипения, кипятить пять минут, огонь – средний. Температуру уменьшить до минимальной величины, уварить сироп в течение 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Влить в другую емкость лимонный сок, добавить сироп, перемешать и остудить. Все эти процедуры можно проделать заранее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Растопить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Купленный в магазине блок теста фило выложить на доску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Острыми ножницами или ножом разделить пополам, лишнее удалить, куски должны быть по размеру формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Форму для выпекания смазать сливочным маслом, выложить два листочка теста, смазать их тем же растопленным маслом кулинарной кисточкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Накрыть еще двумя листами, смазать маслом, продолжать до тех пор, пока не закончатся листочки из первого блока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Верх тоже смазать маслом и посыпать молотыми грецкими орехами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Выложить второй блок точно так же.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Заточенный нож окунуть в горячую воду, надрезать изделие прямоугольниками до орехового слоя.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Поставить пирог в духовку на среднюю полку, печь в течение 25 минут при температуре 180 градусов, огонь уменьшить до 160 градусов, печь еще столько же.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Духовку выключить, пахлаву вынуть, оставить в форме на 10 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Дорезать пирог до конца. Равномерно полить сиропом, стараясь попадать в разрезы.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9195,'Оставить выпечку на четыре часа для пропитывания. Накрыть блюдо фольгой, в холодильник не ставить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Для приготовления маринада перемешать размягченное сливочное масло, дижонскую горчицу и молотую паприку. Посолить по вкусу, добавить молотый белый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Мясо вымыть, обсушить с помощью салфеток, разрезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Каждый кусочек намазать готовой смесью, переложить в миску, накрыть пленкой, поставить на час в холодильник для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'В разогретый сотейник или сковороду положить немного сливочного масла, выложить курицу, жарить со всех сторон до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Подлить белое сухое вино, огонь уменьшить, тушить блюдо под крышкой в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Курицу переложить на тарелку и накрыть крышкой, чтобы не остыло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Для соуса процедить в сотейник или небольшую кастрюлю вино, в котором тушилось мясо, влить сливки, всыпать муку, перемешать и прогреть на тихом огне. В массе не должно быть комочков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Добавить горчицу. Снять с огня.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Положить в соус половину нормы тертого сыра «Грюйер» или аналогичного. Перец молотый и соль – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Почти готовые кусочки курицы переложить в форму для запекания, полить винным соусом и посыпать остатками сыра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9196,'Печь в духовке при температуре 200 градусов до образования румяной корочки в течение 15 минут. Мясо выложить на тарелку, полить соусом и подать к столу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Репчатый лук, чеснок и перец чили накрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Залить шафран небольшим количеством кипятка, дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Сладкий болгарский перец очистить и нарезать кубиками среднего размера, кабачки цуккини и патиссоны – средними кусочками произвольной формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Разогреть на сковороде оливковое масло, обжарить перец чили, лук и чеснок.','https:https://st.vkuso.ru/data/cache/thumb/ef/1f7d14042387fef_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Переложить пряную массу в глубокую посуду, поставить на средний огонь, прогреть, затем всыпать остальные овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Массу перемешать, готовить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Всыпать в сковороду рис, перемешать, прогревать еще две-три минуты, зерно должно впитать аромат овощей.','https:https://st.vkuso.ru/data/cache/thumb/fa/6ddfe4a786b6ffa_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Обычные томаты и помидоры черри нарезать, добавить в сковороду, влить настой шафрана.','https:https://st.vkuso.ru/data/cache/thumb/7d/9be22e9f971747d_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Перемешать и прогревать три-четыре минуты.','https:https://st.vkuso.ru/data/cache/thumb/da/6e78e8702b824da_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Влить воду, она должна покрыть рис на полсантиметра. Далее блюдо не перемешивать.','https:https://st.vkuso.ru/data/cache/thumb/61/36077ac47105f61_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Довести массу до кипения, огонь уменьшить, накрыть блюдо крышкой. Тушить 10 – 12 минут, две трети жидкости должны впитаться в рис.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9197,'Добавить зеленый горошек, накрыть крышкой, огонь выключить, оставить блюдо на 15 минут. При подаче посыпать кушанье измельченной зеленью.','https:https://st.vkuso.ru/data/cache/thumb/ad/60617ec49e613ad_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9198,'Подготовить форму, прогреть духовку до 160 градусов. Блендером измельчить в мелкую крошку печенье или несоленые хрустящие крекеры, добавить растопленное сливочное масло, смешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9198,'Переложить маслянистую крошку в форму, разровнять, сделать бортики и утрамбовать, дать полчаса застыть в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9198,'Положить в чашу миксера сахар и сливочный сыр, взбить до однородного состояния, вбить по одному яйца (перемешивать после каждого), добавить жирные сливки, сметану, хорошо размешать, разделить на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9210,'Какао-порошок соединить с корицей и сахаром, добавить немного кипящей воды, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9198,'Влить в одну апельсиновый ликер (Grand Marnier), всыпать цедру апельсина, в другую – растопленный шоколад. Достать форму, выложить на крошку половину шоколадной смеси, на нее – апельсиновый крем, операцию повторить. Размешать чуть-чуть ножом до получения «мраморного» эффекта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9198,'Выпекать чизкейк «Зебра» с апельсиновым ликером примерно 50 минут, отключить нагрев, дать десерту остыть пару часов в духовке. Для полного застывания убрать в холодильник на ночь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Половину огурцов, помидоров и репчатого лука нарезать небольшими кусочками и положить в комбайн.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Добавить консервированный красный сладкий перец и измельчить все в пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Перелить массу в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Влить томатный сок, красный винный уксус, кинзу, оливковое масло, добавить несколько капель соуса «Табаско».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Из оставшихся помидоров вынуть семена, мякоть нарезать кубиками. Таким же образом нарезать лук и огурец. Овощи добавить в основную массу. Перец и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9199,'Поставить готовый суп в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9200,'Подготовить мясо: зачистить, помыть, обсушить, нарезать кусками толщиной в 1 см, на пару часов замариновать. Раскалить сухую сковороду, обжарить каждый кусочек по паре минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9200,'Выложить в огнеупорную форму слой из колечек лука, на него – мясо, а сверху – кружки помидора. Полить все маринадом, запаковать верх фольгой, отправить свинину по-особому в прогретую до 180 градусов духовку примерно на 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9200,'Удалить фольгу, присыпать верх сырной стружкой, залить 20% сливками, убрать еще на 10 минут для зарумянивания в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9201,'Отваренный в мундире картофель, вареную колбасу без жира и сыр крупно натереть, вбить яйца, добавить порубленные перья зеленого лука, подсолить, поперчить, всыпать муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9201,'Из полученной массы сформовать биточки, обмакнуть в муку, обжарить в прогретом масле с двух сторон, подать со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9202,'Для начинки пирога подготовить яблоки: очистить, убрать семена, порезать на дольки, чуть взбрызнуть лимонным соком. Хорошо промыть изюм, залить теплой водой, дать постоять, воду сцедить, перемешать с яблоками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9202,'Сахар вместе с яйцами взбить до получения пышной массы, добавить хорошую сметану, влить распущенное масло, продолжая взбивать, постепенно всыпать порциями муку вместе с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9202,'Полученным тестом заполнить наполовину смазанную маслом и обсыпанную молотыми сухарями форму, уложить слой начинки, вылить на нее остатки теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9202,'Выпекать яблочный пирог «Домашний» в заранее прогретом до 180 градусов духовом шкафу около 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9202,'Для оформления верха растереть масло с мукой и небольшим количеством сахара до получения маслянистой крошки, присыпать готовую выпечку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9203,'Обжарить пару минут измельченный чеснок и лук, добавить кусочки баклажана, подсолить, готовить еще 10-12 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9203,'Порезать острым ножом помидоры, переложить в сковороду, перемешать, всыпать сахар, влить соевый соус, обжарить все вместе минуты 3-4.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9203,'Последний штрих в приготовлении баклажанов по-китайски - добавить кунжутное масло и крахмал, хорошо размешать и убрать с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9204,'Нарезать как можно мельче лук, натереть крупно морковку, курицу и сладкий перец порезать на мелкие кубики. Обжарить мясо, поперчить, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9204,'Отдельно приготовить зажарку из морковки и перца, когда они станут мягкими, всыпать лук, чуть подсолить и немного обжарить. Форму промазать маслом, уложить слой риса, далее – овощи и половину нормы сметаны, затем положить мясо, прикрыть его слоем кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9204,'Залить все остатками сметаны, присыпать сыром. Отправить  куриную запеканку на полчаса в духовой шкаф, готовить при среднем нагреве, остудить, порезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Разогреть на сковороде немного сливочного и оливкового масла.','https:https://st.vkuso.ru/data/cache/thumb/47/8d5593334eb5847_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Очистить и порубить чеснок, добавить его в смесь, перемешать, немного прогреть, не допустить пригорания.','https:https://st.vkuso.ru/data/cache/thumb/dc/5ab662f4bb748dc_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Пшеничную муку поджарить в жире, добавить её в чесночно-масляную смесь, прогревать все вместе в течение минуты. Масса должна загустеть и потемнеть.','https:https://st.vkuso.ru/data/cache/thumb/01/4037bd9be915001_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Жирные сливки, куриный, говяжий или овощной бульон разогреть на плите или в микроволновой печи. Жидкости нельзя доводить до кипения.','https:https://st.vkuso.ru/data/cache/thumb/95/c56467aa2997295_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Оба продукта влить в обжаренную муку, помешивать венчиком, огонь – средний. Смесь прогревать до слабого кипения.','https:https://st.vkuso.ru/data/cache/thumb/34/c09bde795f86b34_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Добавить специи по вкусу, перец, соль, не допускать сильного кипения.','https:https://st.vkuso.ru/data/cache/thumb/a3/401782900ace4a3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9205,'Натереть сыр «Пармезан» или аналогичный, всыпать в соус, перемешать до расплавления. Массу можно сделать еще гуще, если прогревать её несколько минут до выпаривания жидкости.','https:https://st.vkuso.ru/data/cache/thumb/1d/6c596e464dd801d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9206,'Хорошие сосиски высокого качества очистить от оболочек, отрезать кончики. На каждом изделии сделать несколько надрезов, отварить до готовности в кипящей воде, остудить.','https:https://st.vkuso.ru/data/cache/thumb/1c/2a75c43cc5a8a1c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9206,'Раскрывшиеся кусочки сосисок становятся похожи на крабов и осьминогов. Сделать на них глаза из кусочков сыра, сладкого болгарского перца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9206,'Подать блюдо с зеленым горошком, апельсиновым соком, цельнозерновым хлебом.','https:https://st.vkuso.ru/data/cache/thumb/cb/75834e19df312cb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9207,'Сливочное масло комнатной температуры растереть с сахарным песком, добавить сырое куриное яйцо и дополнительный желток, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9207,'Влить лимонный сок одного лимона, еще раз перемешать и всыпать муку, продолжать мешать до получения теста плотной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9207,'Массу вымешать, раскатать толщиной 1 – 1,5 см, нарезать кружочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9207,'Противень застелить бумагой, печь 10 минут. Выпечка должна остаться белой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9207,'Склеить изделия по два с помощью клубничного джема, посыпать сахарной пудрой, ароматизированной ванилью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9208,'Отварить спагетти в соленой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9208,'Порезать грибы на пластинки, обжарить на сковороде с луком, добавив сливочное и растительное масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9208,'Потереть на терке плавленый сыр, положить к грибам. Налить сливки, держать на огне, пока сыр не расплавится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9208,'Убрать с огня, насыпать перец, соль, добавить прессованный чесночок. Размешать, положить к отваренным спагетти.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9208,'Размешать, украсить зеленью, можно подавать спагетти с шампиньонами в сливочно-чесночном соусе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Очистить лук, чеснок и морковь. Репчатый лук и чеснок мелко нарезать кубиками, а корнеплод – брусочками.','https:https://st.vkuso.ru/data/cache/thumb/7f/6281af792beb97f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Телятину нарезать кубиками крупнее, со стороной в три сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'В сотейнике или в кастрюле с толстым дном разогреть оливковое масло, обжарить в нем мясо до румяной корочки со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/07/4540a73892c2a07_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Всыпать муку, перемешать и выложить телятину на блюдо.','https:https://st.vkuso.ru/data/cache/thumb/5e/3422e6413fd255e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'В ту же кастрюлю или сотейник долить еще немного оливкового масла, обжарить на нем измельченные овощи до прозрачного состояния, на это потребуется две-три минуты.','https:https://st.vkuso.ru/data/cache/thumb/0b/baa0b1bda03f50b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Вернуть мясо в кастрюлю, перемешать, добавить веточки тимьяна и лавровый лист. Добавить белое полусухое вино, выпарить его на сильном огне в течение двух минут.','https:https://st.vkuso.ru/data/cache/thumb/0b/701af0c74e6670b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Влить заранее сваренный бульон или воду, жидкость должна покрыть мясо. Соль и перец – по вкусу. Влить томатную пасту, перемешать и довести смесь до кипения.','https:https://st.vkuso.ru/data/cache/thumb/dc/a7bd2066a2a63dc_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Варить блюдо под крышкой в течение получаса на небольшом огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Нарезать шампиньоны, положить к мясу, продолжить тушить блюдо еще час, мясо должно стать мягким. Досолить и поперчить, если это требуется.','https:https://st.vkuso.ru/data/cache/thumb/b5/c6112d70c3357b5_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9209,'Перед подачей веточки тимьяна и лавровый лист вынуть, подать кушанье теплым.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Десерт оформить карамелью, свежими ягодами или шоколадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9210,'Разогреть молоко в турке или сотейнике, до кипения не доводить, влить шоколадную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9210,'Варить все вместе пять минут, огонь – тихий, не помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9210,'Снять напиток с огня, удалить получившуюся пленку, жидкость перелить в кружку, выложить маршмеллоу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9211,'Вымыть огурцы, отрезать с обеих сторон кончики, измельчить укроп, чесночок, сложить все подготовленные ингредиенты в пакетик, насыпать соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9211,'Все размешать, потрясти, отправить в холодильник на восемь часов, время от времени потряхивать пакет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Сливочное масло комнатной температуры размять вилкой и перемешать с коричневым сахаром и мукой до образования крошки.','https:https://st.vkuso.ru/data/cache/thumb/a6/1a0750eed69bca6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Тесто выложить на противень руками, а потом уплотнить дном стакана или небольшой кастрюли.','https:https://st.vkuso.ru/data/cache/thumb/66/c4640189b05f766_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Поставить в заранее разогретую духовку, печь при температуре 175 градусов в течение 15 минут, корж должен зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'В большой емкости взбить сливочный сыр с сахаром, вбить яйца по одному, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/e5/0bc093e99fc00e5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Добавить ваниль. Налить начинку на корж.','https:https://st.vkuso.ru/data/cache/thumb/9c/91deadc4ca4029c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Яблоки очистить, нарезать кубиками, присыпать сахарным песком и молотой корицей.','https:https://st.vkuso.ru/data/cache/thumb/9f/c7cf4278b043e9f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Выложить фрукты поверх сыра.','https:https://st.vkuso.ru/data/cache/thumb/d2/5610a3e7a61c1d2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'В небольшой миске смешать овсяные хлопья, муку, коричневый сахар. Сливочное масло нарезать кусочками и добавить в мучную смесь, перемешать в крошку.','https:https://st.vkuso.ru/data/cache/thumb/88/d7fe857aa2d6f88_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Насыпать её поверх яблок. Печь чизкейк в течение получаса, за пять минут до готовности температуру снизить до 150 градусов.','https:https://st.vkuso.ru/data/cache/thumb/28/8a91e40433e3528_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9212,'Готовый пирог нарезать квадратиками, полить жидкой карамелью.','https:https://st.vkuso.ru/data/cache/thumb/4f/072ebd3fbf3fb4f_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9213,'Соединить муку и разрыхлитель, порубить с холодным маслом. Взбить яйца и сахар. Все соединить, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9213,'Завернуть его в полиэтилен, отправить минут на тридцать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9213,'Чтобы сделать начинку, соединить все продукты, измельчить при помощи блендера до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9213,'Достать тесто, переложить в формочку, сформировать бортики. Сверху положить начинку, нарезанные фрукты, налить сметану с сахаром, выпекать минут пятьдесят.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9213,'Позволить творожной запеканке с бананами и персиками в сметанной заливке полностью остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'Порезать грибочки на кубики, пожарить на растительном масле с мелко порезанным лучком, посыпать перцем, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'Положить в грибы тертый сыр, сливки, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'Отбить филе курицы, посыпать перцем, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'На середину положить грибной фарш, завернуть, придать форму «бомбочки», если нужно, закрепить зубочистками. Завернуть в намазанную маслом фольгу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'Готовить в духовке минут 30, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9214,'Убрать фольгу, позволить куриным бомбочкам с сырно-грибной начинкой подрумяниться  10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9215,'Перемешать при помощи миксера сгущенное молоко, яйца, муку, просеянную с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9215,'Почистить яблоки, вырезать сердцевину, порезать на кольца, выстелить в формочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9215,'Посыпать орешками (предварительно их подсушить и крупно порубить) , цедрой, изюмом, корицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9215,'Вылить тесто в формочку. Готовить до румяности минут 40.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9215,'Охладить, присыпать шарлотку с яблоками и грецкими орехами на сгущенке сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9216,'Очистить грибы, порезать на пластины, пересыпать в сковороду с разогретым маслом, тушить до полной готовности под крышкой, приправить майораном и черным молотым перцем, перемешать, прогреть еще пару минут, снять с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9216,'Отдельно потушить крупно натертую морковку с измельченным чесноком, добавить шпинат, довести до полной готовности овощей, перемешать с грибами, подсолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11844,'Готовые изделия выложить на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9216,'Для соуса закипятить молоко, всыпать мускатный орех, положить лавровый лист, прикрыть плотно крышкой, оставить на 10-15 минут. В горячем сливочном масле обжарить муку до золотистости, влить маленькими порциями, все время перемешивая, молоко, прогреть до получения однородной бархатистой массы похожей на кефир.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9216,'Собрать лазанью с шампиньонами и шпинатом в следующем порядке: налить несколько ложек соуса в форму, уложить готовые листы, на них – грибную смесь, разровнять, полить соусом, присыпать сыром, все повторить до окончания ингредиентов. Убрать в прогретую примерно до 200 градусов духовку на 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9217,'Разболтать дрожжи в чуть теплом молоке, всыпать стакан муки и сахар, дать постоять не менее 30 минут до образования над опарой пышной шапки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9217,'Перемешать в однородную жидкость яйца, вылить в опару, всыпать остаток чуть подсоленной просеянной муки, для аромата – ванильный сахар, влить растительное масло, тщательно перемешать в однородную массу, дать тесту постоять еще 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9217,'Выкладывать тесто в хорошо прогретое масло столовой ложкой, обжаривать пышные оладушки на дрожжах с двух сторон до образования хрустящей желто-коричневой корочки. В качестве «соуса» можно предложить варенье, сметану или мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9218,'Помыть и очистить яблоки, побрызгать их соком лимона, чтобы не изменился цвет. Приготовить из сахара и доведенной до кипения воды раствор, нагреть его на слабом огне до кипения и полного растворения сахара, цвет карамели должен стать насыщенного золотистого цвета, но не слишком темного, иначе она начнет горчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9218,'В углубление от хвостика каждого яблока вставить по палочке, аккуратно окунуть в карамель, а затем в смесь орехов или цветную присыпку. Дать яблокам в карамели застыть, быстрее это получится в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9219,'Подготовить все ингредиенты для салата: натереть огурец, отжать лишний сок, сварить морковку и яйца, натереть по отдельности, сыр тоже измельчить на терке, рыбу размять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9219,'Все продукты разложить послойно по креманкам. Начать с тертых белков, далее чуть майонеза, потом слой рыбы, прикрыть свежими огурцами, слегка присолить промазать майонезом, уложить морковь, притрусить сырной стружкой, смазать небольшим количеством майонеза, присыпать верх салата с тунцом желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9219,'Перед подачей к столу дать слоям салата немного пропитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Творог протереть сквозь сито в однородную массу, печенье размельчить блендером до состояния очень мелкой крошки, перемешать ее с маслом до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Выложить на дно разъемной формы пергаментный круг, установит борта, закрыть защелку, прижав бумагу, это позволит легко извлечь готовый торт из формы. Разложить ровным слоем и утрамбовать массу из печенья на дне формы, убрать в холодильник, заняться начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Залить пластинки желатина водой, дать постоять согласно инструкции для разбухания, прогреть до 40-50 градусов на слабом огне и при постоянном помешивании до прозрачного состояния, дать раствору остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Измельченные блендером ягоды протереть сквозь сито, хорошо перемешать, а лучше взбить, сметану, творог и сахар до пастообразного состояния без крупинок. Треть полученной массы перемешать с ягодным пюре, можно всыпать пару ст.л. сахара, хорошо взбить, добавить половину раствора желатина (вливать тонкой струйкой, постоянно размешивая), взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Оставшийся желатин перемешать с творожной массой. В достаточно охладившуюся форму налить по центру 5 полных столовых ложек творожно-желатиновой массы, повторить операцию с ягодной массой, продолжать пока начинка для двухцветного творожного торта не закончится и полностью не заполнится форма.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9220,'Для оформления «прочертить» по поверхности зубочисткой 8-10 радиусов.  Отправить десерт минимум на 5 часов застыть, а идеальный вариант – дать переночевать в холодильнике, вынуть из формы, освободить от бумаги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9221,'Включить для прогрева до 180 градусов духовку. Грибы вымыть, очистить, порезать на пластины, мелкие можно не резать, добавить полукольца лука, сырную стружку, сметану, приправить тимьяном, перцем, подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Нашинковать лук и сладкий перец, обжарить, помешивая минут 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9221,'Тесто раскатать в форме прямоугольного пласта и проколоть вилкой, чтобы при выпечке форма коржа не изменилась. Разложить по поверхности начинку, отступив с краев по паре сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9221,'Выпекать пирог с сыром, сметаной и грибами полчаса в уже прогретой духовке до появления золотистости коржа, дать слегка остыть порезать на куски, подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9222,'Смешать кефир, просеянную подсоленную муку, соду, очень тщательно перемешать до образования однородного теста, поместить его на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9222,'Капусту мелко нашинковать, потушить минут 5, всыпать обжаренный тмин, порубленную зелень, специи, слегка присолить, тушить все вместе еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9222,'Раскатать из половины теста пласт, выложить его в форму (предварительно ее промазать маслом и притрусить мукой или манкой), уложить на него начинку, прикрыть пластом из оставшегося теста, верхний и нижний корж капустного пирога с зеленью тщательно защипать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9222,'Сделать ножом на поверхности несколько насечек, отправить в разогретую духовку на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9223,'Разболтать в отдельной посуде яйца, перемешать сахар с просеянной мукой, солью, содой, перцем и разрыхлителем, влить смесь растопленного масла и кефира, замесить тесто, всыпать тертый сыр, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9223,'Испечь вафли согласно инструкции, разложить остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9223,'Тщательно вымыть листья салата, помидоры нарезать на кружки, в прогретой чуть ниже 200 градусов духовке обжарить (процесс займет около четверти часа) на выстланном фольгой противне бекон, достать его, разложить на несколько слоев бумажного полотенца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9223,'Из смеси майонеза и горчицы, сдобренных солью и перцем, приготовить соус для сэндвичей из сырных вафель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9223,'Смазать половину вафель соусом, разложить помидоры, бекон и салат, прикрыть оставленными вафлями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9224,'Размешать размякшее масло с сахаром, добавить муку, яйца и гашеную уксусом соду, хорошо вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9224,'Обжарить цельные (по желанию можно измельчить в блендере) хлопья на сухой сковороде, сильно не зажаривать, пусть только слегка зарумяниться, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9224,'Всыпать в тесто хлопья, дробленые орехи и цедру лимона, перемешать до получения однородного теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9224,'От общего куска отщипывать небольшие кусочки, скатать в шарики, расплюснуть между ладонями, разложить овсяное печенье с орехами на противне, выстланном пергаментом, выпекать около получаса в духовом шкафу с температурой порядка 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9225,'Всыпать к яйцам сахар, взбить, положить сметану, перемешать, добавить смешанную с разрыхлителем муку, все как следует перемешать до получения однородной массы, разделить ее на три равные части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9225,'В первую всыпать мак, перемешать, во вторую – порошок какао с дроблеными орехами, в третью – только какао, испечь (по 15 минут) при 180 градусах из каждой по коржу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9225,'Для приготовления крема вымешать сахар и сметану. Промазать ореховый корж кремом , следом – маковый, корж из какао нарезать на кубики, хаотично разложить по верху, равномерно облить оставшимся кремом, а поверх – жидким шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9225,'Отправить торт «Екатерина» ночевать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9226,'Порубить перья лука и вареные яйца, перемешать, чуть подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9226,'Притрусить  стол мукой, готовое тесто раскатать в пласт нарезать из него квадраты, положить на каждый по ложке начинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9226,'Свернуть по диагонали, защипать, запечь в прогретой духовке до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9227,'Порезать хлеб (лучше чуть черствый) на небольшие кусочки, зарумянить на листе в духовке до темно коричневого цвета, пересыпать  сухари в банку до половины объема, всыпать пару столовых ложек сахарного песка, залить полулитровой банкой кипятка, дать постоять до набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9227,'Закваску охладить, но она должна оставаться теплой, положить дрожжи, хорошо перемешать, завязать марлей горлышко, оставить в тепле на пару-тройку суток для полного сбраживания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9233,'Сварить и остудить рис, порезать сладкий перец красного цвета и ананас на кубики, лук порубить вместе с чесноком и острым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Перемешать творог со сметаной, манной крупой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9227,'Всыпать в трехлитровку сухарей (хватит 3 горсти), 4 полные столовые ложки сахарного песка, долить банку почти до верха (на два пальца ниже) кипятком, перемешать, дать остыть, в теплую смесь положить закваску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9227,'Состав в банке хорошо перемешать, оставить натуральный хлебный квас в тепле для брожения на пару дней, процедить жидкость сквозь сложенную в несколько слоев марлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9227,'По вкусу готовый квас можно еще немного подсластить, всыпать горсточку изюма, дать постоять (минимум сутки) в тепле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9228,'Чуть подогреть смесь молока и воды, всыпать сахар с дрожжами, перемешать, дать смеси постоять, вбить яйцо, влить растопленное масло, подсолить, добавить ванилин, взбить с помощью венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9228,'Вымешивая, по частям всыпать всю просеянную муку, переложить тесто на стол, присыпанный мукой и окончательно вымесить до мягкого состояния, в процессе замеса периодически подсыпать муку (ориентировочно уйдет около 2 стаканов), полученный колобок прикрыть тканью и на полтора часа оставить в покое.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9228,'Если увеличение объема произойдет раньше, то можно приступать к приготовлению пончиков.  Раскатать созревшее тесто в сантиметровый пласт, вырезать кружочки диаметром меньше стандартного стакана, дать им подойти и увеличить объем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9228,'Сильно разогреть в очень глубокой сковороде или сотейнике достаточное количество масла, чтобы пончики не тонули, зажарить равномерно с каждой стороны, разложить на сложенные в несколько раз бумажные полотенца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9228,'В каждом вкусном пончике можно посередине сделать горизонтальный надрез и заполнить начинкой, а можно оставить целыми и просто присыпать через ситечко сахарной пудрой, перемешанной с небольшим количеством корицы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9229,'Подготовить баклажаны, обрезать хвостики, очистить кожицу, порезать достаточно тонко на пластинки, насыпать в плоскую тарелку муку, слегка подсолить, перемешать, обвалять каждый кусочек, обжарить на гриле с двух сторон, промокнуть от излишков масла салфеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9229,'Для пармиджана идеально подойдет соус Наполи. Обжарить для его приготовления нашинкованный лук, помидоры, мелко порезанный чеснок, уварить на медленном огне до уменьшения объема соуса наполовину, подсолить, добавить растертый базилик и сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9229,'Переложить обжаренные баклажаны послойно в прямоугольную форму, после укладки каждого поливать его соусом, верх закуски присыпать натертыми моцареллой и пармезаном, убрать пармиджана из баклажан на треть часа в духовой шкаф с температурой чуть выше 160 градусов, присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9230,'Все ингредиенты перемешать в достаточно глубокой миске, постепенно, постоянно мешая, всыпать всю муку, вымесить тесто в эластичную и достаточно мягкую массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9230,'Полученное тесто не должно при работе прилипать к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9231,'Пластинки желатина залить сливками с добавлением молока, дать постоять минут 10 и разбухнуть, прогреть, помешивая до полного его растворения, разлить по 2 стаканам, но не поровну, в один больше, чем в другой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9231,'Мелко поломать шоколад, перемешать с меньшей частью желатинового раствора до полного его растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9231,'Большую смешать со сгущенкой, разлить по широким стаканам, заполнить чуть менее, чем на половину, поставить на треть часа застывать в холодильник, для получения более декоративного вида панна-котты с шоколадом и сгущенкой, стакан можно зафиксировать в слегка наклонном положении.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9231,'После схватывания молочной смеси, уложить поверх нее шоколадную, дать еще раз застыть в наклонном положении и украсить шоколадной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9232,'Поломать почти весь шоколад (примерно 65 граммов) на кусочки, дать растаять на водяной бане. Нанести тонкий слой шоколада, используя кулинарную кисть, на дно и стенки формочек из силикона, отправить на пару минут в морозилку, нанести еще один слой дать ему застыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9232,'Залить творог сгущенкой, добавить сливочное масло, взбить в однородную массу, но не слишком густую, разложить по формочкам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9232,'Расплавить остатки шоколада, нанести его поверх творожной массы, глазированные сырки поставить минут на 20 (можно и больше) в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9233,'Прогреть в глубокой сковороде, идеально в воке, масло кунжута, помешивая, обжарить пару минут лук, перец и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9233,'Всыпать горошек, добавить кубики ананаса, обжарить 5 минут, перец должен стать чуть хрустящим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9233,'Положить холодный рис, табаско и соевый соус, рис с ананасом и овощами тщательно размешать, присыпать измельченными перьями зеленого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9234,'Включить на разогрев до 180 градусов духовой шкаф. Обжаренные орехи, очистить от шелухи, измельчить любым способом, растопить шоколад вместе с маслом в микроволновке или на водяной бане, дать смеси остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9234,'Всыпать через ситечко порошок какао, сахарный песок и ванильный сахар, взбить с помощью миксера. Вбить по одному яйца, после каждого добавления смесь необходимо немного взбивать. Частями ввести просеянную муку и орехи, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9234,'Залить тесто в силиконовую форму поставить брауни на полчаса в уже достаточно прогретый духовой шкаф, минут за 10 до окончания проверить, если на поверхности уже есть корочка, то десерт можно считать готовым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9234,'Перед подачей брауни из горького шоколада оформить ягодами, сахарной пудрой с какао или жидким шоколадом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9235,'Замесить на желтках с добавлением сахара тесто, оставить стоять минут 30, затем раскатать толщиной не более 1,5 сантиметров, порезать пласт полосками по 6 сантиметров шириной, завернуть каждую спирально.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9235,'Обжарить фигурный хворост до готовности в хорошо разогретом топленом масле, разложить на бумажном полотенце, переложить на блюдо, присыпать равномерно сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9236,'Поместить все ингредиенты в чашу блендера, смешать, переложить массу в разъемную форму, выпекать основу торта примерно четверть часа в прогретой до 180 градусов духовке, дать ей остыть, за это время приготовить начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9236,'Взбить до получения воздушной массы рикотту с сахаром и сыром, добавить по одному все яйца, приправить ванилином, перемешать, поделить на 3 части. Первую смешать с какао и шоколадом, вторую – с пюре из выбранных ягод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9236,'Заполнить шоколадным тестом дно формы, запекать треть часа, сверху положить ягодное тесто, вернуть в духовку на 20 минут, затем выложить остатки теста, запекать неаполитанский сырный торт еще около 35 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9236,'Открыть слегка дверцу духовки, выключить нагрев, дать постоять полчаса. Вынуть десерт из духовки, дать окончательно остыть, убрать часов на 7 в холодильник и можно подавать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'Подготовить куриную тушку, удалить все внутренности и торчащие остатки перьев, промыть, разделить ее на 2 части, отделить окорочка, сложить в объемную кастрюлю, залить водой, поставить варить на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'После закипания нагрев уменьшить до минимального, чтобы кипения практически не было видно, удалить образовавшуюся пену, прикрыть крышкой с отверстием, варить минимум 4 часа, периодически снимать с поверхности жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'Положить в наваристый бульон морковку и лук, варить холодец из курицы еще полчаса, мясо и морковку вынуть, выдавить в бульон чеснок, бросить горошки душистого и черного перцев вместе с листиками лавра, подсолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'Проварить все вместе полчаса, за это время разобрать мясо от костей, порезать его на кусочки, яйца почистить и разрезать на четвертинки или половинки, морковку - на кружочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'Аккуратно залить процеженным бульоном выбранные формы до половины объема, дать чуть подзастыть, разложить волокна мяса, веточки кинзы, морковку, яйца, долить осторожно бульоном, не доходя до краев по сантиметру, дать хорошо застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9237,'Приступить к дегустации можно будет часов через 7, а лучше через 12, когда консистенция станет достаточно плотной, подавать холодец из курицы с домашним хреном и ядреной горчицей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9238,'Добавить к творогу сахар, растереть в однородную массу, добавить оставшиеся ингредиенты, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9238,'Притрусить стол мукой, скатать цилиндр, разрезать на ровные 6 частей, сплюснуть до получения «шайбочки», обвалять сырники с маком в муке, обжарить в масле, подать горячими со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Отдельно перемешать несладкий какао-порошок и красный пищевой краситель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9239,'Сахар и масло взбить до полного растворения сахара и побеления всей смеси. Вбить, взбивая по одному яйцу до образования маслянистой массы. Влить коньяк, всыпать по частям муку, добавить цедру одного лимона, перемешать на низкой скости миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9239,'Подготовить форму, смазать маслом, притрусить манкой, заполнить тестом, поверхность разровнять, лимонный кекс выпекать минут 40 при температуре не выше 180 градусов до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9240,'Сварить очищенный картофель, размять с маслом, яйцом, сыром и мукой в однородное пюре без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9240,'Пока варится картофель нашинковать кубиками лук, обжарить до прозрачного состояния, дать остыть, перемешать с рисом, фаршем, зеленью, яйцом, специями, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9240,'Заполнить картофельным пюре смазанные маслом формочки, сделать бортики, уложить сверху фарш, присыпать тефтели в картофельных корзиночках сыром, выпекать около 40 минут при температуре порядка 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9241,'Зерно промыть, залить водой, проварить на слабом огне около 5 часов, постоянно следить, чтобы вода полностью не выкипала, иначе ячмень пригорит.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9241,'Снять кастрюлю с плиты, дать чуть остыть, сцедить жидкость и вернуть ее в кастрюлю, добавить разогретый сахар, перемешать, проварить до полного его растворения и до сгущения смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9241,'Расстелить лист пергамента, вылить на него сироп для приготовления ячменной карамели, дать чуть застыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9241,'Смочить лезвия ножниц маслом, порезать его длинными полосами, свернуть каждую спиралью, дать полностью затвердеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9242,'Поломать плитку шоколада на небольшие кусочки, растопить, используя водяную баню или микроволновку. Сполоснуть сотейник холодной водой, залить молоко, нагреть его, перемешать с жидким шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9242,'Смешать порошок какао с сахарной пудрой, солью и просеянной мукой, взбить смесь с молоком. Добавить к ней взбитые отдельно яйца, перемешать, влить растопленное масло, шоколад и ром, тесто тщательно перемешать до состояния жидкой сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9242,'Сковороду для приготовления шоколадных блинчиков, слегка смазать маслом, хорошо разогреть, вылить небольшой половник теста, вращательным движениями распределить его равномерно по поверхности сковороды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9242,'Выпекать блины около полуминуты с одной стороны, а затем с другой до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9243,'Растопить кусочки темного шоколада с добавлением столовой ложки сливочного масла, перемешать в однородную массу, добавить яйца, вымесить. Всыпать ваниль, разрыхлитель, смешанный с просеянной мукой, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9243,'Раскрошить булку, смазать небольшим количеством масла дно формы, насыпать в нее равномерным слоем крошки, а на них разложить вплотную друг к другу разрезанные вдоль бананы, залить жидкой шоколадной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9243,'При желании верх бананов в шоколадной заливке можно присыпать дробленым орехом, стружкой кокоса или семечками подсолнуха. Отправить десерт минут на 20 в духовой шкаф с температурой порядка 180 градусов, дать слегка остыть, постараться порезать поперек кусочков банана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9244,'Разрезать слегка охлажденное филе вдоль, чуть не дорезая до конца, развернуть, разложить на пленке, аккуратно отбить с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9244,'Разложить по поверхности козий сыр, разровнять, присыпать измельченным тимьяном, плотно завернуть в трубочку и завернуть в пластинки тонко порезанного бекона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9244,'Дно и стенки формы промазать маслом, притрусить сухарями, выложить кружочками цукини и половинками черри, присолить, поперчить, побрызгать маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9244,'Разложить на овощную «подушку» куриные грудки в беконе, прикрыть несколькими веточками тимьяна, запекать в течение 45 минут при 180 градусах, подавать блюдо лучше горячим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Замесить тесто на молоке, согласно инструкции к хлебопечке, поделить его на две равные части. Раскатать каждую в пласт толщиной не больше 1 сантиметра, вырезать с помощью тарелки ровные круги. Наметить в середине с помощью меньшей тарелки круг для размещения начинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'С помощью миксера взбить в течение трех минут сливочное масло комнатной температуры с сахарным песком. Масса должна получиться воздушной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Для ее приготовления перемешать с фаршем обжаренные до золотистости кубики лука, прожарить все вместе до полной готовности мяса, за 5 минут до окончания положить в смесь измельченный чеснок и немного зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Для вязкости всыпать в начинку пару ложек муки и влить чуть воды, перемешать, дать остыть. переложить один из кругов на противень, выстеленный листом пергамента. По намеченному меньшему кругу выложить начинку, вокруг нее расположить тертый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Второй круг аккуратно уложить поверх начинки, аккуратно чуть обмять по намеченному кругу меньшего диаметра, место расположения начинки станет выпуклым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Сделать по краю круга острым ножом лепестки-насечки по всей его длине от края к центру примерно через 4 сантиметра. Каждый лепесток провернуть на 90 градусов и чуть раскрыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9245,'Смазать верх пирога «Подсолнух» с мясом и сыром разболтанным желтком, присыпать центральный круг (лепестки не трогать) маком. Пирог выпекать около 35 минут в прогретой чуть ниже 190 градусов духовке до появления приятного золотистого цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9246,'Включить духовку, прогреть чуть ниже 180 градусов, взбить масло с сахарным песком в воздушную массу, добавить яйца, тщательно перемешать, всыпать просеянную и перемешанную с разрыхлителем, мускатным орехом и солью муку, добавить молоко, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9246,'Заполнить им формочки до половины объема. Выпекать французские пончики минут 20. В блюдце перемешать сахар и корицу, осторожно вынуть пончики, окунуть верхушку каждого в масло, а затем в сахарную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9247,'Сварить, рассол со специями, остудить, положить подготовленный кусок мяса, кастрюлю прикрыть пленкой, оставить в холодильнике часов на 5, а лучше дать переночевать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9247,'Вынуть мясо, обтереть, обмазать специями с солью и перцем, сделать проколы, заполнить зубчиками чеснока. Запаковать для выпекания домашнюю буженину в рукав, сделать несколько проколов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9247,'Поместить на час в уже прогретую примерно до 190 градусов духовку, обрезать верх у рукава дать буженине чуть подрумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9248,'Нарезать батон на ломти, вырезать мякоть, корочку оставить нетронутой, в глубокую миску вбить яйца, перемешать с сырной стружкой и кубиками колбасы, подсолить, можно и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9248,'Разогреть в сковороде масло, обжарить корочки с одной стороны, перевернуть, заполнить яичной массой, жарить бутерброды «Окошки» под крышкой пока начинка не схватится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9249,'Противень застелить фольгой. Полить её лимонным соком, присыпать рубленой петрушкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9249,'Выложить рыбное филе, накрыть вторым листом фольги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9249,'Печь в течение 15 – 20 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Готовое шоколадное печенье измельчить в чаше блендера. Растопить сливочное масло, добавить в массу и перемешать в течение нескольких секунд.','https:https://st.vkuso.ru/data/cache/thumb/ce/47b77b6db4334ce_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Выстелить форму бумагой для выпекания, высыпать влажную крошку, хорошо утрамбовать.','https:https://st.vkuso.ru/data/cache/thumb/15/556a0b36fb4db15_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Для приготовления начинки перемешать творог с сахарным песком, масса должна быть однородной.','https:https://st.vkuso.ru/data/cache/thumb/db/c28caacd22094db_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Вбить сырые куриные яйца по одному. Всыпать кукурузный крахмал, влить несколько капель ванильного экстракта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Еще раз перемешать всё с помощью блендера. Масса должна быть гладкой и без комочков.','https:https://st.vkuso.ru/data/cache/thumb/75/91e6f7dbfd96a75_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Отделить треть теста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Отдельно растопить черный шоколад, добавить его и растворимый кофе в большую часть творожной массы, перемешать до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/40/50dae6d5f3d0740_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Выложить шоколадную смесь на корж.','https:https://st.vkuso.ru/data/cache/thumb/69/ed481e8af087b69_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Сверху – оставшуюся творожную массу белого цвета.','https:https://st.vkuso.ru/data/cache/thumb/f6/b378b7734382bf6_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9250,'Печь в духовом шкафу при температуре 180 градусов в течение часа. На нижнюю полку поставить небольшую емкость с водой. Готовый сырник на ночь убрать в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Просеять пшеничную муку, соль и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Убрать изделия на два часа в морозильную камеру.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Вбить по одному сырые куриные яйца. Перемешать, добавить смесь красителя и какао, ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Треть полученной мучной смеси всыпать в миксер, хорошо взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Всыпать еще треть муки и влить пахту, затем добавить оставшуюся муку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Взбить массу до однородности, добавить пищевую соду, погашенную уксусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Разделить тесто пополам, выпечь два коржа в двух формах, время приготовления – по полчаса, остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9251,'Приготовить глазурь, промазать ею коржи, полить сверху и с боков.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9252,'Для начинки порезать сало и печень на мелкие кубики, обжарить до готовности, чернослив хорошо вымыть, высушить, мелко порезать, лук мелко нашинковать кубиками, замочить раскрошенный хлеб во взболтанном яйце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9252,'Объединить все и хорошо перемешать, всыпать в начинку измельченную цедру лимона (половину чайной ложки), еще раз перемешать. Чуть подмороженное филе разделить вдоль на три пластины и аккуратно отбить, присыпать корицей и перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9252,'На каждый пласт мяса уложить начинку, свернуть с небольшим нажимом в рулет, обмотать толстыми нитками или скрепить зубочистками (перед едой удалить) переложить на противень с бульоном. Блюдо запечь в течение часа в прогретой до 180 градусов духовке. При желании можно куриные рулеты сначала обжарить со всех сторон до появления румянца, а уж потом довести до готовности в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9252,'Приготовить из спассерованной на масле муки бульона или молока с добавлением сыра соус, варить его, помешивая до полного растворения сыра. Достать рулеты с печенью и черносливом, переложить на блюдо, залить соусом, присыпать лимонной цедрой, в качестве гарнира подойдет отварной рис и овощной салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Репчатый лук мелко нарезать и немного обжарить на кукурузном масле до прозрачности.','https:https://st.vkuso.ru/data/cache/thumb/f3/5f617d8158164f3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Добавить к нему говяжий фарш, прогревать в течение семи минут.','https:https://st.vkuso.ru/data/cache/thumb/eb/459950010ba06eb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'В обжарку положить измельченные помидоры, с которых снята кожица, нарезанную зелень петрушки.','https:https://st.vkuso.ru/data/cache/thumb/4b/6b04a6b7d6b714b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Фарш с овощами поперчить и посолить по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/d7/1cf14a0da116ad7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Натереть сыр «Гауда» на крупной терке.','https:https://st.vkuso.ru/data/cache/thumb/57/5ec0791320fca57_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Разогреть сухую сковороду, выложить тортилью, посыпать её тертым сыром, выложить мясную начинку, снова покрыть слоем сыра.','https:https://st.vkuso.ru/data/cache/thumb/d8/2c86784694e6fd8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9253,'Накрыть начинку второй тортильей, перевернуть. Лепешки с начинкой должны стать хрустящими и румяными. При подаче нарезать выпечку треугольниками.','https:https://st.vkuso.ru/data/cache/thumb/a0/d6c2800341871a0_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9254,'Сливки влить в сотейник, поставить на огонь, довести до кипения. Как только появятся пузырьки – емкость снять с огня.','https:https://st.vkuso.ru/data/cache/thumb/f7/db1c5ecd5f637f7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9254,'Перемешать желтки с сахарной пудрой и ванилью, взбить массу венчиком до однородной консистенции.','https:https://st.vkuso.ru/data/cache/thumb/1c/2eb45c2ac1cd41c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9254,'Влить немного горячих сливок, быстро перемешать.','https:https://st.vkuso.ru/data/cache/thumb/93/ff5a987634c0c93_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9254,'Влить остальные сливки, еще раз перемешать. Поставить сотейник на небольшой огонь, довести массу до кипения, продолжать помешивать до загустения.','https:https://st.vkuso.ru/data/cache/thumb/92/22564ac03a33692_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9254,'Вылить массу в емкость, поставить в морозильную камеру на три-четыре часа. Перемешивать мороженое через каждые 15 – 20 минут в течение трех-четырех часов.','https:https://st.vkuso.ru/data/cache/thumb/c1/cbe63bf9cd460c1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Для заправки смешать оливковое масло и масло виноградных косточек, добавить белый винный уксус, давленый чеснок, измельченный базилик.','https:https://st.vkuso.ru/data/cache/thumb/c6/724a2db393d28c6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Острый зеленый перец очистить от семечек, мелко нарезать и добавить в соус. Оставить смесь на некоторое время для настаивания.','https:https://st.vkuso.ru/data/cache/thumb/12/6675e9fbe1f0912_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Нарезать кубиками помидоры.','https:https://st.vkuso.ru/data/cache/thumb/db/0cb7287065162db_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Также нарезать сладкий болгарский перец, накрошить зелень петрушки и красный репчатый лук.','https:https://st.vkuso.ru/data/cache/thumb/b7/5352455c963ecb7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Овощи аккуратно перемешать с помощью двух вилок. Соль и перец молотый – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/ad/af8dc8075dbdead_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Полить масляным соусом и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/1f/eed2f90cda79f1f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9255,'Перед подачей добавить в блюдо нарезанные консервированные оливки, сбрызнуть кушанье соком лайма.','https:https://st.vkuso.ru/data/cache/thumb/df/2c22a8b4a1e56df_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Репчатый лук нарезать полукольцами.','https:https://st.vkuso.ru/data/cache/thumb/e6/e24a9f2592540e6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Баранину на косточке залить водой, варить бульон в течение 40 минут на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/9d/f628df31b2bcf9d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Лук выложить на сковороду с разогретым растительным маслом. Подлить томатную пасту, все вместе обжарить.','https:https://st.vkuso.ru/data/cache/thumb/a6/347b682f578eca6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Из готового бараньего бульона вынуть мясо, а в жидкость добавить обжарку, потомить блюдо на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Всыпать рис, влить соусы «Ткемали» и острую «Аджику».','https:https://st.vkuso.ru/data/cache/thumb/e2/9239dfe261a0fe2_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'При готовности риса вернуть в кастрюлю мясо.','https:https://st.vkuso.ru/data/cache/thumb/c0/0184c86eb1687c0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Положить приправу «Хмели-сунели», соль, сахар и молотый перец – по вкусу. Отдельно нарезать кубиками кисловатые помидоры, порубить зелень кинзы и чеснок.','https:https://st.vkuso.ru/data/cache/thumb/05/171e69abf399a05_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9256,'Все ингредиенты добавить в кушанье, довести харчо до кипения, снять с огня. Подать блюдо в тарелках или в горшочках, посыпать натертыми грецкими орехами.','https:https://st.vkuso.ru/data/cache/thumb/d4/21a30ae9bacb4d4_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Налить в небольшую емкость молоко, нагреть, положить кусочки горького шоколада.','https:https://st.vkuso.ru/data/cache/thumb/8b/9644a01866c078b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Прогреть смесь до растворения шоколада.','https:https://st.vkuso.ru/data/cache/thumb/d0/a6bf0812e912dd0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Положить нарезанный кусочками зефир, он должен немного размягчиться.','https:https://st.vkuso.ru/data/cache/thumb/1b/eedc8d891b2911b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Шоколадно-зефирную массу переложить в блендер, взбить до однородности.','https:https://st.vkuso.ru/data/cache/thumb/2c/28840e0140ab12c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Перелить массу в чашку, зефир должен подняться на поверхность.','https:https://st.vkuso.ru/data/cache/thumb/33/56f30e1f63e6833_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9257,'Украсить напиток тертым шоколадом.','https:https://st.vkuso.ru/data/cache/thumb/8e/178de7d4e3aa68e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9258,'Сварить до готовности спагетти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9258,'Обжарить на масле кусочки грибов и бекона. Миксером взбить желтки, влить сливки, добавить сыр, чуть присолить, поперчить, размешать, соединить с грибами и беконом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9258,'При слабом нагреве и непрерывном быстром помешивании довести смесь до кипения (осторожно, не увеличивая огонь, чтобы желтки «не схватились»).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9258,'Сцедить спагетти, влить соус, перемешать, чтобы макароны хорошо пропитались соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9258,'Подавать паста карбонара с шампиньонами и беконом на большой подогретой тарелке, верх присыпать сырной стружкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9259,'Персики и манго нарезать на кусочки, дольками или кубиками.','https:https://st.vkuso.ru/data/cache/thumb/9f/42703e050e6779f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9259,'Растопить на сковороде натуральный мёд, подлить оливковое масло, обжарить персики до карамелизации, по пять минут с каждой стороны. При готовности фрукта добавить манго, перемешать, тут же снять с огня.','https:https://st.vkuso.ru/data/cache/thumb/93/3f48f9a52aaa293_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9259,'Для заправки в сотейнике смешать воду с цедрой лимона и коричневым сахаром. Емкость поставить на плиту, варить до растворения сахара и начала кипения.','https:https://st.vkuso.ru/data/cache/thumb/fa/e6989ac1b5d92fa_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9259,'Влить лимонный сок, варить две минуты, сироп начнет густеть.','https:https://st.vkuso.ru/data/cache/thumb/55/7d841bff817b055_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9259,'Перемешать манго и персики с зеленью, добавить накрошенный голубой сыр, полить карамельной заправкой.','https:https://st.vkuso.ru/data/cache/thumb/c5/9257e0309b281c5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Смазать форму для выпекания сливочным маслом и присыпать мукой.','https:https://st.vkuso.ru/data/cache/thumb/cb/b906c5ceebad7cb_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Перемешать просеянную пшеничную муку, сахарный песок, разрыхлитель, соль и пищевую соду.','https:https://st.vkuso.ru/data/cache/thumb/91/64ec489196fa591_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Очистить бананы.','https:https://st.vkuso.ru/data/cache/thumb/e8/b5acb137ed983e8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Сделать из мякоти пюре.','https:https://st.vkuso.ru/data/cache/thumb/7c/a821a5d6ef74c7c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'В отдельной емкости взбить сырые куриные яйца. Добавить пюре, ванилин и растительное масло без запаха. Массу взбить до однородного состояния, смешать с сухой смесью. Шоколадные капли добавить в последнюю очередь.','https:https://st.vkuso.ru/data/cache/thumb/b7/0dd5c3f9ad3c1b7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Влить в форму и печь в заранее разогретом духовом шкафу в течение 50 минут.','https:https://st.vkuso.ru/data/cache/thumb/d5/0b7b2e9bcd746d5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Для крема взбить вместе сливочно-творожный сыр и сахарную пудру.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Постепенно, ложками, добавить молоко, несколько капель ванильной эссенции.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9260,'Вылить массу на пирог, посыпать рублеными миндальными орехами, подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/ea/b6cc7c82a2f45ea_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Твердый сыр натереть на мелкой терке, добавить по вкусу соль и молотый перец, сырые куриные яйца, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Чеснок очистить и измельчить. Положить его в тесто, добавить муку, масса должна быть плотной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Сформовать шарики.','https:https://st.vkuso.ru/data/cache/thumb/79/ee1243ba0ec0979_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Обвалять их в муке.','https:https://st.vkuso.ru/data/cache/thumb/80/82978515bcd5480_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Выложить на раскаленную сковороду, жарить во фритюре из растительного масла с двух сторон до образования золотистой корочки.','https:https://st.vkuso.ru/data/cache/thumb/af/21957923fdb7baf_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9261,'Готовые изделия выложить на бумажное полотенце, чтобы впитался лишний жир.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Вымыть куриное филе, нарезать крупными кусочками или кубиками со стороной в два-три сантиметра. Посыпать мясо солью, смесью итальянских трав, перемешать и оставить на 10 – 15 минут для пропитывания.','https:https://st.vkuso.ru/data/cache/thumb/df/78dfa92593e9bdf_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Обжарить филе на растительном масле до румяной корочки.','https:https://st.vkuso.ru/data/cache/thumb/50/f6e11f61760a250_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Клубни картофеля вымыть, залить водой, довести до кипения, через 10 минут выключить, воду слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Остывший клубнеплод очистить от кожуры и нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Обжаренное куриное филе и картофель высыпать в форму из силикона, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/77/5dc7b93603be177_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Взбить яйца со сметаной, вымытым и нарубленным зеленым луком, солью. Смесью залить картофельно-куриную массу.','https:https://st.vkuso.ru/data/cache/thumb/f7/b7f0180a5fcc4f7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9262,'Поставить в заранее разогретую духовку, печь до появления коричневато-золотистой корочки. Запеканку вынуть, остудить, нарезать и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Несколько зубчиков чеснока порубить.','https:https://st.vkuso.ru/data/cache/thumb/49/f814e51b241c749_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Переложить в ступку, добавить цедру лимона и ложку ароматных сушеных трав.','https:https://st.vkuso.ru/data/cache/thumb/da/0c74b11d50a73da_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Смесь растереть в пасту. Если ступки в хозяйстве нет, то массу можно растереть ложкой в небольшой емкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Добавить сок лимона, оливковое масло.','https:https://st.vkuso.ru/data/cache/thumb/b7/c501d56e44ecdb7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Заправить куриное филе полученным маринадом, поставить в холодильник на час или полтора, два-три раза перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'В йогурт с нейтральным вкусом добавить немного оливкового масла, рубленую мяту.','https:https://st.vkuso.ru/data/cache/thumb/c6/8ac8b53b2b854c6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Натереть свежий огурец на крупной терке, кусочки не должны быть длинными. Порубить зубчик чеснока.','https:https://st.vkuso.ru/data/cache/thumb/8c/59a00e86924fb8c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Отжать огуречную массу от избытка влаги, добавить в йогурт.','https:https://st.vkuso.ru/data/cache/thumb/cb/b1d6110130d19cb_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Маринованную курицу можно приготовить на гриле. Перед началом обжаривания филе нужно обсушить салфеткой, чтобы образовалась румяная корочка.','https:https://st.vkuso.ru/data/cache/thumb/42/cb38035f8d17842_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9263,'Готовое мясо крупно порубить, выложить в булочки или лепешки, полить готовым соусом, украсить нарезанным свежим огурцом.','https:https://st.vkuso.ru/data/cache/thumb/61/d87ef6a77d13f61_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Сосиски из говядины обжарить на гриле или на сковороде с растительным маслом.','https:https://st.vkuso.ru/data/cache/thumb/22/a563cf2858ab322_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Обжарить хлеб в тостере или на гриле с двух сторон, разрезать его на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'На заранее разогретом растительном масле обжарить соломку репчатого лука в течение одной-двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Влить новую порцию воды, крупу проварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Мелкий картофель отварить, нарезать, жарить в течение двух-трех минут до золотистой корочки, соль и перец – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/5b/aba6edfbaf7d25b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Приготовить яичницу-болтунью из яиц, сметаны, молотого перца и соли. Хорошо перемешать с помощью венчика.','https:https://st.vkuso.ru/data/cache/thumb/00/f7764d8296b2700_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Растопить на сковороде с антипригарным покрытием сливочное масло, налить яичную смесь.','https:https://st.vkuso.ru/data/cache/thumb/6b/c33dd147717fe6b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Когда масса начнет схватываться – помешивать яйца силиконовой лопаткой.','https:https://st.vkuso.ru/data/cache/thumb/a8/7135376b709dea8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Должны образоваться небольшие комочки, жарить до готовности.','https:https://st.vkuso.ru/data/cache/thumb/c0/81b20a62f4eabc0_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9264,'Для подачи выложить на тарелку омлет, обжаренный картофель, колбаски, разрезанный тост. Посыпать кушанье рубленой зеленью и украсить помидорами, нарезанными дольками.','https:https://st.vkuso.ru/data/cache/thumb/ba/2d2d075c06e6eba_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Готовое тесто для пиццы размять.','https:https://st.vkuso.ru/data/cache/thumb/54/b44bbe28099e454_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Сформовать длинную колбасу и разрезать её на части.','https:https://st.vkuso.ru/data/cache/thumb/7c/236e6ced49eb57c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Раскатать лепешки на доске, присыпанной мукой. На каждый кусочек намазать соус «Маринара», посыпать его тертым сыром «Чеддер» или «Моцарелла», выложить кружочки колбасы «Пепперони».','https:https://st.vkuso.ru/data/cache/thumb/b6/854e08eeb64a5b6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Края лепешки смочить, плотно скрепить, чтобы начинка была внутри.','https:https://st.vkuso.ru/data/cache/thumb/05/75d06f225366205_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Готовые булочки выложить на противень.','https:https://st.vkuso.ru/data/cache/thumb/aa/d99a6694d9f71aa_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'В большой кастрюле вскипятить воду, всыпать в неё соду и сахарный песок. Жидкость должна активно бурлить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Булочки опускать в кастрюлю по четыре штуки за один прием, время варки – полминуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Изделия вынуть шумовкой, вернуть на противень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9265,'Каждую булочку смазать растопленным сливочным маслом, посыпать крупной солью. Печь при температуре 175 градусов до образования золотисто-коричневой корочки.','https:https://st.vkuso.ru/data/cache/thumb/5c/23b156e99b4545c_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Сварить сироп из воды и сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Очень тонко нарезать яблоки, толщина долек – два-три миллиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Опустить измельченные фрукты на час в сироп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Дольки вынуть, выложить на коврик из силикона или решетку из духового шкафа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Посыпать сахарной пудрой, печь в течение двух часов при температуре 100 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Готовые фруктовые чипсы полностью остудить, их можно хранить при комнатной температуре в плотно закрывающейся емкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Для печенья перемешать в глубокой миске пшеничную муку, сахарную пудру, какао-порошок, разрыхлитель и соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Добавить сырые куриные желтки, кусочки охлажденного сливочного масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Тесто должно быть мягким и эластичным.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Сформовать шар, завернуть его в пищевую пленку и поставить на час в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Охлажденное тесто раскатать в пласт в полсантиметра толщиной, вырезать кружки, наколоть их вилкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Выложить заготовки на лист пергамента или на силиконовый коврик.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Печь в заранее разогретой до 180 градусов духовке в течение 10 минут. Остудить полностью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Удалить из яблок сердцевину с косточками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Выложить их в глубокую форму, присыпать корицей и сахаром, печь при температуре 180 градусов до мягкости.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Остудить, чайной ложкой собрать мякоть.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Полученное пюре взбить вместе с сырым белком в объемную, пышную массу.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Отдельно нагреть воду с сахаром до температуры 80 градусов.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Отдельно смешать сахар с агар-агаром, прогреть до нужной температуры и ввести его в сироп тонкой струйкой, помешивать венчиком.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Нагреть сироп до 110 градусов, влить его в яблочно-белковую массу, скорость взбивания – выше средней.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Масса должна стать плотной и пышной.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Полученную зефирную смесь отсадить с помощью кулинарного мешка поверх печенья в виде башенки.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Для глазури смешать масло из виноградных косточек или фундука с теплым растопленным горьким шоколадом.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'Пирожные из морозилки опустить вниз зефирной башенкой в растопленный шоколад, поднять, подождать, пока шоколад стечет, перевернуть и поставить на стол.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9266,'На липкую неостывшую глазурь приклеить по яблочному чипсу.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9267,'Измельчить блендером все ингредиенты для маринада в однородную смесь, мясо обмыть, зачистить, обсушить, втереть с усилием маринадную смесь, завязать кусок в пакет, положить в глубокую емкость и убрать в холодильник часов на 12, но можно и больше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9267,'Достать промаринованный кусок, ополоснуть, обсушить, переложить в подходящую по размеру форму, покрыть глазурью, отправить в прогретую до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9267,'Примерно через полчаса еще раз обмазать глазурью и через 10 минут снизить температуру на 40 градусов, запекать еще около часа до тех пор, пока при прокалывании не будет выделяться прозрачный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9267,'Переложить баранью ногу в гранатовом маринаде на широкое блюдо, дать «дозреть» еще минут 20, подать с соусом из гранатовой мелассы и гратеном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9268,'Всыпать в сгущенку стружку кокоса, тщательно перемешать, сформовать небольшие прямоугольные батончики, разложить на досочку, застеленную пергаментом, убрать на треть часа в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9268,'Шоколад поломать на кусочки и растопить удобным способом (водяная баня, микроволновка), окунуть в него, используя пару вилок, застывшие кусочки конфет «Баунти», разложить на решетке до полного остывания шоколадной оболочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9269,'Сварить говядину (можно даже чуть переварить, пусть будет очень мягкой), нарезать на средние кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9269,'Разрезать «крутые» яйца пополам, а затем на полукольца. Порезать маленькие луковички, на тонкие полукольца, замариновать на 4 часа в воде с уксусом (1:1), с небольшим количеством сахара и гвоздикой, процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9269,'Нарезать на дольки маринованные грибы, сыр – небольшими квадратиками. Объединить все ингредиенты, подсолить, сдобрить салат «Купеческий»  с говядиной и маринованным луком  майонезом, аккуратно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9270,'Натереть лук на терке или измельчить блендером, обжарить в оливковом масле, через пару минут добавить порубленный чеснок, орегано и томатную пасту, тушить все вместе 10-11 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9270,'Отбить мясо куриных грудок, присолить, окунуть в разболтанные яйца, обвалять в сухарях, обжарить каждую сторону минуты по 3-4.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9270,'Сложить мясо в керамическую форму, залить томатно-луковым соусом, присыпать куриную грудку измельченным твердым сыром, запечь треть часа в заранее прогретой до 200 градусов духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9271,'В кастрюлю с кипящей водой положить масло, чуть присолить, всыпать, постоянно мешая небольшими порциями муку, довести до однородности, тесто переложить в миску, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9271,'Втереть друг за другом пару яиц, должна получиться однородная масса. Заварное тесто для эклеров разложить небольшими порциями на расстоянии 5 сантиметров друг от друга на выстеленный пергаментом противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9271,'Выпекать около четверти часа при 200 градусах, уменьшить температуру до 120 и печь еще столько же, дверцу духовки открывать нельзя – тесто «упадет» и вместо воздушных эклеров получатся палочки из заварного теста. Готовые эклеры заполнить любой выбранной начинкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Нагреть духовку до 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Разложить тертый на средней терке пармезан на четыре горки на специальной бумаге или силиконовом коврике на некотором расстоянии друг от друга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Поставить противень минут на десять в духовку, сыр должен стать коричневым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Несколько минут остужать, чтобы он не распадался и стал эластичным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Осторожно переложить на формочки (мисочки, маленькие салатники или стеклянные стаканы), загнуть края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9272,'Позволить съедобным хрустящим салатницам из пармезана полностью остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Залить кипятком какао-порошок, размешать до однородности. Отставить в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Сахар и масло положить в ковш, поставить на плиту. Варить, перемешивая, до растворения масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Для приготовления первого слоя включить прогреваться до 160 градусов духовку, на водяной бане растворить помешивая в однородную массу шоколад, масло и эспрессо, дать чуть остыть, добавить взбитые желтки и очень быстро перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Постепенно ввести в массу взбитые в крепкую пену с щепоткой соли белки. Форму промазать маслом, застелить пергаментом, заполнить полученным тестом, поместить минут на 18-20 на среднюю полочку в духовке, дать полностью остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Для второго слоя заварить порошок какао кипятком, растопить без добавок молочный шоколад, дать ему минут 5 остыть. Взбить до сохранения формы сахар со сливками, соединить шоколад и заваренное какао, перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Ввести в эту смесь за 3 раза воздушные сливки, осторожно, чтобы сливки не успели опасть, перемешать в однородную массу. Поместить этот крем сверху уже хорошо застывшего первого слоя, убрать на четверть часа в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Для приготовления третьего слоя перемешать воду с желатином, нагреть треть сливок (не кипятить!), смешать с желатином, перемешать до образования однородной жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'В миску сложить поломанный шоколад, залить нагретыми сливками, дать постоять полминуты, перемешать до полного растопления шоколада и образования однородной массы, дать ей остыть, оставшуюся треть сливок перемешать с основной массой, добавить все остальные, вымесить аккуратно до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9273,'Залить полученный третий слой для торта-мусса из шоколада на уже застывшие два, разровнять, убрать опять в холодильник уже на 2 часа, а идеально – на ночь. Извлечь из формы готовый десерт, оформить шоколадной стружкой и ягодами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9274,'Отварить рис по инструкции на коробке, подготовить филе и порезать на кубики небольшого размера. Покрошить зеленый лук, грибы, моцареллу и болгарский перец нашинковать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9274,'Пересыпать все в миску (кроме лука и перца), влить сливки, добавить крахмал, яйца, приправить раздавленным чесноком, перцем чили и черным, подсолить, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9274,'Обжарить на предварительно сильно разогретом масле в сковороде в процессе обжарки котлет с двух сторон огонь убавить до среднего и закрыть крышкой, подать котлетки из куриной грудки горячими с рисом, присыпанным зеленью лука и сладким перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9275,'Для приготовления десерта заранее достать масло и яйца из холодильника. Включить духовку и дать прогреться ей примерно до 180 градусов. Взбить в однородную массу яйца и мелкозернистый сахар, частями подсыпать муку, вымесить до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9275,'Ввести в смесь уже мягкое масло и жидкий мед, взбить еще раз до однородного теста. На подготовленный и смазанный маслом противень налить слой теста, выпекать минут 12-15, следить, чтобы края пласта сильно не подсохли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9275,'Готовую основу достать, дать принять комнатную температуру, промазать сливками (предварительно их взбить), уложить поверх кусочки спелого банана, с легким нажимом свернуть в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9275,'Полить верх бананового рулетика сахарным сиропом, припудрить и присыпать шоколадной стружкой. Можно оформить разноцветными цукатами или сезонными фруктами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Положить в чашу миксера кубики масла, вбить яйцо, всыпать сахар, взбить около пары-тройки минут в однородно-пышную массу. Добавить специи, порошок какао, имбирь и через ситечко муку, смешать тесто миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Вынуть тесто, обернуть пленкой, отправить дойти на полчаса в холодильник, достать, разрезать на две ровные части, одну вернуть в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Расстелить достаточный по площади лист пергамента, положить порцию теста, расплющить рукой, прикрыть другим листом, раскатать примерно в 5 миллиметровый пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Убрать бумагу, вырезать мишек с помощью формочки, положить на грудь каждому по орешку и «обхватить» его лапками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Переложить печенье «Мишки с орешками» на противень, прикрытый бумагой для выпечки, выпекать в уже нагретой чуть выше 175 градусов духовке около 10 минут или чуть больше, если мишки будут толще 5 мм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9276,'Пока готовится первая партия печенья, проделать всю операцию со второй частью теста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Порубить лук и натереть морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Переложить смесь в посуду, взбить миксером, пока смесь не станет комнатной температуры, приблизительно минут пять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Вбивать по одному яйцу, после каждого взбивать. Насыпать ванильный сахар, какао, взбить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Просеять муку, соду, разрыхлитель и соль. Насыпать в шоколадно-яичную смесь в три приема муку, чередовать ее со сметаной. То есть, добавлять часть муки и часть сметанки и так далее, закончить мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Разложить тесто по формочкам, смазанным маслом, заполнять на ¾.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Готовить в духовке минут 30, соблюдать температуру 180 градусов. Вынуть, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Приготовить крем: растопить на водяной бане шоколад.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Соединить сахарную пудру с какао-порошком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Взбить до однородности сливочный сыр и сливочное масло.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Насыпать сахарную пудру с какао, добавить шоколад, взбить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Положить крем в кондитерский мешочек или бумажный кулек для выпечки. Используя насадку, украсить остывшие кексы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9277,'Шоколадные капкейки с шоколадно-сливочным кремом можно посыпать шоколадной стружкой или любой другой присыпкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9278,'Почистить и отварить картофель. Сделать пюре, посыпать перцем, солью, вбить яйцо. Должна получиться крутая масса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9278,'Порезать сыр на одинаковые кусочки. Из пюре сформировать порционные шарики, приплюснуть, чтобы они приняли форму лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9278,'На каждую лепешку положить кусочек сыра, сформировать шарики. Сыр при этом должен оказаться внутри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9278,'Обвалять шарики в сухариках. Обернуть их полосочками бекона, закрепить зубочистками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9278,'Обжарить картофельные шарики с сыром и беконом во фритюре до золотистой корки. Положить на бумажное полотенце.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9279,'Мелко порезать курицу. Разморозить и хорошенько отжать шпинат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9279,'Сделать соус: растопить масло, насыпать муку, обжарить. Тоненькой струей налить молоко, положить мускатный орех, посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9279,'Положить в кокотницы курицу, сверху шпинат, вылить соус, посыпать сырком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9279,'Готовить жюльен с куриным филе и шпинатомв духовке, пока сыр не станет румяным, соблюдать температуру 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9280,'Крупно порезать сливу, косточки убрать. Поместить в кастрюльку с толстым дном. Насыпать сахар, добавить цедру и сок одного апельсина, бадьян.','https:https://st.vkuso.ru/data/cache/thumb/04/f7a15caa737f104_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9280,'Все довести до кипения, перемешать. Варить, пока получится консистенция негустого соуса, минут 30.','https:https://st.vkuso.ru/data/cache/thumb/6c/6db5a1bcee7876c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9280,'Разлить горячее повидло в стерилизованные горячие банки, закрыть крышками. Желательно поставить банку в небольшую емкость, чтобы повидло не разбрызгивалось.','https:https://st.vkuso.ru/data/cache/thumb/ef/9d99eb85577baef_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9280,'На полу или на полочке расстелить кухонное полотенце, сложенное пополам. Поставить на него банки, перевернутые вверх дном. Укутать их покрывалом или полотенцами, позволить им остыть. Когда банки остынут перевернуть в нормальное положение.','https:https://st.vkuso.ru/data/cache/thumb/a9/d0955339955ada9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9281,'Нагреть духовку до 230 градусов. Соединить яйца, соль, муку, налить молоко, перемешать. Не взбивать. Должно быть тесто, как на блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9281,'Налить по три ложечки тесто в формочки из силикона. Предварительно поставить формочки на противень. Не использовать железные формочки, так как к ним липнет тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9281,'Отправить формочки на пятнадцать минут в духовку. Снизить температуру до 200 градусов, готовить простые блинные булочки к завтраку минут 10.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9282,'Срезать с булочек верхушки, вынуть из середины мякоть, смазать дно и стенки жидким сливочным маслом, чуть присолить и поперчить. Включить на разогрев духовку (примерно до 180 градусов), заняться начинкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9282,'Наполнить булочки ветчиной. Вбить сверху по яйцу, сдобрить солью и черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9282,' Запекать Фаршированные булочки «Вкусный завтрак» минут 10, затем осторожно накрыть горячий противень двумя слоями фольги, отправить в духовку еще на треть часа, пока не «схватится» белок яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Добавить измельченный чеснок, прогреть все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Приготовить заправку: соединить в емкости горчицу, оливковое масло, уксус. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/88/cc6326bcf4e9c88_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Несколько столовых ложек заправки положить к тунцу.','https:https://st.vkuso.ru/data/cache/thumb/86/37b178c2d9e6c86_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Порезать огурец на тоненькие пластинки, как можно тоньше порезать красный лук. Сваренные в крутую яйца порезать на пластинки. В оставшуюся заправку положить лук, огурец, размешать.','https:https://st.vkuso.ru/data/cache/thumb/c2/589c9bcacb174c2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Мелко порезать оливки.','https:https://st.vkuso.ru/data/cache/thumb/61/f0c7bc0dd37e161_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Помыть листья базилика, обсушить. Срезать у булочек верх. Вынуть мякоть – она не понадобится. Заполнить сэндвич. Сначала положить маслины, затем базилик.','https:https://st.vkuso.ru/data/cache/thumb/e5/2e7aefd3abe70e5_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Сверху яйца.','https:https://st.vkuso.ru/data/cache/thumb/a1/f8dcc1f8acbe8a1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Затем тунец.','https:https://st.vkuso.ru/data/cache/thumb/8f/679979f62fc9d8f_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'В завершение положить салат из лука и огурцов.','https:https://st.vkuso.ru/data/cache/thumb/1c/95a9a0daae7ba1c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9283,'Накрыть верхушкой булочки, завернуть полиэтиленовой пленкой. Таким образом поступить со всеми булочками. Поместить их под гнет. Отправить конструкцию в холодильник минимум на 60 минут, желательно на ночь, чтобы средиземноморские сэндвичи с тунцом, овощами и яйцом пропитались соком и стали нежными и сочными.','https:https://st.vkuso.ru/data/cache/thumb/cf/d5328e63079ffcf_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'Разделить зефир пополам, положить в формочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'В отдельную посуду вбить яйца, растереть с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'Раскрошить печенье, положить в сахарно-яичную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'Залить смесь молоком, варить, помешивая, пока масса не станет густой, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'Положить в посуду масло, помыть лимон, мелко потереть цедру. Размешать с маслом. Смешать с предварительно охлажденной массой, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9284,'Положить в формочку для кексов часть крема, ½ зефира, сверху покрыть кремом из печенья. Отправить в холодильник на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9285,'Почистить картофель, порезать соломкой, обжарить на растительном масле. Выложить при помощи шумовки на бумажное полотенце, чтобы стек жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9285,'Сделать кляр: соединить яйцо, ледяную воду, перец, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9285,'Обмакнуть куски рыбы в кляр, пожарить. Положить рыбу на бумажное полотенце.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9285,'Побрызгать соком лимона, подавать фиш энд чипс с лимонной долькой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Мелкие яблоки вымыть и просушить. В каждый плод вставить палочку, заготовки убрать в морозилку на 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/17/aaf21c0a8427e17_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Жирные сливки влить в сотейник, добавить светлую патоку и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Смесь варить на тихом огне до растворения сахара, не перемешивать.','https:https://st.vkuso.ru/data/cache/thumb/80/c6f21e0c8e24880_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'После закипания огонь увеличить до среднего, прогревать 10 – 15 минут, накрывая сотейник крышкой и немного наклоняя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Снять с огня. Масса должна получиться эластичной и мягкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Ковшик наклонить, полностью погрузить в карамель яблоко на палочке, повернуть плод вокруг оси, вынуть, поместить в емкость с кондитерской посыпкой.','https:https://st.vkuso.ru/data/cache/thumb/96/d99332c9519a596_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Эту же процедуру проделать с другими яблоками. Загустевшую карамель прогреть несколько секунд на среднем огне и продолжить приготовление.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9286,'Готовые яблоки переставить в холод на 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Сырые яичные белки взбить с сахаром в густую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Взять кондитерский шприц, выложить с его помощью на противень взбитые белки, форма заготовок – удлиненная.','https:https://st.vkuso.ru/data/cache/thumb/b6/b2503aee2e44db6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Печь безе в течение 10 минут при температуре 130 градусов, затем при 100 градусах печь еще 50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Яичные белки смешать с оставшимся сахарным песком и поставить на водяную баню, взбить до загустения.','https:https://st.vkuso.ru/data/cache/thumb/0e/d5840f4b236930e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Всыпать какао-порошок и растворимый кофе.','https:https://st.vkuso.ru/data/cache/thumb/9d/aeaa5e63ed9299d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'Перемешать. Добавить сливочное масло. Перемешать. Эта масса послужит начинкой.','https:https://st.vkuso.ru/data/cache/thumb/f7/5f2ca1c68e4a9f7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9287,'С помощью кондитерского шприца начинку выложить вторым слоем, третий слой – безе.','https:https://st.vkuso.ru/data/cache/thumb/96/640cfe37ee15496_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9288,'Нарезать мелкими кусочками мякоть говядины, переложить в чашу мультиварки, выставить режим «Тушение», оставить на 5 часов. Через 5 часов поперчить, посолить, добавить зубки чеснока и лавровый лист, готовить еще час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9288,'Тушенка в мультиварке по-домашнему после окончания режима «Тушение» должна постоять час с закрытой крышкой и «дойти». Готовую остывшую тушенку переложить в банку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Нарезать красный лук','https:https://st.vkuso.ru/data/cache/thumb/30/c368ce6f534ba30_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Всыпать на заранее разогретую с растительным маслом сковороду.','https:https://st.vkuso.ru/data/cache/thumb/46/7f8fb8fe39c8f46_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Баклажан и болгарские красные, зеленые или желтые сладкие перцы нарезать кубиками.','https:https://st.vkuso.ru/data/cache/thumb/95/8b60a979c7bbd95_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Когда лук обжарится – добавить к нему остальные овощи. Накрыть смесь крышкой, тушить на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/e3/00bba2e852d13e3_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Нарезать кубиками средний кабачок.','https:https://st.vkuso.ru/data/cache/thumb/cc/c220883ab718ecc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Добавить его в обжарку, вместе с давленым чесноком, молотым кумином, паприкой, перцем, солью. Все вместе тушить пять минут под крышкой.','https:https://st.vkuso.ru/data/cache/thumb/f4/d9650b10bf416f4_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9289,'Полученную смесь выложить в порционные горшочки, сделать углубления и вбить по яйцу. Если горшочек большой – можно по два. Поставить в духовку на 10 – 15 минут. Белки должны затвердеть, а желтки остаться жидкими.','https:https://st.vkuso.ru/data/cache/thumb/ea/35685c7cec303ea_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Два противня застелить бумагой для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Поломать кусочками и растопить на водяной бане или в микроволновой печи темный шоколад, немного остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Сырые куриные белки взбить в вязкую массу, всыпать сахарную пудру. Продолжать взбивать до плотного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Еще один стакан сахарной пудры перемешать с крахмалом, солью и какао-порошком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Включить миксер на среднюю скорость, ввести в крем сухую смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Влить растопленный шоколад и оставшиеся шоколадные кусочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Сформовать шарики, обвалять их в пудре, выложить на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Проделать эту процедуру со всем тестом. Печь в течение десяти минут, корочка должна треснуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9290,'Выпечку остудить и подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'На небольшой сковороде растопить сливочное масло, обжарить до готовности нарезанные грибы.','https:https://st.vkuso.ru/data/cache/thumb/5b/087b98b1351f55b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'Ветчину нарезать соломкой или кубиками, добавить в грибную массу, прогреть, убавить огонь до минимального.','https:https://st.vkuso.ru/data/cache/thumb/5a/d5b0b1bc1945e5a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'Сырые куриные яйца перемешать с йогуртом.','https:https://st.vkuso.ru/data/cache/thumb/f1/1069fd745eaa0f1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'Смесью залить грибы и ветчину.','https:https://st.vkuso.ru/data/cache/thumb/b2/307d5eb0cb2bbb2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'Сверху – тертый твердый сыр. Потушить под крышкой две-три минуты.','https:https://st.vkuso.ru/data/cache/thumb/82/61ea3d840048482_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9291,'Перед подачей переложить омлет грибами вверх, украсить листочками петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9292,'Измельчить с помощью блендера очищенный или неочищенный миндаль.','https:https://st.vkuso.ru/data/cache/thumb/a7/71e48d44dc5aba7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9292,'То же самое сделать с овсяными хлопьями.','https:https://st.vkuso.ru/data/cache/thumb/5d/6c6d7ae2acd925d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9292,'Оба ингредиента перемешать, влить воду, всыпать молотую корицу, положить лёд и нарезанный банан. Все вместе взбить и разлить в стаканы.','https:https://st.vkuso.ru/data/cache/thumb/97/2803b48bcdd7d97_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Для приготовления блюда понадобится сухой и жирный творог. Массу желательно протереть через сито.','https:https://st.vkuso.ru/data/cache/thumb/03/b5bc9c7e47d5a03_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Сырые яичные желтки перемешать с творогом, это можно сделать с помощью блендера.','https:https://st.vkuso.ru/data/cache/thumb/e5/4cb5ca48fa1abe5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Всыпать сахарный песок, измельченную цедру апельсина и лимона.','https:https://st.vkuso.ru/data/cache/thumb/a8/95d75303b7e0da8_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Добавить немного манной крупы, ананасовые цукаты и сушеную клюкву.','https:https://st.vkuso.ru/data/cache/thumb/b9/f62f5201ee2eeb9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Остатки яичных белков взбить со щепоткой соли и аккуратно вмешать в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Смазать сливочным маслом форму для выпекания, по желанию присыпать мукой, толчеными сухарями или манной крупой. Выложить массу в форму, запечь пудинг в духовке или на пару. В духовом шкафу готовить блюдо в течение 20 – 40 минут при температуре 180 – 190 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Для приготовления соуса ягоды клубники или вишни, свежие или размороженные, поставить на небольшой огонь. Всыпать сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Когда появится сок – измельчить массу блендером, влить кагор, например, «Новый Афон». Довести смесь до кипения, варить две-три минуты, до выпаривания алкоголя.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'В отдельной емкости перемешать кукурузный крахмал с небольшим количеством воды, влить смесь в соус, перемешать так, чтобы не образовались комки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9293,'Подать пудинг в теплом виде с ягодным соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Отделить желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Мякиш белого хлеба нарезать и залить молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Репчатый лук измельчить и обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Добавить в фарш вместе с желтками, хлебом, перцем и солью. Для фарша лучше всего использовать свинину и говядину в равных пропорциях.','https:https://st.vkuso.ru/data/cache/thumb/bc/c7d35e3251d32bc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Белок взбить и ввести в основную массу, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/bc/c8cbb8be740abbc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Сформовать котлеты, обвалять их в пшеничной муке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Жарить изделия на раскаленном растительном масле до образования румяной корочки, с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/d7/624f281fa8e52d7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'До готовности котлеты можно довести в духовке, разогретой до 180 градусов, время приготовления 15 – 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Очистить картофель, промыть, обсушить. Каждому клубню придать форму бочонка с помощью овощечистки, они должны быть примерно одного размера.','https:https://st.vkuso.ru/data/cache/thumb/8e/b17546cb176a38e_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Отварить картофель до готовности, воду слить, продукт обсушить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Раскалить на сковороде смесь растительного и сливочного масла, обжарить на нем клубни со всех сторон, должна появиться золотистая корочка. Соль и специи – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/a5/e52468bc90587a5_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9294,'Подать котлеты с картофелем, любимым соусом и зеленью.','https:https://st.vkuso.ru/data/cache/thumb/c1/6a91e69bc2dfac1_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Горошек замочить на ночь. Затем слить воду и переложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Налить свежей воды столько, чтобы она покрывала продукт на семь сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Посолить, довести до кипения, варить 10 минут, пену снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Накрыть крышкой, варить около часа на среднем огне, до мягкости.','https:https://st.vkuso.ru/data/cache/thumb/7a/da1ce83ed5b507a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Откинуть горох на сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Нагреть на среднем огне в сковороде топленое или растительное масло, обжарить семена кумина.','https:https://st.vkuso.ru/data/cache/thumb/84/664dc513e44f784_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Нарезать очищенный имбирь, болгарский перец и баклажаны крупными кусочками, морковь – соломкой.','https:https://st.vkuso.ru/data/cache/thumb/a3/e1ac0ab0bf3b3a3_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Обжарить на сковороде с маслом и специями имбирь, затем асафетиду и куркуму, в последнюю очередь – морковь, перец и баклажан.','https:https://st.vkuso.ru/data/cache/thumb/ee/0f27a840cca75ee_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Кусочки перца переворачивать во время приготовления.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Когда этот продукт подрумянится и станет мягким, добавить вымоченный горошек.','https:https://st.vkuso.ru/data/cache/thumb/43/c21ddf3438c4643_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Жарить три минуты, досолить.','https:https://st.vkuso.ru/data/cache/thumb/ab/d766fd83451c3ab_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9295,'Для приготовления соуса перемешать нарезанный помидор с водой, оставшейся от варки гороха, все вместе прогреть пять минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9296,'Взбить с сахаром до побеления 4 желтка, всыпать соду, ванилин, какао, влить холодную воду, перемешать, по частям осторожно вмешать хорошо взбитые белки. Добавить по частям муку, перемешать, но не долго, до получения теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9296,'Заполнить им смазанную форму, разровнять, поместить примерно на 35 минут в уже нагретую до 180 градусов духовку, готовность определить деревянной зубочисткой, она, после прокалывания коржа, должна оставаться сухой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Для начинки потребуется мягкий, не влажный творог, его нужно хорошо размять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9296,'Для приготовления крема поместить в кастрюлю сахар, муку, яйца, перемешать миксером, влить чуть теплое молоко, перемешать, нагреть до кипения, помешивая на слабом огне, сразу убрать с плиты и дать хорошо остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9296,'Взбить за это время ванилин и ставшее мягким масло, постепенно по ложке вмешать уже холодную молочную массу. Из какао, сметаны и сахара приготовить глазурь, проварив, помешивая смесь до начала кипения. Убрать с плиты, положить масло, перемешать до получения блестящей однородной массы, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9296,'Собрать тортик «Эскимо» в следующем порядке. На холодный корж размазать полностью крем, поместить на полчаса в холодильник, достать, полить глазурью, слой разровнять и опять отправить для окончательного застывания в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Всыпать в широкую емкость муку, подсолить, вмешать частями сильно охлажденное и натертое масло, влить холодную воду, слепить тесто в шар, долго не вымешивать, поставить в холодильник минимум на полчаса, но можно и больше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Приготовить из мелко порезанного мяса, обрезанного с окорочка и нашинкованного лука начинку, сдобрить ее перцем и солью, перемешать, дать чуть постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Взять половину теста, другая часть пусть пока лежит в холодильнике, сформовать из нее довольно толстую колбаску, порезать на 7-8 кусочков, раскатать из каждого сочник диаметром около 11-12 сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Разложить на середину каждого начинку, приподнять края с трех сторон и тщательно их залепить, повторить все со второй порцией теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Треугольные заготовки самсы с курицей разложить на противне (застелить предварительно пергаментом или фольгой), смазать разболтанным с небольшим количеством воды желтком, присыпать кунжутом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9297,'Выпекать порядка 50 минут в предварительно прогретой примерно до 180 градусов духовке до золотистости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9298,'Очистить и порезать яблоки на дольки, побрызгать соком лимона, чтобы они не темнели. Всыпать в кефир сахар, перемешать до растворения, вбить яйца, подсолить, взбить до однородности, постепенно по чуть-чуть подсыпая муку, перемешанную с разрыхлителем, до получения теста, напоминающего по густоте сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9298,'Раскалить в сковороде масло, разложить столовой ложкой тесто, а сверху уложить дольки яблок. Жарить оладушки с яблоками до красивого соломенного цвета с двух сторон, переложить на широкую тарелку, присыпать через ситечко корицей с сахарной пудрой, отдельно подать сметану, мед или варенье.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9299,'Обдать помидоры кипятком, а затем сразу облить холодной, кожица треснет и ее легко будет снять, плоды мелко порезать, нашинковать чеснок и поджарить пару минут в разогретом масле при минимальном нагреве, всыпать помидоры, тушить все вместе, периодически помешивая, четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9299,'Включить прогреться духовку (хватит 180 градусов), листики базилика нашинковать, рыбное филе порезать кубиками примерно по 4 см, яйца со специями разболтать вилкой, чуть подсолить. Все хорошо, но аккуратно перемешать и заполнить смесью форму для выпечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9299,'Поставить террин из трески с базиликом в уже достаточно разогретую духовку, запекать на водяной бане порядка 40 минут. Блюдо остудить, а потом поставить в холодильник на пару-тройку часов, извлечь из формы, подать к столу с любым салатом из овощей и тостами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9300,'Взбить вместе сахар и желтки до воздушной плотной массы, белки пока поставить в холодильник. Творог, если он с комочками, протереть через сито, перемешать со сметаной и желтками, добавить порциями смесь муки с крахмалом, все тщательно вымешать до пластичного однородного теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9300,'Достать холодные белки, подсолить, взбить, по частям вмешать в тесто, переложить его в мультиварку, перед этим промазать чашу маслом и притрусить манкой, излишки высыпать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9300,'Творожник в мультиварке готовить 50 минут в режиме «Выпечка», крышку до сигнала не открывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9300,'Достать чашу, прикрыть плоской тарелкой и перевернуть ее вверх дном и вернуть запеканку в чашу (опять смазать маслом и притрусить манкой), чтобы прожарилась и верхняя корочка, выставить тот же режим, выпекать 35 минут до готовности, дать остыть и вынуть из чаши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Баранину нарезать кусочками средней величины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Для приготовления теста взбить миксером мягкое сливочное масло с яйцом, сахаром, погашенной пищевой содой и щепоткой соли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Взбить массу до однородного состояния, муку добавлять постепенно, каждый раз перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Тесто немного помять и оставить на 15 – 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Полученную массу разделить на шарики величиной с грецкий орех.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Стол присыпать мукой, шарики раскатать в лепешки, выложить творожную начинку, свернуть сочни вдвое. Прослойка должна быть видна.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9301,'Время выпекания в духовке – от 20 до 25 минут, температура – от 170 до 200 градусов. Верх сочней перед выпечкой смазать сырым яичным желтком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Картофель, репчатый лук и морковь вымыть, очистить и нарезать. Овощи залить водой. Поставить кастрюлю на сильный огонь, после закипания варить в течение 15 – 20 минут на среднем огне, соль – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/80/af3ea1089fbb280_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Помидоры вымыть и нарезать кусочками средней величины, добавить их к остальным овощам. Прогревать еще 10 минут, до готовности.','https:https://st.vkuso.ru/data/cache/thumb/52/70f10615e35f652_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Готовые овощи немного остудить и перетереть с помощью блендера до днородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Переложить массу обратно в кастрюлю, поставить на тихий огонь, добавить брикет плавленого сыра, он должен расплавиться.','https:https://st.vkuso.ru/data/cache/thumb/5c/0ee8a9b3bd7705c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Затем положить сливочное масло и рубленую зелень, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/fc/c6557d8bd988ffc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9302,'Подать к столу горячим.','https:https://st.vkuso.ru/data/cache/thumb/a6/012f50be1df9ea6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Для приготовления печенья отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Взбить с сахаром (6 ст. л.) белки в плотную пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Добавить два желтка, вмесить муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Пергамент смазать маслом, выложить деревянные палочки и тесто. Присыпать сахарной пудрой, дать постоять 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/3f/33c767dc5d7393f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Разогреть духовку до 200 градусов, печь восемь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Для приготовления крема довести до кипения молоко, ввести заранее взбитый и перемешанный с картофельным крахмалом желток.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Чтобы не получилось комочков, крахмал нужно развести молоком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Всыпать сахарный песок (1 ст. л.), массу вымесить и поставить охлаждаться.','https:https://st.vkuso.ru/data/cache/thumb/43/3efa3ef804ff843_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Взбить сливки, добавить заварной крем, творожную массу и сгущенку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Выстелить пищевой пленкой стаканы, выложить крем, вставить печенье, сбрызнув его подслащенным кофе.','https:https://st.vkuso.ru/data/cache/thumb/c7/f719c70374642c7_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'Поставить стаканы в морозильную камеру на три-четыре часа для охлаждения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9303,'При подаче полить жидким шоколадом, растопленным на водяной бане.','https:https://st.vkuso.ru/data/cache/thumb/b0/9f8913f731c09b0_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9304,'Прогреть в микроволновке сливки (1,5 минуты, мощность – 1000Ват), поломать плитки шоколада на кусочки, соединить с горячими сливками, перемешать, дать остыть, затем поместить на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9304,'Из хорошо остывшего ганаша скатать шарики и вернуть еще на час в холодильник, достать, обвалять шоколадные конфеты в порубленных в крошку вафлях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9305,'Печенье измельчить любым удобным способом, перемешать с растопленным маслом и кусочки миндаля. Заполнить массой дно формы, смазанной маслом и выстланной бумагой для выпечки, слегка утрамбовать, убрать на верхнюю полочку холодильника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9305,'Растопить небольшие кусочки шоколада на водяной бане или микроволновой печи. Взбить миксером сахар со сливочным сыром, яйцами, крахмалом, ванилином и жидким шоколадом. Выложить на основу 2\3 полученной однородной массы, прикрыть прослойкой из ягод или фруктов, затем – 1\3 остатка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9305,'Заранее прогреть духовку поставить примерно на 40 (+5) минут форму, температура не должна превышать 180-190 градусов, готовый торт остудить примерно треть часа. Смазать верх глазурью из перемешанных сметаны, ванилина, мелкого сахара, поставить выпекать еще около 10 минут, температуру духовки не менять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9305,'Остудить готовый торт «Белоснежка», оформить шоколадной крошкой, сезонными фруктами и ягодами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Рис промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9306,'Обжарить мясо до изменения цвета в смеси подсолнечного и сливочного масла, добавить специи и грибы, еще немного протушить, влить сливки, аккуратно перемешать, положить заранее отваренные спагетти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9306,'Перемешать спагетти с курицей и опятами чтобы они хорошо пропитались, прогреть еще пару минут. Разложить по большим плоским тарелкам, дополнить дольками вареных яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9307,'Порезать готовые листы теста треугольниками, яблоки очистить и нарезать примерно одинаковыми дольками, выложить по одной на широкую часть, завернуть рулончиками в сторону меньшей. Сложить их в прямоугольную форму с высокими бортами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9307,'В кастрюльке при помешивании распустить масло, всыпать сахар, прогреть до образования как бы желейной смеси красивого ярко солнечного цвета, равномерно залить слойки в форме, вскрыть банку спрайта и вылить поверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9307,'Сразу поместить дрожжевые слойки с яблоком в уже горячую (170 градусов) духовку. Готовая выпечка разбухнет, смазать ее с помощью кисточки жидкостью из формы, вынуть на блюдо, дать подсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9308,'Куски курицы присолить и поперчить, обжарить с каждой стороны до светло шоколадного цвета примерно по 7-8 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9308,'Мясо вынуть, влить в сковороду сливки с бульоном, проварить две-три минуты, положить растертые листики эстрагона и горчицу, перемешать и прогреть еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9308,'При подаче куриную грудку полить этим соусом, гарнировать блюдо по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9309,'Подобрать одинаковые по размеру корнеплоды, отрезать остатки ботвы и хвостики для устойчивости, обмазать их растительным маслом, натереть солью с черным перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9309,'Обернуть каждую фольгой, поставить на противень, запечь в уже разогретой почти до 190 градусов духовке в течении 35-40 минут. За это время приготовить пассировку из чеснока, моркови и лука, отварить любую крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9309,'Вынуть репки, развернуть, чуть остудить, осторожно, чтобы не обжечься, вынуть мякоть, оставив 4-5 мм стенки. Измельчить ее, смешать с крупой и овощам, приправить небольшим количеством тимьяна, чуть присолить, перемешать, разложить по «стаканчикам», отправить фаршированную репу минут на 6-10 в еще горячую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9309,'Достать, слегка остудить, к столу подать на плоской тарелке с зелеными веточками тимьяна, отдельно поставить сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9310,'Засыпать в молоко комнатной температуры желатин, оставить минут на 5. В сотейнике, желательно с толстым дном, нагреть  с ванильным и обычным сахаром сливки с добавлением цедры лимона и корицы до кипения, сделать нагрев минимальным, кипятить 5 минут при помешивании.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9310,'Положить молочно-желатиновый гель, перемешать, прогреть (кипеть не давать) еще пару минут, чтобы желатин растворился, выловить кусочки цедры. Небольшой тазик наполнить очень холодной водой с крошкой льда, поместить в нее миску и вылить содержимое сотейника, взбить до получения густой массы (около 11-12 минут).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9310,'Разложить ее по фигурным формочкам (сердечки) и поместить в холодильник. За это время приготовить соус из протертой (размороженной) вишни с добавлением джема из смородины. В ягодную массу добавить кукурузную муку, хорошо перемешать, нагреть и дать закипеть, проварить, помешивая около минуты, дать остыть и отправить к формочкам в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9310,'Готовую сливочную панна котту вынуть с помощью тонкого и острого ножа из формочек, разложить по тарелочкам, полить хорошо охлажденным соусом, можно украсить целыми (чуть-чуть размороженными) ягодами вишни.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9311,'Нарезать на куски утку, вымочить в воде 15 минут, обсушить, переложить в мультиварку, подсолить, поперчить, полить соевым соусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9311,'Выставить режим «Выпечка» и время 50 минут, переключить после сигнала на «Тушение», готовить 20-40 минут (проверять готовность).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9312,'Сварить филе, порезать небольшими кубиками, обжарить мелко нашинкованный лук, высыпать в него мясо, для сочности начинки можно добавить одну-две ложечки хорошей сметаны, подсолить, перемешать, чуть потушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9312,'Багет, чуть черствый, порезать на несколько одинаковых частей, удалить мякоть, чтобы получились стаканчики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Мясо порезать на кубики, чуть обжарить, перемешать с перцем и луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9312,'Наполнить их начинкой, переложить «Пеньки» из багета на противень, положить в каждый по дольке помидора, присыпать сыром и отправить минут на 20 в духовку до расплавления сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9313,'Засыпать ягоды в кастрюлю, добавить сахарный песок, сок лимона и цедру, нагреть на среднем огне, варить при периодическом помешивании до тех пор, пока кожура черники не лопнет и не выделится сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9313,'Убрать кастрюльку с плиты, превратить «варенье» с помощью блендера в пюре, влить сливки, сметану, добавить ванилин, взбить в однородную массу, дать остыть и убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9313,'Когда смесь для черничного мороженого из сметаны достаточно остынет поместить ее в мороженицу, далее делать все по инструкции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9313,'Готовое лакомство переложить в контейнер и окончательно заморозить не менее 2 часов в морозильной камере холодильника.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9314,'Налить в кастрюлю с толстым дном и объемом 5 литров масло, нагреть его, покрошить телятину, обжарить четверть часа, далее – грудинку, жарить до изменения цвета, добавить в конце нашинкованный мелкими кубиками лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9314,'После размягчения лука всыпать в кастрюлю кубики соленых огурцов (крупные семена удалить), прогреть 5 минут. Окатить кипятком помидоры, быстро охладить и «раздеть», мякоть порезать маленькими кубиками, отправить следом за огурцами, добавить около столовой ложки каперсов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9314,'Вскрыть банку с томатами в собственном соку, добавить в солянку, поперчить, тушить еще 10 минут. Добавить последний мясной ингредиент – охотничьи колбаски (купаты), тушить порядка 5 минут, влить до желаемой густоты воду, по вкусу сдобрить перцем, подсолить, закрыть крышкой, проварить треть часа на очень малом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9314,'Разлить мясную солянку по тарелкам, положить в каждую по кружочку лимона, по несколько (на свой вкус) маслин и обязательно добавить по ложке хорошей сметаны, заключительный штрих – посыпать зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Тесто для пиццы раскатать в прямоугольник, разложить ветчину и швейцарский сыр, нарезанный ломтиками.','https:https://st.vkuso.ru/data/cache/thumb/ee/f6aa37a174a3eee_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Заготовку скрутить в тугой ролл, края защипать, положить заготовку вниз швом.','https:https://st.vkuso.ru/data/cache/thumb/94/5155c218d526f94_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Разрезать получившийся рулет на десять кусочков, выложить их на противень в один слой.','https:https://st.vkuso.ru/data/cache/thumb/63/cd4f6a1e0670f63_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Перемешать сливочное масло с коричневым сахаром, дижонской горчицей и вустерским соусом. Всыпать мак, поставить на огонь средней мощности.','https:https://st.vkuso.ru/data/cache/thumb/4a/6bf0501a07fe24a_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Готовить до тех пор, пока масса не загустеет и не станет однородной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Полученный соус снять с огня и полить им роллы.','https:https://st.vkuso.ru/data/cache/thumb/e1/30b30bfea69bfe1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9315,'Печь при температуре 180 градусов в течение 25 минут до получения золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Все ингредиенты разделить пополам и замесить каждую часть отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'В ванильный бисквит добавить ванилин, в шоколадный – какао-порошок. Из рецептуры убрать столовую ложку муки и добавить две ложки какао.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Отделить белки от желтков, вторые взбивать с сахаром до посветления в течение пяти минут. Масса должна значительно увеличиться в объеме. Во время взбивания влить растительное масло, а затем воду.','https:https://st.vkuso.ru/data/cache/thumb/cc/346a1d2589c65cc_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Отдельно просеять муку с разрыхлителем, лучше сделать это дважды, для обогащения воздухом, в половину сухой смеси всыпать какао.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'В обе массы добавить цедру лимона, влить желтковую смесь, смешать ингредиенты до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/13/a12f95fb996ff13_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Белки взбить, при появлении пены добавить винный камень или лимонную кислоту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Ввести массу в желтковую смесь, перемешать движениями снизу вверх, чтобы не опали белки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Дно формы для выпекания выстелить пергаментом, не смазывать, перелить тесто и печь в духовом шкафу на средней полке при 180 градусах в течение 35 – 45 минут. Время зависит от глубины формы. Проверить готовность сухой деревянной шпажкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Таким же способом испечь темный бисквит.','https:https://st.vkuso.ru/data/cache/thumb/eb/292549323c43beb_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'В отдельной кастрюле небольшого диаметра довести до кипения сливки (50 мл), влить их в шоколадную массу и перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Далее влить еще часть сливок (100 мл), делать это лучше понемногу, порциями. В результате должна получиться масса, похожая на эмульсию.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Поставить ганаш в холодильник на час или два, затем взбить и сразу же промазать им бисквиты.','https:https://st.vkuso.ru/data/cache/thumb/a6/cc347b1dcf8c7a6_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Для крема взбить сливки (200 мл) с сахарной пудрой, нанести массу на бока и поверхность торта, разровнять и поставить торт в холодильник для пропитывания.','https:https://st.vkuso.ru/data/cache/thumb/48/f2d552b3104fd48_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9316,'Перед подачей украсить торт ягодами, например, ежевикой и веточками красной смородины. Их можно присыпать сахарной пудрой для эффекта заснеженности.','https:https://st.vkuso.ru/data/cache/thumb/b3/72f4fa80da465b3_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9317,'Порезать сыр и ветчину на кубики. Взбить подсоленные яйца с перцем, влить молоко, перемешать. Добавить мягкое масло, кубики ветчины, сыра, постепенно всыпать муку, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9317,'Заполнить массой подготовленные формочки (не доходя на треть до краев формы).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9317,'Выпекать американские маффины с ветчиной и сыром при температуре духовки 180 градусов  (примерно около получаса).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9318,'Разогреть оливковое или любое другое масло на сковороде, добавить специи, чеснок, соль, базилик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9318,'Смесь прогреть до появления аромата, листья базилика вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9318,'Всыпать макароны пенне или лигурийскую пасту, перемешать, влить белое сухое вино, томить на слабом огне до выпаривания алкоголя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9318,'Влить половину нормы заранее сваренного горячего бульона. Подождать, пока паста впитает жидкость, долить оставшийся бульон и сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9318,'Массу аккуратно перемешивать лопаткой. При готовности всыпать тертый сыр «Пармезан» и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Разогреть оливковое масло в небольшом сотейнике, обжарить в нем измельченный чеснок и  репчатый лук в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Добавить сушеные травы базилика и орегано, петрушки, порошок перца чили, молотый тмин, черный перец и соль.','https:https://st.vkuso.ru/data/cache/thumb/e6/bd8d78b8e2f60e6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Перемешать, влить воду, довести смесь до кипения. Томить на тихом огне от 15 до 60 минут, время зависит от получения желаемой консистенции. Соус снять с огня и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Твердый сыр и «Моцареллу» измельчить, соединить с соусом (60 мл), перемешать.','https:https://st.vkuso.ru/data/cache/thumb/e4/fe5463386317ee4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Готовые пшеничные лепешки прогреть в микроволновой печи, начинить сырной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Свернуть плотные роллы, выложить в термостойкую форму, шов должен оказаться внизу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Полить соусом, посыпать остатками сыра, добавить измельченный зеленый лук и оливки.','https:https://st.vkuso.ru/data/cache/thumb/fc/bafcd767fbe7dfc_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9319,'Печь изделия при температуре 200 градусов в течение 20 минут, до получения золотистой корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9320,'Крабовые палочки измельчить при помощи блендера, морковь крупно натереть на терке, репчатый лук мелко порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9320,'Палочки, морковь, лук, молоко, яйцо и панировочные сухари перемешать до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9320,'В получившийся фарш добавить соль и черный молотый перец, еще раз перемешать и сформовать котлеты желаемого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9320,'Обжаривать котлеты из крабовых палочек в панировочных сухарях на растительном масле до подрумянивания со всех сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Вскипятить в сотейнике воду, загрузить тушку кальмара на одну минуту.','https:https://st.vkuso.ru/data/cache/thumb/e1/4c2cd80866879e1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Затем вынуть и нарезать кольцами.','https:https://st.vkuso.ru/data/cache/thumb/9a/cebacdddc43ee9a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Взбить в пену сырые куриные белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Для кляра в отдельной емкости перемешать пшеничную муку с водой, соль – по вкусу, добавить растительное масло и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Аккуратно ввести белковую пену, перемешать до однородности с помощью венчика.','https:https://st.vkuso.ru/data/cache/thumb/11/fd691dac42e9111_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Раскалить в сотейнике большое количество растительного масла. Жарить во фритюре кольца кальмаров, предварительно обмакнув в кляр.','https:https://st.vkuso.ru/data/cache/thumb/95/3e80bfa5a213d95_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'Выложить их на бумажное полотенце для впитывания жира.','https:https://st.vkuso.ru/data/cache/thumb/f0/757e720648d28f0_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9321,'При подаче закуску полить лимонным соком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Всыпать в кастрюлю половину стакана сахара, добавить молоко со сливками, перемешать, прогреть на малом огне до образования сиропа. Яичные желтки (3шт.) взбить блендером, всыпать 1\4 стакана сахара, продолжить взбивать до приобретения смесью бледно-желтого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Осторожно соединить желтки примерно с половиной (чуть меньше) стакана еще горячего молочно-сливочного сиропа, аккуратно перемешать. Теперь можно сиропа влить уже в 3 раза больше, перемешать и объединить с оставшейся молочной массой в кастрюле и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Полученную массу прогреть, при постоянном помешивании на малом огне до сгущения, чтобы после погружения в нее ложки, на последней оставался равномерно густой слой. Еще горячую смесь вылить в сито с мелкими ячейками, добавить любую ореховую пасту, влить экстракт ванили, перемешать в однородную массу, хорошо остудить под крышкой и отправить провести ночь в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Растопить в небольшой кастрюльке, желательно с толстым дном, половину пачки масла, всыпать какао, влить воду, размешать, нагреть до полного распускания масла, убрать с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Приготовить тесто для основы. Для этого перемешать сахар, с просеянной и подсоленной мукой, смешать с еще горячей смесью какао, хорошо вымешать, вбить пару яиц, влить кефир с содой и ванильный экстракт, окончательно перемешать в однородную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Вылить тесто на выстланный пекарской бумагой противень, задвинуть его в уже прогретую духовку на полчаса. Дать остыть готовому коржу около 5 минут, перевернуть противень, удалить бумагу, дать ему как следует остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Уже хорошо остывшую смесь для слоя мороженого перенести в мороженицу, следуя инструкции по ее эксплуатации приготовить мороженое. Порезать любые шоколадные конфеты или шоколад с орехами на кусочки, пересыпать их в готовое мороженое, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Выстлать противень квадратной формы, предварительно смазанный маслом, пергаментом (края должны выступать за его края с большим запасом).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'Уложить на него отрезанный кусок коржа размером с противень, смазать слоем мороженого, разровнять, прикрыть другим куском коржа, слегка придавить широким ножом, накрыть торт свисающими краями пергамента, а затем обернуть пищевой пленкой и определить в морозильную камеру для затвердения десерта.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9322,'За это время приготовить крем. Поломать на маленькие кусочки шоколад, залить почти закипевшими сливками, дать постоять минут 5, перемешать, равномерно облить поверхность орехово-шоколадного торта, присыпать раздробленными орехами, вернуть десерт в морозилку для застывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9323,'Поставить на плиту кастрюльку с водой, всыпать яблоки, порезанные соломкой и сахар, добавить корицу, варить до полного испарения жидкости при среднем нагреве, снять с плиты, всыпать орехи, добавить мармелад из сливы, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9323,'Для теста мягкое сливочное масло растереть с сахаром, вбить яйцо, размешать, влить молоко, сдобрить ванилином, хорошо размешать, добавить муку, разрыхлитель, вымесить мягкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9323,'Отрезать кусок, раскатать в 3-х миллиметровый пласт, нарезать на равносторонние 10 см треугольнички, сделать внутри каждого острым ножом прорези и положить по центру начинку, загнуть одну, а потом другую сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9323,'Разложить печенье «Чарох» на противне, поместить в разогретую духовку на четверть часа, выпекать до появления золотистого цвета, дать печенью остыть присыпать через ситечко сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9324,'Залить стаканом воды сахар, нагреть почти до кипения, перемешать, всыпать дольки апельсина, заранее убрать косточки и прожилки, довести все до кипения, дать «варенью» остыть, еще раз повторить процедуру, остудить, и если соус еще не очень густой, то повторить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9324,'Аккуратно снятую с апельсина цедру залить кипящей водой на 10 минут, добавить вместе с порезанным имбирем, погреть минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9324,'Разлить варенье по небольшим баночкам, убрать после остывания в прохладное место. Это идеальное дополнение к оладьям и блинам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9325,'Взбить размягченное масло и сахар, добавить через сито муку, вымесить тесто, добавить измельченные в мелкую кошку обжаренные орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9325,'Шарик теста поделить на небольшие кусочки, по размеру напоминающими грецкий орех.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9325,'Каждый колобок сплюснуть и положить на промазанный маслом противень, отправить сахарное печенье минут на 15 в уже прогретую до 180 градусов духовку, дать печенью чуть остыть, переложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9326,'Добавить к тертому сыру, яйца, сметану, молоко, майонез, сдобрить специями, как следует перемешать, добавить кубики отварной курицы, всыпать порубленную зелень и муку перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9326,'Заполнить этой смесью формочки, поставить маффины на 20 минут в разогретую заранее чуть ниже 185 градусов духовку, подавать блюдо слегка остывшим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9327,'Разрезать авокадо, удалить косточку, удалить, не повредив кожуры, всю мякоть, нарезать ее на небольшие кубики. Вымытые огурцы измельчить на такие же кубики, креветки (8 шт) разрезать на несколько кусочков, объединить всю нарезку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9327,'Хорошо перемешать между собой ингредиенты для заправки, окунуть в соус отложенные креветки, положить их в сторону, заправить салат из авокадо с креветками, аккуратно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9327,'Заполнить половинки кожуры салатом, оформить оставшимися креветками в соусе, присыпать верх стружкой пармезана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'На небольшие кусочки порезать промытое и обсушенное куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'Сложить все кусочки в миску, добавить по 1 ч.л. соли, черного молотого перца и гранулированного чеснока, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'В полиэтиленовый пакет сложить необходимое количество картофельных чипсов и любым удобным способ превратить их в мелкую крошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'Переложить картофельную крошку в мисочку или пиалу, добавить панировочные сухари, соль, сушеную петрушку, молотый красный перец и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'В небольшую тарелку насыпать муку, в отдельной посуде взбить яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'Подготовленные кусочки куриного филе запанировать сначала в муке, затем во взбитых яйцах, в конце обвалять кусочки в подготовленной сухой смеси.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9328,'Обжаривать острые куриные наггетсы по-домашнему в сковороде с нагретым растительным маслом со всех сторон до образования золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9329,'Раскатать прямоугольником размороженное тесто, разрезать его на два одинаковых квадрата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9329,'Выложить на середину каждого, для предотвращения протекания сока, перемешанную с крахмалом сахарную пудру (чайную ложку), а затем ягоды, свернуть конвертиками, сделать в каждом маленькие надрезы для выхода излишков пара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9329,'Разложить слойки с черной смородиной на противне с пергаментом, задвинуть его в духовку на четверть часа, температуру поддерживать около 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9329,'Дать выпечке чуть остыть, присыпать пудрой и подать к кофе-чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9330,'Пластины свинины, отбить, поперчить, присолить, сложить в миску, дать чуть постоять. Разрезать соленый огурчик вдоль, а потом каждую часть еще раз вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9330,'Уложить на каждую отбитую пластину мяса по одному кусочку огурца, завернуть с небольшим усилием в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9330,'Обжарить в растительном масле с каждой стороны при среднем нагреве по 4-5 минут до зарумянивания, переложить в форму, запечь огурцы в мясной шубке в духовке, заранее прогретой примерно до 200 градусов, четверть часа, если свинина будет чуть жестковатой, то подержать в духовке еще около 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9331,'Перемешать куриный фарш, сделанный из грудки, с брокколи, зеленым горошком, нашинкованными перьями зеленого лука и луком шалот, вбить яйцо, добавить крахмал, цедру лимона и сок, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9331,'Для придания фаршу сочности влить несколько ложек масла, сдобрить черным перцем и солью, хорошо вымесить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9331,'Обжарить оладьи на среднем огне до светло соломенного цвета, подать с любыми овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Натереть на терке сыр «Чеддер».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Нарезать небольшими кусочками белый хлеб для тостов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Ломтики ветчины нарезать квадратиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Обжарить хлеб на небольшой сковороде без жира.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Поставить смесь на плиту, довести до кипения, добавить тертый сыр порциями, прогревать до полного растворения продукта.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9332,'Полученной массой залить хлеб с ветчиной, поставить в разогретую духовку, запечь при высокой температуре в течение нескольких минут в режиме гриля.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Крупную зеленую чечевицу хорошо промыть и варить в воде в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'После закипания убавить огонь до минимального.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Соль добавить в конце приготовления.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Шпинат обжарить на ложке оливкового масла, время – минута, массу помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Нарезать помидоры и авокадо, перемешать со шпинатом и чечевицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Отварить яйца-пашот. В воду добавить немного уксуса, довести её до слабого кипения, разбить яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Лучше влить их из мисочки, при этом в кастрюле создать лопаткой небольшую воронку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Готовые яйца достать шумовкой и опустить на минуту в холодную воду, чтобы остановить процесс денатурации и смыть уксус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9333,'Готовый продукт выложить на салат и подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Форму смазать растительным маслом, на дно положить мясо, нарезанное кусочками и посыпанное солью и пряностями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Нарезать репчатый лук, обжарить до золотистого цвета, всыпать консервированные грибы, прогреть все вместе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Обжарку выложить на мясо, сверху – полукольца картофеля, посыпать смесью соли с пряностями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Отдельно перемешать сладкий болгарский перец, нарезанный кубиками, тертую морковь, перец чили, майонез и давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Полученную смесь вылить на картофель, посыпать тертым твердым сыром. Накрыть блюдо фольгой, печь в течение часа при температуре 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9334,'Фольгу снять и жарить еще 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Тыкву вымыть, очистить и запечь в духовом шкафу при температуре от 180 до 200 градусов до мягкого состояния.','https:https://st.vkuso.ru/data/cache/thumb/a3/3e0dcbbc70a24a3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Залить кипятком изюм без косточек, оставить на несколько минут, затем воду слить. Продукт выложить на бумажное полотенце и обсушить.','https:https://st.vkuso.ru/data/cache/thumb/7d/bde6f9e8ad1c47d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Готовую охлажденную тыкву нарезать брусочками.','https:https://st.vkuso.ru/data/cache/thumb/75/1b80791b1010875_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Почистить апельсин, разделить дольками, удалить пленку, каждый кусочек разрезать пополам.','https:https://st.vkuso.ru/data/cache/thumb/4f/b65fe808cddb24f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Для соуса положить в небольшую кастрюлю сахар, влить воду, прогреть сироп до растворения песка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Добавить шоколад, поломанный на кусочки, сливочное масло, мешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/e5/fe54921d0c811e5_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'В массу добавить ванильный экстракт и сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Выложить на тарелку кусочки апельсина и тыквы, сверху – изюм.','https:https://st.vkuso.ru/data/cache/thumb/41/e79e02002e94041_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9335,'Полить десерт шоколадным соусом, сразу подать.','https:https://st.vkuso.ru/data/cache/thumb/48/dba64106d0d2048_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9336,'Всыпать в широкую миску муку с солью, влить постепенно (по четверти стакана) небольшой струйкой воду, хорошо вымешать тесто, которое не будет приставать к рукам, но останется достаточно упругим, влить масло (1 ст. л.), окончательно перемешать. Колобок теста прикрыть полотенцем и пусть пол часика постоит и «дозреет».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9336,'Для начинки картофель превратить в пюре, добавит остальные ингредиенты, немного подсолить, перемешать, чтобы лук и зелень равномерно распределились в картофеле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9336,'Чтобы сформовать алу паратха надо взять кусочек теста, как для небольшого пирожка, раскатать и по центру сочня поместить достаточное количество начинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9336,'Защипать от краев к центру и вверху хорошо соединить все в одной точке, по форме должны получиться большие манты. Теперь аккуратно раскатать каждый опять в лепешку и обжарить с каждой стороны на прогретой сковороде при среднем нагреве до образования корочки песочного цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9336,'Во время обжарки алу паратха с картофелем пару-тройку раз перевернуть, и при этом побрызгать маслом, и придавить ко дну сковороды лопаточкой для более равномерного прогрева.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Всыпать кукурузу, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9337,'Разогреть при среднем нагреве в глубокой сковороде пару ложек масла, всыпать рис, обжарить, помешивая до потери белого цвета (около 4 мин), добавить нашинкованный сельдерей, репчатый лук, измельченную морковь, обжарить все вместе еще 4-5 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9337,'Порубить мелко чеснок, всыпать к овощам, через пару минут влить воду, приправить рис «Перекати-поле» шафраном, соком лимона, лавровым листом, нагрев сделать минимальным, готовить около 20 минут под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9337,'Готовое блюдо перемешать, убрать лавровый лист, присыпать зеленью кинзы и сразу подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Перетереть сахар со сливочным маслом, добавить сырые куриные яйца, взбить массу венчиком или миксером.','https:https://st.vkuso.ru/data/cache/thumb/14/a742bf84b16be14_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Просеять муку частями.','https:https://st.vkuso.ru/data/cache/thumb/a3/fefb43dcb0b30a3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Добавить в массу какао-порошок и разрыхлитель.','https:https://st.vkuso.ru/data/cache/thumb/5d/52e2f3cfdff8c5d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Все ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Вымыть и почистить груши, нарезать кубиками или дольками.','https:https://st.vkuso.ru/data/cache/thumb/85/a378ed0a0173085_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Добавить их в тесто вместе с очищенными кедровыми орешками.','https:https://st.vkuso.ru/data/cache/thumb/6d/0f41f0b6e412c6d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/40/a14473e36e78640_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Массу выложить в форму, смазанную маслом или застеленную бумагой для выпечки. Если форма силиконовая – это делать необязательно.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Печь в течение 40 – 50 минут в духовке, разогретой до 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/7c/e20095daca8c77c_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Для приготовления глазури поломать плитку шоколада, добавить молоко, немного сливочного масла, продукты поставить в микроволновую печь или растопить на водяной бане.','https:https://st.vkuso.ru/data/cache/thumb/ef/f17456a669ffcef_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9338,'Полить пирог.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9339,'Размягченный маргарин взбить с сахаром, яйцом и молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9339,'Добавить в жидкую массу ванилин, разрыхлитель и муку, быстро замесить тесто. Оно должно получиться мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9339,'Получившееся тесто раскатать в пласт, толщина которого должна быть не больше 0,6-0,7 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9339,'Выдавить из теста коржики любого размера, переложить заготовки на противень и убрать его в духовку, нагретую до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9339,'Выпекать молочные коржики из детства с ванилью в течение 15 минут до подрумянивания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Растопить сливочное масло на тихом огне в небольшой кастрюле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Немного охладить молоко, добавить ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'В течение пяти минут взбить сырые яйца с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'В миску просеять кукурузную и пшеничную муку, разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Влить масло и молоко, яичную смесь, всыпать сахарный песок. Массу взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Смесь вылить в форму для выпекания, поставить в духовку, температура приготовления – 180 градусов, время – 20 минут. Проверить зубочисткой готовность коржа, переложить его на решетку и дать остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Растопить в кастрюле белый шоколад и сливки, смесь перемешать до однородного состояния и взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Положить в кастрюлю темный шоколад и сливочное масло, растопить на минимальном огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Снять, добавить сахарную пудру, мускатный орех.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Если соус получился густым, можно подлить горячую воду.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Охлажденный корж нарезать на одинаковые квадратики.','https:https://st.vkuso.ru/data/cache/thumb/78/250181bb5c66578_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'В неглубокую миску всыпать кокосовую стружку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Каждый квадратик обмакнуть в соус.','https:https://st.vkuso.ru/data/cache/thumb/63/1a6c4e14a33b363_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Затем обвалять в стружке.','https:https://st.vkuso.ru/data/cache/thumb/92/8470545436e0192_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Смоченные ломтики выложить на решетку, подсушить, разрезать вдоль.','https:https://st.vkuso.ru/data/cache/thumb/15/1bb28107f942115_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9340,'Между половинками проложить крем из жирных сливок и белого шоколада.','https:https://st.vkuso.ru/data/cache/thumb/46/80b9152090f5746_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Довести до кипения воду, положить пакетик с рисом, готовить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Вымыть и порезать на мелкие кусочки куриное филе.','https:https://st.vkuso.ru/data/cache/thumb/ed/4f9c3e2415bc7ed_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Продукты перемешать, посолить, поперчить, заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Порезать на кубики моцареллу, сладкий перец, шампиньоны. Измельчить зеленый лук.','https:https://st.vkuso.ru/data/cache/thumb/57/58609a7c9469557_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Соединить в емкости сладкий перец, грибы, мясо, моцареллу, яйца, зеленый лук. Добавить чеснок, перец чили, крахмал, соль, сливки, черный перец.','https:https://st.vkuso.ru/data/cache/thumb/23/328b2513e259323_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Размешать.','https:https://st.vkuso.ru/data/cache/thumb/8c/0db359259def68c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Сформировать котлеты, положить на сковороду с растительным маслом.','https:https://st.vkuso.ru/data/cache/thumb/95/8068e415a4d3995_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9341,'Жарить под крышкой с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/02/a1ce2c3f218fa02_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9342,'Пару тушек сельди разделать на филе или взять готовое, порезать огурцы тонкими пластинками, морковь, лук и перец – небольшими кубиками, порубить зелень и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9342,'Для начинки приготовить желирующий состав, согласно инструкции на упаковке желатина, перемешать его со сметаной, а потом с зеленью и овощами, добавить лимонный сок и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9342,'Выложить на одну половинку филе начинку, уложить сверху другую часть, также поступить и со второй сельдью, плотно, но аккуратно обернуть нафаршированное филе в пленку, концы обвязать, убрать на ночь сельдь «Самоцветы» в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Подготовить продукты. Измельчить печенье. Соединить крошку с ложкой сахара и мягким сливочным маслом.','https:https://st.vkuso.ru/data/cache/thumb/08/d0533bd58c51908_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Намазать разъемную формочку сливочным маслом. Выложить полученную крошку на дно и бортики. Отправить на 7-10 минут в духовку, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/41/6d9c86f0a33c041_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Соединить в посуде плавленый сыр, творог, яйца, цедру лимона, 4 большие ложки сахара, 1 маленькую ложку ванильного сахара. Перемешать до однородности блендером, постепенно увеличивая скорость.','https:https://st.vkuso.ru/data/cache/thumb/76/d8a6c7ab05a4976_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Положить в форму массу из творога, чуть-чуть разровнять. Готовить 30-35 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Вынуть готовый корж из духовки, сразу осторожно провести вдоль бортиков ножом, отделяя пирог.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9343,'Дать творожно-сырному чизкейку по-домашнему остыть, желательно поставить на час в холод.','https:https://st.vkuso.ru/data/cache/thumb/c9/673d4e47edd11c9_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9344,'Готовое тесто разделить на две, желательно равные части, промазать каждую маслом, положить на край банан, если он сильно загнутый, то надломить в нескольких местах и расправить, присыпать банан смесью дробленого ореха, сухарей и корицы, свернуть каждую половинку аккуратно, но с небольшим усилием в трубочку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9344,'Поставить банановый штрудель примерно на 40 минут в духовку с температурой не выше 180 градусов. Оба рулетика должны приобрести приятную для глаза аппетитную коричневатую корочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9345,'Подготовленное филе нарезать на кубики среднего размера, а лук – мелкого, морковь натереть или порезать довольно мелкой соломкой, смешать с мукой полстакана воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9345,'Влить в мультиварку масло, заложить мясо, поставить режим «Выпечка», время – 8 минут, если не хватит, то добавить еще пару минут. Засыпать в чашу лук с морковью, аккуратно перемешать, режим мультиварки не менять, готовить 10 минут, влить сливки, подсолить, приправит паприкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9345,'Добавить, постоянно мешая, мучную «заливку», режим поменять на «Тушение», готовить курицу в сливочном соусе в мультиварке 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9345,'Подавать блюдо сразу после сигнала об окончании программы с рассыпчатым рисом или другим любимым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Нагреть в кастрюле оливковое масло, чуть-чуть потушить мелко нарезанный лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Налить воду, добавить лавровый лист. Подождать, пока закипит.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Положить нарезанный кубиками картофель. Готовить под крышкой, пока он не приготовится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Положить в кастрюлю рыбу (без кожи, костей и мелко нарезанную), готовить 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Налить сливки, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Сделать кашицу, добавив в крахмал ложку воды, перемешать, чтобы растворился крахмал.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Положить кашицу в суп, варить до загустения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Добавить сливочное масло, размешать, убрать с плиты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9346,'Посыпать перцем, солью. Присыпать измельченной зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9347,'Взбить с помощью миксера пару минут размягченное масло, всыпать сахарную пудру, корицу, соль, ванилин, добавить мед, взбить до получения однородной по консистенции массы кремового цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9347,'Переложить медово-коричное масло в стеклянную баночку, хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9348,'Помыть кочан радиккио, порезать на крупные полосы, прокипятить бульон. Разогреть на сковороде смесь оливкового и сливочного масел, обжарить бекон и лук до размягчения. Добавить полосы салата, прожарить пару минут и всыпать рис, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9348,'После того, как рис потеряет цвет и станет прозрачным, влить вино, очень хорошо перемешать, готовить пока смесь не станет сухой, влить треть разогретого бульона, посолить, помешивая дать ему впитаться в рис и подлить еще часть бульона, довести рис почти до готовности, он должен слегка похрустывать, снять с плиты. Если надо, то в процессе приготовления еще раз добавить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9348,'Последний этап в приготовлении ризотто из радиккио с беконом– мантекатура. Для этого кулинарного приема кусочки холодного масла положить в блюдо, быстро и хорошо перемешать, чтобы оно полностью растаяло, всыпать сырную стружку, еще раз перемешать и сразу же подавать к столу, присыпав каждую порцию стружкой пармезана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9349,'Обжарить ломтики бекона до хруста, разложить на полотенце из бумаги, включить прогреваться до 230 градусов духовой шкаф, когда масло с бекона впитается, порезать его на мелкие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9349,'В пюре влить молоко, добавить козий сыр, подсолить, поперчить, добавить кусочки бекона и порезанный зеленый лук, начинку перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9349,'Тесто раскатать на одинаковые круги по размеру пиццы, из расчета по 2 на каждую. На 4 основания равномерным слоем разложить начинку, присыпать чеддером, прикрыть оставшимися кругами, тщательно залепить края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9349,'Переложить пиццу «Кальцоне» с начинкой из пюре на выстланный пергаментом противень, промазанный маслом, задвинуть в духовой шкаф, достигший уже необходимой температуры. Пицца будет готова минут через 10-12, когда верх покроется корочкой золотисто-соломенного цвета (испечь оставшиеся три заготовки).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9349,'Достать выпечку, приготовить из всех ингредиентов с помощью блендера соус, подать вместе с пиццей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9350,'Очистить плоды хурмы от твердой кожуры, порезать на кубики, измельчить с помощью сита в пюре, залить желатин водой, дать минут 10 постоять, влить бренди, прогреть, помешивая на водяной бане до растворения всех пластинок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9350,'Смешать полученный раствор с хурмой, взбить с помощью венчика, дать остыть полчаса, несколько раз за это время взбить, чтобы не пошло застывание.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9350,'Подготовленную печень обсушить, поперчить, подсолить, обжарить в хорошо прогретом масле, перевернув несколько раз для лучшего прогрева, побрызгать на кусочки бальзамическим уксусом, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9350,'Уложить террин из куриной печени с хурмой в прямоугольную классическую форму для кексов, выстланную пленкой, в следующем порядке: треть печенки, половину фруктового желе, треть печени, опять желе и закончить слоем из оставшейся печени, полить несколькими ложками сока с маслом от обжаривания печени. Форму затянуть пленкой, 3 часа дать постоять в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9351,'Отварить рис с добавлением специй, молодые кабачки порезать вместе с кожурой на шайбочки, помидоры – вдоль на кружочки. Включить духовку, прогреть ее до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9351,'Слегка зарумянить на сковороде с маслом кабачки, обжарить измельченный лук на другой сковороде. Выложить на смазанный маслом противень рис, прикрыть слоем лука, а затем – кабачками, последними выложить помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9351,'Взболтать яйцо, перемешать с попущенным через пресс чесноком, залить верх рисовой запеканки, отправить в духовку примерно на треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9352,'Просеять муку с добавлением разрыхлителя в широкую миску, добавить какао, сахар, соль, масло, влить воду, перемешать до образования однородного теста, заполнить им форму, отправить минут на 45-50 в духовку, выпекать при температуре не выше 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Выложить массу на остывший корж, распределить.','https:https://st.vkuso.ru/data/cache/thumb/d3/b57a5f6c32548d3_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Растопить шоколад удобным способом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9352,'Приготовить для украшения постного шоколадного кекса глазурь. Перемешать какао с сахаром, добавить столовыми ложками воду, каждый раз перемешивая, последним влить кокосовое масло, если глазурь чуть постоит, то станет значительно гуще.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9352,'Пропитать коржи любым сиропом, оформить верх глазурью, дать кексу немного постоять, тогда он станет мягче и вкуснее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9353,'Одну морковку крупно натереть, обжарить вместе с нашинкованной луковицей, половину смеси превратить блендером в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9353,'Смешать фарш и обе половины зажарки, добавить яйцо, сдобрить перцем и солью, вылепить котлеты, быстро обжарить с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9353,'Остальной лук разрезать на половинки и нашинковать, грибы – на четвертинки, морковь измельчить на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9353,'Обжарить сначала морковь с грибами, затем всыпать в сковороду лук, нарезанный кубиками болгарский перец, присолить, поперчить, перемешать, слегка обжарить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9353,'Залить полученным соусом котлеты, тушить под крышкой при слабом нагреве котлеты в луковом соусе до тех пор, пока лук не станет полностью мягким.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9354,'Измельчить в комбайне, замоченный с ночи инжир, добавить мед, влить половину нормы сока лимона, перемешать, включить прогреться духовку (190 градусов будет достаточно).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9354,'В объемной миске перемешать  миндальную муку, овес, рисовую муку, разрыхлитель, соль и соду. Влить миндальное молоко, сок лимона, положить цедру, миндальное масло, добавить ваниль, кокосовый сахар, половину овса, тесто тщательно перемешать, тесто разделить на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9354,'Разложить тонким слоем на выстланный пергаментом противень одну часть, разровнять пальцами с небольшим нажимом, покрыть основу инжирным пюре, а сверху распределить оставшееся тесто, слегка прижать, и опять – пюре, присыпать верх стружкой кокоса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9354,'Выпекать мюсли из инжира минут 25, достать, дать хорошо остыть, нарезать на полоски очень острым ножом, хранить в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Довести воду с уксусом до кипения, припустить в нем кочан капусты, вынуть его сразу поместить в очень холодную воду для сохранения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Кочан «раздеть», снять мягкие листья, как только листья перестанут легко сниматься, опустить его обратно в кипяток и продолжить снимать листья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Мясо и лук прокрутить на мясорубке сквозь мелкую решетку, морковку очень мелко порубить в блендере и обжарить почти до готовности с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Объединить с фаршем овощи и сырой рис, всыпать измельченную зелень, приправить перцем и солью, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Завернуть с небольшим усилием фарш в листы капусты, уложить голубцы с мясом в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9355,'Перемешать все ингредиенты для подливки и залить голубцы, тушить примерно час до полной готовности блюда.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Соединить муку, сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Дрожжи растворить в воде с маслом, перелить в смесь из муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Замесить тесто. Если необходимо, насыпать чуть-чуть муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Выложить тесто в посуду, накрыть пленкой, чтобы оно поднялось.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Вымесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Разделить тесто пополам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Обе части раскатать, намазать растопленным маслом. Можно положить чеснок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Свернуть рулет.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Сделать смесь для обмакивания. В растопленное сливочное масло насыпать травы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Порезать рулеты на небольшие куски. Обмакнуть их в смесь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Разложить кусочки по формочкам. Подождать, пока булочки подойдут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9356,'Готовить 20-25 минут, соблюдать температуру 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Порезать масло на кубики (3 кубика оставить для карамели).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Насыпать в масло сахар, муку, 1/2 маленькой ложки соли, перемешать блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Высыпать получившуюся смесь в форму, утрамбовать, равномерно распределить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Отправить на 20 минут в духовку, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Приготовить карамельную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Положить в сковороду оставленные куски масла, налить 2 банки сгущенки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9357,'Готовить, пока не образуется густая карамельная масса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9358,'Вымыть печень, убрать пленку, порезать на крупные куски.','https:https://st.vkuso.ru/data/cache/thumb/96/dd695dd63b1f996_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9358,'Измельчить в блендере лук и печень.','https:https://st.vkuso.ru/data/cache/thumb/18/9196463d95e9f18_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9358,'Насыпать муку, добавить яйца и сметану.','https:https://st.vkuso.ru/data/cache/thumb/14/6d90084153ba014_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9358,'Все перемешать. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/ac/afd28a006c7fcac_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9358,'Нагреть масло на сковороде. Выложить ложкой печеночное тесто. Обжарить нежные печеночные котлеты со сметаной на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/a7/865fdf08d0b94a7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Приготовить тесто: смешать до однородности ½ молока, яйца, соль, разрыхлитель, сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Медленно насыпать муку, долить молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Добавить растительное масло, отставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Разрыхлитель можно заменить содой, погашенной в соке лимона. Вместо соды можно налить чуть-чуть кипятка. Чтобы блинчики были ажурными.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Замесить тесто, накрыть, отставить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Приготовить начинку: измельчить лук, нагреть на сковороде растительное масло. Чуть-чуть обжарить лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Положить фарш, накрыть крышкой, готовить на тихом огне, помешивая.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Если фарш очень сухой, то добавить несколько ложек воды.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Посыпать специями, солью. Готовить 25 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Измельчить фарш блендером.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Приготовить блины без масла.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9359,'Положить в блинчики начинку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9360,'Наколоть на шпажку кусочки маршмеллоу.','https:https://st.vkuso.ru/data/cache/thumb/1b/b3ded5981d0bd1b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9360,'Нагреть на открытом пламени. При нагревании маршмеллоу увеличится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9360,'Когда маршмеллоу станут больше, зажать их между печеньями. Так соединить все печенья.','https:https://st.vkuso.ru/data/cache/thumb/da/cd3f40c05fd78da_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9360,'Одним концом окунуть в растопленный шоколад, посыпать стружкой кокоса или кондитерской посыпкой.','https:https://st.vkuso.ru/data/cache/thumb/41/338653492070041_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9361,'Растереть сахарную пудру с мягким маслом и яйцом, постепенно ввести муку замесить достаточно плотное тесто, сформировать шарики, обернуть каждый в пленку, положить в холодильник минимум на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9361,'Очищенные от кожуры яблоки порезать на дольки, окропить соком лимона, присыпать сахаром с корицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9361,'Раскатать достаточно охлажденное тесто в круг, замотать на скалку, перенести в форму, прижать с небольшим усилием ко дну и бортикам, срезать выступающие края, наколоть несколько раз тесто вилкой, разложить ломтики яблок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9361,'Поместить открытый яблочный пирог на полчаса в духовку, погретую не выше 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Измельчить фрукты.','https:https://st.vkuso.ru/data/cache/thumb/88/1465374a995a088_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Насыпать сахар, добавить йогурт.','https:https://st.vkuso.ru/data/cache/thumb/ee/67844b5e6f085ee_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Порезать моцареллу на кусочки, каждый отдельно нагреть 20 секунд в микроволновой печи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Слить выделенную сыворотку. Собрать сыр в комок.','https:https://st.vkuso.ru/data/cache/thumb/13/02c5985a016c413_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Раскатать скалкой. В центр положить фруктовую начинку.','https:https://st.vkuso.ru/data/cache/thumb/90/c4068d6437d3690_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Кончики собрать в виде мешочка.','https:https://st.vkuso.ru/data/cache/thumb/ab/d07607cabcd37ab_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9362,'Можно подавать фруктовый салат в мешочке Моцареллы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Растереть масло и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Насыпать муку. Растереть в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Вбить яйца, посолить. Замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Отправить на 30 минут в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Распределить тесто в форме 20 на 30 сантиметров. Сделать проколы вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Отправить на 30 минут в холод. Готовить 15 минут, соблюдать температуру 180 градусов. Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Соединить сок трёх лимонов, малиновое пюре (для получения пюре малину протереть через сито), сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Вбить яйца, добавить цедру от двух лимонов. Размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Насыпать муку, размешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Налить начинку на тесто.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Готовить 30-35 минут при той же температуре. Остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9363,'Можно подавать пирог с лимонно-малиновой начинкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Добавить фарш, обжаривать 5-7 минут, время от времени помешивать и разбивать фарш, чтобы не было комков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Измельчить в блендере томаты, вылить в массу. Готовить 15-20 минут. Посолить.','https:https://st.vkuso.ru/data/cache/thumb/d1/53c49b0504cdcd1_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Подойдут помидоры и свежие, и консервированные – главное измельчить их.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Намазать форму сливочным маслом, посыпать сухариками.','https:https://st.vkuso.ru/data/cache/thumb/a3/f9bc67ab7c8b6a3_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Отваривать макароны приблизительно 5 минут в соленой воде.','https:https://st.vkuso.ru/data/cache/thumb/e1/b07add5aa5319e1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Переложить на дуршлаг, промыть водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Осторожно выложить 1/2 часть макарон в форму.','https:https://st.vkuso.ru/data/cache/thumb/fb/2d7dfe70905bdfb_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Сверху положить фарш в томате, посыпать тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/17/356dd8d19103a17_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Сделать соус бешамель: растопить сливочное масло на сковороде. Насыпать муку, осторожно растереть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Медленно налить молоко, перемешать, чтобы не было комков.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Посыпать молотым мускатным орехом, перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/3a/24c2711f3b95a3a_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Вместо соуса можно использовать молочно-яичную смесь.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Положить на начинку остальные макароны.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Залить соусом, присыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/6a/0e6cfce099caf6a_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9364,'Отправить на 20 минут в духовку, соблюдать температуру 200 градусов. Получается вкусная запеканка из макарон и фарша с соусом бешамель.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Измельчить крекеры в крошку, используя кухонный комбайн.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Положить топленое масло, насыпать соль, сахар. Размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Нагреть духовку до 290 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Взбить муку, сыр, цедру, сахар при помощи миксера. Положить яйца, ваниль. Медленно взбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Переложить массу в форму, смазанную маслом, утрамбовать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Готовить в духовке 12-15 минут. Достать, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Приготовить начинку: растопить шоколад на водяной бане.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'В емкости соединить ванилин, сливочный сыр, сахар. Взбить до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Насыпать какао-порошок. Размешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'В смесь влить растопленный шоколад. Взбить до однородности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Распределить начинку по основе, отправить на ночь в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Крем готовить непосредственно перед подачей.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Взбить белки, медленно насыпать ванильный сахар и сахарную пудру. Взбивать крем 20-25 минут. Крем не должен быть жидким.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Выложить крем на охлажденную начинку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9365,'Можно подавать сливочный тарт с шоколадной начинкой и белковым кремом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Постелить фольгу на противень, нагреть в духовке до 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Вымыть батат, отрезать с двух сторон верхушки. Порезать на тоненькие дольки, не срезая кожуру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Обвалять в смеси мускатного ореха, куркумы, оливкового масла, кукурузного крахмала.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Положить слоем на горячий противень, оставляя между кусочками место. Готовить 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/b0/0182750a4518cb0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Срезать с лайма цедру, измельчить, соединить с молотыми сухарями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Порезать филе трески на кусочки по 5 сантиметров, обвалять в панировке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Положить на бумагу для выпечки, побрызгать соком лайма, оливковым маслом, готовить 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/67/86c431dd938cb67_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Во время приготовления рыбы и батата, сделать Гуакамоле.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Разрезать авокадо пополам, убрать косточки, срезать кожуру.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Срезать кожуру с огурца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Измельчить огурец и авокадо при помощи блендера или мелко натереть.','https:https://st.vkuso.ru/data/cache/thumb/1c/15592882687781c_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Добавить по вкусу сок лайма и соль.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9366,'Подавать фиш энд чипс с соусом Гуакамоле на большой тарелке.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Замесить тесто: соединить муку, воду, яйцо, желтки, соль. Отправить в темное место на 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Взять продукты для начинки: тимьян, базилик, моцареллу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9879,'Влить в кастрюлю воду, добавить уксус, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Распределить на нем равномерно шарики, накрыть вторым пластом. Используя формы, вырезать равиоли.','https:https://st.vkuso.ru/data/cache/thumb/41/da744006bdb0641_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Варить 5-6 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Положить равиоли на сковороду, налить сливки, соус песто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Выпаривать сливки, пока соус не станет густой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9367,'Подавать с кусочками моцареллы, украсить тимьяном.','https:https://st.vkuso.ru/data/cache/thumb/28/c0327cc0a39a928_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Раскатать слоеное тесто слоем в 1 миллиметр, порезать на полоски 2,5 на 25 сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Обернуть вокруг специального конуса, слегка растягивая тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Делать витки внахлест.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Не доходить до конца 1 сантиметр, плотно закрепить ленту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Готовить трубочки 12-15 минут, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Снять с конуса, чтобы не отсырели. Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Сделать крем: соединить сахар и воду, довести до кипения, периодически помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Сделать огонь меньше, варить до 120 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Когда закипит сироп, взбить белок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Насыпать ваниль, взбивать, пока сироп не будет готов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Капнуть в белки сок лимона, налить тоненькой струйкой горячий сироп.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Взбивать крем, пока не остынет.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Наполнить трубочки кремом, используя кондитерский мешок или ложку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9368,'Перед подачей посыпать слоеные трубочки с белково-ванильным кремом сахарной пудрой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Подготовить продукты. Срезать с бородинского хлеба корку, порезать на бруски по 1-1,5 сантиметра в толщину и по 8-10 сантиметров в длину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Намазать растительным маслом. Посолить.','https:https://st.vkuso.ru/data/cache/thumb/03/2eebb37d2098d03_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Запекать в духовке 10-12 минут, соблюдать температуру 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/b6/4a25ceb1217acb6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Намазать хлеб чесночным маслом.','https:https://st.vkuso.ru/data/cache/thumb/a0/d40ce1cd6bdcea0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Чтобы сделать чесночное масло, нужно измельчить в блендере или мелко порезать зелень, чеснок, соединить с растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Выложить гренки на тарелку.','https:https://st.vkuso.ru/data/cache/thumb/cd/37a5a2d25ee91cd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9369,'Подавать бородинские гренки с чесночным маслом в духовке с чесночным соусом, салом, овощами, порезанными на бруски.','https:https://st.vkuso.ru/data/cache/thumb/17/0f24bd635e58f17_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Промыть рис, залить водой, отставить на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Слить воду, переложить рис в кастрюлю с водой (на стакан риса полтора стакана воды).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'На большом огне довести до кипения, затем готовить на маленьком огне, пока вода не впитается в рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Выключить плиту, отставить на 15 минут, накрыв крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Соединить сахар, рисовый уксус и соль, поставить на огонь. Готовить до растворения сахара, убрать с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Тоненькой струей, помешивая, налить заправку в рис. Подождать, пока рис остынет.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Порезать огурец, авокадо и рыбу на длинные тоненькие ломтики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Соединить рисовый уксус и воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Положить лист нори на бамбуковый коврик, чтобы гладкая сторона была внизу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Намочить руки в уксусе, разбавленном с водой, положить чуть-чуть риса на лист нори. Распределить внизу листа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'На рис положить начинку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Отрезать часть водоросли без риса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Краешек нори намочить уксусом, разбавленным с водой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Осторожно свернуть ролл, используя бамбуковый коврик.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9370,'Подровнять края ролла, порезать закрытые роллы с семгой, авокадо и огурцом на порции.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Подготовить продукты. Измельчить лук. Вымыть сухие грибы, замочить на 15-20 минут в кипятке. Порезать. Рис не промывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Нагреть оливковое или сливочное масло, чуть-чуть обжарить лук с чесноком. Убрать чеснок, он больше не понадобится.','https:https://st.vkuso.ru/data/cache/thumb/29/81f8f61980f2429_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Высыпать рис порциями, помешивая, готовить минуту, чтобы рис впитал масло.','https:https://st.vkuso.ru/data/cache/thumb/1f/0574579562f0b1f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Налить вино, непрерывно мешать. Рис должен впитать вино.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Налить порциями горячий бульон. Добавить несколько половников бульона, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/bd/f39938b35c4a1bd_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Когда бульон впитается, налить еще бульон и так, пока не останется ½ бульона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Положить грибы, добавить бульон, размешать.','https:https://st.vkuso.ru/data/cache/thumb/ab/85c7ca94d52adab_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Когда бульон закончится, положить 100 грамм сыра, посыпать перцем, солью, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/19/3fb6ba2983b5a19_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9371,'Посыпать японское ризотто с грибами шиитаки остальным сыром, можно положить зелень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Разрезать грудки вдоль, чтобы получилось 4 куска. Чуть-чуть отбить, посыпать солью, смазать бальзамическим соусом, посыпать перцем, майораном. Положить кусочки друг на друга, отставить мариноваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Приготовить начинку: порезать соломкой чеснок, лук, морковь. Если фасоль в замороженном виде, то промыть теплой водой, дать чуть-чуть просохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Обжарить овощи на сильном огне. Посыпать солью.','https:https://st.vkuso.ru/data/cache/thumb/5c/7c8bda7b9ea7d5c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'На каждый кусочек мяса положить начинку, свернуть плотный рулетик.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Завернуть беконом, положить в форму, застеленную фольгой.','https:https://st.vkuso.ru/data/cache/thumb/66/c064b78d409eb66_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Отправить в духовку на 30 минут, соблюдать температуру 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9372,'Подавать куриные рулеты в беконе с фасолью горячими.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9373,'Взбить в пюре с помощью блендера свежие или размороженные ягоды малины, очищенные бананы, молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9373,'Всыпать по вкусу молотую корицу. Налить малиново-банановый смузи в бокалы, посыпать корицей и украсить целыми ягодами малины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Мелко натереть сыр.','https:https://st.vkuso.ru/data/cache/thumb/21/0d4c9f678027421_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Посыпать перцем, солью, вбить яйца, размешать.','https:https://st.vkuso.ru/data/cache/thumb/4b/f9b255b8f7d4d4b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Измельчить почищенный чеснок, добавить в тесто, насыпать муку.','https:https://st.vkuso.ru/data/cache/thumb/cd/fd825f18364a3cd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/c7/09f55c2f11945c7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Сделать шарики.','https:https://st.vkuso.ru/data/cache/thumb/dc/a0830e43c6b4edc_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Обвалять в муке.','https:https://st.vkuso.ru/data/cache/thumb/eb/01b25536f8e6eeb_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Положить на горячую сковороду, готовить на растительном масле до появления корочки.','https:https://st.vkuso.ru/data/cache/thumb/f2/dcf7808461c89f2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Положить на бумажное полотенце, чтобы впитался жир.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Проткнуть шарики зубочисткой, выложить на тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9374,'Можно подавать сырные чесночные шарики на закуску.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Для приготовления крема в небольшом количестве молока развести пшеничную муку и кукурузный крахмал. Остатки молока довести до кипения, добавить ром и сахарный песок, влить смесь с мукой, варить до загустения, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Готовый заварной крем остудить, добавить мягкое сливочное масло, взбить до побеления, масса должна быть плотной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'С помощью кофемолки перемолоть очищенные грецкие орехи и печенье. Добавить щепотку корицы, муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'На листе пергамента нарисовать четыре круга с помощью блюдца, перевернуть бумагу на другую сторону, положить на противень, смазать маслом и посыпать мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Взбить в плотную пену белки, постепенно, порциями, всыпать сахарный песок. Осторожно перемешать с сухой смесью, выложить полученное тесто на нарисованные круги, разровнять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Печь в течение 10 минут при температуре 180 градусов, снять с пергамента, полностью остудить. Коржи промазать кремом, поставить на ночь в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Верх торта полить сахарной глазурью, ею же смазать бока, посыпать рублеными орехами или печеньем. С помощью темной, шоколадной, глазури нарисовать круги, провести ножом к центру, имитируя паутину.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9375,'Снова поставить мини-торт «Эстерхази» в холодильник, чтобы застыла глазурь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Желтки отделить от белков, последние взбить, постепенно добавляя сахар. Масса должна получиться плотной. Отдельно взбить оставшиеся желтки с сахаром, до побеления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Отжать огурцы, положить в емкость мясом вместе с зеленью, помидорами.','https:https://st.vkuso.ru/data/cache/thumb/9a/2af7bbf4cadfd9a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Пшеничную муку просеять и смешать с картофельным крахмалом, ванилином. Соединить белковую и желтковую массы, муку, перемешать до однородности, осторожно, смесь не должна осесть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Форму для выпекания среднего диаметра выложить пергаментом, влить полученное тесто. Печь при температуре 180 градусов, до готовности. Корж вынуть их духовки, остудить и разрезать на три части по горизонтали.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Для приготовления крема вскипятить молоко, еще столько же молока вылить в другую емкость, всыпать пшеничную муку, перемешать до однородного состояния, в смеси не должно быть комочков, вылить в кипящее молоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Довести крем до кипения, постоянно помешивать, поварить в течение трех-пяти минут и снять с огня. Добавить поломанный кусочками белый шоколад, перемешать. Шоколад должен растаять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Остудить заварной крем до комнатной температуры, помешивать, чтобы не образовалась корочка. Взбить массу с помощью миксера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Отдельно, также с помощью миксера, взбить мягкое сливочное масло, всыпать сахарную пудру, ванилин из пакетика. Еще раз взбить миксером, добавить заварной крем, снова взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Пропитать выпеченные коржи компотом от консервированных ананасов, промазать получившейся массой и положить кусочки ананасов в любом порядке, они должны оказаться в толще крема.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9376,'Верх торта «Ананасовый» также украсить нарезанными ананасами, покрыть кремом, намазать бока.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Просеять муку в большую емкость.','https:https://st.vkuso.ru/data/cache/thumb/8d/523fe2e0cfa548d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Растворить в воде сахар и соль.','https:https://st.vkuso.ru/data/cache/thumb/b0/18ff50707e40ab0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Сформировать в муке лунку, налить полученный раствор, растительное масло, водку.','https:https://st.vkuso.ru/data/cache/thumb/2f/f5ebac405a2d92f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Вымесить тесто, завернуть в полиэтилен, отставить на час при комнатной температуре.','https:https://st.vkuso.ru/data/cache/thumb/88/b0cac83e7103388_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Приготовить начинку: посыпать перцем и солью фарш, положить зелень.','https:https://st.vkuso.ru/data/cache/thumb/43/5db3d1b6a7e7e43_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Раскатать тесто при помощи скалки до толщины 3 миллиметра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Положить начинку.','https:https://st.vkuso.ru/data/cache/thumb/af/63d23b927ac96af_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Сложить тесто на две части, хорошо защипнуть края, чтобы в процессе жарки не вытекла начинка.','https:https://st.vkuso.ru/data/cache/thumb/29/002baddfd14d829_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Чебуреки пожарить на масле.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9377,'Можно подавать чебуреки с мясом в хрустящем тесте.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Тонкими полукольцами нарезать красный репчатый лук. Если он острый, то можно положить нарезку на две минуты в горячую воду, затем откинуть на сито или дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Сладкий болгарский перец очистить от семян и измельчить соломкой. Нежирную говядину отварить в подсоленной воде в течение часа или полутора, остудить, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Из перца чили также удалить семена и очень мелко порубить, чеснок пропустить через пресс. Слить жидкость от консервированной красной фасоли, промыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Добавить лук, говяжье мясо, оба вида перцев, порубленную зелень кинзы, обжаренные и нарубленные грецкие орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Посолить салат с фасолью, говядиной и орехами по вкусу, добавить молотый черный перец, приправу хмели-сунели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9378,'Для заправки перемешать оливковое масло и винный уксус, залить массу и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9379,'Протереть творог, в нем не должно быть комочков. Добавить ванилин, вбить по одному яйцу, каждый раз массу хорошо перемешивать. Всыпать сахарный песок, по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9379,'Влить ром, всыпать манную крупу, перемешать. Влить молоко, всыпать разрыхлитель, сухофрукты: изюм, чернослив, курагу, финики. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9379,'Готовую основу для запеканки оставить на час, для набухания манки. Выложить массу в смазанную маслом форму, намазать густой сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9379,'Выпечь творожную запеканку при температуре 180 градусов, до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9380,'С куриной тушки срезать все мясо, порезать на кусочки небольшого размера. Смешать мясо с рубленой петрушкой, чесночным порошком, сушеным укропом, смесью перцев, молотой паприкой, морской солью и сухим желатином.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9380,'У коробки из-под сока отрезать верхнюю часть, оставить, как крышку. Сложить мясо, прижать, масса должна уплотниться, «крышку» закрыть и заклеить скотчем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9380,'Налить в большую кастрюлю воду, поставить коробку, варить в течение полутора часов с самого начала закипания. Огонь выключить, остудить, поставить коробку в холодильник на два-три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9380,'Когда мясная масса застынет – коробку разрезать и выбросить, готовую рубленую ветчину  из курицы подать, нарезав на ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9381,'Пищевую пленку разрезать на квадратные кусочки размером 15х15 сантиметров. Пленку разложить на доске, смазать оливковым маслом, выложить в небольшие пиалы, вылить по яйцу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9381,'Посолить их сразу или оставить на потом. Концы пленки собрать вместе, завязать узелком, можно обвязать ниткой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9381,'В емкости вскипятить воду, огонь убавить, опустить мешочки. Варить в течение пяти-семи минут до нужной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9381,'Яйца-пашот «Мешочки» вынуть, снять пищевую пленку, выложить на блюдце.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9382,'Сливочное масло довести до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9382,'Взбить его с помощью венчика, всыпать сахарную пудру, перемешать, добавить ванилин и какао, растереть массу ложкой до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9382,'Переложить шоколадное масло в форму из силикона и положить в морозильную камеру на 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Для приготовления теста перемешать пшеничную муку, соль, корицу. Добавить крахмал, но можно обойтись и без него.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Отдельно взбить сахарный песок с яйцами, масса должна немного посветлеть и увеличиться в объеме. Можно сделать это вручную или с помощью миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Добавить к яичной смеси мучную смесь, продолжать взбивать до получения однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Груши или яблоки очистить от кожуры, нарезать пластинками или кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Разъемную форму сбрызнуть растительным маслом, присыпать мукой. На дно выложить яблоки, залить тестом, оно должно полностью покрыть фрукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Поставить шарлотку в духовку на 30 или 40 минут, верх должен подрумяниться. Проверить готовность спичкой или зубочисткой, она должна остаться сухой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9383,'Шарлотку остудить, перевернуть, снять форму, посыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Сухие дрожжи развести в небольшом количестве теплой воды, оставить на 10 минут для набухания. Смешать пшеничную муку с солью, добавить дрожжи и остатки воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Замесить тесто, оно должно получиться немного липким. Положить тесто в емкость, смазанную маслом, накрыть влажной тканью и поставить в тепло на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Рабочую поверхность присыпать мукой, раскатать тесто в прямоугольную лепешку. Нанести на нее Нутеллу, края не смазывать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Плотно скрутить лепешку в рулет, положить на застеленный бумагой противень. Присыпать мукой. Скрутить рулет в форме косички. Снова закрыть заготовку полотенцем, оставить на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Печь в течение 20 минут при температуре 190 градусов, затем температуру увеличить, прогревать пять-семь минут до образования коричневатой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9384,'Косичку с нутеллой достать из духовки и охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9385,'Вымыть и почистить овощи, положить на решетку, запечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9385,'Пюрировать до однородности. Для этого можно использовать или вилку, или блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9385,'Положить чеснок, посыпать специями, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9385,'Чтобы соус барбекю из перца и моркови с табаско  надолго сохранился, переложить его в предварительно простерилизованные банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Отварить куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Остудить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Огурцы порезать на длинные полоски. Поместить в емкость, посыпать солью. Отставить.','https:https://st.vkuso.ru/data/cache/thumb/d0/a4a6c4b9c94a3d0_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Положить в емкость поджаренные семена кунжута, насыпать соль, сахар, добавить кунжутное масло, соевый соус, рисовый уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Порезать помидоры на дольки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Измельчить кинзу и зеленый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9386,'Разделить остывшую курицу на волокна, положить в посуду с заправкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9879,'Смесь довести до кипения, затем огонь уменьшить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Вбить к грибам яйца, посыпать перцем, солью. Готовить 3 минуты, помешивая лопаткой, чтобы масса схватилась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Добавить сыр, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Нафаршировать полученной смесью тушки кальмаров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Заколоть зубочистками. Можно добавить рис.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Намазать кальмаров растительным маслом, положить в формочку, отправить на 10-15 минут в духовку, соблюдать температуру 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9387,'Порезать кальмары фаршированные яично-грибной начинкой на ломтики, подавать, как закуску.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Измельчить печенье до состояния крошки, поделить пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Одну часть размешать с маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Разложить массу в формочке. Уплотнить, отправить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Взбить сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Насыпать сахарную пудру, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Распределить большую часть крема на основе десерта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Посыпать крошкой, чуть-чуть уплотнить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Распределить сверху крошки пудинг.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Покрыть десерт кремом, используя кондитерский мешок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Украсить шоколадной крошкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9388,'Отправить шоколадную лазанью со сливочным сыром на 2 часа в холод.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Сливочное масло растопить и немного охладить. Пшеничную муку и соль просеять, сделать в центре углубление, влить сырой желток и растопленное масло. Постепенно влить воду, вымесить однородное тесто вручную или с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Тесто переложить на рабочую поверхность, месить руками до готовности, оно должно стать мягким и податливым. Положить массу в миску, дать постоять в течение часа для набухания клейковины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Творог выложить в сито или марлю, отцедить жидкость в течение получаса или больше, в зависимости от плотности творога. Смешать изюм и абрикосовый ликер или ром, смешать и отставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Взбить миксером до пены сахарный песок, мягкое сливочное масло, яйцо и оставшийся желток, всыпать цедру лимона или апельсина. Смесь добавить в творожную массу вместе с кукурузным крахмалом и изюмом, перемешать. Оставшееся масло растопить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Кухонное полотенце посыпать мукой, раскатать тесто в лепешку и растянуть его очень тонко, до просвечивания. Смазать растопленным маслом с помощью кисточки, края оставить сухими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Посыпать панировочными сухарями, ровным слоем, распределить творог, также оставляя края свободными. Боковины теста подвернуть внутрь, поверх начинки. Начиная с ближайшего края скатать изделие в рулет, помогать себе полотенцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9389,'Заготовку выложить на застеленный бумагой противень, смазать маслом, печь австрийский штрудель с творогом в течение получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9390,'Рыбу разделать на филе, разрезать каждое на три куска, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9390,'Отдельно приготовить овощную обжарку из репчатого лука, моркови, положить в форму для выпечки, скумбрия – сверху.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9390,'Натереть сыр на крупной терке, смешать с майонезом, сметаной, можно добавить немного воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9390,'Залить рыбу, можно посыпать зеленью укропа. Поставить скумбрию с овощами в нагретую духовку на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9391,'Отварить макароны, слить воду, выложить их на дно формы для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9391,'Помидоры нарезать тонкими ломтиками, выложить поверх пасты. Натереть твердый сыр, посыпать запеканку, поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9391,'Очистить зубчики чеснока, нарезать крупными ломтиками, уложить на сыр, покрыть блюдо тонким слоем майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9391,'Печь запеканку из макарон до готовности в духовом шкафу в течение 10–20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Налить в кастрюлю оливковое масло, обжарить на нем целые, очищенные, зубчики чеснока. Добавить веточку свежего базилика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Удалить чеснок и всыпать размороженный зеленый горошек. Залить смесь куриным бульоном, горох должен быть покрыт полностью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Массу накрыть крышкой, огонь убавить, варить в течение 20 минут. По вкусу добавить соль и молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Очистить мелкие креветки, выложить на противень. Порубить зелень петрушки, перемешать с оливковым маслом, перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Этой смесью полить креветки, посыпать панировочными сухарями. Поставить под гриль на несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9392,'Суп-пюре из зеленого горошка перемолоть в блендере, подать с горячими креветками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Просеянную пшеничную муку порубить со сливочным маслом, должна получиться мелкая крошка. Пересыпать ее в миску, добавить сахарный песок, разрыхлитель, щепотку соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Отделить белки от желтков, первые положить в холодильник, вторые добавить в крошку. Замесить тесто, лучше сделать это руками, собрать в ком. Сформовать шар, завернуть в пищевую пленку, поставить на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Смородину в замороженном виде выложить в дуршлаг, окатить кипятком, через десять минут рассыпать на бумажные полотенца, ягоды должны немного обсохнуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Белки из холодильника взбить в плотную пену, добавить порциями оставшийся сахар, разрыхлитель, картофельный крахмал и муку. Аккуратно вмешать подсохшие ягоды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Края и дно разъемной формы смазать сливочным маслом. Тесто вынуть из холодильника, распределить по всей внутренней поверхности формы, сделать бортики. Выложить смородиновую начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9393,'Печь пирог со смородиной в течение 25–30 минут, сначала при температуре 180 градусов, в середине выпечки огонь убавить до 150 градусов. Блюдо остудить при комнатной температуре и подать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9394,'Рульки разморозить, вымыть, обсушить полотенцем. Налить воду в кастрюлю, положить очищенный репчатый лук, морковь, корень сельдерея, перец-горошек. Добавить несколько гвоздик и лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9394,'В кипящий бульон положить рульки, варить на тихом огне в течение часа или полутора, до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9394,'Для приготовления маринада развести мед в светлом пиве, добавить острый перец чили, соль – по вкусу. Можно добавить немного томатной пасты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9394,'Отваренные рульки опустить в маринад, дать постоять в течение нескольких часов или оставить на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9394,'Противень застелить бумагой для выпечки, выложить рульки по-польски, запечь в течение часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9395,'Залить кипятком миндаль, когда вода остынет – орехи очистить от кожицы. Немного подсушить ядрышки в духовом шкафу при 100 градусах в течение 10–15 минут. Миндаль не должен зарумяниться. Орехи измельчить в муку вместе с сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9395,'В посуду с толстым дном влить воду, положить сахар, нагреть сироп на среднем огне до температуры 112 градусов. Муку из миндаля залить горячим сиропом, продолжать измельчать с помощью комбайна. Можно добавить немного воды, если масса получилась слишком густой, сахарную пудру – если слишком жидкая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9395,'Также можно положить пищевые красители или ароматизаторы. Если красители сухие, то перед добавлением их нужно развести в небольшом количестве воды. Вымесить получившуюся марципановую массу, можно добавить сахарную пудру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9396,'В глубокую миску разбить яйца, всыпать сахар, взбить до побеления смеси. Растворить мед в двух ст.л. воды, добавить в миску вместе с  гашеной содой и как следует взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9396,'Смешать  какао и просеянную муку , добавить 1 стакан рубленных  орехов, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9396,'Разделить полученное жидкое тесто на три части, испечь из каждой по коржу, используя бумагу для выпечки,  при температуре около 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9396,'Взбить крем из масла с ванилью и сгущенкой. Промазать кремом охлажденные коржи, присыпать торт «Золотой ключик» со сгущенным молоком оставшимися рублеными орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Поделить сливочный сыр пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Положить ½ сыра в посуду, побрызгать соком лимона, положить измельченный укроп, лук, добавить соль, каперсы, молотый перец. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a7/80c174972280ea7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Намазать ломтик хлеба сырной массой. Положить сверху лосося, порезанного на тоненькие ломтики.','https:https://st.vkuso.ru/data/cache/thumb/83/706db58937bc483_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Выложить сверху огурец, порезанный на кружки.','https:https://st.vkuso.ru/data/cache/thumb/58/b33ab945e1c9a58_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Повторить все слои, кроме верхнего ломтика хлеба.','https:https://st.vkuso.ru/data/cache/thumb/24/344e68800f07524_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Намазать со всех сторон оставшимся мягким сливочным маслом.','https:https://st.vkuso.ru/data/cache/thumb/6a/b1e5af0190b5b6a_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9397,'Украсить бутербродный торт с копченым лососем и сливочным сыром укропом, каперсами.','https:https://st.vkuso.ru/data/cache/thumb/1d/ac4538e7a9f651d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Сделать клецки. Мелко натереть сыр, вбить яйцо, положить мягкое сливочное масло. Посыпать перцем, солью, размешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/e6/81db93e76b87ee6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Подсыпать муку, добавить измельченную зелень, сделать тесто. Отправить в холод на 30 минут – тесто станет тверже, так как масло охладится. Можно оставить тесто в холодильнике на 2 часа.','https:https://st.vkuso.ru/data/cache/thumb/a3/7b1eb59c75f07a3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Достать тесто, сформировать шарики-клецки по 15-20 миллиметров в диаметре. После варки они увеличатся.','https:https://st.vkuso.ru/data/cache/thumb/c9/97cff52b7f4a1c9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Налить в кастрюлю 1,5-1,8 литров воды. Поставить на огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Почистить картофель, порезать на кубики, положить в кипящую воду.','https:https://st.vkuso.ru/data/cache/thumb/0c/bbfeb6ae997500c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'В это время приготовить заправку для супа: нагреть растительное масло, пассеровать 7-8 минут тертую морковь, измельченный лук и сельдерей. Положить порезанный сладкий перец, готовить 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/ea/849ed43d6258fea_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Когда картофель будет практически готов, положить заправку.','https:https://st.vkuso.ru/data/cache/thumb/65/cfa278eae833765_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Не спеша, положить клецки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Когда всплывут, накрыть крышкой и готовить 5-7 минут на тихом огне.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9398,'Можно подавать овощной суп с сырными шариками-клецками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Отварить спагетти, слить воду, оставив чуть-чуть отвара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Обжарить порезанную ветчину, положить в спагетти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Взбить масло, тертый сыр, яйца, оставленный отвар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Добавить в спагетти.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Посыпать приправами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9399,'Можно подавать Быструю пасту карбонара с ветчиной и яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9400,'Нарезать капусту на маленькие квадратики, натереть морковку, смешать с  куриным фаршем, вбить яйца, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9400,'Смешать томатную пасту, сметану, воду, подсолить, сдобрить черным перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9400,'Скатать фарш в шарики размером с мандарин, переложить в кастрюлю, влить соус, поставить голубцы ленивые из куриного фарша тушить примерно на треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Почистить овощи: морковь, лук, сельдерей, свеклу, болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Отправить в кастрюлю. Добавить перец горошком, лавровый лист, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Налить воду, готовить 60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Достать из бульона овощи, кроме свеклы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Порезать лук, крупно потереть сырую морковь и отваренную свеклу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Обжарить овощи на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Добавить томатную пасту и сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Положить в кипящий бульон картофель, порезанный на маленькие кубики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Спустя 5 минут положить нашинкованную капусту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Порезать шампиньоны, обжарить на растительном масле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Положить в суп зажарку, затем шампиньоны. Посыпать паприкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Готовить 5 минут, убрать с огня, дать настояться под крышкой пару минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9401,'Подавать постный борщ с шампиньонами и перцем в горячем виде, заправив холодной сметаной.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Порезать болгарский перец на кубики, измельчить чеснок и лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Обжарить на растительном масле несколько минут, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Положить томатную пасту, лавровый лист, паприку, помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Посыпать перцем, солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Довести до кипения, готовить 10-15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Насыпать сахар, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Убрать лавровый лист, вбить яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Накрыть крышкой, варить до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9402,'Подавать израильскую шакшуку с пряностями с измельченной петрушкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Перебрать грецкие орехи, чтобы удалить остатки скорлупы, перегородки, измельчить.','https:https://st.vkuso.ru/data/cache/thumb/54/1918055ef617354_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Порезать бананы на три части поперек, все на четыре части вдоль и опять поперек – на маленькие куски.','https:https://st.vkuso.ru/data/cache/thumb/fb/d4fa243e22e15fb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9879,'Сырое куриное яйцо вбить в чашку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'На сковороде растопить масло, мед. Положить бананы, обжарить на небольшом огне минут пять.','https:https://st.vkuso.ru/data/cache/thumb/56/3e6e8a75fe3b156_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'После этого насыпать орехи, выключить огонь, позволить смеси потушиться минут пять.','https:https://st.vkuso.ru/data/cache/thumb/a8/caac3d444f996a8_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Потереть на терке заранее охлажденный шоколад, разложить в 2 емкости, отправить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/7b/43e16f682fc707b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Опустить в теплую воду лист рисовой бумаги секунд на пятнадцать. Он должен стать мягким, гибким, но должна сохраниться упругость. Расстелить лист на полотенце, положить маленькую ложечку начинки, завернуть в виде конвертика, на четвертую сторону свернуть рулетиком.','https:https://st.vkuso.ru/data/cache/thumb/17/b1a123bf5b11117_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Таким же образом поступить с остальными листиками рисовой бумаги. Положить скрученные блины на гладкую поверхность, намазанную маслом. Блины очень липкие, поэтому к сухой поверхности они прилипнут, и будут рваться.','https:https://st.vkuso.ru/data/cache/thumb/a8/50b279c92ff9aa8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Оставшееся сливочное масло разогреть на сковороде, обжаривать блины с каждой стороны по шестьдесят секунд.','https:https://st.vkuso.ru/data/cache/thumb/fa/79c71bc73fc62fa_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9403,'Достать из холодильника тарелочку с шоколадом. Готовые блинчики обильно обвалять в шоколаде. Он сразу будет плавиться, поэтому в одной тарелке обвалять в жидком шоколаде. Выложить вьетнамские блинчики с бананами, орехами в шоколаде на сервировочной тарелке. Чуть-чуть остудить блины, когда шоколадная обливка схватится, посыпать стружкой из второй тарелочки.','https:https://st.vkuso.ru/data/cache/thumb/46/7cd9bd470524b46_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9404,'Три вида вырезки: свиную, говяжью и баранью, нарезать на кусочки, обжарить на раскаленной сковороде до готовности, крышкой не накрывать. Мясо не должно пересушиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9404,'Мелко нарезать очищенный лук и морковь, положить к мясу и потомить. Очистить и мелко нарезать баклажан, также добавить в мясо, прогревать до готовности. В блюдо добавить молотый черный перец, перец чили, паприку, соль по вкусу, перемешать и еще потушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9404,'Обжарить отдельно картофель, заранее очищенный и нарезанный мелкими кубиками. Один из лавашей нарезать лентами. В развернутый лаваш положить начинку, завернуть и завязать лентой в виде узелка. Печь в духовке при температуре 160 градусов в течение 20–30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Для приготовления французской меренги взбить сырые яичные белки с 250 г сахарной пудрой в плотную пену. Добавить остатки пудры, перемешать с помощью венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Меренгу выложить на бумагу для выпечки, придать форму двух кругов среднего диаметра. Печь при температуре 90 градусов в течение трех часов, фактически масса не печется, а сушится. Безе остудить в духовке, смазать в холодном виде растопленным на водяной бане темным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Для бисквита нагреть сырые куриные яйца с сахаром и ванилью. Лучше использовать семена из стручков. Температура смеси должна достигнуть 45 градусов, помешивать, затем взбить до образования легкой массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Осторожно вмешать, просеянную вместе с картофельным крахмалом, муку. Диаметр бисквитной лепешки должен быть на два сантиметра меньше, чем диаметр меренги. Печь в течение 15 – 20 минут при температуре 190 градусов. Готовность выпечки проверить с помощью зубочистки, она должна остаться сухой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Для крема довести молоко до кипения вместе с зернами ванили. Отдельно взбить сырое куриное яйцо с сахаром, масса должна стать густой и светлой. Всыпать крахмал. В смесь постепенно влить горячее молоко, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Крем перелить обратно в кастрюлю, прогревать на среднем огне. Довести до кипения, варить до загустения, помешивать. Вылить заваренный крем в миску, накрыть пищевой пленкой и остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Приготовить ванильный шантийи. В небольшом количестве воды замочить желатин на 15 минут. Немного сливок нагреть до кипения, добавить желатиновую массу, перемешать до растворения, в смеси не должно быть комочков. Охладить сливки, взбить с сахаром до плотности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'Смешать желатиновую смесь с заварным кремом и добавить сливки. Массу перемешать, делать это аккуратно, поставить в холодильник до момента использования.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9879,'Влить осторожно яйцо, через три минуты выловить шумовкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9405,'На безе с шоколадным слоем выложить шантийи, затем – бисквит, пропитанный сиропом из клубники, снова ванильный шантийи, безе, шоколадным слоем вниз. Остатками намазать бока тorta «Monia», поставить его на полчаса в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9406,'Вымыть куриные сердечки, залить холодной водой с горошинами черного перца, поварить на тихом огне в течение 30–40 минут, пену снимать. Вынуть субпродукты на тарелку шумовкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9406,'Два крупных клубня картофеля нарезать кубиками, положить в бульон вместе с лавровым листом и зеленым сельдереем, добавить сухой укроп. Поварить в течение получаса, огонь уменьшить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9406,'Две репчатые луковицы нарезать кубиками, спассеровать на топленом масле до готовности. Добавить натертую морковь, молотый кориандр, красный жгучий перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9406,'Сердечки нарезать соломкой, положить в обжаренные овощи и прогреть все вместе. Обжарку положить в бульон, варить суп «Сердечный» десять минут, затем посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9407,'Очистить картофель, нарезать равными брусочками, налить в чашу горчичное масло, положить картофель. Закрыть крышку, выставить режим «Жарка», готовить 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9407,'Открыть крышку и жарить еще 20 минут (через 10 минут посолить и добавить специи для супа). Итого, жареная картошка в мультиварке готовится полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Как можно лучше вымыть картофель и кабачки. Порезать кабачки на кружки по пять миллиметров в толщину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Порезать картофель на тоненькие кружочки, посыпать перцем, солью, зеленью. Вымыть перец, порезать тоненькой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Намазать формочку маслом. Положить ½ картофеля. Сверху слой кабачков, посыпать перцем, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Порезать лук на кольца, положить слоем вместе с перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'После положить бекон, порезанный на ломтики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Последний слой сделать из картофеля, посыпать сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9408,'Готовить картофель с кабачками, перцем и беконом минут 40, соблюдать температуру 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Куриную грудку отварить в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Рис промыть несколько раз, чтобы удалить лишний крахмал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Мясо вынуть, всыпать рис в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Очистить, нарезать репчатый лук мелкими кубиками, обжарить до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Добавить в обжарку томатную пасту, перемешать, влить немного куриного бульона, проварить под крышкой до готовности бульона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Куриное филе отделить от костей, нарезать мясо соломкой вдоль волокон, всыпать в кастрюлю с рисом. Заправить обжаркой с томатной пастой, варить на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9409,'Натереть чеснок, добавить в суп вместе с рубленой кинзой, лавровым листом, солью, перцем и хмели-сунели. Дать блюду постоять несколько минут и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Положить мясо в кастрюлю большого объема (4,5 литра) , залить водой почти до краев, поставить на плиту, прогревать до кипения, пену снимать.','https:https://st.vkuso.ru/data/cache/thumb/34/1674430fd179a34_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Через полчаса всыпать тщательно промытый рис. Еще раз довести до кипения, огонь уменьшить, варить мясо до готовности под крышкой.','https:https://st.vkuso.ru/data/cache/thumb/81/3755a8e7f390281_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Поставить на плиту сковороду, подлить растительное масло.','https:https://st.vkuso.ru/data/cache/thumb/ea/e5dc3bdea1843ea_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Обжарить крупно нарезанный репчатый лук до прозрачного состояния.','https:https://st.vkuso.ru/data/cache/thumb/9f/dabfe478514699f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Через две минуты положить нарезанный сладкий болгарский перец. Этот ингредиент необязателен, им можно пренебречь. Жарить все вместе еще полторы минуты.','https:https://st.vkuso.ru/data/cache/thumb/b9/808029b79f6f6b9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Добавить порезанные свежие помидоры или консервированные в собственном соку.','https:https://st.vkuso.ru/data/cache/thumb/54/a95353bfb691854_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Положить соус ткемали, томатную пасту, все перемешать и тушить еще три минуты.','https:https://st.vkuso.ru/data/cache/thumb/2a/2a05bce83f13e2a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Переложить обжарку в кастрюлю. Добавить хмели-сунели, лавровый лист, соль, черный молотый перец, кориандр.','https:https://st.vkuso.ru/data/cache/thumb/32/aedd48d9b448732_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Всыпать молотые грецкие орехи, оставшиеся специи, хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a1/4a13345c8e13ca1_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Добавить сахарный песок, довести суп до кипения, пену снять, кипятить харчо еще пять минут.','https:https://st.vkuso.ru/data/cache/thumb/08/f07baf16c9f0108_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9410,'Всыпать нарубленную зелень, огонь выключить, дать супу постоять полчаса.','https:https://st.vkuso.ru/data/cache/thumb/f5/1057dfd829ab1f5_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Очистить морковь и натереть на терке для моркови по-корейски или на обычной терке. Небольшой кусочек корня сельдерея очистить и также натереть, положить к моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Очистить репчатый лук, нарезать полукольцами, положить в небольшую тарелку. Обжарить на разогретом рафинированном растительном масле лук, он должен стать мягким и прозрачным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Добавить сельдерей и морковь, обжарить в течение 10 минут. Добавить томатную пасту, перемешать, жарить смесь еще 7–10 минут. Влить теплую кипяченую воду, уксус, всыпать перец, гвоздику, корицу, соль и сахар – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Прогреть в течение 15–20 минут, в конце приготовления добавить лавровый лист. Белую рыбу, хек или треску, разделать на филе с кожей, реберные кости удалить, куски посолить и обвалять в пшеничной муке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Сковороду разогреть на среднем огне, обжарить на растительном масле рыбу, с обеих сторон, до золотистой корочки. Выложить кусочки в сковороду с маринадом, поставить на тихий огонь, тушить блюдо под крышкой в течение 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9411,'Огонь выключить, оставить рыбу под овощным маринадом для остывания и настаивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9412,'Отварить в подсоленной воде куриное мясо, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9412,'Замороженную стручковую фасоль положить на три минуты в кипящую воду, она должна быть соленой. Затем погрузить на 30 секунд в холодную воду. Откинуть на дуршлаг, вода должна полностью стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9412,'Нарезать кубиками сладкий болгарский перец, красный или разноцветный. Обжарить до мягкости вместе с зубчиком измельченного чеснока на растительном масле. Остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9412,'Курицу нарезать кусочками, соединить с отваренными и нарезанными кубиками куриными яйцами, обжаркой из перца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9412,'Салат «Шедевр» заправить майонезом, соль–по вкусу. Поставить в холодильник на полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9413,'Растопить сливочное масло и немного остудить. Взбить яйца с сахаром, добавить смесь в масло вместе со сметаной. Просеять пшеничную муку, соединить с разрыхлителем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9413,'Всыпать сухие ингредиенты в жидкие, порциями замесить тесто. Оно должно быть пластичным. Можно добавить муку, если есть такая необходимость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9413,'Из теста скатать жгутики небольшого размера, сформовать калачики, выложить их на противень, смазанный сливочным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9413,'Печь в разогретой духовке в течение 15 минут при температуре 180 градусов. Сметанные калачики должны зарумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9414,'Смешать пшеничную муку, сахарный песок, разрыхлитель, соль и пищевую соду. Отдельно взбить сырое яйцо с помощью венчика, в пену, влить молоко, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9414,'Жидкую смесь влить в мучную, перемешать. Растопить сливочное масло и также влить в тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9414,'На сухой сковороде выпечь блинчики с одной стороны, должны появиться пузырьки. Затем перевернуть, прогреть в течение 40–50 секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9414,'Американские блинчики выложить на блюдо, полить сгущенным молоком или вареньем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'Свежие шампиньоны хорошо вымыть, нарезать ломтиками небольшого размера. Куриное филе также вымыть, нарезать кусочками. Натереть на крупной терке сыр, любого сорта, он должен легко плавиться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'Разогреть растительное масло в глубокой сковороде. Обжарить на сильном огне грибы, порциями, они не должны превратиться в кашу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'В той же сковороде обжарить куриное филе в течение пяти-семи минут. Мясо должно зарумяниться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'Добавить немного остывшие грибы, посолить, перемешать. Долить сливки, снова перемешать, убавить огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'Прогревать до загустения соуса, по вкусу его можно досолить и поперчить, добавить специи, довести смесь до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9415,'В начале кипения всыпать сыр, перемешать куриное филе с грибами и сыром, дать ему расплавиться. Снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Приправить тмином, перцем, присолить, обжарить минут 6-7 на слабом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9416,'Срезать лишнее сало, если оно есть, должен остаться тонкий слой. Расстелить его на доске, посолить и поперчить по вкусу, добавить тертую морковь, нарезанный пластинками чеснок. Можно добавить немного куриного мяса, нарезанного кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9416,'Свернуть в рулет, в середине не должно остаться свободное пространство. Плотно перевязать нитками или шпагатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9416,'Опустить рулет в кастрюлю с кипящей водой, варить на тихом огне в течение полутора часов под неплотно закрытой крышкой. При таком способе приготовления часть жира из сала вытопится и это будет уже другой продукт. Чтобы этого избежать, можно поступить по-другому.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9416,'Вариант: положить заготовку в пищевой пакет, плотно завязать, выгнать воздух, отварить в таком виде. В кастрюлю или в пакет также можно добавить лавровый лист и перец-горошек по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9416,'Готовое блюдо охладить, завернуть в фольгу, хранить рулет из сала в холодильнике, использовать по мере необходимости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9417,'Жирный творог хорошего качества протереть через сито, добавить сметану и соль, ванилин, сахарный песок, какао-порошок или шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9417,'Песочное или галетное печенье квадратной формы окунать в молоко и сразу выкладывать в три или четыре ряда на лист целлофана. Хорошо смазать творожной массой, в середину положить целый очищенный банан.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9417,'Крайние ряды печенья приподнять, сформовать шалаш. С торца банан можно оставить или залепить его начинкой. Домик поставить в холодильник для застывания. Затем достать, выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9417,'Для глазури растопить отдельно, в кастрюле, сливочное масло с добавлением молока, какао-порошка и сахара. Довести массу до кипения, варить две минуты, затем сразу залить домик.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9417,'Дать постоять час или два для застывания. Если использовались галеты, торт оставить на ночь, они дольше пропитываются.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Для приготовления крема взбить сырые яйца вилкой или венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Отдельно смешать сухие ингредиенты: сахарный песок, крахмал, соль. Постепенно влить молоко, помешивая, поставить на средний огонь, варить до загустения, смесь должна покипеть в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Добавить две столовые ложки массы в яйца, быстро перемешать. Перелить смесь обратно в кастрюлю, поставить на тихий огонь и дать покипеть минуту, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Снять крем с огня, добавить сливочное масло, ванилин. Остудить, затем поставить в холодильник, закрыв пищевой пленкой, чтобы не образовалась корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Растолочь печенье или несоленые крекеры в пакете, смешать полученную крошку с сахаром и растопленным маслом. Выложить массу ровным слоем на противень, поставить на 10–12 минут в духовку, печь при температуре 175 градусов. Должна образоваться золотистая корочка. Остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Выложить крошку в порционные креманки, придавить массу донышком бокала или стакана. Выложить крем, кружочки банана, верхний слой – взбитые сливки. Присыпать десерты крошкой, сбрызнуть карамелью, использовать готовый соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9418,'Повторить слои крема, бананов, сливок, крошки и карамели. Подать карамельно-банановый десерт с кремом к столу сразу или поставить в холодильник на три часа. При подаче украсить кружочком банана.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9419,'Куриные голени посолить и натереть «Русской» горчицей. Выложить в форму для запекания. Добавить чеснок и репчатый лук, нарезанный на восемь долек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9419,'Печь в течение 30–35 минут, добавить разрезанные на четыре части помидоры небольшого размера. Прогревать куриные ножки еще в течение 15–20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9420,'Готовое бездрожжевое тесто из магазина разморозить, раскатать. Разрезать лепешку на квадраты при помощи ножа. Для начинки очистить бананы и натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9420,'Выложить банановое пюре на тесто, сверху – по чайной ложке сахарного песка. Тесто сложить треугольниками, сделать на каждом по три надреза для выхода пара при нагреве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9420,'Противень застелить фольгой, выложить слоёнки с бананом, поставить в духовку, разогретую до 180 градусов, на 40 минут. Остудить выпечку и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9421,'Курицу обжарить в нагретом сотейнике. Удалить, в той же посуде обжарить картофель и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9421,'Вернуть курицу в сотейник, добавить оливки, веточки тимьяна, соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9421,'В отдельной посуде смешать белое вино и бальзамический уксус, мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9421,'Довести до кипения, огонь убавить, потомить курицу с картофелем еще в течение часа, до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9422,'Прямоугольную форму застелить пергаментом. Перемешать обычную и сладкую кокосовую стружку со сгущенным молоком, переложить в форму, разровнять. Охладить в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9422,'Черный шоколад растопить на водяной бане, немного охладить, намазать им кокосовую основу сверху, разровнять, поставить на пять-семь минут для охлаждения, шоколад должен застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9422,'Вынуть корж из основы, держать за края пергамента. Разрезать пополам, сложить вместе кокосовыми сторонами внутрь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9422,'Разрезать на квадраты небольшого размера, выложить кокосовые конфеты на блюдо или в гофрированные бумажные формочки, охладить и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9423,'Форму для выпечки смазать сливочным маслом. В блендере взбить крошки печенья с грецкими орехами в мелкую крошку. Пересыпать в миску, добавить сливочное масло, пшеничную муку, коричневый сахар, смешать массу вилкой до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9423,'Застелить бумагой противень, выложить полученную массу ровным слоем, поставить в духовку на 20 минут. В середине приготовления противень перевернуть. Готовую крошку достать и охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9423,'Для начинки смешать с помощью миксера белки с сахарным песком в течение трех минут. Влить сливки, взбивать еще шесть минут. Добавить сливочный сыр, лимонный сок, массу перемешать, всыпать нарезанную кусочками клубнику.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9423,'Половину крошки выложить в форму, утрамбовать, выложить ровным слоем начинку. Посыпать остатками крошки, орехов. Форму закрыть фольгой, поставить в морозильную камеру на четыре часа, можно на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9423,'Перед подачей подержать пирожное с клубникой при комнатной температуре в течение 10–15 минут, затем нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Вымыть, почистить и отварить картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Вымыть, просушить и измельчить укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Мелко потереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Разделить яичные белки и желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Слить с отваренного картофеля воду, сделать сухое пюре. Посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Добавить сливочное масло, мускатный орех, укроп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Чуть-чуть остудить картофель, положить 4 ст. л. сметаны, желтки, ½ сыра, крахмал. Перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Взбить белки, вмешать в картофельную массу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Намазать форму сливочным маслом, посыпать сухарями, выложить в форму картофельную массу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Помазать сметаной, посыпать сыром, мускатным орехом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Готовить 30-35 минут, соблюдать температуру 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9424,'Получается нежное, воздушное картофельное суфле с чесноком.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Сделать овощной бульон: порезать на большие кусочки стебель сельдерея, морковь, половину перца, цуккини, лука с кожурой.','https:https://st.vkuso.ru/data/cache/thumb/51/a339170a5153351_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Залить кипятком, готовить 20 минут, подсолить.','https:https://st.vkuso.ru/data/cache/thumb/fa/ce081094551f2fa_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Процедить бульон в другую кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'В отдельной емкости залить водой чечевицу, варить 10-15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Слить воду, отставить, добавить в суп за несколько минут до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Подготовить остальные овощи: порезать на маленькие кубики перец, морковь, цуккини, сельдерей, лук, измельчить чеснок.','https:https://st.vkuso.ru/data/cache/thumb/b8/1ebba5189d4a5b8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Обжарить порезанные овощи, кроме чеснока, на оливковом масле несколько минут.','https:https://st.vkuso.ru/data/cache/thumb/b1/6a6e5fe9ed7f4b1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Положить потертые томаты, измельченный чеснок, готовить 3 минуты.','https:https://st.vkuso.ru/data/cache/thumb/89/5acc4848b1bc089_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Положить в бульон кукурузу, фасоль, брокколи, веточку тимьяна, розмарина. Довести до кипения, готовить 10 минут. Посыпать перцем, солью.','https:https://st.vkuso.ru/data/cache/thumb/27/76d3322a193f127_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'За 2 минуты до готовности положить чечевицу. Убрать с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Сделать из помидоров чашечки (мякоть удалить с помощью кофейной ложечки).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Положить со сковороды полученную массу, мешать минуту.','https:https://st.vkuso.ru/data/cache/thumb/87/cfb264b4e166987_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9425,'Подавать суп с мелко порезанным сыром «Пармезан» и порезанным базиликом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Маффины могут быть не только десертными, но и закусочными. Оригинальный и полезный рецепт для будней и праздничного стола.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Кисло-сладкое зеленое яблоко и репчатый лук очистить, измельчить и перемешать с куриным фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Всыпать манную крупу, соль и молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Оставить смесь на час или два, крупа должна набухнуть, впитать влагу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Сформовать небольшие котлеты. Другой способ: выложить фарш в порционные формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Печь при температуре 200 градусов, время – от 30 до 35 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Приготовить заливку из натурального йогурта с солью, перцем и горчицей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'За 15 минут до готовности блюда полить смесью маффины, посыпать тертым нежирным сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9426,'Готовые маффины можно посыпать мелко нарезанным зеленым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9427,'Яблоки очистить от кожуры и семенных камер, нарезать на тонкие дольки толщиной в полсантиметра. На сковороде разогреть сливочное масло, всыпать коричневый сахар, молотую корицу. Добавить яблочную нарезку, прогреть, помешивая, сахарный песок должен раствориться полностью. Убрать начинку с огня.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9427,'Для приготовления теста просеять пшеничную муку, разрыхлитель, перемешать. Охлажденное сливочное масло нарезать кубиками. Растереть массу руками в крошку, добавить немного сахара, по вкусу, от двух до четырех ложек. Влить в крошку жирный йогурт или молоко, перемешать. Тесто должно быть мягким и липким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9427,'Посыпать рабочую поверхность мукой, раскатать тесто в пласт толщиной один сантиметр, соотношение сторон: один к двум. На половину лепешки выложить обжаренные яблоки, накрыть второй половиной, прижать и сформовать квадрат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9427,'Отдельно соединить в чашке сырое куриное яйцо, молотую корицу и сахар, перемешать до однородного состояния. Острым ножом разрезать лепешку на 9–12 кусочков, выложить их на лист пергамента на расстоянии друг от друга.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9427,'Смазать яблочные бисквиты яичной смесью с помощью кисточки, печь при 220 градусах в течение 12–17 минут. Должна образоваться золотистая корочка. Остудить выпечку на противне, подать с соусом, который остался от обжаривания яблок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9428,'Сливочное масло разогреть на сковороде, обжарить измельченный репчатый лук до золотисто-коричневого цвета. Добавить свежий и сушеный чеснок, нарезанную морковь, стебли сельдерея, консервированную рыбу. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9428,'Добавить макароны, бульон из курицы, молоко. Смесь довести до кипения, накрыть крышкой, прогревать на слабом огне в течение 12 минут до мягкости макарон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9428,'Добавить свежий или замороженный горошек, перемешать, готовить еще две минуты. Добавить сыр, перемешать, он должен расплавиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9428,'Соль и перец – по вкусу. Макароны с тунцом и горошком подать к столу горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Охлажденное сливочное масло нарезать, смешать с пшеничной мукой, перетереть в крошку руками. Добавить в смесь сметану, быстро замесить тесто, размять, сформовать «колобок».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Выложить в форму для выпекания, равномерно размазать по поверхности, вылепить высокие бортики. Корж наколоть вилкой, охладить в течение получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Выложить на тесто лист пергамента, груз из сыпучих продуктов: сухого гороха, фасоли, пшена. Такую «насыпку» можно использовать многократно. Печь заготовку при температуре 200 градусов в течение 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Отдельно взбить яйца, добавить любые сухие травы, черный перец, паприку, снова взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Натереть твердый сыр на крупной терке. В готовую и немного остывшую основу выложить сыр, свежий или слабосоленый лосось, нарезанный кусочками, заранее отваренные соцветия брокколи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9429,'Залить начинку яичной массой и сливками. Печь пирог с лососем и брокколи в течение 35 минут при температуре 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9430,'Из готового, купленного в магазине, или приготовленного самостоятельно, бисквита вырезать кружочки, размером с настоящую пивную кружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9430,'Приготовить крем из сгущенного молока и сливочного масла. Промазать массой бисквиты, сложить их в стопку, друг на  друга. Сбоку сделать небольшой вырез и вставить туда сушку, имитирующую «ручку».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9430,'Обмазать бока тем же кремом, обложить бисквитными палочками или печеньем Савоярди. Снизу и сверху от ручки «приклеить» кремом кусочки палочек, все сооружение уплотнить руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9430,'Сверху намазать крем, насыпать, оставшиеся от обрезки бисквита, крошки, снова крем, взбитые сливки из баллончика. Украсить торт «Пивная кружка» любыми ягодами, мармеладом, посыпкой и сразу подать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9431,'Репчатый лук нарезать полукольцами, обжарить на растительном масле. Нарезать пластинками шампиньоны, обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9431,'Нарезать соломкой крабовые палочки, также обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9431,'К этим трем ингредиентам добавить очищенную, отваренную и натертую морковь, рубленый укроп, перемешать, заправить салат «Необыкновенный» оливковым маслом, снова перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9432,'Помидоры нарезать мелким квадратиками, смешать с рубленым базиликом, добавить молотый перец, соль, итальянские травы. Добавить рикотту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9432,'Готовое слоеное тесто разрезать на квадраты, смазать чуть взбитым желтком. Выложить начинку, скрепить края, начинка должна остаться открытой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9432,'Печь итальянские пирожки с рикоттой в течение 20–25 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9433,'В теплой воде растворить свежие, сырые, дрожжи, дать немного постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9433,'Добавить сырое куриное яйцо, соль, всыпать порциями просеянную пшеничную муку. Массу перемешать с помощью лопатки, еще лучше – вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9433,'Накрыть тесто крышкой или пленкой, поставить в тепло на два часа. Масса должна подняться, увеличиться в размерах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9433,'Разогреть на сковороде растительное масло, выкладывать тесто для оладий ложкой, жарить оладьи «Школьные» на среднем огне с двух сторон, до аппетитной, румяной, корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Баклажаны нарезать вдоль, тонкими ломтиками. Посолить, оставить на некоторое время для удаления горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Грибы вешенки нарезать, обжарить на растительном масле, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Нарезать кубиками отварное куриное филе. Так же, кубиками, нарезать свежие помидоры и огурцы. Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'В майонез добавить рубленую зелень укропа и давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Баклажаны обжарить на растительном масле, выложить в глубокую миску, закрыть ими не только дно, но и стенки, смазать майонезным соусом, сверху – огурцы, баклажаны, соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Следующие слои: курица, баклажан, майонез, сыр, снова баклажан, майонезный соус, помидоры, баклажан, соус, вешенки, баклажаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9434,'Салат «Баклажаниус» поставить на ночь в холодильник, утром закуску осторожно перевернуть на блюдо, миску снять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9435,'Отварить тыкву на тихом огне в воде или на молоке. Жидкости много не наливать. Мякоть провернуть в блендере до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9435,'Охлажденное сливочное масло натереть на крупной терке, добавить пшеничную муку и соль. Отдельно взбить желток с холодной водой, смесь добавлять в тесто постепенно, частями. Сформовать шар, завернуть его в пищевую пленку, поставить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9435,'Охлажденное тесто раскатать, выложить в круглую форму небольшого размера, края должны быть закрыты. В лепешке не должно быть дырочек, иначе начинка вытечет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9435,'Для приготовления начинки взбить пюре из тыквы с молоком, яйцом, можно добавить белок, оставшийся от приготовления теста. Всыпать сахарный песок, молотую корицу, мускатный орех, измельченный имбирь, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9435,'Начинка должна быть жидкой, вылить ее в приготовленную форму с тестом, печь тыквенный пирог в духовке в течение 30–40 минут, до готовности, поверить ножом или зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9436,'Нагреть молоко, добавить растопленное сливочное масло, ванилин, влить воду, яйцо. Массу вылить в хлебопечку. Смешать просеянную пшеничную муку, сахарный песок, соль, добавить в жидкость. В углубление всыпать сухие дрожжи, включить режим «Тесто».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Заполнить их начинкой, присыпать крупно натертым сыром, поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9436,'Посыпать мукой рабочую поверхность, раскатать тесто в прямоугольник большого размера, толщина – 5-7 миллиметров. Смазать мягким сливочным маслом. Смешать коричневый сахарный песок с корицей, смесь выложить на тесто в качестве начинки. Свернуть рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9436,'Нарезать «колбаску» на кусочки толщиной в три сантиметра, можно сделать это с помощью нитки. Противень смазать маслом, поставить заготовки на 40 минут в теплую духовку. Булочки должны увеличиться в полтора-два раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9436,'Печь булочки с корицей при температуре 190 градусов в течение 15–20 минут, до образования золотисто-коричневой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9436,'Для глазури смешать сахарную пудру, ванилин, молоко, полить выпечку. При желании в смесь можно добавить немного сыра, например Маскарпоне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9437,'Растопить на тихом огне сахарный песок, сливки и сливочное масло. Массу снять с огня, перемешать с кокосовой стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9437,'Выложить смесь слоем в полтора сантиметра, поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9437,'Разрезать в виде батончиков, оставить в морозилке на три часа. Молочный шоколад растопить на бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9437,'Охлажденные батончики «Баунти» окунуть в массу, поставить в холодильник до полного затвердения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9438,'Готовое слоеное тесто раскатать. Нарезать полосками, ширина – один сантиметр. Из плотного картона свернуть конус, намотать полоску теста в виде «морковки».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9438,'Трубочки выложить на противень, смазать смесью морковного сока с томатной пастой. Печь в духовке до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9438,'Отдельно приготовить салат-начинку из крутых тертых яиц, огурцов, отваренных и разобранных на волокна куриных грудок, мелко нарезанного укропа. Смесь посолить, поперчить, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9438,'Остывшие трубочки начинить с помощью полиэтиленового пакета с отверстием, украсить куриный салат в слоеном тесте стебельками петрушки или зеленого салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9439,'Вяленые или замороженные вишни выложить в сито и хорошо промыть теплой водой. Ягоды обсушить на бумажных полотенцах, нарезать на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9439,'Отдельно взбить мягкое сливочное масло с сахарным песком в пышный крем. Ввести по одному сырому яйцу, продолжать взбивать. Добавлять пшеничную муку, ложками, если масса будет сворачиваться. Влить лимонный сок, всыпать цедру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9439,'Ягоды обвалять в небольшом количестве муки. Всыпать в тесто остатки муки с разрыхлителем, вишню, влить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9439,'Готовое тесто выложить в форму для выпекания, поставить кекс с вишней в духовку, печь в течение часа при температуре 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Субпродукты хорошо промыть холодной водой, оставить отмокать, затем отварить в течение 40–45 минут, с солью, лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Отварить вкрутую и остудить яйца, нарезать мелкими кубиками. Помидоры вымыть и также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Тонко нашинковать репчатый лук, замариновать его в уксусе на 10–15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Хорошо вымыть и порубить зелень петрушки и укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Нарезать сердечки, все ингредиенты смешать, добавить зеленый горошек, сметану, перец и соль, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9440,'Салат из куриных сердечек можно подавать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9441,'Отварить и очистить крупные креветки. Очистить и мелко нарезать корень имбиря, обжарить вместе с креветочной массой на оливковом масле до золотистого цвета. Остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9441,'Для приготовления заправки взбить в блендере листочки свежей мяты с оливковым маслом, влить ложку сока лимона, посолить по вкусу. Листья зеленого салата вымыть, обсушить, выложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9441,'Полить половиной объема полученной заправки, выложить на соус креветки, дольки грейпфрута, очищенные от пленок, кубики сыра Дор Блю. Полить салат с креветками остатками соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9442,'Свинину нарезать на тонкие ломтики, толщина не должна превышать один сантиметр, для этого понадобится очень острый нож. Отбить мясо молотком, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9442,'Для шубы репчатый лук очистить, нарезать маленькими кубиками. Клубни картофеля также очистить от кожуры и натереть на крупной терке. Лишнюю жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Сформовать рогалики с начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9442,'Овощи смешать, вбить сырые куриные яйца, всыпать пшеничную муку, соль, перец, влить сметану, добавить давленый чеснок. Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9442,'Налить в сковороду растительное масло. Отбивные обвалять в полученной смеси и жарить с двух сторон до готовности, должна образоваться золотистая корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9442,'Почти готовые свиные отбивные под шубкой выложить в форму для запекания, намазать сметаной, печь в духовке в течение 15–20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9443,'Чеснок и зелень измельчить, смешать с нежирным творогом, тертым сыром, майонезом или сметаной, добавить специи: кинзу, паприку, куркуму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9443,'Филе разрезать на две части, отбить, натереть солью, выложить творожную начинку, завернуть рулетами и скрепить зубочистками или нитками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9443,'Выложить заготовки на разогретую сковороду, обжарить со всех сторон на масле до корочки, на сильном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9443,'Допечь куриные рулеты в духовке в течение 25 минут при температуре 220 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9444,'Для приготовления крема сметану выложить в марлю, подвесить мешочек на ночь над миской или раковиной. Другой вариант: поместить продукт в марле в дуршлаг и прижать грузом на два-три часа. В любом случае должно отцедиться как можно больше жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9444,'Густую сметану и сахарный песок переложить в сотейник, поставить на водяную баню. Варить крем, помешивая, в течение 60–90 минут, при слабом кипении. Должна получиться мягкая и однородная масса, с легким карамельным оттенком. В конце приготовления в крем добавить сливочное масло комнатной температуры, перемешать, поставить в холодильник на несколько часов или на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9444,'Для теста перемешать сырые куриные яйца с сахаром, добавить жидкий мед, погашенную уксусом соду, растопленное сливочное масло и пшеничную муку. Массу перемешать с помощью деревянной лопатки. Кастрюлю поставить на баню, варить смесь в течение часа, помешивать, от плиты не отходить, тесто начнет завариваться, будут образовываться комочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9444,'Противень застелить пергаментом, выложить часть теста руками в перчатках, в горячем виде. Слой должен быть тонким, просвечивающим. Выпечь поочередно несколько коржей в разогретой до 220 градусов духовке, в течение 4–5 минут. Обрезать до нужного размера, остудить. Обрезки измельчить в крошку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9444,'Коржи торта «Медовик» прослоить сметанным кремом, им же смазать верх и бока, посыпать крошкой, поставить на ночь в холодильник для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9445,'Отварить цветную капусту в подсоленной воде в течение 15–20 минут, до мягкости. Замочить желатин так, как указано на этикетке, в холодной воде, на 15–20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9445,'В готовую капусту добавить сливки двух сортов: обычные и жирные, измельчить блендером до однородного состояния. Смесь снова поставить на огонь, довести до кипения на тихом огне, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9445,'Отжать желатин, переложить в капустную массу, перемешать. Смесь разлить в порционные формочки. Дать остыть при комнатной температуре, затем поставить в холодильник до полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9445,'При подаче украсить блюдо красной икрой, зеленью, например, кресс-салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9446,'Смешать заранее просеянную пшеничную муку, сухое молоко, сахарный песок, соль, перемешать. Взбить вилкой сырое куриное яйцо, долить к нему молоко, положить дрожжи, перемешать с помощью венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9446,'Яичную смесь добавить к сухой смеси, замесить тесто. Ввести растопленное сливочное масло, еще раз перемешать. Тесто выложить в миску, оно должно быть липким. Накрыть массу полотенцем, оставить подходить на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9446,'Для крема развести кукурузный крахмал в теплом молоке, добавить два желтка, сахар, ванилин из пакетика, перемешать. Варить на среднем огне, помешивать, довести до кипения. Дать крему немного остыть, добавить мягкое сливочное масло, снова взбить, влить лимонный сок, еще раз взбить венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9446,'Подошедшее тесто обмять руками, разделить на четырнадцать кусочков, каждый раскатать, положить в середину крем, края должны остаться свободными на три сантиметра. Накрыть крем тестом, края залепить. Остатки теста нарезать полосками, свернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Узоры осторожно снять и украсить торт. Посыпать кокосовой стружкой.','https:https://st.vkuso.ru/data/cache/thumb/de/65df41ba4fa64de_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9446,'Застелить противень пергаментом, выложить булочки, накрыть тканью и оставить на полчаса. Перед выпечкой заготовки смазать желтком, печь булочки с заварным кремом при температуре 180 градусов в течение 15 минут, до золотистой корочки. Готовую выпечку остудить под полотенцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Перемешать сушеные травы: орегано, тимьян, базилик с солью, перцем, панировочными сухарями.','https:https://st.vkuso.ru/data/cache/thumb/18/b345ed67731bf18_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Куриное филе обвалять в данной смеси, стряхнуть лишнее.','https:https://st.vkuso.ru/data/cache/thumb/90/6dc39b736221e90_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'В небольшой жаростойкой сковороде разогреть оливковое масло, огонь – средний.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Добавить куриное мясо, жарить до получения коричневатого цвета, время – по три минуты с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Сковороду снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Вокруг курицы выложить готовый томатный соус. На грудку посыпать тертый сыр «Пармезан», выложить «Моцареллу», нарезанную ломтиками.','https:https://st.vkuso.ru/data/cache/thumb/d8/ddea638437694d8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Накрыть фольгой, печь в течение 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9447,'Фольгу снять, прогреть еще пять минут, до расплавления сыра и готовности мяса.','https:https://st.vkuso.ru/data/cache/thumb/90/94604791fdd9390_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Нарезать большими кубиками куриное филе, обжарить на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Мелкими кубиками нарезать репчатый лук, морковь и сладкий болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Разогреть масло на сковороде, обжарить овощную нарезку в течение пяти-семи минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Влить соевый соус и готовую томатную пасту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Потушить овощи в течение 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'В конце приготовления добавить перец чили и нарезанный чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Выложить куриное филе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'Ингредиенты перемешать и подержать на среднем огне три минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9448,'В конце приготовления посыпать блюдо любой измельченной зеленью, посолить, поперчить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Разморозить слоеное тесто из магазина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Отдельно взбить яйцо и натереть сыр «Чеддер».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Духовой шкаф разогреть до 180 градусов, противень застелить фольгой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Тесто смазать взбитым яйцом и посыпать любимыми сухими приправами. Соль добавить по вкусу и по желанию, можно обойтись без нее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Выложить слой сыра, раскатать тесто скалкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Нарезать его на полоски шириной по два сантиметра.','https:https://st.vkuso.ru/data/cache/thumb/fd/8adc1972f476bfd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Каждую полоску скрутить и обернуть беконом.','https:https://st.vkuso.ru/data/cache/thumb/ad/a0a72d7bff728ad_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Выложить на противень и печь плетенки в духовом шкафу около получаса, переворачивать, прогревать до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Вынуть изделия из духовки, остудить в течение пяти минут, подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'Можно приготовить еще один вариант блюда: перемешать в небольшой емкости коричневый сахар, розмарин или другую приправу, перец и соль.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9449,'В полученной смеси обвалять плетенки и запечь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Измельчить сыр «Сулугуни» на крупной терке, добавить его в обезжиренный творог, посолить и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Армянский лаваш нарезать одинаковыми пластами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Выложить первый лист лаваша в глубокий противень, смазать кефиром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Сверху – сырно-творожная начинка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Второй лист лаваша вымочить в кефире, осторожно перенести на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Выложить еще один слой начинки и еще один лаваш.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Верх посыпать тертым сыром, измельченной зеленью укропа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9450,'Поставить пирог в духовой шкаф, температура выпекания – 180 градусов, время: 30 – 35 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Свежую молодую картошку хорошо промыть и отварить до готовности. Готовность проверить вилкой или ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Готовые клубни вынуть и остудить. Удалить кожицу, мякоть нарезать небольшими кусочками или покрупнее, по желанию.','https:https://st.vkuso.ru/data/cache/thumb/84/87f9ab6dc4ecd84_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Отварить куриные яйца вкрутую.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Остудить, очистить и нарезать небольшими кусочками. Переложить в картошку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Дать торту постоять для пропитывания два часа или оставить на ночь.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Нарезать небольшими кусочками вареную или копченую колбасу или отваренное мясо.','https:https://st.vkuso.ru/data/cache/thumb/bd/4b35df148cd14bd_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Свежие огурцы без горечи нарезать маленькими кубиками, добавить в общую массу.','https:https://st.vkuso.ru/data/cache/thumb/62/0df86ffd96d8e62_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'В качестве душистой зеленой заправки подойдет базилик, сельдерей, кинза, любые другие травы. Промыть и мелко нарезать.','https:https://st.vkuso.ru/data/cache/thumb/c3/ab309365113cec3_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Слить жидкость от зеленого горошка, добавить его к остальным продуктам.','https:https://st.vkuso.ru/data/cache/thumb/c0/233a30c04335ac0_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Массу хорошо перемешать, подержать в холодильнике один-два часа.','https:https://st.vkuso.ru/data/cache/thumb/e7/888b65925d986e7_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Там же заранее охладить минеральную воду.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Смесь овощей и зелени приправить по вкусу солью, поперчить, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'По вкусу добавить сметану, горчицу, лимонный сок и майонез.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9451,'Выложить окрошку в порционные глубокие тарелки, залить минералкой и подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/f0/79a8023815a01f0_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Грибы шитаки, шампиньоны или 20-25 вешенок нарезать кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'В большой кастрюле нагреть по столовой ложке сливочного и оливкового масла, добавить грибы, жарить 10 минут. Продукт должен стать мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Половину грибов переложить в другую тарелку.','https:https://st.vkuso.ru/data/cache/thumb/b4/39459c0c5aa59b4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'В оставшуюся половину добавить нарезанные морковь и репчатый лук, свежие листочки тимьяна, соль и перец по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/64/b268c8816bdd464_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Прогревать смесь еще 10 минут, пока овощи также не станут мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Влить воду, довести до кипения, варить в течение 20 минут на среднем огне. Можно долить еще немного воды, если в этом есть необходимость.','https:https://st.vkuso.ru/data/cache/thumb/96/0590f9abb2e3696_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Снять массу с огня, остудить, измельчить содержимое кастрюли блендером или в комбайне до состояния пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Переложить массу обратно в кастрюлю, добавить сливки и обжаренные грибы.','https:https://st.vkuso.ru/data/cache/thumb/c6/2de515722c60fc6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Довести до кипения, огонь убавить, кипятить на тихом огне под крышкой около пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9452,'Помешивать. Посолить и поперчить по желанию.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Для приготовления бисквита взбить сырые куриные яйца до увеличения объема в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Миксер не выключать, всыпать сахарный песок, взбивать пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Продолжать взбивать, всыпать пшеничную муку и разрыхлитель, перемешивать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Дно формы застелить пергаментной бумагой, смазать растопленным сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Тесто вылить в форму, поставить в духовой шкаф на 30 – 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Готовый бисквит вынуть, охладить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Для приготовления крема смешать сгущенное молоко, мягкое сливочное масло, сладкие кукурузные палочки, кокосовую стружку. Немного стружки оставить для украшения торта.','https:https://st.vkuso.ru/data/cache/thumb/eb/b9897d2ddcb1beb_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Четверть кремовой массы убрать в холод на час.','https:https://st.vkuso.ru/data/cache/thumb/cb/bb7d65b03e598cb_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Для второго крема взбить сливки с сахарной пудрой. Масса лучше взобьется, если венчик и посуда будут охлажденными.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Бисквит разрезать поперек пополам.','https:https://st.vkuso.ru/data/cache/thumb/da/d6aab2cc04ff0da_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Нижний корж намазать первым кремом, накрыть второй половиной и придавить.','https:https://st.vkuso.ru/data/cache/thumb/9d/4b1703d542dec9d_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Весь торт обмазать взбитыми сладкими сливками.','https:https://st.vkuso.ru/data/cache/thumb/86/af5d2ab7f00ae86_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Второй крем переложить в кондитерский мешок.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'С помощью насадки украсить боковые части выпечки.','https:https://st.vkuso.ru/data/cache/thumb/97/911438ed8b7d497_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Вынуть из холодильника охлажденный крем, сформовать шарики, в каждый вставить по орешку миндаля и обмакнуть в кокосовую стружку.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Белый шоколад растопить на водяной бане, начинить массой кондитерский мешок, кончик срезать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9453,'Желаемый узор нанести на пергамент и дать застыть.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Всыпать еще часть зиры, снова положить чеснок.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Картошку очистить и нарезать дольками, положить в воду, варить в течение пяти-семи минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Продукт отцедить и выложить в форму для запекания, посолить и посыпать любимыми специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Сбрызнуть маслом, печь в духовом шкафу до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Другой вариант: выложить картошку со специями и маслом в пакет из целлофана, зажать рукой отверстие и хорошо потрясти, затем выложить и запечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Если картофель молодой, то он будет готов через 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9455,'Мелкие клубни можно запечь целиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9456,'Добавить в йогурт лимонную цедру и сок, заменитель сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9456,'Перемешать смесь венчиком или ложкой. Должна получиться однородная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9456,'Переложить её в мороженицу или пластиковый контейнер, взбивать каждый 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9456,'В морозильной камере десерт будет готов через час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9456,'При подаче разложить продукт в пиалы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Муку высшего сорта просеять, высыпать на разделочную поверхность или в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'В середине горки сделать отверстие, вбить яйца.','https:https://st.vkuso.ru/data/cache/thumb/d2/20cad7df5fe4cd2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Замесить тесто, оно должно получиться мягким и эластичным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Готовый колобок обернуть в пищевую пленку и поставить в холодильник на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/55/0557a6b2c293455_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Если в наличии нет специальной машины для итальянской пасты, то можно использовать скалку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Тесто должно быть раскатано очень тонко и равномерно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Нарезать его острым ножом, присыпанным мукой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9457,'Чтобы раскатывать было удобнее, тесто можно поделить на несколько частей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Внутренние стенки формочек смазать сливочным маслом. Посыпать сахаром, излишки удалить.','https:https://st.vkuso.ru/data/cache/thumb/d4/c10c2551f70dbd4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Растопить на среднем огне сливочное масло, вмешать муку, жарить до появления золотисто-коричневого цвета и аромата жареного ореха.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Влить заранее охлажденное молоко, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Масса должна загустеть через три-четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Переложить её в миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Вмешать апельсиновую цедру и немного ликера «Grand Marnier». Хорошо перемешать.','https:https://st.vkuso.ru/data/cache/thumb/bc/7f171a9a45647bc_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Добавить яичные желтки и ваниль, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/1e/7a29142ee33051e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Белки взбить в отдельной миске, порциями всыпать сахар, продолжать взбивать до загустения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Безе должно быть мягким, но хорошо держать форму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'В два приема смешать белковую массу с желтковой.','https:https://st.vkuso.ru/data/cache/thumb/57/209dd3afe804b57_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Вылить в формы на две трети объема, печь в течение 16 минут, температура – 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/16/bb392f3af283b16_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Во время приготовления дверцу духовки не открывать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9458,'Десерт должен подняться и стать коричневым. Подать блюдо к столу горячим.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Соединить в емкости соль, топленное сливочное масло, сахар, 80 миллилитров горячей воды.','https:https://st.vkuso.ru/data/cache/thumb/96/38864533d434096_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Насыпать муку.','https:https://st.vkuso.ru/data/cache/thumb/7d/c5b2b7d5c9cd27d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Замесить тесто. Накрыть полотенцем, отставить на 30 минут.','https:https://st.vkuso.ru/data/cache/thumb/fb/d93964f501448fb_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Достать косточки из черешни, выложить ягоды на дуршлаг, чтобы стекла жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Разделить тесто на три одинаковые части.','https:https://st.vkuso.ru/data/cache/thumb/44/53dcd2721daa144_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Раскатать все части, в центр положить черешню.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Посыпать смесью корицы и коричневого сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Закрывая галету краями теста, серединку оставлять открытой. Заворачивать тесто складками.','https:https://st.vkuso.ru/data/cache/thumb/d7/639951a5a55bfd7_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Вырезать из фольги кружки диаметром, как открытая часть галеты.','https:https://st.vkuso.ru/data/cache/thumb/65/23cdcb53edbd165_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9459,'Накрыть серединку каждой галеты фольгой, готовить 20 минут, соблюдать температуру 190 градусов.','https:https://st.vkuso.ru/data/cache/thumb/4a/4220a49080ea74a_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'В плове сделать углубление, чтобы вышел пар.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Обжарить измельченный лук, чеснок, мелко порезанную тыкву на масле. Тушить, помешивая, приблизительно 6 минут.','https:https://st.vkuso.ru/data/cache/thumb/2f/803f1765828652f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Долить воду или бульон, продолжать готовить.','https:https://st.vkuso.ru/data/cache/thumb/15/79cb262fe4ed815_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Из тыквы с луком сделать пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Добавить пасту и тертый сыр.','https:https://st.vkuso.ru/data/cache/thumb/80/969e51aa2e3c980_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Долить молока, чтобы сыр хорошо расплавился.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Тушить на сковороде, помешивая время от времени.','https:https://st.vkuso.ru/data/cache/thumb/84/32d74c4a7438c84_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Насыпать перец, соль, добавить измельченный мускатный орех.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9460,'Подавать пасту со сладким сырно-тыквенным соусом в горячем виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Мелко порезать куриное мясо, посыпать перцем, солью, натуральными приправами и специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Отдельно соединить сливки и яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Залить мясо заливкой, перемешать. Отставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Нашинковать овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Крупно потереть морковь. Измельчить лук. Перец порезать на брусочки.','https:https://st.vkuso.ru/data/cache/thumb/7f/df3624d19916a7f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'В чашу мультиварки налить маленькую ложку оливкового масла. Положить овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Посыпать перцем, солью, чуть-чуть потушить.','https:https://st.vkuso.ru/data/cache/thumb/76/09b57ea5ed6c576_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Выровнять слой, положить сверху слой курицы. На нее смесь сыра и зелени.','https:https://st.vkuso.ru/data/cache/thumb/b6/243f05ff86995b6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9461,'Поставить режим «Выпечка» на 30 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Подготовить все ингредиенты для теста.','https:https://st.vkuso.ru/data/cache/thumb/82/97415efa6c50a82_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Соединить все, кроме какао.','https:https://st.vkuso.ru/data/cache/thumb/bb/39fb26c27e33ebb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Разделить тесто пополам, в одну часть насыпать какао.','https:https://st.vkuso.ru/data/cache/thumb/9c/fb761b948afc69c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Слепить шарики диаметром приблизительно 3 сантиметра. Положить их на сковороду, намазанную маслом.','https:https://st.vkuso.ru/data/cache/thumb/d7/3469a5d6f75eed7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Отправить на 25 минут в духовку, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Приготовить клубничный соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Положить в небольшую посуду замороженную клубнику, насыпать сахар, долить воду. Сахар можно заменить сахарозаменителем.','https:https://st.vkuso.ru/data/cache/thumb/c5/206f70d0ef5c9c5_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Довести до кипения, сделать самый маленький огонь. Готовить 30 минут, помешивая время от времени.','https:https://st.vkuso.ru/data/cache/thumb/6d/b5071f99753d26d_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Достать готовые шарики, позволить остыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Готовый клубничный соус можно превратить в однородную смесь при помощи блендера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9462,'Можно подавать творожные шарики с маком и цукатами с клубничным соусом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Вымыть брокколи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Отмерить кунжут, почистить чеснок.','https:https://st.vkuso.ru/data/cache/thumb/c8/a4fa3329f83dac8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Разобрать брокколи на соцветия. Важно, чтобы соцветия были не очень маленькие, иначе они разварятся.','https:https://st.vkuso.ru/data/cache/thumb/a6/7aaf4c36a8834a6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Поставить на огонь кастрюлю с двумя литрами воды, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Порезать чеснок на пластинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Положить в кипящую воду брокколи. Варить не больше 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/90/e56a2d8f1ea8690_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Нагреть сковороду, насыпать кунжут. Обжаривать две минуты на сухой сковороде. Высыпать на тарелку.','https:https://st.vkuso.ru/data/cache/thumb/47/b58a187e7247f47_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'На сковороду налить ложку масла, положить чеснок, порезанный на пластинки. Жарить минуту, чтобы чеснок стал коричневым. Достать чеснок, высыпать в отдельную емкость.','https:https://st.vkuso.ru/data/cache/thumb/ce/b667e19288bc7ce_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'В оставшееся масло налить соевый соус, винный уксус. Хорошо перемешать, на огонь не ставить, так как горячее масло доведет соус до необходимой консистенции.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Достать брокколи из кастрюли, положить на поднос, застеленный салфетками - они впитают лишнюю жидкость. Остудить.','https:https://st.vkuso.ru/data/cache/thumb/e3/a19882a192e69e3_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Положить брокколи на тарелку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Посыпать кунжутом, чипсами из чеснока, полить соусом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9463,'Можно подавать теплый салат из брокколи с чесноком и кунжутом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Отделить желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Взбить при помощи миксера желтки, сахар, маленькую ложку марсалы.','https:https://st.vkuso.ru/data/cache/thumb/87/a902082fecdbf87_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Добавить маскарпоне, размешивать, пока не исчезнут комочки.','https:https://st.vkuso.ru/data/cache/thumb/ea/18adddb1a4234ea_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Вмешать в яичную смесь сливки, перемешать лопаткой.','https:https://st.vkuso.ru/data/cache/thumb/1b/032d1fd5a299f1b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Окунуть в кофе савоярди, держать не очень долго.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Выложить по формочкам: слой крема, савоярди, опять крем, не больше 2-3 раз.','https:https://st.vkuso.ru/data/cache/thumb/54/7fccad368e51854_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Посыпать тертым шоколадом или какао.','https:https://st.vkuso.ru/data/cache/thumb/c4/9402b0f69c87ac4_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Можно сделать тирамису в одной большой форме. Намазать дно кремом, сделать около трех слоев.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Осторожно промазать каждый слой Тирамису Мадалены с Марсалой, равномерно распределить лопаткой.','https:https://st.vkuso.ru/data/cache/thumb/94/68e0a2749fdfa94_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Посыпать какао.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Отправить в холодильник на 5 часов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9464,'Осторожно достать лопаткой. Если ожидается определенное количество гостей, то лучше готовить порционно.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Отварить печень 20 минут, остудить. Крупно потереть или размять вилкой в горячем виде.','https:https://st.vkuso.ru/data/cache/thumb/97/5367ba0981bba97_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Почистить морковь и лук, порезать или потереть. Обжарить вместе или по отдельности.','https:https://st.vkuso.ru/data/cache/thumb/87/fc198f3b4d92187_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Отварить яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Порезать грибы на мелкие кубики или на пластинки, обжарить.','https:https://st.vkuso.ru/data/cache/thumb/eb/564e62301997deb_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Положить в морозильную камеру плавленый сыр на 10-15 минут, чтобы легче было тереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Слоями выложить сначала куриную печень с майонезом.','https:https://st.vkuso.ru/data/cache/thumb/ac/2543a42f84092ac_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Затем лук и морковь.','https:https://st.vkuso.ru/data/cache/thumb/bc/56d11bda64baabc_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Далее грибы, смешанные с майонезом.','https:https://st.vkuso.ru/data/cache/thumb/47/a62840de4795747_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Потом тертый плавленый сыр. Смазать слегка майонезом.','https:https://st.vkuso.ru/data/cache/thumb/5f/9d9bd49d8a47a5f_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Верхний слой – тертое яйцо и майонез.','https:https://st.vkuso.ru/data/cache/thumb/45/4d67f395d12ff45_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9465,'Можно украсить печеночный слоеный салат с шампиньонами зеленью, соленым огурцом, кружком яйца.','https:https://st.vkuso.ru/data/cache/thumb/0a/f351a95c9bee70a_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Подготовить керамическую емкость, способную выдержать высокую температуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Растопить сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Вбить яйца.','https:https://st.vkuso.ru/data/cache/thumb/a2/4641ae3d9363ca2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Взбить.','https:https://st.vkuso.ru/data/cache/thumb/82/a16a216b3402782_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Налить молоко, посыпать специями, солью.','https:https://st.vkuso.ru/data/cache/thumb/c1/09c3cef9dea8dc1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Порезать колбасу на маленькие кубики. Добавить в емкость.','https:https://st.vkuso.ru/data/cache/thumb/cd/ba751020da7b5cd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Положить крупно натертый сыр. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/0b/db737f65c2bb40b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Добавить в емкость с омлетом хлеб или батон, порезанный на кубики. Обильно посыпать зеленью, отправить на 10 минут в духовку.','https:https://st.vkuso.ru/data/cache/thumb/bc/96dac83104f02bc_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'В микроволновой печи омлет с сыром и колбасой в чашке готовится несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9466,'Перед подачей посуду перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/38/25227825f352138_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Подготовить продукты.','https:https://st.vkuso.ru/data/cache/thumb/5f/b0fb269fb35ce5f_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Нагреть духовку до 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Измельчить в блендере или с помощью ножа сливочное масло (125 г), муку и сахар (50 г). Долго тесто не замешивать, оно должно начать таять в процессе готовки.','https:https://st.vkuso.ru/data/cache/thumb/f2/795cd7800057bf2_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Вбить яйцо, замесить.','https:https://st.vkuso.ru/data/cache/thumb/de/2d060877fbb7dde_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Сделать из теста шарик.','https:https://st.vkuso.ru/data/cache/thumb/5a/81cf508c77ede5a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Распределить его по формочке, сделать надколы вилкой.','https:https://st.vkuso.ru/data/cache/thumb/76/fd6e1159f198676_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Накрыть специальной бумагой, насыпать любую крупу, чтобы тесто не поднималось.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Выпекать 15-20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Помыть и почистить яблоки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Одно яблоко порезать на полукольца, побрызгать соком лимона, чтобы не стало темным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Положить на сковороду сливочное масло (30 г), добавить корицу и яблоки, насыпать сахар (100 г). Перемешать. Обжарить, чтобы растворился сахар.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Налить в сковороду 3/4 яблочного сока.','https:https://st.vkuso.ru/data/cache/thumb/bd/c3ef07bee0e12bd_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'В остальном соке развести крахмал, налить в сковороду.','https:https://st.vkuso.ru/data/cache/thumb/68/793188e6f5ffb68_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Выпекать яблоки еще несколько минут, чтобы загустел сок.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Положить яблоки в песочную основу, выложить сверху яблоки, порезанные на полукольца, присыпать сахарной пудрой.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'На 3 минуты отправить в духовку.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9467,'Получается вкусный яблочно-лимонный тарт с корицей.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Соединить муку, соль, масло, смешать, чтобы получилась крошка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Переложить массу в емкость, налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Перемешать вилкой до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Завернуть в специальную пленку, отправить в холодильник на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Нагреть духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Постелить на противень фольгу, намазать маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Соединить рубленую зелень, мягкое масло и цедру.','https:https://st.vkuso.ru/data/cache/thumb/0d/4beee38178b8f0d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Разрезать филе пополам, посыпать перцем, солью. На одну сторону рыбы (со стороны кости) нанести масло с зеленью, на противоположную сторону – горчицу.','https:https://st.vkuso.ru/data/cache/thumb/14/a4e8eaf84451714_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Положить 2 куска филе (стороной кожи), как сэндвич.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Достать из холодильника тесто, раскатать, посыпать мукой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'В центр положить рыбное филе, накрыть тестом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Намазать пирог взбитым яйцом.','https:https://st.vkuso.ru/data/cache/thumb/cb/639b8af5fb833cb_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Отправить на 20 минут в духовку.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9468,'Перед подачей пирог с семгой, укропом и базиликом чуть-чуть остудить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Подготовить продукты, разложить по емкостям.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Залить шафран кипятком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Распалить гриль, поставить большую сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Когда она нагреется, положить чеснок, лук. Обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Положить куриное мясо, обжарить до румяного цвета.','https:https://st.vkuso.ru/data/cache/thumb/7b/6b804ae6278697b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Добавить помидоры, сладкий перец, обжаривать несколько минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Положить промытый рис, готовить до прозрачности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Налить бульон, дождаться его выкипания. Все перемешать.','https:https://st.vkuso.ru/data/cache/thumb/d2/1ad7e66d4ef3fd2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Положить горошек, морепродукты, оставшийся бульон, шафран с водой.','https:https://st.vkuso.ru/data/cache/thumb/51/8558f0ec0e92451_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Можно положить чуть-чуть паприки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Посыпать солью, перцем, размешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Когда испарится жидкость, убрать паэлью с куриным филе, морепродуктами и овощами с огня.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9469,'Перед подачей дать постоять 10 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Подготовить продукты. Использовать лучше самый спелый банан - мороженое будет ароматное и сладкое.','https:https://st.vkuso.ru/data/cache/thumb/ff/263da012194c3ff_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Почистить банан, порезать, отправить в морозилку на 3 часа.','https:https://st.vkuso.ru/data/cache/thumb/e7/7cdbb9d8e23b5e7_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Когда банан станет твердым, измельчить, используя блендер. В результате получится кремообразная паста, похожая на растаявшее мороженое.','https:https://st.vkuso.ru/data/cache/thumb/66/f06f1183b296166_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Положить какао, корицу, размешать.','https:https://st.vkuso.ru/data/cache/thumb/e5/201739508c457e5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Отправить мороженое на 20-30 минут в морозилку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9470,'Перед подачей переложить банановое вегетарианское мороженое с корицей в бокалы. В качестве украшения использовать цедру, полить сиропом.','https:https://st.vkuso.ru/data/cache/thumb/bf/e11a36aaa2392bf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Подготовить продукты, отставить.','https:https://st.vkuso.ru/data/cache/thumb/94/e952abd44a07294_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Заняться подготовкой формы. Подойдет формочка для выпечки или лоток, предназначенный для еды. Важно, чтобы форма была глубокая и прямоугольной формы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Застелить ее пищевой пленкой. Концы пленки должны свисать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'На дно положить блины в шахматном порядке (примерно 4 блина).','https:https://st.vkuso.ru/data/cache/thumb/a6/53d50ff459d0ca6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Время выпекания – от пятнадцати до двадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Подготовить первую начинку. Предварительно отварить куриную грудку. Порезать на маленькие кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Нашинковать лук, обжарить на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Отдельно соединить порезанное мясо, измельченные грецкие орехи, лук. Заправить 2 большими ложками майонеза.','https:https://st.vkuso.ru/data/cache/thumb/7a/98f795aafc9207a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Подготовить вторую начинку. Крупно потереть сыр, выдавить чеснок. Соединить с двумя большими ложками майонеза.','https:https://st.vkuso.ru/data/cache/thumb/c1/e47fe8ca78dadc1_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Первую начинку завернуть в блины. Нужно 3 блина.','https:https://st.vkuso.ru/data/cache/thumb/aa/22892f729698aaa_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Можно использовать готовые блины или приготовить самостоятельно.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Вторую начинку завернуть в салатный лист. Если листы маленькие, то использовать 2-3 листа. Нужно 3 таких рулета.','https:https://st.vkuso.ru/data/cache/thumb/5e/f79ef872b59ec5e_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'В шахматном порядке положить рулетики в форму. То есть, сырный рулет-мясной-сырный.','https:https://st.vkuso.ru/data/cache/thumb/12/2c3a15210afe512_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Выложить второй слой. Мясной рулет-сырный-мясной.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'В разрезе должен получиться шахматный узор.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Накрыть блинами, завернуть пленкой.','https:https://st.vkuso.ru/data/cache/thumb/34/8ac9abf9f036334_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Сверху поставить пресс. Например, крышку, а на нее банку. Отправить на несколько часов, а лучше на ночь в холодильник.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9471,'Подавать шахматный террин из блинов с двумя видами начинок, порезав на кусочки по 3-4 сантиметра.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Порезать и обжарить грибы.','https:https://st.vkuso.ru/data/cache/thumb/83/bd4a295e9712383_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Потереть сыр. Соединить сыр и грибы.','https:https://st.vkuso.ru/data/cache/thumb/ac/5fcf41a97fc74ac_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Положить в фарш яйцо, мелко порезанный лук, посыпать перцем. Размешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Взбить яйцо и соль, насыпать 2 больших ложки муки. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Измельчить чипсы, смешать с панировочными сухарями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Взять чуть-чуть фарша, в середину положить 1 маленькую ложку сырно-грибной массы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Защипнуть края, чтобы получилась котлета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Окунуть в смесь из муки и яйца, потом в панировку.','https:https://st.vkuso.ru/data/cache/thumb/d2/463d259cd0e3dd2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Положить котлетки на противень, отправить на 25-30 минут в духовку, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Через 10-15 минут перевернуть котлеты в духовке, чтобы образовалась корочка с двух сторон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9472,'Можно подавать котлеты с сырно-грибной начинкой в духовке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9473,'Перемешать все сухие ингредиенты, всыпать вишню, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9473,'Влить молоко, хорошо вымешать до получения однородного теста без комков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9473,'Заполнить кружки на две третьи тестом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9473,'Готовить шоколадный магкейк «Минутка» в микроволновке 3 минуты, выставив мощность 800 Вт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9474,'Обжарить на разогретой сковороде ломти хлеба только с одной стороны, другую сторону промазать майонезом.','https:https://st.vkuso.ru/data/cache/thumb/de/e6e849b5a5891de_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9474,'Уложить на него по кусочку сыра, бекона (заранее приготовленного) и мяса.','https:https://st.vkuso.ru/data/cache/thumb/40/8df0da90eec1140_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9474,'Прикрыть парой кружочков помидора, присыпать измельченным луком, положить листья салата.','https:https://st.vkuso.ru/data/cache/thumb/8c/ab5cdc2c1888a8c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9474,'Накрыть готовый сэндвич с мясом, беконом и помидорами другим ломтем хлеба, подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/e5/7651b79b659a2e5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9475,'Смешать яйца и сахар с лимонным соком, всыпать какао, муку, соду.','https:https://st.vkuso.ru/data/cache/thumb/92/6ceeeea3d64b192_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9475,'Вымешать тесто до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/71/7fc60993a2ad571_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9475,'В разогретую сковороду налить масло, прогреть, выпекать нежные шоколадные оладьи на завтрак с двух сторон до зарумянивания на сильном огне.','https:https://st.vkuso.ru/data/cache/thumb/88/6b8003939697188_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9476,'Сварить чечевицу почти до готовности.','https:https://st.vkuso.ru/data/cache/thumb/45/4d019b46305db45_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9476,'Обжарить 15 секунд в сливочном масле перец, асафетиду, кориандр.','https:https://st.vkuso.ru/data/cache/thumb/ce/00127a65b2edbce_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9476,'Добавить в сковороду кубики картофеля и моркови, обжарить практически до готовности.','https:https://st.vkuso.ru/data/cache/thumb/01/292991632720d01_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9476,'Добавить к чечевице содержимое сковороды, добавить лавровый лист, проварить быстрый чечевичный суп с картофелем еще 5 минут.','https:https://st.vkuso.ru/data/cache/thumb/37/b2641a11ba93237_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Тушку цыпленка разрезать вдоль по грудке.','https:https://st.vkuso.ru/data/cache/thumb/04/a81935859e11204_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Смазать растительным маслом.','https:https://st.vkuso.ru/data/cache/thumb/5b/ca92fa591570a5b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Натереть со всех сторон сванской солью (соль крупная, тмин, пажитник, семя укропа, шафран, семя кориандра, горький красный перец, чеснок).','https:https://st.vkuso.ru/data/cache/thumb/37/33444953284a037_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Положить цыпленка спинкой вверх в массивную сковороду.','https:https://st.vkuso.ru/data/cache/thumb/11/2580218545fe911_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Поставить цыплёнка в прогретую духовку, обжарить до полной готовности.','https:https://st.vkuso.ru/data/cache/thumb/b7/6365cc64d729bb7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Для приготовления соуса перемешать нашинкованный укроп и чеснок с подсоленной сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9477,'Готового цыпленка порезать на куски, полить соусом, посыпать зеленью укропа, подать к столу пока горячий.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'В чашу блендера положить масло, покрошить печенье, смешать в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Переложить в форму, сформовать бортики, выпекать основу 15 минут в заранее прогретой до 170 градусов духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Сложить в блендер все ингредиенты начинки. Взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Заполнить ею готовую основу для чизкейка из печенья с творожной начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Оформить верх шоколадной крошкой и дробленым орехом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Убрать в морозильную камеру холодильника на пару часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9478,'Достать десерт, вынуть из формы, переложить на тарелку, подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9479,'Включить для прогревания до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9479,'Разрезать пополам пару-тройку больших головок чеснока, положить на фольгу, побрызгать маслом, посолить, завернуть, но не плотно, а чтобы выходил пар, запекать 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9479,'Удалить с чеснока шелуху, измельчить блендером с базиликом и оливковым маслом, посолить, соус готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9479,'Стейки без кожи обжарить по 2-3 минуты с каждой стороны в оливковом масле с добавлением веточки розмарина, полить лимонным соком, готовить до золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9479,'Со второй стороны обжаривать на малом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9480,'Перемешать сахар с яйцами.','https:https://st.vkuso.ru/data/cache/thumb/14/4256fb57df0fb14_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9480,'Влить кефир, добавить погашенную уксусом соду, всыпать небольшими порциями муку, вымешивая после каждого добавления.','https:https://st.vkuso.ru/data/cache/thumb/87/b441fce65fd1987_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9480,'Добавить в конце какао. Должно получиться однородное тесто похожее на хорошую сметану.','https:https://st.vkuso.ru/data/cache/thumb/e4/d5f7f7806bdace4_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9480,'Заполнить им на 2\3 формочки, отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9480,'Шоколадно-ванильные кексы на кефире будут готовы через полчаса. Вынуть десерт из формочек, дать остыть, покрыть глазурью.','https:https://st.vkuso.ru/data/cache/thumb/43/0e17b603d09de43_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9481,'Разрезать вдоль плоды на две части, каждую – на полоски, до конца не дорезать, посолить и оставить на полчаса для удаления горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9481,'Нарезать пластинками сыр, бекон, помидоры. Если помидоры крупные, то кружки можно разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9481,'Баклажаны промыть от лишней соли, обсушить, выложить в форму для запекания. Между пластинами выложить остальные нарезанные продукты, блюдо поперчить и полить заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9481,'Для приготовления соуса смешать сметану с майонезом в соотношении один к одному или одной сметаной, добавить рубленый чеснок и зелень, любимые специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9481,'Печь баклажаны «Жар-птица» в течение получаса при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Порезать очищенные кабачки без семян на кубики, морковь мелко натереть, помидоры обдать кипятком и снять шкурку, порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Обжарить мелкие кубики лука до прозрачности, добавить морковь, готовить 5 минут до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Добавить кабачки, тушить 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/68/37b85ec8bf50168_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Положить помидоры, готовить еще 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/7c/53fbea3f4f3027c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Через 7 минут положить измельченный чеснок с зеленью.','https:https://st.vkuso.ru/data/cache/thumb/b1/9e2e3af528a52b1_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Для зимней консервации еще добавить на килограмм кабачков по одной-две чайных ложек уксуса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9482,'Измельчить готовые овощи блендером до состояния пюре.','https:https://st.vkuso.ru/data/cache/thumb/89/17c3786f1dfd989_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9483,'Налить в глубокую чашку банановое пюре. Предварительно его лучше немного поварить для загустения, лишняя влага должна испариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9483,'Смешать в сотейнике воду, агар-агар, оставить на десять минут. Поставить сотейник на плиту, довести до кипения, должны появиться пузыри. Всыпать сахарный песок, варить пять-десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9483,'В густое пюре влить половину яичного белка, взбить миксером на небольшой скорости, масса должна посветлеть и увеличиться в объеме. Добавить оставшийся белок, снова взбить до пышности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9483,'Тонкой струйкой влить смесь с агаром, продолжать взбивать до почти полного остывания. Переложить массу в кондитерский мешок и отсадить зефирки на лист пергамента.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9483,'В массу можно добавить пищевые красители и сделать блюдо цветным. Оставить банановый зефир на сутки, затем склеить по две заготовки, обсыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Погасить соду сметаной, добавить растопленное масло, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Небольшими порциями всыпать муку, вымесить тесто, чтобы не липло к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Разделить его на две половины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Порезать на дольки лимон вместе со шкуркой, взбить в блендере, смешать со стаканом сахара.','https:https://st.vkuso.ru/data/cache/thumb/da/d4109ccf6a31dda_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Прогреть до 180 градусов духовку, половину теста положить в форму, сделать бортики, уложить равномерным слоем начинку.','https:https://st.vkuso.ru/data/cache/thumb/df/593d7ca17c565df_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Из другой половины теста раскатать круг и прикрыть верх пирога с лимонной начинкой в духовке, смазать взбитым желтком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9484,'Выпекать примерно полчаса, дать остыть, вынуть из формы, присыпать корицей с сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Обдать креветки кипятком, удалить головы, снять панцири.','https:https://st.vkuso.ru/data/cache/thumb/9d/03548c7d4d5189d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Залить панцири литром воды, варить полчаса.','https:https://st.vkuso.ru/data/cache/thumb/9b/623c5853b056f9b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Мелко порубить пару черешков сельдерея, нашинковать луковицу, пассеровать в разогретом сливочном масле.','https:https://st.vkuso.ru/data/cache/thumb/10/369e87a8cdb6810_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Всыпать половину креветок, добавить томатный соус, всыпать муку, очень хорошо перемешать до получения густой однородной массы, прогреть пару минут, убрать сковороду с плиты.','https:https://st.vkuso.ru/data/cache/thumb/41/0a2d98f4c0c3d41_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Готовый бульон процедить, соединить с содержимым сковороды, перемешать, посолить сырный суп с креветками и сельдереем, поперчить, положить тимьян, несколько лавровых листиков, варить 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/26/b7661db5fdaba26_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Убрать с плиты, достать лавровый лист, разбить блендером до состояния пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9485,'Положить оставшиеся креветки, поставить кастрюлю на плиту, положить ложку плавленого сыра, перемешать до полного его растворения, таким образом добавить весь сыр.','https:https://st.vkuso.ru/data/cache/thumb/0e/8ff0b5775ce610e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Нагреть слегка кислое молоко, добавить сахар, дрожжи, перемешать, дать постоять 10      минут, чтобы дрожжи «проснулись».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Миксером взбить в чаше размягченное масло с яйцом, сливочным сыром, желтками и коричневым сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Добавить, не переставая взбивать, подошедшие дрожжи, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Постепенно, перемешивая всыпать пару стаканов подсоленной муки, довести до однородного состояния, достать из чаши ножи, засыпать полтора стакана муки, вымесить тесто руками до исчезновения комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Готовое эластичное тесто разделить на несколько шариков, оставить их на три часа, чтобы подошли и увеличились в объеме в два раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Для приготовления начинки перемешать мягкое масло с сахаром, мускатным орехом, корицей в однородную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'В небольшой кастрюльке, помешивая довести практически до кипения сливочное масло с медом, сиропом, коричневым сахаром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Когда сахар растворится, снять с плиты, всыпать ванилин, корицу, заполнить массой дно формы для запекания, присыпать порубленным грецким орехом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Раскатать и растянуть из теста прямоугольник, промазать равномерно начинкой по всей поверхности, присыпать сахаром, свернуть в трубочку, разрезать острым ножом на 12 частей.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Переложить булочки в форму с соусом и орехами, прикрыть пленкой, дать постоять пару часов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Поместить форму с булочками с корицей и грецкими орехами под соусом в прогретую до 175 градусов духовку, выпекать четверть часа, достать, плотно упаковать фольгой, вернуть еще на четверть часа в духовку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9486,'Достать форму, «пройтись» по периметру острым ножом, дать немного остыть, аккуратно перевернуть на широкое блюдо, соус должен оказаться сверху.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Разогреть духовку до 220 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Для маринада смешать уксус, апельсиновый сок, цедру, соевый соус, кунжутное семя, имбирь, оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Прямоугольные листы пергамента (примерно 40х35 см или чуть больше) перегнуть пополам для обозначения середины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Точно в середину выложить сладкий болгарский перец и спаржу, побрызгать маринадом.','https:https://st.vkuso.ru/data/cache/thumb/c4/a082831547dd6c4_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Положить по ломтю лосося, вылить на него столовую ложку маринада, хорошо «запаковать».','https:https://st.vkuso.ru/data/cache/thumb/e0/686a19f0cbd01e0_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Переложить пакеты с лососем под апельсиново-имбирным соусом в пергаменте на противень, смазать каждый маслом, отправить на 10 минут в духовку, пока пергамент не начнет темнеть.','https:https://st.vkuso.ru/data/cache/thumb/f0/fb4db7a8c849df0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9487,'Достать противень, разложить по одной порции на тарелку и сразу подать к столу.','https:https://st.vkuso.ru/data/cache/thumb/9a/81c62b65766609a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Залить белые грибы теплой водой, дать разбухнуть около часа.','https:https://st.vkuso.ru/data/cache/thumb/70/5bca97878c38770_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Порезать мясо ломтями, а потом на брусочки, поперчить, посолить, дать постоять.','https:https://st.vkuso.ru/data/cache/thumb/8b/6c8d7da0b8f398b_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Для соуса в растопленном масле обжарить пару столовых ложек муки, влить горячий бульон, перемешать до исчезновения комочков, положить томатную пасту, добавить половину чайной ложки горчицы, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/54/5e8fc2d17ed4954_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Порезать луковицу мелкими кубиками, обжарить в масле до мягкости, добавить отжатые мелко порезанные грибы, обжарить все вместе до готовности.','https:https://st.vkuso.ru/data/cache/thumb/9d/4c04d2ea933749d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Мясо обвалять в муке, обжарить, переворачивая на сильном огне со всех сторон на топленом масле в сковороде с толстым дном.','https:https://st.vkuso.ru/data/cache/thumb/74/8e6395c698c1274_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Переложить соус с грибами в кастрюлю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Добавить мясо, пару столовых ложек сметаны, воду от замачивания грибов, подсолить.','https:https://st.vkuso.ru/data/cache/thumb/d1/0dfa3e6f44eb9d1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Тушить бефстроганов в луково-грибном соусе 10 минут до закипания соуса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9488,'Снять с плиты, перед подачей к столу дать настояться.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Поставить на огонь кастрюлю с водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Свинину или говядину мелко измельчить ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Репчатый лук нарезать тонкими кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Нашинковать соломкой морковь и редьку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Раскалить на сковороде растительное масло, выложить кусочки мяса, прожарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'В конце приготовления добавить овощи, черный молотый перец и соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Через две-три минуты выдавить чеснок, влить соевый соус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Массу перемешать, прогревать еще две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Фунчозу всыпать в кипящую воду, варить в течение четырех-пяти минут, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Готовый продукт должен выглядеть прозрачно-серым.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Лапшу откинуть на сито или дуршлаг, немного отжать, выложить на большое блюдо, можно нарезать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9489,'Сверху – мясной соус, перемешать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Свежие, мягкие дрожжи размять и перемешать с ложкой сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Немного подогреть молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Сливочное масло растопить и охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Сырые куриные желтки перемешать с оставшимся сахаром, солью и ванилином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Муку перемешать с цедрой лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'В готовую закваску всыпать просеянную пшеничную муку, влить молоко и вбить яйцо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Подготовить начинку: перемешать в отдельной емкости сыр «Рикотта», цедру и эссенцию апельсина, сахарный песок, молотый миндаль, небольшое количество взбитых сырых яиц.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Готовое тесто разделить на 12 частей, каждую раскатать в круглую лепешку, надрезать на четыре части, не до конца.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'В середину выложить сырную начинку, немного, по столовой ложке.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Сложить тесто в виде розочки.','https:https://st.vkuso.ru/data/cache/thumb/41/061827168b8b041_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Булочки выложить на противень, накрыть увлажненной тканью, оставить для подъема на полчаса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Смазать изделия взбитыми яйцами, смешанными с водой, сверху – миндальные лепестки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Печь в течение 25 минут до коричневато-золотистого цвета.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9490,'Булочки охладить и посыпать сахарной пудрой.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9491,'Клубни картофеля очистить, вымыть, обсушить и натереть на крупной терке. Лишнюю жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9491,'Отдельно натереть любой сыр, на мелкой терке, порубить репчатый лук, выдавить, с помощью пресса, чеснок. Посолить и поперчить массу по вкусу, вбить яйцо для связки. Перемешать, добавить пшеничную муку, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9491,'На хорошо разогретой сковороде с растительным маслом обжарить картофельные оладушки, выкладывать тесто ложкой. Должна получиться румяная, золотистая, корочка с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9491,'Допечь картофельные драники с сыром под крышкой, в течение нескольких минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9492,'Приготовить овсяную кашу на молоке.','https:https://st.vkuso.ru/data/cache/thumb/d4/3cdfbe9911d2dd4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9492,'В немного остывший продукт добавить мёд, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/2f/c29b34151cd8f2f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9492,'Украсить кушанье голубикой и клубникой.','https:https://st.vkuso.ru/data/cache/thumb/2d/3601f01745e512d_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'В большой огнеупорной кастрюле разогреть оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Мелко нарезать репчатый лук и копченый бекон, обжарить в течение восьми минут до золотистого цвета и мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Оба продукта отодвинуть на край сковороды, добавить кусочки куриного филе. Обжарить мясо до получения румяной корочки в течение трех-четырех минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Добавить рис «басмати», все ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Влить заранее сваренный куриный бульон, добавить кусочки томатов и тонко нарезанные свежие грибы. Соль и перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Довести массу до кипения, накрыть кастрюлю крышкой, поставить в заранее разогретую духовку на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Жидкость должна выпариться, а рис станет мягким.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9493,'Вмешать в плов измельченный базилик, посыпать сыром и подать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Замесить тесто из пшеничной муки, пищевой соды и растопленного сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Массу положить в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Измельчить зеленый лук и грибы, обжарить на сливочном масле, массу перемешать с тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Охлажденное тесто раскатать, выложить в форму, можно вылепить несколько украшений.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Переложить начинку, утопить в неё очищенные головки молодого лука и нарезанные пластинками грибы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9494,'Пирог поставить в духовой шкаф, печь в течение получаса, подать на большом блюде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'В емкости большого размера смешать молоко, сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'Смесь подогреть на тихом огне, до кипения не доводить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'В другой кастрюле перемешать измельченный черный шоколад, соль и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'Влить молоко и всыпать ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'Все перемешать в большой кастрюле, оставить на две минуты на огне, затем разлить в чашки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9495,'Оставшуюся сметану взбить, пенку выложить поверх горячего напитка чайной ложкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Слоеное тесто тонко раскатать, вырезать ровный прямоугольник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Сырое куриное яйцо разболтать и смазать им края для склеивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Тонкие ломтики ветчины выложить внахлест.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Отдельно смешать половину яйца, сливки и тертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Раскатать еще один пласт слоеного теста и закрыть им начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Края защипать руками и вилкой, украсить обрезками, смазать оставшимся яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9496,'Поставить пирог в духовку, печь при температуре в 180 градусов на средней полке. Время приготовления – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Для приготовления блинчиков смешать в блендере сырые куриные яйца, молоко, воду, сливочное масло, соль и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Испечь тонкие блины, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Для начинки растопить сливочное масло на сковороде большого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Измельчить репчатый лук, прогреть до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Огонь убавить до среднего, добавить к луку нарезанные шампиньоны и еще немного масла. Соль и перец молотый – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Потушить обжарку до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Всыпать муку, влить молоко, прогреть до испарения жидкости наполовину, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Добавить тертый сыр «Моцарелла», дать ему расплавиться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9497,'Прослоить готовые блины начинкой и присыпать сверху  тертым пармезаном.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Пшеничную муку, соль, пекарский порошок просеять вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Размягченное сливочное масло взбить с помощью миксера с сахарным песком или пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Вбить сырое куриное яйцо, еще раз взбить.','https:https://st.vkuso.ru/data/cache/thumb/94/03b1b0637d20194_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Всыпать сухие ингредиенты, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Полученное тесто разделить на две одинаковые части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'В одну вмешать какао-порошок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Можно добавить немного муки, если тесто получилось жидковатым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Каждую часть поделить еще раз пополам.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Все четыре кусочка раскатать в плоские лепешки, завернуть в пищевую пленку и поставить в холодильник на час или два, можно оставить на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Раскатать все части в прямоугольники толщиной в один сантиметр, узкая сторона заготовок должна быть 10 см. Снова поставить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/1d/768c6df9994ab1d_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Из одного темного и одного светлого куска нарезать по девять полосок в один сантиметр шириной.','https:https://st.vkuso.ru/data/cache/thumb/11/f3a354602778511_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Сложить их в два бруска по девять полосок, располагать их в шахматном порядке.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Заготовки завернуть в пленку, обжать для уплотнения и придания формы небольшими разделочными досками. Поставить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/c8/401444f020aa7c8_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Вынуть светлый кусок, также раскатать на столе, покрытом пищевой пленкой или пекарской бумагой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Вынуть из холодильника тот брусок, в котором больше темного и завернуть его в светлую лепешку.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Она должна быть по размеру больше бруска по длине и ширине.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Бока выровнять, завернуть в пленку, охладить.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'То же самое проделать с темным тестом и вторым бруском, в котором больше светлого.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Также завернуть в пленку и поставить в холодильник.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Готовые бруски нарезать на равные по толщине квадраты до одного сантиметра толщиной.','https:https://st.vkuso.ru/data/cache/thumb/ed/6648e102a2660ed_434x295.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Печь изделия при температуре 180 градусов или чуть больше в течение 15 минут. Это зависит от характера духовки и толщины печенья.','https:https://st.vkuso.ru/data/cache/thumb/76/c70faba4c508876_434x295.jpg',21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9498,'Выпечку остудить, осторожно переложить на блюдо.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'В чашу блендера всыпать пшеничную муку, какао-порошок, соль и сахарный песок. Добавить сливочное масло, нарезанное кубиками, взбить. Масса должна быть рассыпчатой.','https:https://st.vkuso.ru/data/cache/thumb/1d/64743d034c60e1d_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Влить холодную воду, продолжать взбивать. Тесто должно получиться упругим.','https:https://st.vkuso.ru/data/cache/thumb/3a/5b474f1150c343a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Сплющить колобок в толстую лепешку.','https:https://st.vkuso.ru/data/cache/thumb/7e/7577d79dd8a997e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Завернуть в целлофан или в бумагу, положить в холодильник на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/09/b790aea01151d09_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Охлажденное тесто выложить на присыпанную мукой поверхность, дать полежать десять минут при комнатной температуре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Раскатать тесто в корж толщиной до семи миллиметров, диаметр должен быть немного больше формы для выпечки.','https:https://st.vkuso.ru/data/cache/thumb/aa/adb6e68e9429baa_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Переместить лепешку.','https:https://st.vkuso.ru/data/cache/thumb/d7/5fb88fb2c0770d7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Накрыть заготовку для коржа фольгой, насыпать рис или фасоль, печь при температуре 180 градусов в течение 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9499,'Фольгу вместе с грузом убрать, поставить открытый корж в духовку еще на пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Обрезать мясо с небольших копченых куриных окорочков, порубить его ножом.','https:https://st.vkuso.ru/data/cache/thumb/64/2b4a0439640ba64_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Твердый сыр нарезать одинаковыми кубиками среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/0c/6bb111abdcbe60c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Консервированные маслины без косточек нарезать кольцами.','https:https://st.vkuso.ru/data/cache/thumb/db/3e2cdf6869630db_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Помидоры и огурцы также нарезать небольшими кубиками.','https:https://st.vkuso.ru/data/cache/thumb/3c/09f499d90b5f53c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'В глубокую салатницу выложить куриное мясо, маслины, сыр.','https:https://st.vkuso.ru/data/cache/thumb/53/1e30edc6408ea53_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Добавить огурцы и помидоры.','https:https://st.vkuso.ru/data/cache/thumb/60/556eea408e25560_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9500,'Заправить блюдо французской горчицей, перемешать, посыпать кунжутным семенем.','https:https://st.vkuso.ru/data/cache/thumb/a7/ca6751b6e686ca7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9501,'Авокадо очистить и нарезать кубиками.','https:https://st.vkuso.ru/data/cache/thumb/e4/6324989997f5ee4_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9501,'Одновременно нарезать кубиками помидоры.','https:https://st.vkuso.ru/data/cache/thumb/09/955e011ea11bf09_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9501,'Сразу перемешать, кислота, содержащаяся в помидорах, не даст потемнеть мякоти авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9501,'Измельчить зеленый лук, петрушку и кинзу, сбрызнуть салат лимонным соком.','https:https://st.vkuso.ru/data/cache/thumb/2e/6dc51b162f80c2e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9501,'Перемешать еще раз, добавить по вкусу майонез.','https:https://st.vkuso.ru/data/cache/thumb/75/31c82e0b4795c75_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Почистить и порезать картофель. Посыпать перцем, солью, размешать.','https:https://st.vkuso.ru/data/cache/thumb/04/907046535080904_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Обжарить картофель на оливковом масле до полуготовности на большом огне. Время от времени помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Переложить картофель в огнеупорную форму.','https:https://st.vkuso.ru/data/cache/thumb/ea/00df717aa455bea_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'На масле, оставшемся в сковороде, обжарить чеснок, грибы, лук.','https:https://st.vkuso.ru/data/cache/thumb/b5/e2645b4f952eeb5_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Разрезать пополам помидору, положить к луку и грибам. Посыпать перцем, солью, добавить укроп.','https:https://st.vkuso.ru/data/cache/thumb/1a/20c9bab6e440a1a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Когда овощи пустят сок, положить их к картофелю.','https:https://st.vkuso.ru/data/cache/thumb/89/bf5a79493baf889_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Готовить блюдо 20 минут, соблюдать температуру 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9502,'Можно подавать запеченный картофель с шампиньонами и помидорами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Натереть картофель или использовать кухонный комбайн.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Отжать лишнюю жидкость через чистую марлю.','https:https://st.vkuso.ru/data/cache/thumb/0c/106609f8d488a0c_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Нагреть в глубокой сковороде несколько ложек масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Соединить в посуде картофель, паприку, соль, прессованный чеснок, тмин. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/c2/fbaa7e34cd05bc2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Готовить смесь 6 минут на сковороде, должна появиться коричневая корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Накрыть дном противня, перевернуть.','https:https://st.vkuso.ru/data/cache/thumb/0a/b9b1349175fd50a_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Добавить 2 большие ложки масла, аккуратно вернуть блин не пожаренной стороной на сковороду. Готовить 4 минуты.','https:https://st.vkuso.ru/data/cache/thumb/53/4e94865a9c16553_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9503,'Перед подачей посыпать картофельные драники с паприкой измельченным зеленым луком.','https:https://st.vkuso.ru/data/cache/thumb/e2/2460224d6f1e1e2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Порезать мясо на полоски.','https:https://st.vkuso.ru/data/cache/thumb/b0/1b618fdd24dc6b0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Положить в глубокую емкость, добавить продукты для маринада. Отставить на 30 минут.','https:https://st.vkuso.ru/data/cache/thumb/7e/a2f1eeace82c87e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Нагреть растительное масло на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Положить говядину. Обжаривать несколько минут, помешивая.','https:https://st.vkuso.ru/data/cache/thumb/a1/0de9f4128b677a1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Положить мясо на сито, поставленное на глубокую посуду, чтобы стекло масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Положить на сковороду с растительным маслом, перец чили, жарить 1 минуту, чтобы масло стало острым и ароматным.','https:https://st.vkuso.ru/data/cache/thumb/b9/bc8cec8746c86b9_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Достать перец, мясо вернуть в сковороду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Выпекать 40-45 минут, соблюдать температуру 180 градусов.','https:https://st.vkuso.ru/data/cache/thumb/71/a60edd71e828471_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Положить цедру, соевый соус, сычуаньский перец, соль, кунжутное масло, сахар. Размешать, через 30 секунд убрать с огня.','https:https://st.vkuso.ru/data/cache/thumb/43/4507d975bc81e43_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9504,'Подавать говядину по-сычуаньски с апельсиновой цедрой с рисом и салатом из огурцов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9505,'Сырые куриные яйца взбить с сахаром до увеличения массы в три раза. Просеять муку, перемешать. Тесто должно быть мягким и воздушным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9505,'Небольшой противень застелить бумагой для выпечки, смазать растительным маслом. Вылить тесто. Печь в течение 15–20 минут при температуре 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9505,'Готовый бисквит перевернуть на рабочую поверхность, бумагу снять. Рулет завернуть вместе с полотенцем. Любое варенье разогреть, намазать рулет и оставить в таком виде до полного остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9505,'При подаче смазать верх рулета «Лакомка» тем же вареньем, что использовалось для начинки, посыпать рубленым печеньем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9506,'Отварить небольшой кусок нежирной свинины, измельчить вместе с зеленью с помощью блендера. Нарезать пластинками соленые огурцы, натереть крутые куриные яйца, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9506,'На дно разъемных бортиков, выставленных на тарелку, положить мясо, огурцы, яйца, сыр, все слои промазывать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9506,'Бортики снять, слоеный салат с мясом украсить майонезом, листочками зелени, посыпать кусочками грецких орехов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Измельчить репчатый лук, обжарить. Переложить в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Порезать куриное филе на тоненькие бруски по 1 сантиметру в толщину, обжаривать несколько минут на большом огне в оливковом масле, время от времени перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Положить томатную пасту, посыпать солью, перцем, размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Подержать мясо на огне еще 30 секунд и выложить к луку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Крупно потереть любой полутвердый или твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Положить тортилью на сухую нагретую сковороду, посыпать сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Положить на сыр начинку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Сверху накрыть тортильей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Готовить несколько минут, осторожно перевернуть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Поджарить пару минут с другой стороны.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9507,'Разрезать кесадилью с куриным филе и сыром чеддер на четыре части. Подавать в горячем виде.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Измельчить лук, обжарить на растительном масле. Переложить в емкость, чуть-чуть остудить.','https:https://st.vkuso.ru/data/cache/thumb/be/4a3504ec9220ebe_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Добавить немного взбитое яйцо. Посыпать приправами, солью.','https:https://st.vkuso.ru/data/cache/thumb/19/8b0e13cf197ef19_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Насыпать большую ложку муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Натереть картофель, отжать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Положить в картофель лук с яйцом.','https:https://st.vkuso.ru/data/cache/thumb/65/8268e38bc8b4165_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Размешать.','https:https://st.vkuso.ru/data/cache/thumb/d0/c3c1eca9bb39bd0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Порезать филе тилапии на порционные кусочки.','https:https://st.vkuso.ru/data/cache/thumb/b6/b955708d8c42fb6_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Обвалять в муке. Предварительно кусочки можно натереть солью.','https:https://st.vkuso.ru/data/cache/thumb/d2/7eda3f1a155f9d2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'С двух сторон положить на кусочек картофельную смесь, прижать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Обжаривать 15 минут на растительном масле, один раз перевернуть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9508,'Можно подавать тилапию с хрустящей картофельной корочкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Приготовить тесто: вбить в посуду несколько яиц, насыпать соль, сахар.','https:https://st.vkuso.ru/data/cache/thumb/28/8e57a04df9cfb28_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Размешать.','https:https://st.vkuso.ru/data/cache/thumb/d3/a32363c441246d3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Положить сметану, мягкое сливочное масло. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Насыпать просеянную муку, какао, соду. Размешать, чтобы получилось тесто, как сметана.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Приготовить начинку: размять вилкой творог, вбить яйца. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/1c/9560edeae583e1c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Насыпать ванильный и обычный сахар, манную крупу. Размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Взбить начинку до однородности блендером.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Постелить фольгу или специальную бумагу в форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Положить шоколадное тесто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'В середину осторожно положить начинку.','https:https://st.vkuso.ru/data/cache/thumb/09/4d6c882f5e9a409_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Отправить в холодную духовку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9509,'Вынуть ватрушку из духовки, остудить на решетке. Украсить.','https:https://st.vkuso.ru/data/cache/thumb/99/232605d17905799_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Порезать яблоки на маленькие кубики.','https:https://st.vkuso.ru/data/cache/thumb/67/6316c287be8e367_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Растопить топленое масло, насыпать сахар. Размешивать, пока сахар не подтает.','https:https://st.vkuso.ru/data/cache/thumb/1e/ebb3f737c0cf61e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Положить яблоки, перемешать, чтобы все кусочки обвалялись в сиропе. Тушить 10 минут, чтобы яблоки стали карамельного цвета.','https:https://st.vkuso.ru/data/cache/thumb/f2/f8c3cffec9f78f2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Посыпать корицей, побрызгать соком лимона.','https:https://st.vkuso.ru/data/cache/thumb/09/9a539ad668a5b09_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Перемешать, отправить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/b2/ff934d1f81db9b2_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Просеять муку, соединить с сахаром, разрыхлителем, цедрой лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Отдельно протереть через сито рукотту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Добавить сливочное масло, яйца, ванильную эссенцию, налить молоко.','https:https://st.vkuso.ru/data/cache/thumb/43/d892e2b28868043_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Перемешать до однородности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Соединить творожную смесь и мучную. Размешать.','https:https://st.vkuso.ru/data/cache/thumb/33/616401308cdbb33_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Положить остывшие яблоки.','https:https://st.vkuso.ru/data/cache/thumb/40/82fcb1c63d8cf40_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Положить тесто в формочки, заполнять на 2/3.','https:https://st.vkuso.ru/data/cache/thumb/cf/fa39e311e5bafcf_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Посыпать кунжутом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9510,'Отправить в горячую духовку на 25-30 минут. Не передерживать яблочные маффины с рикоттой, так как может подгореть низ.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Порезать мелко лук, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Крупно порезать морковь, выложить к луку, обжаривать 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Лук и морковь выложить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Обжарить говядину, порезанную на небольшие куски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Положить в сковороду с мясом обжаренную морковь и лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Налить воду, чтобы было покрыто мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Готовить 30 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Положить сухофрукты, готовить еще 30 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Посыпать перцем, солью, добавить барбарис. Готовить 15 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9511,'Можно подавать тушеную говядину с сухофруктами и барбарисом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Подготовить продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Отделить мясо мидий от ракушек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Осторожно вымыть ракушки с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Порезать мелко бекон. Обжарить до румяного цвета.','https:https://st.vkuso.ru/data/cache/thumb/76/d49fb2330a5d176_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Порезать перцы и лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Слить со сковороды лишний жир.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Положить к бекону овощи, обжаривать, пока они не станут мягкими.','https:https://st.vkuso.ru/data/cache/thumb/b8/6ea61ae1ea384b8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Отправить овощи в блендер, чуть-чуть измельчить.','https:https://st.vkuso.ru/data/cache/thumb/51/2c5db0993a6ff51_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Убрать овощи в морозилку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Соединить 120 грамм сливочного масла, сок лимона, устричный соус, остывший бекон и овощи, соус Табаско.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Смешать до однородности, посолить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Добавить дольку чеснока.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Растопить сливочное масло, смешать с хлебными крошками.','https:https://st.vkuso.ru/data/cache/thumb/30/915c21806392930_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Убрать с огня, остудить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Выложить мясо мидий в ракушки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Положить на мидии по маленькой ложке смеси, осторожно распределить.','https:https://st.vkuso.ru/data/cache/thumb/14/136144df39dcf14_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Намазать хлебными крошками.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Выложить на противень.','https:https://st.vkuso.ru/data/cache/thumb/b6/c98fc7151e48cb6_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Надо положить так, чтобы не вытек сок во время готовки.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'На ровном противне под ракушки положить спички, чтобы ракушки стояли ровно.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Отправить на 10 минут, хлебные крошки должны стать румяными.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'Соблюдать температуру 200 градусов.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9512,'На мидии выдавить сок лайма. На гарнир приготовить рис. Перед подачей мидии Казино с беконом полить соком лайма.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Подготовить необходимые продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Соединить сок лайма, оливковое масло, горчицу, прессованный чеснок. Перемешать, отставить.','https:https://st.vkuso.ru/data/cache/thumb/b3/011810bf80e49b3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Вымыть и обсушить овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Положить фасоль в кипящую воду, подсолить. Готовить 5 минут. Чтобы стручки остались зелеными, добавить ледяную воду.','https:https://st.vkuso.ru/data/cache/thumb/61/d8270f8d7643061_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Порезать перец на тонкие кольца.','https:https://st.vkuso.ru/data/cache/thumb/31/a0cf31a36097a31_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Лук порезать на полукольца. Чуть-чуть размять.','https:https://st.vkuso.ru/data/cache/thumb/5f/359c0ca5bbb815f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Положить на тарелку салатные листья, перец, лук.','https:https://st.vkuso.ru/data/cache/thumb/62/7a6b3ff8f177062_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Разрезать стручки фасоли на три части, отрезая кончики.','https:https://st.vkuso.ru/data/cache/thumb/fa/232ab0467b138fa_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Положить фасоль и порезанные помидоры на лук.','https:https://st.vkuso.ru/data/cache/thumb/43/dba7a27bc8c6143_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Измельчить петрушку, положить в салат.','https:https://st.vkuso.ru/data/cache/thumb/2c/fee047cf923722c_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Посыпать перцем, солью, полить заправкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Осторожно перемешать, используя две вилки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9513,'Посыпать овощной салат с горчично-чесночной заправкой пармезаном.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Подготовить все необходимые продукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Обжарить капусту, поделенную на соцветия, на растительном масле несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Положить асафетиду и рис. Обжаривать минуту.','https:https://st.vkuso.ru/data/cache/thumb/ea/84242dce57ecaea_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Налить воду, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/35/c7198db663c7535_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Посыпать солью, накрыть крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Когда рис впитает 80 процентов воды, приблизительно через 10-15 минут, положить молотый мускатный орех, размешать. Накрыть крышкой.','https:https://st.vkuso.ru/data/cache/thumb/ff/70cc850b0cbfdff_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Приготовить соус: натереть сыр, соединить со сливками, мукой, крахмалом, солью. Перемешать.','https:https://st.vkuso.ru/data/cache/thumb/a1/010bfec6216afa1_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Влить соус, размешать. Накрыть крышкой.','https:https://st.vkuso.ru/data/cache/thumb/f7/b9122ed7f6f62f7_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9514,'Уменьшить огонь. Отставить на 5 минут. Можно подавать сытную запеканку из цветной капусты с сырным соусом.','https:https://st.vkuso.ru/data/cache/thumb/7e/5ed2043f415dc7e_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Подготовить ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Отварить рис и картофель. Крупно потереть картофель. Обжарить морковь.','https:https://st.vkuso.ru/data/cache/thumb/60/1a646538fcf5760_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Все соединить, добавить специи и зелень, размешать.','https:https://st.vkuso.ru/data/cache/thumb/0e/e169da89c99330e_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Сформировать котлетки, обвалять в специальных сухарях.','https:https://st.vkuso.ru/data/cache/thumb/a2/a2d077ef5bd30a2_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Обжарить во фритюре.','https:https://st.vkuso.ru/data/cache/thumb/6b/49e99ed70e62b6b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9515,'Откинуть картофельные котлеты с морковью и рисом на дуршлаг.','https:https://st.vkuso.ru/data/cache/thumb/39/80dc75100454539_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Нарезать хлеб поперек дольками, не до конца, батон должен сохранить форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Пропустить чеснок через пресс, смешать с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Смесью густо намазать дольки.','https:https://st.vkuso.ru/data/cache/thumb/d3/6f1447106ac81d3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Колбасу нарезать кольцами. Можно использовать продукт любого сорта.','https:https://st.vkuso.ru/data/cache/thumb/15/5a7cec0aeb71615_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Так же поступить с колбасным сыром.','https:https://st.vkuso.ru/data/cache/thumb/f9/61b6bf1a9fbaff9_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Наполнить разрезы тем и другим.','https:https://st.vkuso.ru/data/cache/thumb/0d/59d6e5465a3fd0d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Отправить все в духовой шкаф на 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9516,'Перед подачей смазать батон сливочным маслом и кетчупом, посыпать зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Мелко нарезать куриное филе, грибы и репчатый лук, обжарить продукты до готовности на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Соль и перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Добавить сметану, довести до кипения, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Вынуть мякиш из разрезанного вдоль багета, наполнить его готовой начинкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Выложить в застеленную фольгой форму для запекания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Посыпать багет тертым сыром, украсить дольками помидоров, зеленью, грибами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9517,'Печь в духовке при температуре 200 градусов в течение 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Вымыть стебли сельдерея и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Очистить репчатый лук, нарезать крупными кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Выложить оба продукта на противень, сбрызнуть оливковым маслом и поставить в духовой шкаф на 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/18/20840088f94e418_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Выложить окорочка, обжарить до румяной корочки с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/7e/bca9a33c6ae097e_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Раздавить чеснок вместе с шелухой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Отделить от стеблей листочки розмарина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Готовые овощи вытащить из духовки и выложить поверх окорочков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Соль и перец молотый – по вкусу, добавить веточки тимьяна и чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Залить блюдо двумя третями бутылки красного сухого вина, накрыть крышкой и тушить в течение часа.','https:https://st.vkuso.ru/data/cache/thumb/c0/6a19fb538e147c0_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'Через час кастрюлю открыть, дать вину выкипеть.','https:https://st.vkuso.ru/data/cache/thumb/a7/31facd75b2948a7_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9518,'При подаче курицу можно украсить кружочками помидоров, веточками розмарина и другой зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Нарезать мясо (свинину или говядину) кубиками среднего размера.','https:https://st.vkuso.ru/data/cache/thumb/39/6dd3d18a7030239_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Репчатый лук нарезать четвертинками.','https:https://st.vkuso.ru/data/cache/thumb/48/af40a8a6940a948_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Перемешать мясо с луком, перцем, солью и хмели-сунели.','https:https://st.vkuso.ru/data/cache/thumb/8c/2fd15dabfb9e58c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Дать настояться два-три часа в прохладном месте.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Замочить деревянные шпажки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Нанизать мясо вперемешку с луком.','https:https://st.vkuso.ru/data/cache/thumb/92/e843dc60fe81592_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9519,'Поставить в духовку на 15 минут.','https:https://st.vkuso.ru/data/cache/thumb/d7/bab90f6bc8d10d7_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Яблоки очистить от кожуры, семена удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Плоды нарезать пластинками, уложить на дно формы, смазанной сливочным маслом.','https:https://st.vkuso.ru/data/cache/thumb/75/354e28215e65775_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Духовку разогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Взбить сырые куриные яйца до однородного состояния, добавить сахарный песок, взбивать все вместе пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Ввести муку в несколько приемов, тесто не должно быть слишком густым.','https:https://st.vkuso.ru/data/cache/thumb/7a/00c709d3d33857a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Залить яблоки.','https:https://st.vkuso.ru/data/cache/thumb/ad/65cf3f0e5a83aad_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9520,'Печь шарлотку в течение 25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Перемешать сахарный песок с морской солью и черным молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Филе семги с кожей разрезать пополам, обвалять куски в смеси со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/a5/4770f0ca12400a5_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Мелко нарезать свежий зеленый укроп, перемешать с сушеным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Посыпать филе и этой смесью, сложить куски стопкой и завернуть в пищевую пленку.','https:https://st.vkuso.ru/data/cache/thumb/61/ad4ef44b4aa7961_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Рыбу поместить под пресс и оставить при комнатной температуре на 10 или 12 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'Убрать в холодильник на 12 часов или больше.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9521,'При подаче слой специй удалить, филе нарезать тонкими ломтиками.','https:https://st.vkuso.ru/data/cache/thumb/88/6846b636c353988_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Добавить сухие дрожжи в теплое молоко вместе с небольшим количеством сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Смесь оставить на несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Яйца комнатной температуры взбить в пышную пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'В емкости большого размера смешать муку с солью, добавить мягкое сливочное масло, сахар, яйца, закваску.','https:https://st.vkuso.ru/data/cache/thumb/5e/74e1cf46d507f5e_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Вымесить тесто, оно не должно липнуть к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Поместить массу в форму, смазанную маслом, накрыть полотенцем, поставить в тепло на час. Тесто должно увеличиться в два раза.','https:https://st.vkuso.ru/data/cache/thumb/96/4983817f380eb96_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Рабочую поверхность посыпать мукой, раскатать тесто в пласт толщиной до пяти миллиметров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Поверхность смазать остатками сливочного масла, посыпать смесью сахара и молотой корицы, свернуть в рулет.','https:https://st.vkuso.ru/data/cache/thumb/c8/009a820434db5c8_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Нарезать заготовку ломтиками толщиной в три-четыре сантиметра, выложить в смазанную форму.','https:https://st.vkuso.ru/data/cache/thumb/75/d08e222f73dd175_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Печь в духовом шкафу при температуре 190 градусов в течение получаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Для крема отдельно смешать сыр «Маскарпоне», ванильный сахар, сахарную пудру. Масса должна быть гладкой и однородной.','https:https://st.vkuso.ru/data/cache/thumb/77/4f79ab8fd608977_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9522,'Готовые булочки вынуть из духовки, остудить в течение трех минут и смазать выпечку сырным кремом.','https:https://st.vkuso.ru/data/cache/thumb/9f/0371c96135aa79f_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Филе нарезать небольшими кусочками, обжарить с растительным маслом на сковороде.','https:https://st.vkuso.ru/data/cache/thumb/83/5ca478f2c882483_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Очищенный репчатый лук нарезать и тоже обжарить на масле.','https:https://st.vkuso.ru/data/cache/thumb/8f/441b2542072028f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Развести водой сметану, хорошо перемешать, посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Мясо выложить в горшочки, положить лук, перец и соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Нарезать картофель небольшими кусочками, разложить поровну в горшочки.','https:https://st.vkuso.ru/data/cache/thumb/5a/0e2ef0448f11e5a_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Подлить сметанный соус.','https:https://st.vkuso.ru/data/cache/thumb/7f/29238e84bf6717f_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9523,'Запекать порции в заранее разогретой духовке в течение получаса, температура приготовления – 240-260 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'В глубокой емкости соединить муку, картофельный или кукурузный крахмал, соль и разрыхлитель. Ингредиенты хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Белки отделить от желтков. Последние перемешать и взбить с растительным маслом, кефиром и молоком. Можно использовать погружной блендер.','https:https://st.vkuso.ru/data/cache/thumb/70/d4f4f3cc84e3370_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Белки взбить отдельно с сахарным песком и ванилином.','https:https://st.vkuso.ru/data/cache/thumb/f5/d891c54105fecf5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Все три смеси соединить с помощью миксера.','https:https://st.vkuso.ru/data/cache/thumb/41/2bb48842809f341_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Печь тесто в вафельнице.','https:https://st.vkuso.ru/data/cache/thumb/d7/7d2601b894b58d7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Готовые изделия выложить на противень. Поставить подсушиться в духовку до образования хрустящей корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9524,'Готовую выпечку выложить на тарелки, украсить взбитыми сливками, размороженными или свежими ягодами, шоколадной пастой. Десерт посыпать сахарной пудрой и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Прогреть в сотейнике на тихом огне сливки с сахарным песком и сливочным маслом.','https:https://st.vkuso.ru/data/cache/thumb/8a/f82e6805209b28a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Снять смесь с огня, всыпать кокосовую стружку и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/02/46b13a617289b02_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Из полученной массы сформовать конфеты, выложить на бумагу для выпекания.','https:https://st.vkuso.ru/data/cache/thumb/c9/389f4923bf6fec9_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Убрать конфеты в морозилку на полтора-два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Шоколад измельчить, прогреть на водяной бане, можно добавить сливочное масло или молоко.','https:https://st.vkuso.ru/data/cache/thumb/e3/ccfe4a09e64d4e3_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9525,'Застывшие конфеты наколоть зубочисткой, окунуть в глазурь, выложить на бумагу для выпекания и вернуть в морозильную камеру на час.','https:https://st.vkuso.ru/data/cache/thumb/7c/9552139a342fc7c_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Нарезать репчатый лук кубиками, обжарить на растительном масле до прозрачности.','https:https://st.vkuso.ru/data/cache/thumb/c8/a2d3f240e36d0c8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Филе курицы нарезать кубиками небольшого размера, добавить в луковую обжарку, прогревать, помешивая.','https:https://st.vkuso.ru/data/cache/thumb/63/078e19568201263_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Добавить в смесь готовую фасоль и соус чили по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/da/10f324e29487bda_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Нарезать кубиками сладкий болгарский перец, положить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Томатная паста, соль, перец, лимонный сок – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9526,'Выложить начинку на листы лаваша, свернуть конвертами, сухие края можно обрезать.','https:https://st.vkuso.ru/data/cache/thumb/d4/643af61ad0b28d4_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9527,'Яблоки разрезать пополам и выложить в емкость для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9527,'Намазать на плоды мёд, присыпать смесью рубленых грецких орехов с корицей, гвоздикой, имбирем, мускатным орехом и коричневым сахаром.','https:https://st.vkuso.ru/data/cache/thumb/88/1fbc67ea869f988_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9527,'На каждую половину яблока положить по кусочку сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9527,'Печь при температуре 190 градусов до готовности.','https:https://st.vkuso.ru/data/cache/thumb/b9/596c03004d6c9b9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Розовый, белый и черный перец, можжевельник, сахар и соль поместить в кофемолку или ступку.','https:https://st.vkuso.ru/data/cache/thumb/76/3c2857ae495a376_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Продукты размолоть.','https:https://st.vkuso.ru/data/cache/thumb/5d/bbd657de39b765d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'В небольшой емкости перемешать тертый имбирь, цедру и сок грейпфрута, протертые специи с солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Все ингредиенты перемешать, выложить филе семги.','https:https://st.vkuso.ru/data/cache/thumb/2f/fec52975bb7f62f_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Добавить черри, мелко нарезанный шпинат и чеснок с креветками, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Поставить рыбу в холодильник, через час продукт перевернуть кожей вверх и оставить еще на час.','https:https://st.vkuso.ru/data/cache/thumb/30/760e189e377c530_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Разогреть растительное масло на сковороде с антипригарным покрытием.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Выложить филе кожей вниз, прижать лопаткой, пока не образуется корочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Кусочки перевернуть, жарить до полной готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9528,'Рыбу снять с огня, переложить на тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'Репчатый лук и чеснок мелко нарезать, обжарить на сковороде с растительным маслом в течение одной-двух минут.','https:https://st.vkuso.ru/data/cache/thumb/03/a0ee2e6c2df7203_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'Добавить смесь говяжьего и свиного фарша, обжарку перемешать и прогревать до полуготовности на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/0d/82d95e215ae5f0d_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'Помидоры бланшировать, очистить от кожицы, нарезать мелкими кубиками.','https:https://st.vkuso.ru/data/cache/thumb/91/f608733937cd791_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'Добавить в фарш, соль и перец – по вкусу. Продолжать прогревать до испарения влаги.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'В готовую смесь положить рубленую зелень петрушки, перемешать и остудить.','https:https://st.vkuso.ru/data/cache/thumb/8c/1426cfbaa90fa8c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9529,'На готовую тортилью выложить начинку и ломтики плавленого сыра, ролл свернуть и обжарить с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/d0/ec6f0ca3b3ce3d0_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Телятину с косточкой обвалять в муке.','https:https://st.vkuso.ru/data/cache/thumb/79/48a6f0fa2da3579_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Обжарить на растопленном сливочном масле со всех сторон.','https:https://st.vkuso.ru/data/cache/thumb/e2/854add06e6ba3e2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Оставить мясо готовиться на среднем огне, подливать готовый говяжий бульон.','https:https://st.vkuso.ru/data/cache/thumb/17/f2502d91f884017_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Блюдо готовится в течение часа, если мясо молодое, в противном случае время приготовления увеличивается до двух часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Влить белое сухое вино, потомить на среднем огне до выпаривания жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Влить бульон еще раз, накрыть сковороду крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9530,'Через 10 минут влить еще половник бульона и положить томатную пасту.','https:https://st.vkuso.ru/data/cache/thumb/84/ed0e835684a5384_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Измельчить 150 г печенья в крошку при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Положить растопленное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Постелить в форму специальную бумагу. Положить массу в форму, утрамбовать. Уплотнить, используя ложку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Отправить в морозилку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Положить в термостойкую емкость 200 грамм масла и горького шоколада, поставить на водяную баню.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Перемешать смесь до однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Взбить желтки с сахаром, соединить с шоколадно-масляной смесью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Налить ликер, положить изюм, орехи, нарезанный инжир и 75 грамм поломанного печенья.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Выложить начинку на подготовленную основу, равномерно распределить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Отправить в морозилку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Вскипятить сливки. Убрать с огня, положить поломанный молочный шоколад, размешать до однородности. Получится консистенция, как густой йогурт.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Покрыть глазурью застывшую начинку, отправить на несколько часов в морозилку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9531,'Перед подачей дать торту «Шоколадная маркиза с ликером» настояться и снять края формы.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Подготовить продукты для маринада.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Промыть курицу, порезанную на части, положить в большую посуду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Замариновать мясо: побрызгать соком лимона, оливковым маслом. Размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Полить мясо белым вином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Посыпать специями: перцем, орегано.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Добавить измельченный лавровый лист и чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Добавить чернослив, оливки, каперсы. Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Мариновать более 2 часов.','https:https://st.vkuso.ru/data/cache/thumb/35/e284e02c7fe4c35_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Положить курицу с маринадом в форму.','https:https://st.vkuso.ru/data/cache/thumb/4a/b7ded2c2553ad4a_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Готовить 30-40 минут, соблюдать температуру 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9532,'Подавать курицу в маринаде с черносливом с любым гарниром, к примеру, рисом. Полить маринадом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Поставить варить карамель, довести до кипения, дать чуть загустеть (при остывании загустеет хорошо).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Порубить миндаль, переложить на пергаментный лист, залить карамелью, дать хорошо остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приготовить нежный бисквит.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Измельчить миндаль, перемешать с яйцами и большей частью сахарной пудры, взбить около 10 минут до светлого и густого состояния массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'В тесто в три раза добавить горячее масло и просеянную муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'В чашу блендера поместить белки, взбить до пиков, сохраняющих форму, постепенно всыпая по ложке сахарную пудру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Осторожно лопаточкой движениями снизу вверх, объединить белки с тестом.','https:https://st.vkuso.ru/data/cache/thumb/b2/5bb0fb0574bf4b2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Заполнить тестом форму (дно выстлать пергаментом), поместить ее в прогретую до 220 градусов духовку примерно на треть часа, остудить прямо в форме, а потом убрать в морозилку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Для приготовления крема желатин залить холодной водой, дать постоять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Взбить до состояния густого крема сахар и желтки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'В небольшую кастрюльку, желательно с толстым дном, влить сливки, положить стручок ванили или ванильный сахар, перемешать, прогреть, но до кипения не доводить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Горячие сливки соединить с желтковой массой, поместить в кастрюльку, нагреть, помешивая до 85 градусов до загустения.','https:https://st.vkuso.ru/data/cache/thumb/64/b7d628f9f8ae764_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Убрать крем с плиты, влить процеженный раствор желатина, перемешать, добавить взбитые до пиков сливки, хорошо перемешать, дать остыть.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приготовить пропитку, сварить сироп, добавить в него после закипания сок апельсина, немного проварить, дать остыть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Остывший бисквит разделить на две части, одну оставить, из второй вырезать меньший по диаметру круг, нанести пропитку на обе части.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Обрезанный маленький бисквит положить на дно в маленькую форму, пропитать, дать постоять 5 минут, залить кремом, убрать на час в морозилку.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приготовить хрустящий слой, раздробить пралине в мощном комбайне до состояния крошки.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Растопить белый шоколад, положить к нему масло, половину пралине и измельченные орехи, тщательно перемешать, смазать равномерным слоем больший корж, убрать в холодильник.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Достать меньший бисквит, вынуть его, залить желе, поставить в морозилку на полчаса.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приготовить мусс, разбить блендером клюкву, протереть сквозь сито, желатин залить водой комнатной температуры.','https:https://st.vkuso.ru/data/cache/thumb/67/400a809b406bd67_434x295.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Приготовить меренгу, взбитые до устойчивых пиков белки «заварить» при взбивании (вливать тоненькой струйкой) сахарным сиропом.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Сироп предварительно уварить до «плотного шарика».',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Прогреть треть клюквенного пюре с желатином, процедить, смешать с оставшимся пюре, а потом очень осторожно с меренгой, ввести взбитые до пиков сливки.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Последний этап – сборка торта.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Застелить разделочную доску плотной пленкой, установить кольцо, заполнить его 2/3 мусса из клюквы, уложить на него (кремом вверх) заготовку из морозилки, чуть вдавить ее.','https:https://st.vkuso.ru/data/cache/thumb/01/220d379a1cac601_434x295.jpg',25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Уложить остатки мусса, прикрыть бисквитом, чуть прижать, поместить на ночь в холодильник, утром переместить на пару часов в морозилку.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Для украшения нарезать шоколадные квадраты, подкрасить расплавленный белый шоколад кандурином.',NULL,27);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'В завершении приготовить глазурь, желатин залить водой комнатной температуры (1,5 ст.л.), перемешать воду с сахаром, прогреть ее до кипения.',NULL,28);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Перемешать сгущенку с жидким шоколадом, смешать с процеженным желатином, влить сироп с красителем, тщательно перемешать, взбить блендером, дать остыть на водяной бане до 40 градусов.',NULL,29);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Вынуть торт из морозилки, установить на решетку, залить третьей частью глазури, дать постоять пару-тройку минут, вылить еще глазурь, пока торт еще достаточно холодный, дать чуть постоять, вылить третий слой глазури, дать остыть пару минут, разровнять поверхность ножом.','https:https://st.vkuso.ru/data/cache/thumb/0c/9a9c71221e58d0c_434x295.jpg',30);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9533,'Убрать на 5 минут торт в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/a4/6c80171dcc7c2a4_434x295.jpg',31);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Залить горячим молоком батон, дать постоять 10 минут.','https:https://st.vkuso.ru/data/cache/thumb/de/7fb08b33c615fde_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Очистить овощи, мелко натереть картофель.','https:https://st.vkuso.ru/data/cache/thumb/06/e8ed7aa17450906_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Натереть морковь и свеклу.','https:https://st.vkuso.ru/data/cache/thumb/7c/0e0df924e9ca07c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Нашинковать мелко лук.','https:https://st.vkuso.ru/data/cache/thumb/df/6a9fe69628500df_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Объединить овощи, фарш, яйца, размоченный батон, перемешать до однородной и достаточно жидкой массы.','https:https://st.vkuso.ru/data/cache/thumb/45/cc48e286cea1445_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Скатать из него небольшие колобочки, испечь около часа в духовке при температуре в 180 градусов, присыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/65/5af1ed1cf612565_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Снизить температуру до 150 градусов, выпекать курино-овощные тефтели в духовке еще полчаса.','https:https://st.vkuso.ru/data/cache/thumb/36/9e33c5b018ec636_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9534,'Подавать блюдо можно как с гарниром, так и без.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Раздробить мак в кофемолке, всыпать манку с разрыхлителем, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Натереть очищенное яблоко на средней терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Взбить миксером в пышную пену сахар и белки около 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Перемешать с яблоками и маковой смесью, добавить мягкое масло, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Подготовить противень, застелить пекарской бумагой, вылить подготовленную массу, запекать при 180 градусах треть часа, дать остыть на противне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Для медовых коржей взбить около 10 минут с помощью миксера сахар с яйцами в пышную пену.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Прогреть мед в микроволновке, всыпать соду, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Объединить медовую и яичную смеси, всыпать частями муку (предварительно ее просеять), тщательно перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Массу вылить на противень, выпекать около 25 минут при температуре 180 градусов, дать остудить на противне.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Для крема жирную сметану взбить с сахаром и ванилью в однородную густую массу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Разделить вдоль коржи на две части, промазать равномерно кремом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Собрать маково-медовый пляцок, чередуя коржи, верх десерта смазать тоже кремом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9535,'Поставить на ночь в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Помыть и очистить овощи, порезать на кубики.','https:https://st.vkuso.ru/data/cache/thumb/35/78169fe6cae8d35_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Засыпать в кастрюлю с разогретым маслом, перемешать, протушить примерно 4 минуты.','https:https://st.vkuso.ru/data/cache/thumb/bd/5f2f6bcbf10dbbd_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Залить горячим бульоном (молоком) так, чтобы чуть прикрыть овощи, нагрев сделать минимальным, готовить под крышкой до полной готовности около 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/60/cac6e2ebeb3a660_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Поместить содержимое кастрюли в чашу блендера, разбить до состояния пюре.','https:https://st.vkuso.ru/data/cache/thumb/80/4d55b6e30973380_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Вернуть в кастрюлю, поперчить, подсолить, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/ae/5fe233bda0774ae_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9536,'Нагреть морковный суп-пюре с сельдереем и чесноком до кипения, снять с плиты, дать постоять минут 10 под крышкой, подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Подготовить мясо, прокрутить на мясорубке.','https:https://st.vkuso.ru/data/cache/thumb/20/7987b5c7d51ac20_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Добавить порубленную зелень, нашинкованный лук, перемешать, заправить перцем, подсолить.','https:https://st.vkuso.ru/data/cache/thumb/80/2a40220aa9e4f80_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Прокрутить отдельно чеснок, лук, стручки зеленого перца, сдобрить специями, перемешать с фаршем.','https:https://st.vkuso.ru/data/cache/thumb/ce/777ad9f3f61b0ce_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Влить в смесь воду, тщательно взбить.','https:https://st.vkuso.ru/data/cache/thumb/01/f26064a18028601_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Просеять на плоскую поверхность горкой муку, сделать на вершине углубление, влить очень холодную подсоленную воду, вымесить достаточно крутое и эластичное тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Из теста раскатать тонкие кружки, положить по центру фарш.','https:https://st.vkuso.ru/data/cache/thumb/89/666b55165ee5e89_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Собрать края узелком, делая до 18 складочек.','https:https://st.vkuso.ru/data/cache/thumb/2a/ab34b08c965162a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Верхушку срезать.','https:https://st.vkuso.ru/data/cache/thumb/c6/735ada23bb809c6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9537,'Варить свино-говяжьи хинкали с зеленью около 13 минут до всплытия, вынуть аккуратно на блюдо шумовкой, обдать холодной водой, подать к столу с душистым перцем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Включить для прогрева до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Взбить блендером до образования пены белки с сахаром (всыпать малыми порциями).','https:https://st.vkuso.ru/data/cache/thumb/74/bcd3af6d3b1a874_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Лопаточкой смешать белки с сухими ингредиентами (добавлять порциями) в воздушное тесто.','https:https://st.vkuso.ru/data/cache/thumb/d9/90a1effe94896d9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Заполнить массой кондитерский шприц, высадить тесто на противень, выстланный пергаментом, выпекать четверть часа.','https:https://st.vkuso.ru/data/cache/thumb/f7/289d620a3c74ff7_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Приготовить крем, всыпать ягоды в чашу блендера, измельчить в пюре, протереть его через сито.','https:https://st.vkuso.ru/data/cache/thumb/5b/e3617538df4a95b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Поместить пюре в сотейник, перемешать с кукурузным крахмалом, довести, помешивая, до кипения, проварить до сгущения, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/1b/482dd4cc7f4171b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Взбить сливки и холодное ягодное пюре.','https:https://st.vkuso.ru/data/cache/thumb/e9/9cede8a0f0ee9e9_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9538,'Соединить печенье попарно, промазав внутри черничным кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9539,'Смешать творог с яйцами, сахаром, ванилином.','https:https://st.vkuso.ru/data/cache/thumb/dc/4f57c0a59cfb4dc_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9539,'Всыпать манку, добавить масло, сметану и разрыхлитель, перемешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/a2/85be97156e2aaa2_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9539,'Заполнить массой формочки, поместить их в прогретую до 200 градусов духовку.','https:https://st.vkuso.ru/data/cache/thumb/71/320d3878f62a871_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9539,'Готовить ванильные сырники в формочках полчаса, дать остыть.','https:https://st.vkuso.ru/data/cache/thumb/33/4ff7208049d6133_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9539,'Вынуть из формочек, подать к столу со сметаной или вареньем.','https:https://st.vkuso.ru/data/cache/thumb/9c/27b34c6a30eb19c_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9540,'Вымыть филе, обсушить, порезать на кубики, добавить измельченный чеснок, влить масло, приправить соком лимона, прованскими травами, подсолить, оставить на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9540,'Очистить от кожуры кабачок, сладкий перец от семян, копченную грудинку порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9540,'На шампуры нанизать попеременно мясо, овощи, маслины и грудинку, обжарить шашлычки из индейки и грудинки с овощами над углями около 5-6 минут, периодически переворачивая.','https:https://st.vkuso.ru/data/cache/thumb/f5/e751ef73629dbf5_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9540,'Подать к столу горячими с соусом из измельченного огурца, чеснока и йогурта, сдобренных перцем и солью.','https:https://st.vkuso.ru/data/cache/thumb/2d/9bb058fa43dc62d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Нашинковать мелко лук и чеснок, обжарить их до прозрачности в разогретом масле вместе с сушеными травами.','https:https://st.vkuso.ru/data/cache/thumb/0a/1eb2304b8c0160a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Добавить измельченный шпинат, протушить пару минут, положить в соус мякоть помидоров, подсолить, перемешать, тушить все вместе при слабом нагреве 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Включить для прогрева до 200 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Хорошо перемешать сливки с рикоттой, измельчить моцареллу, пармезан измельчить на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Перемешать половину пармезана с рикоттой и моцареллой.','https:https://st.vkuso.ru/data/cache/thumb/48/a3313f32f768f48_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Вылить в форму немного красного соуса, положить лист лазаньи, покрыть его белым сырным соусом (он должен полностью закрыть лист), повторить все до окончания листов, верх сырной лазаньи со шпинатом и помидорами присыпать оставленной частью пармезана.','https:https://st.vkuso.ru/data/cache/thumb/41/12cf024619e9641_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9541,'Запекать около 20 минут, подать блюдо горячим, украсив базиликом и половинками черри.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Включить для разогрева до 190 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Очищенный чеснок растереть с приправой «итальянские травы с гималайской солью», порубить мелко перья зеленого лука, перемешать с чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Добавить козий сыр, подсолить, поперчить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Грудки прорезать сбоку до получения кармашка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Мясо чуть отбить, заполнить сырной начинкой, завернуть в полоски бекона.','https:https://st.vkuso.ru/data/cache/thumb/49/10af06de0efac49_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Переложить фаршированные куриные грудки козьим сыром с зеленью вплотную друг к другу на глубокий противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Побрызгать маслом, присолить, поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9542,'Запечь полчаса в уже прогретой духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Приготовить бисквит, смолоть в кофемолке миндаль или кешью до состояния муки, смешать ее с сахарной пудрой, пшеничной мукой, ванильным сахаром и разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9543,'Достать торт, вынуть из формы, присыпать стружкой кокоса, оформить дольками апельсина.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9544,'Подготовить грудки, помыть, обсушить, сделать разрез в виде кармашка, сдобрить мясо солью и перцем снаружи и внутри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9544,'Заполнить каждую грудку базиликом и кусочками помидора, заколоть края зубочистками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9544,'Разогреть сковороду с подсолнечным маслом, обжарить куриные грудки с помидорами и свежим базиликом до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'Хлопья необходимо заранее залить жидкостью и дать немного разбухнуть, для этого потребуется от 10 до 15 минут. Варианты заливки: смесь обезжиренного молока и домашнего йогурта, обычное молоко, кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'Приготовить фарш из куриной грудки вместе с луком и чесноком, продукты измельчить с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'Массу переложить в миску, вбить сырое куриное яйцо. Разбухшие хлопья соединить с готовым фаршем, соль и молотый перец – по вкусу, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'По желанию добавить специи, измельченную зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'На смазанную оливковым маслом сковороду выложить оладьи небольшого размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9545,'Подождать, пока они немного обжарятся, огонь убавить, довести до готовности под крышкой, один раз перевернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Капусту залить водой, посолить, отварить до готовности, можно использовать как свежий, так и замороженный продукт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Жидкость слить, измельчить в пюре с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Для приготовления соуса перемешать домашний натуральный йогурт, дижонскую горчицу и соевый соус. По желанию добавить перец и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Куриное филе разрезать на две части вдоль, отбить через пищевую пленку, посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Треть соуса перемешать с овощным пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Одну отбивную переложить в форму для запекания, промазать полученным соусом, пюре распределить сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Накрыть блюдо сверху оставшейся отбивной, залить остатками соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9546,'Духовку разогреть до температуры 200 градусов, запекать кушанье в течение 30 – 40 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Куриное филе нарезать крупными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Измельчить чернослив и очищенные грецкие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Ингредиенты соединить, соль и перец – по вкусу. По желанию можно добавить чеснок, пропущенный через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Всыпать сухой желатин, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Массу выложить в пакет для запекания, в верхней части сделать несколько проколов и переложить в форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Поставить в духовой шкаф на 35 – 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Кушанье вынуть из духовки, дать немного остыть, а затем все еще раз перемешать прямо в пакете так, чтобы желатин равномерно распределился.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9547,'Сформовать рулет, замотать плотно сверху пищевой пленкой и поставить до полного застывания в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'Для приготовления печенья растопить маргарин с помощью микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'Сырые куриные яйца взбить с сахарным песком, всыпать пшеничную муку, ингредиенты хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'Должно получиться тесто, похожее на густую сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'Печенье выдавить на противень, застеленный пергаментом, с помощью кондитерского мешка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'В серединки положить по ягодке красной смородины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9548,'Печь в духовке до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Размягчить и размять маргарин до получения однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Добавить муку, творог, ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Тесто раскатать в тонкий пласт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Вырезать кружки с помощью стакана, присыпать их сахаром, свернуть пополам сахарной стороной внутрь, затем еще раз посыпать сахаром и свернуть пополам. Сверху еще раз посыпать сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Положить печенье на застеленный пергаментом противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9549,'Печь до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Для приготовления песочного теста можно воспользоваться кухонным комбайном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Сначала положить в чашу сливочное масло, нарубленное кусочками, затем – сухие ингредиенты: пшеничную муку, сахарный песок (100 г), соль, ванилин, кукурузный крахмал. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Если замес делается руками, то последовательность операций такая: нарезать или натереть охлажденное масло, всыпать соль и сахар (100 г), заранее просеянную муку, ванилин, ингредиенты перетереть до получения мелкой крошки. Вбить яйцо и перемешать. Погасить соду свежим лимонным соком или уксусом, влить в тесто и еще раз хорошо перемешать. Можно добавить немного охлажденной воды, вливать её нужно постепенно, в этом случае тесто не станет слишком липким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Должна получиться эластичная масса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Разделить её на две части: одну треть и две трети от общего объема.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Завернуть колобки в пищевую пленку по отдельности, поставить на два часа в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Духовой шкаф разогреть до 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Большую часть теста раскатать тонким слоем в три-четыре миллиметра.','https:https://st.vkuso.ru/data/cache/thumb/00/558bb14525de600_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Для выпечки удобно использовать форму с разъемным дном.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Выложить тесто, распределить его по поверхности, лишние края убрать.','https:https://st.vkuso.ru/data/cache/thumb/99/21a522eeb58f099_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Дно наколоть вилкой в нескольких местах. Форму поставить в холодильник.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Для начинки понадобятся очищенные от цедры лимоны.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Сами плоды нужно избавить от косточек и белой кожуры, мякоть нарезать дольками, измельчить с помощью блендера до однородности.','https:https://st.vkuso.ru/data/cache/thumb/07/1c31ad5f5431c07_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Цедру можно не снимать и размолоть плоды вместе с ней, но в таком случае масса приобретет горьковатый вкус.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Перемешать начинку с сахарным песком (100 г) и кукурузным крахмалом так, чтобы разбить все комочки.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Массу немного поварить до загустения.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Форму с тестом вынуть из холодильника, нанести лимонную массу равномерно.','https:https://st.vkuso.ru/data/cache/thumb/0f/7f3da291e7fdb0f_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Меньшую часть теста натереть на крупной терке, насыпать на пирог.','https:https://st.vkuso.ru/data/cache/thumb/a2/c69329e78faf1a2_434x295.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9550,'Печь в духовом шкафу в течение 30 – 40 минут, верх должен подрумяниться.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Вымыть виноградные кисточки, отделить ягоды от ветки.','https:https://st.vkuso.ru/data/cache/thumb/31/689127101068a31_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Половину виноградин положить в пакет и заморозить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Очистить от семян дыню, вырезать из мякоти шарики с помощью специальной ложки, переложить в кувшин вместе с ягодами.','https:https://st.vkuso.ru/data/cache/thumb/4f/26430a04e6cdf4f_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Ошпарить лимон, нарезать кольцами.','https:https://st.vkuso.ru/data/cache/thumb/65/f4952dc4f779a65_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Вымыть и обсушить мяту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Мяту и лимон добавить в дынные шарики, влить половину нормы сухого белого вина, поставить в холодильник на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'В охлажденный напиток добавить минеральную воду и оставшееся вино.','https:https://st.vkuso.ru/data/cache/thumb/ac/735588c5580c7ac_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9551,'Для подачи разложить в бокалы замороженный виноград и залить сангрией.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Соединить со сметаной, сырыми куриными яйцами, сахарным песком, пищевой содой и орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Массу взболтать венчиком, перелить в разъемную форму и выпечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Для приготовления крема взбить размягченное сливочное масло, добавить сгущенное молоко, какао.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Часть крема оставить белым для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Разрезать корж, промазать кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9552,'Украсить так, как подскажет фантазия, подать выпечку комнатной температуры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Просеять муку, перемешать с сырыми яйцами, молоком, солью, рубленым укропом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Массу перемешать так, чтобы не было комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Жарить тонкие блины с двух сторон.','https:https://st.vkuso.ru/data/cache/thumb/24/3120c9eb1032f24_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Для начинки яйца очистить, нарезать кружками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Тонкими ломтиками нарезать ветчину.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Натереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Выложить на готовый блинчик по ломтику ветчины, затем – по два кружка яйца, посыпать сыром.','https:https://st.vkuso.ru/data/cache/thumb/f5/e5fd6b3d9157cf5_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Сложить изделия конвертиками.','https:https://st.vkuso.ru/data/cache/thumb/7c/6c510bbe9505a7c_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Для панировки взбить сырое яйцо с солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Блинчики с начинкой обмакнуть в яйцо.','https:https://st.vkuso.ru/data/cache/thumb/d6/2198cd92a4f71d6_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Затем в панировочные сухари.','https:https://st.vkuso.ru/data/cache/thumb/5c/5802bc9a6ddb95c_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9553,'Жарить на сковороде до образования румяной корочки.','https:https://st.vkuso.ru/data/cache/thumb/2b/530c388704d6e2b_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Объединить ингредиенты для бисквита, перемешать, добавить мед (густой – растопить), миксером взбить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Подготовить форму, вылить тесто, выпекать около 45 минут при температуре чуть ниже 200 градусов. Разрезать готовый и остывший корж на 2 половинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Вымыть и порубить чернослив (жесткий предварительно размочить), можно измельчить миксером, взбить сахар с густой сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Вырезать из коржей любой круглой формочкой кружочки, остатки подсушить и размолоть в блендере для оформления готовых пирожных.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Разложить на плоское большое блюдо  кружочки, смазать сметанным кремом, на них уложить чернослив, каждый накрыть вторым кружочком, повторить операцию, прикрыть оставшимися кружочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9554,'Смазать медовые пирожные с черносливом со всех сторон кремом,  измельченной крошкой от коржей оформить верх пирожного, обсыпать рубленным жареным грецким орехом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Мелко нарезать репчатый лук, натереть очищенную морковь.','https:https://st.vkuso.ru/data/cache/thumb/9e/a95c9f46792ae9e_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Разогреть на сковороде смесь оливкового и сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Сперва обжарить лук до прозрачного состояния, затем добавить морковь и измельченный корень сельдерея, все вместе прогреть в течение нескольких минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Выложить мясной фарш, перемешать, размять комочки ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Соль и молотый перец – по вкусу, добавить тертый или нарезанный чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Когда мясо изменит цвет – влить сухое белое вино.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Прогревать пять минут, алкоголь должен выпариться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Добавить консервированные в собственном соку помидоры или домашнюю пассату, молоко, нарезанную зелень базилика.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Накрыть смесь крышкой, тушить на тихом огне, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Время приготовления – полчаса или немного дольше.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Соль – по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Должна получиться полужидкая масса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Приготовить соус «Бешамель».',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Положить в сотейник сливочное масло, растапливать до тех пор, пока жир не начнет булькать.','https:https://st.vkuso.ru/data/cache/thumb/9e/7996b93ff18739e_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Снять с плиты, просеять в масло муку небольшими порциями, следить за тем, чтобы не образовывались комочки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Влить молоко, тоже несколькими порциями, каждый раз хорошо перемешивать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Снова поставить массу на плиту, на тихий огонь. Прогревать соус до тех пор, пока он не загустеет, помешивать.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'Приготовить маринад из красного винного уксуса, молотого имбиря, зернистой горчицы, соевого соуса, натурального мёда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Смесь должна закипеть. Снять её с огня, посолить, всыпать немного молотого мускатного ореха, тертый сыр «Пармезан» (40 г), перемешать.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Форму для запекания смазать оливковым маслом, на дно налить немного рагу, сверху – листы готовой пасты.','https:https://st.vkuso.ru/data/cache/thumb/10/36baaf4ddee7f10_434x295.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Еще один слой рагу, соус «Бешамель», рагу, разровнять.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Посыпать пирог частью тертого сыра «Пармезан». Слои повторять в указанном порядке до тех пор, пока не закончатся все ингредиенты.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9555,'Форму накрыть фольгой или крышкой, поставить в заранее разогретый духовой шкаф, печь в течение получаса, температура приготовления – 180 градусов.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Для приготовления начинки растопить на сковороде сливочное масло, добавить нарезанный зубчик чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Обжарить на чесночном масле куриный фарш в течение пяти минут, помешивать вилкой, разминать комочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Добавить молотые перцы, мускатный орех, соль по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Снять массу с огня, добавить тертый сыр «Пармезан» и твердый сыр, измельченную зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Замесить тесто из творога, муки (200 г), соли, сахара, вбить сырое куриное яйцо, добавить пищевую соду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Масса должна получиться мягкой и липкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'На рабочую поверхность насыпать муку (50 г), тесто разрезать на равные части и скатать шарики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Каждый раскатать, положить начинку, края защипать, придать пирожкам продолговатую форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9556,'Жарить пирожки на разогретом растительном масле.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Соединить в чаше миксера заранее просеянную муку, свежие дрожжи, сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Вбить сырое куриное яйцо, влить молоко, массу перемешать в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Добавить немного соли, растопленное сливочное масло, перемешивать еще в течение пяти минут, до гладкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Скатать тесто в шар, завернуть в пленку и оставить на час в тепле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Масса должна увеличиться в два раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Разделить тесто на две части, каждую – на четыре, скатать в шарики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Каждый шар раскатать в круг.','https:https://st.vkuso.ru/data/cache/thumb/26/495e6b04d281526_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Перенести первую лепешку на лист для выпекания, смазать готовой шоколадной пастой из магазина.','https:https://st.vkuso.ru/data/cache/thumb/f8/d4b86d1f14096f8_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Накрыть вторым кругом, смазать, слои повторять, в центр четвертой лепешки поставить стакан и немного вдавить.','https:https://st.vkuso.ru/data/cache/thumb/c6/154ccf1260149c6_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Острым ножом разрезать тесто на 16 частей, они должны быть одинаковыми.','https:https://st.vkuso.ru/data/cache/thumb/d0/69efa45127682d0_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Взять в руки по две полоски теста и повернуть их в разные стороны против своей оси.','https:https://st.vkuso.ru/data/cache/thumb/11/a1b3180902d1811_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'То же самое проделать с остальными полосками.','https:https://st.vkuso.ru/data/cache/thumb/6c/176f2a8a655ee6c_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Кончики полосок защипнуть вместе в центре, а уголки подогнуть внутрь и смазать желтком.','https:https://st.vkuso.ru/data/cache/thumb/94/52f3c08aa903794_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Печь пирог в течение 15 – 20 минут, до образования корочки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9557,'Вторую часть можно сделать с другой начинкой.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Репчатый лук нарезать и обжарить на растительном масле, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Огонь выключить, добавить нарезанное небольшими кусочками куриное мясо, специи.','https:https://st.vkuso.ru/data/cache/thumb/6f/51fe528c330f76f_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Для приготовления теста налить в кастрюлю воду, добавить растительное масло, смесь довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Отдельно просеять пшеничную муку, влить в нее закипевшую смесь.','https:https://st.vkuso.ru/data/cache/thumb/a6/c20d251b16ae1a6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Посолить по вкусу, вымесить тесто ложкой и руками.','https:https://st.vkuso.ru/data/cache/thumb/eb/56d0791387b02eb_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Выложить заварное тесто на посыпанную мукой доску, подождать до остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Сформовать колбаску, нарезать порциями.','https:https://st.vkuso.ru/data/cache/thumb/b8/68d6778af735bb8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Кусочки раскатать в кружки размером с небольшое блюдце.','https:https://st.vkuso.ru/data/cache/thumb/36/7a265da70599a36_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Противоположные края загнуть. Положить на край луково-куриную начинку.','https:https://st.vkuso.ru/data/cache/thumb/91/1a13c1997e91091_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Сковороду или противень смазать растительным маслом, выложить изделия на расстоянии друг от друга, чтобы они не слиплись в процессе приготовления.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Смазать рулеты сверху желтком, посыпать семенами кунжута.','https:https://st.vkuso.ru/data/cache/thumb/2a/766c8762f10972a_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9558,'Поставить в духовой шкаф на полчаса.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9559,'Откинуть консервированные ананасы на сито, дать жидкости стечь, дополнительно обсушить бумажными салфетками, нарезать на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9559,'Замочить желатин  в небольшом количестве воды минут на 10, осторожно нагреть (не давать закипеть!), помешивая довести жидкость до прозрачности. Сливки взбить до появления устойчивой пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9559,'В подходящую емкость положить сметану, цедру лимона, сахарную пудру, влить ликер (Сливочный, Бейлиз или просто коньяк), ванильный экстракт, все взбить, объединить со сливками и раствором желатина, аккуратно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9559,'Бисквитное печенье окунуть в ананасовый сироп, выложить в форму, сверху – часть кубиков ананаса, прикрыть кремом, а сверху покрыть слоем печенья, повторить операцию с фруктами и кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9559,'Накрыть тирамису с консервированными ананасами пленкой, отправить ночевать в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Клубни разрезать крупными кусками, на четыре-шесть частей каждую картофелину. Переложить в кастрюлю.','https:https://st.vkuso.ru/data/cache/thumb/3c/9475d3f83d7f33c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Залить кипящей водой, поставить на огонь, варить до полуготовности, в течение пяти-шести минут после закипания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Воду слить, картофель немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Затем натереть на крупной терке.','https:https://st.vkuso.ru/data/cache/thumb/26/469b5d0e099e126_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Отдельно растопить половину нормы сливочного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'В сотейнике или на сковороде разогреть немного растительного масла, выложить картофельную массу в три слоя, каждый слой посолить и полить сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'По периметру выложить оставшееся сливочное масло, нарезанное кусочками.','https:https://st.vkuso.ru/data/cache/thumb/ca/f4e57000b482dca_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Жарить на среднем огне до румяной корочки в течение пяти минут, перевернуть, жарить еще столько же.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'Готовый картофель должен постоять на сковороде несколько минут, затем его можно переложить на блюдо.','https:https://st.vkuso.ru/data/cache/thumb/8c/9d44c985e9ec98c_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9560,'При подаче запеканку нарезают на порционные куски.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Отварить куриное филе, куриные яйца, вымыть и хорошо обсушить листья салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Отдельно приготовить йогуртовый соус из основного продукта с давленым чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Листья салата порвать руками в глубокую емкость, нарезать крупными кусками помидоры, огурец – брусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Продукты перемешать, посолить, добавить соус, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Выложить овощную массу на большие тарелки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'Курицу нарезать медальонами и выложить сверху вместе с четвертинками крутого яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9561,'На яйца и филе положить остатки соуса, блюдо подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Разделить белки и желтки, взбить белки и сахар в крепкую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Смешать муку с маслом, добавить желтки яиц, взбить в однородную массу, всыпать муку, дробленые орехи, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Аккуратно смешать по частям полученную смесь с белками. Переложить тесто в смазанную форму, поставить на час в уже горячую (160 градусов) духовку, затем дать остыть минут 10 в открытой духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Достать, полностью остудить, вынуть корж из формы, разрезать на 2 части. Смазать одну вареной сгущенкой, накрыть – второй.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Налить в сотейник сливки, нагреть до кипения, убрать с плиты, всыпать кусочки шоколада, перемешать, дать ему раствориться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9562,'Облить венесуэльский торт с орехами и вареной сгущенкой полученной смесью, присыпать крупно порубленным орехом, дать постоять в холодильнике часа 4.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9563,'Цветную капусту и брокколи отварить в течение трех-четырех минут в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9563,'Жидкость слить, капусту выложить в форму, добавить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9563,'В другой емкости взбить молоко с яйцами и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'Мясо выложить в смесь, накрыть емкость пищевой пленкой и поставить на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'Куриные полоски нанизать на зубочистки, присыпать кунжутными семечками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'В сотейник или на сковороду вок налить растительное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9564,'Жарить шашлыки до румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Сливочное масло растопить и перемешать с измельченным печеньем.','https:https://st.vkuso.ru/data/cache/thumb/0c/7fb968675e36b0c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Сливочный сыр взбить с сахарным песком и ванилином, вбить сырое куриное яйцо, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/c3/b35805a5d65aac3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Добавить крахмал и еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Массу переложить в форму, утрамбовать смесь, посыпать ягодами.','https:https://st.vkuso.ru/data/cache/thumb/92/b792620f3a76c92_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Время выпекания – от 40 до 45 минут, температура – 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9565,'Охладить десерт в холодильнике, затем разрезать на порции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Пшеничную муку просеять вместе с какао-порошком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Отдельно растопить сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Сахар и сырые куриные яйца немного взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Разогреть натуральный мёд, до кипения не доводить, всыпать пищевую соду, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Масло и яйца соединить, добавить медовую массу, в последнюю очередь – какао с мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Замесить тесто в емкости, а затем на столе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Масса должна получиться пластичной и мягкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Разделить массу на 12 частей, каждую скатать в колобок, прикрыть пленкой, оставить на столе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Для выпекания раскатать каждую часть теста на присыпанной мукой пекарской бумаге, диаметр – по 23 см.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Коржи ровно обрезать, температура приготовления – от 160 до 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Перед выпечкой изделия наколоть в нескольких местах.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Коржи остудить, последний выпечь из обрезков: он пригодится для украшения торта.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Для крема понадобится жирная сметана, её нужно взбить с вареной сгущенкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'По желанию можно добавить сахарную пудру.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9566,'Собрать торт, прослоить коржи сметанным кремом, дать постоять для пропитывания и подать к столу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'Перемешать муку, какао-порошок, сахарный песок и разрыхлитель. Добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'В небольшой емкости соединить уксус, растительное масло и ванильную эссенцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'Все добавить в сухую смесь.','https:https://st.vkuso.ru/data/cache/thumb/b3/f8df221cfa4abb3_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'В полученную массу влить стакан воды, перемешать до однородного состояния.','https:https://st.vkuso.ru/data/cache/thumb/db/627f30ddfa5d0db_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'Печь корж в течение 30 – 35 минут, готовность проверить спичкой или зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9567,'Остывший корж смазать любимой глазурью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Единым блоком выделить сердцевину арбуза. Это можно сделать с помощью длинного острого ножа.','https:https://st.vkuso.ru/data/cache/thumb/f7/a792d2c3abcfff7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Выложить мякоть на блюдо для сервировки, оставить на время, чтобы отцедить лишний сок, затем убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Очень тонко нарезать любые фрукты и ягоды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Отдельно приготовить взбитые сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Миска и венчик для взбивания должны быть охлаждены.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'В сливки добавить сахар и ванильный экстракт, взбивать энергично, в течение двух минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Когда масса станет плотной – ввести охлажденный раствор желатина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Поставить блюдо в холодильник до загустевания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Получившейся массой обмазать арбуз, сливки выложить сверху.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Края блюда протереть влажной тканью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Украсить ягодами и фруктами, это нужно сделать быстро, пока десерт не согрелся.','https:https://st.vkuso.ru/data/cache/thumb/ee/f3d5275ac597eee_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9568,'Перед подачей нарезать торт треугольниками.','https:https://st.vkuso.ru/data/cache/thumb/4b/1d4dff971bee64b_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9569,'Плоды банана нарезать кусочками и положить в морозильную камеру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9569,'Замороженные плоды выложить в блендер и взбить вместе с молоком и какао-порошком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Курагу залить кипящей водой (50 мл), оставить на 15 минут для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Кружки вырезать стаканом, сделать формочкой для печенья бабочек в половине кружков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Температура выпекания – 170 градусов, время – 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9570,'Каждый кружок смазать джемом из кураги и накрыть вторым кружком, с бабочкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Смешать в миске пшеничную муку, овсянку, соль, разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Добавить порезанное кусочками сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Натереть сыр, добавить в основную массу вместе с молоком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Замесить тесто, сформовать шар, поставить в холод на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Тесто раскатать, вырезать печенье, можно выдавить рисунок с помощью штампов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Печь при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9571,'Подавать к столу в охлажденном виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Миндаль замочить в кипятке на две-три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Орехи очистить от пленок и жарить на сковороде без масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Готовые орехи измельчить в муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Смолоть овсяные хлопья.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Все ингредиенты перемешать с сахарной пудрой, пшеничной мукой, сырыми куриными яйцами, разрыхлителем, щепоткой соли и цедрой одного апельсина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Тесто должно получиться мягким, оставить его на час в холодильнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Разделить массу на небольшие кусочки величиной с грецкий орех.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Скатать шарики, обвалять в сахарной пудре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Выложить на лист пергамента, приплюснуть руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9572,'Время выпекания – 20 минут, температура – 170 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Овсяные хлопья перемолоть в блендере в муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Так же поступить с фундуком, но помол должен быть крупнее.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Смешать то и другое, добавить корицу, сушеную клюкву, соль, сахарный песок, разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Отдельно размять банан и смешать его с ванильным экстрактом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Все ингредиенты соединить, дать постоять 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Полученное тесто не должно быть жидким, при необходимости можно добавить еще немного овсяной муки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Противень застелить бумагой для выпекания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Сформовать из теста небольшие шарики, немного приплюснуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Поставить печенье в заранее разогретую духовку, температура выпекания – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Время приготовления – 20 минут, пять минут – режим конвекции.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9573,'Готовые изделия немного остудить на противне, а затем переложить на решетку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Намазать пастой мисо стейки из говядины 2-3 сантиметра в толщину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Положить в пакет, отправить минимум на 30 минут в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Перед жаркой лишнюю пасту обтереть бумажными салфетками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Обжарить стейк: нагреть сковороду, обжаривать стейк по 5 минут с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Завернуть мясо в фольгу, отставить на 5-10 минут. Не солить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Приготовить гарнир: сушеные водоросли вакаме залить кипятком.','https:https://st.vkuso.ru/data/cache/thumb/ff/452e28862191eff_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Порезать цукини на длинные тонкие ломтики, тонко порезать салат, поломать орешки, порезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Соединить кешью, цукини, вакаме, салат, полить кунжутным маслом, размешать руками, отставить на 10 минут, чтобы замариновалось.','https:https://st.vkuso.ru/data/cache/thumb/3a/07917e392c28d3a_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9574,'Подавать говяжий стейк с мисо с зеленым гарниром.','https:https://st.vkuso.ru/data/cache/thumb/ba/d7b34f6125321ba_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Растопить сливочное масло, влить в него молоко и прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Добавить растворимый кофе и мёд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Овсяные хлопья выложить на сухую сковороду и подсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Перемешать овсяные хлопья и толокно, муку, тростниковый сахар, молотую корицу, разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Добавить в сухую смесь сырые куриные яйца, молоко с маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Всё перемешать до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Скатать из полученного теста небольшие шарики мокрыми руками. Немного приплюснуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Противень застелить бумагой для выпекания, посыпать каждое печенье тростниковым сахаром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9575,'Время выпекания – 20 минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Намазать при помощи кисточки заготовки из творога, осторожно положить обратно в морозилку приблизительно на 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9576,'Можно хранить в холодильнике творожно-ванильные сырки в шоколадной глазури.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'В сковороде нагреть масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'Пожарить шалфей и тонко нарезанный кольцами лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'Накрыть крышкой, соус готовить 20 минут, помешивать время от времени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'Соединить сметану и майонез, положить жареный лук в смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'Посыпать перцем, солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9577,'Закрыть луковый соус с шалфеем для чипсов и овощей, отправить на час в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9578,'Раскатать скалкой кусочек хлеба для тостов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9578,'Положить сверху любую начинку (ветчину, овощи, зелень, семгу, сыр).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9578,'Сформировать рулетик, обмакнуть во взбитое яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9578,'Уложить в форму, намазанную маслом, посыпать кунжутом или тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9578,'Готовить 10 минут в духовке, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Порезать на ломтики морковь и лук.','https:https://st.vkuso.ru/data/cache/thumb/e7/1423713c81082e7_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Нагреть в сковороде ½ масла, обжаривать овощи 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Порезать перец шашками. Мелко потереть имбирь и чеснок, сельдерей на ломтики.','https:https://st.vkuso.ru/data/cache/thumb/cd/8b8a4ff27cc61cd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Положить все к луку и моркови. Обжаривать несколько минут, долить воду, положить соевый соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Тушить, пока овощи не приготовятся.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Порезать куриное филе на большие куски. Обжаривать минуту в оставшемся масле. Мясо должно быть сыроватым внутри.','https:https://st.vkuso.ru/data/cache/thumb/21/b56295252e58421_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Положить к овощам и соусу, отставить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Отваривать 6-8 минут в соленой воде лапшу удон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Воду слить. Переложить лапшу к овощам с мясом, готовить 5-7 минут.','https:https://st.vkuso.ru/data/cache/thumb/ba/367a80f8a1a41ba_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Посыпать перцем, если нужно солью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9579,'Подавать лапшу удон с курицей и тушеными овощами сразу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Пробить творог при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Положить стружку кокоса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Насыпать 4 столовых ложки сахара, добавить 2 желтка и крахмал.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Перемешать, сформировать шарики по размеру, как грецкий орех.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Положить их на дно формы, застеленной специальной бумагой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Сделать заливку: соединить кефир и яйцо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Муку просеять, соединить с сахаром, солью, разрыхлителем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Вылить в смесь из муки растительное масло и кефир.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Положить размороженную красную смородину, осторожно перемешать, чтобы ягоды были хорошо распределены по тесту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Получится тесто, как на оладьи.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Залить шарики из творога смородиновой заливкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Готовить 40-50 минут, соблюдать температуру 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Проверять готовность зубочисткой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9580,'Посыпать заливной творожный пирог с красной смородиной сахарной пудрой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Аккуратно разделить желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Взбить белки, постепенно добавить сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Добавить к белкам пищевой краситель зеленого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Положить массу в кондитерский мешок.','https:https://st.vkuso.ru/data/cache/thumb/3d/7cbd064d6b5b33d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'На противень постелить специальную бумагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Выдавить нижний слой елочки, потом средний и в конце верхний слой.','https:https://st.vkuso.ru/data/cache/thumb/d1/afd59c5619414d1_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Украсить безе ёлочки на новый год кондитерской посыпкой.','https:https://st.vkuso.ru/data/cache/thumb/2e/f240b9448445a2e_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Отправить будущие сладости в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9581,'Готовить 1,5 часа, соблюдать температуру 120 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Взять 2 банки ананасов. Слить жидкость, подсушить шайбы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Соединить жидкий творог и масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Если творог суховат, то пропустить через мясорубку и соединить с двумя ложками сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Добавить гашеную соду, обычный и ванильный сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Постепенно насыпать муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Муки добавлять столько, чтобы тесто не липло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Выдавить при помощи стакана кружки по размеру, как шайба ананаса.','https:https://st.vkuso.ru/data/cache/thumb/f3/a98ebbc3633e6f3_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Положить на тесто ананасы.','https:https://st.vkuso.ru/data/cache/thumb/ca/e3ceff218e0edca_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Из оставшегося теста сделать решетку. Пройтись по ней специальным валиком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Положить на ананасы, подогнуть, прижать снизу.','https:https://st.vkuso.ru/data/cache/thumb/81/f37b2aac9d87881_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Положить на лист, намазать яйцом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Отправить на 20 минут в духовку, соблюдать температуру 180 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9582,'Можно посыпать творожные слойки с ананасами сахарной пудрой.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Приготовить маринад, ингредиенты класть по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Положить в маринад курицу и картофель, накрыть пленкой или крышкой.','https:https://st.vkuso.ru/data/cache/thumb/84/37aa679bd2e2b84_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Отставить на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Положить в форму, намазанную маслом.','https:https://st.vkuso.ru/data/cache/thumb/c7/6db8be346d0e6c7_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Готовить в духовке 40 минут, соблюдать температуру 220 градусов.','https:https://st.vkuso.ru/data/cache/thumb/49/b9ba6722cf31d49_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Если температура будет меньше, то готовить дольше.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Готовность проверять по картофелю – делать проколы вилкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9583,'Курочку с картошкой под маринадом подавать с овощами и зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Приготовить грудинку: порезать на тоненькие ломтики, обжарить.','https:https://st.vkuso.ru/data/cache/thumb/d8/fec05d21dc517d8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Размешать дрожжи в теплой воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Насыпать в посуду муку, насыпать сахар, соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Добавить воду с дрожжами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Ввести обжаренные куски мяса вместе с жиром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Добавить муку по чуть-чуть, чтобы тесто было мягкое.','https:https://st.vkuso.ru/data/cache/thumb/c6/e3ce9606c02ecc6_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Отставить тесто на 30 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Если дрожжи хорошие, то за это время тесто поднимется.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Раскатать тесто в пласт, посыпать тертым сыром.','https:https://st.vkuso.ru/data/cache/thumb/31/cb14002f2096031_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Чтобы придать аромат, то добавить чуть-чуть кунжута.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Любители острого могут добавить красный перец.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Свернуть пласт с содержимым в виде конверта.','https:https://st.vkuso.ru/data/cache/thumb/4c/936ed433477f14c_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Снова раскатать пласт в толщину 0,5 сантиметров.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Порезать на полоски, сложить по две полоски, скрутить в виде жгута.','https:https://st.vkuso.ru/data/cache/thumb/8a/afcea044dbf198a_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Готовятся хлебные палочки с грудинкой к пиву быстро, приблизительно 15 минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9584,'Когда станут румяными, можно доставать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Соединить все продукты для теста, добавить несколько больших ложек холодной воды. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Накрыть специальной бумагой, отправить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Раскатать тесто, переложить в форму, намазанную маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Сделать проколы вилкой, прижать краешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Накрыть специальной бумагой, насыпать фасоль, чтобы на корже не было выпуклостей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Готовить 20 минут, соблюдать температуру 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Убрать бумагу, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Приготовить белковую смесь: белки взбить с солью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Не прекращая взбивать, насыпать сахар, положить миндаль, добавить лимонный сок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Распределить смесь по коржу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'На крем положить ягоды, чуть-чуть посыпать сахаром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Отправить пирог еще на 30-35 минут в духовку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Остудить пирог по-чешски с ягодной начинкой в форме, переложить на блюдо.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9585,'Можно украсить листиком мяты.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Потереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Положить на специальную бумагу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Придать форму при помощи лопатки или ножа.','https:https://st.vkuso.ru/data/cache/thumb/fd/c68230e54b89cfd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Отправить в духовку, соблюдать температуру 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Запекать сыр, пока не станет румяным.','https:https://st.vkuso.ru/data/cache/thumb/25/81778573b2c0925_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9586,'Можно подавать простые сырные чипсы в духовке.','https:https://st.vkuso.ru/data/cache/thumb/3e/f2837106dde453e_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Печенье измельчить.','https:https://st.vkuso.ru/data/cache/thumb/2a/d4db909513fff2a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Порезать печенье чизкейк с шоколадной глазурью на кусочки.','https:https://st.vkuso.ru/data/cache/thumb/9b/f8cf6d0e5dddc9b_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9587,'Можно посыпать измельченным печеньем.','https:https://st.vkuso.ru/data/cache/thumb/da/c6377c8ab388dda_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Порезать сосиски на тоненькие кружки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Вымыть помидоры, снять кожицу, измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Соединить помидоры, сосиски и кислую капусту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Добавить по вкусу перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Перемешать, чтобы все равномерно распределилось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Положить капуст у в жаростойкую форму, намазанную маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Соединить паприку и чуть-чуть соли, добавить растительное масло, размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Обмакнуть голени в полученную смесь, выложить на капусту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Отправить на 30 минут в духовку, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Курица должна хорошо пропечься, то есть пустить прозрачный сок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9588,'Куриные ножки по-польски можно подавать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Насыпать желатин в воду, отставить на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Довести до кипения молоко, мед, сливки на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Положить шоколад, мешать, пока не растает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Добавить желатин, мешать до растворения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Положить йогурт, хорошо взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Положить смесь в формочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Отставить на 20 минут, потом остужать минимум 4 часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9589,'Украсить шоколадно-медовую Понна Котту тертым шоколадом и сливками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Сделать опару: в большой емкости соединить муку, дрожжи и молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Перемешать, накрыть посуду слегка влажным полотенцем, отставить на час при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Спустя час приготовить основное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Досыпать в опару муку, сахар, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Чуть-чуть взбить топленое масло и желток, добавить в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Вымешивать можно планетарным миксером – 3-4 минуты или руками 8-10 минут. Получится эластичное, мягкое тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Накрыть влажным полотенцем, отставить на 1,5-2 часа. Тесто увеличится в несколько раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Поделить тесто пополам, снова накрыть, отставить на 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Соединить корицу и сахар.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Когда время истечет, одну часть раскатать, придав форму прямоугольника.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Обильно посыпать сверху коричневым сахаром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Свернуть плотно по ширине.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Порезать тесто при помощи острого ножа на маленькие булки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Разложить булочки на противень, застеленный специальным силиконовым ковриком или пергаментом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Или положить в жароупорную форму, намазанную маслом, или в чугунную сковороду. В этом случае булочки будут похожи на ароматный пирог, каждый сможет сам отломать себе булочку.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Накрыть булочки влажным полотенцем, отставить на 60 минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Нагреть духовку до 200 градусов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Важно ставить булочки в хорошо разогретую духовку. Готовить булки 18-20 минут, если булочки в виде пирога, то готовить 25-30 минут.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Булочки должны стать румяными, а при надавливании отпружиниваться.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Если булочки выпекались отдельно, то достать их, положить на решетку или тарелку.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Если выпекались в виде пирога, то оставить в форме.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Через 5-8 минут полить глазурью.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Чтобы приготовить глазурь, соединить в емкости сахарную пудру, 2-3 большие ложки воды, экстракт.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Перемешать, чтобы получился густой соус. Мешать венчиком до однородности.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9590,'Поливать булочки глазурью нужно сразу, пока она не застыла.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Растопить на водяной бане твердый ирис, порезанный на маленькие кусочки, с 5 большими ложками сливок.','https:https://st.vkuso.ru/data/cache/thumb/b3/78a8d4e27a491b3_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Убрать с плиты, положить полторы столовые ложки сливочного масла, размешать до однородности.','https:https://st.vkuso.ru/data/cache/thumb/73/5ccad3f1010e773_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Налить растопленный ирис в форму, намазанную маслом, использовать чайную ложку. Брать масло, не имеющее запаха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Положить орешек в ириски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9591,'Отправить домашние «Тоффифи» с фундуком на 4-5 часов в морозилку, осторожно достать из формочек.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Подготовить продукты. Порезать лук, пожарить на свином жире до золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Порезать мясо на куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Положить в трехлитровую кастрюлю лук, мясо и паприку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Размешать, готовить на тихом огне, пока сок от мяса не испарится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Положить чеснок, тмин, налить воду. Тушить, пока мясо не приготовится.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Порезать на кубики картофель, томат и перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Положить овощи к мясу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Размешать, налить воду или бульон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Количество воды зависит от того, какой будет гуляш: густой или жидкий.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9592,'Варить настоящий суп-гуляш из говядины по-венгерски, пока овощи не приготовятся.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Намазать формочки маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Взбить творог, ванильный и обычный сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Соединить какао, разрыхлитель и просеянную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Взбить яйцо, йогурт, сахар и растительное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Насыпать мучную смесь, размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Разделить тесто на две части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Первую часть распределить по формочкам, положить на тесто по несколько маленьких ложек начинки, накрыть второй частью теста.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9593,'Готовить шоколадные кексы с творогом в духовке 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Сделать начинку для пирога: порезать рыбу на большие кубики, пожарить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Порезать лук, положить к рыбе, обжаривать 5 минут, убрать с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Отварить рис до полуготовности, положить к луку и рыбе, размешать, посыпать перцем, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Постелить на противень пергамент, намазать сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Раскатать тесто, положить на противень, сделать бортики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Сделать проколы вилкой, отставить на 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Выложить на тесто начинку, краешки намазать желтком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Полить начинку кипяченой водой, чтобы рис впитал жидкость и не был сухим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Отправить на 45 минут в духовку, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Вынуть пирог, сделать в начинке отверстия. В каждую вбить яйца.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9594,'Поставить открытый пирог с рисово-рыбной начинкой в духовку на 10 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9595,'Взбить яйца, подсыпая сахар. Взбивать до растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9595,'Растопить шоколад на паровой бане, вылить в яичную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9595,'Налить коньяк, насыпать просеянную муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9595,'Размешать все венчиком, разлить в чашки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9595,'Готовить шоколадное суфле с коньяком в чашке 8 минут, соблюдать температуру 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Почистить лук, порезать вдоль волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'На сковороде соединить сливочное и оливковое масло, пожарить лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Налить вино, когда оно испарится, налить бульон, посыпать специями, добавить прессованный чеснок и специи, лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Посыпать солью, сахаром, готовить 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Порезать багет на кружки, сделать гренки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Потереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Налить коньяк в суп, готовить 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Вылить суп в огнеупорную емкость. Лавровый лист и чеснок выбросить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Сверху разложить гренки, посыпать сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Отправить емкость в горячую духовку под гриль на 5 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9596,'Можно подавать луковый суп с коньяком по-французски.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Нашинковать лук полукольцами, нарезать картофель кружками и разрезать их пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Залить сухие грибы кипятком, дать постоять, нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Мясо нарезать как для плова, уложить в чашу нашинкованный лук, мясо, грибы (можно брать свежие), картофель, морковь (нарезать также как картофель).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Сметану смешать со специями по своему вкусу, солью и с томатной пастой, залить жаркое.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Осторожно перемешать, отставить мариноваться на 15-20 минут.','https:https://st.vkuso.ru/data/cache/thumb/c5/95084a1075135c5_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Нагреть духовку до 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Жаркое с грибами и сметаной в мультиварке готовить в режиме «Тушение» час, переключить режим на «Варка на пару», готовить полчаса. Лишняя жидкость должна выкипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9597,'Готовое блюдо перед подачей украсить измельченной зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Приготовить белковые корзинки: взбить до пиков охлажденные белки.','https:https://st.vkuso.ru/data/cache/thumb/a0/15ee456592e6fa0_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Продолжая взбивать, насыпать сахар. Получится крепкая, блестящая пена.','https:https://st.vkuso.ru/data/cache/thumb/75/7ac9ca752276c75_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Используя кондитерский мешок, отсадить белковую смесь на противень, застеленный специальной бумагой, в виде гнезд.','https:https://st.vkuso.ru/data/cache/thumb/6c/515d3b09154c16c_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Отправить безе в духовку, готовить 1,5-2 часа, соблюдать температуру 100 градусов.','https:https://st.vkuso.ru/data/cache/thumb/e9/5c9191c36910be9_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Сделать крем: соединить сметану, творог, насыпать по вкусу сахар, взбить до однородности блендером.','https:https://st.vkuso.ru/data/cache/thumb/39/59ff6187f32ad39_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Наполнить остывшие корзиночки из белка кремом.','https:https://st.vkuso.ru/data/cache/thumb/e2/bfae0f0ef6085e2_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Украсить клубникой.','https:https://st.vkuso.ru/data/cache/thumb/2d/53015d093c20b2d_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9598,'Получаются вкусные белковые пирожные с творожным кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Приготовить пшено: не открывая, опустить пакетик в подсоленную, кипящую воду. Варить 25 минут на тихом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Приготовить куриную грудинку. Разделить грудку на маленькое и большое филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'В маленьком филе убрать центральную прожилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Большое филе разрезать вдоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Из одной грудки получится приблизительно 6 одинаковых филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Отбить мясо молотком, посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Порезать на маленькие кусочки куриную печень или пропустить через мясорубку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Почистить лук, измельчить, обжарить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Положить печень, обжаривать несколько минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'На филе положить по 2 большие ложки начинки, завернуть в рулетики, закрывать краешки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Взболтать яйцо.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Обвалять рулеты в муке, затем в яйце, в конце в сухариках.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Обжарить трубочки на растительном масле до появления корочки с разных сторон.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Порезать рулеты на кусочки. Подавать с пшеном.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9599,'Получается очень вкусная грудка фаршированная куриной печенью.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Подготовить ингредиенты. Измельчить печенье. Для этого использовать ступку, скалку или блендер.','https:https://st.vkuso.ru/data/cache/thumb/8c/f3a249845d8a28c_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Перетереть сливочное масло и сгущенное молоко до однородности.','https:https://st.vkuso.ru/data/cache/thumb/ea/a6e61c8f3a167ea_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Положить в крем ванилин и печенье. Перемешать, чтобы получилась вязкая и густая масса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Сформировать пирожные в форме картофеля.','https:https://st.vkuso.ru/data/cache/thumb/dd/4e963e9fa3140dd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Все пирожные обвалять в какао.','https:https://st.vkuso.ru/data/cache/thumb/ab/3e1521fd75ef9ab_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Сделать ростки на картофеле из обжаренных грецких орехов. Чуть-чуть обжарить орехи, измельчить и украсить пирожные.','https:https://st.vkuso.ru/data/cache/thumb/dc/83ee3521078ffdc_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9600,'Отправить пирожное «Картошка» из печенья и сгущенки без выпечки в холодильник, чтобы полностью охладилось.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Развести сахар и дрожжи в теплом молоке. Отставить на 15 минут, чтобы появилась шапочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Просеять муку, насыпать щепотку соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Положить в муку масло комнатной температуры, перетереть в крошку руками.','https:https://st.vkuso.ru/data/cache/thumb/bd/47e9e99711834bd_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Влить дрожжи, замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/a6/c05e73174625ba6_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Сначала оно будет слегка жидким, но потом получится упругий, мягкий шар.','https:https://st.vkuso.ru/data/cache/thumb/69/baf3228b4567469_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Положить тесто в полиэтиленовый пакет, завязать, отправить на 30 минут в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Сделать начинку: почистить скумбрию, отрезать хвост, голову, плавники.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Снять кожицу, разрезать пополам вдоль, извлечь косточки.','https:https://st.vkuso.ru/data/cache/thumb/5f/a1695ea7f28f05f_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Порезать филе на кусочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Достать распухшее тесто. Разделить его на 2 части, чтобы одна часть была чуть-чуть больше.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Половинку теста, которая побольше, распределить по форме, намазанной маслом, загнуть края.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Выложить на тесто начинку, распределить.','https:https://st.vkuso.ru/data/cache/thumb/9a/6a964e4cb689b9a_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Раскатать вторую половину теста, накрыть начинку.','https:https://st.vkuso.ru/data/cache/thumb/18/a918f808a802718_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Слепить края. Сделать в нескольких местах проколы вилкой, намазать пирог желтком с водой.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Накрыть полотенцем, отставить на 15 минут.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Готовить 30-35 минут.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9601,'Перед подачей закрытый пирог со скумбрией из дрожжевого теста чуть-чуть остудить.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9602,'Нашинковать лук, налить в чашу масло, переложить лук, включить на «Выпечку» на 10 минут, добавить порезанное кубиками мясо и соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9602,'Добавить к мясу нарезанные кубиками морковь, картофель, сладкий перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9602,'Залить разведенной в небольшом количестве воды томатной пастой с сахаром, солью и перцем, заправить лавровым листом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9602,'Выставить режим «Тушение», готовить жаркое по-домашнему с мясом и ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9602,'Готовое жаркое в тарелках украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Натереть стейки смесью красного перца с паприкой, положить кольца лука, кусочек лимона, болгарский перец, веточку укропа, чтобы придать аромат.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Мариновать несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Положить на мангал с углями 2 листа фольги друг на друга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Положить мясо. Обжарить 5 минут, перевернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Обжарить со второй стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Из верхней фольги сделать бортики – придать вид тарелки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Налить 200 миллилитров пива.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Тушить по 10 минут со всех сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9603,'Если необходимо, то доливать пиво.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Развести дрожжи в молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Насыпать соль, сахар, муку, добавить яйцо, масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Замесить тесто. Накрыть, отправить на 3 часа в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Когда тесто подойдет, оставить при комнатной температуре, чтобы чуть-чуть нагрелось.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Раскатать круг 0,6 сантиметров толщиной. Отступить от края 3 сантиметра, выложить по кругу сосиски.','https:https://st.vkuso.ru/data/cache/thumb/4d/6ffec82503ffe4d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Накрыть тестом, залепить края.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Получится валик, порезать его на куски по 4 сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Вывернуть все куски сосиской вверх. Середину пирога намазать кетчупом или соусом.','https:https://st.vkuso.ru/data/cache/thumb/a1/f70bb39d0652fa1_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Посыпать твердым сыром.','https:https://st.vkuso.ru/data/cache/thumb/89/d9a08d6c86c8489_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Положить сверху по кусочку бекона и отваренной курицы, перец и помидоры, порезанные на кольца.','https:https://st.vkuso.ru/data/cache/thumb/b2/2add54d20070eb2_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Накрыть все кружками Моцареллы, посыпать тертым сыром Гауда.','https:https://st.vkuso.ru/data/cache/thumb/57/e8bae61f9f11357_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Отставить на 20-25 минут. Тесто намазать желтком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9604,'Готовить пирог с курицей, беконом и сосисками 30 минут, соблюдать температуру 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Взбить яйца, налить молоко, посыпать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Чуть-чуть взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Вылить смесь в полиэтиленовый пакет, завязать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Опустить на 30 минут в кипящую воду. Получается нежный омлет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Если завязать пакет свободно, то получается пористый и воздушный омлет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Если завязать пакет плотно, то омлет будет плотный.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9605,'Положить омлет на тарелку, добавить сливочное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Достать за час до начала приготовления сливочное масло из холодильника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Просеять пшеничную муку через сито в глубокую посуду. Мука станет чистой, более сухой и рыхлой.','https:https://st.vkuso.ru/data/cache/thumb/f6/b95ca961d4c92f6_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Когда масло станет мягким, положить его в емкость с мукой, насыпать сахарную пудру, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Протереть продукты руками, чтобы получилась крошка, как песок.','https:https://st.vkuso.ru/data/cache/thumb/0d/934dd68f5beb30d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Добавить в мучную смесь желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Снова замесить тесто руками, чтобы получилось эластичное тесто.','https:https://st.vkuso.ru/data/cache/thumb/fd/5c95d15485e37fd_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Сформировать из полуфабриката шар, завернуть в пленку, отправить на 30-60 минут в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Нагреть духовку до 180 градусов, кисточкой намазать противень растительным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Достать из холодильника тесто, снять пленку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Положить тесто на стол, раскатать толщиной 5 миллиметров.','https:https://st.vkuso.ru/data/cache/thumb/9c/cf47e79885a599c_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Рабочую поверхность застелить полиэтиленом, мукой не присыпать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Можно использовать любые формочки для печенья, вырезать из теста фигурки: цветы, круги, звездочки.','https:https://st.vkuso.ru/data/cache/thumb/ac/668f535c7131eac_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Разложить заготовки на противне, между фигурками оставлять пространство 2-2,5 сантиметра.','https:https://st.vkuso.ru/data/cache/thumb/35/8657fb2c3070835_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Поставить противень на средний стеллаж в горячую духовку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Готовить печенье 10-15 минут. Должен появиться румянец. Достать противень из духовки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Дать печенью чуть-чуть остыть, переложить на плоскую тарелку при помощи кухонной лопатки.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Можно посыпать сахарной пудрой, полить сахарной глазурью или растопленным шоколадом.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9606,'Простое печенье с сахарной пудрой подавать с какао, чаем, кофе или теплым молоком.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9607,'Пищевой желатин замочить в воде на полчаса, воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9607,'Массу поставить на тихий огонь, добавить нежирное молоко, обезжиренный творог, какао-порошок, мёд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9607,'Смесь прогреть на медленном огне, перемешать блендером до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9607,'Вылить желе в форму, поставить в холодильник до полного застывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9608,'Влить молоко в чашу мультиварки, нагреть до 40 градусов (выше нельзя, т.к. не произойдет ферментирование), выключить. Использовать можно режим «Подогрев». Температуру замерять градусником.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9608,'Растворить необходимое количество фермента (согласно инструкции) в кипяченой теплой воде (4 ст.л.), вылить в молоко, размешать минуты 2 до лучшего распределения в объеме молока, закрыть, оставить на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9608,'Разрезать аккуратно на мелкие кусочки, прямо в чаше, полученное желе, посолить по вкусу. Закрыть крышку, включить на 2,5-3 часа режим «Подогрев». Сыворотка должна полностью отделиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9608,'Откинуть готовый сыр в мультиварке по-домашнему на марлю, переложить в чашку, добавить по желанию специи, быстро и хорошо перемешать, слить, выделившуюся сыворотку, придать форму, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9608,'Если поместить на него груз и убрать в холодильник, то через время он затвердеет, и в нем образуются дырочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Грудку очистить от жира, мясо нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Отдельно приготовить маринад из соевого соуса, приправ к курице, паприки, черного молотого перца, куркумы и бадьяна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Положить курицу в смесь на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Нарезать морковь, репчатый лук, спассеровать овощи в воке на небольшом огне.','https:https://st.vkuso.ru/data/cache/thumb/7c/b3cff7435f53d7c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Отварить нешлифованный бурый рис с куркумой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'В овощную обжарку добавить курицу, готовить в течение нескольких минут, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/e7/91a6ef23588e4e7_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'В почти готовое блюдо добавить готовый рис и консервированную фасоль без жидкости.','https:https://st.vkuso.ru/data/cache/thumb/5f/61fc84ce21a125f_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9609,'Выложить сверху капусту брокколи, накрыть на 15 минут крышкой и потушить.','https:https://st.vkuso.ru/data/cache/thumb/43/bd1502a8df8e243_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Желатин растворить в 1/2 стакане киселя со вкусом ежевики, дать постоять до набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Для приготовления коржа перемешать обезжиренный творог, сырые куриные яйца, клетчатку, стевию, ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Перемолоть овсянку до состояния муки, всыпать порциями в основную массу. Тесто должно получиться густым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Выложить массу в чашу мультиварки, сформовать бортики, готовить в режиме «Выпечка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Вынуть, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9610,'Для начинки набухший желатин смешать с половиной оставшегося киселя, прогреть до растворения, но не кипятить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9611,'Взбить сырое куриное яйцо, добавить очищенную и натертую морковь, влить теплый кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9611,'Массу перемешать, добавить пищевую соду, овсяную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9611,'Выпечь оладьи, их можно подать как горячими, так и холодными, с кефиром или со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Рыбу нарезать порционными кусками, посолить и поперчить, выложить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Нарезать кружочками соленые огурцы и свежие помидоры, сладкий болгарский перец – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Помидоры выложить по краю формы, остальные овощи – посередине.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Для соуса взбить сырые куриные яйца с солью, добавить горчицу, снова взбить и развести массу молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Полученной смесью залить рыбу, поставить форму в духовку, печь в течение 40 – 45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9612,'Блюдо вынуть, при подаче посыпать свежей рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9613,'Взбить творог с сырым яйцом, добавить мёд, тертое яблоко, мак.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9613,'Массы выложить в формочки для запекания, готовить в пароварке в течение 20 – 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9613,'Это блюдо можно приготовить в духовом шкафу при температуре 200 градусов, на это потребуется 15 – 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9613,'Третий способ: аэрогриль, запекать полчаса на средней решетке, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'Нарезать филе соломкой, очистить и нарезать полукольцами репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'Очистить от семян сладкий болгарский перец, также нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'На сковороде обжарить в течение несколько минут перец и лук. Масло не добавлять, можно подлить немного воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'К курице добавить рубленый чеснок, сметану, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'Переложить массу в обжарку, снова перемешать и довести до кипения. Можно подлить воду, если блюдо получается суховатым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'Довести смесь до кипения, тушить под крышкой в течение семи минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9614,'Несколько раз перемешать. Мясо должно побелеть изнутри и снаружи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9615,'Натереть на крупной терке замороженные крабовые палочки, сваренные вкрутую куриные яйца, свежий огурец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9615,'Измельчить зелень петрушки и укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9615,'Выложить на лепешку сначала зеленую массу, затем насыпать палочки, яйца, огурец. Соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9615,'Закуску из лаваша свернуть в виде рулета, плотно завернуть в пищевую пленку, положить в холодильник не менее, чем на шесть часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9616,'Просеять пшеничную муку, порубить очищенные грецкие орехи и миндаль. Смешать грубые овсяные хлопья, муку с орехами, сушеную вишню, разрыхлитель, сахарный песок, молотую корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9616,'Из яблока вынуть сердцевину, очистить кожицу. Очистить банан от кожуры, оба фрукта измельчить вместе в блендере вместе с маслом оливы, ванильной эссенцией.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9616,'Полученную массу влить в сухую смесь, перемешать. Можно добавить муку, если тесто получилось жидковатым, или долить воду, если оно слишком сухое.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9616,'Противень застелить бумагой для выпекания, выложить полученное тесто столовой ложкой, прижать. Печь овсяные плюшки с вишней и орехами в течение 25–30 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9617,'Клубни картофеля хорошо вымыть, но не чистить. Каждую картофелину разрезать на четыре части, вдоль. Посыпать солью, поперчить, можно добавить любые специи для овощей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9617,'Картофель выложить на противень, предварительно смазанный оливковым маслом. Кусочки не должны друг с другом соприкасаться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9617,'Сбрызнуть картофельные дольки оливковым маслом и запечь при температуре 200 градусов в течение 20 минут, затем перевернуть и печь еще 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9618,'Для приготовления вафельного теста смешать сахарный песок, соль, сырые куриные яйца, влить молоко и растительное масло. Всыпать просеянную пшеничную муку, разрыхлитель. Массу перемешать. Тесто должно быть похоже на густую сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9618,'Приготовить вафли в вафельнице, температура выпечки–200 градусов. Они могут быть круглой или прямоугольной формы. Готовую выпечку выкладывать отдельно друг от друга, вафли должны подсохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9618,'Для приготовления крема смешать творог, свежие ягоды смородины, растопленный в микроволновой печи или на водяной бане шоколад любого сорта: горький, молочный, белый. Добавить жидкий мед, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9618,'Сделать два торта небольшого размера из шести вафель каждый, «коржи» промазывать кремом. Для покрытия вафельных пирожных перетереть смородину с сахаром, намазать выпечку полученной массой сверху. Остатки вафель покрошить сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Пропустить через мясорубку куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Измельчить чеснок, добавить в фарш вместе со сливками, яичными белками и специями: сладкой паприкой, черным молотым перцем, сухими травами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Хорошо перемешать, масса должна быть однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Полученный фарш выложить на лист фольги, уплотнить, завернуть, закрутить концы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Поверх колбаску обернуть пищевой пленкой в несколько слоев.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Выложить изделия в кастрюлю с водой, варить в течение 30 – 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9619,'Вынуть, остудить. Положить на ночь в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Филе курицы довести до кипения, варить в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Отдельно отварить брокколи, после закипания варить семь-восемь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Мелко покрошить репчатый лук, можно использовать лук-порей, этот продукт обладает более нежным вкусом, его нарезать полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Отваренное филе птицы нарезать кусочками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Натереть на средней терке твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'В одну большую форму или в несколько порционных выложить сыр и полить сливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Следующие слои – филе, брокколи, лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Соль и перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Полить смесью сыра и сливок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9620,'Печь в духовке в течение 20 – 25 минут при температуре 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9621,'Вымыть рис, переложить в чашу мультиварки, варить на режиме «Гречка» до сигнала.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9628,'Сформовать мокрыми руками небольшие лепешки, положить в каждую по грецкому или миндальному орешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9621,'Измельчить на мясорубке мясо и лук, добавить вареный рис, смесь перцев, вбить яйцо, перемешать. Скатать шарики-«ёжики», переложить в чашу мультиварки, убрать на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9621,'Взбить блендером  1 мультистакан воды с томатной пастой, мукой и сметаной, добавить чеснок, базилик, укроп, всыпать приправу для мяса, сахар, соль, взбить еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9621,'Залить соусом «ёжики», заправить лавровым листом. Готовить ежики в томатном соусе с базиликом в мультиварке на режиме «Тушение» час, переключить на «Подогрев», выдержать полчаса, подавать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Нарубить репчатый лук и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Смешать белый уксус с соевым соусом, можно разбавить водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Добавить в маринад лук и чеснок, соль, перец молотый, лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Перемешать, залить смесью куриные бедра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Накрыть емкость полотенцем, дать постоять в течение двух часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Через два часа поставить кастрюлю на огонь, довести содержимое до кипения, потомить на тихом огне 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9622,'Подать к столу с небольшим количеством маринада.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9623,'Вскипятить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9623,'Всыпать смесь свежих или замороженных овощей, состав – на вкус хозяйки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9623,'Натереть сыр, добавить в суп, помешивать до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9623,'При подаче положить в суп нарезанное кубиками отваренное яйцо и рубленую зелень укропа или петрушки, кинзы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9624,'Очистить яблоки от кожицы и семенных камер, натереть на мелкой терке или порезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9624,'Протереть через сито нежирный творог, смешать с яблоками, вымытым и обсушенным изюмом, добавить молотую корицу, сырые куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9624,'Массу хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9624,'Выложить смесь в смазанную маслом форму, печь в течение 15 – 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9625,'Очистить от кожуры и натереть спелое яблоко, добавить сырое яйцо и творог, сахарозаменитель и ванилин, молотую корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9625,'Массу хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9625,'Разложить смесь в порционные формочки, печь в духовке или в микроволновой печи в течение пяти-семи минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9626,'Нарезать говядину небольшими кусочками, поперек волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9626,'Намазать готовой горчицей или любым любимым маринадом, дать постоять в течение шести-восьми часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9626,'Соль и перец молотый – по вкусу, можно добавить любые пряности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9626,'Выложить мясо на основной противень пароварки, сверху – помидоры, тертый или нарезанный пластинками сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9626,'Готовить блюдо в течение 45 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'В миску влить молоко, подогретое до 300 С, развести в нем  дрожжи, всыпать сахар, соль, муку,  вбить яйцо, добавить масло сливочное размягченное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Замесить тесто, накрыть миску пищевой пленкой, поставить миску с тестом в холодильник на 3 часа (не меньше!).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Как только объем теста увеличится вдвое, достать миску из холодильника, оставить на столе на 1 час, чтобы тесто постояло при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'По истечении отведенного времени тесто нужно раскатать в круг, толщина которого должна быть 0,6 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Свежее филе форели порезать на куски толщиной по 2,5 см каждый и, отступив от края тестяной заготовки 3,5 см, выложить по кругу рыбу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Накрыть куски форели тестом с краев, тщательно и осторожно залепить получившийся шов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Получившийся валик порезать кусками по 4 см в ширину, каждый кусок повернуть рыбой вверх на 90 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Остальную рыбу порезать кусочками, поместить все в центр будущего пирога.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Поверх рыбы распределить кружочки помидоров и перца, все поперчить и посолить, накрыть кусочками сыра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Поставить форму на полчаса в теплое место, после чего отправить заготовку в разогретую духовку и выпекать пирог с форелью, сладким перцем и сыром моцарелла 30 минут при 180 градусах.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9627,'Когда после начала запекания пройдет 20 минут, пирог нужно смазать яичным желтком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9628,'В глубокой тарелке растереть творог с йогуртом и натуральным мёдом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'Для того чтобы приготовить штрейзель, необходимо смешать муку, предварительно растопленное масло сливочное (если нет масла, то можно использовать маргарин), сахар и какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'С помощью вилки мешать массу до тех пор, пока она не превратится в крошки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'Яйца взбить с сахаром, влить кефир, ввести смешанную с разрыхлителем муку, добавить растительное масло .',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'Хорошо все перемешать, слегка взбить, всыпать  орехи, тщательно  перемешать тесто еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'В смазанную форму переложить полученное тесто, сверху посыпать будущий кекс с орешками на кефире штрейзелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9629,'Убрать форму в духовку и выпекать кекс в течение 40-45 минут при 180-200 градусов, пока он не станет в 1,5-2 раза больше.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Мелко нарезать стебель сельдерея, очищенный чеснок, укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Приготовить фарш из куриного филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Все ингредиенты перемешать, посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Можно добавить толченый в ступке кориандр и душистый перец, другие любимые специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Разделить массу на две части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Вырезать из фольги два прямоугольника, выложить на них смесь в виде колбасок. Удобнее это делать мокрыми руками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9630,'Изделия аккуратно завернуть, сформовать, уплотнить, готовить в пароварке в течение получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Растворить в молоке любой сахарозаменитель, добавить сырое куриное яйцо, всыпать перемолотые с помощью блендера овсяные отруби, разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Печь корж при температуре 180 градусов в течение 25 – 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Сделать второй слой: так же растворить в молоке сахарозаменитель, перемешать с творогом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Смесь выложить на корж.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Для последнего слоя крупно нарезать свежие ягоды клубники, выложить на творог.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Отдельно приготовить красное желе так, как написано на упаковке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Массу немного остудить, залить ягоды на треть, дать застыть, затем вылить на торт остатки желе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9631,'Поставить в холодильник до полного загустения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9632,'Заранее отваренное куриное филе мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9632,'Сырые куриные яйца взбить с молоком и солью, добавить черный перец, карри, итальянские травы, клетчатку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9632,'Отдельно натереть твердый нежирный сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9632,'Все ингредиенты перемешать, выложить в форму для выпекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9632,'Прогревать в течение 35 – 40 минут при температуре 200 градусов, до образования золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9633,'Нарезать соломкой хорошо промытую и обсушенную курагу и чернослив.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9633,'Насыпать на пищевую пленку кокосовую стружку, выложить обезжиренный творог, массу разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9633,'Сверху – нарезанные сухофрукты, свернуть рулетом, поставить в холодильник на 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9633,'Готовый рулет нарезать на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9634,'Вымыть куриные грудки, удалить лишний жир, если он есть на продукте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9634,'Посыпать мясо специями для курицы, завернуть каждую грудку в тонкие полоски бекона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9634,'Печь на решетке на противне в духовом шкафу, время выпечки – 15 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9634,'Подрумяненные «рулеты» выложить на слой замороженной фасоли, насыпанной на пергамент.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9634,'Поставить блюдо в духовку еще на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'Взбить вместе с солью и молотым черным перцем 2 яйца, добавить сметану, после чего влить кефир, массу хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'Муку смешать с разрыхлителем, ввести в кефирно-яичную массу, замесить стойкое тесто (как для простых оладушек).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'Два яйца отварить, очистить, порубить кубиками, промытый зеленый лук, мелко порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'В тесто добавить подготовленные лук и яйца, хорошо все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'На сковородке разогреть растительное масло и обжарить в нем оладьи с яйцом и зелёным луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9635,'Подавать готовые оладьи на кефире с зеленым луком и яйцом горячими, дополнив сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Прогревать, помешивая, пока зелень не станет мягкой, хорошо перемешать с пастой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Грудку индейки измельчить в фарш с помощью блендера или мясорубки вместе с репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Добавить много рубленой петрушки, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Сформовать мокрыми руками небольшие котлеты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Положить изделия в пароварку, между ними должно быть свободное место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Готовить в течение 20 минут, один раз перевернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'В другую емкость насыпать свежую или замороженную зеленую фасоль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Если продукт свежий – вымыть, отрезать стебли.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Варить в течение 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Готовые котлеты должны изменить цвет.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9636,'Подать с фасолью, её можно не солить, а полить перед подачей соевым соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9637,'Хорошо перемешать обезжиренный творог и сырые куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9637,'Добавить по вкусу свежую рубленую или сушеную зелень, соль, перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9637,'Печь на тихом огне, под крышкой, в течение десяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9638,'Для приготовления блюда понадобится горбуша целиком или большой кусок без хвоста и головы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9638,'Очистить и нарезать репчатый лук, чеснок, порубить укроп, смешать ингредиенты с солью и молотым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9638,'Кусок фольги большого размера смазать растительным маслом, выложить нафаршированную рыбу, смазать тушку маслом сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9638,'Завернуть рыбу в фольгу, можно сделать два слоя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9638,'Печь в духовом шкафу при температуре 20 – 25 градусов, до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9639,'Рыбу поперчить, посолить, обжарить на растительном масле в течение двух-трех минут с каждой стороны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9639,'Отдельно измельчить репчатый лук, обжарить на растительном масле, добавить консервированные мелкие шампиньоны целиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9639,'Залить обжарку натуральным йогуртом, всыпать карри, соль и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9639,'Полученный соус хорошо перемешать, прогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9639,'Готовую рыбу выложить на тарелку, полить соусом, посыпать рубленой зеленью укропа и петрушки, лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9640,'Отварить сырые куриные яйца, очистить и нарезать.','https:https://st.vkuso.ru/data/cache/thumb/4b/8e4a209758e254b_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9640,'Разрезать спелый плод авокадо, надрезать мякоть в виде «решетки», выскоблить её ложкой.','https:https://st.vkuso.ru/data/cache/thumb/a8/fe667023a3c86a8_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9640,'Раскалить сковороду, обжарить мелко нарубленный чеснок вместе с очищенными замороженными креветками. Жидкость должна выпариться.','https:https://st.vkuso.ru/data/cache/thumb/95/afa366cb40b2195_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9640,'Добавить морепродукт к остальным ингредиентам и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/fd/e642ef1a76fedfd_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9640,'При подаче салат сбрызнуть по вкусу свежим лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'Смешать в миске среднего размера обезжиренное молоко и пшеничную муку, масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'Вмешать в полученное тесто творог, яйца, натертый нежирный сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'В смесь добавить тертый сыр «Чеддер», сахарный песок и молотый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'Емкость для выпекания смазать маслом, вылить смесь, печь в течение 45 – 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'Пирог должен подрумяниться и подняться, увеличиться в размере.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9641,'Готовность можно проверить с помощью ножа или зубочистки. Подать блюдо в теплом виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Для коржа-основы перемолоть с помощью блендера овсяные или цельнозерновые хлопья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Натереть очищенное яблоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Инжир и финики мелко нарезать, измельчить в блендере, но не до состояния пюре, должны остаться целые кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Превратить в пюре спелый банан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Все ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Полученную массу переложить в форму для выпекания со съемными бортиками, выровнять, немного утрамбовать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Поставить «корж» в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Для приготовления крема перемешать нежирный грушевый йогурт, обезжиренный кремообразный творог, мёд.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Очистить и нарезать грушу тонкими пластинками или кубиками, добавить в творожный крем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Выложить полученную массу на охлажденную основу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9642,'Украсить кусочками груши, грецкими или миндальными орехами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9644,'Взбить в однородную массу хлопья «Геркулес», банан средней величины, сырое куриное яйцо, молоко и разрыхлитель для теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9644,'Печь блинчики на сковороде с антипригарным покрытием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9644,'При подаче уложить панкейки «башенкой», можно промазать мягким нежирным творогом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Для приготовления основы смешать в миске кокосовую стружку, овсяные хлопья «Геркулес», шоколадный протеин, молоко и сырой белок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Выложить массу в форму из силикона или в обычную, смазанную маслом или проложенную пекарской бумагой. Лучше использовать разъемную форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Печь при температуре 180 градусов в течение семи минут, должна образоваться золотистая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Отдельно замочить в воде желатин, отжать через пять минут, поставить в микроволновую печь на 10 секунд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Вылить готовый продукт в мягкий творог, добавить сахарозаменитель, перемешать массу с помощью блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Выложить на дно разъемной формы остывшую основу, сверху – большую часть творожной массы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'В оставшуюся часть добавить свежую или размороженную чернику, взбить смесь с помощью блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Выложить поверх творожного слоя.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9645,'Украсить блюдо целыми ягодами черники и поставить в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Желе растворить в воде так, как написано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Отдельно взбить с помощью миксера обезжиренный творог, протеин, подлить немного воды (100 мл).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Взбить с 50 мл воды вишню и часть полученного желе, вылить массу в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Поставить в морозильную камеру на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Оставшуюся желатиновую массу перемешать с творогом и протеином и взбить в мягкую воздушную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'На охлажденное клубничное желе выложить творожную смесь, поставить в морозилку еще на час или два.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9646,'Перед подачей поместить форму с пирогом в горячую воду на несколько секунд, выложить на тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9647,'Нарезать куриную грудку, посыпать приправами, солью.','https:https://st.vkuso.ru/data/cache/thumb/53/35ee07a53a86253_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9647,'Обжарить со всех сторон, мясо должно побелеть.','https:https://st.vkuso.ru/data/cache/thumb/5a/2dc36420f28d05a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9647,'Влить красное вино, оно должно доходить до середины курицы, оставить на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9647,'Добавить любой плавленый сыр, прогревать, помешивать лопаткой. Оставить на две-три минуты, сыр должен полностью расплавиться.','https:https://st.vkuso.ru/data/cache/thumb/bf/fabae49aaeef1bf_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9647,'Если полученная смесь будет использоваться, как соус к спагетти, то оставить её полужидкой, если задумано самостоятельное блюдо – прогревать его дольше, пока не выпарится большая часть влаги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Подготовить яблоки, разрезать каждое на две равные части, вынуть часть мякоти, чтобы получилось подобие корзиночек, побрызгать лимонным соком, всыпать внутрь каждой по паре столовых ложек сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Порубить орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Сухофрукты вымыть, порезать на кусочки, залить крутым кипятком, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Сцедить, перемешать с медом и орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Наполнить полученной смесью яблочные «корзиночки», переложить их на противень, выстланный пергаментом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Поместить противень в прогретую примерно до 160 градусов духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'Десерт яблочные корзиночки с сухофруктами и орехами будет готово минут через сорок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9648,'На сковороде растопить сахар с парой ложек воды, дождаться изменения цвета на чуть коричневатый, полить каждую половинку яблока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Начинать приготовление лучше с начинки. Пластинки желатина, залить водой минут на 10.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Всыпать в йогурт сахарную пудру, взбить до ее растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Прогреть желатин до растворения, дать остыть, хорошо перемешать со взбитым йогуртом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Добавить хорошо взбитые сливки, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Измельчить печенье в крошку, залить растопленным маслом, перемешать, уложить ее на дно формы, утрамбовать с помощью столовой ложки, дать застыть в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9649,'Достать основу для летнего ягодного чизкейка без выпечки, заполнить начинкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Переложить помидоры с куриным филе и кукурузой на противень, отправить минут на 10 в прогретую до 170 градусов духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9650,'Готовую закуску посыпать мелко порубленной зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9651,'Измельчить блендером до пастообразного состояния порезанный на крупные куски базилик, фету и творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9651,'Порубить орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9651,'Скатать влажными руками из полученной массы шарики, как для пинг-понга.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9651,'Запанировать в порубленных орехах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9651,'Убрать творожно-сырные шарики с грецким орехом на полчаса в холодильник и можно подавать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9652,'Подготовить овощи, разрезать помидоры пополам, перцы, удалив семена – на 4 части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9652,'Морковь натереть, измельчить вместе с чесноком и горьким перцем на мясорубке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9652,'Переложить массу в кастрюлю, проварить аджику из помидоров, перцев и чеснока при слабом нагреве около полутора часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9652,'Всыпать соль, добавить масло, порубленную зелень, сахар, варить еще полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'з хорошо охлажденный белков взбить пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'Не переставая взбивать всыпать порциями сахар (лучше мелкий), должно получиться «тесто», сохраняющее форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'Для получения красивого вкусного безе от Speso по-домашнему заполнить белковой массой шприц, отсадить небольшими порциями на выстланный пергаментом противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'За неимением оного можно воспользоваться обычной столовой ложкой, но тогда безе получится не такой идеальной формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'Задвинуть противень в холодный духовой шкаф, установить температуру на уровне 90-100 градусов, подсушить десерт в течение примерно 2,5 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9653,'Все это время необходимо следить, чтобы безе не покрылось коричневым «загаром».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'Хорошо вымытые свиные ребрышки порезать порционными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'Апельсин и лайм очистить от кожуры, выдавить из каждого цитруса сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'Очищенный чеснок измельчить любым удобным способом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'В большой миске смешать цитрусовый сок, чеснок, горчицу, черный молотый перец, молотую паприку, мед,  оливковое масло и сушеный укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'В получившийся маринад погрузить подготовленные ребрышки, тщательно перемешать и убрать миску в холодильник на 3 часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'Когда ребра замаринуются их нужно выложить в два слоя фольги, залить тем же маринадом и завернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9654,'Форму отправить в духовку и при 180 градусах запекать ребрышки свиные в медово-цитрусовом маринаде на протяжении полутора часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9655,'Закипятить, помешивая молоко с сахаром, пока последний полностью не растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9655,'Нагрев уменьшить, положить в кастрюлю масло, мед, сгущенку, чуть подсолить, перемешать, дать смеси закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9655,'После сгущения и окрашивания смеси в аппетитный коричневатый цвет, взбить ее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9655,'Заполнить пока еще достаточно жидкой медовой помадкой со сгущенкой смазанную маслом форму из силикона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9655,'Дать застыть, порезать на небольшие кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9656,'Порезать филе без кожи на небольшие квадратные кусочки, сложить в глубокую миску, присыпать солю и перцем, перемешать, присыпать мукой, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9656,'Промазать форму маслом, заполнить частью мяса, прикрыть его кружочками баклажана.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9656,'Затем – помидоры, далее положить оставшееся мясо, опять баклажаны и помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9656,'Присыпать сырной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9656,'Отправить на полчаса в духовку, где температура должна быть около 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Яйца разрезать на половинки, мелко нарубить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Отварить стручковую фасоль и порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Маслины нарезать колечками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Рис сварить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Слить масло из банки с тунцом, порезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Все перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Заправить хорошо перемешанной смесью уксуса, оливкового масла, приправленных порубленным тимьяном и солью с перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9657,'Верх рисового салата с тунцом и стручковой фасолью оформить порезанными яйцами и можно сразу подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Грибы помыть, обсушить, разрезать крест-накрест на 4 части, бросить в кипящую подсоленную воду, варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Нашинковать лук на полукольца, чуть обжарить в оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Добавить полоски сладкого перца обжарить пару минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Выдавить чеснок, присыпать орегано, петрушкой и базиликом, хорошо размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Прогреть все около минуты, снять с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Соединить полученную массу с грибами и кубиками апельсина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Сдобрить грибной салат «Афина» перцем, подсолить, побрызгать лимонным соком, размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9658,'Закрыть сковородку крышкой, дать постоять, переложить на блюдо и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'В емкость сложить сливочное масло и шоколад, все вместе растопить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'В кастрюльку или сотейник влить сливки, дать  закипеть и перелить к ним шоколадно-масляную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'Влить виски (можно использовать бренди), тщательно перемешать, накрыть емкость пищевой пленкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'Посудину убрать на 2 часа в морозилку, после чего достать и из подмороженной массы сформовать конфетки-шарики по 2 см в диаметре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'Получившиеся шарики убрать еще на полчаса в морозилку, а по истечении 30 минут каждый шарик обвалять в какао.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9659,'Панированные конфеты трюфели по-домашнему снова поместить в холодильник и достать непосредственно перед подачей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Отделить пару желтков, соединить с яйцами, всыпать сахарный песок, взбить до получения устойчивой пышной пены.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'В другой емкости смешать крахмал, разрыхлитель, муку и просеять все в тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Перемешать, заполнить полученной массой смазанную маслом форму, отправить ее минут на 25 в уже прогретую чуть выше 170 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'В чашу блендера поместить белки, всыпать сахарную пудру, взбить до крепкой пены.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Разложить поверх зарумяненного бисквита.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Запечь основу для торта с безе и творожно-фруктовой начинкой до золотистости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Дать остыть, разрезать вдоль на 2 коржа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Творог соединить со взбитыми с сахаром сливками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Перемешать крем с кусочками фруктов или ягодами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Поместить корж в разъемную форму, чуть пропитать его молоком с добавлением ликера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Промазать кремом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Прикрыть вторым коржом. Украсить дольками апельсина.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9660,'Отправить минимум на пару часов в холодильник и можно подавать к столу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Удалить у долек апельсина кожицу, полить соком, поместить в мисочку, запаковать пленкой, чтобы не высыхали.','https:https://st.vkuso.ru/data/cache/thumb/51/a8cc250446c7f51_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Нагреть сковороду с маслом, соком лайма, положить измельченный чеснок, прогреть полчаса, добавить креветки, присолить, поперчить, прогреть пару минут, убрать с плиты.','https:https://st.vkuso.ru/data/cache/thumb/e3/68bf5320c68b1e3_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Нашинковать шалот на тонкие полукольца.','https:https://st.vkuso.ru/data/cache/thumb/62/9d4e77d0effbe62_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Порезать также авокадо.','https:https://st.vkuso.ru/data/cache/thumb/8d/8696277e81e2e8d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'На плоское блюдо положить авокадо, присолить, поперчить, присыпать щепоткой сахара.','https:https://st.vkuso.ru/data/cache/thumb/60/0e8750493b21a60_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Прикрыть слоем прогретых креветок, а затем апельсинами полить верх апельсиновым соком.','https:https://st.vkuso.ru/data/cache/thumb/ff/705eae3e72befff_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9661,'Притрусить колечками лука, присыпать сахарным песком, полить легкий салат из креветок, авокадо и апельсина соком лайма, перемешать, присыпать порубленной кинзой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Отварить в большом количестве подсоленной воды пасту, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Нагреть в глубокой сковороде масло, обжарить, помешивая очищенные креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Присолить, поперчить, добавить порубленный чеснок, перемешать, обжарить все вместе примерно с полминуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Переложить содержимое сковороды на тарелку, а в нее влить бульон с крахмалом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Добавить высушенный базилик, влить лимонный сок, дать смеси закипеть и сгуститься (достаточно будет пары минут).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9662,'Разложить сковороду средиземноморских креветок с пастой по тарелкам, посыпать размельченной фетой, молотым черным перцем и свежей зеленью базилика.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'Клубни картофеля хорошо вымыть, разрезать вдоль на 2 половинки, а потом каждую еще раз на половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'В небольшой мисочке перемешать масло со специями и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'Кусочки картофеля обмакнуть в смесь и разложить на противне, промазанном маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'Задвинуть его на треть часа в прогретую до 180 градусов духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'Поднять температуру на 30-40 градусов, подержать еще треть часа в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9663,'Переложить золотистый картофель по-деревенски в духовке в тарелку и можно подавать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Включить прогреваться духовку примерно до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Перемешать просеянную подсоленную муку с черным перцем, солью, порошком горчицы, измельченным розмарином, тимьяном и сухим укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Порезать на кубики ветчину и сыр, добавить к мучной смеси и хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Насыпать горкой, сделать на вершине углубление, влить в нее взбитые с молоком яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Добавить чуть взбитое масло, вымесить тесто, но недолго.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'В форму для маффинов вставить бумажные формочки, побрызгать их маслом, и заполнить тестом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Поставить маффины с сыром, ветчиной и пряными травами в уже достаточно прогретую духовку минут на 25 достать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9664,'Дать чуть остыть, вынуть из формочек и сразу подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Раскатать пласт готового теста, порезать на 4 полосы около 8 см ширины.','https:https://st.vkuso.ru/data/cache/thumb/14/96cfcc55cc40c14_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Натереть на терке сыр.','https:https://st.vkuso.ru/data/cache/thumb/af/089fea9831124af_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Обжарить размороженную фасоль с приправами и солью.','https:https://st.vkuso.ru/data/cache/thumb/ee/8b2dffe874263ee_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Уложить на полосу теста сырную стружку, далее - оливки и фасоль, можно присыпать зеленью, свернуть в рулет.','https:https://st.vkuso.ru/data/cache/thumb/dc/7fd7ede47f879dc_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Края смазать разболтанным яйцом или смочить водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Застелить круглую форму пергаментом, промазать маслом.','https:https://st.vkuso.ru/data/cache/thumb/ac/9b17b7b403254ac_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Один за другим выложит рулеты по спирали, скрепляя края.','https:https://st.vkuso.ru/data/cache/thumb/a2/e5ad8cad1de97a2_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Смазать верх слоеного пирога с сыром и фасолью по-деревенски яйцом, присыпать семенем кунжута.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9665,'Отправить на треть часа в духовку с температурой порядка 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Порезать молодой кабачок на кружочки в толщину по 0,5 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Лук нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Перец порезать на полоски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Клубни картофеля – на тонкие слайсы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'На дно промазанной маслом формы выложить картофель, чуть присолить, поперчить, прикрыть еще одним слоем картофеля, сдобрить солью и перцем, далее положить кабачки.','https:https://st.vkuso.ru/data/cache/thumb/5f/dc59b7fc7a1695f_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'А на них положить смесь из сладкого перца и лука, посолить, поперчить, присыпать майораном и орегано, полить маслом.','https:https://st.vkuso.ru/data/cache/thumb/bf/09767119fd0d1bf_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Прикрыть слоем бекона, а потом – парой слоев картофеля.','https:https://st.vkuso.ru/data/cache/thumb/84/36bb64ffe1c2684_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Запеченный картофель с беконом и болгарским перцем поперчить, присолить, сбрызнуть маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Форму накрыть фольгой, поместить на 15 минут в духовой шкаф с температурой около 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9666,'Осторожно удалить фольгу и запекать еще 20 минут, чтобы картофель покрылся аппетитной прожаренной корочкой.','https:https://st.vkuso.ru/data/cache/thumb/9a/ae99f33972b5b9a_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9667,'Ветчину и сыр нарезать ломтиками средней толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9667,'Сложить ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9667,'Панировать шницель в муке, далее хорошенько обвалять его в слегка взбитом яйце, опять обвалять в муке, затем снова в яйце.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9667,'Переложить шницель из ветчины и сыра на хорошо разогретую сковородку с маслом, жарить его со всех сторон по одному разу до образования поджаристой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9667,'Как только шницель будет готов его необходимо подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Нагреть масло на небольшом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Закрыть и оставить тушить минут восемь, баклажан должен стать полу готовым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Положить в сковороду помидорки, посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Закрыть, тушить минут пять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9668,'Насыпать специи, добавить петрушку, тушить минуты две под крышкой до готовности баклажанов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Порезать картофель как угодно, только не тоненькой соломкой, так как картофель может превратиться в кашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Порезать лук на тоненькие полукольца, морковь на длинные брусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Потереть помидор, положить к картофелю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Помидор сделает картофель сочным, компенсирует количество масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Положить все в посуду. Посыпать приправами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Если приправы без соли, то подсолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Налить растительное масло. Размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Упаковать все в рукав для выпекания, отправить в духовку, засечь время и можно заниматься своими делами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Картофель запекать 90 минут, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Порезать мелко чесночок, зелень, добавить в картофель.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Накрыть пленочкой, оставить минут на пять, чтобы блюдо пропиталось ароматами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9669,'Разложить жареную картошку проще простого по тарелочкам.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Кипятить инжир в воде минут пять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Подсушить, измельчить в блендере до состояния пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Нагреть масло, добавить миндальный порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Жарить несколько минут на небольшом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Положить инжирное пюре, сухое молоко, налить воду, готовить минут пять, помешивать, пока не растворится сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Добавить кардамон, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Подавать в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9670,'Можно скатать инжирную халву с миндалем в шарики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Взбить яйца, посыпав по вкусу солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Порезать колбаску соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Соединить колбаску и сваренные макароны, налить взбитые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Переложить смесь в формочку для запекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Отправить в духовку, запекать до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Запеканку посыпать тертым сыром, отправить в еще неостывшую духовку минут на семь, чтобы расплавился сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9671,'Можно подавать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9672,'В подсоленной воде до полной готовности отварить рис, положить в него масло сливочное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9672,'Добавить к рису отваренные креветки, консервированную кукурузу, натертый сыр и рубленую зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9672,'Немного взбить яйца вместе с молоком и специями, перелить получившуюся массу к рису и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9672,'Выложить готовую рисовую массу в форму для выпечки или в формочки для кексов и отправить в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9672,'Выпекается рисовая запеканка с кукурузой, креветками и сыром при 200 градусах в течение 20 минут, после чего охлаждается и достается из формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Растворить в теплой воде дрожжи, позволить им настояться минут пять, чтобы прошла реакция.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Насыпать муку, соль, налить оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Размешать, чтобы тесто стало рассыпчатым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Посыпать мукой стол, замесить тесто. Месить минут семь, чтобы тесто стало цельным, гладким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Положить его в кастрюльку или емкость, смазанную маслом, накрыть пленкой, отправить в тепло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'После поднятия теста в два раза поделить его на восемь равных частей, раскатать лепешки толщиной приблизительно по семь миллиметров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Если пита будет готовиться в духовке, то разогреть ее до 220 градусов, положить лепешки на противень, готовить минуты три.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'В духовке лепешки набухнут мгновенно. Из духовки можно вынимать, когда пита станет шарообразной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Накрыть лепешки полотенцем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Если предполагается готовить питу на сковороде, то разогреть ее, налить несколько капель масла, положить лепешку на сковороду (желательно чугунную).',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Секунд через тридцать появятся пузырьки. Перевернуть лепешку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9673,'Готовить питу минуты две, опять перевернуть, готовить еще минуту.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Подготовить все ингредиенты, охладить белки, сварить чашку натурального кофе, нагреть духовку до 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Измельчить орехи в блендере. Насыпать муку, ¼ стакана сахара.','https:https://st.vkuso.ru/data/cache/thumb/7e/b33816a6b80b47e_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'На противень прямоугольной формы и большого размера постелить специальную бумагу, намазать рафинированным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Взбить белки с солью до густой пены, насыпать сахар, взбивать, пока не растворится сахар.','https:https://st.vkuso.ru/data/cache/thumb/ca/518d01bc89028ca_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Положить ореховую смесь, осторожно размешать.','https:https://st.vkuso.ru/data/cache/thumb/25/cdd994e17f5d225_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Равномерным слоем положить на бумагу тесто.','https:https://st.vkuso.ru/data/cache/thumb/ff/5cc9babf5acddff_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Готовить в духовке минут пятьдесят, соблюдать температуру 160 градусов.','https:https://st.vkuso.ru/data/cache/thumb/19/cbccb561990e119_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Позволить остыть, снять бумагу. Она отделяется с легкостью.','https:https://st.vkuso.ru/data/cache/thumb/6b/789503a3cb9c66b_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Остудить кофе, процедить, добавить большую ложку желатина, отправить в микроволновую печь секунд на десять, чтобы разошелся желатин.','https:https://st.vkuso.ru/data/cache/thumb/8b/2a062bc116d428b_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Взбить сливки в баночке до густого состояния, насыпать сахарную пудру. Когда разойдутся крупинки, тоненькой струйкой налить ликер и кофейно-желатиновую смесь. Отправить баночку в холод.','https:https://st.vkuso.ru/data/cache/thumb/a2/a494bd5148f76a2_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Остывший корж разрезать на две или четыре части, от этого зависит количество слоев в тортике.','https:https://st.vkuso.ru/data/cache/thumb/38/1da074d6a2c8638_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Намазать кремом.','https:https://st.vkuso.ru/data/cache/thumb/fb/ac18385b7f209fb_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Украсить конфетами «Рафаэлло» или другими.','https:https://st.vkuso.ru/data/cache/thumb/ba/92f9dbdeb6a5eba_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Сверху посыпать стружкой кокоса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9674,'Отправить Сливочно-миндальный торт Рафаэлло для пропитки в холодильник, на второй день он еще вкусней.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9675,'Тонко порезать и слегка отбить куриное филе, каждый кусок поперчить, посолить и посыпать специями для курицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9675,'Немного взбить вилкой яйца, добавить мелко натертый сыр, небольшое количество муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9675,'Подготовленные куски мяса по очереди обмакнуть в сырно-яичный кляр, обжарить со всех сторон на раскаленной сковороде до образования золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9675,'Подать куриное филе под  сырной хрустящей корочкой к столу с любым гарниром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Подогреть кислое молоко, до кипения не доводить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Насыпать сахар и дрожжи, оставить минут на десять, дрожжи должны забродить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'В емкости для миксера взбить сливочный сыр, масло, желтки, яйцо, коричневый сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Не переставая взбивать, положить готовые дрожжи на кислом молоке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Насыпать муку, соль, не переставать взбивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'После того, как смешаны все продукты, достать из миксера лезвие.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Насыпать оставшуюся муку, замесить руками тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Сформировать шарик из теста, отставить часа на три при комнатной температуре, чтобы тесто увеличилось.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Приготовить начинку: размять при помощи вилки сливочное масло, коричневый сахар, мускатный орех, корицу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Размешать до однородности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Довести почти до кипения сливочное масло, сироп, мед, коричневый сахар в небольшой кастрюльке на среднем огне.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Время от времени помешивать, чтобы растворился сахар.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Убрать с огня, насыпать ванилин, корицу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Налить данную смесь в формочку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Посыпать грецкими орехами.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'На поверхности, посыпанной мукой, раскатать и растянуть тесто руками.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Приготовить из теста большой прямоугольник, нанести коричневую масляную массу по всей поверхности.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Посыпать сахаром коричневого цвета.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Скрутить рулетик, намазать острый нож маслом, порезать рулетик на двенадцать частей.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Положить булочки-спиральки на блюд в карамельный соус.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Накрыть блюдо пленочкой, отставить часа на два, чтобы булочки увеличились в размере.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Достать из духовки, пройтись по краешкам ножом, чтобы достать булочки.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9676,'Минут через десять перевернуть блюдо, достать булочки с корицей и орехами в сиропе. Соус окажется сверху. Подавать в теплом виде.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Отварить креветки в ароматных специях (черный перец горошком, соль, лавровый лист и так далее). Позволить остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Разрезать все креветки на две или четыре части (резать креветки, если они большие тигровые или королевские).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Почистить отваренный картофель, потереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Измельчить отваренные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Положить салатик слоями: сначала майонез, затем ½ очищенных креветок, картофель, яйца, оставшиеся креветки, красная икра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Все слои промазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Икру выкладывать равномерно по верхнему слою.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'В качестве украшения слоеного салата с креветками под красной икрой использовать, зелень, лимонные дольки и большие креветки в целом виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9677,'Отправить салат в холодильник часов на шесть, чтобы он настоялся.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'В большой емкости соединить кукурузу, мясо креветок, соль, перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Размешать, чтобы получилась пастообразная консистенция.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Отставить минут на десять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Подготовить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Сделать пельмени в виде полумесяца: в середину вырезанного круга положить ложечку начинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Смочить краешки теста водой, слепить пельмени, хорошенько прижимая тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Нагреть воду, положить в нее пельмени, отварить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Когда они начнут всплывать, вынуть шумовкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9678,'Пельмени с мясом креветок и кукурузой подавать с любой заправкой, например, с соевым соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9679,'Взбить творог, желтки, сахар, сметану, крахмал и ванилин в отдельной миске.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9679,'Взбить отдельно белки до стойких пиков, вмешать в творожную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9679,'Добавить цукаты, изюм, другие сухофрукты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9679,'Выпекать минут сорок, соблюдать температуру 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9679,'Проверять готовность творожной запеканки с сухофруктами без муки и манки зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Отделить белки от желтков, к белкам добавить щепотку соли и взбить их в стойкую крепкую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'С сахарной пудрой смешать размягченное сливочное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'В белковую массу очень осторожно подмешать молотый кофе, смешанную с разрыхлителем муку, масляную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Аккуратно перемешивать тесто до тех пор, пока оно не станет однородным, по возможности сохранив воздух.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Очистить от кожуры апельсин, порезать полукруглыми ломтиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Смазать форму растительным маслом, полить медом и выложить дно одним слоем апельсиновых ломтиков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Поверх цитруса аккуратно выложить получившееся тесто, в разогретую духовку поставить форму.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Кофейно-медовый пирог с апельсинами выпекать при 180 градусах 30-40 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9680,'Готовому пирогу дать немного остыть, после чего перевернуть форму на блюдо.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Отварить и слить рожки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Положить в емкость, сбрызнуть ложечкой оливкового масла, чтобы они не слипались.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Разогреть сковороду на небольшом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Вылить еще ложку оливкового масла, положить фарш, посыпать солью, перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Обжарить фарш до готовности, помешивая (он должен измениться в цвете).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Положить помидорки, налить красное вино, вустерский соус, добавить специи: чесночный порошок, базиник, петрушку, хлопья перца, орегано. Посыпать перцем, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Сделать маленький огонь, накрыть крышкой, тушить минут двадцать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Нагреть духовку. Высыпать тертый пармезан на рожки, размешать, чтобы сыр распределился.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Высыпать рожки равномерно в формочку со съемными краешками (заранее намазать блюдо сливочным маслом).',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Положить слой рикотты, залить мясным соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Помыть руки, осторожно пальцами пропихнуть фарш глубже, так начинить все рожки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Отправить формочку с сырным пирогом на решетку, поставить в духовку минут на пятнадцать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Достать итальянский мясной пирог с ригатони из духовки, посыпать равномерно тертой моцареллой, чеддером и поставить в духовку еще минут на пятнадцать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Достать пирог, позволить настояться минут пятнадцать, осторожно пройтись ножом по диаметру, снять края.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9681,'Подавать пирог со свежей измельченной петрушкой.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Соединить в маленькой кастрюльке яичные белки и сахар. Размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Поставить кастрюльку на большую кастрюлю с кипящей водой (то есть, сделать водяную баню).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Взбивать на большой скорости минут восемь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'На четвертой минуте они становятся уже очень плотными, поэтому на взбивание может уйти минут пять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Переложить массу в кулинарный мешочек или пакет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Выложить на противень. Не очень удобно выкладывать, потому что масса достаточно плотная.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Сушить в духовке часа два, соблюдать температуру 100 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9682,'Выключить духовку, но дверцу не открывать, пока она не остынет.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Почистить картофель, отварить в соленой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Остудить, крупно потереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Налить взбитые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Посыпать перцем, солью, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Положить картофельную смесь на противень, намазанный маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Выложить сверху сосиски, порезанные мелко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Посыпать все сыром, мелко потертым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Готовить в духовке минут пятнадцать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9683,'Посыпать запеканку из картофеля с сосисками измельченным зеленым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'На булочку для сэндвича положить чуть-чуть салата, положить сверху чуть-чуть перца, зелень, помидорки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'Порезать зеленый лук, сельдерей, соленые огурчики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'Положить в большую емкость консервированную рыбку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'Добавить сельдерей, лук, соленые огурчики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'Заправить майонезом, посыпать перцем, солью. Размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'Положить на булочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9684,'На сэндвич с тунцом, помидорами и листьями салата положить любимый топпинг (помидоры, острый или сладкий перец, латук и так далее).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Поставить на газовую плиту сковороду, включить большой огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Налить в сковороду столько растительного масла, чтобы дно было закрыто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Порезать цыпленка вдоль грудной кости, развернуть, накрыть полиэтиленом, отбить, чтобы тушка стала по максимуму плоской.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Это важный момент, чтобы мясо прожарилось равномерно, всей поверхностью прикасалось к сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Со всех сторон чуть-чуть посыпать цыпленка солью, намазать аджикой, потом сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Стараться распределить смесь равномерно, потому что самые концентрированные зоны подгорят.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Положить цыпленка на сковороду вниз разрезом, придавить кастрюлькой с водой (предварительно обернуть дно кастрюльки фольгой снаружи).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Сделать умеренный огонь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Минут через пятнадцать перевернуть мясо, вновь придавить прессом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Продолжать готовить минут двадцать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'У цыпленка должна образоваться хрустящая корочка.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9685,'Проверять готовность мяса при помощи ножа – если сочится прозрачный сок, то блюдо готово. Если сок розовый, то продолжать готовить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Освободить куриную грудку от прожилок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Порезать филе на средние кусочки, удобней всего на полосочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Мясо замариновать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Взять красный лук – он придаст блюду приятный внешний вид и великолепный вкус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Отдельно положить мясо, насыпать лук, посыпать перцем, солью, добавить сок лайма. Размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Оставить мясо мариноваться минут на двадцать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Во время приготовления мяса заняться перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Помыть перец, почистить от плодоножек и семян.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Порезать овощи на полосочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Резать необходимо на тоненькие полоски. Чем тоньше они будут, тем лучше.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Налить в сковороду растительное масло, положить маринованное мясо, жарить до готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Затем положить перец, тушить минут десять.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Сделать соус: выложить в емкость сметану, насыпать молотый красный перец. Размешать до однородности.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Помыть салат, посушить, крупно порвать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Подогреть тортилью со всех сторон на сковороде.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Положить в горячую тортилью салатный лист, чтобы он располагался точно в центре.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Потереть полутвердый сыр.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'На салатный лист положить обжаренное мясо и перец. Положить необходимо непосредственно на салат.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Посыпать мясо тертым сыром.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Положить сверху несколько ложек сметанного соуса.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Свернуть тортилью пополам.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9686,'Можно подавать такос с курицей и болгарским перцем – традиционное мексиканское блюдо.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Репчатый лук очистить, измельчить и переложить в сотейник, добавить лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Влить в сотейник молоко, дать содержимому закипеть, после чего накрыть сотейник крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Убрать посудину на 20 минут в сторону настаиваться, затем процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Масло сливочное растопить, добавить к нему муку, обжарить до легкой золотистости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Залить молоком, варить, пока не загустеет, помешивая массу венчиком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Соус посолить, поперчить, добавить тертый сыр , мускатный орех.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Варить сырный соус не больше 5 минут на маленьком огне до однородности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9687,'Готовый молочно-сырный соус с мускатным орехом  подать в горячем виде к пасте, картофелю или овощам на пару.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'На стол или в емкость насыпать муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'В середине горки сделать углубление, вбить яйца, влить теплую воду, соединенную с солью и молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'Вымесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'Положить маленькую ложечку масла, снова хорошенько вымесить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'Накрыть тесто, оставить минут на сорок для созревания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9688,'Спустя сорок минут тесто на вареники и пельмени готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9689,'Измельчить сливочное масло, насыпать муку, смешать в крошку, разделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9689,'Первую часть положить в формочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9689,'Положить начинку сверху: яйца, взбитые с сахаром, насыпать соду, ванилин, положить творог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9689,'Накрыть второй частью теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9689,'Готовить творожную запеканку со вкусом мороженого минут сорок, соблюдать температуру 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Взбить яйца и сахар, насыпать манную крупу, налить кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Отставить заготовку на шестьдесят минут для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Положить масло, муку, разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Все перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Вылить в формочку, отправить в духовку, соблюдать 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9690,'Выпекать манник минут сорок, готовность классического манника на кефире к чаю проверять деревянной палочкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Измельчать в емкости овсяные хлопья с помощью блендера секунд десять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Положить грецкие орехи, измельчить еще несколько секунд, чтобы в печенье ощущались орешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Чтобы их не чувствовать, измельчать секунды четыре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Должна получиться однородная овсяно-ореховая масса для печенья.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Завести тесто на печенье в большой емкости блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Установить крюк для теста, всыпать овсяно-ореховую смесь, вбить яйца, насыпать сахар, положить мед, цедру ½ лимона, погасить соду соком лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Растопить масло в микроволновке, вылить в емкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Накрыть крышкой, включить блендер.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Секунд через пятнадцать тесто готово.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Оно получается нежное и однородное. Если тесто течет, добавить чуть-чуть молотых хлопьев.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'С помощью ложки выложить печенье на лист.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Использовать ложки для мороженого, чтобы печенье было одинаковым.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9691,'Отправить овсяное печенье с орешками без муки в духовку минут на пятнадцать, соблюдать температуру 180 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Тоненько порезать филе семги, скрутить розочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Положить их на блюдо, побрызгать оливковым маслом, посыпать солью, перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Отправить минут на двенадцать в духовку, соблюдать температуру 175 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Измельчить фисташки, мяту, петрушку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Перемешать все в емкости, выдавить чесночок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Натереть цедру, выжать сок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Добавить оливковое масло, посыпать перцем, солью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Перемешать до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9692,'Подавать розочки из семги под фисташковым соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Взбить при помощи венчика яйца и сахар до растворения сахара.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Растопить масло, позволить чуть-чуть остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Помешивая, медленно добавить к яйцам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Просеять муку, соль, разрыхлитель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Насыпать в яичную смесь муку, замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Разделить тесто на маленькие, одинаковые куски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Скатать шарики по размеру, как черешня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Разогреть формочку, готовить печенье порциями с двух сторон на среднем огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Срезать с печений лишнее, растолочь в крошку, добавить к вареному сгущенному молоку (желательно добавить молотые грецкие или любые другие орешки).',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Начинить данным кремом половинки орешков, соединить их в пары.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9693,'Из приготовленного теста получается приблизительно 26 орешков.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'В плотную пену взбить белки вместе с небольшим количеством лимонного сока (буквально несколько капель), после чего не торопясь ввести сахарную пудру, не переставая интенсивно взбивать. Взбивать, пока масса не получится блестящей и гладкой и не приобретет ярко-белый цвет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'В получившуюся массу добавить рубленые орехи, осторожно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Противень застелить листом пекарской бумагой и аккуратно распределить по листу подготовленное безе с помощью кондитерского мешка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Выпекать безе при температуре 100 градусов не менее 2 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Для приготовления крема нужно растереть яичные желтки, влить к ним молоко, всыпать сахар и хорошенько массу перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Далее нагреть желтковую массу, все время помешивая, на водяной бане до загустения. Как только масса начнет закипать снять ее с огня и дать остыть до комнатной температуры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Взбить размягченное сливочное масло, добавить остывший желтковый сироп и взбить массу до однородности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Растопить ломаный кусочками шоколад на водяной бане, смешать с масляно-желтковым кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Добавить в крем ром, снова все взбить, убрать на 30 минут в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9694,'Из безе и готового крема собрать конструкцию в форме конуса, убрать шоколадный торт-безе с грецкими орехами и ромом на 1,5-2 часа в холод.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Сложить в емкость все ингредиенты, кроме муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Взбивать миксером минуты две.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Насыпать муку, активно замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Охладить в холодильнике минут 20.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Посыпать стол мукой, раскатать тесто толщиной семь миллиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Формочкой большого размера вырезать круги, в середине сделать отверстие в два сантиметра диаметром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Положить на противень, отправить в морозилку минут на двадцать. Это необходимо сделать, чтобы с тестом было удобней работать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Почистить готовый обжаренный арахис, измельчить при помощи скалки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Приготовить орехи, желток, достать заготовки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Намазать заготовки желтком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Перевернуть на лист смазанной стороной или на тарелочку с орешками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Уложить на противень.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Выпекать минут двенадцать, соблюдать температуру 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Не допускать сильного зарумянивания.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9695,'Чтобы песочные кольца с арахисовой посыпкой были румяные, выпекать немного больше по времени.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Разогреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Взять кусочек пасты, смазать его по краям яйцом, положить около двух больших ложек начинки к одному краешку, подогнуть краешки, свернуть ролл.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Положить на противень, так же сформировать другие роллы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Готовить минут двадцать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Достать из духовки, намазать все роллы топленным сливочным маслом, присыпать корицей.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Вернуть в духовку минут на пять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9696,'Подавать яблочно-лимонные пирожки с корицей горячими со взбитыми сливками или ванильным мороженым.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Насыпать в теплое молоко сухие дрожжи, ½ маленькой ложки сахара, три маленьких ложки муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Размешать до однородности, отставить минут на сорок до появления пенки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Просеять муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Насыпать сахар, соль, размешать, сухие ингредиенты должны равномерно распределиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Положить в массу мягкий маргарин, сметану, растереть в крупную крошку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Налить дрожжевую смесь, замесить тесто – не очень мягкое, но не сильно густое.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'В процессе можно насыпать чуть-чуть муки или добавить молока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Накрыть тесто, отставить минут на пятнадцать, чтобы мука впитала влагу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Вымесить тесто до гладкой однородности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Накрыть тесто, оставить в тепле до увеличения объема.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Обмять подошедшее тесто, позволить подойти еще раз.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Сделать творожную начинку: растереть творог, сахар, яйца до однородности.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Если творог очень влажный, то насыпать чуть-чуть муки или тертых сухарей.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Раскатать тесто в прямоугольник толщиной один сантиметр.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Разложить начинку.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Свернуть тесто в неплотный рулетик.','https:https://st.vkuso.ru/data/cache/thumb/44/91c45c662160e44_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Нарезать рулетик приблизительно на двадцать кусочков.','https:https://st.vkuso.ru/data/cache/thumb/50/5e08b3da0b11a50_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Разложить завитушки на противень, застеленный специальной бумагой, накрыть, отставить минут на сорок.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Они должны увеличиться в объеме.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Смазать взбитым яйцом минут за пять до отправки в духовку.','https:https://st.vkuso.ru/data/cache/thumb/d8/7ecac2ff14e19d8_434x295.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Готовить при температуре 190 градусов до зарумянивания.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'Для заливки соединить сметану и сахар.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9697,'После приготовления обильно намазать завитушки с начинкой из творога сметанной заливкой, накрыть, отставить до остывания.','https:https://st.vkuso.ru/data/cache/thumb/db/554034cc42b75db_434x295.jpg',23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Положить в муку сливочное масло, измельчить при помощи ножа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Насыпать сахар, добавить желток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Если тесто крошится в руках, значит желток был небольшого размера. В этом случае положить большую ложку сметаны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Поставить на тридцать минут в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Раскатать тесто, вырезать круг.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Почистить яблоки, порезать на восемь частей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Положить яблоки на тесто, сложить на две части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'При помощи вилки взбить белки в пену, намазать корж сверху, посыпать смесью корицы и сахара.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9698,'Поставить печенье с яблоком на противень, готовить минут пятнадцать, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'Соль и сахар растворить в воде, на рабочую поверхность просеять горкой муку и сделать ямку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'В эту ямку влить воду с сахаром и солью, растительное масло и водку, после чего замесить тесто, накрыть полотенчиком и убрать на некоторое время в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'Далее снова помесить тесто и опять убрать в сторону, подобным образом помесить тесто еще 2 раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'Раскатать полностью готовое тесто в пласт толщиной 2,5-3 мм, с помощью блюдца, диаметр которого 15 см, вырезать желаемое количество заготовок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'Для начинки смешать свининой и говяжий фарш, влить молоко (можно заменить мясным бульоном), поперчить, посолить, добавить измельченную головку  репчатого лука, укроп и петрушку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'В центр каждого тестяного круга поместить 1 столовую ложку подготовленной начинки, края соединить и тщательно защипать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9699,'Чебуреки с говяжьим и свиным фаршем обжарить до зарумянивания со всех сторон на среднем огне, либо на сковороде с большим количеством растительного масла, либо во фритюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Положить фарш в посуду, вбить яйцо, насыпать панировочные сухарики, положить сметану, измельченную петрушку, мелко порезанный лук, посыпать перцем, солью, любыми специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'В формочку для запекания постелить пергамент.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Сделать из фарша шарик, положить в формочку, в центре сделать ямку небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Порезать слоеное тесто на полосочки шириной по 1 сантиметру, положить на фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Намазать тесто яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Сделать из теста ручку для корзинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Готовить в духовке, соблюдать температуру двести градусов, приблизительно минут сорок, тесто должно стать золотистым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Чтобы ручка корзинки не подпалилась, достать ее из духовки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Обжарить грибы на масле.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'В соленой воде отварить рис.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'После приготовления воткнуть ручку в корзинку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Насыпать рис, положить сверху грибы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9700,'Слоёную корзинку с мясом, рисом и грибами отправить в духовку еще минут на пять.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Отварить рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Замочить булочку в молоке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Чуть-чуть отжать булочку, соединить с фаршем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Положить рис, посыпать перцем, солью, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Сделать соус: соединить сметану и кетчуп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Если соус очень густой, то подлить чуть-чуть кипяченой воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Слепить из фарша тефтели небольшого размера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Положить в формочку для запекания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Сверху налить соус.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Отправить в духовку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9701,'Готовить тефтели под томатно-сметанным соусом в духовке примерно минут сорок, соблюдать температуру около 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Соединить в емкости сахар и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Чтобы оладьи были более сладкими, положить пять больших ложек сахара. Для закусочного варианта достаточно будет одной ложки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'При помощи миксера взбить сахар и яйца, можно просто тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Налить в емкость кефир. Можно использовать кислое молоко, но важно, чтобы оно было не горьким. Подойдет также молочная сыворотка, но, безусловно, на кефире получается вкусней.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Насыпать в тесто соду, сразу хорошо размешать, чтобы не было комочков. Образуются пузырьки, чем их будет больше, тем ажурней и пышней будут оладьи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Желательно готовить оладьи сразу, так как пузырьки могут пропасть, и оладушки получатся плоские. Лучше замешивать тесто и сразу жарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Насыпать чуть-чуть соли в тесто, просеять в посуду муку – взять стакан муки, размешать, насыпать остальную муку, чтобы тесто получилось густым, консистенция должна быть похожа на домашнюю жирную сметану.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'В сковороду налить подсолнечное масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'При помощи ложки выложить порции теста на горячую сковороду, придавать оладушкам форму круга. Чтобы оладьи не слипались, оставлять между ними промежуток.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Если тесто очень растекается, то насыпать чуть-чуть муки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Жарить оладушки на среднем огне, следить, чтобы не пригорели. Готовятся они очень быстро.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Когда на оладьях появляются ажурные дырочки, то их можно переворачивать.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Осторожно перевернуть при помощи вилочки или лопатки оладьи на другую сторону, обжарить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9702,'Снять пышные оладьи на кефире на тарелочку, чуть-чуть полить маслом, начинать жарить следующую порцию.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Порезать рыбку на небольшие кусочки, посыпать специями, солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Мариновать в смеси соевого соуса и сока лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Почистить креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Порезать сыр на маленькие кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Собрать на шпажки рыбу, куски сыра, креветки.','https:https://st.vkuso.ru/data/cache/thumb/12/798ecdf02951512_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Порезать тесто на полосочки по несколько сантиметров в ширину.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Намазать яйцом, посыпать кунжутом.','https:https://st.vkuso.ru/data/cache/thumb/98/be1e90f855c6c98_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9703,'Готовить шашлычки из рыбы и креветок в тесте минут тридцать, соблюдать температуру 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Разогреть духовку. Соединить сухие продукты, мука должна быть просеянной, вбить яйца, налить молоко, добавить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Взбить, налить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Снова взбить, чтобы получилось жидкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Разлить по формочкам, готовить каждый по двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Соединить в кастрюльке размороженную вишню без сока, сахар (100 г), ром, довести до кипения, оставить на маленьком огне минут на десять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Охладить, жидкость слить, оставить чуть-чуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Взбить маскарпоне и сливки до воздушной консистенции.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Насыпать сахарную пудру, не переставать взбивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Должен получиться воздушный и густой крем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'В емкость положить шоколад, поломанный на плитки, положить сливки, нагреть на водяной бане, мешать, пока глазурь не станет гладкой и однородной.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Охладить и собрать тортик. Корж смазать кремом, сверху выложить вишню, полить сиропом. Накрыть вторым коржом и всё повторить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Третий корж смазать кремом и полить глазурью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9704,'Украсить торт ягодами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'Помыть и порезать капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'Разморозить крабовые палочки, почистить от обертки, порезать на средние кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'На средние кубики порезать сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'Кукурузу из банки смешать с капустой, сыром и крабовыми палочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'Положить майонез, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9705,'Подавать салат из пекинской капусты с сыром и крабовыми палочками можно на капустных листьях, украсить тертым сыром и крабовыми палочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Осторожно помыть филе лосося, при помощи острого ножа срезать с кожицы куски рыбы по одному сантиметру толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Положить филе в глубокую емкость слоями, все слои посыпать солью, перцем, сбрызнуть соком лимона, оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Накрыть емкость полиэтиленом, отправить в холодильник на пару часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Измельчить свежую зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Мелко потереть сыр, соединить с зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Намазать лаваш оливковым маслом (по желанию посыпать сухими приправами), накрыть вторым листом лаваша.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Равномерно на лаваш положить куски лосося, посыпать смесью зелени и сыра, свернуть плотный рулетик.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Порезать рулетик на кусочки толщиной по три сантиметра, каждый кусочек скрепить шпажками, чтобы не развернулись.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Положить рулетики на противень, смазанный маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Соединить большую ложку сока лимона, мед и горчицу, добавить ложечку оливкового масла, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9706,'Намазать рулеты подготовленной смесью, отправить в горячую духовку, готовить минут двадцать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'Соединить сгущенное молоко и масло (200 г).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'При помощи миксера взбить в однородную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'Намазать коржики кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'Покрыть коржики глазурью: смесь шоколада, сливок и масла (50 г).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'Отправить часа на три в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9707,'Украсить многослойный вафельный торт со сгущенкой и шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Приготовить тесто: развести теплой водой дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Насыпать в емкость муку, добавить соль, масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Вылить разведенные дрожжи, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Усердно мять, пока тесто не перестанет прилипать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Переложить в емкость, накрыть, отставить минут на шестьдесят, чтобы настоялось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Тесто увеличится раза в три.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Снова помять, разделить пополам, раскатать, чтобы получился ровненький круг или другая геометрическая фигура.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Пока тесто подходит, сделать соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Взять овощной набор, состоящий из помидоров и красного лука.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Тушить, жарить, добавить чесночок и приправы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Измельчить овощную массу при помощи блендера.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Сверху разложить какую-нибудь колбасу, грибочки, сыр, помидоры, оливки – все что угодно.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9708,'Жарить тонкую пиццу с любимой начинкой минут двадцать и можно подавать блюдо.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Разложить лаваш, намазать сметаной или майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Положить в ряд крабовые палочки, затем яйца, затем перчик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Четвертый ряд – морковь, далее – сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'После этого повторить в любом порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Последним положить крабовые палочки.','https:https://st.vkuso.ru/data/cache/thumb/94/1359687a6e79594_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Осторожно скатать рулет, завернуть в полиэтилен, отправить в холодильник минут на двадцать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9709,'Можно подавать рулет из лаваша с цветной начинкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Приготовить блинчики по рецепту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Приготовить заварной крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Смешать сахар с яйцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Добавить муку и ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Залить холодным молоком и перемешать при помощи миксера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Поставить на средний огонь, постоянно помешивая, и так довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Добавить сливочное масло. И поварить до загустения 5-10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Положить готовый блинчик на доску, обрезать с двух сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'На краешек блина выложить несколько ложечек крема, чуть-чуть распределить по поверхности блинчика, но в основном крем должен остаться с краю.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Осторожно свернуть блин трубочкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Так, свернуть остальные блинчики, осторожно сложить на тарелочке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9710,'Посыпать классические блинчики с заварным кремом стружкой кокоса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'Взбить яйца вместе с сахаром с помощью миксера, добавить негашеную соду, совсем немного соли, творог и тщательно перемешать яичную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'Далее ввести в яично-творожную массу муку и продолжить мешать, пока не получится густое тесто, которое будет липнуть к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'Руки и рабочую поверхность присыпать мукой, достать тесто и раскатать его, после чего разделить готовое тесто на 3 куска.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'Раскатать каждый кусок  в пласт  0,5-0,7 см толщиной, большим стаканом вырезать круги, в центре которых сделать маленькие кружки, например, крышечкой от бутылки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'Растительное масло  разогреть на среднем огне, обжарить в нем творожные пончики до образования золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9711,'На бумажную салфетку переложить готовые пончики, а когда бумага впитает лишнее масло, изделия при желании можно посыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Разогреть масло, положить лук, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Добавить несколько больших ложек паприки, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Положить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Потом морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Спустя некоторое время положить остальные овощи: фасоль, перцы, помидоры без шкурки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Перемешать, чуть-чуть посыпать солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Налить бульон, чтобы слегка покрывал мясо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Должно получиться густо, как гуляш.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Добавить острый перец, накрыть крышкой. Убавить огонь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Приблизительно через пятьдесят минут открыть казан, положить крупные дольки картофеля, налить остальной бульон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Насыпать в суп соль, вновь закрыть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Когда сварится картофель, положить петрушку и чесночок.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9712,'Можно подавать бограч – густой венгерский суп.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9713,'Вымыть клюкву, измельчить при помощи блендера или растереть, выжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9713,'Отправить в кастрюльку, положить остальные ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9713,'Варить на среднем огне минут пять, помешивать, чтобы растворился сахар, а пряности отдали вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9713,'Если использовались звездочки гвоздики, то желательно их достать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9713,'Перед подачей чуть-чуть остудить апельсиново-клюквенный морс с корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Сделать густое тесто, позволить ему отдохнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Приготовить начинку. Крупно потереть морковь, измельчить лук, чуть-чуть обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Насыпать в мясной фарш соль, специи, по желанию потереть картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Тоненько раскатать тесто, положить мясной фарш, на него положить овощной фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Свернуть все в плотный рулетик, уложить или в пароварку, намазанную маслом, или в духовку на фольгу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Положить в воду лавровый листик, чуть-чуть соли, душистый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Готовить минут сорок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Положить в блюдо, полить маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9714,'Ханум с фаршем и морковью подавать со сметанным или томатным соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9715,'Крупное и спелое яблоко натереть, превратить в пюре с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9715,'Добавить сырое куриное яйцо, натуральный мёд, творог.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9715,'Массу перемешать и разложить в формочки, печь в СВЧ в течение семи минут, мощность – максимальная.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9716,'Сырые куриные белки взбить с небольшим количеством соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9716,'Отдельно смешать творог, сырые желтки, манную крупу, сахар, ванилин из пакетика, разрыхлитель для выпечки или пищевую соду, погашенную уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9716,'Добавить изюм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9716,'Огнеупорную форму смазать жиром, печь в течение 45 минут до образования золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9716,'Подать блюдо в теплом виде, к запеканке – любимое варенье или джем, сметана.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Отдельно взбить белки вместе с сахаром до твердых пиков, затем ввести по 1 желтку и  все тщательно взбить еще раз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Порциями подмешать муку, аккуратно перемешивая после каждой порции, добавить тертую лимонную цедру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Смазать разъемную форму маслом и вылить в нее получившееся тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Выпекать бисквит 30 минут при 180 градусах, затем дать ему остыть и порезать вдоль на 2 равные части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'В емкости с водой замочить желатин, затем на огне прогреть его до полного растворения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'С помощью блендера взбить в однородную массу  творог, сливки и сахарную пудру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'В творожную массу добавить подготовленный желатин и консервированные ананасы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Как только творожно-ананасовая масса начнет застывать ее необходимо осторожно переложить на корж и накрыть сверху вторым коржом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9717,'Убрать торт с творожным кремом и консервированными ананасами на 6 часов в холодильник.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Кальмаров очистить от пленок, промыть, отварить в кипящей подсоленной воде в течение трех минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Тушки вынуть шумовкой, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Нарезать соломкой свежие огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Отварить куриные яйца, разрезать каждое на шесть частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Хорошо вымыть и порвать руками листья зеленого салата, переложить на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Поверх – кальмары, нарезанные соломкой, рубленый зеленый лук, яйца, огурец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9718,'Для заправки перемешать натуральный йогурт с лимонным соком, солью и молотым перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Сварить мясной бульон, дать ему покипеть, чтобы испарилась половина объема, а вкус стал насыщенным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Кастрюлю поставить на огонь, довести до кипения, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Положить овощи: стебли сельдерея, лук-порей, морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Огонь убавить, варить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Содержимое откинуть на дуршлаг, промыть холодной водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Лапшу положить в оставшийся бульон, довести до кипения, затем огонь убавить, прогревать до готовности, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'Через четыре минуты воду слить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9719,'И лапшу, и отваренные овощи разложить в тарелки, залить бульоном, при необходимости суп можно досолить и поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'Прежде чем приступить к приготовлению, тесто следует разморозить, после чего раскатать его в тонкий пласт в форме квадрата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'Мелкими кубиками порезать маринованные огурцы, сыр и колбасу – тонкой соломкой (но можно натереть на средней терке).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'По краям тестяной пласт промазать слегка взбитым яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'Смешать кетчуп и майонез, получившейся массой тщательно смазать всю поверхность тестяной заготовки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'На подготовленный пласт выложить слой колбасы, затем слой огурцов и в завершение посыпать все сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'Скатать тесто в рулет, разрезать его на кусочки по 2-3 см, после чего каждый переложить на лист пергамента разрезом вверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9720,'Выпекать мини-пиццы из слоеного теста с  колбасой и солеными  огурчиками при 180 градусах 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9721,'Перемешать нежирный творог, овсяные хлопья, хорошо размятый банан, изюм или курагу, другие сухофрукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9721,'Добавить разрыхлитель и сырое яйцо в качестве связующего «звена».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9721,'Сформовать лепешки, выпекать на противне, на листе пергамента в течение 20 – 25 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Репчатый лук и чеснок порубить и потушить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Добавить хорошо вымытый шпинат, прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Готовую зелень нарубить и выложить в жаропрочное блюдо для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Куриное филе нарезать, обжарить на сковороде со всех сторон, затем допечь в духовке до готовности в течение 10 – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Готовое мясо выложить на «подушку» из шпината.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Приготовить заливку: перемешать горчицу и молоко, добавить по вкусу приправы, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Вылить смесь на курицу, посыпать тертым твердым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9722,'Поставить блюдо в духовку до расплавления сыра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'Отварить куриное филе, остудить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'В салатнице перемешать курицу, свежие нарезанные шампиньоны, рубленый стебель сельдерея, измельченное зеленое яблоко без кожицы и семян.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'Добавить сыр «Фета», зелень петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'Приготовить заправку с помощью блендера: яблочный уксус, горчицу, рубленый тимьян, соль и перец. Масса должна быть однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'Полить салат соусом и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9723,'Хорошо вымытый шпинат выложить на тарелку, сверху – салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Форму средней величины застелить фольгой и смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Бананы очистить, нарезать кольцами, выложить в емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Сверху всыпать половину нормы свежей или замороженной черники, молотую корицу, полить массу мёдом, накрыть фольгой и печь в течение 15 минут при температуре 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Отдельно перемешать овсяные хлопья, половину нормы грецких орехов, оставшуюся корицу и разрыхлитель для выпечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'В другой миске взбить оставшийся мёд с молоком, ванилином и сырым куриным яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Достать блюдо из духовки, посыпать сухой овсяной смесью с орехами и залить молочным соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Выложить остатки ягод и грецких орехов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9724,'Печь пирог в течение получаса до образования румяной корочки, подать к столу в теплом виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9725,'Стручковую фасоль и шпинат приправить перцем и солью, выложить в пароварку на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9725,'Отдельно взбить сырые куриные яйца с молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9725,'Залить продукты и потушить еще в течение десяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Рис промыть под проточной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Клубни картофеля очистить, вымыть и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Очистить от кожицы соленые огурцы, мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Свежую морковь и репчатый лук также очистить, лук нарезать кубиками, морковь – соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Обжарить на растительном масле то и другое до золотистого цвета, добавить огурцы, жарить еще пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Вскипятить воду, положить рис и картофель, варить 10 – 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Добавить жареные овощи, варить на тихом огне до полной готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9726,'Почти готовый суп снять с огня, добавить лавровый лист, измельченный чеснок и сушеную зелень, дать постоять в течение десяти минут и подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'До однородности перемешать яйца со сметаной, сгущенным молоком и ввести муку с содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Получившееся тесто разделить пополам и в одну из частей добавить какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Две формы смазать маслом, в одну перелить светлое тесто, во вторую – темное.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Выпекать коржи в течении 20 минут при 210 градусах, после чего дать им остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Достать остывшие коржи из форм, каждый разрезать пополам вдоль: получится два темных и два светлых коржа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Для крема необходимо взбивать сливочное масло комнатной температуры, частями подмешивая в него сгущенное молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Взбивать крем до тех пор, пока он не приобретет устойчивую пышную консистенцию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Коржи промазать получившимся кремом и соединить их друг с другом, чередуя по цвету.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9727,'Обмазать оставшимся кремом бока и поверхность изделия, посыпать торт «Машенька» из сметаны и сгущенного молока рублеными орехами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9728,'Куриную грудку очистить от кожицы, отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9728,'В бульон добавить нарезанный картофель, поварить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9728,'Затем – капусту брокколи, разобранную на соцветия, измельченный репчатый лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9728,'Варить все вместе 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9729,'Кефир и яйцо взбить с помощью блендера, добавить пшеничную муку, снова взбить, всыпать щепотку соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9729,'Пищевую соду погасить кипятком и влить в тесто, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9729,'Жарить тонкие блины на сковороде с антипригарным покрытием.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9729,'Подать с мёдом или сгущенным молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9730,'Смешать нежирный творог, сырое куриное яйцо, натуральный мёд, нарезанную грушу, кокосовую стружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9730,'Форму смазать небольшим количеством масла, выложить массу и печь в течение 25 минут при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Говядину промыть, нарезать кусками, залить холодной водой, довести до кипения, огонь убавить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Во время приготовления снимать пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Добавить лавровый лист, перец-горошек, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Варить до полной готовности мяса, на это потратится от полутора до двух часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Можно подливать кипяток при необходимости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Обжарить на сухой сковороде гречневую крупу, помешивать. При появлении интенсивного запаха термообработку прекратить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Очистить клубень картофеля, небольшой корень сельдерея, морковь, репчатый лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Нарезать овощи кубиками и обжарить до мягкости на растительном масле, кроме картофеля.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Готовое мясо из бульона вынуть, нарезать кубиками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Жидкость отцедить, вновь довести до кипения, всыпать обжаренную гречневую крупу, обжарку, картофель, варить до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Соль, перец, душистый перец-горошек, лавровый лист – по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9731,'Перед подачей всыпать рубленый чеснок, дать супу постоять под крышкой 15 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9732,'Овсяную крупу перемешать с кефиром, должна получиться густая каша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9732,'Оставить на полчаса для набухания, добавить молотую корицу, мёд и тертые яблоки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9732,'Противень застелить пекарской бумагой, выложить массу в виде лепешек мокрыми руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9732,'Температура приготовления – 200 градусов, печь 20 – 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'Отварить гречневую крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'Для приготовления соуса смешать в небольшой емкости соевый соус, молоко, сметану, прогреть три минуты, снять, добавить рубленую петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'На сковороде обжарить куриное филе до готовности, добавить нарезанный колечками репчатый лук, жарить до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'Подлить молочный соус и немного воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'Потушить блюдо в течение 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9733,'Подать курицу с гарниром, приготовленным из гречки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'В большой миске смешать муку, соду, разрыхлитель, какао и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'В отдельной посудине венчиком взбить яйца, влить к ним молоко и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'Смешать вместе мучную и яичную смеси, тщательно перемешать, замесить плотное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'Влить в тесто кипяток, хорошенько его перемешать и при температуре 160 градусов выпекать один час 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'Дать готовому коржу остыть, после чего разрезать его на 3 части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'Жирную сметану смешать с сахаром и взбивать, пока не получится крем однородной консистенции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'Подготовленные коржи смазать получившимся кремом и собрать шоколадный торт на кипятке и молоке',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Готовую выпечку посыпать сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9734,'При желании изделие можно слегка полить шоколадным сиропом и украсить мелко тертым шоколадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Крупно натереть очищенную морковь, полукольцами нарезать очищенный лук, все вместе слегка обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Залить кипятком помидор, после чего снять  кожицу и нарезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Порезать очищенный от семян болгарский перец тонкой соломкой, мелко натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Каждый кусок куриного филе отбить молоточком (для мяса), смазать солью и перцем и с обеих сторон запанировать в муке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Затем со всех сторон обжарить отбивные на сковороде с разогретым растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Обжаренное мясо переложить на противень, сверху выложить подготовленную морковно-луковую смесь, затем болгарский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Поверх перца распределить кружки помидора, смазать их майонезом, на который выложить половинки оливок и посыпать все тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Вылить на противень около 50 мл бульона или воды и убрать его в разогретую до 200 градусов духовку на 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9735,'Горячая куриная грудка с овощами, запеченная под сыром и оливками посыпается свежей зеленью и подается с макаронами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9736,'Просеять в небольшую миску муку, разрыхлитель и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9736,'В отдельной посудине смешать молоко, яблочное пюре, яичный белок, грецкие орехи и размятый банан.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9736,'В мучную смесь влить молочную и мешать все, пока масса не станет однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9736,'Формочки для кексов наполнить получившимся тестом и выпекать бананово-яблочные кексы с грецкими орехами 15 минут при 200 градусах: они должны стать золотисто-коричневыми.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'Присыпать рабочую поверхность мукой и раскатать на ней пласт теста так, чтобы дно и половину бортов формы можно было покрыть этим пластом (размер формы 20х30 см).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'Саму же форму смазать маслом и руками распределить по ней подготовленный тестяной пласт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'Взбить в миске яйцо, сливочный сыр, обычный и ванильный сахар, получившуюся сырную массу равномерным слоем распределить по тесту, которое уже лежит в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'На сырную начинку выложить готовую консервированную вишневую начинку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'Из оставшегося теста нарезать неширокие полоски  (не более 1 см), выложить их в виде решеточки на вишневый джем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9737,'Выпекать чизкейк из слоеного теста с вишневым джемом при 180 градусах 30-35 минут до аппетитного золотистого цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Теплым молоком залить батон, мелкими кусочками порезать куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Через мясорубку пропустить мясо, батон и очищенные зубчики чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Добавить в получившийся фарш молотый перец  и соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Сформовать из куриного фарша небольшие котлетки, в центр каждой положить небольшой кусочек сыра и закрыть, чтобы он при обжаривании не вытек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Подготовленные котлетки запанировать в сухарях и переложить на сковороду с растопленным сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Обжарить котлеты из куриной грудки с сырной начинкой по 3 минуты с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9738,'Затем переложить их в термостойкое блюдо и запекать в духовке 15 минут при 180 градусах.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Взять баклажан среднего размера, почистить, порезать на кружочки толщиной приблизительно полтора сантиметра. Положить порезанный баклажан минут на пятнадцать в соленую воду, тогда масло во время жарки меньше впитается, и не будет горчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Порезать лук на колечки. Можно использовать любой репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Обжарить баклажаны до золотистого оттенка на масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Луковые колечки обжарить до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Положить обжаренные овощи в емкость, добавить порезанные помидоры, уксус, посыпать перцем, солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Не добавлять в салат из жареных баклажанов и лука с помидорами масло, потому что его достаточное количество в обжаренных овощах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9739,'Все перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Растереть печенье в крошку руками или при помощи комбайна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Рыбу очистить, отделить головы и хвосты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Нагреть масло, шоколад, молоко на маленьком огне, положить к печенью, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Положить смесь в разъемную формочку, утрамбовать при помощи дна стакана, отправить в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Залить желатин водой, оставить минут на пять для набухания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Выжать сок из апельсина, нагреть, довести до кипения, перелить к желатину, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Разделить яйца, взбить белки до пиков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Взбить при помощи блендера сметану, творог, желтки, сахар, апельсиновую цедру до однородности, налить теплый желатин, взбивать еще секунд десять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Используя лопатку или ложку, положить белки в творожную смесь, осторожно размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Налить в разъемную формочку, встряхнуть, чтобы распределить массу равномерно.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Отправить чизкейк из печенья с белым шоколадом и ягодами часа на четыре в холодильник.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9740,'Украсить ягодами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Крупно порезать овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Порезать цукини на тоненькие кружки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'В формочку положить красный лучок, перец, картофель, побрызгать оливковым маслом, посыпать перцем, солью, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Готовить минут тридцать, картофель должен приготовиться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Минут за пять до конца приготовления положить помидоры черри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Положить к овощам соус песто и моцареллу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Накрыть запеченные овощи с сыром моцарелла и песто фольгой, чтобы расплавился сыр, добавить цедру лимона.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9741,'Можно подавать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Для приготовления крема растереть яйца с сахаром и мукой  в небольшой кастрюльке, добавить к ним ванилин и молоко, хорошенько перемешать венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Поставить кастрюльку на медленный огонь, варить крем при постоянном помешивании до загустения, после чего полностью его остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Миксером взбить сливочное масло, добавляя порциями остывший заварной крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'В миску вбить яйца, добавить творог, обычный и ванильный сахар,гашеную соду, частями подмешать муку и замесить плотное, не очень крутое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Разделить получившееся тесто на 6-8 кусков и каждый раскатать в тонкий круг, после чего наколоть тестяные круги вилкой, чтобы они не вздувались.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Печь коржи на сковороде до зарумянивания с обеих сторон, затем обрезать неровные края и дать коржам остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Остывшие коржи промазать подготовленным заварным кремом и собрать торт.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9742,'Украсить творожный торт с заварным кремом орехами и шоколадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Порезать лук, порезать до чуть-чуть золотистого оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Положить фарш, обжаривать, пока не испарится жидкость, непрерывно помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Положить измельченную морковь, насыпать сахар, соль, специи, размешать. Чуть-чуть потушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Положить помидоры, порезанные кубиками, томатную пасту, размешать. Тушить минуты две.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Положить мелко порезанный картофель, налить воду, чтобы покрывала мясо и овощи более, чем на 0,5 сантиметров, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Спустя минут десять положить прессованный чеснок, перец, порезанный соломкой. Тушить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Посыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'В соленой воде отварить спагетти.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9743,'Переложить спагетти на тарелку, залить ленивый лагман со спагетти  мясным соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Подготовить ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Отделить желтки от белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Взбить желтки, соль, перец, пекарский порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Соединить с сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Взбить белки в пену.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Разогреть масло на средней сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Осторожно ввести к желткам белки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Аккуратно и уверенно размешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Готовить на горячей сковороде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Французы омлет не переворачивают, а во время готовки скручивают в «сигару», середину оставляют слегка сыроватой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9744,'Свернуть воздушный омлет с сыром и укропом уверенными движениями.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Время тушения под крышкой – полчаса.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9746,'Украсить тертым сыром, консервированной кукурузой или горошком, зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Разогреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Взбить мягкое масло и сахар до однородности, минут семь, чтобы получилась воздушная, светлая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Добавить по одному яйцу, собирать время от времени со стенок, равномерно размешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'В отдельной емкости соединить разрыхлитель, муку, стружку кокоса, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'В кокосовое молоко насыпать ванильный экстракт, размешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Сделать скорость миксера минимальной. Медленно добавить мучную смесь, потом кокосовое молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Намазать формочку для выпекания сливочным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Вылить в нее тесто, обильно посыпать его ягодами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Можно положить сначала ягоды, а сверху тесто.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Готовить в горячей духовке минут пятьдесят.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Проверять готовность летнего кокосово-малинового пирога зубочисткой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9747,'Подавать пирог с сахарной пудрой, свежими ягодами малины, сметаной.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Разогреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'На всех кусочках мяса сделать сбоку надрезы в виде карманов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Заполнить надрезы сливочным сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Положить куриное филе на противень, намазанный маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Вымыть и измельчить петрушку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'В емкости блендера соединить измельченную петрушку, крошки хлеба, яйцо, мягкое сливочное масло, чуть-чуть перца, соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Полученную смесь разделить на четыре части, положить на филе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9748,'Готовить котлеты по-киевски со сливочным сыром минут 25.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Раскатать тесто, вырезать квадраты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Надрезать слегка тесто по уголкам.','https:https://st.vkuso.ru/data/cache/thumb/eb/1b409cfef2c77eb_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Положить сверху начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Закрепить уголки.','https:https://st.vkuso.ru/data/cache/thumb/2d/07af634f4aabf2d_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Положить на противень, присыпанный мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Намазать сверху яйцом, посыпать кунжутом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9749,'Готовить открытые пирожки в слоеном тесте в духовке, соблюдать температуру 210 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Желательно использовать домашний творог, положить его в емкость, насыпать сахар, перетереть его при помощи ложки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Во время перетирания чуть-чуть посыпать солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Вбить в творог яйцо, вымешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Разделить муку на две части, одну насыпать в смесь творога, вторую часть оставить для присыпки во время лепки вареников.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Насыпать на доску чуть-чуть муки, положить творожную смесь горкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Раскатать руками чуть-чуть творожное тесто в колбаску.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Порезать колбаску из теста на средние кусочки при помощи острого ножа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Налить в кастрюльку приблизительно три литра воды, поставить на огонь, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Бросить вареники в кипящую воду, довести до кипения, варить минуты три.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Выловить вареники из кастрюльки при помощи шумовки, выложить на тарелочку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9750,'Горячие вареники намазать сливочным маслом, можно по желанию положить чуть-чуть сметану.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Замесить тесто в хлебопечке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Если ее нет, то соединить все продукты для теста в обыкновенной посуде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Вымесить, накрыть полотенцем, отправить в теплое местечко, чтобы подошло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Приготовить начинку: почистить яблоки, порезать на маленькие куски, положить в кастрюльку, насыпать сахар, налить воду, варить, пока яблоки не станут мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Добавить крахмал, перемешать, позволить остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Раскатать тесто в прямоугольник, в центр положить яблочную начинку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Защипнуть краешки, чтобы был большой жгут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Осторожно свернуть кольцом, скрепить стык.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Отставить, чтобы поднялся.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Минут через тридцать намазать кольцо желтком, присыпать лепестками миндаля.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Готовить в духовке, соблюдать температуру 180 градусов. Готовность проверять зубочисткой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9751,'Если верх стал румяным, но пирог не приготовился, накрыть его фольгой, выпекать дрожжевое кольцо с яблочной начинкой до готовности.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'От кожуры очистить картофель, промыть его и нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'В одной мисочке взбить яичные белки, во второй перемешать тмин, молотый перец, соль, паприку и смесь итальянских приправ.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'Ломтики картофеля поместить в миску с взбитыми белками, всыпать смесь из приправ, тщательно перемешать содержимое миски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'Смазать противень  растительным маслом и распределить по нему подготовленный картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'Убрать противень в духовку, предварительно разогретую до 220 градусов,  запечь блюдо в течение 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9752,'Чтобы добиться лучшего результата, каждые 10 минут жареный в духовке картофель со специями нужно перемешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9753,'Прежде чем приступить к приготовлению, тесто необходимо разморозить, после чего слегка раскатать и порезать полосками примерно по 2 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9753,'Сделать из картона трубочки, обернуть их фольгой, поверх которой накрутить тестяные полоски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9753,'Прямо в таком виде отправить заготовки в духовку и в течение 5 минут выпекать трубочки до подрумянивания при 170 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9753,'Взбить вареное сгущенное молоко вместе с размягченным сливочным маслом и заполнить получившимся кремом остывшие трубочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9753,'Готовые слоеные трубочки с вареным сгущенным молоком можно при желании посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'В кастрюльке смешать яйца и муку до однородной консистенции без комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'В отдельной кастрюле вскипятить, периодически помешивая, молоко с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'В мучную массу тонкой струей влить молоко, тщательно размешивая лопаткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'Поставить получившийся крем на небольшой огонь и, все время помешивая, довести его до загустения, но не дать ему закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'Затем добавить в крем сливочное масло и ванилин, снять емкость с огня, хорошенько перемешать заварной крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'Поставить кастрюльку с кремом в холодную воду или лед, чтобы ее содержимое быстро остыло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9754,'Использовать крем можно для тортов, пирожных, эклеров или куличей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Разморозить слоеное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Положить на противень, застеленный специальной бумагой или смазанный маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Сделать надрезы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Сверху посыпать тесто сухариками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'На них положить капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'С края загнуть пласт, обернуть пирог полосочками, при этом их следует чуть-чуть вытягивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'В конце завернуть края и завернуть полосками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Намазать пирог холодной сладкой заваркой при помощи кисточки, хорошенько промазывать швы и стыки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9755,'Выпекать слоеный пирог с тушеной капустой в духовке минут двадцать пять, соблюдать температуру 200 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Сварить яйца, почистить, порезать вдоль на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Измельчить сельдерей и лук, положить в глубокую посуду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Достать из яиц желтки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Белки разложить на противень, застеленный пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Желтки положить к сельдерею и луку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Порезать ветчину на кубики маленького размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Добавить ветчину к овощам и желткам, заправить сметаной и майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Посыпать перцем и солью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Перемешать, ингредиенты должны равномерно распределиться.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Положить начинку в белки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Укроп измельчить и добавить в начинку или посыпать фаршированные яйца сверху.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Потереть сыр, посыпать начинку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Отправить противень с подготовленными яйцами в горячую духовку или бройлер.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Блюдо считается готовым, если сыр расплавится.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9756,'Можно подавать фаршированные яйца с ветчиной и сельдереем.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Порубить холодное сливочное масло и муку с солью, перетереть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Залить водой, добавить лавровый лист перец-горошек, морковь, лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Налить ледяную воду, быстро вымесить тесто. Для облегчения можно воспользоваться кухонным комбайном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Завернуть тесто в пленочку, отправить минут на тридцать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Тоненько раскатать пласт толщиной 0,3 миллиметра, положить в формочки, прижать тесто к стеночкам, обрезать лишнее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Сложить формочки с тестом друг на друга стопкой по 4-5 штук, поставить сверху пустую формочку, чуть-чуть прижать данную «конструкцию».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Готовить в горячей духовке минут пятнадцать, соблюдать температуру 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Разобрать стопку, готовить еще минут пятнадцать. Остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Измельчить мясо и зелень, потереть морковь и несладкие яблоки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Соединить горчицу и сметану.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Все смешать, положить салатик по корзинкам.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9757,'Украсить мясной салат с яблоком в корзиночках измельченными орешками или веточками зелени.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Репчатый лук и чеснок очистить и мелко нарубить, обжарить на разогретом растительном масле до полупрозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Всыпать рис басмати или другой, длиннозерный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Перемешать, жарить при постоянном помешивании в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Влить воду или куриный бульон, посолить по вкусу и довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Огонь убавить, прогревать под крышкой до полного впитывания жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'В процессе приготовления, при необходимости, можно долить еще немного бульона или воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Нарезать помидоры на небольшие кусочки, порубить зеленый базилик.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9758,'Перемешать то и другое с рисом, подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'Тыкву вымыть, очистить от кожуры, семечки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'Мякоть натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'Бананы очистить, размять вилкой в пюре и смешать с тыквой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'В полученную смесь всыпать пищевую соду, пшеничную муку грубого помола, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'Сформовать лепешки мокрыми руками, обжарить на сковороде с антипригарным покрытием, с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9759,'Подать с ягодами свежей или размороженной малины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9760,'Разморозить креветки в горячей воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9760,'Нашинковать пекинскую капусту, только её зеленую часть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9760,'Нарезать мелкими кусочками консервированные ананасы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9760,'Очистить и разобрать на зернышки спелый гранат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9760,'Все ингредиенты перемешать, посолить по вкусу и заправить йогуртом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Цукини натереть на крупной терке, сок отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Мелко нарезать лук-шалот и обжарить до золотистого цвета на сливочном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Добавить половину кабачковой массы, подержать на огне в течение двух-трех минут, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Сырые куриные яйца взбить с остатками тертых кабачков, добавить обжарку, соль и перец молотый – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Можно всыпать щепотку шафрана, «лимонный» перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Смесь вылить на разогретую сковороду с маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'Сверху выложить креветки, огонь убавить, подержать блюдо до готовности под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9761,'При подаче кушанье посыпать рубленым укропом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9762,'В большой кружке смешать сахар, муку, какао-порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9762,'В сухую смесь вбить яйцо, влить  растительное масло и молоко, добавить пасту «Nutella».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9762,'Вилкой взбить содержимое кружки до однородности, после чего поместить емкость на 2-3 минуты в микроволновку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9762,'Готовый кекс из пасты Nutella в микроволновке перед подачей можно украсить шоколадной стружкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'Нарезать тесто на столько полосок, сколько будет запекаться крабовых палочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'Рабочую поверхность присыпать пряной смесью и раскатать на ней тестяные полоски по длине так, чтобы на тесте осталась эта смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'Сыр нарезать на пластины так, чтобы они совпадали по размеру с крабовыми палочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'На одну сырную полоску положить крабовую палочку, накрыть ее второй полоской.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'Завернуть палочку в подготовленную тестяную полоску, то же самое проделать с остальными.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9763,'Выпекать рогалики с крабовыми палочками и сыром в течение 25 минут при 180 градусах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Подготовить мясо: помыть, обсушить, зачистить от пленочек, втереть в кусок перец с солью и паприкой, плотно перевязать прочной нитью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Включить для прогрева до 220 градусов духовку. Уложить филе в подходящую по размеру форму, отправить на треть часа в духовку (за это время полить пару раз соком кисло-сладких яблок).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Снизить на 50 градусов температуру в духовке, продолжить запекать (в процессе поливать соком) мясо еще около часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Готовое филе переложить на блюдо, тщательно «запаковать» фольгой, чтобы мясо сильно не остывало, дать постоять, приготовить яблочный гарнир.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Удалить у яблок сердцевину, порезать на средние по толщине дольки, сложить в форму из-под мяса. Поднять температуру духовки чуть выше 200 градусов, готовить четверть часа до размягчения плодов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9764,'Нарезать филе свиное, запеченное с яблоками на ломти (примерно по сантиметру), разложить по тарелкам, полить соком от запекания фруктов, добавить в каждую гарнир из тушеных яблок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9765,'Подготовить мясную вырезку, порезать на средние кубики, пересыпать в сковороду, обжарить при среднем нагреве. Мясо без присмотра не оставлять, постоянно перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9765,'Вымыть грибы, поместить в кипяток, дать закипеть, проварить минут 10-12 (зависит от размера грибов), сцедить отвар, дать хорошо остыть, мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9765,'Когда от сковороды с мясом появится запах ароматного бульона, а на кусочках не будет красноватых пятен, всыпать грибы, сдобрить любимыми приправами, размешать, добавить томатную пасту хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9765,'Порезать на кусочки плавленый сыр, соединить с грибами и мясом, перемешать, дать ему расплавиться. Чем тщательнее перемешивать, тем будет вкуснее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9765,'Разложить свинину с шампиньонами под сырным соусом по тарелкам, добавить любой гарнир, подать к столу.  Блюдо можно есть и без гарнира, например,  с любым овощным салатом или малосольными огурчиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9766,'Нарезать баклажаны, картофель, помидоры на тоненькие кружочки. Разогреть сковороду гриль, обжарить быстро баклажаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9766,'Измельчить луковицу, порубить мелко базилик, смешать с фаршем, приправить молотым перчиком, солью, орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9766,'Выложить запеканку слоями в огнеупорную форму (смазать маслом) в следующем порядке. Двойной слой картофеля, сдобренный черным перчиком и солью. Кружки баклажана, сырная стружка, продублировать картофельный слой. Далее фарш, опять картофель, кружочки помидоров, сырная стружка, картофель. Последний слой из сырной стружки добавить за 10 минут до окончания запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9766,'Форму с мясной запеканкой с помидорами, картофелем и баклажаном  тщательно «запаковать» фольгой, отправить в духовку с температурой чуть выше 210 градусов, хватит 50 минут, удалить фольгу, присыпать сырной стружкой, готовить еще минут 10.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9767,'Сырые орешки кешью, финики без косточек, предварительно замоченные в воде, ванилин или экстракт ванили поместить в блендер и измельчить до состояния густого теста. Масса должна быть клейкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9767,'Руки смочить водой, сформовать небольшие шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9767,'Обвалять их в кокосовой стружке или в какао-порошке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9767,'Подать к столу в качестве десерта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Морковь и куриную грудку нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Лук-порей разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Капусту брокколи разобрать на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'В кипящую воду положить мясо и морковь, лавровый лист, варить в течение 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Добавить лук, варить еще 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Лук-порей и лавровый лист убрать, иначе бульон будет горчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9768,'Всыпать рис или макароны, изготовленные из твердых сортов пшеницы, брокколи, посолить по вкусу, варить 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9769,'Для приготовления хрустящих вафель перемешать овсянку, обезжиренный творог, яичные белки и дополнительный желток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9769,'Массу перемешать, жарить в вафельнице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9782,'Смесью залить рыбу, посыпать тертым сыром, печь в духовке в течение 20 минут. Должна образоваться золотистая корочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9769,'Для приготовления пышных и воздушных венских вафель смешать те же самые ингредиенты, но не добавлять желток: он не даст изделиям подняться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9769,'В тесто можно добавлять сахарный песок, мёд, ваниль, стевию, протеин с клубничным, ванильным или шоколадным вкусом, молотую корицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9769,'Массу взбить с помощью блендера: сначала влить яйца, затем всыпать овсянку. Жарить аналогично.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Кабачки промыть, разрезать пополам, вынуть содержимое, «лодочкам» дать обсохнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Нарезать мякоть, очищенный лук и морковь мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Овощную смесь обжарить на оливковом масле вместе с нарезанным чесноком и помидорами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Всыпать измельченную зелень, специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Готовую обжарку положить в кабачковые «лодочки», посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9770,'Печь в духовом шкафу при температуре 170 градусов в течение 15 – 20 минут. Сыр должен расплавиться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Очистить и нарезать ломтиками яблоко и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Отварить на пару, затем превратить в пюре с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Массу немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Взбить яйца вилкой, перемешать с творогом и тоже вымешать блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Обе смеси соединить, добавить ванилин. Должно получиться полужидкое «тесто».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Смазать форму маслом, посыпать измельченными овсяными хлопьями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Вылить тесто, печь при температуре 170 градусов в течение 40 – 45 минут. Готовность блюда проверить деревянной палочкой, спичкой или зубочисткой, она должна остаться сухой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9771,'Суфле вынуть из духовки, остудить и поставить в холодильник на несколько часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'Измельчить с помощью блендера виноград с творогом, изюмом, сырым яичным белком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'В конце добавить ванилин, муку, разрыхлитель. Должна получиться густая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'Очистить банан от кожуры, нарезать кружочками толщиной в один сантиметр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'Разогреть духовку, противень смазать маслом или застелить бумагой для выпекания, можно положит «коврик» из силикона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'Каждую банановую дольку «закатать» в кусочек творожной массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9772,'Шарики выпекать в течение 15 минут, затем вынуть их из духовки, смазать желтком со всех сторон и печь еще пять-семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Креветки посолить, посыпать кайенским перцем, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Если морепродукт замороженный – предварительно его оттаять и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Налить каноловое масло на сковороду с антипригарным покрытием, добавить креветки, обжарить, помешивая, в течение пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Переложить продукт в миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Измельчить репчатый лук и чеснок, обжарить на той же сковороде в течение двух-трех минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Отдельно нарезать морковь и сладкий болгарский перец, добавить в обжарку вместе с разобранной капустой брокколи и зеленым горошком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Подлить немного воды и потушить овощную смесь в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9773,'Добавить креветки, сбрызнуть смесь лимонным соком, перемешать и прогреть на огне еще две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Нарезать кубиками репчатый лук, обжарить в предварительно нагретой мультиварке с растительным маслом в режиме «Выпечка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Сырое куриное филе нарезать кубиками и добавить к луку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Крупно нарезать свежие шампиньоны, добавить в основную смесь, все прогреть в том же режиме, в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Почти при готовности блюдо посолить и поперчить, всыпать пшеничную муку, массу перемешать и жарить три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Влить сливки, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'Затем влить воду, прогревать 20 минут в режиме «Тушение».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9774,'За пять минут до готовности добавить зеленый горошек.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9775,'Подобрать примерно одинаковые по размеру плоды, помыть, обсушить. У каждого яблока срезать «шапочку» со стороны плодоножки, вынуть середину и часть мякоти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9775,'Смешать протертый творог, изюм, сахар и ванилин, поместить внутрь яблок. Переложить фрукты в керамическую форму, залить на треть ее высоты водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9775,'Нарезать из готового теста полосочки, переплести в виде решетки, нарезать по размеру срезанных верхушек, смазать разболтанным яйцом, посыпать сахаром, закрыть верх каждого яблока плетеночкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9775,'Убрать форму в духовку с температурой 200 градусов, корзиночки из яблок с творогом будут готовы примерно (зависит от размера плодов) через треть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Желатин замочить в холодной кипяченой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Нагреть до растворения, не кипятить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Смешать обезжиренный творог, протеин и какао-порошок при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Влить молоко, снова перемешать вместе с желатином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Масса должны быть однородной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9776,'Разлить смесь в формы и поставить в холодильник на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9777,'Не мокрый творог перетереть вместе со спелым бананом до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9777,'Добавить молотую овсяную крупу или хлопья, тесто замесить вручную.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9777,'Поставить на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9777,'Сформовать шарики средней величины, обвалять их в молотых орехах, маке или кокосовой стружке, немного сплющить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9777,'Выложить изделия на застеленный бумагой противень, печь в течение 12 – 15 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Куриные филе разрезать вдоль, пополам. Каждый кусочек посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Разогреть на сковороде растительное масло, огонь – средний.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Обжарить мясо по две-три минуты с каждой стороны, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Стебель сельдерея нарезать тонкими ломтиками в поперечном направлении, виноградины без косточек – пополам, куриное филе – кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Очистить крупный апельсин, удалить белую пленку, мякоть нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Порвать руками хорошо вымытые листья салата латук, выложить их в салатницу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Сверху – смесь ингредиентов, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Для приготовления заправки смешать натуральный йогурт, дижонскую горчицу и жидкий мёд.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9778,'Полить соусом блюдо и подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9779,'Нарезать баклажаны на длинные полосы квадратного сечения (2,5 х 2,5 см), сварить, отцедить, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9779,'Из рисового уксуса, кунжутного масла, сахара, соевого соуса, небольшого количества соли с добавлением дробленого кунжута приготовить заправку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9779,'Разделить остывшие баклажаны на длинные тоненькие полоски, переложить в салатник, приправить нашинкованным зеленым луком, добавить заправку, размешать, дать постоять. Перед подачей салат по-корейски из баклажанов с кунжутом будет неплохо подержать в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'У длинных и тонких огурцов срезать кончики, каждый разрезать пополам или на три части, затем – на тонкие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Сложить нарезку в миску, посолить и оставить на 15 – 20 минут, овощ должен пустить сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Охлажденную говядину нарезать тонкой соломкой, нашинковать полукольцами репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Слить лишнюю жидкость от огурцов, выложить на них красный острый перец, молотый кориандр, измельченный чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Нагреть сковороду с антипригарным покрытием, огонь должен быть сильным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Обжарить мясо до подрумянивания, добавить лук, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Влить соевый соус, жарить еще две минуты, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Содержимое сковороды переложить на огурцы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Нарезать тонкой соломкой сладкий красный болгарский перец.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Выложить на мясо, полить уксусом и растительным маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9780,'Дать немного постоять, затем перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9781,'Перемешать с помощью блендера творог, кокосовую стружку, сметану и мёд.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9781,'Сформовать руками небольшие шарики, внутрь поместить по любой ягодке или орешку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9781,'Поставить на час в морозильную камеру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9782,'Любую белую рыбу, например, тилапию, промыть, обсушить, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9782,'Сковороду смазать маслом, выложить филе, посолить, посыпать «рыбными» специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9782,'Для соуса разбить в миску сырые куриные яйца, добавить мелко нарезанный зеленый лук и сметану, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Смешать с массой семечки льна, добавить кокосовую стружку и какао-порошок. Смесь должна быть густой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Выложить её слоем в один сантиметр на кальку или полиэтилен в виде прямоугольника средней величины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Свежий очищенный банан разрезать поперек на две части, каждую – вдоль на четыре части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Брусочки выложить на лепешку, завернуть, как рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Хорошо обжать, придать ровную форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Полученную «трубочку» разрезать на две-три части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9783,'Операцию повторить с оставшимися банановыми брусками и основной массой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9784,'Очистить розовый грейпфрут от кожицы и белых пленок и прожилок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9784,'Добавить в мякоть спелый банан, растительное молоко, тертый свежий имбирь, маковый порошок, очищенную морковь и кубики льда.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9784,'Измельчить смесь до однородного состояния с помощью блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9785,'Мелко нарезать зелень укропа и лука, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9785,'Добавить в зелень нежирный домашний творог, соль, сахарный песок, перемешать ингредиенты с помощью блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9785,'Если масса получилась слишком сухой, можно добавить немного сливок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9785,'Нарезать «Бородинский» или другой ржаной хлеб поперек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9785,'Намазать ломтики полученной творожной смесью, выложить слой тонко нарезанного редиса, затем – свежие огурцы, сверху – слабосоленая семга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9786,'Взбить с помощью блендера творог, какао-порошок и свежий банан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9786,'Отдельно взбить с помощью этого же прибора творог, банан и ванилин из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9786,'В креманки выложить обе смеси слоями, чередуя цвет, снизу должна быть белая масса, сверху – темная.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9786,'В середину положить немного белой и «нарисовать» узор зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Вскипятить в кастрюле воду, положить тушки кальмара, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Через две минуты вынуть, промыть холодной водой и откинуть на сито или дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Натереть морковь соломкой, посолить, дать немного постоять, сок отжать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Морепродукт нарезать соломкой, перемешать с морковью, посолить, влить уксус и положить сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Добавить измельченный чеснок, черный и красный жгучий перец, семена кунжута, полукольца репчатого лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9787,'Массу полить растительным маслом, перемешать, поставить в холодильник на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Тыкву нарезать кусочками, залить водой и варить под крышкой до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Измельчить овощ блендером до состояния пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Поставить на тихий огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Вбить сырые куриные яйца по одному, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Отдельно обжарить манную крупу на сковороде без масла, она должна приобрести кремовый оттенок, всыпать в основную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Варить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Добавить апельсиновую цедру и корицу. Масса должна загустеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Вылить смесь в присыпанную пшеничной мукой или молотыми сухарями форму, печь в духовом шкафу при температуре 180 градусов в течение 20 минут, до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9788,'Пирог остудить, вынуть из формы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9789,'Морковь, корень петрушки и капусту брокколи вымыть, отварить в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9789,'Готовые ингредиенты немного остудить, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9789,'Отдельно взбить сырые куриные яйца с молоком, массу посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9789,'Добавить подготовленные овощи, консервированный или отварной зеленый горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9789,'Смазать сковороду маслом, вылить смесь, жарить на тихом огне до готовности, с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9790,'Нашинковать капусту, свежий огурец нарезать кусочками, ветчину – соломкой, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9790,'Ингредиенты перемешать, посолить и поперчить по вкусу, заправить сметаной, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Кабачок вымыть, нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Так же нарезать куриную ветчину или отварную курицу, сладкий болгарский перец – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Приготовить творожный крем из мягкого творожного сыра с рубленой зеленью укропа, измельченным чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'В форму для запекания выложить слой кабачков, затем мясо и перец, сверху – творожная масса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Слои повторять, пока форма не наполнится, сверху должны оказаться кабачки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Натереть сыр «Моцарелла», посыпать блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9791,'Поставить лазанью в духовку, печь при температуре 180 градусов в течение получаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9792,'Подготовить мясо, включить для разогрева до 180 градусов духовку. Порезать грудку на кусочки среднего размера, картофель – узкими брусочками. Приготовить из сметаны и кетчупа заправку, чуть подсолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9792,'Очень тоненько нашинковать луковицу, поджарить до красивого золотистого колера в горячем масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9792,'Выложить дно формы слоем картофеля и лука, уложить на эту «подушку» курицу, полить соусом. Отправить куриные грудки с картофелем в сметане на четверть часа в духовку, вынуть, подсолить, сдобрить молотым перчиком, перемешать, запечь до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'В небольшой емкости смешать сахарозаменитель, яблочный уксус, соевый соус, черный молотый перец, разведенный в воде крахмал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'Очистить и натереть корень имбиря, измельчить чеснок, добавить то и другое в соус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'Смесь прогреть до кипения, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'Смазать маслом противень, выложить куриное филе, нарезанное кусками средней величины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'Полить готовым соусом, поставить в духовку на полчаса, температура приготовления – 220 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9793,'Блюдо перемешивать каждые пять-семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'Куриные грудки очистить, промыть, порезать на порционные кусочки небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'Мясо приготовить с небольшим количеством воды или потушить на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'В готовый продукт добавить соль и нарезанную морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'Через пять минут положить вымытую капусту брокколи, нарезанную кусочками, добавить холодную воду и оливковое масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'Тушить блюдо еще 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9794,'При подаче посыпать рубленой петрушкой, укропом, кинзой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Креветки разморозить, обсушить и положить в глубокую тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Посолить по вкусу, добавить кайенский перец, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Каноловое масло разогреть в сковороде вог, обжарить морепродукты на сильном огне в течение пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Выложить креветки обратно в тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Нарезать лук и чеснок, обжарить на масле, оставшемся от приготовления креветок, в течение трех минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Красный болгарский перец, морковь и капусту брокколи выложить на сковороду вместе с зеленым горошком, залить овощным бульоном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Огонь уменьшить до среднего, готовить овощи до мягкости в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Креветки снова переложить на сковороду, полить лимонным соком, прогревать одну минуту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9795,'Подать блюдо с отваренным рисом и соевым соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Печенье «Юбилейное» измельчить в крошку, добавить яблочный сок, размять, выложить на дно формы для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Творог без крупинок взбить вместе с творогом, йогуртом, сахарным песком, добавить сок лайма и цедру, взбить до гладкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Добавить сырые куриные яйца и картофельный крахмал, взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Дно формы обернуть фольгой с внешней стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'В большую емкость или на противень налить воду, уровень должен доходить до половины высоты формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Сверху накрыть фольгой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Готовить блюдо на поучившейся водяной бане в течение часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9796,'Форму вынуть, фольгу снять, охладить пирог в течение нескольких часов в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Протереть с помощью блендера творог с очищенным бананом, пюре должно быть однородным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Добавить овсяные хлопья, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Поставить тесто на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Приготовить начинку из заранее замоченной кураги: в размягченные плоды аккуратно поместить по орешку кешью или миндаль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Достать тесто, поделить на 15 частей, из каждой сформовать шарик, внутрь положить курагу с орешком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Готовые «конфеты» обвалять в кокосовой стружке, выложить на застеленный бумагой противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Печь при температуре 180 градусов в течение 12 – 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9797,'Перед подачей изделия охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,'Отделить и взбить до устойчивой пены белки, всыпать сахар, добавить желтки (по одному), соду (гасить лимонным соком или уксусом), мед и маленькими порциями муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,'Всю массу поделить на три части. Добавить в первую растворимый кофе, вторую – какао, третью – ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,'Выпекать в духовке с температурой 180 градусов каждый корж отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,'Из взбитого масла с вареной и обычной сгущенкой с добавлением ванили и кофе приготовить крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,'Положить на блюдо темный корж, хорошо промазать кремом, накрыть светлым, смазать кремом, уложить поверх последний темный корж.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9798,' Верх торта «Шарлота» со вкусом кофе оформить жидким темным шоколадом, а белым можно сделать надпись или какой-нибудь узор, обсыпать обжаренным и крупно порубленным  фундуком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9799,'Луковицу очистить, нарезать, обжарить вместе с квашеной капустой до мягкости и золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9799,'Тонкий армянский лаваш разрезать на три-четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9799,'Выложить на него еще теплую начинку, завернуть «конвертом» и обжарить до золотистой корочки со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9800,'Взбить молоко с сахарным песком, добавить пшеничную муку. Масса по консистенции должна быть похожа на сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9800,'Добавить соль, молотую корицу, тертый имбирь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9800,'Разогреть сковороду, смазать сливочным маслом, выпечь блинчики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9800,'Подать с творогом или нарезанными яблоками, грушами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9801,'Кабачок очистить и нарезать кружками толщиной в один-два сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9801,'Выложить кабачок в форму, поставить в духовку на 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9801,'Нарезать репчатый лук, помидор, натереть твердый сыр «Пармезан» или «Российский».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9801,'Через 15 минут кабачок достать, выложить поверх него измельченные ингредиенты, поставить в духовку на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9802,'Дать духовке нагреться (180 градусов будет достаточно), подготовить противень: смазать маслом, выстелить фольгой или бумагой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9802,'Достать заранее масло, чтобы размякло, смешать с сахаром, всыпать муку, добавить кофе, какао, чуть подсолить, вымесить тесто, раскатать между двух листов пергаментной бумаги, отправить на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9802,'Вынуть тесто, формочками вырезать печенье, переложить вкусное кофейно-шоколадное печенье на противень, отправить на треть часа в прогретую',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Натереть морковь, картофель, кабачок, отцедить излишки жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Измельчить зелень укропа и петрушки, добавить в овощи, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Отдельно разбить и взболтать сырые куриные яйца, добавить в основную массу, посолить, поперчить по вкусу, всыпать пшеничную муку и картофельный крахмал.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'«Тесто» выкладывать на горячую сковороду и обжаривать с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Готовые изделия выложить на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Натереть сыр твердого сорта: «Пармезан», «Грана Падано», «Грюйер», «Пекорино Романо».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Перемешать с томатной пастой или соусом, измельченным чесноком и зеленью укропа и петрушки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9803,'Смесь выложить на оладьи, печь до образования румяной корочки при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Кабачок нарезать кольцами, обмакнуть в отдельно взбитое яйцо, в пшеничную муку, обжарить на сковороде с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Изделия выложить на бумажные полотенца для впитывания излишков жира.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Репчатый лук нарезать полукольцами, натереть морковь на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Нарезать кольцами помидоры, порубить очищенный чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Противень смазать растительным маслом, выложить кружочки кабачка, они должны располагаться плотно, в два слоя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'На кабачки выложить нарезанную кружками отваренную куриную грудку, морковь, лук, посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Следующий слой – помидоры, чеснок, тертый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Все вместе варить полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Оставшиеся яйца перемешать с молоком или водой, посыпать рубленой зеленью, залить смесью основную массу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9804,'Поставить блюдо в духовку, печь до готовности, пока не расплавится сыр и не образуется аппетитная румяная корочка.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Филе вымыть, вытереть бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Нарезать длинными брусочками толщиной в два сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Смешать панировочные сухари с кунжутом белого и черного цвета. Добавить соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Отдельно взбить вилкой сырые куриные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Куриные «палочки» обвалять в муке, обмакнуть в яйцо, запанировать в сухарях.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Выложить на противень, поставить в разогретую духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Печь при температуре 220 градусов в течение 10 – 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Приготовить соус из сметаны, натурального мёда и дижонской горчицы, посолить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9805,'Нарезать брусками морковь и огурец, прогреть. Палочки подать с горячими овощами и соусом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9806,'Свиные отбивные (или куриное филе) немного отбить с обеих сторон, поперчить, посолить, спрыснуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9806,'Свежие шампиньоны промыть и обжарить их до полной готовности, сыр порезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9806,'Разогреть на сковородке небольшое количество растительного масла, в течение 2-3 секунд обжарить на нем подготовленное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9806,'Затем переложить отбивные на противень, выложить на них обжаренные грибы, поверх которых положить ломтики сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9806,'Выпекаются свиные отбивные с шампиньонами и сыром 20 минут при 180-200 градусах, после чего посыпается измельченной зеленью или зеленым луком и подается к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Смешать в большой миске овсяные хлопья, рубленый сушеный инжир, фисташки, любые сушеные ягоды, тертую цедру и сок половины апельсина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Добавить ванильную эссенцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Отдельно взбить сырое яйцо, добавить в основную массу, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Выложить смесь в застеленную пергаментом квадратную форму средней величины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Печь при температуре 180 градусов в течение 20 – 25 минут до золотистого цвета, должна образоваться румяная корочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9807,'Оставить на 10 минут, разрезать на полоски и остудить выпечку на решетке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9808,'Свежие помидоры надрезать, ошпарить, снять кожицу, разрезать плоды пополам, удалить семена, каждую половинку разделить на шесть-восемь частей, это зависит от величины овоща.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9808,'Мелко нарезать лук-репку, потушить с небольшим количеством воды, добавить помидоры, тушить, помешивая, в течение 10 – 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9808,'Консервированную кукурузу прогреть в банке, жидкость отцедить через дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9808,'Перемешать теплые зернышки с помидорами, тушить вместе пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Репчатый лук или лук-порей нарезать кольцами или полукольцами, цуккини и баклажаны, помидоры – кубиками, капусту – соломкой, стебли сельдерея – кусочками. Натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Разогреть в сотейнике растительное масло, обжарить лук, добавить морковь, прогреть, следующий ингредиент – баклажаны, затем цуккини, тушить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Всыпать нашинкованную капусту, сельдерей и помидоры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Тушить овощную смесь в течение еще пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Влить воду, посолить и поперчить по вкусу, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9809,'Положить говяжий фарш, нарезанный маленькими кусочками, варить 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9810,'Натереть кабачок соломкой, обжарить до мягкости на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9810,'Отдельно взболтать сырые куриные яйца с солью, зеленью, залить смесью кабачки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9810,'Блюдо накрыть крышкой, прогревать до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9810,'Разрезать омлет на порции, подать в горячем виде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'Вскипятить небольшое количество воды, залить чернослив, дать постоять пять минут, плоды должны стать мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'В нежирный кефир добавить овсяные, гречневые, ржаные или пшеничные отруби, льняную муку, какао-порошок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Гаспачо с сельдереем и мятой хорошо охладить, подавать с зеленью и кусочками льда.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'Разбухший чернослив измельчить в пюре с помощью блендера вместе с водой или нарезать мелкими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'Добавить массу в кефирную смесь, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9811,'Коктейль поставить в холодильник на пять минут, отруби должны набухнуть, смесь будет густой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9812,'Творог размять с помощью вилки, добавить яйцо и жидкий мёд, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9812,'Отдельно натереть заранее отваренную морковь, добавить в основную массу вместе со светлым изюмом, тыквенными семечками, всыпать молотую корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9812,'Смазать сливочным маслом формочки для маффинов, выложить смесь на высоту в два сантиметра, аккуратно разровнять с помощью лопатки, печь при температуре 200 градусов в течение 20 – 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9812,'Подать блюдо с натуральным йогуртом или сметаной, натуральным мёдом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9813,'Листья зеленого салата вымыть, обсушить и порвать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9813,'Нарезать кусочками отваренное куриное мясо, сыр, авокадо – кубиками, оливки – пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9813,'Все составляющие перемешать, заправить оливковым маслом и выложить на салатные листья. Соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9814,'Перемешать с помощью блендера овсянку, обезжиренный творог, сырые яичные белки, разрыхлитель, ванильный сахар из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9814,'Овсянку можно добавить в последнюю очередь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9814,'Выпечь небольшие оладьи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Порционно порезать свиное филе, каждый кусок хорошенько отбить, смазать солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Смазать противень растительным маслом и выложить на него подготовленное мясо на небольшом друг от друга расстоянии.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'На мясные кусочки выложить нарезанный полукольцами репчатый лук, смазать его майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Поверх луково-майонезного слоя распределить кружки помидоров, которые нужно поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Сыр натереть на крупной терке и 1/2 частью от получившегося объема посыпать помидорный слой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Помытый и очищенный картофель порезать дольками и посолить, после чего переложить его на противень на свободное между мясом место.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'Запекать филе свиное по-французски с картофелем 1,5 часа при 200 градусах, все время поливая выделяющимся соком (если сока будет выделяться мало, можно влить чуть-чуть кипятка).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9815,'За 20 минут до готовности картофель и мясо необходимо посыпать оставшейся половиной сыра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9816,'В миске смешать яйца, сахар и соль, добавить к ним творог, тщательно все размять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9816,'В творожную массу ввести муку с ванилином, мешать содержимое миски до тех пор, пока не получится однородное тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9816,'Получившееся тесто скатать в колбаску желаемого объема и порезать ее порционными кусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9816,'Каждому куску придать округлую форму, после чего чуть обмакнуть каждый в муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9816,'Сковородку с растительным маслом хорошо разогреть и обжарить ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9817,'Обжарить в разогретом масле нашинкованный лук и грибы, закипятить в кастрюле бульон, положить шампиньоны с чесноком, добавить специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9817,'Через 8 минут удалить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9817,'Вегетарианский крем-суп из грибов на сливках взбить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9817,'Подавать, посыпав орешками кедра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9817,'Оформить парой грибных пластинок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Лук нашинковать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Грибы порезать на кубики, протушить их до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Добавить вино, продолжить нагревать до его испарения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Готовой зажаркой заправить бульон, дать ему закипеть, проварить около четверти часа (через 10 минут положить в него тимьян).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Измельчить грибной крем-суп из лисичек с белым вином с помощью блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9818,'Добавить слегка нагретые сливки и специи, подсолить, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'В сотейнике с толстым дном довести до кипения бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'До прозрачности на сливочном масле обжарить кубики лука, присыпать их мукой, перемешать, обжаривать 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'Снять с плиты, соединить с бульоном, размешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'У помидоров убрать шкурку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Чеснок мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'К жидкости добавить ножки грибов с приправами, дать закипеть, проварить около трети часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'Грибные шляпки порезать на кусочки, обжарить на сливочном масле, присолить, добавить сок лимона, перемешать, тушить 5 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'Суп процедить, положить в него грибы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'Для заправки перемешать сливки с желтками, добавлять их по ложечке в суп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'Поставить готовый крем-суп на огонь, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9819,'К столу подавать с кусочком сливочного масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Поставить варить нарезанный картофель с морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Грибы обжарить с луком, в конце добавить чеснок, раздавленный прессом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Грибную зажарку переложить в овощной бульон, дать ему закипеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Добавить натертый плавленый сыр, размешать, чтобы он растворился.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Приправить суп специями, добавить сливки, подсолить, взбить с помощью блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'В грибной крем-суп с картофелем и сыром добавить пармезан и чуть-чуть мускатного ореха, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9820,'Дать ему немного постоять и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'Лук порубить комбайном, обжарить со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'Добавить кубики шампиньонов, протушить минут 10-15, присыпать мукой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'Чтобы сливочный крем-суп из грибов с хересом получился нужной консистенции, во время измельчения его блендером, добавить немного муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'Влить смесь молока со сливками, дать супу закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'Варить около 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9821,'В конце влить херес, проварить ещё три минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Морковь крупно натереть, лук нашинковать кубиками, обжарить их со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Добавить в зажарку кусочки грибов и вареных каштанов, тушить 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Затем добавить вермут, дать ему выпариться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Добавить бульон, дать супу закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Нагрев уменьшить, варить порядка 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Блендером превратить массу в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9822,'Крем-суп из грибов и каштанов с вермутом посолить, поперчить, подавать с белыми сухариками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'Сыр мелко натереть на терке, пропустить зубчики чеснока через пресс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'В миске смешать подготовленный сыр и чеснок, вбить к ним яйца и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'Добавить в сырную массу майонез и все еще раз тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'В получившийся кляр обмокнуть предварительно размороженные палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'Обжарить крабовые палочки в сырно-майонезном кляре с чесноком на растительном масле со всех сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9823,'Выложить палочки на сервировочное блюдо и подать в охлажденном виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Нарезать картофель и грибы с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Картофель отварить, превратить в пюре вместе с плавленым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Обжарить лук с грибами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Всё смешать, прогреть на небольшом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Измельчить с помощью блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9824,'Сливочно-грибной крем-суп с плавленым сыром поперчить, посолить по вкусу и, продолжая взбивать, добавить тонкой струйкой сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9825,'Залить на полчаса белые грибы водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9825,'Картофель нарезать, поставить варить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9825,'Лук с шампиньонами порезать и обжарить, отварить белые грибы около 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9825,'Все смешать, измельчить блендером до состояния пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9825,'В крем-суп с белыми грибами и соусом бешамель влить горячий соус бешамель, дать закипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9826,'Порезать лаваш небольшими кусочками, промазать кетчупом, а сверху тонким слоем фарша с луком и специями (если слой будет толстым, то мясо может не прожариться).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9826,'Взбить яйцо с солью, осторожно полить полученной смесью лаваш, свернуть его в трубочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9826,'Обжарить хрустящие трубочки из лаваша с фаршем со всех сторон в разогретом масле. Блюдо можно приготовить и в духовке, только перед запеканием надо смазать трубочки маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Нарезать лук и обжарить до прозрачности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Добавить кусочки грибов, жарить еще минут 6-7.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Разбавить частью бульона, объединить все ингредиенты (кроме сливок), хорошо все перемешать, поперчить, посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9827,'Как только сливочный крем-суп из шампиньонов на скорую руку закипит, влить сливки, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Срезать с ножки соцветия капусты, отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Грибы обжарить на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Лук залить сливками, добавить травы, прокипятить пару-тройку минут луковицу вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Капусту и грибы разбить блендером до состояния пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Добавить сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9828,'Несколько минут крем-суп из грибов, капусты и брокколи прогреть, перемешать, добавить зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9829,'Порезать мелко перец чили, высыпать во взбитый с медом соевый соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9829,'Порезать рыбу на кусочки, уложить в лоток, залить соусом, выдержать треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9829,'Почистить красный сладкий перец, нарезать на квадраты, насадить рыбу попеременно с перцем на шпажки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9829,'Жарить шашлык из лосося с перцем чили до готовности, подать горячим с зеленью и черными маслинами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Помидоры поместить в кипяток, а потом сразу окатить холодной водой, очистить от шкурки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Половину из них мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Порезать огурец, сложить кусочки в чашу блендера, измельчить, поперчить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Нашинковать мелко кинзу, перемешать с томатным соком, добавить масло с уксусом и табаско, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Остатки овощей нашинковать на мелкие кусочки, перемешать все с томатом, если надо, то подсолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9830,'Убрать суп Гаспачо с соусом Табаско в холодильник настояться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Помидоры опустить в кипяток, снять шкурку, порезать на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Перец нарезать более мелкими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Чили и лук мелко нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Чеснок раздавить прессом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Петрушку нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Превратить все овощи в пюре, используя блендер, поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Мясо краба разобрать на волокна, присыпать измельченной кинзой, перемешать с маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Добавить сахар, полить соками, поперчить, посолить, взбить блендером.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Из холодильника достать пюре, разложить крабовое Гаспачо на праздник по пиалам.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9831,'Положить в каждую по паре ложечек крабовой смеси.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9832,'Подготовить свиную вырезку: помыть, обсушить, обрезать излишки жира, удалить жилки. Приготовить из воды, сахара и соли засолочную смесь, поместить мясо в пакет и залить смесью. Закрыть плотно пакет, поместить в подходящую кастрюлю и отправить минут на 40 в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9832,'Включить на разогрев примерно до 190 градусов духовку. Достать мясо, слить рассол, кусок обмыть и обтереть, переложить в глубокую форму',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9832,'Смешать в миске сок одного лимона, мед, тимьян, горчицу, оливковое масло и измельченный чеснок, тщательно перемешать и вылить на свинину. Во время приготовления мясо периодически (через 7-10 минут) поливать подливкой из формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9832,'Свиная вырезка в подливке из меда и горчицы будет готова примерно через 30-40 минут. Блюдо можно есть как горячим так и холодным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Порезать огурец и болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Чеснок раздавить прессом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Мелко нашинковать кинзу и перья зеленого лука, огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'В блендере приготовить томатную основу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Сварить креветки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Объединить все ингредиенты, приправить кумином и перцем, добавить уксус, чуть посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Хорошо перемешать гаспачо с помидорами в собственном соку и креветками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9833,'Убрать остыть в холодильник на 3 часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Очистить помидоры от шкурки, обдав их кипятком, а потом поместив под холодную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Нарезать перец и огурец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Лук нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Сельдерей порезать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'Всё сложить в чашу блендера, взбить до состояния пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9834,'В овощное пюре добавить базилик с мятой и залить томатным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9835,'Поломать лепешку и добавить в суп. Должно получиться густое и сытное блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Помидоры разрезать на 4 части, удалить семечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Огурцы очистить от шкурки, тоже убрать семечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Овощи крупно нарезать, сложить все в миску, добавить молоко, влить масло, соус табаско и уксус, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Поставить на полтора-два часа в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Смесь измельчить блендером, вылить в чашу мультиварки, посолить, поперчить, добавить специи и перемешать, если масса слишком густая, то добавить воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Варить 15 минут, выставить режим «суп», дать остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Перелить в другую посуду, поставить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Пока гаспачо в мультиварке с сухариками остывает, нарезать на кубики батон, обжарить в мультиварке до корочки на режиме «Выпечка».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9836,'Охлажденную массу разложить по тарелкам, присыпать сухариками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Замочить на 5 минут хлеб.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Помидоры окатить кипятком, очистить шкурку, удалить семена, измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Огурцы почистить, разрезать, удалить семена, порубить на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Сложить всё в блендер, добавить кусочки болгарского перца, сок, чили, табаско и воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Взбить смеси, но должны остаться небольшие твердые кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Приправить солью, перемешать убрать на 3 часа в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Для крутонов натереть куски хлеба чесноком, порезать на кубики, сложить в контейнер с маслом, потрясти, чтобы все они пропитались.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Обжарить на сковороде до красивого золотистого цвета.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Для сальсы авокадо порезать на кусочки, сбрызнуть соком, чтобы плод не потемнел.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Перемешать его с огурцом и чили.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Достать овощную смесь из холодильника, разлить испанский гаспачо с сальсой и крутонами по тарелкам.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9837,'Добавить в каждую крошку льда, сальсу, посыпать рубленым базиликом, положить крутоны.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9838,'Блендером измельчить очищенные томаты с чесноком и маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9838,'На маленькие кубики порезать лук, сельдерей, перец и авокадо, перемешать с пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9838,'В гаспачо с авокадо и зеленью добавить измельченную петрушку, поперчить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9838,'Убрать его в холодное место на несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9839,'Порезать все продукты на кусочки, сложить в чашу блендера, измельчить до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9839,'Добавить масло, поперчить и посолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9839,'Томатный гаспачо по-андалузски хорошо охладить, убрав на 3-4 часа в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Фисташки очистить, обжарить на сковороде в течение двух минут без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Растопить сахар на среднем огне, карамелизовать фисташки и остудить на тарелке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Ошпарить апельсин, обсушить, цедру снять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Из мякоти выжать сок, тонко нарезать цедру.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Очистить тыкву, нарезать небольшими кубиками со стороной в два или три сантиметра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Измельчить очищенный репчатый лук и чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Разогреть в кастрюле сливочное масло, всыпать чеснок, лук, карри, все вместе жарить до золотистого цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Всыпать кубики тыквы, хорошо перемешать, жарить до румяной корочки в течение нескольких минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Влить апельсиновый сок, заранее приготовленный куриный бульон, соевый соус, перец молотый – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Прогревать под крышкой до мягкости основного ингредиента в течение 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Массу взбить при помощи погружного блендера.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9840,'Подать к столу с фисташками в сахаре и яркими полосками апельсина.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9841,'Нарезать мясо кубиками 4×4, обжарить чеснок и лук в разогретом масле. Добавить кубики говядины, жарить 5 минут при сильном нагреве до корочки, всыпать паприку, добавить через пару минут томатную пасту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9841,'Прожарить несколько минут, залить водой, присолить, сдобрить перцем, добавить пару-тройку лавровых листиков, тушить час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'В конце приготовления влить водку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9841,'Нарезать крупно морковь, картофель и сладкий перец – кубиками. Высыпать все к мясу, залить пивом (вином), добавить немного воды, варить гуляш с овощами на пиве до мягкости картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Очистить и нарезать тыкву, морковь, репчатый лук и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Разогреть на сковороде оливковое масло, обжарить морковь, затем всыпать лук, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Добавить тыкву, затем рубленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Все вместе прогревать пять или семь минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Потушить под крышкой несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Массу переложить в кастрюлю, подлить кипящую воду, посолить по вкусу и приправить молотым мускатным орехом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Очистить имбирь, нарезать, переложить к остальным ингредиентам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Взбить массу при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9842,'Влить жирные сливки, перемешать и прогреть на тихом огне.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Мелко порубить репчатый лук и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Очистить тыкву, мякоть крупно нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Сладкие груши очистить и разрезать на четвертинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Переложить тыкву и грушу в огнеупорную форму, печь при температуре 200 градусов в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Взбить погружным блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Очистить и подсушить на сковороде тыквенные семечки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Разогреть в кастрюле сливочное масло, обжарить лук и чеснок, влить куриный бульон, посолить и поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Всыпать молотую корицу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Выложить готовое пюре, прогреть, довести до закипания, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Порезать хлеб на кубики и обжарить на сливочном масле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9843,'Суп при подаче посыпать белыми домашними сухариками, очищенными семечками тыквы.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Нарубить лемонграсс.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Нарезать небольшими кубиками мякоть тыквы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Репчатый лук нашинковать, тушить на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Через две минуты добавить чеснок, лавровый лист, веточки тимьяна, лемонграсс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'В сотейник выложить тыкву, прогревать десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Влить куриный бульон, тушить 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Вынуть из полученной массы тимьян и лавровый лист.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'Остальные ингредиенты пробить при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9844,'При подаче украсить листочками петрушки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Порубить репчатый лук и чеснок, то и другое обжарить до появления золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Нарезать тыкву, морковь, картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Влить воду, варить до готовности под крышкой, время – около получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Снять суп с огня, остудить, взбить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Добавить сливки, посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9845,'Смесь довести до кипения на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Куриные бедра порубить кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Варить в подсоленной воде со специями в течение двадцати минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Добавить картофель, зеленый горошек, прогревать до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Приготовить обжарку из репчатого лука на сливочном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Овощи и мясо вынуть из бульона, добавить обжарку, все ингредиенты взбить при помощи блендера, а затем разбавить бульоном до нужной консистенции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9846,'Поставить на огонь, влить сливки, прогреть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9847,'Взбить до состояния крепкой пены сахар, сыр маскарпоне и сливки, отправить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9847,'Для блинов смешать сахар, разрыхлитель, какао-порошок, муку до однородной смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9847,'В отдельную посуду положить сметану, влить молоко, хорошо перемешать, вбить яйца, влить эспрессо, добавить ванилин, растопленное масло, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9847,'Объединить полученную жидкую массу с  мучной смесью, аккуратно перемешать до исчезновения комочков. Если получилось чересчур жидкое тесто (зависит от сорта муки), то всыпать еще пару ложек муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9847,'Нажарить на разогретой сковороде блины, переложить готовые блины ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Куриное филе промыть, положить в воду, варить на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'После закипания огонь убавить, накрыть крышкой, оставить щель. Варить еще полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Если для приготовления используется целая куриная тушка, то на варку бульона понадобится два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Отварить в готовом бульоне картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'На сливочном масле спассеровать лук-порей, куриное мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Обжарку добавить в картофель, взбить массу блендером.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Подлить сливки, суп довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9848,'Блюдо подать с рубленой зеленью, белыми гренками, тертым копченым сыром-косичкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9849,'Отварить куриное мясо, отделить его от костей, пропустить через блендер, добавить немного куриного бульона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9849,'Пшеничную муку обжарить на сливочном масле, влить остатки бульона, смесь проварить в течение двадцати минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9849,'Массу процедить, в ней не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9849,'Добавить куриное филе и сырой куриный желток, взбитый с небольшим количеством молока, сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9849,'Под действием горячего желток свернется.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Приготовить куриный бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Положить картофель, варить на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Растопить на сковороде сливочное масло, спассеровать репчатый лук и куриное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Очистить и обжарить на сухой сковороде грецкие орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Перемолоть в крошку при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Залить кипятком чернослив на пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Сухофрукты добавить к картофелю, туда же – обжарку с луком, сметану.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Массу пробить блендером.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9850,'Посыпать орехами при подаче.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Налить в чашу мультиварки растительное масло, обжарить рубленый репчатый лук до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Тыкву очистить и нарезать кубиками, все вместе пассеровать несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Добавить нарезанный картофель и куриное филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Прогревать пять минут, затем влить куриный бульон, посолить и поперчить по вкусу, варить полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Перелить суп в блендер, приготовить пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9851,'Положить сметану, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Окорок отварить, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Мясо вынуть, отделить от костей, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'На сливочном масле обжарить измельченную морковь и репчатый лук, перец чили, очищенные помидоры и сладкий болгарский перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Посыпать карри.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'В куриный бульон добавить обжарку, картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Варить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Массу взбить в пюре при помощи погружного блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9852,'Куриное мясо добавить при подаче.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9853,'Подобрать сушки подходящего диаметра (должны легко надеваться на сосиски), взять достаточное количество для приготовления, положить в глубокую миску. Залить подсоленным молоком, дать чуть размякнуть, а не раскиснуть. Включить на разогрев духовку, температура должна быть чуть меньше 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9853,'Намазать слегка каждую из сосисок горчицей, плотно нанизать сушки, но края сосисок должны выглядывать. Уложить сосиски  в форму, смазанную маслом, присыпать сырной стружкой. Отправить форму в духовку примерно на треть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9853,'Сыр зарумянится, сверху появится хрустящая корочка, но внутри сосиски в сушках под сырной корочкой будут нежные и мягкие, подавать блюдо горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Разогреть сливочное масло. Обжарить нарезанный репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Добавить картофель, прогревать все вместе до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Положить аджику, влить кипяток, ингредиенты должны быть полностью покрыты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Тушить на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Приготовить соус из сметаны, чеснока, рубленой зелени укропа и петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Влить в овощи, прогревать еще пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Затем добавить маринованные огурцы и заранее отваренное куриное филе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Соль и молотый перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9854,'Массу взбить при помощи блендера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Горох замочить на ночь в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Наутро отцедить и отварить в курином бульоне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Рыбу и морковь вытащить, нарезать кусочками, отходы убрать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Через полчаса после начала варки добавить картофель, куриное филе, морковь, репчатый лук, немного сливочного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Отдельно измельчить стебли сельдерея при помощи блендера, должна получиться зеленая кашица.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Влить массу в суп, добавить молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Довести до кипения, выключить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9855,'Взбить суп при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Дикий рис залить на ночь кипяченой холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Посолить. Варить в течение сорока минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Дать постоять двадцать минут, крышку не снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Куриное филе, репчатый лук и морковь, стебли сельдерея нарезать кубиками, продукты спассеровать на сливочном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Посолить, залить куриным бульоном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Добавить специи: сушеный майоран, тимьян, розмарин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Положить куриное филе, довести суп до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Вынуть мясо через пятнадцать минут, добавить рис и вернуть мясо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Растопить в сотейнике немного сливочного масла, ввести муку, перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Затем влить молоко, потушить смесь до загустения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9856,'Влить в суп, добавить сливки средней жирности, взбить все вместе погружным блендером.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Приготовить овощной бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Добавить картофель, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Растопить на сковороде сливочное масло, обжарить нарезанный лук-порей, морковь, куриное филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Обжарку добавить в бульон, варить в течение двадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Приготовить пюре при помощи погружного блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'Добавить жирные сливки, суп довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9857,'При подаче посыпать суп тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9858,'Отварить, охладить и почистить креветки. Пару вареных яиц и отварной картофель измельчить на терке (крупной), чуть подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9858,'Подготовить два порционных салатника. Уложить слоеный салат с креветками и картофелем в следующем порядке: креветки-майонез-яйца-майонез-картофель-майонез- креветки. Верх салата полить майонезом, оформить половинками яиц и петрушкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9859,'Куриное филе мелко нарезать, положить в кипящую воду, поперчить и посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9859,'Добавить кубики картофеля и репчатого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9859,'Дать закипеть, положить плавленый сыр, варить около получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9859,'Массу взбить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9859,'Суп должен немного постоять и загустеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Бобы промыть, влить воду, соотношение – один к двум.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Во время приготовления влить немного оливкового масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Другой способ – отварить чечевицу в грибном бульоне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Шампиньоны обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'На сливочном масле спассеровать морковь и лук, куриное филе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Обжарку добавить в бульон, положить туда же картофель, соль, поперчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Приготовить пюре при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9860,'Подать суп к столу с обжаренными грибами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Куриный окорочок отварить в подсоленной воде до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Мясо вынуть, кости отделить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Нарезать картофель, стебли сельдерея, репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Картофель и сельдерей положить в бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Разогреть растительное масло, обжарить шампиньоны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Отдельно спассеровать репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Все готовые овощи и плавленый сырок взбить при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Суп довести до кипения, огонь погасить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9861,'Блюдо подать к столу с жареными грибами и курицей.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Сварить бульон из куриного окорочка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Соль и перец молотый – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Мясо должно отстать от костей, его нужно вынуть, разобрать на волокна.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Обжарить морковь, репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Картофель, овощи добавить в бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Приготовить пюре блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Долить молоко, довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9879,'Воду в кастрюле раскрутить так, чтобы образовалась воронка в центре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9862,'Сыр «Сулугуни» нарезать тонкими кольцами, посыпать молотой паприкой, разложить в тарелки вместе с зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Отварить куриное филе, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Нарезать репчатый лук и чеснок, спассеровать на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Бланшировать помидоры, снять кожицу, мякоть положить в обжарку, потушить четыре минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Довести воду до кипения, всыпать кубики картофеля, сладкого болгарского перца, моркови, обжарку из лука и томатов. Посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Затем добавить куриное мясо и сметану.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Массу взбить при помощи блендера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'Суп довести до кипения и поварить минуту или две.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9863,'При подаче посыпать кушанье рубленой петрушкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Грибы промыть, обсушить и мелко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Репчатый лук очистить и покрошить, жарить на сливочном масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Добавить грибы, все вместе пассеровать еще пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Сварить куриный бульон, влить в кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Добавить лук с грибами, все вместе варить в течение двадцати минут, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Перелить суп в чашу блендера, измельчить содержимое в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Вернуть массу в кастрюлю, довести до кипения, посолить и поперчить, влить сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9864,'Суп помешивать, прогревать еще около десяти минут. Огонь погасить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9865,'Порезать грудку, обжарить с «чесночным» маслом, солью, перцем чили и карри, переложить на салфетки из бумаги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9865,'Обжарить в подсоленном «чесночном» масле крупные кубики хлеба, переложить на салфетку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9865,'Нашинковать очень тоненько капусту, нарезать помидор на средние кубики, огурец и сладкий перец – соломкой. Измельчить морковку на «корейской» терке, лук нашинковать полукольцами, порубить мелко укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9865,'Объединить все овощные ингредиенты и добавить измельченные листья салата айсберг.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9865,'Всыпать в овощной салат с куриной грудкой и хлебом  гренки и мясо, чуть подсолить, заправить смесью сметаны, сырного соуса и майонеза, аккуратно перемешать. Переложить  в салатницу и присыпать жаренным кунжутным семенем или небольшим количеством тмина.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Довести воду до кипения, налить в миску, всыпать сушеные грибы, дать постоять около получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Разогреть в кастрюле растительное и сливочное масло, добавить репчатый лук, чеснок, зерна горчицы, прогревать до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Добавить свежие грибы, жарить до испарения сока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Сушеные грибы отцедить, мелко нарезать, воду не выливать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Положить в кастрюлю с куриным бульоном картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Влить воду от замачивания грибов, сами грибы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Варить до готовности картофеля.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Слить стакан жидкости, влить сливки и взбить блендером.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Влить обратно в кастрюлю.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Духовой шкаф разогреть до 180 градусов, противень смазать растительным маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'Выложить кубики белого хлеба, посолить, отправить в духовку, дать подрумяниться. Остудить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9866,'В готовый суп при подаче положить гренки и петрушку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9867,'Свежие белые грибы вымыть, почистить, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9867,'Порубить репчатый лук и морковь, нарезать картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9867,'Налить воду в кастрюлю, добавить грибы, варить до полной готовности. Суп посолить, добавить овощную смесь, прогревать до мягкости. Поперчить, грибы и овощи вытащить, положить в чашу блендера, измельчить. Добавить зелень, влить сливки, взбить еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Мелко порубить репчатый лук и чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Растопить в кастрюле сливочное масло, жарить лук в течение пяти минут, помешивать, огонь – средний.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Положить в кастрюлю свежие белые грибы, прогревать еще пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Влить куриный бульон, добавить веточки тимьяна, довести до кипения, варить двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9868,'Снять суп с огня, перелить в чашу блендера, измельчить в пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Отвар процедить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Ножки выложить в кастрюлю с водой, отварить, при готовности добавить мирпуа, тимьян и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Пластинки шляпок обжарить на оливковом масле в течение пятнадцати минут, посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Полученную жидкость добавить в бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'За десять минут до готовности грибного супа переложить в него обжарку, тимьян и чеснок удалить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Растопить сливочное масло, всыпать муку, жарить на тихом огне три минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Влить стакан грибного бульона, прогревать семь минут, помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Суп и заправку с мукой перелить в блендер, взбить до однородного состояния, вернуть в кастрюлю, довести до кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Соль и перец – по вкусу, влить сливки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Снять с огня.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9869,'Оставленные грибы тонко нарезать, обжарить и украсить суп в тарелках.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Шампиньоны измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Нашинковать репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Разогреть растительное масло на сковороде, выложить продукты, жарить в течение семи минут до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Филе курицы отварить, нарезать тонкими полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Маринованные огурцы нарезать дольками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Потереть сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Все ингредиенты перемешать, заправить сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Соль и перец молотый – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9870,'Еще раз перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9871,'Колбасный копченый сыр натереть, половину массы насыпать на блюдо ровным слоем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9871,'Крабовые палочки потереть, выложить, посыпать сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9871,'Пропустить через пресс чеснок, смешать с майонезом, намазать на сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9871,'Следующий слой – тертые отваренные яйца, сыр, майонез с чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9871,'Сверху – чипсы с сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9872,'Порезать филе на кусочки, чуть присолить, окропить соком половинки лимона. Измельчить чеснок и зелень с базиликом, порезать мелко помидоры, смешать все с тертым сыром (часть оставить) и майонезом. Включить на разогрев духовку (температура должна быть чуть меньше 200 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9872,'Смазать кусочки рыбы этой смесью, переложить на противень, смазанный маслом, присыпать верх оставшимся сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9872,'Запекать рыбу по-гречески с базиликом полчаса в разогретой духовке, подавать блюдо лучше горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Нарезать сладкий болгарский перец мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Очистить свежие огурцы, мякоть нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Томаты нарезать дольками, сыр – кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Порезать оливки и порубить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Перемешать оливковое масло с соевым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9873,'Залить овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Отварить рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Малосольную семгу нарезать тонкими ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Отварить и натереть яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Зелень нашинковать, можно использовать лук и кинзу, петрушку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Рис выложить на блюдо, намазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Следующий слой – рыба, майонез.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9874,'Далее – кусочки сыра, зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Нарезать кубиками маринованные огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Отварить, очистить, измельчить яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Сыр нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Зеленый лук нашинковать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Ингредиенты перемешать, полить майонезом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9875,'Добавить «Кириешки» и сразу подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9876,'Натереть морковь и сыр, порубить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9876,'Продукты перемешать, заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Воду довести до кипения, выложить кальмары, через семь минут жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Остывшие морепродукты нарезать мелкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Порубить заранее отваренные лесные грибы, перемешать с кальмарами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Очистить чеснок, измельчить, так же поступить с грецкими орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Сыр натереть на мелкой терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9877,'Ингредиенты перемешать, полить смесью сметаны и майонеза. Еще раз перемешать. Соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Сыр нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Сухую колбасу – кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9878,'Яйца отварить и нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9880,'Подготовить креветки: помыть, почистить, обсушить. В лоток влить масло, сок лимона, добавить мед, приправить перцем, солью, перемешать, залить этой смесью креветки, оставить стоять в маринаде на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9880,'Вынуть креветки, обсушить бумажными салфетками. Разогреть в сковороде масло, обжарить маринованные креветки по несколько минут с каждой стороны. Обжаривать надо до тех пор, пока креветки не утратят прозрачность. Вынуть их из сковороды и переложить в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9880,'Смешать нарезанный чеснок с маслом, дать постоять часа два-три. Слить масло, нагреть и зажарить на нем кубики хлеба, переложить на противень, присыпать специями и солью, отправить для подсыхания на несколько минут в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9880,'Для соуса взбить яйца, сок лимона, горчицу, растительное и оливковое масло. Добавить анчоусы, вустерский соус, сдобрить молотым перцем и солью, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9880,'Порвать салат ромэн на кусочки, переложить в миску, залить небольшим количеством соуса, перемешать. Натереть блюдо чесноком, разложить слой салата, положить на него гренки, присыпать сыром, сверху выложить креветки, полить соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9881,'Отрезать квадратный кусок пищевой пленки, смазать растительным маслом, положить на пиалу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9881,'Сырое куриное яйцо осторожно вбить на пленку, концы собрать, скрутить, завязать в узел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9881,'Воду в кастрюле довести до среднего кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9881,'Опустить яйцо в пленке, прогревать три или четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9881,'Яйцо вынуть, пленку снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9882,'Формочки смазать растительным маслом, вбить по яйцу, делать это нужно так, чтобы не растекся желток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9882,'Прикрыть фольгой, чтобы не падал конденсат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9882,'Вскипятить воду, влить в мультиварку, установить решетку для приготовления продуктов на пару.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9882,'Поставить формы, выставить режим «Варка на пару» на три или четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9882,'Готовые яйца вынуть, осторожно переложить на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'В жаропрочную посуду небольшого диаметра поместить сырые куриные желтки, налить винный или бальзамический уксус, поставить смесь на водяную баню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'Массу быстро взбивать венчиком в пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'Частями ввести топленое сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'Смесь по густоте должна напоминать майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'Добавить соль, перец, лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9883,'Приготовить бутерброды, полить соусом, украсить листочками зелени.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Отварить яйца в «мешочке» любым способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Раскалить сковороду, обжарить бекон до корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Хлебную булочку разрезать пополам вдоль, обжарить на той же сковороде, где готовился бекон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Смазать голландским соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Выложить по кусочку бекона, по два яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9884,'Бутерброд полить сверху оставшимся соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9885,'На обычной или сковороде гриль кусочки хлеба подрумянить с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9885,'Измельчить чеснок, прогреть вместе с листьями шпината с добавлением оливкового масла в течение полуминуты на раскаленной сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9885,'На хлеб выложить шпинат, сверху – тонко нарезанная копченая рыба, яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9885,'Полить голландским соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9885,'Соль и молотый черный перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Натереть сыр на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Натереть яйца на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Слить жидкость из банки с консервированными ананасами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Фрукт нарезать мелкими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Порубить очищенный чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9886,'Продукты перемешать, посолить по вкусу и заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9887,'Измельчить на терке картофель, отжать лишнюю жидкость, вбить яйцо, добавить фарш, сдобрить молотым перцем, присолить, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9887,'Взбить четверть стакана молока с тремя яйцами, всыпать измельченную зелень, приготовить омлет, разрезать на полосы и свернуть каждую рулетиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9887,'Сформовать из картофельного фарша шарик, приплюснуть в лепешку, положить сверху омлет или жареные грибы с луком, хорошо залепить края, обвалять в муке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9887,'Разогреть сковороду, обжарить зразы в сырно-чесночном соусе до красивого колера. Переложить на противень, полить сметаной с натертым сыром и измельченным чесноком, поставить зарумяниваться в нагретую духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Любой хлеб с плотным мякишем нарезать, намазать майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'По желанию можно добавить столовую горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Припустить свежую семгу, нарезать, уложить сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Для отваривания стейка понадобится лавровый лист, соль, перец-горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Довести воду до кипения, варить рыбу две или три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Далее семгу остудить, руками разобрать на пластинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Следующий слой – долька помидора, кусочек сыра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Гриль разогреть до 150 градусов, выложить бутерброды, прогревать от семи до десяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9888,'Другой способ приготовления – в микроволновой печи или в разогретой духовке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9889,'Мягкое сливочное масло перемешать с творожным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9889,'Смесью намазать ломтики любого хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9889,'Выложить красную икру на половинку бутерброда, на вторую – ломтик лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9889,'Сверху – тонко нарезанная рыба, скрученная в маленький рулет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9889,'Готовую закуску украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9890,'Для приготовления бутербродов понадобится белый хлеб, можно с добавлением семечек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9890,'Продукт нарезать, подрумянить в тостере или в электрогриле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9890,'Намазать сливочным сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9890,'Сверху – ломтики соленой или копченой семги, веточка укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9891,'Включить на разогрев (примерно до 200 градусов) духовку. Для основы покрошить печенье, смешать с мягким маслом. Форму застелить пергаментом, смазать маслом, переложить смесь, прикрыть пленкой и утрамбовать руками. Выпекать корж около 12 минут, достать, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9891,'Протереть творог до однородного состояния, переложить в чашу миксера, добавить муку, сметану, чуть присолить, всыпать сахар, ванилин, взбить до однородности. Всыпать крошку из шоколадного печенья, вбить яйца, перемешать, вылить на холодную основу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9891,'Выпекать аппетитный чизкейк с шоколадным печеньем примерно час при температуре около 150 градусов. Готовый десерт остудить и отправить ночевать в холодильник. Но можно подать и через пару часов охлаждения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Ломтики белого или серого хлеба подрумянить и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Приготовить смесь из размятого спелого авокадо, укропа, петрушки, любой другой зелени, перца, помидора.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Массу заправить лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Готовую сальсу можно посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Намазать бутерброды, сверху положить по кусочку соленой семги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9892,'Украсить тонкими ломтиками помидора или веточками рукколы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9893,'Белый хлеб нарезать ломтиками, намазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9893,'Нарезать копченую семгу, уложить сверху на ломтик свежего огурца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9893,'Порубить зелень укропа и петрушки, посыпать сверху.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9894,'леб нарезать ломтиками и подсушить в тостере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9894,'Намазать творожный сыр без вкусовых добавок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9894,'Положить по листочку салата «Айсберг», сверху – копченую семгу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9895,'Белый батон нарезать ломтиками толщиной в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9895,'Смазать мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9895,'Выложить красную икру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9895,'Украсить веточками петрушки, укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Перемешать сметану с рубленой зеленью',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Смесью намазать ломтики хлеба темных сортов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Сверху выложить икру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Отварить перепелиные яйца, очистить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Натереть на терке или порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9896,'Посыпать бутерброды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Измельченная соленая семга, дижонская горчица, майонез, рубленый зеленый лук, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Второй способ: сливочный сыр, соленая рыба, зелень укропа и нарезанные вяленые томаты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Третий рецепт: каперсы, шнитт-лук, любая рыба холодного копчения с творожным кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Острый вариант: взбитое мягкое сливочное масло, нарезанный лук-порей, жгучий перец, рыба горячего копчения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Рецепт с орехами: сливки средней жирности, отваренная семга, жареный миндаль или фисташки, пассерованный репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9897,'Вариант с помидорами: соленая семга, стеблевой сельдерей, помидоры, зелень, репчатый лук, сок лимона и рафинированное растительное масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9898,'Порезать на небольшие кубики масло, порубить в крупную крошку с просеянной мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9898,'Смешать в глубокой миске сахар, яичные желтки, сметану, подсолить, объединить с крошкой, перемешать до однородности, обернуть тесто пленкой, поставить на час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9898,'Подготовить яблоки (кисло-сладкие) для начинки: почистить, удалить сердцевину и косточки. Порезать на кубики, посыпать смесью обычного и ванильного сахара, перемешать, высыпать в сухую  сковороду и потушить до мягкости около 10 минут (следить, чтобы не получилась каша), всыпать муку, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9898,'Включить прогреться духовку до 180 градусов, подготовить форму для выпечки. Достать тесто, отделить небольшой кусочек (размером чуть больше теннисного мячика). Основную часть раскатать по размерам формы с небольшим запасом для формирования бортика в 3-4 см, проколоть тесто в нескольких местах вилкой, отправить минут на 12-13 в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9898,'Готовую основу наполнить начинкой, слой разровнять и утрамбовать. Раскатать вторую часть теста, нарезать на полоски, разложить вплотную одна к другой по поверхности классической польской шарлотки с яблоками, отправить десерт минут на 35 в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9899,'Хлеб нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9899,'Намазать сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9899,'Выложить икру и украсить листочками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9900,'Плавленый сыр со вкусом трав смешать с измельченным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9900,'Смесью намазать темный хлеб.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9900,'Второй слой – икра, сверху – помидоры и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9901,'Хлебцы с отрубями смазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9901,'Сверху выложить ломтики мякоти авокадо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9901,'Далее – икра горкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9901,'Украсить зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9902,'Перемешать мягкое сливочное масло с отваренным и растертым яичным желтком, перцем и чесночным порошком. Масса должна получиться однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9902,'Смазать ломтики серого хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9902,'Выложить икру тонким слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9902,'Украсить зеленью и красиво нарезанными ломтиками свежего огурца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Сливочное масло комнатной температуры соединить с охлажденной сметаной, ингредиенты перемешать при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Просеять вместе с разрыхлителем муку, соединить с массой, перемешивать в течение трех минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Скатать тесто в шар, завернуть в пищевую пленку, положит на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Разделить тесто на шесть равных частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Раскатать каждую в круг, оставить на десять минут, затем разрезать на треугольники от центра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'На широкую сторону положить немного любимого густого варенья, тесто свернуть в рогалик.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Посыпать сахарным песком или пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Положить на противень, заранее застеленный пергаментом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9903,'Время выпекания – от десяти до пятнадцати минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9904,'В чашу блендера положить маргарин, нарезанный кусочками, сметану, взбить до однородного состояния. Продукты должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9904,'Всыпать просеянную муку, быстро, в течение нескольких минут, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9904,'Разрезать тесто на шесть частей, раскатать круглые лепешки, нарезать треугольники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9904,'Выложить варенье, скрутить рогалики, выпечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9904,'Готовые рогалики посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Вбить в чашу миксера сырое куриное яйцо, влить растопленное сливочное масло или маргарин, сметану. Ингредиенты взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Всыпать муку с пищевой содой, вымешать тесто. Оно должно быть в меру мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9905,'Очистить и измельчить грецкие орехи, смешать с сахаром, имбирем, кардамоном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9906,'Маргарин измельчить в крошку, вбить сырое куриное яйцо, всыпать сахар, добавить сметану. Смесь взбить при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9906,'Всыпать муку в несколько приемов, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9906,'Раскатать лепешки, нарезать треугольники, завернуть повидло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9906,'Время выпекания – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9906,'Выпечку посыпать пудрой, подать с горячим чаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'Сметану смешать с яйцом, сахарным песком, натуральным медом, солью. Перемешать продукты можно при помощи обычного венчика или миксером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'Всыпать смесь муки с разрыхлителем, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'Сформовать заготовки в виде небольших треугольников, свернуть рогалики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'Начинка – любая, удобно использовать густой джем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'Выложить порции на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9907,'По желанию посыпать молотой корицей, температура выпекания – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'К мягкому сливочному маслу добавить ванильный и обычный сахар, влить сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Продукты взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Вбить сырое куриное яйцо, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Ввести муку порциями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Раскатать круг, нарезать треугольники то центра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Выложить корицу с сахаром, свернуть рогалики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Выложить на противень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Лист заранее застелить пергаментом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9908,'Печь при температуре 200 градусов. Должна получиться золотистая корочка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Подогреть воду, всыпать сухие дрожжи, размешать, добавить сахар и немного соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Через десять или пятнадцать минут вбить сырые куриные яйца, добавить сметану, перемешать ингредиенты при помощи венчика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Всыпать муку, тесто поставить на час в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Для приготовления начинки смешать творог, яйца, сахар и ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Из подошедшего теста сформовать треугольники, выложить начинку, скрутить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Смазать изделия взбитым яйцом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9909,'Печь в течение 25 минут при температуре 190 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Отварить куриные яйца в подсоленной воде, остудить, накрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Открыть банку с консервированной кукурузой, слить жидкость, зерна высыпать в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Нарезать крабовые палочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Натереть сыр на крупной терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Пропустить через пресс чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Ингредиенты перемешать, заправить по вкусу майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9910,'Перед подачей положить сухарики, посыпать салат зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Грибы отварить до готовности, нарезать кусочками, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Репчатый лук нарезать кубиками, пересыпать в грибную обжарку, все вместе потушить под крышкой в течение четверти часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Продукты переложить в салатницу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Всыпать зерна консервированной кукурузы, тертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Все перемешать, посолить по вкусу и заправить смесью сметаны и майонеза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9911,'Перед подачей добавить кириешки и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9912,'Из всех ингредиентов замесить тесто, прикрыть тканью, дать постоять минут 40, разделить на порционные шарики, сформовать из каждого основу для ватрушки. Разложить заготовки на противень, смазать яичным желтком, взбитым с небольшим количеством воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9912,'Объединить нарезанные ингредиенты начинки, перемешать с яичным белком, разложить по кружочкам основы, посыпать остренькие ватрушки с колбасой сырной стружкой, отправить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Поставить на тарелку разъемную форму или кольцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Нарезать копченую колбасу брусками, выложить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Второй слой – зеленый лук, намазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Следующий слой – сухари и майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Четвертый слой – консервированная фасоль, майонез с тертым чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Далее – тертый сыр, заправка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'В конце выложить отваренные и натертые яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9913,'Кольцо убрать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9914,'Свежий огурец вымыть, нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9914,'Слить жидкость от кукурузы, выложить к огурцу вместе с консервированной красной фасолью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9914,'Продукты посолить по вкусу и заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9914,'Перед подачей посыпать салат сухарями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9915,'епчатый лук измельчить, перемешать с морковью по-корейски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9915,'Копченую куриную грудку нарезать кубиками, добавить к овощам вместе с кукурузой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9915,'Салат заправить майонезом и посыпать кириешками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9916,'Курицу отварить в течение получаса в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9916,'Порезать кубиками, переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9916,'Добавить консервированную фасоль и кукурузу, жидкость отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9916,'Салат посолить, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9916,'Посыпать зеленью и кириешками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Дрожжи растереть с солью и сахаром, разбавить теплым молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Всыпать просеянную муку через десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Два яйца взболтать, добавить в основной состав.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Влить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Замесить мягкое тесто в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Накрыть пленкой, убрать в тепло на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Варить рис в течение 20 минут, яйца – около десяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Рис остудить, посолить, поперчить, добавить зелень, лук и рубленые яйца, сливочное масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Тесто нарезать кусками, раскатать лепешки, положить начинку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Сформовать пирожки, уложить на противень швом вниз, оставить на 15 или 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Смазать немного взбитым желтком, посыпать кунжутными семечками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9917,'Поставить в духовку. Время выпекания – от 17 до 20 минут, температура – 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9918,'Измельчить на терке (крупной) в отдельные емкости морковку и сыр, тонко нашинковать сочную луковицу и капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9918,'Фарш сдобрить молотым перцем, подсолить, поджарить в небольшом количестве разогретого масла около 6-7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9918,'Потушить на среднем огне капусту минут 7, подсолить, добавить пассировку из морковки и лука, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9918,'Подготовить форму, выложить половину капусты, разровнять, промазать верх сметаной, выложить фарш, прикрыть капустой, еще раз промазать сметаной, присыпать сырной стружкой, убрать форму в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9918,'Блюдо готовить при 200 градусах, капустная запеканка с фаршем в сметане будет готова через 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9919,'Измельчить для основы печенье до состояния крошки, распустить масло, перемешать с крошкой и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9919,'Довести температуру духовки до 160 градусов, подготовить формочки для выпечки. Взбить сахар и мягкий сыр, всыпать ванильный сахар, чуть подсолить, смешать до однородности, вбить по одному яйца, перемешивая смесь после каждого.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9919,'Заполнить формочки маслянистой крошкой, на основу выложить сырную начинку. Приготовить в блендере пюре из сахара и клубники, нанести небольшое количество поверх начинки, а кончиком зубочистки нарисовать произвольные разводы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9919,'Поставить формочки в прогретую духовку, капкейки – чизкейки с клубникой будут готовы через 25 минут. Достать готовый десерт, дать остыть, окончательно остудить перед подачей в холодильнике не менее 4 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9920,'Подготовить форму для выпечки, смазать маслом, включить на разогрев до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9920,'Для начинки проварить мак около 5 минут, оставить на треть часа под крышкой для набухания, сцедить лишнюю жидкость, откинув массу на сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9920,'Отделить желтки, взбить до однородности с маслом и сахаром, соединить с маком, мукой и разрыхлителем, хорошо размешать. Если есть, то можно всыпать дробленый орех с изюмом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9920,'Белки взбить в устойчивую пену, аккуратно соединить с тестом, переложить массу в форму, маковник классический будет готов минут через 30-40, дать десерту остыть, подать к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9921,'Высыпать в сотейник какао и сахар, перемешать, залить молоком, довести при среднем нагреве и помешивании почти до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9921,'Измельчить шоколад, высыпать в разогретое какао, перемешать до полного растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Язык промыть, очистить при помощи ножа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9921,'Разлить готовый ароматный и легкий горячий шоколад по широким стаканам, подать десерт к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9922,'Прогреть до 200 градусов духовку, подготовить стеклянную форму, смазать маслом. В глубокую миску вбить яйца, влить молоко, чуть присолить, хорошо перемешать, но не взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9922,'Вылить яичную смесь в форму, установить ее в глубокую металлическую форму, налить в нее воду, поставить в горячую духовку. Пышный омлет на молоке будет готов через полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9922,'Вынуть стеклянную форму, положить наверх омлета небольшие кубики масла и на 3-5 минут убрать в духовку. В этом случае поверхность омлета будет красивого желто-янтарного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9923,'Очистить молодой корешок имбиря, порезать очень тонкой соломкой. Смешать и растолочь все специи (кроме кориандра, чили, куркумы). Высыпать специи в разогретую сковороду, добавить имбирь, сахар, залить 4 стаканами воды, нагревать до тех пор, пока останется примерно пару стаканов, жидкость сцедить и оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9923,'Нагреть в глубокой сковороде масло, всыпать куркуму, подсолить, перемешать, обжарить ножки курицы до красивого золотистого колера. Влить к мясу сок от специй, добавить сок от одного лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9923,'Прикрыть сковороду крышкой, тушить мясо до мягкости. Измельчить перец чили и зелень кинзы, всыпать к мясу, перемешать, убрать с плиты. Подавать куриные ножки с имбирем и кориандром горячими с обжаренным рисом, полить соусом от тушения мяса и специй.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Отварить рис до состояния рассыпчатости. Лучший вариант – взять крупу в пакетах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Отварить куриные яйца, покрошить кубиками, соединить с остывшим рисом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Всыпать измельченный зеленый лук, пряные травы, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Всыпать пищевую соду и сахарный песок в кефир комнатной температуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Вбить сырые яйца, всыпать муку и влить растительное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Продукты перемешать, комочки разбить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Сформовать лепешки, положить начинку, залепить края.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9924,'Пирожки жарить на сковороде в кипящем масле, с двух сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9925,'Подготовить мясо, порезать, отбить, прикрыв пленкой, переложить на противень, сдобрить специями и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9925,'Очистить помидоры от шкурки, порезать на кружочки, выложить на куски мяса, присыпать частью сырной стружки (примерно третью).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9925,'Поверх сыра выложить грибы, полить майонезом, присолить, присыпать оставшимся сыром. Поместить противень в разогретую до 200 градусов духовку, свинина с грибами по-купечески будет готова через треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9926,'Обжарить курицу в соусе','https://vkuso.ru/data/cache/data/09/67cfbcb74a74009_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9926,'Отварить спагетти','https://vkuso.ru/data/cache/data/95/671b8536749fb95_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9926,'Выложить отваренные спагетти в сковороду и на 10 минуток под крышку.','https://vkuso.ru/data/cache/data/90/c631deaf1054590_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Морковь с луком обжарить на растительном масле до готовности.','https://vkuso.ru/data/cache/data/99/d589e9a63796e99_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Картофель размять.','https://vkuso.ru/data/cache/data/c3/5d335d4bae097c3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Смешать картофель с растопленным сливочным маслом, яйцами, сыром и морковью. Добавить немного молока.','https://vkuso.ru/data/cache/data/0a/a3bf360f5ec1d0a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Намазываем на лаваш тонким слоем. Сверху кладем второй лаваш и также намазываем картофелем. И так все 4 лаваша.','https://vkuso.ru/data/cache/data/38/deea3639259c738_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Лаваш скрутить рулетом. Разрезать пополам.','https://vkuso.ru/data/cache/data/ba/087baa9db4f0eba_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Обернуть в пищевую пленку. В холодильник на 30 минут.','https://vkuso.ru/data/cache/data/8a/d553ef68a932d8a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Разрезаем на рулетики.','https://vkuso.ru/data/cache/data/c0/d4bc790cdf287c0_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'В духовку на 15 минут при температуре 180 градусов.','https://vkuso.ru/data/cache/data/64/8833dd4180a4d64_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9927,'Приятного аппетита.','https://vkuso.ru/data/cache/data/7f/4a22708139b6c7f_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9928,'Подготовить помидоры, разрезать на половинки, уложить в форму, побрызгать маслом, присыпать смесью пряных трав, отправить в нагретую чуть ниже 190 градусов духовку примерно на треть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9928,'Размять вилкой до состояния пасты сыр со сметаной, подсолить, можно добавить по вкусу измельченную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9928,'Нарезать багет на одинаковые ломти, смазать сырной пастой, выложить поверх нее помидоры. Сбрызнуть гренки с запеченными помидорами и сыром маслом, оформить веточками зелени или базилика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'В теплом молоке развести сахар, соль, дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Добавить топленое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Всыпать муку небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Замесить тесто, дать постоять 40 минут в тепле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Отварить рис и яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Добавить рубленый зеленый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Готовую начинку посолить по вкусу, положить майонез, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9929,'Сформовать пирожки, обжарить до румянца с каждой стороны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Охлажденное сливочное масло настрогать ножом, соединить с мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'В получившуюся крошку добавить соль и ледяную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Быстро замесить тесто, завернуть в пищевую пленку, убрать на час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Массу очень тонко раскатать на доске, положить немного масла, свернуть конвертом, еще раз раскатать, процедуру повторить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Заготовку еще раз раскатать и убрать в холод на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Процесс повторить два раза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Для приготовления начинки отварить рис, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Отварить и порубить яйца, зеленый лук нарезать колечками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Все перемешать и посолить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Слоеное тесто тонко раскатать, разрезать квадратами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Сырое яйцо взболтать и смазать им квадраты.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'В середину положить начинку, сформовать конвертики.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9930,'Выложить изделия на противень, смазать яйцом, печь в течение 25 минут при температуре 200 градусов. Должна получиться румяная корочка.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Молоко прогреть, развести в нем сахар, быстродействующие дрожжи, соль, муку. Должно получиться полужидкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Накрыть массу тканью, поставить в тепло на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'В получившуюся опару добавить растопленное сливочное масло, яйца, остатки муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Быстро, в течение 15 минут, замесить тесто. Поставить его в тепло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Отварить яйца и мелко покрошить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Отварить рис до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Измельчить репчатый лук, обжарить в масле до прозрачности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Добавить нарезанную отварную говядину, соль, рис, молотый перец, жарить семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Влить мясной бульон, положить пропущенный через пресс чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Добавить яйца, перемешать и остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Тесто разделить на кусочки, раскатать, оставить на десять минут для расстойки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Разложить начинку, скрепить края.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9931,'Время выпекания – 25 минут, температура – 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Отварить рис и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Оставшиеся яйца взбить с сахарным песком, творогом, солью, мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Муку перемешать с разрыхлителем, просеять, добавить в основную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Замесить крутое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Порубить яйца, смешать их с рисом, луком, маслом и солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Сформовать пирожки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9932,'Печь в течение 20 минут при температуре 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Пекарские дрожжи размешать в подогретой воде, всыпать соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Добавить мягкий маргарин, просеянную муку, взбитое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Замесить тесто и убрать его на час в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Отварить и остудить рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Репчатый лук нарезать, обжарить в масле, перемешать с рисом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Грибы мелко нарезать, добавить в рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Вбить сырое яйцо для связывания, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9933,'Сформовать пирожки и обжарить с двух сторон на масле до румяной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9934,'Распустить в кастрюле с толстым дном масло, добавить порезанные овощи, подсолить, тушить 10 минут под закрытой крышкой. Всыпать муку, размешать до однородности, влить сидр (постоянно помешивая).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9934,'В кастрюлю с овощами добавить бульон, закрыть крышку, сделать слабый нагрев, готовить полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Блюдо снять с огня, дать постоять.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9934,'Перемешать кубики хлеба с оливковым маслом, всыпать пармезан, запечь в духовке 8-10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9934,'Добавить в суп молоко, сыр стилтон, нагревать до полного расплавления сыра, приправить молотым перцем, присолить, влить сливки (не давать кипеть!).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9934,'Если суп из сыра стилтон с пармезаном и гренками  взбить блендером, то получится нежный суп-пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Сварить бульон из филе и обрезков (головы, хвосты).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Добавить лавровый лист, душистый перец, морковь, зеленую фасоль, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Варить полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'В конце приготовления влить водку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Рыбу, морковь и фасоль вытащить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Морковь нарезать любыми фигурками, осетра – кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Отвар процедить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'В посуду для заливного выложить филе и все остальные ингредиенты в произвольном порядке, залить бульоном.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9935,'Оставить в холоде для застывания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Тушку красной рыбы очистить и нарезать порционно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Филе, голову и хвост залить водой, добавить головку лука, морковь, гвоздику, перец, лавровый лист, зелень – по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Варить в течение часа, добавить лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Рыбу вытащить, голову и кости удалить, мясо порезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Бульон процедить, разделить на части, в первую влить сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'В тарелку для заливного выложить рыбу, залить бульоном со сливками и дать застыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Отварить яйца и морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9936,'Нарезать соломкой. Выложить оба продукта на застывший слой, залить второй частью бульона. Перенести тарелку в прохладное место.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Рыбное филе очистить, филе отделить от костей, положить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Из рыбных остатков сварить бульон с добавлением сладкой моркови, репчатого лука, лаврового листа, перца-горошка, гвоздики, соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Время варки – один час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Отвар процедить, положить в него филе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'В небольшом количестве готового бульона развести желатин, влить к остальным ингредиентам, варить полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Филе вытащить, нарезать, выложить в тарелку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9937,'Украсить красиво нарезанной морковью, залить отваром и охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Судака очистить, отделить жабры, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Залить водой, бульон варить с корнем петрушки и моркови, специями, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Готовый отвар процедить, мясо отделить от костей и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Выложить в тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Морковь нарезать звездочками, украсить рыбу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'В небольшом количестве бульона растворить желатин, влить в бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Кастрюлю нагреть, влить сок лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'Рыбу залить отваром, охладить до застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9938,'При подаче блюдо украсить зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Щуку очистить, сварить бульон из хвоста и головы в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Отвар процедить, добавить нарезанное филе, целую луковицу, морковь, специи, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Варить еще полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'В небольшом количестве отвара развести желатин из пакетика, влить оставшийся бульон, варить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Отварить, очистить, крупно нарезать куриные яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Отвар процедить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'На дно тарелки выложить щуку, красиво нарезанную морковь, яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9939,'Продукты залить бульоном, поставить в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Карпа очистить, нарезать порциями, отделить хвосты и головы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Все вместе переложить в кастрюлю, залить водой, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Добавить перец и лавровый лист, лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Варить в течение часа, затем влить уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Рыбу вытащить, удалить кости, мясо нарезать кусочками произвольной формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Отлить часть отвара, растворить желатин, влить обратно в кастрюлю, варить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'На прозрачную тарелку выложить кусочки филе, кружочки отваренной моркови.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9940,'Продукты залить бульоном, поставить в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'На тарелку выложить филе, листья петрушки и нарезанную морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9941,'Залить бульоном, выставить в холод до застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Треску очистить и нарезать порциями, головы и хвосты не выбрасывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Рыбу залить водой, положить лук и морковь, специи, варить в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Затем долить в кастрюлю лимонный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Бульон процедить, головы и хвосты удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Филе поделить на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Жидкость поделить пополам, в одну половину влить сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Рыбу выложить в тарелку, залить бульоном со сливками, поставить в холод для застывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Отварить яйца, нарезать соломкой или кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Точно так же нарезать морковь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9942,'Продукты выложить на застывшую массу, залить оставшимся прозрачным бульоном, поставить в холод.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Форель очистить, отделить жабры, филе нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Приготовить отвар с луком-репкой, морковью, корнем петрушки, специями, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Время варки – один час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Бульон процедить, мясо отделить от костей, нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Выложить в тарелку, украсить морковью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Отлить немного бульона, растворить желатин, перемешать с остальным отваром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Прогреть, влить сок лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9943,'Филе-кусочки залить бульоном, поставить на холод для застывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Рыбу очистить, филе отделить от других частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Поставить охлаждаться, а из обрезков, специй, лука и моркови сварить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Время приготовления – один час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Бульон процедить, добавить филе, варить еще 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Отлить немного отвара, добавить желатин, размешать, влить обратно в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Продолжать варить бульон в течение 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Филе вынуть, нарезать порциями, выложить в тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9944,'Украсить морковью, залить отваром, поставить для застывания в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'Горбушу очистить, нарезать порциями, довести до кипения вместе с головой и хвостом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'Добавить лук и морковь, лавровый лист, перец, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'Все вместе варить полчаса, долить уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'Горбушу вытащить, обрезки выбросить, мясо разделать на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'Развести желатин в отваре, перемешать с остальными продуктами, варить 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9945,'На тарелки выложить кусочки филе, нарезанную морковь, залить бульоном и поставить для застывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9946,'Подготовить гречку: перебрать, промыть, обсушить, обжарить на разогретой сковороде минут 5-6. Довести до кипения 3 стакана воды, всыпать крупу, варить треть часа, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9946,'Нашинковать и обжарить часть лука до красивого соломенного цвета. Остальной лук с разогретым маслом довести до мягкости в сотейнике, добавить соломку из красного и желтого болгарского перца и морковки, тушить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9946,'Влить к томатной пасте стакан воды, размешать, соединить с овощами в сотейнике, сдобрить солью, сахаром, орегано, перемешать, нагревать 2-3 минуты, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9946,'Пропустить остывшую гречку с фаршем через мясорубку, размешать, вбить яйцо, добавить жареный лук, майонез, поперчить, подсолить, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9946,'Из этой массы сделать котлетки, зажарить минут по 7 с каждой стороны. Переложить гречаники с соусом из овощей и томатной пасты в форму, запечь при 185 градусах около 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Семгу очистить, жабры отделить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Филе нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Приготовить отвар с корнеплодами: морковью и петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Добавить специи',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Время варки – один час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Бульон процедить, филе отделить от костей, нарезать кусочками, выложить на тарелку и украсить нарезанной отваренной морковью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Растворить желатин в части бульона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Влить его в оставшуюся часть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Прогреть, добавить лимонный сок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9947,'Мясо залить бульоном, поставить для застывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Залить мясо холодной водой, довести до кипения, варить три или четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Поменять воду в кастрюле, варить язык три часа под крышкой с лавровым листом и перцем-горошком. Пену в процессе приготовления снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Лук и морковь очистить, добавить в бульон за полчаса до окончания варки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Язык вынуть, переложить в холодную воду, снять кожу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Бульон процедить, растворить в нем желатин, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Готовое мясо нарезать ломтиками средней толщины, разложить их в формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Украсить консервированным горошком, кусочками вареной моркови.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9948,'Налить в формочки бульон, поставить их в холод.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/b4/4c481ed5e311cb4_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Огурцы мелко порезать, посолить.','https://vkuso.ru/data/cache/data/3d/0928c258076a33d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Чернослив - мелко порезать.','https://vkuso.ru/data/cache/data/8d/007c0a0f6690d8d_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Куриное филе - мелко порезать.','https://vkuso.ru/data/cache/data/03/52ecc3eb970b403_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Орехи - измельчить.','https://vkuso.ru/data/cache/data/2c/270882d4b3f2a2c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Зелень - мелко порезать.','https://vkuso.ru/data/cache/data/8e/db7fc7f1b57538e_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Яйца соединить с солью и крахмалом. Размешать. Вылить на сухую сковороду. Жарить до готовности.','https://vkuso.ru/data/cache/data/fd/077f4bd1840a0fd_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Яичные блины свернуть в трубочку и мелко нарезать.','https://vkuso.ru/data/cache/data/e0/5d3c7f741343be0_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Соединяем все продукты.','https://vkuso.ru/data/cache/data/a4/051ef0f850f1ea4_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9949,'Украшаем зеленью и орехами. Приятного аппетита!','https://vkuso.ru/data/cache/data/1a/0c9d1b44328ee1a_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9950,'Обжарить фарш и специи до тех пор, пока мясо не подсохнет и не зарумянится, присыпать пармезаном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9950,'Нарезать мелко картошку, обжарить во фритюре, огурцы нарезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9950,'Раскатать тесто как для пельменей, уложить в форму, сформовать бортики. Уложит на тесто фарш, кусочки сыра для сэндвичей, жареную картошку, огурчики, полить майонезом, присыпать моцареллой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9950,'Закрыть слоеный пирог с сыром, фаршем и картофелем  фольгой, отправить в нагретую (185 градусов) духовку на треть часа. Фольгу удалить, снизит нагрев на 100 градусов, подержать пирог еще четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Репчатый лук нарезать на четвертинки, а затем полосками.','https:https://st.vkuso.ru/data/cache/thumb/3a/8267196d870253a_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Растопить сливочное масло на среднем огне.','https:https://st.vkuso.ru/data/cache/thumb/d0/f43d79f9aeef8d0_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Выложить лук, по желанию можно добавить рубленые стебли сельдерея.','https:https://st.vkuso.ru/data/cache/thumb/4b/9eacc59ae2ed14b_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Жарить до карамелизации, время – около 35 минут','https:https://st.vkuso.ru/data/cache/thumb/0c/bd28ae3c14af00c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Влить кипяток или бульон, куриный, овощной или говяжий.','https:https://st.vkuso.ru/data/cache/thumb/1d/96007b093e5531d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Прогревать, добавить листочки свежего или сушеного тимьяна.','https:https://st.vkuso.ru/data/cache/thumb/d3/64e528609e31cd3_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'После выпаривания жидкости добавить новую порцию.','https:https://st.vkuso.ru/data/cache/thumb/9a/8c05e8977d3429a_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Процесс повторить, влить оставшийся бульон. Должен получиться суп средней густоты.','https:https://st.vkuso.ru/data/cache/thumb/56/1c4e840e5023356_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Багет на ржаной муке нарезать по диагонали тонкими ломтиками. Варианты – брусочки, кубики.','https:https://st.vkuso.ru/data/cache/thumb/12/6f2d1ac7b2ed812_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Обжарить на сковороде или при помощи тостера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Перелить суп в тарелки или горшочки, посыпать тертым сыром «Пармезан» или «Грюйер».','https:https://st.vkuso.ru/data/cache/thumb/d2/fd19b6a57a477d2_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Выложить гренки.','https:https://st.vkuso.ru/data/cache/thumb/0d/bd61d581f95280d_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Сверху – еще одна порция тертого сыра.','https:https://st.vkuso.ru/data/cache/thumb/54/ce813c03e96d054_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Поставить в духовку, сыр должен расплавиться, температура приготовления – 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/08/36b3f37c1856108_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9951,'Вынуть, подать на стол.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Говядину на косточке промыть и отварить в подсоленной воде со специями до получения бульона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Лук очистить и нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Налить в сотейник с толстым дном растительное масло, положить кусочек сливочного.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Нагреть, переложить лук, пассеровать на тихом огне полчаса, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Влить бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Довести до кипения, варить под крышкой пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Подсушить хлеб, нарезанный кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9952,'Суп подать в тарелках, всыпать гренки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Белый репчатый лук очистить, нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Растопить сливочное масло в глубокой сковороде, выложить лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Время пассеровки – полчаса, продукт должен изменить цвет на золотистый.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Влить четверть объема заранее приготовленного говяжьего бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Массу выпаривать при постоянном помешивании.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Влить еще столько же жидкости, посолить, добавить листочки тимьяна.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'В третий раз влить оставшийся бульон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Ломтики багета подсушить без масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Довести суп до кипения, затем разлить в горшочки, положить по две гренки, посыпать тертым твердым сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9953,'Поставить в духовку на две минуты, температура – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Лук очистить, нарезать полукольцами, спассеровать на сливочном масле в течение десяти минут на тихом огне, восемь минут – на среднем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Для приготовления лучше использовать кастрюлю с толстым днем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Влить белое сухое вино, бульон, довести суп до кипения, посолить, поперчить, приправить листочками тимьяна. Варить 15 минут на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Сковороду смазать сливочным маслом, обжарить ломтики багета, выложить в суп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Натереть твердый сыр, насыпать на хлеб, отправить блюдо на три минут в духовой шкаф.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9954,'Разлить в тарелки, в каждой должен оказаться ломтик багета с сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Положить в глубокую сковороду сливочное масло, влить растительное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Нашинковать лук, обжарить в течение сорока минут, огонь – тихий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'За десять минут до конца варки добавить сахар, в самом конце ввести горчицу в зернах и муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Влить бульон, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Добавить перец и тимьян, суп довести до кипения, затем огонь уменьшить, потомить блюдо в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Нарезать багет ломтиками, посыпать тертым сыром, жарить две минуты на гриле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9955,'Разлить суп в тарелки, положить по два тоста на порцию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9956,'Поломать шоколад на куски, растопить вместе с маслом на водяной бане до однородной массы, отдельно смешать какао с мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9956,'Взбить пару яиц и пару столовых ложек сахара до светлого цвета, добавить масло с шоколадом и смесь какао, тщательно перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9956,'Смешать творог, банан, сахар, яйцо в однородную смесь. Уложить шоколадное тесто в форму, вылить на него бананово-творожную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9956,'Нарисовать на поверхности брауни-чизкейка шоколадно-бананового кончиком зубочистки произвольные линии. Убрать десерт в прогретую (185 градусов) духовку на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Лук очистить и нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Порубить зубчики чеснока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'То и другое обжарить на сливочном масле в кастрюле с толстым дном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Когда овощи приобретут золотистый оттенок – добавить муку, а через две минут влить сухое белое вино.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'После испарения жидкости влить бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Почти готовый суп перемешать, посолить по вкусу, добавить приправы, потомить полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Нарезать хлеб, выложить на противень, подсушить в духовке до золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9957,'Суп разлить в тарелки, добавить гренки и немного коньяка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9958,'Отварить мясо, остудить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9958,'Репчатый лук измельчить и залить кипящей водой для удаления горечи. Подлить столовый уксус, всыпать сахар, оставить для пропитывания на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9958,'Нарезать болгарский перец, очищенный чеснок и зелень. Ингредиенты перемешать, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9958,'Выложить массу на блюдо в виде свинки, покрыть дополнительной порцией майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Зеленое крупное яблоко, очистить, нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9958,'Украсить салат ветчиной и маринованными маслинами в виде глаз, ушек, пятачка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Твердый сыр натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Грецкие орехи измельчить при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Чернослив залить кипятком, распарить, нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Куриные яйца отварить до готовности и разделить на желтки и белки. То и другое натереть на терке отдельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Отваренное или копченое куриное филе нарезать кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Выложить салат послойно: курица, желтки, чернослив, сыр, орехи, белки. Продукты промазывать майонезом, сверху – белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9959,'Готовый салат украсить «ушками» и «пятачком» из ветчины, глаза – маслины.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9960,'Яйца отварить, нарезать кубиками вместе с отваренным картофелем и свежими огурцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9960,'Слить жидкость от зеленого горошка, добавить в общую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9960,'Новогодний салат заправить майонезом, выложить на тарелку в виде овала. Можно использовать форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9960,'Засыпать массу тертой колбасой (ветчиной), вырезать ушки, хвост, пятачок, сделать глаза из маслин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9961,'Нарезать небольшими кубиками ветчину, отварное куриное яйцо, твердый сыр, помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9961,'Ингредиенты перемешать, заправить майонезом по вкусу и выложить на блюдо в виде поросенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9961,'Из вареной колбасы вырезать хвостик, пятачок, ушки, глаза сделать из маслин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9962,'Отварить картофель, куриные яйца, желтки и белки разделить, и все натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9962,'Нарезать лук и спассеровать до прозрачности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9962,'Нарезать кубиками соленый огурец, консервированные шампиньоны – тонкими пластинками. Сыр натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9962,'Салат выложить на тарелку слоями, промазать майонезом. Последовательность слоев: лук, грибы, натертый картофель, огурец, желтки, белки, сыр. Салат должен постоять некоторое время для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9962,'Украсить черными маслинами и нарезанной ветчиной в виде поросенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9963,'Почистить картофель, нарезать на кружочки, нашинковать очень тоненько лук, обвалять в муке, обжарить на горячем масле, отдельно обжарить пластинки грибов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9963,'Переложить картофель на дно формы, объединить с грибами, луком, сметаной и специями, перемешать. Запекать в духовке при температуре 180 градусов. Картофель запеченный с шампиньонами в сметане будет готов в течение 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9963,'Прекрасно дополнят блюдо помидоры домашнего посола.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9964,'Измельчить лук и чеснок, пересыпать в чашу мультиварки, залить оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9964,'Выставить режим «Тушение», прогревать до получения золотистого цвета. Обжарку помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9964,'Всыпать муку, перемешать, влить бульон, добавить специи, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9964,'Выставить режим «Суп» до закипания, а затем «Подогрев» на сорок минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9964,'Обжарить гренки на сковороде, натереть чесноком и посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Измельчить лук, спассеровать на растительном масле в кастрюле до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Всыпать муку, специи, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Обжарку перемешать, влить бульон, через полчаса добавить плавленый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Суп варить до растворения сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Превратить смесь в пюре при помощи погружного блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9965,'Чеснок обжарить отдельно, на полученном чесночном масле прогреть хлебные кубики. Подать к супу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Мясо промыть, нарезать брусками, жарить в течение десяти минут на сковороде с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Добавить стручковую фасоль, соль, тушить шесть или семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Свежие огурцы и помидоры вымыть, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Желтый болгарский перец очистить от семенных камер, нарезать полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Переложить овощи в чашу, добавить измельченную зелень и листья салата, порванные руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Продукты перемешать, посолить по вкусу, поперчить и полить оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9966,'Подать порционно: разложить в тарелки овощи, сверху – фасоль с мясом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Филе индейки промыть, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Переложить на сковороду с растительным маслом, посолить, посыпать приправами, жарить до изменения цвета. Лучше использовать морскую соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Шампиньоны промыть, нарезать пластинками, обжарить до готовности в отдельной посуде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Морковь очистить, натереть на крупной терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Очищенный лук нарубить брусками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Овощи переложить в грибы, прогревать восемь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Мелкие помидоры вымыть, нашинковать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Слить жидкость от консервированного зеленого горошка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Вымыть кинзу и укроп, порубить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Все ингредиенты перемешать, добавить майонез, соль – по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9967,'Перемешать, выложить в салатницу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Филе индейки промыть, положить в подогретую и подсоленную воду, варить полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Переложить в тарелку, остудить, поделить на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Стебли сельдерея очистить, вымыть, нарезать квадратиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Красные болгарские перцы нарезать, семенные камеры удалить, мякоть нашинковать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Для заправки очистить лук, нарезать кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Перемешать с нежирной сметаной, горчицей, солью, душистым перцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Все составляющие соединить в большой миске, заправить сметанным соусом, дать салату постоять под крышкой в течение десяти минут для пропитывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9968,'Подать закуску в тарелке с листьями сельдерея.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Филе птицы отварить в воде с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Вешенки или боровики очистить, нарезать тонкими пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Лук нарезать тонкой соломкой, перемешать с грибами, тушить на сковороде с маслом до выпаривания жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Ананасы вынуть из банки, нарезать кусочками средней величины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Потереть твердый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Выложить салат на красивое блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Первый слой – мясной, второй – ананасы, третий – грибы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Слои промазывать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Сверху салат посыпать сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9969,'Блюдо поставить в холод на два часа для пропитывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9970,'Растереть масло (маргарин) с обычным и ванильным сахаром, вбить яйца и влить молоко. Добавить в жидкую массу муку и разрыхлитель, замесить тесто и перелить его в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9970,'Тесто разровнять и распределить по нему дольки консервированных персиков (чем больше фруктов и компота, тем вкуснее изделие).Духовку разогреть до 180 градусов, после чего отправить в нее форму с пирогом на 30-35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9970,'Для крема необходимо смешать сметану с сахаром. Готовый пирог «Персиковое наслаждение» еще горячим залить получившейся сметанно-сахарной массой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9970,'Дать пирогу немного времени остыть и пропитаться кремом, а затем нарезать его порционными кусочками и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Отварить индейку, нарезать мясо небольшими брусками, посолить, поперчить и обжарить на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Нашинковать помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Листья салата порвать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Промыть изюм в горячей воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Ингредиенты соединить, всыпать сухарики, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Приготовить соус из несладкого натурального йогурта, горчицы, чеснока, сока лимона, белого перца, морской соли, прованских трав.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Компоненты растереть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Блюдо покрыть листьями зеленого салата, выложить сверху смесь из мяса индейки, сухариков и овощей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9971,'Салат посыпать тертым сыром, залить заправкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Мясо индейки нарезать кусками, отварить до готовности, порубить на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Отварить куриные яйца, остудить, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Грецкие орехи очистить, поломать руками на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Чернослив хорошо вымыть, залить кипятком на пятнадцать минут, отцедить и нарезать квадратиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Выложить мясо в салатницу, посолить, смазать майонезом, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Сверху положить чернослив, яйца, полить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9972,'Посыпать блюдо грецкими орехами, поставить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Предварительно промытый рис (1,5 стакана) залить 2 стаканами холодной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Довести содержимое кастрюли до кипения и варить рис 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Влить в рис готовый рисовый уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Накрыть кастрюлю с рисом крышкой и варить его на маленьком огне еще 5-7 минут, пока вода не выпарится и не впитается.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Далее огонь под кастрюлей выключаем и, не снимая крышки, даем рису 15 минут настояться и заодно остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Обернуть макису для скатывания роллов пищевой пленкой и тонким плотным слоем выложить на нее готовый рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Затем по рису распределить нори, слегка спрыснуть их водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Выложить по центру заготовки угря,  сыр «Филадельфия» и порезанный соломкой маринованный огурец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Плотно скатать ролл, сверху колбаски выложить сырого или слабо копченого лосося и снова прокатать ролл.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9973,'Разрезать колбаску острым ножом на кусочки и подать роллы «Филадельфия» с васаби, имбирем и соевым соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Отварить куриные яйца, остудить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Грунтовые огурцы вымыть, нарезать квадратиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Отварить мясо индейки, нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Продукты перемешать, посолить, добавить зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Для заправки перемешать сметану с рубленым чесноком, перцем и соевым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9974,'Полить салат, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'Копченую индейку порубить кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'Апельсин очистить, разделить на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'Вымыть петрушку, мяту, кинзу, обсушить, нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'Рукколу вымыть и обсушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'На сухую нагретую сковороду всыпать семена кунжута, обжарить до коричневатого оттенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'В салатницу всыпать кусочки индейки, положить рукколу и апельсин, зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9975,'Посыпать блюдо крупной солью, специями, перемешать, посыпать кунжутом и полить оливковым маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Мясо положить в кастрюлю и залить водой. Довести до кипения, пену снять, варить до готовности.','https:https://st.vkuso.ru/data/cache/thumb/c1/24ef6a4b788c0c1_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Очистить и нарезать репчатый лук.','https:https://st.vkuso.ru/data/cache/thumb/24/2f986e6b1d73624_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Поставить на средний огонь сковороду, налить растительное масло.','https:https://st.vkuso.ru/data/cache/thumb/81/2fe9f41e4462b81_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Обжарить лук до зарумянивания.','https:https://st.vkuso.ru/data/cache/thumb/4b/59498326574594b_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Нарезать корень петрушки.','https:https://st.vkuso.ru/data/cache/thumb/6d/5b09656a577fb6d_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Всыпать в луковую обжарку кукурузную муку и перемешать.','https:https://st.vkuso.ru/data/cache/thumb/4d/d52a1ae9418c74d_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Вынуть из кастрюли мясо, всыпать промытый рис.','https:https://st.vkuso.ru/data/cache/thumb/2c/e1ceda2ba1fe42c_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Через десять минут положить в суп луковую обжарку.','https:https://st.vkuso.ru/data/cache/thumb/22/1cc442ed0de3022_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Добавить специи: лавровый лист, кориандр, корень петрушки, перец-горошек. Варить еще десять минут.','https:https://st.vkuso.ru/data/cache/thumb/b0/fe31cc6b14d84b0_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Положить баранину.','https:https://st.vkuso.ru/data/cache/thumb/b2/01d5a1bab6501b2_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Нарезать мелкими кусочками пастилу из алычи, выложить в кружку на две трети объема.','https:https://st.vkuso.ru/data/cache/thumb/47/eae1700bfa22947_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Залить бульоном и подождать, чтобы получилось пюре.','https:https://st.vkuso.ru/data/cache/thumb/de/30da95b7ce216de_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Порубить зелень кинзы и петрушки.','https:https://st.vkuso.ru/data/cache/thumb/ca/704b7ef102da0ca_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Положить пастилу в суп.','https:https://st.vkuso.ru/data/cache/thumb/ad/d157aa2b491f1ad_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Добавить стручок острого перца чили, хмели-сунели, петрушку, корицу и шафран, перемешать. Соль – по вкусу.','https:https://st.vkuso.ru/data/cache/thumb/a0/c74f0f38d55a6a0_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Если суп получился пресноватым – можно добавить зеленый соус ткемали. Перемешать и варить пять минут.','https:https://st.vkuso.ru/data/cache/thumb/9e/5d8fff08667389e_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Очистить и нарезать чеснок, растереть в кашицу в ступке.','https:https://st.vkuso.ru/data/cache/thumb/45/ceed4f425924745_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9976,'Огонь погасить, отправить в суп чеснок, кинзу и базилик.','https:https://st.vkuso.ru/data/cache/thumb/7d/8f91db026ac197d_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Отварить индейку, порубить небольшими прямоугольными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Открыть банку с консервированной кукурузой, слить жидкость, зернышки пересыпать к яблоку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Вымыть пекинскую капусту, нарезать тонкими полосками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Выложить в салатницу капусту, второй слой – индейка, третий – яблоко с кукурузой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Приготовить заправку из оливкового масла, лимонного сока, вылить на салат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9977,'Подать сразу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Мясо нарезать крупными кусками с косточкой, положить в кастрюлю.','https:https://st.vkuso.ru/data/cache/thumb/51/c75331f31e52951_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Залить водой, поставить на средний огонь и довести до кипения.','https:https://st.vkuso.ru/data/cache/thumb/40/e4a27353ddde040_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Снять пену при помощи ложки или шумовки. Если курица не домашняя, то первую воду лучше слить.','https:https://st.vkuso.ru/data/cache/thumb/1a/13b598b5d1f4f1a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Нарезать крупными кусочками морковь, надрезать крестом очищенную головку лука.','https:https://st.vkuso.ru/data/cache/thumb/35/51a3236ec5c3535_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Вымыть зелень, отрезать стебли, они пригодятся для бульона.','https:https://st.vkuso.ru/data/cache/thumb/41/3665ae4e44ba441_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Когда вторая вода снова закипит – добавить лук, стебли, морковь, лавровый лист, черный и душистый перец. Бульон довести до кипения, огонь уменьшить. Варить при слабом кипении от 40 до 60 минут.','https:https://st.vkuso.ru/data/cache/thumb/e8/2a7fc73613c6ee8_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Из готового бульона вынуть травы, курицу и овощи.','https:https://st.vkuso.ru/data/cache/thumb/6b/1c7e7d9b21f7e6b_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Бульон процедить через марлю или сито. Еще раз довести жидкость до кипения.','https:https://st.vkuso.ru/data/cache/thumb/28/96fa6fdd1f44928_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'В этот момент по желанию  можно добавить картофель.','https:https://st.vkuso.ru/data/cache/thumb/f0/954869762b048f0_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Всыпать промытый рис, вскипятить, варить 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/93/b6e44ded0a81d93_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Прогреть растительное масло на среднем огне, добавить нарезанный лук, пассеровать четыре минуты, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/c2/9eac958e3985cc2_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Отделить мясо от костей и нарезать кусочками небольшого размера.','https:https://st.vkuso.ru/data/cache/thumb/4b/4f01cddea6f4a4b_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Нарезать консервированные в собственном соку или свежие помидоры. Если они из магазина и не обладают выраженным вкусом – добавить по вкусу томатную пасту.','https:https://st.vkuso.ru/data/cache/thumb/a1/268878dc5581aa1_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'В обжаренный до мягкости лук добавить куриные кусочки, жарить две минуты, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/32/f245681dd97f332_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Положить специи: молотый кориандр, хмели-сунели, чабер, молотый красный перец, томатную пасту, соль.','https:https://st.vkuso.ru/data/cache/thumb/28/de6e1d308413028_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Добавить помидоры.','https:https://st.vkuso.ru/data/cache/thumb/4e/95ddf3f67853e4e_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Влить бульон, перемешать и потушить все вместе в течение семи или десяти минут.','https:https://st.vkuso.ru/data/cache/thumb/e5/f148e49e0ee06e5_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'В почти готовый кипящий суп влить готовую обжарку, перемешать, снова довести до кипения.','https:https://st.vkuso.ru/data/cache/thumb/9b/2168d6527bfe49b_434x295.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Добавить паприку, грецкие орехи, черный молотый перец, соль – по необходимости. Заправить ткемали.','https:https://st.vkuso.ru/data/cache/thumb/5c/c4b7a5cb61b065c_434x295.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9978,'Плиту выключить, в суп добавить рубленый чеснок, рубленую зелень. Дать блюду постоять под крышкой десять или двадцать минут.','https:https://st.vkuso.ru/data/cache/thumb/05/3fa08b30f636a05_434x295.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'В столовой ложке воды развести желатин и убрать его в сторону, чтобы набух.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'В маленькую кастрюлю влить молоко, всыпать кофе и дать смеси закипеть, затем снять ее с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'С помощью венчика взбить сахар и ванилин с яичным желтком и ввести массу в горячее молоко. Поставить кастрюльку с молочно-яичной массой на маленький огонь и при постоянном помешивании нагревать (не дать закипеть) содержимое посудины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'Как только смесь начнет густеть, ее нужно снять с огня, влить подготовленный желатин. Перемешивать массу до полного растворения желатина, после чего дать ей остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'Влить в остывшую массу сметану (сливки), перемешать и разлить по формочкам (чашкам).Далее классическая кофейная панакота помещается на 5 часов в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9979,'Перед подачей десерт можно при желании украсить тертым шоколадом, какао или апельсиновой цедрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Мясистые помидоры разрезать пополам, вынуть семена, слить сок, мякоть нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Твердый сыр нарезать ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Слить жидкость от консервированной красной фасоли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Продукты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Для заправки перемешать сметану с майонезом, давленым чесноком, солью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Салат заправить, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9980,'Блюдо посыпать рубленой зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'В миске смешать банановое пюре, сметану и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'Добавить в банановую массу крекер и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'Убрать емкость на 4 часа в холодильник, чтобы набух крекер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'По истечении времени достать тортик из холодильника, выложить его на сервировочное блюдо и придать ему желаемую форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'Посыпать верх торта тертым шоколадом и украсить по желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9981,'Оформленный сметанно-банановый тортик без выпечки торт снова поместить в холодильник, но уже на 2 часа',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Для пиццы в качестве основы подойдет дрожжевая булка или батон. Хлебобулочное изделие нужно разрезать на две половины вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Мякоть вынуть ножом или руками, делать это нужно осторожно, чтобы не повредить корочку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Обе половины намазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Отварить и натереть куриные яйца, насыпать в «лодочки».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Маринованные огурцы нарезать кружками, выложить поверх яиц.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Выложить кубики копченой колбасы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Нарезать кружками помидоры, это будет следующий слой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Натереть твердый сыр, посыпать пиццу, поставить в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9982,'Температура приготовления – 180 градусов, сыр должен расплавиться.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Любую колбасу и сладкий болгарский перец нарезать кубиками, помидоры и оливки – кружками, сыр натереть соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Батон накрошить в емкость руками, залить молоком, помять, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Вмесить в массу муку и сырое яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'В результате должно получиться плотное и густое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Налить масло на сковороду, выложить полученное тесто тонким слоем, жарить под крышкой до получения золотистой корочки с нижней стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Лепешку перевернуть, намазать соусом из томатного соуса и майонеза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Выложить начинку, посыпать тертым сыром, поставить на плиту на пять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9983,'Прогревать под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Для приготовления мини-пиццы лучше использовать готовые булочки для гамбургеров, но подойдет и батон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Нарезать ветчину или колбасу, помидоры кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Порубить зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Натереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Вынуть мякиш из булочек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Ингредиенты красиво выложить на хлебную основу, посыпать сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Мини-пиццы выложить в мультиварку, крышки от булочек – рядом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9984,'Выставить режим «Выпечка» на 15 минут, сыр должен расплавиться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Мясо нарезать кусками средней величины.','https:https://st.vkuso.ru/data/cache/thumb/b2/7eb7992d099ebb2_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Рис замочить.','https:https://st.vkuso.ru/data/cache/thumb/89/f58727e986cf489_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Свинину положить в кастрюлю, залить водой, варить 40 минут.','https:https://st.vkuso.ru/data/cache/thumb/d6/92fab59d5e082d6_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Снять пену.','https:https://st.vkuso.ru/data/cache/thumb/32/0d567fda2441532_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Очистить, нарезать репчатый лук. Обжарить на растительном масле в течение пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/40/39be362301a3940_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Добавить нарезанные свежие помидоры, кожицу лучше снять. Жарить все вместе пять минут.','https:https://st.vkuso.ru/data/cache/thumb/3b/9922ae21457f53b_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Добавить обжарку в бульон вместе с рисом, варить до готовности.','https:https://st.vkuso.ru/data/cache/thumb/a8/1f19ccfde1389a8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Чеснок измельчить.','https:https://st.vkuso.ru/data/cache/thumb/a2/81c2fde945f2fa2_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'Суп посолить за пять минут до окончания варки. Всыпать острый красный перец, чеснок и хмели-сунели.','https:https://st.vkuso.ru/data/cache/thumb/3b/5bdf71a76b7bf3b_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Масло прогреть, обжарить на нем лук и чеснок, овощи помешивать, чтобы не подгорели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9985,'В конце добавить лавровый лист, поварить две минуты, положить рубленую петрушку, кинзу. Прогреть две или три минуты, огонь выключить. Дать супу немного постоять.','https:https://st.vkuso.ru/data/cache/thumb/66/f89dbb5f7c2a766_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Говяжью тушенку нарезать, положить в кастрюлю, залить водой. Включить плиту, дать супу покипеть в течение семи или десяти минут. Нарезать кубиками очищенный картофель и лук.','https:https://st.vkuso.ru/data/cache/thumb/e8/37fca5faa2389e8_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Натереть на крупной терке морковь.','https:https://st.vkuso.ru/data/cache/thumb/03/a62eac829257103_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Прогреть на сковороде растительное масло, положить туда морковь и лук, перемешать и закрыть крышкой. Через десять минут обжарка будет готова.','https:https://st.vkuso.ru/data/cache/thumb/3a/e8297d38fdb4f3a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Положить в бульон картофель и промытый рис, варить 20 минут.','https:https://st.vkuso.ru/data/cache/thumb/a0/1147e1e2858a1a0_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'На сковороду с овощами добавить томатную пасту, перемешать. Прожарить несколько минут, помешивать.','https:https://st.vkuso.ru/data/cache/thumb/3b/69f6dd7c731da3b_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'При готовности риса и картофеля заправить суп обжаркой и специями: сушеным укропом, лавровым листом, сушеной петрушкой, паприкой, хмели-сунели и смесью перцев.','https:https://st.vkuso.ru/data/cache/thumb/44/4389e476a425044_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Огонь убавить, положить лимонную кислоту, соль.','https:https://st.vkuso.ru/data/cache/thumb/79/9755d30e49cb379_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9986,'Дать харчо закипеть, заправить давленым чесноком, прогреть пять минут.','https:https://st.vkuso.ru/data/cache/thumb/a6/2d798e22e2241a6_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Положить говядину в кастрюлю, залить водой, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Варить на тихом огне с лавровым листом, нарезанной морковью, сельдереем, картошкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Через 20 минут после закладки овощей добавить замоченную перловую крупу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Варить еще час на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Приготовить обжарку из нарезанного репчатого лука, ткемали, тертых соленых огурцов. Влить немного воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9987,'Готовую заправку перелить в суп, варить десять минут. Заправить измельченным чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9988,'Батон нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9988,'Смазать соусом из майонеза и кетчупа или томатной пасты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9988,'Сосиски нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9988,'Выложить на батон, посыпать тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9988,'Поставить в микроволновую печь на полторы минуты, до расплавления сыра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Куриное филе вымыть, срезать пленки и прожилки, мякоть нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Обжарить с виноградным маслом до изменения цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Шампиньоны вымыть и нарезать кубиками такого же размера, как и куриное мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Несколько грибов оставить целыми для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Добавить грибы к курице, продолжать жарить на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Репчатый лук нарезать соломкой, добавить на сковороду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Жарить все вместе, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Всыпать специи.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Почти готовую начинку посыпать зеленью, залить нежирной сметаной, потушить на медленном огне до закипания жидкости.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Сковороду снять с плиты, дать начинке немного остынуть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Батон разрезать пополам, мякиш вынуть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Противень застелить фольгой, выложить основу, начинку, сверху – кружки помидоров, тертый сыр, дольки оставшихся грибов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9989,'Время запекания – 10 минут, температура – 200 градусов. Края батона должны подрумяниться.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9990,'Консервированную фасоль выложить в салатницу, жидкость заранее слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9990,'Добавить измельченный чеснок, зелень, соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9990,'Салат заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9990,'Перед подачей положить сухарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9991,'Открыть банки с кукурузой и красной консервированной фасолью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9991,'Жидкость слить, продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9991,'Добавить чеснок, соль, любую зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9991,'Заправить майонезом по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9991,'Кириешки всыпать перед подачей на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Готовность выпечки проверить зубочисткой или деревянной шпажкой. Коврижку вынуть, остудить, разделить на два коржа, промазать джемом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9992,'Взбить любым способом сливочное размягченное масло с яйцами, обычным и ванильным сахаром. Добавить в масляную массу натуральный йогурт и тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9992,'Ввести просеянную муку в жидкую смесь, еще раз все перемешать: должно получиться не очень жидкое и не очень густое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9992,'Из получившегося теста испечь в электровафельнице ванильные хрустящие вафли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Разжечь костер, налить в казан воду. Положить куски говядины или баранины, варить под крышкой в течение часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Рис залить холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Репчатый лук очистить и нарезать тонкими полукольцами. Подлить немного готового бульона в сковороду, добавить лавровый лист, лук и томатную пасту. Потушить смесь до мягкости лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Через час после начала варки добавить в бульон рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Свежие помидоры надрезать, залить кипятком и снять кожицу. Мякоть нарезать мелкими кубиками, перемешать с давленым чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Нарезать зелень, добавить ее к помидорам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Измельчить орехи, добавить к помидорам вместе с хмели-сунели и смесью перцев.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Выдавить сок половины лимона, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Достать мясо из супа, нарезать кусками, вернуть в казан.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Добавить кипящую воду и соль по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Влить луковую смесь, довести до кипения.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9993,'Добавить орехово-томатную заправку, еще раз довести до кипения, дать постоять без огня 15 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Промыть сухофрукты, обсушить и выложить в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Добавить очищенные грецкие орехи, измельчить ингредиенты в кашу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'В небольшую емкость налить теплый свежий чай, рафинированное растительное масло, положить сахарный песок, смесь орехов с сухофруктами, приправить солью, ванилином из пакетика, корицей. Перемешать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Пищевую соду погасить лимонным соком, перелить в основную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Всыпать муку частями, вымесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Застелить форму пергаментом, смазать маслом, выложить тесто, разровнять, поставить в духовой шкаф.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9994,'Печь при температуре 190 градусов. Время приготовления – один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Слить жидкость с консервированной красной фасоли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Вымыть и порубить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Колбасу нарезать мелкими брусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Раздавить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Продукты перемешать и заправить нежирным майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9995,'Сухарики положить в конце приготовления.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'Размять шпроты вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'Отварить морковь и картофель, натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'Отварить и натереть куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'Продукты перемешать, добавить соль и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'Заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9996,'При подаче всыпать сухарики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Влить оливковое масло в глубокую емкость, добавить любимое варенье и сахар, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Растворить кофе в горячем крепком чае, жидкость перелить в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Положить измельченные обжаренные орехи и курагу, всыпать муку, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Погасить пищевую соду лимонным соком, перелить смесь в тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Натереть и добавить цедру половины лимона, остатки муки. Еще раз вымесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Форму для выпекания смазать маслом и присыпать манной крупой, переложить тесто, выпекать в течение часа. Температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9997,'Выпечку остудить и нарезать порционными кусками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Налить в миску растительное масло, положить варенье, всыпать сахарный песок, ванилин из пакета и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Ингредиенты перемешать, влить густой чай. Взбить смесь до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Перемешать муку с разрыхлителем, просеять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Всыпать смесь частями в тесто, добавить кусочки обжаренных орехов. Перемешать так, чтобы они равномерно распределились.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9998,'Форму для выпекания застелить пергаментом, выложить тесто. Выпекать 40 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9999,'Сливочное масло охладить и натереть на терке, муку просеять с разрыхлителем. Соединить муку, масло и яйцо, перетереть все в крошку и добавить творог, сметану и сахар. Замесить тесто, раскатать его в круг в 4-5 мм толщиной и, начиная от центра, нарезать на треугольники.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9999,'Для начинки смешать земляничное, персиковое и грушевое варенье с кедровыми орешками и фундуком, измельченным в крупную крошку. На каждый получившийся сегмент выложить полученную  начинку и скрутить в рогалики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9999,'Противень выстелить пекарской бумагой, распределить по нему подготовленные творожные рогалики с начинкой из варенья и орешков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (9999,'Смазать каждую заготовку яичным желтком и выпекать изделия в духовом шкафу 20 минут при 180 градусах. Дать готовым рогаликам остыть, перед подачей присыпать их сахарной пудрой и кунжутом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10000,'Налить воду в кастрюлю, поставить на огонь, растворить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10000,'Добавить натуральный мед, перемешать. Снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10000,'Отдельно перемешать какао-порошок с разрыхлителем. Влить теплый сироп из кастрюли. Перемешать, оставить на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10000,'Тесто перелить в форму, смазанную маслом, печь в течение часа, температура приготовления – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10000,'Готовую коврижку посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Отварить и нарезать куриные яйца, лучше кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Соленые огурцы измельчить точно так же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Натереть сыр на крупной терке, чеснок – на мелкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Порубить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Заправить салат майонезом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10001,'Всыпать сухарики и подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10002,'Куриные яйца отварить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10002,'Твердый сыр натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10002,'Соленые огурцы нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10002,'Чеснок порубить, зелень укропа нашинковать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10002,'Продукты перемешать, залить сметаной и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10003,'Яйца отварить и порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10003,'Измельчить чеснок, натереть сыр «Чеддер».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10003,'Продукты перемешать, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Мягкий сыр натереть на крупной терке, твердый – на мелкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Отварить и порубить куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Очистить свежие огурцы, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Зубчики чеснока натереть, перемешать со сметаной и натуральным йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Зелень петрушки порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10004,'Все смешать, добавить горчицу, каперсы, поставить на полчаса в холодильник для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Натереть на терке морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Пропустить чеснок через чеснокодавку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Продукты перемешать и залить сметаной, оставить на пятнадцать минут для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Бурак сварить и натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Чернослив промыть и порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Грецкие орехи измельчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Сыр натереть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Все перемешать, можно добавить еще одну порцию сметаны.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10005,'Соль – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10006,'В большую миску сложить творог, всыпать сахар, крахмал и ванилин. Затем в эту же емкость вбить яйцо, влить сметану и добавить апельсиновую цедру, которую при желании можно заменить орехами, свежими фруктами или сухофруктами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10006,'Взбить содержимое миски миксером в течение 3-4 минут и перелить получившееся тесто в форму, диаметр которой 20-22 см, предварительно смазанную маслом или выстеленную пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10006,'Убрать форму с тестом на 40-50 минут в разогретую до 180 градусов  духовку, после чего готовый творожник с цедрой апельсина обязательно остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Курицу или индейку промыть в холодной воде, опустить в кастрюлю, залить водой, посолить по вкусу, положить лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Мясо можно заранее нарезать кусочками, кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Довести до кипения, уменьшить огонь, варить до готовности, пену снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Картофель нарезать кубиками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Морковь и свеклу потереть в разные емкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Добавить свеклу, морковь, молотую паприку, черный перец, перемешать, тушить под крышкой в течение пятнадцати минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Нашинковать белокочанную капусту, добавить в обжарку и немного упарить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Добавить томатную пасту, немного бульона, сахарный песок, перемешать, прогревать все вместе двадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'В бульон добавить картофель, через двадцать минут – обжарку, рубленую петрушку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Потушить суп пять или семь минут на тихом огне.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10007,'Дать блюду настояться.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Борщ можно сделать постным или на основе говяжьего, куриного или свиного бульона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Для пампушек подогреть молоко, растворить в нем сахарный песок, дрожжи, соль, немного заранее просеянной муки, растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Ингредиенты перемешать, накрыть тканью, дать постоять, чтобы начали «работать» дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'В поднявшуюся опару всыпать муку, замесить тесто, выложить в мисочку и поставить в теплое место.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Масса должна увеличиться в два раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Противень для выпекания смазать маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Тесто обмять, сформовать шарики, выложить, оставить в тепле для расстойки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Через пятнадцать минут поставить в духовой шкаф, печь при температуре 200 градусов. Должна получиться румяная корочка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Выпечку вынуть, накрыть полотенцем, оставить на некоторое время.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Отдельно в ступке растереть соль с чесноком и водой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Пампушки обмакнуть в поученный соус.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10008,'Посыпать зеленью петрушки, укропа.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Фасоль промыть под проточной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Затем залить новой порцией воды и оставить на четыре часа для набухания. Жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Залить свежей водой, поставить на огонь, варить в течение часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Морковь натереть или нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Репчатый лук мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Нашинковать белокочанную капусту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Нарезать кубиками картофель.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'В сваренную фасоль выложить капусту и картофель.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Прогревать все вместе в течение десяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Прогреть на сковороде растительное масло, обжарить репчатый лук и морковь.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Добавить томатную пасту, немного бульона, проварить несколько минут, затем переложить в борщ.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Очистить и натереть свеклу, потушить с маслом в течение пяти минут, переложить в суп.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'Добавить немного сахарного песка и лавровый лист, готовить на среднем огне под крышкой, время – пятнадцать минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10009,'При подаче всыпать в борщ рубленую зелень.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Промыть и нарезать соломкой морковь, репчатый лук, картофель и свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Белокочанную капусту нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Помидоры бланшировать в кипятке, очистить от кожуры, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Чеснок очистить и пропустить через пресс или натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Вскипятить воду, положить капусту и картофель, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Прогреть растительное масло на сковороде, обжарить лук и морковь в течение пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Добавить нарезанную свеклу, сахар и столовый уксус, прогреть на минимальном огне пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Всыпать кубики томатов, тушить еще двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Готовую обжарку переложить в суп, довести до кипения, пенку снять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Добавить лавровый лист, варить пять минут, затем – чеснок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Блюдо накрыть крышкой, огонь погасить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10010,'Подать к столу со сметаной и зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/83/c24f8c7a16eb083_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Смешать все сухие ингредиенты.Перемешать.','https://vkuso.ru/data/cache/data/96/23bfeec2492ae96_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Добавить яйца и масло.','https://vkuso.ru/data/cache/data/dc/c7f824714bf85dc_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Замесить тесто.','https://vkuso.ru/data/cache/data/ab/af5dbcfda69d6ab_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Выложить тесто на противень.','https://vkuso.ru/data/cache/data/93/c1b6a06eebf0293_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Разровнять.','https://vkuso.ru/data/cache/data/ad/d4f04cb6c0673ad_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Выложить повидло, разровнять. Выпекать при температуре 180 градусов 20 минут.','https://vkuso.ru/data/cache/data/ad/c9fbce8fccd19ad_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10011,'Нарезать красиво. Приятного аппетита.','https://vkuso.ru/data/cache/data/33/fbdca2076bdfa33_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Всыпать растворимый кофе в чашку, заварить кипятком, добавить сахар и мед, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Перелить в миску, всыпать рисовые хлопья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Добавить растительное масло, всыпать муку порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Промыть изюм, выложить на бумажное полотенце, обсушить. Пересыпать в тесто, вымешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Чашу мультиварки смазать маслом, вылить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Выставить программу «Выпечка» на 50 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10012,'Коврижку достать, отправить в духовой шкаф на полчаса, чтобы подрумянилась. Остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10013,'Курицу или куриные окорочка очистить от кожи и костей, порезать на небольшие кусочки и переложить их в миску. Добавить к мясу соль, пропущенный через пресс очищенный чеснок и молотый перец. Далее всыпать в эту же емкость сухой желатин (воду не добавлять!), тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10013,'Сложить подготовленное мясо в пакет от сока или молока, внутри которого должна быть фольга, обернуть верх пакета пищевой пленкой. В кастрюлю влить воду в таком количестве, чтобы уровень мяса в пакете совпадал с уровнем воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10013,'Готовится (варится) домашняя куриная ветчина с чесноком  на протяжении 1-1,5 часов на среднем огне. После того как ветчина будет готова, ее необходимо полностью остудить, а затем аккуратно разрезать пакет и достать из него мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Вскипятить воду, залить заварку черного чая, оставить для настаивания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Чай процедить через сито, добавить мед и сахарный песок. Поставить на плиту, подержать на небольшом огне до растворения ингредиентов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Влить растительное масло, перемешать и остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Изюм без косточек промыть, залить кипящей водой, дать постоять, затем отжать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Очищенные орехи выложить в полиэтиленовый пакет, измельчить при помощи скалки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'В уже остывшую жидкость всыпать какао-порошок через ситечко, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Добавить в смесь изюм и орехи, перемешать, добавить корицу, гвоздику, имбирь, взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Муку с подмешанной пищевой содой подсыпать порциями, тесто вымесить, оно должно получиться как на оладьи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10014,'Форму смазать, присыпать манной крупой, вылить тесто. Время выпекания – 40 минут, температура – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Сделать сироп из варенья: положить варенье в сито, дать сиропу стечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Влить воду в небольшой сотейник, всыпать сахарный песок, поставить на плиту. Прогреть, помешивая, до растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Немного остудить, влить сироп из варенья, подсолнечное масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Нарезать мелко хорошо промытый лимон, переложить в чашу блендера, изрубить в кашу, добавить в сотейник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Пшеничную муку перемешать с пищевой содой и какао-порошком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Смесь всыпать в сотейник порциями, добавить цукаты, измельченные орехи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Форму смазать маслом, вылить тесто, разровнять мокрой лопаткой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10015,'Поставить изделие в духовой шкаф на 30 минут, температура выпекания – 180 градусов. Готовность выпечки проверить зубочисткой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Налить воду в сотейник, добавить растительное масло, сахар. Прогреть и добавить натуральный мед. Прогревать до растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'В еще неостывшую жидкость добавить молотую корицу и пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Измельчить грецкие орехи всыпать в основную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Перемешать с мукой разрыхлитель, замесить полужидкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Яблоки вымыть и нарезать дольками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Чашу мультиварки смазать маслом, влить тесто, фрукты разложить сверху, немного вдавливая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10016,'Выставить программу «Выпечка» на 50 минут. Оставить пирог еще на несколько минут в режиме подогрева.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Вырезку промыть, положить в воду, довести до кипения на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Появляющуюся пенку убрать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'После начала закипания в бульон положить морковку и луковицу, овощи разрезать на две части, добавить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Время варки – один час, температура – средняя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Фасоль промыть и замочить в ледяной воде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Добавить в кастрюлю с почти готовым мясом и варить еще час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Отдельно отварить свеклу до мягкости, проверить можно вилкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Мясо вынуть, разрезать на порции или произвольными ломтиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Вынуть и выбросить морковь, лук, лавровый лист.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Отваренную свеклу очистить и крупно натереть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Половину массы переложить в борщ, варить пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Нарезать кубиками корнеплоды.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Картофель выложить в бульон.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Нарезать сладкий перец, лук и томаты кубиками, пассеровать на масле вместе с тертой морковью пятнадцать минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Приправить томатной пастой и несколькими столовыми ложками бульона, перемешать и прогревать несколько минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Массу переложить в борщ, варить пять минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Белокочанную капусту нашинковать, отправить в бульон вместе с оставшейся свеклой.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Нарезать мелкими кубиками сало, добавить тертый чеснок, перемешать, немного растереть и заправить борщ.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Соль и молотый черный перец – по вкусу.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'Вернуть в суп ломтики говядины, прогреть в течение нескольких минут, оставить на полчаса под крышкой для настаивания.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10017,'При подаче приправить суп зеленью и сметаной.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Свиную вырезку поделить на несколько частей, залить водой, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Воду слить, залить мясо свежей холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Прогревать от сорока до сорока пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Мясо вытащить и разобрать на кусочки вилкой и ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Приготовить обжарку из репчатого лука и чеснока, затем добавить тертую свеклу, томатную пасту и сахарный песок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Нашинковать белокочанную капусту, положить в борщ.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Нарезать соломкой картофель.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Овощи добавить в бульон, вернуть кусочки свинины, положить обжарку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Все вместе кипятить в течение нескольких минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10018,'Огонь погасить, дать блюду настояться.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Говяжью вырезку нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Залить водой, добавить лавровый лист и луковицу целиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Варить в течение часа, огонь – сильный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Кусок копченого сала нарезать брусочками по одному сантиметру толщиной, обжарить на сковороде до полупрозрачности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Натереть на крупной терке морковь и свеклу, нарезать кольцами репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Переложить ингредиенты на сковороду к салу, прогревать, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'При готовности добавить томатную пасту, тушить еще две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Из готового бульона удалить лук и лавровый лист, добавить обжарку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Нарезать мелкими кусочками половину лимона и добавить в борщ для цвета и аромата.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Готовить десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Нашинковать белокочанную капусту.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Нарезать клубни картофеля.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Сначала в борщ положить капусту, через пятнадцать минут – картофель.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10019,'Еще через пятнадцать минут суп можно подать к столу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Приготовить обжарку из тертых овощей: свеклы, моркови, нарезанного лука. Режим – «Выпечка», десять минут. Массу помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Добавить мясо, нарезанное кусочками, лучше, если это будет курица.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Жарить пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'В теплой воде развести томатную пасту, подлить в овощи, тушить под крышкой пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Нарезать картофель, нашинковать белокочанную капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Положить овощи в чашу, залить теплой водой, посолить, добавить специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'Выставить режим «Тушение», готовить под крышкой 45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10020,'В конце добавить зелень, давленый или тертый чеснок, выставить режим «Подогрев» на 10 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10021,'Сделать вдоль каждой сосиски глубокий разрез (не разрезать до конца!).Сыр натереть на терке и заполнить им все разрезы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10021,'Каждую начиненную сосиску обернуть полоской бекона так, чтобы разрез «скрывался» под беконом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10021,'Выложить все подготовленные сосиски по-шведски с сыром  на противень или порционную сковороду и в течение 5-6 минут запечь их при 250 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Приготовить бульон из любого мяса. Пенку снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Натереть морковь и свеклу, спассеровать вместе с полукольцами репчатого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Выжать сок из лимона, добавить к овощам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Мясо вытащить, мелко нарезать, обжарить вместе с овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Картофель нарезать средней соломкой, добавить в бульон, огонь уменьшить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'В обжарку добавить сахар и соль, перец чили, паприку, хмели-сунели, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Бульон довести до кипения, положить обжарку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Обжарить на масле измельченный чеснок, переложить в борщ.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10022,'Суп прогреть в течение трети часа, подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/85/d37c864fd017185_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'Нарежьте кубиком.','https://vkuso.ru/data/cache/data/fb/a65946fecc5d5fb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'Собираем салат слоями.1 слой - картошка, сверху майонез.','https://vkuso.ru/data/cache/data/28/3d0c6bb408a4028_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'2 слой - огурцы','https://vkuso.ru/data/cache/data/62/2a52624fc298362_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'3 слой - курица, сверху майонез.','https://vkuso.ru/data/cache/data/59/890904caf255359_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'4 слой - горошек.','https://vkuso.ru/data/cache/data/1c/4724a3cab1f921c_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'5 слой - яйца, сверху майонез.','https://vkuso.ru/data/cache/data/45/a3538bd47607745_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'6 слой - помидор.','https://vkuso.ru/data/cache/data/ef/cc462c67c2e1aef_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10023,'Украсить бока зеленью, сверху уложить сухарики.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Овощи очистить, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Морковь нашинковать соломкой, свеклу натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Сладкий болгарский перец очистить от семян, порубить кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Белокочанную капусту нашинковать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Картофель очистить и нарезать кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Репчатый лук нарезать полукольцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Пересыпать его в кастрюлю с толстыми стенками, влить постное масло и сливочный жир.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Обжарить до мягкости, добавить морковь, тонко нарезанный кружками корень сельдерея, болгарский перец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Прогревать, через пять минут положить тертую свеклу, полить уксусом или лимонным соком для сохранения цвета.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Готовить на среднем огне в течение двадцати минут под крышкой, несколько раз перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Заправить борщ томатной пастой, рубленым чесноком, сахаром, положить капусту.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Ингредиенты перемешать, посолить и поперчить по вкусу, влить кипяток.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Добавить картофель, довести до кипения, огонь убавить, варить до готовности.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10024,'Оставить суп для настаивания на пятнадцать минут, затем подать к столу.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Красную фасоль замочить с вечера: на одну часть бобовых должно приходиться две части воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Назавтра отварить продукт до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Репчатый лук и морковь мелко накрошить, спассеровать на постном масле в сотейнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Добавить тертую свеклу, томатную пасту, разведенную в воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Потомить обжарку в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Влить воду в кастрюлю, положить перец-горошек, лавровый лист, морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Проварить пятнадцать минут, ингредиенты вынуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Выложить в бульон нарезанный брусками картофель, полоски красного сладкого перца, нашинкованную белокочанную капусту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Посолить, добавить специи, варить овощи до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Переложить в суп обжарку, прогреть пять минут, положить кусочек сливочного масла, огонь погасить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10025,'Борщ разлить по тарелкам и положить отваренную красную фасоль.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Репчатый лук и морковь нарезать кубиками, точно так же поступить с картофелем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Свеклу натереть на мелкой терке, достаточно половины корнеплода.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Выставить режим «Жарка». Влить растительное масло, нагреть в течение минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Всыпать лук и морковь, жарить вместе пять минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Положить в обжарку свеклу, прогреть три минуты, всыпать кубики картофеля, помешивать, жарить пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Выставить режим «Суп», время – сорок минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Влить в чашу горячую воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Посолить, всыпать сахарный песок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'За десять минут до конца срока приготовления добавить нашинкованную белокочанную капусту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Остатки свеклы натереть, спассеровать рубленый чеснок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Ингредиенты выложить в суп за пять минут до конца варки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10026,'Долить уксус.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Репчатый лук нарезать кружочками, а затем четвертинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Нашинковать соломкой морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Из сладкого болгарского перца вынуть семена, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Клубни картофеля очистить и нарезать брусками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Перо зеленого лука, зелень петрушки, щавель и укроп промыть, у щавеля удалить стебли, листья крупно порвать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'В кастрюлю налить растительное масло, обжарить морковь и лук до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Добавить измельченные помидоры и томатную пасту.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Состав перемешать, потушить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Залить продукты горячей водой, добавить картофель, болгарский перец.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Посолить по вкусу, варить до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Добавить в борщ щавель и другую зелень, лавровый лист, заранее отваренные, очищенные и нашинкованные яйца.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Приправить душистым и жгучим перцем, положить немного сливочного масла.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10027,'Борщ перемешать, довести до кипения, огонь выключить через три минуты.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10028,'До легкой воздушной массы взбить масло с сахаром миксером на высокой скорости. Сбавить скорость до средней и ввести яйца (большие), ванилин, сметану и оба вида цедры, хорошо размешать. Просеять муку с солью, крахмалом и содой, снова сбавить скорость миксера до маленькой и всыпать в массу мучную смесь, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10028,'Две формы смазать сливочным маслом и выстелить пергаментом, равномерно распределить по ним получившееся тесто. Тесто в каждой форме разровнять, убрать все в духовку, нагретую до 175 градусов, выпекать коржи 45 минут, после чего дать им полностью остыть. Для начинки взбить до пиков сливки с обычным и ванильным сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10028,'Собрать торт: первый корж смазать 1/2 частью получившегося крема и распределить по нему половину консервированных персиков. Далее на персики положить второй корж, который также промазать кремом и сверху выложить оставшиеся персики. Подается торт с консервированными персиками и взбитыми сливками в охлажденном виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Замочить в чистой воде сушеные грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Через два или три часа продукт можно отварить в той же жидкости до мягкого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Грибы вынуть, нашинковать, процедить отвар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Чернослив без косточек хорошо промыть, сварить в небольшом количестве воды, процедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Сухофрукты порубить кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Нарезать лук и морковь, спассеровать на масле, добавить тертую свеклу и томатную пасту, состав прогревать двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Грибной бульон вскипятить, посолить, выложить готовые овощи',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Влить отвар, оставшийся от чернослива.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Всыпать кусочки сухофруктов, рубленую зелень и грибы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10029,'Прокипятить борщ в течение минуты и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Репчатый лук порубить и спассеровать на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Добавить нарезанную соломкой морковь. Прогревать еще десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Натереть свеклу и обжарить отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Просеять ржаную муку, посолить, влить воду, масло, замесить тесто. Оно должно быть пластичным, мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Накрыть тканью, оставить на некоторое время.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10044,'Все вместе взбить до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'От получившегося колобка отщипнуть пальцами небольшие галушки, скатать шариками, каждый кусочек немного придавить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Налить в кастрюлю воду, посолить, опустить галушки, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Добавить овощную обжарку, свеклу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10030,'Прогреть все вместе пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Сахарный песок растереть с оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Апельсины очистить, нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Орехи измельчить при помощи скалки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Заварить крепкий черный чай.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Апельсины переложить вместе с орехами и повидлом в масляную смесь, влить чайную заварку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Всыпать муку, перемешанную с содой, вымесить полужидкое тесто, как для оладий.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10031,'Застелить дно формы пергаментом, смазать маслом, перелить тесто, выпекать 40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10032,'Всыпать муку в миску, добавить сахар, влить растительное масло, соду, погашенную уксусом, лимонад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10032,'Вымесить тесто полужидкой консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10032,'Форму для выпекания присыпать мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10032,'Вылить тесто, посыпать молотой корицей и сахаром, выложить бананы, нарезанные кружочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10032,'Время выпекания – 20 минут, температура – 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Грушу разрезать на две половинки, удалить сердцевину с косточками. Широкий край нарезать тонкими пластинками или веером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Миндальные орехи измельчить в порошок при помощи кофемолки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Всыпать сахар в емкость, влить воду, перемешанную с постным маслом. Смесь поставить на водяную баню, выложить натуральный мед, прогревать до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Погасить пищевую соду лимонной кислотой, положить в смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Приправить молотой корицей, выложить орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Перемешать, всыпать муку, смешанную с разрыхлителем, в несколько приемов, вымесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Форму смазать, присыпать панировочными сухарями, вылить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10033,'Мокрой лопаткой разровнять поверхность, разложить груши, поставить на полчаса в духовой шкаф. Температура выпекания – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10034,'Промыть сухофрукты, обсушить салфеткой. Выложить в чашу блендера, перемолоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10034,'Смешать растительное масло с сахарным песком, добавить сухофрукты, орехи, влить свежий яблочный сок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10034,'Приправить молотой корицей, перемешать, добавить ванилин, соду, погашенную лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10034,'Всыпать пшеничную муку порциями, вымесить полужидкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10034,'Форму смазать маслом, вылить тесто, печь коврижку в течение часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10035,'В кастрюльку налить воду, всыпать сахар и варить, пока не получится сироп. Добавить к сиропу порезанный лимон и продолжить варить все вместе 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10035,'Куриные крылья промыть, смазать молотым перцем и переложить в форму. Залить крылышки получившимся сиропом вместе с лимонами и убрать форму в загодя разогретую до 180 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10035,'Запекать блюдо в районе 40 минут, а затем подать куриные крылышки в лимонном сиропе к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10036,'В чаше перемешать сахарный песок, соль, ванилин из пакетика, сухие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10036,'Всыпать муку, тертую цедру одного лимона, добавить размягченное сливочное масло, жирные сливки, вбить яйца и влить дополнительные сырые желтки без белков. Ингредиенты хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10036,'В мультиварке или хлебопечке включить режим «Сладкая выпечка». На втором этапе замешивания теста добавить заранее промытый и обсушенный изюм без косточек, немного коньяка – по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10037,'В смесь воды с молоком добавить сухие дрожжи и сахар, оставить на 10 или 15 минут, дрожжи должны разойтись.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10037,'Всыпать соль, цельнозерновую и пшеничную муку, влить растительное масло, вбить сырое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10037,'Замесить тесто, оно должно отставать от рук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10037,'Поделить массу на 12 частей, сформовать небольшие булочки, выложить их на противень и оставить на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10037,'Духовку разогреть до 180 градусов, время выпекания – от 20 до 25 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10065,'Поставить кастрюлю на огонь, прогреть, в начале закипания положить плавленый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10038,'Готовое песочное печенье измельчить при помощи блендера, перемешать полученную крошку с растаявшим сливочным маслом. Переложить смесь в форму для выпекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10038,'Йогурт перемешать с заранее растворенным в горячем молоке желатином, залить первый слой. Поставить заготовку в холодильник для застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10038,'Выложить консервированную или свежую, слегка проваренную, вишню на молочный слой. Залить вишневым соком с желатином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10038,'Торт отправить на ночь в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Свеклу очистить, промыть, нашинковать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Полить продукт уксусом, чтобы он не потерял цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Выложить на сковороду, налить масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Добавить томатный соус или пюре, немного воды и сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Накрыть крышкой, потушить. Несколько раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Немного масла влить в сотейник, спассеровать репчатый лук, морковь, нарезанный мелкими кусочками корень петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Пшеничную муку просеять, выложить на сковороду без масла, влить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Прогреть до однородного состояния, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Нарезать дольками клубни картофеля, опустить в кипяток, варить пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Добавить свеклу, нарезанный кубиками сладкий болгарский перец, овощную обжарку, лавровый лист.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Суп заправить специями, солью, растертым чесноком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10039,'Ввести мучную заправку, перемешать, прогреть в течение минуты.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10040,'Приготовить тесто для блинов из молока, сахара, сырых яиц, растительного масла, ванилина и щепотки соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10040,'Пожарить блины, сложить их треугольниками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10040,'На сковороду налить апельсиновый сок, положить кусочек сливочного масла, всыпать сахар по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10040,'Выложить блинчики, потушить две минуты под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Креветки в течение двух минут отварить в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Откинуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'В том же бульоне сварить репчатый лук, корень сельдерея и картофель до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Разогреть сковороду и потушить шпинат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Все ингредиенты соединить, взбить при помощи блендера вместе с жидкостью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Добавить по вкусу сухой базилик, перец и соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10041,'Довести суп до кипения, подать на стол, положить отваренные креветки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10042,'Рыбу промыть и извлечь все косточки, пропустить очищенный чеснок через чесночницу. Для маринада смешать в форме для запекания соевый соус, мед, оливковое масло. Добавить в жидкую смесь подготовленный чеснок, острый молотый чили и смесь молотых перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10042,'Поместить в получившийся маринад подготовленные куски рыбы кожей вверх и оставить при комнатной температуре на полчаса мариноваться. Перевернуть кожей вниз промариновавшуюся рыбу, сверху посыпать семенами кунжута.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10042,'Убрать рыбу вместе с маринадом в разогретую духовку и запекать блюдо в течение 12-15 минут при 230 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10042,'Семга в соево-медовом соусе с перцем чили прекрасно сочетается с гарнирами из  риса или с овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'В сотейник налить оливковое масло, прогреть, обжарить нарезанный мелкими кусочками цуккини, лук-порей, корень имбиря.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Положить шпинат, все вместе тушить еще две или три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Влить заранее приготовленный овощной бульон, добавить давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Посолить и поперчить по вкусу, положить молотый мускатный орех.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Суп довести до кипения, варить в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Взбить блендером до состояния однородности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10043,'Долить кокосовые сливки, хорошо перемешать, подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10044,'Картофельные клубни и брокколи отварить в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10044,'Капусту добавить за несколько минут до готовности картофеля, иначе она потеряет цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10044,'Потушить в сотейнике шпинат в течение двух или трех минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10044,'Все ингредиенты соединить, добавить любимые специи, немного бульона, оставшегося от варки овощей, растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Положить на сковороду немного сливочного масла, подлить растительное масло, жарить измельченный лук с чесноком до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Посолить, поперчить, положить листья шпината.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Прогревать еще несколько минут, затем добавить молотый мускатный орех.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Отварить отдельно картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Ингредиенты соединить, взбить при помощи блендера, подлить сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Суп прокипятить в течение нескольких минут, подать горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10045,'Посыпать тертым сыром «Пармезан».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Нарезать репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Измельчить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Положить шпинат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Всыпать немного муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Подлить овощной бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Смесь довести до кипения, потушить в течение нескольких минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Влить молоко, варить еще пять-шесть минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'При помощи погружного блендера превратить смесь в пюре, добавить соль и специи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'На сковороде обжарить тигровые креветки на оливковом масле с добавлением чеснока.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10046,'Разлить суп в тарелки, добавить креветки, посыпать семенами черного кунжута.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Репчатый лук очистить и нарезать кубиками, так же поступить с картофелем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Овощи залить водой, добавить лавровый лист, варить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Лавровый лист вынуть, выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Добавить замороженный шпинат и специи, соль, варить еще пять или шесть минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Содержимое кастрюли превратить в пюре при помощи блендера, влить сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10047,'Приготовить сухарики, подать к супу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10048,'В большой посудине смешать все указанные для соуса ингредиенты. Куриные крылья помыть, обсушить и поместить в емкость с подготовленным маринадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10048,'Промариновать курицу не меньше двух часов, если нет необходимости, крылья можно на ночь оставить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10048,'Переложить крылышки куриные в соевом соусе с томатной пастой в смазанную маслом форму. Запекать в духовке при 200 градусах в течение 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Перепелиные яйца отварить до полной готовности, почистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Налить в сотейник оливковое масло, добавить сливочное.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Нарезать репчатый лук и чеснок, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Добавить бульон, шпинат, подлить сливки, всыпать специи, соль по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Смесь довести до кипения, время варки – пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Превратить суп в крем при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10049,'Разлить в тарелки, добавить по разрезанному пополам перепелиному яйцу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Разогреть в кастрюле растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Лук-порей нарезать кольцами и обжарить до прозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Добавить сливочное масло, всыпать прованские травы, положить нарезанный кубиками картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Смесь залить бульоном, варить до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Добавить листья хорошо промытого шпината, посолить и поперчить, приправить мускатным орехом, варить пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Превратить смесь в пюре при помощи погружного блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Влить сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10050,'Суп еще раз довести до кипения и подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'Лук-порей нарезать кольцами, обжарить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'Сварить куриный бульон, добавить в него кубики картофеля, луковую обжарку, специи – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'Варить до полной готовности, затем положить шпинат и прогревать до готовности зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'Суп превратить в пюре погружным блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'При подаче добавить немного сока лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10051,'Разлить суп по тарелкам и украсить тонко нарезанной копченой семгой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10052,'Шоколад растопить со сливочным маслом на пару.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10052,'Отдельно взбить сырые куриные яйца с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10052,'Добавить массу в шоколад, всыпать муку, влить коньяк.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10052,'Перемешать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10079,'Кабачки, картофель и морковь нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10052,'Тесто перелить в формы, печь в течение пяти или десяти минут, температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Хлеб для крутонов нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'В емкости с герметичной крышкой перемешать растительное масло с нарубленным чесноком и специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Пересыпать хлеб, потрясти контейнер так, чтобы приправа распределилась равномерно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Подсушить крутоны на сухой сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Нарезать пекинскую капусту, крабовые палочки, твердый сыр, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Всыпать консервированную кукурузу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Сбрызнуть салат лимонным соком и заправить сметаной. Соль и молотый перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10053,'Сверху посыпать крутонами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Изюм залить кипящей водой, через полчаса воду слить, продукт обсушить при помощи бумажного полотенца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Грецкие орехи измельчить блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Тесто можно замесить в стационарном миксере или сделать это венчиком. Размягченное сливочное масло взбить с сахаром до его полного растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Вбить по одному яйцу, всыпать мускатный орех и разрыхлитель, соль, ванилин. Продолжать помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Влить коньяк, тесто еще раз хорошо вымешать, добавить муку. Масса должна получиться воздушной, полужидкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Ввести молотые орехи и изюм.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Тесто выложить в форму, печь в течение 50 минут, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10054,'Готовность кекса проверить деревянной палочкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Нарезать кубиками маринованные огурцы и отваренный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Натереть на терке сыр и отваренные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Репчатый лук очистить и также нарезать кубиками, ошпарить кипятком, чтобы удалить лишнюю горечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Шпроты открыть, слить масло, рыбу размять вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Выложить салат на тарелку башенкой, удобнее использовать круглую разъемную форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Первый слой – картофельный, промазать майонезом. Затем – лук, шпроты, огурцы, тертые яйца. Еще раз смазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10055,'Форму снять. Верх посыпать сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10056,'Сварить из воды и риса вязкую кашу, которую затем полностью остудить. Через мясорубку дважды пропустить рыбную мякоть вместе с рисом и измельченным чесноком . В получившуюся массу влить масло оливковое, посолить и поперчить ее по вкусу и тщательно все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10056,'Сформовать из фарша небольшие шарики и готовить рыбные фрикадельки с рисом на пару до полной готовности. Готовые фрикадельки подавать с любимым гарниром, предварительно украсив их свежей зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'В кастрюлю положить сливочное и подлить растительное масло. Прогреть, обжарить рубленый репчатый лук до появления золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Лесные грибы вымыть и нарезать кусочками среднего размера. Переложить в луковую обжарку, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Влить сливки, смесь довести до кипения, тушить в течение пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Добавить горячий бульон из овощей, посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Содержимое кастрюли размолоть блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Хлеб нарезать кусочками, подсушить, намазать чесночным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Сушеные белые грибы залить горячей водой на десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10057,'Готовый суп разлить в тарелки, украсить размоченными сушеными грибами и гренками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Свежие белые грибы почистить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Для обжарки смешать сливочное и оливковое масло, обжарить нарезанную морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Всыпать грибы, тмин, посолить и поперчить, жарить в течение пятнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Влить 6-7 стаканов воды, довести до кипения, огонь уменьшить и варить около 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Порезать лук и обжарить на сковороде до золистого цвета, затем всыпать муку, жарить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Влить белое вино, перемешать, прогревать еще минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'Добавить в бульон поджарку, соль и перец, довести суп до кипения, проварить двадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10058,'В конце приготовления влить сливки и всыпать рубленую петрушку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Грибы вымыть, очистить и нарезать. Залить водой, довести до кипения, время варки – один час. Пенку снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Очистить и нарезать картофель, лук, морковь и чеснок. Продукты обжарить на сливочном масле на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Бульон процедить, грибы промыть чистой водой и вернуть в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Всыпать картофель, через пятнадцать минут – обжарку, варить все вместе пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Влить сливки, перец и соль – по вкусу. Варить пять минут, довести суп до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10059,'Измельчить содержимое кастрюли при помощи блендера в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Грибы разморозить и обжарить на сливочном масле до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Нарезать базилик и петрушку, положить в обжарку, влить воду, довести до кипения и посолить. Варить в течение пяти минут, снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Приготовить заправку: растопить сливочное масло на сковороде, положить плавленый сыр, прогреть, перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Влить сливки, поперчить, еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Готовый соус смешать с грибным бульоном, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Хлеб намазать сливочным маслом и запечь в духовом шкафу, затем порезать гренки кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10060,'Разлить суп в тарелки, посыпать домашними гренками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Сушеные грибы промыть, дать настояться в течение часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Отварить фасоль, раздавить вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Очистить от кожуры картофель, нарезать кубиками. Морковь нарезать крупными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Сушеные грибы, морковь и картофель отварить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Нарезать кубиками репчатый лук, обжарить на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Добавить размороженные грибы, жарить на тихом огне. Излишки жидкости слить в стакан.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Обжарку и фасоль добавить в кастрюлю.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Все ингредиенты перемолоть в блендере, долить бульон. Соль и перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10061,'Суп поставить на огонь. При закипании добавить сливки. Смесь еще раз перемешать, посыпать укропом, снять с огня.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10062,'Свежие белые грибы мелко нарезать, всыпать в кипяток. Варить в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10062,'Картофель очистить и нарезать кубиками небольшого размера, добавить в грибы. Варить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10062,'Репчатый лук мелко порубить, морковь натереть. Овощи обжарить на растительном масле и добавить в суп вместе с лавровым листом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10062,'В конце приготовления положить любой плавленый сыр, перемешивать до растворения. Взбить все блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10062,'Перец – по вкусу, соль может не понадобиться. Поварить еще 5 минут, затем кастрюлю снять с огня, дать постоять пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10063,'Нарезать репчатый лук, обжарить на сливочном масле до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10063,'Добавить размороженные белые грибы и жарить еще 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10063,'Долить куриный бульон, варить 20 минут. Снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10063,'Добавить сливки, соль, перец черный молотый и мускатный орех, измельчить все блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10063,'Подать суп к столу с сухариками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Картофель очистить, нарезать кусочками среднего размера. Залить водой, отварить, жидкость не сливать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Репчатый лук и грибы нарезать некрупно. Оставить несколько грибов для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Растопить сливочное масло, обжарить лук до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Добавить грибы, жарить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Обжарку переложить в кастрюлю с картофельным отваром, добавить молоко, сливки, соль, перец. Смесь измельчить при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Нарезать хлеб, посыпать сушеным укропом и солью, запечь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10064,'Разлить суп в тарелки, украсить свежей зеленью, гренками, целыми обжаренными грибами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10065,'Белые сушеные грибы замочить на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10065,'Отварить отдельно картофель и фасоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10065,'Нашинковать репчатый лук, спассеровать на масле, добавить размоченные грибы. Время обжаривания – 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10065,'В отваренный картофель добавить обжарку, фасоль, специи. Перемолоть в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10066,'Отварить очищенный картофель до готовности, слить воду и сделать пюре, добавив сливочное масло. В отдельной миске смешать фарш, манную крупу, тертый репчатый лук и яйцо. Посолить и поперчить массу по вкусу, добавить приправы (при желании), хорошенько перемешать чистыми руками, после чего поделить на 5 одинаковых кусков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10066,'Сковородку с растительным маслом разогреть, выложить в центр кусок подготовленного фарша и разровнять его так, чтобы получилась лепешка (будущий корж). Обжарить все 5 лепешек подобным образом с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10066,'Для крема нужно хорошенько мешать пропущенный через чесночницу чеснок с майонезом. Каждую готовую лепешку необходимо промазать получившимся майонезно-чесночным кремом и собрать их в торт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10066,'Сверху торт мясной из куриного фарша обмазать горячим картофельным пюре, затем смазать кетчупом и посыпать рубленой петрушкой. Бока торта обсыпать тертым сыром, лучше всего натертым на крупной терке, и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'Промыть белые сушеные грибы, замочить в новой порции воды на полтора часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'Картофель очистить и нарезать. Гречку промыть. Репчатый лук нарезать кубиками. Морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'Вскипятить воду, всыпать картофель, соль, гречку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'Лук и морковь обжарить, добавить грибы, немного муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'Переложить содержимое сковороды в кастрюлю, превратить в пюре при помощи блендера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10067,'По вкусу заправить суп сливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Морковь, кабачки, лук и картофель очистить и вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Лук и чеснок измельчить и обжарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Переложить в кастрюлю нарезанные кусочками овощи, потушить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Влить заранее сваренный куриный бульон, прогревать до тех пор, пока картофель, кабачки и морковь не станут мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Перелить бульон в отдельную миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Овощи превратить в пюре блендером, подлить горячие сливки, бульон до нужной консистенции.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10068,'Суп довести до кипения, огонь погасить. Посыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10069,'Отварить до готовности картофель, шампиньоны, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10069,'Добавить свежий шпинат, любые специи, прогревать еще три или четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10069,'Взбить массу при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10069,'При подаче подлить оливковое масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10069,'Сухарики положить в тарелку перед подачей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10070,'Отварить картофель в мундире, после чего корнеплоды почистить и нарезать кусочками. Отваренные вкрутую яйца почистить и нарезать кубиками, порезать колбасу некрупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10070,'Редис, огурцы и зелень помыть, порезать небольшими кубиками или кусочками. Сложить все подготовленные ингредиенты в большую посудину, посолить и залить либо квасом, либо заправкой из кефира и минералки (в соотношении 2:1).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10070,'Подается окрошка с редисом и свежей зеленью  порционно или в одной большой сервировочной емкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Прогреть сотейник, обжарить на оливковом масле мелко накрошенный кабачок цуккини, репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Добавить куриный бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Положить шпинат, все вместе варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'С помощью блендера сделать пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Влить сливки и всыпать сухой базилик, перец, соль, нарезанный кусочками плод авокадо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Суп разлить в тарелки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10071,'Добавить сыр «Филадельфия», выложить его чайной ложкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Репчатый лук нарезать полукольцами, обжарить на сливочном масле на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Переложить обжарку в кастрюлю, нарезанный кубиками картофель, подлить воду, варить до полной готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Всыпать специи, измельченный чеснок и укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Влить сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Положить шпинат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Все вместе варить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10072,'Взбить содержимое кастрюли блендером и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'На сухой сковороде или на противне подсушить орехи, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Подлить растительное масло на сковороду, разогреть, обжарить измельченный репчатый лук до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Довести до кипения бульон, положить в него готовую обжарку и нарезанный картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Варить в течение десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Добавить шпинат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Влить сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Довести до кипения, затем огонь уменьшить и прогревать еще несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Приправить суп любимыми специями.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Взбить все блендером.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10073,'Разлить суп в тарелки, посыпать орехами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Листья шпината вымыть, оборвать стебли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Зеленую массу обжарить в течение нескольких минут с оливковым маслом в сотейнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Добавить свежий базилик и посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Залить овощным бульоном, добавить сливки, все вместе тушить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Массу помешивать, иначе сливки могут пригореть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Налить оливковое масло на сковороду, обжарить мидии с белым вином и чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Прогревать, пока вино не выпарится.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Морепродукты посолить, поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Суп превратить в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10074,'Вылить в тарелку, добавить жареные мидии.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Приготовить куриный бульон, добавить в него нарезанный картофель, убавить огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Корень петрушки очистить и нарезать, обжарить до готовности на сливочном масле. Всыпать нарезанный кабачок, обжарить еще раз все вместе, добавить соль и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Долить в овощи немного бульона, затем добавить картофель, перемешать, тушить от одиннадцати до пятнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Переложить овощи в блендер, долить сливки, взбить до однородного состояния, влить в кастрюлю с бульоном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Натереть плавленый сыр, положить в суп, прогревать на тихом огне, перец и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10075,'Перед подачей добавить зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10076,'Кабачки вымыть, нарезать кусочками. Обжарить на сковороде с оливковым и сливочным маслом до полуготовности под крышкой. Время приготовления – от десяти до пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10076,'Нагреть молоко, влить в кабачки, добавить соль и специи, тушить пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10076,'Кабачки перемолоть в блендере вместе с жидкостью, добавить молоко до нужной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10076,'Перелить в кастрюлю, посолить, поставить на огонь, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Молодые кабачки и морковь очистить и крупно нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Почистить репчатый лук и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Овощи переложить в кастрюлю, добавить сахар и лавровый лист, долить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Суп довести до кипения, варить на тихом огне около двадцати минут, крышку не снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Через пять минут после начала варки удалить лавровый лист.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Овощи поместить в чашу блендера, размолоть до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Перелить пюре обратно в кастрюлю, поперчить, посолить, влить сливки, положить сливочное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Ингредиенты перемешать, поставить крем-суп на огонь, варить пять минут на тихом огне, помешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10077,'Снять с огня, дать постоять пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10078,'В холодной воде замочить ломтики белого хлеба, очищенный репчатый лук измельчить в очень мелкие кубики. Мелкими кубиками нарезать помытый болгарский перец и сыр фета. Вымытые цукини нарезать вдоль тонкими полосками и обжарить их в горячем масле (растительном) в течение 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10078,'Тщательно перемешать фарш с хлебом (отжатым), яйцом, горчицей, луком и тимьяном. Добавить к фаршу сыр и болгарский перец, соль и молотый перец и снова перемешать. Поделить получившуюся мясную массу на две одинаковые части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10078,'Форму выстелить бумагой для выпечки и первым слоем распределить по ней одну часть фарша, придав продолговатую  овальную форму. Вторым слоем выложить обжаренные полоски цукини, закрыть их оставшейся частью фарша.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10078,'Крупно натереть очищенный картофель, отжать всю жидкость, добавить соль и перемешать. Распределить, слегка придавливая, картофель по верху и бокам будущей запеканки. Готовится запеканка из фарша в картофельной шубке  в духовке в течение 1-1,5 часов при 200 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Натереть сыр, накрошить зелень, добавить в блюдо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10079,'Чеснок и репчатый лук спассеровать на оливковом масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10079,'Добавить морковь, жарить три минуты. Добавить картофель и кабачок, залить кипящей водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10079,'Посолить по вкусу, положить перец чили, сушеные томаты. Все вместе потушить двадцать минут, огонь – средний. Остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10079,'Приготовить пюре в блендере, добавить пучок рубленой петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Поставить воду на огонь, довести до кипения. Положить кубики картофеля и кабачков. Кабачки должны быть нарезаны немного крупнее, чем картофель. Варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Растолочь в ступе семена кориандра, корень имбиря. Переложить в суп. Через минуту огонь выключить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Слить бульон в отдельную миску, овощи измельчить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Добавить овощи обратно, поставить суп на огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Приправить блюдо сушеной зеленью, перцем, солью, дать закипеть и снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10080,'Разлить суп по тарелкам, добавить тертый сыр или сельдерей, свежую рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Кабачки цукини вымыть и нарезать кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Четверть нарезки обжарить для украшения перед подачей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Репчатый лук нарезать полукольцами, измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Клубни картофеля вымыть, нарезать кусочками среднего размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Разогреть в кастрюле растительное масло, обжарить до мягкости лук и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Всыпать цукини, прогревать пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Добавить картофель, подержать две минуты, затем влить овощной бульон, ингредиенты перемешать, варить около 20 минут до готовности овощей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Все овощи превратить в пюре при помощи погружного блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10081,'Отложенные кольца кабачков обжарить на растительном масле, посолить, разложить в тарелки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10082,'Репчатый лук и чеснок очистить и нарезать. Кабачки очистить, мякоть нарезать кусочками. Петрушку порубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10082,'В кастрюле разогреть сливочное масло, обжарить лук в течение пяти минут, добавить остальные овощи, прогревать еще пять минут, огонь – средний.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10082,'Посолить, долить  200 мл  воды, довести до кипения. Накрыть крышкой, варить пятнадцать минут, кабачки должны стать мягкими.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10082,'Всыпать зелень петрушки, через две минуты огонь погасить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10082,'Суп превратить в крем при помощи блендера. Влить сливки, блюдо поперчить по вкусу. Еще раз взбить суп блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/35/be9d3548373a435_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Грибы и лук нарезать мелким кубиком','https://vkuso.ru/data/cache/data/13/8ccd4bc63d12d13_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Обжарить лук.','https://vkuso.ru/data/cache/data/62/8d9a5e23fe57962_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Добавить грибы.','https://vkuso.ru/data/cache/data/f1/58d8766140e19f1_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Обжарить до испарения жидкости. Посолить. Добавить специи.','https://vkuso.ru/data/cache/data/6d/71d074064435c6d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'В картофельное пюре добавить яйца и муку. Замесить тесто.','https://vkuso.ru/data/cache/data/ad/06e025a99b310ad_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Берем тесто. Делаем кружок,кладем начинку. Защепляем края, формируя зразы.','https://vkuso.ru/data/cache/data/c0/989fbfc75a51fc0_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Обжариваем с двух сторон до золотистой корочки.','https://vkuso.ru/data/cache/data/ea/2adffe613d878ea_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10083,'Подаем к столу со сметаной.','https://vkuso.ru/data/cache/data/43/4551f8149b69d43_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10084,'Промытые и обсушенные куриные ножки натереть солью и черным молотым перцем. Сложить курицу в среднюю или большую посудину, посыпать сверху измельченным чесноком (не пропущенным через чесночницу), дать мясу постоять 10 минут. Затем куриные ножки обжарить со всех сторон на сковороде с растительным маслом, после чего выложить их на тарелку и дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10084,'Раскатать предварительно размороженное слоеное тесто в тонкий пласт и нарезать на тонкие полоски (полосок должно быть столько же, сколько и ножек). Каждую остывшую куриную голень вместе с косточкой обернуть тестяной полоской по спирали (снизу вверх).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10084,'Противень смазать маслом, выложить на него подготовленную курицу и смазать все ножки яичным желтком. Выпекать куриные ножки в тесте на протяжении 20-25 минут при температуре 200 градусов, пока не зарумянится тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10085,'Крылышки, помоем и обсушим. Нальем масло растительное и чеснок. Хорошо перемешаем. Выпекаем в разогретой до 200 градусов духовке примерно 30-40 минут. Лучше положить крылья на решетку, так они лучше запекутся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10085,'В сотейнике или кастрюле с толстым дном смешаем мед, кетчуп, вустерский соус, перец и сливочное масло. Ставим на огонь и увариваем, чтобы соус немного загустел.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10085,'Готовые крылья смешиваем с соусом и ставим обратно в духовку, можно включить гриль, на 200 градусов, на 5-10 минут.','https://vkuso.ru/data/cache/data/c7/5edddba253c2fc7_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Очистить клубни картофеля, морковь, кабачки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Измельчить лук и чеснок, обжарить в кастрюле на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Остальные овощи нарезать кусочками средней величины, добавить в кастрюлю и тушить семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Влить заранее сваренный куриный бульон. Все вместе прогревать до тех пор, пока овощи не станут мягкими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Отлить бульон в отдельную миску, прогреть сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Овощи взбить до однородности, добавить куриный бульон и сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10086,'Прогреть суп пять минут, снять с огня. Подать на стол через пятнадцать или двадцать минут – блюдо должно настояться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10087,'Почистить и вымыть кабачки, морковь, картофель и репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10087,'Морковь и лук взбить в блендере, кабачки и картофель нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10087,'Налить воду в кастрюлю, довести до кипения, добавить картофель и кабачки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10087,'Лук и морковь обжарить на растительном масле до золотого цвета. Добавить обжарку в бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10087,'Все овощи и бульон перелить в блендер, взбить, посолить и поперчить, всыпать зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10088,'Филе индейки, промытое и обсушенное бумажным полотенцем, порезать порционными кусками, но не очень большими. Разогреть в объемной сковородке растительное и сливочное масло, добавить кусочки мяса и обжарить их до подрумянивания на среднем огне, добавить соль и перец по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10088,'Нарезать очищенный картофель небольшими кубиками и добавить в сковородку с мясом и обжарить все вместе в течение 10 минут, затем  к картофельно-мясной смеси добавить предварительно нашинкованный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10088,'К содержимому сковородки добавить болгарский красный перец, нарезанный соломкой, все посолить и поперчить по вкусу, перемешать и  жарить в районе 10 минут. За 5 минут до полной готовности блюдо нужно опять поперчить, посолить, добавить сушеный тимьян, паприку и измельченный любым удобным способом чеснок, все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10088,'Прежде чем снять жаркое из индейки с тимьяном и паприкой  с огня, его нужно приправить рубленой петрушкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10089,'Тыквенную мякоть, кабачки и репчатый лук нарезать кубиками одного размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10089,'Переложить на противень, посыпать овощи молотым кориандром, поперчить, посолить, добавить сливочное масло и рубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10089,'Ингредиенты перемешать, поставить в духовку на 20 минут, температура приготовления – от 140 до 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10089,'Тушеные овощи переложить в кастрюлю, влить бульон и горячее молоко, варить семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10089,'Суп немного остудить, взбить в блендере до однородного состояния, затем подогреть и дать постоять еще 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Нарезать крупно кабачки и сладкий болгарский перец, картофель, морковь, сельдерей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Лук-порей нашинковать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Налить в кастрюлю растительное масло, добавить лук и все остальные овощи, жарить семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Влить 3 литра воды, прогревать до готовности овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Взбить готовые овощи блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Всыпать рубленый чеснок, молотый перец, соль, лавровый лист, петрушку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10090,'Все вместе прокипятить в течение трех минут, снять с огня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Овощи вымыть и очистить. Измельчить лук-порей и чеснок, петрушку и укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Кабачки, картофель, болгарский перец нарезать кубиками небольшого размера. Морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Куриный бульон довести до кипения, заправить лавровым листом, всыпать картофель, варить 20 минут на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Подержать на огне две или три минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Морковь и лук обжарить в течение семи или десяти минут на сливочном масле, добавить сладкий перец, прогревать еще четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Добавить кабачки, потушить все вместе еще несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Переложить обжарку в бульон, добавить соль, тимьян, кориандр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Почти готовый суп довести до кипения, варить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Положить чеснок и плавленый сыр, перемешать, довести блюдо до кипения, снять с огня.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10091,'Содержимое кастрюли взбить при помощи блендера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10092,'Картофель отварить до готовности с корнем сельдерея и репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10092,'Обжарить листья шпината на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10092,'Все ингредиенты взбить блендером, при помощи блендера сделать массу пюреобразной и однородной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10092,'Перелить в кастрюлю, положить специи, влить сливки, суп довести до кипения, погасить огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10092,'Яйцо «пашот» сварить отдельно, добавить в тарелку с супом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Свеклу отварить до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Куриные грудки варить в течение сорока минут. Куриную грудку вынуть из бульона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Репчатый лук, морковь и картофель очистить, вымыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Морковь натереть, репчатый лук нарезать соломкой. Обжарить на масле до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Кабачки и картофель нарезать соломкой. То и другое добавить в бульон, увеличить огонь, добавить обжарку, варить пятнадцать минут. Снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Свеклу натереть в суп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Перелить суп в чашу блендера, взбить, вернуть в кастрюлю. Довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10093,'Влить сливки. Еще раз довести до кипения, снять с огня, положить в каждую тарелку заранее отваренную белую фасоль, петрушку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Репчатый лук и морковь очистить и разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Сладкий болгарский перец вымыть, удалить семена, плоды также разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Влить воду в кастрюлю, поставить на огонь, добавить зелень, черный перец, соль, лавровый лист. Довести до кипения, варить 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Кабачки вымыть, почистить и нарезать колечками, картофель – кубиками. Треть кабачков отложить отдельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Репчатый лук нарезать полукольцами, обжарить на масле, всыпать рубленый чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Добавить часть кабачков, тушить семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Положить картофель, тушить четыре минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Обжарку пересыпать в бульон, варить двадцать минут, овощи должны стать мягкими.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Отложенные вначале кабачки посолить, поперчить, посыпать другими специями. Жарить на масле до румяной корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Суп взбить при помощи блендера, вернуть в кастрюлю, прогреть и снять с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10094,'Готовый суп разлить в тарелки, в каждую положить по обжаренному кабачку и листочку петрушки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10095,'Соединяем в сотейнике мед, сахар, специи, ставим на огонь. Хорошо перемешиваем, варим до растворения сахара. Снимаем с огня, добавляем соду, хорошо перемешиваем, масса начинает пениться и увеличиваться в размере. Остужаем и добавляем яйцо, перемешиваем.  По чуть-чуть добавляем муку, лучше вмешать меньше муки. Тесто получается мягким и не липнет к рукам. Отправляем в холодильник минимум на 1 час. Можно сделать тесто заранее и заморозить.','https://vkuso.ru/data/cache/data/58/1d0e4f1f617ce58_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10095,'Раскатываем тесто примерно толщиной миллиметра 3. Вырезаем фигурки. В этот раз мы решили сделать пряники с изюминкой. Вырезали внутри маленький кружок и положили обычные леденцы, которые в духовке расплавятся. Лучше запекать на пергаменте для выпечки. Ставим заранее разогретую духовку до 180 градусов на 7-10 минут. Время зависит и от духовки и от желаемой жесткости пряников. Хотите мягче пеките 7 минут. После духовки даем остыть пряникам и застыть карамели, только после этого снимаем с пергамента. Хранятся они довольно долго, мы храним в холодильнике.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10102,'Кусок говядины отварить в воде до полной готовности, дать ему остыть и порезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'При подаче блюдо украсить тонкими кусочками перца чили и сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10096,'С кочана капусты снять верхние листья, сам кочан хорошенько промыть под проточной водой. В большую кастрюлю влить воду и дать ей закипеть, после чего на 3-4 минут положить в нее подготовленный кочан. Когда пройдет отведенное время, капусту нужно достать из воды и дать ей остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10096,'Для фарша смешать говяжий и свиной фарш с заранее отваренным рисом, яйцом, нашинкованным репчатым луком, рубленой петрушкой, молотым перцем, паприкой и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10096,'От остывшего кочана капусты отделить нужное количество листов, выложить на каждый небольшое количество получившейся мясной начинки, сложить все листы конвертиками. Если получилось так, что фарша больше не осталось, а капуста еще есть, ее нужно нашинковать и переложить в чистую кастрюлю. Поверх свежей капусты выложить слой квашенной, затем несколько подготовленных голубцов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10096,'Для соуса смешать в миске томаты в собственном соку, томатную пасту, коричневый сахар, куриный бульон, соль, пропущенный чрез пресс чеснок и молотый перец. Слой голубцов залить половиной получившегося соуса, накрыть их слоем из капусты. На капусту выложить оставшиеся голубцы и залить их остальным томатным соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10096,'Кастрюлю накрыть крышкой, поставить на огонь, дать соусу закипеть, после чего убавить огонь и готовить голубцы в томатном соусе с квашеной капустой на протяжении 2-2,5 часов до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10097,'Вымыть огурцы, взять 2 стерилизованные литровые банки, положить в каждую по паре листиков смородины и листику вишни (предварительно их вымыть), добавить по паре зубчиков чеснока, плотно заполнить банки огурцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10097,'Закипятить воду, осторожно залить в банки, прикрыть крышками, дать постоять четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10097,'Приготовить маринад: в кастрюлю с 1 литром воды добавить соль с сахаром и гвоздику, перемешать, прокипятить пару минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10097,'Слить воду из банок с огурцами и залить кипящим маринадом, влить в каждую банку по чайной ложке эссенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10097,'Закатать банки  с классическими сладкими маринованными огурцами, перевернуть, закрыть чем-нибудь теплым, дать остыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10098,'Подготовить мясо, если надо порезать на куски, сложить его в лоток, перемешать с майонезом, соевым соусом, тмином, дать постоять минимум полчаса, но лучше дольше, если время позволяет, то можно и на ночь оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10098,'Обжарить курочку на сухой сковороде с двух сторон до появления хрустящей корочки или запечь в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10099,'Подготовить грибы, перебрать, вымыть, очистить от налипшего мусора, порезать на куски, прокипятить в подсоленной воде четверть часа, откинуть на сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10099,'Овощи вымыть, почистить, порезать на крупные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10099,'Выложить на прогретую сковороду с маслом в первую очередь чеснок, через полминуты добавить лук, через минуту помидоры, протушить пару минут, положить грибы, перемешать, обжаривать 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10099,'Дать смеси чуть остыть, прокрутить на мясорубке или измельчить блендером, вернуть в сковородку, дать массе закипеть, на слабом огне потомить 25 минут, посолить, поперчить, добавить сахар, размешать, подержать на плите еще 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10099,'Икра из грибов и овощей на зиму готова. Для длительного хранения надо добавить по 1 ч.л. уксуса на пол литровую банку и простерилизовать 30 минут, закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10100,'Почистить овощи, кабачок и морковь натереть, чеснок раздавить прессом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10100,'Лук нашинковать и обжарить вместе с чесноком и пореем, добавить в конце морковь, тушить до полуготовности, положить кабачок, перемешать, тушить еще около 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10100,'Переложить овощи в форму, подсолить, поперчить, залить разболтанными яйцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10100,'Поставить запеканку из кабачков с сыром рикотта в прогретую до 200 градусов духовку на треть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10100,'Достать форму, присыпать сыром с петрушкой, запекать еще 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10101,'Крупно натереть кабачок, а чеснок с сыром – мелко, перемешать, вбить яйца, добавить крахмал, соду, муку, подсолить, хорошо все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10101,'Разогреть сковороду с небольшим количеством масла, обжарить оладьи из кабачков с сыром с двух сторон при среднем нагреве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Содержимое сотейника тушить час или полтора.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10102,'Промыть свежие огурцы, петрушку и укроп, после чего огурцы порезать, а зелень порубить. Сложить мясо и огурцы в большую миску или кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10102,'Сметану перемешать с небольшим количеством кваса и залить смесью мясо с овощами. Содержимое посудины перемешать, влить остальной квас и еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10102,'Перед подачей мясная окрошка со свежим огурцом посыпается рубленым укропом и петрушкой и подается либо порционно, либо в большой красивой посудине.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10103,'Подготовить грибы, помыть, порезать, высыпать на прогретую сковороду с маслом, обжаривать на большом огне пока не останется влаги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10103,'Огонь убавить, грибы подсолить, немного еще обжарить, дать хорошо остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10103,'Для заморозки обжаренных грибов на зиму разложить небольшими порциями их по пакетам, сплющить между ладонями (до 1 см толщиной), положить на доске в морозилку, потом доску убрать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10104,'Молодой кабачок натереть мелко, если у него уже грубая кожура, то предварительно почистить и удалить семечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10104,'Чеснок порубить, перемешать с тертым сыром, добавить яйца, масло, порубленный укроп, перемешать с кабачком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10104,'Подсоленную муку смешать с разрыхлителем, высыпать в кабачковую массу, вымесить однородное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10104,'Подготовить формочки, заполнить кабачковой массой, поместить маффины из кабачков с сыром моцарелла в прогретую заранее до 180 градусов духовку примерно на треть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'Подготовить овощи, кроме помидоров, почистить, крупно натереть или измельчить на комбайне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'Помидоры порубить в блендере до однородного жидкого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'В кастрюлю с толстым дном налить масло, положить овощи, влить треть уксуса с водой, тушить четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'К полученной массе вылить измельченные помидоры, добавить остаток уксуса, приправить перцем, лавровым листом, добавить сахар, поперчить и посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'Тщательно всё перемешать, дать закипеть, тушить около получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10105,'Горячую овощную заготовку для борща на зиму разложить по банкам, хорошо завинтить крышки, перевернуть их вверх дном, дать остыть под тёплым одеялом, хранить можно в комнате.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Тыкву тщательно вымыть при помощи щетки, вынуть семена, мякоть нарезать кусочками по два или три сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Репчатый лук и морковь почистить и мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Сначала обжарить лук в течение пяти минут на растительном масле, массу помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Добавить морковь, обжарить до румянца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Овощи снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Выложить нарезанную мякоть тыквы в кастрюлю, залить водой, довести до кипения под крышкой, варить до размягчения тыквы на небольшом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'В конце приготовления посолить и поперчить, приправить щепотью муската.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Добавить обжарку, взбить погружным блендером в пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'Положить кусочек сливочного масла, прогреть, помешивая, до первых признаков закипания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10106,'При подаче сбрызнуть суп жирными сливками, украсить листочками зелени.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Тыкву разрезать на две половины, середину с семечками вынуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Срезы присыпать зирой, порошком карри, сушеным тимьяном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Сверху положить иголочки розмарина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Время запекания в духовом шкафу – от 40 до 50 минут, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Мякоть вынуть ложкой, влить овощной или куриный бульон, кокосовое молоко, взбить погружным блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10107,'Выложить в тарелки на крем шалфей, посыпать очищенными семечками тыквы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Клубни картофеля, тыкву, чеснок и лук очистить и нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Разогреть в кастрюле сливочное масло, обжарить накрошенный лук и чеснок в течение двух минут',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Всыпать кубики тыквы и картофеля, карри, потушить смесь в течение минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Влить овощной бульон, все вместе довести до кипения, варить полчаса на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Смесь взбить погружным блендером.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10108,'Добавить сметану, соль, перец, молотый мускатный орех, кайенский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Тыкву очистить и нарезать, выложить в жаропрочную емкость, посолить и сбрызнуть оливковым маслом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Печь в духовом шкафу при температуре 180 градусов, время приготовления – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Свежие шампиньоны очистить и порезать, измельчить репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Сначала обжарить лук на сковороде, потом туда же выложить грибы, потушить до румяной корочки на сильном огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Печеную тыкву положить в кастрюлю, залить заранее подогретыми сливками, пробить блендером в пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Массу довести до кипения на среднем огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10109,'Суп при подаче украсить дольками шампиньонов, тыквенными семечками и сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Нарезать кусочками мякоть тыквы, морковь и куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Измельчить репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Мясо и лук обжарить в кастрюле на тихом огне в течение пяти или семи минут на оливковом масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Добавить тыкву и морковь, влить заранее приготовленный куриный бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Все вместе варить 20 минут, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Приготовить пюре при помощи блендера и еще немного прогреть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Тонкие, прозрачные ломтики копченого бекона обжарить до хрустящей корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10110,'Положить в тарелки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10111,'Растереть в миске сухие дрожжи с солью, влить туда же молоко, всыпать сахар и перемешать. Далее добавить маргарин (мягкий) и муку, замесить тесто и убрать его на 5-6 часов в холодильник. Для начинки перемешать до однородности сливочное масло с сахаром и молотой корицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10111,'Охлажденное тесто разделить на кусочки, каждый из которых сначала нужно скатать в шарик, а затем раскатать в жгут. Каждый тестяной жгутик раскатать в лепешку, смазать получившейся начинкой и свернуть рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10111,'Из каждого получившегося рулета свернуть «улиточку», сделать по всей тестяной заготовке небольшие надрезы ножницами. Все получившиеся заготовки слегка присыпать сахаром и переложить их на заранее смазанный маргарином противень. Запекать плюшки «Хризантема»  с корицей в духовке до золотистого цвета при 180 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Измельчить морковь, мякоть тыквы, красный репчатый лук, корень сельдерея, чеснок, свежий перец чили.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Перец и чеснок обжарить в кастрюле в течение полуминуты, добавить иголочки розмарина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Добавить все нарезанные овощи, кроме тыквы, жарить на среднем огне до полуготовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Посолить и поперчить по вкусу, выложить тыкву.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Влить куриный или овощной бульон, он должен покрывать овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Суп должен закипеть, варить под крышкой на минимальном огне, время – от 30 до 45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Приготовить гренки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Нарезать батон на ломтики средней толщины, корочку удалить, мякиш покрошить кубиками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'На сковороде разогреть сливочное масло, жарить хлеб до румяной корочки на сильном огне со всех сторон, присыпать мелкой солью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Кусочки высыпать на бумажное полотенце, чтобы впитался лишний жир.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Посыпать гренки сушеным чесноком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Из супа удалить розмарин.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Массу пробить блендером до получения пюре.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Соль – по вкусу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Влить сливки средней жирности, суп перемешать.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10112,'Подать с гренками.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Мякоть тыквы нарезать крупными кусками, залить водой, варить в течение 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Нарезать клубни картофеля небольшими кубиками, репчатый лук – полукольцами, морковь – мелкими брусочками или кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'На сковороде обжарить лук, добавить картофель и морковь, овощи подрумянить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Долить воду, она должна закрыть ингредиенты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Жидкость должна частично выкипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Слить воду, добавить в тыкву обжарку, приготовить пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Постепенно вмешать сливки, сливочный сыр, молоко.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Тонко нарезать куриное филе, положить в суп.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Сыр натираем на мелкой терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Массу довести до кипения, посолить и поперчить, добавить орегано и чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10113,'Все вместе варить до полной готовности мяса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Нарезать небольшими кубиками репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Тыкву очистить, нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'На тихом огне в кастрюле обжарить лук, всыпать морковь, овощи перемешать и потушить под крышкой до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Крупно нарезать чеснок, порубить зелень петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Добавить чеснок в обжарку, перемешать, переложить тыкву.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Подлить кипяток, тушить под крышкой до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Для приготовления сухариков понадобится батон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Мякиш нарезать кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Противень застелить пергаментом, высыпать хлеб, посолить, посыпать гранулированным чесноком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Побрызгать оливковым маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Сушить в духовом шкафу при температуре 150 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'В овощную массу всыпать рубленую петрушку, кориандр и другие специи, соль.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Приготовить пюре при помощи блендера.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Долить сливки средней жирности, помешать и довести суп до кипения.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10114,'Сухарики положить в тарелки при подаче, украсить блюдо листочками свежей петрушки.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Тыкву, морковь, кабачок цуккини, репчатый лук, чеснок очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Все нарезать крупными кубиками, кроме чеснока и лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Для приготовления супа понадобится толстостенная кастрюля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Сначала обжарить в ней чеснок и лук, затем добавить все остальные овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Положить специи: листья шалфея, веточку розмарина, лавровый лист.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Жарить овощную массу до румянца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Затем всыпать красную чечевицу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Травы вынуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Подлить кипяток, содержимое кастрюли должно быть покрыто на два сантиметра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Соль – по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Варить суп под крышкой, время 25 минут после закипания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Приготовить пюреобразную массу при помощи блендера.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'Отдельно обжарить на оливковом масле кубики белого хлеба, присыпать их смесью сухих ароматных трав, тех же, что использовались при приготовлении супа: шалфей, розмарин, тимьян. Посолить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10115,'При подаче положить в тарелку, украсить тертым твердым сыром.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Тыкву очистить и нарезать крупными кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Переложить овощ в жаропрочную емкость, присыпать листочками богородской травы, полить оливковым маслом и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Время запекания в духовом шкафе – 30 минут, температура – 170 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Овощную массу переложить в чашу блендера, долить заранее приготовленный овощной бульон, превратить в пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Массу перелить в кастрюлю, варить на тихом огне пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Влить сливки, всыпать паприку, перемешать, дождаться кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'Еще раз перелить в чашу блендера, размолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10116,'При подаче посыпать суп измельченным козьим сыром, крутонами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10117,'Отварить грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10117,'Нашинковать крупно лук, обжарить его до незначительного изменения цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10117,'Добавить в сковороду грибы, обжаривать до испарения жидкости, поперчить посолить, можно добавить любимую приправу, тушить около 4 минут, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10117,'Переложить грибную смесь в чашу блендера, к паштету из грибов добавить сыр, перемешать всё до однородного состояния, разложить  по баночкам, убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'3 ст. л. муки просеять в большую миску, всыпать к ней дрожжи, влить теплое молоко, перемешать и убрать в сторону. Масло сливочное растопить, перелить в отдельную емкость, всыпать соль, обычный и ванильный сахар, добавить яйцо и растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'Все хорошенько перемешать, перелить в миску с опарой, порциями подмешать оставшуюся муку (предварительно просеянную), вымешивать массу, пока не получится мягкое тесто. Получившееся тесто положить в миску, прикрыть пищевой пленкой и убрать на 40 минут в теплое место, чтобы опара подошла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Лаваш нарезаем на равные части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'Промытые и очищенные яблоки мелко натереть на терке, образовавшийся сок отжать, добавить пару столовых ложек сахара (при желании можно больше). Рабочую поверхность посыпать мукой, переложить на нее подошедшее тесто, которое затем чуть обмять и разделить на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'В прямоугольный пласт раскатать каждую часть теста, промазать их небольшим количеством сливочного масла. Поверх масла нанести сначала немного вареной сгущенки, а затем половину подготовленной яблочной начинки. Оба пласта свернуть в не очень тугие рулеты и нарезать каждый кусочками средней ширины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'Выстелить форму промасленным пергаментом, выложить на него булочки срезами вверх на небольшом друг от друга расстоянии, накрыть пищевой пленкой и отставить ее в сторону на 10 минут. Заготовки смазать взбитым яйцом и чуть присыпать обычным или коричневым сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10118,'Выпекать булочки из быстрого теста с яблоком при 180 градусах, пока они хорошенько не поднимутся. Далее температуру можно увеличить до 200 градусов и выпекать изделия, пока они не станут золотистыми. Готовые булочки, не доставая из формы, накрыть чистой салфеткой и дать им так остыть, после чего аккуратно разделить их ножом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'Баклажаны разделить на 2 половинки, удалить сердцевину, чуть присолить, дать постоять полчаса, хорошо промыть водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'Смазать их маслом и отправить на полчаса в прогретую до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'Лук нашинковать вместе с морковью и помидорами мелкими кубиками, чеснок раздавить прессом, порубить вынутую из баклажанов серединку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'Разогреть масло, обжарить чеснок и лук, добавить морковь и фарш, хорошо размешать, жарить до изменения цвета фарша.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'В последнюю очередь добавить в смесь мякоть от баклажанов и помидоры, приправить хмели-сунели, солью и перцем, тушить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10119,'Плоды баклажанов наполнить полученной массой, сверху на баклажаны, запеченные с фаршем положить крупно тертый сыр, поставить в духовку, запекать до появления корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10120,'Вареное яйцо и плавленый сыр натереть на крупной терке. Консервированную рыбу и свежий огурец порезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10120,'Сложить подготовленные ингредиенты в миску, добавить туда же майонез и все тщательно перемешать. Получившейся начинкой наполнить готовые тарталетки и украсить их по своему вкусу. Тарталетки с огурцом и красной рыбой готовы!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10121,'Хорошо перемешать манку с геркулесом сахаром и солью, залить кефиром, дать постоять пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10121,'Вилкой разболтать яйца, положить соду, размешать, вылить в тесто, вымешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10121,'Необычные оладьи из овсянки и манки на кефире выпекать на смазанной маслом и хорошо прогретой сковороде, как обычные оладьи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10122,'Ягоды перебрать, высыпать в эмалированную кастрюлю, влить воду, дать закипеть, сделать нагрев минимальным, поварить 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10122,'Газ отключить, всыпать весь сахар, размешать до его растворения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10122,'Дать варенью-желе из черной смородины остыть, разложить по стерилизованным баночкам, закрутить крышками, убрать желе на зимнее хранение в прохладное место.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10123,'Заранее прогреть до 170 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10123,'Взять форму, промазать маслом, присыпать мукой или манкой, излишки высыпать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10123,'Размешать мягкое масло с сахаром, добавить протертый творог, вымешивая, ввести одно за другим яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10123,'Перемешать полученную массу с мукой и разрыхлителем, вымесить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10123,'Заполнить форму тестом, выпекать очень простой и вкусный творожный кекс около часа, дать остыть на решетке, вынуть из формы, присыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10124,'В сотейник с толстым дном насыпать сахар, поставить на небольшой огонь, дать ему расплавиться, перемешивая сахар наклонами из стороны в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10124,'Подогреть сливки практически до кипения, в потемневший сахар осторожно влить сливки, постоянно помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10124,'Прогреть полученную массу пару-тройку минут, до полного растворения сахара и получения однородной карамели.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11970,'Чашу мультиварки смазать сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10124,'Переложить карамель в подходящую посуду, добавить масло, перемешать до получения однородной массы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10125,'Удалить у креветок панцири, чуть присолить, поперчить кайенским перцем, добавить паприку, порубленную петрушку с чесноком, влить масло, тщательно и аккуратно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10125,'Прогреть все на сковороде до изменения цвета креветок, подавать креветки пиль-пиль по-испански сразу к столу, чтобы они не успели остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Пшеничную муку просеять в емкость большого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Всыпать какао-порошок и сахар, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Отдельно вбить сырые куриные яйца в кефир или несладкий йогурт, добавить растительное масло, также перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Соединить обе смеси и перемешать до однородного состояния при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Шоколадную плитку порубить крупными кусочками и добавить в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Смазать маслом форму для выпекания, налить тесто, поставить в духовой шкаф на 40 минут, температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10126,'Готовность выпечки можно проверить зубочисткой. Кекс остудить, полить шоколадом и присыпать рублеными грецкими орехами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'Филе курицы нарезать поперек волокон, кусочки должны быть тонкими, по 7 – 10 миллиметров толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'Отбить молотком через полиэтиленовую пленку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'В одну мисочку разбить куриное яйцо, в другую насыпать муку, в третью – панировочные сухари.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'В яйца добавить любимые специи и соль, взболтать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'Отбивную обвалять в муке, затем в яичной смеси и панировочных сухарях.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10127,'Выложить на заранее разогретую сковороду, жарить по две или три минуты с каждой стороны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10128,'Очищенный чеснок порезать тонкими ломтиками, репчатый лук нарезать кольцами. Для того чтобы приготовить маринад необходимо в кастрюлю налить воду, добавить в нее подготовленный лук и чеснок, черный перец, гвоздику, соус чили и лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10128,'Поставить кастрюлю на огонь, дать ее содержимому покипеть в течение 15 минут, после чего положить в маринад предварительно порезанные сегментами ребра: они должны быть покрыты маринадом. Дать маринаду закипеть, затем уменьшить огонь и варить ребрышки на протяжении 1 часа, но не меньше. Если во время варки маринад не будет покрывать ребра, в кастрюлю нужно влить недостающее количество кипятка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10128,'Когда ребрышки будут полностью готовы их нужно достать из кастрюли и выложить на тарелку остывать, затем обсушить бумажным полотенцем или салфеткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10128,'Для глазури нужно в кастрюльку влить 1 стакан маринада, в котором варились ребрышки, и варить его, пока в посудине не останется половина от первоначального объема. Не снимая кастрюльку с огня, добавить к маринаду кленовый сироп, белый винный уксус, зернистую горчицу, соус чили и соль. Все перемешать и кипятить при периодическом помешивании, пока не получится соус однородной консистенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10128,'Противень выстелить фольгой и выложить на него подготовленные мясные ребрышки, равномерно покрыть их получившейся глазурью (лучше это сделать кисточкой). Поставить противень на среднюю полку духовки и запекать ребра при 220 градусах около 10 минут до подрумянивания. Далее ребрышки  нужно перевернуть, также смазать глазурью и запекать при такой же температуре в районе 5-7 минут. Готовые мясные ребрышки в глазури вынуть из духовки, остудить, выложить на тарелку или сервировочное блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Отварить и нарезать одинаковыми кубиками морковь, картофель, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Точно также поступить с мясной составляющей – запеченной бужениной (ее можно заменить вареной колбасой и отварным мясом).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Нарезать кубиками маринованные и свежие огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Открыть банку с зеленым горошком и слить жидкость. Нарезать зелень укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Все перечисленные ингредиенты перемешать с майонезом, поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Стакан смазать растительным маслом и поставить его в середине блюда. Вокруг выложить салатную массу, прижать ложкой, стакан осторожно вынуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Разлить массу в кокотницы, посыпать каждую порцию тертым сыром, накрыть фольгой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10129,'Украсить венок веточками укропа, нарезанными маслинами, половинками отваренных перепелиных яиц, полосками или звездочками желтого и красного болгарского перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10130,'Замороженные крабовые палочки натереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10130,'Отварить куриное яйцо и также натереть вместе с плавленым сыром, его лучше заранее охладить в морозильной камере в течение 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10130,'Перемешать половину нормы крабовых палочек, сыр и яйцо, добавить давленый чеснок, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10130,'Перемешать и сформовать небольшие шарики, это лучше делать мокрыми руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10130,'Обвалять в оставшейся крабовой стружке и выложить на блюдо. Тарелку можно выложить листьями зеленого салата.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'Репчатый лук нарезать полукольцами, сладкий болгарский перец нашинковать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'Помидоры разрезать пополам, а затем поперек на пластинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'В рыбе сделать небольшие надрезы. Приправить специями, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'На каждый рыбный кусок приготовить по листу фольги, смазать их оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'Выложить лук, поверх – рыба, помидоры и перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'Прикрыть рыбу фольгой и хорошо защепить край. Время запекания – полчаса, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10131,'Фольгу развернуть, печь еще восемь минут, температуру увеличить до 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10132,'Вбить в творог сырые куриные яйца, добавить немного соли, сахар, манную крупу, муку, ванильный сахар из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10132,'Ингредиенты хорошо перемешать, тесто оставить на полчаса, накрыть пищевой пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10132,'Сформовать сырники, обвалять в муке, жарить на масле до появления румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10132,'Подать к столу с натуральным медом, сметаной или любимым вареньем, джемом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Филе индейки нарезать кусочками небольшого размера, обжарить на масле, на заранее прогретой сковороде с толстым дном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Подлить воду и потушить мясо в течение получаса на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Репчатый лук очистить и нарезать кубиками, обжарить на другой сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Морковь очистить и нарезать мелкой соломкой, добавить к луку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Очистить от кожуры и нарезать баклажаны небольшими кусочками, так же поступить с кабачком. Если кожица мягкая, то ее снимать необязательно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Морковную обжарку переложить в мисочку, на сковороде обжарить кабачки с баклажанами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Нарезать соломкой сладкий болгарский перец, кубиками – помидоры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Оба ингредиента добавить к баклажанам вместе с луковой обжаркой. Добавить в овощи филе.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Разбавить водой или мясным бульоном томатную пасту, влить в сковороду. Соль и перец молотый – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'Блюдо тушить под крышкой в течение пяти или семи минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10133,'В самом конце добавить фасоль из банки, рубленую зелень укропа и давленый чеснок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/2b/107a2248dc3b62b_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'Яйца и крабовые палочки нарезать - кубиком. Укроп мелко порубить. Сыр натрем на крупной терке.','https://vkuso.ru/data/cache/data/2c/1b7188f288a4e2c_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'В майонез выдавить чеснок. Перемешать.','https://vkuso.ru/data/cache/data/c7/db5e8ada31dfec7_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'Добавить остальные продукты.','https://vkuso.ru/data/cache/data/2e/12b9ba54823202e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'Выложить продукты в тарталетки и украсить укропом.','https://vkuso.ru/data/cache/data/94/7a5c4c4241ad794_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10134,'Приятного аппетита.','https://vkuso.ru/data/cache/data/2a/5a565593970002a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10135,'Кальмары отвариваем в кипящей подсоленной воде 2-3 мин ( не дольше ). Креветки отвариваем также в кипящей подсоленной воде не более 1-2 мин.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10135,'Пекинскую капусту нарезаем тонкой соломкой, кальмары очищаем от лишних пленочек и нарезаем соломкой, креветки очищаем.','https://vkuso.ru/data/cache/data/d8/23fc2cc484477d8_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10135,'Кладем все в одну посуду, добавляем маслины, сок лимона, черный молотый перец, солим по вкусу и заправляем оливковым маслом. Сразу же подаем к столу! Приятного аппетита!!!','https://vkuso.ru/data/cache/data/58/7e65d7051ed8e58_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Потереть помытые и очищенные яблоки на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10136,'Каждую тестяную пластину раскатать в прямоугольник длиной в 30 см и нарезать их на длинные полосы толщиной в 3 см. Из кондитерской бумаги вырезать столько треугольников, сколько получилось тестяных полосок. Все треугольники свернуть в кулечки-корнетики, каждый из которых обернуть, начиная с узкого конца, подготовленными полосками (1 корнетик=1 полоска теста).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10136,'Выложить заготовки швом вниз на противень, смазать каждую взбитым яичным желтком и выпекать все при 180 градусах в районе 20-25 минут. Для приготовления белкового крема нужно в кастрюльку влить воду, добавить сахар и нагреть смесь до 118 градусов — температуру можно измерить специальным термометром. Если такового термометра нет, в холодную воду нужно капнуть немножко сиропа – если в воде сразу же образуется шарик, значит, сироп достиг нужной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10136,'Со щепоткой лимонной кислоты взбить отделенные от желтков белки до состояния крепкой пены. На максимальной скорости миксера влить в белки получившийся сироп и взбивать массу, пока она не остынет. Получившимся кремом наполнить кондитерский мешок и аккуратно заполнить им все испеченные трубочки. Трубочки из готового слоеного теста  с  кремом украсить сахарной пудрой и выложить на сервировочное блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Очистить авокадо, мякоть нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Помидоры надрезать крест-накрест, опустить на несколько секунд в кипяток и снять кожицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Также нарезать кубиками вместе со сладким болгарским перцем, крабовыми палочками, сырами «Пармезан» и «Сулугуни».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Порубить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Продукты перемешать, посолить и поперчить, по желанию добавить сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10137,'Готовый салат при подаче можно посыпать консервированным зеленым горошком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Перепелиные яйца отварить, авокадо очистить, натереть свежий огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Измельчить крабовые палочки, слобосоленую рыбу, авокадо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Выложить на блюдо слоями: авокадо, рыбу с яйцами, промазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Третий слой – крабовые палочки, затем огурец и майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Посыпать тертым твердым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'Тонко нарезанной семгой покрыть всю поверхность салата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10138,'В центре положить ложку красной икры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10139,'Авокадо очистить, косточку вынуть, нарезать мякоть кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10139,'Измельчить репчатый лук, крабовые палочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10139,'Открыть банку со сладкой кукурузой, слить жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10139,'Ингредиенты перемешать, добавить соль и молотый перец, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10139,'Выложить массу на тарелку, украсить веточками укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Если осьминоги крупные – их нужно отбить кулинарным молотком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Мелких представителей моря достаточно вымыть, вынуть внутренности из головы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Налить воду в кастрюлю, добавить репчатый лук, помидоры, сладкий красный перец, зелень сельдерея и укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Дать закипеть, положить осьминогов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Маленькие особи сварятся через несколько минут, крупные – за час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Готовность проверить вилкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Отварить яйца, натереть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Очистить и нарезать авокадо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Выложить в глубокую емкость осьминогов, остальные продукты, добавить сладкую кукурузу из банки, нарезанные крабовые палочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Салат посолить и поперчить по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Полить оливковым маслом или майонезом, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10140,'Выложить на блюдо, посыпать измельченной зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Очистить авокадо, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Измельчить крабовые палочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Репчатый лук и стебель сельдерея нарезать кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Добавить сладкую кукурузу из банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Нашинковать кинзу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Порвать руками листья зеленого салата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10141,'Смесь овощей и морепродуктов заправить бальзамическим уксусом, оливковым маслом, соль и перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Нарезать свежий огурец, крабовые палочки и авокадо кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'Нарезать кубиками запеченную со специями буженину (можно использовать ветчину, копченую грудку или отварную говядину).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'Помидоры разрезать пополам, а затем поперек тонкими пластинками. Так же нарезать свежие огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'Открыть банку с кукурузой, слить жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'На большое блюдо по краю выложить вымытые листья зеленого салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'Затем огуречную нарезку – веером на четыре стороны тарелки, точно так же – помидоры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'В центр – буженину, в оставшиеся места насыпать кукурузу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10142,'Блюдо украсить нарезанными маслинами. Распределить капельки сметаны или майонеза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Нарезать репчатый лук и шампиньоны, обжарить продукты на растительном масле до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Филе судака нарезать крупными кубиками, также обжарить на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Очистить и нарезать авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Измельчить крабовые палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Все ингредиенты перемешать, добавить красную икру, сбрызнуть только что отжатым лимонным соком, поперчить и посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10143,'Украсить веточкой петрушки или кинзы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10144,'Отварить куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10144,'Авокадо и яблоко очистить и нарезать некрупной соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10144,'Покрошить кубиками крабовые палочки, репчатый лук, яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10144,'Перед перемешиванием лук можно обдать кипятком и через несколько минут отжать, эта несложная процедура удалит лишнюю горечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10144,'Продукты перемешать, поперчить, добавить соль и майонез по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10145,'Нарезать кольцами пекинскую капусту, свежий огурец – соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10145,'Плод авокадо очистить, вынуть косточку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10145,'Нарезать мякоть и крабовые палочки небольшими кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10145,'Все ингредиенты перемешать, добавить консервированную кукурузу, перец и соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10145,'Заправить салат майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Дрожжевое тесто приобрести в магазине или приготовить самостоятельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Если будете делать самостоятельно, то для опары понадобятся сухие дрожжи (можно использовать свежие – 30 г), немного муки и теплой воды, сахарный песок. Дать смести постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Яйца перемешать с солью и сахаром, влить опару, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Добавить подогретое молоко, растопленный маргарин или сливочное масло, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Всыпать муку небольшими порциями, просеивать через сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Тесто вымесить и накрыть полотенцем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Для приготовления начинки яблоки нужно очистить от кожуры и семенных камер, мякоть нарезать кусочками небольшого размера.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Прогреть сковороду со сливочным маслом. Обжарить яблоки, добавить молотую корицу и сахарный песок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Подошедшее тесто еще раз вымесить. Разделить на две неравные части, меньшая понадобится для украшения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Большую часть тонко раскатать, переложить в разъемную форму, смазанную сливочным маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Сформовать невысокие бортики. Выложить начинку, прикрыть ее краями.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Из оставшегося теста вырезать звездочки или другие декоративные элементы, разложить поверх начинки. Другой вариант – сеточка из «колбасок».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10146,'Яйцо перемешать с водой, смазать пирог. Изделие должно подняться в течение десяти минут. Время выпекания – от 30 до 35 минут, температура – 180 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Плод авокадо разрезать на две половинки, вынуть косточку, мякоть вынуть ложкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Размять в пюре, побрызгать лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Мелко нарезать крабовые палочки, перемешать с авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Свежий огурец почистить, натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Добавить к остальным ингредиентам вместе с творожным сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Порубить укроп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Все ингредиенты перемешать, посолить, поперчить, заправить майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10147,'Выложить массу в небольшие тарталетки или в половинки кожуры авокадо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Добавить консервированную кукурузу и креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10148,'Сливочное масло растопить, затем смешать его с сахарной пудрой и творогом. Желатин растворить в небольшом количестве горячей воды (хватит около 5-6 ст. л.). Добавить ванильный сахар, хорошенько взбить, вливая растворенный желатин тонкой струей. Получившуюся массу переложить в форму и убрать ее в холодильник на 2 часа',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10148,'Для коржа тщательно смешать мелко истолченное овсяное печенье с растопленным на водяной бане шоколадом (растопить нужно 200 г). Лист пекарской бумаги смазать маслом и выложить на него массу из печенья и шоколада, убрать корж в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10148,'Форму с творогом на несколько секунд опустить в горячую воду, после чего аккуратно выложить массу на застывший корж. Смазать творожный слой ягодным джемом, сверху распределить остывший растопленный шоколад (оставшиеся 100 г).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10148,'Убрать получившийся чизкейк с ягодным джемом (без выпекания) в холодильник на ночь, перед подачей нарезать его порционными кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Готовое дрожжевое тесто раскатать в пласт толщиной в полсантиметра на присыпанной мукой поверхности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Намазать лепешку мягким сливочным маслом. Посыпать сахарным песком и корицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Скатать рулет, защепить край. Нарезать изделие на одинаковые кусочки по четыре или пять сантиметров.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Противень застелить бумагой для выпекания, смазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Выложить слойки, верхние края немного разогнуть, чтобы получились розочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10149,'Посыпать еще одной порцией корицы и сахара, печь в течение 20 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10150,'Репчатый лук очистить и мелко нарезать, спассеровать на масле. Как только продукт станет прозрачным – добавить измельченные шампиньоны, жарить все вместе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10150,'Куриное филе нарезать небольшими кусочками. Освободить сковороду от обжарки, переложить на нее мясо, прогревать пять-семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10150,'Вернуть на сковороду лук с грибами, поперчить и посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10150,'Тесто раскатать, нарезать кружки, выложить начинку, защипать края.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10150,'Смешать сырой желток с водой, смазать изделия, поставить в духовой шкаф на 15 – 20 минут. Температура выпекания – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Тонко нарезать репчатый лук, обжарить на небольшом количестве масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Нарезать тонкой соломкой морковь, добавить в лук. Соль и специи – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Куриное филе нарезать небольшими кубиками, а затем порубить острым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Добавить измельченный чеснок, тертый сыр, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Ингредиенты перемешать, посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'Обжарку переложить в другую посуду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10151,'На освободившейся сковороде обжарить небольшие котлеты по четыре минуты с каждой стороны, затем добавить луковую обжарку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10152,'Включить  на разогрев духовку до 200 градусов, подготовить форму для запекания, переложить в нее кусочки рыбы, чтобы они покрыли дно полностью, посолить, поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10152,'Разложить вокруг филе цветную капусту, разобранную на соцветия и брокколи. Залить равномерно сливками, добавить зеленый горошек, убрать в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10152,'Рыба запеченная в сливках с брокколи, будет готова через полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10153,'В мисочку вбить яйца, всыпать сахарный песок, соль, влить немного растительного масла. Перемешать при помощи венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10153,'Влить теплое молоко и подогретую воду, перемешать. Всыпать муку порциями, перемешивать, разбивать комочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10153,'Жарить на небольшом количестве масла с двух сторон. Вторую сторону блина можно смазывать кусочком сливочного масла, а затем переворачивать и обжаривать с другой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Репчатый лук нарезать кубиками небольшого размера, жарить на масле до прозрачности в течение пяти или семи минут, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Нарезать шампиньоны небольшими кусочками, добавить к луку, жарить до корочки, переложить на отдельную тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Нарезать куриное филе небольшими кусочками, жарить на той же сковороде в течение десяти минут, посолить, добавить специи. Перемешать с луковой обжаркой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Влить сливки, потушит пять-семь минут под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10154,'Поставить жульен с курицей и грибами в духовку на 15 – 20 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10155,'Очистить плод авокадо от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10155,'Нарезать небольшими кубиками грушу, крабовые палочки, твердый сыр, авокадо, огурцы, сладкий болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10155,'Приготовить заправку из сока лимона, пропущенного через пресс чеснока, натурального жидкого мёда, оливкового масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10155,'Продукты хорошо перемешать, посолить и поперчить, полить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Вскипятить воду, выложить тушки кальмаров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Довести до кипения еще раз, варить в течение минуты, вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Очистить тушки от хребта и пленок, нарезать кольцами, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Отварить и натереть яйца, свежий огурец нарезать мелкими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Так же нарезать крабовые палочки, мякоть очищенного плода авокадо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Выложить продукты на тарелку слоями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Первый слой – кальмары, затем авокадо, яйца, майонез, крабовые палочки, огурцы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Сверху намазать салат майонезом и посыпать тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Отварить перепелиные яйца, очистить, разрезать пополам.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Вынуть желтки, вместо них положить красную икру.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10156,'Украсить блюдо получившимися лодочками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10157,'Очистить авокадо, вынуть косточку, мякоть нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10157,'Измельчить крабовые палочки, помидоры, копченый куриный окорок, свежий огурец, сладкий красный перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10157,'Ингредиенты побрызгать лимонным соком, соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10157,'Заправить блюдо майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10158,'Поставить клубнику размораживаться, перемолоть мелко стружку кокоса. Взбить белки до густой пены, всыпать постепенно сахар (оставить две ложки) и продолжать взбивать 6-8 минут. Смешать белки, муку и кокосовую стружку на малой скорости блендера. Противень выложить пергаментом, вылить кокосовую смесь, разровнять, поставить подсушиться в духовку на слабый огонь примерно на час, замочить желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10158,'Растереть клубнику в пюре, разделить на две части. Добавить к одной половине разбухший желатин и ванильный сахар, подогреть на слабом огне, когда желатин растворится, дать чуть остыть и убрать в холодильник. Сливки вылить в высокую посуду и поставить на водяную баню, взбивать около минуты. Сделать скорость выше и взбить до сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10158,'Достать чуть схватившееся желе  и смешать со сливками на малой скорости, переложить сливочное суфле на подсушенный корж. Если корж сильно пересушен, то корочку смазать водой и тогда его будет легко утром нарезать на отдельные пирожные из кокосовой стружки и клубники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10158,'Добавить две столовые ложки сахара ко второй половине пюре из клубники и уварить до состояния густого повидла, остудить, намазать на суфле. Оставить намазанный корж до утра и нарезать формочками на кусочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Плод авокадо разрезать пополам, мякоть вынуть ложкой, нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Некрупно нарезать крабовые палочки и зеленый салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Приготовить заправку из порошка «Васаби», кипяченой воды, майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Перемешать рубленый укроп с крабовыми палочками, авокадо, консервированной кукурузой, салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Посолить по вкусу, полить острым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10159,'Выложить в половинки кожуры авокадо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Нарезать брынзу крупными кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Плод авокадо почистить, мякоть нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Измельчить крабовые палочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Приготовить заправку из сока лимона, майонеза, соевого соуса, давленого чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Нарезать репчатый лук тонкими полукольцами, залить соусом на пять минут для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Заправить смесью салат, поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Выложить массу на блюдо горкой, посыпать тертым сыром/',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10160,'Eкрасить маслинами без косточек, веточками укропа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Воду подсолить, вскипятить, отварить креветки в течение одной или двух минут, снять панцири.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Очистить авокадо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Чеснок очистить, нарезать тонкими пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Полить соком лимона, посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10161,'Заправить салат оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Отварить до готовности говядину или телятину, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Другой вариант – разобрать филе на волокна руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Очистить яблоко, потереть на крупной терке, добавить к мясу. Этот ингредиент добавляется в блюдо по желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Нарезать тонкой соломкой дайкон или натереть на терке для приготовления моркови по-корейски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Репчатый лук нарезать полукольцами, жарить на заранее разогретом растительном масле в течение двух или трех минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Горячую обжарку добавить к основной массе, перемешать, чтобы масло впиталось в мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Посолить, поперчить салат по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Приготовить заправку, возможны четыре варианта: растительное масло с лимонным соком, сметана, майонез, смесь майонеза со сметаной в равных количествах.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Залить салат и перемешать еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Порубить зелень.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Отварить и разрезать пополам перепелиные яйца.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10162,'Готовый салат выложить на тарелку, посыпать зеленью, украсить половинками яиц.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Дайкон очистить от кожуры, натереть на терке для приготовления моркови по-корейски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Другой вариант – нарезать мякоть длинными полосками острым ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Морковь очистить и тоже натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Сладкий красный или оранжевый болгарский перец нарезать тонкими полосками, репчатый лук – тонкими полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Для приготовления заправки порубить очищенный чеснок, мелко нарезать красный острый перец чили, семена удалить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Продукты перемешать, заправить оливковым маслом холодного отжима и лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Залить полученным соусом основную массу, посолить по вкусу и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10163,'Салат оставить на несколько часов для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/82/c199f99e8a96282_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'В миске соединяем воду, мед, сахар, соль, растительное масло. Размешать.','https://vkuso.ru/data/cache/data/2b/ddfa096081a752b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'В муку высыпать соду. Просеять и перемешать.','https://vkuso.ru/data/cache/data/49/dcddcf1a70c2c49_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'В муку вылить медовую смесь. Замесить тесто. Тесто получается жидким. Можно добавить сухофрукты.','https://vkuso.ru/data/cache/data/a0/589b52192a57ca0_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'Заполняем формочки на 2/3 тестом. Выпекаем при 180 градусах 15-20 минут. Проверяем готовность шпажкой.','https://vkuso.ru/data/cache/data/8a/992b555ed15e28a_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'Когда остынут. Вынуть из формочек.','https://vkuso.ru/data/cache/data/25/3846ba1b9f8c825_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10164,'Пожеланию украшаем сахарной пудрой. Приятного чаепития.','https://vkuso.ru/data/cache/data/4f/0147f312af3514f_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10165,'Смешать размягченное масло с порошком какао, орехами и сахаром, всыпать измельченное печенье и перемешать. Переложить шоколадную массу на пергамент, разровнять в слой в пол сантиметра и охладить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10165,'Для получения массы из кокоса смешать масло, сахарную пудру, кокосовую стружку до однородности и равномерно смазать этой смесью шоколадную массу. Свернуть рулет, используя пергамент и отправить ночевать в холодильник. Перед подачей рулет шоколадный с кокосовой стружкой нарезать наискось на порции, разложить на блюде в виде ромашки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Приготовить тесто из муки, яиц, молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Испечь блины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Нарезать шампиньоны и спассеровать их на сковороде с маслом в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Добавить грибы, обжарить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Порубить зелень, соединить с остывшей обжаркой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Добавить куриный паштет, еще раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Выложить на блюдо первый блин, на него – начинку, снова блин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10166,'Слои повторить несколько раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10167,'Яйца взбить с солью, обжарить блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10167,'Сложить их друг на друга, скрутить рулетом и тонко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10167,'Свежие помидоры и копченую колбасу нарезать брусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10167,'Ингредиенты перемешать и заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10168,'Отварить картофель, яйца, морковь, затем нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10168,'Так же нарезать свежий огурец, нашинковать зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10168,'Овощи пересыпать в глубокую миску, добавить зеленый горошек, майонез и сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10168,'Продукты перемешать, выложить на тарелку, посыпать тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10168,'Из колбасы сделать ушки, хвост и пятачок, глаза – маслины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10169,'Соединяем в сотейнике мед, сахар, специи, ставим на огонь. Хорошо перемешиваем, варим до растворения сахара. Снимаем с огня, добавляем соду, хорошо перемешиваем, масса начинает пениться и увеличиваться в размере. В горячую смесь добавляем масло, хорошо перемешиваем. Остужаем и добавляем яйцо, перемешиваем.  По чуть-чуть добавляем муку, лучше вмешать меньше муки. Тесто получается мягким и не липнет к рукам. Отправляем в холодильник минимум на 1 час. Можно сделать тесто заранее и заморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10169,'Раскатываем тесто примерно толщиной миллиметра 3. Вырезаем домик. Там, где окна положили карамельки, они растают и превратиться в стекла. Выпекаем в разогретой духовке 7-10 минут. Даем остыть на противне и только потом снимаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10169,'Для глазури смешаем 2 белка и 150 грамм сахарной пудры. Поставим на водяную баню и при постоянном помешивании варим до загустения. Дальше собираем дом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10169,'Лучше сделать так: 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10170,'Нашинковать мелко лук, обжарить до прозрачного состояния, добавить нарезанные грибы, посолить. Жарить около10 минут, постоянно размешивая до готовности грибов (жидкость должна испариться).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10170,'Нарезать грудки на кусочки, измельчить блендером или мясорубкой, вбить в фарш  яйцо, посолить, поперчить, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10170,'Взбить второе яйцо, насыпать панировочные сухари в широкую плоскую емкость, фарш разделить на 6 частей. Сформовать из фарша шарик, сжать его в сантиметровую лепешку. Положить в центр грибную начинку, тщательно залепить края',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10170,'Сформовать зразу овальной формы, окунуть в яйцо, обвалять в панировочных сухарях, обжарить в масле. Переложить зразы из куриного филе с шампиньонами в форму, запечь около 20 минут при 180 градусах.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10171,'В два яйца добавить немного соли, взбить слегка венчиком и пожарить два блинчика. Дать блинам остыть и нарезать соломкой.','https://vkuso.ru/data/cache/data/5f/7d7de78f7f4155f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10171,'Лук нарезать тонкими полукольцами, залить 200 г воды, добавить уксус, сахар, соль и оставить мариноваться.','https://vkuso.ru/data/cache/data/ef/146ef47b2518def_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10171,'Колбасу, огурец и отварные яйца ( белок ) также нарезать соломкой. Все ингредиенты смешать, добавить майонез. Выложить горкой на блюдо и сверху посыпать тертым на мелкой терке желтком. Приятного аппетита!!!','https://vkuso.ru/data/cache/data/a4/51e37ce721f8fa4_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10172,'Отварить и покрошить куриные яйца, натереть сыр, нарезать мелкими кусочками помидоры и ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10172,'Все ингредиенты переложить на большое блюдо в виде свинки, вырезать из колбасы пятачок, ушки и хвост.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10173,'Нарезать зеленый лук, сладкий перец, свежие огурцы, ветчину, отваренные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10173,'Выложить в глубокую миску, добавить кукурузу из банки, майонез, соль, перец. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10173,'На большую плоскую тарелку выложить салатные листья, в середину – приготовленную массу, потереть желток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10173,'Блюдо украсить колечками из зеленых консервированных оливок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10173,'Нарезать колечки из сладкого перца, положить на них по отваренному яйцу, вырезать пятачки и ушки из ветчины, глаза можно сделать из перца или оливок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10174,'Смешать яйца с молоком и взбить, всыпать натертый сыр, приправить солью, мускатным орехом и перцем. Включить на разогрев духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10174,'Очищенный картофель нарезать тонкими дольками, поместить в форму для запекания и залить молочной смесью, поместить нежный картофель по-савойски в разогретую духовку на 30-35 минут',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10175,'Нарезать копченую свинину, консервированный ананас и мякоть авокадо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10175,'Отварить и измельчить куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10175,'Ингредиенты перемешать, посолить, поперчить, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10175,'Выложить на листья салата, охладить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10176,'Готовые блины нарезать тонкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10176,'Точно так же нарезать два вида огурцов: свежие и маринованные или малосольные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10176,'Отварить и порвать на волокна куриное филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10176,'Очистить и порубить грецкие орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10176,'Продукты перемешать и заправить по вкусу майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Испечь пресные блины, нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Копченую куриную грудку измельчить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Порубить зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Отварить и мелко порубить или натереть куриные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Ингредиенты перемешать и полить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10177,'Еще раз перемешать. Соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Приготовить тесто для блинов из яиц, муки, молока, растительного масла и мелко рубленного укропа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Обжарить, сложить стопочкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Нарезать кольцами помидоры, потереть сыр, порубить зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Пропустить через пресс чеснок, перемешать с сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Выложить в форму первый блин, на него – сыр, зелень, помидоры, второй блин, слои повторять, пока не закончатся продукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10178,'Поставить в духовой шкаф, время запекания – от пяти до десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10179,'Нарезать репчатый лук, спассеровать до золотистого цвета на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10179,'Взбить яйца с солью и обжарить блинчики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10179,'Нарезать полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10179,'Мелко порубить зелень, ветчину нарезать брусками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10179,'Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10180,'Включить для разогрева духовку (220 градусов). Нарезать тонко овощи, переложить в миску. Из тимьяна, горчицы, давленого чеснока и половины столовой ложки соли приготовить маринад, смазать вырезку и дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10180,'Влить к овощам оливковое масло и сливочное (растопленное), добавить соль и перец, перемешать. Переложить все в чугунную сковороду, тушить полчаса. Положить свинину сверху овощей, свиная вырезка, запеченная в сковороде с морковью и картофелем, будет готова через 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10180,'Мясо положить на разделочную доску, обернуть фольгой, дать постоять минут 5-7, нарезать на кусочки и подать с овощами, посыпанными измельченным укропом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Перемешать яйца с сахаром и солью, влить молоко, взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Всыпать муку, еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Приготовить обычные блины, жарить с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Нарезать брусками отваренную курицу, свежий огурец, чернослив.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Продукты перемешать, полить майонезом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10181,'Посыпать кунжутными семечками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Перемешать яйца с солью, хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Всыпать муку и еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Обжарить блины с двух сторон на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Отварить грудку, нарезать соломкой. Можно использовать копченую курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Грушу нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10182,'Все составляющие перемешать, заправить майонезом или натуральным йогуртом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10183,'Испечь постные блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10183,'Нарезать их соломкой вместе с репчатым луком, вареной колбасой, свежим огурцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10183,'Натереть отваренные куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10183,'Ингредиенты перемешать и заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10184,'Взбить сырые куриные яйца, всыпать крахмал, взбить, испечь блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10184,'Отварить куриное мясо, нарезать по волокнам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10184,'Порезать соломкой остывшие блины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10184,'Продукты смешать, приправить по вкусу давленым чесноком и майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10185,'Свежую белокочанную капусту нарезать тонкой соломкой, помять и дать полежать, чтобы продукт дал сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10185,'Натереть морковь и свеклу. Лучше использовать терку для корейских салатов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10185,'Листья зеленого салата порвать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10185,'Перемешать ингредиенты в глубокой миске, заправить оливковым маслом и водой, пропорции – два к одному.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10185,'Добавить соль и специи по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Овощи хорошо сочетаются с любыми добавками, салаты-щетки имеют большое количество интерпретаций.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Белокочанную капусту нарезать соломкой, помять, долить немного воды и дать постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Натереть морковь и свеклу на терке для корейских салатов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Корень сельдерея измельчить кубиками или соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Потереть сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10186,'Ингредиенты перемешать, дать постоять от пятнадцати минут до получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Помидоры нарезать кубиками, слить сок. Открыть банку с зеленым горошком, слит сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Отварить куриные яйца, нарезать кубиками, один желток оставить для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Ветчину нарезать небольшими кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Репчатый лук измельчить, залить кипящей водой, чтобы ушла горечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Компоненты перемешать. Заправить майонезом по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'На тарелку выложить хорошо промытые и обсушенные салатные листья. На них – салатную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Сформовать поросят из яиц, ветчины, бутонов гвоздики.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10187,'Горку из салата присыпать тертым сыром, тертым желтком и гранатовыми зернами. Украсить «поросятами», зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10188,'Отварить картошку и яйца, куриное филе. Продукты нарезать кубиками, добавить соленые огурцы, зеленый горошек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10188,'Ингредиенты заправить майонезом, посолить, перемешать, выложить на блюдо в виде свинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10188,'Крабовые палочки натереть, засыпать салат полностью, из колбасы вырезать хвост, нос, ушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10188,'Из маслин и капелек майонеза сделать глаза. Блюдо настоять и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Приготовить соус из равных частей майонеза и сметаны.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Отварить морковь и куриные яйца, очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Натереть плавленый сыр, чеснок, яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Приготовить смеси для прослойки коржей: мелко нарезанные маринованные огурцы с рыбными консервами в масле, плавленый сыр с яйцами и чесноком и тертая морковь с твердым сыром и майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Выложить салат слоями: корж, сметанный соус, огуречная смесь, второй корж, соус, чесночная масса, третий корж, соус, морковная прослойка. Сверху – корж, слои повторить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10189,'Готовый торт-салат смазать майонезом, посыпать тертым желтком середину, белком – края. Украсить блюдо ломтиками отваренной моркови, вместо глаз – маслины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10190,'Яйца отварить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10190,'«Докторскую» колбасу, огурцы, помидоры также измельчить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10190,'Продукты перемешать, приправить майонезом по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10190,'Выложить массу на тарелку, застеленную салатными листьями, смазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10190,'Выложить «хрюшку» из кусочков колбасы и маслин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'1-слой: Отварной картофель тертый на крупной терке',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'2-слой: Отварная куриная грудка нарезанная мелкими кубиками.','https://vkuso.ru/data/cache/data/f2/846bc85399cf0f2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'3-слой: Соленные огурцы тертые на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'4-слой: Маринованные грибы обжаренные слегка с луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'5-слой: Перед самой подачей на стол тертый на крупной терке сыр.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10191,'Между всеми ингредиентами наносим сеточку майонеза. Приятного аппетита и хорошего настроения!!!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Картофель, яйца, морковь отварить, охладить и очистить. Компоненты нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Так же нарезать готовую копченую курицу, кожицу лучше убрать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Нарезать свежие огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Продукты перемешать, добавить майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Выложить массу на блюдо в виде свинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Измельчить морковь и лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Натереть сыр «Пармезан» или «Российский», посыпать салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10192,'Украсить черным виноградом или маслинами, вырезать ушки, пятачок и хвостик из колбасы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Яйца и морковь отварить, натереть. Натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Грибы нарезать и обжарить до готовности на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Мякоть авокадо тонко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Репчатый лук нарезать кубиками, залить кипящей водой, оставить на 15 минут, влить уксус, всыпать сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Через 30 минут жидкость отцедить при помощи дуршлага.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Салат выложить слоями: тертая отваренная морковь, свежие огурцы, маринованный лук, грибная обжарка, авокадо, тертые яйца, сыр. Все слои, кроме последнего, промазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10193,'Украсить блюдо ветчиной, вырезав ушки, хвост, ножки, пятачок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10194,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/2f/bf3dd44e354972f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10194,'Сыр натрем на крупной терке. Лук порежем полукольцами. Орехи порубим ножом. Лук замаринуем.','https://vkuso.ru/data/cache/data/04/aa47a3cece94004_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10194,'Соединить все продукты, добавить сметану и перемешать.','https://vkuso.ru/data/cache/data/d6/a484dc5d31823d6_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10194,'Салат украсить. Приятного аппетита!','https://vkuso.ru/data/cache/data/e0/69ed663038da0e0_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10195,'Для пасты со сладким перцем смешать майонез, нарезанный мелко укроп, горчицу, посолить, поперчить. Для рыбной пасты смешать майонез, лимонный сок, сливочный сыр, порубленный укроп, тертую лимонную цедру, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10195,'Испечь в нагретой духовке желтые и зеленые перцы, разрезанные пополам, через 20 минут переложить их в миску, дать постоять 10 минут, очистить от кожицы, порезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10195,'Нарезать филе слабосоленой красной рыбы на тонкие пластинки, смазать лаваш пастой с сыром, уложить сверху рыбу. Другой лаваш смазать пастой с горчицей, а сверху уложить перец и ломтики ветчины. Свернуть из лавашей рулеты, порезать кусочками по 2,5-3 см, как на роллы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10195,'Если времени для готовки мало, то роллы из тонкого лаваша с рыбой и ветчиной можно приготовить со свежим перцем, нарезав его тоненькой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10196,'Яйца отварить и очистить, натереть отдельно желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10196,'Копченую свинину и консервированные ананасы нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10196,'Измельчить мякоть авокадо, сладкий болгарский перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10196,'Все ингредиенты перемешать, заправить майонезом, белки оставить для украшения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10196,'Уложить массу в виде овала, посыпать белком и украсить колбасой или ветчиной, маслинами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10197,'Отварить картофель в мундире, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10197,'То и другое нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10197,'Маринованные или соленые огурцы и вареные яйца, вареную колбасу покрошить точно так же.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10197,'Добавить зеленый горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10197,'Нарезку заправить майонезом, соль – по вкусу и по необходимости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10198,'Нарезать хорошую вареную колбасу, добавить кубики отваренного картофеля, яйца, маринованные огурцы, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10198,'Приготовить заправку из сметаны и майонеза, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10198,'Полить смесь, перемешать, соль можно не добавлять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10198,'Дать постоять в холодильнике два или три часа для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/b5/1d5d5321f5edfb5_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'Сыр, зелень, колбасу, перец - мелко нарезать. Яйца посолить, поперчить, добавить зелень, размешать венчиком.','https://vkuso.ru/data/cache/data/b8/ec11b259a536bb8_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'В формочки выложить продукты.','https://vkuso.ru/data/cache/data/de/0e56adc0f993fde_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'Залить яичной смесью.','https://vkuso.ru/data/cache/data/4d/03500abbf522a4d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'Выпекать в духовке 20 минут при 180 градусов.','https://vkuso.ru/data/cache/data/48/ca806a4be5e8c48_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10199,'Приятного аппетита.','https://vkuso.ru/data/cache/data/83/1fb767855604483_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10200,'Нарезать кубиками копченую колбасу или ветчину, обычную вареную колбасу, вареные морковь и яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10200,'Покрошить соленые огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10200,'Открыть банку с зеленым горошком, отцедить жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10200,'Ингредиенты перемешать, посолить, заправить майонезом «Провансаль».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10201,'Сдобрить мясо курицы солью и перцем, дать постоять полчаса, растопит половину сливочного масла, обжарить нарезанные яблоки. Включить для разогрева духовку (180 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10201,'Запанировать курицу в муке, обжарить на оставшемся масле (4-5 минут с каждой стороны) до желтоватой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10201,'Нашинковать тонкими полукольцами лук и высыпать к курице, жарить 6 минут, влить сидр и дать закипеть. Убрать в нагретую духовку на полчаса, добавить припущенные яблоки, курица тушеная в сидре с яблоками будет готова через 5-7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10202,'Свежие шампиньоны нашинковать, обжарить на растительном масле с добавлением чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10202,'Нарезать вареные яйца, картофель, маринованные огурцы и копченую колбасу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10202,'Добавить рубленый чеснок, зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10202,'Заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10203,'В чашу для блендера вбиваем яйцо, желток должен остаться целым, добавляем сахар, соль, горчицу, сок лимона или уксус, вливаем масло без запаха и накрываем желток блендером, взбиваем несколько секунд не поднимая блендер, затем постепенно отводим блендер в сторону, поднимаем и еще взбиваем несколько секунд до полного загустения майонеза.','https://vkuso.ru/data/cache/data/30/f8ee27f0395d930_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10203,'Домашний майонез хранится в холодильнике не более недели, использовать можно как обычный магазинный для салатов, закусок и т.д. Приятного аппетита!!!','https://vkuso.ru/data/cache/data/36/95258d4bc2ccb36_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10204,'Яйца, картофель, морковь, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10204,'Добавить горошек, вареную колбасу, сельдерей, маринованные шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10204,'Полить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10204,'Перемешать и подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10205,'Нарезать небольшими кубиками вареные яйца и картофель, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10205,'Репчатый лук залить разбавленным водой уксусом, через полчаса жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10205,'Покрошить вареную колбасу, маринованные огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10205,'Заправить жирным майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10206,'Нарезать кубиками отваренные яйца, морковь, картофель, копченую колбасу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10206,'Добавить зеленый горошек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10206,'Заправить майонезом по вкусу. Смесь можно не солить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10206,'Вложить в качестве начинки в вафельные рожки, купленные в магазине или приготовленные самостоятельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10207,'Для начала сухофрукты (у меня изюм), замочим в алкоголе (у меня ром), добавим цедру мандарина (можно лимона, апельсина). Оставим на 2 часа, периодически помешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10207,'В миску всыпаем просеянную муку, добавляем сахар, дрожжи, соль и специи. Перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10207,'Измельчим орехи. У меня грецкие (в классическом штоллене используют миндаль). Добавляем в тесто, туда же добавляем изюм, слив перед этим жидкость. Вымешиваем. Подсыпаем мукой, делим штоллен на части, я разделила на 3. Скалкой формируем овал толщиной 1 см. складываем пополам, как чебурек. А затем край верхней части еще пополам. Укладываем на противень, выстланный пергаментной бумагой. Оставляем на расстойку на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10207,'Выпекаем при 160 градусах, 40-50 минут. Достаем штоллен из духовки. Обильно смазываем сливочным маслом, обсыпаем сахарной пудрой. Остывший штоллен заворачиваю в пакет и убираю в холодильник. Перед подачей посыпаем сахарной пудрой.  Приятного аппетита! ','https://vkuso.ru/data/cache/data/25/3f6f75648c69925_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10208,'Измельчить печенье в крошку, смешать с маслом, переложить в формочки, слегка прижать ложкой ко дну, чтобы сформовать основу для чизкейка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10208,'Взбить блендером сметану и крем-сыр на малой скорости до однородности (буквально несколько секунд). Дольше не надо, т.к. образуется много воздушных пузырьков и в готовом чизкейке могут появиться трещины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10208,'Всыпать сахарную пудру, вбить яйцо, перемешать блендером до однородности, влить апельсиновый сок, осторожно перемешать, разлить по формочкам. Готовить в микроволновой печи около 2 минут при 700 Вт. Вынуть при появлении пузырьков в центре формы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10225,'Сверху порции посыпать рублеными яйцами, украсить майонезом, половинками яиц, листочками петрушки, красной икрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10208,'Дать остыть и отправить на пару часов в холодильник. После охлаждения серединка чизкейка должна застыть. Чизкейк с апельсиновым соком в микроволновке перед подачей украсить любыми ягодами или цветными цукатами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Приготовьте продукты. Свеклу, картофель, лук, филе сельди, укроп - мелко нарежьте.','https://vkuso.ru/data/cache/data/ec/19751495864b5ec_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Смешать картофель, селедку, яблоко и лук. Яблоко почистить и мелко нарезать, полить 1 ст.л. сока лимона. Все перемешать, посолить, поперчить.','https://vkuso.ru/data/cache/data/4c/f186f9f445d5c4c_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Свеклу полить соком лимона, добавить растительное масло, сахар, соль и перемешать.','https://vkuso.ru/data/cache/data/9c/0a027de82baa79c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Выкладываем на плоское блюдо и формируем салат.','https://vkuso.ru/data/cache/data/9a/566450b5122279a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Ножом делаем бороздки, а ложкой углубляем их.','https://vkuso.ru/data/cache/data/7c/757613b3c2b347c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'В бороздки выкладываем свеклу.','https://vkuso.ru/data/cache/data/9d/e378c9d4e54959d_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10209,'Между свеклой выкладываем зелень и подаем к столу. Приятного аппетита!','https://vkuso.ru/data/cache/data/24/7e19f1dd732c824_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'Свиное филе отварить в подсоленной воде, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'Покрошить маринованные огурцы, отваренные яйца, добавить рубленые грецкие орехи, измельченный чеснок, перец, майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'Посолить по вкусу и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'Выложить на тарелку в форме свиной тушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'В густую сметану добавить сок сырой свеклы и обмазать свинку розовым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10210,'Из половинок маслин сделать глазки, из колбасы – ушки, хвост, пятачок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10211,'Отварить морковь, яйца, картофель. Продукты нарезать, выложить в глубокую тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10211,'Нарезать свежие огурцы, копченую курицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10211,'Массу заправить майонезом, посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10211,'Выложить на плоскую тарелку, сделать фигурку свиньи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10211,'Ушки и другие детали вырезать из колбасы, глаза сделать из маслин или горошин перца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10212,'Порезать маринованные огурцы, отваренный картофель, морковь, яйца, вареную колбасу и курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10212,'Нашинковать репчатый лук, укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10212,'Открыть банку с горошком, слить жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10212,'Порезать зеленые яблоки сорта «Антоновка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10212,'Все продукты перемешать и заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Свежий зеленый горох бланшировать в течение нескольких минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Нарезать вареные яйца, покрошить вареную колбасу, свежие огурцы, молодой отваренный картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Измельчить зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Салат посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10213,'Дать постоять в холодильнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Отварить куриные яйца, очистить, измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Нарезать помидоры, огурцы соленые, вареную колбасу, зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Добавить зеленый горошек из банки, посолить и поперчить, заправить смесью майонеза и сметаны в равных пропорциях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Выложить массу на тарелку, обсыпать нарезанной соломкой колбасой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Вырезать детали: ушки, пятачок, хвостик колечком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10214,'Глаза сделать из маслин или из горошин перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10215,'Отварить картофель, морковь, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10215,'Добавить маринованные огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10215,'Покрошить яйца, «Докторскую» колбасу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10215,'Заправить смесью майонеза и сметаны в соотношении «один к одному».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10215,'Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10216,'Сварить заранее в мундире все овощи, ночевать оставить в холодильнике. Разделать на филе сельдь, нарезать мелко на кубики, нарезать также лук, смешать. Почистить вареные овощи и натереть вместе с яйцами на терке с мелкими отверстиями в разные емкости. Свеклу отжать и выложить на пленку, присолить, накрыть сверху пленкой и слегка уплотнить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/c8/151dec044b951c8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Балык мелко настругать. Зелень - мелко порезать. Яйца разделить на белок и желток - натрем на мелкой терке. Смешать сыр, сметану, зелень и чеснок. Все перемешать.','https://vkuso.ru/data/cache/data/38/642a4e47a754238_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10216,'Вторым слоем уложить морковь, слой должен быть чуть уже чем первый, чуть посолить, прикрыть пакетом и уплотнить, смазать майонезом. Третьим слоем будет картофель, выложить надо уже предыдущего слоя, посолить, уплотнить, смазать майонезом.   Выложить следующий слой – яичный (по ширине меньше картофельного), посолить, уплотнить, смазать майонезом. Поместить по центру слоя горкой селедочную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10216,'Завернуть все в рулет, обжать края, убрать в холодильник минимум на 3 часа (идеально на ночь). Утром переложить рулет из филе сельди с овощами  на блюдо, снять пленку, украсить листиками петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10217,'Свеклу нарежем на кусочки поменьше. В чаше блендера соединяем свеклу, сахар, соль, водку. В оригинальной рецепте добавляли еще и свежий хрен, но к сожалению его я не нашла. Перемалываем в мелкую крошку. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10217,'Фольгу накрываем пищевой пленкой, сверху укладываем филе рыбы, затем маринад. Распределяем маринад по всей рыбе. Хорошо заворачиваю. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10217,'Кладем в контейнер, потому что маринад может протечь. Оставляем в холодильнике на 36 часов. Рыбу достаём убираем маринад. Ее уже можно есть, она очень вкусная. ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10217,'Укроп нарезаем мелко. Посыпаем им рыбу. Сверху натираем цедру мандарина и поливаем соком. Оставляем еще на 8 часов в холодильнике. ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10217,'Подавать будем на оладьях. Смажем их сметаной. Сверху листок салата (у меня пекинская капуста), затем кружок огурца и завершаем вкуснейшей рыбой. Такую закуску можно подать и на хлебе, но на оладьях вкуснее. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10218,'Нарезать отварную курятину, яйцо,  свежий огурец, потереть сыр, яблоко, редис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10218,'Продукты перемешать, заправить майонезом, выложить на  блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10218,'Украсить яйцами, ветчиной, горошинами перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10219,'Нарезать капусту на квадратики по 1-1.5 см, залить крутым кипятком, дать постоять минут 5, слить воду, отжать капусту, накрошить мелко лук. Смешать вареный рис, лук, фарш, капусту, поперчить, посолить. Сформовать котлетки, обвалять в измельченных сухарях, обжарить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10219,'Добавить к сметане томатную пасту и хорошо перемешать. Переложить голубцы в форму, вылить соус, убрать в духовку. Запекать классические ленивые голубцы в томатном соусе около 45 минут, подавать к столу со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Отварить морковь, свеклу, картофель, натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Селедку разобрать, удалить кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Отварить яйца, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Нашинковать репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Салат выложить слоями: картофель, сельдь, лук, морковь, яйца, свекла. Каждый слой солить и перчить, промазывать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10220,'Верх салата смазать майонезом, украсить бутонами гвоздики и ломтиками свеклы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10221,'Отварить картофель и яйца, очистить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10221,'Добавить горошек, маринованные огурцы, вареную колбасу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10221,'Заправить смесью сметаны и майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10221,'Соль и молотый перец – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Нарезать вареную колбасу, картофель, морковь, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Нашинковать зеленое яблоко, маринованные огурцы, репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Открыть зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Продукты смешать, посыпать рубленым укропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Заправить небольшим количеством майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10222,'Салат можно украсить полосками красного сладкого перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10223,'Отварить и нарезать морковь, картофель, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10223,'Покрошить свежие и соленые огурцы, вареную колбасу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10223,'Заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10224,'Перемолоть куриное филе с чесноком в фарш, вбить яйцо, сдобрить перцем, солью, натереть сыр, смешать с фаршем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10224,'Смазать маслом руки, скатать из мяса шарики размером с грецкий орех, можно чуть крупнее. Запекать куриные шарики с сыром в духовке 10 минут, потом перевернуть и еще 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10225,'В прозрачные широкие стаканы выложить слоями отваренный и нарезанный картофель, свежие и соленые огурцы, яйца, горошек, ветчинную колбасу, креветки, горошек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10225,'Слои заправлять майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Покрошить репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Натереть сыр на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'На лаваш тонким слоем на нести намазку из сыра. А сверху выложить балык.','https://vkuso.ru/data/cache/data/3c/f895739d447103c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Свернуть лаваш рулетом.','https://vkuso.ru/data/cache/data/6a/1064224203fc96a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Разрезать на порционные кусочки.','https://vkuso.ru/data/cache/data/ed/8ad88ab2ed4b5ed_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Обмакнуть рулетик в намазку, а затем в белок. Другой рулетик в белок.','https://vkuso.ru/data/cache/data/d1/893e1701fc485d1_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10226,'Украсить. Приятного аппетита.','https://vkuso.ru/data/cache/data/13/5a5ddac04cb3a13_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10227,'Нарезать кубиками сыр, колбасу, свежие помидоры, сладкий болгарский перец, яйца, свежий огурец, колбасу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10227,'Перемешать, заправить майонезом по вкусу, переложить на тарелку в виде свинки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10227,'Для украшения использовать маслины и колбасу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10228,'Копченую рыбу очистить и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10228,'Так же поступить с отварным картофелем, яйцами, морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10228,'Очистить и нарезать репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10228,'Отцедить от жидкости зеленый горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10228,'Все ингредиенты перемешать, заправить по вкусу майонезом, посолить и поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10229,'Кальмары отварить, нарезать небольшими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10229,'Отцедить горошек, нарезать кубиками отваренную морковь, картофель, свежий и маринованный огурец, нашинковать зеленый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10229,'Все ингредиенты перемешать, добавить нежирный майонез, еще раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'Отварить говядину, морковь, картофель в «мундире», куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'Все продукты остудить, очистить, нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'Зеленые спелые яблоки очистить от сердцевины и кожуры, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'Так же поступить со свежими или солеными огурцами, репчатым луком, покрошить петрушку, базилик и укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'Заправить смесь кефиром, «Нежной» горчицей, полить лимонным соком, поперчить, посолить, добавить молотую паприку. Ингредиенты хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10230,'На большое блюдо выложить хорошо вымытые и обсушенные листья зеленого салата, на них – сам салат, полить майонезом «Деликатесным». Порубить зелень, посыпать сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10231,'Включить на разогрев духовку (200 градусов), нашинковать лук, спассеровать, добавить вино и измельченный помидоры в собственном соку, потушить 6-7 минут на слабом огне, перемешать с очищенными креветками, сыром фета и пряностями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10231,'Разложить массу по формам, присыпать измельченным сыром, отправить в нагретую духовку. Креветки с сыром фета в белом вине будут готовы через 15 минут, подавать со свежим хлебом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10232,'Филе курицы отварить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10232,'Отварить картофель, яйца, морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10232,'Нарезать все перечисленные ингредиенты, добавить свежий и маринованный огурец, зеленое яблоко, зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10232,'Заправить салат майонезом, перемешать. Посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Отварить стручковую фасоль, быстро охладить и нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Натереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Смесь посолить и поперчить по вкусу, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Сухарики можно приготовить самостоятельно, подсушив на сковороде или в духовке, или купить в магазине.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10233,'Добавить в салат перед подачей, чтобы не успели размокнуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Отварить картофель, в конце варки в кастрюлю положить фасоль, разрезанную на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Клубни вынуть, нарезать, переложить в салатницу вместе с фасолью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Очистить и нарезать красный лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Приготовить заправку из оливкового масла, винного уксуса, каперсов и дижонской горчицы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Половину смеси добавить в салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Красную рыбу очистить, отделить кости, филе нарезать кусочками и добавить в общую массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10234,'Полить остатками соуса и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Отварить основной ингредиент в кипящей воде в течение трех-пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Быстро охладить, выложить  в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10235,'Нарезать кубиками свежие помидоры, соломкой – ветчину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Фундук подсушить в духовом шкафу на противне. Время – 20 минут, температура – 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Нарезать кусочками стручковую фасоль, отварить ее в подсоленном кипятке в течение пяти минут после начала закипания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Приготовить однородный соус из зернистой горчицы, оливкового масла, бальзамического уксуса, льняного масла холодного отжима, масла из фундука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Ингредиенты можно перемешать при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Красный лук мелко порезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10236,'Орехи, фасоль и лук перемешать, полить соусом и при необходимости посолить, поперчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10237,'Залить на ночь фасоль холодной водой, отцедить воду через дуршлаг, залить свежей водой, поставить варить на среднем огне, после закипания варить 2 часа. Слить отвар, оставить полстакана для пюре. Приготовить из фасоли однородное пюре, добавить масло, перец, соль, перемешать, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10237,'Разделить готовое тесто на порции, раскатать в лепешки, положить в середину начинку из фасоли, защипать. Перевернуть лепешку швом вниз, раскатать толщиной в 1 см, запечь полчаса при 180 градусах. Можно запекать и под крышкой на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10237,'Лобиани из дрожжевого теста смазать салом или маслом, сложить в стопку, нарезать на треугольные порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10237,'Удобнее сделать эти лепешки небольшими, тогда есть удобно. Вкуснее блюдо есть с копченым окороком, а запивать красным сухим вином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Отварить фасоль в течение нескольких минут, быстро охладить в холодной воде, отцедить жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Натереть или нарезать заранее отваренную свеклу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Порубить укроп и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Приготовить заправку из соевого соуса, яблочного уксуса, растительного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Черный и острый молотый красный перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10238,'Заправить блюдо, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Кусочки бекона обжарить на гриле, затем охладить и порезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Зеленую фасоль в стручках отварить в кипятке, время – от трех до пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Быстро охладить в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Переложить в салатницу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Добавить шпинат, нарезанный лук-шалот, кубики мякоти авокадо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Приготовить заправку из толченого с сахаром чеснока, бальзамического уксуса, кунжутного и оливкового масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Перемешать до однородности и заправить основную массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10239,'Соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Отварить говяжий язык, нарезать кубиками или кусочками произвольной формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Также отварить свежую или замороженную стручковую фасоль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Нарезать красный лук, порубить кинзу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Приготовить заправку из соевого соуса, бальзамического или рисового уксуса, кунжутного масла, натурального жидкого меда.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Добавить специи: паприку, перец чили, сушеный розмарин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10240,'Перемешать и полить соусом основную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Зеленую стручковую фасоль отварить: после второго закипания подержать в воде в течение нескольких минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Охладить сразу, откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Консервированного тунца размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Нарезать помидоры черри половинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Перемешать, добавить оливки без косточек, «Моцареллу» в шариках, листья любого салата и маслины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Приготовить заправку из оливкового масла, лимонного сока, молотого перца чили, рубленой петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10241,'Салат заправить, перемешать, подать на стол на красивом блюде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10242,'Грудку залить молоком на один час. Затем натереть солью, перцем, приправой. В середину выложить дольки мандарин, которые предварительно полностью очистили от всех пленок.','https://vkuso.ru/data/cache/data/4b/dbdadd375dc6a4b_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10242,'Заворачиваем и перевязываем кулинарной нитью, затем хорошо и плотно оборачиваем фольгой и отправляем в разогретую духовку на 30 мин, затем фольгу сверху раскрываем и еще готовим 10 мин до золотистой корочки грудки. Приятного аппетита!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10243,'Картофель, яйца и морковь отварить, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10243,'Покрошить свежий и маринованный огурец, репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10243,'Выложить продукты в формовочное кольцо, каждый слой промазать майонезом. Порядок слоев: язык, огурцы, картофель,  лук, горошек, морковь, сверху – яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10244,'Сварить картофель, спассеровать лук-порей в смеси подсолнечного  и сливочного масла, приготовить пюре и смешать с луком. Положить стейки рыбы в кастрюлю, залить молоком, дать закипеть, прикрутить газ, положит креветки, варить около 5 минут, остудить. Достать рыбу и креветки, молоко не выливать, снять со стейков кожу, разделить на куски, удалить кости. Включить на разогрев до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10244,'Поджарить на сливочном масле муку, влить молоко, в котором варилась рыба, дать закипеть, помешивать пока жидкость в сковороде не загустеет. Всыпать измельченную петрушку, цедру лимона, приправить перцем и солью, добавить рыбу и креветки, перемешать очень аккуратно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10244,'Переложить все в форму, сверху выложить пюре, разровнять, полить растопленным маслом, поставить в нагретую духовку. Рыбная запеканка сливочная будет готова через полчаса, когда появится золотистая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10245,'Семгу нарезать полосками небольшого размера, креветки отварить, разрезать на три или четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10245,'Зеленый горошек отцедить, репчатый лук мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10245,'Нарезать кубиками маринованные огурцы, консервированный ананас, отваренную морковь и картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10245,'Ингредиенты перемешать с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10246,'Отцедить зеленый горошек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10246,'Измельчить соевую колбасу, тофу, морковь, маринованные огурцы, картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10246,'Заправить смесь майонезом, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10247,'Нарезать ломтиками филе жареного рябчика, отваренный картофель, свежие огурцы, добавить оливки, каперсы, залить майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10247,'Салат переложить в хрустальную посуду, украсить листьями зеленого салата, кубиками прозрачного холодца, раковыми шейками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10248,'Репчатый лук нашинковать, полить яблочным уксусом, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10248,'Отварить неочищенный картофель, снять кожуру, нарезать мякоть кубиками большого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10248,'Нарезать мелкими кубиками отваренные яйца, маринованные огурцы, стебли сельдерея, сладкий болгарский перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10248,'Посолить и поперчить, добавить лук вместе с уксусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10248,'Охлажденный майонез перемешать с зернами горчицы, заправить смесью салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10249,'Мелкий картофель отварить, положить в салатницу целыми или разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10249,'Для заправки перемешать винный уксус с солью, оливковым маслом, зирой, красным молотым перцем, паприкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10249,'Заправить картофель, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10249,'Красный лук очистить и нарезать кольцами, вынуть из маслин косточки, порубить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10249,'Все продукты хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10250,'Нарезать мелкими пластинками репчатый лук и маринованные огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10250,'Для заправки перемешать фруктовый уксус с оливковым маслом и горчицей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10250,'Отварить картофель, выложить сверху лук и огурцы, полить заправкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10251,'Смешать желтки яиц, манку, сахар, эссенцию и разрыхлитель. Взбить отдельно холодные белки в устойчивую, крепкую пену. Включить на разогрев до 180 духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10251,'Аккуратно все соединить с творогом, подготовить форму, вылить массу, поставить выпекаться. Торт-суфле с творогом и фруктами будет готов минут через 45. Дать торту остыть, украсить фруктами, можно залить желе. Отправить для застывания в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Отварить неочищенный картофель, крупно порезать.  Полить рассолом, слитым из-под оливок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Перемешать, остудить, оставить в тепле на десять минут для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Красный лук нарезать кольцами, полукопченую колбасу, сосиски, оливки – кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Полоски бекона обжарить на сковороде, вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'В этой же сковороде быстро обжарить лук с сосисками и колбасой, время приготовления – две минуты, огонь – сильный.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10252,'Все продукты переложить в салатницу, посолить по вкусу, сверху – оливки, бекон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10253,'Картофель отварить, очистить кожуру, мякоть нарезать крупными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10253,'Посыпать продукт измельченным зеленым луком, чесноком, укропом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10253,'Следующий слой – маслины. Посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10253,'Нарезать кубиками сыр «Фета», переложить на слой маслин, сверху – зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10253,'Заправить блюдо оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10254,'Молодой картофель отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10254,'Мелко порубить укроп, разрезать на кусочки стручковый зеленый горох, помидоры черри – половинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10254,'Для приготовления соуса натереть корень свежего хрена, перемешать с уксусом, солью, оливковым маслом, молотым перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10254,'Ингредиенты перемешать, заправить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Молоко поперчить, посолить, перемешать с оливковым маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Смесь взбить при помощи блендера до густоты. Половину массы перелить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Нарезать небольшими кусочками ветчину, огурцы – кольцами, переложить продукты в заправку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Нашинковать репчатый лук, зелень, посыпать салат сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Натереть отваренное яйцо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Отварить и нарезать картофель, посолить, переложить в салат, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Можно добавить еще немного заправки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10255,'Готовый салат украсить тертым яйцом и зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10256,'Свежую капусту нарезать соломкой, добавить воду и дать полежать, чтобы овощ дал сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10256,'Свеклу натереть на терке для салатов по-корейски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10256,'Корейскую морковь можно приобрести в магазине или приготовить самостоятельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10256,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10256,'Заправить оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10257,'Измельчить на мелкой терке сыр, добавить пропущенный через пресс чеснок, всыпать паприку, посолить, заправить майонезом, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10257,'Скатать из смеси небольшие шарики, обвалять в стружке кокоса. Перед подачей шарики сырные в кокосовой стружке охладить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10258,'Нарезать белокочанную капусту мелкой соломкой, помять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10258,'Если продукт суховатый, можно добавить немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10258,'Натереть свежую морковь и свеклу, добавить листья зеленого салата и кинзу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10258,'Продукты перемешать в глубокой емкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10258,'Заправить оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10259,'Отварить филе, нарезать мелкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10259,'Белокочанную капусту также нарезать соломкой, долить воду, дать полежать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10259,'Натереть свежую свеклу и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10259,'Ингредиенты перемешать',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10259,'Полить оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Яблоко очистить от семян, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Морковь и свеклу натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Капусту белокочанную нашинковать соломкой, долить воду, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Продукты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Оливковое масло перемешать с водой в пропорции три к двум.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10260,'Заправить салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10261,'Листья зеленого салата вымыть, обсушить, порвать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10261,'Натереть морковь и свеклу на терке для салатов по-корейски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10261,'Капусту нашинковать, помять и дать полежать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10261,'Все ингредиенты перемешать и заправить ореховой заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10262,'Приготовить начинку: обжарить в нагретом масле чеснок, добавить фарш, обжарить 5 минут, приправить смесью перцев (мельничка), мускатным орехом и солью. Снять с плиты, всыпать измельченную зелень и сыр, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10262,'Замесить из творога, муки, яиц, сахара, соды и соли мягкое тесто. Присыпать стол мукой, раскатать из теста небольшие сочни, положить на середину начинку, защипать, обжарить в масле. Пирожки с куриным фаршем из творожного теста начинать обжаривать со стороны с защипом. Переложить готовые пирожки на полотенца из бумаги, когда жир впитается можно подавать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Белокочанную капусту порубить, помять, дать полежать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Морковь и свеклу натереть длинной соломкой на терке для корейских салатов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Маринованные шампиньоны нарезать мелкими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'В качестве заправки использовать оливковое масло с водой в соотношении два к одному.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10263,'Специи, соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10264,'Красную капусту нашинковать, помыть и подождать, пока она даст сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10264,'Натереть морковь и свеклу длинной соломкой, перемешать с капустой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10264,'Соль и специи добавить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10264,'Заправить оливковым маслом с водой, соотношение – один к двум.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10264,'Готовый салат посыпать белыми кунжутными семечками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10265,'Порвать листья зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10265,'Добавить тертую морковь, свеклу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10265,'Белокочанную капусту нашинковать и потереть, добавить в основную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10265,'Заправить салат оливковым маслом, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10265,'Посыпать очищенными кедровыми орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10266,'Натереть на терке для корейских салатов редис, морковь и свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10266,'Порвать руками любой зеленый салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10266,'Белокочанную капусту нарезать, потереть руками, когда даст сок – переложить в салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10266,'Ингредиенты перемешать, заправить оливковым маслом холодного отжима.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Капусту нарезать, помять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Порвать хорошо вымытый салат руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Морковь и свеклу потереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Продукты смешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Полить оливковым маслом, лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10267,'Дать постоять для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10268,'Дать закипеть молоку с солью, всыпать постепенно помешивая кукурузную крупу. Сделать минимальный нагрев, закрыть крышкой, варить порядка 45 минут периодически помешивая. Добавить перед окончанием масло, половину измельченного сыра, яичные желтки, приправить солью и перцем, перемешать, снять с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10268,'Переложит кашу слоем 2,5 см на противень и быстро остудить. Обжарить в оливковом масле чеснок, вынуть его, добавить грибы, посолить, поперчить, жарить 15 минут, всыпать в конце измельченную петрушку. Включить на разогрев духовку (200 градусов).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10268,'Выдавить из остывшей поленты чашкой 8 кружков. Уложить в 4 порционные формочки слои в следующем порядке: полента, бешамель, грибы, сыр, повторить слои. Запечь поленту с грибами и сыром до золотистого цвета сыра, подавать к столу горячей в формочках.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Филе любой рыбы нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Крупно нашинковать репчатый лук, перемешать с рыбой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Столовый девятипроцентный уксус разбавить водой, перелить в посуду с рыбой, массу уплотнить, накрыть крышкой, оставить для пропитывания на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Затем лишнюю жидкость слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Салат поперчить и посолить по вкусу, приправить рубленым чесноком, посыпать красным и черным молотым перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10269,'Залить кипящим растительным маслом и оставить мариноваться еще на два часа или на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Свежую рыбу нарезать соломкой, сложить в посуду, посолить, полить уксусом и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Оставить для пропитывания на два часа или больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Отдельно нарезать чеснок и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Свежие огурцы – тонкими полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Жидкость отжать, огурцы переложить к луку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Нашинковать кинзу, добавить в основную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Готовую рыбу переложить в кастрюлю, посыпать черным и красным молотым перцем, полить кипящим растительным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Влить соевый соус, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10270,'Оставить для пропитывания полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Говядину нарезать тонкой соломкой, посолить по вкусу и обжарить на сковороде на растительном масле, помешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Нашинковать репчатый лук и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Крупно натереть морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Все перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Посолить, поперчить, полить уксусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Раскалить на сковороде масло до появления дымка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Перелить в салат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10271,'Перемешать, дать настояться и подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Для приготовления заправки раздавить очищенный чеснок, добавить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Выжать сок лайма, перемешать его с солью и сахаром, чесночным маслом. Соль и молотый перец – по вкусу. Смесь оставить для настаивания на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Отварить картофель, нарезать мякоть большими кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Маринованные грибы из банки отцедить, обсушить, добавить в картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Свежие огурцы нарезать брусочками, добавить в салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Белую часть зеленого лука нашинковать, всыпать в блюдо, полить заправкой, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10272,'Украсить нашинкованным зеленым луком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Репчатый лук и морковь мелко нарезать и спассеровать на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Отварить куриное филе, нарезать кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Свежий огурец нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Отварить и натереть яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Консервированные маслины разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Выложить продукты слоями на тарелку: куриное филе, обжарка, огурцы, яйца, консервированная кукуруза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Каждый ингредиент промазать майонезом, соль – по желанию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10273,'Украсить блюдо маслинами вместо зерен, чипсы выложить в качестве лепестков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10274,'Сахар и соевый соус соединяем в миске, перемешиваем. Заливаем стейки соусом и оставляем на 10-15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10274,'Тем временем разогреваем духовку до 200 градусов и отправляем стейки на 10-15 минут. Если есть режим гриль включаем его. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Майонез перемешать со сметаной, соль – по вкусу и желанию.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Клубни картофеля отварить, натереть, выложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Мелко нарезать маринованные огурцы, выложить на картошку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Далее – сметанно-майонезный соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Отварной говяжий язык нарезать соломкой, выложить третьим слоем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Далее – крупно натертое яйцо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10275,'Салат украсить половинками маслин, картофельными чипсами, мелко нарезанной зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Семечки подсолнуха обжарить на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Яйца отварить, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Зеленый лук порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Куриное филе отварить в подсоленной воде, измельчить как угодно, соломкой или кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Твердый сыр натереть на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Пропустить через пресс чеснок, перемешать с майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Слои выложить в следующей последовательности: куриное мясо, нашинкованный зеленый лук, нарезанные яйца, тертый сыр, семечки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Все слои промазать чесночным соусом, посолить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10276,'Украсить блюдо чипсами и маслинами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Отварить картофель, яйца, морковь до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Мелко порубить зеленый лук и перемешать с солью и майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Первым слоем выложить тертый картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Вторым – отваренные и очищенные креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Несколько штук оставить целиком, для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Далее – тертая морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Следующий слой – отваренные тертые яйца, майонез без зеленого лука.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Сверху – икра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Блюдо украсить маслинами и чипсами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10277,'Салат накрыть пищевой пленкой, оставить для пропитывания на несколько часов в холодном месте.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Репчатый лук обжарить на масле до прозрачного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Картофель отварить, нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Открыть банку с печенью трески, слить масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Филе размять при помощи вилки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Яйца отварить, разделить на желтки и белки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Натереть на терке: белки – на крупной, желтки – на мелкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Маслины разрезать пополам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Первый слой – картофельный, второй – луковая обжарка, сеточка из майонеза, соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Далее – печень и белки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Слой посолить и намазать майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10278,'Сверху – желтки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Далее – измельченные шампиньоны, прожаренные с луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Третий слой – консервированные ананасы, жидкость отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Четвертый – натертые белки вареных яиц.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Пятый – тертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Шестой – желтки, натертые на мелкой терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Каждый слой промазывать майонезом, соль – по желанию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Сверху сделать майонезную сетку, в ячейки выложить маслины.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10279,'Украсить чипсами.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Репчатый лук нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Морковь потереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Овощи поместить в чашу мультиварки, залить водой и поставить режим «Тушение» на пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Картофель нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Чечевицу промыть, пересыпать в чашу вместе с картофелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Влить оставшуюся воду, положить лавровый лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'Выставить режим «Суп» на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10280,'После сигнала крышку не открывать, оставить блюдо для настаивания на четверть часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Репчатый лук нашинковать, обжарить до готовности в масле на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Отварить рис. Если в него добавить немного свекольного сока, то продукт станет приятного розового цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Нарезать отваренные яйца, соленые огурцы, крабовые палочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Открыть банку с консервами, жидкость слить, рыбу размять вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Все продукты перемешать, заправить майонезом, выложить на блюдо, сверху – розовый рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10281,'Глаза сделать из яйца и маслин, пятачок и ушки – из колбасы или ветчины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10282,'Куриную грудку отварить, нарезать, выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10282,'Отварить яйца, натереть, высыпать на мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10282,'Натереть яблоко, сыр и свежий огурец, продукты добавить в общую массу, заправить сметаной или майонезом, перемешать, разровнять, сделать «полянку».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10282,'Насыпать рубленый укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10282,'Из трех отваренных яиц сформовать свинок, ушки и пятачок сделать из редиски, глаза – из гвоздики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Салат укладываем слоями. Первый стой это отварная картошечка. Этот слой обязательно нужно посолить и немного смазать майонезом.','https://vkuso.ru/data/cache/data/ed/25318fd0d8d5fed_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Далее идет слой печени трески. Печень трески сама по себе очень жирная, поэтому смазывать майонезом ее не стоит.','https://vkuso.ru/data/cache/data/5b/8ab9f94a4f2b25b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Далее идет слой тертых яиц на который мы выкладываем мелко нашинкованные соленые или маринованные огурчики. Этот слой немного присыпаем тертым сыром и смазываем майонезом.','https://vkuso.ru/data/cache/data/01/d90f5f9471ac401_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Далее, снимаем кожуру у яблока и натираем его на крупной терке, добавляем в салат предпоследним слоем. Скрепляем все майонезом.','https://vkuso.ru/data/cache/data/d1/b63219a92c319d1_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Последний слой - это тертый на мелкой терке сыр. Повторюсь, печень трески очень жирная поэтому майонез в этом салате я использую по минимуму, чтобы просто скрепить ингредиенты между собой.','https://vkuso.ru/data/cache/data/7a/8582df1102ea57a_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Перед подачей его, конечно же, украшаем по своему вкусу, я сделала майонезную сеточку и украсила икоркой. Простенько и со вкусом)','https://vkuso.ru/data/cache/data/ec/083eea81d69c0ec_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10283,'Салат получается очень нежным и вкусным , когда постоит ночь в холодильнике и как следует пропитается.','https://vkuso.ru/data/cache/data/b4/48d1937651111b4_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Отварить куриное филе, нарезать соломкой или кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Промыть холодной водой чернослив, облить кипятком, залить подогретой водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Через десять минут воду слить, продукт порезать небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Отварить яйца вкрутую, нашинковать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Натереть твердый сыр, «Российский» или «Пармезан». Другой вариант: порезать острым ножом тонкой соломкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Открыть банку с ананасом, жидкость слить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Мякоть мелко нарезать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Продукты перемешать, выложить на блюдо слоями, последовательность – любая.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10284,'Слои промазать майонезом или смесью майонеза и сметаны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Мясо, ветчину и маринованные огурцы нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Свежие грибы хорошо промыть, нарезать, прожарить с репчатым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Если для приготовления используются маринованный продукт, то достаточно простой нарезки на кусочки крупного размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Два варианта: выложить салат слоями или перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10285,'Заправить майонезом, поперчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10286,'Отварить куриное филе, разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10286,'Натереть отваренные желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10286,'Измельчить заранее замоченный чернослив, грецкие орехи, белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10286,'Выложить на тарелку слоями: куриное мясо, желтки, смазать майонезом, второй слой – чернослив с майонезом, засыпать орехами и белком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10286,'Из колбасы сделать хвост, пятачок, уши. Глаза – из маслин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10287,'Крупными кубиками порезать отваренные куриные яйца, куриное мясо, морковь, картофель и свежие огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10287,'Массу посолить по вкусу, перемешать, заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10287,'Выложить салат в виде поросенка, засыпать поверхность тертым сыром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10287,'Сделать мордочку из маслин и колбасы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Отварить курицу, остудить, нарезать соломкой, поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Отварить вкрутую яйца, натереть, заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Промыть чернослив в холодной воде, далее обдать кипятком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Воду слить, еще раз залить сухофрукты новой порцией воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Подождать, пока продукт не станет мягким, нарезать полосками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Свежие огурцы нарезать соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Грецкие орехи перемолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Порубить зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Продукты выложить слоями в следующем порядке: на дно постелить листья зеленого салата.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Первый слой – курица, майонез, затем чернослив, яйца, перемешанные с майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Сверху выложить орехи, посыпать зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10288,'Слои повторить несколько раз, сверху насыпать орехи и зелень.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Промыть под проточной водой чернослив, обдать кипятком, воду слить, снова залить на несколько минут свежей порцией.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Размякшие сухофрукты нарезать кусочками среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Шампиньоны нарезать, жарить на сковороде с растительным маслом и луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Если жареный продукт нежелателен, на сковороду можно влить немного воды, тушить грибы до мягкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Когда вода испарится, добавить нарезанный лук, прогревать все вместе на тихом огне до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Отварить куриные яйца, натереть на крупной терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Так же натереть твердый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Свежий огурец нарезать кубиками или соломкой, посолить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Выделившийся сок отжать, нарезку переложить в другую емкость.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Куриное копченое мясо нарезать кубиками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Выложить салат слоями: большая часть распаренного чернослива, майонез.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Куриное мясо, майонез.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Третий слой – грибы и огурцы с молотой паприкой и майонезом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Отваренные яйца с майонезом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10289,'Последний слой – сыр и чернослив.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Отварить яйца и клубни картофеля.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Шампиньоны нарезать и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Разделить и натереть желтки и белки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Массу выкладывать двумя горками: большую и поменьше, туловище и голову.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Первый слой – грибы, затем картофель, белок, огурцы, желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Слои промазывать майонезом, сверху – сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Из вареной колбасы вырезать уши и пятачок. Глаза можно сделать из маслин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10290,'Поставить блюдо в холодильник на два часа для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10291,'Нарезать кубиками копченую куриную грудку, свежие огурцы и репчатый лук. Можно использовать красный лук-шалот.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10291,'Отварить морковь, яйца и картошку, нарезать произвольно, добавить в салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10291,'Заправить массу майонезом, при необходимости посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10291,'Выложить на блюдо в виде поросенка, посыпать тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10291,'Детали мордочки можно сделать из колбасы и маслин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10292,'Желатин разводим горячим молоком, ставим на паровую баню и помешивая даем желатину полностью раствориться, при этом молоко закипеть не должно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10292,'В чашу блендера кладем творог, сметану, сахарную пудру и ванилин взбиваем около трех минут. Добавляем молоко с желатином, которое уже достаточно остыло. Взбиваем еще около 2 минут.','https://vkuso.ru/data/cache/data/62/d9e87416e3fdf62_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10292,'Разливаем по креманкам, по желанию можно добавить ягоды. У меня красная смородина, сочетание сладкого десерта и легкой кислинки смородины делает этот замечательный десерт еще вкуснее! Отправляем в холодильник на 3-4 часа.','https://vkuso.ru/data/cache/data/49/9a2ddc015b7b949_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10292,'Если Вы делали десерт в одной большой форме и Вам нужно его извлечь для того, чтобы поделить на порционные кусочки. Для этого опустите форму с десертом на несколько секунд в горячею воду, следите чтобы вода не попала на сам десерт. Затем накройте тарелкой, переверните и хорошо встряхните. Приятного аппетита!!!','https://vkuso.ru/data/cache/data/55/26cd415e27f5155_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Овощи очистить, нарезать кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Переложить в сковороду, влить оливковое масло и обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Овощной бульон вскипятить, положить обжарку, варить все вместе в течение восьми минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Положить чечевицу и красную фасоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Брокколи разобрать, соцветия поместить в бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Нарезать спаржу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Покрошить кабачок цуккини.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Шпинат порубить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Все ингредиенты добавить в бульон, варить пятнадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Соль и перец – по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Треть похлебки переложить в блендер, размолоть в пюре.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10293,'Массу отправить в суп, время прогревания – три минуты.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Горох замочить с вечера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Нарезать сельдерей, мелко нашинковать репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Обжарить без масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Натереть морковь на средней терке, измельчить чеснок, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Налить в кастрюлю воду, пересыпать горох, отварить в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Добавить обжарку, морковь с чесноком, массу прогреть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10294,'Нашинковать зелень, положить в суп, всыпать перец, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Шампиньоны промыть, нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Болгарский перец нарубить соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Репчатый лук разрезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Довести воду до кипения, положить лук, отварить в течение пятнадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Овощ выбросить, он больше не понадобится.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'В бульон поместить грибы, варить четверть часа, пенку снимать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Всыпать гречку, суп проварить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Вторую часть луковицы измельчить, положить в суп, поперчить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Нарезать зелень.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10295,'Всыпать в похлебку тогда, когда крупа станет мягкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Довести воду до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Нарезать картофель, положить в кастрюлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Капусту нашинковать, добавить в картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Белокочанную капусту нашинковать, добавить в кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Потереть свежую свеклу, морковь, положить в суп, варить до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Нарезать репчатый лук, порубить зелень, добавить в похлебку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10296,'Все ингредиенты перемешать, прогревать пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Отварить куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Очистить и нарезать киви.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Продукты измельчить кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Так же поступить с копченым куриным филе или окорочком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Ингредиенты выложить слоями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Перец и соль по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Каждый слой промазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10297,'Украсить зернами граната.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Яйца смешиваем со сгущенным молоком. Добавляем растопленное сливочное масло. Перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Просеиваем муку и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Замешиваем тесто: соединяем вместе яично-сгущеную смесь и муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Банан режем на кружочки. На дно формы наливаем немного растительного масла. Выкладываем банан (можно также смешать банан с тестом, получится также очень вкусно).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Сверху банана выливаем тесто. Выпекаем в разогретой до 180 градусов духовке 30-40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10298,'Готовому кексу даем остыть. Кекс будет вкуснее если полить сгущенкой. Приятного аппетита! 	','https://vkuso.ru/data/cache/data/d6/dbd34035a5b39d6_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Нежирное куриное филе отварить, остудить, поделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Мясо нарезать соломкой или небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Нашинковать стебли сельдерея, зеленый лук, добавить в курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Фисташки очистить и порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Если виноград с косточками – их нужно вынуть, ягоды разрезать пополам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Продукты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10299,'Заправить несладким йогуртом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Копченый куриный окорок и киви нарезать небольшими кубиками и перемешать с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Переложить на тарелку, разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Яйца отварить, отделить желтки от белков, натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Белки высыпать на курицу, сверху – майонез и морковь по-корейски.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Очистить яблоки, потереть на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Выложить на яблоки и так же заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10300,'Сверху – тертые желтки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Приготовьте продукты','https://vkuso.ru/data/cache/data/74/1394611b9250f74_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Смешайте желток, сметану, сахар, растительное масло. В муку добавить разрыхлитель и замесить эластичное тесто.','https://vkuso.ru/data/cache/data/61/624c4c56536a761_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Тесто раскатать в жгутик и разрезать на кусочки.','https://vkuso.ru/data/cache/data/f4/56d76507b3f99f4_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Сделать узор.','https://vkuso.ru/data/cache/data/00/290f8882622a900_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Выпекать на сковороде до золотистой корочки.','https://vkuso.ru/data/cache/data/1b/290e14017c88b1b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10301,'Приятного аппетита.','https://vkuso.ru/data/cache/data/39/33d04600d3e0e39_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Вымыть, обсушить, выложить на тарелку листья зеленого салата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Куриное мясо обжарить, остудить, нарезать кубиками, выложить на листья.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Сверху намазать майонез, крошку миндаля или грецких орехов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Натереть сыр на крупной терке, лучше, если продукт будет с терпким вкусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Насыпать поверх орехового слоя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Приправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Отварить и натереть яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Разложить сверху, намазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10302,'Ягоды винограда разрезать пополам, косточки удалить, украсить салат.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Отварить на пару куриную грудку, продукт должен получиться нежным, но не разваренным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Нарезать кубиками мякоть свежего ананаса, порубить орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Часть сыра натереть, часть – нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Продукты перемешать, заправить натуральным йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Тарелку покрыть листьями зеленого салата, переложить салатную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10303,'Посыпать тертым сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10304,'В фарш добавляем обжаренные лук с морковью, тертый на мелкой терке сырок, яйцо, соль, перец. В 100 мл воды растворяем томатную пасту и соединяем со сметаной, добавляем специи и соль по вкусу.','https://vkuso.ru/data/cache/data/02/bf2b45064d56e02_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10304,'В блюдо кладем очищенный картофель, в центр кладем сформированные котлеты, заливаем подливой и отправляем в разогретую духовку на 1 час. Затем посыпаем тертым сыром и отправляем в духовку на 3 минуты. Приятного аппетита!','https://vkuso.ru/data/cache/data/6d/575af07a489476d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10305,'Приготовим начинку №1.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10305,'Приготовим начинку №2.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Отцедить консервированную красную фасоль и кукурузу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Продукты перемешать, посолить по вкусу, приправить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Полить кукурузным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10314,'Репчатый лук, куриное мясо или говяжью вырезку нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10305,'На лаваш выкладываем начинки и равномерно распределяем. Заворачиваем в рулет. Режем рулет поперек на порции шириной 2-4см. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10306,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/1e/bfb3ad1e360041e_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10306,'Смешайте все ингредиенты. Муку добавлять постепенно.','https://vkuso.ru/data/cache/data/03/4af5cc38bb79e03_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10306,'Замесить тугое тесто. Даем настоятся 3-4 часа, а лучше ночь, в теплом месте.','https://vkuso.ru/data/cache/data/ee/d0c344daa06dfee_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10306,'Выпекаем любым способом, по 2-3 минуты. Если в духовке, то при 180 градусах.','https://vkuso.ru/data/cache/data/11/b251f50d69c0911_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10306,'Приятного аппетита.','https://vkuso.ru/data/cache/data/6b/f76fedc2626626b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Столовый уксус наполовину разбавить водой, положить в него нарезанный полукольцами репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Через двадцать минут жидкость отцедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Отварную говядину нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Отварить куриные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Яйца и сыр «Пармезан» или «Российский» натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Порядок слоев: лук, мясо, яйца, тертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Все слои посолить и поперчить, промазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10307,'Готовое блюдо поставить на час в холод для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Редьку вымыть, очистить, натереть, посолить и оставить на некоторое время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Репчатый лук измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Заранее отваренное куриное мясо порубить ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Измельчить очищенные зубчики чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Натереть морковь, отваренные яйца, сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Отжатую редьку выложить на блюдо, затем лук, мясо, тертую морковь с чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Слои промазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Сверху – тертый сыр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10308,'Блюдо поставить в холодильник на час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Разбавить уксус водой, всыпать сахар, замариновать колечки фиолетового лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Нежирную свинину нарезать кусочками, жарить на растительном масле до корочки, по три-четыре минуты с каждой стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Отварить картофель, измельчить на терке, перемешать с постным майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Выложить на тарелку часть картофеля, мясо, лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Слои пропитать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Сверху – яйца, картофель, тертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10309,'Закуску поставить в холод на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Репчатый лук нарезать полукольцами, обдать кипятком для избавления от горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Нарезать кубиками сыр и ветчину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Отварить яйца, желтки и белки измельчить отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Выложить продукты слоями: репчатый лук, ветчина, белки, нарезанный сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Каждый слой промазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Сверху закуску посыпать желтками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10310,'Поставить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Зеленую редьку вымыть, очистить от кожуры, натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Полученную массу отжать руками, сок слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Майонез приправить солью и давленым чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Копченую куриную грудку отделить от косточки, снять, шкурку, разобрать на волокна.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Мелко нашинковать очищенный лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Потереть крупную и сочную морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Ингредиенты выложить слоями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10311,'Каждый слой промазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10312,'Заранее отваренную говядину и яйца нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10312,'Если использовать свежие грибы, то их нужно обжарить, от маринованных отцедить жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10312,'Очистить яблоко от сердцевины и кожуры, натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10312,'Продукты соединить, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10312,'Готовую закуску украсить половинками маслин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Отварную говядину и сладкий болгарский перец оранжевого цвета нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Зеленый лук нашинковать колечками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10313,'Морковь по-корейски нарубить ножом на некрупные кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10314,'Картофель вымыть, очистить, также нарезать соломкой. Залить его кипящей водой, довести до кипения, сразу откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10314,'Разогреть на сковороде растительное масло, обжарить лук и мясо на сильном огне в течение пяти – шести минут. Посолить, поперчить, добавить соевый соус, кориандр, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10314,'Добавить в картофель. Очистить и нарубить чеснок, влить столовый уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10315,'Отварить молодой картофель, разрезать каждый клубень на две или три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10315,'Помидоры черри разрезать пополам, порубить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10315,'Прогреть оливковое масло на сковороде, добавить картофель и маслины, жарить пять минут, помешивать, огонь – слабый.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10315,'После подрумянивания картофеля добавить на сковороду помидоры и чеснок, полить бальзамическим уксусом, посолить. Все вместе прогревать две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10316,'Отварить до готовности на тихом огне картофель в мундире. Очистить от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10316,'Отварить яйца. Приготовить соус из майонеза, соли, перца, столового уксуса, горчицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10316,'Нарезать мелкими колечками стебель сельдерея, зеленый и обычный лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10316,'Перемешать, добавить кубики картофеля, яйца, заправку, поставить в холодильник для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10316,'При подаче блюдо посыпать еще одной порцией зеленого лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Свиные языки промыть, залить холодной чистой водой на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Мясо еще раз промыть, залить новой порцией воды, довести до кипения и откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Приготовить бульон из мяса с добавлением лаврового листа, гвоздики, душистого перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Время варки – около часа, затем добавить лук и морковь целиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Прогревать до готовности языков, соль и черный перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Прохладной водой залить желатин, оставить для набухания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Отваренные языки вынуть, залить холодной водой и очистить от кожи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Готовый бульон процедить, соединить с желатином, прогревать на тихом огне до растворения комочков. До кипения не доводить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'В небольшие пиалы налить бульон на треть объема, остудить на холоде.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Разложить поверх желе нарезанную звездочками или кружочками отваренную морковь, ломтики языка.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10317,'Залить оставшимся бульоном и снова остудить в холодильнике.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Снять кожицу с говяжьего языка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Сердце вымыть и разрезать на четыре части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Крылья и лапки индюка зачистить от чешуек и коготков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Все продукты переложить в кастрюлю большого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Залить водой, добавить целую очищенную морковь, лук, лавровый лист, соль, перец-горошек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Довести бульон до кипения, огонь убавить, варить три часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Морковь удалить через полчаса после начала варки, нарезать кружками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Бульон процедить, добавить давленый чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Субпродукты нарезать пластинками, с лапок и крыльев снять кусочки мяса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'На дно небольших силиконовых форм выложить морковь, мясо и кружочки заранее отваренных перепелиных яиц.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10318,'Сверху – бульон с добавлением чеснока. Заливное поставить в холодильник для полного застывания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10319,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/57/8ab6ce05578dd57_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10319,'Смешайте все продукты.','https://vkuso.ru/data/cache/data/0d/2c7f227d072360d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10319,'Взбейте миксером.','https://vkuso.ru/data/cache/data/30/075ad826c7dad30_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10319,'Вылить в форму. Выпекать при 180 градусах 50 минут.','https://vkuso.ru/data/cache/data/1b/43f25011d090c1b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10319,'Украсить по своему желанию. Приятного аппетита.','https://vkuso.ru/data/cache/data/aa/b20d09d632a56aa_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Говяжий язык положить в чашу вместе с солью, специями, луком-репкой, нарезанным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Выставить режим тушения на три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Мясо облить ледяной водой, снять кожу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Субпродукт нарезать кусочками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Бульон процедить, растворить в нем желатин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Овощи обжарить на подсолнечном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Половину полученной жидкости перелить в блюдо, остудить, выложить язык.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10320,'Залить остатками бульона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10321,'Зелень мелко нарежем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10321,'Лаваш выкладываем в тарелку (чтобы яйцо не вытекло). На лаваш разбиваем яйцо, взбиваем его вилкой. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10321,'Сворачиваем так, чтобы получился треугольник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10321,'На сковороду со сливочным маслом выкладываем ёку швом вниз и обжариваем с двух сторон до золотистой корочки. Наша ёка готова. Приятного аппетита!','https://vkuso.ru/data/cache/data/38/e840302566afd38_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Отварить картофель до готовности, размять при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Для приготовления заправки понадобится йогурт и майонез, горчица, продукты хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Половину мелко нарезанного зеленого лука и огурца добавить в заправку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Полить смесью картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Остатки огурцов и лука добавить вместе с измельченными яйцами сверху. Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10322,'Сельдь, приготовленную в укропном маринаде, выложить поверх салата вместе с маслинами, поперчить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Субпродукты промыть, варить на тихом огне полтора часа вместе с луковицей и морковью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Шелуху с луковицы не снимать, она придаст бульону приятный оттенок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'За полчаса до готовности бульона добавить в кастрюлю лавровый лист, соль, перец, специи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Опята отварить отдельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Желатин развести в холодной воде, оставить на несколько минут для набухания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Субпродукты вынуть, облить ледяной водой, очистить от кожицы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Языки нарезать ломтиками, перемешать с грибами, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Бульон процедить, досолить, добавить прованские травы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Влить желатин.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Массу нагреть и перемешивать до полного растворения желатина.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Тонко нарезать лимон вместе со шкуркой, маринованные огурцы – кружками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Выложить в форму грибы и мясо, лимон, огурцы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Залить бульоном.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10323,'Поставить в холод до застывания.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Залить холодной водой на два часа субпродукты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Жидкость слить, налить свежую воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Поставить вариться на два с половиной часа с морковью, корешками петрушки и сельдерея, лавровым листом и целой луковицей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Пену снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Отдельно приготовить куриный бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Охладить, развести желатин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Языки залить ледяной водой, очистить пленку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Мясо нарезать ломтиками, выложить в пиалы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Желатин влить в горячий говяжий бульон, добавить соль по вкусу и давленый чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Жидкость процедить через два слоя марли, залить мясо.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10324,'Украсить закуску зеленью, поставить в холодное место.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10325,'Репчатый лук нарезать небольшими кубиками, перемешать с размятым тунцом из банки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10325,'Нарезать яйца, отваренный картофель, соленые или маринованные огурцы, добавить в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10325,'Сверху – соль, перец, укроп. Ингредиенты перемешать и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10326,'Отварить и нарезать кубиками картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10326,'Репчатый лук измельчить, тресковую печень нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10326,'Отварить яйца, желтки покрошить и перемешать с печенью, консервированным зеленым горошком, луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10326,'Измельчить белки, лимон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10326,'Салат заправить маслом, посолить, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10327,'Белый хлеб нарезать мелкими кубиками, запечь на противне в духовом шкафу в течение 20 минут, температура – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10327,'Зеленый или репчатый лук измельчить, яйца и отваренный картофель нарезать кубиками. Продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10327,'Слить масло со шпрот, рыбу нарезать, переложить в салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10327,'Сухарики перемешать с маслом от консервов, половину добавить в блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Смешать кефир, масло, соль. Перемешать.','https://vkuso.ru/data/cache/data/b0/577a289c11299b0_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10327,'Для приготовления соуса понадобится лимонный сок, майонез, перец и соль. Заправить салат, посыпать остатками сухарей, зеленым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/ae/67e4cf84b2b58ae_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Сварите маринад. Поставить остывать.','https://vkuso.ru/data/cache/data/32/bf6f09be83f0132_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Лук порезать полукольцами, добавить соль, сахар - помять.','https://vkuso.ru/data/cache/data/24/61e8c9d15e78a24_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Добавить специи, масло и уксус. Оставить мариноваться.','https://vkuso.ru/data/cache/data/bd/d3bd703b937bfbd_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Рыбу разделать и залить остывшим маринадом. Поставить мариноваться на 1,5 - 2 часа.','https://vkuso.ru/data/cache/data/8a/7d9b6eb6c6eaf8a_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Вынуть рыбу из маринада. Засыпать маринованным луком. Оставить на полчаса.','https://vkuso.ru/data/cache/data/4e/41c38f7bd2e4d4e_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10328,'Приятного аппетита.','https://vkuso.ru/data/cache/data/31/32ee708a54a0c31_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Для приготовления бисквита к сырым желткам подсыпать половину нормы сахарного песка и ванилин. При помощи миксера превратить массу в светлый крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Белки взбить отдельно, подсыпать оставшийся сахар. Пену аккуратно ввести в желтковый крем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Муку перемешать с какао-порошком и разрыхлителем, просеять два или три раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Порциями ввести в яичную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Влить растопленное и охлажденное до комнатной температуры сливочное масло, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Вырезать из пергамента круг, положить на дно формы, переложить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Испечь корж при температуре 200 градусов, время приготовления – полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Переложить выпечку на решетку, накрыть полотенцем. Дождаться, пока остынет. Если есть время – дать коржу полежать восемь часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Приготовить крем: влить в сотейник воду, вбить желток, влить сгущенное молоко из банки. Уваривать массу до тех пор, пока она не загустеет.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Мягкое сливочное масло взбить с ванилином из пакетика, в несколько приемов ввести заварной крем. Всыпать какао-порошок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Бисквит разрезать на три коржа, пропитать чаем с сахаром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Промазать коржи кремом. Сверху обмазать торт любимым густым повидлом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Поставить в холодильник на полчаса.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Растопить на водяной бане шоколад со сливочным маслом. Готовой глазурью залить торт.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10329,'Украсить десерт можно на свой вкус – мармеладом, орехами, зефиром.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'В емкость насыпать муку, пищевую соду, какао-порошок, разрыхлитель. Сухую смесь два раза просеять через мелкое сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Отдельно взбить в пену сырые куриные яйца, перемешать со сгущенкой и сметаной. Ввести сухую смесь в несколько приемов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Застелить дно чаши пергаментом, переложить тесто, выставить режим «Выпечка». Время приготовления – от шестидесяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Корж вынуть, остудить, дать полежать несколько часов, а затем разрезать на три части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Растопить черный шоколад на водяной бане или в микроволновой печи. Немного остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Мягкое сливочное масло взбить в пену, добавлять порциями сгущенку, перемешанную с какао.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Влить растопленный шоколад, все вместе взбить до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Промазать коржи кремом. Поставить десерт в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Соединить шоколад, сливочное масло и жирные сливки, растопить продукты в микроволновке.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10330,'Торт смазать густым джемом, а потом полить глазурью. Перенести на блюдо.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10331,'Для начала нарежем грудку и обжарим ее на небольшом количестве масла. Добавим специи и овощи. Хорошо перемешаем. Добавляем томатную пасту и готовим до готовности.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10331,'Дно формы смажем сливочным маслом. Выложим 2 лаваша, как на видео. Сверху часть начинки, накрываем 2-мя кончиками одного лаваша, сверху поливаем половиной яично-кефирной смеси. Выкладываем начинку. Накрываем оставшимся лавашом и заливаем яично-кефирной смесью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Влить в емкость сгущенное молоко, всыпать просеянный какао-порошок. Перемешать ингредиенты при помощи ручного венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Вбить сырые куриные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Всыпать обычный и ванильный сахар, муку, разрыхлитель, положить сметану. Массу перемешать, в ней не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Испечь отдельно два коржа, время приготовления – от 35 до 40 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Переложить на разделочную доску, накрыть салфеткой, оставить на пять часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Размягченное сливочное масло взбить с какао-порошком, сгущенкой и ванильным сахаром при помощи миксера. Должна получиться густая масса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10332,'Собрать торт, обмазать остатками крема.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10333,'Сковороду ставим на средний огонь, наливаем в нее растительное масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10333,'Сливочное масло выкладываем в миску, туда же добавляем вареную сгущенку. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10333,'
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Приготовить бисквитное тесто из яиц, сахара, какао-порошка, ванилина из пакетика, муки и растопленного сливочного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Испечь корж в мультиварке или в духовке. Через несколько часов выпечку разрезать на четыре одинаковых коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Для приготовления первого крема взбить в миксере мягкое сливочное масло, время – две или три минуты, скорость – максимальная.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Добавить заранее взбитый желток, какао-порошок и просеянную сахарную пудру. Масса должна стать однородной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Влить охлажденное молоко, взбить все вместе еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Для второй прослойки тоже понадобится мягкое сливочное масло и сгущенное молоко. Добавить ванилин и немного какао, по цвету крем должен быть светлее, чем первый.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Для третьего крема взбить масло с вареной сгущенкой и сахарной пудрой. Эту массу подкрашивать не надо, она должна быть светлой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'На среднем огне проварить ром с сахаром в течение 20 минут. Алкоголь должен испариться. Если блюдо делается для детей, то этот ингредиент не использовать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Приготовить помадку из растопленного масла, какао-порошка, сахарной пудры. Вливать понемногу молоко, варить глазурь в течение десяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Коржи пропитать ромом с сахаром, прослоить кремами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10334,'Выдержать десерт в холоде один час. Затем полить его помадкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Перемешать какао-порошок и растворимый кофе. Залить горячей водой. Перемешать до однородности, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Сырые желтки взбить с сахарным песком, растительное масло без запаха влить небольшими порциями, добавить шоколадно-кофейную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Отдельно перемешать муку с содой и разрыхлителем. Сухие и жидкие ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Взбить в крепкую пену белки с солью и оставшимся сахаром. Аккуратно вмешать в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Время выпекания бисквита – 50 минут, температура – 160 градусов. Дверцу духовки не открывать, иначе масса осядет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Остудить корж в перевернутой форме, затем его вынуть, дать полежать пять или шесть часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Развести желтки водой, влить смесь в сгущенное молоко, варить на пару до густоты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Снять массу с плиты, добавить кусочки шоколада и перемешать до растворения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Остывший заварной крем взбить со сливочным маслом, по желанию для аромата можно добавить коньяк.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Шоколадный корж разрезать на три части, промазать кремом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10335,'Приготовить помадку: насыпать в воду какао-порошок, сахар, довести смесь до кипения, подержать минуту или две, затем добавить сливочное масло. Смесью облить торт.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/51/8ada0e800547851_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'В муку добавить соду и ванилин. Добавить к кефиру полпорции.','https://vkuso.ru/data/cache/data/16/06fbe1ad6ab5616_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Добавить остатки муки и сухофрукты. Замесить тесто.','https://vkuso.ru/data/cache/data/6a/fd54a13d0f89b6a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Выложить тесто в формочки на 2\3.','https://vkuso.ru/data/cache/data/3d/78cfb5f719dbc3d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Выпекать в духовке при 180 градусов 30 минут.','https://vkuso.ru/data/cache/data/d3/119ee16f97154d3_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10336,'Приятного чаепития.','https://vkuso.ru/data/cache/data/2f/13756a51270032f_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10337,'Нашинкуйте капусту. Залейте ее кипятком и накройте крышкой на 10 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10337,'Измельчите лук кубиками. Разогрейте сковороду. Налейте растительное масло и поджарьте лук до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10337,'С капусты слейте воду и перемешайте ее с луком. Добавьте соль, яйцо и муку. Все тщательно перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10337,'На разогретую сковороду с растительным маслом добавляйте капустное тесто по 1 ст.л. Обжарьте оладушки с двух сторон до золотистого цвета. Выложите готовые блинчики на тарелочку застеленную бумажной салфеткой, чтобы она впитала в себя лишнее масло. Я подаю их со сметанкой. Это очень вкусно!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10338,'С куриных грудок срезать жир, удалить пленки, вымыть и высушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10338,'Насыпать в небольшую емкость черный и душистый перец, паприку и соль, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10338,'Обвалять грудки, оставить для просаливания на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10338,'Удалить лишние приправы, мясо повесить сушиться на два дня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10338,'Далее обернуть заготовку бумагой, оставить на 12 часов для дозревания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10339,'Филе очистить и просушить, обернуть пищевой пленкой, положить в морозилку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10339,'Выжать лимон, добавить масло, соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10339,'Подмерзшее, но не перемерзшее филе нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10339,'Дождаться оттаивания, выложить на красивую тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10339,'Полить заправкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Куриное филе сбрызнуть коньяком, натереть солью крупного помола.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Сложить в емкость, накрыть крышкой, оставить при комнатной температуре на два дня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Мясо промыть от соли, повесить под потолок хорошо проветриваемого помещения, подождать еще одни сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'В летнее время продукт лучше завернуть в марлю для защиты от насекомых.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Далее подержать продукт в холоде в течение 24 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Подготовить коптильню, насыпать щепки, закрепить емкость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Мясо выложить, выставить режим «Холодное копчение» на 20 минут, крышку закрыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10340,'Подать к столу в тонко нарезанном виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10341,'Дрожжи смешиваем с сахаром, добавляем теплое молоко и оставляем на 10 минут, чтобы дрожжи оживали.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10341,'Тесто должно получиться мягким, воздушным, не липнуть к рукам. Оставляем тесто увеличиться в два три раза в теплом месте без сквозняков на 1-2 часа.','https://vkuso.ru/data/cache/data/1c/d0aeee0e44e6a1c_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10341,'Тесто делим на 4 части, каждую часть раскатываем в жгут и делим на равные части, у меня вышло 20 шт. Из каждого кусочка формируем колобок, колобок раскатываем выкладываем в центр на противень, застеленный пергаментной бумагой, вокруг него будем формировать цветок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10341,'На противне формируем цветок и накрыв полотенцем даем булочкам подойти еще раз в течении 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10342,'Куриные филе разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10342,'Кусочки завернуть в пищевую пленку, положить в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10342,'Выжать сок из апельсина и лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10342,'Влить оливковое масло, всыпать специи, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10342,'Подмерзшее мясо тонко нарезать, выложить на блюдо, полить заправкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Куриные грудки положить в морозилку, каждый кусочек обернуть в пленку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Выдавить сок из лимона и лайма.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Смешать с маслом оливы, перцем, солью, паприкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Грудку тонко нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Положить в маринад, подержать на холоде два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10343,'Мясо просушить, подать к столу с зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Куриное филе разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'В соль влить коньяк, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Дно емкости смазать соленой смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Выложить птицу слоями, промазывая заправкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Сверху вылить оставшийся маринад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Накрыть закуску крышкой, поставить в холод на сутки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Готовые грудки вымыть, обсушить, присыпать черным или красным молотым перцем, паприкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10344,'Каждый кусочек завернуть в марлю, вернуть в холодное место на неделю.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10345,'Листья зеленого салата порвать руками, выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10345,'Сверху – тонкие ломтики готового куриного карпаччо, половинки помидор черри, отваренные и разрезанные на четверти перепелиные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10345,'Приготовить заправку из оливкового масла, сока лайма, сушеных трав майорана и базилика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10345,'Салат посолить, поперчить, полить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10346,'Куриную грудку промыть, разрезать на несколько кусков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10346,'Обернуть их пищевой пленкой, поместить в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10346,'Лимонный сок перемешать с оливковым маслом, состав перемешать вилкой, посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10346,'Застывшее филе нарезать аккуратными тонкими кусочками. Это можно сделать при помощи слайсера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10346,'Выложить закуску на тарелку, полить соусом, украсить дольками лимона, листочками рукколы, помидорами черри.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Куриное мясо хорошо вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'В теплой воде растворить соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Положить филе на несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Мясо еще раз промыть, обсушить при помощи бумажной салфетки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Нарезать тонкими пластинками очищенный чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'К рафинированному маслу добавить столовую горчицу и любимые приправы, например, базилик, паприку, куркуму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'В середину мясных кусочков положить чеснок, завернуть, смазать масляной смесью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Разогреть духовой шкаф, отправить в нее закуску на 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Духовку выключить, дверку не открывать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10347,'Через четыре или пять часов пастрома будет готова.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Растопите маргарин. Смешайте его со сметаной, солью и сахаром. Хорошо перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Затем добавьте соду гашеную уксусом и муку, ее добавляйте постепенно, постоянно перемешивая тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Тесто хорошенько вымесите на столе и поделите на 8 частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Каждую часть раскатайте в виде круга и нарежьте треугольниками. На широкий край положите ложечку варенья и закрутите в рогалик.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Все рогалики выложите на противень застеленный пергаментом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Отправьте в духовку на 20-25 минут при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10348,'Когда рогалики остынут украсьте их пудрой. Я всегда рогалики складываю в глубокую миску и накрываю пакетом. Тогда они остаются всегда мягкими.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Приготовить тесто из яиц, сахарного песка, сгущенного молока, какао-порошка, сметаны, муки и соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Выпечь корж, время приготовления – от 40 до 60 минут, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Остывший бисквит разрезать на три коржа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Сгущенку взбить с какао-порошком и маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Коржи прослоить кремом и свежей или консервированной вишней без косточек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Приготовить глазурь из масла и растопленного шоколада. Полить торт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10349,'Украсить десерт вишней.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Куриное филе промыть, переложить в чашу с соленой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Поставить на сутки в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10350,'Крышку не открывать, оставить пастрому в закрытом устройстве на восемь часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'С костей срезать куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Промыть, удалить кожу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Сложить по два кусочка мяса валетом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Перевязать нитью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Посолить и посыпать куркумой, пряными травами, молотым перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Завернуть подготовленные филе в фольгу, сделать проколы зубочисткой, чтобы выходил пар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Выложить кулечки на противень, поставить на полчаса в духовку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Температура тушения – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'Заготовки развернуть, вернуть в духовку на десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10351,'В процессе тушения поливать мясо выделяющимся соком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10352,'Замочить в молоке хлеб (примерно на 4-5 минут), включить на разогрев духовку (200 градусов). Обжарить измельченную ветчину, через несколько минут добавить чеснок, измельченный лук, посолить, поперчить, перемешать, чуть остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10352,'Смешать куриный фарш с отжатым хлебом, столовой ложкой томатной пасты, обжаренной ветчиной с луком и чесноком, вбить яйцо, всыпать измельченную петрушку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10352,'Скатать из смеси 12 шариков, переложить их на противень, смазать смесью оливкового масла и томатной пасты. Вставить противень на самый верх духовки, тефтели из куриного фарша с ветчиной будут готовы через 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Куриное филе промыть, замочить на ночь в воде с солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Утром заготовки просушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Филе обернуть кулинарными нитками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Растительное масло перемешать с натуральным медом, давленым чесноком, сладкой паприкой, молотым перцем чили, мускатным орехом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Филе обмазать смесью со всех сторон, печь в духовом шкафу в течение 20 минут при максимальной температуре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10353,'Оставить пастрому для остывания, дверку не открывать несколько часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Филе птицы промыть, очистить от пленок и кожи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Замочить в молоке на два или три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Соевый соус досолить, добавить давленый чеснок, сладкую молотую паприку, молотый мускатный орех.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Филе вынуть, обсушить бумажными салфетками, переложить в маринад, оставить на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Мясо завернуть в фольгу, поставить в заранее нагретую духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'Запекать пастрому в течение получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10354,'За несколько минут до окончания приготовления фольгу развернуть, закуску допечь до румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10355,'Включить на разогрев до 230 градусов духовку. Добавить в мягкое сливочное масло тертый сыр, муку, влить коньяк, посолить, вымесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10355,'Раскатать его в прямоугольник сантиметровой толщины, нарезать в форме палочек шириной примерно по 1-1,5 см, переложить сырные палочки на противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10355,'Выпекать золотистые сырные палочки примерно 16-18 минут, до соответствующего оттенка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Стебель сельдерея измельчить, зеленый лук нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Сковороду смазать маслом с помощью силиконовой кисти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Положить измельченные продукты, приготовить обжарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Воду довести до кипения, положить нашинкованный шпинат, обжарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Отдельно бланшировать помидоры, снять кожицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Овощи перетереть на крупной терке, перелить в бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Все вместе вскипятить, варить пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10356,'Влить лимонный сок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Репчатый лук разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Воду довести до кипения, отварить лук в течение восьми минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Поместить хорошо промытое куриное филе, лук вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Варить в течение часа, мясо удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Морковь измельчить на крупное терке, положить в бульон вместе со стручковой фасолью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Гречневую лапшу поломать, отправить к овощам, поперчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10357,'Варить четверть часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10358,'Белокочанную капусту нашинковать, нарезать морковь мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10358,'Воду вскипятить, выложить морковь, капусту, стручковую замороженную фасоль, варить пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10358,'Размять томаты или мелко порубить, варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10358,'Настаивать блюдо без огня в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10359,'Клубни картофеля порубить, черешки сельдерея нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10359,'Кабачки нарезать кубиками, морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10359,'Вскипятить воду, выложить нарезанные овощи, варить до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10359,'Содержимое кастрюли остудить, измельчить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10359,'Всыпать специи, перемешать, еще раз довести до кипения и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Довести воду до кипения, положить в нее говядину, отварить в течение получаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'В процессе приготовления пену убирать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Всыпать белый молотый перец, положить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Репчатый лук нарезать полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Варить в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Мясо вынуть, нарезать, положить обратно в бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Брокколи разобрать на соцветия, поместить в суп, проварить до размягчения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Все вместе взбить при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10360,'Положить плавленый сыр, перемешивать суп до растворения продукта.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Томаты обдать кипятком и снять кожицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Мякоть нарезать соломкой или порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Нашинковать репчатый лук, натереть морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'То и другое тушить на сковороде в течение семи минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Положить нарезанный томат, прогреть все вместе еще пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Обжарку положить в кастрюлю, залить водой, прогреть до закипания, варить еще семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Рыбное филе нарезать кусками среднего размера, отправить в бульон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Если для блюда используется камбала, то куски должны быть крупными.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Залить молоком, перемешать, поварить пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Нашинковать зелень, посыпать похлебку, поперчить и посолить по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Перемешать, огонь погасить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10361,'Рыбу вынуть, разобрать, удалить кости, мякоть поместить обратно в суп.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10362,'Перемешать муку с яйцами, майонезом, разрыхлителем, замесить тесто по густоте похожее на сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10362,'Приготовить из нарезанной ветчины и натертого сыра начинку. Вылить 1/2 часть теста в форму, положить сверху начинку, залить остатками теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10362,'Присыпать пирог сверху измельченным сыром. Быстрый пирог с сыром и ветчиной в духовке будет готов через 30 минут, температура для выпечки 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Нагреть сухую сковороду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Порубить очищенный чеснок, смешать с мускатом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Отправить смесь на сковороду, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'В небольшую кастрюлю влить воду, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Всыпать соцветия цветной капусты, варить шесть минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Морковь натереть на терке среднего размера, добавить в воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Положить чеснок, варить пятнадцать минут под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Зелень петрушки порвать, добавить в бульон, поперчить, перемешать',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10363,'Соль – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Воду довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Положить нарезанную крупными кусочками морковь и картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Репчатый лук нарезать полукольцами, сладкий перец – полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Продукты добавить в бульон, довести до кипения, варить пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Нашинковать белокочанную капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'Отцедить зеленый горошек.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10364,'То и другое добавить в бульон, варить полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10365,'Воду вскипятить, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10365,'Нарезать крупными кусками картофель и морковь, сладкий перец, положить в воду вместе с брокколи, чесноком, шпинатом, отварить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10365,'Взбить при помощи погружного блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10365,'Если суп получился жидким – добавить муку или крахмал, еще раз взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10365,'Всыпать соль и специи, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10366,'Взбейте яйца с сахаром. Добавьте кефир и соду. Затем растительное масло и муку. Все тщательно взбейте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10366,'Формочку для мультиварки или духовки смажьте растительным маслом. Залейте в форму тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10366,'Поставьте выпекать в мультиварку на 55 минут при температуре 160 градусов или в духовку на 45-50 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10366,'Пока пирог выпекается приготовьте шоколад. Для этого в кастрюльке смешайте сахар, шоколадку, сметану и сливочное масло. Варите на медленном огне, помешивая. Когда шоколад закипит, поварите его 1-2 минутки. Дайте остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10366,'Готовый остывший пирог смажьте шоколадом и украсьте рубленными орехами.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10367,'Растопить на водяной бане шоколадную пасту с орехами и сливочное масло, взбить сахарный порошок с яйцами. Всыпать разрыхлитель, смешанный с мукой, порошок какао, посолить, тщательно перемешать. Включить на разогрев духовку (200 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10367,'Добавить к шоколадной смеси взбитые яйца, перемешать. Заполнить этой массой смазанные маслом формы на 2/3 объема. Убрать формы в духовку, домашний шоколадный  фондан будет готов примерно через 7 минут. Если фондан передержать, то получится обычный кекс без жидкой серединки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10367,'Этот нежный французский шоколадный десерт хорошо подавать с шариками мороженого.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Слоеное дрожжевое тесто подержать при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Зеленый щавель вымыть и потушить со сливочным маслом. Соль и молотый перец добавить по вкусу. Если готовится десерт – всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Выложить тесто в форму с бортиками, далее – начинка, второй пласт теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Чтобы края лучше слиплись, использовать болтушку из яиц и молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Сделать несколько проколов вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10368,'Пирог смазать яйцом, посыпать рубленым арахисом, печь в духовом шкафу. Время приготовления – от 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10369,'Перемешать сахарный песок с дрожжами, влить подогретое молоко. Ввести сырое яйцо, растопленное, но не горячее масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10369,'Муку просеять, замесить тесто, оно не должно быть тугим. Поставить в тепло на 45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10369,'Щавель потушить с маслом и сахаром. Масса в процессе тепловой обработки должна уменьшиться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10369,'Половину теста выложить в форму, затем начинку, закрыть сверху другой половиной теста. Время выпекания – от 45 до 50 минут, температура – от 190 до 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10370,'При помощи миксера взбить сырые яйца, сахар добавлять порциями. Масса должна получиться пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10370,'Ввести пекарский порошок и муку на малых оборотах и с другой насадкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10370,'Разъемную форму смазать маслом, выложить нарезанный щавель и залить тестом. Температура приготовления – 180 градусов, готовность проверить зубочисткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10371,'Стол посыпать мукой, раскатать готовое слоеное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10371,'Щавель нашинковать, брынзу нарезать мелкими кубиками, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10371,'Выложить начинку на лепешку, подтянуть края к центру, защипать, оставить отверстие.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10371,'Смазать тесто взбитым сырым яйцом, печь в течение 40 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10372,'Перемешать растопленное сливочное масло со сметаной, мукой, взбитыми с сахаром яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10372,'Разделить тесто пополам, часть раскатать в лепешку между листами пергамента. Вторую часть обернуть пленкой, обе положить в холод на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10372,'Для приготовления начинки перемешать нарезанный соломкой щавель с творогом, крахмалом и сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10372,'Выложить в форму охлажденную лепешку, срезать края. Выложить начинку, сверху – оставшееся тертое тесто и обрезки. Температура выпекания – от 170 до 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10373,'Подготовить кастрюлю подходящего размера с толстым дном, сполоснуть ее водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10373,'Налить молоко, прогреть до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10373,'Нагрев сделать минимальным, засыпать малыми порциями вермишель при непрерывном помешивании, чтобы она не склеилась в комок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10373,'За несколько минут до готовности молочный суп с любимой вермишелью чуть-чуть подсолить, положить сахар, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10374,'Сложить ингредиенты в чашу, залить молоком, закрыть мультиварку, запустить необходимый режим.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10374,'Если нет опции "Молочная каша", необходимо довести до кипения молоко в любом режиме (суп, жарка, мультиповар).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10374,'Заправить его вермишелью, подсолить, добавить масло с сахаром, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10374,'Варить минут 7 на режиме «Мультиповар».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10375,'Отварить очищенный картофель, добавить масло, молоко, приготовить пюре. Обжарить мелко нарезанный лук с измельченными грибами, жарить до полного испарения жидкости. Смешать пюре и грибы. Включить на разогрев до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10375,'Куриные голени поперчить, посолить, обжарить со всех сторон около получаса, оставить остывать. Заняться подготовкой готового слоеного теста: раскатать толщиной в 3 мм, нарезать квадратами со стороной 15 см, сохранить обрезки. Из обрезков сформовать небольшую лепешку и уложит по центру на каждый квадрат. Положить на нее пару ложек начинки, поставить вертикально голень, края теста загнуть вверх и связать ниткой (только не туго).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10375,'Переложить мешочки на застеленный пергаментом противень (бумагу слегка смазать маслом). Надеть на косточки колпачки из фольги, чтобы их концы не подгорели. Выпекать куриные ножки в мешочке с картофелем и грибами около 20 минут. Когда мешочки будут готовы не забыть с них снять нитку. Это оригинальное блюдо должно понравиться гостям.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10376,'Отварить картофель, порезанные на мелкие кубики, до мягкости, т.к. в молоке он не разваривается, вода должна лишь чуть-чуть покрывать картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10376,'Довести молоко, почти до кипения, залить им картошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10376,'Добавить вермишель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10376,'Варить молочный суп с вермишелью и картофелем без сахара до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10376,'Перед окончанием варки подсолить и добавить любимые специи по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Очистить тыкву от семян и кожуры, нарезать на кусочки средние величины, залить небольшим количеством воды, варить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Удобным способом приготовить тыквенное пюре, используя блендер, пестик или протереть сквозь мелкое сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Молоко нагреть, залить тыквенное пюре, поставить на плиту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Нагреть, добавить вермишель, сдобрить специями и всыпать сахар, размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Варить суп молочный суп с вермишелью, тыквой и корицей до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10377,'Разлить по тарелкам и положить в каждую по кусочку масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10378,'В подсоленной воде отварить фигурные макаронные изделия или вермишель почти до готовности, время указано обычно на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10378,'Выложить их в дуршлаг, обдать горячей водой, чтобы они не слиплись в комочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10378,'Довести до кипения молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10378,'Добавить в него сахар, масло и залить макаронные изделия.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10378,'Варить молочный суп с вермишелью и маслом для ребенка до полной его готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Сладкое молоко довести до кипения, подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Всыпать вермишель, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Проварить пару минут, чтобы крахмал заварился и вермишель не превратилась в комок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'За это время в кружке, с добавлением небольшого количества воды, разболтать яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Энергично помешивая, влить тонкой струйкой в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Добавить мелко натертый зубчик чеснока, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10379,'Варить молочный суп с яйцом и чесноком до готовности вермишели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10380,'Очистите картофель и поделите на 4-6 частей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10380,'Курочку поделите пропорционными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10380,'Смешайте курочку и картофель. Добавьте соль, перец, паприку, кориандр, сушенный чеснок и растительное масло. Все тщательно перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10380,'Отправьте в духовку на 70 минут при температуре 180 градусов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10381,'Варить для этого салатика ничего не надо. Нарезать все ингредиенты соломкой, добавить зеленый горошек, кукурузу, заправить сметаной или майонезом, посолить. Все аккуратно перемешать и вкусный салат с колбасой на скорую руку готов к употреблению.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10382,'Для теста смешаем разрыхлитель и муку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10382,'Обильно посыпаем стол мукой. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10382,'Мини-пиццы можно запечь в духовке, а можно пожарить на сковороде.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10383,'Всыпать в воду дрожжи, вбить яйцо, положить муку, сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10383,'Замесить тесто, оставить на некоторое время, масса должна подойти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10383,'Растопить на сковороде сливочное масло, потушить  нашинкованный щавель, продавить его через сито. Другой вариант: взбить блендером в пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10383,'Тесто раскатать в лепешку прямоугольной формы, смазать начинкой, посыпать нарезанными отваренными яйцами. Свернуть рулетом, соединить в кольцо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10383,'Расплавить в кастрюле сливочное масло, положить пирог, прогревать на огне до зарумянивания, перевернуть на другую сторону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Подогреть воду, всыпать сахар, дрожжи из пакетика, хорошо перемешать и оставить на несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Мягкое сливочное масло или маргарин растереть с мукой в крошку. Влить дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Быстро замесить тесто, сформовать колобок, накрыть полотенцем и оставить в тепле на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Листья щавеля вымыть и обсушить. Нарезать соломкой, положить в миску. Посыпать сахаром и потереть руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Половину теста раскатать, выложить в форму, сверху посыпать крахмалом и выложить начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10384,'Края защипать, наколоть тесто вилкой в нескольких местах. Время выпекания – полчаса, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10385,'Грибы вымыть, обсушить салфеткой, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10385,'Прогреть сковороду, выложить грибы, посолить по вкусу, прогревать без масла до испарения жидкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10385,'В конце приготовления поперчить и положить сметану. Тушить под крышкой пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Шампиньоны вымыть, нашинковать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Репчатый лук нарезать тонкими полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Продукты обжарить вместе на масле в течение четырех минут. Помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Долить воду, потушить обжарку под крышкой 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Блюдо посолить по вкусу, влить взбитое яйцо и положить сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10386,'Кушанье прогреть и убрать с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10387,'Разрезать поперек багет на 3-4 части, а каждую часть —  на две половинки вдоль. Вынуть из половинок мякоть, оставить стенки в 1 см толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10387,'Нарезать огурец, колбасу, сосиски, помидор кубиками, аккуратно все перемешать, вбить яйцо, добавить немного майонеза, должна получиться вязкая масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10387,'Наполнить половинки багета начинкой, присыпать сверху сыром и запечь. Горячая закуска из сосисок в багете готовиться при 180 градусах около 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'Репчатый лук тонко нарезать, обжарить на подсолнечном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'Нарезать шампиньоны, добавить в лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'Отдельно обжарить картофель, нарезанный соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'Соединить с грибами, подлить воду и сметану, перец и соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'Накрыть сковороду крышкой, тушить 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10388,'При готовности посыпать блюдо рубленой петрушкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Нежирную свинину нарезать кубиками небольшого размера, обжарить с маслом на сковороде до появления румяной корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Оставшееся растительное масло нагреть в сотейнике, спассеровать репчатый лук, нарезанный полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Порубить ножом свежие или размороженные шампиньоны, переложить к луку, все вместе прогревать 5-6 минут, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Влить горячий мясной бульон, положить обжаренное мясо, поперчить и посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Порубить чеснок, добавить в основную массу вместе со сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10389,'Накрыть блюдо крышкой, тушить в течение 25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'В ёмкость перекладываем сливочное масло 150 грамм, сметану 150 грамм, и одну столовую ложку сахара! Все это надо очень хорошо взбить до кремовой основы!)','https://vkuso.ru/data/cache/data/09/593a5506037d809_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'Вот такая кремовая основа должна получиться.','https://vkuso.ru/data/cache/data/25/ac1a2b8e873c125_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'После того как взбили до кремовой основы, нужно замешать тесто, постепенно добавляйте просеянную муку. Замащивайте тесто. После того как замещали тесто, уберите его на 1 час в холодильник.','https://vkuso.ru/data/cache/data/18/0a9eca8b7d8e518_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'Вот такое тесто должно получиться .','https://vkuso.ru/data/cache/data/73/236a8f2e6d48873_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'Как только прошел час, достаньте тесто, разделите его на две половины! Одно половину раскатайте, чтобы ширина была 5-7 см.','https://vkuso.ru/data/cache/data/3a/7f7b5265325143a_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'И после этого нанесите джем и закатайте тесто в рулет.','https://vkuso.ru/data/cache/data/75/65b2907af1e6a75_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'После поделите рулет на маленькие печеньки.','https://vkuso.ru/data/cache/data/c6/78c9499c024f2c6_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'Переложите на противень и отправьте в разогретую духовку на 30-35 минут, при температуре 200 градусов до готовности!','https://vkuso.ru/data/cache/data/9d/348d446d1e7299d_434x295_notrise.png',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10390,'Как только печенье готово, дайте ему остыть и посыпьте сахарной подрой.','https://vkuso.ru/data/cache/data/95/bba9e1e581c3f95_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10391,'Нарезать на мелкие кубики стебель сельдерея, цукини, морковь, обжарить все на оливковом масле, добавить раздавленный прессом чеснок и тимьян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10391,'Смешать все с замоченной перловкой, залить водой, варить, закрыв крышкой 5-7 минут, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10391,'Обжарить белые грибы, добавить к перловке и тушить еще около 3 минут. Выложить перловую кашу с цукини и белыми грибами на тарелку, посыпать измельченной зеленью петрушки, подавать  со сметанным соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Курицу вымыть, промокнуть бумажным полотенцем, разрезать на части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Репчатый лук нашинковать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Шампиньоны вымыть и нарезать тонкими пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Раскалить подсолнечное масло, обжарить мясо со всех сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Отдельно обжарить лук с грибами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Обе обжарки перемешать, влить нежирную сметану, посолить, добавить специи для курицы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10392,'Прогревать блюдо в закрытой сковороде, время – около получаса, огонь – минимальный.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10393,'Выложить неразмороженные грибы на сковороду с заранее раскаленным маслом. Жарить от 5 до 7 минут. Сок должен выпариться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10393,'Добавить нарезанный репчатый лук, жарить все вместе 4 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10393,'Блюдо полить сметаной и посолить по вкусу, довести до кипения, огонь убавить до минимального. Тушить 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Грибы обтереть мокрой тканью и нарезать крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Нашинковать лук кубиками, обжарить на масле до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Ингредиенты соединить, прогревать до испарения влаги.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Влить сметану, посолить и поперчить, тушить в течение 12 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Блюдо снять с плиты, добавить желток.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10394,'Блюдо посыпать тертым сыром, подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Жирный (лучше домашний) творог размять. Если масса получилась крупинчатая – размять при помощи блендера или протереть через сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Добавить заранее растопленное сливочное масло, сырое яйцо, сахарный песок, ваниль или корицу, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Добавить просеянную муку, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Раскатать колбаски на столе, припыленном мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Нарезать кругляши, в каждом сделать вмятину пальцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10395,'Отварить изделия в подсоленной воде, в которую можно добавить и сахар. Время  приготовления – от трех до четырех минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Для начинки отварите картофель в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Лук нарежьте кубиками и поджарьте на растительном масле до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Когда картофель отварится, слейте с нее воду, добавьте сливочное масло и разомните картофель, добавьте немного воды с картошки, чтобы пюре могло легко размазываться по тесту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Для теста размешайте кефир с солью и содой. Затем постепенно добавляйте муку. Тесто вымесите на ровной поверхности, оно не должно приставать к рукам, но при этом должно быть мягким. Положите тесто в пакет и оставьте его на столе на 30 минут. ',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Тесто разделите на 8 ровных частей. Раскатайте круг, в центр положите картофель. Края защепите и скалкой немного раскатайте лепешку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10396,'Лепешку поджарьте на сухой сковороде с двух сторон до золотистого цвета. Горячую лепешку смажьте сливочным маслом. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10397,'Протереть или размять вилкой творог, перемешать с сахаром, яйцом, солью, всыпать муку. Тесто должно получиться нежным и мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10397,'Раскатать в толстый пласт, нарезать полосками, затем – прямоугольниками, ромбами или квадратами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10397,'Отварить в подсоленном кипятке. Время приготовления – от четырех до шести минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10397,'Вынуть вареники шумовкой, полить растопленным сливочным маслом. Подать к столу горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10398,'Срезать верхушки с помидоров, вынуть ложкой мякоть, оставить ее для добавления в фарш. Приготовить из вареного риса, говяжьего фарша и измельченной мякоти помидоров фарш, сдобрить чесноком, добавить мелкие кубики репчатого лука. Начинить фаршем помидоры, наколоть их в нескольких местах зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10398,'Переложить помидоры в форму, накрыть верхушками, положить между ними несколько веточек свежего тимьяна. Влить в форму немного воды, поставить помидоры в нагретую духовку (180 градусов), запеченные помидоры с говяжьим фаршем будут готовы через 15 минут. При подаче к столу украсить веточками петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10399,'Творог протереть через сито, смешать с яйцами и сахарным песком. Вмесить манку и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10399,'Массу убрать в холодильник на полчаса для набухания крупы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10399,'Всыпать муку, тесто не должно липнуть к рукам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10399,'Раскатать массу колбасками, нарезать на кусочки, отварить в подсоленной воде. Время – 5 минут после закипания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10400,'Очистить клубни картофеля, промыть, разрезать на части и отварить в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10400,'Сцедить воду, клубни размять при помощи толкушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10400,'В почти остывшее пюре вбить куриные яйца, всыпать муку. По желанию – молотый перец, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10400,'Раскатать легкое тесто в жгут, нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10400,'Отварить в кипящей подсоленной воде в течение трех минут. Вареники должны всплыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10401,'Перемешать творог с сахаром, яйцом, мукой, солью и ванилином. Должно получиться липкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10401,'Скатать на столе, присыпанном мукой, нетолстую колбаску, нарезать небольшими кусочками, отварить в воде с солью или сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10402,'Надрезать крестообразно помидоры, поместить в кипяток на пару минут. Переложить на лед, срезать у плодов верхушки, удалить мякоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10402,'Приготовить фарш из измельченного тунца и красного репчатого лука, нарезанного кубиками, заправить майонезом, солью, черным перцем, тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10402,'Заполнить плоды фаршем, полить помидоры фаршированные тунцом и красным луком оливковым маслом, украсить веточками петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10403,'Взбить все ингредиенты блендером, испечь на разогретой сковороде блинчики. Это самый простой и вкусный рецепт тонких блинов, начинку для них можно приготовить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10403,'Блинчики можно подать с джемом, шоколадом, вареньем или сгущенкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Отварить полоски куриного филе в смеси бульона со сливками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'В другой кастрюле отварить вермишель, время приготовления зависит от сорта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Промыть ее в дуршлаге и выложить в смесь бульона со сливками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Крахмал разболтать в холодном молоке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Помешивая постепенно влить в горячий суп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Добавить зёрна кукурузы, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10404,'Варить итальянский куриный суп с вермишелью и кукурузой до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Замесить крутое тесто на воде, разобрать несколько раз его на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Вымесить кулаком в комок, положить в миску, дать постоять часа три.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Размять в лепешку, смазать с двух сторон маслом, ещё раз переместить, раскатать в тонкую лепешку, разрезать на две части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Порезать каждую на полоски, шириной порядка 3 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Скрутить все в «улитку», полученные спирали обернуть пленкой, дать постоять полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Вытянуть из каждой жгутик, начиная от центра, сложить в две кучки, смазать маслом прикрыть и дать постоять около 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Каждый жгутик ещё раз растянуть, чтобы получились длинные «шнурки».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Полученные заготовки намотать на руки, раздвинув их примерно на полметра, растянуть, чтобы получилась длина около полутора метра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10405,'Вскипятить подсоленную воду и варить лапшу 7 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10406,'Нарезать готовое слоеное тесто на полосы, колбасу на тонкие кружки и разрезать их пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10406,'Раскатать тесто, положить на него колбасу, свернуть в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10406,'Выпекать завитушки из слоеного теста с колбасой 20-25 минут при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10407,'Отварите яйца. Остудите.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10407,'На мелкой терке натрите яйца, плавленый сырок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10407,'Выдавите чеснок через чеснокодавку, добавьте майонез и все тщательно перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10407,'Нарежьте тоненько черный хлеб и намажьте на него яично-сырную намазку. Всем приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Приготовьте продукты.','https://vkuso.ru/data/cache/data/4d/d9c5e355814aa4d_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'В миску кладем творог, яйцо, сахар, соль, сметану. Все перемешаем.','https://vkuso.ru/data/cache/data/13/d80dfe5860cf013_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Добавляем просеянную муку с разрыхлителем.','https://vkuso.ru/data/cache/data/56/8218b1091b33f56_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Замесить мягкое тесто.','https://vkuso.ru/data/cache/data/ac/11615c311b821ac_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Тесто для удобства делим на части. Раскатываем в жгутик диаметр 1 см.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Жарим на сковороде с растительным маслом на среднем огне,с двух сторон до золотистой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10408,'Украшаем сахаром или сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Из подсоленной муки замесить на чуть теплой воде тесто, обернуть его в пленку, убрать в холод на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Достать, размять, скатать в длинный жгут, порезать на куски толщиной примерно по сантиметру, каждый скатать в жгутик, смазать маслом, дать постоять примерно час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Растянуть каждый до длины около 1,5 м.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Отварить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Сложить в подходящую посуду, полив маслом и прикрыв крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Сильно разогреть в сковороде масло для приготовления соуса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Чеснок порубить, смешать с острым перцем и кориандром, добавить кинзу, чуть посолить, размешать, высыпать в раскаленное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Быстро перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Соус лаза-чанг для уйгурского лагмана по–классически убрать с плиты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'В казане разогреть масло, обжарить нашинкованный лук.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Всыпать фасоль, добавить кориандр, сельдерей, обжарить всё вместе, посолить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Мясо разрезать на куски и положить в казан, обжарить, присыпать кориандром.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Добавить к нему измельченные баклажаны с редькой и нарезанные помидоры.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Залить стаканом бульона от варки лапши, перемешать и дать закипеть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Лапшу обдать кипятком, разложить по тарелкам.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10409,'Полить соусом и положить по центру зажарку.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10410,'Приготовить из измельченных овощей нежный фарш, добавить муку, скатать шарики и переложить в пароварку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10410,'Готовить овощные  котлеты с яблоком на пару 15 минут. Это блюдо идеально подходит для поста. Котлетки не теряют форму, получаются плотными и румяными.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10411,'Свинину порежьте на кусочки и отбейте с двух сторон.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Добавить овощную нарезку, варить до мягкости картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'В это время помыть шпинат и щавель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10411,'Добавьте к мясу перец, соль, сушенный чеснок и кетчуп. Хорошо перемешайте мясо. Накройте крышкой или пищевой пленкой и отправьте в холодильник мариноваться на 2-3 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10411,'Когда мясо замаринуется приступаем к жарке. Для этого в яйца добавьте щепотку соли и немного воды, взболтайте вилкой. Подготовьте муку. Сначала мясо обмакните в муке, а затем в яйце. ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10411,'Отправьте мясо на хорошо разогретую сковороду смазанную растительным маслом. Отбивные обжарить с двух сторон до золотистого цвета на среднем огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10412,'Яйца слегка взбиваем с сахаром, добавляем ванилин, молоко и муку хорошо размешиваем венчиком и ставим на медленный огонь, беспрерывно помешивая доводим до кипения и держим на огне до достижения нужной густоты. Для верности крем можно пропустить через сито во избежания маленьких комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10412,'Даем крему остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10412,'Форму застилаем пергаментной бумагой, печенье обмакиваем в молоке и выкладываем в форму, смазываем густо кремом, затем снова печенье, крем и так несколько слоев.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10412,'Смазываем бока тортика, верх и украшаем на свое усмотрение, это могут быть орехи, изюм, тертый шоколад, у меня шоколадные кукурузные шарики. Даем тортику настоятся около 15 мин.','https://vkuso.ru/data/cache/data/08/07441cb21df6d08_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10413,'Поставить кастрюлю с водой на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10413,'Творог растереть с солью, сахарным песком, крахмалом при помощи вилки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10413,'Ввести заранее просеянную муку, замесить тесто. Масса должна получиться нежной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10413,'Скатать небольшие шарики, отварить в кипящей подсоленной воде в течение двух минут после всплытия.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Небольшие грибы с плотно прилегающими шляпками промыть, отрезать ножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Продукт переложить в миску, полить бальзамическим уксусом и приправить размятым чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Добавить оливковое масло и соевый соус. Всыпать прованские травы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Оставить грибы для пропитывания на 15 минут, два раза перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Переложить продукт в форму для запекания, перелить маринад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10414,'Поставить закуску в духовой шкаф на полчаса, температура приготовления – 190 градусов. В процессе приготовления несколько раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10415,'Грибы промыть, аккуратно вырезать ножки при помощи острого, тонкого ножа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10415,'Выложить шляпки в форму для запекания отверстиями вверх. Добавить по кусочку сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10415,'Натереть сыр, перемешать с классическим майонезом, добавить рубленый или размятый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10415,'Нафаршировать смесью шляпки. Время запекания – от 17 до 20 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10416,'Осторожно удалить ножки из шампиньонов, шляпки переложить в форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10416,'Добавить в каждую по кусочку сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10416,'Приготовить начинку из обжаренного репчатого лука и нарезанных грибных ножек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10416,'По вкусу и желанию заправить чесноком, сливками, зеленью, солью, молотым перцем. Массу потушить в течение нескольких минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10416,'Начинить шляпки, посыпать тертым сыром. Запекать в духовом шкафу при температуре от 180 до 200 градусов. Время – 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10417,'Крупные грибы промыть, осторожно срезать ножки, перегородки. Шляпка должна остаться целой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10417,'Ножки покрошить, перемешать с тертым сыром, сливками, мягким сливочным маслом и чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10417,'Нафаршировать шляпки, сверху посыпать еще одной порцией сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10417,'Каждый гриб обернуть тонко нарезанным беконом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10417,'Переложить заготовки в форму, поставить в духовой шкаф на 20 минут. Температура приготовления – от 180 до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10418,'Включить разогревать духовку (180 градусов). Смешать вилкой муку, соль, сахар без комков. Взбить желтки с маслом, добавить цедру лимона, в конце влить сок лимона. Всыпать небольшими порциями муку, подливая постепенно молоко, перемешать все до однородного  состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Черешки щавеля и шпината мелко порубить,',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Листья нашинковать на полоски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Засыпать зелень к овощам в кастрюлю, проварить ещё 5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10418,'Отдельно взбить белки, добавить их в тесто. Переложить тесто в форму для кекса. Взять большую низкую кастрюлю, налить воды, поставить форму. Поставить водяную баню с кексом в духовку, выпекать кекс-пудинг с лимонным соком около 45 минут. Слегка охладить, перед подачей посыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10419,'Шампиньоны среднего размера хорошо вымыть, поместить в пакет с паприкой, солью, чесноком и классическим майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10419,'Упаковку потрясти, чтобы пряности распределились равномерно. Оставить для пропитывания на 80 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10419,'Деревянные шпажки заранее залить кипятком на 15 минут, в мокром виде они не потрескаются в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10419,'Грибы нанизать на шпажки, выложить на застеленный фольгой противень, печь до готовности в течение получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10420,'Вырезать из шампиньонов ножки. Шляпки переложить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10420,'В каждый гриб добавить измельченный чеснок, тертый «Российский» сыр, майонез, специи. По желанию майонез можно заменить подсоленной сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10420,'На шляпки выложить по отрезанной ножке, грибы завернуть в листочки фольги, каждый – по отдельности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10420,'Время запекания – от 40 до 45 минут, температура – средняя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Шампиньоны промыть, острым ножом вырезать ножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Круглую форму смазать растительным маслом, выложит шляпки вплотную друг к другу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Промыть куриное филе, отварить до готовности с лавровым листом, остудить в бульоне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Мясо вынуть и порубить, обжарить с репчатым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Массу посолить, поперчить, добавить измельченный укроп и сметану. Прогреть в течение двух минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10421,'Наполнить теплой массой шляпки. Посыпать тертым «Голландским» сыром. Время запекания – 25 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Картофель очистить, порубить кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Репчатый лук нарезать полукольцами, шампиньоны – крупными кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Выложить продукты в горшочек в такой последовательности: картофель, лук, грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Приготовить смесь из жирных сливок, соли, перца и мускатного ореха. Залить грибы с картошкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Время запекания – 45 минут, температура – от 200 до 210 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10422,'Насыпать сверху тертый сыр, прогревать еще семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10423,'Замочить в стакане кипяченой воды, наполненном на 3/4 водой,  желатин. Смешать творог с сахарной пудрой и сметаной, добавить растворенный на водяной бане желатин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10423,'Разделить полученную смесь на три части, одну подкрасить в разовый цвет, в другую добавить какао. Вылить посередине в форму (разъемную) 4 ст. ложки светлой массы, на нее столько же розовой, а сверху массу с какао, повторить слои несколько раз, убрать на холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10423,'Достать разноцветный творожный десерт из формы, нарезать на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10424,'Шампиньоны промыть, очистить, положить в глубокую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10424,'Перемешать подсолнечное масло с солью, перцем, классическим соевым соусом и хмели-сунели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10424,'Залить смесью грибы, оставить на два часа в прохладном месте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10424,'Насадить грибы на шпажки, разложить на решетке в духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10424,'Выставить режим «Гриль», время – от 20 до 25 минут, температура – от 190 до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Подготовить все овощи, лук нашинковать, морковь крупно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Влить в мультиварку масло, включить режим «Выпечка», всыпать лук с морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Обжаривать до прозрачности лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Залить в мультиварку бульон, добавить кусочки картофеля, варить до его готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Добавить в борщ порезанную зелень, щавель и кусочки мяса, посолить, положить пряности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Варить борщ с щавелем и свининой в мультиварке в режиме «Подогрев» примерно четверть часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10425,'Разлить зеленый борщ по тарелкам, положить в каждую по ложке хорошей сметаны и яйцо, разрезанное пополам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10426,'Сварить из кореньев овощной бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10426,'Процедить, а дальше варить как обычно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10426,'В постный зеленый борщ с сельдереем добавлять яйца не принято.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'Оставить борщ с щавелем и шпинатом на курином бульоне под крышкой на четверть часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10427,'При подаче посыпать порубленным укропом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10428,'Нарезать мелко ботву, корнеплоды – кубиками или соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10428,'Овощи поставить варить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10428,'После закипания проварить еще 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10428,'Всыпать ботву.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10428,'Подавать белорусский зеленый борщ «Ботвинья» тоже с вареными яйцами и сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Подготовить все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Овощи порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Разогреть хорошо в сковороде масло, обжарить чеснок с луком до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Положить морковку, готовить пару минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Добавить сладкий перец и сельдерей. Тушить 2-3 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Добавить кабачок, перемешать, тушить на малом огне около трети часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Приправить минестроне специями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Перемешать, довести в кастрюле до кипения воду, положить картофель.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Добавить содержимое сковороды, дать закипеть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Добавить горошек и дольки помидоров.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Положить в суп макароны, варить до готовности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10429,'Подавать можно сразу, присыпать в тарелках стружкой пармезана.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Влить в кастрюлю с толстым дном масло, разогреть его, обжарить мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Добавить нарезку овощей в следующем порядке: лук, морковь, картофель, кабачки, сладкий перец, измельченные помидоры, приправить специями, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Тушить на малом огне около 10 минут',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Добавить фасоль и воду (количество регулировать по своему вкусу).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Через 5 минут положить макароны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Сварить суп до готовности всех ингредиентов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Заправить чесноком, пропущенным через пресс.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10430,'Блюдо подать с тертым пармезаном.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Налить в чашу масло, прогреть на режиме «Жарка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Обжарить до прозрачности кубики лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Кабачок очистить и нарезать на кубики, положить к луку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Добавить орегано, кусочки помидора без кожицы мелко порубленные острым ножом, влить немного воды, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Порубить мелко зубчики чеснока, сельдерей порезать тонкими пластинками, высыпать в мультиварку, выставить режим «Тушение» и время 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Всыпать макароны и фасоль, посолить, поперчить, варить еще полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10431,'Минестроне разлить по тарелкам, добавь в каждую натертый пармезан и нашинкованную зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'В небольшой кастрюльке подогреть масло, заложить в него овощную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'Лук порезать кубиками, чеснок – тонкими пластинами и добавить к овощам вместе с томатной пастой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'Перемешать Итальянский Минестроне с замороженными овощами и тушить еще 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'После этого влить воду, добавить любимые специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'Как только суп закипит, положить макароны или рис, через 10 минут выключить плиту, дать блюду время настояться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10432,'Подавать блюдо с зеленью и крупной стружкой пармезана.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Фасоль замочить и отварить, для скорости можно использовать консервированные бобы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'У стручков фасоли обрезать хвостики, нарезать ее на несколько кусочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Томаты очистить от кожицы, мякоть порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Нашинковать мелко лук, измельчить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Порезать грудинку на ломтики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Обжарить грудинку и лук с добавлением масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Всыпать к ней 3 вида фасоли и помидоры, залить все водой (бульоном).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Тушить порядка 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Положить в Итальянский Минестроне с копченостями пасту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Приправить травами, посолить, варить 5 минут, снять с плиты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Смешать базилик с петрушкой и толченым чесноком.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10433,'Смесь разложить по тарелкам и залить супом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10434,'В сотейник влить пару ложек масла, прогреть его, обжарить кубики лука и пластинки чеснока, посолить, поперчить, жарить до прозрачности лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10434,'Положить томатную пасту, прогреть пару минут, добавить нашинкованную капусту, хлопья перца и тимьян, проварить 2-3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10434,'Всыпать фасоль, положить томаты, залить литром воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10434,'Томить суп Минестроне с белой фасолью и капустой минут 20 на малом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10434,'Подавать с пармезаном.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'В большую кастрюлю положить косточку, залить 3 литрами воды, варить пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Мясо обрезать, бульон процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Измельчить морковь и лук, обжарить на масле до мягкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Положить огурцы, нарезанные соломкой, готовить полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Сварить крупу до полуготовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Бульон довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Положить картофель, нарезанный брусочками, всыпать крупу, проварить около 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'В классический рассольник на говядине с перловкой добавить зажарку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'По вкусу можно влить огуречный рассол, варить 5 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Положить мясо, горошины душистого перца, посолить, добавить лавровый лист.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Перемешать, варить под крышкой около 20 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10435,'Убрать с плиты, дать настояться 30-40 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10436,'В миске взболтайте вилочкой 3 яйца с щепоткой соли и 2 ложками молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10436,'На крупной терке натрите сыр и вареную колбасу (или сосиску).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10436,'Разогрейте сковороду и смажьте ее небольшим количеством растительного масла.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10436,'В сковороду выложите 3 столовые ложки яичной массы и распределите по всей поверхности блин с помощью ложки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10436,'Поджарьте до золотистого цвета и сверните руликом, Далее опять выложите три ложки, поджарьте и опять сверните рулетиком. Рулетик будет увеличиваться как снежный ком. Омлет готов. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10437,'Грибы вымыть, очистить, промыть, нарезать крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10437,'Обжарить на сливочном масле с рубленым репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10437,'Через восемь минут от начала обжаривания всыпать муку, влить сметану, специи и соль по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10437,'Массу довести до кипения, переложить в жаропрочную форму. Посыпать тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10437,'Запечь в течение 8 минут, температура – 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10438,'Макароны отварить в подсоленной кипящей воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10438,'Натереть твердый соленый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10438,'Соединить молоко со сливочным маслом и любыми специями. Всыпать сыр, соль – по вкусу и желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10438,'Смесь прогревать на тихом огне до растворения сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10438,'Отцеженные макароны залить соусом, перемешать и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10439,'Соленый твердый сыр натереть, перемешать с сырыми яйцами, молотым белым перцем и сметаной. Посолить смесь по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10439,'Растопить на сковороде сливочное масло, добавить сырную массу, сливки, всыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10439,'Ингредиенты перемешать и прогреть на тихом огне в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10440,'Разогреть в сотейнике оливковое масло, добавить сливочное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10440,'Обжарить мелко нарезанный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10440,'Через 3-4 минуты после начала обжаривания влить жирное молоко, положить кусочки плавленого сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10440,'Массу посолить, добавить тертый твердый сыр и приправы. Прогревать до загустения на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Нарезать кусочками сливочное масло, положить в сотейник. Растопить до появления пузырьков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Всыпать просеянную муку, перемешать, чтобы не было комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Добавить измельченный чеснок, смесь прогревать и помешивать до тех пор, пока она не станет желтоватой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Огонь уменьшить, влить молоко тонкой струйкой. Продолжать взбивать до тех пор, пока смесь не закипит.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Через минуту всыпать тертый сыр, перемешать. Добавить перец и соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10441,'Соус взбить и слегка остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10442,'Филе рыбы нарезать небольшими кусочками, посолить, поперчить.','https://vkuso.ru/data/cache/data/23/5bf898b06c36523_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'В конце положить зелень, через пару минут убрать с плиты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10449,'Сыр натереть на мелкой или средней терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10442,'Картофель натереть на крупной терке, посолить и отжать от сока.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10442,'Готовые биточки выложить на бумажное полотенце, чтобы избавиться от лишнего масла, и горячими подаем к столу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'На кубики порезать сельдерей и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Чеснок порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Лук-порей нарезать поперек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Обжарить овощи в разогретом масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'В сотейник налить овощной бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Всыпать промытую крупу, варить четверть часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Добавить нут, готовить 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Положить в постный суп с перловкой и нутом овощи, мелко измельченную петрушку, приправить специями, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10443,'Варить 5 минут, снять плиты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10444,'Растопить в сотейнике сливочное масло. Всыпать просеянную муку, массу взбивать венчиком, чтобы избежать образования комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10444,'Когда соус станет светло-коричневым – влить горячее молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10444,'Добавить сыр с голубой плесенью, соль, смесь перцев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10444,'Прогревать и помешивать заправку до тех пор, пока сыр не растворится полностью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10445,'Филе минтая разморозить, отжать лишнюю воду и извлечь кости, если таковые имеются. С одной стороны филе сделать надрезы, натереть куски молотым перцем и солью, сложить кусочки друг на друга, чтобы они пропитались специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10445,'Болгарский перец, помидоры, кольраби, репчатый лук и чеснок очистить, промыть и порезать (так как нравиться). Овощи переложить в противень, добавить молотый перец и соль по вкусу, полить все оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10445,'Содержимое противня хорошо перемешать и убрать овощи запекаться до полной готовности в предварительно разогретую духовку. Как только овощи запекутся на них нужно выложить рыбное филе и полить куски соком, образовавшимся во время запекания овощей, убрать противень с рыбой и овощами в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10445,'По прошествии 3-4 минут филе перевернуть и запекать минтай с кольраби в духовке еще в районе 2-3 минут. Перед подачей на тарелку выложить небольшое количество запеченных овощей, на овощную «подушку» положить готовое рыбное филе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Сварить до готовности мясо, например, говядину (2 часа).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Мясо достать немного остудить, порезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Если бульон прозрачный, то процеживать его не надо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Дать бульону закипеть, всыпать хорошо промытую крупу, варить 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Морковь, сельдерей и лук порезать на брусочки, обжарить на масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Добавить пюре из томата, приправить специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Дать опять закипеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Раздавить прессом чеснок, положить его в суп вместе с мясом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'В суп с перловкой и сельдереем на говяжьем бульоне добавить зажарку, подсолить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10446,'Варить при еле заметном кипении около получаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10447,'Измельчить рыбное филе при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10447,'Добавить к анчоусам тертый сыр и сметану, молотый перец, лимонный сок и майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10447,'Ингредиенты перемешать, соус положить в прозрачную стеклянную емкость и закрыть крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10447,'Убрать в холодильник. Смесь должна постоять в холодильнике не менее двух часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Крупу тщательно промыть, залить на час водой, чтобы сократить время варки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Откинуть на дуршлаг, высыпать в кастрюлю, дать закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Воду слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Крупу промыть и залить еще раз, варить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Овощи измельчить и обжарить на масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Картофель порезать на кубики и высыпать к перловке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Нарезанные грибы добавить в зажарку перемешать, готовить 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Грибную зажарку переложить в перловый суп с картофелем и грибами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10448,'Добавить специи, подсолить, варить 5 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'В чистые банки положить перец, лавровый лист.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10449,'Сливочное масло нарезать и растопить в сотейнике. Добавить муку высшего качества.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10449,'Прогревать массу на огне до изменения цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10449,'Влить подогретое молоко. Соус прогревать до тех пор, пока он не загустеет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10449,'Всыпать тертый сыр, помешивать массу венчиком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10450,'Взбить с сахаром отделенные от белков желтки, добавить сметану и сливочное растопленное масло, перемешать массу с помощью миксера. Муку смешать с содой, ввести в желтковую массу и снова перемешать, после чего аккуратно ввести в тесто взбитые белки. Смазать маслом разъемную форму, переложить в нее получившееся тесто и убрать все на 40 минут в духовку, нагретую до 180-190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10450,'Клубнику помыть, удалить хвостики, сложить в миску, засыпать сахаром (хватит 2-3 ст. л.) и убрать в сторону на 30 минут (ягоды должны дать сок). Вынуть из духовки готовый бисквит и разрезать его еще на 2 коржа, каждый из которых пропитать образовавшимся клубничным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10450,'Один корж переложить на сервировочное блюдо и распределить по нему (коржу) засахаренную клубнику (большие ягоды нужно разрезать пополам). Для крема взбить до однородности сметану с сахарной пудрой и получившейся массой залить всю клубнику на первом корже.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10450,'Положить на ягоды второй корж, полить его оставшимся кремом и украсить клубникой (или так как захочется). Убрать получившийся домашний торт «Клубника» для пропитки на 1-2 часа в холодильник, затем можно подавать лакомство к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'В миске взбейте миксером, яйца, сахар, ванильный сахар. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Добавьте кефир, соду и растопленное сливочное масло, взбейте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Затем добавьте муку и взбейте тесто до однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Форму для выпекания смажьте сливочным маслом. Залейте в нее тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Яблоки помойте и очистите их от середины. Яблоки порежьте дольками. Шкурку я не снимаю, мне так больше нравится.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'На тесто выложите яблоки кожицей вверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Отправьте в духовку на 50-60 минут при температуре 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10451,'Остудите пирог и присыпьте его сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Варим рис до полуготовности, чтобы он слегка размягчился, но в тоже время похрустывал на зубах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Лук, морковь нарежем и пассируем на сковороде. Снимаем с огня и остужаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Натираем сыр. Нарезаем грудинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Яйца смешиваем с молоком. Солим, перчим, добавляем мускатный орех, прованские травы. Нарезаем петрушку. Добавляем в яичную смесь, перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Смешиваем половину сыра, горошек, грудинку, лук, морковь и рис.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10452,'Через 15 минут достаем, посыпаем оставшимся сыром и отправляем опять в духовку. Запекаем до золотистой корочки. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10453,'Растопить на сковороде кусочки сливочного масла, всыпать муку. Ингредиенты перемешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10453,'После того, как смесь изменит цвет, влить жирные сливки, довести до кипения. В массе не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10453,'Соус посолить и поперчить, всыпать тертый сыр. Прогревать до растворения сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10454,'Цельное молоко влить в любую подходящую емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10454,'Прогреть продукт до теплого состояния, всыпать сахар. Смесь помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10454,'Время приготовления – 60 минут. До кипения молоко не доводить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10455,'В миске перемешать (не взбивать) яйца с обычным и ванильным сахаром, ввести муку и тщательно все размешать, чтобы получилось однородное жидкое тесто без комков. Хорошенько смазать маргарином горячий противень и выложить на него 4-5 ч. л. теста на большом друг от друга расстоянии.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10455,'Выпекать заготовки для будущего печенья в районе 5 минут при 200 градусах, затем вынуть противень из духовки и приподнять (с противня не снимать) каждый коржик шпателем. С помощью бумажного полотенца сформировать из каждой горячей заготовки цветок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Закрыть крышку, выставить программу «Суп», и время 1 час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10455,'Для заварного крема нужно тщательно растереть до однородного состояния яичные желтки с мукой, ванилином и сахаром. Вскипятить в небольшой кастрюльке на маленьком огне молоко, дать ему слегка остыть, после чего при постоянном помешивании влить его в желтковую массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10455,'Яично-молочную массу поставить на маленький огонь и, все время помешивая, варить ее до загустения в течение 5-6 минут (крем не должен подгореть), дать массе остыть. В кастрюльку с полностью остывшим кремом добавить сливочное масло и взбить все вместе в однородную пышную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10455,'Любым удобным способом наполнить очень вкусное и нежное печенье «Каллы» приготовленным заварным кремом и выложить все изделия на большое сервировочное блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10456,'Влить в емкость воду, всыпать сахарный песок, перемешать, прогреть до растворения и изменения цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10456,'Добавить сливочное масло, нагретое цельное молоко. Прогревать массу до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10456,'Всыпать сухое молоко. Все вместе варить 3 минуты, затем остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10457,'Влить сливки  любой жирности в емкость, всыпать сахарный песок. Смесь прогреть до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10457,'Подержать сгущенку на огне десять минут, массу помешивать. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10458,'В чашу блендера всыпать сахар и сухое молоко, смесь перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10458,'Влить молоко, взбивать содержимое до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10458,'Перелить смесь в мультиварку, выставить режим «Каша» на полчаса. Температура приготовления – 90 градусов. Содержимое чаши постоянно помешивать. Продукт остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10459,'В кастрюлю влить молоко, всыпать сахар и щепотку пищевой соды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10459,'Массу перемешать, поставить на плиту и прогреть, до кипения не доводить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10459,'Перелить массу в хлебопечку, выставить режим «Джем». Запустить режим два или три раза, все зависит от мощности прибора.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'Сварить курицу, вынуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'В бульон положить промытую крупу с картофелем, порезанным брусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'Лук мелко нашинковать, обжарить до прозрачности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'Добавить нарезанный сельдерей и морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'Готовить до мягкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'В конце добавить томатный соус, нагревать еще минут 5.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10460,'Зажарку отправить в куриный суп с сельдереем и перловкой, варить до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10461,'В средней или большой миске смешать майонез с лимонным соком, молотым черным перцем, солью и специями (при желании). ромытой филе курицы нарезать на маленькие кусочки (каждый размером около 1,5 см), сложить мясо в подготовленный майонезный маринад и промариновать курицу в течение 30-40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10461,'Все овощи очистить от кожуры и промыть: картофель порезать кружочками, морковь крупно натереть, лук порезать полукольцами. Смазать форму маслом и выложить на ее дно замариновавшееся куриное филе, поверх которого нужно разложить подготовленный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10461,'По луковому слою распределить тертую морковь, которую затем «спрятать» под картофельными кружочками. Последний слой (картофельный) посолить, промазать майонезом и посыпать предварительно натертым на крупной терке сыром. Запекать куриное филе под шубой из овощей в духовке при 180 градусах на протяжении 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Поставить варить перловку в небольшом количестве воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Обжарить овощи на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Порезать филе рыбы на кусочки, сварить до готовности и вынуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Добавить к почти готовой крупе брусочки картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Влить рыбный бульон и через 5-7 минут добавить зажарку и рыбу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10462,'Приправить перловый суп на рыбном бульоне сухой зеленью и специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Порезать лук на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Разогреть в мультиварке на программе «Жарка» масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Всыпать лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Обжарить до исчезновение цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Положить кусочки мяса, перемешать, дать им подрумяниться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Положить кубики моркови, перемешать, жарить 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Добавить картофель, нарезанный небольшими кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'Всыпать перловку, залить все водой (бульоном), подсолить, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10463,'За 5 минут до готовности в перловый суп из говядины в мультиварке добавить лавровый лист.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Мясистые помидоры поместить на одну-две минуты в кипяток, очистить от шкурки и порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Остальные овощи тоже нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Чеснок раздавить прессом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Мясо порезать тонкими пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Поставить на огонь чугунок, хорошо прогреть его.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Налить масло, нагреть, обжарить лук с мясом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Добавить редьку, фасоль, морковь, помидоры и чеснок, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Залить мясо с овощами смесью бульона с томатным соусом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Готовить уйгурский лагман с зеленой фасолью  примерно четверть часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Сварить лапшу, смешать ее с маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10464,'Выложить на большое блюдо, залить овощной подливкой и уложить сверху куски мяса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Подготовить и порезать на куски мясо, обжарить его в сильно разогретом масле с добавлением лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Помидоры порезать, перемешать с томатной пастой, добавить мелко порубленный или раздавленный прессом чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Перемешать, дать постоять около 15 минут, добавить все в казан, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Жарить до полного испарения сока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Порезать редьку с морковью и перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Фасоль и зеленые стрелки чеснока порубить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Высыпать смесь в мясо, посолить, поперчить, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Тушить минут 7-8.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Влить воду перемешать тушить еще минут 30.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Добавить зиру с кориандром, измельченную зелень петрушки, прогреть 5 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Чеснок обжарить в кунжутном масле, посолить, влить уксус, перемешать соус.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Разложить отваренную лапшу с подливой и приправой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10465,'Подавать лагман с говядиной и дунганским перцем горячим.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Подготовить овощи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Нарезать на куски мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Капусту нашинковать на полоски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Хорошо разогреть масло в сковороде, обжарить мясо поперчить, подсолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Добавить лук и зажарить все вместе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Измельчить чеснок и помидоры, переложить к мясу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Томить на малом огне 3-5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Положить остальные овощи, обжарить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Добавить в сковороду немного воды, она должна лишь слегка покрыть овощи с мясом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Тушить лагман из говядины с капустой почти до испарения жидкости.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Добавить зелёный лук, кориандр, зиру, подсолить, перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Отваренную заранее лапшу с маслом уложить на блюдо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10466,'Залить подливой с мясом и сразу подать к столу.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Предварительно кости бараньи обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Отдельно обжарить нарезанное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Объединить мясо и кости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Положить порезанные помидоры, овощи, залить водой, которая должна лишь чуть-чуть покрывать продукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Дать лагману из баранины по рецепту Сталика Ханкишиева закипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Смесь в казане посолить и добавить специи, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'На большое блюдо положить лапшу, смазанную маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10467,'Залить овощной подливой, вокруг разложить мясо на кости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Лук нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Нарезать на квадратики капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Порубить перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Порезать мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Помидоры очистить от шкурки и тоже нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Сильно разогреть в казане масло, обжарить мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Добавить в уйгурский лагман с говядиной без лапши помидоры с луком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Прогреть 2-3 минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Добавить к мясу джандо (стручковая фасоль), капусту и сельдерей, перемешать сдобрить специями.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10468,'Обжарить всё вместе минут 5-7.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Сварить из курицы со специями и луком бульон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Процедить его.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Морковь нашинковать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Картофель порезать брусочками или кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Щавель сложить в стопку, отрезать стебельки мелко их нашинковать, а листья разрезать вдоль на 2-3 полосы и тоже нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'В бульоне отварить почти до готовности картофель и морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'В кислой среде клубни просто до готовности не сварятся.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Добавить щавель и зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Дать зеленому борщу из курицы с щавелем и яйцом прокипеть минут 5.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Огонь выключить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'Закрыть кастрюлю крышкой, дать постоять четверть часа.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10469,'При подаче в каждую тарелку положить по ложке хорошей сметаны и разрезанное пополам яйцо.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10470,'Килограмм мяса (окорок, шейная часть или грудинка) залить 2,5 л воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10470,'Сварить наваристый бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10470,'Пока он варится подготовить и нарезать овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10470,'Готовый бульон процедить, но если он достаточно прозрачный, то можно это и не делать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10470,'Дальше готовить зелёный зеленый борщ на говяжьем бульоне с сельдереем можно также, как и по классическому рецепту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'Разрезаем грибы небольшими кубиками. Наливаем немного воды в сковороду и отправляем в неё грибы тушиться на огне под закрытой крышкой на 10-15 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'Тем временем разрезаем кубиками вареную картошку, соленые огурцы, морковь и яйца. В идеале все резать под размер горошины, но в нашей семье есть личности, которые не очень любят вареную морковь, поэтому мы разрезаем ее мелко. Все разрезанные ингредиенты отправляем в большую миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'По истечению 10-15 мин. перемешиваем грибы, которые дали большое количество жидкости и значительно уменьшились в размерах. Добавляем туда соль или соевый соус и оставляем жариться до полного испарения жидкости. Крышкой больше не накрываем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'Продолжаем разрезать ингредиенты. На очереди у нас зеленый и репчатый лук. Режем всё мелко, чтобы салат не был горьким. Далее отправляем в общую миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'После того как из грибов выпарится вся жидкость, добавляем туда ст. ложку сметаны и хорошенько перемешаем. Выключаем плиту и даем грибам остынуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'Зеленый горошек и полностью остывшие грибы отправляем в общую миску, солим, добавляем 2 ст.л. сметаны и 2 ст.л. майонеза и хорошенько перемешиваем все ингредиенты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10471,'Наш Оливьешка с грибами без колбасы ГОТОВ! Приятного аппетита.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'У тушки курицы срезать весь жир, удалить кожу, убрать крылышки, срезать мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Порезать его кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Прокрутить на мясорубке вместе с чесноком и луком, подсолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Взбить подсоленные белки до состояния устойчивых пиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Перемешать с фаршем, добавить паприку, укроп, мускатный орех, петрушку, йогурт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Если фарш будет жидким, то добавить пару столовых ложек панировочных сухарей, хорошо размешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Решетку пароварки и руки смазать маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Сформовать шарики, придавить с 2-х сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10472,'Низкокалорийные куриные котлеты с зеленью готовить около получаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10473,'Курицу отварить, порезать на кубики вместе с крабовыми палочками, яблоками и ананасом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10473,'Добавить кукурузу и порезанный салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10473,'Все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10473,'Для заправки салата Тропикаль с ананасами перемешать 1:2 кетчуп и майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Очистить холодные креветки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Помидоры порезать не очень тонкими кружками (примерно по 1 см).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'В одну тарелку насыпать муку, перемешать с солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Во вторую – панировочные сухари.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'В третью – разбить яйцо, добавить молоко и разболтать вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Кружок помидора обвалять в муке, потом в обмакнуть в яйцо, а затем в сухари.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Обжарить с двух сторон в нагретом масле, разложить на бумажном полотенце.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'Обжарить в сливочном масле креветки с чесноком, кумином, кайенским перцем и паприкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10474,'На широкое блюдо выложить помидоры, на них положить порцию подсоленного пюре из авакадо с чесноком и соком лайма, прикрыть парой креветок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'В чашку миксера вбить пару яиц, взбить на средней скорости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Влить чуть теплое молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Всыпать чайную ложку сахара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Добавить 50 г растопленного масла, подсолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Сквозь небольшое ситечко добавить стакан муки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Перемешать до исчезновения комочков, дать постоять около трети часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Для начинки обжарить кубики лука, добавить фарш, чеснок, раздавленный прессом, обжаривать до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Соединить с пюре, подсолить, поперчить, перемешать, дать остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Нажарить блинчиков, смазать каждый начинкой и свернуть в трубочку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Сложить «улиткой» в форму для выпекания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Для заливки перемешать пару яиц, 4 ст. л. сметаны, 1 ст. л. молока, чуть подсолить, всыпать пару ст. л. муки, хорошо перемешать и вылить на блинчики.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10475,'Выпекать блинчатый пирог с фаршем в духовке около получаса при температуре 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Для теста разболтать пару яиц, добавить майонез со сметаной, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Всыпать муку, перемешать еще раз до исчезновения комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Отставить в сторону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Помидоры порезать кольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Подготовленный фарш, обжарить до полной готовности, подсолить, поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Перемешать с соусом «барбекю», протушить пару минут все вместе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Смазать сковороду маслом, разложить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Нанести сеточку из кетчупа, уложить помидоры, чуть присолить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Ровным слоем выложить мясную смесь, далее – сырную стружку, присыпать орегано.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Сковороду закрыть крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'Готовить пиццу с соусом барбекю на сковороде на малом огне.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10476,'В момент когда сыр расплавится, нежная и ароматная пицца будет готова.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10477,'В теплое молоко добавляем сахар, дрожжи, соль, растопленное сл. масло перемешиваем, добавляем постепенно просеянную муку, замешиваем тесто. Тесто должно получиться мягким, не забитым мукой, но и не липнуть к к рукам. Сразу же раскатываем в жгут и нарезаем на одинаковые кусочки, каждый кусочек формируем в шарик.','https://vkuso.ru/data/cache/data/be/4a2f4d7452760be_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10477,'Шарик раскатываем, в середину кладем ложку начинки, у меня творог с сахаром и ванилью, формируем пирожок.','https://vkuso.ru/data/cache/data/2e/2efaf478b9cbb2e_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10477,'Складываем на смазанный маслом противень и сверху пирожки смазываем яйцом с добавлением ложки молока или просто желтком. Отправляем в разогретую духовку на 20-25 мин печем на среднем огне.','https://vkuso.ru/data/cache/data/01/c06305072822101_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10477,'Пирожки получаются безумно вкусными, тесто как будто слоится! Это тот вариант когда теста мало, а начинки много! Приятного аппетита!','https://vkuso.ru/data/cache/data/8e/a8d18ffb6d6d48e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10478,'Подготовьте заливку. Для этого взболтайте вилкой яйца с солью, затем добавьте молоко и воду, хорошенько перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10478,'Сыр натрите на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10478,'Фарш посолите и поперчите по вкусу, хорошо перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10478,'Противень смажьте растительным маслом. На дно выложите макароны, затем фарш. Залейте все заливкой и посыпьте натертым сыром.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10478,'Форму для запекания накройте фольгой или крышкой и отправьте в духовку при температуре 200 градусов на 40 минут. Затем откройте крышку или снимите фольгу и запекайте еще 15 минут до образование золотистой корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Порезать курицу на куски, срезать жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Сельдерей нарезать кубиками, порей – полукольцами, лук – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Все сложить в одну кастрюлю, приправить специями, перемешать, залить водой, влить 3 ст. л. масла, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Варить под крышкой, нагрев уменьшить до среднего, когда вода закипит.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'За время варки приготовить кус-кус: засыпать в миску, залить подсоленной водой, добавить ст. л. масла, оставить набухать (около 7 минут).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Потом переместить в пароварку, осторожно сделать углубления пальцем, готовить около получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Подготовить и очистить морковь, редьку, кабачки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Остальные овощи четвертинками (пополам, а потом каждую на части), кусочки должны быть примерно одного размера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Первой отправить в кастрюлю морковь, далее, через минут 5 – редька, потом, через 5 минут – кабачки и тыкву, варить под крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Кус-кус пересыпать в таз, размешать до исчезновения всех кусочков, даже самых маленьких.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Добавить сливочное масло, размешать еще раз.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Когда он остынет перетереть с небольшим усилием между ладонями примерно 5 минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Вернуть кус-кус в пароварку.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'На большое широкое блюдо выложить кус-кус с курицей, овощами и специями.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Кус-кус уложить по центру горкой, вокруг него овощи, а сверху куски курицы.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10479,'Отдельно подать бульон, разлив его по пиалам.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Картофель сварить в мундире.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Лук нашинковать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Перец нарезать на полоски и испечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Оливки разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Очистить картофель, порезать шайбочками, разложить на плоском блюде, чуть присолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Прикрыть колечками лука, сверху положить полоски перца и кусочки тунца, оливки и каперсы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10480,'Украсить картофельный салат с запеченным перцем и тунцом четвертинками яиц, подсолить и чуть поперчить, полить маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10481,'Нарежем мелко лук и грибы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10481,'Отправляем лук на сковороду с растительным маслом и жарим до размягчения, добавляем грибы тушим 3 минуты под крышкой. ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10481,'Добавляем воду, накрываем крышкой тушим еще 5 минут на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10481,'Снимаем крышку тушим до выпаривания жидкости. Выложим грибы в миску, добавляем сметану, хорошо перемешиваем. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10482,'Лук и грибы - режем мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10482,'Обжариваем лук на растительном масле, добавляем сливочное масло, выкладываем грибы, тушим постоянно помешивая, солим и перчим. Остужаем',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10482,'Куриное филе режем мелким кубиком. Сыр - трем на крупной терке, добавить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10482,'Собираем салат. Все смешать. Добавить по желанию майонез. Украсить - черносливом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'В миску насыпьте стакан и третью часть стакана муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Масло предварительно заморозьте. Натрите на крупной терке, постоянно обмакивая масло в муку. Перетрите руками масло с мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Затем добавьте соль, ванильный сахар и разрыхлитель, перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Добавьте творог и хорошо вымесите. Тесто не должно липнуть к рукам. При необходимости добавьте муку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Поделите тесто на несколько частей. Раскатайте круг и с помощью формочки сделайте небольшие кружочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Разогрейте сковороду с растительным маслом и выложите кружечки из творога.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Обжарьте с двух сторон до золотистого цвета. Выложите на бумажное полотенце.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10483,'Когда вкуснятина из творога немного остынет, посыпьте их сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'Измельчить лук, морковь натереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'В кастрюлю с толстым днем налейте растительное масло. Добавьте лук, немного поджарьте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'Затем добавьте морковь. Овощи поджарьте и добавьте рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'Рис с овощами необходимо пожарить 5 минут, затем налить воду и добавить соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'Варите рис под прикрытой крышкой до готовности, пока не выкипит вся вода.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10484,'Затем перемешайте рис, накрой те крышкой, выключите огонь и дайте постоять 10 минут. Гарнир готов! Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'Перемешать сливки и половину масла, нагреть до кипения, всыпать 3 стакана муки, хорошо вымесить, дать заварному тесту остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'В большой посуде залить дрожжи теплым молоком, всыпать стакан сахара, перемешать, дать постоять треть часа, дождаться шапки пены.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'Взбить  700  сахара и желтки 15 штук, добавить две ложки воды, перемешать с заварным тестом и опарой, всыпать около 7 стаканов муки, вымесить тесто, дать постоять около часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Влить в сотейник треть необходимого по рецепту масла, прогреть его.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'Смешать остатки сахара и яичных желтков, всыпать изюм либо цукаты, подсолить, добавить ванилин и мягкое масло, хорошо вымешать, объединить с тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'Подсыпать оставшуюся муку, порциями влить масло, вымешать тесто подходящей консистенции, поместить в тепло на пару часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10485,'Подготовить формы для выпечки заварного кулича на сливках, заполнить на 1/3 тестом, дать ему подняться, отправить в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10486,'Довести до кипения молоко, заварить в нем стакан муки, тщательно размешать венчиком, чтобы исчезли комочки, дать остыть до 35 градусов, всыпать пару ложек сахара с дрожжами, дать подойти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10486,'В чашу блендера положить творог и желтки, взбить, добавить сахар, размешать до однородности, ввести мягкое масло, еще раз взбить, всыпать1 ч.л. соли, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10486,'Объединить с опарой, размешать всыпать изюм, подсыпать немного муки, вымесить тесто, дать ему хорошо подняться, разделить на кусочки, разложить по формочкам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10486,'Выпекать заварной кулич с творогом порядка 35 минут, поставить остывать, оформить верх глазурью и украсить по своему вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10487,'Размягчить сливочное масло, взбить с сахарным песком добела с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10487,'Вбить сырые куриные яйца по одному, затем порциями всыпать муку, молотую корицу, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10487,'Добавить сливы без косточек, разломанные на половинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10487,'Готовое тесто поместить в смазанную форму и поставить в горячую духовку на 45 – 50 минут. Температура приготовления – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Для приготовления блюда перемешать сырые яйца с обычным и ванильным сахаром, добавить газированную воду, масло, смесь перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Всыпать в емкость муку, добавить основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Погасить пищевую соду, лимонным соком или уксусом, влить в тесто, еще раз хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Смазать маслом форму для выпекания, дно застелить пергаментной бумагой, переложить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Поверх выложить половинки абрикосов без косточек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Для приготовления штрейзеля перемешать руками в крошку сливочное масло, муку, сахар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10488,'Посыпать абрикосовую начинку, печь в течение 40 – 50 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Промыть и обсушить инжир, нарезать кусочками небольшого размера, залить вином. Дать постоять для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Куриные грудки разрезать вдоль на две или три части в зависимости от величины, немного отбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Обжарить филе на сковороде с растительным маслом до готовности, с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Грудки вынуть, на сковороду положить инжир с вином, потушить до испарения жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Смазать растительным маслом жаропрочную форму, выложить мясо. Соль и молотый перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Посыпать блюдо сушеным базиликом, выложить инжир сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10489,'Натереть на крупной терке сыр, посыпать блюдо, поставить в духовку на несколько минут для расплавления сыра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Порезать мясо на кусочки, кальмар – кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Креветки очистить, головы и панцири отварить пару-тройку минут, процедить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Хорошо вымыть мидии, сварить в белом вине под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Снять сразу и разделить на половинки, как только они раскроются.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'У помидоров удалить шкурку и порезать кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Зелень порубить мелко вместе с чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Лимон порезать, перец болгарский – кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Обжарить, слегка присолив, на разогретой сковороде омары, дать остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Обжарить мясо.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Когда будет почти готово положить перец, далее чеснок, протушить минут 5.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Добавить помидоры, тушить еще пару-тройку минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Влить в глубокую сковороду 50 г масла, прогреть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Положить овощи с мясом и рис, влить бульон от креветок.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Положить в паэлью с мясом, морепродуктами и овощами замороженный горошек.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Когда рис будет еще слегка жестким, положить кальмары и креветки с паприкой.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10490,'Огонь погасить, дать под крышкой постоять 10 минут и можно приступать к еде.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10491,'Яйца с сахаром взбиваем в легкую пенку, добавляем растопленное сливочное масло, какао, разрыхлитель, размешиваем и постепенно вводим муку и хорошо размешиваем.','https://vkuso.ru/data/cache/data/5f/be8492848d69e5f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10491,'Добавляем вишни. можно использовать любые, размешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10491,'Готовим крем:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10491,'Делаем глазурь:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10491,'Когда пирог остынет смазываем полностью шоколадным кремом, а сверху наносим лимонную глазурь тонкой струей используя кондитерский шприц.','https://vkuso.ru/data/cache/data/da/8a1b2f85d7131da_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Крупу хорошо вымыть, желательно проточной водой, для более быстрой варки перловку можно предварительно замочить часа на 3, затем отварить минут 20.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Морковь очистить, нашинковать тонкими брусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Обжарить в хорошо прогретом масле, удобнее это делать в казане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Добавить кусочки томатов, перемешать прогреть 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Добавить картофель, порезанный средними кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Приправить острым перцем, всыпать петрушку, положить лавровый лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Влить в казан 1,5 литра воды, подсолить, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Варить треть часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Всыпать готовую перловку, проварить перловый суп с овощами без мяса пару-тройку минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10492,'Закрыть крышкой, снять с плиты, дать постоять перед подачей.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Помидоры крупно порезать, сложить в блендер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'За неимением такового, просто порубить ножом, но предварительно очистить от шкурки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Морковь со свеклой крупно натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Лук прокрутить на мясорубке или мелко порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'В подходящую по объему кастрюлю влить половину от нормы масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Добавить 1/3 уксуса с водой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Поместить овощи, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Прогреть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Когда начнет кипеть, сделать нагрев минимальным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Тушить под крышкой около четверти часа.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Положить в борщевую заправку помидоры.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Влить остатки уксуса и воды.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Готовить треть часа.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Подсолить, положить горошки душистого перца, лавровый лист.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Подсластить, подсолить перемешать, готовить 10 минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Заполнить осторожно банки булькающей смесью.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10493,'Завинтить крышками, перевернуть, накрыть одеялом, дать остыть.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Подготовить овощи, измельчить удобным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Сладкий перец порезать на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Влить в кастрюлю (взять с толстым дном) 1/2 необходимого объема масла, прогреть его.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Положить свеклу, залить ее 1/2 уксуса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Перемешать, готовить минут 5.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Всыпать морковь, тушить еще около 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Добавить лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Через 3-4 минуты – болгарский перец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Содержимое кастрюли перемешать, проварить 5-6 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Положить томатную пасту, подсолить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Добавить сахар и остатки масла, еще раз размешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Заправка для борща со сладким перцем и томатной пастой должна еле кипеть минут 25.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Разложить ее по банкам, укупорить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Прикрыть чем-нибудь теплым, дать постепенно остыть.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10494,'Убрать в темное место для хранения.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Помидоры разрезать на 4 части, сложить в чашу блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Измельчить до получения пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Перец нарезать соломкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Свеклу крупно натереть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'У горького перца убрать семена и мелко порезать (желательно в перчатках).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Вылить пюре в лук.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Добавить горький перец со свеклой, подсолить, добавить сахар.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Залить овощи остатком масла, тушить смесь, иногда помешивая, порядка часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Положить в заправку полоски сладкого перца.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Тушить на малом огне еще около 20 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'За пару-тройку минут до окончания влить к овощам уксус, размешать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10495,'Заполнить горячей заправкой банки, укупорить их, поставить на крышку, прикрыть одеялом, дать остыть примерно сутки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Подготавливаем тесто. Для этого нам понадобится глубокая миска, в которую добавляем яйцо, сливочное масло, сметану, муку и соль по вкусу.','https://vkuso.ru/data/cache/data/19/8ca8fe406356c19_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Все ингредиенты хорошенько разминаем руками в течении 10 мин. Готовое тесто не должно прилипать к рукам, если же оно липнет, то добавляем немного муки и снова его мнём.','https://vkuso.ru/data/cache/data/2e/c9b45c736d5c62e_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'В итоге получается "колобочек", который отправляем в холодильник на 30 мин.','https://vkuso.ru/data/cache/data/a9/fa1fac8985480a9_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Подготавливаем начинку. Помидор и репчатый лук разрезаем на небольшие колечки, болгарский перец режем на тонкие дольки, а сыры натираем на крупной тёрке.','https://vkuso.ru/data/cache/data/f5/ca788ea0cc59bf5_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Подготавливаем соус. В отдельной миске перемешиваем майонез с кетчупом. Для остроты добавляем тертый на мелкой тёрке чеснок.','https://vkuso.ru/data/cache/data/46/93e0f5dd2025b46_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Вынимаем тесто из холодильника и тонко раскатываем его скалкой по форме противня.','https://vkuso.ru/data/cache/data/f2/a232114c25a44f2_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Смазываем противень сливочным маслом и перекладываем туда тесто, которое равномерно намазываем соусом.','https://vkuso.ru/data/cache/data/b5/7cd40b66a2047b5_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Далее раскладываем начинку. На соус насыпаем колбасный сыр, затем аккуратно кладем нарезанные помидор, болгарский перед и лук. В конце нашу пиццу обильно посыпаем твердым сыром.','https://vkuso.ru/data/cache/data/29/330ef05e30a3c29_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'В заранее разогретую духовку (190 градусов) отправляем пиццу на 20 мин.','https://vkuso.ru/data/cache/data/e2/ab510002a6be3e2_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'После выключения духовки не спешим сразу вынимать пиццу, оставляем ее внутри еще минут на 10.','https://vkuso.ru/data/cache/data/65/5cf6e5f8b5c4f65_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10496,'Вынимаем готовую пиццу и зовём всех близких к столу. Приятного аппетита!','https://vkuso.ru/data/cache/data/0b/526c1ce32bdad0b_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'Корень имбиря почистить и нарезать мелкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'Лимон вымыть и срезать с него кожицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'В кастрюле большого размера перемешать цедру, сахарный сок и имбирь, залить кипятком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'В стакане теплой воды растворить дрожжи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'В остывающую воду в кастрюле влить дрожжи и лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10497,'Все ингредиенты перемешать, дать напитку настояться, процедить через марлю и поставить в прохладу на два дня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10498,'Залить дрожжи слегка подогретыми сливками, всыпать половину сахара, размешать, всыпать пару-тройку ложек муки, оставить опару «созреть».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10498,'Довести до кипения воду, всыпать около 2/3 стакана муки, хорошо перемешать, остудить, перемешать со сливочной смесью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10498,'В полученную опару добавить оставшиеся ингредиенты в следующем порядке: яйца, сахар (оставшийся), уже жидкое масло, соль, любые цукаты, коньяк, цедру с остатками муки, можно еще и изюм.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10498,'Дать постоять тесту где-нибудь в тепле, чтобы объем стал в 3 раза больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10498,'Разложить тесто в формочки, смазанные маслом, прикрыть тканью, дать еще раз подойти, выпекать пасхальный кулич с цедрой, коньяком и цукатами до готовности, проверять зубочисткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Растопить на слабом огне масло, снять с плиты, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Изюм вымыть и ошпарить кипятком, залить его водой, выдержать четверть часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Подогреть в кастрюльке пол стакана сливок, всыпать две ложки сахара, добавить дрожжи, полторы ст.л. муки, перемешать, дать постоять в тепле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Желтки засыпать сахаром, хорошо взбить, или тщательно растереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Объединить опару и масляную смесь, влить чуть подогретые сливки, добавить мускат и ваниль, обсушенный изюм, измельченные орехи и муку, вымесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Накрыть посуду с тестом тканью, поместить в тёплое место, чтобы оно увеличилось в объеме не менее чем в 2 раза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Подготовить формы, включить для разогрева до 160 градусов духовку, обмять тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Заполнить формы тестом, прикрыть тканью, дать постоять треть часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Внизу духовки поставить миску с водой, а в середину поместить формочки, четверть часа выпекать пасхальный кулич на сливках с миндалем и изюмом при заданной температуре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10499,'Далее прикрыть фольгой верх формочек, увеличить нагрев до 190 градусов. Время приготовления зависит от объёма форм, готовность проверять спичкой или зубочисткой. Достать куличи, слегка остудить, вынуть из формы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10500,'Репчатый лук нарезать мелкими кубиками, залить горячей водой для удаления горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10500,'Нарезать кубиками ветчину, яблоки, отваренные яйца и консервированный ананас.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10500,'На крупной терке натереть сельдерей, добавить лук и консервированную кукурузу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10500,'Тертый сельдерей и яблоки можно сбрызнуть лимонным соком, чтобы продукты не потемнели.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10500,'Соль и перец – по вкусу, заправить салат майонезом и поставить в холодильник на несколько часов для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10501,'Куриное филе нарезать кубиками среднего размера, добавить сладкую молотую паприку, чеснок, соль и перец, любые сушеные травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10501,'В смесь всыпать быстрорастворимый желатин, ингредиенты хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10501,'Массу выложить в рукав для запекания, придать изделию форму рулета. Время приготовления – 50 минут, температура – 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10501,'Готовый рулет остудить, поставить в холодильник на пять – семь часов, из формы не вынимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10502,'В миску насыпьте муку, разрыхлитель, соль, ванильный сахар, корицу и сахар. Перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10502,'Постепенно вливайте молоко и размешивайте венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10502,'Банан разомните вилкой и добавьте в тесто, перемешайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10502,'Разогрейте сковороду, смажьте растительным маслом, добавьте 3-4 ст.л. теста и распределите по всей поверхности сковороды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10502,'Обжарьте с двух сторон до золотистого цвета. Банановые оладьи готовы!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Перемешать крахмал,  муку, 1 стакан сахарного песка, сырые яйца, 2 ст.л. с горкой сметаны, пищевую соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Нарезать кусочками сливочное масло, добавить в смесь и хорошо перемешать руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Из готового теста сформовать шарики меньше грецкого ореха, выложить их на противень, застеленный пергаментом и смазанный рафинированным растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Поместить в духовку, печь до золотистого цвета при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Приготовить крем из оставшейся сметаны с сахарным песком, добавить загуститель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Выложить на плоскую тарелку остывшие шарики в один слой, намазать кремом из сметаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Затем выложить следующий слой, отступив от края, снова покрыть кремом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10503,'Сформовать торт в виде горки, посыпать кокосовой стружкой, поставить в холодильник для пропитывания на 12 часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Перемешать сухие ингредиенты: горчицу, разрыхлитель, муку, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Добавить мягкое сливочное масло, массу перетереть руками в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Сыр натереть на мелкой терке, добавить в основную смесь, влить молоко, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Присыпать стол мукой, раскатать тесто в тонкую лепешку, вырезать кружки стаканом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Противень застелить пергаментом и смазать маслом, выложить лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10504,'Каждое изделие смазать молоком и присыпать еще одной порцией тертого сыра. Время выпекания – от 10 до 15 минут, в зависимости от возможностей духового шкафа, температура – 220 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'Прогреть до 40 градусов смесь сливок и молока на малом огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'Растопить масло, дать ему остыть, замочить изюм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'Масло влить в чашу хлебопечки вместе с прогретой смесью из сливок и молока, добавить ваниль и сахар, сквозь сито всыпать муку, добавить дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'Крышку печки закрыть, установить режим «Сладкий хлеб», вес –900 граммов, цвет корочки – «Средний», запустить программу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'После сигнала положить в тесто изюм с цукатами, закрыть крышку, дождаться окончания программы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10505,'Остудить кулич в чаше, выложить быстрый рецепт кулича на сливках в хлебопечке на решётку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Смешать сахар с дрожжами и подогретым сливками, всыпать стакан муки (порциями), перемешать до исчезновения комочков, поставить в тепло на 25 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Досыпать еще 250 г муки, когда над дрожжами появится «шапка» из пены, убрать на час в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Залить водой изюм, дать постоять, обсушить его, цукаты измельчить на маленькие кусочки,  порубить миндаль, с апельсина, через мелкую терку, снять цедру.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Сложить в миску мягкое масло, сахар с желтками, растереть ложкой до однородного состояния, вылить массу в опару, всыпать цукаты, миндаль с изюмом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Для тонкого аромата влить коньяк, добавить ваниль с апельсиновой цедрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'В смесь досыпать остальную муку, вымесить около 10 минут, дать постоять полтора часа в тазике, придвинув к батарее.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Тесто обмять, разложить в формы, прикрыть льняным полотенцем, дать постоять около часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10506,'Поместить формы в духовку выпекать кулич на сливках и желтках с миндалем, цукатами и изюмом 25-30 минут (средняя форма), а большая – 40 минут. Достать, дать полежать на решетке, вынуть из формы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10507,'Скумбрию без головы почистить и промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10507,'Приготовить рассол из воды с солью, сахарным песком, луковой шелухой, лавровым листом, черным чаем, душистым перцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10507,'Смесь поставить на огонь и довести до кипения, прогревать пять минут, остудить, затем процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10507,'Залить рыбу на четыре дня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Произвольно нарезать овощи, как обычно, для борща.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Лук – на кубики, морковь – тонкой соломкой, перец сладкий – тоже соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Помидоры без шкурки мелко покрошить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Свеклу крупно натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Капусту нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'Чеснок порубить острым ножом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10508,'На разогретом в кастрюле масле обжарить лук около 5 минут.',NULL,7);
