INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10512,'Завинтить крышками, хранить в прохладе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Говяжью ногу зачистить ножом под струей воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Просмолить над газом и опять зачистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Разрубить, промыть от мелких костей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Сложить части в кастрюлю с водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Держать около 4 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Далее проварить ногу при чуть заметном кипении около 8-10 часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Мясо должно очень легко отделяться от костей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Положить в кастрюлю очищенные луковицы, приправить лавровым листом.',NULL,8);
