INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'За это время из чеснока, пропущенного через пресс, уксуса (винного) и соли приготовить соус.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10513,'Готовый армянский хаш из говяжьей ноги разложить по тарелкам, добавив соус.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10514,'В миску разобьем яйцо, смешаем со сгущенным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10514,'Нарежем банан на кружочки (можно банан смять вилкой в пюре). Добавляем к яично-сгущённой смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10514,'Разогреем сковороду с растительным или сливочным маслом. Выкладываем на сковороду лаваш, затем заливаем в центр лаваша начинку. Сворачиваем в конверт. Жарим с двух сторон до золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10514,'Готовый конверт поливаем сгущенным молоком и украшаем бананом. Подаем горячим.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10515,'Муку, разрыхлитель, соль - смешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10515,'Соединяем творог, сахар, ванильный сахар и растительное масло перебить блендером. Добавляем изюм и курагу - перемешать.',NULL,2);
