INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10515,'Из теста сделать шарики. Берем шарик и опускаем в сбитое яйцо, а затем в дробленые орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10515,'Выкладываем на противень застеленный пергаментной бумагой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Вымыть тщательно мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Сделать на нем прорези, дойдя до кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Сложить его в кастрюлю, влить воду, поставить на огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Дать закипеть и слить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Процедуру повторить несколько раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Завернуть в марлю бутончики гвоздики, лавровый лист и горошки перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Погрузить ее в бульон, при желании (и наличии) можно положить и корешки петрушки.',NULL,7);
