INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10516,'Разложить по глубоким тарелкам, залить бульоном, приправить толченым чесноком с зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Обработать, просмолить и зачистить ножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Порубить их.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Сложить в кастрюлю, влить воду, дать сутки вымокнуть, меняя за это время четырежды воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Ножки вынуть, промыть, поставить на огонь, положив лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Дать закипеть, тщательно снять с поверхности пену, нагрев сделать меньше, пену убирать регулярно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Варить не менее 5 часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Вынуть ножки, дать остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Срезать мясо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Жидкость процедить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Сложить обратно в кастрюлю свинину.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Влить прозрачный бульон.',NULL,11);
