INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'Кипение должно быть еле заметно.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10517,'К блюду подать крупно натертую редьку, порубленный базилик с чесноком и мелко натертый корень петрушки.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10518,'Ножку опалить над газом или на открытом огне.',NULL,1);
