INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10519,'Смешать бульон и кусочки мяса, дать блюду закипеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10519,'Положить порубленный чеснок, проварить 5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10519,'Снять с плиты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (10520,'Рульку зачистить, срезать часть жира.',NULL,1);
